INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Alussa loi Jumala taivaan ja maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Ja maa oli autio ja tyhjä, ja pimeys oli syvyyden päällä, ja Jumalan Henki liikkui vetten päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Ja Jumala sanoi: tulkoon valkeus, ja valkeus tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Ja Jumala näki valkeuden hyväksi. Niin Jumala eroitti valkeuden pimeydestä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Ja Jumala kutsui valkeuden päiväksi, ja pimeyden kutsui hän yöksi. Ja tuli ehtoosta ja aamusta ensimäinen päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Ja Jumala sanoi: tulkoon vahvuus vetten vaiheelle, eroittamaan vesiä vesistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Ja Jumala teki vahvuuden, ja eroitti vedet, jotka ovat vahvuuden alla, niistä vesistä, jotka ovat vahvuuden päällä: ja tapahtui niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Ja Jumala kutsui vahvuuden taivaaksi. Ja tuli ehtoosta ja aamusta toinen päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Ja Jumala sanoi: kokoontukoon vedet taivaan alla erinomaiseen paikkaan, niin että kuiva näkyy. Ja tapahtui niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Ja Jumala kutsui kuivan maaksi, ja vetten kokoukset hän kutsui mereksi. Ja Jumala näki sen hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Ja Jumala sanoi: vihoittakoon maa, ja kasvakoon ruohon, jossa siemen on, ja hedelmälliset puut, jotka hedelmän kantavat lajinsa jälkeen, jossa sen siemen on maan päällä. Ja tapahtui niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Ja maa vihoitti ja kasvoi ruohon, jossa siemen oli lajinsa jälkeen, ja hedelmälliset puut, joiden siemen oli itsessänsä lajinsa jälkeen. Ja Jumala näki sen hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Ja tuli ehtoosta ja aamusta kolmas päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Ja Jumala sanoi: tulkoon valkeudet taivaan vahvuuteen, eroittamaan päivää ja yötä: ja olkoon merkeiksi, ja ajoiksi, ja päiviksi ja vuosiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Ja olkoon valkeudeksi taivaan vahvuudessa, paistamaan maan päälle. Ja tapahtui niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Ja Jumala teki kaksi suurta valkeutta: suuremman valkeuden päivää hallitsemaan, ja vähemmän valkeuden yötä hallitsemaan, ja tähdet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Ja Jumala pani ne taivaan vahvuuteen, paistamaan maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Ja hallitsemaan päivää ja yötä, ja eroittamaan valkeutta ja pimeyttä. Ja Jumala näki sen hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Ja tuli ehtoosta ja aamusta neljäs päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Ja Jumala sanoi: kuohuttakoon vedet yltäkyllä liikkuvaisia eläimiä, ja linnut lentäköön maan päällä taivaan avaruudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Ja Jumala loi suuret valaskalat, ja kaikkinaiset liikkuvaiset eläimet, jotka vedet kuohuttivat yltäkyllä kunkin lajinsa jälkeen, ja kaikkinaiset siivilliset linnut, lajinsa jälkeen. Ja Jumala näki sen hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Ja Jumala siunasi heitä, ja sanoi: olkaat hedelmälliset ja lisääntykäät, ja täyttäkäät meren vedet, ja linnut lisääntyköön veden päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Ja tuli ehtoosta ja aamusta viides päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Ja Jumala sanoi: tuottakoon maa eläimet lajinsa jälkeen, karjan, madot ja pedot maalle lajinsa jälkeen. Ja tapahtui niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Ja jumala teki pedot maalle lajinsa jälkeen, ja karjan lajinsa jälkeen, ja kaikkinaiset matelevaiset maalla lajinsa jälkeen. Ja Jumala näki sen hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Ja Jumala sanoi: tehkäämme ihminen meidän kuvaksemme, meidän muotomme jälkeen: ja he vallitkaan kalat meressä, ja taivaan linnut, ja karjan ja koko maan, ja kaikki, jotka maalla matelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Ja Jumala loi ihmisen omaksi kuvaksensa, Jumalan kuvaksi hän sen loi: mieheksi ja vaimoksi loi hän heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Ja Jumala siunasi heitä, ja Jumala sanoi heille: kasvakaat ja lisääntykäät ja täyttäkäät maata, ja tehkäät se teillenne alamaiseksi; ja vallitkaat kalat meressä, ja taivaan linnut, ja kaikki eläimet, jotka maalla liikkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Ja Jumala sanoi: katso, minä annoin teille kaikkinaiset ruohot, joissa siemen on koko maan päällä, ja kaikkinaiset hedelmälliset puut, ja puut, joissa siemen on, teille ruaksi');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Ja kaikille eläimille maan päällä, ja kaikille taivaan linnuille, ja kaikille, jotka matelevat maan päällä, joissa elävä henki on, kaikkinaiset viheriäiset ruohot syötäväksi. Ja tapahtui niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Ja Jumala katsoi kaikkia, kuin hän tehnyt oli, ja katso, ne olivat sangen hyvät. Ja tuli ehtoosta ja aamusta se kuudes päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Ja niin taivas ja maa päätettiin, ja kaikki heidän joukkonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Ja Jumala oli päättänyt seitsemänteen päivään (asti) työnsä, kuin hän tehnyt oli, ja lepäsi seitsemäntenä päivänä kaikista teoistansa, kuin hän tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Ja Jumala siunasi seitsemännen päivän ja pyhitti sen; että hän lepäsi hänessä kaikista teoistansa, jotka Jumala loi ja (täydellisesti) teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Ja näin on taivas ja maa tullut, koska he luotiin, sillä ajalla jolla Herra Jumala teki maan ja taivaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Ja kaikkinaiset pensaat kedolla, jotka ei ennen olleet maan päällä, ja kaikkinaiset ruohot kedolla, jotka ei ennen kasvaneet. Sillä ei Herra Jumala antanut vielä sataa maan päälle, eikä ollut ihmistä, joka maata viljeli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Vaan sumu nousi maasta, ja kasti kaiken maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Ja Herra Jumala teki ihmisen, tomun maasta, ja puhalsi hänen sieraimiinsa elävän hengen: ja tuli ihminen niin eläväksi sieluksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Ja Herra Jumala istutti Paradisin Edenissä itään päin, ja pani siihen ihmisen, jonka hän tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Ja Herra Jumala kasvatti maasta kaikkinaiset puut, ihanaiset nähdä ja hyvät syödä, ja elämän puun keskelle Paradisia, niin myös hyvän ja pahan tiedon puun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Ja Edenistä kävi virta kastamaan Paradisia, ja jakoi sieltä itsensä neljäksi päävirraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Ensimäinen kutsutaan Pison: se juoksee koko Hevilan maan ympärinsä, ja siellä on kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Ja sen maan kulta on kallis, ja siellä myös löytään Bedellion, ja kallis kivi Oniks.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Toinen virta kutsutaan Gihon: se juoksee koko Etiopian ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Kolmas virta kutsutaan Hiddekel, ja juoksee Assyrian editse. Ja neljäs virta on Phrat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Ja Herra Jumala otti ihmisen, ja pani Edenissä Paradisiin, viljelemään ja varjelemaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Ja Herra Jumala käski ihmistä, ja sanoi: syö vapaasti kaikkinaisista puista Paradisissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Mutta hyvän ja pahan tiedon puusta älä syö: sillä jona päivänä sinä siitä syöt, pitää sinun kuolemalla kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Ja Herra Jumala sanoi: ei ole hyvä ihmisen yksinänsä olla, minä teen hänelle avun, joka hänen tykönänsä oleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Koska Herra Jumala oli tehnyt maasta kaikkinaiset eläimet kedolle, ja kaikkinaiset taivaan linnut, toi hän ne Adamin eteen, että hän näkis, kuinka hän ne nimittäis: sillä niinkuin Adam kaikkinaiset eläimet nimitti, niin ne kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Ja Adam antoi kullekin karjalle, ja taivaan linnuille, ja eläimille maan päällä heidän nimensä. Mutta Adamille ei löytty apua, joka hänen tykönänsä olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Ja Herra jumala pani raskaan unen Adamiin, ja kuin hän nukkui, otti hän yhden hänen kylkiluistansa, ja täytti sen paikan lihalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Ja Herra Jumala rakensi vaimon siitä kylkiluusta, jonka hän Adamista otti, ja toi sen hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Niin sanoi Adam: tämä on nyt luu minun luistani, ja liha minun lihastani: se pitää kutsuttaman miehiseksi, sillä hän on otettu miehestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Sentähden pitää miehen luopuman isästänsä ja äidistänsä, ja vaimoonsa sidottu oleman, ja tulevat yhdeksi lihaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Ja he olivat molemmat alasti, Adam ja hänen emäntänsä, ja ei hävenneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Ja kärme oli kavalin kaikkia eläimiä maan päällä, jotka Herra Jumala tehnyt oli, ja se sanoi vaimolle: sanoiko Jumala, älkäät syökö kaikkinaisista puista Paradisissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Niin vaimo sanoi kärmeelle: me syömme niiden puiden hedelmistä, jotka ovat Paradisissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Mutta sen puun hedelmästä, joka on keskellä Paradisia, on Jumala sanonut: älkäät syökö siitä, ja älkäät ruvetko siihen, ettette kuolis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Niin kärme sanoi vaimolle: ei suinkaan pidä teidän kuolemalla kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Vaan Jumala tietää, että jona päivänä te syötte siitä, aukenevat teidän silmänne, ja te tulette niinkuin Jumala, tietämään hyvän ja pahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Ja vaimo näki siitä puusta olevan hyvän syödä, ja että se oli ihana nähdä ja suloinen puu antamaan ymmärryksen: ja otti sen hedelmästä ja söi, ja antoi miehellensä siitä, ja hän söi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Silloin aukenivat molempain heidän silmänsä, ja äkkäsivät, että he olivat alasti; ja sitoivat yhteen fikunalehtiä, ja tekivät heillensä peitteitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Ja he kuulivat Herran Jumalan äänen, joka käyskenteli Paradisissa, kuin päivä viileäksi tuli. Ja Adam lymyi emäntinensä Herran Jumalan kasvoin edestä puiden sekaan Paradisissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Ja Herra Jumala kutsui Adamin, ja sanoi hänelle: Kussas olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Ja hän sanoi: minä kuulin sinun äänes Paradisissa, ja pelkäsin: sillä minä olen alasti, ja sen tähden minä lymyin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Ja hän sanoi: kuka sinulle ilmoitti, ettäs alasti olet? Etkös syönyt siitä puusta, josta minä sinua haastoin syömästä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Niin sanoi Adam: vaimo, jonkas annoit minulle, antoi minulle siitä puusta, ja minä söin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Silloin sanoi Herra Jumala vaimolle: miksis sen teit? Ja vaimo sanoi: kärme petti minut, ja minä söin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Ja Herra Jumala sanoi kärmeelle: ettäs tämän teit, kirottu ole sinä kaikesta karjasta, ja kaikista eläimistä maalla: sinun pitää käymän vatsallas, ja syömän maata kaiken elinaikas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Ja minä panen vainon sinun ja vaimon välille, ja sinun siemenes ja hänen siemenensä välille; sen pitää rikki polkemaan sinun pääs, ja sinä olet pistävä häntä kantapäähän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Ja vaimolle sanoi hän: Minä saatan sinulle paljon tuskaa, koskas raskaaksi tulet: sinun pitää synnyttämän lapsia kivulla, ja sinun tahtos pitää miehes alle annettu oleman, ja hänen pitää vallitseman sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Ja Adamille sanoi hän: ettäs kuulit emäntäs ääntä, ja söit puusta, josta minä kielsin sinua sanoen: ei sinun pidä siitä syömän: kirottu olkoon maa sinun tähtes; surulla pitää sinun elättämän itses hänestä kaiken elinaikas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Orjantappuroita ja ohdakkeita pitää hänen kasvaman, ja sinun pitää maan ruohoja syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Sinun otsas hiessä pitää sinun syömän leipää, siihen asti kuin sinä maaksi jällensä tulet, ettäs siitä otettu olet: sillä sinä olet maa, ja maaksi pitää sinun jällensä tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Ja Adam kutsui emäntänsä nimen Heva, että hän on kaikkein elävitten äiti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Ja Herra Jumala teki Adamille ja hänen emännällensä nahoista hameet, ja puetti heidän yllensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Ja Herra Jumala sanoi: katso, Adam on ollut niin kuin yksi meistä, tietäen hyvän ja pahan; mutta nyt ettei hän ojentaisi kättänsä, ja ottaisi myös elämän puusta, söisi ja eläisi ijankaikkisesti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Niin Herra Jumala johdatti hänen ulos Edenin Paradisista maata viljelemään, josta hän otettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Ja ajoi Adamin ulos, ja pani idän puolelle Edenin Paradisia Kerubimin paljaalla, lyöväisellä miekalla elämän puun tietä vartioitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Ja Adam tunsi emäntänsä Hevan, ja hän tuli raskaaksi, ja synnytti Kainin, ja sanoi: minulla on mies Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Ja taas hän synnytti hänen veljensä Habelin. Ja Habel tuli lampuriksi, mutta Kain peltomieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Ja tapahtui muutamain päiväin perästä, että Kain uhrasi Herralle lahjan maan hedelmistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Ja Habel myös uhrasi laumansa esikoisista, ja heidän lihavuudestansa. Ja Herra katsoi (leppyisesti) Habelin ja hänen uhrinsa puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Mutta Kainin ja hänen uhrinsa puoleen ei hän (leppyisesti) katsonut: silloin Kain vihastui sangen kovin, ja hänen hahmonsa muuttui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Niin Herra sanoi Kainille: miksis olet vihainen? Ja miksi hahmos muuttuu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Eikö se niin ole? jos hyvin teet niin syntis anteeksi annetaan; ja jolles hyvin tee, niin synti väijyy oven edessä, ja hänen himonsa on sinun tykös, vaan hallitse sinä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Ja Kain puhui veljensä Habelin kanssa. Ja tapahtui heidän kedolla ollessansa, että Kain karkasi veljensä Habelin päälle, ja tappoi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Niin Herra sanoi Kainille: kussa on Habel sinun veljes? hän vastasi: en minä tiedä: olenko minä veljeni vartia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Ja hän sanoi: mitäs tehnyt olet? veljes veren ääni huutaa minun tyköni maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Ja nyt kirottu ole sinä: (kirottu) maan päältä, joka avasi suunsa ottamaan veljes verta sinun kädestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Koskas maata viljelet, niin ei pidä sen tästedes sinulle väkeänsä antaman; kulkian ja pakenevaisen pitää sinun oleman maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Ja Kain sanoi Herralle: minun rangaistukseni on suurempi, kuin että se on kannettava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Katsos, sinä ajat minun pois tänäpäivänä maalta, ja minun pitää sinun kasvois edestä lymymän ja tulen kulkiaksi ja pakenevaiseksi maan päällä. Ja niin minun käy, kuka ikänänsä minun löytää, se tappaa minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Mutta Herra sanoi hänelle: Sentähden, kuka ikänänsä Kainin tappaa, se pitää seitsemän kertaisesti kostettaman. Ja Herra pani merkin Kainiin, ettei kenkään häntä tappaisi, joka hänen löytäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Ja niin Kain läksi Herran kasvoin edestä, ja asui Nodin maalla, itään päin Edenistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Ja Kain tunsi emäntänsä, joka tuli raskaaksi, ja synnytti Hanokin. Ja hän rakensi kaupungin, jonka hän kutsui poikansa nimellä Hanok.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Mutta Hanok siitti Iradin. Irad siitti Mahujaelin. Mahujael siitti Metusaelin. Metusael siitti Lamekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Mutta Lamek otti kaksi emäntää, yhden nimi oli Ada, ja toisen nimi Zilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ja Ada synnytti Jabalin, joka oli niiden isä, jotka majoissa asuivat, ja karjaa kasvattivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Ja hänen veljensä nimi oli Jubal, josta kantelein ja huiluin soittajat tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Zilla myös synnytti TubalKainin, joka oli taitava kaikkinaisissa vaski-ja rautatöissä, ja Tubalkainin sisar oli Naema.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Ja Lamek sanoi emännillensä, Adalle ja Zillalle: te Lamekin emännät, kuulkaat minun ääntäni, ja vaari ottakaat siitä kuin minä sanon: minä olen miehen tappanut minulleni haavaksi, ja nuorukaisen minulleni sinimarjaksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Kain kostetaan seitsemän kertaisesti, mutta Lamek seitsemän ja seitsemänkymmenen kertaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Ja Adam taas tunsi emäntänsä, ja hän synnytti pojan, ja kutsui hänen nimensä Set, sanoen: Jumala on minulle toisen siemenen antanut Habelin edestä, jonka Kain tappoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Ja Set myös siitti pojan, ja kutsui hänen Enos. Silloin ruvettiin saarnaamaan Herran nimestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Tämä on ihmisen sukukunnan kirja, siihen aikaan, koska Jumala loi ihmisen, ja teki hänen Jumalan muotoiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Mieheksi ja vaimoksi loi hän heidät ja siunasi heitä, ja kutsui heidän nimensä ihminen, sinä päivänä jona he luotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Ja Adam oli sadan ja kolmenkymmenen ajastajan vanha, ja siitti pojan, joka hänen kuvansa kaltainen oli, ja kutsui hänen nimensä Set.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Ja eli sitte kahdeksansataa ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Ja koko hänen ikänsä oli yhdeksänsataa ja kolmekymmentä ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Set oli sadan ja viiden ajastajan vanha, ja siitti Enoksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Ja eli sitte kahdeksansataa ja seitsemän ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Ja koko hänen ikänsä oli yhdeksänsataa ja kaksitoistakymmentä ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Enos oli yhdeksänkymmenen ajastajan vanha, ja siitti Kenanin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Ja eli sitte kahdeksansataa ja viisitoistakymmentä ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Ja koko hänen ikänsä oli yhdeksänsataa ja viisi ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenan oli seitsemänkymmenen ajastajan vanha, ja siitti Mahalaleelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Ja eli sitte kahdeksansataa ja neljäkymmentä ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Ja koko hänen ikänsä oli yhdeksänsataa ja kymmenen ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Mahalaleel oli viiden ajastajan seitsemättäkymmentä vanha, ja siitti Jaredin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Ja eli sitte kahdeksansataa ja kolmekymmentä ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Ja koko hänen ikänsä oli kahdeksansataa yhdeksänkymmentä ja viisi ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Jared oli sadan ja kahdenseitsemättäkymmentä ajastajan vanha, ja siitti Henokin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Ja eli sitte kahdeksansataa ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Ja koko hänen ikänsä oli yhdeksänsataa ja kaksiseitsemättäkymmentä ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Henok oli viidenseitsemättäkymmentä ajastajan vanha, ja siitti Metusalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Ja sitte kuin hän oli Metusalan siittänyt, pysyi hän jumalisessa elämässä kolmesataa ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Ja koko hänen ikänsä oli kolmesataa ja viisiseitsemättäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Ja hän eli jumalisesti: ja ei enää ollut; sillä Jumala otti hänen pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Metusalah oli sadan ja seitsemän ajastajan yhdeksättäkymmentä vanha, ja siitti Lamekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Ja eli sitte seitsemänsataa ja kaksiyhdeksättäkymmentä ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Ja koko hänen ikänsä oli yhdeksänsataa ja yhdeksänseitsemättäkymmentä ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Lamek oli sadan ja kahden ajastajan yhdeksättäkymmentä vanha, ja siitti pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Ja kutsui hänen nimensä Noa, sanoen: tämä on lohduttava meitä meidän vaivassamme ja töissämme maan päällä, jonka Herra kironnut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Sitte eli hän viisisataa yhdeksänkymmentä ja viisi ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Ja koko hänen ikänsä oli seitsemänsataa ja seitsemänkahdeksattakymmentä ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Noa oli viidensadan ajastajan vanha, ja siitti Semin, Hamin ja Japhetin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Ja tapahtui, koska ihmiset rupesivat lisääntymään maan päällä, ja siittivät tyttäriä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Niin Jumalan pojat näkivät ihmisten tyttäret kauniiksi, ja ottivat emänniksensä kaikesta kuin he valitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Silloin sanoi Herra: ei minun henkeni pidä nuhteleman ihmistä (sanan kautta) ijankaikkisesti, sillä hän on liha; sentähden olkoon hänellä aikaa, sata ja kaksikymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Siihen aikaan olivat sankarit maan päällä: ja myös sitte, kuin Jumalan pojat makasivat ihmisten tytärten kanssa, ja he olivat siittäneet heille (lapsia): nämä olivat valtiaat, ne muinen kuuluisat miehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Mutta Herra näki ihmisen pahuuden suureksi maan päällä; ja kaikki hänen sydämensä aivoitus ja ajatus oli ainoastansa paha joka aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Ja Herra katui ihmisen tehneensä maan päälle, ja tuli murheelliseksi sydämessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Ja Herra sanoi: Minä tahdon ihmisen, jonka minä loin, hukuttaa maan päältä, hamasta ihmisestä niin karjaan asti, matoihin ja ja taivaan lintuihin asti; sillä minä kadun, että minä niitä tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mutta Noa löysi armon Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Tämä on Noan sukukunta: Noa oli hurskas ja vakaa mies ajallansa, ja eli jumalisesti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Ja siitti kolme poikaa, Semin, Hamin ja Japhetin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Mutta maa oli turmeltu Jumalan kasvoin edessä, ja täynnänsä väkivaltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Silloin katsahti Jumala maan päälle, ja katso, se oli turmeltu: sillä kaikki liha oli turmellut tiensä maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Ja Jumala sanoi Noalle: kaiken lihan loppu on minun eteeni tullut: sillä maa on heistä täynnänsä väkivaltaa, ja katso, minä hukutan heitä ynnä maan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Tee sinulles arkki hongasta, ja tee sisälle olinsijat, ja tervaa se sisältä ja ulkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Ja tee häntä näin: Kolmesataa kyynärää pitää oleman arkin pituuden, viisikymmentä kyynärää hänen leveytensä ja kolmekymmentä kyynärää korkeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Arkin akkunan sinun pitää tekemän, ja kyynärällä päättämän sen ylhäältä: Ja arkin oven pitää sinun paneman sivuun. Ja hänellä pitää oleman kolme pohjaa, yksi alinna, toinen keskellä ja kolmas ylinnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Ja minä, katso, minä annan tulla vedenpaisumuksen maan päälle hukuttamaan kaikkea lihaa, jossa elävä henki on taivaan alla, ja kaikki, mitä maan päällä on, pitää hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mutta sinun kanssas minä minun liittoni teen, ja sinun pitää arkkiin sisälle menemän, sinun ja sinun poikas, ja sinun emäntäs, ja poikais emännät sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Ja sinun pitää saattaman arkkiin kaikkinaiset eläimet kaikesta lihasta kaksittain, koiraksen ja naaraksen, jäämään elämään kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Linnuista lajistansa, karjasta lajistansa, kaikkinaisista madoista maan päällä lajistansa. Kaikista näistä pitää kaksittain sinun tykös käymän, jäämän elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Ja sinun pitää ottaman tykös kaikkinaista ruokaa, jota syödään, ja kokooman sinun tykös, sinulle ja heille elatukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Ja Noa teki sen: kaikki mitä Jumala hänen käski, niin hän teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Ja Herra sanoi Noalle: mene sinä ja koko sinun huonees arkkiin: sillä sinun minä olen nähnyt hurskaaksi minun edessäni tällä ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Kaikista puhtaista eläimistä ota tykös seitsemän ja seitsemän, koiras ja naaras, mutta saastaisista eläimistä kaksin, koiras ja naaras.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Niin myös taivaan linnuista seitsemän ja seitsemän, koiras ja naaras, että siemen jäis elämään koko maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Sillä vielä seitsemän päivän perästä annan minä sataa maan päälle neljäkymmentä päivää ja neljäkymmentä yötä, ja hukutan maan päältä kaikki elävät luontokappaleet, jotka minä tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Ja Noa teki kaiken sen jälkeen kuin Herra hänelle käski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Ja Noa oli kuudensadan ajastajan vanha, koska vedenpaisumus tuli maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Ja Noa meni arkkiin poikinensa, emäntinensä, ja hänen poikainsa emännät hänen kanssansa, vedenpaisumisen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Puhtaista eläimistä ja saastaisista, ja linnuista ja kaikista, kuin matelevat maan päällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Menivät Noan tykö arkkiin kaksittain, koiras ja naaras, niinkuin Herra Noalle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Ja tapahtui, koska seitsemän päivää kuluneet olivat, tuli vedenpaisumus maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Kuudennella sadalla ajastajalla Noan ijästä, toisella kuukaudella, seitsemäntenätoista kymmenentenä päivänä kuusta, sinä päivänä kuohuivat kaikki syvyyden lähteet, ja taivaan akkunat aukenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Ja maan päälle satoi neljäkymmentä päivää ja neljäkymmentä yötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Juuri sinä päivänä meni Noa ja Sem, ja Ham, ja Japhet, Noan pojat, ja Noan emäntä, ja kolme hänen poikainsa emäntää hänen kanssansa arkkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'He ja kaikki pedot lajistansa, ja kaikki matelevaiset, jotka matelevat maan päällä, lajistansa, ja kaikki linnut lajistansa, kaikki lentäväiset, joilla siivet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Ja menivät Noan tykö arkkiin kaksittain kaikesta lihasta, jossa elävä henki oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Je ne olivat koirakset ja naarakset kaikkinaisesta lihasta, ja menivät sisälle niinkuin Jumala hänelle käskenyt oli. Ja Herra sulki hänen jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Silloin tuli vedenpaisumus neljäkymmentä päivää maan päälle, ja vedet paisuivat, ja nostivat arkin ylös, ja veivät korkialle maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Niin vedet saivat vallan, ja paisuivat sangen suuresti maan päälle, niin että arkki oli vesiajolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Ja vedet saivat sangen suuren vallan, ja enänivät niin suuresti maan päälle, että kaikki korkiat vuoret koko taivaan alla peitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Viisitoistakymmentä kyynärää korkialla olivat vedet vuorten päällä, jotka he peittivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Silloin hukkui kaikki liha, joka maan päällä matelee, linnut, karja, pedot, ja kaikki, jotka maan päällä liikkuvat, ja kaikki ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Ja kaikki, joilla elävä henki oli kuivan maan päällä, ne kuolivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Niin hukutettiin kaikki ne, kuin maan päällä olivat, ihmisestä niin karjaan asti, ja matoihin, ja taivaan lintuihin asti, kaikki hukutettiin maan päältä, ainoastansa Noa jäi, ja ne jotka hänen kanssansa olivat arkissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Ja vedet seisoivat valtiasna maan päällä sata ja viisikymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Silloin Jumala muisti Noaa ja kaikkia eläviä, ja kaikkea karjaa, kuin hänen kanssansa olivat arkissa, ja Jumala nosti tuulen maan päälle, ja vedet seisahtivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Ja syvyyden lähteet tukittiin, ja taivaan akkunat, ja sateet taivaasta asetettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Ja vedet maan päältä enemmin ja enemmin juoksivat pois, ja vähenivät sadan ja viidenkymmenen päivän perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Ja seitsemäntenätoistakymmenentenä päivänä, seitsemännessä kuukaudessa jäi arkki Araratin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Mutta vedet juoksivat pois, ja vähenivät hamaan kymmenenteen kuukauteen asti. Ensimäisnä päivänä kymmenentenä kuukautena näkyivät vuorten kukkulat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Neljänkymmenen päivän perästä avasi Noa arkin akkunan, jonka hän tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Ja antoi kaarneen lentää ulos, joka lensi kahtiapäin, siihen asti kuin vedet maan päältä kuivuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Sitte lähetti hän kyhkyisen tyköänsä, koettelemaan, jos vedet olisivat juosseet pois maan päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Koska ei kyhkyinen löytänyt kussa hän sai jalkansa levätä, palasi hän hänen tykönsä arkkiin: sillä vedet olivat vielä koko maan päällä, niin hän ojensi kätensä, otti hänen ja toi arkkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Ja odotti vielä toiset seitsemän päivää, ja antoi taas kyhkyisen lentää arkista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Se palasi hänen tykönsä, ehtoopuolella, ja katso, hän toi suussansa öljypuun lehden, jonka hän murtanut oli. Niin Noa ymmärsi vedet maan päältä juosseeksi pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Mutta hän odotti vielä seitsemän päivää, ja antoi kyhkyisen lentää ulos, joka ei enää palannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Ja kuudennella sadalla ja ensimäisellä ajastajalla (Noan ijästä) ensimäisenä päivänä ensimäisessä kuukaudessa, kuivuivat vedet maan päältä. Niin avasi Noa arkin katon, ja näki, ja katso, maa oli kuivunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Niin maa tuli peräti kuivaksi seitsemäntenäkolmattakymmenentenä päivänä toisessa kuukaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Niin Jumala puhui Noalle sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Lähde arkista, sinä ja sinun emäntäs, ja sinun poikas, ja sinun poikais emännät sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Kaikkinaiset eläimet, jotka sinun tykönäs ovat, kaikkinaisesta lihasta, sekä linnuista että karjasta, ja kaikista matelevaisista maan päällä, johdata ne ulos kanssas: ja kävelköön ne maan päällä, ja olkoon hedelmälliset ja lisääntyköön maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Niin Noa meni ulos poikinensa, ja emäntinensä, ja poikainsa emännät hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Kaikkinaiset eläimet, kaikkinaiset matelevaiset, kaikkinaiset linnut, ja kaikki kuin maalla matelevat: läksivät arkista, jokainen kaltaisensa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Ja Noa rakensi Herralle alttarin: ja otti kaikkinaisesta puhtaasta karjasta, ja kaikkinaisista puhtaista linnuista, ja uhrasi polttouhria alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Ja Herra haisti lepytyshajun, ja Herra sanoi sydämessänsä: en minä silleen enää maata kiroo ihmisen tähden: vaikka ihmisen sydämen aivoitus on paha hamasta lapsuudesta: ja en minä silleen enää lyö kaikkia kuin elävät, niinkuin minä tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Niin kauvan kuin maa seisoo, ei pidä kylväminen ja niittäminen, vilu ja helle, suvi ja talvi, päivä ja yö lakkaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Ja Jumala siunasi Noan ja hänen poikansa, ja sanoi heille: olkaat hedelmälliset, lisääntykäät ja täyttäkäät maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Ja teidän pelkonne ja hämmästyksenne olkoon kaikissa eläimissä maan päällä, ja kaikissa linnuissa taivaan alla; ja kaikissa, jotka maalla matelevat, ja kaikissa kaloissa meressä: ne ovat teidän käsiinne annetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Kaikki, jotka liikkuvat ja elävät, olkoon teille ruaksi: niinkuin viheriäisen ruohon, olen minä kaikki teille antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Ainoastansa älkäät syökö lihaa, jossa vielä on veri itsessänsä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Ja totisesti minä tahdon vaatia teidän ruumiinne veren, kaikilta eläimiltä minä sen tahdon vaatia: ja ihmisen kädestä, ja myös itsekunkin hänen veljensä kädestä tahdon minä vaatia ihmisen hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Se kuin ihmisen veren vuodattaa, hänen verensä pitää ihmisen kautta vuodatettaman: sillä Jumala on ihmisen tehnyt kuvaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Olkaat siis hedelmälliset, lisääntykäät ja enentäkäät teitänne maassa, ja tulkaat siinä moneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Ja Jumala puhui Noalle ja hänen pojillensa hänen kanssansa, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Ja minä, katso, minä teen teidän kanssanne minun liittoni, ja teidän siemenenne kanssa teidän jälkeenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Ja jokaisen elävän hengen kanssa, jotka teidän tykönänne ovat, sekä linnuissa että karjassa, ja kaikissa eläimissä maan päällä, jotka teidän tykönänne ovat, kaikissa niissä, jotka arkista läksivät, mikä ikänänsä eläin se maassa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ja teen minun liittoni teidän kanssanne: ettei tästedes enää pidä kaikkea lihaa hukutettaman vedenpaisumisella: ja ei pidä tästedes enää vedenpaisumus tuleman maata turmelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Ja Jumala sanoi: tämä on sen liiton merkki, jonka minä annan minun ja teidän välillenne, ja joka elävän hengen välille teidän tykönänne, tästedes ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Minun kaareni minä olen pannut pilviin: sen pitää oleman liiton merkki, minun ja maan välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Ja koska niin tapahtuu, että minä tuotan pilven maan ylitse: niin pitää kaari pilvissä nähtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Ja niin minä muistan minun liittoni, minun ja teidän välillänne, ja joka elävän hengen kaikkinaisessa lihassa; ettei enää vedenpaisumus pidä tuleman kaikkea lihaa hukuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Sentähden pitää kaaren pilvissä oleman, että minä katson sitä, ja muistan sen ijankaikkisen liiton Jumalan välillä ja joka elävän hengen, kaikkinaisessa lihassa, kuin maan päällä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Ja Jumala sanoi Noalle: tämä on sen liiton merkki, jonka minä olen tehnyt minun ja kaiken lihan välille maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Ja Noan pojat, jotka läksivät arkista, olivat Sem, Ham, ja Japhet. Ja Ham oli Kanaanin Isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Nämä ovat kolme Noan poikaa, ja heistä ovat ne, jotka hajoitetut ovat kaikkeen maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Ja Noa rupesi olemaan peltomiesnä, ja istutti viinamäen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Ja hän joi viinaa; ja juopui ja makasi peittämättä majassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Koska Ham, Kanaanin Isä, näki hänen isänsä hävyn, sanoi hän sen molemmille veljillensä, jotka ulkona olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Niin otti Sem ja Japhet vaatteen, ja panivat molempain heidän hartioillensa, ja menivät seljittäin, ja peittivät isänsä hävyn. Ja heidän kasvonsa olivat käännetyt pois, niin etteivät he nähneet isänsä häpyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Koska Noa heräsi viinastansa, ja sai tietää, mitä hänen nuorin poikansa hänelle tehnyt oli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Niin sanoi hän: kirottu olkoon Kanaan: olkoon hän orjain orja, hänen veljeinsä seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Ja vielä sanoi: Kiitetty olkoon Herra Semin Jumala, ja Kanaan olkoon hänen orjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Jumala levittäköön Japhetin, ja hän asukoon Semin majoissa, ja Kanaan olkoon hänen orjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Ja Noa eli, vedenpaisumisen jälkeen kolmesataa ja viisikymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Ja koko Noan ikä oli yhdeksänsataa ja viisikymmentä ajastaikaa, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Tämä on Noan lasten sukukunta: Semin, Hamin ja Japhetin: ja heille syntyi lapsia vedenpaisumisen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Japhetin lapset: Gomer, Magog, Madai, Javan ja Tubal: Mesek ja Tiras.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Mutta Gomerin lapset: Askenas, Riphad ja Togarma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Javanin lapset: Elisa ja Tarsis: Kittim ja Dodanim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Näistä ovat hajoitetut pakanain luodot, heidän maakunnissansa, itsekukin oman kielensä jälkeen: heidän sukukuntainsa jälkeen, heidän kansoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Hamin lapset: Kus, Misraim, Put ja Kanaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Kuksen lapset: Seba, Hevila, Sabta, Naema ja Sabteka. Naeman lapset: Skepa ja Dedan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Mutta Kus siitti Nimrodin: hän rupesi olemaan valtias maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Ja hän oli jalo metsämies Herran edessä. Siitä on sananlasku: se on jalo metsämies Herran edessä, niinkuin Nimrod.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Ja hänen valtakuntansa alku oli Babel, Erek, Akad ja Kalne, Sinearin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Siitä maakunnasta tuli hän Assyriaan: ja rakensi Niniven, ja Rehobotin kaupungin, ja Kalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Ja myös Ressen, Niniven ja Kalan vaiheelle: joka on suuri kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Misraim siitti Ludimin, Anamimin, Leabimin, Naphtuhimin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Patrusimin ja Kasluhimin; joista tulleet ovat Philistim ja Kaphtorim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Mutta Kanaan siitti esikoisensa Sidonin ja Hetin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Ja Jebusin, Emorin, Girgosin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hivin, Arkin, Sinin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Ja Arvadin, Semarin ja Hamatin. Sitten ovat hajoitetut Kanaanealaisten suvut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Ja Kanaanealaisten rajat olivat Sidonista Gerarin kautta hamaan Gatsaan: Sodomaan, ja Gomorraan, ja Adamaan, Seboimiin päin, Lasaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Nämät ovat Hamin lapset heidän sukukuntainsa ja kieltensä jälkeen: heidän maakunnissansa ja kansoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Mutta myös itse Semille syntyi lapsia: hän oli kaikkein Eberin lasten isä: Japhetin sen vanhimman veli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, '(Ja nämät ovat) Semin lapset: Elam ja Assur: Arphaksad, Lud ja Aram.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Ja Aramin lapset: Uts, Hul, Geter ja Mas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Mutta Arphaksad siitti Salan: Sala siitti Eberin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Eberille syntyi kaksi poikaa: yksi kutsuttiin Peleg, että hänen aikanansa maailma jaettiin: hänen veljensä kutsuttiin Joktan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Joktan siitti Almodadin ja Salephin: Hasarmavetin ja Jaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoramin, Usalin, Dikelan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obalin, Abimaelin, Seban.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ophirin, Hevilan ja Jobabin. Kaikki nämä ovat Joktanin pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Ja heidän asumasiansa oli Mesasta: siihen asti kuin Sephariin tullaan, vuoren tykö, itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Nämät ovat Semin lapset, sukukuntainsa ja kieltensä jälkeen: heidän maakunnissansa, kansainsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Nämät ovat Noan lasten sukukunnat, heidän heimokuntainsa jälkeen, heidän kansoissansa. Ja näistä ovat kansat jaetut maan päälle vedenpaisumisen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Ja koko maailmalla oli yhtäläinen kieli ja yhtäläinen puheenparsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Ja koska he matkustivat idästä, löysivät he kedon Sinearin maalla, ja asuivat siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Ja sanoivat keskenänsä: käykäämme tiilejä tekemään ja polttamaan. Ja heillä olivat tiilit kivein siassa, ja maan pihka siteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Ja sanoivat: käykäämme, rakentakaamme meillemme kaupunki ja torni, joka taivaaseen ulottuisi, tehdäksemme meillemme nimeä; ettei meitä hajoitettaisi kaikkiin maihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Silloin Herra astui alas katsomaan kaupunkia ja tornia, jota ihmisten lapset rakensivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Ja Herra sanoi: katso, se on yhtäläinen kansa, ja yhtäläinen kieli on kaikkein heidän seassansa, ja he ovat ruvenneet tätä tekemään: ja nyt ei heitä taideta estettää mistään, kuin he ovat aikoneet tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Käykäämme, astukaamme alas ja sekoittakaamme siellä heidän kielensä; niin ettei kenkään ymmärtäisi toisensa kieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Ja niin Herra hajoitti heidät sieltä kaikkiin maihin; ja he lakkasivat sitä kaupunkia rakentamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Ja sentähden kutsuttiin hänen nimensä Babel: sillä siellä Herra sekoitti koko maan kielen: ja Herra hajoitti heidät sieltä kaikkiin maihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Nämät ovat Semin sukukunnat: Sem oli sadan ajastajan vanha, ja siitti Arphaksadin, kaksi ajastaikaa vedenpaisumisen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Ja eli sitte viisisataa ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arphaksad oli viidenneljättäkymmentä ajastajan vanha, ja siitti Salan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Ja eli sitte neljäsataa ja kolme ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Sala oli kolmenkymmenen ajastajan vanha, ja siitti Eberin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Ja eli sitte neljäsataa ja kolme ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Eber oli neljänneljättäkymmentä ajastajan vanha, ja siitti Pelegin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Ja eli sitte neljäsataa ja kolmekymmentä ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg oli kolmenkymmenen ajastajan vanha, ja siitti Regun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Ja eli sitte kaksisataa ja yhdeksän ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Regu oli kahdenneljättäkymmentä ajastajan vanha, ja siitti Serugin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Ja eli sitte kaksisataa ja seitsemän ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serug oli kolmenkymmenen ajastajan vanha ja siitti Nahorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Ja eli sitte kaksisataa ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nahor oli yhdeksänkolmattakymmentä ajastajan vanha, ja siitti Taran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Ja eli sitte sata ja yhdeksäntoistakymmentä ajastaikaa, ja siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Tara oli seitsemänkymmenen ajastajan vanha, ja siitti Abramin, Nahorin ja Haranin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Nämät ovat Taran sukukunnat: Tara siitti Abramin, Nahorin ja Haranin. Haran siitti Lotin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Ja Haran kuoli isänsä, Taran edessä, isänsä maalla Kaldean Uurissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Silloin Abram ja Nahor ottivat heillensä emännät: Abramin emännän nimi oli Sarai, ja Nahorin emännän nimi oli Milka, Haranin tytär, joka oli Milkan ja Jiskan isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Mutta Sarai oli hedelmätöin, eikä ollut hänellä lasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Ja Tara otti poikansa Abramin ja Lotin Haranin pojan, poikansa pojan, ja miniänsä Sarain, poikansa Abramin emännän, ja he läksivät ulos ynnä Kaldean Uurista menemään Kanaanin maalle, ja tulivat Haraniin, ja asuivat siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Ja Tara oli kahdensadan ja viiden ajastajan vanha ja kuoli Haranissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Ja Herra oli sanonut Abramille: Lähde maaltas, ja suvustas, ja isäs huoneesta: sille maalle, jonka minä sinulle osoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Ja minä teen sinun suureksi kansaksi, ja siunaan sinun, ja teen sinulle suuren nimen, ja sinä olet siunaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Minä siunaan niitä, jotka sinua siunaavat, ja kiroon niitä, jotka sinua kiroovat. Ja sinussa pitää kaikki sukukunnat maan päällä siunatuiksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Niin Abram läksi, niinkuin Herra hänelle sanonut oli, ja Lot meni hänen kanssansa: Mutta Abram oli viidenkahdeksattakymmentä ajastajan vanha Haranista lähteissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Niin otti Abram emäntänsä Sarain, ja Lotin, veljensä pojan, tavaroinensa, jotka he olivat panneet kokoon, ja sielut, jotka he olivat saaneet Haranissa, ja läksivät matkustamaan Kanaanin maalle; tulivat myös Kanaanin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Ja Abram vaelsi sen maakunnan lävitse, hamaan Sikemin paikkakuntaan, Moren lakeuteen asti. Ja siihen aikaan asuivat Kanaanealaiset maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Silloin näkyi Herra Abramille, ja sanoi: sinun siemenelles annan minä tämän maan. Ja hän rakensi siinä alttarin Herralle, joka hänelle näkynyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Sitte siirsi hän itsensä edemmä vuoren tykö, BetElistä itään päin, ja pani siihen majansa, niin että BetEl oli lännen puolella ja Ai idän puolella, ja rakensi siinä alttarin Herralle, ja saarnasi Herran nimestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Ja Abram läksi sieltä edemmä, ja vaelsi etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Niin tuli kova aika maalle, ja Abram meni alas Egyptiin, olemaan muukalaisna siellä: sillä sangen kova aika oli maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Ja tapahtui, koska hän lähestyi Egyptiä, puhui hän emännällensä Saraille: katso armaani, minä tiedän sinun ihanaksi vaimoksi nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Koska Egyptiläiset saavat sinun nähdä, niin he sanovat: tämä on hänen emäntänsä, ja tappavat minun, ja antavat sinun elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Sanos siis itses minun sisarekseni; että minulle hyvin olis sinun tähtes, ja minä eläisin sinun vuokses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Koska Abram tuli Egyptiin, näkivät Egyptiläiset vaimon juuri ihanaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Ja Pharaon ruhtinaat näkivät hänen, ja ylistivät häntä Pharaon edessä: silloin vietiin vaimo Pharaon huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Ja Abramille tehtiin hyvin hänen tähtensä. Ja hänellä oli lampaita ja karjaa, ja aaseja, ja palvelioita, ja piikoja, ja aasintammoja ja kameleja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mutta Herra vitsasi Pharaota suurilla vitsauksilla, ja hänen huonettansa, Sarain Abramin emännän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Silloin kutsui Pharao Abramin tykönsä, ja sanoi: miksis tämän minulle teit? miksi et ilmoittanut minulle häntä emännäkses?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Miksis sanoit, hän on sisareni? että minä ottaisin hänen emännäkseni? katso tässä on sinun emäntäs, ota häntä ja mene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Ja Pharao antoi käskyn hänestä miehillensä: ja he saattoivat hänen ulos ja hänen emäntänsä, ja kaikki kuin hänellä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Niin Abram vaelsi ylös Egyptistä emäntänsä ja kaiken kalunsa kanssa, ja Lot hänen kanssansa, etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Ja Abramilla oli sangen paljo karjaa, hopiaa ja kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Ja hän matkusti edespäin etelästä BetEliin asti, hamaan siihen paikkaan, jossa hänen majansa oli ennen ollut, BetElin ja Ain vaiheella:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Juuri siihen paikkaan, johon hän ennen alttarin oli rakentanut; ja Abram saarnasi siinä Herran nimestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Mutta Lotilla, joka Abramia seurasi, oli myös lampaita, ja karjaa, ja majoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Ja ei heitä vetänyt maa yhdessä asumaan; sillä heillä oli paljo tavaraa, eikä taitaneet yhdessä asua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Ja riita oli Abramin paimenien ja Lotin paimenien välillä: Ja siihen aikaan asuivat myös Kanaanealaiset ja Pheresiläiset maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Niin Abram sanoi Lotille: älkään olko riita minun ja sinun välilläs, ja minun ja sinun paimentes välillä: sillä me olemme miehet veljekset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Eikö koko maa ole edessäs altis? eroita sinus minusta, jos sinä menet vasemmalle puolelle, minä menen oikialle, eli jos sinä menet oikialle, minä menen vasemmalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Niin Lot nosti silmänsä, ja katseli kaiken Jordanin lakeuden; sillä se oli vedestä viljainen: ennen kuin Herra Sodoman ja Gomorran hukutti, oli se niinkuin Herran yrttitarha, niinkuin Egyptin maa, siihenasti kuin Zoariin tullaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Ja Lot vallitsi itsellensä koko sen lakeuden Jordanin tykönä, ja matkusti itään päin: ja niin veljekset erkanivat toinen toisestansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Että Abram asui Kanaanin maalla, ja Lot asui lakeuden kaupungeissa, ja pani majansa Sodoman puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Mutta Sodoman kansa oli paha, ja rikkoi kovin Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Ja Herra sanoi Abramille, sitte kuin Lot oli eroittanut itsensä Abramista: nosta nyt silmäs ja katso siitä, kussas asut, pohjan puoleen, etelän puoleen, idän puoleen ja lännen puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Sillä kaiken sen maan, minkä sinä näet, annan minä sinulle, ja sinun siemenelles ijankaikkiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Ja teen sinun siemenes niinkuin tomun maan päällä: että jos joku taita lukea tomun maan päällä, niin hän myös taitaa sinun siemenes lukea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Nouse ja vaella maata pitkin ja poikin: sillä sinulle minä sen annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Niin Abram siirsi majansa, ja tuli, ja asui Mamren lakeudella, joka on Hebronissa: ja rakensi siinä alttarin Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Ja tapahtui Amraphelin Sinearin kuninkaan, Ariokin Elassarin kuninkaan, Kedorlaomerin Elamin kuninkaan, ja Tidealin pakanoitten kuninkaan aikana:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Että he sotivat Bereaa Sodoman kuningasta, ja Birsaa Gomorran kuningasta, ja Sineabia Adaman kuningasta, ja Semeberiä Zeboimin kuningasta, ja Belan, se on Zoarin, kuningasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Nämät kaikki tulivat yhteen Siddimin laaksossa; se on suolainen meri:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Sillä he olivat olleet kaksitoistakymmentä ajastaikaa kuningas Kedorlaomerin alla; mutta kolmantenatoistakymmenentenä ajastaikana olivat he hänestä luopuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Neljäntenätoistakymmenentenä ajastaikana tuli Kedorlaomer, ja ne kuninkaat, kuin hänen kanssansa olivat, ja löivät ne Kalevan pojat Karnaimin Astarotissa, ja Susimin Hammissa; niin myös Emimin Sjaven Kirjataimissa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Ja Horilaiset Seirin vuorella; siihen lakiaan paikkaan Pharaniin asti, korpea liki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Ja he palasivat ja tulivat Mispatin lähteen tykö, se on Kades, ja löivät koko Amalekilaisten maan; niin myös Amorilaiset, jotka asuivat Hasesonin Tamarissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Niin läksivät Sodoman kuningas, ja Gomorran kuningas, ja Adaman kuningas, ja Zeboimin kuningas, ja Belan, se on Zoarin kuningas: ja hankitsivat sotaan heitä vastaan Siddimin laaksossa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Kedorlaomeria Elamin kuningasta, ja Tibealia pakanoitten kuningasta, ja Amraphelia Sinearin kuningasta, ja Ariokia Elassarin kuningasta vastaan: neljä kuningasta viittä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Ja Siddimin laaksossa oli monta maanpihkakuoppaa. Mutta Sodoman ja Gomorran kuningas siinä pakoon ja maahan lyötiin, ja jääneet pakenivat vuorille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Ja he ottivat kaiken Sodoman ja Gomorran tavaran, ja kaiken heidän elatuksensa, ja menivät matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ja ottivat myös Lotin Abramin veljen pojan kanssansa, ja hänen tavaransa, ja menivät matkaansa, sillä hän asui Sodomassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Silloin tuli yksi joka päässyt oli, ja ilmoitti sen Abramille Hebrealaiselle, joka asui Mamren Amorilaisen lakeudella, joka Eskolin ja Anerin veli oli. Nämät olivat liitossa Abramin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Koska Abram kuuli veljensä otetuksi kiini, varusti hän omaa kotona syntynyttä palveliaansa kolmesataa ja kahdeksantoistakymmentä, ja ajoi takaa heitä Daniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Jakoi itsensä ja karkasi heidän päällensä yöllä palvelioinensa, ja löi heitä: ja ajoi takaa hamaan Hobaan, joka on vasemmalla puolella Damaskua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Ja toi jällensä kaiken tavaran: ja myös veljensä Lotin ja hänen tavaransa toi hän jällensä, niin myös vaimot ja väen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Silloin meni Sodoman kuningas häntä vastaan, koska hän palasi lyömästä Kedorlaomeria, ja niitä kuninkaita hänen kanssansa: Sjaven lakeudella, joka kuninkaan laaksoksi kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Mutta Melkisedek Salemin kuningas toi leivän ja viinan: ja hän oli ylimmäisen Jumalan pappi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Ja siunasi häntä, ja sanoi: siunattu ole sinä Abram sille kaikkein korkeimmalle Jumalalle, jonka taivas ja maa oma on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Ja kiitetty olkoon kaikkein korkein Jumala, joka sinun vihollises antoi sinun käsiis. Ja (Abram) antoi hänelle kymmenykset kaikista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Silloin Sodoman kuningas sanoi Abramille: anna minulle väki, ja pidä itse tavara.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Ja Abram sanoi Sodoman kuninkaalle: Minä nostan minun käteni Herran kaikkein korkeimman Jumalan tykö, jonka taivas ja maa oma on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Etten minä ota kaikesta sinun omastas lankaakaan eli kengän rihmaa, ettes sanoisi: minä olen Abramin äveriääksi tehnyt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Ei suinkaan, paitsi sitä kuin nämät nuoret miehet syöneet ovat; ja niiden miesten osan, jotka minua seurasivat: Aner, Eskol ja Mamre, he saakoon osansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Kuin nämä olivat niin tapahtuneet, tuli Herran sana Abramin tykö näyssä, sanoen: älä pelkää Abram, minä olen sinun kilpes, ja sangen suuri palkkas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Mutta Abram sanoi: Herra, Herra, mitäs minulle annat? minä lähden lapsetoinna täältä, ja minun huoneeni haltia on tämä Eleasari Damaskusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Ja Abram taas sanoi: mutta minulle et sinä antanut siementä. Ja katsos, minun kotopalkolliseni tulee minun perillisekseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Ja katso, Herran sana tuli hänen tykönsä, sanoen: ei tämä sinua peri: vaan joka sinun ruumiistas tulee, se tulee sinun perillisekses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Niin hän vei hänen ulos, ja sanoi: katso taivaaseen ja lue tähdet, jos sinä ne taidat lukea. Ja sanoi hänelle: niin sinun siemenes on oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, '(Abram) uskoi Herran, ja hän luki hänelle sen vanhurskaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Ja sanoi hänelle: minä se Herra olen, joka vein sinun ulos Kaldean Uurista, antaakseni sinulle tämän maan omakses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Ja hän sanoi: Herra, Herra, mistä minä tietäisin sen omistavani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Ja hän sanoi hänelle: ota minulle kolmivuotinen hehkonen, ja kolmivuotinen vuohi, ja kolmivuotinen oinas: niin myös mettinen, ja nuori kyhkyläinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Ja hän otti hänelle nämät kaikki, ja jakoi keskeltä kahtia, ja pani itsekunkin osan toinen toisensa kohdalle; vaan lintuja ei hän jakanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Niin linnut tulivat lihain päälle; ja Abram karkotti ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Ja tapahtui auringon laskeissa, että raskas uni lankesi Abramin päälle: ja katso, hämmästys ja synkkä pimeys tuli hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Niin hän sanoi Abramille: sinun pitää totisesti tietämän, että sinun siemenes tulee muukalaiseksi sille maalle, joka ei heidän omansa ole, ja he saattavat heitä orjaksi, ja vaivaavat heitä neljäsataa ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mutta sille kansalle, jonka orjana he ovat, kostan minä: ja sitte he lähtevät ulos suurella tavaralla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Ja sinä menet isäis tykö rauhassa, ja haudataan hyvässä ijässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Vaan neljännessä miespolvessa he tänne palajavat: sillä Amorilaisten pahuus ei ole vielä täytetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Ja koska aurinko oli laskenut, ja pimeys joutunut: katso, pätsi suitsi, ja liekki kävi kappaleitten keskeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Sinä päivänä teki Herra liiton Abramin kanssa, sanoen: sinun siemenelles annan minä tämän maan, hamasta Egyptin virrasta, niin suureen virtaan Phratiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Keniläiset, ja Kenitsiläiset, ja Kadmonilaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Ja Hetiläiset, ja Pheresiläiset, ja Kalevan pojat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Ja Amorilaiset, ja Kanaanealaiset, ja Gergesiläiset, ja Jebusilaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Ja Sarai Abramin emäntä ei synnyttänyt hänelle. Mutta hänellä oli Egyptiläinen piika, jonka nimi oli Hagar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Ja Sarai sanoi Abramille: katso nyt; Herra on minun sulkenut synnyttämästä, menes siis minun piikani sivuun, jos minä sittenkin saisin lapsia hänestä. Ja Abram otti Sarain sanan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Ja Sarai Abramin emäntä otti Egyptiläisen piikansa Hagarin, sitte kun Abram kymmenen ajastaikaa oli asunut Kanaanin maalla: ja antoi sen miehellensä Abramille emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Ja hän makasi Hagarin tykönä, joka tuli raskaaksi. Koska hän tunsi itsensä raskaaksi, tuli hänen emäntänsä halvaksi hänen silmissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Niin sanoi Sarai Abramille: minulle tapahtunut vääryys lankee sinun päälles; minä annoin minun piikani sinun sivuus; ja että hän tunsi itsensä raskaaksi, halpenin minä hänen edessänsä: Herra tuomitkoon minun ja sinun välilläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Mutta Abram sanoi Saraille: katso, sinun piikas on sinun käsissäs, tee hänen kanssansa mitäs tahdot: Niin Sarai kuritti häntä, ja hän pakeni hänen tyköänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Mutta Herran enkeli löysi hänen vesilähteen tykönä korvessa: lähteen tykönä Surrin tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Ja sanoi: Hagar, Sarain piika, kustas tulet? ja kuhunkas menet? hän sanoi: minä pakenin emäntääni Saraita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Ja Herran enkeli sanoi hänelle: palaja emäntäs tykö, ja nöyryytä itses hänen kätensä alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Ja Herran enkeli sanoi hänelle: minä lisään suuresti sinun siemenes, niin ettei sitä taideta luettaa paljouden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Ja Herran enkeli sanoi (vielä) hänelle: katso, sinä olet raskas, ja synnytät pojan: ja sinun pitää kutsuman hänen nimensä Ismael: sillä Herra on kuullut sinun vaivas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Hän tulee tylyksi mieheksi, ja hänen kätensä jokaista vastaan, ja jokaisen käsi häntä vastaan, ja hän on asuva kaikkein veljeinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Ja hän kutsui Herran nimen, joka häntä puhutteli, sinä Jumala, joka näet minun, sillä hän sanoi: enkö minä ole katsonut hänen peräänsä, joka minun näkee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Sentähden nimitti hän sen kaivon, sen elävän kaivoksi, joka minun näkee, joka on Kadeksen ja Baredin välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Ja Hagar synnytti Abramille pojan: ja Abram kutsui poikansa nimen, jonka Hagar synnytti, Ismael.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Ja Abram oli kuudenyhdeksättäkymmentä ajastajan vanha, koska Hagar synnytti Ismaelin Abramille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Koska Abram oli yhdeksänkymmenen ja yhdeksän ajastaikainen, näkyi Herra Abramille ja sanoi hänelle: Minä olen Jumala kaikkivaltias: vaella minun edessäni, ja ole vakaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ja minä teen liittoni minun ja sinun välilles, ja lisään sinun sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Ja Abram lankesi kasvoillensa: Ja Jumala puhui hänen kanssansa, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Katso, Minä olen, ja minun liittoni on sinun kanssas, ja sinä tulet paljon kansan isäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Sentähden ei sinua pidä enää kutsuttaman Abram; mutta Abrahamin pitää oleman sinun nimes: sillä minä olen tehnyt sinun paljon kansan isäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Ja teen sinun sangen suuresti hedelmälliseksi, ja asetan sinun kansoiksi: ja kuninkaat tulevat sinusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Ja minä teen minun liittoni minun vaiheelleni ja sinun, ja sinun siemenes sinun jälkees, heidän suvuissansa ijankaikkiseksi liitoksi: että minä olen sinun Jumalas, ja sinun siemenes sinun jälkees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Ja annan sinulle ja sinun siemenelles sinun jälkees, sen maan, jossa sinä muukalainen olet; koko Kanaanin maan ijäiseksi omaisuudeksi: ja olen heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Ja Jumala sanoi Abrahamille: pidä siis minun liittoni, sinä ja sinun siemenes sinun jälkees, heidän suvuissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Ja tämä on liitto, jonka teidän pitämän pitää, minun vaiheellani ja teidän, ja sinun siemenes vaiheella sinun jälkees: kaikki miehenpuoli pitää teidän seassanne ympärileikattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Ja teidän pitää ympärileikkaaman teidän esinahkanne lihan: sen pitää oleman liiton merkiksi minun ja teidän vaiheellanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Kahdeksan päiväinen poikalapsi pitää ympärileikattaman teidän seassanne, kaikki miehenpuoli teidän suvuissanne: kotona syntynyt, eli kaikkinaiselta muukalaiselta rahalla ostettu, joka ei ole sinun siemenestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Kaiketi pitää ympärileikattaman sekä kotonas syntynyt, että rahallas ostettu; ja niin minun liittoni on oleva teidän lihassanne ijankaikkiseksi liitoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Ja jonka esinahallisen miehenpuolen esinahan liha ei ympärileikata, se sielu pitää hukutettaman kansastansa: hän on minun liittoni rikkonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Ja Jumala sanoi Abrahamille: Saraita sinun emäntääs ei pidä sinun enää kutsuman Sarai; vaan Saara pitää oleman hänen nimensä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Sillä minä siunaan häntä, ja annan myös hänestä sinulle pojan; sillä minä siunaan hänen, ja hän on tuleva kansoiksi, ja kansain kuninkaat tulevat hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Ja Abraham lankesi kasvoillensa ja naurahti, ja sanoi sydämessänsä: syntyneekö sadanajastaikaiselle poika? ja Saara yhdeksänkymmenen ajastaikainen synnyttäneekö?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Ja Abraham sanoi Jumalalle: josko Ismael sais elää sinun edessäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Niin sanoi Jumala: Tosin Saara sinun emäntäs synnyttää sinulle pojan ja sinun pitää hänen nimensä kutsuman Isaak: ja minä teen minun liittoni hänen kanssansa ijankaikkiseksi liitoksi, hänen siemenellensä hänen jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Ismaelista olen minä myös sinun rukoukses kuullut, katso, minä olen siunannut häntä, ja teen hänen hedelmälliseksi, ja lisään hänen sangen suuresti: kaksitoistakymmentä ruhtinasta pitää hänen siittämän, ja minä teen hänen suureksi kansaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mutta minun liittoni teen minä Isaakin kanssa; jonka Saara on sinulle synnyttävä, tähän aikaan tulevana vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Ja kuin puhe oli päätetty hänen kanssansa, meni Jumala ylös Abrahamin tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Ja Abraham otti poikansa Ismaelin, ja kaikki kotona syntyneet, ja kaikki ostetut: kaiken miehenpuolen Abrahamin huoneessa: ja ympärileikkasi heidän esinahkansa lihan, kohta sinä päivänä kuin Jumala oli puhunut hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Ja Abraham oli yhdeksän ja yhdeksänkymmenen ajastaikainen, koska hänen esinahkansa liha ympärileikattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Mutta Ismael hänen poikansa oli kolmentoistakymmenen ajastaikainen, koska hänen esinahkansa liha ympärileikattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Yhtenä päivänä ympärileikattiin Abraham, ja Ismael hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Ja kaikki miehenpuoli hänen huoneessansa, kotona syntyneet ja muukalaisilta ostetut, ympärileikattiin hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Ja Herra näkyi hänelle Mamren lakeudella; jossa hän istui majan ovella, koska päivä oli palavimmallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Koska hän silmänsä nosti ja näki, katso kolme miestä seisoivat hänen edessänsä: ja kuin hän näki heidät, juoksi hän heitä vastaan majan ovelta, ja kumarsi itsensä maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Ja sanoi: Herra, jos minä olen armon löytänyt sinun edessäs, niin älä mene palvelias ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Ja sallikaat tuotaa vähä vettä pestäksenne teidän jalkanne, ja levätkäät teitänne puun alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Ja minä tuon teidän eteenne kappaleen leipää, virvottaaksenne teidän sydäntänne, ja sitte menkäät: sillä sentähden te poikkesitte teidän palvelianne tykö. Ja he sanoivat: tee niin kuin sinä olet puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Niin Abraham riensi majaan Saaran tykö, ja sanoi: riennä sinuas ja tuo kolme mittaa sämpyläjauhoja, sotke ja leivo kaltiaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Ja Abraham juoksi karjan tykö: ja toi nuoren ja kauniin vasikan, ja antoi palveliallensa, joka riensi valmistamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Ja hän toi voita ja maitoa, ja vasikasta, jota hän valmistanut oli, ja pani heidän eteensä: ja hän seisoi heidän edessänsä puun alla ja he söivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Niin sanoivat he hänelle: kussa on Saara sinun emäntäs? hän vastasi: täällä majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Ja hän sanoi: tosin minä palajan sinun tykös, liki tällä vuoden ajalla, ja katso, Saaralla emännälläs on poika. Ja Saara kuuli sen majan ovelle, joka oli hänen takanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Mutta Abraham ja Saara olivat vanhat ja ijälliseksi joutuneet; niin että Saaralta olivat lakanneet vaimolliset menot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Sentähden nauroi Saara itsellensä, ja sanoi: nyt koska minä vanha olen, antanenko minä itseni hekumaan? ja minun herrani on vanhentunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Ja Herra sanoi Abrahamille: miksi Saara nauroi, sanoen: pitäneeköstä todellakin minun synnyttämän, joka olen vanhaksi tullut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Onko Herralle jotakin mahdotointa? Määrättyyn aikaan, koska minä palajan sinun tykös, tällä vuoden ajalla, niin Saaralla on poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Niin Saara kielsi, sanoen: en minä nauranut: sillä hän hämmästyi. Mutta hän sanoi: ei ole niin, sinä nauroit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Silloin nousivat miehet sieltä, ja käänsivät heitänsä Sodomaan päin: ja Abraham meni heidän kanssansa, saattamaan heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Ja Herra sanoi: kuinka minä salaan Abrahamilta, jota minä teen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Että Abraham tulee suureksi ja väkeväksi kansaksi, ja kaikki kansat maan päällä pitää hänessä siunatuksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Sillä minä tunnen hänen, että hän käskee lapsiansa ja huonettansa hänen jälkeensä Herran tietä pitämään, ja tekemään hurskautta ja oikeutta: että Herra saattais Abrahamille kaikki, kuin hän hänelle luvannut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Ja Herra sanoi: Sodomassa ja Gomorrassa on suuri huuto, ja heidän syntinsä ovat sangen raskaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Minä astun nyt alas ja katson, jos he täydellisesti tehneet ovat huudon jälkeen, joka minun eteeni tullut on; taikka jos ei niin ole, että minä sen tietäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Ja miehet käänsivät itsensä sieltä, ja menivät Sodomaan päin. Mutta Abraham jäi seisomaan vielä Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Ja Abraham astui hänen tykönsä, ja sanoi: hukutatkos myös vanhurskaan jumalattoman kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Jos kaupungissa olisi viisikymmentä vanhurskasta, hukuttaisitkos myös ne, ja et säästäisi sitä siaa viidenkymmenen vanhurskaan tähden, jotka siellä olisivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Pois se sinusta, ettäs sen tekisit, ja kuolettaisit vanhurskaan jumalattoman kanssa, ja että vanhurskaalle kävis niinkuin jumalattomallekin. Pois se sinusta: Eikö kaiken maailman tuomari oikein tuomitsisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Herra sanoi: jos minä löydän viisikymmentä vanhurskasta Sodoman kaupungissa; niin minä säästän kaiken sen paikan heidän tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham vastasi ja sanoi: katso, minä olen ruvennut puhumaan minun Herrani kanssa; ehkä minä tomu ja tuhka olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Mitämaks, jos oli vailla viisi niistä viidestäkymmenestä vanhurskaasta, kadottaisitkos viiden tähden koko kaupungin? ja hän sanoi: en kadota, jos minä löydän siellä viisiviidettäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Ja hän puhui vielä hänelle, ja sanoi: mitämaks, siinä löyttäisiin neljäkymmentä? ja hän sanoi: en tee minä neljänkymmenen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Abraham sanoi: älköön minun Herrani vihastuko, että minä vielä puhun: mitämaks, löyttäisiin siellä kolmekymmentä? ja hän sanoi: en minä tee, jos minä löydän siellä kolmekymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Ja hän sanoi taas: katso, minä olen ruvennut puhumaan minun Herrani kanssa: mitämaks, löyttäisiin siellä kaksikymmentä? ja hän sanoi: en kadota heitä kahdenkymmenen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Ja hän vielä sanoi: älköön minun Herrani vihastuko, jos minä ainoastansa tällä erällä puhu: mitämaks, siellä löyttäisiin kymmenen? ja hän sanoi: en kadota heitä kymmenen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Ja Herra meni pois sitte kuin hän oli Abrahamin kanssa puhunut: ja Abraham palasi kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Ja kaksi enkeliä tulivat ehtoona Sodomaan, ja Lot istui Sodoman portissa: ja kuin hän näki heidät, nousi hän heitä vastaan, ja kumarsi kasvoillensa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Ja sanoi: katso, minun Herrani, poiketkaat teidän palvelianne huoneeseen yöksi, ja antakaat pestä jalkanne, ja aamulla varhain noustuanne menette matkaan. Ja he sanoivat: ei suinkaan, vaan kadulla me yötä pidämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Ja hän kovin vaati heitä, ja he poikkesivat hänen tykönsä, ja tulivat hänen huoneeseensa. Ja hän valmisti heille aterian, ja leipoi happamattomia leipiä, ja he söivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Ennenkuin he levätä panivat, tulivat kaupungin miehet, Sodomalaiset, nuoret ja vanhat: kaikki kansa joka kulmalta, ja piirittivät huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Ja huusivat Lotin, ja sanoivat hänelle: kussa ovat ne miehet, jotka sinun tykös yöllä tulivat? tuo heitä meidän tykömme tutaksemme heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Silloin Lot meni ulos heidän tykönsä oven eteen, ja sulki oven jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Ja sanoi: älkäät te, rakkaat veljeni, tehkö niin pahoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Katso, minulla on kaksi tytärtä, jotka ei vielä miehestä mitään tiedä: ne minä tuotan teille, tehkäät heille mitä te tahdotte: ainoastansa näille miehille älkäät mitään pahaa tehkö; sillä sentähden ovat he tulleet minun kattoni varjon ala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Mutta he sanoivat: tule tänne. Ja sanoivat: tuleeko joku muukalaiseksi, ja kuitenkin tahtoo kokonansa hallita? nyt, me teemme enemmän pahaa sinulle kuin heille: ja he tekivät suurella väkivallalla miehelle Lotille ylläkön, ja juoksivat ovea särkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Niin miehet ojensivat kätensä ulos, ja tempasivat Lotin tykönsä huoneesen, ja paiskasivat oven kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Ja miehet, kuin huoneen oven edessä olivat, löivät he sokeudella, pienet ja suuret, niin että he väsyivät ovea etseissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Ja miehet sanoivat Lotille: onko sinulla vielä tässä joku? vävyjä, eli poikia taikka tyttäriä, eli kaikkia mitä sinulla on tässä kaupungissa? vie ne ulos tästä siasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Sillä me hukutamme tämän paikan: että heidän huutonsa on suuri Herran edessä, niin Herra lähetti meidät heitä hukuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Niin Lot meni ulos ja puhutteli vävyjänsä, jotka piti saaman hänen tyttärensä, ja sanoi: nouskaat ja lähtekäät tästä siasta: sillä Herra hukuttaa tämän kaupungin: mutta hän oli niinkuin leikkiä tekevä hänen vävyinsä silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Koska aamurusko kävi ylös, kiiruhtivat enkelit Lotin joutumaan, ja sanoivat: nouse, ota emäntäs, ja kaksi tytärtäs, jotka saapuvilla ovat, ettet sinä myös hukkuisi tämän kaupungin pahuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Koska hän viipyi, tarttuivat miehet hänen käteensä, ja hänen emäntänsä, ja hänen kahden tyttärensä käteen, sillä Herra tahtoi säästää heitä: ja taluttivat hänen ulos ja jättivät hänen ulkopuolelle kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Ja koska he johdattivat heitä ulos, sanoivat he: pelasta sinun sielus, ja älä katsahda taakses, ja älä myös seisahda koko tälle lakeudelle; vaan turvaa sinuas vuorelle, ettes hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Ja Lot sanoi heille: Ei Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Katso, sinun palvelias on löytänyt armon sinun edessäs, sinä olet tehnyt sinun laupeutes suureksi, jonkas minulle osotit, pelastaakses minun sieluani: en taida minä pelastaa minuani vuorella, ettei minulle jotakuta pahaa tapahtuisi, ja kuolisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Katsos, tuo kaupunki on läsnä, paeta sinne: ja hän on vähä: salli minua siellä pelastettaa: eikö hän ole vähäinen? että minun sieluni siellä elävänä pysyis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Niin sanoi hän hänelle: katso, tässä asiassa olen minä myös sinun rukoukses päälle katsonut: etten minä kukista sitä kaupunkia, jostas puhuit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Riennä, pelasta sinuas siellä: sillä en minä taida tehdä mitään, siihenasti ettäs sinne sisälle tulet. Sentähden kutsui hän sen kaupungin Zoar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Aurinko oli noussut maan päälle, ja Lot tuli Zoariin sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Ja Herra antoi sataa Sodoman ja Gomorran päälle tulikiveä ja tulta: Herralta taivaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Ja kukisti ne kaupungit, ja kaiken sen lakeuden: niin myös kaikki niiden kaupunkein asuvaiset, ja maan kasvon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Ja Lotin emäntä käänsi kasvonsa takaisin hänestä; ja muuttui suolapatsaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Mutta Abraham nousi varhain aamulla, ja meni siihen paikkaan, kussa hän oli ennen seisonut Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Ja katsahti Sodomaa ja Gomorraa päin, ja kaiken sen maan lakeuteen; ja näki että savu nousi maasta niinkuin pätsin savu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Ja tapahtui, koska Jumala kukisti sen lakeuden kaupungit, muisti Jumala Abrahamin: ja johdatti Lotin ulos hävityksen keskeltä, koska hän kukisti ne kaupungit, joissa Lot asui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Ja Lot läksi Zoarista, ja asui vuorella, ja kaksi hänen tytärtänsä hänen kanssansa; sillä hän pelkäsi asua Zoarissa: ja oli luolassa ja kaksi hänen tytärtänsä hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Niin sanoi vanhempi nuoremmalle: meidän isämme on vanha: eikä ole muuta miestä maan päällä, makaamaan meidän kanssamme, koko maan tavan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Käykäämme, juottakaamme meidän isämme viinalla, ja maatkaamme hänen kanssansa, herättääksemme isästämme siementä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Niin he juottivat isänsä sinä yönä viinalla. Ja vanhempi tuli ja makasi isänsä kanssa, ja ei hän huomainnut koska hän levätä tuli, ja koska hän nousi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Toisena päivänä sanoi vanhempi nuoremmalle: katso, minä makasin menneenä yönä isäni kanssa: juottakaamme häntä tänäkin yönä viinalla, ja mene sinä ja makaa hänen kanssansa, herättääksemme isästämme siementä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Niin he juottivat myös sinä yönä isänsä viinalla: ja nuorempi meni ja makasi hänen kanssansa, ja ei hän huomainnut koska hän levätä tuli, ja koska hän nousi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Ja niin molemmat Lotin tyttäret tulivat isästänsä raskaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Ja vanhempi synnytti pojan, ja kutsui hänen nimensä Moab: hänestä ovat Moabilaiset tulleet, hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Ja nuorempi myös synnytti pojan, ja kutsui hänen nimensä BenAmmi: hänestä tulivat Ammonin lapset, hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Niin Abraham vaelsi sieltä etelään päin, ja asui Kadeksen ja Surrin vaiheella: ja oli muukalainen Gerarissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Ja Abraham sanoi emännästänsä Saarasta: hän on minun sisareni. Niin Abimelek Gerarin kuningas lähetti ja antoi noutaa Saaran tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Mutta Jumala tuli Abimelekin tykö yöllä unessa: ja sanoi hänelle: katso, sinun pitää kuoleman sen vaimon tähden, jonkas ottanut olet; sillä hän on yhden miehen aviovaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Mutta Abimelek ei ollut ryhtynyt häneen, ja sanoi: Herra tahdotkos myös surmata hurskaan kansan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Eikö hän sanonut minulle: hän on minun sisareni, ja hän myös itse sanoi: hän on minun veljeni: yksivakaisella sydämellä ja viattomilla käsillä olen minä sen tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Ja Jumala sanoi hänelle unessa: minä myös tiedän, ettäs sydämes yksivakaisuudessa sen tehnyt olet. Sentähden minä myös estin sinun, ettes rikkoisi minua vastaan; jonka tähden en minä sallinut sinua ryhtymään häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Niin anna nyt miehelle hänen emäntänsä jälleen; sillä hän on propheta: ja hän on rukoileva sinun edestäs, ettäs saat elää. Mutta jos et sinä anna häntä jälleen, niin tiedä, ettäs totisesti kuolet, ja kaikki mitä sinulla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Niin Abimelek nousi varhain aamulla, ja kutsui kaikki palveliansa, ja puhui kaikki nämät sanat heidän kuultensa: ja miehet pelkäsivät suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Ja Abimelek kutsui Abrahamin, ja sanoi hänelle: mitäs meille teit? ja mitä minä olen rikkonut sinua vastaan, ettäs saattaisit minulle ja minun valtakunnalleni niin suuren rikoksen? sinä olet tehnyt minua vastaan niitä töitä joita ei sovi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Ja Abimelek sanoi vielä Abrahamille: mitäs näit, ettäs tämän teit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham sanoi: minä ajattelin: kukaties ei tässä paikassa ole yhtään Jumalan pelkoa: ja he surmaavat minun, emäntäni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Ja hän on tosin minun sisareni: sillä hän on minun isäni tytär, vaan ei äitini tytär: ja minä otin hänen emännäkseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Koska Jumala laski minun kulkemaan isäni huoneesta, sanoin minä hänelle: tämä on sinun lempes, jonka sinun minua kohtaan pitää tekemän: kuhunka paikkaan ikänänsä me tulemme, sano minusta: hän on minun veljeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Niin Abimelek otti lampaita, ja karjaa, ja palvelioita, ja piikoja, ja antoi Abrahamille: ja antoi hänelle jälleen Saaran hänen emäntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Ja Abimelek sanoi: katso, minun maani on altis sinun edessäs: asu kussa sinulle parhain kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Ja sanoi Saaralle: katso, minä olen antanut veljelles tuhannen hopiapenninkiä, katso, ne pitää oleman sinulle silmäin peitteeksi, kaikkein edessä, jotka sinun kanssas ovat, ja kaikkein muiden edessä. Ja niin vahvistettiin (hänen nuhteettomuutensa).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Ja Abraham rukoili Jumalaa: ja Jumala paransi Abimelekin, ja hänen emäntänsä, ja hänen piikansa, ja ne siittivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Sillä Herra oli peräti sulkenut kaikki kohdut Abimelekin huoneessa, Saaran Abrahamin emännän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Ja Herra etsi Saaraa, niinkuin hän sanonut oli: ja Herra teki Saaralle niinkuin hän puhunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Ja Saara tuli raskaaksi, ja synnytti Abrahamille pojan hänen vanhuudessansa; sillä ajalla kuin Jumala hänelle sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Ja Abraham kutsui poikansa nimen, joka hänelle syntynyt oli, ja jonka Saara hänelle synnyttänyt oli, Isaak.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Ja Abraham ympärileikkasi poikansa Isaakin kahdeksan päiväisenä: niinkuin Jumala hänen käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Ja Abraham oli sadan ajastaikainen, koska Isaak hänen poikansa hänelle syntyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Ja Saara sanoi: Jumala on tehnyt minulle nauron: kuka ikänä sen saa kuulla, hän nauraa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Ja sanoi vielä: kuka olis taitanut sanoa Abrahamille: Saara on lapsia imettävä; sillä minä olen synnyttänyt pojan hänen vanhuudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Ja lapsi kasvoi ja vieroitettiin: ja Abraham teki suuren pidon sinä päivänä, jona Isaak vieroitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Ja Saara näki Egyptiläisen Hagarin pojan, jonka se Abrahamille synnyttänyt oli, pilkkaajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Ja sanoi Abrahamille: aja ulos tämä palkkavaimo poikinensa: sillä palkkavaimon pojan ei pidä perimän minun poikani Isaakin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Ja tämä sana oli Abrahamin mielestä sangen karvas, hänen poikansa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Mutta Jumala sanoi Abrahamille: älä ota sitä pahakses pojasta ja palkkapiiastas: kaikki mitä Saara sinulle sanoo, niin kuule häntä: sillä Isaakissa pitää sinulle siemen kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Minä teen myös piikas pojan (suureksi) kansaksi; että hän sinun siemenes on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Niin nousi Abraham aamulla varhain, ja otti leipiä ja vesileilin; ja antoi Hagarille, ja pani hänen selkäänsä, ja (antoi hänelle) pojan, ja laski hänen menemään. Ja hän meni matkaansa, ja eksyi BerSaban korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Koska vesi oli loppunut leilistä, heitti hän pojan puun alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Ja meni pois, ja istui hänen kohdallensa taamma, liki joutsen kantamalle; sillä hän sanoi: en minä voi nähdä pojan kuolemaa. Ja hän istui hänen kohdallensa, korotti äänensä ja itki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Ja Jumala kuuli pojan äänen, ja Jumalan enkeli huusi Hagaria taivaasta, ja sanoi hänelle: mikä sinun on, Hagar? älä pelkää; sillä Jumala on kuullut pojan äänen, kussa hän makaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Nouse, ota poika, ja tue häntä kädelläs: sillä minä teen hänen suureksi kansaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Ja Jumala avasi hänen silmänsä, että hän näki vesikaivon; niin hän meni ja täytti leilin vedellä, ja antoi pojan juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Ja Jumala oli pojan kanssa, ja hän kasvoi; ja asui korvessa, ja tuli tarkaksi joutsimieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Ja asui Paranin korvessa; ja hänen äitinsä otti hänelle emännän Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Sillä ajalla puhui Abimelek ja hänen sotapäämiehensä Phikol Abrahamille, sanoen: Jumala on sinun kanssas kaikissa mitä sinä teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Niin vanno nyt minulle tässä Jumalan kautta, ettes ole minulle, ja minun pojalleni, ja poikanipojalle petollinen; vaan sen laupiuden jälkeen, jonka minä tein sinun kanssas, tee sinä myös minun kanssani, ja sen maan kanssa, jossa sinä olet muukalainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Niin sanoi Abraham: minä vannon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Ja Abraham nuhteli Abimelekiä, sen vesikaivon tähden, kun Abimelekin palveliat olivat väkivallalla ottaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Ja Abimelek sanoi: en ole minä tietänyt kuka sen teki; etkä sinä ilmoittanut minulle; enkä minä sitä ole ennen kuullut, kuin tänä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Niin otti Abraham lampaita ja karjaa, ja antoi Abimelekille; ja he tekivät molemmat liiton keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Ja Abraham asetti seitsemän karitsaa laumasta erinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Ja Abimelek sanoi Abrahamille: mihinkä ne seitsemän karitsaa, jotkas olet asettanut erinänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Hän vastasi: nämät seitsemän karitsaa pitää sinun ottaman minun kädestäni, todistukseksi minulle, että minä olen tämän kaivon kaivanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Sentähden kutsui hän sen sian BerSaba: sillä siinä he molemmat vannoivat keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Ja niin he tekivät liiton BerSabassa. Ja Abimelek nousi ja Phikol hänen sotapäämiehensä, ja palasivat Philistealaisten maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Ja Abraham istutti puita BerSabassa; ja saarnasi siinä Herran ijankaikkisen Jumalan nimestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Ja oli muukalainen Philistealaisten maalla kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Ja koska se oli tapahtunut, koetteli Jumala Abrahamia, ja sanoi hänelle: Abraham. Ja hän vastasi: Katso, tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Ja hän sanoi: ota nyt Isaak sinun ainoa poikas, jotas rakastat, ja mene Morian maalle; ja uhraa häntä siellä polttouhriksi yhdellä niistä vuorista, jonka minä sinulle sanova olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Niin Abraham nousi varhain aamulla, ja valjasti aasinsa, ja otti kaksi palveliaansa kanssansa, ja poikansa Isaakin; ja halkoili puita polttouhriin, ja valmisti itsensä, ja meni sille paikalle, minkä Jumala oli hänelle sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Kolmantena päivänä nosti Abraham silmänsä, ja näki sen paikan taampana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Silloin Abraham sanoi palvelioillensa: olkaat te tässä itseksenne aasin tykönä; mutta minä ja poika käymme tuonne. Ja koska me olemme rukoilleet, niin me palajamme teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Ja Abraham otti polttouhrin halvot, ja sälytti poikansa Isaakin selkään, vaan itse hän otti tulen ja veitsen käteensä; ja he kävivät molemmat ynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Niin sanoi Isaak isällensä Abrahamille: minun isäni. Hän vastasi: katso, tässä minä olen, poikani. Ja hän sanoi: katso, tässä on tuli ja halvot; mutta kussa on lammas polttouhriksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham vastasi: Jumala on edeskatsova itsellensä lampaan polttouhriksi, poikani. Ja he kävivät molemmat ynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Ja kuin he tulivat sille paikalle, josta Jumala oli hänelle sanonut, teki Abraham siihen alttarin, ja pani halvot; ja sitoi poikansa Isaakin, ja pani hänen alttarille halkoin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Ja ojensi kätensä, ja sivalsi veitsen, teurastaaksensa poikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Niin Herran enkeli huusi häntä taivaasta, sanoen: Abraham, Abraham. Hän vastasi: tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Hän sanoi: älä satuta kättäs poikaan, älä myös hänelle mitään tee: sillä nyt minä tiedän, että sinä pelkäät Jumalaa, ja et ole säästänyt ainokaista poikaas minun tähteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Niin Abraham nosti silmänsä, ja äkkäsi oinaan takanansa, sarvista sekaantuneena tihkiään pensastoon. Niin Abraham meni, ja otti oinaan ja uhrasi polttouhriksi poikansa edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Ja Abraham nimitti sen paikan, Herra on edeskatsova: josta vielä tänäpänä sanotaan, Herran vuorella edeskatsotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Mutta Herran enkeli huusi Abrahamia toistamiseen taivaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Ja sanoi: Minä olen vannonut itse kauttani, sanoo Herra: ettäs tämän teit, ja et säästänyt sinun ainoaa poikaas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Niin minä suuresti siunaan sinun, ja runsaasti lisään sinun siemenes niinkuin taivaan tähdet, ja niinkuin sannan meren reunalla. Ja sinun siemenes on perivä vihollistensa portit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Ja sinun siemenessäs pitää kaikki kansat maan päällä siunatuksi tuleman, ettäs minun äänelleni kuuliainen olit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Sitte palasi Abraham palveliainsa tykö, ja he nousivat, ja ynnä matkustivat BerSabaan. Ja Abraham asui BerSabassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Ja koska nämät olivat tapahtuneet, ilmoitettiin Abrahamille sanoen: katso, Milka on myös synnyttänyt poikia sinun veljelles Nahorille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Esikoisensa Utsin, ja Butsin hänen veljensä, ja Kemuelin Aramin isän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Ja Kesedin ja Hasonin, ja Pildaksen ja Jedlaphen, ja Betuelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Mutta Betuel siitti Rebekan. Nämät kahdeksan synnytti Milka Nahorille Abrahamin veljelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Mutta hänen jalkavaimonsa, Rehuma nimeltä, synnytti Teban, Gahamin, Tehaksen ja Maakan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Ja Saaran elinaika oli sata ja seitsemänkolmattakymmentä ajastaikaa: ne olivat Saaran ikävuodet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Ja Saara kuoli Arban kaupungissa, joka (on) Hebron Kanaanin maalla. Niin tuli Abraham murehtimaan Saaraa ja itkemään häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Sitte nousi hän kuolleensa tyköä; ja puhui Hetin lapsille sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Minä olen muukalainen ja kuitenkin asuvainen teidän tykönänne, antakaat minulle perintöhauta teidän tykönänne, haudatakseni minun kuolleeni, joka on minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Niin vastasivat Hetin lapset Abrahamia, sanoen hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Kuule meitä, rakas herra: sinä olet Jumalan ruhtinas meidän seassamme, hautaa sinun kuollees meidän parhaisiin hautoihimme: ei yksikään meistä sinua kiellä hautaamasta kuolluttas hänen hautaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Niin Abraham nousi ja kumarsi itsensä maan kansan edessä, (nimittäin) Hetin lasten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Ja hän puhui heille, sanoen: jos teidän mielenne on, että minä hautaan minun kuolleeni, joka minun edessäni on; niin kuulkaat minua, ja rukoilkaat minun edestäni Ephronia Zoarin poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Että hän antais minulle Makpelan luolan, joka hänellä on, vainionsa perällä: täyden hinnan edestä antakaan sen minulle teidän keskellänne perintöhaudaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Sillä Ephron asui Hetin lasten seassa. Niin vastasi Ephron Hetiläinen Abrahamia, Hetin poikain kuullen, kaikkein sisälle ja ulos käyväisten hänen kaupunkinsa portista, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Ei, minun herrani, vaan kuule minua; vainion minä annan sinulle, ja luolan, joka siinä on, annan minä sinulle: minun kansani lasten nähden annan minä sen sinulle; hautaa kuollees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Abraham kumarsi maan kansan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Ja puhui Ephronille maan kansan kuullen, sanoen: jos sinä minua kuulet: minä annan rahan vainion edestä, ota se minulta, ja minä hautaan minun kuolleeni siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Ephron vastasi Abrahamia, sanoen hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Minun herrani, kuule minua: maa maksaa neljäsataa sikliä hopiaa; vaan mitä se on minun ja sinun välilläs? hautaa sinun kuollees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Abraham kuuli Ephronia, ja punnitsi hänelle rahan, jonka hän nimittänyt oli Hetin lasten kuullen: neljäsataa sikliä hopiaa, käypää rahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Ja niin vahvistettiin Ephronin vainio, joka Makpelassa on Mamren kohdalla, sekä pelto että luola joka siinä on, ja kaikki puut siinä vainiossa, jotka ympäri kaikissa sen rajoissa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, '(Kaikki ne tulivat) Abrahamille omaisuudeksi Hetin lasten nähden: kaikkein (nähden), jotka sisällekävivät hänen kaupunkinsa portista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Ja sitte hautasi Abraham emäntänsä Saaran siihen luolaan, joka oli Makpelan vainiossa Mamren kohdalla; se on Hebron Kanaanin maalla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Niin vahvistettiin siis vainio ja luola, joka siinä oli, Abrahamille perintöhaudaksi, Hetin lapsilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Ja Abraham oli vanha ja joutunut ijälliseksi: ja Herra oli siunannut hänen kaikissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Niin sanoi Abraham vanhimmalle huoneensa palvelialle, joka kaikki hallitsi, mitä hänellä oli: laske nyt kätes minun kupeeni alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Ja minä vannotan sinua Herran taivaan ja maan Jumalan kautta; ettes ota emäntää minun pojalleni Kanaanealaisten tyttäristä, joiden seassa minä asun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Vaan mene minun isäni maalle ja minun sukuni tykö; ja ota minun pojalleni Isaakille emäntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Ja palvelia sanoi: jos niin tapahtuis, ettei vaimo tahtoisi seurata minua tähän maahan: pitääkö minun kumminkin viemän jällensä sinun poikas sille maalle, jostas lähtenyt olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham sanoi hänelle: kavahda sinuas, ettes vie minun poikaani sinne jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Herra taivaan Jumala, joka minun otti isäni huoneesta ja syntymä-maaltani, ja joka minun kanssani puhui, ja myös vannoi minulle, sanoen: sinun siemenelles minä annan tämän maan: hän lähettää enkelinsä sinun edelläs, ettäs ottaisit minun pojalleni emännän sieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Jos ei vaimo tahtoisi seurata sinua, niin sinä olet vapaa tästä minun valastani; ainoastansa älä vie minun poikaani sinne jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Niin laski palvelia kätensä herransa Abrahamin kupeen alle; ja vannoi hänelle sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Niin otti palvelia kymmenen kamelia herransa kameleista, ja läksi matkaan, ja otti myötänsä kaikkinaisesta herransa tavarasta: ja vaelsi Mesopotamiaan Nahorin kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Ja hän antoi kamelein laskea polvillensa ulkona kaupungista vesikaivon tykönä; ehtoopuolella, jolla ajalla vaimoväen tapa oli lähteä vettä ammuntamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Ja sanoi: Herra, minun herrani Abrahamin Jumala, anna minun kohdata tänäpänä (herrani morsiamen); ja tee laupius minun herrani Abrahamin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Katso, minä seison tässä vesikaivon tykönä: ja heidän tyttärensä, jotka asuvat tässä kaupungissa, tulevat vettä ammuntamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Jos joku piika tulee, jolle minä sanon: kallista tänne vesiastias juodakseni, ja hän sanoo: juo, minä juotan myös sinun kamelis: että hän on se, jonkas olet edeskatsonut palvelialles Isaakille, ja siitä ymmärtäisin tehnees laupiuden minun herrani kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Ja ennenkuin hän lakkasi puhumasta, katso, Rebekka tuli, joka syntynyt oli Betuelille, Milkan, Abrahamin veljen Nahorin emännän pojalle. Ja hänellä vesiastiansa olallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Ja piika oli sangen ihana nähdä, ja vielä neitsy, ja ei yksikään mies ollut häneen ryhtynyt: hän meni alas kaivon tykö, ja täytti astiansa, ja tuli ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Niin palvelia juoksi häntä vastaan, ja sanoi: annas minun juoda vähä vettä astiastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Hän sanoi: juo minun herrani: ja hän kiiruusti laski alas vesiastiansa kätensä päälle, ja antoi hänen juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Ja kuin hän oli antanut hänen juoda, sanoi hän: minä myös ammunnan vettä kameleilles, niinkauvan että he kaikki saavat juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Ja hän kaasi kohta veden astiastansa ruuheen, ja juoksi taas kaivolle ammuntamaan: ja ammunsi kaikille hänen kameleillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Mutta mies ihmetteli häntä: ja oli ääneti, ja tahtoi tietää, jos Herra oli tehnyt hänen matkansa onnelliseksi, taikka ei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Ja koska kaikki kamelit olivat juoneet, antoi mies hänelle kulta-otsalehden, joka painoi puolen sikliä: niin myös kaksi rannerengasta hänen käsiinsä, jotka painoivat kymmenen sikliä kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Ja sanoi: kenenkäs tytär olet? sanos minulle se: onko isäs huoneessa siaa meidän yötä ollaksemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Hän sanoi hänelle: minä olen Betuelin, Milkan pojan, tytär, jonka hän synnytti Nahorille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Ja hän vielä sanoi hänelle: on myös olkia ja karjan ruokaa kyllä meillä: ja myös siaa yötä olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Ja mies kumarsi maahan ja rukoili Herraa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Ja sanoi: kiitetty olkoon Herra, minun herrani Abrahamin Jumala, joka ei ottanut pois laupiuttansa ja totuuttansa minun herraltani: minua on Herra johdattanut tällä tiellä, minun herrani veljen huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Niin piika juoksi ja ilmoitti nämät asiat äitinsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Oli myös Rebekalla veli, jonka nimi oli Laban: ja Laban juoksi miehen tykö lähteelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Sillä koska hän näki otsalehden ja rannerenkaat sisarensa käsissä, ja kuuli sisarensa Rebekan puheet, sanovan: näin on mies puhunut minulle; tuli hän miehen tykö, ja katso, hän seisoi kamelein tykönä lähteellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Ja sanoi: tule sisälle, sinä Herran siunattu, mitäs seisot ulkona? minä olen huoneen valmistanut, ja sian kameleille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Niin meni mies huoneesen, ja riisui kamelit: ja hän antoi olkia ja ruokaa kameleille, ja vettä pestä hänen jalkojansa, ja miesten jalkoja, jotka hänen kanssansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Sitte pantiin ruokaa hänen eteensä: mutta hän sanoi: en minä syö ennenkuin minä olen puhunut minun asiani. He vastasivat: puhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Hän sanoi: minä olen Abrahamin palvelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Ja Herra on runsaasti siunannut minun herrani, ja hän on suureksi tullut, ja on antanut hänelle lampaita ja karjaa, hopiaa ja kultaa, palvelioita ja piikoja, kameleja ja aaseja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Niin myös Saara minun herrani emäntä on synnyttänyt minun herralleni pojan, vanhalla ijällänsä: hänelle on hän antanut kaikki mitä hänellä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Ja minun herrani vannotti minua, sanoen: ei sinun pidä ottaman minun pojalleni emäntää Kanaanealaisten tyttäristä, joiden maalla minä asun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Vaan mene minun isäni huoneesen, ja minun sukuni tykö; ja ota (sieltä) minun pojalleni emäntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Mutta minä sanoin minun herralleni: taitais tapahtua, ettei vaimo seuraisi minua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Niin hän sanoi minulle: Herra, jonka edessä minä vaellan, lähettää enkelinsä sinun kanssas, joka tekee sinun matkas onnelliseksi, ottamaan minun pojalleni emäntä minun suvustani ja minun isäni huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Silloin sinä tulet vapaaksi minun valastani, koskas tulet minun sukuni tykö: ja jos ei he anna sinulle, niin sinä olet vapaa valastani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Niin tulin minä tänäpänä lähteelle, ja sanoin: Herra, minun herrani Abrahamin Jumala, jos sinä olet tehnyt minun matkani onnelliseksi, jota minä nyt vaellan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Katso, niin seison minä tässä vesilähteen tykönä: koska yksi piika tulee vettä ammuntamaan, ja minä sanon hänelle: annas minulle vähä vettä juoda astiastas:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Ja hän sanoo minulle: juo sinä, minä ammunnan myös sinun kameleilles: se on se vaimo, jonka Herra on edeskatsonut minun herrani pojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'En minä vielä päässyt puhumasta sydämessäni, katso, niin Rebekka tuli, ja hänen vesiastiansa hänen olallansa, astui alas lähteelle ja ammunsi: ja minä sanoin hänelle: annas minun juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Ja hän riensi ja laski vesiastian olaltansa alas, ja sanoi: juo, minä juotan myös kamelis. Niin minä join, ja hän juotti myös kamelit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Ja minä kysyin häneltä, ja sanoin: kenekä tytär sinä olet? hän vastasi: minä olen Betuelin tytär, Nahorin pojan, jonka Milka hänelle synnytti. Niin minä panin otsalehden hänen otsaansa, ja rannerenkaat hänen käsiinsä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Ja kumarsin itseni maahan ja rukoilin Herraa: ja kiitin Herraa, minun herrani Abrahamin Jumalaa, joka minun oli johdattanut oikiaa tietä, ottamaan hänen pojallensa minun herrani veljen tytärtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Ja nyt, jos te olette ne, jotka osotatte minun herralleni laupiuden ja totuuden, niin sanokaat minulle: ja jos ei, niin sanokaat myös minulle, että minä kääntäisin itseni oikialle taikka vasemmalle puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Niin vastasi Laban ja Betuel, ja sanoivat: tämä asia on tullut Herralta; sentähden emme taida sinua vastaan puhua, pahaa taikka hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Siinä on Rebekka edessäs, ota häntä ja mene, ja olkaan sinun herras pojan emäntä, niinkuin Herra on sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Ja koska Abrahamin palvelia kuuli heidän sanansa; kumarsi hän maahan Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Ja palvelia toi hopia- ja kultakalut, ja vaatteet, ja antoi Rebekalle: vaan hänen veljellensä ja äidillensä antoi hän (muita) kalleita kaluja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Niin he söivät ja joivat, hän ja miehet, jotka hänen kanssansa olivat, ja siellä pitivät yötä: ja he nousivat aamulla varhain: ja hän sanoi: päästäkäät minua herrani tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Mutta hänen veljensä ja äitinsä sanoivat: olkaan piika meidän tykönämme edes kymmenenkin päivää: sitte sinä saat mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Niin sanoi hän heille: älkäät viivyttäkö minua: sillä Herra on tehnyt minun matkani onnelliseksi: laskekaat minua menemään minun herrani tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Niin he sanoivat: kutsukaamme piika, ja kysykäämme mitä hän sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Ja he kutsuivat Rebekan, ja sanoivat hänelle: tahdotkos mennä tämän miehen kanssa? hän vastasi: menen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Niin he laskivat sisarensa Rebekan menemään, ja hänen imettäjänsä, Abrahamin palvelian kanssa; ja ne jotka hänen seurassansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Ja he siunasivat Rebekkaa ja sanoivat hänelle: sinä olet meidän sisaremme, lisäänny tuhannen tuhanteen; ja sinun siemenes omistakoon vihamiestensä portit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Niin Rebekka nousi piikoinensa, ja istuivat kamelein päälle, ja seurasivat sitä miestä. Ja palvelia otti Rebekan, ja meni matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Mutta Isaak palasi siltä kaivolta, joka kutsuttiin sen elävän, joka minun näkee: sillä hän asui etelän maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Ja oli lähtenyt rukoilemaan kedolle ehtoopuolella: ja nosti silmänsä, ja näki, ja katso, kamelit lähestyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Ja Rebekka nosti silmänsä ja näki Isaakin: ja pudotti itsensä maahan kamelin päältä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Ja sanoi palvelialle: mikä mies tämä on, joka kedolla käy meitä vastaan? palvelia vastasi: se on minun herrani: niin hän otti vaatteen ja peitti itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Ja palvelia jutteli Isaakille kaiken asian, kuin hän oli toimittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Ja Isaak vei hänen äitinsä Saaran majaan: ja otti Rebekan emännäksensä, ja rakasti häntä: ja niin Isaak lohdutettiin äitinsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Ja Abraham taas otti emännän nimeltä Ketura.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Hän synnytti hänelle Simran ja Joksan, ja Medan ja Midian, ja Jesbakin ja Suan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Mutta Joksan siitti Seban ja Dedanin. Dedanin lapset olivat: Asserim, Letusin ja Luumim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Midianin lapset olivat: Epha, Epher, Hanok, Abida, ja Eldaa: nämät kaikki ovat Keturan pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Ja Abraham antoi kaikki mitä hänellä oli Iisakille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Mutta niille lapsille, jotka jalkavaimoista olivat, antoi hän lahjoja, ja lähetti heidät pois poikansa Isaakin tyköä, vielä eläissänsä, idän puoleen, itäiselle maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Ja tämä on Abrahamin elinaika, kuin hän eli: sata ja viisikahdeksattakymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Ja hän tuli riutuneeksi, ja kuoli levollisessa ijässä, vanhana ja elämästä kyllänsä saanut: ja koottiin kansansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Ja hänen poikansa Isaak ja Ismael hautasivat hänen Makpelan luolaan: Ephronin Hetiläisen Zoarin pojan vainiossa, Mamren kohdalle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Sille kedolle, jonka Abraham oli ostanut Hetin lapsilta: siihen on Abraham haudattu, ja Saara hänen emäntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Ja Abrahamin kuoleman jälkeen siunasi Jumala hänen poikansa Isaakin: Ja Isaak asui sen elävän, joka minun näkee, kaivon tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Mutta nämät ovat Ismaelin Abrahamin pojan sukukunnat, jonka Hagar Egyptiläinen Saaran piika synnytti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Ja nämä ovat Ismaelin poikain nimet, heidän nimeinsä ja sukukuntainsa jälkeen: Ismaelin esikoinen oli Nebaot, Kedar, Abdeel, Mibsam,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duma, Masa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, Tema, Jetur, Naphis ja Kedma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Nämät ovat Ismaelin lapset, ja nämät heidän nimensä, heidän kylissänsä ja kaupungeissansa: kaksitoistakymmentä ruhtinasta heidän kansoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Ja tämä on Ismaelin ikä: sata ja seitsemänneljättäkymmentä ajastaikaa: ja hän tuli riutuneeksi, ja kuoli, ja koottiin kansansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Mutta he asuivat Hevilasta hamaan Surriin asti, joka on Egyptin kohdalla Assyriaan mentäissä. Kaikkein hänen veljeinsä kohdalle lankesi (hänen arpansa).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Ja nämät ovat Isaakin Abrahamin pojan sukukunnat: Abraham siitti Isaakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Ja Isaak oli neljänkymmenen ajastaikainen, koska hän otti Rebekan Betuelin Syrialaisen tyttären Mesopotamiasta, Labanin syrialaisen sisaren, itsellensä emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Ja Isaak rukoili Herraa emäntänsä edestä; sillä hän oli hedelmätöin, ja Herra kuuli häntä: niin Rebekka hänen emäntänsä tuli raskaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Ja lapset sysäsivät toinen toistansa hänen kohdussansa. Niin hän sanoi: jos näin piti käymän, miksi minä olen (raskaaksi tullut?) ja meni kysymään Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Ja Herra sanoi hänelle: kaksi kansaa ovat sinun kohdussas, ja kahtalainen väki erkanee sinun ruumiistas: mutta toinen kansa voittaa toisen, ja suurempi palvelee vähempää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Koska aika tuli synnyttää; katso, kaksoiset olivat hänen kohdussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Ensimäinen joka tuli ulos, oli ruskia ja karvainen niinkuin vaate: sentähden kutsuivat he hänen nimensä Esau.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Senjälkeen tuli ulos hänen veljensä, joka piti kädellänsä Esaun kantapäästä, ja se kutsuivat hänen nimensä Jakob. Kuudenkymmenen ajastaikainen oli Isaak heidän syntyissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Ja poikaiset kasvoivat, ja Esau tuli jaloksi metsä- ja peltomieheksi. Mutta Jakob oli yksivakainen mies, ja asui majoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Ja Isaak rakasti Esauta; sillä hän söi mielellänsä hänen metsäsaalistansa. Mutta Rebekka rakasti Jakobia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Koska Jakob oli keittänyt herkun, tuli Esau metsästä, ja oli väsyksissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Ja Esau sanoi Jakobille: anna minun syödä tästä ruskiasta herkusta: sillä minä olen väsyksissä. Sentähden kutsutaan hänen nimensä Edom.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Mutta Jakob sanoi: myy minulle tänäpänä sinun esikoisuutes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esau vastasi: katso, minä kuolen kuitenkin; mitä minun esikoisuudesta on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Ja Jakob sanoi: niin vanno minulle tänäpänä: ja hän vannoi hänelle, ja myi Jakobille esikoisuutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Niin Jakob antoi Esaulle leivän, ja sen ruskian herneherkun, ja hän söi ja joi, ja nousi ja meni pois. Ja niin Esau katsoi esikoisuutensa ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Niin kallis aika tuli maalle sen entisen jälkeen, joka oli Abrahamin ajalla: ja Isaak meni Abimelekin Philistealaisten kuninkaan tykö Gerariin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Niin Herra ilmestyi hänelle, ja sanoi: älä mene Egyptiin, vaan asu sillä maalla, jonka minä sanon sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Ole muukalainen tällä maalla, ja minä olen sinun kanssas, ja siunaan sinua: sillä sinulle ja sinun siemenelles minä annan kaikki nämät maat, ja vahvistan sen valan, jonka minä Abrahamille sinun isälles vannonut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Ja enennän sinun siemenes niinkuin taivaan tähdet: ja annan sinun siemenelles kaikki nämät maat: Ja sinun siemenes kautta pitää kaikki kansat maan päällä siunatuksi tuleman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Sillä Abraham oli kuuliainen minun äänelleni, ja piti minun oikeuteni, käskyni, säätyni ja lakini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Niin Isaak asui Gerarissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Ja koska sen maan kansa kysyi hänen emännästänsä, sanoi hän: hän on minun sisareni; sillä hän pelkäsi sanoa: hän on minun emäntäni (ajatellen), ettei he joskus löisi minua kuoliaksi Rebekan tähden: sillä hän oli ihana kasvoilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Ja tapahtui, koska hän siellä kappaleen aikaa viipyi, katsoi Abimelek Philistealaisten kuningas akkunasta, ja näki Isaakin hyväilevän emäntäänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Niin kutsui Abimelek Isaakin, ja sanoi: katso, totisesti hän on sinun emäntäs: miksis olet sanonut: hän on minun sisareni? Ja Isaak sanoi hänelle: minä ajattelin, etten minä tapettaisi hänen tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelek sanoi: miksis tämän meille teit? olis pikaisesti tapahtunut, että joku kansasta olis maannut sinun emäntäs kanssa, ja niin sinä olisit saattanut meidän päällemme rikoksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Niin Abimelek antoi käskyn kaikelle kansalle, sanoen: joka ryhtyy tähän mieheen, tahi hänen emäntäänsä, hänen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Ja Isaak kylvi sillä maalla, ja sai sinä vuonna satakertaisesti: sillä Herra siunasi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Ja mies tuli voimalliseksi: ja menestyi sangen suuresti siihen asti, että hän juuri suureksi joutui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Ja hänellä oli paljo tavaraa lampaissa ja karjassa, oli myös paljo perhettä: sentähden Philistealaiset kadehtivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Ja he tukitsivat kaikki kaivot, jotka hänen isänsä palveliat olivat kaivaneet, hänen isänsä Abrahamin aikana, ja täyttivät ne mullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Ja Abimelek sanoi Isaakille: mene pois meidän tyköämme: sillä sinä olet tullut paljo väkevämmäksi meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Niin Isaak läksi sieltä: ja teki majansa Gerarin laaksoon, ja asui siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Ja Isaak antoi jällensä kaivaa ne vesikaivot, jotka he olivat kaivaneet hänen isänsä Abrahamin aikana, ja jotka Philistealaiset Abrahamin kuoleman jälkeen olivat tukinneet: ja nimitti ne niillä nimillä, joilla hänen isänsä ne kutsunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Niin kaivoivat myös Isaakin palveliat siihen laaksoon: ja löysivät sieltä luontolähteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Mutta Gerarin paimenet riitelivät Isaakin paimenten kanssa, ja sanoivat: tämä on meidän vetemme. Niin hän kutsui sen kaivon Esek, että he riitelivät hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Niin kaivoivat he myös toisen kaivon, ja he riitelivät myös siitä: niin hän nimitti sen Sitna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Niin hän siirsi itsensä sieltä, ja kaivoi toisen kaivon, josta ei he riidelleet. Sen tähden nimitti hän sen Rehobot, ja sanoi: nyt Herra on antanut meille laviamman sian, ja on antanut meidän kasvaa maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Sitte meni hän BerSabaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Niin Herra ilmestyi hänelle sinä yönä ja sanoi: minä olen sinun isäs Abrahamin Jumala: älä pelkää, sillä minä olen kanssas, ja siunaan sinun, ja annan lisääntyä sinun siemenes, minun palveliani Abrahamin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Ja hän rakensi siinä alttarin, ja saarnasi Herran nimestä, ja teki siihen majansa: ja hänen palveliansa kaivoivat siihen kaivon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Niin Abimelek meni hänen tykönsä Gerarista: ja Ahusat hänen ystävänsä, ja Phikol hänen sotajoukkonsa päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Mutta Isaak sanoi heille: miksi te tulitte minun tyköni: ja te vainositte minua, ja ajoitte minun pois teidän tyköänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'He sanoivat: me näimme ilmeissänsä, että Herra on sinun kanssas, sentähden me sanoimme: olkoon nyt vala meidän molempain vaiheellamme, meidän ja sinun välilläs, ja me teemme liiton sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Ettes tekisi meille mitään vahinkoa, niinkuin emme mekään ole sinuun ryhtyneet, ja niinkuin emme myös tehneet sinulle muuta kuin hyvää, ja laskimme sinun rauhassa menemään. Sinä olet nyt Herran siunattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Ja hän valmisti heille pidon, ja he söivät ja joivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Ja nousivat aamulla varhain, ja vannoivat toinen toisellensa, ja Isaak laski heidät menemään, ja menivät pois hänen tyköänsä rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Sinä samana päivänä tulivat Isaakin palveliat, ja ilmoittivat hänelle kaivosta, jonka he kaivaneet olivat, ja sanoivat hänelle: me löysimme veden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Ja hän kutsui hänen Saba: siltä nimitetään kaupunki BerSaba, hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Koska Esau oli neljänkymmenen ajastaikainen, otti hän Juditin Hetiläisen Berin tyttären emännäksensä: Ja Basmatin Hetiläisen Elonin tyttären:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Jotka olivat Isaakille ja Rebekalle mielikarvaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Ja tapahtui, koska Isaak tuli vanhaksi, ja hänen silmänsä pimiäksi, ettei hän nähnyt, niin kutsui hän Esaun vanhemman poikansa, ja sanoi hänelle: minun poikani: hän vastasi häntä: tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Ja hän sanoi: katso, minä olen vanhennut: enkä tiedä minun kuolemanpäivääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Ota siis nyt sinun kalus, viines ja joutses; ja mene kedolle, ja pyydä minulle metsän-otus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Ja tee minulle himoruokaa, senkaltaista jota minä rakastan, ja tuo syödäkseni: että minun sieluni siunais sinua, ennenkuin minä kuolen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Mutta Rebekka kuuli Isaakin näitä puhuvan poikansa Esaun kanssa. Ja Esau meni metsään, pyytämään metsänotusta, tuodaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Niin puhui Rebekka pojallensa Jakobille, sanoen: katso, minä kuulin isäs puhuvan veljes Esaun kanssa, ja sanovan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Tuo minulle metsänotus, ja tee minulle himoruokaa syödäkseni; että siunaisin sinua Herran edessä, ennen kuin minä kuolen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Niin kuule nyt poikani minun ääneni, mitä minä sinulle käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Mene laumaan, ota sieltä minulle kaksi hyvää vohlaa; tehdäkseni isälles niistä himoruokaa, niinkuin hän rakastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Ja vie se isälles hänen syödäksensä; että hän siunais sinua, ennen kuin hän kuolee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Niin Jakob sanoi äidillensä Rebekalle: katso, veljeni Esau on karvainen, mutta minä olen paljas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Mitämaks, isäni sivelee minua, ja luulee minun häntä pettävän: ja minä saatan päälleni kirouksen, ja en siunausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Niin hänen äitinsä sanoi hänelle: sinun kiroukses tulkoon minun päälleni, minun poikani: ainoastansa ole minun äänelleni kuuliainen, mene ja tuo se minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Niin hän meni ja otti ja toi äidillensä; ja hänen äitinsä valmisti himoruan, jota hänen isänsä rakasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Ja Rebekka otti vanhemman poikansa Esaun parhaat vaatteet, jotka huoneessa hänen tykönänsä olivat: ja puetti nuoremman poikansa Jakobin niihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Vaan vohlain nahat kääri hän hänen käsiinsä, ja paljaaseen kaulaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Ja antoi sen himoruan ja leivän, kun hän valmistanut oli, poikansa Jakobin käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Ja hän tuli isänsä tykö, ja sanoi: minun isäni. Hän vastasi: tässä minä olen. Kukas olet, minun poikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakob sanoi isällensä: minä olen Esau sinun esikoises; minä olen niin tehnyt kuin sinä minulle käskit: nouse siis, istu, ja syö minun saalistani, että sinun sielus siunaisi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Mutta Isaak sanoi pojallensa: minun poikani, kuinkas olet niin nopiasti löytänyt? ja hän vastasi: Herra sinun Jumalas antoi minun sen kohdata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Niin sanoi Isaak Jakobille: tules tänne minun poikani sivelläkseni: jos olet minun poikani Esau taikka et.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Niin Jakob astui isäntä Isaakin tykö: ja kuin hän siveli häntä, sanoi hän: ääni on Jakobin ääni, mutta kädet ovat Esaun kädet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Ja ei tuntenut häntä: sillä hänen kätensä olivat niinkuin Esaun veljensä kädet, karvaiset: ja niin hän siunasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Ja sanoi hänelle: oletkos minun poikani Esau? hän vastasi: olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Niin hän sanoi: tuo siis tänne syödäkseni minun poikani saalista, että minun sieluni siunaisi sinua: niin hän toi sen hänelle, ja hän söi, toi myös hänelle viinaa, ja hän joi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Ja Isaak hänen isänsä sanoi hänelle: tules nyt liki, minun poikani, ja anna minun suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Ja hän astui liki, ja suuta antoi hänen. Niin hän tunsi hänen vaatteensa hajun, ja siunasi häntä, ja sanoi: katso, minun poikani haju, on niinkuin kedon haju, jonka Herra siunannut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Jumala antakoon sinulle taivaan kasteesta, ja maan lihavuudesta; yltäkyllä jyviä ja viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Kansat palvelkoon sinua, ja sukukunnat kumartakoon sinua. Ole sinun veljeis herra, ja sinun äitis lapset langetkoon sinun jalkais juureen: kirottu olkoon se, joka sinua kiroo, ja siunattu olkoon se, joka sinua siunaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Koska Isaak oli päättänyt siunauksensa Jakobille, ja Jakob siitä siihen oli lähtenyt isänsä Isaakin tyköä; niin Esau hänen veljensä tuli pyydyksiltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Ja hän myös valmisti himoruan, ja vei isällensä, ja sanoi hänelle: nouskaan minun isäni, ja syökään poikansa saalista, että sinun sielus siunaisi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Niin vastasi Isaak hänen isänsä häntä: kukas olet? hän sanoi: minä olen sinun poikas, sinun esikoises Esau.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Niin Isaak vapisi hämmästyksestä sangen kovin, ja sanoi: kuka? kussasta siis se metsämies on, joka minulle sen toi? ja minä söin kaikista, ennen kuin sinä tulit ja minä siunasin hänen: hänen pitää myös siunatun oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Koska Esau kuuli isänsä puheen, huusi hän suurella äänellä, ja hänen mielensä tuli sangen karvaaksi: ja hän sanoi isällensä: siunaa myös minuakin, minun isäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Niin hän sanoi: sinun veljes on tullut kavaluudella, ja vienyt pois siunauksen sinulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Niin hän sanoi: eiköstä hän myös oikein kutsuta Jakob? sillä hän jo kahdesti minun on polkenut, minun esikoisuuteni hän sai, ja katso, nyt hän vei pois minun siunaukseni minulta: ja hän sanoi: etkös yhtäkään siunausta minun varakseni pitänyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Niin vastasi Isaak, ja sanoi Esaulle: Katso, minä olen asettanut hänen sinun herrakses, ja kaikki hänen veljensä olen minä hänelle palveliaksi pannut, jyvillä ja viinalla olen minä hänen varustanut: mitästä minä siis nyt sinulle teen, minun poikani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Ja Esau sanoi isällensä: yksiköstä siunaus sinulla vaivoin onkin, minun isäni? siunaa myös minuakin, minun isäni: ja Esau korotti äänensä ja itki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Niin vastasi Isaak, hänen isänsä, ja sanoi hänelle: Katso, lihava asuinsia pitää sinulla oleman maan päällä, ja kastetta taivaasta ylhäältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Sinun miekallas pitää sinun elättämän itses, ja palveleman sinun veljeäs. Ja tapahtuu, että sinä myös tulet herraksi, ja särjet hänen ikeensä niskastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Ja Esau vihastui Jakobin päälle siunauksen tähden, jolla hänen isänsä hänen siunannut oli; ja sanoi sydämessänsä: minun isäni murhepäivät lähestyvät: ja minä tapan veljeni Jakobin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Mutta Rebekalle ilmoitettiin Esaun hänen vanhemman poikansa sanat: joka lähetti ja kutsui Jakobin nuoremman poikansa, ja sanoi hänelle: katso, veljes Esau lohduttaa itsiänsä siitä, että hän sinun tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Nyt, minun poikani, ole minun äänelleni kuuliainen: valmista sinus ja pakene kohta minun veljeni Labanin tykö Haraniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Ja ole hänen tykönänsä kappale aikaa: siihenasti että veljes kiukku asettuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Ja siihenasti että hänen vihansa lakkaa sinusta, ja hän unhottaa mitäs häntä vastaan tehnyt olet. Niin minä lähetän ja tuotan sinun sieltä. Miksi teidän molempain pitäis yhtenä päivänä minulta tuleman pois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Ja Rebekka sanoi Isaakille: minä suutun minun elämääni, Hetin tytärten tähden: jos Jakob ottaa vaimon Hetin tyttäristä, jotka ovat niinkuin tämän maan tyttäret, mitä minun sitte auttaa elämään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Niin Isaak kutsui poikansa Jakobin ja siunasi häntä, käski ja sanoi hänelle: älä ota emäntää Kanaanin tyttäristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Vaan valmista ja mene Mesopotamiaan, Betuelin sinun äitis isän huoneesen: ja ota sinulles sieltä emäntä, Labanin sinun enos tyttäristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Ja Jumala kaikkivaltias siunatkoon sinua, ja tehköön sinun hedelmälliseksi ja enätköön sinun, ettäs tulisit (suureksi) kansain joukoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Antakoon myös sinulle Abrahamin siunauksen, sinulle ja sinun siemenelles sinun kanssas: periäkses sitä maata, jossas muukalainen olet, jonka Jumala Abrahamille antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Niin lähetti Isaak Jakobin tyköänsä menemään Mesopotamiaan, Labanin, Betuelin Syrialaisen pojan tykö, Rebekan, Jakobin ja Esaun äidin, veljen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Koska Esau näki, että Isaak oli siunannut Jakobin, ja lähettänyt hänen Mesopotamiaan ottamaan sieltä itsellensä emäntää: ja että hän, sittekuin hän hänen siunannut oli, käski häntä ja sanoi: ei sinun pidä ottaman emäntää Kanaanin tyttäristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Ja että Jakob oli isällensä ja äidillensä kuuliainen; ja meni Mesopotamiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Esau näki myös, ettei Isaak hänen isänsä voinut nähdä Kanaanin tyttäriä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Meni Esau Ismaelin tykö: ja otti Mahalatin Ismaelin Abrahamin pojan tyttären, Nabojotin sisaren, emännäksensä, paitsi entisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Niin Jakob läksi BerSabasta: ja meni Haraniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Ja joutui yhteen paikkaan, ja oli siinä yötä: sillä aurinko oli laskenut, ja otti kiven siitä paikasta, ja pani päänsä alaiseksi, ja makasi siinä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Ja näki unta, ja katso, tikapuut seisoivat maan päällä, joiden pää ulottui taivaasen: ja katso, Jumalan enkelit kävivät ylös ja alas niitä myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Ja katso, Herra seisoi niiden päällä, ja sanoi: Minä olen Herra, Abrahamin sinun isäs Jumala, ja Isaakin Jumala: tämän maan, jonka päällä sinä makaat, annan minä sinulle ja sinun siemenelles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Ja sinun siemenes pitää oleman niinkuin maan tomu, ja sinun pitää leviämän länteen ja itään, pohjaan ja etelään päin. Ja sinussa pitää kaikki sukukunnat maan päällä siunatuksi tuleman, ja sinun siemenessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Ja katso, minä olen sinun kanssas, ja varjelen sinua, kuhunkas ikänänsä joudut, ja saatan sinun jällensä tälle maalle: sillä en minä hylkää sinua siihenasti, että minä kaikki teen, mitä minä sinulle puhunut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Koska Jakob heräsi unestansa, niin hän sanoi: totisesti on Herra tässä paikassa: ja en minä sitä tietänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Niin hän pelkäsi, ja sanoi: kuinka peljättävä on tämä paikka! ei tässä muu ole kuin Jumalan huone ja taivaan ovi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Ja Jakob nousi varhain aamulla, ja otti kiven, jonka hän oli pannut päänsä alaiseksi, ja pani sen pystyälle muistopatsaaksi: ja vuodatti öljyä sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Kutsui siis sen paikan BetEl; vaan muinaisiin aikoin se kutsuttiin Luts.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Niin Jakob teki lupauksen, sanoen: jos Jumala on minun kanssani, ja varjelee minua tällä tiellä, jota minä vaellan, antaa myös minulle leipää syödäkseni, ja vaatetta verhokseni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Ja tulen takaperin rauhassa kotia isäni tykö: ja Herra on minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Niin tämä kivi, jonka minä panin pystyälle muistopatsaaksi, pitää oleman Jumalan huone: ja kaikista, jotkas minulle annat, annan minä tosin sinulle kymmenykset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Niin Jakob läksi matkaan: ja tuli itäiselle maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Ja katseli ympärillensä, ja katso, kaivo oli kedolla. Ja katso, siellä makasi myös kolme lammaslaumaa sen tykönä, sillä siitä kaivosta juottivat he laumat: ja suuri kivi oli kaivon suulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Sillä sinne koottiin kaikki laumat, ja vieritettiin kivi kaivon suulta, ja he juottivat lampaita: ja vierittivät kiven jälleen siallensa kaivon suulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Ja Jakob sanoi heille: minun veljeni, kusta te olette? he vastasivat: Haranista me olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Hän sanoi heille: tunnetteko Labanin, Nahorin pojan? he sanoivat: tunnemme kyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Hän sanoi: onko hän rauhassa? he vastasivat: rauhassa hän on. Ja katso, Rakel hänen tyttärensä tulee lammasten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Niin hän sanoi: katso, vielä on paljo päivää, eikä vielä ole aika karjaa koota: niin juottakaat siis lampaita, menkäät ja kaitkaat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'He sanoivat: emme saa siihenasti kuin kaikki laumat kootaan, ja vieritämme kiven kaivon suulta, juottaaksemme lampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Vielä hänen puhuissansa heidän kanssansa, tuli Rakel isänsä lammasten kanssa: sillä hän kaitsi lampaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Ja tapahtui, koska Jakob näki Rakelin enonsa Labanin tyttären, ja enonsa Labanin lampaat: niin meni Jakob hänen tykönsä, ja vieritti kiven kaivon suulta. Ja juotti enonsa Labanin lampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Ja Jakob suuta antoi Rakelin: ja korotti äänensä ja itki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Ja ilmoitti hänelle, että hän oli hänen isänsä veli, Rebekan poika. Niin juoksi hän ja ilmoitti sen isällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Ja koska Laban kuuli sanoman Jakobista sisarensa pojasta, juoksi hän häntä vastaan, ja otti hänen syliinsä, ja suuta antoi hänen, ja vei hänen huoneesensa: ja hän jutteli Labanille kaiken asian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Niin sanoi Laban hänelle: tosin sinä olet minun luuni ja lihani. Ja hän oli hänen tykönänsä koko kuukauden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Sitte sanoi Laban Jakobille: vaikkas olet minun veljeni, palveletkos sentähden minua ilman mitäkään? ilmoita minulle, mikä sinun palkkas olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Ja Labanilla oli kaksi tytärtä: vanhemman nimi oli Lea, ja nuoremman nimi oli Rakel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Mutta Lea oli pehmiä silmistä; vaan Rakel oli kauniin muotoinen, ja ihana kasvoilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Ja Jakob rakasti Rakelia: ja sanoi: minä palvelen sinua seitsemän ajastaikaa Rakelin, sinun nuoremman tyttäres tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban vastasi: parempi on, että minä hänen annan sinulle, kuin jollekin toiselle: ole minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Niin palveli Jakob Rakelin tähden seitsemän ajastaikaa: ja ne olivat hänen silmissänsä niinkuin muutamat päivät, rakastaissansa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Ja Jakob sanoi Labanille: anna minun emäntäni minulle: sillä minun aikani on täytetty mennä hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Niin Laban kutsui kokoon kaiken sen paikkakunnan miehet, ja piti häät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Mutta ehtoona otti hän tyttärensä Lean, ja vei sen hänen tykönsä: ja hän makasi sen tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Ja Laban antoi tyttärellensä Lealle piikansa Silpan piiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Aamulla, katso, se oli Lea. Ja hän sanoi Labanille: miksis tämän minulle teit? enkö minä Rakelin tähden palvellut sinua? miksis minun petit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Vastasi Laban: ei niin ole meidän maan tapa, että nuorempi annetaan ennen vanhempaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Täytä tämän viikko; niin se myös sinulle annetaan, siitä palveluksesta kun sinä palvelet minua vielä toiset seitsemän ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Jakob teki niin, ja täytti hänen viikkonsa: ja hän antoi hänelle tyttärensä Rakelin emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Ja Laban antoi tyttärellensä Rakelille piikansa Bilhan, piiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Niin hän makasi myös Rakelin kanssa, ja piti Rakelin rakkaampana kuin Lean; ja palveli häntä vielä toiset seitsemän ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Ja koska Herra näki Lean katsottavan ylön, teki hän hänen hedelmälliseksi; mutta Rakel oli hedelmätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Niin Lea tuli raskaaksi, ja synnytti pojan, ja kutsui hänen nimensä Ruben, ja sanoi: Herra on katsonut minun ahdistukseni puoleen, nyt siis minun mieheni rakastaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Ja hän taas tuli raskaaksi, ja synnytti pojan, ja sanoi: Herra on kuullut minua katsottavan ylön, ja on myös tämän minulle antanut: ja kutsui hänen nimensä Simeon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Ja hän jälleen tuli raskaaksi ja synnytti pojan, ja sanoi: nyt taas minun mieheni pysyy minun tykönäni: sillä minä synnytin hänelle kolme poikaa. Sentähden hän kutsui hänen nimensä Levi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Ja hän tuli vielä raskaaksi, ja synnytti pojan, ja sanoi: nyt minä kiitän Herraa; sentähden kutsui hän hänen nimensä Juuda: ja lakkasi synnyttämästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Koska Rakel näki, ettei hän synnyttänyt Jakobille, kadehti hän sisartansa, ja sanoi Jakobille: anna minun lapsia, eli minä kuolen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Jakob vihastui kovin Rakelin päälle, ja sanoi: olenko minä Jumalan siassa, joka on sinulta kieltänyt kohdun hedelmän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Ja hän sanoi: tässä on minun piikani Bilha, makaa hänen kanssansa; että hän synnyttäis minun helmaani, ja saisin sittenkin hänestä lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Niin hän antoi hänelle piikansa Bilhan emännäksi: ja Jakob makasi hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Niin Bilha tuli raskaaksi ja synnytti Jakobille pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Ja Rakel sanoi: Jumala ratkasi minun asiani, ja kuuli myös minun ääneni, ja antoi minulle pojan; sentähden kutsui hän hänen nimensä Dan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Ja taas Bilha Rakelin piika tuli raskaaksi, ja synnytti Jakobille toisen pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Niin sanoi Rakel: minä olen jalosti kilvoitellut minun sisareni kanssa, ja olen myös voittanut: ja hän kutsui hänen nimensä Naphtali.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Koska Lea näki, että hän lakkasi synnyttämästä; otti hän piikansa Silpan, ja antoi sen Jakobille emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Niin synnytti Silpa, Lean piika, Jakobille pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Ja Lea sanoi: joukko tulee: ja kutsui hänen nimensä Gad.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Ja Silpa, Lean piika, synnytti Jakobille toisen pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Ja Lea sanoi: autuasta minua, sillä tyttäret sanovat minua autuaaksi: ja hän kutsui hänen nimensä Asser.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Ja Ruben meni ulos nisun elonaikana, ja löysi dudaimia vainioilta, ja toi ne Lealle äidillensä. Niin sanoi Rakel Lealle: anna minulle poikas dudaimista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Hän vastasi häntä: vähäkö sinun siinä on, ettäs olet minulta miehen vienyt, mutta tahdot myös ottaa poikani dudaimit? Ja Rakel sanoi: sentähden maatkaan hän tänä yönä sinun kanssas poikas dudaimien tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Koska Jakob ehtoona kedolta palasi, meni Lea häntä vastaan, ja sanoi: minun kanssani pitää sinun makaaman: sillä minä olen sinun kallisti ostanut poikani dudaimilla. Ja hän makasi sen yön hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Ja Jumala kuuli Lean, ja hän tuli raskaaksi, ja synnytti Jakobille viidennen pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Ja Lea sanoi: Jumala on maksanut sen minulle, että minä annoin piikani miehelleni: ja kutsui hänen nimensä Isaskar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Ja Lea taas tuli raskaaksi, ja synnytti Jakobille kuudennen pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Ja Lea sanoi: Jumala on minun hyvästi lahjoittanut, nyt taas asuu minun mieheni minun tykönäni: sillä minä olen synnyttänyt hänelle kuusi poikaa. Ja kutsui hänen nimensä Sebulon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Sitte synnytti hän tyttären, ja kutsui hänen nimensä Dina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Mutta Jumala muisti myös Rakelin, ja Jumala kuuli hänen, ja saatti hedelmälliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Niin hän tuli raskaaksi ja synnytti pojan, ja sanoi: Jumala on ottanut pois minun häväistykseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Ja kutsui hänen nimensä Joseph, sanoen: Herra lisätköön minulle vielä toisen pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Ja tapahtui, koska Rakel oli synnyttänyt Josephin; sanoi Jakob Labanille: päästä minua menemään kotiani ja maalleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Anna minulle minun emäntäni ja lapseni, joiden tähden minä olen sinua palvellut, että minä menisin pois: sillä sinä tiedät minun palvelukseni, kuin minä olen sinua palvellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Ja Laban sanoi hänelle: anna minun löytää armo sinun edessäs, minä ymmärrän, että Herra on siunannut minun sinun tähtes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Ja sanoi (vielä): määrää siis sinun palkkas minulle, ja minä annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Mutta hän sanoi hänelle: sinä tiedät, kuinka minä olen palvellut sinua: ja kuinka paljo sinun karjaas on minun haltuuni annettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Sinulla oli vähä ennenkuin minä tulin, mutta nyt se on paljoksi kasvanut, ja Herra on siunannut sinun, minun jalkajuonteni kautta. Koska minä siis oman huoneeni parasta katson?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Ja (Laban) sanoi: mitästä minä sinulle annan? Ja Jakob sanoi: ei sinun pidä mitään antaman minulle. Mutta jos sinä tämän minulle teet, niin minä vielä tästälähin kaitsen ja varjelen sinun laumaas:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Minä käyn tänäpänä kaiken sinun laumas lävitse, eroittaen sieltä kaikki pilkulliset ja kirjavat lampaat, ja kaikki hallavat karitsain seassa, ja kirjavat ja pilkulliset vuohten seassa, (mitä sitte kirjavaksi ja pilkulliseksi tulee) se olkoon minun palkkani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Niin minun vanhurskauteni on todistava tästedes minusta, koska se siihen tulee, että minun pitää palkkani sinun nähtes saaman: niin että kaikki, jotka ei ole pilkulliset taikka kirjavat vohlista, eikä hallavat karitsoista, se olkoon varkaus minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Niin sanoi Laban: katso, joska se olis sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Ja sinä päivänä eroitti hän pilkulliset ja kirjavat kauriit ja kaikki pilkulliset ja kirjavat vuohet, kaikki joissa jotakin valkeutta oli, ja kaikki hallavat karitsat: ja antoi ne lastensa haltuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Ja asetti kolmen päiväkunnan matkan, itsensä ja Jakobin vaiheelle: ja Jakob kaitsi niitä, jotka Labanin laumasta jäivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Mutta Jakob otti viherjäisiä haapaisia sauvoja, mandelpuisia ja plataneapuisia; ja kuori niihin valkiat juonteet, valkian paikan paljastamisella, joka sauvain päällä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Ja pani ne sauvat, jotka hän kuorinut oli, laumain eteen, vesiruuhiin, ja juoma-astioihin, lauman eteen, joihin he tulivat juomaan, että he juomalle tultuansa siittäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Ja niin laumat siittivät niiden sauvain päällä, ja kantoivat pilkullisia, juonteisia ja kirjavia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Niin Jakob eroitti karitsat, ja asetti lauman kasvot, siinä valkiassa laumassa, niitä pilkullisia ja hallavia päin: ja teki itsellensä eri lauman, ja ei laskenut niitä Labanin lauman sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Ja koska se varhain kantava lauma oli sikoillansa, pani Jakob sauvat laumain silmäin eteen ruuhiin: että he siittäisivät sauvain päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mutta koska ne hiljain juoksivat, niin ei hän pannut niitä sisälle. Niin tulivat äpöiset Labanille ja varhain kannetut Jakobille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Siitä tuli mies sangen äveriääksi, niin että hänellä oli paljo lampaita ja piikoja ja palvelioita, ja kameleja ja aaseja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Ja hänen eteensä tuli Labanin lasten puhe, että he sanoivat: Jakob on saattanut itsellensä kaiken meidän isämme tavaran: ja siitä meidän isämme hyvyydestä on hän saattanut itsellensä kaiken tämän tavaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Ja Jakob näki Labanin kasvon: ja katso, ei ollut se häntä kohtaan, niinkuin eilen ja entispäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Ja Herra sanoi Jakobille: palaja sinun isäis maalle, ja sukuis tykö: ja minä olen sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Niin lähetti Jakob ja kutsui Rakelin ja Lean kedolle laumansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Ja sanoi heille: minä näen teidän isänne kasvon, ettei hän ole minua kohtaan niinkuin eilen ja entispäivänä, mutta minun isäni Jumala on ollut minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Ja te itse tiedätte, että minä olen kaikella minun väelläni palvellut teidän isäänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Mutta teidän isänne on vietellyt minua, ja muuttanut minun palkkani jo kymmenen kertaa: ei kuitenkaan sallinut Jumala hänen vahinkoa tehdä minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Koska hän sanoi: kirjavat pitää oleman sinun palkkas, niin kaikki lauma kantoi kirjavia. Mutta jos hän sanoi: pilkulliset pitää oleman sinun palkkas, niin kaikki lauma kantoi pilkullisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Niin on Jumala ottanut teidän isänne hyvyyden ja antanut minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Ja tapahtui lauman siittämisen ajalla, nostin minä silmäni ja näin unessa: ja katso, kauriit, jotka nousivat laumain päälle, olivat juonteiset, pilkulliset ja kirjavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Ja Jumalan enkeli sanoi minulle unessa: Jakob; ja minä vastasin: tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Mutta hän sanoi: nosta silmäs, ja katso, kaikki kauriit, jotka nousevat laumain päälle, ovat juonteiset, pilkulliset ja kirjavat: sillä minä olen nähnyt kaikki, mitä Laban sinulle tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Minä olen Jumala BetElissä, jossa sinä voitelit kiven, ja jossas teit minulle lupauksen: nouse siis nyt ja lähde tältä maalta, ja palaja syntymä-maalles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Niin vastasivat Rakel ja Lea, ja sanoivat hänelle: onko meillä enää osaa, eli perimistä meidän isämme huoneessa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Eikö hän ole pitänyt meitä muukalaisina? Sillä hän on myynyt meidät, ja peräti syönyt meidän hintamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Sentähden kaikki hyvyys, jonka Jumala on ottanut meidän isältämme, se tulee oikeudella meille ja meidän lapsillemme: Nyt siis kaikki, mitä Jumala sinulle on käskenyt, se tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Niin nousi Jakob; ja nosti lapsensa ja emäntänsä kamelein päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Ja vei pois kaiken karjansa, ja kaiken tavaransa, minkä hän oli pannut kokoon, sen oman karjansa, kun hän oli saanut Mesopotamiassa: mennäksensä isänsä Isaakin tykö Kanaanin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Mutta Laban oli mennyt keritsemään laumaansa. Ja Rakel varasti isänsä epäjumalat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Niin varasti Jakob Labanin Syrialaisen sydämen, siinä ettei hän ilmoittanut hänelle, että hän pakeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Niin hän pakeni, ja kaikki, mitä hänellä oli, nousi ja meni virran ylitse; ja meni Gileadin vuorta kohden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Kolmantena päivänä ilmoitettiin Labanille, että Jakob oli paennut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Niin hän otti veljensä kanssansa, ja ajoi häntä takaa seitsemän päiväkunnan matkan: ja saavutti hänen Gileadin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Mutta Jumala oli tullut Labanin Syrialaisen tykö yöllä unessa ja sanonut hänelle: kavahda sinuas, ettes puhu Jakobille hyvää eli pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Ja Laban lähestyi Jakobia. Mutta Jakob oli majansa tehnyt vuorelle. Ja Laban teki veljinensä myös majansa Gileadin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Niin sanoi Laban Jakobille: mitäs olet tehnyt, ettäs varastit minun sydämeni ja olet vienyt pois minun tyttäreni niinkuin miekalla otetut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Ja miksis salaa pakenit ja varastit sinus minulta, ja et ilmoittanut minulle? että minä olisin sinua saattanut ilolla, ja lauluilla, ja trumpuilla, ja kanteleilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Ja et sallinut minun suuta antaa minun pojilleni ja tyttärilleni: tämän sinä olet tyhmästi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Ja minulla olis kyllä voimaa tehdä teille pahaa, mutta teidän isänne Jumala sanoi menneenä yönä minulle: kavahda itses puhumasta Jakobille hyvää eli pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Ja nyt ettäs kumminkin menit pois, ja niin suuresti ikävoitsit isäs huoneeseen: miksis varastit minun jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Ja Jakob vastasi, ja sanoi Labanille: minä pelkäsin ja luulin sinun väkivallalla ottavan pois minulta sinun tyttäres.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Mutta kenenkä tyköä sinä löydät jumalas, ei sen pidä elämän. Tunnustele meidän veljeimme läsnä ollessa, mitä omaas on minun tykönäni, ja ota pois se. Mutta ei Jakob tietänyt Rakelin niitä varastaneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Niin Laban meni Jakobin majaan, ja Lean majaan, ja heidän molempain piikainsa majaan, ja ei löytänyt. Ja läksi Lean majasta, ja tuli Rakelin majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Mutta Rakel oli ottanut epäjumalat ja pannut kamelein satulan ala, ja istui siihen päälle; mutta Laban etsi kaiken majan ja ei löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Ja hän sanoi isällensä: älköön minun herrani vihastuko, etten minä saa nousta sinun edessäs: sillä minulle tapahtuu vaimoin menon jälkeen: Ja hän etsi, ja ei löytänyt epäjumaliansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Ja Jakob vihastui ja riiteli Labanin kanssa; vastasi ja sanoi hänelle: mitä minä olen rikkonut, ja mikä minun pahatekoni on, ettäs minua olet niin vihaisesti ajanut takaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Sinä olet etsiskellyt kaikki minun taloni kalut, mitäs olet löytänyt kaikista sinun talois kaluista? Tuo tähän minun ja sinun veljeis eteen, ratkaista meidän kahden vaiheellamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Minä olen ollut sinun tykönäs jo kaksikymmentä ajastaikaa, ja sinun lampaas ja vuohes ei ole hedelmättömät olleet: ja en ole minä syönyt oinaita sinun laumastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Enkä ole tuonut sinulle pedolta haaskattua, mutta minun piti sen maksaman, sen olet sinä minun kädestäni vaatinut: niin myös mitä ikänänsä sinulta päivällä eli yöllä varastettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Päivällä on minun helle väsyttänyt, ja yöllä vilu: ja uni on paennut minun silmistäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Minä olen jo kaksikymmentä ajastaikaa ollut sinun huoneessas, neljätoistakymmentä ajastaikaa palvelin minä sinua kahden tyttäres tähden, ja kuusi ajastaikaa sinun laumas tähden: ja sinä olet muuttanut minun palkkani kymmenen kertaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Jollei minun isäni Jumala, Abrahamin Jumala ja Isaakin pelko olisi ollut minun puolellani; niin sinä peräti tyhjänä olisit minun päästänyt. Mutta Jumala on nähnyt minun vaivani ja kätteni työt, ja nuhteli menneenä yönä sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Vastasi Laban, ja sanoi Jakobille: tyttäret ovat minun tyttäreni, ja pojat ovat minun poikani, ja laumat ovat minun laumani, ja kaikki mitä sinä näet ovat minun: mitä minä teen tänäpänä minun tyttärilleni taikka heidän lapsillensa, jotka he ovat synnyttäneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Tule siis nyt ja tehkäämme liitto, minä ja sinä; joka pitää oleman todistus minun ja sinun vaiheellas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Niin otti Jakob kiven, ja pani pystyälle muistopatsaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Ja Jakob sanoi veljillensä: kootkaat kiviä. Ja he toivat kiviä, ja tekivät roukkion; ja atrioitsivat siinä sen roukkion päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Ja Laban kutsui hänen Jegar Sahabuta: mutta Jakob kutsui hänen Gilead.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Niin Laban sanoi: tämä roukkio olkoon todistus tänäpänä minun ja sinun vaiheellas; sentähden kutsui hän hänen nimensä Gilead.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Ja Mitspa; sillä hän sanoi: Herra olkoon peräänkatsoja sinun ja minun vaiheellani, koska me erkanemme toinen toisestamme:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Jos sinä vaivaat minun tyttäriäni, taikka otat muita emäntiä, paitsi minun tyttäriäni. Ei ole yhtään ihmistä (joka todistais) meidän kanssamme, mutta katso, Jumala on todistaja minun ja sinun vaiheellas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Ja Laban sanoi (vielä) Jakobille: katso, tämä on roukkio, ja tämä on muistopatsas, jonka minä panen minun ja sinun vaiheelles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Tämä roukkio olkoon todistus, ja tämä patsas olkoon myös todistus, etten minä käy ylitse tämän roukkion sinun tykös, etkä sinä käy ylitse tämän roukkion ja tämän patsaan minun tyköni, vahinkoa tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Abrahamin Jumala ja Nahorin Jumala ja heidän isäinsä Jumala, ratkaiskoon meidän välillämme. Ja Jakob vannoi isänsä Isaakin pelvon kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Ja Jakob uhrasi vuorella, ja kutsui veljensä syömään leipää. Ja kuin he olivat syöneet, olivat he yötä vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Mutta aamulla varhain nousi Laban, ja suuta antoi poikainsa ja tytärtensä, ja siunasi heitä, ja meni matkaansa, ja palasi kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Mutta Jakob meni tietänsä myöten, ja Jumalan enkelit tulivat häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Ja koska hän näki heidät, sanoi hän: Nämä ovat Jumalan sotajoukko. Ja hän kutsui sen paikan Mahanaim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Niin Jakob lähetti sanansaattajat edellänsä veljensä Esaun tykö, Seirin maakuntaan, Edomin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Ja käski heitä, sanoen: sanokaat näin minun herralleni Esaulle: näin sanoo sinun palvelias Jakob: minä olen ollut muukalainen Labanin tykönä, ja viipynyt tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Ja minulla on karjaa ja aaseja, lampaita, palvelioita ja piikoja: ja lähetin ilmoittamaan minun herralleni, löytääkseni armoa sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Sanansaattajat palasivat Jakobin tykö, sanoen: me tulimme Esaun sinun veljes tykö; ja hän tulee sinua vastaan, ja neljäsataa miestä hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Niin peljästyi Jakob kovin, ja ahdistus tuli hänen päällensä: ja jakoi väen, joka oli hänen kanssansa, ja lampaat, ja karjan ja kamelit kahteen joukkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Ja sanoi: jos Esau tulee yhden joukon päälle, ja lyö sen; niin jäänyt joukko pääsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Ja Jakob sanoi: minun isäni Abrahamin Jumala, ja minun isäni Isaakin Jumala, Herra joka sanoit minulle: palaja maalles ja sukuis tykö, ja minä teen sinulle hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Minä olen mahdotoin kaikkeen siihen armoon, ja kaikkeen siihen totuuteen, jonka sinä teit palvelialles. Sillä koska minä tämän Jordanin ylitse menin, ei minulla muuta ollut kuin minun sauvani; mutta nyt minulla on kaksi joukkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Pelasta siis nyt minua minun veljeni Esaun käsistä: sillä minä pelkään hänen tulevan ja lyövän minun, ja äidin lapsinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Sinä olet kumminkin sanonut: minä teen kaiketi sinulle hyvää; ja lisään sinun siemenes niinkuin sannan meressä, joka paljouden tähden ei luettaa taideta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Ja hän yötyi sinne, ja otti niistä, kuin olivat käsillä, lahjoja lähettääksensä veljellensä Esaulle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Kaksisataa vuohta, ja kaksikymmentä kaurista: kaksisataa lammasta ja kaksikymmentä jäärää:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Imettäviä kameleja varsoinensa kolmekymmentä: neljäkymmentä lehmää ja kymmenen härkää, kaksikymmentä aasia ja kymmenen varsaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Ja antoi ne palvelioittensa käsiin, itsekunkin lauman erinänsä; ja sanoi palvelioillensa: menkäät minun edelläni, ja pitäkäät väli jokaisen lauman vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Ja käski ensimäiselle, sanoen: Koska minun veljeni Esau kohtaa sinun, ja kysyy sinulta, kenenkäs olet, ja kuhunkas menet? ja kenenkä nämät ovat, joitas ajat edelläs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Niin sano: nämät ovat sinun palvelias Jakobin lahjat, lähetetyt minun herralleni Esaulle: ja katso, hän tulee myös itse meidän jälissämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Niin käski hän myös toiselle ja kolmannelle, ja kaikille niille, jotka kävivät lauman jälissä, sanoen: tämän minun sanani jälkeen puhukaat Esaulle, koska te hänen löydätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Ja sanokaat myös: katso, sinun palvelias Jakob on myös meidän jälissämme; sillä hän ajatteli: minä lepytän hänen lahjoilla, jotka minun edelläni menevät; sitte tahdon minä nähdä hänen kasvonsa, mitämaks, hän ottaa vastaan minun ystävällisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Niin lahjat menivät hänen edellänsä; mutta hän oli itse siinä yötä joukkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Ja nousi yöllä ja otti kaksi emäntäänsä, ja ne kaksi piikaansa, ja yksitoistakymmentä lastansa: ja meni ylitse Jabbokin luotuspaikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Ja otti ne ja vei heidät virran ylitse: ja vei myös ylitse kaikki, mitä hänellä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Mutta Jakob jäi sille puolelle yksinänsä. Silloin paineli yksi mies hänen kanssansa, siihenasti kuin aamurusko nousi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Ja kuin hän näki, ettei hän voittanut häntä, rupesi hän hänen reiteensä, niin että Jakobin reisiluu horjahtui painellessa hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Ja hän sanoi: päästä minua, sillä aamurusko nousee. Mutta hän vastasi: en minä päästä sinua, jolles siunaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Ja hän sanoi hänelle: mikä sinun nimes on? hän vastasi: Jakob.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Ja hän sanoi: ei sinua sillen pidä kutsuttaman Jakob, vaan IsraEl: sillä sinä olet taistellut Jumalan ja ihmisten kanssa, ja olet voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Ja Jakob kysyi häneltä, ja sanoi: sanos nyt sinun nimes. Mutta hän sanoi: miksis minun nimeäni kysyt? Ja hän siunasi häntä siinä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Ja Jakob kutsui sen paikan Pniel: sillä minä olen nähnyt Jumalan kasvosta kasvoon, ja minun sieluni on vapahdettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Ja aurinko nousi, koska hän Pnielin ohitse kävi, ja hän ontui reidestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Sentähden ei syö Israelin lapset reisisuonta tähän päivään asti, että Jakobin reisiluu horjahtui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Ja Jakob nosti silmänsä ja näki, ja katso, Esau tuli, ja neljäsataa miestä hänen kanssansa: ja hän jakoi lapset Lealle ja Rakelille, ja molemmille piioille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Ja asetti piiat lapsinensa ensimmäiseksi; sitälähin Lean hänen lastensa kanssa, ja Rakelin Josephin kanssa jälimmäiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Mutta itse hän kävi heidän edellänsä: ja kumarsi maahan seitsemän kertaa, siihenasti kuin hän veljeänsä lähestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Ja Esau juoksi häntä vastaan, ja syliinsä otti hänen, ja halasi häntä kaulasta, ja suuta antoi hänen: ja he itkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Ja hän nosti silmänsä, ja näki vaimot ja lapset, ja sanoi: kutka nämät kanssas ovat? Hän vastasi: ne ovat lapset, jotka Jumala on lahjoittanut sinun palvelialles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Niin piiat lähestyivät lapsinensa ja kumarsivat hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Ja lähestyi myös Lea lapsinensa, ja kumarsivat hänen edessänsä. Sitte tuli Joseph ja Rakel, jotka myös kumarsivat hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Ja hän sanoi: mitäs tahdot kaiken sen joukon kanssa, kuin minä kohdannut olen? Hän vastasi: löytääkseni armoa minun herrani edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Ja Esau sanoi: minulla on kyllä, minun veljeni, pidä omas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Niin Jakob vastasi: ei niin, mutta jos minä olen löytänyt armon sinun edessäs, niin ota minun lahjani minun kädestäni: sillä minä näin sinun kasvos, niinkuin minä olisin nähnyt Jumalan kasvot; ettäs olet minut hyväksi ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Ota siis se siunaus, jonka minä olen tuonut sinulle: sillä Jumala on sen minulle antanut, ja minulla on kyllä kaikkinaista. Niin hän vaati häntä ottamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Ja (Esau) sanoi: lähtekäämme jo matkustamaan, minä vaellan sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Niin hän sanoi hänelle: minun herrani tietää minulla olevan pieniä lapsia, ja imettäväisiä lampaita ja karjaa: jos ne yhtenä päivänä äkisti ajettaisiin, niin kuolis lauma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Niin menkään minun herrani palveliansa edellä: mutta minä seuraan hiljaksensa senjälkeen kuin karja ja lapset käydä voivat, siihenasti kuin minä tulen minun herrani tykö Seiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Ja Esau sanoi: minä jätän kuitenkin sinun tykös jotakin siitä väestä, kuin minun kanssani on. Hän vastasi: mihinkä se? Anna minun ainoastansa löytää armo minun herrani edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Niin Esau palasi sinä päivänä tietänsä myöten Seiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Mutta Jakob matkusti Sukkotiin, ja rakensi itsellensä huoneen, ja teki majat karjallensa. Sentähden kutsui hän sen paikan Sukkot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Sitte tuli Jakob rauhoitettuna siihen kaupunkiin Sikem, joka on Kanaanin maalla, sitte kuin hän oli tullut Mesopotamiasta; ja sioitti itsensä kaupungin kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Ja osti murun peltoa, johonka hän teki majansa, Hemorin, Sikemin isän lapsilta, sadan penningin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Ja rakensi siinä alttarin: ja rukoili väkevää Israelin Jumalan nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Ja Dina, Lean tytär, jonka hän Jakobille synnyttänyt oli, meni katselemaan sen maakunnan tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Koska Sikem, Hemorin Heviläisen, sen maakunnan ruhtinaan poika näki hänen, otti hän hänen ja makasi hänen, ja häpäisi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Ja hänen sydämensä paloi Dinan Jakobin tyttären perään; ja rakasti piikaa, ja puhutteli häntä suloisilla sanoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Ja Sikem puhui isällensä Hemorille, sanoen: ota minulle tämä piika emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Ja Jakob kuuli, että he hänen tyttärensä Dinan olivat häväisseet, ja hänen poikansa olivat lauman kanssa kedolla. Ja Jakob vaikeni siihenasti kuin he tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Ja Hemor Sikemin isä meni Jakobin tykö puhuttelemaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Silloin tulivat Jakobin pojat kedolta: ja koska he sen kuulivat, tulivat miehet surulliseksi, ja vihastuivat sangen kovin; että hän oli tehnyt tyhmyyden Israelissa, maaten Jakobin tyttären: sillä ei ollut se oikein tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Niin puhui Hemor heidän kanssansa, sanoen: minun poikani Sikemin sydän halajaa teidän tyttärenne jälkeen; antakaat siis se hänelle emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Naittakaat teitänne yhteen meidän kanssamme: antakaat teidän tyttärenne meille, ja ottakaat jällensä meidän tyttäremme teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Ja asukaat meidän kanssamme: maan pitää oleman teillä alttiina, asukaat, myykäät ja ostakaat siinä, ja omistakaat maa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Ja Sikem sanoi hänen isällensä ja veljillensä: antakaat minun löytää armo teidän edessänne: ja mitä te sanotte minulle, sen minä annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Anokaat minulta rohkiasti huomenlahja ja antimia, ja minä annan, mitä te anotte: antakaat minulle vaivoin se piika emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Niin vastasivat Jakobin pojat Sikemille, ja hänen isällensä Hemorille, ja puhuivat petoksella; että hän oli heidän sisarensa Dinan häväissyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Ja sanoivat heille: emme taida sitä tehdä, että me annamme meidän sisaremme ympärileikkaamattomalle miehelle: sillä se olis meille häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Mutta kuitenkin siinä me suostumme teihin; jos te tulette meidän kaltaiseksemme, että kaikki miehenpuoli teidän seassanne ympärileikattaisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Niin me annamme meidän tyttäremme teille, ja otamme teidän tyttärenne meille, ja asumme teidän kanssanne ja tulemme yhdeksi kansaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mutta jollette kuule meitä, ja anna teitänne ympärileikata; niin me otamme meidän tyttäremme, ja menemme matkaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Ja heidän puheensa kelpasi Hemorille, ja Sikemille Hemorin pojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Ja se nuori mies ei viivytellyt sitä tehdäksensä: sillä hän rakasti suuresti Jakobin tytärtä, ja hän oli kunniassa pidettävä kaikkein ylitse isänsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Niin tuli Hemor ja hänen poikansa Sikem kaupunkinsa porttiin, ja puhuivat kaupunkinsa miehille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Nämät miehet ovat rauhalliset meidän kanssamme, ja tahtovat asua ja elää tällä maalla, ja katso, maa on kyllä avara heidän edessänsä: ottakaamme heidän tyttärensä meille emännäksi, ja antakaamme meidän tyttäremme heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mutta siihen ne miehet antavat meille suosionsa, asuaksensa meidän kanssamme ja tullaksensa yhdeksi kansaksi: jos meistä ympärileikataan kaikki miehenpuoli, niin kuin he myös ympärileikatut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Heidän karjansa ja hyvyytensä, ja kaikki heidän eläimensä, eikö ne ole meidän omamme? Jos me muutoin olemme heidän tahtonsa jälkeen, niin että he asuvat meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Ja he olivat Hemorille kuuliaiset, ja Sikemille hänen pojallensa, kaikki jotka hänen kaupunkinsa portista kävivät ulos: ja ympärileikkasivat itsensä, jokainen miehenpuoli, jotka hänen kaupunkinsa portista kävivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Ja tapahtui kolmantena päivänä, koska he kipiämmällänsä olivat, ottivat kaksi Jakobin poikaa Simeon ja Levi, Dinan veljet, kumpikin miekkansa, ja menivät rohkiasti kaupunkiin: ja tappoivat jokaisen miehenpuolen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Ja tappoivat myös Hemorin, ja hänen poikansa Sikemin miekan terällä: ja ottivat Dinan Sikemin huoneesta, ja menivät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Niin tulivat Jakobin pojat tapettuiden päälle, ja ryöstivät kaupungin; että he olivat häväisseet heidän sisarensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ja veivät pois heidän lampaansa, karjansa, aasinsa, ja mitä sekä kaupungissa että kedolla oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Ja kaikki heidän hyvyytensä, lapsensa ja heidän vaimonsa he ottivat vangiksi, ja ryöstivät; niin myös kaikki, mitä huoneissa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Ja Jakob sanoi Simeonille ja Leville: te olette minulle mielikarvauden tehneet, saattaen minun haisevaiseksi tämän maakunnan asuvaisille, Kanaanealaisille ja Pheresiläisille: ja minä olen vähä joukko, koska he heitänsä kokoovat minun päälleni, niin he tappavat minun, ja minä hukutetaan, ja minun huoneeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Mutta he vastasivat: pitiköstä heidän tekemän meidän sisaremme kanssa, niinkuin jonkun porton kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Ja Jumala sanoi Jakobille: nouse ja mene ylös BetEliin, ja asu siellä: ja tee siihen alttari Jumalalle, joka sinulle ilmestyi, koska sinä pakenit veljes Esaun edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Niin sanoi Jakob perheellensä, ja kaikille, jotka hänen kanssansa olivat: eroittakaat teistänne vieraat Jumalat, jotka teidän seassanne ovat, ja puhdistakaat teitänne, ja muuttakaat teidän vaatteenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Ja nouskaamme ja menkäämme ylös BetEliin; että minä tekisin siihen alttarin Jumalalle, joka minua kuuli minun hätäaikanani, ja on ollut minun kanssani tiellä, jota minä matkustin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Niin he antoivat Jakobille kaikki vieraat Jumalat, jotka heidän käsissänsä olivat, ja korvarenkaansa, jotka heidän korvissansa olivat. Ja Jakob kaivoi ne sen tammen alle, joka oli Sikemin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Ja he matkustivat. Ja Jumalan pelko tuli niille kaupungeille, jotka olivat heidän ympärillänsä, ettei he ajaneet Jakobin poikia takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Niin tuli Jakob Lutsiin Kanaanin maalle, se on BetEl, kaiken sen väen kanssa kuin hänen kanssansa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Ja rakensi siihen alttarin, ja kutsui sen paikan ElBetEl; sillä Jumala ilmestyi siinä hänelle, paetessansa veljensä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Niin kuoli Debora Rebekan imettäjä, ja haudattiin alemmaiselle puolelle BetEliä, tammen alle: ja se kutsuttiin itkutammeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Ja Jumala ilmestyi taas Jakobille, sitte kuin hän oli tullut Mesopotamiasta ja siunasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Ja Jumala sanoi hänelle: sinun nimes on Jakob: mutta ei silleen pidä sinun nimes kutsuttaman Jakob, vaan IsraEl pitää sinun nimes oleman. Ja niin kutsuttiin hänen nimensä IsraEl.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Ja Jumala sanoi hänelle: Minä olen kaikkivaltias Jumala, ole hedelmällinen ja enäne, kansa ja kansain joukko pitää sinusta tuleman: ja kuninkaat pitää tuleman sinun kupeistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Ja sen maan, jonka minä olen antanut Abrahamille ja Isaakille, annan minä sinulle: ja sinun siemenelles sinun jälkees, annan minä sen maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Ja niin meni Jumala ylös hänen tyköänsä, siinä paikassa, kuin hän hänen kanssansa puhunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Mutta Jakob asetti muistopatsaan siihen paikkaan, jossa hän hänen kanssansa puhunut oli, (nimittäin) kivisen patsaan: ja uhrasi juomauhria, ja kaasi öljyä sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Ja Jakob kutsui sen paikan, jossa Jumala hänen kanssansa puhunut oli, BetEl.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Ja he matkustivat BetElistä, ja kuin vielä vähä matkaa oli Ephratiin, niin synnytti Rakel, ja synnyttäminen oli hänelle sangen raskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Ja koska synnyttäminen oli hänelle raskaimmallansa; sanoi lastenämmä hänelle: älä pelkää, sillä tämä poika on sinulla myös oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Mutta hänen henkensä lähteissä, koska hänen piti kuoleman, kutsui hän hänen nimensä BenOni: mutta hänen isänsä kutsui hänen nimensä BenJamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Niin kuoli Rakel: ja hän haudattiin Ephratiin tien viereen, se on BetLehem.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Ja Jakob pani patsaan hänen hautansa päälle: tämä on Rakelin haudan patsas hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Ja IsraEl matkusti edespäin, ja teki majansa tuolle puolelle Ederin tornia');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Ja se tapahtui, koska IsraEl asui siinä maakunnassa, meni Ruben ja makasi Bilhan isänsä jalkavaimon kanssa. Ja IsraEl sai sen kuulla. Ja Jakobilla oli kaksitoistakymmentä poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Lean pojat olivat nämät: Jakobin esikoinen Ruben; niin Simeon, ja Levi, ja Juuda, ja Isaskar ja Zebulon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Rakelin pojat olivat: Joseph ja BenJamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Bilhan Rakelin piian pojat olivat: Dan ja Naphtali.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Silpan Lean piian pojat olivat: Gad ja Asser. Nämät ovat Jakobin pojat, jotka hänelle syntyneet olivat Mesopotamiassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Ja Jakob tuli isänsä Isaakin tykö Mamreen, Arban kaupunkiin, joka on Hebron, jossa Abraham ja Isaak olivat muukalaiset olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Ja Isaak oli sadan ja kahdeksankymmenen ajastaikainen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Ja tuli riutuneeksi, ja kuoli, ja koottiin kansansa tykö, vanhana ja suuttununna elämästä. Ja hänen poikansa Esau ja Jakob hautasivat hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Tämä on Esaun sukukunta, joka on Edom.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau otti emännät Kanaanin tyttäristä: Adan, Hetiläisen Elonin tyttären, ja Oholibaman, Anan Heviläisen Zibeonin pojan tyttären.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Ja Basmatin, Ismaelin tyttären, Nebajotin sisaren.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Ada synnytti Esaulle Eliphan. Ja Basmat synnytti Reguelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oholibama synnytti Jeun, Jaelamin ja Koran. Nämät ovat Esaun lapset, jotka hänelle syntyivät Kanaanin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ja Esau otti emäntänsä, poikansa ja tyttärensä ja kaikki huoneensa sielut, ja karjansa ja kaikki juhtansa, ja kaiken sen tavaransa, kuin hän oli pannut kokoon Kanaanin maalla: ja meni (toiselle) maalle, veljensä Jakobin tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Sillä heidän tavaransa oli niin suuri, ettei he taitaneet asua ynnä: ja se maa, jossa he muukalaiset olivat, ei vetänyt heitä heidän karjansa (paljouden) tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Niin asui Esau Seirin vuorella, ja tämä Esau on Edom.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Nämät ovat Esaun sukukunnat Edomilaisten isän Seirin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Nämät ovat Esaun poikain nimet: Eliphas, Adan Esaun emännän poika: Reguel Basmatin Esaun emännän poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Ja Eliphan pojat olivat: Teman, Omar, Zepho, ja Gaetam ja Kenas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Mutta Timna oli Eliphan Esaun pojan jalkavaimo, joka synnytti hänelle Amalekin. Ne ovat Adan Esaun emännän lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Mutta Reguelin lapset ovat nämät: Nahat, ja Zera, Samma, Missa. Ne ovat Basmatin Esaun emännän lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Mutta nämät olivat Oholibaman Esaun emännän pojat, Anan tyttären Zibeonin pojan tyttären lapset; jotka hän synnytti Esaulle: Jeus ja Jaelam ja Kora.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Nämät ovat ruhtinaat Esaun lapsista: Eliphan Esaun esikoisen lapset ovat nämät: se ruhtinas Teman, se ruhtinas Omar, se ruhtinas Zepho, se ruhtinas Kenas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Se ruhtinas Kora, se ruhtinas Gaetam, se ruhtinas Amalek. Nämät ovat ruhtinaat Eliphasta Edomin maalla, ja ovat Adan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Ja nämät ovat Reguelin Esaun pojan lapset: se ruhtinasa Nahat, se ruhtinas Sera, se ruhtinas Samma, se ruhtinas Missa. Nämät ovat ruhtinaat Reguelista Edomilaisten maalla ja ovat Basmatin Esaun emännän lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Mutta nämät ovat Oholibaman Esaun emännän lapset: se ruhtinas Jeus, se ruhtinas Jaelam, se ruhtinas Kora. Nämät ovat ruhtinaat Oholibamasta, Anan tyttärestä, Esaun emännästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Nämät ovat Esaun lapset, ja heidän ruhtinaansa. Hän on Edom.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Mutta nämät ovat Seirin Horilaisen lapset, jotka sillä maalla asuivat: Lotan, Sobal, Sibeon, Ana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dison, Etser ja Disan. Nämät ovat Horilaisten ruhtinaat, Seirin lapset Edomin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Mutta Lotanin lapset ovat: Hori ja Heman: ja Lotanin sisar Timna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Sobalin lapset olivat nämät: Alvan, Manahat, Ebal, Sepho ja Onam.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Nämät olivat Sibeonin lapset: Aja ja Ana. Tämä on se Ana, joka korvessa löi Jeminiläiset, kaitessansa isänsä Sibeonin aaseja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Mutta Ananin lapset olivat: Dison ja Oholibama Ananin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Disonin lapset olivat: Hemdan, ja Esban, Jetran ja Karan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Etserin lapset olivat: Bilhan, ja Savan ja Akan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Disanin lapset olivat: Uts ja Aran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Nämät ovat Horilaisten ruhtinaat: se ruhtinas Lotan, se ruhtinas Sobal, se ruhtinas Zibeon, se ruhtinas Ana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Se ruhtinas Dison, se ruhtinas Etser, se ruhtinas Disan. Nämät ovat Horilaisten ruhtinaat, heidän ruhtinastensa seassa Seirin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Mutta kuninkaat kuin Edomin maalla hallitsivat, ennenkuin joku kuningas hallitsi Israelin lapsia, ovat nämät:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Niin hallitsi Edomissa Bela Beorin poika: ja hänen kaupunkinsa nimi on Dinhaba.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Ja koska Bela kuoli, tuli Jobab Seran poika Bosrasta kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Kuin Jobab kuoli, tuli Husam Temanilaisten maalta kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Koska Husam kuoli, tuli Hadad Bedadin poika kuninkaaksi hänen siaansa, joka löi Midianilaiset Moabilaisten kedolla, ja hänen kaupunkinsa nimi oli Avit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Koska Hadad kuoli, hallitsi Samla Masrekasta hänen siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Koska Samla kuoli, tuli Saul kuninkaaksi hänen siaansa, Rehobotin virran tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Koska Saul kuoli, tuli Baalhanan Akborin poika kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Koska Baalhanan Akborin poika kuoli, tuli Hadar kuninkaaksi hänen siaansa, ja hänen kaupunkinsa nimi oli Pagu: ja hänen emäntänsä nimi oli Mehetabeel, Matredin tytär, joka Mesahabin tytär oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Ja nämät ovat Esaun ruhtinasten nimet heidän suvuissansa, paikoissansa ja nimissänsä: se ruhtinas Timna, se ruhtinas Alva, se ruhtinas Jetet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Se ruhtinas Oholibama, se ruhtinas Ela, se ruhtinas Pinon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Se ruhtinas Kenas, se ruhtinas Teman, se ruhtinas Mibtsar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Se ruhtinas Magdiel, se ruhtinas Iram. Nämät ovat Edomin ruhtinaat, niin kuin he asuneet ovat perintömaallansa, ja Esau on Edomilaisten isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Ja Jakob asui sillä maalla, jossa hänen isänsä muukalainen oli ollut: (nimittäin) Kanaanin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Ja nämät ovat Jakobin sukukunnat: Joseph oli seitsemäntoistakymmenen ajastaikainen, koska hän kaitsi karjaa veljeinsä kanssa, ja hän oli nuorella ijällänsä Bilhan ja Silpan, isänsä emäntäin lasten kanssa: ja Joseph ilmoitti isällensä, mikä paha sanoma heistä kuului.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Mutta Israel rakasti Josephia enemmin kuin kaikkia muita lapsiansa, että hän oli syntynyt hänelle vanhalla ijällänsä: ja teki hänelle kirjavan hameen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Kuin hänen veljensä näkivät, että hänen isänsä rakasti häntä enemmin kuin kaikkia hänen veljiänsä, vihasivat he häntä; ja ei voineet puhutella häntä ystävällisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Niin Joseph näki unen, ja ilmoitti sen veljillensä, josta he rupesivat häntä enemmin vihaamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Sillä hän oli sanonut heille, kuulkaas tätä unta, jonka minä näin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Katso, me olimme sitovanamme jalallisia vainiolla ja minun jalalliseni nousi ja seisoi; ja katso, teidän jalallisenne seisoivat ympärillä, ja kumarsivat minun jalallistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Niin sanoivat hänen veljensä hänelle: sinäkö tulet meidän kuninkaaksemme, kokonansa hallitsemaan meitä? Ja vihasivat häntä vielä enemmin, hänen unensa ja puheensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Ja hän taas näki toisen unen, ja jutteli sen veljillensä, ja sanoi: katso, minä näin vielä unta: ja katso, aurinko, kuu ja yksitoista tähteä kumarsivat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Ja kuin hän sitä saneli isällensä ja veljillensä, nuhteli hänen isänsä häntä ja sanoi hänelle: mikä uni se on, kuin sinä olet nähnyt? Pitääkö minun ja sinun äitis ja veljes tuleman ja kumartaman meitämme sinun edessäs maahan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Ja hänen veljensä kadehtivat häntä; mutta hänen isänsä piti nämät sanat mielessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Koska hänen veljensä menivät kaitsemaan karjaa Sikemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Sanoi Israel Josephille: eikö veljes kaitse karjaa Sikemissä? Tule, minä lähetän sinun heidän tykönsä; hän vastasi: tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Hän sanoi: mene ja katso, ovatko veljes ja karja rauhassa, ja palaja minulle sitä sanomaan. Ja hän lähetti hänen Hebronin laaksosta; ja hän tuli Sikemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Niin yksi mies kohtasi hänen eksyksissä kedolla; ja kysyi häneltä sanoen: mitäs etsit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Hän vastasi: minä etsin veljiäni: sanos minulle, kussa he kaitsevat karjaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Ja mies sanoi: he läksivät täältä; sillä minä kuulin heidän sanovan: käykäämme Dotaniin. Niin Joseph meni veljeinsä perään, ja löysi heidät Dotanista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Kuin he kaukana näkivät hänen, ja ennenkuin hän heitä lähestyi, pitivät he neuvoa häntä vastaan, tappaaksensa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Ja sanoivat toinen toisellensa: katso, tuo unennäkiä tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Tulkaat siis, tappakaamme häntä, ja heittäkäämme häntä yhteen kuoppaan, ja sanokaamme: paha peto on hänen syönyt: niin saadaan nähdä, mihinkä hänen unensa joutuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Koska Ruben sen kuuli, tahtoi hän häntä pelastaa heidän käsistänsä, ja sanoi: älkäämme hänen henkeänsä ottako.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Ja Ruben vielä sanoi heille: älkäät vuodattako verta, vaan heittäkäät häntä tähän kuoppaan, joka on korvessa, ja älkäät satuttako kättänne häneen; sillä hän tahtoi pelastaa häntä heidän käsistänsä, saattaaksensa häntä jälleen isänsä tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Ja tapahtui, koska Joseph tuli veljeinsä tykö, riisuivat he häneltä hameen, (nimittäin) sen kirjavan hameen, joka hänen yllänsä oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Ja ottivat hänen ja heittivät kuoppaan: ja kuoppa oli tyhjä, ja ei ollut siinä vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Sitte istuivat he syömään leipää: ja kuin he nostivat silmänsä ja katselivat, niin katso, Ismaelilaisten joukko tuli Gileadista; ja heidän kameleinsa kannatus oli styraks, mastiks ja ladanum, ja vaelsivat viemään niitä alas Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Niin sanoi Juuda veljillensä: mitä me siitä hyödymme, että me murhaamme meidän veljemme ja salaamme hänen verensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Tulkaat ja myykäämme häntä Ismaelilaisille, ja älkäämme satuttako käsiämme häneen: sillä hän on meidän veljemme ja lihamme; ja he kuulivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Koska Midianilaisten kauppamiehet siitä menivät ohitse, vetivät he Josephin ja ottivat ylös kuopasta, ja myivät hänen Ismaelilaisille, kahteenkymmeneen hopiapenninkiin; jotka veivät Josephin pois Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Koska Ruben palasi kuopalle, niin katso, ei ollut Joseph kuopassa: ja hän repäisi vaatteensa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Ja palasi veljeinsä tykö, ja sanoi: ei ole nuorukainen siellä, voi minua! kuhunka minä menen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Niin he ottivat Josephin hameen ja tappoivat kauriin, ja tahrasivat hameen vereen');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Ja lähettivät sen kirjavan hameen, ja antoivat kantaa isällensä, ja sanoivat: tämän me löysimme: tunnustele, jos tämä on poikas hame taikka ei?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Ja hän tunsi sen, ja sanoi: tämä on minun poikani hame, paha peto on hänen syönyt: raadellen on Joseph revelty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Ja Jakob repäisi vaatteensa, ja kääri säkin kupeisiinsa; ja murehti poikaansa monta päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Ja kaikki hänen poikansa ja tyttärensä nousivat häntä lohduttamaan; vaan ei hän tahtonut antaa itsiänsä lohdutettaa, mutta sanoi: minä menen murehtien alas poikani tykö hautaan. Ja hänen isänsä itki häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Mutta Midianilaiset myivät hänen Egyptiin Potipharille, Pharaon kamaripalvelialle ja huovinhaltialle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Se tapahtui siihen aikaan, että Juuda meni alas veljeinsä tyköä, ja poikkesi yhden miehen tykö Odollamiin, jonka nimi oli Hira.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Ja Juuda näki siellä Kanaanin miehen tyttären, hänen nimensä oli Sua: ja otti hänen, ja meni hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Ja hän tuli raskaaksi ja synnytti pojan; ja kutsui hänen nimensä Ger.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Ja hän taas tuli raskaaksi ja synnytti pojan; ja kutsui hänen nimensä Onan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Ja hän synnytti vielä pojan, ja kutsui hänen nimensä Sela. Ja Juuda oli Kesibissä, koska hän sen synnytti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Ja Juuda otti esikoisellensa Gerille emännän, jonka nimi oli Tamar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Mutta Ger, Juudan esikoinen, oli paha Herran edessä: ja Herra kuoletti hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Niin sanoi Juuda (pojallensa) Onanille: mene veljes emännän tykö, ja ota häntä aviokses, herättääkses veljelles siementä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mutta Onan tiesi, ettei siemen olisi tullut hänen omaksensa: koska hän siis makasi veljensä emännän kanssa, antoi hän sen pudota maahan, ja turmeli sen, ettei hän olisi antanut veljellensä siementä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Ja se paha, kuin hän teki, ei kelvannut Herralle, joka kuoletti myös hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Niin sanoi Juuda miniällensä Tamarille: ole leskenä isäs huoneessa siihenasti kuin minun poikani Sela kasvaa. Sillä hän ajatteli: tohtii tapahtua, että hän myös kuolee, niinkuin hänen veljensäkin. Niin Tamar meni pois, ja oli isänsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Koska monta päivää oli kulunut, kuoli Suan tytär, Juudan emäntä. Ja kuin Juuda oli itsensä lohduttanut, meni hän Timnatiin, lammastensa keritsiäin tykö ystävänsä Hiran kanssa Odollamista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Niin ilmoitettiin Tamarille, sanoen: katso, appes menee ylös Timnatiin keritsemään lampaitansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Niin riisui hän yltänsä leskivaatteensa, ja verhoitti itsensä liinalla ja peitti itsensä, ja istui kahden lähteen veräjälle, joka on tiellä Timnatiin; sillä hän näki, että Sela oli kasvanut, ja ei häntä annettu sille emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Koska Juuda näki hänen, luuli hän sen portoksi; sillä hän oli peittänyt kasvonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Ja hän poikkesi tien oheen hänen tykönsä, ja sanoi: annas minun maata kanssas; sillä ei hän tietänyt sitä miniäksensä. Hän vastasi: mitäs minun annat, jos sinä makaisit minun kanssani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Hän sanoi: minä lähetän kauriin laumastani. Hän vastasi: anna siis minulle pantti niin kauvaksi kuin sinä sen lähetät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Hän sanoi: mitästä minä sinulle pantiksi annan? Hän vastasi: sinettis, sitees, ja sauvas, joka kädessäs on. Niin hän antoi ne hänelle, ja makasi hänen kanssansa, ja hän tuli raskaaksi hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Ja hän nousi ja meni, ja pani pois peitteen, ja puki jälleen leskivaatteet yllensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Mutta Juuda lähetti kauriin ystävänsä kanssa Odollamista, että hän vaimolta ottais pantin jälleen: ja ei hän löytänyt häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Niin hän kyseli sen paikan miehiltä, sanoen: kussa on se portto, kuin istui näillä kahdella lähteellä tien ohessa? He vastasivat: ei yksikään portto ole tässä ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Mutta hän palasi Juudan tykö, ja sanoi: en minä löytänyt häntä; sanoivat myös sen paikan miehet, ettei tässä ole yhtäkään porttoa ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Juuda sanoi: pitäkään ne, ettemme mitämaks häpiään tulisi; katso, minä lähetin kauriin, ja et sinä löytänyt häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Liki kolmen kuukauden jälkeen ilmoitettiin Juudalle: sinun miniäs Tamar on salavuoteessa ollut, ja katso, salavuoteesta on hän myös raskaaksi tullut. Juuda sanoi: viekäät häntä poltettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Mutta koska hän tuotiin edes, lähetti hän appensa tykö, sanoen: siitä miehestä, jonka nämät ovat, olen minä raskas. Ja sanoi: tunnetkos, kenenkä on tämä sinetti, side ja sauva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Ja Juuda tunsi ne, ja sanoi: hän on minua hurskaampi: etten minä hänelle poikaani Selaa antanut. Kuitenkin ei hän enempää maannut häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Ja tapahtui hänen synnyttämisensä ajalla, ja katso, kaksoiset olivat hänen kohdussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Ja tapahtui hänen synnyttäissänsä, pisti toinen ulos kätensä, johonka lastenämmä tarttui, ja sitoi siihen punaisen langan, sanoen: tämä tulee ensisti ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Mutta koska hän kätensä takaperin veti, tuli ulos hänen veljensä, ja hän sanoi: miksis olet reväissyt? Tämä rikkirepäisemys on sinun tähtes: ja hänen nimensä kutsuttiin Perets.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Sitte tuli ulos hänen veljensä, jonka kädessä oli se punainen lanka; ja hänen nimensä kutsuttiin Sera.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Ja Josef vietiin alas Egyptiin: ja Potiphar Egyptiläinen Pharaon kamaripalvelia ja huovinhaltia osti hänen Ismaelilaisilta, jotka hänen sinne alas vieneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Ja Herra oli Josephin kanssa, ja hän oli onnellinen mies, ja oli isäntänsä Egyptiläisen huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Ja hänen isäntänsä näki, että Herra oli hänen kanssansa; sillä kaikki, mitä hän teki, antoi Herra menestyä hänen kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Niin että hän löysi armon hänen edessänsä, ja tuli hänen palveliaksensa: ja hän asetti hänen huoneensa ylitse, ja kaikki mitä hänellä oli, antoi hän hänen käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Ja siitä ajasta kuin hän oli hänen pannut huoneensa ja kaiken tavaransa päälle, siunasi Herra sen Egyptiläisen huoneen Josephin tähden, ja Herran siunaus oli kaikissa niissä, jotka hänellä kotona ja kedolla olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Sentähden antoi hän kaikki Josephin haltuun, mitä hänellä oli, ja ei tiedustellut mitään häneltä, paitsi sitä ruokaa, jonka hän söi. Ja Joseph oli kauniin luontoinen, ja ihana kasvoilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Ja tapahtui tämän jälkeen, että hänen isäntänsä emännän silmät paloivat Josephin päälle, ja sanoi: makaa minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Mutta hän kielsi, ja sanoi isäntänsä emännälle: katso, minun isäntäni ei tiedusta minulta, mitä huoneessa on, ja kaikki mitä hänellä on, antoi hän minun käteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Ei pidä hän itseänsä tässä huoneessa suurempana minua, ei myös ole hän kieltänyt minulta mitään, paitsi sinun, siinä kuin sinä olet hänen emäntänsä: kuinka siis minä niin paljon pahaa tekisin ja rikkoisin Jumalaa vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Mutta hän piti jokapäivä senkaltaiset puheet Josephin kanssa; mutta ei hän totellut maata hänen kanssansa, eli olla hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Ja tapahtui yhtenä päivänä, että Joseph meni huoneesen askaroitsemaan; ja ei ollut yksikään perheestä läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Ja hän tarttui hänen hameesensa, sanoen: makaa minun kanssani. Mutta hän jätti hameensa hänen käteensä, ja pakeni, ja meni ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Koska hän näki, että hän jätti hameensa hänen käteensä, ja pakeni ulos:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Huusi hän perhettänsä, ja sanoi heille: katsokaat, hän on tuonut meille yhden Hebrealaisen miehen, saattamaan meitä häpiään: hän tuli minun tyköni makaamaan minun kanssani; mutta minä huusin korkialla äänellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Ja koska hän kuuli, että minä riahdin ja huusin, jätti hän minulle hameensa, pakeni ja meni ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Niin hän piti hänen hameensa tykönänsä, siihenasti kuin hänen isäntänsä kotia tuli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Ja puhui hänelle ne sanat, sanoen: Hebrealainen palvelia, jonkas olet meille tuonut, tuli minun tyköni, saattamaan minua häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Mutta koska minä riahdin ja huusin, jätti hän minulle hameensa ja pakeni ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Koska hänen isäntänsä kuuli emäntänsä sanat, kuin hän puhui hänelle, sanoen: niin on sinun palvelias tehnyt minulle, vihastui hän sangen kovin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Ja hänen isäntänsä otti Josephin, ja pani vankihuoneesen, jossa kuninkaan vangit olivat: ja niin hän oli siellä vankihuoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mutta Herra oli Josephin kanssa, ja käänsi laupiutensa hänen tykönsä; ja antoi hänen löytää armon vankihuoneen haltian edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Niin että hän antoi kaikki vangit vankihuoneessa Josephin käden alle, että kaikki mitä siellä tehtiin, se tehtiin hänen kauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Ja vankihuoneen haltia ei pitänyt mistään murhetta niistä, jotka hänen kädessänsä olivat; sillä Herra oli Josephin kanssa, ja mitä hän teki, antoi Herra menestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Ja sitte tapahtui, että Egyptin kuninkaan ylimmäinen juomanlaskia ja leipoja rikkoivat herraansa Egyptin kuningasta vastaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Niin Pharao vihastui molempain palveliainsa, ylimmäisen juomanlaskian ja ylimmäisen leipojan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Ja heitti heidät vankiuteen huovinhaltian huoneesen, vankihuoneesen siihen paikkaan, jossa Joseph oli vankina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Ja huovinhaltia pani Josephin heidän kanssansa palvelemaan heitä. Ja he olivat vankiudessa kappaleen aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Ja molemmat näkivät unta, kumpikin unensa yhtenä yönä, kukin unensa selityksen jälkeen, Egyptin kuninkaan juomanlaskia ja leipoja, jotka olivat sidottuna vankihuoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Koska Joseph tuli aamulla heidän tykönsä, ja näki heidän murheelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Kysyi hän niiltä Pharaon palvelioilta, jotka hänen kanssansa herransa vankihuoneessa olivat, ja sanoi: miksi te olette tänäpänä surulliset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'He vastasivat häntä: me olemme nähneet unta, ja ei ole, joka sen selittää. Niin sanoi Joseph heille: Jumalan on selitys, kuitenkin jutelkaat se minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Niin ylimmäinen juomanlaskia jutteli unensa Josephille, ja sanoi hänelle: minä näin unta ja katso, viinapuu oli minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Ja sillä viinapuulla oli kolme haaraa ja se oli niinkuin viheriöitsemällänsä, sen kukoistus kävi ylös, ja sen rypäleet tuleentuivat viinamarjoiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Ja Pharaon juoma-astia oli minun kädessäni: niin minä otin viinamarjat, ja pusersin ne Pharaon juomaastiaan, ja annoin sen juoma-astian Pharaon käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Ja Joseph sanoi hänelle: tämä on sen selitys: Kolme haaraa ovat kolme päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Kolmen päivän sisällä korottaa Pharao sinun pääs, ja asettaa sinun jällensä entiseen virkaas: ja sinä annat Pharaon käteen juoma-astian niinkuin ennenkin, koska olit hänen juomansa laskia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mutta muista minua tykönäs, koska sinun hyvin käy, ja tee sitte laupius minun kanssani, ettäs ilmoittaisit minun Pharaolle, ja antaisit minun ottaa täältä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Sillä minä olen salaisesti varastettu Hebrealaisten maalta; enkä ole tässä mitään tehnyt, että he minun tähän vankiuteen panivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Koska ylimmäinen leipoja näki, että selitys oli hyvä; sanoi hän Josephille: minä myös uneksuin, ja katso, kolme palmikoittua koria oli minun pääni päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Ja ylimmäisessä korissa oli kaikkinaisia leivotuita ruokia Pharaon tarpeeksi: ja linnut söivät niitä korista minun pääni päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Joseph vastasi, ja sanoi: tämä on sen selitys: kolme koria ovat kolme päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Ja kolmen päivän sisällä ylentää Pharao sinun pääs, ja ripustaa sinun hirsipuuhun: ja linnut syövät sinun lihas sinun päältäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Ja tapahtui kolmantena päivänä, koska Pharao piti syntymäpäiväänsä, teki hän pidon kaikille palvelioillensa, ja ylensi ylimmäisen juomanlaskian pään, ja ylimmäisen leipojan pään palvelioittensa seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Ja asetti ylimmäisen juomanlaskian jälleen (entiseen) virkaansa, antamaan Pharaon käteen juomaastian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Mutta ylimmäisen leipojan antoi hän hirttää; niinkuin Joseph oli heille selittänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Mutta ylimmäinen juomanlaskia ei muistanut Josephia, vaan unhotti hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Ja tapahtui kahden ajastajan perästä, että Pharao näki unen, niinkuin hän olis seisonut virran tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Ja katso, virrasta astui ylös seitsemän kaunista ja lihavaa lehmää, jotka kävivät laitumella ruohostossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Sitte näki hän toiset seitsemän lehmää tulevan virrasta ylös, rumaa ja laihaa; ja seisoivat niiden (toisten) lehmäin tykönä virran reunalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Ja ne rumat ja laihat lehmät söivät ne seitsemän lihavaa ja kaunista lehmää. Niin Pharao heräsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Ja hän nukkui jällensä, ja näki toisen kerran unta: ja katso, seitsemän täysinäistä ja paksua tähkäpäätä kasvoivat yhdessä oljessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Ja katso, seitsemän pientä ja itätuulelta surkastunutta tähkäpäätä kasvoivat niiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Ja ne seitsemän laihaa tähkää nielivät ne seitsemän paksua ja täysinäistä tähkäpäätä. Niin Pharao heräsi ja näki, että se oli uni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Ja aamulla oli hänen henkensä murheellinen, lähetti ja antoi kutsua kokoon kaikki Egyptin noidat ja tietäjät, ja Pharao jutteli heille unensa. Mutta ei ollut, joka sen taisi selittää Pharaon edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Niin puhui ylimmäinen juomanlaskia Pharaolle, sanoen: minä muistan tänäpänä minun rikokseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Koska Pharao vihastui palveliainsa päälle, ja pani minun ja ylimmäisen leipojan vankiuteen, huovinhaltian huoneesen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Niin me molemmat näimme yhtenä yönä unta, kumpikin unensa selityksen jälkeen me uneksuimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Ja siellä oli meidän kanssamme Hebrealainen nuorukainen, huovinhaltian palvelia, ja me juttelimme hänelle, ja hän selitti meille meidän unemme: kummallekin unensa jälkeen selitti hän sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Ja niinkuin hän meille selitti, niin se tapahtui: sillä minä asetettiin minun virkaani ja hän hirtettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Niin lähetti Pharao, ja antoi kutsua Josephin, ja he hopusti ottivat hänen vankiudesta ulos. Ja hän antoi itsensä keritä, ja muutti vaattensa ja tuli Pharaon tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Niin sanoi Pharao Josephille: minä olen unta nähnyt, ja ei ole sen selittäjää; mutta minä olen kuullut sinusta sanottavan: koskas unen kuulet, niin sinä taidat sen selittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joseph vastasi Pharaota, sanoen: ei se ole minulla; mutta Jumala aavistaa kuitenkin Pharaolle hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Niin puhui Pharao Josephille: unessa olin minä seisovana virran reunalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Ja katso, virrasta tuli ylös seitsemän lihavaa ja kaunista lehmää, jotka kävivät laitumella ruohostossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Ja katso, heidän jälkeensä tulivat ylös toiset seitsemän pientä ja juuri rumaa ja laihaa lehmää: en ole minä koko Egyptin maalla nähnyt niin rumia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Ja ne laihat ja rumat lehmät söivät ne ensimäiset seitsemän lihavaa lehmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Ja koska he olivat syöneet, ei heidän päällänsä mitään tuntunut, että he olivat syöneet; vaan olivat niin rumat nähdä kuin ennenkin. Niin minä heräsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Ja taas näin minä unessani seitsemän tähkäpäätä kasvaneen yhdessä oljessa, täysinäistä ja kaunista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Sitte kävi ylös seitsemän kuivaa, pientä ja itätuulelta surkastunutta tähkäpäätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Ja ne pienet tähkäpäät nielivät ne seitsemän kaunista tähkäpäätä. Ja minä olen sen sanonut tietäjille, mutta ei ole joka sen minulle ilmoittais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Joseph sanoi Pharaolle: Pharaon uni on yhtäläinen: Jumala ilmoittaa Pharaolle, mitä hän tekevä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Ne seitsemän kaunista lehmää ovat seitsemän vuotta, ja ne seitsemän täysinäistä tähkäpäätä ovat myös seitsemän vuotta: se on yhtäläinen uni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Mutta ne seitsemän laihaa ja rumaa lehmää, jotka astuivat ylös heidän jälkeensä, ovat seitsemän vuotta, ja ne seitsemän laihaa ja itätuulelta surkastunutta tähkäpäätä ovat seitsemän nälkävuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Se on nyt se, kuin minä Pharaolle sanonut olen: että Jumala ilmoitti Pharaolle, mitä hän tekevä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Katso, seitsemän viljaista vuotta tulevat koko Egyptin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Ja niiden jälkeen tulevat seitsemän nälkävuotta, niin että kaikki senkaltainen viljan kyllyys unhotetaan Egyptin maalla, ja se kallis aika hävittää maakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Ja ei enämpi tiedetä siitä viljan kyllyydestä maakunnassa, sen kalliin ajan tähden, joka tulee; sillä se tulee sangen raskaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Mutta että uni on kerrottu Pharaolle, se (aavistaa) että asia on Jumalalta päätetty, ja Jumala on pian sen tekevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nyt siis Pharao etsikään toimellista ja taitavaa miestä, asettaaksensa Egyptin maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Toimittakaan Pharao ja asettakaan ottomiehiä maakuntaan, ja ottakaan viidennen osan Egyptin maalta niinä seitsemänä viljavuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Ja he kootkaan kaikkinaista ravintoa niinä hyvinä vuosina, jotka tulevat, ja antakaan tulla jyviä Pharaon haltuun, varaksi kaupungeissa, ja tallella pitäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Että ruokaa olis tähteelle pantu maakunnalle, niinä seitsemänä nälkävuonna, jotka tulevat Egyptin maalle, ettei maa hävitettäisi näljän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Ja se puhe kelpasi Pharaolle, ja kaikille hänen palvelioillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Ja Pharao sanoi palvelioillensa: taidammeko me löytää tainkaltaisen miehen, jossa Jumalan henki on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Ja Pharao sanoi Josephille: että Jumala on tämän kaiken sinulle ilmoittanut, niin ei ole yhtään niin taitavaa ja ymmärtäväistä kuin sinä olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ole sinä minun huoneeni päällä, ja sinun sanalles pitää kaiken minun kansani kuuliaisen oleman; ainoastansa kuninkaallisessa istuimessa tahdon minä olla korkiampi sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Ja Pharao sanoi Josephille: katso, minä olen asettanut sinun koko Egyptin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Ja Pharao otti sormuksen kädestänsä, ja pani sen Josephin käteen: ja puetti hänen kalleisiin liinavaatteisiin, ja ripusti kultakäädyt hänen kaulaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Ja antoi hänen ajaa toisessa vaunussansa, ja antoi huutaa hänen edellänsä: Abrek: ja asetti hänen koko Egyptin maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Ja Pharao sanoi Josephille: minä olen Pharao; ja ilman sinun tahdotas ei pidä yhdenkään ylentämän kättänsä taikka jalkaansa koko Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Ja Pharao kutsui Josephin nimen Salaisuutten selittäjäksi: ja antoi hänelle Asnatin, Potipheran Onin papin tyttären, emännäksi. Niin Joseph meni ympärinsä Egyptin maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Ja Joseph oli kolmenkymmenen ajastaikainen, koska hän seisoi Pharaon, Egyptin kuninkaan edessä. Ja Joseph läksi Pharaon tyköä, ja vaelsi ympärinsä kaiken Egyptin maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Ja maa kasvoi pivottaisin niinä seitsemänä viljavuosina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Ja hän kokosi niinä seitsemänä vuonna kaikkinaisen elatuksen, joka oli Egyptin maalla, ja pani sen tähteelle kaupunkeihin: mitä elatusta maa kasvoi ympärinsä kunkin kaupungin, sen hän siihen tähteelle pani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Ja Joseph kokosi sangen paljon jyviä, niinkuin santaa meressä, siihenasti että hän lakkasi lukemasta, sillä ne olivat epälukuiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Ja Josephille syntyi kaksi poikaa, ennenkuin kallis aika tuli, jotka hänelle synnytti Asnat, Potipheran Onin papin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Ja kutsui esikoisensa nimen Manasse; sillä (sanoi hän) Jumala on antanut minun unhottaa kaiken minun vaivani, ja kaiken minun isäni huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Mutta toisen nimen hän kutsui Ephraim; sillä (sanoi hän) Jumala on tehnyt minun hedelmälliseksi minun raadollisuuteni maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Koska ne seitsemän viljavuotta olivat kuluneet Egyptin maalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Rupesivat ne seitsemän nälkävuotta tulemaan, niinkuin Joseph oli (edellä) sanonut: ja nälkä tuli kaikkiin maakuntiin; mutta koko Egyptin maalla oli leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Kuin Egyptin maa myös kärsi nälkää, huusi kansa Pharaon tykö leivän tähden. Mutta Pharao sanoi kaikille Egyptiläisille: menkäät Josephin tykö; mitä hän sanoo teille, se tehkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Koska nälkä tuli koko maakuntaan, avasi Joseph kaikki jyväaitat jokapaikassa, ja myi Egyptiläisille; sillä nälkä tuli aina raskaammaksi Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Ja kaikki maakunnat tulivat Egyptiin ostamaan Josephilta; sillä suuri nälkä oli kaikissa maakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Mutta koska Jakob näki olevan jyviä myydä Egyptissä, sanoi hän pojillensa: mitä te katselette toinen toisenne päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Ja sanoi: katso, minä kuulen Egyptissä olevan jyviä; menkäät alas sinne, ja ostakaat meille sieltä, että me eläisimme, ja emme kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Niin menivät kymmenen Josephin veljeä alas, ostamaan jyviä Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mutta BenJaminia, Josephin veljeä, ei lähettänyt Jakob veljiensä kanssa; sillä hän sanoi: ettei hänelle vahinkoa tapahtuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Niin läksivät Israelin lapset matkaan (jyviä) ostamaan muiden seurassa; sillä nälkä oli Kanaanin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Mutta Joseph oli hallitsia maakunnassa, hän antoi myydä jyviä kaikelle maan kansalle. Niin tulivat Josephin veljet, ja kumarsivat maahan kasvoillensa hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Ja Joseph näki veljensä, ja tunsi heidät, ja teeskeli hänensä oudoksi heitä vastaan, ja puhui kovasti heidän kanssansa, ja sanoi heille: kusta te tulette? He vastasivat: Kanaanin maalta, ostamaan syötävää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Ja Joseph tunsi veljensä, vaan ei he häntä tunteneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Niin Joseph muisti unensa, jotka hän oli nähnyt heistä; ja sanoi heille: te olette vakojat, ja olette tulleet katsomaan, kusta maa avojoin olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'He vastasivat häntä: ei minun herrani: mutta sinun palvelias ovat tulleet ostamaan jyviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Me olemme kaikki yhden miehen pojat: me olemme vaat, eikä sinun palvelias ole ikänänsä olleet vakojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Hän sanoi heille: ei suinkaan, mutta te olette tulleet katsomaan, kusta maa avojoin olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'He sanoivat: me sinun palvelias olimme kaksitoistakymmentä veljestä, yhden miehen pojat Kanaanin maalla; ja katso, nuorin on nyt meidän isämme tykönä, mutta yksi ei ole sillen eleillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joseph sanoi heille: sepä se on, kuin minä olen teille puhunut, sanoen: vakojat te olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Siinä teitä pitää koeteltaman. Niin totta kuin Pharao elää, ei teidän pidä täältä pääsemän, jollei teidän nuorin veljenne tule tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Lähettäkäät yksi teistänne, joka tuo teidän veljenne tänne: mutta teidän pitää vankina oleman, niin teidän puheenne koetellaan, jos teissä totuus on; mutta jollei, niin totta kuin Pharao elää, te olette vakojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Niin hän pani heidät kiinni kolmeksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Ja kolmantena päivänä sanoi Joseph heille: jos te tahdotte elää, niin tehkäät näin; sillä minä pelkään Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Jos te olette vaat, niin antakaat yksi teidän veljistänne olla sidottuna teidän vankihuoneessanne; mutta menkäät te ja viekäät kotia, mitä te ostaneet olette nälkää vastaan kotonanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Ja tuokaat teidän nuorin veljenne minun tyköni, että teidän sananne todeksi löyttäisiin, ettette kuolisi; ja he tekivät niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Mutta he sanoivat toinen toisellensa: me olemme totisesti vianalaiset meidän veljemme tähden; sillä me näimme hänen sielunsa ahdistuksen, koska hän meiltä armoa rukoili, ja emme kuulleet häntä; sentähden on tämä ahdistus meidän päällemme tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruben vastasi heitä, sanoen: enkö minä puhunut teille, sanoen: älkäät tehkö vääryyttä nuorukaiselle, ja ette tahtoneet kuulla? Ja nyt hänen verensä meiltä vaaditaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Vaan ei he tietäneet Josephin sitä ymmärtävän; sillä hän puhui heille tulkin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Ja hän käänsi itsensä heistä, ja itki. Koska hän jällensä käänsi heidän puoleensa ja puhutteli heitä, otti hän Simeonin heiltä, ja sitoi hänen heidän nähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Ja Joseph käski heidän säkkinsä täytettää jyvillä, ja annettaa heidän rahansa jälleen itsekunkin omaan säkkiinsä, ja annettaa heille evästä matkalle; ja heille tehtiin niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Ja he panivat kalunsa aaseinsa päälle, ja läksivät sieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Koska yksi heistä avasi säkkinsä, antaaksensa ruokaa aasillensa, ja äkkäsi rahansa säkkinsä suussa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Ja sanoi veljillensä: minulle on annettu minun rahani jällensä, katso, se on minun säkissäni. Niin heidän sydämensä vavahtui, ja hämmästyivät keskenänsä, sanoen: miksi on Jumala meille näin tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Koska he tulivat isänsä Jakobin tykö Kanaanin maalle, ilmoittivat he hänelle kaikki, mitä heille tapahtunut oli, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Se mies, sen maan herra, puhui kovasti meille, ja piti meitä maan vakojina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Ja me vastasimme häntä: me olemme vaat, emme ole ikänänsä oleet vakoojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Me olimme kaksitoistakymmentä veljestä meidän isämme poikaa: yksi ei ole silleen eleissä, ja nuorin on nyt isämme tykönä Kanaanin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Sanoi se mies, sen maan herra meille: siitä minä tunnen, jos te olette vaat: yksi teidän veljistänne jättäkäät minun tyköni, ja ottakaat teidän taloinne tarve, ja menkäät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Ja tuokaat teidän nuorin veljenne minun tyköni, niin minä ymmärrän, ett\'ette ole vakojat, vaan vaat; niin annan minä myös teidän veljenne jälleen, ja saatte tehdä kauppaa tässä maakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Ja tapahtui, koska he tyhjensivät säkkejänsä, katso, oli itsekunkin rahakäärö hänen säkissänsä: ja kuin he näkivät rahakäärönsä, hämmästyivät he isänsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Niin sanoi Jakob heidän isänsä heille: te olette saattaneet minun lapsettomaksi: Joseph ei ole elävissä, eikä Simeon, Ja Benjaminin tahdotte te vielä viedä pois; minun kohtaani nämät kaikki tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruben vastasi isällensä, sanoen: tapa molemmat minun poikani, jollen minä häntä jälleen sinulle (kotia) tuo, ainoastansa anna häntä minun haltuuni, minä hänen sinulle jälleen (kotia) tuon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Hän sanoi: ei minun poikani pidä menemän alas teidän kanssanne: sillä hänen veljensä on kuollut, ja hän on jäänyt yksin, ja jos hänelle tapahtuis jotakin pahaa tiellä, jota te vaellatte, niin te saatatte minun harmaat karvani murheella hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Mutta kallis aika ahdisti maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Ja koska he loppuivat syödä ne jyvät kuin he Egyptistä tuoneet olivat, sanoi heidän isänsä heille: menkäät jällensä sinne, ja ostakaat meille jotakin elatusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Niin vastasi häntä Juuda, sanoen: se mies haastoi meitä sangen kovin, ja sanoi: ei pidä teidän näkemän minun kasvojani, jollei teidän veljenne ole teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Jos siis sinä nyt lähetät meidän veljemme meidän kanssamme, niin me menemme alas ja ostamme sinulle elatusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Vaan jolles häntä lähetä, niin emme mekään mene; sillä se mies sanoi meille: ei teidän pidä näkemän minun kasvojani, jollei teidän veljenne ole teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel sanoi: miksi te teitte minua vastaan niin pahoin, että te sanoitte sille miehelle teillänne vielä olevan veljen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'He vastasivat: se mies kysyi meistä niin visusti, ja meidän suvustamme, sanoen: vieläkö teidän isänne elää? Onko teillä vielä veljeä? Niin me vastasimme häntä kuin hän kysyi. Taitaisimmeko me ratki tietää hänen sanovan: tuokaat veljenne tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Niin sanoi Juuda isällensä Israelille: lähetä nuorukainen minun kanssani, niin me valmistamme ja lähdemme matkaan: että me eläisimme ja emme kuolisi, sekä me että sinä ja meidän lapsemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Minä takaan hänen edestänsä, kaipaa häntä minun käsistäni; jollen minä tuo häntä jälleen sinun tykös, ja pane häntä sinun etees, niin minä olen vikapää sinun edessäs kaikkena minun elinaikanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Sillä jollei meillä olisi ollut viivytystä, totisesti me olisimme jo toisen kerran tulleet jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Niin sanoi Israel heidän isänsä heille: jos nyt kumminkin niin pitää oleman, tehkäät siis näin: ottakaat maan parhaista hedelmistä teidän astioihinne, ja viekäät sille miehelle lahjoja: jotakin mastiksia ja hunajaa, ja styraksia, ja ladanumia, ja dadelia ja mandelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Ottakaat myös toinen raha teidän myötänne, ja se raha, jonka te toitte jällensä säkkein suussa, viekäät myötänne; taitaa olla, että se on epähuomiosta tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Ottakaat myös teidän veljenne; ja valmistakaat, ja menkäät jälleen sen miehen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Jumala kaikkivaltias antakoon teidän löytää laupiuden sen miehen edessä, että hän päästäis jälleen teille toisen teidän veljenne, ja (tämän) BenJaminin. Mutta minä, niinkuin minä olen lapsettomaksi joutunut, olen lapsetonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Niin ottivat miehet nämät lahjat, ja ottivat kaksi sen vertaa rahaa myötänsä, ja BenJaminin: valmistivat itsensä ja menivät Egyptiin, ja seisoivat Josephin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Ja kun Joseph näki BenJaminin heidän kanssansa, sanoi hän huoneensa haltialle: vie nämät miehet huoneesen, ja tee ja teurasta ja valmista; sillä heidän pitää minun kanssani päivällistä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Ja se mies teki niinkuin Joseph oli hänelle käskenyt, ja vei miehet Josephin huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Ja he pelkäsivät, että he vietiin Josephin huoneesen, ja sanoivat: me viedään tänne sen rahan tähden jonka me tätä ennen löysimme meidän säkeistämme: että hän soimais meitä, ja saattais meitä oikeuden alle, ja ottais meitä orjiksensa, ja meidän aasimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Sentähden he menivät Josephin huoneenhaltian tykö, ja puhuttelivat häntä huoneen oven edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Ja sanoivat: ah, minun herrani, me olimme ennen tänne tulleet ostamaan jyviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Ja koska me tulimme yösialle, ja avasimme meidän säkkimme, katso, niin oli itsekunkin raha säkkinsä suussa täydellä painolla: sentähden olemme me ne jällensä myötämme tuoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Olemme myös toisen rahan myötämme tuoneet ostaaksemme jyviä; emme sitä tiedä, kuka on pannut jällensä meidän rahamme meidän säkkiimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Mutta hän sanoi: olkaat hyvässä turvassa, älkäät peljätkö: teidän Jumalanne ja teidän isänne Jumala on teille tavaran antanut teidän säkkiinne: teidän rahanne olen minä saanut. Ja hän toi Simeonin heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Ja se mies vei heidät Josephin huoneesen, antoi heille vettä pestä heidän jalkojansa, ja antoi ruokaa heidän aaseillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Mutta he valmistivat lahjojansa, siihen asti kuin Joseph tuli päivälliselle; sillä he olivat kuulleet, että heidän piti siellä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Koska Joseph tuli huoneesen, kantoivat he lahjoja huoneesen hänelle käsissänsä, ja kumarsivat maahan hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Ja hän tervehti heitä rakkaasti, ja sanoi: onko teidän vanha isänne rauhassa, josta te minulle sanoitte? Vieläkö hän elää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'He vastasivat: sinun palvelias meidän isämme on rauhassa, ja elää vielä; ja he kumarsivat ja maahan lankesivat hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Niin hän nosti silmänsä ja näki veljensä BenJaminin, äitinsä pojan, ja sanoi: onko tämä teidän nuorin veljenne, josta te sanoitte minulle? Ja sanoi vielä: Jumala olkoon sinulle armollinen, minun poikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Ja Joseph kiiruhti itsensä; sillä hänen sydämensä paloi veljeänsä kohtaan, ja etsi siaa itkeäksensä; ja meni kamariinsa, ja itki siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Ja kuin hän oli pessyt kasvona, tuli hän ulos; ja pidätti itsensä, ja sanoi: tuokaat leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Ja pantiin erinänsä hänelle ja erinänsä heille, niin myös Egyptiläisille, jotka hänen kanssansa atrioitsivat, erinänsä; sillä Egyptiläiset ei saa syödä Hebrealaisten kanssa, sillä se on Egyptiläisille kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Ja he istutettiin hänen kohdallensa, esikoinen esikoisuutensa jälkeen, ja nuorin nuoruutensa jälkeen: sitä miehet ihmettelivät keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Ja heille kannettiin ruokaa hänen pöydältänsä, mutta BenJaminille viisi kertaa enemmän kuin muille. Ja he joivat ja juopuivat hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Ja Joseph käski huoneensa haltiaa, sanoen: täytä miesten säkit jyvillä, niin paljo kuin he voivat kannattaa, ja pane itsekunkin raha säkkinsä suuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Ja minun maljani, se hopiamalja pane nuorimman säkin suuhun, ynnä jyväinsä hinnan kanssa. Ja hän teki niinkuin Joseph hänelle käski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Mutta aamulla päivän valjetessa, päästettiin miehet menemään aaseinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Ja koska he olivat lähteneet kaupungista, eikä vielä kauvas joutuneet, sanoi Joseph huoneensa haltialle: nouse ja aja takaa miehiä, ja koska heidän saat takaa, niin sano heille: miksi te olette hyvän pahalla maksaneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Eikö se ole, josta minun herrani juo? Ja josta hän kyllä hyvin taitaa arvata teistä? Te olette pahoin tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Ja kuin hän käsitti heidät, puhui hän nämät sanat heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'He vastasivat häntä: miksi minun herrani senkaltaista puhuu? Pois se, että sinun palvelias niin tekisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Katso, rahan, jonka me löysimme säkkeimme suusta, olemme me jälleen sinulle tuoneet Kanaanin maalta: kuinkasta siis me varastimme hopiaa eli kultaa sinun herras huoneesta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Jonka tyköä sinun palvelioiltas se löydetään, hän kuolkaan: niin tahdomme me myös olla orjat minun herralleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Hän sanoi: olkaan nyt teidän sananne jälkeen: jonka tyköä se löydetään, hän olkaan minun orjani; mutta te olette vapaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Ja he laskivat kiiruusti itsekukin säkkinsä maahan, ja jokainen avasi säkkinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Ja hän etsei, ruveten vanhimmasta niin nuorimpaan asti; ja hopiamalja löydettiin BenJaminin säkistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Niin repäisivät vaatteensa, ja itsekukin pani kuormansa aasin päälle, ja palasivat kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Ja Juuda meni veljinensä Josephin huoneesen (sillä hän oli vielä silloin siellä); ja he lankesivat maahan hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Joseph sanoi heille: mikä työ se on, kuin te tehneet olette? Ettekö te tietäneet, että senkaltainen mies kuin minä olen taitaa kyllä hyvin arvata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Ja Juuda sanoi: mitä me vastaamme minun herralleni? Taikka mitä me puhumme? Taikka millä me taidamme itsemme puhdistaa? Jumala on löytänyt sinun palveliais vääryyden: katso, me olemme meidän herramme orjat, sekä me, että se, jolta malja löydettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Mutta hän sanoi: pois se, että minä niin tekisin; sen miehen, jolta malja on löydetty, pitää oleman minun orjani; mutta menkäät te rauhassa isänne tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Niin Juuda astui hänen tykönsä, ja sanoi: ah minun herrani, suo nyt palvelias puhua yksi sana minun herrani korvissa, ja älkään julmistuko sinun vihas sinun palvelias päälle, sillä sinä olet niinkuin Pharao.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Minun herrani kysyi hänen palvelioiltansa, sanoen: onko teillä isää taikka veljeä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Niin me vastasimme meidän herraamme: meillä on vanha isä, ja nuorukainen syntynyt hänen vanhalla ijällänsä, jonka veli on kuollut, ja hän on yksinänsä jäänyt äidistänsä, ja hänen isänsä pitää hänen rakkaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Niin sinä sanoit palvelioilles: tuokaat häntä tänne minun tyköni, että minä saan nähdä hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Mutta me vastasimme minun herralleni: ei taida nuorukainen jättää isäänsä; sillä jos hän jättäis isänsä, niin hän kuolis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Niin sinä sanoit palvelioilles. jollei teidän nuorin veljenne tule teidän kanssanne, niin ei teidän pidä enää minun kasvojani näkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Ja koska me menimme sinun palvelias minun isäni tykö, ja ilmoitimme hänelle minun herrani sanat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Niin sanoi meidän isämme: menkäät jälleen pois, ja ostakaat meille jotakin elatusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Mutta me sanoimme: emme tohdi sinne mennä; vaan jos meidän nuorin veljemme on meidän kanssamme, niin me menemme; sillä emme saa nähdä sen miehen kasvoja, jollei meidän nuorin veljemme ole meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Niin sinun palvelias minun isäni sanoi meille: te tiedätte, että minun emäntäni synnytti minulle kaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Ja toinen läksi minun tyköäni, josta sanottiin, että hän on kuoliaaksi revelty, ja en ole minä häntä vielä sitte nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Jos te tämän myös minulta viette pois, ja hänelle tapahtuis jotakin pahaa, niin te saattaisitte minun harmaat karvani murheella hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Jos minä nyt tulisin sinun palvelias minun isäni tykö, ja ei olisi nuorukainen meidän kanssamme: sillä hänen henkensä riippuu tämän hengestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Niin tapahtuis, koska hän näkis, ettei nuorukainen kanssa olisi, että hän kuolis; niin me sinun palvelias saattaisimme sinun palvelias meidän isämme harmaat karvat murheella hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Sillä sinun palvelias on taannut nuorukaisen minun isäni edessä, sanoen: jollen minä häntä tuo jällensä sinun tykös, niin minä sen edestä kaiken minun elinaikani olen vikapää kärsimään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Ja nyt siis jääkään sinun palvelias nuorukaisen edestä minun herralleni orjaksi: vaan nuorukainen menkään veljeinsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Sillä kuinka minä taidan mennä minun isäni tykö, jollei nuorukainen olisi minun kanssani? Etten minä näkisi sitä surkeutta, johon minun isäni joutuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Niin ei Joseph voinut itseänsä silleen pidättää kaikkein niiden edessä, jotka hänen tykönänsä seisoivat, ja hän huusi: menkäät ulos kaikki minun tyköäni; ja ei yksikään seisonut hänen tykönänsä, koska Joseph itsensä ilmoitti veljillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Ja itki korkealla äänellä, niin että Egyptiläiset ja Pharaon perhe sen kuulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Ja Joseph sanoi veljillensä: minä olen Joseph. Vieläkö minun isäni elää? Mutta ei hänen veljensä taitaneet häntä vastata; sillä he olivat niin hämmästyneet hänen kasvoinsa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Niin sanoi Joseph veljillensä: tulkaat siis minun tyköni. Ja he tulivat. Ja hän sanoi: minä olen Joseph teidän veljenne, jonka te myitte Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Ja nyt, älkäät surulliset olko, ja älkäät niin kovin hämmästykö, että te olette minua tänne myyneet; sillä teidän henkenne elatuksen tähden on Jumala minun teidän edellänne tänne lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Kaksi nälkävuotta on jo ollut maassa, ja vielä nyt on viisi vuotta, niin ettei kynnetä eikä niitetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Mutta Jumala on minun lähettänyt teidän edellänne, tallella pitämään teitä maan päällä, ja elättämään teitä suuren pelastuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Ja nyt ette ole minua tänne lähettäneet, vaan Jumala, joka myös minun asetti isäksi Pharaolle, ja herraksi kaiken hänen huoneensa päälle, ja koko Egyptin maan esimieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Rientäkäät ja menkäät minun isäni tykö, ja sanokaat hänelle: näin sanoo sinun poikas Joseph: Jumala on minun asettanut koko Egyptin maan herraksi, tule alas minun tyköni, ja älä viivyttele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Ja sinä olet asuva Gosenin maassa, ja olet oleva juuri läsnä minua, sinä ja sinun lapses ja sinun lastes lapset, sinun karjas, pienet ja suuret, ja kaikki mitä sinulla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Siellä minä elätän sinua, vielä on viisi nälkävuotta, ettet sinä ja sinun huonees, ja kaikki kuin sinulla on, hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Ja katso, teidän silmänne näkevät, ja minun veljeni BenJaminin silmät, että minä puhun teidän kanssanne suusta suuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Ja ilmoittakaat minun isälleni kaikki minun kunniani Egyptissä, ja kaikki mitä te nähneet olette. Rientäkäät siis ja tuokaat minun isäni tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Ja hän halasi veljeänsä BenJaminia kaulasta ja itki, ja BenJamin myös itki hänen kaulassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Ja hän antoi suuta kaikille veljillensä, ja itki heidän ylitsensä; ja sitte puhuivat hänen veljensä hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Koska se sanoma kuului Pharaon huoneesen, nimittäin, että Josephin veljet tulleet olivat, oli se hyvä Pharaon mielestä, ja kaikkein hänen palveliainsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Ja Pharao sanoi Josephille: sano veljilles, tehkäät näin: sälyttäkäät teidän juhtainne päälle, ja menkäät matkaanne; ja kuin te tulette Kanaanin maalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Niin ottakaat teidän isänne, ja teidän perheenne ja tulkaat minun tyköni: minä annan teille Egyptin maan hyvyyden, ja te syötte maan ytimen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Ja käske heitä: tehkäät niin, ottakaat teillenne vaunut Egyptin maalta teidän lapsillenne, ja emännillenne, ja tuokaat teidän isänne ja tulkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Älkäät myös totelko teidän talonne kappaleita: sillä kaikki Egyptin maan hyvyys pitää teidän oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Ja Israelin lapset tekivät niin, ja Joseph antoi heille vaunut Pharaon käskyn jälkeen, ja antoi myös heille evään matkalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Ja antoi heille kaikille itsekullekin muutinvaatteet, mutta BenJaminille antoi hän kolmesataa hopiapenninkiä, ja viidet muutinvaatteet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Mutta isällensä lähetti hän kymmenen aasia sälytettyä Egyptin hyvyydellä, ja kymmenen aasintammaa, kannattaen jyviä ja leipää ja evästä isällensä matkalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Niin hän lähetti veljensä matkaan, ja sanoi heille: älkäät riidelkö tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Niin he läksivät Egyptistä, ja tulivat Kanaanin maalle isänsä Jakobin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Ja ilmoittivat hänelle, sanoen: vielä Joseph elää, ja on koko Egyptin maan herra; ja hänen sydämensä hämmästyi, sillä ei hän uskonut heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Niin he sanoivat hänelle kaikki Josephin sanat, kuin hän heille puhunut oli. Ja kuin hän näki vaunut, jotka Joseph oli lähettänyt häntä tuomaan, niin Jakobin, heidän isänsä henki virkosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Ja Israel sanoi: nyt minulla kyllä on, että minun poikani Joseph vielä elää: minä menen häntä katsomaan ennekuin minä kuolen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Niin läksi Israel kaiken sen kanssa kuin hänellä oli, ja koska hän tuli BerSabaan, uhrasi hän uhria isänsä Isaakin Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Ja Jumala puhui yöllä näyssä Israelille, sanoen: Jakob, Jakob. Hän vastasi: tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Ja hän sanoi: Minä olen Jumala, sinun isäs Jumala: älä pelkää mennä Egyptiin: sillä minä teen sinun siellä suureksi kansaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Minä menen Egyptiin sinun kanssas, ja minä jällensä sinun sieltä johdatan. Ja Joseph laskee kätensä sinun silmäis päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Ja Jakob läksi BerSabasta: ja Israelin lapset veivät isänsä Jakobin ynnä lastensa ja emäntäinsä kanssa, vaunuissa, jotka Pharao oli häntä tuomaan lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Ja he ottivat karjansa ja tavaransa, jotka he olivat koonneet Kanaanin maalla, ja tulivat Egyptiin, Jakob ja kaikki hänen siemenensä hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Hänen poikansa ja hänen poikainsa pojat hänen kanssansa, hänen tyttärensä ja hänen lastensa tyttäret, ja kaikki hänen siemenensä, vei hän kanssansa Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Ja nämät ovat Israelin lasten nimet, jotka tulivat Egyptiin: Jakob ja hänen poikansa. Jakobin esikoinen Ruben.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Ja Rubenin lapset: Hanok, Pallu, Hetsron ja Karmi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeonin lapset: Jemuel, Jamin, Ohad, Jakin, Zohar: niin myös Saul, Kananean vaimon poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Levin lapset: Gerson, Kahat ja Merari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Juudan lapset: Ger, Onan, Sela, Perets ja Sera. Mutta Ger ja Onan kuolivat Kanaanin maalla. Ja Peretsin pojat olivat: Hetsron ja Hamul.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Ja Isaskarin lapset: Tola, Phua, Job ja Simron.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Ja Sebulonin lapset: Sered, Elon ja Jahleel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Nämät ovat Lean lapset, jotka hän synnytti Jakobille Mesopotamiassa, ja Dinan hänen tyttärensä. Kaikki hänen poikansa ja tyttärensä olivat kolmeneljättäkymmentä henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gadin lapset: Ziphion, Haggi, Suni, Etsbon, Eri, Arodi ja Areli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Asserin lapset: Jemna, Jesua, Jesui, Bria ja Sera heidän sisarensa. Mutta Brian lapset: Heber ja Malkiel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Nämät ovat Silpan lapset, jonka Laban antoi tyttärellensä Lealle, ja hän synnytti Jakobille nämät kuusitoistakymmentä henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Rakelin Jakobin emännän lapset: Joseph ja BenJamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Ja Josephille olivat syntyneet Egyptin maalla, jotka hänelle synnytti Asnat, Potipheran Onin papin tytär: nimittäin Manasse ja Ephraim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'BenJaminin lapset: Bela, Beker, Asbel, Gera, Naaman, Ehi ja Ros; Mupim, Hupim, ja Ard.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Nämät ovat Rakelin lapset, jotka ovat Jakobille syntyneet, kaikki yhteen, neljätoistakymmentä henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Danin lapset: Husim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Naphtalin lapset: Jahseel, Guni, Jetser ja Sillem.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Nämät ovat Bilhan lapset, jonka Laban antoi tyttärellensä Rakelille, ja hän synnytti nämät Jakobille, kaikki yhteen, seitsemän henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Kaikki henget, kuin tulivat Jakobin kanssa Egyptiin, jotka olivat tulleet hänen kupeistansa, paitsi Jakobin poikain emäntiä, ovat kaikki yhteen, kuusiseitsemättäkymmentä henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Ja Josephin pojat, jotka hänelle olivat syntyneet Egyptissä, olivat kaksi henkeä. Niin että kaikki henget Jakobin huoneesta, jotka tulivat Egyptiin olivat seitsemänkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Ja hän lähetti edellänsä Juudan Josephin tykö, osoittamaan hänelle tietä Goseniin, ja he tulivat Gosenin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Niin valmisti Joseph vaununsa ja meni isäänsä Israelia vastaan Goseniin. Ja koska hän sai nähdä hänen, halasi hän häntä kaulasta ja itki hetken aikaa hänen kaulassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Niin sanoi Israel Josephille: nyt minä mielelläni kuolen, että minä näin sinun kasvos, ja ettäs vielä elät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Ja Joseph sanoi veljillensä, ja isänsä huoneelle: minä menen ja ilmoitan Pharaolle, ja sanon hänelle: minun veljeni ja isäni huone, jotka olivat Kanaanin maalla, ovat tulleet minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Ja he ovat paimenet, sillä he ovat tottuneet karjaa kaitsemaan: niin myös suuret ja pienet karjansa, ja kaikki, mitä heillä oli, ovat tuoneet myötänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Koska siis Pharao kutsuu teitä ja sanoo: mikä teidän virkanne on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Niin sanokaat: sinun palvelias ovat tottuneet karjaa kaitsemaan, hamasta meidän nuoruudestamme niin tähänasti, sekä me että meidän isämme: että te saisitte asua Gosenin maalla, sillä kaikki paimenet ovat kauhistus Egyptiläisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Niin Joseph tuli ja ilmoitti Pharaolle, ja sanoi: minun isäni ja minun veljeni, heidän karjansa, pienet ja suuret, ja kaikki, mitä heillä on, ovat tulleet Kanaanin maalta; ja katso, he ovat Gosenin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Ja hän otti viisi nuorimmista veljistänsä, ja asetti Pharaon eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Niin Pharao sanoi hänen veljillensä: mikä teidän virkanne on? He vastasivat: sinun palvelias ovat paimenet, sekä me että meidän isämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Ja sanoivat vielä Pharaolle: me olemme tulleet asumaan teidän kanssanne tälle maalle; sillä sinun palvelioillas ei ole laidunta karjallensa, niin kova nälkä on Kanaanin maalla. Niin suo sinun palvelias asua Gosenin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Niin Pharao puhui Josephille, sanoen: sinun isäs ja veljes ovat tulleet sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egyptin maa on altis sinun edessäs; aseta isäs asumaan ja veljes kaikkein parhaasen paikkaan tässä maassa: asukaan Gosenin maalla. Ja jos sinä ymmärrät, että heidän seassansa on kelvollisia miehiä, niin aseta heitä minun karjani päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Ja Joseph toi isänsä, Jakobin, sisälle, ja asetti hänen Pharaon eteen. Ja Jakob siunasi Pharaota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Niin Pharao sanoi Jakobille: kuinka vanha sinä olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob sanoi Pharaolle: minun kulkemiseni aika on sata ja kolmekymmentä ajastaikaa: vähä ja paha on minun elämäni aika ja ei ulotu minun isäini kulkemisen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Ja Jakob siunasi Pharaota, ja läksi hänen tyköänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Niin Joseph toimitti isänsä ja veljensä asumaan, ja antoi heille omaisuuden Egyptin maalla, parhaassa maan paikassa; nimittäin Rameseksen maalla, niinkuin Pharao oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Ja Joseph elätti isänsä, veljensä ja koko isänsä huoneen, sen jälkeen kuin heillä lapsia oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Ja ei ollut leipää kaikessa maassa; sillä sangen raskas nälkä oli, niin että Egyptin ja Kanaanin maa nääntyi näljän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Ja Joseph kokosi kaiken rahan kuin löyttiin Egyptin ja Kanaanin maalla, jyväin edestä kuin he ostivat. Ja Joseph vei rahan Pharaon huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Koska raha oli kulunut Egyptin ja Kanaanin maalta, niin tulivat kaikki Egyptiläiset Josephin tykö, sanoen: anna meille leipää, miksi meidän pitää kuoleman edessäs, että raha on puuttunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joseph sanoi: tuokaat teidän karjanne, ja minä annan teille karjanne edestä, jos raha on puuttunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Ja he toivat karjansa Josephille, ja Joseph antoi heille leipää hevosten, ja lammasten, ja karjan ja aasein edestä. Niin hän ruokki heitä leivällä sen vuoden, kaiken heidän karjansa edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Koska se vuosi oli kulunut, tulivat he hänen tykönsä toisna vuonna, ja sanoivat hänelle: emme taida salata meidän herraltamme, ettei ainoastansa raha ole kulunut, mutta myös kaikki karja on meidän herrallamme, ja ei ole mitään jäänyt meidän herramme edessä, paitsi meidän ruumistamme ja meidän peltoamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Miksi meidän pitää kuoleman edessäs ja meidän peltomme tulee kylmille? Osta meitä ja meidän maamme leivän edestä, niin me ja meidän maamme tulemme Pharaon omaksi. Anna siemeniä, että me eläisimme ja emme kuolisi, ja ei maa tulisi kylmille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Niin Joseph osti koko Egyptin maan Pharaolle; sillä Egyptiläiset myivät itsekukin peltonsa, että nälkä heitä niin kovin ahdisti: ja maa tuli Pharaon omaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Ja hän siirsi kansan kaupunkeihin yhdestä Egyptin äärestä niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Paitsi pappein peltoa, jota ei hän ostanut: sillä se oli säätty Pharaolta, että papit söisivät sen nimitetyn osan, kuin Pharao heille antoi: sentähden ei he myyneet maatansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Niin Joseph sanoi kansalle: katso, minä olen ostanut tänäpänä teidän ja teidän maanne Pharaolle: katso, tässä on teille siemenet, kylväkäät teidän maanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Ja teidän pitää antaman tulosta viidennen osan Pharaolle; mutta neljä osaa pitää oleman teille pellon siemeneksi, ja teille ravinnoksi, ja niille, jotka ovat teidän huoneessanne, ja ruaksi teidän lapsillenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Niin he sanoivat: sinä olet meitä elämässä pitänyt: anna ainoastansa meidän löytää armo sinun meidän herramme edessä, ja me tahdomme olla Pharaon orjat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Ja Joseph teki sen määrän koko Egyptin maalle, hamaan tähän päivään asti, että Pharaolle piti annettaman viides osa; paitsi pappein maata, se ei tullut Pharaon omaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Niin Israel asui Egyptissä Gosenin maalla; ja he omistivat sen, ja kasvoivat ja suuresti lisääntyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Ja Jakob eli Egyptin maalla, seitsemäntoistakymmentä ajastaikaa, ja koko hänen ikänsä oli sata ja seitsemänviidettäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Ja koska Israelin päivät joutuivat kuolla, kutsui hän poikansa Josephin, ja sanoi hänelle: jos minä olen löytänyt armon sinun edessäs, niin laske nyt kätes minun kupeeni alle, ettäs tekisit laupiuden ja totuuden minun kanssani, ettes hautaisi minua Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Mutta minä tahdon maata minun isäini tykönä, ja sinun pitää viemän minua Egyptistä, ja hautaaman minua heidän hautaansa. Ja hän sanoi: minä teen sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Hän sanoi: vanno minulle. Ja hän vannoi hänelle. Ja Israel kallisti itsensä päänalaiselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Sitte sanottiin Josephille: katso, sinun isäs sairastaa. Ja hän otti molemmat poikansa kanssansa, Manassen ja Ephraimin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Niin Jakobille ilmoitettiin, sanoen: katso, sinun poikas Joseph tulee sinun tykös. Ja Israel vahvisti itsensä ja istui vuoteessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Ja Jakob sanoi Josephille: Jumala kaikkivaltias näkyi minulle Lutsissa Kanaanin maalla; ja siunasi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Ja sanoi minulle: katso, minä annan sinun olla hedelmällisen ja lisääntyä, ja teen sinun paljoksi kansaksi; ja annan myös tämän maan sinun siemenelles sinun jälkees, ijankaikkiseksi perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Nyt siis ne kaksi sinun poikaas, jotka sinulle ovat syntyneet Egyptissä, ennenkuin minä tulin tänne sinun tykös, pitää oleman minun; nimittäin Ephraim ja Manasse, niinkuin Ruben ja Simeon ovat minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mutta sinun lapses, jotkas siität niiden jälkeen, pitää oleman sinun, ja pitää nimitettämän veljeinsä nimellä, heidän perimisestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Ja koska minä tulin Mesopotamiasta, kuoli minulta Rakel Kanaanin maalla, tiellä, koska vielä kappale matkaa oli Ephrataan; ja minä hautasin hänen siellä Ephratan tiellä, se on Betlehem.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Ja Israel näki Josephin pojat, ja sanoi: kutka nämät ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Ja Joseph vastasi isäänsä: ne ovat minun poikani, jotka Jumala on minulle täällä antanut. Ja hän sanoi: tuos heitä minun tyköni siunatakseni heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Sillä Israelin silmät olivat pimiät vanhuudesta, eikä taitanut hyvin nähdä. Ja hän vei heidät hänen tykönsä. Ja hän antoi suuta heidän, ja otti heitä syliinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Ja Israel sanoi Josephille: en minä ajatellut nähdä sinun kasvojas, ja katso, Jumala on antanut minun myös nähdä sinun siemenes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Ja Joseph otti heidät pois hänen sylistänsä, ja kumarsi itsiänsä maahan hänen kasvoinsa eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Niin Joseph otti heidät molemmat, Ephraimin oikiaan käteensä, jonka hän asetti Israelin vasemmalle kädelle, ja Manassen vasempaan käteensä, Israelin oikialle kädelle, ja vei heidät hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Niin Israel ojensi oikian kätensä, ja laski Ephraimin pään päälle, joka oli nuorempi, mutta vasemman kätensä Manassen pään päälle, ja muutti tiettävästi kätensä; sillä Manasse oli esikoinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Ja hän siunasi Josephia, ja sanoi: Jumala, jonka kasvoin edessä minun isäni Abraham ja Isaak vaeltaneet ovat, Jumala, joka minun kainnut on minun elinaikanani tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Enkeli, joka minun pelastanut on kaikesta pahasta, siunatkoon näitä nuorukaisia, että he nimitettäisiin minun ja minun isäini, Abrahamin, ja Isaakin nimellä, ja kasvaisivat aivan paljoksi maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Mutta koska Joseph näki isänsä laskevan oikian kätensä Ephraimin pään päälle, otti hän sen pahaksi, ja rupesi isänsä käteen, siirtääksensä Ephraimin pään päältä Manassen pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Ja sanoi Joseph isällensä: ei niin minun isäni; tämä on esikoinen, laske oikia kätes hänen päänsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mutta hänen isänsä kielsi sen, ja sanoi: minä tiedän kyllä, minun poikani, minä tiedän: tämä myös tulee suureksi kansaksi; mutta kuitenkin hänen nuorempi veljensä tulee suuremmaksi kuin hän, ja hänen siemenensä tulee suureksi kansain paljoudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Niin hän siunasi heitä sinä päivänä, sanoen: joka tahtoo jonkun siunata Israelissa, niin sanokaan näin: Jumala tehköön sinun niinkuin Ephraimin ja Manassen. Ja niin asetti hän Ephraimin Manassen edelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Ja Israel sanoi Josephille: katso minä kuolen; ja Jumala on teidän kanssanne, ja vie teitä jällensä teidän isäinne maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Minä olen myös antanut sinulle osan maata, päälle sinun veljeis osan, jonka minä miekallani ja joutsellani Amorilaisten käsistä ottanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Niin kutsui Jakob poikansa, ja sanoi: kootkaat teitänne, ja minä ilmoitan teille, mitä teille tapahtuu tulevaisilla ajoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Tulkaat kokoon ja kuulkaat, te Jakobin lapset, kuulkaat teidän isäänne Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, sinä olet minun esikoiseni, minun voimani, ja väkevyyteni alku, ylimmäinen kunniassa, ja ylimmäinen vallassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Hempiä niinkuin vesi, ei sinun pidä ylimmäisen oleman; sillä sinä astuit isäs vuoteesen: silloin sinä saastutit sen. Hän nousi minun vuoteelleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon ja Levi ovat veljekset, heidän miekkansa ovat murha-aseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Ei minun sieluni pidä tuleman heidän neuvoonsa, ja minun kunniani ei pidä yhdistymän heidän seurakuntansa kanssa; sillä kiukussansa ovat he miehen murhanneet, ja ylpeydessänsä turmelleet härjän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Kirottu olkoon heidän kiukkunsa, että se niin tuima on, ja heidän julmuutensa, että se niin paatunut on. Minä eroitan heitä Jakobissa, ja hajotan heitä Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juuda, sinä olet; sinua pitää sinun veljes kiittämän, sinun kätes pitää oleman sinun vihollistes niskalle, sinun isäs lapset pitää sinua kumartaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juuda on nuori jalopeura, saaliilta olet sinä astunut, minun poikani: hän on itsensä kumartanut maahan, ja levännyt niinkuin jalopeura, ja niinkuin suuri jalopeura; kuka tohtii hänen herättää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Ei valtikka oteta pois Juudalta, eikä Lain opettaja hänen jalvoistansa, siihenasti kuin Sankari tulee, ja hänessä kansat riippuvat kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Hän sitoo varsansa viinapuuhun, ja aasintammansa varsan parhaasen viinapuuhun; Hän pesee vaatteensa viinassa, ja hameensa viinamarjan veressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Hänen silmänsä ovat punaisemmat viinaa ja hampaansa valkeammat rieskaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulon on asuva meren sataman ja haahtein satamain vieressä, ja on ulottuva hamaan Sidoniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaskar on luja aasi, ja sioittaa itsensä rajain välille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Hän näki levon hyväksi, ja maan ihanaksi; ja kumarsi hartiansa kantamaan, ja on veronalainen palvelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan on tuomitseva kansaansa, niinkuin joku Israelin sukukunnista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan on oleva kärmeenä tiellä, ja kyykärmeenä polulla; ja puree hevosta vuokoiseen, niin että sen ajaja seljällensä lankee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Herra, minä odotan sinun autuuttas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad hän on; hänelle tekee joukko väkirynnäkön; mutta hän itse on tekevä väkirynnäkön vihdoin heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Asserista tulee hänen lihava leipänsä, ja hän antaa kuninkaalle herkut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphtali on nopia peura, ja antaa suloiset puheet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joseph on hedelmällisen puun oksa, hedelmällisen puun oksa lähteen tykönä: tyttäret kävelivät muurin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Ja vaikka ampujat saattivat hänen mielensä karvaaksi, riitelivät hänen kanssansa ja vihasivat häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'On kuitenkin hänen joutsensa vahvana pysynyt, ja hänen käsivartensa miehustunut, sen väkevän kätten kautta Jakobissa; hänestä on paimen ja kivi Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Sinun isäs Jumalalta on hän sinulle avun tuottava, ja ynnä kaikkivaltiaan kanssa on hän sinua siunaava taivaan siunauksella ylhäältä, ja syvyyden siunauksella alhaalta, niin myös nisäin ja kohtuin siunauksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Sinun isäs siunaukset minun isäini siunausten sivussa, ulottuvat voimallisesti niihin kalliimpihin asti maailman kukkuloilla; jotka tulevat Josephin pään päälle, ja Natsirein pään laelle, hänen veljeinsä keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'BenJamin on raatelevainen susi, aamulla hän syö saaliin, ja ehtoona saaliin jakaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Nämät kaikki ovat kaksitoistakymmentä Israelin sukukuntaa. Ja tämä on se kuin heidän isänsä heille puhui siunatessansa heitä: itsekutakin, niinkuin kunkin siunaus oli, siunasi hän heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Ja hän käski heitä, ja sanoi heille: minä kootaan minun kansani tykö: haudatkaat minua minun isäni tykö, siihen luolaan, joka on Hetiläisen Ephronin vainiossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'Siihen luolaan Makpelan vainiossa, joka on Mamren kohdalla Kanaanin maalla, jonka Abraham osti hautaamisen perimiseksi vainion kanssa, siltä Hetiläiseltä Ephronilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Sinne ovat he haudanneet Abrahamin ja hänen emäntänsä Saaran, sinne ovat he myös haudanneet Isaakin ja Rebekan hänen emäntänsä. Sinne olen minä myös haudannut Lean.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Siihen vainioon ja siihen luolaan, kuin on ostettu Hetin lapsilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Ja koska Jakob lopetti käskyn lastensa tykö, pani hän jalkansa kokoon vuoteessa; ja loppui, ja koottiin kansansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Niin Joseph lankesi isänsä kasvoille, itki hänen ylitsensä, ja antoi suuta hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Ja Joseph käski palvelioitansa lääkäreitä voidella isäänsä; ja lääkärit voitelivat Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Ja he täyttivät hänelle neljäkymmentä päivää; sillä niin monta oli voiteluspäivää. Ja Egyptiläiset itkivät häntä seitsemänkymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Koska hänen murhepäivänsä olivat kuluneet, puhui Joseph Pharaon palvelioille, sanoen: jos minä olen armon löytänyt teidän edessänne, niin puhukaat Pharaolle, ja sanokaat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Minun isäni vannotti minua, sanoen: katso, minä kuolen, hautaa minua minun hautaani, jonka minä olen kaivanut minulle Kanaanin maalla: niin tahtoisin minä nyt siis mennä, ja haudata minun isäni, ja palata tänne jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Pharao sanoi hänelle: mene ja hautaa sinun isäs, niinkuin hän sinua vannottanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Niin Joseph meni hautaamaan isäänsä; ja hänen kanssansa menivät kaikki Pharaon palveliat, hänen huoneensa vanhimmat, ja kaikki Egyptin maan vanhimmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Kaikki myös Josephin väki, ja hänen veljensä, ja hänen isänsä väki. Ainoastaan lapsensa, ja lampaansa, ja karjansa jättivät he Gosenin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Menivät myös hänen kanssansa vaunut ja ratsasmiehet. Ja se oli sangen suuri joukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Ja koska he tulivat Atadin riihen tykö, joka on sillä puolen Jordania, niin he pitivät siinä suuren ja katkeran valituksen; ja hän murehti isäänsä seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Ja koska Kanaanin maan asuvaiset näkivät heidän murheensa Atadin riihen tykönä, sanoivat he: Egyptiläiset murehtivat siellä sangen kovin. Siitä se paikka kutsutaan: Egyptiläisten valitus, joka on sillä puolella Jordania.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Niin hänen lapsensa tekivät hänelle niinkuin hän oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Ja veivät hänen Kanaanin maalle, ja hautasivat hänen Makpelan vainion luolaan, jonka Abraham vainion kanssa ostanut oli perintöhaudaksi, Ephronilta Hetiläiseltä, Mamren kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Niin palasi Joseph Egyptiin, hän ja hänen veljensä, ja kaikki jotka hänen kanssansa olivat menneet hautaamaan hänen isäänsä, sitte kuin hän isänsä haudannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Mutta koska Josephin veljet näkivät isänsä kuolleeksi, sanoivat he: mitämaks, Joseph on vihaava meitä, ja kaiketi kostaa meille kaiken sen pahan, kuin me häntä vastaan tehneet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Sentähden käskivät he sanoa Josephille: sinun isäs käski ennenkuin hän kuoli, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Niin sanokaat Josephille: minä rukoilen, anna nyt veljilles anteeksi heidän rikoksensa ja pahatekonsa, että he niin pahoin ovat tehneet sinua vastaan. Anna nyt anteeksi, sinun isäs Jumalan palveliain pahateko. Mutta Joseph itki heidän näitä puhuissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Ja hänen veljensä myös tulivat ja lankesivat maahan hänen eteensä ja sanoivat: katso, me olemme sinun palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Joseph sanoi heille: älkäät peljätkö; sillä minä olen Jumalan käden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Te ajattelitte minua vastaan pahaa; mutta Jumala on ajatellut sen hyväksi, että hän tekis, niinkuin nyt nähtävä on, pelastaaksensa paljo kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Älkäät siis nyt peljätkö, minä ravitsen teitä ja teidän lapsianne; ja hän rohkaisi heitä ja puheli ystävällisesti heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Ja niin asui Joseph Egyptissä, hän ja hänen isänsä huone; ja Joseph eli sata ja kymmenen ajastaikaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Ja näki Ephraimin lapset kolmanteen polveen, niin myös Makirin Manassen pojan lapset, kasvatetut Josephin polven juuressa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Joseph sanoi veljillensä: minä kuolen, ja Jumala on totisesti etsivä teitä, ja vie teidän tältä maalta siihen maahan, jonka hän on itse vannonut Abrahamille, Isaakille ja Jakobille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Niin vannotti Joseph Israelin lapsia, sanoen: Jumala on totisesti teitä etsivä, viekäät pois minun luuni täältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Ja niin Joseph kuoli sadan ja kymmenen ajastaikaisena, ja he voitelivat hänen, ja panivat arkkuun Egyptissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Nämät ovat Israelin lasten nimet, jotka Jakobin kanssa tulivat Egyptiin, itsekukin huoneinensa he sinne tulivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi ja Juuda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaskar, Zebulon ja Benjamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, Naphtali, Gad ja Asser.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Ja kaikki henget, jotka Jakobin kupeista olivat tulleet, olivat seitsemänkymmentä henkeä. Mutta Joseph oli (ennen) Egyptissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Ja Joseph oli kuollut, ja kaikki hänen veljensä, ja kaikki sen aikaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Ja Israelin lapset olivat hedelmälliset ja suuresti enenivät ja lisääntyivät, ja sangen voimallisesti vahvistuivat, niin että maa täytettiin heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Niin uusi kuningas tuli Egyptiin, joka ei Josephista mitään tietänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Hän sanoi kansallensa: katso, Israelin lasten joukko on suurempi ja väkevämpi meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Tulkaat, käykäämme kavalasti heidän kimppuunsa, ettei heitä tulisi niin paljo. Sillä jos joku sota nousis, tohtisivat he mennä meidän vihamiestemme puolelle, ja sotia meitä vastaan, ja lähteä maalta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Niin asetettiin heidän päällensä veron päämiehet, vaivaamaan heitä orjuudella; sillä Pharaolle rakennettiin verokaupungit, Pitom ja Raamses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Mutta jota enemmin he rasittivat kansaa, sitä enemmin se lisääntyi ja kasvoi. Ja he tulivat suutuksiin Israelin lasten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Ja Egyptiläiset vaivasivat Israelin lapsia orjuudella armaitsemata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Ja saattivat heidän elämänsä katkeraksi raskaalla saven ja tiilein työllä, ja kaikkinaisella rasituksella kedolla, ja kaikkinaisella työllä, kuin he taisivat heidän päällensä panna, armaitsemata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Ja Egyptin kuningas puhui Heprealaisille lastenämmille, joista yhden nimi oli Siphra, ja toisen nimi Pua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Ja hän sanoi: Koska te autatte Hebreailaisia vaimoja heidän synnyttäissänsä, ja näette istuimella, jos on poika, niin surmatkaat häntä; mutta jos se tytär on, niin se eläköön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mutta lastenämmät pelkäsivät Jumalaa, ja ei tehneet niinkuin Egyptin kuningas oli heille sanonut; mutta antoivat poikaiset elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Niin Egyptin kuningas kutsui lastenämmät, ja sanoi heille: miksi te tämän teitte, että te annoitte poikaisten elää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Niin lastenämmät vastasivat Pharaota: Heprealaiset vaimot ei ole niinkuin Egyptiläiset; sillä he ovat vahvemmat luonnostansa, ja ennenkuin lastenämmä tulee heidän tykönsä, ovat he synnyttäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Sentähden teki Jumala lastenämmille hyvin, ja kansa lisääntyi ja vahvistui sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Ja että lastenämmät pelkäsivät Jumalaa, rakensi hän heille huoneita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Niin käski Pharao kaikelle kansallensa, sanoen: kaikki pojat kuin syntyvät pitää teidän heittämän virtaan, mutta kaikki tyttäret antakaat elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Niin mies Leevin huoneesta meni ja nai Levin tyttären.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Ja se vaimo tuli raskaaksi, ja synnytti pojan. Ja koska hän näki, että se oli ihana lapsi, salasi hän sen kolme kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Ja kuin ei hän taitanut häntä enää salata, otti hän kaisilaisen arkun, ja sivui sen savella ja pijellä, ja pani lapsen siihen ja laski sen kaisilistoon, virran partaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Ja hänen sisarensa seisoi taampana, että hän näkis, mitä hänelle tapahtuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Niin Pharaon tytär meni alas pesemään itseänsä virtaan, ja hänen piikansa käyskentelivät virran partaalla; ja kuin hän näki arkun kaisilistossa, lähetti hän piikansa ja antoi hänen ottaa ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Ja kuin hän avasi, näki hän lapsen, ja katso, lapsi itki; niin hän armahti sen päälle, ja sanoi: tämä on Heprealaisten lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Niin sanoi hänen sisarensa Pharaon tyttärelle: tahdotkos että minä menen kutsumaan sinulle imettäväisen Heprealaisen vaimon, joka sinulle sen lapsen imettäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Pharaon tytär sanoi hänelle: mene. Niin piika meni ja kutsui lapsen äidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Ja Pharaon tytär sanoi hänelle: ota tämä lapsi, ja imetä häntä minulle, ja minä annan palkan sinulle. Niin vaimo otti lapsen, ja imetti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Mutta koska lapsi oli kasvanut, toi hän sen Pharaon tyttärelle, ja hän otti sen pojaksensa, ja kutsui hänen Moses; sillä hän sanoi: vedestä olen minä hänen ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Siihen aikaan koska Moses oli suureksi tullut, meni hän veljeinsä tykö ja näki heidän orjuutensa, ja äkkäsi Egyptiläisen lyövän Hebrealaista miestä hänen veljistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Ja hän katseli ympärillensä sinne ja tänne, ja kuin hän näki, ettei yhtään läsnä ollut, tappoi hän sen Egyptiläisen ja kätki santaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Ja hän meni toisna päivänä ulos, ja katso, kaksi Heprealaista miestä tappelivat keskenänsä, ja hän sanoi väärintekiälle: miksis lyöt lähimmäistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Hän vastasi: kuka sinun on asettanut päämieheksemme ja tuomariksemme? Tahdotkos minunkin tappaa, niinkuin sinä tapoit Egyptiläisen? Niin Moses pelkäsi, ja sanoi: tosin on tämä ilmi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Ja se tuli Pharaon eteen, ja hän etsi Mosesta tappaaksensa. Mutta Moses pakeni Pharaon edestä, ja seisahtui Midianin maalla, ja istui kaivon tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Mutta Midianin papilla oli seitsemän tytärtä; ne tulivat vettä ammuntamaan ja täyttivät ruuhet, juottaaksensa isänsä lampaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'niin tulivat muutamat paimenet ja ajoivat heidät pois. Mutta Moses nousi ja autti heitä, ja juotti heidän lampaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Ja kuin he tulivat isänsä Reguelin tykö, sanoi hän: miksi te tänäpänä niin pian jouduitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'He sanoivat: Egyptin mies autti meitä paimenien käsistä, ja myös viriästi ammunsi meille, ja juotti lampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Ja hän sanoi tyttärillensä: kussa hän on? Miksi te niin jätitte miehen? Kutsukaat häntä syömään meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Ja Moses mielistyi asumaan sen miehen tykönä, ja hän antoi Mosekselle tyttärensä Ziporan emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Se synnytti pojan ja hän kutsui hänen nimensä Gersom; sillä hän sanoi: minä olen muukalainen vieraalla maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Ja pitkän ajan perästä kuoli Egyptin kuningas. Ja Israelin lapset huokasivat orjuuden tähden ja huusivat, ja heidän huutonsa astui ylös Jumalan tykö heidän orjuutensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Ja Jumala kuuli heidän huokauksensa: ja muisti liittonsa Abrahamin, Isaakin ja Jakobin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Ja Jumala katsahti Israelin lasten puoleen, ja Jumala piti heistä murheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Ja Moses kaitsi appensa Jetron Midianin papin lampaita: ja hän ajoi lampaat taamma korpeen, ja tuli Jumalan vuoren Horebin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Ja Herran enkeli näkyi hänelle pensaasta, tulen liekissä: ja hän näki, ja katso, pensas paloi tulesta, ja ei kuitenkaan kulunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Ja Moses sanoi: minä käyn tuonne, ja katson tätä suurta näkyä, miksi ei pensas pala ylös?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Koska Herra näki hänen menevän katsomaan, huusi Jumala häntä pensaasta, ja sanoi: Moses, Moses. Hän vastasi: tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Hän sanoi: älä lähesty tänne; riisu kenkäs jalvoistas; sillä paikka, jossas seisot, on pyhä maa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Ja hän vielä sanoi: Minä olen sinun isäs Jumala, Abrahamin Jumala, Isaakin Jumala, ja Jakobin Jumala. Ja Moses peitti kasvonsa; sillä hän pelkäsi katsoa Jumalan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Ja Herra sanoi: Minä olen hyvin kyllä nähnyt minun kansani ahdistuksen, joka on Egyptissä, ja minä olen kuullut heidän huutonsa, niiden tähden, jotka heitä ahdistavat; sillä minä tiedän heidän tuskansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Ja olen astunut alas heitä vapahtamaan Egyptiläisten käsistä, ja viemään heitä tältä maalta hyvään ja laviaan maahan, siihen maahan, jossa rieskaa ja hunajaa vuotaa, sille paikalle, jossa Kanaanealaiset, Hetiläiset, Amorilaiset, Pheresiläiset, Heviläiset ja Jebusilaiset asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Ja katso, Israelin lasten huuto on tullut minun eteeni, ja minä myös olen nähnyt heidän ahdistuksensa, jolla Egyptiläiset heitä ahdistavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Ja nyt mene, ja minä tahdon lähettää sinun Pharaon tykö, ja sinun pitää johdattaman minun kansaani Israelin lapsia ulos Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Ja Moses sanoi Jumalalle: mikä minä olen menemään Pharaon tykö, ja viemään Israelin lapset ulos Egyptistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Hän sanoi: totisesti olen sinun kanssas; ja tämä olkoon sinulle merkiksi, että minä olen sinun lähettänyt. Koska olet johdattanut minun kansani Egyptistä, niin teidän pitää palveleman Jumalaa tällä vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Moses sanoi Jumalalle: katso, koska minä tulen Israelin lasten tykö, ja sanon heille: teidän isäinne Jumala on minun lähettänyt teidän tykönne, ja he sanovat minulle: mikä hänen nimensä on? Mitä minun pitää heille sanoman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Sanoi Jumala Mosekselle: Minä olen se kuin minä olen. Ja sanoi: niin pitää sinun sanoman Israelin lapsille: Minä olen lähetti minun teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Ja Jumala sanoi vielä Mosekselle: niin pitää sinun sanoman Israelin lapsille: Herra teidän isäinne Jumala, Abrahamin Jumala, Isaakin Jumala, ja Jakobin Jumala lähetti minun teidän tykönne; tämä on minun nimeni ijankaikkisesti, ja tämä on minun muistoni suvusta niin sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Mene ja kokoo Israelin vanhemmat, ja sano heille: Herra teidän isäinne Jumala on näkynyt minulle, Abrahamin, Isaakin, ja Jakobin Jumala, sanoen: minä olen etsein etsinyt teitä, ja nähnyt, mitä teille on tapahtunut Egyptissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Ja olen sanonut: minä tahdon johdattaa teitä ulos Egyptin ahdistuksesta, Kanaanealaisten, Hetiläisten, Amorilaisten, Pheresiläisten ja Jebusilaisten maalle, jossa rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Ja heidän pitää kuuleman sinun äänes; ja sinun ja vanhimmat Israelista pitää menemän Egyptin kuninkaan tykö, ja sanoman hänelle: Herra Hebrealaisten Jumala on kohdannut meitä. Anna siis nyt meidän mennä kolmen päivän matka korpeen, uhraamaan Herralle meidän Jumalallemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Mutta minä tiedän, ettei Egyptin kuningas laske teitä menemään; vaan väkevän käden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Silloin minä ojennan käteni, ja lyön Egyptin kaikkinaisilla minun ihmeilläni, joita minä tekevä olen heidän keskellänsä, ja sitte pitää hänen teidät päästämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Ja minä annan armon tälle kansalle Egyptiläisten edessä, että koska te lähdette, ei teidän pidä tyhjin käsin lähtemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Vaan jokaisen vaimon pitää anoman kylänsä vaimolta, ja huonekuntalaiseltansa hopia- ja kulta-astiat ja vaatteet, ja paneman ne teidän poikainne ja tytärtenne päälle, ja paljastaman Egyptiläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Moses vastasi, ja sanoi: katso, ei he usko minua, eikä ole kuuliaiset minun äänelleni; vaan sanovat: ei ole Herra näkynyt sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Herra sanoi hänelle: mikä se on sinun kädessäs? Hän sanoi: sauva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Ja hän sanoi: heitä se maahan, ja hän heitti sen maahan, ja se muuttui kärmeeksi. Ja Moses pakeni häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Mutta Herra sanoi Mosekselle: ojenna kätes, ja rupee hänen pyrstöönsä. Niin hän ojensi kätensä ja rupesi häneen, ja se muuttui sauvaksi hänen kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Sentähden pitää heidän uskoman, että Herra on näkynyt sinulle, heidän isäinsä Jumala, Abrahamin Jumala, Isaakin Jumala ja Jakobin Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Ja Herra sanoi vielä hänelle: pistä nyt kätes povees. Ja hän pisti sen poveensa. Ja koska hän veti sen ulos, katso, hänen kätensä oli spitalinen niinkuin lumi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Ja hän sanoi: pistä kätes jällensä povees, ja hän pisti kätensä jälleen poveensa, ja veti jällensä sen ulos povestansa, ja katso, se tuli niinkuin hänen ihonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Ja on tapahtuva, jollei he sinua usko, eikä ole kuuliaiset sinun äänelles yhden ihmeen tähden, niin he uskovat sinun äänes toisen ihmeen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Jollei he usko niitä kahta ihmettä, eikä ole kuuliaiset sinun äänelles, niin ota vettä virrasta, ja kaada kuivalle maalle, niin se vesi, jonkas olet ottanut virrasta, tulee vereksi kuivalla maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Niin sanoi Moses Herralle: Ah Herra, en ole minä tähän asti puhelias mies ollut, enkä myös sitte kuin sinä palvelias kanssa puhunut olet; sillä minulla on hidas puhe ja kankia kieli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Ja Herra sanoi hänelle: kuka on luonut ihmisen suun? Eli kuka on tehnyt mykän taikka kuuron, eli näkevän taikka sokian? Enkö minä Herra (ole niitä tehnyt)?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Mene siis nyt, minä olen sinun suussas, ja opetan sinua, mitä sinun puhuman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Moses sanoi: Ah Herra, lähetä, jonkas tahdot lähettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Niin Herra vihastui suuresti Moseksen päälle, ja sanoi: enkö minä tunne Aaronia sinun veljeäs, Levin suvusta, että hän on puhelias? Ja katso, hän tulee sinua vastaan, ja koska hän näkee sinun, niin hän iloitsee sydämestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Sinun pitää puhuman hänelle, ja paneman sanat hänen suuhunsa; ja minä olen sinun ja hänen suunsa kanssa, ja opetan teitä, mitä teidän pitää tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Ja hänen pitää puhuman sinun puolestas kansalle. Hänen pitää oleman sinun suunas, ja sinun pitää oleman hänelle Jumalana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Ja ota tämä sauva kätees, jolla sinun pitää tekemän ihmeitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Niin Moses läksi sieltä, ja tuli jällensä appensa Jetron tykö, ja sanoi hänelle: annas minun mennä, että minä palajaisin veljeini tykö, jotka ovat Egyptissä, ja näkisin heitä, jos he vielä elävät. Ja Jetro sanoi Mosekselle: mene rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Ja Herra sanoi Mosekselle Midianissa: mene ja palaja Egyptiin; sillä ne kaikki ovat kuolleet, jotka sinun henkes perään seisoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Ja Moses otti emäntänsä ja poikansa, ja pani ne aasin päälle, ja palasi Egyptiin; ja otti Jumalan sauvan käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Ja Herra sanoi Mosekselle: katso, koskas tulet Egyptiin jällensä, ettäs teet kaikki ne ihmeet Pharaon edessä, jotka minä olen antanut sinun kätees. Ja minä paadutan hänen sydämensä, ja ei hän päästä kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Ja sinun pitää sanoman Pharaolle: näin sanoo Herra: Israel on minun poikani, minun esikoiseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Ja minä käsken sinulle: päästä minun poikani palvelemaan minua, ja jos et sinä tahdo häntä päästää, katso, minä tapan sinun poikas, sinun esikoises.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Ja koska hän oli tiellä majassa, tuli Herra häntä vastaan, ja tahtoi hänen tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Niin Zippora otti kiven, ja ympärileikkasi poikansa esinahan, ja rupesi hänen jalkoihinsa, ja sanoi: sinä olet minulle veriylkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Niin hän luopui hänestä. Mutta sanoi: veriylkä ympärileikkauksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Ja Herra sanoi Aaronille: mene Mosesta vastaan korpeen. Ja hän meni, ja tuli häntä vastaan Jumalan vuorella, ja antoi hänen suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Ja Moses ilmoitti Aaronille kaikki Herran sanat, jotka hänen lähetti, ja kaikki ihmeet, jotka hän hänet käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Niin meni Moses ja Aaron, ja kokosivat kaikki Israelin lasten vanhimmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Ja Aaron puhui kaikki ne sanat, jotka Herra Mosekselle puhunut oli, ja teki ihmeitä kansan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Ja kansa uskoi. Ja kuin he kuulivat, että Herra oli etsinyt Israelin lapsia, nähnyt myös heidän ahdistuksensa, lankesivat he maahan ja rukoilivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Sitte menivät Moses ja Aaron Pharaon tykö, ja sanoivat: näin sanoo Herra Israelin Jumala: päästä minun kansani pitämään minulle juhlaa korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Pharao vastasi: kuka on Herra, jonka ääntä minun pitäis kuuleman, ja päästämän Israelin? En minä siitä Herrasta mitään tiedä, enkä päästä Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Ja he sanoivat: Heprealaisten Jumala on kohdannut meitä; anna siis nyt meidän mennä kolmen päivän matka korpeen uhraamaan Herralle meidän Jumalallemme, ettei hän rutolla miekalla meidän päällemme tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Niin Egyptin kuningas sanoi heille: miksi te, Moses ja Aaron, pidätte kansan heidän työstänsä? Menkäät teidän työhönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Pharao sanoi vielä: katso, ilmankin on kansaa paljo maalla, ja te vielä nyt tahdotte heitä joutilaaksi saattaa heidän töistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Sentähden käski Pharao sinä päivänä kansan teettäjille ja heidän haltioillensa, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ei teidän pidä tästälähin olkia antaman kansalle tiilejä tehdä niinkuin ennen; menkään he itse ja kootkaan itsellensä olkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Kuitenkin se tiililuku, jonka he tekivät tähän asti, laskekaat heidän päällensä, ja älkäät siitä vähentäkö; sillä he ovat joutilasna, sentähden he huutavat, sanoen: me tahdomme mennä uhraamaan meidän Jumalallemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Rasitettakoon kansa työllä, että heillä olis kyllä tekemistä, eikä luottaisi valhepuheisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Niin kansan teettäjät ja heidän haltiansa menivät ja puhuivat kansalle, sanoen: näin sanoo Pharao: en minä tahdo teille olkia antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Menkäät itse kokoomaan teillenne olkia kusta ikänänsä te löydätte; mutta teidän työstänne ei pidä mitään vähennettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Niin kansa hajotti itsensä koko Egyptin maan ympärinsä hakemaan heillensä sänkiä, että heillä olkia olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Ja teettäjät vaativat heitä, sanoen: täyttäkäät teidän päivätyönne, niinkuin silloinkin, koska teillä olkia oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Ja Israelin lasten haltiat, jotka Pharaon teettäjät heidän päällensä asettaneet olivat, piestiin ja sanottiin heille: miksi ette eilen eikä tänäpänä täyttäneet teidän määrättyä päivätyötänne tiilein tekemisessä, niinkuin ennenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Niin Israelin lasten haltiat menivät ja huusivat Pharaon tykö, sanoen: miksis näin teet palvelioilles?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Ei anneta sinun palvelioilles olkia, ja he sanovat meille: tehkäät tiilit, ja katso, sinun palvelias piestään, ja sinun kansalles nuhde on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Ja hän sanoi: te olette joutilaat, joutilaat te olette, sentähden te sanotte: menkäämme ja uhratkaamme Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Niin menkäät nyt, ja tehkäät työtä. Olkia ei pidä teille annettaman; mutta tiililuvun pitää teidän kuitenkin antaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Niin Israelin lasten haltiat näkivät itsensä olevan ahdistuksessa, sillä (heille) sanottiin: ei teidän pidä vähentämän teidän tiileistänne, kunkin päivän määrästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Ja he kohtasivat Moseksen ja Aaronin, jotka seisoivat heitä vastassa, kuin he läksivät Pharaon tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Joille he sanoivat: Herra nähköön teitä ja tuomitkoon; sillä te olette tehneet meidän haisevaiseksi Pharaon edessä, ja hänen palveliainsa edessä, että te olette miekan antaneet heidän käteensä, surmata meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Moses palasi Herran tykö, ja sanoi: Herra miksis niin pahasti teet tätä kansaa vastaan? Miksis olet minut tänne lähettänyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Sillä sitte kuin minä menin Pharaon tykö, puhuttelemaan häntä sinun nimees, on hän pahoin tehnyt tälle kansalle; ja et sinä ollenkaan ole pelastanut sinun kansaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Niin sanoi myös Herra Mosekselle: nyt pitää sinun näkemän, mitä minä Pharaolle teen; sillä hänen pitää heitä päästämän väkevän käden kautta, ja hänen myös pitää väkevän käden kautta heitä ajaman ulos maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Ja Jumala puhui Mosekselle, ja sanoi hänelle: Minä (olen) Herra,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ja olen näkynyt Abrahamille, Isaakille ja Jakobille kaikkivaltiasna Jumalana. Mutta minun nimessäni HERRA, en ole minä tuttu heiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Ja minä tein myös minun liittoni heidän kanssansa, antaakseni heille Kanaanin maan, heidän vaelluksensa maan, jossa he ovat muukalaiset olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Ja minä olen myös kuullut Israelin lasten huokauksen, joita Egyptiläiset orjuudella vaivaavat, ja olen minun liittoni muistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Sentähden sano Israelin lapsille: minä olen Herra, ja minä johdatan teitä Egyptin kuorman alta, ja pelastan teitä orjuudestanne, ja vapahdan teitä ojetulla käsivarrella ja suurella oikeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Ja otan teitä minun kansakseni, ja olen teidän Jumalanne, että te tietäisitte, että minä olen teidän Jumalanne, joka teitä johdatan ulos Egyptin orjuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Ja vien teitä sille maalle, jonka ylitse minä nostin minun käteni antaakseni sen Abrahamille, Isaakille ja Jakobille; sen minä tahdon antaa teille omaksi: minä Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Näin puhui Moses Israelin lapsille; vaan ei he kuulleet Mosesta henkensä ahdistuksen ja raskaan orjuutensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Silloin puhui Herra Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Mene ja puhu Pharaolle Egyptin kuninkaalle, että hän päästäis Israelin lapset hänen maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mutta Moses puhui Herran edessä, sanoen: katso Israelin lapset ei kuulleet minua, kuinkasta Pharao kuulis minua, ja minulla on myös ympärileikkaamattomat huulet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Niin puhui Herra Mosekselle ja Aaronille, ja käski heitä Israelin lasten ja Pharaon Egyptin kuninkaan tykö, johdattamaan Israelin lapsia ulos Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Nämät olivat heidän isäinsä huonetten päät. Rubenin Israelin esikoisen lapset: Hanok ja Pallu, Hetsron ja Karmi: nämät ovat Rubenin sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Ja Simeonin lapset: Jemuel, Jamin, Ohad, Jakin, Zoar ja Saul, sen Kanaanean vaimon poika: nämät ovat Simeonin sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Ja nämät ovat Levin lasten nimet heidän sukukunnissansa: Gerson, Kahat ja Merari: Mutta Levin elämän vuodet olivat sata ja seitsemänneljättäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Gersonin lapset: Libni ja Simei heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kahatin lapset: Amram, Jesear, Hebro ja Usiel. Mutta Kahatin elämän vuodet olivat sata ja kolmeneljättäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Ja Merarin pojat: Maheli ja Musi: nämät ovat Levin sukukunnat heidän polvisuvussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Ja Amram otti isänsä sisaren Jokebetin emännäksensä, joka synnytti hänelle Aaronin ja Moseksen. Ja Amramin elämän vuodet olivat sata ja seitsemänneljättäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Ja Jetsearin lapset: Kora, Nepheg ja Sikri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Ja Usielin lapset: Misael, Eltsaphan ja Sitri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aaron otti itsellensä emännän Elitseban, Aminadabin tyttären, Nahassonin sisaren, joka hänelle synnytti Nadabin, Abihun, Eleatsarin ja Itamarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Ja Koran lapset: Assir, Elkana ja Abiasaph: nämät ovat Koralaisten sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Mutta Eleatsar Aaronin poika otti itsellensä Putielin tyttäristä emännän, joka synnytti hänelle Pinehaan. Nämät ovat Leviläisten isäin päät heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Nämät ovat Aaron ja Moses, joille Herra sanoi: johdattakaat ulos Israelin lapset Egyptin maalta joukkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Nämät ovat ne, jotka puhuivat Pharaon Egyptin kuninkaan kanssa, että heidän piti johdattaman ulos Israelin lapset Egyptistä: nämät ovat Moses ja Aaron.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Ja sinä päivänä puhui Herra Moseksen kanssa Egyptin maalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Ja sanoi hänelle: Minä olen Herra: puhu Pharaolle Egyptin kuninkaalle kaikki, mitä minä sinulle puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Niin vastasi Moses Herralle: katso, minä olen ympärileikkaamatoin huulilta, kuinkasta Pharao minua kuulee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Ja Herra sanoi Mosekselle: katso, minä olen asettanut sinun Pharaon Jumalaksi. Ja veljes Aaron pitää oleman sinun prophetas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Sinun pitää puhuman kaikki, mitä minä käsken sinulle, vaan Aaron sinun veljes pitää sen puhuman Pharaolle: että hän päästäis Israelin lapset maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Mutta minä tahdon paaduttaa Pharaon sydämen, ja tehdä monta minun ihmettäni ja tunnustähteäni Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Ja ei Pharao kuule teitä; ja minä tahdon osoittaa minun käteni Egyptissä, ja johdatan ulos minun joukkoni, minun kansani Israelin lapset Egyptin maalta suurella oikeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Ja Egyptiläisten pitää tietämän, että minä olen Herra, ojetessani kättäni Egyptin ylitse, ja johdattaissani ulos Israelin lapset heidän keskeltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Moses ja Aaron tekivät niinkuin Herra oli heille käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Ja Moses oli kahdeksankymmenen ajastaikainen, ja Aaron kolmen ajastaikainen yhdeksättäkymmentä, koska he puhuivat Pharaon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Koska Pharao puhuu teille, sanoen: osoittakaat teidän ihmeenne. Niin sinun pitää sanoman Aaronille: ota sauvas, ja heitä Pharaon eteen, ja se tulee kärmeeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Niin Moses ja Aaron menivät Pharaon tykö, ja tekivät niinkuin Herra oli käskenyt. Ja Aaron heitti sauvansa Pharaon ja hänen palveliainsa eteen, ja se tuli kärmeeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Niin Pharao myös kutsui tietäjät ja noidat, ja Egyptin noidat tekivät myös niin noitumisillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Ja itsekukin heistä heitti sauvansa maahan, ja ne tulivat kärmeiksi. Mutta Aaronin sauva nieli heidän sauvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Niin Pharaon sydän paatui, eikä myös kuullut heitä: niinkuin Herra oli sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Ja Herra sanoi Mosekselle: Pharaon sydän on kovettunut, ja ei tahdo päästää kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Mene Pharaon tykö varhain aamulla, katso, hän kävelee vetten tykönä, ja seiso häntä vastassa virran reunalla, ja se sauva, joka oli kärmeeksi muuttunut, ota sinun kätees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Ja sano hänelle: Herra Hebrealaisten Jumala on minun lähettänyt sinun tykös, sanoen: laske minun kansani palvelemaan minua korvessa; ja katso, et ole sinä kuullut tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Sentähden sanoo Herra näin: tästä pitää sinun tunteman minun olevan Herran: katso, minä lyön tällä sauvalla, joka on minun kädessäni, veteen, joka virrassa on, ja sen pitää muuttuman vereksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Niin että kalat, jotka virrassa ovat, pitää kuoleman, ja virran pitää haiseman, ja Egyptiläiset pitää kyylymän, koska he juovat vettä virrasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Ja Herra sanoi Mosekselle: sano Aaronille: ota sauvas, ja ojenna kätes Egyptin vetten ylitse, ja heidän virtainsa ylitse, ja heidän jokeinsa ylitse, ja heidän järveinsä ylitse, ja kaikkein heidän vesilammikkoinsa ylitse, ja ne pitää tuleman vereksi, ja pitää oleman veri koko Egyptin maassa, sekä puuastioissa että myös kiviastioissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Niin Moses ja Aaron tekivät niinkuin Herra oli käskenyt, ja hän nosti sauvan ja löi veteen, joka virrassa oli, Pharaon ja hänen palveliainsa edessä: ja kaikki vedet, jotka olivat virrassa, muuttuivat vereksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Ja kala, jotka olivat virrassa, kuolivat, ja virta haisi, niin ettei Egyptiläiset saaneet juoda vettä virrasta. Ja veri oli koko Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Egyptin noidat tekivät myös niin noituuksillansa. Mutta Pharaon sydän paatui, ja ei kuullut heitä: niinkuin Herra sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Ja Pharao käänsi itsensä ja palasi kotiansa, ja ei pannut sitäkään sydämeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Mutta kaikki Egyptiläiset kaivoivat virran ympärillä vettä juodaksensa; sillä ei he saaneet juoda virran vesistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Ja se oli täyttä seitsemän päivää, sittenkuin Herra oli lyönyt virran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Ja Herra sanoi Mosekselle: mene Pharaon tykö, ja sano hänelle: näin sanoo Herra: päästä minun kansani palvelemaan minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Vaan jos et sinä tahdo päästää; katso, niin minä rankaisen kaikki sinun maas ääret sammakoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Niin että virran pitää kuohuman sammakoista, ja ne pitää astuman ylös, ja tuleman sinun huoneesees, ja sinun lepokammioos, ja sinun vuoteesees, niin myös sinun palveliais huoneesen, ja sinun kansas sekaan, ja sinun pätsiis, sinun taikina-astioihis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Ja sinun päälles, ja sinun kansas ja kaikkein sinun palveliais päälle, pitää sammakot hyppelemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Ja Herra sanoi Mosekselle: sanos Aaronille: ojenna kätes sauvoinensa virtain, jokein ja järvein ylitse, ja anna sammakot nousta ylitse koko Egyptin maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Ja Aaron ojensi kätensä Egyptin vetten ylitse; ja sammakot tulivat sieltä ylös, ja peittivät koko Egyptin maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Tekivät myös noidat niin noituuksillansa: ja antoivat sammakot tulla Egyptin maan ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Niin Pharao kutsui Moseksen ja Aaronin, ja sanoi: rukoilkaat Herraa, että hän ottais pois sammakot minulta ja minun kansaltani; niin minä päästän kansan uhraamaan Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Moses sanoi: pidä sinä se kunnia, (ettäs määräät) koska minun pitää rukoileman edestäs, ja palveliais ja kansas edestä, että sammakot pitäis hukutettaman sinulta, ja sinun huoneistas, ainoastansa virtaan jäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Hän sanoi: huomenna. Hän vastasi: olkoon sanas jälkeen, ettäs tietäisit, ettei yksikään ole niinkuin Herra, meidän Jumalamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Silloin sammakot pitää otettaman pois sinulta, ja sinun huoneistas, ja sinun palvelioiltas, ja sinun kansaltas, ainoastansa virtaan jäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Niin Moses ja Aaron läksivät Pharaon tyköä: ja Moses huusi Herran tykö sammakkoin tähden, jotka hän Pharaon päälle pannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Ja Herra teki Moseksen sanan jälkeen: ja sammakot kuolivat huoneista, kylistä ja kedoilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Ja he heittivät ne suuriin roukkioihin, ja maa haisi siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Kun Pharao näki levon saaneensa, paadutti hän sydämensä, ja ei kuullut heitä: niinkuin Herra sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Ja Herra sanoi Mosekselle: sano Aaronille: ojenna sauvas, ja lyö maan tomuun, että se tulis täiksi koko Egyptin maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Ja he tekivät niin: ja Aaron ojensi kätensä sauvoinensa, ja löi maan tomua, ja täit tulivat ihmisiin ja eläimiin: ja kaikki maan tomu muuttui täiksi koko Egyptin maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Tekivät myös noidat noituuksillansa niin, täitä matkaan saattaaksensa; vaan ei he taitaneet. Ja täit olivat ihmisissä ja eläimissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Niin sanoivat noidat Pharaolle: tämä on Jumalan sormi. Mutta Pharaon sydän paatui, ja ei kuullut heitä: niinkuin Herra sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Ja Herra sanoi Mosekselle: nouse huomenna varhain, ja seiso Pharaon edessä; katso, hän menee vetten tykö, ja sano hänelle: näin sanoo Herra: päästä minun kansani palvelemaan minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Sillä jos et sinä päästä minun kansaani; katso, niin minä tahdon lähettää sinulle, ja sinun palvelioilles, ja sinun kansalles, ja sinun huoneisiis kaikkinaiset turilaat, niin että kaikki huoneet Egyptissä täytetään turilaista, niin myös se maa jonka päällä he ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Ja minä tahdon eroittaa sinä päivänä Gosenin maan, jossa minun kansani asuu, ettei siinä yhtään turilasta pidä oleman: ettäs tietäisit minun olevan Herran koko maan keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Ja minä panen lunastuksen minun ja sinun kansas välille. Huomenna pitää tämän ihmeen tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Ja Herra teki niin. Ja tuli paljo turilaita Pharaon huoneesen, ja hänen palveliainsa huoneisiin, ja koko Egyptin maalle; ja maa turmeltiin turilailta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Niin kutsui Pharao Moseksen ja Aaronin, ja sanoi: menkäät ja uhratkaat teidän Jumalallenne tällä maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Moses sanoi: ei sovi niin tehdä; sillä me uhraisimme Herralle meidän Jumalallemme Egyptiläisten kauhistuksen: katso, jos me Egyptin maan kauhistukset uhraisimme heidän edessänsä, eikö he meitä kivittäisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Kolmen päiväkunnan matkan menemme me korpeen, ja uhraamme Herralle meidän Jumalallemme, niinkuin hän on meille sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Pharao sanoi: minä päästän teidät, että te uhraisitte Herralle teidän Jumalallenne korvessa, ainoastansa ettétte kauvas menisi; rukoilkaat minun edestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Moses sanoi: Katso, kuin minä menen sinun tyköäs, niin minä rukoilen Herraa, että turilaat otettaisiin pois Pharaolta, ja hänen palvelioiltansa, ja hänen kansaltansa huomenna: ainoastansa älä minua enää viettele, niin ettes päästä kansaa uhraamaan Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Ja Moses läksi Pharaon tyköä, ja rukoili Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Ja Herra teki niinkuin Moses sanonut oli: ja otti turilaat Pharaolta ja hänen palvelioiltansa, ja hänen kansaltansa pois, niin ettei yhtäkään jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mutta Pharao paadutti sydämensä vielä nyt tälläkin haavaa ja ei päästänyt kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Niin Herra sanoi Mosekselle mene Pharaon tykö, ja sano hänelle: näin sanoo Herra Hebrealaisten Jumala: päästä minun kansani palvelemaan minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Vaan jolles päästä, mutta vielä pidätät heitä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Katso, Herran käsi on sinun karjas päällä, jotka ovat kedolla, hevosten päällä, aasein päällä, kamelein päällä, härkäin päällä, lammasten päällä, sangen raskaan ruttotaudin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Ja Herra on eroittava Israelin karjan Egyptin karjasta, niin ettei mitään kuole kaikesta kuin Israelin lapsilla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Ja Herra määräsi ajan, sanoen: tämän Herra tekee huomenna maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Ja Herra teki niin toisna päivänä, ja kaikki Egyptin karja kuoli: vaan Israelin lasten karjasta ei yhtäkään kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Niin Pharao lähetti (tiedustelemaan) ja katso, ei ollut Israelin karjasta yhtäkään kuollut. Mutta Pharaon sydän paatui, ja ei päästänyt kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Ja Herra sanoi Mosekselle ja Aaronille: ottakaat kätenne täyteen toton nokea, ja Moses paiskatkaan sen taivaasen päin Pharaon edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Ja pitää tuleman tomuksi koko Egyptin maan päälle, ja pitää oleman ihmisten ja karjan päällä märkäpäistä punottavaiset paisumat koko Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Ja he ottivat nokea totosta, ja seisoivat Pharaon edessä, ja Moses paiskasi sen taivaasen päin: niin tulivat märkäpäistä punottavaiset paisumat ihmisiin ja karjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Niin ettei noidatkaan saaneet seisoa Moseksen edessä paisumain tähden: sillä paisumat olivat niin noitain päällä, kuin kaikkien Egyptiläisten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Mutta Herra paadutti Pharaon sydämen, ja ei hän kuullut heitä: niinkuin Herra Mosekselle sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Niin sanoi Herra Mosekselle: nouse huomenna varhain, ja seiso Pharaon edessä, ja sano hänelle: Näin sanoo Herra Hebrealaisten Jumala: päästä minun kansani palvelemaan minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Muutoin minä tällä haavaa lähetän kaikki minun rangaistukseni sinun sydämees, ja sinun palveliais, ja sinun kansas päälle, tietääkses, ettei kaikessa maassa ole minun vertaani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Sillä minä olisin nyt jo ojentanut käteni, ja lyönyt sinun ja sinun kansas ruttotaudilla: että sinun olis täytynyt hukkua maan päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Mutta tosin sentähden olen minä sinun antanut seisoa, että minä osoittaisin sinulle minun voimani, ja että minun nimeni julistettaisiin kaikessa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ja vieläkös nyt ylennät itses minun kansani päälle, etkä päästä heitä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Katso, huomenna tällä ajalla annan minä sangen suuria rakeita sataa, jonka kaltaisia ei ole ollut Egyptissä, hamasta siitä päivästä kuin se perustettu on, niin tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Lähetä siis nyt ja korjaa sinun karjas ja kaikki mitä sinulla on kedolla; sillä kaikki ihmiset ja karja kuin kedolla löydetään, ja ei ole korjatut huoneesen, niiden päälle lankeevat rakeet ja heidän pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Joka Pharaon palvelioista pelkäsi Herran sanaa, se palveliansa ja karjansa huoneesen korjasi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Vaan jonka sydän ei totellut Herran sanaa, se jätti kedolle palveliansa ja karjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Niin sanoi Herra Mosekselle: ojenna kätes taivaasen päin, että rakeita satais koko Egyptin maan päälle: ihmisten päälle, karjan päälle, ja kaikkein päälle, mitä kedolla vihottaa Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Niin ojensi Moses sauvansa taivaasen päin, että Herra antais jylistä ja rakeita sataa, ja että pitkäisen tuli leimahtelis maan päälle; ja Herra antoi sataa rakeita Egyptin maan päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Että rakeet ja tuli sekaisin maahan lankesivat, niin raskaasti, ettei ikänänsä senkaltaista kaikessa Egyptin maassa tapahtunut ollut, siitä ajasta kuin kansa siinä asumaan rupesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Ja rakeet löivät koko Egyptin maalla kaikki kuin kedolla olivat, sekä ihmiset että karjan: niin myös koko maan vihannan löivät rakeet kaikki, myös puut kedolla särkivät rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Ainoasti Gosenin maakunnassa, jossa Israelin lapset olivat, ei rakeita ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Niin lähetti Pharao ja kutsui Moseksen ja Aaronin, ja sanoi heille: minä olen tällä haavalla pahoin tehnyt; Herra on vanhurskas, vaan minä ja minun kansani olemme jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Sentähden rukoilkaat Herraa, että jo kyllä olis, ja että Jumalan jylinä ja rakeet lakkaisivat: niin minä päästän teidät, eikä teidän pidä enempi täällä viipymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Ja Moses sanoi hänelle: koska minä lähden kaupungista, niin minä ojennan käteni Herran tykö: niin jylinä lakkaa ja rakeita ei pidä enempi oleman, ettäs tietäisit maan olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mutta et sinä ja sinun palvelias, minä kyllä tiedän, vielä nytkään pelkää Herraa Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Niin pellavat ja ohrat maahan lyötiin; sillä ohra oli tähkäpäällä ja pellava oli kulkulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Mutta nisu ja kaura (a) ei turmeltuneet, sillä ne olivat hiljakylvöt. (a) Spelta eli Turkin kaura.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Niin Moses meni ulos kaupungista Pharaon tyköä, ja ojensi kätensä Herran tykö: ja jylinä ja rakeet lakkasivat, ja sade ei enempi vuodatettu maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Koska Pharao näki, että sade, ja rakeet, ja jylinät lakkasivat, teki hän vielä enemmin pahaa, ja paadutti sydämensä, sekä hän että hänen palveliansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Niin paatui Pharaon sydän, ja ei päästänyt Israelin lapsia: niinkuin Herra Moseksen kautta sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Ja Herra sanoi Mosekselle: mene Pharaon tykö; sillä minä paadutin hänen ja hänen palveliainsa sydämet, tehdäkseni nämät minun ihmeeni heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Ja että sinä ilmoittaisit sinun lastes, ja sinun lastes lasten korviin, mitä minä tehnyt olen Egyptissä, ja minun ihmeeni, jotka minä tein heidän seassansa, että te tietäisitte, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Niin menivät Moses ja Aaron Pharaon tykö, ja sanoivat hänelle: näin sanoo Herra Hebrealaisten Jumala: kuinka kauan et sinä tahdo nöyryyttää itsiäs minun edessäni? Päästä minun kansani palvelemaan minua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Sillä jos sinä estelet päästää minun kansani; katso, niin minä huomenna tuotan heinäsirkat kaikkiin sinun maas ääriin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Niin että heidän pitää peittämän maan, niin ettei maa pidä näkymän; ja heidän pitää syömän tähteet, mitkä teille on jääneet rakeilta, ja pitää syömän kaikki vihottavaiset puut teidän kedollanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Ja täyttämän sinun huonees, ja kaikkein sinun palveliais huoneet, ja koko Egyptin huoneet; jonka kaltaisia sinun isäs ja isäis-isät ei nähneet ole, siitä päivästä kuin he maan päällä olleet ovat tähän päivään asti. Ja hän käänsi itsensä ja meni ulos Pharaon tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Niin sanoivat Pharaon palveliat hänelle: kuinka kauvan pitää hänen oleman meille paulaksi? Päästä kansa palvelemaan Herraa Jumalaansa: etkös vielä tiedä Egyptiä hävitetyksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Niin Moses ja Aaron palautettiin jällensä Pharaon tykö, joka sanoi heille: menkäät ja palvelkaat Herraa teidän Jumalaanne; vaan kutka ne ovat jotka menevät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Ja Moses sanoi: me menemme meidän nuorten ja vanhain kanssa, poikinemme ja tyttärinemme, lammastemme ja karjamme kanssa; sillä meillä on Herran juhla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Ja hän sanoi heille: ikään niin, olkoon Herra teidän kanssanne. Pitäiskö minun päästämän teidät ja teidän lapsenne? Katsokaat, jollei teillä jotakin pahaa sydämessänne ole?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Ei niin, mutta menkäät te miehet ja palvelkaat Herraa; sillä sitä te olette pyytäneetkin. Ja he ajoivat heidät pois Pharaon edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Niin sanoi Herra Mosekselle: ojenna kätes Egyptin maan ylitse heinäsirkkain tähden, että he tulisivat Egyptin maan päälle, ja söisivät kaiken maan vihannon, kaikki mitä rakeilta jäänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Moses ojensi sauvansa Egyptin maan ylitse, ja Herra antoi tulla itätuulen sille maalle kaiken sen päivän ja kaiken sen yön; ja aamulla nosti itätuuli heinäsirkat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Ja tulivat heinäsirkat koko Egyptin maan päälle, laskivat itsensä joka paikkaan Egyptin maalle, niin epälukuiset, ettei heidän kaltaisiansa heinäsirkkoja ennen ollut, eikä tästedes tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Ja he peittivät kaiken maan, ja maa tuli mustaksi. Ja söivät kaikki maan vihannon, ja kaikki puiden hedelmät kuin jääneet olivat rakeilta, ja ei jäänyt ensinkään viheriäistä puihin ja kedon ruohoihin koko Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Niin kutsui Pharao kiiruusti Moseksen ja Aaronin, ja sanoi: minä olen pahaa tehnyt Herraa teidän Jumalaanne, ja teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Niin anna nyt minulle anteeksi minun rikokseni vielä tällä erällä, ja rukoilkaat Herraa teidän Jumalaanne, että hän ottais minulta pois vielä tämän kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Ja hän meni pois Pharaon tyköä, ja rukoili Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Niin Herra käänsi tuulen aivan tuimaksi länsituuleksi, ja nostatti heinäsirkat ja heitti heidät Punaiseen mereen, niin ettei yhtäkään heinäsirkkaa jäänyt koko Egyptin maan ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mutta Herra paadutti Pharaon sydämen, ja ei hän päästänyt Israelin lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Ja Herra sanoi Mosekselle: ojenna kätes taivaaseen päin, että pimeys tulis Egyptin maan päälle, niin että pimeyteen ruveta taidettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Ja Moses ojensi kätensä taivaaseen päin, niin tuli synkiä pimeys koko Egyptin maan päälle kolmeksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Niin ettei toinen toistansa nähnyt, eikä myös noussut paikastansa kolmena päivänä. Mutta kaikilla Israelin lapsilla oli valkeus heidän asuinsioissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Niin kutsui Pharao Moseksen, ja sanoi: menkäät ja palvelkaat Herraa; ainoastansa teidän lampaanne ja karjanne jääkään tänne: teidän lapsenne menkään myös teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Moses sanoi: sinun pitää myös salliman minun käsiini uhrini, ja polttouhrin, jota meidän pitää tekemän Herralle meidän Jumalallemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Meidän karjamme pitää myös menemän meidän kanssamme, ja ei yhtäkään sorkkaa jäämän; sillä siitä meidän pitää ottaman ja tekemän palveluksen Herralle meidän Jumalallemme: ja emme tiedä, millä me palvelemme Herraa, siihenasti kuin me sinne tulemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mutta Herra paadutti Pharaon sydämen, ja ei hän tahtonut päästää heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Ja Pharao sanoi hänelle: mene pois minun tyköäni, ja karta ettes enempi silleen tule minun kasvoini eteen; sillä jona päivänä sinä tulet minun eteeni, pitää sinun kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Moses vastasi: niinkuin sinä sanonut olet, en tule minä enempi sinun kasvois eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Ja Herra oli sanonut Mosekselle: vielä minä annan tulla yhden rangaistuksen Pharaolle ja Egyptiin, sitte hän päästää teidät täältä, ja koska hän teidät kokonansa päästää, niin hän ajain ajaa teidät täältä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Niin sano siis nyt kansalle: että joka mies anois lähimmäiseltänsä, ja jokainen vaimo lähimmäiseltänsä, hopia- ja kulta-astioita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Sillä Herra oli antanut armon kansalle Egyptiläisten edessä. Ja Moses oli sangen kuuluisa mies Egyptin maalla, Pharaon palveliain ja kansan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Ja Moses sanoi: näin sanoo Herra: puoliyön aikaan minä vaellan Egyptin maan lävitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Ja jokainen esikoinen Egyptin maalla pitää kuoleman, Pharaon esikoisesta, joka hänen istuimellansa piti istuman, piian esikoiseen asti, joka myllyssä on, niin myös kaikkein eläinten esikoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Ja suuren parun pitää oleman koko Egyptin maalla, jonkakaltaista ei ole ollut, eikä tuleman pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mutta kaikkein Israelin lasten seassa ei koirakaan kieltänsä värväyttämän pidä ihmisiä taikka eläimiä vastaan: että te tietäisitte, kuinka Herra eroittaa Egyptin ja Israelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Silloin kaikki nämät sinun palvelias pitää tuleman minun tyköni, ja kumartaman minua, sanoen: lähde ulos, sinä ja kaikki kansa, jotka sinun allas ovat, ja sitte minä lähden. Ja hän läksi Pharaon tyköä sangen vihoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Mutta Herra oli sanonut Mosekselle: ei Pharao kuule teitä, että paljo minun ihmeitäni tapahtuis Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Ja Moses ja Aaron tekivät kaikki nämä ihmeet Pharaon edessä, vaan Herra paadutti hänen sydämensä, ja ei hän päästänyt Israelin lapsia maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Herra oli puhunut Mosekselle ja Aaronille Egyptin maalla, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Tämä kuukausi pitää oleman teidän tykönänne ensimäinen kuu; hänestä pitää teidän alkaman ajastajan kuukaudet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Puhukaat koko Israelin seurakunnalle, sanoen: kymmenentenä päivänä tällä kuulla ottakaan itsekukin itsellensä karitsan, se joka perheen isäntä on, karitsan joka huoneelle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Vaan jos yksi huone vähä on karitsaa syömään, niin ottakaan kylänsä miehen kanssansa, joka likin hänen huonettansa on, että niin monta tulis, kuin voisivat karitsan syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ja sen karitsan pitää teille oleman virheettömän ajastaikaisen oinaan. Karitsoista eli vohlista pitää teidän sen ottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Ja sen teidän pitää tallella pitämän neljänteentoistakymmenenteen päivään asti tätä kuuta, ja koko Israelin kansan kokous pitää sen teurastaman kahden ehtoon välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Ja heidän pitää ottaman verestä, ja sivuman molemmat pihtipielet ja huonetten ovenpäällisen, joissa he sitä syövät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Ja heidän pitää sinä yönä syömän lihaa tulella paistettua ja happamatointa leipää; katkerain ruohoin kanssa pitää heidän sen syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ei teidän pidä sitä syömän uutena eikä vedellä keitettynä, mutta tulella paistettuna, pään, jalkain ja sisällysten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Eikä teidän pidä jättämän mitään huomeneksi; ja jos jotakin jää huomeneksi, se tulella poltettakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Mutta näin pitää teidän syömän sitä: teidän pitää oleman vyötetyt kupeista, ja kengät jalassanne, ja sauva kädessänne, ja pitää sen syömän niinkuin matkaan kiiruhtavaiset: se on Herran pääsiäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Sillä minä käyn sinä yönä Egyptin maan lävitse, ja lyön kaikki esikoiset Egyptin maalla, ihmisistä karjaan asti, ja annan tulla minun rangaistukseni kaikkein Egyptiläisten epäjumalain päälle: Minä Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Ja veren pitää oleman teille merkiksi huoneissanne, kussa te olette, että koska minä veren näen, niin minä menen teidän ohitsenne: ja ei pidä teille tuleman se rangaistus kadottamaan teitä, koska minä lyön Egyptin maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Ja tämä päivä pitää oleman teille muistoksi, ja teidän pitää sen pyhittämän juhlaksi Herralle: ijankaikkiseksi säädyksi teidän sukukunnissanne teidän sen pyhittämän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Seitsemän päivää pitää teidän syömän happamatointa leipää, nimittäin ensimäisenä päivänä pitää teidän paneman pois happaman leivän teidän huoneissanne: sillä jokainen kuin hapointa leipää syö ensimäisestä päivästä niin seitsemänteen päivään asti, hänen sielunsa pitää hukutettaman Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Ensimäisenä päivänä on teillä pyhä kokous, ja myös seitsemäntenä päivänä on teillä pyhä kokous. Ei yhtäkään työtä pidä tehtämän niinä päivinä, mutta vaivoin mitä ruaksi tarvitaan jokaiselle hengelle, se ainoastansa tehkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Ja pitäkäät happamatoin leipä; sillä sinä päivänä olen minä teidän joukkonne johdattanut Egyptin maalta: ja teidän pitää pitämän tämän päivän teidän sukukunnissanne ijankaikkiseksi säädyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Neljäntenätoistakymmenentenä päivänä ensimäisestä kuusta ehtoona pitää teidän syödä happamatointa leipää, hamaan ensimäiseen päivään asti kolmattakymmentä siitä kuusta, ehtoona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Niin ettei seitsemänä päivänä löydetä hapointa leipää teidän huoneissanne; sillä jokainen joka hapointa leipää syö, hänen sielunsa pitää hukutettaman Israelin joukosta, joko hän muukalainen on eli omainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Sentähden älkäät ensinkään syökö hapointa leipää; vaan happamatointa leipää syökäät kaikissa teidän asuinsioissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Ja Moses kutsui kaikki Israelin vanhimmat, ja sanoi heille: menkäät ja ottakaat teillenne lampaita kukin perhekuntansa jälkeen, ja teurastakaat pääsiäiseksi');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Ja ottakaat side isoppia, ja kastakaat vereen, joka on maljassa, ja sivukaat sillä oven päällinen, ja molemmat pihtipielet: ja ei yksikään ihminen pidä menemän ulos huoneensa ovesta huomeniseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Sillä Herra tahtoo käydä ohitse lyömään Egyptiläisiä: ja koska hän saa nähdä veren ovenpäällisessä ja molemmissa pihtipielissä, menee Herra sen oven ohitse, ja ei salli hukuttajan tulla teidän huoneisiinne rankaisemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Sentähden pidä tämä sääty sinulle ja sinun lapsilles ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Ja koska te tulette siihen maahan, jonka Herra teille antava on, niinkuin hän sanonut on, niin pitäkäät tämä palvelus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Ja koska teidän lapsenne sanovat teille: mikä palvelus tämä teillä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Niin teidän pitää sanoman: tämä on Herran pääsiäisuhri, joka ohitse meni Israelin lasten huoneet Egyptissä, koska hän rankaisi Egyptiläisiä, ja meidän huoneemme vapahti: niin kansa maahan kumartain rukoili.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Ja Israelin lapset menivät ja tekivät niinkuin Herra Mosekselle ja Aaronille käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Ja tapahtui puoliyön aikana, että Herra löi kaikki esikoiset Egyptin maalla, Pharaon esikoisesta, joka hänen istuimellansa istuman piti, niin vangin esikoiseen asti, joka oli vankihuoneessa, ja kaikki eläinten esikoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Sinä yönä nousi Pharao ja kaikki hänen palveliansa, ja kaikki Egyptiläiset, ja suuri parku oli Egyptissä; sillä ei siellä ollut huonetta, jossa ei kuollutta ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Ja hän kutsui Moseksen ja Aaronin yöllä, ja sanoi: nouskaat ja menkäät pois minun kansastani, sekä te että Israelin lapset: ja menkäät matkaanne ja palvelkaat Herraa, niinkuin te sanoneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ottakaat myös myötänne teidän lampaanne ja teidän karjanne, niinkuin te sanoneet olette, menkäät matkaanne; ja siunatkaat myös minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Ja Egyptiläiset vaativat kansaa, ja hoputtaen ajoivat heitä pois maalta; sillä he sanoivat: me kuolemme jokainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Ja kansa kantoi taikinansa, ennenkuin se happani, nimittäin tähteensä, sidottuna vaatteisiin olallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Ja Israelin lapset olivat tehneet Moseksen sanan jälkeen, ja olivat anoneet Egyptiläisiltä hopia- ja kultaastioita ja vaatteita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Ja Herra oli antanut kansalle armon Egyptiläisten edessä, että he lainasivat, ja niin he paljastivat Egyptiläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Niin matkustivat Israelin lapset Rameksesta Sukkotiin, lähes kuusisataa tuhatta jalkamiestä, paitsi lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Ja paljo kaikkinaista kansaa meni heidän kanssansa, ja lampaita, ja karjaa, ja sangen paljon eläimiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Ja he leipoivat siitä uudesta taikinasta, jonka he olivat tuoneet Egyptistä, happamattomia leipiä; sillä ei se ollut hapannut, sentähden että he ajettiin Egyptistä pois, eikä myös saaneet viipyä, ja ei semminkään saaneet heillensä evästä valmistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Se aika kuin Israelin lapset asuivat Egyptissä, oli neljäsataa ja kolmekymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Ja koska ne olivat kuluneet, läksi koko Herran joukko yhtenä päivänä Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Sentähden tämä yö pidetään Herralle, että hän vei heidät ulos Egyptin maalta: tämä on se yö, joka pidettämän pitää Herralle kaikilta Israelin lapsilta heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Ja Herra sanoi Mosekselle ja Aaronille: tämä on sääty pitää pääsiäistä: ei yksikään muukalainen pidä siitä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Jokainen ostettu orja pitää ympärileikattaman, ja sitten syökään siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Muukalainen ja päivämiehen ei pidä syömän sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Yhdessä huoneessa pitää se syötämän. Ei teidän pidä huoneesta viemän ulos sitä lihaa, eikä teidän pidä luuta rikkoman siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Koko Israelin seurakunta pitää näin tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Jos joku muukalainen asuu sinun tykönäs, ja tahtoo pitää Herralle pääsiäistä, niin ympärileikattakaan kaikki miehenpuolet, ja sitten käykään sitä tekemään, ja olkaan niinkuin maan omainen; sillä ei yhdenkään ympärileikkaamattoman pidä sitä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Yksi sääty pitää oleman omaisella ja muukalaisella, joka asuu teidän seassanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Ja kaikki Israelin lapset tekivät niinkuin Herra oli Mosekselle ja Aaronille käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Niin Herra yhtenä päivänä johdatti Israelin lapset ulos Egyptin maalta, heidän joukoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Ja Herra puhui Mosekselle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Pyhitä minulle jokainen esikoinen, kuka ikänänsä äitinsä kohdun avaa Israelin lasten seassa, sekä ihmisistä että eläimistä: ne ovat minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Niin sanoi Moses kansalle: muistakaat tämä päivä, jona te olette lähteneet Egyptistä, orjuuden huoneesta, että Herra on teidät täältä johdattanut väkevällä kädellä. Sentähden ei pidä syötämän hapointa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Tänäpänä olette lähteneet, sillä kuulla Abib.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Ja on tapahtuva, koska Herra sinun tulla antaa Kanaanealaisten, Hetiläisten, Amorilaisten, Heviläisten ja Jebusilaisten maalle, jonka hän sinun isilles on vannonut antaaksensa sinulle: sen maan, jossa rieskaa ja hunajaa vuotaa, niin sinun pitää tämän palveluksen tekemän tällä kuulla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Seitsemän päivää pitää sinun syömän happamatointa leipää, ja seitsemäntenä päivänä on Herran juhla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Sentähden pitää seitsemän päivää syötämän happamatointa leipää, ja ei pidä sinun tykönäs yhtään hapointa taikinaa nähtämän; eikä hapointa leipää pidä nähtämän kaikissa sinun maas äärissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Ja sinun pitää ilmoittaman sinun pojalles sinä päivänä, sanoen: (tämän minä pidän) sentähden että Herra teki näin minun kanssani, koska minä läksin Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Sentähden pitää tämä oleman sinulle merkiksi sinun kädessäs, ja muistoksi sinun edessäs, että Herran käsky pitää oleman sinun suussas; sillä Herra on väkevällä kädellä sinun johdattanut Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Sentähden pidä tämä sääty ajallansa vuosi vuodelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Ja koska Herra on sinun vienyt Kanaanealaisten maalle, niinkuin hän sinulle ja sinun isilles vannonut on, ja antanut sen sinulle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Niin pitää sinun eroittaman Herralle jokaisen kuin avaa äitinsä kohdun, ja jokaisen esikoisen eläinten seassa, kuin sinulla on: kaikki miehenpuoli on Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mutta kaikki aasin esikoiset pitää sinun lunastaman karitsalla; jollet sinä lunasta sitä, niin väännä niskat rikki. Mutta jokaisen esikoisen ihmisistä sinun lastes seassa pitää sinun lunastaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Ja koska sinun poikas kysyy sinulta tästedes: mikä tämä on? pitää sinun sanoman hänelle: Herra on johdattanut meitä väkevällä kädellä Egyptistä, orjuuden huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Sillä se tapahtui, koska Pharao kovuutti itsensä ja ei tahtonut meitä päästää, että Herra löi kuoliaaksi jokaisen esikoisen Egyptin maalla, ihmisen esikoisesta niin eläinten esikoiseen asti: sentähden uhraan minä Herralle jokaisen kuin äitinsä kohdun avaa, joka miehenpuoli on, ja jokaisen, esikoisen minun lapsistani lunastan minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Ja tämän pitää oleman merkiksi sinun kädessäs, ja muistoksi sinun edessäs: että Herra on johdattanut meidät väkevällä kädellä Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Ja tapahtui, koska Pharao oli päästänyt kansan, niin ei Jumala johdattanut heitä tietä Philistealaisten maan lävitse, joka tärkin oli; sillä Jumala sanoi, ettei kansa joskus katuisi, koska he näkisivät sodan heitänsä vastaan, ja palajaisi Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Sentähden hän johdatti kansan ympärinsä, korven lävitse Punaista merta kohden. Ja Israelin lapset läksivät viisin joukoin Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Ja Moses otti myötänsä Josephin luut: sillä hän oli kovasti vannottanut Israelin lapset, sanoen: Jumala on tosin teitä etsivä, niin viekäät minun luuni täältä myötänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Niin he läksivät Sukkotista, ja sioittivat heitänsä Etamiin, joka on korven ääressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Ja Herra kävi heidän edellänsä päivällä pilven patsaassa, johdattaaksensa heitä tiellä, ja yöllä tulen patsaassa, valistaaksensa heitä vaeltamaan, sekä yöllä että päivällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Pilven patsas ei erinnyt päivällä, eikä tulen patsas yöllä kansan edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Ja Herra puhui Mosekselle sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Puhu Israelin lapsille, että he palajaisivat ja sioittaisivat heitänsä Hiirotin laakson kohdalle, Migdolin ja meren vaiheelle, BaalZephonin eteen ja sen kohdalle sioittaen heitänsä meren tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Ja Pharao sanoo Israelin lapsista: he käyvät eksyksissä maalla, korpi on heidät sulkenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Ja minä paadutan Pharaon sydämen, ja hän ajaa heitä takaa; ja minä voitan kunnian Pharaosta ja kaikesta hänen sotaväestänsä. Ja Egyptiläisten pitää tietämän, että minä olen Herra. Ja he tekivät niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Ja kuin sanottiin Egyptin kuninkaalle, että kansa pakeni, tuli hänen ja hänen palveliainsa sydän käännetyksi kansaa vastaan, ja he sanoivat: miksi me olemme niin tehneet, että me päästimme Israelin palvelemasta meitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Ja hän valmisti vaununsa, ja otti väkensä myötänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Ja otti kuusisataa parasta vaunua, niin myös kaikki muut Egyptin vaunut, ja päämiehet niiden kaikkein päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Ja Herra paadutti Pharaon Egyptin kuninkaan sydämen, ja hän ajoi takaa Israelin lapsia, jotka kuitenkin olivat korkian käden kautta lähteneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Niin Egyptiläiset ajoivat heitä takaa, ja saavuttivat heidät meren tykönä, kussa he itsensä sioittaneet olivat, kaikki Pharaon vaunuhevoset, hänen ratsasmiehensä, ja hänen sotajoukkonsa: Hiirotin laaksossa, BaalZephonin kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Ja kuin Pharao lähestyi heitä, nostivat Israelin lapset silmänsä, ja katso, Egyptiläiset tulivat heidän perässänsä; ja Israelin lapset peljästyivät sangen suuresti, ja huusivat Herran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Ja sanoivat Mosekselle: Eikö hautoja ollut Egyptissä, ettäs rupesit meitä johdattamaan korpeen kuolemaan? Miksis meille niin olet tehnyt: ettäs meitä johdatit Egyptistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Eikö tämä se ole, kuin me puhuimme Egyptissä, sanoen: anna meidän olla, että me palvelisimme Egyptiläisiä; sillä meidän olis parempi palvella Egyptiläisiä, kuin kuolla korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Moses sanoi kansalle: älkäät peljätkö, seisokaat ja katsokaat minkä autuuden Herra tänäpänä tekee teille; sillä näitä Egyptiläisiä, jotka te tänäpänä näette, ei teidän pidä ikänänsä enempi näkemän ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Herra sotii teidän puolestanne, ja teidän pitää alallanne oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Ja Herra sanoi Mosekselle: mitäs huudat minun tyköni? Sano Israelin lapsille, että he vaeltaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Mutta nosta sinä sauvas, ja ojenna kätes meren ylitse, ja eroita se yhdestä, että Israelin lapset kävisivät keskeltä merta kuivaa myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ja katso, minä paadutan Egyptiläisten sydämet, ja he seuraavat teidän jälissänne; niin minä voitan kunnian Pharaosta ja kaikesta hänen sotajoukostansa, hänen vaunuistansa ja ratsasmiehistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Ja Egyptiläisten pitää tietämän, että minä olen Herra, koska minä olen kunnian voittanut Pharaosta, ja hänen vaunuistansa ja ratsasmiehistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Niin Jumalan enkeli nousi, joka Israelin joukon edellä kävi, ja meni heidän takansa: ja pilven patsas siirsi itsensä heidän kasvoinsa edestä, ja seisoi heidän takanansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Ja tuli Egyptiläisten ja Israelin joukkoin vaiheelle, ja oli pimiä pilvi, ja valaisi (näille) yön: niin ettei he koko yönä toinen toistansa taitaneet lähestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Koska Moses ojensi kätensä meren ylitse, antoi Herra vedet juosta pois vahvalla itätuulella koko sen yön; ja teki meren kuiville, ja vedet erkanivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Ja Israelin lapset kävivät keskeltä merta kuivaa myöten, ja vedet olivat heille niinkuin muuri heidän oikialla ja vasemmalla puolellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Ja Egyptiläiset ajoivat heitä takaa ja seurasivat heidän perässänsä, ja kaikki Pharaon hevoset, hänen vaununsa ja ratsasmiehensä keskelle merta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Koska aamuvartio tuli, katsahti Herra Egyptiläisten joukon päälle tulen patsaasta ja pilvestä hukuttaaksensa Egyptiläisten joukon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Ja hän syöksi pyörät erinänsä heidän vaunuistansa, niin että he työläästi vetivät niitä. Niin sanoivat Egyptiläiset: paetkaamme Israelia, sillä Herra sotii heidän puolestansa Egyptiläisiä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Mutta Herra sanoi Mosekselle: ojenna kätes meren ylitse, että vedet juoksisivat Egyptiläisten ylitse, heidän vaunuinsa ja ratsasmiestensä ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Niin ojensi Moses kätensä meren ylitse, ja meri palasi ennen huomenta voimaansa. Ja koska Egyptiläiset pakenivat, kohtasi heitä vesi, ja Herra syöksi heidät keskelle merta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Ja vedet palasivat ja kävivät vaunuin, ja ratsasmiesten, ja koko Pharaon sotajoukon ylitse, jotka heitä olivat seuranneet mereen: niin ettei yksikään heistä päässyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Mutta Israelin lapset kävivät kuivaa myöten keskeltä merta, ja vedet olivat heille niinkuin muuri heidän oikialla ja vasemmalla puolellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Ja niin Herra vapahti Israelin sinä päivänä Egyptiläisten kädestä: ja Israel näki Egyptiläiset kuolleina meren reunalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Ja Israel näki myös sen suuren voiman, jonka Herra oli osottanut Egyptiläisten päälle. Ja kansa pelkäsi Herraa, ja he uskoivat Herran ja hänen palveliansa Moseksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Silloin veisasi Moses ja Israelin lapset Herralle tämän virren, ja sanoivat: Minä veisaan Herralle, sillä hän on sangen jalon työn tehnyt, hevosen ja miehen hän mereen syöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Herra on minun väkevyyteni ja kiitosvirteni, ja on minun autuuteni. Hän on minun Jumalani, ja minä rakennan hänelle majan, hän on minun Isäni Jumala, ja minä ylistän häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Herra on äsken sotamies: Herra on hänen nimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Pharaon vaunut ja hänen sotaväkensä syöksi hän mereen. Hänen valitut päämiehensä ovat upotetut Punaiseen mereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Syvyys on heitä peittänyt, ja vajosivat pohjaan, niinkuin kivi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Herra, sinun oikia kätes osotti hänensä voimalliseksi väkevyydessä: Herra, sinun oikia kätes on lyönyt vihollisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Ja sinun suurella kunniallas olet sinä sinun vihollises kukistanut, sillä koska sinä lähetit hirmuisuutes, kulutti se heidät niinkuin korren.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Ja sinun vihas puhalluksen kautta kokoontuivat vedet; ja virrat seisoivat niinkuin roukkioissa, syvyydet niinkuin hyytyivät keskelle merta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Vihollinen sanoi: minä ajan takaa ja saavutan heitä, ja saalista jaan, ja heihin minun mieleni jäähdytän: minä vedän ulos miekkani, ja minun käteni pitää heitä hukuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Silloin sinun tuules puhalsi, ja meri peitti heidät, ja he pohjaan vajosivat, niinkuin lyijy, väkevissä vesissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Herra, kuka on sinun vertas jumalten seassa? Kuka on sinun kaltaises, joka olet niin korkia ja pyhä, hirmullinen, kiitettävä ja ihmetten tekiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Koskas oikian kätes ojensit, niin maa heidät nieli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Sinä olet johdattanut laupiudessas tämän kansan, jonkas pelastit, ja olet vienyt heidän väkevyydessäs sinun pyhään asumisees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Koska kansat sen kuulevat, vapisevat he: ahdistus käsittää Philistealaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Silloin hämmästyvät Edomin ruhtinaat, ja vapistus tarttuu Moabin sankareihin: kaikki kanaanin maan asuvaiset raukeavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Tulkoon hämmästys heidän päällensä, ja pelko sinun väkevän käsivartes kautta, he vaijetkoon niinkuin kivi, siihenasti että sinun kansas, Herra, lävitse käy, jonka sinä saanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Johdata heitä ja istuta heitä sinun perimises vuorelle, jonka sinä Herra asumisekses tehnyt olet: sinun pyhyytes tykö, Herra, jonka sinun kätes vahvistaneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Herra hallitsee alati ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Sillä Pharaon hevoset menivät mereen, vaunuinensa ja ratsasmiehinensä, ja Herra palautti meren vedet heidän päällensä. Mutta Israelin lapset kävivät kuivaa myöten keskeltä merta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Ja MirJam prophetissa, Aaronin sisar, otti kanteleen käteensä, ja kaikki vaimot seurasivat häntä kanteleilla ja hypyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Ja MirJam vastasi heitä: Veisatkaat Herralle: sillä hän on sangen jalon työn tehnyt, hevosen ja miehen hän mereen syöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Niin Moses antoi Israelin lasten vaeltaa Punaisen meren tyköä, ja he menivät Suurin korpeen: ja matkustivat kolme päivää korvessa, ja ei löytäneet vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Niin he tulivat Maraan, vaan eivät saaneet juoda sitä vettä Marassa, sillä se oli ylen karvas; josta se paikka kutsutaan Mara.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Siinä napisi kansa Mosesta vastaan, sanoen: mitä me juomme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Mutta hän huusi Herran tykö, ja Herra osotti hänelle puun, jonka hän heitti veteen, ja vedet tulivat makiaksi. Siinä pani hän heidän eteensä käskyn ja oikeuden, ja kiusasi siinä heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Ja sanoi: jos sinä kuulet sinun Herras Jumalas äänen, ja teet mikä oikeus on hänen edessänsä, ja panet hänen käskynsä sinun korviis, ja pidät kaikki hänen säätynsä: niin en minä pane sinun päälles yhtäkään vitsausta niistä, jotka minä Egyptiläisten päälle pannut olen; sillä minä olen Herra sinun parantajas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Ja he tulivat Elimiin, siellä on kaksitoistakymmentä lähdettä, ja seitsemänkymmentä palmupuuta: siellä he sioittivat itsensä vetten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Niin he matkustivat Elimistä, ja koko Israelin lasten joukko tuli Sinnin korpeen, joka on Elimin ja Sinain välillä: viidentenätoistakymmenentenä päivänä toisella kuulla sittenkuin he Egyptin maalta lähteneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Ja koko Israelin lasten joukko napisi Mosesta ja Aaronia vastaan korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Ja Israelin lapset sanoivat heille: joska me olisimme Egyptin maalla Herran käden kautta kuolleet, koska me istuimme lihapatain tykönä, ja oli leipää yltäkyllä syödä; sillä te olette sentähden meidän johdattaneet tähän korpeen kuolettaaksenne näljällä kaikkea tätä joukkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Niin sanoi Herra Mosekselle: katso, minä annan sataa teille leipää taivaasta: ja kansan pitää menemän ulos ja kokooman joka päivä niin paljo kuin he tarvitsevat, koetellakseni heitä, jos he vaeltavat minun käskyssäni elikkä ei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Ja pitää tapahtuman, että he kuudentena päivänä valmistavat sen kuin he tuovat (kotia) ja kaksikertaisesti sen suhteen, minkä he muutoin joka päivä kokoovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Moses ja Aaron sanoivat kaikille Israelin lapsille: ehtoona pitää teidän tietämän Herran johdattaneen teidät Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Ja huomenna pitää teidän näkemän Herran kunnian; sillä hän on kuullut teidän napistuksenne Herraa vastaan. Ja mitkä me olemme, että te napisette meitä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Vielä sanoi Moses: Herra antaa teille ehtoona lihaa syödäksenne, ja huomenna leipää teidän ravinnoksenne, että Herra on kuullut teidän napistuksenne, jolla te olette napisseet häntä vastaan. Sillä mitkä me olemme? Teidän napistuksenne ei ole meitä, vaan Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Ja Moses sanoi Aaronille: sano koko Israelin lasten joukolle: tulkaat Herran eteen, sillä hän on kuullut teidän napistuksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Ja tapahtui, kun Aaron näitä puhunut oli kaikelle Israelin lasten joukolle, käänsivät he itsensä korpeen päin, ja katso, Herran kunnia näkyi pilvessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Minä olen kuullut Israelin lasten napistuksen, puhu heille sanoen: kahden ehtoon välillä pitää teillä oleman lihaa syödäksenne, ja aamulla pitää teidän ravituksi tuleman leivästä: ja teidän pitää tietämän, että minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Ja tapahtui ehtoona, että peltokanat tulivat ja peittivät leirin, ja aamulla oli kaste leirin ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Ja kuin kaste nousi, katso, niin oli korvessa jotakin ymmyrjäistä ja pientä, niin kuin härmää maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Ja kuin Israelin lapset sen näkivät, sanoivat he toinen toisellensa: Man tämä on; sillä he ei tietäneet mitä se oli. Mutta Moses sanoi heille: tämä on se leipä, jonka Herra teille on antanut syödäksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Tämä on se, josta Herra käskenyt on. Jokainen kootkaan sitä niin paljo kuin hän itse syö, ja ottakaan gomor joka pääluvulle, henkiluvun jälkeen joka on hänen majassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Ja Israelin lapset tekivät niin, ja kokosivat muutamat enemmän ja muutamat vähemmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Ja kuin he mittasivat sen gomorilla, niin ei sillä mitään liiaksi ollut, joka paljo koonnut oli, eikä siltä mitään puuttunut, joka vähemmän kokosi, mutta jokainen oli koonnut niin paljo kuin he syödäksensä tarvitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Ja Moses sanoi heille: ei kenenkään pidä siitä huomeneksi mitään jättämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mutta ei he kuulleet Mosesta, monikahdat jättivät siitä jotakin huomeneksi. Niin madot kasvoivat siihen, ja tuli haisemaan. Ja Moses vihastui heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Niin he kokosivat siitä joka aamu, niin paljon kuin jokainen syödäksensä tarvitsi. Mutta koska päivä tuli palavaksi, niin se suli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Ja tapahtui kuudentena päivänä, että he kokosivat kaksikertaisesti sitä leipää, kaksi gomoria kullekin. Ja kaikki päämiehet kansan seasta tulivat ja ilmoittivat sen Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Ja hän sanoi heille: tämä on se minkä Herra sanonut on: huomenna on sabbati, pyhä lepo Herralle: mitä te leivotte, se leipokaat, ja mitä te keitätte, se keittäkäät; mutta mitä liiaksi on, jättäkäät se tähteelle pantaa huomeneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Ja he jättivät sitä huomeneksi, niinkuin Moses käskenyt oli: ja ei tullut se haisemaan, eikä matoa tullut siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Niin sanoi Moses: syökäät se tänäpänä, sillä tätäpänä on Herran sabbati: tänäpänä ette sitä löydä kedolta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Kuusi päivää pitää teidän kokooman; mutta seitsemäntenä päivänä on sabbati, ja ei löydetä sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Ja tapahtui, että seitsemäntenä päivänä läksivät muutamat kansan seasta kokoomaan, ja ei he löytäneet mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Niin Herra sanoi Mosekselle: kuinka kauvan ette tahdo pitää minun käskyjäni ja lakiani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Katsokaat, Herra on teille antanut sabbatin, ja sen tähden on hän antanut teille kuudentena päivänä kahden päivän leivän: niin olkaan siis jokainen kotonansa, ja älkään yksikään lähtekö siastansa seitsemäntenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Niin lepäsi kansa seitsemäntenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Ja Israelin huone kutsui hänen nimensä man: ja se oli niinkuin korianderin siemen, valkia, ja maisti niinkuin sämpylä hunajan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Ja Moses sanoi: tämä on se minkä Herra käskenyt on: täytä gomor siitä, kätkettää teidän jälkeentulevaisillenne: että he näkisivät sen leivän, jolla minä olen teitä ruokkinut korvessa, koska minä johdatin teitä ulos Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Ja Moses sanoi Aaronille: ota astia, ja pane siihen gomorin täysi mannaa: ja pane se Herran eteen, tallella pidettää teidän jälkeen tulevaisillenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Niinkuin Herra käskenyt oli Mosekselle, niin Aaron pani sen todistuksen eteen tallella pidettäväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Ja Israelin lapset söivät mannaa neljäkymmentä ajastaikaa, siihenasti kuin he tulivat sille maalle jossa heidän asuman piti: siihenasti kuin he tulivat Kanaanin maan rajoille, söivät he mannaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Ja gomor on kymmenes osa ephaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Ja koko Israelin lasten joukko matkusti Sinnin korvesta, vaelluksissansa Herran käskyn jälkeen, ja sioittivat itsensä Raphidimiin, ja ei ollut vettä kansalle juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Ja kansa riiteli Moseksen kanssa, ja sanoi: antakaat meille vettä juodaksemme. Moses sanoi heille: mitä te riitelette minun kanssani? Miksi kiusaatte Herraa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Ja kansa janosi juoda siellä vettä, ja he napisivat Mosesta vastaan, ja sanoivat: mitä vasten sinä olet meidät johdattanut Egyptistä tänne kuolettaakses minua ja minun lapsiani, ja minun eläimiäni janolla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Niin Moses huusi Herran tykö, sanoen: mitä minä teen tälle kansalle? Vähä puuttuu, ettei he kivitä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Ja Herra sanoi Mosekselle: mene kansan edellä, ja ota kanssas muutamia Israelin vanhimmista, ja sinun sauvas, jolla sinä löit virtaa, ota sinun kätees ja mene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Katso, minä seison siellä sinun edessäs kalliolla Horebissa: ja sinun pitää lyömän kalliota, ja siinä pitää vedet juokseman, niin että kansa siitä juoda saa. Ja Moses teki niin Israelin vanhimpain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Ja kutsui sen paikan nimen Massa ja Meriba, Israelin lasten riidan tähden, ja että he kiusasivat Herraa, sanoen: olleeko Herra meidän seassamme elikkä ei?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Niin Amalek tuli: ja soti Israelia vastaan Raphidimissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Ja Moses sanoi Josualle: valitse meille miehiä, mene ja sodi Amalekia vastaan: huomenna minä seison mäen kukkulalla, ja pidän Jumalan sauvan kädessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Ja Josua teki niinkuin Moses sanoi hänelle, ja soti Amalekia vastaan. Mutta Moses, Aaron ja Hur astuivat mäen kukkulalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Ja tapahtui, että koska Moses piti kätensä ylhäällä, voitti Israel; mutta koska hän kätensä laski alas, voitti Amalek.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Mutta Moseksen kädet olivat raskaat, sentähden ottivat he kiven ja asettivat hänen alansa ja hän istui sen päällä; vaan Aaron ja Hur pitivät ylhäällä hänen käsiinsä kumpikin puoleltansa, niin pysyi hänen kätensä juuri vahvana auringon laskemaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Ja Josua heikonsi Amalekin ja hänen kansansa miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Ja Herra sanoi Mosekselle: kirjoita tämä muistoksi kirjaan, ja muistuta Josuan korvissa; sillä minä pyyhin kokonansa pois Amalekin muiston taivaan alta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Ja Moses rakensi alttarin, ja kutsui sen nimen: Herra on minun lippuni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Ja hän sanoi: koska käsi oli Herran istuinta päin, oli Herralla sota Amalekia vastaan: (niin se on tästäkin lähin) suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Ja Jetro Midianin pappi, Moseksen appi kuuli kaikki, mitä Jumala Mosekselle ja Israelin kansalle oli tehnyt: että Herra oli johdattanut Israelin pois Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Ja Jetro Moseksen appi otti Ziporan Moseksen emännän, jonka hän oli takaperin lähettänyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Ja kaksi hänen poikaansa, joista yhden nimi oli Gersom, sillä hän sanoi: minä olin muukalainen vieraalla maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Ja toisen nimi oli Elieser, sillä (hän sanoi) minun isäni Jumala on ollut minun apuni, ja on pelastanut minun Pharaon miekasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Niin Jetro Moseksen appi, ja hänen poikansa, ja hänen emäntänsä tulivat Moseksen tykö siihen korpeen, kussa hän itsensä sioittanut oli Jumalan vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Ja antoi sanoa Mosekselle: minä Jetro sinun appes olen tullut sinun tykös, ja sinun emäntäs, ja molemmat hänen poikansa hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Niin meni Moses appeansa vastaan, kumarsi itsensä, ja suuta antoi hänen; ja koska he olivat tervehtineet toinen toistansa, menivät he majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Niin jutteli Moses apellensa kaikki, mitä Herra tehnyt oli Pharaolle, ja Egyptiläisille Israelin tähden, ja kaiken sen vaivan joka heillä tiellä oli ollut, ja että Herra oli auttanut heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Ja Jetro riemuitsi kaiken sen hyvyyden ylitse, jonka Herra oli tehnyt Israelille, että hän oli pelastanut heitä Egyptiläisten kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Ja Jetro sanoi: kiitetty olkoon Herra, joka teidät pelastanut on Egyptiläisten ja Pharaon kädestä: joka on vapahtanut kansansa Egyptiläisten käden alta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nyt minä tiedän, että Herra on suurempi kuin kaikki Jumalat; sillä siinä asiassa, jossa ylpeilivät, oli hän heidän ylitsensä (valtias).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Ja Jetro Moseksen appi otti polttouhria ja muuta uhria Jumalalle. Niin tuli Aaron ja kaikki vanhimmat Israelista syömään leipää Moseksen apen kanssa Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Ja tapahtui toisena päivänä, että Moses istui oikeutta tekemään kansalle; ja kansa seisoi Moseksen ympärillä aamusta niin ehtooseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Koska Moseksen appi näki kaikki, mitä hän teki kansalle, sanoi hän: mikä tämä on kuin sinä teet kansalle? Miksis sinä istut yksinäs, ja kaikki kansa seisoo sinun edessäs, hamasta aamusta niin ehtooseen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Moses vastasi appeansa: sillä kansa tulee minun tyköni, ja kysyy Jumalalta neuvoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Koska heillä on jotakin asiaa, tulevat he minun tyköni, että minun pitää oikeutta tekemän jokaisen välillä ja hänen lähimmäisensä välillä, ja osottaman heille Jumalan oikeudet ja käskyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Ja Moseksen appi sanoi hänelle: ei se ole hyvä kuin sinä teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Sinä väsytät peräti sekä itses että tämän kansan joka sinun kanssas on; sillä tämä asia on sinulle ylen raskas, et taida sinä sitä yksinäs toimittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Nyt kuule minun ääneni, minä neuvon sinua, ja Jumala on sinun kanssas. Ole sinä kansan puolesta Jumalan edessä, ja tuota heidän asiansa Jumalan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Ja muistuta heille oikeudet ja käskyt: osota heille tie, jota heidän vaeltaman pitää, ja ne työt mitkä heidän tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Niin etsi sinä kaiken kansan seasta vaat miehet, Jumalaa pelkääväiset, totuuden miehet, ne jotka ahneutta vihaavat: ja aseta ne heille päämiehiksi, tuhanten päälle, sadan päälle, viidenkymmenen päälle, ja kymmenen päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Että ne aina kansalle oikeuden tekisivät: mutta kuin joku raskas asia tulee, että he sen tuovat sinun eteesi mutta kaikki pienet asiat he itse ratkaiskaan: niin huojenna jotakin itseltäs, ja he kantavat kuormaa sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Jos sinä sen teet, ja Jumala sen sinulle käskee, niin sinä taidat voimassa pysyä, niin myös kaikki tämä kansa saa mennä kotiansa rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Ja Moses kuuli appensa äänen, ja teki kaikki mitä hän sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Ja valitsi vaat miehet kaikesta Israelista, ja asetti heidät kansan päämiehiksi, tuhanten päälle, sadan päälle, viidenkymmenen päälle, ja kymmenen päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Jotka tekivät kansalle oikeuden joka aika. Mutta jotka raskaat asiat olivat, lykkäsivät he Moseksen alle; vaan kaikki pienet asiat he itse ratkasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Niin Moses antoi appensa mennä ja hän meni omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Kolmantena kuukautena Israelin lasten lähtemisestä Egyptin maalta, tulivat he sinä päivänä Sinain korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Sillä he olivat lähteneet Raphidimista, ja tulivat Sinain korpeen, ja sioittivat itsensä korpeen: ja Israel sioitti itsensä siihen, vuoren kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Ja Moses astui ylös Jumalan tykö. Ja Herra huusi häntä vuorelta, ja sanoi: näin sinun pitää sanoman Jakobin huoneelle, ja Israelin lapsille ilmoittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Te olette nähneet, mitä minä Egyptiläisille tehnyt olen: ja kuinka minä olen teitä kantanut kotkan siivillä, ja olen saattanut teidät minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Jos te siis minun ääneni ahkerasti kuulette, ja pidätte minun liittoni, niin teidän pitää oleman minulle kallis omaisuus kaikista kansoista, vaikka muutoin koko maa on minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Ja teidän pitää oleman minulle papillinen valtakunta ja pyhä kansa. Nämä ovat ne sanat, jotka sinun pitää Israelin lapsille, sanoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Niin Moses tuli ja kutsui kokoon vanhimmat kansan seasta, ja jutteli heille kaikki sanat, jotka Herra hänen käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Ja kaikki kansa vastasi yhtä haavaa, ja sanoi: kaikki mitä Herra puhunut on, me tahdomme tehdä. Ja Moses sanoi jällensä kansan sanat Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Niin Herra sanoi Mosekselle: katso, minä tulen sinun tykös paksussa pilvessä, että kansa kuulee minun puhuvan sinun kanssas, ja uskoo sinua ijankaikkisesti. Ja Moses ilmoitti Herralle kansan puheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Ja Herra sanoi Mosekselle: mene kansan tykö, ja pyhitä heitä tänäpänä ja huomenna: että he vaatteensa pesisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Ja olisivat kolmantena päivänä valmiit; sillä kolmantena päivänä Herra on astuva alas kaiken kansan eteen Sinain vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Ja sinun pitää paneman rajan kansan ympärille, sanoen: karttakaat teitänne, ettette vuorelle astu taikka tartu sen rajaan: joka siihen vuoreen sattuu, sen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ei yksikään käsi pidä häneen rupeeman, vaan hän pitää täydellisesti kivitettämän, eli kohdastansa ammuttaman lävitse, joko se eläin taikka ihminen olis, ei pidä sen elämän. Koska ääni rupee pitkään kajahtamaan, silloin he vuorelle astukaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Moses astui vuorelta kansan tykö, ja pyhitti heitä: ja he pesivät vaatteensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Ja hän sanoi heille: olkaat kolmanteen päivään valmiit, ja älkäät lähestykö vaimoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Kuin kolmas päivä tuli, ja aamu oli, niin tuli pitkäisen jylinä ja leimaus, ja paksu pilvi vuoren päälle, ja sangen väkevä basunan ääni: niin kaikki kansa, jotka leirissä olivat, pelvosta vapisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Ja Moses johdatti kansan leiristä Jumalaa vastaan, ja he seisahtivat vuoren alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Mutta koko Sinain vuori suitsi, siitä että Herra astui alas sen päälle tulessa, ja sen savu kävi ylös niinkuin pätsin savu, niin että koko vuori sangen kovaan vapisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Ja sen basunan helinä enemmin ja enemmin eneni. Moses puhui ja Jumala vastasi häntä kuultavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Kuin nyt Herra oli tullut alas Sinain vuoren kukkulalle, niin Herra kutsui Moseksen vuoren kukkulalle. Ja Moses astui sinne ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Niin sanoi Herra hänelle: astu alas ja varoita kansaa, ettei he kävisi rajan ylitse Herran tykö, häntä näkemään, ja monta heistä lankeaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Niin myös papit, jotka Herraa lähestyvät, pitää heitänsä pyhittämän, ettei Herra heitä hukuttaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Ja Moses sanoi Herralle: eipä kansa saa astua ylös Sinain vuorelle; sillä sinä olet meille todistanut ja sanonut: pane rajat vuoren ympärille, ja pyhitä se.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Ja Herra sanoi hänelle: mene ja astu alas, ja astu ylös (jällensä) sinä ja Aaron sinun kanssas; mutta papit ja kansa älkään lähestykö astumaan ylös Herran tykö, ettei hän heitä hukuttaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Ja Moses astui alas kansan tykö ja sanoi nämät heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Ja Jumala puhui kaikki nämät sanat, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '(1) Minä (olen) Herra sinun Jumalas; joka sinun Egyptin maalta orjuuden huoneesta ulos vienyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Ei sinun pidä muita jumalia pitämän minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Ei sinun pidä tekemän sinulles kuvaa eikä jonkun muotoa, niiden jotka ylhäällä taivaassa ovat, eli niiden, jotka alhaalla ovat maan päällä, eikä niiden, jotka vesissä maan alla ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Ei sinun pidä kumartaman niitä, eikä myös palveleman niitä: Sillä minä, Herra sinun Jumalas, olen kiivas Jumala, joka etsiskelen isäin pahat teot lasten päälle, kolmanteen ja neljänteen polveen, jotka minua vihaavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Ja teen laupiuden monelle tuhannelle, jotka minua rakastavat, ja pitävät minun käskyni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, '(2) Ei sinun pidä turhaan lausuman sinun Herras Jumalas nimeä; sillä ei Herra pidä sitä rankaisemata, joka hänen nimensä turhaan lausuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, '(3) Muista sabbatin päivää, ettäs sen pyhittäisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Kuusi päivää pitää sinun työtä tekemän ja kaikki askarees toimittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Mutta seitsemäntenä päivänä on Herra sinun Jumalas sabbati: silloin ei sinun pidä yhtään työtä tekemän, eikä sinun, eikä sinun poikas, eikä sinun tyttäres, eikä sinun palvelias, eikä sinun piikas, eikä sinun juhtas, eikä sinun muukalaises, joka sinun portissas on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Sillä kuutena päivänä on Herra, taivaan ja maan ja meren tehnyt, ja kaikki mitä niissä ovat, ja lepäsi seitsemäntenä päivänä. Sentähden siunasi Herra sabbatin päivän, ja pyhitti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, '(4) Sinun pitää kunnioittaman isääs ja äitiäs, ettäs kauvan eläisit maan päällä, jonka Herra sinun Jumalas antaa sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, '(5) Ei sinun pidä tappaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, '(6) Ei sinun pidä huorin tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, '(7) Ei sinun pidä varastaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, '(8) Ei sinun pidä väärää todistusta sanoman sinun lähimmäistäs vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, '(9) Ei sinun pidä pyytämän sinun lähimmäises huonetta. (10) Ei sinun pidä himoitseman sinun lähimmäises emäntää, eikä hänen palveliaansa, eikä piikaansa, eikä hänen härkäänsä, eikä mitään mikä sinun lähimmäises on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Ja kaikki kansa näki pitkäisen jylinän, ja tulen leimaukset, ja basunan helinän, ja vuoren suitsevan: ja koska he sen näkivät, niin he pakenivat ja seisahtuivat taamma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Niin he sanoivat Mosekselle: puhu sinä meidän kanssamme, ja me kuulemme: ja älkään Jumala meidän kanssamme puhuko, ettemme kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Ja Moses sanoi kansalle: älkäät peljätkö; sillä Jumala on tullut teitä koettelemaan, ja että hänen pelkonsa olis teidän edessänne, ettette syntiä tekisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Ja kansa seisahtui taamma; mutta Moses meni sen pimeyden tykö, jossa Jumala oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Ja Herra sanoi Mosekselle: niin sinun pitää Israelin lapsille sanoman: te olette nähneet, että minä olen taivaasta teidän kanssanne puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ei teidän pidä tekemän epäjumalia minun sivuuni: hopiaisia jumalia, ja kultaisia jumalia ei teidän pidä teillenne tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Tee alttari maasta minulle, jonka päälle sinun pitää polttouhris ja kiitosuhris, sinun lampaas ja karjas uhraaman: mihinkä paikkaan ikänänsä minä säädän minun nimeni muiston, sinne minä tulen sinun tykös, ja siunaan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Ja jos sinä teet minulle kivisen alttarin, niin älä tee sitä vuoltuista kivistä: jos sinä siihen veitses satutat, niin sinä sen saastutat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Ei myös sinun pidä astumilla minun alttarilleni astuman, ettei sinun häpiäs sen päällä paljastettaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Nämät ovat ne oikeudet, jotka sinun pitää paneman heidän eteensä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Jos sinä ostat Hebrealaisen orjan, hänen pitää sinua palveleman kuusi vuotta; vaan seitsemäntenä pitää hänen lähtemän vapaana lunastamatta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Jos hän naimatoinna on ollut, naimatoinna pitää hänen myös lähtemän; vaan jos hän nainunna tuli, lähtekään emäntinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Jos hänen isäntänsä antoi hänelle emännän, jos se on synnyttänyt hänelle poikia tai tyttäriä, niin hänen emäntänsä ja lapsensa pitää oleman hänen isäntänsä omat, vaan itse hänen pitää lähtemän yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Mutta jos orja julkisesti sanoo: minä rakastan minun isäntääni, vaimoani ja lapsiani: en tahdo tulla minä vapaaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Niin hänen isäntänsä viekään hänen tuomarien tykö, ja seisauttakaan hänet oveen, taikka pihtipieleen, ja lävistäkään isäntä hänen korvansa naskalilla, ja olkaan ijäti hänen orjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Jos joku myy tyttärensä orjaksi, ei hänen pidä lähtemän niinkuin orjat lähtevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Jollei hän kelpaa isännällensä, joka ei tahdo häntä kihlata, niin hänen pitää antaman hänen lunastettaa; mutta muukalaiselle kansalle ei pidä oleman hänelle voimaa häntä myydä, tehden petollisesti hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Mutta jos hän sen kihlaa pojallensa, niin antakaan hänen nautita tytärten oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Jos hän pojallensa ottaa toisen, niin ei hänen pidä kieltämän häneltä hänen ravintoansa, vaatteitansa, ja asunto-oikeuttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Jollei hän tee hänelle näitä kolmea, niin sen pitää vapaana lähtemän lunastamatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Joka lyö ihmisen niin että hän kuolee, hänen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Vaan jollei hän ole häntä väijynyt, mutta Jumala on antanut hänen langeta hänen käsiinsä, niin minä määrään sinulle paikan, johonka hänen pakeneman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Mutta jos joku ylpeydestä tappaa lähimmäisensä kavaluudella; sen sinun pitää ottaman minun alttariltanikin pois, kuolettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Joka lyö isäänsä taikka äitiänsä, sen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Joka varastaa ihmisen ja myy hänen, eli löydetään hänen tykönänsä, sen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Ja joka kiroilee isäänsä ja äitiänsä, sen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Koska miehet keskenänsä riitelevät, ja toinen lyö toistansa kivellä eli rusikalla, ja hän ei kuole vaan makaa vuoteessansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Jos hän paranee, niin että hän käy ulos sauvansa nojalla, niin sen pitää syyttömän oleman joka löi: ainoastaan maksakaan hänen työnsä vahingon, josta hän on estetyksi tullut, ja hänen pitää kaiketi hänen terveeksi laittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Kun joku lyö palveliaansa eli palkkapiikaansa sauvalla, niin että hän kuolee hänen käsiinsä: hän pitää kaiketi kostettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Vaan jos hän päivän taikka kaksi elää, ei pidä häntä kostettaman, sillä se on hänen rahansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Jos miehet tappelevat keskenänsä, ja loukkaavat raskaan vaimon, niin että hänen täytyy hedelmänsä kesken synnyttää; ja ei kuoleman vahinko tapahdu: niin hän pitää rahalla rangaistaman, sen jälkeen kuin vaimon mies häneltä anoo, ja se pitää annettaman arviomiesten ehdosta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mutta jos kuoleman vahinko tulee, niin pitää hänen antaman hengen hengestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Silmän silmästä, hampaan hampaasta, käden kädestä, jalan jalasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Polton poltosta, haavan haavasta, sinimarjan sinimarjasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Joka lyö palveliansa eli palkkapiikansa silmän, ja turmeles sen, hänen pitää päästämän sen vapaaksi silmän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Niin myös jos hän lyö palvelialtansa taikka palkkapiialtansa hampaan suusta, niin pitää hänen päästämän sen vapaaksi hampaan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Jos härkä kuokaisee miehen eli vaimon, niin että hän kuolee: se härkä pitää kaiketi kivitettämän, ja ei pidä hänen lihaansa syötämän; ja niin on härjän isäntä viatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Mutta jos härkä ennen oli harjaantunut kuokkimaan, ja sen isännälle oli todistusten kanssa ilmoitettu, ja ei hän korjannut häntä; jos hän sitte tappaa miehen eli vaimon, niin pitää härkä kivitettämän, ja hänen isäntänsä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Mutta jos hän rahalla pääsee, niin pitää hänen antaman henkensä lunastukseksi niin paljo kuin määrätään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Jos hän pojan eli tyttären kuokaisee, niin pitää yhdellä tavalla hänen kanssansa tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Jos joku härkä kuokaisee palvelian eli palkkapiian, niin pitää hänen antaman heidän isännällensä kolmekymmentä hopiasikliä, ja härkä pitää kivitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Jos joku avaa kuopan, taikka kaivaa kuopan, jos ei hän sitä peitä, ja härkä eli aasi siihen putoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Niin pitää sen kuopan isäntä maksaman rahalla sen isännälle; mutta sen kuolleen pitää hänen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Jos jonkun härkä kuokkii toisen miehen härjän, että se kuolee, niin pitää heidän myymän sen elävän härjän, ja jakaman rahan, niin myös sen kuolleen härjän pitää heidän jakaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Elikkä jos se oli tiettävä, että härkä on ennen tottunut kuokkimaan, ja hänen isäntänsä ei korjannut häntä, niin hänen pitää antaman härjän härjästä, ja se kuollut pitää hänen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Jos joku varastaa härjän taikka lampaan ja teurastaa eli myy sen; hänen pitää antaman viisi härkää yhdestä härjästä, ja neljä lammasta yhdestä lampaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Jos varas käsitetään, koska hän itsensä sisälle kangottaa, ja hän lyödään kuoliaaksi, niin ei pidä tappajan vereen vikapään oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Vaan jos aurinko on noussut hänen ylitsensä, niin pitää tappajan kuolemaan vikapään oleman: kaiketi pitää hänen jällensä maksaman; jollei hänellä ole varaa, niin myytäkään hän varkautensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Jos varkaan kappale löydetään täydellisesti hänen tyköänsä, härkä, aasi, eli lammas; niin pitää hänen jällensä kaksikertaisesti maksaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Jos joku syöttää toisen pellon eli viinamäen, niin että hän päästää sisälle karjansa, ja syöttää toisen pellossa, hänen pitää siitä parhaasta, kuin hänen omassa pellossansa eli viinamäessänsä löydetään maksaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Jos valkia vallallensa pääsee, ja orjantappuroihin syttyy, niin että kykäät eli laiho, eli pelto poltetaan, niin sen pitää maksaman, kuin valkian päästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Jos joku antaa lähimmäisellensä rahaa, eli muuta kalua kätköön, ja se varastetaan hänen huoneestansa: jos se varas löydetään, niin hänen pitää sen kaksikertaisesti maksaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Ja jos ei varas löydetä, niin pitää huoneen isäntä tuotaman tuomarien eteen vannotettaa, jos ei hän ole käsiänsä satuttanut lähimmäisensä kaluun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Kaiken väärän asian tähden härjästä eli aasista, taikka lampaasta, eli vaatteesta ja kaiken sen tähden kuin pois tullut on, josta joku sanoo: tämä se on, niin pitää heidän molempain asiansa tuleman tuomarien eteen; jonka tuomarit vikapääksi löytävät, sen pitää lähimmäisellensä kaksikertaisesti maksaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Jos joku antaa lähimmäisellensä aasin, eli härjän, eli lampaan, taikka mikä eläin se olis, tähteelle, ja se kuolee, taikka saa muutoin vamman, taikka ajetaan pois, ettei yksikään sitä näe:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Niin pitää valan heidän molempain välillänsä käymän Herran kautta, ettei hän ole satuttanut kättänsä lähimmäisensä kaluun; ja sen jonka kalu oma oli, pitää siihen tyytymän, ja toisen ei pidä sitä maksaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Jos varas sen varastaa häneltä, niin pitää hänen sen maksaman sen isännälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Mutta jos se raadeltu on, niin pitää hänen todistajat tuoman, ja ei mitään jälleen antaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Jos joku ottaa lainaksi lähimmäiseltänsä, ja se tulee rivinomaksi eli kuolee, niin ettei sen isäntä ole läsnä, niin hänen pitää sen kokonansa maksaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Mutta jos sen isäntä on siihen tykönä, niin ei hänen pidä sitä maksaman; jos se palkalla oli, niin saakoon palkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Jos joku viettelee neitseen, joka ei vielä ole kihlattu, ja makaa hänen, sen pitää kaiketi hänelle antaman huomenlahjan, ja ottaman hänen emännäksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Jos hänen isänsä ei tahdo häntä antaa hänelle, niin hänen pitää antaman rahaa, niin paljo kuin neitseen huomenlahja on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Velhonaista ei sinun pidä salliman elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Joka järjettömäin luontokappalten kanssa yhteyntyy, sen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Se joka uhraa jumalille, ja ei ainoalle Herralle, hänen pitää kirottu oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Muukalaisia ei sinun pidä ahdistaman, eikä myös polkuna pitämän: sillä te olette myös olleet muukalaisna Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Ei teidän pidä yhtään leskeä eli orpolasta murheelliseksi saattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Koska sinä jonkun heistä murheelliseksi saatat: jos hän hartaasti huutaa minun tyköni, niin minä tahdon totisesti kuulla hänen huutonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Ja minun vihani julmistuu, niin että minä tapan heidät miekalla; ja teidän emäntänne pitää tuleman leskiksi, ja teidän lapsenne orvoiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Koska sinä lainaat minun kansalleni rahaa, köyhälle kuin sinun tykönäs on, ei sinun pidä oleman häntä vastaan niinkuin kasvon ottaja, eli korkoa hänen päällensä paneman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Koska sinä lähimmäiseltäs vaatteet otat pantiksi, niin sinun pitää antaman sen hänelle jällensä, ennen kuin aurinko laskee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Sillä se on hänen ainoa verhonsa, ja vaate hänen ihollansa: missästä hän makais? Ja tapahtuu, että hän huutaa minun tyköni, niin minä kuulen häntä; sillä minä olen laupias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Tuomareita ei sinun pidä kiroileman, ja ylimmäistä sinun kansassas ei sinun pidä sadatteleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Sinun uutistas ja pisarias ei sinun pidä viivyttelemän. Esikoisen sinun pojistas pitää sinun antaman minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Niin pitää myös sinun tekemän härkäis ja lammastes kanssa. Seitsemän päivää anna heidän olla emäinsä tykönä, kahdeksantena päivänä pitää sinun sen antaman minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Teidän pitää oleman pyhä kansa minulle. Sentähden ei teidän pidä syömän lihaa, joka metsän pedoilta raadeltu on, mutta heittämän sen koirille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Ei sinun pidä uskoman valheita; ettäs auttaisit jumalatointa, ja tulisit vääräksi todistajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Ei sinun pidä joukkoa seuraaman pahuuteen, eikä myös vastaaman oikeuden edessä niin että sinä poikkeat joukon jälkeen pois oikeutta vääntämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Ei sinun pidä kaunisteleman köyhää, hänen asiassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Koska sinä kohtaat vihollises härjän eli aasin eksyksissä niin sinun pitää johdattaman sen hänelle jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Koskas näet vihollises aasin makaavan kuorman alla, kavahda, ettes häntä jättäisi; vaan sinun pitää kaiketi auttaman häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Ei sinun pidä kääntelemän sinun köyhäs oikeutta hänen asiassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Ja ole kaukana vääristä asioista. Viatointa ja hurskasta ei sinun pidä tappaman; sillä en minä pidä jumalatointa hurskaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Ei sinun pidä lahjoja ottaman; sillä lahjat sokaisevat näkeväiset, ja kääntävät hurskasten asiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Ei teidän pidä solvaiseman muukalaisia; sillä te tiedätte muukalaisen sydämen, että te myös itse olette olleet muukalaiset Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Kuusi vuotta pitää sinun kylvämän sinun maas, ja kokooman sen tulon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Vaan seitsemäntenä vuonna pitää sinun sen levolle jättämän, että köyhät sinun kansastas siitä syödä saisivat. Ja mitä jää, sen metsän pedot syökään. Niin pitää myös sinun tekemän viinamäkes ja öljymäkes kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Kuusi päivää pitää sinun työtäs tekemän, mutta seitsemäntenä päivänä pitää sinun lepäämän: että sinun härkäs ja aasis saisivat levätä, ja sinun piikas poika ja muukalainen sais itsensä virvottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Kaikki ne mitkä minä olen teille sanonut, pitää teidän pitämän. Ja vierasten jumalain nimeä ei pidä teidän muistaman, ja sinun suustas ei pidä ne kuuluman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Kolmasti vuodessa pitää sinun minulle juhlaa pitämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Happamattoman leivän juhlan pitää sinun pitämän, niin että sinä seitsemän päivää syöt happamatointa leipää, niinkuin minä sinulle käskenyt olen, määrättynä aikana sillä kuulla Abib. Sillä että sillä ajalla olet sinä lähtenyt Egyptistä; mutta älä tule tyhjin käsin minun eteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Ja sen juhlan, koskas ensin rupeet pellolta korjaamaan, mitäs siihen kylvänyt olet. Ja korjaamisen juhlan, vuoden lopussa, koska sinä työs kedolta korjannut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Kolmasti vuodessa pitää kaikki sinun miesväkes tuleman Herran Jumalan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Ei sinun pidä uhraaman minun uhrini verta happaman taikinan kanssa; ja minun juhlani lihavuus ei pidä ylitse yön jäämän huomeneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Uutista ensimäisestä sinun maas hedelmästä pitää sinun tuoman sinun Herras Jumalas huoneesen. Ei sinun pidä keittämän vohlaa emänsä rieskassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Katso, minä lähetän enkelin sinun edelles varjelemaan sinua tiellä, ja johdattamaan sinun siihen paikkaan, jonka minä olen valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Pidä vaari itsestäs hänen kasvoinsa edessä ja kuule hänen äänensä, älä hänen mieltänsä pahoita; sillä ei hän jätä rankaisemata teidän ylitsekäymistänne: sillä minun nimeni on hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Vaan jos sinä ahkerasti kuulet hänen äänensä, ja teet kaikki mitä minä sinulle käsken, niin minä olen sinun vihollistes vihollinen, ja sinun vainoojais vainooja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Sillä minun enkelini käy sinun edelläs, ja johdattaa sinun Amorilaisten, Hetiläisten, Pheresiläisten, Kanaanealaisten, Heviläisten, ja Jebusilaisten tykö, ja minä hävitän heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Niin ei sinun pidä kumartaman heidän jumaliansa, eikä myös heitä palveleman, eikä heidän tekoinsa jälkeen tekemän; mutta sinun pitää heidän epäjumalansa heittämän pois, ja lyömän heidän kuvansa rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Mutta Herraa teidän Jumalaanne pitää teidän palveleman, niin hän siunaa sinun leipäs ja sinun vetes: ja minä otan sinulta pois kaikki sairaudet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Ei yksikään kesken synnyttäväinen eikä hedelmätöin pidä oleman sinun maassas; ja minä tahdon täyttää sinun päiväs luvun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Minä lähetän minun pelkoni sinun edelles, ja hukutan kaiken kansan, jonka tykö sinä menet: ja saatan kaikki sinun vihollises pakoon sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Minä lähetän hörhöläiset sinun edelles, jotka pitää ajaman pois sinun edestäs Heviläiset, Kanaanealaiset ja Hetiläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'En minä heitä aja ulos yhtenä vuonna sinun edestäs, ettei maa autiaksi tulisi, eikä metsän pedot enenisi sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Vähittäin minä heitä ajan ulos sinun edestäs, siihenasti ettäs kasvat ja omistat maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Ja minä panen sinun maas rajat Punaisesta merestä niin Philistealaisten mereen asti, ja korvesta niin virtaan asti: sillä minä annan maan asuvaiset sinun kätees, ajaakses heitä ulos edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Ei sinun pidä liittoa tekemän heidän kanssansa, eikä heidän jumalainsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Ei heidän pidä asuman sinun maassas, ettei he kehoittaisi sinua syntiä tekemään minua vastaan, niin ettäs palvelet heidän jumaliansa, sillä se on sinulle paulaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Ja hän sanoi Mosekselle: astu Herran tykö, sinä ja Aaron, Nadab ja Abihu, ja seitsemänkymmentä vanhinta Israelista: ja kumartakaat itsenne taampana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mutta Moses lähestyköön yksinänsä Herran tykö, ja älkööt muut lähestykö: älköön myös kansa astuko ylös hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Ja Moses tuli ja jutteli kansalle kaikki Herran sanat, ja oikeudet. Niin vastasi kaikki kansa yhdellä äänellä, ja sanoi: kaikki ne sanat, mitkä Herra puhunut on, tahdomme me tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Niin kirjoitti Moses kaikki Herran sanat, ja nousi varhain aamulla, ja rakensi alttarin vuoren palttaan, kahdentoistakymmenen patsaan kanssa, kahdentoistakymmenen Israelin sukukunnan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Ja lähetti sinne nuoria miehiä Israelin lapsista, jotka uhrasivat polttouhria, ja kiitosuhria Herralle, mulleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Ja Moses otti puolen verestä ja pani maljoihin; mutta toisen puolen verestä priiskotti hän alttarille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Ja otti liitonkirjan, ja luki sen kansan korvain kuullen, ja he sanoivat: kaikki mitä Herra puhunut on tahdomme me tehdä ja olla hänelle kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Niin Moses otti veren ja priiskotti kansan päälle, ja sanoi: katso, tämä on liiton veri, jonka Herra teki teidän kanssanne kaikkein näiden sanain päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Niin astui Moses ja Aaron, Nadab ja Abihu ylös, ja seitsemänkymmentä Israelin vanhinta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Ja näkivät Israelin Jumalan: hänen jalkainsa alla oli niinkuin teko saphirin kivestä, ja kuin itse taivas, koska seijes on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Eikä ojentanut kättänsä Israelin lasten päämiesten tykö: ja kuin he olivat nähneet Jumalan, niin he söivät ja joivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Ja Herra sanoi Mosekselle: astu ylös minun tyköni vuorelle, ja ole siellä: ja minä annan sinulle kiviset taulut, ja lain, ja käskyt, jotka minä kirjoittanut olen, jotka sinun pitää heille opettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Silloin nousi Moses ja hänen palveliansa Josua: ja Moses astui ylös Jumalan vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Ja sanoi vanhimmille: olkaat tässä siihen asti, kuin me palajamme teidän tykönne: katso, Aaron ja Hur ovat teidän tykönänne: jolla joku asia on, se tulkaan heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Koska Moses tuli vuorelle, niin pilvi peitti vuoren,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Ja Herran kunnia asui Sinain vuorella, ja pilvi peitti sen kuusi päivää: ja hän kutsui Moseksen pilven keskeltä seitsemäntenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Ja Herran kunnia oli nähdä niinkuin kuluttavainen tuli, vuoren kukkulalla, Israelin lasten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Ja Moses meni keskelle pilveä, ja astui ylös vuorelle: ja Moses oli vuorella neljäkymmentä päivää ja neljäkymmentä yötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Puhu Israelin lapsille, että he tuovat minulle ylennysuhrin: joka mieheltä, jonka sydän hyvästä tahdosta sen antaa, pitää teidän minun ylennysuhrini ottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Ja tämä on ylennysuhri, jonka teidän pitää ottaman heiltä: kultaa ja hopiaa ja vaskea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Sinisiä villoja, purpuraa, ja tulipunaisia villoja, niin myös kallista liinaa ja vuohen karvoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Punaisia oinaan nahkoja, tekasjim-nahkoja, ja sittimipuita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Öljyä lamppuihin, yrttejä voide-öljyksi, ja hyvän hajullisia kaluja savuttamiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Onikinkiviä, ja sisälle sovitettuja kiviä päällisvaatteeseen ja kilpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Ja heidän pitää tekemän minulle pyhän, että minä asuisin heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Kaiken sen jälkeen kuin minä osotan sinulle Tabernaklin muodon, ja kaikkein sen astiain muodon: niin pitää teidän sen tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Tehkäät arkki sittimipuusta, jonka pituus pitää oleman puolikolmatta kyynärää, ja leveys puolitoista kyynärää, ja korkeus puolitoista kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Ja sinun pitää sen silaaman puhtaalla kullalla, sisältä ja ulkoa pitää sinun sen silaaman; ja sinun pitää tekemän kultaisen vanteen sen ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Ja pitää myös valaman neljä kultaista rengasta, jotka sinun pitää paneman neljään kulmaan, niin että kaksi rengasta ovat hänen yhdellä puolellansa, ja toiset kaksi rengasta toisella puolellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Ja sinun pitää tekemän korennot sittimipuusta, ja silaaman ne kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Ja pitää pistämän korennot renkaisiin, arkin sivulle; että niillä arkki kannettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Sen arkin renkaissa pitää oleman korennot; ja ei pidä niistä vedettämän ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Ja sinun pitää paneman arkkiin sen todistuksen, jonka minä sinulle annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Sinun pitää myös tekemän armoistuimen, puhtaasta kullasta, puolikolmatta kyynärää pitkän, ja puolitoista kyynärää leviän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Ja sinun pitää tekemän kaksi Kerubimiä kullasta: valetusta kullasta pitää sinun ne tekemän, molempiin päihin armo-istuinta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Ja tee yksi Kerubimi tähän päähän ja toinen toiseen päähän: molempiin päihin armoistuinta pitää teidän Kerubimit tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Ja ne Kerubimit pitää hajottaman siipensä sen ylitse, niin että he peittävät armo-istuimen siivillänsä, ja heidän kasvonsa pitää oleman toinen toisensa puoleen: ja Kerubimin kasvot pitää oleman armo-istuinta päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Ja sinun pitää asettaman armo-istuimen arkin päälle, ja paneman arkkiin sen todistuksen, jonka minä sinulle annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Ja siinä minä sinulle olen saapuvilla, ja puhuttelen sinua armo-istuimelta, kahden Kerubimin väliltä, jotka ovat todistuksen arkin päällä, kaikista mitä minä sinun käsken sanoa Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Ja sinun pitää tekemän pöydän sittimipuusta: kaksi kyynärää pitää oleman hänen pituutensa, ja kyynärä hänen leveytensä, ja puolitoista kyynärää hänen korkeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Ja sinun pitää silaaman sen puhtaalla kullalla, ja tekemän ympärinsä sen päälle kultaisen vanteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Ja sinun pitää tekemän vanteen sen ympäri kämmentä korkian, ja tekemän kultaisen palteen vanteen ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Ja sinun pitää siihen tekemän neljä kultaista rengasta, ja paneman renkaat neljään kulmaan, jotka ovat neljän jalan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Juuri vanteen kohdalla pitää ne renkaat oleman, että niihin taidettaisiin pistää korennot, joilla pöytä kannettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Ja sinun pitää tekemän ne korennot sittimipuusta ja silaaman kullalla: ja pöytä niillä kannettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Ja sinun pitää siihen myös tekemän sen vadit, ja lusikat, ja maljat ja pikarit, joilla ulos ja sisälle kaadetaan: puhtaasta kullasta pitää sinun ne tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Ja sinun pitää paneman aina pöydälle minun eteeni katumusleivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Sinun pitää myös tekemän kynttiläjalan puhtaasta kullasta: valetusta kullasta pitää se kynttiläjalka tehtämän, jonka varsi haarainsa, maljainsa, nuppeinsa ja kukkaistensa kanssa pitää siitä samasta oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Kuusi haaraa pitää käymän ulos hänen kyljistänsä: kolme kynttiläjalan haaraa hänen yhdestä kyljestänsä, ja kolme kynttiläjalan haaraa hänen toisesta kyljestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Ja pitää oleman kolme maljaa niinkuin mandelpähkinät, yhdessä haarassa, niin myös nuppi ja kukkainen, ja kolme mandelpähkinän muotoista maljaa toisessa haarassa, ja nuppi ja kukkainen: niin pitää oleman niissä kuudessa haarassa, jotka kynttiläjalasta ulos käyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Mutta kynttiläjalassa pitää oleman neljä maljaa mandelin muotoista, ja siihen nupit ja kukkaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Nimittäin yksi nuppi kahden haaran alla, ja taas yksi nuppi toisen haaran alla, ja vielä yksi nuppi kahden (jälkimäisen) haaran alla: niissä kuudessa haarassa, jotka kynttiläjalasta ulos käyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Niiden nupit ja niiden haarat pitää siitä oleman: ja kaikki tyyni pitää oleman valetusta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Ja sinun pitää tekemän seitsemän lamppua sen päälle, jotka lamput pitää sytytettämän, niin että ne valistaisivat toinen toisensa kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Ja kynttilän niistimet ja sammutuskalut puhtaasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Yhdestä leiviskästä puhdasta kultaa pitää sinun sen tekemän, kaikkein näiden astiain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Niin katso, ja tee sen muodon jälkeen, kuin sinä näit vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Ja Tabernaklin pitää sinun tekemän kymmenestä vaatteesta: kalliista kerratuista liinalangoista, sinisistä, purpuraisista, ja tulipunaisista villoista. Gerubimin sinun pitää tekemän taitavasti sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Kunkin vaatten pituus pitää oleman kahdeksan kyynärää kolmattakymmentä, ja leveys pitää oleman neljä kyynärää: ja niillä kaikilla vaatteilla pitää yksi mitta oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Viisi vaatetta pitää yhdistettämän toinen toiseensa, ja taas viisi yhdistettämän toinen toiseensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Sinun pitää myös tekemän silmukset sinisistä villoista ensimäisen vaatteen reunaan, äärimäiset kulmat yhteen sidottaa: ja niin sinun pitää tekemän äärimäisen vaatteen reunaan, sen kulmat yhteenpantaa toistamiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Sinun pitää tekemän viisikymmentä silmusta ensimäiseen vaatteesen, niin myös viisikymmentä silmusta äärelle vaatetta, joka toisessa yhdistyksessä on; ja silmukset pitää oleman toinen toisensa kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Ja sinun pitää tekemän viisikymmentä kultaista koukkua, ja ne vaatteet yhdistämän toinen toiseensa niillä koukuilla, niin että se tulis yhdeksi Tabernakliksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Ja sinun pitää tekemän yksitoistakymmentä vaatetta vuohen karvoista, peitteeksi Tabernaklin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Jokaisen vaatteen pituuden pitää oleman kolmekymmentä kyynärää, ja leveyden neljä kyynärää, ja leveyden neljä kyynärää. Ja kaikki yksitoistakymmentä pitää oleman yhdensuuruiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Viisi vaatetta pitää sinun toinen toiseensa yhdistämän erinänsä, ja myös kuusi vaatetta erinänsä; niin ettäs teet sen kuudennen vaatteen kaksikertaiseksi etiseltä puolen Tabernaklia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Ja sinun pitää tekemän viisikymmentä silmusta ensimäisen vaatteen reunaan, äärelle, josta se yhdistetään ja myös viisikymmentä silmusta siihen vaatteen reunaan, josta se toinen kerta yhdistetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Niin myös pitää sinun tekemän viisikymmentä vaskikoukkua, ja paneman koukut silmuksiin ja yhdistämän majan, että se olis yksi maja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Vaan se liika joka ylitse jää Tabernaklin vaatteesta: nimittäin puolen siitä liiaksi jääneestä vaatteesta, pitää sinun antaman riippua ylitse Tabernaklin, perän puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Ja yksi kyynärä pitää oleman yhdellä ja yksi kyynärä toisella puolen, sen ylitse jääneen majan vaatteen pituudesta: sen pitää riippuman Tabernaklin sivuilla siellä ja täällä, sitä peittämässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Mutta tämän ensimäisen peitteen päälle sinun pitää tekemän toisen peitteen punaisista oinaan nahoista, ja vielä sitten ylimmäisen peitteen tekasjim-nahoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Sinun pitää myös tekemän Tabernaklin laudat sittimipuusta, pystyällä olemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Jokaisen laudan pituus pitää oleman kymmenen kyynärää, vaan leveys puolitoista kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Kaksi vaarnaa pitää jokaisessa laudassa oleman, niin että he taittaisiin yhdistettää toinen toiseensa. Näin pitää sinun tekemän kaikki Tabernaklin laudat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Ja sinun pitää tekemän Tabernaklin laudat, niin että kaksikymmentä lautaa pitää oleman etelän puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Ja neljäkymmentä hopiajalkaa pitää sinun tekemän kahdenkymmenen laudan alle, niin että jokaisen laudan alla pitää oleman kaksi jalkaa, kahden vaarnansa päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Niin myös majan toisella sivulla pohjan puolella pitää oleman kaksikymmentä lautaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Ja neljäkymmentä hopiajalkaa: aina kaksi jalkaa kunkin laudan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Mutta perällä Tabernaklia länteen päin pitää sinun tekemän kuusi lautaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Ja kaksi lautaa pitää sinun tekemän Tabernaklin perälle, niihin kahteen kulmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Niin että kumpikin niistä taittaisiin yhdistettää silmuksella sekä alhaalta että ylhäältä: yhdellä tavalla pitää he molemmista kulmista yhdistettämän kulmakiskoilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Niin että yhteen olis kahdeksan lautaa, ja heidän hopiajalkansa kuusitoistakymmentä: aina kaksi jalkaa kunkin laudan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Sinun pitää myös tekemän korennot sittimipuusta: viisi niihin lautoihin, jotka yhdellä Tabernaklin sivulla ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Ja viisi korentoa niihin lautoihin, kuin toisella Tabernaklin sivulla ovat: ja viisi korentoa myös niihin lautoihin, jotka perällä Tabernaklia ovat, länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Ja keskimäinen korento pitää keskeltä lautoja käymän yhdestä kulmasta niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Ja sinun pitää laudat kullalla silaaman, ja kullasta renkaat niihin tekemän, joihinka korennot pistetään, ja sinun pitää myös korennot kullalla silaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Ja niin pitää sinun Tabernaklin pystyälle paneman, sen muodon jälkeen, kuin sinä näit vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Esiripun pitää myös sinun tekemän sinisistä, purpuraisista ja tulipunaisista villoista, niin myös kalliista kerratuista liinalangoista, ja tekemään Kerubimit sen päälle taitavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Ja sinun pitää ripustaman sen neljän sittimipuisen, kullalla silatun patsaan päälle, ja niiden kultaiset koukut, neljän hopiajalan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Ja sinun pitää ripustaman esiripun koukuille, ja paneman todistusarkin sisälliselle puolen esirippua, niin että esirippu olis teille erotus pyhän ja kaikkein pyhimmän vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Armo-istuimen pitää sinun myös paneman todistusarkin päälle, kaikkein pyhimpään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Ja paneman pöydän ulkoiselle puolen esirippua, ja kynttiläjalan pöydän kohdalle, päivän puolelle Tabernaklia, niin että pöytä seisoo pohjaan päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Ja sinun pitää tekemän peittovaatteen Tabernaklin oveen, sinisistä, purpuraisista ja tulipunaisista villoista, niin myös kalliista kerratusta liinalangasta, taitavasti ommellun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Tätä peittovaatetta varten pitää sinun tekemän viisi patsasta sittimipuusta ja ne kullalla silaaman, ja koukut pitää oleman kullasta: ja sinun pitää valaman niille viisi vaskista jalkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Ja sinun pitää tekemän myös alttarin sittimipuusta: viisi kyynärää pitää oleman pituuden, ja viisi kyynärää leveyden: neljäkulmaisen pitää sen alttarin oleman, ja kolme kyynärää hänen korkeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Sarvet sinun pitää myös tekemän hänen neljään kulmaansa: siitä pitää hänen sarvensa oleman; ja sinun pitää sen vaskella silaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Tee myös hänen patansa, joihin tuhka korjataan, ja lapionsa, ja maljansa, ja tadikkonsa ja hiilikattilansa: kaikki hänen kalunsa pitää sinun vaskesta tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Ja sinun pitää myös tekemän hänelle häkin, niinkuin verkon vaskesta, ja tekemän sen verkon päälle neljä vaskirengasta hänen neljään kulmaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Sinun pitää sen paneman alhaalta alttarin ympäri, niin että se häkki ulottuu keskelle alttaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Ja sinun pitää tekemän sittimipuiset korennot alttarille, ja silaaman ne vaskella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Ja pitää pistämän korennot renkaisiin, niin että korennot ovat kahden puolen alttaria, joilla se kannettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Ja laudoista pitää sinun sen tekemän, niin että se on tyhjä sisältä: niinkuin sinulle osoitettiin vuorella, niin se tehtämän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Sinun pitää myös tekemän Tabernaklin pihan meren puolelle; ja pihan vaatteet pitää oleman kalliista kerratusta liinasta, sata kyynärää pitää oleman yhden sivun pituus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Ja hänen patsaitansa pitää oleman kaksikymmentä, kahdenkymmenen vaskijalan päällä, ja patsasten koukut ja heidän vyönsä hopiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Niin myös pohjan puoleen, pituudelle pitää oleman esivaatteet sata kyynärää pitkät, ja kaksikymmentä sen patsasta kahdenkymmenen vaskijalan päällä, patsasten koukut vöinensä hopiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Mutta pihan laveudelle lännen puoleen pitää oleman vaatteet, viisikymmentä kyynärää pitkät, ja kymmenen patsasta kymmenen jalan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Ja itään päin, pihan laveuden pitää oleman viisikymmentä kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Niin että vaatteella yhdellä puolella on viisitoistakymmentä kyynärää: ja kolme patsasta kolmen jalan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Ja viisitoistakymmentä kyynärää toisella puolella, siihen myös kolme patsasta kolmen jalan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Mutta pihan läpikäytävässä pitää oleman yksi vaate kaksikymmentä kyynärää leviä, sinisistä, purpuraisista ja tulipunaisista villoista, ja kalliista liinalangasta taitavasti ommellun: siihen myös neljä patsasta ja neljän jalan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Kaikilla patsailla ympärinsä pihan pitää oleman hopiavanteet, hopiakoukut, ja vaskiset jalat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Ja pihan pituus pitää oleman sata kyynärää, ja leveys kaikelta kohtaa viisikymmentä, ja korkeus viisi kyynärää, kalliista kerratusta liinasta: ja heidän jalkansa vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Kaikki Tabernaklin astiat, jotka kaikkinaiseen palvelukseen tarvitaan, kaikki hänen vaarnansa ja kaikki pihan vaarnat pitää oleman vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Ja käske Israelin lapsille, että he toisivat sinulle kaikkein selkiämpää öljypuun öljyä puserrettua, valkeudeksi: että lamppu aina palais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Seurakunnan majassa ulkoisella puolella esirippua, joka on todistuksen edessä, pitää Aaron poikinensa sen toimittaman, (valistamaan) ehtoosta niin aamuun asti, Herran edessä. Se pitää teille oleman ijankaikkinen sääty heidän sukukunnissansa, Israelin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Ja sinun pitää ottaman tykös sinun veljes Aaronin poikinensa Israelin lasten seasta, että hän olis minun pappini: Aaron ja hänen poikansa Nadab, Abihu, Eleatsar ja Itamar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Ja sinun pitää tekemän veljelles Aaronille pyhät vaatteet, kunniaksi ja kaunistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Ja sinun pitää myös puhuman kaikkein niiden kanssa, joilla taitava sydän on, jotka minä taidon hengellä täyttänyt olen, että he tekevät vaatteita Aaronille hänen pyhittämiseksensä, että hän olis minun pappini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Ja nämät ovat vaatteet, jotka heidän tekemän pitää: kilpi, päällisvaate, hame, ahdashame, hiippa ja vyö. Ja näin pitää heidän tekemän sinun veljelles Aaronille ja hänen pojillensa pyhät vaatteet, että hän minun pappini olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Siihen pitää heidän ottaman kultaa, sinisiä, purpuraisia ja tulipunaisia villoja, ja kallista liinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Päällisvaatteen pitää heidän tekemän kullasta, ja sinisistä, purpuraisista ja tulipunaisista villoista, ja kalliisti kerratusta liinasta, taitavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Että se yhdistettäisiin molempain olkain päältä ja sidottaisiin yhteen molemmilta puolilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Ja hänen päällisvaatteensa vyö, kuin sen päällä on, pitää oleman yhdellä tavalla tehty, kullasta, sinivilloista, purpurasta ja tulipunaisista villoista, ja kalliista kerratusta liinalangasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Ja sinun pitää ottaman kaksi onikin kiveä, ja kaivaman niihin Israelin poikain nimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Heidän kuusi nimeänsä yhteen kiveen, ja toiset kuusi nimeä toiseen kiveen, sen jälkeen kuin he syntyneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Niinkuin kivenvuolia sinetin kaivaa, pitää sinun taitavasti kaivaman niihin kahteen kiveen Israelin lasten nimet, ja ne kultaan sisälle sulkeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Ja sinun pitää ne molemmat kivet paneman hartioille päällisvaatteeseen, että ne ovat muistokivet Israelin lapsille: ja Aaronin pitää kantaman heidän nimensä Herran edessä molemmilla olillansa muistoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Ja sinun pitää tekemän kultaiset nastat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Ja kahdet vitjat puhtaasta kullasta, joilla päät ovat, pitää sinun tekemän, taitavasti väätyt: ne väätyt vitjat pitää sinun yhdistämän nastoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Virankilven pitää sinun myös tekemän taitavasti, niinkuin päällisvaatteenkin pitää sinun sen tekemän: kullasta, sinisistä ja purpuraisista, ja tulipunaisista villoista, ja kerratusta kalliin liinan langasta sinun sen tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Neljäkulmaisen pitää sen oleman ja kaksinkertaisen, kämmenen leveys hänen pituutensa, ja kämmenen leveytensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Ja sinun pitää täyttämän sen täyttymys kivillä, neljällä kivirivillä. Ensimäinen rivi pitää oleman sardius, topats, smaragdi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Toinen rivi: rubiin, saphiir, demanti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Kolmas rivi: linkurius, akat ja ametisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Neljäs rivi: turkos, oniks ja jaspis: kultaan pitää ne istutettaman kaikilta riveiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Ja ne kivet pitää oleman kahdentoistakymmenen Israelin lasten nimen jälkeen, kaivetut kivenvuolialta jokainen nimeltänsä, kahdentoistakymmenen sukukunnan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Ja sinun pitää tekemän vitjat kilpeen, yhden pituiset, taitavasti väätyt, puhtaasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Ja sinun pitää tekemän kilpeen kaksi kultarengasta, ja paneman ne molemmat renkaat kahteen kilven kulmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Ja pistämään ne kaksi kultavitjaa kahteen renkaaseen kilven kulmiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Mutta ne kaksi päätä niistä kahdesta vitjasta pitää sinun antaman tulla kahteen nastaan, ja paneman päällisvaatteeseen hartioille, toinen toisensa kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Ja sinun pitää tekemän kaksi kultaista rengasta, ja paneman ne molempiin kilven kulmiin: sen reunaan sisälliselle puolelle päällisvaatetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Ja sinun pitää tekemän kaksi kultarengasta, ja paneman ne päällisvaatteen molemmille olkapäille toinen toisensa kohdalle, alaspäin, sen saumaa vasten, vaatteen vyön päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Ja rintavaate pitää yhdistettämän renkaillansa sinisellä siteellä päällisvaatteen renkaisiin, niin että se olis päällisvaatetta liki, ettei rintavaate eriäis päällisvaatteesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Ja niin pitää Aaronin kantaman Israelin lasten nimet virankilvessä sydämensä päällä, koska hän pyhään sisälle menee, muistoksi Herran edessä alinomaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Ja sinun pitää paneman virankilpeen valkeudet ja täydellisyydet, jotka pitää oleman Aaronin sydämen päällä, koska hän menee Herran eteen. Ja niin pitää Aaronin kantaman Israelin lasten oikeuden sydämensä päällä aina Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Sinun pitää myös tekemän päällisvaatteen alle hameen, kaiken sinisistä villoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Ja ylinnä siinä pitää keskellä oleman pään läpi, ja sepalus sen läven ympärillä, pallistettu yhteen niinkuin pantsarin läpi, ettei se kehkiäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Ja alhaalle hänen liepeisiinsä pitää sinun tekemän niinkuin granatin omenat sinisistä, purpuraisista ja tulipunaisista villoista ympärinsä: ja niiden keskelle kultaiset kulkuiset ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Niin että siinä on kultainen kulkuinen, ja sitälikin granatin omena: ja taas kultainen kulkuinen granatin omenan kanssa, ympärinsä hameen liepeitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Ja Aaron pitää sen päällensä pitämän, koska hän palveluksen tekee, niin että siitä kuullaan kulina, koska hän menee pyhään, Herran eteen, ja hän käy ulos, ettei hän kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Sinun pitää myös tekemän otsalehden puhtaasta kullasta, ja kaivaman siihen, niinkuin sinetti kaivetaan, HERRAN PYHYYS.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Ja sinun pitää sen sitoman sinisellä langalla, niin että se on hiipan päällä: etisellä puolella hiippaa sen pitää oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Ja sen pitää oleman Aaronin otsalla, niin että Aaron kantaa pyhäin vääryyden, kuin Israelin lapset pyhittivät, kaikissa heidän pyhyytensä lahjoissa. Ja se pitää alinomati oleman hänen otsassansa, heille mielisuosioksi Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Sinun pitää myös tekemän ahtaan hameen kalliista liinasta, ja hiipan kalliista liinasta: ja taitavasti ommellun vyön pitää myös tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Ja Aaronin pojille pitää sinun tekemän hameita, vöitä ja hiippoja, kunniaksi ja kaunistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Ja sinun pitää ne puettaman veljes Aaronin ja hänen poikainsa ylle, ja pitää voiteleman heitä, ja täyttämän heidän kätensä, ja pyhittämän heitä, että he olisivat minun pappini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Ja pitää tekemän heille liinaiset alusvaatteet, peittääksensä häpylihansa: kupeista niin reisiin asti pitää ne oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Ja Aaron poikinensa pitää ne yllänsä pitämän, koska he menevät seurakunnan majaan, eli koska he lähestyvät alttaria palvelusta tekemään pyhässä, ettei heille kostettaisi heidän vääryyttänsä, ja he kuolisi. Se pitää oleman hänelle ja hänen siemenellensä hänen jälkeensä ijankaikkinen sääty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Ja tämä on se kuin sinun pitää tekemän heille, pyhittääkses heitä, että he olisivat minun pappini: ota yksi nuori mulli, ja kaksi virheetöintä oinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Ja happamattomia leipiä ja happamattomia kyrsiä sekoitettuja öljyllä, ja happamattomia ohuita kyrsiä voidelluita öljyllä: nisuisista jauhoista pitää sinun ne tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Ja sinun pitää paneman ne koriin, ja korissa ne kantaman edes, niin myös mullin ja ne kaksi oinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Ja sinun pitää tuoman Aaronin poikinensa seurakunnan majan oven eteen, ja pesemän heitä vedellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Ja sinun pitää ottaman vaatteet ja puettaman Aaronin ylle, ahtaan hameen, ja päällisvaate-hameen, ja vyöttämän hänen päällisvaatteen vyöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Sinun pitää myös paneman hiipan hänen päähänsä, ja laskeman pyhän kruunun hiipan päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Ja ottaman voidellusöljyn, ja vuodattaman hänen päänsä päälle, ja voiteleman häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Ja hänen poikainsa anna tulla edes, ja pueta heidän yllensä ahtaat hameet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Ja sinun pitää vyöttämän heidän vyöllä, sekä Aaronin että hänen poikansa, ja paneman hiipat heidän päähänsä, että heillä olis pappeus ijankaikkiseksi säädyksi: ja sinun pitää täyttämän Aaronin käden ja hänen poikainsa käden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Ja sinun pitää tuoman mullin seurakunnan majan eteen: ja Aaronin poikinensa pitää paneman kätensä mullin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Niin sinun pitää teurastaman mullin Herran edessä, seurakunnan majan oven tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Ja sinun pitää ottaman mullin verestä, ja sivuman sormellas alttarin sarviin; mutta kaikki sen muu veri vuodata alttarin pohjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Ja sinun pitää ottaman kaiken lihavuuden kuin sisällykset peittää, ja maksan kalvon, ja molemmat munaskuut, ja lihavuuden, joka on niiden päällä, ja polttaman alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Mutta mullin lihan ja hänen vuotansa ja rapansa pitää sinun polttaman tulella ulkona leiristä; sillä se on rikosuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Yhden oinaan pitää sinun myös ottaman: ja Aaronin poikinensa pitää paneman kätensä sen oinaan pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Ja sinun pitää teurastaman oinaan, ja ottaman hänen verensä, ja priiskottaman alttarille ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Mutta oinaan pitää sinun leikkaaman kappaleiksi, ja pesemän hänen sisällyksensä ja jalkansa, ja paneman sen hänen kappaltensa ja päänsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Ja polttaman koko oinaan alttarilla; sillä se on polttouhri Herralle: makia haju ja tuli Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Toisen oinaan pitää sinun myös ottaman, ja Aaron poikinensa pitää paneman kätensä oinaan pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Ja sinun pitää teurastaman oinaan ja ottaman hänen verestänsä, ja sivuman Aaronin ja hänen poikainsa oikian korvan lehteen, ja oikian käden peukaloon, ja heidän oikian jalkansa isoon varpaaseen: ja priiskottaman veren alttarille ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Ja sinun pitää ottaman verestä, kuin alttarilla on, ja voidellusöljystä, ja priiskottaman Aaronin ja hänen vaatettensa päälle, ja hänen poikainsa ja heidän vaatettensa päälle: niin hän tulee pyhäksi itse vaatteinensa, ja hänen poikansa vaatteinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Sitte pitää sinun ottaman oinaasta lihavuuden, ja saparon, ja sen lihavuuden kuin sisällykset peittää, ja maksan kalvon, ja molemmat munaskuut, niin myös sen lihavuuden kuin niiden päällä on, ja oikian lavan; sillä se on täyttämisen oinas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Ja yhden kyrsän leipää, ja yhden öljykyrsän, ja ohuen kyrsän korista, jossa happamattomat leivät ovat Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Ja sinun pitää paneman kaikki nämät Aaronin ja hänen poikainsa kätten päälle, ja häälyttämän ne häälytykseksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Ja niin pitää sinun ne ottaman heidän käsistänsä, ja polttaman alttarilla polttouhriksi ja makiaksi hajuksi Herralle; sillä se on Herran tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Ja sinun pitää ottaman rinnan Aaronin täyttämisen oinaasta, ja pitää sen häälyttämän häälytysuhriksi Herran eteen: ja se pitää oleman sinun osas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Ja sinun pitää pyhittämän häälytysrinnan ja ylennyslavan, joka häälytetty on ja ylennetty on, Aaronin ja hänen poikainsa täyttämisen oinaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Ja sen pitää oleman Aaronille ja hänen pojillensa ijankaikkiseksi säädyksi Israelin lapsilta; sillä se on ylennysuhri: ja ylennysuhrin pitää oleman Herran oman Israelin lapsilta, heidän kiitosuhrissansa ja ylennysuhrissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Mutta Aaronin pyhät vaatteet pitää oleman hänen pojillansa hänen jälkeensä, että heidät pitää niissä voideltaman, ja heidän kätensä täytettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Joka hänen pojistansa tulee papiksi hänen siaansa, sen pitää pukeman ne yllensä seitsemän päivää; jonka pitää käymän seurakunnan majaan palvelemaan pyhässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Sinun pitää myös ottaman täyttämisen oinaan, ja keittämän sen lihan pyhässä siassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Ja Aaronin poikinensa pitää syömän sen oinaan lihan, ja leivän, joka on korissa, seurakunnan majan oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Ja niiden pitää ne syömän, jotka niiden kautta sovitetut ovat, täytettää heidän käsiänsä, ja pyhitettää heitä. Ei muukalaisen pidä sitä syömän; sillä se on pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Jos jotakin tähteeksi jää täyttymisen lihasta ja leivästä aamuun asti, sen pitää sinun polttaman tulessa: ei sitä pidä syötämän, sillä se on pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Ja näin pitää sinun tekemän Aaronille ja hänen pojillensa, kaiken sen jälkeen kuin minä sinulle käskenyt olen: seitsemän päivää pitää sinun heidän kätensä täyttämän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Ja joka päivä teurastaman mullin rikosuhrin sovinnoksi. Ja sinun pitää puhdistaman alttarin, koskas sovintoa uhraat sen päällä, ja voiteleman sen, ettäs sen pyhittäisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Ja seitsemän päivää pitää sinun puhdistaman alttarin, ja pyhittämän sen; ja se alttari pitää oleman kaikkein pyhin. Mitä ikänänsä siihen alttariin tarttuu, se on pyhitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Ja tämä on se kuin sinun pitää tekemän alttarilla: kaksi vuosikuntaista karitsaa pitää sinun uhraaman joka päivä sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Yhden karitsan aamulla, ja toisen karitsan pitää sinun uhraaman kahden ehtoon välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Ja kymmenennen osan jauhoja, sekoitettu neljännekseen hinniä puserretun öljyn kanssa; ja neljänneksen hinniä viinaa juomauhriksi, yhdelle karitsalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Ja toisen karitsan pitää sinun uhraaman kahden ehtoon välillä: niinkuin aamullisenkin ruokauhrin ja juomauhrin pitää sinun sen uhraaman Herralle makiaksi hajuksi ja tuleksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Tämä on alinomainen polttouhri teidän sukukunnillenne seurakunnan majan oven tykönä Herran edessä, kussa minä olen saapuvilla teille, ja puhun sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Siellä minä Israelin lapsille olen saapuvilla: ja se pyhitetään minun kunniassani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Ja minä pyhitän todistuksen majan alttareinensa, ja pyhitän Aaronin poikinensa minulle papiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Ja asun Israelin lasten seassa, ja olen heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Ja heidän pitää tietämän, että minä olen Herra heidän Jumalansa, joka heidät johdatin Egyptin maalta, että minä asuisin heidän seassansa. Minä olen Herra heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Sinun pitää myös tekemän suitsutusalttarin suitsutettaa: sittimipuusta sinun sen tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Kyynärä pitää oleman hänen pituutensa ja kyynärä leveytensä: nelikulmaisen pitää sen oleman, ja kaksi kyynärää hänen korkeutensa; siitä myös pitää oleman hänen sarvensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Ja sinun pitää silaaman sen puhtaalla kullalla, hänen lakensa ja seinänsä ympärinsä, ja sen sarvet. Ja sinun pitää tekemän kultaisen vanteen sen ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Ja kaksi kultaista rengasta pitää sinun tekemän, molemmille tahoille kahteen hänen kulmaansa vanteen alle, että korennot niihin pistettäisiin, joilla se kannettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Sinun pitää myös tekemän korennot sittimipuusta, ja silaaman ne kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Ja asettaman se esiripun eteen, joka on todistusarkin edessä; armo-istuimen edessä, joka on todistuksen päällä, siellä minä tulen sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Ja Aaronin pitää sen päällä polttaman hyvänhajullista suitsutusta: joka aamu koska hän valmistaa kynttilät, pitää hänen sen suitsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Niin myös koska Aaron sytyttää kynttilät kahden ehtoon välillä, pitää hänen sen suitsuttaman: sen suitsutuksen pitää oleman alinomaisen Herran edessä, teidän sukukunnissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ei teidän pidä yhtään muukalaista suitsutusta tekemän sen päällä, eli polttouhria, eli ruokauhria, eikä myös juomauhria uhraaman sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Ja Aaron pitää sen sarvein päällä sovittaman kerran vuodessa: rikosuhrin verestä pitää hänen sen päällä kerran vuodessa sovittaman teidän sukukunnissanne: se on kaikkein pyhin Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Koska Israelin lapset luettelet, niin heidän pitää itsekunkin sielunsa edestä antaman sovinnon Herralle, koska he luetellaan: ettei heidän päällensä joku rangaistus tulisi, koska he luetellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Ja pitää jokaisen, joka luvussa on, antaman puolen sikliä, pyhän siklin jälkeen: sikli maksaa kaksikymmentä geraa: puoli sikliä pitää oleman Herran ylennysuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Joka kahdenkymmenen vuotisen luvussa löydetään ja sen ylitse: sen pitää antaman Herralle ylennysuhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Varallisen ei pidä siihen lisäämän, ja köyhän ei pidä vähentämän puolesta siklistä, koska he antavat Herralle ylennysuhrin teidän sieluinne sovinnoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Ja sinun pitää sovintorahan ottaman Israelin lapsilta, ja antaman sen seurakunnan majan palvelukseksi: ja sen pitää Israelin lapsille muistoksi oleman Herran edessä, että teidän sielunne sovitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Niin Herra taas puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Sinun pitää myös tekemän vaskisen pesoastian, vaskijalan kanssa, pesemistä varten: ja sen pitää sinun asettaman seurakunnan majan ja alttarin vaiheelle, ja paneman siihen vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Että Aaron ja hänen poikansa pesisivät siitä kätensä ja jalkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Koska he menevät seurakunnan majaan, pitää heidän itsensä pesemän vedellä, ettei he kuolisi, taikka koska he lähestyvät alttarin tykö palvelemaan Herraa savu-uhrilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Ja heidän pitää pesemän kätensä ja jalkansa, ettei he kuolisi ja se pitää heille oleman ijankaikkiseksi säädyksi, hänelle ja hänen siemenellensä heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Ota sinulles parhaista kaluista: kaikkein kalliimmasta mirhamista viisisataa sikliä, ja puoli sen vertaa kanelia, kaksisataa ja viisikymmentä, ja myös kalmusta kaksisataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Mutta kasiaa viisisataa pyhän siklin jälkeen, ja öljyä öljypuusta yksi hin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Ja sinun pitää siitä tekemän pyhän voidellusöljyn, parhaan voiteen apotekarin tavalla: sen pitää pyhän voiteen-öljyn oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Sillä sinun pitää voiteleman seurakunnan majan, niin myös todistusarkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Ja pöydän ja kaikki hänen astiansa, ja kynttiläjalan ja sen astiat, niin myös suitsutusalttarin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Polttouhrin alttarin ja kaikki sen astiat, niin myös pesoastian jalkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Ja sinun pitää ne pyhittämän, ja ne pitää kaikkein pyhimmät oleman: mitä ikänänsä niihin tarttuu, se pitää pyhitetty oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Aaronin ja hänen poikansa pitää sinun myös voiteleman ja pyhittämän heitä minulle papiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Sinun pitää myös puhuman Israelin lapsille, sanoen: tämä öljy pitää oleman minulle pyhä voidellus teidän sukukunnissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Ihmisen ruumiin päälle ei pidä se voidellus vuodatettaman, ja ei teidän pidä myös senkaltaista tekemän; sillä se on pyhä, sentähden pitää myös se teiltä pyhitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Se joka tekee senkaltaista voidetta, eli joka panee sitä muukalaisen päälle, se pitää hävitettämän kansoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Ja Herra sanoi Mosekselle: ota sinulle hyvänhajullisia kaluja, staktea ja galbania (a); näistä hajavista kaluista, puhtaan pyhän savun (b) kanssa, pitää yhden verran oleman. (a) Bdellium. (b) Ollibanum purum.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Sinun pitää siitä tekemän suitsutuksen, apotekarin tavalla: suolatun, puhtaan ja pyhän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Ja sinun pitää sen pieneksi survoman, ja paneman siitä todistuksen eteen seurakunnan majaan, kussa minä olen sinua läsnä: sen pitää teille oleman kaikkein pyhimmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Ja senkaltaista suitsutusta ei teidän pidä itsellenne tekemän; mutta tämä pitää oleman sinulle pyhä, Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Joka senkaltaista tekee suitsuttaaksensa, se pitää hävitettämän kansoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Katso, minä kutsuin nimeltänsä Betsaleelin Urin pojan, Hurin pojanpojan, Juudan suvusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Ja täytin hänen Jumalan hengellä: viisaudella ja kaikkinaisella taidolla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Taitoja ylösajattelemaan, ja tekemään kullasta, ja hopiasta, ja vaskesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Taitavasti leikkaamaan ja sisälle panemaan kivet, ja taitavasti tekemään puusta kaikkinaista työtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Ja katso, minä annoin myös hänelle avuksi Oholiabin Ahisamakin pojan, Danin suvusta, ja itsekunkin taitavan sydämeen annoin minä taidon tekemään kaikkia, mitä minä olen sinulle käskenyt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Seurakunnan majan ja liiton arkin, ja armo-istuimen, joka sen päällä on, ja kaikki majan astiat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Pöydän ja sen astiat, ja puhtaan kynttilänjalan, ja kaikki sen kalut, ja myös savu-alttarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Polttouhri-alttarin ja kaikki sen kalut, ja myös pesoastian jalkoinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Ja virkavaatteet, ja papin Aaronin pyhät vaatteet, ja hänen poikainsa vaatteet, papin virkaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Voidellusöljyn ja suitsutuksen hajavista kaluista, pyhään: kaiken sen jälkeen, kuin minä olen sinulle käskenyt, pitää heidän tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Puhu Israelin lapsille, sanoen: teidän pitää kaiketi pitämän minun sabbatini; sillä se on merkki minun välilläni ja teidän, teidän suvuissanne, että te tietäisitte minun olevan Herran, joka teitä pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Sentähden pitäkäät sabbati; sillä se on teillä pyhä. Joka sen rikkoo, hänen pitää totisesti kuoleman; sillä kuka ikänänsä silloin työtä tekee, sen sielu pitää hävitettämän kansansa seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Kuusi päivää pitää työtä tehtämän, mutta seitsemäntenä päivänä on sabbatin lepo, pyhä Herralle: kuka ikänänsä työtä tekee sabbatin päivänä, hänen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Sentähden pitäkään Israelin lapset sabbatin, että he sen pyhittäisivät, sukukunnissansa ijankaikkiseksi liitoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Minun ja Israelin lasten välillä on se ijankaikkinen merkki; sillä kuutena päivänä teki Herra taivaan ja maan, mutta seitsemäntenä päivänä hän lepäsi, ja virvoitti itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Ja sitte kuin Herra oli lopettanut puheensa Moseksen kanssa Sinain vuorella, antoi hän hänelle kaksi todistuksen taulua, jotka olivat kivestä, Jumalan sormella kirjoitetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Mutta koska kansa näki, että Moses viipyi tulemasta alas vuorelta, niin he kokoontuivat Aaronia vastaan, ja sanoivat hänelle: nouse, tee meille jumalia, jotka meidän edellämme kävisivät; sillä emme tiedä, mitä tälle miehelle Mosekselle tapahtunut on, joka meidät Egyptin maalta johdatti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Niin sanoi Aaron heille: reväiskäät kultaiset korvarenkaat, jotka ovat emäntienne korvissa, ja teidän poikainne, ja teidän tyttärenne: ja tuokaat minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Niin kaikki kansa repäisi ne kultaiset korvarenkaat, jotka olivat heidän korvissansa: ja toivat Aaronin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Jonka hän otti heidän kädestänsä, ja kuvasi sen kaivinraudalla, ja teki siitä valetun vasikan; ja he sanoivat: nämät ovat sinun jumalas, Israel, jotka sinun Egyptin maalta johdattivat ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Ja koska Aaron sen näki, rakensi hän alttarin heidän eteensä; ja Aaron huusi ja sanoi: huomenna on Herran juhlapäivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Ja he varhain aamulla nousivat toisena päivänä, ja he uhrasivat polttouhria, ja kantoivat edes kiitosuhria. Ja kansa istui syömään ja juomaan, ja nousivat mässäämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Mutta Herra puhui Mosekselle: mene, astu alas; sillä sinun kansas, jonka sinä Egyptin maalta johdatit ulos, turmeli itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'He äkisti poikkesivat pois siltä tieltä, jonka minä heille käskin. He tekivät itsellensä valetun vasikan, ja kumarsivat sitä, ja uhrasivat sille, ja sanoivat: nämät ovat sinun jumalas, Israel, jotka sinun Egyptin maalta johdattivat ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Ja Herra sanoi Mosekselle: minä näin tämän kansan; ja katso, se on niskurikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Sentähden salli nyt minun vihani julmistua heidän päällensä, että minä hukutan heidät: niin minä teen sinun suureksi kansaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mutta Moses rukoili hartaasti Herran Jumalansa edessä, ja sanoi: Herra, miksi sinun vihas julmistuu sinun kansan päälle, jonka Egyptin maalta johdatit ulos, suurella voimalla ja väkevällä kädellä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Miksi Egyptiläiset pitäis puhuman ja sanoman: heidän vahingoksensa hän heitä johdatti ulos, tappaaksensa heitä vuorella, ja hävittääksensä heitä maan päältä? Käänny pois sinun vihas hirmuisuudesta, ja kadu sitä pahaa sinun kansaas vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Muista sinun palvelioitas Abrahamia, Isaakia ja Israelia, joille sinä itse kauttas vannoit, ja sanoit heille: minä enennän teidän siemenenne niinkuin taivaan tähdet: ja kaiken tämän maan, josta minä sanoin, annan teidän siemenellenne, ja heidän pitää sen perimän ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Niin Herra katui sitä pahaa, jonka hän uhkasi tehdä kansallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Ja Moses käänsi itsensä, ja astui alas vuorelta, ja hänen kädessänsä oli kaksi todistuksen taulua: ja taulut olivat kirjoitetut molemmilta puolilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Ja taulut olivat Jumalan teko: ja kirjoitus oli myös Jumalan kirjoitus, kaivettu tauluihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Koska Josua kuuli kansan huudon, sanoi hän Mosekselle: sodan ääni leirissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Hän vastasi: ei se ole voittajain, eikä voitettuiden huuto: minä kuulen veisaajain äänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Ja koska hän lähestyi leiriä, näki hän vasikan ja hypyn. Ja Moseksen viha julmistui, ja heitti pois käsistänsä taulut, ja löi ne rikki vuoren alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Hän otti myös vasikan, jonka he tehneet olivat, ja poltti tulella, ja musersi sen tuhaksi; sitte hajoitti hän sen veteen, ja antoi sen Israelin lasten juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Ja Moses sanoi Aaronille: mitä tämä kansa on sinulle tehnyt, ettäs niin suuren rikoksen saatit heidän päällensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Ja Aaron sanoi: älköön minun herrani viha julmistuko: sinä tiedät, että tämä kansa on pahuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'He sanoivat minulle: tee meille jumalia, jotka meidän edellemme kävisivät; sillä emme tiedä, mitä tälle miehelle Mosekselle tapahtunut on, joka meidän Egyptin maalta johdatti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Joille minä sanoin: jolla on kultaa, reväiskään sen pois; ja he antoivat sen minulle, ja minä heitin sen tuleen, ja siitä tuli tämä vasikka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Kun Moses näki, että kansa oli paljastettu; sillä Aaron oli heidän paljastanut häväistykseksi heidän vihollisillensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Niin Moses seisoi leirin portissa ja sanoi: joka on Herran oma, se tulkaan minun tyköni; niin kokoontuivat hänen tykönsä kaikki Levin pojat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Joille hän sanoi: näin sanoo Herra Israelin Jumala: jokainen sitokaan miekan kupeillensa: vaeltakaat lävitse, ja palaitkaat portista niin porttiin leirissä, ja tappakaat itsekukin veljensä, ja kukin ystävänsä, ja kukin lähimmäisensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Niin Levin pojat tekivät Moseksen käskyn jälkeen: ja sinä päivänä lankesi kansasta liki kolmetuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Moses sanoi: pyhittäkäät tänäpänä teidän kätenne Herralle, itsekukin pojassansa ja veljessänsä, että hän tänäpänä antais teille siunauksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Toisna päivänä sanoi Moses kansalle: te olette tehneet suuren synnin; ja nyt minä astun ylös Herran tykö, jos minä mitämaks taidan sovittaa teidän rikoksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Niin Moses palasi Herran tykö, ja sanoi: minä rukoilen; tämä kansa teki suuren synnin, ja he tekivät itsellensä kultaisia jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Nyt siis anna heidän rikoksensa anteeksi; mutta jollei, niin pyyhi minut nyt pois sinun kirjastas, jonkas kirjoittanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Ja Herra sanoi Mosekselle: joka minua vastaan syntiä tekee, sen minä pyyhin minun kirjastani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Niin mene sinä nyt, ja johdata kansa sille sialle, josta minä olen sinulle puhunut: Katsos, minun enkelini käy sinun edelläs. Mutta minun etsikkopäivänäni kostan minä heidän rikoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Ja niin löi Herra kansaa; että he olivat tehneet vasikan, jonka Aaron teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Ja Herra puhui Mosekselle: mene täältä, sinä ja kansa, jonkas johdatit Egyptin maalta, sille maalle, kuin minä vannoin Abrahamille, Isaakille ja Jakobille, sanoen: sinun siemenelles minä sen annan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ja lähetän sinun edelläs enkelin, ja ajan pois Kanaanealaiset, Amorilaiset, ja Hetiläiset, ja Pheresiläiset, Heviläiset, ja Jebusilaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Sille maalle, jossa rieskaa ja hunajaa vuotaa; sillä en minä mene sinun kanssas, sillä sinä olet niskuri kansa, etten minä sinua joskus tieltä hukuttaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Koska kansa kuuli tämän pahan puheen, tulivat he surulliseksi, ja ei yksikään pukenut kaunistusta yllensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Ja Herra sanoi Mosekselle: sano Israelin lapsille: te olette niskurikansa, minä tulen äkisti sinun päälles, ja hukutan sinun; riisu siis nyt kaunistukses sinultas, että minä tietäisin, mitä minä sinulle tekisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Niin riisuivat Israelin lapset kaunistuksensa Horebin vuoren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Moses myös otti majan ja pani sen ylös kauvas leiristä, ja kutsui sen seurakunnan majaksi: ja kuka ikänänsä tahtoi kysyä Herralta, hänen piti menemän seurakunnan majan tykö, joka oli ulkona leiristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Ja tapahtui, koska Moses meni majan tykö, niin nousi kaikki kansa, ja itsekukin seisoi majansa ovella, ja he katselivat Moseksen jälkeen siihen asti, että hän tuli majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Ja tapahtui, koska Moses tuli majaan, tuli pilven patsas alas, ja seisoi majan ovella: ja puhutteli Mosesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Ja koska kaikki kansa näki pilven patsaan seisovan majan oven edessä, niin kaikki kansa nousi ja itsekukin kumarsi itsensä majan ovella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Ja Herra puhutteli Mosesta kasvosta niin kasvoon, niinkuin joku ystävätänsä puhuttelee. Ja koska hän palasi leiriin, niin hänen palveliansa Josua Nunin poika, nuorukainen ei lähtenyt majasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Ja Moses sanoi Herralle: katso, sinä sanot minulle: johdata tämä kansa, ja et sinä ilmoittanut, kenenkä sinä lähetät minun kanssani; ja kuitenkin sinä sanoit minulle: minä tunnen sinun nimeltäs, ja sinä olet myös armon löytänyt minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Nyt siis, jos minä muutoin olen armon löytänyt sinun edessäs, niin osota nyt minulle sinun ties, että minä sinut tuntisin ja löytäisin armon sinun edessäs: ja katso kuitenkin, että tämä väki on sinun kansas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Ja hän sanoi: minun kasvoni käy sinun edelläs, ja minä annan sinulle levon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Ja hän sanoi hänelle: jollei sinun kasvos käy edellä, niin älä vie meitä tästä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Ja mistä se tässä tietää saadaan, että minä ja sinun kansas olemme löytäneet armon sinun edessäs? Eikö, koskas vaellat meidän kanssamme? että me eroitettaisiin, minä ja sinun kansas, kaikista kansoista, jotka ovat maan piirin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Ja Herra sanoi Mosekselle: Ja minä myös tämän teen, niinkuin sinä sanoit; sillä sinä olet löytänyt armon minun edessäni, ja minä tunnen sinun nimeltäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Mutta hän sanoi: osota siis minulle sinun kunnias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Ja hän vastasi: minä annan kaikki minun hyvyyteni käydä sinun kasvois edellä, ja tahdon saarnata Herran nimeä sinun edessäs. Ja minä armaitsen, ja olen laupias, jolle minä laupias olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Ja sanoi taas: et sinä taida nähdä minun kasvojani; sillä ei yksikään ihminen, joka minun näkee, taida elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Vielä sanoi Herra: katsos, sia on minun tykönäni: siellä pitää sinun seisoman kalliolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Ja pitää tapahtuman, koska minun kunniani vaeltaa ohitse, niin minä panen sinun kallion rotkoon, ja minä peitän sinun minun kädelläni niinkauvan kuin minä vaellan ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Sitte koska minä otan pois minun käteni, saat sinä nähdä minun takaa; vaan minun kasvojani ei taideta nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Ja Herra sanoi Mosekselle: vuole sinulles kaksi kivistä taulua entisten kaltaista: ja minä kirjoitan niihin tauluihin ne sanat, jotka ensimäisissä tauluissa olivat, jotkas löit rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Ole siis huomenna valmis, ja astu varhain Sinain vuorelle, ja seiso siellä minun edessäni vuoren kukkulalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Vaan älkään yksikään astuko ylös sinun kanssas, älkään myös yksikään koko sillä vuorella näkykö; ja eikä lampaita eikä karjaa pidä kaittaman sen vuoren kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Ja Moses teki kaksi kivistä taulua entisten kaltaista, ja nousi aamulla varhain, ja astui ylös Sinain vuorelle, niinkuin Herra hänen käskenyt oli, ja otti ne kaksi kivistä taulua käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Ja Herra astui alas pilvessä, ja seisoi hänen kanssansa siellä, ja saarnasi Herran nimestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Ja Herra vaelsi hänen kasvoinsa edessä, ja huusi: Herra, Herra Jumala (on) laupias ja armollinen, ja pitkämielinen, suuresta armosta ja totuudesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Joka pitää laupiuden tuhanteen polveen, ja ottaa pois vääryyden, ylitsekäymisen ja synnin: jonka edessä ei yksikään ole viatoin, joka etsii isäin vääryyden ja lasten ja lastenlasten päälle, hamaan kolmanteen ja neljänteen polveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Ja Moses kiiruusti kumarsi itsensä maahan ja rukoili.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Ja sanoi: Herra, jos minä olen löytänyt armon sinun edessäs, niin käykään siis Herra meidän kanssamme: sillä tämä on niskuri kansa; että olisit meidän vääryydellemme ja synnillemme armollinen, ja omistaisit meitä sinulles perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Ja hän sanoi: katso, minä teen liiton kaiken sinun kansas edessä, ja minä myös teen ihmeellisiä tekoja, joidenka kaltaisia ei ikänänsä ennen tehty ole jossakussa maassa, eikä yhdenkään kansan seassa: ja kaiken kansan, joiden seassa sinä olet, pitää näkemän Herran teot; sillä se pitää oleman peljättävä, minkä minä sinun kanssas teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Pidä se, kuin minä sinulle tänäpänä käsken: katso, minä ajan ulos sinun edestäs Amorilaisen, Kanaanealaisen, Hetiläisen, Pheresiläisen, Heviläisen ja Jebusilaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Kavahda sinuas, ettet sinä tee liittoa sen maan asuvaisten kanssa, johonkas tulet: ettei se olisi sinulle paulaksi teidän keskellänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Vaan heidän alttarinsa pitää teidän kukistaman, ja heidän kuvansa rikkoman: ja heidän metsistönsä maahan lyömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Sillä ei sinun pidä rukoileman muita jumalia: sillä Herran nimi on kiivoittelia, että hän on kiivas Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ei sinun pidä joskus tekemän liittoa sen maan asuvaisten kanssa: sillä koska he hauristelevat jumalainsa kanssa, ja uhraavat jumalillensa, ja kutsuvat sinun, ettäs söisit heidän uhristansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Ja ottaisit heidän tyttäristänsä sinun pojilles emäntiä; jotka hauristelevat jumalainsa kanssa, ja saattavat sinun poikas myös heidän jumalainsa kanssa hauristelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Ei sinun pidä valetuita jumalia tekemän sinulles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Happamattoman leivän juhlan sinun pitää pitämän. Seitsemän päivää pitää sinun happamatointa leipää syömän, niinkuin minä sinulle käskenyt olen, määrätyllä ajalla Abibin kuulla; sillä sinä olet lähtenyt Egyptistä Abibin kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Kaikki, jotka ensin avaavat äitinsä kohdun, ovat minun: kaikki härkyiset karjasta, ja oinaat lampaista, jotka esikoiset ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Mutta aasin esikoisen pitää sinun lunastaman lampaalla; jos et sinä lunasta, niin väännä hänen niskansa poikki. Jokaisen esikoisen sinun pojistas pitää sinun lunastaman, ja ei yksikään pidä tyhjin käsin minun eteeni tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Kuusi päivää pitää sinun työtä tekemän, ja seitsemäntenä päivänä pitää sinun lepäämän: sekä pellon kyntämisestä että niittämisestä pitää sinun lepäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Viikkojuhlan sinun pitää pitämän, ensimäisestä nisun elon uutisesta: ja korjaamisen juhlan, vuoden lopulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Kolmasti vuodessa pitää kaikki miehen puoles näkymän kaikkivaltiaan Herran Israelin Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Sillä minä ajan ulos pakanat sinun edestäs ja levitän sinun maas ääret; ja ei pidä yhdenkään himoitseman sinun maatas, koska sinä menet ylös näyttämään itses Herralle sinun Jumalalles, kolmasti vuodessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Ei sinun pidä uhraaman minun uhrini verta happaman leivän ohessa. Ja pääsiäisjuhlan uhrista ei pidä mitään jäämän yön yli huomeneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Ensimäisestä sinun maas kasvon uutisesta pitää sinun tuoman sinun Herras Jumalas huoneesen. Ei sinun pidä keittämän vohlaa hänen emäntänsä rieskassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Ja Herra sanoi Mosekselle: kirjoita sinulles nämät sanat: sillä näiden sanain jälkeen olen minä liiton tehnyt sinun ja Israelin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Ja hän oli siellä Herran tykönä neljäkymmentä päivää ja neljäkymmentä yötä, ja ei syönyt leipää, eikä juonut vettä: ja hän kirjoitti tauluihin liiton sanat, ne kymmenet sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Koska Moses astui Sinain vuorelta alas, oli hänellä kaksi todistustaulua kädessänsä, astuissansa alas vuorelta: ja ei Moses tietänyt, että hänen kasvonsa nahka paisti siitä, että Herra oli puhutellut häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Ja koska Aaron ja kaikki Israelin lapset näkivät hänen kasvonsa nahan paistavan, pelkäsivät he häntä lähestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Niin kutsui Moses heitänsä hänen puoleensa, sekä Aaron että kaikki ylimmäiset kansan seasta, ja Moses puhutteli heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Sitte lähestyivät kaikki Israelin lapset häntä, ja hän käski heille kaikki ne, mitkä Herra puhui hänen kanssansa Sinain vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Ja että Moses olis tainnut päättää puheensa heidän kanssansa, pani hän peitteen kasvoinsa eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Mutta koska hän meni sisälle Herran eteen puhuttelemaan häntä, pani hän peitteen pois, niin kauvaksi kuin hän läksi jällensä ulos. Ja koska hän läksi ulos, puhui hän Israelin lapsille, mitä hänelle käsketty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Niin katsoivat Israelin lapset hänen kasvoihinsa, kuinka hänen kasvoinsa nahka paisti: niin veti jällensä peitteen kasvoinsa päälle, niinkauvaksi kuin hän jällensä meni puhuttelemaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Ja Moses kokosi kaiken Israelin seurakunnan, ja sanoi heille: nämät ovat ne, mitä Herra käskenyt on teidän tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Kuusi päivää pitää työtä tehtämän, mutta seitsemännen päivän pitää teille pyhä oleman, sabbatin lepo Herralle: kuka ikänänsä silloin työtä tekee, sen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ei teidän pidä tulta sytyttämän kaikissa teidän asuinsioissanne sabbatin päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Ja Moses sanoi kaikille Israelin lasten seurakunnalle: tämä on se, jota Herra käskenyt on, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Ottakaat teidän seastanne ylennysuhria Herralle: jokainen, jolla hyväntahtoinen sydän on, tuokaan ylennysuhrin Herralle: kultaa, hopiaa ja vaskea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Sinisiä, purpuraisia ja tulipunaisia villoja, kallista liinaa ja vuohen karvoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Punalla painetuita, oinaan nahkoja, ja tekasjim-nahkoja, sittimipuita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Öljyä lamppuihin, ja hyvänhajuisia kaluja voidellusöljyyn ja hyvään suitsutukseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Onikin kiviä ja sisälle suljetuita kiviä päällisvaatteesen ja rintavaatteesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Ja jokainen taitava teidän seassanne tulkaan ja tehkään kaikki mitä Herra käskenyt on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Majan vaatteinensa, peitteinensä, renkainensa, lautoinensa, korentoinensa, patsainensa ja jalkoinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Arkin korentoinensa, armo-istuimen ja esiripun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Pöydän korentoinensa ja kaikki sen kalut, niin myös katsomusleivän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Kynttiläjalan kaluinensa valistamaan, ja hänen lamppunsa ja öljyä valkeudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Ja savu-alttarin korentoinensa, voidellusöljyn ja hyvänhajavia kaluja suitsutukseen, ja vaatteen majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Polttouhrin alttarin vaskihäkin kanssa, korennot ja kaikki sen astiat: pesoastian jalkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Pihan vaatteet patsainensa ja jalkoinensa, niin myös vaatteen pihan oven eteen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Majan ja pihan vaarnat köysinensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Virkavaatteet pyhän palvelukseen: pyhät vaatteet papille Aaronille, hänen poikainsa vaatteen kanssa, papin virkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Silloin meni koko Israelin lasten seurakunta ulos Moseksen kasvoin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Ja tuli jokainen, jonka sydän kehoitettiin, ja jolla oli hyvänsuopainen henki, ja toivat ylennysuhrin Herralle, seurakunnan majan tarpeeksi, ja kaikkeen sen palvelukseen, ja pyhiin vaatteisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Ja tulivat sekä miehet että vaimot, kaikki, joilla oli hyvänsuopainen sydän, ja toivat rannerenkaita, korvarenkaita, sormuksia ja solkia, ja kaikkinaisia kultaisia astioita; toi myös joka mies kultaa häälytysuhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Ja jokainen toi, joka tyköänsä löysi sinisiä, ja purpuraisia, ja tulipunaisia villoja, ja kallista liinaa, ja vuohenkarvoja, punalla painetuita oinaan nahkoja, ja tekasjim-nahkoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Jokainen joka hopiaa ja vaskea ylensi, hän sen toi ylennysuhriksi Herralle. Ja jokainen, joka tyköänsä löysi sittimipuita, hän toi niitä kaikkinaiseksi Jumalan palveluksen tarpeeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Ja kaikki taitavat vaimot kehräsivät käsillänsä, ja toivat kehräyksensä sinisistä, ja purpuraisista ja tulipunaisista villoista, ja kalliista liinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Ja ne vaimot, jotka senkaltaisia töitä taisivat ja siihen olivat hyväntahtoiset, kehräsivät vuohen karvoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Mutta päämiehet toivat onikin kiviä, ja kiinnitettyjä kiviä, päällisvaatteesen ja rintavaatteesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Ja hyvänhajullisia yrttejä, ja öljyä valkeudeksi, ja voidellusöljyksi, ja yrttein suitsutukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Ja niin Israelin lapset toivat hyvällä mielellä, sekä miehet että vaimot kaikkinaiseen tarpeesen, niinkuin Herra Mosekselle käskenyt oli että tehtämän piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Ja Moses sanoi Israelin lapsille: katsokaat, Herra on kutsunut Betsaleelin nimeltä, Urin pojan, Hurin pojanpojan, Juudan suvusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Ja täyttänyt hänen Jumalan hengellä: taidolla, ymmärryksellä ja tiedolla kaikkinaiseen työhön,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Ja taitavasti ylösajattelemaan sitä, mitä tehdä taidetaan kullasta, hopiasta ja vaskesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Taitavasti kaivamaan ja sisälle kiinnittämään kalliita kiviä, veistämään puita, ja tekemään taitavasti kaikkinaista visua työtä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Ja on antanut taidon hänen sydämeensä opettaa: ynnä Oholiabin Ahisamakin pojan kanssa Danin suvusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Ja on täyttänyt heidän sydämensä taidolla, tekemään kaikkinaista visua työtä, kaivamaan, kutomaan ja neulomaan sinisiä, ja purpuraisia ja tulipunaisia villoja, ja kallista liinaa, niin että he tekevät ja ylösajattelevat kaikkinaisia, taitavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Niin Betsaleel ja Oholiab tekivät työtä, ja jokainen taitava mies, joille Herra oli antanut taidon ja ymmärryksen, tietämään tehdä kaikkea pyhän palveluksen työtä: kaiken sen jälkeen kuin Herra käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Ja Moses kutsui Betsaleelin ja Oholiabin, ja kaikki taitavat miehet, joiden sydämiin Herra oli taidon antanut: kaikki ne, jotka mielellänsä itsensä taritsivat ja menivät sitä työtä tekemään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Ja he ottivat Mosekselta kaikkinaiset ylennykset, jotka Israelin lapset toivat pyhän palveluksen tarpeeksi, että sen piti tehdyksi tuleman: ja he toivat joka aamu hyvämielisen lahjansa hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Niin he tulivat kaikki taitavat miehet, jotka kaikkea työtä tekivät pyhän rakennuksessa, itsekukin työstänsä kuin hän teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Ja he puhuivat Mosekselle, sanoen: kansa tuo ylen paljon: enemmän kuin tämän palveluksen rakennukseen tarvitaan, jonka Herra on käskenyt tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Niin Moses käski kaikille kuuluttaa leirissä, sanoen: älkään yksikään mies elikkä vaimo enempi tuoko ylennykseksi. Ja niin kansa estettiin tuomasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Sillä jo oli kalua kyllä kaikkinaiseen tarpeesen kuin tehtämän piti, ja vielä sittekin liiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Ja niin kaikki taitavat miehet, jotka siinä työssä olivat, tekivät majan kymmenen vaatetta: kalliista kerratusta liinasta, sinisistä, purpuraisista ja tulipunaisista villoista; ynnä Kerubimein kanssa tekivät he ne, taitavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Ja kunkin vaatteen pituus oli kahdeksankolmattakymmentä kyynärää, ja joka vaatteen leveys neljä kyynärää: yksi mitta oli kaikilla vaatteilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Ja hän yhdisti viisi vaatetta toinen toiseensa, ja taas viisi vaatetta toinen toiseensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Ja teki myös silmukset sinisistä villoista sen ensimäisen vaatteen palteesen sauman kohdalle: ja niin hän myös teki sen äärimäisen vaatteen reunaan toisen sauman kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Viisikymmentä silmusta hän teki ensimäiseen vaatteesen, ja viisikymmentä silmusta toisen vaatteen reunaan, joilla ne toinen toisiinsa yhdistettiin: ja silmukset olivat toinen toisensa kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Ja hän teki myös viisikymmentä kultaista koukkua, joilla hän vaatteet toinen toiseensa yhdisti, niin että se tuli yhdeksi majaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Ja hän teki vaatteet vuohen karvoista, peitteeksi majan päälle: yksitoistakymmentä vaatetta hän niistä teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Ja jokaisen vaatteen pituus oli kolmekymmentä kyynärää, ja leveys neljä kyynärää: yksi mitta oli kaikilla yhdellätoistakymmenellä vaatteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Ja yhdisti viisi vaatetta erinänsä, ja kuusi vaatetta erinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Ja teki viisikymmentä silmusta äärimäisen vaatteen reunalle, sauman kohdalle, ja teki myös viisikymmentä silmusta toisen vaatteen reunaan, sauman kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Ja hän teki viisikymmentä vaskikoukkua, joilla maja yhdistettiin, että se yksi olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Ja teki peitteen majan päälle, punalla painetuista oinaan nahoista, ja vielä peitteen sen päälle tekasjimnahoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Ja teki majan laudat sittimipuista, pystyälle olemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Jokaisen laudan pituus oli kymmenen kyynärää, ja leveys puolitoista kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Jokaiseen lautaan teki hän kaksi vaarnaa, joilla ne toinen toiseensa liitettiin: niin teki hän kaikki majan laudat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Ja hän teki ne majan laudat, niin että kaksikymmentä lautaa seisoi etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Ja teki neljäkymmentä hopiajalkaa kahdenkymmenen laudan alle: joka laudan alle kaksi jalkaa, aina kahden vaarnan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Hän teki myös toiselle sivulle majaa, pohjan puolelle, kaksikymmentä lautaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Neljänkymmenen hopiajalan kanssa: aina kaksi jalkaa kunkin laudan alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Mutta perälle majaa, länteen päin, teki hän kuusi lautaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Ja teki kaksi muuta lautaa majan kulmille, molemmille sivuille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Niin että kumpikin niistä tuli yhteen alhaalta; niin myös ylhäältä yhdistettiin ne yhdellä renkaalla: niin hän teki niille molemmille kulmille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Ja oli kahdeksan lautaa, ja kuusitoistakymmentä hopiajalkaa: aina kaksi jalkaa yhden laudan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Niin teki hän myös korennot sittimipuusta: viisi niihin lautoihin, jotka olivat yhdellä puolella majaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Ja viisi korentoa niihin lautoihin, jotka olivat toisella puolella majaa, ja taas viisi korentoa niihin lautoihin, jotka olivat kahden puolen majaa länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Ja teki keskimäisen korennon, niin että se piti lautain keskeltä sisälle sysättämän, yhdestä kulmasta toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Ja silasi laudat päältä kullalla, mutta heidän renkaansa teki hän kullasta, joihinka korennot pistettiin: ja silasi myös korennot kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Hän teki myös esiripun, sinisistä, purpuraisista ja tulipunaisista villoista ja kalliista kerratusta liinasta: hän teki myös Kerubimin sen päälle taitavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Ja teki siihen neljä patsasta sittimipuusta, ja silasi ne kullalla, ja niiden koukut kullasta, ja valoi niille neljä hopiajalkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Ja teki vaatteen majan oven eteen, sinisistä, ja purpuraisista, ja tulipunaisista villoista, ja valkiasta kerratusta liinasta: taitavasti neulotun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Ja viisi patsasta heidän koukkuinsa kanssa, ja silasi niiden päät, ja heidän vanteensa kullalla: ja niiden viisi vaskijalkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Ja Betsaleel teki arkin sittimipuusta: puolikolmatta kyynärää pitkän, puolitoista kyynärää leviän, ja puolitoista kyynärää korkian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Ja silasi sen puhtaalla kullalla, sekä sisältä että ulkoa, ja teki sen ympärille kultaisen vanteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Ja valoi neljä kultarengasta hänen neljään kulmaansa: kaksi rengasta yhdelle puolelle, ja myös kaksi rengasta toiselle puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Ja teki korennot sittimipuusta, ja silasi ne kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Ja pisti ne korennot renkaisiin arkin sivulle, niin että arkki taidettiin kannettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Ja hän teki armo-istuimen puhtaasta kullasta, puolikolmatta kyynärää pitkän ja puolitoista kyynärää leviän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Ja teki kaksi Kerubimia kullasta: vahvaa tekoa, molempiin päihin armo-istuinta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Yhden Kerubimin tähän päähän, ja toisen Kerubimin toiseen päähän: molempiin päihin armo-istuinta hän teki Kerubimit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Ja Kerubimit levittivät siipensä sen ylitse, ja peittivät armo-istuimen siivillänsä, ja heidän kasvonsa olivat toinen toisensa puoleen: armo-istuimeen päin olivat Kerubimien kasvot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Hän teki myös pöydän sittimipuusta, kaksi kyynärää pitkäksi, kyynärää leviäksi, ja puolitoista kyynärää korkiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Ja silasi sen puhtaalla kullalla, ja teki kultaisen vanteen sen ympärille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Ja teki partaan sen ympärille kämmentä leviän: teki myös kultaisen vanteen partaan ympärille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Ja valoi siihen neljä kultaista rengasta, ja pani ne renkaat neljälle kulmalle heidän neljän jalkansa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Juuri partaan kohdalla olivat renkaat, joissa korennot olivat sisällä, joilla pöytä kannettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Ja hän teki myös korennot sittimipuusta, ja silasi ne kullalla, että pöytä niillä kannettaa taidettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Hän teki myös pöytäastiat, vadit, lusikat, ja maljat, ja pikarit, joilla ulos ja sisälle kaadettiin, puhtaasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Hän teki myös kynttiläjalan puhtaasta kullasta: vahvan tekoiseksi hän kynttiläjalan teki ja hänen vartensa, haaransa, maljansa, nuppinsa ja kukkaisensa olivat siitä samasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Kuusi haaraa kävi hänen kyljestänsä: kolme haaraa kynttiläjalan yhdeltä sivulta, ja myös kolme haaraa sen toiselta sivulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Kolme mandelin-muotoista maljaa oli sen yhdessä haarassa, ja yksi nuppi ja kukkainen, niin myös kolme mandelin-kaltaista maljaa toisessa haarassa, yksi nuppi ja kukkainen: niin oli niissä kuudessa haarassa, jotka kynttiläjalasta uloskävivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Mutta kynttiläjalassa oli neljä mandelin-muotoista maljaa toisessa haarassa, nuppeinsa ja kukkaistensa kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Niin että nuppi oli siinä kahden haaran alla, ja taas nuppi (toisen) kahden haaran alla, ja vielä nuppi kahden jälkimmäisen haaran alla: nimittäin niissä kuudessa haarassa, jotka siitä uloskävivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ja hänen nuppinsa ja haaransa sen päällä, ja se kaikki oli puhtaasta lujasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Ja hän teki myös seitsemän lamppua: ja heidän niistimensä ja sammutuskalunsa olivat puhtaasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Ja hän teki sen, kaikkein astiainsa kanssa, yhdestä leiviskästä puhdasta kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Hän teki myös suitsutusalttarin sittimipuusta: yhtä kyynärää pitkän ja yhtä kyynärää leviän, juuri nelikulmaiseksi, ja kaksi kyynärää korkian; siitä uloskävivät hänen sarvensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Ja silasi sen puhtaalla kullalla, sen katon ja seinät ympärinsä, ja sen sarvet: ja teki sen ympärille vanteen kullasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Ja kaksi kultaista rengasta vanteen alle molemmin puolin, niin että korennot siihen sysättiin, kannettaa niillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Ja korennot hän teki sittimipuusta, ja silasi ne kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Ja teki pyhän voidellusöljyn ja puhtaan suitsutuksen, hyvänhajullisista yrteistä, apotekarin tavan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Ja teki myös polttouhrin alttarin sittimipuusta, viisi kyynärää pitkän ja viisi kyynärää leviän, juuri nelikulmaiseksi, ja kolme kyynärää korkiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Ja teki neljä sarvea sen neljän kulman päälle: siitä olivat hänen sarvensa; ja silasi sen vaskella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Ja teki kaikkinaiset alttarin astiat, tuhka-astiat, lapiot, maljat, hangot, hiiliastiat: kaikki astiat teki hän vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Ja teki alttarin ympärille vaskihäkin niinkuin verkon, maasta niin puolialttariin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Ja valoi neljä rengasta neljään vaskihäkin kulmiin, että korennot niihin pistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Ja teki korennot sittimipuusta, ja silasi ne vaskella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Ja pani renkaisiin alttarin sivulle, joilla se kannettiin. Ja teki laudoista, avojammaksi sisältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Ja hän teki pesoastian vaskesta, ja sen jalan myös vaskesta, niiden vaimoin peileistä, jotka palvelivat seurakunnan majan oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Ja hän teki pihan etelään päin, ja pihan vaatteet valkiasta kerratusta liinasta, sata kyynärää pitkäksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Hänen kahdenkymmenen patsastensa ja kahdenkymmenen jalkainsa kanssa vaskesta, mutta heidän koukkunsa ja vyönsä hopiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Niin myös pohjaa päin sata kyynärää, kahdenkymmenen patsaan ja kahdenkymmenen jalan kanssa vaskesta, mutta heidän koukkunsa ja vyönsä hopiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Mutta lännen puolella olivat vaatteet viisikymmentä kyynärää, kymmenen patsaansa ja kymmenen jalkansa kanssa, mutta heidän koukkunsa ja vyönsä hopiasta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Mutta itää päin viisikymmentä kyynärää:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Vaatteet viisitoistakymmentä kyynärää sivulla: kolmen patsaan ja kolmen jalan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Ja toisella sivulla molemmin puolin, pihan läpikäytävän tykönä, olivat vaatteet viisitoistakymmentä kyynärää: heidän kolmen patsaansa ja jalkansa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Ja kaikki pihan vaatteet ympärinsä olivat valkiasta kerratusta liinasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Ja patsasten jalat vaskesta, ja heidän koukkunsa ja vyönsä hopiasta, niin että heidän nuppinsa olivat silatut hopialla: ja kaikki myös ne pihan patsaat olivat vyötetyt hopiavyöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Ja peitevaatteet pihan sisällekäytävään teki hän sinisistä ja purpuraisista ja tulipunaisista villoista, ja valkiasta kerratusta liinasta, taitavasti neulotut, kaksikymmentä kyynärää pitkäksi, ja viisi kyynärää korkiaksi leveydessä pihan vaatteen kohdalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Niin myös niiden neljä patsasta ja niiden neljä jalkaa vaskesta, ja heidän koukkunsa hopiasta, ja heidän päänsä silatut ja vyötetyt hopiavöillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Ja kaikki vaarnat majassa, ja koko piha ympärinsä, olivat vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Tämä on kaluin luku joka todistuksen majaan tarvittiin, jotka ovat luetut Moseksen käskyn jälkeen: Leviläisten palveluksen kautta, Itamarin papin Aaronin pojan käden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Ja Betsaleel Urin poika, Hurin pojanpoika Juudan suvusta, teki kaikki kuin Herra Mosekselle oli käskenyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Ja hänen kanssansa Oholiab Ahisamakin poika Danin suvusta; sillä hän oli taitava ja ymmärtäväinen neulomaan sinisillä, ja purpuraisilla, ja tulipunaisilla villoilla, ja valkialla liinalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Kaikki se kulta mikä tehtiin kaiken tämän pyhän tarpeeksi, se kuin annettu oli ylennykseksi, oli yhdeksänkolmattakymmentä leiviskää, seitsemänsataa ja kolmekymmentä sikliä, pyhän siklin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Mutta hopia, joka siihen yhteiseltä kansalta annettiin, oli sata leiviskää, tuhannen seitsemänsataa viisikahdeksattakymmentä sikliä, pyhän siklin jälkeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Niin monta puolta sikliä, kuin monta henkeä, pyhän siklin jälkeen: kaikilta niiltä, jotka luetut olivat kahdestakymmenestä ajastajasta ja sen ylitse, kuusisataa tuhatta, kolmetuhatta, viisisataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Sadasta leiviskästä hopiaa valettiin pyhät jalat, ja esiripun jalat: sata jalkaa sadasta leiviskästä, leiviskä kullekin jalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Mutta tuhannesta seitsemästäsadasta ja viidestäkahdeksattakymmenestä siklistä tehtiin koukut patsaisiin: ja heidän päänsä silattiin, ja vyöllä vyötettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Mutta vaski, joka annettiin ylennysuhriksi, oli seitsemänkymmentä leiviskää, kaksituhatta ja neljäsataa sikliä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Siitä tehtiin jalat seurakunnan majan oveen, ja vaski-alttari ja vaskihäkki kuin siinä oli, ja myös kaikki alttarin astiat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Niin myös jalat ympärinsä pihaa, ja jalat pihan sisällekäytävään, ja kaikki majan vaarnat, ja kaikki pihan vaarnat ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Mutta sinisistä, ja purpuraisista, ja tulipunaisista villoista tekivät he virkavaatteita palvelukseen pyhässä: ja he tekivät pyhiä vaatteita Aaronille, niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Ja hän teki päällisvaatteen kullasta, sinisistä, ja purpuraisista, ja tulipunaisista villoista ja valkiasta kerratusta liinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Ja he takoivat kullan kiskoksi, jonka hän leikkasi langaksi, että se taittiin taitavasti kudottaa sinisten, purpuraisten ja tulipunaisten villain ja valkian liinan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'He tekivät hänelle olkavaatteet, yhteensidotut: kahdelta kulmalta se yhdistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Ja vyö sen päällä oli myös tehty sillä tavalla taitavasti kullasta, sinisistä, purpuraisista, ja tulipunaisista villoista ja valkiasta kerratusta liinasta: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Ja he tekivät onikin kivet, kiinnitetyt kultaan: kaivetut sinetin tavalla Israelin lasten nimein jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Ja istuttivat ne olkapäille päällisvaatteesen, että ne kivet piti oleman Israelin lapsille muistoksi: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Ja he tekivät rintavaatteen sillä tavalla taitavasti, kuin päällisvaatekin oli tehty: kullasta, sinisistä, ja purpuraisista villoista, ja kalliista kerratusta liinasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Niin että se oli nelitahkoinen ja kaksikertainen: vaaksa pituudelta ja vaaksa leveydeltä, aina kaksikertaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Ja täytti sen neljällä kivirivillä: ensimäinen rivi oli sardius, topatsius ja smaragdi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Toinen rivi: rubin, saphiir ja demanti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Kolmas rivi: lynkurius, akat ja ametisti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Ja neljäs rivi: turkos, oniks ja jaspis: kiinnitetyt ympäriltä kullalla joka riviltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Ja nämät kivet olivat Israelin lasten nimein jälkeen kaksitoistakymmentä, kaivetut sinetin tavalla, itsekukin nimeltänsä, kahdentoistakymmentä sukukunnan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'He tekivät myös rintavaatteen päälle vitjat kahden pään kanssa, vääten puhtaasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Ja he tekivät kaksi kultanastaa, ja kaksi kultarengasta, ja yhdistivät ne kaksi rengasta kahteen rintavaatteen palteesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Ja pistivät ne kaksi kultavitjaa niihin kahteen renkaasen, rintavaatteen kulmiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Mutta ne kaksi päätä vitjoista panivat he ylös niihin kahteen nastaan, ja yhdistivät ne päällisvaatteen kulmilta, juuri toinen toisensa kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Niin he tekivät kaksi muuta kultarengasta, ja yhdistivät ne niihin toisiin kahteen rintavaatteen kulmaan, sen palteesen joka on päällisvaatteen sivussa sisällisellä puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Ja he tekivät kaksi muuta kultarengasta: ne panivat he kahteen kulmaan alhaallepäin päällisvaatteesen, toinen toisensa kohdalle, sitä saumaa kohden, päällisvaatteen vyön ylimmäiselle puolelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Niin että rintavaate yhdistettiin renkainensa niihin renkaisiin, kuin oli päällisvaatteessa, sinisellä nuoralla, niin että se olis liki päällisvaatetta, ja ei eriäis päällisvaatteesta: niinkuin Herra käski Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Hän teki myös hameen päällisvaatteen alle, kokonansa kudotun sinisistä villoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Ja päänläven keskelle, niinkuin pantsarin päänläven; sepaluksen päänläven ympärille pallistetun, ettei se kehkiäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Ja he tekivät granaatin omenat alhaalle hameen liepeisiin sinisistä, ja purpuraisista ja tulipunaisista villoista, jotka kerratut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Ja tekivät kulkuiset puhtaasta kullasta, ja panivat ne kulkuiset granaatin omenain välille ympärille, hameen liepeisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Niin että kulkuinen ja granaatin omena oli vuoroin ympärinsä hameen liepeitä: palvelemaan sillä, niinkuin Herra käskenyt oli Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Ja he tekivät myös ahtaat hameet, kudotut valkiasta kalliista liinasta, Aaronille ja hänen pojillensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Ja hiipan valkiasta kalliista liinasta, ja kauniit lakit valkiasta kalliista liinasta, ja alusvaatteet valkiasta kerratusta liinasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Ja taitavasti neulotun vyön valkiasta kerratusta kalliista liinasta, sinisistä, ja purpuraisista, ja tulipunaisista villoista: niinkuin Herra käskenyt oli Mosekselle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'He tekivät myös otsalehden, pyhän kruunun päälle, puhtaasta kullasta, ja kaivoivat kirjoituksen siihen, niinkuin sinetti kaivetaan: HERRAN PYHYYS.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Ja sitoivat sen päälle sinisen nuoran, että sen piti yhdistämän hiipan ylhäältä: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Ja niin kaikki seurakunnan majan rakennus päätettiin. Ja Israelin lapset tekivät kaikki sen jälkeen, kuin Herra oli käskenyt Mosekselle; niin he tekivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Ja he kantoivat majan Moseksen tykö kaluinensa: sen koukut, laudat, korennot, patsaat ja jalat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Ja peitteen punalla painetuista oinaan nahoista, peitteen tekasjim-nahoista: ja peitteen esiripun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Todistusarkin korentoinensa, ja myös armo-istuimen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Pöydän kaikkein astiainsa kanssa, ja katsomusleivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Puhtaan kynttiläjalan valmistetun lamppuinensa, kaiken sen kanssa kuin siihen tarvittiin, ja öljyä valkeudeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Kulta-alttarin ja voidellusöljyn, ja yrttein suitsutuksen, ja majan ovivaatteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Vaskisen alttarin ja vaskisen häkin korentoinensa, ja kaikkein kaluinsa kanssa, ja pesoastian jalkoinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Pihan vaatteet patsainensa ja jalkoinensa, vaatteen pihan sisällekäytävän eteen, köysinensä ja vaajoinensa, ja kaikki seurakunnan majan palveluksen astiat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Virkavaatteet palveltaa pyhässä, papin Aaronin pyhät vaatteet, ja hänen poikainsa vaatteet, joilla heidän piti tekemän papin viran palveluksen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Kaikkein niiden jälkeen mitkä Herra oli käskenyt Mosekselle: niin tekivät Israelin lapset kaiken sen työn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Ja Moses näki kaiken tämän rakennuksen, että he olivat tehneet sen, niinkuin Herra oli käskenyt; ja Moses siunasi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Ensimäisenä päivänä ensimäisestä kuusta pitää sinun paneman ylös seurakunnan majan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Ja sinun pitää siihen paneman sisälle todistuksen arkin, ja sinun pitää peittämän arkin esiripulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Ja sinun pitää myös sinne sisälle tuoman pöydän, ja valmistaman sen, ja asettaman siihen kynttiläjalan, ja paneman lamput sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Ja sinun pitää asettaman kultaisen savualttarin todistusarkin eteen, ja ripustaman vaatteen majan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Mutta polttouhrin alttarin pitää sinun asettaman seurakunnan majan oven eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Ja paneman pesoastian seurakunnan majan ja alttarin välille, ja paneman siihen vettä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Ja tekemän pihan sen ympärille, ja ripustaman vaatteen pihan portin eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Ja ottaman voidellusöljyn, ja voiteleman majan ja kaikki ne mitkä siinä ovat, ja pyhittämän sen kaluinensa, että ne olisivat pyhät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ja voiteleman polttouhrin alttarin kaluinensa, ja pyhittämän alttarin: ja se alttari pitää oleman kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Sinun pitää myös voiteleman pesinastian jalkoinensa, ja sen pyhittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Ja sinun pitää tuoman Aaronin poikinensa seurakunnan majan oven eteen, ja pesemän heidät vedellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Ja puettaman Aaronin pyhiin vaatteisiin, ja voiteleman ja pyhittämän hänen, minun papikseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Ja sinun pitää myös tuoman hänen poikansa ja puettaman heidän yllensä ahtaat hameet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Ja voiteleman heidät, niinkuin sinä heidän isänsä voitelit, minun papikseni. Ja tämän voidelluksen pitää oleman heille ijankaikkiseksi pappeudeksi, heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Ja Moses teki kaikki kuin Herra oli hänelle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Niin tapahtui toisena vuonna, ensimäisenä päivänä ensimäisestä kuusta, että maja pantiin ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Ja koska Moses pani ylös majan, niin hän asetti jalat ja laudat ja korennot, ja nosti patsaat pystyälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Ja levitti peitteen majan ylitse, ja pani katon sen päälle: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Ja otti todistuksen ja pani arkkiin, ja asetti korennot arkin päälle, ja pani myös armoistuimen arkin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Ja toi arkin majaan, ja ripusti esiripun todistusarkin eteen: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Niin asetti hän myös pöydän seurakunnan majaan, pohjan puoliselle sivulle, ulkoiselle puolelle esirippua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Ja asetti leivät sen päälle järjestykseen, Herran eteen: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Niin pani hän myös kynttiläjalan seurakunnan majaan, juuri pöydän kohdalle, etelän sivulle majaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Ja pani lamput niiden päälle Herran eteen: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Ja pani myös kultaisen alttarin seurakunnan majaan, esiripun eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Ja suitsutti yrttein suitsutuksen sen päällä: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Ja ripusti vaatteen majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Vaan polttouhrin alttarin pani hän seurakunnan majan oven eteen, ja uhrasi sen päällä polttouhrin ja ruokauhrin: niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Ja pesoastian pani hän seurakunnan majan ja alttarin välille, ja pani siihen vettä pestä heitänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Ja Moses ja Aaron ja hänen poikansa pesivät kätensä ja jalkansa siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Sillä heidän piti pesemän itsensä, koska he menivät seurakunnan majaan eli kävivät alttarin tykö; niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Ja hän pani pihan ylös, majan ja alttarin ympärille, ja ripusti vaatteen pihan sisällekäytävään. Ja niin Moses päätti sen työn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Ja pilvi peitti seurakunnan majan, ja Herran kunnia täytti majan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Ja ei Moses taitanut käydä seurakunnan majaan; sillä pilvi oli sen päällä, ja Herran kunnia täytti majan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Ja koska pilvi meni ylös majan päältä niin Israelin lapset vaelsivat, kaikissa matkoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Vaan koska ei pilvi mennyt ylös, silloin ei he vaeltaneet, siihen päivään asti, että se meni ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Sillä Herran pilvi oli päivällä majan ylitse, ja yöllä oli tuli siinä, koko Israelin huoneen silmäin edessä, kaikissa heidän vaelluksissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Ja Herra kutsui Moseksen, ja puhui hänelle seurakunnan majasta, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Puhu Israelin lapsille, ja sano heille: joka teistä tahtoo uhrata Herralle, niin tehkäät teidän uhrinne eläimistä, karjasta ja lampaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Jos hän tahtoo Herralle polttouhria karjasta tehdä, niin uhratkaan virheettömän härkyisen: seurakunnan majan oven edessä hän sen uhratkaan, että se olis Herralle otollinen häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Ja pankaan kätensä sen polttouhrin pään päälle, niin se on otollinen häntä sovittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Ja hänen pitää teurastaman mullin Herran edessä; ja papit, Aaronin pojat, pitää tuoman veren ja priiskottaman alttarille ympärinsä, joka on seurakunnan majan oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Ja vuota pitää polttouhrista nyljettämän ja pitää kappaleiksi hakattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Ja papin Aaronin pojat pitää tekemän tulen alttarille ja halvot tulen päälle paneman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Ja papit Aaronin pojat pitää sovittaman kappaleet, pään ja lihavuuden, halkoin päälle, jotka ovat alttarilla tulen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Mutta sisällykset ja jalat pitää vedellä pestämän, ja papin pitää kaikki nämät polttaman alttarilla: polttouhriksi, ja lepytyshajun tuleksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Ja jos hän tahtoo tehdä polttouhria pienistä eläimistä, lampaista eli vuohista, niin uhratkaan virheettömän oinaan eli kauriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Ja teurastakaan sen Herran edessä pohjan puolella alttaria, ja papit, Aaronin pojat, pitää priiskottaman hänen verensä alttarille ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Ja se pitää hakattaman kappaleiksi, sekä pää että lihavuus, ja papin pitää ne sovittaman halkoin päälle, jotka ovat alttarilla tulen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Mutta sisällykset ja jalat pitää vedellä pestämän, ja papin pitää sen kaiken uhraaman ja polttaman alttarillla: se on polttouhri, tuliuhri ja lepytyshaju Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Jos hän tahtoo taas tehdä polttouhria Herralle linnuista, niin tehkään sen mettisistä, elikkä kyhkyläisten pojista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Ja papin pitää sen alttarille tuoman, ja niskan poikki vääntämän, ja alttarilla polttaman, ja antaman veren vuotaa alttarin seinään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Ja ottakaan hänen kupunsa höyheninensä ulos, ja heittäkään ne alttarin viereen itään päin, tuhka-ko\'on päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Ja pitää sen siipinensä halkaiseman, mutta ei erinänsä repäisemän. Ja niin papin pitää sillänsä sen polttaman halkoin päällä, jotka ovat alttarilla tulen päällä: tämä on polttouhri, tuliuhri ja lepytyshaju Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Ja jos joku henki tahtoo tehdä Herralle ruokauhria, niin sen pitää oleman sämpyläjauhoista, ja hänen pitää öljyä sen päälle vuodattaman ja pyhää savua sen päälle paneman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Ja sitte sen papeille Aaronin pojille viemän: niin pitää papin ottaman pivonsa täyden niistä sämpyläjauhoista, ja öljyä kaiken pyhän savun kanssa, ja sen polttaman alttarilla muistoksi. Tämä on tuliuhri ja lepytyshaju Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Se kuin jää ruokauhrista, pitää oleman Aaronin ja hänen poikainsa oman: sen pitää oleman kaikkein pyhimmän Herran tulista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Mutta jos sinä tahdot tehdä ruokauhria pätsissä kypsytetystä, niin ota happamattomia kyrsiä sämpyläjauhoista öljyyn sekoitettuna, ja happamattomia ohukaisia kyrsiä öljyllä voideltuita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Vaan jos sinun ruokauhris on pannussa kypsetystä, niin sen pitää oleman happamattomista sämpyläjauhoista öljyyn sekoitettuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Sen sinun pitää jakaman kappaleiksi, ja vuodattaman öljyä sen päälle: niin se on ruokauhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ja jos sinun ruokauhris on halstarilla kypsetystä, niin sinun pitää tekemän sen sämpyläjauhoista öljyn kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Ja sen ruokauhrin, jonka sinä tahdot senkaltaisista tehdä Herralle, pitää sinun tuoman papille, ja kantaman sen alttarin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Ja papin pitää ylentämän sen ruokauhrin muistoksi ja polttaman alttarilla. Se on tuliuhri ja lepytyshaju Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Tähteet ruokauhrista tulee oleman Aaronin ja hänen poikainsa omat: sen pitää oleman kaikkein pyhimmän Herran tulista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Kaiken ruokauhrin, kuin te uhraatte Herralle, pitää teidän tekemän ilman hapatusta: sillä ei yhtään hapatusta eli hunajaa pidä siinä poltettaman uhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Mutta uutisten uhrissa pitää teidän ne uhraaman Herralle; vaan ei ne pidä tuleman alttarille makiaksi hajuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Kaiken sinun ruokauhris pitää sinun suolaaman, ja sinun ruokauhris ei pidä ikänänsä ilman sinun Jumalas liittosuolata oleman; sillä kaikissa sinun uhreissas pitää sinun suolaa uhraaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Mutta jos sinä tahdot tehdä uutisesta ruokauhrin Herralle, niin sinun pitää kuivaaman viheriäiset tähkäpäät tulella, ja survoman ne pieniksi, ja sitten uhraaman ruokauhrin sinun uutisestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Ja sinun pitää paneman öljyä siihen ja pyhää savua, niin on se ruokauhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Ja papin pitää ottaman niistä survotuista jyvistä ja öljystä, ynnä kaiken pyhän savun kanssa, ja polttaman sen muistoksi. Se on tuliuhri Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Ja jos hänen uhrinsa on kiitosuhri karjasta, niin pitää hänen uhraaman härjän eli lehmän, ja virheettömän uhrin tuoman Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Ja pitää laskeman kätensä uhrinsa pään päälle, ja teurastaman seurakunnan majan oven edessä: ja papit Aaronin pojat pitää priiskottaman veren alttarille ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Ja pitää uhraaman siitä kiitosuhrista polttouhrin Herralle: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Ja kaksi munaskuuta sen lihavuuden kanssa, kuin niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Aaronin pojat pitää polttaman sen alttarilla polttouhriksi puiden päällä, jotka ovat tulessa, tuliuhriksi ja lepytyshajuksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Mutta jos hän tekee Herralle kiitosuhria pienistä eläimistä, oinaista eli uuhista, niin sen pitää oleman ilman virheetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Jos hän uhraa karitsan, niin hänen pitää sen tuoman Herran eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'Ja pitää laskeman kätensä uhrinsa pään päälle, ja teurastaman sen seurakunnan majan oven edessä. Ja Aaronin pojat pitää priiskottaman sen veren alttarille ympärinsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Ja kiitosuhrista uhraaman Herralle polttouhrin, sen lihavuuden: koko saparon eroitetun selkäpiistä: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Ja kaksi munaskuuta sen lihavuuden kanssa kuin lanteissa niiden päällä on, ja eroittaman maksan kalvon munaskuiden kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Ja papin pitää sen polttaman alttarilla, tulen ruaksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Jos hänen uhrinsa on vuohi ja hän tuo sen Herran eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Niin hänen pitää laskeman kätensä sen pään päälle, ja teurastaman seurakunnan majan oven edessä. Ja Aaronin pojat pitää priiskottaman hänen verensä alttarille ympärinsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Ja pitää siitä uhraaman polttouhrin Herralle: lihavuuden, kuin sisällykset peittää, ja kaiken sisällysten lihavuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Ja kaksi munaskuuta lihavuuden kanssa, joka niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Ja papin pitää polttaman sen alttarilla, tulen ruaksi, makiaksi hajuksi. Kaikki lihavuus on Herran oma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne, kaikissa tiedän asuinsioissanne: ettette yhtään lihavuutta eli mitään verta söisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Puhu Israelin lapsille, ja sano: jos joku sielu rikkoo tietämätä jotakuta Herran käskyä vastaan, jota ei hänen pitäis tekemän, niin että hän tekis yhtäkin vastaan niistä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Jos pappi, joka voideltu on, rikkoo kansan pahennukseksi, niin hänen pitää rikoksensa edestä, kuin hän tehnyt on, tuoman virheettömän nuoren mullin Herralle rikosuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Ja pitää tuoman mullin Herran eteen, seurakunnan majan oven tykö, ja laskeman kätensä mullin pään päälle, ja teurastaman mullin Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Ja pappi kuin voideltu on, pitää ottaman mullin verestä, ja kantaman seurakunnan majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Ja papin pitää kastaman sormensa vereen ja priiskottaman sitä verta seitsemän kertaa Herran ja pyhän esiripun edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Ja papin pitää siitä verestä paneman suitsutusalttarin sarvein päälle, joka on Herran edessä seurakunnan majassa, ja kaiken muun veren kaataman polttouhrin alttarin pohjalle, joka on seurakunnan majan oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Ja kaiken rikosuhrin mullin lihavuuden pitää hänen ylentämän: nimittäin sen lihavuuden joka sisällykset peittää, ja kaiken sisällysten lihavuuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Ja kaksi munaskuuta sen lihavuuden kanssa, joka niiden päällä on lanteissa, ja maksan kalvon munaskuiden kanssa eroittaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Niinkuin ylennetään kiitosuhri härjästä: ja papin pitää sen polttaman polttouhrialttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Mutta mullin vuodan, kaiken lihan, pään ja jalkain kanssa, ja sisällykset ja ravan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Niin myös koko mullin pitää hänen leiristä viemän ulos puhtaaseen paikkaan, johonka tuhkat heitetään, ja se pitää poltettaman puiden päällä tulessa: juuri siinä paikassa, johon tuhka heitetään, pitää se poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Jos koko Israelin seurakunta eksyis, ja se olis heidän silmäinsä edessä peitetty, niin että he olisivat tehneet jotakuta Herran käskyä vastaan, jota ei heidän tulisi tehdä, ja niin tulisivat vikapääksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Ja sitte ymmärtäisivät rikoksensa, jonka he olivat tehneet, niin pitää heidän tuoman nuoren mullin rikosuhriksi, ja asettaman sen seurakunnan majan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Ja seurakunnan vanhimmat pitää laskeman kätensä mullin pään päälle Herran edessä, ja teurastaman mullin Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Ja pappi, joka voideltu on, pitää kantaman mullin veren seurakunnan majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Ja papin pitää kastaman sormensa vereen ja seitsemän kertaa priiskottaman Herran eteen, esiripun edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Ja pitää siitä verestä paneman altarin sarvein päälle, joka on Herran edessä seurakunnan majassa, ja kaiken sen muun veren kaataman polttouhrin alttarin pohjaan, joka on seurakunnan majan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Kaiken hänen lihavuutensa pitää hänen ylentämän ja polttaman alttarilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Ja pitää tekemän tämän mullin kanssa niinkuin hän teki rikosuhrin mullin kanssa: ja niin pitää papin heidät sovittaman, ja se heille annetaan anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Ja hänen pitää viemän mullin leiristä ulos, ja polttaman hänen, niinkuin hän poltti sen entisen mullin: sen pitää oleman rikosuhri seurakunnan edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Mutta jos päämies rikkoo ja tekee jotakuta Herran Jumalansa käskyä vastaan, jota ei hänen tekemän pitäisi, ja tulee tietämätä vikapääksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Ja osotetaan hänelle sitte hänen rikoksensa, jolla hän on rikkonut: hänen pitää tuoman uhriksi virheettömän kauriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Ja laskeman kätensä kauriin pään päälle, ja teurastaman siinä paikassa, kussa Herralle polttouhria teurastetaan: se pitää oleman hänen rikosuhrinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Sitte pitää papin ottaman rikosuhrin verta sormellansa, ja paneman sen polttouhrin alttarin sarvein päälle, ja sen muun veren kaataman polttouhrin alttarin pohjalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Mutta kaiken hänen lihavuutensa pitää hänen polttaman alttarilla, niinkuin sen lihavuuden kiitosuhrista. Ja niin papin pitää sovittaman hänen rikoksensa, ja se hänelle annetaan anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Jos joku sielu yhteisestä kansasta rikkoo tietämätä, niin että hän tekee jotakuta Herran käskyä vastaan, jota ei hänen tekemän pitäis, ja tulee niin vikapääksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Ja sitte saatetaan ymmärtämään rikoksensa, jolla hän on rikkonut: hänen pitää tuoman uhriksi virheettömän vuohen, sen rikoksen edestä, jolla hän rikkonut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Ja pitää laskeman kätensä rikosuhrin pään päälle ja teurastaman sen rikosuhrin polttouhrin paikalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Ja papin pitää sormellansa ottaman sen verta, ja paneman sen polttouhrin alttarin sarvein päälle, ja kaiken veren kaataman altarin pohjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Ja kaiken hänen lihavuutensa pitää hänen eroittaman, niinkuin hän eroitti kiitosuhrin lihavuuden: ja papin pitää sen polttaman alttarilla makiaksi hajuksi Herralle. Ja niin pitää papin häntä sovittaman, ja se annetaan anteeksi hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Mutta jos hän tuo lampaansa rikosuhriksi, niin tuokaan virheettömän uuhen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Ja laskekaan kätensä rikosuhrin pään päälle ja teurastakaan sen rikosuhriksi siinä paikassa, missä polttouhri teurastetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Ja papin pitää sormellansa ottaman rikosuhrin verta, ja paneman polttouhrin alttarin sarvein päälle, ja kaataman kaiken muun veren alttarin pohjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Mutta kaiken lihavuuden pitää hänen eroittaman niinkuin kiitosuhrin lampaan lihavuus eroitettiin, ja papin pitää polttaman sen alttarilla Herran tuleksi. Ja niin pitää papin hänen rikoksensa sovittaman, jolla hän on rikkonut, ja se hänelle annetaan anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Jos joku sielu rikkoo, niin että hän kuulee jonkun kiroilevan, ja hän on sen todistaja, eli on sen nähnyt taikka tietänyt, ja ei ilmoita siitä, hän on vikapää vääryyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Eli jos joku sielu rupee johonkuhun saastaiseen kappaleeseen, taikka saastaisen metsän eläimen raatoon, eli saastaisen karjan raatoon eli saastaisen madon raatoon, ja se olis hänelle tietämätöin: hän on saastainen ja vikapää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Eli jos hän rupee saastaiseen ihmiseen, millä ikänänsä saastaisuudella ihminen taitaa saastaiseksi tulla, tietämätä, ja sen sitte ymmärtää, se on vikapää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Eli jos joku sielu vannoo, niin että hänen suustansa käy ajattelemata pahoin eli hyvin tehdä, kaikki kuin ihminen vannoo huomaitsemata, ja sen sitte ymmärtää: hän on vikapää yhteen näistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Koska hän on vikapää johonkuhun näistä, ja tunnustaa, että hän siinä rikkonut on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Niin pitää hänen tämän rikoksensa vian edestä, kuin hän rikkonut on, tuoman laumasta Herralle uuhen eli vuohen rikosuhriksi: niin pitää papin sovittaman hänen rikoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Jollei hänellä ole lammasta, niin tuokaan Herralle rikoksensa edestä, jolla hän rikkonut on, kaksi mettistä eli kaksi kyhkyläisen poikaa: yhden rikosuhriksi, ja toisen polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Ja viekään ne papille: hänen pitää sen ensimäisen uhraaman rikosuhriksi ja vääntämän sen niskat ja ei kuitenkaan päätä erinänsä repäisemän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Ja pitää priiskottaman alttarin seinän rikosuhrin verellä, ja antaman sen veren, joka jää, vuotaa alttarin pohjaan. Se on rikosuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Toisen pitää hänen uhraaman polttouhriksi tavan jälkeen. Ja niin pitää papin sovittaman hänen rikoksensa, jolla hän rikkonut on, ja se annetaan hänelle anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Jollei hänelle ole kahta mettistä eli kahta kyhkyläisen poikaa, niin tuokaan uhrinsa, rikoksensa edestä, kymmenennen osan ephaa sämpyläjauhoja rikosuhriksi. Mutta ei hänen pidä öljyä sen päälle paneman, eikä pyhää savua; sillä se on rikosuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Ja hänen pitää sen viemän papille, ja papin pitää siitä ottaman pivon täyden muistoksi, ja polttaman sen alttarilla Herralle tuliuhriksi: tämä on rikosuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Ja papin pitää niin sovittaman hänelle hänen rikoksensa, jolla hän rikkonut on, ja se annetaan anteeksi hänelle. Ja sen pitää oleman papin oman niinkuin ruokauhrinkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Jos joku sielu kovasti rikkoo ja erehdyksestä syntiä tekee jossakussa joka Herralle pyhitetty on, hänen pitää Herralle tuoman vikauhrin, virheettömän oinaan laumasta, sinun arvios jälkeen hopiapainoon, pyhän siklin jälkee, vikauhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Siihen myös, mitä hän on rikkonut pyhitetyssä, pitää hänen sen antaman jällensä, ja pitää sen tykö antaman viidennen osan, ja antaman sen papille: ja papin pitää sovittaman hänen vikauhrin oinaalla, niin se hänelle annetaan anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Ja jos joku sielu rikkoo ja tekee vastoin jotakuta Herran käskyä, jota ei hänen pitänyt tekemän, ja ei sitä tietänyt: hän on vikapää vääryyteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Ja pitää tuoman papille virheettömän oinaan laumasta, sinun arvios jälkeen vikauhriksi: ja papin pitää sovittaman hänelle hänen tietämättömyytensä, kun hän tehnyt on tietämätä, niin se hänelle annetaan anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Se on vikauhri: sillä vikaan hän kaiketikin Herran edessä joutunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Jos joku sielu tekee syntiä ja rikkoo kovasti Herraa vastaan, kieltäen lähimmäiseltänsä sen, minkä hän hänen haltuunsa antanut on, eli sen, jonka hän hänelle (muutoin) käteen antanut on, taikka jonka hän väkivallalla ottanut on, eli vääryydellä on saattanut allensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Eli sen joka kadotettu oli, löytänyt on, ja kieltää sen väärällä valalla, eli mikä ikänänsä se olis, jossa ihminen lähimmäistänsä vastaan rikkoo;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Koska hän niin rikkoo ja tulee vikapääksi, niin pitää hänen antaman jällensä, mitä hän väkivallalla ottanut on ja vääryydellä on saattanut allensa eli sen mikä hänen haltuunsa annettu oli, eli kadotetun kuin hän löytänyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Eli jonka tähden hän väärän valan tehnyt on, sen pitää hänen kaikki tyynni antaman jällensä ja vielä sitte viidennen osan päälliseksi: sille, jonka se oma oli, pitää hänen sen antaman vikauhrinsa päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Mutta vikauhrinsa pitää hänen tuoman Herralle: virheettömän oinaan laumasta, sinun arvios jälkeen vikauhriksi, papin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Ja papin pitää sovittaman hänen Herran edessä, niin hänelle annetaan anteeksi, mitä ikänänsä se olis, kaikista niistä mitä hän tehnyt on, jossa hän itsensä vikapääksi saatti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Käske Aaronille ja hänen pojillensa sanoen: tämä on polttouhrin sääty: polttouhrin pitää palaman alttarilla kaiken yötä aamuun asti. Ja alttarilla tulen pitää sen päällä palaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Ja papin pitää yllensä pukeman liinahameen, ja vetämän liinaisen alusvaatteen ihonsa päälle, ja korjaaman tuhan alttarilta, sitte kuin tuli polttouhrin kuluttanut on, ja paneman sen alttarin viereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Ja sitte pitää riisuman vaatteensa, ja toisiin vaatteisiin itsensä pukeman, ja sitte tuhan viemän ulos leiristä puhtaaseen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Tuli pitää palaman alttarilla, ja ei koskaan sammuman. Ja papin pitää halot sen päällä joka aamu sytyttämän, ja hänen pitää asettaman polttouhrin sen päälle, ja polttaman kiitosuhrin lihavuuden sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Tuli pitää alinomaa palaman alttarilla, ja ei koskaan sammutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Ja tämä on ruokauhrin sääty, jonka Aaronin pojat uhraaman pitää alttarilla, Herran eteen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Papin pitää ottaman pivon täyden sämpyläjauhoja ruokauhrista, ja öljystä, ja kaiken pyhän savun, joka ruokauhrin päällä on, ja sen polttaman alttarilla lepytyshajuksi ja muistoksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Ja sen tähteet pitää Aaronin poikinensa syömän: happamatoinna pitää se syötämän, pyhässä siassa, seurakunnan majan pihassa pitää heidän sen syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Ja ei heidän pidä leipoman sitä hapatuksen kanssa; sillä se on heidän osansa, jonka minä heille minun tuliuhristani antanut olen: se pitää oleman kaikkein pyhin, niinkuin rikosuhri ja niinkuin vikauhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Jokainen miehenpuoli Aaronin lapsista pitää sen syömän. Se olkoon alinomainen sääty teidän sukukunnissanne Herran tuliuhrista. Jokainen kuin niihin rupee, se pitää pyhitetty oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Tämän pitää oleman Aaronin ja hänen poikainsa uhri, jonka heidän pitää uhraaman Herralle voidelluspäivänänsä: kymmenennen osan ephaa sämpyläjauhoja alinomaiseksi ruokauhriksi, puolen aamulla ja puolen ehtoolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Pannussa sinun sen tekemän pitää öljyn kanssa, ja sen kypsettynä tuoman: ja leivottuina kappaleina sinun sen uhraaman pitää, lepytyshajuksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Ja papin, joka hänen pojistansa hänen siaansa voideltu on, pitää sen tekemän. Tämä on ijankaikkinen sääty Herralle, se pitää kaikki poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Sillä kaikki papin ruokauhri pitää kokonansa poltettaman, ei sitä pidä syötämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Puhu Aaronille ja hänen pojillensa, ja sano: tämä on rikosuhrin sääty: kussa paikassa polttouhri teurastetaan, siinä pitää myös rikosuhri teurastettaman Herran edessä, ja se on kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Pappi, joka rikosuhria uhraa, pitää sen syömän: pyhällä sialla sen syötämän pitää, seurakunnan majan pihalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Kuka ikänänsä hänen lihaansa rupee, se pitää pyhitetty oleman, ja vaatteen, jonka päälle se veri priiskotetaan, pitää sinun pesemän pyhässä siassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Ja se saviastia, jossa se keitetään, pitää rikottaman. Jos se on vaskisessa padassa keitetty, niin se pitää hivutettaman, ja vedellä virutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Kaikki miehenpuolet papeista pitää syömän sen; sillä se on kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Mutta kaikki se rikosuhri, jonka veri viedään seurakunnan majaan, sovinnoksi pyhään siaan, sitä ei pidä syötämän, vaan tulella poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Ja tämä on vikauhrin sääty: se on kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Siinä paikassa, kussa polttouhri teurastetaan, pitää myös teurastettaman vikauhri, ja sen veri pitää priiskotettaman alttarille ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Ja kaikki sen lihavuus pitää uhrattaman, sekä häntä että lihavuus, joka sisällykset peittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Ja ne kaksi munaskuuta sen lihavuuden kanssa, joka niiden päällä on lanteissa: ja maksan kalvon munaskuiden kanssa pitää hänen eroittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Niin pitää papin sen polttaman alttarilla tuliuhriksi Herralle; se on vikauhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Jokainen miehenpuoli papeista pitää syömän sen; pyhässä siassa pitää se syötämän; sillä se on kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Niinkuin rikosuhri on, niin pitää myös vikauhrin oleman; sillä yhtäläinen pitää heidän molempain säätynsä oleman: ja se pitää sen papin oma oleman, joka sillä sovittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Sen papin, joka polttouhrin uhraa, pitää polttouhrin vuota oma oleman, jonka hän uhrannut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Ja kaikkinainen ruokauhri, joka pätsissä kypsetty on, ja kaikki kuin pannussa eli halstarilla valmistettu on, sen pitää papin oman oleman, joka sen uhraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Ja kaikkinainen ruokauhri, joka öljyllä sekoitettu, taikka kuiva on, sen pitää kaikkein Aaronin lasten oman oleman, yhden niinkuin toisenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Ja tämä on kiitosuhrin sääty, joka Herralle uhrataan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Jos he tahtovat tehdä ylistysuhria, niin heidän pitää uhraaman ylistysuhrin sivussa happamattomia leipiä, sekoitettuja öljyllä, ja happamattomia ohukaisia kyrsiä, voidelluita öljyllä, ja pannussa kypsetyitä sämpyläleipiä sekoitettuja öljyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Mutta senkaltaisia uhreja pitää heidän tekemän hapanneen kyrsän päälle, heidän kiitosuhrinsa ylistysuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Ja yksi kaikista niistä pitää uhrattaman Herralle ylennysuhriksi, ja sen pitää papin oman oleman, joka priiskottaa kiitosuhrin vereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Ja ylistysuhrin liha hänen kiitosuhrissansa pitää sinä päivänä syötämän, jona se uhrattu on, ja ei mitään pidä tähteeksi jätettämän huomeneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Mutta jos joku lupauksesta taikka hyvästä tahdosta uhraa, niin se pitää sinä päivänä syötämän, jona se uhrattu on; mutta jos jotakin tähteeksi jää uhrista toiseksi päiväksi, niin pitää se myös syötämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Mutta se mikä tähteeksi jää siitä uhrin lihasta, niin se kolmantena päivänä pitää poltettaman tulessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Mutta jos joku syö kolmantena päivänä siitä uhratusta lihasta, joka on hänen kiitosuhristansa, niin ei ole hän otollinen, joka sen on uhrannut, eikä se hänelle pidä luettaman, mutta se on kauhistus; ja jokainen sielu, joka sitä syö, on vikapää pahaan tekoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Mutta se liha, joka sattuu johonkuhun saastaisuuteen, ei pidä syötämän, mutta tulessa poltettaman. Joka puhdas on, se pitää syömän lihasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Ja se sielu, joka syö kiitosuhrin lihasta, siitä mikä Herran oma on, ja hänen saastaisuutensa on hänen päällänsä, se sielu pitää hävitettämän kansoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Jos joku sielu rupee johonkuhun saastaisuuteen, olkoon se saastainen ihminen eli saastainen eläin eli joku muu saastainen kauhistus, ja syö kiitosuhrin lihasta siitä mikä Herran oma on, se pitää hävitettämän kansoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Puhu Israelin lapsille, sanoen: ei teidän pidä mitään lihavuutta syömän härjistä, lampaista ja vuohista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Raadon eli haaskan lihavuus pantakoon kaikkinaisiin tarpeisiin: mutta ei teidän pidä sitä kaiketikaan syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Sillä joka syö lihavuutta siitä eläimestä, joka Herralle tuliuhriksi annettu on, se sielu pitää hävitettämän kansoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ei teidän pidä myös verta syömän kaikissa teidän asumasioissanne, ei linnuista, eikä eläimistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Jokainen sielu, joka syö jotain verta, se pitää hävitettämän kansoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Puhu Israelin lapsille, sanoen: se joka Herralle kiitosuhrinsa uhraa, hänen pitää tuoman, mikä Herralle kiitosuhriksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Mutta hänen pitää sen kantaman kädessänsä Herran tuliuhriksi: rinnan lihavuuden pitää hänen tuoman rinnan kanssa, että ne pitää oleman häälytysuhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Mutta papin pitää polttaman lihavuuden alttarilla, ja rinnan pitää Aaronin ja hänen poikainsa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Ja oikian lavan pitää teidän antaman papille ylennysuhriksi, teidän kiitosuhristanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Ja joka uhraa kiitosuhrin verta ja lihavuutta Aaronin pojista, hänen pitää saaman oikian lavan osaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Sillä häälytysrinnan ja ylennyslavan olen minä ottanut Israelin lapsilta heidän kiitosuhristansa, ja olen sen antanut papille Aaronille ja hänen pojillensa ijankaikkiseksi säädyksi, Israelin lapsilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Tämä on Aaronin ja hänen poikainsa voitelus Herran tuliuhrista, siitä päivästä, jona he Herralle papiksi annettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Jotka Herra käski sinä päivänä, jona hän heidän voiteli, annettaa heille Israelin lapsilta, ijankaikkiseksi säädyksi heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Ja tämä on sääty polttouhrista, ruokauhrista, rikosuhrista, vikauhrista, niin myös täytösuhrista ja kiitosuhrista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Jonka Herra Mosekselle käski Sinain vuorella; sinä päivänä, jona hän käskyn antoi hänelle Israelin lasten tykö, että heidän pitää uhraaman uhrinsa Herralle Sinain korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Ota Aaron poikinensa ja vaatteet, ja voidellusöljy: niin myös mulli rikosuhriksi, ja kaksi oinasta, ja myös kori happamattomia leipiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Ja kokoo kaikki kansa, seurakunnan majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Moses teki niinkuin Herra hänelle käskenyt oli: ja kokosi kansan seurakunnan majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Ja Moses sanoi kansalle: tämä on se minkä Herra on käskenyt tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Ja Moses otti Aaronin poikinensa, ja pesi heidät vedellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Ja puetti hänen yllensä hameen, ja vyötti hänen vyöllä ja puetti hänen ylishameella, ja pani päällisvaatteen hänen päällensä: niin myös vyötti hänen päällisvaatteen vyöllä, ja vaatetti hänen sillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Ja pani hänen päällensä rintavaatteen: ja pani rintavaatteen päälle valkeudet ja täydellisyydet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Ja pani hiipan hänen päähänsä: ja pani hiipan päälle hänen otsallensa kultaisen otsalehden, pyhän kruunun, niinkuin Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Ja Moses otti voidellusöljyn, ja voiteli majan ja kaikki mitä siinä oli: ja pyhitti ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Ja priiskotti sitä seitsemän kertaa alttarille, ja voiteli alttarin ja kaikki sen astiat, ja pesoastian jalkoinensa, ja pyhitti ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Ja kaasi voidellusöljyä Aaronin pään päälle, ja voiteli hänen ja pyhitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Ja Moses toi aaronin pojat, ja puetti heidän yllensä hameet, vyötti heidät vyöllä, ja sitoi lakit heidän päähänsä: niin kuin Herra hänelle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Ja antoi tuoda mullin rikosuhriksi ja Aaron poikinensa pani kätensä rikosuhrin mullin pään päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Ja teurasti sen. Ja Moses otti verestä, ja pani sormellansa alttarin sarviin ympärinsä, ja puhdisti alttarin, ja kaasi veren alttarin pohjalle, ja pyhitti sen, sovittaaksensa (kansaa) sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Ja otti kaiken sisällysten lihavuuden, ja maksan kalvon, ja molemmat munaskuut, ynnä lihavuuden kanssa, ja Moses suitsutti ne alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mutta mullin vuotinensa, lihoinensa ja sontinensa poltti hän tulessa ulkona leiristä, niinkuin Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Ja hän toi oinaan polttouhriksi, ja Aaron poikinensa panivat kätensä oinaan pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Ja se teurastettiin, ja Moses priiskotti hänen verensä alttarille ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Ja leikkasi oinaan kappaleiksi, ja Moses suitsutti pään ja kappaleet ja lihavuuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Ja pesi sisällykset ja jalat vedellä; ja Moses suitsutti koko oinaan alttarilla: se on polttouhri makiaksi hajuksi, se on tuliuhri Herralle, niinkuin Herra hänelle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Ja toi myös toisen oinaan, täytösuhrin oinaan, ja Aaron poikinensa pani kätensä oinaan pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Ja Moses teurasti sen ja otti hänen vertansa, ja sivui Aaronin oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Ja Moses toi myös Aaronin pojat, ja sivui verellä heidän oikian korvansa lehden, ja heidän oikian kätensä peukaloon, ja heidän oikian jalkansa isoon varpaaseen, ja Moses priiskotti veren alttarille ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Ja otti lihavuuden ja saparon ja kaiken sisällysten lihavuuden, ja maksan kalvon ja molemmat munaskuut heidän lihavuutensa kanssa, niin myös oikian lavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Hän otti myös korista, jossa happamattomat leivät olivat Herran edessä, yhden happamattoman kyrsän, ja öljyllä voidellun kyrsän, ja ohukaisen kyrsän, ja pani ne lihavuuden ja oikian lavan päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Ja antoi kaikki nämät Aaronin käsiin, ja hänen poikainsa käsiin, ja häälytti ne häälytykseksi Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Ja sitte otti Moses ne heidän käsistänsä ja poltti alttarilla polttouhrin päällä: se on täytösuhri lepytyshajuksi, se on tuliuhri Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Ja Moses otti rinnan ja häälytti sen häälytykseksi Herran edessä: täytösuhrin oinaasta sai Moses osan, niinkuin Herra hänelle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Ja Moses otti voidellusöljyä ja verta, joka oli alttarilla, ja priiskotti Aaronin ja hänen vaatettensa päälle, niin myös hänen poikainsa ja heidän vaatettensa päälle, ja pyhitti niin Aaronin ja hänen vaatteensa, niin myös hänen poikansa ja heidän vaatteensa hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Ja Moses sanoi Aaronille ja hänen pojillensa: keittäkäät lihaa seurakunnan majan oven edessä, ja syökäät se siinä paikassa, niin myös leipää, joka täytösuhrin korissa on, niinkuin minä käskin sanoen: Aaron poikinensa pitää ne syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Vaan mitä jää tähteeksi lihasta ja leivästä, sen teidän pitää polttaman tulessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Ja ei teidän pidä lähtemän seitsemänä päivänä seurakunnan majan ovesta, siihenasti, koska tiedän täytösuhrinne päivät täytetään; sillä seitsemänä päivänä teidän kätenne täytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Niinkuin se tänäpänä tapahtunut on, niin Herra on käskenyt tehtää, että te sovitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Ja teidän pitää oleman seitsemän päivää seurakunnan majan oven edessä, yli päivää ja yötä, ja teidän pitää ottaman vaarin Herran vartioista, ettette kuolisi; sillä niin on minulle käsketty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Ja Aaron poikinensa teki kaiken sen, kuin Herra Moseksen kautta käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Ja tapahtui kahdeksantena päivänä, että Moses kutsui Aaronin ja hänen poikansa, niin myös vanhimmat Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Ja sanoi Aaronille: ota sinulles nuori vasikka rikosuhriksi, ja oinas polttouhriksi, molemmat virheettömät, ja tuo Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Ja puhu Israelin lapsille, sanoen: ottakaat kauris rikosuhriksi, ja vasikka ja karitsa, molemmat vuosikuntaiset ja virheettömät, polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Ja myös härkä ja oinas uhrattaa kiitosuhriksi Herran edessä, ja ruokauhri sekoitettu öljyllä; sillä tänäpänä ilmestyy Herra teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Ja he toivat ne kuin Moses käskenyt oli, seurakunnan majan oven eteen: ja kaikki kansa kävi edes, ja seisoi Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Niin sanoi Moses: tämä on se, minkä Herra käskenyt on teidän tehdä, ja Herran kunnia ilmestyy teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Ja Moses sanoi Aaronille: astu alttarin tykö, ja tee rikosuhris, ja poltouhris ja sovita sinuas ja kansaa, ja tee sitte kansan uhri ja sovita heitä, niinkuin Herra käskenyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Ja Aaron astui alttarin tykö ja teurasti vasikan rikosuhriksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Ja Aaronin pojat kantoivat veren hänen tykönsä, ja hän kasti sormensa vereen, ja sivui alttarin sarviin, ja veren kaasi hän alttarin pohjalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Ja lihavuuden, ja munaskuut, ja maksan kalvon rikosuhrista, poltti hän alttarilla, niinkuin Herra oli Mosekselle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Mutta lihan ja nahan poltti hän tulessa ulkona leiristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Sitte hän teurasti polttouhrin, ja Aaronin pojat kantoivat veren hänen tykönsä, ja hän priiskotti sen alttarille ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Ja he toivat myös polttouhrin hänelle, kappaleiksi leikatun, ja pään, ja hän poltti ne alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Ja hän pesi sisällykset ja jalat, ja poltti ne polttouhrin päällä, alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Sitte kantoi hän kansan uhrin edes, ja otti kauriin, joka oli kansan rikosuhri, ja teurasti sen, ja teki siitä rikosuhrin, niinkuin sen entisenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Ja hän toi myös polttouhrin, ja valmisti sen tavan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ja toi ruokauhrin, ja otti siitä pivonsa täyden, ja poltti ne alttarilla, paitsi aamullista polttouhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Sitte teurasti hän härjän ja oinaan kansan kiitosuhriksi, ja Aaronin pojat kantoivat veren hänelle, ja hän priiskotti sen alttarin ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Mutta härjän lihavuuden, ja oinaan saparon, ja sisällysten lihavuuden, ja munaskuut, ja maksan kalvon:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Kaiken tämän lihavuuden panivat he rintain päälle, ja polttivat lihavuuden alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Mutta rinnat ja oikian lavan häälytti Aaron häälytykseksi Herran edessä, niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Ja Aaron nosti kätensä kansan puoleen, ja siunasi heitä: ja sittekuin hän rikosuhrin, polttouhrin ja kiitosuhrin tehnyt oli, meni hän alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Niin Moses ja Aaron menivät seurakunnan majaan, ja koska he jälleen sieltä läksivät, siunasivat he kansan. Niin Herran kunnia ilmestyi kaiken kansan edessä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Sillä tuli tuli Herralta alas, ja kulutti polttouhrin, ja sen lihavuuden, alttarilta: ja koska kaikki kansa sen näki, riemuitsivat he sangen suuresti, ja lankesivat maahan kasvoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Ja Aaronin pojat Nadab ja Abihu ottivat kumpikin suitsutusastiansa, ja panivat tulta niihin, ja panivat suitsutusta sen päälle: ja kantoivat vierasta tulta Herran eteen, jota ei hän heille ollut käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Silloin läksi tuli Herralta, ja kulutti heidät; niin että he kuolivat Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Niin sanoi Moses Aaronille: tämä on se kuin Herra puhunut on, sanoen: Minä pyhitetään niissä, jotka minua lähestyvät, ja kaiken kansan edessä minä kunnioitetaan. Ja Aaron oli ääneti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Mutta Moses kutsui Misaelin, ja Eltsaphanin, Usielin, Aaronin sedän pojat ja sanoi heille, tulkaat ja kantakaat teidän veljenne pyhän edestä: ulos leiristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Ja he tulivat ja kantoivat heidät hameinensa leiristä, niinkuin Moses oli sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Niin sanoi Moses Aaronille, ja hänen pojillensa Eleatsarille ja Itamarille: ei teidän pidä paljastaman teidän päätänne, eikä myös repimän teidän vaatteitanne, ettette kuolisi, ja ettei viha tulisi kaiken kansan päälle: mutta teidän veljenne koko Israelin huoneesta itkekään tätä paloa, jonka Herra sytyttänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Vaan ei teidän pidä menemän seurakunnan majan ovesta ulos, ettette kuolisi; sillä Herran voidellusöljy on teidän päällänne. Ja he tekivät Moseksen sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Ja Herra puhui Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Viinaa ja väkevää juomaa ei pidä sinun juoman, eikä sinun poikas sinun kanssa, koska te menette seurakunnan majaan, ettette kuolisi: se pitää oleman ijankaikkinen sääty teidän sukukunnillenne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Että te eroitatte mikä pyhä ja ei pyhä, mikä saastainen ja puhdas on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Ja että te opettaisitte Israelin lapsille kaikki oikeudet, kuin Herra heille Moseksen kautta puhunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Ja Moses puhui Aaronille ja hänen jääneille pojillensa Eleatsarille ja Itamarille: ottakaat se, joka tähteeksi jäänyt on ruokauhrista, Herran tuliuhrista, ja syökäät se happamattomana alttarin tykönä; sillä se on kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Ja teidän pitää sen syömän pyhällä sialla: sillä se on sinun oikeutes ja sinun poikais oikeus Herran tuliuhrista; sillä se on minulle niin käsketty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Mutta häälytysrinnan ja ylennyslavan pitää sinun ja sinun poikas ja tyttäres sinun kanssas syömän puhtaalla paikalla; sillä tämä oikeus on sinulle ja sinun pojilles annettu Israelin lasten kiitosuhrista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Sillä ylennyslapa ja häälytysrinta, lihavuus tuliuhrein kanssa, pitää kannettaman sisälle häälytettää häälytykseksi Herran edessä: sentähden pitää sen oleman sinulle ja sinun lapsilles ijankaikkiseksi säädyksi, niinkuin Herra käskenyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Ja Moses etsi ahkerasti rikosuhrin kaurista, ja katso, se oli poltettu: ja vihastui Eleatsarin ja Itamarin Aaronin jääneiden poikain päälle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Miksi ette ole syöneet rikosuhria pyhällä paikalla? sillä se on kaikkein pyhin, ja hän on antanut teille sen, että teidän pitää kantaman kansan rikokset, ja sovittaman heitä Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Katso, hänen verensä ei ole tuotu pyhään: teidän olis pitänyt kaiketi syömän sen pyhässä, niinkuin minulle käsketty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Mutta Aaron sanoi Mosekselle: katso, tänäpänä ovat he uhranneet rikosuhrinsa ja polttouhrinsa Herran edessä. Ja minulle on senkaltainen asia tapahtunut: ja pitäiskö minun tänäpänä syömän rikosuhrista, olisko se Herralle otollinen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Kun Moses sen kuuli, tyytyi hän siihen');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Puhukaat Israelin lapsille, sanoen: nämät ovat eläimet, joita te saatte syödä, kaikkein eläinten seassa maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Kaikista kaksisorkkaisista eläimistä, jotka sorkkansa kokonansa hajoittavat ja märhettivät, saatte te syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Kuitenkin tätä ette mahda syödä niistä, jotka märhettivät ja ovat kaksisorkkaiset, nimittäin: kameli, joka kyllä märhettii, vaan ei hajota sorkkiansa, se on teille saastainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Kaninit märhettivät, mutta ei ole kaksisorkkaiset, sentähden ne ovat teille saastaiset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Ja jänis myös märhettii, vaan ei ole kaksisorkkainen, sentähden se on teille saastainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Ja sika on kaksisorkkainen, joka kokonansa hajottaa sorkkansa, mutta ei märheti, sentähden se on teille saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Näiden lihaa ei teidän pidä syömän, eikä heidän raatoihinsa tarttuman; sillä ne ovat teille saastaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Näitä te saatte syödä kaikista niistä jotka vesissä ovat: kaikki, joilla on uimukset ja suomukset vesissä, meressä ja virroissa, niitä teidän pitää syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mutta kaikki, joilla ei ole uimuksia ja suomuksia meressä ja virroissa, kaikkein niiden seassa, jotka liikkuvat ja elävät vesissä, ne pitää oleman teille kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Ne ovat teitä kauhistavat: niiden lihaa ei teidän pidä syömän, kauhistukaat heidän raatoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Sillä kaikki, joilla ei ole uimuksia ja suomuksia vesissä, ne ovat teille kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Näitä te kauhistukaat linnuista, eikä teidän niitä pidä syömän, sillä ne ovat kauhistus: Kotka, ja luukotka ja kalakotka;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Kokkolintu, ja harakka lainensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Ja kaikki kaarneet lainensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Strutsi, pääskyinen, louve ja haukka lainensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Huhkaja, merimetsäs ja hyypiä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Yökkö, ruovonpäristäjä ja storkki;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Haikara ja mäkihaukka lainensa, puputtaja ja nahkasiipi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Ja kaikki, jotka liikkuvat lintuin seassa ja käyvät neljällä jalalla, pitää oleman teille kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Kuitenkin näitä saatte te syödä linnuista, jotka liikkuvat ja käyvät neljällä jalalla: joilla ovat sääret jalkain päällä, hypellä maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Ja näitä te saatte syödä heistä kuin on: arbe lainensa, ja selaam lainensa, ja hargol lainensa, ja hagab lainensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Vaan kaikki, jotka paitsi niitä ovat nelijalkaiset lintuin seassa, ne ovat teille kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Ja ne pitää teidän saastaisena pitämän; ja jokainen kuin tarttuu heidän raatoihinsa, sen pitää oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Ja jos joku heidän raatojansa kantaa, sen pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Ja jokainen eläin, joka on sorkallinen, vaan ei kaksisorkkainen, eikä märheti, ne ovat teille saastaiset; ja jokainen, kuin niihin tarttuu, pitää oleman saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Ja jokainen kuin käy kämmenellänsä kaikkein petoin seassa, jotka käyvät neljällä jalalla, ne ovat teille saastaiset; jokainen, kuin rupee heidän raatoihinsa, sen pitää oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Ja joka kantaa heidän raatojansa, se peskään vaatteensa, ja pitää oleman saastaisen ehtoosen asti; sillä kaikki nämät ovat saastaiset teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Ja nämät pitää oleman myös teille saastaiset niiden eläinten seassa, jotka matelevat maalla: myyrä, hiiri, maakrokodili, jokainen lainensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Stellio, kameleon, sisilisko, sinisisilisko ja salamandra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Nämät ovat teille saastaiset kaikkein niiden seassa, kuin matelevat; ja jokainen kuin rupee heihin sittekuin he kuolleet ovat, pitää oleman saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Ja kaikki, kuin senkaltainen raato päälle putoo pitää oleman saastainen, olis se kaikkinainen puuastia, eli vaate, eli nahka, eli säkki; ja kaikkinainen ase, jolla jotakin tehdään, pitää pantaman veteen, ja sen pitää oleman saastaisen ehtoosen asti, niin se tulee puhtaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Ja kaikkinaiset savi-astiat, joihinka senkaltainen raato putoo, ovat kaikki saastaiset, ja mitä niissä on, ja pitää rikottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Kaikki ruoka, jota syödään, jos se vesi tulee sen päälle, se on saastainen, ja kaikki juoma, jota juodaan senkaltaisista astioista, on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Ja kaikki, kuin senkaltainen raato päälle putoo, se tulee saastaiseksi, olis se pätsi eli kattila, se pitää rikottaman; sillä se on saastainen, ja sen pitää oleman teille saastaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Kuitenkin lähteet, kaivot ja lammikot ovat puhtaat; vaan jokainen, joka tarttuu heidän raatoonsa, sen pitää oleman saastaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Ja jos senkaltainen raato lankee siemenen päälle, joka kylvetty on, niin on se kuitenkin puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Ja jos vettä kaadetaan siemenen päälle, ja lankee joku senkaltainen raato niiden päälle, niin se tulee teille saastaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Ja jos joku eläin kuolee, jota teidän sopii syödä, se joka sen raatoon tarttuu, se on saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Se joka syö senkaltaista raatoa, hänen pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti, niin myös se, joka kantaa senkaltasia raatoja, pitää pesemän vaatteensa ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Kaikki maalla matelevainen pitää oleman teille kauhistava, ja ei pidä sitä syötämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Ja jokainen kuin vatsallansa käy, ja jotka käyvät neljällä eli useammalla jalalla, kaikista, jotka matelevat maalla, ei pidä teidän niitä syömän; sillä ne ovat kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Älkäät sielujanne kauhistavaiseksi tehkö kaikissa matelevaisissa, ja älkäät saastuttako teitänne niissä, niin että te tulette saastaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Sillä minä olen Herra teidän Jumalanne, sentähden teidän pitää pyhittämän teitänne, että te tulisitte pyhäksi; sillä minäkin olen pyhä. Ei teidän pidä saastuttaman teidän sielujanne jollakin matelevaisella eläimellä, joka matelee maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Sillä minä olen Herra, joka teidät johdatin Egyptin maalta, että minä olisin teidän Jumalanne, sentähden teidän pitää oleman pyhät; sillä minä olen pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Ja tämä on sääty kaikista eläimistä ja linnuista, ja kaikista, jotka vesissä liikkuvat, ja kaikkinaisista eläimistä, jotka maalla matelevat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Että tietäisitte eroittaa puhtaat saastaisista: ja mitä eläimiä syödä saadaan, ja mitä eläimiä ei sovi syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Puhu Israelin lapsille, ja sano: koska vaimo siittää ja synnyttä poikalapsen, niin hänen pitää seitsemän päivää oleman saastaisen, niinkauvan kuin hän kärsii sairauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Ja kahdeksantena päivänä pitää ympärileikattaman hänen esinahkansa liha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Mutta hänen pitää oleman kotona kolmeneljättäkymmentä päivää puhdistuksensa veressä; ei hänen pidä rupeeman yhteekään, mikä pyhä on, eikä hänen pidä pyhään tuleman, siihenasti kuin hänen puhdistuspäivänsä täytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Mutta jos hän synnyttää piikalapsen, niin hänen pitää saastaisen oleman kaksi viikkoa, niinkauvan kuin hän kärsii sairauttansa, ja kuusiseitsemättäkymmentä päivää pitää hänen kotona oleman puhdistuksensa veressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Mutta koska hänen puhdistuspäivänsä pojan eli tyttären jälkeen ovat täytetyt, niin tuokaan vuosikuntaisen karitsan polttouhriksi, ja kyhkyläisen pojan eli mettisen rikosuhriksi, papille seurakunnan majan oven eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Jonka ne pitää uhraaman Herran edessä, ja sovittaman hänen, niin hän puhdistuu verensä juoksusta. Tämä on sääty pojan eli tyttären synnyttämisestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Jos ei hänellä ole varaa karitsaan, niin ottakaan kaksi mettistä, eli kaksi kyhkyläisen poikaa, toisen polttouhriksi ja toisen rikosuhriksi. Ja niin papin pitää sovittaman hänen, että hän puhdistettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Jos ihmisen ihoon tulee ajos, eli rupi, eli syhelmä, niinkuin spitalitauti tahtois tulla hänen ihoonsa, niin pitää hän vietämän papin Aaronin tykö, eli yhden hänen pojistansa pappein seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Ja sitte kuin pappi näkee merkin ihossa, ja jos karvat merkissä ovat muuttuneet valkiaksi, ja haavan paikka on nähdä matalampi kuin muu iho hänen ruumiissansa, niin se on spitalitauti, sentähden pitää papin katseleman häntä ja tuomitseman hänen saastaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Mutta jos hänen ihossansa on valkea syhelmä, eikä kuitenkaan näy olevan syvemmällä muuta ihoa, ja karvat ei ole muuttuneet valkiaksi, niin pitää papin hänen sulkeman sisälle seitsemäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Ja seitsemäntenä päivänä katselkaan pappi häntä, jos haavat näkyvät hänessä olevan niinkuin ennekin, ja ei ole levinneet hänen ihossansa, niin papin pitää hänen jälleen toiseksi seitsemäksi päiväksi sulkeman sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Ja koska pappi taas katselee hänen toisena seitsemäntenä päivänä ja löytää haavat rauvenneeksi, eikä levinneeksi hänen ihossansa, niin pitää papin tuomitseman hänen puhtaaksi; sillä se on syhelmä: ja pitää pesemän vaatteensa, ja niin on hän puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mutta jos rupi leviää hänen ihossansa, sitte kuin hän on papilta katsottu ja puhtaaksi sanottu, niin hän pitää katsottaman toisen kerran papilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Jos siis pappi näkee, että ruvet ovat levinneet hänen ihossansa, niin pitää papin tuomitseman hänen saastaiseksi: se on spitali.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Mutta koska spitalin haava tulee ihmiseen, niin hän pitää vietämän papin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Ja koska pappi näke valkian ajoksen tulleeksi hänen ihoonsa, ja karvat vaalistuneeksi, ja elävän lihan olevan ajoksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Niin on vanha spitali hänen ihossansa, ja sentähden pitää papin tuomitseman häntä saastaiseksi, ja ei silleen sulkeman sisälle, sillä hän on jo saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Ja jos spitali kovin leviää hänen ihossansa, ja täyttää koko ihonsa, päästä niin jalkoihin, kaiken sen jälkeen, mitä pappi näkee silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Koska pappi katsoo ja näkee spitalin peittäneeksi koko hänen ihona, niin pitää hän tuomitseman hänen puhtaaksi, sentähden että kaikki on hänessä muuttunut valkiaksi; sillä hän on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mutta jona päivänä elävä liha hänessä näkyy, niin hän tuomitaan saastaiseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Ja pappi nähtyänsä elävän lihan, pitää hänen tuomitseman saastaiseksi; sillä elävä liha on saastainen, ja se on spitali.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mutta jos se elävä liha muuttuu jälleen valkiaksi, niin pitää hänen tuleman papin tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Ja koska pappi näkee haavat muuttuneen valkiaksi, niin papin pitää tuomitseman hänen puhtaaksi; sillä hän on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Ja jos jonkun ihoon tulee paisuma, ja paranee jälleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Ja sitte siihen siaan tulee jotakin valkiaa eli punaista rakkoa, se pitää katsottaman papilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Koska pappi näkee sen paikan matalammaksi muuta ihoa, ja karvat ovat muuttuneet valkiaksi, niin papin pitää hänen tuomitseman saastaiseksi; sillä siitä paisumasta on spitali tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mutta jos pappi näkee, ettei karvat ole siinä muuttuneet valkiaksi, ja ei ole matalampi kuin muukaan iho, ja se on kadonnut, niin papin pitää sulkeman hänen sisälle seitsemäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Mutta jos se paljo levenee hänen ihossansa, niin pitää papin tuomitseman hänen saastaiseksi; sillä se on spitalin haava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mutta jos se syhelmä pysyy siallansa, ja ei levitä itseänsä, niin se on paisuman arpi, ja papin pitää tuomitseman hänen puhtaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Ja jos jonkun iho tulee rupiin tulen poltteesta ja polton haavat ovat punaiset taikka valkiat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Ja pappi näkee sen karvat muuttuneeksi valkiaksi, siitä kuin palanut on, ja matalammaksi muuta ihoa, niin on spitali tullut siitä poltteesta: sentähden pitää papin tuomitseman hänen saastaiseksi; sillä se on spitalin haava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mutta jos pappi näkee, ettei karvat palaneessa ole muuttuneet valkiaksi, eikä matalammaksi ole tullut muuta ihoa, ja on siitä kadonnut, niin pitää papin sulkeman hänen sisälle seitsemäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Ja seitsemäntenä päivänä pitää papin katseleman häntä: jos se on paljo levinnyt hänessä, niin papin pitää tuomitseman hänen saastaiseksi; sillä se on spitali.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Mutta jos se on alallansa pysynyt palaneessa, eikä ole levinnyt hänen ihossansa, mutta on kadonnut, niin se on arpi palaneen jälkeen, ja papin pitää tuomitseman hänen puhtaaksi; sillä se on arpi palaneen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Jos mieheen eli vaimoon tulee syhelmä, päähän eli partaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Ja pappi katsoo sen ruven ja näkee sen matalammaksi muuta ihoa, ja karvat tulevat siitä paikasta keltaiseksi ja harvemmaksi, niin papin pitää tuomitseman sen saastaiseksi; sillä se on rupi, se on spitali päässä eli parrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Mutta jos pappi näkee, ettei se rupi ole matalampi muuta ihoa, ja karvat ei ole hänessä mustat, niin pitää papin sulkeman hänen, jolla rupihaava on, sisälle seitsemäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Ja koska pappi seitsemäntenä päivänä näkee, ettei rupi ole levinnyt ihossa, eikä ole keltaisia karvoja, ja ei ole rupi matalampi nähdä muuta ihoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Pitää hänen ajeleman itsensä, kuitenkin ettei hän ajele rupea ja papin pitää hänen, jolla rupi on, sulkeman sisälle toiseksi seitsemäksi päiväksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Ja koska pappi seitsemäntenä päivänä näkee ruven, ja löytää, ettei rupi ole levinnyt ihossa, ja ei ole matalampi muuta ihoa, niin papin pitää tuomitseman hänen puhtaaksi, ja hänen pitää pesemän vaatteensa, ja niin puhdas oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mutta jos rupi kovin levittää itsensä ihoon hänen puhdistuksensa jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Ja pappi näkee ruven levinneeksi ihossa, niin ei pidä papin silleen kysymän, jos karvat ovat keltaiset; sillä hän on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Jos se on silmäin edessä nähdä, että rupi on yhdellänsä ollut, ja siitä ovat mustat karvat käyneet ulos, niin rupi on parantunut, ja hän on puhdas: sentähden pitää papin hänen puhtaaksi sanoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Ja jos miehen eli vaimon ihoon tulee valkia syhelmä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Ja pappi näkee sen rauvenneeksi, niin on valkia rupi tullut hänen ihoonsa, ja hän on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Jos miehen hiukset päästä lähtevät, niin että hän tulee paljaspääksi, hän on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Ja jos ne etiseltä puolelta päätä lähtevät, niin hän on otsalta paljas, ja on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mutta jos joku valkea taikka punainen haava tulee paljaan päälle, niin on siihen spitali tullut paljaan pään eli otsan päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Sentähden pitää papin katsoman häntä, ja koska hän näkee valkian eli punaisen haavan tulleen paljaan pään eli otsan päälle, että se näkyy niinkuin muukin spitali ihossa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Niin hän on spitalinen ja saastainen mies, ja papin pitää kaiketi tuomitseman hänen saastaiseksi, senkaltaisen haavan tähden hänen päässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Joka spitalinen on, hänen vaatteensa pitää revityt oleman, ja pää avoin, suu peitetty, ja hänen pitää huutaman: saastainen! saastainen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Niinkauvan kuin haava hänessä on, pitää hänen saastainen oleman, yksinänsä asuman ja hänen asuinsiansa ulkona leiristä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Jos jonkun vaatteeseen tulee tulee spitalin haava, olkoon se lankainen eli liinainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Loimeen eli kuteesen, olkoon se liinainen eli villainen, elikkä nahkaan, elikkä kaikkinaiseen nahkavaatteeseen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Ja jos se haava kovin vihertyy, eli paljo punertuu vaatteessa, eli nahassa, eli loimessa, eli kuteessa, eli jossakussa kappaleessa, joka nahasta tehty on, se on spitalin haava; sentähden pitää papin häntä katsoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Ja koska pappi senkaltaisen haavan näkee, niin hänen pitää sen sulkeman sisälle seitsemäksi päiväksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Ja jos hän seitsemäntenä päivänä näkee että haava on levinnyt vaatteessa, loimessa eli kuteessa, nahassa, eli jossakussa kappaleessa joka nahasta tehty on, niin on se kuluttavainen spitali, ja se haava on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Ja hänen pitää vaatteet polttaman, loimen ja kuteen, eli mikä se olis, liinainen eli lankainen, eli kaikkinainen joka nahasta tehty on, jossa senkaltainen haava on; sillä se on kuluttavainen spitali, ja pitää tulessa poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Ja jos pappi näkee, ettei haava ole levinnyt vaatteessa, loimessa eli kuteessa, eli kaikkinaisessa kappaleessa joka nahasta on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Niin pitää papin käskemän pestä sen, jossa haava on, ja pitää hänen sulkeman sisälle jällensä toiseksi seitsemäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Ja koska pappi näkee haavan, sittekuin se pesty on, ettei haava ole muuttunut hänen silmäinsä edessä, eikä myös ole levinnyt, niin se on saastainen, ja pitää tulessa poltettaman; sillä se on syvälle itsensä laskenut, ja on sen paljaaksi kuluttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Jos pappi näkee, ette haava kadonnut on sittekuin se pestiin, niin hänen pitää sen repäisemän pois vaatteesta, nahasta, loimesta eli kuteesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Ja jos se vielä sitte näkyy vaatteessa, loimessa, kuteessa eli kaikkinaisessa nahkavaatteessa, niin se on pisama, ja se pitää poltettaman tulessa ynnä sen kanssa, jossa se haava on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Mutta vaate, loimi, kude, eli kaikkinainen nahkakalu, kuin pesty on, joista haava kadonnut on; se pitää vastuudesta pestämän ja puhdas oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Tämä on sääty spitalisesta ruvesta vaatteessa, liinaisessa, lankaisessa loimessa eli kuteessa, ja kaikkinaisessa nahkavaatteessa: niitä puhtaaksi eli saastaiseksi sanoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Ja tämä on spitalisen sääty: koska hän puhdistetaan, hän pitää tuotaman papin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Ja papin pitää käymän ulos leiristä, katselemaan häntä, jos spitalin haava on parantunut spitalisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Ja pappi käskekään sen, joka puhdistetaan, ottaa kaksi elävää puhdasta lintua, ja sedripuuta, ja tulipunaiseksi painettua villaa, ja isoppia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Ja pappi käskekään sen teurastaa yhden linnun saviastiassa, vuotavan veden tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Ja ottakaan elävän linnun sedripuun kanssa, tulipunalla painetun villan ja isopin, ja kastakaan tapetun linnun vereen, vuotavan veden tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Ja priiskottakaan spitalista puhdistettavan päälle seitsemän kertaa: ja niin puhdistakaan hänen, ja antakaan elävän linnun lentää kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Mutta puhdistettu peskään vaatteensa, ja ajelkaan kaikki hiuksensa, ja peskään itsensä vedessä ja niin on hän puhdas. Menkään sitte leiriin, kuitenkin asukaan ulkona majastansa seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Ja seitsemäntenä päivänä pitää hänen ajeleman kaikki hiukset päästänsä, ja partansa ja karvat silmäkulmistansa, niin että kaikki karvat ovat ajellut, ja pitää pesemän vaatteensa, ja pesemän ihonsa vedellä, niin on hän puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Ja kahdeksantena päivänä pitää hänen ottaman kaksi virheetöintä karitsaa, ja virheettömän vuosikuntaisen lampaan, niin myös kolme kymmenestä sämpyläjauhoja ruokauhriksi, öljyllä sekoitettuja, ja yhden login öljyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Niin pitää papin, joka puhdisti, asettaman puhdistetun ja tämän kalun, Herran eteen seurakunnan majan oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Ja papin pitää ottaman yhden karitsan, ja uhraaman vikauhriksi, öljylogin kanssa, ja pitää ne häälyttämäm häälytykseksi Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Ja sitte teurastaman karitsan sillä paikalla, kussa rikosuhri ja polttouhri teurastetaan, pyhässä siassa; sillä niinkuin rikosuhri, niin myös vikauhrikin on papin oma; sillä se on kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Ja papin pitää ottaman vikauhrin verta ja sivuman puhdistetun oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Ja papin pitää ottaman öljylogista ja vuodattaman papin vasempaan käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Ja papin pitää kastaman oikian kätensä sormen öljyyn, joka hänen vasemmassa kädessänsä on, ja priiskottaman öljyä sormellansa seitsemän kertaa Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Vaan käteensä jääneestä öljystä pitää papin paneman puhdistetun oikian korvan lehteen, ja oikiaan peukaloon, ja oikian jalan isoon varpaaseen, vikauhrin veren päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Käteensä jääneen öljyn, pitää papin paneman puhdistetun pään päälle, ja papin pitää sovittaman häntä Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Ja papin pitää tekemän rikosuhrin, ja sovittaman puhdistetun hänen saastaisuudestansa, ja sen jälkeen teurastaman polttouhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Ja papin pitää uhraaman polttouhrin ja ruokauhrin alttarilla, ja papin pitää sovittaman häntä, niin hän on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Jos hän on köyhä eikä ole hänellä varaa, niin ottakaan karitsan vikauhrinsa edestä häälytykseksi, sovittaakseen häntä, ja yhden kymmeneksen sämpyläjauhoja, sekoitetun öljyllä, ruokauhriksi, ja login öljyä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Ja kaksi mettistä eli kaksi kyyhkyläisen poikaa, jotka hän voi saada: toinen olkoon rikosuhriksi, ja toinen polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Ja kantakaan sen papille kahdeksantena päivänä puhdistukseksensa, seurakunnan majan oven eteen, Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Niin pitää papin ottaman vikauhrin karitsan, ja login öljyä, ja papin pitää ne häälyttämän häälytykseksi Herran edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Ja teurastaman vikauhrin karitsan, ja papin pitää ottaman vikauhrin verta, ja sivuman puhdistetun oikian korvan lehteen, niin myös oikian käden peukaloon, ja oikian jalan isoon varpaaseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Ja papin pitää vuodattaman öljyä papin vasempaan käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Ja papin pitää priiskottaman oikian käden sormella öljyä, joka on hänen vasemmassa kädessänsä, seitsemän kertaa Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Käteensä jääneestä öljystä pitää papin panenman puhdistetun oikian korvan lehteen, ja oikian käden peukaloon, ja oikian jalan isoon varpaaseen, vikauhrin veren päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Ja käteensä jääneen öljyn pankaan papin puhdistetun pään päälle, ja sovittakoon häntä Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Ja valmistakaan mettisiä, taikka kyhkyläisen poikia, jotka hän on voinut saada,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Nimittäin niitä, joita hän on voinut saada: yhden rikosuhriksi ja toisen polttouhriksi, ynnä ruokauhrin kanssa; ja niin pitää papin sovittaman puhdistetun Herran edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Tämä on sääty spitalisesta, joka ei voi saada sitä, mikä hänen puhdistukseensa tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Koska te tulette Kanaanin maalle, jonka minä annan teille omaisuudeksi, ja minä sen maan huoneesen spitalin haavan annan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Niin pitää sen tuleman, jonka huone on, ja ilmoittaman papille, sanoen: minun huoneessani näkyy niinkuin (spitalin) haava;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Niin pitää papin käskemän heidän lakaista huoneen, ennenkuin pappi siihen menee katsomaan haavaa, ettei kaikki, jotka huoneessa ovat, saastutettaisi: sitte pitää papin menemän katselemaan huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Koska hän näkee haavan, ja löytää, että huoneen seinissä viheriäiset ja punahtavat onnet ovat, ja ovat nähdä matalammat muuta seinää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Niin lähtekään pappi huoneen ovesta, ja sulkekaan huoneen kiinni seitsemäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Ja koska pappi seitsemäntenä päivänä palajaa ja näkee haavan itsensä levittäneeksi huoneen seiniin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Niin pitää papin käskemän heidän kangottaa ulos kiviä, joissa haava on, ja heittää niitä kaupungista ulos, saastaiseen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Ja huone pitää sisältä kaikki ympärinsä puhtaaksi kaavittaman, ja kaavittu savi heitettämän kaupungista ulos, saastaiseen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Ja heidän pitää ottaman toiset kivet, ja paneman niiden kivein siaan, ja ottaman toisen saven, ja sivuman huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Jos siis haava jällensä tulee, ja pakahtuu ulos huoneessa sittekuin kivet ovat kangotetut ulos, ja huone vastuudesta sivuttu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Niin pitää papin menemän sen sisälle, ja koska hän näkee haavan laskeneeksi itsensä leviämmälle huoneessa, niin on tosin kuluttuvainen spitali siinä huoneessa, ja se on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Sentähden pitää se huone särjettämän, sekä kivet että puut, ja kaikki savi huoneesta, ja vietävä kaupungista ulos, saastaiseen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Ja se joka käy huoneessa niinkauvan kuin se teljetty on, hänen pitää oleman saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Ja sen joka siinä huoneessa makaa, pitää vaatteensa pesemän, ja se joka syö siinä huoneessa, pitää vaatteensa pesemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Jos myös pappi menee ja näkee, ettei haava ole laskenut itseänsä leviämmelle huoneessa, sittekuin se sivuttu on, niin sanokaan sen puhtaaksi; sillä haava on parannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Ja pitää ottaman huoneen puhdistamiseksi kaksi lintua, niin myös sedripuuta, ja tulipunalla painetuita villoja, ja isoppia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Ja teurastaman toisen linnun savisessa astiassa, vuotavan veden tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Ja pitää ottaman sedripuun, ja isopin, ja tulipunalla painetuita villoja, ja elävän linnun, ja kastaman ne sen vereen, ja vuotavaan veteen, ja priiskottaman huoneen seitsemän kertaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Ja puhdistaman huoneen linnun verellä, ja vuotavalla vedellä, niin myös elävällä linnulla, sedripuulla, isopilla ja tulipunalla painetulla villalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Ja sitte päästäkään elävän linnun lentämään kaupungista kedolle, ja sovittakaan huoneen, niin se on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Tämä on kaikkinaisen spitalin ja syhelmän haavain sääty:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Vaatteen ja huoneen spitalin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Paisumain, pisamain ja putkenpolttamien,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Että pitää tiedettämän, mikä puhdas eli saastainen kunakin päivänä oleman pitää. Tämä on sääty spitalista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Puhukaat Israelin lapsille, ja sanokaat heille: koska miehellä on lihansa juoksu, on hän saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Ja silloin on hän saastainen siitä juoksusta, koska hänen lihansa juoksee taikka tulee tukituksi siitä vuotamisesta; niin se on saastaisuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Jokainen vuode, jossa hän lepää, jolla on juoksu, on saastainen, ja kaikki se, jonka päällä hän istuu, saastutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Ja se, joka sattuu hänen vuoteesensa, pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja pitää oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Se joka istuu sillä istuimella millä hän on istunut, jolla juoksu on, hänen pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Se joka sattuu hänen lihaansa, hän peskään vaatteensa, ja viruttakaan hänensä vedellä, ja olkaan saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Jos hän sylkee puhtaan päälle, niin se pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja oleman saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Ja koko se satula, jolla hän ajaa, pitää oleman saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Ja se joka sattuu johonkuhun siihen, joka hänen allansa on ollut, pitää saastaisen oleman ehtoosen asti, ja joka niitä kantaa, pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Ja johonka hän, jolla juoksu on, tarttuu, ennen kuin hän kätensä pesee vedellä, sen pitää vaatteensa pesemän ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Jos hän tarttuu saviseen astiaan, se pitää rikottaman; mutta puu-astia pitää vedellä virutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Ja tultuansa puhtaaksi lihansa juoksusta, pitää hänen lukeman seitsemän päivää puhdistuksestansa, ja pitää pesemän vaatteensa, niin myös viruttaman itsensä juoksevalla vedellä, niin hän on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Ja kahdeksantena päivänä pitää hänen ottaman parin mettisiä, eli kaksi kyhkyläisen poikaa, ja pitää tuoman Herran eteen seurakunnan majan ovella, ja antaman ne papille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Ja papin pitää ne uhraaman, yhden rikosuhriksi, ja toisen polttouhriksi, ja sovittaman hänen Herran edessä hänen juoksustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Koska miehestä siemen vuotaa unessa, hänen pitää pesemän koko ruumiinsa vedellä, ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Ja kaikki vaate, ja kaikki nahka, joka senkaltaisella siemenellä tahrattu on, pitää pestämän vedellä, ja oleman saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Ja vaimo, jonka tykönä senkaltainen mies makaa, jolla on siemenen juoksu, heidän pitää pesemän itsensä vedellä, ja oleman saastaiset ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Koska vaimolla on lihansa veren juoksu, pitää hänen erinänsä oleman seitsemän päivää, ja joka häneen sattuu, sen pitää saastaisen oleman ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Ja kaikki jonka päällä hän lepää, niinkauvan kuin hän erinänsä on, pitää oleman saastainen, ja kaikki, jonka päällä hän istuu, pitää oleman saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Ja se, joka hänen vuoteesensa sattuu, pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Ja joka tarttuu johonkuhun, jonka päällä hän on istunut, hänen pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Jos jotakin osaa olla sen vuoteessa, eli istuimella, kussa hän istuu, ja joku siihen tarttuu, hänen pitää oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Ja jos joku mies leväten lepää hänen tykönänsä, siihen aikaa kuin hänen aikansa tulee, hänen pitää oleman saastaisen seitsemän päivää, ja koko hänen vuoteensa, jossa hän levännyt on, pitää oleman saastaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Jos jonkun vaimon veren juoksu vuotaa kauvan aikaa, ei vaivoin niinkauvan kuin aika on, mutta myös ylitse sen ajan, hänen pitää oleman saastaisen niinkauvan kuin se vuotaa, niinkuin hänen oikialla vuotonsa ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Kaikki vuode, kussa hän lepää, niinkauvan kuin hän vuotaa, pitää oleman niinkuin oikian vuotonsa ajan vuode. Ja kaikki istuin, jonka päällä hän istuu, pitää oleman saastainen, niinkuin se hänen oikiana vuotamisensa aikana on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Se joka rupee johonkuhun niihin, hänen pitää oleman saastaisen, ja pitää pesemän vaatteensa, ja viruttaman itsensä vedellä, ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Koska hän on puhdas vuotamisesta, niin hänen pitää lukeman seitsemän päivää, ja sitte hänen pitää oleman puhtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Mutta kahdeksantena päivänä pitää hänen ottaman parin mettisiä eli kaksi kyhkyläisen poikaa, ja viemän papille, seurakunnan majan oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Ja papin pitää uhraaman yhden rikosuhriksi, ja toisen polttouhriksi, ja sovittaman hänen Herran edessä saastaisuutensa juoksusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Niin teidän pitää eroittaman Israelin lapsia heidän saastaisuudestansa, ettei he kuolisi saastaisuudessa, koska he minun majani saastuttavat, joka heidän seassansa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Tämä on sääty vuotamisesta, ja siitä, jolta (unessa) siemen vuotaa, niin että hän siitä tulee saastaiseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Ja siitä, jolla on veren juoksu, ja siitä, jolla joku vuotaminen on, miehestä eli vaimosta: ja koska mies lepää saastaisen tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Ja Herra puhui Mosekselle, sittekuin ne kaksi Aaronin poikaa kuolleet olivat; sillä uhratessansa Herran edessä kuolivat he.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Ja Herra sanoi Mosekselle: sano veljelles Aaronille, ettei hän joka aika mene sisimäiseen pyhään, sisälliselle puolelle esirippua armo-istuimen eteen, joka arkin päällä on, ettei hän kuolisi; sillä minä näytän minun pilvessä armo-istuimen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Mutta näiden kanssa pitää Aaronin käymän pyhään sisälle: hänen pitää ottaman nuoren mullin rikosuhriksi, ja oinaan polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Ja pitää pukeman pyhän liinahameen yllensä ja liinaisen alusvaatteen ihonsa päälle, ja vyöttämään itsensä liinaisella vyöllä, ja paneman liinahiipan päähänsä; sillä ne ovat pyhät vaatteet, ja pitää viruttaman ihonsa vedellä, ja ne pukeman päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Ja pitää ottaman Israelin lasten joukolta kaksi kaurista rikosuhriksi ja yhden oinaan polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Ja Aaronin pitää tuoman mullin rikosuhriksensa ja sovittaman itsensä huoneinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Ja sitte ottaman ne kaksi kaurista asettaaksensa Herran eteen, seurakunnan majan ovella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Ja Aaronin pitää heittämän arvan kahdesta kauriista: toisen arvan Herralle, ja toisen vapaalle kauriille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Ja Aaronin pitää uhraaman sen kauriin, jonka päälle Herran arpa lankesi, ja valmistaman sen rikosuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Mutta sen kauriin, jonka päälle vapauden arpa lankesi, pitää hänen asettaman elävänä Herran eteen, että hänen pitää sovittaman sen ja päästämän sen vapaan kauriin korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Ja niin pitää Aaronin tuoman rikosuhrinsa mullin, ja sovittaman itsensä ja huoneensa, ja teurastaman sen rikosuhrin mullin edestänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Ja ottaman astian täynnänsä tulisia hiiliä alttarilta, joka on Herran edessä, ja pivonsa täyden survottua Pyhää savua ja kantaman sisälliselle puolen esirippua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Ja paneman sitä tulen päälle Herran eteen, niin että pyhän savun suitsu armo-istuimen peittäis, joka on todistuksen päällä, ettei hän kuolisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Ja ottaman mullin verta, priiskottaaksensa sormellansa armo-istuimen puoleen, etiselle puolelle itään päin: seitsemän kertaa pitää hänen näin sormellansa armo-istuimen edessä verta priiskottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Sitte pitää hänen teurastaman kansan rikosuhrin kauriin ja kantaman hänen verestänsä esiripun sisälliselle puolelle, ja pitää tekemän sen veren kanssa, niinkuin hän teki mullin veren kanssa, ja priiskottaman sitä armo-istuimen päälle, ja armo-istuimen edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Ja niin sovittaman pyhän, Israelin lasten riettaudesta ja heidän vääryydestänsä, kaikissa heidän synneissänsä: niin pitää myös hänen tekemän seurakunnan majalle, joka on heidän tykönänsä, keskellä heidän saastaisuuttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Ei pidä yhdenkään ihmisen oleman seurakunnan majassa, koska hän käy sovittamaan pyhässä, siihenasti että hän sieltä käy ulos: ja pitää niin sovittaman itsensä, ja huoneensa, ja koko Israelin kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Ja koska hän menee ulos alttarin tykö, joka on Herran edessä, pitää hänen sovittaman sen ja ottaman mullin verta, ja kauriin verta, ja sivuman alttarin sarvein päälle ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Ja priiskottaman sormellansa verta seitsemän kertaa sen päälle ja puhdistaman ja pyhittämän sen Israelin lasten saastaisuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Ja koska hän on täyttänyt pyhän ja seurakunnan majan ja alttarin sovinnon, niin pitää hänen tuoman elävän kauriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Ja Aaronin pitää paneman molemmat kätensä elävän kauriin pään päälle, ja tunnustaman sen päällä kaikki Israelin rikokset ja heidän pahat tekonsa kaikissa heidän synneissänsä, ja ne paneman kauriin pään päälle, ja lähettämän sen jonkun soveliaan miehen kanssa korpeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Että kauriin pitää kantaman kaikki heidän pahat tekonsa erämaahan, ja hänen pitää jättämän kauriin korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Ja Aaronin pitää käymän seurakunnan majaan, ja riisuman liinavaatteet yltänsä, jotka hän ennen pukenut oli käydessänsä pyhään, ja jättämän ne sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Ja pitää pesemän ihonsa vedellä pyhässä siassa, ja pukeman yllensä omat vaatteensa, ja menemän ulos, ja tekemän sekä oman että kansan polttouhrin, ja niin sovittaman sekä itsensä että kansan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Ja polttaman rikosuhrin lihavuuden alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Vaan se, joka vei sen vapaan kauriin ulos, pitää viruttaman vaatteensa, ja pesemän ihonsa vedellä, ja sitte tuleman jällensä leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Ja rikosuhrin mullin ja rikosuhrin kauriin, joidenka veri kannettiin sovinnoksi pyhään, pitää vietämän leiristä ulos, tulessa poltettaa, sekä heidän nahkansa, lihansa ja rapansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Ja se joka niitä polttaa, pitää viruttaman vaatteensa, ja pesemän ihonsa vedellä, ja sitte tuleman leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Tämän pitää oleman teille ijankaikkisen säädyn: kymmenentenä päivänä seitsemäntenä kuukautena pitää teidän sielujanne vaivaaman, ja ei mitäkään työtä tekemän: olkoon se omainen, eli vieras, joka teidän seassanne muukalainen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Sillä sinä päivänä te sovitetaan, niin että tulette puhtaaksi: kaikista teidän synneistänne Herran edessä tulette te puhtaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sentähden pitää sen oleman teille suurimman sabbatin, ja teidän pitää vaivaaman teidän sielujanne: se olkoon teille alinomainen sääty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Mutta sovinnon pitää papin tekemän, joka voideltu on, ja jonka käsi täytetty on papin virkaan hänen isänsä siaan: ja pitää pukeman yllensä liinaiset vaatteet, jotka ovat pyhät vaatteet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Ja niin pitää hänen sovittaman kaikkein pyhimmän ja seurakunnan majan ja alttarin, niin myös papit, ja kaiken kansan pitää hänen sovittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Tämän pitää oleman teille alinomaisen säädyn, että sovitatte Israelin lapset kaikista heidän synneistänsä, kerran vuodessa. Ja hän teki niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Puhu Aaronille ja hänen pojillensa, ja kaikille Israelin lapsille, ja sano heille: tämä on se, minkä Herra käskenyt on, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Kuka ikänänsä Israelin huoneesta teurastaa härjän, eli karitsan, eli vuohen leirissä, taikka joka teurastaa ulkona leiristä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Ja ei kanna seurakunnan majan oven eteen sitä, mikä Herralle uhriksi pitää tuotaman, Herran majan eteen, hänen pitää vereen vikapää oleman, niinkuin se, jonka veren vuodattanut on, ja se ihminen pitää hävitettämän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Sentähden pitää Israelin lapset uhrinsa, jonka he kedolla uhrata tahtovat, Herran eteen kantaman seurakunnan majan ovella papille, ja siellä uhraaman ne kiitosuhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Ja papin pitää priiskottaman veren Herran alttarille seurakunnan majan oven edessä, ja polttaman lihavuuden Herralle lepytyshajuksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Ja ei millään muotoa enää uhriansa uhraaman ajattaroille, joiden kanssa he huorin tehneet ovat. Se pitää oleman heille heidän sukukunnissansa ijankaikkinen sääty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Sentähden pitää sinun sanoman heille: kuka ikänänsä ihminen Israelin huoneesta, eli vieras, joka teidän seassanne on muukalainen, teki uhrin eli polttouhrin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Eikä sitä kanna seurakunnan majan oven eteen, että hänen Herralle sen tekemän pitäis, se ihminen pitää hävitettämän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Ja kuka ikänänsä ihminen Israelin huoneesta, eli muukalaisista, jotka teidän seassanne asuvat, syö jotakin verta, häntä vastoin minä panen minun kasvoni, ja hävitän hänen kansastansa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Sillä lihan sielu on veressä, ja minä olen sen teille antanut alttarille, että teidän sielunne pitäis sen kautta sovitettaman; sillä veri on sielun sovinto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Sentähden minä olen sanonut Israelin lapsille: ei yksikään henki teidän seassanne pidä verta syömän: eikä yksikään muukalainen, joka teidän seassanne asuu, pidä verta syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Ja kuka ikänä ihminen Israelin lapsista, taikka muukalainen teidän seassanne, joka saa metsän eläimen eli linnun pyydyksellä, jota syödään, hänen pitää vuodattaman sen veren, ja peittämän sen multaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Sillä kaiken lihan henki on hänen verensä niinkauvan kuin se elää. Ja minä olen sanonut Israelin lapsille: ei teidän pidä yhdenkään lihan verta syömän; sillä kaiken lihan henki on hänen verensä: kuka ikänänsä sen syö, se pitää hukutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Ja kuka ikänä henki syö raatoa, taikka sitä, joka revitty on, olkoon hän kotolainen eli muukalainen, hänen pitää pesemän vaatteensa, ja viruttaman hänensä vedellä, ja oleman saastaisen ehtoosen asti: niin hän tulee puhtaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Jollei hän pese itsiänsä ja ihoansa viruta, niin hänen pitää itse kantaman vääryytensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Puhu Israelin lapsille, ja sano heille. Minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ei teidän pidä tekemän Egyptin maan työn jälkeen, jossa te asuitte, ei myös teidän pidä tekemän Kanaanin maan työn jälkeen, johonka minä tiedän vien, ei teidän myös pidä heidän säädyissänsä vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Vaan tehkäät minun oikeuteni, ja pitäkäät minun säätyni, vaeltaaksenne niissä; (sillä) minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Sentähden pitää teidän minun säätyni pitämän ja minun oikeuteni: se ihminen, joka niitä tekee, hän elää niissä; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ei kenenkään pidä lähimmäistä lankoansa lähestymän, hänen häpyänsä paljastaman; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Sinun isäs häpyä, ja äitis häpyä ei sinun pidä paljastaman. Se on sinun äitis, älä siis hänen häpyänsä paljasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Ei sinun pidä paljastaman isäs emännän häpyä; sillä se on isäs häpy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Sinun sisares häpyä, isäs tyttären, eli äitis tyttären, kotona taikka ulkona syntyneen, ei sinun pidä paljastaman heidän häpyänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Ei sinun pidä paljastaman poikas tyttären, eli tyttäres tyttären häpyä; sillä se on sinun häpys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Ei sinun pidä paljastaman äitipuoles tyttären häpyä, joka isälles syntynyt on; sillä se on sinun sisares.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Ei sinun pidä paljastaman isäs sisaren häpyä; sillä se on isäs lähimmäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Ei sinun pidä paljastaman äitis sisaren häpyä, sillä se on sinun äitis lähimmäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Ei sinun pidä paljastaman setäs häpyä, niin ettäs lähestyt hänen emäntäänsä; sillä se on sinun setäs emäntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Ei sinun pidä paljastaman miniäs häpyä; sillä hän on poikas emäntä, sentähden ei sinun pidä hänen häpyänsä paljastaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Ei sinun pidä paljastaman veljes emännän häpyä; sillä se on sinun veljes häpy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Ei sinun pidä sinun emäntäs ynnä hänen tyttärensä häpyä paljastaman, eikä hänen poikansa tytärtä, eli tyttären tytärtä ottaman, heidän häpyänsä paljastamaan; sillä ne ovat hänen lähimmäisensä, ja se on kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Ei sinun pidä myös ottaman sinun emäntäs sisarta, häntä vaivaamaan, hänen häpyänsä paljastamaan, vielä hänen eläissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Vaimon tykö, niin kauvan kuin hän saastaisuutensa sairautta kärsii, ei sinun pidä lähestymän, hänen häpynsä paljastamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Ei sinun pidä myös makaaman lähimmäises emännän tykönä, häneen ryhtymän, jolla itses häneen saastutat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Ei sinun pidä siemenestäs antaman Molekille poltettaa, ettes häpäisisi sinun Jumalas nimeä; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Ei sinun pidä miehenpuolen kanssa makaaman, niinkuin vaimon kanssa; sillä se on kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Ei sinun pidä myös eläimen kanssa makaaman, ettes itsiäs sen kanssa saastuttais. Ja ei yksikään vaimo pidä eläimeen ryhtymän, yhdistymään sen kanssa; sillä se on kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ei teidän pidä yhdessäkään näissä itsiänne saastuttaman; sillä näissä kaikissa ovat pakanat heitänsä saastuttaneet, jotka minä ajan pois teidän edestänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Ja maa on sillä saastutettu, ja minä etsiskelen sen pahat teot, niin että sen maan pitää asujansa oksentaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Sentähden pitäkäät minun säätyni ja oikeuteni, ja älkäät näistä kauhistuksista yhtäkään tehkö: ei omainen, eikä vieras, joka teidän seassanne muukalainen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Sillä kaikkia näitä kauhistuksia ovat tämän maan kansat tehneet, jotka teidän edellänne olivat, ja ovat maan saastuttaneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Ettei se maa myös teitä oksentaisi, jos te sitä saastutatte, niinkuin se on oksentanut kansan, joka teidän edellänne oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Sillä kuka ikänänsä näitä kauhistuksia tekee, sen sielu pitää hävitettämän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Sentähden pitäkäät minun käskyni, ettette tekisi kauhistavaisten tapain jälkeen, joita ne tekivät, jotka teidän edellänne olivat: ettette itsiänne niillä saastuttaisi; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Puhu koko Israelin lasten joukolle, ja sano heille: teidän pitää oleman pyhät; sillä minä olen pyhä, Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Jokainen peljätkään äitiänsä ja isäänsä, ja pitäkäät minun sabbatini; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ei teidän pidä teitänne kääntämän epäjumalain tykö, ja ei pidä teidän tekemän teillenne valetuita jumalia; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Ja koska te Herralle teette kiitosuhria, niin teidän pitää uhraaman, että se teiltä otollinen olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Ja se pitää syötämän sinä päivänä, jona te uhraatte, ja toisena päivänä; mutta mitä tähteeksi jää kolmanneksi päiväksi, pitää tulella poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Jos joku sitä kuitenkin syö kolmantena päivänä, niin on se kauhistus, eikä ole otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Ja joka siitä syö, sen pitää kantaman vääryytensä; sillä hän on Herran pyhän riivannut, ja se sielu pitää hävitettämän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Koska te elon leikkaatte maastanne, ei sinun pidä tyynni peltos kulmia leikkaaman, ja ei elos päitä noukkiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Ei pidä sinun myös tyynni korjaaman viinamäkiäs, eli noukkiman varisseita marjoja, vaan jättämän ne vaivaisille ja muukalaisille; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ei teidän pidä varastaman, eli valehteleman, eli pettämän toinen toistanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Ei teidän pidä väärin vannoman minun nimeeni, ja häpäisemän sinun Jumalas nimeä; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Ei sinun pidä tekemän lähimmäiselles vääryyttä, eli ryöväämän häntä. Sinun päivämiehes palkka ei pidä oleman sinun tykönäs huomiseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Ei sinun pidä kuuroja kirooman, ei sinun pidä myös paneman sokian eteen jotakin, johonka hän kompastuis. Vaan sinun pitää pelkäämän sinun Jumalaas; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ei teidän pidä vääryyttä tekemän tuomiossa, ei armaitseman köyhää, eikä kunnioitseman voimallista, mutta tuomitseman lähimmäises oikein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Ei sinun pidä oleman panettelian sinun kansas seassa. Ei sinun pidä myös asettaman sinuas lähimmäises verta vastaan; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Ei sinun pidä vihaaman veljeäs sinun sydämessäs; vaan sinun pitää kaiketi nuhteleman lähimmäistäs, ettes vikapääksi tulisi hänen tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Ei sinun pidä kostaman, eikä vihaaman kansas lapsia. Sinun pitää rakastaman lähimmäistäs, niinkuin itse sinuas; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Minun säätyni pitää teidän pitämän. Ei sinun pidä antaman karjas sekoittaa heitänsä muiden eläinten laihin. Ja älä kylvä peltoas sekoitetulla siemenellä. Ja ei yksikään vaate pidä tuleman sinun ylles, joka villaisesta ja liinaisesta kudottu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Jos mies makaa vaimon tykönä ja ryhtyy häneen, ja se on orja, ja jo on toiselta maattu, kuitenkaan ei ole irrallensa eli vapaaksi laskettu, se pitää suomittaman, vaan ei pidä heidän kuoleman, sillä ei hän ollut vapaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Mutta miehen pitää tuoman Herralle vikansa edestä oinaan vikauhriksi, seurakunnan majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Ja papin pitää sovittaman hänen vikauhrinsa oinaalla Herran edessä siitä rikoksesta, jolla hän on rikkonut; niin hänelle (Jumalalta) armo tapahtuu hänen rikoksestansa, jolla hän rikkonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Koska te tulette siihen maahan ja istutatte kaikkinaisia puita, joita syödään, pitää teidän leikkaaman pois niiden hedelmän esinahan: kolme vuotta pitää teidän pitämän heitä ympärileikkaamatoinna, niin ettette syö niistä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Vaan neljäntenä vuonna pitää kaikki heidän hedelmänsä pyhitettämän kiitokseksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Viidentenä vuonna pitää teidän hedelmän syömän, ja kokooman sisälle tulon; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ei teidän pidä mitään syömän veren kanssa. Ei teidän pidä totteleman aavistuksia eli taikauksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ei teidän pidä keritsemän paljaaksi päänne lakea ympärinsä, ja ei tyynni ajeleman partaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Ei teidän pidä leikkaaman ihoanne kuolleen tähden, eli piirusteleman kirjoituksia päällenne; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ei sinun pidä salliman tytärtäs porttona olla, ettei maa tottuisi haureuteen ja tulisi täyteen kauhistusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Pitäkäät minun pyhäpäiväni, ja peljätkäät minun pyhääni; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ei teidän pidä kääntämän teitänne tietäjäin tykö, ja älkäät kysykö velhoilta, ettette saastuisi heistä; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Harmaapään edessä pitää sinun nouseman, ja kunnioittaman vanhaa, ja pelkäämän Jumalaas; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Jos joku muukalainen on sinun tykönäs teidän maallanne asuva, ei teidän pidä sitä ryöstämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Hänen pitää asuman teidän tykönänne, niinkuin omainen teidän seassanne. Ja sinun pitää rakastaman häntä, niinkuin itse sinuas; sillä te olitte myös muukalaiset Egyptin maalla. Minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ei pidä teidän vääryyttä tekemän tuomiolla: kyynärällä, vaalla ja mitalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Oikia vaaka, oikia leiviskä, oikia vakka, oikia kannu pitää oleman teidän tykönänne; sillä minä olen Herra teidän Jumalanne, joka teitä olen johdattanut Egyptin maalta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Että teidän pitää pitämän ja tekemän kaikki minun säätyni, ja kaikki minun oikeuteni; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Ja Herra puhui Mosekselle; sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Sano myös Israelin lapsille: kuka ikänänsä Israelin lapsista, eli muukalaisista, joka Israelin lasten seassa asuu, siemenestänsä Molekille antaa, sen pitää totisesti kuoleman: maan kansan pitää häntä kivittämän kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Ja minä asetan minun kasvoni sitä ihmistä vastaan, ja hävitän hänen kansastansa, että hän Molekille siemenestänsä antanut ja minun pyhäni saastuttanut on, ja minun pyhää nimeäni häväissyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Ja jos maan kansa sitä ihmistä säästää, joka siemenestänsä Molekille antanut on, niin ettei he sitä surmaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Niin minä kuitenkin sitä ihmistä vastaan minun kasvoni asetan, ja hänen sukuansa vastaan, ja hävitän sen ja kaikki jotka hänen perässänsä Molekin kanssa huorin tehneet ovat, heidän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Jos joku sielu hänensä noitain ja tietäjäin tykö kääntää, huorin tekemään heidän kanssansa, niin minä kasvoni asetan sitä sielua vastaan, ja hävitän sen kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Sentähden pyhittäkäät teitänne, ja olkaat pyhät; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Ja pitäkäät minun säätyni, ja tehkäät niitä; sillä minä olen Herra, joka teitä pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Kuka ikänänsä isäänsä ja äitiänsä kiroo, sen pitää totisesti kuoleman, että hän isäänsä ja äitiänsä kironnut on: hänen verensä olkoon hänen päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Joka huorin tekee jonkun miehen aviopuolison kanssa, se joka lähimmäisensä emännän kanssa huorin tekee, pitää totisesti kuoletettaman, sekä huorintekiä, että huora.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Jos joku isänsä emännän tykönä makaa, niin että hän isänsä hävyn paljastanut on, he molemmat pitää totisesti kuoleman: heidän verensä olkoon heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Jos joku miniänsä tykönä makaa, niin he molemmat pitää totisesti kuoleman; sillä he ovat kauhistuksen tehneet: heidän verensä olkoon heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Jos joku miehenpuolen kanssa makaa, niinkuin jonkun vaimon kanssa, he ovat kauhistuksen tehneet, heidän pitää molemmat totisesti kuoleman: heidän verensä olkoon heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Jos joku nai vaimon ja sen äidin, hän on kauhistuksen tehnyt: se pitää tulella poltettaman, ja ne ynnä molemmat, ettei yhtään kauhistusta olisi teidän seassanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Jos joku eläimen kanssa makaa, sen pitää totisesti kuoleman, ja se eläin pitää tapettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Jos joku vaimo johonkuhun eläimeen ryhtyy, makaamaan sen kanssa, niin sinun pitää tappaman sekä vaimon, että eläimen; heidän pitää totisesti kuoleman: heidän verensä olkoon heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Jos joku sisarensa nai, isänsä eli äitinsä tyttären, ja hänen häpynsä näkee, ja se näkee hänen häpynsä, se on kauhistus: ne pitää hävitettämän sukunsa kansan edessä: sillä hän on sisarensa hävyn paljastanut, hänen pitää pahuutensa kantaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Jos joku mies jonkun vaimon tykönä makaa hänen sairautensa aikana, ja paljastaa hänen häpynsä, ja avaa hänen lähteensä, ja vaimo paljastaa verensä lähteen: ne molemmat pitää hävitettämän heidän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Sinun äitis sisaren häpyä ja sinun isäs sisaren häpyä ei sinun pidä paljastaman; sillä se on lähimmäisensä paljastanut, ja ne pitää pahuutensa kantaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Jos joku setänsä emännän kanssa makaa, hän on setänsä hävyn paljastanut: ne pitää rikoksensa kantaman. Lapsetonna heidän pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Jos joku veljensä emännän ottaa, se on häpiällinen työ: heidän pitää lapsetonna oleman, että hän on veljensä hävyn paljastanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Niin pitäkäät nyt kaikki minun säätyni, ja kaikki minun oikeuteni, ja tehkäät ne, ettei maa teitä oksentaisi, johon minä teidät vien asumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Ja älkäät vaeltako pakanain säädyissä, jotka minä teidän edeltänne olen ajava ulos; sillä kaikkia näitä he ovat tehneet, ja minä olen kauhistunut heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Mutta teille sanon minä: teidän pitää omistaman heidän maansa; sillä minä annan teille sen perimiseksi, sen maan, jossa rieskaa ja hunajaa vuotaa. Minä olen Herra teidän Jumalanne, joka olen teitä eroittanut muista kansoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Että teidän pitää myös eroittaman puhtaat eläimet saastaisista, ja saastaiset linnut puhtaista, ja ei saastuttaman teidän sielujanne eläimissä, linnuissa ja kaikissa, mitkä maalla matelevat, jotka minä teille eroittanut olen, että ne ovat saastaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Sentähden pitää teidän oleman minulle pyhät, sillä minä Herra olen pyhä, ja olen teitä eroittanut muista kansoista, että teidän pitäis oleman minun omani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Jos joku mies eli vaimo noidaksi eli tietäjäksi löydetään, ne pitää totisesti kuoleman, heidän pitää ne kivittämän, heidän verensä olkoon heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Ja Herra sanoi Mosekselle: puhu papeille Aaronin pojille ja sano heille: papin ei pidä itsiänsä saastuttaman yhdessäkään kuolleessa kansastansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Vaan hänen suvussansa, joka on hänen lähimmäisensä: niinkuin hänen äitinsä, isänsä, poikansa, tyttärensä ja veljensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Ja sisarensa, joka neitsy on, joka hänen tykönänsä on, ja ei yhdenkään miehen emäntänä ollut ole: niissä mahtaa hän saastuttaa itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Ei hänen pidä saastuttaman itsiänsä, että hän on esimies kansassansa, ettei hän itsiänsä halventaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ei heidän pidä paljaaksi ajeleman päälakiansa, eli keritsemään partansa vieriä, eikä ihoonsa merkkejä leikkaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Heidän pitää Jumalallensa pyhät oleman, ja ei häpäisemän Jumalansa nimeä; sillä he uhraavat Herran tuliuhria, Jumalansa leipää; sentähden pitää heidän oleman pyhät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Ei heidän pidä naiman porttoa, eli muilta maattua, eli mieheltänsä hyljättyä ottaman; sillä hän on pyhä Jumalallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Sentähden pitää sinun pyhittämän hänen, että hän uhraa sinun Jumalas leipää: hänen pitää oleman sinulle pyhän; sillä minä Herra olen pyhä, joka teidät pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Jos papin tytär rupee salavuoteiseksi, se pitää tulessa poltettaman; sillä hän on häväissyt isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Joka ylimmäinen pappi on veljeinsä seassa, jonka pään päälle voidellusöljy vuodatettu, ja käsi täytetty on, että hän vaatteesen puetetaan: ei pidä sen paljastaman päätänsä, ja ei leikkaaman rikki vaatettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Ja ei yhdenkään kuolleen tykö tuleman, ja ei saastuttaman itsiänsä isässänsä eli äidissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Ei hänen pidä lähtemän pyhästä, ettei hän saastuttaisi Jumalansa pyhää; sillä hänen Jumalansa voidellusöljyn kruunu on hänen päällänsä. Minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Hänen pitää ottaman neitseen emännäksensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Ja ei leskeä, eli hyljättyä, eli maattua, taikka porttoa pidä hänen ottaman. Mutta neitosen omasta kansastansa pitää hänen ottaman emännäksensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Ettei hän saastuttaisi siementänsä kansansa seassa; sillä minä olen Herra, joka hänen pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Puhu Aaronille ja sano: jos joku virhe on jossakussa sinun siemenessäs teidän suvussanne, ei pidä sen lähestymän uhraamaan Jumalansa leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Sillä ei kenenkään, jossa joku virhe on, pidä käymän edes: jos hän on sokia, eli ontuva, vajava eli liiallinen jäsenistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Eli virheellinen jalasta eli kädestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Taikka ryhäselkä, eli pienukainen, eli karsoi, eli pisamainen, taikka rupinen, eli rivinoma rauhaisista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Jos jossakin papin Aaronin siemenessä virhe on, ei sen pidä lähestymän uhraamaan Herran tuliuhria; sillä hänellä on virhe, sentähden ei pidä hänen lähestymän Jumalansa leipää uhraamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Kuitenkin pitää hänen syömän Jumalansa leivästä, sekä siitä pyhästä, että kaikkein pyhimmästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Mutta ei hänen pidä kuitenkaan tuleman esiripun tykö, eikä lähestymän alttaria, että hänessä on virhe, ettei hän saastuttaisi minun pyhääni; sillä minä olen Herra, joka heidät pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Ja Moses sanoi (nämät) Aaronille, ja hänen pojillensa, ja kaikille Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Puhu Aaronille ja hänen pojillensa, että he karttaisivat Israelin lasten pyhitettyä, joita he pyhittävät minulle, ja ettei he häpäisisi minun pyhää nimeäni; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sano siis heille ja heidän suvuillensa: jokainen kuin teidän siemenestänne menee pyhitetyn tykö, jonka Israelin lapset pyhittävät Herralle, ja hänen saastaisuutensa on hänessä, hänen sielunsa pitää hävitettämän minun kasvoini edestä; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Kuka ikänä Aaronin siemenestä on spitalinen eli vuotavainen, sen ei pidä syömän pyhitetyistä, ennen kuin hän puhdistetaan. Ja jos joku rupee johonkuhun saastaiseen ruumiisen, taikka siihen, joka siemenensä vuodattaa unessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Taikka se, joka rupee johonkuhun matelevaiseen, joka hänelle saastainen on, taikka ihmiseen, joka hänelle saastainen on, ja kaikkinaiseen, joka hänen saastuttaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Se sielu joka rupee johonkuhun niistä, pitää oleman saastainen ehtoosen asti, ja ei pidä syömän pyhitetyistä, vaan hänen pitää ensin viruttaman ruumiinsa vedellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Ja koska aurinko laskenut on, ja hän on puhdistettu, niin syökään sitte pyhitetyistä; sillä se on hänen ruokansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Raatoa ja mitä pedolta raadeltu on, ei hänen pidä syömän, ettei hän siitä saastutettaisi; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Sentähden heidän pitää pitämän minun säätyni, ettei heidän pitäisi syntiä saattaman päällensä, ja kuoleman siitä, koska he saastuttavat itsensä; sillä minä olen Herra, joka heitä pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Mutta ei yksikään muukalainen pidä syömän pyhitetyistä, eikä papin perhe, eikä myös joku palkollinen pidä syömän pyhitettyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Vaan koska pappi ostaa jonkun hengen rahallansa, se syökään siitä, ja se joka hänen huoneessansa syntynyt on, se myös syökään hänen leivästänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Ja jos papin tytär tulee jonkun muukalaisen emännäksi, niin ei hänen pidä syömän pyhitetystä ylennyksestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mutta jos papin tytär tulee leskeksi, eli hyljätyksi ja ei hänellä ole siementä, ja hän tulee jälleen kotia isänsä huoneeseen, niin hänen pitää syömän isänsä leivästä, niinkuin silloinkin, koska hän neitsenä oli. Mutta ei yksikään muukalainen pidä siitä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Ja jos joku syö pyhitetyistä tietämätä, hänen pitää lisäämän siihen viidennen osan, ja antaman papille pyhitetyn,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Ettei heidän pitäisi saastuttaman Israelin lasten pyhitettyjä, joita he ylentävät Herralle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Ettei he saattaisi rikosta ja vikaa päällensä, syödessänsä heidän pyhitetyistänsä; sillä minä olen Herra, joka heitä pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Puhu Aaronille ja hänen pojillensa, ja kaikille Israelin lapsille, ja sano heille: kuka ikänä Israelin huoneesta, eli muukalainen Israelissa, tahtoo uhrata, olkoon se lupauksesta, taikka vapaasta ehdosta, jota he tahtovat uhrata Herralle polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Että se hänelle olis otollinen teiltä, niin pitää sen oleman virheettömän härkyisen karjasta, oinaan karitsoista, eli kauriin vuohista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Mutta ei yhtäkään, jossa virhe on, pidä teidän uhraaman; sillä ei se ole hänelle otollinen teiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Jos joku tahtoo uhrata Herralle kiitosuhria, eli erinomaisesta lupauksesta, taikka vapaasta ehdosta, karjasta eli lampaista, sen pitää oleman virheettömän, että se olis otollinen: ei siinä pidä yhtään virhettä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Jos se on sokia, taikka raajarikko, taikka jäsenpuoli, taikka kuivettu, taikka rupinen, taikka köhnäinen, niin ei pidä teidän senkaltaisia Herralle uhraaman, ja ei pidä teidän tuliuhria niistä antaman Herran alttarille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Härjän eli lampaan, liiallisen eli puuttuvaisen jäsenistä, saat sinä uhrata vapaasta ehdostas; mutta ei se ole otollinen lupauksen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Eikä myös sinun pidä sitä Herralle uhraaman, mikä muserrettu, eli runneltu, eli revitty, eli haavoitettu on; ei teidän pidä sitä teidän maassanne tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Ei myös teidän pidä uhraaman jonkun muukalaisen kädestä teidän Jumalanne leipää kaikista niistä; sillä ne ovat turmellut ja virheelliset: ei ne ole otolliset teiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Koska vasikka, eli karitsa, eli vohla pojittu on, niin olkaan emänsä tykönä seitsemän päivää; mutta kahdeksantena päivänä, ja sen jälkeen, on se otollinen tuliuhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Olkoon se nauta, eli lammas, niin ei pidä se teurastettaman sikiöinensä yhtenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Koska te uhraatte Herralle kiitosuhria, teidän pitää sen niin uhraaman, että se teiltä otollinen olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Se pitää syötämän sinä päivänä, ja ei pidä mitään tähteeksi huomeneksi jätettämän; sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Sentähden pitäkäät minun käskyni ja tehkäät ne, sillä minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Ettette häpeäisi minun pyhää nimeäni, ja että minä pyhitettäisiin Israelin lasten keskellä; sillä minä olen Hera, joka teitä pyhitän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Ja joka olen teidät johdattanut Egyptin maalta, että minä olisin teidän Jumalanne: minä Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Puhu Israelin lapsille ja sano heille: nämät ovat Herran juhlat, jotka teidän pitää kutsuman pyhiksi kokouksiksi: ne ovat minun juhlani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Kuusi päivää pitää sinun työtä tekemän, vaan seitsemäntenä päivänä on se suuri sabbati, pyhä kokous, jona ei teidän pidä yhtään työtä tekemän; sillä se on Herran sabbati kaikissa teidän asuinsioissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Nämät ovat Herran juhlapäivät, pyhät kokoukset, jotka teidän pitää pitämän määrätyillä ajallansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Neljäntenätoistakymmenentenä päivänä ensimmäisenä kuukautena, kahden ehtoon välillä, on Herran pääsiäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Ja viidentenätoistakymmenentenä päivänä sinä kuukautena on Herran happamattoman leivän juhla: silloin pitää teidän syömän happamatointa leipää seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Ensimmäisenä päivänä olkoon teillä pyhä kokous, eikä yhtään raskasta työtä pidä teidän silloin tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Ja teidän pitää uhraaman Herralle tuliuhria seitsemän päivää. Seitsemäntenä päivänä on pyhä kokous. (Ja silloin myös) ei pidä teidän yhtäkään raskasta työtä tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Puhu Israelin lapsille, ja sano heille: koska te tulette sille maalle, jonka minä annan teille, ja te leikkaatte sen elon, niin teidän pitää viemän papille lyhteen teidän elostanne uutiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Ja sen lyhteen pitää hänen häälyttämän Herran edessä, että se olis otollinen teiltä: päivää jälkeen sabbatin pitää papin sen häälyttämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Ja teidän pitää sinä päivänä, jona teidän lyhteenne häälytetään, uhraaman virheettömän vuosikuntaisen karitsan polttouhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Ja ruokauhriksi kaksi kymmenestä sämpyläjauhoja, sekoitetut öljyllä, tuliuhriksi ja lepytyshajuksi Herralle, niin myös juomauhriksi neljännes hinni viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Ja ei pidä teidän syömän uudisleipää, kuivattua tähkäpäätä eli jyviä, siihen päivään asti, jona te kannatte teidän Jumalallenne uhrin. Sen pitää oleman ijankaikkisen säädyn teidän sukukunnillenne kaikissa teidän asuinsioissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Sitte pitää teidän lukeman toisesta sabbatin päivästä, koska te kannoitte häälytyslyhteen edes: seitsemän täysinäistä viikkoa ne pitää oleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Toiseen päivään asti, seitsemännen viikon jälkeen, (se on) viisikymmentä päivää pitää teidän lukeman, ja sitte uhraaman Herralle uutta ruokauhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Ja uhraaman kaikista teidän asumasioistanne kaksi häälytysleipää, kahdesta kymmeneksestä sämpyläjauhoja, hapatettuina pitää ne kypsettämän, Herranne uutiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Ja pitää tuoman teidän leipänne kanssa seitsemän vuosikuntaista ja virheetöintä karitsaa, ja yhden nuoren mullin, ja kaksi oinasta: sen pitää oleman Herran polttouhrin, ja heidän ruokauhrinsa ja juomauhrinsa, se on makian hajun tuli Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Niin myös pitää teidän valmistaman kauriin rikosuhriksi, niin myös kaksi vuosikuntaista karitsaa kiitosuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Ja papin pitää häälyttämän ne uudisleivän kanssa häälytykseksi Herran edessä, kahden karitsan kanssa. Ja pitää oleman Herralle pyhät, ja papin omat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Ja teidän pitää kuuluttaman tämän päivän: tämä pitää teille pyhä kokous oleman. Ei teidän pidä (silloin) yhtäkään raskasta työtä tekemän: ijankaikkisen säädyn pitää sen oleman teidän sukukunnissanne, kaikissa teidän asuinsioissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Koska te leikkaatte elon teidän maastanne, ei sinun pidä ylen tyynni peltos kulmia leikkaaman, eikä elon päitä noukkiman, vaan jättämän ne vaivaisille ja muukalaisille. Minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Puhu Israelin lapsille, ja sano: ensimäisenä päivänä seitsemäntenä kuukautena pitää teidän pitämän sabbatin, soittamisen muistoksi: se on pyhä kokous.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Silloin ei pidä teidän yhtään raskasta työtä tekemän, ja teidän pitää uhraaman tuliuhri Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Kymmenentenä päivänä tänä seitsemäntenä kuuna on sovintopäivä, se pitää oleman teille pyhä kokous: silloin vaivatkaat sielujanne, ja uhratkaat Herralle tuliuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Ja ei pidä teidän yhtään työtä tekemän sinä päivänä; sillä se on sovintopäivä, että te sovitettaisiin Herran teidän Jumalanne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Sillä jokainen sielu, jota ei sinä päivänä vaivata, pitää hävitettämän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Ja jokainen sielu, joka sinä päivänä jotakin työtä tekee, sen minä hukutan kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Sentähden ei pidä teidän (silloin) mitään työtä tekemän: sen pitää oleman ijankaikkisen säädyn teidän sukukunnillenne kaikissa teidän asuinsioissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Se on teidän suuri sabbatinne, ja teidän pitää vaivaaman sielujanne: yhdeksäntenä päivänä kuusta ehtoona pitää teidän pitämän tämän sabbatin, ehtoosta niin ehtoosen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Puhu Israelin lapsille, sanoen: viidentenätoistakymmenentenä päivänä tänä seitsemäntenä kuukautena on lehtimajan juhla, seitsemän päivää Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Ensimäisenä päivänä pitää oleman pyhä kokous: ei teidän pidä yhtään raskasta työtä (silloin) tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Seitsemän päivää pitää teidän uhraaman tuliuhria Herralle, kahdeksantena päivänä pitää teillä pyhä kokous oleman, ja teidän pitää tekemän tuliuhri Herralle; sillä se on päätöspäivä: ei pidä teidän yhtään raskasta työtä (silloin) tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Nämät ovat Herran juhlapäivät, jotka teidän pitää kutsuman pyhäksi kokoukseksi, ja uhraaman Herralle tuliuhria, polttouhria, ruokauhria, juomauhria, ja muita uhreja, jokaisen päivänänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Ilman Herran sabbatia, ja ilman teidän lahjojanne ja ilman kaikkia lupauksianne, ja ilman kaikkia mielellisiä antimianne, joita teidän pitää antaman Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Niin pitää nyt teidän viidentenätoistakymmenentenä päivänä seitsemäntenä kuukautena, koottuanne vuoden tulon maalta, juhlallisesti viettämän Herran riemujuhlaa, seitsemän päivää: ensimäisenä päivänä on sabbati, ja kahdeksantena päivänä on myös sabbati.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Ja teidän pitää ensimäisenä päivänä ottaman teillenne hedelmiä ihanasta puusta, palmun versoja, ja oksia paksu-oksaisista puista ja pajuja ojista, ja oleman riemuiset seitsemän päivää, Herran teidän Jumalanne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Ja pitää niin pitämän Herralle sitä riemujuhlaa vuodessa seitsemän päivää: sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne, että teidän niin pitää pyhää riemujuhlaa pitämän seitsemäntenä kuukautena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Seitsemän päivää pitää teidän asuman lehtimajoissa: joka omainen on Israelissa, hänen pitää asuman lehtimajoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Että teidän sukunne tietäisivät, kuinka minä olen antanut Israelin lapset asua majoissa, koska minä johdatin heitä Egyptin maalta: Minä Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Ja Moses sanoi nämät Herran juhlapäivät Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Käske Israelin lasten tuoda sinulle selkiää öljypuun öljyä, puserrettua ulos, valaistukseksi, joka aina pitää lampuissa sytytettynä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Ulkoiselle puolelle todistuksen esirippua seurakunnan majassa pitää Aaronin sen alati valmistaman, ehtoosta niin aamuun asti Herran edessä. Sen pitää oleman ijankaikkisen säädyn teidän sukukunnissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Ja hänen pitää valmistaman lamput puhtaasen kynttiläjalkaan, aina Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Ja sinun pitää ottaman sämpyläjauhoja ja leipoman niistä kaksitoistakymmentä kyrsää: kaksi kymmenestä pitää oleman joka kyrsässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Ja sinun pitää heidän paneman kahteen läjään, kuusi kumpaankin läjään, puhtaalle pöydälle Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Ja sinun pitää paneman niiden päälle puhdasta pyhää savua, että ne pitää oleman muistoleivät: se on tuliuhri Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Joka sabbatin päivänä pitää hänen aina valmistaman ne Herran edessä, Israelin lapsilta ijankaikkiseksi liitoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Ja ne pitää Aaronin ja hänen poikainsa omat oleman, heidän pitää ne syömän pyhässä siassa; sillä se on hänelle kaikkein pyhin Herran tuliuhreista ijankaikkiseksi säädyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Ja yhden Israelilaisen vaimon poika läksi ulos, joka Egyptiläisen miehen poika oli Israelin lasten seassa, ja se Israelilaisen vaimon poika riiteli toisen Israelilaisen kanssa leirissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Ja se Israelilaisen vaimon poika pilkkasi nimeä ja kirosi. Niin toivat he hänen Moseksen eteen, (ja hänen äitinsä nimi oli Selomit Dibrin tytär, Danin sukukunnasta).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Ja panivat hänen vankeuteen niinkauvaksi, että heille olis selkiä päätös annettu Herran suusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Vie häntä leiristä ulos, joka kiroillut on, ja anna kaikkein, jotka sen kuulivat, laskea kätensä hänen päänsä päälle, ja kaikki kansa kivittäkään häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Ja puhu Israelin lapsille, sanoen: kuka ikänä Jumalaansa kiroilee, hänen pitää kantaman syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Ja joka Herran nimeä pilkkaa, sen pitää totisesti kuoleman, kaiken kansan pitää häntä kuoliaaksi kivittämän. Niinkuin muukalaisen, niin pitää myös omaisen oleman: jos hän pilkkaa sitä nimeä, niin hänen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Jos joku lyö jonkun ihmisen kuoliaaksi, hänen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Vaan joka jonkun naudan lyö, hänen pitää maksaman hengen hengestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Ja joka tekee jonkun lähimmäisensä virheelliseksi, hänelle pitää niin tehtämän, kuin hänkin tehnyt on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Haava haavasta, silmä silmästä, hammas hampaasta; niinkuin hän on jonkun ihmisen virheelliseksi tehnyt, niin pitää myös hänelle jälleen tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Niin että joka lyö naudan, hänen pitää sen maksaman, vaan joka lyö ihmisen, sen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Yhden oikeuden pitää oleman teidän seassanne, niin muukalaisella kuin omaisellakin; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Koska Moses oli näitä puhunut Israelin lapsille, niin veivät he sen leiristä ulos, joka kiroillut oli, ja kivittivät hänen kuoliaaksi: ja Israelin lapset tekivät niinkuin Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Ja Herra puhui Mosekselle Sinain vuorella, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Puhu Israelin lapsille ja sano heille: koska te tulette siihen maahan, jonka minä teille annan, niin maan pitää pitämän Herralle lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Kuusi vuotta pitää sinun peltos kylvämän, ja kuusi vuotta viinamäkes leikkaaman, ja sen hedelmät kokooman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Mutta seitsemäntenä vuonna pitää maan pitämän Herralle suuren pyhän, jona ei sinun pidä kylvämän sinun peltoas taikka leikkaaman sinun viinamäkeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Ja mitä itsestänsä kasvaa laihostas, ei sinun pidä leikkaaman, ja viinamarjoja, jotka ilman sinun työtäs ovat kasvaneet, ei sinun pidä noukkiman; sillä se on maan lepovuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Mutta maan lepoa sinun pitää sentähdn pitämän, että sinun pitää siitä syömän, sinun palvelias ja piikas, niin myös päivämiehes, huonekuntaises, ja muukalaiset sinun tykönäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Ja sinun karjalles ja eläimilles sinun maallas kaikki, mitä siinä kasvaa, pitää oleman ruaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Ja sinun pitää lukeman sinulles seitsemän lepovuotta, niin että seitsemän vuotta pitää seitsemän kertaa luettaman: ja ne seitsemän lepovuoden aikaa tekee yhdeksän vuotta viidettäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Niin sinun pitää antaman soittaa basunalla ylitse koko teidän maakuntanne, kymmenentenä päivänä seitsemäntenä kuukautena: juuri sovintopäivänä pitää teidän antaman basunan käydä yli koko teidän maakuntanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Ja teidän pitää sen viidennenkymmenennen vuoden pyhittämän, ja pitää kuuluttaman vapauden maassa kaikille niille, jotka siinä asuvat; sillä se on teidän riemuvuotenne: silloin pitää itsekunkin pääsemän jälleen omaan saamaansa, itsekukin omaan sukuunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Sillä viideskymmenes vuosi on teidän riemuvuotenne: ei teidän pidä kylvämän, eikä leikkaaman itsestänsä kasvanutta, eikä myös hakeman niitä, mitkä ilman työtä kasvaneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Sillä se on riemuvuosi, se pitää pyhitettämän teiltä. Mutta teidän pitää syömän niitä kaikkia, mitä maa kantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Tämä on riemuvuosi, jona itsekunkin teistä pitää omaan saamaansa pääsemän jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Jos sinä jotakin myyt lähimmäiselles, taikka ostat jotakin häneltä, niin ei yhdenkään pidä pettämän veljeänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Vaan riemuvuoden luvun jälkeen pitää sinun ostaman lähimmäiseltäs, ja vuoden tulon jälkeen pitää hänen sinulle myymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Sitä usiammat kuin vuodet ovat, pitää sinun korottaman hinnan, ja sen harvemmat kuin vuodet ovat, pitää sinun alentaman hinnan; sillä vuoden tulon luvun jälkeen pitää hänen myymän sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Älkään kenkään pettäkö lähimmäistänsä, mutta pelkää sinun Jumalaas; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Sentähden tehkäät minun säätyni ja pitäkäät minun oikeuteni, että te ne teette, ja turvallisesti asutte maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Ja maan pitää antaman teille hedelmänsä, ja teillä pitää oleman kyllä syötävää, ja asuman pelkäämätä siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Ja jos te sanotte: mitä meidän pitää syömän seitsemäntenä vuonna? katso, ei meidän pidä kylvämän, eikä vuoden tuloa kokooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Niin minä käsken minun siunaukseni tulla kuudentena vuotena teidän ylitsenne, niin että sen pitää tekemän teille kolmen vuoden tulon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Ja teidän pitää kylvämän kahdeksantena vuonna, ja vanhasta vuoden kasvusta syömän yhdeksänteen vuoteen asti, niin että te syötte vanhasta uutiseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Sentähden ei teidän pidä maata peräti myymän; sillä maan on minun, ja te olette muukalaiset ja vieraat minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Ja teidän pitää koko teidän omassa maassanne antaman maan lunastettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Jos sinun veljes köyhtyy, ja myy sinulle omaisuudestansa, ja hänen lähimmäinen lankonsa tulee hänen tykönsä, ja tahtoo lunastaa, niin pitää hänen lunastaman sen, minkä hänen veljensä myynyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Ja jos joku on, jolla ei yhtään lunastajaa ole, ja taitaa niin paljo matkaan saada, kuin sen lunastukseksi tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Niin pitää luettaman vuosiluku sittenkuin hän myi, ja annettaman hänelle, joka myi, mitä liiaksi on, että hän tulis omaisuuteensa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mutta jos ei hän takaansa löydä niin paljo että hän sais sen jälleen, niin pitää sen, minkä hän myynyt on, oleman ostajan kädessä riemuvuoteen asti; niin hänen pitää oleman vapaan ja saaman omansa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Se joka myy asuttavan huoneen kaupungin muurin sisältä, hänellä on vapaa ehto ajastajassa, sitä lunastaa jällensä: ja sen pitää oleman ajan, jolla hän lunastaa sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Ja jos ei hän lunasta sitä koko ajastajassa, niin pitää ostajan sen huoneen kaupungin muurin sisältä pitämän ijankaikkisesti ja hänen sukunsa, ja ei pidä vapaaksi tuleman ilovuotena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mutta jos huone on maan kylässä, kussa ei yhtään muuria ympärillä ole, niin se pitää luettaman peltomaaksi: se lunastetaan ja tulee ilovuotena vapaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Leviläisten kaupungit ja huoneet kaupungeissa, joissa heidän tavaransa ovat, saavat he aina lunastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Se joka jotakin lunastaa Leviläisiltä, hänen pitää siitä luopuman ilovuonna, olkoon se ostettu huone eli omaisuus kaupungissa, jossa hän asunut on; sillä huoneet Leviläisten kaupungeissa ovat heidän omaisuutensa Israelin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Mutta maata heidän kaupunkeinsa ympäriltä ei pidä myytämän; sillä se on heidän saamansa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Jos veljes köyhtyy ja tulee voimattomaksi tykönäs, niin sinun pitää pitämän hänen ylös, niinkuin muukalaisen, taikka huonekuntaisen, että hän eläis sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Ja ei sinun pidä ottaman korkoa eli voittoa häneltä; vaan pelkää sinun Jumalaas, että sinun veljes sais elää sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Ei sinun pidä antaman rahaas hänelle korolle, eikä antaman viljaas kasvulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Sillä minä olen Herra teidän Jumalanne, joka teidän johdatin Egyptin maalta, antaakseni teille Kanaanin maan, ja ollakseni teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Jos veljes köyhtyy sinun tykönäs, ja myy itsensä sinulle, niin ei sinun pidä häntä pitämän niinkuin orjaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Mutta hänen pitää oleman sinun tykönäs niinkuin päivämiehen, eli huonekuntaisen, palvellen sinua riemuvuoteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Silloin pitää hänen käymän ulos vapaana sinun tyköäs lapsinensa, ja pitää tuleman sukunsa tykö jälleen, ja isäinsä saaman päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Sillä he ovat minun palveliani, jotka minä Egyptin maalta johdattanut olen: sentähden ei pidä heitä orjan tavalla myytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Ei sinun pidä ankarasti heitä hallitseman, vaan pelkäämän sinun Jumalaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Jos tahdot pitää orjaa ja piikaa, niin sinun pitää ostaman ne pakanoilta, jotka teidän ympärillänne ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Ja huonekuntalaisilta, jotka muukalaiset ovat teidän seassanne, pitää teidän ne ostaman, ja heidän suvuiltansa, jotka he teidän tykönänne teidän maassanne synnyttäneet ovat: ja ne pitää teidän omanne oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Ja pitäkäät heitä omananne, ja teidän lapsillenne teidän jälkeenne ijankaikkiseksi perimiseksi, ja niiden pitää oleman teidän orjanne; mutta veljenne Israelin lapset ei pidä toinen toistansa ankarasti hallitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Jos muukalainen eli huonekuntainen hyötyy sinun tykönäs, ja sinun veljes köyhtyy hänen tykönänsä, niin että hän myy itsensä muukalaiselle, joka huonekuntainen sinun tykönäs on, eli jollekulle muukalaisen suvusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Niin pitää hänellä oikeus oleman lunastettaa jälleen sittekuin hän myyty on, että joku hänen veljistänsä pitäis hänen lunastaman jällensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Eli hänen setänsä eli setänsä poika lunastakaan hänen, taikka joku hänen lähimmäisestä suvustansa, eli jos hän itse taitaa niin paljo matkaan saada, niin pitää hänen lunastaman itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Ja hänen pitää lukua laskeman ostajansa kanssa, siitä vuodesta kuin hän myi itsensä ilovuoteen asti, ja raha pitää luettaman vuoden luvun jälkeen, sittekuin hän myytiin, ja kaiken sen ajan palkka pitää siihen luettaman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Ja jos vielä monta vuotta on ilovuoteen, niin hänen pitää sitä enemmän antaman lunastuksestansa, senjälkeen kuin hän ostettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Mutta jos harvat vuodet ovat ilovuoteen, niin laskekaan lukua hänen kanssansa ja hänen pitää vuotten jälkeen antaman lunastuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Ja pitää hänen palkkansa myös siihen luettaman vuosi vuodelta, ja ei hänen pidä ankaruudella häntä hallitseman sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Jos ei hän näin lunasta itsiänsä, niin hänen pitää ilovuonna vapaana käymän ulos lapsinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Sillä Israelin lapset ovat minun palveliani; he ovat minun palveliani, jotka minä olen Egyptin maalta johdattanut ulos: Minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ei teidän pidä tekemän teillenne epäjumalia, ei kuvia, eikä myös patsaita pystyttämän teillenne, eikä myös yhtään merkkikiveä paneman teidän maallanne, kumartaaksenne niitä; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Pitäkäät minun sabbatini, ja peljätkäät minun pyhyyttäni: Minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Jos te säädyissäni vaellatte, ja minun käskyni kätkette, ja teette ne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Niin minä annan teille sateen ajallansa, ja maa antaa kasvunsa, ja kedon puut antavat hedelmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Ja riihen aika ulottuu viinan uutiseen asti, ja viinan uutinen ulottuu toukoaikaan asti, ja teillä pitää oleman leipää viljalta, ja saatte asua levollisesti teidän maassanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Ja minä annan rauhan teidän maallenne, ja te saatte levätä, ja ei kenkään teitä peljätä, ja minä ajan pahat pedot teidän maaltanne pois, ja miekan ei pidä käymän teidän maanne lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Teidän pitää vihollisianne ajaman takaa, ja heidän pitää kaatuman miekkaan teidän edessänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Viisi teistä karkottaa sata, ja sata teistä karkottaa kymmenentuhatta, ja teidän vihollisenne pitää kaatuman teidän edessänne miekkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Ja minä käännän minuni teidän puoleenne, ja teen teidät hedelmälliseksi ja lisään teitä, ja vahvistan minun liittoni teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Ja te saatte syödä sitä vanhaa, joka vanhenee, ja vanhat te hylkäätte uuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ja minä panen asumasiani teidän keskellenne, ja minun sieluni ei hyljää teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Ja minä vaellan teidän keskellänne ja olen teidän Jumalanne, ja teidän pitää oleman minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Sillä minä olen Herra teidän Jumalanne, joka johdatin teidät ulos Egyptin maalta, ettei teidän pitänyt oleman heidän orjansa. Minä olen taittanut poikki ikeenne vehmerän, ja olen antanut tiedän käydä pystyällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mutta jos ette kuule minua, ettekä tee kaikkia näitä käskyjä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Vaan suututte säätyihini, ja teidän sielunne hyljää minun oikeuteni, ettekä tee kaikkia minun käskyjäni, ja rikotte minun liittoni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Niin minä teen teille nämät: minä rankaisen teitä vavistuksella, kuivataudilla, ja poltetaudilla, josta kasvonne raukeevat ja ruumiinne nääntyvät: ja teidän pitää siemenenne kylvämän turhaan, ja teidän vihollistenne pitää syömän sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Ja minä asetan kasvoni teitä vastaan, ja te lyödään vihamiehiltänne, ja ne pitää hallitseman teitä, jotka teitä vihaavat, teidän pitää myös pakeneman, koska ei kenkään teitä aja takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Jollette vielä sittekään kuule minua, niin minä lisään sen seitsemän kertaa, rangaistakseni teitä synteinne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Ja minä särjen teidän ylpeytenne uppiniskaisuuden, minä teen teidän toivonne niinkuin raudan, ja teidän maanne niinkuin vasken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Ja teidän voimanne pitää hukkaan kulutettaman, niin ettei teidän maanne kasvoansa anna, eikä puut maalla hedelmäänsä anna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Ja jos te vielä minua vastaan vaellatte, ettekä tahdo kuulla minua, niin minä vielä sitte lisään rangaistuksen teidän päällenne seitsemän kertaa, teidän synteinne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Ja lähetän teidän sekaanne metsän pedot syömään lapsianne, ja karjaanne raatelemaan, ja vähentämään teitä, ja teidän tienne pitää autioksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Jollette vielä niillä anna kuritettaa teitänne, mutta käytte minua vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Niin minä myös käyn teitä vastaan, ja lyön teitä vielä seitsemän kertaa enemmin, teidän synteinne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Ja saatan päällenne kostomiekan, joka minun liittoni pitää kostaman, että te kokootte teitänne teidän kaupunkeihinne: sitte minä lähetän teidän sekaanne ruttotaudin, ja annan teitä vihamiestenne käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Ja minä hukutan teiltä leivän aineen, niin että yhdessä pätsissä kymmenen vaimoa leipänne kypsentävät, ja punnitsevat leipänne vaalla: ja syötyänne ette tule ravituksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Ja jollette vielä sitte kuule minua, mutta vaellatte minua vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Niin minä myös hirmuisuudessa vaellan teitä vastaan, ja minä rankaisen teitä seitsemän kertaa enemmin, teidän synteinne tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Että teidän pitää syömän poikainne ja tytärtenne lihaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Ja minä kukistan teidän kukkulanne ja hävitän teidän kuvanne, ja panen teidän raatonne epäjumalainne raatoin päälle, ja minun sieluni kuoittaa teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Ja teen kaupunkinne autioiksi ja kirkkonne hävitän, enkä myös teidän lepytyshajuanne haista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Ja minä tahdon hävittää maan, niin että vihollisenne, jotka siinä asuvat, pitää siitä hämmästymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Ja hajoitan teitä pakanain sekaan, ja vedän ulos miekan teidän jälkeenne, ja maanne pitää tuleman kylmille ja kaupunkinne kukistetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Silloin kelpaa maalle hänen leponsa, niinkauvan kuin hän autiona on, ja te olette vihollisten maalla. Ja silloin vasta maa lepää ja pyhää pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Niinkauvan kuin se autiona on, saa hän levätä, ettei hän saanut pyhää pitää, silloin koska teidän piti hänen pyhäänsä antaman pitää, koska te asuitte siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Ja niille, jotka jäävät teistä, teen minä vapisevan sydämen heidän vihollistensa maalla, niin että kapisevan lehden ääni karkottaa heitä, ja pitää pakeneman sitä niinkuin miekkaa, ja pitää kaatuman siinä, kussa ei kenkään heitä aja takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Ja heidän pitää lankeeman toinen toisensa päälle, niinkuin miekan edestä, vaikka ei yksikään karkota heitä, ja ette tohdi nousta vihamiehiänne vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Ja teidän pitää hukkuman pakanain seassa, ja vihollisten maa pitää teitä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Ne kuin jäävät teistä, pitää vaipuman pahuudessansa, teidän vihollistenne maalla. Ja isäinsä pahoissa teoissa pitää teidän vaipuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Silloin pitää heidän tunnustaman pahat tekonsa ja isäinsä pahat teot, joilla he ovat minun mieleni rikkoneet, ja vaeltaneet minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Sentähden minä myös vaellan heitä vastaan ja vien heitä vihollistensa maalle, että edes silloin heidän ympärileikkaamatoin sydämensä nöyryyttäis itsensä; silloin myös heidän pahan tekonsa rangaistus heille kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Ja minä muistan minun liittoni Jakobin kanssa, niin myös minun liittoni Isaakin kanssa, ja myös minun liittoni Abrahamin kanssa muistan minä, muistan myös maan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Joka heiltä jätetty on, ja sille kelpaa lepopäivänsä, niinkauvan kuin se autiona on heiltä, ja heidän pahan tekonsa rangaistus heille kelpaa, että he hylkäsivät minun oikeuteni, ja heidän sielunsa on kuoittanut minun säätyjäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Ja vaikka he vielä vihollistensa maalla ovat, en minä kuitenkaan ole heitä hyljännyt, ja en heitä niin kurittanut, että minä olisin heidän peräti hukuttanut, ja minun liittoni heidän kanssansa tyhjäksi tehnyt; sillä minä olen Herra heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Ja minä muistan ensimäisen liittoni heistä, koska minä johdatin heidät Egyptin maalta pakanain silmäin edestä, ollakseni heidän Jumalansa: minä Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Nämät ovat ne säädyt ja oikeudet ja käskyt, jotka Herra antoi itsensä ja Israelin lasten vaiheelle, Sinain vuorella, Moseksen käden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Puhu Israelin lapsille ja sano heille: Jos joku tekee jonkun erinomaisen lupauksen, niin pitää ne sinun arvios jälkeen oleman Herran omat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Niin pitää tämän oleman sinun arvios: Kahdenkymmenen vuotisen miehenpuolen kuuteenkymmeneen vuoteen asti, pitää sinun arvaaman viiteenkymmeneen hopeasikliin, pyhän siklin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Mutta vaimonpuolen pitää sinun arvaaman kolmeenkymmeneen sikliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Mutta viiden vuotisesta kahdenkymmenen vuotiseen asti, jos se on miehenpuoli, niin pitää sinun arvaaman kahteenkymmeneen sikliin, vaan vaimonpuolen kymmeneen sikliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Jos se on kuukautinen viidenteen vuoteen asti, ja on miehenpuoli, pitää sinun sen arvaaman viiteen hopeasikliin, mutta vaimonpuolen kolmeen hopeasikliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Mutta jos se on kuudenkymmenen vuotinen eli sen päälle, ja miehenpuoli, pitää sinun arvaaman hänen viiteentoistakymmeneen sikliin, mutta vaimonpuolen kymmeneen sikliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ja jos hän on ylen köyhä senkaltaiseen arvioon, niin pitää hänen menemän papin eteen, ja papin pitää arvaaman hänen. Sen jälkeen, kuin se, joka lupauksen tehnyt on, voi matkaan saada, pitää papin hänen arvaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Jos se on karjasta, jota Herralle uhrataan, kaikki mitä Herralle annetaan, se on pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Ei pidä sitä vaihetettaman eli muutettaman hyvä pahaan, eli paha hyvään. Jos joku kumminkin vaihettaa yhden eläimen toiseen, niin pitää he molemmat oleman pyhät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Jos se eläin on saastainen, jota ei saada uhrata Herralle, niin pitää se vietämän papin eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Ja papin pitää arvaaman sen, jos se on hyvä eli paha: sen pitää pysymän sinun arviossas, joka pappi olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Jos joku kuitenkin tahtoo lunastaa sen, hänen pitää antaman viidennen osan sinun arvios päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Ja jos joku pyhittää huoneensa Herralle pyhäksi, niin pitää papin arvaaman sen, jos se on hyvä eli paha: ja papin arviossa pitää sen pysymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mutta jos pyhittänyt tahtoo lunastaa huoneensa, niin pitää hänen antaman viidennen osan enemmän rahaa, kuin sinun arvios on, ja niin pitää se hänen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Jos joku pyhittää Herralle kappaleen peltoa perintömaastansa, niin pitää sinun se arvaaman sen jälkeen, kuin siihen kylvetään; jos siihen kylvetään homer ohria, niin pitää sen maksaman viisikymmentä hopeasikliä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Vaan jos hän pyhittää peltonsa ilovuodesta alkain, niin pitää sen maksaman sinun arvios jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Jos hän on pyhittänyt peltonsa ilovuoden jälkeen, niin papin pitää lukeman hänelle rahan vuoden luvun jälkeen, kuin takaperin on ilovuoteen asti, ja se pitää sinun arviostas vähennettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Jos se joka pellon pyhittänyt on, tahtoo sen todella lunastaa jälleen, niin pitää hänen antaman viidettä osaa enemmän rahaa, kuin se sinulta arvattu on, ja niin pitää se hänen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Jos ei hän tahdo lunastaa peltoa, mutta myy sen toiselle, niin ei pidä sitä enää lunastettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Vaan se pelto, koska se ilovuonna tulee vapaaksi, pitää oleman pyhä Herralle, niinkuin valallisella lupauksella eroitettu pelto, ja pitää oleman papin perintösaama.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Jos joku sen pellon, jonka hän ostanut on, joka ei ole hänen perintömaansa, pyhittää Herralle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Niin pitää papin laskeman hänen edessänsä sen hinnan sinun arvios jälkeen, ilovuoteen asti, ja hänen pitää sen samana päivänä antaman ulos, sinun arvios jälkeen, että se Herralle pyhä olis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Mutta ilovuonna pitää sen tuleman hänen omaksensa jälleen, jolta hän sen ostanut on, että se oli hänen perintösaamansa maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Kaikki sinun arvios pitää tapahtuman pyhän siklin jälkeen; mutta sikli tekee kaksikymmentä geraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Mutta eläinten esikoista, joka esikko-oikeuden jälkeen Herran oma muutoinkin on, ei pidä kenenkään pyhittämän, olkoon härkä eli lammas; sillä se on Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Jos jotakin saastaista on eläinten seassa, niin se pitää lunastettaman sinun arvios jälkeen, ja siihen lisäksi annettaman viides osa; jos ei sitä lunasteta, niin se myytäkään sinun arvios jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Kuitenkin kaikkea valallisella lupauksella eroitettua, jota joku valallisesti lupaa Herralle kaikesta mitä hänellä on, joko se olis ihminen, eläin eli perintöpelto, ei sitä pidä myytämän eli lunastettaman; sillä kaikki valallisellla lupauksella eroitettu on kaikkein pyhin Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Kaikkea kirottua, joka kiroukseen annetaan ihmisistä, ei pidä lunastettaman, vaan hän pitää totisesti kuoletettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Kaikki maan kymmenykset, sekä maan siemenestä että puiden hedelmistä, ovat Herran, ja pitää oleman pyhät Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Jos joku tahtoo lunastaa kymmenyksensä, hänen pitää antaman viidennen osan lisäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Ja kaikki kymmenykset karjasta, ja lampaista, ja kaikista kuin vitsan alla käy, ne ovat pyhät kymmenykset Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Ei pidä kysyttämän, jos se on hyvä eli paha, eikä myös pidä sitä vaihetettaman. Jos joku vaihettaa sen, niin pitää ne molemmat oleman pyhät, ja ei lunastettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Nämät ovat ne käskyt, jotka Herra antoi Moseksen kautta Israelin lapsille, Sinain vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Ja Herra puhui Mosekselle Sinain korvessa, seurakunnan majassa, ensimäisenä päivänä toisena kuukautena, toisena vuonna jälkeen, sittekuin he olivat lähteneet Egyptin maalta, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Lukekaat koko Israelin lasten joukko, heidän sukunsa, ja heidän isäinsä huonetten jälkeen, ja heidän nimeinsä luvun jälkeen, kaikki miehenpuoli, mies mieheltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Kahdenkymmenen vuotiset ja sen ylitse, kaikki jotka kelpaavat lähtemään sotaan Israelissa: lukekaat heitä heidän joukkonsa jälkeen, sinä ja Aaron.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Ja teidän kanssanne pitää oleman yksi mies jokaisesta sukukunnasta, joka on isänsä huoneen päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Ja nämät ovat niiden päämiesten nimet, jotka teidän kanssanne seisoman pitää: Rubenista, Elitsur Zedeurin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Simeonista, Selumiel Suri-Saddain poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Juudasta, Nahesson Amminadabin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Isaskarista, Netaneel Suarin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Sebulonista, Eliab Helonin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Josephin pojista: Ephraimista, Elisama Ammihudin poika; Manassesta, Gamliel Pedatsurin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'BenJaminista, Abidan Gideonin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Danista, Ahieser Ammi Saddain poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Asserista, Pagiel Okranin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Gadista, Eliasaph Deguelin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Naphtalista, Ahira Enan poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Nämät olivat kutsutut kansan seasta, isäinsä sukuin esimiehet, jotka olivat Israelin tuhanten päät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Niin Moses ja Aaron ottivat miehet tykönsä, jotka nimeltänsä nimitetyt olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Ja he kokosivat kaiken kansan, ensimäisenä päivänä toisella kuulla, jotka luettelivat polvilukunsa, sukukuntainsa, ja isäinsä huonetten jälkeen: nimenomattain, kahdenkymmenen vuotisesta ja sen ylitse, mies mieheltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Niinkuin Herra oli käskenyt Mosekselle, niin luki hän heitä Sinain korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Rubenin Israelin esikoisen lapset olivat heidän polviluvuissansa, sukunsa ja isäinsä huonetten jälkeen, nimenomattain, mies mieheltä kaikki miehenpuoli, kahdenkymmenen vuotisista ja sen ylitse, kaikki kelvolliset sotaan menemään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Luetut Rubenin sukukuntaan, kuusiviidettäkymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Simeonin lapset ja heidän polvilukunsa, sukunsa ja isäinsä huonetten jälkeen, luetut nimenomattain mies mieheltä, kaikki miehenpuoli kahdenkymmenen vuotisista ja sen ylitse, kaikki sotaan menemään kelvolliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Luetut Simeonin sukukuntaan, yhdeksänkuudettakymmentä tuhatta ja kolmesataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Gadin lapset ja heidän polvilukunsa, sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki sotaan menemään kelvolliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Luetut Gadin sukukuntaan, viisiviidettäkymmentä tuhatta, kuusisataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Juudan lasten polviluku, heidän sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki sotaan menemään kelvolliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Luetut Juudan sukukuntaan, neljäkahdeksattakymmentä tuhatta ja kuusisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Isaskarin lasten polviluku, heidän sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki sotaan menemään kelvolliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Luetut Isaskarin sukukuntaan, neljäkuudettakymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Sebulonin lasten polviluku, heidän sukuinsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki sotaan menemään kelvolliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Luetut Sebulonin sukukuntaan, seitsemänkuudettakymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Josephin lapset: Ephraimin lapsista polvilukunsa, sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki sotaan menemään kelvolliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Luetut Ephraimin sukukuntaan olivat neljäkymmentätuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Manassen lapset polvilukunsa, sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki jotka sotaan menemään kelpasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Luetut Manassen sukukuntaan, kaksineljättäkymmentä tuhatta ja kaksisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'BenJaminin lasten polviluku, heidän sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki jotka sotaan menemään kelpasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Luetut BenJaminin sukukuntaan, viisineljättäkymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Danin lasten polviluku, heidän sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki ne jotka sotaan menemään kelpasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Luetut Danin sukukuntaan, kaksiseitsemättäkymmentä tuhatta ja seitsemänsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Asserin lasten polviluku, heidän sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki jotka sotaan kelpasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Luetut Asserin sukukuntaan, yksiviidettäkymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Naphtalin lasten polviluku, heidän sukunsa ja isäinsä huonetten jälkeen, nimenomattain kahdenkymmenen vuotisista ja sen ylitse, kaikki jotka sotaan kelpasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Luetut Naphtalin sukukuntaan, kolmekuudettakymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Nämät ovat ne luetut, jotka Moses ja Aaron ja kaksitoistakymmentä Israelin päämiestä lukivat, joista aina yksi oli jokaisen heidän isänsä huoneen ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Ja olivat kaikki yhteen luetut Israelin lapset, heidän isäinsä huonetten jälkeen, kahdestakymmenestä vuodesta ja sen ylitse, kaikki jotka olivat sotaan kelvolliset Israelissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Ja olivat kaikki luetut, kuusi kertaa satatuhatta ja kolmetuhatta ja viisisataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mutta Leviläiset heidän isäinsä sukukunnan jälkeen ei olleet heidän lukuunsa luetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Ei kuitenkaan pidä sinun lukeman Levin sukukuntaa, eli ottaman heistä päälukua, Israelin lasten seassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Mutta sinun pitää asettaman Leviläiset todistuksen majan palvelukseen, ja kaikkein sen astiain päälle, ja kaikkein mitkä sen omat ovat. Heidän pitää kantaman majan, ja kaikki sen astiat, ja heidän pitää ottaman vaarin siitä, ja sioittaman itsensä majan ympärille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Ja kuin matkustetaan, silloin pitää Leviläisten ottaman majan alas, ja koska joukko itsensä sioittaa, pitää heidän paneman sen ylös. Jos joku muukalainen lähestyy sitä, sen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Israelin lapset pitää sioittaman itsensä kukin leirinsä ja joukkonsa lipun tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mutta Leviläiset pitää sioittaman itsensä todistuksen majan ympärille, ettei viha tulisi Israelin lasten joukon päälle. Sentähden pitää Leviläisten pitämän vaarin todistuksen majan vartiosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Ja Israelin lapset tekivät sen: kaikki mitä Herra Mosekselle käskenyt oli, niin he tekivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Israelin lapset pitää itsensä sioittaman, jokainen lippunsa ja merkkinsä alle, isäinsä huoneen jälkeen: sille kohdalle ympäri seurakunnan majaa pitää heidän itsensä sioittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Etiselle puolelle itään päin pitää Juudan lippunsa ja joukkonsa kanssa itsensä sioittaman: heidän päämiehensä Nahesson Amminadabin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Ja hänen joukkonsa luetut, neljäkahdeksattakymmentä tuhatta ja kuusisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Hänen viereensä pitää Isaskarin sukukunnan itsensä sioittaman: heidän päämiehensä Netaneel Zuarin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Ja hänen joukkonsa luetut, neljäkuudettakymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Senjälkeen Sebulonin sukukunta ja heidän päämiehensä Eliab Helonin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Ja hänen joukkonsa luetut, seitsemänkuudettakymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Kaikki Juudan leirissä luetut, satatuhatta ja kuusiyhdeksättäkymmentä tuhatta ja neljäsataa, heidän joukoissansa: heidän pitää ensinnä vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Etelän puolelle pitää Rubenin itsensä sioittaman lippunsa ja joukkonsa kanssa, heidän päämiehensä Elitsur Sedeurin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Ja hänen joukkonsa luetut, kuusiviidettäkymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Hänen viereensä pitää Simeonin sukukunnan itsensä sioittaman: heidän päämiehensä Selumiel Suri Saddain poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Ja hänen joukkonsa luetut, yhdeksänkuudettakymmentä tuhatta ja kolmesataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Sitälähin Gadin sukukunta, heidän päämiehensä Eliasaph Reguelin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Ja heidän joukkonsa luetut, viisiviidettäkymmentä tuhatta, kuusisataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Kaikki Rubenin leirissä luetut, satatuhatta, yksikuudettakymmentä tuhatta, neljäsataa ja viisikymmentä heidän joukoissansa. Ja heidän pitää toisena vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Sitte pitää seurakunnan majan vaeltaman Leviläisten leirin kanssa keskileirissä, ja niinkuin he teitänsä sioittavat, niin pitää myös heidän vaeltaman, jokaisen paikassansa, lippuinsa alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Lännen puolelle pitää Ephraimin itsensä sioittaman lippunsa ja joukkonsa kanssa, heidän päämiehensä Elisama Ammihudin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Ja hänen joukkonsa luetut, neljäkymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Lähin häntä pitää Manassen sukukunnan itsensä sioittaman: heidän päämiehensä Gamliel Pedatsurin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Ja hänen joukkonsa luetut, kaksineljättäkymmentä tuhatta ja kaksisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Senjälkeen BenJaminin sukukunta: heidän päämiehensä Abidan Gideonin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Ja hänen joukkonsa luetut, viisineljättäkymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Kaikki Ephraimin leirissä luetut, satatuhatta, ja kahdeksantuhatta, ja sata, heidän joukoissansa. Ja heidän pitää kolmantena vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Pohjan puolella pitää Danin sioituslippu oleman heidän joukkoinsa jälkeen, ja Danin lasten päämies Ahieser AmmiSaddain poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Ja hänen joukkonsa luetut, kaksiseitsemättäkymmentä tuhatta ja seitsemänsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Hänen viereensä pitää Asserin sukukunnan heitänsä sioittaman, ja Asserin lasten päämies Pagiel Okranin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Ja hänen joukkonsa luetut, yksiviidettäkymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Sitälikin Naphtalin sukukunta, ja Naphtalin lasten päämies Ahira Enanin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Ja hänen joukkonsa luetut, kolmekuudettakymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Niin että kaikki Danin leirissä luetut ovat satatuhatta, seitsemänkuudettakymmentä tuhatta ja kuusisataa. Ja heidän pitää viimeisenä vaeltaman lippunsa alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Tämä on Israelin lasten luku heidän isäinsä huonetten jälkeen, kaikkein heidän leirinsä luettuin ja joukkoinsa kanssa: kuusisataa tuhatta ja kolmetuhatta, viisisataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mutta Leviläiset ei ole luetut Israelin lasten lukuun, niinkuin Herra Mosekselle oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Ja Israelin lapset tekivät sen: kaiken sen jälkeen, kuin Herra oli Mosekselle käskenyt, sioittivat he heitänsä lippuinsa alle ja matkustivat itsekukin sukukunnassansa, isäinsä huoneen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Nämät ovat Aaronin ja Moseksen sukukunnat siihen aikaan koska Herra puhui Mosekselle Sinain vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Ja nämät ovat Aaronin poikain nimet: Nadab esikoinen, sitälikin Abihu, Eleatsar ja Itamar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Nämät ovat Aaronin poikain nimet, jotka olivat papiksi voidellut, ja heidän kätensä täytetyt papin virkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mutta Nadab ja Abihu kuolivat Herran edessä, koska he uhrasivat vierasta tulta Herran edessä Sinain korvessa, ja ei ollut heillä poikia; mutta Eleatsar ja Itamar tekivät papin virkaa isänsä Aaronin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Tuo edes Levin sukukunta ja aseta heitä papin Aaronin eteen, palvelemaan häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Ja pitämään vaarin hänen vartiostansa ja koko seurakunnan vartiosta, seurakunnan majan edessä, ja palvelemaan majan palveluksessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Ja tallella pitämään kaikki seurakunnan majan astiat, ja ottamaan vaarin Israelin lasten vartioitsemisesta, palvelemaan majan palveluksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Ja sinun pitää antaman Aaronille ja hänen pojillensa Leviläiset; he ovat niille lahjaksi annetut Israelin lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Mutta Aaronin poikinensa pitää sinun asettaman pitämään vaaria pappeudestansa. Ja jos joku muukalainen siihen lähestyy, sen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Ja Herra puhui Mosekselle sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Katso, minä otin Leviläiset Israelin lapsista kaikkein esikoisten edestä, jotka ensisti äitinsä kohdun avaavat Israelin lasten seassa, niin että Leviläisten pitää oleman minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Sillä kaikki esikoiset ovat minun: sinä päivänä, kuin minä löin kaikki esikoiset Egyptin maalla, pyhitin minä itselleni kaikki esikoiset Israelissa, ihmisistä niin karjaan asti, että ne olisivat minun: Minä Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Ja Herra puhui Mosekselle Sinain korvessa, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Lue Levin pojat heidän isäinsä huoneen ja sukukuntainsa jälkeen: kaiken miehenpuolen, kuukauden vanhan ja sen ylitse, pitää sinun lukeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Ja Moses luki heitä Herran sanan jälkeen, niinkuin hänelle oli käsketty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Ja nämät olivat Levin pojat nimeinsä jälkeen: Gerson, Kahat ja Merari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Mutta Gersonin poikain nimet heidän sukukunnissansa olivat Libni ja Simei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Kahatin pojat heidän sukukunnissansa: Amram, Jetsehar, Hebron ja Usiel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Merarin pojat heidän sukukunnissansa: Maheli ja Musi. Nämät ovat Levin sukukunnat heidän isäinsä huoneen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Nämät ovat Gersonin sukukunnat: Libniläiset ja Simeiläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Heidän lukunsa, kaikki miehenpuoli kuukauden vanha ja sen ylitse, ne olivat seitsemäntuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Ja Gersonilaisten sukukunnat pitää heitänsä sioittaman takapuolelle majaa, länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Heidän päämiehensä, pitää oleman Eljasaph Laelin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Ja Gersonin lasten pitää vartioitseman seurakunnan majassa Tabernaklia, ja majaa, peitteitä, ja seurakunnan majan oven vaatteita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Ja pihan vaatteita, ja pihan oven peitettä, joka on Tabernaklin ja alttarin päällä ympäri, ja köysiä ja kaikkia, mitä sen palvelukseen tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Nämät ovat Kahatin sukukunnat: Amramilaiset, Jetseharilaiset, Hebronilaiset ja Usielilaiset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Kaikki miehenpuoli kuukauden vanhasta ja sen ylitse, lukuansa kahdeksantuhatta ja kuusisataa, joiden pitää pitämän vaarin pyhän vartioitsemisesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Ja pitää heitänsä sioittaman etelän puolelle, sivulle majaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Ja heidän päämiehensä pitää oleman Elitsaphan Usielin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Ja heidän pitää vartoitseman arkkia, pöytää, kynttiläjalkaa, alttareita ja kaikkia pyhän astioita, joilla palvelusta tehdään, ja peitteitä ja kaikkia, mitä palvelukseen tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Mutta kaikkein Levin päämiesten ylimmäinen pitää oleman Eleatsarin papin Aaronin pojan, ylitse niiden, jotka pitävät vaarin pyhän vartioitsemisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Nämät ovat Merarin sukukunnat: Mahelilaiset ja Musilaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Joiden luku oli kuusituhatta ja kaksisataa, kaikki miehenpuoli, kuukauden vanha ja sen ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Heidän päämiehensä pitää oleman Suriel Abihailin poika, ja pitää sioittaman heitänsä sivulle majaa, pohjan puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Ja heidän virkansa pitää oleman, vartioida majan lautoja, korennoita, patsaita ja majan jalkoja, ja kaikkia astioita, jotka sen palvelukseen tarvitaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Niin myös patsaita pihan ympärillä, ja sen jalkoja, ynnä paanuin ja köytten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Mutta seurakunnan majan etiselle puolelle itään päin pitää Moses ja Aaron ja hänen poikansa heitänsä sioittaman, ja vartioitseman pyhän vartioita Israelin lasten puolesta. Jos joku muukalainen siihen lähestyy, sen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Kaikkein Leviläisten luku, jotka Moses ja Aaron lukivat, heidän sukukunnissansa Herran sanan jälkeen, kaikki miehenpuoli, kuukauden vanha ja sen ylitse, oli kaksikolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Ja Herra puhui Mosekselle: lue kaikki esikoiset, jotka miehenpuolet ovat Israelin lasten seassa, kuukauden vanhat ja sen ylitse, ja ota heidän nimeinsä luku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Ja sinun pitää ottaman Leviläiset minulle, minä Herra, kaikkein Israelin lasten esikoisten edestä, ja Leviläisten karjat, kaikkein Israelin lasten karjan esikoisten edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Ja Moses luki, niinkuin Herra hänelle käskenyt oli, kaikki Israelin lasten esikoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Ja olivat kaikki miehiset esikoiset, heidän nimeinsä luvun jälkeen, kuukauden vanhat ja sen ylitse luetut, kaksikolmattakymmentä tuhatta, kaksisataa ja kolmekahdeksattakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Ota Leviläiset kaikkein Israelin lasten esikoisten edestä, ja Leviläisten karja heidän karjansa edestä: ja Leviläisten pitää oleman minun, minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Mutta lunastuksen niiden kahdensadan ja kolmenkahdeksattakymmenen edestä, jotka jäävät Israelin lasten esikoisista Leviläisten luvun ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Pitää sinun ottaman viisi sikliä joka hengeltä: pyhän siklin jälkeen pitää sinun sen ottaman; sikli maksaa kaksikymmentä geraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Ja sinun pitää antaman rahan Aaronille ja hänen pojillensa, lunastettuin edestä, jotka ylitse olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Niin otti Moses lunastusrahan niiltä, jotka ylitse olivat Leviläisten lunastetuista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Israelin lasten esikoisilta otti hän rahan, tuhannen kolmesataa ja viisiseitsemättäkymmentä sikliä: pyhän siklin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Ja Moses antoi lunastusrahan Aaronille ja hänen pojillensa Herran sanan jälkeen, niinkuin Herra oli Mosekselle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Lue Kahatin lapset Levin poikain seasta, heidän sukukuntainsa ja isäinsä huoneen jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Kolmenkymmenen vuotisesta ja sen ylitse, viidenkymmenen vuotiseen asti: kaikki ne jotka kelvolliset ovat sotaan menemään, seurakunnan majassa palvelusta tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Ja tämä pitää oleman Kahatin poikain virka todistuksen majassa, joka kaikkein pyhin on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Koska leiriä siirretään, niin pitää Aaronin poikinensa tuleman ja ottaman esiripun alas, ja käärimän todistuksen arkin siihen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Ja paneman peitteen sen päälle tekasjim-nahoista, ja hajoittamaan kokonansa sinisen vaatteen sen ylitse, ja paneman sen korennot siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Niin myös pitää heidän hajoittaman näkypöydälle sinisen vaatteen, ja paneman sen päälle vadit, lusikat, maljat ja kannut, joilla ulos ja sisälle kaadetaan, ja ne alinomaiset leivät pitää sen päällä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Ja heidän pitää hajoittaman niiden päälle tulipunaisen vaatteen, ja peittämän tekasjim-nahkaisella peitteellä, ja paneman sen korennot siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Ja heidän pitää ottaman sinisen vaatteen, ja käärimän valkeuden kynttiläjalan sen sisälle, ja sen lamput, niistimet ja sammutusastiat, ja kaikki öljyastiat, joilla palvelusta siinä tehdään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Ja tämän ja kaikkein näiden kaluin ympäri pitää heidän paneman peitteen tekasjim-nahasta, ja paneman ne korentoin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Niin myös pitää heidän hajoittaman kultaisen alttarin päälle sinisen vaatteen, ja peittämän sen tekasjimnahkaisella peitteellä, ja paneman sen korennot siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Kaikki astiat, joilla he palvelevat pyhässä, pitää heidän ottaman ja levittämän niiden ylitse sinisen vaatteen, ja peittämän sen tekasjim-nahkaisella peitteellä, ja paneman ne korentoin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Heidän pitää myös käväisemän tuhan alttarilta ja hajoittaman purppuraisen vaatteen sen päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Ja paneman sen päälle kaikki astiat, joilla he siinä palvelevat, hiilipannut, hangot, lapiot ja maljat, ja kaikki alttarin astiat; heidän pitää myös hajoittaman sen ylitse tekasjim-nahkaisen peitteen, ja paneman korennot siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Koska Aaron ja hänen poikansa nämät toimittaneet ovat ja peittäneet pyhän ja kaikki pyhät astiat, ja leiriä siirretään, niin pitää sitte Kahatin lapset menemän ja kantaman niitä, ja ei pidä rupeeman pyhään, ettei he kuolisi. Nämät pitää oleman Kahatin lasten taakat seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Ja Eleatsarilla, papin Aaronin pojalla, pitää oleman tämä virka: toimittaa öljyä valaistukseksi, ja yrttejä suitsutukseksi, ja alinomaista ruokauhria, ja voidellusöljyä, niin että hän toimittaa koko Tabernaklin ja kaikki, mitä siinä on, pyhän ja hänen astiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Ja Herra puhui Mosekselle ja Aaronille sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Ei teidän pidä Kahatilaisten sukukuntain sikiöitä hävittämän Leviläisten seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Vaan sen teidän pitää heidän kanssansa tekemän, että he eläisivät ja ei kuolisi: jos he lähestyvät sitä kaikkein pyhimpää, niin pitää Aaronin poikinensa menemän sisälle ja asettaman itsekunkin heidän virkaansa ja taakkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Vaan ei heidän pidä menemän sinne sisälle, katsomaan pyhää, koska se peitetään, ettei he kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Lue Gersonin lapset, heidän isäinsä huoneen ja sukukuntainsa jälkeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Kolmenkymmenen vuotisesta ja sen ylitse viidenkymmenen vuotiseen asti, pitää sinun ne lukeman, kaikki ne, jotka sotaan menemään kelvolliset ovat, että heillä olis virka seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Ja tämä pitää oleman Gersonilaisten sukukunnan virka, jota heidän pitää tekemän ja kantaman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Ja heidän pitää kantaman Tabernaklin vaatteet, ja seurakunnan majan, ja hänen peitteensä, ja tekasjimnahkaisen peitteen, joka on sen päällä, ja myös seurakunnan majan ovivaatteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Ja pihan vaatteet, ja läpikäytävän oven vaatteen pihassa, joka käy sekä Tabernaklin että myös alttarin ympäri, ja hänen köytensä ja kaikki virkansa astiat, ja kaikki mitä heidän virassansa tarvitaan ja heidän tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Aaronin ja hänen poikainsa sanan jälkeen pitää kaikkein Gersonin poikain virka tehtämän, kaikki mitä heidän kantaman ja korjaaman pitää; ja teidän pitää katsoman, että he ottaisivat vaarin kaikista kuormistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tämän pitää Gersonin lasten ja sukuin virka oleman seurakunnan majassa: ja heidän vartionsa pitää oleman Itamarin, papin Aaronin pojan käden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Merarin lapset, heidän sukukuntainsa ja isäinsä huoneen jälkeen, pitää sinun myös lukeman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Kolmenkymmenen vuotisesta ja sen ylitse, viidenkymmenen vuotiseen asti, pitää sinun ne lukeman, kaikki sotaan menemään kelvolliset, palvelemaan seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Tästä kuormasta pitää heidän pitämän vaarin, kaiken virkansa jälkeen seurakunnan majassa, kuin ovat majan laudat, ja korennot, ja patsaat, ja jalat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Niin myös patsaat pihan ympärillä, ja jalat, ja naulat, ja köydet, kaikkein heidän astiainsa kanssa, kaiken heidän virkansa perästä: jokaiselle pitää teidän nimenomattain asettaman kuormat astioista, joista heidän pitää pitämän vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Ja tämä pitää oleman Merarin lasten sukuin virka kaikissa, joista heidän pitää ottaman vaarin seurakunnan majassa, Itamarin papin Aaronin pojan käden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Ja Moses ja Aaron, ynnä kaiken kansan päämiesten kanssa, lukivat Kahatilaisten lapset, heidän sukuinsa ja isäinsä huoneen jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Kolmenkymmenen vuotisesta ja sen ylitse viidenkymmenen vuotiseen asti, kaikki sotaan menemään kelvolliset, palvelusta tekemään seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Ja heidän lukunsa oli heidän sukuinsa jälkeen, kaksituhatta, seitsemänsataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Tämä on Kahatilaisten sukukuntain luku, joilla kaikilla oli toimittamista seurakunnan majassa, jotka Moses ja Aaron lukivat, Herran sanan jälkeen, Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Niin luettiin myös Gersonin lapset, sukukuntainsa ja isäinsä huoneen jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Kolmenkymmenen vuotisista ja sen ylitse viidenkymmenen vuotisiin asti, kaikki sotaan menemään kelvolliset, palvelusta tekemään seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Ja heidän lukunsa, heidän sukuinsa ja isäinsä huoneen jälkeen, oli kaksituhatta kuusisataa ja kolmekymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Tämä on Gersonin lasten suvun luku, joilla kaikilla oli tekemistä seurakunnan majassa, jotka Moses ja Aaron lukivat, Herran sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Luettiin myös Merarin lapset, sukuinsa ja isäinsä huoneen jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Kolmenkymmenen vuotisista ja sen ylitse viidenkymmenen vuotisiin asti, kaikki sotaan menemään kelvolliset, palvelusta tekemään seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Ja heidän lukunsa oli, heidän sukuinsa jälkeen, kolmetuhatta ja kaksisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Tämä on Merarin lasten suvun luku, jotka Moses ja Aaron lukivat, Herran sanan jälkeen Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Kaikkein Leviläisten luku, kuin Moses ja Aaron ynnä Israelin päämiesten kanssa lukivat, heidän sukuinsa ja isäinsä huoneen jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Kolmenkymmenen vuotisesta ja sen ylitse, viidenkymmenen vuotiseen asti, kaikki ne jotka menivät sisälle palvelusta tekemään virassansa, ja kuormaa kantamaan seurakunnan majaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Heidän luettunsa olivat kahdeksantuhatta, viisisataa ja kahdeksankymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Ja hän luki heidät Herran sanan jälkeen Moseksen kautta, itsekunkin hänen virkaansa ja kuormaansa, ja ne, mitkä hän luki, olivat niinkuin Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Käske Israelin lapset ajaa kaikki spitaliset leiristä ulos, ja kaikki, joiden siemen vuotaa, ja kaikki ne, jotka ovat johonkuhun kuolleesen itsensä saastuttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Sekä miehet että vaimot pitää teidän ajaman ulos: leiristä ne pitää teidän ajaman ulos, ettei he leiriänsä saastuttaisi, kussa minä heidän keskellänsä asun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Ja Israelin lapset tekivät niin, ja ajoivat ne leiristä ulos: niinkuin Herra oli Mosekselle sanonut, niin he tekivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Puhu Israelin lapsille: jos joku mies eli vaimo tekee jotakin syntiä ihmistä vastaan, niin että hän raskaasti rikkoo Herraa vastaan, se sielu on vianalaiseksi itsensä saattanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Heidän pitää tunnustaman rikoksensa, jonka he tehneet ovat, ja pitää päänänsä sovittaman vikansa, ja vielä lisäämän viidennen osan, ja antaman sille, jota vastaan he rikkoneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Jos ei sillä ihmisellä ole sitä, jolla omaisen oikeus on, jolle se rikos maksettaa taittaisiin, niin pitää se Herralle annettaman, ja oleman papin oman, paitsi sovinto-oinasta, jolla hän sovitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Niin pitää myös kaikki ylennys kaikista, minkä Israelin lapset pyhittävät ja uhraavat papille, oleman hänen omansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Jos joku jotain pyhittää, sen pitää oleman papin omana, ja mitä joku antaa papille, sen pitää oleman myös hänen omansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Puhu Israelin lapsille ja sano heille: jos jonkun miehen vaimo tulee ynsiäksi ja rikkoo kovasti häntä vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'Ja jos joku makaa hänen, ja se on hänen miehensä silmäin edestä salattu ja peitetty, että hän on itsensä saastuttanut, ja ei ole todistusta häntä vastaan, eikä hän ole siinä löydetty,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Ja kiivaushenki kehoittaa hänen, että hän kiivoittelee vaimostansa, että hän on saastuttanut itsensä, eli epäluulon henki on tullut hänen päällensä, että hän on epäluulossa vaimostansa, vaikka ei hän ole saastuttanut itsiänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Niin pitää miehen viemän vaimonsa papin eteen, ja viemän uhrin hänen edestänsä, kymmenennen osan ephaa ohraisia jauhoja, ja ei sen päälle öljyä vuodattaman, eikä myös pyhää savua sen päälle paneman; sillä se on kiivausuhri ja muistouhri, joka pahan teon muistuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Niin pitää papin tuoman hänen edes, ja asettaman Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Ja papin pitää ottaman pyhää vettä saviastiaan, ja tomua Tabernaklin permannosta pitää papin myös ottaman ja paneman veteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Ja papin pitää asettaman vaimon Herran eteen, ja paljastaman vaimon pään, ja paneman sen kätten päälle muistouhrin, joka on kiivausuhri, ja papin kädessä pitää oleman ne katkerat kirousvedet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Ja papin pitää vannottaman vaimoa, ja sanoman hänelle: jos ei yksikään mies ole maannut sinun kanssas, ja jos et sinä ole poikennut sinun miehes tyköä, niin ettet sinä ole itsiäs saastuttanut, niin sinun pitää vapaa oleman tästä karvaasta vedestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mutta jos sinä olet poikennut miehes tyköä, niin että sinä olet saastuttanut itses, ja joku on sinun maannut, paitsi sinun omaa miestäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Niin pitää papin vannottaman vaimoa kirouksen valalla, ja sanoman hänelle: Herra antakoon sinun kiroukseksi ja sadatukseksi kansas keskelle, niin että Herra sallii lakastua lantees ja vatsas ajettua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Niin menkään nyt tämä kirousvesi sinun sisällyksiis, niin että sinun vatsas ajettuu, ja sinun lantees lakastuvat. Ja vaimon pitää sanoman: amen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Ja niin pitää papin kirjoittaman nämä kiroukset kirjaan, ja pitää taas pyyhkimän ne ulos siihen katkeraan veteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Ja pitää antaman vaimon juoda siitä katkerasta kirousvedestä, ja se kirousvesi pitää menemän hänen sisällensä katkeruudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Ja papin pitää ottaman kiivausuhrin vaimon kädestä, ja ylentämän sen Herran eteen ruokauhriksi, ja uhraaman sen alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Ja papin pitää ottaman pivon täyden ruokauhrista hänen muistouhriksensa, ja polttaman sen alttarilla, ja sitte antaman sitä vettä vaimon juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Ja koska hän on juottanut hänen sillä vedellä, niin tapahtuu, jos hän on itsensä saastuttanut ja kaiketikin rikkonut miestänsä vastaan, että kirousvesi tulee hänen sisällänsä katkeraksi, ja hänen vatsansa ajettuu ja hänen lanteensa lakastuvat: ja sen vaimon pitää oleman kirotun kansansa seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Vaan jos se vaimo ei ole saastuttanut itsiänsä, vaan on puhdas, niin ei pidä sen mitään hänelle vahinkoa tekemän, vaan hänen pitää hedelmälliseksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Tämä on kiivauslaki: koska joku vaimo poikkee pois miehensä tyköä ja saastuttaa itsensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Eli koska epäluulon henki kehoittaa miehen kiivoittelemaan vaimostansa, että hän asettaa hänen Herran eteen, niin papin pitää tekemän hänelle kaiken tämän lain jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Ja miehen pitää oleman viattoman siitä pahasta teosta, vaan vaimon pitää kantaman pahuutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Puhu Israelin lapsille ja sano heille: jos mies eli vaimo lupaa erinomaisen lupauksen, eroittaaksensa itsensä Herralle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Hänen pitää eroittaman itsensä viinasta ja väkevästä juomasta: viinan etikkaa ja väkevän juoman etikkaa ei pidä hänen myös juoman, eikä myös kaikkea sitä, mikä on viinamarjoista vuotanut, pidä hänen juoman, eikä myös pidä hänen syömän tuoreita eikä kuivia viinamarjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Kaikella eroituksensa ajalla ei pidä hänen mitään, kuin viinapuusta tehty on, eikä viinamarjan tuumia eli kuoria syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Kaikella eroituksensa lupauksen ajalla ei pidä partaveitsen tuleman hänen päänsä päälle: siihenasti kuin hänen päivänsä täytetään, kuin hän oli Herralle itsensä eroittanut, pitää hänen pyhän oleman, ja antaman päänsä hiukset vapaasti kasvaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Kaikella ajalla, kuin hän Herralle itsensä eroittanut on, ei pidä hänen menemän yhdenkään kuolleen ruumiin tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Eikä saastuttaman itsiänsä isänsä taikka äitinsä, eikä veljensä eli sisarensa kuolleesen ruumiisen; sillä hänen Jumalansa eroitus on hänen päänsä päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Ja kaikella eroituksensa ajalla pitää hänen Herralle pyhän oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Jos joku äkisti ja tapaturmaisesti kuolee hänen tykönänsä, niin tulee hänen eroituksensa pää saastutetuksi, ja hänen pitää ajeleman päänsä paljaaksi puhdistuspäivänänsä, seitsemäntenä päivänä pitää hänen sen ajeleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Ja kahdeksantena päivänä pitää hänen tuoman kaksi mettistä eli kaksi kyhkyläisen poikaa papin tykö, seurakunnan majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Ja papin pitää uhraaman yhden syntiuhriksi, ja toisen polttouhriksi, ja sovittaman hänen, että hän saastutti itsensä kuolleen ruumiilla, ja niin pitää hänen pyhittämän päänsä sinä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Ja hänen pitää Herralle pitämän eroituksensa päivät, ja tuoman vuosikuntaisen karitsan vikauhriksi. Ja niin pitää ne entiset päivät tyhjään raukeeman, sentähden että hänen eroituksensa tuli saastutetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Tämä on eroitetun laki, koska hänen lupauksensa aika täyetty on: hän pitää tuotaman seurakunnan majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Ja hänen pitää tuoman uhrinsa Herralle: vuosikuntaisen virheettömän karitsan polttouhriksi, vuosikuntaisen virheettömän uuhen syntiuhriksi ja vuosikuntaisen virheettömän oinaan kiitosuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Ja korin happamattomia kyrsiä sämpyläjauhoista, sekoitettuja öljyyn, ja ohukaisia happamattomia kyrsiä, öljyllä voidelluita, ja heidän ruokauhrinsa ja juomauhrinsa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Ja papin pitää ne tuoman Herran eteen ja pitää uhraaman hänen syntiuhriksensa ja polttouhriksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Mutta oinaan hänen pitää uhraaman Herralle kiitosuhriksi, ja happamattomat leivät korissa; ja papin pitää myös hänen ruokauhrinsa ja juomauhrinsa tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Ja se, joka luvannut on, pitää lupauksensa pään ajeleman paljaaksi, seurakunnan majan oven edessä, ja ottaman lupauksensa pään hiukset ja heittämän ne tuleen, joka kiitosuhrin alla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Ja papin pitää ottaman oinaan keitetyn lavan, ja yhden happamattoman kyrsän korista, ja yhden ohukaisen happamattoman kyrsän, ja paneman ne eroitetun käden päälle, sittekuin hän ajellut on eroituksensa hiukset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Ja papin pitää ne häälyttämän häälytykseksi Herran edessä. Ja se on pyhä papille, ynnä häälytysrinnan ja ylennyslavan kanssa, ja sitte eroitettu juokaan viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Tämä on eroitetun laki, joka uhrinsa lupaa Herralle eroituksensa puolesta, paitsi mitä hän muutoin taisi matkaan saattaa: niinkuin hän on luvannut, niin pitää myös hänen tekemän lupauslakinsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Puhu Aaronille ja hänen pojillensa, ja sano: näin pitää teidän siunaaman Israelin lapsia, ja sanoman heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Herra siunatkoon sinua, ja varjelkoon sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Herra valistakoon kasvonsa sinun päälles, ja olkoon sinulle armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Herra ylentäköön kasvonsa sinun puolees, ja antakoon sinulle rauhan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Ja heidän pitää paneman minun nimeni Israelin lasten päälle, ja minä tahdon siunata heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Ja tapahtui sinä päivänä, koska Moses oli pannut Tabernaklin ylös, voiteli hän sen ja pyhitti sen, ja kaikki sen astiat, niin myös alttarin ja kaikki sen astiat: ja voiteli ne, ja pyhitti ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Niin uhrasivat Israelin päämiehet, jotka ylimmäiset olivat isäinsä huoneessa; sillä he olivat päämiehet sukukuntain ylitse, ja seisoivat ylimmäisessä siassa heidän seassansa, jotka luetut olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Ja toivat uhrinsa Herran eteen: kuusi peitettyä vaunua ja kaksitoistakymmentä härkää, aina vaunun kahden päämiehen edestä; mutta härjän itsekunkin edestä, ja toivat ne majan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Ota heiltä, että ne palvelisivat seurakunnan majan palveluksessa ja anna ne Leviläisille, itsekullekin virkansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Niin otti Moses vaunut ja härjät, ja antoi ne Leviläisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Kaksi vaunua ja neljä härkää antoi hän Gersonin lapsille, heidän virkansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Neljä vaunua ja kahdeksan härkää antoi hän Merarin lapsille, heidän virkansa jälkeen, Itamarin, papin Aaronin pojan käden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Mutta Kahatin lapsille ei hän mitään antanut; sillä heillä oli pyhän virka, ja piti kantaman olallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Ja päämiehet uhrasivat alttarin vihkimiseksi, sinä päivänä koska se voideltu oli, ja uhrasivat lahjansa alttarin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Ja Herra sanoi Mosekselle: anna jokaisen päämiehen tuoda uhrinsa, itsekunkin päivänänsä alttarin vihkimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Ensimäisenä päivänä uhrasi lahjansa Nahesson, Amminadabin poika, Juudan sukukunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Ja hänen lahjansa oli yksi hopiavati, joka painoi sata ja kolmekymmentä sikliä, yksi hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: ne molemmat täynnänsä öljyllä sekoitettuja sämpyläjauhoja, ruokauhriksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Siihen kultainen lusikka, jossa oli kymmenen sikliä kultaa, täynnänsä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Yksi nuori mulli, yksi oinas, yksi vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Yksi kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on Nahessonin Amminadabin pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Toisena päivänä uhrasi Netaneel, Suarin poika, Isaskarin päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä sämpyläjauhoja, sekoitetuita öljyllä, ruokauhriksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Siihen kultainen lusikka, joka maksoi kymmenen sikliä kultaa, täynnänsä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Mulli karjasta, oinas, vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on Netaneelin Suarin pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Kolmantena päivänä Sebulonin lasten päämies, Eliab Helonin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä sämpyläjauhoja, sekoitetuita öljyllä, ruokauhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Kultainen lusikka, joka maksoi kymmenen sikliä kultaa, täynnä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Mulli karjasta, oinas, vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on Eliabin Helonin pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Neljäntenä päivänä Rubenin lasten päämies, Elisur Sedeurin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä sämpyläjauhoja, sekoitetuita öljyllä, ruokauhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Kultainen lusikka, joka maksoi kymmenen sikliä kultaa täynnänsä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Mulli karjasta, oinas, vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on Elisurin Sedeurin pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Viidentenä päivänä Simeonin lasten päämies, Selumiel SuriSaddain poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä sämpyläjauhoja, sekoitetuita öljyllä, ruokauhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Kultainen lusikka, joka maksoi kymmenen sikliä kultaa, täynnänsä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Mulli karjasta, oinas, vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on Selumielin SuriSaddain pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Kuudentena päivänä Gadin lasten päämies, Eliasaph Deguelin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä sämpyläjauhoja, sekoitetuita öljyllä, ruokauhriksi,');
