INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Yhdeksäntenä päivänä BenJaminin lasten päämies, Abidan Gideonin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä sämpyläjauhoja, sekoitetuita öljyllä, ruokauhriksi,');
