INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Kymmenentenä päivänä Danin lasten päämies, AhiEser AmmiSaddain poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä sämpyläjauhoja, sekoitetuita öljyllä, ruokauhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Kultainen lusikka, joka maksoi kymmenen sikliä kultaa, täynnä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Mulli karjasta, oinas, vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on AhiEserin AmmiSaddain pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Ensimäisenätoistakymmenentenä päivänä Asserin lasten päämies, Pagiel Okranin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä öljyllä sekoitettuja sämpyläjauhoja, ruokauhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Kultainen lusikka, joka maksoi kymmenen sikliä kultaa, täynnä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Mulli karjasta, oinas, vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on Pagielin Okranin pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Toisenatoistakymmenentenä päivänä Naphtalin lasten päämies, Ahira Enanin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Hänen lahjansa oli hopiavati, joka maksoi sata ja kolmekymmentä sikliä, hopiamalja, joka maksoi seitsemänkymmentä sikliä, pyhän siklin jälkeen: molemmat täynnä öljyllä sekoitettuja sämpyläjauhoja, ruokauhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Kultainen lusikka, joka maksoi kymmenen sikliä kultaa, täynnä suitsutusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Mulli karjasta, oinas, vuosikuntainen karitsa, polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Kauris syntiuhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Ja kiitosuhriksi kaksi härkää, viisi oinasta, viisi kaurista, ja viisi vuosikuntaista karitsaa. Tämä on Ahiran Enanin pojan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Tämä on alttarin vihkimys sinä päivänä, jona se voideltiin, johonka Israelin lasten ruhtinaat uhrasivat: kaksitoistakymmentä hopiavatia, kaksitoistakymmentä hopiamaljaa, kaksitoistakymmentä kultaista lusikkaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Niin että jokainen vati painoi sata ja kolmekymmentä sikliä hopiaa, ja jokainen malja seitsemänkymmentä sikliä, niin että kaikkein astiain hopian luku juoksi kaksituhatta ja neljäsataa sikliä, pyhän siklin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Ja ne kaksitoistakymmentä kultaista lusikkaa, jotka suitsutusta täynnä olivat, jokainen painoi kymmenen sikliä, pyhän siklin jälkeen, niin että luku lusikkain kullasta juoksi sata ja kaksikymmentä sikliä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Eläinten luku polttouhriksi, kaksitoistakymmentä mullia, kaksitoistakymmentä oinasta, kaksitoistakymmentä vuosikuntaista karitsaa, ja heidän ruokauhrinsa, ja kaksitoistakymmentä kaurista syntiuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Ja karjan luku kiitosuhriksi oli neljä härkää kolmattakymmentä, kuusikymmentä oinasta, kuusikymmentä kaurista, kuusikymmentä vuosikuntaista karitsaa. Tämä on alttarin vihkimys koska se voideltiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Ja koska Moses meni seurakunnan majaan, että häntä siellä puhuteltaisiin, niin kuuli hän äänen puhuvan kanssansa armoistuimelta, joka oli todistuksen arkin päällä, kahden Kerubimin vaiheella, ja sieltä puhuteltiin häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Ja Herra puhui Mosekselle sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Puhu Aaronille, ja sano hänelle: koskas lamput panet ylös, niin pitää ne seitsemän lamppua valaiseman juuri kynttiläjalan kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Ja Aaron teki niin, ja asetti lamput kynttiläjalan kohdalle, niinkuin Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Mutta kynttiläjalka oli tehty lujasta kullasta, varresta niin kukkaisiin asti oli se vahvaa tekoa: sen muodon jälkeen kuin Herra oli Mosekselle näyttänyt, niin teki hän kynttiläjalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Ota Leviläiset Israelin lapsista ja puhdista heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Ja näin pitää sinun tekemän heille, puhdistaakses heitä. Sinun pitää priiskottaman syntivettä heidän päällensä: ja heidän pitää kaiken lihansa päältä karvat ajeleman, ja vaatteensa pesemän, niin he ovat puhtaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Ja sitte pitää heidän ottaman nuoren mullin, ja sen ruokauhriksi öljyllä sekoitettuja sämpyläjauhoja, ja toisen nuoren mullin pitää sinun ottaman syntiuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Ja sinun pitää tuoman Leviläiset seurakunnan majan eteen, ja kaiken Israelin lasten kansan kokooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Ja tuoman Leviläiset Herran eteen: ja Israelin lapset pitää paneman kätensä Leviläisten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Ja Aaronin pitää häälyttämän Leviläiset Israelin lapsilta Herran eteen, Herran palvelusta palvelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Ja Leviläisten pitää laskeman kätensä mullin päälle, ja toinen mulli pitää Herralle syntiuhriksi tehtämän, ja toinen polttouhriksi, Leviläisiä sovittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Ja sinun pitää asettaman Leviläiset Aaronin ja hänen poikainsa eteen, ja häälyttämän heitä häälytykseksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Ja sinun pitää eroittaman Leviläiset Israelin lapsista, niin että Leviläiset pitää oleman minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Ja sitte pitää heidän käymän sisälle palvelemaan seurakunnan majassa, ja pitää sinun heitä puhdistaman, ja häälyttämän heitä häälytykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Sillä he ovat minulle peräti annetut Israelin lasten seasta, ja minä olen heidät ottanut minulleni kaikkein edestä, jotka ensisti avaavat äitinsä kohdun, nimittäin, kaikkein esikoisten edestä Israelin lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Sillä kaikki esikoiset Israelin lapsista ovat minun, sekä ihmisistä että eläimistä: sinä päivänä, kuin minä löin kaikki esikoiset Egyptin maalla, pyhitin minä ne minulleni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Ja otin minulleni Leviläiset, kaikkein esikoisten edestä Israelin lapsista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Ja annoin Leviläiset Aaronille ja hänen pojillensa lahjaksi Israelin lapsista, että heidän pitää seurakunnan majassa Israelin lasten virassa palveleman, ja sovittaman Israelin lapset, ettei rangaistus tulisi Israelin lasten päälle, jos he lähestyisivät pyhää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Ja Moses ynnä Aaronin kanssa, ja koko Israelin seurakunta tekivät Leviläisille kaikki niinkuin Herra oli Mosekselle käskenyt; niin tekivät Israelin lapset heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Ja Leviläiset puhdistivat itsensä, ja pesivät vaatteensa, ja niin Aaron häälytti heidät häälytykseksi Herran edessä, ja sovitti heitä niin että he puhdistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Ja sitte Leviläiset menivät seurakunnan majaan, virkaansa tekemään Aaronin ja hänen poikainsa eteen: niinkuin Herra oli Mosekselle käskenyt Leviläisistä, niin tekivät he heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Tämä on se minkä Leviläisten pitää pitämän: viidennestä vuodesta kolmattakymmentä ja sen ylitse, ovat he kelvolliset sotaan menemään ja palvelemaan seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Mutta viidennestäkymmenestä vuodesta pitää heidän vapaat oleman palveluksensa virasta, ja ei pidä enää palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Mutta heidän pitää veljeinsä palveluksesta seurakunnan majassa ottaman vaarin; mutta viran töitä ei heidän pidä tekemän. Näin sinun pitää tekemän Leviläisille heidän vartiossansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Ja Herra puhui Mosekselle Sinain korvessa, toisena vuonna sittekuin he olivat lähteneet Egyptin maalta, ensimäisenä kuukautena, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Israelin lasten pitää pääsiäistä pitämän määrätyllä ajallansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Neljäntenätoistakymmenentenä päivänä tällä kuulla kahden ehtoon välillä, pitää heidän sen pitämän, ajallansa: kaikkein säätyinsä ja kaikkein oikeuttensa jälkeen pitää teidän sen tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Ja Moses puhui Israelin lapsille, että heidän piti pääsiäistä pitämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Ja he pitivät pääsiäistä neljäntenä päivänä toistakymmentä ensimäisellä kuulla, kahden ehtoon välillä, Sinain korvessa: kaiken sen jälkeen minkä Herra oli Mosekselle käskenyt, niin tekivät Israelin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Niin siellä oli muutamia miehiä, jotka olivat saastaantuneet kuolleessa ihmisessä, niin ettei he saaneet pitää pääsiäistä sinä päivänä, ja he menivät sinä päivänä Moseksen ja Aaronin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Ja ne miehet sanoivat hänelle: me olemme saastaantuneet kuolleesta ihmisestä: miksi me niin ylönkatsottuna pidetään, ettemme saa uhrata lahjojamme aikanansa Israelin lasten seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Ja Moses sanoi heille: seisokaat, minä tahdon kuulla, mitä Herra käskee teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Puhu Israelin lapsille, sanoen: kuka ikänä saastuttaa itsensä kuolleessa, elikkä on taampana kaukaisella matkalla teistä, taikka teidän lankoinne seassa, hänen pitää kuitenkin pitämän pääsiäistä Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Vaan toisella kuulla, neljäntenä päivänä toistakymmentä, kahden ehtoon välillä, pitää heidän sen tekemän, ja heidän pitää sen syömän happamattoman leivän ja karvasten ruohoin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Ei pidä heidän siitä mitäkään tähteeksi jättämän huomeneksi, eikä luuta siitä rikkoman: kaikkein pääsiäissäätyin jälkeen pitää heidän sen tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Mutta joka puhdas on, ja ei ole matkalla, ja unhottaa pitää pääsiäistä, hänen sielunsa pitää hävitettämän kansoistansa. Sentähden ettei hän ole kantanut uhrinansa Herralle määrätyllä ajallansa, sen pitää itse syntinsä kantaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Ja jos joku muukalainen asuu teidän seassanne, ja pitää myös Herralle pääsiäistä: pääsiäisen säätyin ja oikeutten jälkeen hänen sen pitämän pitää. Tämä sääty pitää teille yhtäläinen oleman, niin muukalaiselle kuin omaisellekin maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Ja sinä päivänä kuin Tabernakli pantiin ylös, varjosi pilvi todistuksen majan, ja oli ehtoosta niin aamuun asti majan päällä, niinkuin tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Niin tapahtui alati, että pilvi varjosi sen ja näkyi yöllä niinkuin tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Ja kuin pilvi nousi majan päältä, niin vaelsivat Israelin lapset, ja kuhunka paikkaan pilvi seisahti, siinä myös Israelin lapset heitänsä sioittivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Herran sanan jälkeen vaelsivat Israelin lapset, ja Herran sanan jälkeen he myös heitänsä sioittivat: aina niinkauvan kuin pilvi pysyi majan päällä, pysyivät he myös siallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Ja koska pilvi usiammat päivät pysyi majan päällä, niin ottivat Israelin lapset vaarin Herran vartiosta, ja ei vaeltaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Ja koska niin tapahtui, että pilvi oli järjestänsä monikahdat päivät majan päällä, niin he sioittivat heitänsä Herran sanan jälkeen, ja Herran sanan jälkeen he myös vaelsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Ja jos se niin tapahtui, että pilvi aina ehtoosta niin huomeneen asti oli majan päällä, ja sitte aamulla nousi, niin he vaelsivat, eli koska pilvi päivällä taikka yöllä nousi, niin he myös vaelsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Eli koska pilvi kaksi päivää eli kuukauden taikka muutoin kauvan aikaa pysyi majan päällä, niin Israelin lapset sioittivat heitänsä, ja ei matkustaneet, ja koska se nousi, niin he matkustivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Herran käskyn jälkeen olivat he siallansa, ja Herran käskyn jälkeen he matkustivat, ja ottivat vaarin Herran vartiosta, Herran sanan jälkeen Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Tee sinulles hopiasta kaksi torvea, vahvaksi sinun ne tekemän pitää, niillä kutsuakses seurakuntaa kokoon, ja koska joukon pitää matkustaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Koska niillä molemmilla hiljaksensa soitetaan, silloin pitää koko seurakunnan kokoontuman seurakunnan majan oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Vaan koska ainoastaan yhdellä hiljaksensa soitetaan, silloin pitää päämiehet ja tuhanten esimiehet Israelissa tuleman kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Mutta koska te vahvasti soitatte, silloin pitää ne leirit lähtemän matkaan, jotka itään päin ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Mutta koska te toisen kerran vahvasti soitatte, silloin pitää ne leirit lähtemän matkaan, jotka etelään päin ovat; sillä koska he lähtevät matkaan, niin pitää teidän vahvasti soittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Mutta koska seurakunnan pitää kokoontuman, silloin teidän pitää ainoastansa hiljaksensa, ja ei vahvasti soittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Ja papit Aaronin pojat pitää näillä torvilla soittaman: ja tämä pitää teille ja teidän sukukunnillenne oleman ijankaikkinen sääty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Ja koska te lähdette sotaan teidän maallanne vihollisianne vastaan, jotka teitä vainoovat, silloin pitää teidän vahvasti torvilla soittaman, että teitä muistettaisiin Herran teidän Jumalanne edessä, ja te pelastettaisiin vihollisistanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Niin myös teidän ilopäivinänne, ja teidän juhlapäivinänne, ja teidän uusissa kuissanne, pitää teidän torvilla soittaman, teidän polttouhrianne ja kiitosuhrianne uhratessanne, että ne olisivat teille muistoksi teidän Jumalanne edessä. Minä Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Ja tapahtui kahdentenakymmenentenä päivänä, toisena kuukautena toisena vuonna, että pilvi nostettiin todistuksen majan tyköä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Ja Israelin lapset läksivät matkaansa järjestyksessä Sinain korvesta, ja pilvi seisahti Paranin korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Ja he läksivät ensimäisen kerran Herran sanan jälkeen Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Nimittäin Juudan lasten leirin lippu läksi ensin matkaan joukkoinensa, ja heidän joukkonsa päällä oli Nahesson Amminadabin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Ja Isaskarin lasten suvun joukon päällä oli Netaneel Suarin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Ja Sebulonin lasten suvun joukon päällä oli Eliab Helonin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Silloin maja otettiin maahan: ja Gersonin ja Merarin lapset läksivät matkaan ja kantoivat majaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Sitälähin läksi Rubenin leirin lippu joukkoinensa, ja hänen joukkonsa päällä oli Elisur Sedeurin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Ja Simeonin lasten suvun joukon päällä oli Selumiel SuriSaddain poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Ja Gadin lasten suvun joukon päällä oli Eliasaph Deguelin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Niin matkustivat myös Kahatilaiset ja kantoivat pyhää, ja toiset panivat majan ylös, siihenasti että nämät tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Sitälikin läksi Ephraimin lasten leirin lippu joukkoinensa, ja hänen joukkonsa päällä oli Elisama Ammihudin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Ja Manassen lasten sukukunnan joukon päällä oli Gamliel Pedatsurin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Ja BenJaminin lasten sukukunnan joukon päällä oli Abidan Gideonin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Sitälikin läksi Danin lasten leirin lippu joukkoinensa. Ja niin kaikki leirit matkassansa olivat. Ja hänen joukkonsa päällä oli AhiEser AmmiSaddain poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Ja Asserin lasten sukukunnan joukon päällä oli Pagiel Okranin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Ja Naphtalin lasten sukukunnan joukon päällä oli Ahira Enanin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Nämät ovat Israelin lasten vaellukset joukkoinensa, koska he matkustivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Ja Moses puhui näälämiehellensä Hobabille Reguelin Midianilaisen pojalle: me menemme siihen paikkaan, josta Herra sanonut on: minä annan sen teille. Tule meidän kanssamme, me teemme sinulle hyvää, sillä Herra on hyvää luvannut Israelille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Hän vastasi häntä: en minä tule teidän kanssanne, vaan minä menen omalle maalleni sukuni tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Hän sanoi: älä meistä luovu, sillä sinä tiedät, kussa meidän pitää itsemme sioittaman korvessa, ja sinä olet meidän silmämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Ja jos sinä tulet meidän kanssamme, niin se hyvä, minkä Herra meille tekee, sen me teemme sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Niin he matkustivat kolme päiväkuntaa Herran vuoren tyköä, ja Herran liiton arkki vaelsi heidän edellänsä kolme päiväkuntaa, katsomaan heille, kussa heidän lepäämän piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Ja Herran pilvi oli heidän päällänsä päivällä, koska he leiristä matkustivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Ja koska arkki läksi matkaan, sanoi Moses: Herra nouse, että vihollises hajotettaisiin, ja ne, jotka sinua vainoovat, pakenisivat sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Koska arkki lepäsi, sanoi hän: Palaja, Herra, niiden monen kymmenen tuhannen tykö Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Ja tapahtui, koska kansa kärsimättömyydestä napisi, oli se paha Herran korvissa, ja koska Herra sen kuuli, julmistui hänen vihansa, ja Herran tuli syttyi heidän seassansa, joka äärimäiset heidän leirissänsä poltti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Silloin huusi kansa Moseksen tykö, ja Moses rukoili Herraa, niin tuli asettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Ja se paikka kutsuttiin Tabeera, että Herran tuli oli syttynyt heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Mutta sekalainen kansa heidän seassansa oli syttynyt himoon, ja Israelin lapset myös rupesivat taas itkemään ja sanoivat: kuka antaa meille lihaa syödäksemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Me muistamme ne kalat, joita me söimme ilman maksota Egyptissä, ja ne agurkit, ja melonit, ja puurlaukat, ja sipulit, ja kynsilaukat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Mutta nyt on sielumme kuivettunut, ja ei ole ikänä mitään, paitsi tämä manna on meidän silmäimme edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Ja man oli niinkuin korianderin siemen, ja nähdä niinkuin bedellion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Ja kansa juoksi sinne ja tänne, ja kokosi sitä, ja jauhoi myllyllä eli survoi rikki huhmaressa, ja keitti padassa, ja teki itsellensä siitä paistinkakkuja, ja ne maistivat niinkuin öljyleivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Ja koska kaste yöllä laskeusi leiriin, niin laskeusi myös manna sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Ja Moses kuuli kansan itkevän sukukunnissansa, itsekunkin majansa ovella, ja Herran viha julmistui suuresti, ja Moses myös pani sen pahaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Ja Moses sanoi Herralle: miksi sinä niin ahdistat palveliaas? ja miksi en minä löydä armoa sinun edessäs, ettäs panet kaiken tämän kansan kuorman minun päälleni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Olenko minä kaiken tämän kansan siittänyt? olenko minä synnyttänyt hänen? ettäs niin sanoit minulle: kanna heitä helmassas, niinkuin elatusisä kantaa imevän lapsen, siihen maahan, jonka sinä heidän isillensä vannoit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Mistä minä otan lihaa kaikelle tälle kansalle antaakseni? sillä he itkevät minun edessäni ja sanovat: anna meille lihaa syödäksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'En minä yksinäni voi kaikkea tätä kansaa kantaa; sillä se on minulle ylen raskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Ja jos sinä niin teet minulle, niin lyö minut kohta kuoliaaksi, jos minä muutoin olen armon löytänyt sinun edessäs, ettei minun niin täytyisi onnettomuuttani nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Ja Herra sanoi Mosekselle: kokoa minulle seitsemänkymmentä miestä Israelin vanhimmista, jotkas tiedät vanhimmiksi ja päämiehiksi kansan seassa, ja tuo heitä seurakunnan majan oven eteen, ja seisokaat siinä sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Ja minä tulen alas, ja puhun siellä sinun kanssas, ja otan siitä hengestä joka sinun ylitses on ja annan heille, että he ynnä sinun kanssas kantaisivat kansan kuorman, ettet sinä yksinäs sitä kantaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Ja sano kansalle: pyhittäkäät teitänne huomeneksi, että te lihaa söisitte; sillä teidän itkunne on tullut Herran korviin ja te sanoitte: kuka antaa meille lihaa syödäksemme? sillä hyvin me elimme Egyptissä; ja Herra antaa teille lihaa syödäksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Ei vaivoin päiväksi, eikä kahdeksi syödäksenne, eikä viideksi, eikä kymmeneksi, eikä kahdeksikymmeneksi päiväksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Mutta koko kuukaudeksi, siihen asti että se käy teidän sieramistanne ulos, ja tulee teille kyylytykseksi; sillä te olette Herran hyljänneet, joka on teidän seassanne, ja itkitte hänen edessänsä, ja sanoitte: miksi me olemme tänne lähteneet Egyptistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Ja Moses sanoi: tämä kansa on kuusisataa tuhatta jalkamiestä, joidenka seassa minä olen, ja sinä sanot: minä annan heille lihaa syödäksensä koko kuukaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Tapetaanko lampaat ja karja, että he ravittaisiin? taikka kootaanko kaikki kalat merestä heille, että he ravittaisiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Herra sanoi Mosekselle: onko Herran käsi lyhennetty? Nyt sinun pitää näkemän, jos minun sanani jälkeen tapahtuu sinulle elikkä ei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Ja Moses meni ulos ja sanoi kansalle Herran sanat, ja kokosi seitsemänkymmentä miestä kansan vanhimmista ja asetti heidät ympäri majaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Niin tuli Herra alas pilvessä, ja puhui hänen kanssansa, ja otti siitä hengestä, joka oli hänen päällänsä, ja antoi seitsemällekymmenelle vanhimmalle miehelle. Ja tapahtui, koska henki lepäsi heidän päällänsä, niin he ennustivat; vaan ei sitte enää kertoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Mutta kaksi miestä jäi vielä leiriin, yhden nimi oli Eldad ja toisen nimi Medad, joiden päällä myös henki lepäsi; sillä he olivat myös kirjoitetut, vaan ei he vielä olleet käyneet ulos majan tykö, ja he ennustivat leirissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Niin juoksi nuorukainen ja ilmoitti Mosekselle, ja sanoi: Eldad ja Medad ennustavat leirissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Niin vastasi Josua Nunin poika, Moseksen palvelia, jonka hän valinnut oli, ja sanoi: minun herrani Moses! kiellä heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mutta Moses sanoi hänelle: oletko sinä minun edessäni kiivas? Jospa kaikki Herran kansa ennustaisi! Ja Herra antais henkensä tulla heihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Ja niin Moses ja Israelin vanhimmat palasivat leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Niin tuli tuuli Herralta ja ajoi peltokanat merestä, ja hajoitti ne leiriin, täältäpäin päiväkunnan matkan, ja sieltäpäin päiväkunnan matkan leirin ympärille, liki kahta kyynärää korkialle maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Niin nousi kansa koko sinä päivänä, ja koko sinä yönä, ja koko toisena päivänä, ja kokosi peltokanoja, ja se, joka vähimmän kokosi, hän kokosi kymmenen homeria, ja he leivittivät ne kohta ympäri leiriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Koska liha oli vielä heidän hammastensa välillä, ja ennenkuin se tuli kuluneeksi, julmistui Herran viha kansan päälle, ja Herra löi heitä sangen suurella rangaistuksella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Josta se paikka kutsutaan Himohaudaksi; sillä siihen on haudattu himoitseva kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Ja kansa matkusti Himohaudoilta Hatserotiin ja pysähtyi Hatserotissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Ja MirJam ja Aaron puhuivat Mosesta vastaan hänen Etiopilaisen emäntänsä tähden, jonka hän nainut oli, että hän Etiopilaisen nainut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Ja sanoivat: puhuuko Jumala ainoastaan Moseksen kautta? eikö hän myös puhu meidän kauttamme? Ja Herra kuuli sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Mutta Moses oli sangen siviä mies, enempi kuin kaikki muut ihmiset maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Ja Herra sanoi äkisti Mosekselle, Aaronille ja MirJamille: menkäät te kolme seurakunnan majaan. Ja he kaikki kolme menivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Niin Herra tuli alas pilven patsaassa, ja seisoi majan ovella, ja kutsui Aaronin ja MirJamin, ja he molemmat menivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Ja hän sanoi: kuulkaat nyt minun sanojani: jos joku on teidän seassanne propheta, minä Herra ilmestyn hänelle näyssä, ja unessa puhuttelen häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Vaan ei niin palveliani Moses, joka koko minun huoneessani uskollinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Hänen kanssansa minä puhun suusta suuhun ja näkyväisesti, ja ei tapauksilla, ja hän näkee Herran muodon. Miksi ette te siis peljänneet puhua palveliaani Mosesta vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Ja Herran viha julmistui heidän päällensä, ja hän meni pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Niin myös pilvi meni pois majan päältä. Ja katso, niin MirJam tuli kohta spitaliin niinkuin lumi: niin Aaron käänsi itsensä MirJamia päin, ja katso, hän oli spitalissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Sanoi siis Aaron Mosekselle: Ah minun herrani! älä pane tätä syntiä meidän päällemme: sillä me olemme tyhmästi tehneet, ja me olemme syntiä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Ettei tämä nyt tulisi niinkuin kuollut, jonka puoli lihaa on kulunut lähteissänsä äitinsä kohdusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Niin Moses huusi Herralle ja sanoi: Ah Jumala, paranna häntä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Ja Herra sanoi Mosekselle: jos hänen isänsä olis hänen kasvoillensa sylkenyt, eikö hänen olisi pitänyt häpeemän seitsemän päivää? Anna sulkea hänen seitsemäksi päiväksi leiristä ulos, ja sitte hän jälleen otettakaan sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Niin MirJam suljettiin seitsemäksi päiväksi leiristä, ja ei kansa matkustanut, ennenkuin MirJam otettiin takaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Ja sitte kansa matkusti Hatserotista ja sioitti itsensä Paranin korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Lähetä miehet edelläs vakoomaan Kanaanin maata, jonka minä Israelin lapsille annan: yksi mies itsekustakin isänsä suvusta pitää lähetettämän, kukin päämies heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Ja Moses lähetti heidät Paranin korvesta Herran sanan jälkeen: kaikki ne olivat Israelin lasten päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Ja nämät ovat heidän nimensä: Rubenin sukukunnasta, Sammua Sakkurin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Simeonin sukukunnasta, Saphat Horin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Juudan sukukunnasta, Kaleb Jephunnen poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Isaskarin sukukunnasta, Igeal Josephin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Ephraimin sukukunnasta, Hosea Nunin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'BenJaminin sukukunnasta, Palti Raphun poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Sebulonin sukukunnasta, Gaddiel Sodin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Josephin sukukunnasta, Manassesta, Gaddi Susin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Danin sukukunnasta, Ammiel Gemallin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Asserin sukukunnasta, Setur Mikaelin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Naphtalin sukukunnasta, Nakbi Vopsin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Gadin sukukunnasta, Guel Makin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Nämät ovat niiden miesten nimet, jotka Moses lähetti vakoomaan maata, ja Hosean Nunin pojan nimitti Moses Josuaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Koska Moses lähetti heidät vakoomaan Kanaanin maata, sanoi hän heille: menkäät etelän puoleen, ja astukaat vuorelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Katselkaat maata, millainen se on, ja kansaa, joka siinä asuu, onko se väkevä eli heikko, vähä eli paljo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Ja millainen maa se on, jossa he asuvat, onko se hyvä eli paha, ja minkäkaltaiset kaupungit ovat, joissa he asuvat, asuvatko he majoissa eli linnoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Ja millainen maa on, lihava eli laiha, ja onko puita sillä maalla, taikka ei. Olkaat vahvassa turvassa, ja ottakaat maan hedelmää. Ja se oli siihen aikaan jona viinamarjat ensisti kypsyneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Ja he menivät ja vakoivat maan Zinin korvesta Rehobiin asti, jonka kautta Hamatiin mennään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'He menivät myös etelään päin ja tulivat Hebroniin: siellä oli Abkiman, Sesai ja Talmai, Enakin lapset. Ja Hebron oli rakennettu seitsemän ajastaikaa ennen kuin Zoan Egyptissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Ja tulivat hamaan Eskolin ojan tykö, ja leikkasivat sieltä viinapuun oksan viinamarjarypäleen kanssa, ja kaksi kantoi sitä korennolla, niin myös granatin omenia ja fikunia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Ja se paikka kutsuttiin Eskolin virraksi, sen viinamarjarypäleen tähden, jonka Israelin lapset sieltä leikkasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Ja he palasivat maata vakoomasta neljänkymmenen päivän perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Ja he kävivät, ja tulivat Moseksen ja Aaronin tykö, ja kaiken Israelin lasten seurakunnan tykö, Paranin korpeen Kadeksessa, ja ilmoittivat heille asian ja koko joukolle, millainen se oli, ja osoittivat heille maan hedelmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Ja he juttelivat hänelle, ja sanoivat: me tulimme sille maalle, johonka sinä meitä lähetit, jossa myös rieskaa ja hunajaa vuotaa, ja tämä on hänen hedelmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Paitsi sitä, että siinä maakunnassa asuu väkevä kansa, ovat siellä juuri vahvat ja suuret kaupungit, ja me näimme siellä myös Enakin pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalekilaiset asuvat etelän puolella maata, Hetiläiset ja Jebusilaiset ja Amorilaiset asuvat vuorilla. Kanaanealaiset asuvat meren tykönä ja Jordanin vierellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Mutta Kaleb vaikitti kansaa Moseksen edessä, ja sanoi: käykäämme rohkiasti ja omistakaamme maa; sillä kyllä me sen voitamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Mutta ne miehet, jotka hänen kanssansa olivat menneet, sanoivat: emme taida mennä sitä kansaa vastaan; sillä he ovat meitä väkevämmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Ja he saattivat maan, jonka he katselleet olivat, pahaan huutoon Israelin lasten seassa, sanoen: maa, jonka lävitse me kävimme vakoomassa sitä, syö asujansa, ja kaikki kansa, jonka me siellä näimme, ovat juuri pitkät ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Me näimme siellä myös hirmuiset Enakin pojat, jättiläisiä: ja me olimme meidän silmäimme edessä (nähdä) niinkuin heinäsirkat, ja niin olimme myös me heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Niin kaikki seurakunta nousi ja rupesi parkumaan, ja kansa itki sen yön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Ja kaikki Israelin lapset napisivat Mosesta ja Aaronia vastaan, ja koko joukko sanoi heille: jospa olisimme kuolleet Egyptin maalla! taikka jospa tässä korvessa vielä kuolisimme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Miksi Herra vie meitä tälle maalle miekalla surmattaa! Meidän vaimomme ja lapsemme tulevat saaliiksi! Eikö parempi ole, että palajamme Egyptiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Ja he sanoivat toinen toisellensa: asettakaamme päämies ja palatkaamme Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Niin Moses ja Aaron lankesivat kasvoillensa, koko Israelin lasten seurakunnan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Ja Josua Nunin poika, ja Kaleb Jephunnen poika, jotka myös maan olivat vaonneet, repäisivät vaatteensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Ja puhuivat kaikelle Israelin kokoukselle, sanoen: maa, jonka lävitse me vaeltaneet olemme vakoomassa sitä, on juuri hyvä maa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Jos Herralla on hyvä suosio meihin, niin hän vie meidät sille maalle, ja antaa sen meille: se on maa, jossa rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Ainoastansa älkäät olko Herraa vastaan niskurit, ja älkäät te peljätkö tämän maan kansaa; sillä me syömme heitä niinkuin leipää: heidän turvansa on erinnyt heistä, ja Herra on meidän kanssamme: älkäät peljätkö heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Niin sanoi koko kansan joukko, että he piti kivitettämän kuoliaaksi, ja Herran kunnia näkyi seurakunnan majassa kaikille Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Ja Herra sanoi Mosekselle: kuinka kauvan tämä kansa pilkkaa minua? ja kuinka kauvan ei he usko minun päälleni, kaikkein tunnustähtein kautta, jotka minä heidän seassansa tehnyt olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Minä lyön heitä ruttotaudilla, ja hävitän heitä, ja minä teen sinun suuremmaksi ja väkevämmäksi kansaksi, kuin tämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Ja Moses sanoi Herralle: jos Egyptiläiset saavat sen kuulla, joiden keskeltä sinä olet johdattanut tämän kansan sinun voimallas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Ja ne sanovat tämän maan asuvaisille, jotka kuulleet ovat, että sinä Herra olet tämän kansan seassa, ja että sinä Herra nähdään kasvoista niin kasvoihin, ja sinun pilves seisoo heidän päällänsä, ja sinä käyt heidän edellänsä, päivällä pilven patsaassa ja yöllä tulen patsaassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Jos sinä tapat tämän kansan, niinkuin yhden miehen, niin pakanat, jotka sanoman sinusta kuulleet ovat, puhuvat ja sanovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Ei Herra voinut johdattaa tätä kansaa siihen maahan, jonka hän heille vannoi; sentähden on hän heidät surmannut korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Nyt siis enentäkään Herra voimansa, niinkuin sinä puhunut olet, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Herra on pitkämielinen ja sangen laupias, ja antaa anteeksi vääryydet ja rikokset, ja ei yhtään viallista pidä viatoinna, mutta kostaa isäin vääryydet lapsille kolmanteen ja neljänteen polveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Niin ole armollinen tämän kansan rikokselle, sinun suuresta laupiudestas, niinkuin sinä tälle kansalle annoit anteeksi hamasta Egyptistä tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Ja Herra sanoi: minä annoin sen heille anteeksi, sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mutta niin totta kuin minä elän, niin koko maailma täytetään Herran kunnialla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Sillä kaikki miehet, jotka näkivät minun kunniani ja ihmeeni, jotka minä tein Egyptissä ja korvessa, ja nyt kymmenen kertaa ovat minua kiusanneet, eikä kuulleet minun ääntäni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Ei heidän pidä näkemän sitä maata, jonka minä heidän isillensä vannoin, eikä yksikään, joka minua pilkannut on, pidä näkemän sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Vaan palveliani Kalebin, että toinen henki on hänen kanssansa ja hän uskollisesti seurasi minua, vien minä siihen maahan, jossa hän ennen oli, ja hänen siemenensä pitää sen perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Nyt siis että Amalekilaiset ja Kanaanealaiset väjyvät laaksoissa, niin palatkaat huomenna ja matkustakaat korpeen, Punaisen meren tietä myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Kuinka kauvan tämä paha joukko napisee minua vastaan? Sillä minä kuulin Israelin lasten napinan, jolla he minua vastaan napisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Sentähden sano heille: niin totta kuin minä elän, sanoo Herra, minä teen teille, niinkuin te minun korvaini kuullen puhuitte:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Teidän ruumiinne pitää lankeeman tässä korvessa ja kaikki teidän luettunne, jotka luettiin kahdenkymmenen vuotisista ja sen ylitse, jotka napisitte minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Ei teidän pidä tuleman siihen maahan, jonka ylitse minä käteni nostin, salliakseni teidän siellä asua, paitsi Kalebia Jephunnen poikaa, ja Josuaa Nunin poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Vaan teidän lapsenne, jotka te sanoitte tulevan saaliiksi, minä sinne johdatan, että he tuntisivat sen maan, jonka te hylkäsitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Mutta te ja teidän ruumiinne pitää lankeeman tässä korvessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Ja teidän lapsenne pitää oleman paimenina tässä korvessa, neljäkymmentä ajastaikaa, kantaen teidän huoruuttanne, siihenasti että ruumiinne kuluvat korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Niiden neljänkymmenen päiväluvun jälkeen, joina te maan vaonneet olette, aina ajastaika päivästä pitää luettaman, että teidän pitää kantaman pahat tekonne neljäkymmentä ajastaikaa, että te ymmärtäisitte minun pois luopumiseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Minä Herra olen sen puhunut, sen minä myös teen kaikelle tälle pahalle joukolle, joka on itsensä asettanut minua vastaan: tässä korvessa pitää heidän kuluman ja siinä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Ja ne miehet, jotka Moses lähetti maata vakoomaan ja palasivat, saattaen kaiken kansan napisemaan häntä vastaan, ja olivat tuottaneet pahan sanoman maasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Ne miehet kuolivat Herran rangaistuksesta, jotka toivat pahan sanoman maasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Mutta Josua Nunin poika ja Kaleb Jephunnen poika jäivät elämään kaikista niistä miehistä, jotka menneet olivat maata vakoomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Ja Moses puhui kaikki nämät sanat kaikille Israelin lapsille: silloin kansa murehti suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Ja he nousivat varhain huomeneltain ja menivät vuoren kukkulalle, ja sanoivat: katso, tässä me olemme, ja menemme siihen paikkaan, josta Herra on puhunut; sillä me olemme syntiä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mutta Moses sanoi: miksi te niin rikotte Herran sanan? ei se teille menesty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Älkäät menkö, sillä ei ole Herra teidän kanssanne, ettette lyötäisi teidän vihollisiltanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Sillä Amalekilaiset ja Kanaanealaiset ovat siellä teidän edessänne, ja miekalla surmataan, että te itsenne käänsitte pois Herrasta: ja ei ole Herra teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Mutta he rohkaisivat itsensä menemään vuoren kukkulalle, vaan Herran liitonarkki ja Moses ei menneet leiristä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Niin tulivat Amalekilaiset ja Kanaanealaiset, jotka vuorella asuivat, ja löivät heidät ja runtelivat heitä hamaan Hormaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Puhu Israelin lapsille ja sano heille: koska te tulette siihen maahan, jossa teidän asuman pitää, jonka minä teille annan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'Ja te uhraatte Herralle tuliuhria, polttouhria, elikkä erinomaisen lupauksen uhria, eli oman hyvän tahdon, eli teidän juhlanne uhria, tehdäksenne Herralle makiaa hajua karjasta eli lampaista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Joka siis Herralle tahtoo mieluisesti uhrata lahjansa, hänen pitää tekemän ruokauhriksi kymmeneksen sämpyläjauhoja, sekoitettuja neljänneksellä hinniä öljyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Ja viinaa juomauhriksi myös neljänneksen hinniä: sen pitää sinun tekemän polttouhriksi eli muuksi uhriksi, koska karitsa uhrataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Eli koska oinas uhrataan, niin pitää sinun tekemän ruokauhriksi kaksi kymmenestä sämpyläjauhoja, sekoitettuja kolmanneksella hinniä öljyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Ja viinaa juomauhriksi myös kolmas osa hinniä: sen sinun pitää uhraaman Herralle lepytyshajuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Mutta jos sinä teet mullin polttouhriksi taikka teurasuhriksi tahi erinomaisen lupauksen uhriksi, tahi kiitosuhriksi Herralle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Niin sinun pitää mullin kanssa tekemän ruokauhriksi kolme kymmenestä sämpyläjauhoja, sekoitettuja puoleen hinniin öljyä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Ja viinaa juomauhriksi myös puoli hinniä: tämä on tuliuhri makiaksi hajuksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Niin sinun pitää tekemän kunkin mullin kanssa, oinaan, lampaan, karitsan ja vohlan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Sen luvun jälkeen kuin te yhdelle teette, niin pitää teidän tekemän kullekin heidän lukunsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Jokainen omainen pitää tämän näin tekemän, uhrataksensa ne Herralle lepytyshajun tuleksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Ja jos joku muukalainen asuu teidän tykönänne, eli on teidän sukuinne seassa, ja tahtoo tehdä Herralle tuliuhria makiaksi hajuksi, hän tehkään niinkuin teidän tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Kaikella kansalla pitää oleman yksi sääty, sekä teillä että muukalaisilla. Ijankaikkinen sääty pitää se oleman teidän sukukunnillenne, niin että Herran edessä pitää muukalaisen oleman niinkuin tekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Yksi laki ja yksi oikeus pitää oleman teillä ja muukalaisilla, jotka asuvat teidän tykönänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Puhu Israelin lapsille, ja sano heille: tultuanne siihen maahan, johon minä teidät johdatan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Ja syötyänne sen maan leipää, pitää teidän antaman ylennysuhrin Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Taikinanne alkeista pitää teidän antaman yhden kyrsän ylennykseksi: niinkuin te annatte Herralle ylennyksen teidän riihestänne, niin pitää teidän myös tämän ylennyksen tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Niin pitää teidän myös antaman Herralle taikinanne alkeista ylennykseksi, teidän sukukunnissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Ja jos te tietämättä eksytte, ja ette tee kaikkia näitä käskyjä, joita Herra Mosekselle käskenyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Kaikki mitä Herra Moseksen kautta teille käskenyt on, siitä päivästä, jona hän rupesi käskemään, niin teidän lapsiinne asti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Jos siis koko kansa jossakin tietämättömyydestä erehtyy, niin pitää kaiken kansan tekemän polttouhriksi nuoren mullin karjasta, makiaksi hajuksi Herralle heidän ruokauhrinsa ja juomauhrinsa kanssa, kuin se tulee heidän tehdäksensä, ja yhden kauriin syntiuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Ja papin pitää näin sovittaman koko joukon Israelin lapsista, ja se heille annetaan anteeksi; sillä se on tietämättömyys. Ja heidän pitää kantaman lahjansa tuliuhriksi Herralle, ja syntiuhrinsa Herran eteen tietämättömyytensä tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Niin se annetaan anteeksi koko Israelin lasten joukolle, niin myös muukalaisille, jotka asuvat heidän seassansa; sillä kaikki kansa on siinä tietämättömyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Mutta kuin yksi sielu tietämätä syntiä tekee, hänen pitää tuoman vuosikuntaisen vuohen syntiuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Ja papin pitää eksyneen sielun sovittaman, koska hän tietämättömyydestä syntiä tekee Herran edessä, niin että hän sovittaa hänen, ja se annetaan hänelle anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Ja sekä omaisille Israelin lasten seassa että muukalaisille, jotka heidän seassansa asuvat, pitää yhden lain oleman kuin teidän pitää tekemän tietämättömyyden edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mutta jos joku sielu ilkivaltaisuudesta jotakin tekee, olkoon omainen eli muukalainen, se pilkkaa Herraa: ja se sielu pitää hävitettämän kansastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Sillä hän on Herran sanan katsonut ylön, ja hänen käskynsä tyhjäksi tehnyt: se sielu pitää peräti hävitettämän, ja olkoon oma nuhteensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Ja tapahtui, että Israelin lapset korvessa ollessansa löysivät miehen puita hakemasta sabbatina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Ja ne jotka hänen olivat löytäneet puita hakemasta, veivät hänen Moseksen ja Aaronin eteen, ja kaiken kansan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Ja he panivat hänen kiinni; sillä ei se ollut vielä päätetty, mitä hänelle piti tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Mutta Herra sanoi Mosekselle: sen miehen pitää totisesti kuoleman: kaiken kansan pitää häntä kivittämän kuoliaaksi, ulkona leiristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Niin kaikki kansa vei hänen leiristä ulos, ja kivitti hänen kuoliaaksi, niinkuin Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Puhu Israelin lapsille, ja sano heille: että heidän pitää tekemän tilkoja vaatettensa liepeisiin, sukukunnillensa, ja heidän pitää paneman sinisen langan niiden tilkain päälle, jotka ovat heidän vaatettensa liepeissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Ja ne tilkat pitää oleman teille merkiksi, ja katsoissanne niiden päälle pitää teidän kaikki Herran käskyt muistaman ja tekemän ne, ettette tekisi teidän sydämenne ajatuksen jälkeen, ettekä myös huorin tekisi teidän silmäinne näyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Sentähden pitää teidän muistaman ja tekemän kaikki minun käskyni, ja oleman pyhät teidän Jumalallenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Minä olen Herra teidän Jumalanne, joka teidät Egyptin maalta ulos johdatin, ollakseni teidän Jumalanne: Minä Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Ja Kora Jetseharin poika, joka oli Levin pojan Kahatin poika, otti kanssansa Datanin ja Abiramin Eliabin pojat, ja Onin Peletin pojan Rubenin pojista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Ja he nousivat Mosesta vastaan: niin myös Israelin lapsista kaksisataa ja viisikymmentä miestä ylimmäisistä, kansalta kutsuttua, kuuluisaa miestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Ja he kokoontuivat Mosesta ja Aaronia vastaan, ja sanoivat heille: se on teille ylen paljo; sillä kansa on kaikki pyhä, ja Herra on heidän kanssansa, ja miksi te korotatte teitänne Herran kansan päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Koska Moses sen kuuli, lankesi hän kasvoillensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Ja puhui Koralle ja koko hänen seurallensa sanoen: huomenna Herra ilmoittaa kuka hänen omansa on, ja kuka pyhä on ja saa hänelle uhrata: jonka hän valitsee, se uhratkaan hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Tehkäät näin: ottakaat teillenne savuastiat, Kora ja kaikki hänen seuransa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'Ja pankaat niihin tulta, ja heittäkäät niihin suitsutusta Herran eteen huomenna, ja se mies, jonka Herra valitsee, olkoon pyhä: se on teille paljo, Levin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Ja Moses sanoi Koralle: kuulkaat nyt Levin lapset!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Vähäkö se teille on, että Israelin Jumala on teidät eroittanut Israelin kansasta ja antanut tulla tykönsä palvelusta tekemään Herran Tabernaklin virassa, ja seisomaan seurakunnan edessä, ja heitä palvelemaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Hän on ottanut sinun ja kaikki sinun veljes Levin lapset tykönsä: ja te pyydätte myös pappeutta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Sinä ja kaikki sinun joukkos nostatte kapinan Herraa vastaan. Mikä Aaron on, että te napisette häntä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Ja Moses lähetti kutsumaan Datania ja Abiramia Eliabin poikia; mutta he sanoivat: emme sinne tule ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Vähäkö se on, että sinä olet meidät maalta tuonut ulos, jossa rieskaa ja hunajaa vuotaa, tappaakses meitä korvessa, vaan teet sinus vielä päämieheksi meidän ylitsemme, ja tahdot myös hallita meitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Jalosti sinä olet meidät johdattanut siihen maahan, jossa rieskaa ja hunajaa vuotaa, ja annoit pellot ja viinamäet perinnöksi. Tahdotkos vielä näiltä miehiltä silmät puhkaista? emme tule sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Silloin vihastui Moses sangen kovin, ja sanoi Herralle: älä käännä sinuas heidän ruokauhrinsa puoleen! En minä heiltä ottanut aasiakaan, ja en ole heidän yhdenkään pahaa tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Ja Moses sanoi Koralle: sinä ja koko sinun joukkos pitää huomenna oleman Herran edessä, sinä ja he, ja Aaron,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Ja jokainen ottakoon savuastiansa, ja pankaan suitsutusta siihen, ja tuokaan Herran eteen, kukin savuastiansa, kaksisataa ja viisikymmentä savuastiaa, niin myös sinä ja Aaron kukin savuastianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Ja kukin otti savuastiansa, ja pani siihen tulen, ja heittivät siihen suitsutusta, ja seisoivat seurakunnan majan ovessa, Moses ja Aaron myös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Ja Kora kokosi heitä vastaan kaiken kansan, seurakunnan majan oven eteen: silloin Herran kunnia näkyi kaikelle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Eroittakaat teitänne tästä joukosta, niin minä äkisti heidät hukutan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Mutta he lankesivat kasvoillensa ja sanoivat: Jumala, kaiken lihan henkein Jumala! jos yksi mies on syntiä tehnyt, tahdotkos antaa vihas julmistua kaiken kansan päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Puhu kansalle ja sano: paetkaat Koran, Datanin ja Abiramin majain ympäriltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Ja Moses nousi ja meni Datanin ja Abiramin tykö, ja vanhimmat Israelista seurasivat häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Ja puhui kansalle, sanoen: paetkaat näiden jumalattomain ihmisten majain ympäriltä, ja älkäät ruvetko mihinkään heidän omaansa, ettette myös hukkuisi kaikissa heidän synneissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Ja he pakenivat Koran, Datanin ja Abiramin majain ympäriltä; mutta Datan ja Abiram kävivät ulos, ja seisoivat majainsa ovella emäntinensä, poikinensa ja lapsinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Ja Moses sanoi: siitä teidän pitää tietämän Herran minua lähettäneeksi, kaikkia näitä töitä tekemään, niin ettei se ole minun omasta sydämestäni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Jos he kuolevat niinkuin kaikki ihmiset kuolevat, eli kostetaan, niinkuin kaikille ihmisille kostetaan, niin ei Herra ole minua lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Mutta jos Herra tässä jotakin uutta tekee, niin että maa avaa suunsa ja nielee heidät kaikkein kanssa, mitä heillä on, niin että he elävinä menevät helvettiin, niin teidän pitää tietämän, että nämät miehet pilkkasivat Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Ja tapahtui, koska hän kaikki nämät sanat puhunut oli, halkesi maa heidän altansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Ja maa avasi suunsa ja nieli heidät, ja heidän huoneensa, ja kaikki ne ihmiset, jotka Koran tykönä olivat, ja kaiken heidän tavaransa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Ja he menivät elävänä helvettiin, kaikkinensa kuin heillä oli, ja maa peitti heidät, ja he hukkuivat kansan seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Ja koko Israel, joka heidän ympärillänsä oli, pakeni heidän parkunsa tähden. Sillä he sanoivat: ettei maa meitäkin nielisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Ja tuli läksi Herralta, ja poltti ne kaksisataa ja viisikymmentä miestä, jotka suitsutusta uhrasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Sano Eleatsarille papin Aaronin pojalle, että hän ottaa savuastiat tulipalosta, ja hajoittaa tulen sinne ja tänne; sillä ne ovat pyhät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Näiden savuastiat, jotka syntiä tekivät sielujansa vastaan, ne takokaat leveiksi, ohukaisiksi kiskoiksi, joilla alttari peitetään; sillä ne ovat Herran eteen uhratut ja pyhitetyt. Ja ne pitää oleman merkiksi Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Ja Eleatsar pappi otti ne vaskiastiat, joissa palaneet miehet olivat uhranneet, ja taotti ne leveiksi, ohukaisiksi kiskoiksi, alttarin peitteeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Israelin lapsille muistoksi, ettei yksikään muukalainen, joka ei ole Aaronin siemenestä, lähestyisi uhraamaan suitsutusta Herran eteen, ettei hänelle tapahtuisi, niinkuin Koralle ja hänen joukollensa, niinkuin Herra hänelle sanoi Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Toisena päivänä taas napisivat koko Israelin lasten joukko Mosesta ja Aaronia vastaan, ja sanoivat: te olette tappaneet Herran kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Ja koska kansa kokoontui Mosesta ja Aaronia vastaan, ja kuin he käänsivät heitänsä seurakunnan majaan päin, katso, pilvi peitti sen ja Herran kunnia näkyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Ja Moses ja Aaron menivät seurakunnan majan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Paetkaat tästä kansasta; sillä minä surmaan äkisti heidät, ja he lankesivat kasvoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Ja Moses sanoi Aaronille: ota savuastia, ja pane tulta siihen alttarilta, ja heitä suitsutusta siihen. Ja mene nopiasti kansan tykö ja sovita heitä: sillä vihan julmuus on Herralta käynyt ulos, ja rangaistus on jo alkanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Ja Aaron otti niinkuin Moses hänelle sanoi, ja juoksi kansan keskelle, ja katso, rangaistus oli jo ruvennut kansan seassa: ja hän suitsutti savutusta, ja sovitti kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Ja seisoi kuolleitten ja elävitten välillä; niin rangaistus asettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Mutta ne kuin rangaistuksesta kuolivat, oli neljätoistakymmentä tuhatta ja seitsemänsataa; paitsi niitä, jotka Koran kapinassa hukkuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Ja Aaron palasi Moseksen tykö, seurakunnan majan oveen ja rangaistus asettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Puhu Israelin lapsille, ja ota heiltä itsekultakin sauva isänsä huoneen jälkeen, kaikilta heidän päämiehiltänsä heidän isäinsä huoneen jälkeen, kaksitoistakymmentä sauvaa: kirjoita kunkin nimi hänen sauvaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Mutta Aaronin nimi kirjoita Levin sauvaan; sillä itsekullakin isänsä huoneen päämiehellä olkoon sauva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Ja pane ne seurakunnan majaan, todistuksen eteen, jossa minä olen teillä saapuvilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Ja jonka minä heistä valitsen, sen sauva pitää viheriöitsemän, että minä asettaisin Israelin lasten moninaisen napinan minun päältäni, jolla he teitä vastaan napisevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Niin Moses puhui Israelin lapsille: ja kaikki heidän päämiehensä antoivat hänelle kaksitoistakymmentä sauvaa, itsekukin päämies isänsä huoneesta yhden sauvan: ja Aaronin sauva oli heidän sauvainsa keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Ja Moses pani sauvat Herran eteen todistuksen majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Ja tapahtui toisena päivänä, että Moses meni todistuksen majaan: ja katso, Aaronin sauva levin huoneesta viheriöitsi: ja kukoistus puhkesi ja kukkainen tuli täydelliseksi ja kasvoi kypsiä mandelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Ja Moses kantoi kaikki sauvat ulos Herran edestä kaikkein Israelin lasten eteen: ja he näkivät sen, ja itsekukin otti sauvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Ja Herra sanoi Mosekselle: kanna Aaronin sauva jälleen todistuksen eteen tallella pidettää, merkiksi niskurille lapsille; että heidän napinansa minua vastaan lakkais, ettei he kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Ja Moses teki sen; niinkuin Herra hänelle käskenyt oli, niin hän teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Ja Israelin lapset puhuivat Mosekselle, sanoen: katso, me olemme riutumallamme! me hukumme, kaikki me hukumme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Kuka ikänä lähestyy Herran majaa, se kuolee. Hävitetäänkö meitä peräti?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Ja Herra sanoi Aaronille: sinä ja sinun poikas, ja sinun isäs huone sinun kanssas, kantakaat pyhän viat: ja sinä ja sinun poikas sinun kanssas, kantakaat pappeutenne viat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Mutta veljes isäs Levin suvusta ota kanssas, heidän pitää pysymän sinun tykönäs ja palveleman sinua: mutta sinä ja poikas sinun kanssas, palvelkaat todistuksen majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Ja he ottakaan vaarin sinun vartioistas, ja koko majan vartiosta: älkööt kuitenkaan lähestykö pyhän astioita ja alttaria, ettei sekä he ja te kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Mutta heidän pitää pysymän sinun tykönäs ottamassa vaarin seurakunnan majan vartioista kaikessa majan palveluksessa, eikä yhdenkään muukalaisen pidä teitä lähestymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Niin ottakaat siis vaari pyhän vartiosta ja alttarin vartiosta, ettei enää vihan julmuus Israelin lasten päälle tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Ja katso, minä otin teidän veljenne Leviläiset Israelin lasten seasta, ja annoin teille lahjaksi, jotka ovat Herran omat, ja pitää palveleman seurakunnan majan palveluksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Mutta sinä ja poikas sinun kanssas ottakaat pappeudestanne vaari, ja palvelkaat kaikissa alttarin asioissa ja sisällisellä puolella esirippua: sillä pappeutenne annan minä teille viran lahjaksi. Jos joku muukalainen lähestyy siihen, sen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Ja Herra sanoi Aaronille: katso, minä annoin sinun haltuus minun ylennysuhrini vartion: kaikki mitä Israelin lapset pyhittävät, annoin minä sinulle ja pojilles, lahjaksi, ijankaikkiseksi oikeudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Nämät sinä saat siitä kaikkein pyhimmästä, tuliuhrista: kaikki heidän lahjansa, ynnä kaiken heidän ruokauhrinsa, ja kaiken heidän syntiuhrinsa, ja myös kaiken heidän vikauhrinsa kanssa, mitkä he sinulle antavat, se on sinulle ja sinun pojilles kaikkein pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Ja kaikkein pyhimmällä sialla pitää sinun sen syömän. Kaikki miehenpuoli syökään sitä: sen pitää oleman sinulle pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Minä annoin myös sinulle ja sinun pojilles ja tyttärilles sinun kanssas heidän lahjansa ylennysuhrin, kaikissa Israelin lasten häälytysuhreissa, ijankaikkiseksi oikeudeksi. Jokainen puhdas sinun huoneessas syökään sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Kaikkein parhaan öljyn ja kaikkein parhaan vierteen, ja jyvät ja niiden uutisen, jotka he antavat Herralle, annoin minä sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Ensimäinen hedelmä kaikesta kuin heidän maallansa kasvaa, jonka he antavat Herralle, pitää oleman sinun. Jokainen puhdas sinun huoneessas syökään sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Kaikki valallisella lupauksella eroitettu Israelissa olkaan sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Kaikki mikä äitinsä kohdun avaa, kaiken lihan seassa, jotka he kantavat Herralle, olis se ihmisistä elikkä eläimistä, pitää oleman sinun. Kuitenkin, ettäs ihmisten esikoiset annat kaiketikin lunastettaa, ja myös saastaisten eläinten esikoiset annat lunastettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Ja kuukautisena pitää heidän sen lunastaman, ja annettakaan lunastettaa sinun arvios jälkeen rahalla, viidellä siklillä, pyhän siklin jälkeen, joka maksaa kaksikymmentä geraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Mutta esikoisia karjasta, taikka lampaista, taikka vuohista, ei sinun pidä antaman lunastettaa; sillä ne ovat pyhät: heidän verensä pitää sinun priiskottaman alttarille, ja lihavuutensa pitää sinun polttaman makian hajun tuleksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Ja heidän lihansa pitää oleman sinun, niinkuin häälytysrinta ja oikia lapa sinun ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Kaikki ylennysuhrit, jotka ovat pyhitetyt, jotka Israelin lapset ylentävät Herralle, annoin minä sinulle ja pojilles, ja tyttärilles sinun kanssas ijankaikkiseksi oikeudeksi. Se on katoomatoin ijankaikkinen liitto Herran edessä sinulle ja sinun siemenelles sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Ja Herra sanoi Aaronille: ei sinulle pidä perintöä oleman heidän maallansa eikä osaa heidän seassansa; sillä minä olen sinun osas ja sinun perintös Israelin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Mutta Levin lapsille, katso, minä annoin kaikki kymmenykset perinnöksi Israelissa, heidän virkansa edestä, jolla he palvelusta seurakunnan majassa tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Niin ettei tästälähin Israelin lasten pidä lähestymän seurakunnan majaa, syntiä saattamaan päällensä, ja kuolemaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Vaan Leviläisten pitää ottaman vaarin seurakunnan majan palveluksesta, ja heidän pitää kantaman syntinsä; se on ijankaikkinen oikeus teidän sukukunnissanne, ja ei pidä heidän perimistä saaman Israelin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Sillä Israelin lasten kymmenykset, jotka he antavat ylennykseksi Herralle, annoin minä Leviläisille perinnöksi; sentähden sanoin minä heille: ettei heillä Israelin lasten seassa pidä perintöä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Puhu Leviläisille ja sano heille: koska te otatte kymmenykset Israelin lapsilta, jotka minä teille annoin heiltä, teidän perinnöksenne, niin tehkäät Herralle siitä ylennysuhriksi aina kymmenysten kymmenykset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Ja teidän ylennysuhrinne pitää luettaman teille, niinkuin te antasitte jyviä riihestä ja nestettä kuurnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Niin antakaat myös Herralle ylennysuhriksi kaikista teidän kymmenyksistänne, joita te Israelin lapsilta otatte, niin että te Herran ylennysuhrin niistä annatte papille Aaronille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Kaikista teille annetuista antakaat Herralle kaikkinaiset ylennysuhrit, kaikista parhaista, pyhitettävän osan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Ja sano heille: koska te parhaan siitä ylennätte, niin luettakaan se Leviläisille niinkuin tulo riihestä ja viinakuurnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Ja syökäät siitä kaikissa paikoissa, te ja teidän huoneenne, sillä se on teidän palkkanne teidän palveluksestanne seurakunnan majassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Niin ettette synnillä raskauta teitänne, koska te sen parhaan ylennätte, ja ettekä saastuta niitä, mitkä Israelin lapset pyhittäneet ovat, ettette kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Ja Herra puhui Mosekselle ja Aaronille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Tämä tapa olkoon teille säädyksi, jonka Herra käski, sanoen: sanos Israelin lapsille, että he tuovat sinulle ruskian terveen lehmän, jossa ei yhtään virhettä ole, ja joka ei vielä ole ikeen alainen ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Ja antakaat se papille Eleatsarille: hänen pitää sen viemän leiristä ulos, siellä teurastettavaksi edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Ja papin Eleatsarin pitää ottaman sen verta sormellansa ja priiskottaman juuri seurakunnan majaa kohden sen verta seitsemän kertaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Ja antaman polttaa lehmän edessänsä, sekä hänen vuotansa että lihansa ja myös hänen verensä: ynnä sonnan kanssa se pitää poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Ja papin pitää ottaman sedripuun, ja isopin, ja tulipunaisen villan, ja heittämän sen palaneen lehmän päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Ja papin pitää pesemän vaatteensa ja viruttaman ruumiinsa vedellä, ja sitte tuleman leiriin: ja papin pitää oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Ja se, joka sen poltti, pitää myös pesemän vaatteensa ja viruttaman ruumiinsa vedellä ja oleman saastaisen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Ja puhdas mies pitää kokooman tuhan lehmästä, ja paneman sen puhtaasen paikkaan leiristä ulos, tallella pidettää, kaikelle kansalle Israelin lapsista puhdistusvedeksi: se on syntiuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Ja se, joka lehmän tuhan kokosi, pitää pesemän vaatteensa ja oleman saastainen ehtoosen asti. Tämä pitää oleman ijankaikkinen sääty Israelin lapsille, ja muukalaisille, jotka heidän seassansa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Joka tarttuu johonkuhun kuolleesen ihmiseen, sen pitää saastaisen oleman seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Hänen pitää tällä puhdistaman itsensä kolmantena ja seitsemäntenä päivänä, ja niin hän tulee puhtaaksi. Ja jollei hän puhdista itsiänsä kolmantena ja seitsemäntenä päivänä, niin ei ole hän puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Mutta jos joku tarttuu kuolleen ihmisen ruumiisen, ja ei puhdista itsiänsä, se saastuttaa Herran majan, ja se sielu pitää hävitettämän Israelista; ettei puhdistusvesi ole priiskotettu hänen päällensä, niin on hän saastainen: hänen saastaisuutensa on vielä hänen päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Tämä on laki, koska joku ihminen majassa kuolee: se joka siihen majaan menee, ja kaikki mitä majassa on, pitää oleman saastainen seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Ja jokainen avoin astia, joka on kannetoin ja peittämätä, se on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Ja jos joku tarttuu kedolla johonkuhun miekalla lyötyyn, elikkä muutoin kuolleesen, elikkä ihmisen luuhun, taikka hautaan, se on saastainen seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Niin ottakaat he saastaiselle, tätä poltetun syntiuhrin tuhkaa, ja pankaan sen päälle juoksevaa vettä astiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Ja puhdas mies ottakaan isoppia, ja kastakaan veteen ja priiskottakaan majan, ja kaikki astiat, ja kaikki sielut, jotka siellä ovat, niin myös sen päälle, joka on tarttunut (kuolleen) luuhun, eli tapettuun, taikka kuolleesen eli hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Niin puhdas priiskottakaan saastaista kolmantena ja seitsemäntenä päivänä, ja puhdistakaan hänen seitsemäntenä päivänä: hän peskään vaatteensa ja viruttakaan itsensä vedellä, niin hän ehtoona puhtaaksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Mutta joka saastaiseksi tulee, ja ei puhdista itsiänsä, se sielu pitää hävitettämän seurakunnasta, että hän on saastuttanut Herran pyhän, ja ei ole priiskotettu puhdistusvedellä, sentähden on hän saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Ja tämä on heille ijankaikkinen sääty. Ja joka puhdistusvedellä priiskotteli, se peskään myös vaatteensa. Ja se joka tarttuu puhdistusveteen, pitää oleman saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Ja kaikki, johonka saastainen rupee, pitää oleman saastainen ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Ja Israelin lapset tulivat kaiken seurakunnan kanssa Sinin korpeen, ensimäisellä kuulla, ja kansa viipyi Kadeksessa. Ja MirJam kuoli siellä, ja myös haudattiin sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Ja kansalla ei ollut vettä, ja he kokoontuivat Mosesta ja Aaronia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Ja kansa riiteli Moseksen kanssa, ja sanoivat: jospa olisimme hukkuneet siellä, kussa meidän veljemme hukkuivat Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Miksi olette vieneet tämän Herran Herran kansan tähän korpeen, kuolemaan täällä, sekä meitä että karjaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Ja miksi olette johdattaneet meidät Egyptistä, tuodaksenne meitä tähän pahaan paikkaan, jossa emme taida kylvää, jossa ei myös ole fikunia, taikka viinapuita, ei myös granatin omenia, eipä ole vettäkään juodaksemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Niin Moses ja Aaron menivät kansan tyköä seurakunnan majan ovelle ja lankesivat kasvoillensa, ja Herran kunnia näkyi heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Ota sauva, ja kokoa kansa, sinä ja veljes Aaron, ja puhukaat kalliolle heidän silmäinsä edessä, ja se antaa vetensä. Ja näin sinun pitää saattaman heille vettä kalliosta, ja juottaman kansan ja heidän karjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Niin otti Moses sauvan Herran edestä, niinkuin hän käski hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Ja Moses ja Aaron kokosivat kansan kallion eteen, ja sanoivat heille: kuulkaat nyt te niskurit: pitääkö meidän tästä kalliosta teille vettä saaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Ja Moses nosti kätensä ja löi kahdesti sauvallansa kallioon, niin juoksi siitä paljo vettä, ja kansa ja heidän karjansa saivat juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Ja Herra sanoi Mosekselle ja Aaronille: ettette uskoneet minun päälleni, pyhittääksenne minua Israelin lasten edessä, ei teidän pidä johdattaman tätä joukkoa siihen maahan, jonka minä heille annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Tämä on se riitavesi, josta Israelin lapset riitelivät Herran kanssa: ja hän pyhitettiin heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Ja Moses lähetti sanansaattajat Kadeksesta Edomin kuninkaan tykö, (sanoen:) näin sanoo veljes Israel: sinä tiedät kaiken vaivan, joka meille on tapahtunut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Että meidän isämme menivät alas Egyptiin ja me asuimme Egyptissä pitkän ajan, ja Egyptiläiset vaivasivat meitä ja meidän isiämme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Ja me huusimme Herran tykö, ja hän kuuli äänemme, ja lähetti Enkelin, ja vei meidät Egyptistä ulos. Ja katso, me olemme Kadeksessa, siinä kaupungissa, joka on sinun äärimäisillä rajoillas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Anna meidän vaeltaa maas lävitse: emme poikkee peltoihin eli viinamäkiin, emme myös juo vettä kaivoista; me vaellamme oikiaa maantietä, ei poiketen oikialle eikä vasemmalle puolelle, siihenasti kuin tulemme sinun rajas ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Edom sanoi hänelle: ei sinun pidä minun kauttani vaeltaman, taikka minä kohtaan sinua miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Ja Israelin lapset sanoivat hänelle: me vaellamme yhteistä maantietä, ja jos me ja meidän karjamme juovat sinun vettäs, niin me sen maksamme, emme ilman mitään tahdo; ainoastansa jalkaisin vaellamme sen lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Mutta hän sanoi: ei sinun pidä vaeltaman tästä lävitse. Ja Edomilaiset läksivät heitä vastaan paljolla väellä ja väkevällä kädellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Ja näin estivät Edomilaiset Israelin vaeltamasta maansa äären lävitse. Ja Israel käänsi itsensä heistä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Ja Israelin lapset läksivät Kadeksesta ja tulivat kaiken joukon kanssa Horin vuoren tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Ja Herra puhui Mosekselle ja Aaronille Horin vuorella, Edomin maan rajalla, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Kokoontukaan Aaron kansansa tykö; sillä ei hänen pidä tuleman siihen maahan, jonka minä Israelin lapsille antanut olen, että te olitte minun suulleni kovakorvaiset riitaveden tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Niin ota siis Aaron ja hänen poikansa Eleatsar, ja vie heidät Horin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Ja riisu Aaronin yltä vaatteet, puettaakses hänen poikansa Eleatsarin ylle: ja Aaron pitää siellä koottaman ja kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Ja Moses teki niinkuin Herra hänen käski, ja he astuivat Horin vuorelle kaiken kansan nähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Ja Moses riisui Aaronilta hänen vaatteensa, ja puetti hänen poikansa Eleatsarin ylle. Ja Aaron kuoli siellä, vuoren kukkulalla, mutta Moses ja Eleatsar astuivat vuorelta alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Ja koska kaikki kansa näki Aaronin kuolleeksi, itki koko Israelin huone häntä kolmekymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Ja koska Arad Kanaanealaisten kuningas, joka asui etelän puolessa, kuuli Israelin tulleeksi vakoojain tien kautta, soti hän Israelia vastaan ja vei heistä monikahtoja vangiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Niin lupasi Israel Herralle lupauksen ja sanoi: jos sinä annat tämän kansan minun käteni alle, niin minä kiroon heidän kaupunkinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Ja Herra kuuli Israelin rukouksen: ja antoi heille Kanaanealaiset, ja he kirosivat heitä ja heidän kaupungeitansa. Ja kutsui sen paikan Horma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Sitte menivät he pois Horin vuoren tyköä, Punaisen meren tietä, vaeltamaan Edomilaisten maata ympäri. Ja kansa suuttui matkasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Ja kansa puhui Jumalaa ja Mosesta vastaan: miksi sinä toit meitä Egyptistä korpeen kuolemaan? Sillä ei tässä ole leipää eikä vettä, ja meidän sielumme suuttuu tähän huonoon ruokaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Niin Herra lähetti kansan sekaan tuliset kärmeet, jotka kansaa purivat, niin että paljo kansaa Israelista kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Niin tuli kansa Moseksen tykö, ja sanoivat: me teimme syntiä, puhuen Herraa ja sinua vastaan. Rukoile Herraa nämät kärmeet meidän seastamme ottamaan pois: ja Moses rukoili kansan edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Niin sanoi Herra Mosekselle: tee sinulles tulinen kärme, ja nosta se merkiksi ylös: ja tapahtuu, että se joka purtu on, kuin hän katsoo sen päälle, niin hän elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Ja Moses teki vaskikärmeen, ja nosti sen merkiksi ylös: ja tapahtui, että jos joku kärmeeltä purtiin, ja katsahti vaskikärmeen päälle, niin hän jäi elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Ja Israelin lapset läksivät, ja sioittivat heitänsä Obotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Ja läksivät Obotista, ja sioittivat itsensä Abarimin mäen tykö, siihen korpeen, joka Moabin kohdalla on, auringon nousemiseen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Sieltä läksivät he, ja sioittivat heitänsä Saredin ojan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Niin he sieltä menivät ulos, ja sioittivat heitänsä tälle puolen Arnonia, joka korvessa on, ja tulee Amorilaisten maan ääristä; sillä Arnon on Moabin ja Amorin välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Siitä sanotaan Herran sotain kirjassa: Vaheb Suphassa, ja Arnonin ojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Ja sen ojan juoksu, joka poikkee Arin asumiseen, ja ulottuu Moabin rajaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Ja sieltä läksivät he Beraan, se on se kaivo, josta Herra sanoi Mosekselle: kokoa kansa, ja minä annan heille vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Silloin veisasi Israel tämän virren: Nouse, kaivo, veisatkaat hänestä toinen toisellenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Tämä on se kaivo, jonka päämiehet kaivoivat, kansan johdattajat kaivoivat, lain opettajan kautta sauvallansa. Tästä korvesta matkustivat he Mattanaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Ja Mattanasta niin Nahalieliin, Ja Nahalielistä niin Bamotiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Ja Bamotista siihen laaksoon, joka on Moabin kedolla, Pisgan kukkulaa kohden, joka katsahtaa korpeen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Ja Israel lähetti sanansaattajat Sihonin Amorilaisten kuninkaan tykö, ja käski sanoa hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Salli minun vaeltaa maakuntas lävitse: emme poikkee peltoihin, emmekä viinamäkiin, emmekä juo vettä kaivosta; maantietä myöten me vaellamme, siihenasti kuin me tulemme sinun maas ääristä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mutta Sihon ei sallinut Israelin vaeltaa maakuntansa lävitse, vaan Sihon kokosi kaiken väkensä, ja meni Israelia vastaan korpeen, ja tuli Jaksaan, ja soti Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Mutta Israel löi hänen miekan terällä, ja omisti hänen maansa Arnonista Jabbokiin asti, ja vielä Ammonin lapsiin saakka; sillä Ammonin maan ääret olivat vahvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Ja näin Israel sai kaikki nämät kaupungit, ja Israel asui kaikissa Amorilaisten kaupungeissa, Hesbonissa ja kaikissa sen tyttärissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Sillä Hesbonin kaupunki oli Sihonin Amorilaisten kuninkaan oma, ja hän soti ennen Moabilaisten kuninkaan kanssa, ja otti häneltä kaiken hänen maansa Arnoniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Siitä sananlaskussa sanotaan: tulkaat Hesboniin: rakennettakoon ja valmistettakoon Sihonin kaupunki;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Sillä tuli on käynyt Hesbonista ulos, ja liekki Sihonin kaupungista: se on kuluttanut Moabin Arin, ja Arnonin korkeuden asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Voi sinuas Moab! sinä Kamosin kansa olet hukkunut! Hän saatti poikansa pakolaiseksi ja hänen tyttärensä vangiksi, Sihonille Amorilaisten kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Me olemme heitä ampuneet, Hesbon on kukistettu Diboniin asti: me hävitimme heitä hamaan Nophaan, joka Medebaan ulottuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Ja niin Israel asui Amorilaisten maakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Sitte lähetti Moses vakoomaan Jaeseria, ja he voittivat sen tyttärinensä, ja omistivat ne Amorilaiset, jotka siinä asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Ja he palasivat ja menivät ylöspäin tietä Basaniin. Niin Og, Basanin kuningas, meni heitä vastaan, hän ja kaikki hänen väkensä, sotimaan Edreissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Ja Herra sanoi Mosekselle: älä pelkää häntä, sillä minä annoin hänen sinun käsiis, sekä kaiken hänen väkensä, että hänen maansa: ja sinun pitää tekemän hänelle niinkuin sinä Sihonille Amorilaisten kuninkaalle teit, joka Hesbonissa asui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Ja he löivät hänen ja hänen poikansa ja hänen väkensä, siihenasti ettei yksikään elämään jäänyt, ja he valloittivat hänen maansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Sitte menivät Israelin lapset sieltä, ja sioittivat heitänsä Moabin kedoille, toiselle puolelle Jordania, Jerihon kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Ja koska Balak Zipporin poika näki kaikki, mitä Israel teki Amorilaisille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Ja että Moabilaiset sangen suuresti pelkäsivät sitä kansaa heidän paljoutensa tähden, ja että Moabilaiset kauhistuivat Israelin lapsia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Niin sanoivat he Midianilaisten vanhimmille: Tämä kansa syö puhtaaksi kaikki, mitä ympäristöllämme on, niinkuin härkä syö vihannon laitumelta. Ja Balak Zipporin poika oli siihen aikaan Moabilaisten kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Ja hän lähetti sanan Petoriin, Bileamille Beorin pojalle, joka asui virran tykönä, kansansa lasten maalla, kutsumaan häntä, sanoen: katso, kansa on lähtenyt Egyptistä, katso, se peittää maan piirin, ja asettaa leirinsä minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Tule siis nyt ja kiroo minulle tämä kansa; sillä se on minua väkevämpi, että minä löisin häntä, ja hänen maaltani karkottaisin ulos; sillä minä tiedän, ketä sinä siunaat, se on siunattu, ja jota sinä kiroot, se on kirottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Ja Moabilaisten vanhimmat ynnä Midianilaisten vanhimpain kanssa menivät sinne, ja heillä oli noitumisen palkka kädessänsä. Ja koska he tulivat Bileamin tykö, sanoivat he hänelle Balakin sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Ja hän sanoi heille: olkaat tässä yö, niin minä sanon teille vastauksen, mitä Herra minulle sanova on. Niin olivat Moabilaisten päämiehet Bileamin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Ja Jumala tuli Bileamin tykö ja sanoi: mitkä miehet ne sinun tykönäs ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Ja Bileam sanoi Jumalalle: Balak Zipporin poika, Moabilaisten kuningas, lähetti minun tyköni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Katso, kansa läksi Egyptistä ja peittää maan piirin: tule siis ja kiroo heitä minulle, että minä voisin sotia heitä vastaan ja karkottaisin heitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Mutta Jumala sanoi Bileamille: älä mene heidän kanssansa, äläkä kiroo kansaa, sillä se on siunattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Silloin Bileam nousi varhain aamulla ja sanoi Balakin päämiehille: menkäät maallenne; sillä ei Herra salli minun teidän kanssanne mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Ja Moabilaisten päämiehet nousivat ja tulivat Balakin tykö, ja sanoivat: ei Bileam tahdo tulla meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Niin lähetti Balak päämiehet, vielä usiammat ja jalommat entisiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Jotka tultuansa Bileamin tykö sanoivat hänelle: Näin Balak Zipporin poika sanoo sinulle: älä estele tulemasta minun tyköni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Sillä minä teen sinulle suuren kunnian, ja mitäs sanot minulle, sen minä myös teen: tule siis ja kiroo minulle tämä kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Niin vastasi Bileam, ja sanoi Balakin palvelioille: jos Balak antais minulle huoneensa täyden hopiaa ja kultaa, niin en minä sittenkään taida Herran minun Jumalani sanaa käydä ylitse tekemään vähää elikkä paljoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Vaan olkaat kuitenkin tekin tämä yö tässä, niin minä tahdon tiedustaa, mitä Herra vielä minun kanssani puhuva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Silloin Jumala tuli yöllä Bileamin tykö ja sanoi hänelle: jos ne miehet ovat tulleet kutsumaan sinua, niin nouse ja mene heidän kanssansa, vaan kuitenkin, mitä minä sinulle sanon, sen pitää sinun tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Niin Bileam nousi varhain aamulla, valjasti aasinsa ja seurasi Moabilaisten päämiehiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Mutta Jumalan viha julmistui, että hän sinne meni. Ja Herran enkeli seisoi tiellä häntä vastassa, mutta hän ajoi aasillansa ja kaksi hänen palveliaansa oli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Ja aasi näki Herran enkelin seisovan tiellä ja hänen miekkansa vedetyn ulos hänen kädessänsä, niin aasi poikkesi tieltä ja meni kedolle: vaan Bileam löi aasia ohjataksensa häntä tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Niin Herran enkeli astui ahtaasen tanhuaan, viinamäen vaiheelle, jossa aidat molemmin puolin olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Ja koska aasi näki Herran enkelin, ahdisti hän itsensä aitaa vastaan, ja likisti Bileamin jalan aitaa vastaan, ja sitte hän kovemmin löi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Niin Herran enkeli meni edespäin ja seisoi ahtaassa paikassa, kussa ei ollut varaa poiketa oikialle eli vasemmalle puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Ja kuin aasi näki Herran enkelin, laski hän Bileamin alla polvillensa; niin Bileam sangen suuresti vihastui ja löi aasia sauvallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Silloin Herra avasi aasin suun, ja se sanoi Bileamille: mitä minä olen rikkonut sinua vastaan, ettäs minua kolmasti hosunut olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam sanoi aasille: ettäs pilkkasit minua. Jos minun kädessäni miekka olis, niin minä sinun tappaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Sanoi aasi Bileamille: enkö minä ole sinun aasis, jolla sinä tähän asti ajanut olet? olenko siis minä ikänä ennen niin tehnyt sinua vastaan? Hän vastasi: et.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Silloin avasi Herra Bileamin silmät, että hän näki Herran enkelin seisovan tiellä, ja avoimen miekan hänen kädessänsä; ja hän kumarsi, ja lankesi kasvoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Niin sanoi Herran enkeli hänelle: miksi sinä jo kolmasti sinun aasias hosuit? katsos, minä läksin sinua vastoin seisomaan; sillä tämä tie on nurja minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Ja aasi näki minun, ja poikkesi jo kolme erää minun edestäni; vaan jollei hän olisi minun edestäni poikennut, niin minä nyt sinun tappaisin ja jättäisin aasin elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Niin Bileam sanoi Herran enkelille: minä olen syntiä tehnyt; sillä en minä tietänyt, että sinä seisoit minun vastassani tiellä. Nyt siis, jollei se sinulle kelpaa, niin minä palajan takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Ja Herran enkeli sanoi Bileamille: mene miesten kanssa, vaan ei sinun pidä puhuman muuta, kuin minä sinulle sanon: ja Bileam seurasi Balakin päämiehiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Koska Balak kuuli Bileamin tulevan, läksi hän häntä vastaan Moabilaisten kaupunkiin, joka Arnonin rajoissa on, juuri rajan äärellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Ja Balak sanoi Bileamille: enkö minä sanaa lähettänyt sinun perääs, kutsumaan sinua? miksi siis et sinä tullut minun tyköni? vai luulitkos, etten minä olisi sen edestä sinua taitanut kunnioittaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Ja Bileam vastasi häntä: katso, minä tulin nyt sinun tykös; vaan onko minulla voimaa mitään puhua? Sen minkä Jumala minun suuhuni antaa, sen minä puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Ja niin Bileam meni Balakin kanssa, ja he tulivat Kujakaupunkiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Ja Balak uhrasi karjaa ja lampaita, ja lähetti Bileamin ja päämiesten perään, jotka hänen kanssansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Mutta huomeneltain tapahtui, että Balak otti Bileamin, ja vei hänen Baalin kukkulalle, näkemään sieltä kansan ääreen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Ja Bileam sanoi Balakille: rakenna minulle tähän seitsemän alttaria, ja valmista minulle tässä seitsemän mullia, ja seitsemän oinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Balak teki niinkuin Bileam sanoi, ja Balak ja Bileam uhrasivat (kullakin) alttarilla mullin ja oinaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Ja Bileam sanoi Balakille: seiso polttouhris tykönä, ja minä menen tuonne. Kukaties Herra tulee minua kohtaamaan, ja mitä hän minulle tietää antaa, sen minä tahdon sinulle ilmoittaa. Ja hän meni pois korkialle paikalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Ja Jumala kohtasi Bileamin; mutta hän sanoi hänelle: seitsemän alttaria minä valmistin, ja olen uhrannut mullin ja oinaan (joka) alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Ja Herra pani Bileamin suuhun sanat, ja sanoi: palaja Balakin tykö ja puhu näin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Ja koska hän tuli jälleen hänen tykönsä, katso, niin hän seisoi polttouhrinsa tykönä, kaikkein Moabin päämiesten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Niin alkoi hän puheensa ja sanoi: Syriasta on Balak Moabilaisten kuningas minua tuottanut, idän puolisilta vuorilta: tule ja kiroo minulle Jakob, tule sadattele Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kuinka minun pitää kirooman sitä, jota ei Jumalakaan kiroo? kuinka minä sitä sadattelen, jota ei Herrakaan sadattele?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Sillä vuorten kukkuloilta minä hänen näen, ja korkeuksista minä häntä katselen. Katso, se kansa pitää asuman yksinänsä, ja ei pidä pakanain sekaan luettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kuka lukee Jakobin tomus, ja neljännen osan Israelin lapsista? Minun sieluni kuolkoon vanhurskasten kuolemalla, ja minun loppuni olkoon niinkuin heidän loppunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Niin sanoi Balak Bileamille: mitäs minun teet? Minä tuotin sinun kiroilemaan vihollisiani, ja katso, sinä täydellisesti siunaat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Hän vastasi, ja sanoi: eikö minun pidä sitä pitämän ja puhuman, mitä Herra minun suuhuni antaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Balak sanoi hänelle: tule siis minun kanssani toiseen paikkaan, jostas hänen saat nähdä. Ainoastaan hänen äärimäisensä sinä taidat nähdä, vaan et näe kaikkia: kiroo häntä minulle sieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Ja hän vei hänen Vartialakeudelle, Pisgan kukkulalle, ja rakensi seitsemän alttaria, ja uhrasi (joka) alttarilla mullin ja oinaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Ja hän sanoi Balakille: seiso tässä polttouhris tykönä, ja minä tahdon kohdata (häntä) tuolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Ja Herra tuli Bileamia vastaan, ja antoi sanat hänen suuhunsa, ja sanoi: mene jälleen Balakin tykö ja sano näin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Ja kuin hän tuli hänen tykönsä jälleen, katso, hän seisoi polttouhrinsa tykönä Moabin päämiesten kanssa. Ja Balak sanoi hänelle: mitä Herra sanoi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Ja hän toi puheensa edes, ja sanoi: nouse, Balak ja kuule, kuuntele minua, Zipporin poika:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Ei ole Jumala ihminen, että hän valhettelis, taikka ihmisen lapsi, että hän jotakin katuis. Pitäiskö hänen jotakin sanoman, ja ei tekemän? Pitäiskö hänen jotakin puhuman, ja ei täyttämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Katso, siunauksen olen minä saanut: hän myös siunasi, ja en minä taida sitä muuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Ei nähdä vääryyttä Jakobissa, eikä havaita pahuutta Israelissa. Herra hänen Jumalansa on hänen tykönänsä, ja Kuninkaan basuna on hänen seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Jumala on hänen johdattanut Egyptistä: hänen väkevyytensä on niinkuin yksisarvisen väkevyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Sillä ei yhtään velhoa ole Jakobissa eikä noitaa Israelissa: ajallansa pitää sanottaman Jakobille ja Israelille, mitä Jumala tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Katso sen kansan pitää nouseman niinkuin syömäri jalopeura, ja karkaaman niinkuin tarkka jalopeura, ja ei pidä hänen maata paneman siihenasti että hän saaliin syö, ja juo niiden verta, jotka tapetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Niin sanoi Balak Bileamille: ellet ollenkaan tahdo kirota heitä, niin älä suinkaan siunaakaan heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileam vastasi, ja sanoi Balakille: enkö minä puhunut sinulle, sanoen: kaikki mitä Herra puhuva on, pitää minun tekemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Ja Balak sanoi Bileamille: tule, minä vien sinun toiseen paikkaan: mitämaks Jumalalle kelpaa, ettäs häntä sieltä kiroilisit minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Ja Balak vei Bileamin Peorin vuoren kukkulalle, joka korpeen päin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Ja Bileam sanoi Balakille: rakenna tähän minulle seitsemän alttaria, ja valmista minulle tässä seitsemän mullia ja seitsemän oinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Balak teki niinkuin Bileam sanoi, ja uhrasi (kullakin) alttarilla mullin ja oinaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Koska Bileam näki kelpaavan Herralle, hän siunasi Israelia, ei mennyt hän pois, niinkuin ennen, etsimään ilmoitusta, vaan käänsi kasvonsa korpeen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Ja Bileam nosti silmänsä ja näki Israelin sioittaneen itsensä sukukuntainsa jälkeen, ja Jumalan henki tuli hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Ja hän toi edes puheensa, ja sanoi: näitä sanoo Bileam Beorin poika, näitä sanoo se mies, jonka silmät avatut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Näitä sanoo se, joka kuulee Jumalan puheet, se, joka Kaikkivaltiaan ilmoitukset näkee, joka lankee maahan, ja hänen silmänsä avataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kuinka kauniit ovat sinun majas, Jakob, ja sinun asumas, Israel?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Niinkuin ojat levitetään, niinkuin yrttitarha virran vieressä, niinkuin aloes, jonka Herra istuttaa, niinkuin sedripuu veden tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Veden pitää vuotaman hänen ämpäristänsä, ja hänen siemenensä on paljoissa vesissä. Hänen kuninkaansa pitää oleman korkiamman Agagia, ja hänen valtakuntansa pitää korotettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Jumala johdatti hänen Egyptistä, hänen väkevyytensä on niinkuin yksisarvisen väkevyys: hänen pitää nielemän pakanat vihollisensa, ja heidän luunsa murentaman, ja nuolillansa ampuman lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Hän pani maata niinkuin tarkka jalopeura, ja niinkuin syömäri jalopeura: kuka tohtii herättää häntä? Siunattu olkoon se, joka sinua siunaa, kirottu olkoon se, joka sinua kiroo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Silloin Balakin viha julmistui Bileamia vastaan, ja löi käsiänsä yhteen, ja sanoi hänelle: minä kutsuin sinua kiroomaan vihollisiani, ja katso, sinä jo kolmasti täydellisesti siunasit heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Pakene kohta sialles. Minä ajattelin kunnioittaa sinua suuresti, ja katso, Herra on sen kunnian estänyt sinulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Ja Bileam puhui Balakille: enkö minä puhunut sanansaattajilles, kuin sinä lähetit minun tyköni, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Jos Balak antais minulle huoneensa täyden hopiaa ja kultaa, en minä taida senvuoksi Herran sanaa käydä ylitse, tekemään hyvää eli pahaa minun mieleni jälkeen; vaan mitä Herra sanoo, sen pitää myös minun sanoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Ja nyt katso, koska minä menen kansani tykö, niin tule, minä neuvon sinua, mitä tämä kansa sinun kansalles tekevä on, viimeisellä ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Ja hän piti puheen, ja sanoi: näin sanoo Bileam Beorin poika, näin sanoo se mies, jonka silmät avatut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Sen sanoo se, joka kuulee Jumalan puheen, ja se, jolla Ylimmäisen tieto on, joka näkee Kaikkivaltiaan ilmestyksen, joka lankee maahan, ja hänen silmänsä avataan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Minä saan nähdä hänen, mutta en nyt: minä katselen häntä, vaan en läheltä. Tähti nousee Jakobista, ja valtikka tulee Israelista, ja musertaa Moabin ruhtinaat, ja hävittää kaikki Setin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Hän omistaa Edomin, ja Seir tulee vihollistensa vallan alle, vaan Israel tekee voimallisia töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Jakobista tulee hallitsia, ja hävittää mitä tähteeksi jäänyt on kaupungeista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Ja kuin hän näki Amalekilaiset, piti hän puheen ja sanoi: Amalek ensimäinen pakanain seassa, vaan viimeiseltä sinä peräti hävitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Ja kuin hän näki Keniläiset, piti hän puheen, ja sanoi: sinun asumises on vahva, ja sinä teit pesäs kallioon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Vaan sinä Kain poltetaan, siihenasti kuin Assur vie sinun vankina pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Vihdoin piti hän puheen, ja sanoi: voi! kuka elää silloin, kuin väkevä Jumala näitä on tekevä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Ja haahdet Kittimin rannoilta kukistavat Assurin ja kukistavat Eberin, vaan hän itse myös hukkuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Ja Bileam nousi ja meni matkaansa, ja tuli jälleen siallensa, ja Balak myös meni tietänsä myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Ja Israel asui Sittimissä, ja kansa rupesi tekemään huorin Moabilaisten tytärten kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Jotka kutsuivat kansan epäjumalainsa uhrille: ja kansa söi, ja kumarsi heidän epäjumaliansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Ja Israel yhdisti itsensä BaalPeorin kanssa: niin Herran viha julmistui Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Ja Herra sanoi Mosekselle: ota kaikki kansan päämiehet, ja hirtä heidät Herralle aurinkoa vastaan, että Herran vihan julmuus käännettäisiin Israelista pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Ja Moses sanoi Israelin tuomareille: jokainen tappakoon väkensä, jotka BaalPeorin kanssa ovat itsensä yhdistäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Ja katso, mies Israelin lapsista tuli ja toi veljeinsä sekaan Midianilaisen vaimon, Moseksen ja kaikkein Israelin lasten joukon nähden, jotka itkivät seurakunnan majan ovessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Kuin Pinehas Eleatsarin poika, papin Aaronin pojanpoika sen näki, nousi hän kansan keskeltä ja otti keihään käteensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Ja meni Israelin miehen jälkeen makausmajaan, ja pisti heidät molemmat sekä Israelin miehen, että vaimon vatsasta lävitse: niin rangaistus lakkasi jälleen Israelin lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Ja siinä rangaistuksessa surmattiin neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinehas Eleatsarin poika, papin Aaronin pojanpoika, on kääntänyt julmuuteni pois Israelin lasten päältä, siinä että hän oli kiivas minun kiivauteni tähden heidän keskellänsä, etten minä kiivaudessani hukuttanut Israelin lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Sentähden sano: katso, minä annan hänelle minun rauhani liiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Ja hänellä ja hänen siemenellänsä hänen jälkeensä pitää oleman ijankaikkisen pappeuden liiton, että hän oli kiivas Jumalallensa ja sovitti Israelin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Ja lyödyn Israelin miehen nimi, joka Midianilaisen vaimon kanssa lyötiin, oli Simri Salun poika, isän Simeonin huoneen päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Mutta Midianilaisen vaimon nimi, joka myös lyötiin, oli Kosbi, Zurin, Midianin kansan huoneen päämiehen, tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Ahdistakaat Midianilaisia, ja lyökäät heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Sillä he ovat teitä ahdistaneet kavaluuksillansa, joilla he teidät pettäneet ovat Peorin kautta, ja sisarensa Kosbin kautta, Midianilaisten päämiehen tyttären, joka lyötiin rangaistuksen päivänä, Peorin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Ja tapahtui, rangaistuksen jälkeen, että Herra puhui Mosekselle ja Eleatsarille, papin Aaronin pojalle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Lue koko Israelin lasten joukko kahdenkymmenen vuotiset ja sen ylitse, heidän isäinsä huoneen jälkeen, kaikki jotka sotaan Israelissa kelpaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Ja Moses ja pappi Eleatsar puhuivat heidän kanssansa, Moabin kedoilla, Jordanin tykönä, Jerihon kohdalla, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Ne jotka ovat kahdenkymmenen vuotiset ja sen ylitse, niinkuin Herra oli käskenyt Mosekselle ja Israelin lapsille, jotka Egyptistä lähteneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben Israelin esikoinen: Rubenin lapset: Hanok, josta on Hanokilaisten sukukunta: Pallu, siitä Pallulaisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Hetsron, hänestä Hetsronilaisten sukukunta: Karmi, josta Karmilaisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Nämät ovat Rubenilaisten sukukunnat. Ja heidän lukunsa oli kolmeviidettäkymmentä tuhatta seitsemänsataa ja kolmekymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Mutta Pallun poika oli Eliab.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Ja Eliabin pojat, Nemuel ja Datan ja Abiram. Nämät ovat Datan ja Abiram, jotka kutsuttiin kansasta, jotka asettivat heitänsä Mosesta ja Aaronia vastaan Koran eriseurassa, koska he asettivat heitänsä Herraa vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Ja maa avasi suunsa ja nieli heidät ja Koran, koska se eriseura kuoli, ja koska myös tuli söi viisikymmentä miestä kolmattasataa, ja tulivat merkiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Vaan Koran lapset ei kuolleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeonin lapset heidän sukukunnissansa: Nemuel, hänestä Nemuelilaisten sukukunta: Jamin, hänestä Jaminilaisten sukukunta: Jakin, hänestä Jakinilaisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Sera, hänestä Seralaisten sukukunta: Saul, hänestä Saulilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Nämät ovat Simeonilaisten sukukunnat, kaksikolmattakymmentä tuhatta ja kaksisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gadin lapset heidän sukukunnissansa: Sephon, hänestä Sephonilaisten sukukunta: Haggi, hänestä Haggilaisten sukukunta: Suni, hänestä Sunilaisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Osni, hänestä Osnilaisten sukukunta: Eri, hänestä Eriläisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod, hänestä Arodilaisten sukukunta: Ariel, hänestä Arielilaisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Nämät ovat Gadin lasten sukukunnat, heidän lukunsa jälkeen: neljäkymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Juudan lapset, Ger ja Onan: ja Ger ja Onan kuolivat Kanaanin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Ja Juudan lapset heidän sukukunnissansa olivat: Sela, hänestä Selanilaisten sukukunta: Perets, hänestä Peretsiläisten sukukunta: Sera, hänestä Seralaisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Mutta Peretsin lapset olivat, Hetsron, hänestä Hetsronilaisten sukukunta: Hamul, hänestä Hamulilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Nämät ovat Juudan sukukunnat, heidän lukunsa jälkeen: kuusikahdeksattakymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Isaskarin lapset heidän sukukunnissansa: Tola, hänestä Tolalaisten sukukunta: Phua, hänestä Phualaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub, hänestä Jasubilaisten sukukunta: Simron, hänestä Simronilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Nämät ovat Isaskarin sukukunnat, heidän lukunsa jälkeen: neljäseitsemättäkymmentä tuhatta ja kolmesataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sebulonin lapset heidän sukukunnissansa: Sered, hänestä Serediläisten sukukunta: Elon, hänestä Elonilaisten sukukunta: Jahlel, hänestä Jahlelilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Nämät ovat Sebulonin sukukunnat, lukunsa jälkeen: kuusikymmentä tuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Josephin lapset sukukunnissansa: Manasse ja Ephraim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manassen lapset: Makir, hänestä Makirilaisten sukukunta. Makir siitti Gileadin, hänestä Gileadilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Nämät ovat Gileadin lapset: Jeser, hänestä Jeseriläisten sukukunta: Helek, hänestä Helekiläisten sukukunta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asriel, hänestä Asrielilaisten sukukunta: Sikem, hänestä Sikemiläisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Semida, hänestä Semidalaisten sukukunta: Hepher, hänestä Hepheriläisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Mutta Zelophkad oli Hepherin poika, ja ei hänellä ollut poikia, mutta ainoastaan tyttäriä, ja Zelophkadin tytärten nimet: Makla, Noa, Hogla, Milka ja Tirtsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Nämät ovat Manassen sukukunnat, heidän lukunsa oli kaksikuudettakymmentä tuhatta ja seitsemänsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Nämät ovat Ephraimin lapset heidän sukukunnissansa: Suthelak, hänestä Sutalkilaisten sukukunta: Beker, hänestä Bakrilaisten sukukunta: Tahan, hänestä Tahanilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Vaan Suthelakin lapset olivat Eran, hänestä Eranilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Nämät ovat Ephraimin lasten sukukunnat: heidän lukunsa oli kaksineljättäkymmentä tuhatta ja viisisataa. Nämät ovat Josephin lapset heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'BenJaminin lapset heidän sukukunnissansa: Bela, hänestä Belalaisten sukukunta: Asbel hänestä Asbelilaisten sukukunta: Ahiram, hänestä Ahiramilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Sephupham, hänestä Sephuphamilaisten sukukunta: Hupham, hänestä Huphamilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Mutta Belan lapset olivat Ard ja Naeman, näistä Ardilaisten ja Naemanilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Nämät ovat BenJaminin lapset heidän sukukunnissansa: heidän lukunsa oli viisiviidettäkymmentä tuhatta ja kuusisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Nämät ovat Danin lapset heidän sukukunnissansa: Suham, hänestä Suhamilaisten sukukunta. Nämät ovat Danin lapset heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Ja olivat kaikki yhteen Suhamilaisten sukukunta, neljäseitsemättäkymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Asserin lapset heidän sukukunnissansa: Jemna, hänestä Jemnalaisten sukukunta: Jesvi, hänestä Jesviläisten sukukunta: Brija, hänestä Brijalaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Mutta Brijan lapset olivat Heber, hänestä Hebriläisten sukukunta: Melkiel, hänestä Melkieliläisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Ja Asserin tytär kutsuttiin Sara.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Nämät ovat Asserin lasten sukukunnat, ja heidän lukunsa kolmekuudettakymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naphtalin lapset heidän sukukunnissansa: Jahtseel, hänestä Jahtseelilaisten sukukunta: Guni, hänestä Gunilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jetser, hänestä Jetsriläisten sukukunta: Sillem, hänestä Sillemiläisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Nämät ovat Naphtalin sukukunnat, heidän heimokuntainsa jälkeen: heidän lukunsa oli viisiviidettäkymmentä tuhatta ja neljäsataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Tämä on Israelin lasten luku: kuusi kertaa satatuhatta ja yksituhatta, seitsemänsataa ja kolmekymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Näille sinun pitää jakaman maan perinnöksi, nimein lukuin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Monelle pitää sinun paljo antaman perinnöksensä, ja harvemmille antaman vähemmän perinnöksensä: jokaiselle pitää annettaman perimys heidän lukunsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Kuitenkin arvalla pitää maa jaettaman ja isäinsä sukukuntain nimein jälkeen pitää heidän perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Arvalla sinun pitää jakaman heidän perimisensä, sen jälkeen kuin heitä monta ja harvat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Ja tämä myös on Leviläisten luku heidän sukukunnissansa: Gerson, hänestä Gersonilaisten sukukunta: Kahat, hänestä Kahatilaisten sukukunta; Merari, hänestä Merarilaisten sukukunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Nämät ovat Levin sukukunnat: Libniläisten sukukunnat, Hebronilaisten sukukunnat, Maklilaisten sukukunnat, Musilaisten sukukunnat, Koralaisten sukukunnat. Kahat siitti Amramin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Ja Amramin emännän nimi oli Jokebed Levin tytär, joka Leville oli syntynyt Egyptissä: ja hän synnytti Amramille Aaronin ja Moseksen, ja heidän sisarensa MirJamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Mutta Aaronille oli syntynyt Nadab ja Abihu: Eleatsar ja Itamar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Ja Nadab ja Abihu kuolivat, koska he uhrasivat vierasta tulta Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Ja heidän lukunsa oli kolmekolmattakymmentä tuhatta, kaikki miehenpuoli, kuukauden vanha ja sen ylitse, jotka ei olleet luetut Israelin lasten sekaan; sillä ei heille annettu perimistä Israelin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Tämä on Israelin lasten luku, jotka Moses ja pappi Eleatsar lukivat Moabin kedoilla, Jordanin tykönä, Jerihon kohdalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Joiden luvussa ei yhtään ollut siitä luvusta, kuin Moses ja pappi Aaron lukivat Israelin lapset Sinain korvessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Sillä Herra oli sanonut heille, että heidän piti totisesti kuoleman korvessa; ja ei yksikään jäänyt heistä elämään, ainoastansa Kaleb Jephunnen poika ja Josua Nunin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Niin tulivat edes Zelophkadin tyttäret, Hephrin pojan, Gileadin pojan, Makirin pojan, Manassen pojan, Manassen Josephin pojan suvusta, ja nämät olivat hänen tytärtensä nimet: Makla, Noa, Hogla, Milka ja Tirtsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Ja he astuivat Moseksen ja papin Eleatsarin, ja päämiesten, ja kaiken kansan eteen, seurakunnan majan ovelle, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Meidän isämme kuoli korvessa, eikä hän ollut siinä joukossa, jotka metelin nostivat Herraa vastaan Koran kapinassa, mutta on synnissänsä kuollut: ja ei ollut hänellä poikia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Miksi meidän isämme nimen pitää tuleman suvustansa pois, sentähden ettei hänellä ollut yhtään poikaa? antakaat meille osa isämme veljein seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Ja Moses tuotti heidän asiansa Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Zelophkadin tyttäret ovat oikein puhuneet: sinun pitää kaiketi antaman perintöosan heille heidän isänsä veljein seassa, ja saattaman heidän isänsä perimisen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Ja puhu Israelin lapsille, sanoen: jos joku kuolee ilman pojata, niin teidän pitää antaman hänen perimisensä hänen tyttärellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Jollei hänellä ole tytärtä, niin teidän pitää sen perimisen hänen veljillensä antaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Ja jollei hänellä ole veljiä; niin teidän pitää sen antaman hänen sedillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Jollei hänellä ole setiä, niin teidän pitää sen antaman hänen lähimmäiselle sukulaisellensa, joka hänen lähimmäinen lankonsa on hänen suvustansa, että hän sen omistaa. Tämä pitää oleman Israelin lapsille sääty ja oikeus, niinkuin Herra on Mosekselle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Ja Herra sanoi Mosekselle: astu ylös tälle Abarimin vuorelle, ja katsele sitä maata, jonka minä Israelin lapsille annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Ja kuin sen nähnyt olet, niin sinäkin kootaan kansas tykö, niinkuin sinun veljes Aaron koottu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Sillä te olitte minun sanalleni kovakorvaiset Sinin korvessa kansan toruessa, kuin teidän piti minua pyhittämän veden kautta heidän edessänsä. Se on se riitavesi Kadeksessa, Sinin korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Ja Moses puhui Herralle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Herra, kaiken lihan henkein Jumala asettakaan miehen kansan päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Joka heidän edessänsä kävis ulos ja sisälle, ja veis heitä ulos ja sisälle, ettei Herran kansa olisi niinkuin lampaat ilman paimenta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Ja Herra sanoi Mosekselle: ota Josua Nunin poika sinun tykös, joka on mies, jossa henki on, ja pane sinun kätes hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Ja aseta hänet papin Eleatsarin ja kaiken kansan eteen, ja käske hänelle heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Ja pane sinun kunniastas hänen päällensä, että kaikki kansa Israelin lapsista olisivat hänelle kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Ja hänen pitää papin Eleatsarin eteen astuman, hänen pitää kysymän neuvoa hänen edestänsä valkeuden säädyllä Herran edessä, ja hänen suunsa jälkeen pitää hänen käymän ulos ja sisälle, sekä hänen että Israelin lasten hänen kanssansa, ja koko seurakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Ja Moses teki niinkuin Herra hänelle käski, ja otti Josuan ja asetti hänen papin Eleatsarin ja koko seurakunnan eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Ja laski kätensä hänen päällensä, ja käski hänelle, niinkuin Herra oli Mosekselle puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Käske Israelin lapsille, ja sano heille: minun uhristani, joka minun leipäni on, tuliuhriksi ja lepytyshajuksi minulle, pitää teidän vaarinottaman, niin että te sen ajallansa minulle uhraatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Ja sano heille: tämä on tuliuhri, jonka teidän pitää uhraaman Herralle: kaksi virheetöintä vuosikuntaista karitsaa jokapäivä, alinomaiseksi polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Yhden karitsan pitää sinun valmistaman aamulla, ja toisen pitää sinun valmistaman kahden ehtoon välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Siihen kymmenesosa ephaa sämpyläjauhoja ruokauhriksi, sekoitettuna puserretulla öljyllä, neljännellä osalla hinniä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Se on alinomainen polttouhri, joka Sinain vuorella asetettu on makiaksi hajuksi: se on tuliuhri Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Niin myös sen juomauhrin, yhdelle karitsalle neljännen osan hinniä. Ja juomauhri pitää uhrattaman pyhässä, väkevästä viinasta, Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Toisen karitsan pitää sinun valmistaman kahden ehtoon välillä: niinkuin aamullisen ruokauhrin ja juomauhrin pitää sinun sen valmistaman, makian hajun tuleksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Mutta sabbatin päivänä kaksi virheetöintä vuosikuntaista karitsaa, ja kaksi kymmenestä sämpyläjauhoja, sekoitettuna öljyllä, ruokauhriksi ja sen juomauhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Tämä on joka sabbatin polttouhri, paitsi alinomaista polttouhria juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Vaan ensimäisenä päivänä joka kuusta pitää teidän uhraaman Herralle polttouhriksi: kaksi nuorta mullia, yhden oinaan, seitsemän vuosikuntaista karitsaa, virheetöintä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Ja kolme kymmenestä sämpyläjauhoja ruokauhriksi, sekoitettuina öljyllä jokaiselle mullille, ja kaksi kymmenestä sämpyläjauhoja ruokauhriksi, öljyllä sekoitettuina, jokaiselle oinaalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Ja aina kymmenes sämpyläjauhoja ruokauhriksi, öljyllä sekoitettuja, jokaiselle karitsalle: se on lepytyshajun tuli Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Ja heidän juomauhrinsa pitää oleman puoli hinniä viinaa mullille, kolmannes hinniä oinaalle, neljännes hinniä karitsalle. Se on kuukautinen polttouhri, joka kuukaudella ympäri ajastajan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Ja yksi kauris syntiuhriksi Herralle: paitsi alinomaista polttouhria, juomauhrinensa pitää se valmistettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Mutta neljäntenätoistakymmenentenä päivänä ensimäisellä kuulla, on pääsiäinen Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Ja viidentenätoistakymmenenentenä päivänä sitä kuuta on juhla. Seitsemän päivää pitää syötämän happamatointa leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Ensimäisenä päivänä on pyhä kokous: ei yhtään orjan työtä pidä teidän (silloin) tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Ja teidän pitää uhraaman tuliuhria Herralle polttouhriksi: kaksi nuorta mullia, ja yhden oinaan, niin myös seitsemän vuosikuntaista karitsaa: virheettömät ne pitää teillä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Ja heidän ruokauhrinsa, öljyllä sekoitettuja sämpyläjauhoja, kolme kymmenestä mullille, ja kaksi kymmenestä oinaalle pitää teidän tekemän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Ja aina yhden kymmeneksen jokaiselle niistä seitsemästä karitsasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Siihen myös yhden kauriin syntiuhriksi, teitä sovittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Paitsi aamuista polttouhria, joka alinomainen polttouhri on, pitää teidän ne tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Tällä tavalla pitää teidän jokaisena seitsemänä päivänä uhraaman leipää makian hajun tuleksi Herralle: paitsi alinomaista polttouhria, pitää se valmistettaman juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Ja seitsemäntenä päivänä pitää teillä oleman pyhä kokous: ei yhtäkään orjan työtä pidä teidän (silloin) tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Ja uutisten päivänä, kuin te uhraatte uutta ruokauhria Herralle, kuin teidän viikkonne ovat kuluneet, pitää teillä pyhä kokous oleman: ei yhtäkään orjan työtä pidä teidän (silloin) tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Ja teidän pitää uhraaman polttouhria, otolliseksi hajuksi Herralle: kaksi mullia, yhden oinaan ja seitsemän vuosikuntaista karitsaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Ja heidän ruokauhrinsa: sämpyläjauhoja sekoitettuja öljyllä, kolme kymmenestä kummallekin mullille, kaksi kymmenestä yhdelle oinaalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Ja aina kymmeneksen kullekin karitsalle, niistä seitsemästä karitsasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Ja yhden kauriin, teitä sovittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Tämän pitää teidän tekemän, paitsi alinomaista polttouhria, ruokauhrinensa: virheettömät pitää ne teillä oleman, niin myös heidän juomauhrinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Ensimäisenä päivänä seitsemännellä kuukaudella pitää teillä pyhä kokous oleman: ei yhtään orjan työtä pidä teidän (silloin) tekemän: se pitää oleman soittamisen juhlapäivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Ja teidän pitää uhraaman polttouhria makiaksi hajuksi Herralle: yhden nuoren mullin, yhden oinaan, seitsemän vuosikuntaista karitsaa, virheetöinnä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Niin myös heidän ruokauhrinsa: öljyllä sekoitettuja sämpyläjauhoja, kolme kymmenestä mullille, kaksi kymmenestä oinaalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'Ja yhden kymmeneksen jokaiselle karitsalle, niistä seitsemästä karitsasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Ja yhden kauriin syntiuhriksi, teitä sovittamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Paitsi saman kuukauden polttouhria ja ruokauhria, ja paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa, heidän säätynsä jälkeen makian hajun tuleksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Kymmenentenä päivänä tällä seitsemännellä kuukaudella pitää myös teillä pyhä kokous oleman ja teidän pitää vaivaaman teidän sielujanne, ja ei yhtään työtä (silloin) tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Vaan teidän pitää uhraaman polttouhria makiaksi hajuksi Herralle: yhden nuoren mullin, ja yhden oinaan, ja seitsemän vuosikuntaista karitsaa: virheettömät ne pitää oleman teillä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Ynnä heidän ruokauhrinsa kanssa: sämpyläjauhoja, sekoitettuja öljyllä, kolme kymmenestä mullille, kaksi kymmenestä oinaalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Ja aina kymmeneksen jokaiselle karitsalle, niistä seitsemästä karitsasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Yhden kauriin syntiuhriksi, paitsi sovittamisen syntiuhria ja alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Viidentenätoistakymmenentenä päivänä seitsemännellä kuukaudella pitää teillä pyhä kokous oleman: ei mitään orjan työtä pidä teidän (silloin) tekemän, ja teidän pitää juhlaa pitämän Herralle ne seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Ja teidän pitää uhraaman polttouhria ja tuliuhria, makiaksi hajuksi Herralle: kolmetoistakymmentä nuorta mullia, kaksi oinasta, neljätoistakymmentä vuosikuntaista karitsaa: virheettömät ne pitää oleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Heidän ruokauhrinsa kanssa, sämpyläjauhoja, sekoitettuja öljyllä, kolme kymmenestä jokaiselle kolmestatoistakymmenestä mullista, kaksi kymmenestä kumpaisellekin oinaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'Ja kymmeneksen itsekullekin neljästätoistakymmenestä karitsasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Siihen myös kauriin syntiuhriksi: paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Ja toisena päivänä kaksitoistakymmentä nuorta mullia, kaksi oinasta, neljätoistakymmentä vuosikuntaista karitsaa, virheetöinnä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Ja heidän ruokauhrinsa ja juomauhrinsa mulleille, oinaille ja karitsoille, heidän lukunsa ja säätynsä perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Siihen myös kauriin syntiuhriksi: paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Kolmantena päivänä yksitoistakymmentä mullia, kaksi oinasta, neljätoistakymmentä vuosikuntaista karitsaa, virheetöinnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Ja heidän ruokauhrinsa ja juomauhrinsa mulleille, oinaille ja karitsoille, heidän lukunsa ja säätynsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Siihen myös kauriin syntiuhriksi: paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Neljäntenä päivänä kymmenen mullia, kaksi oinasta, neljätoistakymmentä vuosikuntaista karitsaa, virheetöinnä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Heidän ruokauhrinsa ja juomauhrinsa mulleille, oinaille ja karitsoille, heidän lukunsa ja säätynsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Siihen kauriin syntiuhriksi; paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Ja viidentenä päivänä yhdeksän mullia, kaksi oinasta, neljätoistakymmentä vuosikuntaista karitsaa, ilman virhettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Ja heidän ruokauhrinsa ja juomauhrinsa mulleille, oinaille ja karitsoille, heidän lukunsa ja säätynsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Siihen myös kauriin syntiuhriksi; paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Ja kuudentena päivänä kahdeksan mullia, kaksi oinasta, neljätoistakymmentä vuosikuntaista karitsaa, virheetöinnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Ja heidän ruokauhrinsa ja juomauhrinsa mulleille, oinaille ja karitsoille, heidän lukunsa ja säätynsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Siihen myös kauriin syntiuhriksi; paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Ja seitsemäntenä päivänä seitsemän mullia, kaksi oinasta, neljätoistakymmentä vuosikuntaista karitsaa, virheetöinnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Ja heidän ruokauhrinsa ja juomauhrinsa mulleille, oinaille ja karitsoille, heidän lukunsa ja säätynsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Siihen myös kauriin syntiuhriksi; paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Kahdeksas päivä pitää oleman teille päätösjuhla: ei yhtään orjan työtä teidän pidä (silloin) tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Ja teidän pitää uhraaman polttouhria makian hajun tuleksi Herralle: yhden mullin, yhden oinaan ja seitsemän vuosikuntaista karitsaa, virheetöinnä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Heidän ruokauhrinsa ja juomauhrinsa mulleille, oinaille ja karitsoille, heidän lukunsa ja säätynsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Siihen myös kauriin syntiuhriksi; paitsi alinomaista polttouhria, ruokauhrinensa ja juomauhrinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Nämät pitää teidän tekemän Herralle juhlapäivinänne, paitsi mitä te mielellänne lupaatte ja hyvällä tahdollanne annatte polttouhriksenne, ruokauhriksenne, juomauhriksenne ja kiitosuhriksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'Ja Moses sanoi Israelin lapsille kaikki ne, mitä Herra hänelle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Ja Moses puhui Israelin sukukuntain päämiehille, sanoen: tämä on se minkä Herra käski:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Jos mies lupaa lupauksen Herralle eli vannoo valan, sitoen sillä sielunsa, ei pidä hänen tekemän sanaansa turhaksi, vaan kaiken sen täyttämän, mikä hänen suustansa lähtenyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Ja jos vaimo lupaa lupauksen Herralle, sitoen itsensä, ollessansa vielä isänsä huoneessa nuoruudessansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Ja hänen isänsä kuulee hänen lupauksensa ja valasiteensä, jolla hän on sielunsa sitonut, ja hänen isänsä on ääneti siihen: niin kaikki hänen lupauksensa on vahva, niin myös koko hänen valasiteensä, jolla hän on sielunsa sitonut, pitää vahvan oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Mutta jos hänen isänsä kieltää sen sinä päivänä, jona hän sen kuulee, niin hänen lupauksensa ja valasiteensä, jolla hän on sielunsa sitonut, ei pidä vahva oleman, ja Herra on hänelle armollinen, että hänen isänsä on sen häneltä kieltänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Ja jos hänellä on mies, ja hän on luvannut, taikka hänen suustansa lähtee jotakin, jolla hän on sielunsa sitonut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Ja hänen miehensä kuulee sen, ja on ääneti siihen sinä päivänä, jona hän sen kuulee, niin pitää hänen lupauksensa vahvan oleman; ja hänen valasiteensä, jolla hän on sielunsa sitonut, pitää myös vahvan oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Mutta jos hänen miehensä sen kieltää sinä päivänä, jona hän sen kuulee, niin hän pääsee lupauksestansa, ja siitä mikä hänen suustansa lähtenyt on, jolla hän sielunsa sitoi, ja Herra on hänelle armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Lesken ja hyljätyn lupaus ja kaikki, jolla hän on sielunsa sitonut, pitää häneltä vahvana pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Mutta jos hän lupaa miehensä huoneessa, eli sielunsa sitoo valallansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Ja mies kuulee sen, ja on ääneti siihen, ja ei kiellä sitä, niin pitää kaiken sen lupauksen ja valasiteen, jolla hän on sielunsa sitonut, oleman vahvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Jos hänen miehensä tekee sen kokonansa tyhjäksi sinä päivänä, jona hän sen kuulee, niin kaikki mikä hänen suustansa on lähtenyt, lupaamaan ja sitomaan sieluansa, ei pidä oleman vahvan; sillä hänen miehensä on sen tehnyt tyhjäksi, ja Herra on hänelle armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Ja kaikki lupaukset ja valat, jotka sitovat vaivaamaan sielua, pitää hänen miehensä taikka vahvistaman, taikka tekemän tyhjäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Mutta jos hänen miehensä on juuri ääneti siihen, päivästä päivään, niin hän vahvistaa kaikki hänen lupauksensa ja kaikki hänen valasiteensä: että hän on ääneti ollut sinä päivänä, jona hän sen kuuli, niin hän vahvistaa ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Ja jos hän jälistä sen ottaa takaperin, sittekuin hän sen kuuli, niin pitää hänen kantaman vääryytensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Nämät ovat ne säädyt, jotka Herra on käskenyt Mosekselle miehen ja vaimon välillä, isän ja tyttären välillä, kuin hän on vielä nuorena isänsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Kosta täydellisesti Midianilaisille Israelin lasten puolesta, sitte kootaan sinä kansas tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Niin Moses puhui kansalle sanoen: hankitkaat teistänne miehet sotaan Midianilaisia vastaan, että he kostaisivat Midianilaisia, Herran puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Jokaisesta sukukunnasta pitää teidän lähettämän tuhannen sotaan, kaikista Israelin sukukunnista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Niin otettiin Israelin sukukunnista joka sukukunnasta tuhannen, niin että he varustivat sotaan kaksitoistakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Ja Moses lähetti heidät sotaan, tuhannen jokaisesta sukukunnasta, ynnä Pinehaan papin Eleatsarin pojan kanssa, ja pyhät aseet, ja myös ilotorvet hänen kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Ja he sotivat Midianilaisia vastaan, niinkuin Herra oli Mosekselle käskenyt, ja löivät kuoliaaksi kaiken miehenpuolen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Niin tappoivat he myös Midianilaisten kuninkaat heidän lyötyjensä päälle; Evin, Rekemin, Zurin, Hurin ja Reban, ne viisi Midianilaisten kuningasta; Bileamin Beorin pojan löivät he myös miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Mutta Israelin lapset ottivat vangiksi Midianilaisten vaimot ja heidän lapsensa, ja kaikki heidän eläimensä ja kaikki heidän kalunsa ja kaiken heidän hyvyytensä ryöstivät he.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Ja kaikki heidän kaupunkinsa ja asumisensa ja kaikki heidän linnansa he polttivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Ja ottivat kaiken saaliin ja kaikki mikä otettava oli, sekä ihmiset että eläimet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Ja veivät ne Moseksen ja papin Eleatsarin eteen, ja kaiken Israelin lasten seurakunnan eteen; vangit ja otetut eläimet, ja saaliin, leiriin Moabin kedolle, joka on Jordanin tykönä Jerihon kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Ja Moses ja pappi Eleatsar ja kaikki seurakunnan päämiehet menivät heitä vastaan, ulos leiristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Ja Moses vihastui sodan päämiesten päälle, jotka olivat päämiehet tuhannen ja sadan päällä, kuin siitä sodan joukosta tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Ja Moses sanoi heille: ettekö te ole kaikki vaimot jättäneet elämään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Katso, eikö ne Bileamin neuvosta kääntäneet Israelin lapsia syntiä tekemään Herraa vastaan Peorin asiassa, ja rangaistus tuli Herran kansan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Niin lyökäät nyt kuoliaaksi kaikki miehenpuoli lasten seassa, ja kaikki vaimot, jotka miehen tunteneet ja miehen kanssa maanneet ovat, lyökäät myös kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Mutta lapsista kaikki vaimonpuoli, jotka ei ole miestä tunteneet eikä maanneet miehen tykönä, sallikaat elää teidän edessänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Ja pysykäät ulkona leiristä seitsemän päivää kaikki, jokainen, joka hengen tappanut on eli tapettuun sattunut, että te puhdistatte teitänne kolmantena ja seitsemäntenä päivänä, ynnä niiden kanssa, jotka te vangiksi otitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Ja kaikki vaatteet, ja kaikki nahkakalut, ja kaikki, mitkä vuohen karvoista tehdyt ovat, ja kaikki puuastiat pitää teidän puhdistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Ja pappi Eleatsar sanoi sotajoukolle, jotka sodassa olleet olivat: tämä on lain sääty, jonka Herra on käskenyt Mosekselle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Ainoastansa kullan, hopian, vasken, raudan, tinan ja lyijyn,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Ja kaikki mikä tulen kärsii, pitää teidän tulessa käyttämän, ja ne ovat puhtaat; kuitenkin pitää ne puhdistusvedellä puhtaaksi tehtämän. Mutta kaikki se, mikä ei tulta kärsi, pitää teidän vedessä käyttämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Ja teidän pitää pesemän vaatteenne seitsemäntenä päivänä, niin te tulette puhtaaksi, sitte teidän pitää tuleman leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Lue vangittuin saalis sekä ihmiset että eläimet: sinä ja pappi Eleatsar, ja ylimmäiset kansan isät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Ja anna puoli saalista niille, jotka sotaan menivät ja sotineet ovat, ja toinen puoli kaikelle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Ja sinun pitää ylentämän Herralle sotamiehiltä, jotka sodassa olivat, aina viidestäsadasta yhden sielun, ihmisistä, eläimistä, aaseista ja lampaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Siitä puolesta osasta, joka heille tuli, pitää sinun ottaman ja antaman papille Eleatsarille, ylennykseksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Vaan siitä puolesta, joka Israelin lapsille tuli, pitää sinun aina viidestäkymmenestä ottaman yhden niistä otetuista, ihmisistä, karjasta, aaseista ja lampaista, ja kaikista eläimistä, ja sinun pitää ne antaman Leviläisille, jotka vartioitsevat Herran majaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Ja Moses ja pappi Eleatsar tekivät niinkuin Herra oli käskenyt Mosekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Ja se saalisluku mikä jäänyt oli siitä minkä sotaväki ryöstänyt oli, oli kuusisataa tuhatta, ja viisikahdeksattakymmentä tuhatta lammasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Kaksikahdeksattakymmentä tuhatta nautaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Yksiseitsemättäkymmentä tuhatta aasia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Vaimoväkeä, jotka ei olleet miehen kanssa maanneet, oli kaksineljättäkymmentä tuhatta sielua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Ja se puoli, joka heille tuli, jotka sodassa olleet olivat, oli lukuansa kolmesataa tuhatta, seitsemänneljättäkymmentä tuhatta ja viisisataa lammasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Siitä tuli Herralle kuusisataa ja viisikahdeksattakymmentä lammasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Niin myös kuusineljättäkymmentä tuhatta nautaa, ja siitä Herralle kaksikahdeksattakymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Niin myös kolmekymmentä tuhatta ja viisisataa aasia, ja siitä tuli Herralle yksiseitsemättäkymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Niin myös ihmisten sieluja kuusitoistakymmentä tuhatta, ja niistä tuli Herralle kaksineljättäkymmentä sielua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Ja Moses antoi Herran ylennysuhrin osan papille Eleatsarille, niinkuin Herra oli hänelle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Mutta toisesta puolesta, jonka Moses Israelin lapsille jakanut oli sotamiehiltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'Se puoli, mikä kansalle tuli, oli kolmesataa tuhatta, seitsemänneljättäkymmentä tuhatta ja viisisataa lammasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Kuusineljättäkymmentä tuhatta nautaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Kolmekymmentä tuhatta ja viisisataa aasia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Ja kuusitoistakymmentä tuhatta ihmisten sielua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Ja Moses otti siitä puolesta osasta, joka Israelin lasten oli, aina yhden viidestäkymmenestä, sekä ihmisistä että eläimistä, ja antoi sen Leviläisille, jotka vartioitsivat Herran majaa, niinkuin Herra oli Mosekselle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Ja ne, jotka asetetut olivat sotaväestä tuhanten päälle, tuhanten ja satain päämiehet, ne menivät Moseksen tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Ja he sanoivat hänelle: sinun palvelias ovat lukeneet sotajoukon, jotka meidän allamme olivat, ja ei siitä yhtäkään puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Ja me tuomme Herralle lahjoja, senjälkeen kuin kukin löytänyt on, kultaisia kaluja, käsirenkaita, rannerenkaita, sormuksia, korvarenkaita, seppeleitä, että meidän sielumme sovitettaisiin Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Niin Moses ja pappi Eleatsar ottivat heiltä kullan kaikkinaisissa kappaleissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Ja kaikki ylennysuhrin kulta, jonka he Herralle uhrasivat, oli kuusitoistakymmentä tuhatta seitsemänsataa ja viisikymmentä sikliä, tuhanten ja satain päämiehiltä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Sillä sotaväki oli ryövännyt itsekukin edestänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Ja Moses ja pappi Eleatsar ottivat kullan tuhanten ja satain päämiehiltä, ja he veivät sen seurakunnan majaan, Israelin lapsille muistoksi Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Rubenin lapsilla oli sangen paljo karjaa, ja Gadin lapsilla oli myös aivan suuri joukko karjaa, ja he näkivät Jaeserin ja Gileadin maan, että se olis sovelias karjan laiduin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Sentähden tulivat Gadin lapset ja Rubenin lapset ja puhuivat Mosekselle, ja papille Eleatsarille, ja kansan päämiehille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarot, Dibon, Jaeser, Nimra, Hesbon, Eleale, Sebam, Nebo ja Beon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Se maa, jonka Herra on lyönyt Israelin kansan edessä, on sovelias maa karjalle, ja meillä sinun palvelioillas on karjaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Ja he (vielä) sanoivat: jos me olemme armon löytäneet sinun edessäs, niin anna sinun palvelioilles tämä maa omaksi, ettes meidän antaisi mennä Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Moses sanoi Gadin ja Rubenin lapsille: pitäiskö veljenne menemän sotaan ja teidän tänne jäämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Miksi käännätte Israelin lasten sydämet, ettei heidän pitäisi menemän ylitse siihen maahan, jonka Herra heille antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Niin tekivät teidän isännekin, koska minä lähetin heidät KadesBarneasta katsomaan tätä maata,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Ja kuin he tulivat Eskolin ojalle ja näkivät maan, käänsivät he Israelin lasten sydämen, niin ettei he siihen maahan tahtoneet mennä, jonka Herra heille tahtoi antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Ja Herran viha julmistui sinä päivänä ja hän vannoi, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Tämä kansa, joka Egyptistä lähtenyt on, kahdenkymmenen vuoden vanhasta ja sen ylitse, ei suinkaan pidä näkemän sitä maata, jonka minä Abrahamille, Isaakille ja Jakobille vannonut olen, ettei he minua uskollisesti seuranneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Paitsi Kalebia Jephunnen Kenisiläisen poikaa, ja Josuaa Nunin poikaa; sillä he uskollisesti seurasivat Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Niin Herran viha julmistui Israelissa, ja laski heidät menemään korpeen sinne ja tänne neljäksikymmeneksi vuodeksi, siihenasti kuin kaikki se sukukunta hukkui, joka Herran edessä pahaa tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Ja katso, te olette nousseet isäinne siaan, syntisten joukko, lisäämään vielä Herran vihan julmuutta Israelia vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Sillä jos te käännytte hänestä pois, niin hän antaa teidän enemmän aikaa viipyä korvessa, ja niin te turmelette kaiken tämän kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Niin he kävivät edes ja sanoivat: me rakennamme ainoastansa tähän pihatoita karjallemme, ja kaupungeita lapsillemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Mutta me tahdomme olla joudukkaat varustettuina käymään Israelin lasten edellä, siihenasti että me johdatamme heitä sioillensa; vaan lapsemme ovat näissä vahvoissa kaupungeissa maan asuvaisten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Emme myös palaja huoneisiimme, siihenasti että Israelin lapset itsekukin saavat perintönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Sillä emme tahdo heidän kanssa periä toisella puolella Jordania eli etempää; vaan meidän perintömme olkoon tällä puolella Jordania itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Ja Moses sanoi heille: jos tämän teette, että hankitsette teitänne sotaan Herran edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'Niin menkäät Herran edessä Jordanin ylitse, jokainen kuin teistä hankittu on, siihenasti että hän ajaa kaikki vihollisensa pois kasvoinsa edestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'Ja maa tulee Herran edessä alamaiseksi; sitte pitää teidän palajaman jällensä ja oleman viattomat Herran ja Israelin edessä, ja niin tämä maa on teidän omanne Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mutta jos ette niin tee, katso, niin te rikotte Herraa vastaan, ja teidän pitää tietämän teidän rikoksenne, että se käsittää teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Niin rakentakaat siis kaupungeita lapsillenne, ja pihatoita karjallenne, ja tehkäät niinkuin te sanoitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Gadin ja Rubenin lapset sanoivat Mosekselle: sinun palvelias tekevät niinkuin minun Herrani on käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Meidän lapsemme, emäntämme, tavaramme ja kaikki meidän karjamme pitää jäämän Gileadin kaupunkeihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Mutta me sinun palvelias lähdemme kaikki yhdessä joukossa hankittuina sotaan Herran edessä, niinkuin minun Herrani sanonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Niin Moses käski heidän puolestansa pappia Eleatsaria, ja Josuaa Nunin poikaa, ja Israelin lasten sukukuntain ylimmäisiä isiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Ja sanoi heille: jos Gadin ja Rubenin lapset menevät teidän kanssanne Jordanin ylitse, kaikki hankittuina sotaan Herran edessä, ja te saatte kaikki maan allenne, niin antakaat heille Gileadin maa omaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Vaan jos ei he mene hankittuina teidän kanssanne, niin pitää heidän perimän teidän kanssanne Kanaanin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Gadin ja Rubenin lapset vastasivat, ja sanoivat: niinkuin Herra on puhunut sinun palvelioilles, niin me teemme:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Me menemme hankittuina Herran eteen Kanaanin maalle, ja omistamme perintöosamme tällä puolella Jordania.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Niin Moses antoi Gadin ja Rubenin lapsille ja puolelle Manassen Josephin pojan sukukunnalle Sihonin Amorilaisten kuninkaan valtakunnan ja Ogin Basanin kuninkaan valtakunnan: maan kaupunkeinensa, jotka niissä maan äärissä ympärillä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Ja Gadin lapset rakensivat Dibonin, Atarotin, Aroerin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atarot-Sophanin, Jaeserin, Jogbehanin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Betnimran ja Betaranin, vahvat kaupungit ja pihatot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Rubenin lapset rakensivat Hesbonin, Elealen, Kirjataimin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Ja Nebon, BaalMeonin, MusabotSemin ja Sibman, ja antoivat nimet niille kaupungeille, jotka he rakensivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Ja Makirin Manassen pojan lapset menivät Gileadiin ja voittivat sen, ja ajoivat ulos Amorilaiset, jotka siellä asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Niin Moses antoi Makirille Manassen pojalle Gileadin, ja hän asui siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Mutta Jair Manassen poika meni, ja voitti heidän maakylänsä, jotka hän kutsui Jairin kyliksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Meni myös Noba, ja voitti Kenatin tyttärinensä, ja hän kutsui sen Nobaksi nimestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Nämät ovat Israelin lasten matkustukset, kuin he läksivät Egyptin maalta, joukkoinsa jälkeen, Moseksen ja Aaronin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Ja Moses kirjoitti heidän matkustuksensa, niinkuin he matkustivat Herran käskyn jälkeen. Ja nämät ovat heidän matkustuksensa heidän lähdentönsä jälkeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Ja he matkustivat Ramesesta viidentenätoistakymmenentenä päivänä ensimäisenä kuukautena: toisena päivänä pääsiäisestä, läksivät Israelin lapset ulos korkian käden kautta, kaikkein Egyptiläisten nähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Ja Egyptiläiset hautasivat kaikki esikoisensa, jotka Herra heidän seassansa lyönyt oli, ja Herra oli myös antanut tuomion käydä heidän jumalainsa ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Koska Israelin lapset olivat vaeltaneet Ramesesta, niin he sioittivat itsensä Sukkotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Ja matkustivat Sukkotista, ja sioittivat itsensä Etamiin, joka on korven äärellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Ja he matkustivat Etamista ja palasivat PiiHahirotiin, joka on BaalZephoniin päin, ja sioittivat itsensä Migdolin kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Ja he matkustivat Hahirotin editse ja kävivät keskeltä merta korpeen, ja matkustivat kolme päiväkuntaa Etamin korvessa, ja sioittivat itsensä Maraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Ja he matkustivat Marasta ja tulivat Elimiin: ja Elimissä oli kaksitoistakymmentä lähdettä, ja seitsemänkymmentä palmupuuta, ja sioittivat itsensä siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Ja he matkustivat Elimistä, ja sioittivat itsensä Punaisen meren tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Ja matkustivat Punaisen meren tyköä, ja sioittivat itsensä Sinin korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Ja he matkustivat Sinin korvesta, ja sioittivat itsensä Dophkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Ja he matkustivat Dophkasta, ja sioittivat itsensä Alusiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Ja he matkustivat Alusista, ja sioittivat itsensä Raphidimiin, ja siinä ei ollut kansalle vettä juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Ja he matkustivat Raphidimista, ja sioittivat itsensä Sinain korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Ja he matkustivat Sinain korvesta, ja sioittivat itsensä Himohaudoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Ja he matkustivat Himohaudoilta, ja sioittivat itsensä Hatserotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Ja he matkustivat Hatserotista, ja sioittivat itsensä Ritmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Ja he matkustivat Ritmasta, ja sioittivat itsensä Rimmon Paretsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Ja he matkustivat Rimmon Paretsista, ja sioittivat itsensä Libnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Ja he matkustivat Libnasta, ja sioittivat itsensä Rissaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Ja he matkustivat Rissasta, ja sioittivat itsensä Kehelaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Ja he matkustivat Kehelasta, ja sioittivat itsensä Sapherin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Ja he matkustivat Sapherin vuorelta, ja sioittivat itsensä Haradaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Ja he matkustivat Haradasta ja sioittivat itsensä Makhelotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Ja he matkustivat Makhelotista, ja sioittivat itsensä Tahatiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Ja he matkustivat Tahatista, ja sioittivat itsensä Taraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Ja he matkustivat Tarasta, ja sioittivat itsensä Mitkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Ja he matkustivat Mitkasta, ja sioittivat itsensä Hasmonaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Ja he matkustivat Hasmonasta, ja sioittivat itsensä Moserotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Ja he matkustivat Moserotista, ja sioittivat itsensä BeneJaekaniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Ja he matkustivat BeneJaekanista, ja sioittivat itsensä Horgidgadiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Ja he matkustivat Horgidgadista, ja sioittivat itsensä Jotbataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Ja he matkustivat Jotbatasta, ja sioittivat itsensä Abronaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Ja he matkustivat Abronasta, ja sioittivat itsensä Etseongeberiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Ja he matkustivat Etseongeberistä, ja sioittivat itsensä Sinin korpeen, se on Kades.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Ja he matkustivat Kadeksesta, ja sioittivat itsensä Horin vuorelle, joka on Edomin maan rajoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Siinä meni pappi Aaron Horin vuorelle, Herran käskyn jälkeen, ja kuoli siellä neljäntenäkymmenentenä vuotena, sittekuin Israelin lapset olivat lähteneet Egyptin maalta, ensimäisenä päivänä viidennestä kuusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Ja Aaron oli sadan ja kolmenkolmattakymmentä vuotinen kuollessansa Horin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Silloin kuuli Arad Kanaanealaisten kuningas, joka asui etelään päin Kanaanin maalla, että Israelin lapset tulleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Ja he matkustivat Horin vuorelta, ja sioittivat itsensä Salmonaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Ja he matkustivat Salmonasta, ja sioittivat itsensä Phunoniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Ja he matkustivat Phunonista, ja sioittivat itsensä Obotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Ja he matkustivat Obotista, ja sioittivat itsensä Iije Abarimiin, Moabin rajoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Ja he matkustivat Iijestä, ja sioittivat itsensä DibonGadiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Ja he matkustivat DibonGadista, ja sioittivat itsensä AlmonDiblataimiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Ja he matkustivat AlmonDiblataimista, ja sioittivat itsensä Abarimin vuorille Nebon kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Ja he matkustivat Abarimin vuorilta, ja sioittivat itsensä Moabin kedoille, Jordanin tykö, Jerihon kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Ja he sioittivat itsensä Jordanin tykö hamasta BetJesimotista, niin AbelSittimiin Moabin kedoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Ja Herra puhui Mosekselle, Moabin kedoilla, Jordanin tykönä Jerihon kohdalla, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Puhu Israelin lapsille, ja sano heille: kuin te olette tulleet Jordanin ylitse Kanaanin maalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Niin teidän pitää kaikki sen maan asuvaiset teidän edestänne ajaman pois, ja kaikki heidän maalauksensa ja valetut kuvansa hukuttaman, ja kaikki heidän korkeutensa hävittämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Ja niin teidän pitää maan omistaman ja asuman siinä; sillä teille olen minä maan antanut omistaaksenne sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Ja teidän pitää maan jakaman arvalla teidän sukukunnillenne. Joita usiampi on, niille pitää teidän enempi antaman perinnöksensä, ja joita vähempi on, niille vähemmän perinnöksensä; kuin arpa lankee kullekin, niin pitää hänen sen ottaman: teidän isäinne sukukuntain jälkeen pitää teidän perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Mutta jollette maan asuvaisia aja ulos teidän edestänne, niin pitää ne, jotka te heistä jätätte, oleman teille niinkuin orjantappurat silmissänne, ja keihäs kyljessänne; sillä heidän pitää ahdistaman teitä sillä maalla, kussa te asutte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Niin tapahtuu, että minä teen niin teille, kuin minä aioin heille tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Käske Israelin lapsille, ja sano heille: kuin te tulette Kanaanin maalle, niin pitää se maa oleman se, joka teille perimiseksi lankee, Kanaanin maa rajainsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Etelän puoli pitää rupeeman Sinin korvesta Edomin tyköä, niin että teidän rajanne etelään päin pitää käymän Suolaisen meren äärestä, joka itään päin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Ja se raja pitää teille käymän ympäri etelästä Akrabimin palttaa myöten ja menemän Siniin, niin että sen uloskäyminen eteläpuolelta on KadesBarneaan päin, että se ulottuu Hatsar Adariin, ja menee Asmoniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Sitte pitää rajan menemän ympäri Asmonista Egyptin virtaan asti, niin että sen loppu on meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Mutta raja länteen päin pitää oleman teille suuri meri: se pitää oleman teidän maanne ääri länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Ja tämä pitää raja pohjaa päin oleman: teidän pitää määräämän sen suuresta merestä hamaan Horin vuoreen asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Ja Horin vuoresta määräämän siihenasti että Hamatiin tullaan, niin että rajan loppu on Zedassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Ja raja menköön Ziphroniin ja sen loppu olkoon HatsarEnanissa. Se olkoon rajanne pohjoista päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Ja pitää myös määräämän rajanne itään päin, Enanista niin Sephamiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Ja raja menkään alas Sephamista Riblaan, Ainin itäpuolella; sitte juoskaan alaspäin, ja menkään Kinneretin meren sivutse idän puolella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Ja tulkaan raja alas Jordaniin päin ja sen loppu olkoon Suolainen meri. Sen pitää oleman teidän maanne, rajoinensa joka taholta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Ja Moses käski Israelin lapsille ja sanoi: tämä on maa, jonka teidän pitää jakaman keskenänne arvalla, jonka Herra käski antaa niille yhdeksälle sukukunnalle, ja sille puolelle sukukunnalle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Sillä Rubenin lasten sukukunta, heidän isäinsä huoneen jälkeen, ja Gadin lasten sukukunta heidän isäinsä huoneen jälkeen, ja puoli Manassen sukukuntaa ovat jo ottaneet osansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Niin ovat ne kaksi sukukuntaa, ja se puoli sukukuntaa saaneet perintöosansa tällä puolella Jordania, Jerihon kohdalle itää päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Nämät ovat miesten nimet, joiden pitää jakaman maan teille: pappi Eleatsar ja Josua Nunin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Siihen pitää myös teidän ottaman yhden päämiehen jokaisesta sukukunnasta, maata jakamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Ja nämät ovat miesten nimet: Juudan sukukunnasta, Kaleb Jephunnen poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Simeonin lasten sukukunnasta, Semuel Ammihudin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'BenJaminin sukukunnasta, Elidad Kislonin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Danin lasten sukukunnan päämies, Bukki Joglin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Josephin lapsista, Manassen sukukunnan päämies, Haniel Ephodin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Ephraimin lasten sukukunnan päämies, Kemuel Siphtanin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Sebulonin lasten sukukunnan päämies, Elitsaphan Parnakin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Isaskarin lasten sukukunnan päämies, Patiel Assan poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Asserin lasten sukukunnan päämies, Ahihud Selomin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Naphtalin lasten sukukunnan päämies, Pedahel Ammihudin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Nämät ovat ne jotka Herra käskenyt on Israelin lasten perintöosaa jakamaan Kanaanin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Ja Herra puhui Mosekselle, Moabin kedoilla, läsnä Jordania Jerihon kohdalla, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Käske Israelin lasten perimisestänsä antaa Leviläisille kaupungeita heidän asuaksensa, antakaat myös esikaupungit niiden ympärille Leviläisille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Että he asuisivat kaupungeissa, ja pitäisivät karjansa, tavaransa ja kaikkinaiset eläimensä esikaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Esikaupunkein laveus, jotka teidän pitää antaman Leviläisille, pitää oleman tuhannen kyynärää kaupungin muurista ulos, kaikki ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Niin teidän pitää mittaaman ulkopuolelle kaupunkia idän puolelle kaksituhatta kyynärää, ja etelän puolelle kaksituhatta kyynärää, ja lännen puolelle kaksituhatta kyynärää, ja pohjan puolelle kaksituhatta kyynärää, että kaupunki keskellä olis: se pitää oleman heidän esikaupunkinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Ja niiden kaupunkein seassa, mitkä te annatte Leviläisille, pitää teidän antaman kuusi vapaakaupunkia, että se joka jonkun kuoliaaksi lyö, pakenis niihin. Vielä päälliseksi pitää teidän antaman heille kaksiviidettäkymmentä kaupunkia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Niin että kaikkiansa kaupungeita, jotka annatte Leviläisille, tulee kahdeksanviidettäkymmentä, esikaupunkeinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Ja ne kaupungit, jotka te annatte Israelin lasten omaisuudesta, pitää heille annettaman enempi siltä, jolla paljo on, ja vähempi siltä, jolla vähempi on: itsekukin perimisensä jälkeen, joka hänelle jaettu on, pitää antaman Leviläisille kaupungeita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Ja Herra puhui Mosekselle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Puhu Israelin lapsille ja sano heille: tultuanne Jordanin ylitse Kanaanin maalle');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Pitää teidän valitseman teillenne kaupungeita, jotka teille vapaat kaupungit oleman pitää, joihin tappaja paetkaan, se kuin tapaturmasta jonkun kuoliaaksi lyö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Ja pitää senkaltaiset vapaakaupungit oleman teidän seassanne, verenkostajan tähden, ettei tappajan pidä kuoleman, siihenasti että hän koko seurakunnan oikeuden edessä on seisonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Ja ne kaupungit, jotka teidän antaman pitää, pitää oleman teille kuusi vapaakaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Kolme kaupunkia pitää teidän antaman tällä puolella Jordania, ja kolme Kanaanin maalla: ne pitää oleman vapauskaupungit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Sekä Israelin lapsille, että muukalaisille ja huonekuntalaisille heidän seassansa, pitää ne kuusi kaupunkia oleman pakoa varten, että sinne pakenis kuka ikänä jonkun sielun tapaturmaisesti lyö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Joka jonkun lyö rautaisella aseella, niin että hän kuolee, hän on miehentappaja: sen miestappajan pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Jos hän paiskaa jonkun kivellä, joka hänen kädessänsä on, josta kuolla taidetaan, ja se kuolee, niin hän on miehentappaja, ja pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Jos hän lyö häntä jollakulla puuaseella, josta taidetaan kuolla, ja se kuolee, hän on miehentappaja, ja pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Verenkostajan pitää itse tappaman miehentappajan: kohdatessansa häntä, pitää hänen sen kuolettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Jos hän syöksee hänen vihasta taikka paiskaa häntä väijymisessä, niin että hän kuolee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Taikka vihasta lyö häntä kädellänsä, niin että hän kuolee, niin pitää sen totisesti kuoleman, joka hänen löi; sillä hän on miehentappaja. Veren lähimmäinen lanko pitää tappaman hänen kohdatessansa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mutta jos hän syöksee hänen tapaturmasta ilman vihata, taikka heittää jotakin hänen päällensä ilman väijymystä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Taikka heittää häntä kivellä, josta kuolla taidetaan, ja ei sitä nähnyt, niin että hän kuolee, ja ei ole hänen vihamiehensä, ei myös hänelle mitäkään pahaa aikonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Niin pitää kansan tuomitseman lyöjän ja verenkostajan välillä, näiden oikeutten jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Ja kansan pitää vapahtaman miehentappajan verenkostajan käsistä, antaen hänen tulla vapaakaupunkiin jälleen, johon hän pakeni; ja siellä pitää hänen oleman ylimmäisen papin kuolemaan asti, joka pyhällä öljyllä voideltu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Mutta jos miehentappaja rohkiasti menee vapaakaupunkinsa rajain ylitse, johon hän paennut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'Ja verenkostaja löytää hänen ulkona vapaakaupunkinsa rajoista, ja lyö hänen kuoliaaksi, niin ei pidä hänen sen vereen syypää oleman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Sillä hänen piti vapaakaupungissansa oleman ylimmäisen papin kuolemaan asti ja ylimmäisen papin kuoleman jälkeen tuleman perintömaallensa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Nämät pitää oleman teille ja teidän lapsillenne oikeuden säädyksi, kaikissa teidän asumasioissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Joka lyö jonkun kuoliaaksi, se miehentappaja pitää tapettaman todistajain suun jälkeen, ja yksi todistaja ei pidä sielua vastaan täysi todistus oleman kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Ja ei teidän pidä ottaman yhtäkään hintaa miehentappajan hengen edestä, joka itse pahuudesta on kuoleman matkaan saattanut; sillä hänen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Ja ei pidä teidän yhtäkään hintaa ottaman siltä, joka vapaakaupunkiinsa paennut oli, niin että hän tulis jälleen asumaan maalle ennen papin kuolemaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Ja älkäät saastuttako maata, jossa te asutte; sillä se joka vereen vikapää on, hän saastuttaa maan, ja maa ei taida puhdistettaa verestä, joka siihen vuodatettu on, muutoin kuin sen veren kautta, joka sen vuodattanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Älkäät te saastuttako maata, jossa te asutte, jossa myös minä asun; sillä minä olen Herra, joka asun Israelin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Ja ylimmäiset isät, Gileadin lasten suvusta, Makirin pojan, joka oli Manassen poika, Josephin lasten suvusta, kävivät edes, ja puhuivat Moseksen ja Israelin lasten ylimmäisten edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Ja sanoivat: Herra käski minun Herrani jakaa maan arvalla Israelin lapsille perittäväksi. Ja sinä minun Herrani olet käskenyt Herran kautta, meidän veljemme Zelophkadin perimyksen antaa hänen tyttärillensä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Jos joku Israelin suvusta ottaa heitä emännäksensä, niin tulee heidän perintönsä vähemmäksi, meidän isäimme perinnöstä, ja tulee sen suvun perimyksen tykö, kuhunka he tulevat, ja niin tulee meidän perimyksemme arpa vähennetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Kuin Israelin lasten ilovuosi tulee, niin tulee heidän perintöosansa sen suvun perimykseen, johonka he tulevat, niin tulee meidän isäimme perimys vähennetyksi, heidän perinnöksestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Niin käski Moses Israelin lapsille Herran käskyn jälkeen, ja sanoi: Josephin lasten suku on oikein puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Tämä on se minkä Herra käski Zelophkadin tyttärille ja sanoi: huolkaan kellenkä tahtovat, kuitenkin niin, että he huolevat isäinsä sukukunnan langoille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Ettei Israelin lasten perimys menisi yhdestä suvusta niin toiseen; sillä jokainen Israelin lasten seassa pitää riippuman kiinni isäinsä sukukunnan perimyksessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Ja kaikki tyttäret, joilla perimys on Israelin lasten suvussa, pitää huoleman jollekulle isänsä suvun langolle, että jokainen Israelin lasten seassa pitäis isänsä perimyksen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Ja ettei perintöosa menisi yhdestä sukukunnasta toiseen; vaan jokainen riippukaan omassa perimyksessänsä Israelin lasten sukuin seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Niinkuin Herra käski Mosekselle, niin tekivät Zelophkadin tyttäret:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Makla, Tirtsa, Hogla, Milka, Noa, Zelophkadin tyttäret, huolivat setäinsä pojille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Ja tulivat emänniksi niille, jotka olivat Manassen Josephin pojan suvusta; niin pysyi heidän perimyksensä sillänsä lankoudessansa, heidän isänsä sukukunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Nämät ovat ne käskyt ja oikeudet, joita Herra Moseksen kautta käski Israelin lapsille, Moabin kedoilla, Jordanin tykönä, Jerihon kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Nämät ovat ne sanat, mitkä Moses puhui koko Israelille, tällä puolella Jordania korvessa, sillä kedolla Punaisen meren kohdalla, Paranin,ja Tophelin, ja Labanin, ja Hatserotin ja Disahabin vaiheella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Yksitoistakymmentä päiväkuntaa Horebista, sitä tietä Seirin vuoren kautta niin KadesBarneaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Ja tapahtui neljäntenäkymmenentenä vuonna, ensimäisenä päivänä, ensimäisellä kuukaudella toistakymmentä, että Moses puhui Israelin lapsille kaikki, mitä Herra hänen käski heille puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Sittekuin hän oli lyönyt Sihonin Amorilaisten kuninkaan, joka Hesbonissa asui, niin myös Ogin, Basanin kuninkaan, joka Astarotissa Edreissä asui,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Tällä puolella Jordania, Moabin maalla, rupesi Moses selittämään tätä lakia ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Herra meidän Jumalamme puhui meille Horebissa, sanoen: te olette jo kyllä kauvan olleet tällä vuorella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Kääntäkäät teitänne ja menkäät matkaan Amorilaisten vuorelle, ja kaikkein heidän läsnä asuvaistensa tykö, kedoilla, vuorella ja laaksossa, etelämaalle, ja meren satamissa, Kanaanin maalle ja Libanoniin, hamaan suuren Phratin virran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Katso, minä annoin teille maan, joka on teidän edessänne: menkäät ja omistakaat se maa, niinkuin Herra teidän isillenne Abrahamille, Isaakille ja Jakobille vannoi, antaaksensa sen heille ja heidän siemenellensä heidän jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Ja minä puhuin teille silloin, sanoen: en minä voi yksinäni kantaa teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Sillä Herra teidän Jumalanne on lisännyt teitä, niin että te tänäpänä olette niin monta, kuin tähdet taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Herra teidän isäinne Jumala lisätköön teitä vielä monta tuhatta kertaa enempi, ja siunatkoon teitä, niinkuin hän teille sanonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Kuinka minä yksinäni voin kantaa senkaltaisen vaivan, kuorman ja riidan teiltä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Valitkaat teistänne toimelliset ja ymmärtäväiset miehet, jotka teidän suvustanne tunnetut ovat, ja minä asetan heitä teidän päämiehiksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Niin te vastasitte minua, sanoen: se on hyvä asia, josta puhut tehdäkses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Niin minä otin ylimmäiset teidän suvuistanne, toimelliset ja tunnetut miehet, ja asetin teille päämiehiksi, tuhannen, sadan, viidenkymmenen ja kymmenen päälle, ja esimiehiksi sukukunnissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Ja minä käskin tuomareille silloin, sanoen: kuulkaat teiden veljiänne, ja tuomitkaat oikein jokaisen miehen ja hänen veljensä vaiheella, ja hänen muukalaisensa vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Ei teidän pidä katsoman kenenkään muotoa tuomiossa, vaan kuulkaat niin pientä, kuin suurtakin: älkäät peljätkö kenenkään muotoa; sillä tuomio on Jumalan: vaan se asia, mikä teille on raskas, antakaat tulla minun eteeni, kuullakseni sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Ja minä käskin teitä siihen aikaan kaikista, mitä teidän tekemän piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Niin me läksimme Horebista, ja vaelsimme kaiken sen suuren ja hirmuisen korven lävitse, jonka te nähneet olette Amorilaisten vuoren tiellä, niinkuin Herra meidän Jumalamme meille käski. Ja tulimme KadesBarneaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Niin sanoin minä teille: te olette tulleet Amorilaisten vuoreen asti, jonka Herra meidän Jumalamme antaa meille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Katso sitä maata sinun edessäs, jonka Herra sinun Jumalas sinulle antanut on, mene, ja omista se niinkuin Herra sinun isäis Jumala sinulle sanonut on: älä pelkää, älä myös hämmästy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Ja te tulitte kaikki minun tyköni, ja sanoitte: lähettäkäämme miehet meidän edellämme vakoomaan maata, ja meille asiaa ilmoittamaan, ja tietä, jota meidän sinne menemän pitää, ja kaupungeita, joihin meidän tuleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Ja se asia kelpasi minulle: niin otin minä kaksitoistakymmentä miestä teidän seastanne, jokaisesta sukukunnasta yhden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Ne menivät matkaansa, ja astuivat vuorelle, ja tulivat Eskolin ojaan asti, ja vakosivat sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Ja ottivat maan hedelmästä myötänsä ja toivat meille, ja ilmoittivat meille asian, ja sanoivat: maa on hyvä, jonka Herra meidän Jumalamme meille antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Mutta ette tahtoneet mennä sinne, vaan olitte vastahakoiset Herran teidän Jumalanne sanalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Ja napisitte majoissanne ja sanoitte: Herra on meille vihainen, ja on tuonut meitä ulos Egyptin maalta, antaaksensa meitä Amorilaisten käsiin, hukutettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Kuhunka me menemme? Meidän veljemme ovat peljättäneet meidän sydämemme, sanoen: se kansa on suurempi ja pitempi meitä, ja ne kaupungit ovat suuret ja varustetut taivaasen asti: olemme myös nähneet siellä Enakin pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Ja minä sanoin teille: älkäät hämmästykö, älkäät myös peljästykö heitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Sillä Herra teidän Jumalanne käy teidän edellänne, ja sotii teidän edestänne, niin kuin hän myös tehnyt on Egyptissä teille teidän silmäinne edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Ja korvessa, jossa sinä olet nähnyt, kuinka Herra sinun Jumalas on sinun kantanut, niinkuin mies kantaa poikansa, kaikella sillä tiellä, jota te vaeltaneet olette, siihenasti kuin te tälle paikalle tulitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Vaan ette siitä lukua pitäneet, uskoa Herran teidän Jumalanne päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Joka kävi tiellä teidän edellänne, tiedustamaan leirin paikkaa, yöllä tulessa, osoittaen teille tietä jota te kävitte, ja päivällä pilvessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Koska Herra kuuli teidän huutonne, vihastui hän ja vannoi, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Ei yksikään tästä pahasta sukukunnasta pidä näkemän sitä hyvää maata, jonka minä olen vannonut, antaakseni teidän isillänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Paitsi Kalebia Jephunnen poikaa, hän näkee sen, hänelle minä annan sen maan, jonka päälle hän astunut on, ja myös hänen lapsillensa, että hän uskollisesti seurasi Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Ja Herra vihastui myös minulle teidän tähtenne, et sinäkään sinne tule;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Vaan Josua Nunin poika, sinun palvelias, hän tulee sinne: vahvista häntä; sillä hänen pitää asettaman Israelin perimykseensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Ja teidän lapsenne, jotka te sanoitte saaliiksi tulevan, ja teidän poikanne, jotka ei tänäpänä tiedä hyvää eli pahaa, he tulevat sinne, ja minä annan sen heille, ja heidän pitää sen omistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Vaan palatkaat te ja menkäät korpeen, Punaisen meren tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Niin te vastasitte ja sanoitte minulle: me olemme rikkoneet Herraa vastaan: me menemme ja sodimme, niinkuin Herra meidän Jumalamme meille käskenyt on. Kuin te siis valmiit olitte, jokainen sota-aseinensa, ja ynseydessä menitte vuorelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Sanoi Herra minulle: sano heille: ei teidän pidä sinne menemän, eikä myös sotiman, sillä en minä ole teidän kanssanne, ettette lyötäisi teidän vihollistenne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Koska minä näin teille sanoin, niin ette kuulleet minua, vaan olitte Herran sanalle vastahakoiset, ja olitte röyhkeät menemään vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Niin läksivät Amorilaiset, jotka vuorella asuivat, teitä vastaan, ja ajoivat teitä takaa niinkuin kimalaiset tekevät, ja löivät teitä maahan Seirissä Hormaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Kuin te sieltä palasitte ja itkitte Herran edessä, niin ei Herra tahtonut kuulla teidän ääntänne, eikä korviinsa ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Niin olette te olleet Kadeksessa kauvan aikaa, niiden päiväin luvun jälkeen, kuin te viivyitte siellä (odottain vakoojia).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Silloin me palasimme ja matkustimme korpeen Punaisen meren tietä, niinkuin Herra minulle sanonut oli, ja vaelsimme Seirin vuorta ympäri kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Ja Herra puhui minulle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Jo te olette kyllä vaeltaneet tätä vuorta ympäri, palatkaat pohjoiseen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Ja käski kansalle, sanoen: teidän pitää vaeltaman teidän veljenne Esaun lasten rajain ylitse, jotka Seirissä asuvat, ja he pelkäävät teitä; mutta karttakaat teitänne sangen visusti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Älkäät alkako sotaa heitä vastaan; sillä en minä anna teille jalankaan leveyttä heidän maastansa; sillä Esaun lapsille olen minä antanut Seirin vuoren perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Rahalla pitää teidän heiltä ruuan ostaman, jonka te syötte, niin myös veden pitää teidän heiltä rahalla ostaman, jota te juotte:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Sillä Herra sinun Jumalas on siunannut sinun, kaikissa sinun kättes töissä, hän tietää sinun matkustukses tässä suuressa korvessa. Jo neljäkymmentä ajastaikaa on Herra sinun Jumalas ollut sinun kanssas, niin ettei sinulta mitäkään ole puuttunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Kuin me veljemme Esaun lasten tyköä vaeltaneet olimme, jotka Seirin vuorella asuivat, sitä kedon tietä Elatista ja Etseongeberistä, niin palasimme me, ja menimme Moabin korven tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Ja Herra sanoi minulle: älä vahingoitse Moabilaisia, älä myös sekoita itsiäs sotaan heidän kanssansa; silä en minä anna sinulle mitäkään hänen maastansa perimiseksi; sillä Lotin lapsille olen minä antanut Arin perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Emiläiset ovat muinen sillä paikalla asuneet, jotka olivat suuri, väkevä ja pitkä kansa, niinkuin Enakilaiset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'He luultiin myös Refalaisiksi, niinkuin Enakilaiset, ja Moabilaiset kutsuivat heitä Emiläisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Asuivat myös muinen Horilaiset Seirissä, ja Esaun lapset ajoivat pois ja hukuttivat ne edestänsä, ja asuivat heidän siassansa: niinkuin Israel teki perintömaassansa, jonka Herra heille antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Niin nouskaat nyt, ja matkustakaat Saredin ojan ylitse. Ja me vaelsimme Saredin ojan ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Vaan aika, kuin me matkustimme KadesBarneasta, siihen asti kuin me tulimme Saredin ojan ylitse, oli kahdeksan vuotta neljättäkymmentä, siihenasti kuin kaikki sotamiehet leirissä olivat hukkuneet, niinkuin Herra heille vannonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Sillä Herran käsi oli heitä vastaan, hukuttamaan heitä leirissä, siihenasti kuin hän peräti lopetti heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Kuin kaikki sotamiehet olivat loppuneet ja kuolleet kansan seasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Puhui Herra minulle, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Tänäpänä pitää sinun matkustaman Moabin rajain yli, lähellä Aria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Ja kuin lähestyt Ammonin lapsia, älä heitä vahingoitse, älä myös sekoita itsiäs sotaan heidän kanssansa; sillä en minä anna sinulle Ammonin lasten maata perimiseksi; vaan Lotin lapsille olen minä sen antanut perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Se on myös luettu Refalaisten maaksi; sillä Refalaiset ovat muinen siinä asuneet. Ja Ammonilaiset kutsuvat heidät Samsumilaisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Sillä he olivat suuri, väkevä ja pitkä kansa, niinkuin Enakilaiset. Ja Herra hävitti heitä heidän edestänsä, niin että he ajoivat heidät ulos, ja asuivat heidän siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Niinkuin hän oli tehnyt Esaun lapsille Seirin vuorella asuvaisille, hävittäissänsä Horilaiset heidän edestänsä, niin että he ovat heidät ajaneet ulos, ja asuneet heidän siassansa tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Availaiset asuivat maakylissä Gatsaan asti; mutta Kaphtorilaiset läksivät Kaphtorista ja hävittivät ne, ja asuivat heidän siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Nouskaat ja lähtekäät, ja matkustakaat Arnonin ojan ylitse: katso, minä annoin sinun käsiis Sihonin Amorilaisten kuninkaan Hesbonissa, mainensa, rupee siis omistamaan, ja sotimaan häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Tänäpänä minä alan tuottamaan kaiken kansan päälle koko taivaan alla pelvon ja vapisemisen sinun edessäs, niin että he, sanoman sinusta kuultuansa, pitää värisemän, ja surulliset oleman sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Niin minä lähetin sanansaattajat Kedemotin korvesta Sihonille Hesbonin kuninkaalle rauhallisilla sanoilla, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Minä tahdon vaeltaa sinun maakuntais lävitse, ja niinkuin tie antaa, niin minä vaellan: en minä oikialle puolelle enkä vasemmalle poikkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Ruokaa pitää sinun rahan edestä antaman minulle syödä, ja vettä rahan edestä juoda: minä käyn vaivoin joudukkaasti sen lävitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Niinkuin Esaun lapset, jotka Seirissä asuvat, minulle tehneet ovat, ja Moabilaiset, jotka Arissa asuvat, siihenasti että minä tulen Jordanin ylitse, siihen maahan, jonka Herra meidän Jumalamme antaa meille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Vaan ei Sihon Hesbonin kuningas tahtonut meidän antaa vaeltaa sen lävitse; sillä Herra sinun Jumalas kovetti hänen mielensä ja paadutti hänen sydämensä, että Herra tahtoi antaa hänen sinun käsiis, niinkuin tänäpäivänä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Ja Herra sanoi minulle: katso, minä olen ruvennut antamaan Sihonin kuninkaan ja hänen maansa sinun etees: rupee omistamaan ja perintönäs pitämään hänen maatansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Ja Sihon läksi sotimaan meitä vastaan, hän ja kaikki hänen väkensä Jaksassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Mutta Herra meidän Jumalamme antoi hänen meidän eteemme, ja me löimme hänen ja hänen lapsensa ja kaikki hänen väkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Ja me otimme silloin kaikki hänen kaupunkinsa, ja hukutimme kaikki kaupungit, miehet ja vaimot ja lapset, niin ettemme yhtäkään jättäneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Paitsi eläimiä jotka me meillemme otimme, ja kaupunkein saaliin, jotka me voitimme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Hamasta Aroerista Arnonin ojan reunalla, ja siitä kaupungista ojan vieressä, niin Gileadiin asti. Ei yhtäkään kaupunkia ollut, joka taisi olla meitä väkevämpi: Herra meidän Jumalamme antoi kaikki meidän allemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Vaan Ammonin lasten maahan et sinä tullut, etkä mihinkään, joka oli Jabbokin ojan tykönä, eikä niihin kaupunkeihin vuorella, taikka johonkuhun muuhun, josta Herra meidän Jumalamme meitä kieltänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Ja me palasimme ja menimme Basanin tietä: niin Og Basanin kuningas läksi kaiken väkensä kanssa meitä vastaan sotimaan Edrein tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Mutta Herra sanoi minulle: älä pelkää häntä; sillä minä olen antanut hänen sinun käsiis ja kaiken hänen väkensä ja hänen maansa, ja sinun pitää tekemän hänelle, niinkuin sinä teit Sihonille Amorilaisten kuninkaalle, joka Hesbonissa asui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Ja niin Herra meidän Jumalamme antoi kuningas Ogin Basanista meidän käsiimme, ynnä kaiken hänen väkensä kanssa, ja me löimme hänen siihenasti ettei hänelle yhtäkään jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Ja silloin me otimme kaikki hänen kaupunkinsa, ja ei ollut hänellä yhtään kaupunkia, jota emme häneltä ottaneet pois: kuusikymmentä kaupunkia, ja koko Argobin maakunnan, joka oli Ogin valtakunnassa Basanissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Ja kaikki nämät kaupungit olivat vahvistetut korkeilla muureilla, porteilla ja teljillä, paitsi monta muuta kaupunkia, jotka olivat erinäiset maakylät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Jotka me kaikki maahan kukistimme, niinkuin me Sihonille Hesbonin kuninkaalle teimme: me hävitimme kaiken kaupungin miehet, vaimot ja myös lapset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Vaan kaikki eläimet, ja kaiken saaliin kaupungeista, otimme me meillemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Ja niin me otimme siihen aikaan sen maan kahden Amorilaisten kuninkaan kädestä, sillä puolella Jordania, Arnonin ojasta niin Hermonin vuoreen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'Sidonilaiset kutsuivat Hermonin Sirioniksi, mutta Amorilaiset kutsuivat sen Seniriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Ja kaikki kaupungit lakialla, ja koko Gileadin, ja koko Basanin, Salkaan ja Edreiin asti, Ogin valtakunnassa Basanin kaupungit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Sillä ainoastansa kuningas Og Basanissa oli jäänyt Refalaisista: katso, hänen vuoteensa, rautainen vuode, eikö se ole Ammonin lasten Rabbatissa? joka on yhdeksän kyynärää pitkä, ja neljä kyynärää lavia, miehen kyynärpään pituudelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Ja niin me siihen aikaan sen maan meillemme omistimme: Aroerista Arnonin ojan tyköä, ja puolen Gileadin mäkeä, ja sen kaupungit, annoin minä Rubenilaisille ja Gadilaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Mutta mitä Gileadista jäi ja koko Basanin Ogin valtakunnan annoin minä puolelle Manassen sukukunnalle, kaiken Argobin maakunnan, koko Basanin kanssa, joka kutsutaan Refalaisten maaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair Manassen poika sai koko Argobin maakunnan Gessurin ja Makatin maan ääriin, ja kutsui Basanin oman nimensä jälkeen Jairin kyliksi, tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Mutta Makirille minä annoin Gileadin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Ja Rubenilaisille ja Gadilaisille annoin minä osan Gileadista, Arnonin ojaan asti, keskelle ojaa, kussa raja on, niin Jabbokin ojaan asti, jossa Ammonin lasten raja on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Niin myös Araban kedon ja Jordanin ja rajamaat Kinneretistä niin kedon mereen asti, se on Suolainen meri, Pisgan vuoren alaisella puolella itää kohden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Ja minä käskin teitä sillä ajalla, ja sanoin: Herra teidän Jumalanne on antanut teille tämän maan omaksenne: menkäät aseinenne veljeinne Israelin lasten edellä, kaikki te, jotka väkevät olette sotaan menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Paitsi emäntiänne, lapsianne ja myös karjaanne, (sillä minä tiedän teillä olevan paljo karjaa) antakaat niiden olla kaupungeissanne, jotka minä teille antanut olen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Siihenasti että Herra teidän veljennekin saattaa lepoon, niinkuin teidätkin, että hekin omistaisivat sen maan, jonka Herra teidän Jumalanne heille antava on tuolla puolella Jordania: sitte te palajatte kukin omaisuuteenne, jonka minä teille antanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Ja minä käskin Josualle sillä ajalla, sanoen: sinun silmäs ovat nähneet kaikki, mitä Herra teidän Jumalanne näille kahdelle kuninkaalle on tehnyt, niin hän on myös tekevä kaikille valtakunnille, kuhunka sinä menet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Älkäät heitä peljätkö; sillä Herra teidän Jumalanne itse sotii teidän edestänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Ja minä rukoilin Herraa siihen aikaan, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Herra, Heraa, sinä olet ruvennut ilmoittamaan palvelialles sinun kunnias ja sinun vahvan kätes; sillä kuka on Jumala taivaassa eli maassa, joka taitaa sinun tekos ja väkes perään tehdä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Anna nyt minun mennä katsomaan sitä hyvää maata tuolla puolella Jordania, hyviä vuoria ja Libanonia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mutta Herra vihastui minun päälleni teidän tähtenne, eikä kuullut minun rukoustani; mutta sanoi minulle: sinulla on kyllä, älä minulle siitä asiasta enempää puhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Astu Pisgan kukkulalle, ja nosta silmäs länteen päin, pohjaan päin, lounaan päin ja itään päin, ja katso silmilläs; sillä ei sinun pidä menemän tämän Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Mutta käske Josualle ja vahvista häntä, ja rohkaise häntä; sillä hänen pitää menemän ylitse, tämän kansan edellä, ja pitää heille omistaman perinnöksi sen maan, jonka sinä näet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Ja me olimme siinä laaksossa, joka on BetPeorin kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Ja kuule nyt, Israel, ne säädyt ja oikeudet, jotka minä teille opetan tehdäksenne, että te eläisitte ja tulisitte ja omistaisitte maan jonka Herra teidän isäinne Jumala teille on antava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ei teidän pidä mitään lisäämän siihen sanaan minkä minä teille käsken, eikä pidä myös teidän mitään siitä ottaman pois, kätkeäksenne Herran teidän Jumalanne käskyjä, jotka minä teille käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Teidän silmänne ovat nähneet, mitä Herra tehnyt on BaalPeorille; sillä kaikki, jotka seurasivat BaalPeoria, on Herra sinun Jumalas hukuttanut teidän seastanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Vaan te, jotka riiputte kiinni Herrassa teidän Jumalassanne, te elätte kaikki tänäpänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Katso, minä opetin teille käskyt ja oikeudet, niinkuin Herra minun Jumalani minulle käskenyt on, niin tehdäksenne maalla, johonka te tulette, omistamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Niin pitäkäät siis ja tehkäät ne; sillä tämä on teidän ymmärryksenne ja toimellisuutenne kaikkein kansain edessä, koska he kuulevat nämät käskyt, niin he sanovat: tämä suuri kansa ainoastaan on toimellinen ja kuuluisa kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Sillä mikä kansa on niin suuri, jota Jumala niin lähestyy, niinkuin Herra meidän Jumalamme, niin usein kuin me häntä rukoilemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Ja mikä on niin ylistettävä kansa jolla niin hurskaat säädyt ja käskyt ovat, niinkuin kaikki tämä laki on, jonka minä teille tänäpänä annan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Niin karta ja varjele sinun sielus sangen visusti, ettet sinä unhottaisi niitä asioita, jotka sinun silmäs ovat nähneet, ja ettei ne läksisi sinun sydämestäs kaikkena sinun elinaikanas: ja sinun pitää niitä julistaman lapsilles ja lastes lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Sitä päivää, jonas seisoit Herran sinun Jumalas edessä Horebissa, kuin Herra sanoi minulle: kokoa minulle kansa, antaakseni heidän kuulla minun sanojani, jotka heidän pitää oppiman, että he pelkäisivät minua kaikkena elinaikanansa maan päällä, ja opettaisivat lapsiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Ja te astuitte edes, ja seisoitte alhaalla vuoren tykönä, ja vuori paloi taivaasen asti, ja siellä oli pimeys, pilvi ja synkeys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Ja Herra puhui teille keskeltä tulta: puheen äänen te kuulitte, mutta ette yhtäkään kuvaa nähneet, vaan äänen kuulitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Ja hän ilmoitti teille liittonsa, jonka hän teidän tehdä käski: ne kymmenet sanat, ja kirjoitti ne kahteen kiviseen tauluun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Ja Herra käski minun silloin opettaa teille säädyt ja oikeudet, teidän niitä tehdäksenne siinä maassa, johon te menette omistamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Varjelkaat siis sielujanne sangen visusti; sillä ette ole yhtäkään kuvaa nähneet sinä päivänä, jona Herra puhui teille, keskeltä tulta, Horebissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Ettette turmelisi teitänne, ja tekisi teillenne kuvaa, jonkun muotoista, miehen eli vaimon kaltaista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Jonkun eläimen kaltaista, joka on maan päällä, jonkun linnun kaltaista, joka lentää taivaan alla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Eli jonkun madon muotoa maan päällä, eli jonkun kalan muotoa, joka on vedessä maan alla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Ja ettet sinä myös nostaisi silmiäs taivaasen päin, ja katselisi aurinkoa, ja kuuta, ja tähtiä, ja kaikkea taivaan sotajoukkoa, ja tulisi kehoitetuksi kumartamaan ja palvelemaan heitä, jotka Herra sinun Jumalas jakanut on kaikille kansoille koko taivaan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Mutta teidät on Herra ottanut ja johdattanut ulos rautapätsistä Egyptistä, että olisitte hänelle perintökansa, niinkuin se myös on tänäpänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Ja Herra vihastui minun päälleni teidän puheenne tähden, niin että hän vannoi, ettei minun pitänyt menemän Jordanin ylitse, eli tuleman siihen hyvään maahan, jonka Herra sinun Jumalas antaa sinulle perinnöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Vaan minun pitää kuoleman tässä maassa, ja ei minun pidä käymän Jordanin ylitse; mutta te käytte sen ylitse ja omistatte hyvän maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Niin kavahtakaat, ettette Herran teidän Jumalanne liittoa unhottaisi, jonka hän teidän kansanne on tehnyt: ja älkäät tehkö kuvaa jonkun muotoista niinkuin Herra sinun Jumalas sinulta kieltänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Sillä Herra sinun Jumalas on kuluttavainen tuli, ja kiivas Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Kuin sinä siität lapsia, ja lasten lapsia, ja te vanhenette maassa ja turmelette itsenne, ja teette itsellenne kuvia jonkun muotoisia, niin että te teette pahaa Herran teidän Jumalanne edessä, ja vihoitatte hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Niin minä tänäpänä kutsun taivaat ja maan todistajaksi teitä vastaan, että teidän pitää äkisti peräti hukkuman siitä maasta, johon te menette Jordanin ylitse, omistamaan sitä. Ei teidän pidä kauvan elämän siinä, vaan te pitää peräti hukutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Ja Herra hajoittaa teitä kansain sekaan, ja te tulette vähäksi kansaksi, jätetyksi pakanain sekaan, kuhunka Herra vie teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Siellä pitää teidän palveleman epäjumalia, jotka ihmisten käsialat ovat: puita ja kiviä, jotka ei näe, eikä kuule, eikä syö, eikä haista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Jos sinä silloin siellä etsit Herraa sinun Jumalaas, niin sinä löydät hänen, koska sinä etsit häntä kaikesta sydämestäs, ja kaikesta sielustas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Koskas ahdistetaan, ja nämät kaikki sinun päälles tulevat, niin sinä viimeisinä päivinä palajat Herran sinun Jumalas tykö ja kuulet hänen ääntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Sillä Herra sinun Jumalas on armollinen Jumala: ei hän sinua hylkää, eikä kadota sinua, ja ei hän unhota sinun isäis liittoa, jonka hän heille vannonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Kysele entisiä aikoja, jotka ovat olleet sinun edelläs, siitä päivästä, jona Jumala loi ihmisen maan päälle, ja yhdestä taivaan äärestä niin toiseen ääreen: jos ikänä niin suuri asia tapahtunut on, eli senkaltaista on ikänä kuultu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Onko joku kansa kuullut Jumalan äänen puhuvan tulen keskeltä, niinkuin sinä kuullut olet, ja on elänyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Eli onko Jumala koetellut mennäksensä ottamaan itsellensä kansaa kansan seasta, kiusauksilla, ja tunnustähdeillä, ja ihmeillä, ja sodalla, ja väkevällä kädellä, ja ojetulla käsivarrella ja suurilla peljästyksillä, niinkuin Herra teidän Jumalanne kaikki nämät tehnyt on teille Egyptistä sinun silmäis edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Nämät olet sinä nähnyt, tietääkses, että Herra on ainoastaan Jumala; ja paitsi häntä ei yksikään muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Taivaasta on hän antanut sinun kuulla äänensä, opettaaksensa sinua, ja maalla on hän antanut sinun nähdä suuren tulensa, ja tulen keskeltä olet sinä kuullut hänen sanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Että hän sinun isiäs on rakastanut, ja heidän siemenensä on valinnut heidän jälkeensä, ja vienyt ulos sinun Egyptin maasta kasvoillansa, ja suurela voimallansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Ajamaan ulos sinun edestäs suuret kansat, väkevämmät sinua, johdattaaksensa sinun siihen, ja antaaksensa sinulle heidän maansa perinnöksi, niinkuin se tänäpänä tapahtunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Niin tiedä siis tänäpänä, ja pane mielees, että Herra on Jumala ylhäällä taivaassa, ja alhaalla maassa, ja ei yksikään muu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Ettäs pidät hänen säätynsä ja käskynsä, jotka minä tänäpänä sinulle käsken, että sinun ja sinun lapsilles sinun jälkees hyvin kävis, ja ettäs olisit pitkä-ijällinen maassa, jonka Herra sinun Jumalas sinulle antaa ikäpäivikses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Silloin eroitti Moses kolme kaupunkia, sillä puolella Jordania auringon nousemisen puoleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Että sinne pakenis, tietämätä lähimmäisensä kuoliaaksi löis ja ei ennen ole ollut hänen vihamiehensä; että hän pakenis yhteen niistä kaupungeista, ja eläis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Kuin oli Betser korvessa, lakialla maalla Rubenilaisten seassa, ja Ramot Gileadissa Gadilaisten seassa, ja Goan Basanissa Manasselaisten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Tämä on se laki, jonka Moses Israelin lasten eteen pani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Ja nämät ovat todistukset, säädyt ja oikeudet, jotka Moses sanoi Israelin lapsille, lähdettyänsä Egyptistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Sillä puolella Jordania, laaksossa BetPeorin kohdalla, Sihorin Amorilaisten kuninkaan maalla joka Hesbonissa asui, jonka Moses ja Israelin lapset löivät lähdettyänsä Egyptistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Ja omistivat hänen maansa, niin myös Ogin Basanin kuninkaan maan, kahden Amorilaisten kuninkaan, jotka sillä puolella Jordania asuivat, auringon ylenemistä päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Aroerista Arnonin ojan reunalla, Sionin vuoreen asti, se on Hermon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'Ja kaiken lakian maan sillä puolella Jordania itään päin, lakeuden mereen asti, Pisgan vuoren alaisella puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Ja Moses kutsui koko Israelin, ja sanoi heille: kuule Israel näitä säätyjä ja oikeuksia, jotka minä tänäpänä puhun teidän korvainne kuullen, ja oppikaat ne, ja pitäkäät ne, tehdäksenne niiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Herra meidän Jumalamme teki liiton meidän kanssamme Horebissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ei tehnyt Herra tätä liittoa meidän isäimme kanssa, vaan meidän kanssamme, jotka nyt tässä olemme tänäpänä, ja kaikki elämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Herra puhui kasvoista kasvoihin teidän kanssanne vuorella, tulen keskeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Silloin minä seisoin Herran ja teidän vaiheellanne, ilmoittamassa teille Herran sanaa; sillä te pelkäsitte tulta, ja ette nousseet vuorelle, ja hän sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Minä (olen) Herra sinun Jumalas, joka sinun Egyptin maalta orjuuden huoneesta ulos vienyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Ei sinun pidä pitämän muita Jumalia minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Ei sinun pidä kuvaa tekemän sinulles jonkun muotoiseksi, joka ylhäällä taivaassa on, eli alhaalla maassa, elikkä vesissä maan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Ei sinun pidä niitä kumartaman, eikä palveleman niitä; sillä minä olen Herra sinun Jumalas, kiivas Jumala, joka kostan lapsille isäin rikokset, kolmanteen ja neljänteen polveen niille, jotka minua vihaavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'Ja teen laupiuden monelle tuhannelle, jotka minua rakastavat, ja minun käskyni pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Ei sinun pidä turhaan lausuman Herran sinun Jumalas nimeä; sillä ei Herra pidä sitä rankaisemata, joka hänen nimensä turhaan lausuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Sinun pitää lepopäivän pitämän, ettäs sen pyhittäisit, niinkuin Herra sinun Jumalas sinun käski:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Kuusi päivää pitää sinun työtä tekemän, ja kaikki sinun asias toimittaman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Mutta seitsemäs päivä on Herran sinun Jumalas lepopäivä: silloin ei sinun pidä mitään työtä tekemän, eikä sinun poikas, eikä sinun tyttäres, eikä sinun palvelias, eikä sinun piikas, eikä sinun härkäs, eikä aasis, eikä yksikään sinun karjas, eikä sinun muukalaises, joka sinun portteis sisällä on, että sinun palvelias ja piikas levossa olisivat niinkuin sinäkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Ja muista, että sinäkin olit orja Egyptin maalla, ja Herra sinun Jumalas johdatti sinun sieltä väkevällä kädellä ja ojennetulla käsivarrella. Sentähden Herra sinun Jumalas käski sinun pitää lepopäivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Sinun pitää kunnioittaman isääs ja äitiäs, niinkuin Herra sinun Jumalas on sinun käskenyt, ettäs kauvan eläisit, ja menestyisit siinä maassa, jonka Herra sinun Jumalas sinulle antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Ei sinun pidä tappaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Ei sinun pidä huorin tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Ei sinun pidä varastaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Ei sinun pidä väärää todistusta sanoman sinun lähimmäistäs vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Ei sinun pidä himoitseman sinun lähimmäises emäntää. Ei sinun pidä himoitseman sinun lähimmäises huonetta, hänen peltoansa, palveliaansa, piikaansa, härkäänsä, aasiansa, ja mitä ikänä sinun lähimmäises on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Nämät ovat ne sanat, jotka Herra puhui kaikelle teidän seurakunnallenne vuorella, tulesta, pilvestä ja synkeydestä suurella äänellä, ja ei siihen enempää lisännyt, ja kirjoitti ne kahteen kiviseen tauluun, ja antoi ne minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Ja tapahtui, kuin te äänen kuulitte pimeyden keskeltä, ja vuori paloi tulesta, niin te tulitte minun tyköni, kaikki päämiehet ja vanhimmat teidän suvustanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Ja te sanoitte: katso, Herra meidän Jumalamme on osottanut meille kunniansa ja suuruutensa, ja me kuulimme hänen äänensä tulesta. Tänäpänä me näimme Jumalan puhuvan ihmisille, ja heidän elämään jäävän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Ja miksi meidän nyt pitää kuoleman, että tämä suuri tuli pitää kuluttaman meidät? Jos me useammin kuulemme Herran meidän Jumalamme äänen, niin me kuolemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Sillä mikä on kaikki liha, että se kuulis elävän Jumalan äänen tulesta puhuvan, niinkuin me, ja jäis elämään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Lähesty sinä ja kuule kaikki, mitä Herra meidän Jumalamme sanoo, ja sano sinä meille kaikki, mitä Herra meidän Jumalamme sinun kanssas puhuu, niin me tahdomme kuulla ja tehdä niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Ja Herra kuuli teidän sanainne äänen, kuin te puhuitte minun kanssani, ja Herra sanoi minulle: minä kuulin tämän kansan puheen äänen, kuin he puhuivat sinun kanssas: se on kaikki hyvä, minkä he puhuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Joska heille olis senkaltainen sydän, pelkäämään minua ja kätkemään kaikki minun käskyni kaikkena heidän elinaikanansa, että heille menestyis ja heidän lapsillensa ijankaikkisesti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Mene siis ja sano heille: palatkaat kotianne teidän majoihinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Mutta sinun pitää seisoman tässä minun edessäni, että minä puhun sinun kanssas kaikki käskyt, säädyt ja oikeudet, jotka sinun pitää heille opettaman, että he tekisivät niiden jälkeen, siinä maassa, jonka minä heille annan heidän omistaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Niin pitäkäät nämät ja tehkäät niinkuin Herra teidän Jumalanne teidän käski, ja älkäät poiketko oikialle eikä vasemmalle puolelle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Vaan vaeltakaat kaikkia niitä teitä, jotka Herra teidän Jumalanne teille käski, että eläisitte, menestyisitte ja olisitte pitkä-ijälliset siinä maassa, jonka te omistatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Nämät ovat ne käskyt, säädyt ja oikeudet, jotka Herra teidän Jumalanne käski opettaa teille tehdäksenne siinä maassa, kuhunka te menette omistamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Ettäs pelkäisit Herraa sinun Jumalaas, ja pitäisit kaikki hänen säätynsä ja käskynsä, jotka minä käsken sinulle, sinä ja sinun lapses ja sinun lastes lapset, kaikkena sinun elinaikanas, ettäs kauvan eläisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Israel, sinun pitää kuuleman ja pitämän, niin että sinä myös teet sen jälkeen, että sinulle hyvin kävis, ja te tulisitte paljon lisätyksi; niinkuin Herra sinun isäis Jumala sinulle on luvannut maan, joka rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Kuule Israel, Herra meidän Jumalamme on yksi (ainoa) Herra,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Ja sinun pitää rakastaman Herraa sinun Jumalaas, kaikesta sydämestäs, ja kaikesta sielustas ja kaikesta voimastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Ja nämät sanat, jotka minä käsken sinulle tänäpänä, pitää sinun paneman sydämees,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Ja teroittaman ne sinun lapsilles, ja niistä puhuman, huoneessa istuissas ja tiellä käydessäs, maata pannessas ja noustessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Ja sinun pitää sitoman ne merkiksi kätees, ja ne pitää oleman sinulle muistoksi sinun silmäis edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Ja sinun pitää kirjoittaman ne huonees pihtipieliin ja portteihis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Kuin Herra sinun Jumalas johdattaa sinun sille maalle, jonka hän sinun isilles, Abrahamille, Isaakille ja Jakobille on vannonut sinulle antaaksensa, suuret ja jalot kaupungit, joita et sinä rakentanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Ja huoneet täynnä kaikkea hyvyyttä, joita et sinä itse täyttänyt, ja vuojonkiviset kaivot, joita et sinä itse kaivanut, ja viinamäet ja öljymäet, joita et sinä itse istuttanut, että sinä syöt ja ravitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Niin ota vaari, ettet sinä unhota Herraa, joka sinun Egyptin maalta, orjuuden huoneesta on johdattanut ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Mutta sinun pitää pelkäämän Herraa sinun Jumalaas ja palveleman häntä, ja hänen nimensä kautta pitää sinun vannoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ei teidän pidä seuraaman muukalaisia jumalia, niiden kansain jumalia, jotka teidän ympärillänne ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Sillä Herra sinun Jumalas on kiivas Jumala teidän keskellänne, ettei Herran sinun Jumalas viha julmistuisi sinun päälles, ja hukuttaisi sinua maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ei teidän pidä kiusaaman Herraa teidän Jumalaanne, niinkuin te häntä kiusasitte Massassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Mutta pitämän uskollisesti Herran teidän Jumalanne käskyt, niin myös hänen todistuksensa ja hänen säätynsä, jotka hän sinulle käskenyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Ettäs teet sitä mikä oikia ja hyvä on Herran edessä, että sinulle hyvin kävis, ja tulisit sisälle ja omistaisit sen hyvän maan, josta Herra vannoi sinun isilles,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Että hän karkottais kaikki viholliset sinun edestäs, niinkuin Herra sanonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Kuin poikas tästälähin kysyy sinulta, sanoen: mitkä todistukset ja säädyt ja oikeudet nämät ovat, jotka Herra meidän Jumalamme teille käskenyt on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Niin sinun pitää sanoman pojalles: me olimme Pharaon orjat Egyptissä; mutta Herra johdatti meidät ulos Egyptistä väkevällä kädellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Ja Herra teki suuria ja pahoja tunnustähtejä, ja ilmeitä Egyptille, Pharaolle, ja kaikelle hänen huoneellensa, meidän silmäimme edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Ja johdatti meidät sieltä, että hän veis meitä, ja antais meille sen maan, josta hän vannoi meidän isillemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Ja Herra käski meitä tekemään kaikkein näiden säätyin jälkeen, peljäten Herraa meidän Jumalaamme, että meille hyvin kävis kaikkena meidän elinaikanamme, niinkuin myös tänäpänä käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Ja sen pitää oleman meille vanhurskaudeksi, jos me pidämme ja teemme kaikki nämät käskyt Herran meidän Jumalamme edessä, niinkuin hän meille on käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Kuin Herra sinun Jumalas vie sinun siihen maahan, johon sinä tulet omistamaan sitä, ja ajaa paljon kansaa ulos sinun edestäs: Hetiläiset, Girgasilaiset, Amorilaiset, Kanaanilaiset, Pheresiläiset, Heviläisetja Jebusilaiset, seitsemän kansaa, jotka sinua suuremmat ja väkevämmät ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Ja kuin Herra sinun Jumalas antaa heidät sinun etees, ja sinä lyöt heitä, niin sinun pitää peräti hukuttaman heitä, niinkuin kirotuita, ja ei tekemän yhtäkään liittoa heidän kanssansa, eikä armahtaman heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Ja ei sinun pidä heimolaisuuteen antaman sinuas heidän kanssansa: sinun tyttäriäs ei sinun pidä antaman heidän pojillensa, ja heidän tyttäriänsä ei pidä sinun ottaman pojilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Sillä he viettelevät sinun poikas minun tyköäni, palvelemaan muukalaisia jumalia; niin julmistuu Herran viha teidän päällenne ja nopiasti hukuttaa teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Mutta näin pitää teidän tekemän heille: heidän alttarinsa pitää teidän kukistaman ja heidän patsaansa rikkoman, niin myös heidän metsistönsä hakkaaman, ja heidän epäjumalansa kuvat tulella polttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Sillä sinä olet pyhä kansa Herralle sinun Jumalalles: sinun on Herra sinun Jumalas valinnut omaksi kansaksensa kaikista kansoista, jotka asuvat maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ei ole Herra mielistynyt teihin ja valinnut teitä sentähden, että teidän lukunne on suurempi kuin kaikkein muiden kansain; sillä sinä olet vähin kaikista kansoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Mutta että Herra rakasti teitä ja pitää valansa, jonka hän vannoi teidän isillenne, johdatti hän teidät ulos väkevällä kädellä ja vapahti teidät orjuuden huoneesta, Pharaon Egyptin kuninkaan kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Niin sinun pitää tietämän, että Herra sinun Jumalas on Jumala, uskollinen Jumala, pitäväinen liiton ja laupiuden niiden kanssa, jotka häntä rakastavat ja pitävät hänen käskynsä, tuhanteen polveen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Ja kostaa niille, jotka häntä vihaavat, kasvoinsa edessä, niin että hän hukuttaa heitä, ja ei viivy kostamasta niille kasvoinsa edessä, jotka häntä vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Niin pidä ne käskyt, säädyt ja oikeudet, jotka minä sinulle käsken tänäpänä tehdäkses niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Ja kuin te nämät oikeudet kuulette, ja pidätte, ja teette ne, niin myös Herra sinun Jumalas pitää sinulle sen liiton ja laupiuden, jonka hän vannoi sinun isilles,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Ja rakastaa sinua, ja siunaa sinun, ja enentää sinun, ja siunaa sinun ruumiis hedelmän, ja sinun maas hedelmän, sinun jyväs, viinas ja öljys, sikiät karjastas, ja laumat lampaistas, siinä maassa, jonka hän sinun isilles vannoi sinulle antaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Sinun pitää oleman siunatun kaikista kansoista. Ei yksikään hedelmätöin pidä sinun seassas oleman, eikä karjas seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Ja Herra ottaa sinulta pois kaikki sairaudet: ei hän yhtäkään Egyptin pahaa tautia, jotka sinä tiedät, pane sinun päälles; mutta heittää ne kaikkein niiden päälle, jotka sinua vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Sinun pitää nielemän kaikki ne kansat, jotka Herra sinun Jumalas sinulle antava on: ei sinun silmäs pidä säästämän heitä, eikä sinun pidä palveleman heidän jumaliansa; sillä se tulis sinulle paulaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Jos sinä sanot sydämessäs: nämät kansat ovat usiammat kuin minä; kuinka taidan minä heidät ajaa ulos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Niin älä pelkää heitä: muista visusti, mitä Herra sinun Jumalas teki Pharaolle ja kaikille Egyptiläisille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Ja ne suuret kiusaukset, jotka silmät nähneet ovat, ja tunnustähdet ja ihmeet, ja väkevä käsi, ja ojettu käsivarsi, jolla Herra sinun Jumalas johdatti sinun. Niin Herra sinun Jumalas tekee kaikille niille kansoille, joita sinä pelkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Niin myös Herra sinun Jumalas lähettää heidän sekaansa hörhöläiset siihen asti että kaikki hukutetaan, jotka jääneet ja heitänsä lymyttäneet ovat sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Älä hämmästy heidän edessänsä; sillä Herra sinun Jumalas on sinun keskelläs, suuri ja peljättävä Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Ja Herra sinun Jumalas karkottaa nämät kansat sinun edestäs, vähitellen toisen toisensa jälkeen: et sinä saa äkisti hukuttaa heitä, ettei metsän pedot lisääntyisi sinua vastaan maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Ja Herra sinun Jumalas antaa heitä sinun etees, ja häiritsee heitä suurella sekaseuraisuudella, siihenasti että hän hukuttaa heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Ja antaa heidän kuninkaansa sinun käsiis, ja sinun pitää hukuttaman heidän nimensä taivaan alta: ei pidä yhdenkään seisoman sinua vastaan siihenasti ettäs heidät hukutat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Heidän epäjumalainsa kuvat pitää sinun tulella polttaman: ei sinun pidä himoitseman sitä hopiaa ja kultaa, joka niiden päällä on ollut, taikka ottaman siitä jotain sinulles, ettei se olisi sinulle paulaksi; sillä se on Herralle sinun Jumalalles kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Sentähden ei sinun pidä sitä kauhistusta huoneeses viemän, ettei tulisi kirotuksi niinkuin se, mutta sinun pitää ilvoituksella ilvoittaman ja kauhistuksella kauhistuman sitä; sillä se on kirottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Kaikki käskyt, jotka minä käsken sinulle tänäpänä, pitäkäät ja tehkäät, että eläisitte ja lisääntyisitte, tulisitte ja omistaisitte maan, josta Herra vannoi teidän isillenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Ja muista kaikkea sitä matkaa, jonka kautta Herra sinun Jumalas johdatti sinun näinä neljänäkymmenenä vuotena korvessa, vaivataksensa sinua ja koetellaksensa sinua, tietääksensä mitä sinun sydämessäs oli, pitäisitkö hänen käskynsä, vai etkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Ja hän vaivasi sinua ja antoi sinun isota, ja ravitsi sinun mannalla, jota et sinä eikä sinun isäs tunteneet, antaaksensa sinun tietää, ettei ihminen elä ainoastansa leivästä; vaan kaikesta mikä Herran suusta lähtee, elää ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Ei sinun vaattees vanhuudesta kuluneet yltäs ja sinun jalkas ei kuulettuneet, näinä neljänäkymmenenä vuotena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Niin tiedä sydämessäs, että Herra sinun Jumalas on kurittanut sinua, niinkuin mies kurittaa poikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Ja pidä Herran sinun Jumalas käskyt vaeltaakses hänen tiellänsä ja peljätäkses häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Sillä Herra sinun Jumalas vie sinun hyvälle maalle: sille maalle, jossa vesiojat, lähteet ja järvet ovat, jotka laaksoihin ja vuorten sivuille vuotavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Maalle, jossa nisu, ohra, viinapuut, fikunapuut ja granatin omenat ovat; maalle, jossa on öljypuita ja hunajaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Maalle, jossa ei sinun pidä vajavaisuudessa syömän leipää jossa ei mitään puutu; maalle, jonka kivet ovat rautaa, jossa sinä myös vasken vuorista lohkaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Ja koska sinä syönyt ja ravittu olet, ettäs silloin kiität Herraa sinun Jumalaas hyvän maan edestä, jonka hän antoi sinulle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Niin ota siis vaari, ettet unhota Herraa sinun Jumalaas siinä, ettet sinä pidä hänen käskyjänsä, oikeuksiansa ja säätyjänsä, jotka minä tänäpänä sinulle käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Koskas syönyt ja ravittu olet, ja rakennat kauniit huoneet ja asut niissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Ja sinun karjas ja lampaas, hopias ja kultas, ja kaikki mitä sinulla on, lisääntyvät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Ettei sinun sydämes silloin tulisi ylpiäksi, ja unhottaisit Herran sinun Jumalas, joka sinun johdatti Egyptin maalta, orjuuden huoneesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Ja on sinun johdattanut suuren ja hirmuisen korven lävitse, jossa tuliset kärmeet, ja skorpionit, ja kuivuus oli, ja ei ensinkään vettä ollut, ja hän antoi veden vuotaa sinulle kovasta kalliosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Ja ravitsi sinun mannalla korvessa, josta ei sinun isäs tietäneet, vaivataksensa ja koetellaksensa sinua, ja viimeiseltä hyvää tehdäksensä sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Muutoin sinä sanoisit sydämessäs: minun voimani ja käteni väkevyys on minulle näin voimalliset työt tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Vaan muista Herraa Jumalaas; sillä hän on se, joka sinulle voiman antaa, tekemään senkaltaisia voimallisia tekoja, että hän vahvistais liittonsa, jonka hän vannoi sinun isilles, niinkuin se tänäkin päivänä tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Mutta jos sinä niin unhotat Herran sinun Jumalas, ja noudatat muita jumalia, palvelet ja kumarrat niitä, niin minä tänäpänä todistan teille, että teidän pitää peräti hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Juuri niinkuin pakanat, jotka Herra hukuttaa teidän edestänne, niin teidän pitää hukkuman, ettette ole Herran teidän Jumalanne äänelle kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Kuule Israel: tänäpänä sinä menet Jordanin yli, ettäs tulet omistamaan sitä kansaa, joka on sinua suurempi ja väkevämpi, suuria kaupungeita rakennetuita taivaaseen asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Suurta ja pitkää kansaa, Enakin poikia, jotka sinä tunnet, joista sinä myös kuullut olet sanottavan: kuka voi seisoa Enakin poikia vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Niin sinun pitää tänäpänä tietämän, että Herra sinun Jumalas käy sinun edelläs niinkuin kuluttavainen tuli; hän hukuttaa heitä, ja hän alentaa heitä sinun edessäs, ettäs ajat heitä ulos ja hukutat nopiasti, niinkuin Herra sanoi sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Kuin Herra sinun Jumalas on heidät ajanut sinun edestäs ulos, niin älä sano sydämessäs: Herra on minun tähän tuonut omistamaan tätä maata minun vanhurskauteni tähden; sillä Herra ajaa nämät pakanat sinun edestäs ulos heidän jumalattomuutensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Et sinä tule omistamaan heidän maatansa vanhurskautes eli sydämes vakuuden tähden; vaan Herra sinun Jumalas ajaa pakanat ulos heidän jumalattomuutensa tähden, että Herra vahvistais sanansa, jonka Herra sinun isilles Abrahamille, Isaakille ja Jakobille vannoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Niin tiedä nyt, ettei Herra sinun Jumalas anna sinulle tätä hyvää maata, omistaakses sitä sinun vanhurskautes tähden; sillä sinä olet niskurikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Muista ja älä unhota, kuinka sinä Herran sinun Jumalas vihoitit korvessa: siitä päivästä kuin sinä läksit Egyptin maalta, siihenasti kuin te tulleet olette tähän paikkaan, olette te olleet Herralle vastahakoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Sillä Horebissa te vihoititte Herran, ja Herra vihastui teille, niin että hän tahtoi teidät hukuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Kuin minä vuorelle astuin ottamaan kivisiä tauluja vastaan, liiton tauluja, jonka Herra teki teidän kanssanne, ja minä olin vuorella neljäkymmentä päivää ja neljäkymmentä yötä, ja en syönyt leipää, enkä juonut vettä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Ja Herra antoi minulle kaksi kivistä taulua, kirjoitettu Jumalan sormella, ja niissä olivat kaikki sanat, jotka Herra teille tulesta vuorella puhui, kokouksen päivänä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Ja tapahtui neljänkymmenen päivän ja neljänkymmenen yön perästä, että Herra antoi minulle kaksi kivistä liiton taulua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Ja Herra sanoi minulle: nouse ja mene nopiasti täältä alas; sillä sinun kansas, jonkas Egyptistä olet johdattanut ulos, on turmellut itsensä, he ovat pikaisesti tieltä menneet pois, jonka minä käskin heille, ja ovat tehneet heillensä valetun kuvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Ja Herra puhui minulle, sanoen: minä näin tämän kansan, ja katso, se on niskurikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Salli, että minä hukutan heidät, ja pyyhin heidän nimensä taivaan alta: ja minä tahdon sinun tehdä väkevämmäksi ja suuremmaksi kansaksi kuin tämä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Ja kuin minä käännyin ja astuin vuorelta alas, joka tulesta paloi, ja pidin kaksi liiton taulua molemmissa käsissäni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Niin näin minä, ja katso, te olitte tehneet syntiä Herraa teidän Jumalaanne vastaan: te olitte tehneet teille valetun vasikan, ja nopiasti menitte pois siltä tieltä, jonka Herra käski teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Niin otin minä ne molemmat taulut ja heitin molemmista käsistäni, ja löin ne rikki teidän silmäinne edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Ja lankesin maahan Herran eteen, Niinkuin ennenkin, niinä neljänäkymmenenä päivänä ja neljänäkymmenenä yönä, ja en syönyt leipää, enkä juonut vettä, kaikkein teidän synteinne tähden, jotka te tehneet olitte, että te teitte pahaa Herran edessä ja vihoititte hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Sillä minä pelkäsin sitä vihaa ja hirmuisuutta, jolla Herra teidän päällenne vihastunut oli, niin että hän tahtoi hukuttaa teidät: ja Herra kuuli minun rukoukseni vielä silläkin erällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Herra oli myös suuresti vihainen Aaronin päälle, niin että hän tahtoi hänen hukuttaa; vaan minä rukoilin silloin Aaroninkin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Mutta teidän syntinne, vasikan, jonka te tehneet olitte, otin minä ja poltin tulessa, ja löin sen rikki ja survoin hyvästi, siihenasti että se mureni tomuksi, ja heitin tomun ojaan, joka siitä vuoresta vuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Niin myös Tabeerassa, ja Massassa, ja Himohaudoillas te vihoititte Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Ja kuin Herra lähetti teidät KadesBarneasta, ja sanoi: menkäät ja omistakaat maa, jonka minä annoin teille, niin te olitte Herran teidän Jumalanne suulle vastahakoiset, ja ette uskoneet häntä, ette myös olleet kuuliaiset hänen äänellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Te olette olleet Herralle tottelemattomat, siitä päivästä kuin minä teidän tuntenut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Niin minä lankesin maahan Herran eteen, neljäkymmentä päivää ja neljäkymmentä yötä, kuin minä siinä makasin; sillä Herra sanoi, että hän tahtoi hukuttaa teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Ja minä rukoilin Herraa, sanoen: Herra, Herra, älä hukuta kansaas ja perikuntaas, jonka suurella voimallas pelastanut ja väkevällä kädelläs Egyptistä olet johdattanut ulos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Muista palvelioitas Abrahamia, Isaakia ja Jakobia: älä katso tämän kansan kovuutta, jumalattomuutta ja syntiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Ettei sen maan asuvaiset, jostas meidät johdattanut olet, sanoisi: sentähden, ettei Herra voinut heitä viedä siihen maahan, jonka hän heille luvannut oli, ja että hän on vihannut heitä, johdatti hän heidät ulos, tappaaksensa heitä korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Sillä he ovat sinun kansas ja perimykses, jonka suurella voimallas ja ojennetulla käsivarrellas johdattanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Silloin sanoi Herra minulle: vuole sinulles kaksi kivistä taulua entisten kaltaista, ja astu minun tyköni vuorelle, ja tee sinulles puuarkki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Niin minä kirjoitan niihin tauluihin ne sanat, jotka ensimäisissä tauluissa olivat, jotka särkenyt olet: ja pane ne arkkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Niin minä tein arkin sittimipuusta, ja vuolin kaksi kivistä taulua entisten kaltaista, ja astuin vuorelle, pitäen kaksi taulua kädessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Niin hän kirjoitti ensimäisen kirjoituksen jälkeen, niihin tauluihin ne kymmenet sanat, jotka Herra teille puhui vuorella tulesta, kokouksen päivänä: ja Herra antoi ne minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Niin minä käännyin ja astuin vuorelta alas, ja panin taulut arkkiin, jonka minä tein, että heidän piti siellä oleman, niinkuin Herra minulle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Ja Israelin lapset menivät BerotBeneJaakanista Moseraan: siellä kuoli Aaron ja haudattiin, ja hänen poikansa Eleatsar toimitti papin virkaa hänen siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Sieltä menivät he Gudgodaan: Gudgodasta Jodbatiin, siihen maahan, jossa vesi-ojat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Silloin eroitti Herra Levin suvun, kantamaan Herran liitonarkkia, seisomaan Herran edessä, palvelemaan häntä ja kiittämään hänen nimeänsä tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Sentähden ei ollut Leviläisillä yhtään osaa eli perimystä veljeinsä kanssa; sillä Herra on heidän perimyksensä, niinkuin Herra sinun Jumalas sanoi heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Ja minä seisoin vuorella niinkuin ennenkin, neljäkymmentä päivää ja neljäkymmentä yötä, ja vielä silloinkin kuuli Herra minun rukoukseni, eikä Herra tahtonut hukuttaa sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Vaan Herra sanoi minulle: nouse, ja mene matkaas, niin ettäs kansan edellä vaellat, että he tulisivat ja omistaisivat sen maan, jonka minä vannoin heidän isillensä antaakseni heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Nyt siis Israel, mitä Herra sinun Jumalas sinulta muuta anoo; vaan ettäs pelkäisit Herraa sinun Jumalaas, ja vaeltaisit kaikissa hänen teissänsä ja rakastaisit häntä, ja palvelisit Herraa sinun Jumalaas kaikesta sinun sydämestäs ja kaikesta sinun sielustas:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Ettäs myös pitäisit Herran käskyt ja hänen säätynsä, jotka minä käsken sinulle tänäpänä, että sinulle hyvin kävis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Katso, taivaat ja taivasten taivaat ovat Herran sinun Jumalas, ja maa ja kaikki, mitä hänessä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Kuitenkin Herralla on ollut hyvä suosio sinun isäis tykö rakastaaksensa heitä, ja on valinnut heidän siemenensä heidän jälkeensä, nimittäin teidät kaikista kansoista, niinkuin tänäpäivänäkin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Niin ympärileikatkaat teidän sydämenne esinahka, ja älkäät enää niskurit olko!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Sillä Herra teidän Jumalanne on kaikkein jumalain Jumala, voimallinen ja peljättävä, joka ei katso muotoa, eikä lahjoja ota,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Joka orvoille ja leskille oikeuden tekee, ja rakastaa muukalaisia, niin että hän heille leivän ja vaatteen antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Sentähden pitää teidänkin rakastaman muukalaista; sillä te myös olitte muukalaiset Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Sinun pitää pelkäämän Herraa sinun Jumalaas, häntä pitää sinun palveleman, hänessä pitää sinun kiinni riippuman, ja hänen nimensä kautta vannoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Hän on sinun ylistykses ja sinun Jumalas, joka sinulle teki suuria ja hirmuisia töitä, joita silmäs nähneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Sinun isäs menivät alas Egyptiin seitsemänkymmenen sielun kanssa; mutta nyt Herra sinun Jumalas on enentänyt sinun niinkuin taivaan tähdet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Niin rakasta nyt Herraa sinun Jumalaas, ja pidä hänen lakinsa, säätynsä, oikeutensa ja käskynsä alinomaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Ja tuntekaat te tänäpänä; sillä en minä teidän lastenne kanssa puhu, jotka ei tiedä, eikä ole nähneet Herran teidän Jumalanne kuritusta, hänen jalouttansa, voimallista kättänsä ja ojennettua käsivarttansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Ja hänen ihmeitänsä, ja tekojansa jotka hän teki Egyptiläisten seassa, Pharaolle Egyptin kuninkaalle, ja kaikelle hänen maakunnallensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Ja mitä hän teki Egyptiläisten sotaväelle, heidän hevosillensa ja vaunuillensa, kuin hän antoi Punaisen meren vedet juosta heidän päällensä, kuin he teitä ajoivat takaa, ja Herra hukutti heidät hamaan tähän päivään asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Ja mitä hän teille korvessa tehnyt on, siihenasti kuin te tähän paikkaan tulitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Ja mitä hän teki Datanille ja Abiramille Eliabin Rubenin pojan pojille, koska maa avasi suunsa ja nieli heidät, ja heidän perheensä ja majansa; niin myös kaikki heidän tavaransa, joka oli heidän hallussansa koko Israelin keskellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Sillä teidän silmänne ovat nähneet kaikki ne suuret Herran teot, jotka hän tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Sentähden pitäkäät kaikki ne käskyt, jotka minä teille tänäpänä käsken, että te vahvistuisitte tulemaan ja omistamaan sitä maata, jota te menette omistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'Että te kauvan siinä maassa eläisitte, jonka Herra sinun Jumalas vannoi teidän isillenne, heille antaaksensa ja heidän siemenellensä: sen maan, joka rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Sillä se maa, johonkas menet omistamaan sitä, ei ole niinkuin Egyptin maa, josta te lähteneet olette; jossa sinä siemenes kylvit, ja kastoit sen jaloillas niinkuin kaalimaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Vaan se maa, johonka te menette omistamaan sitä, on vuorinen ja laaksoinen maa, jonka sade taivaasta kastaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Josta maasta Herra sinun Jumalas pitää vaarin; ja Herran sinun Jumalas silmät aina näkevät sen, vuoden alusta niin vuoden loppuun asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Ja pitää tapahtuman, jos te hyvin kuuliaiset olette minun käskyilleni, jotka minä tänäpänä teille käsken; niin että te rakastatte Herraa teidän Jumalaanne, ja palvelette häntä kaikesta teidän sydämestänne ja kaikesta sielustanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Että minä annan teidän maallenne sateen ajallansa, varhain ja hiljain; että sinä korjaat jyväs, viinas ja öljys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Ja minä annan sinun karjalles ruohoa sinun kedoillas; että te syötte ja ravitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Varokaat ettei teidän sydämenne vieteltäisi, niin että poikkeette palvelemaan vieraita jumalia ja kumartamaan heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Ja Herran viha julmistuis teidän päällenne, ja sulkis taivaan, ettei sadetta tulisi, ja maa ei antaisi hedelmäänsä: ja te kiiruusti hukkuisitte siitä hyvästä maasta, jonka Herra on teille antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Niin pankaat nyt nämät minun sanani teidän sydämeenne, ja teidän mieleenne, ja sitokaat niitä merkiksi teidän käsiinne, että ne olisivat muistoksi teidän silmäinne edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Ja opettakaat niitä teidän lapsillenne, niin että sinä puhut niistä, huoneessa istuissas, tiellä käydessäs, levätä pannessas ja noustessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Ja kirjoita ne sinun huonees pihtipieliin, ja sinun portteihis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Että sinä ja sinun lapses kauvan eläisitte maan päällä, jonka Herra teidän isillenne vannoi antaaksensa heille, niinkauvan kuin päivät taivaasta maan päällä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Sillä te kaikki nämät käskyt pidätte, jotka minä teille käsken, että te sen jälkeen teette; niin että te rakastatte Herraa teidän Jumalaanne, ja vaellatte kaikissa hänen teissänsä, ja riiputte hänessä kiinni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Niin Herra ajaa kaikki nämät kansat pois teidän kasvoinne edestä; niin että te omistatte suuremmat ja voimallisemmat kansat, kuin te olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Kaikki paikat, mihin teidän jalkanne astuu, pitää teidän oleman: korvesta ja Libanonista ja Phrathin virrasta, äärimäiseen mereen asti, pitää teidän rajanne oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Ei yksikään voi olla teitä vastaan: teidän pelkonne ja vavistuksenne antaa Herra tulla kaikkein niiden maiden päälle, kussa te vaellatte; niinkuin hän teille on sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Katso, minä asetan tänäpänä teidän eteenne, sekä siunauksen että kirouksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Siunauksen, jos te kuuliaiset olette Herran teidän Jumalanne käskylle, jonka minä tänäpänä teille käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Kirouksen, jos ette tottele Herran teidän Jumalanne käskyjä, ja poikkeette siitä tiestä, jonka minä teille tänäpänä käsken; niin että te vaellatte muiden jumalain jälkeen, joita ette tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Koska Herra sinun Jumalas johdattaa sinun siihen maahan, johonkas tulet omistamaan sitä; niin anna siunaus sanottaa Grisimin vuorella, ja kirous Ebalin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Eikö he ole tuolla puolella Jordania tien perällä, auringon laskemiseen päin Kanaanealaisten maalla, jotka asuvat lakeudella, Gilgalin kohdalla, Moren tammiston tykönä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Sillä teidän pitää menemän Jordanin yli, tuleman ja omistaman maan, jonka Herra teidän Jumalanne teille antaa, sen omistaaksenne, ja asuaksenne siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Niin pitäkäät ja tehkäät kaikki ne säädyt ja oikeudet, jotka minä tänäpänä panen teidän eteenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Nämät ovat säädyt ja oikeudet, joita teidän pitämään pitää, että te niiden jälkeen tekisitte, sillä maalla, jonka Herra sinun isäis Jumala antoi sinulle omistaakses; niinkauvan kuin te maan päällä elätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Teidän pitää peräti hävittämän kaikki ne paikat, joissa pakanat, jotka te omistatte, jumaliansa palvelleet ovat; joko se olis korkeilla vuorilla, taikka mäillä, eli kaikkein viheriäisten puiden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Ja kukistakaat heiden alttarinsa, ja särkekäät heidän patsaansa, heidän metsistönsä tulella polttakaat, ja heidän epäjumalansa kuvat rikki hakatkaat; ja hukuttakaat heidän nimensä siitä paikasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Ei teidän pidä niin tekemän Herralle teidän Jumalallenne:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Vaan siinä paikassa, minkä Herra teidän Jumalanne valitsee kaikista teidän sukukunnistanne, asettaaksensa siihen nimensä: siinä missä hän asuu, pitää teidän etsimän häntä ja sinne pitää sinun tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Ja siellä pitää teidän uhraaman polttouhrinne, ja muut uhrinne, ja kymmenyksenne, ja kättenne ylennysuhrin; ja lupauksenne, ja vapaaehtoiset uhrinne, niin myös esikoiset karjastanne ja lampaistanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Ja siellä teidän pitää syömän Herran teidän Jumalanne edessä, ja iloitseman kaikissa, mitä te ja teidän huoneenne kannatte edes, joilla Herra sinun Jumalas sinun on siunannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ei teidän pidä tekemän kaikkein niiden jälkeen, kuin me tässä tänäpänä teemme, jokainen niinkuin hänelle itse näkyis oikiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Sillä ette vielä ole tähänasti tulleet lepoon ja perimykseen, jonka Herra sinun Jumalas sinulle antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Vaan teidän pitää menemän Jordanin yli, ja asuman siinä maassa, jonka Herra teidän Jumalanne antaa teidän periä: ja hän antaa teille levon kaikilta vihamiehiltänne ympäriltänne, teidän pitää myös turvallisesti asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Ja siinä pitää oleman se paikka, jonka Herra sinun Jumalas valitsee, että hänen nimensä siinä asuis; sinne pitää teidän viemän kaikki ne mitkä minä teille käsken: polttouhrinne, ja muut uhrinne, kymmenyksenne, kättenne ylennysuhrin, ja kaikki vapaat lupauksenne, jotka te Herralle lupaatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Ja teidän pitää iloitseman Herran teidän Jumalanne edessä, sekä te että poikanne, ja tyttärenne, palvelijan ja piikanne; ja myös Leviläiset, jotka teidän porteissanne ovat: sillä ei heillä ole osaa eli perimystä teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Karta uhraamasta polttouhrias joka paikassa, minkäs näet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Vaan siinä paikassa, jonka Herra valitsee jossakussa sinun sukukunnassas, siellä pitää sinun polttouhris uhraaman; ja tekemän kaikki, mitä minä sinulle käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Kuitenkin teurasta ja syö lihaa kaiken sinun sielus himon jälkeen, Herran sinun Jumalas siunauksen jälkeen, jonka hän sinulle on antanut, kaikissa sinun porteissas: sekä saastainen että puhdas siitä syökään, niinkuin metsävuohen ja peuran lihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Mutta ei teidän pidä verta syömän; vaan kaataman sen maahan niinkuin veden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Et sinä saa suinkaan syödä porteissas jyväis, viinas, ja öljys kymmenyksiä, eikä myös esikoisia karjastas ja lampaistas; taikka yhtäkään lupausuhria, jonka sinä luvannut olet, taikka sinun vapaan ehtos uhria, eli kättes ylennysuhria;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Vaan Herran sinun Jumalas edessä, pitää sinun niitä syömän siinä paikassa, jonka Herra sinun Jumalas valitsee, sinä ja poikas, ja tyttäres, ja palvelias ja piikas, ja Leviläinen joka sinun porteissas on, ja iloitse Herran sinun Jumalas edessä kaikissa, mitä sinun kätes suo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Ja ota vaari, ettes hyljää Leviläistä, niin kauvan kuin sinä elät maan päällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Kuin Herra sinun Jumalas, levittää sinun maas rajat, niinkuin hän sanoi sinulle, ja sinä sanot: minä syön lihaa: että sinun sielus himoitsee lihaa syödä; niin syö lihaa kaiken sinun sielus himon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Jos se sia sinusta kaukana on, jonka Herra sinun Jumalas valitsi, että hän siellä antaa nimensä asua, niin teurasta karjastas ja lampaistas, jotka Herra sinulle antanut on, niinkuin minä sinulle käskin, ja syö porteissas kaiken sinun sielus himon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Kaiketikin niinkuin metsävuohi ja peura syödään, niin pitää sinun sen syömän: sekä saastainen että puhdas siitä syökään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Vaan ainoasti kavahda, ettes verta syö; sillä veri on henki, sentähden ei sinun pidä syömän henkeä lihan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Ei sinun pidä sitä syömän, mutta kaataman maahan niinkuin veden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Ei pidä sinun syömän sitä, ettäs menestyisit, ja sinun lapses sinun jälkees, ettäs oikein tehnyt olet Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Mutta jos sinä pyhität jotain joka sinun omas on, taikka teet lupauksen, niin sinun pitää sen viemän, ja sinun pitää tuleman siihen siaan, jonka Herra valinnut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Ja tee siellä lihasta ja verestä polttouhris, Herran sinun Jumalas alttarilla; mutta uhris veri kaada Herran sinun Jumalas alttarille, ja syö liha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Ota vaari, ja kuule kaikki nämät sanat, jotka minä käsken sinulle, ettäs menestyisit, ja sinun lapses sinun jälkees ijankaikkisesti, ettäs olet oikein ja kelvollisesti Herran sinun Jumalas edessä tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Kuin Herra sinun Jumalas hävittää pakanat edestäs, kuhunka sinä tulet heitä omistamaan, ja olet heitä omistanut ja asut heidän maallansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Niin ota vaari, ettes heidän perässänsä paulaan lankee, sittekuin he ovat hukutetut sinun edestäs, ja ettes etsisi heidän jumaliansa, sanoen: niinkuin tämäkin kansa on palvellut epäjumaliansa, niin tahdon myös minä tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Ei sinun pidä niin tekemän Herralle sinun Jumalalles; sillä he ovat tehneet jumalillensa kaikkia niitä, mitä Herralle kauhistus on, jota hän vihaa; sillä he ovat poikansakin ja tyttärensä tulella polttaneet jumalillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Kaikki mitä minä käsken teille, pitää teidän pitämän, tehdäksenne sen jälkeen: ei teidän pidä siihen mitään lisäämän, eikä myös siitä mitään vähentämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Jos propheta eli unennäkiä nousee teidän seassanne, ja antaa teille merkin eli ihmeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Ja se merkki eli ihme tapahtuu niin, josta hän puhui sinulle, sanoen: käykäämme ja noudattakaamme vieraita jumalia, joita et sinä tunne, ja palvelkaamme heitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Niin ei sinun pidä kuuleman sen prophetan eli unennäkiän sanoja, sillä Herra teidän Jumalanne koettelee teitä, tietääksensä, rakastatteko Herraa teidän Jumalaanne kaikesta sydämestänne ja kaikesta sielustanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Herraa, teidän Jumalaanne pitää teidän noudattaman ja häntä pelkäämän, ja hänen käskynsä pitämän ja hänen ääntänsä kuuleman, häntä palveleman ja hänessä kiinni riippuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Vaan sen prophetan eli unennäkiän pitää kuoleman; sillä se opetti teitä luopumaan Herrasta teidän Jumalastanne, joka teidät Egyptin maalta johdatti ulos ja sinun orjuuden huoneesta pelasti, ja se vietteli sinun siltä tieltä, jota Herra sinun Jumalas käski sinun käymään: ja sinun pitää eroittaman pois pahan seastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Jos veljes, äitis poika, eli sinun poikas, eli tyttäres, eli emäntäs, joka sinun sylissäs on, eli ystäväs, joka on kuin oma sydämes, viettelis sinua salaa, ja sanois: käykäämme ja palvelkaamme muita jumalia, joita et sinä tunne eikä sinun isäskään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Kansain jumalia teidän ympäristöllänne, joko he läsnä eli kaukana ovat, yhdestä maan äärestä niin toiseen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Niin älä siihen mielisty, älä myös ole hänelle kuuliainen, ja ei sinun silmäs pidä säästämän häntä: ei ensinkään pidä sinun armaitseman eli salaaman häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Mutta sinun pitää kaiketikin surmaaman hänen, sinun kätes pitää ensin hänen päällensä oleman, että hän surmattaisiin, ja sen perästä kaiken kansan käsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Hän pitää kivillä surmattaman, ja hänen pitää kuoleman, sillä hän ahkeroitsi luovuttaa sinua Herrasta sinun Jumalastas, joka sinun Egyptin maalta, orjuuden huoneesta on johdattanut ulos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Että koko Israel sen kuulis ja pelkäis, eikä silleen sen muotoista pahuutta teidän seassanne tekisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Jos saat kuulla jossakussa kaupungissas, jonka Herra sinun Jumalas sinulle antaa asuakses, sanottavan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Muutamat Belialin lapset ovat lähteneet sinun seastas, ja kääntäneet kaupunkinsa asujat pois, ja sanoneet: käykäämme ja palvelkaamme muita jumalia, joita ette tunne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Niin pitää sinun etsimän, tutkiman, ja kyselemän visusti, ja jos todeksi löydetään, että se niin on tosi, että se kauhistus teidän seassanne tapahtunut on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Niin pitää sinun lyömän sen kaupungin asujat miekan terällä, ja hukuttaman heitä, ja kaikki mitä ikänä siinä on, ja heidän karjansa miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Ja kaikki hänen saaliinsa pitää sinun kokooman keskelle sen katua, ja polttaman tulessa, sekä kaupungin että kaikki hänen saaliinsa, Herralle sinun Jumalalles, että se autiona pysyy ijankaikkisesti, ja ei ikänä enään pidä rakettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Ja älä mitään sinun käsiis jätä siitä kirotusta, että Herra kääntyis vihansa julmuudesta, ja antais sinulle laupiuden, ja armahtais sinun päälles, ja enentäis sinun, niinkuin hän vannoi sinun isilles,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Että sinä Herran sinun Jumalas äänelle kuuliainen ollut olet, ja pitänyt kaikki hänen käskynsä, jotka minä sinulle tänäpänä käsken, oikein tehdäkses Herran sinun Jumalas silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Te olette Herran teidän Jumalanne lapset: älkäät piirustelko itsiänne, ja älkäät keritkö itsiänne paljaaksi otsaltanne, jonkun kuolleen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Sillä sinä olet pyhä kansa Herralle sinun Jumalalles, ja Herra on sinun valinnut erinomaiseksi kansaksi, kaikista kansoista, jotka maan päällä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Ei sinun pidä mitäkään kauhistavaista syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Mutta nämät ovat ne eläimet, joita saatte syödä: härkä, lammas, ja vuohi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Peura, metsävuohi, ruskia peura, akko, dison, teo, mäkikauris.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Ja kaikkinainen eläin, jolla on kaksihaarainen sorkka, hajoitettu kahtia, ja märehtii, niitä te saatte syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Ette kuitenkaan saa näitä syödä niistä, jotka märehtivät, ja halaistun sorkkansa jakavat, kuin on: kameli, jänis, kanini; sillä he märehtivät, mutta ei ole kuitenkaan kokonansa kaksisorkkaiset: ne pitää oleman teille saastaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Sika, vaikka hänellä on kaksihaaraiset sorkat, ei hän kuitenkaan märehdi, se pitää teille oleman saastainen: hänen lihaansa ei teidän pidä syömän, eikä sen raatoon sattuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Nämät ovat ne, joita te saatte syödä kaikista niistä jotka vedessä ovat: kaikkinainen, jolla uimus ja suomus on, sitä te saatte syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Mutta se, jolla ei ole uimuksia eikä suomuksia, sitä ei teidän pidä syömän: se on teille saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Kaikkia puhtaita lintuja syökäät:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Nämät heistä ovat ne, joita ei teidän syömän pidä: kotka, luukotka ja kalakotka,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Varis, harakka ja kokkolintu lainensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Ja kaikki kaarneet lainensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Strutsi, pääskyinen, louve ja haukka lainensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Huhkaja, hyypiö, ja yökkö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Ruovon päristäjä, storkki, merimetsäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Haikara, mäkihaukka lainensa, puputtaja ja nahkasiipi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Ja kaikki, jotka matelevat ja lentävät, pitää oleman teille saastaiset: ei pidä niitä syötämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Kaikkia puhtaita lintuja saatte te syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Ei teidän pidä syömän yhtään raatoa: muukalaiselle, joka sinun porteissas on, anna sa syödä, eli myy muukalaiselle: sillä sinä olet pyhä kansa Herralle sinun Jumalalles. Ei sinun pidä keittämän vohlaa emänsä rieskassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Sinun pitää vilpittömästi eroittaman kymmenykset kaikesta sinun jyvätulostas, joka pellostas tulee, vuosi vuodelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Ja sinun pitää syömän Herran sinun Jumalas edessä, siinä paikassa, jonka hän valitsee, että hänen nimensä siinä asuis, sinun jyväis, viinas ja öljys kymmenykset, esikoiset karjastas ja lampaistas, että sinä oppisit pelkäämään Herraa sinun Jumalaas kaikkena elinaikanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Mutta jos tie on sinulle ylen pitkä, niin ettet sinä taida sitä viedä sinne, että se paikka on kaukana sinusta, jonka Herra sinun Jumalas on valinnut, että hänen nimensä siellä asuis; koska Herra sinun Jumalas on siunannut sinun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Niin myy se rahaan, ja ota raha kätees, ja mene siihen paikkaan, jonka Herra sinun Jumalas on valinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Ja osta sillä rahalla kaikkia, mitä sinun sielus himoitsee, joko se on nauta eli lammas, viina, väkevä juoma, taikka mitä ikänä sinun sielus himoitsee, ja syö se Herran sinun Jumalas edessä, ja ole iloinen, sinä ja sinun huonees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Ja Leviläistä, joka sinun porteissas on, ei sinun pidä hylkäämän, sillä ei hänellä ole osaa eli perimystä sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Joka kolmannen vuoden lopulla pitää sinun eroittaman kaikki kymmenykset sinun vuotes tulosta sinä vuonna, ja viemän sinun portteihis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Niin pitää Leviläisen tuleman, jolla ei yhtään osaa eli perimystä ole sinun kanssas, ja muukalainen, ja orpo, ja leski, jotka sinun porteissas ovat, ja heidän pitää syömän ja ravittaman, että Herra sinun Jumalas sinua siunais kaikissa sinun kättes töissä, jotka sinä teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Seitsemän vuoden perästä pitää sinun pitämän vapaavuoden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Ja näin pitää vapaavuosi pidettämän: joka jotakin kädestänsä lähimmäisellensä lainannut on, sen hänen pitää hänelle antaman anteeksi, ja ei velkoman lähimmäistänsä ja veljeänsä; sillä se kutsutaan Herran vapaavuodeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Muukalaista mahdat sinä velkoa; mutta veljelles pitää sinun sen antaman anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Ja ei pidä yksikään kerjääjä teidän seassanne oleman; sillä Herra on siunaava sinua sillä maalla, jonka Herra sinun Jumalas sinulle perimiseksi antaa, omistettavakses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Jos vaan sinä ahkerasti kuulet Herran sinun Jumalas äänen, ja pidät ja teet kaikki nämät käskyt, jotka minä sinulle tänäpänä käsken,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Niin Herra sinun Jumalas on siunaava sinua, niinkuin hän sinulle on sanonut, niin että sinä lainaat monelle kansalle, mutta ei sinun pidä lainaksi ottaman: sinun pitää hallitseman paljo kansaa, mutta sinun ei pidä kenenkään vallitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Jos joku veljistäs on joutunut köyhäksi jossakussa kaupungissa sinun maallas, jonka Herra sinun Jumalas sinulle antaa, niin ei pidä sinun koventaman sydäntäs eikä käsiäs köyhältä veljeltäs sulkeman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Mutta pitää kaiketi avaaman kätes hänelle ja mieluisesti lainaaman, senjälkeen minkä hän puutteessansa tarvitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Ota vaari, ettei sinun sydämees tulisi Belialin ajatus, ettäs sanoisit: nyt tulee pian seitsemäs vuosi, joka on vapaavuosi, ja sinä armottomasti katsot sinun köyhän veljes puoleen, etkä mitäkään annan hänelle: niin hän huutaa sinun ylitses Herran tykö, ja se tulee sinulle synniksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Sinun pitää antaman hänelle hyvällä mielellä, ja sinun sydämes ei pidä paheksuman, koskas hänelle annat; sillä sentähden on Herra sinun Jumalas siunaava sinua kaikissa sinun töissäs, ja sinun kättes teoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Sillä ei köyhät pidä puuttuman maalta, sentähden käsken minä sinua ja sanon: avaa aina kätes veljelles, joka tarvitseva ja köyhä on sinun maallas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Jos veljes, Hebrealainen mies eli vaimo, myy itsensä sinulle, niin hänen pitää palveleman sinua kuusi vuotta; mutta seitsemäntenä vuotena pitää sinun hänen vapaaksi päästämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Ja kuin sinä hänen vapaaksi päästät, ei sinun pidä antaman hänen mennä tyhjin käsin sinun tyköäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Vaan sinun pitää hänelle mieluisesti lahjoittaman lampaistas ja riihestäs ja viinakuurnastas, niin että sinä annat hänelle sitä, jolla Herra sinun Jumalas sinunkin on siunannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Ja muista, että sinäkin olit orja Egyptin maalla, ja Herra sinun Jumalas pelasti sinun; sentähden minä näitä sinulle tänäpänä käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Jos hän sanoo sinulle: en minä lähde sinun tyköäs; sillä hän rakastaa sinua ja sinun huonettas, sillä hänen on hyvä olla sinun tykönäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Niin ota naskali ja pistä hänen korvaansa niin myös oveen, ja anna hänen olla sinun orjas ijäisesti: niin pitää myös sinun tekemän piikas kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Ja älä työlääksi lue sitä sinulles, ettäs hänen tyköäs vapaaksi päästät; sillä hän on palvellut sinua, niinkuin kaksinkertainen palkollinen, kuusi vuotta: niin Herra sinun Jumalas siunaa sinua kaikissa niissä mitä sinä teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Kaikki härkyiset karjan, ja oinaat lammasten esikoisista, pitää sinun pyhittämän Herralle sinun Jumalalles: ei sinun pidä työtä tekemän karjas esikoisella eikä pidä sinun keritsemän lammastes esikoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Herra sinun Jumalas edessä pitää sinun ne syömän vuosi vuodelta, siinä paikassa minkä Herra valinnut on, sinä ja sinun huonees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Jos sillä on joku virhe, niin että hän ontuu taikka on sokia, taikka muutoin joku paha virhe hänessä, niin ei sinun pidä uhraaman sitä Herralle sinun Jumalalles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Sinun porteissas pitää sinun sen syömän, saastainen ja puhdas yhdessä, niinkuin metsävuohen ja peuran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Ainoasti ei sinun pidä syömän sen verta, mutta vuodattaman maahan niinkuin veden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Pidä vaari siitä kuusta Abib, ettäs pidät Herralle sinun Jumalalles pääsiäistä: että sillä kuulla Abib on Herra sinun Jumalas johdattanut sinun Egyptistä, yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Ja teurasta Herralle sinun Jumalalles pääsiäislampaita ja karjaa, siinä paikassa minkä Herra valitseva on nimensä asumasiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Älä syö hapanta leipää sinä juhlana. Seitsemän päivää pitää sinun syömän happamatointa murheen leipää; sillä sinä läksit kiiruusti Egyptin maalta, ettäs sen päivän, jona läksit Egyptin maalta, muistaisit kaikkena sinun elinaikanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Seitsemänä päivänä ei pidä sinulla hapantunutta nähtämän kaikissa sinun maas äärissä, ja lihasta joka ensimäisenä päivänä ehtoona teurastetaan, ei pidä mitäkään jäämän yli yön huomeneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Et sinä saa teurastaa pääsiäiseksi missäkään sinun portissas, jonka Herra sinun Jumalas sinulle antaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Vaan siinä paikassa, jonka Herran sinun Jumalas valitseva on nimensä asumasiaksi, siinä teurasta pääsiäiseksi ehtoolla, kun aurinko laskenut on, sillä ajalla, kuin sinä Egyptistä läksit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Ja kypsennä ja syö siinä paikassa, jonka Herra sinun Jumalas valitseva on, ja sitte huomeneltain palaja ja mene majaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Kuutena päivänä syö happamatointa; mutta seitsemäntenä päivänä on Herran sinun Jumalas päätösjuhla, älä silloin mitäkään työtä tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Lue sinulles seitsemän viikkoa: siitä kuin sirppi eloon viedään, pitää sinun rupeeman ne seitsemän viikkoa lukemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Ja pidä viikkojuhla Herralle sinun Jumalalles, ettäs annat sinun hyväntahtoiset lahjas sinun kädestäs, senjälkeen kuin Herra sinun Jumalas sinulle siunannut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Ja iloitse Herran sinun Jumalas edessä, sinä ja poikas, tyttäres, palvelias, piikas, ja Leviläinen, joka on sinun porteissas, ja muukalainen, ja orpo ja leski, jotka ovat sinun seassas, siinä paikassa jonka Herra sinun Jumalas valitseva on nimensä asumasiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Ja muista, että sinä olet ollut orja Egyptissä, ettäs pidät ja teet nämät säädyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Lehtimajan juhlaa pidä seitsemän päivää, koskas olet sisälle koonnut riihestäs ja viinakuurnastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Ja iloitse juhlanas, sinä ja poikas ja tyttäres, palvelias, piikas, Leviläinen, muukalainen, orpo ja leski, jotka ovat porteissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Seitsemän päivää pidä juhlaa Herralle sinun Jumalalles, siinä paikassa jonka Herra valitseva on; sillä Herra sinun Jumalas siunaa sinua kaikissa, kuin sinä sisälle kokoat, kaikessa sinun kättes työssä; sentähden iloitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Kolmasti vuodessa pitää näkymän kaikki sinun miehenpuoles Herran sinun Jumalas edessä, siinä paikassa jonka hän valitseva on, happamattoman leivän juhlana, viikkojuhlana, ja lehtimajan juhlana: ei yhdenkään pidä näkymän tyhjin käsin Herran edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Itsekukin kätensä lahjan jälkeen, Herran sinun Jumalas siunauksen jälkeen, jonka hän sinulle antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Tuomarit ja käskyläiset aseta sinulles kaikkiin sinun portteihis, jotka Herra sinun Jumalas sinulle antaa sukukunnassas, tuomitsemaan kansaa oikialla tuomiolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Älä käännä oikeutta, älä muotoa katso, ja älä lahjoja ota; sillä lahjat sokaisevat toimellisten silmät ja kääntävät hurskasten asiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Etsi ahkerasti oikeutta, ettäs eläisit ja omistaisit sen maan, jonka Herra sinun Jumalas sinulle antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Älä istuta sinulles metsistöä, jonkun kaltaista puuta Herran sinun Jumalas alttarin juureen, jonka sinä teet sinulles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Älä nosta sinulles patsasta, jota Herra sinun Jumalas vihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Älä uhraa Herralle sinun Jumalalles mitään nautaa eli lammasta, jossa joku virhe taikka puutos on: sillä se on Herralle sinun Jumalalles kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Jos löydetään jossakussa sinun porteistas, jotka Herra sinun Jumalas antaa sinulle, joku mies eli vaimo, joka pahaa tekee Herran sinun Jumalas silmäin edessä, rikkoen hänen liittonsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'Ja menee palvelemaan vieraita jumalia, ja kumartaa niitä, aurinkoa, kuuta tahi jotakuta taivaan joukosta, jota en minä käskenyt ole,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'Ja se sanotaan sinulle, ja sinä kuulet sen, niin tiedustele visusti, ja koskas löydät totiseksi todeksi, että senkaltainen kauhistus Israelissa tehty on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Niin vie se mies tahi vaimo ulos joka senkaltaisen pahuuden on tehnyt, sinun portteihis, ja kivitä hänet kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Kahden eli kolmen suun todistuksesta pitää sen kuoleman, joka kuoleman on ansainnut; mutta yhden suun todistuksesta ei pidä hänen kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Todistajain käsi pitää ensin oleman hänen päällensä tappamaan häntä ja sitte kaiken kansan käsi: sinun pitää eroittaman pahan sinun seastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Jos joku asia tuomiossa näkyy sinulle pimiäksi, veren ja veren välillä, asian ja asian välillä, vahingon ja vahingon välillä, ja kuin eripuraiset asiat ovat sinun porteissas, niin nouse ja mene siihen paikkaan jonka Herra sinun Jumalas valitseva on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Ja tule pappein, Leviläisten ja tuomarin tykö, jotka siihen aikaan ovat, ja kysy heiltä: he sanovat sinulle tuomion sanan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Ja tee sen sanan jälkeen, jonka he sinulle julistavat, siinä paikassa minkä Herra valitseva on, ja ota vaari, ettäs teet kaikki mitä he sinulle opettavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Sen lain jälkeen jonka he opettavat sinulle, ja sen tuomion jälkeen jonka he sanovat sinun etees, pitää sinun tekemän, niin ettes siitä sanasta, kuin he sanovat sinulle, vilpistele et oikialle etkä vasemmalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Ja jos joku olis ollut ylpiä, niin ettei hän ole kuuliainen papille, joka siellä Herran sinun Jumalas palvelusta tekemässä seisoo, eli tuomarille, hänen pitää kuoleman: ja ota sinä paha Israelista pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Että kaikki kansa sen kuulevat ja pelkäävät, ja ei enää ylpiästi tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Koska tulet siihen maahan, kuin Herra sinun Jumalas sinulle antaa, omistaakses sitä ja asuakses siinä, ja sanot: minä asetan kuninkaan minulleni, niinkuin kaikki kansat jotka minun ympärilläni ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Niin aseta se kuninkaaksi sinulles, jonka Herra sinun Jumalas valitsee. Aseta veljistäs kuningas sinulles: et sinä saa muukalaista asettaa sinulles, joka ei sinun veljes ole,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Ainoastaan ettei hän pidä monta hevosta, ja vie kansaa jälleen Egyptiin niiden monien hevosten tähden, ja että Herra teille sanoi: ettette enää tätä tietä tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Ei hänen myös pidä ottaman itsellensä monta emäntää, ettei hänen sydämensä kääntyisi pois, ja ei hänen pidä myös itsellensä aivan paljo hopiaa ja kultaa kokooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Ja kuin hän istuu valtakuntansa istuimella, niin ottakaan tämän lain papeilta Leviläisiltä, ja antakaan kirjoittaa toisen kappaleen siihen kirjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Se olkoon hänen tykönänsä, ja lukekaan sitä kaiken elinaikansa, että hän oppis pelkäämään Herraa Jumalaansa, ja pitämään kaiken tämän lain sanat ja nämät säädyt, ja että hän tekis niiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Niin ettei hän korottaisi sydäntänsä veljeinsä ylitse, eikä myös käskyistä vilpistelisi, oikialle eikä vasemmalle puolelle, että hän päivänsä pitentäisi valtakunnassansa, hän ja hänen poikansa Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Papilla, Leviläisillä ja kaikella Levin sukukunnalla ei pidä osaa eli perintöä Israelissa oleman. Herran uhria ja hänen perintöänsä pitää heidän syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Sentähden ei pidä hänellä perimistä oleman veljeinsä keskellä; sillä Herra on hänen perimisensä, niinkuin hän on hänelle sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Ja tämä on pappein oikeus kansalta ja niiltä, jotka uhraavat härjän tahi lampaan: Papille annettakaan lapa, leukaluut ja sisällykset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Ja uutisen jyvistäs, viinastas, öljystäs, ja liemenet lampaistas pitää sinun antaman hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Sillä Herra sinun Jumalas on hänen valinnut kaikista sinun sukukunnistas, seisomaan ja palvelemaan Herran nimeen, hän ja hänen poikansa jokapäivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Koska Leviläinen tulee jostakusta sinun portistas, koko Israelista, kussa hän vieras on, ja hän tulee kaikesta sielunsa himosta siihen paikkaan, jonka Herra valinnut on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Niin palvelkaan hän Herran Jumalansa nimeen, niinkuin kaikki muutkin Leviläiset hänen veljensä, jotka siellä seisovat Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Ja heidän pitää yhden verran osaa saaman syödäksensä, paitsi sitä mitä hänellä on vanhempainsa myydystä hyvyydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Koskas tulet siihen maahan, jonka Herra sinun Jumalas sinulle antaa, niin älä opi tekemään sen kansan kauhistusten jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Ei yksikään pidä sinun seassas löyttämän, joka poikansa eli tyttärensä käyttää tulessa, eli joka on ennustaja, päivän valitsija, tietäjä, tahi velho,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Tahi lumooja, tahi noita, tahi merkkein tulkitsija, tahi joka kuolleita kysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Sillä joka senkaltaisia tekee, on Herralle kauhistus, ja senkaltaisten kauhistusten tähden ajaa Herra sinun Jumalas heidät ulos sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Sinun pitää oleman vakaa Herran sinun Jumalas edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Sillä nämät kansat, joiden maan sinä omistat, kuulevat päivän valitsioita ja ennustajia: mutta sinulle ei ole niin Herra sinun Jumalas sallinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Vaan Prophetan sinun seastas, sinun veljistäs, minun kaltaiseni, herättää sinulle Herra sinun Jumalas: häntä kuulkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Kaiken se jälkeen kuin sinä anoit Herralta sinun Jumalaltas Horebissa kokouksen päivänä, sanoen: en minä voi enää kuulla Herran minun Jumalani ääntä, enkä silleen voi suurta tulta nähdä, etten minä kuolisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Ja Herra sanoi minulle: he ovat oikein puhuneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Minä herätän heille Prophetan heidän veljistänsä niinkuin sinä olet, ja minä panen minun sanani hänen suuhunsa: hän puhuu heille kaikkia mitä minä hänelle käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Ja tapahtuu, että joka ei minun sanaani kuule, jonka hän minun nimeeni puhuu, häneltä minä sen vaadin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Mutta jos joku propheta ylpeydestä puhuu minun nimeeni sitä mitä en minä hänen käskenyt puhua, ja se joka puhuu muiden jumalain nimeen, sen prophetan pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Jos sanot sydämessäs: kuinka me tiedämme, mitä sanoja ei Herra ole puhunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Kuin propheta puhuu Herran nimeen, ja ei siitä mitään ole, eikä niin tapahdu, niin ne ovat ne sanat, joita ei Herra ole puhunut: se propheta on sen puhunut ylpeydestänsä, älä pelkää häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Kuin Herra sinun Jumalas on hävittänyt pakanat, joiden maan Herra sinun Jumalas sinulle antaa, niitä omistaakses ja asuakses heidän kaupungeissansa ja huoneissansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Niin eroita sinulles kolme kaupunkia sen maan keskellä, jonka Herra sinun Jumalas antaa sinun omistaakses,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Ja valmista sinulles tie, ja jaa maas rajat, jonka Herra sinun Jumalas sinulle antaa perinnöksi, kolmeen osaan, sen paeta, joka miesvahinkoon tullut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Ja se olkaan miehentappajan meno, joka sinne paeta ja elää saa: joka tappaa lähimmäisensä tietämätä, ja ei ennen vihannut häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Vaan niinkuin joku menis metsään lähimmäisensä kanssa puita hakkaamaan, ja nostais käsin kirveensä hakkaamaan puuta maahan, ja kirves lähtis varresta, ja osais loukata lähimmäisensä niin että hän siitä kuolis: sen pitää yhteen näistä kaupungeista pakeneman ja saaman elää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Ettei verenkostaja ajaisi miehentappajaa niinkauvan kuin hänen sydämensä on katkera, ja saavuttaisi häntä että matka pitkä on, ja löis hänen kuoliaaksi, vaikka ei hän kuoleman syytä ole tehnyt; sillä ei hän ennen vihannut häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Sentähden käsken minä sinua, sanoen: eroita sinulles kolme kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Ja jos Herra sinun Jumalas sinun maas rajat levittää, niinkuin hän vannoi isilles, ja antaa sinulle kaiken sen maan, jonka hän lupasi isilles antaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Jos muutoin pidät kaikki nämät käskyt, ja teet sen jälkeen kuin minä sinulle tänäpänä käsken, ettäs rakastat Herraa sinun Jumalaas ja vaellat hänen teissänsä kaikkena elinaikanas: niin lisää vielä kolme kaupunkia näihin kolmeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Ettei viatointa verta vuodatettaisi sinun maassas, jonka Herra sinun Jumalas sinulle antaa perinnöksi, ja veren vika tulisi sinun päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mutta jos joku vihaa lähimmäistänsä ja väijyy häntä ja karkaa hänen päällensä ja tappaa hänen, ja se pakenee yhteen niistä kaupungeista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Niin vanhimmat hänen kaupungistansa lähettäkään sinne sanan, ja tuokaan hänen sieltä, ja antakaan hänen verenkostajan käsiin, että hän kuolis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Ei sinun silmäs pidä armaitseman häntä, ja sinun pitää ottaman pois viattoman veren Israelista, ettäs menestyisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Ei sinun pidä siirtämän lähimmäises rajaa, jonka entiset panneet ovat sinun perintöös, kuin sinä perit siinä maassa, jonka Herra sinun Jumalas sinulle antaa omistaakses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ei pidä todistajan yksinänsä astuman edes ketäkään vastaan, jostakusta pahasta teosta ja synnistä, mikä ikänä paha teko se olis joka tehdään; mutta kahden eli kolmen todistajan suussa ovat kaikki asiat vahvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Jos väärä todistaja tulee ja todistaa jotakuta vastaan ja soimaa hänelle jotain syntiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Niin molemmat ne miehet, jotka riitelevät, seisokaan Herran edessä, pappein ja tuomarein edessä, jotka siihen aikaan ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Ja tuomarit visusti tutkistelkaan sitä, ja katso, jos todistaja on väärä todistaja, ja todistaa väärin veljeänsä vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Niin tehkäät hänelle niinkuin hän aikoi tehdä veljellensä, ettäs erottaisit pahan sinustas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Ja muut sen kuulisivat ja pelkäisivät, ja ei tekisi enää senkaltaista pahaa teidän seassanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Sinun silmäs ei pidä säästämän häntä: henki hengestä, silmä silmästä, hammas hampaasta, käsi kädestä, jalka jalasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Koskas menet sotaan vihollisias vastaan, ja näet hevoset ja vaunut, ja kansan joka on suurempi sinua, niin älä pelkää heitä; sillä Herra sinun Jumalas, joka sinun johdatti ulos Egyptin maalta, on sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Ja kuin te lähestytte sotaa, niin astukaan pappi edes ja puhukaan kansalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Ja sanokaan heille: kuule Israel, te menette tänäpänä sotaan vihollisianne vastaan: älkään sydämenne pehmetkö, älkäät peljätkö, älkäät vavisko, älkäät myös hämmästykö heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Sillä Herra teidän Jumalanne käy kanssanne, sotimaan edestänne vihollisianne vastaan, ja auttaa teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Vaan sodan päämiehet puhutelkaan kansaa ja sanokaan: joka uuden huoneen on rakentanut, ja ei siinä vielä ruvennut asumaan, hän menkään pois ja palatkaan kotiansa, ettei hän kuolisi sodassa, ja joku toinen omistais sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Ja se joka istutti viinamäen, ja ei vielä sitä tehnyt yhteiseksi, hän menkään pois ja palatkaan kotiansa, ettei hän kuolisi sodassa ja toinen tekis sen yhteiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Jos joku on hänellensä vaimon kihlannut, ja ei ottanut häntä tykönsä, hän menkään pois ja palatkaan kotiansa, ettei hän kuolisi sodassa, ja toinen nais häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Ja sodan päämiehet vielä puhukaan kansalle ja sanokaan: joka pelkuri on ja vapisevaisella sydämellä, hän menkään pois ja palatkaan kotiansa, ettei hän saattaisi veljeinsä sydämiä pelkuriksi, niinkuin hänen sydämensä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Ja sittekuin sodan päämiehet lopettaneet ovat kansalle puheensa, niin he asettakaan sotajoukon ylimmäiset ensimäiseksi kansan sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Kuin mene jonkun kaupungin eteen, sotimaan sitä vastaan, niin taritse heille rauhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Ja jos he sinua rauhallisesti vastaavat ja avaavat etees, niin olkaan kaikki kansa joka siinä on, sinulle verollinen ja palvelkaan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Vaan jos ei he tee rauhaa sinun kanssas, vaan sotivat sinua vastaan, niin ahdista heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Ja kuin Herra sinun Jumalas antaa heidät sinun käsiis, niin lyö kuoliaaksi kaikki miehenpuoli miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Mutta vaimot, lapset ja eläimet, ja kaikki ne jotka kaupungissa ovat, ja kaikki saalis ota itselles, ja syö vihollistes saalista, kuin Herra sinun Jumalas antaa sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Ja tee niin jokaiselle kaupungille, joka sinusta aivan kaukana on, ja ei ole näiden kansain kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Mutta näiden kansain kaupungeissa, jotka Herra sinun Jumalas sinulle perimiseksi antaa, älä jätä elämään yhtäkään henkeä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Vaan hukuta ne peräti: nimittäin Hetiläiset, Amorilaiset, Kanaanealaiset, Pheresiläiset, Heviläiset ja Jebusilaiset, niinkuin Herran sinun Jumalas sinulle on käskenyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Ettei he opettaisi teitä tekemään kaikkia niitä kauhistuksia, joita he tekivät jumalillensa, ettette myös tekisi syntiä Herraa teidän Jumalaanne vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Jos sinä kauvan olet jonkun kaupungin edessä, jota vastaan sinä sodit omistaakses sitä, niin älä hävitä sen puita, älä myös kirveellä raiskaa niitä; sillä sinä saat niistä syödä, sentähden älä hakkaa niitä maahan; sillä ihmisellä on metsäpuitakin, tulemaan varustukseksi sinun etees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Vaan ne puut, joista tiedät, ettei ne ole syötäviä, hävitä ja hakkaa maahan, ja rakenna varustus kaupunkia vastaan, jonka kanssa sinä sodit, siksi kuin sinä voitat sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Jos joku tapettu löydetään siinä maassa, jonka Herra sinun Jumalas sinun omakses antaa, ja se makaa kedolla, ja tietämätöintä on, kuka hänen tappoi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Niin käykään ulos vanhimpas ja tuomaris, ja mitatkaan sen tapetun tyköä kaupunkeihin, jotka tapetun ympärillä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Joka kaupunki tapettua lähin on, sen vanhimmat ottakaan nuoren lehmän karjasta, jolla ei ole työtä tehty ja joka ei ikeen alla ole ollut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Ja kaupungin vanhimmat taluttakaan nuoren lehmän kovaan laaksoon, jota ei kynnetä eikä kylvetä, ja leikatkaan lehmän kaulan siinä laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Niin pitää papit, Levin pojat käymän edes; sillä Herra sinun Jumalas on heidät valinnut palvelemaan itseänsä, ja Herran nimeä ylistämään: ja heidän suunsa jälkeen pitää kaikki riidat ja kaikki vahingot selitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Ja kaikki vanhimmat siitä kaupungista, joka tapettua lähinnä on, peskään kätensä nuoren lehmän päällä, jonka kaula laaksossa leikattiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Ja he vastatkaan ja sanokaan: ei meidän kätemme tätä verta vuodattaneet, eikä meidän silmämme sitä nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Ole armollinen kansalles Israelille, jonka sinä Herra pelastit, ja älä tätä viatointa verta anna tulla kansas Israelin päälle; ja niin he ovat sovitetut siitä verestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Ja niin sinä eroitat tyköäs viattoman veren, ettäs teet sen mikä oikia on Herran silmän edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Kuin menet sotaan vihollisias vastaan, ja Herra sinun Jumalas antaa heidät sinun käsiis, ja sinä viet heitä vankina pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Ja näet vankein seassa kauniin vaimon, ja himoitset häntä ottaa emännäkses:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Niin vie häntä huoneeses ja anna hänen keritä hiuksensa ja leikata kyntensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Ja riisua vaatteensa, joissa hän vangittiin, ja anna hänen istua huoneessas, ja itkeä kuukauden isänsä ja äitiänsä: mene sitte hänen tykönsä ja ole hänen miehensä, ja hän olkoon sinun emäntäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Ja jos tapahtuu, ettei hän sinulle kelpaa, niin anna hänen mennä kuhunka hän tahtoo, ja älä suinkaan myy häntä rahaan: älä myös pyydä itselles jotakin voittoa hänen kauttansa; sillä sinä alensit hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Jos jollakin miehellä on kaksi emäntää, yksi, jota hän rakastaa, ja toinen, jota hän vihaa, ja ne synnyttävät hänelle lapsia, sekä se jota hän rakastaa, että se jota hän vihaa, niin että esikoinen on sen, jota hän vihaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Ja aika tulee, että hän lastensa välillä perimisen jakaa, niin ei hän taida tehdä rakkaamman poikaa esikoiseksensa vihattavan esikoisen edestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Vaan hänen pitää tunteman vihattavan pojan esikoiseksensa, niin että hän antaa hänelle kaksinkertaisesti kaikista niistä, mitä häneltä löydetään; sillä se on hänen ensimäinen voimansa, ja hänelle tulee esikoisen oikeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Jos jollakin on itsevaltainen ja kovakorvainen poika, joka ei kuule isänsä ja äitinsä ääntä, ja kuin he kurittavat häntä, ei heitä tottele;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Niin pitää hänen isänsä ja äitinsä hänen ottaman kiinni, ja viemän kaupunkinsa vanhimpain ja portin eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Ja sanokaan kaupunkinsa vanhimmille: tämä meidän poikamme on itsevaltainen ja kovakorvainen, ei tottele meidän ääntämme, ja on syömäri ja juomari;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Niin pitää kaiken kaupungin kansan hänen kuoliaaksi kivittämän: ja niin sinä eroitat pahan sinustas, että koko Israel sen kuulis ja pelkäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Jos joku on tehnyt jonkun synnin, joka kuoleman on ansainnut, ja hirsipuussa kuoletetaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Niin ei pidä hänen ruumiinsa yötä puussa pidettämän, mutta haudatkaat häntä kohta sinä päivänä; sillä se on kirottu Jumalalta, joka hirtetty on, ettet sinä saastuttaisi sinun maatas, jonka Herra sinun Jumalas sinulle perimiseksi antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Kuin näet veljes härjän taikka lampaan eksyneen, niin ei sinun pidä kääntämän itsiäs pois, vaan viemän se kaiketikin jälleen sinun veljelles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Jollei veljes ole sinua läsnä etkä häntä tunne, niin ota se huoneeses, ja olkoon se tykönäs, siihenasti kuin veljes etsii sitä, ja niin anna se hänelle jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Niin tee myös hänen aasinsa kanssa, hänen vaatteensa ja kaikkinaisen kadonneen kanssa, mikä veljeltäs kadonnut on, ja sinä sen löysit: ei sinun pidä itsiäs siitä pois kääntämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Jos näet veljes aasin eli härjän langenneena tiellä, älä käänny pois niistä; vaan sinun pitää joudukkaasti auttaman niitä ylös hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Vaimon ei pidä miehen asetta kantaman, eikä myös miehen pukeman yllensä vaimon vaatteita; sillä jokainen, joka sen tekee, on Herralle sinun Jumalalles kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Ja jos löydät linnun pesän tiellä puusta tahi maasta, jossa on pojat tahi munat, ja emä istuu poikansa eli munain päällä, niin älä ota emää poikinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Mutta päästä kaiketikin emä pois, ja ota pojat sinulles, ettäs menestyisit ja kauvan eläisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Kuin rakennat uutta huonetta, niin tee käsipuut kattos ympäri, ettes veren vikaa saattaisi huoneeses, jos joku sieltä putois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Älä kylvä viinamäkeäs moninaisilla siemenillä, ettes saastuttaisi sekä siemenes kokousta, jonka kylvänyt olet, ja myös viinamäen tuloa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Älä ynnä härjällä ja aasilla kynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Älä pue sitä vaatetta ylles, joka villaisesta ja liinaisesta yhdessä kudottu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tee sinulles rihmoja vaattees neljään kulmaan, jollas puetetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Jos joku mies on nainut emännän, ja on mennyt hänen tykönsä, ja rupee vihaamaan häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'Ja soimaa häntä johonkuhun häpiään vikapääksi, ja saattaa hänestä pahan sanoman, sanoen: minä otin tämän emännäkseni, ja menin hänen tykönsä, ja löysin, ettei hän ollut neitsyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Niin ottakaan vaimon isä ja äiti hänen, ja tuokaan vaimon neitsyyden merkit edes, ja näyttäkään vanhimmille, jotka kaupungin portissa istuvat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Ja vaimon isä sanokaan vanhimmille: minä annoin tälle miehelle minun tyttäreni emännäksi, ja nyt hän vihaa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Ja katso, hän soimaa häntä häpiällisiin asioihin vikapääksi, ja sanoo: en minä löytänyt sinun tytärtäs neitseeksi. Ja katso, tämä on minun tyttäreni neitsyyden merkki. Ja heidän pitää levittämän vaatteen kaupungin vanhimpain eteen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Niin kaupungin vanhimmat ottakaan sen miehen, ja rangaiskaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Ja sakoittakaan hänen sataan hopiasikliin ja antakaan ne nuoren vaimon isälle, että hän häpäisi neitseen Israelissa, ja hänen pitää pitämän hänen emäntänänsä, eikä saa häntä hyljätä kaikkena elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Ja jos se tosi on, ettei vaimo löydetty neitseeksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Niin vietäkään vaimo isänsä huoneen ovelle, ja kaupungin kansa kivittäkään hänen kuoliaaksi, että hän teki tyhmyyden Israelissa, ja että hän salavuoteudessa makasi isänsä huoneessa: ja niin sinä otat pahan pois tyköäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Jos joku löydetään maanneeksi vaimon tykönä, jolla aviomies on, niin pitää molempain kuoleman, sekä miehen, että vaimon, jonka tykönä hän makasi; ja niin pahuus otetaan pois Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Jos joku piika on mieheltä kihlattu, ja joku häneen ryhtyy kaupungissa, ja makaa hänen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Niin pitää ne molemmat vietämän kaupungin porttiin, ja molemmat kivitettämän kuoliaaksi, piika, ettei hän huutanut, sillä hän oli kaupungissa, mies, että hän lähimmäisensä vaimon häpäisi; ja niin sinä eroitat pahan tyköäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Jos joku löytää kihlatun piian kedolla, ryövää ja makaa hänen, niin mies pitää yksin tapettaman, joka makasi hänen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Vaan piialle ei sinun pidä mitään tekemän; sillä ei piika yhtään kuoleman syntiä tehnyt, vaan niinkuin joku karkais lähimmäistänsä vastaan, ja löis hänen kuoliaaksi, niin on myös tämä asia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Sillä hän löysi hänen kedolla: se kihlattu piika huusi, mutta ei ollut hänellä auttajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Jos joku löytää neitseen, joka ei ole kihlattu, ja ottaa hänen kiinni, ja makaa hänen, ja he löydetään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Niin se joka hänen makasi, antakaan piian isälle viisikymmentä hopiasikliä, ja ottakaan piian emännäksensä, että hän on alentanut hänen: ei hän saa hyljätä häntä kaikkena elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Ei yhdenkään pidä ottaman isänsä emäntää, eikä myös paljastaman isänsä peitettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Ei kuohitun ja raajarikon pidä tuleman Herran seurakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Eikä pidä myös äpärän tuleman Herran seurakuntaan, eipä vielä kymmenenteen polveenkaan asti pidä jonkun heistä Herran seurakuntaan tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ammonilaiset ja Moabilaiset ei pidä tuleman Herran seurakuntaan, ei kymmenenteenkään polveen asti, ja ei ikänä tuleman Herran seurakuntaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Sentähden ettei he kohdanneet teitä tiellä leivällä ja vedellä, kuin te läksitte Egyptistä, ja että he palkkasivat teitä vastaan Bileamin Beorin pojan Mesopotamian Petorista, kiroomaan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Mutta Herra sinun Jumalas ei kuullut Bileamia, vaan Herra sinun Jumalas muutti sinulle kirouksen siunaukseksi; sillä Herra sinun Jumalas rakasti sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Älä toivota heille rauhaa eli jotakin hyvää, kaikkena elinaikanas ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Edomilaista älä kauhistu; sillä hän on sinun veljes. Älä myös Egyptiläistä kauhistu; sillä sinä olit muukalainen hänen maassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Ne lapset, jotka heistä syntyvät kolmannessa polvessa, tulkaan Herran seurakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Kuin lähdet leiristäs vihollisias vastaan, kavahda itsiäs kaikkinaisesta pahuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Jos joku on teidän seassanne, joka ei ole puhdas, että hänelle yöllä jotakin tapahtunut on; hänen pitää menemän pois leiristä, ja ei leiriin sisälle tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Ja hänen pitää ehtoona itsensä vedellä pesemän, ja sittekuin aurinko laskenut on, palatkaan leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Ulkona leiristä olkoon sinulla paikka, johonkas menet tarpeilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Ja sinulla pitää oleman vähä kalikka vyölläs, ja kuin menet tarpeilles, kaiva sillä, ja istuttuas, peitä saastaisuutes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Sillä Herra sinun Jumalas vaeltaa sinun leiris lävitse pelastamaan sinua ja antamaan sinun vihollises sinun etees, sentähden pitää sinun leiris pyhä oleman, ettei häpiää näkyisi sinun seassas ja hän kääntäis itsensä sinusta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Älä isännän haltuun anna orjaa, joka häneltä sinun tykös karannut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Hän olkaan sinun tykönäs, sinun keskelläs siinä paikassa, joka hänelle kelpaa, jossakussa sinun portissas, itsellensä hyväksi, älä sorra häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Ei pidä yhtäkään porttoa oleman Israelin lasten tytärten seassa, eikä yhtään huorintekiää Israelin poikain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Älä kanna porton palkkaa eikä koiran hintaa Herran sinun Jumalas huoneesen, jonkun lupauksen edestä; sillä ne molemmat ovat Herralle sinun Jumalalles kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Älä korkoa ota veljeltäs rahasta, syötävästä tahi muusta, josta korko otetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Muukalaiselta ota korko, mutta älä veljeltäs, että Herra sinun Jumalas siunais sinua kaikessa aivoituksessas siinä maassa, johonkas tulet omistamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Kuin Herralle sinun Jumalalles lupauksen lupaat, niin älä viivytä maksaa sitä; sillä Herra sinun Jumalas on sen totisesti vaativa sinulta, ja se on sinulle synti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Vaan jollet sinä lupaa, niin ei ole sinulla syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Pidä se, mikä sinun huulistas on käynyt ulos, ja tee, niinkuin sinä Herralle sinun Jumalalles hyvällä ehdolla luvannut olet sitä, minkä sinä suullas puhunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Kuin menet lähimmäises viinamäkeen, niin sinä saat syödä viinamarjoja himos jälkeen, ettäs ravitaan; mutta älä pane mitäkään astiaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Koskas menet lähimmäises laihoon, niin sinä saat katkoa tähkäpäitä kädelläs, mutta älä sirpillä lähimmäises laihoa niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Jos joku ottaa vaimon avioksensa, ja tapahtuu, ettei hän sitte löydä armoa hänen silmäinsä edessä, että on löytänyt jonkun häpiän hänessä; niin kirjoittaa hän hänelle erokirjan, ja antaa sen hänen käteensä, ja antaa hänen mennä huoneestansa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Kuin se hänen huoneestansa lähtenyt on, menee pois ja tulee jonkun toisen miehen emännäksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Ja taas toinen mies rupee häntä vihaamaan, ja kirjoittaa hänelle erokirjan, ja antaa hänen käteensä ja laskee hänen huoneestansa pois: eli jos toinen mies, joka hänen emännäksensä otti, kuolee:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Niin hänen ensimäinen miehensä, joka hänen antoi mennä pois, ei pidä häntä ottaman jälleen emännäksensä, sittekuin hän tuli saastaiseksi; sillä se on kauhistus Herran edessä, ettes maata saastuttaisi, jonka Herra sinun Jumalas antaa sinulle perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Jos joku on äsken emännän nainut, ei sen pidä menemän sotaan, eikä pidä hänen päällensä mitään rasitusta pantaman; vaan olkaan vapaana huoneessansa ajastajan päivät, että hän sais iloita emäntänsä kanssa, jonka hän nainut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Ei pidä molempia myllynkiviä, eli päällyskiveäkään keltään pantiksi otettaman; sillä se olis ottaa hengen pantiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Jos joku löydetään, joka sielun varastaa veljistänsä, Israelin lapsista, ja etsii sillä voittoa taikka myy hänen, sen varkaan pitää kuoleman, ettäs eroittaisit pahan sinustas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Karta spitalitautia, ettäs visusti teet ja pidät kaikki, mitä Leviläiset ja papit opettavat sinulle: niinkuin minä heille käskin, ne pitäkäät ja niiden jälkeen tehkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Muista, mitä Herra sinun Jumalas teki MirJamille, tiellä, kuin te Egyptistä läksitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Ja kuin jotain lainaat lähimmäiselles, älä mene hänen huoneesensa panttia ottamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Vaan seiso ulkona, ja se, jolle lainasit, kantakaan itse pantin sinulle ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Vaan jos hän köyhä on, älä mene levätä hänen pantillansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Vaan anna hänen panttinsa kaiketikin jälleen ennen auringon laskemata, että hän makais vaatteissansa ja siunais sinua: ja se luetaan sinulle vanhurskaudeksi Herran sinun Jumalas edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Älä tee vääryyttä köyhälle ja tarvitsevalle päivämiehelle, joko hän olis sinun veljistäs, eli muukalaisista, joka on sinun maallas sinun porteissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Vaan maksa hänelle hänen palkkansa sinä päivänä, ennen auringon laskemata; sillä hän on hätäytynyt ja siitä hän elää, ettei hän huutaisi Herran tykö sinun tähtes, ja se luettaisiin sinulle synniksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Ei pidä isäin kuoleman lasten tähden, eikä myös lasten isäinsä tähden; mutta kunkin pitää kuoleman oman syntinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Älä käännä muukalaisen eli orvon oikeutta, älä myös leskeltä ota vaatteita pantiksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Vaan muista, että sinäkin olit orja Egyptissä, ja Herra sinun Jumalas sieltä sinun johdatti; sentähden minä sinua käsken, ettäs nämät tekisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Kuin pellostas elon leikkaat, ja lyhde sinulta sinne unohtuu, älä palaja sitä ottamaan, vaan olkoon se muukalaisen, orvon ja lesken oma, että Herra sinun Jumalas siunaisi sinua kaikissa sinun kättes töissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Kuin olet poiminut öljypuus hedelmät, niin älä vastuudesta sitä varista; vaan sen pitää muukalaisen, orvon ja lesken oman oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Kuin viinamäkes korjannut olet, älä vastuudesta jääneitä hae; vaan ne pitää muukalaisen, orvon ja lesken omat oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Ja muista, että sinä olet orja ollut Egyptin maalla, sentähden käsken minä sinua näitä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Jos riita on miesten välillä, niin tulkaan ne oikeuden eteen, ja tuomittakaan niiden välillä: ja tuomittakaan hurskas hurskaaksi, ja jumalatoin jumalattomaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Ja jos jumalatoin on ansainnut haavoja, niin käskekään tuomari hänen langeta maahan, ja antakaan nähtensä lyödä häntä, senjälkeen kuin hänen pahatekonsa on, luvun jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Neljäkymmentä kertaa pitää häntä lyötämän, ja ei enempää, ettei häntä ylönpalttisesti lyötäisi, ja sinun veljes tulis huonoksi sinun silmäis edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Ei sinun pidä riihtä tappavan härjän suuta sitoman kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Koska veljekset asuvat ynnä, ja yksi heistä kuolee pojatoinna, niin ei pidä kuolleen veljen vaimon ottaman muukalaista miestä toisesta suvusta; mutta hänen miehensä veli menkään hänen tykönsä, ja ottakaan veljensä siassa häntä avioksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Ja ensimäinen poika, jonka hän synnyttää, pitää nimitettämän kuolleen veljen nimeltä, ettei hänen nimensä peräti hävitettäisi Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Jos ei mies tahdo ottaa veljensä vaimoa, niin menkään hänen veljensä vaimo porttiin vanhimpain eteen, ja sanokaan: ei kytyni tahdo herättää veljellensä nimeä Israelissa ja ei tahdo minua kytylain jälkeen naida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Niin kaupungin vanhimmat antakaan hänen kutsuttaa edes, ja puhukaan hänen kanssansa. Ja jos hän seisoo ja sanoo: en minä tahdo ottaa häntä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Niin hänen natonsa astukaan hänen tykönsä vanhimpain nähden, ja riisukaan kengän hänen jalastansa, ja sylkekään hänen kasvoillensa, ja vastatkaan häntä sanoen: näin jokaiselle pitää tehtämän, joka ei veljensä huonetta rakenna,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Ja hänen nimensä kutsuttakaan Israelissa paljasjalan huoneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Jos kaksi miestä keskenänsä tappelevat ja toisen vaimo tulee pelastamaan miestänsä sen kädestä joka häntä lyö, ja kurottaa kätensä ja tarttuu hänen häpyynsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Niin hakkaa hänen kätensä poikki; sinun silmäs ei pidä säästämän häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Älä pidä kahtalaista vaakaa säkissäs, suurempaa ja vähempää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Eikä myös pidä huoneessas oleman kahtalainen mitta, suurempi ja vähempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Mutta sinulla pitää oleman täysi ja oikia vaaka, ja täysi ja oikia mitta, ettäs olisit pitkäijällinen siinä maassa, jonka Herra sinun Jumalas sinulle antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Sillä jokainen, joka näitä tekee, on Herralle sinun Jumalalles kauhistus: kaikki jotka vääryyttä tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Muista mitä Amalekilaiset tekivät sinua vastaan tiellä, kuin Egyptistä läksit:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Kuinka he kohtasivat sinua tiellä, ja löivät sinun jälkimäises, kaikki ne jotka heikommat olivat ja jälinnä kävivät, koskas väsyksissä ja hervotoin olit, ja ei he Jumalaa peljänneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Ja pitää tapahtuman, kuin Herra sinun Jumalas antaa sinun saada levon kaikilta vihamiehiltäs, jotka ympärilläs ovat siinä maassa, jonka Herra sinun Jumalas antaa perinnöksi sinulle, ettäs sen omistat, ja sinun pitää peräti hävittämän Amalekilaisten muiston taivaan alta. Älä sitä unohda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Kuin tulet siihen maahan jonka Herra sinun Jumalas sinulle perinnöksi antaa, ja sinä sen omistat, ja asut siinä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Niin ota kaikkinaisista sinun maas kasvuista ensimäiset hedelmät, jotka maasta kasvavat, jotka Herra sinun Jumalas sinulle antaa, pane ne koriin, ja mene siihen siaan, jonka Herra sinun Jumalas valitsee nimensä asumasiaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Ja mene papin tykö, joka siihen aikaan on, ja sano hänelle: minä tunnustan tänäpänä Herran sinun Jumalas edessä, että minä olen tullut siihen maahan, jonka Herra meidän isillemme vannoi, meille antaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Ja pappi ottakoon korin kädestäs ja laskekaan sen maahan, Herran sinun Jumalas alttarin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Niin lausu sinä, ja sano Herran sinun Jumalas edessä: minun raadollinen isäni oli Syrialainen, ja meni Egyptiin vähällä joukolla, ja oli siellä muukalainen, ja hän tuli siellä suureksi, väkeväksi ja monilukuiseksi kansaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Mutta Egyptiläiset ahdistivat ja vaivasivat meitä, ja panivat kovan orjuuden meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Niin me huusimme Herran meidän isäimme Jumalan tykö, ja Herra kuuli meidän äänemme, ja katsoi meidän tuskaamme, työtämme ja ahdistustamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Ja Herra vei meidät ulos Egyptistä voimallisella kädellä, ja ojennetulla käsivarrella, suurella peljästyksellä, merkeillä ja ihmeillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Ja johdatti meidät tähän paikkaan ja antoi meille tämän maan, maan, joka rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Ja nyt katso, minä kannan tässä maan ensimäisiä hedelmiä, jonka sinä Herra minulle annoit. Ja niin pane ne Herran sinun Jumalas eteen, ja kumarra Herran sinun Jumalas edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Ja ole iloinen kaikesta hyvyydestä, minkä Herra sinun Jumalas sinulle antoi, ja sinun huoneelles: sinä ja Leviläinen ja muukalainen, joka sinun keskelläs on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Kuin olet koonnut kaikki kymmenykset sinun vuotes kasvusta kolmantena vuonna, joka on kymmenysten vuosi, niin anna Leviläisille, muukalaisille, orvoille ja leskille, että he söisivät sinun porteissas ja ravittaisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Ja sano Herran sinun Jumalas edessä: minä olen tuonut huoneestani sen, mikä pyhitetty on, ja annoin Leviläisille, muukalaisille, orvoille ja leskille, kaiken sinun käskys jälkeen jonka olet minulle käskenyt: en minä harhaillut sinun käskyistäs, enkä niitä unhottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'En minä siitä ole syönyt minun surussani, enkä ottanut siitä saastaisuudesta, en myös niistä mitään antanut kuolleille: minä olen ollut Herran minun Jumalani äänelle kuuliainen, ja tehnyt kaiken sen jälkeen, minkä sinä minulle käskenyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Katsahda tänne pyhästä asumasiastas taivaasta, ja siunaa sinun kansaas Israelia ja maata, jonka sinä meille antanut olet, niinkuin sinä vannoit isillemme, maata, joka rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Tänäpänä Herra sinun Jumalas käskee sinua tekemään näiden säätyin ja oikeutten jälkeen, niin ettäs pidät ne ja teet niiden jälkeen kaikesta sydämestäs ja kaikesta sielustas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Herran edessä olet sinä sen luvannut tänäpänä, että hän pitää oleman sinun Jumalas, ja sinä tahdot vaeltaa hänen teissänsä, ja pitää hänen säätynsä, käskynsä ja oikeutensa, ja olla kuuliainen hänen äänellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Ja Herra on sinulle tänäpänä luvannut, että sinun pitää oleman hänen kansansa, niinkuin hän sinulle on puhunut, että sinun pitää kaikki hänen käskynsä pitämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Ja hän korottaa sinua kaikkein kansain ylitse, minkä hän tekee ylistykseksi, kiitokseksi ja kunniaksi, ettäs olisit Herralle sinun Jumalalles pyhä kansa, niinkuin hän sanonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Sitte Moses ja Israelin vanhimmat käskivät kansalle ja sanoivat: pitäkäät kaikki ne käskyt, jotka minä tänäpänä teille käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Ja sinä päivänä, jona te menette Jordanin yli siihen maahan, jonka Herra sinun Jumalas sinulle antaa, pitää sinun pystyttämän suuret kivet ja sivuuman ne kalkilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Ja kirjoita niihin kaikki nämät lain sanat, kuin tulet ylitse, ettäs tulisit sille maalle, jonka Herra sinun Jumalas sinulle antaa, sille maalle joka rieskaa ja hunajaa vuotaa, niinkuin Herra isäis Jumala sanoi sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Kuin te siis menette Jordanin yli, niin pystyttäkäät ne kivet, joista minä tänäpänä käsken, Ebalin vuorella, ja sivutkaat ne kalkilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Ja rakenna siinä Herralle sinun Jumalalles alttari kivistä, joihin ei sinun pidä rautaa satuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Rakenna siellä alttari Herralle sinun Jumalalles kokonaisista kivistä, ja uhraa Herralle sinun Jumalalles polttouhria sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Uhraa myös kiitosuhria, ja syö siellä, ja ole iloinen Herran sinun Jumalas edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Ja kirjoita kaikki tämän lain sanat selkiästi ja ymmärtäväisesti niihin kiviin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Ja Moses ynnä pappein ja Leviläisten kanssa puhui kaikelle Israelin kansalle, sanoen: ota vaari ja kuule Israel. Tänäpänä sinä tuli Herran sinun Jumalas kansaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Ettäs kuuliainen olisit Herran sinun Jumalas äänelle ja tekisit hänen käskyinsä ja säätyinsä jälkeen, jotka minä tänäpänä sinulle käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Ja Moses käski kansalle sinä päivänä, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Nämät seisokaan Gerisimin vuorella, ja siunatkaan kansaa, kuin olette käyneet Jordanin ylitse: Simeon, Levi, Juuda, Isaskar, Joseph ja BenJamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Ja nämät seisokaan Ebalin vuorella kiroomassa: Ruben, Gad, Asser, Sebulon, Dan ja Naphtali.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Ja Leviläiset alkakaan ja sanokaan jokaiselle Israelissa korkialla äänellä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Kirottu olkoon, joka tekee kaivetun tahi valetun epäjumalan kuvan Herralle kauhistukseksi, virkamiesten käsialaisen, ja pitää sen salaa, ja kaikki kansa vastatkaan ja sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Kirottu olkoon, joka isänsä eli äitinsä ylönkatsoo, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Kirottu olkoon, joka lähimmäisensä rajan siirtää, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Kirottu olkoon, joka laskee sokian eksymään tiellä, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Kirottu olkoon, joka muukalaisen, orvon ja lesken oikeuden vääntää, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Kirottu olkoon, joka isänsä emännän tykönä makaa, että hän paljasti isänsä peitteen, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Kirottu olkoon, joka johonkuhun eläimeen ryhtyy, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Kirottu olkoon, joka sisarensa makaa, joka hänen isänsä eli äitinsä tytär on, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Kirottu olkoon, joka anoppinsa makaa, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Kirottu olkoon, joka lähimmäisensä salaisesti lyö, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Kirottu olkoon, joka lahjoja ottaa, lyödäksensä viatointa verta, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Kirottu olkoon, joka ei kaikkia näitä lain sanoja täytä, että hän niiden jälkeen tekis, ja kaikki kansa sanokaan: amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Ja jos sinä olet Herran sinun Jumalas äänelle ahkerasti kuuliainen, ettäs pidät ja teet kaikki hänen käskynsä, jotka minä tänäpänä sinulle käsken, niin Herra sinun Jumalas tekee sinun korkiammaksi kaikkia kansoja maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Ja kaikki nämät siunaukset tulevat sinun päälles, saavuttavat sinun, ettäs Herran sinun Jumalas äänelle kuuliainen olit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Siunattu olet sinä kaupungissa, siunattu pellolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Siunattu on ruumiis hedelmä, ja maas hedelmä, ja karjas hedelmä, eläintes hedelmä, ja lammaslaumas hedelmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Siunattu on koris ja tähtees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Siunattu olet sinä käydessäs sisälle, ja siunattu käydessäs ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Ja Herra langettaa vihollises sinun edessäs, jotka sinua vastaan nousevat; yhtä tietä he tulevat sinua vastaan, ja seitsemää tietä pitää heidän pakeneman sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Herra käskee siunauksen olla sinun kanssas sinun riihessäs ja kaikissa mitä sinä aiot, ja siunaa sinun siinä maassa, jonka Herra sinun Jumalas sinulle antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Herra asettaa sinun itsellensä pyhäksi kansaksi, niinkuin hän vannoi sinulle, koskas pidät Herran sinun Jumalas käskyt ja hänen teissänsä vaellat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Että kaikki kansat maan päällä näkevät sinun olevan Herran nimeen nimitetyn, ja pitää sinua pelkäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Ja Herra lahjoittaa sinun runsaasti hyvyydellä, sekä kohtus hedelmällä, karjas hedelmällä, ja maas hedelmällä, siinä maassa, jonka Herra vannoi sinun isilles, sinulle antaaksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Herra avaa sinulle hyvän tavaransa, taivaan, antaaksensa maalles sateen ajallansa ja siunataksensa kaikki sinun käsialas; ja sinä lainaat monelle kansalle, mutta et sinä keneltäkään lainaksi ota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Ja Herra asettaa sinun pääksi, eikä hännäksi: sinä olet aina ylimmäinen etkä alimmainen, koskas olet Herran sinun Jumalas käskyille kuuliainen, jotka minä tänäpänä sinun käsken pitää ja tehdä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Ja et luovu niistä sanoista, jotka minä tänäpänä teille käsken, ei oikialle eikä vasemmalle puolelle, muiden jumalain jälkeen vaeltaakses ja heitä palvellakses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Mutta ellet sinä kuule Herran sinun Jumalas ääntä, pitääkses ja tehdäkses kaikki hänen käskyjänsä ja säätyjänsä, jotka minä tänäpänä sinulle käsken, niin kaikki nämät kiroukset tulevat sinun päälles ja sattuvat sinuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Kirottu olet sinä kaupungissa, kirottu pellolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Kirottu on koris ja tähtees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Kirottu on ruumiis hedelmä, maas hedelmä, karjas hedelmä, lammaslaumas hedelmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Kirottu olet sinä käydessäs sisälle, kirottu käydessäs ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Herra lähettää sinun sekaas kirouksen, tyhmyyden ja rangaistuksen kaikissa sinun aivoituksissas, siihenasti ettäs hukut ja pian katoat pahain tekois tähden, ettäs minun hylkäsit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Herra antaa ruttotaudin riippua sinussa, siihenasti että hän sinun hukuttais siitä maasta, jotas tulet omistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Herra lyö sinua kuivataudilla, lämpimällä taudilla, poltteella, palavuudella, kuivuudella, kuumuudella ja keltataudilla, ja vainoo sinua, siihenasti että hän sinun kadottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Ja sinun taivaas, joka sinun pääs päällä on, pitää niinkuin vasken oleman, ja maan, joka sinun allas on, niinkuin raudan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Herra antaa maalles tomun ja tuhan sateen edestä taivaasta sinun päälles, siihenasti ettäs hukutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Herra lyö sinun vihollistes edessä. Yhtä tietä sinä menet heidän tykönsä, mutta seitsemän tien kautta sinä heidän edellänsä pakenet, ja sinä hajoitetaan kaikkein valtakuntain sekaan maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Sinun ruumiis on ravinnoksi kaikille taivaan linnuille ja kaikille maan pedoille, ja ei kenkään heitä karkota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Herra lyö sinun Egyptin paisumilla, häpiällisillä veripahkoilla, ruvilla ja syyhelmällä, niin ettes taida parantua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Herra lyö sinun hourauksella, sokeudella ja sydämen tyhmyydellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Ja sinä koperoitset puolipäivänä niinkuin sokia pimiässä koperoitsee, ja et menesty teissäs, ja sinä kärsit väkivaltaa ja vääryyttä, niinkauvan kuin elät, ja ei kenkään sinua auta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Vaimon sinä kihlaat, mutta toinen sen makaa; huoneen sinä rakennat, mutta et sinä saa hänessä asua; viinamäen sinä istutat, mutta et sinä saa sitä yhteiseksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Sinun härkäs teurastetaan silmäis nähden, mutta et sinä saa hänestä syödä. Aasis otetaan väkivallalla sinun nähtes, ja ei sinulle anneta sitä jälleen. Lampaas annetaan vihollisilles, ja ei kenkään sinua auta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Sinun poikas ja tyttäres annetaan toiselle kansalle, niin että sinun silmäs sen näkevät, ja hiveltyvät heistä joka päivä, ja ei yhtään väkevyyttä pidä sinun käsissäs oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Sinun maas hedelmän ja kaikki sinun työs se kansa syö, jota et tunne, ja sinun täytyy ainoastansa vääryyttä kärsiä ja sorrettuna olla koko sinun elinaikanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Ja sinä tulet mielettömäksi niistä, mitä silmäs näkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Herra lyö sinua pahoilla paisumilla polvissas ja pohkeissas, niin ettes taida parantua jalkapöydästä niin pääs lakeen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Herra antaa sinun ja sinun kuninkaas, jonka itselles asettanut olet, vaeltaa sen kansan tykö, jota et sinä tunne, eikä sinun isäs, ja siellä sinä palvelet muukalaisia jumalia, puita ja kiviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Ja sinun pitää tuleman kauhistukseksi, sananlaskuksi ja jutuksi kaikkein kansain seassa, joihin Herra ajaa sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Sinä kylvät paljo siementä peltoon, mutta tuot vähän sisälle; sillä heinäsirkat syövät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Viinamäen sinä istutat ja ruokkoat, mutta et saa siitä juoda viinaa, et myös koota; sillä madot sen syövät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Öljypuita on sinulla kaikissa sinun maas paikoissa, mutta ei sinun pidä voiteleman sinuas öljyllä; sillä öljypuus revitään ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Poikia ja tyttäriä sinä siität, ja et kuitenkaan niitä nautitse; sillä ne viedään vangittuna pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Kaikki sinun puus ja maas hedelmän omistavat sirkat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Muukalainen, joka sinun tykönäs on, ylennetään sinun ylitses, ja on alati ylinnä; mutta sinä alennetaan ja alati alinna olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Hän lainaa sinulle, mutta ei sinä voi hänelle lainata. Hän on pää, ja sinun pitää hännän oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Ja kaikki nämät kiroukset tulevat sinun päälles ja sinua vainoovat, ja sinuun sattuvat, siihenasti ettäs hukut; ettes Herran sinun Jumalas ääntä kuullut, pitääkses hänen käskynsä ja säätynsä, jotka hän sinulle on käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Sentähden ovat ne sinussa merkiksi ja ihmeiksi ja sinun siemenessäs ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Ettes palvellut Herraa sinun Jumalaas iloisella ja riemuisella sydämellä, koska sinulla kaikkinaista kyllä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Ja sinun pitää palveleman vihollisias, jotka Herra lähettää sinun päälles, nälässä ja janossa, alastomuudessa ja kaikkinaisessa puutteessa. Ja hän panee sinun kaulaas rautaisen ikeen, siihenasti että hän sinun hukuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Herra lähettää kansan sinun päälles taampaa maailman äärestä, niinkuin kotka lentäis, kansan, jonka puhetta et sinä ymmärrä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Häpeemättömän kansan, joka ei karta vanhaa eikä armaitse nuorukaista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Ja syö karjas hedelmän ja maas hedelmän, siihenasti ettäs hukut, eikä jätä sinulle mitäkään jyvistä, viinasta, öljystä, karjan eli lammasten hedelmästä, siihenasti että hän sinun kadottaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Ja ahdistaa sinua kaikissa porteissas, siihenasti että hän kukistaa maahan korkiat ja vahvat muuris, joihin sinä luotat, kaikissa maakunnissas; ja sinä ahdistetaan kaikissa porteissas, koko sinun maassas, jonka Herra sinun Jumalas sinulle antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Sinun täytyy syödä ruumiis hedelmän, poikais ja tytärtes lihan, jotka Herra sinun Jumalas sinulle antanut on, siinä ahdistuksessa ja vaivassa, jolla sinun vihollises sinua ahdistavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Se mies, joka ennen sangen herkullisesti ja hekumassa teidän seassanne eli, ei pidä suoman veljellensä ja vaimollensa, joka on hänen sylissänsä, ja sille joka on vielä jäänyt hänen pojistansa, jääneitä tähteitänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Annettaa jonkun niistä hänen poikainsa lihasta, jota hän syö; ettei hänellä mitäkään muuta ole kaikesta hyvyydestänsä siinä ahdistuksessa ja vaivassa, jolla vihollises ahdistaa sinua kaikissa porteissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Vaimo teidän seassanne, joka ennen herkullisesti ja hekumassa elänyt on, niin ettei hän malttanut jalkaansa laskea maan päälle herkun ja hekuman tähden, ei pidä suoman miehellensä, joka hänen sylissänsä lepää, ja pojallensa ja tyttärellensä');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Jälkimmäisiä, jotka hänen kohdustansa lähteneet ovat, eikä myös poikiansa joita hän synnyttää; sillä hän syö ne kaikkein tarvetten puuttumisessa salaisesti, siinä ahdistuksessa ja vaivassa, jolla vihollises ahdistavat sinua porteissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Elles pidä ja tee kaikkia näitä lain sanoja, jotka tässä kirjassa ovat kirjoitetut, niin että pelkäät tätä kunniallista ja peljättävää nimeä, Herraa sinun Jumalaas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Niin Herra ihmeelliseksi tekee sinun ja sinun siemenes rangaistukset, suurilla ja pitkällisillä vitsauksilla, pahoilla ja pitkällisillä taudeilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Ja kääntää sinun päälles kaikkinaiset Egyptin taudit, joita pelkäsit, ja ne pitää sinuun tarttuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Siihen myös kaikki sairaudet ja kaikki rangaistukset, jotka ei kirjoitetut ole tässä lakiraamatussa, laskee Herra sinun päälles, siihenasti ettäs hukut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Ja teistä, jotka ennen olitte niinkuin tähdet taivaassa paljouden tähden, jää vähäinen kansa, ettes kuullut Herran sinun Jumalas ääntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Ja tapahtuu, että niinkuin Herra ennen iloitsi teistä, teille hyvää tehdessänsä ja enentäissänsä teitä, niin Herra on iloitseva teistä, hukuttaissansa ja kadottaissansa teitä; ja te syöstään siitä maasta pois, jota te menette omistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Ja Herra hajoittaa sinun kaikkein kansain sekaan, yhdestä maan äärestä toiseen; ja siellä sinä palvelet muukalaisia jumalia, joita et sinä tunne, eikä isäskään, kantoja ja kiviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Siihen myös ei pidä sinulla sen kansan seassa yhtään vahvaa kotoa oleman, eikä jalkais pöytä yhtään lepoa saaman; sillä Herra antaa sinulle siellä vapisevaisen sydämen, hiveltyneet silmät ja murheellisen mielen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Niin että sinun elämäs riippuu sinun edessäs: yöllä ja päivällä sinun pitää pelkäämän ja elämästäs tietämätöin oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Aamulla sinä sanot: ah, jospa minä ehtoosen eläisin! ehtoona sinä sanot: ah, jospa minä aamuun eläisin! sinun sydämes suuren pelvon tähden, joka sinua peljättää, ja sen tähden, jota sinun silmäs näkemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Ja Herra vie sinua taas haaksilla Egyptiin sitä tietä, josta minä sanoin sinulle: ei sinun pidä häntä silleen näkemän. Ja te myytte itsenne siellä vihollisillenne palvelioiksi ja piioiksi, ja ei yhtäkään ostajaa siellä oleman pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Nämät ovat liiton sanat, jonka Herra käski Moseksen tehdä Israelin lasten kanssa Moabin maassa, paitsi sitä liittoa, jonka hän heidän kanssansa teki Horebissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Ja Moses kutsui koko Israelin ja sanoi heille: te näitte kaikki, mitä Herra teidän silmäinne edessä teki Egyptissä Pharaolle, kaikille hänen palvelioillensa ja koko hänen maallensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Ne suuren kiusaukset, jotka sinun silmäsi näkivät, ja ne suuret merkit ja ihmeelliset teot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Ja ei Herra vielä nytkään tähän päivään asti antanut teille sydäntä ymmärtämään ja silmiä näkemään ja korvia kuulemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Ja minä annoin teidän vaeltaa korvessa neljäkymmentä vuotta; ei teidän vaatteenne vanhenneet yltänne, eikä kenkäs kuluneet jaloissas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Ette syöneet leipää, ettekä myös juoneet viinaa elikkä väkevää juomaa, että te tietäisitte minun olevan Herran teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Ja kuin te tulitte tähän paikkaan, niin tuli Sihon Hesbonin kuningas ja Og Basanin kuningas sotimaan meitä vastaan, ja me löimme heidät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Ja omistimme heidän maansa, ja annoimme sen Rubenilaisille ja Gadilaisille, niin myös puolelle Manassen sukukunnalle, perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Niin pitäkäät nyt nämät liiton sanat, ja tehkäät niiden jälkeen, että toimellisesti tekisitte kaikki mitä te teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Te seisotte kaikki tänäpänä Herran teidän Jumalanne edessä: ylimmäiset teidän suvuistanne, teidän vanhimpanne, ja teidän esimiehenne, joka mies Israelissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Teidän lapsenne, teidän vaimonne, ja muukalaises joka sinun leirissäs on, sinun puus hakkaajasta niin vetes ammuntajaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Että sinä käyt Herran sinun Jumalas liittoon ja siihen valaan, minkä Herra sinun Jumalas teki sinun kanssas tänäpänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Että hän tänäpänä korottaa sinun itsellensä kansaksi, ja hän on sinun Jumalas niinkuin hän sanoi sinulle, ja niinkuin hän vannoi isilles, Abrahamille, Isaakille ja Jakobille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Sillä en minä tee tätä liittoa ja tätä valaa ainoastaan teidän kanssanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Mutta sekä teidän, jotka tässä läsnä tänäpänä olette ja seisotte meidän kanssamme Herran meidän Jumalamme edessä, että myös niiden kanssa, jotka ei tässä tänäpänä meidän kanssamme ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Sillä te tiedätte, kuinka me asuimme Egyptin maalla, ja kuinka me vaelsimme pakanain lävitse, joiden kautta te vaelsitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Ja näitte heidän kauhistuksensa ja epäjumalansa, kannot ja kivet, hopiat ja kullat, jotka heidän tykönänsä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Ettei joku olisi teidän seassanne mies eli vaimo, elikkä perhe taikka sukukunta, jotka sydämensä tänäpänä kääntäis pois Herrasta meidän Jumalastamme, mennäksensä pois palvelemaan tämän kansan jumalia, ja tulis teille juureksi, joka kasvaa sappea ja koiruohoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Ja tapahtuisi, kuin hän kuulee nämät kirouksen sanat, että hän siunaa itsiänsä sydämestänsä, ja sanoo: rauha on minulla oleva, ehkä minä vaellan sydämeni ajatuksen jälkeen, sentähden että juopuneet janoovain kanssa hukutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Ei Herra ole hänelle armollinen, sillä silloin tulee suuri Herran viha ja kiivaus sen miehen päälle, ja kaikki nämät kiroukset, jotka tässä kirjassa ovat kirjoitetut, joutuvat hänen päällensä; ja Herra pyyhkii pois hänen nimensä taivaan alta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Ja Herra eroittaa hänen pahuuteen kaikesta Israelin suvusta, koko tämän liiton kirousten jälkeen, joka tässä lakikirjassa on kirjoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Niin jälkeentulevaiset sanovat, teidän lapsenne, jotka jälkeenne tulevat, ja vieraat, jotka kaukaiselta maalta tulevat, kuin he näkevät tämän maan rangaistukset ja sairaudet, joilla Herra lyö heitä siinä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Että hän on polttanut koko heidän maansa tulikivellä ja suolalla, niin ettei sitä kylvetä eikä se vihota, eikä myös yhtäkään ruohoa käy hänestä ylös, niinkuin Sodoma, Gomorra, Adama ja Zeboim olivat kukistetut maahan, jotka Herra vihassansa ja hirmuisuudessansa ylösalaisin kukisti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Niin kaikki kansat sanovat: miksi Herra niin teki tälle maakunnalle? mikä on tämä suuri hänen julmuutensa viha?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Silloin sanotaan: että he hylkäsivät Herran isäinsä Jumalan liiton, jonka hän teki heidän kanssansa, kuin hän heidät johdatti Egyptin maalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Ja ovat menneet ja muita jumalia palvelleet, ja kumartaneet niitä, senkaltaisia jumalia, joita ei he tunteneet, ja jotka ei heille mitään antaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Sentähden on Herran viha julmistunut tämän maan päälle, niin että hän antoi tulla heidän päällensä kaikki kiroukset, jotka tässä kirjassa kirjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Ja Herra on heidät hävittänyt heidän maastansa suuressa vihassa, julmuudessa ja närkästyksessä, ja on heidät heittänyt vieraasen maahan, niinkuin hän tänäpänä tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Niin salaiset asiat ovat Herran meidän Jumalamme edessä; mutta ne ilmoitetut ovat meillä ja meidän lapsillamme alati, että meidän kaikki nämät lain sanat tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Ja pitää tapahtuman, kuin kaikki nämät tulevat sinun päälles, siunaus eli kirous, jotka minä panin sinun etees, ja sinä rupeet ne panemaan sydämees, kaikkein pakanain keskellä, kuhunka Herra sinun Jumalas sinun on ajanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'Ja sinä käännyt Herran sinun Jumalas tykö, olemaan kuuliainen hänen äänellensä kaikissa niissä, mitkä minä sinulle tänäpänä käsken, sinä ja sinun lapses, kaikesta sydämestäs ja kaikesta sielustas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Niin Herra sinun Jumalas kääntää sinun vankiutes, ja armahtaa sinua, ja tuo jälleen ja kokoo sinun kaikista kansoista, joihin Herra sinun Jumalas sinun hajoittanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Jos sinä olisit ajettu taivaan ääriin, niin Herra sinun Jumalas kokoo sinun, ja tuo sinun sieltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Ja Herra sinun Jumalas johdattaa sinun siihen maahan, jonka isäs omistaneet ovat, ja sinä se omistat; ja hän tekee hyvää sinulle, ja enentää sinun enempi kuin sinun isäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Ja Herra sinun Jumalas ympärileikkaa sinun sydämes ja siemenes sydämen, rakastamaan Herraa sinun Jumalaas kaikesta sydämestäs ja kaikesta sielustas, ettäs eläisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Mutta kaikki nämät kiroukset antaa Herra sinun Jumalas tulla sinun vihollistes päälle, ja kaikkein niiden päälle, jotka sinua vihaavat ja vainoovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Ja sinä käännyt ja kuulet Herran äänen, tehdäkses kaikki hänen käskynsä, jotka minä sinulle tänäpänä käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Ja Herra sinun Jumalas antaa sinulle onnen kaikissa kättes töissä, kohtus hedelmässä, karjas hedelmässä, ja maas hedelmässä, että ne sinulle menestyisivät; sillä Herra kääntää itsensä riemuitsemaan sinusta sinulle hyväksi, niinkuin hän isistäs iloitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Ettäs Herran sinun Jumalas äänelle kuuliainen olet, ja pidät hänen käskynsä ja säätynsä, jotka ovat kirjoitetut tässä lakikirjassa, koskas palajat Herran sinun Jumalas tykö kaikesta sydämestäs ja kaikesta sielustas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Sillä tämä käsky, kuin minä sinulle tänäpänä käsken, ei ole sinulta salattu, eikä myös kaukana,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Eikä myös taivaassa, ettäs sanoisit: kuka astuu ylös taivaasen, ja tuo meille sen, kuullaksemme sitä ja tehdäksemme sen jälkeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Eikä myös ole tuolla puolella merta, ettäs sanoisit: kuka menis meren ylitse noutamaan meille sen, kuullaksemme sitä, ja tehdäksemme sen jälkeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Sillä se sana on sangen läsnä sinun tykönäs, sinun suussas, ja sinun sydämessäs, ettäs sen tekisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Katso, minä panin tänäpänä sinun etees elämän ja hyvän, niin myös kuoleman ja pahan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Siinä kuin minä tänäpänä käsken, ettäs rakastat Herraa sinun Jumalaas, ja vaellat hänen teissänsä, ja pidät hänen käskynsä, säätynsä ja oikeutensa; ettäs saisit elää ja enettäisiin, ja Herra sinun Jumalas siunais sinua siinä maassa, kuhunkas menet, sitä omistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mutta jos sinä käännät sydämes, ja et ole kuuliainen, vaan annat vietellä sinus, niin ettäs kumarrat vieraita jumalia ja palvelet heitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Niin teen minä teille tänäpänä tiettäväksi, että teidän pitää peräti hukkaantuman, ja ei kauvan pysymän siinä maassa, johonkas menet Jordanin ylitse, sitä omistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Minä otan tänäpänä taivaan ja maan todistajaksi teistä, että minä panin teidän eteenne elämän ja kuoleman, siunauksen ja kirouksen; niin valitse elämä, että sinä ja sinun siemenes eläisit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Ettäs rakastaisit Herraa sinun Jumalaas ja kuulisit hänen ääntänsä, ja riippuisit hänessä kiinni; sillä hän on sinun elämäs ja sinun pitkä ikäs, että pysyisit siinä maassa, jonka Herra isilles, Abrahamille, Isaakille ja Jakobille vannoi, heille antaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Ja Moses meni ja puhui nämät sanat koko Israelin kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Ja sanoi heille: minä olen tänäpänä sadan ja kahdenkymmenen ajastaikainen, en minä voi enää käydä ulos ja sisälle; siihen on Herra myös sanonut minulle: ei sinun pidä menemän tämän Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Herra sinun Jumalas käy itse sinun edelläs, hän itse hukuttaa nämät pakanat sinun edestäs, niin että sinä omistat heitä. Josua käy sinun edelläs sen ylitse, niinkuin Herra on sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Ja Herra tekee heille, niinkuin hän teki Sihonille ja Ogille Amorilaisten kuninkaille ja heidän maallensa, jotka hän on hukuttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Koska Herra antaa heidät teidän käteenne, niin tehkäät heidän kanssansa kaikkein käskyin jälkeen, jotka minä teille olen käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Olkaat vahvat ja hyvässä turvassa, älkäät peljästykö ja kauhistuko heidän edessänsä; sillä Herra sinun Jumalas itse vaeltaa sinun kanssas; ei hän jätä sinua, eikä hylkää sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Ja Moses kutsui Josuan, ja sanoi hänelle koko Israelin silmäin edessä: ole vahva ja hyvässä turvassa, sillä sinä johdatat tämän kansan siihen maahan, jonka Herra heidän isillensä vannonut on heille antaaksensa, ja sinä jaat tämän heille perimiseksi heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Mutta Herra, joka itse käy sinun edelläs, on sinun kanssas; ei hän jätä sinua, eikä myös hylkää sinua: älä pelkää, älä myös hämmästy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Ja Moses kirjoitti tämän lain ja antoi sen papeille, Levin pojille, jotka kantoivat Herran liitonarkkia, ja kaikille Israelin vanhimmille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Ja Moses käski heille ja sanoi: aina joka seitsemän vuoden perästä, kun vapaa vuosi alkaa, lehtimajan juhlana,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Kuin koko Israel tulee osoittamaan itsensä Herran sinun Jumalas eteen, siihen paikkaan, minkä hän valitsee, pitää sinun kuuluttaman tämän lain koko Israelin edessä heidän korvainsa kuullen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Kokoo kansa sekä miehet että vaimot, lapset ja muukalaiset, jotka sinun porteissas ovat, kuulemaan ja oppimaan ja pelkäämään Herraa teidän Jumalaanne, pitämään ja tekemään kaikki tämän lain sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Ja että heidän lapsensa, jotka ei sitä tiedä, kuulisivat myös ja oppisivat pelkäämään Herraa teidän Jumalaanne kaikkena teidän elinaikananne, kuin te elätte siinä maassa, johon te menette Jordanin ylitse sitä omistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Ja Herra sanoi Mosekselle: katso, sinun aikas, jona sinä kuolet, on juuri läsnä; kutsu Josua, ja seisokaat seurakunnan majassa, että minä antaisin hänelle käskyn. Ja Moses meni Josuan kanssa, ja he seisoivat seurakunnan majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Ja Herra ilmestyi majassa, pilven patsaassa, ja pilven patsas seisoi majan ovella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Ja Herra sanoi Mosekselle: katso, sinun pitää lepäämän isäis kanssa; ja tämä kansa nousee ja juoksee huoruuteen maan epäjumalain jälkeen, kuhun he menevät, hylkäävät minun, ja rikkovat sen liiton, jonka minä tein heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Niin minun vihani silloin julmistuu heidän päällensä, ja minä hylkään heitä ja peitän kasvoni heidän edestänsä, että he hukutetaan, ja paljo pahuutta ja ahdistusta käy heidän päällensä; ja he sanovat sinä päivänä: eikö nämät pahuudet ole tapahtuneet minulle, ettei minun Jumalani ole minun kanssani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Mutta minä peräti peitän kasvoni kasvoni sillä ajalla, kaiken sen pahuuden tähden, jonka he tehneet ovat, että he ovat itsensä kääntäneet muiden jumalain tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Niin kirjoittakaat nyt teillenne tämä virsi, ja opettakaat se Israelin lapsille, asettakaat se heidän suuhunsa, että tämä virsi olis minulle todistajaksi Israelin lapsia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Sillä minä johdata heidät siihen maahan, jonka minä vannoin heidän isillensä, joka rieskaa ja hunajaa vuotaa. Ja kuin he syövät ja tulevat ravituiksi ja lihavaksi, kääntävät he teitänsä muiden jumalain tykö, ja palvelevat niitä, ja pilkkaavat minua ja rikkovat minun liittoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Ja kuin suuri pahuus ja ahdistus käsittää heidät, niin tämä virsi vastaa heitä todistukseksi, sillä ei sitä pidä unhotettaman heidän siemenensä suussa; sillä minä tiedän heidän ajatuksensa, joita he tänäpänä ajattelevat, ennen kuin minä johdatan heitä siihen maahan, josta minä vannonut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Ja Moses kirjoitti tämän virren sinä päivänä, ja opetti sen Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Ja käski Josualle Nunin pojalle, ja sanoi: ole vahva ja urhoollinen, sillä sinä johdatat Israelin lapset siihen maahan, josta minä vannoin heille: ja minä olen sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Kuin Moses oli nämät lain sanat kirjoittanut kirjaan, ja ne lopettanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Käski hän Leviläisille, jotka Herran liitonarkkia kantoivat, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Ottakaat tämä lakikirja ja laskekaat Herran teidän Jumalanne liitonarkin sivulle, että se olis siinä todistukseksi sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Sillä minä tunnen sinun tottelemattomuutes ja niskuruutes: katso, tänäpänä minun vielä eläissäni teidän kanssanne, olette te tottelemattomat Herraa vastaan, kuinka paljo enemmin minun kuolemani jälkeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Niin kootkaat minun eteeni kaikki vanhimmat teidän sukukunnissanne ja teidän esimiehenne, että minä puhuisin nämät sanat heidän korvainsa kuullen ja ottaisin taivaan ja maan todistajaksi heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Sillä minä tiedän, että te minun kuolemani jälkeen peräti turmellaan, ja poikkeette siltä tieltä, jonka minä teille käskenyt olen; niin teille tapahtuu onnettomuus viimeisillä ajoilla, että teitte pahaa Herran silmäin edessä ja vihoititte hänen teidän kättenne töiden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Niin Moses puhui koko Israelin seurakunnan kuullen tämän veisun sanat hamaan loppuun asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Kuulkaat te taivaat, minä puhun, ja maa kuulkaan minun suuni sanoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Minun oppini tiukkukaan niinkuin sade, minun puheeni vuotakaan niinkuin kaste, niinkuin sade vihannon päälle ja niinkuin pisarat ruohon päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Sillä minä ylistän Herran nimeä: antakaat meidän Jumalallemme suuri kunnia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Hän on kallio, hänen työnsä ovat laittamattomat, sillä kaikki hänen tiensä ovat oikiat; vakaa on Jumala, ilman kaikkea vääryyttä, hän on vanhurskas ja oikia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Onko hän hänen turmellut? Ei, vaan hänen lapsensa ovat heidän häpiäpilkkunsa; se on nurja ja sekaseurainen suku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Niinköstä te Herralle maksatte, hullu ja tyhmä kansa? Eikö hän ole sinun Isäs ja sinun Lunastajas, joka sinun luonut ja valmistanut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Muista muinaisia aikoja, ymmärrä vuosikaudet suvusta sukuun; kysy isältäs, ja hän ilmoittaa sinulle, ja vanhimmiltas, niin he sinulle sanovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Kuin kaikkein korkein jakoi pakanat ja hajoitti ihmisten lapset, silloin hän laski kansain maan rajat, Israelin lasten luvun jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Sillä Herran osa on hänen oma kansansa, Jakob on hänen perimisensä nuora.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Hän löysi hänen erämaassa ja hirmuisessa suuressa itkukorvessa. Hän vei hänen ympäri, hän opetti hänen ymmärtämään ja varjeli häntä niinkuin silmäteräänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Niinkuin kotka kehoittelee pesäänsä ja laukuilee poikainsa päällä, levittää siipensä, ottaa kunkin heistä ja kantaa siipeinsä päällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Niin Herra yksinänsä talutti häntä, ja ei ollut hänen kanssansa muuta Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Hän vei hänen hamaan maan korkeuteen, ja ruokki hänen pellon hedelmällä, ja antoi hänen imeä hunajaa kalliosta ja öljyä kovasta kivestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Voita lehmistä, ja rieskaa lampaista, ynnä karitsain lihavuuden kanssa, ja Basanin oinaat, ja lihavat kauriit, ja parhaan nisun, ja juotti hänen parhaalla viinamarjan verellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Ja Israel lihoi, tuli vikuriksi, lihavaksi, paksuksi ja väkeväksi, ja hylkäsi Jumalan, joka hänen teki, ja katsoi autuutensa kallion ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'He yllyttivät hänen kiivauteen muukalaisten kautta, kauhistusten kautta vihoittivat he hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'He uhrasivat perkeleille, eikä Jumalalle, jumalille, joita ei he tunteneet, vasta-uutisille, jotka ei ennen olleet, joita isänne ei peljänneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Kallion, joka sinun siitti, sinä hyljäsit, ja unhotit Jumalan, joka sinun loi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Ja Herra näki sen, ja vihastui, poikainsa ja tyttäriensä kehoituksen tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Ja sanoi: minä peitän kasvoni heidän edestänsä, ja katson mitä heidän viimeiseltä tapahtuu; sillä se on nurja suku ja senkaltaiset lapset, joissa ei ole uskoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'He härsyttelivät minua sen kautta, joka ei ole jumala, epäjumaluutensa kautta ovat he minun vihoittaneet ja minä vihoitan heitä jälleen sen kautta, joka ei ole kansa, tyhmällä kansalla minä heitä vihoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Sillä tuli on syttynyt minun vihassani, ja polttaa hamaan alimaiseen helvettiin, ja kuluttaa maan, ynnä hänen hedelmänsä kanssa, ja polttaa vuorten perustukset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Minä kokoon kaiken onnettomuuden heidän päällensä, minä ammun kaikki nuoleni heihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Nälästä heidän pitää hiukahtuman ja poltetaudilla kulutettaman, ja äkillisellä kuolemalla; minä lähetän metsän petoin hampaat heidän keskellensä, ja kyykärmeen myrkyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Ulkona pitää miekan heitä hävittämän ja sisällä huoneessa pelvon, sekä nuorukaiset että neitseet, imeväiset ja harmaapäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Minä sanoin: minä hävittäisin heitä, minä lakkauttaisin heidän muistonsa ihmisistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Ellen minä vihollisteni vihaa karttaisi, ettei heidän vainollisensa ylpeilisi, ja lähes sanoisi: meidän oikia kätemme on kaikki nämät tehnyt, eikä Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Sillä se on kansa, jossa ei mitään neuvoa ole, eikä ymmärrystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Jospa he taitavaiset olisivat, niin he ymmärtäisivät ja huomaitsisivat, mitä heille viimeiseltä tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kuinka yksi ajais tuhatta takaa ja kaksi karkottaisi kymmenentuhatta heistä? Eikö sentähden, että heidän kallionsa on heidät myynyt? ja Herra on heidät sulkenut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Sillä ei ole meidän kalliomme niinkuin heidän kallionsa, ja meidän vihollisemme ovat meidän tuomarimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Sillä heidän viinapuunsa on Sodoman viinapuusta ja Gomorran pelloista, heidän viinamarjansa myrkylliset viinamarjat, heillä ovat karvahimmat marjat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Heidän viinansa on lohikärmeen kiukkuvahto, ja kyykärmetten hirmullinen myrkky.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Eikö se liene kätketty minun tykönäni? ja sinetillä lukittu minun tavaroissani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Minun on kosto, minä kostan, heidän jalkansa pitää ajallansa kompastuman; sillä heidän kadotuksensa aika on läsnä, ja mikä heille tarjontelee, se rientää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Sillä Herra tuomitsee kansansa, ja armahtaa palveliaansa; sillä hän näkee, että käsi on poissa, ja ei ole mitään tallella pidetty eikä jätetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Ja pitää sanottaman: kussa heidän Jumalansa ovat? heidän kallionsa, johonka he uskalsivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Joiden lihavimmat uhrit he söivät, ja joivat viinan heidän juomauhristansa, nouskaan ne ja auttakaan teitä ja varjelkaan teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Nähkäät nyt, että minä itse olen, ja ei ole jumalia minun kanssani. Minä kuoletan ja teen eläväksi, minä lyön ja minä parannan, ja ei kenkään ole, joka minun käsistäni vapahtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Sillä minä nostan käteni taivaasen ja sanon: minä elän ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Kuin minä hion miekkani niinkuin pitkäisen leimauksen, ja minun käteni rupee rangaistukseen, niin minä koston maksan minun vihollisilleni, ja niille palkitsen, jotka minua vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Minä juotan nuoleni verellä, ja miekkani pitää lihaa syömän tapettuiden verestä, ja vangittuiden ja vihollisten paljastetusta päästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Riemuitkaat te kaikki, jotka olette hänen kansansa; sillä hän kostaa palveliainsa veren. Ja kostaa vihollisillensa, ja sovittaa maansa ja kansansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Ja Moses tuli ja puhui kaikki nämät veisun sanat tämän kansan kuullen, hän ja Josua Nunin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Ja Moses päätti kaikki nämät sanat koko Israelille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Ja sanoi heille: pankaat sydämeenne kaikki ne sanat, jotka minä teille tänäpänä todistin, että te käskisitte teidän lapsianne, tekemään ja pitämään kaikki tämän lain sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Sillä ei siinä ole teille yhtään turhaa sanaa, vaan se on teidän elämänne; ja ne sanat pitentävät teidän ikänne maan päällä, johon te menette Jordanin ylitse, omistamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Ja Herra puhui Mosekselle sinä päivänä, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Mene tälle Abarimin vuorelle, Nebon vuorelle, joka on Moabin maalla Jerihon kohdalla, ja katsele Kanaanin maata, jonka minä Israelin lapsille omaksi annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Sinun pitää kuoleman vuorella, johonkas menet, ja koottaman kansas tykö, niinkuin veljeskin Aaron kuoli Horin vuorella, ja koottiin kansan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Että te olette rikkoneet minua vastaan Israelin lasten seassa, riitaveden tykönä Kadeksessa Sinin korvessa: ettette minua pyhittäneet Israelin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Sillä sinä näet maan kohdastansa; vaan ei sinun pidä siihen maahan tuleman, jonka minä Israelin lapsille annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Ja tämä on siunaus, jolla Moses Jumalan mies siunasi Israelin lapsia ennen kuolemaansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Ja sanoi: Herra on tullut Sinaista, ja noussut heille Seiristä, ja ilmestynyt Paranin vuorelta, ja on tullut kymmenentuhannen pyhän kanssa, ja tulinen laki hänen oikiassa kädessänsä heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Hän myös rakastaa kansoja; kaikki hänen pyhänsä ovat sinun kädessäs, ja he asettavat itsensä sinun jalkais juureen, ja ottavat opin sinun sanoistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Moses on meille käskenyt lain, Jakobin sukukunnalle perimisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Ja hän oli Kuningas oikeudessa; kansan päämiehet hän kokosi yhteen, ynnä Israelin sukukuntain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruben eläkään, ja älkään kuolko, ja hänen kansansa olkoon luettava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Tämä on Juudalle siunaus: ja hän sanoi: kuule Herra Juudan ääntä, ja johdata häntä kansansa tykö; ja hänen kätensä sotii puolestansa, sinä olet apu vastoin hänen vihollisiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Ja hän sanoi Leville: sinun täydellisyytes ja sinun valkeutes olkoon sinun pyhän miehes tykönä, jota sinä kiusasit Massassa, ja saatit hänen riitelemään riitaveden tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Joka sanoo isällensä ja äidillensä: en minä nähnyt heitä, ja ei tunne veljiänsä, eikä tiedä pojistansa; ne pitävät sinun sanas, ja kätkevät sinun liittos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'He opettavat sinun oikeuksias Jakobille ja Israelille sinun lakis, he kantavat suitsutusta sinun nenäs eteen, ja kaikkinaiset uhrit uhraavat sinun alttarillas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Siunaa Herra hänen voimansa ja anna hänen kättensä työ sinulle kelvata; riko heidän lanteensa, jotka karkaavat häntä vastaan ja häntä vihaavat, niin ettei he voisi ojentaa heitänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Ja BenJaminille sanoi hän: Herran rakkaat pitää asuman turvallisesti hänen tykönänsä; hän suojelee heitä kaiken päivän, ja hän asuu heidän hartioidensa välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Ja hän sanoi Josephille: hänen maansa olkoon siunattu Herralta, parhaista taivaan hedelmistä, kasteesta, ja syvyydestä, joka makaa alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Siinä olkoon ihanimmat hedelmät auringosta, ja ihanimmat kypsät hedelmät kuusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Ja itäisten vuorten kukkuloilta, ja ijäisiltä kukkuloilta parhaat hedelmät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Ja ne kalliimmat maan hedelmät, ja mitä siinä on. Hänen suosionsa, joka asuu pensaassa, tulkoon Josephin päähän, ja Natsirin päälaelle veljeinsä keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Ja hänen kauneutensa olkoon niinkuin esikoisen härjän, ja hänen sarvensa olkoon niinkuin yksisarvisen sarvet, joilla hän kansaa kuokkii yhteen, hamaan maailman ääriin asti; nämät ovat Ephraimin kymmenentuhatta, ja nämät Manassen tuhannet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Ja hän sanoi Sebulonille: iloitse Sebulon uloskäymisessäs, mutta sinä Isaskar iloitse majoissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Heidän pitää kutsuman kansaa vuorelle ja siellä vanhurskauden uhria uhraaman; sillä he imevät meren kyllyyden ja santaan kätketyt tavarat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Ja hän sanoi Gadille: siunattu olkoon se, joka levittää Gadin, hän asuu niinkuin hotka jalopeura, ja ryöstää sekä käsivarren että päänlaen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Ja hän katsoi itsellensä ensimäisen osan maasta, että hän siinä lainopettajalta annetussa osassa olis surutoin; kuitenkin tuli hän kansan päämiesten kanssa, ja teki Herran vanhurskautta, ja hänen oikiutensa Israelin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Ja Danille sanoi hän: Dan niinkuin jalopeuran penikka, joka karkaa Basanista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Ja Naphtalille sanoi hän: Naphtalilla on yltäkyllä, mitä hänen mielensä tekee, ja hän täytetään Herran siunauksella, lännen ja etelän pitää hänen omistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Ja Asserille sanoi hän: Asser olkoon siunattu pojissa, hän olkoon veljillensä otollinen, ja kastakaan jalkansa öljyyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Rauta ja vaski olkoon sinun kenkäs; ja niinkuin sinun ikäs, niin myös sinun väkevyytes lisääntyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ei yhtään ole niinkuin oikeuden Jumala, joka istuu taivaassa, hän olkoon sinun auttajas, ja hänen kunniansa on pilvissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Jumalan asuinsia on alusta, ijankaikkisten käsivartten alla. Ja hän ajaa ulos sinun vihollises sinun edestäs ja sanoo: ole hukutettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Israel asuu levollisesti yksinänsä, ja Jakobin silmä katsoo sen maan päälle, jossa jyviä ja viinaa on, siihen myös taivaat kastetta vuodattavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Autuas olet sinä Israel: kuka on sinun kaltaises? O sinä kansa, joka Herrassa autuaaksi tulet, joka sinun apus kilpi ja sinun kunnias miekka on. Vihollises valhettelevat sinulle, ja sinä astelet heidän kukkulainsa päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Ja Moses meni Moabin kedoilta ja astui Nebon vuorelle, Pisgan kukkulalle, joka on Jerihon kohdalla; ja Herra osoitti hänelle kaiken Gileadin maan Daniin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Ja koko Naphtalin ja Ephraimin ja Manassen maan, ja kaiken Juudan maan viimeiseen mereen asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Ja etelämaan, ja aukian kedon Palmukaupungin Jerihon tykönä, hamaan Zoariin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Ja Herra sanoi hänelle: tämä on se maa, jonka minä Abrahamille, Isaakille ja Jakobille vannoin ja sanoin: minä annan sen sinun siemenelles; sinä näit sen nyt silmilläs, vaan et sinä sinne tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Ja Moses Herran palvelia kuoli siellä Moabin maalla, Herran sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Ja hän hautasi hänen laaksoon, Moabin maalla, Peorin huoneen kohdalla. Ja ei ole yksikään saanut tietää hänen hautaansa tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Ja Moses oli sadan ja kahdenkymmenen ajastaikainen, kuin hän kuoli; ei hänen silmänsä olleet pimenneet, ja hänen elämänsä neste ei ollut lakastunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Ja Israelin lapset itkivät Mosesta Moabin kedoilla kolmekymmentä päivää; ja itku- ja valituspäivät Moseksesta täytettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Mutta Josua Nunin poika oli täytetty taidon hengellä, sillä Moses oli kätensä laskenut hänen päällensä; ja Israelin lapset olivat kuuliaiset hänelle ja tekivät niinkuin Herra oli Mosekselle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Ja sitte ei yhtään prophetaa noussut Israelissa niinkuin Moses, jonka Herra tunsi kasvoista niin kasvoihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Kaikkinaisissa tunnustähdeissa ja ihmeissä, joita Herra hänen lähetti tekemään Egyptin maalla Pharaolle ja kaikille hänen palvelioillensa, koko hänen maallensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Ja kaikessa väkevässä kädessä, ja kaikissa suurissa peljättävissä töissä, jotka Moses teki koko Israelin silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Ja tapahtui Moseksen Herran palvelian kuoleman jälkeen, että Herra puhui Josualle Nunin pojalle, Moseksen palvelialle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Minun palveliani Moses on kuollut; niin nouse nyt ja matkusta tämän Jordanin ylitse, sinä ja kaikki tämä kansa, siihen maahan, kuin minä annan Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Kaiken sian minä annan teille, kussa teidän jalkanne käyvät, niinkuin minä Mosekselle sanonut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Korvesta ja tästä Libanonista suuren Phratin virtaan asti, koko Hetiläisten maan, niin isoon mereen länteen päin, pitää teidän maanne rajat oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Ei kenkään voi sinua vastaan seisoa koko elinaikanas: niinkuin minä olin Moseksen kanssa, niin olen minä myös sinun kanssas; en minä hylkää sinua enkä luovu sinusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Ole rohkia ja vahvista sinuas, sillä sinun pitää tälle kansalle maan jakaman, josta minä vannoin heidän isillensä, sen heille antaakseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Ainoastaan ole rohkia ja vahvista sinuas juuri hyvin, ettäs pitäisit kaiken lain ja tekisit sen jälkeen, kuin Moses minun palveliani sinulle käski; älä siitä harhaile oikialle eikä vasemmalle puolelle, ettäs toimellisesti tekisit kaikissa missä sinä vaellat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Ei pidä tämän lakiraamatun tuleman sinun suustas pois, vaan ajattele sitä yötä ja päivää, ettäs kaikki sen jälkeen pitäisit ja tekisit, kuin siinä on kirjoitettu; sillä niin sinä menestyt kaikissa sinun teissäs ja kaikki työs toimellisesti päätät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Enkö minä käskenyt sinun olla rohkian ja vahvistaa itses? Älä pelkää, älä myös hämmästy, sillä Herra sinun Jumalas on sinun kanssas kaikissa sinun aivoituksissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Silloin käski Josua kansan päämiehiä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Käykäät leirin lävitse ja käskekäät kansaa, sanoen: valmistakaat teille evästä, sillä kolmannen päivän perästä pitää teidän käymän tämän Jordanin ylitse, että te joutuisitte maata omistamaan, jonka Herra teidän Jumalanne teille antaa omistaaksenne sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Ja Josua puhui Rubenilaisille, Gadilaisille ja puolelle Manassen sukukunnalle, sanoen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Muistakaat se sana, jonka Moses Herran palvelia teille käski, sanoen: Herra teidän Jumalanne saatti teidät lepoon ja antoi teille tämän maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Teidän emäntänne, lapsenne, ja karjanne jättäkäät siihen maahan, minkä Moses teille antoi, tällä puolella Jordania. Vaan teidän pitää käymän veljeinne edellä varustettuina, kaikki ne jotka vahvat miehet ovat, ja auttaman heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Siihenasti että Herra teidän veljillenne antaa levon, niinkuin teillekin, että hekin omistaisivat sen maan, jonka Herra teidän Jumalanne heille antaa; sitte pitää teidän palajaman omalle maallenne ja omistaman sen, minkä Moses Herran palvelia teille antoi, tällä puolella Jordania auringon nousemiseen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Ja he vastasivat Josualle ja sanoivat: kaikki mitä meille käskenyt olet, sen me teemme, ja kuhunkas ikänä lähetät meidät, sinne me menemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Niinkuin me olemme olleet Mosekselle kaikissa kuuliaiset, niin olemme sinullekin kuuliaiset; ainoastaan olkoon Herra sinun Jumalas sinun kanssas, niinkuin hän oli Moseksen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Jokainen, joka asettaa itsensä sinun suutas vastaan ja ei ole kuuliainen sinun sanoilles kaikissa mitä käsket, hänen pitää kuoleman; ainoastansa ole rohkia ja vahvista sinuas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Ja Josua Nunin poika lähetti salaisesti kaksi vakoojaa Sittimistä, sanoen: menkäät ja katselkaat maata ja Jerihoa. Niin he läksivät matkaan ja tulivat porton huoneeseen, jonka nimi oli Rahab, ja lepäsivät siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Mutta se ilmoitettiin Jerihon kuninkaalle, sanoen: katso, tänä yönä tulivat tänne miehet Israelin lapsista, vakoomaan maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Niin lähetti Jerihon kuningas Rahabin tykö, sanoen: tuo ne miehet ulos, jotka sinun tykös, sinun huoneesees tulivat, sillä he ovat tulleet vakoomaan kaikkea maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Mutta vaimo otti molemmat miehet ja kätki heidät, ja sanoi näin: miehet tulivat minun tyköni, vaan en minä tietänyt, kusta he olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Ja kuin portti pimeässä pantiin kiinni, niin ne miehet läksivät ulos; enkä minä tiedä, kuhunka he menivät. Ajakaat nopiasti heitä takaa, niin heidät saatte kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Mutta hän oli käskenyt heidän astua katon päälle ja oli peittänyt heidät pellavain varsilla, jotka hän oli hajoittanut katolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Ja miehet ajoivat heitä takaa, Jordanin tietä hamaan luotuspaikkaan; ja portti pantiin kiinni, sitte kohta kuin he läksivät, jotka heitä ajoivat takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Mutta ennen kuin miehet panivat levätä, meni hän katolle heidän tykönsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Ja sanoi miehille: minä tiedän, että Herra antaa teille tämän maan; sillä teidän pelkonne on langennut meidän päällemme, ja koko maan asuvaiset ovat hämmästyneet teidän kasvoinne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Sillä me olemme kuulleet, kuinka Herra kuivasi Punaisen meren vedet teidän edestänne lähteissänne Egyptistä, ja mitä te olette tehneet niille kahdelle Amorilaisten kuninkaalle, jotka olivat tuolla puolella Jordania, Sihonille ja Ogille, jotka te tapoitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Kuin me sen kuulimme, niin meidän sydämemme raukesi, ja ei ole yhdelläkään rohkeutta teidän edessänne; sillä Herra teidän Jumalanne on Jumala ylhäällä taivaissa ja alhaalla maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Niin vannokaat nyt minulle Herran kautta, sillä minä tein armon teidän kohtaanne, että te myös teette armon minun isäni huoneelle ja annatte minulle totuuden merkin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Että te jätätte elämään minun isäni, ja äitini, ja veljeni, ja sisareni, ja kaikki jotka heidän omansa ovat ja vapahdatte meidän sielumme kuolemasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Ja miehet sanoivat hänelle: meidän sielumme kuolkaan teidän edestänne, jolles vaan petä tätä meidän asiaamme, jollemme tee armoa ja totuutta sinua kohtaan, kuin Herra tämän maan meille antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Ja hän laski heidät köydellä akkunasta alas; sillä hänen huoneensa oli kaupungin muurissa, ja hän asui juuri muurissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Ja hän sanoi heille: menkäät vuorelle, ettei ne teitä kohtaisi, jotka ajavat teitä takaa, ja olkaat siellä lymyssä kolme päivää, niinkauvan että takaa-ajajat palajavat, ja menkäät sitte tietänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Ja miehet sanoivat hänelle: vapaat me olemme tästä valastas, jolla meitä vannotit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Katso, kuin maahan sisälle tulemme, niin sinun pitää ripustaman tämän punaisen köyden akkunaan, josta meidät laskit alas, ja sinun pitää kokooman tykös huoneesees isäs ja äitis ja veljes ja koko isäs huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Mutta jos joku käy huonees ovesta ulos, hänen verensä olkoon oman päänsä päällä, ja me olemme viattomat; ja joka ikänä sinun kanssas huoneessa on, hänen verensä olkoon meidän päämme päällä, jos jonkun käsi häneen sattuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Vaan jos sinä petät tämän meidän asiamme, niin me olemme vapaat sinun valastas, jolla meitä vannottanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Hän vastasi: olkoon niinkuin te sanotte; ja päästi heidät menemään, ja he menivät pois; ja hän ripusti punaisen köyden akkunaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Ja he menivät pois, ja tulivat vuorelle ja olivat siellä kolme päivää, niinkauvan että ne palasivat, jotka heitä ajoivat takaa, jotka etsivät heitä kaikilla teillä, ja ei löytäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Niin ne molemmat miehet palasivat, sittekuin he olivat astuneet vuorelta alas, menivät ylitse, ja tulivat Josuan Nunin pojan tykö ja juttelivat hänelle kaikki, mitä heille tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Ja he sanoivat Josualle: Herra on antanut meidän käsiimme koko maan, sillä kaikki maan asuvaiset ovat hämmästyneet meidän edessämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Ja Josua nousi aamulla varhain, ja he matkustivat Sittimistä ja tulivat Jordaniin asti, hän ja kaikki Israelin lapset ja he olivat siinä yötä ennenkuin he matkustivat ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Ja tapahtui kolmen päivän perästä, että päämiehet menivät leirin lävitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'Ja käskivät kansalle, sanoen: kuin te näette Herran teidän Jumalanne liitonarkin, ja papit Leviläiset kantavat sitä, niin matkustakaat te myös siastanne ja seuratkaat sitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Kuitenkin niin että teidän välillänne ja hänen on liki kahdentuhannen kyynärän pituus siaa; eikä teidän pidä tuleman häntä juuri lähes, että te tietäisitte tien, jota teidän pitää matkustaman; sillä ette ennen ole sitä tietä vaeltaneet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Ja Josua sanoi kansalle: pyhittäkäät teitänne, sillä huomenna tekee Herra ihmeellisen työn teidän keskellänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Ja Josua puhui papeille, sanoen: ottakaat liitonarkki ja menkäät kansan edellä; niin he ottivat liitonarkin ja menivät kansan edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Ja Herra sanoi Josualle: tänäpänä rupeen minä tekemään sinun suureksi koko Israelin edessä, että he tietäisivät, että niinkuin minä olin Moseksen kanssa, niin minä olen myös sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Ja käske pappeja, jotka kantavat liitonarkkia, ja sano: kuin te tulette Jordanin vetten ääreen, niin seisahtukaat Jordanissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Ja Josua sanoi Israelin lapsille: astukaat tänne ja kuulkaat Herran teidän Jumalanne sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Ja Josua sanoi: siitä tietäkäät elävän Jumalan olevan teidän seassanne, ja että hän kaiketi ajaa pois teidän edestänne Kanaanilaiset, Hetiläiset, Heviläiset, Pheresiläiset, Gergesiläiset, Amorilaiset ja Jebusilaiset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Katso, kaiken maailman hallitsian liitonarkki menee Jordanissa teidän edellänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Niin ottakaat nyt teille kaksitoistakymmentä miestä Israelin sukukunnista, jokaisesta sukukunnasta yksi mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Ja pitää tapahtuman, että kuin papit, jotka kantavat Herran, kaiken maailman hallitsian arkkia, laskevat jalkansa Jordanin veteen, niin se vesi, joka Jordanissa ylimmäiseltä puolelta juoksee, eroittaa itsensä, niin että se seisoo yhdessä läjässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Ja koska kansa läksi majoistansa menemään Jordanin yli, ja papit kantoivat liitonarkkia kansan edellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Ja kuin arkin kantajat tulivat Jordaniin, ja pappein, arkin kantajain jalat kastuivat veden syrjään, (ja Jordan oli täynnä partaaseen saakka kaiken elonajan).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Niin seisoi se vesi, joka ylimmäiseltä puolelta juoksee, koottuna yhdessä läjässä, sangen kaukana Adamin kaupungin puolessa, joka on Zartanin tykönä; mutta se vesi, joka juoksi alas korven mereen, nimittäin Suolaiseen mereen, väheni ja juoksi pois; niin meni kansa yli Jerihon kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Ja papit, jotka kantoivat Herran liitonarkkia, seisoivat kuivan päällä, asetetut Jordanin keskellä ja koko Israel kävi kuivan päällä sen lävitse, siihenasti että kaikki kansa tuli Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Ja kun kaikki kansa oli tullut Jordanin yli, puhui Herra Josualle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Ottakaat teillenne kansasta kaksitoistakymmentä miestä, jokaisesta sukukunnasta yksi mies,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Ja käskekäät heitä, sanoen: ottakaat teille keskeltä tätä Jordania, siitä paikasta, jossa pappein jalat seisovat alallansa, kaksitoistakymmentä kiveä, ja viekäät ne kanssanne ylitse ja jättäkäät ne siihen majaan, jossa te tätä yötä pidätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Niin kutsui Josua kaksitoistakymmentä miestä, jotka hän oli valmistanut Israelin lapsista, jokaisesta sukukunnasta yhden miehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Ja Josua sanoi heille: menkäät Herran teidän Jumalanne arkin edellä keskelle Jordania, ja jokainen nostakaan yhden kiven olallensa, Israelin lasten sukukuntain luvun jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Että ne olisivat merkiksi teidän seassanne, kuin teidän lapsenne tästedes kysyvät ja sanovat: mihinkä nämät kivet teille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Että silloin sanoisitte heille: Jordanin vesi jakausi Herran liitonarkin edestä; sen mennessä Jordanin ylitse jakausi Jordanin vesi; ja nämät kivet pitää oleman Israelin lapsille ijankaikkiseksi muistoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Niin Israelin lapset tekivät niinkuin Josua heitä käski, ja kantoivat kaksitoistakymmentä kiveä keskeltä Jordania, niinkuin Herra oli Josualle sanonut, Israelin lasten sukukuntain luvun jälkeen, ja he veivät ne yli myötänsä yösiaan asti ja panivat ne siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Ja Josua pystytti myös kaksitoistakymmentä kiveä keskellä Jordania, kussa pappein jalat seisoneet olivat, jotka liitonarkkia kantoivat; ja ne ovat siellä tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Ja papit, jotka arkkia kantoivat, seisoivat keskellä Jordania, siihenasti kuin kaikki toimitettiin, mitä Herra käski Josuan kansalle sanoa, kaiken sen jälkeen minkä Moses Josualle käskenyt oli; ja kansa kiiruhti itsensä ja kävi ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Kuin kaikki kansa oli käynyt ylitse, meni myös Herran arkki ylitse, ja papit kansan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Ja Rubenilaiset ja Gadilaiset ja puoli Manassen sukukuntaa kävivät aseinensa Israelin lasten edellä, niinkuin Moses heille sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Liki neljäkymmentä tuhatta sotaan hankittua kävivät Herran edellä sotaan Jerihon kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Sinä päivänä teki Herra Josuan suureksi koko Israelin edessä; ja he pelkäsivät häntä, niinkuin he pelkäsivät Mosesta, kaikkena hänen elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Ja Herra puhui Josualle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Käske pappein, jotka kantavat todistuksen arkkia, astua Jordanista ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Niin käski Josua pappeja, ja sanoi: astukaat ylös Jordanista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Ja kuin papit, jotka Herran liitonarkkia kantoivat, astuivat Jordanista ylös, ja pappein jalat kävivät ylös kuivalle maalle, niin tulivat Jordanin vedet siallensa ja juoksivat niinkuin ennenkin parrastensa yli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Ja se oli kymmenes päivä ensimäisessä kuussa, kuin kansa astui Jordanista ylös, ja siottivat itsensä Gilgalissa idän puolella Jerihoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Ja ne kaksitoistakymmentä kiveä, jotka he ottivat Jordanista, pani Josua Gilgalissa pystyälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Ja hän puhui Israelin lapsille, sanoen: kuin teidän lapsenne tästedes kysyvät isiltänsä, ja sanovat: mihinkä nämät kivet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Niin antakaat lastenne tietää, sanoen: Israel kävi kuivalla tämän Jordanin yli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Kuin Herra teidän Jumalanne kuivasi Jordanin vedet teidän edestänne, niinkauvan kuin te kävitte sen ylitse, niinkuin Herra teidän Jumalanne teki Punaisessa meressä, jonka hän kuivasi meidän edestämme, siihenasti että me kävimme sen ylitse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Että kaikki kansat maan päällä tuntisivat Herran käden, kuinka väkevä se on, että te pelkäisitte aina Herraa teidän Jumalaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Kuin kaikki Amorilaisten kuninkaat, jotka toisella puolella Jordania länteen päin asuivat, ja kaikki Kanaanealaisten kuninkaat meren tykönä kuulivat, että Herra kuivasi Jordanin vedet Israelin lasten eteen, niinkauvan kuin he kävivät sen ylitse, niin heidän sydämensä raukesi ja ei ollut heissä enään yhtään miehuutta Israelin lasten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Siihen aikaan sanoi Herra Josualle: tee sinulles kiviveitset ja ympärileikkaa taas Israelin lapset toisen kerran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Niin teki Josua itsellensä kiviveitset ja ympärileikkasi Israelin lapset Aralotin kukkulalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Ja tämä on syy, jonkatähden Josua heidät siinä ympärileikkasi: kaikki se kansa joka läksi ulos Egyptistä, miehenpuoli, kaikki sotamiehet kuolivat tiellä korvessa, sitte kuin he läksivät Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Sillä kaikki kansa, joka läksi ulos, oli ympärileikattu: mutta kaikki se kansa, joka korvessa syntyi matkalla, sittekuin he läksivät ulos Egyptistä, ei ollut ympärileikattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Sillä Israelin lapset vaelsivat neljäkymmentä ajastaikaa korvessa, siihenasti että kaikki kansa sotamiehiä, jotka Egyptistä lähteneet olivat, loppuivat, jotka ei kuulleet Herran ääntä; niinkuin Herra heille vannonut oli, ettei heidän pitänyt näkemän sitä maata, jonka Herra heidän isillensä vannonut oli, antaaksensa meille maan, rieskaa ja hunajaa vuotavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Heidän lapsensa, jotka heidän siaansa tulivat, ympärileikkasi Josua; sillä heillä oli esinahka, ja ei olleet ympärileikatut matkalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Ja kuin kaikki kansa ympärileikattu oli, pysyivät he siallansa leirissä siihenasti että he paranivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Ja Herra sanoi Josualle: tänäpänä olen minä teiltä kääntänyt pois Egyptin häväistyksen; ja se paikka kutsutaan Gilgal, tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Ja kuin Israelin lapset niin sioittivat itsensä Gilgalissa, pitivät he pääsiäistä neljäntenätoistakymmenentenä päivänä sinä kuukautena, ehtoona, Jerihon kedolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Ja söivät sen maan jyvistä toisena pääsiäispäivänä, happamattomia leipiä ja paistetuita tähkäpäitä, juuri sinä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Ja manna lakkasi toisena päivänä, sittekuin he syöneet olivat maan jyvistä, niin ettei Israelin lapsilla enää ollut mannaa, vaan he söivät Kanaanin maan hedelmää sinä vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Ja tapahtui kuin Josua oli lähellä Jerihoa, nosti hän silmänsä ja näki: ja katso, mies seisoi siellä hänen edessänsä, ja oli avoin miekka hänen kädessänsä; ja Josua meni hänen tykönsä ja sanoi hänelle: oletko sinä meidän vai vihamiestemme puolella?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Hän sanoi: en, vaan minä olen Herran sotajoukon päämies, ja olen nyt tullut; niin Josua lankesi maahan kasvoillensa ja kumarsi häntä, ja sanoi hänelle: mitä Herrani sanoo palveliallensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Ja Herran sotajoukon päämies sanoi Josualle: riisu kengät jaloistas, sillä paikka, jossa seisot, on pyhä; ja Josua teki niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Ja Jeriho oli suljettu ja visusti varustettu Israelin lasten edestä, niin ettei yksikään taitanut tulla ulos eli sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Mutta Herra sanoi Josualle: katso, minä olen antanut Jerihon, ja hänen kuninkaansa, väkevät sotajoukot, sinun kätees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Käykäät ympäri kaupunkia kaikki sotamiehet, ja piirittäkäät kaupunki kerta ympäri; ja tee niin kuusi päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Ja seitsemän pappia ottakaan seitsemän riemuvuoden basunaa arkin eteen, ja seitsemäntenä päivänä käykäät seitsemän kertaa kaupungin ympäri, ja papit soittakaan basunilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Ja kuin he soittavat riemuvuoden basunaa pitkään, ja te kuulette basunan äänen, niin nostakaan kaikki kansa suuren äänen ja huutakaan; ja niin kaupungin muuri hajoo itsestänsä, ja kansa astuu sinne sisälle itsekukin kohdastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Niin kutsui Josua Nunin poika papit ja sanoi heille: kantakaat liitonarkki, ja seitsemän pappia kantakaan seitsemän riemuvuoden basunaa Herran arkin edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Mutta kansalle sanoi hän: menkäät matkaan ja käykäät kaupungin ympäri, ja se, joka sota-aseilla varustettu on, käykään Herran arkin edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Ja kuin Josua nämät kansalle sanonut oli, niin ottivat ne seitsemän pappia seitsemän riemuvuoden basunaa, ja kävivät Herran arkin edellä, ja soittivat basunilla, ja Herran liitonarkki seurasi heitä heidän jälissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Ja ne, jotka sota-aseilla hankitut olivat, kävivät pappein edellä ja soittivat basunilla; vaan yhteinen kansa seurasi arkkia, ja soitettiin basunilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Mutta Josua käski kansaa ja sanoi: ei teidän pidä huutaman eikä antaman teidän ääntänne kuulla eli sanaa lausuman suustanne, siihen päivään asti kuin minä sanon teille: huutakaat, niin antakaat kuulla sodan ääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Niin kävi Herran arkki kaupungin ympäri, piirittäen sen yhden kerran; ja he tulivat leiriin ja pitivät yötä leirissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Ja Josua nousi huomeneltain varhain, ja papit kantoivat Herran arkkia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'ne seitsemän pappia kantoivat ne seitsemän riemuvuoden basunaa Herran arkin edellä, ja käyden alati soittivat basunaa; ja jokainen, joka sota-aseilla hankittu oli, kävi heidän edellänsä, vaan yhteinen kansa kävi Herran arkin jälissä, basunain soidessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Kävivät he myös toisena päivänä kerran kaupungin ympäri ja tulivat leiriin jälleen; ja sitä he tekivät kuusi päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Ja tapahtui seitsemäntenä päivänä, kuin huomenrusko kävi ylös, nousivat he varhain ja kävivät entisellä tavalla seitsemän kertaa kaupungin ympäri; ja sinä päivänä ainoastaan kävivät he seitsemän kertaa kaupungin ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Ja seitsemännellä kerralla, kuin papit soittivat basunaa, sanoi Josua kansalle: huutakaat, sillä Herra antoi teille kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Mutta kaupunki ja kaikki mitä siinä on, pitää oleman kirottu Herralle; ainoastaan portto Rahab pitää elämään jäämän, hän ja kaikki, jotka hänen kanssansa huoneessa ovat; sillä hän kätki sanansaattajat, jotka me lähetimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Ainostaan karttakaat kirottua, ettette itsiänne saattaisi kiroukseen, jos jotakin kirotusta otatte, te saatatte Israelin leirin kirouksen ja onnettomuuden alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Mutta kaikki hopia ja kulta, vaski- ja rautakalu olkaan Herralle pyhitetyt ja tulkaan Herran tavarahuoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Ja kansa huusi ja soitettiin basunaa; sillä kaikki kansa, jotka kuulivat basunan äänen, huusivat suurella äänellä, ja muuri hajosi itsestänsä; ja kaikki kansa itsekukin kohdastansa astui kaupunkiin, ja he voittivat kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Ja hukuttivat kaikki jotka kaupungissa olivat miekan terällä, sekä miehet että vaimot, nuoret ja vanhat, karjan, ja lampaat ja aasit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Ja Josua sanoi niille kahdelle miehelle, jotka maata vaonneet olivat: menkäät porton huoneeseen ja johdattakaat vaimo sieltä ulos, ja kaikki mitä hänellä on, niinkuin te olette hänelle vannoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Niin nuoret miehet, jotka maata vaonneet olivat, menivät sinne ja toivat Rahabin ulos, ja hänen isänsä, ja äitinsä, ja veljensä, ja kaikki mitä hänellä oli; niin myös kaiken hänen sukunsa toivat he ulos ja sioittivat heidät ulkoiselle puolelle Israelin leiriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Mutta kaupungin he polttivat tulella ja kaikki mitä siellä oli; ainoastaan hopian, kullan, vasken ja rautakalun panivat he tavaraksi Herran huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Mutta porton Rahabin, ja hänen isänsä huoneen ja kaikki mitä hänellä oli, antoi Josua elää; ja hän asui Israelin seassa tähän päivään asti, että hän kätki sanansaattajat, jotka Josua Jerihoa vakoomaan lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Silloin vannoi Josua ja sanoi: kirottu olkoon se mies Herran edessä, joka nousee ja rakentaa tämän Jerihon kaupungin; koska hän laskee siihen perustuksen, niin kadottakoon esikoisensa, ja koska hän rakentaa sen portit, niin kadottakoon nuorimman poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Ja Herra oli Josuan kanssa, ja hän tuli kuuluisaksi kaikissa maakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Mutta Israelin lapset horjahtivat kovin kirotussa kalussa; sillä Akan Karmin poika, Saddin pojan, Seran pojan, Juudan sukukunnasta, otti jotakin kirottua, niin julmistui Herran viha Israelin lasten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Ja Josua lähetti miehiä Jerihosta Aihin päin, joka on BetAvenin tykönä itäänpäin Betelistä, ja puhui heille, sanoen: menkäät ja vaotkaat maata; niin he menivät ja vakosivat Ain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Sitte palasivat he jälleen Josuan tykö ja sanoivat hänelle: älä anna kaikkea kansaa sinne mennä, mutta vaivoin kaksi eli kolmetuhatta miestä menkään ja lyökään Ain, ettei kaikkea kansaa hukkaan sinne vaivattaisi; sillä he ovat harvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Niin meni sinne kansasta liki kolmetuhatta miestä, ja he pakenivat Ain kaupungin miesten edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Ja ne miehet Aista löivät heistä liki kuusineljättäkymmentä miestä, ja ajoivat heitä portista takaa Sabarimiin asti, ja löivät heitä tiellä paetessa; niin kansan sydän hämmästyi ja tuli niinkuin vesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Ja Josua repäisi vaatteensa ja hän lankesi maahan kasvoillensa Herran arkin eteen hamaan ehtooseen asti, hän ja Israelin vanhimmat; ja he heittivät tomua päänsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Ja Josua sanoi: Ah Herra, Herra, miksis tämän kansan annoit olleenkaan tulla Jordanin ylitse, antaakses meitä Amorilaisten käsiin, hukuttaakses meitä? jospa me olisimme tyytyneet ja pysähtyneet sille puolelle Jordania!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Voi minun Herrani, mitä minun pitää sanoman, että Israel selkänsä kääntää vihollistensa puoleen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Kuin Kanaanealaiset ja kaikki maan asuvaiset sen kuulevat, niin he piirittävät meidät ja hävittävät meidän nimemme maan päältä; mitäs siis teet sinun suurella nimelläs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Niin sanoi Herra Josualle: nouse, miksi niin makaat kasvoillas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel on syntiä tehnyt ja rikkonut minun liittoni, jonka minä käskin heille, ja ottivat kirottua, ja varastivat, ja valhettelivat, ja panivat kaluinsa sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Ei Israelin lapset voi seisoa vihamiestensä edessä, vaan kääntävät selkänsä vihollistensa puoleen; sillä he ovat kirouksessa. En minä enää ole teidän kanssanne, jollette hukuta kirottua teidän keskeltänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Nouse, ja pyhitä kansa ja sano: pyhittäkäät teitänne huomeneen saakka; sillä näin sanoo Herra Israelin Jumala: kirous on sinun keskelläs Israel, sentähden et sinä ole seisovainen vihamiestes edessä, siihenasti kuin te kirouksen siirrätte pois teidän seastanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Ja teidän pitää varhain huomeneltain käymän edes teidän sukukuntainne jälkeen: ja jonka sukukunnan päälle Herran arpa lankee, sen pitää käymän edes perhekuntainsa jälkeen: ja jonka perhekunnan päälle Herran arpa lankee, sen pitää käymän edes huonettensa jälkeen: ja jonka huoneen päälle Herran arpa lankee, pitää käymän edes kukin perheenisäntä toinen toisensa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Ja pitää tapahtuman, että joka löydetään ryhtyneeksi johonkuhun kirottuun kaluun, se pitää tulella poltettaman ja kaikki mitä hänellä on, että hän Herran liiton on rikkonut ja tehnyt hulluuden Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Niin nousi Josua varhain huomeneltain ja toi Israelin edes, yhden sukukunnan toisen jälkeen; ja arpa lankesi Juudan sukukunnan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Ja kuin hän Juudan sukukunnan toi edes, lankesi arpa Serahilaisten perhekunnalle, ja kuin hän toi Serahilaisten perhekunnan edes, yhden perheenisännän toisen jälkeen, lankesi arpa Saddille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Ja kuin hän toi edes hänen huoneensa miesluvun jälkeen, niin lankesi arpa Akanille, Karmin pojalle, Saddin pojan, Seran pojan, Juudan sukukunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Ja Josua sanoi Akanille: minun poikani, anna Herralle Israelin Jumalalle kunnia ja anna hänelle ylistys, ja ilmoita minulle mitäs teit, ja älä salaa sitä minulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Silloin vastasi Akan Josualle ja sanoi: totisesti olen minä syntiä tehnyt Herraa Israelin Jumalaa vastaan: niin ja niin minä tein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Minä näin saaliissa yhden kalliin Babelin hameen, ja kaksisataa sikliä hopiaa, ja kultaisen kielen, joka painoi viisikymmentä sikliä, joita minun mieleni teki, ja minä otin ne; ja katso, se on kaivettu maahan keskellä minun majaani ja hopia sen alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Niin Josua lähetti sinne sanansaattajat, ja ne juoksivat majaan; ja katso, se oli kaivettu hänen majaansa ja hopia sen alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Ja he ottivat ne majasta, ja veivät ne Josuan ja kaikkein Israelin lasten tykö, ja panivat ne Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Niin otti Josua ja koko Israel hänen kanssansa Akanin Seran pojan, ja hopian, ja hameen, ja kultaisen kielen, hänen poikansa ja tyttärensä, hänen härkänsä, aasinsa ja lampaansa, hänen majansa ja kaikki mitä hänen omansa oli, ja veivät ne Akorin laaksoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Ja Josua sanoi: miksis meitä murheelliseksi saatit? saattakoon Herra sinun murheelliseksi tänäpäivänä. Ja koko Israel kivitti heitä kuoliaaksi, ja polttivat heidät tulella sitte kuin he olivat heidän kivittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Ja sitte tekivät he suuren kiviroukkion heidän päällensä, joka vielä on tähän päivään asti. Niin lakkasi Herran vihan julmuus. Siitä kutsutaan se paikka Akorin laaksoksi tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Ja Herra sanoi Josualle: älä pelkää, älä myös vapise: ota kanssas kaikki sotaväki, ja nouse ja mene ylös Aihin; katso, minä annan Ain kuninkaan kansoinensa, kaupunkinensa ja mainensa sinun kätees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Ja sinun pitää tekemän Aille ja sen kuninkaalle niinkuin sinä teit Jeriholle ja sen kuninkaalle; ainoasti hänen saaliinsa ja karjansa jakakaat keskenänne, ja pane väijyjät kaupungin taa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Niin Josua nousi kaiken sotaväen kanssa menemään ylös Aihin, ja Josua valitsi kolmekymmentä tuhatta väkevää sotamiestä ja lähetti heidät yöllä ulos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Ja käski heitä ja sanoi: katsokaat te, jotka väijytte kaupunkia kaupungin takana, ettette kauvas mene kaupungista, mutta olkaat kaikki valmiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Ja minä ja kaikki kansa, joka minun kanssani on, lähestymme kaupunkia. Ja kuin he tulevat ulos meitä vastaan niinkuin ennenkin, niin me pakenemme heidän edellänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Että he tulisivat meidän jälkeemme niinkauvan, että me saisimme heidät eroitetuksi kaupungista; sillä he sanovat: he pakenevat meidän edellämme niinkuin ennenkin; ja me pakenemme heidän edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Silloin te nouskaat väijymästä ja ottakaat kaupunki; sillä Herra teidän Jumalanne antaa sen teidän käteenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Ja kuin te olette saaneet kaupungin, sytyttäkäät siihen tuli ja tehkäät Herran sanan jälkeen; katsokaat, minä olen sen käskenyt teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Niin Josua lähetti heidät, ja he menivät sinne väijymään ja pidättivät BetElin ja Ain välillä, lännen puolella Aista; mutta Josua yötyi kansan keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Ja Josua nousi varhain ja asetti kansan, ja hän meni ylös ja Israelin vanhimmat Aihin kansan edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Ja kaikki sotaväki, jotka hänen tykönänsä olivat, menivät, kävivät edes ja tulivat kaupungin kohdalle ja sioittivat itsensä pohjan puolelle Aista; ja laakso oli heidän ja Ain välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Mutta hän otti liki viisituhatta miestä ja pani ne väijymään BetElin ja Ain välillä, lännen puolella kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Ja he asettivat koko leirin kansan, joka pohjan puolella kaupunkia oli, niin että ne viimeiset ulottuivat lännen puolelta kaupunkiin; niin Josua meni sinä yönä keskelle sitä laaksoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Kuin Ain kuningas sen näki, kiiruhti hän, ja varhain huomeneltain valmisti itsensä ja kaupungin miehet menivät ulos Israelia vastaan sotaan, kuningas itse kaiken väkensä kanssa, määrätyllä ajalla, lakialle kedolle; mutta ei hän tietänyt itsiänsä väijyttävän kaupungin takana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Mutta Josua ja kaikki Israel teeskelivät heidän edessänsä niinkuin he olisivat lyödyt ja pakenivat tietä myöten korpeen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Niin kaikki kansa, joka kaupungissa oli, huusi että heitä piti ajettaman takaa, ja he myös ajoivat Josuaa takaa ja eroitettiin kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Niin ettei yhtäkään miestä jäänyt Aihin ja BetEliin, joka ei mennyt ulos Israelin perässä: ja he jättivät kaupungin avoin ja ajoivat Israelia takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Niin sanoi Herra Josualle: ojenna keihääs, joka on kädessäs Ain puoleen, sillä minä annan sen sinun kätees. Ja Josua ojensi keihäänsä, joka oli hänen kädessänsä, kaupungin puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Silloin väijyjät kiiruusti nousivat siastansa ja juoksivat, sittekuin hän ojensi kätensä, ja tulivat kaupunkiin ja voittivat sen; ja kiiruhtivat heitänsä ja sytyttivät kaupungin palamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Ja Ain miehet kääntyivät ja katsoivat taaksensa, ja näkivät savun nousevan kaupungista taivaaseen. Ja ei ollut heillä siaa paeta ei sinne eikä tänne; ja se kansa, joka pakeni korpeen päin, palasi niitä vastaan, jotka heitä takaa ajoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Kuin Josua ja koko Israel näkivät, että väijyjät voittivat kaupungin ja että savu nousi kaupungista, palasivat he ja löivät Ain miehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Ja jotka kaupungissa olivat, menivät ulos heitä vastaan, niin he tulivat keskelle Israelia molemmilta puolilta; ja he löivät heitä siihenasti ettei yhtään heistä elämään jäänyt, eikä myös päässyt pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Ja Ain kuninkaan ottivat he elävänä kiinni ja veivät hänen Josuan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Ja kuin Israel oli lyönyt kuoliaaksi kaikki Ain asujat kedolla ja korvessa, johonka he heitä ajoivat takaa, ja he lankesivat kaikki miekan terällä, siihenasti että he loppuivat; niin koko Israel palasi Aihin ja löi kaiken sen miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Ja kaikki ne, jotka lankesivat sinä päivänä sekä miehistä että vaimoista, heitä oli kaksitoistakymmentä tuhatta, kaikki Ain kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Ja ei Josua kättänsä vetänyt puoleensa, jolla hän oli ojentanut keihään, siihenasti kuin hän oli tappanut kaikki Ain asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Mutta kaupungin karjan ja saaliin jakoi Israel keskenänsä, Herran sanan jälkeen, niinkuin hän oli käskenyt Josualle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Ja Josua poltti Ain ja teki siitä kiviraunion ijankaikkiseksi, joka vielä autiona on tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Ja antoi hirttää Ain kuninkaan puuhun ehtooseen asti; ja kuin päivä oli laskenut, käski hän ottaa hänen ruumiinsa puusta pois, ja he heittivät sen kaupungin portin eteen ja kokosivat suuren kiviraunion hänen päällensä, joka siellä on vielä nyt tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Silloin rakensi Josua Herralle Israelin Jumalalle alttarin Ebalin vuorella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Niinkuin Moses Herran palvelia Israelin lapsille käskenyt oli, niinkuin Moseksen lakikirjassa kirjoitettu on: alttarin kokonaisista kivistä, joihinka ei ole rauta sattunut. Ja he uhrasivat Herralle sen päällä polttouhria ja kiitosuhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Ja hän kirjoitti siellä kiviin sen lain muodon, jonka Moses Israelin lapsille kirjoittanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Ja koko Israel vanhimpainsa, päämiestensä ja tuomareinsa kanssa seisoivat molemmilla puolilla arkkia pappein Leviläisten edessä, jotka kantoivat Herran liitonarkkia, niin muukalaiset kuin kotonakin syntyneet, puoli heitä Grisimin vuoren kohdalla ja toinen puoli Ebalin vuoren kohdalla, niinkuin Moses Herran palvelia käskenyt oli ensisti siunaamaan Israelin kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Sitte kuulutti hän kaikki lain sanat, siunauksen ja kirouksen, kaiken sen jälkeen kuin kirjoitettu on lakikirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Ei ollut yhtäkään sanaa kaikista mitä Moses käskenyt oli, jota ei Josua kuuluttanut koko Israelin seurakunnan edessä, vaimoin ja lasten ja muukalaisten, jotka olivat heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Ja kuin kaikki kuninkaat sen kuulivat, jotka sillä puolella Jordania olivat vuorilla ja laaksoissa ja kaikissa ison meren satamissa, Libanonin vuoren kohdalla: Hetiläiset, ja Amorilaiset, Kanaanilaiset, Pheresiläiset, Heviläiset ja Jebusilaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Kokoontuivat he yhteet, sotimaan Josuaa ja Israelia vastaan yksimielisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Kuin Gibeonin asuvaiset kuulivat, mitä Josua teki Jeriholle ja Aille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Niin ajattelivat he petoksen, menivät ja teeskelivät itsensä sanansaatajiksi, ja ottivat vanhat säkit aaseinsa päälle, ja vanhat kuluneet ja ravistuneet viinaleilit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Ja vanhat paikatut kengät jalkoihinsa ja vanhat ja rikkinäiset vaatteet yllensä, ja kaikki leivät, jotka he ottivat myötänsä, olivat kovat ja homehtuneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Ja menivät leiriin Josuan tykö Gilgaliin ja sanoivat hänelle ja kaikelle Israelille: me olemme kaukaiselta maalta tulleet, tehkäät nyt liitto meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Niin sanoi koko Israel Heviläisille, mitämaks sinä asut meidän seassamme, kuinka me teemme liiton sinun kanssas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'He sanoivat Josualle: me olemme sinun palvelias. Ja Josua sanoi heille: kutka te olette ja kusta te tulette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'He sanoivat hänelle: palvelias ovat sangen kaukaiselta maalta tulleet Herran sinun Jumalas nimen tähden; sillä me olemme kuulleet hänen sanomansa ja kaikki mitä hän Egyptissä on tehnyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'Ja kaikki mitä hän on tehnyt kahdelle Amorilaisten kuninkaalle, jotka olivat sillä puolella Jordania: Sihonille Hesbonin kuninkaalle ja Ogille Basanin kuninkaalle, joka asui Astarotissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Sentähden sanoivat meille meidän vanhimmat ja kaikki meidän maan asuvaiset: ottakaat evästä myötänne, ja menkäät heitä vastaan ja sanokaat heille: me olemme teidän palvelianne, tehkäät liitto kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Tämä leipämme, jonka me myötämme evääksi otimme kotoamme, oli vielä tuore, kuin me läksimme tulemaan teidän tykönne, mutta katso, tämä on nyt kova ja homehtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Ja nämät viinaleilit me täytimme uusina, ja katso, ne ovat kuluneet, ja nämät vaatteemme ja kenkämme ovat vanhaksi tulleet, aivan pitkän matkan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Niin ottivat päämiehet heidän eväästänsä ja ei kysyneet Heran suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Ja Josua teki rauhan heidän kanssansa ja teki liiton heidän kanssansa, että he saisivat elää; ja kansan päämiehet vannoivat heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Mutta kolmen päivän jälkeen, sitte kuin he tekivät liiton heidän kanssansa, kuulivat he, että he olivat läsnä heitä ja asuivat heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Kuin Israelin lapset matkustivat, tulivat he kolmantena päivänä heidän kaupunkeihinsa, jotka kutsutaan Gibeon, Kephira, Beerot ja KirjatJearim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Ja ei Israelin lapset lyöneet heitä; sillä kansan päämiehet olivat vannoneet heille Herran Israelin Jumalan kautta. Ja kaikki kansa napisi päämiehiä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Niin sanoivat kaikki kansan päämiehet kaikelle joukolle: me olemme vannoneet heille Herran Israelin Jumalan kautta, ja sentähden emme heihin taida ruveta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Mutta sen me teemme heille: antakaamme heidän elää, ettei viha tulisi valan tähden meidän päällemme, jonka me heille vannoneet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Ja päämiehet sanoivat heille: antakaamme heidän elää, että he olisivat halkoin hakkaajat ja veden kantajat kaikelle kansalle, niinkuin päämiehet heille sanoneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Niin Josua kutsui heitä ja puhui heille, ja sanoi: miksi te olette pettäneet meidät ja sanoneet: me asumme aivan kaukana teistä; ja kuitenkin te asutte meidän seassamme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Sentähden pitää teidän kirotut oleman, niin ettei teiltä pidä orjat puuttuman, jotka halkoja hakkaaman ja vettä kantaman pitää minun Jumalani huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'He vastasivat Josuaa ja sanoivat: se on todella sanottu sinun palvelioilles, että Herra sinun Jumalas on käskenyt palveliansa Moseksen antaa teille kaiken tämän maan ja hävittää teidän edestänne kaikki maan asuvaiset; niin me suuresti pelkäsimme henkeämme teidän edessänne ja teimme tämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Mutta katso, me olemme nyt sinun kädessäs: mikä sinulle näkyy oikiaksi eli hyväksi meille tehdäkses, se tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Ja hän teki heille niin ja vapahti heitä Israelin lasten kädestä, ettei he lyöneet heitä kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Niin teki Josua heidät sinä päivänä halkoin hakkaajiksi ja veden kantajiksi seurakunnalle ja Herran alttarille tähän päivään asti, siihen paikkaan jonka hän valitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Kuin Jerusalemin kuningas AdoniZedek kuuli Josuan voittaneeksi Ain ja hävittäneeksi sen, ja niin tehneeksi Aille ja hänen kuninkaallensa, kuin hän teki Jeriholle ja hänen kuninkaallensa, ja että Gibeonin asuvaiset olivat tehneet rauhan Israelin kanssa ja asuivat heidän seassansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Pelkäsivät he sangen suuresti; sillä Gibeon oli suuri kaupunki, niinkuin joku kuninkaallinen kaupunki ja suurempi kuin Ai, ja kaikki hänen asuvaisensa olivat vahvat sotamiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Niin lähetti AdoniZedek Jerusalemin kuningas Hohamin Hebronin kuninkaan tykö, ja Pireamin Jarmutin kuninkaan tykö, ja Japhian Lakiksen kuninkaan tykö ja Deberin Eglonin kuninkaan tykö, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Tulkaat ylös minun tyköni ja auttakaat minua ja lyökäämme Gibeon; sillä he tekivät rauhan Josuan ja Israelin lasten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Silloin kokoontuivat ja menivät ylös viisi Amorilaisten kuningasta, Jerusalemin kuningas, Hebronin kuningas, Jarmutin kuningas, Lakiksen kuningas, Eglonin kuningas, he ja kaikki heidän leirinsä ja piirittivät Gibeonin ja sotivat sitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Mutta Gibeonin miehet lähettivät Josuan tykö leiriin Gilgaliin, sanoen: älä ota kättäs pois palvelioiltas, tule nopiasti ylös meidän tykömme, ja vapahda meitä ja auta meitä; sillä kaikki Amorilaisten kuninkaat, jotka asuvat vuorilla, ovat kokoontuneet meitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Ja Josua meni ylös Gilgalista, ja kaikki sotaväki hänen kanssansa, ja kaikki vahvat sotamiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Ja Herra sanoi Josualle: älä heitä mitään pelkää; sillä minä annan heidät sinun käsiis: ei yksikään heistä ole seisovainen sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Niin Josua tuli äkisti heidän päällensä; sillä hän matkusti kaiken yötä Gilgalista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Ja Herra peljätti heitä Israelin edessä, ja löi heitä suurella lyömisellä Gibeonissa, ja ajoi heitä takaa sitä tietä jota ylös BetHoroniin mennään, ja löi heitä Asekaan ja Makkedaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Ja kuin he Israelin edellä pakenivat alas BetHoronin tietä, antoi Herra taivaasta tulla suuret kivet heidän päällensä Asekaan asti, niin että he kuolivat; ja paljo enempi heistä kuoli raekivien kautta, kuin Israelin lapset miekalla löivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Silloin puhui Josua Herralle sinä päivänä, jona hän antoi Amorilaiset Israelin lasten eteen, ja sanoi Israelin läsnä ollessa: aurinko, seiso alallas Gibeonissa ja kuu Ajalonin laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Ja aurinko ja kuu seisahtivat, siihenasti kuin kansa kosti vihamiehensä. Eikö tämä ole kirjoitettu hurskaan kirjassa? Niin seisoi aurinko keskellä taivasta ilman laskemata koko päivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Ja ei ole yksikään päivä ollut senkaltainen ei ennen eikä sitte, kuin Herra miehen äänen kuuli; sillä Herra soti Israelin puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Ja Josua meni jälleen leiriin Gigaliin ja koko Israel hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Mutta ne viisi kuningasta pakenivat ja lymyivät luolaan Makkedassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Niin Josualle ilmoitettiin sanoen: ne viisi kuningasta ovat löydetyt, kätketyt luolaan Makkedassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Ja Josua sanoi: vierittäkäät suuret kivet luolan suulle ja asettakaat miehet heitä vartioitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Mutta älkäät te alallanne seisoko, vaan ajakaat teidän vihamiehiänne takaa ja lyökäät heidän viimeisiänsä; älkäät salliko heitä tulla kaupunkeihinsa, sillä Herra teidän Jumalanne on antanut heidät teidän käsiinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Ja kuin Josua ja Israelin lapset lopettivat sen ylen suuren tapon ja peräti olivat heidät surmanneet, ja jääneet pääsivät heistä ja tulivat vahvoihin kaupunkeihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Niin tuli kaikki kansa jälleen leiriin Josuan tykö Makkedaan rauhassa, ja ei kenkään rohjennut Israelin lasten edessä hiiskuakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Mutta Josua sanoi: avatkaat luolan suu ja tuokaat ne viisi kuningasta luolasta minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'He tekivät niin ja toivat ulos ne viisi kuningasta hänen tykönsä luolasta: Jerusalemin kuninkaan, Hebronin kuninkaan, Jarmutin kuninkaan, Lakiksen kuninkaan, Eglonin kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Ja kuin nämät kuninkaat olivat tuodut Josuan eteen, kutsui Josua kaikki Israelin miehet ja sanoi sotajoukon päämiehille, jotka hänen kanssansa matkustivat: tulkaat tänne ja tallatkaat näiden kuningasten kaulat; ja he tulivat, ja tallasivat heidän kaulansa jaloillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Ja Josua sanoi heille: älkäät peljätkö, älkäät myös vavisko, vahvistakaat itsenne ja olkaat rohkiat; sillä näin tekee Herra kaikille vihamiehillenne, joita vastaan te soditte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Ja Josua löi heidät sitte, ja surmasi heidät, ja ripusti viiteen puuhun; ja he riippuivat puissa hamaan ehtooseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Ja kuin aurinko laski, käski Josua heitä, ja he ottivat heidät puista alas ja heittivät luolaan, johonka he itsensä lymyttivät, ja panivat suuret kivet luolan suulle, jotka siellä vielä tänäpänä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Sinä päivänä voitti myös Josua Makkedan, ja löi sen miekan terällä, ja hänen kuninkaansa tappoi, ja kaikki ne sielut, jotka hänessä olivat, eikä yhtäkään jättänyt, ja teki Makkedan kuninkaalle niinkuin hän teki Jerihon kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Niin vaelsi Josua ja koko Israel hänen kanssansa Makkedasta Libnaan ja soti Libnaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Ja Herra antoi myös sen Israelin käsiin heidän kuninkaansa kanssa, ja hän löi sen miekan terällä ja kaikki ne sielut, jotka siellä olivat, eikä ketään elämään jättänyt, ja teki heidän kuninkaallensa niinkuin hän teki Jerihon kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Sitte matkusti Josua ja koko Israel hänen kanssansa Libnasta Lakikseen, ja piiritti sen ja soti sitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Ja Herra antoi myös Lakiksen Israelin käsiin, niin että hän voitti sen toisena päivänä ja löi sen miekan terällä ja kaikki ne sielut jotka siinä olivat, juuri niinkuin hän oli Libnalle tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Siihen aikaan meni Horam Jeserin kuningas auttamaan Lakista; mutta Josua löi hänen kaiken joukkonsa kanssa, siihenasti ettei yhtäkään jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Ja Josua meni Lakiksesta ja koko Israel hänen kanssansa Egloniin, ja piirittivät sen ja sotivat sitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Ja voittivat sen sinä päivänä, ja löivät miekan terällä, ja surmasivat kaikki sielut, jotka siellä olivat, sinä päivänä, juuri niinkuin hän oli tehnyt Lakikselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Sitte meni Josua ja koko Israel hänen kanssansa Eglonista ylös Hebroniin, ja he sotivat sitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Ja voittivat sen ja löivät sen miekanterällä, ja hänen kuninkaansa kaikkein kaupunkeinsa kanssa ja kaikki sielut, jotka siellä olivat, eikä yhtäkään jättänyt, juuri niinkuin hän oli tehnyt Eglonille; ja tappoi sen ja kaikki sielut, jotka siellä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Silloin palasi Josua ja koko Israel hänen kanssansa Debiriin ja soti sitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Ja voitti sen kuninkainensa ja kaikki hänen kaupunkinsa, ja löi ne miekan terällä, ja tappoi kaikki sielut, jotka siellä olivat, ja ei ketäkään jättänyt; niinkuin hän oli Hebronille tehnyt, niin teki hän myös Debirille ja hänen kuninkaallensa, ja niinkuin hän oli tehnyt Libnalle ja hänen kuninkaallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Niin Josua löi kaikki maan asuvaiset vuorilta, ja lounamaasta, ja laaksoista, ja ojain tyköä, ja kaikki heidän kuninkaansa, eikä yhtäkään jättänyt, vaan tappoi kaikki, joilla henki oli, niinkuin Herra Israelin Jumala oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Ja Josua tappoi heidät, ruveten KadesBarneasta Gasaan asti, ja koko Gosenin maakunnan Gibeoniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Ja Josua voitti kaikki nämät kuninkaat maakuntinensa yhdellä rupeemisella; sillä Herra Israelin Jumala soti Israelin puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Ja Josua palasi leiriin Gilgaliin ja koko Israel hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Ja tapahtui, että kuin Jobin Hatsorin kuningas sen kuuli, lähetti hän Jobabin Madonin kuninkaan tykö, ja Simronin kuninkaan, ja Akasaphin kuninkaan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Ja niiden kuningasten tykö, jotka asuivat pohjan puolella vuorella, ja lakeudella, meren puolella Kinerotista, ja laaksoissa, ja Dorin Naphotissa meren puolella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Kanaanealaisten tykö idän ja lännen puoleen, Amorilaisten, Hetiläisten, Pheresiläisten ja Jebusilaisten tykö vuorelle, niin hyös Heviläisten tykö alapuolella Hermonin vuorta Mitspan maakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Ja nämät läksivät kaiken sotajoukkonsa kanssa, joka oli sangen suuri kansan paljous, niinkuin santa meren rannalla paljouden tähden, ja sangen monta hevosta ja vaunua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Kaikki nämät kuninkaat kokoontuivat ja he tulivat ja sioittivat heitänsä yhteen Meromin vetten tykönä, sotimaan Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Ja Herra sanoi Josualle: älä heitä ensinkään pelkää, sillä huomenna tällä ajalla minä annan heidät kaikki lyötynä Israelin kansan eteen; heidän hevosensa pitää sinun rivinomaksi tekemän ja heidän vaununsa tulella polttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Ja Josua tuli ja kaikki sotajoukko hänen kanssansa äkisti heidän päällensä, Meromin vetten tykönä, ja karkasivat heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Ja Herra antoi heidät israelin käsiin, ja he löivät heitä, ja ajoivat heitä takaa isoon Zidoniin asti, ja lämpimään veteen asti, ja Mitspan ketoon asti, itään päin, ja löivät heitä siihenasti, ettei yksikään heistä jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Niin teki myös Josua heille, niinkuin Herra oli hänelle käskenyt, ja teki rivinomaksi heidän hevosensa ja poltti heidän vaununsa tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Ja Josua palasi sillä ajalla ja voitti Hatsorin ja löi hänen kuninkaansa miekalla; sillä Hatsor oli ennen kaikkein näiden valtakuntain pääkaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Ja he löivät kaikki ne sielut, jotka siellä olivat, miekan terällä, ja tappoivat, niin ettei yhtäkään jäänyt, jolla henki oli, ja poltti Hatsorin tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Ja kaikkein niiden kuningasten kaupungit voitti Josua, kaikkein heidän kuningastensa kanssa, ja löi heitä miekan terällä, ja tappoi heidät, niinkuin Moses Herran palvelia käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Mutta Israelin lapset ei polttaneet yhtäkään kaupunkia, jotka seisoivat töyräillänsä, paitsi ainoaa Hatsoria, jonka Josua poltti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Ja kaiken saaliin ja eläimet, jotka he näistä kaupungeista olivat ottaneet, jakoivat Israelin lapset keskenänsä. Ainoasti kaikki ihmiset tappoivat he miekan terällä, siihenasti että he hukuttivat heidät, niin ettei yhtäkään elävää henkeä jäänyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Niinkuin Herra palveliallensa Mosekselle käskenyt oli, ja Moses oli Josualle käskenyt. Ja niin Josua teki, ettei niistä yhtäkään tekemätä jäänyt, mitä Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Ja Josua otti kaiken tämän maakunnan, vuorimaan, ja kaiken Etelämaan, ja kaiken Gosenin maan ja kedot sekä myös laaksot, ja Israelin vuoret laaksoinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Siitä sileästä vuoresta, joka menee ylös Seiriin päin BaalGadiin asti Libanonin laaksossa, Hermonin vuoren alapuolella: kaikki heidän kuninkaansa voitti hän, löi ja tappoi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Kauvan aikaa soti Josua kaikkein näiden kuningasten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Ei ollut yhtäkään kaupunkia, joka rauhalla itsensä antoi Israelin lasten alle, paitsi Heviläisiä, jotka asuivat Gibeonissa; mutta kaikki he ottivat sodalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Ja se tapahtui niin Herralta, että heidän sydämensä oli niin paatunut, että he kohtasivat Israelin sodalla, että hän heidät tappais, ja ei yhtäkään armoa heille tapahtuisi, vaan että hän hukuttais heidät, niinkuin Herra Mosekselle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Siihen aikaan tuli Josua ja hävitti Enakilaiset vuorelta, Hebronista, Debiristä, Anabista ja kaikilta Juudan vuorilta ja kaikilta Israelin vuorilta, ja tappoi heidät kaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Ja ei antanut yhtäkään Enakilaista jäädä Israelin lasten maalle, paitsi Gasassa, Gatissa ja Asdodissa, joihin he jäivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Ja niin Josua otti kaiken maakunnan, peräti niin kuin Herra Mosekselle oli sanonut, ja antoi Israelille perinnöksi, kullekin sukukunnalle osansa; ja maakunta lakkasi sotimasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Ja nämät ovat maan kuninkaat, jotka Israelin lapset löivät, ja ottivat heidän maansa tuolla puolella Jordania, auringon nousemista päin, Arnonin ojasta Hermonin vuoreen asti, ja kaikki lakeudet itään päin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon Amorilaisten kuningas, joka asui Hesbonissa ja hallitsi Aroerista, joka on Arnonin ojan reunalla, ja keskellä ojaa, ja puolen Gileadia Jabbokin ojaan asti, joka on Ammonin lasten raja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Ja lakeutta Kinneretin mereen asti itään päin, ja korven mereen, Suolaiseen mereen itään päin, BetJesimotin tietä myöten, ja lounaasta alaspäin lähelle Asdot Pisgaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Siihen myös Ogin Basanin kuninkaan maan rajat, joka vielä jäänyt oli uljaista, ja asui Astarotissa ja Edreissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Ja hallitsi Hermonin vuorella, Salkassa ja koko Basanissa, Gessurin ja Maakatin maan rajoihin, ja puolen Gileadia, joka Sihonin Hesbonin kuninkaan maan raja oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Moses Herran palvelia ja Israelin lapset löivät heitä; ja Moses Herran palvelia antoi sen Rubenilaisille, Gadilaisille ja puolelle Manassen sukukunnalle omaisuudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Nämät ovat maan kuninkaat, jotka Josua löi ja Israelin lapset tällä puolella Jordania länteen päin, BaalGadista Libanonin vuorenlakeudella, sileään vuoreen, joka ulottuu Seiriin, jonka Josua Israelin sukukunnille antoi omaisuudeksi itsekullekin osansa jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Vuorilla, laaksoissa, lakeudella, vetten tykönä, korvessa, ja lounaan puolessa: Hetiläiset, Amorilaiset, Kanaanealaiset, Pheresiläiset, Heviläiset ja Jebusilaiset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Jerihon kuningas, yksi; Ain kuningas, joka BetElin sivussa on, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Jerusalemin kuningas, yksi; Hebronin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Jarmutin kuningas, yksi; Lakiksen kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Eglonin kuningas, yksi; Geserin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Debirin kuningas, yksi; Gederin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Horman kuningas, yksi; Aradin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Libnan kuningas, yksi; Adullamin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Makkedan kuningas, yksi; BetElin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Tapuan kuningas, yksi; Hepherin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Aphekin kuningas, yksi; Lassaronin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Madonin kuningas, yksi; Hatsorin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'SimronMeronin kuningas, yksi; Aksaphin kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Taanakin kuningas, yksi; Megiddon kuningas, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Kedeksen kuningas, yksi; Jokneamin kuningas Karmelin tykönä, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'DornaphatDorin kuningas, yksi, ja pakanain kuningas Gilgalissa, yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Tirtsan kuningas, yksi. Ne kaikki ovat yksineljättäkymmentä kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Kuin Josua vanheni ja ijälliseksi tuli, sanoi Herra hänelle: sinä olet vanhentunut ja ijälliseksi tullut, ja maata on vielä aivan paljo jäänyt omistamata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Tämä on se jälellä oleva maa: kaikki Philistealaisten maan ääret ja koko Gessuri,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Sihorista, joka juoksee Egyptin editse, Ekronin maan ääriin asti, pohjan puoleen, jotka luetaan Kanaanealaisille; ne viisi Philistealaisten päämiestä ovat: Gasilainen, Asdonilainen, Asklonilainen, Gatilainen, Ekronilainen ja Avilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Mutta eteläänpäin ovat kaikki Kanaanealaisten maat ja Meara, joka on Zidonilaisten, Aphekiin saakka ja hamaan Amorilaisten maan ääriin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Ja myös Gibiläisten maa, ja koko Libanon auringon nousemiseen päin, BaalGadista Hermonin vuoren alta, siihenasti kuin Hamatiin tullaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Kaikki jotka vuorella asuvat, Libanonista lämpimään veteen asti, ja kaikki Zidonilaiset: minä ajan ne Israelin lasten edestä pois; ainoasti jaa ne Israelille perimiseksi, niinkuin minä olen sinulle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Niin jaa nyt tämä maa yhdeksän sukukunnan välillä perimiseksi, ja puolelle Manassen sukukunnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Sillä Rubenilaiset ja Gadilaiset ovat toisen puolen Manassen sukukunnan kanssa saaneet perimisensä, jonka Moses heille oli antanut sillä puolella Jordania itään päin, niinkuin Herran palvelia Moses heille sen antanut oli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Aroerista, joka on Arnonin ojan reunalla, ja siitä kaupungista, joka on ojan keskellä, ja koko Medeban lakeuden Diboniin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'Ja kaikki Sihonin Amorilaisten kuninkaan kaupungit, joka hallitsi Hesbonissa, Ammonin lasten maan rajoihin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Ja Gileadin ja Gessurin ja Maakatin maan ääret, ja koko Hermonin vuoren, ja koko Basanin Salkaan asti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Koko Ogin Basanin kuninkaan valtakunnan, joka hallitsi Astarotissa ja Edreissä, joka vielä jäänyt oli uljaista, ja Moses löi heitä ja ajoi heitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Mutta Israelin lapset ei ajaneet Gessurilaisia ja Maakatilaisia ulos, vaan Gessurilainen ja Maakatilainen asuu Israelin lasten seassa tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Mutta Leviläisten sukukunnalle ei hän antanut yhtään perimistä; sillä Herran Israelin Jumalan polttouhri on heidän perintönsä, niinkuin hän heille sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Ja Moses antoi Rubenin lasten suvulle, heidän sukukuntainsa jälkeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Että heidän rajansa oli Aroerista, joka on Arnonin ojan reunalla, ja se kaupunki ojan keskellä kaiken sen tasaisen kedon kanssa Medeban tykönä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbonin kaupunkeinensa, jotka ovat tasaisella kedolla: Dibonin, BamotBaalin ja BetBaalMeonin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jaksan, Kedemotin, Mephaotin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjataimin, Sibman, Zeretin, Saharin laakson, vuorilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Ja BetPeorin, ne ojat Pisgan tykönä ja BetJesimotin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Ja kaikki lakeuden kaupungit, ja koko Sihonin, Amorilaisten kuninkaan valtakunnan, joka hallitsi Hesbonissa, jonka Moses löi, niin myös Midianin päämiehet: Evin, Rekemin, Zurin, Hurin ja Reban, Sihonin päämiehet, jotka maassa asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Ja Bileaminkin Beorin pojan, tietäjän, Israelin lapset miekalla kuoliaaksi löivät muita tapettaessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Ja Rubenin lasten raja oli Jordani rajoinensa. Tämä on Rubenin lasten perimys heidän sukukuntainsa, kaupunkeinsa ja kyläinsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Ja Moses antoi Gadin lasten sukukunnalle heidän sukukuntainsa jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Että heidän rajansa oli Jaeser, ja kaikki Gileadin kaupungit, ja puoli Ammonin lasten maata, Aroeriin asti, joka on Rabban kohdalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'Ja Hesbonista RamatMitspeen ja Betoniimiin asti, ja Mahanaimista Debirin rajaan asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Ja laaksossa Betaram ja BetNimra, Sukkot ja Zaphon, joka jäi Sihonin Hesbonin kuninkaan valtakunnasta; joiden raja oli Jordani Kinneretin meren ääreen asti, toisella puolella Jordania itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Tämä on Gadin lasten perimys heidän sukukunnissansa, kaupungeissansa ja kylissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Ja Moses antoi puolelle Manassen lasten suvulle sen mikä puolelle Manassen sukukunnalle tuli, heidän sukukuntainsa jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Että heidän rajansa oli Mahanaimista koko Basan, koko Ogin Basanin kuninkaan valtakunta ja kaikki Jairin kylät, jotka ovat Basanissa, kuusikymmentä kaupunkia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Ja puolen Gileadia ja Astarotia, Edreiä Ogin valtakunnan kaupungit Basanissa (antoi hän) Makirin Manassen pojan lapsille, toiselle puolelle Makirin lapsia heidän sukukuntainsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Tämä on se minkä Moses antoi Moabin kedoilla, sillä puolella Jordania, Jerihon kohdalla itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Mutta Levin sukukunnalle ei antanut Moses yhtään perimystä; Herra Israelin Jumala on heidän perimisensä, niinkuin hän heille sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Ja nämät ovat ne mitkä Israelin lapset ovat perimiseksi saaneet Kanaanin maalla, jonka heille perinnöksi jakoi pappi Eleatsar ja Josua Nunin poika ja Israelin lasten sukukuntain ylimmäiset isät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Ja he jakoivat sen heillensä arvalla, niinkuin Herra oli käskenyt Moseksen käden kautta, yhdeksälle sukukunnalle ja puolelle sukukunnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Sillä Moses oli antanut puolelle kolmatta sukukunnalle perimisen tuolla puolella Jordania. Mutta Leviläisille ei hän antanut yhtään perimistä heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Sillä Josephin lasten oli kaksi sukukuntaa, Manasse ja Ephraim; sentähden ei he Leviläisille yhtään osaa antaneet maakunnassa, vaan kaupungit heidän asuaksensa, ja esikaupungit, joissa heidän karjansa ja kalunsa oleman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Niinkuin Herra oli Mosekselle käskenyt, niin tekivät Israelin lapset, ja jakoivat maakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Silloin menivät Juudan lapset Josuan tykö Gilgalissa, ja Kaleb Jephunnen poika Kenisiläinen sanoi hänelle: sinä tiedät, mitä Herra sanoi Jumalan miehelle Mosekselle minun ja sinun puolestas KadesBarneassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Minä olin neljänkymmenen ajastaikainen, kuin Moses Herran palvelia minun lähetti KadesBarneasta vakoomaan maata, ja minä sanoin hänelle jälleen vastauksen sydämeni jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Mutta veljeni, jotka minun kanssani menneet olivat, saattivat kansalle vapisevaisen sydämen; mutta minä seurasin Herraa minun Jumalaani uskollisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Ja Moses vannoi sinä päivänä ja sanoi: se maa, jonka päälle sinä jaloillas olet astunut, on sinun ja sinun lastes perittävä ijankaikkisesti, ettäs Herraa minun Jumalaani uskollisesti seurannut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Ja nyt katso, Herra on antanut minun elää, niinkuin hän sanonut oli. Tämä on viides ajastaika viidettäkymmentä sittekuin Herra näitä sanoi Mosekselle, kuin Israel vaelsi korvessa. Ja katso, minä olen tänäpäivänä viiden ajastajan vanha yhdeksättäkymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Ja olen vielä tänäpäivänä niin väkevä, kuin minä sinä päivänä olin, jona Mosen minun lähetti; niinkuin väkevyyteni oli siihen aikaan, niin on se vielä nyt vahva sotimaan, käymään ulos ja sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Niin anna nyt minulle tämä vuori, josta Herra sanoi sinä päivänä, sillä sinä kuulit sen siihen aikaan. Ja Enakilaiset asuvat siellä, ja siellä ovat suuret ja vahvat kaupungit; jos Herra on minun kanssani, että minä ajaisin heidät pois, niinkuin Herra on sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Ja Josua siunasi häntä ja antoi Kalebille Jephunnen pojalle Hebronin perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Siitä oli Hebron Kalebin Jephunnen pojan Kenisiläisen perimys tähän päivään asti, että hän on uskollisesti seurannut Herraa Israelin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Mutta Hebron kutsuttiin muinaiseen aikaan KirjatArba, joka oli suurin mies Enakilaisten seassa; ja maakunta lakkasi sotimasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Juudan lasten suvun arpa heidän huonettensa jälkeen oli Edomin maan rajaan, Sinin korven puoleen, joka etelän puoleen on, lounaan maan äärestä asti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Niin että heidän lounainen maan rajansa oli Suolameren äärestä, se on, siitä lahdesta, joka menee etelään päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Ja käy sieltä ylöspäin Akrabiin, ja käy Sinin lävitse, ja menee ylöspäin merestä KadesBarneaan, ja menee Hetsronin lävitse, ja käy ylös Adariin päin, ja kääntyy ympäri Karkaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Ja menee Atsmonin ohitse, ja tulee Egyptin ojaan, niin että sen maan rajan ääri on meri. Tämä pitää oleman teille maan raja lounaaseen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Vaan raja itään päin on Suolainen meri Jordanin suuhun asti; vaan raja pohjan puoleen on siitä meren lahdesta, joka on Jordanin ääressä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Ja menee ylös BetHoglaan, ja vetäytyy pohjasta BetAraban puoleen, ja menee ylös Rubenin pojan Bohenin kiven tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Ja raja käy ylös Debirin tykö Akorin laaksosta, ja pohjan puoleen Gilgaliin päin, joka on Adumimin paltan kohdalla, joka etelän puoleen on ojan vieressä; sitte se menee EnSemeksen vedelle, ja menee Rogelin lähteelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Sitte menee raja Hinnomin pojan laaksoon, Jebusilaisen ohitse lounaan päin, se on Jerusalem; ja raja menee vuoren kukkulan ylitse, joka on Hinnomin laakson edessä, meren tykö, joka on Rephaimin laakson äärellä pohjaan päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Sitte käy se siitä vuoren kukkulasta Nephtoan lähteen tykö, ja menee Ephronin vuoren kaupunkein tykö, ja kääntyy Baalaan päin, joka on KirjatJearim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Ja menee Baalasta ympäri länteen päin Seirin vuoren tykö, ja menee ulos pohjan puolesta Jearin vuoren vieritse, se on Kessalon, ja tulee alas BetSemeksen tykö, ja menee Timnaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Ja tulee ulos Ekronin vieritse pohjan puolelle, ja vetää hänensä Sikroniin asti, ja menee Baalan vuoren ylitse, ja tulee Jabneeliin, että hänen äärensä loppu on meri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Mutta raja länteen päin on suuri meri. Tämä on Juudan lasten maan raja, joka taholta ympäri heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Mutta Kalebille Jephunnen pojalle annettiin osa Juudan lasten keskellä, niinkuin Herra oli käskenyt Josualle, nimittäin KirjatArba, Enakilaisten isän kaupunki, se on Hebron.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Ja Kaleb ajoi sieltä pois kolme Enakin poikaa, Sesain, Akimananin ja Talmain, Enakin sikiät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Ja meni sieltä ylös Debirin asuvaisten tykö; vaan Debir kutsuttiin muinen KirjatSepher.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Ja Kaleb sanoi: joka lyö KirjatSepherin ja voittaa sen, hänelle annan minä tyttäreni Aksan emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Niin voitti sen Otniel, Kenaksen Kalebin veljen poika; ja hän antoi tyttärensä Aksan hänelle emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Ja tapahtui, kuin hän tuli, että hän neuvoi miestänsä anomaan peltoa isältänsä, ja hän astui aasin päältä alas; niin sanoi Kaleb hänelle: mikä sinun on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Ja hän sanoi: anna minulle siunaus, sillä sinä olet antanut minulle kuivan maan, anna minulle myös vesilähteitä; niin antoi hän hänelle lähteitä sekä ylhäältä että alhaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Tämä on Juudan lasten sukukunnan perimys, heidän sukuinsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Ja kaupungit Juudan lasten sukukunnan äärestä, Edomin rajan tykönä, lounaaseen käsin olivat: Kabseel, Eder, Jagur,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona, Adada;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Hatsor, Jitnan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph, Telem, Bealot;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'HatsorHadata, Kerijot, Hetsron, se on Hatsor;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Sema, Molada;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'HatsarGadda, Hesmon, BetPalet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'HatsarSual, BeerSeba, BisJotja;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijim, Atsem;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil, Horma;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ziglag, Madmanna, Sansanna;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaot, Silhim, Ain, Rimmon; yhdeksänkolmattakymmentä kaupunkia kylinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Vaan lakialla maalla oli Estaol, Zora, Asna;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Sanoa, EnGannim, Tappua, Enam;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut, Adullam, Soko, Aseka;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Aditaim, Gedera, Gederotaim: neljätoistakymmentä kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan, Hadasa, Migdalgad;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilean, Mitspe, Jokteel;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lakis, Botskat, Eglon;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabbon, Lakmas, Kitlis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, BetDagon, Naama, Makkeda: kuusitoistakymmentä kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Asan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jephta, Asna, Nesib;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Aksib, Maresa: yhdeksän kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron tyttärinensä ja kylinensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Ekronista mereen asti, kaikki mikä ulottuu Asdodiin, ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod tyttärinensä ja kylinensä; Gasa tyttärinensä ja kylinensä, Egyptin veteen asti; ja se suuri meri on hänen rajansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Mutta vuorella oli: Samir, Jatir, Soko;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, KirjatSanna, se on Debir;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo, Anim;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon, Gilo: yksitoistakymmentä kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Esean;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janum, BetTapua, Apheka;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, KirjatArba, se on Hebron, Zior: yhdeksän kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, Siph, Juta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jisreel, Jokdeam, Sanoa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Kibea, Timna: kymmenen kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Betsur, Gedor;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarat, BetAnot, Eltekon: kuusi kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'KirjatBaal, se on KirjatJearim, Harabba: kaksi kaupunkia ja heidän kylänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Mutta korvessa oli BetAraba, Middin, Sekaka;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan, ja Suolakaupunki, Engedi; kuusi kaupunkia ja heidän kylänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Mutta Jebusilaiset asuivat Jerusalemissa, ja Juudan lapset ei voineet heitä ajaa ulos. Ja silloin jäivät Jebusilaiset asumaan Juudan lasten kanssa Jerusalemissa tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Josephin lasten arpa lankesi Jordanista Jerihoon päin, Jerihon veden tykö, itään käsin, siihen korpeen, joka menee Jerihosta ylös BetElin mäkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Ja tulee BetElistä Lusiin, ja menee ArkkiAtarotin rajan lävitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Ja antaa itsensä alas länteen päin Japhletin rajan tykö, alimmaisen BetHoronin rajaan, ja Gaseriin asti; ja sen ääri on meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Nämät saivat Josephin lapset, Manasse ja Ephraim perinnöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Ephraimin lasten raja heidän suvuissansa ja heidän perimisissänsä itään päin oli AtharotAddar, ylimmäiseen BetHoroniin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Joka antaa itsensä länteen päin Mikmethatiin, joka pohjoisessa on; sieltä kääntyy se itään, TaenatSilon puoleen, ja menee idästä Janoaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Ja tulee Janoasta Atarotiin ja Naarataan, ja antaa itsensä Jerihoa vastaan ja menee Jordaniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Tapuasta menee se länteen päin NahalKanaan, ja hänen äärensä on meressä. Tämä on Ephraimin lasten sukukunnan perimys heidän suvuissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Ephraimin lasten sukukunnalle olivat myös annetut kaikki kaupungit ja kylät keskellä Manassen lasten perintöä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Ja ei he ajaneet Kanaanealaisia pois, jotka asuivat Geserissä. Niin pysyivät Kanaanealaiset Ephraimin seassa tähän päivään asti ja tulivat verollisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Ja arpa lankesi Manassen sukukunnalle, sillä hän oli Josephin esikoinen, ja se lankesi Makirille Manassen esikoiselle, Gileadin isälle; sillä hän oli jalo sotamies, sentähden sai hän Gileadin ja Basanin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Muille Manassen lapsille myös lankesi arpa heidän sukukuntainsa jälkeen: Abieserin lapsille, Helekin lapsille, Asrielin lapsille, Sekemin lapsille, Hepherin lapsille ja Semidan lapsille. Nämät ovat Manassen Josephin pojan lapset, jotka olivat miehenpuolet heidän suvuissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Mutta Zelophkadilla Hepherin pojalla, Gileadin pojan, Makirin pojan, Manassen pojan, ei ollut yhtään poikaa, vaan tyttäriä; ja nämät ovat hänen tytärtensä nimet: Makla ja Noa, Hogla, Milka ja Tirtsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Ja he menivät papin Eleatsarin ja Josuan Nunin pojan ja ylimmäisten tykö, ja sanoivat: Herra käski Moseksen antaa meille perinnön meidän veljeimme sekaan; ja hän antoi myös heille perinnön heidän isänsä veljein sekaan, Herran käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Mutta Manasselle tuli kymmenen osaa, paitsi Gileadin ja Basanin maata, jotka ovat tuolla puolella Jordania;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Sillä Manassen tyttäret saivat perinnön hänen poikainsa seassa; ja Gileadin maa oli annettu muille Manassen pojille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Ja Manassen raja oli Asserista Mihmetatiin asti, joka on Sikemin edessä, ja menee ulos oikian käden puoleen niihin asti, kuin asuivat EnTapuassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Tapuan maa tuli Manasselle, mutta Tapua Manassen rajalla Ephraimin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Sitte tulee se alas NahalKanaan asti etelään päin velikaupungeita, jotka Ephraimin omat ovat, Manassen kaupunkien seassa. Mutta pohjan puolesta ovat Manassen rajat ojaan asti, ja niiden ääret ovat meren tykönä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Sillä Ephraimin maa on etelän puolella ja Manassen pohjan puolella, niin että meri on heidän rajansa, ja ulottuu Asseriin saakka pohjan puolesta, ja Isaskariin asti idän puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Niin oli Manassella Isaskarin ja Asserin seassa BetSean ja hänen tyttärensä, Jiblaam ja hänen tyttärensä, ja Dorin asuvaiset tyttärinensä, ja EnDorin asuvaiset tyttärinensä, ja Taanan asuvaiset tyttärinensä, Megiddon asuvaiset tyttärinensä, ja kolmas osa Naphetista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Ja Manassen lapset ei voineet ajaa niiden kaupunkien asuvaisia ulos, vaan Kanaanealaiset rupesivat asumaan siinä maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Mutta kuin Israelin lapset vahvistuivat, tekivät he Kanaanealaiset verollisiksi, ja ei ajaneet heitä ollenkaan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Silloin puhuivat Josephin lapset Josualle ja sanoivat: miksi et minulle enempää antanut, kuin yhden arvan ja osan, perinnöksi, ja minä olen kuitenkin suuri kansa, niinkuin Herra on minun tähän asti siunannut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Niin Josua sanoi heille: ettäs olet suuri kansa, niin mene metsään ja perkaa siellä sinulles siaa, Pheresiläisten ja uljasten maalla, jos Ephraimin vuori on sinulle ahtaimmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Niin sanoivat Josephin lapset: ei ne vuoret meille täydy, sillä kaikilla Kanaanealaisilla, jotka asuvat maan laaksoissa, ovat rautavaunut, ja BetSeanin asuvaisilla ja hänen tyttärillänsä, ja Jisreelin laaksossa asuvaisilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Josua puhui Josephin huoneelle, Ephraimille ja Manasselle, sanoen: sinä olet suuri ja väkevä kansa, ei sinulla pidä oleman yksi arpa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Sillä vuori pitää myös sinun omas oleman, jossa metsää on, siellä perkaa ympärilläs, ja sinulla pitää oleman sen ääret; sillä sinä ajat Kanaanealaiset pois, vaikka heillä rautavaunut ovat, ja vaikka he väkevät ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Ja kaikki Israelin lasten kansa kokoontui Siloon ja pani siellä ylös seurakunnan majan; ja maa oli heille alamainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Ja oli vielä Israelin lapsista seitsemän sukukuntaa, joiden perintö ei ollut jaettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Ja Josua sanoi Israelin lapsille: kuinka kauvan te olette niin kähläät, ettette mene ja omista maata, jonka Herra teidän isäinne Jumala teille on antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Ottakaat itsellenne jokaisesta sukukunnasta kolme miestä, lähettääkseni heitä menemään ja vaeltamaan maan lävitse, ja että he kirjoittaisivat sen perimisensä jälkeen ja palajaisivat minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Ja he jakakaan maan seitsemään osaan: Juudan pitää oleman rajallansa etelän puolella, ja Josephin huoneen pitää oleman rajallansa pohjan puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Mutta teidän pitää kirjoittaman ne seitsemän maan osaa ja tuoman tänne minun tyköni, niin minä heitän teidän arpanne tässä Herran meidän Jumalamme edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Sillä Leviläisillä ei ole yhtäkään osaa teidän seassanne, vaan Herran pappeus on heidän perimisensä. Mutta Gad ja Ruben, ja puoli Manassen sukukuntaa ottivat osansa tuolla puolella Jordania itäisellä puolella, jonka Moses Herran palvelia antoi heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Niin miehet nousivat ja läksivät matkaan, ja Josua käski heitä, kuin he tahtoivat mennä kirjoittamaan maata, ja sanoi: vaeltakaat maan lävitse ja kirjoittakaat se, ja tulkaat jälleen minun tyköni, ja minä heitän tässä teidän arpanne Herran edessä Silossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Niin miehet läksivät ja vaelsivat maan lävitse, ja kirjoittivat sen kirjaan, seitsemään osaan, kaupunkein jälkeen, ja tulivat Siloon, Josuan tykö leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Silloin heitti Josua Silossa arvan heille Herran edessä, ja Josua jakoi siinä maan Israelin lapsille, heidän osansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Ja BenJaminin lasten sukukunnan arpa lankesi heidän sukukuntainsa jälkeen, ja heidän arpansa raja oli Juudan lasten ja Josephin lasten vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Ja heidän rajansa oli pohjan kulmalla Jordanista, ja se raja menee ylöskäsin Jerihon viertä myöten pohjan puolesta, ja nousee vuorelle länteen päin, ja loppuu Betavenin korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Ja se raja juoksee sieltä Lutsaan, Lutsan viertä myöten lounaaseen päin, se on BetEl, ja laskee AtaraotAdariin, mäen ohessa etelään päin alamaista BetHoronia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Sitte laskee raja ja kääntää itsensä ympäri lännen puoleen meren kulmaan siitä mäestä, joka on BetHoronin edessä mereen päin, ja loppuu KirjatBaalin tykönä, se on KirjatJearim, Juudan lasten kaupunki. Tämä on lännenpuolinen kulma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Mutta lounaanpuolinen kulma on KirjatJearimin äärestä, ja loppuu raja lännen puoleen, ja tulee Nephtoan lähteen tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Ja laskee mäen loppuun, joka on Hinnomin lasten laakson edessä, joka on Rephaimin notkossa, pohjan puolella, ja laskee Hinnomin laaksoon Jebusilaisten viereen etelään päin, ja laskee Rogelin lähteelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Ja antaa itsensä pohjoisesta, ja juoksee EnSemeksen tykö, ja juoksee Gelilotin tykö, jotka ovat ylhäällä Adummin puolessa, ja laskee Bohanin, Rubenin pojan kiven tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Ja menee sen tasaisen kedon viertä myöten, joka on pohjaan päin, ja laskee tasaiselle kedolle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Ja menee sitä viertä myöten, BetHoglan ohesta pohjaan päin, ja loppuu Suolaisen meren lahteen, pohjaan päin, lounaan puolella Jordania. Tämä on lounaan puolinen raja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Mutta idänpuolinen kulma pitää Jordaniin loppuman. Tämä on BenJaminin lasten perintö heidän rajainsa ympärillä, heidän sukukuntainsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Mutta nämät ovat BenJaminin lasten sukukunnan kaupungit heidän heimokuntainsa jälkeen: Jeriho, BetHogla, EmekKetsits;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'BetAraba, Zemaraim, BetEl;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avvim, Para ja Ophra;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'KapharAmmoni, Ophni, ja Gaba: kaksitoistakymmentä kaupunkia kylinensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama ja Beerot;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mitspe, Kaphira ja Mosa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel ja Tarala;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Zela, Eleph, ja Jebusi, se on Jerusalem, GibeatKirjat, neljätoistakymmentä kaupunkia kylinensä. Tämä on BenJaminin lasten perimys heidän sukukuntainsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Senjälkeen lankesi toinen arpa Simeonin lasten sukukunnalle heidän sukuinsa jälkeen, ja heidän perintönsä oli keskellä Juudan lasten perimystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Ja heidän perittäväksensä tuli BeerSeba, Seba ja Molada:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'HatsarSual, Bala ja Atsem;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Betul ja Horma;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ziglag, Bethammarkabot ja HatsarSusa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'BetLebaot ja Saruhen: kolmetoistakymmentä kaupunkia ja heidän kylänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Eter ja Asan: neljä kaupunkia kylinensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Siihen myös kaikki kylät, jotka ympäri näitä kaupungeita ovat, BaalatBeeriin asti, ja Ramatiin, etelän puoleen. Tämä on Simeonin lasten sukukunnan perimys heidän suvuissansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Sillä Simeonin lasten perimys on keskellä Juudan lasten osaa; ja että Juudan lasten osa oli suurempi kuin he itse, sentähden perivät Simeonin lapset osan keskellä heidän perintöänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Kolmas arpa lankesi Sebulonin lasten sukukunnalle heidän sukuinsa jälkeen, ja heidän perintönsä raja oli Saridiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Ja heidän rajansa astuu lännen puoleen Maralaan, ja ulottuu Dabbasetiin ja siihen ojaan, joka juoksee Jokneamin ohitse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Ja kääntyy Saridista itään päin auringon nousemisen puoleen, KislotTaborin rajan tykö, ja menee Dabratiin, ja ulottuu Japhiaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Ja menee sieltä itään päin lävitse Githan, Hepherin, Ittan, Katsin, ja loppuu Rimmoniin, Mitoariin ja Neaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Ja juoksee ympäri pohjan puoleen Hannatoniin päin, ja loppuu JephtaElin laaksoon;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Kattat, Nahalal, Simron, Ideala ja Betlehem: kaksitoistakymmentä kaupunkia ja heidän kylänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tämä on Sebulonin lasten perimys heidän sukuinsa jälkeen, nämät heidän kaupunkinsa ja kylänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Neljäs arpa lankesi Isaskarin lapsille heidän sukuinsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Ja heidän rajansa oli Jisreel, Kesullot ja Sunem;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hapharaim, Sion ja Anaharat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbit, Kisjon ja Abets;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remet, EnGannim, Enhadda ja BetPhatsets;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Ja ulottuu Taboriin, Sahatsimaan, ja BetSemekseen, ja hänen loppunsa ovat Jordanin tykönä: kuusitoistakymmentä kaupunkia kylinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tämä on Isaskarin lasten sukukunnan perimys, kaupungit ja kylät heidän sukuinsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Viides arpa lankesi Asserin lasten sukukunnalle heidän sukuinsa jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Ja heidän rajansa oli Helkat, Hali, Beten ja Aksaph;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Allammelek, Amead ja Miseal, ja ulottuu Karmeliin länteen päin, ja SihorLibnatiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Ja kääntyy auringon nousemista käsin BetDagonia vastaan, ja ulottuu Sebuloniin ja Jephtahelin laaksoon pohjan puoleen, BetEmekiin ja Negieliin, ja loppuu Kabulin tykönä vasemmalla puolella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ja Ebroniin, Rehobiin, Hammoniin ja Kanaan, aina isoon Sidoniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Ja kääntyy raja Raman puoleen, aina vahvaan kaupunkiin Zoriin asti, ja palajaa Hosaan päin, ja loppuu meren tykönä nuoraa myöten Aksibin tykö;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umma, Aphek ja Rehob: kaksikolmattakymmentä kaupunkia kylinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tämä on Asserin lasten sukukunnan perimys heidän sukuinsa jälkeen, ne kaupungit ja heidän kylänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Kuudes arpa lankesi Naphtalin lapsille heidän sukunsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Ja heidän rajansa oli Helephistä, Elon Zananimin lävitse, Adami, Nekeb, JabneEl, Lakkumiin asti ja loppuu Jordaniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Ja raja kääntyy lännen puoleen AsnotTaborin tykö, ja tulee sieltä hamaan Hukkokiin, ja ulottuu etelästä Sebuloniin ja lännestä Asseriin ja Juudaan asti Jordanin tykö auringon ylenemisen puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Ja vahvat kaupungit ovat: Ziddim, Zer, Hammat, Rakkat ja Kinneret,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama ja Hatsor,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei ja Enhatsor,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, MigdalEl, Harem, BetAnat ja BetSemes: yhdeksäntoistakymmentä kaupunkia kylinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tämä on Naphtalin lasten sukukunnan perimys heidän suvuissansa, kaupungit ja kylät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Seitsemäs arpa lankesi Danin lasten sukukunnalle heidän sukuinsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Ja raja heidän perimisestänsä oli Sorea, Estaol ja Irsemes,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabbin, Ajalon ja Jitla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timnata ja Ekron,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibbeton ja Baalat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehut, BeneBarak ja GatRimmon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Mehaijarkon ja Rakkon, sen rajan kanssa Japhoa vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Ja siellä loppuu Danin lasten raja. Ja Danin lapset nousivat ja sotivat Lesemiä vastaan, ja voittivat sen ja löivät sen miekan terällä, omistivat sen ja asuivat siinä, ja kutsuivat Lesemin Daniksi, isänsä Danin nimeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Tämä on Danin lasten sukukunnan perintö heidän suvuissansa, nämät kaupungit ja niiden kylät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Ja kuin he olivat lakanneet jakamasta maata rajoinensa, antoivat Israelin lapset Josualle Nunin pojalle perinnön heidän seassansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Ja antoivat hänelle Herran käskyn jälkeen sen kaupungin, jota hän anoi, joka oli TimnatSera Ephraimin vuorella; siellä hän rakensi kaupungin ja asui siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Nämät ovat ne perimiset, jotka pappi Eleatsar ja Josua Nunin poika ja ylimmäiset Israelin lasten sukukuntain isistä arvalla jakoivat Silossa Herran edessä, seurakunnan majan oven tykönä; ja niin lopettivat maan jakamisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Ja Herra puhui Josualle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Puhu Israelin lapsille, sanoen: asettakaat teille muutamia vapaakaupungeita, joista minä teille puhuin Moseksen kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Että sinne sais paeta miehentappaja, joka jonkun lyö tapaturmaisesti ja tietämätä, että he teidän seassanne olisivat vapaat verenkostajalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Ja joka pakenee johonkuhun niistä kaupungeista, hänen pitää seisoman ulkona kaupungin portin edessä ja jutteleman vanhinten edessä syynsä, niin pitää heidän ottaman hänen kaupunkiin tykönsä ja antaman hänelle siaa, asuaksensa heidän tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Ja kuin verenkostaja ajaa häntä takaa, ei heidän pidä antaman miehentappajaa hänen käsiinsä, että hän tietämätä löi lähimmäisensä ja ei ollut ennen vainoa hänen välillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Niin asukaan hän siinä kaupungissa, siihenasti kuin hän seisoo seurakunnan oikeuden edessä, ylimmäisen papin kuolemaan asti, joka siihen aikaan on; sitte pitää miehentappajan palaaman ja tuleman kaupunkiinsa ja huoneeseensa, kaupunkiin, josta hän pakeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Niin he pyhittivät Kedeksen Galileassa Naphtalin vuorella, ja Sikemin Ephraimin vuorella, ja KirjatArban, se on Hebroni, Juudan vuorella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Ja tuolla puolella Jordania, Jerihon kohdalla itään päin, antoivat he Betserin, korvessa lakialla kedolla, Rubenin sukukunnasta, ja Ramotin Gileadissa Gadin sukukunnasta ja Golanin Basanissa Manassen sukukunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Nämät olivat ne kaupungit, jotka asetettiin kaikille Israelin lapsille ja muukalaisille, jotka heidän seassansa asuivat, että sinne piti pakeneman jokainen joka jonkun tapaturmaisesti löi, ettei hän kuolisi verenkostajan käden kautta, siihenasti että hän seisois seurakunnan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Niin menivät Leviläisten ylimmäiset isät papin Eleatsarin ja Josuan Nunin pojan eteen, ja ylimmäisten isäin eteen Israelin lasten sukukunnissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'Ja puhuttelivat heitä Silossa Kanaanin maalla ja sanoivat: Herra käski Moseksen kautta antaa meille kaupungeita asuaksemme, ja niiden esikaupungit meidän karjallemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Niin antoivat Israelin lapset Leviläisille perinnöstänsä, Herran käskyn jälkeen, nämät kaupungit esikaupunkeinensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Ja arpa lankesi Kahatilaisten sukukunnille: ja papin Aaronin lapset Leviläisistä saivat arvalla Juudan sukukunnalta, Simeonin sukukunnalta ja BenJaminin sukukunnalta kolmetoistakymmentä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Vaan muille Kahatin lapsille tuli arvalla Ephraimin sukukunnalta, Danin sukukunnalta ja puolelta Manassen sukukunnalta kymmenen kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Gersonin lapsille tuli arvalla Isaskarin sukukunnalta, Asserin sukukunnalta, Naphtalin sukukunnalta ja puolelta Manassen sukukunnalta Basanissa kolmetoistakymmentä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merarin lapset sukuinsa jälkeen saivat Rubenin sukukunnalta, Gadin sukukunnalta ja Zebulonin sukukunnalta kaksitoistakymmentä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Ja niin antoivat Israelin lapset Leviläisille arvalla nämät kaupungit esikaupunkeinensa, niinkuin Herra Moseksen kautta käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Juudan lasten sukukunnalta ja Simeonin lasten sukukunnalta annettiin nämät kaupungit, jotka he nimittivät nimeltänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Aaronin pojille Kahatilaisten suvusta Levin pojista; sillä ensimäinen arpa oli heidän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Niin antoivat he heille KirjatArban, (Arba oli Enakin isä), se on Hebron, Juudan vuorella, ja esikaupungit ympäristöltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Mutta kaupungin pellon kylinensä antoivat he Kalebille Jephunnen pojalle perinnöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Niin antoivat he papin Aaronin lapsille miehentappajain vapaakaupungin Hebronin esikaupunkeinensa ja Libnan esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jatirin esikaupunkeinensa ja Estmoan esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Holonin esikaupunkeinensa ja Debirin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ain esikaupunkeinensa, Juttan esikaupunkeinensa ja BetSemeksen esikaupunkeinensa: yhdeksän kaupunkia niiltä kahdelta sukukunnalta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'BenJaminin sukukunnalta Gibeonin esikaupunkeinensa ja Geban esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatotin esikaupunkeinensa ja Almonin esikaupunkeinensa: neljä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Kaikki pappein Aaronin poikain kaupungit olivat kolmetoistakymmentä ja niiden esikaupungit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Mutta muut Kahatin lasten sukukunnat, Leviläiset, Kahatin sikiät saivat kaupunkia arvallansa Ephraimin sukukunnalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Ja he antoivat heille miehentappajan vapaakaupungin Sikemin esikaupunkeinensa Ephraimin vuorella ja Getserin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibtsaimin esikaupunkeinensa ja BetHoronin esikaupunkeinensa: neljä kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Ja Danin sukukunnalta Elteken esikaupunkeinensa ja Gibtonin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalonin esikaupunkeinensa, GatRimmonin esikaupunkeinensa: neljä kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Puolelta Manassen sukukunnalta Thaanakin esikaupunkeinensa ja GatRimmonin esikaupunkeinensa: kaksi kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Kaikki muiden Kahatin lasten sukukuntain kaupungit olivat kymmenen ja niiden esikaupungit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Gersonin lapsille Leviläisten sukukunnasta annettiin puolelta Manassen sukukunnalta miehentappajan vapaakaupunki Golan Basanissa esikaupunkeinensa ja Beestera esikaupunkeinensa: kaksi kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Isaskarin sukukunnalta Kision esikaupunkeinensa, Dabrat esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut esikaupunkeinensa ja EnGannim esikaupunkeinensa: neljä kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Asserin sukukunnalta Miseal esikaupunkeinensa, Abdon esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkat esikaupunkeinensa ja Rehob esikaupunkeinensa: neljä kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Naphtalin sukukunnalta miehentappajan vapaakaupunki Gedes Galileassa esikaupunkeinensa ja HammotDor esikaupunkeinensa, Kartan esikaupunkeinensa: kolme kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Kaikki Gersonilaisten sukukuntain kaupungit olivat kolmetoistakymmentä ja niiden esikaupungit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Merarin lapsille, toisille Leviläisille, annettiin Sebulonin sukukunnalta Jokneam esikaupunkeinensa ja Kartta esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimna esikaupunkeinensa, Nahalal esikaupunkeinensa: neljä kaupunkia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Rubenin sukukunnalta Betser esikaupunkeinensa ja Jaksa esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot esikaupunkeinensa ja Mephaat esikaupunkeinensa: neljä kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Gadin sukukunnalta miehentappajan vapaakaupunki Ramot Gileadissa esikaupunkeinensa ja Mahanaim esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon esikaupunkeinensa ja Jaeser esikaupunkeinensa: kaikki neljä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Kaikki toisten Leviläisten Merarin lasten kaupungit, heidän suvussansa arpansa jälkeen, olivat kaksitoistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Kaikki Leviläisten kaupungit Israelin lasten perinnön seassa olivat kahdeksanviidettäkymmentä ja niiden esikaupungit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Ja itsekullakin kaupungilla oli hänen esikaupunkinsa ympäristöllänsä, niin oli niillä kaikilla kaupungeilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Ja niin antoi Herra Israelin lapsille kaiken sen maan, jonka hän vannoi heidän isillensä antaaksensa; ja he omistivat sen ja asuivat siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Ja Herra antoi heille levon kaikella heidän ympäristöllänsä, niinkuin hän vannoi heidän isillensä; ja ei yksikään heidän vihollisistansa seisonut heitä vastaan, vaan kaikki heidän vihollisensa antoi Herra heidän käsiinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Ja ei puuttunut mitään kaikesta siitä hyvyydestä, mitä Herra oli puhunut Israelin huoneelle, vaan kaikki tapahtui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Silloin kutsui Josua tykönsä Rubenilaiset, Gadilaiset ja puolen Manassen sukukuntaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Ja sanoi heille: te piditte kaikki mitä Moses Herran palvelia teille käski, ja olette kuulleet minun ääneni kaikissa mitä minä olen teille käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Ette hyljänneet teidän veljiänne isoon aikaan tähän päivään asti, ja te piditte Herran teidän Jumalanne käskyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Ja nyt on Herra teidän Jumalanne antanut teidän veljillenne levon, niinkuin hän sanoi heille; palatkaat siis nyt ja menkäät teidän majoillenne perintömaahanne, jonka Moses Herran palvelia antoi teille tuolla puolella Jordania.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Ainoastaan ottakaat visusti vaari, että te teette sen käskyn ja lain jälkeen, jonka Moses Herran palvelia on teille käskenyt, että te rakastatte Herraa teidän Jumalaanne, ja vaellatte kaikissa hänen teissänsä, ja pidätte hänen käskynsä, ja riiputte hänessä kiinni, ja palvelette häntä kaikesta teidän sydämestänne ja kaikesta teidän sielustanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Niin Josua siunasi heitä ja antoi heidän mennä, ja he menivät majoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Manassen puolelle sukukunnalle on Moses antanut Basanissa ja toiselle puolelle antoi Josua heidän veljeinsä keskellä tällä puolella Jordania länteen päin. Ja kuin Josua antoi heidän käydä majoillensa ja siunasi heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Puhui hän heille, sanoen: te tulette kotia suurella saaliilla teidän majoillenne ja sangen suurella karjalaumalla, hopialla, kullalla, vaskella, raudalla ja aivan paljoilla vaatteilla; niin jakakaat teidän vihamiestenne saalis teidän veljeinne kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Ja niin palasivat Rubenilaiset ja Gadilaiset ja puoli Manassen sukukuntaa, ja menivät pois Israelin lasten tyköä Silosta, joka Kanaanin maalla on, menemään Gileadin maahan, perintömaahansa, jonka he olivat perineet Herran käskyn jälkeen Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Ja kuin he tulivat Jordanin rajoille, jotka Kanaanin maassa ovat, rakensivat Rubenilaiset, Gadilaiset ja puoli Manassen sukukuntaa siinä lähes Jordania jalon suuren alttarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Ja kuin Israelin lapset kuulivat sanottavan: katso, Rubenin lapset, Gadin lapset ja puoli Manassen sukukuntaa ovat rakentaneet alttarin Kanaanin maata vastaan, lähes Jordanin rajoja Israelin lasten puolelle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Ja Israelin lapset kuulivat sen, ja koko Israelin lasten joukko kokoontui Silossa, menemään ylös sotimaan heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Ja Israelin lapset lähettivät Rubenilaisten, Gadilaisten ja puolen Manassen sukukunnan tykö Gileadin maahan Pinehaan, papin Eleatsarin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Ja kymmenen ylimmäistä päämiestä hänen kanssansa, yhden päämiehen kustakin isänsä huoneesta, kaikista Israelin sukukunnista, joista kukin oli isäinsä huonetten päämies Israelin tuhanten ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Ja he tulivat Rubenilaisten, Gadilaisten ja puolen Manassen sukukunnan tykö Gileadin maahan ja puhuivat heidän kanssansa, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Näin kaikki Herran kansa käski teille sanoa: mikä on se rikos, jolla te olette rikkoneet Israelin Jumalaa vastaan, kääntääksenne itsenne tänäpäivänä Herrasta pois, rakentaen itsellenne alttaria, asettaaksenne teitänne tänäpäivänä Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Vähäkö meillä on Peorin pahuudesta, josta emme puhtaat ole hamaan tähän päivään asti? josta myös rangaistus tuli Herran kansan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Ja te käännätte itsenne tänäpäivänä Herrasta pois; niin tapahtuu, että panette itsenne tänäpänä Herraa vastaan, niin pitää huomenna hänen vihansa palaman koko Israelin kansan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Jos te luulette, että teidän perintömaanne on saastainen, niin tulkaat tänne ylitse Herran perintömaahan, jossa Herran maja on, ja ottakaat perintö meidän seassamme ja älkäät asettako teitänne Herraa vastaan ja meitä vastaan, rakentaen teillenne alttarin, paitsi Herran meidän Jumalamme alttaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Eikö Akan Seran poika tehnyt raskaasti syntiä kirotussa, ja viha tuli koko Israelin ylitse ja ei hän yksin hukkunut pahuudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Niin vastasivat Rubenin ja Gadin lapset ja puoli Manassen sukukuntaa ja sanoivat Israelin tuhanten päämiehille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Herra väkevä Jumala, Herra väkevä Jumala tietää sen, ja Israel myös mahtaa itse tietää; jos me olemme langenneet pois ja syntiä tehneet Herraa vastaan, niin älkäät auttako hän meitä tänäpäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Ja jos me olemme alttarin rakentaneet, kääntääksemme meitämme Herrasta pois ja uhrataksemme sen päällä polttouhria ja ruokauhria, taikka tehdäksemme kiitosuhria sen päällä, niin etsiköön sitä Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Ja jos emme paljo ennemmin ole sitä tehneet sen asian pelvon tähden, sanoen: tästälähin mahtaa teidän lapsenne sanoa meidän lapsillemme: mitä teidän on tekemistä Herran Israelin Jumalan kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Herra on pannut Jordanin rajamaaksi meidän ja teidän välillemme, te Rubenin ja Gadin lapset; ei ole teillä yhtään osaa Herrassa: ja niin teidän lapsenne saattavat pois meidän lapsemme Herraa pelkäämästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Sentähden me sanoimme: tehkäämme se meillemme, rakentakaamme alttari, ei uhriksi eli polttouhriksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Mutta todistukseksi meidän ja teidän vaiheellamme, ja meidän sukumme meidän jälkeemme, tehdäksemme Herran palvelusta hänen edessänsä meidän polttouhrillamme, kiitosuhrillamme ja muilla uhreillamme; ja teidän lapsenne ei pidä tästälähin sanoman meidän lapsillemme: ei ole teillä yhtään osaa Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Sillä me sanoimme: se olkoon, kuin he niin sanovat meille, taikka meidän lapsillemme tästedes, niin me taidamme sanoa: katsokaat vertausta Herran alttariin, jonka meidän vanhempamme tehneet ovat, ei polttouhriksi taikka teurasuhriksi vaan todistukseksi teidän ja meidän vaiheellamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Pois se meistä, että me asetamme itsemme Herraa vastaan, ja käännymme tänäpäivänä hänestä pois, ja rakennamme alttarin polttouhriksi, ruokauhriksi ja muuksi uhriksi, paitsi Herran meidän Jumalamme alttaria, joka on hänen majansa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Kuin Pinehas pappi ja kansan ylimmäiset ja Israelin tuhanten päämiehet, jotka olivat hänen kanssansa, kuulivat nämät sanat, jotka Rubenin, Gadin ja Manassen lapset sanoivat, kelpasi se heille sangen hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Ja Pinehas papin Eleatsarin poika sanoi Rubenin, Gadin ja Manassen lapsille: tänäpänä ymmärsimme me Herran olevan meidän kanssamme, ettette syntiä tehneet tällä rikoksella Herraa vastaan: nyt te vapahditte Israelin lapset Herran kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Niin meni Pinehas papin Eleatsarin poika, ja ylimmäiset Gileadin maalta, Rubenin ja Gadin lasten tyköä Kanaanin maahan jälleen Israelin lasten tykö ja sanoi sen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Niin se kelpasi hyvin Israelin lapsille, ja Israelin lapset kunnioittivat Jumalaa ja ei enää sanoneet, että he tahtoivat sinne mennä heitä vastaan sotaväen kanssa maata hävittämään, jossa Rubenin ja Gadin lapset asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Ja Rubenin ja Gadin lapset kutsuivat sen alttarin, että se olis todistukseksi meidän välillämme, ja että Herra on Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Ja pitkän ajan perästä, kuin Herra oli antanut Israelin tulla lepoon kaikilta vihollisiltansa, jotka heidän ympärillänsä olivat, ja Josua jo oli vanha ja hyvään ikään joutunut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Kutsui Josua koko Israelin tykönsä, heidän vanhimpansa, päämiehensä, tuomarinsa ja esimiehensä, sanoen heille: minä olen jo vanha ja hyvään ikään tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Ja te olette nähneet kaikki, jotka Herra teidän Jumalanne on tehnyt kaikelle tälle kansalle teidän edessänne; sillä Herra teidän Jumalanne itse sotii teidän edestänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Katsokaat, minä olen jakanut teille ne kansat arvalla, jotka vielä jäljellä ovat, jokaiselle sukukunnalle oman perintönsä jälkeen, hamasta Jordanista, ja kaiken sen kansan, jonka minä hävitin, suureen mereen asti auringon laskemiseen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Ja Herra teidän Jumalanne syöksee ulos ne teidän edestänne ja ajaa heidät ulos teidän kasvoinne edestä, niin että te omistatte heidän maansa, niinkuin Herra teidän Jumalanne teille sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Niin vahvistukaat jalosti pitämään ja tekemään kaikki, mikä on kirjoitettu Moseksen lakiraamatussa, niin ettette siitä poikkeisi oikialle eli vasemmalle puolelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Niin ettette tulisi näiden teidän keskellenne jääneiden kansain sekaan, ja ettette mieleenne johdattaisi eli vannoisi heidän jumalainsa nimen kautta, ettekä myös palvelisi heitä elikkä kumartaisi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Mutta riippukaat Herrassa teidän Jumalassanne kiinni, niinkuin te tähän päivään asti tehneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Ja niin Herra ajaa teidän edestänne suuren ja väkevän kansan ulos, niinkuin ei yksikään ole kestänyt teidän edessänne tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Yksi teistä ajaa tuhatta takaa; sillä Herra teidän Jumalanne itse sotii teidän edestänne, niinkuin hän teille sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Sentähden ottakaat visusti vaari teidän sielustanne, että rakastatte Herraa teidän Jumalaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Mutta jos te käännätte teitänne pois ja pidätte teitänne jääneiden kansain tykö, ja yhdistätte teitänne naimisessa heidän kanssansa, niin että te tulette heidän ja he teidän sekaanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Niin teidän pitää todella tietämän, ettei Herra teidän Jumalanne enää tätä kansaa teidän edestänne aja ulos; mutta he tulevat teille paulaksi ja pahennukseksi ja ruoskaksi teidän kylkenne päälle, ja orjantappuraksi teidän silmillenne, siihenasti että hän teitä hukuttaa siitä hyvästä maasta, jonka Herra teidän Jumalanne teille antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Ja katso, minä vaellan tänäpänä kaiken maailman tien; ja teidän pitää tietämän kaikessa teidän sydämessänne ja kaikessa teidän sielussanne, ettei yhtään sanaa ole jäänyt takaperin kaikesta siitä hyvästä, minkä Herra teidän Jumalanne teille luvannut on, mutta kaikki on tapahtunut teille, ja ei mitään jäänyt takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Ja pitää tapahtuman, että niinkuin kaikki se hyvä on teille tullut, jonka Herra teidän Jumalanne teille sanonut on, niin Herra myös antaa tulla teidän ylitsenne kaikki pahat, siihenasti että hän kadottaa teidät siitä hyvästä maasta, jonka Herra teidän Jumalanne teille antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Jos te Herran teidän Jumalanne liiton käytte ylitse, jonka hän teille käski, ja menette ja palvelette vieraita jumalia, ja heitä rukoilette, niin Herran viha julmistuu teidän päällenne, ja te hukutte äkisti siitä hyvästä maasta, jonka hän teille antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Ja Josua kokosi kaikki Israelin sukukunnat Sikemiin, ja kutsui edes vanhimmat Israelissa, päämiehet, tuomarit ja esimiehet; ja kuin he olivat seisatetut Jumalan eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Sanoi Josua kaikelle kansalle: näin sanoo Herra Israelin Jumala: teidän isänne asuivat entiseen aikaan sillä puolella virtaa, Tara, Abrahamin ja Nahorin isä, ja palvelivat muita jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Niin otin minä isänne Abrahamin tuolta puolelta virtaa, ja annoin hänen vaeltaa koko Kanaanin maalla, ja enensin hänen siemenensä, ja annoin hänelle Isaakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Ja Isaakille annoin minä Jakobin ja Esaun; ja annoin Esaulle Seirin vuoren asuaksensa. Mutta Jakob ja hänen lapsensa menivät alas Egyptin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Ja minä lähetin Moseksen ja Aaronin, ja rankaisin Egyptin, niinkuin minä heidän seassansa tehnyt olen; sitte vein minä teidät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Niin vein minä myös teidän isänne Egyptistä ulos, ja te tulitte meren tykö; ja Egyptiläiset ajoivat teidän isiänne takaa vaunuin ja ratsasmiesten kanssa Punaiseen mereen saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Niin huusivat he Herran tykö, ja hän pani pimeyden teidän ja Egyptiläisten vaiheelle, ja saatti meren heidän päällensä, ja peitti heidät. Ja teidän silmänne näkivät, mitä minä tein Egyptissä; ja te asuitte korvessa kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Ja minä toin teidät Amorilaisten maahan, jotka asuivat tuolla puolella Jordania; ja kuin he sotivat teitä vastaan, annoin minä heidät teidän käsiinne, että te omistaisitte heidän maansa; ja minä hävitin heitä teidän edestänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Niin nousi Balak Zipporin poika, Moabin kuningas, ja soti Israelia vastaan; ja hän lähetti ja antoi kutsua Bileamin Beorin pojan kiroomaan teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mutta en minä tahtonut kuulla Bileamia; ja hän siunaten siunasi teitä, ja minä vapahdin teitä hänen käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Ja kuin te tulitte Jordanin ylitse ja jouduitte Jerihoon, sotivat Jerihon asuvaiset teitä vastaan, Amorilaiset ja Pheresiläiset ja Kanaanealaiset ja Hetiläiset ja Girgasilaiset ja Heviläiset ja Jebusilaiset; mutta minä annoin heidät teidän käsiinne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Ja lähetin vapsaiset teidän edellänne, ja ne ajoivat heidät ulos teidän edestänne, kaksi Amorilaisten kuningasta, ei sinun miekkas kautta eikä sinun joutses kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Ja annoin teille maan, jossa ette mitään työtä tehneet, ja kaupungit, joita ette rakentaneet, asuaksenne niissä ja syödäksenne viinapuista ja öljypuista, joita ette istuttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Peljätkäät siis nyt Herraa ja palvelkaat häntä täydellisesti ja uskollisesti, ja hyljätkäät ne jumalat, joita teidän isänne palvelivat tuolla puolella virtaa ja Egyptissä, ja palvelkaat Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Jollei teidän kelpaa Herraa palvella, niin valitkaat teillenne tänäpäivänä ketä te palvelette, niitä jumalia, joita teidän isänne palvelivat sillä puolella virtaa, eli Amorilaisten jumalia, joiden maassa te asutte. Mutta minä ja minun huoneeni palvelemme Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Niin vastasi kansa ja sanoi: pois se meistä, että me hylkäisimme Herran ja palvelisimme muita jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Sillä Herra meidän Jumalamme on se, joka johdatti meitä ja meidän isiämme Egyptin maalta orjuuden huoneesta, ja joka teki meidän silmäimme edessä niitä suuria tunnusmerkkejä, ja varjeli meitä kaikella matkalla, jota me vaelsimme, ja kaikkein kansain seassa, joiden lävitse me kävimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Ja Herra ajoi meidän edestämme ulos kaiken kansan ja Amorilaiset, jotka asuivat maassa: niin me myös palvelemme Herraa, sillä hän on meidän Jumalamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Ja Josua sanoi kansalle: ette taida palvella Herraa, sillä hän on pyhä Jumala ja hän on kiivas Jumala, joka ei säästä teidän syntejänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Kuin te hylkäätte Herran ja palvelette muukalaisia jumalia, niin hän kääntää hänensä, ja tekee teille pahaa, ja hukuttaa teitä sen jälkeen, kuin hän teille hyvää teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Niin sanoi kansa Josualle: ei suinkaan, vaan me palvelemme Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Ja Josua sanoi kansalle: te olette teillenne todistajat, että te valitsitte teillenne Herran, palvellaksenne häntä. Ja he sanoivat: me olemme todistajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Niin pankaat nyt teidän tyköänne muukalaiset jumalat pois, jotka teidän seassanne ovat, ja kumartakaat teidän sydämenne Herran Israelin Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Ja kansa sanoi Josualle: me tahdomme palvella Herraa meidän Jumalaamme, ja olemme hänen äänellensä kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Niin Josua teki sinä päivänä liiton kansan kanssa, ja asetti säädyn ja oikeuden heidän eteensä Sikemissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Ja Josua kirjoitti kaikki nämä sanat Jumalan lakikirjaan, ja otti suuren kiven, ja pystytti sen siinä tammen alla, joka oli Herran pyhässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Ja Josua sanoi kaikelle kansalle: katso, tämä kivi pitää oleman todistus meidän vaiheellamme; sillä hän on kuullut kaikki Herran puheet, jotka hän meidän kanssamme puhunut on, ja pitää oleman teille todistus, ettette teidän Jumalaanne kiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Ja niin antoi Josua kansan mennä, itsekunkin perintöönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Ja sen jälkeen tapahtui, että Josua Nunin poika, Herran palvelia, kuoli, sadan ja kymmenen ajastaikaisena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Ja he hautasivat hänen oman perityn maansa rajoihin, Timnat Serakiin, joka on Ephraimin vuorella, pohjan puolelle Gaasin vuorta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Ja Israel palveli Herraa kaikkena Josuan elinaikana, niin myös kaikkena vanhimpain elinaikana, jotka kauvan aikaa josuan perästä elivät ja tiesivät kaikki Herran teot, jotka hän Israelille tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Ja Josephin luut, jotka Israelin lapset olivat tuoneet Egyptistä, hautasivat he Sikemiin, siihen pellon kappaleeseen, jonka Jakob osti Hemorin Sikemin isän lapsilta sadalla penningillä. Ja se tuli Josephin lasten perinnöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Niin kuoli myös Eleatsar Aaronin poika, ja he hautasivat hänen Gibeassa, joka oli hänen poikansa Pinehaan oma, joka hänelle Ephraimin vuorella annettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Ja tapahtui Josuan kuoleman jälkeen, että Israelin lapset kysyivät Herralta, sanoen: kuka meistä ensisti menee sotaan ylös Kanaanealaisia vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Ja Herra sanoi: Juudan pitää menemän: katso, minä annoin maan hänen käsiinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Niin sanoi Juuda veljellensä Simeonille: käy minun kanssani minun arpaani, sotimaan Kanaanealaisia vastaan, niin minä myös menen sinun arpaas sinun kanssas; ja Simeon meni hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Kuin Juuda meni sinne ylös, antoi Herra hänelle Kanaanealaiset ja Pheresiläiset heidän käsiinsä; ja he löivät Besekissä kymmenentuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Ja he löysivät AdoniBesekin Besekistä, ja sotivat heitä vastaan ja löivät Kanaanealaiset ja Pheresiläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Mutta AdoniBesek pakeni, ja he ajoivat häntä takaa, saivat hänen kiinni ja leikkasivat häneltä peukalot käsistä ja isot varpaat jaloista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Niin sanoi AdoniBesek: seitsemänkymmentä kuningasta, leikatuilla peukaloilla heidän käsistänsä ja jaloistansa, hakivat minun pöytäni alla; niinkuin minä tein, niin on Jumala minulle maksanut. Ja he veivät hänen Jerusalemiin, ja siellä hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Mutta Juudan lapset sotivat Jerusalemia vastaan, ja voittivat sen, ja löivät sen miekan terällä, ja polttivat kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Sitte matkustivat Juudan lapset alas sotimaan Kanaanealaisia vastaan, jotka vuorella asuivat etelään päin laaksoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Meni myös Juuda Kanaanealaisia vastaan, jotka Hebronissa asuivat (mutta Hebron kutsuttiin muinen KirjatArba), ja löivät Sesain, Ahimanin ja Talmain;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Ja meni sieltä Debirin asuvia vastaan (mutta Debir kutsuttiin muinen KirjatSepher).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Ja Kaleb sanoi: joka KirjatSepherin lyö ja sen voittaa, hänelle annan minä tyttäreni Aksan emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Niin voitti sen Otniel Kenaksen, Kalebin nuoremman veljen poika, ja hän antoi tyttärensä Aksan hänelle emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Ja tapahtui, kuin Aksa tuli, että hän neuvoi miestänsä anomaan peltoa isältä; ja hän astui aasinsa päältä alas, niin sanoi Kaleb hänelle: mikä sinun on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Hän sanoi hänelle: anna minulle siunaus; sillä sinä annoit minulle kuivan maan, anna myös minulle vesinen maa. Niin antoi Kaleb hänelle vesiset maat ylhäältä ja alhaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Ja Moseksen apen Keniläisen lapset menivät Palmukaupungista Juudan lasten kanssa Juudan korpeen, etelään päin Aradia; ja he menivät ja asuivat kansan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Ja Juuda meni veljensä Simeonin kanssa, ja he löivät Kanaanealaiset jotka Sephatissa asuivat, ja hävittivät sen, ja kutsuivat kaupungin Horma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Sitälikin voitti Juuda Gasan rajoinensa, ja Askalonin rajoinensa, ja Ekronin rajoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Ja Herra oli Juudan kanssa, niin että hän omisti vuoret; sillä ei hän voinut niitä ajaa ulos, jotka laaksoissa asuivat, sillä heillä oli rautaiset vaunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Ja he antoivat Kalebille Hebronin, niinkuin Moses sanonut oli, ja hän ajoi siitä ulos kolme Enakin poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Mutta BenJaminin lapset ei ajaneet Jebusilaisia pois, jotka asuivat Jerusalemissa; ja Jebusilaiset asuivat BenJaminin lasten tykönä Jerusalemissa tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Meni myös Josephin huone ylös BetEliin, ja Herra oli heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Ja Josephin huone vakosi BetEliä (joka muinen kutsuttiin Luts).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Ja vartiat saivat nähdä miehen käyvän kaupungista, ja sanoivat hänelle: osoita meille, kusta kaupungin sisälle mennään, niin me teemme laupiuden sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Ja hän osoitti heille kaupungin sisällekäytävän, ja he löivät kaupungin miekan terällä; mutta sen miehen ja kaiken hänen sukunsa laskivat he menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Niin meni se mies Hetiläisten maakuntaan ja rakensi kaupungin, ja kutsui hänen Luts, joka tähän päivään asti niin kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Ja ei Manasse ajanut ulos Betseania tyttärinensä, eikä myös Taanakia tyttärinensä, eikä Dorin asuvaisia tyttärinensä, eikä Jibleamin asuvia tyttärinensä, eikä Megiddon asuvia tyttärinensä. Ja Kanaanealaiset rupesivat asumaan siinä maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Ja kuin Israel voimalliseksi tuli, teki hän Kanaanealaiset verolliseksi ja ei ajanut heitä ollenkaan ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Eikä myös Ephraim ajanut ulos Kanaanealaisia, jotka asuivat Gatserissa; mutta Kanaanealaiset asuivat heidän seassansa Gatserissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Eikä myös Zebulon ajanut Kitronin ja Nahalolin asuvaisia ulos; vaan Kanaanealaiset asuivat heidän keskellänsä ja olivat verolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Eikä myös Asser ajanut niitä ulos, jotka asuivat Akkossa, eikä niitä, jotka asuivat Zidonissa, Akelabissa, Aksibissa, Helbassa, Aphikissa ja Rehobissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Mutta Asserilaiset asuivat Kanaanealaisten seassa, jotka siinä maassa asuivat: ettei he niitä ajaneet ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Eikä myös Naphtali ajanut niitä ulos, jotka asuivat BetSemessä ja BetAnatissa, mutta asuivat Kanaanealaisten seassa, jotka maan asuvaiset olivat; mutta ne, jotka BetSemessä ja BetAnatissa olivat, tulivat heille verollisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Ja Amorilaiset ahdistivat Danin lapsia vuorilla eikä sallineet heitä tulemaan laaksoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Mutta Amorilaiset rupesivat asumaan vuorilla, Hereessä, Ajalonissa ja Saalbimissa; niin tuli Josephin käsi heille raskaaksi, ja he tulivat verollisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Ja Amorilaisten rajat olivat siitä, kuin käydään ylös Akrabimiin, kalliosta ja ylhäältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Ja Herran enkeli astui ylös Gilgalista Bokimiin ja sanoi: minä johdatin teidät tänne Egyptistä ja toin teidät siihen maahan, jonka minä vannoin teidän isillenne ja sanoin: en minä tee liittoani teidän kanssanne tyhjäksi ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Ja ei teidän pidä ikänä tekemän liittoa tämän maan asuvaisten kanssa: teidän pitää maahan kukistaman heidän alttarinsa; mutta ette totelleet minun ääntäni. Miksi te sen olette tehneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Sanoin minä myös: en minä heitä teidän edestänne aja pois, vaan heidän pitää oleman teille paulaksi, ja heidän Jumalansa teille verkoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Ja kuin Herran enkeli nämät sanat puhunut oli kaikille Israelin lapsille, korotti kansa äänensä ja itki;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Ja kutsuivat sen paikan Bokim, ja uhrasivat siinä Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Ja kuin Josua oli päästänyt kansan tyköänsä, ja Israelin lapset menneet itsekukin perintöönsä, maata omistamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Palveli kansa Jumalaa niinkauvan kuin Josua eli, ja koko vanhimpain aikana, jotka Josuan perässä kauvan elivät ja olivat nähneet kaikkia Herran suuria töitä, jotka hän Israelille tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Mutta kuin Josua Nunin poika Herran palvelia kuoli, sadan ja kymmenen ajastaikaisena,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Ja he olivat haudanneet hänet perintömaansa rajoihin, TimnatHerekseen, Ephraimin vuorelle pohjan puolelle Gaasin vuorta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Kuin myös kaikki se sukukunta oli koottu isäinsä tykö, tuli toinen sukukunta heidän jälkeensä, jotka ei tunteneet Herraa eikä niitä töitä, jotka hän Israelille tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Ja Israelin lapset tekivät pahaa Herran edessä ja palvelivat Baalia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Ja hylkäsivät Herran, isäinsä Jumalan, joka heidät Egyptin maalta oli johdattanut ulos, ja seurasivat vieraita jumalia niiden kansain jumalista, jotka heidän ympärillänsä asuivat, ja kumarsivat niitä, ja vihoittivat Herran;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Ja hylkäsivät Herran, ja palvelivat Baalia ja Astarotia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Niin julmistui Herran viha Israeliin, ja antoi heidät ryövärien käsiin, jotka heitä ryöstivät, ja myi heitä vihollistensa käsiin ympäristölle; ja ei he taitaneet enää seisoa vihollisiansa vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Mutta kuhunka ikänä he itsensä käänsivät, oli Herran käsi heitä vastaan onnettomuudeksi, niinkuin Herra heille sanonut ja niinkuin Herra heille vannonut oli; ja he aivan kovin ahdistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Ja Herra herätti tuomarit, jotka heitä vapahtivat niiden käsistä, jotka heitä ryöstivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Niin ei he tuomareitansakaan totelleet, vaan huorin tekivät vierasten jumalain kanssa, ja kumarsivat niitä; he harhailivat nopiasti siltä tieltä, jota heidän isänsä olivat vaeltaneet, kuullaksensa Herran käskyjä: ei he niin tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Kuin Herra herätti heille tuomarit, niin oli Herra tuomarein kanssa ja varjeli heitä heidän vihollistensa käsistä niinkauvan kuin tuomari eli; sillä Herra armahti heidän huokauksensa päälle niiden tähden, jotka heitä vaivasivat ja ahdistivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Mutta kuin tuomari kuollut oli, palasivat he, ja turmelivat sen enemmin kuin heidän isänsä, seuraten vieraita jumalia, palvellen ja kumartain niitä; ei he luopuneet teoistansa eikä kovasta tiestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Sentähden julmistui Herran viha niin Israelin päälle, että hän sanoi: että tämä kansa rikkoi minun liittoni, jonka minä käskin heidän isillensä, ja ei kuullut minun ääntäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Niin en minäkään tästedes aja pois heidän edestänsä yhtäkään niistä pakanoista, jotka Josua jätti kuoltuansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Että minä koettelisin Israelia heidän kauttansa, pysyvätkö he Herran teillä ja vaeltavat niissä, niinkuin heidän isänsä ovat pysyneet, vai eikö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Ja Herra jätti nämät pakanat, ettei hän nopiasti heitä ajanut ulos, ja ei antanut heitä Josuan käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Ja nämät ovat ne pakanat, jotka Herra jätti Israelia kiusaamaan, kaikkia niitä, jotka ei mitään tietäneet kaikista Kanaanin sodista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Ainoasti että Israelin lasten sukukunta olisivat oppineet sotimaan, ne jotka ei ennen sodasta mitään tietäneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Viisi Philistealaisten päämiestä ja kaikki Kanaanealaiset, Zidonilaiset ja Heviläiset, jotka asuivat Libanonin vuorella, BaalHermonin vuoresta Hamatiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Ja he jäivät kiusaamaan Israelia, että tiedettäisiin, tottelisivatko Herran käskyjä, jotka hän oli käskenyt heidän isillensä Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Kuin Israelin lapset asuivat keskellä Kanaanealaisia, Hetiläisiä, Amorilaisia, Pheresiläisiä, Heviläisiä ja Jebusilaisia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Ottivat he heidän tyttäriänsä emännäksensä ja antoivat tyttäriänsä heidän pojillensa, ja palvelivat heidän jumaliansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Ja Israelin lapset tekivät pahaa Herran edessä, ja unhottivat Herran Jumalansa, ja palvelivat Baalia ja metsistöitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Niin julmistui Herran viha Israeliin, ja hän myi heidät KusanRisataimin, Mesopotamian kuninkaan käteen; ja Israelin lapset palvelivat KusanRisataimia kahdeksan ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Ja Israelin lapset huusivat Herran tykö, ja Herra herätti heille vapahtajan, joka heitä vapahti, Otnielin, Kalebin nuorimman veljen Kenaksen pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Ja Herran henki tuli hänen päällensä, ja hän oli tuomari Israelissa, joka myös läksi sotaan; ja Herra antoi KusanRisataimin, Syrian kuninkaan tulla hänen käsiinsä, että hänen kätensä tuli voimalliseksi KusanRisataimin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Ja maa lepäsi neljäkymmentä ajastaikaa; ja Otniel Kenaksen poika kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Mutta Israelin lapset tekivät vielä pahaa Herran edessä; niin vahvisti Herra Eglonin, Moabilaisten kuninkaan Israelia vastaan, että he pahaa tekivät Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Ja hän kokosi tykönsä Ammonin lapset ja Amalekilaiset, ja meni ja löi Israelin, ja omisti Palmukaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Ja Israelin lapset palvelivat Eglonia, Moabilaisten kuningasta kahdeksantoistakymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Niin huusivat Israelin lapset Herran tykö, ja Herra herätti heille vapahtajan, Ehudin Geran pojan, Jeminin pojan, joka oli kurittu; ja Israelin lapset lähettivät hänen kanssansa lahjoja Eglonille, Moabilaisten kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Ja Ehud teki itsellensä kaksiteräisen miekan, kyynärää pitkän, sitoi sen vaatteensa alle, oikean reitensä päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Ja kantoi lahjat Eglonille, Moabilaisten kuninkaalle; ja Eglon oli sangen lihava mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Kuin hän oli lahjat antanut, päästi hän kansan, jotka olivat lahjoja kantaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Ja palasi itse epäjumalista Gilgalissa ja sanoi: minulla on, kuningas, jotakin salaista sinulle sanomista. Niin hän sanoi: vaiti! Ja kaikki menivät ulos, jotka hänen ympärillänsä seisoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Ja Ehud tuli hänen tykönsä, ja hän istui suvisalissa, joka hänellä oli, yksinänsä. Ja Ehud sanoi: minulla on Jumalan sana sinun tykös; niin nousi hän istuimeltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Mutta Ehud ojensi vasemman kätensä ja otti miekan oikialta reideltänsä, ja pisti hänen vatsaansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Niin että kahva meni sisälle terän kanssa, ja lihavuus peitti kahvan; sillä ei hän vetänyt ulos miekkaa hänen vatsastansa; ja rapa vuoti ulos hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Ja Ehud läksi ulos takaoven kautta, ja sulki salin ovet jälkeensä ja lukitsi ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Kuin hän oli tullut ulos, menivät kuninkaan palveliat sisälle, näkivät salin ovet suljetuiksi ja sanoivat: taitaa olla, että hän peittää jalkojansa suvisalin kammiossa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Ja odottivat niin kauvan, että he häpesivät: ja katso, ei heille kenkään salin ovia avannut; niin ottivat he avaimen ja avasivat: ja katso, heidän herransa makasi kuolleena maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Mutta Ehud pakeni heidän viipyissänsä, ja meni ohitse epäjumalain kuvia, ja pääsi Seiratiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Ja kuin hän sinne tuli, puhalsi hän torveen Ephraimin vuorella. Ja Israelin lapset menivät hänen kanssansa alas vuorelta, ja hän heidän edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Ja hän sanoi heille: seuratkaat minua, sillä Herra on antanut teidän vihamiehenne Moabilaiset teidän käsiinne. Ja he seurasivat häntä, ja voittivat Jordanin luotuspaikat Moabiin päin, ja ei sallineet yhdenkään mennä ylitse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Ja tappoivat Moabilaisia sillä ajalla lähes kymmenentuhatta miestä, kaikki parhaat ja väkevät sotamiehet, niin ettei yhtäkään heistä päässyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Ja niin tulivat Moabilaiset painetuksi sillä ajalla Israelin lasten kätten alle; ja maa lepäsi kahdeksankymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Hänen jälkeensä tuli Samgar Anatin poika, ja hän löi kuusisataa Philistealaista karjan kaareksella; ja hän vapahti myös Israelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Ja Israelin lapset vielä tekivät pahaa Herran edessä, kuin Ehud kuollut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Ja Herra myi heidät Jabinin, Kanaanealaisten kuninkaan käteen, joka hallitsi Hatsorissa; ja hänen sotajoukkonsa päämies oli Sisera: ja hän asui pakanain Harosetissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Ja Israelin lapset huusivat Herran tykö; sillä hänellä oli yhdeksänsataa rautavaunua, ja hän vaivasi tylysti Israelin lapsia kaksikymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Ja naispropheta Debora, Lapidotin emäntä tuomitsi Israelia siihen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Ja hän asui Deboran palmupuun alla, Raman ja BetElin välillä, Ephraimin vuorella; ja Israelin lapset tulivat sinne hänen tykönsä oikeuden eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Hän lähetti ja kutsui Barakin Abinoamin pojan Naphtalin Kedeksestä, ja sanoi hänelle: eikö Herra Israelin Jumala ole käskenyt: mene Taborin vuorelle ja ota kymmenentuhatta miestä kanssas Naphtalin ja Sebulonin lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Ja minä vedän sinun tykös Siseran, Jabinin sodanpäämiehen, Kisonin ojan tykö, vaunuinensa ja annan hänet sinun käsiis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Niin Barak sanoi hänelle: jos sinä menet kanssani, niin minäkin menen, mutta jollet sinä mene minun kanssani, niin en minä mene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Hän vastasi: minä kyllä menen sinun kanssas, mutta et sinä kunniaa voita tällä tiellä, jotas menet; sillä Herra myy Siseran vaimon käsiin. Niin Debora nousi ja meni Barakin kanssa Kedekseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Niin Barak kutsui kokoon Kedekseen Sebulonin ja Naphtalin ja rupesi jalkaisin matkustamaan kymmenentuhannen miehen kanssa; ja Debora meni hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Mutta Heber Keniläinen oli erinnyt Keniläisen Hobabin, Moseksen apen, lasten seasta, ja pannut majansa Zaanaimin tammen tykö, joka on Kedeksen tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Ja Siseralle ilmoitettiin, että Barak Abinoamin poika oli mennyt Taborin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Ja Sisera kokosi kaikki vaununsa yhteen, yhdeksänsataa rautaista vaunua, ja kaiken sen joukon, joka hänen kanssansa oli, pakanain Harosetissa Kisonin ojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Ja Debora sanoi Barakille: nouse, sillä tämä on se päivä, jona Herra on antanut Siseran sinun käsiis: eikö Herra mennyt sinun edelläs? Niin Barak meni Taborin vuorelta alas ja kymmenentuhatta miestä hänen perässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Ja Herra kauhisti Siseran kaikkein hänen vaunuinsa ja sotajoukkonsa kanssa Barakin miekan edessä, niin että Sisera hyppäsi vaunuistansa ja pääsi jalkapakoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Mutta Barak ajoi vaunuja ja sotajoukkoa takaa pakainain Harosetiin asti; ja kaikki Siseran joukko kaatui miekan terän edessä, niin ettei yksikään jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Mutta Sisera pakeni jalkaisin Jaelin majaan, joka oli Keniläisen Heberin emäntä; sillä Jabinin Hatsorin kuninkaan ja Keniläisen Heberin huoneen välillä oli rauha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Niin Jael kävi Siseraa vastaan ja sanoi hänelle: poikkee, minun herrani, poikkee minun tyköni, älä pelkää! Ja hän poikkesi hänen tykönsä majaan, ja hän peitti hänen vaatteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Ja hän sanoi hänelle: annas minun vähä vettä juodakseni, sillä minä janoon. Ja hän avasi rieskaleilin ja antoi hänen juoda, ja peitti hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Ja hän sanoi hänelle: seiso majan ovella, ja jos joku tulee ja kysyy sinulta ja sanoo: onko täällä ketään? niin sano: ei ketään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Ja Jael Heberin vaimo otti naulan majasta ja vasaran käteensä, ja meni hiljaksensa hänen tykönsä ja löi naulan hänen korvansa juuresta läpi, niin että se meni maahan kiinni; sillä hän makasi raskaasti ja oli hermotoin, ja hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Ja katso, Barak ajoi Siseraa takaa; ja Jael kävi häntä vastaan ja sanoi hänelle: tule, minä osoitan sinulle miehen, jota sinä etsit; ja hän tuli hänen tykönsä, ja katso: Sisera makasi kuolleena ja naula kiinni hänen korvansa juuressa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Näin nöyryytti Jumala sinä päivänä Jabinin Kanaanealaisten kuninkaan Israelin lasten eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Ja Israelin lasten kädet joutuivat ja vahvistuivat Jabinia Kanaanealaisten kuningasta vastaan, siihenasti että he hänen peräti hävittivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Niin veisasi Debora ja Barak Abinoamin poika sinä päivänä, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Että Israelin puolesta on täydellisesti kostettu ja että kansa antoi itsensä mieluisesti siihen, sentähden kiittäkäät Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Kuulkaat te kuninkaat ja ottakaat vaari te päämiehet: minä, minä veisaan Herralle, ja Herralle Israelin Jumalalle minä veisaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Herra, kuin sinä läksit Seiristä ja kävit Edomin kedolta, silloin maa vapisi, taivaat myös tiukkuivat, ja pilvet pisaroitsivat vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Vuoret vuosivat Herran edessä, itse Sinai Herran, Israelin Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Samgarin Anatin pojan aikana ja Jaelin aikana tiet katosivat, ja ne kuin kohdastansa käymän piti, kävivät vääriä polkuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Talonpojat puuttuivat Israelista, ne puuttuivat siihenasti kuin minä Debora tulin, siihenasti kuin minä tulin äidiksi Israeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Hän valitsi uusia jumalia: silloin oli sota porteissa: ei siellä nähty kilpeä eikä keihästä neljänkymmenen tuhannen seassa Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Minun sydämelläni on ilo Israelin valtamiehistä: he ovat hyväntahtoiset kansan seassa; kiittäkäät Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Te jotka ajatte kaunisten aasein päällä, te jotka istutte oikeudessa, te jotka käytte teitä myöten, puhukaat näistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Kussa ampujat huusivat vedenkantajain seassa, siellä julistettakaan Herran vanhurskautta ja hänen talonpoikainsa vanhurskautta Israelissa; silloin meni Herran kansa porttein tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Nouse, nouse, Debora: nouse, nouse ja veisaa virsiä, valmista itses, Barak, vangiksi ota sinun vangitsiat, sinä Abinoamin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Silloin rupesi se jäänyt vallitsemaan voimallista kansaa: Herra on hallinnut väkeviä minun kauttani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Ephraimista oli heidän juurensa Amalekia vastaan, ja sinun jälkees BenJamin sinun kansoissas; Makirista ovat tulleet hallitsiat ja Sebulonista kirjoittajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Isaskarin päämiehet olivat myös Deboran kanssa, ja Isaskar oli niinkuin Barak laaksoon lähetetty jalkaväkinensä; Rubenin eroituksessa ovat suuret sydämen ajatukset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Miksis istuit kahden joukon välillä, kuullakses laumain määkynätä? Rubenin eroituksessa ovat suuret sydämen ajatukset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead jäi toiselle puolelle Jordania, ja miksi Dan asui haahtein seassa? Asser istui meren satamissa ja asui langenneissa kylissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Sebulonin kansa antoi henkensä alttiiksi kuolemaan, Naphtali myös, kedon korkeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Kuninkaat tulivat ja sotivat; silloin sotivat Kanaanin kuninkaat Taanakissa Megiddon veden tykönä: ei he saaneet rahaa saaliiksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Taivaasta sotivat tähdet juoksussansa, he sotivat Siseraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Kisonin ojan kieritti heitä, Kedumin oja, Kisonin oja; minun sieluni tallaa väkeviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Silloin sotkuivat hevosten kaviot heitä, heidän väkeväinsä hätäisessä paossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Kirotkaat Merosta, sanoi Herran enkeli, kiroten kirotkaat hänen asuvaisiansa, ettei he tulleet Herran avuksi, Herran avuksi sankarien seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Siunattu olkoon Jael vaimoin seassa, Heberin Keniläisen emäntä, siunattu olkoon hän majoissansa vaimoin seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Kuin hän vettä anoi, niin hän rieskaa antoi; hän kantoi voita kalliissa maljassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Hän otti naulan käteensä ja sepän vasaran oikiaan käteensä, ja löi Siseran ja runteli hänen päänsä, musersi ja lävisti hänen korvainsa juuren.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Hänen jalkainsa juureen kumarsi hän maahan, hän lankesi maahan ja pani maata: hänen jalkainsa juureen kumarsi hän itsensä ja lankesi maahan, siinä kuin hän kumarsi itsensä, siinä hän myös makasi hukutettuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Siseran äiti katsoi akkunasta ja itki huutain häkistä: miksi viipyy hänen vaununsa tulemasta? miksi ovat hänen vaununsa pyörät niin jääneet jälkeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Ne viisaimmat hänen ylimmäisistä vaimoistansa vastasivat häntä, että hän sanojansa kertoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Eikö he löydä ja jaa saalista, jokaiselle miehelle piian taikka kaksi, ja Siseralle kirjavia ja ommeltuja vaatteita, neulalla ommeltuja vaatteita, kirjavia molemmin puolin kaulan ympäri, saaliiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Kaikki sinun vihollises niin hukkukoon, Herra! Mutta ne, kuin sinua rakastavat, olkoon niinkuin ylöskäypä aurinko voimassansa. Ja maa oli levossa neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Ja Israelin lapset taas tekivät pahaa Herran edessä; ja Herra antoi heidät Midianilaisten käteen seitsemäksi ajastajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Koska Midianilaisten käsi oli ylen ankara Israelin päällä, tekivät Israelin lapset heillensä Midianilaisten tähden hautoja vuorille, ja luolia ja linnoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Ja kuin Israel jotakin kylvi, tulivat Midianilaiset ja Amalekilaiset, ja ne itäiseltä maalta heidän päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Ja asettivat leirinsä heitä vastaan ja turmelivat kaiken maan kasvun Gasariin asti; ja ei yhtäkään elatusta Israelille jättäneet ei lampaita, härkiä eikä aaseja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Sillä he tulivat laumoinensa ja majoinensa, ja niinkuin suuri metsäsirkkain paljous, että sekä he ja heidän kamelinsa olivat lukemattomat, ja tulivat hävittämään maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Niin Israel peräti köyhtyi Midianilaisten tähden. Silloin huusivat Israelin lapset Herran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Ja kuin Israelin lapset huusivat Herran tykö Midianilaisten tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Lähetti Herra prophetan Israelin lasten tykö, joka sanoi heille: näin sanoo Herra Israelin Jumala: minä johdatin teidät Egyptistä, ja talutin teidät ulos orjuuden huoneesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Ja pelastin teidät Egyptiläisten kädestä ja kaikkein kädestä, jotka teitä vaivasivat, jotka minä ajoin teidän edestänne ulos, ja annoin teille heidän maansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Ja minä sanoin teille: Minä olen Herra teidän Jumalanne, älkäät peljätkö Amorilaisten jumalia, joiden maassa te asutte; ja ette totelleet minun ääntäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Ja Herran enkeli tuli ja istui tammen alla Ophrassa, joka Joaksen Abiesriläisen oma oli; ja hänen poikansa Gideon tappoi nisuja viinakuurnan tykönä, saadaksensa ne säilytetyksi Midianilaisilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Silloin ilmaantui Herran enkeli hänelle ja sanoi: Herra olkoon sinun kanssas, sinä väkevä sotamies!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Niin sanoi Gideon hänelle: minun Herrani, jos Herra on meidän kanssamme, miksi meille siis kaikki nämät tapahtuneet ovat? Kussa ovat kaikki hänen ihmeensä, jotka meidän isämme ilmoittivat meille ja sanoivat: eikö Herra meitä johdattanut Egyptistä? Mutta nyt on Herra meidät hyljännyt ja antanut Midianilaisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Ja Herra käänsi itsensä hänen tykönsä ja sanoi: mene tässä väkevyydessäs! Sinä vapahdat Israelin Midianilaisten kädestä: enkö minä ole sinua lähettänyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Hän sanoi hänelle: minun Herrani, millä minä vapahdan Israelin? Katso, minun sukuni on kaikkein köyhin Manassessa, ja minä olen kaikkein pienin minun isäni huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Ja Herra sanoi hänelle: totisesti minä olen sinun kanssas, ja sinä lyöt Midianilaiset niinkuin yhden miehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Mutta hän sanoi hänelle: jos minä olen nyt löytänyt armon sinun tykönäs, niin anna minulle merkki, että sinä se olet, joka minun kanssani puhut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Älä kumminkaan täältä lähde, siihenasti kuin minä tulen sinun tykös, ja kannan minun ruokauhrini ja panen sinun etees. Hän sanoi: minä olen siihenasti kuin sinä palajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gideon tuli ja teurasti vohlan, ja otti ephan happamattomia jauhoja, ja pani lihan koriin ja lihan liemen pataan, ja vei hänen tykönsä tammen alle ja pani eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Ja Jumalan enkeli sanoi hänelle: ota liha ja happamaton leipä, ja pane tämän kiven päälle, ja kaada liemi ulos; ja hän teki niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Ja Herran enkeli ojensi sauvansa pään, joka oli hänen kädessänsä, ja satutti lihaan ja happamattomaan leipään, ja tuli nousi kivestä ja kulutti lihan ja happamattoman leivän. Ja Herran enkeli katosi hänen silmäinsä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Kun Gideon näki sen olevan Herran enkelin, sanoi hän: Herra, Herra, olenko minä niin nähnyt Herran enkelin kasvoista kasvoihin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Mutta Herra sanoi hänelle: rauha olkoon sinulle! älä pelkää, et sinä kuole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Ja Gideon rakensi Herralle alttarin siinä, jonka hän kutsui rauhan Herraksi. Se on vielä tänäpänä Abiesriläisten Ophrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Ja sinä yönä sanoi Herra hänelle: ota mulli isäs karjasta ja toinen mulli, joka on seitsemännellä vuodella, ja kukista Baalin alttari, joka on sinun isälläs, ja hävitä metsistö, joka siinä tykönä on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Ja rakenna Herralle sinun Jumalalles alttari tälle korkialle vuorelle, sopivaiselle paikalle, ja ota toinen mulleista ja uhraa se polttouhriksi metsistön puilla jonka sinä hakkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Silloin otti Gideon kymmenen miestä palvelioistansa ja teki niinkuin Herra hänelle sanonut oli. Mutta hän pelkäsi ei saavansa sitä päivällä tehdä isänsä huoneen ja kaupungin asuvaisten tähden, ja teki sen yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Kuin kaupungin kansa aamulla nousivat, katso, Baalin alttari oli kukistettu ja metsistö maahan hakattu, joka sen tykönä oli, ja toinen mulli pantu polttouhriksi alttarille, joka siihen rakennettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Ja he sanoivat toinen toisellensa: kuka on tämän tehnyt? Koska he visusti kyselivät ja tutkistelivat, niin he sanoivat: Gideon Joaksen poika sen teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Niin kaupungin asuvaiset puhuivat Joakselle, sanoen: anna poikas tulla tänne! Hänen pitää kuoleman; sillä hän on Baalin alttarin kukistanut ja metsistön hakannut, joka siinä tykönä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Niin Joas sanoi kaikille, jotka seisoivat häntä vastaan: riitelettekö te Baalin puolesta? autatteko te häntä? Joka riitelee hänen puolestansa, sen pitää kuoleman ennen aamua: jos hän on jumala, niin kostakoon itse, että hänen alttarinsa on kukistettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Ja siitä päivästä kutsui hän hänen JerubBaal ja sanoi: Baal kostakoon itse, että hänen alttarinsa kukistettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Kuin kaikki Midianilaiset ja Amalekilaiset ja ne itäiseltä maalta kokosivat itsensä yhteen, ja menivät ja sioittivat heitänsä Jisreelin laaksoon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Niin Herran henki täytti Gideonin, ja hän puhalsi basunaan ja kutsui Abieserin seuraamaan itsiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Ja hän lähetti sanan koko Manasselle ja kutsui myös heitä seuraamaan. Hän lähetti myös sanan Asserille, Sebulonille ja Naphtalille, ja hekin tulivat heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Ja Gideon sanoi Jumalalle: jos sinä vapahdat Israelin minun käteni kautta, niinkuin sinä sanonut olet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Katso, minä panen villaisen nahan pihalle: jos kaste tulee ainoastaan nahan päälle ja kaikki muu maa on kuiva, niin minä ymmärrän, ettäs minun käteni kautta Israelin vapahdat, niinkuin sinä sanonut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Ja se tapahtui niin: kuin hän toisena päivänä varhain nousi, kääri hän nahan kokoon ja pusersi kasteen nahasta ja täytti maljan vedestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Ja Gideon sanoi Jumalalle: älköön sinun vihas syttykö minua vastaan, jos minä vielä kerran puhun: minä koettelen vielä kerran sitä nahalla: anna ainoastaan nahan kuivan olla ja kaikella muulla maalla kasteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Jumala teki myös niin sinä yönä: ja nahka ainoastaan jäi kuivaksi, ja kaste tuli kaiken maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Silloin nousi JerubBaal (se on Gideon) varhain aamulla ja kaikki väki joka hänen kanssansa oli, ja sioittivat heitänsä Harodin lähteen tykö, niin että Midianilaisten leiri oli pohjaan päin, vartian kukkulan takana, laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Ja Herra sanoi Gideonille: ylen paljo on väkeä sinun kanssas: jos minä antaisin Midianin heidän käsiinsä, kerskais Israel minua vastaan ja sanois: minun käteni vapahti minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Niin anna nyt huutaa kansan korvissa ja sanoa: joka pelkuri ja hämmästynyt on, palatkaan ja nopiasti rientäkään Gileadin vuorelta. Silloin palasi kansaa takaperin kaksikolmattakymmentä tuhatta, ja kymmenentuhatta jäi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Ja Herra sanoi Gideonille: vielä on paljo kansaa, vie heitä veden tykö, siellä minä koettelen heitä sinulle: ja josta minä sanon sinulle: tämä menköön sinun kanssas, hän myös menee sinun kanssas: ja josta minä taas sanon sinulle: älköön hän menkö sinun kanssas, ei hänen pidä menemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Ja hän vei kansan veden tykö; ja Herra sanoi Gideonille: joka vettä latkii kielellänsä niinkuin koira latkii, aseta häntä erinänsä seisomaan, niin myös kaikki, jotka heitänsä polvillensa kumartavat juodessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Silloin oli niitä, jotka latkivat kädestänsä suuhunsa, kolmesataa miestä; ja kaikki muu kansa olivat kumartaneet polvillensa juomaan vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Ja Herra sanoi Gideonille: kolmensadan miehen kautta, jotka latkivat, vapahdan minä teitä, ja annan Midianilaiset sinun käsiis; mutta kaikki muu kansa menkään kukin siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Ja kansa otti evään myötänsä ja basunansa, mutta kaikki muut Israelin miehet antoi hän mennä itsekunkin majaansa, ja vahvisti itsensä ainoasti kolmellasadalla miehellä; ja Midianilaisten leiri oli hänen edessänsä alhaalla laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Ja Herra sanoi sinä yönä hänelle: nouse ja mene alas leiriin, sillä minä olen antanut heidät sinut käsiis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Jos sinä pelkäät mennä sinne, niin anna palvelias Puran mennä sinun kanssas leiriin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Ettäs kuulisit, mitä he puhuvat; sitte sinun kätes vahvistuvat ja sinä menet leiriin. Niin hän meni palveliansa Puran kanssa leiriin, sille paikalle, kussa vartiat olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Mutta Midianilaiset ja Amalekilaiset ja kaikki ne itäiseltä maalta, makasivat laaksossa niinkuin metsäsirkkain paljous ja heidän kamelinsa olivat lukemattomat, niinkuin santa meren rannalla paljouden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Koska Gideon tuli, katso, niin jutteli yksi kumppanillensa unen ja sanoi: katso, minä näin unta ja olin näkevinäni ohraisen porokakun kierittävän itsensä Midianilaisten leiriin, ja tulevan majaan asti, ja lyövän sen päälle, niin että se lankesi maahan, ja kukistavan sen ylösalaisin, niin että maja maassa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Jolle se toinen vastasi ja sanoi: ei se ole muuta, kuin Gideonin Joaksen pojan Israelin miehen miekka: Jumala on antanut Midianilaiset hänen käsiinsä kaiken heidän sotajoukkonsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Kuin Gideon kuuli unen juteltavan ja sen selityksen, niin hän kumartaen rukoili, ja palasi Israelin leiriin ja sanoi: valmistakaat itsenne, sillä Herra on antanut Midianilaisten sotajoukon teidän käsiinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Ja hän jakoi ne kolmesataa miestä kolmeen joukkoon, ja antoi basunat heidän jokaisen käteensä ja tyhjät savi-astiat, ja lamput astiain sisälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Ja sanoi heille: katsokaat minua, ja tehkäät te niin: katso, kuin minä tulen leirin ääreen, niinkuin minä teen, niin myös te tehkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Ja minä puhallan basunaan ja kaikki jotka minun kanssani ovat, niin myös teidän pitää puhaltaman basunaan kaiken leirin ympäri, ja teidän pitää sanoman: (tässä) Herra ja Gideon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Silloin tuli Gideon leiriin, ja sata miestä jotka hänen kanssansa olivat, ensimäisten vartiain tykö, jotka siellä asetetut olivat, herättivät ainoasti vartiat, ja puhalsivat basuniin, ja rikkoivat saviastiat, jotka olivat heidän käsissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Ja ne kolme joukkoa puhalsivat basunaan, ja rikkoivat saviastiat, mutta lamput he tempasivat vasempaan käteensä ja basunat oikiaan käteensä, joihin he puhalsivat ja huusivat: (tässä) Herran ja Gideonin miekka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Ja jokainen seisoi siallansa leirin ympärillä. Silloin rupesi kaikki leiri juoksemaan, huutamaan ja pakenemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Ja koska ne kolmesataa miestä puhalsivat basuniin, sovitti Herra niin, että yhden miekka kääntyi toista vastaan siinä sotajoukossa; ja sotaväki pakeni Bethsittan ja Zeredataan, Abel Meholan rajan viereen, Tabatin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Ja Israelin miehet kokoontuivat Naphtalista, Asserista ja kaikesta Manassesta, ja ajoivat Midianilaisia takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Ja Gideon lähetti sanansaattajat kaikelle Ephraimin vuorelle, sanoen: tulkaat alas Midianilaisia vastaan ja ennättäkäät heiltä vedet BetBaraan ja Jordaniin asti. Niin kokoontuivat kaikki Ephraimin miehet ja ennättivät vedet BetBaraan ja Jordaniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Ja he ottivat kaksi Midianilaisten päämiestä kiinni, Orebin ja Zebin, ja tappoivat Orebin Orebin kalliolla, ja Zebin he tappoivat Zebin viinakuurnassa, ja ajoivat Midianilaisia takaa; mutta Orebin ja Zebin päät kantoivat he Gideonille Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Ja Ephraimin miehet sanoivat hänelle: miksis tämän meille teit, ettes kutsunut meitä, kuin sinä menit sotimaan Midianilaisia vastaan? ja he riitelivät kovin hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Niin hän vastasi heitä: mitä minä olen nyt tehnyt niinkuin te? Eikö Ephraimin viinapuun oksa parempi ole, kuin Abieserin koko viinamarjan läjä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Jumala antoi Midianilaisten päämiehet Orebin ja Zebin teidän käsiinne: kuinka olisin minä taitanut niin tehdä, kuin te teitte? Ja kuin hän sen sanoi, asettui heidän vihansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Kuin Gideon tuli Jordanin tykö, meni hän sen ylitse, ja ne kolmesataa miestä jotka hänen kanssansa olivat, ja he olivat väsyneet ja ajoivat takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Ja hän sanoi Sukkotin asuvaisille: antakaat vähä leipää väelle joka minun kanssani on; sillä he ovat väsyneet, että minä saisin ajaa Midianilaisten kuninkaita Sebaa ja Zalmunnaa takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Mutta Sukkotin päämiehet sanoivat: onko Seban ja Zalmunnan kämmen juuri jo sinun kädessäs, että meidän pitää sinun sotaväelles leipää antaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon sanoi: sentähden kuin Herra minun käsiini antaa Seban ja Zalmunnan, niin minä muserran teidän lihanne korven orjantappuroilla ja ohdakkeilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Ja hän meni sieltä ylös Penueliin ja puhui heille myös niin. Ja Penuelin kansa vastasi häntä niinkuin Sukkotinkin miehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Niin puhui hän myös Penuelin kansalle, sanoen: kuin minä rauhassa palajan, kukistan minä tämän tornin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Mutta Seba ja Zalmunna olivat Karkorissa ja heidän sotajoukkonsa heidän kanssansa lähes viisitoistakymmentä tuhatta, kaikki jotka jäivät koko sotaväen joukosta itäiseltä maalta; sillä sata ja kaksikymmentä tuhatta miekan vetävää miestä oli siellä langennut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Ja Gideon meni ylös niiden tietä, jotka majoissa asuvat itäisellä puolella Nobatia ja Jogbehaa, ja löi leirin, sillä he olivat suruttomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Ja Seba ja Zalmunna pakenivat, mutta hän ajoi heitä takaa, ja sai ne kaksi Midianilaisten kuningasta Seban ja Zalmunnan kiinni, ja peljätti kaiken heidän sotaväkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Ja Gideon Joaksen poika palasi sodasta, ennenkuin aurinko nousi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Ja sai yhden palvelian kiinni, joka oli Sukkotista, ja kysyi häneltä: ja se kirjoitti hänelle Sukkotin päämiehet ja vanhimmat, seitsemänkahdeksattakymmentä miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Ja hän tuli Sukkotiin kansan tykö ja sanoi: tässä on Seba ja Zalmunna, joilla te pilkkasitte minua, sanoen: onko Seban ja Zalmunnan kämmen jo juuri sinun kädessäs, että meidän pitäis sentähden sinun sotaväelles, joka väsynyt on, leipää antaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Ja hän otti ne kaupungin vanhimmat ja korven orjantappuroita ja ohdakkeita, ja antoi Sukkotin miehet piestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Ja kukisti Penuelin tornin, ja tappoi kaupungin kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Ja hän sanoi Seballe ja Zalmunnalle: minkämuotoiset miehet ne olivat, jotka te tapoitte Taborissa? He sanoivat: ne olivat sinun muotoises, kauniit kuin kuninkaan pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Ja hän sanoi: ne olivat minun veljeni, minun äitini pojat: niin totta kuin Herra elää, jos te olisitte antaneet heidän elää, niin en tappaisi minä teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Ja hän sanoi Jeterille esikoisellensa: nouse ja tapa heitä, mutta nuorukainen ei vetänyt miekkaansa, sillä hän pelkäsi, että hän oli vielä nuorukainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Mutta Seba ja Zalmunna sanoivat: nouse sinä meitä lyömään, sillä niinkuin mies on, niin on myös hänen voimansa. Niin Gideon nousi ja tappoi Seban ja Zalmunnan, ja otti nastat, jotka heidän kameleinsa kaulassa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Silloin sanoivat Israelin miehet Gideonille: hallitse sinä meitä, sinä ja sinun poikas, ja sinun poikas poika; sillä sinä vapahdit meidät Midianilaisten käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Mutta Gideon sanoi heille: en minä tahdo hallita teitä, ei myös minun poikani pidä teitä hallitseman, vaan Herra olkoon teidän hallitsianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Ja Gideon sanoi heille: yhtä minä anon teiltä: jokainen antakoon minulle korvarenkaat, kukin saaliistansa; sillä he olivat Ismaelilaisia, ja heillä olivat kultaiset korvarenkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Ja he sanoivat: me annamme mielellämme; ja levittivät vaatteen, jonka päälle itsekukin heitti ne korvarenkaat, jotka he ryövänneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Ja ne kultaiset korvarenkaat, joita hän anonut oli, painoivat tuhannen ja seitsemänsataa sikliä kultaa, ilman nastoja, käädyjä ja purpuravaatteita, joita Midianilaisten kuninkaat kantoivat, ja ilman heidän kameleinsa kultaisia kaulasiteitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Ja Gideon teki niistä päällisvaatteen ja pani sen omaan kaupunkiinsa Ophraan; ja koko Israel teki huorin sen jälkeen siinä, ja se tuli Gideonille ja hänen huoneellensa paulaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Ja niin Midianilaiset alennettiin Israelin lasten edessä, ja ei enää nostaneet ylös päätänsä; ja maa oli levossa neljäkymmentä ajastaikaa, niinkauvan kuin Gideon eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Ja JerubBaal Joaksen poika meni ja asui omassa huoneessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Ja Gideonilla oli seitsemänkymmentä poikaa, jotka hänen kupeistansa tulleet olivat; sillä hänellä oli monta emäntää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Ja hänen jalkavaimonsa, joka hänellä Sikemissä oli, synnytti myös hänelle pojan, ja kutsui hänen nimensä Abimelek.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Ja Gideon Joaksen poika kuoli hyvällä ijällä ja haudattiin isänsä Joaksen hautaan Ophrassa, joka Abiesriläisten oma oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Kuin Gideon kuollut oli, käänsi Israelin kansa itsensä huorin tekemään Baalin jälkeen ja teki BaalBeritin itsellensä jumalaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Ja Israelin lapset ei enää muistaneet Herraa Jumalaansa, joka heidät vapahti kaikilta heidän vihollisiltansa, ympäristöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Ja ei he tehneet yhtään laupiutta JerubBaalin Gideonin huoneelle kaikesta hyvästä, minkä hän Israelille teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Mutta Abimelek, JerubBaalin poika, meni Sikemiin äitinsä veljein tykö, puhui heille ja koko äitinsä isän huoneen sukukunnalle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Puhukaat nyt kaikkein päämiesten korvissa Sikemissä: mikä teille on parempi, että seitsemänkymmentä miestä, kaikki JerubBaalin pojat, hallitsevat teitä, eli jos yksi mies hallitsee teitä? Ja muistakaat, että minä olen teidän luunne ja lihanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Niin puhuivat hänen äitinsä veljet kaikki nämät sanat hänestä kaikkein Sikemin päämiesten korvissa; ja heidän sydämensä käännettiin AbiMelekin jälkeen, sillä he sanoivat: hän on meidän veljemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Ja he antoivat hänelle seitsemänkymmentä hopiapenninkiä BaalBeritin huoneesta, joilla AbiMelek palkkasi itsellensä valtojamia ja joutilaita miehiä, jotka häntä seurasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Ja hän tuli isänsä huoneesen Ophraan, ja murhasi seitsemänkymmentä veljeänsä, JerubBaalin poikaa, yhden kiven päällä. Mutta Jotam, nuorin JerubBaalin pojista jäi; sillä hän kätki itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Ja kaikki päämiehet Sikemistä ja koko Millon huone kokoontuivat, ja menivät ja asettivat Abimelekin kuninkaaksi korkian tammen tykönä, joka Sikemissä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Kuin tämä sanottiin Jotamille, meni hän pois ja seisoi Gerisimin vuoren kukkulalla, korotti äänensä ja huusi ja sanoi heille: kuulkaat minua, te Sikemin päämiehet, että Jumala myös kuulis teitä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Puut menivät kerran yksimielisesti voitelemaan itsellensä kuningasta ja sanoivat öljypuulle: ole meidän kuninkaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Mutta öljypuu vastasi heitä: pitääkö minun luopuman lihavuudestani, jolla sekä jumalia ja myös ihmisiä minussa kunnioitetaan, ja menemän ja korottaman itseni puiden ylitse?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Niin puut sanoivat fikunapuulle: tule sinä ja ole meidän kuninkaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Mutta fikunapuu sanoi heille: pitääkö minun luopuman makeudestani ja parhaasta hedelmästäni, ja menemän ja korottaman itseni puiden ylitse?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Niin sanoivat puut viinapuulle: tule sinä ja ole meidän kuninkaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Mutta viinapuu sanoi heille: pitääkö minun luopuman viinastani, joka sekä jumalat että ihmiset ilahuttaa, ja menemän ja korottaman itseni puiden ylitse?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Niin sanoivat kaikki puut orjantappuralle: tule sinä ja ole meidän kuninkaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Ja orjantappura sanoi puille: onko se tosi, että tahdotte minua voidella teillenne kuninkaaksi, niin tulkaat ja levätkäät minun varjoni alla. Mutta jos ei, niin lähtekään tuli orjantappurapensaasta ja polttakaan sedripuut Libanonissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Oletteko te siis nyt oikein ja toimellisesti tehneet, kuin AbiMelekin kuninkaaksi teitte, ja oletteko te oikein tehneet JerubBaalia ja hänen huonettansa vastaan? Ja oletteko niin tehneet häntä vastaan kuin hän ansaitsikin teiltä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Että minun isäni on teidän edessänne sotinut ja antanut henkensä alttiiksi, vapahtaaksensa teitä Midianilaisten kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Ja te olette nousseet minun isäni huonetta vastaan tänäpänä ja olette tappaneet hänen poikansa, seitsemänkymmentä miestä yhden kiven päällä; ja teitte teillenne AbiMelekin, hänen piikansa pojan, kuninkaaksi Sikemin päämiesten ylitse, että hän teidän veljenne on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Jos olette oikein ja toimellisesti tehneet JerubBaalia ja hänen huonettansa vastaan tänäpänä, niin iloitkaat AbiMelekistä, ja hän myös iloitkaan teistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Mutta jollei, niin lähteköön tuli AbiMelekistä ja polttakoon Sikemin päämiehet ja Millon huoneen; lähteköön myös tuli Sikemin päämiehistä ja Millon huoneesta ja polttakoon AbiMelekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Ja Jotam pakeni ja vältti, ja meni Beeraan ja asui siellä veljensä AbiMelekin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Kuin AbiMelek jo kolme vuotta oli hallinnut Israelia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Lähetti Jumala pahan hengen AbiMelekin ja Sikemin päämiesten välille: ja Sikemin päämiehet asettivat itsensä AbiMelekiä vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Että se vääryys, jonka hän teki seitsemällekymmenelle JerubBaalin pojalle, ja heidän verensä tulis ja pantaisiin AbiMelekin heidän veljensä päälle, joka heidät oli murhannut, ja Sikemin päämiesten päälle, jotka olivat vahvistaneet hänen kätensä veljiänsä murhaamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Ja Sikemin päämiehet panivat väijyjiä vuorten kukkoille häntä vastaan, ja he ryöväsivät tiellä kaikki, jotka siitä matkustivat; ja se ilmoitettiin AbiMelekille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Niin tuli Gaal Ebedin poika ja hänen veljensä, ja menivät Sikemiin; ja Sikemin päämiehet uskalsivat hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Ja menivät kedolle, ja poimivat viinamäkensä ja sotkuivat, ja iloiten veisasivat, ja menivät jumalansa huoneeseen, söivät ja joivat, ja kirosivat AbiMelekiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Ja Gaal Ebedin poika sanoi: mikä on AbiMelek ja mikä on Sikem, että me häntä palvelemme? eikö hän ole JerubBaalin poika, ja Sebul hänen päämiehensä? Palvelkaat paremmin Hemorin Sikemin isän miehiä: miksi meidän pitää häntä palveleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Jumala tekis että kansa olis minun käteni alla, että minä ajaisin AbiMelekin ulos. Niin sanottiin AbiMelekille: enennä sotajoukkos ja käy ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Kuin Sebul, kaupungin päämies, kuuli Gaalin, Ebedin pojan, sanan, vihastui hän sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Ja lähetti sanansaattajat AbiMelekille salaisesti, sanoen: Katso, Gaal, Ebedin poika ja hänen veljensä tulivat Sikemiin, tekemään kaupunkia sinulle vastahakoiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Niin nouse nyt yöllä, sinä ja sinun väkes, joka myötäs on, ja väijy kedolla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Ja aamulla, kuin aurinko nousee, ole varhain ylhäällä ja karkaa kaupungin päälle. Ja kuin hän ja se kansa, joka hänen myötänsä on, tulevat sinun tykös, niin tee hänen kanssansa niinkuin sinun kätes löytää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'AbiMelek nousi yöllä ja kaikki kansa, joka hänen seurassansa oli, ja asetti vartian Sikemin eteen neljään joukkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Ja Gaal, Ebedin poika, kävi kaupungin portin eteen; mutta AbiMelek nousi väijymisestänsä sen väen kanssa, joka hänen myötänsä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Kuin Gaal näki kansan, sanoi hän Sebulille: katso, tuolta tulee kansan joukko alas vuorten kukkoilta. Ja Sebul sanoi hänelle: sinä näet vuorten varjon niinkuin ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal puhui taas ja sanoi: katso, tuolta tulee kansan joukko alas keskeltä maata ja yksi joukko tulee Noituustammen tieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Niin sanoi Sebul hänelle: kussa on nyt sinun suus, joka sanoi: kuka on AbiMelek, että meidän häntä palveleman pitää? eikö tämä ole se kansa, jonkas olet katsonut ylön? käy nyt ulos ja sodi häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Ja Gaal meni Sikemin päämiesten edellä ja soti AbiMelekiä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Mutta AbiMelek ajoi häntä takaa, ja hän pakeni hänen edestänsä; ja monta lankesi lyötynä kaupungin porttiin saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Ja AbiMelek oli Arumassa; mutta Sebul ajoi Gaalin ja veljensä ulos, niin ettei he saaneet olla Sikemissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Ja aamulla läksi kansa kedolle; ja kuin AbiMelek sen sai tietää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Otti hän kansan ja jakoi kolmeen osaan, ja asetti väijytyksen kedolle. Kuin hän siis näki, että kansa läksi kaupungista ulos, lankesi hän heidän päällensä ja löi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Mutta AbiMelek sen joukon kanssa, joka hänen seurassansa oli, lankesi heidän päällensä, ja kävivät kaupungin porttiin saakka, ja ne kaksi joukkoa lankesivat niiden päälle, jotka kedolla olivat, ja löivät heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Sitte soti AbiMelek kaupunkia vastaan kaiken sen päivän, ja voitti kaupungin, ja tappoi kansan, joka siellä oli, ja kukisti kaupungin, ja kylvi suolaa sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Kuin kaikki päämiehet, jotka Sikemin tornissa asuivat, sen kuulivat, menivät he linnaan jumalan Beritin huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Ja AbiMelekille ilmoitettiin kaikki Sikemin tornin päämiehet kokoontuneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Niin meni AbiMelek ylös Salmonin vuorelle, hän ja kaikki kansa joka hänen seurassansa oli, ja AbiMelek otti kirveen käteensä ja hakkasi oksan puusta, pani olallensa ja kantoi sen, ja sanoi kansalle, joka hänen seurassansa oli: mitä te näitte minun tekevän, se myös te nopiasti tehkäät niinkuin minäkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Ja hakkasi myös kaikki kansa itsekukin oksansa ja seurasi AbiMelekiä, ja heittivät ne linnan päälle, ja polttivat niillä linnan tulessa; niin että myös kaikki Sikemin tornin päämiehet kuolivat, lähes tuhannen miestä ja vaimoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Niin AbiMelek meni Tebetseen, piiritti ja voitti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Mutta siinä oli vahva torni keskellä kaupunkia, johonka kaikki pakenivat sekä miehet että vaimot ja kaikki kaupungin päämiehet, ja sulkivat kiinni perässänsä, ja kiipesivät tornin katon päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Sitte tuli AbiMelek tornin tykö, soti sitä vastaan, ja tuli tornin oven eteen, sitä tulella polttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Mutta yksi vaimo heitti myllynkiven kappaleen AbiMelekin päähän ja löi hänen pääkallonsa rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Sitte kutsui AbiMelek nopiasti palveliansa, joka kantoi hänen aseitansa, ja sanoi hänelle: vedä miekkas ulos ja tapa minua, ettei minusta sanottaisi: vaimo tappoi hänen; niin pisti palvelia hänen lävitse, ja hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Ja kuin Israelin miehet näkivät AbiMelekin kuolleeksi, menivät he itsekukin paikallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Ja näin maksoi Jumala AbiMelekille sen pahuuden, minkä hän teki isäänsä vastaan, että hän tappoi seitsemänkymmentä veljeänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Niin myös kaiken sen pahuuden, minkä Sikemin miehet tekivät, antoi Jumala tulla heidän päänsä päälle; ja heidän päällensä tuli Jotamin JerubBaalin pojan kirous.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'AbiMelekin jälkeen nousi Isaskarilainen Tola, Dodan pojan Puan poika, auttamaan Israelia. Ja hän asui Samirissa, Ephraimin vuorella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Ja tuomitsi Israelia kolmekolmattakymmentä ajastaikaa, ja kuoli ja haudattiin Samiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Hänen jälkeensä nousi Jair Gileadilainen ja tuomitsi Israelia kaksikolmattakymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Ja hänellä oli kolmekymmentä poikaa, jotka ajoivat kolmellakymmenellä aasin varsalla, ja heillä oli kolmekymmentä kaupunkia, jotka kutsuttiin Jairin kyliksi tähän päivään asti ja ovat Gileadin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Ja Jair kuoli ja haudattiin Kamoniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Mutta Israelin lapset tekivät vielä pahaa Herran edessä, ja palvelivat Baalia ja Astarotia, ja Syrian jumalia, ja Zidonin jumalia, ja Moabin jumalia, ja Ammonin lasten jumalia, ja Philistealaisten jumalia, ja luopuivat Herrasta ja ei palvelleet häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Niin julmistui Herran viha Israelin ylitse, ja hän myi heidät Philistealaisten ja Ammonin lasten käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Ja he vaativat ja vaivasivat siitä vuodesta kaikkia Israelin lapsia kahdeksantoistakymmentä ajastaikaa, kaikkia Israelin lapsia, jotka olivat tällä puolella Jordania, Amorilaisten maalla, joka on Gileadissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Ja Ammonin lapset matkustivat Jordanin ylitse ja sotivat Juudaa, BenJaminia ja Ephraimin huonetta vastaan, ja Israel suuresti ahdistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Niin huusivat Israelin lapset Herran tykö, sanoen: me olemme syntiä tehneet sinua vastaan; sillä me olemme hyljänneet meidän Jumalamme ja palvelleet Baalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Mutta Herra sanoi Israelin lapsille: Eikö Egyptiläiset, Amorilaiset, Ammonilaiset, Philistealaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Ja Zidonilaiset, Amalekilaiset ja Maonilaiset ole teitä vaivanneet? ja minä autin teitä heidän käsistänsä, kuin te minun tyköni huusitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Niin te hylkäsitte minun, ja olette palvelleet muita jumalia: sentähden en minä teitä tahdo auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Menkäät ja rukoilkaat niitä jumalia, jotka te valinneet olette, antakaat niiden auttaa teitänne ahdistuksenne aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Mutta Israelin lapset vastasivat Herralle: me olemme syntiä tehneet, tee meidän kanssamme niinkuin sinulle otollinen on, kuitenkin auta meitä tällä ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Ja he panivat tyköänsä vieraat jumalat pois, ja palvelivat Herraa; ja hänen sielunsa suuresti armahti Israelin vaivaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Ja Ammonin lapset kokoontuivat ja sioittivat itsensä Gileadiin; mutta Israelin lapset kokoontuivat ja sioittivat itsensä Mitspaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Ja kansa ja ylimmäiset Gileadista sanoivat toinen toisellensa: kuka rupee ensisti sotimaan Ammonin lapsia vastaan, hänen pitää oleman kaikkein Gileadin asuvaisten pääruhtinaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Ja Jephta Gileadista oli väkevä sotamies, vaan hän oli äpärä; ja Gilead oli siittänyt Jephtan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Mutta kuin Gileadin emäntä synnytti hänelle lapsia, ja vaimon lapset tulivat isoiksi, ajoivat he Jephtan ulos, ja sanoivat hänelle: ei sinun pidä perimän meidän isämme huoneessa, sillä sinä olet vieraan vaimon poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Niin pakeni Jephta veljeinsä edestä ja asui Tobin maalla; ja Jephtan tykö kokoontuivat joutilaat miehet ja menivät hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Ja kappaleen ajan perästä sotivat Ammonin lapset Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Kuin Ammonin lapset sotivat Israelia vastaan, menivät Gileadin vanhimmat tuomaan Jephtaa Tobin maalta jällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Ja sanoivat hänelle: tule ja ole meidän päämiehemme, sotimaan Ammonin lapsia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Vaan Jephta sanoi Gileadin vanhimmille: ettekö te minua vihanneet ja ajaneet minua isäni huoneesta ulos? ja nyt te tulette minun tyköni, kuin teillä tuska on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Gileadin vanhimmat sanoivat Jephtalle: sentähden me nyt tulemme jälleen sinun tykös, ettäs kävisit meidän kanssamme, ja sotisit Ammonin lapsia vastaan, ja olisit meidän päämiehemme ja kaikkein jotka Gileadissa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jephta sanoi Gileadin vanhimmille: jos te viette minun sotimaan Ammonin lapsia vastaan, ja Herra antaa heidät minun eteeni, pitääkö minun oleman teidän päämiehenne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Gileadin vanhimmat sanoivat Jephtalle: Herra olkoon kuulia meidän välillämme, jos emme sitä tee, mitä sinä sanonut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Ja Jephta meni Gileadin vanhimpain kanssa, ja kansa asetti hänen itsellensä päämieheksi ja johdattajaksi. Ja Jephta puhui Herran edessä kaikki sanansa Mitspassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Silloin lähetti Jephta sanansaattajat Ammonin lasten kuninkaan tykö, sanoen: mitä sinun on minun kanssani, ettäs tulet sotimaan minua ja minun maakuntaani vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Ammonin lasten kuningas vastasi Jephtan sanansaattajia: että Israel otti minun maani, silloin kuin hän läksi Egyptistä, Arnonista Jabbokiin ja Jordaniin asti, anna siis ne jällensä hyvällä sovinnolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jephta lähetti taas sanansaattajat Ammonin lasten kuninkaan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Jotka sanoivat hänelle: näin sanoo Jephta: ei Israel ottanut maakuntaa Moabilaisilta eikä Ammonin lapsilta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Sillä kuin he läksivät Egyptistä, matkusti Israel korven lävitse Punaiseen mereen asti, ja tuli Kadekseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Ja Israel lähetti sanansaattajat Edomilaisten kuninkaan tykö, sanoen: anna minun käydä sinun maas lävitse. Mutta Edomilaisten kuningas ei kuullut heitä. Ja hän lähetti myös Moabilaisten kuninkaan tykö, joka ei myöskään tahtonut. Niin oli Israel Kadeksessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Ja vaelsi korvessa, ja kävi Edomilaisten ja Moabilaisten maita ympäri, ja tuli auringon nousemisen puolelta Moabilaisten maahan, ja sioitti itsensä tuolla puolella Arnonia; ja ei tulleet Moabilaisten rajan sisälle, sillä Arnon on Moabilaisten raja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Ja Israel lähetti sanansaattajat Sihonin Amorilaisten kuninkaan, Hesbonin kuninkaan tykö, ja sanoi hänelle: salli meidän käydä sinun maas lävitse omaan paikkaani asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mutta ei Sihon uskonut Israelia käymään rajansa ohitse, vaan kokosi kaiken väkensä, ja sioittivat itsensä Jaksassa, ja soti Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Mutta Herra Israelin Jumala antoi Sihonin kaiken väkensä kanssa Israelin käsiin, että he löivät heidät: ja niin omisti Israel kaiken maan Amorilaisilta, jotka siinä maassa asuivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Ja omistivat myös kaikki Amorilaisten rajat, ruveten Arnonista Jabbokiin asti ja korvesta Jordaniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Näin on Herra Israelin Jumala ajanut Amorilaiset kansansa Israelin edestä pois: ja sinä nyt sen omistaisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Jos sinun jumalas Kamos on jonkun ajanut pois, omista se, ja anna meidän omistaa kaikki ne, jotka Herra meidän Jumalamme meidän edestämme on ajanut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Vai luuletkos sinun paljoa paremmaksi kuin Balak Zipporin poika Moabilaisten kuningas oli? eikö hän riidellyt ja sotinut kappaletta aikaa Israelia vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Kuin Israel asui Hesbonissa ja hänen tyttärissänsä, Aroerissa ja hänen tyttärissänsä, ja kaikissa kaupungeissa, jotka ovat läsnä Arnonia, kolmesataa ajastaikaa; miksi ette ottaneet sitä silloin pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Ja en minä mitään rikkonut sinua vastaan, ja sinä teet niin pahoin minun kanssani, ettäs sodit minua vastaan: Herra joka on tuomari, tuomitkoon tänäpänä Israelin lasten ja Ammonin lasten välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Mutta Ammonin lasten kuningas ei pitänyt lukua Jephtan sanoista, jotka hän oli hänen tykönsä lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Silloin tuli Herran henki Jephtan päälle, ja hän kävi Gileadin ja Manassen lävitse, ja Mitspan lävitse, joka on Gileadissa, ja Mitspasta Gileadissa kävi hän Ammonin lasten ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Ja Jephta lupasi Herralle lupauksen ja sanoi: jos sinä kokonansa annat Ammonin lapset minun käsiini:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Mitä ikänä minun huoneeni ovesta kohtaa minua, kuin minä rauhassa palajan Ammonin lapsilta, se pitää oleman Herran, ja minä uhraan sen polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Niin Jephta meni sotimaan Ammonin lapsia vastaan, ja Herra antoi heidät hänen käsiinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Ja hän löi heidät, Aroerista Minnitiin asti, kaksikymmenestä kaupunkia, ja Abelin viinamäkeen asti sangen suurella tapolla. Ja niin Ammonin lapset alennettiin Israelin lasten edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Kuin Jephta tuli huoneesensa Mitspaan, katso, niin hänen tyttärensä kävi häntä vastaan kanteleilla ja hypyillä; ja se oli ainoa lapsi, eikä hänellä ollut yhtäkään muuta poikaa eli tytärtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Ja kuin hän näki hänen, repäisi hän vaatteensa ja sanoi: ah, minun tyttäreni, sinä painat alas ja sangen surulliseksi saatat minun; sillä minä avasin suuni Herralle, ja en saa sitä ottaa takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Mutta hän vastasi: isäni, jos avasit suus Herralle, niin tee minun kanssani niinkuin sinun suustas on lähtenyt, että Herra on kostanut sinun vihollisilles, Ammonin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Ja sanoi isällensä: tee se ainoastansa minulle, ettäs soisit minun kaksi kuukautta mennä vuorelle ja itkeä minun neitsyyttäni tuttavain piikain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Hän sanoi: mene, ja laski hänen menemään kahdeksi kuukaudeksi; niin meni hän tuttavain piikain kanssa, ja itki neitsyyttänsä vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Ja kahden kuukauden perästä tuli hän isänsä tykö, ja hän täytti lupauksensa hänestä niin kuin hän luvannut oli; ja ei hän tuntenut miestä: ja se oli tapa Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Ja Israelin tyttäret menivät itkemään joka vuosi Jephtan Gileadilaisen tytärtä neljä päivää ajastajassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Ja Ephraimin miehet tulivat kokoon ja menivät pohjoiseen päin ja sanoivat Jephtalle: miksis menit sotaan Ammonin lapsia vastaan, ja et meitä kutsunut menemään kanssas? Me poltamme sinun ja sinun huonees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jephta sanoi heille: minulla ja minun kansallani oli suuri riita Ammonin lasten kanssa, ja minä kutsuin teitä, ja ette auttaneet minua heidän käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Koska minä näin, ettette tahtoneet vapahtaa minua, panin minä sieluni minun käteeni ja menin Ammonin lapsia vastaan, ja Herra antoi heidän minun käteeni: miksi te tulitte minun tyköni tänäpänä sotimaan minua vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Ja Jephta kokosi kaikki Gileadin miehet ja soti Ephraimia vastaan, ja Gileadin miehet löivät Ephraimin, että he sanoivat: oletteko te Gileadilaiset Ephraimin ja Manassen seassa, te Ephraimin karkurit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Ja Gileadilaiset ennättivät Jordanin luotuspaikat Ephraimin edestä. Koska ne paenneet Ephraimista sanoivat: anna minun käydä ylitse, niin sanoivat Gileadin miehet hänelle: oletkos Ephraimilainen? Ja hän vastasi: en.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Niin he käskivät hänen sanoa: Sjibbolet, niin hän sanoi Sibbolet, ja ei taitanut sitä niin sanoa; niin ottivat he hänen kiinni ja tappoivat hänen Jordanin luotuspaikalla, niin että silloin lankesi Ephraimista kaksiviidettäkymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Ja Jephta tuomitsi Israelia kuusi ajastaikaa; ja Jephta Gileadilainen kuoli ja haudattiin Gileadin kaupunkeihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Tämän jälkeen tuomitsi Ibtsan Betlehemistä Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Hänellä oli kolmekymmentä poikaa, ja kolmekymmentä tytärtä hän naitti ulos, ja kolmekymmentä tytärtä otti hän muukalaisista pojillensa; ja tuomitsi Israelia seitsemän ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Ja Ibtsan kuoli ja haudattiin Betlehemissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Tämän jälkeen tuomitsi Israelia Elon Sebulonilainen, ja hän tuomitsi Israelia kymmenen ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Ja Elon Sebulonilainen kuoli ja haudattiin Ajalonissa, Sebulonin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Tämän jälkeen tuomitsi Israelia Abdon Hillelin poika, Pirtagonilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Hänellä oli neljäkymmentä poikaa ja kolmekymmentä pojanpoikaa, jotka ajoivat seitsemälläkymmenellä aasin varsalla; hän tuomitsi Israelia kahdeksan ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Ja Abdon Hillelin poika, Pirtagonilainen, kuoli ja haudattiin Pirtagoniin Ephraimin maalla, Amalekilaisten vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Ja Israelin lapset tekivät vielä pahaa Herran edessä, ja Herra antoi heidät Philistealaisten käsiin neljäksikymmeneksi ajastajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Mutta yksi mies oli Zorasta Danin sukukunnasta, Manoak nimeltä, ja hänen emäntänsä oli hedelmätöin ja ei synnyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Ja Herran enkeli ilmestyi vaimolle ja sanoi hänelle: katso, sinä olet nyt hedelmätöin ja et synnyttänyt; mutta sinun pitää siittämän ja synnyttämän pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Niin karta nyt, ettes juo viinaa eli väkevää juomaa ja ettes mitään saastaista syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Sillä katso, sinä tulet raskaaksi ja synnytät pojan, jonka pään päälle ei pidä yksikään partaveitsi tuleman; sillä se lapsi pitää oleman Jumalan natsir äitinsä kohdusta, ja hän rupee vapahtamaan Israelia Philistealaisten kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Niin tuli vaimo ja ilmoitti sen miehellensä ja sanoi: Jumalan mies tuli minun tyköni, ja hän oli näkyänsä niinkuin Jumalan enkeli sangen peljättävä, ja en minä häntä kysynyt, kusta hän oli, eikä hänkään nimeänsä ilmoittanut minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Mutta hän sanoi minulle: katso, sinä tulet hedelmälliseksi ja synnytät pojan: älä siis nyt juo viinaa taikka väkevää juomaa, älä myös syö mitään saastaista; sillä se lapsi pitää oleman Jumalan natsir äitinsä kohdusta niin kuolemaansa asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Ja Manoak rukoili Herraa ja sanoi: ah minun Herrani! anna sen Jumalan miehen, jonkas lähetit, tulla meidän tykömme jälleen, että hän meitä opettais, mitä meidän tekemän pitää lapselle, joka syntyvä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Ja Jumala kuuli Manoakin äänen: ja Jumalan enkeli tuli jälleen vaimon tykö, ja hän istui kedolla ja hänen miehensä Manoak ei ollut hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Niin hän kiiruusti juoksi ja tiettäväksi teki sen miehellensä, ja sanoi hänelle: katso, se mies, joka ennen tuli minun tyköni, on minulle ilmestynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Manoak nousi ja seurasi emäntäänsä ja tuli miehen tykö ja sanoi hänelle: oletkos se mies, joka puhuttelit vaimoa? Hän sanoi: olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Ja Manoak sanoi: kuin nyt tapahtuu, mitä sanonut olet: minkäkaltaiset pitää lapsen tavat ja hänen työnsä oleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Herran enkeli sanoi Manoakille: vaimon pitää karttaman kaikkia niitä, mitä hänelle sanonut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Ei hänen pidä syömän siitä, mikä viinapuusta tullut on, ja ei hänen pidä viinaa taikka väkevää juomaa juoman eikä mitään saastaista syömän: kaikki kuin minä hänelle käskin, pitää hänen pitämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Manoak sanoi Herran enkelille: Jospa tahtoisit viipyä, me valmistamme sinulle vohlan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Mutta Herran enkeli vastasi Manoakille: Vaikkas saisitkin minun viipymään, en minä kuitenkaan söisi sinun leipääs, mutta jos tahdot uhrata polttouhria, niin uhraa se Herralle; sillä ei Manoak tietänyt sitä Herran enkeliksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Ja Manoak sanoi Herran enkelille: mikä sinun nimes on, että me sinua ylistäisimme, kuin se tapahtuu, minkä sanonut olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Herran enkeli sanoi hänelle: miksis kysyt minun nimeäni, joka ihmeellinen on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Niin otti Manoak vohlan ja ruokauhrin ja uhrasi sen kallion päällä Herralle, ja hän teki ihmeen; mutta Manoak emäntinensä näki sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Ja tapahtui, kuin liekki nousi alttarilta taivaaseen päin, meni Herran enkeli myös ylös alttarin liekissä. Ja Manoak emäntinensä näki sen, ja lankesivat kasvoillensa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Ja ei Herran enkeli enää näkynyt Manoakille ja hänen emännällensä. Niin ymmärsi Manoak sen Herran enkeliksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Ja Manoak sanoi emännällensä: totisesti me kuolemme, että näimme Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Mutta hänen emäntänsä vastasi häntä: jos Herra olis tahtonut meidät tappaa, niin ei hän olisi ottanut polttouhria ja ruokauhria vastaan meidän kädestämme, eikä olisi osoittanut meille kaikkia näitä, eikä myös antanut meidän näitä kuulla, niinkuin tapahtunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Ja vaimo synnytti pojan ja kutsui hänen Simson; ja lapsi kasvoi, ja Herra siunasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Ja Herran henki rupesi vaikuttamaan hänessä Danin leirissä, Zoran ja Estaolin välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Ja Simson meni alas Timnatiin, ja hän näki vaimon Timnatissa Philistealaisten tytärten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Ja kuin hän tuli sieltä, sanoi hän isällensä ja äidillensä: minä näin vaimon Timnatissa Philistealaisten tyttäristä: ottakaat se minulle emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Ja hänen isänsä ja äitinsä sanoivat hänelle: eikö yhtään vaimoa ole veljeis tytärten seassa ja kaikessa minun kansassani, ettäs menet ottamaan emäntää Philistealaisista, jotka ovat ympärileikkaamattomat? Ja Simson sanoi isällensä: salli minulle tämä, sillä hän kelpaa minun silmilleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Mutta hänen isänsä ja äitinsä ei tietäneet sen olevan Herralta; sillä hän etsi tilaa Philistealaisia vastaan, ja Philistealaiset hallitsivat silloin Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Niin Simson meni isänsä ja äitinsä kanssa alas Timnatiin, ja he tulivat Timnatin viinamäkein tykö, ja katso, nuori jalopeura tuli kiljuin häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Ja Herran henki tuli voimalliseksi hänessä, ja hän repäisi sen kappaleiksi, niinkuin hän olis vohlan reväissyt, ja ei ollut mitään hänen kädessänsä; ja ei hän sanonut mitään isällensä eikä äidillensä, mitä hän tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Kuin hän sinne alas tuli, puhutteli hän vaimoa, ja hän kelpasi Simsonille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Ja muutamain päiväin perästä tuli hän jälleen ottamaan häntä, ja poikkesi tieltä katsomaan jalopeuran raatoa, ja katso, kimalaispesä oli jalopeuran raadossa ja hunajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Ja hän otti sen käteensä tiellä käydessänsä syödäksensä, meni isänsä ja äitinsä tykö ja antoi heidän myös sitä syödä; mutta ei hän ilmoittanut hunajaa ottaneensa jalopeuran raadosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Ja kuin hänen isänsä tuli alas vaimon tykö, valmisti Simson siellä häät, niinkuin nuoren väen tapa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Ja kuin he näkivät hänen, antoivat he hänelle kolmekymmentä kansalaista, hänen tykönänsä olemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Mutta Simson sanoi heille: minä panen teidän eteenne arvoituksen, jos sen minulle seitsemänä hääpäivänä oikein selitätte ja arvaatte, niin minä annan teille kolmekymmentä paitaa ja kolmekymmentä vaatekertaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mutta jollette taida sitä selittää minulle, niin teidän pitää antaman minulle kolmekymmentä paitaa ja kolmekymmentä vaatekertaa. Ja he sanoivat hänelle: annas meidän kuulla arvoitukses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Ja hän sanoi heille: ruoka läksi syömäristä ja makeus väkevästä. Ja ei he taitaneet kolmena päivänä arvoitusta selittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Ja seitsemäntenä päivänä puhuivat he Simsonin emännälle: houkuttele miestäs ilmoittamaan meille arvoitusta, taikka me poltamme sinun ja sinun isäs huoneen tulella. Sentähdenkö me olemme tänne kutsutut, että hän meidän hyvyytemme omistais, elikkä ei?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Niin Simsonin emäntä itki hänen edessänsä ja sanoi: sinä olet minulle vihainen ja et minua rakasta: sinä panit minun kansani lapsille arvoituksen, ja et minulle sitä sanonut. Hän sanoi hänelle: katso, isälleni ja äidilleni en minä sitä ilmoittanut, pitäiskö minun sen sinulle sanoman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Ja hän itki hänen edessänsä kaikki ne seitsemän hääpäivää, ja seitsemäntenä päivänä ilmoitti hän sen hänelle; sillä hän suuresti vaati häntä. Ja hän sanoi kansansa lapsille arvoituksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Mutta seitsemäntenä päivänä ennen kuin aurinko laski, sanoivat kaupungin miehet hänelle: mikä on hunajaa makiampi, ja mikä jalopeuraa väkevämpi? Hän sanoi heille: jollette olisi kyntäneet minun vasikallani, ette olisi saaneet tietää arvoitustani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Ja Herran henki tuli voimalliseksi hänessä ja hän meni Askaloniin ja löi siellä kolmekymmentä miestä, joiden vaatteet hän otti, ja antoi vaatekerrat niille, jotka arvoituksen selittäneet olivat. Ja hän kovin julmistui vihassansa ja meni ylös isänsä huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Mutta Simsonin emäntä huoli yhdelle kansalaisistansa, joka oli Simsonin kumppani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Ja tapahtui muutamain päiväin perästä, kuin nisun elonaika lähestyi, tuli Simson oppimaan emäntäänsä ja toi hänelle vohlan, ja hän sanoi: minä menen emäntäni tykö makaushuoneesen; ja hänen emäntänsä isä ei sallinut hänen sinne mennä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Mutta sanoi: minä luulin todella, sinun kokonansa vihastuneen hänen päällensä, ja annoin hänen sinun ystävälles. Mutta hänellä on toinen nuorempi sisar, kauniimpi muotoansa kuin hän, olkoon se nyt sinulla tämän edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Ja Simson sanoi heille: nyt on minulla oikia syy Philistealaisia vastaan: minä teen heille vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Ja Simson meni ja otti kolmesataa kettua kiinni, ja otti kekäleet, ja käänsi hännät yhteen, ja sitoi aina yhden kekäleen keskelle kahden hännän välille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Ja sytytti tulen kekäleihin, ja päästi ne Philistealaisten eloon; ja ne polttivat heidän kykäänsä ja kuhilaansa, niin myös viinapuut ja öljypuut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Niin sanoivat Philistealaiset: kuka on tämän tehnyt? Niin sanottiin: Simson, Timnalaisen vävy, että hän otti häneltä emännän pois ja antoi sen hänen ystävällensä. Niin Philistealaiset menivät ylös ja polttivat sekä vaimon että hänen isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Mutta Simson sanoi heille: ja vaikka te tämän teitte, kuitenkin minä teille kostan ja sitte lakkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Ja hän löi heitä sangen kovasti sekä hartioihin että kupeisiin, ja meni sieltä alas asumaan Etamin mäen rotkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Niin Philistealaiset menivät ylös ja sioittivat itsensä Juudan maalle ja levittivät heitänsä Lehiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Ja Juudan miehet sanoivat: miksi olette tänne tulleet meitä vastaan? He vastasivat: me olemme tänne tulleet sitomaan Simsonia ja tekemään hänelle, niinkuin hän meille teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Niin meni kolmetuhatta miestä Juudasta Etamin mäen rotkoon, ja sanoivat Simsonille: etkös tiedä Philistealaisten hallitsevan meitä? kuinka sinä olet tämän tehnyt meitä vastaan? Ja hän sanoi heille: niinkuin he tekivät minulle, niin minä tein heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Ja he sanoivat hänelle: me olemme tulleet sinua sitomaan ja antamaan Philistealaisten käsiin. Simson sanoi heille: vannokaat siis minulle, ettette karkaa minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Ja he sanoivat hänelle: emme karkaa sinun päälles, mutta ainoasti sidomme sinun tukevasti ja annamme sinun heidän käsiinsä, ja emme sinua kuoliaaksi lyö. Ja he sitoivat hänen kahdella uudella nuoralla ja veivät hänen kukkulalta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Ja kuin hän tuli Lehiin, ilakoitsivat Philistealaiset häntä vastaan; mutta Herran henki tuli voimalliseksi hänessä, ja nuorat hänen käsivarsissansa tulivat niinkuin poltettu lanka, ja niin raukesivat siteet hänen käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Ja hän löysi tuoreen aasin leukaluun, ja hän ojensi kätensä, otti sen ja löi sillä tuhannen miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Ja Simson sanoi: katso, siinä he koossa makaavat, yhdellä leukaluulla löin minä tuhannen miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Ja kuin hän sen sanonut oli, heitti hän leukaluun kädestänsä pois, ja kutsui sen paikan RamatLehi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Ja kuin hän kovin janosi, huusi hän Herran tykö ja sanoi: sinä annoit tämän suuren pelastuksen palvelias käden kautta, ja nyt minä janoon kuolen ja lankeen ympärileikkaamattomain käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Niin Jumala avasi syömähampaan leukaluussa, ja siitä vuosi vesi, ja kuin hän oli juonut, sai hän henkensä takaisin ja virkosi; sentähden kutsutaan myös se paikka vielä tähän päivään asti Huutajan lähteeksi, joka oli leukaluussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Ja hän tuomitsi Israelia Philistealaisten aikana kaksikymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Ja Simson meni Gasaan, ja hän näki siellä porton, ja meni hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Ja sanottiin Gasalaisille, että Simson oli sinne tullut; niin he kohta piirittivät hänen ja väijyivät häntä koko yön kaupungin portissa, ja olivat hiljaksensa kaiken yötä, ja sanoivat: aamulla päivän tullessa me tapamme hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Vaan Simson makasi puoliyöhön asti, ja nousi puoliyöstä, ja tarttui kaupungin portin oviin ja molempiin pihtipieliin, ja nosti ne telkein kanssa, pani olallensa ja kantoi mäen kukkulalle, joka on Hebronin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Sitte rupesi hän jälleen rakastamaan yhtä vaimoa Sorekin ojan tykönä, jonka nimi oli Delila.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Ja hänen tykönsä tulivat Philistealaisten päämiehet, jotka sanoivat hänelle: viettele häntä sanoilla, että saisit tietää, missä hänen suuri väkevyytensä on, ja kuinka me hänen voittaisimme, että me saisimme hänen sitoa ja vaivata: ja me jokainen annamme sinulle tuhannen ja sata hopiapenninkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Delila sanoi Simsonille: sanos minulle, missä sinun suuri väkevyytes on, ja millä sinä sidottaisiin ja vaivattaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson sanoi hänelle: jos joku sitoo minun seitsemällä viheriäisellä köydellä, jotka ei vielä ole kuivuneet, niin minä tulen heikoksi ja olen niinkuin muutkin ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Silloin veivät Philistealaisten päämiehet hänelle seitsemän viheriäistä köyttä, jotka ei vielä olleet kuivuneet; ja hän sitoi hänen niillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Ja he vartioitsivat häntä salaisesti kammiossa, ja hän sanoi hänelle: Philistealaiset sinun päälles, Simson! niin hän katkaisi köydet, niinkuin rohtiminen lanka katkaistaan, joka liekissä poltettu on. Ja ei saatu tietää, missä hänen väkevyytensä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Taas sanoi Delila Simsonille: katso, sinä viettelit minua ja väärin puhuit minun edessäni: sano siis nyt minulle, millä sinä sidottaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Ja hän sanoi hänelle: jos minä sidottaisiin uusilla nuorilla, joilla ei vielä ole mitään tehty, niin minä tulisin heikoksi niinkuin muutkin ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Niin Delila otti uudet nuorat ja sitoi hänen niillä, sanoen hänelle: Philistealaiset sinun päälles, Simson! Ja he vartioitsivat häntä salaisesti kammiossa; ja hän katkaisi ne käsivarsistansa niinkuin langan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Taas Delila sanoi Simsonille: sinä viettelit vielä nyt minua ja väärin puhuit minun edessäni: ilmoita minulle, millä sinä sidottaisiin. Hän vastasi häntä: jos sinä palmikoitset seitsemän suortua hiuksia minun päästäni yhteen päärihmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Ja kuin hän oli kiinnittänyt ne naulaan, sanoi hän hänelle: Philistealaiset sinun päälles, Simson! Niin hän heräsi unestansa ja veti ulos palmikkonauhan ja päärihman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Hän sanoi hänelle jällensä: kuinka sinä sanot rakastavas minua, koska sinun sydämes ei ole minun kanssani? Kolmasti sinä jo vääristelit minun edessäni ja et ilmoittanut minulle, missä sinun suuri väkevyytes on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Kuin hän päivä päivältä vaati häntä sanoillansa ja vaivasi häntä, että hänen sielunsa väsyi kuolemaan asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Ilmoitti hän hänelle kaiken sydämensä, sanoen hänelle: minun päähäni ei ole ikänä partaveitsi tullut, sillä minä olen Jumalan natsir hamasta äitini kohdusta. Jos hiukset ajellaan minun päästäni, niin minun väkevyyteni menee minusta pois, ja tulen heikoksi niinkuin kaikki muutkin ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Ja Delila näki, että hän ilmoitti hänelle kaiken sydämensä, lähetti ja kutsui Philistealaisten päämiehet, sanoen: tulkaat vielä erä, sillä hän ilmoitti minulle kaiken sydämensä. Ja Philistealaisten päämiehet tulivat hänen tykönsä ja toivat rahan käsissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Niin hän antoi hänen maata polveinsa päällä, kutsui yhden, joka ajeli seitsemän hiussuortua hänen päästänsä, ja rupesi häntä vaatimaan, ja hänen väkensä meni hänestä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Ja hän sanoi: Philistealaiset sinun päälles, Simson! Kuin hän unestansa heräsi, ajatteli hän itseksensä: minä menen ulos niinkuin usein ennenkin ja kirvotan itseni; ja ei hän tietänyt Herran menneen hänen tyköänsä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Vaan Philistealaiset ottivat hänen kiinni, ja puhkasivat hänen silmänsä, ja veivät hänen alas Gasaan, ja sitoivat hänen kaksilla vaskikahleilla, jauhamaan vankihuoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Ja hänen hiuksensa rupesivat taas kasvamaan, sittekuin hän paljaaksi ajettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Ja Philistealaisten päämiehet kokoontuivat suurta uhria tekemään jumalallensa Dagonille ja iloitsemaan, ja sanoivat: meidän jumalamme on antanut meille vihollisemme Simsonin käsiimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Ja kuin kansa näki hänen, kiittivät he jumalaansa, sanoen: meidän jumalamme on antanut meille vihollisemme käsiimme, joka meidän maakuntamme hävitti ja sangen monta meistä tappoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Kuin he juuri sydämestänsä iloitsivat, sanoivat he: kutsukaat Simson soittamaan meidän eteemme. Ja he kutsuivat Simsonin vankihuoneesta, ja hän soitti heidän edessänsä, ja he asettivat hänen pilarien välille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Mutta Simson puhui palveliallensa, joka häntä kädestä talutti: anna minun tarttua pilareihin, joiden päälle huone on vahvistettu, nojatakseni niihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Ja huone oli täynnä miehiä ja vaimoja, ja Philistealaisten päämiehet olivat kaikki siinä; ja oli myös katon päällä liki kolmetuhatta miestä ja vaimoa, jotka katselivat Simsonin soittamista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Mutta Simson huusi Herran tykö, sanoen: Herra, Herra, muista minua, ja vahvista minua Jumala ainoasti tällä haavalla, että minä kahden minun silmäni tähden kostaisin yhden kerran Philistealaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Ja Simson tarttui kahteen keskimäiseen pilariin, joiden päälle huone oli vahvistettu, ja nojasi niiden päälle, otti yhden oikiaan ja toisen vasempaan käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Ja Simson sanoi: minun sieluni kuolkoon Philistealaisten kanssa. Ja hän nojasi vahvasti niiden päälle; ja huone kaatui päämiesten ja kaiken kansan päälle joka siinä oli, että ne, jotka hän tappoi kuollessansa, olivat usiammat kuin ne, jotka hän eläissänsä tappoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Niin tulivat hänen veljensä alas ja kaikki hänen isänsä huone, ottivat hänen ja menivät ylös, ja hautasivat hänen Zoran ja Estaolin välille isänsä Manoakin hautaan. Ja hän tuomitsi Israelia kaksikymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Ja yksi mies oli Ephraimin vuorelta, nimeltä Miika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Hän sanoi äidillensä: ne tuhannen ja sata hopiapenninkiä, jotka sinulta otettiin, joiden tähden sinä kirosit ja puhuit minun korvaini kuullen: katso, ne ovat minun tykönäni, minä ne otin. Silloin sanoi hänen äitinsä: siunattu olet sinä, minun poikani, Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Niin antoi hän äidillensä ne tuhannen ja sata hopiapenninkiä jälleen. Ja hänen äitinsä sanoi: minä pyhitin kokonansa sen rahan Herralle minun kädestäni poikani edestä, tehdä kaivettua ja valettua kuvaa; ja nyt annan minä sinulle sen jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Mutta hän antoi sen rahan äidillensä jälleen. Ja hänen äitinsä otti kaksisataa hopiapenninkiä ja antoi ne hopiasepälle; hän teki kaivetun ja valetun kuvan, joka sitte oli Miikan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Ja Miikalla oli Jumalan huone, ja hän teki päällisvaatteen ja epäjumalan kuvat, ja täytti yhden poikansa kädet, ja hän oli hänen pappinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Silloin ei ollut kuningasta Israelissa, ja itsekukin teki niinkuin heille näkyi hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Mutta nuorukainen oli Juudan Betlehemistä, Juudan sukukunnasta, ja se oli Leviläinen, joka oli siellä muukalaisena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Hän meni Betlehemistä Juudan kaupungista vaeltamaan, kuhunka hän joutuis. Ja kuin hän tuli Ephraimin vuorelle Miikan huoneesen, vaeltaen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Kysyi Miika häneltä: kustas tulet? Leviläinen vastasi: minä olen Leviläinen Betlehemistä Juudan maalta, ja vaellan, kuhunka minä parhain taidan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Miika sanoi hänelle: olen minun tykönäni. Sinun pitää oleman minun isäni ja pappini, ja minä annan sinulle vuosi vuodelta kymmenen hopiapenninkiä ja määrätyt vaatteet ja elatukses; ja Leviläinen meni hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Ja Leviläinen rupesi olemaan sen miehen tykönä, ja hän piti sen nuorukaisen niinkuin yhden pojistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Ja Miika täytti Leviläisen käden, että hän oli hänen pappinsa, ja hän asui Miikan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Ja Miika sanoi: nyt minä tiedän Herran minulle hyvää tekevän, että minulla on Leviläinen pappina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Siihen aikaan ei ollut kuningasta Israelissa, ja silloin Danin sukukunta etsi itsellensä perintöä asuaksensa; sillä siihen päivään asti ei ollut yhtään perintöarpaa hänelle langennut Israelin sukukuntain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Ja Danin lapset lähettivät sukukunnastansa ja ääristänsä viisi urhoollista sotamiestä Zorasta ja Estaolista, vakoomaan maata ja tutkistelemaan sitä, ja sanoivat heille: menkäät ja vaotkaat maata. Ja he tulivat Ephraimin vuorelle Miikan huoneesen ja yötyivät sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Ja kuin he olivat Miikan perheen tykönä, tunsivat he sen nuoren miehen Leviläisen äänen; ja he menivät hänen tykönsä ja sanoivat hänelle: kuka sinun on tänne tuonut? mitäs täällä teet? ja mitä sinun on täällä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Hän vastasi heitä: niin ja niin on Miika minulle tehnyt, ja hän on palkannut minun papiksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'He sanoivat hänelle: kysy Jumalalta, että me saisimme tietää, onko tiemme, jota me vaellamme, meille onnellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Pappi vastasi heitä: menkäät rauhassa: Herran edessä on teidän tienne, jota te vaellatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Niin menivät ne viisi miestä matkaansa ja tulivat Laikseen, ja näkivät kansan, joka siellä oli, asuvan surutoinna Zidonilaisten tavan jälkeen, levollisesti ja surutoinna: ja ei yksikään ollut, joka heitä vaivasi sillä maalla, eikä myös heillä ollut yhtäkään isäntää; ja olivat kaukana Zidonilaisista, ja ei heillä ollut mitäkään yhdenkään ihmisen kanssa tekemistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Ja he tulivat veljeinsä tykö Zoraan ja Estaoliin. Ja heidän veljensä sanoivat heille: kuinka teidän asianne on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'He sanoivat: nouskaat, käykäämme ylös heidän tykönsä; sillä me olemme katselleet maan, ja katso, se on sangen hyvä: sentähden rientäkäät, älkäät olko hitaat menemään ja omistamaan maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Kuin te tulette, niin te löydätte suruttoman kansan, ja maa on itsestänsä lavia: sillä Jumala on antanut sen teidän käsiinne, sen paikan, jossa ei mitään puutu, mitä maan päällä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Niin meni Danin sukukunnasta, Zorasta ja Estaolista, kuusisataa miestä hyvin varustettuina sota-aseilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Ja menivät sinne ylös, ja sioittivat itsensä Juudan KirjatJearimiin: siitä kutsutaan se paikka Danin leiriksi tähän päivään asti; katso, se on KirjatJearimin takana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Ja sieltä menivät he Ephraimin vuorelle ja tulivat Miikan huoneen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Niin puhuivat ne viisi miestä, jotka läksivät Laikseen maata vakoomaan, ja sanoivat veljillensä: ettekö te tiedä, että näissä huoneissa on päällisvaate, pyhyys, kuvat ja epäjumalat? Nyt ajatelkaat, mitä te teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Ja he poikkesivat sinne ja tulivat nuoren miehen Leviläisen huoneesen, joka oli Miikan huoneessa, ja tervehtivät häntä ystävällisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Mutta ne kuusisataa sota-aseilla varustettua miestä, jotka olivat Danin lapsista, seisoivat portilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Ja ne viisi miestä, jotka olivat menneet vakoomaan maata, menivät ylös ja tulivat sinne sisälle, ja ottivat kuvan, päällisvaatteen, pyhyyden ja epäjumalan. Ja pappi seisoi portilla kuudensadan sota-aseilla varustettuin miesten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Kuin ne olivat tulleet Miikan huoneesen ja ottivat kuvan, päällisvaatteen, pyhyyden ja epäjumalat, sanoi pappi heille: mitä te teette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'He vastasivat häntä: ole vaiti ja pidä suus kiinni, ja tule meidän kanssamme, ja ole meidän isämme ja pappimme: onko se parempi, ettäs olet pappi yhden miehen huoneessa, kuin koko sukukunnassa Israelissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Ja papin mieli oli hyvä, ja otti sekä päällisvaatteen, pyhyyden ja kuvan, ja meni kansan keskelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Ja kuin he käänsivät itsensä ja menivät matkaansa, asettivat he pienet lapset ja karjan ja kaikkein kalliimmat tavaransa, menemään edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Kuin he olivat taamma joutuneet Miikan huoneesta, kokoontuivat ne miehet, jotka niissä huoneissa olivat, jotka olivat Miikan huoneen tykönä, ja ajoivat Danin lapsia takaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Ja huusivat Danin lapsille; ja he käänsivät kasvonsa ja sanoivat Miikalle: mikä sinun on, ettäs niin huudat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Hän vastasi: te olette ottaneet minun jumalani, jotka minä tehnyt olen, ja papin, ja menneet matkaanne: ja mitä minulla nyt enää on? Ja te sanotte vielä sitte minulle: mikä sinun on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Mutta Danin lapset sanoivat hänelle: älä anna ääntäs kuulua meidän tykönämme, ettei vihaiset miehet lankeaisi teidän päällenne, ja sinä hukutat sielus ja huonees sielut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Niin Danin lapset menivät matkaansa. Ja kuin Miika näki heidät häntä väkevämmäksi, käänsi hän itsensä ja palasi huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Mutta he ottivat sen mitä Miika tehnyt oli ja papin, joka hänellä oli, ja tulivat Laikseen, levollisen ja suruttoman kansan päälle, ja löivät heitä miekan terällä, ja polttivat kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Ja ei yksikään ollut, joka heitä autti, sillä he olivat kaukana Zidonista, ja ei ollut heillä kenenkään kanssa tekemistä: ja he olivat siinä laaksossa, joka on BetRehobin tykönä; niin rakensivat he kaupungin, ja asuivat siinä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Ja kutsuivat kaupungin nimen Dan, isänsä Danin nimeltä, joka Israelista oli syntynyt, vaikka se kaupunki ennen muinen kutsuttiin Lais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Ja Danin lapset panivat heillensä sen kuvan ylös, ja Jonatan Gersomin poika, Manassen pojan, ja hänen poikansa olivat papit Danilaisten sukukunnassa, siihenasti että he vietiin vankina maalta pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Ja he panivat keskellensä Miikan kuvan, jonka hän tehnyt oli, niinkauvan kuin Jumalan huone oli Silossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Siihen aikaan ei ollut kuningasta Israelissa, ja yksi Leviläinen oli muukalaisena Ephraimin vuoren reunalla, ja otti itsellensä jalkavaimon Juudan Betlehemistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Ja hänen jalkavaimonsa teki huorin hänen tykönänsä, ja juoksi hänen tyköänsä isänsä majaan Juudan Betlehemiin, ja oli siellä neljä kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Ja hänen miehensä matkusti hänen peräänsä, puhuttelemaan häntä ystävällisesti ja palauttamaan tykönsä. Ja hänellä oli palvelia ja kaksi aasia myötänsä. Ja hän vei hänen isänsä huoneesen. Ja kuin vaimon isä näki hänen, tuli hän iloiseksi ja meni häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Ja hänen appensa, vaimon isä, pidätti hänen, että hän viipyi hänen tykönänsä kolme päivää; he söivät ja joivat, ja olivat siinä yötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Neljäntenä päivänä olivat he varhain ylhäällä, ja hän nousi ja tahtoi matkaan lähteä, niin sanoi vaimon isä vävyllensä: vahvista sydämes leivän palalla, ja menkäät sitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Ja he istuivat, söivät ja joivat toinen toisensa kanssa. Niin sanoi vaimon isä hänelle: ole tässä yötä, ja iloita sydämes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Mutta hän nousi vaeltamaan, vaan hänen appensa vaati häntä, että hän oli siinä sen yön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Viidentenä päivänä oli hän aamulla varhain ylhäällä vaeltamaan, ja vaimon isä sanoi: virvoita sydämes, ja hän viivytti hänen siihenasti että päivä kului, ja he söivät toinen toisensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Ja mies nousi lähtemään matkaan jalkavaimonsa ja palveliansa kanssa, mutta hänen appensa, vaimon isä, sanoi hänelle: katsos, päivä on kulunut ja ehtoo on käsissä, olkaat tässä yötä; katso, tässä on sinulla oltava vielä nyt tämä päivä, ole tässä yö, että sydämes tulis iloiseksi. Nouskaat aamulla varhain matkallenne ja matkustakaat majoillenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mutta ei mies ollut yötä, vaan nousi ja meni matkaansa, ja lähestyi Jebusta, se on Jerusalem, ja kaksi hänen aasiansa kannattaen kuormaa, ja hänen jalkavaimonsa hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Kuin he tulivat Jebukseen asti, oli päivä paljo kulunut, ja palvelia sanoi isännällensä: poiketkaamme Jebusilaisten kaupunkiin ja olkaamme yötä siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Mutta hänen isäntänsä sanoi hänelle: en minä mene outoon kaupunkiin, jotka ei ole Israelin lapsia; vaan käykäämme edespäin Gibeaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Ja sanoi palveliallensa: käy vahvasti, että me johonkuhun paikkaan tulisimme yötä pitämään, Gibeaan taikka Ramaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Ja he menivät ja vaelsivat, ja aurinko joutui heiltä kovin alas läsnä Gibeaa, joka on BenJaminissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Ja he menivät Gibeaan olemaan yötä. Kuin hän sinne tuli, istui hän kaupungin kujalle; sillä ei siellä ollut yksikään, joka heidät otti yöksi huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Ja katso, vanha mies tuli pellolta ehtoona töistänsä, joka myös itse oli Ephraimin vuorelta ja oli Gibeassa muukalainen. Mutta sen paikan kansa olivat BenJaminilaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Ja kuin hän nosti silmänsä, näki hän oudon miehen kaupungin kujalla; ja sanoi vanha mies hänelle: kuhunka sinä tahdot? ja kusta sinä tulet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Hän vastasi häntä, sanoen: me olemme tulleet Juudan Betlehemistä ja menemme Ephraimin vuoren reunalle, josta minä olen kotoisin, ja vaelsin Juudan Betlehemiin, vaan nyt minä menen Herran huoneesen: ja ei yksikään minua huoneesen korjaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Meillä on olkia ja heiniä aaseillemme, ja leipää ja viinaa minulle ja piialles, ja palvelialle joka sinun palvelias kanssa on; niin ettei meiltä mitään puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Vanha mies sanoi: rauha olkoon sinulle! kaikkea mitä sinulta puuttuu, on minulla; ainoasti älä ole tässä kujalla yötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Ja hän vei hänen huoneesensa, ja antoi aaseille heiniä; ja he pesivät jalkansa, söivät ja joivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Ja kuin he rupesivat sydämestä iloitsemaan, ja katso, kaupungista tulivat ilkiät miehet, ja piirittivät huoneen, ja löivät oven päälle, ja sanoivat sille vanhalle miehelle perheen isännälle: anna se mies tänne ulos, joka sinun huoneeses on tullut, että me hänen tuntisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Mutta perheen isäntä meni heidän tykönsä ja sanoi heille: ei niin, hyvät veljeni, älkäät tehkö tätä pahaa tekoa, että tämä mies on tullut minun huoneeseni, älkäät tehkö niin suurta tyhmyyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Katso, minulla on tytär, joka vielä neitsy on, ja tällä on yksi jalkavaimo, nämät minä tuon teille, vaivataksenne heitä ja tehdäksenne heille, mitä te tahdotte; mutta tätä miestä vastaan älkäät osoittako niin kauheaa pahaa tekoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mutta miehet ei tahtoneet häntä kuulla; niin otti mies jalkavaimonsa ja talutti hänen ulos heidän tykönsä, jonka he tunsivat, ja käyttivät itsensä häpiällisesti hänen kanssansa kaiken yötä aina huomeneen asti; ja päivän koittaissa päästivät he hänen menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Silloin tuli vaimo vähää ennen auringon nousemaa sen huoneen oven eteen, jossa hänen isäntänsä makasi, lankesi maahan ja makasi siinä valkiaan päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Kuin hänen isäntänsä huomeneltain nousi, avasi hän huoneen oven ja meni ulos lähtien matkallensa; ja katso, hänen jalkavaimonsa oli kaatunut maahan oven eteen, ja hänen kätensä oli kynnyksellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Ja hän sanoi hänelle: nouse ja käykäämme; mutta ei hän mitään vastannut; niin otti hän hänen aasinsa päälle, valmisti itsensä ja matkusti kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Kuin hän kotiansa tuli, otti hän veitsen ja jakoi jalkavaimonsa kahteentoistakymmeneen kappaleeseen kaikki lihoinensa ja luinensa, ja lähetti ne kaikkiin Israelin maan rajoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Ja kaikki jotka sen näkivät, sanoivat: ei ole senkaltaista ikänä ennen tapahtunut eikä nähty, siitä päivästä kuin Israelin lapset tulivat Egyptin maalta niin tähän päivään asti. Ajatelkaat nyt itsellänne tästä asiasta visusti, pitäkäät neuvoa ja puhukaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Ja kaikki Israelin lapset läksivät ulos ja kokosivat heitänsä joukkoon niinkuin yksi mies, Danista BerSebaan asti, ja Gileadin maasta niin Herran tykö Mitspaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Ja kaiken kansan päämiehet, kaikki Israelin sukukunnat seisoivat Jumalan kansan seurakunnassa, neljäsataa tuhatta miekan vetävää jalkamiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Ja BenJaminin lapset saivat kuulla Israelin lapset menneeksi ylös Mitspaan. Ja Israelin lapset sanoivat: sanokaat, kuinka tämä pahateko on tapahtunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Niin vastasi Leviläinen, tapetun vaimon mies, ja sanoi: minä tulin Gibeaan, joka on BenJaminissa, ja minun jalkavaimoni yöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Ja Gibean asuvaiset nousivat minua vastaan ja piirittivät minun yöllä huoneessa, jossa minä olin, ja tahtoivat tappaa minun ja häpäisivät jalkavaimoni, että hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Niin minä otin jalkavaimoni ja jaoin kappaleiksi, ja lähetin ne kaikkiin Israelin maan rajoihin: että he tekivät häpiällisen ja kauhian työn Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Katso, te olette kaikki Israelin lapset tässä, pitäkäät neuvoa ja tehkäät jotain tähän asiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Niin kaikki kansa nousi niinkuin yksi mies ja sanoi: älkään meistä yksikään menkö majaansa eikä kenkään poiketko huoneesensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Mutta sen me nyt teemme Gibeaa vastaan, me heitämme arpaa häntä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Ja otamme kymmenen miestä sadasta ja sata tuhannesta ja tuhannen kymmenestätuhannesta, kaikista Israelin sukukunnista, ottamaan kansalle ravintoa, tulemaan ja tekemään Gibealle, joka BenJaminissa on, kaiken sen hulluuden jälkeen, kuin he ovat tehneet Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Niin kokosivat heitänsä kaikki Israelin miehet kaupunkiin, niinkuin yksi mies, ja tekivät liiton keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Ja Israelin sukukunnat lähettivät miehiä kaikkein BenJaminin sukukuntain tykö, ja käskivät heille sanoa: mikä pahateko tämä on, joka teidän seassanne on tapahtunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Antakaat siis nyt ne ilkiät miehet Gibeasta, meidän tappaaksemme ja ottaaksemme pahuutta Israelista pois. Mutta BenJaminin lapset ei tahtoneet kuulla veljeinsä Israelin lasten ääntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Vaan BenJaminin lapset kokosivat heitänsä kaupungeista Gibeaan, menemään ulos sotaan Israelin lapsia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Ja olivat sinä päivänä luetut BenJaminin lapset kaupungeista kuusikolmattakymmentä tuhatta miestä, jotka miekkaa vetivät ulos, ilman Gibean asuvaisia, joita oli seitsemänsataa valittua miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Ja kaiken sen kansan seassa oli seitsemänsataa valittua miestä, jotka olivat vasenkätiset, ja taisivat kaikki nämät lingolla osata hiuskarvaan, niin ettei he hairahtuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Mutta Israelin miehiä, ilman BenJaminilaisia oli neljäsataa tuhatta, jotka miekkaa vetivät ulos, ja olivat kaikki vahvat sotamiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Ja Israelin lapset nousivat ja menivät Jumalan huoneesen, ja kysyivät Jumalalta, sanoen: kuka menee meidän edellämme alkamaan sotaa BenJaminin lapsia vastaan? Herra sanoi: Juudan pitää alkaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Ja Israelin lapset nousivat aamulla ja sioittivat itsensä Gibean eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Israelin miehet menivät sotaan BenJaminin kanssa, ja Israelin miehet sääsivät sodan heitä vastaan Gibeassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Ja BenJaminin lapset läksivät Gibeasta ja löivät sinä päivänä Israelista kaksikolmattakymmentä tuhatta miestä ketoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Ja Israelin kansan miehet vahvistivat heitänsä ja valmistivat itsensä taas sotimaan siinä paikassa, jossa he olivat ensimmäisenäkin päivänä valmiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Ja Israelin lapset menivät ylös ja itkivät Herran edessä ehtoosen asti, ja kysyivät Herralta, sanoen: pitääkö meidän vielä menemän sotimaan BenJaminin lasten, meidän veljeimme kanssa? Herra sanoi: menkäät heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Ja Israelin lapset kävivät edes toisena päivänä BenJaminin lapsia vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Ja BenJaminilaiset läksivät Gibeasta toisena päivänä heitä vastaan ja löivät vielä nyt kahdeksantoistakymmentä tuhatta miestä Israelin lapsista maahan, jotka kaikki miekkaa vetivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Silloin menivät kaikki Israelin lapset ja kaikki kansa ylös ja tulivat Jumalan huoneesen, itkivät ja oleskelivat siellä Herran edessä, ja paastosivat sen päivän ehtoosen asti, ja uhrasivat polttouhria ja kiitosuhria Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Ja Israelin lapset kysyivät Herralta; ja Jumalan liitonarkki oli siihen aikaan siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Ja Pinehas Eleatsarin poika, Aaronin pojan, seisoi hänen edessänsä sillä ajalla ja sanoi: pitääkö meidän vielä menemän sotimaan BenJaminin lapsia meidän veljiämme vastaan, taikka pitääkö meidän lakkaaman? Herra sanoi: menkäät sinne, huomenna minä annan heidät teidän käsiinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Ja Israelin lapset panivat väijytykset joka taholta Gibean ympärille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Ja Israelin lapset menivät kolmantena päivänä BenJaminin lapsia vastaan ja asettivat heitänsä Gibeaa vastaan, niinkuin he ennenkin kaksi kertaa tekivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Niin menivät BenJaminin lapset kansaa vastaan, ja erkausivat kaupungista, rupesivat lyömään ja haavoittamaan monikahtoja kansasta, niinkuin ennenkin niillä kahdella erällä, kedolla kahden tien päällä, joista yksi menee BetEliin ja toinen Gibeaan, liki kolmekymmentä miestä Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Niin BenJaminin lapset sanoivat: he ovat lyödyt meidän edessämme niinkuin ennenkin. Vaan Israelin lapset sanoivat: paetkaamme ja houkutelkaamme heitä kaupungista ulos teiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Niin nousivat kaikki miehet Israelista, jokainen siastansa, ja asettivat heitänsä BaalTamariin; ja Israelin väijyjät nousivat siastansa Gabaan luolasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Ja kymmenentuhatta valittua miestä kaikesta Israelista tuli Gibeaa vastaan, ja sota tuli sangen raskaaksi; mutta ei ne tietäneet onnettomuuden heitä lähestyvän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Ja Herra löi BenJaminin Israelin edestä, niin että Israelin lapset sinä päivänä löivät viisikolmattakymmentä tuhatta ja sata miestä BenJaminista, jotka kaikki miekkaa vetivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Mutta kuin BenJaminin lapset näkivät heitänsä lyödyksi, antoivat Israelin miehet heille siaa; sillä he uskalsivat väijytyksensä päälle, jotka he olivat asettaneet liki Gibeaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Ja väijyjät kiiruhtivat, karkasivat Gibeaan, menivät ja löivät koko kaupungin miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Ja Israelin miehillä oli määrätty aika keskenään väijyjäin kanssa, lyödä heitä miekalla, koska savu nousi kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Kuin Israelin miehet käänsivät itsensä sotaan, ja BenJaminilaiset rupesivat lyömään ja haavoittamaan Israelia, liki kolmekymmentä miestä, niin he sanoivat: tosin he ovat lyödyt meiltä, niinkuin entisessäkin tappeluksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Niin rupesi savu käymään kohdastansa kaupungista ylös ja BenJaminilaiset palasivat takaperin, ja katso, koko kaupungista savu kävi ylös taivasta kohden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Ja Israelin miehet käänsivät itsensä, ja BenJaminin miehet hämmästyivät; sillä he näkivät, että heitä onnettomuus lähestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Ja he käänsivät itsensä Israelin miesten edessä korven tielle; mutta sota saavutti heidät: sitälikin niitä jotka kaupungeista olivat, surmasivat he siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Ja ne piirittivät BenJaminin, ja ajoivat takaa Menuaan asti, ja tallasivat niitä Gibean kohdalla, auringon ylenemistä päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Ja BenJaminista lankesi kahdeksantoistakymmentä tuhatta miestä, jotka kaikki olivat vahvat sotamiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Niin käänsivät he itsensä ja pakenivat korpeen päin Rimmonin vuorelle, mutta sillä tiellä löivät he viisituhatta miestä, ja ajoivat heitä takaa Gibeoniin asti, ja löivät heistä kaksituhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Ja kaikki jotka sinä päivänä BenJaminista lankesivat, olivat viisikolmattakymmentä tuhatta miestä, jotka miekkaa vetivät ulos, ja olivat kaikki vahvat sotamiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Ainoasti kuusisataa miestä käänsi itsensä ja pakeni jälleen korpeen Rimmonin vuorelle, ja jäivät Rimmonin vuorelle neljäksi kuukaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Ja Israelin lapset tulivat jällensä BenJaminin lasten tykö ja löivät ne kaupungista miekan terällä, sekä kansan että eläimet, ja kaikki mitä he löysivät; ja kaikki kaupungit jotka he löysivät, polttivat he tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Ja Israelin miehet olivat vannoneet Mitspassa ja sanoneet: ei yksikään meistä pidä tytärtänsä antaman BenJaminilaisille emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Ja kansa tuli Jumalan huoneesen ja oli siellä Jumalan edessä ehtoosen asti; ja he korottivat äänensä ja itkivät katkerasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Ja sanoivat: O Herra Israelin Jumala, miksi tämä tapahtui Israelissa, että tänäpänä on yksi sukukunta Israelista vähentynyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Ja toisena päivänä nousi kansa varhain ja rakensi siihen alttarin, ja uhrasi polttouhria ja kiitosuhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Ja Israelin lapset sanoivat: kuka on kaikista Israelin sukukunnista, joka ei tänne ole tullut kansan kanssa Herran eteen? Sillä suuri vala oli tehty, että se joka ei tullut Herran tykö Mitspaan, hänen piti totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Ja Israelin lapset katuivat veljensä BenJaminin tähden ja sanoivat: tänäpänä on yksi sukukunta Israelista hävitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Ja kuinka me käytämme itsemme heidän kanssansa, että jääneet saisivat emäntiä? sillä me olemme vannoneet Herran kautta, ettemme anna heille emäntiä meidän tyttäristämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Ja he sanoivat: kuka on Israelin sukukunnassa, joka ei ole tänne tullut Herran tykö Mitspaan? ja katso, ei ole yksikään ollut leirissä kansan seassa Jabeksesta Gileadissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Ja kansa luettiin: ja katso, ei ollut siellä yhtäkään Jabeksen asuvaa Gileadista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Niin he lähettivät sinne kansasta kaksitoistakymmentä tuhatta sotamiestä ja käskivät heitä, sanoen: menkäät ja lyökäät Jabeksen asuvaiset Gileadissa miekan terällä vaimoinensa ja lapsinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Mutta näin pitää teidän tekemän: kaiken miehenpuolen ja kaikki vaimot, jotka miesten kanssa ovat maanneet, pitää teidän tappaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Ja he löysivät Jabeksen asuvaisista Gileadissa neljäsataa piikaa, jotka neitseet olivat ja ei olleet yhdenkään miehen tykönä maanneet, ne he veivät Silon leiriin, joka on Kanaanin maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Niin koko kansa lähetti matkaan ja käski sanoa BenJaminin lapsille, jotka olivat Rimmonin kalliolla, ja kutsuivat heitä ystävällisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Ja BenJaminin lapset tulivat silloin jälleen, ja he antoivat heille emäntiä niistä jotka he olivat jättäneet elämään Jabeksen vaimoista Gileadissa; ja ei niinkään heille täytynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Niin kansa katui BenJaminin tähden, että Herra oli loven tehnyt Israelin sukukunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Ja kansan vanhimmat sanoivat: kuinka me teemme, että jääneet saisivat myös emäntiä? sillä vaimoväki BenJaminissa on hukutettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Ja sanoivat: niiden pitää kuitenkin nautitseman perimisensä, jotka jääneet ovat BenJaminista, ettei yksikään sukukunta Israelista hävitettäisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Ja emme taida antaa heille meidän tyttäriämme emänniksi; sillä Israelin lapset ovat vannoneet ja sanoneet: kirottu olkoon se, joka BenJaminilaisille emännän antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Ja he sanoivat: katso, Herran jokavuotinen juhlapäivä on Silossa, joka on BetElistä pohjoiseen päin, auringon nousuun päin siitä tiestä, joka menee BetElistä Sikemiin, ja länteen päin Lebonasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Ja he käskivät BenJaminin lapsille ja sanoivat: menkäät ja väijykäät viinamäissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Ja kuin näette Silon tyttäret käyvän ulos hyppyyn, niin juoskaat kiiruusti viinamäistä, ja ottakaat jokainen teillenne Silon tyttäristä emännän, ja menkäät BenJaminin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Kuin heidän isänsä taikka veljensä tulevat valittamaan meidän eteemme, niin me sanomme heille: olkaat heille armiaat, sillä emme ole ottaneet heille emäntää sodalla; mutta ette tahtoneet heille antaa: tämä on teidän syynne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'BenJaminin lapset tekivät niin ja ottivat hypyistä lukunsa jälkeen vaimot ryövyydellä, ja menivät pois ja asuivat perinnössänsä, rakensivat kaupungeita ja asuivat niissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Israelin lapset menivät myös sieltä pois silloin, itsekukin sukukuntansa ja lankoutensa tykö, ja menivät sieltä itsekukin perimiseensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Silloin ei ollut kuningasta Israelissa, vaan jokainen teki niinkuin hänelle näkyi oikein olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Ja tuomarien hallitessa oli kallis aika maalla, ja mies Juudan Betlehemistä meni vaeltamaan Moabilaisten maalle, hän ja hänen emäntänsä ja kaksi hänen poikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Hänen nimensä oli EliMelek, ja hänen emäntänsä nimi Noomi, ja hänen kahden poikansa nimi Mahlon ja Kiljon, he olivat Ephratilaisia Juudan Betlehemistä. Ja kuin he tulivat Moabilaisten maalle, pysyivät he siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Ja EliMelek Noomin mies kuoli, ja hän jäi hänestä kahden poikansa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'He naivat Moabilaisia vaimoja: yhden nimi oli Orpa ja toisen nimi Ruut, ja asuivat siellä liki kymmenen ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Ja kuolivat nekin molemmat, sekä Mahlon että Kiljon, ja se vaimo jäi jälkeen kahdesta pojastansa ja miehestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Ja hän nousi miniöinensä ja palasi Moabilaisten maalta; sillä hän oli Moabilaisten maalla ollessansa kuullut, että Herra oli etsinyt kansaansa ja antanut heille leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Ja hän läksi pois siitä paikasta, jossa hän oli ollut, molempain miniöinsä kanssa; ja kuin he matkustivat tiellä palataksensa Juudan maalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Sanoi Noomi kahdelle miniällensä: menkäät ja palatkaat kukin teidän äitinne huoneesen: tehköön Herra teille laupiuden, niinkuin te olette niille kuolleille ja minulle tehneet!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Herra antakoon teidän kummankin löytää levon miehensä huoneessa! Ja hän suuta antoi heidän, ja he korottivat äänensä ja itkivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'Ja sanoivat hänelle: sinun kanssas me käymme kansas tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Mutta Noomi sanoi: palatkaat, tyttäreni: miksi te tahdotte minun kanssani käydä? kuinka minä taidan lapsia saada minun kohdussani teille mieheksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Palatkaat, minun tyttäreni, ja menkäät, sillä minä olen ylen vanha miestä ottamaan; ja vaikka minä sanoisin: se on toivottava, että minä ottaisin tänä yönä itselleni miehen ja synnyttäisin poikia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Kuinka te odottaisitte niinkauvan kuin ne suureksi tulisivat? Ja kuinka te taidatte viivyttää, ettette ota miestä? Ei, minun tyttäreni: sillä minä suuresti murehdin teidän tähtenne, ja Herran käsi on sattunut minuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Niin he korottivat äänensä ja itkivät vielä hartaammasti; ja Orpa antoi suuta anoppinsa, mutta Ruut riippui hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Mutta hän sanoi hänelle: katsos, kälys on palannut omaistensa tykö ja jumalainsa tykö: palaja sinäkin kälys kanssa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruut vastasi: älä minulle sitä puhu, että minä luovun sinusta ja palajan pois tyköäs; sillä kuhunka sinä menet, sinne myös minä menen, ja kussa sinä yödyt, siellä tahdon myös minä yötä olla: sinun kansas on minun kansani, ja sinun Jumalas on minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Kussa sinä kuolet, siellä minäkin tahdon kuolla ja itseni haudattaa antaa. Herra tehköön minulle sen ja sen, jos ei ainoastaan kuolema eroita meitä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Kuin hän näki hänen täydellä mielellä häntä seuraavan, lakkasi hän sitä puhumasta hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Ja he matkustivat kahden Betlehemiin asti. Ja kuin he tulivat Betlehemiin, liikkui koko kaupunki heidän tähtensä, ja sanoivat: onko tämä Noomi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Mutta hän sanoi heille: älkäät minua kutsuko Noomi, vaan kutsukaat minua Mara; sillä Kaikkivaltias on minun suuresti surulliseksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Täysinäisenä minä täältä läksin, vaan Herra antoi minun tyhjänä palata. Miksi te siis kutsutte minua Noomi? sillä Herra on minun alentanut ja Kaikkivaltias on minua vaivannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Ja niin palasi Noomi, ja Ruut Moabilainen hänen miniänsä palasi hänen kanssansa Moabilaisten maalta; ja he tulivat Betlehemiin ohran leikkaamisen alussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Oli myös Noomin miehen lanko, jalo, voimallinen mies, EliMelekin suvusta; ja hänen nimensä oli Boas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Ja Ruut Moabilainen sanoi Noomille: salli minun mennä pellolle päitä noukkimaan sen perässä, jonka edessä minä löydän armon. Sanoi hän hänelle: mene, tyttäreni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Ja hän meni ja pääsi noukkimaan pellolla elonleikkaajain jälissä, ja se pelto, johon hän osaantui, oli Boaksen perintöosa, joka oli EliMelekin suvusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Ja katso, Boas tuli Betlehemistä ja sanoi elonleikkaajille: Herra olkoon teidän kanssanne. Ja he sanoivat hänelle: Herra siunatkoon sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Ja Boas sanoi palveliallensa, elonleikkaajain päämiehelle: kenenkä tämä piika on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Ja palvelia, elonleikkaajain päämies, vastasi ja sanoi: se on Moabilainen piika, joka tuli Noomin kanssa Moabilaisten maalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Ja hän sanoi: anna minun noukkia ja koota lyhdetten välillä elonleikkaajain perässä. Ja hän on tullut ja seisonut aamusta niin tähänasti, ja on vaan vähän aikaa huoneessa ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Ja Boas sanoi Ruutille: kuules minua, tyttäreni! Älä mene muiden pellolle poimimaan, älä myös tästä lähde, mutta ole tässä minun piikaini kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Katso visusti, millä pellolla he eloa ottavat, ja seuraa heitä: minä sanoin palvelioilleni, ettei yksikään sinua vahingoitse. Ja jos sinä janoat, niin mene astiain tykö ja juo siitä, mitä minun palveliani ovat ammuntaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Ja hän lankesi kasvoillensa ja kumarsi maahan, ja sanoi hänelle: minkätähden olen minä löytänyt armon sinun kasvois edessä, että tunnet minun, joka kuitenkin olen muukalainen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boas vastasi ja sanoi hänelle: minulle ilmoitettiin kaikki, mitäs tehnyt olet anopilles, sittekuin sinun miehes kuoli: ettäs jätit isäs ja äitis, ja isäs maan, ja matkustit kansan tykö, jota et sinä ennen tuntenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Herra maksakoon sinulle työs, ja sinun palkkas olkoon täydellinen Herran Israelin Jumalan tykönä, jonka tykö sinä olet tullut, turvaamaan hänen siipeinsä alle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Hän sanoi: anna minun löytää armo sinun kasvois edessä, minun herrani; sillä sinä olet lohduttanut minua ja olet puhutellut piikaas suloisesti, vaikka en minä ole niinkuin joku sinun piioistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Boas sanoi jälleen hänelle: koska ruan aika joutuu, niin tule tänne, syö leipää ja kasta palas etikkaan. Niin hän istui elonleikkaajain viereen, ja hän antoi hänelle kuivatuita tähkäpäitä, hän söi ja ravittiin, ja jätti jotakin tähteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Kuin hän nousi poimimaan, käski Boas palvelioitansa ja sanoi: sallikaat hänen poimia lyhdetten keskellä ja älkäät häntä häväiskö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Varistelkaat myös sitomista läpimitten hänelle, ja jättäkäät siihen, että hän ne poimis, ja älkään yksikään häntä nuhdelko!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Niin poimi hän pellolla ehtooseen asti, ja hän tappoi ne poimitut; ja oli liki yksi epha ohria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Ja hän kantoi ne ja vei kaupunkiin, ja osoitti anopillensa, mitä hän oli poiminut. Toi myös ne ruan tähteet, joista hän oli itsensä ravinnut ja antoi hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Silloin sanoi hänen anoppinsa hänelle: kussas olet poiminut tänäpänä, ja kussas olet työtä tehnyt? Siunattu olkoon se, joka sinun tuntenut on! Ja hän ilmoitti anopillensa, kenenkä tykönä hän työtä teki, sanoen: se mies, jonka tykönä minä tänäpänä työtä tein, kutsutaan Boas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Noomi sanoi miniällensä: hän olkoon siunattu Herralta, joka ei ole ollut armotoin enemmin eläviä kuin kuolleitakaan vastaan. Ja Noomi sanoi hänelle: tämä mies on meidän lähimmäisemme ja on meidän perillisemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Ja Ruut Moabilainen sanoi: hän sanoi myös minulle: ole minun palvelioitteni kanssa, siihenasti kuin he lopettavat kaiken minun eloni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Noomi sanoi Ruutille miniällensä: minun tyttäreni, hyvä on sinun mennä hänen piikainsa kanssa, ettei joku olisi sinua vastoin toisen pellolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Ja hän viipyi Boaksen piikain tykönä ja poimi tähkäpäitä, siihenasti kuin ohrat ja nisut leikattiin; ja tuli jälleen anoppinsa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Ja Noomi hänen anoppinsa sanoi hänelle: minun tyttäreni, minä tahdon saattaa sinulle levon, että sinulle hyvin kävis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Boas, meidän sukulaisemme, jonka piikain tykönä sinä olet ollut, katso, hän viskaa tänä yönä ohria luvassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Niin pese itses ja voitele sinus, ja vaateta itses ja mene luvaan, ettei yksikään sinua tunne, siihenasti kuin syöty ja juotu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Kuin hän maata panee, niin katso paikka, kussa hän makaa: niin mene ja nosta vaate hänen jalkainsa päältä ja pane siihen maata; niin hän kyllä sinulle sanoo, mitä sinun tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Hän sanoi hänelle: kaikki, mitä sinä sanot minulle, teen minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Hän meni luvaan ja teki kaikki mitä hänen anoppinsa hänelle käski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Ja kuin Boas oli syönyt ja juonut, tuli hänen sydämensä iloiseksi, ja hän meni levätä yhden kuhilaan taa. Ja hän tuli salaisesti ja nosti vaatteen hänen jalkainsa päältä, ja pani siihen levätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Puoliyön aikaan peljästyi mies ja käänsi itsensä: ja katso, vaimo makasi hänen jalkainsa juuressa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Ja hän sanoi: kukas olet? Hän vastasi: minä olen Ruut, sinun palkollises: levitä siipes piikas ylitse, sillä sinä olet perillinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Hän sanoi: siunattu ole sinä Herrassa, minun tyttäreni: sinä olet parantanut ensimäisen armotyön sillä viimeisellä, ettes ole seurannut nuorukaisia, köyhiä eli rikkaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Ja nyt, tyttäreni, älä pelkää: kaikki, mitäs sanot, teen minä sinulle; sillä koko minun kansani kaupunki tietää, ettäs olet kunniallinen vaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Se on tosi, että minä olen perillinen; mutta toinen on läheisempi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Ole tässä yö, ja jos hän huomenna omistaa sinun, niin se on hyvä, vaan jollei hän tahdo omistaa sinua, niin minä omistan sinun, niin totta kuin Herra elää: lepää huomeneen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Ja hän lepäsi huomeneen asti hänen jalkainsa juuressa, ja nousi ennenkuin yksikään toisensa tunsi, ja sanoi: ei pidä kenenkään tietämän vaimon luvaan tulleeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Ja hän sanoi: anna liinavaattees joka ylläs on, ja ota siihen; ja hän otti siihen. Ja hän mittasi hänelle kuusi mittaa ohria ja pani ne hänen päällensä. Ja hän itse tuli kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Mutta vaimo meni anoppinsa tykö, joka sanoi: kuinka sinulle menestyy, tyttäreni? Ja hän jutteli hänelle kaikki, mitä mies oli tehnyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'Ja sanoi: nämät kuusi mittaa ohria antoi hän minulle; sillä hän sanoi: ei pidä sinun tyhjin käsin menemän anoppis tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Hän sanoi: ole hiljakses, tyttäreni, niinkauvan että sinä saat nähdä, kuinka tämä tapahtuu; sillä ei se mies lakkaa ennen kuin hän tämän tänäpäivänä hyvin lopettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Ja Boas meni porttiin ja istui siellä; ja katso, perillinen kävi ohise, ja Boas puhutteli häntä, sanoen: palaja tänne ja istu viereeni, ole kukas olet. Niin hän palasi ja istui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Ja hän otti kymmenen miestä kaupungin vanhimmista, sanoen heille: istukaat tähän; ja he istuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Niin sanoi hän perilliselle: sitä maan kappaletta, joka oli meidän veljellämme EliMelekillä, kaupitsee Noomi, joka on tullut Moabilaisten maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Sentähden ajattelin minä sen sinulle ilmoittaa ja sanoa: jos tahdot sen todella periä, niin lunasta se tässä kaupungin asuvaisten ja kansani vanhimpain edessä; vaan jollet sinä sitä tahdo periä, niin sano minulle, että minä sen tietäisin; sillä ei ole yhtään muuta perillistä kuin sinä ja minä sinun jälkees. Hän sanoi: minä perin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Niin vastasi Boas: jona päivänä sinä Noomin kädestä lunastat pellon, niin ota Ruut Moabilainen, vainajan emäntä, herättääkses kuolleelle nimeä hänen perinnössänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Niin sanoi perillinen: en minä taida periä sitä, etten minä hukuttaisi omaa perimistäni: peri sinä se mitä minun tulisi periä; sillä en minä taida sitä periä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Ja muinen oli Israelissa lunastamisessa ja perimisessä vahvistukseksi kaikkiin asioihin, että mies riisui kenkänsä ja antoi lähimmäisellensä: ja se oli todistus Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Niin perillinen sanoi Boakselle: lunasta sinä se; ja riisui kengän jalastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Boas anoi vanhimmille ja kaikelle kansalle: te olette tänäpäivänä todistajani, että minä olen lunastanut Noomilta kaikki mitä EliMelekin, Kiljonin ja Mahlonin oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Ja myös Ruutin Moabilaisen, Mahlonin lesken, olen ottanut emännäkseni, herättääkseni kuolleelle nimeä hänen perimisessänsä, ja ettei kuolleen nimi hukkuisi veljeinsä seasta ja hänen siastansa portissa; sen päälle olette te tänäpäivänä todistajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Niin kansa ja vanhimmat, jotka portissa olivat, sanoivat: me olemme todistajat. Herra tehköön vaimolle, joka sinun huoneeses tulee, niinkuin Rakelille ja niinkuin Lealle, jotka molemmat Israelin huoneen rakensivat, ja enentyköön voimas Ephratassa, ja tullos kuuluisaksi Betlehemissä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Ja sinun huonees olkoon niinkuin Peretsen huone, jonka Tamar synnytti Juudalle, siitä siemenestä, jonka Herra sinulle antaa tästä nuoresta vaimosta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Niin Boas otti Ruutin emännäksensä, ja hän meni hänen tykönsä; ja Herra antoi hänen tulla hedelmälliseksi, ja hän synnytti pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Niin vaimot sanoivat Noomille: kiitetty olkoon Herra, joka ei sallinut sinulta puuttua perillistä tähän aikaan, että hänen nimensä pysyis Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Hän on virvoittava sinua ja holhoova sinun vanhuuttas; sillä sinun miniäs, joka sinua rakastaa, on hänen synnyttänyt; hän itse on sinulle parempi kuin seitsemän poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Ja Noomi otti lapsen, pani helmaansa ja kasvatti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Mutta hänen kylänsä vaimot antoivat hänelle nimen ja sanoivat: Noomille on poika syntynyt; ja kutsuivat hänen nimensä Obed: tämä on Davidin isän Isain isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Tämä on Peretsin sukukunta: Perets siitti Hetsronin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Ja Hetsron siitti Raamin: Raam siitti Amminadabin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadab siitti Nahessonin: Nahesson siitti Salmon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmo siitti Boaksen: Boas siitti Obedin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed siitti Isain, ja Isai siitti Davidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Yksi mies oli Ramataimin Zophimista Ephraimin vuorelta, ja hänen nimensä oli Elkana Jerohamin poika, Elihun pojan, Tohun pojan, Zuphin pojan, joka oli Ephratista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Ja hänellä oli kaksi vaimoa, yhden nimi oli Hanna ja toisen nimi Peninna; ja Peninnalla oli lapsia, mutta Hannalla ei ollut lasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Se mies meni vuosivuodelta kaupungistansa Siloon rukoilemaan ja uhraamaan Herralle Zebaotille; ja siellä oli kaksi Elin poikaa, Hophni ja Pinehas, Herran papit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Ja sinä päivänä, jona Elkana uhrasi, antoi hän emännällensä Peninnalle ja kaikille hänen pojillensa ja tyttärillensä osat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Mutta Hannalle antoi hän yhden osan murehtien, sillä hän rakasti Hannaa; mutta Herra oli sulkenut hänen kohtunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Ja hänen vainoojansa vaivasi häntä ja soimasi hänelle, että Herra oli sulkenut hänen kohtunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Ja niin hän teki joka vuosi, kuin he menivät Herran huoneesen, ja saatti hänen murheelliseksi. Mutta hän itki ja ei syönyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Ja Elkana hänen miehensä sanoi hänelle: Hanna, mitäs itket? ja miksi et syö? ja minkätähden sinun sydämes on murheellinen? enkö minä sinulle parempi ole kuin kymmenen poikaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Niin nousi Hanna, sittekuin hän oli syönyt ja juonut Silossa; ja pappi Eli istui istuimella Herran templin pihtipielen tykönä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'Ja Hanna oli sangen katkeralla sydämellä, ja rukoili Herraa, ja itki hartaasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'Ja lupasi lupauksen, sanoen: Herra Zebaot! jos sinä armossa katsoisit piikas ahdistusta, muistaisit minua ja et unhottaisi piikaas, mutta antaisit piialles pojan; niin minä annan hänen Herralle kaikiksi hänen ikäpäiviksensä, ja partaveitsi ei pidä hänen päähänsä tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Ja kuin hän kauvan rukoili Herran edessä, otti Eli vaarin hänen suustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Sillä Hanna puhui sydämessänsä, ja ainoastaan hänen huulensa liikkuivat, mutta hänen äänensä ei kuulunut; niin Eli luuli hänen juovuksissa olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Ja Eli sanoi hänelle: kuinka kauvan sinä olet juovuksissa? anna viinan olla sinustas pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Mutta Hanna vastasi ja sanoi: ei, herrani! minä olen murheellinen vaimo: viinaa ja väkevää juomaa en ole minä juonut, vaan olen vuodattanut sydämeni Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Älä pidä piikaas irstaisena vaimona, sillä minä olen suuresta murheestani ja vaivastani tähänasti puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eli vastasi ja sanoi: mene rauhaan, ja Israelin Jumala antakoon sinulle rukoukses, jonka sinä olet häneltä rukoillut!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Hän sanoi: anna sinun piikas löytää armo silmäis edessä. Niin vaimo meni matkaansa ja söi, ja ei ollut silleen niin murheellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Ja he nousivat varhain huomeneltain rukoilemaan Herraa; sitte palasivat he ja tulivat kotiansa Ramaan. Ja Elkana tunsi emäntänsä Hannan, ja Herra muisti häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Ja kuin muutamat päivät olivat kuluneet, tuli Hanna raskaaksi ja synnytti pojan ja kutsui hänen nimensä Samuel: sillä minä olen häntä rukoillut Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Ja Elkana meni ylös kaiken huoneensa kanssa, uhraamaan Herralle vuosikautista uhria ja lupaustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Ja ei Hanna mennyt ylös, vaan sanoi miehellensä: kuin lapsi vieroitetaan, niin minä otan hänen kanssani näyttääkseni Herralle, ja sitte pitää hän siellä aina oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Elkana hänen miehensä sanoi hänelle: tee niinkuin sinulle parhaaksi näkyy, ole niinkauvan ettäs hänen vieroitat: Herra vahvistakoon sen minkä hän puhunut on. Niin vaimo jäi kotia ja imetti poikaansa, siihenasti että hän vieroitti hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Ja hän toi hänen ylös kanssansa, sittekuin hän hänen vieroittanut oli, kolmen mullin kanssa, yhden ephan jauhoja ja leilin viinaa: ja toi hänen Herran huoneesen Silossa, ja nuorukainen oli vielä sangen nuori.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Ja he teurastivat mullin, ja toivat nuorukaisen Elin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Ja hän sanoi: Ah, herrani! niin totta kuin sinun sielus elää, herrani, minä olen se vaimo, joka tässä tykönäs seisoi ja rukoili Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Tätä nuorukaista minä anoin: nyt on Herra minulle antanut minun rukoukseni, jonka minä häneltä rukoilin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Sentähden annan minä hänen Herralle jälleen kaikeksi elinajaksensa, että hän Herralta rukoiltu on; ja hän rukoili Herraa siinä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Ja Hanna rukoili ja sanoi: minun sydämeni riemuitsee Herrassa, minun sarveni on ylennetty Herrassa. Minun suuni on leviältä auvennut minun vihollisteni ylitse; sillä minä riemuitsen sinun autuudestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Ei kenkään niin pyhä ole kuin Herra; sillä ei yksikään ole paitsi sinua, ja ei yhtään kalliota ole niinkuin meidän Jumalamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Lakatkaat suuresta kerskaamisestanne, pankaat pois teidän suustanne se vanha; sillä Herra on kaikkitietävä Jumala, ja ei anna senkaltaisia aivoituksia menestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Väkeväin joutset ovat särjetyt, ja heikot ovat väkevyydellä vyötetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Jotka ennen ravitut olivat, ne ovat itsensä myyneet leivän edestä, jotka nälkää kärsivät, ei silleen isoa, siihen asti että hedelmätöin seitsemän synnytti, ja jolla monta lasta oli, tuli heikoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Herra kuolettaa ja virvoittaa, vie suureen ahdistukseen ja siitä ulos jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Herra tekee köyhäksi ja rikkaaksi, hän alentaa ja ylentää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Hän nostaa tomusta köyhän ja ylentää vaivaisen loasta, istuttaaksensa häntä päämiesten sekaan ja antaaksensa hänen kunnian istuimen periä; sillä maan perustukset ovat Herran, ja maan piirin on hän asettanut niiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Hän varjelee pyhäin jalat, mutta jumalattomat pitää vaikenemaan pimeydessä; sillä oma suuri voima ei mitään auta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Ne, jotka riitelevät Herran kanssa, pitää muserrettaman rikki, hän jylisee taivaassa heidän ylitsensä. Herra tuomitsee maan ääret, ja antaa kuninkaallensa väkevyyden, ja ylentää voideltunsa sarven.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Ja Elkana meni Ramaan huoneesensa; vaan nuorukainen palveli Herraa papin Elin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Mutta Elin pojat olivat ilkiät ja ei totelleet Herraa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Eikä myös pappein oikeutta kansan edessä: kuin joku uhrin uhrasi, tuli papin palvelia, kuin liha keitettiin, ja oli kolmehaarainen hanko kädessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'Ja pisti sen kattilaan, eli pataan, eli kruusiin, eli pannuun, ja kaikki mitä hän veti ylös hangolla, sen pappi otti siitä; ja niin tekivät he kaikelle Israelille, jotka tulivat sinne Siloon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Niin myös ennenkuin he polttivat lihavuuden, tuli papin palvelia ja sanoi niille, jotka uhria kantoivat: anna lihaa paistettaa papille, sillä ei hän ota keitettyä lihaa sinulta vaan uutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Kuin joku sanoi hänelle: polttakaat lihavuus tänäpänä niinkuin pitää, ota sitte sinulles, mitä sydämes himoitsee. Niin sanoi hän hänelle: nyt pitää sinun antaman, jolles anna, niin minä otan väkisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Ja sentähden oli nuorukaisten rikos sangen suuri Herran edessä; sillä kansa katsoi Herran ruokauhrin ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Mutta Samuel palveli Herran edessä, ja nuorukainen oli vyötetty liinaisella päällisvaatteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Ja hänen äitinsä oli tehnyt hänelle vähän hameen, ja vei sen hänelle joka vuosi, kuin hän meni ylös miehensä kanssa uhraamaan vuosiuhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Ja Eli siunasi Elkanan ja hänen emäntänsä ja sanoi: Herra antakoon sinulle siemenen tästä vaimosta sen rukouksen tähden, jonka hän on rukoillut Herralta; ja he menivät siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Ja Herra oppi Hannaa, ja hän tuli raskaaksi ja synnytti kolme poikaa ja kaksi tytärtä; ja nuorukainen Samuel kasvoi Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Mutta Eli oli juuri vanha, ja kuuli, mitä hänen poikansa tekivät kaikelle Israelille ja että he makasivat vaimoin kanssa, jotka palvelivat seurakunnan majan ovella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'Ja sanoi heille: miksi te teette senkaltaisia? sillä minä kuulen teidän pahoja tekojanne kaikelta tältä kansalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ei niin, minun poikani! ei ole se hyvä sanoma, jonka minä kuulen, että te saatatte Herran kansan syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Jos joku rikkoo ihmistä vastaan, niin tuomarit sen sovittavat; mutta jos joku rikkoo Herraa vastaan, kuka sen edestä rukoilee? Ja ei he kuulleet Isänsä ääntä, sentähden Herra tahtoi heidät tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Mutta nuorukainen Samuel vaelsi ja kasvoi, ja oli otollinen sekä Herran että ihmisten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Ja Jumalan mies tuli Elin tykö ja sanoi hänelle: näin sanoo Herra: enkö minä ilmeisesti ilmoittanut minuani sinun isäs huoneelle, kuin he vielä olivat Egyptissä Pharaon huoneessa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Ja minä valitsin hänen minulle papiksi kaikista Israelin sukukunnista uhraamaan minun alttarilleni, ja sytyttämään suitsutusta, ja kantamaan päällisvaatetta minun edessäni: ja minä olen antanut sinun isäs huoneelle kaikki Israelin lasten tulet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Miksi siis te potkitte minun uhriani vastaan ja ruokauhriani, jonka minä olen käskenyt uhrata seurakunnan majassa, ja enemmän kunnioitit poikias kuin minua, lihoittaaksenne teitänne kaikista minun kansani Israelin ruokauhrein uutisista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Sentähden sanoo Herra Israelin Jumala: minä olen vakaisesti puhunut, että sinun huonees ja sinun isäs huone pitää vaeltaman minun edessäni ijankaikkisesti; mutta nyt sanoo Herra: olkoon se kaukana minusta: sillä jotka minua kunnioittavat, niitä minä tahdon kunnioittaa, vaan jotka minua katsovat ylön, ne pitää katsottaman ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Katso, se aika tulee, että minä murran sinun käsivartes ja sinun isäs huoneen käsivarren, ettei yksikään vanha pidä sinun huoneessas oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Ja sinun pitää näkemän sinun vastaanseisojas majassa, kaikessa hyvyydessä, mikä Israelille tapahtuu; ja ei yksikään vanha pidä oleman sinun huoneessas ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'En minä kuitenkaan hävitä kaikkia lapsias minun alttariltani, että minä kulutan sinun silmäs, ja sinun sielus murheesen saatan; mutta kaikki sinun huonees paljous pitää kuoleman, kuin ne ovat mieheksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Ja tämä pitää oleman sinulle merkiksi, mikä sinun poikais Hophnin ja Pinehaan päälle pitää tuleman: yhtenä päivänä pitää molemmat kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Ja minä herätän minulleni uskollisen papin: se tekee niinkuin minun sydämessäni ja mielessäni on. Ja minä rakennan hänelle vahvan huoneen, vaeltaaksensa minun voideltuni edessä hänen elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Ja tapahtuu, että se joka jää jälkeen sinun huoneeses, pitää tuleman ja kumartaman häntä hopiapenningin ja leivän kappaleen edestä, ja pitää sanoman: päästä minua nyt yhden papin osaan, että minä saisin syödä palan leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Ja nuorukainen Samuel palveli Elin edessä Herraa; ja Herran sana oli kallis siihen aikaan, ja ei ollut ilmoituksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Ja tapahtui siihen aikaan, että Eli makasi siallansa, ja hänen silmänsä rupesivat pimentymään, niin ettei hän nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'Ja Samuel makasi Herran templissä, siinä kuin Jumalan arkki oli, ennenkuin Jumalan lamppu sammutettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Ja Herra kutsui Samuelia; hän vastasi: katso, tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Ja hän juoksi Elin tykö ja sanoi: katso, tässä minä olen, sinä kutsuit minua. Hän sanoi: en minä kutsunut, mene jälleen ja pane maata; ja hän meni ja pani maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Ja Herra kutsui taas Samuelia, ja Samuel nousi ja meni Elin tykö, ja sanoi: katso, tässä minä olen, sinä kutsuit minua. Hän sanoi: en minä kutsunut sinua, minun poikani, mene jälleen ja pane maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Mutta Samuel ei tuntenut silloin vielä Herraa; ja Herran sana ei ollut vielä ilmoitettu hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Ja Herra kutsui Samuelia vielä kolmannen kerran, ja hän nousi ja meni Elin tykö, ja sanoi: katso, tässä minä olen, sinä kutsuit minua. Niin ymmärsi Eli, että Herra kutsui nuorukaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Ja Eli sanoi Samuelille: mene ja pane maata, ja jos sinua vielä kutsutaan, niin sano: puhu, Herra! sillä sinun palvelias kuulee. Samuel meni ja pani maata siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Niin tuli Herra ja seisoi siellä, ja kutsui niinkuin ennenkin: Samuel, Samuel. Ja Samuel sanoi: puhu! sillä sinun palvelias kuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Ja Herra sanoi Samuelille: katso, minä teen yhden asian Israelissa, niin että sen molemmat korvat pitää soiman, joka sen kuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Sinä päivänä tuotan minä Elille kaikki ne mitkä minä hänen huonettansa vastaan puhunut olen: minä alan ja päätän sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Ja minä tahdon tehdä hänelle tiettäväksi, että minä olen Tuomari hänen huoneellensa ijankaikkisesti sen pahan työn tähden, että hän tiesi poikansa häpiällisesti itsensä käyttäneen, ja ei kertaakaan vihaisesti katsonut heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Sentähden olen minä vannonut Elin huoneelle, että tämä Elin huoneen pahateko ei pidä lepytettämän uhrilla eikä ruokauhrilla ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Ja Samuel makasi huomeneen asti, ja avasi Herran huoneen oven. Ja Samuel ei tohtinut ilmoittaa Elille sitä näkyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Niin kutsui Eli hänen ja sanoi: Samuel poikani; hän vastasi: katso, tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Hän sanoi: mikä sana se on, joka sinulle sanottiin? älä salaa sitä minulta. Jumala tehköön sinulle sen ja sen, jos sinä jotain salaat minulta siitä mikä sinulle sanottu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Niin Samuel sanoi hänelle kaikki ja ei häneltä mitään salannut. Vaan hän sanoi: hän on Herra, hän tehköön niinkuin hänelle on kelvollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Ja Samuel kasvoi, ja Herra oli hänen kanssansa, ja ei langennut yhtäkään kaikista hänen sanoistansa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Ja koko Israel, hamasta Danista niin BerSabaan, tunsi Samuelin uskolliseksi Herran prophetaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Ja Herra taas ilmestyi hänelle Silossa; sillä Herra oli ilmaantunut Samuelille Silossa Herran sanan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Ja Samuel rupesi saarnaamaan koko Israelin edessä; ja Israel meni sotaan Philistealaisia vastaan, ja he sioittivat heitänsä EbenEtserin tykö, mutta Philistealaiset asettivat leirinsä Aphekiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Ja Philistealaiset valmistivat itsensä Israelia vastaan, ja sota levitti itsensä pitkälle, ja Israel lyötiin Philistealaisilta; ja he löivät siinä tappeluksessa kedolla lähes neljätuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Kuin kansa tuli leiriin, sanoivat Israelin vanhimmat: minkätähden Herra antoi meidän tänäpänä lyötää Philistealaisilta? Ottakaamme Herran liitonarkki Silosta tykömme ja antakaamme sen tulla keskellemme vapahtamaan meitä vihollistemme kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Ja kansa lähetti Siloon, ja he antoivat sieltä tuoda Herran Zebaotin liitonarkin, joka istuu Kerubimin päällä. Ja siellä oli kaksi Elin poikaa, Hophni ja Pinehas, Jumalan liitonarkin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Ja Herran liitonarkin tultua leiriin, huusi kaikki Israel suurella ilohuudolla, niin että maa kajahti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Kuin Philistealaiset kuulivat ilohuudon, sanoivat he: mikä suuri ilohuuto on Hebrealaisten leirissä? Ja kuin he ymmärsivät Herran arkin tulleen leiriin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Pelkäsivät Philistealaiset ja sanoivat: Jumala on tullut leiriin. Ja vielä sitte sanoivat: voi meitä! sillä ei se ole ennen niin ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Voi meitä! kuka pelastaa meitä näiden suurten jumalain käsistä? Nämät ovat ne jumalat, jotka löivät Egyptin korvessa kaikkinaisilla rangaistuksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Olkaat siis rohkiat sydämestä ja olkaat miehet, Philistealaiset, ettei teidän pitäisi palveleman Hebrealaisia, niinkuin he ovat teitä palvelleet: olkaat miehet ja sotilaat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Niin Philistealaiset sotivat, ja Israel lyöttiin, ja jokainen pakeni majaansa, ja se oli sangen suuri tappo, niin että Israelista kaatui kolmekymmentä tuhatta jalkamiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Ja Jumalan arkki otettiin pois; ja kaksi Elin poikaa, Hophni ja Pinehas, kuolivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Silloin juoksi sotajoukosta yksi BenJaminilainen ja tuli sinä päivänä Siloon; ja hän oli reväissyt vaatteensa ja viskonut multaa päänsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Ja katso, kuin hän sinne tuli, istui Eli istuimella, tielle katselemaan; sillä hänen sydämensä oli peljästyksissä Jumalan arkin tähden. Ja kuin mies tuli kaupunkiin, ilmoitti hän sen, ja koko kaupunki parkui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Ja kuin Eli kuuli korkian huudon äänen, kysyi hän: mikä kapina tämä on? Niin tuli mies nopiasti ja ilmoitti sen Elille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Ja Eli oli yhdeksänkymmenen ja kahdeksan ajastaikainen, ja hänen silmänsä olivat jo niin pimenneet, ettei hän nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Ja mies sanoi Elille: minä olen tullut ja paennut tänäpänä sotajoukosta. Mutta hän sanoi: kuinka käy, poikani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Silloin vastasi sanansaattaja ja sanoi: Israel on paennut Philistealaisten edellä, ja suuri tappo on kansassa tapahtunut, ja molemmat sinun poikas, Hophni ja Pinehas, ovat myös kuolleet, ja Jumalan arkki on otettu pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Ja kuin hän kuuli mainittavan Jumalan arkkia, lankesi hän maahan taapäin istuimelta portin tykönä, ja mursi niskansa ja kuoli; sillä hän oli vanha ja raskas mies. Ja hän tuomitsi Israelia neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Ja hänen miniänsä Pinehaan emäntä oli viimeisellensä raskas; kuin hän sen sanoman kuuli, että Jumalan arkki oli otettu pois ja hänen appensa ja miehensä olivat kuolleet, kumarsi hän itsensä ja synnytti; sillä hänen kipunsa kävi hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Ja kuin hän oli kuolemallansa, sanoivat vaimot, jotka seisoivat hänen tykönänsä: älä pelkää, sillä sinulle on poika syntynyt. Mutta ei hän mitään vastannut eikä sitä mieleensä pannut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Ja kutsui sen lapsen Ikabod ja sanoi: kunnia on tullut Israelista pois; sillä Jumalan arkki otettiin pois, ja hänen appensa ja miehensä olivat kuolleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Ja hän taas sanoi: Israelin kunnia on tullut pois, sillä Jumalan arkki on otettu pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Ja Philistealaiset ottivat Jumalan arkin ja veivät sen EbenEtseristä Asdodiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Ja veivät sen sisälle Dagonin huoneesen ja asettivat sen Dagonin rinnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Ja Asdodilaiset nousivat toisena päivänä varhain, ja katso, Dagon makasi suullansa maassa Herran arkin edessä; mutta he ottivat Dagonin ja nostivat entiselle siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Ja he nousivat toisena huomenna, ja katso, Dagon makasi suullansa maassa Herran arkin edessä, mutta Dagonin pää ja molemmat hänen kätensä olivat poikki hakattuina kynnyksellä, ja muu ruumis vain oli jälellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Sentähden Dagonin papit ja kaikki jotka Dagonin huoneesen menevät, ei astu Dagonin kynnykselle Asdodissa tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Mutta Herran käsi oli raskas Asdodilaisten päällä ja hävitti heidät, ja löi Asdodin ja kaiken ympäristön ajoksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Kuin Asdodin miehet näkivät niin olevan, sanoivat he: älkäämme antako Israelin Jumalan arkin olla meidän tykönämme; sillä hänen kätensä on juuri raskas meitä ja jumalaamme Dagonia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Ja he lähettivät ja kutsuivat kaikki Philistealaisten päämiehet tykönsä kokoon, ja sanoivat: mitä me teemme Israelin Jumalan arkille? He vastasivat: antakaat kantaa Israelin Jumalan arkki Gatin ympäri; ja he kantoivat Israelin Jumalan arkin ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Ja kuin he sen kantoivat, nousi suuri kapina kaupungissa Herran käden kautta, ja hän löi kaupungin miehet sekä pienet että suuret; ja he saivat salaiset kivut salaisiin paikkoihinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Niin he lähettivät Jumalan arkin Ekroniin. Kuin Jumalan arkki tuli Ekroniin, huusivat Ekronilaiset ja sanoivat: he ovat vetäneet Israelin Jumalan arkin minun tyköni, surmataksensa minua ja minun kansaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Niin lähettivät he ja kutsuivat kaikki Philistealaisten päämiehet kokoon, ja sanoivat: lähettäkäät Israelin Jumalan arkki siallensa jälleen, ettei hän surmaisi minua ja minun kansaani; sillä kaikessa kaupungissa oli suuri kapina kuoleman tähden, ja Jumalan käsi oli siellä sangen raskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Ja ihmiset, jotka ei kuolleet, olivat lyödyt salaisissa paikoissansa, niin että huuto meni kaupungista ylös taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Ja Herran arkki oli seitsemän kuukautta Philistealaisetn maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Ja Philistealaiset kutsuivat pappinsa ja tietäjänsä kokoon ja sanoivat: mitä meidän pitää Herran arkille tekemän? Antakaat meidän tietää, millä meidän pitää lähettämän häntä siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'He vastasivat: jos te lähetätte Israelin Jumalan arkin, niin älkäät häntä lähettäkö tyhjänä, vaan teidän pitää maksaman hänelle vikauhrin, niin te tulette terveeksi ja saatte tietää, minkätähden hänen kätensä ei teistä lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Mutta he sanoivat: mikä on se vikauhri, jonka meidän hänelle antaman pitää? He vastasivat: viisi kultaista ajosta ja viisi kultaista hiirtä Philistealaisten päämiesten luvun jälkeen; että kaikilla teidän päämiehillänne ja teillä oli yksi vitsaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Tehkäät siis teidän ajostenne kuvat ja teidän hiirtenne kuvat, jotka teidän maanne hävittäneet ovat, kunnioittaaksenne Israelin Jumalaa: hänen kätensä tulee joskus huokiammaksi teille, teidän jumalillenne ja teidän maallenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Miksi te paadutatte sydämenne, niinkuin Egyptiläiset ja Pharao paaduttivat sydämensä? Eikö se niin ole: sittekuin hän heidät häpiään saatti, laskivat he heidän menemään, ja he menivät matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Niin ottakaat ja tehkäät uudet vaunut, ja ottakaat kaksi nuorta imettävää lehmää, joiden päällä ei ole yhtään ijestä vielä ollut, ja pankaat lehmät vaunuin eteen ja salvatkaat heidän vasikkansa kotia heidän jälistänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Ja ottakaat Herran arkki ja pankaat se vaunuin päälle, ja ne kultaiset kalut jotka te hänelle annoitte vikanne sovinnoksi, pankaat arkkuun hänen sivullensa, ja lähettäkäät häntä matkaan, ja antakaat hänen mennä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Ja katsokaat, jos hän menee kohdastansa rajainsa kautta ylös BetSemekseen päin, niin hän on tehnyt meille kaiken tämän suuren pahan; mutta jos ei, niin me tiedämme, ettei hänen kätensä ole meitä liikuttanut, vaan se on meille muutoin tapaturmaisesti tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Miehet tekivät niin, ja ottivat kaksi nuorta imettävää lehmää ja panivat vaunuin eteen, ja salpasivat heidän vasikkansa kotia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Ja panivat Herran arkin vaunuin päälle, niin myös arkun kultaisten hiirten ja ajosten kuvain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Ja lehmät menivät kohdastansa tietä myöten BetSemekseen, ja kävivät aina yhtä tietä ja ammuivat, ja ei poikenneet oikialle taikka vasemmalle puolelle; ja Philistealaisten päämiehet seurasivat heitä BetSemeksen maan ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Mutta BetSemiläiset leikkasivat nisueloansa laaksossa, ja nostivat silmänsä ja näkivät arkin, ja olivat iloiset, että saivat sen nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Mutta vaunut tulivat Josuan BetSemiläisen pellolle, ja seisoivat siinä alallansa, ja siellä oli suuri kivi; ja he halkasivat puita vaunuista, ja uhrasivat lehmät Herralle polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Ja Leviläiset nostivat Herran arkin maahan ja arkun, joka sivussa oli, jossa ne kultaiset kalut olivat, ja panivat suuren kiven päälle. Ja BetSemiläiset uhrasivat sinä päivänä Herralle polttouhria ja muita uhreja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Kuin ne viisi Philistealaisen päämiestä näkivät sen, palasivat he sinä päivänä Ekroniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Ja nämät ovat ne kultaiset ajosten kuvat, jotka Philistealaiset uhrasivat Herralle vikauhriksi: Asdod yhden, Gasa yhden, Asklon yhden, Gat yhden ja Ekron yhden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Ja kultaiset hiiret kaikkein Philistealaisten kaupunkein luvun jälkeen, viiden päämiehen edestä, sekä vahvoista kaupungeista ja maakylistä, siihen suureen Abeliin asti, johonka he panivat Herran arkin; joka on tähän päivään asti Josuan BetSemiläisen pellolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Ja muutamat BetSemiläiset lyötiin, että he katsoivat Herran arkkiin, ja hän löi siitä kansasta viisikymmnetä tuhatta ja seitsemänkymmentä miestä; niin se kansa murehti, että Herra niin suurella vitsauksella löi kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Ja BetSemiläiset sanoivat: kuka on seisovainen Herran edessä, tainkaltaisen pyhän Jumalan? ja kenen tykö hän menee meidän tyköämme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Ja lähettivät sanansaattajat KirjatJearimin asuvaisten tykö ja käskivät heille sanoa: Philistealaiset ovat tuoneet Herran arkin jälleen, tulkaat tänne alas ja viekäät häntä ylös teidän tykönne jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Niin tulivat KirjatJearimin miehet, ja toivat sinne Herran arkin, ja veivät sen Amminadabin huoneesen Gibeaan, ja vihkivät hänen poikansa Eleatsarin ottamaan Herran arkista vaaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Ja siitä päivästä, jona arkki tuli KirjatJearimiin, kului paljon aikaa, kaksikymmentä ajastaikaa; ja koko Israelin huone itki Herran jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Mutta Samuel puhui koko Israelin huoneelle, sanoen: jos te käännätte teitänne kaikesta sydämestänne Herran tykö, niin heittäkäät teiltänne vieraat jumalat ja Astharot pois, ja valmistakaat teidän sydämenne Herran tykö, ja palvelkaat häntä ainoaa, niin hän pelastaa teidät Philistealaisten käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Niin heittivät Israelin lapset heiltänsä Baalin ja Astharotin pois, ja palvelivat ainoaa Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Ja Samuel sanoi: kootkaat kaikki Israel Mitspaan: ja minä rukoilen teidän edestänne Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Ja he tulivat Mitspaan kokoon, ammunsivat vettä ja kaasivat Herran eteen, paastosivat sen päivän, ja sanoivat siinä paikassa: me olemme syntiä tehneet Herraa vastaan! Ja Samuel tuomitsi Israelin lapsia Mitspassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Kuin Philistealaiset kuulivat Israelin lapset kokoontuneeksi Mitspaan, menivät Philistealaisten päämiehet Israelia vastaan. Kuin Israelin lapset sen kuulivat, pelkäsivät he Philistealaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Ja Israelin lapset sanoivat Samuelille: älä lakkaa huutamasta meidän edestämme Herran meidän Jumalamme tykö, että hän meidät pelastais Philistealaisten käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Niin Samuel otti yhden imevän karitsan ja uhrasi sen kokonansa Herralle polttouhriksi; ja Samuel huusi Herran tykö Israelin edestä, ja Herra kuuli hänen rukouksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Ja kuin Samuel uhrasi polttouhrin, lähestyivät Philistealaiset sotimaan Israelia vastaan; mutta Herra jylisti sinä päivänä suurella pauhinalla Philistealaisten ylitse ja peljätti heidät, niin että he lyötiin Israelin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Niin Israelin miehet menivät ulos Mitspasta, ja ajoivat Philistealaisia takaa, ja löivät heidät aina BetKarin alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Ja Samuel otti kiven ja pani Mitspan ja Senin välille, ja kutsui sen nimen EbenEtser, ja sanoi: tähän asti on Herra auttanut meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Ja niin Philistealaiset poljettiin, eikä enää tulleet Israelin rajoille. Ja Herran käsi oli Philistealaisia vastaan niinkauvan kuin Samuel eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Niin Israelin lapset saivat ne kaupungit jälleen, jotka Philistealaiset heiltä olivat ottaneet pois, Ekronista Gatiin saakka, rajoinensa. Ne vapahti Israel Philistealaisten käsistä; sillä Israelilla oli rauha Amorilaisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Ja Samuel tuomitsi Israelia kaiken elinaikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Ja vaelsi joka vuosi ympäri BetElin ja Gilgalin ja Mitspan. Ja kuin hän oli tuominnut Israelia kaikissa näissä paikoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Tuli hän Ramaan jälleen; sillä siellä oli hänen huoneensa ja siellä hän tuomitsi Israelia, ja rakensi Herralle siellä alttarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Ja tapahtui, kuin Samuel vanhentui, että hän pani poikansa Israelin tuomariksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Hänen esikoisensa nimi oli Joel ja toisen Abia, jotka tuomarit olivat BerSabassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Mutta hänen poikansa ei vaeltaneet hänen teissänsä, vaan poikkesivat ahneuden perään, ja ottivat lahjoja, ja käänsivät oikeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Niin kaikki Israelin vanhimmat kokosivat itsensä ja tulivat Samuelin tykö Ramaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'Ja sanoivat hänelle: katso, sinä olet vanhentunut, ja sinun poikas ei vaella sinun teissäs. Niin aseta nyt meille kuningas, joka meitä tuomitsis, niinkuin kaikilla pakanoillakin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Ja Samuel otti sen pahaksi, että he sanoivat: anna meille kuningas, joka meitä tuomitsis; ja Samuel rukoili Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Ja Herra sanoi Samuelille: kuule kansan ääntä kaikissa niissä, mitä he sinulle sanovat; sillä ei he ole sinua hyljänneet, vaan minun he ovat hyljänneet, etten minä heitä hallitsisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Niinkuin he aina tehneet ovat siitä päivästä kuin minä heidät vein Egyptistä tähän päivään asti, ja ovat minun hyljänneet ja palvelleet vieraita jumalia: niin tekevät he myös sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Kuule siis nyt heidän äänensä: kuitenkin ettäs ahkerasti todistat heitä vastaan ja ilmoitat heille kuninkaan oikeuden, joka heitä hallitseva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Ja Samuel sanoi kaikki Herran sanat kansalle, joka häneltä kuningasta anoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Ja sanoi: tämä pitää oleman kuninkaan oikeus, joka teitä vallitseva on: teidän poikanne ottaa hän ja panee vaunu- ja hevosmiehiksensä ja vaunuinsa edelläjuoksioiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Ja panee päämiehiksi tuhannen ja viidenkymmenen päälle, ja kyntäjiksi, joiden hänen peltonsa kyntämän pitää, ja elonleikkaajiksi eloonsa, ja sotakaluinsa ja vaunukaluinsa tekiöiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Ja teidän tyttärenne ottaa hän voidetten tekiöiksi, keittäjiksi ja leipojiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Hän ottaa myös teidän parhaat peltonne, viinamäkenne ja öljypuunne, ja antaa ne palvelioillensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Ja ottaa teiltä kymmenykset teidän jyvistänne ja viinastanne, ja antaa huovillensa ja palvelioillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Hän ottaa myös palvelianne ja piikanne, ja parhaat nuorukaisenne, ja aasinne, ja panee ne työhönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Hän ottaa laumastanne kymmenykset: ja teidän pitää oleman hänen orjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Niin te silloin huudatte kuninkaanne tähden, jonka te olette teillenne valinneet; vaan silloin ei Herra kuule teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Ja ei kansa totellut Samuelin ääntä, vaan sanoi: ei millään muotoa, vaan kuningas pitää meillä oleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Että me myös olisimme niinkuin kaikki muut pakanat, ja että meidän kuninkaamme tuomitsis meitä ja menis edellämme, kuin meidän pitää sotiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Ja niin Samuel kuuli kaikkia niitä mitä kansa sanoi, ja puhui ne Herran korvain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Niin sanoi Herra Samuelille: kuule heidän äänensä ja aseta heille kuningas. Ja Samuel sanoi Israelin miehille: menkäät matkaanne kukin kaupunkiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Niin oli yksi mies BenJaminista, nimeltä Kis, Abielin poika, Serorin pojan, Bekoratin pojan, Aphiaan pojan, Isjeminin pojan; voimallinen mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Hänellä oli poika nimeltä Saul, hän oli kaunis nuori mies, ja ei ollut yksikään häntä kauniimpi Israelin lasten seassa, päätä pitempi kaikkea muuta kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Ja Kis Saulin isä oli kadottanut aasintammansa, ja Kis sanoi pojallensa Saulille: ota palvelioista kanssas ja nouse; mene matkaas ja etsi aasintammat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Ja hän kävi Ephraimin vuoren yli ja Salisan maan lävitse, ja ei he löytäneet; niin he kävivät Salimin maan lävitse, ja ei ne olleet siellä, ja he kävivät Jeminin maan lävitse, ja ei löytäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Kuin he tulivat Zuphin maalle, sanoi Saul palveliallensa, joka hänen kanssansa oli: tule, käykäämme kotia jällensä, ettei minun isäni unhottaisi aasintammoja ja murehtisi meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Mutta se sanoi hänelle: katso, tässä kaupungissa on kuuluisa Jumalan mies: kaikki mitä hän sanoo, se kaiketi tapahtuu. Käykäämme nyt sinne: kuka tietää, hän sanoo meille meidän retkemme, jota vaellamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Saul sanoi palveliallensa: katso, siis me menemme sinne; mutta mitä me viemme miehelle? sillä leipä on kaikki loppunut säkistämme: ei ole meillä yhtään lahjaa vietävää sille Jumalan miehelle: mitä meillä on myötämme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Palvelia vastasi edespäin Saulille ja sanoi: katso, minulla on neljäs osa hopiasikliä tykönäni; antakaamme se sille Jumalan miehelle, että hän sanois meille meidän retkemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Muinaiseen aikaan Israelissa, kuin käytiin Jumalaa etsimään, sanottiin: tulkaat, käykäämme näkiän tykö; sillä se joka nyt on propheta, kutsuttiin muinen näkiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul sanoi palveliallensa: puhees on hyvä: tule, käykäämme. Ja he menivät kaupunkiin, jossa Jumalan mies oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Ja tultuansa kaupungin paltalle, löysivät he piikoja, jotka läksivät vettä ammuntamaan; niille he sanoivat: onko näkiä täällä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'He vastasivat heitä ja sanoivat: on, katso, siellä sinun edessäs: riennä nyt, sillä tänäpänä hän on tullut kaupunkiin, että tänäpänä on kansalla uhri korkeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Kuin tulette kaupunkiin, niin te löydätte hänen, ennenkuin hän menee korkeudelle atrioitsemaan; sillä ei kansa ennen syö, kuin hän siunaa uhrin, sitte ne syövät jotka kutsutut ovat: menkäät siis sinne, sillä juuri nyt te hänen löydätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Ja he menivät ylös kaupunkiin, ja kuin he tulivat keskelle kaupunkia, katso, Samuel kohtasi heidät mennessänsä korkeudelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Mutta Herra oli ilmoittanut Samuelille päivää ennen kuin Saul tuli, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Huomenna tällä ajalla lähetän minä sinun tykös miehen BenJaminin maasta, voitele se minun kansani Israelin päämieheksi: ja hän on vapahtava heitä Philistealaisten käsistä, sillä minä olen katsonut minun kansani puoleen, ja heidän huutonsa on tullut minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Kuin Samuel näki Saulin, vastasi Herra ja sanoi: katso, tämä on se mies, josta minä sinulle sanonut olen: tämä on hallitseva minun kansaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Saul meni Samuelin tykö porttiin ja sanoi: ilmoita minulle, kussa täällä on näkiän huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel vastasi Saulille ja sanoi: minä olen näkiä, mene minun edelläni ylös korkeudelle: ja te syötte tänäpänä minun kanssani, ja huomenna päästän minä sinun: ja kaikki mitä sydämessäs on, ilmoitan minä sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Ja aasintammoja, jotka ovat olleet sinulta kolme päivää poissa, älä silleen murehdi, sillä ne ovat löydetyt: ja kenen kaikki himoittava Israelissa pitää oleman? Eikö ne sinulle tule ja kaikelle isäs huoneelle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul vastasi ja sanoi: enkö minä ole Jeminin poika, kaikkein vähimmästä Israelin suvusta, ja minun sukuni on vähin kaikkein sukukuntain seassa BenJaminista? Miksis senkaltaista minulle puhut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Mutta Samuel otti Saulin palvelioinensa ja vei heidät saliin, ja istutti heidät ylimmäiseksi kaikista niistä, jotka kutsutut olivat, joita oli liki kolmekymmentä miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Ja Samuel sanoi keittäjälle: tuo tänne se kappale, jonka minä sinulle annoin ja käskin tykönäs pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Niin keittäjä kantoi lavan ja sen mikä siinä riippui kiinni, ja hän pani sen Saulin eteen. Ja Samuel sanoi: katso, tämä jäi, laske etees ja syö; sillä se on tähän hetkeen asti sinulle tallella pidetty, silloin kuin minä kutsuin kansan. Niin Saul söi Samuelin kanssa sinä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Ja kuin he menivät korkeudelta alas kaupunkiin, puhui hän Saulin kanssa katon päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Ja he nousivat varhain aamulla. Niin Samuel kutsui Saulin aamuruskon noustessa katon päälle ja sanoi: nouse, ja minä päästän sinun; ja Saul nousi, ja he molemmat menivät ulos, hän ja Samuel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Ja kuin he tulivat kaupungin ääreen, sanoi Samuel Saulille: sano palvelialle, että hän menis meidän edellämme (ja hän meni edellä); mutta seiso sinä nyt tässä, ja minä ilmoitan sinulle, mitä Jumala sanonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Niin otti Samuel öljyastian ja kaasi hänen päänsä päälle, ja antoi suuta hänen ja sanoi: näetkös, että Herra on sinun voidellut päämieheksi perimisensä päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Kuin sinä menet minun tyköäni tänäpänä pois, niin sinä löydät kaksi miestä Rakelin haudan tykönä Zelsassa, BenJaminin rajassa: ne sanovat sinulle: aasintammat, joitas olet lähtenyt etsimään, ovat löydetyt: ja katso, ei isäs pidä silleen lukua aaseista, vaan murehtii teitä ja sanoo: mitä minun pitää tekemän pojalleni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Ja kuin edemmäksi siitä menet, niin sinä tulet Taborin lakeudelle, siinä kohtaavat sinua kolme miestä, jotka Jumalan tykö ylös BetEliin menevät: ensimäinen kantaa kolme vohlaa, ja toinen kantaa kolme kappaletta leipää, ja kolmas kantaa viinaleiliä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Ja ne tervehtivät sinua ystävällisesti, antavat sinulle kaksi leipää: ota ne heidän kädestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Sitte tulet sinä Jumalan korkeudelle, kussa Philistealaisten leirit ovat. Ja pitää tapahtuman, että tultuas kaupunkiin, kohtaat prophetain joukon, jotka ovat tulleet korkeudelta, ja heidän edellänsä kantele ja trumpu, huilut ja harput, ja he propheteeraavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Ja Herran henki tulee sinussa voimalliseksi, ettäs propheteeraat heidän kanssansa ja tulet toiseksi mieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Ja kuin nämät merkit tapahtuvat sinulle, niin tee kaikki, mitä etees tulee; sillä Jumala on sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Mutta sinun pitää menemän minun edelläni alas Gilgaliin, ja katso, minä tulen sinne sinun tykös uhraamaan polttouhria ja kiitosuhria: seitsemän päivää pitää sinun odottaman, siihenasti kuin minä tulen sinun tykös ja ilmoitan sinulle, mitä sinun pitää tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Ja tapahtui, että kuin hän oli kääntänyt selkänsä Samuelin puoleen ja meni hänen tyköänsä pois, antoi Jumala hänelle toisen sydämen; ja kaikki nämät merkit tapahtuivat sinä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Ja kuin he tulivat sinne korkeudelle, katso, prophetain joukko kohtasi häntä, ja Jumalan henki tuli voimalliseksi hänessä, että hän propheteerasi heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Kuin hänen kaikki näkivät jotka ennen hänen tunteneet olivat, ja katso, hän propheteerasi prophetain kanssa, sanoivat he toinen toisellensa: mitä Kisin pojalle tapahtunut on? onko Saul myös prophetain seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Ja yksi vastasi siellä ja sanoi: kuka on heidän isänsä? Siitä on sananlasku tullut onko Saul myös prophetain seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Ja kuin hän lakkasi propheteeraamasta, tuli hän korkeudelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Mutta Saulin setä sanoi hänelle ja hänen palveliallensa: kussa te kävitte? Ja hän sanoi: me etsimme aasintammoja, ja kuin me näimme, ettemme löytäneet, tulimme me Samuelin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Niin sanoi Saulin setä: sano siis minulle, mitä Samuel sanoi teille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul vastasi sedällensä: hän sanoi yksivakaisesti aasintammat jo löydetyksi; mutta kuninkaan valtakunnasta ei hän mitään hänelle puhunut, mitä Samuel hänelle sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Mutta Samuel antoi kutsua kansan kokoon Herran tykö Mitspaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Ja sanoi Israelin lapsille: näin sanoo Herra Israelin Jumala: minä johdatin Israelin Egyptistä, ja vapahdin teidät Egyptiläisten käsistä ja kaikkein valtakuntain käsistä, jotka teitä vaivasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Ja te hylkäsitte tänäpänä teidän Jumalanne, joka teidät kaikesta vastoinkäymisestänne ja murheestanne auttanut on, ja sanoitte: pane meille kuningas. Nyt siis käykäät Herran eteen sukuinne ja päämiestenne jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Kuin Samuel oli koonnut kaikki Israelin sukukunnat, lankesi arpa BenJaminin sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Mutta kuin hän BenJaminin suvun kutsui lankoinensa edes, lankesi arpa Matrin suvun päälle, ja lankesi Kisin pojan Saulin päälle. Ja he etsivät häntä, mutta ei häntä löydetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Ja he kysyivät Herralta, oliko hän vielä sinne tuleva. Herra vastasi: katso, hän on lymyttänyt itsensä astiain alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Niin he juoksivat ja toivat hänen sieltä. Ja hän seisoi kansan keskellä, ja hän oli päätänsä pitempi kaikkea kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Ja Samuel sanoi kaikelle kansalle: näettekö, kenenkä Herra on valinnut? sillä ei hänen vertaistansa ole yhtään kaikessa kansassa. Niin huusi kaikki kansa ja sanoi: olkoon kuninkaalle onneksi!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Ja Samuel sanoi kansalle kaikki valtakunnan oikeuden, ja kirjoitti kirjaan, ja pani sen Herran eteen. Ja Samuel päästi kaiken kansan, itsekunkin kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Ja Saul meni myös kotia Gibeaan, ja yksi osa sotaväestä meni hänen kanssansa, joiden sydämen Jumala käänsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Mutta monikahdat Belialin lapset sanoivat: mitä tämä auttaa meitä? ja katsoivat hänen ylön ja ei tuoneet hänelle mitään lahjaa. Mutta hän teeskenteli, niinkuin ei hän sitä kuullutkaan olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Niin Nahas Ammonilainen meni ja piiritti Jabesta Gileadissa; niin kaikki Jabeksen miehet sanoivat Nahakselle: tee liitto meidän kanssamme, niin me palvelemme sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Mutta Nahas Ammonilainen vastasi heitä: tällä tavalla teen minä liiton teidän kanssanne, että minä jokaisen teidän oikian silmänne puhkaisen, ja teen teidät häväistykseksi kaikessa Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Niin sanoivat hänelle Jabeksen vanhimmat: anna meille seitsemän päivää aikaa, että me lähettäisimme sanoman kaikille Israelin maan rajoille: ja jollei yhtäkään ole, joka meidät vapahtaa, niin me tulemme sinun tykös ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Niin tulivat sanansaattajat Saulin tykö Gibeaan ja puhuivat nämät kansan korvain kuullen; niin kaikki kansa korotti äänensä ja itki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Ja katso, Saul tuli kedolta käyden härkäinsä jälessä ja sanoi: mikä kansan on, että he itkevät? Niin he juttelivat hänelle Jabeksen miesten asian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Ja Jumalan henki tuli Saulissa voimalliseksi, kuin hän oli kuullut nämät sanat, ja hänen vihansa sangen suuresti julmistui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Niin otti hän parin härkiä ja leikkasi ne kappaleiksi, ja lähetti kaikkiin Israelin rajoihin sanansaattajain kautta ja käski sanoa: joka ei lähde Saulin ja Samuelin jälkeen, hänen härjillensä pitää näin tehtämän. Niin Herran pelko lankesi kansan päälle, että he läksivät ulos niinkuin yksi mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Ja hän luki heitä Besekissä. Ja Israelin lapsia oli kolmesataa tuhatta miestä, mutta Juudan lapsia kolmekymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Ja he sanoivat sanansaattajille, jotka tulleet olivat: sanokaat näin Jabeksen miehille Gileadissa: huomenna te saatte avun, kuin päivä on palavimmillansa. Niin sanansaattajat tulivat ja ilmoittivat sen Jabeksen miehille; ja he ihastuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Ja Jabeksen miehet sanoivat: huomenna me käymme teidän tykönne ulos, tehdäksenne meidän kanssamme, niinkuin teille kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Niin Saul jakoi toisena päivänä huomeneltain kansan kolmeen joukkoon, ja he tulivat huomenvartiossa sisälle keskelle leiriä ja löivät Ammonilaisia siihenasti kuin päivä tuli palavimmaksi; ja ne jotka jäivät, hajoitettiin, niin ettei kahta heistä yhteen jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Niin kansa sanoi Samuelille: kutka ne ovat jotka sanoivat: pitääkö Saul meitä hallitseman? Antakaat niiden tulla edes tappaaksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Niin sanoi Saul: ei tänäpänä pidä yhdenkään kuoleman, sillä tänäpänä on Herra tehnyt autuuden Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Niin sanoi Samuel kansalle: tulkaat, käykäämme Gilgaliin ja uudistakaamme siellä kuninkaan valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Niin kaikki kansa meni Gilgaliin, ja Saul tehtiin siellä kuninkaaksi Herran edessä Gilgalissa; ja he uhrasivat siellä kiitosuhria Herran edessä. Niin Saul ja kaikki Israelin miehet iloitsivat sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Ja Samuel sanoi kaikelle Israelille: katsos, minä olen kuullut teidän äänenne kaikissa mitä te minulle puhuneet olette, ja olen asettanut teille kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Ja katso, nyt kuningas käy teidän edellänne, ja minä olen vanhaksi ja harmaaksi tullut, ja minun poikani ovat teidän tykönänne; ja minä olen käynyt teidän edellänne minun nuoruudestani tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Katso, tässä minä olen; vastatkaat minua Herran ja hänen voideltunsa edessä: jos olen kenenkään härjän eli aasin ottanut, ja jos olen jollekulle ylöllistä tehnyt eli jotakuta sortanut, jos jonkun kädestä olen lahjoja ottanut ja antanut soaista silmäni: niin minä ne teille annan jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'He vastasivat: et sinä mitään ylöllistä etkä vääryyttä ole meille tehnyt, etkä myös kenenkään kädestä ole mitään ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Hän sanoi heille: Herra on todistaja teitä vastaan, ja hänen voideltunsa on todistaja tänäpänä, ettette ole mitään minun kädestäni löytäneet. He sanoivat: olkoon todistaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Ja Samuel sanoi kansalle: Herra joka Moseksen ja Aaronin teki, ja johdatti teidän isänne Egyptin maalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Niin astukaat nyt edes, oikeudelle käydäkseni teidän kanssanne Herran edessä kaikista Herran hyvistä töistä, jotka hän teille ja teidän isillenne tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Kuin Jakob oli tullut Egyptiin, huusivat teidän isänne Herran tykö, ja Herra lähetti Moseksen ja Aaronin, ja he johdattivat teidän isänne ulos Egyptistä ja asettivat heidän tähän paikkaan asumaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Mutta kuin he unohtivat Herran Jumalansa, myi hän heidät Siseran, Hasorin sodanpäämiehen vallan alle, ja Philistealaisten vallan alle ja Moabin kuninkaan vallan alle, ja he sotivat heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Ja he huusivat Herran tykö ja sanoivat: me olemme syntiä tehneet, että me hylkäsimme Herran ja palvelimme Baalia ja Astharotia; mutta vapahda nyt meitä meidän vihollistemme kädestä, niin me sinua palvelemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Ja Herra lähetti Jerubbaalin, Bedanin, Jephtan ja Samuelin, ja pelasti teitä teidän vihamiestenne käsistä ympäriltänne, ja antoi teidän asua rauhallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Kuin te näitte Nahaksen Ammonin lasten kuninkaan tulevan teitä vastaan, sanoitte te minulle: ei millään muotoa, vaan kuningas meitä vallitkoon; vaikka Herra teidän Jumalanne oli teidän kuninkaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Ja nyt katso, siinä on kuningas, jonka te olette valinneet ja anoneet; sillä katso, Herra on asettanut teille kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Jos te pelkäätte Herraa ja palvelette häntä, kuulette hänen äänensä ja ette ole Herran suulle tottelemattomat, niin sekä te että teidän kuninkaanne, joka teitä hallitsee, seuraa Herraa teidän Jumalaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mutta jollette Herran ääntä kuule, vaan olette hänen suullensa tottelemattomat, niin Herran käsi on sekä teitä että teidän isiänne vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Niin käykäät siis tästä edes ja katsokaat tätä suurta asiaa, jota Herra on tekevä teidän silmäinne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Eikö nyt ole nisun elonaika? Vaan minä huudan Herran tykö, että hän antaisi jylistä ja sataa, ymmärtääksenne ja nähdäksenne sen suuren pahuuden, jonka te olette tehneet Herran edessä, anoissanne teillenne kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Ja kuin Samuel huusi Herran tykö, antoi Herra sinä päivänä jylistä ja sataa. Niin kaikki kansa suuresti pelkäsi Herraa ja Samuelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Ja sanoivat kaikki Samuelille: rukoile sinun palveliais edestä Herraa sinun Jumalaas, ettemme kuolisi; sillä me olemme lisänneet kaikkein meidän synteimme tykö sen pahuuden, että me anoimme meillemme kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Ja Samuel sanoi kansalle: älkäät peljätkö: te tosin olette tehneet kaiken tämän pahuuden, mutta älkäät kuitenkaan luopuko Herrasta, vaan palvelkaat Herraa kaikesta teidän sydämestänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Ja älkäät itsiänne kääntäkö turhan menon perään, ei se mitään teitä hyödytä eikä auta, sillä se on turhuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Mutta Herra ei hylkää kansaansa suuren nimensä tähden; sillä Herra on tahtonut teitä tehdä itsellensä kansaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Olkoon myös kaukana minusta, että minä syntiä tekisin Herraa vastaan, lakaten rukoilemasta Herraa teidän edestänne, ja opettamasta teille hyvää ja oikiaa tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Ainoastansa peljätkäät Herraa ja palvelkaat häntä uskollisesti kaikesta sydämestänne; sillä katsokaat, kuinka suuria tekoja hän tekee teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Mutta jos te teette pahaa, niin sekä te että teidän kuninkaanne hukkuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Kuin Saul oli vuoden ollut kuninkaana, ja hallinnut Israelia kaksi ajastaikaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Valitsi hän itsellensä kolmetuhatta miestä Israelista: kaksituhatta olivat Saulin kanssa Mikmassa ja BetElin vuorella, mutta tuhannen Jonatanin kanssa BenJaminin Gibeassa, mutta muun joukon päästi hän menemään itsekunkin majoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Ja Jonatan löi Philistealaisia heidän leirissänsä, joka oli Gibeassa; ja Philistealaiset saivat sen tietää. Ja Saul antoi soittaa basunalla kaikessa maakunnassa ja sanoa: antakaat Hebrealaisten sen kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Ja kaikki Israel kuuli sanottavan: Saul on lyönyt Philistealaisten leirin; ja Israel myös haisi Philistealaisten edessä, ja kansa kutsuttiin Saulin tykö kokoon Gilgaliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Niin kokoontuivat Philistealaiset sotimaan Israelia vastaan, kolmekymmentä tuhatta vaunua, kuusituhatta ratsasmiestä ja paljo muuta kansaa, niinkuin santaa meren rannalla; ja he matkustivat ylöspäin ja asettivat leirinsä Mikmaan, itään päin BetAvenista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Kuin Israelin miehet näkivät heitänsä ahdistetuksi, sillä kansa oli sangen hämmästyksissä, lymyttivät he heitänsä luoliin, maan kuoppiin, mäen rotkoihin, linnoihin ja kaivoihin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Ja Hebrealaiset vaelsivat Jordanin ylitse Gadin ja Gileadin maakuntaan; vaan Saul oli vielä Gilgalissa, ja kaikki kansa, jotka olivat hänen perässänsä, pelkäsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Niin odotti hän seitsemän päivää, siihen aikaan asti, kun Samuel määrännyt oli. Vaan koska ei Samuel tullutkaan Gilgaliin, rupesi kansa hajoomaan häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Silloin sanoi Saul: tuokaat minulle polttouhria ja kiitosuhria; ja uhrasi polttouhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Kuin hän oli päättänyt polttouhrin, katso, Samuel tuli; niin Saul meni häntä vastaan siunaamaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Niin sanoi Samuel: mitäs olet tehnyt? Saul vastasi: minä näin kansan minultani hajoovan, et myös sinä tullut määrättyyn aikaan, ja Philistealaiset olivat Mikmassa koossa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Niin minä sanoin: nyt tulevat Philistealaiset tänne minun tyköni Gilgaliin, ja en minä rukoillut Herran kasvoin edessä; niin minä rohkaisin itseni ja uhrasin polttouhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel sanoi Saulille: sinä olet tyhmästi tehnyt, ja et pitänyt Herran sinun Jumalas käskyä, jonka hän käski sinulle; sillä hän oli vahvistanut sinun valtakuntas Israeliin ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Vaan sinun valtakuntas ei pidä enää oleman seisovainen: Herra on yhden miehen oman sydämensä jälkeen etsinyt, sen on Herra käskenyt olla kansansa päämiehen; sillä et sinä pitänyt sitä, mitä Herra sinulle käski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Niin Samuel nousi ja meni Gilgalista pois BenJaminin Gibeaan; niin Saul luki väen, joka hänen tykönänsä oli, liki kuusisataa miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Ja Saul ja Jonatan hänen poikansa, ja se väki joka heidän tykönänsä oli, jäivät BenJaminin kukkulalle; vaan Philistealaiset asettivat leirinsä Mikmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Philistealaisten leiristä läksi kolme joukkoa maata hävittämään: yksi käänsi itsensä Ophran tielle Sualin maalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'Toinen käänsi itsensä BetHoronin tielle ja kolmas käänsi itsensä sille rajatielle, joka menee Seboimin laakson korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Niin ei löydetty yhtään seppää kaikesta Israelin maakunnasta; sillä Philistealaiset ajattelivat, ettei Hebrealaiset tekisi miekkoja ja keihäitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Ja kaiken Israelin täytyi mennä Philistealaisten tykö teroittamaan vannastansa, rautalapioitansa, kirvestänsä ja vikahdintansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Mutta heillä oli teroitusrauta vikahtimille, lapioille, hangoille ja kirveille, niin myös ojettaa pistintä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Kuin tappelupäivä joutui, niin ei löytynyt miekkaa eikä keihästä kaiken kansan kädessä, jotka Saulin ja Jonatanin kanssa olivat, vaan Saulilla ja hänen pojallansa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Ja Philistealaisten leiri läksi Mikman taipaleelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Se tapahtui yhtenä päivänä, että Jonatan Saulin poika sanoi palveliallensa, joka kantoi hänen asettansa: tule, käykäämme Philistealaisten leiriin, jotka toisella puolella ovat; ja ei hän sitä sanonut isällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Vaan Saul viipyi Gibean ääressä granatin puun alla, joka oli esikaupungissa, ja se kansa, joka hänen tykönänsä oli, oli liki kuusisataa miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Ja Ahia Ahitobin poika, Ikabodin veljen, Pinehaan pojan, Elin pojan, oli Herran pappi Silossa, kantain päällisvaatetta; mutta kansa ei tietänyt Jonatanin menneeksi pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Ja tiellä, kussa Jonatan pyysi ylitse mennä Philistealaisten leiriin, oli kaksi jyrkkää kalliota, yksi tällä puolella ja toinen toisella puolella: yksi kutsuttiin Botsets, toinen Sene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Yksi oli Mikmaan päin pohjasta ja toinen etelästä Gabaan päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Ja Jonatan sanoi palvelialle, joka oli hänen aseensa kantaja: tule, käykäämme näiden ympärileikkaamattomain leiriin: taitaa tapahtua, Herra on jotakin toimittava meidän kauttamme, sillä ei ole Herralle työläs auttaa monen kautta elikkä harvain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Niin hänen aseensa kantaja vastasi häntä: tee kaikki, mitä sinun sydämessäs on: mene matkaan, katso, minä olen sinun kanssas, niinkuin sinun sydämes tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonatan sanoi: katso, me menemme niiden miesten tykö ja ilmoitamme itsemme heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Jos he näin meille sanovat: seisokaat alallanne siihen asti että me tulemme teidän tykönne, niin seisokaamme siassamme ja älkäämme menkö heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Vaan jos he näin sanovat: tulkaat tänne meidän tykömme, niin astukaamme heidän tykönsä; sillä Herra on antanut heidät meidän käsiimme: se olkoon meille merkiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Kuin Philistealaisten leiri näki heidät molemmat, sanoivat Philistealaiset: katso, Hebrealaiset ovat lähteneet luolistansa, joihin he heitänsä lymyttäneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Ja miehet leiristä vastasivat Jonatania ja hänen aseensa kantajaa ja sanoivat: tulkaat tänne ylös meidän tykömme, me kyllä opetamme teitä. Niin sanoi Jonatan aseensa kantajalle: astu ylös minun jälkeeni, Herra on antanut heidät Israelin käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Ja Jonatan kiipesi käsillänsä ja jaloillansa ylöspäin ja hänen aseensa kantaja hänen jälissänsä; ja he lankesivat maahan Jonatanin eteen ja hänen aseensa kantajan, joka löi heitä kuoliaaksi hänen jäljissänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Että ensimäinen tappelus oli, jona Jonatan ja hänen aseensa kantaja löi liki kaksikymmentä miestä, liki puolella vakomitalla peltoa, kuin juhtapari kyntäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Ja pelko tuli leiriin, kedolle ja koko kansan sekaan leirissä, ja hävittäjät myös peljätettiin, että maa vapisi siitä; sillä se hämmästys oli Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Ja Saulin vartiat BenJaminin Gibeassa saivat nähdä kansan joukot hajoovan ja pakenevan, ja toinen toistansa sysivän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Niin sanoi Saul kansalle, joka hänen kanssansa oli: lukekaat nyt ja katsokaat, kuka meistä on mennyt pois; ja kuin he lukivat, katso, niin ei ollut Jonatan ja hänen aseensa kantaja siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Ja Saul sanoi Ahialle: tuo tänne Jumalan arkki; (sillä Jumalan arkki oli siihen aikaan Israelin lasten tykönä.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Ja kuin Saul vielä puhui papin kanssa, eneni kapina ja juoksu Philistealaisten leirissä. Ja Saul sanoi papille: ota kätes pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Ja Saul kokoontui ja kaikki kansa joka hänen kanssansa oli, ja tulivat sotaan. Ja katso, silloin kävi itsekunkin miekka lähimmäistänsä vastaan, ja oli sangen suuri kapina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Ja ne Hebrealaiset, jotka ennen olivat olleet Philistealaisten tykönä ja olivat käyneet heidän kanssansa leirin ympäri, antoivat heitänsä Israelin sekaan, jotka olivat Saulin ja Jonatanin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Ja kaikki Israelin miehet, jotka heitänsä kätkeneet olivat Ephraimin vuorelle, kuin he kuulivat Philistealaisten paenneen, ajoivat he myös heitä takaa sodassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Ja niin Herra autti silloin Israelia; ja sota seisoi BetAveniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Ja kuin Israelin miehet olivat väsyneet sinä päivänä, vannotti Saul kaiken kansan, ja sanoi: kirottu olkoon jokainen, joka syö jotakin ehtooseen asti, että minä kostaisin vihollisilleni. Ja koko kansa ei syönyt mitäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Ja kaikki kansa tuli metsään, ja siellä oli hunajaa kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Kuin kansa tuli metsään, katso, silloin vuosi siellä hunajaa, mutta ei yksikään ottanut sitä kädellänsä suuhunsa; sillä kansa pelkäsi valaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Mutta Jonatan ei kuullut isänsä vannottaneeksi kansaa, hän ojensi sauvansa joka hänen kädessänsä oli, ja satutti pään hunajaläjään, ja pisti kätensä suuhunsa, niin hänen silmänsä valpauntuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Silloin vastasi yksi kansasta ja sanoi: isäs vannotti kovasti kansaa, ja sanoi: kirottu olkoon jokainen, joka jotakin syö tänäpänä. Ja kansa oli väsyksissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Ja Jonatan sanoi: minun isäni on turmellut maan: katsos, kuinka minun silmäni valpauntuivat, että minä tästä jotakin maistoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Jos kansa tänäpänä olis syönyt vihollistensa saalista, kuin he löytäneet ovat, niin olis tappelus ollut suurempi Philistealaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Ja he löivät sinä päivänä Philistealaisia Mikmasta Ajaloniin asti; ja kansa väsyi sangen kovin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Ja kansa jakoi saaliin, ja ottivat lampaita, ja karjaa, ja vasikoita, ja teurastivat maan päällä, ja söivät ne verinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Niin Saulille ilmoitettiin sanoen: katso, kansa on syntiä tehnyt Herraa vastaan ja syönyt verinensä. Hän sanoi: te olette pahasti tehneet: vierittäkäät nyt minulle tänne suuri kivi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Ja Saul sanoi: menkäät ulos kansan sekaan ja sanokaat heille: tuokaan itsekukin härkänsä ja lampaansa minun tyköni ja teurastakaan tässä, että te söisitte ja ette syntiä tekisi Herraa vastaan veren syömisellä; niin kaikki kansa toivat kukin härkänsä kädessänsä yöllä ja teurastivat ne siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Ja Saul rakensi Herralle alttarin: se on ensimäinen alttari, jonka hän rakensi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Ja Saul sanoi: käykäämme alas Philistealaisten jälkeen yöllä ja ryöstäkäämme heitä, siihenasti kuin päivä valkenee, ettemme yhtäkään heistä jättäisi. He vastasivat: tee kaikki mitä sinulle kelpaa. Ja pappi sanoi: käykäämme tänne Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Ja Saul kysyi Jumalalta ja sanoi: astunko minä Philistealaisten perään alas, ja annatkos heitä Israelin käsiin? Mutta ei hän häntä silloin vastannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Niin sanoi Saul: tulkaan väki tänne joka kulmalta, tiedustelkaat ja katselkaat, kenessä tänäpänä synti lienee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Sillä, niin totta kuin Herra Israelin auttaja elää, vaikka se olis minun pojassani Jonatanissa, niin hänen pitää totisesti kuoleman. Ja ei yksikään vastannut häntä kaikesta kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Ja hän sanoi koko Israelille: olkaat te sillä puolelle, minä ja Jonatan minun poikani olemme tällä puolella. Kansa sanoi Saulille: tee kuin sinulle kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Ja Saul sanoi Herralle Israelin Jumalalle: tee oikeus; niin se osasi Jonatanin ja Saulin, ja kansa meni vapaana ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul sanoi: heittäkäät minusta ja minun pojastani Jonatanista; niin se lankesi Jonataniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Ja Saul sanoi Jonatanille: ilmoita minulle, mitäs olet tehnyt? Jonatan ilmoitti hänelle ja sanoi: tosin minä maistoin vähän hunajaa sauvani nenällä joka minun kädessäni oli, ja katso minun pitää sentähden kuoleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Ja Saul sanoi: Jumala tehköön minulle niin ja niin! Jonatan, sinun pitää totisesti kuoleman!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Vaan kansa sanoi Saulille: pitääkö Jonatanin kuoleman, joka tämän suuren autuuden teki Israelissa? Pois se: niin totta kuin Herra elää, ei hiuskarvakaan pidä hänen päästänsä putooman: sillä Jumala on sen tehnyt tänäpänä hänen kauttansa. Ja näin kansa vapahti Jonatanin kuolemasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Niin Saul meni Philistealaisten tyköä pois; ja Philistealaiset menivät sioillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Mutta kuin Saul oli saanut Israelin valtakunnan, soti hän joka taholta kaikkia vihollisiansa vastaan, Moabilaisia, Ammonilaisia, Edomilaisia, Zoban kuninkaita ja Philistealaisia vastaan; ja kuhunka hän ikänä hänensä käänsi, siellä hän rankaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Ja hän teki urhoollisia töitä ja löi Amalekilaiset ja vapahti Israelin niiden käsistä, jotka häntä raatelivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Ja Saulilla oli poikia: Jonatan, Isvi, Malkisua, ja hänen kahden tyttärensä nimet, esikoisen nimi Merab ja nuoremman nimi Mikal,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Ja Saulin emännän nimi oli Ahinoam, Ahimatsin tytär, ja hänen sotajoukkonsa päämiehen nimi Abner, Nerin poika, Saulin sedän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Ja Kis Saulin isä, ja Ner Abnerin isä, oli Abielin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Ja suuri sota oli Philistealaisia vastaan niinkauvan kuin Saul eli. Ja kussa ikinä Saul näki jalon ja väkevän sotamiehen, otti hän sen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Mutta Samuel sanoi Saulille: Herra lähetti minun voitelemaan sinua kansansa Israelin kuninkaaksi: niin kuule siis nyt Herran sanain ääntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Näin sanoo Herra Zebaot: Minä olen ajatellut etsiskellä mitä Amalek teki Israelille, kuin hän pani hänensä tiellä häntä vastaan, Egyptistä tullessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Mene siis nyt ja lyö Amalek, ja hukuta kaikki, mitä hänellä on, ja älä säästä häntä, mutta tapa sekä vaimo että mies, lapset ja imeväiset, karja ja lampaat, kamelit ja aasit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul ilmoitti tämän kansalle, ja luki heitä Telaimissa; kaksisataa tuhatta jalkaväkeä, ja kymmenentuhatta miestä Juudasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Ja kuin Saul tuli liki Amalekilaisten kaupunkia, pani hän väijytyksen ojan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Ja antoi sanoa Keniläisille: menkäät, paetkaat ja eroittakaat itsenne Amalekilaisista, etten minä peräti hävittäisi teitä heidän kanssansa; sillä te teitte laupeuden kaikille Israelin lapsille, kuin he vaelsivat Egyptistä; ja niin luopuivat keniläiset Amalekilaisista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Niin löi Saul Amalekilaiset hamasta Hevilasta siihen asti kuin Suriin tullaan, joka on Egyptin kohdalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Ja otti Agagin Amalekilaisten kuninkaan elävänä kiinni, ja kaiken kansan surmasi hän miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Niin Saul ja kansa säästi Agagin, ja mitä parasta lampaista ja karjasta oli, lihavia karitsoita ja syöttiläitä, ja kaikki mitä hyvä oli, ei he tahtoneet hukuttaa niitä; mutta sen, mikä häijy oli ja ei kelvannut, he hukuttivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Niin tapahtui Herran sana Samuelille, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Minä kadun, että minä olen tehnyt Saulin kuninkaaksi, sillä hän on luopunut minusta ja ei täyttänyt minun sanojani; ja Samuel vihastui ja huusi Herran tykö kaiken sen yön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Ja Samuel nousi varhain huomeneltain kohtaamaan Saulia, ja Samuelille oli sanottu Saulin tulleeksi Karmeliin, ja panneeksi voiton merkin, ja vaeltaneeksi ympäri, ja tulleeksi Gilgaliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Kuin Samuel tuli Saulin tykö, sanoi Saul hänelle: siunattu ole sinä Herralta; minä olen täyttänyt Herran sanan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel vastasi: mikä siis on tämä lammasten määkynä minun korvissani ja karjan ammuminen, jonka minä kuulen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul sanoi: Amalekilaisilta ovat he ne tuoneet; sillä kansa säästi parhaita lampaista ja karjasta, Herran sinun Jumalas uhrin tähden; ne muut olemme me hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Mutta Samuel sanoi Saulille: salli, että minä sanon sinulle, mitä Herra on puhunut minun kanssani tänä yönä. Hän sanoi hänelle: puhu!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel sanoi: eikö se näin ole? Kuin sinä olit vähäinen sinun silmäis edessä, tulit sinä Israelin sukukuntain pääksi, ja Herra voiteli sinun Israelin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Ja Herra lähetti sinun matkaan ja sanoi: mene ja tapa ne syntiset Amalekilaiset ja sodi heitä vastaan, niinkauvan että hukutat heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Miksi et kuullut Herran ääntä? mutta annoit itses saaliin puoleen ja teit pahoin Herran silmäin edessä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Niin sanoi Saul Samuelille: minä olen kuitenkin kuullut Herran äänen ja olen vaeltanut sitä tietä, kuin Herra minun lähetti: minä olen tuonut tänne Agagin Amalekilaisten kuninkaan ja surmannut Amalekilaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mutta väki on ottanut saaliista, lampaita ja karjaa: ne parhaat kirotuista, uhrataksensa Gilgalissa Herralle sinun Jumalalles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Mutta Samuel sanoi: kelpaako Herralle paremmin polttouhri ja uhri, kuin että sinä kuulisit Herran äänen? Katso, kuuliaisuus on parempi kuin uhri, ja totella parempi kuin oinasten lihavuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Sillä tottelemattomuus on noituuden synti, ja vastahakoisuus on taikaus ja epäjumalan palvelus: ettäs siis olet hyljännyt Herran sanan, on hän sinun myös hyljännyt, ettei sinun silleen pidä kuningasna oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Niin sanoi Saul Samuelille: minä olen syntiä tehnyt rikkoissani Herran käskyn ja sinun sanas; sillä minä pelkäsin kansaa ja kuulin heidän äänensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Anna siis nyt minulle tämä synti anteeksi, ja palaja minun kanssani, että minä kumartaisin ja rukoilisin Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel sanoi Saulille: en minä palaja sinun kanssas; sillä sinä olet hyljännyt Herran sanan, ja Herra on myös sinun hyljännyt, niin ettei sinun pidä oleman Israelin kuninkaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Kuin Samuel käänsi itsensä menemään pois, otti hän hänen hameensa liepeestä kiinni, ja se repesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Niin sanoi Samuel hänelle: Herra on tänäpänä repinyt Israelin valtakunnan sinulta ja antanut sen lähimmäiselles, joka parempi on sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Ja Israelin sankari ei valehtele eikä kadu; sillä ei hän ole ihminen, että hän katuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Mutta hän sanoi: minä olen syntiä tehnyt. Tee siis minulle nyt kunnia minun kansani vanhimpain edessä ja Israelin edessä ja palaja minun kanssani, että minä kumartaen rukoilisin Herraa sinun Jumalaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Ja Samuel käänsi itsensä ja seurasi Saulia; ja Saul rukoili Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Ja Samuel sanoi: antakaat Agagin tulla minun tyköni, Amalekilaisten kuninkaan. Ja Agag tuli rohkiasti hänen eteensä ja sanoi: totisesti kuoleman katkeruus on paennut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Samuel sanoi: niinkuin sinun miekkas on tehnyt vaimot lapsettomaksi, niin pitää myös sinun äitis vaimoin seassa lapsetoin oleman; niin Samuel hakkasi Agagin kappeleiksi Herran edessä Gilgalissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Ja Samuel meni Ramaan, mutta Saul meni huoneeseensa Saulin Gibeaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Ja ei nähnyt Samuel enää Saulia kuolemapäivään asti; sillä Samuel murehti Saulia, että Herra oli katunut asettaneensa hänen Israelin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Ja Herra sanoi Samuelille: kuinka kauvan sinä murehdit Saulia, jonka minä hyljännyt olen hallitsemasta Israelia? Täytä sinun sarves öljyllä ja mene: minä lähetän sinun Isain Betlehemiläisen tykö, sillä hänen pojistansa olen minä katsonut minulleni kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Niin Samuel sanoi: kuinka minä sinne menen? Saul saa sen tietää ja lyö minun kuoliaaksi. Ja Herra sanoi: ota sinulles vasikka karjasta ja sano: minä tulin uhraamaan Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Ja sinun pitää kutsuman Isain uhrille, niin minä osoitan sinulle, mitä sinun pitää tekemän, ettäs sen voitelisit minulle, jonka minä sinulle sanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel teki niinkuin Herra sanonut oli ja tuli Betlehemiin; niin hämmästyivät kaupungin vanhimmat, ja menivät häntä vastaan, ja sanoivat: onko rauha, että sinä tulet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Hän sanoi: rauha. Minä tulin uhraamaan Herralle: pyhittäkäät teitänne ja tulkaat minun kanssani uhrille. Ja hän pyhitti Isain ja hänen poikansa ja kutsui heidät uhrille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Ja kuin he tulivat sisälle, katsoi hän Eliabia ja ajatteli: tosin tämä on Herran edessä hänen voideltunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Mutta Herra sanoi Samuelille: älä katso hänen muotoansa elikkä suurta kokoansa, sillä minä olen hyljännyt hänen: sillä ei se ole niinkuin ihminen näkee; sillä ihminen näkee sen mikä silmäin edessä on, mutta Herra katsoo sydämeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Niin kutsui Isai Abinadabin ja antoi hänen tulla Samuelin eteen; ja hän sanoi: ei tätäkään ole Herra valinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Niin antoi Isai Samman tulla edes; mutta hän sanoi: ei tätäkään ole Herra valinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Niin antoi Isai seitsemän poikaansa tulla Samuelin eteen; mutta Samuel sanoi Isaille: ei ole Herra näitä valinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Ja Samuel sanoi Isaille: joko nyt täällä kaikki pojat ovat? Hän sanoi: vielä nuorin jäljellä on, ja katso, hän kaitsee lampaita. Niin sanoi Samuel Isaille: lähetä hänen peräänsä ja anna noutaa tänne; sillä ei meidän pidä istuman ennen kuin hän tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Niin hän lähetti ja noudatti hänen; ja hän oli verevä ja kaunis kasvoilta ja ihanan muotoinen. Ja Herra sanoi: nouse ja voitele tämä, sillä tämä se on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Niin otti Samuel öljysarvensa ja voiteli hänen veljeinsä keskellä: ja Herran henki tuli Davidiin siitä päivästä ja sen perään; niin Samuel nousi ja meni Ramaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Ja Herran henki läksi Saulista, ja paha henki vaivasi häntä Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Niin sanoivat Saulin palveliat hänelle: katsos, paha henki vaivaa sinua Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Meidän Herramme sanokaan nyt palvelioillensa, jotka hänen edessänsä seisovat, että he etsivät miestä, joka taitais soittaa harppua: kuin paha henki tulee Jumalalta sinuun, että hän soittais kädellänsä, niin sinä paranet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Niin Saul sanoi palvelioillensa: katsokaat nyt minulle joku mies, joka taitais hyvin soittaa, ja noutakaat häntä minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Niin vastasi yksi hänen palvelioistansa ja sanoi: katso, minä näin Isain Betlehemiläisen pojan, hän taitaa soittaa, ja on urhollinen sotamies, ja toimellinen asioissa, ja ihana mies, ja Herra on hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Niin Saul lähetti sanansaattajat Isaille, sanoen: lähetä minun tyköni sinun poikas David, joka on lampuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Niin otti Isai aasin leipäin kanssa, ja leilin viinaa, ja yhden vohlan vuohista, ja lähetti Saulille poikansa Davidin myötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Niin David tuli Saulin tykö ja seisoi hänen edessänsä; ja hän tuli hänelle juuri rakkaaksi, ja tuli hänen aseensa kantajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Ja Saul lähetti Isain tykö, sanoen: anna Davidin olla minun tykönäni, sillä hän on löytänyt armon minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Kuin Jumalan henki tuli Saulin päälle, otti David kanteleen ja soitti kädellänsä; niin Saul virvoitettiin ja tuli paremmaksi, ja paha henki läksi hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Niin Philistealaiset kokosivat sotaväkensä sotaan, ja tulivat kokoon Sokoon, joka on Juudassa, ja asettivat leirinsä Sokon ja Asekan välille Dammimin rajalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Mutta Saul ja Israelin miehet menivät kokoon, ja asettivat leirinsä Tammilaaksoon, ja valmistivat itsensä sotimaan Philistealaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Ja Philistealaiset seisoivat vuorella siellä, ja Israelilaiset seisoivat vuorella täällä, että laakso oli heidän välillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Niin tuli Philistealaisten leiristä yksi mies heidän keskellensä, Goljat nimeltä, Gatista, kuusi kyynärää ja kämmenen leveyden pitkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Ja hänellä oli vaskilakki päässänsä ja suomuksen kaltainen pantsari yllänsä, ja hänen pantsarinsa painoi viisituhatta sikliä vaskea,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Ja vaskiset saappaat jaloissansa ja vaskikilpi hartioillansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Ja hänen keihäänsä varsi oli niinkuin kankaan orsi, ja hänen keihäänsä rauta painoi kuusisataa sikliä rautaa. Ja hänen kilpensä kantaja kävi hänen edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Ja hän seisoi ja huusi Israelin joukolle, ja sanoi heille: miksi te läksitte valmistamaan teitänne sotaan; enkö minä ole Philistealainen, ja te olette Saulin palveliat? valitkaat yksi teistänne, joka tulee tänne alas minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Jos hän voi sotia minua vastaan ja lyö minun, niin me olemme teidän palvelianne, mutta jos minä hänen voitan ja lyön hänen, niin teidän pitää oleman meidän palveliamme ja teidän pitää meitä palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Ja Philistealainen sanoi: minä häpäisin tänäpänä Israelin sotajoukon; antakaat minulle mies, me sodimme keskenämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Kuin Saul ja koko Israel kuuli nämät Philistealaisten puheet, hämmästyivät he, ja pelkäsivät suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Mutta David oli Ephratin miehen poika Juudan Betlehemistä, joka kutsuttiin Isai, hänellä oli kahdeksan poikaa, ja oli vanha mies Saulin aikaan ja ijällinen miesten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Ja kolme Isain vanhimpaa poikaa olivat lähteneet Saulin kanssa sotaan; hänen kolmen poikansa nimet, jotka olivat menneet sotaan olivat Eliab esikoinen, ja toinen Abinadab ja kolmas, Samma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Ja David oli nuorin; vaan ne kolme vanhinta menivät Saulin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Mutta David meni kotiansa jälleen Saulin tyköä, kaitsemaan isänsä lampaita Betlehemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Ja Philistealainen tuli varhain aamulla ja ehtoona, ja sitä tekoa hän teki neljäkymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Ja Isai sanoi pojallensa Davidille: ota veljilles tämä epha kuivatuita tähkäpäitä ja nämät kymmenen leipää, ja vie ne leiriin veljeis tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Ja kanna nämät kymmenen tuoretta juustoa päämiehelle; ja etsi veljiäs, jos he rauhassa ovat, ja pane mielees, mitä he sinulle käskevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Mutta Saul ja he kaikki Israelin miehet olivat Tammilaaksossa ja sotivat Philistealaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Niin David nousi varhain aamulla ja jätti lampaat paimenen haltuun, kantoi ja meni matkaansa, niinkuin Isai häntä käskenyt oli, ja tuli leiriin, ja sotaväki oli lähtenyt ulos sotaan, ja huusivat suurella äänellä sotimaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Sillä Israel ja Philistealaiset olivat valmistaneet itsensä sotimaan toinen toistansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Niin David jätti kalut, jotka hän kantoi, kalunvartijalle, ja juoksi sodan rintaan, ja tuli ja tervehti veljiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Kuin hän parhaallansa heitä puhutteli, katso, se välimies, hänen nimensä oli Goljat, Philistealainen Gatista, nousi Philistealaisten sotajoukosta, ja puhui niinkuin ennenkin; ja David kuuli sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Ja kutka ikänä Israelin miehistä näkivät hänen, pakenivat he hänen edestänsä ja pelkäsivät suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Ja kaikki Israelin miehet sanoivat: ettekö te nähneet sitä miestä, joka on tullut? Hän on tullut pilkkaamaan Israelia. Ja pitää tapahtuman, että joka sen miehen lyö, sen kuningas tekee aivan rikkaaksi, ja antaa myös tyttärensä hänelle, ja tekee hänen isänsä huoneen vapaaksi Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Niin David sanoi miehille, jotka hänen tykönänsä seisoivat: mitä annetaan sille miehelle, joka tämän Philistealaisen lyö ja ottaa häväistyksen pois Israelista? sillä mikä tämä ympärileikkaamatoin Philistealainen on, joka häpäisee elävän Jumalan sotajoukkoa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Niin kansa sanoi hänelle niinkuin ennenkin: niin sille miehelle tehdään, joka hänen lyö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Kuin hänen vanhin veljensä Eliab kuuli hänen näitä puhuvan miesten kanssa, närkästyi hän suuresti Davidin päälle ja sanoi: miksi sinä olet tänne tullut? ja miksis olet jättänyt vähän lammaslauman metsän korpeen? Minä tiedän sinun ylpeytes ja sydämes pahan sisun; sinä olet tänne tullut sotaa katsomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Niin David sanoi: mitä minä olen tehnyt? eikö se ole minulle käsketty?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Ja käänsi itsensä hänestä pois toisen puoleen ja sanoi niinkuin hän ennenkin oli sanonut; niin kansa vastasi häntä niinkuin ennenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Ja kuin he kuulivat Davidin puhuvan ne sanat, ilmoittivat he ne Saulille, ja hän noudatti hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Ja David sanoi Saulille: älköön kenenkään sydän hämmästykö hänen tähtensä: palveliais käy sotimaan Philistealaista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul sanoi Davidille: et sinä voi mennä ja sotia tätä Philistealaista vastaan; sillä sinä olet nuorukainen, vaan hän on sotamies hamasta nuoruudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Mutta David sanoi Saulille: palvelias kaitsi isänsä lampaita, ja tuli jalopeura ja karhu ja vei lampaan laumasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Niin minä juoksin sen perästä ja löin sen ja tempasin sen ulos hänen suustansa. Ja kuin hän karkasi minua vastaan, niin minä tartuin hänen partaansa, löin hänen ja tapoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Niin on sinun palvelias sekä jalopeuran että karhun lyönyt; niin pitää tämän ympärileikkaamattoman Philistealaisen oleman, kuin yksi niistä, sillä hän on pilkannut elävän Jumalan sotaväkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Ja David sanoi: Herra, joka minun pelasti jalopeuran ja karhun käsistä, hän pelastaa minun tämän Philistealaisen käsistä. Ja Saul sanoi Davidille: mene, Herra olkoon sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Niin Saul puetti vaatteensa Davidin ylle ja pani vaskilakin hänen päähänsä ja pantsarin hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Ja David sitoi miekan vyöllensä vaatettensa päälle ja rupesi käymään; vaan ei hän ollut siihen tottunut. Sanoi siis David Saulille: en minä näillä taida käydä, sillä en minä ole tottunut. Ja David pani ne pois yltänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Ja otti sauvansa käteensä, ja valitsi ojasta viisi sileää kiveä, pani ne paimenen kukkaroon ja säkkiin, joka hänellä oli, ja linko hänen kädessänsä, ja kävi Philistealaista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Käveli myös Philistealainen ja lähestyi Davidia, ja hänen kilpensä kantaja hänen edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Kuin Philistealainen katsoi ja näki Davidin, katsoi hän hänen ylön; sillä hän oli verevä ja kaunis nuorukainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Philistealainen sanoi Davidille: olenko minä koira, ettäs tulet sauvoilla minun tyköni? Ja Philistealainen kiroili Davidia jumalainsa kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Ja Philistealainen sanoi Davidille: tule tänne minun tyköni, minä annan lihas taivaan linnuille ja kedon pedoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Niin David sanoi Philistealaiselle: sinä tulet minun tyköni miekalla, keihäällä ja kilvellä, mutta minä tulen sinun tykös Herran Zebaotin, Israelin sotaväen Jumalan nimeen, jota sinä pilkannut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Tänäpänä antaa Herra sinun minun käsiini, että minä lyön sinun, ja otan sinun pääs sinulta pois, ja annan Philistealaisten sotaväen ruumiit tänäpänä taivaan linnuille ja kedon pedoille: että kaikkein maan asuvaisten pitää tietämän Israelilla olevan Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Ja koko tämän joukon pitää ymmärtämän, ettei Herra auta miekan eli keihään kautta; sillä sota on Herran, ja hän antaa teidät meidän käsiimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Kuin Philistealainen nousi ja kävi ja lähestyi Davidia, niin David riensi ja juoksi sotajoukon eteen Philistealaista vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Ja pisti kätensä kukkaroon, otti sieltä kiven, ja linkosi ja paiskasi Philistealaista otsaan, että kivi meni hänen otsansa sisälle, ja hän lankesi maahan kasvoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Niin David voitti Philistealaisen lingolla ja kivellä, löi Philistealaisen ja tappoi hänen. Ja ettei Davidilla ollut miekkaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Juoksi hän ja seisahti Philistealaisen tykö, ja otti hänen miekkansa ja veti tupesta ulos, ja tappoi hänen, ja sillä hakkasi pois hänen päänsä. Kuin Philistealaiset sen näkivät, että heidän väkevimpänsä kuollut oli, niin he pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Ja Israelin ja Juudan miehet nousivat, huusivat ja ajoivat Philistealaisia takaa laaksoon ja Ekronin porttiin asti; ja Philistealaiset lankesivat lyötynä Saarimin tiellä, Gatiin ja Ekroniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Ja Israelin lapset palasivat ajamasta Philistealaisia takaa ja ryöstivät heidän leirinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Mutta David otti Philistealaisen pään ja vei Jerusalemiin: vaan hänen aseensa pani hän majaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Mutta kuin Saul näki Davidin menevän Philistealaista vastaan, sanoi hän Abnerille, sodan päämiehelle: Abner, kenen poika tuo nuorukainen on? Abner sanoi: niin totta kuin sinun sielus elää, kuningas, en minä tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Kuningas sanoi: kysy siis, kenenkä poika se nuorukainen on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Kuin David palasi Philistealaista lyömästä, otti Abner hänen ja vei Saulin eteen; ja hänen kädessänsä oli Philistealaisen pää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Ja Saul sanoi hänelle: kenenkäs poika olet, nuorukainen? David sanoi: palvelias Isain Betlehemiläisen poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Ja kuin hän oli puheensa lopettanut Saulin kanssa, mieltyi Jonatan ja David keskenänsä sydämestä; ja Jonatan rakasti häntä niinkuin omaa sydäntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Ja Saul otti hänen sinä päivänä eikä sallinut hänen enää palata isänsä huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Ja Jonatan ja David tekivät liiton keskenänsä; sillä hän rakasti häntä niinkuin omaa sydäntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Ja Jonatan riisui hameensa, jolla hän oli puetettu ja antoi sen Davidille, niin myös vaatteensa, miekkansa, joutsensa ja vyönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Ja David meni, kuhunka Saul lähetti hänen, ja käytti itsensä toimellisesti; ja Saul asetti hänen sotamiestensä päälle, ja hän oli otollinen kaikelle kansalle, niin myös Saulin palvelioille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Mutta tapahtui, kuin he tulivat ja David palasi lyömästä Philistealaista, että vaimot kaikista Israelin kaupungeista kävivät virsillä ja hypyillä kuningas Saulia vastaan, harpuilla, ilolla ja kanteleilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Ja vaimot lauloivat keskenänsä, soittaen ja sanoen: Saul löi tuhannen, mutta David kymmenentuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Niin Saul närkästyi sangen suuresti, ja se puhe ei hänelle kelvannut, ja sanoi: he ovat antaneet Davidille kymmenentuhatta ja minulle he antoivat tuhannen: vielä hän kuninkaankin valtakunnan saa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Ja Saul katsoi julmasti Davidin päälle siitä päivästä ja aina sitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Toisena päivänä vaivasi taas Jumalan paha henki Saulia, ja hän ennusti kotona huoneessansa. Ja David soitti kädellänsä, niinkuin hänen jokapäiväinen tapansa oli; ja Saulin kädessä oli keihäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Jonka hän syöksi, ajatellen: minä syöksen Davidin seinää vastaan; mutta David vältti hänen edestänsä kaksi kertaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Ja Saul pelkäsi Davidia; sillä Herra oli hänen kanssansa ja oli mennyt pois Saulin tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Niin pani Saul hänen pois tyköänsä ja teki hänen tuhannen miehen päämieheksi; ja hän kävi ulos ja sisälle kansan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Ja David oli toimellinen kaikissa teissänsä, ja Herra oli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Kuin Saul näki hänen aivan toimellisesti tekevän, pelkäsi hän häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Mutta koko Israel ja Juuda rakasti Davidia; sillä hän kävi ulos ja sisälle heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Ja Saul sanoi Davidille: katso, minä annan vanhimman tyttäreni Merabin sinulle emännäksi, ainoasti ole minulle miehullinen ja sodi Herran sotaa; sillä Saul ajatteli: ei pidä minun käteni häneen sattuman, vaan Philistealaisten käsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Mutta David vastasi Saulia: mikä minä olen? eli mikä on elämäni ja minun isäni sukukunta Israelissa, että minä tulisin kuninkaan vävyksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Ja tapahtui, kuin aika tuli, että Merab Saulin tytär piti annettaman Davidille, annettiin se Adrielille Meholatilaiselle emännäksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Mutta Mikal Saulin tytär rakasti Davidia. Kuin se Saulille ilmoitettiin, niin se kelpasi hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Ja Saul sanoi: minä annan hänen hänelle, että hän olis hänelle paulaksi, ja Philistealaisten kädet tulisivat hänen päällensä. Ja Saul sanoi Davidille: sinä tulet tänäpänä toisen kanssa minun vävykseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Ja Saul käski palvelioillensa: puhukaat Davidille salaisesti ja sanokaat: katso, kuningas mielistyy sinuun, ja kaikki hänen palveliansa rakastavat sinua; niin tule nyt kuninkaan vävyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Ja Saulin palveliat puhuivat ne sanat Davidin korvissa; mutta David sanoi: luuletteko te sen vähäksi, tulla kuninkaan vävyksi? Ja minä olen köyhä ja halpa mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Ja Saulin palveliat ilmoittivat sen hänelle, sanoen; nämät sanat on David puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Saul sanoi: sanokaat näin Davidille: ei kuningas ano yhtään muuta huomenlahjaa, vaan sata Philistealaisten esinahkaa, että kuninkaan vihamiehille kostettaisiin; sillä Saul ajatteli hukuttaa Davidia Philistealaisten kätten kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Niin hänen palveliansa sanoivat Davidille nämät sanat, ja se kelpasi hänelle, tulla niin kuninkaan vävyksi. Ja se aika ei ollut vielä täytetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Ja David nousi ja läksi matkaan, hän ja hänen miehensä, ja löi Philistealaisista kaksisataa miestä, ja David toi heidän esinahkansa ja täytti kuninkaan luvun, että hän olis kuninkaan vävy. Niin antoi Saul tyttärensä Mikalin hänelle emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Ja Saul näki ja ymmärsi Herran olevan Davidin kanssa, ja Saulin tytär Mikal rakasti häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Niin Saul vielä enemmin pelkäsi Davidia, ja Saul tuli Davidin vihamieheksi kaikkena elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Ja Philistealaisten ruhtinaat läksivät ulos, ja heidän lähteissänsä ulos teki David toimellisemmasti kuin kaikki Saulin palveliat, että hänen nimensä tuli sangen kuuluisaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Ja Saul puhui pojallensa Jonatanille ja kaikille palvelioillensa, että he tappaisivat Davidin; mutta Jonatan Saulin poika rakasti suuresti Davidia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Ja Jonatan ilmoitti Davidille ja sanoi: minun isäni Saul pyytää sinua tappaa: varjele siis itses huomenna, mene lymyyn ja kätke itses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Ja minä menen ulos isäni kanssa ja seison hänen ohessansa kedolla, jossa sinä olet, ja minä puhun sinusta isäni kanssa: ja mitä minä näen, ne minä ilmoitan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Ja Jonatan puhui parhain päin Davidista isällensä Saulille ja sanoi hänelle: älköön kuningas syntiä tehkö palveliaansa Davidia vastaan; sillä ei hän ole mitään rikkonut sinua vastaan, hänen työnsä ovat sinulle juuri tarpeelliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Ja hän on pannut henkensä käteensä ja löi Philistealaisen; ja Herra teki suuren autuuden koko Israelille, sen sinä näit ja ihastuit: miksis siis tahdot syntiä tehdä viatointa verta vastaan, surmatakses Davidia ilman syytä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Niin Saul kuuli Jonatanin äänen ja vannoi: niin totta kuin Herra elää, ei hänen pidä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Niin Jonatan kutsui Davidin ja sanoi hänelle kaikki nämät sanat ja saatti hänen Saulin eteen, ja hän oli hänen edessänsä niinkuin ennenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Niin nousi taas sota, ja David meni ja soti Philistealaisia vastaan, löi heitä suurella surmalla; ja Philistealaiset pakenivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Ja paha henki tuli Herralta Saulin päälle, ja hän istui huoneessansa, ja hänen keihäänsä oli hänen kädessänsä, ja David soitti kädellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Mutta Saul pyysi pistää Davidia keihäällä seinää vasten, mutta hän vältti Saulia ja keihäs kävi seinään; ja David pakeni ja pääsi sinä yönä pakoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Ja Saul lähetti sanansaattajat Davidin huoneesen, että heidän piti ottaman hänestä vaarin ja tappaman hänen huomeneltain. Mutta Mikal Davidin emäntä ilmoitti sen hänelle ja sanoi: jollet tänä yönä pelasta henkeäs, niin sinä huomenna tapetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Niin Mikal laski Davidin alas akkunan lävitse; ja hän meni, pakeni ja pääsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Ja Mikal otti kuvan ja pani vuoteesen, ja pani vuohen nahan hänelle päänalaiseksi ja peitti vaatteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Silloin lähetti Saul sanansaattajat ottamaan kiinni Davidia; mutta hän sanoi: hän on sairas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Niin lähetti Saul sanansaattajat katsomaan Davidia ja sanoi: kantakaat häntä tänne minun tyköni vuoteinensa, surmattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Kuin sanansaattajat tulivat, katso, kuva makasi vuoteessa ja vuohen nahka pään alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Niin Saul sanoi Mikalille: miksis olet minun niin pettänyt ja päästänyt viholliseni, että hän vältti minun käteni? Mikal sanoi Saulille: hän sanoi minulle: päästä minua taikka minä tapan sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Ja David pakeni ja pääsi, ja tuli Samuelin tykö, joka oli Ramassa, ja ilmoitti hänelle kaikki, mitä Saul oli hänelle tehnyt; ja hän meni Samuelin kanssa ja oleskeli Najotissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Ja se ilmoitettiin Saulille, sanoen: katso, David on Raman Najotissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Niin Saul lähetti sanansaattajat tuomaan Davidia; ja he näkivät prophetain kokouksen propheteeraavan ja Samuelin seisovan, asetetun heidän päällensä. Niin Jumalan henki tuli Saulin sanansaattajain päälle, että ne myös propheteerasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Kuin se ilmoitettiin Saulille, lähetti hän toiset sanansaattajat, ne myös propheteerasivat; ja hän lähetti vielä kolmannet sanansaattajat, jotka myös propheteerasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Niin meni hän itse viimein Ramaan, ja kuin hän tuli sen suuren kaivon tykö, joka on Sekossa, kysyi hän ja sanoi: kussa on Samuel ja David? niin sanottiin hänelle: katso, he ovat Raman Najotissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Ja hän meni Raman Najotiin; ja Jumalan henki tuli hänenkin päällensä, ja hän käyskenteli ja propheteerasi siihenasti kuin hän tuli Raman Najotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Niin hänkin riisui vaatteensa ja propheteerasi Samuelin edessä, ja lankesi alasti maahan koko sen päivän ja koko yön, sentähden sanotaan: onko Saulkin prophetain seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Ja David pakeni Raman Najotista, tuli ja sanoi Jonatanille: mitä minä olen tehnyt? mikä on vääryyteni? eli mikä on pahatekoni sinun isääs vastaan, että hän seisoo minun henkeni perään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Hän sanoi hänelle: pois se, ei sinun pidä kuoleman: katso, isäni ei tee suurta eli pientä, jota ei hän ilmoita minulle, kuinkas isäni salaa tämän minulta? Ei se pidä niin tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Niin David vannoi vielä, sanoen: totisesti sinun isäs tietää, että minä olen löytänyt armon sinun kasvois edessä, sentähden hän ajattelee: ei Jonatanin pidä tästä mitään tietämään, ettei hän tulisi murheelliseksi. Totisesti, niin totta kuin Herra ja sinun sielus elää, että askele on vaivoin minun ja kuoleman vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jonatan sanoi Davidille: minä teen sinulle kaikki, mitä sinun sydämes halajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'David sanoi hänelle: katso, huomenna on uusikuu, ja minun pitäis istuman ja atrioitseman kuninkaan kanssa: salli siis, että minä kätken minuni kedolle kolmannen päivän ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Jos isäs minua kovasti kaipaa, niin sano: David rukoili suuresti minulta juostaksensa kaupunkiinsa Betlehemiin; sillä siellä pidetään ajastaikainen uhri koko sukukunnalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Ja jos hän sanoo: se on hyvin, niin on rauha palveliallas; mutta jos hän kovin vihastuu, niin sinä ymmärrät hänen pahaa aikovan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Tee siis laupius palvelialles; sillä sinä olet ottanut palvelias Herran liittoon sinun kanssas. Ja jos joku vääryys minussa on, niin tapa sinä minua: miksis sallit minun tulla isäs eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Jonatan sanoi: pois se sinusta, sillä jos minä ymmärtäisin isäni aikovan sinulle pahaa tehdä, tullaksensa sinun päälles, enkö minä näitä sinulle ilmoittaisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'David sanoi Jonatanille: kuka minulle ilmoittaa, jos sinun isäs vastaa sinua jotakin kovasti?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonatan sanoi Davidille: tule, käykäämme kedolle; ja he menivät molemmat kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Ja Jonatan sanoi Davidille: Herra, Israelin Jumala! kuin minä kyselen isältäni huomenna ja kolmantena päivänä, katso, jos hän suo Davidille hyvää, ja en minä silloin lähetä sinun tykös, ja ilmoita sitä sinun korviis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Niin tehköön Herra sitä ja sitä Jonatanille; mutta jos isäni taas ajattelee jotakin pahaa sinua vastaan, niin minä sen myös ilmoitan sinun korviis, ja lasken sinun rauhaan menemään: ja Herra olkoon sinun kanssas, niinkuin hän isäni kanssa ollut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Etkös sinäkin, jos vielä elän: etkös sinäkin ole tekevä Herran armoa minua kohtaani, niin ettei minun pidä kuoleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Ja et sinä ota laupiuttas minun huoneestani pois ijankaikkisesti, et vielä sittenkään, kuin Herra hävittää Davidin vihamiehet, itsekunkin maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Näin teki Jonatan liiton Davidin huoneen kanssa, että Herra sen vaatisi Davidin vihamiesten kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Ja Jonatan taas vannoi Davidille; sillä niin rakkaana piti hän hänen, että hän rakasti häntä niinkuin omaa sieluansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Ja Jonatan sanoi hänelle: huomenna on uusikuu, jona sinua kysytään ja kaivataan sinua sialtas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Ja kuin olet viipynyt kolme päivää poissa, niin tule kiiruusti alas ja mene siihen paikkaan, johon sinä itses kätkit sinä päivänä kuin tämä asia tapahtui, ja istu Aselin kiven viereen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Niin minä ammun kolme nuolta sen sivulle, niinkuin minä ampuisin maaliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Ja katso, minä lähetän pojan (sanoen hänelle:) mene ja hae nuolet jällensä! jos vielä sanon pojalle: katso, nuolet ovat takanas tässä puolessa, ota ylös! niin tule; sillä rauha on sinulla ja ei ole mitään hätää, niin totta kuin Herra elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Mutta jos sanon pojalle: katso, nuolet ovat edempänä edessäs! niin mene pois, sillä Herra on päästänyt sinun menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Ja mitä sinä ja mitä minä keskenämme puhuneet olemme, katso, Herra on minun ja sinun vaiheellas ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Niin David kätki itsensä kedolle. Ja kuin uusikuu tuli, istui kuningas pöydän tykö rualle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Kuin kuningas oli istunut siallensa, entisen tapansa jälkeen, seinän nojalle, nousi Jonatan, ja Abner istui Saulin viereen; ja Davidia kaivattiin siastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Ja ei puhunut Saul sinä päivänä mitäkään; sillä hän ajatteli: hänelle on jotakin tapahtunut, ettei hän ole puhdas; ei suinkaan hän ole puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Ja toisena päivänä uudesta kuusta, kuin Davidia kaivattiin siastansa, sanoi Saul pojallensa Jonatanille: Miksi ei Isain poika ole tullut pöydän tykö, ei eilen eikä myöskään tänäpänä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Jonatan vastasi Saulia: hän rukoili hartaasti minulta mennäkseen Betlehemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Ja sanoi: anna minun mennä, sillä meidän sukukuntamme uhraa kaupungissa ja minun veljeni itse on minua kutsunut: jos nyt olen löytänyt armon sinun silmäis edessä, niin salli minun mennä katsomaan veljiäni; ja sen tähden ei hän tullut kuninkaan pöydän tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Ja Saul vihastui sangen suuresti Jonatanin päälle ja sanoi hänelle: sinä ilkiä ja tottelematoin poika! enkö minä tiedä, ettäs olet valinnut Isain pojan sinulles ja äidilles häpiäksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Sillä niinkauvan kuin Isain poika elää maan päällä, et sinä eikä sinun kuninkaan valtakuntas ole seisova: lähetä siis nyt ja anna tuotaa häntä minun tyköni, sillä hänen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonatan vastasi isällensä Saulille ja sanoi hänelle: miksi hänen pitää kuoleman? mitä hän on tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Silloin paiskasi Saul keihään hänen perässänsä syöstäksensä häntä; niin ymmärsi Jonatan isänsä aikovan Davidin tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Ja Jonatan nousi pöydän tyköä sangen vihoissansa ja ei syönyt sinä toisena päivänä uudesta kuusta mitään leipää; sillä hän murehti Davidia, että hänen isänsä oli hänen niin häväissyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Ja Jonatan läksi aamulla kedolle, siihen aikaan kuin hän oli määrännyt Davidille, ja vähä poikainen hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Ja hän sanoi pojalle: juokse noutamaan nuoleni, jotka minä ammun: pojan juostessa laski hän nuolen hänen ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Ja kuin poika tuli sille paikalle, johon Jonatan nuolen ampunut oli, huusi Jonatan hänen perässänsä ja sanoi: eikö nuoli ole edemmä sinusta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Ja huusi taas poikaa: joudu, kiiruhda sinuas nopiammin ja älä seisahtele. Niin Jonatanin poika otti nuolet otti nuolet ja kantoi herrallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Eikä poika tietänyt asiasta mitään; vaan Jonatan ja David ainoastaan asian tiesivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Niin Jonatan antoi aseensa pojalle, joka hänen kanssansa oli, ja sanoi: mene ja vie kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Ja kuin poika oli mennyt, nousi David siastansa meren puolelta ja lankesi maahan kasvoillensa ja rukoili kolme kertaa; ja he antoivat toinen toisellensa suuta ja itkivät toinen toisensa kanssa; vaan David itki hartaammin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Ja Jonatan sanoi Davidille: mene rauhaan, (ja muista) mitä me olemme vannoneet yhteen Herran nimeen ja sanoneet: Herra olkoon sinun ja minun vaiheellani, minun ja sinun siemenes vaiheella ijankaikkisesti! Ja hän nousi ja meni matkaansa; mutta Jonatan palasi kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Ja David tuli Nobeen papin Ahimelekin tykö, ja Ahimelek hämmästyi, kuin hän tuli Davidia vastaan, ja sanoi hänelle: kuinka sinä yksinäs olet, ja ei yhtään miestä ole sinun kanssas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David sanoi papille Ahimelekille: kuningas on minun käskenyt asialle ja sanoi minulle: älä kenellekään ilmoita, minkätähden minä olen sinun lähettänyt ja mitä minä olen käskenyt sinulle; minä olen myös lähettänyt palveliani sinne ja sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Jos nyt on jotakin sinun kätes alla, anna minulle viisikin leipää, taikka mitäs löydät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Pappi vastasi Davidia ja sanoi: ei ole ensinkään yhteisiä leipiä minun käteni alla, paitsi pyhää leipää, jos vaan muutoin palveliat ovat pitäneet heitänsä vaimoista pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'David vastasi pappia ja sanoi hänelle: vaimot ovat kolme päivää olleet eroitetut meistä, kuin minä läksin, ja palveliaini astiat olivat pyhät; mutta jos tämä tie on saastainen, niin se pitää tänäpänä pyhitettämän astiain kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Niin antoi pappi hänelle pyhää; sillä ei siellä ollut muuta leipää kuin näkyleipiä, jotka olivat korjatut Herran kasvoin edestä, että sinne pantaisiin toiset vastauutiset leivät sinä päivänä, jona ne korjattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Mutta sinne on sinä päivänä yksi mies Saulin palvelioista jäänyt Herran eteen, Doeg nimeltä Edomilainen, kaikkein voimallisin Saulin paimenista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Ja David sanoi Ahimelekille: eikö täällä ole sinun kätes alla yhtäkään keihästä eli miekkaa? En ottanut minä myötäni miekkaani taikka asettani käteeni, sillä kuninkaan asia kiiruhti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Mutta pappi vastasi: Philistealaisen Goljatin miekka, jonkas löit Tammilaaksossa, on täällä kääritty yhteen hameesen päällisvaatteen taa: jos tahdot sitä, niin ota; sillä ei täällä ole yhtään muuta, paitsi sitä. David sanoi: ei ole sen vertaa, anna se minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Ja David nousi ja pakeni sinä päivänä Saulin kasvoin edestä, ja tuli Akiksen Gatin kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Ja Akiksen palveliat sanoivat hänelle: eikö tämä ole David, maan kuningas? eikö he tästä veisanneet hypyssä, sanoen: Saul löi tuhannen, ja David kymmenentuhatta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Ja David pani ne sanat sydämeensä ja pelkäsi suuresti Gatin kuningasta Akista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Ja muutteli menojansa heidän edessänsä ja hullutteli heidän käsissänsä, ja piirusteli portin ovissa, ja valutti sylkeänsä parrallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Silloin sanoi Akis palvelioillensa: katso, te näette tämän miehen olevan mielipuolen, miksi te toitte hänen minun tyköni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Puuttuneeko minulta mielipuolia, että te tämän toitte hulluttelemaan minun eteeni? pitääkö hänen tuleman minun huoneeseni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Ja David läksi sieltä ja pakeni Adullamin luolaan; kuin hänen veljensä ja kaikki isänsä huone sen kuulivat, tulivat he myös sinne hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Ja kaikkinaiset miehet, jotka olivat vaivassa, ja jokainen, joka velassa oli, ja jokainen, jolla murheellinen sydän oli, kokosivat itsensä hänen tykönsä, ja hän oli heidän päämiehensä: että liki neljäsataa miestä oli hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Ja David meni sieltä Mitspaan Moabilaisten maakuntaan ja sanoi Moabilaisten kuninkaalle: anna isäni ja äitini käydä ulos ja sisälle teidän tykönänne, siihenasti että minä saan tietää, mitä Jumala tekee minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Ja hän johdatti heidät Moabilaisten kuninkaan eteen; ja he viipyivät hänen tykönänsä aina niinkauvan kuin David oli linnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Niin sanoi propheta Gad Davidille: älä ole siinä linnassa, mutta mene ja kulje Juudan maalle. Niin David meni ja tuli Haretin metsään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Ja Saul kuuli, että David ja ne miehet, jotka hänen tykönänsä olivat, tulivat tiettäväksi. Ja Saul asui Gibeassa metsistössä Ramassa, ja hänen keihäänsä oli hänen kädessänsä, ja kaikki hänen palveliansa seisoivat hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Niin sanoi Saul palvelioillensa, jotka seisoivat hänen tykönänsä: kuulkaat, te Jeminin lapset! antaako Isain poika teille kaikille pellot ja viinamäet, ja tekeekö hän teitä kaikkia tuhanten ja satain päämiehiksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Että te kaikki teitte liiton minua vastaan, ja ei ole yhtään, joka ilmoitti sen minun korvilleni että minun poikani on myös tehnyt liiton Isain pojan kanssa ja ei ole yhtäkään teistä, joka sitä panee pahaksensa minun tähteni, ja ei myös ilmoita sitä minun korvaini kuullen, että minun poikani on yllyttänyt palveliani minua vastaan, väijymään minua, niinkuin tänäpänä on nähtävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Niin vastasi Doeg Edomilainen, joka seisoi Saulin palveliain tykönä, ja sanoi: minä näin Isain pojan tulevan Nobeen, Ahimelekin Akitobin pojan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Hän kysyi Herralta neuvoa hänen tähtensä ja evästi hänen, ja antoi hänelle Philistealaisen Goljatin miekan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Niin kuningas lähetti kutsumaan pappia Ahimelekia Akitobin poikaa ja kaikkea hänen isänsä huonetta, pappeja, jotka olivat Nobessa; ja he tulivat kaikki kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Ja Saul sanoi: kuule sinä Akitobin poika. Hän sanoi: tässä minä olen, herrani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Ja Saul sanoi hänelle: miksi te teitte liiton minua vastaan, sinä ja Isain poika, ettäs annoit hänelle leipää ja miekan ja kysyit Herralta neuvoa hänen tähtensä, yllyttääkses häntä minua väijymään, niinkuin tänäpänä on nähtävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelek vastasi kuningasta ja sanoi: kuka on kaikkein sinun palveliais seassa niinkuin David? Hän on uskollinen ja kuninkaan vävy, vaeltaa kuuliaisuudessas ja on kunniallinen sinun huoneessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Olenko minä vasta tänäpänä ruvennut kysymään Jumalalta neuvoa hänen tähtensä? Pois se minusta, älkään kuningas luulko senkaltaista palveliastansa ja kaikesta minun isäni huoneesta: sillä sinun palvelias ei tietänyt mitään kaikista näistä, pienistä eli suuresta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Kuningas sanoi: Ahimelek, sinun pitää totisesti kuoleman, sinun ja koko sinun isäs huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Ja kuningas sanoi vartioillensa, jotka seisoivat hänen tykönänsä: kääntäkäät itsenne ja tappakaat Herran papit; sillä heidän kätensä on myös Davidin kanssa, ja koska he tiesivät hänen paenneen, niin ei he ilmoittaneet sitä minulle. Mutta kuninkaan palveliat ei tahtoneet satuttaa käsiänsä Herran pappeihin, lyödäksensä heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Niin sanoi kuningas Doegille: käännä sinä itses ja lyö papit. Ja Doeg Edomilainen käänsi itsensä ja löi pappeja, ja tappoi sinä päivänä viisiyhdeksättäkymmentä miestä, jotka kantoivat liinaista päällisvaatetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Ja hän löi Noben, pappein kaupungin, miekan terällä, sekä miehet että vaimot, lapset ja imeväiset, niin myös härjät, aasit ja lampaat, aina miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Ja yksi Ahimelekin Akitobin pojan poika Abjatar nimeltä, pääsi, ja pakeni Davidin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Ja Abjatar ilmoitti Davidille, että Saul oli tappanut Herran papit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Ja David sanoi Abjatarille: minä sen sinä päivänä kyllä tiesin, koska Doeg Edomilainen oli siellä, että hän sen Saulille oli totisesti ilmoittava. Minä olen siis vikapää koko isäs huoneen kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Pysy minun tykönäni ja älä pelkää: joka seisoo minun henkeni perään, hän myös seisoo sinun henkes perään; sillä sinä varjellaan minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Ja Davidille ilmoitettiin, sanoen: katso, Philistealaiset sotivat Kegilaa vastaan ja ryöstävät heidän riihensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Niin David kysyi Herralta ja sanoi: pitääkö minun menemän ja lyömän näitä Philistealaisia? Ja Herra sanoi Davidille: mene, lyö Philistealaiset ja vapahda Kegila.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Ja Davidin miehet sanoivat hänelle: katso, me pelkäämme täällä Juudassa, ja menemme vielä Kegilaan Philistealaisten sotajoukon tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Niin David taas kysyi Herralta, ja Herra vastasi häntä ja sanoi: nouse ja mene alas Kegilaan; sillä minä annan Philistealaiset sinun käsiis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Niin David meni ja hänen miehensä Kegilaan, ja soti Philistealaisia vastaan, ja ajoi heidän karjansa pois, ja tappoi heitä suurella tapolla; ja niin David vapahti Kegilan asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Mutta kuin Abjatar Ahimelekin poika pakeni Davidin tykö Kegilaan, vei hän sinne myötänsä päällisvaatteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Niin sanottiin Saulille Davidin tulleeksi Kegilaan; ja Saul sanoi: Jumala on antanut hänen minun käsiini, että hän on salvattu, nyt hän on tullut kaupunkiin, joka on varustettu porteilla ja teljillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Ja Saul kuulutti kaiken kansan sotaan Kegilaan, piirittämään Davidia miehinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Kuin David ymmärsi Saulin aikovan pahaa hänellensä, sanoi hän papille Abjatarille: ota päällisvaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Ja David sanoi: Herra Israelin Jumala! sinun palvelias on tosin kuullut Saulin aikovan tulla Kegilaan, hävittämään minun tähteni kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Antanevatko Kegilan asuvaiset minun hänen käsiinsä? ja tulleeko Saul tänne niinkuin palvelias on kuullut? Herra Israelin Jumala, ilmoita se palvelialles! Ja Herra sanoi: hän tulee alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Ja David sanoi: antanevatko Kegilan asuvaiset minun ja minun väkeni Saulin käsiin? Herra sanoi: antavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Niin David nousi miehinensä, joita oli liki kuusisataa miestä, ja läksivät Kegilasta ja vaelsivat sinne mihinkä he vaaeltaa taisivat. Koska Saulille sanottiin Davidin paenneen Kegilasta, lakkasi hän sinne menemästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Ja David pysyi korvessa linnoissa, viipyi myös Siphin korven vuorella. Ja Saul etsi häntä joka aika, mutta ei Jumala antanut häntä hänen käsiinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Ja David näki Saulin lähteneeksi etsimään hänen henkensä perään, vaan David pysyi Siphin korvessa, yhdessä metsässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Niin Jonatan Saulin poika nousi ja meni Davidin tykö metsään, ja vahvisti hänen kätensä Jumalassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Ja sanoi hänelle: älä pelkää, sillä ei minun isäni Saulin käsi löydä sinua, ja sinä tule Israelin kuninkaaksi, ja minä olen likin sinua; ja sen myös Saul minun isäni kyllä tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Ja he molemmat tekivät liiton keskenänsä Herran edessä; ja David pysyi metsässä, mutta Jonatan palasi kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Mutta Siphiläiset menivät ylös Saulin tykö Gibeaan ja sanoivat: eikö David ole kätketty meidän tykönämme linnoissa metsässä, Hakilan kukkulalla, liki korpea oikialla puolella?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Niin tule nyt kuningas kiiruusti alas kaiken sydämes himon jälkeen: ja me annamme hänen kuninkaan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Ja Saul sanoi: olkaat te siunatut Herrassa, että te armahditte minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Menkäät siis ja tutkikaat paremmin, että te saisitte tietää ja nähdä sen paikan, jossa hänen jalkansa ovat, ja kuka hänen siellä on nähnyt; sillä minulle on hän sanottu sangen kavalaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Tutkistelkaat ja vaotkaat kaikki salaiset paikat, joihin hän lymyttää itsensä, ja tulkaat jälleen minun tyköni, kuin saatte vahvan tiedon; niin minä menen teidän kanssanne. Jos hän tällä maalla on, niin minä hänen etsin kaikkein tuhanten seasta Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Ja he nousivat ja menivät Siphiin Saulin edellä. Mutta David ja hänen miehensä olivat Maonin korvessa, oikialla puolella korpea, kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Kuin Saul matkusti sinne väkinensä etsimään häntä, ja se ilmoitettiin Davidille, meni hän kukkulalta alas, ja oli Maonin korvessa. Ja kuin Saul sen kuuli, ajoi hän Davidia takaa Maonin korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Ja Saul meni yhdeltä puolelta vuorta, ja David väkinensä toiselta puolelta vuorta. Ja koska David riensi pakenemaan Saulin edestä, piiritti Saul väkinensä Davidin ja hänen väkensä, ottaaksensa heitä kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Mutta sanansaattaja tuli Saulin tykö ja sanoi: kiiruhda sinuas ja tule nopiasti; sillä Philistealaiset ovat maalle tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Nin Saul palasi ajamasta Davidia takaa ja meni Philistealaisia vastaan; sentähden kutsutaan se paikka SelaMahelkot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '[]');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, '(H24:2) Kuin Saul palasi Philistealaisten tyköä, ilmoitettiin hänelle, sanoen: David on EnGedin korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, '(H24:3) Ja Saul otti kolmetuhatta valittua nuorta miestä koko Israelista, ja meni etsimään Davidia ja hänen miehiänsä Metsävuohten kallioille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, '(H24:4) Ja kuin hän lähestyi lammasten huonetta tien ohessa, oli siinä luola, ja Saul meni siihen peittämään jalkojansa; mutta David ja hänen miehensä istuivat luolan kulmilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, '(H24:5) Silloin sanoivat Davidin miehet hänelle: katso, tämä on se päivä, josta Herra sinulle on sanonut: katso, minä annan sinulle vihamiehes sinun käsiis, ettäs tekisit hänen kanssansa niinkuin sinulle kelpaa. Ja David nousi ja leikkasi salaa kappaleen Saulin vaatteen liepeestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, '(H24:6) Sen jälkeen tykytti Davidin sydän, että hän oli leikannut tilkan Saulin hameesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, '(H24:7) Ja sanoi miehillensä: Herra antakoon sen kaukana olla minusta, että minä sen tekisin ja satuttaisin käteni minun herraani, Herran voideltuun, sillä hän on Herran voideltu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, '(H24:8) Ja David asetti miehensä sanoilla eikä sallinut karata Saulin päälle. Niin Saul nousi luolasta ja meni matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, '(H24:9) Senjälkeen nousi myös David ja läksi luolasta, ja huusi Saulin jälkeen ja sanoi: herrani kuningas! Saul katsahti taaksensa, ja David kallisti kasvonsa maahan ja kumarsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, '(H24:10) Ja David sanoi Saulille: miksis uskot ihmisten sanoja, jotka sanovat: katso, David etsii vahinkoas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, '(H24:11) Katso, tänäpänä näkivät sinun silmäs, että Herra oli antanut sinun minun käsiini luolassa, ja sanottiin, että minä tappaisin sinun, vaan minä armahdin sinua, sillä minä sanoin: en minä satuta kättäni herraani, sillä hän on Herran voideltu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, '(H24:12) Katso, minun isäni, katso kuitenkin tätä tilkkaa sinun hameestas minun kädessäni, etten minä tahtonut tappaa sinua, koska minä sen tilkan leikkasin hameestas. Tunne ja katso, ettei yhtään pahuutta eli vääryyttä ole minun kädessäni, en minä myös ole syntiä tehnyt sinua vastaan, ja sinä seisot minun henkeni perään, ottaakses sen pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, '(H24:13) Herra tuomitkoon minun ja sinun välilläs, ja Herra kostakoon sinulle minun puolestani; vaan minun käteni ei pidä sinuun sattuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, '(H24:14) Niinkuin vanha sananlasku on: jumalattomasta tulee jumalattomuus; mutta minun käteni ei pidä sinuun sattuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, '(H24:15) Kenenkä jälkeen Israelin kuningas on lähtenyt? ketäs ajat takaa? Kuollutta koiraa ja kirppua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, '(H24:16) Herra olkoon tuomari ja tuomitkoon minun välilläni ja sinun: nähköön ja ratkaiskoon minun asiani, ja vapahtakoon minua sinun käsistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, '(H24:17) Sittekuin David lakkasi puhumasta Saulille, sanoi Saul: eikö se ole sinun äänes, poikani David? Ja Saul korotti äänensä ja itki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, '(H24:18) Ja sanoi Davidille: sinä olet hurskaampi minua, sillä sinä olet osoittanut minulle hyvää, mutta minä sitä vastaan olen osoittanut sinulle pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, '(H24:19) Ja sinä olet tänäpänä minulle ilmoittanut, kuinka hyvin sinä olet tehnyt minua kohtaan: että Herra oli sulkenut minun sinun käsiis, ja et sinä minua tappanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, '(H24:20) Kuinka joku löytäis vihollisensa ja antais hänen mennä hyvää tietä? Herra maksakoon sinulle sitä hyvää, jotas tänäpänä minulle olet tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, '(H24:21) Nyt katso, minä tiedän sinun tulevan kuninkaaksi, ja Israelin valtakunta on sinun kädessäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, '(H24:22) Niin vanno siis nyt minulle Herran kautta, ettet hävitä minun siementäni minun jälkeeni ja et kadota minun nimeäni minun isäni huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, '(H24:23) Ja David vannoi Saulille. Ja Saul meni kotiansa; mutta David ja hänen miehensä menivät linnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Ja Samuel kuoli, ja koko Israel kokoontui murehtimaan häntä ja hautasi hänen omaan huoneeseensa Ramaan. Mutta David nousi ja meni alas Paranin korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Ja yksi mies asui Maonissa, jolla myös oli tekemistä Karmelissa, ja se mies oli sangen rikas, ja hänellä oli kolmetuhatta lammasta ja tuhannen vuohta; ja hän keritsi lampaitansa Karmelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Ja miehen nimi oli Nabal, ja hänen emäntänsä nimi Abigail; ja se oli toimellinen vaimo ja kaunis kasvoilta, mutta mies oli sangen kova ja paha töissänsä, ja hän oli Kalebin sukua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Ja kuin David kuuli korvessa Nabalin keritsevän lampaitansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Lähetti hän kymmenen nuorukaista ja sanoi heille: menkäät Karmeliin, ja kuin te tulette Nabalin tykö, niin tervehtikäät häntä minun puolestani ystävällisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'Ja sanokaat: terve! rauha olkoon sinulle, ja rauha huoneelles, ja kaikille mitä sinulle on, olkoon rauha!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Minä olen nyt saanut kuulla, että sinulla on lammasten keritsiät: katso, paimenet jotka sinulla on, olivat meidän tykönämme, ja emme heitä häväisseet, ja ei heiltä mitään puuttunut niinkauvan kuin he olivat Karmelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Kysy palvelioiltas, he sanovat sinulle. Niin anna siis nuorukaisten löytää armo sinun kasvois edessä, sillä me olemme tulleet hyvään aikaan: anna siis palvelioilles ja pojalles Davidille, mitä sinun kätes löytää!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Kuin Davidin palveliat sinne tulivat ja puhuivat kaikki nämät sanat Nabalille Davidin puolesta, niin he vaikenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Mutta Nabal vastasi Davidin palvelioita ja sanoi: kuka on David? ja kuka on Isain poika? Nyt on monta palveliaa, jotka jättävät isäntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Pitääkö minun ottaman leipäni, veteni ja teuraani, jonka minä keritsiöilleni olen teurastanut, ja antaman miehille, joita en minä tiedä, kusta he tulleet ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Niin Davidin palveliat palasivat tiellensä, ja tultuansa taas Davidin tykö sanoivat he hänelle kaikki nämät sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Niin sanoi David miehillensä: vyöttäkään kukin miekkansa vyöllensä. Niin vyötti jokainen miekkansa vyöllensä, ja David vyötti myös miekkansa vyöllensä; ja läksi Davidin kanssa liki neljäsataa miestä, mutta kaksisataa jäi kaluin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Mutta yksi palvelioista ilmoitti Abigailille, Nabalin emännälle, sanoen: katso, David on lähettänyt sanansaattajat korvesta siunaamaan isäntäämme, mutta hän tiuskui heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Ja ne miehet olivat meille aivan hyvät ja ei meitä pahoin puhutelleet, ja ei meiltä mitään puuttunut niinkauvan kuin me vaelsimme heidän tykönänsä kedolla ollessamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Mutta he ovat olleet meidän turvamme yötä ja päivää, niinkauvan kuin me kaitsimme lampaitamme heidän tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Niin ajattele nyt ja katso mitäs teet; sillä pahuutta on totisesti tarjona meidän isännällemme ja kaikelle hänen huoneellensa, vaan hän on tyly mies, jota ei yksikään tohdi puhutella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Niin Abigail kiiruhti ja otti kaksisataa leipää, ja kaksi leiliä viinaa, ja viisi keitettyä lammasta, ja viisi vakkaista tuletettuja jauhoja, ja sata rusinarypälettä, ja kaksisataa rypälettä fikunia, ja pani aasein päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Ja sanoi palvelioillensa: menkäät minun edelläni, katso, minä tulen perässänne. Ja ei hän miehellensä Nabalille sitä ilmoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Ja kuin hän ajoi aasilla ja tuli vuoren varjoon, katso, David ja hänen väkensä tulivat vuorilta alas häntä vastaan; ja hän kohtasi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Mutta David oli sanonut: minä olen turhaan tallella pitänyt kaikki, mitä hänellä oli korvessa, ja ei ole mitään puuttunut kaikista mitä hänellä oli; ja hän kostaa minun hyvät työni pahalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Jumala tehköön näitä Davidin vihamiehille ja vielä suurempia, jos minä jätän hänelle huomeneksi kaikista, mitä hänellä on, jonkun, joka vetensä seinään heittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Mutta kuin Abigail näki Davidin, kiiruhti hän ja astui nopiasti alas aasin päältä, lankesi kasvoillensa Davidin eteen ja kumarsi itsensä maahan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Ja lankesi hänen jalkainsa juureen ja sanoi: Ah herrani, minun olkoon tämä paha teko! ja anna piikas puhua korvais kuullen, ja kuule piikas sanaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Älkään minun herrani asettako sydäntänsä tätä tylyä miestä Nabalia vastaan; sillä niinkuin hänen nimensä kuuluu, niin on hän: Nabal on hänen nimensä, tyhmyys on hänen kanssansa; mutta minä sinun piikas en ole nähnyt herrani palvelioita, jotka sinä olit lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Mutta nyt, herrani, niin totta kuin Herra elää ja niin totta kuin sinun sielus elää, niin Herra on sinun estänyt, ettet verta vuodattanut eikä sinun kätes vapahtanut sinua. Mutta nyt olkoon sinun vihamiehes niin kuin Nabal ja kaikki jotka herralleni pahaa suovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Tämä on se siunaus, jonka sinun piikas minun herralleni tuonut on, annettaa palvelioille, jotka herrani kanssa vaeltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Anna piialles tämä rikos anteeksi. Sillä Herra tosin tekee minun herralleni vahvan huoneen; sillä koska minun herrani sotii Herran sotia, niin ei yhtäkään pahuutta ole löydetty sinun tyköäs kaikkena sinun elinaikanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Jos joku ihminen asettaa itsensä vainoomaan sinua ja väijyy sinun sielus jälkeen, niin olkaan herrani sielu sidottu eläväin kimppuun Herran sinun Jumalas tykönä; mutta sinun vihollistes sielu pitää lingottaman lingolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Ja kuin Herra minun herralleni kaikki nämät hyvät tekevä on, niinkuin hän sinulle sanonut on, ja käskee sinun olla Israelin ruhtinaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Niin ei pidä se oleman sinulle minun herralleni lankeemiseksi ja mielen pahennukseksi, ettet vuodattanut verta ilman syytä ja auttanut itse sinuas; ja Herra on hyvää tekevä minun herralleni, ja sinä muistat piikaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Silloin sanoi David Abigailille: kiitetty olkoon Herra Israelin Jumala, joka sinun tänäpänä on lähettänyt minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Ja siunattu olkoon sinun toimellinen puhees, ja siunattu olet sinä, joka minun tänäpänä estit verta vuodattamasta ja kostamasta omalla kädelläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Totisesti, niin totta kuin Herra Israelin Jumala elää, se joka minun on tänäpänä estänyt sinulle pahaa tekemästä, jollet nopiasti olisi tullut minua vastaan, niin ei olisi Nabalille jäänyt huomeneksi yhtäkään seinään vetensä heittävää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Niin otti David hänen kädestänsä, mitä hän oli hänelle tuonut, ja sanoi hänelle: mene rauhassa sinun huoneeses, ja katso, minä kuulin sinun äänes ja otin sinun hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Kuin Abigail tuli Nabalin tykö, katso, niin hänellä oli huoneessansa pito, niinkuin kuninkaallinen pito, ja Nabalin sydän oli iloinen, sillä hän oli juuri kovin juovuksissa; mutta ei hän sanonut hänelle vähää eli paljoa huomeneen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Mutta huomeneltain, kuin Nabal oli viinasta kaljennut, sanoi hänen emäntänsä hänelle kaikki nämät; niin hänen sydämensä kuoli hänessä, että hän tuli niinkuin kivi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Ja kymmenen päivän perästä löi Herra Nabalin, että hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Kuin David kuuli Nabalin kuolleeksi, sanoi hän: kiitetty olkoon Herra, joka on kostanut häväistykseni Nabalille ja on varjellut palveliansa pahasta, ja Herra on kääntänyt Nabalin pahuuden hänen päänsä päälle. Ja David lähetti ja antoi puhutella Abigailia, ottaaksensa häntä emännäksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Ja kuin Davidin palveliat tulivat Abigailin tykö Karmeliin, puhuttelivat he häntä ja sanoivat: David lähetti meitä sinun tykös, että hän ottais sinun emännäksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Hän nousi ja lankesi maahan kasvoillensa, sanoen: katso, tässä on sinun piikas palvelemaan ja pesemään herrani palveliain jalkoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Ja Abigail kiiruhti itsensä, ja valmisti hänensä, ja ajoi aasilla, ja otti viisi piikaansa kanssansa, jotka kävivät hänen jälissänsä; ja hän seurasi Davidin sanansaattajia ja tuli hänen emännäksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'David otti myös Ahinoamin Jisreelistä; ja olivat ne molemmat hänen emäntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Mutta Saul antoi tyttärensä Mikalin, Davidin emännän, Phaltille Laiksen pojalle Gallimista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Ja Siphiläiset tulivat Saulin tykö Gibeaan ja sanoivat: eikö David ole lymyssä Hakilan kukkulalla korven kohdalla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Niin nousi Saul ja meni Siphin korpeen, ja hänen kanssansa kolmetuhatta valittua miestä Israelista, etsimään Davidia Siphin korvesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Ja Saul sioitti itsensä Hakilan kukkulalle korven kohdalle tien viereen, mutta David pysyi korvessa ja näki Saulin tulevan perässänsä korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Niin David lähetti vakoojat ja ymmärsi Saulin totisesti tulleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Ja David nousi ja tuli siihen paikkaan, johonka Saul itsensä sioittanut oli; ja David näki paikan, kussa Saul ja hänen sotapäämiehensä Abner Neerin poika oli; sillä Saul makasi vaunuin piirissä, ja sotaväki sioitettuna hänen ympärillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Silloin vastasi David ja sanoi Ahimelekille, Hetiläiselle, ja Abisaille ZeruJan pojalle Joabin veljelle: kuka menee minun kanssani Saulin tykö leiriin? Abisai sanoi: minä menen kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Niin tuli David ja Abisai kansan tykö yöllä, ja katso, Saul makasi nukkuneena vaunuin piirissä, ja hänen keihäänsä pistetty maahan hänen päänsä pohjaan; mutta Abner ja kansa makasi hänen ympärillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Silloin sanoi Abisai Davidille: Jumala on sulkenut tänäpänä vihamiehes sinun kätees: nyt minä syöksen häntä keihäällä maata vasten yhden kerran, niin etten minä enään tarvitse kertoa sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Mutta David sanoi Abisaille: älä surmaa häntä; sillä kuka satuttaa kätensä Herran voideltuun ja on viatoin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Vielä sanoi David: niin totta kuin Herra elää; jollei Herra lyö häntä, elikkä tule hänen aikansa kuolla, eli mene sotaan ja huku,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Niin antakoon Herra kaukana olla minusta, että minä satuttaisin käteni Herran voideltuun: ota nyt vaivoin keihäs hänen päänsä pohjasta ja vesimalja, ja käykäämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Niin otti David keihään ja vesimaljan Saulin pään pohjasta, ja he menivät matkaansa; ja ei yhtään ollut, joka sen näki taikka huomaitsi, eli heräsi, vaan he makasivat kaikki nukkuneena, sillä Herralta oli tullut syvä uni heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Kuin David oli tullut ylitse toiselle puolelle, meni hän kauvas vuoren kukkulalle, että iso väli oli heidän välillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Ja David huusi kansalle ja Abnerille Neerin pojalle ja sanoi: etkös vastaa, Abner? Abner vastasi ja sanoi: kukas olet, ettäs niin huudat kuningasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Ja David sanoi Abnerille: etkös ole mies? ja kuka on sinun vertaises Israelissa? Miksi et varjellut herraas kuningasta? Sillä yksi kansasta on mennyt tappamaan kuningasta sinun herraas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Ei se ole oikein minkä sinä tehnyt olet. Niin totta kuin Herra elää, te olette kuoleman lapset, ettette varjelleet herraanne, Herran voideltua. Ja nyt katso, kussa kuninkaan keihäs ja vesimalja on, jotka hänen päänsä pohjassa olivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Niin Saul tunsi Davidin äänen ja sanoi: eikö se ole sinun äänes, minun poikani David? David sanoi: minun ääneni se on, herrani kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Ja vielä sanoi: miksi minun herrani vainoo palveliaansa? Sillä mitä minä olen tehnyt ja mitä pahaa on minun kädessäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Niin kuulkaan siis nyt herrani kuningas palveliansa sanan: Jos Herra on yllyttänyt sinun minua vastaan, niin anna joku ruokauhri sytytettää, mutta jos ihmiset sen tekevät, niin olkoon he kirotut Herran edessä, että he tänäpänä ovat minun syösseet ulos, etten minä pysyisi Herran perimisessä, ja sanovat: mene ja palvele muukalaisia jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Niin älköön minun vereni langatko maahan Herran eteen; sillä Israelin kuningas on lähtenyt yhtä kirppua etsimään, niinkuin hän takaa ajelis peltokanaa vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Ja Saul sanoi: minä olen syntiä tehnyt. Tule jälleen poikani David! sillä en minä sinulle enää tee pahaa, että minun sieluni on tänäpänä ollut kallis sinun silmäis edessä: katso, minä olen tehnyt tyhmästi ja sangen hullusti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David vastasi ja sanoi: katso, tässä on kuninkaan keihäs, tulkaan yksi palvelioistas tänne ja ottakaan sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Herra maksaa jokaiselle hänen vanhurskautensa ja uskonsa jälkeen; sillä Herra on sinun tänäpänä antanut minun käteeni, vaan en minä tahtonut satuttaa kättäni Herran voideltuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Ja katso, niinkuin sinun sielus tänäpänä on paljo pidettävä ollut minun silmäini edessä, niin olkoon myös minun sieluni paljo pidettävä Herran silmäin edessä, ja vapahtakoon minua kaikesta minun murheestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul sanoi Davidille: siunattu ole sinä, poikani David: sinä teet ja toimitat, sinä taidat ja voit. Niin David meni matkaansa, ja Saul palasi kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Niin David ajatteli sydämessänsä: kuitenkin minä yhtenä päivänä joudun Saulin käsiin: ei ole minun parempaa, kuin että minä menen ojetinsa Philistealaisten maalle, että Saul lakkais minua etsimästä kaikissa Israelin rajoissa, ja minä pääsisin hänen käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Ja David nousi ja läksi matkaan kuudensadan miehen kanssa, jotka hänen myötänsä olivat, Akiksen Maokin pojan Gatin kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Niin David asui Akiksen tykönä Gatissa, hän ja hänen miehensä itsekukin perheinensä: David ja kaksi hänen emäntäänsä, Ahinoam Jisreelista ja Abigail Nabalin emäntä Karmelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Kuin Saulille sanottiin Davidin paenneen Gatiin, niin ei hän enää häntä etsinyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Niin David sanoi Akikselle: jos minä olen löytänyt armon sinun edessäs, niin anna minulle yhteen kaupunkiin sia maalle, asuakseni siellä; sillä miksi pitäis sinun palvelias asuman kuninkaallisessa kaupungissa sinun tykönäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Sinä päivänä antoi Akis hänelle Ziklagin. Sentähden on Ziklag Juudan kuningasten vielä tänäpänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Vaan se aika, minkä David asui Philistealaisten maalla, oli ajastaika ja neljä kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Ja David nousi miehinensä ja karkasi Gessurilaisten ja Girsiläisten ja Amalekilaisten maalle; sillä nämät asuivat jo vanhuudesta siinä maassa, kuin Suriin mennään, Egyptin maahan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Ja kuin David oli kaiken maan lyönyt, ei hän jättänyt yhtäkään miestä eli vaimoa elämään; ja otti heidän lampaansa, härkänsä, aasinsa, kamelinsa ja vaatteensa, palasi ja tuli Akiksen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Ja Akis sanoi: kenenkä päälle te olette karanneet tänäpänä? David vastasi: lounaan päin Juudaa, lounaan päin Jerakmelilaisia ja lounaan päin Keniläisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Ja ei David jättänyt eläväksi yhtäkään miestä eli vaimoa viedäksensä Gatiin, ja ajatteli: ettei he puhuisi jotakin meitä vastaan, sanoen: näin teki David, ja tämä oli hänen tapansa niinkauvan kuin hän asui Philistealaisten maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Niin Akis uskoi Davidin ja ajatteli, hän on tehnyt itsensä kokonansa kauhistuttavaksi kansallensa Israelille, sentähden olkaan hän aina minun palveliani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Ja Philistealaiset kokosivat siihen aikaan sotaväkensä menemään sotaan Israelia vastaan. Ja Akis sanoi Davidille: Sinun pitää kaiketi tietämän, että sinä ja sinun väkes pitää menemän minun kanssani sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'David vastasi Akikselle: olkoon; sinä saat nähdä, mitä sinun palvelias on tekevä. Akis sanoi Davidille: sentähden asetan minä sinun pääni vartiaksi joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Niin oli Samuel kuollut, ja koko Israel oli häntä murehtinut ja haudannut hänen kaupunkiinsa Raaman. Ja Saul oli ajanut maakunnasta noidat ja velhot pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Kuin Philistealaiset kokosivat heitänsä, ja tulivat ja sioittivat itsensä Sunemiin, kokosi myös Saul kaiken Israelin, ja he sioittivat itsensä Gilboaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Kuin Saul näki Philistealaisten sotajoukon, pelkäsi hän ja hänen sydämensä oli suuresti hämmästynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Ja Saul kysyi Herralta, ja ei Herra mitään häntä vastannut, ei unen, eikä valkeuden, eli prophetain kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Silloin sanoi Saul palvelioillensa: etsikäät minulle vaimo, jolla noidan henki on, mennäkseni hänen tykönsä ja kysyäkseni häneltä. Hänen palveliansa sanoivat hänelle: katso, Endorissa on vaimo, jolla on noidan henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Ja Saul muutti vaatteensa ja otti toiset päällensä, ja meni sinne, ja kaksi miestä hänen kanssansa; ja he tulivat yöllä vaimon tykö, ja hän sanoi: noidu minulle noidan hengen kautta ja nosta se ylös minulle, jonka sanon sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Vaimo sanoi hänelle: katso, sinä tiedät kyllä, mitä Saul tehnyt on, kuinka hän on hävittänyt noidat ja velhot maakunnasta: miksi siis tahdot minun sieluani pauloihin, että minä kuoliaaksi lyötäisiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Niin Saul vannoi hänelle Herran kautta ja sanoi: niin totta kuin Herra elää, ei tämä lueta sinulle pahuudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Niin vaimo sanoi: kenen minä nostan sinulle? Hän sanoi: nosta minulle Samuel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Kuin vaimo näki Samuelin, huusi hän suurella äänellä, ja sanoi Saulille sanoen: miksis olet minun pettänyt? sinä olet Saul.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Ja kuningas sanoi hänelle: älä pelkää! mitäs näet? Vaimo sanoi Saulille: minä näen jumalat astuvan maasta ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Hän sanoi hänelle: kuinka hän on muotoansa? ja hän sanoi: vanha mies nousee ylös ja on vaatetettu hameella. Niin ymmärsi Saul sen olevan Samuelin, ja kumarsi kasvoillensa maahan ja rukoili.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Mutta Samuel sanoi Saulille: miksis olet minua vaivannut nostaen minua? Saul sanoi: minä olen suuressa ahdistuksessa: Philistealaiset sotivat minua vastaan ja Jumala on minusta erinnyt, ja ei vastaa enää minua prophetain eikä unen kautta; sentähden olen minä antanut sinua kutsua, ilmoittamaan, mitä minun tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel sanoi: mitäs kysyt minulta, että Herra on sinusta erinnyt ja on sinun vihamiehekses tullut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Herra on tekevä niinkuin hän minun kauttani puhunut on: ja Herra repäisee valtakunnan sinun kädestäs pois ja antaa lähimmäiselles Davidille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Ettet kuullut Herran ääntä, etkä täyttänyt hänen vihansa julmuutta Amalekia vastaan, sentähden on Herra näitä sinulle tänäpänä tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Ja vielä sitte antaa Herra sinun kanssas Israelin Philistealaisten käsiin: huomenna pitää sinun ja sinun poikas oleman minun tykönäni: ja Herra antaa Israelin sotajoukon Philistealaisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Niin Saul kaatui äkisti maahan niin pitkäksi kuin hän oli, ja peljästyi suuresti Samuelin puheen tähden, niin ettei hänessä mitään enämpi voimaa ollut, sillä ei hän ollut mitään syönyt koko sinä päivänä ja yönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Ja vaimo meni Saulin tykö ja näki hänen suuresti peljästyneeksi, ja sanoi hänelle: katso, sinun piikas on kuullut sinun sanas, ja minä olen pannut sieluni käteeni, niin että minä kuuliainen olin sinun sanalles, jonkas puhuit minulle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Niin kuule myös nyt sinä piikas sana: minä panen etees palan leipää, ettäs söisit ja tulisit väkees jällensä, ja menisit matkaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Hän kielsi ja sanoi: en minä syö. Niin hänen palveliansa ja vaimo vaativat häntä syömään, ja hän totteli heidän ääntänsä, ja nousi maasta ja istui vuoteelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Ja vaimolla oli huoneessa lihava vasikka, ja hän kiiruhti ja teurasti sen, ja otti jauhoja ja sekoitti, ja leipoi sen happamattomiksi kyrsiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Ja kantoi Saulin ja hänen palveliainsa eteen. Ja kuin he olivat syöneet, nousivat he ja matkustivat sinä yönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Mutta Philistealaiset kokosivat kaiken sotajoukkonsa Aphekiin; ja Israel sioitti itsensä Ainiin Jisreelissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Ja Philistealaisten päämiehet menivät sadoittain ja tuhansittain; mutta David meni jälistä miehinensä, liki Akista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Niin sanoivat Philistealaisten päämiehet: mitä nämät Hebrealaiset tahtovat? Akis sanoi Philistealaisten päämiehille: eikö tämä ole David Saulin Israelin kuninkaan palvelia, joka on ollut monta päivää eli vuoden minun tykönäni ja en minä ole löytänyt mitäkään hänen kanssansa siitä ajasta, kuin hän pakeni minun tyköni, tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Niin Philistealaisten päämiehet vihastuivat hänen päällensä ja sanoivat hänelle: anna sen miehen palata ja mennä jälleen siallensa, kuhunkas hänen asettanut olet, ettei hän tulisi meidän kanssamme sotaan ja olisi meidän vihamiehemme sodassa; sillä millä taitais hän paremmin herrallensa mielinouteen tehdä, kuin näiden miesten päillä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Eikö tämä ole David? josta he veisasivat hypyssä, sanoen: Saul löi tuhannen, mutta David kymmenentuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Niin kutsui Akis Davidin ja sanoi hänelle: niin totta kuin Herra elää, minä pidän sinun oikiana ja hyvänä, ja sinun ulos ja sisälle käymises minun kanssani sotaleiriin kelpaa minulle, sillä en ole minä löytänyt yhtään pahuutta sinusta siitä ajasta, kuin sinä tulit minun tyköni, niin tähän päivään asti; mutta et sinä kelpaa päämiehille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Niin palaja nyt takaperin ja mene rauhaan, ettes pahaa tekisi Philistealaisten päämiesten silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David sanoi Akikselle: mitä minä olen tehnyt? ja mitäs olet löytänyt palvelialtas siitä ajasta, kuin minä olen ollut sinun tykönäs, niin tähän päivään asti, etten minä saa tulla ja sotia kuninkaan minun herrani vihamiehiä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Akis vastasi ja sanoi Davidille: minä tiedän sinun otolliseksi minun silmäini edessä, niinkuin Jumalan enkelin, mutta Philistealaisten päämiehet ovat sanoneet: älä anna hänen tulla meidän kanssamme sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Niin nouse siis varhain aamulla, ja sinun herras palveliat, jotka sinun kanssas tulleet ovat: ja kuin te olette aamulla varhain nousseet ja päivä teille valkenee, niin menkäät teidän tietänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Niin David oli miehinensä aamulla varhain ylhäällä, matkustamaan ja tulemaan Philistealaisten maalle jälleen; mutta Philistealaiset menivät Jisreeliin päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Kuin David kolmantena päivänä tuli Ziglagiin miehinensä, olivat Amalekilaiset tulleet etelän puolelta Ziglagiin, lyöneet Ziglagin ja polttaneet sen tulella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Ja olivat vieneet vaimot, jotka siellä olivat, pienimmästä niin suurimpaan; ei he yhtäkään surmanneet, mutta veivät pois ja menivät tiehensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Kuin David tuli miehinensä kaupunkiin, katso, se oli tulella poltettu, ja heidän emäntänsä ja poikansa ja tyttärensä viedyt vangiksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Korotti David ja väki, joka hänen kanssansa oli, äänensä ja itkivät siihenasti, ettei heillä enää voimaa itkeä ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Ja Davidin kaksi emäntää olivat myös vankina viedyt pois: Ahinoam Jisreeliläinen ja Abigail Nabalin emäntä Karmelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Ja David oli suuresti ahdistettu, sillä kansa tahtoi hänen kivittää, että kaiken kansan sielut olivat murheissa poikainsa ja tytärtensä tähden. Mutta David vahvisti itsiänsä Herrassa Jumalassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Ja David sanoi papille AbJatarille Ahimelekin pojalle: tuo minulle päällisvaate. Ja AbJatar toi Davidille päällisvaatteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Niin kysyi David Herralta ja sanoi: pitääkö minun ajaman sitä joukkoa takaa? saanenko minä heidät kiinni? Hän sanoi hänelle: aja heitä takaa, ja sinä totisesti saavutat heidät ja otat saaliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Niin meni David matkaan, hän ja kuusisataa miestä, jotka hänen kanssansa olivat, ja tulivat Besorin ojan tykö; ja muut seisahtivat siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Mutta David ja neljäsataa miestä ajoivat takaa; mutta kaksisataa miestä, jotka siihen seisomaan jäivät, suuttuivat menemästä Besorin ojan ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Ja he löysivät yhden Egyptin miehen kedolta, sen he veivät Davidin tykö, ja antoivat hänen leipää syödä ja vettä juoda,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Ja antoivat rypäleen fikunia ja kaksi rypälettä rusinoita; ja sittenkuin hän oli syönyt, tuli hänen henkensä virvoitetuksi, sillä ei hän ollut kolmena päivänä eikä kolmena yönä leipää syönyt eikä vettä juonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Ja David sanoi hänelle: kenenkä sinä olet ja kustas olet? Egyptin nuorukainen sanoi: minä olen Amalekilaisen palvelia, ja minun herrani on hyljännyt minun; sillä minä tulin sairaaksi jo kolme päivää sitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Me ryöstimme etelästä päin Kretin ja Juudan, etelästä päin Kalebin, ja poltimme Ziglagin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'David sanoi hänelle: vietkös minun sen sotaväen tykö? Hän sanoi: vannos minulle Jumalan kautta, ettes minua tapa etkä anna minua minun herrani käsiin, niin minä vien sinun sen sotaväen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Ja hän vei hänen; ja katso, he olivat hajoittaneet heitänsä koko maahan, söivät, joivat ja hyppäsivät ilosta kaiken sen suuren saaliin tähden, jonka he olivat saaneet Philistealaisten ja Juudan maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Ja David löi heitä aamuhämärästä ruveten ehtooseen asti, liki toiseen päivään; niin ettei heistä yhtäkään päässyt, paitsi neljäsataa nuorukaista, jotka istuivat kamelein päälle ja pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Niin David pelasti kaikki mitä Amalekilaiset ottaneet olivat, ja David pelasti myös kaksi emäntäänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Ja ei puuttunut niistä mitään, pientä eli suurta, pojista ja tyttäristä, eli saaliista kun he heillensä ottaneet olivat: David toi ne kaikki takaperin jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Ja David otti kaikki lampaat ja härjät ja antoi ajaa ne karjansa edellä, ja he sanoivat: tämä on Davidin saalis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Ja kuin David tuli kahdensadan miehen tykö, jotka olivat suuttuneet seuraamasta Davidia ja olivat jääneet Besorin ojan tykö, menivät he Davidia vastaan ja sitä sotaväkeä joka hänen kanssansa oli. Ja David meni sen väen tykö ja tervehti heitä ystävällisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Niin vastasivat kaikki ne, jotka pahat ja tylyt miehet olivat niiden seasta, jotka Davidin kanssa olivat matkustaneet, ja sanoivat: ettei he menneet meidän kanssamme, ei pidä heille annettaman siitä saaliista jonka me saaneet olemme; mutta itsekukin ottakaan emäntänsä ja lapsensa ja menkään tiehensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Niin sanoi David: ei teidän niin pidä tekemän, minun veljeni, sillä Herra on ne meille antanut, ja on meidät varjellut ja antanut sen sotaväen meidän käsiimme, joka tuli meitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Kuka teitä pitää kuuleman tässä asiassa? Senkaltainen kuin niiden osa on, jotka olivat sodassa meidän kanssamme, pitää myös oleman heidän osansa jotka kaluin tykönä ovat olleet, ja pitää yhdenkaltainen jako oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Tämä on ollut siitä ajasta ja aina sitte sääty ja oikeus Israelissa tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Ja David tuli Ziglagiin ja lähetti saaliista ylimmäisille Juudasta, jotka hänen ystävänsä olivat, ja sanoi: katso, tässä on teille siunaus Herran vihollisten saaliista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Niille jotka olivat Betelissä, niille Ramotissa etelään päin, niille Jatirissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Niille Aroerissa, niille Siphmotissa, niille Estmoassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Ja niille kuin on Rakalissa, ja niille Jerakmelilaisten kaupungeista, ja niille Keniläisten kaupungeista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Niille Hormassa, ja niille Korasanissa, ja niille Atakissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'Niille Hebronissa, ja kaikkiin paikkoihin, kussa David oli miehinensä vaeltanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Niin Philistealaiset sotivat Israelia vastaan, ja Israelin miehet pakenivat Philistealaisia ja lankesivat lyötynä Gilboan vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Ja Philistealaiset ajoivat Saulia ja hänen poikiansa takaa, ja Philistealaiset surmasivat Jonatanin, Abinadabin ja Melkisuan, Saulin pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Ja sota oli ankara Saulia vastaan, ja joutsimiehet kävivät hänen päällensä joutsilla, ja hän haavoitettiin pahoin joutsimiehiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Niin sanoi Saul aseensa kantajalle: vedä ulos miekkas ja pistä sillä minua lävitse, ettei nämät ympärileikkaamattomat tulisi ja pistäisi minua lävitse, ja pilkkaisi minua. Mutta hänen aseensa kantaja ei tahtonut, sillä hän pelkäsi suuresti. Niin otti Saul miekan ja lankesi siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Kuin hänen aseensa kantaja näki Saulin kuolleeksi, lankesi hän myös miekkaansa ja kuoli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Ja niin kuoli Saul ja kolme hänen poikaansa, ja hänen aseensa kantaja, ja ynnä kaikki hänen miehensä sinä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Kuin Israelin miehet, jotka olivat toisella puolella laaksoa ja toisella puolella Jordania, näkivät Israelin miehet paenneeksi ja Saulin poikinensa kuolleeksi, jättivät he kaupungit ja pakenivat. Niin tulivat Philistealaiset ja asuivat niissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Ja toisena päivänä tulivat Philistealaiset ryöstämään tapetuita ja löysivät Saulin ja kolme hänen poikaansa makaavan Gilboan vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Ja hakkasivat hänen päänsä pois, ja ottivat häneltä aseet, ja lähettivät ympäri Philistealaisten maakuntaa, ilmoitettaa epäjumalainsa huoneissa ja kansan seassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Ja panivat hänen aseensa Astarotin huoneesen; mutta hänen ruumiinsa ripustivat he Betsanin muurin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Kuin Jabeksen asuvaiset Gileadissa kuulivat, mitä Philistealaiset Saulille tehneet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Nousivat kaikki sotaan kelpaavaiset miehet, kävivät kaiken sen yön ja ottivat Saulin ruumiin ja hänen poikainsa ruumiit alas Betsanin muurin päältä, veivät Jabekseen ja polttivat ne siellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Ja ottivat heidän luunsa ja hautasivat puun alle Jabekseen, ja paastosivat seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Ja tapahtui Saulin kuoleman jälkeen, kuin David oli palannut Amalekilaisten taposta, oli David Ziklagissa kaksi päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Katso, kolmantena päivänä tuli yksi mies Saulin leiristä reväistyillä vaatteilla ja multaa päänsä päällä. Ja kuin hän tuli Davidin tykö, lankesi hän maahan ja kumarsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'David sanoi hänelle: kustas tulet? Ja hän sanoi hänelle: minä olen paennut Israelin leiristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David sanoi hänelle: sanos minulle, mitä siellä on tapahtunut? Hän vastasi: väki on paennut sodasta, ja paljo väkeä on langennut ja kuollut, ja myös Saul ja hänen poikansa Jonatan ovat kuolleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'David sanoi nuorukaiselle, joka näitä ilmoitti: mistä sinä tiedät Saulin ja hänen poikansa Jonatanin kuolleeksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Nuorukainen, joka hänelle sitä ilmoitti, sanoi: minä tulin tapaturmasta Gilboan vuorelle, ja katso, Saul oli langennut omaan keihääseensä, ja katso, rattaat ja hevosmiehet ajoivat häntä takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Ja sitte hän käänsi hänensä, ja näki minun ja kutsui tykönsä, ja minä sanoin: tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Hän sanoi minulle: kuka sinä olet? Minä vastasin: minä olen Amalekilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Ja hän sanoi minulle: tules minun tyköni ja tapa minua; sillä minä ahdistetaan kovin ja minun henkeni on vielä kokonainen minussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Niin minä menin hänen tykönsä ja tapoin hänen; sillä minä tiesin, ettei hän olisi kuitenkaan sen lankeemisen jälkeen elänyt. Ja minä otin kruunun hänen päästänsä ja käsirenkaat hänen kädestänsä ja toin ne tänne minun herralleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Silloin tarttui David vaatteisiinsa ja repäisi ne; niin myös joka mies, joka hänen kanssansa oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Ja valittivat ja itkivät, ja paastosivat ehtoosen asti, Saulin ja hänen poikansa Jonatanin tähden, ja Herran kansan tähden, ja Israelin huoneen tähden, että ne miekan kautta langenneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Ja David sanoi nuorukaiselle, joka näitä hänelle ilmoitti: kusta sinä olet? Hän sanoi: minä olen muukalaisen Amalekilaisen poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'David sanoi hänelle: miksi et peljännyt laskea kättäs tappamaan Herran voideltua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Ja David kutsui yhden palvelioistansa ja sanoi: tule tänne ja lyö häntä. Ja hän löi hänen kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Niin sanoi David hänelle: sinun veres olkoon sinun pääs päällä; sillä sinun suus on todistanut itse sinuas vastaan ja sanonut: minä olen Herran voidellun tappanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Ja David valitti tämän valituksen Saulin ja Jonatanin hänen poikansa ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'Ja käski opettaa Juudan lapsia Joutsivirren: katso, se on kirjoitettu Hurskasten kirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'O Israelin kunnia! sinun kukkuloillas ovat surmatut: kuinka sankarit ovat langenneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Älkäät sanoko sitä Gatissa, älkäät myös ilmoittako Askalonin kaduilla, ettei Philistealaisten tyttäret iloitsisi eikä ympärileikkaamattomain tyttäret riemuitsisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Te Gilboan vuoret, älköön tulko kaste eikä sade teidän päällenne, älköön myös olko pellot, joista ylennysuhri tulee; sillä siellä on väkeväin kilpi lyöty maahan, Saulin kilpi, niinkuin ei hän olisikaan ollut öljyllä voideltu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Jonatanin joutsi ei harhaillut tapettuin verestä ja voimallisten lihavuudesta, ja Saulin miekka ei palajanut tyhjänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul ja Jonatan, rakkaat ja suloiset eläissänsä, ei ole myös kuollessansa eroitetut: liukkaammat kuin kotka ja väkevämmät kuin jalopeurat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Te Israelin tyttäret, itkekäät Saulia, joka teidän vaatetti tulipunaisilla koriasti ja kaunisti teidän vaatteenne kultaisella kaunistuksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Kuinka sankarit ovat langenneet sodassa? Jonatan on myös tapettu sinun kukkuloillas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Minä suren suuresti sinun tähtes, minun veljeni Jonatan. Sinä olit minulle juuri rakas: sinun rakkautes oli suurempi minulle kuin vaimoin rakkaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Kuinka ovat sankarit langenneet, ja sota-aseet tulleet pois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Sittenkuin nämä olivat tapahtuneet, kysyi David Herralta, sanoen: menenkö minä johonkuhun Juudan kaupungeista? Ja Herra sanoi hänelle: mene. David sanoi: kuhunka minun pitää menemän? Hän sanoi: Hebroniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Niin David meni sinne ja kaksi hänen emäntäänsä, Ahinoam Jisreeliläinen ja Abigail Nabalin emäntä Karmelista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Niin myös miehet, jotka olivat hänen kanssansa, vei David myötänsä jokaisen huoneinensa. Ja he asuivat Hebronin kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Ja Juudan miehet tulivat ja voitelivat siellä Davidin Juudan huoneen kuninkaaksi. Ja kuin Davidille ilmoitettiin Jabeksen miehet Gileadissa haudanneen Saulin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Lähetti hän heille sanan ja antoi sanoa heille: siunatut olette te Herralta, että te tämän laupiuden teitte Saulille teidän herrallenne ja olette haudanneet hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Niin tehköön Herra teille laupiuden ja totuuden, ja minä teen myös teille hyvää, että te tämän teitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Vahvistakaat siis nyt teidän kätenne ja olkaat väkevät; sillä teidän herranne Saul on kuollut, ja Juudan huone on myös minun voidellut hänellensä kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Mutta Abner, Nerin poika, Saulin sodanpäämies, otti Isbosetin Saulin pojan, ja vei hänen Mahanaimiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'Ja asetti hänen Gileadin, Assurin, Jisreelin, Ephraimin, BenJaminin ja kaiken Israelin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Ja Isboset Saulin poika oli neljänkymmenen ajastaikainen, kuin hän tuli Israelin kuninkaaksi, ja hallitsi kaksi ajastaikaa; ainoastaan Juudan huone piti Davidin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Ja se aika, jonka David oli Hebronissa Juudan huoneen kuninkaana, oli seitsemän ajastaikaa ja kuusi kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Ja Abner Nerin poika läksi ulos Isbosetin Saulin pojan palveliain kanssa Mahanaimista Gibeoniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Ja Joab, Zerujan poika, ja Davidin palveliat läksivät ulos, ja he kohtasivat toisensa Gibeonin lammikon tykönä, ja seisoivat toinen toistansa vastaan, nämät tällä puolella ja toiset toisella puolella lammikkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Ja Abner sanoi Joabille: nouskaan nuorukaiset meidän eteemme leikitsemään. Joab sanoi: tehkään niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Niin he nousivat ja kävivät kaksitoistakymmentä BenJaminin luvusta Isbosetin Saulin pojan puolelta, ja kaksitoistakymmentä Davidin palvelioista edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Ja jokainen heistä otti toinen toisensa kiinni kaulasta, ja pistivät miekkansa kylkiin, ja lankesivat toinen toisensa kanssa maahan. Siitä kutsutaan se paikka Helkat-Hatsurim, joka on Gibeonissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Ja sangen kova sota nousi sinä päivänä; mutta Abner ja Israelin miehet lyötiin Davidin palvelioilta takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Ja kolme ZeruJan poikaa oli siellä: Joab, Abisai ja Asahel; mutta Asahel oli nopia juoksemaan, niinkuin metsävuohi kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Hän ajoi Abneria takaa, ja ei poikennut oikialle eikä vasemmalle puolelle ajamasta Abneria takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Niin Abner katsoi taaksensa ja sanoi: etkö sinä ole Asahel? Hän sanoi: olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Ja Abner sanoi: pakene minun tyköäni oikialle eli vasemmalle puolelle, ja käsitä sinulles yksi noista nuorukaisista, ja ota sen ase. Mutta Asahel ei tahtonut luopua hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Niin Abner taas puhui Asahelille: pakene minun takaani: miksis tahdot minua lyömään sinuas? ja kuinka minä sitte tohdin nostaa kasvoni Joabin sinun veljes edessä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mutta hän ei paennut; ja Abner pisti häntä takamaisella puolella keihäästä hänen vatsaansa, niin että keihäs kävi takaa ulos, ja hän lankesi siihen ja kuoli hänen eteensä. Ja jokainen, joka siihen paikkaan tuli, kussa Asahel kaatunut ja kuolleena oli, seisahti siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Mutta Joab ja Abisai ajoivat Abneria takaa siihen asti kuin päivä laski. Ja kuin he tulivat Amman kukkulalle, joka on Gian tykönä, Gibeonin korven tiellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Silloin tulivat BenJaminin lapset Abnerin takaa kokoon ja kokosivat itsensä yhteen joukkoon, ja seisahtivat mäen kukkulalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Ja Abner huusi Joabia ja sanoi: pitääkö miekan syömän ilman lakkaamata? Etkös tiedä, että siitä tulee enempi katkeruutta? Kuinka kauvan et sinä tahdo sanoa kansalle, että he lakkaisivat vainoomasta veljiänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Joab vastasi: niin totta kuin Jumala elää, jos sinä olisit (ennen) niin sanonut, niin olis kansa tänäpänä jo varhain lakannut vainoomasta kukin veljeänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Ja Joab puhalsi torveen, ja kaikki kansa seisahti alallensa, ja ei enää ajaneet Israelia takaa eikä myös enää sotineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Mutta Abner ja hänen miehensä kävivät kaiken yötä lakialla kedolla ja menivät Jordanin ylitse, vaelsivat kaiken Bitronin lävitse ja tulivat Mahanaimiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Ja Joab käänsi itsensä Abnerista ja kokosi kaiken kansan; ja siinä kaivattiin Davidin palvelioista yhdeksäntoistakymmentä miestä ja Asahel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Mutta Davidin palveliat olivat lyöneet BenJaminilta ja niistä miehistä, jotka olivat Abnerin kanssa, kolmesataa ja kuusikymmentä miestä, jotka kuolivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Ja he ottivat Asahelin ja hautasivat Betlehemiin, hänen isänsä hautaan; ja Joab kävi miehinensä kaiken sen yön ja tuli päivän valjetessa Hebroniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Ja pitkällinen sota oli Saulin huoneen ja Davidin huoneen vaiheella; mutta David kasvoi ja menestyi, ja Saulin huone hävisi ja väheni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Ja Davidille syntyi lapsia Hebronissa; hänen esikoisensa oli Amnon Ahinoamista Jisreeliläisestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Toinen Kileab Abigailista Nabalin emännästä, joka oli Karmelista; kolmas Absalom Maakan poika kuninkaan Talmain tyttären Gessurista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Neljäs Adonia Haggitin poika; viides Sephatja Abitalin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Kuudes Jitream Eglasta Davidin emännästä; nämä syntyivät Davidille Hebronissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Kuin sota oli Saulin huoneeen ja Davidin huoneen vaiheella, vahvisti Abner itsensä Saulin huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Ja Saulilla oli ollut jalkavaimo, Ritspa nimeltä, Aijan tytär, ja (Isboset) sanoi Abnerille: miksis olet mennyt isäni jalkavaimon tykö?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Niin Abner vihastui suuresti Isbosetin sanoista ja sanoi: olenko minä koiran pää, joka Juudaa vastaan tein tänäpänä laupiuden sinun isäs Saulin huoneelle, ja hänen veljillensä ja ystävillensä, ja en ole antanut sinua Davidin käsiin! ja sinä soimaat minua tänäpänä vaimon tähden pahantekiäksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Jumala tehköön Abnerin kanssa sen ja sen, jos minä en tee, niinkuin Herra on vannonut Davidille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Että minä otan kuninkaan valtakunnan Saulin huoneesta pois, ja ylennän Davidin istuimen Israelin ja Juudan ylitse, Danista Bersebaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Ja ei hän taitanut Abneria enää vastata yhtään sanaa; sillä hän pelkäsi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Ja Abner lähetti sanansaattajat edellänsä Davidin tykö, sanoen: kenenkä maa oma on? ja sanoi: tee liitto minun kanssani, ja katso, minun käteni on sinun kanssas, kääntämään kaikkea Israelia sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Hän sanoi: oikein, minä teen liiton sinun kanssas; mutta yhtä anon minä sinulta, sanoen: ei pidä sinun tuleman minun näkyviini ennen kuin sinä tuot Mikalin Saulin tyttären minun tyköni, tullessas katsomaan kasvojani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Lähetti myös David sanansaattajat Isbosetin Saulin pojan tykö ja antoi hänelle sanoa: anna minulle minun emäntäni Mikal, jonka minä kihlasin minulleni sadalla Philistealaisten esinahalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Isboset lähetti matkaan ja antoi ottaa hänen mieheltänsä Paltielilta Laiksen pojalta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Ja hänen miehensä meni hänen kanssansa, hän kävi ja itki hänen jälissänsä hamaan Bahurimiin asti. Niin sanoi Abner hänelle: palaja ja mene matkaas. Ja hän palasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Ja Abner puhui Israelin vanhimmille ja sanoi: te olette jo kauvan aikaa halunneet Davidia kuninkaaksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Niin tehkäät nyt se; sillä Herra on sanonut Davidista; minä vapahdan minun kansani Israelin palveliani Davidin käden kautta Philistealaisten kädestä ja kaikkein heidän vihollistensa kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Puhui myös Abner BenJaminin korvain kuullen, ja meni myös puhumaan Davidin korville Hebroniin kaikkia mikä Israelille ja kaikelle BenJaminin huoneelle kelpasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Kuin Abner tuli Davidin tykö Hebroniin ja kaksikymmentä miestä hänen kanssansa, teki David pidot Abnerille ja niille miehille, jotka hänen kanssansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Ja Abner sanoi Davidille: minä nousen ja menen kokoomaan kaiken Israelin herrani kuninkaan tykö, että he tekisivät liiton sinun kanssas, ja sinä olisit kuningas niinkuin sinun sielus halajaa. Niin David päästi Abnerin menemään rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Ja katso, Davidin palveliat ja Joab tulivat sotaväen tyköä ja toivat kanssansa suuren saaliin; mutta Abner ei ollut silloin Davidin tykönä Hebronissa, sillä hän oli päästänyt hänen menemään rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Kuin Joab ja kaikki sotajoukko olivat tulleet, sanottiin Joabille, sanoen: Abner Nerin poika on tullut kuninkaan tykö, ja hän on päästänyt hänet rauhassa menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Niin meni Joab kuninkaan tykö ja sanoi: mitäs olet tehnyt? Katso, Abner on tullut sinun tykös: miksis olet hänen päästänyt vapaasti menemään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Etkös tunne Abneria Nerin poikaa? Hän on tullut sinua pettämään tiedustellaksensa ulos- ja sisällekäymistäs ja koetellaksensa kaikkia, mitäs teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Ja kuin Joab läksi Davidin tyköä, lähetti hän sanansaattajat Abnerin perään, ja he toivat hänen Borhasirasta; ja ei David siitä mitään tietänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Kuin Abner tuli Hebroniin jälleen, vei Joab hänet keskelle porttia puhutellaksensa häntä erinänsä, ja pisti siellä häntä vatsaan, niin että hän kuoli, veljensä Asahelin veren tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Kuin David sai sen tietää, sanoi hän: minä olen viatoin ja minun valtakuntani Herran edessä ijankaikkisesti Abnerin Nerin pojan verestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Mutta tulkoon se Joabin pään päälle ja kaiken hänen isänsä huoneen, ja älköön puuttuko Joabin huoneessa se, jolla juoksu ja spitali on, ja joka sauvalla käy ja miekalla kaatuu, ja jolta leipä puuttuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Ja näin tappoivat Joab ja hänen veljensä Abisai Abnerin, että hän löi kuoliaaksi Asahelin heidän veljensä sodassa Gibeonin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Mutta David sanoi Joabille ja kaikelle kansalle, jotka olivat hänen kanssansa: reväiskää vaatteenne rikki, ja puettakaat teitänne säkeillä, ja valittakaat Abnerin tähden. Ja kuningas David kävi paarien perässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Ja he hautasivat Abnerin Hebronissa, ja kuningas koroitti äänensä ja itki Abnerin haudan tykönä; itki myös kaikki kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Ja kuningas valitti Abneria ja sanoi: onko Abner kuollut, niinkuin tyhmä kuolee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Sinun kätes ei olleet sidotut, sinun jalkas ei olleet vaskikahleissa: sinä olet kaatunut, niinkuin se, joka pahantekiäin edessä lankee. Ja kaikki kansa itki vielä enemmin häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Ja kaikki kansa tuli Davidin kanssa rualle, kuin vielä valkia päivä oli; ja David vannoi ja sanoi: Jumala tehköön minulle sen ja sen, jos minä leipää taikka jotakin muuta maistan, ennenkuin aurinko laskee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Ja kaikki kansa ymmärsi sen, ja se kelpasi heille, ja kaikki se hyvä minkä kuningas oli tehnyt kaiken kansan silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Ja kaikki kansa ja koko Israel ymmärsivät sinä päivänä, ettei se ollut kuninkaalta, että Abner Nerin poika oli tapettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Ja kuningas sanoi palvelioillensa: ettekö te tiedä, että tänäpänä on yksi päämies, ja tosin suuri mies kaatunut Israelissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Ja minä olen vielä heikko ja voideltu kuningas, mutta ne miehet ZeruJan pojat ovat kovemmat minua: Herra maksakoon sille, joka pahaa tekee, hänen pahuutensa jälkeen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Kuin Saulin poika kuuli Abnerin kuolleeksi Hebronissa, väsyivät hänen kätensä, ja koko Israel hämmästyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Ja Saulin pojalla oli kaksi sotaväen päämiestä, toisen nimi oli Baana ja toisen Rekab, Rimmonin Berotilaisen pojat, BenJaminin lapsista; sillä Berot oli myös luettu BenJaminin sukukuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Ja Berotilaiset olivat paenneet Gittaimiin, ja olivat siellä muukalaisina tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Oli myös Jonatanilla Saulin pojalla yksi poika, joka oli saattamatoin jaloista, ja oli jo viiden ajastaikainen, kuin sanoma Saulista ja Jonatanista tuli Jisreelistä; ja hänen imettäjänsä otti hänen ja pakeni. Ja koska hän kiiruusti pakeni, lankesi hän ja tuli saattamattomaksi, ja hänen nimensä oli MephiBoset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Niin menivät Berotilaisen Rimmonin pojat Rekab ja Baana, ja tulivat Isbosetin huoneesen, kuin päivä oli palavimmallansa; ja hän lepäsi vuoteessansa puolipäivän aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Ja he tulivat keskelle huonetta nisuja ottamaan ja pistivät häntä vatsaan; ja Rekab ja Baana hänen veljensä pakenivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Sillä koska he huoneesen tulivat, lepäsi hän vuoteessansa, makaushuoneessansa. Ja he pistivät hänen kuoliaaksi, ja hakkasivat hänen päänsä pois, ja ottivat hänen päänsä ja menivät pois lakian kedon tien kautta koko sen yön,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'Ja toivat Isbosetin pään Davidille, joka oli Hebronissa, ja sanoivat kuninkaalle: katso, tässä on Isbosetin Saulin pojan pää, sinun vihollises, joka sinun sielus perään seisoi: ja Herra on tänäpänä kostanut Saulille ja hänen siemenellensä herrani kuninkaan puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Niin vastasi David Rekabia ja Baanaa, hänen veljeänsä, Rimmnonin Berotilaisen poikia, ja sanoi heille: niin totta kuin Herra elää, joka minun sieluni on vapahtanut kaikesta surusta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Sen joka minulle ilmoitti ja sanoi: Saul on kuollut, ja luuli itsensä hyväksi sanansaattajaksi, sen minä otin kiinni ja tapoin Ziklagissa, jolle minun piti antaman sanansaattajan palkan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Ja nämät jumalattomat miehet ovat tappaneet hurskaan miehen huoneessansa ja omassa vuoteessansa: eikö siis minun pitäisi nyt vaatiman hänen vertansa teidän kädestänne ja ottaman teitä pois maan päältä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Ja David käski nuorukaisiansa, ja he tappoivat heidät, ja hakkasivat kädet ja jalat poikki, ja ripustivat heidät lammikon tykö Hebronissa. Mutta Isbosetin pään he ottivat ja hautasivat Abnerin hautaan Hebroniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Ja Israelin kaikki sukukunnat tulivat Davidin tykö Hebroniin, ja puhuivat sanoen: katso, sinun luus ja lihas me olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Ja aina ennen, kuin Saul oli meidän kuninkaamme, johdatit sinä Israelin ulos ja sisälle, ja Herra on sinulle sanonut: sinun pitää minun kansaani Israelia kaitseman ja Israelin päämiehen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Ja kaikki kansan vanhimmat Israelista tulivat kuninkaan tykö Hebroniin, ja kuningas David teki heidän kanssansa liiton Herran edessä Hebronissa; ja he voitelivat Davidin Israelin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Ja David oli kolmenkymmenen ajastaikainen tullessansa kuninkaaksi, ja hän hallitsi neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Hebronissa hän hallitsi Juudaa seitsemän vuotta ja kuusi kuukautta; mutta Jerusalemissa hän hallitsi kaikkea Israelia ja Juudaa kolmeneljättäkymmentä vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Ja kuningas meni ja hänen miehensä Jerusalemiin Jebusilaisia vastaan, jotka maalla asuivat. Ja he sanoivat Davidille: ei sinun pidä tänne tuleman, vaan sokiat ja ontuvat pitää sinun täältä pois ajaman; ja he ajattelivat, ettei Davidin pitänyt sinne tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Mutta David voitti Zionin linnan, se on Davidin kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Ja sinä päivänä sanoi David: jos joku lyö Jebusilaiset, ja tarttuu heidän rästäänsä alaisiin ja lyö sokiat ja ontuvat, joita Davidin sielu vihaa (hänen pitää pään ja ylimmäisen oleman); josta heillä on sananlasku: ei yhtään sokiaa ja ontuvaa päästetä huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Ja David asui linnassa ja kutsui sen Davidin kaupungiksi; ja David rakensi sen ympäri Millosta, niin myös sisällisen puolen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Ja David menestyi ja enentyi, ja Herra Jumala Zebaot oli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Niin Hiram, Tyron kuningas, lähetti sanansaattajat Davidin tykö, ja sedripuita, ja puuseppiä, ja seinäkivien hakkaajia, jotka rakensivat Davidin huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Ja David ymmärsi Herran vahvistaneeksi hänen Israelin kuninkaaksi ja korottaneeksi hänen valtakuntansa, kansansa Israelin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Niin David otti Jerusalemista vielä usiampia jalkavaimoja ja emäntiä, sittekuin hän tuli Hebronista. Ja Davidille syntyi vielä poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Ja nämät ovat heidän nimensä, jotka hänelle Jerusalemissa syntyivät: Sammua, Sobab, Natan ja Salomo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibhar, Elisua, Nepheg ja Japhia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eliada ja Eliphalet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Ja kuin Philistealaiset kuulivat Davidin voidelluksi Israelin kuninkaaksi, nousivat kaikki Philistealaiset etsimään Davidia. Ja kuin David sen kuuli, niin hän meni linnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Mutta Philistealaiset tulivat ja sioittivat itsensä Rephaimin laaksoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Ja David kysyi Herralta, sanoen: menenkö minä Philistealaisia vastaan? ja annatkos heitä minun käteeni? Ja Herra sanoi Davidille: mene, sillä minä annan tosin Philistealaiset sinun käsiis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Ja David tuli BaalPeratsimiin, ja David löi heidät siinä, ja sanoi: Herra on minun viholliseni eroittanut minun edestäni, niinkuin vesi erkanee toinen toisestansa; siitä kutsutaan se paikka BaalPeratsim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'Ja he jättivät siihen epäjumalansa; mutta David ja hänen väkensä ottivat ne pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Ja Philistealaiset vielä nousivat ja sioittivat itsensä Rephaimin laaksoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Niin David kysyi Herralta, ja hän vastasi: ei sinun pidä menemän alas, mutta tule takaa heidän ympärinsä, ettäs tulet heitä vastaan fikunapuiden kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Ja kuin sinä kuulet fikunapuun latvat kahisevan, niin kulje; sillä Herra on silloin lähtenyt ulos sinun etees, lyömään Phlistealaisten sotajoukkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'David teki niinkuin Herra oli hänelle käskenyt, ja löi Philistealaiset hamasta Gebasta siihenasti kuin Gaseriin tullaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Ja David taas kokosi kaikki valitut miehet Israelista, kolmekymmentä tuhatta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Ja David nousi ja meni, ja kaikki kansa kuin hänen tykönänsä oli Juudan asuvaisista, tuomaan sieltä Jumalan arkkia, joka kutsutaan Herran Zebaotin nimi, joka asuu Kerubimin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Ja he panivat Jumalan arkin uuden vaunun päälle ja toivat sen AbiNadabin huoneesta, joka asui Gibeassa. Mutta Ussa ja Ahjo, AbiNadabin pojat ajoivat sitä uutta vaunua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Niin he toivat sen AbiNadabin huoneesta, joka oli Gibeassa, Jumalan arkin kanssa; ja Ahjo kävi arkin edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Niin David ja kaikki Israelin huone soittivat Herran edessä kaikkinaisilla honkaisilla kanteleilla ja harpuilla, psaltareilla, trumpuilla, kulkuisilla ja simpeleillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Ja kuin he tulivat Nahonin riihen tykö, otti Ussa Jumalan arkin ja piteli sitä, sillä härjät menivät sivuin tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Niin Herran viha julmistui Ussan päälle, ja Jumala löi hänen siinä maahan hänen tyhmyytensä tähden, niin että hän kuoli siinä Jumalan arkin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Silloin tuli David murheelliseksi, että Herra niin repäisi Ussan, ja kutsui sen paikan PeretsUssa, tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Ja David pelkäsi Herraa sinä päivänä ja sanoi: kuinka Herran arkki tulisi minun tyköni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Ja ei tahtonut antaa tuoda sitä tykönsä Davidin kaupunkiin, vaan salli kannettaa ObedEdomin Gatilaisen huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Ja Herran arkki viipyi kolme kuukautta ObedEdomin Gatilaisen huoneessa, ja Herra siunasi hänen ja kaiken hänen huoneensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Ja se oli sanottu kuningas Davidille, että Herra oli siunannut ObedEdomin huoneen ja kaiken mitä hänellä oli, Jumalan arkin tähden. Niin meni David ja toi Jumalan arkin ObedEdomin huoneesta Davidin kaupunkiin ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Ja kuin ne, jotka Herran arkkia kantoivat, olivat käyneet kuusi askelta, niin uhrattiin härkä ja lihava lammas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Ja David hyppäsi kaikella voimalla Herran edessä ja hän oli vaatetettu liinaisella päällisvaatteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Ja David ja kaikki Israelin kansa toivat Herran arkin riemulla Ja basunan helinällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Ja kuin Herran arkki joutui Davidin kaupunkiin, katsoi Mikal, Saulin tytär akkunasta ja näki kuningas Davidin hyppäävän kaikella voimallansa Herran edessä, ja hän katsoi hänen ylön sydämessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Ja he toivat Herran arkin sisälle ja panivat sen siallensa keskelle majaa, jonka David oli sille rakentanut. Ja David uhrasi polttouhria ja kiitosuhria Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Ja kuin David oli uhrannut polttouhria ja kiitosuhria, siunasi hän kansan Herran Zebaotin nimeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Ja jakoi kaikelle kansalle ja kaikelle Israelin seurakunnalle, miehille ja vaimoille, jokaiselle kyrsän leipää, ja kappaleen lihaa, ja mitan (viinaa); sitte meni kaikki kansa matkaansa, jokainen huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Ja kuin David palasi siunaamaan huonettansa, meni Mikal, Saulin tytär ulos häntä vastaan ja sanoi: kuinka jalo on ollut Israelin kuningas tänäpänä, joka on itsensä paljastanut palveliainsa piikain edessä, niinkuin irstaat ihmiset paljastavat itsensä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Mutta David sanoi Mikalille: Herran edessä joka minun valinnut on pikemmin kuin sinun isäs ja kaiken hänen huoneensa, ja on käskenyt minun olla Herran kansan Israelin päämiehenä: ja Herran edessä minä tahdon iloita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'Ja minä tahdon vielä halvempi olla ja nöyrä minun silmäini edessä: ja minä kunnioitetaan niiden piikain kanssa, joistas puhunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Ja Mikalilla, Saulin tyttärellä ei ollut yhtään lasta kuolemapäiväänsä asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Ja kuin kuningas istui huoneessansa, ja Herra oli hänelle antanut levon kaikilta hänen vihollisiltansa, ympäristöllä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Sanoi kuningas propheta Natanille: katso, minä asun sedripuisessa huoneessa, ja Jumalan arkki asuu vaatetten keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Natan sanoi kuninkaalle: mene ja tee kaikki mitä sydämessäs on, sillä Herra on sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Mutta tapahtui sinä yönä, että Herran sana tuli Natan prophetan tykö ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Mene ja sano palvelialleni Davidille: Näin sanoo Herra: sinäkö minulle huoneen rakennat asuakseni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Sillä en minä ole asunut yhdessäkään huoneessa siitä päivästä, jona minä Israelin lapset johdatin Egyptistä, tähän päivään asti; vaan minä olen vaeltanut majoissa ja Tabernaklissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Kuhunka ikänä minä kaikkein Israelin lasten kanssa vaelsin, olenko minä ikänä puhunut jonkun kanssa Israelin suvusta, jolle minä olen käskenyt kaita minun kansaani Israelia ja sanonut: miksi ette ole minulle rakentaneet sedripuista huonetta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Sano siis nyt palvelialleni Davidille: Näin sanoo Herra Zebaot: minä olen ottanut sinun lampurista kansani Israelin päämieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Ja minä olen sinun kanssas ollut, kussa ikänä sinä olet käynyt, ja olen hävittänyt kaikki vihollises sinun edestäs, ja olen sinulle antanut suuren nimen niiden suurten nimien jälkeen kuin ovat maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Ja minä asetan Israelille minun kansalleni sian ja istutan hänen siinä asumaan, ettei hän enää kulkiana olisi; ja jumalattomat ei pidä häntä enää niinkuin ennen vaivaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Ja siitä päivästä, jona minä asetin tuomarit Israelille minun kansalleni, annoin minä sinulle levon kaikilta vihamiehiltäs; ja Herra ilmoittaa sinulle, että Herra sinulle huoneen tehdä tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Sittekuin sinun aikas on täytetty ja sinä lepäät isäis kanssa, herätän minä sinun siemenes sinun jälkees, joka sinun ruumiistas tuleva on: ja minä vahvistan hänen valtakuntansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Ja hän rakentaa minun nimelleni huoneen, ja minä vahvistan hänen vaItakuntansa istuimen ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Minä olen hänen isänsä, ja hän on minun poikani: kuin hän väärin tekee, rankaisen minä häntä ihmisen vitsalla ja ihmisten lasten haavoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Vaan minun laupiuteni ei pidä hänestä eriämän, niinkuin minä sen Saulista eroitin, jonka minä otin sinun edestäs pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Mutta sinun huonees ja valtakuntas on pysyvä sinun edessäs ijankaikkisesti, ja sinun istuimes pitää vahva oleman ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Kaikkein näiden sanain jälkeen ja kaiken tämän näyn jälkeen puhui Natan Davidille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Niin tuli kuningas David ja pysähtyi Herran eteen, ja sanoi: kuka olen minä, Herra, Herra, ja mikä on minun huoneeni, ettäs minun tähän asti saattanut olet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Ja olet sen vielä vähäksi lukenut, Herra, Herra, mutta olet myös puhunut palvelias huoneelle kaukaisista asioista: ja tämä on sen ihmisen laki, joka on Herra Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Ja mitä Davidin pitää enää sinun kanssas puhuman? sillä sinä tunnet palvelias, Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Sinun sanas tähden ja sydämes jälkeen olet sinä nämät suuret asiat tehnyt, ilmoittaakses palvelialles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Sentähden olet sinä suuresti ylistetty, Herra Jumala! sillä ei yhtään ole sinun vertaas, ja ei ole yhtään Jumalaa paitsi sinua, kaiken sen jälkeen, kuin me olemme korvillamme kuulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Ja kuka on niinkuin sinun kansas, niinkuin Israel, yksi kansa maan päällä, jota Jumala on mennyt vapahtamaan kansaksensa, ja toimittamaan itsellensä nimeä ja tekemään senkaltaisia suuria ja hirmuisia asioita sinun maallas, kansas edessä, jonka sinä sinulles vapahdit Egyptistä, pakanain ja heidän jumalainsa seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Ja sinä olet vahvistanut sinulles Israelin sinun kansakses ijankaikkisesti, ja sinä Herra olet heidän Jumalaksensa tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Niin vahvista siis, Herra Jumala, se sana ijankaikkisesti, jonkas palveliastas ja hänen huoneestansa puhunut olet, ja tee niin kuin puhunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Niin sinun nimes tulee suureksi iankaikkisesta, että sanotaan: Herra Zebaot on Israelin Jumala, ja sinun palvelias Davidin huone on pysyväinen sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Sillä sinä Herra Zebaot Israelin Jumala olet avannut palvelias korvat, ja sanonut: minä rakennan sinulle huoneen; sentähden löysi palvelias sydämessänsä, että hän tämän rukouksen sinun tykönäs rukoilis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Sentähden nyt Herra, Herra, sinä olet Jumala, ja sinun sanas ovat totuus: sinä olet tämän hyvän puhunut palvelialles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Niin rupee nyt siunaamaan palvelias huonetta, että se olis ijankaikkisesti sinun edessäs; sillä sinä Herra, Herra, olet sen puhunut, niin siunattakoon sinun siunauksellas palvelias huone ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Ja sitte tapahtui, että David löi Philistealaiset ja alensi heitä; ja David otti orjuuden suitset Philistealaisten kädestä');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Ja hän löi Moabilaiset, pani heidät maahan makaamaan ja mittasi heitä nuoralla: ja hän mittasi kaksi nuoraa tapettavaksi ja yhden nuoran elämään jätettäväksi, ja Moabilaiset tulivat Davidin palveliaksi, ja he kantoivat hänelle lahjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David löi myös HadadEserin, Rehobin pojan Zoban kuninkaan, hänen mennessä asettamaan kättänsä Euphratin virran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Ja David otti heistä tuhannen ja seitsemänsataa hevosmiestä ja kaksikymmentä tuhatta jalkamiestä kiinni, ja raiskasi kaikki vaunuhevoset, ja sata vaunua jätti heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Niin tulivat Syrialaiset Damaskusta auttamaan HadadEseriä, Zoban kuningasta; ja David löi Syrialaisista kaksikolmattakymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Ja David asetti vartiat Syrian Damaskuun. Näin tulivat Syrialaiset Davidin palveliaksi ja kantoivat hänelle lahjoja; sillä Herra autti Davidia, kuhunka ikänä hän meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Ja David otti HadadEserin palveliain kultaiset kilvet ja vei ne Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Mutta Betasta ja Berotaista, HadadEserin kaupungeista, otti kuningas David ylen paljon vaskea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Kuin Toi, Hamatin kuningas kuuli Davidin lyöneen kaikki HadadEserin sotaväen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Lähetti hän poikansa Joramin kuningas Davidin tykö, tervehtimään häntä ystävällisesti ja siunaamaan häntä, että hän soti HadadEserin kanssa ja löi hänen; sillä Toi soti HadadEserin kanssa; ja hänen kädessänsä olivat hopiaiset, kultaiset ja vaskiset astiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Ne myös kuningas David pyhitti Herralle, sen hopian ja kullan kanssa, jonka hän pyhitti Herralle kaikilta pakanoilta, jotka hän vaatinut oli allensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Syriasta ja Moabista, Ammonin lapsilta, Philistealaisilta, Amalekilaisilta, niin myös HadadEserin, Rehobin pojan, Zoban kuninkaan saaliista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Ja David teki itsensä kuuluisaksi, kuin hän palasi lyömästä Syrialaisia Suolalaaksossa, kahdeksantoistakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Ja hän asetti vartiat koko Edomiin, ja koko Edom oli Davidin alla; sillä Herra autti Davidia, kuhunka ikänä hän meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Niin oli David kaiken Israelin kuningas, ja hän toimitti lain ja oikeuden kaikelle kansallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Ja Joab, ZeruJan poika oli sotajoukon päällä, mutta Josaphat, Ahiludin poika oli kansleri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Zadok, Ahitobin poika ja Ahimelek, AbJatarin poika olivat papit; Seraja oli kirjoittaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, Jojadan poika oli Kretin ja Pletin päällä; ja Davidin pojat olivat papit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Ja David sanoi: olleeko joku vielä jäänyt Saulin huoneesta, tehdäkseni laupiuden Jonatanin tähden hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Niin oli palvelia Saulin huoneesta Ziba nimeltä, sen kutsuivat Davidin tykö. Ja kuningas sanoi hänelle: oletkos Ziba? Hän sanoi: olen, sinun palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Kuningas sanoi: onko vielä joku mies Saulin huoneesta, että minä Jumalan laupiuden tekisin hänelle? Ziba sanoi kuninkaalle: vielä on siellä Jonatanin poika, rampa jaloista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Kuningas sanoi hänelle: kussa hän on? Ziba sanoi kuninkaalle: katso, hän on Lodabarissa, Makirin, Ammielin pojan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Niin kuningas David lähetti ja antoi tuoda hänen Lodabarista, Makirin Ammielin pojan huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Kuin MephiBoset, Saulin pojan Jonatanin poika tuli Davidin tykö, lankesi hän kasvoillensa ja kumarsi. Ja David sanoi: MephiBoset! Hän vastasi: tässä olen, sinun palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'David sanoi hänelle: älä pelkää; sillä minä totisesti teen laupiuden sinun kanssas Jonatanin sinun isäs tähden, ja minä annan sinulle kaikki sinun isäs Saulin pellot jälleen, ja sinä syöt jokapäivä leipää minun pöydältäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Hän kumarsi ja sanoi: kuka olen minä sinun palvelias, ettäs käänsit sinus kuolleen koiran puoleen, niinkuin minä olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Niin kutsui kuningas Ziban, Saulin palvelian, ja sanoi hänelle: minä olen antanut sinun herras pojalle kaiken sen mikä Saulin oma on ollut ja koko hänen huoneensa oma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Niin pitää sinun, ja sinun lapses, ja palvelias viljelemän hänen peltojansa ja korjaaman herras pojalle leiväksi ja ravinnoksi. Mutta MephiBoset sinun herras poika syö jokapäivä leipää minun pöydältäni. Ja Ziballa oli viisitoistakymmentä poikaa ja kaksikymmentä palveliaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Ja Ziba sanoi kuninkaalle: kaikki mitä minun herrani kuningas on palveliallensa käskenyt, tekee palvelias; ja MephiBoset syököön minun pöydältäni, niinkuin yksi kuninkaan lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Ja MephiBosetilla oli yksi vähä poika nimeltä Miika; mutta kaikki, jotka Ziban huoneesta olivat, olivat MephiBosetin palveliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Ja MephiBoset asui Jerusalemissa; sillä hän söi jokapäivä kuninkaan pöydältä; ja hän ontui molemmista jaloistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Sitte tapahtui, että Ammonin lasten kuningas kuoli, ja hänen poikansa Hanun hallitsi hänen siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Niin sanoi David: minä teen laupiuden Hanunin, Nahaksen pojan kanssa, niinkuin hänen isänsä teki laupiuden minun kanssani; ja lähetti palveliansa lohduttamaan häntä hänen isänsä tähden. Kuin Davidin palvelijat tulivat Ammonin lasten maahan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Niin sanoivat Ammonin lasten ylimmäiset herrallensa Hanunille: luuletkos Davidin kunnioittavan sinun isääs sinun silmäis edessä, että hän on lähettänyt lohduttajat sinun tykös? Etkös luule hänen lähettäneen palvelioitansa kaupunkia tutkistelemaan ja vakoomaan ja hävittämään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Silloin otti Hanun Davidin palveliat, ja ajeli puolen heidän partaansa, ja leikkasi puolen heidän vaatteistansa liki suolivyöhön asti, ja laski heidät menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Kuin se Davidille ilmoitettiin, lähetti hän heitä vastaan, sillä miehet olivat suuresti pilkatut; ja kuningas antoi heille sanottaa: olkaat Jerihossa siihen asti, kuin teidän partanne kasvaa, ja sitte tulkaat jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Kuin Ammonin lapset näkivät itsensä haisevan Davidin edessä, lähettivät he ja palkkasivat Syrialaiset Rehobin huoneesta ja Zobasta, kaksikymmentä tuhatta jalkamiestä, ja kuningas Maakalta tuhannen miestä, ja Istobilta kaksitoista kymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Kuin David sen kuuli, lähetti hän Joabin koko urhoollisen sotajoukon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Ja Ammonin lapset läksivät ja sääsivät sodan kaupungin portin eteen. Mutta Syrialaiset Zobasta, Rehobista, Istobista ja Maakasta olivat erinänsä kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Kuin Joab näki sodan asetetuksi vastaansa edestä ja takaa, valitsi hän kaikista Israelin parhaista miehistä, ja asetti itsensä Syrialaisia vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Ja muun väen antoi hän veljensä Abisain käden alle, joka asetti itsensä Ammonin lapsia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Ja hän sanoi: jos Syrialaiset tulevat minua voimallisemmaksi, niin tule minun avukseni; jos Ammonin lapset joutuvat sinua voimallisemmaksi, niin minä tulen sinun apuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Ole miehuullinen, ja olkaamme vahvat meidän kansamme edestä ja meidän Jumalamme kaupunkein edestä; mutta Herra tehköön niinkuin hänelle kelvollinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Ja Joab läksi matkaan ja se väki joka hänen kanssansa oli, sotimaan Syrialaisia vastaan; ja he pakenivat hänen edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Ja kuin Ammonin lapset näkivät Syrialaiset pakenevan, pakenivat he myös Abisain edestä ja menivät kaupunkiin. Niin palasi Joab Ammonin lasten tyköä ja tuli Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Ja kuin Syrialaiset näkivät itsensä Israelilta lyödyksi, kokoontuivat he yhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'Ja HadadEser lähetti ja tuotti Syrialaiset toiselle puolelle veden, ja he tulivat Helamiin; ja Sobak, HadadEserin sodanpäämies meni heidän edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Kuin se Davidille ilmoitettiin, kokosi hän kaiken Israelin, ja meni Jordanin ylitse, ja tuli Helamiin; ja Syrialaiset asettivat itsensä Davidia vastaan sotimaan hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Mutta Syrialaiset pakenivat Israelin edestä, ja David löi heistä seitsemänsataa vaunua ja neljäkymmentä tuhatta ratsasmiestä, löi myös Sobakin sodanpäämiehen, että hän siinä kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Kuin kaikki ne kuninkaat, jotka olivat HadadEserin alla, näkivät itsensä lyödyksi Israelilta, tekivät he Israelin kanssa rauhan, ja olivat heille alamaiset; ja Syrialaiset ei uskaltaneet Ammonin lapsia enää auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Ja kuin se aika joutui vuodesta, jolla kuningasten tapa oli sotiin mennä, lähetti David Joabin ja palveliansa hänen kanssansa ja kaiken Israelin, hukuttamaan Ammonin lapsia, ja he piirittivät Rabban; mutta David jäi Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Ja tapahtui, että David ehtoopuolella nousi vuoteeltansa, ja käyskenteli kuninkaan huoneen katon päällä, ja näki katon päältä vaimon pesevän itsiänsä; ja vaimo oli sangen ihana näkyänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Ja David lähetti ja antoi kysyä vaimoa, ja sanoi: eikö tämä ole BatSeba, Eliamin tytär, Hetiläisen Urian emäntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Ja David lähetti sanansaattajat ja antoi tuoda hänen. Ja kuin hän tuli hänen tykönsä, makasi hän hänen kanssansa; mutta hän puhdisti itsensä saastaisuudestansa, ja palasi huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Ja vaimo tuli raskaaksi, ja lähetti ja ilmoitti sen Davidille, ja sanoi: minä olen raskaaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Niin lähetti David Joabin tykö, sanoen: lähetä minun tyköni Uria Hetiläinen. Ja Joab lähetti Urian Davidin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Ja kuin Uria tuli hänen tykönsä, kysyi David: jos Joab ja kansa rauhassa olisivat ja jos sota menestyis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Ja David sanoi Urialle: mene huoneeses ja pese jalkas. Ja kuin Uria läksi kuninkaan huoneesta, seurasi häntä kohta kuninkaan herkku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Ja Uria pani levätä kuninkaan huoneen oven eteen, kussa kaikki hänen herransa palveliat makasivat, ja ei mennyt huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Kuin Davidille sanottiin: ei Uria ole mennyt huoneesensa, sanoi David Urialle: etkös tullut matkasta? miksi et mennyt huoneeses?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Mutta Uria sanoi Davidille: arkki, ja Israel ja Juuda makaavat majoissa, herrani Joab ja herrani palveliat makaavat kedolla, ja minä menisin huoneesen syömään, juomaan ja makaamaan emäntäni tykönä? Niin totta kuin sinä elät ja sinun sielus elää, en tee minä sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'David sanoi Urialle: niin ole vielä tämä päivä tässä, huomenna lasken minä sinun menemään. Niin Uria oli sen päivän Jerusalemissa ja toisen päivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Ja David kutsui hänen kanssansa syömään ja juomaan, ja juovutti hänen. Ja ehtoona läksi hän ulos ja pani vuoteesensa levätä herransa palveliain kanssa, ja ei mennyt huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Huomeneltain kirjoitti David Joabin tykö kirjan, ja lähetti sen Urian myötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Ja hän kirjoitti kirjaan sanoen: pankaat Uria kovimman sodan eteen, ja kääntykäät hänen tyköänsä takaperin, että hän lyötäisiin ja kuolis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Kuin Joab oli kaupungin edessä, asetti hän Urian siihen paikkaan, kussa hän väkevimmät sotamiehet tiesi olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Ja kuin miehet läksivät kaupungista ja sotivat Joabia vastaan, kaatuivat muutamat Davidin palvelioista, ja Uria Hetiläinen myös kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Niin Joab lähetti ja antoi sanoa Davidille kaikki sodan menot,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Ja käski sanansaattajalle sanoen: kuin sinä olet puhunut kaikki sodan menot kuninkaalle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Ja jos niin on, että kuningas vihastuu ja sanoo sinulle: miksi te niin lähes kaupunkia astuitte sodalla? Ettekö te tietäneet, että muurin päältä paiskataan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kuka löi Abimelekin Jerubbesetin pojan? Eikö vaimo paiskannut myllynkiven kappaletta muurista hänen päällensä, että hän kuoli Tebetsessä? Miksi te astuitte niin lähes muuria? Niin sano: sinun palvelias Uria Hetiläinen on myös kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Sanansaattaja meni ja tuli ja jutteli Davidille kaikki nämät, joiden tähden Joab hänen lähettänyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Ja sanansaattaja sanoi Davidille: ne miehet voittivat meidät ja tulivat ulos kedolle meidän tykömme; mutta me löimme heidät takaperin kaupungin porttiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Ja ampujat ampuivat muurista sinun palvelloitas ja tappoivat muutamia kuninkaan palvelioita, ja sinun palvelias Uria Hetiläinen on myös kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'David sanoi sanansaattajalle: sano näin Joabille: älä sitä pahakses pane, sillä miekka syö nyt yhden, nyt toisen, vahvista sota kaupunkia vastaan, ettäs kukistaisit sen: ja vahvista sinä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Ja kuin Urian emäntä kuuli miehensä Urian kuolleeksi, murehti hän miestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Sittekuin hän oli murehtinut, lähetti David ja antoi tuoda hänen huoneesensa, ja hän tuli hänen emännäksensä ja synnytti hänelle pojan, mutta se työ, jonka David teki, oli paha Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Ja Herra lähetti Natanin Davidin tykö. Kuin hän tuli hänen tykönsä, sanoi hän hänelle: kaksi miestä oli yhdessä kaupungissa, toinen rikas ja toinen köyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Rikkaalla oli aivan paljo lampaita ja karjaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Mutta köyhällä ei ollut mitään muuta kuin yksi vähä karitsa, jonka hän ostanut oli, ja elättänyt, ja kasvattanut suureksi, ja ravitsi sen tykönänsä lastensa kanssa; joka myös söi hänen leipänsä palasta, ja joi hänen juoma-astiastansa, ja makasi hänen sylissänsä, ja se oli hänelle niinkuin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Mutta kuin rikkaalle miehelle tuli vieras, ei raskinut hän ottaa omista lampaistansa ja karjastansa, valmistaaksensa vieraalle, joka hänen tykönsä tullut oli; mutta otti köyhän miehen lampaan ja valmisti vieraalle, joka hänen tykönsä tullut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Niin Davidin viha julmistui suuresti sitä miestä vastaan, ja hän sanoi Natanille: niin totta kuin Herra elää, se mies on kuoleman lapsi, joka sen teki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Niin myös pitää hänen maksaman neljäkertaisesti sen lampaan, että hän sen tehnyt on, ja ei säästänyt sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Niin sanoi Natan Davidille: sinä olet se mies. Näin sanoo Herra Israelin Jumala: minä olen voidellut sinun Israelin kuninkaaksi ja minä olen pelastanut sinun Saulin kädestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Ja olen antanut sinulle sinun herras huoneen ja hänen emäntänsä sinun syliis, ja olen antanut sinulle Israelin ja Juudan huoneen; ja jos siinä vähä on, niin minä sen lisään sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Miksis katsoit Herran sanan ylön, tehden pahaa hänen silmäinsä edessä? Urian Hetiläisen olet sinä lyönyt miekalla, ja hänen vaimonsa olet sinä ottanut sinulles emännäksi; mutta hänen olet sinä tappanut Ammonin lasten miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Niin ei pidä myös miekan lakkaaman sinun huoneestas ijankaikkisesti; ettäs olet katsonut minun ylön, ja Urian, Hetiläisen, emännän ottanut sinulles emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Näin sanoo Herra: katso, minä herätän pahuuden sinua vastaan omasta huoneestas, ja otan sinun emäntäs sinun silmäis nähden, ja annan ne lähimmäiselles, ja hän makaa sinun emäntäis sivussa valkiana päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Sillä sinä olet sen tehnyt salaisesti; mutta minä teen tämän koko Israelin edessä ja auringon edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Niin sanoi David Natanille: minä olen syntiä tehnyt Herraa vastaan. Natan sanoi Davidille: niin on myös Herra sinun syntis ottanut pois, ei sinun pidä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Mutta ettäs tämän työn kautta saatit Herran viholliset pilkkaamaan, pitää sen pojan, joka sinulle syntynyt on, totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Sitte meni Natan huoneesensa. Mutta Herra löi lapsen, jonka Urian emäntä Davidille synnyttänyt oli, että se sairasti kuolemallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Ja David etsi Jumalaa lapsen tähden: ja David paastosi paljo, ja meni ja makasi yön maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Niin nousivat hänen huoneensa vanhimmat nostamaan häntä maasta; mutta ei hän tahtonut, eikä syönyt leipää heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Seitsemäntenä päivänä kuoli lapsi; ja ei Davidin palveliat tohtineet sanoa hänelle lasta kuolleeksi, sillä he ajattelivat: katso, kuin lapsi vielä eli, puhuimme me hänen kanssansa, ja ei hän kuullut meidän ääntämme, kuinka paljo enemmin hän tulis murheelliseksi,jos me sanoisimme hänelle: lapsi on kuollut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Kuin David näki palveliainsa hiljaksensa puhuvan, ymmärsi hän lapsen kuolleeksi, ja sanoi palvelioillensa: kuoliko lapsi? He sanoivat: kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Ja David nousi maasta, pesi itsensä ja voiteli, ja muutti toiset vaatteet yllensä, ja meni Herran huoneesen ja rukoili, ja tuli kotiansa, ja antoi panna ruokaa eteensä ja söi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Niin sanoivat hänen palveliansa hänelle: mikä se on minkä sinä teet? lapsen eläissä paastosit sinä ja itkit, mutta lapsen kuoltua nouset sinä ja syöt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Hän sanoi: lapsen eläissä minä paastosin ja itkin; sillä minä ajattelin: kuka tietää, jos Herra on minulle armollinen, että lapsi eläis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mutta nyt on se kuollut: mitä minun pitäis vielä paastoaman: taidanko minä hänen enää jällensä tuoda? Minä menen hänen tykönsä, mutta ei hän palaja minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Ja kuin David oli lohduttanut emäntäänsä BatSebaa, meni hän hänen tykönsä ja lepäsi hänen tykönänsä; ja hän synnytti pojan ja hän kutsui hänen nimensä Salomo, ja Herra rakasti häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Ja hän lähetti hänen Natan prophetan käden alle, ja kutsui hänen Jedidjah, Herran tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Niin soti Joab Ammonin lasten Rabbaa vastaan ja voitti sen kuninkaallisen kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Ja Joab lähetti sanansaattajat Davidille ja antoi sanoa hänelle: minä olen sotinut Rabbaa vastaan ja olen voittanut vesikaupungin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Niin kokoa nyt jäänyt kansa, ja piiritä kaupunki, ja voita se, etten minä sitä voittaisi, ja minulle siitä nimi olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Niin David kokosi kaiken kansan, ja matkusti Rabbaan ja soti sitä vastaan, ja voitti sen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Ja otti heidän kuninkaansa kruunun hänen päästänsä, joka painoi leiviskän kultaa, ja kalliita kiviä, ja se pantiin Davidin päähän; ja hän vei paljo saalista kaupungista ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Ja kansan, joka siellä oli, johdatti hän ulos ja pani sahaan, rautahaudoille ja kirvestöihin, ja käytti heidän tiilihautoja myöten: niin hän teki kaikille Ammonin lasten kaupungeille. Ja David ja kaikki kansa palasi Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Ja tapahtui sitte, että Absalomilla Davidin pojalla oli kaunis sisar, jonka nimi oli Tamar; ja Amnon Davidin poika rakasti häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Ja Amnon saatti itsensä tuskissansa sairaaksi sisarensa Tamarin tähden; sillä hän oli neitsy. Ja näkyi työlääksi Amnonin silmäin edessä hänelle jotakin tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Mutta Amnonilla oli ystävä,joka kutsuttiin Jonadab, Simean Davidin veljen poika; ja Jonadab oli sangen kavala mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Hän sanoi hänelle: kuninkaan poika, miksis niin laihaksi tulet päivä päivältä? Etkös minulle sitä sano? Niin sanoi Amnon hänelle: minä rakastan Tamaria,veljeni Absalomin sisarta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Jonadab sanoi hänelle: laske sinus vuoteeses ja teeskele itses sairaaksi: kuin siis sinun isäs tulee katsomaan sinua, niin sano hänelle: tulkaan sisareni Tamar ruokkimaan minua ja valmistamaan ruokaa minun eteeni, että minä näkisin ja söisin hänen kädestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Niin Amnon pani levätä ja teeskeli itsensä sairaaksi. Kuin kuningas tuli häntä katsomaan, sanoi Amnon kuninkaalle: tulkaan minun sisareni Tamar valmistamaan minun eteeni kaksikin herkkua, että minä söisin hänen kädestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Niin lähetti David sanan Tamarille huoneesen ja antoi hänelle sanoa: mene veljes Amnonin huoneesen ja valmista hänelle ruokaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Tamar meni veljensä Amnonin huoneesen, ja hän makasi vuoteessa; ja hän otti taikinan, sotkui ja valmisti sen hänen silmäinsä edessä, ja kypsensi ne herkut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Ja hän otti pannun ja kaasi hänen eteensä, vaan ei hän tahtonut syödä. Ja Amnon sanoi: antakaat kaikki mennä ulos minun tyköäni; niin menivät kaikki ulos hänen tyköänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Niin sanoi Amnon Tamarille: kanna ruoka kamariin syödäkseni kädestäs. Niin Tamar otti herkun, jonka hän valmistanut oli, ja kantoi kamariin veljensä Amnonin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Ja kuin hän taritsi hänelle syödä, tarttui hän häneen ja sanoi hänelle: tule minun sisareni ja makaa minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Mutta hän sanoi: ei, minun veljeni, älä minua häpäise! sillä ei niin pidä tehtämän Israelissa. älä tee hulluutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Kuhunka minun pitäis häpiäni sälyttämän? Ja sinä tulisit niinkuin tyhmä Israelissa. Puhu paremmin kuninkaan kanssa, sillä ei hän minua sinulta kiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Mutta ei hän tahtonut kuulla häntä, vaan voitti hänen, häpäisi ja makasi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Sitte vihasi Amnon häntä sangen suurella vihalla, niin että viha, jolla hän häntä vihasi oli suurempi, kuin rakkaus ennen oli, jolla hän häntä rakasti. Ja Amnon sanoi hänelle: nouse ja mene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Mutta hän sanoi: eikö tämä pahuus ole suurempi kuin se toinen, jonka sinä olet tehnyt minun kanssani, ettäs minun ajat ulos. Mutta ei hän tahtonut kuulla häntä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Vaan kutsui nuorukaisensa, joka häntä palveli ja sanoi: aja tämä ulos minun tyköäni, ja sulje ovi kiinni hänen jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Ja hänen yllänsä oli kirjava hame; sillä senkaltaisilla hameilla olivat kuninkaan tyttäret vaatetetut, niinkauvan kuin he olivat neitseet. Ja kuin hänen palveliansa oli hänen ajanut ulos ja sulkenut oven hänen jälkeensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Heitti Tamar tuhkaa päänsä päälle, ja repäisi sen kirjavan hameen rikki, joka hänen yllänsä oli, ja pani kätensä päänsä päälle, ja huusi mennessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Ja hänen veljensä Absalom sanoi hänelle: onko sinun veljes Amnon ollut sinun kanssas? Ole ääneti sisareni: se on sinun veljes, älä sitä niin pane sydämees. Niin Tamar jäi yksinäiseksi veljensä Absalomin huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Ja kuin kuningas David kaikki nämät kuuli vihastui hän sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Mutta Absalom ei puhunut Amnonille pahaa eli hyvää; vaan Absalom vihasi Amnonia että hän häpäisi hänen sisarensa Tamarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Kahden vuoden perästä antoi Absalom kerittää lampaitansa BaalHatsarissa, joka on Ephraimin tykönä; ja Absalom kutsui kaikki kuninkaan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Ja Absalom tuli myös kuninkaan tykö ja sanoi: katso, palveliallas ovat nyt lammasten keritsiät: minä rukoilen, että kuningas palvelioinensa tulis palveliansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Mutta kuningas sanoi Absalomille: ei niin, poikani, älkäämme kaikki menkö, ettemme tekisi sinulle vaivaa. Ja vaikka hän suuresti rukoili häntä, ei hän kuitenkaan tahtonut mennä, vaan siunasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Absalom sanoi: jollet sinä tule, niin salli veljeni Amnonin käydä meidän kanssamme. Kuningas sanoi hänelle: mitä hän menee sinun kanssas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Niin Absalom vaati häntä, että hän antoi Amnonin ja kaikki kuninkaan lapset mennä heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Ja Absalom käski palvelioillensa ja sanoi: ottakaat vaari kuin Amnon tulee iloiseksi viinasta ja minä sanon teille: lyökäät Amnon! niin tappakaat häntä, älkäät peljätkö, sillä minä olen sen teille käskenyt, olkaat rohkiat ja miehuulliset siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Ja Absalomin palveliat tekivät Amnonille niinkuin Absalom käskenyt oli. Niin kaikki kuninkaan lapset nousivat, ja jokainen istui muulinsa päälle ja pakeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Ja kuin he vielä tiellä olivat, tuli sanoma Davidille, sanoen: Absalom on lyönyt kaikki kuninkaan lapset, niin ettei yksikään heistä ole jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Niin nousi kuningas ja repäisi vaatteensa rikki, ja heitti itsensä maahan; ja kaikki palveliat, jotka seisoivat hänen ympärillänsä, repäisivät vaatteensa rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Niin vastasi Jonadab Simean Davidin veljen poika ja sanoi: älköön minun Herrani ajatelko, että kaikki nuorukaiset kuninkaan lapsista ovat tapetut, vaan ainoastansa Amnon on kuollut; sillä se on ollut Absalomin mielessä siitä päivästä, kuin hän häpäisi hänen sisarensa Tamarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Niin älköön herrani kuningas panko sydämellensä, ajatellen, että kaikki kuninkaan lapset ovat kuolleet; sillä Amnon on ainoastansa kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Ja Absalom pakeni; ja palvelia, joka vartiana oli, nosti silmänsä ja näki, ja katso, suuri joukko kansaa tuli tiellä toinen toisensa perästä, vuoren sivulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Niin Jonadab sanoi kuninkaalle: katso, kuninkaan lapset tulevat; niinkuin palvelias sanonut on, niin on myös tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Ja kuin hän puhunut oli, katso, kuninkaan lapset tulivat, korottivat äänensä ja itkivät. Kuningas ja kaikki hänen palveliansa itkivät myös suurella itkulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Mutta Albsalom pakeni ja meni Talmain Gessurin kuninkaan Ammihudin pojan tykö; mutta hän murehti poikansa tähden ne päivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Mutta sittekuin Absalom oli paennut ja matkustanut Gessuriin oli hän siellä kolme ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Ja sen jälkeen lakkasi kuningas David menemästä Absalomia vastaan; sillä hän oli jo lohdutettu Amnonin jälkeen, joka kuollut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Ja kuin Joab ZeruJan poika ymmärsi kuninkaan sydämen olevan Absalomia vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Niin Joab lähetti Tekoaan ja antoi tuoda sieltä toimellisen vaimon, ja sanoi hänelle: teeskele nyt sinus murheelliseksi, ja pue murhevaatteet päälles, ja älä voitele sinuas öljyllä; vaan ole niinkuin joku vaimo, joka jo kauvan aikaa on murehtinut kuollutta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Ja mene kuninkaan tykö ja puhu näin ja näin hänen kanssansa. Ja Joab pani sanat hänen suuhunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Ja kuin Tekoan vaimo tahtoi puhua kuninkaan kanssa, lankesi hän maahan kasvoillensa, kumarsi ja sanoi: auta minua! kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Kuningas sanoi hänelle: mikä sinun on? Hän sanoi: minä olen tosin leskivaimo, ja minun mieheni on kuollut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Ja sinun piiallas oli kaksi poikaa: ne riitelivät keskenänsä kedolla, ja ettei siellä ollut joka heidät eroitti, niin löi toinen toisensa ja tappoi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Ja katso, nyt nousee koko sukukunta piikaas vastaan ja sanoo: anna tänne se, joka veljensä tappoi, tapettavaksi hänen veljensä sielun edestä, jonka hän tappanut on, ja tehtäväksi perinnöttömäksi. Ja he tahtovat sammuttaa minun kipinäni, joka vielä jäljellä on, ettei minun miehelläni ensinkään nimeä pitäisi hänen jälkeensä oleman maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Kuningas sanoi vaimolle: mene kotias, ja minä käsken sinun puolestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Ja Tekoan vaimo sanoi kuninkaalle: minun herrani kuningas, se pahateko olkoon minun päälläni ja minun isäni huoneen päällä; mutta kuningas ja hänen istuimensa olkoon viatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Kuningas sanoi: joka sinua vastaan puhuu, tuo häntä minun tyköni: ei hänen pidä enää rupeeman sinuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Hän sanoi: ajatelkaan nyt kuningas Herransa Jumalansa päälle, ettei verenkostajia ylen monta olisi kadottamaan, ja ettei minun poikani surmattaisi. Hän sanoi: niin totta kuin Herra elää, ei pidä hiuskarvakaan lankeeman pojastas maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Ja vaimo sanoi: anna nyt sinun piikas sanoa jotakin herralleni kuninkaalle! Hän sanoi: sano.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Vaimo sanoi: miksi sinulla on senkaltainen ajatus Jumalan kansaa vastaan? että kuningas senkaltaisia sanoja puhunut on, niinkuin hän tekis itsensä vialliseksi, ettei kuningas anna tuoda kulkiaansa jälleen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Sillä me tosin kuolemme ja juoksemme niinkuin vesi maahan, jota ei pidätetä: Ja ei Jumalakaan henkeä ota pois, vaan ajattelee kaiketi, ettei kulkia häneltä syöstäisi ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Niin olen minä nyt tullut puhumaan senkaltaisia herralleni kuninkaalle; sillä kansa on peljättänyt minua, ja piikas ajatteli: minä puhun kuninkaan kanssa, kuka tietää, että hän tekee piikansa sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Sillä kuningas kuulee piikaansa ja auttaa niiden kädestä, jotka minua ja minun poikaani yhtä haavaa Jumalan perimisestä eroittaa tahtovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Ja piikas ajatteli: herrani kuninkaan sanat ovat minulle lohdutukseksi; sillä herrani kuninkaani on niinkuin Jumalan enkeli, ja kuultelee hyvän ja pahan; sentähden myös Herra sinun Jumalas on sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Kuningas vastasi ja sanoi vaimolle: älä siis salaa minulta sitä, mitä minä kysyn sinulta. Vaimo sanoi: herrani kuningas puhukaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Kuningas sanoi: eikö Joabin käsi ole sinun kanssas kaikissa päissä? Vaimo vastasi ja sanoi: niin totta kuin sinun sielus elää, minun herrani kuningas, ei ole yhtäkään oikialla eli vasemmalla kädellä, paitsi sitä kuin minun herrani kuningas sanonut on; sillä sinun palvelias Joab on minun käskenyt ja on kaikki nämät sanat piikas suuhun pannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Että minä niin kääntäisin tämän asian, sen on sinun palvelias Joab tehnyt: mutta minun herrani on toimellinen niinkuin Jumalan enkeli, ja ymmärtää kaikki kappaleet maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Silloin sanoi kuningas Joabille: katso, minä olen sen tehnyt: mene ja tuo nuorukainen Absalom jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Silloin lankesi Joab kasvoillensa maahan, kumarsi ja kiitti kuningasta, ja sanoi: tänäpänä ymmärtää palvelias minun löytäneeksi armon sinun edessäs, minun herrani kuningas; sillä kuningas tekee, mitä hänen palveliansa sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Niin nousi Joab ja meni Gessuriin, ja toi Absalomin Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Mutta kuningas sanoi: anna hänen poiketa huoneesensa ja ei nähdä minun kasvojani. Niin Absalom poikkesi huoneesensa ja ei nähnyt kuninkaan kasvoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Ja koko Israelissa ei ollut yksikään mies niin kaunis kuin Absalom, ja niin suuresti ylistettävä; hamasta hänen kantapäästänsä niin päänlakeen asti ei ollut yhtäkään virhettä hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Ja kuin hänen päänsä kerittiin (se tapahtui vihdoin joka vuosi, sillä se oli hänelle ylen raskas, niin että hänen piti sen keritsemän), niin painoivat hänen hiuksensa kaksisataa sikliä kuninkaan painon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Ja Absalomille syntyi kolme poikaa ja yksi tytär, se kutsuttiin Tamar; ja hän oli kaunis vaimo näöstä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Ja niin oli Absalom kaksi ajastaikaa Jerusalemissa, ettei hän kuninkaan kasvoja nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Ja Absalom lähetti Joabin perään, lähettääksensä häntä kuninkaan tykö: ja ei hän tahtonut tulla hänen tykönsä. Hän lähetti toisen kerran, vaan ei hän tahtonut tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Silloin sanoi hän palvelioillensa: katsokaat sitä Joabin pellon kappaletta minun sarkani vieressä, ja hänellä on siinä ohraa: menkäät ja pistäkäät tuli siihen; niin pistivät Absalomin palveliat tulen siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Silloin nousi Joab ja tuli Absalomin huoneesen, ja sanoi hänelle: miksi palvelias ovat pistäneet tulen minun sarkaani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom sanoi Joabille: katso, minä lähetin sinun perääs ja annoin sanoa sinulle: tule minun tyköni, lähettääkseni sinua kuninkaan tykö, ja antaakseni sanoa: miksi minä tulin Gessurista? Se olis minulle parempi, että minä vielä siellä olisin. Niin anna minun nähdä kuninkaan kasvot: jos myös joku pahateko on minussa, niin tappakoon minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Ja Joab meni kuninkaan tykö ja sanoi sen hänelle, ja hän kutsui Absalomin kuninkaan tykö. Ja hän kumarsi kuninkaan eteen maahan kasvoillensa, ja kuningas antoi suuta Absalomille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Ja tapahtui sitte, että Absalom antoi valmistaa itsellensä vaunut ja hevoset, ja viisikymmentä miestä, jotka olivat hänen edelläjuoksiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Ja Absalom nousi varhain huomeneltain ja seisoi porttitien vieressä, ja kuin jollakin oli asiaa tulla kuninkaan tykö oikeuden eteen, kutsui Absalom sen tykönsä ja sanoi: sinun palvelias on yhdestä Israelin sukukunnista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Niin Absalom sanoi hänelle: katso, sinun asias on oikia ja selkiä; mutta ei ole yksikään siellä kuninkaalta asetettu, joka sinua kuulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Ja Absalom sanoi: kuka minun asettais tuomariksi maalla, että jokainen tulis minun tyköni jolla jotain asiaa ja kaipaamista on, auttaakseni häntä oikeuteen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Ja kuin joku tuli hänen tykönsä kumartamaan häntä, ojensi hän kätensä ja tarttui häneen, ja antoi hänen suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Niin teki Absalom kaikelle Israelille, kuin he tulivat oikeuden eteen kuninkaan tykö; ja niin varasti Absalom Israelin miesten sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Ja tapahtui neljänkymmenen ajastajan perästä, että Absalom sanoi kuninkaalle: minä menisin ja täyttäisin lupaukseni, jonka minä lupasin Herralle Hebronissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Sillä silloin kuin minä asuin Gessurissa Syriassa, lupasi sinun palvelias lupauksen ja sanoi: kuin Herra tuo minun kerran Jerusalemiin jälleen, palvelen minä Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Kuningas sanoi hänelle: mene rauhassa! Ja hän nousi ja meni Hebroniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Mutta Absalom oli lähettänyt vakoojat kaikkiin Israelin sukukuntiin, ja käski sanoa: kuin saatte kuulla torven äänen, niin sanokaat: Absalom on kuningas Hebronissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Mutta Absalomin kanssa meni kaksisataa miestä Jerusalemista, jotka olivat kutsutut; mutta ne menivät yksinkertaisuudessansa, eikä mitään asiasta tietäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Ja Absalom lähetti myös Ahitophelin Gilonilaisen, Davidin neuvonantajan, perään hänen kaupungistansa Gilosta, kuin hän uhria uhrasi; niin tehtiin juuri vahva liitto, ja paljo kansaa lisääntyi ja eneni Absalomin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Ja yksi tuli ja ilmoitti sen Davidille, ja sanoi: Israelin miesten sydän on kääntynyt Absalomin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Ja David sanoi kaikille palvelioillensa, jotka hänen kanssansa Jerusalemissa olivat: nouskaamme ja paetkaamme, sillä muutoin ei pääse yksikään meistä Absalomin edestä! rientäkäät menemään, ettei hän äkisti karkaisi meidän päällemme, ja ottaisi meitä kiinni, ja vahingoitsisi meitä ja löisi kaupunkia miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Kuninkaan palveliat sanoivat kuninkaalle: mitä meidän herramme kuningas valitsee, katso tässä me palvelias olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Ja kuningas kävi jalkaisin ulos kaiken huoneensa kanssa; mutta hän jätti kymmenen jalkavaimoa huoneita vartioitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Ja kuin kuningas ja kaikki kansa olivat jalkaisin käyneet ulos, seisoivat he kaukana huoneista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Ja kaikki hänen palveliansa kävivät hänen tykönänsä, sitälikin myös kaikki Kretit ja Pletit; ja kaikki Gatilaiset kuusisataa miestä, jotka jalkaisin olivat tulleet Gatista, kävivät kuninkaan edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Ja kuningas sanoi Ittaille Gatilaiselle: miksi sinä myös tulet meidän kanssamme? Palaja ja ole kuninkaan tykönä; sillä sinä olet muukalainen, ja olet tänne tullut sinun sialtas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Sillä eilen sinä tulit, ja minun pitäis tänäpänä antaman sinun käydä meidän kanssamme; mutta minä menen, kuhunka minä menen: palaja sinä ja vie sinun veljes myötäs. Sinun kanssas tapahtukoon armo ja vakuus!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Ittai vastasi kuningasta ja sanoi: niin totta kuin Herra elää, ja niin totta kuin minun herrani kuningas elää, kussa ikänä herrani kuningas on, olisi se kuolemassa eli elämässä, siellä pitää myös sinun palvelias oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'David sanoi Ittaille: tule ja käy meidän kanssamme. Ja niin kävi Ittai Gatilainen, ja kaikki hänen miehensä, ja kaikki lapset jotka hänen kanssansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Ja kaikki maakunta itki suurella äänellä, ja kaikki väki meni kanssa. Ja kuningas kävi Kidronin ojan ylitse, ja kaikki kansa kävi edellä korven tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'Ja katso, Zadok myös oli siellä ja kaikki Leviläiset, jotka hänen kanssansa olivat, ja he kantoivat Jumalan liitonarkin, ja panivat ylös Jumalan arkin. Ja Abjatar meni ylös, siihenasti kuin kaikki väki tuli kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Niin sanoi kuningas Zadokille: kanna Jumalan arkki kaupunkiin jälleen: jos minä löydän armon Herran edessä, niin hän tuo minun jälleen ja antaa minun nähdä hänen ja hänen majansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Mutta jos hän niin sanoo: et sinä ole minulle otollinen! katso, tässä minä olen: hän tehköön minulle, mitä hän tahtoo!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Ja kuningas sanoi papille Zadokille: sinä näkiä, palaja rauhassa kaupunkiin, ja molemmat teidän poikanne teidän kanssanne, Ahimaats sinun poikas ja Jonatan AbJatarin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Katso, minä odotan tasaisella kedolla korvessa siihenasti kuin teiltä sana tulee, tekemään minulle tiettäväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Niin Zadok ja AbJatar kantoivat Jumalan arkin Jerusalemiin, ja olivat siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Mutta David meni ylös öljymäen paltaa myöten ja itki käydessänsä, ja hänen päänsä oli peitetty, ja kävi kengittä; niin myös kaikki kansa, jotka hänen kanssansa olivat, peittivät päänsä, ja käyden astuivat ylös ja itkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Ja kuin Davidille ilmoitettiin Ahitophelin olevan liitossa Absalomin kanssa, sanoi hän: Herra, tee Ahitophelin neuvo tyhmyydeksi!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Ja kuin David tuli kukkulalle, kussa Jumalaa rukoiltiin, katso, Husai Arkilainen kohtasi häntä reväistyllä hameella, ja multaa hänen päänsä päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Ja David sanoi: jos seuraat minua, niin sinä olet minulle kuormaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Mutta jos palajat kaupunkiin ja sanot AbsalomilIe: minä olen sinun palvelias, kuningas, joka ennen isääs olen kauvan palvellut, ja tahdon olla nyt sinun palvelias: ja näin sinä minulle teet Ahitophelin neuvon tyhjäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Eikö Zadok ja AbJatar papit ole sinun kanssas? Ja kaikki, mitäs kuulet kuninkaan huoneessa, ilmoita papeille Zadokille ja AbJatarille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Katso, heidän kaksi poikaansa ovat siellä heidän kanssansa, Ahimaats Zadokin poika ja Jonatan AbJatarin poika: niiden kanssa te saatte lähettää minulle, mitä te kuulette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Niin Husai Davidin ystävä meni kaupunkiin ja Absalom tuli Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Ja kuin David oli vähä käynyt alas vuoren kukkulalta, katso, kohtasi hänen Ziba MephiBosetin palvelia kahdella satuloidulla aasilla, joiden päällä oli kaksisataa leipää, ja sata rypälettä rusinoita, ja sata rypälettä fikunia ja leili viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Niin sanoi kuningas Ziballe: mitäs näillä tahdot tehdä? Ziba sanoi: aasit pitää oleman kuninkaan perheelle, joilla he ajaisivat, leivät ja fikunat palvelioille, joista he söisivät, ja viina heidän juodaksensa, kuin he väsyvät korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Kuningas sanoi: kussa on herras poika? Ziba sanoi kuninkaalle: katso, hän jäi Jerusalemiin, sillä hän sanoi: tänäpänä pitää Israelin huoneen antaman minulle minun isäni valtakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Kuningas sanoi Ziballe: katso, kaikki mitä MephiBosetilla on, pitää sinun oleman. Ziba sanoi: minä rukoilen nöyrästi, anna minun löytää armo sinun edessäs, herrani kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Kuin kuningas David tuli Bahurimiin, katso, sieltä tuli yksi mies Saulin huoneen suvusta, Simei nimeltä, Geran poika, se läksi ulos ja kiroili käydessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Ja paiskeli kiviä Davidin puoleen, ja kaikkia kuningas Davidin palvelioita vastaan; sillä kaikki kansa ja kaikki väkevät olivat hänen oikialla ja vasemmalla puolellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Ja Simei sanoi näin kiroillessansa häntä: ulos, ulos tänne, sinä verikoira, sinä Belialin mies!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Herra on maksanut sinulle kaiken Saulin huoneen veren, ettäs olet tullut hänen siaansa kuninkaaksi. Ja Herra on antanut valtakunnan pojalles Absalomille; ja katso, nyt sinä olet sinun pahuudessas, sillä sinä olet verikoira.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Silloin Abisai ZeruJan poika sanoi kuninkaalle: pitääkö tämän kuolleen koiran kiroileman herraani kuningasta? Minä menen ja lyön häneltä pään pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Kuningas sanoi: te ZeruJan pojat, mitä minun on teidän kanssanne? Anna hänen kirota; sillä Herra on hänelle sanonut: kiroile David. Kuka taitaa nyt sanoa: miksis niin teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Ja David sanoi Abisaille ja kaikille palvelioillensa: katso, minun poikani, joka minun kupeistani tullut on, seisoo minun henkeni perään: miksi ei siis pidä myös Jeminin pojan? Antakaat hänen kiroilla, sillä Herra on hänelle sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Mahtaa tapahtua: Herra katsoo minun viheliäisyyttäni, ja Herra maksaa minulle hyvällä, sen kun hän minua tänäpänä kiroilee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Ja David meni väkinensä tietä myöten; mutta Simei kävi hänen kohdallansa mäen viertä myöten, ja käyden kiroili, lasketti kiviä hänen puoleensa ja viskeli multaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Ja kuningas vaelsi, ja kaikki kansa joka oli hänen kanssansa oli väsyksissä; ja hän lepäsi siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Mutta Absalom ja kaikki kansa, Israelin miehet, tulivat Jerusalemiin; ja Ahitophel hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Kuin Husai Arkilainen Davidin ystävä tuli Absalomin tykö, sanoi hän Absalomille: kuningas eläköön, kuningas eläköön!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom sanoi Husaille: onko tämä sinun laupiutes ystävääs kohtaan? Miksi et mennyt ystäväs kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Husai sanoi Absalomille: ei niin; mutta jonka Herra valitsee,ja tämä kansa, ja kaikki Israelin miehet, hänen minä olen ja hänen kanssansa minä pysyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Sitälikin, ketästä minun pitäis palveleman? eikö hänen poikansa edessä? Niinkuin minä olen palvellut isäis edessä, niin minä myös tahdon olla sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Ja Absalom sanoi Ahitophelille: pitäkäät neuvoa, mitä meidän pitää tekemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitophel sanoi Absalomille: makaa isäs jalkavaimoin kanssa, jotka hän on jättänyt huonetta vartioitsemaan; niin koko Israel saa kuulla sinun tehneeksi isäs haisemaan, ja kaikkein kädet vahvistetaan siitä, jotka sinun tykönäs ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Niin tekivät he Absalomille majan katon päälle; ja Absalom makasi kaikkein isänsä jalkavaimoin kanssa, kaiken Israelin nähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Kuin Ahitophel neuvoa antoi sillä ajalla, oli se niinkuin joku olis kysynyt Jumalalta jostakin asiasta: kaikki niin olivat Ahitophelin neuvot niin Davidin kuin Absalominkin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Ja Ahitophel sanoi Absalomille: minä valitsen nyt kaksitoistakymmentä tuhatta miestä ja nousen tänä yönä ajamaan Davidia takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Ja minä karkaan hänen päällensä, niinkauvan kuin hän on väsynyt ja heikko käsistä. Kuin minä hänen peljätän, että kaikki kansa pakenee, joka hänen tykönänsä on, niin lyön minä kuninkaan yksinänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Ja palautan kaiken kansan sinun tykös. Kuin jokainen on sinun tykös palautettu, niinkuin sinä anonut olet, niin kaikki kansa on rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Se näkyi oikia olevan Absalomille ja kaikille vanhimmille Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Mutta Absalom sanoi: kutsuttakoon myös Husai Arkilainen, ja kuulkaamme, mitä hän tästä asiasta sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Ja kuin Husai tuli Absalomin tykö, puhui Absalom hänelle, sanoen: näitä Ahitophel on puhunut, sano sinä, pitääkö meidän niin tekemän, taikka ei?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Niin Husai sanoi Absalomille: ei ole se hyvä neuvo, kuin Ahitophel tällä haavalla antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Ja Husai sanoi vielä: sinä tunnet hyvin isäs ja hänen miehensä, että ne ovat väkevät ja vihaiset sydämestä niinkuin karhu, jolta pojat ovat otetut kedolla pois: on myös isäs sotamies, ja ei hän yöttele väkensä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Katso: nyt hän on lymyttänyt itsensä johonkuhun luolaan eli johonkuhun muuhun paikkaan: jos se nyt tapahtuis, että he nyt alussa kaatuisivat, ja se kuin sen kohta kuulis, niin hän sanois: siellä on tapahtunut suuri tappo sen kansan seassa, jotka Absalomia seurasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Niin rupeais todella jokainen pelkäämään, joka muutoin on väkevä sotamies, jonka sydän on kuin jalopeuran sydän; sillä kaikki Israel tietää, että isäs on väkevä, ja ne ovat jalot sotamiehet, jotka hänen kanssansa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Mutta sitä neuvoa minä annan, että sinä kokoat tykös kaiken Israelin, hamasta Danista BerSebaan asti, niin monta kuin santaa meren rannalla: ja sinä itse menet heidän kanssansa heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Niin me karkaamme hänen päällensä, kussa paikassa me hänen ikänä löydämme, ja karkaamme hänen päällensä, niinkuin kaste lankee maan päälle, ettemme yhtäkään jätä jäljelle kaikista hänen miehistänsä, jotka hänen kanssansa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Mutta jos hän kokoo itsensä johonkuhun kaupunkiin, niin pitää koko Israelin siihen kaupunkiin heittämän köysiä; ja me vedämme sen virtaan siihenasti, ettei siitä löydetä yhtäkään kiveä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Niin sanoi Absalom ja jokainen mies Israelista: Husain Arkilaisen neuvo on parempi kuin Ahitophelin. Mutta Herra asetti sen niin, että Ahitophelin hyvä neuvo estettiin, että Herra saattais Absalomille onnettomuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Ja Husai sanoi papille Zadokille ja AbJatarille: niin ja niin on Ahitophel Absalomia ja Israelin vanhempia neuvonut, mutta minä olen niin ja niin neuvonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Niin lähettäkäät nyt kiiruusti matkaan, ja ilmoittakaat Davidille ja sanokaat: älä ole yötä kedolla korvessa, mutta riennä pois, ettei kuningas nieltäis ja kaikki väki joka hänen kanssansa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Ja Jonatan ja Ahimaats seisoivat Rogelin lähteen tykönä, ja yksi piika meni ja sanoi sen heille, ja he menivät ja sanoivat sen kuningas Davidille; sillä ei he uskaltaneet näyttää itsiänsä, että olivat tulleet kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Mutta yksi palvelia sai heidät nähdä ja ilmoitti Absalomille. Ja he menivät nopiasti molemmin matkaansa ja tulivat Bahurimissa yhden miehen huoneesen, hänellä oli kaivo kartanossansa; ja he astuivat siihen sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Ja vaimo otti peitteen ja levitti kaivon päälle, ja hajoitti survotuita herneitä sen päälle; niin ettei sitä tuntunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Kuin Absalomin palveliat tulivat vaimon tykö huoneeseen, sanoivat he: kussa on Ahimaats ja Jonatan? Vaimo sanoi heille: he menivät tuon vähän ojan ylitse. Ja kuin he olivat etsineet ja ei mitään löytäneet, menivät he Jerusalemiin jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Ja kuin he olivat menneet pois, nousivat he kaivosta ylös, ja menivät matkaansa, ja ilmoittivat kuningas Davidille, ja sanoivat Davidille: nouskaat ja menkäät kiiruusti veden ylitse; sillä niin ja niin on Ahitophel pitänyt neuvoa teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Silloin nousi David ja kaikki väki, joka hänen kanssansa oli, ja meni ennen päivän koittamaa Jordanin ylitse, ja ei yksikään puuttunut heistä, joka ei tullut Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Kuin Abitophel näki, ettei hänen neuvonsa jälkeen tehty, satuloitsi hän aasinsa, nousi ja meni huoneesensa ja kaupunkiinsa, ja toimitti huoneensa menot, ja hirtti itsensä; ja niin hän kuoli ja haudattiin isänsä hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Ja David tuli Mahanaimiin; ja Absalom meni Jordanin ylitse, hän ja kaikki Israelin miehet hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Ja Absalom asetti Amasan Joabin siaan sodanpäämieheksi. Ja Amasa oli Jetran sen Jisreeliläisen poika, joka makasi Abigailin Nahaksen tyttären ZeruJan sisaren, Joabin äidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Mutta Israel ja Absalom sioittivat itsensä Gileadin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Kuin David oli tullut Mahanaimiin, toi Sobi Nahaksen poika, Ammonin lasten Rabbatista, ja Makir Amnielin poika Lodebarista ja Barsillai Gileadilainen Rogelimista');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Makausvaatteita, maljoja, saviastioita, nisuja, ohria, jauhoja, kuivatuita tähkäpäitä, papuja, herneitä ja tuletettuja herneitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'Hunajaa, voita, lampaita ja lehmän juustoja, ne kantoivat he Davidille ja väelle, joka hänen kanssansa oli, ravinnoksi; sillä he ajattelivat: kansa rupee isoomaan, väsymään ja janoomaan korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Ja David silmäili kansan, joka hänen tykönänsä oli, ja pani päämiehiä tuhanten ja satain päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Ja lähetti kansasta kolmannen osan Joabin kanssa ja kolmannen osan Abisain ZeruJan pojan Joabin veljen kanssa, ja kolmannen osan Ittain sen Gatilaisen kanssa. Ja kuningas sanoi kansalle: minä menen kohta myös teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Mutta kansa sanoi: älä mene; sillä jos me joudumme pakenemaan, ei he meistä tottele: jos puoli kuolee meistä, ei he siitä pidä lukua; sillä sinä olet niinkuin kymmenentuhatta meistä. Se on parempi, ettäs tulet meille avuksi kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Kuningas sanoi heille: mitä te luulette teillenne olevan hyväksi, sen minä teen. Ja kuningas seisoi portilla, ja kansa kävi sadoin ja tuhansin ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Ja kuningas käski Joabia, Abisaita ja Ittaita, sanoen: menkäät siviästi nuorukaisen Absalomin kanssa; ja kaikki kansa kuuli kuninkaan varoittavan jokaista päämiestä Absalomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Ja kuin kansa tuli väljälle Israelia vastaan, niin oli sota Ephraimin metsässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Ja Israelin kansa lyötiin siellä Davidin palvelioilta, että sinä päivänä tapahtui sangen suuri tappo: (ja kaatui) kaksikymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Ja sota hajoitettiin siellä kaikkeen maahan; ja metsä surmasi usiamman sinä päivänä kansasta, kuin miekka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Ja Absalom kohtasi Davidin palvelioita ja ajoi muulilla. Ja kun muuli tuli oksaisen paksun tammen alle, tarttui hänen päänsä tammeen, ja hän jäi riippumaan taivaan ja maan välille, mutta muuli juoksi matkaansa hänen altansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Kuin yksi mies sen näki, ilmoitti hän Joabille, ja sanoi: katso, minä näin Absalomin riippuvan tammessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Ja Joab sanoi miehelle, joka sen hänelle ilmoitti: katso, näitkös sen? Miksi et lyönyt häntä siitä maahan? Niin minä olisin minun puolestani antanut sinulle kymmenen hopiapenninkiä ja yhden vyön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mies sanoi Joabille: jos olisin saanut punnittuna tuhannen hopiapenninkiä minun käteeni, en minä vielä sittenkään olisi kättäni satuttanut kuninkaan poikaan; sillä kuningas käski meidän kuullemme sinua ja Abisaita ja Ittaita, sanoen: pitäkäät vaari nuorukaisesta Absalomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Eli jos minä vielä jotakin vääryyttä tehnyt olisin sieluni vahingoksi (sillä ei kuninkaan edessä mitään salattu ole), niin sinä olisit ollut minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Joab sanoi: en minä enää sinun tykönäs viivy; ja otti kolme keihästä käteensä ja pisti ne Absalomin sydämeen, kuin hän vielä tammessa eli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Ja kymmenen nuorukaista Joabin asetten kantajista piirittivät hänen; he löivät ja tappoivat Absalomin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Niin puhalsi Joab basunaan, ja kansa palasi ajamasta Israelia takaa; sillä Joab tahtoi armahtaa kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Ja he ottivat Absalomin, ja heittivät metsässä suureen kuoppaan, ja panivat suuren kiviroukkion hänen päällensä. Ja koko Israel pakeni kukin majallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Vaan Absalom oli eläissänsä pystyttänyt itsellensä patsaan, se seisoo Kuninkaanlaaksossa; sillä hän sanoi: ei minulla ole yhtään poikaa, olkoon tämä sentähden minun nimeni muistoksi. Ja kutsui sen patsaan nimellänsä, joka vielä tänäpänä kutsutaan Absalomin paikaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaats Zadokin poika sanoi: minä juoksen nyt ja ilmoitan kuninkaalle, Herran saattaneeksi hänelle oikeuden hänen vihollistensa käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Joab sanoi hänelle: et sinä yhtään hyvää sanomaa vie tänäpänä, vie toisena päivänä sanomia, vaan ei sinun pidä tänäpänä sanomaa saattaman; sillä kuninkaan poika on kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Mutta Joab sanoi Kuusille: mene ja ilmoita kuninkaalle mitäs nähnyt olet. Ja Kuusi kumarsi Joabia ja juoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Mutta Ahimaats Zadokin poika sanoi vielä kerran Joabille: vaikka mitä olis, minä juoksen myös Kuusin perässä. Joab sanoi: miksi sinä juokset, poikani? Et sinä vie yhtään hyvää sanomaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Hän vastasi: vaikka mitä olis, minä juoksen. Hän sanoi hänelle: juokse. Niin Ahimaats juoksi kohdastansa ja ennätti Kuusin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Mutta David istui kahden portin vaiheella, ja vartia meni portin kohdalle, muurin katon päälle, nosti silmänsä ja näki miehen juoksevan yksinänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Ja vartia huusi ja sanoi sen kuninkaalle. Kuningas sanoi: jos hän on yksin, niin hän on hyvä sanantuoja; Ja hän aina juoksi ja tuli lähemmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Niin vartia näki toisen miehen juoksevan, ja huusi ovenvartialle ja sanoi: katso, yksi mies juoksee yksinänsä. Kuningas sanoi: se on myös hyvä sanantuoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Vartia sanoi: minulle näkyy ensimäisen juoksu, niinkuin se olis Ahimaatsin Zadokin pojan juoksu. Ja kuningas sanoi: se on hyvä mies ja tuo hyvää sanomaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ahimaats huusi ja sanoi kuninkaalle: Rauha! ja kumarsi kuninkaan edessä maahan kasvoillensa ja sanoi: kiitetty olkoon Herra sinun Jumalas, joka ne miehet on antanut sinun kätees, jotka nostivat kätensä herraani kuningasta vastaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Kuningas sanoi: onko nuorukainen Absalom rauhassa? Ahimaats sanoi: minä näin suuren metelin, kuin Joab kuninkaan palvelia lähetti minun sinun palvelias tänne, ja en minä tiedä, mikä se oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Kuningas sanoi: mene erinäs ja seiso siellä. Ja hän meni erinänsä ja seisoi siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Ja katso, Kuusi tuli ja sanoi: täällä ovat hyvät sanomat, herrani kuningas: Herra on saattanut tänäpänä sinulle oikeuden kaikkein kädestä, jotka nousivat sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Kuningas sanoi Kuusille: onko nuorukainen Absalom rauhassa? Kuusi sanoi: tapahtukoon niin herrani kuninkaan vihollisille, kuin nuorukaiselle on tapahtunut, ja kaikille niille, jotka heitänsä asettavat sinua vastaan sinulle vahingoksi!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Niin tuli kuningas murheelliseksi, ja meni portin ylistupaan ja itki, ja sanoi mennessänsä näin: poikani Absalom! poikani, poikani Absalom! 0, jospa minä olisin kuollut sinun siassas, oi, Absalom poikani, minun poikani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Ja Joabille ilmoitettiin: katso, kuningas itkee ja suree Absalomia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Ja sinä päivänä oli voitosta itku kaiken kansan seassa; sillä kansa oli kuullut sinä päivänä sanottavan kuninkaan olevan murheellisen poikansa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Ja kansa lymytti sinä päivänä itsensä ja ei tullut kaupunkiin; niinkuin joku kansa varastaa itsensä, joka häpee paetessansa sodassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Mutta kuningas peitti kasvonsa ja huusi suurella äänellä: voi minun poikani Absalom! Absalom, minun poikani, minun poikani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Niin Joab tuli kuninkaan tykö huoneeseen ja sanoi: sinä olet häväissyt tänäpänä kaikki sinun palvelias, jotka ovat sinun, ja sinun poikais ja tytärtes, emäntäis ja jalkavaimois hengen hädästä pelastaneet tänäpänä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Ettäs rakastat niitä, jotka sinua vihaavat, ja vihaat niitä, jotka sinua rakastavat; sillä tänäpänä sinä ilmoitit sinus ei lukua pitävän sodanpäämiehistä eli palvelioistas, ja siitä minä tänäpänä ymmärrän, että jos Absalom ainoastansa eläis ja me kaikki olisimme tänäpänä kuolleet, se sinulle kelpais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Nouse siis nyt ja käy ulos, ja puhu suloisesti palvelioilles; sillä minä vannon sinulle Herran kautta, että jolles sinä käy ulos, niin ei ole yksikään mies sinun tykönäs tätä yötä; se on sinulle pahempi, kuin kaikki se vastoinkäyminen, joka sinulle hamasta nuoruudestas tähän asti on tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Niin nousi kuningas, ja istui portilla. Ja se ilmoitettiin kaikelle kansalle, sanoen: katso, kuningas istuu portilla. Niin kaikki kansa tuli kuninkaan eteen; vaan Israel oli paennut itsekukin majoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'Ja kaikki kansa Israelin sukukunnista riiteli keskenänsä, sanoen: kuningas on meitä auttanut meidän vihamiestemme käsistä, Ja hän on meitä pelastanut Philistealaisilta: ja nyt täytyy hänen maakunnasta paeta Absalomin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Mutta Absalom, jonka me voitelimme meillemme, on kuollut sodassa, miksi te nyt olette niin hiljaiset noutamaan kuningasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Mutta kuningas David lähetti pappein Zadokin ja AbJatarin tykö, ja käski heille sanoa: puhukaat vanhimmille Juudassa, sanoen: miksi te olette viimeiset kuningasta kotiansa noutamaan? Sillä kaiken Israelin puhe oli ilmoitettu kuninkaan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Te olette minun veljeni, minun luuni ja minun lihani: miksi te olette viimeiset noutamaan jälleen kuningasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Ja sanokaat Amasalle: etkös ole minun luuni ja lihani? Jumala tehköön minulle niin ja niin, jollei sinun pidä tuleman sotaherraksi minun edessäni Joabin siaan sinun elinaikanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Ja hän käänsi kaikkein Juudan miesten sydämet niinkuin yhden miehen. Ja he lähettivät kuninkaalle sanan: palaja sinä ja kaikki palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Niin kuningas tuli jälleen. Ja kuin hän lähestyi Jordania, olivat kaikki Juudan miehet tulleet Gilgaliin menemään kuningasta vastaan ja saattamaan kuningasta Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Ja Simei Geran poika, Jeminin pojan Bahurimista, kiiruhti itsensä ja meni alas Juudan miesten kanssa kuningas Davidia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Ja hänen kanssansa oli tuhannen miestä BenJaminista, oli myös Ziba Saulin huoneen palvelia viidentoistakymmenen poikansa kanssa ja kahdenkymmenen palvellansa kanssa; ja he kiiruhtivat heitänsä Jordanin ylitse kuninkaan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'He valmistivat alukset kuningasta ja hänen palvelioitansa ylitse vietää, tehdäksensä sitä kuninkaalle mielen nouteeksi. Mutta Simei Geran poika lankesi polvillensa kuninkaan eteen hänen mennessä Jordanin ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'Ja sanoi kuninkaalle: minun herrani, älä lue minulle sitä pahaa tekoa, älä myös muistele sinun palvelias rikosta, jolla hän sinun vihoitti, herra kuningas, lähteissäs Jerusalemista: älköön kuningas sitä sydämeensä panko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Sillä sinun palvelias tuntee syntiä tehneensä, ja katso, minä olen tänäpänä lähtenyt ensimäisenä koko Josephin huoneesta herraani kuningasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Mutta Abisai ZeruJan poika vastasi ja sanoi: eikö Simein sen edessä pitäisi kuoleman, että hän kirosi Herran voideltua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Ja David vastasi: mitä minun on teidän kanssanne, te ZeruJan pojat, että tahdotte tänäpänä minulle tulla saatanaksi? Pitäiskö jonkun tänäpänä kuoleman Israelista? Luuletteko, etten minä tiedä tänäpänä itseni tulleeksi kunininkaaksi Israelissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Sanoi siis kuningas Simeille: ei sinun pidä kuoleman; ja kuningas vannoi hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Tuli myös MephiBoset Saulin poika kuningasta vastaan, pesemättömillä jaloilla ja ajelemattomalla parralla; ei hän ollut myös pessyt vaatteitansa siitä päivästä, kuin kuningas läksi ja rauhassa jälleen palasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Kuin hän tuli Jerusalemissa kuningasta vastaan, sanoi kuningas hänelle: miksi et minun kanssani tullut, MephiBoset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Ja hän sanoi: herra kuningas, minun palveliani on pettänyt minun; sillä palvelias ajatteli: minä satuloitsen aasin, ajan ja vaellan sillä kuninkaan tykö; sillä palvelias on ontuva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'Ja vielä päälliseksi on hän kantanut minun herrani kuninkaan edessä palvelias päälle; vaan herrani kuningas on kuin Jumalan enkeli, tee siis mitä sinulle on kelvollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Sillä koko minun isäni huone ei ole muu ollut kuin kuoleman kansa herrani kuninkaan edessä, ja sinä olet palvelias istuttanut niiden sekaan, jotka sinun pöydältäs syövät; mikä oikeus on minulla enää huutaa kuninkaan tykö?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Kuningas sanoi hänelle: mitäs tahdot enää puhua asiastas? Minä olen sanonut: sinun ja Ziban pitää keskenänsä jakaman pellon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Niin MephiBoset sanoi kuninkaalle: ottakaan hän sen kokonansa, että herrani kuningas on rauhassa kotiansa palannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Ja Barsillai Gileadilainen tuli Rogelimista ja meni kuninkaan kanssa Jordanin ylitse, saattamaan häntä Jordanin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Ja Barsillai oli sangen ijällinen, jo kahdeksankymmenen vuotinen; hän oli ravinnut kuningasta, kuin hän Mahanaimissa oli; sillä hän oli sangen jalo mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Ja kuningas sanoi Barsillaille: seuraa minua, minä ravitsen sinun minun kanssani Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Mutta Barsillai sanoi kuninkaalle: kuinka monta vuotta minulla enää on elää, että minä menisin kuninkaan kanssa Jerusalemiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Minä olen jo tänäpänä kahdeksankymmenen ajastaikainen, tietäisinkö minä, mikä hyvä eli paha olis? eli maistaisko palvelias, mitä hän syö ja juo? taikka kuulisinko minä silleen veisaajain ja laulajain ääntä? Miksi palvelias pitäis vaivaaman herraani kuningasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Sinun palvelias menee vähä Jordanin ylitse kuninkaan kanssa: minkätähden kuningas tahtoo minulle näin kostaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Salli siis nyt palvelias palata jällensä, että minä kuolisin minun kaupungissani ja haudattaisiin isäni ja äitini hautaan: ja katso, tässä on sinun palvelias Kimeham, hän menköön herrani kuninkaan kanssa: ja tee hänelle, mitä sinulle on kelvollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Kuningas vastasi: Kimehamin pitää seuraaman minua ylitse, ja minä teen hänelle, mikä sinulle on otollinen, ja kaikki mitäs minulta anot, teen minä sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Kuin kaikki kansa ja kuningas olivat menneet Jordinin ylitse, antoi kuningas Barsillain suuta ja siunasi häntä, ja hän palasi kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Niin kuningas meni Gilgaliin ja Kimeham seurasi häntä; ja kaikki Juudan väki oli saattanut kuningasta ylitse, niin myös puoli Israelin kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Ja katso, silloin tulivat kaikki Israelin miehet kuninkaan tykö ja sanoivat hänelle: miksi meidän veljemme Juudan miehet ovat varastaneet sinun ja vieneet kuninkaan perheinensä Jordanin ylitse, kaikki myös Davidin miehet hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Niin vastasivat kaikki Juudan miehet Israelin miehille: sillä kuningas on meitä läheisempi, miksi te sentähden niin närkästytte? Vai luuletteko te, että me jollakulla olemme kuninkaalta ravitut, taikka joitakin lahjoja saaneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Niin Israelin miehet vastasivat Juudan miehiä, sanoen: meillä on kymmenen osaa kuninkaassa, enemmin myös David meille tulee kuin teille: kuinka siis sinä olet minua niin halvaksi lukenut, ettei minun olisi sopinut ensimäisenä olla kuningastani noutamassa? Mutta Juudan miehet puhuivat tuimemmin kuin Israelin miehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Mutta siihen tuli yksi kuuluisa Belialin mies, jonka nimi oli Seba Bikrin poika Jeministä; se soitti basunalla ja sanoi: ei meillä ole yhtäkään osaa Davidissa eikä yhtäkään perimistä Isain pojassa, itsekukin palatkaan majaansa, o Israel!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Silloin jokainen Israelissa luopui Davidista, ja seurasivat Sebaa Bikrin poikaa. Mutta Juudan miehet riippuivat kuninkaassansa Jordanista Jerusalemiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Ja David tuli kotiansa Jerusalemiin, ja kuningas otti ne kymmenen jalkavaimoa, jotka hän oli jättänyt huonetta vartioitsemaan, ja antoi heidän kätkettää, ja elätti heitä ja ei mennyt heidän tykönsä; ja he olivat salvatut kuolemaansa asti leskeydessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Ja kuningas sanoi Amasalle: kokoa minun tyköni Juudan miehet kolmena päivänä, ja sinun pitää myös itse läsnä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Niin Amasa meni kokoomaan Juudan miehiä, ja hän viipyi määrätyn ajan ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Niin David sanoi Abisaille: nyt Seba Bikrin poika enempi meitä vahingoitsee kuin Absalom: ota siis herras palveliat ja aja häntä takaa, ettei hän löytäisi vahvoja kaupungeita ja pääsisi meidän silmäimme edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Silloin läksivät hänen kanssansa Joabin miehet, ja Kretit ja Pletit, ja kaikki väkevät. Ja he läksivät Jerusalemista ajamaan Sebaa Bikrin poikaa takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Kuin he joutuivat suuren vahan tykö Gibeoniin, tuli Amasa heidän eteensä. Mutta Joab oli vyötetty päällisvaatteissansa, ja sen päällä miekan vyö, joka riippui hänen kupeissansa tupessa, ja koska hän kävi, taisi se pudota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Ja Joab sanoi Amasalle: oletkos rauhassa, minun veljeni? Ja Joab tarttui oikialla kädellänsä Amasan partaan, suuta antaaksensa hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Mutta ei Amasa ottanut vaaria miekasta joka oli Joabin kädessä: ja hän pisti sillä häntä vatsaan ja vuodatti hänen sisällyksensä maalle, eikä häntä enää pistänyt, ja hän kuoli. Mutta Joab ja hänen veljensä Abisai ajoivat Sebaa Bikrin poikaa takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Mutta yksi Joabin palvelioista seisoi hänen tykönänsä ja sanoi: kuka tahtoo pitää Joabin ja Davidin kanssa, hän seuratkaan Joabia!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Mutta Amasa makasi tahrattuna veressä keskellä tietä. Kuin yksi näki sen, että kaikki kansa seisahti, siirsi hän Amasan tieltä kedolle ja heitti vaatteen hänen päällensä; sillä hän näki, että jokainen joka hänen tykönsä tuli, seisahti siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Kuin hän oli tieltä siirretty, meni jokainen Joabin jälkeen, ajamaan Sebaa Bikrin poikaa takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Ja hän vaelsi kaikki Israelin sukukunnat lävitse Abelaan ja BetMaakaan ja koko Berimiin, ja ne kokoontuivat ja seurasivat myös häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Mutta kuin he tulivat, niin he piirittivät hänen Abelassa BetMaakan tykönä, ja rakensivat vallin kaupungin ympärille, joka seisoi muurin tasalla. Mutta kaikki kansa, joka Joabin myötä oli, karkasi muuria kukistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Niin toimellinen vaimo huusi kaupungista: kuulkaat, kuulkaat! sanokaat Joabille, että hän tulee tänne lähes, minä puhuttelen häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Kuin hän tuli hänen tykönsä, sanoi vaimo: oletkos Joab? Hän vastasi: olen. Vaimo sanoi hänelle: kuule piikas sanat! Hän vastasi: minä kuulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Ja hän puhui, sanoen: muinoin sanottiin: joka kysellä tahtoo, hän kysykään Abelassa, ja niin se menestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Minä olen rauhallinen ja uskollinen (kaupunki) Israelissa, ja sinä tahdot tappaa sen kaupungin ja äidin Israelissa: miksis tahdot niellä Herran perimisen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Silloin vastasi Joab ja sanoi: pois se, pois se minusta, että minä nielisin ja hävittäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Ei asia niin ole; vaan yksi mies Ephraimin vuorelta nimeltä Seba Bikrin poika on nostanut kapinan David kuningasta vastaan: antakaat hän ainoastansa, ja minä erkanen kaupungista. Ja vaimo sanoi Joabille: katso, hänen päänsä pitää sinulle heitettämän muurin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Ja vaimo tuli kaiken kansan tykö toimellansa. Ja he hakkasivat Seban Bikrin pojan pään pois ja heittivät Joabille. Ja hän soitti basunalla, ja he hajosivat kaikki kaupungin tyköä itsekukin majoihinsa; mutta Joab palasi Jerusalemiin kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Ja Joab oli koko Israelin sotajoukon ylitse; vaan BenaJa Jojadan poika oli Kretin ja Pletin ylitse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram oli verorahan haltia; Josaphat Ahiludin poika oli kansleri;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Ja Seja oli kirjoittaja; ja Zadok ja Abjatar olivat papit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Niin myös Ira Jairilainen oli Davidin ylimmäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Ja Davidin aikana oli kallis aika kolme vuotta järjestänsä: ja David etsi Herran kasvoja. Ja Herra sanoi, Saulin tähden ja sen verihuoneen tähden, että hän tappoi Gibeonilaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Niin kuningas antoi kutsua Gibeonilaiset ja sanoi heille. Mutta Gibeonilaiset ei olleet Israelin lapsista, vaan jääneistä Amorilaisista: ja Israelin lapset olivat vannoneet heille, ja Saul etsi heitä lyödäksensä vihansa kiivaudessa Israelin ja Juudan lasten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Niin sanoi David Gibeonilaisille, mitä minun pitää teille tekemän? ja millä minun pitää sen sovittaman, että te siunaisitte Herran perikuntaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Niin vastasivat häntä Gibeonilaiset, ei ole meillä tekemistä hopiasta eli kullasta Saulin ja hänen huoneensa kanssa, eikä myös että joku surmattaisiin Israelista. Hän sanoi, mitä te tahdotte, että minä teille tekisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'He sanoivat kuninkaalle, sen miehen, joka meitä hukutti ja aikoi semmoista meitä vastaan, että meidän piti tuleman niin hävitetyksi, ettei meidän pitänyt seisovaiset oleman kaikissa Israelin maan rajoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Hänen huoneestansa annettakaan meille seitsemän miestä hirttääksemme heitä Herran edessä Saulin Gibeassa, Herran valitun. Kuningas sanoi, minä annan heidät teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Mutta kuningas armahti MephiBosetia, Jonatanin Saulin pojan poikaa, sen Herran valan tähden, joka oli heidän välillänsä, Davidin ja Jonatanin Saulin pojan välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Mutta kuningas otti ne kaksi Ritspan Aijan tyttären poikaa, jotka hän Saulille synnyttänyt oli, Armonin ja MephiBosetin, ja viisi Mikalin Saulin tyttären poikaa, jotka hän Hadrielille Barsillain pojalle synnyttänyt oli, joka oli Meholatilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'Ja hän antoi ne Gibeonilaisten käsiin, ja he hirttivät ne vuorella Herran eteen. Ja ne seitsemän lankesivat yhdellä haavalla: ja niin he surmattiin ensimäisinä päivinä elonajasta, ohran leikkaamisen alussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Niin Ritspa Aijan tytär otti säkin ja levitti sen kalliolle elon alusta, siihenasti että vesi olis pisaroinnut taivaasta heidän päällensä, eikä sallinut taivaan lintuja tulla heidän päällensä päivällä, eikä metsän petoja yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Ja ilmoitettiin Davidille, mitä Ritspa, Aijan tytär, Saulin jalkavaimo, tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Ja David läksi matkaan ja otti Saulin ja hänen poikansa Jonatanin luut Jabeksen asuvilta Gileadissa, jotka he Betsanin kadulta varastaneet olivat, jossa Philistealaiset heitä ripustaneet olivat siihen aikaan, kuin he surmasivat Saulin Gilboassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Ja otti sieltä Saulin luut ja hänen poikansa Jonatanin luut; ja he kokosivat myös niiden luut, jotka ripustetut olivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'Ja he hautasivat Saulin ja hänen poikansa Jonatanin luut BenJaminin maahan Zelaan, hänen isänsä Kisin hautaan, ja he tekivät kaikki niinkuin kuningas heille käskenyt oli: ja niin Jumala sovitettiin sitte maakunnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Niin taas nousi Philistealaisten sota Israelia vastaan. Ja David meni sotimaan palvelioinensa Philistealaisia vastaan; ja David väsyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Niin Jesbibenob, joka oli Raphan lapsia, jonka keihään ota painoi kolmesataa sikliä vaskea, ja jolla oli uudet sota-aseet, alkoi surmata Davidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mutta Abisai ZeruJan poika autti häntä, ja löi Philistealaisen, ja tappoi hänen. Niin Davidin palveliat vannoivat hänelle ja sanoivat: ei sinun pidä enää menemän meidän kanssamme sotaan, ettet valkeutta Israelissa sammuttaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Ja sen jälkeen tapahtui, että sota taas nousi Gobissa Philistealaista vastaan; ja Sibekai Husathilainen löi Saphan, joka myös oli Raphan lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Niin sota vielä nousi Gobissa Philistealaisia vastaan; ja Elhanan Jaere Oregiminin poika Betlehemiläinen löi Gatilaisen Goljatin, jonka keihään varsi oli niinkuin joku kangasorsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Sitälähin nousi vielä sota Gatissa; ja siellä oli pitkä mies, jolla oli kuusi sormea käsissä ja kuusi varvasta jaloissa, se on yhteen lukien neljäkolmattakymmentä; hän oli myös syntynyt Raphalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Ja kuin hän pilkkasi Israelia, löi hänen Jonatan Davidin veljen Simean poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Nämät neljä olivat syntyneet Raphalle Gatissa; ja he lankesivat Davidin ja hänen palveliainsa kätten kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Ja David puhui Herralle nämät veisun sanat sinä päivänä, jona Herra oli hänen vapahtanut kaikkein vihollistensa käsistä ja Saulin käsistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'Ja sanoi: Herra on minun kallioni, ja minun linnani, ja minun vapahtajani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Jumala on minun vahani, johon minä turvaan; minun kilpeni, ja minun autuuteni sarvi, ja minun varjelukseni, ja minun turvani; minun vapahtajani, joka minun pelastaa vääryydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Ylistettävää Herraa minä avukseni huudan; ja minä vapahdetaan vihollisistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Sillä kuoleman aallot ovat minun piirittäneet, ja Belialin ojat peljättivät minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Helvetin siteet kietoivat minun, ja kuoleman paulat ennättivät minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Ahdistuksessani minä avukseni huudan Herraa, ja minun Jumalani tykö minä huudan; niin hän kuulee minun ääneni templissänsä, ja minun parkuni tulee hänen korviinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Maa järisi ja vapisi, ja taivaan perustukset liikkuivat; he värisivät, kuin hän vihastui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Savu suitsi hänen sieramistansa ja kuluttavainen tuli hänen suustansa, niin että hiilet siitä syttyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Hän notkisti taivaat ja astui alas; ja synkiä pimeys oli hänen jalkainsa alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Ja hän astui Kerubimin päälle ja lensi, ja näkyi tuulen sulkain päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Hän pani pimeyden majaksi ympärillensä, ja paksut ja vedestä mustat pilvet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Siitä kirkkaudesta hänen edessänsä paloivat tuliset hiilet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Herra jylisti taivaassa, Ylimmäinen antoi pauhinansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Hän ampui nuolia ja hajoitti heitä, hän iski leimaukset ja peljätti heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Ja niin ilmestyivät meren kuljut, ja maan perustukset ilmaantuivat Herran kovasta nuhtelemisesta ja hänen sieramiensa hengen puhalluksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Hän lähetti korkeudesta ja otti minun ja veti minun ulos suurista vesistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Hän vapahti minun väkevistä vihollisistani, vainollisiltani, jotka olivat minua väkevämmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Ne ennättivät minun tuskapäivänäni; mutta Herra tuli minun turvakseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Hän vei minun ulos lakialle, ja pelasti minun; sillä hän mielistyi minuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Herra maksoi minulle vanhurskauteni jälkeen, hän antoi minulle kätteni puhtauden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Sillä minä pidän Herran tiet ja en ole jumalatoin minun Jumalaani vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Sillä kaikki hänen oikeutensa ovat silmäni edessä, ja hänen käskyjänsä en minä tyköäni hylkää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Vaan olen vakaa hänen edessänsä, ja vältän vääryyttä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Sentähden kostaa Herra minulle vanhurskauteni perästä, puhtauteni jälkeen hänen silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Pyhäin kanssa sinä olet pyhä, ja toimellisten kanssa toimellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Puhdasten kanssa sinä olet puhdas, ja nurjain kanssa sinä olet nurja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Sinä vapahdat ahdistetun kansan ja sinun silmäs ovat korkeita vastaan, ja sinä nöyryytät ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Sillä sinä Herra olet valkeuteni: Herra valaisee pimeyteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Sillä sinun kauttas minä sotaväen lävitse juoksen, ja Jumalassani karkaan muurin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Jumalan tie on täydellinen, Herran puhe tulella koeteltu: hän on kaikkein kilpi, jotka hänen päällensä uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Sillä kuka on Jumala, paitsi Herraa? ja kuka on kallio paitsi meidän Jumalaamme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Jumala on väkevyyteni ja voimani: hän avaa minun tieni täydellisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Hän tekee jalkani peurain kaltaiseksi, ja asettaa minun korkeuteni päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Hän opettaa käteni sotimaan ja käsivarteni vaskijoutsea jännittämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Ja sinä annoit minulle sinun autuutes kilven: Ja kuin sinä nöyryytät minun, teet sinä minun suureksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Sinä levitit minun askeleeni minun allani, ja ei minun kantapääni livistyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Minä ajan vihollisiani takaa ja hävitän heitä, Ja en palaja ennenkuin minä heidät hukutan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Minä hukutan heidät ja runtelen, ettei heidän pidä nouseman; heidän täytyy kaatua jalkaini alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Sinä valmistat minun voimalla sotaan, sinä taivutat minun alleni ne, jotka nousevat minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Ja sinä annat minulle viholliseni kaulan; ja minä kadotan vainoojani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'He huutavat, vaan ei ole auttajaa: Herran tykö, mutta ei hän vastaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Minä survon heitä niinkuin maan tomun, ja muserran heidän rikki ja hajoitan heidät niinkuin loan kaduilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Sinä pelastat minua riitaisesta kansasta, ja asetat minun pakanain pääksi: se kansa, jota en minä tuntenut, palvelee minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Muukalaiset lapset viekastelevat minua, korvan kuuloon he kuulevat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Muukalaiset lapset vaipuvat ja vapisevat siteistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Herra elää, ja kiitetty olkoon minun kallioni, ja ylistetty olkoon Jumala, minun autuuteni kallio!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Jumala, joka minulle koston antaa ja vaatii kansat minun alleni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Joka minua johdatat ulos vihollisistani ja korotat minun niistä, jotka karkaavat minua vastaan, sinä pelastat minua väkivaltaisesta miehestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Sentähden minä kiitän sinua Herra pakanain seassa, ja sinun nimelles kiitoksen veisaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Joka kuninkaallensa suuren autuuden osoittaa ja tekee laupiuden voidellullensa, Davidille ja hänen siemenellensä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Ja nämät ovat Davidin viimeiset sanat. David, Isain poika, sanoi, se mies sanoi, joka korotettu on, Jakobin Jumalan voideltu, ja suloinen Israelin psalmein veisaaja:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Herran Henki on puhunut minun kauttani, ja hänen sanansa on tapahtunut minun kieleni kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Israelin Jumala on sanonut minulle, Israelin turva on minulle puhunut, ihmisten hallitsiasta, vanhurskaasta, joka hallitsee Jumalan pelvossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Niinkuin valkeus on aamulla, kuin aurinko koittaa, varhain ilman pilvetä, ja paisteesta sateen jälkeen ruoho kasvaa maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Eikö minun huoneeni ole niin Jumalan tykönä? Sillä hän on tehnyt ijankaikkisen liiton minun kanssani, kaikella muodolla lujan ja vahvan; sillä se on kaikki minun autuuteni ja haluni; eikö se ole kasvava?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Mutta ilkiät ihmiset kaikki hävitetään niinkuin orjantappurat, joihin ei taideta käsin ruveta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Mutta jos joku tahtoo tarttua niihin, hänellä pitää täydellisesti oleman rauta ja keihään varsi; ja ne pitää kokonansa poltettaman tulella heidän sioissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Nämät ovat Davidin sankarien nimet: Josebbaselet Tahkemonilainen, ylimmäinen päämiehistä: hän oli se AdoniEtsniläinen, joka nousi kahdeksaasataa vastaan, jotka tapettiin yhdellä erällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Sitälähin oli Eleatsar Dodon poika Ahohin pojan, niiden kolmen sankarien keskellä Davidin kanssa, kuin he pilkkasivat Philistealaisia, jotka olivat sinne kokoontuneet sotaan, ja Israelin miehet menivät ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Se nousi ja löi Philistealaiset, siihenasti että hänen kätensä väsyi ja puuntui miekasta. Ja Herra antoi suuren autuuden siihen aikaan, niin että kansa palasi hänen jälkeensä ainoasti ryöstämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Hänen jälkeensä oli Samma Agen Hararilaisen poika: koska Philistealaiset kokosivat itsensä yhteen kylään ja siellä oli yksi peltosarka täynnä herneitä, ja kansa pakeni Philistealaisia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Silloin seisoi hän keskellä sarkaa ja varjeli sen, löi Philistealaiset, ja Herra antoi suuren autuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Ja nämät kolme ylimmäistä kolmenkymmenen keskellä tulivat alas elonaikana Davidin tykö Adullamin luolaan; ja Philistealaisten leiri oli Rephaimin laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Mutta David oli siihen aikaan linnassa, ja Philistealaisten kansa oli Betlehemissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Ja David himoitsi ja sanoi: kuka tuo minulle juoda vettä Betlehemin kaivosta portin tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Niin ne kolme sankaria menivät Philistealaisten leiriin ja ammensivat vettä Betlehemin kaivosta, joka on portin tykönä, kantoivat ja toivat Davidille; mutta ei hän tahtonut sitä juoda, vaan kaasi Herran eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'Ja sanoi: Herra, olkoon se minusta kaukana, että minä se tekisin: eikö tämä ole niiden miesten veri, jotka itsensä antoivat hengenvaaraan ja sinne menivät? Ja ei tahtonut sitä juoda. Tämän tekivät ne kolme sankaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai Joabin veli ZeruJan poika oli myös ylimmäinen kolmen keskellä, hän nosti keihäänsä ja löi kolmesataa, ja oli myös ylistetty kolmen keskellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Ja kaikkein jaloin kolmen keskellä ja oli heidän päämiehensä, mutta ei hän tullut niiden kolmen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Ja Benaja Jojadan poika, kuuluisan miehen poika suurista töistänsä Kabselista löi kaksi Moabin väkevää niinkuin jalopeuraa, ja hän meni alas ja löi yhden jalopeuran kaivon tykönä lumen aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Ja hän löi hirmuisen Egyptin miehen, jolla oli keihäs kädessä, mutta hän meni hänen tykönsä seipäällä, ja tempasi Egyptin miehen kädestä keihään, ja löi hänen kuoliaaksi omalla keihäällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Nämät teki Benaja Jojadan poika, ja oli ylistetty kolmen sankarin keskellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Ja oli jalompi kuin ne kolmekymmentä mutta ei hän tullut niiden kolmen tykö; ja David asetti hänen salaiseksi neuvonantajaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, Joabin veli, kolmenkymmenen keskellä, Elhanan Dodonin poika Betlehemistä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma Harodilainen, Elika Harodilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helets Paltilainen, Ira Ikeksen Tekoalaisen poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abieser Anatotilainen, Mebunai Husatilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Salmon Ahohilainen, Maharai Netophatilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb Baenan poika Netophatilainen, Ittai Ribain poika BenJaminin lasten Gibeasta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja Pirtagonilainen, Hiddai Gasin ojista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abialbon Arbatilainen, Asmavet Barhumilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eliaheba Saalbonilainen Jasennin Jonathanin pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Samma Hararilainen, Ahiam Sararin poika Ararilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Eliphelet Maakatin pojan Ahasbain poika, Eliam Ahitophelin Gilonilaisen poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hesrai Karmelilainen, Paerai Arbilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal Natanin poika Zobasta, Bani Gadilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek Ammonilainen; Naharai Beerotilainen, Joabin ZeruJan pojan sota-asetten kantaja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira Jitriläinen, Gareb Jitriläinen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uria Hetiläinen. Kaikki yhteen seitsemänneljättäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Ja Herran viha taas julmistui Israelia vastaan ja hän kehoitti Davidin heidän keskellensä, sanoen: mene ja lue Israel ja Juuda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Ja kuningas sanoi Joabille sodanpäämiehellensä: mene nyt kaikkein Israelin sukukuntain ympäri, ruveten Danista BerSebaan asti, ja lue kansa, että minä tietäisin kansan paljouden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Joab sanoi kuninkaalle: Herra sinun Jumalas enetköön siihen kansaan sata kertaa sen verran kuin siinä nyt on, että herrani kuninkaan silmät sen näkisivät; mutta mitä iloa on herrallani kuninkaalla siitä asiasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Mutta kuninkaan sana vahvistui Joabia ja sodanpäämiehiä vastaan. Niin Joab ja sotajoukon päämiehet menivät kuninkaan tyköä lukemaan Israelin kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Ja he menivät Jordanin ylitse ja sioittivat itsensä Aroeriin, oikialle puolelle sitä paikkaa, joka on keskellä Gadin ojaa, Jaeserin tykönä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Ja tulivat Gileadiin ja alhaiseen maahan Hadsiin, sitte tulivat he DanJaniin ja Zidonia ympärinsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Ja tulivat vahvaan kaupunkiin Tyroon ja kaikkiin Heviläisten ja Kanaanealaisten kaupunkeihin. Sitte he läksivät sieltä etelän puolelle Juudaa BerSebaan asti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Ja kävivät kaiken maan ympäri, ja tulivat yhdeksän kuukauden ja kahdenkymmenen päivän perästä Jerusalemiin jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Ja Joab antoi kuninkaalle kansan luvun, ja Israelissa oli kahdeksansataa tuhatta vahvaa miekan ulosvetävää sotamiestä; mutta Juudassa oli viisisataa tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Ja Davidin sydän tykytti sitte kuin kansa luettu oli, ja David sanoi Herralle: minä olen sangen suuresti syntiä tehnyt, että minä sen tein. Herra, käännä nyt palvelias pahateko pois; sillä minä olen tehnyt sangen tyhmästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Ja kuin David huomeneltain nousi, tuli Herran sana prophetan Gadin Davidin näkiän tykö, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Mene ja puhu Davidille: näin sanoo Herra: kolme minä panen sinun etees; valitse itselles niistä yksi, jonka minä sinulle teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Gad tuli Davidin tykö, ilmoitti ja sanoi hänelle: tahdotkos että nälkä tulee seitsemäksi ajastajaksi maakunnalles, taikka ettäs kolme kuukautta pakenet vihamiestes edellä ja he ajavat sinua takaa, eli että rutto on kolme päivää sinun maallas? Niin ota nyt vaari, ja katso, mitä minä hänelle vastaan, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'David sanoi Gadille: minulla on sangen suuri ahdistus; mutta salli meidän langeta Herran käsiin, sillä Herran armo on suuri. En minä tahdo langeta ihmisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Ja Herra antoi ruttotaudin tulla Israeliin, ruveten aamulla niin määrättyyn aikaan asti; ja kansaa kuoli Danista niin BerSebaan asti, seitsemänkymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Ja kuin enkeli ojensi kätensä Jerusalemin ylitse, kadottaaksensa häntä, niin Herra katui sitä pahaa ja sanoi enkelille, joka kansaa hävitti: kyllä jo on; pidä nyt kätes alallansa. Ja Herran enkeli oli Araunan Jebusilaisen riihen tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Kuin David näki enkelin, joka kansaa löi, sanoi hän Herralle: katso, minä olen syntiä tehnyt ja minä olen sen pahan tehnyt: mitä nämät lampaat ovat tehneet? Anna siis kätes olla minua vastaan ja minun isäni huonetta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Ja sinä päivänä tuli Gad Davidin tykö ja sanoi hänelle: mene ja rakenna Herralle alttari Jebusilaisen Araunan riiheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Ja David meni kohta niinkuin Gad sanoi ja Herra oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Mutta kuin Arauna käänsi itsensä, näki hän kuninkaan palvelioinensa tulevan tykönsä; niin Arauna läksi ulos ja lankesi kasvoillensa maahan kuninkaan eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Ja sanoi: miksi herrani kuningas tulee palveliansa tykö? David sanoi: riihtä ostamaan sinulta, rakentaakseni Herralle alttaria, että vitsaus lakkais kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arauna sanoi Davidille: herrani kuningas ottakaan ja uhratkaan niinkuin hänelle kelpaa. Katso, tässä on härkä polttouhriksi, reet ja kaikki härkäin kalut haloiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Nämät kaikki, kuningas, antaa Arauna kuninkaalle. Ja Arauna sanoi kuninkaalle: Herra sinun Jumalas leppyköön sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Mutta kuningas sanoi Araunalle: ei suinkaan, vaan minä ostan sen täydellisesti sinulta hinnalla; sillä en minä tee Herralle polttouhria siitä, joka minulle lahjaksi on annettu. Niin osti David riihen ja härjän viidelläkymmenellä hopiasiklillä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Ja rakensi Herralle siinä alttarin ja uhrasi polttouhreja ja kiitosuhreja; ja Herra leppyi maakunnalle, ja vitsaus lakkasi Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Ja kuin kuningas David oli vanhentunut ja ijälliseksi joutunut, ei hän voinut itsiänsä lämmittää, ehkä hän vaatteilla peitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Niin sanoivat hänen palveliansa hänelle: anna heidän etsiä herralleni kuninkaalle piika, joka neitsy on, joka seisois kuninkaan edessä, ja korjaisi häntä ja makais hänen sylissänsä, ja lämmittäis herraani, kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Ja he etsivät ihanan piian kaikista Israelin rajoista; ja he löysivät Abisagin Sunemista, ja veivät hänet kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Ja se oli sangen ihanainen piika, ja hän korjasi kuningasta ja palveli häntä, vaan ei kuningas tuntenut häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Mutta Adonia Haggitin poika korotti itsensä ja sanoi: minä tahdon olla kuningas; ja rakensi itsellensä vaunut ja hevosmiehiä, ja viisikymmentä miestä juoksemaan edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Ja hänen isänsä ei tahtonut tehdä häntä surulliseksi eläissänsä, että hän olis sanonut: kuinkas niin teet? Ja hän oli myös sangen ihanainen; ja oli hänen synnyttänyt Absalomin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Ja hän puhui Joabin ZeruJan pojan kanssa ja papin Abjatarin kanssa; ja he auttivat Adoniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mutta Zadok pappi, ja BenaJa Jojadan poika, ja Natan propheta, ja Simei, ja Rei, ja Davidin sankarit ei olleet Adonian kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Ja kuin Adonia uhrasi lampaita ja härkiä ja myös syötettyä karjaa Soheletin kiven tykönä, joka on läsnä Rogelin kaivoa, kutsui hän kaikki veljensä, kuninkaan pojat, ja kaikki Juudan miehet kuninkaan palveliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Mutta Natan prophetaa, ja Benajaa ja sankareita, ja veljeänsä Salomoa hän ei kutsunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Niin puhui Natan BatSeballe Salomon äidille, sanoen: etkös ole kuullut Adoniaa Haggitin poikaa tulleeksi kuninkaaksi? ja herramme David ei siitä mitään tiedä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Niin tule nyt, minä annan sinulle neuvoa, ettäs vapahtaisit sielus ja poikas Salomon sielun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Mene ja käy kuningas Davidin tykö, ja sano hänelle: herrani kuningas, etkös ole vannonut ja sanonut piialles: sinun poikas Salomo pitää oleman kuningas minun jälkeeni ja istuman minun istuimellani? Miksi siis Adonia on kuninkaaksi tullut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Katso, sinun vielä siellä puhuissas kuninkaan kanssa, tulen minä myös perässäs ja täytän puhees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Ja BatSeba meni kamariin kuninkaan tykö, ja kuningas oli juuri vanha; ja Abisag Sunemista palveli Kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Ja BatSeba nöyryytti itsensä ja kumarsi kuningasta. Kuningas sanoi: mitäs tahdot?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Hän sanoi hänelle: herrani, sinä vannoit piialles Herran sinun Jumalas kautta: sinun poikas Salomo pitää oleman kuningas minun jälkeeni ja istuman minun istuimellani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Mutta nyt, katso, Adonia on tullut kuninkaaksi, ja herrani kuningas, et sinä siitä mitään tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Hän on uhrannut härkiä ja syötettyä karjaa, ja monta lammasta, ja on kutsunut kaikki kuninkaan pojat, ja papin AbJatarin, ja Joabin sodanpäämiehen; mutta palveliaas Salomoa ei hän kutsunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Mutta sinä, Herrani kuningas, koko Israelin silmät katsovat sinun päälles, ettäs ilmoittaisit heidän edessänsä, kuka on istuva herrani kuninkaan istuimella hänen jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Muutoin tapahtuu, kuin herrani kuningas isäinsä kanssa nukkunut on, niin täytyy minun ja poikani Salomon vialliset olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Ja katso, vielä hänen puhuissansa kuninkaan kanssa, tuli Natan propheta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Ja he ilmoittivat kuninkaalle sanoen: katso, Natan propheta on täällä. Ja kuin hän tuli sisälle kuninkaan eteen, lankesi hän maahan kasvoillensa kuninkaan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Ja Natan sanoi: herrani kuningas, sanoitkos: Adonia pitää oleman kuningas minun jälkeeni ja istuman minun istuimellani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Sillä hän on tänäpänä mennyt ja uhrannut härkiä, ja syötettyjä karjaa, ja monta lammasta, ja on kutsunut kaikki kuninkaan pojat ja sodanpäämiehet, niin myös papin AbJatarin, ja katso, he syövät ja juovat hänen edessänsä, ja sanovat: onneksi kuninkaalle Adonialle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mutta minua sinun palveliaas, ja pappia Zadokia, ja BenaJaa Jojadan poikaa, ja palveliaas Salomoa ei ole hän kutsunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Onko se niin herraltani kuninkaalta käsketty, ja et sinä ole sitä asiata antanut tietää palvelialles, kuka herrani kuninkaan istuimella hänen jälkeensä on istuva?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Kuningas David vastasi ja sanoi: kutsukaat minulle BatSeba. Ja hän tuli kuninkaan eteen ja seisoi kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Ja kuningas vannoi ja sanoi: niin totta kuin Herra elää, joka minun sieluni on päästänyt kaikkinaisesta ahdistuksesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Niinkuin minä sinulle Herran Israelin Jumalan edessä vannonut olen ja sanonut: Salomo sinun poikas pitää oleman kuningas minun jälkeeni, ja hän pitää istuman minun istuimellani minun edestäni; niin minä teen tänäpänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Niin BatSeba lankesi kasvoillensa maahan ja kumarsi kuningasta, sanoen: onneksi herralleni kuningas Davidille ijankaikkisesti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Ja kuningas David sanoi: kutsukaat Zadok pappi, Natan propheta ja BenaJa Jojadan poika. Ja he tulivat kuninkaan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Ja kuningas sanoi heille: ottakaat kanssanne teidän herranne palveliat, ja asettakaat poikani Salomo minun muulini päälle, ja viekäät häntä Gihoniin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Ja Zadok pappi ja Natan propheta voidelkaan hänen Israelin kuninkaaksi. Ja soittakaat basunalla ja sanokaat: onneksi kuninkaalle Salomolle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Ja menkäät ylös hänen perässänsä, että hän tulis ja istuis minun istuimellani, ja olis kuningas minun edestäni: ja minä käsken hänen olla Israelin ja Juudan päämiehenä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Niin vastasi BenaJa Jojadan poika kuninkaalle ja sanoi: Amen! Sanokaan myös niin Herra, herrani kuninkaan Jumala!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Niinkuin Herra on ollut herrani kuninkaan kanssa, niin olkoon hän myös Salomon kanssa, ja tehköön hänen istuimensa suuremmaksi herrani, kuningas Davidin, istuinta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Ja pappi Zadok, ja Natan propheta ja BenaJa Jojadan poika ja Kreti ja Pleti menivät alas, ja asettivat Salomon kuningas Davidin muulin päälle ja veivät hänen Gihoniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'ja pappi Zadok otti öljysarven majasta ja voiteli Salomon, ja he soittivat basunalla, ja kaikki kansa sanoi: onneksi kuningas Salomolle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Ja kaikki kansa meni ylös hänen jälkeensä, ja kansa soitti huilulla, ja he olivat sangen suuresti iloissansa, että maa vapisi heidän äänestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Ja Adonia ja kaikki kutsutut, jotka hänen kanssansa olivat, kuulivat sen, ja he olivat jo atrioineet; ja kuin Joab kuuli basunan äänen, sanoi hän: mitä se meteli ja töminä tietää kaupungissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Ja kuin hän vielä puhui, katso, niin tuli Jonatan papin AbJatarin poika. Ja Adonia sanoi: tule, sillä sinä olet luja mies ja tuot hyviä sanomia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Jonatan vastasi ja sanoi Adonialle: totisesti, herramme kuningas David on tehnyt Salomon kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Ja kuningas on lähettänyt hänen kanssansa papin Zadokin, ja prophetan Natanin, ja BenaJan Jojadan pojan, ja Kretit ja Pletit: he ovat hänen istuttaneet kuninkaan muulin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Ja Zadok pappi ja Natan propheta ovat voidelleet hänen kuninkaaksi Gihonissa, ja he ovat sieltä menneet ylös iloissansa, niin että kaupunki tömisi. Se oli se meteli, kuin te kuulitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Vielä sitte istuu Salomo valtakunnan istuimella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Ja kuninkaan palveliat ovat myös menneet siunaamaan herraamme kuningas Davidia, sanoen: antakoon sinun Jumalas Salomolle paremman nimen kuin sinun nimes on, ja tehköön hänen istuimensa suuremmaksi kuin sinun istuimes on! Ja kuningas rukoili vuoteessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'On myös kuningas näin sanonut: kiitetty olkoon Herra Israelin Jumala, joka tänäpänä on antanut vielä istuvan minun istuimellani, että minun silmäni sen nähneet ovat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Niin hämmästyivät ja nousivat kaikki jotka Adonia kutsunut oli, ja menivät itsekukin tiellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Vaan Adonia pelkäsi Salomoa, nousi ja meni ja tarttui alttarin sarviin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Ja se ilmoitettiin Salomolle, sanoen: katso, Adonia pelkää kuningas Salomoa, ja katso, hän tarttui alttarin sarviin ja sanoi: vannokaan kuningas Salomo minulle tänäpänä, ettei hän lyö palveliaansa kuoliaaksi miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Salomo sanoi: jos hän tahtoo olla toimellinen mies, niin ei pidä yksikään karva hänestä lankeeman maan päälle; mutta jos jotain pahuutta hänessä löydetään, niin hänen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Ja kuningas Salomo lähetti ja tuotti hänen alas alttarilta, ja kuin hän tuli, rukoili hän kuningas Salomoa; mutta Salomo sanoi hänelle: mene huoneeses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Ja kuin Davidin aika lähestyi, että hänen piti kuoleman, käski hän pojallensa Salomolle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Minä menen kaiken maailman tietä: niin rohkaise nyt itses, ja ole mies!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Ja pidä mitä Herra sinun Jumalas on käskenyt, niin ettäs vaellat hänen teissänsä ja pidät hänen säätynsä, käskynsä, oikeutensa ja todistuksensa, niinkuin on kirjoitettu Moseksen laissa: ettäs toimellisesti tekisit kaikki, mitä sinä teet, ja kuhunka sinä sinus käännät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Että Herra vahvistais sanansa, jonka hän on minulle puhunut ja sanonut: jos sinun poikas kätkevät tiensä, että he vaeltavat uskollisesti minun edessäni kaikesta sydämestänsä ja kaikesta sielustansa, niin ei sinulta ikänä pidä puuttuman mies Israelin istuimelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Ja sinä myös tiedät, mitä Joab ZeruJan poika on tehnyt minulle, mitä hän teki kahdelle sodanpäämiehelle Israelissa, Abnerille Nerin pojalle ja Amasalle Jeterin pojalle, jotka hän tappoi, ja vuodatti sodanveren rauhassa, ja antoi tulla sodanveren vyönsä päälle, joka oli hänen suolillansa, ja kenkäinsä päälle, jotka olivat hänen jaloissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Tee toimes jälkeen, niin ettes anna hänen harmaita karvojansa rauhassa tulla hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Ja tee Barsillain Gileadilaisen lapsille laupius, että he syövät sinun pöydältäs, sentähden että he pitivät itsensä minun tyköni, kun minä pakenin veljes Absalomin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Ja katso, sinun tykönäs on Simei Geran poika Jeminin pojan Bahurimista, joka minua julmalla kirouksella kiroili mennessäni Mahanaimiin. Mutta hän tuli minua vastaan Jordanin tykönä, silloin vannoin minä Herran kautta ja sanoin: en minä tapa sinua miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Mutta älä sinä anna hänen viatoinna olla, sillä sinä olet toimellinen mies ja tiedät, mitäs teet hänelle, ettäs lähetät hänen harmaat karvansa verissä hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Niin nukkui David isäinsä kanssa ja haudattiin Davidin kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Ja aika, jona David oli ollut Israelin kuningas, oli neljäkymmentä ajastaikaa. Seitsemän ajastaikaa oli hän kuningas Hebronissa, ja kolmeneljättäkymmentä ajastaikaa Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Ja Salomo istui isänsä Davidin istuimella, ja hänen valtakuntansa vahvistettiin suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Mutta Adonia Haggitin poika tuli BatSeban Salomon äidin tykö, joka sanoi: tuletkos rauhallisesti? Hän sanoi: rauhallisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Ja sanoi: minulla on jotakin puhumista sinun kanssas. BatSeba sanoi; puhu!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Ja hän sanoi: sinä tiedät, että valtakunta oli minun, ja kaikki Israel oli kääntänyt kasvonsa minun puoleeni, että minä olisin kuningas; mutta nyt on valtakunta kääntynyt ja on tullut veljeni omaksi: Herralta on se hänelle tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Nyt rukoilen minä yhden rukouksen sinulta, ettes minulta sitä kieltäis. Ja hän sanoi hänelle: puhu!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Hän sanoi: puhu kuningas Salomolle, sillä ei hän sinulta kiellä: että hän antais minulle Abisagin Sunemista emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'BatSeba sanoi: oikein! minä puhun kuninkaalle sinun puolestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Ja BatSeba tuli kuningas Salomon tykö, puhumaan hänen kanssansa Adonian puolesta; ja kuningas nousi ja meni häntä vastaan, ja kumarsi häntä ja istui istuimellensa. Ja kuninkaan äidin eteen pantiin istuin, ja hän istui siihen hänen oikialle puolellensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Ja hän sanoi: minä rukoilen vähän rukouksen sinulta, älä sitä minulta kiellä. Kuningas sanoi hänelle: rukoile, äitini: en minä sinulta kiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Hän sanoi, annettakaan Abisag Sunemista veljelles Adonialle emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Niin vastasi kuningas Salomo ja sanoi äidillensä: miksi rukoilet Abisagia Sunemista Adonialle? Rukoile myös hänelle valtakuntaa: sillä hän on vanhin veljeni, ja hänellä on pappi AbJatar ja Joab ZeruJan poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Ja kuningas Salomo vannoi Herran kautta ja sanoi: Jumala tehköön minulle sen ja sen, jollei Adonia ole puhunut tätä sanaa henkeänsä vastaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Ja nyt, niin totta kuin Herra elää, joka minun vahvistanut on ja antanut minun istua isäni Davidin istuimella, joka minulle huoneen tehnyt on, niinkuin hän sanonut on, niin pitää Adonian tänäpänä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Ja kuningas Salomo lähetti BenaJan Jojadan pojan; hän löi häntä, niin että hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Ja kuningas sanoi papille AbJatarille: mene Anatotiin pellolles, sillä sinä olet kuoleman mies. Mutta en minä tapa sinua tänäpänä, sillä sinä olet kantanut Herran Jumalan arkkia isäni Davidin edessä, ja sinä olet kärsinyt, mitä ikänä isäni on kärsinyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Ja niin Salomo ajoi AbJatarin pois, ettei hän olisi Herran pappi; että Herran sana täyettäisiin, niinkuin hän Elin huoneesta puhunut oli Silossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Ja tämä sanoma tuli Joabin eteen; sillä Joab piti itsensä Adonian puoleen, vaikka ei hän ollut Absalomin kanssa; niin pakeni Joab Herran majaan ja tarttui alttarin sarviin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Ja se ilmoitettiin kuningas Salomolle, että Joab oli paennut Herran majaan, ja katso, hän seisoi alttarin tykönä. Niin Salomo lähetti BenaJan Jojadan pojan ja sanoi: mene ja lyö häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Ja kuin BenaJa tuli Herran majaan, sanoi hän hänelle: näin sanoo kuningas: mene tästä ulos. Vaan hän sanoi: en suinkaan, tässä minä tahdon kuolla. Ja BenaJa ilmoitti sen kuninkaalle jälleen ja sanoi: niin on Joab sanonut ja niin hän on vastannut minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Kuningas sanoi hänelle: tee niinkuin hän on sanonut, ja lyö häntä, ja hautaa häntä; ettäs käännät minusta ja minun isäni huoneesta sen viattoman veren pois, jonka Joab on vuodattanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Ja Herra maksakoon hänen verensä hänen päänsä päälle, että hän on lyönyt kaksi miestä, jotka hurskaammat ja paremmat olivat kuin hän, ja murhannut ne miekalla, niin ettei minun isäni David siitä mitään tietänyt: Abnerin Nerin pojan Israelin sodanpäämiehen ja Amasan Jeterin pojan Juudan sodanpäämiehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Ja heidän verensä tulkoon Joabin pään päälle ja hänen siemenensä pään päälle ijankaikkisesti. Mutta Davidille ja hänen siemenellensä, hänen huoneellensa ja istuimellensa olkoon rauha Herralta ijankaikkiseen aikaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Ja BenaJa Jojadan poika karkasi hänen päällensä ja tappoi hänen; ja hän haudattiin korpeen huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Ja kuningas asetti BenaJan Jojadan pojan hänen siaansa sotajoukon päälle; ja Zadokin papin asetti kuningas AbJatarin siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Ja kuningas lähetti ja antoi kutsua Simein, ja sanoi hänelle: rakenna sinulles huone Jerusalemiin ja asu siellä, ja älä mene sieltä sinne eli tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Jona päivänä sinä sieltä lähdet ja menet Kidronin ojan ylitse, niin tiedä totisesti, että sinun pitää totisesti kuoleman, ja sinun veres tulee sinun pääs päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Simei sanoi kuninkaalle: se on hyvä puhe kuin minun herrani kuningas puhunut on; niin on sinun palvelias tekevä. Niin Simei asui Jerusalemissa kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Niin tapahtui kolmen ajastajan jälkeen, että kaksi palveliaa karkasivat Simeiltä Akiksen Maekan pojan Gatin kuninkaan tykö; Simeille sanottiin: katso, sinun palvelias ovat Gatissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Niin Simei nousi ja satuloitsi aasinsa, ja läksi Gatiin Akiksen tykö, etsimään palvelioitansa. Ja Simei meni ja toi palveliansa Gatista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Ja Salomolle sanottiin Simein menneeksi Jerusalemista Gatiin ja tulleeksi jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Niin lähetti kuningas ja antoi kutsua Simein, ja sanoi hänelle: enkö minä vannonut sinulle Herran kautta, todistanut ja sanonut: jona päivänä sinä lähdet ulos ja menet sinne eli tänne, niin sinun pitää hyvin tietämän, että sinun pitää totisesti kuoleman? Ja sinä sanoit minulle: minä olen kuullut hyvän puheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Miksi et ole pitänyt Herran valaa ja sitä käskyä, jonka minä sinulle käskin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Ja kuningas sanoi Simeille: sinä tiedät kaiken sen pahuuden, jonka sinun sydämes tietää, kun sinä isälleni Davidille tehnyt olet, ja Herra on kostanut sinun pahuutes sinun pääs päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Ja kuningas Salomo on siunattu, ja Davidin istuin on vahvistettu Herran edessä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Ja kuningas käski BenaJaa Jojadan poikaa; hän meni ja löi hänen kuoliaaksi. Ja valtakunta vahvistettiin Salomon käden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Ja Salomo tuli Pharaon Egyptin kuninkaan vävyksi, ja otti Pharaon tyttären ja vei hänen Davidin kaupunkiin, siihen asti kuin hän oli päättänyt rakentaa hänellensä huoneen ja Herran huoneen, ja Jerusalemin ympärille muurin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Mutta kansa uhrasi silloin vielä korkeuksissa; sillä ei ollut vielä rakennettu huonetta Herran nimelle siihen aikaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Ja Salomo rakasti Herraa ja vaelsi isänsä Davidin säädyissä, paitsi että hän uhrasi ja suitsutti korkeuksissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Ja kuningas meni Gibeoniin uhraamaan, sillä siellä oli jaloin korkeus, ja Salomo uhrasi tuhannen polttouhria sillä alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Ja Herra ilmaantui Salomolle Gibeonissa yöllä unessa; ja Jumala sanoi: anos, mitä minä annan sinulle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo sanoi: sinä olet tehnyt minun isälleni Davidille sinun palvelialles suuren laupiuden, niinkuin hän vaelsi sinun edessäs totuudessa ja vanhurskaudessa, ja vakaalla sydämellä sinun kanssas: ja sinä olet pitänyt hänelle suuren laupiuden, ja olet antanut hänelle pojan, joka istuu hänen istuimellansa, niinkuin tänäpänä tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Ja nyt, Herra minun Jumalani, sinä olet tehnyt palvelias kuninkaaksi isäni Davidin siaan; ja minä olen nuorukainen ja en tiedä käydä ulos taikka sisälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Ja sinun palvelias on sinun kansas keskellä, jonka sinä olet valinnut, suuren kansan, jota ei kenkään lukea taikka kirjoittaa taida, paljouden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Anna sentähden palvelialles ymmärtäväinen sydän tuomita kansaas ja erottaa pahaa ja hyvää; sillä kuka taitaa tätä sinun suurta kansaas tuomita?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Ja tämä puhe kelpasi Herralle, että Salomo tätä anoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Ja Herra sanoi hänelle: ettäs tätä anoit, ja et anonut sinulles pitkää ikää, etkä anonut sinulles rikkautta, ja et anonut vihamiestes sieluja, vaan anoit sinulles tietoa ymmärtää oikeutta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Katso, minä olen tehnyt sinun sanais jälkeen: katso, minä olen antanut sinulle tietäväisen ja ymmärtäväisen sydämen, niin ettei sinun vertaistas ollut ole sinun edelläs eikä myös pidä tuleman sinun jälkees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Ja myös sitä mitä et sinä anonut, olen minä antanut sinulle: rikkautta ja kunniaa, niin ettei yhdenkään pidä sinun vertaises oleman kuningasten seassa kaikkena sinun elinaikanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Ja jos sinä vaellat minun teissäni ja pidät säätyni ja käskyni, niin kuin isäs David vaelsi, niin minä teen ikäs pitkäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Kuin Salomo heräsi, niin katso se oli uni; ja hän tuli Jerusalemiin ja seisoi Herran liitonarkin edessä, ja uhrasi polttouhria ja valmisti kiitosuhrin, ja teki pidon kaikille palvelioillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Silloin tuli kaksi porttonaista kuninkaan tykö, ja seisoivat hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Ja toinen vaimoista sanoi: herrani! minä ja tämä vaimo asuimme yhdessä huoneessa, ja minä synnytin hänen tykönänsä siinä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Ja tapahtui kolmantena päivänä sittekuin minä synnytin, synnytti myös tämä vaimo: ja me olimme ynnä, ja ei yksikään muukalainen ollut kanssamme siinä huoneessa, paitsi meitä kahta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Ja tämän vaimon lapsi kuoli yöllä; sillä hän makasi hänen päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Niin hän nousi puoliyöstä ja otti minun lapseni sivustani: ja piikas makasi, ja hän pani sen sivuunsa, ja kuolleen lapsensa pani hän minun sivuuni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Kuin minä aamulla heräsin imettämään lastani, ja katso, se oli kuollut. Niin minä taas katselin visusti päivän koittaissa lapsen, ja katso, ei se ollut minun poikani, jonka minä olin synnyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Niin toinen vaimo sanoi: ei se niin ole kuin sinä sanot, mutta minun lapseni elää ja sinun lapses on kuollut. Ja tämä sanoi: ei, mutta sinun lapses on kuollut ja minun lapseni elää. Ja näin he puhuivat kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Ja kuningas sanoi: tämä sanoo: tämä minun lapseni elää ja sinun lapses on kuollut. Ja taas tämä toinen sanoo: ei niin, mutta sinun lapses on kuollut ja minun lapseni elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Ja kuningas sanoi: tuokaat minulle miekka. Ja miekka tuotiin kuninkaan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Ja kuningas sanoi: jakakaat elävä lapsi kahtia, ja antakaat toinen puoli toiselle ja toinen puoli toiselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Niin sanoi se vaimo kuninkaalle, jonka elävä lapsi oli, sillä hänen äidillinen sydämensä paloi lapseensa, ja hän sanoi: Ah herrani! antakaat hänelle se elävä lapsi ja älkäät suinkaan tappako sitä. Mutta toinen sanoi: ei minulle eikä sinulle pidä annettaman, vaan jaettakaan kahdeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Niin kuningas vastasi ja sanoi: annettakaan hänelle tämä elävä lapsi, ja ei sitä pidä suinkaan tapettaman, sillä tämä on hänen äitinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Ja sen tuomion, jonka kuningas sanoi, kuuli kaikki Israel, ja he pelkäsivät kuningasta; sillä he näkivät, että Jumalan tieto oli hänessä, toimittaa tuomiota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Niin oli Salomo koko Israelin kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Ja nämät olivat hänen päämiehensä: AsarJa, papin Zadokin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoreph ja Ahia, Sisan pojat, olivat kirjoittajat; Josaphat Ahiludin poika kansleri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'BenaJa, Jojadan poika, sodanpäämies; Zadok ja AbJatar olivat papit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'AsarJa Natanin poika päämiesten haltia. Sabud pappi Natanin poika kuninkaan neuvonantaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ja Ahisar huoneenhaltia; Adoniram Abdanin poika oli veron päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Ja Salomolla oli kaksitoistakymmentä valtamiestä koko Israelissa, jotka murheen pitivät kuninkaasta ja hänen huoneestansa; ja kukin heistä toimitti ruan kuukautenansa, vuosivuodelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Ja nämä olivat heidän nimensä: Hurrin poika Ephraimin vuorella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dekerin poika Makassa, ja Saalbimissa ja BetSemeksessä, ja Elonissa ja BetHananissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Hesedin poika Arubotissa; hänellä oli Soko ja kaikki Hepherin maakunta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Abinadabin pojalla kaikki Dorin paikkakunta; jolla oli Taphat Salomon tytär emäntänä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baena Ahiludin poika Taanakissa ja Megiddossa, ja koko BetSeanissa, joka on liki Zartanaa Jisreelin alla, BetSeanista Mahalonin ketoon asti, niin tällä puolella Jokmeamia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Geberin poika Ramotista Gileadissa, jolla olivat Jairin kylät, Manassen pojan Gileadista, jolla oli Argobin niitty, joka on Basaniin päin, kuusikymmentä suurta muurattua kaupunkia vaskitelkinensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab Iddon poika oli Mahanaimissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaats Naphtalissa; ja hänkin otti Basmatin Salomon tyttären emännäksensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baena Husain poika Asserissa ja Alotissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josaphat Paruan poika Isaskarissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simei Elan poika BenJaminissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber Urin poika Gileadin maalla, Sihonin Amorilaisten kuninkaan maalla, ja Ogin Basanin kuninkaan, joka myös oli yksi niiden maakuntain valtamies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Mutta Juudaa ja Israelia oli paljo, niinkuin santaa meren tykönä paljouden tähden; he söivät ja joivat ja iloitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Ja Salomo hallitsi kaikissa valtakunnissa, hamasta Philistealaisten maakunnan virrasta Egyptin rajaan asti, jotka toivat hänelle lahjoja ja palvelivat Salomoa kaiken hänen elinaikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Ja Salomolla oli jokapäiväiseksi ruaksi kolmekymmentä koria sämpyläjauhoja, kuusikymmentä koria muita jauhoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Kymmenen lihavaa härkää, ja kaksikymmentä härkää laitumelta, ja sata lammasta, ilman peuroja, ja metsävuohia, ja valittua lihavaa karjaa ja lintuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Sillä hän hallitsi koko maakunnassa, sillä puolella virtaa, hamasta Dipsasta Gasaan asti, kaikkein kuningasten ylitse tällä puolella virtaa; ja hänellä oli rauha kaikella ympäristöllänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'Niin että Juuda ja Israel asuivat levollisesti, itsekukin viinapuunsa ja fikunapuunsa alla, Danista BerSebaan asti, niinkauvan kuin Salomo eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Ja Salomolla oli neljäkymmentä tuhatta hinkaloa hevosille vaunuinsa eteen, ja kaksitoistakymmentä tuhatta hevosmiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Ja nämä valtamiehet toimittivat kuningas Salomolle ruokaa ja kaikille jotka kuningas Salomon pöytää lähestyivät; kukin kuukaudellansa, niin ettei siitä mitään puuttunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'He toivat myös ohria ja olkia hevosille ja nopsille orhille, sinne kussa hän oli, kukin niinkuin hänelle käsketty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Ja Jumala antoi Salomolle viisauden ja sangen suuren ymmärryksen, niin myös rohkian sydämen, niinkuin sannan meren rannalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Niin että Salomon taito oli suurempi kuin kaikkein itäisen maan lasten ja Egyptiläisten taito.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Ja hän oli taitavampi kaikkia ihmisiä, ja taitavampi kuin Etan Estrahilainen, ja Heman, ja Kalkol, ja Darda, Makolin pojat, ja hänen nimensä oli kuuluisa ympäri kaikkein pakanain,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Ja puhui kolmetuhatta sananlaskua; ja hänen virsiänsä oli tuhannen ja viisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Ja puhui myös puista, sedristä, joka on Libanonissa, hamaan isoppiin asti, joka seinästä kasvaa. Niin puhui hän myös eläimistä, linnuista, matelevaisista ja kaloista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Ja kaikista kansoista tultiin kuulemaan Salomon taitoa, ja kaikilta maan kuninkailta, jotka olivat kuulleet hänen taidostansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Ja Hiram, Tyron kuningas, lähetti palveliansa Salomon tykö; sillä hän oli kuullut, että he olivat hänen voidelleet kuninkaaksi isänsä siaan; sillä Hiram rakasti Davidia niinkauvan kuin hän eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Ja Salomo lähetti Hiramille, ja käski hänelle sanoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Sinä tiedät, ettei isäni David taitanut rakentaa Herran Jumalansa nimelle huonetta, sen sodan tähden, joka oli hänen ympärillänsä, siihen asti kuin Herra antoi heidät hänen jalkainsa alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Mutta nyt on Herra minun Jumalani antanut levon ympäristölläni, niin ettei vihollista eli pahaa estäjää ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Katso, minä aion rakentaa huoneen Herran Jumalani nimelle, niinkuin Herra on puhunut isälleni Davidille, sanoen: sinun poikas, jonka minä sinun siaas asetan istuimelles, pitää rakentaman minun nimelleni huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Niin käske nyt hakata minulle sedripuita Libanonista, ja että minun palveliani olisivat sinun palveliais kanssa: ja minä annan sinulle sinun palveliais palkan kaiken sen jälkeen kuin sinä sanot; sillä sinä tiedät, ettei meillä ole yhtään miestä, joka taitaa hakata puita niinkuin Zidonilaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Mutta kuin Hiram kuuli Salomon puheen, iloitsi hän suuresti ja sanoi: kiitetty olkoon Herra tänäpänä, joka on antanut Davidille taitavan pojan tämän paljon kansan päälle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Ja Hiram lähetti Salomon tykö, sanoen: minä olen kuullut, mitä minulle olet lähettänyt, ja minä teen myös kaiken sinun tahtos jälkeen, sedripuissa ja hongissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Ja minun palveliani pitää ne vetämän Libanonista mereen, ja minä annan ne panna lauttoihin merellä, ja vien siihen paikkaan, kuhunka sinä minun käsket, ja minä hajoittelen ne siellä, ja anna sinä ne sieltä ottaa. Mutta tee sinä myös minun tahtoni, ettäs annat minun perheelleni leivän ainetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Ja niin antoi Hiram Salomolle sedripuita ja honkia, niin paljo kuin hän tahtoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Ja Salomo antoi Hiramille kaksikymmentä tuhatta koria nisuja, hänen perheellensä ravinnoksi, ja kaksikymmentä koria survottua öljyä: niin antoi Salomo Hiramille joka vuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Ja Herra antoi Salomolle taidon, niinkuin hän hänelle luvannut oli. Ja Salomon ja Hiramin välillä oli rauha, ja he tekivät myös liiton keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Ja Salomo antoi valita miesluvun koko Israelista, ja valittuin luku oli kolmekymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Ja hän lähetti heidät Libanoniin, kymmenentuhatta kuukaudeksi vuorottain, niin että he olivat yhden kuukauden Libanonissa ja kaksi kuukautta kotonansa; ja Adoniram oli sen miesluvun päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'ja Salomolla oli seitsemänkymmentä tuhatta, jotka kuormia kantoivat, ja kahdeksankymmentä tuhatta, jotka vuorella hakkasivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Ilman ylimmäisiä Salomon käskyläisiä, jotka työn päälle asetetut olivat, kolmetuhatta ja kolmesataa, jotka vallitsivat kansaa joka työtä teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Ja kuningas käski heidän vetää suuria kiviä, kalliita kiviä, hakatuita kiviä huoneen perustukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Ja Salomon rakentajat, ja Hiramin rakentajat ja Giblimiläiset, vuolivat ja valmistivat puita ja kiviä huoneen rakennukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Ja tapahtui neljännelläsadannella ja kahdeksannellakymmenennellä ajastajalla Israelin lasten lähtemisen jälkeen Egyptin maalta, neljännellä ajastajalla sittekuin Salomo oli tullut Israelin kuninkaaksi, Sivin kuukaudella, joka on se toinen kuukausi, että huone rakennettiin Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Ja huone, jonka kuningas Salomo rakensi Herralle, oli kuusikymmentä kyynärää pitkä, kaksikymmentä kyynärää leviä ja kolmekymmentä kyynärää korkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Ja esihuone templin edessä oli kaksikymmentä kyynärää pitkä, huoneen leveyden jälkeen, ja kymmenen kyynärää leviä, huoneen edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Ja teki akkunan huoneen päälle, sisältä avaraksi ja ahtaaksi ulkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Ja hän rakensi käytävän seinää myöten huoneen ympäri, niin että se kävi kirkon ja kuorin ympäri, ja teki solat ulkonaiselle puolelle yltympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Se alimainen käytävä oli viisi kyynärää leviä, ja keskimäinen kuusi kyynärää leviä, ja kolmas seitsemän kyynärää leviä; sillä hän asetti malat ulkoa huonetta ympäri, niin ettei ne olis sattuneet huoneen seinään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Ja kuin huone rakennettiin, rakennettiin se kokonaisista kivistä, jotka tuodut olivat, niin ettei yhtään vasaraa, eikä kirvestä, eikä yhtään rauta-asetta kuulunut siinä rakennuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Ja ovi keskimäiseen solaan oli oikialla puolella huonetta, niin että mentiin kieroja astuimia myöten ylös keskimäiseen käytävään, ja keskimäisestä kolmanteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Ja niin rakensi hän huoneen ja päätti sen, ja kattoi huoneen sedripuisilla kaarimaloilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Hän rakensi myös käytävän koko huoneen ympäri, viisi kyynärää korkian, jonka hän yhdisti huoneesen sedripuilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Ja Herran sana tuli Salomolle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Tämä on huone, jonkas rakennat; jos sinä vaellat minun säädyissäni, ja teet minun oikeuteni, ja pidät kaikki minun käskyni, vaeltain niissä, niin minä vahvistan minun sanani sinun kanssas, kuin minä isälles Davidille sanonut olen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'Ja minä asun Israelin lasten keskellä, ja en hylkää kansaani Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Niin Salomo rakensi huoneen ja päätti sen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Ja kaunisti huoneen seinät sisältä sedripuisilla laudoilla, huoneen permannosta niin lakeen asti, ja kaunisti sisältä puilla, ja teki huoneen permannon honkaisista laudoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Ja hän rakensi huoneen sivuilta sedripuisen seinän, kaksikymmentä kyynärää pitkän, permannosta kattoon asti, ja teki siihen sisälle kuorin kaikkein pyhimpään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Ja huone oli neljäkymmentä kynärää pitkä, se esipuoli templistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Koko huone oli sisältä aivan sedripuusta, kaivettu nuppien ja kukkaisten muodolla: kaikki sedripuusta, ja ei yhtään kiveä näkynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Mutta kuorin hän valmisti huoneen sisälle, Herran liitonarkkia pantaa siihen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Ja kuorin edustan kaksikymmentä kyynärää pitkän, kaksikymmentä kyynärää leviän ja kaksikymmentä kyynärää korkian; ja hän silasi sen selkiällä kullalla ja kaunisti alttarin sedripuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Ja Salomo silasi huoneen sisältä selkiällä kullalla, ja teki kultaiset vitjat teljeksi kuorin eteen, jonka hän kullalla silannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Ja hän silasi koko huoneen kullalla siihenasti että koko huone valmiiksi tuli, niin myös koko alttarin, joka kuorissa oli, silasi hän kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Hän teki myös kuoriin kaksi Kerubimia öljypuista, kymmenen kyynärää korkiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'Viisi kyynärää pitkä oli kummankin Kerubimin siipi, niin että kymmenen kyynärää oli yhden siiven äärestä niin toisen siiven ääreen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Niin että sillä toisella Kerubimilla oli myös kymmenen kyynärää, ja oli yhtäläinen mitta ja sia molemmilla Kerubimilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Niin että yksi Kerubim oli kymmenen kyynärää korkia; niin oli myös se toinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Ja hän pani ne Kerubimit keskelle sisimäistä huonetta, ja Kerubimit levittivät siipensä, niin että yhden siipi sattui tähän seinään ja toisen Kerubimin siipi sattui toiseen seinään; mutta keskellä huonetta sattui siipi siipeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Ja hän silasi Kerubimit kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Ja kaikkein huoneen seinäin ympäri antoi hän tehdä pyörtyjä töitä, kaivetuita Kerubimeja, palmuja ja avoimia kukkasia sisälle ja ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Ja hän silasi huoneen permannon kullalla sisältä ja ulkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Ja kuorin läpikäytävään teki hän kaksi ovea öljypuista, viisikulmaisilla päällispuilla ja pihtipielillä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Ja niihin molempiin oviin antoi hän leikata pyörtyjä töitä, Kerubimeja, palmuja ja avoimia kukkaisia, ja silasi ne kullalla, ja levitti kultaa Kerubimein ja palmuin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Niin teki hän myös templin läpikäytävään neljäkulmaiset pihtipielet öljypuista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'Ja kaksi ovea hongasta, niin että kummassakin ovessa oli kaksi osaa ja molemmat saranoillansa juoksevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Ja hän kaivoi Kerubimeja, palmuja ja avoimia kukkaisia, ja silasi ne kullalla, kohdastansa leikkauksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Ja sitte rakensi hän sisimäisen pihan kolmella rivillä hakatuista kivistä ja yhdellä rivillä vuolluista sedripuista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Neljännellä ajastajalla perustettiin Herran huone Sivin kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Ja ensimmäisellä ajastajalla toistakymmentä Buulin kuulla (se on kahdeksas kuukausi) päätettiin huone kaluinensa, kaiken sen jälkeen kuin sen oleman piti. Ja hän rakensi sen seitsemänä ajastaikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Mutta Salomo rakensi huonettansa kolmetoistakymmentä ajastaikaa, ennenkuin se täydellisesti valmiiksi tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Ja hän rakensi Libanonin metsästä huoneen, sata kyynärää pituudelle, viisikymmentä kyynärää leveydelle ja kolmekymmentä kyynärää korkeudelle; neljällä taholla olivat sedripuiset patsaat, ja vuollut sedripuiset kaaret patsasten päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Ja se oli peitetty sedripuisilla laudoilla ylhäältä kaarten ylitse, jotka olivat patsasten päällä, joita oli viisiviidettäkymmentä, viisitoistakymmentä kullakin taholla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Ja kolme akkunariviä, kolmeen kertaan suutasuuksin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Ja kaikki ovet ja pihtipielet olivat nelikulmaiset, ja akkunat suutasuuksin kolmeen kertaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Hän rakensi myös patsasten esihuoneen, viisikymmentä kyynärää pituudelle ja kolmekymmentä kyynärää laveudelle; ja esihuone oli niiden kohdalla, ja patsaat ja paksut kaaret niiden kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Ja myös tuomio-istuimen esihuoneen tuomitaksensa siinä; tuomio-istuimen hän teki ja peitti molemmat permannot sedripuilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Niin myös omaan huoneesensa, jossa hän itse asui, toisen pihan sisälliselle puolelle esihuonetta, joka oli tehty niinkuin se toinenkin huone. Hän teki myös huoneen Pharaon tyttärelle, jonka Salomo emännäksensä ottanut oli, sen esihuoneen kaltaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Nämät kaikki olivat kalliista kivistä, mitan jälkeen vuolluista ja sahalla leikatuista sisältä ja ulkoa, perustuksesta kattoon asti, ja vielä ulkoiselta puolen isoon pihaan saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Perustukset olivat myös kallista kivistä ja suurista kivistä: kymmenen kyynärän kivistä ja kahdeksan kyynärän kivistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Ja niiden päällä oli muita kalliita kiviä mitan jälkeen vuoltuja ja myös sedripuita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Mutta sen suuren pihan ympäri oli kolme riviä vuoltuja kiviä ja yksi rivi sedripuisia lautoja, niin myös Herran huoneen sisäpuolella ja esihuoneen sisällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Ja kuningas Salomo lähetti ja noudatti Hiramin Tyrosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Joka oli lesken poika Naphtalin suvusta, ja hänen isänsä oli myös ollut Tyrolainen, vaskiseppä; ja hän oli taidolla, ymmärryksellä ja tiedolla lahjoitettu, kaikkinaisia vaskitöitä tekemään. Koska hän tuli kuningas Salomon tykö, niin hän teki kaikki hänen työnsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Ja hän valmisti kaksi vaskipatsasta, kummankin kahdeksantoistakymmentä kyynärää korkiaksi, ja yhden langan kahdentoistakymmenen kyynärän pituiseksi, kumpaakin patsasta ympäriinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Ja teki kaksi valettua vaskista kruunua asettaaksensa patsasten päihin; ja kumpikin kruunu oli viisi kyynärää korkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Verkot (teki hän) verkon tavalla, ja köydet niin kuin renkaat kruunuihin, jotka olivat ylhäällä patsasten päässä, seitsemän kumpaankin kruunuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Ja teki patsaat ja kaksi riviä ympäri yhden verkon päälle, peittämään kruunuja, jotka olivat granatin omenain päällä, ja niin hän myös teki toiselle kruunulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Ja ne kruunut, jotka olivat patsasten päässä, olivat tehdyt niinkuin kukkaiset esihuoneessa, neljä kyynärää suuret,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Ja kruunut kahden patsaan päällä ylhäällä keskipaikan kohdalla, jonka päällä verkko oli, ja kaksisataa granatin omenaa rivittäin ympärinsä toisen kruunun päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Ja hän nosti ne patsaat templin esihuoneen eteen, ja sen patsaan, jonka hän oikialle puolelle asetti, kutsui hän Jakin, ja sen patsaan, jonka hän asetti vasemmalle puolelle, kutsui hän Boas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Ja ne seisoivat patsasten päissä, tehdyt niinkuin kukkaiset; ja niin päätettiin patsasten teko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Ja hän teki valetun järven kymmenen kyynärää leviän, yhdestä partaasta niin toiseen ympyriäisen ja viisi kyynärää korkian, ja nuora, kolmekymmentä kyynärää pitkä, kävi sen ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Ja nupit olivat järven partaan alla, jotka kävivät sen ympäri, kymmenen jokaisella kyynärällä järveä ympäri; ja nupit olivat kokonansa valetut kahteen riviin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Ja se seisoi kahdentoistakymmenen härjän päällä: kolme heistä käänsi itsensä pohjoiseen, kolme länteen, kolme etelään, ja kolme itään päin; ja se järvi oli ylhäällä heidän päällänsä, ja kaikki heidän takaiset puolensa sisällekäsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Ja se oli kämmenen paksuus, ja sen parras oli tekoansa niinkuin maljan parras ja niinkuin ulospuhkeeva kukkainen; ja se veti kaksituhatta batia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Hän teki myös kymmenen vaskista istuinta; neljä kyynärää oli itsekukin istuin pitkä ja neljä kyynärää leviä, vaan kolmekyynärää korkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Ja ne istuimet olivat niin tehdyt, että niissä olivat laidat; ja ne laidat olivat palletten välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Ja laidoissa palletten välillä olivat jalopeurat, härjät ja Kerubimit, ja palletten päällä ylhäällä oli vahva virvanto; mutta jalopeurain ja härkäin alla olivat venytetyt jatkokset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Ja jokaisella istuimella oli neljä vaskista ratasta vaskisten ijesten kanssa, ja niissä olivat neljällä kulmalla niskat, jotka niskat olivat kattilaan alle valetut, kunkin jatkoksen kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Ja sen koverrus oli seppeleen sisäpuolelta kyynärää korkia, jonka keskus oli puolitoista kyynärää leviä: olivat myös sen vierellä leikkaukset; mutta niiden laidat olivat nelitahkoiset ja ei ympyriäiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Vaan ne neljä ratasta seisoi juuri laitain alla, ja ratasten ikeet olivat istuinta liki; jokainen ratas oli puolitoista kyynärää korkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Ja pyörät olivat tehdyt niinkuin vaunuin pyörät, ja heidän napansa, kappansa, kehrävartensa ja kierunsa olivat kaikki valetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Ja ne neljä niskaa jokaisen istuimen neljässä kulmassa oli myös istuimessa kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Ja istuimen päässä oli puolen kyynärän korkeus, joka oli kokonansa ympyriäinen; oli myös kunkin istuimen päässä heidän kahvansa, ja hänen laitansa olivat itse hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Ja hän antoi kaivaa takaisiin paikkoihin, kahvoihin ja laitoihin, Kerubimit, jalopeurat ja palmupuita, toinen toisensa tykö ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Näin teki hän ne kymmenen valettua istuinta: heillä kaikilla oli yksi muoto, yksi mitta, yksi sia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Ja hän teki kymmenen vaskikattilaa; niin että kukin kattila veti neljäkymmentä batia, ja kukin kattila oli neljä kyynärää suuri, yksi kattila oli yhden istuimen päällä, ja niin kymmenellä istuimella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Ja hän asetti viisi istuinta huoneen oikialle sivulle ja toiset viisi sen vasemmalle sivulle; mutta järven pani hän huoneen oikialle sivulle eteen, idän puoleen, etelän kohdalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Ja Hiram teki myös patoja, lapioita ja maljoja; ja niin Hiram päätti kaiken työn, minkä hän teki kuningas Salomolle Herran huoneesen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Ne kaksi patsasta ja ne kaksi ympyriäistä kruunua, jotka kahden patsaan päällä olivat, ja ne kaksi verkkoa, peittämään kahta ympyriäistä kruunua, patsasten päässä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'Ja ne neljäsataa granatin omenaa, kahden verkon päällä, ja kaksi riviä granatin omenia, kunkin verkon päällä, peittämään kahta ympyriäistä kruunua patsasten päässä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Ja ne kymmenen istuinta ja kymmenen kattilaa istuinten päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'Ja yhden järven ja kaksitoistakymmentä härkää järven alle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Ja padat, lapiot ja maljat, ja kaikki nämä astiat, jotka Hiram teki kuningas Salomolle Herran huoneesen, selkiästä vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Jordanin kedolla antoi kuningas Salomo ne valaa, savisessa töyrässä Sukkotin ja Zartanin välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Ja Salomo antoi kaikki nämä astiat olla (punnitsemata); sillä vaskea oli ylen paljo: ei kysytty vasken painoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Ja Salomo teki kaikki kalut, mitkä Herran huoneessa tarvittiin: kultaisen alttarin ja kultaisen pöydän, jolla näkyleivät pidettiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'Viisi kynttiläjalkaa oikialle ja viisi vasemmalle puolelle kuorin eteen, puhtaasta kullasta, kultaisten kukkaisten, lamppuin ja niistinten kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'Niin myös maljoja, vateja, kuppeja, lusikoita ja pannuja puhtaasta kullasta; ja olivat huoneen saranat huoneen sisimäisissä ovissa, joka oli se kaikkein pyhin, ja templin huoneen oven saranat aivan puhtaasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Näin kaikki työ päätettiin, minkä kuningas Salomo teki Herran huoneesen. Ja Salomo kantoi sinne kaikki mitä hänen isänsä David pyhittänyt oli, hopiaa ja kultaa, ja astioita, ja pani Herran huoneen tavaroihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Silloin kokosi Salomo Israelin vanhimmat, kaikki sukukuntain ylimmäiset ja isäin päämiehet Israelin lasten seasta kuningas Salomon tykö Jerusalemiin, viemään Herran liitonarkkia Davidin kaupungista, se on Zion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Ja kaikki Israelin miehet kokoontuivat kuningas Salomon tykö Ethanimin kuukaudella, juhlapäivänä, se on seitsemäs kuukausi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Ja kuin kaikki Israelin vanhimmat tulivat kokoon, nostivat papit arkin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'ja kantoivat Herran arkin ja seurakunnan majan, ja kaikki pyhän kalut, jotka majassa olivat: ne veivät papit ja Leviläiset ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Ja kuningas Salomo ja koko Israelin joukko, joka hänen tykönänsä itsensä oli koonnut, menivät hänen kanssansa arkin edellä, ja uhrasivat lampaita ja karjaa, joita ei arvattu eikä luettu paljouden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Ja näin kantoivat papit Herran liitonarkin siallensa templin kuoriin, kaikkein pyhimpään, Kerubimin siipein alle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Sillä Kerubimit hajoittivat siipensä arkin siaan, ja Kerubimit varjosivat arkin ja korennot ylhäältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Ja korennot vedettiin niin pitkälle ulos, että niiden päät näkyivät pyhästä kuorin eteen; vaan ulkoapäin ne eivät näkyneet; ja ne ovat siellä tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Arkissa ei ollut mitään, paitsi Moseksen kahta kivistä taulua, jotka Moses sinne pani Horebissa, kuin Herra liiton teki Israelin lasten kanssa, heidän lähteissänsä Egyptistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Ja tapahtui, kun papit menivät pyhästä ulos, niin täytti pilvi Herran huoneen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Niin ettei papit saaneet seisoa ja tehdä virkaansa pilven tähden; sillä Herran kunnia täytti Herran huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Silloin sanoi Salomo: Herra on sanonut asuvansa pimeydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Minä olen tosin rakentanut sinulle huoneen asumiseksi ja istuimen, ettäs siellä asuisit ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Ja kuningas käänsi kasvonsa ja siunasi koko Israelin joukon. Ja koko Israelin joukko seisoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Ja hän sanoi: kiitetty olkoon Herra Israelin Jumala, joka suullansa minun isälleni Davidille puhunut on, ja on täyttänyt kädellänsä, ja sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Siitä päivästä, jona minä johdatin minun kansani Israelin Egyptistä, en ole minä yhtään kaupunkia valinnut kaikesta Israelin sukukunnasta, että minulle huone rakennettaisiin, niin että minun nimeni olis siellä: mutta Davidin minä olen valinnut minun kansani Israelin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Ja minun isäni David aikoi rakentaa huoneen Herran Israelin Jumalan nimelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Mutta Herra sanoi isälleni Davidille: ettäs aioit rakentaa minun nimelleni huonetta, olet sinä sen hyvästi tehnyt, ettäs sen aioit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Kuitenkin ei sinun pidä sitä huonetta rakentaman; vaan sinun poikas, joka sinun kupeistas tulee, hän on rakentava minun nimelleni huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Ja Herra on vahvistanut sanansa, jonka hän puhunut on; sillä minä olen noussut minun isäni Davidin siaan, ja istun Israelin istuimella, niinkuin Herra puhunut on, ja olen rakentanut Herran Israelin Jumalan nimelle huoneen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Ja olen siellä valmistanut arkille sian, kussa Herran liitto on, jonka hän teki meidän isillemme, johdattaissansa heitä Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Ja Salomo seisoi Herran alttarin edessä koko Israelin joukon edessä, ja hajoitti kätensä ylös taivaasen päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'Ja sanoi: Herra Israelin Jumala! ei ole yhtään Jumalaa sinun vertaistas, ylhäällä taivaasa taikka alhaalla maassa, joka pidät liiton ja laupiuden palvelioilles, jotka sinun edessäs kaikesta sydämestänsä vaeltavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Joka olet pitänyt sinun palvelialles Davidille, minun isälleni, kaikki mitä sinä hänelle puhunut olet; sinun suullas sinä olet puhunut sen, ja sinä olet täyttänyt sen kädelläs, niinkuin se tänäpänä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Niin siis, Herra, Israelin Jumala! pidä sinun palvelialles Davidille minun isälleni se minkä sinä hänelle puhunut olet ja sanonut: ei pidä sinulta miestä puuttuman minun edessäni, joka istuu Israelin istuimella: ainoastaan jos sinun lapses pitävät heidän tiensä, vaeltaaksensa minun edessäni, niinkuin sinä olet vaeltanut minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Nyt, Israelin Jumala! anna sanas olla totinen, jonka sinä palvelialles Davidille minun isälleni puhunut olet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Luuletkos Jumalan maan päällä asuvan? Katso taivaat ja taivasten taivaat ei voi sinua käsittää: kuinka siis tämä huone, jonka minä rakensin, sen tekis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Niin käännä siis sinuas palvelias rukoukseen ja anomiseen, Herra minun Jumalani! ettäs kuulisit minun kiitokseni ja rukoukseni, jonka palvelias tänäpänä rukoilee sinun edessäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Että sinun silmäs avoinna olis tämän huoneen puoleen yöllä ja päivällä, ja siinä paikassa, jostas sanonut olet: minun nimeni pitää oleman siellä; ettäs kuulisit sen rukouksen, jonka sinun palvelias rukoilee tässä paikassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Ja kuulisit sinun palvelias ja kansas Israelin hartaan rukouksen, jonka he tässä paikassa rukoilevat: ja sinä kuulisit sen siellä, kussas asut taivaissa, ja koskas sen kuulet, olisit armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Koska joku rikkoo lähimmäistänsä vastaan, ja ottaa valan päällensä, jolla hän hänensä velkapääksi tekee, ja vala tulee sinun alttaris eteen tässä huoneessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Ettäs kuulisit taivaissa, ja saattaisit palvelioilles oikeuden, ettäs tuomitsisit jumalattoman ja antaisit hänen tiensä tulla hänen päänsä päälle, ja vanhurskaaksi tekisit viattoman, ja tekisit hänelle hänen oikeutensa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Jos sinun kansas Israel lyödään vihamiestensä edessä, että he ovat syntiä tehneet sinua vastaan, ja he kääntävät itsensä sinun tykös, ja tunnustavat sinun nimes, ja rukoilevat ja anteeksi anovat sinulta tässä huoneessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Ettäs kuulisit taivaissa, ja sinun kansas Israelin synnille armollinen olisit, ja johdattaisit heitä sille maalle jälleen, jonka heidän isillensä antanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Jos taivaat suljetut ovat, niin ettei sada, että he sinua vastaan rikkoneet ovat, ja rukoilevat tässä siassa, ja tunnustavat sinun nimes, ja kääntävät itsensä synnistänsä, ettäs rankaiset heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Ettäs kuulisit heitä taivaissa, ja olisit sinun palvelias ja kansas Israelin synnille armollinen, että osoitat heille sen hyvän tien, jota heidän vaeltaman pitää; ja annat sataa sinun maas päälle, jonka kansalles perimiseksi antanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Jos kallis aika tulee maalle, eli rutto tulee, taikka pouta, eli ruoste, taikka kaskat, eli jyvämadot maan päälle tulevat, taikka vihamiehet piirittävät maakunnassa heidän porttinsa, taikka kaikkinainen vitsaus, eli kaikkinainen sairaus tulee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Kaikki rukoukset, kaikki anteeksi anomiset mitkä kaikki ihmiset, kaikki sinun kansas Israel tekevät, koska he ymmärtävät vitsauksen itsekukin sydämessänsä, ja hajoittavat kätensä tämän huoneen puoleen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Ettäs silloin kuulisit taivaissa, siitä siasta, kussas asut, ja olisit armollinen ja tekisit sen niin, ettäs annat itsekullekin niinkuin hän vaeltanut on, niin kuin sinä hänen sydämensä tunnet; sillä sinä ainoastaan tunnet kaikkein ihmisten lasten sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Että he aina sinua pelkäisivät, niinkauvan kuin he maan päällä elävät, jonkas meidän isillemme antanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Jos myös joku muukalaisista, joka ei ole sinun kansaas Israelia, tulee kaukaiselta maalta sinun nimes tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'Sillä he saavat kuulla sinun suuresta nimestäs, ja voimallisesta kädestäs, ja ojetusta käsivarrestas: ja joku tulee rukoilemaan tähän huoneesen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Ettäs kuulisit taivaissa siitä siasta, kussas asut, ja tekisit kaiken sen, minkä muukalainen sinulta anoo: että kaikki kansa maan päällä tuntis sinun nimes, että he myös pelkäisivät sinua niinkuin sinun kansas Israel, ja tietäisivät, että sinun nimeäs avuksihuudetaan tässä huoneessa, jonka minä rakentanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Jos sinun kansas vaeltaa sotaan vihamiehiänsä vastaan sitä tietä, jota heidän lähetät, ja he rukoilevat Herraa tiellä kaupungin puoleen, jonka valinnut olet, ja huoneen puoleen, jonka minä sinun nimelles rakentanut olen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Ettäs kuulisit heidän rukouksensa ja anomisensa taivaissa, ja saattaisit heille oikeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Jos he syntiä tekevät sinua vastaan (sillä ei ole yhtäkään ihmistä, joka ei syntiä tee) ja sinä vihastut heidän päällensä, ja annat heidät vihamiehen käsiin, niin että he vievät heitä vankina vihollisen maalle, taamma eli lähemmä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Ja he tekisivät sydämestänsä parannuksen siinä maassa, jossa he vankina ovat, ja he palajaisivat sinua rukoilemaan vankeutensa maalla, sanoen: me rikoimme ja teimme pahoin, ja olimme jumalattomat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'Ja he niin palajaisivat sinun tykös kaikesta sydämestänsä ja kaikesta sielustansa vihamiestensä maalla, jotka heitä vangiksi vieneet ovat pois; ja he rukoilevat sinua tiellä maansa puoleen, jonka heidän isillensä antanut olet, sen kaupungin puoleen, jonka minä sinun nimelles rakentanut olen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Että kuulisit heidän rukouksensa ja anteeksi anomisensa taivaissa, siitä siasta, kussa sinä asut, ja saattaisit heille oikeuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'Ja olisit sinun kansalles armollinen, jotka sinua vastaan syntiä tehneet ovat, ja kaikille heidän rikoksillensa, joilla he rikkoneet ovat sinua vastaan: ja antaisit heille armon niiltä, jotka heitä vankina pitävät, ja he armahtaisivat heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Sillä he ovat sinun kansas ja sinun perimises, jotka sinä Egyptistä johdatit rautaisesta pätsistä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Että sinun silmäs olisivat avoinna sinun palvelias anomiseen ja sinun kansas Israelin rukoukseen; ettäs heitä kaikissa kuulisit, joiden tähden he sinun tykös huutavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Sillä sinä olet heidät erottanut sinulles perimiseksi kaikista kansoista maan päällä, niinkuin sinä sanonut olet sinun palvelialles Moseksen kautta, kuin sinä meidän isämme johdatit Egyptistä, Herra, Herra!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Ja koska Salomo oli kaiken tämän rukouksen ja anomisen lopettanut Herran edessä, nousi hän Herran alttarin edestä polviansa kumartamasta ja hajoittamasta käsiänsä taivaasen päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'Ja seisoi ja siunasi koko Israelin joukon, korotetulla äänellä, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Kiitetty olkoon Herra, joka kansallensa Israelille levon antanut on, kaiken sen jälkeen kuin hän puhunut on: ei yhtäkään ole puuttunut hänen hyvistä sanoistansa, jotka hän palveliansa Moseksen kautta puhunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Herra meidän Jumalamme olkoon meidän kanssamme, niinkuin hän on ollut meidän isäimme kanssa: älköön meitä hyljätkö, eikä ylönantako meitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Että hän kääntäis meidän sydämemme tykönsä, että me vaeltaisimme kaikissa hänen teissänsä ja pitäisimme hänen käskynsä, säätynsä ja oikeutensa, jotka hän meidän isillemme käskenyt on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Ja että nämät minun sanani, jotka minä Herran edessä rukoillut olen, olisivat läsnä Herran meidän Jumalamme tykönä päivällä ja yöllä; että hän saattais palveliallensa ja Israelille kansallensa oikeuden, itsekullakin ajallansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Että kaikki kansat maan päällä tietäisivät, että Herra on itse Jumala, ja ei yksikään muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Ja teidän sydämenne olkoon vakaa Herran meidän Jumalamme edessä, vaeltamaan hänen säädyissänsä ja pitämään hänen käskynsä, niin kuin se tänäpänä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Ja kuningas ja koko Israel hänen kanssansa uhrasivat uhria Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Ja Salomo uhrasi kiitosuhria (jonka hän Herralle uhrasi,) kaksikolmattakymmentä tuhatta härkää ja sata ja kaksikymmentä tuhatta lammasta. Näin he vihkivät Herran huoneen, kuningas ja kaikki Israelin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Sinä päivänä pyhitti kuningas keskikartanon, joka oli Herran huoneen edessä; sillä hän teki siellä polttouhrin, ruokauhrin ja kiitosuhrin lihavuuden; sillä vaskialttari, joka Herran edessä oli, oli vähäinen polttouhriin, ruokauhriin ja kiitosuhrin lihavuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Ja Salomo piti siihen aikaan juhlaa, ja koko Israel hänen kanssansa, suuressa kokouksessa, Hematin rajasta Egyptin virtaan asti, Herran meidän Jumalamme edessä, seitsemän päivää, ja taas seitsemän päivää: (se on) neljätoistakymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Ja kahdeksantena päivänä päästi hän kansan menemään, ja he siunasivat kuningasta, ja vaelsivat majoillensa, iloiten ja riemuiten kaikesta siitä hyvyydestä, minkä Herra palveliallensa Davidille ja kansallensa Israelille tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Ja kuin Salomo oli rakentanut Herran huoneen ja kuninkaan huoneen, ja kaikki mitä hänen sydämensä anoi ja halusi tehdäksensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Ilmaantui Herra Salomolle toisen kerran, niinkuin hän oli hänelle ilmaantunut Gibeonissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'Ja Herra sanoi hänelle: Minä olen kuullut sinun rukoukses ja anomises, joita olet minun edessäni anonut, ja olen pyhittänyt tämän huoneen, jonkas rakentanut olet, pannakseni siihen minun nimeni ijankaikkisesti, ja minun silmäni ja sydämeni ovat alati siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Ja jos sinä vallat minun edessäni, niinkuin sinun isäs David vaeltanut on, sydämen yksinkertaisuudessa ja vakuudessa, niin ettäs teet kaikki, mitä minä sinulle käskenyt olen, ja pidät minun säätyni ja oikeuteni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Niin minä vahvistan sinun valtakuntas istuimen Israelin ylitse ijankaikkisesti, niinkuin minä sinun isäs Davidin kanssa puhunut olen, sanoen: ei sinulta pidä otettaman pois mies Israelin istuimelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mutta jos te käännätte teitänne peräti pois minusta, te ja teidän lapsenne, ja ette pidä minun käskyjäni ja säätyjäni, jotka minä olen pannut teidän eteenne, ja menette ja palvelette vieraita jumalia ja rukoilette niitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Niin minä hävitän Israelin siitä maasta, jonka minä heille antanut olen: ja huoneen, jonka minä nimelleni pyhittänyt olen, heitän minä minun kasvoni edestä pois. Ja Israel pitää oleman sananlaskuksi ja jutuksi kaikissa kansoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Ja vaikka tämä huone on kaikkein korkein, niin kuitenkin kaikkein, jotka siitä käyvät ohitse, pitää hämmästymän ja viheltämän, sanoen: miksi Herra näin teki tälle maalle ja tälle huoneelle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Silloin vastataan: että he Herran Jumalansa hylkäsivät, joka heidän isänsä Egyptin maalta johdatti ulos, ja seurasivat muita jumalia ja kumarsivat niitä ja palvelivat niitä; sentähden on Herra kaiken tämän pahan antanut tulla heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Kuin kaksikymmentä ajastaikaa kulunut oli, joina Salomo ne kaksi huonetta rakensi, Herran huoneen ja kuninkaan huoneen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Joihin Hiram Tyron kuningas antoi Salomolle sedripuita, honkia ja kultaa, kaiken hänen tahtonsa jälkeen; niin kuningas Salomo antoi Hiramille kaksikymmentä kaupunkia Galilean maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Ja Hiram matkusti Tyrosta katsomaan kaupungeita, jotka Salomo hänelle antanut oli; ja ei ne hänelle kelvanneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Ja sanoi: mitkä nämä kaupungit ovat, minun veljeni, jotkas minulle antanut olet? Ja hän kutsui ne Kabulin maaksi tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Ja Hiram oli lähettänyt kuninkaalle sata ja kaksikymmentä sentneriä kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Ja tämä on luku verosta, jonka kuningas Salomo kantoi rakentaaksensa Herran huonetta, ja omaa huonettansa, ja Milloa, ja Jerusalemin muuria, ja Hatsoria, ja Megiddoa ja Gaseria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Sillä Pharao Egyptin kuningas oli mennyt ja voittanut Gaserin, ja polttanut sen tulella, ja lyönyt Kanaanealaiset kuoliaaksi, jotka kaupungissa asuivat, ja oli antanut sen tyttärellensä Salomon emännälle lahjaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Niin Salomo rakensi Gaserin ja alamaisen BetHoronin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Ja Baalatin ja Tadmorin, korvessa maalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'Ja kaikki tavarakaupungit, jotka Salomolla olivat, ja kaikki vaunukaupungit, ja ratsasmiesten kaupungit, ja mitä Salomo halusi ja tahtoi rakentaa Jerusalemissa ja Libanonissa, ja koko maassa, joka hänen vallassansa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Kaiken jääneen kansan Amorealaisista, Hetiläisistä, Pheresiläisistä, Heviläisistä ja Jebusilaisista, jotka ei olleet Israelin lapsia:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Heidän lapsensa, jotka he jättivät heistänsä maahan, joita Israelin lapset ei taitaneet hävittää; ne teki Salomo verolliseksi tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Mutta Israelin lapsista ei Salomo tehnyt yhtään orjaksi; vaan ne olivat sotamiehet, ja hänen palveliansa, ja päämiehensä, ja esimiehensä, ja hänen vaunuinsa ja ratsasmiestensä päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Ja virkamiesten päämiehiä, jotka olivat Salomon työn päällä, oli viisisataa ja viisikymmentä, jotka kansaa hallitsivat ja työn toimittivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Mutta Pharaon tytär meni ylös Davidin kaupungista omaan huoneesensa, jonka (Salomo) hänelle rakentanut oli. Silloin rakensi hän myös Millon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Ja Salomo uhrasi kolmasti vuodessa polttouhria ja kiitosuhria alttarilla, jonka hän Herralle rakentanut oli, ja suitsutti sen päällä Herran edessä; ja niin huone päätettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Ja kuningas Salomo teki myös laivan EtseonGeberissä, joka liki Elotia on, Punaisen meren reunan tykönä Edomilaisten maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Ja Hiram lähetti palveliansa laivaan, jotka olivat jalot haaksimiehet ja mereen hyvin harjaantuneet, Salomon palveliain kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Ja he tulivat Ophiriin ja veivät sieltä neljäsataa ja kaksikymmentä leiviskää kultaa; ja he veivät sen kuningas Salomolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Ja rikkaan Arabian kuningatar oli kuullut Salomon sanoman Herran nimestä, ja tuli koettelemaan häntä tapauksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Ja hän tuli Jerusalemiin sangen suuren joukon kanssa, kamelein kanssa, jotka jaloja yrttejä kannattivat, ja aivan paljon kultaa ja kalliita kiviä. Ja kuin hän tuli kuningas Salomon tykö, puhui hän hänelle kaikki, mitä hän sydämessänsä aikonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Ja Salomo ilmoitti hänelle kaikki hänen sanansa: ei ollut mitään kuninkaalta salattu, jota ei hän hänelle ilmoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Koska rikkaan Arabian kuningatar näki kaiken Salomon taidon ja huoneen, jonka hän rakentanut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Ja ruat hänen pöydällänsä, ja hänen palveliainsa asuinsiat, kunkin heidän virkansa, ja heidän vaatteensa, ja hänen juomansa laskiat ja polttouhrinsa, jonka hän Herran huoneessa uhrasi, tuli hän liki hengettömäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Sitte sanoi hän kuninkaalle: se on tosi, minkä minä sinusta kuullut olen minun maalleni, ja sinun menostas, ja sinun taidostas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Ja en minä uskonut sitä ennenkuin minä tulin itse, ja minä olen sen nyt silmilläni nähnyt, ja katso, ei ole minulle puoliakaan sanottu: sinulla on enempi taitoa ja hyvyyttä, kuin sanoma on, jonka minä kuullut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Autuaat ovat sinun miehes ja sinun palvelias, jotka aina sinun edessäs seisovat ja kuuntelevat sinun taitoas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Kiitetty olkoon Herra sinun Jumalas, joka sinuun on mielistynyt, sinun Israelin istuimelle pannaksensa! Sentähden että Herra rakastaa Israelia ijankaikkisesti, on hän pannut sinun kuninkaaksi tuomiota ja oikeutta tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Ja hän antoi kuninkaalle kaksikymmentä toistasataa sentneriä kultaa ja sangen paljon jaloja yrttejä ja kalliita kiviä. Ei tullut sinne sitte niin paljo kalliita yrttejä, kuin rikkaan Arabian kuningatar kuningas Salomolle antoi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Siihen myös Hiramin haahdet, jotka kultaa toivat Ophirista, ja sangen paljo Hebenin puita ja kalliita kiviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Ja kuningas antoi tehdä Hebenin puista patsaita Herran huoneesen ja kuninkaan huoneesen, ja kanteleet ja harput soittajille. Ei tullut sinne sitte niin paljo Hebenin puita, eikä myös nähty ole tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Ja kuningas Salomo antoi rikkaan Arabian kuningattarelle kaikki, mitä hän pyysi ja anoi häneltä, paitsi mitä hän hänelle itse antoi. Ja hän palasi ja meni palvelioinensa omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Mutta kullan paino, jonka he joka vuosi toivat Salomolle, oli kuusisataa ja kuusiseitsemättäkymmentä sentneriä kultaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Ilman sitä mitä kauppamiehet ja yrttein myyjät, niin myös kaikki Arabian kuninkaat ja voimalliset maalta (toivat hänelle.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Ja kuningas Salomo antoi myös tehdä parhaasta kullasta kaksisataa keihästä, kuusisataa kultapenninkiä antoi hän panna jokaiseen keihääseen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Ja kolmesataa kilpeä parhaasta kullasta, ja kolme leiviskää kultaa jokaiseen kilpeen; ja kuningas pani ne Libanonin metsähuoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Ja kuningas teki suuren istuimen elephantin luista, ja kultasi sen selkiällä kullalla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Ja siinä istuimessa oli kuusi astuinlautaa, ja sen istuimen pää oli ympyriäinen takaapäin, ja käsipuut olivat molemmilla puolilla istuinta, ja kaksi jalopeuraa seisoi käsipuiden tykönä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Ja siellä seisoi kaksitoistakymmentä jalopeuraa niiden kuuden astuinlaudan päällä molemmin puolin: ei senkaltaista ole tehty missäkään valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Kaikki kuningas Salomon juoma-astiat olivat selkiästä kullasta, ja jokainen astia Libanonin metsähuoneessa oli myös selkiästä kullasta; sillä ei yksikään huolinut kuningas Salomon aikana hopiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Sillä kuninkaalla oli haaksi Tarsis merellä Hiramin haahden kanssa; ja haaksi Tarsis tuli joka kolmantena vuotena kerran ja toi kultaa, hopiaa, elephantin hampaita, apinoita ja riikinkukkoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Ja näin kuningas Salomo on tullut suuremmaksi kaikkia kuninkaita maan päällä, rikkaudessa ja viisaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Kaikki maailma pyysi nähdä Salomoa, kuullaksensa sitä taitoa, jonka Jumala oli antanut hänen sydämeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Ja he kukin toivat hänelle lahjoja, hopia-astioita ja kultaisia kaluja, ja vaatteita, ja haarniskoita, ja yrttejä, ja hevosia, ja muuleja, joka vuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Ja Salomo kokosi vaunuja ja ratsasmiehiä, niin että hänellä oli tuhannen ja neljäsataa vaunua ja kaksitoistakymmentä tuhatta ratsasmiestä; ne hän pani vaunukaupunkeihin ja kuninkaan tykö Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Ja kuningas teki niin, että hopiaa oli niin paljo Jerusalemissa kuin kiviä, ja sedripuita niin paljo kuin villifikunapuita laaksoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Ja Salomolle tuotiin hevosia Egyptistä, ja kudotuita kaluja, ja kuninkaan kauppamiehet ostivat ne kalut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Ja toivat Egyptistä jokaisen vaunun kuudensadan hopiapenningin edestä, ja hevosen sadan ja viidenkymmenen hopiapenningin edestä. Niin veivät he niitä myös kättensä kautta kaikkein Hetiläisten kuningasten ja Syrian kuningasten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Ja kuningas Salomo rakasti monta muukalaista vaimoa, Pharaon tytärtä, ja Moabilaisia, Ammonilaisia, Edomilaisia, Zidonilaisia ja Hetiläisiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Niistä kansoista, joista Herra Israelin lapsille sanonut oli: älkäät menkö heidän tykönsä, eikä hekään tulko teidän tykönne; sillä he kääntävät totisesti teidän sydämenne jumalainsa perään. Näihin suostui Salomo, rakastamaan heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Ja hänellä oli seitsemänsataa ruhtinaallista emäntää ja kolmesataa jalkavaimoa; ja hänen vaimonsa käänsivät pois hänen sydämensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Kuin Salomo vanheni, käänsivät hänen emäntänsä hänen sydämensä vierasten jumalain perään, niin ettei hänen sydämensä ollut täydellinen Herran Jumalansa kanssa, niinkuin Davidin hänen isänsä sydän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Ja niin vaelsi Salomo Astarotin Zidonilaisten jumalan perään, ja Milkomin Ammonilaisten kauheuden perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Ja Salomo teki pahaa Herran edessä, ja ei seurannut Herraa täydellisesti, niinkuin hänen isänsä David.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Silloin rakensi Salomo korkeuden Kamokselle, Moabilaisten kauhistukselle, sille vuorelle, joka on Jerusalemin edessä, ja Molokille Ammonilaisten kauhistukselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Niin teki Salomo kaikille muukalaisille emännillensä, jotka jumalillensa suitsuttivat ja uhrasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Ja Herra vihastui Salomon päälle, että hänen sydämensä oli kääntynyt pois Herrasta Israelin Jumalasta, joka hänelle kahdesti ilmaantunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'Ja häntä näistä kieltänyt oli, ettei hänen pitänyt vaeltaman vierasten jumalain perään; ja ei kuitenkaan pitänyt, mitä Herra hänelle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Sanoi siis Herra Salomolle: että se on tapahtunut sinulta, ja et sinä pitänyt minun liittoani ja minun käskyjäni, jotka minä sinulle käskin; niin minä totisesti repäisen valtakunnan sinulta, ja annan sen palvelialles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'En minä kuitenkaan sitä tee sinun ajallas, isäs Davidin tähden; mutta poikas kädestä minä sen repäisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'En minä kuitenkaan koko valtakuntaa repäise: yhden sukukunnan minä annan pojalles, Davidin minun palveliani tähden ja Jerusalemin tähden, jonka minä olen valinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Ja Herra nosti Salomolle vihollisen, Hadadin Edomilaisen, kuninkaallisesta suvusta Edomissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Sillä kun David oli Edomissa, ja Joab sodanpäämies meni hautaamaan tapetuita, ja löi kuoliaaksi kaiken miehenpuolen Edomissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Sillä Joab ja koko Israel viipyi kuusi kuukautta siellä, siihen asti että hän kaiken miehenpuolen Edomissa hävitti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Niin pakeni Hadad ja muutamat Edomin miehet hänen kanssansa hänen isänsä palvelioista, ja menivät Egyptiin; mutta Hadad oli vähä nuorukainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Ja he nousivat Midianista ja tulivat Paraniin, ja ottivat kanssansa miehiä Paranista, ja menivät Egyptiin, Pharaon Egyptin kuninkaan tykö, joka antoi hänelle huoneen ja elatuksen, ja maan hän myös antoi hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Ja Hadad löysi suuren armon Pharaon edessä, niin että hän antoi hänelle emäntänsä kuningatar Tapheneksen sisaren emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Ja Tapheneksen sisar synnytti hänelle Genubatin hänen poikansa. Ja Taphenes kasvatti hänen Pharaon huoneessa, niin että Genubat oli Pharaon huoneessa Pharaon lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Kuin Hadad Egyptissä kuuli Davidin nukkuneeksi isäinsä kanssa, ja että sodanpäämies Joab oli kuollut; sanoi hän Pharaolle: päästä minua menemään minun maalleni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Pharao vastasi häntä: mitä sinulta puuttuu minun tykönäni, ettäs tahdot mennä sinun maalles? Hän sanoi: ei mitään, vaan salli minun kuitenkin mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Ja Jumala nosti myös hänelle vihamiehen Resonin ElJadan pojan, joka oli karannut herraltansa HadadEseriltä Zoban kuninkaalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Ja kokosi miehiä häntä vastaan, ja hän oli sotajoukon päämies silloin kuin David surmasi heitä; ja he menivät Damaskuun ja asuivat siellä, ja hallitsivat Damaskuussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Ja hän oli Israelin vihollinen niinkauvan kuin Salomo eli, paitsi sitä vahinkoa, jonka Hadad teki; hän kauhistui Israelia ja tuli Syrian kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Niin myös Jerobeam Nebatin poika Ephratilainen Zarebasta, Salomon palvelia; hänen äitinsä nimi oli Zeruga, leskivaimo; hän nosti myös kätensä kuningasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Ja tämä on syy, jonkatähden hän kätensä nosti kuningasta vastaan: Kuin Salomo rakensi Milon, sulki hän isänsä Davidin kaupungin raon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Ja Jerobeam oli jalo sotamies: ja koska Salomo näki nuorukaisen kelpaavaiseksi, asetti hän hänen koko Josephin huoneen kuormain päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Se tapahtui siihen aikaan, että Jerobeam meni ulos Jerusalemista, ja propheta Ahia Silosta löysi hänen tiellä, ja hänen yllänsä oli uusi hame, ja he olivat ainostansa kahden kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Ja Ahia rupesi uuteen hameesen, joka hänen yllänsä oli, ja repäisi kahdeksitoistakymmeneksi kappaleeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'Ja sanoi Jerobeamille: ota kymmenen kappaletta sinulle; sillä näin sanoo Herra Israelin Jumala: katso, minä repäisen valtakunnan Salomon kädestä, ja annan sinulle kymmenen sukukuntaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Yksi sukukunta jää hänelle, Davidin minun palveliani tähden ja Jerusalemin kaupungin tähden, jonka minä olen valinnut kaikista Israelin sukukunnista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Että he ovat minun hyljänneet ja kumartaneet Astarotia Zidonilaisten jumalaa, Kamosta Moabilaisten jumalaa ja Milkomia Ammonin lasten jumalaa, ja ei vaeltaneet minun tielläni eikä tehneet, mitä minulle kelpasi, minun säätyjäni ja minun oikeuttani, niinkuin David hänen isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'En minä kuitenkaan ota kaikkea valtakuntaa hänen kädestänsä, vaan teen hänen ruhtinaaksi hänen elinajaksensa, Davidin minun palveliani tähden, jonka minä valitsin; sillä hän piti minun käskyni ja säätyni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mutta hänen poikansa kädestä otan minä valtakunnan, ja annan sinulle kymmenen sukukuntaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'Mutta hänen pojallensa annan minä yhden sukukunnan, että minun palveliallani Davidilla olis aina valkeus minun edessäni Jerusalemissa, siinä kaupungissa, jonka minä olen valinnut minulleni, pannakseni nimeni sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Niin otan minä nyt sinun hallitsemaan kaikissa mitä sydämes halajaa, ja sinun pitää oleman Israelin kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Jos sinä kuulet kaikkia, mitä minä sinulle käsken, ja vaellat minun tielläni, ja teet mitä minulle kelpaa, pitäen minun säätyni ja käskyni, niin kuin David minun palveliani teki; niin minä olen sinun kanssas, ja rakennan sinulle vahvan huoneen, niinkuin minä Davidille rakensin, ja annan sinulle Israelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Ja näin alennan minä sentähden Davidin siemenen, en kuitenkaan ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Mutta Salomo pyysi tappaa Jerobeamia. Niin Jerobeam nousi ja pakeni Egyptiin, Sisakin, Egyptin kuninkaan tykö, ja oli Egyptissä Salomon kuolemaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Mitä muuta Salomosta sanomista on, hänen tekonsa ja taitonsa: eikö ne ole kirjoitetut Salomon aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Mutta aika, kuin Salomo hallitsi Jerusalemissa kaiken Israelin ylitse, oli neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Ja Salomo nukkui isäinsä kanssa ja haudattiin isänsä Davidin kaupunkiin. Ja hänen poikansa Rehabeam tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Ja Rehabeam meni Sikemiin, sillä koko Israel oli silloin tullut Sikemiin, tekemään häntä kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Ja Jerobeam Nebatin poika kuuli sen ollessansa Egyptissä, johon hän kuningas Salomon edestä paennut oli: (ja Jerobeam viipyi Egyptissä.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Ja he olivat lähettäneet häntä kutsumaan; ja Jerobeam tuli ja koko Israelin joukko, ja he puhuivat Rehabeamille ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Sinun isäs on meidän ikeemme raskauttanut: niin huojenna nyt sinä isäs kova palvelus ja raskas ijes, jonka hän meidän päällemme pannut on, niin me palvelemme sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Mutta hän sanoi heille: menkäät pois kolmanteen päivään asti ja tulkaat jälleen minun tyköni; ja kansa meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Niin kuningas Rehabeam piti neuvoa vanhempain kanssa, jotka hänen isänsä Salomon edessä seisoivat, kuin hän vielä eli, ja sanoi: kuinka te neuvotte vastaamaan tätä kansaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'He puhuivat hänelle sanoen: jos sinä palvelet tänäpänä tätä kansaa ja noudat heidän mielensä, ja vastaat heitä ja annat heille hyviä sanoja; niin he ovat sinun palvelias kaiken sinun elinaikas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mutta hän hylkäsi vanhimpain neuvon, jonka he hänelle antaneet olivat, ja piti neuvoa nuorukaisten kanssa, jotka hänen kanssansa kasvaneet olivat ja hänen edessänsä seisoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Ja hän sanoi niille: mitä te neuvotte vastaamaan tätä kansaa, joka minulle on puhunut sanoen: Huojenna se ijes, jonka isäs meidän päällemme pannut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Ja nuorukaiset, jotka hänen kanssansa kasvaneet olivat, puhuivat hänelle sanoen: näin pitää sinun sanoman kansalle, joka sinulle sanoo: sinun isäs on meidän ikeemme raskauttanut, huojenna se meiltä! sille pitää sinun sanoman: minun pienin sormeni on paksumpi kuin minun isäni kupeet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Minun isäni on teidän ikeenne raskauttanut, mutta minä lisään vielä nyt teidän ikeesenne: minun isäni on kurittanut teitä ruoskilla, vaan minä kuritan teitä skorpioneilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Niin Jerobeam ja kaikki kansa tuli Rehabeamin tykö kolmantena päivänä, niinkuin kuningas puhunut ja sanonut oli: tulkaat minun tyköni jälleen kolmantena päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Ja kuningas vastasi kovin kansaa, ja hylkäsi sen neuvon, jonka vanhimmat olivat hänelle antaneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Ja puhui heille niinkuin nuoret olivat neuvoneet, ja sanoi: minun isäni on teidän ikeenne raskauttanut, mutta minä lisään teidän ikeesenne vielä: minun isäni on teitä kurittanut ruoskilla, vaan minä kuritan teitä skorpioneilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Ja ei kuningas kuullut kansaa; sillä Herra oli sen niin kääntänyt, vahvistaaksensa sanansa jonka Herra puhui Jerobeamille Nebatin pojalle Ahian kautta Silosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Kuin koko Israel sen näki, ettei kuningas kuullut heitä, vastasi kansa kuningasta ja sanoi: mikä osa meillä on Davidissa? eli perimys Isain pojassa? Israel, mene majoilles! katso siis sinä, David huonettas! Ja Israel meni majoillensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Niin että Rehabeam ainoastansa vallitsi ne Israelin lapset, jotka Juudan kaupungeissa asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Ja kuin kuningas Rehabeam lähetti Adoramin verorahan haltian matkaan, niin koko Israel kivitti hänen, niin että hän kuoli. Mutta kuningas Rehabeam astui nopiasti vaunuihin ja pakeni Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Ja niin erkani Israel Davidin huoneesta, hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Kuin koko Israel kuuli Jerobeamin tulleeksi jälleen, lähettivät he ja käskivät kutsua hänen kansan eteen, ja tekivät hänen kaiken Israelin kuninkaaksi; ja ei yksikään seurannut Davidin huonetta, vaan Juudan suku ainoastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Ja kuin Rehabeam tuli Jerusalemiin, kokosi hän koko Juudan huoneen ja BenJaminin suvun, sata ja kahdeksankymmentä tuhatta valittua sotamiestä, sotimaan Israelin huonetta vastaan ja omistamaan valtakuntaa Rehabeamille Salomon pojalle jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mutta Jumalan sana tuli sen Jumalan miehen Semajan tykö, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Puhu Rehabeamille Salomon pojalle Juudan kuninkaalle ja koko Juudan huoneelle, ja BenJaminille ja jääneelle kansalle, ja sano:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Näin sanoo Herra: älkäät menkö sotimaan teidän veljiänne Israelin lapsia vastaan. Palatkaan jokainen kotiansa; sillä se on minulta tapahtunut. Ja he kuulivat Herran sanan ja palasivat menemään Herran sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Ja Jerobeam rakensi Sikemin Ephraimin vuorelle ja asui siinä, ja läksi sieltä ja rakensi Penuelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Ja Jerobeam ajatteli sydämessänsä: nyt valtakunta tulee Davidin huoneelle jälleen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Jos tämä kansa menee Jerusalemiin uhraamaan Herran huoneesen, ja tämän kansan sydän kääntyy jälleen herransa Rehabeamin Juudan kuninkaan puoleen; niin he tappavat minun ja palajavat jälleen Rehabeamin Juudan kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Ja kuningas piti neuvon ja teki kaksi kultaista vasikkaa; ja hän sanoi heille: teidän on työläs mennä Jerusalemiin, katso, tässä on sinun Jumalas, Israel, joka sinun on johdattanut Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Ja pani niistä yhden Beteliin, ja toisen pani hän Daniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Ja se asia joutui synniksi; sillä kansa meni sen yhden eteen hamaan Daniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Niin teki hän myös huoneen kukkulalle ja teki papit halvimmista kansan seasta, jotka ei Levin lapsia olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Ja Jerobeam teki juhlan viidentenätoistakymmenentenä päivänä, kahdeksantena kuukautena, niin kuin Juudan juhlapäivän, ja uhrasi alttarilla. Niin hän myös teki Betelissä, uhraten vasikoille, jotka hän tehnyt oli. Ja hän toimitti Betelin papit kukkuloille, jotka hän tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Ja hän uhrasi alttarilla, (jonka hän Beteliin tehnyt oli) viidentenätoistakymmenentenä päivänä kahdeksantena kuukautena, jonka hän sydämessänsä ajatellut oli. Ja teki Israelin lapsille juhlan, ja uhrasi alttarilla suitsutukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Ja katso, Jumalan mies tuli Juudasta Herran sanan kanssa Beteliin; ja Jerobeam seisoi alttarin tykönä suitsuttamassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Ja hän huusi alttaria vastaan Herran sanan kautta ja sanoi: alttari, alttari! Näin sanoo Herra: katso, Davidin huoneelle on syntyvä poika, Josia nimeltä: hän on uhraava sinun päälläs korkeuden pappeja, jotka sinun päälläs suitsuttavat, ja on polttava ihmisen luita sinun päälläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Ja hän antoi sinä päivänä ihmeen ja sanoi: tämä on se ihme, jonka Herra puhunut on: katso, alttarin pitää halkeaman, ja tuhka, joka sen päällä on, pitää hajoitettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Kuin kuningas kuuli sanan siltä Jumalan mieheltä, joka alttaria vastaan Betelissä huutanut oli, ojensi Jerobeam kätensä alttarin tyköä ja sanoi: ottakaat häntä kiinni. Ja hänen kätensä kuivettui, jonka hän häntä vastaan ojensi, ja ei hän taitanut sitä vetää jälleen puoleensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Ja alttari halkesi, ja tuhka hajoitettiin alttarilta, sen ihmeen jälkeen, jonka Jumalan mies Herran sanan kautta antanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Ja kuningas vastasi ja sanoi Jumalan miehelle: nöyryytä nyt sinus rukouksella Herran Jumalas kasvoin edessä, ja rukoile minun edestäni, että käteni taipuis minun tyköni. Niin Jumalan mies rukoili nöyrästi Herraa, ja kuninkaan käsi taipui jälleen hänen puoleensa ja tuli niinkuin se oli ennenkin ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Ja kuningas puhui Jumalan miehelle: tule kotia minun kanssani ja virvoita itses: minä annan sinulle lahjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mutta Jumalan mies sanoi kuninkaalle: vaikkas antaisit minulle puolen huonettas, en minä sittenkään tulisi sinun kanssas, enkä syö tässä paikassa leipää enkä juo vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Sillä niin käski minua Herran sanansa kautta, sanoen: ei sinun pidä leipää syömän eikä vettä juoman, eikä myös palajaman sitä tietä, jota sinä mennyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Ja hän meni toista tietä ja ei palannut sitä tietä, jota hän Beteliin tullut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Mutta Betelissä asui vanha propheta; hänen tykönsä tuli hänen poikansa ja jutteli hänelle kaikki, mitä Jumalan mies teki sinä päivänä Betelissä, ja sanat, jotka hän kuninkaalle sanonut oli, he juttelivat isällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'Ja heidän isänsä sanoi heille, mitä tietä hän meni? ja hänen poikansa osoittivat hänelle tien, jota Juudasta tullut Jumalan mies vaeltanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Mutta hän sanoi pojillensa: satuloikaat minulle aasi. Ja kuin he olivat satuloineet aasin, istui hän sen selkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'Ja meni sen Jumalan miehen perään, ja löysi hänen istumassa tammen alla, ja sanoi hänelle, sinäkö se Jumalan mies olet, joka Juudasta tullut olet? Hän sanoi: minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Hän sanoi hänelle: tule minun kanssani kotia ja syö leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Hän sanoi: en minä taida palata sinun kanssas enkä tulla sinun tykös: en minä syö leipää enkä juo vettä sinun kanssas tässä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Sillä minun kanssani on puhuttu Herran sanan kautta: ei sinun pidä siellä leipää syömän eikä vettä juoman, ei myös sinun pidä palajaman sitä tietä, jota sinä sinne mennyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Hän sanoi hänelle: minä olen myös propheta niinkuin sinäkin, ja enkeli on puhunut minun kanssani Herran sanan kautta ja sanonut: vie häntä kanssas huoneeses syömään leipää ja juomaan vettä. Mutta hän valehteli hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Ja hän palasi hänen kanssansa, ja söi leipää ja joi vettä hänen huoneessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Ja tapahtui, kuin he istuivat pöydän tykönä, että Herran sana tuli prophetan työ, joka hänen palauttanut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Ja hän huusi Jumalan miehelle, joka Juudasta tullut oli, ja sanoi: näin sanoo Herra: ettäs olet Herran käskylle tottelematoin ollut, ja et ole sitä käskyä pitänyt, jonka Herra sinun Jumalas käskenyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Ja olet palannut syömään leipää ja juomaan vettä siinä paikassa, josta sinulle sanottu oli: ei sinun pidä siellä leipää syömän eikä vettä juoman: ei pidä sinun ruumiis tuleman sinun isäis hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Ja kuin hän leipää syönyt ja vettä juonut oli, satuloitsi hän aasin prophetalle, jonka hän palauttanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Ja koska hän meni pois, kohtasi hänen jalopeura tiellä ja tappoi hänen. Ja hänen ruumiinsa makasi heitettynä tiellä, ja aasi seisoi hänen sivussansa, ja jalopeura seisoi lähinnä ruumista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Ja katso, koska siitä kävi ihmisiä ohitse, näkivät he ruumiin heitetyksi tielle ja jalopeuran seisovan ruumiin tykönä; ja he tulivat ja sanoivat sen kaupungissa, jossa vanha propheta asui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Kuin propheta sen kuuli, joka hänen tieltä palauttanut oli, sanoi hän: se on Jumalan mies, joka Herran käskylle tottelematoin oli; sentähden on Herra hänen antanut jalopeuralle, ja se on musertanut ja tappanut hänen niiden sanain jälkeen, jotka Herra hänelle sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Ja sanoi pojillensa: satuloikaat minulle aasi. Ja koska he olivat satuloineet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Meni hän sinne, ja löysi hänen ruumiinsa heitetyksi tielle, ja aasin ja jalopeuran seisovan ruumiin tykönä. Ei jalopeura ollut syönyt ruumista eikä reväissyt aasia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Niin otti propheta sen Jumalan miehen ruumiin ja pani aasinsa päälle, ja vei sen takaperin; ja vanha propheta tuli kaupunkiin itkemään ja hautaamaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Ja hän pani ruumiin omaan hautaansa, ja he itkivät häntä: oi minun veljeni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Ja kuin he olivat haudanneet hänen, puhui hän pojillensa, sanoen: koska minä kuolen, niin haudatkaat minua siihen hautaan, johon Jumalan mies haudattu on, ja pankaat minun luuni hänen luidensa sivuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Sillä se on tapahtuva, minkä hän alttaria ja Beteliä vastaan Herran sanan kautta huutanut oli, ja kaikkia korkeuden huoneita vastaan, jotka Samarian kaupungeissa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Mutta kuin nämät tapahtuneet olivat, ei Jerobeam kääntänytkään itseänsä pahalta tieltänsä pois, mutta meni ja teki taas korkeuden pappeja halvimmista kansan seassa; kenenkä hän tahtoi, sen käden hän täytti, ja se tuli korkeuden papiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Ja tämä asia tapahtui Jerobeamin huoneelle synniksi, ja että hän piti hävitettämän ja hukutettaman maan päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Siihen aikaan sairasti Abia Jerobemin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Ja Jerobeam sanoi emännällensä: nouse ja muuta itses, niin ettei yksikään tuntisi sinua Jerobeamin emännäksi; ja mene Siloon. Katso siellä on propheta Ahia, joka minulle sanoi: että minä olen tuleva tämän kansan kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Ja ota kätees kymmenen leipää ja kyrsää, ja astia hunajaa, ja mene hänen tykönsä, että hän sanois sinulle, mitä nuorukaiselle tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Ja Jerobeamin emäntä teki niin, nousi ja meni Siloon, ja tuli Ahian huoneesen; mutta ei Ahia taitanut nähdä, sillä hänen silmänsä olivat pimenneet vanhuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Mutta Herra sanoi Ahialle: katso Jerobeamin emäntä tulee kysymään sinulta yhtä asiaa pojastansa, sillä hän on sairas; niin puhu sinä hänelle niin ja niin. Ja kuin hän tuli sisälle, piti hän itsensä outona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Kuin Ahia kuuli ovessa hänen jalkainsa töminän, sanoi hän: tule sisälle, sinä Jerobeamin emäntä: kuinkas itses niin outona pidät? Minä olen lähetetty sinun tykös kovan sanoman kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Mene ja sano Jerobeamille: näin sanoo Herra Israelin Jumala: että minä olen korottanut sinun kansan seasta ja pannut sinun minun kansani Israelin ruhtinaaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'Ja olen reväissyt valtakunnan Davidin huoneelta pois, ja antanut sen sinulle: mutta et sinä ole ollut niinkuin minun palveliani David, joka piti minun käskyni ja vaelsi minun jälkeeni kaikella sydämellä, ja teki ainoastaan mitä minulle kelvollinen oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Mutta sinä olet tehnyt pahemmin kaikkia muita, jotka sinun edelläs olleet ovat, ja sinä olet mennyt ja tehnyt itselles vieraita jumalia ja valetuita kuvia kehoittaakses minua vihaan, ja olet heittänyt minun selkäs taa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Sentähden katso, minä annan tulla pahaa Jerobeamin huoneen päälle, ja hukutan Jerobeamista sen, joka vetensä seinään heittää, suljetun ja hyljätyn Israelissa, ja käväisen Jerobeamin huoneen sukukunnan, niinkuin tunkio käväistään, perikatoonsa asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Joka Jerobeamista kuolee kaupungissa, se pitää koirilta syötämän, mutta joka kuolee kedolla, se pitää taivaan linnuilta syötämän; sillä Herra on sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Niin nouse sinä ja mene kotias, ja kuin jalkas astuu kaupunkiin, niin pojan pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Ja koko Israel itkee häntä ja hautaa hänen, sillä ainoastansa tämä tulee Jerobeamista hautaan, että jotakin hyvää on löydetty hänen tykönänsä, Herran Israelin Jumalan edessä, Jerobeamin huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Ja Herra herättää itsellensä yhden Israelin kuninkaan, se on hävittävä Jerobeamin huoneen sinä päivänä: ja mitä jo on tapahtunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Ja Herra lyö Israelin niinkuin ruoko häälyy vedessä, ja repii Israelin tästä hyvästä maasta, jonka hän heidän isillensä antanut on, ja hajottaa heidät virran ylitse; että he ovat itsellensä tehneet metsistöitä, vihoittaksensa Herraa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Ja hylkää Israelin, Jerobeamin synnin tähden, joka syntiä teki ja saatti Israelin syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Ja Jerobeamin emäntä nousi ja meni, ja tuli Tirtsaan; ja kuin hän astui huoneen kynnykseen, kuoli nuorukainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Ja he hautasivat hänen, ja koko Israel itki häntä, Herran sanan jälkeen, jonka hän palveliansa propheta Ahian kautta sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Mitä enempi Jerobeamista on sanomista, kuinka hän soti ja kuinka hän hallitsi: katso se on kirjoitettu Israelin kuningasten aikakirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Ja aika, jonka Jerobeam hallitsi, oli kaksikolmattakymmentä ajastaikaa; ja hän nukkui isäinsä kanssa; ja hänen poikansa Nadab tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Niin oli Rehabeam, Salomon poika kuningas Juudassa, ja oli yhdenviidettäkymmentä ajastaikainen tultuansa kuninkaaksi, ja hallitsi seitsemäntoistakymmentä ajastaikaa Jerusalemissa, siinä kaupungissa, jonka Herra valinnut on kaikista Israelin sukukunnista, pannaksensa siihen nimensä; ja hänen äitinsä nimi oli Naema Ammonilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Ja Juuda teki pahaa Herran edessä; ja he saattivat hänen enempi kiivaaksi, kuin kaikki heidän esiisänsä olivat tehneet synneillänsä, joita he tekivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Sillä hekin rakensivat itsellensä korkeuksia, patsaita ja metsistöitä kaikille korkeille vuorille ja kaikkein viheriäisten puiden alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Ja maakunnassa oli huorintekijöitä; ja he tekivät kaikki pakanain kauhistukset, jotka Herra Israelin lasten edestä oli ajanut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Ja tapahtui viidennellä kuningas Rehabeamin ajastajalla, että Sisak Egyptin kuningas meni Jerusalemia vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Ja otti Herran huoneen tavarat, ja kuninkaan huoneen tavarat, ja kaiken mitä sieltä taidettiin ottaa, ja otti kaikki kultaiset kilvet, jota Salomo oli antanut tehdä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Joiden siaan kuningas Rehabeam antoi tehdä vaskisia kilpiä, ja antoi ne ylimmäisten vartioittensa haltuun, jotka kuninkaan huoneen ovea vartioitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Ja niin usein kuin kuningas meni Herran huoneesen, kantoivat vartiat niitä, ja veivät ne vartiakamariin jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Mitä enempi Rehabeamin asioista on sanomista ja kaikista mitä hän tehnyt oli: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Ja Rehabeamin ja Jerobeamin välillä oli sota kaikkina heidän päivinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Ja Rehabeam nukkui isäinsä kanssa ja haudattiin isäinsä tykö Davidin kaupunkiin. Ja hänen äitinsä nimi oli Naema Ammonilainen. Ja hänen poikansa Abiam tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Niin oli kuningas Jerobeamin Nebatin pojan kahdeksantena vuotena toistakymmentä Abiam kuningas Juudassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Ja hallitsi kolme ajastaikaa Jerusalemissa; hänen äitinsä nimi oli Maeka Abisalomin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Ja hän vaelsi kaikissa isänsä synneissä, jotka hän oli tehnyt hänen edellänsä, ja ei ollut hänen sydämensä vakaa Herran hänen Jumalansa edessä, niinkuin Davidin hänen isänsä sydän oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mutta Davidin tähden antoi Herra hänen Jumalansa hänelle valkeuden Jerusalemissa, herättääksensä hänelle pojan hänen jälkeensä, ja asettaaksensa Jerusalemiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Sillä David oli tehnyt mitä oikein on Herran edessä, ja ei poikennut kaikista, mitä hän hänelle käskenyt oli, kaikkena elinaikanansa, paitsi Urian Hetiläisen asiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Mutta Rehabeam ja Jerobeam sotivat keskenänsä kaiken elinaikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Mitä enempi on sanomista Abiamista ja kaikista hänen töistänsä, eikö se ole kirjoitettu Juudan kuningasten aikakirjassa? Ja Abiam soti Jerobeamin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Niin Abiam nukkui isäinsä kanssa ja haudattiin Davidin kaupunkiin; ja Asa hänen poikansa hallitsi hänen perässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Ja kahdentenakymmenentenä Jerobeamin Israelin kuninkaan vuonna oli Asa kuningas Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Ja hallitsi yhden ajastajan viidettäkymmentä Jerusalemissa; hänen äitinsä nimi oli Maeka Abisalomin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Ja Asa teki kelvollisesti Herran edessä, niinkuin David hänen isänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Ja karkoitti huorintekijät maalta, ja ajoi pois kaikki epäjumalat, jotka hänen isänsä tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Ja vielä sitten pani hän äitinsä Maekan viralta pois, että hän oli tehnyt Mipletsetin metsistön; vaan Asa kukisti hänen Mipletsetinsä ja poltti sen Kidronin ojan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mutta kukkuloita ei hän kukistanut; kuitenkin Asan sydän oli vakaa Herran edessä kaiken elinaikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Ja hän vei sisälle mitä hänen isänsä oli pyhittänyt, ja Herran huoneen pyhät kalut: hopian ja kullan ja astiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Mutta Asan ja Baesan Israelin kuninkaan välillä oli sota kaiken heidän elinaikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Vaan Baesa Israelin kuningas nousi Juudaa vastaan ja rakensi Raman, ettei yksikään vaeltaisi ulos taikka sisälle Asan Juudan kuninkaan puolelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Silloin otti Asa kaiken hopian ja kullan, jotka Herran huoneen tavaroista ja kuninkaan huoneen tavaroista jääneet olivat, ja antoi ne palveliansa käsiin, jotka kuningas Asa lähetti Benhadadille Tabrimmonin Hesionin pojan pojalle Syrian kuninkaalle, joka asui Damaskussa, ja käski sanoa hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Minun ja sinun vaiheella, ja minun isäni ja sinun isäs vaiheella on liitto: katso minä lähetin sinulle hopiaa ja kultaa lahjaksi, ettäs rikkoisit sen liiton, minkä sinä Baesan Israelin kuninkaan kanssa tehnyt olet, että hän erkanis minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Ja Benhadad oli kuuliainen kuningas Asalle, ja lähetti sodanpäämiehet Israelin kaupunkeihin, ja löi Iionin ja Danin ja Abelin Betmaekan, ja koko Kinerotin, ynnä kaiken Naphtalin maakunnan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Kuin Baesa sen kuuli, lakkasi hän rakentamasta Ramaa, ja meni Tirtsaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Mutta kuningas Asa lähetti sanoman kaiken Juudan ympäri: ei tässä pidä yksikään nuhteetoin oleman. Ja he kukistivat kivet ja puut Ramasta, joita Baesa oli rakentanut; ja kuningas Asa rakensi niistä Geban BanJaminista ja Mitspan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Mitä muuta on kuningas Asasta puhumista, ja kaikesta hänen vallastansa, ja kaikista hänen töistänsä, ja kaupungeista, jotka hän rakentanut oli: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa? paitsi että hän oli vanhuudellansa sairas jaloista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Ja Asa nukkui isäinsä kanssa ja haudattiin isäinsä kanssa isänsä Davidin kaupunkiin. Ja Josaphat hänen poikansa tuli kuninkaaksi hänen peräänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Ja Nadab Jerobeamin poika oli Israelin kuningas toisena Asan Juudan kuninkaan vuonna, ja hallitsi Israelissa kaksi vuotta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Ja teki pahaa Herran edessä, ja vaelsi isänsä teillä ja hänen synneissänsä, joilla hän saatti Israelin syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Ja Baesa Ahian poika Isaskarin huoneesta teki liiton häntä vastaan, ja Baesa löi hänen Philistealaisten Gibetonissa; sillä Nadab ja koko Israel piirittivät Gibetonin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Sitte tappoi Baesa hänen kolmantena Asan Juudan kuninkaan vuonna, ja tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Koska hän oli kuningas, löi hän kuoliaaksi kaiken Jerobeamin huoneen, ja ei jättänyt yhtään ainoaa henkeä Jerobeamin huoneesta, siihenasti että hän hävitti hänen, Herran sanan jälkeen, joka oli sanottu hänen palvelialtansa Ahialta Silosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'Jerobeamin syntein tähden, jotka hän teki, ja jolla hän saatti Israelin syntiä tekemään, sillä vihoittamisella, jolla hän vihaan kehoitti Herran Israelin Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Mitä enempi Nadabista on sanomista ja kaikista hänen töistänsä: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Mutta Asa ja Baesa Israelin kuningas sotivat keskenänsä kaiken ikänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Kolmantena Asan Juudan kuninkaan vuonna oli Baesa Ahian poika koko Israelin kuningas Tirtsassa, neljäkolmattakymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Ja hän teki pahaa Herran edessä, ja vaelsi Jerobeamin teillä ja hänen synneissänsä, joilla hän saatti Israelin syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Niin tuli Herran sana Jehun Hananin pojan tykö Baesaa vastaan, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Että minä olen ylentänyt sinun tomusta ja tehnyt sinun minun kansani Israelin ruhtinaaksi, ja kuitenkin sinä olet vaeltanut Jerobeamin teillä ja saattanut minun kansani Israelin syntiä tekemään, niin ettäs vihoitat minun heidän synneillänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Katso, minä hävitän Baesan perilliset ja hänen huoneensa perilliset, ja annan sinun huonees tulla niinkuin Jerobeamin Nebatin pojan huoneen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Joka Baesan suvusta kuolee kaupungissa, se pitää koirilta syötämän, ja joka kuolee kedolla se pitää taivaan linnuilta syötämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Mitä enempi on puhumista Baesasta ja hänen töistänsä ja voimastansa: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Ja Baesa nukkui isäinsä kanssa ja haudattiin Tirtsaan. Ja hänen poikansa Ella tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Ja Herran sana tuli prophetan Jehun Hananin pojan kautta Baesaa ja hänen huonettansa vastaan, ja kaikkea pahuutta vastaan, minkä hän Herran edessä tehnyt oli, vihoittaaksensa häntä kättensä töillä, että sen piti tuleman niinkuin Jerobeamin huone, ja sentähden että hän hänen tappanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Asan Juudan kuninkaan kuudentena vuonna kolmattakymmentä oli Ella Baesan poika Israelin kuningas Tirtsassa kaksi ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Mutta hänen palveliansa Simri, joka hallitsi puolet vaunuja, teki liiton häntä vastaan: kuin hän tuli Tirtsaan, niin hän joi ja juopui Artsan tykönä, joka oli Tirtsan kartanon haltia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Ja Simri tuli ja löi hänen, ja tappoi hänen Asan Juudan kuninkaan seitsemäntenä vuonna kolmattakymmentä, ja tuli hänen siaansa kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Ja kuin hän oli kuningas ja istui kuninkaallisella istuimellansa, löi hän kaiken Baesan huoneen ja ei jättänyt yhtäkään seinään vettänsä heittävää, eikä perillisiä eli lankoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Ja niin hävitti Simri koko Baesan huoneen, Herran sanan jälkeen, joka Baesalle oli puhuttu propheta Jehun kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Kaikkein Baesan ja hänen poikansa Ellan syntein tähden, joita he olivat tehneet, ja olivat saattaneet Israelin syntiä tekemään, ja olivat vihoittaneet Herran Israelin Jumalan turhuudellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Mitä enempi on sanomista Ellasta ja kaikista hänen menoistansa: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Seitsemäntenä kolmattakymmentä Asan Juudan kuninkaan vuonna oli Simri kuningas Tirtsassa seitsemän päivää; sillä väki oli sioittanut itsensä Philistealaisten Gibetonissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Koska väki leirissä ollessansa kuuli sanottavan Simrin tehneen liiton ja tappaneen kuninkaan, niin koko Israel vahvisti sinä päivänä Omrin sodanpäämiehen Israelin kuninkaaksi leirissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Ja Omri meni ylös ja koko Israel hänen kanssansa Gibetonista, ja ahdistivat Tirtsan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Koska Simri näki kaupungin voitettavan, meni hän kuninkaallisen huoneen saliin, ja poltti itsensä kuninkaallisen huoneen kanssa ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'Synteinsä tähden, jotka hän oli tehnyt: sillä hän oli tehnyt pahaa Herran edessä ja vaeltanut Jerobeamin teillä ja niissä synneissä, jotka hän oli tehnyt ja joilla hän oli saattanut Israelinkin syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Mitä enempi on sanomista Simristä, ja kuinka hän oli liiton tehnyt: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Siihen aikaan hajosi Israelin kansa kahteen joukkoon: yksi osa Tibnin Ginatin pojan puolelle, ja vahvistivat hänen kuninkaaksensa ja toinen Omrin puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Mutta se joukko, joka piti Omrin puolta, oli väkevämpi kuin ne, jotka pitivät Tibnin Ginatin pojan puolta. Ja Tibni kuoli, ja Omri tuli kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Asan Juudan kuninkaan ensimmäisenä vuonna neljättäkymmentä oli Omri Israelin kuningas kaksitoistakymmentä ajastaikaa, ja hallitsi Tirtsassa kuusi ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Hän osti Semeriltä Samarian vuoren kahdella hopiasentnerillä, ja rakensi vuorelle, ja kutsui kaupungin, jonka hän rakensi, Semerin vuoren herran nimellä Samariaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Ja Omri teki pahaa Herran edessä, ja oli pahempi kaikkia, jotka hänen edellänsä olleet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Ja vaelsi kaikissa Jerobeamin Nebatin pojan teissä ja hänen synneissänsä, joilla hän Israelin saatti syntiä tekemään, niin että he vihoittivat Herran Israelin Jumalan turhuudellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Mitä enempi on sanomista Omrista, ja kaikista hänen töistänsä, ja hänen voimastansa teoissansa: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Ja Omri nukkui isäinsä kanssa ja haudattiin Samariaan; ja Ahab hänen poikansa tuli kuninkaaksi hänen peräänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Asan Juudan kuninkaan kahdeksantena vuonna neljättäkymmentä oli Ahab Omrin poika kuningas Israelissa, ja hallitsi Israelia Samariassa kaksi ajastaikaa kolmattakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Ja Ahab Omrin poika teki pahaa Herran edessä enemmän kuin kaikki ne, jotka hänen edellänsä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Ja se oli hänelle vähä, että hän vaelsi Jerobeamin Nebatin pojan synneissä, hän otti myös Isebelin, Etbaalin Zidonin kuninkaan tyttären emännäksensä, ja meni palvelemaan ja kumartamaan Baalia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Ja asetti Baalille alttarin Baalin huoneessa, jonka hän oli rakentanut Samariassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Ja Ahab teki metsistön; niin että Ahab vihoitti Herran Israelin Jumalan kovemmin kuin kaikki muut Israelin kuninkaat, jotka hänen edellänsä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Silloin rakensi Hiel Betelistä Jerihon: se maksoi hänen esikoisensa Abiramin, koska hän perustuksen laski, ja hänen nuorimman poikansa Segubin, koska hän sen portit pani, Herran sanan jälkeen, jonka hän oli sanonut Josuan Nunin pojan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Ja Elia Tisbiläinen Gileadin asuja sanoi Ahabille: niin totta kuin Herra Israelin Jumala elää, jonka edessä minä seison, ei pidä näillä vuorilla kastetta eikä sadetta tuleman, muutoin kuin minun sanani jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Ja Herran sana tuli hänen tykönsä sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Mene tästä pois ja käännä itses itään päin, ja lymytä sinus Keritin ojan tykö, joka on Jordanin kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Ja sinun pitää juoman ojasta: ja minä olen käskenyt kaarnetten elättää sinua siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Hän meni ja teki Herran sanan jälkeen, ja meni istui Keritin ojan tykönä, joka on Jordanin kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Ja kaarneet veivät hänelle leipää ja lihaa, huomeneltain ja ehtoona, ja hän joi ojasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Ja monikahtain päiväin perästä kuivui oja; sillä ei ollut sadetta maakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Niin tuli Herran sana hänen tykönsä, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Nouse ja mene Sarpatiin, joka Sidonin tykönä on, ja pysy siellä: katso, minä olen käskenyt leskivaimon sinua siellä elättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Ja hän nousi ja meni Sarpatiin; ja kuin hän kaupungin porttiin tuli, katso, leskivaimo oli siellä ja haki puita, ja hän puhui hänelle, sanoen: tuo minulle vähä vettä astiassa juodakseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Kuin hän meni tuomaan, huusi hän häntä ja sanoi: tuo myös minulle pala leipää kädessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Hän sanoi: niin totta kuin Herra sinun Jumalas elää, ei ole minulla leipää, mutta pivo jauhoja vakkaisessa ja vähä öljyä astiassa: ja katso, minä kokoon kaksi puuta ja menen valmistamaan itselleni ja pojalleni, syödäksemme ja sitte kuollaksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Ja Elia sanoi hänelle: älä pelkää, mene ja tee niinkuin sinä sanonut olet; kuitenkin leivo minulle vähä kyrsäinen siitä ensin ja tuo minulle; mutta itselles ja pojalles pitää myös sinun siitä sen jälkeen tekemän:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Sillä näin sanoo Herra Israelin Jumala: Ei jauhot vakkaisesta pidä loppuman ja öljy astiasta ei pidä puuttuman, siihen päivään asti kuin Herra antaa sataa maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Ja hän meni ja teki niinkuin Elia puhunut oli. Ja hän söi ja myös vaimo perheinensä kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Ei jauhot loppuneet vakkaisesta eikä öljy astiasta, Herran sanan jälkeen, jonka hän Elian kautta puhunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Sen jälkeen tapahtui, että perheen emännän poika sairasti, ja hänen sairautensa oli niin raskas, ettei henkeä hänessä silleen ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Ja hän sanoi Elialle: mitä minulla on sinun kanssas, sinä Jumalan mies? Sinä olet tullut minun tyköni, että minun pahatekoni muistettaisiin ja minun poikani kuolis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Hän sanoi hänelle: tuo minulle poikas. Ja hän otti hänet, hänen sylistänsä, ja vei hänen ylistupaan, kussa hän asui, ja pani hänen omaan vuoteesensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Ja huusi Herran tykö ja sanoi: Herra minun Jumalani! oletkos niin pahoin tehnyt tätä leskeä vastaan, jonka tykönä minä holhotaan, ettäs tapat hänen poikansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Ja hän ojensi itsensä kolmasti nuorukaisen päälle, ja huusi Herran tykö ja sanoi: Herra minun Jumalani, anna tämän nuorukaisen sielu tulla häneen jällensä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Ja Herra kuuli Elian äänen: ja hänen sielunsa tuli häneen jälleen, ja hän virkosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Ja Elia otti pojan ja kantoi ylistuvasta alas huoneesen, ja antoi äidillensä, ja sanoi: katso, sinun poikas elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Ja vaimo sanoi Elialle: nyt minä ymmärrän, ettäs olet Jumalan mies, Herran sana on tosi sinun suussas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Ja monen päivän perästä tuli Herran sana Elian tykö kolmantena vuonna, sanoen: mene ja osoita sinus Ahabille, ja minä annan sataa maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Ja Elia meni näyttämään itsiänsä Ahabille; vaan sangen kallis aika oli Samariassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Ja Ahab kutsui Obadian, joka oli hänen huoneensa haltia: (Ja Obadia pelkäsi Herraa suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Sillä kun Isebel hukutti Herran prophetat, otti Obadia sata prophetaa ja kätki ne, viisikymmentä kuhunkin luolaan, ja elätti heidät leivällä ja vedellä.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Niin sanoi Ahab Obadialle: vaella maan lävitse kaikkein vesilähdetten tykö ja kaikkein ojain tykö, jos löydettäisiin ruohoja hevosille ja muuleille elatukseksi, ettei kaikki eläimet hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Ja he jakoivat itsensä vaeltamaan maata lävitse: Ahab vaelsi yksinänsä yhtä tietä myöten ja Obadia toista tietä yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Kun Obadia tiellä oli, katso, silloin kohtasi hänen Elia; ja kuin hän tunsi hänen, lankesi hän kasvoillensa ja sanoi: etkös ole herrani Elia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Hän sanoi: olen; mene ja sano herralles: katso, Elia on tässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Ja hän sanoi: mitä minä olen rikkonut, ettäs annat palvelias Ahabin käsiin tappaa minua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Niin totta kuin Herra sinun Jumalas elää, ei ole yhtään kansaa eli valtakuntaa, kuhunka minun herrani ei ole lähettänyt, sinua etsimään. Ja koska he ovat sanoneet: ei hän ole tässä, on hän vannottanut sitä valtakuntaa ja kansaa, ettet sinä ole löydetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Ja nyt sinä sanot: mene ja sano herralles: katso, Elia on tässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Ja taitais tapahtua, kuin minä menisin pois sinun tyköäs, niin ottais Herran henki sinun pois, ja en minä tietäisi kuhunka, ja minä sitte tulisin ja sanoisin sen Ahabille, ja hän ei löytäisi sinua, niin hän tappais minun. Mutta minä sinun palvelias pelkään Herraa hamasta nuoruudestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Eikö minun herralleni ole sanottu, mitä minä tehnyt olen, kuin Isebel tappoi Herran prophetat? ja minä kätkin sata Herran prophetaa luoliin, viisikymmentä tänne ja viisikymmentä sinne, ja ruokin heidät leivällä ja vedellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Ja nyt sinä sanot: mene ja sano herralles: katso, Elia on tässä: että hän minun tappais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Elia sanoi: niin totta kuin Herra Zebaot elää, jonka edessä minä seison: tänäpänä minä itseni hänelle ilmoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Niin meni Obadia Ahabia vastaan ja sanoi nämät hänelle, ja Ahab meni Eliaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Ja kuin Ahab näki Elian, sanoi Ahab hänelle: etkö sinä ole se, joka Israelin villitset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Hän sanoi: en minä villitse Israelia, mutta sinä ja sinun isäs huone, että te olette hyljänneet Herran käskyt, ja sinä vaellat Baalin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Lähetä siis nyt kokoamaan minun tyköni koko Israel Karmelin vuorelle, ja neljäsataa ja viisikymmentä Baalin prophetaa ja neljäsataa metsistöin prophetaa, jotka syövät Isebelin pöydältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Niin lähetti Ahab kaikkein Israelin lasten tykö ja kokosi prophetat Karmelin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Niin astui Elia kaiken kansan eteen ja sanoi: kuinka kauvan te onnutte molemmille puolille? Jos Herra on Jumala, niin vaeltakaat hänen jälkeensä, mutta jos Baal, niin vaeltakaat hänen jälkeensä; ja ei kansa häntä mitään vastannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Niin sanoi Elia kansalle: minä olen ainoasti jäänyt Herran prophetaista; mutta Baalin prophetaita on neljäsataa ja viisikymmentä miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Niin antakaat nyt meille kaksi mullia ja antakaat heidän valita toisen mullin ja hakata kappaleiksi, ja pankaan puiden päälle, mutta älkään siihen panko tulta: ja minä otan toisen mullin ja panen myös puiden päälle, ja en pane siihen tulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Ja huutakaat te teidän jumalainne nimeä, ja minä huudan Herran nimeä: kumpi Jumala vastaa tulen kautta, hän olkoon Jumala. Ja kaikki kansa vastasi ja sanoi: se on oikein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Ja Elia sanoi Baalin prophetaille: valitkaat teillenne toinen mulli, ja tehkäät te ensin, sillä teitä on monta, ja huutakaat teidän jumalainne nimeä, ja älkäät siihen tulta panko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Ja he ottivat mullin, jonka hän heille antoi, ja valmistivat ja huusivat Baalin nimeä huomenesta puolipäivään asti, sanoen: Baal, kuule meitä! mutta ei siinä ollut ääntä eli vastaajaa; ja he hyppelivät alttarin ympärillä, jonka he tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Kun jo puolipäivä oli, pilkkasi heitä Elia ja sanoi: huutakaat vahvasti; sillä hän on jumala, hän ajattelee jotakin, eli on jotakin toimittamista, eli on matkalla, eli jos hän makaa, että hän heräis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Ja he huusivat suurella äänellä, ja viileskelivät itsiänsä veitsillä ja naskaleilla tavallansa, niin että he verta tiukkuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Kuin puolipäivä kulunut oli, propheterasivat he siihenasti, että ruokauhri uhrattaman piti; ja ei ollut siinä ääntä eli vastaajaa, elikkä joka vaaria otti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Niin sanoi Elia kaikelle kansalle: tulkaat minun tyköni; ja kuin kaikki kansa tuli hänen tykönsä, paransi hän Herran alttarin, joka kukistunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Ja Elia otti kaksitoistakymmentä kiveä Jakobin lasten luvun jälkeen (jonka tykö Herran sana tapahtunut oli, sanoen: Israel pitää sinun nimes oleman),');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Ja rakensi niistä kivistä alttarin Herran nimeen, ja teki kuopan alttaria ympäri kahden jyvämitan leveydeltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Ja latoi puut, ja hakkasi mullin kappaleiksi, ja pani sen puiden päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Ja sanoi: täyttäkäät neljä kadia vedellä ja kaatakaat se polttouhrin ja puiden päälle; ja hän sanoi: tehkäät se vielä toinen kerta; ja he tekivät sen toisen kerran; ja hän sanoi: tehkäät se vielä kolmas kerta; ja he tekivät sen kolmannen kerran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Ja vesi juoksi alttaria ympäri, että kuoppakin täytettiin vedestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Ja koska ruokauhri piti uhrattaman, astui propheta Elia edes ja sanoi: Herra Abrahamin, Isaakin ja Israelin Jumala! ilmoita tänäpänä, että sinä olet Israelin Jumala, ja minä sinun palvelias, ja että minä nämä kaikki sinun sanas jälkeen tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Kuule minua Herra, kuule minua, että tämä kansa tietäis sinun olevan Herran Jumalan; ettäs kääntäisit heidän sydämensä takaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Niin putosi Herran tuli ja poltti polttouhrin, puut, kivet ja mullan, ja nuoli veden kuopasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Kuin kaikki kansa näki sen, heittäysivät he kasvoillensa ja sanoivat: Herra on Jumala, Herra on Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Mutta Elia sanoi heille: ottakaat Baalin prophetat kiinni, ettei yksikään heistä pääsisi. Ja he ottivat heidät kiinni; ja Elia vei heidät Kisonin ojan tykö ja tappoi heidät siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Ja Elia sanoi Ahabille: mene ylös, syö ja juo; sillä suuren sateen hyminä kuuluu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Ja kuin Ahab meni syömään ja juomaan, meni Elia Karmelin kukkulalle, ja lankesi maahan, ja kumarsi kasvoillensa, ja pani päänsä polviensa välille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Ja sanoi palveliallensa: mene nyt ylös ja katso meren puoleen. Hän meni ylös, katsoi ja sanoi: ei siellä ole mitään. Hän sanoi: mene vielä sinne seitsemän kertaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Ja seitsemännellä kerralla sanoi hän: katso sieltä nousee vähä pilvi merestä, niinkuin miehen kämmen. Hän sanoi: mene ja sano Ahabille: valjasta ja mene, ettei sade sinua käsittäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Ja sillä välillä tuli taivas pilvistä mustaksi ja tuulesta, ja tuli sangen suuri sade. Mutta Ahab matkusti ja tuli Jisreeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Ja Herran käsi oli Elian päällä, ja hän vyötti kupeensa ja juoksi Ahabin edellä, siihenasti kuin hän tuli Jisreeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Ja Ahab ilmoitti Isebelille kaikki mitä Elia tehnyt oli, ja kuinka hän oli tappanut prophetat miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Niin lähetti Isebel sanansaattajat Elialle, sanoen: jumalat minun niin ja niin tehköön, jollen minä huomenna tällä aikaa tee sinun sielulles, niinkuin yhdelle näiden sielulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Kuin hän sen näki, nousi hän ja meni kuhunka hän tahtoi, ja tuli Bersebaan, joka oli Juudassa, ja jätti sinne palveliansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Mutta itse hän meni korpeen päiväkunnan matkan; ja kuin hän tuli sinne, istui hän katavan alle, rukoillen sieluansa kuolemaan, ja sanoi: jo kyllä on, Herra, ota nyt sieluni; sillä en minä ole parempi isiäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Ja hän pani maata ja nukkui katavan alle; ja katso, enkeli tarttui häneen ja sanoi hänelle: nouse ja syö!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Mutta kuin hän katsahti ympärillensä, katso, niin oli hänen päänsä takana hiilillä kypsytetty leipä ja astia vettä; ja koska hän syönyt ja juonut oli, niin hän pani maata jälleen ja nukkui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Ja Herran enkeli palasi hänen tykönsä toisen kerran, tarttui häneen ja sanoi: nouse ja syö! sillä sinulla on pitkä matka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Ja hän nousi, söi ja joi, ja matkusti sen ruan voimalla neljäkymmentä päivää ja neljäkymmentä yötä Herran vuoreen Horebiin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Ja tuli siellä luolaan, ja oleskeli siellä yötä; ja katso, Herran sana sanoi hänelle: mitäs tässä Elia teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Hän vastasi: minä olen kiivauksella kiivannut Herran Jumalan Zebaotin tähden; sillä Israelin lapset ovat hyljänneet sinun liittos, ja sinun alttaris kukistaneet ja tappaneet sinun prophetas miekalla, ja minä yksinäni jäin, ja he etsivät minun henkeäni, ottaaksensa sitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Hän sanoi: mene tästä ulos ja astu vuorelle Herran eteen. Ja katso, Herra meni ohitse, ja suuri ja väkevä tuuli kävi, joka vuoret halkasi ja mäet särki Herran edellä; mutta ei Herra ollut tuulessa; ja tuulen perästä tuli maanjäristys, ja ei Herra ollut maanjäristyksessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Ja maanjäristyksen perästä tuli tulta, ja ei Herra ollut tulessa; tulen perästä tuli hieno tuulen hyminä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Kuin Elia sen kuuli peitti hän kasvonsa hameellansa, ja meni ulos ja seisoi luolan ovella, ja katso, ääni sanoi hänelle: mitä sinulla tässä on (tekemistä), Elia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Hän vastasi: minä olen kiivauksella kiivannut Herran Jumalan Zebaotin tähden; sillä Israelin lapset ovat hyljänneet sinun liittos, kukistaneet sinun alttaris ja tappaneet sinun prophetas miekalla, ja minä ainoasti jäin, ja he etsivät minun henkeäni, ottaaksensa sitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Mutta Herra sanoi hänelle: palaja tietäs myöten Damaskun korpeen: mene ja voitele Hasael Syrian kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Ja voitele Jehu Nimsin poika Israelin kuninkaaksi; ja Elisa Saphatin poika, AbelMeholasta, voitele prophetaksi sinun siaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Ja tapahtuu, että joka välttää Hasaelin miekan, se tapetaan Jehulta, ja joka välttää Jehun miekan, se tapetaan Elisalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Mutta minä jätän seitsemäntuhatta Israeliin: kaikki polvet, jotka ei kumartaneet Baalia, ja kaikki suut, jotka ei hänen suuta antaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Ja hän läksi sieltä ja kohtasi Elisan Saphatin pojan, joka kynti kahdellatoistakymmenellä parilla härkiä, ja hän itse oli niiden kahdentoistakymmenen seassa; ja Elia meni hänen tykönsä ja heitti hameensa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Ja hän jätti härjät ja juoksi Elian perässä, ja sanoi: anna minun suuta antaa minun isälleni ja äidilleni, niin minä seuraan sinua; hän sanoi hänelle: mene ja tule jälleen; sillä mitä minä sinulle tein?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Ja hän palasi hänen tykönsä, ja otti parin härkiä ja uhrasi sen, ja keitti lihan härkäin kaluilla, ja antoi kansalle syödä; ja hän nousi ja seurasi Eliaa, ja palveli häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Ja Behadad Syrian kuningas kokosi kaikki sotaväkensä ja oli kaksineljättäkymmentä kuningasta hänen kanssansa, ja hevoset ja vaunut; ja hän meni ja piiritti Samarian, ja soti sitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Ja lähetti sanansaattajat Ahabille Israelin kuninkaalle kaupunkiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Ja käski hänelle sanottaa: näin sanoo Benhadad: sinun hopias ja kultas ovat minun, ja sinun emäntäs ja ihanimmat lapses ovat myös minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Israelin kuningas vastasi ja sanoi: herrani kuningas, niinkuin sinä sanonut olet, minä olen sinun ja kaikki mitä minulla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Ja sanansaattajat tulivat jälleen ja sanoivat: näin sanoo Benhadad: minä olen lähettänyt sinun tykös sanan, sanoen: sinun hopias ja kultas, emäntäs ja lapses pitää sinun minulle antaman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Niin minä huomenna tällä aikaa lähetän palveliani sinun tykös tutkimaan sinun huonees ja sinun palvelias huoneet: ja mitä sinulla rakkainta on, pitää heidän ottaman ja tuoman tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Niin Israelin kuningas kutsui kaikki maan vanhimmat ja sanoi: tutkikaat ja katsokaat, mitä pahuutta on hänen mielessänsä; sillä hän lähetti sanan minun tyköni, minun emännistäni ja lapsistani, hopiastani ja kullastani, ja en ole minä häneltä kieltänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Niin sanoivat hänelle kaikki vanhimmat ja kaikki kansa: ei sinun pidä häntä kuuleman, eikä häneen suostuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Ja hän sanoi Benhadadin sanansaattajille: sanokaat herralleni kuninkaalle: kaikki minkä hän käski minulle palveliallensa ensin, teen minä, mutta tätä en minä taida tehdä. Ja sanansaattajat menivät takaperin ja sanoivat vastauksen hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Sitte lähetti Benhadad hänen tykönsä ja käski hänelle sanoa: jumalat tehköön minulle niin ja niin, jos multa Samariassa piisaa, että kaikki minua seuraava kansa taitais siitä ottaa pivonsa täyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Mutta Israelin kuningas vastasi ja sanoi: sanokaat: joka vyöttää itsensä, älkään kerskatko, niinkuin se joka riisuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Kuin hän sen kuuli, kuningasten kanssa juodessansa majassa, sanoi hän palvelioillensa: valmistakaat teitänne. Ja he valmistavat heitänsä kaupunkia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Ja katso, yksi propheta astui Ahabin Israelin kuninkaan tykö ja sanoi: näin sanoo Herra; etkös nähnyt kaikkea sitä suurta joukkoa? Katso, minä annan heidät sinun käsiis tänäpänä, että sinun pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Ahab sanoi: kenen kautta? Ja hän sanoi: näin sanoo Herra: maan ruhtinasten palveliain kautta: Hän sanoi: kuka alkaa sodan? Hän vastasi: sinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Niin hän luki maan ruhtinasten palveliat, ja heitä oli kaksisataa ja kaksineljättäkymmentä. Ja niiden jälkeen luki hän kaiken kansan jokaisesta Israelin lapsista, seitsemäntuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Ja he läksivät ulos puolipäivästä; mutta Benhadad oli juopuneena majassa kahdenneljättäkymmentä kuninkaan kanssa, jotka häntä auttamaan tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Ja maan ruhtinasten palveliat läksivät ulos ensin; mutta Benhadad lähetti, ja he ilmoittivat hänelle, sanoen: miehet lähtevät ulos Samariasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Hän sanoi: joko he ovat rauhan tähden uloslähteneet, niin käsittäkäät heitä elävinä, eli jos he ovat lähteneet sotaan, niin ottakaat heitä myös elävinä kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Niin maan ruhtinasten palveliat olivat lähteneet kaupungista ja sotaväki heidän perässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Ja niin löi mies miehensä ja Syrialaiset pakenivat, ja Israel ajoi heitä takaa; ja Benhadad Syrian kuningas pääsi hevostensa selkään hevosmiestensä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Niin Israelin kuningas läksi ulos ja löi hevosia ja vaunuja; ja hän tappoi sangen paljo Syrialaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Niin astui propheta Israelin kuninkaan tykö ja sanoi hänelle: mene ja vahvista sinus, ymmärrä ja katso, mitä sinun tekemän pitää; sillä Syrian kuningas on sinua vastaan nouseva jälleen tämän vuoden perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Ja Syrian kuninkaan palveliat sanoivat hänelle; heidän jumalansa ovat vuorten jumalat, sentähden voittivat he meidät: jos me vielä heitä vastaan kedolla sodimme, mitämaks me voitamme heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Niin tee nyt tämä: ota kaikki kuninkaat pois heidän sioistansa ja pane ruhtinaat heidän siaansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Ja aseta sinulles sotajoukko, senkaltainen kuin tämä sotajoukko oli, ja hevoset ja vaunut niinkuin ennenkin, ja me sodimme heitä vastaan kedolla, mitämaks me voitamme heidät. Ja hän kuuli heitä ja teki niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Kuin ajastaika kulunut oli, asetti Benhadad Syrialaiset, ja meni ylös Aphekiin, sotimaan Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Ja Israelin lapset nousivat myös ja hankitsivat itsensä ja menivät heitä vastaan; ja Israelin lapset sioittivat itsensä heidän kohdallensa, niinkuin kaksi vähää vuohilaumaa; mutta maa oli täynnä Syrialaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Ja Jumalan mies astui edes ja sanoi Israelin kuninkaalle: näin sanoo Herra: että Syrialaiset ovat sanoneet: Herra on vuorten Jumala ja ei laaksoin Jumala, niin minä tahdon antaa kaiken tämän suuren joukon sinun kätees, että tietäisitte minun olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Ja he asettivat leirinsä toistensa kohdalle seitsemäksi päiväksi, mutta seitsemäntenä päivänä he menivät sotimaan yhteen. Ja Israelin lapset löivät Syrialaisia satatuhatta jalkamiestä yhtenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Mutta jääneet pakenivat Aphekin kaupunkiin. Ja muuri kaatui seitsemänkolmattakymmenen tuhannen miehen päälle, jotka jääneet olivat. Ja Benhadad pakeni myös kaupunkiin, yhdestä majasta toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Niin sanoivat hänen palveliansa hänelle: katso, me olemme kuulleet Israelin huoneen kuninkaat olevan laupiaat kuninkaat: niin pankaamme säkit kupeisiimme ja köydet päihimme ja menkäämme Israelin kuninkaan tykö, kuka tiesi että hän sallii sinun sielus elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Ja he panivat säkit kupeisiinsa ja köydet päihinsä ja tulivat Israelin kuninkaan tykö, ja sanoivat: Benhadad palvelias sanoo sinulle: minä rukoilen, salli minun sieluni elää. Ja hän sanoi: vieläkö hän elää? hän on minun veljeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Niin ne miehet ottivat kiinni sen sanan häneltä nopiasti ja käänsivät itsellensä hyväksi, ja sanoivat: sinun veljes Benhadad: niin hän sanoi: menkäät ja johdattakaat häntä tänne. Niin Benhadad meni hänen tykönsä, ja hän antoi hänen istua vaunuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Ja hän sanoi hänelle: ne kaupungit, jota minun isäni sinun isältäs ottanut on, annan minä jälleen, ja tee kadut sinulles Damaskuun, niinkuin minun isäni teki Samariassa: niin minä teen liiton sinun kanssas ja annan sinun mennä. Ja hän teki liiton hänen kanssansa ja päästi hänen menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Silloin sanoi yksi mies prophetan lapsista lähimmäisellensä Herran sanan kautta: lyö minua! vaan hän kielsi, ettei hän häntä lyönyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Niin hän sanoi hänelle jällensä: ettet sinä kuullut Herran ääntä, katso, koskas lähdet minun tyköäni, niin jalopeura lyö sinun. Ja kuin hän läksi hänen tyköänsä, kohtasi hänen jalopeura ja löi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Ja hän löysi toisen miehen ja sanoi: lyö minua! Ja se mies löi häntä kovasti ja haavoitti hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Niin propheta meni pois ja seisoi tiellä kuningasta vastassa, ja muutti kasvonsa tuhalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Ja kuin kuningas siitä kävi ohitse, huusi hän kuningasta ja sanoi: palvelias meni keskelle sotaa, ja katso mies pakeni ja johdatti miehen minun tyköni, ja sanoi: kätke tämä mies! jos niin on, että hän kaiketikin tulee pois, niin pitää sinun sielus oleman hänen sielunsa siassa, eli sinun pitää punnitseman sen edestä leiviskän hopiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Ja koska sinun palveliallas siellä ja täällä tekemistä oli, niin ei hän enää siellä ollut. Niin sanoi Israelin kuningas hänelle: sinun tuomios on oikia, sinä olet itse sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Niin hän otti kohta tuhan pois kasvoistansa; ja Israelin kuningas tunsi hänen olevan prophetoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Ja hän sanoi hänelle: näin sanoo Herra: ettäs päästit minulta kirotun miehen kädestäs, pitää sinun sielus oleman hänen sielunsa edestä ja sinun kansas pitää oleman hänen kansansa edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Niin Israelin kuningas meni vihaisena ja pahalla mielellä huoneesensa ja tuli Samariaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Sitte tapahtui, että Nabotilla Jisreeliläisellä oli viinamäki Jisreelissä, läsnä Ahabin Samarian kuninkaan huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Ja Ahab puhui Nabotille ja sanoi: anna minulle viinamäkes kaalimaaksi, että se on niin läsnä huonettani, ja minä annan sinulle sen edestä paremman viinamäen: eli jos sinun niin kelpaa, niin minä annan sinulle hopiaa niin paljo kuin se maksaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Mutta Nabot sanoi Ahabille: Herra varjelkoon minua antamasta sinulle isäini perintöä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Niin Ahab tuli kotiansa pahalla mielellä ja vihoissansa, sen sanan tähden minkä Nabot Jisreeliläinen hänelle puhunut oli, sanoen: en minä anna sinulle isäini perintöä; ja hän heittäysi vuoteesen, käänsi kasvonsa ja ei syönyt leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Niin tuli Isebel hänen emäntänsä hänen tykönsä ja sanoi hänelle: mikä se on, että henkes on niin murheellinen, ja et syö leipää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Niin hän sanoi hänelle: minä olen puhutellut Nabotia Jisreeliläistä ja sanonut: anna minulle viinamäkes rahan edestä, eli jos tahdot, niin minä annan sinulle toisen viinamäen sen edestä. Mutta hän sanoi: en minä anna sinulle viinamäkeäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Niin Isebel hänen emäntänsä sanoi hänelle: sinä hallitset nyt Israelin valtakunnan. Nouse ja syö leipää ja ole hyvällä mielellä: minä saatan sinulle Nabotin Jisreeliläisen viinamäen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Ja hän kirjoitti kirjan Ahabin nimellä, ja lukitsi sen hänen sinetillänsä, ja lähetti sen kirjan vanhimpain ja ylimmäisten tykö, jotka hänen kaupungissansa asuivat Nabotin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Ja kirjoitti näin kirjaan, sanoen: kuuluttakaat paasto, ja asettakaat Nabot istumaan ylimmäiseksi kansan sekaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Ja tuokaat kaksi pahanjuonista miestä häntä vastaan, jotka tunnustavat ja sanovat: sinä olet kironnut Jumalaa ja kuningasta: ja viekäät häntä ulos ja kivittäkäät häntä kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Niin vanhimmat ja sen kaupungin ylimmäiset, jotka hänen kaupungissansa asuivat, tekivät niinkuin Isebel heidän käskenyt oli ja niinkuin kirjassa kirjoitettu oli, jonka hän heidän tykönsä lähettänyt oli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Kuuluttivat paaston, ja antoivat Nabotin istua ylimmäiseksi kansan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Niin tuli kaksi pahanjuonista miestä ja istui hänen kohdallensa, ja tunnustivat Nabotia vastaan kansan edessä ja sanoivat: Nabot on kironnut Jumalaa ja kuningasta; niin veivät he hänen kaupungista ulos ja kivittivät hänen juuri kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Ja he lähettivät Isebelin tykö, sanoen: Nabot on kivitetty ja kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Kun isebel kuuli Nabotin kivitetyksi ja kuolleeksi, sanoi hän Ahabille: nouse ja omista Nabotin Jisreeliläisen viinamäki, jonka hän sinulta on kieltänyt rahan edestä; sillä ei Nabot elä, vaan on kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Kuin Ahab kuuli Nabotin kuolleeksi, nousi hän menemään ja omistamaan Nabotin Jisreeliläisen viinamäkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Mutta Herran sana tuli Elialle Tisbiläiselle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Nouse ja mene Ahabia Israelin kuningasta vastaan, joka on Samariassa, (katso, hän on Nabotin viinamäessä, jota hän on mennyt omistamaan.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Ja puhu hänelle ja sano: näin sanoo Herra: pitikö sinun tappaman, ja vielä päälliseksi omistaman? Ja sinun pitää puhuman hänelle ja sanoman: näin sanoo Herra: siinä paikassa, jossa koirat nuoleskelivat Nabotin veren, pitää koirain sinunkin vertas nuoleskeleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Ja Ahab saboi Elialle: löysitkös nyt minun, sinä minun vihamieheni? Hän sanoi: löysin, ettäs olet sinus myynyt pahaa tekemään Herran silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Katso, minä annan tulla pahuuden sinun päälles, ja otan sinun sukukuntas pois, ja hävitän Ahabilta sen, joka vettänsä seinään heittää, ja suljetun ja hyljätyn Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Ja teen sinun huonees niinkuin Jerobeaminkin Nebatin pojan huoneen, ja niinkuin Baesan Ahian pojan huoneen, sen vihoittamisen tähden, millä sinä minua vihoittanut olet, ja saattanut Israelin syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Ja Herra puhui myös Isebelille ja sanoi: koirain pitää syömän Isebelin Jisreelin muurin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Joka Ahabista kuolee kaupungissa, se pitää koirilta syötämän, ja jos joku kuolee kedolla, se pitää taivaan linnuilta syötämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Tosin ei yhtään ollut, joka niin oli itsensä myynyt pahaa tekemään Herran edessä kuin Ahab; sillä hänen emäntänsä Isebel vietteli hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Ja teki aivan suuret kauhistukset, seuraten epäjumalia, kaiken sen jälkeen kuin Amorilaiset tehneet olivat, jotka Herra ajoi Israelin lasten edestä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Koska Ahab nämät sanat kuuli, repäisi hän vaatteensa, ja puki säkin ihollensa ja paastosi, ja makasi säkissä ja kävi suruissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Ja Herran sana tuli Elian Tisbiläisen tykö ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Etkös nähnyt, kuinka Ahab nöyryytti itsensä minun edessäni? että hän itsensä niin nöyryyttää minun edessäni, en minä saata sitä pahaa hänen aikanansa; mutta hänen poikansa aikana saatan minä pahan hänen huoneensa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'Ja he olivat kolme ajastaikaa levossa, ettei ollut sotaa Syrialaisten ja Israelin vaiheilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Mutta kolmantena vuonna meni Josaphat Juudan kuningas Israelin kuninkaan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Ja Israelin kuningas sanoi palvelioillensa: ettekö te tiedä Gileadin Ramotia olevan meidän omamme? ja me istumme ääneti ja emme ota sitä Syrian kuninkaan kädestä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Ja hän sanoi Josaphatille: tuletkos minun kanssani sotimaan Gileadin Ramotia vastaan? Josaphat sanoi Israelin kuninkaalle: minä olen niinkuin sinä, ja minun kansani niinkuin sinun kansas, ja minun hevoseni niinkuin sinun hevoses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Ja Josaphat sanoi vielä Israelin kuninkaalle: kysy siis tänäpänä Herran sanaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Niin Israelin kuningas kokosi prophetaita liki neljäsataa miestä ja sanoi heille: pitääkö minun menemän Gileadin Ramotiin sotaan, taikka lakkaaman? He sanoivat: mene, ja Herra antaa sen kuninkaan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Mutta Josaphat sanoi: eikö tässä ole vielä Herran prophetaa, kysyäksemme häneltä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Ja Israelin kuningas sanoi Josaphatille: vielä on yksi mies, Miika Jimlan poika, jolta kysyttäköön Herraa, mutta minä vihaan häntä; sillä ei hän minulle mitään hyvää ennusta, vaan pahaa. Josaphat sanoi: älköön kuningas niin puhuko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Niin Israelin kuningas kutsui yhden palvelian ja sanoi: tuo Miika Jimlan poika kiiruusti tänne!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Mutta Israelin kuningas ja Josaphat Juudan kuningas istuivat molemmat kuninkaallisella istuimellansa, vaatetettuina (kuninkaallisiin) vaatteisiin Samarian portin raitilla; ja kaikki prophetat ennustivat heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Ja Zedekia Kenanan poika oli tehnyt itsellensä rautasarvet, ja sanoi: näin sanoo Herra: puske näillä Syrialaisia siihenasti kuin he kokonansa hävitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Niin myös kaikki prophetat ennustivat ja sanoivat: mene Gileadin Ramotiin, ja sinä menestyt, Jumala antaa sen kuninkaan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Mutta sanansaattaja, joka oli mennyt Miikaa kutsumaan, puhui hänelle, sanoen: katso, kaikki prophetat ennustavat yhdestä suusta kuninkaalle hyvää: niin olkoon sinun sanas niinkuin heidänkin sanansa, ja puhu hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Niin Miika sanoi: niin totta kuin Herra elää, mitä Herra sanoo minulle, sitä minä puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Mutta kun Miika tuli kuninkaan tykö, sanoi kuningas hänelle: Miika, menemmekö sotimaan Gileadin Ramotiin, taikka lakkaammeko? Hän sanoi hänelle: mene, ja sinä menestyt; sillä Herra antaa sen kuninkaan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Ja kuningas sanoi taas hänelle: kuinka usein minun pitää sinua vannottaman, ettes minulle muuta sanoisi, kuin totuuden Herran nimeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Hän sanoi: minä näin koko Israelin hajoitetuksi vuorille niinkuin lampaat, joilla ei paimenta ole. Ja Herra sanoi: ei näillä ole yhtään isäntää, palatkaan jokainen kotiansa rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Ja Israelin kuningas sanoi Josaphatille: enkö minä sinulle sanonut, ettei hän ennusta minulle hyvää, vaan pahaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Ja hän sanoi: kuule siis Herran sanaa: minä näin Herran istuvan istuimellansa, ja koko taivaallisen sotajoukon seisovan hänen tykönänsä, oikialla ja vasemmalla puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Ja Herra sanoi: kuka pettäis Ahabin, että hän menis ja lankeis Gileadin Ramotissa? Yksi sanoi niin ja toinen näin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Silloin läksi henki, joka seisoi Herran edessä, ja sanoi: minä petän hänen. Jolle Herra sanoi: missä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Hän vastasi: minä menen ja olen valheen henki kaikkein hänen prophetainsa suussa. Hän sanoi: petä häntä, ja sinä taidat, mene ja tee niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Ja katso, nyt Herra antoi valheen hengen kaikkein näiden sinun prophetais suuhun, ja Herra on puhunut sinua vastaan pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Niin astui Zedekia Kenanan poika edes, ja löi Miikaa poskelle, ja sanoi: onko Herran henki paennut minusta sinua puhuttelemaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Miika vastasi: katso, sinä olet sen näkevä sinä päivänä, jona käyt majasta majaan lymytäkses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Niin sanoi Israelin kuningas: ota Miika ja vie häntä jälleen kaupungin päämiehen Amonin tykö ja Joaksen kuninkaan pojan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Ja sano: näin sanoo kuningas: pankaat tämä vankihuoneesen, ja ruokkikaat häntä murheen leivällä ja murheen vedellä, siihen asti kuin minä tulen rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Miika sanoi: jos sinä toki palajat rauhassa, niin ei Herra ole puhunut minun kauttani; ja sanoi: kuulkaat, kaikki kansat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Ja Israelin kuningas ja Josaphat, Juudan kuningas, meni ylös Gileadin Ramotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Ja Israelin kuningas sanoi Josaphatille, koska hän muutti vaatteensa sotaan lähtiessänsä: pue sinä itses omiin vaatteisiis. Ja Israelin kuningas muutti vaatteensa ja meni sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Mutta Syrian kuningas käski vaunuin päämiehille, joita hänellä oli kaksineljättäkymmentä, sanoen: ei teidän pidä sotiman pientä eli suurta vastaan, mutta ainoastansa Israelin kuningasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Koska vaunuin päämiehet näkivät Josaphatin, sanoivat he: tämä on tosin Israelin kuningas, ja poikkesivat sotimaan häntä vastaan. Niin Josaphat huusi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Koska vaunuin päämiehet näkivät, ettei se ollut Israelin kuningas, luopuivat he hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Mutta yksi mies jännitti joutsensa yksinkertaisuudessa ja ampui Israelin kuningasta rautapaidan jatkoon. Ja hän sanoi vaunumiehellensä: käännä kätes ja vie minua pois leiristä; sillä minä olen haavoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Ja sinä päivänä oli suuri sota, ja kuningas seisoi vaunuissansa Syrialaisia vastaan, ja kuoli ehtoona, ja veri vuoti hänen haavastansa vaunuin keskelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Ja auringon laskiessa kuulutettiin leirissä sanoen: menkään jokainen kaupunkiinsa ja maallensa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Ja kuningas kuoli ja vietiin Samariaan, ja he hautasivat kuninkaan Samariassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Mutta kuin vaunut virutettiin Samarian kalalammikossa, nuolivat koirat hänen vertansa, ja portot pesivät, Herran sanan jälkeen, jonka hän puhui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Mitä Ahabista enempi on sanomista, ja kaikista hänen töistänsä, ja huoneesta, jonka hän elephantin luista rakensi, ja kaikista kaupungeista, jotka hän rakensi: eikö ne ole kirjoitetut Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Ja niin Ahab nukkui isäinsä kanssa, ja hänen poikansa Ahasia tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Mutta Josaphat Asan poika Juudan kuninkaaksi neljäntenä Ahabin Israelin kuninkaan vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Ja Josaphat oli viiden ajastajan neljättäkymmentä vanha ruvetessansa hallitsemaan, ja hallitsi viisikolmattakymmentä ajastaikaa Jerusalemissa. Ja hänen äitinsä nimi oli Ashuba Silhin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Ja hän vaelsi kaikissa isänsä Asan teissä, eikä poikennut niistä, ja teki mitä Herralle kelpasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Mutta ei hän pannut pois korkeuksia, joissa kansa vielä uhrasi ja suitsutti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Ja Josaphat teki rauhan Israelin kuninkaan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Mutta muut Josaphatin sanat ja hänen voimansa ja työnsä, ja sotansa: eikö ne ole kirjoitetut Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Ja mitä huorintekijöistä jäänyt oli hänen isänsä Asan aikana, ne ajoi hän pois maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Ja silloin ei ollut kuningasta Edomissa, vaan yksi oli hänen siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'Josaphat oli antanut tehdä haaksia Tarsikseen, jotka piti Ophririin purjehtiman, kultaa noutamaan; mutta ei ne tulleet matkaan, vaan tulivat särjetyiksi EtseonGeberissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Silloin Ahaisa Ahabin poika sanoi Josaphatille: anna minun palveliaini mennä sinun palveliais kanssa haaksiin; mutta ei Josaphat tahtonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Ja Josaphat kuoli isäinsä kanssa ja haudattiin isänsä Davidin kaupunkiin. Ja Joram hallitsi hänen siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ja Ahasia Ahabin poika tuli Israelin kuninkaaksi Samariassa, Josaphatin kuninkaan seitsemäntenä vuonna toistakymmentä, ja hallitsi Israelia kaksi vuotta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'Ja teki pahaa Herran edessä, ja vaelsi isänsä tiellä, ja äitinsä tiellä ja Jerobeamin Nebatin pojan tiellä, joka Israelin saatti syntiä tekemään. Ja hän palveli Baalia ja kumartaen rukoili häntä, ja vihoitti Herran Israelin Jumalan, kaiken sen jälkeen minkä hänen isänsä oli tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Ja Moabilaiset luopuivat Israelista Ahabin kuoleman jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Ja Ahasia putosi häkin lävitse makaushuoneessansa Samariassa, sairasti ja lähetti sanansaattajat, ja sanoi heille: menkäät ja kysykäät Baalsebubilta, Ekronin jumalalta, jos minä paranen tästä sairaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Mutta Herran enkeli sanoi Elialle Tisbiläiselle: nouse ja mene Samarian kuninkaan sanansaattajia vastaan, ja sano heille: sentähdenkö, ettei yhtään Jumalaa ole Israelissa, te menette neuvoa kysymään Baalsebubilta, Ekronin jumalalta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Sentähden näin sanoo Herra: ei sinun pidä siitä vuoteesta nouseman, jossa makaat, mutta sinun pitää kaiketi kuoleman. Ja Elia meni pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Ja kuin sanansaattajat palasivat hänen tykönsä, sanoi hän heille: miksi te palasitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'He sanoivat hänelle: yksi mies kohtasi meitä ja sanoi meille: menkäät, palatkaat kuninkaan tykö, joka teidät on lähettänyt, ja sanokaat hänelle: näin sanoo Herra: sentähdenkö, ettei yhtään Jumalaa ole Israelissa, sinä lähetät kysymään neuvoa Baalsebubilta, Ekronin jumalalta? Sentähden ei sinun pidä siitä vuoteesta nouseman, johon sinä maata pannut olet, mutta sinun pitää kaiketi kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Ja hän sanoi heille: minkäkaltainen se mies oli, joka kohtasi teitä ja näitä sanoja puhui teille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'He sanoivat hänelle: se mies oli karvainen, ja vyötetty hihnaisella vyöllä. Hän sanoi: se on Elia Tisbiläinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Ja hän lähetti hänen tykönsä yhden viidenkymmenen päämiehen viidenkymmenensä kanssa; ja kuin hän tuli hänen tykönsä, ja katso, hän istui vuoren kukkulalla. Ja hän sanoi hänelle: sinä Jumalan mies, kuningas sanoo: tule alas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Elia vastasi ja sanoi viidenkymmenen päämiehelle: jos minä olen Jumalan mies, niin tulkaan tuli taivaasta ja polttakoon sinun ja sinun viisikymmentäs. Niin tuli lankesi taivaasta ja poltti hänen ja hänen viisikymmentänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Ja hän lähetti taas toisen viidenkymmenen päämiehen hänen tykönsä hänen viidenkymmenensä kanssa, ja hän sanoi hänelle: sinä Jumalan mies, näin sanoo kuningas: tule kiiruusti alas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Elia vastasi ja sanoi heille: jos minä olen Jumalan mies, niin tulkaan tuli taivaasta ja polttakaan sinun ja sinun viisikymmentäs. Niin Jumalan tuli putosi taivaasta ja poltti hänen ja hänen viisikymmentänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Niin hän vielä lähetti kolmannen viidenkymmenen päämiehen hänen viidenkymmenensä kanssa. Kuin hän tuli ylös hänen tykönsä, kumarsi hän polvillensa Elian eteen, rukoili häntä ja sanoi hänelle: sinä Jumalan mies, olkoon siis minun sieluni ja näiden viidenkymmenen sinun palveliais sielut kalliit sinun edessäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Katso, tuli on tullut taivaasta ja on polttanut ne kaksi ensimäistä viidenkymmenen päämiestä heidän viidenkymmenensä kanssa; mutta olkoon minun sieluni kallis sinun edessäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Niin sanoi Herran enkeli Elialle: mene alas hänen kanssansa ja älä mitään pelkää häntä. Niin hän nousi ja meni hänen kanssansa kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Ja hän sanoi hänelle: näin sanoo Herra: ettäs lähetit sanansaattajat ja annoit kysyä neuvoa Baalsebubilta, Ekronin jumalalta, sentähdenkö, ettei yhtäkään Jumalaa olis Israelissa, jonka sanaa kysyttäisiin? niin ei sinun pidä siitä vuoteesta nouseman, johon sinä maata pannut olet, mutta sinun pitää kaiketi kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Ja niin hän kuoli Herran sanan jälkeen, jonka Elia puhunut oli. Ja Joram tuli kuninkaaksi hänen siaansa, toisena Joramin Josaphatin pojan Juudan kuninkaan vuonna; sillä ei hänellä ollut poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Mitä enempi on sanomista Ahasiasta ja mitä hän tehnyt on, eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Niin tapahtui, kuin Herra tahtoi Elian tuulispäässä ottaa ylös taivaasen, kävivät Elia ja Elisa Gilgalissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Ja Elia sanoi Elisalle: istus tässä, sillä Herra on minun lähettänyt Beteliin. Mutta Elisa sanoi: niin totta kuin Herra elää ja sinun sielus elää, en minä luovu sinusta. Ja he tulivat alas Beteliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Silloin kävivät prophetain pojat, jotka Betelissä olivat, Elisan tykö ja sanoivat hänelle: tiedätkös Herran tänäpänä ottavan sinulta pois isäntäs sinun pääs päältä? Hän sanoi: minä kyllä sen tiedän, olkaat ääneti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Ja Elia sanoi hänelle: Elisa, viivys tässä, sillä Herra on minun lähettänyt Jerihoon. Hän sanoi: niin totta kuin Herra elää ja sinun sielus elää, en minä luovu sinusta. Ja niin he tulivat Jerihoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Niin tulivat prophetain pojat, jotka Jerihossa olivat, Elisan tykö ja sanoivat hänelle: tiedätkös Herran tänäpänä ottavan sinulta pois isäntäs sinun pääs päältä? Hän sanoi: minä kyllä sen tiedän, olkaat ääneti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Ja Elia sanoi hänelle: istus tässä, sillä Herra on minun lähettänyt Jordaniin. Hän sanoi: niin totta kuin Herra elää ja sinun sielus elää, en minä luovu sinusta. Ja he kävivät molemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Mutta viisikymmentä miestä prophetain pojista meni pois ja jäivät kauvas seisomaan heidän kohdallansa; vaan he seisoivat ynnä Jordanin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Niin otti Elia hameensa ja kääri kokoon, ja löi veteen, ja vesi hajosi molemmille puolille, niin että he molemmat kävivät kuivina sen lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Ja kuin he tulivat ylitse, sanoi Elia Elisalle: ano, mitä minun pitää sinulle tekemän, ennenkuin minä otetaan pois sinulta. Elisa sanoi: että kaksi osaa hengestäs olis minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Hän sanoi: sinä olet anonut kovaa asiaa; mutta kuitenkin, jos näet minun kuin minä sinulta otetaan pois, se tapahtuu niin sinulle, mutta jos et näe, niin ei se tapahdu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Ja tapahtui kuin he ynnä kävivät ja puhuivat keskenänsä, katso, niin tulivat tuliset vaunut tulisten hevosten kanssa ja eroittivat heidät toinen toisestansa. Ja Elia meni ylös tuulispäässä taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Mutta Elisa näki sen ja huusi: minun isäni, minun isäni, Israelin vaunu ja hänen ratsasmiehensä! ja ei häntä enää nähnyt. Ja hän tarttui vaatteisiinsa ja repäisi ne kahtia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Ja otti Elian hameen ylös, joka häneltä pudonnut oli, palasi ja seisoi Jordanin rannalla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Ja otti Elian hameen, joka häneltä pudonnut oli, löi veteen ja sanoi: kussa on nyt Herra Elian Jumala? ja löi veteen, niin vesi hajosi molemmille puolille, ja Elisa kävi ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Kuin prophetain pojat, jotka toisella puolella Jerihossa olivat, näkivät hänen, sanoivat he: Elian henki lepää Elisan päällä, ja kävivät häntä vastaan ja kumarsivat maahan asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Ja sanoivat hänelle: katso, sinun palvelioissas on viisikymmentä vahvaa miestä, anna heidän mennä etsimään isäntääsi, jos Herran henki on ottanut hänen ja heittänyt jollekulle vuorelle, taikka johonkuhun laaksoon. Hän sanoi: älkäät antako mennä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Mutta he vaativat häntä siihenasti, että hän häpesi, ja sanoi: antakaat mennä! Ja he lähettivät matkaan viisikymmentä miestä, ja he etsivät kolme päivää ja ei löytäneet häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Ja tulivat jälleen hänen tykönsä, ja hän asui Jerihossa; ja hän sanoi heille: enkö minä sanonut teille, ettei teidän pitänyt menemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Ja kaupungin miehet sanoivat Elisalle: katso, tässä kaupungissa on hyvä asua, niinkuin meidän herramme näkee; mutta vesi on paha ja maa hedelmätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Hän sanoi: tuokaat minulle uusi astia ja pankaat suolaa siihen! Ja he toivat sen hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Niin hän meni ulos vesihuokoin tykö ja heitti suolaa niihin, sanoen: näin sanoo Herra: minä olen tämän veden parantanut, ei kuolema, taikka hedelmättömyys pidä heistä tästedes tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Niin parani vesi tähän päivään asti Elisan sanan jälkeen, jonka hän puhui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Ja hän meni sieltä ylös Beteliin, ja hänen mennessänsä tiellä, tulivat pienet pojat kaupungista ja pilkkasivat häntä, sanoen hänelle: tule ylös paljaspää, tule ylös paljaspää!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Ja hän käänsi itsensä, ja kuin hän heidät näki, kirosi hän heitä Herran nimeen. Niin tuli kaksi karhua metsästä ja repeli heistä kaksi poikaa viidettäkymmentä kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Sieltä hän meni Karmelin vuorelle, ja palasi sieltä sitten Samariaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Niin Joram Ahabin poika tuli Israelin kuninkaaksi Samariassa kahdeksantenatoistakymmenentenä Josaphatin Juudan kuninkaan vuonna, ja hallitsi kaksitoistakymmentä vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Ja teki pahaa Herran edessä, vaan ei kuitenkaan niinkuin hänen isänsä ja äitinsä; sillä hän hävitti Baalin patsaan, jonka hänen isänsä tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Mutta kuitenkin hän pysyi Jerobeamin Nebatin pojan synneissä, joka Israelin saatti syntiä tekemään; ei hän luopunut niistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Mutta Mesalla Moabilaisten kuninkaalla oli paljo lampaita, ja hän antoi Israelin kuninkaalle veron, satatuhatta karitsaa ja satatuhatta oinasta villoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Kuin Ahab oli kuollut, luopui Moabilaisten kuningas Israelin kuninkaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Siihen aikaan läksi kuningas Joram Samariasta ja luki kaiken Israelin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Ja meni ja lähetti Josaphatille Juudan kuninkaalle sanomaan: Moabilaisten kuningas on luopunut minusta, tuletkos sotimaan minun kanssani Moabilaisia vastaan? Hän sanoi: minä tulen, minä olen niinkuin sinä, ja minun kansani niinkuin sinun kansas, ja minun hevoseni niinkuin sinun hevoses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Ja sanoi: mitä tietä meidän pitää sinne vaeltaman? Hän vastasi: Edomin korven tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Ja niin läksi Israelin kuningas ja Juudan kuningas ja Edomin kuningas. Ja koska he olivat vaeltaneet ympäri seitsemän päivän matkan, ja ei ollut vettä sotaväellä ja juhdilla, jotka heitä seurasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'Niin sanoi Israelin kuningas: voi! Herra on kutsunut nämät kolme kuningasta antaaksensa heitä Moabilaisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Mutta Josaphat sanoi: onko tässä yhtään Herran prophetaa, kysyäksemme hänen kauttansa neuvoa Herralta? Niin vastasi yksi Israelin kuninkaan palvelioista ja sanoi: tässä on Elisa Saphatin poika, joka kaasi vettä Elian kätten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josaphat sanoi: hänen tykönänsä on Herran sana. Ja Israelin kuningas, ja Josaphat ja Edomin kuningas menivät hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Niin sanoi Elisa Israelin kuninkaalle: mitä sinun on minun kanssani? mene pois isäs prophetain tykö ja äitis prophetain tykö! Israelin kuningas sanoi hänelle: ei, sillä Herra on kutsunut nämät kolme kuningasta antaaksensa heitä Moabilaisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elisa sanoi: niin totta kuin Herra Zebaot elää, jonka edessä minä seison, jollen minä katsoisi Josaphatia Juudan kuningasta, en minä katsahtaisi sinun päälles enkä tottelisi sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Niin tuokaat nyt minulle kanteleensoittaja! Ja kuin soittaja soitti, tuli Herran käsi hänen päällensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'Ja hän sanoi: näin sanoo Herra: tehkäät kuoppia sinne ja tänne tähän ojaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Sillä näin sanoo Herra: ei teidän pidä tuulta eikä sadetta näkemän, ja kuitenkin pitää oja vedellä täytettämän: ja teidän pitää juoman, ja teidän karjanne ja teidän juhtanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Ja tämä on vähä Herran edessä; sillä hän antaa myös Moabilaiset teidän käsiinne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'Niin että te lyötte kaikki vahvat kaupungit ja kaikki valitut kaupungit, ja te kaadatte kaikki hyvät puut ja tukitsette kaikki vesilähteet, ja te turmelette kaikki hyvät pellot kivillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Ja tapahtui aamulla ruokauhrin ajalla, katso, silloin tuli vesi Edomin tietä myöten, ja maa täytettiin vedellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Kuin kaikki Moabilaiset kuulivat, että kuninkaat oli nousseet ylös sotimaan heitä vastaan, kutsuivat he kokoon kaikki, jotka itsensä ensin vyöllä vyöttivät, ja sitä vanhemmat, ja menivät rajoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Mutta kuin he aamulla varhain nousivat, ja aurinko nousi veden yli, niin näkivät Moabilaiset, että vesi oli heitä vastaan punainen niinkuin veri,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Ja sanoivat: se on veri; kuninkaat ovat tapelleet keskenänsä, ja yksi on lyönyt toisen kuoliaaksi: nyt siis, Moab, mene saaliille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Mutta kuin he tulivat Israelin leiriin, niin nousi Israel ja löi Moabilaisia; ja ne pakenivat heidän edellänsä; mutta he kiiruhtivat ja löivät Moabin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Ja kukistivat kaupungit, ja itsekukin heitti kivensä kaikkiin hyviin peltoihin ja täyttivät ne, ja tukitsivat kaikki vesilähteet, ja kaasivat kaikki hyvät puut, siihenasti että he ainoasti Hasaretin muuriin kiviä jättivät; ja he piirittivät sen lingoilla ja löivät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Kuin Moabilaisten kuningas näki sodan olevan ylen väkevän itsiänsä vastaan, otti hän seitsemänsataa miestä tykönsä, jotka vetivät miekan ulos, karataksensa Edomin kuninkaan päälle; vaan ei he voineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Niin otti hän ensimäisen poikansa, joka hänen siaansa piti kuninkaaksi tuleman, ja uhrasi sen polttouhriksi muurin päällä. Silloin tuli Israel sangen vihaiseksi, niin että he menivät pois hänen tyköänsä ja palasivat omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Ja yksi vaimo prophetain poikain emäntiä huusi Elisan tykö ja sanoi: sinun palvelias minun mieheni kuoli: niin sinä tiedät sen, että sinun palvelias pelkäsi Herraa: nyt tuli velkamies, ja tahtoo ottaa kaksi minun poikaani orjaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa sanoi hänelle: mitä minun pitää tekemän sinulle? sano minulle, mitä sinun huoneessas on? Hän sanoi: sinun piiallas ei ole muuta mitään kuin yksi öljyastia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Hän sanoi: mene ja ano koko kyläkunnaltas astioita, tyhjiä astioita niin monta kuin saat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Ja mene sisälle, ja sulje ovi sinun ja sinun poikais perään, ja kaada jokaiseen niihin astioihin: ja koskas olet ne täyttänyt, niin anna ne ottaa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Hän meni pois hänen tyköänsä, sulki oven jälkeensä ja poikainsa jälkeen. He kantoivat astiat hänen eteensä, ja hän kaasi niihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Ja kuin astiat olivat täytetyt, sanoi hän pojallensa: tuo minulle vielä astia. Hän sanoi hänelle: ei ole täällä enää astiaa; niin öljy seisahti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Ja hän tuli ja ilmoitti sen Jumalan miehelle. Hän sanoi: mene ja myy öljy, ja maksa velkamiehes; mutta sinä ja sinun poikas eläkäät jääneestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Ja se tapahtui siihen aikaan, että Elisa meni Sunemiin, ja siellä oli varallinen vaimo, joka vaati häntä syömään tykönänsä. Ja niin usein kuin hän sen kautta vaelsi, poikkesi hän sinne syömään leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Ja hän sanoi miehellensä: katso, minä ymmärrän tämän Jumalan miehen olevan pyhän, joka tässä meidän kauttamme aina vaeltaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Tehkäämme siis tähän ylistupa, ja pankaamme hänelle sinne vuode, pöytä, istuin ja kynttiläjalka, että hän sinne menis, kuin hän meidän tykömme tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Niin tapahtui siihen aikaan, että hän tuli sinne; ja hän meni ylistupaan ja makasi siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Ja hän sanoi palveliallensa Gehatsille: kutsu Sunemin vaimo tänne. Ja kuin hän oli kutsunut hänen, astui hän hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Niin hän sanoi hänelle: sano hänelle: katso, sinä olet tehnyt meille kaiken tämän palveluksen, mitä minun pitää sinulle tekemän? Onko sinulla asiaa kuninkaan taikka sodanpäämiehen tykö? Hän sanoi: minä asun keskellä minun kansaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Hän sanoi hänelle: mitästä siis hänelle pitäis tehtämän? Gehatsi sanoi: ei ole hänellä poikaa, ja hänen miehensä on vanha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Hän sanoi: kutsu häntä; ja kuin hän meni häntä kutsumaan, niin hän tuli omissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Ja hän sanoi: tähän määrättyyn aikaan vuoden perästä pitää sinun syleilemän poikaa. Hän sanoi: ei, minun herrani, sinä Jumalan mies, älä vääryttele piikas edessä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Ja vaimo tuli raskaaksi ja synnytti pojan määrättyyn aikaan vuoden perästä, niinkuin Elisa oli hänelle sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Ja kuin lapsi jo isoksi tuli, niin tapahtui, että hän meni ulos isänsä ja elonleikkaajain tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Ja hän sanoi isällensä: voi-minun päätäni, minun päätäni! Ja hän sanoi palveliallensa: kanna häntä äitinsä tykö!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Ja hän otti hänen ja vei äitinsä tykö; ja hän istui hänen helmassansa puolipäivään asti, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Ja hän nousi ja laski hänen Jumalan miehen vuoteelle, läksi ulos ja sulki oven,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Ja kutsui miehensä ja sanoi: lähetä minun tyköni yksi palvelioista ja yksi aaseista, sillä minä menen Jumalan miehen tykö ja palajan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Ja hän sanoi: miksi sinä hänen tykönsä menet tänäpänä, sillä ei nyt ole uusi kuu taikka sabbati? Hän sanoi: rauha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Ja hän satuloitsi aasin ja sanoi palveliallensa: aja vahvasti, älä viivytä ajamasta, muutoin kuin minä sanon sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Ja niin hän meni pois ja tuli Jumalan miehen tykö Karmelin vuorelle. Kuin Jumalan mies näki hänen tulevan, sanoi hän palveliallensa Gehatsille: katso, se on Sunemin vaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Niin juokse nyt häntä vastaan ja sano hänelle: oletkos rauhassa, ja sinun miehes ja sinun poikas? Hän vastasi: rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Mutta kuin hän tuli vuorelle Jumalan miehen tykö, tarttui hän hänen jalkoihinsa. Ja Gehatsi meni sysäämään häntä pois. Mutta Jumalan mies sanoi: anna hänen olla, sillä hänen sielunsa on murheellinen, ja Herra on minulta sen salannut ja ei ilmoittanut minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Hän sanoi: anoinko minä poikaa minun herraltani? Enkö minä sanonut: älä minua petä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Ja hän sanoi Gehatsille: vyötä sinun kupees ja ota minun sauvani kätees, ja mene matkaas: jos joku sinun kohtaa, niin älä tervehdi häntä, ja jos joku sinua tervehtii, niin älä vastaa häntä: ja laske minun sauvani pojan kasvoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Mutta pojan äiti sanoi: niin totta kuin Herra elää ja sinun sielus elää, en minä päästä sinua. Niin hän nousi ja seurasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Mutta Gehatsi meni pois heidän edellänsä, ja laski sauvansa pojan kasvoille, vaan ei ollut ääntä eikä tuntoa. Niin hän palasi ja kohtasi hänen, ilmoitti hänelle ja sanoi: ei poika herännyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Ja kuin Elisa tuli huoneesen, katso, poika makasi kuolleena hänen vuoteellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Ja hän meni sisälle ja sulki oven molempain perään; ja hän rukoili Herraa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Nousi ja laski itsensä lapsen päälle, ja pani suunsa hänen suunsa päälle, ja silmänsä hänen silmäinsä päälle, ja kätensä hänen kättensä päälle, ja niin ojensi itsensä hänen päällensä, että lapsen ruumis tuli lämpimäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Ja hän nousi jälleen ja kävi kerran sinne ja tänne huoneessa, nousi ja laski itsensä hänen päällensä. Niin poika aivasti seitsemän kertaa, sitte avasi poika silmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Ja hän kutsui Gehatsin ja sanoi: kutsu Sunemin vaimo. Ja kuin hän oli hänen kutsunut, tuli hän sisälle hänen tykönsä. Hän sanoi: ota poikas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Niin hän tuli ja lankesi hänen jalkainsa juureen, kumarsi itsensä maahan, ja otti poikansa ja meni ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Ja Elisa palasi Gilgaliin, ja kallis aika oli maalla, ja prophetain pojat olivat hänen edessänsä. Ja hän sanoi palveliallensa: ota suuri pata ja keitä lientä prophetain pojille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Niin yksi läksi kedolle hakemaan ruohoja, ja löysi metsäviikunapuun, ja haki siitä kolokinteja vaatteensa täyden. Ja kuin hän tuli, leikkasi hän sen liemipataan; sillä ei he tunteneet sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Ja kuin he sen antoivat miesten eteen syödä, söivät he liemestä ja huusivat, sanoen: Jumalan mies, kuolema on padassa! Sillä ei he saaneet syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Ja hän sanoi: tuokaat tänne jauhoja, ja hän heitti pataan ja sanoi: antakaat kansalle syödä, ja ei ollut mitään vahinkoa padassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Ja yksi mies tuli Baalsalisasta ja kantoi Jumalan miehelle uutisleipiä, kaksikymmentä ohraista leipää ja uutisjyviä vaatteissansa. Mutta hän sanoi: anna kansalle, että he söisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Hänen palveliansa sanoi: mitä minä siitä annan sadalle miehelle? Hän sanoi: anna kansalle syödä; sillä näin sanoo Herra: he syövät ja vielä sittenkin jää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Ja hän pani ne heidän eteensä, ja he söivät; ja vielä oli liiaksi Herran sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Ja Naeman Syrian kuninkaan sodanpäämies oli kuuluisa mies ja suurena pidetty herransa edessä; sillä hänen kauttansa oli Herra antanut autuuden Syriaan; ja hän oli voimallinen mies, vaan spitalinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Ja sotaväki oli Syriasta mennyt ulos joukottaisin, ja olivat vieneet pois Israelin maalta vähän piikaisen, joka palveli Naemanin emäntää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Hän sanoi emännällensä: o, jos minun herrani olis prophetan tykönä, joka on Samariassa, niin hän parantais hänen spitalista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Niin hän meni ja ilmoitti herrallensa, sanoen: näin ja näin on puhunut Israelin maan piika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Syrian kuningas sanoi: mene sinne, ja minä lähetän kirjan Israelin kuninkaalle. Ja hän meni sinne ja otti myötänsä kymmenen leiviskää hopiaa ja kuusituhatta kultapenninkiä ja kymmenen vaatekertaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Ja vei kirjan Israelin kuninkaalle näin kirjoitetun: Kuin tämä kirja tulee sinulle, katso, minä lähetin palveliani Naemanin sinun tykös, ettäs hänen puhdistaisit spitalistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Kuin Israelin kuningas oli kirjansa lukenut, repäisi hän vaatteensa ja sanoi: olenko minä Jumala, että minä kuolettaisin ja eläväksi tekisin? Sillä hän lähettää minun tyköni, että minä puhdistaisin miehen spitalista. Havaitkaat siis ja katsokaat, kuinka hän etsii tilaa minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Kuin Jumalan mies Elisa kuuli Israelin kuninkaan reväisseeksi vaatteensa, lähetti hän kuninkaan tykö ja antoi sanoa hänelle: miksis olet reväissyt vaattees? Tulkaan nyt minun tyköni, että hän tietäis prophetan olevan Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Niin tuli Naeman hevosillansa ja vaunuillansa, ja seisahti Elisan huoneen oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Ja Elisa lähetti sanansaattajan hänen tykönsä, sanoen: mene ja pese itses seitsemän kertaa Jordanissa, ja sinun lihas pitää entisellensä ja puhtaaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Niin Naeman vihastui ja meni matkaansa, sanoen: katso, minä luulin hänen kumminkin tulevan ulos minun tyköni, seisovan ja huutavan avuksensa Herran Jumalansa nimeä, ja kädellänsä pitelevän tätä paikkaa, ja niin parantavan spitalin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Eikö Abanan ja Pharpharan virrat Damaskussa ole kaikkia Israelin vesiä paremmat, että minä itseni niissä pesisin ja tulisin puhtaaksi? Ja hän palasi ja meni matkaansa vihoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Niin hänen palveliansa tulivat hänen tykönsä ja puhuttelivat häntä, ja sanoivat: minun isäni! jos propheta olis sanonut sinulle jotakin suurta asiaa, eikö sinun pitänyt sitä tekemän? Mitä enemmin, että hän sanoi sinulle: pese sinus, ja sinä tulet puhtaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Niin hän meni ja pesi itsensä Jordanissa seitsemän kertaa, niinkuin Jumalan mies käskenyt oli, ja hänen lihansa tuli entisellensä, niinkuin vähän nuorukaisen liha, ja tuli puhtaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Ja hän palasi Jumalan miehen tykö kaiken joukkonsa kanssa; ja kuin hän oli tullut sisälle, seisoi hän hänen edessänsä ja sanoi: katso, nyt minä tiedän, ettei yhtäkään Jumalaa ole kaikessa maassa, vaan Israelissa: ota siis nyt tämä siunaus sinun palvelialtas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Mutta hän sanoi: niin totta kuin Herra elää, jonka edessä minä seison, en ota minä sitä. Ja hän vaati häntä ottamaan, mutta hän kielsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Niin sanoi Naeman: eikö palvelialles annettaisi kuorma multaa, niin paljo kuin kaksi muulia kantaa? Sillä palvelias ei tahdo enää muukalaisille jumalille uhrata ja polttouhria tehdä, vaan Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Tässä asiassa olkoon Herra armias palvelialles! kuin herrani menee Rimmonin huoneesen rukoilemaan, ja nojaa minun käteni päälle, ja minä rukoilen Rimmonin huoneessa; niin olkoon Herra tässä asiassa palvelialles armias mies, että minä Rimmonin huoneessa rukoilen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Ja hän sanoi hänelle: mene rauhaan. Ja kuin hän oli mennyt kappaleen matkaa pois hänen tyköänsä kedolle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Sanoi Gehatsi, Jumalan miehen Elisan palvelia: katso, herrani on säästänyt Naemania, tätä Syrialaista, ettei hän häneltä ottanut mitä hän toi; niin totta kuin Herra elää, minä juoksen hänen perässänsä ja otan jotakin häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Niin Gehatsi juoksi nopiasti Naemanin jälkeen. Ja kuin Naeman näki hänen juoksevan perässänsä, astui hän vaunuista ulos häntä vastaan ja sanoi: onko rauha?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Hän sanoi: Rauha. Minun herrani lähetti minun, sanoen: katso, juuri nyt ovat tulleet minun tyköni Ephraimin vuorelta kaksi nuorukaista prophetain pojista, anna heille leiviskä hopiaa ja kahdet juhlapäivän vaatteet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naeman sanoi: ota kaksi leiviskää hopiaa; ja hän vaati hänen, ja sitoi kaksi leiviskää hopiaa kahteen säkkiin, ja kahdet juhlapäivän vaatteet, ja antoi ne kahdelle palveliallensa, ja he kantoivat hänen edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Ja kuin hän tuli Opheliin, otti hän ne pois heidän käsistänsä, ja kätki ne huoneesen, ja päästi miehet, ja he menivät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Ja hän meni sisälle ja seisoi herransa edessä; niin Elisa sanoi hänelle: kustas tulet, Gehatsi? Hän vastasi: ei palvelias ole mennyt sinne eli tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Mutta hän sanoi hänelle: eikö minun sydämeni vaeltanut miehen palatessa vaunuistansa sinua vastaan? Oliko nyt aika sinun mennä ottamaan hopiaa ja ottamaan vaatteita, öljypuita, viinamäkiä, lampaita, härkiä, palvelioita ja piikoja?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Sentähden pitää Naemanin spitali tarttuman sinuun ja sinun siemenees ijankaikkisesti. Niin hän meni pois hänen tyköänsä spitalisena niinkuin lumi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Ja prophetain pojat sanoivat Elisalle: katso, se sia, jossa me asumme sinun tykönäs, on meille ahdas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Anna meidän mennä Jordaniin asti, ja jokaisen tuoda sieltä yksi hirsi, että me rakentaisimme sinne sian asuaksemme. Ja hän sanoi: menkäät!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Ja yksi sanoi: tule palveliais kanssa! Ja hän vastasi: minä tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Ja hän meni heidän kanssansa. Ja kuin he tulivat Jordanin tykö, hakkasivat he siinä puita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Ja kuin yksi heistä oli puun maahan hakannut, putosi rauta veteen, ja hän huusi ja sanoi: voi, herrani! senkin minä olen lainaksi ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Mutta Jumalan mies sanoi: kuhunka se putosi? Ja kuin hän osoitti hänelle paikan, leikkasi hän yhden puun ja heitti sinne, ja saatti niin raudan uiskentelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Ja hän sanoi: ota se ylös! ja hän ojensi kätensä ja otti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Ja Syrian kuningas soti Israelia vastaan, ja piti neuvoa palveliainsa kanssa ja sanoi: me tahdomme sioittaa itsemme sinne ja sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Mutta Jumalan mies lähetti Israelin kuninkaan tykö, ja käski hänelle sanoa: karta, ettes menisi siihen paikkaan; sillä Syrialaiset väijyvät siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Niin lähetti siis Israelin kuningas siihen paikkaan, josta Jumalan mies oli sanonut hänelle, ja varoittanut häntä siitä, ja piti siinä vartiat; ja ei tehnyt sitä ainoasti yhtä eli kahta kertaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Niin Syrian kuninkaan sydän tuli surulliseksi siitä, ja kutsui palveliansa ja sanoi heille: ettekö te ilmoita minulle, kuka meistä on paennut Israelin kuninkaan tykö?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Niin sanoi yksi hänen palvelioistansa: ei niin, herrani kuningas; mutta Elisa propheta, joka on Israelissa, sanoo Israelin kuninkaalle nekin asiat, joitas puhut makaushuoneessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Hän sanoi: niin menkäät matkaan ja katsokaat, kussa hän on, että minä lähettäisin ja antaisin ottaa hänen kiinni. Ja he ilmoittivat hänelle ja sanoivat: katso, hän on Dotanissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Niin hän lähetti sinne hevoset ja vaunut ja suuren joukon; ja kuin he sinne tulivat yöllä, piirittivät he kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Ja Jumalan miehen palvelia nousi varhain aamulla menemään ulos: ja katso, suuri sotajoukko piiritti kaupungin hevosten ja vaunuin kanssa. Niin hänen palveliansa sanoi hänelle: voi, herrani! mitä me nyt teemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Ja hän sanoi: älä pelkää, sillä niitä on enempi jotka meidän kanssamme ovat, kuin niitä, jotka heidän kanssansa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Ja Elisa rukoili ja sanoi: Herra, avaa nyt hänen silmänsä, että hän näkis! Niin avasi Herra palvelian silmät, että hän näki, ja katso, vuori oli täynnä tulisia hevosia ja vaunuja, Elisan ympärillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Ja kuin he tulivat alas hänen tykönsä, rukoili Elisa Herraa ja sanoi: lyö tätä kansaa sokeudella! Ja hän löi heidät sokeudella Elisan sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Ja Elisa sanoi heille: ei tämä ole se tie ja se kaupunki: seuratkaat minua, minä vien teidät sen miehen tykö, jota etsitte; ja hän vei heidät Samariaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Kuin he tulivat Samariaan, sanoi Elisa: Herra, avaa näiden silmät, että he näkisivät! Ja Herra avasi heidän silmänsä, että he näkivät, ja katso, niin he olivat keskellä Samariaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Ja kuin Israelin kuningas näki heidät, sanoi hän Elisalle: isäni, lyönkö minä heitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Ja hän sanoi: älä lyö! Pitääkö sinun lyömän niitä, jotka sinä vangiksi saat miekallas ja joutsellas? Anna heille leipää ja vettä, että he söisivät ja joisivat, ja anna heidän mennä Herransa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Niin valmistettiin heille suuri pito. Ja kuin he olivat syöneet ja juoneet, laski hän heidät menemään, ja he menivät herransa tykö. Ja ei Syriasta enää sotaparvia tullut Israelin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Vaan senjälkeen tapahtui, että Benhadad Syrian kuningas kokosi kaikki sotaväkensä, meni ja piiritti Samarian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Ja suuri nälkä oli Samariassa, ja he ahdistivat kaupunkia, siihenasti että aasin pää maksoi kahdeksankymmentä hopiapenninkiä, ja neljäs osa kabia kyhkyläisen sontaa maksoi viisi hopiapenninkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Ja kuin Israelin kuningas kävi muurin päällä, huusi yksi vaimo häntä ja sanoi: auta minua, herrani kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Ja hän sanoi: jollei Herra auta sinua, kusta minä sinua autan, luvastako eli viinakuurnasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Ja kuningas sanoi hänelle: mikä sinun on? Hän sanoi: tämä vaimo sanoi minulle: tuo tänne poikas, että sen söisimme tänäpänä; syökäämme huomenna minun poikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Ja me olemme keittäneet minun poikani ja syöneet sen. Ja minä sanoin toisena päivänä hänelle: tuo tänne sinun poikas, että me söisimme sen; mutta hän kätki poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Kuin kuningas kuuli vaimon puheet, repäisi hän vaatteensa; ja kuin hän kävi ohitse muurin päällä, niin kansa näki, ja katso, hänen päällänsä oli säkki ihoa vasten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Ja hän sanoi: Jumala tehköön minulle sen ja sen, jos Elisan Zaphatin pojan pää tänäpänä pitää seisoman hänen päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Ja Elisa istui huoneessansa, ja vanhimmat istuivat hänen tykönänsä; mutta hän lähetti miehen edellänsä, mutta ennenkuin sanansaattaja tuli hänen tykönsä, sanoi hän vanhimmille: oletteko nähneet, kuinka se murhamiehen poika on lähettänyt ottamaan minun päätäni pois? Katsokaat, koska sanansaattaja tulee, että te oven suljette ja ovella hänen syöksette ulos: katso, hänen herransa jalkain töminä seuraa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Kuin hän vielä heidän kanssansa puhui, katso, niin sanansaattaja tuli hänen tykönsä ja sanoi: katso, tämä paha tulee Herralta, mitä minä enään odotan Herraa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Mutta Elisa sanoi: kuulkaat Herran sanaa: näin sanoo Herra: huomenna tähän aikaan maksaa vakkainen pieniä jauhoja siklin ja kaksi vakkaista ohria siklin, Samarian portissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Niin vastasi päämies, jonka käden päälle kuningas nojasi, Jumalan miestä ja sanoi: katso, jos Herra tekis vielä akkunat taivaasen, kuinka se tapahtuis? Hän sanoi: katso, silmilläs pitää sinun sen näkemän, mutta ei sinun pidä siitä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Ja neljä spitalista miestä olivat portin edessä, jotka sanoivat toinen toisellensa: mitä me tässä olemme niinkauvan että me kuolemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Jos me sanomme: käykäämme kaupunkiin, niin on nälkä kaupungissa, ja me kuolemme siellä: jos taas olemme täällä, niin me kuolemme: käykäämme siis ja antautukaamme Syrialaisten leiriin, jos he antavat meidän elää, niin me elämme, taikka jos he meidät tappavat, niin me olemme tapetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Ja he nousivat hämärissä menemään Syrialaisten leiriin; ja kuin he tulivat ensimäisille paikoille leiriä, katso, niin ei siellä ollut ketään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Sillä Herra oli antanut Syrialaisten sotajoukon kuulla vaunuin, hevosten ja suuren sotaväen äänen, niin että he sanoivat toinen toisellensa: katso, Israelin kuningas on palkannut meitä vastaan Hetiläisten kuninkaat ja Egyptiläisten kuninkaat, että he tulisivat meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Ja he nousivat ja pakenivat hämärissä, ja jättivät majansa, hevosensa ja aasinsa leiriin, niinkuin ne seisoivat, ja pakenivat henkensä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Kuin spitaliset tulivat leirin ääreen, menivät he yhteen majaan, söivät ja joivat, ja ottivat hopiaa ja kultaa ja vaatteita, ja menivät pois ja kätkivät ne, ja tulivat jälleen ja menivät toiseen majaan, ja ottivat sieltä, menivät pois ja kätkivät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Sitte he sanoivat toinen toisellensa: emme oikein tee: tämä on hyvän sanoman päivä, jos me tämän salaamme ja viivytämme valkiaan aamuun asti, niin meidän pahatekomme tulee tiettäväksi: käykäämme siis ja tehkäämme tiettäväksi kuninkaan huoneelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Ja he tulivat, huusivat kaupungin portin vartioille, ja tekivät tiettäväksi heille ja sanoivat: me menimme Syrialaisten leiriin, ja katso, ei siellä ole ketään, eikä ihmisen ääntä; vaan hevosia ja aaseja sidottuna, ja majat niinkuin ne seisoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Niin huudettiin portin vartioille, ja he ilmoittivat sisälle kuninkaan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Ja kuningas nousi yöllä ja sanoi palvelioillensa: minä sanon teille, kuinka Syrialaiset tekevät meidän kanssamme: he tietävät meidän kärsivän nälkää, ja sentähden ovat he menneet pois leiristä, ja ovat lymyttäneet itsensä kedolle: ja ajattelevat: kuin he lähtevät kaupungista, otamme me heidät kiinni elävänä, ja pääsemme kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Niin vastasi yksi hänen palvelioistansa ja sanoi: niin otettakaan nyt ne viisi hevosta, jotka tähän jääneet ovat: katso, nämät ovat tähän jääneet kaikesta Israelin paljoudesta, katso, ne muut Israelin paljoudesta ovat loppuneet: lähettäkäämme nämät ulos katsomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Niin he toivat kaksi vaunuhevosta, ja kuningas lähetti ne Syrialaisten leiriin ja sanoi: menkäät ja katsokaat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'Ja he menivät heidän jälkeensä hamaan Jordaniin asti, ja katso, kaikki tie oli vaatteita ja kaluja täynnä, joita Syrialaiset kiiruhtaissansa olivat heittäneet pois. Ja sanansaattajat tulivat jälleen ja tiettäväksi tekivät sen kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Niin kansa meni ulos ja ryösti Syrialaisten leirin. Ja tapahtui, että vakkainen sämpyläjauhoja maksoi siklin, niin myös kaksi vakkaista ohria siklin, Herran sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Mutta kuningas asetti päämiehen, jonka käden päälle hän itsensä nojasi, porttiin, ja kansa tallasi hänen portin edessä, niin että hän kuoli, niinkuin Jumalan mies sanonut oli, kuin kuningas tuli alas hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Ja tapahtui niinkuin Jumalan mies puhunut oli kuninkaalle, koska hän sanoi: huomenna tällä aikaa maksaa kaksi vakkaista ohria siklin ja vakkainen sämpyläjauhoja siklin, Samarian portissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Ja päämies vastasi Jumalan miestä ja sanoi: katso, jos Herra tekee vielä akkunat taivaasen, kuinka tämä sittekään tapahtuis? Mutta hän sanoi: katso, sinun pitää silmilläs sen näkemän, ja ei siitä syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Ja se tapahtui hänelle niin; sillä kansa tallasi hänen portissa kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Ja Elisa puhui vaimolle, jonka pojan hän oli herättänyt, ja sanoi: nouse ja matkusta pois huoneines, ja ole outona, kussas saat; sillä Herra on kutsuva nälän, joka on tuleva maalle seitsemäksi vuodeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Vaimo nousi ja teki niinkuin Jumalan mies sanoi, ja matkusti huoneinensa, ja oli outona Philistealaisten maalla seitsemän vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Ja seitsemän vuoden perästä tuli vaimo Philistealaisten maalta jälleen. Ja hän meni rukoilemaan kuninkaalta huonettansa ja peltoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Silloin puhui kuningas Gehatsin, Jumalan miehen palvelian kanssa ja sanoi: juttele minulle kaikki ne suuret teot, mitkä Elisa on tehnyt!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Ja kuin hän ilmoitti kuninkaalle, kuinka hän oli kuolleen virvoittanut, ja katso, vaimo, jonka pojan hän oli kuolleista herättänyt, huusi kuninkaan tykö huoneensa ja peltonsa tähden. Niin sanoi Gehatsi: herrani kuningas, tämä on vaimo, ja tämä on hänen poikansa, jonka Elisa kuolleista herätti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Ja kuningas kysyi vaimolta, ja hän jutteli hänelle sen. Niin kuningas antoi hänelle yhden palvelioistansa ja sanoi: anna hänen saada kaikki, mitä hänen omansa on, ja kaikki tulot pelloista, siitä päivästä, jona hän maan jätti, niin tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Ja Elisa tuli Damaskuun, ja Benhadad Syrian kuningas sairasti, ja hänelle oli ilmoitettu ja sanottu, että Jumalan mies on tullut tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'Niin kuningas sanoi Hasaelille: ota lahjoja myötäs ja mene Jumalan miestä vastaan, ja kysy hänen kauttansa neuvoa Herralta ja sano: parantunenko minä tästä taudista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Ja Hasael meni häntä vastaan ja otti lahjoja myötänsä ja kaikkinaista Damaskun hyvyyttä neljäkymmentä kamelin kuormaa; ja kuin hän tuli, seisoi hän hänen edessänsä ja sanoi: Benhadad, sinun poikas, Syrian kuningas, lähetti minun sinun tykös ja käski sinulle sanoa: parantunenko minä tästä taudista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisa sanoi hänelle: mene ja sano hänelle: kyllä sinä paranisit; mutta kuitenkin on Herra ilmoittanut minulle, että hänen pitää totisesti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Ja (Jumalan mies) katsoi terävästi hänen päällensä, siihenasti että hän häpesi, sitte itki Jumalan mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Niin Hasael sanoi: miksi herrani itkee? Ja hän sanoi: minä tiedän, mitä pahuutta sinun pitää tekemän Israelin lapsille: sinun pitää polttaman heidän väkevät kaupunkinsa tulella, ja heidän nuoret miehensä tappaman miekalla, ja surmaaman heidän lapsensa, ja heidän raskaat vaimonsa halkaiseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hasael sanoi: mikä on sinun palvelias tämä koira, että hän niin suuria asioita tekisi? Elisa sanoi: Herra on minulle ilmoittanut sinun tulevan Syrian kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Ja hän meni pois Elisan tyköä ja tuli herransa tykö, ja hän sanoi hänelle: mitä Elisa sanoi sinulle? Hän vastasi: hän sanoi minulle sinun paranevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Mutta toisena päivänä otti hän yhden makausvaatteen ja kasti veteen, ja levitti hänen kasvoinsa päälle, ja hän kuoli; ja Hasael tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Joramin Ahabin pojan Israelin kuninkaan viidentenä vuonna, ja Josaphatin Juudan kuninkaan (kuolemavuonna) tuli Joram Josaphatin poika Juudan kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Ja hän oli kahden ajastajan vanha neljättäkymmentä tullessansa kuninkaaksi, ja hallitsi kahdeksan ajastaikaa Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Ja vaelsi Israelin kuningasten teillä, niin kuin Ahabin huone teki: sillä Ahabin tytär oli hänen emäntänsä, ja hän teki pahaa Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Mutta palveliansa Davidin tähden ei Herra tahtonut hävittää Juudaa, niinkuin hän oli hänelle sanonut, että hän oli antava hänelle yhden valkeuden ja hänen lapsillensa joka aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Hänen aikanansa luopuivat Edomilaiset Juudasta ja tekivät itsellensä kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Sillä Joram oli matkustanut Zairiin ja kaikki vaunut hänen kanssansa, ja nousi yöllä ja löi Edomilaiset, jotka hänen ympärillänsä olivat, niin myös vaunuin päämiehet, niin että kansa pakeni majoihinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Sentähden luopuivat Edomilaiset Juudasta tähän päivään asti; silloin myös Libna luopui siihen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Mitä enempi Joramista sanomista on ja kaikista niistä, mitä hän tehnyt on: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Ja Joram nukkui isäinsä kanssa ja haudattiin isäinsä kanssa Davidin kaupunkiin. Ja Ahasia hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Joramin Ahabin pojan Israelin kuninkaan toisena vuonna toistakymmentä tuli Ahasia Joramin poika Juudan kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Ja Ahasia oli kahdenkolmattakymmentä vuoden vanha, koska hän tuli kuninkaaksi, ja hallitsi yhden vuoden Jerusalemissa; hänen äitinsä nimi oli Atalia Omrin Israelin kuninkaan tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Ja hän vaelsi Ahabin huoneen teillä ja teki pahaa Herran edessä, niinkuin Ahabin huone; sillä hän oli Ahabin huoneen vävy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Ja hän meni Joramin Ahabin pojan kanssa sotimaan Hasaelia Syrian kuningasta vastaan, Gileadin Ramotissa; mutta Syrialaiset löivät Joramin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Silloin palasi kuningas Joram antamaan parantaa itsensä Jisreelissä niistä haavoista, jotka Syrialaiset löivät häneen Ramassa, hänen soteissa Hasaelin Syrian kuninkaan kanssa; ja Ahasia Joramin poika, Juudan kuningas, tuli katsomaan Joramia Ahabin poikaa Jisreeliin; sillä hän sairasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Mutta Elisa propheta kutsui yhden prophetain poikia ja sanoi hänelle: vyötä kupees ja ota tämä öljyastia kätees, ja mene Gileadin Ramotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Ja kuin tulet sinne, niin sinä näet siellä Jehun Josaphatin pojan Nimsin pojan, mene ja nosta häntä veljeinsä keskeltä, ja vie hänet sisäiseen kamariin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Ota öljyastia ja kaada se hänen päänsä päälle, ja sano: näin sanoo Herra: minä olen voidellut sinun Israelin kuninkaaksi; ja sinun pitää oven avaaman ja pakeneman, eikä siekaileman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Ja prophetan palvelia nuorukainen läksi matkaan, Gileadin Ramotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Ja kuin hän tuli sisälle, katso, siellä istuivat sotaväen päämiehet, ja hän sanoi: sinä päämies, minulla on jotakin sinulle sanomista. Jehu sanoi: kenelle meistä kaikista? Hän sanoi: sinulle, päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Niin hän nousi ja meni sisälle huoneesen, ja hän vuodatti öljyä hänen päänsä päälle, ja sanoi hänelle: näin sanoo Herra Israelin Jumala: minä olen sinun voidellut Israelin, Herran kansan kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Ja sinun pitää lyömän herras Ahabin huoneen; sillä minä vaadin minun palveliaini prophetain veren ja kaikkein Herran palveliain veren Isebelin kädestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Niin että kaikki Ahabin huone pitää hukkuman: ja minä hävitän Ahabista sen, joka vetensä seinään heittää, ja suljetun ja hyljätyn Israelissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Ja teen Ahabin huoneen niinkuin Jerobeaminkin Nebatin pojan huoneen, ja niinkuin Baesan Ahian pojan huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Ja koirat pitää syömän Isebelin Jisreelin pellolla, ja ei yksikään pidä häntä hautaaman. Ja hän avasi oven ja pakeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Ja kuin Jehu läksi ulos herransa palveliain tykö, sanoivat he hänelle: onko rauha? minkätähden tämä mielipuoli on tullut sinun tykös? Hän sanoi heille: te tunnette miehen hyvin, ja mitä hän puhuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'He sanoivat: ei se ole totta; sano sinä se meille. Hän sanoi: niin ja niin on hän puhunut minun kanssani ja sanonut: näin sanoo Herra: minä olen voidellut sinun Israelin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Niin he kiiruhtivat, ja jokainen otti vaatteensa, ja panivat hänen allensa korkialle astuimelle, ja puhalsivat pasunalla, ja sanoivat: Jehu on tullut kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Niin Jehu Josaphatin poika Nimsin pojan teki liiton Joramia vastaan; mutta Joram vartioitsi Ramotia Gileadissa kaiken Israelin kanssa Hasaelia Syrian kuningasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Mutta kuningas Joram oli palannut Jisreeliin parannettavaksi niistä haavoista, jotka Syrialaiset häneen lyöneet olivat, kuin hän soti Hasaelin Syrian kuinkaan kanssa. Ja Jehu sanoi: jos se teidän mieleenne on, niin ei pidä yhdenkään pääsemän kaupungista menemään ja ilmoittamaan Jisreeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Ja Jehu matkusti ratsain ja meni Jisreeliin; sillä Joram sairasti siellä, ja Ahasia Juudan kuningas oli mennyt katsomaan Joramia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Mutta vartia, joka tornin päällä Jisreelissä seisoi, sai nähdä Jehun joukon tulevan ja sanoi: minä näen yhden joukon. Niin sanoi Joram: ota yksi ratsasmies ja lähetä heitä vastaan, ja sano: onko rauha?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Ja ratsasmies ajoi häntä vastaan ja sanoi: näin sanoo kuningas: onko rauha? Jehu sanoi: mitä sinä rauhasta tahdot? käänny minun taakseni! Vartia ilmoitti ja sanoi: sanansaattaja on tullut heidän tykönsä ja ei palaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Niin lähetti hän toisen ratsasmiehen. Kuin se tuli hänen tykönsä, sanoi hän: näin sanoo kuningas: onko rauha? Jehu sanoi: mitä sinä rauhasta tahdot? käännä itses minun taakseni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Sen ilmoitti vartia ja sanoi: hän on tullut heidän tykönsä ja ei palaja: ja sen ajo on niinkuin Jehun Nimsin pojan ajo; sillä hän ajaa niinkuin hän olis hullu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Niin sanoi Joram: valjastakaat! Ja he valjastivat hänen vaununsa. Ja he menivät ulos, Joram Israelin kuningas ja Ahasia Juudan kuningas, itsekukin vaunussansa, ja he läksivät ulos kohtaamaan Jehua, ja löysivät hänen Nabotin Jisreeliläisen pellolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Ja kuin Joram näki Jehun, sanoi hän: Jehu, onko rauha? Hän sanoi: mikä rauha? Äitis Isebelin huoruus ja noituus tulee aina suuremmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Niin Joram kohta käänsi kätensä ympäri ja pakeni, ja sanoi Ahasialle: tässä on petos, Ahasia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Mutta Jehu sivui joutsen ja ampui Joramia lapaluiden välille, niin että nuoli meni hänen sydämensä lävitse, ja hän putosi maahan vaunuistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Ja Jehu sanoi päämiehellensä Bidekarille: ota ja heitä häntä Nabotin Jisreeliläisen pellolle; sillä muista, koska minä ja sinä seurasimme hänen isäänsä Ahabia yhdessä ajaen, että Herra nosti tämän kuorman hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Mitämaks, sanoi Herra, minä kostan sinulle tällä pellolla Nabotin ja hänen poikansa veren, jonka minä eilen ehtoona näin; niin ota nyt häntä ja heitä pellolle Herran sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Kuin Ahasia Juudan kuningas sen näki, pakeni hän kryytimaan huoneen tietä; mutta Jehu ajoi häntä takaa ja sanoi: lyökäät myös häntä vaunuissansa Gurin vastamäessä, joka on Jiblamin tykönä. Ja hän pakeni Megiddoon ja kuoli siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Ja hänen palveliansa antoivat hänen viedä vaunulla Jerusalemiin; ja he hautasivat hänen omaan hautaansa, hänen isäinsä kanssa Davidin kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Mutta Ahasia hallitsi Juudassa Joramin Ahabin pojan ensimäisenä vuotena toistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Ja kuin Jehu tuli Jisreeliin, ja Isebel sai sen kuulla, voiteli hän kasvonsa ja kaunisti päänsä, ja katseli akkunan lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Ja kuin Jehu tuli portista sisälle, sanoi hän: kävikö Simrin hyvästi, joka tappoi herransa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Ja hän nosti kasvonsa ylös akkunaan ja sanoi: kuka on tässä minun tykönäni? Niin käänsi itsensä hänen puoleensa kaksi eli kolme palveliaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Hän sanoi: syöskäät hänet ulos! ja he syöksivät hänen ulos, ja seinä ja hevoset priiskoitettiin hänen verestänsä, ja hän tallattiin maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Ja kuin hän oli tullut sisälle, ja oli syönyt ja juonut, sanoi hän: korjatkaat kuitenkin sitä kirottua ja haudatkaat häntä; sillä hän on kuninkaan tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Kuin he menivät pois häntä hautaamaan, niin ei he löytäneet hänestä muuta mitään kuin pääkallon ja jalat ja paljaat kämmenet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Ja he tulivat jälleen ja sanoivat hänelle sen; hän sanoi: tämä on nyt se minkä Herra puhui palveliansa Elian Tisbiläisen kautta ja sanoi: Jisreelin pellolla pitää koirain syömän Isebelin lihan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Näin tuli Isebelin raato niinkuin loka kedolla, Jisreelin pellolla, ettei sanoa taidettu: tämä on Isebel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Ja Ahabilla oli seitsemänkymmentä poikaa Samariassa. Ja Jehu kirjoitti kirjan ja lähetti Samariaan Jisreelin päämiesten tykö, ja vanhimpain ja Ahabin edustusmiesten tykö, näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Kuin tämä kirje tulee teidän tykönne, joiden tykönä teidän herranne pojat ovat, niin myös vaunut, hevoset, vahvat kaupungit ja sota-aseet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Niin valitkaat herranne pojista paras ja kelvollisin, ja asettakaat häntä isänsä istuimelle, ja sotikaat herranne huoneen puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Mutta he pelkäsivät sangen suuresti ja sanoivat: katso, kaksi kuningasta ei voineet seisoa hänen edessänsä: kuinka siis me seisoisimme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Ja ne huoneen ja kaupungin haltiat, ja vanhimmat ja edustusmiehet lähettivät Jehun tykö, sanoen: me olemme sinun palvelias, me teemme kaikki, mitäs meille sanot: emme tee ketään kuninkaaksi: tee mitä sinulle kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Silloin kirjoitti hän heidän tykönsä toisen kirjan näin: jos te olette minun ja olette minulle kuuliaiset, niin ottakaat teidän herranne poikain päät ja tulkaat huomenna tällä aikaa minun tyköni Jisreeliin; ja oli niitä kuninkaan poikia, joita kaupungin ylimmäiset kasvattivat, seitsemänkymmentä miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Kuin he saivat kirjan, ottivat he ne kuninkaan pojat ja tappoivat seitsemänkymmentä miestä, ja panivat niiden päät astioihin ja lähettivät ne hänen tykönsä Jisreeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Ja sanoma saatettiin hänelle, että he ovat tuoneet kuninkaan poikain päät tänne. Hän vastasi: asettakaat ne kahteen roukkioon aamuun asti, kaupungin portin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Kuin hän aamulla meni ulos, seisoi hän ja sanoi kaikelle kansalle: te olette oikiat: katso, minä olen liiton tehnyt herraani vastaan ja tappanut hänen; mutta kuka siis nämät kaikki tappanut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Niin tietäkäät nyt, ettei yksikään Herran sana, jonka Herra puhunut on Ahabin huoneesta, ole turhaksi tullut: ja Herra teki niinkuin hän puhunut oli palveliansa Elian kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Niin hävitti Jehu kaikki ne jotka Ahabin huoneesta olivat jääneet Jisreelissä: kaikki hänen ylimmäisensä, ja hänen ystävänsä, ja hänen pappinsa, niin ettei hän yhtäkään heistä jättänyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Ja nousi ja matkusti Samariaan, ja kuin hän tuli paimenten majan tykö, joka oli hänen tiessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Löysi Jehu siinä Ahasian Juudan kuninkaan veljet ja sanoi niille: mitkä te olette? He vastasivat: me olemme Ahasian veljet ja menemme tervehtimään kuninkaan ja kuningattaren poikia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Ja hän sanoi: ottakaa heitä elävinä kiinni; ja he ottivat heidät elävinä kiinni, ja tappoivat paimenten majan kaivon tykönä kaksi miestä viidettäkymmentä, niin ettei hän heistä yhtäkään jättänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Ja kuin hän sieltä vaelsi, löysi hän Jonadabin Rekabin pojan, joka häntä kohtasi, tervehti häntä ja sanoi hänelle: onko sinun sydämes vilpitöin, niinkuin minun sydämeni on sinun sydämes kanssa? Jonadab vastasi: on niinkin. Jos niin on, (sanoi hän) niin ojenna kätes tänne; ja hän ojensi kätensä ja hän asetti hänen istumaan sivuunsa vaunuihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Ja sanoi: tule minun kanssani katsomaan minun kiivauttani Herran tähden! Ja hän antoi hänen ajaa vaunuissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Kuin hän Samariaan tuli, löi hän kaikki Ahabista jääneet Samariassa, siihenasti että hän hänen hävitti, Herran sanan jälkeen, jonka hän puhunut oli Elialle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Ja Jehu kokosi kaiken kansan ja antoi heille sanoa: jos Ahab on vähän palvellut Baalia; Jehu tahtoo enemmän häntä palvella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Sentähden kutsukaat kaikki Baalin prophetat kokoon, kaikki hänen palveliansa ja kaikki hänen pappinsa minun tyköni, niin ettei yksikään heistä jää; sillä minä teen suuren uhrin Baalille, ja joka ikänä jää pois, ei sen pidä elämän. Mutta Jehu teki sen kavaluudella, että hän olis saanut hävittää Baalin palveliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Ja Jehu sanoi: pyhittäkäät Baalille juhlapäivä! Ja he kutsuivat kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Ja Jehu lähetti kaikkeen Israeliin, ja kaikki Baalin palveliat tulivat, niin ettei yksikään heistä jäänyt, joka ei tullut; ja he tulivat sisälle Baalin huoneesen ja täyttivät Baalin huoneen joka loukkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Silloin sanoi hän vaatehuoneen haltialle: kanna kaikki Baalin palveliain vaatteet ulos; ja hän kantoi heille vaatteet ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Ja Jehu meni Jonadabin Rekabin pojan kanssa Baalin huoneesen ja sanoi Baalin palvelioille: tutkistelkaat ja katsokaat, ettei kukaan tässä teidän seassanne ole Herran palvelia, vaan ainoastaan Baalin palveliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Kuin he tulivat sisälle tekemään uhria ja polttouhria, asetti Jehu kahdeksankymmentä miestä ulos ja sanoi: kuka teistä yhden niistä, jotka minä teidän käteenne annan, päästää hengissä, hänen sielunsa pitää oleman sen sielun edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Kuin he olivat uhranneet polttouhrin, sanoi Jehu vartioille ja päämiehille: menkäät sisälle ja lyökäät ne, niin ettei yksikään heistä pääse. Ja he löivät heidät miekan terällä, ja vartiat ja päämiehet heittivät heidät pois ja menivät Baalin huoneen kaupunkiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'Ja kantoivat ulos Baalin huoneen patsaat ja polttivat ne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Ja kukistivat Baalin patsaat ja Baalin huoneen ja tekivät niistä yhteiset huoneet hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Näin hävitti Jehu Baalin Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Mutta ei Jehu lakannut Jerobeamin Nebatin pojan synneistä, joka oli saattanut Israelin syntiä tekemään, kultaisilla vasikoilla Betelissä ja Danissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Ja Herra sanoi Jehulle: ettäs olet ollut hyväntahtoinen tekemään sitä mikä minulle kelpasi, ja sinä teit Ahabin huonetta vastaan kaiken sen, mikä minun sydämessäni oli; niin pitää sinun poikas istuman Israelin istuimella neljänteen polveen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mutta ei Jehu kuitenkaan pysynyt, että hän Herran Israelin Jumalan laissa kaikesta sydämestänsä vaeltanut olis; sillä ei hän lakannut Jerobeamin synneistä, joka Israelin oli saattanut syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Silloin rupesi Herra Israelista lohkaisemaan; sillä Hasael löi heidät kaikissa Israelin rajoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Hamasta auringon ylenemisen puolelta Jordania, ja kaiken Gileadin, Gadilaisten, Rubenilaisten ja Manasselaisten maan, hamasta Aroerista, joka on Arnonin ojan tykönä, ja Gileadin ja Basanin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Mitä enempi Jehusta on sanottavaa, ja kaikista hänen töistänsä, ja kaikesta hänen voimastansa: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Ja Jehu nukkui isäinsä kanssa ja haudattiin Samariaan. Ja Joahas hänen poikansa tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Ja aika jonka Jehu Israelia hallitsi Samariassa, oli kahdeksan ajastaikaa kolmattakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Mutta kuin Atalia Ahasian äiti näki poikansa kuolleeksi, nousi hän ja hukutti kaiken kuninkaallisen siemenen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mutta Joseba, kuningas Joramin tytär, Ahasian sisar, otti Joaksen Ahasian pojan ja varasti hänen kuninkaan lasten seasta, jotka tapetut olivat, hänen ja hänen imettäjänsä, makaushuoneesta. Ja he kätkivät hänen Atalian edestä, niin ettei hän tapettu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Ja hän oli kätkettynä Herran huoneessa hänen kanssansa kuusi ajastaikaa; mutta Atalia oli kuningatar maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Seitsemäntenä ajastaikana lähetti Jojada ja otti sadanpäämiehet, esimiehet ja vartiat, ja noudatti heidät tykönsä Herran huoneesen, ja teki liiton heidän kanssansa, ja vannotti heitä Herran huoneessa, ja näytti heille kuninkaan pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Ja käski heitä ja sanoi: tämä on se, jonka teidän tekemän pitää: kolmas osa teistä, jonka vuoro on sabbatina, olkoon kuninkaan huoneen vartiana;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'Ja kolmas osa olkoon Surin portin tykönä, ja kolmas osa olkoon sen portin tykönä, joka on vartiain takana, ja teidän pitää vartioitseman huoneen päällekarkaamista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Mutta kaksi osaa teistä kaikista, jotka sabbatina pääsette, pitää vartioitseman kuningasta Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Ja teidän pitää oleman kuninkaan ympärillä, ja jokaisella aseensa hänen kädessänsä; ja joka tulee järjestykseen, se pitää tapettaman, että te olisitte kuninkaan tykönä hänen mennessänsä ulos ja sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Ja sadanpäämiehet tekivät kaikki, mitä pappi Jojada käskenyt oli, ja ottivat miehensä tykönsä, jotka sabbatina tulivat, niiden kanssa, jotka sabbatina läksivät, ja tulivat papin Jojadan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Ja pappi antoi päämiehille keihäät ja kilvet, jotka olivat olleet kuningas Davidin, ja olivat Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Ja vartiat seisoivat kuninkaan ympärillä, jokaisella aseensa kädessänsä, oikiasta huoneen loukkaasta niin vasempaan loukkaasen, alttaria ja huonetta läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Ja hän toi kuninkaan pojan edes ja pani kruunun hänen päähänsä, ja antoi hänelle todistuksen, ja he tekivät hänen kuninkaaksi ja voitelivat hänen, ja löivät käsiänsä yhteen ja sanoivat: menestyköön kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Ja kuin Atalia kuuli kansan huudon, joka sinne juoksi, meni hän sisälle kansan tykö Herran huoneesen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Ja näki, katso, kuningas seisoi patsaan tykönä, niinkuin tapa oli, ja päämiehet ja vaskitorvet kuninkaan tykönä, ja kaikki maan kansa oli iloissansa ja soittivat vaskitorvilla. Niin Atalia repäisi vaatteensa ja huusi: petos, petos!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Mutta pappi Jojada käski sadanpäämiehiä, jotka olivat pannut joukon päälle, ja sanoi heille: viekäät häntä ulos joukon lävitse, ja jos joku seuraa häntä, se surmattakaan miekalla! Sillä pappi oli sanonut, ettei hänen pitänyt kuoleman Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Ja he laskivat kätensä hänen päällensä, ja hän meni sitä tietä myöten, jota hevoset kuninkaan huoneesen käyvät; ja hän tapettiin siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Niin teki Jojada liiton Herran ja kuninkaan välillä, ja kansan välillä, että he ovat Herran kansa, niin myös kuninkaan ja kansan välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Sitte meni kaikki maan kansa Baalin huoneesen, ja kukistivat sen ja hänen alttarinsa, ja rikkoivat peräti kaikki hänen kuvansa, ja Mattanin Baalin papin tappoivat he myös alttarin edessä; mutta pappi asetti virat Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Ja otti sadanpäämiehet ja esimiehet, ja vartiat ja kaiken maan kansan, ja he johdattivat kuninkaan alas Herran huoneesta, ja tulivat vartiain portin tietä kuninkaan huoneesen. Ja hän istui kuninkaan istuimelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Ja kaikki maan kansa oli iloissansa, ja kaupunki oli alallansa. Mutta Atalian olivat tappaneet miekalla kuninkaan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Ja Joas oli seitsemän ajastaikainen tullessansa kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Seitsemäntenä Jehun vuotena tuli Joas kuninkaaksi, ja hallitsi neljäkymmentä ajastaikaa Jerusalemissa. Hänen äitinsä nimi oli Ziba Bersabasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Ja Joas teki sitä, mikä oikia oli ja Herralle hyvin kelpasi, niinkauvan kuin pappi Jojada opetti häntä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Paitsi ettei hän pannut pois korkeuksia; sillä kansa uhrasi ja teki suitsutusta vielä korkeuksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Ja Joas sanoi papeille: kaikki pyhitetyt rahat, jotka tuodaan Herran huoneesen, nimittäin raha jokaiselta ohitsekäyvältä, raha minkä kukin antaa veroksi hengeltänsä, ja kaikki raha, minkä itsekukin uhraa vapaasta sydämestä, ne kannettakaan Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Ottakaan papit sen itsellensä kukin tuttavaltansa; sillä pitää heidän parantaman sen, mikä rauvennut on Herran huoneessa, kussa ikänä he löytävät olevan rauvenneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Mutta kolmaanteenkolmattakymmentä kuningas Joaksen vuoteen ei olleet papit parantaneet sitä, mikä Herran huoneessa rauvennut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Niin kutsui kuningas Joas papin Jojadan ja muut papit ja sanoi heille: miksi ette paranna sitä, mikä huoneessa rauvennut on? Niin ei pidä nyt teidän ottaman niitä rahoja tykönne kukin tuttavaltansa; mutta antakaat siihen, mikä rauvennut on huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Ja papit mielistyivät, ettei heidän pitänyt ottaman rahaa kansalta eikä parantaman sitä, mikä rauvennut oli huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Niin pappi Jojada otti arkun ja lävisti läven kanteen ja pani sen oikialle puolelle alttaria, josta käydään Herran huoneesen sisälle. Ja papit, jotka vartioitsivat ovea, panivat sinne kaikki ne rahat, jotka tuotiin Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Kuin he näkivät paljon rahaa olevan arkussa, tuli kuninkaan kirjoittaja ja ylimmäinen pappi ylös, ja sitoivat rahan yhteen, joka Herran huoneesta löyttiin, sitte kuin he olivat sen lukeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Ja he antoivat valmiin rahan teettäjille, jotka olivat asetetut Herran huoneesen; ja he antoivat ne puusepille, jotka rakensivat ja työtä tekivät Herran huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'Ja muuraajille, ja kivenhakkaajille, ja niille, jotka hirsiä ja vuoltuja kiviä ostivat, parantaaksensa mitä rauvennut oli Herran huoneessa ja kaikkiin, mitkä he huoneessa löysivät parannusta tarvitsevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Ei kuitenkaan tehty hopiamaljoja, psaltareita, viskaimia, torvia, taikka jotakin kultaista eli hopiaista astiaa Herran huoneesen niistä rahoista, jotka Herran huoneesen tuodut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Mutta ne annettiin työväelle, että he niillä parantaisivat Herran huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Ja ne miehet ei tarvinneet lukua tehdä, joiden käsiin raha annettiin, työväelle annettaa; vaan he toimittivat sen uskollisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Mutta rikosuhrin ja syntiuhrin rahoja ei tuotu Herran huoneesen; sillä ne olivat pappein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Silloin matkusti Hasael Syrian kuningas ja soti Gatia vastaan, ja voitti sen. Ja Hasael käänsi itsensä menemään ylös Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Niin otti Joas Juudan kuningas kaikki pyhitetyt, jotka hänen esivanhempansa Josaphat, Joram ja Ahasia Juudan kuninkaat olivat pyhittäneet, ja ne mitkä hän itse pyhittänyt oli, niin myös kaiken kullan, joka löyttiin Herran huoneen tavaroista ja kuninkaan huoneesta, ja lähetti Hasaelille Syrian kuninkaalle; sitte hän meni Jerusalemista pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Mitä enempi on Joaksesta sanomista, ja kaikista, mitä hän tehnyt on: eikö ne ole kirjoitetut Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Ja hänen palveliansa nousivat ja tekivät liiton, ja löivät Joaksen kuoliaaksi Millon huoneessa, josta mennään alas Sillaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Nimittäin Josabar Simeatin poika ja Josabad Somerin poika, hänen palveliansa, löivät hänen kuoliaaksi. Ja hän haudattiin isäinsä kanssa Davidin kaupunkiin. Ja Amatsia hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Joaksen Ahasian pojan Juudan kuninkaan kolmantena vuotena kolmattakymmentä oli Joahas Jehun poika Israelin kuningas Samarjassa seitsemäntoistakymmentä ajastaikaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Ja teki pahaa Herran edessä, ja vaelsi Jerobeamin Nebatin pojan synneissä, joka Israelin saatti syntiä tekemään, ja ei lakannut siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Ja Herran viha julmistui Israelin päälle ja hän antoi heidät Hasaelin Syrian kuninkaan ja Benhadadin Hasaelin pojan käsiin, niinkauvan kuin he elivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Mutta Joahas rukoili Herran kasvoja, ja Herra kuuli häntä; sillä hän näki Israelin ahdistuksen, kuinka Syrian kuningas ahdisti heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Ja Herra antoi Israelille pelastajan, joka heidät johdatti ulos Syrialaisten käsistä, niin että Israelin lapset asuivat majassansa niinkuin ennenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Ei he kuitenkaan luopuneet Jerobeamin huoneen synneistä, joka Israelin saatti syntiä tekemään, vaan hekin vaelsivat niissä; ja metsistö seisoi Samariassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Mutta Joahaksen kansasta ei enempää jäänyt, kuin viisikymmentä hevosmiestä, ja kymmenen vaunua, ja kymmenentuhatta jalkamiestä; sillä Syrian kuningas oli heidät hukuttanut ja tehnyt niinkuin tomun, riihtä tapettaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Mitä enempi Joahaksesta sanomista on, ja kaikista, mitä hän tehnyt on, ja hänen voimastansa: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Ja Joahas nukkui isäinsä kanssa, ja he hautasivat hänen Samariaan; ja hänen poikansa Joas tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Joaksen Juudan kuninkaan seitsemäntenä vuonna neljättäkymmentä oli Joas Joahaksen poika Israelin kuningas Samariassa kuusitoistakymmentä ajastaikaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Ja teki pahaa Herran edessä, ja ei luopunut kaikista Jerobeamin Nebatin pojan synneistä, joka Israelin saatti syntiä tekemään; vaan vaelsi niissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Mitä enempi Joaksesta sanomista on, ja mitä hän tehnyt on, ja hänen voimastansa, kuinka hän Amatsian Juudan kuninkaan kanssa sotinut on: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Ja Joas nukkui isäinsä kanssa, ja Jerobeam istui hänen istuimellensa. Mutta Joas haudattiin Samariaan Israelin kuningasten oheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Ja Elisa sairasti kuolintautiansa; ja Joas Israelin kuningas tuli hänen tykönsä ja itki hänen edessänsä, ja sanoi: minun isäni, minun isäni, Israelin vaunu ja hänen ratsasmiehensä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Elisa sanoi hänelle: ota joutsi ja nuolet! Ja kuin hän otti joutsen ja nuolet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Sanoi hän Israelin kuninkaalle: jännitä joutsi kädelläs; ja hän jännitti kädellänsä. Ja Elisa laski kätensä kuninkaan kätten päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Ja sanoi: avaa akkuna, joka on itään päin; ja hän avasi sen. Ja Elisa sanoi: ammu; ja hän ampui. Hän sanoi: pelastuksen nuoli Herralta, pelastuksen nuoli Syrialaisia vastaan: ja sinun pitää lyömän Syrialaiset Aphekissa, siihenasti että he lopetetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Ja hän sanoi: ota nuolet! ja kuin hän otti ne, sanoi hän Israelin kuninkaalle: lyö maahan! ja hän löi kolmasti ja sitte lakkasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Niin Jumalan mies närkästyi hänen päällensä ja sanoi: jos olisit lyönyt viidesti eli kuudesti, niin sinä olisit lyönyt Syrialaiset, siihen asti että he olisivat lopetetut; mutta nyt sinun pitää lyömän heitä kolmasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Kuin Elisa oli kuollut, ja he olivat hänen haudanneet, tuli Moabilaisten sotajoukko maakuntaan sinä vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Ja tapahtui, että he hautasivat yhtä miestä, ja kuin he saivat nähdä sotajoukon, heittivät he miehen Elisan hautaan; ja kuin hän sinne tuli ja sattui Elisan luihin, tuli hän eläväksi ja nousi jaloillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Ja Hasael Syrian kuningas ahdisti Israelia, niinkauvan kuin Joahas eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mutta Herra teki armon heidän kanssansa, ja armahti heidän päällensä, ja käänsi itsensä heidän puoleensa, liittonsa tähden Abrahamin, Isaakin ja Jakobin kanssa, ja ei tahtonut kadottaa heitä, eikä heittänyt heitä pois kasvoinsa edestä tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Ja Hasael Syrian kuningas kuoli, ja hänen poikansa Benhadad tuli kuninkaaksi hänen siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Ja Joas Joahaksen poika palasi ja otti ne kaupungit Benhadadilta Hasaelin pojalta jälleen, jotka hän hänen isältänsä Joahakselta sodalla ottanut oli. Joas löi kolmasti häntä, ja sai Israelin kaupungit jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Toisena Joaksen Joahaksen pojan Israelin kuninkaan vuonna tuli Amatsia Joaksen Juudan kuninkaan poika kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Hän oli viiden ajastajan vanha kolmattakymmentä, kuin hän tuli kuninkaaksi, ja hallitsi yhdeksän ajastaikaa kolmattakymmentä Jerusalemissa. Hänen äitinsä nimi oli Joaddan Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Ja hän teki mitä Herralle hyvästi kelpasi, ei kuitenkaan niinkuin hänen isänsä David, vaan kaiketi niinkuin hänen isänsä Joas oli tehnyt, niin myös hän teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Sillä korkeudet ei olleet pannut pois; mutta kansa uhrasi vielä ja suitsutti korkeuksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Ja kuin valtakunta hänen kädessänsä vahvistui, löi hän palveliansa, jotka kuninkaan hänen isänsä tappaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mutta tappajain lapsia ei hän surmannut, niinkuin kirjoitettu on Moseksen lakikirjassa, jossa Herra käskenyt oli ja sanonut: Isät ei pidä kuoleman lasten tähden, ja lapset ei pidä kuoleman isäinsä tähden, vaan jokainen pitää kuoleman oman syntinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Hän löi myös kymmenentuhatta Edomilaista Suolalaaksossa, ja voitti Selan (kaupungin) sodalla, ja kutsui sen nimen Jokteel tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Silloin lähetti Amatsia sanansaattajat Joaksen Joahaksen pojan Jehun pojan Israelin kuninkaan tykö, ja käski hänelle sanoa: tule ja katselkaamme toinen toistamme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Mutta Joas Israelin kuningas lähetti Amatsian Juudan kuninkaan tykö ja antoi hänelle sanoa: orjantappura, Libanonissa, lähetti sedripuun tykö Libanonissa ja antoi hänelle sanoa: anna tyttäres minun pojalleni emännäksi! Mutta metsän eläimet kedolla Libanonissa juoksivat orjantappuran päälle ja maahan tallasivat sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Sinä olet kokonansa lyönyt Edomilaiset, siitä paisuu sinun sydämes: pidä se ylistys ja ole kotonas! miksis etsit vahinkoa kaatuakses sekä itse että Juuda sinun kanssas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Mutta Amatsia ei totellut häntä. Niin meni Joas Israelin kuningas ylös, ja he katselivat toinen toistansa, hän ja Amatsia Juudan kuningas Betsemeksessä, joka Juudassa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Mutta Juuda lyötiin Israelilta, niin että jokainen pakeni majoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Ja Joas Israelin kuningas otti Amatsian Juudan kuninkaan Joaksen pojan, Ahasian pojan, Betsemeksessä kiinni, ja tuli Jerusalemiin, ja kukisti Jerusalemin muurit Ephraimin portista Kulmaporttiin asti, neljänsadan kyynärän pituudelta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Ja otti kaiken kullan ja hopian ja kaikki astiat, jotka löyttiin Herran huoneesta ja kuninkaan huoneen tavaroista, ja vielä hänen lapsensa pantiksi, ja palasi Samariaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Mitä enempi Joaksesta sanomista on, mitä hän tehnyt on, ja hänen väkevyydestänsä, ja kuinka hän Amatsian Juudan kuninkaan kanssa soti: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Ja Joas nukkui isäinsä kanssa ja haudattiin Samariassa, Israelin kuningasten sekaan; ja hänen poikansa Jerobeam tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Mutta Amatsia, Joaksen Juudan kuninkaan poika, eli Joaksen Joahaksen Israelin kuninkaan pojan kuoleman jälkeen viisitoistakymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Mitä enempi Amatsiasta sanomista on: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Ja he tekivät liiton häntä vastaan Jerusalemissa; mutta hän pakeni Lakikseen, ja he lähettivät hänen peräänsä Lakikseen, ja tappoivat hänen siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Ja he veivät hänen sieltä hevosilla pois, ja hän haudattiin Jerusalemissa isäinsä oheen Davidin kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Ja koko Juudan kansa ottivat Asarian kuudentoistakymmenen ajastajan vanhana, ja tekivät hänen kuninkaaksi isänsä Amatsian siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Hän rakensi Elatin ja saatti sen jälleen Juudan alle, sitte kuin kuningas isäinsä kanssa nukkunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Amatsian Joaksen pojan Juudan kuninkaan viidentenä vuonna toistakymmentä oli Jerobeam Joaksen poika Israelin kuningas Samariassa yhden ajastajan viidettäkymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Ja teki pahaa Herran edessä, ja ei lakannut kaikista Jerobeamin Nebatin pojan synneistä, joka Israelin saatti syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Hän otti Israelin maan rajat jälleen, Hematista hamaan kedon mereen asti, Herran Israelin Jumalan sanan jälkeen, jonka hän sanonut oli palveliansa, propheta Jonan, Amittain pojan kautta, joka oli GatHepheristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Sillä Herra näki Israelin suuren viheliäisyyden, niin ettei ollut suljettua, eikä hylättyä, eikä auttajaa Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Ja Herra ei ollut sanonut tahtovansa pyyhkiä Israelin nimeä taivaan alta pois; mutta autti heitä Jerobeamin Joaksen pojan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Mitä enempi Jerobeamista sanomista on, ja kaikista mitä hän tehnyt on, ja hänen väkevyydestänsä, kuinka hän sotinut on, ja kuinka hän otti Damaskun jälleen ja Hematin Juudalle Israelissa: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Ja Jerobeam nukkui isäinsä, Israelin kuningasten kanssa; ja hänen poikansa Sakaria tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Jerobeamin Israelin kuninkaan seitsemäntenä vuonna kolmattakymmentä tuli Asaria Amatsian Juudan kuninkaan poika kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Ja kuudentoistakymmenen ajastaikainen oli hän tullessaan kuninkaaksi, ja hän hallitsi kaksi vuotta kuudettakymmentä Jerusalemissa; hänen äitinsä kutsuttiin Jekolja Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Ja hän teki mitä Herralle hyvästi kelpasi, kaiketi niinkuin hänen isänsä Amatsia tehnyt oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Paitsi sitä ettei he luopuneet korkeuksista; sillä kansa uhrasi ja suitsutti vielä korkeuksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Ja Herra vaivasi kuningasta, niin että hän oli spitalissa kuolemapäiväänsä asti, ja asui erinäisessä huoneessa. Mutta Jotam kuninkaan poika hallitsi huoneen ja tuomitsi kansaa maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Mitä enempi Asariasta sanomista on, ja kaikista, mitä hän tehnyt on: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Ja Asaria nukkui isäinsä kanssa ja haudattiin isäinsä tykö Davidin kaupunkiin; ja hänen poikansa Jotam tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Asarian Juudan kuninkaan kahdeksantena vuonna neljättäkymmentä oli Sakaria Jerobeamin poika Israelin kuningas kuusi kuukautta Samariassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Ja hän teki pahaa Herran edessä, niinkuin hänen isänsäkin tehneet olivat, ja ei luopunut Jerobeamin Nebatin pojan synneistä, joka Israelin saatti syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Ja Sallum Jabeksen poika teki liiton häntä vastaan, ja löi hänen kansan edessä, ja tappoi hänen, ja tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Mitä enempi Sakariasta sanomista on: katso, se on kirjoitettu Israelin kuningasten aikakirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Tämä on Herran sana, jonka hän Jehulle puhunut oli, sanoen: sinun poikas pitää istuman Israelin istuimella neljänteen polveen asti; ja se tapahtui niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Ussian Juudan kuinkaan yhdeksäntenä vuonna neljättäkymmentä tuli Sallum Jabeksen poika kuninkaaksi, ja hallitsi kuukauden Samariassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Sillä Menahem Gadin poika meni ylös Tirsasta ja tuli Samariaan, ja löi Sallumin Jabeksen pojan Samariassa, tappoi hänen ja tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Mitä enempi Sallumista sanomista on ja hänen liitostansa, jonka hän teki: katso, se on kirjoitettu Israelin kuningasten aikakirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Silloin löi Menahem Tipsan ja kaikki jotka siellä olivat, ja löi heidän rajansa Tirsasta, ettei he häntä tahtoneet päästää sisälle, ja kaikki heidän raskaat vaimonsa repäisi hän rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Asarian Juudan kuninkaan yhdeksäntenä vuonna neljättäkymmentä tuli Menahem Gadin poika Israelin kuninkaaksi ja oli kymmenen vuotta Samariassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Ja teki pahaa Herran edessä, ja ei luopunut elinaikanansa Jerobeamin Nebatin pojan synneistä, joka Israelin saatti syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Ja Phul Assyrian kuningas tuli maakuntaan, ja Menahem antoi Phulille tuhannen leiviskää hopiaa, että hän olis pitänyt hänen kanssansa ja vahvistanut häntä valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Ja Menahem pani hopiaveron voimallisten päälle Israelissa, että itsekukin heistä antais viisikymmentä hopiasikliä Assyrian kuninkaalle. Niin meni Assyrian kuningas kotia jälleen ja ei jäänyt maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Mitä enempi Menahemista sanomista on, ja kaikista mitä hän tehnyt on: eikö se ole kirjoitettu Israelin kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Ja Menahem nukkui isäinsä kanssa; ja Pekahja hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Viidentenäkymmenentenä Asarian Juudan kuninkaan vuonna tuli Pekahja Menahemin poika Israelin kuninkaaksi ja oli kaksi vuotta Samariassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Ja teki pahaa Herran edessä; ei hän luopunut Jerobeamin Nebatin pojan synneistä, joka Israelin saatti syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Ja Peka Remaljan poika hänen päämiehensä, kapinoitsi häntä vastaan ja löi hänen kuoliaaksi kuninkaan huoneen salissa, Samariassa, Argobin ja Arjen kanssa, ja viisikymmentä miestä hänen kanssansa Gileadin lapsista. Ja kuin hän oli hänen tappanut, tuli hän kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Mitä enempi Pekahjasta sanomista on ja kaikista mitä hän tehnyt on: katso, se on kirjoitettu Israelin kuningasten aikakirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Asarjan Juudan kuninkaan toisena vuonna kuudettakymmentä tuli Peka Remaljan poika Israelin kuninkaaksi, ja hallitsi Samariassa kaksikymmentä vuotta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Ja teki pahaa Herran edessä, ei hän luopunut Jerobeamin Nebatin pojan synneistä, joka saatti Israelin syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Pekan Israelin kuninkaan aikana tuli Tiglat Pilesser Assyrian kuningas, ja otti Gijonin, Abelbetmaekan, Janoan, Kedeksen, Hasorin, Gileadin, Galilean ja kaiken Naphtalin maan, ja vei heidät Assyriaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Ja Hosea Elan poika nosti kapinan Pekaa Remaljan poikaa vastaan ja löi hänen kuoliaaksi, ja tuli kuninkaaksi hänen siaansa kahdentenakymmenentenä Jotamin Ussian pojan vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Mitä enempi Pekasta sanomista on, ja kaikista mitä hän tehnyt on: katso, se on kirjoitettu Israelin kuningasten aikakirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Toisena Pekan Remaljan pojan Israelin kuninkaan vuonna tuli Jotam, Ussian Juudan kuninkaan poika, kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Ja viiden ajastaikainen kolmattakymmentä oli hän tullessansa kuninkaaksi, ja hallitsi kuusitoistakymmentä ajastaikaa Jerusalemissa; hänen äitinsä nimi oli Jerusa Zadokin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Ja hän teki mitä Herralle hyvästi kelpasi, kaiken sen jälkeen, kuin hänen isänsä Ussia tehnyt oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Paitsi ettei he luopuneet korkeuksista; sillä kansa uhrasi ja suitsutti vielä korkeuksilla; hän rakensi Herran huoneen ylimmäisen portin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Mitä enempi Jotamista sanomista on, ja kaikista mitä hän tehnyt on: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Silloin rupesi Herra lähettämään Juudalle Retsinin Syyrian kuninkaan ja Pekan Remaljan pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Ja Jotam nukkui isäinsä kanssa ja haudattiin isäinsä tykö, isänsä Davidin kaupunkiin; ja Ahas hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Pekan Remaljan pojan seitsemäntenä vuonna toistakymmentä tuli Ahas, Jotamin Juudan kuninkaan poika, kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Kahdenkymmenen ajastaikainen oli Ahas tullessansa kuninkaaksi, ja hallitsi kuusitoistakymmentä ajastaikaa Jerusalemissa; ja ei tehnyt sitä, mikä oli kelvollinen Herralle hänen Jumalallensa, niinkuin David hänen isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Sillä hän vaelsi Israelin kuningasten tiellä, ja hän käytti poikansa tulen lävitse pakanain kauhistuksen jälkeen, jotka Herra Israelin lasten edestä oli ajanut ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Hän uhrasi ja suitsutti korkeuksilla ja kukkuloilla, ja kaikkein viheriäisten puiden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Silloin matkusti Retsin Syrian kuningas ja Peka Remaljan poika Israelin kuningas Jerusalemiin sotimaan; ja he piirittivät Ahaksen, ja ei kuitenkaan voittaneet häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Silloin myös Retsin Syrian kuningas sai Syrialaisille Elatin jälleen ja ajoi Juudalaiset Elatista ulos; mutta Syrialaiset tulivat Elatiin ja asuivat siinä tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Mutta Ahas lähetti sanansaattajat Tiglat Pilesserin Assyrian kuninkaan tykö ja käski hänelle sanoa: minä olen sinun palvelias ja poikas: matkusta tänne ja vapahda minua Syrian kuninkaan kädestä ja Israelin kuninkaan kädestä, jotka ovat nousseet minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Ja Ahas otti kultaa ja hopiaa, mitä hän löysi Herran huoneesta ja kuninkaan huoneen tavaroista, ja lähetti Assyrian kuninkaalle lahjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Assyrian kuningas kuuli häntä ja meni ylös Damaskuun, ja voitti sen ja vei heidät Kiriin; ja hän löi Retsinin kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Ja kuningas Ahas matkusti Tiglat Pilesseriä Assyrian kuningasta vastaan Damaskuun; ja kuin hän näki alttarin Damaskussa, lähetti kuningas Ahas alttarin kuvan ja muodon papille Urialle, juuri niinkuin se tehty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Niin rakensi pappi Uria alttarin ja teki kaiken sen jälkeen, minkä Ahas kuningas hänelle oli lähettänyt Damaskusta: ja näin teki Uria pappi siihenasti kuin Ahas kuningas tuli Damaskusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Ja kuin kuningas tuli ja näki alttarin, astui hän alttarin tykö ja uhrasi sen päällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'Ja sytytti sen päällä polttouhrinsa ja ruokauhrinsa, ja kaasi sen päälle juomauhrinsa; ja kiitosuhrinsa veren, jonka hän uhrasi, antoi hän pirskottaa alttarille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Mutta vaskialttarin, joka Herran edessä seisoi, siirsi hän pois huoneen edestä, niin ettei se seisonut alttarin ja Herran huoneen välillä; vaan pani sen alttarin sivulle pohjan puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Ja kuningas Ahas käski Urialle papille, sanoen: suuremmalla alttarilla pitää sinun uhraaman polttouhrin huomeneltain ja ruokauhrin ehtoona, ja kuninkaan polttouhrin ja hänen ruokauhrinsa, ja kaiken maan kansan polttouhrin, heidän ruokauhrinsa ja juomauhrinsa ja kaiken polttouhrin veren, ja kaikkein muiden uhrien veren pitää sinun priiskottaman sen päälle: vaan vaskialttarista tahdon minä vielä ajatella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Uria pappi teki kaikki niinkuin Ahas kuningas hänelle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Ja kuningas Ahas särki istuimen sivut, ja siirsi kattilan niiden päältä, ja hän otti meren pois vaskihärjistä, jotka sen alla olivat, ja pani sen kivipermannolle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Sitälikin sabbatin peitteen, jonka he huoneesen rakentaneet olivat. Ja kuninkaan huoneen ulkonaisen sisällekäytävän käänsi hän Herran huoneen ympäri Assyrian kuninkaan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Mitä enempi Ahaksesta sanomista on, ja mitä hän tehnyt on: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Ja Ahas nukkui isäinsä kanssa ja haudattiin isäinsä tykö Davidin kaupunkiin; ja Hiskia hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Ahaksen Juudan kuninkaan toisena vuonna toistakymmentä hallitsi Hosea Elan poika Israelin ylitse Samariassa yhdeksän ajastaikaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Ja teki pahaa Herran edessä, mutta ei kuitenkaan niinkuin ne Israelin kuninkaat, jotka hänen edellänsä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Häntä vastaan soti Salmanassar Assyrian kuningas; ja Hosea tuli hänelle alamaiseksi, niin että hän antoi hänelle lahjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Mutta kuin Assyrian kuningas sai tietää Hosean tehneen liiton ja lähettäneen sanansaattajat Soon, Egyptin kuninkaan tykö, ja ettei hän lähettänyt Assyrian kuninkaalle lahjoja vuosi vuodelta; niin piiritti Assyrian kuningas hänen, ja pani hänen vankihuoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Ja Assyrian kuningas meni kaikkeen siihen maakuntaan ylös, ja tuli Samariaan, ja piiritti sen kolmeksi ajastajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Mutta yhdeksännellä Hosean ajastajalla voitti Assyrian kuningas Samarian, ja vei Israelin Assyriaan, ja pani heidät Halaan ja Haboriin, Gosan virran tykö, ja Mediläisten kaupunkeihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Ja tapahtui, kuin Israelin lapset syntiä tekivät Herraa Jumalaansa vastaan, joka heidät Egyptin maalta johdattanut oli, Pharaon Egyptin kuninkaan käsistä; ja he pelkäsivät vieraita jumalia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Ja vaelsivat pakanain tapain jälkeen, jotka Herra oli ajanut Israelin lasten edestä ulos; ja niinkuin myös Israelin kuninkaat tekivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Ja Israelin lapset peittelivät asiansa Herraa Jumalaansa vastaan, jotka ei hyvät olleet, ja rakensivat itsellensä korkeuksia, kaikissa kaupungeissansa, sekä linnoissa että vahvoissa kaupungeissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'Ja nostivat patsaita ja metsistöitä kaikilla korkeilla vuorilla, ja kaikkein viheriäisten puiden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Ja he suitsuttivat kaikissa korkeuksissa niinkuin pakanat, jotka Herra heidän edestänsä oli ajanut pois, ja tekivät myös hirmuisia töitä, joilla he vihoittivat Herran,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'Ja palvelivat epäjumalia, joista Herra heille oli sanonut: senkaltaisia ei teidän pidä tekemän!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Ja kuin Herra todisti Israelia ja Juudaa vastaan, kaikkein prophetain ja näkiäin kautta, ja antoi heille sanoa: palatkaat teidän vääriltä teiltänne, ja pitäkäät minun käskyni, ja säätyni, kaiken sen lain jälkeen, jonka minä teidän isillenne käskenyt olen, ja minä myös palveliaini prophetain kautta teille lähettänyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Ja ei he totelleet; mutta olivat niskurit, niinkuin heidän esi-isänsäkin, jotka ei uskoneet Herran Jumalansa päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'Ja he katsoivat ylön hänen käskynsä ja hänen liittonsa, jonka hän heidän isäinsä kanssa tehnyt oli, ja heidän todistuksensa, jonka hän heidän seassansa todisti, ja vaelsivat turhissa menoissansa, ja tekivät turhia, kuin pakanatkin heidän ympärillänsä, joista Herra oli kieltänyt, ettei heidän pitäis tekemän niinkuin ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'Mutta he pelkäsivät kaikki Herran Jumalansa käskyt, ja tekivät heillensä kaksi valettua vasikkaa, ja tekivät metsistön, ja kumarsivat koko taivaallista sotajoukkoa, ja palvelivat Baalia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Ja käyttivät poikansa ja tyttärensä tulen lävitse, ja pitivät noituuksia ja velhouksia, ja myivät itsensä tekemään sitä, mikä paha oli Herran edessä, häntä vihoittaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Niin vihastui Herra suuresti Israelin päälle, ja heitti heidät pois kasvoinsa edestä, niin ettei yhtään heistä jäänyt, vaan Juudan sukukunta yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Ei myös Juuda pitänyt Herran Jumalansa käskyjä, vaan he vaelsivat Israelin säädyissä, joita he tekivät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Sentähden hylkäsi Herra kaiken Israelin siemenen, vaivasi heitä ja antoi ryövärein käsiin, siihenasti että hän heidät kasvoinsa edestä heitti pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Sillä Israel eroitti itsensä Davidin huoneesta, ja tekivät itsellensä Jerobeamin Nebatin pojan kuninkaaksi. Hän käänsi Israelin Herrasta pois, ja saatti heidät suuresti syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Ja niin vaelsivat Israelin lapset kaikissa Jerobeamin synneissä, joita hän tehnyt oli, ja ei lakanneet siitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Siihenasti että Herra heitti Israelin kasvoinsa edestä pois, niinkuin hän ennen sanonut oli kaikkein palveliainsa prophetain kautta. Ja Israel vietiin pois omalta maaltansa Assyriaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Ja Assyrian kuningas antoi tulla (kansaa) Babelista ja Kutasta, ja Avvasta, ja Hematista, ja Sepharvaimista, ja asetti heidät Samarian kaupunkeihin Israelin lasten siaan, jotka omistivat Samarian, ja asuivat niissä kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Mutta kuin he niissä ensin rupesivat asumaan, ja ei peljänneet Herraa, lähetti Herra jalopeurat heidän sekaansa, jotka heidät surmasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Ja he puhuivat Assyrian kuninkaalle, sanoen: pakanat, jotka sinä tänne annoit tulla ja panit Samarian kaupunkeihin asumaan, ei tiedä mitään maakunnan Jumalan säädyistä: sentähden lähetti hän jalopeurat heidän sekaansa, ja katso, ne surmaavat heidät, sentähden ettei he mitään tiedä maakunnan Jumalan säädyistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Mutta Assyrian kuningas käski ja sanoi: viekäät sinne yksi papeista, jotka te sieltä vieneet olette pois; ja he menkäät sinne, ja asukaat siellä: että hän opettais heille maan Jumalan tavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Niin tuli yksi papeista, joka viety oli Samariasta pois, ja asui Betelissä; ja hän opetti heitä, kuinka heidän piti pelkäämän Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Mutta jokainen kansa teki itsellensä erinomaiset jumalat, ja panivat ne korkeusten huoneisiin, jotka Samarialaiset tehneet olivat: jokainen kansasta omassa kaupungissansa, jossa he asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Mutta Babelin miehet tekivät SukkotBenotin; Kutan miehet tekivät Nergalin; Hematin miehet tekivät Asiman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Ja Avvilaiset tekivät Nibhan ja Tartakin; Sepharvaimilaiset polttivat poikansa Adramelekille ja Anamelekille Sepharvaimin epäjumalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Mutta he pelkäsivät Herraa, ja tekivät itsellensä pappeja korkeuksille alhaisimman kansan seasta seassansa, jotka uhrasivat heidän korkeuttensa huoneissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'He pelkäsivät Herraa ja palvelivat myös epäjumaliansa pakanain tavan jälkeen, kusta he tulleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Ja hamaan tähän päivään asti tekivät he tätä vanhan tavan jälkeen, niin ettei he pelkää Herraa, eikä myös pidä tapaansa ja oikeuttansa, lain ja käskyn jälkeen, jonka Herra käski Jakobin lapsille, jolle hän antoi Israelin nimen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Ja Herra oli tehnyt heidän kanssansa liiton, ja käskenyt heitä, sanoen: älkäät peljätkö muita jumalia ja älkäät heitä kumartako, älkäät heitä palvelko ja älkäät heille uhratko;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Mutta Herraa, joka teidät Egyptin maalta toi ulos, suurella voimalla ja ojennetulla käsivarrella, häntä peljätkäät, häntä rukoilkaat, ja hänelle uhratkaat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Ja pitäkäät ne tavat, oikeudet, laki ja käskyt, jotka hän teille kirjoittanut on, että te kaikkena elinaikananne teette sen jälkeen: ja älkäät peljätkö muita jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Ja älkäät unhottako sitä liittoa, jonka minä tein teidän kanssanne: ettette pelkäisi muita jumalia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Mutta peljätkäät Herraa teidän Jumalaanne: ja hän auttaa teitä kaikkein teidän vihamiestenne käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Mutta ei he totelleet sitä, vaan tekivät vanhan tapansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Ja näin nämät pakanat pelkäsivät Herraa, ja palvelivat myös epäjumaliansa; niin myös tekivät heidän lapsensa ja lastensa lapset, kuin heidän isänsäkin tehneet olivat, hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Ja tapahtui kolmantena Hosean Elan pojan Israelin kuninkaan ajastaikana, että Hiskia Ahaksen Juudan kuninkaan poika tuli kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Hän oli viidenkolmattakymmenen ajastaikainen tullessansa kuninkaaksi, ja hallitsi yhdeksän ajastaikaa kolmattakymmentä Jerusalemissa; hänen äitinsä nimi oli Abi, Sakarian tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Ja hän teki sitä mikä otollinen oli Herran edessä, juuri niinkuin hänen isänsä David teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Hän kukisti korkeudet, ja särki patsaat, ja hävitti metsistöt, ja löi vaskikäärmeen rikki, jonka Moses tehnyt oli, sillä Israelin lapset suitsuttivat sille aina siihen päivään asti; ja hän kutsui sen Nehustan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Hän turvasi Herraan Israelin Jumalaan; niin ettei yksikään hänen kaltaisensa ollut hänen jälkeensä, ei myös hänen edellänsä kaikkein Juudan kuningasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Hän riippui Herrassa ja ei luopunut hänestä, ja piti hänen käskynsä niinkuin Herra Mosekselle oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Ja Herra oli hänen kanssansa, ja kuhunkapäin hän meni, toimitti hän taitavasti; hän luopui myös Assyrian kuninkaasta, ja ei palvellut häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Hän löi Philistealaiset Gasaan asti, ja heidän rajansa, vartiain tornista vahvoihin kaupunkeihin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Ja tapahtui neljäntenä Hiskian kuninkaan vuonna, (se oli seitsemäs Hosean Elan pojan Israelin kuninkaan vuosi) että Salmanassar Assyrian kuningas meni Samariaa vastaan ja piiritti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Ja voitti kolmen vuoden perästä, kuudentena Hiskian vuonna, se on yhdeksäs Hosean Israelin kuninkaan vuosi: silloin voitettiin Samaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Ja Assyrian kuningas vei Israelin Assyriaan, ja pani heitä Halaan ja Haboriin, Gosarin virran tykö, Mediläisten kaupunkeihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Ettei he olleet kuuliaiset Herran Jumalansa äänelle, ja rikkoivat hänen liittonsa ja kaikki, mitä Moses Herran palvelia käskenyt oli: sitä ei he totelleet eikä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Mutta neljäntenätoistakymmenentenä Hiskian kuninkaan vuonna, meni Sanherib Assyrian kuningas kaikkia Juudan vahvoja kaupungeita vastaan ja voitti ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Niin lähetti Hiskia Juudan kuningas Lakikseen Assyrian kuninkaan tykö ja antoi hänelle sanoa: minä olen rikkonut, mene minun tyköäni pois, mitäs panet minun päälleni, sen minä kannan. Niin pani Assyrian kuningas Hiskian Juudan kuninkaan päälle kolmesataa leiviskää hopiaa ja kolmekymmentä leiviskää kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Niin antoi Hiskia kaiken sen hopian, mikä Herran huoneessa löyttiin ja kuninkaan huoneen tavaroissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Silloin särki Hiskia Herran templin ovet ja kiskot, jotka Hiskia Juudan kuningas oli antanut silata, ja antoi ne Assyrian kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Ja Assyrian kuningas lähetti Tartanin, ja ylimmäisen kamaripalvelian, ja Rabsaken Lakiksesta kuningas Hiskian tykö, suuren väen kanssa Jerusalemiin; ja he nousivat ja menivät Jerusalemiin. Ja noustuansa ja tultuansa sinne, seisahtivat he ylimmäisen vesilammikon kanavan vieressä, tiellä Vanuttajakedolle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Ja kutsuivat kuninkaan; niin meni Eliakim Hilkian poika huoneenhaltia heidän tykönsä ulos, ja Sebna kirjoittaja, ja Joa Asaphin poika kansleri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Niin sanoi Rabsake heille: sanokaat nyt Hiskialle: näin sanoo suuri kuningas, Assyrian kuningas: mikä on tämä turva, johon sinä luotat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Ajatteletkos (vaikka ne ovat tyhjät puheet) neuvoa ja voimaa olevan sotiakses? mihinkä sinä luotat, ettäs olet minusta luopunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Katso, sinä uskallat tuon särjetyn ruokosauvan päälle Egyptistä! joka, jos joku nojaa sen päälle, menee sisälle hänen käteensä ja pistää sen lävitse: niin on Pharao Egyptin kuningas kaikille, jotka luottavat hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Mutta jos te sanoisitte minulle: me uskallamme Herran Jumalamme päälle: eikö hän ole se, jonka korkeudet ja alttarit Hiskia on kukistanut? ja sanoi Juudalle ja Jerusalemille: tämän alttarin edessä, joka on Jerusalemissa, pitää teidän kumartaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Lyö siis nyt veto herrani Assyrian kuninkaan kanssa: minä annan sinulle kaksituhatta hevosta, jos sinä taidat antaa niitä, jotka niillä ratsastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kuinka siis sinä taidat ajaa takaperin yhden päämiehen herrani vähimmistä palvelioista? Mutta sinä luotat Egyptin päälle, vaunuin ja ratsasmiesten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Eli luuletkos, että minä ilman Herraa tähän paikkaan tullut olen, hävittämään tätä? Herra on minulle sanonut: mene tätä maata vastaan ja hukuta se.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Niin sanoi Eliakim Hilkian poika, ja Sebna ja Joa Rabsakelle: puhu palveliais kanssa Syrian kielellä, sillä me ymmärrämme sen, ja älä puhu meidän kanssamme Juudan kielellä, kansan kuullen, jotka muurin päällä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Mutta Rabsake sanoi heille: onko herrani lähettänyt minun sinun herras tykö eli sinun tykös, näitä sanoja puhumaan? eikö enemmin niiden miesten tykö, jotka muurin päällä istuvat, että heidän pitää syömän omaa lokaansa ja juoman omaa vettänsä teidän kanssanne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Niin seisoi Rabsake ja huusi korkealla äänellä Juudan kielellä, puhui ja sanoi: kuulkaat suuren kuninkaan, Assyrian kuninkaan ääntä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Näin sanoo kuningas: älkää antako Hiskian pettää teitänne; sillä ei hän voi vapahtaa teitä hänen käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Ja älkään antako Hiskia teidän turvata Herran päälle, sanoen: Herra on totisesti pelastava meitä, ja ei tämä kaupunki anneta Assyrian kuninkaan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Älkäät kuulko Hiskiaa; sillä näin sanoo Assyrian kuningas: sopikaat minun kanssani, ja tulkaat minun tyköni, niin joka mies on syövä viinapuustansa ja fikunapuustansa, ja juova kaivostansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Siihen asti minä tulen ja vien teitä siihen maahan, joka teidän maanne kaltainen on, jossa jyviä, viinaa, leipää, viinamäkiä, öljypuita, öljyä ja hunajaa on, niin te elätte ja ette kuole. Älkäät kuulko Hiskiaa, sillä hän pettää teitä, kuin hän sanoo: Herra pelastaa meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Ovatko myös pakanain jumalat pelastaneet kukin maansa Assyrian kuninkaan käsistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kussa ovat Hematin ja Arpadin jumalat? kussa ovat Sepharvaimin, Henan ja Ivvan jumalat? ovatko he Samarian pelastaneet minun käsistäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kussa on joku kaikkein niiden maakuntain jumalain seassa, joka maansa on pelastanut minun kädestäni, että Herra nyt pelastaisi Jerusalemin minun kädestäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Ja kansa vaikeni ja ei häntä mitäkään vastannut: sillä kuningas oli käskenyt ja sanonut: älkäät häntä vastatko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Niin tuli Eliakim Hilkian poika huoneenhaltia, ja Sebna kirjoittaja, ja Joa Asaphin poika kansleri Hiskian tykö reväistyillä vaatteilla, ja ilmoittivat hänelle Rabsaken sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Kuin kuningas Hiskia sen kuuli, repäisi hän vaatteensa ja puki säkin yllensä ja meni Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Ja hän lähetti Eliakimin huoneenhaltian ja Sebnan kirjoittajan vanhimpain pappien kanssa, puetettuina säkeillä, prophetan Jesaian Amotsin pojan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Ja he sanoivat hänelle: näin sanoo Hiskia: tämä on vaivan, toran ja häväistyksen päivä; sillä lapset ovat tulleet synnyttämiselle, mutta ei ole voimaa synnyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Jospa Herra sinun Jumalas kuulis kaikki Rabsaken sanat, jonka hänen herransa Assyrian kuningas on lähettänyt tänne pilkkaamaan elävää Jumalaa, että hän nuhtelis häntä niiden sanain tähden, jotka Herra sinun Jumalas kuullut on: niin korota sinun rukoukses niiden edestä, jotka vielä jääneet ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Kuin kuningas Hiskian palveliat tulivat Jesaian tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Sanoi Jesaia heille: näin sanokaat teidän herrallenne: näin sanoo Herra: älä mitään peljästy niiden sanain tähden, jotka sinä kuullut olet, joilla Assyrian kuninkaan palveliat minua häväisseet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Katso, minä annan hänelle hengen, että hän saa kuulla sanoman, ja palajaa omalle maallensa; ja minä annan hänen kaatua miekalla omassa maakunnassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Ja kuin Rabsake palasi, löysi hän Assyrian kuninkaan sotimasta Libnaa vastaan; sillä hän oli kuullut hänen menneeksi Lakiksesta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Ja kuin hän sai kuulla Tirhakasta Ethiopian kuninkaasta sanottavan: katso, hän on mennyt sotimaan sinua vastaan; niin hän palasi, ja lähetti sanan Hiskialle ja antoi hänelle sanoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Puhukaat näin Hiskialle Juudan kuninkaalle, sanoen: älä anna Jumalas, jonka päälle sinä luotat, vietellä sinuas ja sanot: ei Jerusalem anneta Assyrian kuninkaan käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Katso, sinä olet kuullut, mitä Assyrian kuninkaat tehneet ovat kaikille maakunnille, ja hukuttaneet heitä: ja sinä pelastettaisiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Ovatko myös pakanain jumalat pelastaneet heidät, jotka minun isäni hukuttaneet ovat, Gosanin, Haranin, niin myös Resephin ja Edenin lapset, jotka Telassarissa olivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kussa on Hematin kuningas, Arpadin kuningas, Sepharvaimin, Henan ja Ivvan kaupungin kuningas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Kuin Hiskia oli ottanut kirjan sanansaattajilta ja lukenut sen, meni hän Herran huoneesen, ja Hiskia levitti sen Herran eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Ja rukoili Herran edessä ja sanoi: Herra Israelin Jumala, joka istut Kerubimin päällä, sinä olet ainoa Jumala kaikissa maan valtakunnissa, sinä olet tehnyt taivaan ja maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Herra, kallista korvas ja kuule, avaa Herra silmäs ja näe, ja kuule Sanheribin sanat, joka tänne on lähettänyt pilkkaamaan elävää Jumalaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Se on tosi, Herra, että Assyrian kuninkaat ovat hävittäneet pakanat ja heidän maakuntansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Ja ovat heittäneet heidän jumalansa tuleen; sillä ei ne olleet jumalia, mutta ihmisten kätten teot, puut ja kivet, sentähden ovat he ne hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Mutta nyt sinä, Herra meidän Jumalamme, auta meitä hänen kädestänsä: että kaikki maan valtakunnat tietäisivät sinun, Herra, olevan ainoan Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Niin lähetti Jesaia Amotsin poika Hiskian tykö ja antoi hänelle sanoa: näin sanoo Herra Israelin Jumala: minä olen kuullut, mitäs minulta rukoillut olet Sanheribin Assyrian kuninkaan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Nämät ovat ne, mitkä Herra häntä vastaan puhunut on: neitsy Zionin tytär katsoo sinun ylön ja pilkkaa sinua, Jerusalemin tytär vääntelee päätänsä sinun jälkees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Ketäs olet pilkannut ja häväissyt? ketä vastaan sinä olet korottanut äänes? Sinä olet nostanut silmäs pyhää vastaan Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Sinä olet sanansaattajais kautta häväissyt Herraa ja sanonut: minä olen noussut vuoren kukkuloille vaunuini paljoudella, Libanonin sivulle: minä tahdon hakata maahan hänen korkiat sedripuunsa ja valitut honkansa, ja mennä hänen viimeiseen majaansa, hänen ihanan vainionsa metsään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Minä olen kaivanut ja juonut muukalaiset vedet, ja olen kuivannut kaikki piiritetyt ojat minun jalkapöydälläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Etkös ole kaukaa kuullut minun näitä tehneeksi, ja jo aikaa ennen näitä valmistaneeksi? Nyt olen minä sen antanut tapahtua, että vahvat kaupungit pitäis kukistettaman hävinneeksi kiviroukkioksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Ja ne, jotka siinä asuvat, pitäis tuleman heikoksi, peljästymän, häpeemän ja tuleman niinkuin ruoho kedolla, ja niinkuin viheriäinen ruohon korsi katon päällä, ja niinkuin kuivettu oras ennen kuin se oljeksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Minä tiedän sinun asumasias, sinun ulos- ja sisällekäymises, ja ettäs kiukuitset minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Ettäs kiukuitset minua vastaan ja sinun ylpeytes on tullut minun korvilleni, panen minä renkaani sinun sieraimiis ja suitseni suuhus, ja johdatan sinun sitä tietä myöten takaperin, jotas tulitkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Ja tämä pitää oleman sinulle merkiksi: syö tällä ajastajalla sitä, mikä kasvanut on, toisella ajastajalla sitä, mikä itsestänsä kasvaa; mutta kolmannella ajastajalla kylväkäät ja leikatkaat, ja istuttakaat viinamäkiä, syökäät heidän hedelmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Ja joka Juudan huoneesta päässyt ja jäänyt on, pitää vielä nyt alta juurtuman ja ylhäältä hedelmöitsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Sillä jääneet pitää käymän Jerusalemista ulos, ja Zionin vuorelta ne, jotka päässeet ovat. Herran Zebaotin kiivaus tekee näitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Sentähden sanoo Herra Assyrian kuninkaasta näin: ei hänen pidä tuleman tähän kaupunkiin, eikä yhtään nuolta sinne ampuman, ei myös yhtään kilpeä tuoman sen eteen, ja ei yhtään vallia rakentaman sen ympärille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Mutta hänen pitää sitä tietä palajaman, jota hän tullut on, ja ei pidä hänen tähän kaupunkiin tuleman, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Ja minä varjelen tämän kaupungin ja pelastan sen minun tähteni ja Davidin minun palveliani tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Niin tapahtui sinä yönä, että Herran enkeli meni ja tappoi Assyrian leirissä sata kahdeksankymmentä ja viisituhatta miestä. Ja kuin he silloin varhain huomeneltain nousivat, katso, ne kaikki olivat kuolleitten ruumiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Ja Sanherib Assyrian kuningas meni matkaansa, palasi ja oli Ninivessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Ja kuin hän rukoili Nisrokin jumalansa huoneessa, niin hänen poikansa Adramelek ja Saretser tappoivat hänen miekalla ja pakenivat Araratin maakuntaan: ja hänen poikansa Assarhaddon tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Silloin sairasti Hiskia kuolemallansa, ja propheta Jesaia Amotsin poika tuli hänen tykönsä ja sanoi hänelle: näin sanoo Herra: toimita talos, sillä sinun pitää nyt kuoleman ja ei elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Mutta hän käänsi kasvonsa seinän puoleen, rukoili Herraa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Oi, Herra! muista että minä olen uskollisesti ja vaalla sydämellä vaeltanut sinun edessäs ja tehnyt, mikä sinulle otollinen ollut on! Ja Hiskia itki hartaasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Mutta kuin Jesaia ei ollut vielä puoli kaupunkiin käynyt ulos, tuli Herran sana hänen tykönsä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Palaja ja sano Hiskialle, kansani päämiehelle: näin sanoo Herra sinun isäs Davidin Jumala: minä olen kuullut sinun rukoukses ja nähnyt sinun kyyneles: katso, minä parannan sinun: kolmantena päivänä pitää sinun menemän ylös Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Ja minä lisään sinun ikääs viisitoistakymmentä ajastaikaa, ja vapahdan sinun ja tämän kaupungin Assyrian kuninkaan kädestä, ja varjelen tämän kaupungin minun tähteni ja minun palveliani Davidin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Ja Jesaia sanoi: tuokaat minulle fikunarypäle. Ja he toivat ja panivat paisuman päälle, ja hän tuli terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Hiskia sanoi Jesaialle: mikä merkki siihen on, että Herra minun parantaa, ja että minun pitää menemän kolmantena päivänä Herran huoneesen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Jesaia sanoi: sinä saat tämän merkin Herralta, että Herra tekee mitä hän sanonut on. Pitääkö varjon käymän kymmenen piirtoa edeskäsin, taikka kymmenen piirtoa takaperin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Ja Hiskia sanoi: se on keviä, että varjo käy edeskäsin kymmenen piirtoa: ei, mutta että hän kävis kymmenen piirtoa takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Niin rukoili Jesaia Herraa, ja hän veti varjon kymmenen piirtoa takaperin, jotka hän oli käynyt edeskäsin Ahaksen säjärissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Silloin lähetti Berodak Baladan Baladanin poika Babelin kuningas kirjoituksen ja lahjoja Hiskialle; sillä hän oli kuullut Hiskian sairastuneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ja Hiskia kuuli heitä, ja osoitti heille koko tavarahuoneensa, hopian, kullan, kalliit yrtit, ja parhaan öljyn, ja koko asehuoneensa ja kaikki, mitä hänen tavaroissansa oli. Ja ei mitään ollut hänen huoneessansa ja kaikessa hänen vallassansa, jota ei Hiskia heille osoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Niin tuli propheta Jesaia kuningas Hiskian tykö ja sanoi hänelle: mitä nämät miehet ovat sanoneet, ja kusta he ovat tulleet sinun tykös? Hiskia sanoi: he ovat tulleet kaukaiselta maalta, Babelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Hän sanoi: mitä he ovat nähneet sinun huoneessas? Hiskia sanoi: he ovat nähneet kaikki, mitä minun huoneessani on, ja ei ole mitään minun tavaroissani, jota en minä heille osoittanut ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Niin sanoi Jesaia Hiskialle: kuule Herran sanaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Katso, aika tulee, että kaikki sinun huoneestas ja kaikki, mitä sinun esi-isäs koonneet ovat tähän päivään asti, viedään pois Babeliin, ja ei jätetä mitään, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Ja myös lapset, jotka sinusta tulevat, jotkas siität, otetaan kamaripalvelioiksi Babelin kuninkaan huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Hiskia sanoi Jesaialle: Herran sana on hyvä, jonkas puhunut olet; ja sanoi vielä: eikö se niin ole? kuitenkin että rauha ja uskollisuus minun aikanani olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Mitä enempi sanomista on Hiskiasta, ja hänen voimastansa, ja mitä hän tehnyt on, ja vesilammikosta ja kanavista, joilla hän vedet johdatti kaupunkiin: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Ja Hiskia nukkui isäinsä kanssa; ja Manasse hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse oli kahdentoistakymmenen ajastaikainen tullessansa kuninkaaksi, ja hallitsi viisi ajastaikaa kuudettakymmentä Jerusalemissa; hänen äitinsä nimi oli Hephtsiba.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Ja hän teki pahaa Herran edessä, pakanain kauhistusten jälkeen, jotka Herra Israelin lasten edestä oli ajanut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Hän rakensi korkeudet jälleen, jotka hänen isänsä Hiskia kukistanut oli, ja nosti Baalin alttarin, ja teki metsistön, niinkuin Ahab Israelin kuningas tehnyt oli, ja kumarsi koko taivaan sotajoukkoa, ja palveli niitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Ja rakensi myös alttarit Herran huoneesen, josta Herra sanonut oli: minä asetan minun nimeni Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Ja hän rakensi koko taivaalliselle sotajoukolle alttarit molempiin pihoihin Herran huoneesen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Ja käytti poikansa tulessa, ja otti vaarin lintuin lauluista ja merkeistä, ja piti noitia ja merkkein sanojia, ja teki paljon pahaa Herran edessä, jolla hän hänen vihoitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Hän pani myös metsistöjumalan, jonka hän tehnyt oli, huoneesen, josta Herra Davidille ja hänen pojallensa Salomolle sanonut oli: tähän huoneesen ja Jerusalemiin, jonka minä valinnut olen kaikista Israelin sukukunnista, panen minä nimeni ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Ja en liikuta enää Israelin jalkoja siitä maasta, jonka minä heidän isillensä antanut olen, jos he ainoastaan pitävät ja tekevät kaikki, mitä minä heille käskenyt olen, ja kaiken sen lain, minkä minun palveliani Moses heille käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mutta ei he totelleet sitä, vaan Manasse vietteli heitä, niin että he tekivät pahemmin kuin pakanat, jotka Herra Israelin lasten edestä hävittänyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Silloin puhui Herra palveliainsa prophetain kautta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Että Manasse Juudan kuningas on nämät kauhistukset tehnyt, jotka pahemmat ovat kuin kaikki ne kauhistukset, joita Amorilaiset tehneet ovat, jotka hänen edellänsä olivat, ja on myös saattanut Juudan syntiä tekemään epäjumalillansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Sentähden sanoo Herra Israelin Jumala näin: katso, minä saatan vahingon Juudan ja Jerusalemin päälle, että kuka ikänä sen kuulee, pitää hänen molemmat korvansa soiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Ja minä vedän Samarian mittanuoran Jerusalemin ylitse, ja Ahabin huoneen painomitan, ja virutan Jerusalemin niinkuin astiat virutetaan: ne virutetaan ja käännetään kumollensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Ja minä hylkään jääneet minun perimisestäni ja annan heidät vihamiestensä käsiin, että heidän pitää oleman kaikille vihollisillensa saaliiksi ja ryöstöksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Että he tekivät sitä, mikä paha oli minun silmäini edessä, ja ovat minun vihoittaneet siitä päivästä, jona heidän isänsä läksivät Egyptistä, tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Ja Manasse vuodatti myös paljon viatointa verta, siihen asti että Jerusalem sieltä ja täältä täynnä oli, ilman niitä syntejä, joilla hän Juudan saatti syntiä tekemään, että he tekivät pahaa Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Mitä enempi Manassesta sanomista on ja kaikista, mitä hän tehnyt on, ja niistä synneistä, jotka hän teki: eikö ne ole kirjoitetut Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Ja Manasse nukkui isäinsä kanssa ja haudattiin huoneensa yrttitarhaan, joka oli Ussan yrttitarha; ja hänen poikansa Amon tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Kahden ajastaikainen kolmattakymmentä oli Amon tullessansa Juudan kuninkaaksi, ja hallitsi kaksi ajastakaa Jerusalemissa; hänen äitinsä nimi oli Mesulemet Hatsurin tytär Jotbasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Ja hän teki sitä, mikä Herralle ei kelvannut, niinkuin hänen isänsä Manasse tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Ja hän vaelsi kaikkia niitä teitä, joita hänen isänsä vaeltanut oli, ja palveli epäjumalia, joita hänen isänsä palvellut oli, ja kumarsi niitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Ja luopui Herrasta isäinsä Jumalasta, ja ei vaeltanut Herran tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Ja Amonin palveliat tekivät liiton häntä vastaan ja tappoivat kuninkaan omassa huoneessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Mutta maakunnan kansa löi kaikki ne kuoliaaksi, jotka olivat liiton tehneet kuningas Amonia vastaan, ja kansa teki Josian hänen poikansa kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Mitä Amon enempi tehnyt on: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Ja hän haudattiin omaan hautaansa Ussan yrttitarhassa, ja hänen poikansa Josia tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josia oli kahdeksan ajastaikainen tullessansa kuninkaaksi, ja hallitsi yhden ajastajan neljättäkymmentä Jerusalemissa; hänen äitinsä nimi oli Jedida Adajan tytär Botskatista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Ja hän teki sitä, mikä Herran edessä oli kelvollinen, ja vaelsi kaikella isänsä Davidin tiellä, ja ei poikennut oikialle eli vasemmalle puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Mutta kuningas Josian kahdeksantena vuonna toistakymmentä, lähetti kuningas Saphanin Atsalian pojan Mesullamin pojan, kirjoittajansa, Herran huoneesen, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Mene ylimmäisen papin Hilkian tykö, ja anna hänen lukea se raha, mikä Herran huoneesen tuotu on, jonka ovenvartiat kansalta koonneet ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Että ne annettaisiin teettäjille, jotka Herran huoneesen asetetut ovat, ja he antaisivat työväelle, jotka työtä tekevät Herran huoneessa ja parantavat mitä Herran huoneessa rauvennut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Sepille, rakentajille, muuraajille ja niille, jotka hirsiä ja vuoltuja kiviä ostaman pitää, huoneen parannukseksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Vaan ei kuitenkaan yhtään lukua pidä heiltä vaadittaman niistä rahoista, jotka heidän käsiinsä ovat annetut; vaan heidän pitää uskollisesti niitä toimittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Ja ylimmäinen pappi Hilkia sanoi Saphanille kirjoittajalle: minä löysin lakikirjan Herran huoneesta; ja Hilkia antoi kirjan Saphanille, ja hän luki sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Ja Saphan kirjoittaja tuli kuninkaan tykö, ja ilmoitti kuninkaalle asian ja sanoi: sinun palvelias ovat koonneet ne rahat, jotka Herran huoneessa löydetyt ovat, ja ovat ne jakaneet työväelle, jotka asetetut ovat Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Ja Saphan kirjoittaja ilmoitti kuninkaalle ja sanoi: Hilkia pappi antoi minulle kirjan; ja Saphan luki sen kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Kuin kuningas kuuli lakikirjan sanat, repäisi hän vaatteensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Ja kuningas käski pappi Hilkiaa, ja Ahikamia Saphanin poikaa, ja Aboria Mikajan poijaa, ja Saphania kirjoittajaa, ja Asajaa kuninkaan palveliaa, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Menkäät ja kysykäät Herralta minun puolestani, kansan ja koko Juudan puolesta, tämän kirjan sanoista, joka löydetty on; sillä se on suuri Herran viha, joka meidän päällemme syttynyt on, ettei meidän isämme ole kuuliaiset olleet tämän kirjan sanoille, että he olisivat tehneet niitä kaikkia, mitkä siinä meille kirjoitetut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Niin meni pappi Hilkia, Ahikam, Akbor, Saphan ja Asaja naisprophetan Huldan tykö, Sallumin Tikuan pojan emännän, Harhamin pojan, vaatetten vartian (ja hän asui Jerusalemissa toisella puolella); ja he puhuivat hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Mutta hän sanoi heille: näin sanoo Herra Israelin Jumala: sanokaat sille miehelle, joka teidät minun tyköni lähettänyt on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Näin sanoo Herra: katso, minä saatan onnettomuuden tähän siaan ja hänen asuvaisillensa, kaikki lain sanat, jotka Juudan kuningas lukenut on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Että he ovat luopuneet minusta ja suitsuttaneet vieraille jumalille, vihoittain minua kaikilla kättensä töillä, sentähden syttyy minun vihani tätä siaa vastaan, ja ei pidä sammutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Mutta Juudan kuninkaalle, joka teidät lähettänyt on kysymään Herralta, pitää teidän näin sanoman: näin sanoo Herra Israelin Jumala niistä sanoista, joita sinä kuullut olet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Että sinun sydämes on pehminnyt ja olet sinus nöyryyttänyt Herran edessä, koskas kuulit, mitä minä sanoin tätä siaa ja hänen asuvaisiansa vastaan, että heidän pitää tuleman hävitetyksi ja kiroukseksi, ja olet repinyt vaattees, ja olet itkenyt minun edessäni: niin olen minä myös kuullut sen, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Sentähden, katso, kokoon minä sinua isäis tykö, ettäs kootaan rauhassa hautaas, ettei sinun silmäs näkisi kaikkea sitä onnettomuutta, jonka minä tälle sialle saatan. Ja he sanoivat sen kuninkaalle jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Ja kuningas lähetti, ja kaikki vanhimmat Juudasta ja Jerusalemista kokoontuivat hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Ja kuningas meni ylös Herran huoneesen ja kaikki Juudan miehet ja Jerusalemin asuvaiset hänen kanssansa, papit ja prophetat, ja kaikki kansa, pienet ja suuret; ja luettiin heidän korvainsa kuullen kaikki liittokirjan sanat, joka Herran huoneesta löydetty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Ja kuningas seisoi yhden patsaan tykönä, ja teki liiton Herran edessä, että heidän piti vaeltaman Herran jälkeen ja pitämän hänen käskynsä, todistuksensa ja säätynsä, kaikesta sydämestänsä ja kaikesta sielustansa, että heidän piti pitämän nämät liiton sanat, jotka kirjoitetut olivat tässä kirjassa. Ja kaikki kansa mielistyi siihen liittoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Ja kuningas käski Hilkiaa ylimmäistä pappia, ja pappeja toisesta vuorosta, ja ovenvartioita, ottaa Herran temppelistä kaikkinaiset kalut, jotka Baalille, metsistölle ja kaikelle taivaalliselle sotajoukolle tehdyt olivat; ja hän poltti ne ulkona Jerusalemin edessä Kidronin laaksossa, ja niitten tuhka kannettiin sieltä Beteliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Ja hän otti epäjumalain papit pois, jotka Juudan kuninkaat asettaneet olivat suitsuttamaan korkeuksissa Juudan kaupungeissa ja ympäri Jerusalemia, ja ne jotka suitsuttivat Baalille, auringolle ja kuulle ja planeteille, ja kaikelle taivaalliselle sotajoukolle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Ja antoi viedä Astarotin Herran huoneesta, ulos Jerusalemista, Kidronin ojan tykö, ja poltti sen Kidronin ojan tykönä, ja musersi sen tuhaksi, ja heitti sen tuhan kansan lasten hautoihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Ja kukisti huorain huoneet, jotka olivat Herran huoneen tykönä, joissa vaimot kutoivat huoneita metsistölle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Ja hän kokosi kaikki papit Juudan kaupungeista ja saastutti korkeudet, joissa papit suitsuttivat, Gebasta Bersebaan asti. Ja hän kukisti porttein korkeudet, jotka olivat Josuan kaupungin päämiehen portin vajassa, joka oli vasemmalla puolella kaupungin porttia, sisälle mennessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Ei kuitenkaan korkeutten papit uhranneet koskaan Herran alttarilla Jerusalemissa, vaan söivät kaltiaista leipää veljeinsä keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Hän saastutti myös Tophetin, joka on Hinnomin lasten laaksossa, ettei yksikään käyttäisi poikaansa ja tytärtänsä tulessa Molokille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Ja otti pois hevoset, jotka Juudan kuninkaat auringolle asettaneet olivat Herran huoneen sisällekäymiseen, NetanMelekin kamaripalvelian majan tykönä, joka oli esikaupungissa; ja auringon rattaat poltti hän tulessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Niin myös alttarit, jotka kattoin päällä Ahaksen salissa olivat, jotka Juudan kuninkaat tehneet olivat. Ja ne alttarit, jotka Manasse tehnyt oli kahdessa Herran huoneen pihassa, särki kuningas, ja pakeni sieltä, ja heitti heidän tuhkansa Kidronin ojaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Ja ne korkeudet, jotka Jerusalemin edessä olivat, oikialla puolella Maskitin vuorta, jotka Salomo Israelin kuningas rakentanut oli Astarotille Zidonin kauhistukselle, ja Kamokselle Moabin kauhistukselle, ja Milkomille Ammonin lasten kauhistukselle, ne saastutti myös kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Ja särki patsaat, ja hävitti metsistöt, ja täytti heidän siansa ihmisten luilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Niin myös Betelin alttarin, sen korkeuden, minkä Jerobeam Nebatin poika tehnyt oli, joka Israelin saatti syntiä tekemään; hän kukisti sen alttarin ja korkeuden, ja poltti myös metsistön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Ja Josia käänsi itsensä ja näki ne haudat, jotka olivat vuorella, lähetti ja antoi ottaa luut haudoista, ja poltti ne alttarilla ja saastutti sen, Herran sanan jälkeen, jonka Jumalan mies huutanut oli, joka nämät niin ennen puhunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Ja hän sanoi: mikä haudan merkki tämä on, jonka minä näen? Ja kaupungin kansa sanoi hänelle: se on sen Jumalan miehen hauta, joka Juudasta tuli ja huusi näitä, joita sinä tehnyt olet alttarille Betelissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Ja hän sanoi: anna hänen maata, ja älkään yksikään liikuttako hänen luitansa. Näin tulivat hänen luunsa vapahdetuksi sen prophetan luiden kanssa, joka Samariasta tullut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Ja Josia pani myös kaikki korkeutten huoneet Samarian kaupungista pois, jotka Israelin kuninkaat tehneet olivat vihaa kehoittaaksensa, ja teki heidän kanssansa peräti niinkuin hän Betelissä tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Ja hän tappoi kaikki korkeutten papit, jotka siellä olivat alttareilla, ja poltti ihmisten luut niiden päällä, ja palasi Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Ja kuningas käski kaikkea kansaa ja sanoi: pitäkäät Herralle Jumalallenne pääsiäistä, niinkuin kirjoitettu on tämän liiton kirjassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Sillä ei yhtään pääsiäistä ollut niin pidetty kuin tämä, tuomarien ajasta, jotka olivat tuominneet Israelia, ja kaikkein Israelin kuningasten ja Juudan kuningasten aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Mutta kahdeksantenatoistakymmenentenä kuningas Josian vuonna pidettiin tämä pääsiäinen Herralle Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Ja Josia perkasi kaikki noidat, merkkein tulkitsiat, kuvat ja epäjumalat, ja kaikki kauhistukset, jotka nähtiin Juudan maalla ja Jerusalemissa; että hän pitäis lain sanat, jotka kirjassa kirjoitetut olivat, jonka pappi Hilkia löysi Herran huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Hänen vertaisensa ei ollut yksikään kuningas ennen häntä, joka niin kaikesta sydämestänsä, kaikesta sielustansa ja kaikesta voimastansa itsensä käänsi Herran tykö, kaiken Moseksen lain jälkeen; ja hänen jälkeensä ei tullut myöskään hänen kaltaistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Ei kuitenkaan kääntynyt Herra vihansa suuresta julmuudesta, jolla hän Juudan päälle vihoitettu oli, kaikkein kehoitusten tähden, joilla Manasse hänen kehoittanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Ja Herra sanoi: minä heitän myös Juudan pois minun kasvoini edestä, niinkuin minä Israelin heittänyt olen, ja hylkään tämän kaupungin, jonka minä valinnut olen, Jerusalemin, ja sen huoneen, josta minä puhunut olen: minun nimeni on oleva siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Mitä enempi Josiasta sanomista on, ja kaikista mitä hän tehnyt on: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Hänen ajallansa matkusti Pharao Neko, Egyptin kuningas, Assyrian kuningasta vastaan Phratin virran tykö; mutta kuningas Josia meni häntä vastaan, ja se tappoi hänen Megiddossa, sittekuin hän oli nähnyt hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Ja hänen palveliansa veivät hänen kuolleena pois Megiddosta, ja veivät hänen Jerusalemiin ja hautasivat hänen omaan hautaansa. Ja maan kansa otti Joahaksen Josian pojan, voitelivat ja tekivät hänen kuninkaaksi isänsä siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Kolmen ajastajan vanha kolmattakymmentä oli Joahas, kuin hän tuli kuninkaaksi, ja hallitsi kolme kuukautta Jerusalemissa. Hänen äitinsä nimi oli Hamutal, Jeremian tytär Libnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Ja hän teki pahaa Herran edessä, niinkuin hänen esi-isänsä tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Mutta Pharao Neko sitoi hänen kiinni Riblatissa Hamatin maalla, ettei hän hallitsisi Jerusalemissa, ja pani sakkoveron maan päälle, sata leiviskää hopiaa ja leiviskän kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Ja Pharao Neko teki Eliakimin Josian pojan kuninkaaksi, hänen isänsä Josian siaan, ja muutti hänen nimensä Jojakimiksi; mutta Joahaksen hän otti ja vei Egyptiin, siellä hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Ja Jojakim antoi Pharaolle hopian ja kullan; kuitenkin laski hän maan verolliseksi, antamaan hopiaa Pharaon käskyn jälkeen: itsekunkin maakunnan kansan teki hän verolliseksi voimansa perästä hopiaan ja kultaan, Pharao Nekolle antaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Viidenkolmattakymmenen ajastajan vanha oli Jojakim, kuin hän kuninkaaksi tuli, ja hallitsi yksitoistakymmentä ajastaikaa Jerusalemissa: hänen äitinsä nimi oli Zebuda, Pedajan tytär Rumasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Ja hän teki pahaa Herran edessä, niinkuin hänen isänsäkin tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Hänen aikanansa nousi Nebukadnetsar Babelin kuningas; ja Jojakim tuli hänelle alamaiseksi kolmeksi vuodeksi; mutta hän käänsi itsensä ja erkani hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Ja Herra antoi tulla hänen päällensä sotaväen Kaldeasta, Syriasta, Moabista ja Ammonin lapsista, ja antoi ne tulla Juudeaan hukuttamaan häntä, Herran sanan jälkeen, niinkuin hän oli puhunut palveliainsa prophetain kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Mutta se tapahtui Juudalle Herran sanan jälkeen, että hän heitä heittäis pois kasvoinsa edestä Manassen syntein tähden, jotka hän tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'Ja myös viattoman veren tähden, jonka hän vuodatti, ja täytti Jerusalemin viattomalla verellä: sitä ei Herra tahtonut antaa anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Mitä enempi Jojakimista sanomista on, ja kaikista hänen teoistansa: eikö se ole kirjoitettu Juudan kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Ja Jojakim nukkui isäinsä kanssa ja hänen poikansa Jojakin tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Ja Egyptin kuningas ei lähtenyt enään maaltansa; sillä Babelin kuningas oli häneltä ottanut kaikki pois, mitä Egyptin kuninkaan oma oli, Egyptin ojasta Phratin virtaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Kahdeksantoistakymmenen vuotinen oli Jojakin tullessansa kuninkaaksi, ja hallitsi kolme kuukautta Jerusalemissa; hänen äitinsä nimi oli Nehusta Elnatanin tytär Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Ja hän teki pahaa Herran edessä, niinkuin hänen isänsäkin tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Silloin matkustivat Nebukadnetsarin Babelin kuninkaan palveliat ylös Jerusalemiin; ja kaupunki piiritettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Ja Nebukadnetsar, Babelin kuningas, tuli kaupungin tykö, ja hänen palveliansa piirittivät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Niin Jojakin Juudan kuningas meni äitinensä Babelin kuninkaan tykö, ja hänen palveliansa, ja ylimmäisensä, ja kamaripalveliansa. Ja Babelin kuningas otti hänen valtakuntansa kahdeksantena vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Ja hän otti kaiken tavaran Herran huoneesta ja kuninkaan huoneesta, ja rikkoi kaikki kultaiset astiat, jotka Salomo Israelin kuningas oli Herran templiin antanut tehdä niinkuin Herra puhunut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Ja vei koko Jerusalemin, kaikki ylimmäiset, kaikki voimalliset sotamiehet, kymmenentuhatta vankia, ja kaikki puusepät ja rautasepät pois, niin ettei yhtäkään jäänyt, vaan köyhimmät kansasta maalle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Ja vei Jojakinin ja kuninkaan äidin, kuninkaan emännät ja hänen kamaripalveliansa pois Babeliin. Ja ne voimalliset maalta vei hän myös Jerusalemista vankina Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Ja kaikki väkevät miehet, seitsemäntuhatta, ja tuhannen puuseppää ja rautaseppää, kaikki väkevät sotamiehet; ja Babelin kuningas vei heidät vankina Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Ja Babelin kuningas asetti Mattanian hänen setänsä kuninkaaksi hänen siaansa ja muutti hänen nimensä Zidkiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Yhden vuoden vanha kolmattakymmentä oli Zidkia tullessansa kuninkaaksi, ja hallitsi yksitoistakymmentä vuotta Jerusalemissa. Hänen äitinsä nimi oli Hamutal, Jeremian tytär Libnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Ja hän teki pahaa Herran edessä, niinkuin Jojakin myös tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Sillä se tapahtui niin Jerusalemin ja Juudan kanssa Herran vihasta, siihen asti että hän heitti heidät pois kasvoinsa edestä. Ja Zidkia erkani Babelin kuninkaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Niin tapahtui yhdeksäntenä hänen valtakuntansa vuonna, kymmenentenä päivänä kymmenennellä kuulla, että Nebukadnetsar Babelin kuningas tuli kaiken väkensä kanssa Jerusalemin eteen, ja he sioittuivat sen eteen ja rakensivat saarron joka taholta sen ympärille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Ja niin oli se kaupunki piiritetty kuningas Zidkian ensimäiseen vuoteen toistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Mutta yhdeksännellä kuukaudella tuli sangen suuri nälkä kaupunkiin, niin ettei maakunnan kansalla mitään syömistä ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Niin kukistettiin kaupunki, ja kaikki sotamiehet pakenivat yöllä ulos porttitietä, niiden kahden muurin väliltä, joka menee kuninkaan yrttitarhaan (vaan Kaldealaiset olivat ympäri kaupunkia), ja hän pakeni sitä tietä myöten tasaiselle kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Mutta Kaldealaisten sotaväki ajoi kuningasta takaa, ja he käsittivät hänen Jerihon kedolla; ja kaikki sotamiehet, jotka hänen tykönänsä olivat, olivat hänestä hajonneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Mutta kuninkaan he ottivat kiinni ja veivät hänen Babelin kuninkaan tykö Riblatiin; ja he tuomitsivat hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Ja he tappoivat Zidkian lapset hänen silmäinsä nähden, ja puhkasivat Zidkian silmät, ja sitoivat hänen kaksilla vaskikahleilla ja veivät Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Seitsemäntenä päivänä viidennellä kuukaudella, se on yhdeksästoistakymmenes Nebukadnetsarin Babelin kuninkaan ajastaika, tuli Nebutsaradan huovin päämies, Babelin kuninkaan palvelia, Jerusalemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Ja poltti Herran huoneen ja kuninkaan huoneen, ja kaikki huoneet Jerusalemissa, niin myös kaikki suuret huoneet poltti hän tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Ja kaikki Kaldealaisten sotaväki, jotka huovin päämiehen kanssa olivat, särkivät muurit, jotka Jerusalemin ympärillä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Mutta muun kansan, joka jäänyt oli kaupunkiin, ja ne jotka Babelin kuninkaan tykö paenneet olivat, ja muun yhteisen kansan vei Nebutsaradan huovin päämies pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Ja niitä halvimpia maakunnassa jätti huovin päämies viinamäen miehiksi ja peltomiehiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Mutta Kaldealaiset särkivät vaskiset patsaat Herran huoneessa, ja istuimet, ja vaskimeren, joka Herran huoneessa oli, ja veivät niiden vasken Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Ja padat, lapiot, veitset, lusikat ja kaikki vaskiset astiat, joilla palveltiin, ottivat he pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Huovin päämies otti myös pannut ja maljat, jotka olivat kokonansa kullasta ja hopiasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Kaksi patsasta, yhden meren ja istuimet, jotka Salomo oli antanut rakentaa Herran huoneesen; joita vaski-astioita ei taidettu kaikkia punnita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Yksi patsas oli kahdeksantoistakymmentä kyynärää korkia, ja sen kruunu oli myös vaskesta, joka kruunu oli kolme kyynärää korkia, ja verkko ja granatin omenat ympäri kruunun olivat kaikki vaskesta: tainkaltainen oli myös toinen patsas verkkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Ja huovin päämies otti papin Serajan ensimäisestä vuorosta ja papin Zephanian toisesta vuorosta, ja kolme ovenvartiaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Ja yhden kamarihaltian otti hän kaupungista, joka oli sotaväen haltiaksi asetettu, ja viisi miestä niistä, jotka seisoivat aina kuninkaan edessä, jotka kaupungista löydettiin, ja Sopherin sodanpäämiehen, joka maan kansan opetti sotimaan, niin myös kuusikymmentä miestä maan väestä, jotka kaupungista löydettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Nämät otti Nebutsaradan huovin ylimmäinen ja vei Babelin tykö Riblatiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Ja Babelin kuningas löi ja tappoi ne Riblatissa Hematin maalla. Näin vietiin Juuda pois maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Mutta sen väen päälle, joka Juudan maassa jälellä oli, jonka Nebukadnetsar Babelin kuningas jättänyt oli, asetti hän Gedalian Ahikamin pojan, Saphamin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Kuin kaikki sotajoukkoin päämiehet ja muut kuulivat Babelin kuninkaan korottaneen Gedalian, tulivat he Gedalian tykö Mitspaan: Ismael Netanian poika, ja Johanan Karean poika, ja Seraja Tanhumetin Netophatilaisen poika, ja Jaasanja Maakatin poika, miehinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Ja Gedalia vannoi heille ja heidän miehillensä ja sanoi heille: älkäät peljätkö olla Kaldealaisten alamaisina: pysykäät maassa ja palvelkaat Babelin kuningasta, niin te menestytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Mutta seitsemännellä kuukaudella tuli Ismael Netanian poika, Elisaman pojan kuninkaallisesta suvusta, ja kymmenen miestä hänen kanssansa, ja tappoivat Gedalian ja ne Juudalaiset ja Kaldealaiset, jotka hänen kanssansa olivat Mitspassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Niin nousi kaikki kansa sekä suuret että pienet, ja sotaväen päämiehet, ja tulivat Egyptiin; sillä he pelkäsivät Kaldealaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Seitsemäntenä ajastaikana neljättäkymmentä, sittekuin Jojakin Juudan kuningas oli viety pois, seitsemäntenä päivänä kolmattakymmentä, toisella kuukaudella toistakymmentä otti Evilmerodak Babelin kuningas ensimäisenä valtakuntansa vuonna Jojakinin Juudan kuninkaan ylös vankihuoneesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Ja puhui hänen kanssansa ystävällisesti, ja asetti hänen istuimensa ylemmäksi niiden kuningasten istuimia, jotka hänen tykönänsä olivat Babelissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Ja muutti hänen vankeutensa vaatteet; ja hän söi aina hänen tykönänsä kaiken elinaikansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Ja hän määräsi hänelle hänen osansa, hänelle aina joka päivä kuninkaalta annettavaksi, kaikkena hänen elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahaleel, Jared,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Henok, Metusala, Lamek,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noa, Sem, Ham ja Japhet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Japhetin lapset: Gomer, Magog, Madai, Javan ja Tubal, Mesek ja Tiras.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Gomerin lapset: Askenas, Riphatja, Togarma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Niin myös Javanin lapset: Elisa ja Tarsisa, Kittim ja Dodanim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Hamin lapset: Kus, Mitsraim, Put ja Kanaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Ja Kusin lapset: Seba, Hevila, Sabta, Raema ja Sabteka; ja Raeman lapset: Sjeba ja Dedan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Kus siitti Nimrodin: tämä rupesi olemaan voimallinen maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mistraim siitti Ludim, Anamim, Lehabim, Naphutim,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Niin myös Patrusim ja Kaluhim, joista Philistealaiset ovat tulleet ja Kaphtorim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaan siitti Zidonin esikoisensa ja Hetin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'Niin myös Jebusin, Amorin ja Gergosin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Ja Hevin, Arkin ja Sinin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Ja Arvadin, Zemarin ja Hematin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Semin lapset: Elam, Assur, Arphaksad, Lud ja Aram, Uts, Hul, Geter ja Masek.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Arphaksad siitti Salan, ja Sala siitti Eberin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Eberille oli syntynyt kaksi poikaa: yhden nimi oli Peleg, että hänen aikanansa oli maa jaettu, ja hänen veljensä nimi oli Joktan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Joktan siitti Almodadin ja Salephin, Hatsarmavetin ja Jaran,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoramin, Usalin ja Diklan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebalin, Abimaelin ja Sjeban,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ophirin, Hevilan ja Jobadin: nämät ovat kaikki Joktanin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arphaksad, Sala,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eber, Peleg, Regu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Tara,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, se on Abraham.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Abrahamin lapset: Isaak ja Ismael.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Nämät ovat heidän sukukuntansa: Ismaelin esikoinen Nebajot, Kedar, Adbeel ja Mibsam,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duma, Masa, Hadad ja Tema,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naphis ja Kedma: nämät ovat Ismaelin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Keturan Abrahamin toisen emännän lapset, jotka hän synnytti: Simran, Joksan, Medan, Midian, Jesbak ja Sua; ja Joksanin lapset: Sjeba ja Dedan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Midianin lapset: Epha, Epher, Henok, Abida ja Eldaa. Nämät ovat kaikki Keturan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Ja Abraham siitti Isaakin. Isaakin lapset olivat Esau ja Israel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Esaun lapset: Eliphas, Reguel, Jeus, Jaelam ja Korah.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Eliphan lapset: Teman, Omar, Zephi, Gaetan, Kenas, Timna ja Amalek.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reguelin lapset: Nahat, Sera, Samma ja Missa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Seirin lapset: Lotan, Sobal, Sibeon ja Ana, Dison, Etser ja Disan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lotanin lapset: Hori ja Homam; mutta Lotanin sisar oli Timna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Sobalin lapset: Aljan, Manahat, Ebal, Sephi ja Onam. Sibeonin lapset ovat: Aija ja Ana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Anan lapset: Dison. Disonin lapset: Hamran, Esban, Jitran ja Karan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Etserin lapset: Bilhan, Saevan, Jaekan. Disanin lapset: Uts ja Aran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Nämät ovat kuninkaat, jotka hallitsivat Edomin maalla, ennenkuin yksikään kuningas hallitsi Israelin lasten seassa: Bela Beorin poika, ja hänen kaupunkinsa nimi oli Dinhaba.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Ja kuin Bela oli kuollut, tuli Jobab Seran poika Botsrasta kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Kuin Jobab oli kuollut, tuli Husam kuninkaaksi hänen siaansa, Temanilaisten maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Kuin Husam oli kuollut, tuli hänen siaansa kuninkaaksi Hadad Bedadin poika, joka löi Midianilaiset Moabilaisten kedolla; ja hänen kaupunkinsa nimi oli Avit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Kuin Hadad oli kuollut, tuli hänen siaansa kuninkaaksi Samla Masrekasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Kuin Samla oli kuollut, tuli Saul Rehobotin virran tyköä kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Kuin Saul oli kuollut, tuli Baal Hanan Akborin poika kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Kuin Baal Hanan oli kuollut, hallitsi hänen siassansa Hadad; ja hänen kaupunkinsa nimi oli Pagi. Ja hänen emäntänsä nimi oli Mehetabeel, Matredin tytär, Mehasabin tyttären.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Kuin Hadad oli kuollut, olivat ruhtinaat Edomissa: ruhtinas Timna, ruhtinas Alja, ruhtinas Jetet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Ruhtinas Oholibama, ruhtinas Ela, ruhtinas Pinon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Ruhtinas Kenas, ruhtinas Teman, ruhtinas Mibtsar,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Ruhtinas Magdiel, ruhtinas Iram: nämät ovat Edomin ruhtinaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Nämät ovat Israelin lapset: Ruben, Simeon, Levi ja Juuda, Isaskar ja Sebulon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Joseph ja Benjamin, Naphtali, Gad ja Asser.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Juudan lapset: Ger, Onan, Sela, ne kolme synnytti hänelle Suan tytär Kanaanealainen. Ja Ger Juudan esikoinen oli paha Herran edessä, sentähden tappoi hän hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Ja Tamar hänen miniänsä synnytti hänelle Peretsen ja Seran, niin että Juudan lapsia oli kaikkiansa viisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Peretsen lapset: Hetsron ja Hamul.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Seran lapset: Simri, Etan, Heman, Kalkol ja Dara: ja heitä kaikkiansa oli myös viisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Karmin lapset: Akar, joka Israelin murheelliseksi saatti, ryhtyissänsä kirottuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Etanin lapset, Asaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Hetsronin lapset, jotka hänelle ovat syntyneet: Jerahmeel, Ram ja Kalubai.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ram siitti Amminadabin; Amminadab siitti Nahessonin, Juudan lasten päämiehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Nahesson siitti Salman; Salma siitti Boaksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Boas siitti Obedin; Obed siitti Isain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Isai siitti esikoisensa Eliabin, toisen Abinadabin, kolmannen Simean,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Neljännen Netaneelin, viidennen Raddain,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Kuudennen Otsemin ja seitsemännen Davidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Ja heidän sisarensa olivat Seruja ja Abigail. Serujan lapset: Abisai, Joab ja Asael, ne kolme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Ja Abigail synnytti Amasan; ja Jeter Ismaelilainen oli Amasan isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kaleb Hetsronin poika siitti emäntäinsä Asuban ja Jerigodin kanssa, nämät ovat hänen lapsensa: Jeser, Sobad ja Ardon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Ja kuin Asuba kuoli, otti Kaleb itsellensä Ephratin, joka synnytti hänelle Hurin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Hur siitti Urin ja Uri siitti Betsaleelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Sitte meni Hetsron Makirin Gileadin isän tyttären tykö ja nai hänen, kuin hän oli kuudenkymmenen ajastaikainen; ja hän synnytti hänelle Segubin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Ja Segub siitti Jairin; ja hänellä oli kolmekolmattakymmentä kaupunkia Gileadin maakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Mutta Gesur ja Aram saivat heiltä Jairin kylät, Kenatin ja hänen tyttärensä, kuusikymmentä kaupunkia: kaikki nämät ovat Makirin Gileadin isän lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Kuin Hetsron oli kuollut Kalebin Ephratassa, niin Hetsronin emäntä Abia synnytti hänelle Assurin Tekoan isän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Ja Jerahmeelilla Hetsronin esikoisella olivat lapset: hänen esikoisensa Ram, ja Buna, Oren, Otsem ja Ahia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Ja Jerahmeelilla oli vielä toinen emäntä, hänen nimensä oli Atara, hän on Onamin äiti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Ja Ramin Jerahmeelin esikoisen lapset: Maats, Jamin ja Eker.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Ja Onamilla olivat lapset: Samai ja Jada; Samain lapset: Nadab ja Abisur.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Ja Abisurin emännän nimi oli Abihail, ja hän synnytti hänelle Ahbanin ja Molidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Nadabin lapset: Seled ja Appaim. Ja Seled kuoli lapsetonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Ja Appaimin lapset: Jisei; ja Jisein lapset: Sesan; Sesanin lapset: Ahlai.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Ja Jodan Sammain veljen lapset: Jeter ja Jonatan. Ja Jeter kuoli lapsetonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Ja Jonatanin lapset: Pelet ja Sasa: nämät ovat Jerahmeelin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sesanilla ei ollut yhtään poikaa, vaan tyttäriä. Ja Sesanilla oli Egyptiläinen palvelia, hänen nimensä oli Jarha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Ja Sesan antoi Jarhalle palveliallensa tyttärensä emännäksi, hän synnytti hänelle Attain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Attai siitti Natanin, Natan siitti Sabadin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Sabad siitti Ephlalin, Ephlal siitti Obedin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Obed siitti Jehun, Jehu siitti Asarian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Asaria siitti Haletsin, ja Halets siitti Elasan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Elasa siitti Sismain, ja Sismai siitti Sallumin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Sallum siitti Jekamian, ja Jekamia siitti Elisaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Kalebin Jerahmeelin veljen lapset: Mesa hänen esikoisensa; hän on Siphin isä: ja Maresan Hebronin isän lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Ja Hebronin lapset: Kora, Tappua, Rekem ja Samma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Samma siitti Rahamin Jorkamin isän; ja Rekem siitti Sammain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Ja Sammain poika Maon, ja Maon oli Betsurin isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Ja Epha Kalebin vaimo synnytti Haranin, Motsan ja Gaseksen; ja Haran siitti Gaseksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Ja Jahdain lapset: Regem, Jotam, Gesan, Pelet, Epha ja Saaph.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maeka Kalebin vaimo synnytti Seberin ja Tirhenan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Ja hän synnytti myös Saaphin Madmannan isän ja Sjevan Makbenan isän ja Gibean isän. Ja Aksa oli Kalebin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Nämät olivat Kalebin lapset Hurin pojan Ephratan esikoisen: Sobal, Kirjatjearimin isä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma Betlehemin isä, Hareph Betgaderin isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Ja Sobalilla Kirjatjearimin isällä oli poikia: Haroe, Hatsimenyhot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Ja Kirjatjearimin sukukunnat: Jetriläiset, Putilaiset, Sumatilaiset ja Misrailaiset. Heistä ovat Zorgatilaiset ja Estaolilaiset tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Salman lapset, Betlehem ja Netophatilaiset, Joabin huoneen kruunut; ja puoli osaa Manatilaisista ovat Zorgilaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Ja kirjoittajain sukukunnat, jotka asuivat Jabeksessa, ovat Tirgatilaiset, Simealaiset, Sukatilaiset. Nämät ovat Kiniläiset, jotka ovat tulleet Hammatista Rekabin huoneen isästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Nämät olivat Davidin pojat, jotka hänelle syntyneet olivat Hebronissa: Amnon esikoinen, joka syntyi Ahinoamista Jisreeliläisestä, toinen Daniel Abigailista Karmelilaisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Kolmas Absalom Maakan poika Talmain Gessurin kuninkaan tyttären, neljäs Adonia Haggitin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Viides Sephatia Abitalista, kuudes Jitream, hänen emännästänsä Eglasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Nämät kuusi ovat hänelle syntyneet Hebronissa. Ja hän hallitsi siellä seitsemän vuotta ja kuusi kuukautta; mutta Jerusalemissa hallitsi hän kolmeneljättäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Ja nämät ovat hänelle syntyneet Jerusalemissa: Simea, Sobab, Natan ja Salomo, ne neljä Batsuasta Ammeelin tyttärestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'Sitte Jibhar, Elisama ja Eliphalet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Nogah, Nepheg ja Japhia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eljada, Eliphelet; ne yhdeksän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Nämät ovat kaikki Davidin pojat; ilman muiden vaimoin lapsia. Ja Tamar oli heidän sisarensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Rehabeam oli Salomon poika, hänen poikansa Abia, hänen poikansa Asa, hänen poikansa Josaphat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Hänen poikansa Joram, hänen poikansa Ahasia, hänen poikansa Joas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Hänen poikansa Amasia, hänen poikansa Asaria, hänen poikansa Jotam,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Hänen poikansa Ahas, hänen poikansa Hiskia, hänen poikansa Manasse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Hänen poikansa Amon, hänen poikansa Josia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Mutta Josian pojat olivat: esikoinen Johanan, toinen Jojakim, kolmas Zidkia, neljäs Sallum.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Mutta Jojakimin lapset: Jekonia hänen poikansa, Zidkia hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Mutta vangitun Jekonian lapset: hänen poikansa Sealtiel,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, '(Hänen poikansa) Malkiram, Pedaja, Senatsar, Jekamja, Hosama, Nedabja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Pedajan pojat, Zerubbabel ja Simi; Zerubbabelin pojat Mesullam ja Hanania, ja heidän sisarensa Selomit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'Hasuba, Ohel, Berekia, Hasadia, Jusabhesed; ne viisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Hananian pojat Pelatja ja Jesaja; Rephajan pojat, Arnanin pojat, Obadian pojat, Sekanian pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Mutta Sekanian lapset: Semaja; ja Semajan lapset: Hattus, Jigal, Baria, Nearia, Saphat; ne kuusi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Nearin lapset: Eljoenai, Hiskia, Asrikam; ne kolme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Eljoenain lapset: Hodajeva, Eljasib, Pelaja, Akkub, Johanan, Delaja ja Anani; ne seitsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Juudan lapset: Perets, Hetsron, Karmi, Hur ja Sobal.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Mutta Reaja Sobalin poika siitti Jahatin, Jahat siitti Ahumain ja Lahadin: nämät ovat Zorgalaisten sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Ja nämät Etamin isän: Jisreel, Jisma, Jidbas, ja heidän sisarensa nimi oli Hatslelponi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'Ja Penuel Gedorin isä, ja Eser Husan isä: nämät ovat Hurin Betlehemin isän Ephratan esikoisen lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Mutta Ashurilla Tekoan isällä oli kaksi emäntää, Helea ja Naera.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Ja Naera synnytti hänelle Ahussamin, Hepherin, Temenin, Ahastarin: nämät ovat Naeran lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Mutta Helean lapset: Zeret, Jesohar ja Etnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Mutta Kots siitti Anubin ja Hatsobeban, ja Aharhelin Harumin pojan sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Mutta Jagbets oli kuuluisampi veljiänsä; ja hänen äitinsä kutsui hänen Jagbets, sillä hän sanoi: minä olen hänen synnyttänyt kivulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Ja Jagbets rukoili Israelin Jumalaa ja sanoi: jos sinä minua hyvin siunaisit ja levittäisit minun maani rajat, ja sinun kätes olis minun kanssani, ja asettaisit sitä pahaa, ettei se minua vaivaisi. Ja Jumala antoi tapahtua niinkuin hän rukoili.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Mutta Kelub Suan veli siitti Mehirin, se on Estonin isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Mutta Eston siitti Petraphan, Pasean, Tehinnan Irnahaksen isän: nämät ovat Rekan miehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Kenaksen lapset: Otniel ja Seraja; Otnielin lapset: Hatat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Ja Meonatai siitti Ophran, ja Seraja siitti Joabin seppäin laakson isän, sillä he olivat puusepät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Kalebin Jephunnen pojan lapset: Iru, Ela ja Naam; Elan lapset: Kenas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Jehaleelin lapset: Siph, Sipha, Tiria ja Asareel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Esran lapset: Jeter, Mered, Epher ja Jalon; ja hän siitti Mirjamin, Sammain, Jisban, Estemoan isän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Ja hänen Juudalainen emäntänsä synnytti Jeredin Gedorin isän, Heberin Sokon isän, Jekuthelin Sanoan isän: nämät ovat Bitian Pharaon tyttären lapset, jonka Mered otti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Hodijan emännän Nahamin Kegilan isän sisaren lapset: Garmi ja Estemoa, Maakatilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Ja Simonin lapset: Amnon ja Rinna, Benhanan ja Tilon. Jisin lapset: Sohet ja Bensohet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Selan Juudan pojan lapset: Erlekan isä, Laeda Maresan isä, ja liinainkutojain suvut Asbean huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'Niin myös Jokim, ja Koseban miehet, Joas ja Saraph, jotka olivat herrat Moabissa ja Jasubilekemissä: nämät ovat vanhat asiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'He olivat savenvalajat ja asuivat moisioissa ja umpiaidoissa, ja kuninkaan tykönä työnsä tähden, siellä he asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeonin lapset: Nemuel ja Jamin, Jarib, Sera, Saul,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Sallum hänen poikansa, Mibsam hänen poikansa, Misma hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Misman pojat olivat: Hamuel hänen poikansa, Sakur hänen poikansa, Simei hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simeillä oli kuusitoistakymmentä poikaa ja kuusi tytärtä, mutta hänen veljillänsä ei ollut monta lasta; sillä kaikki heidän sukukuntansa ei enentynyt niinkuin Juudan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Ja he asuivat Bersebassa, Moladassa ja Hatsarsuasissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Ja Bilhassa ja Etsemissä ja Toladissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Ja Betuelissa ja Hormassa ja Siklagissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Ja Betmarkabotissa ja Hatsarsusimissa, BetBirissä ja Saaraimissa. Nämät olivat heidän kaupunkinsa, Davidin hallitukseen asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Ja heidän kylänsä, Etam, Ain, Rimmon, Token ja Asan: viisi kaupunkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'Ja kaikki ne kylät, jotka olivat niiden kaupunkein ympäristöllä Baaliin asti. Tämä on heidän asumasiansa ja sukukuntansa heidän keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Ja Mesobab, Jamlek ja Josat Amatsian poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Joel ja Jehu Josibian poika, Serajan pojan, Asielin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenai, Jaekoba, Jesohaja, Asaja, Adiel, Jesimiel ja Benaja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'Ja Sisa Siphin poika, Allonin pojan, Jedajan pojan, Simrin pojan, Semajan pojan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Nämät nimitettiin päämiehiksi sukukuntainsa seassa; ja heidän isäinsä huone hajoitti itsensä paljouden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Ja he menivät pois ja tulivat hamaan Gedoriin asti itäiselle puolelle laaksoa, etsimään laidunta lampaillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Ja he löysivät lihavan ja hyvän laitumen ja maan, joka oli avara ja lavia, rauhallinen ja levollinen; sillä Hamin lapset olivat ennen siellä asuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Ja jotka nimenomattain kirjoitetut olivat, tulivat Hiskian Juudan kuninkaan aikaan, ja he löivät muiden majat ja Meonilaiset jotka sieltä löydettiin, ja hävittivät heidät hamaan tähän päivään asti, ja asuivat heidän siallansa; sillä siellä olivat laitumet heidän lampaillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Ja silloin meni heistä liki viisisataa miestä, jotka olivat Simeonin lapsia, Seirin vuorelle; ja Pelatia, Nearia, Rephaja ja Ussiel Jisein lapset olivat heidän päämiehensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Ja tappoivat päässeet ja jääneet Amalekilaisista, ja asuivat siinä tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Rubenin Israelin esikoisen lapset, sillä hän oli ensimäinen poika; mutta että hän isänsä vuoteen saastutti, annettiin hänen esikoisuutensa Josephin Israelin pojan lapsille, ja ei hän ole polviluvussa luettu esikoiseksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Sillä Juuda oli voimallinen veljeinsä seassa, ja pääruhtinaat ovat hänestä; ja Josephilla on esikoisuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Niin ovat Rubenin Israelin ensimäisen pojan lapset: Hanok, Pallu, Hetsron ja Karmi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Ja Joelin lapset: Semaja hänen poikansa, Gog hänen poikansa, Simei hänen poikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Hänen poikansa Miika, hänen poikansa Reaja, hänen poikansa Baal,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Hänen poikansa Beera, jonka Tiglat Pilneser Assyrian kuningas vei vangiksi; hän oli Rubenilaisten pääruhtinas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Mutta hänen veljensä heidän sukukuntainsa jälkeen, koska he heidän sukukunnissansa polvilukuun luettiin, pitivät he Jeielin ja Sakarian pääruhtinainansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Ja Bela Asaksen poika, Seman pojan, Joelin pojan: hän asui Aroerissa hamaan Neboon ja Baalmeoniin asti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Ja asui itään päin siihenasti kuin tullaan korpeen, Phratin virran tyköä; sillä heidän karjansa oli paljo enentynyt Gileadin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Ja Saulin ajalla sotivat he Hagarilaisia vastaan, niin että ne lankesivat heidän kättensä kautta; ja he asuivat heidän majoissansa, kaikessa itäisessä puolessa Gileadin maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Ja Gadin lapset asuivat juuri heidän kohdallansa Basanin maassa Salkaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel ylimmäinen, Sapham toinen, Jaenai ja Saphat Basanissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Ja heidän veljensä heidän isäinsä huoneen jälkeen, Mikael, Mesullam, Seba, Jorai, Jaekan, Sia ja Eber, seitsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Nämät ovat Abihailin lapset Hurin pojan, Jaroan pojan, Gileadin pojan, Mikaelin pojan, Jesirain pojan, Jahdon pojan, Busin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi Abdielin poika, Gunin pojan, oli päämies heidän isäinsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Ja he asuivat Basanin Gileadissa ja hänen kylissänsä ja kaikissa Saronin esikaupungeissa, hamaan heidän rajoihinsa asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Nämät ovat kaikki luetut polvilukuun Jotamin Juudan kuninkaan ja Jerobeamin Israelin kuninkaan aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Rubenin lapset, Gadilaiset ja puoli Manassen sukukuntaa, jotka olivat urhoolliset miehet, jotka kilpeä ja miekkaa kantoivat ja taisivat joutsen jännittää, ja olivat oppineet sotimaan; joita oli neljäviidettäkymmentä tuhatta, seitsemänsataa ja kuusikymmentä, jotka kelpasivat sotaan menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Ja kuin he läksivät sotaan Hagarilaisia, Jeturia, Naphesta ja Nodabia vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Niin he autettiin niitä vastaan, ja Hagarilaiset annettiin heidän käsiinsä, ja kaikki jotka heidän kanssansa olivat; sillä he huusivat Jumalan tykö sodassa, ja hän kuuli heidän rukouksensa, että he turvasivat häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Ja he veivät heidän karjansa pois, viisikymmentä tuhatta kamelia, kaksisataa ja viisikymmentä tuhatta lammasta, kaksituhatta aasia, niin myös satatuhatta ihmistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Sillä siellä lankesi monta haavoitettuna, että sota oli Jumalalta. Ja he asuivat niiden siassa vankeuteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Ja puolen Manassen sukukunnan lapset asuivat maassa, Basanissa hamaan Baal Hermoniin ja Seniriin, ja Hermonin vuoreen asti; sillä heitä oli monta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Ja nämät olivat pääruhtinaat heidän isäinsä huoneessa: Epher, Jisei, Eliel, Asriel, Jeremia, Hodavia, Jahdiel, väkevät ja voimalliset miehet ja kuuluisat pääruhtinaat heidän isäinsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Ja koska he syntiä tekivät isäinsä Jumalaa vastaan, ja tekivät huoruutta niiden kansain epäjumalain kanssa siinä maassa, jotka Jumala oli hävittänyt heidän edestänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Herätti Israelin Jumala Phulin Assyrian kuninkaan hengen, ja Tiglat Pilneserin Assyrian kuninkaan hengen, ja vei Rubenilaiset, Gadilaiset ja puolen Manassen sukukuntaa pois, ja vei heidät Halaan, Haboriin, ja Haraan, ja Gosanin virran tykö, hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Levin lapset: Gerson, Kahat ja Merari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Mutta Kahatin lapset: Amram, Jitsehar, Hebron ja Usiel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Amramin lapset: Aaron, Moses ja Mirjam; Aaronin lapset: Nadab, Abihu, Eleasar ja Itamar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleasar siitti Pinehaan; Pinehas siitti Abisuan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua siitti Bukkin; Bukki siitti Ussin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Ussi siitti Serajan; Seraja siitti Merajotin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajot siitti Amarian; Amaria siitti Ahitobin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Ahitob siitti Zadokin; Zadok siitti Ahimaatsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Ahimaats siitti Asarian; Asaria siitti Johananin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Johanan siitti Asarian, joka oli pappi siinä huoneessa, jonka Salomo rakensi Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Asaria siitti Amarian; Amaria siitti Ahitobin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Ahitob siitti Zadokin; Zadok siitti Sallumin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Sallum siitti Hilkian; Hilkia siitti Asarian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Asaria siitti Serajan; Seraja siitti Jotsadakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Jotsadak myös meni pois, silloin kuin Herra antoi Juudan ja Jerusalemin vietää vankina Nebukadnetsarin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Levin lapset: Gersom, Kahat ja Merari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Ja nämät olivat Gersomin lasten nimet: Libni ja Simei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Kahatin lapset: Amram, Jitsehar, Hebron ja Ussiel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Merarin lapset: Maheli ja Musi. Nämät ovat Leviläisten sukukunnat heidän isäinsä seassa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Gersomin poika oli Libni, hänen poikansa Jahat, hänen poikansa Simma,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Hänen poikansa Joah, hänen poikansa Iddo, hänen poikansa Sera, hänen poikansa Jeatrai.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Kahatin lapset: hänen poikansa Amminadab, hänen poikansa Kora, hänen poikansa Assir,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Hänen poikansa Elkana, hänen poikansa Abiasaph, hänen poikansa Assir,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Hänen poikansa Tahat, hänen poikansa Uriel, hänen poikansa Ussia, hänen poikansa Saul.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Elkanan lapset: Amasai ja Ahimot,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkana, hänen poikansa Elkana, hänen poikansa Sophai, hänen poikansa Nahat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Hänen poikansa Eliab, hänen poikansa Jeroham, hänen poikansa Elkana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Samuelin lapset: hänen esikoisensa Vasni ja Abia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Merarin lapset: Maheli, hänen poikansa Libni, hänen poikansa Simei, hänen poikansa Ussa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Hänen poikansa Simea, hänen poikansa Haggia, hänen poikansa Asaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Ja nämät ovat ne, jotka David asetti veisaamaan Herran huoneesen, kuin arkki lepäsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Ja he palvelivat virsillä seurakunnan majan asuinsian edessä, siihenasti että Salomo rakensi Herran huoneen Jerusalemissa; ja he seisoivat virassansa asetuksensa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ja nämät ovat ne, jotka siellä seisoivat, ja heidän lapsensa: Kahatin lapsista, Heman veisaaja, Joelin poika, Samuelin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Elkanan pojan, Jerohamin pojan, Elielin pojan, Toan pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Zuphin pojan, Elkanan pojan, Mahatin pojan, Amasain pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Elkanan pojan, Joelin pojan, Asarian pojan, Zephanian pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Tahatin pojan, Assirin pojan, Abiasaphin pojan, Koran pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Jitseharin pojan, Kahatin pojan, Levin pojan, Israelin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Ja hänen veljensä Assaph seisoi hänen oikialla puolellansa; ja Assaph oli Berekian poika, Simejan pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Mikaelin pojan, Baesejan pojan, Malkian pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Etnin pojan, Seran pojan, Adajan pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Etanin pojan, Simman pojan, Simein pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Jahatin pojan, Gersomin pojan, Levin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Mutta heidän veljensä, Merarin lapset, vasemmalla puolella: Etan Kisin poika, Abdin pojan, Mallukin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Hasabian pojan, Amasian pojan, Hilkian pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Amsin pojan, Banin pojan, Samerin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Mahelin pojan, Musin pojan, Merarin pojan, Levin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Ja Leviläiset heidän veljensä olivat annetut kaikkinaisiin virkoihin Jumalan huoneen asuinsiassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Ja Aaron ja hänen poikansa olivat sytyttäjät polttouhrin alttarilla ja suitsutusalttarilla kaikkinaisissa töissä siinä kaikkein pyhimmässä, sovittamassa Israelia, juuri niinkuin Moses Jumalan palvelia käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Nämät ovat Aaronin lapset: Eleasar hänen poikansa, Pinehas hänen poikansa, Abisua hänen poikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Bukki hänen poikansa, Ussi hänen poikansa, Seraja hänen poikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Merajot hänen poikansa, Amaria hänen poikansa, Ahitob hänen poikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Zadok hänen poikansa, Ahimaats hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Ja nämät ovat heidän asuinsiansa ja kylänsä heidän rajoissansa: Aaronin lasten Kahatilaisten sukukunnasta: sillä arpa lankesi heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Ja he antoivat heille Hebronin Juudan maalta ja hänen esikaupunkinsa hänen ympäristöltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Mutta kaupungin pellot ja sen kylät antoivat he Kalebille Jephunnen pojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Niin antoivat he Aaronin lapsille vapaat kaupungit, Hebronin ja Libnan esikaupunkeinensa, Jaterin ja Estemoan esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Hilen esikaupunkeinensa, ja Debirin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asanin esikaupunkeinensa, ja Betsemeksen esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Ja BenJaminin sukukunnasta: Geban esikaupunkeinensa, Alemetin esikaupunkeinensa ja Anatotin esikaupunkeinensa. Ja kaikki kaupungit heidän sukukunnissansa olivat kolmetoistakymmentä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Mutta ne muut Kahatin lapset heidän suvussansa, siitä puolesta Manassen sukukunnasta, saivat kymmenen kaupunkia arvalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Gersonin lapset heidän sukukuntainsa jälkeen saivat Isaskarin sukukunnalta, Asserin sukukunnalta, Naphtalin sukukunnalta ja Manassen sukukunnalta Basanissa, kolmetoistakymmentä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Ja Merarin lapset heidän sukukuntainsa jälkeen saivat arvalla Rubenin sukukunnalta, Gadin sukukunnalta ja Sebulonin sukukunnalta, kaksitoistakymmentä kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Ja Israelin lapset antoivat myös Leviläisille kaupungit esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'Ja antoivat arvan jälkeen Juudan lasten sukukunnasta, Simeonin lasten sukukunnasta, BenJaminin lasten sukukunnasta, ne kaupungit, jotka he nimittivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Mutta ne, jotka olivat Kahatin lasten suvusta, saivat rajakaupunkinsa Ephraimin sukukunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Niin antoivat he heille nämät vapaat kaupungit: Sikemin ja sen esikaupungit, Ephraimin vuorelta, niin myös Geserin ja sen esikaupungit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmeamin ja sen esikaupungit, ja Bethoronin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalonin esikaupunkeinensa, ja Gatrimmonin esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'Niin myös puolesta Manassen sukukunnasta, Anerin esikaupunkeinensa, ja Bileamin esikaupunkeinensa, antoivat he jääneiden Kahatin lasten sukukunnalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Mutta Gersonin lapsille antoivat he puolesta Manassen sukukunnasta, Golanin Basanissa esikaupunkeinensa, ja Astarotin esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'Isaskarin sukukunnasta, Kedeksen esikaupunkeinensa, ja Dobratin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramotin esikaupunkeinensa, ja Anemin esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'Asserin sukukunnasta, Masalin esikaupunkeinensa ja Abdonin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hukokin esikaupunkeinensa, ja Rehobin esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'Naphtalin sukukunnasta, Kedeksen Galileassa esikaupunkeinensa, Hammonin esikaupunkeinensa ja Kirjataimin esikaupunkeinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Muille Merarin lapsille antoivat he Sebulonin sukukunnasta, Rimmonin esikaupunkeinensa, ja Taborin esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'Ja tuolta puolen Jordania Jerihoon päin, itään käsin Jordanin tyköä, Rubenin sukukunnasta, Betserin korvessa esikaupunkeinensa, ja Jahsan esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemotin esikaupunkeinensa, ja Mephaatin esikaupunkeinensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'Gadin sukukunnasta, Ramotin Gileadissa esikaupunkeinensa, Mahanaimin esikaupunkeinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Ja Hesbonin esikaupunkeinensa, ja Jaeserin esikaupunkeinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Isaskarin lapset: Tola, Pua, Jasub ja Simron, neljä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Tolan lapset: Ussi, Rephaja, Jeriel, Jahemai, Jibsam ja Samuel, jotka olivat päämiehet heidän isäinsä huoneessa Tolasta, ja väkevät miehet sukukunnissansa; heidän lukunsa oli Davidin aikana kaksikolmattakymmentä tuhatta ja kuusisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Ussin lapset: Jisraja. Ja Jisrajan lapset: Mikael, Obadia, Joel ja Jesia, viisi, ja olivat kaikki päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Ja heidän kanssansa heidän sukukunnissansa isäinsä huoneessa oli sotajoukko kuusineljättäkymmentä tuhatta; sillä heillä oli monta emäntää ja lasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Ja heidän veljensä, jalot miehet kaikesta Isaskarin sukukunnasta, olivat seitsemänyhdeksättäkymmentä tuhatta, nämät kaikki luettiin polvilukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'BenJaminin lapset: Bela, Beker, Jediael, ne kolme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Belan lapset: Etsbon, Ussi, Ussiel, Jerimot ja Iri, ne viisi, päämiehet heidän isäinsä huoneesta, väkevät miehet, ja heitä luettiin polvilukuun kaksikolmattakymmentä tuhatta ja neljäneljättäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Bekerin lapset: Semira, Joas, Elieser, Eljoenai, Omri, Jeremot, Abia, Anatot ja Alemeth: ne kaikki olivat Bekerin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Ja olivat luetut polvilukuun heidän sukukunnastansa, heidän isäinsä huoneen päämiehet, kaksikymmentä tuhatta ja kaksisataa jaloa miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Jediaelin lapset: Bilhan. Bilhanin lapset: Jeus, Benjamin, Ehud, Kenaena, Setan, Tarsis ja Ahisaar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Ne olivat kaikki Jediaelin lapset, heidän isäinsä sukukuntain päämiehet, ja väkevät miehet: seitsemäntoistakymmentä tuhatta ja kaksisataa, jotka sotaan läksivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Suppim ja Huppim olivat Irin lapset. Mutta Husim Aherin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naphtalin lapset: Jahsiel, Guni, Jetser ja Sallum, Bilhan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manassen lapset: Esriel, jonka hänen emäntänsä synnytti; mutta hänen Syrialainen jalkavaimonsa synnytti Makirin Gileadin isän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Makir otti Huppimin ja Suppimin tyköä emännän, joka oli molempain sisar, Maeka nimeltä; hänen toisen poikansa nimi oli Zelophkad. Ja Zelophkadilla oli tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Ja Maeka Makirin emäntä synnytti pojan, jonka hän kutsui Peres, ja hänen veljensä kutsuttiin Sares, ja hänen poikansa oli Ulam ja Rakem.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Mutta Bedam oli Ulamin poika. Nämät ovat Gileadin lapset, Makirin pojan Manassen pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Ja hänen sisarensa Moleeket synnytti Ishudin, Abieserin ja Mahlan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Ja Semidalla olivat nämät lapset: Ahjan, Sikem, Likhi ja Aniam.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Nämät ovat Ephraimin lapset: Sutela, ja Bered hänen poikansa, Tahat hänen poikansa, Elada hänen poikansa, Tahat hänen poikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'Sabad hänen poikansa, Sutela hänen poikansa, Eser ja Elad. Ja Gatin miehet, siinä maassa syntyneet, löivät heidät kuoliaaksi; sillä he olivat menneet ottamaan heidän karjaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Ja heidän isänsä Ephraim murehti kauvan aikaa; ja hänen veljensä tulivat lohduttamaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Ja hän meni emäntänsä tykö, ja hän siitti ja synnytti pojan, jonka hän kutsui Beria, että hän oli ollut ahdistuksessa huoneessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Hänen tyttärensä oli Seera, hän rakensi alimaisen ja ylimäisen Bethoronin ja Ussen Seeran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Hänen poikansa oli Repha ja Reseph, ja Tela hänen poikansa, Tahan hänen poikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Ladan hänen poikansa, Ammihud hänen poikansa, Elisama hänen poikansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'Nun hänen poikansa, Josua hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Ja heidän tavaransa ja asuinsiansa oli Betel, kyläinsä kanssa, ja Naeran itään päin, ja Geser länteen päin kyläinsä kanssa, Sekem kyläinsä kanssa, hamaan Assaan asti kyläinsä kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Ja Manassen lasten poikain tyköä, Betsean kylinensä, Taenak ja hänen kylänsä, Megiddo ja hänen kylänsä. Näissä asuivat Josephin Israelin pojan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Asserin lapset: Jimna, Jisva, Jisvi, Beria ja Sera heidän sisarensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Berian lapset olivat: Heber ja Makiel, se on Bersavitin isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Ja Heber siitti Japhletin, Somerin, Hotamin, ja Suan heidän sisarensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Japhletin lapset: Pasak, Bimhal ja Asvat: ne olivat Japhletin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Somerin lapset: Ahi, Rahga, Jehubba ja Aram.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Ja hänen veljensä Helemin lapset: Zopha, Jimna, Seles ja Amal.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Zophan lapset: Sua, Harnepher, Sual, Beri ja Jimra,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Betser, Hod, Samma, Silsa, Jitran ja Beera.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Jeterin lapset: Jephunne, Phispa ja Ara.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ullan lapset: Arah, Hanniel ja Ritsja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Nämät olivat kaikki Asserin lapset, valitut päämiehet heidän isäinsä huoneessa, väkevät miehet ja päämiesten pääruhtinaat, ja luettiin polvittain sotajoukkoon, ja heidän lukunsa oli kuusikolmattakymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamin siitti Belan ensimäisen poikansa, Asbalin toisen, Ahran kolmannen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noan neljännen, Raphan viidennen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Ja Belalla oli lapsia, Addar, Gera, Abihud,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naaman ja Ahoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sephupham ja Huram.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Nämät ovat Ehudin lapset, jotka olivat isäin päämiehet niiden seassa, jotka asuivat Gebassa; ja hän vei heitä Manahatiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Naaman, Ahia ja Gera, hän vei heidät pois, ja siitti Ussan ja Ahihudin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Ja Saharaim siitti Moabin maalla, sittekuin hän heidät tyköänsä laskenut oli, Husimista ja Baerasta hänen emännistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Ja hän siitti emännästänsä Hodesta, Jobabin, Zibian, Mesan ja Malkamin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeusin, Sobjan ja Mirman. Nämät ovat hänen lapsensa, isäin päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Husimista siitti hän Abitobin ja Elpaalin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Elpaalin lapset olivat: Eber, Miseam ja Semer: se rakensi Onon ja Lodin, ja hänen kylänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Ja Beria ja Sama olivat isäin päämiehet, niiden, jotka asuivat Ajalonissa: ne ajoivat niitä takaa, jotka asuivat Gatissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'Ja Ahio, Sasak ja Jeremot,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Sebadia, Arad, Ader,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mikael, Jispa ja Joha, Berian lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Sebadia, Mesullam, Hiski, Heber,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jismerai, Jislia ja Jobab, Elpaanin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Jakim, Sikri ja Saddi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Zilletai ja Eliel,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja ja Simrat, Simein lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Jispan, Eber ja Eliel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Sikri ja Hanan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananja, Elam ja Antotia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jiphdeja ja Penuel, Sasakin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Samserai, Seharia ja Atalia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaeresia, Elia ja Sikri, Jerohamin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Nämät ovat isäin päämiehet heidän sukukunnissansa; ja he asuivat Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Mutta Gibeonissa asui Gibeonin isä; ja hänen emäntänsä nimi oli Maeka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Ja hänen ensimäinen poikansa oli Abdon, sitte oli Zur, Kis, Baal ja Nadab,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahio ja Seker.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Mutta Miklot siitti Simean; ja he asuivat myös Jerusalemissa veljeinsä kohdalla heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ner siitti Kisin; Kis siitti Saulin; Saul siitti Jonatanin, Malkisuan, Abinadabin ja Esbaalin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Jonatanin poika oli Meribbaal; Meribbaal siitti Miikan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Miikan lapset olivat: Piton, Melek, Taerea ja Ahas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ahas siitti Joaddan; Joadda siitti Alemetin, Asmavetin ja Simrin; Simri siitti Motsan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Motsa siitti Binean; hänen poikansa oli Rapha, hänen poikansa Elasa, hänen poikansa Atsel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Mutta Atselilla oli kuusi poikaa, joiden nimet olivat: Esrikam, Bokru, Ismael, Searia, Obadia ja Hanan. Nämät kaikki olivat Atselin pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Esekin hänen veljensä lapset: Ulam hänen ensimäinen poikansa, Jeus toinen, Eliphelet kolmas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Mutta Ulamin lapset olivat vahvat miehet ja jalot joutsimiehet, ja heillä oli paljo poikia ja poikain poikia, sata ja viisikymmentä. Nämät kaikki ovat Benjaminin lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Ja koko Israel luettiin polviluvun jälkeen, ja katso, he ovat kirjoitetut Israelin kuningasten kirjaan; ja Juuda vietiin Babeliin pahain tekoinsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Mutta ne ensimäiset asujamet, jotka tulivat perintöönsä ja kaupunkeihinsa, olivat Israel, papit, Leviläiset ja Netinimit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Ja silloin asuivat Jerusalemissa Juudan lapsista, Benjaminin lapsista, ja Ephraimin ja Manassen lapsista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utal Ammihudin poika, Omrin pojan, Imrin pojan, Banin pojan, Peretsin Juudan pojan lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'Mutta Silonilaisista Asaja ensimäinen poika, ja hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'Seran lapsista, Jeguel veljinensä; kuusisataa ja yhdeksänkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'Benjaminin lapsista, Sallu Mesullamin poika, Hodavian pojan, Hassenuan pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Ja Jibneja Jerohamin poika, ja Ela Ussin poika, Mikrin pojan, ja Mesullam Sephatian poika, Reguelin pojan, Jibnejan pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Niin myös heidän veljensä sukukuntainsa jälkeen yhdeksänsataa ja kuusikuudettakymmentä: nämät kaikki ovat olleet isäin päämiehet heidän isäinsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Papeista: Jedaja, Jojarib ja Jakin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Ja Asaria Hilkian poika, Mesullamin pojan, Zadokin pojan, Merajotin pojan, Ahitobin pojan, Jumalan huoneen päämies,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Ja Adaja Jerohamin poika, Pashurin pojan, Malkian pojan, ja myös Maesai Adielin poika, Jahseran pojan, Mesullamin pojan. Mesillemitin pojan, Immerin pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'Niin myös heidän veljeinsä päämiehet isäinsä huoneessa, tuhannen seitsemänsataa ja kuusikymmentä väkevää miestä, toimittamaan viran menoja Jumalan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Mutta Leviläisistä, jotka olivat Merarin lapsia, Semaja Hassubin poika, Asrikamin pojan, Hasabian pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Ja Bakbakkar, Heres, ja Galal, ja Mattania Miikan poika, Sikrin pojan, Asaphin pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Ja Obadia Semajan poika, Galalin pojan, Jedutunin pojan, ja Berekia Asan poika, Elkanan pojan, joka asui Netophatilaisten kylissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Ja ovenvartiat olivat Sallum, Akkub, Talmon, Ahiman ja heidän veljensä: Sallum oli ylimmäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Sillä he olivat tähän saakka vartioineet itäisellä puolella kuninkaan porttia: ne olivat ovenvartiat Levin poikain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Ja Sallum Koren poika Ebjasaphin pojan, Koran pojan ja hänen veljensä hänen isänsä huoneesta, ne Korhilaiset, heidän virkansa menoissa, vartioitsemaan seurakunnan majan ovipieleen; ja heidän isänsä pitää vartioitseman Herran leirissä sisällekäymistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Mutta Pinehas Eleasarin poika oli ennen ollut heidän päämiehensä; sillä Herra oli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Ja Sakaria Meselemian poika oli vartia seurakunnan majan ovella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Kaikki nämät olivat valitut ovea vartioitsemaan, kaksisataa ja kaksitoistakymmentä, jotka olivat luetut polviluvun jälkeen heidän kylissänsä. Ja David ja Samuel, näkiä, asettivat heitä virkaan heidän uskollisuudessansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Niin että he ja heidän lapsensa ottivat Herran huoneesta vaarin, seurakunnan majan huoneesta, että he sitä vartioitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Ja ovenvartiat olivat asetetut neljää ilmaa kohden: itään, länteen, pohjaan ja etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Mutta heidän veljensä olivat maakylissänsä, niin kuitenkin, että heidän piti tuleman sisälle seitsemäntenä päivänä, ja ajasta niin aikaan heidän tykönänsä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Sillä Leviläiset olivat uskotut olemaan neljäksi ylimmäiseksi ovenvartiaksi; ja he olivat myös kätkyin ja Herran huoneen tavarain päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'Ja he olivat yötä Jumalan huoneen ympärillä; sillä heidän piti sitä vartioitseman, ja avajaman joka aamu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Ja muutamat olivat heistä viran asetten päällä; sillä heidän piti ne kantaman ulos ja sisälle luvun jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Ja muutamat heistä olivat asetetut astiain ja pyhäin kaluin päälle, sämpyläjauhoin, viinan, öljyn, pyhän savun ja myös yrttein päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Mutta muutamat pappein lapsista tekivät hyvin valmistettuja voiteita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Ja Mattitjalle Leviläisistä, Sallumin Korhilaisten ensimäiselle pojalle oli uskottu mitä pannuissa valmistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Ja Kahatilaisista heidän veljistänsä olivat asetetut katsomusleipäin yli, että he niitä valmistaisivat joka sabbattina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Nämät ovat veisaajat, Leviläisten isäin päämiehet vapaat heidän kammioissansa; sillä he olivat siellä askareissansa päivää ja yötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Nämät olivat ylimmäiset Leviläisten isät, päämiehet sukukunnissansa; he asuivat Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Jegil Gibeonin isä asui Gibeonissa; hänen emäntänsä nimi oli Maeka,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'Ja hänen ensimäinen poikansa Abdon, Zur, Kis, Baal, Ner ja Nadab,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahio, Sakaria ja Miklot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Mutta Miklot siitti Simeamin; jotka myös asuivat veljeinsä kohdalla, veljinensä Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ja Ner siitti Kisin; Kis siitti Saulin; Saul siitti Jonatanin, Malkisuan, Abinadabin, Esbaalin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Ja Meribbaal oli Jonatanin poika; ja Meribbaal siitti Miikan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Miikan pojat olivat Piton, Melek ja Tahrea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahas siitti Jaeran; Jaera siitti Alemetin, Asmavetin ja Simrin; Simri siitti Motsan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Motsa siitti Binejan; ja Rephaja oli hänen poikansa, Eleasa hänen poikansa, Atsel hänen poikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Ja Atselilla oli kuusi poikaa, ja nämät olivat heidän nimensä: Asrikam, Bokru, Ismael, Searia, Obadia ja Hanan: ne olivat Atselin pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Mutta Philistealaiset sotivat Israelia vastaan; ja Israel pakeni Philistealaisia, ja he lankesivat lyötynä Gilboan vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Ja Philistealaiset kovin ajoivat Saulia ja hänen poikiansa takaa, ja Philistealaiset löivät Jonatanin, Abinadabin ja Malkisuan, Saulin pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Ja sota oli ankara Saulia vastaan, ja joutsimiehet tulivat hänen päällensä, ja hän haavoitettiin ampujilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Niin sanoi Saul aseensa kantajalle: vedä miekkas ulos ja pistä minut lävitse, ettei nämät ympärileikkaamattomat tulisi ja tekisi häpiällisesti minulle. Mutta hänen aseensa kantaja ei tahtonut; sillä hän pelkäsi suuresti. Niin otti Saul miekan ja heittäysi siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Kuin hänen aseensa kantaja näki Saulin kuolleeksi, heittäysi myös hän miekkaan ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Ja niin Saul kuoli, ja kolme hänen poikaansa, ja koko hänen huoneensa kuoli yhtä haavaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Kuin Israelin miehet, jotka laaksossa olivat, näkivät heidän paenneeksi ja Saulin poikinensa kuolleeksi, jättivät he kaupunkinsa ja pakenivat. Ja Philistealaiset tulivat ja asuivat niissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Toisena päivänä tulivat Philistealaiset riisumaan lyötyjä, ja he löysivät Saulin poikinensa makaavan Gilboan vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Ja sittekuin he hänen riisuneet olivat, ottivat he hänen päänsä ja aseensa, ja lähettivät Philistealaisten maan ympäri, ja antoivat ilmoittaa epäjumalillensa ja kansalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Ja panivat hänen aseensa jumalansa huoneesen, ja hänen päänsä löivät he kiinni Dagonin huoneen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Kuin kaikki Gileadin Jabeksessa kuulivat kaikki, mitä Philistealaiset Saulille tehneet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Nousivat kaikki väkevät miehet ja ottivat Saulin ja hänen poikansa ruumiit, ja veivät ne Jabekseen, ja hautasivat heidän luunsa tammen alle Jabeksessa, ja paastosivat seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Ja niin kuoli Saul pahoissa teoissansa, joita hän Herraa vastaan tehnyt oli, ettei hän pitänyt Herran sanaa, ja että hän myös etsi velhovaimoa kysyäksensä häneltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Ja ei kysynyt Herralta; sentähden tappoi hän hänen, ja käänsi valtakunnan Davidille Isain pojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Ja koko Israel kokoontui Davidin tykö Hebroniin ja sanoi: katso, me olemme sinun luus ja lihas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Ja aina ennenkin, Saulin ollessa kuninkaana, johdatit sinä Israelin ulos ja sisälle. Ja Herra sinun Jumalas on sanonut sinulle: sinun pitää kaitseman kansaani Israelia ja sinun pitää oleman kansani Israelin päämiehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Ja kaikki Israelin vanhimmat tulivat kuninkaan tykö Hebroniin, ja David teki liiton heidän kanssansa Herran edessä Hebronissa. Ja he voitelivat Davidin Israelin kuninkaaksi Herran sanan jälkeen Samuelin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Sitten meni David ja koko Israel Jerusalemiin, se on Jebus; sillä Jebusilaiset asuivat siinä maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Ja Jebuksen asuvaiset sanoivat Davidille: sinun ei pidä tuleman tänne; mutta David voitti Zionin linnan, se on Davidin kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Ja David sanoi: joka Jebusilaiset ensin lyö, hänen pitää oleman pään ja ylimmäisen. Niin Joab Zerujan poika astui ensin ylös ja tuli päämieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Ja David asui linnassa; sentähden kutsuivat he sen Davidin kaupungiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Ja hän rakensi kaupungin ympäri Millosta ja sitte kaiken ympäri. Ja Joab jätti ne elämään, jotka jääneet olivat kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Ja niin David menestyi ja tuli väkeväksi, ja Herra Zebaot oli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Nämät ovat ylimmäiset Davidin väkevimpäin seassa, jotka miehuullisesti hänen kanssansa pitivät hänen valtakunnassansa koko Israelin tykönä, niin että hän tehtiin kuninkaaksi Herran sanan jälkeen Israelin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Ja tämä on Davidin sankarien luku: Jasobeam Hakmonin poika ylimmäinen päämiesten seassa. Hän nosti keihäänsä ja löi kerralla kolmesataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Hänen jälkeensä oli Eleasar, Dodon Ahohilaisen poika, hän oli kolmen sankarin seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Tämä oli Davidin kanssa Pasdammimissa, kuin Philistealaiset olivat kokoontuneet sinne sotaan. Ja oli kappale peltoa ohraa täynnä, ja kansa pakeni Philistealaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'Ja he astuivat keskelle peltoa, ja varjelivat sen, ja löivät Philistealaiset. Ja Herra antoi heille suuren autuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Ja kolme niistä kolmestakymmenestä ylimmäisestä tulivat kalliolle alas Davidin tykö Adullamin luolaan. Mutta Philistealaisten leiri oli Rephaimin laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Ja David oli silloin linnassa; ja Philistealaisten kansa oli silloin Betlehemissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Ja David himoitsi ja sanoi: kuka antais minun juoda sitä vettä, joka on kaivossa Betlehemin portin tykönä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Niin ne kolme juoksivat Philistealaisten leiriin, ja ammunsivat vettä kaivosta Betlehemin portin tyköä, ottivat ja kantoivat Davidille; mutta ei David tahtonut sitä juoda, vaan kaasi sen Herran eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'Ja sanoi: Jumala antakoon sen kaukana olla minusta, että minä tämän tekisin! pitäiskö minun juoman näiden miesten verta heidän henkensä vaarassa? sillä he ovat sen tuoneet henkensä vaaralla; sentähden ei hän tahtonut sitä juoda. Sen tekivät ne kolme sankaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Abisai Joabin veli, hän oli ylimmäinen kolmesta, ja hän nosti keihäänsä ja löi kolmesataa, ja hän ylistettiin niiden kolmen seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Ja hän oli kolmen seassa kuuluisampi kahta ja oli heidän päämiehensä; mutta kolmen tykö ei hän tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja Jojadan poika väkevän miehen poika, joka suuria töitä tehnyt oli, Kabtseelista: hän löi kaksi Moabilaisten jalopeuraa; ja hän meni alas ja löi jalopeuran keskellä kaivoa lumen aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Hän löi myös Egyptin miehen, joka oli viisi kyynärää pitkä, ja Egyptiläisen kädessä oli keihäs niinkuin kankaan puu, mutta hän meni alas hänen tykönsä sauvalla, tempasi keihään Egyptiläisen kädestä ja tappoi hänen omalla keihäällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Näitä teki Benaja Jojadan poika; ja hän ylistettiin kolmen uljasten seassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Ja oli kuuluisampi niitä kolmeakymmentä; mutta kolmen tykö ei hän tullut. Ja David teki hänen salaiseksi neuvonantajaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Niin myös sotasankarit: Asahel Joabin veli, Elhanan Dodonin poika Betlehemistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Samot Harorilainen, Heles Pelonilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira Ikeksen Tekoalaisen poika, Abieser Antotilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibbekai Husatilainen, Ilai Ahohilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maherai Netophatilainen, Heled Baenan Netophatilaisen poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Ittai Ribain poika Gibeasta, BenJaminin lapsista, Benaja Pirtagonilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hurai Gasin pojista, Abiel Arbatilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmavet Baharumilainen, Eliahba Saalbonilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Hasemin Gisonilaisen lapset: Jonatan Sagen Hararilaisen poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam Sakarin Hararilaisen poika, Eliphal Urin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hepher Makeratilainen, Ahia Pelonilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hetsro Karmelilainen, Naerai Asbain poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel Natanin veli, Mibhar Hagrin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek Ammonilainen, Naherai Berotilainen, Joabin Zerujan pojan aseenkantaja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira Jetriläinen, Gareb Jetriläinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uria Hetiläinen, Sabad Ahelain poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina Sisan Rubenilaisen poika, Rubenilaisten päämies, ja kolmekymmentä oli hänen kanssansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan Maekan poika, Josaphat Mitniläinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Ussia Asteratilainen, Sama ja Jeiel Hotamin Aroerilaisen pojat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael Simrin poika, Joha hänen veljensä, Titsiläinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel Maheavilainen, Jeribai ja Josavia Elnaamin pojat, Itma Moabilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Obed ja Jaesiel Mesobajasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Nämät tulivat Davidin tykö Ziklagiin, kuin hän vielä oli suljettu Saulin Kisin pojan edestä; ja he olivat myös sankarein seassa, jotka sotaan auttivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Ja olivat soveliaat ampujat joutsella molemmin käsin, kivillä, nuolilla ja joutsilla: Saulin veljistä, BenJaminista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Ahieser päämies ja Joas, Semajan Gibealaisen pojat, Jesiel ja Pelet Asmavetin pojat, Baraka ja Jehu Antonilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Jesmaja Gibeonilainen, väkevä kolmenkymmenen seassa ja ylitse kolmenkymmenen, Jeremia, Jahesiel, Johanan ja Josabad Gederalainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elusai, Jerimot, Bealia, Semaria ja Saphatia Harophilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Jesija, Asareel, Joeser ja Jasobeam Korhilainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Joela ja Sedadia Jerohamin lapset Gedorista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Gadilaisista eroittivat heitänsä Davidin tykö linnaan korvessa väkevät sankarit ja sotamiehet, jotka kilpeä ja keihästä kantoivat; ja heidän kasvonsa olivat niinkuin jalopeuran kasvot, ja nopiat niinkuin metsävuohet vuorilla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ensimäinen Eser, toinen Obadia, kolmas Eliab,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Neljäs Mismanna, viides Jeremia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Kuudes Attai, seitsemäs Eliel,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Kahdeksas Johanan, ykdeksäs Elsabad,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Kymmenes Jeremia, yksitoistakymmenes Mahbanai.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Nämät olivat Gadin lapsista sodan päämiehet: vähin sadan päälle ja suurin tuhannen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Nämät ovat ne jotka menivät Jordanin ylitse ensimäisenä kuuna, kuin se oli täysi kaikkiin reunoihinsa asti; ja he ajoivat pakoon kaikki, jotka asuivat laaksossa, itään ja länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Ja sinne myös tulivat BenJaminin lapsista ja Juudasta, Davidin tykö linnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Ja David meni ulos heidän tykönsä, ja vastasi ja sanoi heille: jos tulitte rauhan kanssa minun tyköni auttamaan minua, niin olkoon sydämeni teidän kanssanne: vaan jos tulitte pettämään minua vihollisilleni, vaikka ei vääryyttä ole minussa, niin meidän isäimme Jumala nähköön ja rangaiskoon;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Ja henki vaikutti Amasain, päämiehen kolmenkymmenen seassa: Sinun me olemme, David, ja pidämme sinun kanssas, Isain poika, rauha, rauha olkoon sinulle, rauha olkoon sinun auttajilles! sillä sinun Jumalas auttaa sinua. Niin otti David heidät tykönsä ja asetti heidät sotaväen päämiehiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Ja Manassesta tuli väkeä Davidin puolelle, kuin hän meni Philistealaisten kanssa Saulia vastaan sotaan, vaikka ei he auttaneet heitä; sillä Philistealaisten päämiehet antoivat neuvonpiteestä hänen tyköänsä mennä pois, ja sanoivat: jos hän lankee herransa Saulin tykö, niin se tulee henkemme vaaraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Kuin hän meni Ziklagiin, tulivat hänen tykönsä Manassesta Adna, Josabad, Jediael, Mikael, Josabad, Elihu ja Ziltai, tuhanten päämiehet Manassesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Ja he auttivat Davidia sotajoukkoa vastaan; sillä he olivat kaikki väkevät miehet ja olivat päämiehet sodassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Ja joka päivä tuli muutamia Davidin tykö auttamaan häntä, siihenasti että se tuli suureksi sotajoukoksi, niinkuin Jumalan sotajoukoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Ja tämä on sotaan hankittuin päämiesten luku, jotka tulivat Davidin tykö Hebroniin, kääntämään Saulin valtakuntaa hänen tykönsä, Herran sanan jälkeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Juudan lapsista, jotka kantoivat kilpeä ja keihästä, oli kuusituhatta ja kahdeksansataa sotaan hankittua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Simeonin lapsista väkevät miehet sotimaan, seitsemäntuhatta ja sata;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Levin lapsista neljätuhatta ja kuusisataa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Ja Jojada niiden päämies, jotka olivat Aaronista, ja hänen kanssansa oli kolmetuhatta ja seitsemänsataa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'Ja Zadok väkevä nuorukainen, ja hänen isänsä huoneen kanssa oli kaksikolmattakymmentä päämiestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'Ja BenJaminin lapsista Saulin veljistä kolmetuhatta; sillä siihenasti piti heistä sangen monta vielä Saulin huoneen kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'Ja Ephraimin lapsista kaksikymmentä tuhatta ja kahdeksansataa, väkevät ja ylistetyt miehet heidän isäinsä huoneessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'Ja puolesta Manassen sukukunnasta kahdeksantoistakymmentä tuhatta, jotka olivat nimeltänsä nimitetyt tulemaan ja tekemään Davidia kuninkaaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'Ja Isaskarin lapsista, jotka olivat taitavat aikain tietäjät ymmärtämään, mitä Israelin tekemän piti, kaksisataa heidän päämiestänsä, ja kaikki heidän veljensä tekivät heidän käskynsä jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Sebulonista, jotka menivät sotimaan, hankitut sotaan kaikkinaisilla sota-aseilla, viisikymmentä tuhatta, asettamaan itsensä yksimielisesti järjestykseen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Naphtalista tuhannen päämiestä, ja seitsemänneljättäkymmentä tuhatta heidän kanssansa, jotka kantoivat kilpeä ja keihästä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'Danista hankitsivat sotaan kahdeksankolmattakymmentä tuhatta ja kuusisataa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Asserista, jotka menivät hankittuina sotimaan, neljäkymmentä tuhatta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'Tuolta puolelta Jordania: Rubenilaisista, Gadilaisista ja puolesta Manassen sukukunnasta, kaikkinaisilla aseilla sotaan, sata ja kaksikymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Kaikki nämät sotamiehet sodan toimittajat tulivat täydestä sydämestä Hebroniin, tekemään Davidia koko Israelin kuninkaaksi: niin myös kaikilla muilla Israelissa oli yksi mieli tehdä Davidia Israelin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Ja he olivat siellä Davidin tykönä kolme päivää, söivät ja joivat; sillä heidän veljensä olivat valmistaneet heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Ja ne myös, jotka likin olivat heidän ympärillänsä Isaskariin, Sebuloniin ja Naphtaliin asti, he toivat leipiä aaseilla, kameleilla, muuleilla ja härjillä, syötäviä jauhoja, fikunoita, rusinoita, viinaa, öljyä, härkiä ja lampaita viljalta; sillä ilo oli Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Ja David piti neuvoa tuhanten ja satain pääruhtinain ja kaikkein päämiesten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Ja David sanoi kaikelle Israelin joukoille: jos teille kelpaa, ja jos se on Herralta meidän Jumalaltamme, niin toimittakaamme kaikella muotoa menemään muiden meidän veljeimme tykö koko Israelin maahan, ja pappein ja Leviläisten tykö kaupunkeihin, joissa esikaupungit ovat, että he kokoontuisivat meidän tykömme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Ja noutakaamme Jumalamme arkki meidän tykömme; sillä emme Saulin aikana siitä lukua pitäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Niin kaikki joukko vastasi, että niin piti tehtämän; sillä se kelpasi kaikelle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Niin David kokosi kaiken Israelin, Egyptin Siihorista aina Hamatiin asti, noutamaan Jumalan arkkia Kirjatjearimista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Ja David meni ja kaikki Israel Baalatiin, Kirjatjearimiin, joka on Juudassa, noutamaan sieltä Herran Jumalan arkkia, joka Kerubimin päällä istuu, jonka nimeä rukoillaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Ja he panivat Jumalan arkin uuteen vaunuun, veivät sen Abinadabin huoneesta, ja Ussa ja Ahio ajoivat vaunua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Mutta David ja kaikki Israel iloitsivat Jumalan edessä kaikesta voimastansa, lauluilla, kanteleilla, psaltareilla, trumpuilla, symbaleilla ja basunilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Ja he tulivat Kidonin lakeudelle, niin ojensi Ussa kätensä arkkia pitelemään; sillä härjät poikkesivat sivulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Niin Herran viha julmistui Ussan päälle ja löi häntä, että hän ojensi kätensä arkkia pitämään, niin että hän siinä kuoli Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Niin David tuli murheelliseksi, että Herra Ussan repäisi rikki. Ja hän kutsui sen paikan Perets-ussa tähän päivään asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Ja David pelkäsi Jumalaa sinä päivänä ja sanoi: kuinka minun pitää viemän Jumalan arkin minun tyköni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Sentähden ei David antanut viedä Jumalan arkkia tykönsä Davidin kaupunkiin, vaan antoi poiketa Obededomin Gatilaisen huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Ja Jumalan arkki viipyi Obededomin tykönä hänen huoneessansa kolme kuukautta. Ja Herra siunasi Obededomin huoneen ja kaikki mitä hänellä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Ja Hiram Tyron kuningas lähetti sanansaattajat Davidin tykö, ja sedripuita, muuraajia ja puuseppiä, rakentamaan hänelle huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Ja David ymmärsi, että Herra oli hänen vahvistanut Israelin kuninkaaksi; sillä hänen valtakuntansa korkeni hänen kansansa Israelin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Ja David otti vielä emäntiä Jerusalemissa, ja hän siitti vielä poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Ja niiden nimet, jotka hänelle olivat syntyneet Jerusalemissa, olivat: Sammua, Sobab, Natan ja Salomo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elisua ja Elpalet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noga, Nepheg ja Japhia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Baeljada ja Eliphalet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Ja kuin Philistealaiset kuulivat Davidin voidelluksi koko Israelin kuninkaaksi, nousivat kaikki Philistealaiset Davidia etsimään. Kun David sen kuuli, meni hän heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Ja Philistealaiset tulivat ja levisivät Rephaimin laaksoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Mutta David kysyi neuvoa Jumalalta ja sanoi: pitääkö minun menemän ylös Philistealaisia vastaan, ja tahdotkos heitä antaa minun käsiini? Herra sanoi hänelle: mene, ja minä tahdon antaa heidät sinun käsiis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Ja kuin he menivät ylös Baalperatsimiin päin, löi David heidät siellä; ja David sanoi: Jumala on hajoittanut vihamieheni minun käteni kautta, niinkuin vesi hajoitetaan; sentähden kutsuivat he sen paikan nimen Baalperatsim.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Ja he jättivät sinne jumalansa, ja Davidin käskyn jälkeen poltettiin ne tulessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Mutta Philistealaiset kokoontuivat jälleen ja asettivat itsensä alas laaksoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Ja David kysyi jälleen neuvoa Jumalalta, ja Jumala sanoi hänelle: ei sinun pidä menemän heidän jälkeensä; mutta poikkea heistä, ettäs tulisit metsäfikunapuiden kohdalla heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Ja kuin kuulet metsäfikunapuiden latvat havisevan, niin mene sotimaan; sillä Jumala on mennyt sinun edelläs lyömään Philistealaisten sotajoukkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Ja David teki niinkuin Jumala hänelle oli käskenyt; ja he löivät Philistealaisten sotajoukot Gibeonista niin Gaseriin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Ja Davidin nimi kuului kaikissa maissa; ja Herra antoi hänen pelkonsa tulla kaikkein pakanain päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Ja hän rakensi itsellensä huoneita Davidin kaupunkiin, ja valmisti sian Jumalan arkille, ja valmisti sille majan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Silloin sanoi David: ei yhdenkään pidä kantaman Jumalan arkkia, vaan Leviläiset; sillä Herra on heidät valinnut kantamaan Jumalan arkkia ja palvelemaan häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Sentähden kokosi David koko Israelin Jerusalemiin, kantamaan Herran arkkia ylös siihen paikkaan, jonka hän hänelle valmistanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Ja David antoi myös tulla kokoon Aaronin lapset ja Leviläiset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Kahatin lapsista päämiehen Urielin, sadan ja kahdenkymmenen veljensä kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Merarin lapsista päämiehen Asajan, kahdensadan ja kahdenkymmenen veljensä kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Gersomin lapsista päämiehen Joelin, sadan ja kolmenkymmenen veljensä kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Elitsaphanin lapsista päämiehen Semajan, kahdensadan veljensä kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Hebronin lapsista päämiehen Elielin, kahdeksankymmenen veljensä kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Ussielin lapsista päämiehen Amminadabin, sadan ja kahdeksantoistakymmenen veljensä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Ja David kutsui papit Zadokin ja Abjatarin, ja Leviläiset, Urielin, Asajan, Joelin, Semajan, Elielin ja Amminadabin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'Ja sanoi heille: te kuin olette isäin päämiehet Leviläisten seassa, pyhittäkäät teitänne veljeinne kanssa kantamaan ylös Herran Israelin Jumalan arkkia siihen siaan, jonka minä hänelle valmistanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Sillä ennen kuin ette läsnä olleet, teki Herra meidän Jumalamme raon meissä, ettemme häntä etsineet, niinkuin meidän tekemän piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Niin papit ja Leviläiset pyhittivät itsensä Herran Israelin Jumalan arkkia kantamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Ja Leviläisten pojat kantoivat Jumalan arkin, niinkuin Moses Herran sanan jälkeen käskenyt oli, olallansa korennoilla, jotka siinä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Ja David sanoi Leviläisten päämiehille, että he asettaisivat veljistänsä veisaajia harpuilla, psaltareilla, kanteleilla ja symbaleilla, niin että he olisivat kuultut veisaavan korkialla äänellä ilon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Niin Leviläiset asettivat Hemanin Joelin pojan ja hänen veljistänsä Asaphin Berekian pojan, ja Merarin pojista heidän veljistänsä Etanin Kusajan pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'Ja heidän kanssansa heidän veljensä toisesta vuorosta, Sakarian, Benin, Jaeselin, Semiramotin, Jehielin, Unnin, Eliabin, Benajan, Maesejan, Mattitjan, Eliphelehun, Miknejan, Obededomin ja Jeielin, ovenvartiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Sillä Heman, Asaph ja Etan olivat veisaajat vaskisymbaleilla, helistäin heliällä äänellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Mutta Sakaria, Ussiel, Semiramot, Jehiel, Unni, Eliab, Maesia ja Benaja psaltarilla alamotin päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Vaan Mattitja ja Eliphelehu ja Mikneja, ja Obededom, Jeiel ja Ahasia veisasivat kahdeksan kielisillä kanteleilla heidän edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Mutta Kenania Leviläisten päämies, veisumestari, piti neuvoman heitä ylhäisesti veisaamaan; sillä hän oli sangen taitava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Ja Berekia ja Elkana olivat arkin ovenvartiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Mutta papit Sebania, Josaphat, Netaneel, Amasai, Sakaria, Benaja ja Elieser soittivat basunilla Jumalan arkin edessä; ja Obededom ja Jehija olivat arkin ovenvartiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Niin meni David ja Israelin vanhimmat ja tuhanten päämiehet noutamaan Herran liitonarkkia Obededomin huoneesta ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Ja koska Jumala autti Leviläisiä, jotka kantoivat Herran liitonarkkia, uhrasivat he seitsemän mullia ja seitsemän oinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Ja David oli puettu liinavaatteella, ja kaikki Leviläiset, jotka arkkia kantoivat, ja veisaajat, ja Kenania veisumestari veisaajain kanssa; oli myös Davidin yllä liinainen päällisvaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Niin saatti koko Israel Herran liitonarkin ilolla, basunain, trometein, heliäin symbalein, psaltarein ja kantelein kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Kuin Herran liitonarkki tuli Davidin kaupunkiin, katsoi Mikal Saulin tytär akkunasta ja näki Davidin hyppäävän ja soittavan, niin hän katsoi hänen sydämessänsä ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Kuin he Jumalan arkin olivat kantaneet sisälle, asettivat he sen keskelle majaa, jonka David oli valmistanut, ja uhrasivat polttouhria ja kiitosuhria Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Ja kuin David oli täyttänyt polttouhrit ja kiitosuhrit, siunasi hän kansaa Herran nimeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Ja jakoi jokaiselle Israelissa sekä miehille että vaimoille, jokaiselle leivän ja kappaleen lihaa ja mitan viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Ja hän asetti Herran arkin eteen muutamia Leviläisiä palveliaksi, ylistämään, kiittämään ja kunnioittamaan Herraa Israelin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Ne olivat: Asaph ensimäinen, Sakaria toinen, Jeiel, Semiramot, Jehiel, Mattitja, Eliab, Benaja, Obededom ja Jeiel, psaltarein ja harppuin kanssa; mutta Asaph kiliseväisten symbalein kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Ja Benaja ja Jehasiel papit, vaskitorvilla, aina Jumalan liitonarkin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Sinä päivänä asetti David ensisti kiittämään Herraa, Asaphin ja hänen veljeinsä kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Kiittäkäät Herraa ja saarnatkaat hänen nimeänsä, julistakaat hänen töitänsä kansain seassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Veisatkaat hänelle, soittakaat hänelle, puhukaat kaikista hänen ihmeellisistä töistänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Ylistäkäät hänen pyhää nimeänsä, niiden sydän iloitkaan, jotka etsivät Herraa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Etsikäät Herraa ja hänen voimaansa, etsikäät hänen kasvojansa alati!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Muistakaat hänen ihmeellisiä töitänsä, jotka hän tehnyt on, hänen ihmeitänsä ja suunsa tuomioita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Te Israelin hänen palveliansa siemen, te Jakobin hänen valittunsa lapset!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Hänpä on Herra meidän Jumalamme, hän tuomitsee kaikessa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Muistakaat ijankaikkisesti hänen liittoansa, mitä hän on käskenyt tuhannelle sukukunnalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Jonka hän teki Abrahamin kanssa ja hänen valaansa Isaakin kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Ja sääsi sen Jakobille säädyksi ja Israelille ijankaikkiseksi liitoksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Ja sanoi: sinulle minä annan Kanaanin maan, teidän perimisenne arvan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Koska te vähät ja harvat olitte, ja muukalaiset siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Ja he vaelsivat kansasta kansaan, ja yhdestä valtakunnasta toiseen kansaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Eipä hän sallinut kenenkään heitä vahingoittaa, vaan rankaisi kuninkaat heidän tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Älkäät ruvetko minun voideltuihini, ja älkäät pahaa tehkö minun prophetailleni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Veisatkaat Herralle kaikki maa, julistakaat päivä päivältä hänen autuuttansa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Luetelkaat pakanain seassa hänen kunniaansa, kaikkein kansain seassa hänen ihmeitänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Sillä Herra on suuri ja sangen kiitettävä, peljättävä kaikkein jumalain seassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Sillä kaikki pakanain jumalat ovat epäjumalat; mutta Herra on taivaat tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Kaunistus ja kunnia on hänen edessänsä, ja väkevyys ja ilo on hänen siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Te kansain sukukunnat, tuokaat Herralle, tuokaat Herralle kunnia ja voima!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Tuokaat Herralle hänen nimensä kunnia, tuokaat lahjoja ja tulkaat hänen eteensä. Kumartakaat Herraa pyhässä kaunistuksessa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Peljätkäät häntä kaikki maailma; hän on maan vahvistanut, ettei se liiku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Taivaat iloitkaan ja maa riemuitkaan, sanottakaan pakanain seassa, että Herra hallitsee!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Meri pauhatkaan ja mitä siinä on, kedot iloitkaan ja kaikki, mitä sen päällä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Ja ihastukaan kaikki puut metsissä Herran edessä; sillä hän tulee tuomitsemaan maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Kiittäkäät Herraa, sillä hän on hyvä, ja hänen laupiutensa on ijankaikkinen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Ja sanokaat: auta meitä Jumala, meidän vapahtajamme, ja kokoa meitä ja kehitä meitä pakanoista, että me kiittäisimme sinun pyhää nimeäs ja kerskaisimme sinun kiitoksessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Kiitetty olkoon Herra Israelin Jumala ijankaikkisesta ijankaikkiseen; ja kaikki kansa sanokaan: amen! ja kiittäkään Herraa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Näin jätti hän Herran liitonarkin eteen Asaphin ja hänen veljensä, palvelemaan alinomati arkin edessä jokapäiväisessä työssä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Mutta Obededomin ja hänen kahdeksan veljeänsä seitsemättäkymmentä, ja Obededomin Jeditunin pojan ja Hossan, ovenvartiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Ja papin Zadokin ja papit hänen veljensä pani hän Herran majan eteen Gibeonin korkeudelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Tekemään päivä päivältä Herralle polttouhria polttouhrin alttarilla aamulla ja ehtoolla; kaiketi niinkuin kirjoitettu on Herran laissa, ja hän Israelille käskenyt oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Ja Hemanin ja Jedutunin heidän kanssansa, ja muut valitut, nimeltänsä nimitetyt, kiittämään Herraa, että hänen laupiutensa on ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Ja Hemanin ja Jedutunin heidän kanssansa, vaskitorvilla ja symbaleilla soittamaan, ja Jumalan kanteleilla. Mutta Jedutunin pojat pani hän ovenvartiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Ja näin matkusti kaikki kansa kukin kotiansa; David myös palasi siunaamaan huonettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Ja tapahtui, kuin David asui huoneessansa, sanoi hän propheta Natanille: katso, minä asun sedrihuoneessa, ja Herran liitonarkki on vaatetten alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'Natan sanoi Davidille: kaikki mikä sinun sydämessäs on, tee, sillä Herra on sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mutta sinä yönä tuli Jumalan sana Natanin tykö ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Mene ja sano palvelialleni Davidille: näin sanoo Herra: ei sinun pidä minulle rakentaman huonetta asuakseni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Sillä en minä ole asunut yhdessäkään huoneessa siitä päivästä, kuin minä Israelin lapset johdatin ulos, tähän päivään asti, vaan minä olen aina ollut majoissa ja tabernaklissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Kuhunka ikänä minä vaelsin koko Israelissa, olenko minä puhutellut jotakuta tuomaria Israelissa, jonka minä olen käskenyt kaita minun kansaani, ja sanonut: miksi ette ole minulle rakentaneet sedrihuonetta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Niin sano nyt näin palvelialleni Davidille: näin sanoo Herra Zebaot: minä olen ottanut sinun kedolta, kussas lampaita kaitsit, kansani Israelin päämieheksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Ja olen ollut sinun kanssas, kuhunkas ikänä vaelsit, ja olen hävittänyt kaikki vihamiehes edestäs, ja olen tehnyt sinulle nimen, niiden suurten nimien jälkeen, jotka maan päällä ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Mutta minä panen kansalleni Israelille paikan ja istutan sen niin, että se siinä asuu ja ei enään liikuteta, ja pahan kansan ei pidä enää sitä vaivaaman niinkuin ennen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Ja siitä ajasta, jona minä asetin tuomarit kansalleni Israelille, painoin minä kaikki sinun vihamiehes alas: ja minä ilmoitan sinulle Herran rakentavan sinulle huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Ja pitää tapahtuman, kuin sinun aikas on täytetty, että sinä menet isäis tykö, niin minä herätän sinun siemenes sinun jälkees, joka pitää oleman sinun pojistas, ja minä vahvistan hänen valtakuntansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Hän rakentaa minulle huoneen, ja minä vahvistan hänen istuimensa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Minä olen hänen isänsä, ja hän on minun poikani: ja en minä käännä laupiuttani häneltä pois, niinkuin minä sen käänsin häneltä pois, joka sinun edelläs oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Mutta minä asetan hänen minun huoneeseni ja valtakuntaani ijankaikkisesti, niin että hänen istuimensa on pysyväinen ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Ja kuin Natan kaikkein näiden sanain jälkeen ja kaiken tämän näyn jälkeen Davidin kanssa puhunut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Niin tuli kuningas David ja oli Herran edessä, ja sanoi: kuka olen minä, Herra Jumala? ja mikä on minun huoneeni, ettäs olet saattanut minun tähän asti?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Ja tämä on vähä ollut sinun silmäis edessä, Jumala, mutta sinä olet myös puhunut sinun palvelias huoneelle kaukaisista asioista, ja olet katsellut minun niinkuin ihmisen hahmossa, joka on Herra Jumala korkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Mitä enempää David mahtaa anoa sinulta, ettäs kunnioittaisit palvelias? sillä sinä tunnet palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Herra, palvelias tähden ja sinun sydämes jälkeen olet sinä kaikki nämät suuret asiat tehnyt, ilmoittaakses kaikki ne suuret työt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Herra, ei ole sinun kaltaistas ja ei ole Jumalaa paitsi sinua, kaiken senjälkeen, minkä me korvillamme kuulleet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Ja mikä kansa maan päällä on niinkuin kansas Israel, jota Jumala mennyt on vapahtamaan itsellensä kansaksi, ja tekemään itsellensä nimeä suurista ja hirmuisista töistä, ajain pakanat ulos kansas edestä, jonkas Egyptistä vapahtanut olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Ja olet tehnyt kansas Israelin itselles ijankaikkiseksi kansaksi, ja sinä Herra olet heidän Jumalaksensa tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Nyt Herra, se sana, jonkas puhunut olet palveliastas ja hänen huoneestansa, vahvistukoon ijankaikkisesti! ja tee niinkuin sinä puhunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Vahvistukoon ja suureksi tulkoon sinun nimes ijankaikkisesti! että sanottaisiin: Herra Zebaot, Israelin Jumala, on Jumala Israelissa, ja palvelias Davidin huone olkoon pysyväinen sinun edessäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Sillä sinä, Jumalani, olet ilmoittanut palvelias korvain kuullen, ettäs rakennat hänelle huoneen, sentähden on palvelias aikonut rukoilla sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Nyt Herra, sinä olet Jumala, ja sinä olet tätä hyvää puhunut palvelialles;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Niin rupee nyt siunaamaan palvelias huonetta, että se pysyis ijankaikkisesti sinun edessäs; sillä sinä Herra olet siunannut sen, niin olkoon se siunattu ijankaikkisesti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Sitte löi David Philistealaiset ja vaati allensa heidät, ja hän otti Gatin kylinensä Philistealaisten kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Hän löi myös Moabilaiset, niin että he tulivat Davidille alamaisiksi ja veivät hänelle lahjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David löi myös Hadareserin Zoban kuninkaan Hamatissa, silloin kuin hän meni asettamaan sotajoukkoansa Phratin veden tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Ja David voitti häneltä tuhannen vaunua, seitsemäntuhatta hevosmiestä ja kaksikymmentätuhatta jalkamiestä. Ja David raiskasi kaikki vaunut, ja piti heistä tallella sata vaunua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Ja Syrialaiset Damaskusta tulivat Hadareserin Zoban kuninkaan apuun; mutta David löi Syrialaisista kaksikolmattakymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Ja David asetti vartiat Syrian Damaskuun, niin että Syrialaiset tulivat Davidin alamaisiksi ja veivät hänelle lahjoja; sillä Herra autti Davidia, kuhunka ikänä hän vaelsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Ja David otti ne kultaiset kilvet, jotka olivat Hadareserin palvelioilla, ja vei ne Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Otti myös David Hadareserin kaupungeista Tibehatista ja Kunista juuri paljon vaskea, josta Salomo teki vaskimeren, patsaat ja vaskiastioita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Ja kuin Togu Hematin kuningas kuuli Davidin lyöneen kaiken Hadareserin Zoban kuninkaan sotajoukon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Lähetti hän poikansa Hadoramin kuningas Davidin tykö, tervehtimään häntä ystävällisesti ja siunaamaan häntä, että hän Hadareserin kanssa sotinut ja hänen lyönyt oli; sillä Togulla oli sota Hadareserin kanssa: niin myös kaikellaisia kultaisia, hopiaisia ja vaskisia asioita (lähetti hän).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Ja kuningas David pyhitti ne Herralle sen sen hopian ja kullan kanssa, jonka hän oli ottanut kaikilta pakanoilta, Edomilaisilta, Moabilaisilta, Ammonin lapsilta, Philistealaisilta ja Amalekilaisilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Ja Abisai Zerujan poika löi Suolalaaksossa Edomilaisista kahdeksantoistakymmentä tuhatta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'Ja asetti vartiat Edomiin, niin että kaikki Edomilaiset olivat Davidin alamaiset; sillä Herra autti Davidia, kuhunka ikänä hän vaelsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Ja niin hallitsi David kaiken Israelin, ja hän teki oikeuden ja hurskauden kaikelle kansallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab Zerujan poika oli sotajoukon päällä, Josaphat Ahiludin poika oli kansleri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Zadok Ahitobin poika ja Abimelek Abjatarin poika olivat papit, Sausa oli kirjoittaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja Jojadan poika oli Kretin ja Pletin päällä. Ja Davidin pojat olivat ensimäiset kuninkaan käsillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Sen jälkeen tapahtui, että Nahas Ammonin lasten kuningas kuoli, ja hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Niin David sanoi: minä osoitan laupiuden Hanunille Nahaksen pojalle; sillä hänen isänsä on tehnyt laupiuden minun kohtaani. Ja David lähetti sanansaattajat lohduttamaan häntä hänen isänsä tähden. Ja Davidin palveliat tulivat Ammonin lasten maalle Hanunin tykö, lohduttamaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Niin sanoivat Ammonin lasten ylimmäiset Hanunille: luuletkos Davidin kunnioittavan isääs sinun silmäis edessä, että hän lähetti lohduttajat sinun tykös? ja eikö hänen palveliansa tulleet sinun tykös tutkistelemaan, kukistamaan ja vakoomaan maata?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Silloin otti Hanun Davidin palveliat, ajeli heidät ja leikkasi puolen heidän vaatteistansa liki kupeisiin asti, ja päästi heidät menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Ja he menivät, ja se tehtiin Davidille tiettäväksi niistä miehistä. Ja hän lähetti heitä vastaan (sillä miehet olivat sangen suuresti häväistyt), ja kuningas sanoi: olkaat siihenasti Jerihossa kuin teidän partanne kasvaa, tulkaat sitte jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Mutta kuin Ammonin lapset näkivät haisevansa Davidin edessä, lähetti Hanun ja Ammonin lapset tuhannen leiviskää hopiaa, palkataksensa vaunuja ja hevosmiehiä Mesopotamiasta ja Syrian Maekasta ja Sobasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Ja he palkkasivat kaksineljättäkymmentä tuhatta vaunua, ja Maekan kuninkaan väkinensä. He tulivat ja sioittivat itsensä Medban eteen. Ja Ammonin lapset kokoontuivat myös kaupungeistansa ja tulivat sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Kuin David sen kuuli, lähetti hän Joabin ulos ja koko sankarein sotajoukon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Ja Ammonin lapset olivat lähteneet ja hankitsivat heitänsä sotaan kaupungin portin edessä; mutta kuninkaat, jotka tulleet olivat, olivat kedolla erinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Kuin Joab näki sodan sekä edessänsä että takanansa nousevan häntä vastaan, valitsi hän kaikki parhaat miehet Israelista ja asetti ne Syrialaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Muun väen antoi hän veljensä Abisain käden alle, ja he varustivat itsensä Ammonin lapsia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Ja hän sanoi: jos Syrialaiset tulevat minua väkevämmäksi, niin tule minun avukseni; ja jos Ammonin lapset tulevat sinua väkevämmäksi, niin minä autan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Ole miehuullinen, ja olkaamme vahvat kansamme edestä ja Jumalamme kaupunkein edestä: mutta Herra tehköön niinkuin hänelle otollinen on!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Ja Joab lähestyi sillä väellä, joka hänen kanssansa oli, sotimaan Syrialaisia vastaan; ja ne pakenivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Kuin Ammonin lapset näkivät Syrialaisten pakenevan, pakenivat hekin Abisaita hänen veljeänsä ja menivät kaupunkiin; ja Joab meni Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Kuin Syrialaiset näkivät itsensä Israelilta lyödyksi, lähettivät he sanansaattajat ja toivat Syrialaiset tuolta puolelta virtaa. Ja Sophak Hadareserin sodanpäämies meni heidän edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Kuin se oli Davidille sanottu, kokosi hän koko Israelin ja meni Jordanin ylitse. Ja kuin hän tuli heidän tykönsä, asettui hän heitä vastaan; ja David asetti itsensä Syrialaisia vastaan sotaan, ja ne sotivat hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Mutta Syrialaiset pakenivat Israelia. Ja David tappoi Syrialaisista seitsemäntuhatta vaunua ja neljäkymmentä tuhatta jalkamiestä, hän tappoi myös Sophakin sodanpäämiehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Ja koska Hadareserin palveliat näkivät itsensä lyödyksi Israelilta, tekivät he rauhan Davidin kanssa, ja olivat hänen palveliansa; ja Syrialaiset ei tahtoneet enää auttaa Ammonin lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Ja kuin ajastaika kulunut oli siihen aikaan kuin kuninkaat lähtevät ulos, johdatti Joab sotajoukon ja hävitti Ammonin lasten maan, tuli ja piiritti Rabban; mutta David oli Jerusalemissa. Ja Joab löi Rabban ja kukisti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Ja David otti heidän kuninkaansa kruunun hänen päästänsä ja löysi sen painavan leiviskän kultaa, ja siinä oli kalliita kiviä, ja se pantiin Davidin päähän. Hän toi myös sangen paljon saalista kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Mutta väen, joka siellä oli, toi hän ulos ja siirsi heidät sahoihin ja rautahaudoille ja kirvestöihin. Niin teki David kaikkein Ammonin lasten kaupunkein kanssa. Ja David palasi sitte kaiken väen kanssa Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Sitte nousi sota taas Gaserissa Philistealaisten kanssa. Silloin löi Sibbekai Husatilainen Sippain, joka oli Raphan lapsia, ja he lannistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Ja vielä nousi sota Philistealaisten kanssa. Silloin löi Elhanan Jairin poika Lahemin Goljatin Gatilaisen veljen, jonka keihään varsi oli niinkuin kankaan puu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Ja taas nousi sota Gatissa; siellä oli suuri mies, ja hänellä oli kuusi sormea ja kuusi varvasta, se on neljäkolmattakymmentä. Ja hän myös oli syntynyt Raphan pojista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Ja hän pilkkasi Israelia; mutta Jonatan Simean poika, Davidin veljen poika, löi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Nämät olivat syntyneet Raphalle Gatissa; ja he lankesivat Davidin käden ja hänen palveliainsa kätten kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Ja saatana seisoi Israelia vastaan ja kehoitti Davidin lukemaan Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Ja David sanoi Joabille ja kansan ylimmäisille: menkäät ja lukekaat Israel Bersebasta Daniin saakka, ja tuokaat minulle, että minä tietäisin heidän lukunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Joab sanoi: Herra enentäköön kansansa sata kertaa suuremmaksi kuin se nyt on. Herrani kuningas, eikö nämät kaikki ole herrani palveliat? miksi siis herrani kysyy sitä? miksi se tulis synniksi Israelille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Mutta kuninkaan sana voitti Joabin. Ja Joab meni ja vaelsi koko Israelin ympäri, ja tuli Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Ja Joab antoi Davidille luetun kansan luvun: ja koko Israelissa oli yksitoistakymmentä kertaa satatuhatta miestä, jotka miekkaa ulos vetivät. Ja Juudassa neljäsataa tuhatta ja seitsemänkymmentä tuhatta miekan vetävää miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Mutta Leviä ja BenJaminia ei hän näiden sekaan lukenut; sillä Joab kauhistui kuninkaan sanasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Mutta asia oli paha Jumalan silmäin edessä; ja hän löi Israelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Ja David sanoi Jumalalle: minä olen raskaasti syntiä tehnyt, että minä sen tehnyt olen: mutta ota palvelias vääryys pois; sillä minä olen sangen tyhmästi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Ja Herra puhui Gadille, Davidin näkiälle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Mene ja puhu Davidille, sanoen: näin sanoo Herra: kolme minä panen sinun etees: valitse yksi niistä, ja minä teen sen sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Ja kuin Gad tuli Davidin tykö, sanoi hän hänelle: näin sanoo Herra: valitse sinulles:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Taikka kolme nälkävuotta, taikka kolmen kuukauden pako vihollistes edessä ja vainollises miekan edessä, että se on käsittävä sinun, eli kolmeksi päiväksi Herran miekka ja ruttotauti maalle, niin että Herran enkeli kadottaa kaikki Israelin rajoilla. Niin ajattele siis nyt, mitä minun pitää häntä vastaamaan, joka minun on lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'David sanoi Gadille: minulla on suuri ahdistus; kuitenkin tahdon minä langeta Herran käsiin, sillä hänen laupiutensa on sangen suuri, en tahdo langeta ihmisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Ja Herra antoi ruttotaudin tulla Israeliin, niin että Israelista lankesi seitsemänkymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Ja Jumala lähetti enkelin Jerusalemiin hukuttamaan sitä; ja hukuttaissa katsoi Herra siihen ja katui sitä pahaa, ja sanoi enkelille, joka hukutti: nyt on kyllä, pidä kätes ylös! Mutta Herran enkeli seisoi Ornanin Jebusilaisen riihen tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Ja David nosti silmänsä ja sai nähdä Herran enkelin seisovan maan ja taivaan välillä, ja ulosvedetyn miekan hänen kädessänsä ojennetun Jerusalemin päälle. Niin lankesi David ja vanhimmat kasvoillensa, puetetut säkeillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Ja David sanoi Jumalalle: enkö minä se ole, joka annoin lukea kansan? minä se olen, joka syntiä tein ja aivan pahoin tein. Mitä nämät lampaat tehneet ovat? Herra Jumalani, anna kätes olla minun ja minun isäni huoneen päälle, ja ei sinun kansalles vaivaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Ja Herran enkeli sanoi Gadille että hän sanois Davidille, että David menis ja rakentais Herralle alttarin Ornanin Jebusilaisen riiheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Ja David meni Gadin sanan jälkeen, jonka hän Herran nimeen puhunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Vaan kuin Ornan käänsi itsensä ja näki neljän poikansa kanssa enkelin, lymyttivät he heitänsä; sillä Ornan tappoi nisuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Kuin David meni Ornanin tykö, näki Ornan ja havaitsi Davidin, ja meni riihestä ulos ja lankesi kasvoillensa Davidin eteen maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Ja David sanoi Ornanille: anna minulle sen riihen sia, rakentaakseni siihen Herralle alttarin; anna se minulle täyden rahan edestä, että vitsaus lakkais kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ja Ornan sanoi Davidille: ota sinulles ja tee, herrani kuningas, kuin sinulle kelpaa. Katso, minä annan myös härkiä polttouhriksi ja aseita puiksi, ja nisuja ruokauhriksi: kaikki minä annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Mutta kuningas David sanoi Ornanille: ei niin, vaan minä tahdon peräti ostaa sen täydellä rahalla; sillä en minä ota sitä, mikä sinun on, Herralle ja tee polttouhria maksamata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Niin David antoi Ornanille sen sian edestä kuudensadan siklin painon kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Ja David rakensi siinä Herralle alttarin ja uhrasi polttouhria ja kiitosuhria, ja rukoili Herraa; ja hän kuuli hänen tulella taivaasta polttouhrin alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Ja Herra sanoi enkelille, että hän pistäis miekkansa tuppeensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Kuin David näki Herran kuulleeksi häntä Ornanin Jebusilaisen riihessä, uhrasi hän siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Sillä Herran maja, jonka Moses oli tehnyt korvessa, ja polttouhrin alttari olivat silloin Gibeonin korkeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Ja ei David taitanut mennä sen eteen kysymään Jumalaa; sillä hän oli peljästynyt Herran enkelin miekkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Ja David sanoi: tässä pitää oleman Herran huone, ja tämä alttari Israelin polttouhria varten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Ja David käski koota muukalaiset, jotka Israelin maalla olivat: ne asetti hän kivien vuoliaksi, vuolemaan kiviä Jumalan huoneen rakennukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Ja David valmisti paljon rautaa porttein ovien nauloiksi, ja mitä yhteen naulittaa tarvittiin, ja niin paljo vaskea, ettei se punnittaa taidettu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Ja sedripuita epäluvun; sillä Sidonilaiset ja Tyrolaiset toivat paljon sedripuita Davidille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Ja David ajatteli: minun poikani Salomo on nuori ja heikko, mutta huone, joka pitää Herralle rakettaman, pitää niin suuri oleman, että sen nimi ja kunnia korotetaan kaikissa maissa; sentähden valmistan minä nyt hänelle varaksi. Näin valmisti David paljon ennen kuolemaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Ja hän kutsui poikansa Salomon ja käski hänen rakentaa huoneen Herralle Israelin Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Ja David sanoi Salomolle: poikani, minun mieleni oli rakentaa Herralle minun Jumalalleni huonetta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mutta Herran sana tuli minun tyköni ja sanoi: sinä olet paljon verta vuodattanut ja suurta sotaa pitänyt; sentähden ei sinun pidä rakentaman minun nimelleni huonetta, ettäs niin paljon verta olet vuodattanut maan päälle minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Katso, poika, joka sinulle syntyy, on oleva levollinen mies; sillä minä annan levon kaikilta vihollisiltansa hänen ympärillänsä: sentähden pitää hänen nimensä oleman Salomo; sillä minä annan rauhan ja levon Israelille hänen elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Hänen pitää rakentaman minun nimelleni huoneen, hänen pitää oleman minun poikani, ja minä olen hänen isänsä: ja minä vahvistan hänen valtakuntansa istuimen Israelissa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Niin on nyt, minun poikani, Herra sinun kanssas: sinä menestyt ja rakennat Herralle sinun Jumalalles huoneen, niinkuin hän sinusta puhunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Kuitenkin antakoon Herra sinulle ymmärryksen ja toimen, ja asettakoon sinun Israelia hallitsemaan ja pitämään Herran sinun Jumalas lain!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Silloin sinä menestyt, koskas ahkeroitset pitää niitä säätyjä ja oikeuksia, jotka Herra Moseksen kautta on käskenyt Israelille. Ole vahva ja hyvässä turvassa, älä pelkää, älä myös vavahdu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Katso, minä olen vaivassani valmistanut Herran huoneesen satatuhatta leiviskää kultaa ja tuhannen kertaa tuhannen leiviskää hopiaa, niin myös vaskea ja rautaa määrättömästi (sillä niitä on ylen paljo): minä olen myös toimittanut hirsiä ja kiviä, joihin vielä lisätä taidat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Niin on sinulla paljo työntekiöitä, kivenhakkaajia ja puuseppiä, ja kaikkia taitavia kaikkinaisiin töihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Kullalla, hopialla, vaskella ja raudalla ei ole lukua: nouse siis ja tee se, Herra on sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Ja David käski kaikkia Israelin ylimmäisiä auttamaan poikaansa Salomoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Eikö Herra teidän Jumalanne ole teidän kanssanne ja ole antanut teille levon joka taholta? Sillä hän on antanut maan asujamet minun käsiini, ja maa on voitettu Herran ja hänen kansansa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Sentähden antakaat sydämenne ja sielunne etsiä Herraa teidän Jumalaanne; nouskaat ja rakentakaat Herralle Jumalalle pyhä, kannettaa siihen Herran liitonarkki ja pyhät Jumalan astiat huoneesen, joka Herran nimeen rakennetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Kuin David oli vanha ja elämästä kyllänsä saanut, asetti hän poikansa Salomon Israelin kuninkaaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Ja kokosi kaikki ylimmäiset Israelissa, ja papit ja Leviläiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Että Leviläiset luettaisiin hamasta kolmestakymmenestä ajastajasta ja sen ylitse. Ja heidän lukunsa oli päästä päähän, väkeviä miehiä, kahdeksanneljättäkymmentä tuhatta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Joista oli neljäkolmattakymmentä tuhatta teettäjää Herran huoneessa, ja kuusituhatta virkamiestä ja tuomaria;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Ja neljätuhatta ovenvartiaa ja neljätuhatta niitä, jotka Herralle kiitosta veisasivat kanteleilla, jotka minä pannut olen kiitosta veisaamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Ja David teki järjestyksen Levin lapsille, Gersonille, Kahatille ja Merarille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Gersonilaisia olivat Laedan ja Simei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Laedanin lapset: ensimäinen Jehieli, Setam ja Joel, kolme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Simein lapset: Salomit, Hasiel ja Haran, kolme. Nämät olivat Laedanin isäin ylimmäiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Olivat myös nämät Simein lapset: Jahat, Sina, Jeus ja Beria. Nämät neljä olivat Simein lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahat oli ensimäinen, Sina toinen. Mutta Jeuksella ja Berialla ei ollut monta lasta, sentähden luettiin ne yhdeksi isän huoneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kahatin lapset: Amram, Jitshar, Hebron ja Ussiel, neljä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amramin lapset: Aaron ja Moses. Mutta Aaron eroitettiin, koska oli pyhitetty kaikkein pyhimmälle, hän ja hänen poikansa ijankaikkisesti, kantamaan suitsutusta Herran edessä, ja palvelemaan häntä, ja siunaamaan hänen nimeensä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Ja Moseksen Jumalan miehen lapset luettiin Leviläisten sukukuntain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Moseksen lapset olivat: Gersom ja Elieser.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Gersomin lapset: ensimäinen oli Sebuel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Elieserin lapset: ensimäinen oli Rehabia. Ja Elieserillä ei ollut muita lapsia, vaan Rehabeamin lapsia oli paljon enempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Jitsharin lapset: Selomit ensimäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebronin lapset: Jeria ensimäinen, Amaria toinen, Jahasiel kolmas ja Jakneam neljäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Ussielin lapset: Miika ensimäinen ja Jissia toinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merarin lapset: Maheli ja Musi. Mahelin lapset: Eleasar ja Kis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Mutta Eleasar kuoli, ja ei ollut hänellä poikia, vaan tyttäriä, jotka heidän veljensä Kisin pojat naivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Musin lapset: Maheli, Eder ja Jeremot, kolme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Nämät ovat Levin lapset heidän isäinsä huoneen jälkeen, isäin päämiehet, jotka nimien luvun jälkeen päästä päähän luetut olivat, jotka tekivät viran töitä Herran huoneen palveluksessa, kahdenkymmenen ajastaikaisista ja sen ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Sillä David sanoi: Herra Israelin Jumala, joka on asuva Jerusalemissa ijankaikkisesti, on antanut kansallensa levon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Ja ei Leviläiset tarvinneet kantaa majaa kaikkein hänen kaluinsa kanssa palvelukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Ja Levin lapset luettiin Davidin viimeisten sanain jälkeen Leviläisten sekaan, kahdenkymmenen vuotisista ja sen ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Että heidän piti seisoman Aaronin lasten sivussa palvelemassa Herran huoneessa, kartanoilla ja kammioissa, ja kaikkinaisissa pyhitetyn puhdistuksissa, ja kaikissa viran töissä Herran huoneessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'Ja oleman näkyleipäin, sämpyläjauhoin, ruokauhrein, happamattomain kyrsäin, pannuin, halstarien ja kaikkein vaakain ja mittain päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'Ja seisoman joka aamulla, kiittämässä ja ylistämässä Herraa, niin myös ehtoolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Ja uhraamassa Herralle kaikkinaiset polttouhrit sabbateina, uudelle kuulla ja juhlapäivinä, luvun ja tavan jälkeen, alati Herran edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Ja ottamassa vaarin seurakunnan majasta ja pyhyyden vartiosta, ja Aaronin lasten heidän veljeinsä vartiosta, Herran huoneen palveluksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Mutta tämä oli Aaronin lasten järjestys: Aaronin pojat oli: Nadab, Abihu, Eleasar ja Itamar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Mutta Nadab ja Abihu kuolivat isänsä edessä, ja ei heillä ollut lasta. Ja Eleasar ja Itamar tulivat papeiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Ja David määräsi heitä näin: Zadokin Eleasarin lapsista ja Ahimelekin Itamarin lapsista, heidän virkansa jälkeen heidän palveluksessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Ja usiammat väkevät päämiehet löydettiin Eleasarin kuin Itamarin lapsista, koska he heitä niin määräsivät: Eleasarin lapsista oli siellä kuusitoistakymmentä ylimmäistä heidän isäinsä huoneessa, ja kahdeksan Itamarin lapsista, heidän isäinsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Ja he määräsivät heitä arvalla sekä näitä että niitä; sillä molemmat Eleasarin ja Itamarin lapset olivat päämiehet pyhässä ja päämiehet Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Ja Semaja kirjoittaja, Netaneelin poika Leviläisistä, kirjoitti heidät kuninkaan edessä, ja päämiesten ja papin Zadokin, ja Ahimelekin Abjatarin pojan, ja pappein ja Leviläisten, ja ylimmäisten isäin edessä: yksi isän huone otettiin Eleasarin edestä ja toinen otettiin sitte Itamarin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Ja ensimäinen arpa lankesi Jojaribin päälle, toinen Jedatjan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Kolmas Harimin, neljäs Seorimin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Viides Malkian, kuudes Mijamin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Seitsemäs Hakkotsin, kahdeksas Abian,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Yhdeksäs Jesuan, kymmenes Sekanian,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Yksitoistakymmenes Eliasibin, kaksitoistakymmenes Jakimin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Kolmastoistakymmenes Huppan, neljästoistakymmenes Jesebabin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Viidestoistakymmenes Bilgan, kuudestoistakymmenes Immerin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Seitsemästoistakymmenes Hesirin, kahdeksastoistakymmenes Happitsetsin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Yhdeksästoistakymmenes Petahian, kahdeskymmenes Jeheskelin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Ensimäinenkolmattakymmentä Jakinin, toinenkolmattakymmentä Gamulin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Kolmaskolmattakymmentä Delajan, neljäskolmattakymmentä Maasian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Tämä on heidän järjestyksensä heidän virkansa jälkeen, menemään Herran huoneesen tapansa jälkeen, isänsä Aaronin käden alla; niinkuin Herra Israelin Jumala heidän oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Muiden Levin lasten seassa oli Amramin lapsista Subael, Subaelin lapsista Jehdeja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Rehabian lapsista: Jissia oli heistä ensimäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Mutta Jitseharilaisista oli Selomot, Selomotin lapsista Jahat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, '(Hebronin lapset) Jerija ensimäinen, Amaria toinen, Jahasiel kolmas, Jekameam neljäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Ussielin lapset: Miika. Miikan lapsista Samir.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Jesija oli Miikan veli; Jesijan lapsista Sakaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merarin lapset: Maheli ja Musi; Jaesijan hänen poikansa lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Merarin lapset Jaesijasta, hänen poikansa oli Soham, Sakkur ja Ibri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Mutta Mahelilla oli Eleasar, ja hänellä ei ollut yhtään poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Kisistä, Kisin lapset: Jerahmeel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Musin lapset: Maheli, Eder ja Jeremot. Ne ovat Leviläisten lapset heidän isäinsä huoneen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Ja nämät myös heittivät arpaa veljeinsä Aaronin lasten kanssa kuningas Davidin edessä, ja Zadokin ja Ahimelekin, ja ylimmäisten isäin edessä, pappein ja Leviläisten seassa; ylimmäinen isäin seassa pienimmänkin veljensä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Ja David sodanpäämiesten kanssa eroitti virkoihin Asaphin, Hemanin ja Jedutunin lapset, jotka propheterasivat harpuilla, psaltareilla ja symbaleilla. Ja he luettiin töihin heidän virkansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Asaphin lapsista: Sakkur, Joseph, Netania, Asarela, Asaphin pojat, Asaphin käden alla, jotka ennustivat kuninkaan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Jedutunista, Jedutunin lapset: Gedalia, Zeri, Jesaja, Hasabia ja Mattitia, kuusi isänsä Jedutunin johdon alla harpuilla, jotka ennustivat, kiittivät ja ylistivät Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Hemanista: Hemanin lapset, Bukkia, Mattania, Ussiel, Sebuel ja Jerimot, Hanania, Hanani, Eliata, Giddalti ja Romamtieser, Josbekaja, Malloti, Hotir, Mahasiot;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Nämät olivat kaikki Hemanin lapset, kuninkaan näkiän Jumalan sanassa, ylentämään sarvea; sillä Jumala oli antanut Hemanille neljätoistakymmentä poikaa ja kolme tytärtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Nämät kaikki olivat isänsä käden alla, veisaamassa Herran huoneessa symbaleilla, psaltareilla ja harpuilla, Jumalan huoneen virassa, kuninkaan, Asaphin, Jedutunin ja Hemanin asetuksen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Ja heidän ja heidän veljeinsä luku kaikki yhteen, jotka olivat oppineet ja ymmärtäväiset Herran veisussa, oli kaksisataa ja kahdeksanyhdeksättäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Ja heittivät arpaa vartioistansa niin pieni kuin suuri, ja oppinut niinkuin opetuslapsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Ja ensimäinen arpa lankesi Asaphin Josephille, toinen Gedalialle ja hänen veljillensä ja pojillensa: ja heitä oli kaksitoistakymmentä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Kolmas Sakkurin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Neljäs Jitsrin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Viides Netanian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Kuudes Bukkian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Seitsemäs Jesarelan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Kahdeksas Jesaian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Yhdeksäs Mattanian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Kymmenes Simein, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Ensimäinentoistakymmentä Asareelin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Toinentoistakymmentä Hasabian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Kolmastoistakymmentä Subaelin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Neljästoistakymmentä Mattitjan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Viidestoistakymmentä Jeremotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Kuudestoistakymmentä Hananian, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Seitsemästoistakymmentä Josbekasan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Kahdeksastoistakymmentä Hananin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Yhdeksästoistakymmentä Mallotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Kahdeskymmenes Elijatan, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Ensimäinenkolmattakymmentä Hotirin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Toinenkolmattakymmentä Giddaltin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Kolmaskolmattakymmentä Mahesjotin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Neljäskolmattakymmentä Romamtieserin, hänen poikainsa ja veljeinsä päälle: ja heitä oli kaksitoistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Ovenvartiain järjestyksessä: Korhilaisista oli Meselemia, Koren poika, Asaphin lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meselemian lapset olivat nämät: hänen esikoisensa Sakaria, toinen Jediael, kolmas Sebadia, neljäs Jatniel,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Viides Elam, kuudes Johanan, seitsemäs Eljoenai.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Mutta Obededomin lapset olivat nämät: hänen esikoisensa Semaja, toinen Josabad, kolmas Joa, neljäs Sakar, viides Netaneel,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Kuudes Ammiel, seitsemäs Isaskar, kahdeksas Pegultai; sillä Jumala oli siunannut hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Ja hänen poikansa Semaja siitti myös poikia, jotka isänsä huoneessa hallitsivat; sillä he olivat väkevät sankarit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Semajan lapset: Otni, Rephael, Obed ja Elsabad, jonka veljet olivat väkevät miehet, Elihu ja Semakia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Nämät kaikki olivat Obededomin lapset, he ja heidän lapsensa ja veljensä olivat väkevät miehet virassa: kaksiseitsemättäkymmentä Obededomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemialla oli lapsia ja veljiä, väkeviä miehiä kahdeksantoistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Mutta Hosalla Merarin lapsista oli poikia: kaikkein jaloin oli Simri, vaikka ei hän ollut esikoinen, kuitenkin asetti hänen isänsä hänen päämieheksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Toinen Hilkia, kolmas Tebalia, neljäs Sakaria: kaikki Hosan lapset ja veljet kolmetoistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Tämä on ovenvartiain järjestys väkeväin päämiesten seassa, vartioissa heidän veljeinsä kohdalla, palvelemaan Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Ja arpa oli heitetty pienten niinkuin suurtenkin välillä, heidän isäinsä huoneessa, jokaisen portin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Arpa itään päin lankesi Selemian päälle; mutta hänen poikansa Sakaria, joka toimellinen neuvossa oli, heitti arvan, ja hänen arpansa lankesi pohjaan päin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Mutta Obededomin etelään päin, ja hänen poikainsa Asuppimin huoneen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Ja Suppim ja Hosa saivat lännen puolelle, Salleketin portille, josta korkian ahteen päälle mennään, jossa vartiat seisovat toinen toistansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Itään päin oli kuusi Leviläistä, pohjaan päin neljä joka päivä, etelään päin neljä joka päivä, mutta Asuppimin tykönä kaksi ja kaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Parbarin tykönä länteen päin neljä joka haarassa, ja kahdet Parbarin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Tämä on ovenvartiain järjestys, Korhilaisten ja Merarin lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Leviläisistä oli Ahia Jumalan huoneen tavarain päällä ja pyhyyden tavarain päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Laedanin lapset, Gersonin lapset Laedanista: Laedanin Gersonilaisen, isäin päämiehet Jehieliläiset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Jehieliläisten lapset: Setam ja hänen veljensä Joel, Herran huoneen tavarain päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Amramilaisista, Jitseharilaisista, Hebronilaisista ja Ussielilaisista');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Oli Sebuel Gersomin poika, Moseksen pojan poika, päämies tavarain päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Mutta hänen veljellänsä Elieserillä oli poika Rehabia, ja hänen poikansa Jesaja, hänen poikansa Joram, hänen poikansa Sikri, ja hänen poikansa Selomit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Selomit ja hänen veljensä olivat kaikkein pyhäin tavarain päällä, jotka David kuningas oli pyhittänyt, ja ylimmäiset isät, tuhanten ja satain päämiehet sotajoukon päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Sodasta ja saaliista ovat he pyhittäneet Herran huoneen parannukseksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Kaikki myös mitä näkiä Samuel, ja Saul Kisin poika, ja Abner Nerin poika, ja Joab Zerujan poika olivat pyhittäneet, ja kaikki mitkä pyhitetyt olivat, olivat Selomitin ja hänen veljeinsä käden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Jitseharilaisista olivat Kenania poikinensa asetetut ulkonaisen työn haltiaksi ja tuomariksi Israelissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Hebronilaisia Hasabia ja hänen veljensä, väkevät miehet, tuhannen ja seitsemänsataa, asetetut virkaan Israelissa, tuolla puolella Jordania länteen päin, kaikkinaisiin Herran asioihin ja kuninkaan palvelukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Hebronilaisia oli myös Jerijah, Hebronilaisten päämies, heidän sukukuntainsa ja isäinsä seassa. Ja neljäntenäkymmenentenä kuningas Davidin valtakunnan vuonna etsittiin ja löydettiin heidän seassansa väkevät miehet Gileadin Jaeserissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'Ja hänen veljensä olivat väkevät miehet, kaksituhatta ja seitsemänsataa isäin päämiehiä. Ja David kuningas asetti heitä Rubenilaisten, Gadilaisten ja puolen Manassen sukukunnan päälle, kaikkiin Jumalan ja kuninkaan asioihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Mutta Israelin lapset heidän lukunsa jälkeen olivat: isäin päämiehet, tuhanten ja satain ruhtinaat, ja virkamiehet, jotka ottivat kuninkaasta vaarin, heidän järjestyksensä jälkeen, vaeltamaan sinne ja tänne jokainen kuukautenansa, joka kuukautena ajastajassa; ja jokaisessa joukossa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Ensimäisen joukon päällä ensimäisenä kuukautena oli Jasobeam Saddielin poika, ja hänen joukossansa neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Mutta Peretsin lapsista oli ylimmäinen kaikkein sodanpäämiesten päällä, ensimäisenä kuukautena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Toisen kuukauden joukon päällä oli Dodai Ahohilainen, ja Miklot päämies hänen joukkonsa päällä, ja hänen joukossansa neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Kolmannen joukon päämies kolmantena kuukautena oli Benaja papin Jojadan poika, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Tämä on Benaja väkevä kolmenkymmenen seassa ja kolmenkymmenen päällä, ja hänen joukkonsa oli hänen poikansa Ammisabadin alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Neljäs, neljäntenä kuukautena, oli Asahel Joabin veli, ja hänen jälkeensä Sebadia hänen poikansa, ja hänen joukossansa neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Viides, viidentenä kuukautena, oli päämies Samehut Jesrahilainen, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Kuudes, kuudentena kuukautena, oli Ira Ikeksen Thekoalaisen poika, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Seitsemäs, seitsemäntenä kuukautena, oli Heles Pelonilainen Ephraimin lapsia, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Kahdeksas, kahdeksantena kuukautena, oli Sibbekai Hussatilainen Sarhilaisista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Yhdeksäs, yhdeksäntenä kuukautena, oli Abieser Antotilainen Jeminin lapsista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Kymmenes, kymmenentenä kuukautena, oli Maherai Netophatilainen Sarhilaisista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Ensimäinentoistakymmentä, ensimäisenä kuukautena toistakymmentä, oli Benaja Pirtagonilainen Ephraimin lapsista, ja hänen joukossansa oli neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Toinentoistakymmentä, toisena kuukautena toistakymmentä, oli Heldai Netophatilainen Otnielista, ja hänen joukossansa neljäkolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Israelin sukukuntain päällä: Rubenilaisten päämies oli Elieser Sikrin poika; Simeonilaisten seassa Sephatia Maekan poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Leviläisten seassa, Hasabia Kemuelin poika; Aronilaisten seassa Zadok;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Juudan seassa, Elihu Davidin veljistä; Isaskarin seassa, Omri Mikaelin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Sebulonin seassa, Jismaja Obadian poika; Naphtalin seassa, Jerimot Asrielin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Ephraimin lasten seassa, Hosea Asasian poika; puolen Manassen sukukunnan seassa, Joel Pedajan poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Puolen Manassen sukukunnan seassa Gileadissa, Jiddo Sakarian poika; BenJaminin seassa, Jaasiel Abnerin poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Danin seassa, Asareel Jerohamin poika. Nämät ovat Israelin sukukuntain päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Mutta David ei lukenut niitä, jotka kahdenkymmenen vuotiset ja sitä nuoremmat olivat; sillä Herra oli luvannut enentää Israelin niinkuin tähdet taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Mutta Joab Zerujan poika oli ruvennut lukemaan ja ei sitä täyttänyt, ja viha tuli siitä Israelin päälle: ja ei se luku tullut kuningas Davidin aikakirjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Kuninkaan tavarain päällä oli Asmavet Adielin poika, ja tavarain päällä, jotka olivat maalla, kaupungeissa, kylissä ja linnoissa, oli Jonatan Ussian poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Talonpoikain päällä, jotka maata viljelivät, oli Esri Kelubin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Viinamäkein päällä oli Simei Ramalainen; viinakellarein ja viinatavarain päällä Sabdi Siphmiläinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Öljypuiden ja metsäfikunapuiden päällä, jotka olivat laaksossa, oli BaalHanan Gadarilainen; öljytavarain päällä Joas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Laidunhärkäin päällä Saronissa oli Sitrai Saronilainen; mutta härkäin päällä laaksossa Saphat Adlain poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Kamelein päällä Obil Ismaelilainen; aasein päällä Jehedia Meronotilainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Lammasten päällä Jasis Hagarilainen: nämät kaikki olivat päämiehet kuningas Davidin omaisuuden päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Mutta Davidin setä Jonatan oli neuvonantaja, toimellinen mies ja hyvin oppinut. Jehiel Hakmonin poika oli kuninkaan lasten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitophel oli myös kuninkaan neuvonantaja; Husai Arkilainen oli kuninkaan ystävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Ja Ahitophelin jälkeen oli Jojada Benajan poika ja Ebjatar. Mutta Joab oli kuninkaan sodan päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Ja David kokosi kaikki Israelin päämiehet, sukukuntain päämiehet ja niiden joukkoin päämiehet, jotka kuningasta palvelivat, päämiehet tuhanten ja satain päällä, kuninkaan ja hänen poikainsa omaisuuden ja tavaran päämiehet kamaripalveliain kanssa, ja uljaat ja kaikki väkevät sotamiehet Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Ja kuningas David nousi seisoalle ja sanoi: veljeni ja kansani, kuulkaat minua: minä olen aikonut rakentaa Herran liitonarkin lepohuoneen ja Jumalamme jalkain astinlaudan, ja olen valmistanut rakennuksen varaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mutta Jumala sanoi minulle: ei sinun pidä rakentaman nimelleni huonetta; sillä sinä olet sotamies ja olet paljon verta vuodattanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Herra Israelin Jumala on valinnut minun koko isäni huoneesta Israelin kuninkaaksi ijankaikkisesti; sillä hän on Juudan valinnut hallitsiaksi, ja Juudan huoneesta minun isäni huoneen; ja minä olen ollut isäni lapsista hänelle niin kelvollinen, että hän teki minun koko Israelin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Ja kaikkein poikaini seassa (sillä Herra on antanut minulle monta poikaa) on hän valinnut poikani Salomon istumaan Herran valtakunnan istuimella Israelin ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Ja on puhunut minulle: poikas Salomo pitää rakentaman minun huoneeni ja kartanoni; sillä minä olen hänen valinnut pojakseni, ja minä olen hänen isänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Ja vahvistan hänen valtakuntansa ijankaikkisesti, ja hän vahvana pysyy, pitäen minun käskyni ja oikeuteni, niinkuin tänäpänäkin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Nyt siis, koko Herran kokouksen Israelin silmäin edessä ja meidän Jumalamme korvissa, pitäkäät ja tutkistelkaat kaikki Herran teidän Jumalanne käskyt, että te omistaisitte tämän hyvän maan ja jättäisitte sen teidän lapsillenne perinnöksi teidän jälkeenne ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Ja sinä, poikani Salomo! tunne isäs Jumala ja palvele häntä kaikesta sydämestä ja hyvällä mielellä; sillä Herra tutkistelee kaikki sydämet ja ymmärtää kaikkein ajatusten aikomiset; jos etsit häntä, niin sinä löydät hänen; jos hylkäät hänen, niin hän sinun hylkää ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Niin katso nyt, koska Jumala on sinun valinnut rakentamaan huonetta pyhäksi siaksi: ole vahva ja tee niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Ja David antoi pojallensa Salomolle pihan muodon ja hänen huonettensa ja tavarahuoneiden, salien ja sisimäisten kammioin, ja armoistuimen huoneen muodon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Ja vielä kaikkein niiden muodon, jotka hänen mielessänsä olivat, Herran huoneen kartanoista ja kaikista huoneista ympäri, Jumalan huoneen tavaroista ja pyhitetyistä tavaroista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'Pappein ja Leviläisten järjestyksen, ja kaikkein Herran huoneen virkain töiden, ja kaikkein astiain muodon, Herran huoneen palveluksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Kultaa hän antoi kullan painon jälkeen kaikkinaisiksi astioiksi joka virassa, antoi myös hopiaa jokaiseen hopia-astiaan painonsa, jokaisen virka-astian jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Ja kultaa kultaisille kynttiläjaloille ja kultaisille lampuille, jokaiselle kynttiläjalalle ja hänen lampullensa hänen painonsa. Niin antoi hän myös hopiaa hopiakynttiläjaloille ja heidän heidän lampuillensa, jokaisen kynttiläjalan viran jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Niin myös kultaa näkyleipäin pöydiksi, jokaiselle pöydälle painonsa, ja myös hopiaa hopiapöydiksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'Ja puhdasta kultaa kolmihaaraisiksi hangoiksi, maljoiksi ja kannuiksi: kultaa myös kultapikareiksi, jokaiselle pikarille painonsa, hopiaa hopiapikareiksi, jokaiselle pikarille painonsa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Ja savu-alttariksi kaikkein puhtaimpaa kultaa painonsa: ja kultaisten Kerubimein ratasten muodon, jotka levittivät siipensä ja peittivät Herran liitonarkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'Kaikki nämät kirjoitettuina Herran kädeltä, joka minun antoi ymmärtää kaikkein töiden muodon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Ja David sanoi pojallensa Salomolle: ole vahva ja miehuullinen, ja tee niin, älä pelkää, älä myös hämmästy; sillä Herra Jumala minun Jumalani on sinun kanssas, ja ei ota kättänsä pois sinulta, eikä hylkää sinua, siihenasti ettäs kaiken viran työt Jumalan huoneessa päättänyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Ja katso, pappein ja Leviläisten järjestykset pitää oleman kaikessa Jumalan huoneen palveluksessa ja sinun kanssas on hyväntahtoisia ja ymmärtäväisiä kaikkeen virkaan; niin myös päämiehet ja kaikki kansa, kaikissa sinun asioissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Ja kuningas David sanoi koko joukolle: Salomon, yhden minun pojistani, on Jumala valinnut, joka vielä nuori ja heikko on, mutta työ on suuri; sillä ei se ole ihmisen asumasia, vaan Herran Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Ja minä olen kaikesta voimastani valmistanut Jumalani huoneelle kultaa kultakaluiksi, hopiaa hopiaisiksi, vaskea vaskisiksi, rautaa rautaisiksi, puita puuaseiksi, ja onikin kiviä, kiinniliitetyitä rubineja, monenpilkullisia kiviä, ja kaikkinaisia kalliita kiviä, ja marmorikiviä sangen paljon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Ja olen vielä antanut hyvästä tahdostani Jumalani huoneesen mitä minun omani on, kultaa ja hopiaa, ylitse sen kaiken, minkä minä olen valmistanut pyhän huoneesen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Kolmetuhatta leiviskää ophirin kultaa ja seitsemäntuhatta leiviskää puhdasta hopiaa, silata huonetten seiniä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Kultaa kultaisiin, ja hopiaa hopiaisiin ja kaikkinaisiin töihin, tekiäin käden kautta. Ja kuka on hyväntahtoinen täyttämään kättänsä tänäpänä Herralle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Niin isäin päämiehet ja Israelin sukukuntain päämiehet, niin myös tuhanten ja satain päämiehet, ja kuninkaan töiden päämiehet olivat hyväntahtoiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Ja antoivat Jumalan huoneen palvelukseen viisituhatta leiviskää kultaa, ja kymmenentuhatta kultapenninkiä, ja kymmenentuhatta leiviskää hopiaa, kahdeksantoistakymmentä tuhatta leiviskää vaskea, ja satatuhatta leiviskää rautaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Ja joiden tyköä kiviä löydettiin, ne he antoivat Herran huoneen tavaroihin, Jehielin Gersonilaisen käden alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Ja kansa iloitsi, että he niin hyvästä tahdosta antoivat; sillä he antoivat Herralle vaasta sydämestä, vapaasta tahdostansa. Ja kuningas David oli myös sangen suuresti iloissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Ja David kiitti Herraa kaiken kansan edestä ja sanoi: kiitetty ole sinä Herra, Israelin meidän isämme Jumala ijankaikkisesta ijankaikkiseen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Sillä sinun, Herra, on suuruus, ja voima, ja kunnia, ja voitto, ja kiitos; sillä kaikki, mitä taivaassa ja maan päällä on, se on sinun. Sinun Herra on valtakunta, ja sinä olet korotettu kaikkein päämiesten ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Rikkaus ja kunnia ovat sinun edessäs, ja sinä hallitset kaikki kappaleet, ja sinun kädessäs on väki ja voima: sinun kädessäs on kaikki suureksi ja väkeväksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Ja nyt meidän Jumalamme! me kiitämme sinua, ja ylistämme sinun kunnias nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Sillä mikä minä olen, ja mikä on minun kansani, että me olemme niin paljon voineet antaa hyvällä mielellä, niinkuin se nyt tapahtuu? sillä se on kaikki sinulta tullut, ja sinun kädestäs olemme me antaneet sinulle sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Sillä me olemme muukalaiset ja oudot sinun edessäs, niinkuin kaikki meidän isämmekin: meidän ikämme on maan päällä niinkuin varjo, ja ei täällä ole yhtään viipymystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Herra meidän Jumalamme! kaikki tämä kalun paljous, jonka me olemme valmistaneet sinun pyhälle nimelles rakentaa huonetta, se on kaikki tullut sinun kädestäs, ja ne ovat kaikki sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Minun Jumalani! minä tiedän, ettäs tutkistelet sydämen ja tahdot vakuutta. Sentähden olen myös minä kaikki nämät yksivakaisesta sydämestä antanut vapaalla mielellä. Ja minä näin nyt ilolla tämän sinun kansas, joka tässä on, että se on hyvällä mielellä sinulle antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Herra meidän isäimme Abrahamin, Isaakin ja Israelin Jumala! pidä ijankaikkisesti tämänkaltainen mieli ja tahto kansas sydämessä, ja valmista heidän sydämensä sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Ja pojalleni Salomolle anna täydellinen sydän pitämään sinun käskys, todistukses ja säätys, niin että hän ne kaikki tekis ja rakentais tämän asuinsian, jonka minä olen valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Ja David sanoi kaikelle kansalle: kiittäkäät Herraa teidän Jumalaanne! ja kaikki kansa kiitti Herraa isäinsä Jumalaa, kumarsivat ja rukoilivat Herraa ja kuningasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Ja he uhrasivat Herralle uhrin, ja toisena päivänä uhrasivat he polttouhrin Herralle, tuhannen mullia, tuhannen oinasta, tuhannen karitsaa, ja heidän juomauhrinsa, ja monta muuta uhria kaiken Israelin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Ja he söivät ja joivat sinä päivänä sangen suurella ilolla Herran edessä, ja tekivät Salomon Davidin pojan toisen kerran kuninkaaksi ja voitelivat hänen Herralle hallitsiaksi ja Zadokin papiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Ja niin Salomo istui Herran istuimelle kuninkaaksi isänsä Davidin siaan, ja oli onnellinen; ja koko Israel oli hänelle kuuliainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Niin myös kaikki päämiehet ja voimalliset, ja kaikki kuningas Davidin lapset antoivat itsensä kuningas Salomon alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Ja Herra teki Salomon enemmin ja enemmin suuremmaksi kaiken Israelin edessä, ja antoi hänelle kuuluisan valtakunnan, jonkakaltaista ei yhdelläkään kuninkaalla Israelissa hänen edellänsä ole ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Ja niin oli David, Isain poika, koko Israelin kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Mutta aika, jonka hän oli Israelin kuninkaana, oli neljäkymmentä ajastaikaa. Hebronissa hän hallitsi seitsemän ajastaikaa ja Jerusalemissa kolmeneljättäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Ja hän kuoli hyvällä ijällä, ravittuna elämästä, rikkaudesta ja kunniasta; ja hänen poikansa Salomo tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Mutta kuningas Davidin teot ensimäiset ja viimeiset, katso, ne ovat kirjoitetut näkiän Samuelin teoissa, ja prophetan Natanin teoissa, ja näkiän Gadin teoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Kaiken hänen valtakuntansa, väkevyytensä ja aikainsa kanssa, jotka hänen ja Israelin, ja kaikkein maan valtakuntain aikana kuluneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Ja Salomo Davidin poika vahvisti itsensä valtakuntaansa; ja Herra hänen Jumalansa oli hänen kanssansa ja teki hänen aina suuremmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Ja Salomo puhui koko Israelin kanssa tuhanten ja satain päämiesten kanssa, tuomarein ja kaikkien esimiesten kanssa Israelissa, ja ylimmäisten isäin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Ja he menivät, sekä Salomo että koko joukko korkeudelle, joka oli Gibeonissa; sillä siellä oli Jumalan seurakunnan maja, jonka Moses Herran palvelia teki korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Mutta Jumalan arkin oli David vienyt Kirjatjearimista sinne, johon David oli sille sian valmistanut; sillä hän oli rakentanut sille majan Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Ja vaskialttari, jonka Betsaleel Urin poika Hurin pojan poika rakentanut oli, oli siellä Herran asuinsian edessä. Ja Salomo ja koko joukko etsivät sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Ja Salomo nousi sinne ylös vaskialttarin tykö Herran eteen, joka siellä seurakunnan majassa oli, ja uhrasi sen päällä tuhannen polttouhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Sinä yönä ilmestyi Jumala Salomolle ja sanoi hänelle: ano, mitä minä sinulle antaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Ja Salomo sanoi Jumalalle: sinä olet tehnyt suuren armon isälleni Davidille, ja olet tehnyt minun hänen siaansa kuninkaaksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Olkoon nyt, Herra Jumala, sanas totinen minun isälleni Davidille; sillä sinä olet tehnyt minun niin paljon kansan kuninkaaksi, kuin tomua on maan päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Niin anna minulle nyt taito ja ymmärrys, käydäkseni tämän kansan edessä ulos ja sisälle; sillä kuka voi tuomita tätä suurta kansaas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Niin sanoi Jumala Salomolle: että se on sinun mielessäs, ja et anonut rikkautta, tavaraa eli kunniaa, eli vihamiestes sieluja, etkä anonut pitkää ikää, vaan anoit taitoa ja ymmärrystä, tuomitakses minun kansaani, joiden kuninkaaksi minä olen sinun pannut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Niin olkoon sinulle taito ja ymmärrys annettu: vielä sitte annan minä sinulle rikkautta, ja tavaraa ja kunniaa, niin ettei sinun vertaistas kuningasten seassa ennen sinua ole ollut, eikä myös sinun jälkees tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Ja Salomo tuli korkeudelta, joka oli Gibeonissa, Jerusalemiin, seurakunnan majasta, ja hallitsi Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Ja Salomo kokosi itsellensä rattaita ja hevosmiehiä, niin että hänellä oli neljäsataa toistatuhatta ratasta ja kaksitoistakymmentä tuhatta hevosmiestä, ja antoi heidän olla rataskaupungeissa ja kuninkaan tykönä Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Ja kuningas toimitti niin että hopiaa ja kultaa oli Jerusalemissa niin paljo kuin kiviäkin, ja sedripuita kuin metsäfikunapuitakin laaksoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Ja Salomolle vietiin hevosia Egyptistä ja kudotuskaluja. Ja kuninkaan kauppamiehet ostivat ne kudotuskalut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Ja he menivät ylös ja veivät ne Egyptistä, ja jokainen ratas maksoi kuusisataa hopiapenninkiä, ja hevonen sata ja viisikymmentä. Ja niin vietiin niitä myös kaikkein Hetiläisten ja Syrian kuninkaiden tykö heidän kättensä kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Ja Salomo aikoi rakentaa Herran nimelle huoneen ja myös valtakunnallensa huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Ja Salomo luki seitsemänkymmentä tuhatta miestä kuormain kantajiksi ja kahdeksankymmentä tuhatta hirtten hakkaajiksi vuorille, ja kolmetuhatta ja kuusisataa teettäjää heidän ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Ja Salomo lähetti kuningas Hiramin tykö Tyroon ja käski hänelle sanoa: niinkuin sinä minun isäni Davidin kanssa teit ja lähetit hänelle sedripuita, rakentaaksensa itsellensä huonetta, jossa hänen asuman piti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Katso, minä rakennan Herran minun Jumalani nimelle huoneen, että se hänelle pyhitettäisiin, suitsutettaa hyvän hajun uhria hänen edessänsä, ja aina valmistettaa näkyleipiä ja polttouhria, aamulla ja ehtoolla, lepopäivinä ja uusilla kuilla, ja Herran meidän Jumalamme juhlina: ijankaikkisesti pitää tämä oleman Israelin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Ja huone, jonka minä rakennan, pitää oleman suuri; sillä meidän Jumalamme on suurempi kaikkia jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Mutta kuka on niin voimallinen, että hän rakentaa hänelle huoneen? sillä taivaat ja taivasten taivaat ei taida käsittää häntä: mikä siis minä olen rakentamaan hänelle huonetta? mutta ainoastaan suitsuttamaan hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Niin lähetä nyt minulle taitava mies työtä tekemään kullasta, hopiasta, vaskesta, raudasta, purpurasta, tulipunaisista ja sinisistä villoista, ja joka taitaa kaivaa, taitavain kanssa, jotka minun tykönäni ovat Juudassa ja Jerusalemissa, jotka minun isäni David on valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Ja lähetä minulle sedripuita ja honkia, ja Heben puita Libanonista; sillä minä tiedän sinun palvelias taitavan hakata puita Libanonissa. Ja katso, minun palveliani pitää oleman sinun palveliais kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Että he valmistaisivat minulle paljon puita; sillä huone, jonka minä rakennan, pitää oleman suuri ja ihmeellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Ja katso, minä annan sinun palvelioilles, hirsimiehille, jotka puita hakkaavat, kaksikymmentä tuhatta koria survottuja nisuja, kaksikymmentä tuhatta koria ohria, ja kaksikymmentä tuhatta batia viinaa, ja kaksikymmentä tuhatta batia öljyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Ja Hiram Tyron kuningas vastasi kirjoituksella ja lähetti Salomolle: koska Herra rakastaa kansaansa, on hän sinun tehnyt heidän kuninkaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Ja Hiram sanoi vielä: kiitetty olkoon Herra Israelin Jumala, joka taivaan ja maan tehnyt on, että hän on antanut kuningas Davidille viisaan, toimellisen ja ymmärtäväisen pojan, joka Herralle huoneen rakentaa ja valtakunnallensa huoneen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Niin lähetän minä nyt taitavan ja toimellisen miehen, jolla ymmärrys on, nimittäin Huramabin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Joka on vaimon poika Danin tyttäristä, ja hänen isänsä on ollut Tyrolainen; hän taitaa työtä tehdä kullasta, hopiasta, vaskesta, raudasta, kivestä, puusta, purpurasta, sinisistä villoista, kalliista liinasta, tulipunaisesta, ja kaikkinaisia kaivaa, ja ajatella ylös kaikkinaisia taitavasti, mitä hänen eteensä pannaan, sinun taitavais kanssa ja herrani kuningas Davidin sinun isäs taitavain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Niin lähettäkään nyt herrani nisuja, ohria, öljyä ja viinaa palvelioillensa, niinkuin hän on sanonut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Niin me hakkaamme puita Libanonissa kaiketi niin paljon kuin sinä tarvitset, ja viemme ne merelle lautoilla Japhoon; anna sinä ne noutaa sieltä Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Ja Salomo luki kaikki muukalaiset Israelin maalla, sen luvun jälkeen, kuin hänen isänsä David ne luki; ja siellä löydettiin sata ja viisikymmentä tuhatta, kolmetuhatta ja kuusisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Ja hän asetti niistä seitsemänkymmentä tuhatta vetäjiksi ja kahdeksankymmentä tuhatta hakkaajiksi vuorella, ja kolmetuhatta ja kuusisataa teettäjiksi, joiden kansaa piti teettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Ja Salomo rupesi rakentamaan Herran huonetta Jerusalemissa, Morian vuorelle, joka Davidille hänen isällensä neuvottu oli, Davidin paikkaan, jonka hän oli valmistanut Ornanin Jebusilaisen luvaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Ja hän rupesi rakentamaan toisena kuukautena, toisena päivänä, neljäntenä valtakuntansa vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Ja Salomo laski perustuksen, Jumalan huonetta rakentaa, ensisti pituudelle kuusikymmentä kyynärää, ja leveydelle kaksikymmentä kyynärää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Mutta esihuoneen pituudelta huoneen leveyden jälkeen kaksikymmentä kyynärää, ja korkeus oli sata ja kaksikymmentä kyynärää; ja hän silasi sen sisältä puhtaalla kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Mutta suuren huoneen peitti hän hongalla ja silasi sen päältä parhaalla kullalla, ja teki siihen päälle palmuin ja käädyin kaltaiset työt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Ja peitti huoneen kalliilla kivillä kaunistukseksi; ja kulta oli Parvaimin kulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Ja hän silasi huoneen kaaret, pihtipielet, seinät ja ovet kullalla, ja antoi leikata Kerubimeja seiniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Teki hän myös kaikkein pyhimmän huoneen, jonka pituus oli kaksikymmentä kyynärää, huoneen leveyden jälkeen, ja hänen leveytensä oli kaksikymmentä kyynärää, ja silasi sen parhaalla kullalla, kuudellasadalla leiviskällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Niin myös nauloihin antoi hän viisikymmentä sikliä kultaa, painon jälkeen; ja silasi salit kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Niin teki hän myös kaikkein pyhimpään huoneeseen kaksi Kerubimia liikkeillä olevalla teolla; ja he silasivat ne kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Ja pituus oli Kerubimein siivillä kaksikymmentä kyynärää; niin että yksi siipi oli viisi kyynärää ja ulottui huoneen seinään, ja toinen siipi oli myös viisi kyynärää ja ulottui hamaan toisen Kerubimin siipeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Niin myös oli toisen Kerubimin siipi viisi kyynärää pitkä ja ulottui huoneen seinään, ja toinen siipi myös oli viisi kyynärää pitkä ja riippui toisessa Kerubimin siivessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Niin että nämät Kerubimein siivet olivat levitettyinä kaksikymmentä kyynärää leveydelle; ja ne seisoivat jalkainsa päällä, ja heidän kasvonsa olivat käännetyt huoneesen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Hän teki myös esiripun sinisistä, purpuraisista ja tulipunaisista villoista ja kalliista liinasta, ja teki Kerubimit siihen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Ja hän teki huoneen eteen kaksi patsasta, viisineljättäkymmentä kyynärää korkiaksi, ja niiden päälle kruunun viisi kyynärää korkian,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Ja käädyin kaltaiset työt kuoriin, ja sovitti ne patsasten päälle, ja teki sata granatin omenaa, ja asetti ne käädytekoin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Ja pystytti patsaat templin eteen, yhden oikialle ja toisen vasemmalle puolelle, ja kutsui sen nimen, joka oikialla puolella oli, Jakin, ja sen nimen, joka vasemmalla puolella oli, Boas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Ja hän teki myös vaskisen alttarin, kaksikymmentä kyynärää pitkän ja kaksikymmentä kyynärää leviän, ja kymmenen kyynärää korkian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Ja hän teki valetun meren, kymmenen kyynärää leviän toisesta reunasta niin toiseen, ympyriäiseksi, viisi kyynärää korkian; ja juonne kävi ympäri, kolmekymmentä kyynärää pitkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Ja härkäin kuvat olivat sen alla, kiertäen sitä yltympäri; kymmenen kyynärää, piiritti ne meren ympärinsä, kaksi riviä valettuja härkiä oli siinä samaa valantoa kuin sekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Ja se seisoi kahdentoistakymmenen härjän päällä, että kolme kääntyivät heistä pohjoiseen päin, kolme länteen, kolme etelään ja kolme itään päin, ja meri oli ylhäällä heidän päällänsä, ja kaikki heidän takaiset puolensa olivat sisälle päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Ja se oli kämmenen leveyttä paksu, ja hänen reunansa niinkuin maljan reuna ja kuin kukoistava kukkainen, ja se veti kolmetuhatta batia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Ja hän teki kymmenen kattilaa, ja pani niistä viisi oikialle puolelle ja viisi vasemmalle, että niissä pestäisiin kaikkia niitä, kuin polttouhriksi tarvittiin, ja niihin heitettäisiin; mutta meren, pappein pestä itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Ja hän teki myös kymmenen kultaista kynttilänjalkaa, niinkuin ne oleman piti, ja pani templiin, viisi oikialle puolelle ja viisi vasemmalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Ja hän teki kymmenen pöytää ja pani templiin, viisi oikialle ja viisi vasemmalle puolelle; ja hän teki sata kultaista maljaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Hän teki myös pappein esihuoneen ja suuren esihuoneen, ja esihuoneen ovet, ja silasi ovet vaskella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Ja pani meren oikialle sivulle, itään ja etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Ja Huram teki patoja, lapioita ja maljoja. Ja niin Huram lopetti sen työn, jonka hän teki kuningas Salomolle Jumalan huoneesen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Kaksi patsasta, ja kaksi ympyriäistä kruunua kahden patsaan päällä, ja kaksi verkkoa peittämään kahta ympyriäistä kruunua, jotka patsasten päässä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Ja neljäsataa granatin omenaa oli niiden kahden verkon päällä, kaksi riviä granatin omenia kunkin verkon päällä, peittämään kahta ympyriäistä kruunua, jotka olivat patsasten päässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Ja hän teki istuimia, teki myös kattiloita istuinten päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Ja meren ja kaksitoistakymmentä härkää sen alle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Siihen myös patoja, lapioita ja hankoja; ja kaikki heidän astiansa teki Huramabi kuningas Salomolle Herran huoneeseen puhtaasta vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Jordanin kedolla antoi kuningas ne valaa savisessa töyrässä, Sukkotin ja Saredatan vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Ja Salomo teki kaikki nämät astiat suuressa paljoudessa; sillä ei vasken painoa kysytty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Ja Salomo teki kaikki astiat Jumalan huoneesen, niin myös kultaisen alttarin ja pöydät, näkyleipiä pidettää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Kynttiläjalat lamppuinensa puhtaasta kullasta, palamaan kuorin edessä soveliaasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'Ja kukkaiset ja lamput, ja kynttilän niistimet olivat kullasta: ne olivat kokonansa kullasta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Ja veitset, maljat, lusikat ja sammuttimet olivat puhtaasta kullasta, ja läpikäytävä, ja hänen ovensa sisimäiseltä puolelta sitä kaikkein pyhintä, ja ovet templin huoneesen olivat kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Ja kuin kaikki työ täytettiin minkä Salomo teki Herran huoneesen, niin antoi Salomo sinne tuottaa kaikki, mitä hänen isänsä David pyhittänyt oli: hopian, kullan, ja kaikki astiat, ja pani ne Jumalan huoneen tavarain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Silloin kutsui Salomo kaikki vanhimmat Israelissa kokoon, ja kaikki sukukuntain päämiehet, Israelin lasten isäin esimiehet, Jerusalemiin, tuomaan Herran liitonarkkia Davidin kaupungista, se on Zion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Ja kaikki Israelin miehet kokoontuivat kuninkaan tykö juhlapäivinä, joka oli seitsemäntenä kuukautena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Ja kaikki vanhimmat Israelista tulivat; ja Leviläiset nostivat arkin ylös,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'Ja kantoivat arkin ylös ja seurakunnan majan, ja kaikki pyhät astiat, jotka majassa olivat: ne kantoivat papit ja Leviläiset ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Mutta kuningas Salomo ja kaikki Israelin kokous, joka oli tullut kokoon hänen tykönsä arkin eteen, uhrasivat lampaita ja härkiä niin monta, ettei yksikään lukea eli laskea taitanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Ja papit kantoivat Herran liitonarkin siallensa huoneen kuoriin, kaikkein pyhimpään, Kerubimein siipein alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Niin että Kerubimit levittivät siipensä arkin paikan päälle. Ja Kerubimit peittivät arkin korentoinensa ylhäältä päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Mutta korennot olivat niin pitkät, että niiden päät näkyivät kuorin eteen arkista, mutta ei heitä ulkoiselta puolelta näkynyt; ja ne ovat siellä tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Ja arkissa ei ollut muuta mitään, vaan kaksi taulua, jotka Moses oli sinne pannut Horebissa, Herran tehdessä liittoa Israelin lasten kanssa, kuin he Egyptistä läksivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Ja tapahtui, kuin papit tulivat pyhästä ulos; (sillä kaikki papit, jotka silloin läsnä olivat, pyhittivät itsensä, niin ettei heidän järjestyksestänsä eroitusta pitänyt pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Ja Leviläiset veisaajat kaikki Asaphin, Hemanin, Jedutunin, ja heidän lapsensa ja veljensä, olivat puetetut kalliilla liinavaatteella, soittivat symbaleilla, psaltareilla, harpuilla, ja seisoivat itään päin alttaria, ja heidän tykönänsä sata ja kaksikymmentä pappia, jotka puhalsivat vaskitorviin).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'Ja soittajain ja veisaajain ääni kuului soveliaasti yhteen niinkuin yhden ääni, kiittäin ja kunnioittain Herraa; ja kuin vaskitorven, symbalein ja muiden harppuin ääni hänensä korotti, kiittäissä Herraa, että hän on hyvä, ja hänen laupiutensa pysyy ijankaikkiseen, silloin Herran huone täytettiin pilvellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Niin ettei papit saaneet seisoa ja palvella pilven tähden; sillä Herran kunnia täytti Jumalan huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Silloin sanoi Salomo: Herra on sanonut tahtovansa asua pimeydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Minä tosin rakensin sinulle asuinhuoneen ja sian asuakses ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Ja kuningas käänsi kasvonsa ja siunasi koko Israelin joukkoa; ja kaikki Israelin joukko seisoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Ja hän sanoi: kiitetty olkoon Herra Israelin Jumala, joka suullansa on puhunut isälleni Davidille, ja kädellänsä täyttänyt, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Siitä päivästä, jona minä kansani Egyptin maalta johdatin, en ole minä yhtään kaupunkia valinnut kaikista Israelin sukukunnista, rakentaakseni huonetta minun nimeni asuinsiaksi, enkä ole yhtään miestä valinnut kansani Israelin hallitsiaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Vaan Jerusalemin olen minä valinnut nimeni asuinsiaksi. Ja Davidin olen minä valinnut kansani Israelin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Ja kuin isäni David aikoi rakentaa Herran Israelin Jumalan nimelle huonetta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Sanoi Herra isälleni Davidille: sinä olet aikonut rakentaa minun nimelleni huonetta: sinä olet hyvin tehnyt, ettäs sitä olet aikonut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Ei kuitenkaan pidä sinun rakentaman sitä huonetta, vaan poikas, joka kupeistas tuleva on, rakentaa minun nimelleni huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Niin on Herra vahvistanut sanansa, jonka hän puhunut on; sillä minä olen tullut isäni Davidin siaan, ja istun Israelin istuimella, niinkuin Herra sanonut on, ja olen rakentanut huoneen Herran Israelin Jumalan nimelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Ja minä olen pannut sinne arkin, jossa Herran liitto on, jonka hän Israelin lasten kanssa tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Ja hän seisoi Herran alttarin edessä, koko Israelin kokouksen läsnä ollessa, ja ojensi kätensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Sillä Salomo oli tehnyt vaskikattilan ja pannut sen keskelle esihuonetta, viisi kyynärää pitkäksi ja viisi kyynärää leviäksi, ja kolme kyynärää korkiaksi. Sen tykönä seisoi hän ja lankesi polvillensa kaiken Israelin kokouksen edessä, ja ojensi kätensä taivaasen päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'Ja sanoi: Herra Israelin Jumala! ei ole yhtään jumalaa sinun vertaistas, taivaissa eli maassa: sinä joka pidät liiton ja laupiuden palveliais kanssa, jotka sinun edessäs vaeltavat kaikesta sydämestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Sinä olet pitänyt palvelialles Davidille minun isälleni, mitäs hänelle puhunut olet: suullas olet sinä sen puhunut ja kädelläs täyttänyt, niinkuin se tänäpäivänä tapahtunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Nyt Herra Israelin Jumala, pidä palvelialles Davidille minun isälleni, mitäs hänelle puhunut olet ja sanonut: ei sinusta pidä puuttuman mies minun edessäni, joka Israelin istuimella istuu: ainoastaan että sinun poikas kätkevät tiensä; että he vaeltavat minun laissani, niinkuin sinä minun edessäni vaeltanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Nyt Herra Israelin Jumala, anna sanas tosi olla, jonka sinä palvelialles Davidille puhunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Sillä luuletko Jumalan asuvan ihmisten tykönä maassa? katso, taivas ja taivasten taivaat ei käsitä sinua: kuinkasta se huone sen tekis; jonka minä rakentanut olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Mutta käännä sinuas, Herra minun Jumalani, sinun palvelias rukoukseen ja hänen anomisensa puoleen, kuulemaan sitä anomusta ja rukousta, jonka sinun palvelias rukoilee sinun edessäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Ja että sinun silmäs olisivat avoinna tämän huoneen puoleen yötä ja päivää, sitä paikkaa päin, jostas sanonut olet, tahtovas asettaa sinun nimes sinne ja kuulevas sen rukouksen, jonka sinun palvelias siinä paikassa rukoileva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Niin kuule nyt palvelias ja kansas Israelin rukous, jonka he tässä paikassa rukoilevat, ja kuule se sinun asumises paikasta taivaista, ja koska sinä sen kuulet, niin ole armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Jos joku rikkoo lähimmäistänsä vastaan, ja vala pannaan hänen eteensä, jonka hänen vannoman pitää, ja se vala tulee sinun alttaris eteen tässä huoneessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Että sinä kuulisit taivaissa ja saattaisit palvelioilles oikeuden, kostaisit jumalattomalle ja antaisit hänen tiensä tulla hänen päänsä päälle, julistaen vanhurskaan vanhurskaaksi ja antaen hänelle hänen vanhurskautensa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Jos kansas Israel vihollisiltansa lyödään, että he sinua vastaan rikkoneet ovat, ja he kääntävät itsensä, tunnustaen sinun nimes, rukoilevat ja anteeksi anovat sinun edessäs tässä huoneessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Että sinä kuulisit taivaissa, ja olisit kansas Israelin synneille armollinen, ja antaisit heidän tulla jälleen siihen maahan, jonka heille ja heidän isillensä antanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Jos taivas suljettu on, niin ettei sada, että he sinua vastaan rikkoneet ovat, ja he rukoilevat tässä paikassa ja tunnustavat sinun nimes, kääntyen synneistänsä, sitte kuin sinä heitä kurittanut olet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Että kuulisit taivaissa, ja olisit palveliais ja kansas Israelin rikokselle armollinen, koskas heille olet osoittanut hyvän tien, jota heidän vaeltaman pitää, ja antaisit sateen maalle, jonka kansalles antanut olet perinnöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Kuin kallis aika tulee maalle, eli rutto tulee, eli kuivuus, ruoste, heinäsirkat eli jyvämadot tulevat; taikka jos heidän vihollisensa piirittävät maakunnassa heidän porttinsa, eli kaikkinainen vaiva taikka sairaus tulee:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Kaikki rukoukset, kaikki anomiset, jotka kaikki ihmiset, kaikki sinun kansas Israel, pitävät, koska kukin rangaistuksensa ja murheensa tuntee ja ojentaa kätensä tämän huoneen puoleen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Että kuulisit taivaista asumasias istuimelta, ja olisit armollinen, antaen jokaiselle kaiken hänen tiensä jälkeen, sen jälkeen kuin sinä tunnet hänen sydämensä; sillä sinä ainoastaan tunnet ihmisten lasten sydämet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Että he pelkäisivät sinua, ja vaeltaisivat sinun teissäs joka päivä, niin kauvan kuin he elävät sillä maalla, jonka meidän isillemme antanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Ja jos myös joku muukalainen, joka ei ole sinun kansastas Israelista, tulee vieraalta maalta sinun suuren nimes ja voimallisen kätes, ja ojennetun käsivartes tähden, ja tulee ja rukoilee tässä huoneessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Ettäs kuulisit taivaista asumises istuimelta, ja tekisit kaiken sen, jota muukalainen sinulta anoo; että kaikki kansat maan päällä tuntisivat sinun nimes ja pelkäisivät sinua niinkuin kansas Israel, ja tietäisivät, että sinun nimeäs avuksihuudetaan tässä huoneessa, jonka minä rakentanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Jos sinun kansas lähtee sotaan vihollistansa vastaan sitä tietä, jotas heitä lähettävä olet, ja he rukoilevat sinua sillä tiellä, sitä kaupunkia päin, jonkas valinnut olet, ja sen huoneen puoleen, jonka minä sinun nimelles rakentanut olen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Ettäs kuulisit heidän rukouksensa ja anomisensa taivaista, ja auttaisit heitä heidän oikeuteensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Kuin he rikkovat sinua vastaan (sillä ei yhtään ihmistä ole, joka ei syntiä tee), ja sinä vihastut heidän päällensä, ja annat heitä vihamiestensä alle, vietäviksi vankina johonkuhun maahan kauvas eli lähes;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Ja he tekevät sydämestänsä parannuksen siinä maassa, jossa he vankina ovat, ja he kääntyvät, ja rukoilevat sinua vankeutensa maalla ja sanovat: me olemme rikkoneet, väärin tehneet ja olleet jumalattomat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'Ja kääntyvät sinun tykös kaikesta sydämestänsä, ja kaikesta sielustansa vankeutensa maalla, jossa heitä vankina pidetään, ja he rukoilevat sillä tiellä maansa puoleen, jonka heidän isillensä antanut olet, ja sitä kaupunkia päin, jonka valinnut olet, ja sen huoneen puoleen, jonka minä nimelles rakentanut olen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Ettäs kuulisit heidän rukouksensa ja anteeksi anomisensa taivaista asumasias istuimelta, ja auttaisit heitä oikeuteensa, ja olisit kansalles armollinen, jotka sinua vastaan syntiä tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Niin anna nyt, minun Jumalani, sinun silmäs avoinna olla, ja sinun korvas ottakoon vaarin rukouksesta tässä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Niin nouse nyt, Herra Jumala, sinun lepoos, sinä ja sinun voimas arkki: anna pappis, Herra Jumala, olla puetettuna autuudella, ja anna pyhäs iloita hyvyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Herra Jumala! älä käännä pois sinun voideltus kasvoja: muista sen armon päälle, jonka sinä Davidille sinun palvelialles lupasit!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Ja kuin Salomo oli päättänyt rukouksensa, lankesi tuli taivaasta ja kulutti polttouhrit ja muut uhrit, ja Herran kunnia täytti huoneen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Niin ettei papit saaneet mennä Herran huoneesen, sillä Herran kunnia täytti Herran huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Ja kaikki Israelin lapset näkivät tulen alas lankeevan, ja Herran kunnian huoneen ylitse, ja kumarsivat kasvoilla maahan permannolla, rukoilivat ja kiittivät Herraa, että hän on hyvä ja hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Ja kuningas ja kaikki kansa uhrasivat uhria Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Ja kuningas Salomo uhrasi uhriksi kaksikolmattakymmentä tuhatta härkää, sata ja kaksikymmentä tuhatta lammasta; ja he vihkivät Jumalan huoneen, kuningas ja kaikki kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Mutta papit seisoivat vartioissansa ja Leviläiset Herran veisun kanteleissa, jotka kuningas David oli antanut tehdä Herraa kiitettää, että hänen laupiutensa pysyy ijankaikkisesti, niinkuin David kiitti heidän kättensä kautta. Ja papit puhalsivat vaskitorviin heidän kohdallansa, ja koko Israel seisoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Ja Salomo pyhitti keskikartanon, joka Herran huoneen edessä oli, että hän oli siellä tehnyt polttouhrit ja kiitosuhrin lihavuuden; sillä vaskialttari, jonka Salomo oli antanut tehdä, ei vetänyt kaikkia polttouhria, ruokauhria ja lihavuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Ja Salomo piti siihen aikaan juhlaa seitsemän päivää, ja koko Israel hänen kanssansa, sangen suuri kansanpaljous, Hematin rajasta Egyptin ojaan asti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Ja piti kahdeksantena päivänä päätösjuhlan, sillä he pitivät alttarin vihkimistä seitsemän päivää ja juhlaa myös seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Mutta kolmannella päivällä kolmattakymmentä seitsemännellä kuukaudella laski hän kansan menemään heidän majoillensa, iloiten ja hyvässä mielessä siitä hyvyydestä, jonka Herra Davidille ja Salomolle ja kansallensa Israelille tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Ja näin päätti Salomo Herran huoneen ja kuninkaan huoneen, ja kaiken sen, mikä hänen mieleensä tullut oli, tehdäksensä Herran huoneessa ja hänen huoneessansa: sen hän onnellisesti teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Ja Herra ilmestyi Salomolle yöllä ja sanoi hänelle: minä olen kuullut rukoukses, ja valinnut itselleni tämän sian uhrihuoneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Katso, jos minä suljen taivaan, niin ettei sada, ja katso, jos minä käsken heinäsirkkain syödä maan, eli annan tulla ruton minun kansani sekaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'Ja minun kansani nöyryyttää itsensä, joka minun nimeni jälkeen nimitetty on, ja he rukoilevat ja etsivät minun kasvojani, ja kääntyvät pois pahoilta teiltänsä; niin minä kuulen heitä taivaista, ja annan heidän syntinsä anteeksi, ja parannan heidän maansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Niin minun silmäni ovat auki, ja korvani ottavat heidän rukouksistansa vaarin tässä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Niin olen minä nyt valinnut ja pyhittänyt tämän huoneen, että minun nimeni pitää oleman siinä ijankaikkisesti, ja minun silmäni ja sydämeni pitää oleman siellä ainiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Ja jos sinä vaellat minun edessäni, niinkuin sinun isäs David vaeltanut on, niin ettäs teet kaikki, mitä minä sinulle käskenyt olen, ja pidät minun säätyni ja oikeuteni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Niin minä vahvistan valtakuntas istuimen, niinkuin minä isälles Davidille luvannut olen, sanoen: ei sinulta pidä pois otettaman mies, joka on oleva Israelin hallitsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mutta jos te käännytte pois ja hylkäätte minun säätyni ja käskyni, jotka minä teille antanut olen, menette myös ja palvelette vieraita jumalia, ja kumarratte heitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Niin minä hävitän heitä minun maaltani, jonka minä heille antanut olen; ja tämän huoneen, jonka minä nimelleni pyhittänyt olen, heitän minä pois kasvoini edestä, ja annan sen sananlaskuksi ja jutuksi kaikkein kansain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Ja tätä huonetta, jota kaikkein korkeimmaksi tullut on, pitää kaikkein, jotka käyvät sen ohitse, hämmästymän ja sanoman: miksi Herra näin teki tälle maalle ja tälle huoneelle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Niin sanotaan: että he hylkäsivät Herran isäinsä Jumalan, joka heidät Egyptin maalta oli johdattanut ulos, ja olivat mielistyneet vieraisiin jumaliin, ja rukoilleet ja palvelleet heitä; sentähden on hän saattanut kaiken tämän pahan heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Ja kahdenkymmenen vuoden perästä, sittekuin Salomo rakensi Herran huoneen ja oman huoneensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Rakensi hän myös ne kaupungit, jotka Hiram antoi Salomolle, ja antoi Israelin lapset asua niissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Ja Salomo meni Hematsobaan, ja sai sen allensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Rakensi hän myös Tadmorin korvessa ja kaikki tavarakaupungit, jotka hän rakensi Hematissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Hän rakensi myös ylimmäisen ja alimmaisen Bethoronin sangen vahvoiksi kaupungeiksi, muureilla, porteilla ja salvoilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Ja Baelatin ja kaikki tavarakaupungit, jotka Salomolla olivat, ja kaikki vaunukaupungit ja ratsasmiesten kaupungit, ja kaikki mitä ikänä Salomon mieli oli rakentaa sekä Jerusalemissa että Libanonissa ja koko maassa, joka hänen vallassansa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Ja kaiken sen kansan, joka jäänyt oli Hetiläisistä, Amorilaisista, Pheresiläisistä, Heviläisistä ja Jebusilaisista, jotka ei Israelin lapsia olleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Ja heidän lapsensa, jotka jäivät heistä maalle, joita Israelin lapset ei hävittäneet: ne laski Salomo verollisiksi tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Mutta Israelin lapsista ei tehnyt Salomo yhtään orjaksi työhönsä; vaan he olivat sotamiehet, hänen huovinsa päämiehet, hänen vaunuinsa ja hevosmiestensä päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Ja kuningas Salomon ylimmäiset virkamiesten päämiehet, jotka kansaa hallitsivat, oli kaksisataa ja viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Ja Salomo antoi tuoda Pharaon tyttären ylös Davidin kaupungista siihen huoneesen, jonka hän hänelle rakentanut oli; sillä hän sanoi: emäntäni ei pidä Davidin Israelin kuninkaan huoneessa asuman; sillä se on pyhä, että Herran arkki on siihen tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Sitte uhrasi Salomo Herralle polttouhria Herran alttarilla, jonka hän rakentanut oli esihuoneen eteen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Kunkin uhrin päivänänsä Moseksen käskyn jälkeen, sabbatina, uudella kuulla ja juhlapäivinä, kolmasti vuodessa, makian leivän juhlana, viikkojuhlana ja lehtimajan juhlana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Ja hän asetti papit heidän järjestyksissänsä heidän virkoihinsa, niinkuin hänen isänsä David oli asettanut, ja Leviläiset heidän vartioonsa, kiittämään ja palvelemaan pappein edessä, senjälkeen kuin jokapäivä tarvittiin, ja portinvartiat heidän järjestykseensä, kunkin hänen porttiinsa; sillä David Jumalan mies oli niin käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Ja ei yksikään heistä horjahtanut kuninkaan käskyistä, jotka hän antoi papeille ja Leviläisille, kaikissa asioissa ja tavaroissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Ja kaikki Salomon teot tulivat valmiiksi siitä päivästä, jona Herran huone perustettu oli, siihenasti kuin se oli täytetty; niin että Herran huone täydellisesti valmis oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Silloin meni Salomo Etseongeberiin ja Elotiin, meren rannalle, Edomin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Ja Hiram lähetti hänelle haaksia palveliainsa kätten kautta, jotka taitavat merimiehet olivat; ja he menivät Salomon palveliain kanssa Ophiriin, ja toivat sieltä neljäsataa ja viisikymmentä leiviskää kultaa ja veivät kuningas Salomolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Ja rikkaan Arabian kuningatar kuuli Salomosta sanoman, ja tuli sangen suuren joukon kanssa Jerusalemiin, ja kamelein kanssa, jotka kantoivat yrttejä ja paljon kultaa, ja kalliita kiviä, koettelemaan Salomoa tapauksilla. Ja kuin hän tuli Salomon tykö, puhui hän hänen kanssansa kaikki, mitä hän sydämessänsä aikonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Ja Salomo ilmoitti hänelle kaikki hänen sanansa; ja ei ollut mitään Salomolta salattu, jota ei hän ilmoittanut hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Ja kuin rikkaan Arabian kuningatar näki Salomon taidon ja huoneen, jonka hän rakentanut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Ja ruat hänen pöydällänsä, ja hänen palveliainsa asuinsiat, niin myös hänen palveliainsa viran ja heidän vaatteensa, hänen juomansa laskiat vaatteinensa, ja solan, josta Herran huoneesen käytiin; niin ei hän taitanut itsiänsä enää pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Ja hän sanoi kuninkaalle: se on tosi, minkä minä kuullut olen minun maalleni sinun menostas ja taidostas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Vaan en minä uskonut heidän sanojansa ennenkuin minä itse tulin, ja minun silmäni nähneet ovat: ja katso, ei ole minulle puoliakaan sanottu sinun suuresta taidostas: sinulla on enempi, kuin se sanoma on, jonka minä kuulin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Autuaat ovat sinun miehes, autuaat ovat myös nämät sinun palvelias, jotka joka hetki sinun edessäs seisovat ja kuultelevat taitoas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Herra sinun Jumalas olkoon kiitetty, joka sinuun mielistynyt on, ja pannut sinun istuimellensa Herralle sinun Jumalalles kuninkaaksi. Että Jumala rakastaa Israelia, vahvistaaksensa häntä ijankaikkisesti, on hän sinun asettanut heidän kuninkaaksensa, tekemään oikeutta ja vanhurskautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Ja hän antoi kuninkaalle sata ja kaksikymmentä leiviskää kultaa ja ylen paljon yrttejä ja kalliita kiviä. Ja ei senkaltaisia yrttejä ollut, kuin ne olivat, jotka rikkaan Arabian kuningatar antoi kuningas Salomolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Veivät myös Hiramin ja Salomon palveliat kultaa Ophirista, ja Hebenin puita ja kalliita kiviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Ja Salomo antoi tehdä astuimet Hebenin puista Herran huoneesen ja kuninkaan huoneesen, ja kanteleita ja psaltareita veisaajille. Ei yhtään senkaltaista ennen ollut nähty Juudan maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Ja kuningas Salomo antoi rikkaan Arabian kuningattarelle kaikkia, mitä hän pyysi ja anoi, paitsi sitä, mitä hän kuninkaalle tuonut oli. Ja hän palasi ja matkusti omalle maallensa palvelioinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Ja kulta, joka vuosittain tuotiin Salomolle, oli kuusisataa ja kuusiseitsemättäkymmentä leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Paitsi mitä kauppamiehet ja yrttein myyjät toivat. Ja kaikki Arabian kuninkaat ja maan herrat veivät kultaa ja hopiaa Salomolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Niin antoi kuningas Salomo tehdä kaksisataa kilpeä parhaasta kullasta, niin että kuusisataa kappaletta kultaa tuli jokaiseen keihääseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Teki hän myös kolmesataa vähempää kilpeä parhaasta kullasta, niin että kolmesataa kappaletta kultaa tuli jokaiseen kilpeen. Ja kuningas pani ne Libanonin metsähuoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Ja kuningas teki suuren istuimen elephantin luista ja kultasi sen puhtaalla kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Ja istuimessa oli kuusi astuinta, ja kultainen astinlauta istuimen edessä, ja kaksi käsipuuta molemmin puolin istuinta, ja kaksi jalopeuraa seisoi käsipuiden tykönä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Ja kaksitoistakymmentä jalopeuraa seisoi niillä kuudella astuimella, molemmilla puolilla; senkaltaista ei ole tehty yhdessäkään valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Ja kaikki kuningas Salomon juoma-astiat olivat kullasta, ja kaikki astiat Libanonin metsähuoneessa puhtaasta kullasta; sillä ei hopiaa miksikään luettu Salomon aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Sillä kuninkaan haahdet menivät Tarsikseen Hiramin palveliain kanssa, ja tulivat kerran joka kolmantena vuotena, ja toivat kultaa, hopiaa, elephantin luita, apinoita ja riikinkukkoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Ja kuningas Salomo tuli suuremmaksi kaikkia kuninkaita maan päällä rikkaudessa ja viisaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Ja kaikki kuninkaat maan päällä himoitsivat nähdä Salomon kasvoja ja kuulla hänen taitoansa, jonka Jumala hänen sydämeensä antanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Ja he veivät hänelle kukin lahjansa, hopia-astioita, kulta-astioita, vaatteita, sota-aseita, yrttejä, hevosia ja muuleja, joka vuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Ja Salomolla oli neljätuhatta hevoskorsua ja kaksitoistakymmentä tuhatta ratsasmiestä, ja ne pantiin vaunukaupunkeihin ja kuninkaan tykö Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Ja hän oli kaikkein kuningasten haltia, hamasta virrasta niin Philistealaisten maahan asti, Egyptin maan rajaan saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Ja kuningas saatti niin paljon hopiaa Jerusalemiin kuin kiviä, ja niin paljon sedripuita toimitti hän kuin metsäfikunapuita laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Ja Salomolle vietiin hevosia Egyptistä ja kaikista maakunnista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Mitä enempää Salomon asioista sanomista on, sekä ensimäisistä että viimeisistä: eikö ne ole kirjoitetut Natan prophetan aikakirjassa, ja Ahian Silonilaisen prophetiassa, niin myös Jeddin näkiän näyssä, Jerobeamia Nebatin poikaa vastoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Ja Salomo hallitsi Jerusalemissa koko Israelia neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Ja Salomo nukkui isäinsä kanssa, ja he hautasivat hänen isänsä Davidin kaupunkiin; ja Rehabeam hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Ja Rehabeam meni Sikemiin; sillä kaikki Israel oli tullut Sikemiin tekemään häntä kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Ja kuin Jerobeam, Nebatin poika sen kuuli joka oli Egyptissä, johonka hän oli paennut kuningas Salomon edestä, niin hän tuli Egyptistä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Sillä he lähettivät ja antoivat hänen kutsuttaa. Ja Jerobeam tuli ja kaikki Israel; ja he puhuivat Rehabeamille ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Sinun isäs teki meidän ikeemme ylen kovaksi; niin huojenna nyt isäs kova palvelus ja se raskas ijes, jonka hän laski meidän päällemme, niin me olemme sinun alamaises.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Ja hän sanoi heille: tulkaat minun tyköni jälleen kolmantena päivänä; ja kansa meni pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Ja kuningas Rehabeam kysyi neuvoa vanhimmilta, jotka seisoivat hänen isänsä Salomon edessä hänen eläissänsä, ja sanoi: mitä te neuvotte vastaamaan tätä kansaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'He puhuivat hänen kanssansa ja sanoivat: jos olet tälle kansalle ystävällinen ja suosittelet heitä, puhutellen heitä hyvillä sanoilla, niin he ovat aina sinulle alamaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mutta hän hylkäsi vanhimpain neuvon, jonka he antoivat hänelle, ja piti neuvoa nuorukaisten kanssa, jotka hänen kanssansa kasvaneet olivat ja seisoivat hänen edessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Ja sanoi heille: mitä te neuvotte vastaamaan tätä kansaa, joka minun kanssani puhui ja sanoi: huojenna se ijes, jonka isäs laski meidän päällemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Ja nuorukaiset, jotka olivat kasvaneet hänen kanssansa, puhuivat hänelle ja sanoivat: sano näin kansalle, joka puhui kanssas ja sanoi: isäs teki meidän ikeemme ylen raskaaksi, huojenna sinä se; ja sano heille: minun pienin sormeni pitää oleman paksumpi isäni kupeita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Jos minun isäni on laskenut raskaan ikeen teidän päällenne, niin minä vielä lisään teidän ikeesenne: minun isäni rankaisi teitä ruoskilla, mutta minä skorpioneilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Kuin Jerobeam ja kaikki kansa tulivat jälleen Rehabeamin tykö kolmantena päivänä, niinkuin kuningas puhunut oli, sanoen: tulkaat minun tyköni kolmantena päivänä jälleen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Niin kuningas vastasi heitä kovasti; ja kuningas Rehabeam hylkäsi vanhimpain neuvon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'Ja puhui heidän kanssansa nuorukaisten neuvon jälkeen ja sanoi: isäni on teidän ikeenne raskaaksi tehnyt, mutta minä lisään siihen: isäni on rangaissut teitä ruoskilla, mutta minä skorpioneilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Ja ei kuningas kuullut kansaa; sillä se oli niin asetettu Jumalalta, että Herra tahtoi vahvistaa sanansa, jonka hän puhui Ahian Silonilaisen kautta Jerobeamille Nebatin pojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Ja kuin kaikki Israel näki, ettei kuningas kuullut heitä, niin vastasi kansa kuningasta ja sanoi: mikä osa meillä on Davidissa? Ei meillä ole yhtään perimystä Isain pojassa: kukin majaansa, Israel! niin katso nyt David huonettas! Ja kaikki Israel meni majoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Ja Rehabeam hallitsi ainoastaan niitä Israelin lapsia, jotka asuivat Juudan kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Ja kuningas Rehabeam lähetti Hadoramin matkaan, joka oli veron päällä; mutta Israelin lapset kivittivät hänen kuoliaaksi. Ja kuningas Rehabeam astui nopiasti vaunuun pakenemaan Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Niin luopui Israel Davidin huoneesta tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Ja kuin Rehabeam tuli Jerusalemiin, niin hän kokosi Juudan ja BenJaminin huoneen, sata ja kahdeksankymmentä tuhatta valittua sotamiestä, sotimaan Israelia vastaan, saattaaksensa valtakuntaa Rehabeamille jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mutta Herran sana tuli Semajan Jumalan miehen tykö, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Puhu Rehabeamille, Salomon pojalle, Juudan kuninkaalle, ja kaikelle Israelille, jotka Juudassa ja BenJaminissa ovat, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Näin sanoo Herra: ei teidän pidä nouseman eikä sotiman veljiänne vastaan, vaan palatkaat jokainen kotianne; sillä se on minulta niin tapahtunut. He olivat kuuliaiset Herran sanalle ja palasivat menemästä Jerobeamia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Mutta Rehabeam asui Jerusalemissa, ja rakensi Juudan kaupungit vahvaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Ja rakensi Betlehemin, Etamin ja Tekoan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Betsurin, Sokon, ja Adullamin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gatin, Maresan ja Siphin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraimin, Lakiksen ja Asekan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zorgan, Ajalonin ja Hebronin, jotka olivat kaikkein vahvimmat kaupungit Juudassa ja BenJaminissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Ja hän teki ne vahvaksi ja pani niihin hallitsiat, ja elatuksen varaa, öljyä ja viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'Ja hän toimitti kaikkiin kaupunkeihin kilvet ja keihäät, ja teki ne sangen vahvaksi. Ja Juuda ja BenJamin olivat hänen allansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Ja papit ja Leviläiset kaikesta Israelista tulivat hänen tykönsä kaikista maansa rajoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Sillä Leviläiset hylkäsivät esikaupunkinsa ja saamansa ja tulivat Juudaan ja Jerusalemiin; sillä Jerobeam ja hänen poikansa ajoivat heidät pois, ettei he olisi saaneet tehdä Herralle papin palvelusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Mutta hän asetti papit itsellensä kukkuloille ja perkeleille, ja vasikoille, jotka hän tehdä antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Ja monta kaikista Israelin sukukunnista, jotka sydämestänsä etsivät Herraa Israelin Jumalaa, tulivat heidän perässänsä Jerusalemiin, uhraamaan Herralle isäinsä Jumalalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Ja vahvistivat Juudan valtakunnan, ja vahvistivat Rehabeamin Salomon pojan kolmena ajastaikana; sillä he vaelsivat Davidin ja Salomon tietä kolme ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Ja Rehabeam otti Mahelatin, Jerimotin Davidin pojan tyttären, emännäksensä, niin myös Abihailin, Eliabin tyttären, Isain pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Joka hänelle synnytti nämät pojat: Jeuksen, Semarian ja Sahamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Sitte otti hän Maekan, Absalomin tyttären, joka hänelle synnytti Abian, Attain, Sisan ja Selomitin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Mutta Rehabeam piti Maekan, Absalomin tyttären, rakkaampana kaikkia muita emäntiänsä ja jalkavaimojansa; sillä hänellä oli kahdeksantoistakymmentä emäntää ja kuusikymmentä jalkavaimoa, ja hän siitti kahdeksankolmattakymmentä poikaa ja kuusikymmentä tytärtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Ja Rehabeam asetti Abian, Maekan pojan, veljeinsä pääksi ja hallitsiaksi; sillä hän mieli tehdä hänen kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Ja hän teki toimellisesti ja jakoi poikansa Juudan ja BenJaminin maahan kaikkiin vahvoihin kaupunkeihin, ja antoi heille yltäkyllä viljaa, ja havitteli monta emäntää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Ja kuin Rehabeamin valtakunta tuettu ja hän vahvistettu oli, hylkäsi hän Herran lain, ja kaikki Israel hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Mutta viidentenä kuningas Rehabeamin vuotena meni Sisak Egyptin kuningas ylös Jerusalemiin (sillä he olivat rikkoneet Herraa vastaan),');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Tuhannen ja kahdensadan vaunun ja kuudenkymmenen tuhannen hevosmiehen kanssa; ja se kansa oli lukematoin, jotka häntä seurasivat Egyptistä, Libiasta, Sukimista ja Etiopiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Ja hän voitti ne vahvat kaupungit Juudassa, ja tuli Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Silloin tuli Semaja propheta Rehabeamin ja päämiesten tykö Juudassa, jotka olivat kokoontuneet Sisakin tähden Jerusalemiin, ja sanoi heille: näin sanoo Herra: te olette hyljänneet minun, sentähden olen minä myös hyljännyt teidät Sisakin käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Niin Israelin ylimmäiset nöyryyttivät itsensä kuninkaan kanssa ja sanoivat: Herra on vanhurskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Koska Herra näki heidän nöyryyttävän itsensä, tuli Herran sana Semajan tykö ja sanoi: he ovat itsensä nöyryyttäneet, sentähden en minä heitä kadota, vaan minä annan kohta heille pelastuksen, niin ettei minun vihani vuotais Jerusalemin päälle Sisakin käden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Mutta heidän pitää kuitenkin hänelle alamaiset oleman, että he tietäisivät, mikä se on, palvella minua, ja palvella valtakuntia maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Niin Sisak Egyptin kuningas meni Jerusalemiin ja otti Herran huoneen tavarat ja kuninkaan huoneen tavarat: ne kaikki otti hän pois. Ja hän otti myös ne kultakilvet, jotka Salomo oli tehdä antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Joiden siaan kuningas Rehabeam teetti vaskiset kilvet ja antoi vartiain päämiehille tallelle, jotka kuninkaan huoneen ovea vartioitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Ja niin usein kuin kuningas meni Herran huoneesen, tulivat vartiat ja kantoivat niitä, ja veivät ne sitte jälleen vartiain huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Ja koska hän nöyryytti itsensä, sentähden Herran viha kääntyi hänestä pois, niin ettei hän peräti kadotettu; sillä vielä jotain hyvää löydettiin Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Niin kuningas Rehabeam vahvistui Jerusalemissa, ja hallitsi. Ja Rehabeam oli yhden ajastaikainen viidettäkymmentä tullessansa kuninkaaksi, ja hallitsi Jerusalemissa seitsemäntoistakymmentä ajastaikaa, siinä kaupungissa, jonka Herra kaikista Israelin sukukunnista valinnut oli, asettaaksensa siihen nimensä. Ja hänen äitinsä nimi oli Naema Ammonilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Ja hän teki pahoin, ettei hän valmistanut sydäntänsä Herraa etsimään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Ja Rehabeamin teot, ensimäiset ja viimeiset, eikö ne ole kirjoitetut Semajan prophetan ja Iddon näkiän sanoissa, joissa kirjoitetaan sukukunnat, niin myös Rehabeamin ja Jerobeamin sodat kaikkina aikoina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Ja Rehabeam nukkui isäinsä kanssa ja haudattiin Davidin kaupunkiin; ja hänen poikansa Abia tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Kuningas Jerobeamin kahdeksantena vuotena toistakymmentä tuli Abia Juudan kuninkaaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Ja hallitsi kolme ajastaikaa Jerusalemissa. Hänen äitinsä nimi oli Mikaja, Urielin tytär Gibeasta. Ja sota nousi Abian ja Jerobeamin välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Ja Abia alkoi sodan neljänsadan tuhannen juuri väkevän ja valitun sotamiehen kanssa. Ja Jerobeam valmisti sotaa heitä vastaan kahdeksansadan tuhannen valitun ja urhoollisen sotamiehen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Ja Abia nousi ylös Semaraimin vuorelle, joka oli Ephraimin vuorella, ja sanoi: kuulkaat minua, Jerobeam ja koko Israel!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Ettekö te tiedä Herran Israelin Jumalan antaneeksi Davidille kuninkaan valtakuntaa Israelissa ijankaikkisesti, hänelle ja hänen pojillensa suolaliitolla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mutta Jerobeam Nebatin poika, Salomon Davidin pojan palvelia, nosti kapinan herraansa vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Ja hänen tykönsä kokoontui joutilaita miehiä ja Belialin lapsia, ja he vahvistivat itsensä Rehabeamia Salomon poikaa vastaan; sillä Rehabeam oli nuori ja pehmiä sydämestä, niin ettei hän voinut vahvistaa itsiänsä heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Mutta te ajattelette vahvistaa teitänne Herran valtakuntaa vastaan, joka on Davidin poikain kädessä, että teitä on suuri joukko, ja pidätte kultaisia vasikoita, jotka Jerobeam teille jumaliksi tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Ettekö te ole ajaneet Herran pappeja Aaronin poikia ja Leviläisiä pois, ja olette itse teillenne tehneet pappeja, niinkuin kansat maakunnissa? Jokainen, joka tulee käsiänsä täyttämään nuorella mullilla ja seitsemällä oinaalla, se tulee papiksi niille, jotka ei jumalia ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mutta Herra on meidän Jumalamme, jota emme hylkää; ja papit, jotka Herraa palvelevat, ovat Aaronin pojat, ja Leviläiset ovat heidän työssänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'Ja sytyttävät Herralle polttouhrin joka aamuna ja ehtoona, niin myös yrttein suitsutuksen, ja valmistavat leipiä puhtaalle pöydälle ja kultakynttilänjalan lamppuinensa, niin että ne joka ehtoo sytytetään; sillä me pidämme Herran meidän Jumalamme vartiota; mutta te olette hänen hyljänneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Ja katso, meidän kanssamme on Jumala esipäässä, ja hänen pappinsa pyhillä torvilla soittamassa teitä vastaan. Te Israelin lapset! älkäät sotiko Herraa isäinne Jumalaa vastaan; sillä se ei menesty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Ja Jerobeam asetti väijytyksen ympäri, tullaksensa takaa heidän päällensä, niin että he olisivat itse Juudan edessä ja väijytys heidän takanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Kuin Juuda katsoi ympärinsä, katso, niin oli sota sekä edessä että takana. Niin he huusivat Herran tykö, ja papit soittivat vaskitorvilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Ja joka mies huusi Juudassa. Ja kuin joka mies niin Juudassa huusi, löi Jumala Jerobeamin ja koko Israelin Abian ja Juudan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Ja Israelin lapset pakenivat Juudan edellä, ja Jumala antoi heitä heidän käsiinsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Niin että Abia löi väkinensä heitä suurella lyömisellä. Ja Israelissa lankesi lyötynä viisisataa tuhatta valittua sotamiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Ja niin Israelin lapset nöyryytettiin siihen aikaan, ja Juudan lapset vahvistettiin; sillä he turvasivat Herraan isäinsä Jumalaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Ja Abia ajoi Jerobeamia takaa, ja voitti häneltä kaupungeita; Betelin kylinensä, Jesanan kylinensä ja Ephronin kylinensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Niin ettei Jerobeam enää tullut voimaansa, niinkauvan kuin Abia eli: ja Herra rankaisi häntä, niin että hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Kuin Abia vahvistui, otti hän neljätoistakymmentä emäntää ja siitti kaksikolmattakymmentä poikaa ja kuusitoista tytärtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Mitä enempi Abiasta sanomista on, ja hänen teistänsä ja teoistansa, se on kirjoitettu Iddon prophetan tietokirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Ja Abia nukkui isäinsä kanssa ja he hautasivat hänen Davidin kaupunkiin; ja Asa hänen poikansa tuli kuninkaaksi hänen siaansa. Hänen aikanansa oli maa levossa kymmenen ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Ja Asa teki sitä mikä hyvä ja oikia oli Herran hänen Jumalansa edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Ja otti vieraat alttarit pois ja korkeudet, ja rikkoi patsaat, ja maahan hakkasi metsistöt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Ja sanoi Juudalle, että he etsisivät Herraa, isäinsä Jumalaa, ja tekisivät lain ja käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Ja hän otti pois korkeudet ja epäjumalat kaikista Juudan kaupungeista; ja valtakunta oli levossa hänen allansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Ja hän rakensi vahvat kaupungit Juudassa; sillä maa oli levossa, ja ei ollut sotaa häntä vastaan niinä vuosina; sillä Herra antoi hänelle levon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Ja hän sanoi Juudalle: rakentakaamme nämät kaupungit, ja tehkäämme muurit niiden ympäri, ja tornit, ja portit, ja salvat, niin kauvan kuin maa on meidän edessämme; sillä me olemme etsineet Herraa meidän Jumalaamme, häntä me olemme etsineet, ja hän on antanut meille levon jo joka taholta. Niin he rakensivat, ja se menestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Ja Asalla oli suuri sotajoukko, jotka kantoivat kilpiä ja keihäitä: Juudasta kolmesataa tuhatta, ja BenJaminista, jotka kilpiä kantoivat ja joutsia jännittivät, kaksisataa ja kahdeksankymmentä tuhatta. Ja nämät olivat kaikki väkevät sotamiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Ja Sera Etiopialainen meni heitä vastaan suuren sotajoukon kanssa, jossa oli kymmenen kertaa satatuhatta miestä ja kolmesataa vaunua, ja tuli Maresaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Ja Asa meni häntä vastaan. Ja he hankitsivat sotimaan Zephatan laaksossa Maresan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Ja Asa huusi Herran Jumalansa tykö ja sanoi: Herra! et sinä väliä pidä auttaissas monen kautta, taikka kussa ei yhtäkään voimaa ole. Auta meitä, Herra meidän Jumalamme! sillä me turvaamme sinuun, ja olemme tulleet sinun nimees tätä suurta joukkoa vastaan; sinä olet Herra meidän Jumalamme, ei yksikään ihminen voi mitään sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Ja Herra löi Etiopialaisia Asan ja Juudan edessä, niin että Etiopialaiset pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Ja Asa ja hänen väkensä, jotka olivat hänen kanssansa, ajoivat heitä Gerariin asti takaa. Ja Etiopialaiset kaatuivat, niin ettei yhtään heistä eläväksi jäänyt, vaan he tapettiin Herran ja hänen sotaväkensä edessä. Ja he veivät sieltä paljon saalista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Ja he löivät kaikki kaupungit Gerarin ympäriltä maahan; sillä Herran pelko tuli heidän päällensä. Ja he ryöstivät kaikki kaupungit; sillä niissä oli paljo saalista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Ja he löivät navetat maahan, ja veivät ylen paljon lampaita ja kameleja, ja tulivat jälleen Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Ja Jumalan henki tuli Asarian, Obedin pojan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Ja hän meni Asaa vastaan ja sanoi hänelle: kuulkaat minua, Asa, ja koko Juuda ja Benjamin: Herra on teidän kanssanne, että te olette hänen kanssansa; ja koska te etsitte häntä, antaa hän itsensä teiltä löyttää; mutta jos te hylkäätte hänen, niin hän hylkää myös teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Monta päivää on Israelissa, ettei yhtään oikiaa Jumalaa ole, eikä yhtään pappia, joka opettaa, eli yhtään lakia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Ja kuin he tuskissansa kääntyvät Herran Israelin Jumalan tykö ja etsivät häntä, niin hän löydetään heiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Niinä aikoina ei ole rauhaa niillä, jotka käyvät sisälle ja ulos; sillä suuri meteli tulee kaikkein maan asuvaisten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Ja yksi kansa musertaa toisen, ja yksi kaupunki toisen: sillä Jumala hämmästyttää heitä kaikkinaisilla ahdistuksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Mutta te vahvistakaa teitänne, ja älkäät lievittäkö käsiänne; sillä teidän työllänne on hänen palkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Kuin Asa kuuli nämät sanat ja prophetan Obedin ennustuksen, vahvistui hän, ja otti kauhistukset pois kaikelta Juudan ja Benjaminin maalta, ja kaupungeista, jotka hän oli voittanut Ephraimin vuorelta, ja uudisti Herran alttarin, joka Herran esihuoneen edessä oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Ja kokosi kaiken Juudan ja Benjaminin, ja muukalaiset, jotka heidän tykönänsä olivat Ephraimista, Manassesta ja Simeonista; sillä hänen tykönsä tuli monta Israelista, koska he näkivät Herran hänen Jumalansa olevan hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Ja he tulivat Jerusalemiin kokoon kolmantena kuukautena, Asan valtakunnan viidentenä vuonna toistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'Ja he uhrasivat sinä päivänä Herralle siitä saaliista, jonka he kotiansa tuoneet olivat, seitsemänsataa härkää ja seitsemäntuhatta lammasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Ja He tekivät liiton, että heidän piti etsimän Herraa, isäinsä Jumalaa, kaikesta sydämestänsä ja kaikesta sielustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'Ja kuka ikänä ei tahtonut etsiä Herraa Israelin Jumalaa, hänen piti kuoleman: pienen ja suuren, miehen ja vaimon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Ja he vannoivat Herralle korkealla äänellä, ilohuudolla, vaskitorvilla ja basunilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Ja koko Juuda iloitsi siitä valasta; sillä he olivat vannoneet kaikesta sydämestänsä, ja etsivät häntä kaikesta tahdostansa, ja hän löydettiin heiltä; ja Herra antoi heille levon joka paikassa heidän ympäristöllänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Ja kuningas Asa pani äitinsä Maekan pois vallan päältä; sillä hän oli asettanut Mipletsetin metsistöön. Ja Asa hävitti hänen Mipletsetinsä, ja löi sen rikki ja poltti Kidronin ojan vieressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Mutta korkeudet ei olleet vielä pannut pois Israelista; kuitenkin oli Asan sydän vakaa, niinkauvan kuin hän eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Ja hän antoi tuoda Jumalan huoneesen, mitä hänen isänsä pyhittänyt oli ja mitä hän itse pyhittänyt oli, hopiaa, kultaa ja astioita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Ja ei ollut yhtään sotaa hamaan viidenteenneljättäkymmentä Asan valtakunnan ajastaikaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Asan valtakunnan kuudentena vuonna neljättäkymmentä nousi Baesa Israelin kuningas Juudaa vastaan, ja rakensi Raman, estääksensä Asan Juudan kuninkaan ulos- ja sisällekäymistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Vaan Asa otti Herran huoneen ja kuninkaan huoneen tavaroista hopiaa ja kultaa, ja lähetti Benhadadille Syrian kuninkaalle, joka asui Damaskussa, ja käski sanoa hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Liitto on minun ja sinun vaiheellas, minun ja sinun isäs vaiheella: katso, minä lähetin sinulle hopiaa ja kultaa, ettäs Baesan Israelin kuninkaan liiton särkisit, että hän menis pois minun tyköäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Benhadad oli kuningas Asalle kuuliainen ja lähetti sodanpäämiehet, jotka hänellä olivat, Israelin kaupungeita vastaan; he löivät Ijonin, Danin ja Abelmajimin, ja kaikki Naphtalin jyväkaupungit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Kuin Baesa sen kuuli, lakkasi hän rakentamasta Ramaa ja jätti työnsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Vaan kuningas Asa otti tykönsä koko Juudan, ja he ottivat kivet ja hirret Ramasta, joista Baesa rakensi. Ja hän rakensi niistä Geban ja Mitspan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Siihen aikaan tuli Hanani näkiä Asan Juudan kuninkaan tykö ja sanoi hänelle: koskas turvasit Syrian kuninkaasen ja et turvannut Herraan Jumalaas, sentähden on Syrian kuninkaan väki päässyt pois sinun käsistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Eikö Etiopialaiset ja Libialaiset olleet suuri joukko monien vaunuin ja hevosmiesten kanssa? Kuitenkin, koskas Herraan turvasit, antoi hän heidät sinun käsiis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Sillä Herran silmät katselevat kaikki maat, vahvistaaksensa niitä, jotka pysyvät hänen tykönänsä kaikesta sydämestänsä. Sinä olet tyhmästi tehnyt, sentähden sinun pitää tästedeskin sotia saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Niin Asa vihastui näkiän päälle ja heitti hänen vankeuteen; sillä hän kovin suuttui hänen päällensä tästä asiasta. Ja Asa ahdisti muutamia kansasta siihen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Ja katso, Asan työt, sekä ensimäiset että viimeiset, katso, ne ovat kirjoitetut Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Ja Asa tuli kipiäksi jaloista yhdeksäntenäneljättäkymmentä valtakuntansa vuotena, ja hänen tautinsa kovin eteni, ja ei hän kuitenkaan etsinyt Herraa taudissansakaan, vaan lääkäreitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Niin Asa nukkui isäinsä kanssa ja kuoli valtakuntansa ensimäisenä vuotena viidettäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Ja hän haudattiin omaan hautaansa, jonka hän oli antanut kaivaa Davidin kaupungissa. Ja he panivat hänet leposiaansa, joka täytettiin hyvänhajullisilla ja kaikkinaisilla kalliilla yrteillä, jotka olivat valmistetut apotekarein tavalla, ja polttivat hänelle sangen suurella polttamisella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Ja Josaphat hänen poikansa tuli kuninkaaksi hänen siaansa; ja hän tuli väkeväksi Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Ja hän asetti sotaväen kaikkiin Juudan vahvoihin kaupunkeihin, ja pani esimiehiä Juudan maalle ja Ephraimin kaupunkeihin, jotka hänen isänsä Asa oli voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Ja Herra oli Josaphatin kanssa; sillä hän vaelsi isänsä Davidin tiellä, ja ei etsinyt Baalia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Vaan hän etsi isänsä Jumalaa ja vaelsi hänen käskyissänsä, ja ei Israelin töiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Sentähden vahvisti Herra hänelle valtakunnan, ja kaikki Juuda antoi Josaphatille lahjoja; ja hänellä oli rikkautta ja kunniaa yltäkyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Ja kuin hänen sydämensä tuli rohkiaksi Herran teissä, otti hän korkeudet ja metsistöt Juudasta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Ja kolmantena valtakuntansa vuonna lähetti hän päämiehensä Benhailin, Obadian, Sakarian, Netaneelin ja Mikajan, opettamaan Juudan kaupungeissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'Ja Leviläiset heidän kanssansa: Semajan, Netanian, Sebadian, Asaelin, Semiramotin, Jonatanin, Adonijan, Tobijan ja Tobadonijan, Leviläiset; ja heidän kanssansa papit, Elisamin ja Joramin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Ja he opettivat Juudassa, ja pitivät Herran lakikirjan myötänsä, ja vaelsivat ympäri kaikki Juudan kaupungit, ja opettivat kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Ja Herran pelko tuli kaikkein valtakuntain päälle, niissä maakunnissa, jotka olivat Juudan ympäristöllä, niin ettei he sotineet Josaphatia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Ja Philistealaiset toivat Josaphatille lahjoja ja rahaveron; ja Arabialaiset toivat myös hänelle pientä karjaa, seitsemäntuhatta ja seitsemänsataa oinasta, ja seitsemäntuhatta ja seitsemänsataa kaurista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Niin menestyi Josaphat ja tuli aina suuremmaksi. Ja hän rakensi Juudassa linnoja ja tavarakaupungeita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Ja hänellä oli paljo varaa Juudan kaupungeissa, ja sotamiehiä ja väkevää kansaa Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Ja tämä on järjestys heidän isäinsä huoneen vaiheella, jotka Juudassa tuhanten päämiehet olivat: päämies Adna, ja hänen kanssansa kolmesataa tuhatta väkevää sotamiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'Lähin häntä oli päämies Johanan, ja hänen kanssansa kaksisataa ja kahdeksankymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'Häntä likin Amasia Sikrin poika, joka itsensä hyvällä tahdolla antoi Herralle, ja hänen kanssansa kaksisataa tuhatta vahvaa sotamiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Benjaminin lapsista Eljada, väkevä sotamies, ja hänen kanssansa varustettuja joutsilla ja kilvillä kaksisataa tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'Häntä likin oli Josabad, ja hänen kanssansa sata ja kahdeksankymmentä tuhatta valmista sotamiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Nämät ottivat kuninkaasta vaarin, paitsi niitä, jotka kuningas oli asettanut vahvoihin kaupunkeihin koko Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Ja Josaphatilla oli suuri rikkaus ja kunnia; ja hän teki nuoteutta Ahabin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Ja jonkun vuoden perästä sen jälkeen meni hän Ahabin tykö Samariaan. Ja Ahab antoi teurastaa hänelle ja hänen väellensä, joka oli hänen kanssansa, monta lammasta ja härkää; ja hän yllytti hänen menemään ylös Gileadin Ramotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Ja Ahab Israelin kuningas sanoi Josaphatille Juudan kuninkaalle: menetkös minun kanssani Gileadin Ramotiin? Hän sanoi hänelle: minä olen niinkuin sinä, ja minun kansani niinkuin sinun kansas: me tahdomme sinun kanssas sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Mutta Josaphat sanoi Israelin kuninkaalle: kyseles tänäpänä Herran sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Ja Israelin kuningas kokosi prophetaita neljäsataa miestä ja sanoi heille: menemmekö me sotimaan Gileadin Ramotiin, vai ei? He sanoivat: mene, Jumala antaa heidät kuninkaan käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Silloin sanoi Josaphat: eikö tässä ole joku Herran propheta, kysyäksemme häneltä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Israelin kuningas sanoi Josaphatille: tässä on vielä yksi mies, jonka kautta taidettaisiin kysellä Herraa, vaan minä vihaan häntä; sillä ei hän ennusta minulle mitään hyvää, mutta aina pahaa: se on Miika Jimlan poika. Josaphat sanoi: älköön kuningas niin puhuko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Ja Israelin kuningas kutsui yhden kamaripalvelioistansa ja sanoi: nouda nopiasti Miika Jimlan poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Ja Israelin kuningas ja Josaphat Juudan kuningas istui kumpikin istuimellansa puettuna vaatteisiin Samarian portin lakeudella, ja kaikki prophetat ennustivat heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Ja Zidkija Kenaanan poika teki itsellensä rautasarvet ja sanoi: näin sanoo Herra: näillä sinä pusket Syrialaisia, siihenasti ettäs heidät hävität.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Ja kaikki prophetat ennustivat niin ja sanoivat: mene Gileadin Ramotiin, ja se menestyy sinulle: Herra antaa heidät kuninkaan käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Ja sanansaattaja, joka oli mennyt kutsumaan Miikaa, puhui hänen kanssansa ja sanoi: katso, prophetain puhe on yksimielisesti hyvä kuninkaan edessä: anna sinun sanas olla myös niinkuin heidänkin, ja puhu hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Ja Miika sanoi: niin totta kuin Herra elää, minä puhun, mitä minun Jumalani sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Ja kuin hän tuli kuninkaan tykö, sanoi kuningas hänelle: Miika, menemmekö me sotimaan Gileadin Ramotia vastaan, eli ei? Hän sanoi: menkäät, se menestyy teille, he annetaan teidän käsiinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Niin kuningas sanoi hänelle: kuinka usein minä vannotan sinua, ettet sinä sanois minulle muuta kuin totuutta Herran nimeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Niin hän sanoi: minä näin kaiken Israelin hajoitettuna vuorella, niinkuin lampaat, joilla ei yhtään paimenta ole: ja Herra sanoi: eikö näillä ole yhtään Herraa? palatkaan kukin kotiansa rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Niin sanoi Israelin kuningas Josaphatille: enkö minä sanonut sinulle, ettei hän minulle ennusta hyvää vaan pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Ja hän sanoi: sentähden kuulkaat Herran sanaa; minä näin Herran istuvan istuimellansa, ja koko taivaallisen sotajoukon seisovan hänen oikialla ja vasemmalla puolellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Ja Herra sanoi: kuka viettelis Ahabin Israelin kuninkaan, että hän menis ylös ja lankeaisi Gileadin Ramotissa? Ja kuin yksi sanoi niin, ja toinen näin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Niin tuli yksi henki ja seisoi Herran edessä, ja sanoi: minä viettelen hänen. Ja Herra sanoi hänelle: millä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Hän sanoi: minä menen ja olen valheen henki kaikkein hänen prophetainsa suussa. Ja hän sanoi: viettele häntä ja sinä myös taidat: mene ja tee niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Nyt siis katso, Herra on antanut valheen hengen näiden sinun prophetais suuhun, ja Herra on puhunut pahaa sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Niin astui Zidkija Kenaanan poika edes ja löi Miikaa poskelle, ja sanoi: minkä tien kautta on Herran henki mennyt minun tyköäni pois, sinua puhuttelemaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Miika sanoi: katso, sinä olet sen näkevä sinä päivänä, jona käyt majasta majaan, lymytäkses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Niin sanoi Israelin kuningas: ottakaat Miika ja viekäät jälleen häntä kaupungin päämiehen Amonin tykö ja Joaksen kuninkaan pojan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Ja sanokaat: näin sanoo kuningas: pankaat tämä vankihuoneesen, ja ruokkikaat häntä murheen leivällä ja murheen vedellä, siihenasti että minä tulen jälleen rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Miika sanoi: jos sinä toki palajat rauhassa, niin ei ole Herra puhunut minun kauttani. Ja hän sanoi: kuulkaat, kaikki kansat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Niin meni Israelin kuningas ja Josaphat Juudan kuningas Gileadin Ramotia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Ja Israelin kuningas sanoi Josaphatille: minä muutan vaatteeni ja tulen sotaan, mutta pidä sinä omat vaattees; ja Israelin kuningas muutti vaatteensa, ja he menivät sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Ja Syrian kuningas käski vaunuin päämiehille, jotka hänellä olivat, ja sanoi: ei teidän pidä sotiman pientä eli suurta vastaan, vaan ainoastaan Israelin kuningasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Ja tapahtui, kuin vaunuin päämiehet näkivät Josaphatin, että he sanoivat: se on Israelin kuningas; ja he käänsivät itsensä sotimaan häntä vastaan. Ja Josaphat huusi, ja Herra autti häntä, ja Jumala käänsi heidät pois hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Sillä kuin vaunuin päämiehet näkivät, ettei hän ollut Israelin kuningas, käänsivät he itsensä pois hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Niin yksi mies jännitti joutsensa yksinkertaisuudessa ja ampui Israelin kuningasta rautapaidan jatkoon. Niin hän sanoi vaununsa ajajalle: käänä kätes ja vie minua ulos sotaväestä; sillä minä olen haavoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Ja sota tuli suureksi sinä päivänä, ja Israelin kuningas seisoi vaunuissa Syrialaisia vastaan ehtoosen asti; ja hän kuoli auringon laskeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Mutta Josaphat Juudan kuningas palasi kotia rauhassa Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Ja Jehu Hananin poika näkiä meni häntä vastaan ja sanoi kuningas Josaphatille: pitääkö sinun auttaman jumalatointa ja rakastaman niitä, jotka Herraa vihaavat? ja sentähden on Herran viha sinun päälläs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Niin on kuitenkin jotain hyvää löydetty sinun tykönäs, ettäs olet hävittänyt metsistöt maalta ja olet aikonut sydämestäs Jumalaa etsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Niin Josaphat jäi Jerusalemiin. Ja hän meni jälleen ulos kansan seassa Bersabasta hamaan Ephraimin vuorelle, ja palautti heidät jälleen Herran heidän isäinsä Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Ja hän asetti tuomarit maalle, kaikkiin Juudan vahvoihin kaupunkeihin, muutaman kuhunkin kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Ja hän sanoi tuomareille: katsokaat, mitä teette; sillä ette pidä tuomiota ihmisten, vaan Herran edessä. Ja hän on teidän kanssanne tuomiossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Sentähden antakaat Herran pelvon olla teidän tykönänne, ja karttakaat teitänne ja tehkäät se; sillä Herran meidän Jumalamme tykönä ei ole yhtään vääryyttä, ei myös hän katso muotoa, eikä ota lahjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Ja Josaphat asetti myös Jerusalemiin Leviläisiä ja pappeja, ja Israelin isäin ylimmäisiä Herran tuomion ja asiain päälle; ja he palasivat Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Ja hän käski heitä, sanoen: tehkäät näin Herran pelvossa uskollisesti ja vaalla sydämellä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Kaikissa riita-asioissa, jotka tulevat teidän eteenne veljiltänne, jotka kaupungeissansa asuvat, veren ja veren välillä, lain ja käskyn välillä, säätyin ja oikeutten välillä, pitää teidän neuvoman heitä, ettei he syntiä tekisi Herraa vastaan ja saattaisi vihaa teidän ja veljeinne päälle; tehkäät siis kaikki näin, niin ette syntiä tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Katso, Amaria pappi on kaikkein ylimmäinen teidän ylitsenne kaikissa Herran asioissa. Niin on Sebadia Ismaelin poika hallitsia Juudan huoneessa kaikissa kuninkaan asioissa, niin ovat myös teillä virkamiehet Leviläiset: olkaat hyvässä turvassa ja tehkäät tämä, ja Herra on hyväin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Sitte tulivat Moabilaiset, Ammonilaiset ja heidän kanssansa myös muita, paitsi Ammonilaisia, sotimaan Josaphatia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Niin tultiin ja ilmoitettiin Josaphatille, sanoen: sinua vastaan tulee sangen suuri sotajoukko Syriasta, tuolta puolelta meren; ja katso, he ovat HatsetsonTamarissa: se on Engeddi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Mutta Josaphat pelkäsi, ja asetti kasvonsa etsimään Herraa, ja antoi kuuluttaa paaston koko Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Ja Juuda tuli kokoon etsimään Herralta; tultiin myös kaikista Juudan kaupungeista etsimään Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Ja Josaphat seisoi Juudan ja Jerusalemin seurakunnassa, Herran huoneessa, uuden pihan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'Ja hän sanoi: Herra meidän isäimme Jumala! etkös ole Jumala taivaissa, joka hallitset kaikkein pakanain valtakunnissa? Ja sinun kädessäs on väki ja voima, ja ei ole yhtään, joka voi olla sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Etkös sinä, meidän Jumalamme, ole ajanut tämän maan asujamia kansas Israelin edestä pois? ja olet sen antanut Abrahamin sinun ystäväs siemenelle ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Niin että he ovat asuneet siinä, ja ovat rakentaneet sinun nimelles pyhän, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Kuin joku onnettomuus, rangaistusmiekka, rutto eli kallis aika meille tulee, niin pitää meidän seisoman tässä huoneessa sinun edessäs (sillä sinun nimes on tässä huoneessa) ja huutaman sinua tuskassamme, niin sinä kuulet ja autat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Ja nyt katso, Ammonin lapset, Moab ja Seirin vuorelaiset, joidenka kautta et sinä antanut Israelin lasten mennä, vaeltaissansa Egyptistä; vaan heidän täytyi palata pois heidän tyköänsä, eikä hävittäneet heitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Ja katso, he kostavat sen meille; ja he tulevat meitä ajamaan perinnöstäs pois, jonka meille perinnöksi antanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Meidän Jumalamme! etkös heitä tuomitse? Sillä ei ole meillä yhtään voimaa tätä suurta joukkoa vastaan, joka tulee meitä vastaan: emme tiedä, mitä me teemme, vaan meidän silmämme katselevat sinun puolees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Ja kaikki Juuda seisoi Herran edessä, lapsinensa, vaimoinensa ja poikinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Ja Jehasielin Sakarian pojan, Benajan pojan, Jehielin pojan, Mattanjan pojan päälle, Leviläisen Asaphin lapsista, tuli Herran henki seurakunnan keskellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Ja sanoi: kuulkaat, koko Juuda ja Jerusalemin asuvaiset, ja kuningas Josaphat! Näin sanoo Herra teille: älkäät peljätkö, älkäät vavisko tätä suurta joukkoa, sillä te ette sodi, vaan Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Huomenna pitää teidän menemän alas heidän tykönsä, ja katso, he menevät ylös Zitsin paltaan, ja te löydätte heidät ojan lopulla kohdastansa Jeruelin korven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Ei teidän pidä sotiman tässä asiassa, ainoastansa käykäät edes, seisokaat ja katsokaat Herran autuutta, joka on teidän kanssanne: Juuda ja Jerusalem, älkäät peljätkö ja älkäät hämmästykö, menkäät huomenna ulos heitä vastaan, Herra on teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Silloin kumarsi Josaphat kasvoillensa maahan; ja kaikki Juuda ja Jerusalemin asuvaiset lankesivat Herran eteen ja rukoilivat Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Ja Leviläiset Kahatilaisten lapsista ja Korhilaisten lapsista nousivat kiittämään Herraa Israelin Jumalaa kovalla äänellä korkeuteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Ja he nousivat varhain huomeneltain ja menivät Tekoan korpeen. Ja heidän lähteissänsä seisoi Josaphat ja sanoi: kuulkaat minua, Juuda ja Jerusalemin asujamet, uskokaat Herran teidän Jumalanne päälle, niin te olette hyvässä turvassa, ja uskokaat hänen prophetansa, niin te menestytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Ja hän keskusteli kansan kanssa, ja asetti veisaajat Herralle, kiittämään pyhässä kaunistuksessa, mennessä hankitun sotaväen edellä, jotka sanoivat: kiittäkäät Herraa, sillä hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Ja sittekuin he rupesivat kiittämään ja ylistämään, antoi Herra väijyjät tulla Ammonin, Moabin ja Seirin vuorelaisten päälle, jotka Juudaa vastaan tulleet olivat; ja he löivät heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Niin nousivat Ammonin ja Moabin lapset Seirin vuoren asuvia vastaan, tappamaan ja hävittämään heitä. Ja sittekuin he olivat lopettaneet Seirin asuvaiset, autti kukin lähimmäistänsä toinen toistansa tappamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Mutta kuin Juuda tuli Mitspaan, joka on korven tykönä, käänsivät he heitänsä joukkoa päin, ja katso, silloin makasivat kuolleet ruumiit maassa, niin ettei yksikään heistä ollut päässyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Ja Josaphat tuli väkinensä jakamaan heidän saalistansa, ja he löysivät siellä ruumisten seassa tavaraa ja kallista kalua, ja he ottivat heiltä niin paljon, ettei he voineet kantaa; ja he ottivat siitä saaliista kolme päivää; sillä sitä oli sangen paljo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Neljäntenä päivänä tulivat he kokoon Kiitoslaaksoon, sillä siinä he kiittivät Herraa; siitä kutsutaan se paikka Kiitoslaaksoksi tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Ja kaikki Juuda ja Jerusalem palasivat takaperin, ja Josaphat kaikkein ensin, niin että he menivät ilolla Jerusalemiin; sillä Herra oli antanut heille ilon heidän vihollisistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Ja he menivät Jerusalemiin psaltareilla, harpuilla ja basunilla, Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Ja Jumalan pelko tuli kaikkein valtakuntain päälle maalla, sittekuin he kuulivat Herran sotineen Israelin vihollisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Ja niin Josaphatin valtakunta oli levossa; ja Jumala antoi hänelle levon ympäristöllänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Ja Josaphat hallitsi Juudaa, ja oli viiden ajastaikainen neljättäkymmentä tullessansa kuninkaaksi ja hallitsi Jerusalemissa viisikolmattakymmentä ajastaikaa; hänen äitinsä nimi oli Asuba Silhin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Ja hän vaelsi isänsä Asan teillä ja ei siitä horjahtanut, ja teki sitä mikä Herralle otollinen oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Paitsi ettei korkeudet tulleet otetuiksi pois; sillä ettei kansa vielä asettanut sydäntänsä Herran isänsä Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Mitä enempi Josaphatin töistä sanomista on, sekä ensimäisistä että viimeisistä: katso, ne ovat kirjoitetut Jehun Hananin pojan teoissa, jotka hän oli kirjoittanut Israelin kuningasten kirjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Senjälkeen yhdisti Josaphat Juudan kuningas itsensä Ahasian Israelin kuninkaan kanssa, joka oli jumalatoin menoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Ja hän suostui hänen kanssansa haaksia tekemään, vaeltaaksensa Tarsikseen. Ja he tekivät haaksia EtseonGeberissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Mutta Elieser Dodavan poika Maresasta ennusti Josaphatia vastaan ja sanoi: ettäs olet suostunut Ahasiaan, on Herra särkenyt sinun työs; ja haahdet menivät rikki, ja ei he saaneet enää Tarsikseen kulkea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Ja Josaphat nukkui isäinsä kanssa ja haudattiin isäinsä tykö Davidin kaupunkiin. Ja hänen poikansa Joram tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Ja hänellä oli veljiä Josaphatin poikia, Asaria, Jehiel, Sakaria, Asaria, Mikael ja Sephatia. Nämät kaikki olivat Josaphatin Israelin kuninkaan pojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Ja heidän isänsä antoi heille monta lahjaa hopiasta, kullasta ja kalliista kappaleista, vahvain Juudan kaupunkein kanssa. Mutta Joramille antoi hän valtakunnan; sillä hän oli esikoinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Kuin Joram korotettiin isänsä valtakuntaan ja tuli voimalliseksi, tappoi hän kaikki veljensä miekalla ja muutamia Israelin ylimmäisistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Ja Joram oli kahden ajastajan vanha neljättäkymmentä tullessansa kuninkaaksi; ja hän hallitsi kahdeksan ajastaikaa Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Ja hän vaelsi Israelin kuningasten tiellä, niinkuin Ahabin huone teki; sillä Ahabin tytär oli hänen emäntänsä; ja hän teki pahaa Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Mutta ei Herra tahtonut hukuttaa Davidin huonetta, sen liiton tähden, jonka hän tehnyt oli Davidin kanssa, ja niinkuin hän puhunut oli antaaksensa hänelle ja hänen lapsillensa valkeuden joka aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Hänen aikanansa luopuivat Edomilaiset Juudan vallan alta ja tekivät itsellensä kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Niin Joram meni ylitse ylimmäistensä kanssa, ja kaikki vaunut hänen kanssansa; ja hän valmisti itsensä yöllä ja löi kaikki Edomilaiset ympäristöltänsä, ja myös vaunuin päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Ja Edomilaiset luopuivat Juudan vallan alta tähän päivään asti; silloin luopui myös Libna hänestä; sillä hän hylkäsi Herran isäinsä Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Ja hän teki korkeuksia Juudan vuorilla, ja saatti Jerusalemin asuvaiset huorin tekemään ja vietteli Juudan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Ja kirjoitus tuli hänelle Elialta prophetalta, joka näin oli: näin sanoo Herra sinun isäs Davidin Jumala: ettes vaeltanut isäs Josaphatin teillä, etkä Aksan Juudan kuninkaan teillä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Mutta vaellat Israelin kuningasten tiellä, ja saatat Juudan ja Jerusalemin asuvaiset huorin tekemään Ahabin huoneen huoruuden jälkeen, ja olet tappanut veljes isäs huoneesta, jotka sinua paremmat olivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Katso, niin Herra lyö sinua kovin ja sinun kansaas, lapsias, emäntiäs ja kaikkea hyvyyttäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Ja sinun sisällyksissäs pitää oleman monta sairautta, siihenasti että sisällykses sinusta päivä päivältä sairauden tähden käyvät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Niin Herra herätti Joramia vastaan Philistealaisten ja Arabialaisten hengen, jotka ovat Etiopialaisten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Ja he menivät ylös Juudaan, ja hävittivät sen ja veivät pois kaiken kalun, joka kuninkaan huoneessa oli, niin myös hänen poikansa ja emäntänsä; niin ettei hänelle yhtään poikaa jäänyt, paitsi Joahasta nuorinta poikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Ja kaiken sen jälkeen rankaisi Herra häntä hänen sisällyksissänsä senkaltaisella taudilla, jota ei taidettu parantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Ja se tapahtui päivä päivältä, siihenasti kuin kahden vuoden aika kulunut oli, että hänen sisällyksensä kävivät ulos hänestä, hänen tautinsa kanssa; ja hän kuoli pahoista taudeista. Ja he ei tehneet yhtään suitsutusta hänelle, niin kuin he olivat tehneet hänen esi-isillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Hän oli kahden ajastajan vanha neljättäkymmentä tullessansa kuninkaaksi, ja hallitsi kahdeksan ajastaikaa Jerusalemissa, ja vaelsi kelvottomasti; ja he hautasivat hänen Davidin kaupunkiin, mutta ei kuningasten hautain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Ja Jerusalemin asuvaiset asettivat Ahasian hänen nuorimman poikansa kuninkaaksi hänen siaansa; sillä se sotaväki, joka Arabiasta tuli, oli tappanut kaikki vanhemmat; sentähden tuli Ahasia Joramin poika Juudan kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Ja Ahasia oli kahden ajastajan vanha viidettäkymmentä tullessansa kuninkaaksi, ja hallitsi ajastajan Jerusalemissa. Ja hänen äitinsä nimi oli Atalia Omrin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Hän vaelsi myös Ahabin huoneen teillä; sillä hänen äitinsä neuvoi häntä jumalattomuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Sentähden hän myös teki sitä, joka ei Herralle kelvannut, niinkuin Ahabinkin huone; sillä he olivat hänen neuvonantajansa hänen isänsä kuoleman jälkeen, hukuttamaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Hän vaelsi myös heidän neuvonsa jälkeen, ja meni pois Joramin Israelin kuninkaan pojan kanssa sotaan Hasaelia Syrian kuningasta vastaan, Gileadin Ramotiin. Mutta Syrialaiset löivät Joramin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Niin että hän palasi antamaan itsiänsä parantaa Jisreelissä; sillä hänellä oli haavat, jotka hän oli saanut Ramassa soteissansa Hasaelin Syrian kuninkaan kanssa. Ja Asaria Joramin poika Juudan kuningas meni sinne katsomaan Joramia Ahabin poikaa, joka sairasti Jisreelissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Sillä se onnettomuus oli Jumalalta Ahasian päälle pantu, että hän tuli Joramin tykö, ja että hän tultuansa meni Joramin kanssa Jehua Nimsin poikaa vastaan, jonka Herra voidellut oli Ahabin huonetta hävittämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Ja kuin Jehu rupesi rankaisemaan Ahabin huonetta, löysi hän muutamia ylimmäisiä Juudasta ja Ahasian veljein lapsista, jotka Ahasiaa palvelivat, ja tappoi ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Ja hän etsi Ahasiaa; ja he saivat hänen kiinni Samariassa, johon hän itsensä lymyttänyt oli, ja he veivät hänen Jehun eteen, ja he tappoivat hänen, ja hautasivat hänen; sillä he sanoivat: hän on Josaphatin poika, joka on etsinyt Herraa kaikesta sydämestänsä. Ja ei sitte yhtään ollut Ahasian huoneesta, joka taisi kuninkaaksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Kuin Atalia Ahasian äiti näki poikansa kuolleeksi, nousi hän ja murhasi kaiken kuninkaallisen siemenen Juudan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mutta Josabeath kuninkaan tytär otti Joaksen Ahasian pojan varkain kuninkaan lasten seasta, jotka tapettiin, ja pani hänen imettäjänsä kanssa makaushuoneesen; ja näin lymytti Josabeath kuningas Joramin tytär, papin Jojadan emäntä, hänen Athalian edestä; (sillä hän oli Ahasian sisar) niin ettei hän tapettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Ja hän oli heidän kanssansa Jumalan huoneessa kätkettynä kuusi vuotta. Ja Athalia hallitsi maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Seitsemäntenä vuonna rohkaisi Jojada itsensä ja otti sodanpäämiehet, Asarian Jerohamin pojan, Ismaelin Johananin pojan, Asarian Obedin pojan, Maesejan Adajan pojan ja Elisaphatin Sikrin pojan liittoon kanssansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Jotka kävivät Juudan ympäri ja kokosivat Leviläisiä kaikista Juudan kaupungeista, ja ylimmäiset Israelin isät, tulemaan Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Ja kaikki seurakunta teki liiton kuninkaan kanssa Jumalan huoneessa. Ja hän sanoi heille: katso, kuninkaan poika pitää kuningas oleman, niinkuin Herra Davidin lapsista sanonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Näin pitää teidän tekemän: kolmas osa teistä, jotka käyvät sisälle sabbatina papeista ja Leviläisistä, pitää oleman oven tykönä vartiana;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'Ja kolmas osa kuninkaan huoneessa, ja kolmas osa perustuksen portissa; mutta kaikki kansa pitää oleman Herran huoneen pihalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Ettei yksikään mene Herran huoneesen, vaan papit ja Leviläiset, jotka siellä palvelevat, niiden pitää sisälle menemän; sillä he ovat pyhät; mutta kaikki muu kansa vartioitkaan Herran vartiota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Ja Leviläisten pitää piirittämän kuninkaan jokainen aseensa kanssa kädessänsä. Ja jos joku muu menee huoneesen, hänen pitää kuoleman. Ja teidän pitää oleman kuninkaan tykönä, kuin hän käy sisälle ja ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Ja Leviläiset kaiken Juudan kanssa tekivät kaiketi niinkuin pappi Jojada käskenyt oli. Ja jokainen otti väkensä, jotka menivät sabbatille, niiden kanssa jotka menivät pois sabbatilta; sillä pappi Jojada ei antanut niiden eritä toinen toisestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Ja Jojada pappi antoi sodanpäämiehille keihäät ja kilvet ja kuningas Davidin aseet, jotka Jumalan olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Ja asetti kaiken kansan, itsekunkin aseinensa kädessänsä, oikiasta huoneen loukkaasta niin vasempaan loukkaasen, alttarin ja huoneen tykö, kuningasta ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Ja he toivat kuninkaan pojan edes, panivat kruunun hänen päähänsä, ja todistuksen, ja tekivät hänen kuninkaaksi. Ja Jojada ja hänen poikansa voitelivat hänen, ja sanoivat: menestyköön kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Kuin Atalia kuuli kansan äänen, jotka juoksivat ylistäen kuningasta, niin hän meni kansan tykö Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Ja hän näki, ja katso, kuningas seisoi patsaansa tykönä läpikäytävässä, ja ylimmäiset ja vaskitorvet kuninkaan ympärillä, ja kaikki maan kansa oli iloinen, ja puhalsivat vaskitorviin, ja veisaajat kaikkinaisten kanteleiden kanssa, taitavat kiittämään. Silloin repäisi Atalia vaatteensa ja sanoi: kapina, kapina!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Mutta Jojada pappi meni sodanpäämiesten kanssa ulos, jotka olivat sotajoukon päällä, ja sanoi heille: taluttakaat häntä ulos joukon lävitse: ja joka häntä seuraa, se pitää miekalla tapettaman; sillä pappi oli käskyn antanut, ettei häntä pitänyt Herran huoneessa tapettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Ja he panivat kätensä hänen päällensä, ja kuin hän tuli hevosportin läpikäytävään, joka oli kuninkaan huoneen tykönä, tappoivat he hänen siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Ja Jojada teki liiton itsensä, kaiken kansan ja kuninkaan vaiheella, että he olisivat Herran kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Silloin meni kaikki kansa Baalin huoneesen ja kukistivat sen, ja särkivät hänen alttarinsa ja kuvansa, ja tappoivat Mattanin Baalin papin alttarien edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Ja Jojada pani Herran huoneen virat pappein ja Leviläisten käsiin, jotka David oli asettanut Herran huoneesen tekemään Herran polttouhria, niinkuin kirjoitettu on Moseksen laissa, ilolla ja veisulla Davidin asetuksen jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Ja asetti portinvartiat Herran huoneen portteihin, ettei mitään saastaisuutta sisälle tulisi missään kappaleessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Ja hän otti sadanpäämiehet, ja voimalliset, ja kansan hallitsiat, ja kaiken maan kansan, ja vei kuninkaan Herran huoneesta alas ja he menivät ylimmäisen portin lävitse kuninkaan huoneesen; ja he antoivat kuninkaan istua valtakunnan istuimelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Ja kaikki maan kansa oli iloinen, ja kaupunki oli levossa, sittekuin Atalia tapettiin miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas oli seitsemän ajastaikainen tullessansa kuninkaaksi, ja hallitsi neljäkymmentä ajastaikaa Jerusalemissa. Ja hänen äitinsä nimi oli Zibia Bersabasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Ja Joas teki sitä, mikä oikein oli Herran edessä, niinkauvan kuin pappi Jojada eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Ja Jojada otti hänelle kaksi emäntää ja hän siitti poikia ja tyttäriä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Ja tapahtui sen jälkeen, että Joas aikoi uudistaa Herran huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Ja hän kokosi papit ja Leviläiset ja sanoi heille: menkäät ulos Juudan kaupunkeihin ja kootkaat rahaa kaikelta Israelilta, vuosi vuodelta, teidän Jumalanne huoneen parannukseksi, ja kiiruhtakaat tekemään sitä; mutta Leviläiset ei kiiruhtaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Silloin kutsui kuningas Jojadan, ylimmäisen papin, ja sanoi hänelle: miksi et ota vaaria Leviläisistä, että he toisivat veron Juudasta ja Jerusalemista, jonka Moses Herran palvelia pani päälle, kuin piti Israelista koottaman todistuksen majaksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Sillä jumalatoin Atalia on poikinensa särkenyt Jumalan huoneen, ja kaiken Herran huoneesen pyhitetyn olivat he tehneet Baalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Niin kuningas käski; ja he tekivät arkun, jonka he panivat Herran huoneen portin ulkoiselle puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Ja he kuuluttivat Juudassa ja Jerusalemissa tuomaan Herralle veroa, jonka Jumalan palvelia Moses oli pannut Israelin päälle korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Silloin iloitsivat kaikki päämiehet ja kaikki kansa; ja he toivat ja panivat arkkuun, siihenasti että se tuli täyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Ja kuin aika tuli, että arkku kannettiin edes Leviläisiltä kuninkaan käskyn jälkeen (ja he näkivät siinä olevan paljon rahaa), tuli kuninkaan kirjoittaja ja se joka ylimmäiseltä papilta uskottu oli, ja he tyhjensivät arkun ja kantoivat sen jälleen siallensa. Näin he tekivät joka päivä siihenasti että he kokosivat paljon rahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Ja kuningas ja Jojada antoivat ne teettäjille Herran huoneen palvelukseksi; ne palkkasivat kivenhakkaajia ja rakentajia, uudistamaan Herran huonetta, niin myös rauta- ja vaskiseppiä, parantamaan Herran huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Ja työmiehet tekivät työtä, niin että parannustyö menestyi heidän kättensä kautta; ja he saivat Jumalan huoneen kokonansa valmiiksi ja hyvin rakennetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Ja kuin he sen olivat päättäneet, veivät he liian rahan kuninkaan ja Jojadan eteen; siitä tehtiin astioita Herran huoneesen, astioita palvelukseen ja polttouhriin, lusikoita, kulta- ja hopia-astioita; ja uhrasivat polttouhria Herran huoneen tykönä alati niinkauvan kuin Jojada eli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Ja Jojada tuli vanhaksi ja ijällä ravituksi ja kuoli; ja hän oli sadan ja kolmenkymmenen ajastaikainen kuollessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Ja he hautasivat hänen Davidin kaupunkiin kuningasten sekaan; sillä hän oli tehnyt hyvin Israelissa Jumalaa ja hänen huonettansa kohtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Ja Jojadan kuoleman jälkeen tulivat Juudan ylimmäiset ja rukoilivat kuningasta. Niin kuningas kuuli heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Ja he hylkäsivät Herran isäinsä Jumalan huoneen ja palvelivat metsistöitä ja epäjumalia. Niin tuli viha Juudan ja Jerusalemin päälle tämän heidän syntinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Ja hän lähetti heille prophetat palauttamaan heitä Herran tykö; ja he todistivat heille, mutta ei he totelleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Ja Jumalan henki puetti Sakarian papin Jojadan pojan; hän astui kansan eteen ja sanoi heille: näin sanoo Jumala: miksi te rikotte Herran käskyn? Ei se pidä teille menestymän; koska te olette hyljänneet Herran, niin hylkää hän jälleen teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mutta he tekivät liiton häntä vastaan ja kivittivät hänen kuoliaaksi kuninkaan käskyn jälkeen, Herran huoneen pihalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Ja kuningas Joas ei ajatellut sitä laupiutta, jonka Jojada hänen isänsä hänelle tehnyt oli, mutta tappoi hänen poikansa. Ja hän sanoi kuollessansa: Herra on näkevä ja etsivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Ja tapahtui kuin ajastaika oli kulunut, että Syrian sotajoukko nousi häntä vastaan ja tuli Juudaan ja Jerusalemiin, ja surmasivat kaikki ylimmäiset kansan seasta, ja lähettivät kaiken saaliinsa Damaskun kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Vaikka Syrian sotajoukko tuli vähällä väellä, kuitenkin antoi Herra sangen suuren joukon heidän käsiinsä, että he Herran isäinsä Jumalan hyljänneet olivat. Ja niin he myös rankaisivat Joaksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Ja kuin he läksivät hänen tyköänsä, jättivät he hänen suureen sairauteen. Ja hänen palveliansa tekivät liiton häntä vastaan, Jojadan papin lasten veren tähden, ja tappoivat hänen omalla vuoteellansa, ja hän kuoli; ja he hautasivat hänen Davidin kaupunkiin, mutta ei kuningasten hautain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Ne jotka liiton olivat tehneet häntä vastaan, olivat nämät: Sabad Simeatin Ammonilaisen poika, ja Josabad Simritin Moabilaisen poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Mutta hänen poikainsa ja hänen aikanansa koottujen verojen luku, ja Jumalan huoneen rakennus, katso, ne ovat kirjoitetut kuningasten historiakirjassa. Ja hänen poikansa Amatsia tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amatsia oli viiden ajastaikainen kolmattakymmentä tullessansa kuninkaaksi, ja hallitsi yhdeksänkolmattakymmentä ajastaikaa Jerusalemissa. Ja hänen äitinsä nimi oli Joaddan Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Ja hän teki, mitä Herralle oli otollinen, vaan ei täydestä sydämestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Kuin hänen valtakuntansa vahvistettiin, tappoi hän palveliansa, jotka tappoivat kuninkaan hänen isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mutta heidän lapsiansa ei hän tappanut; sillä näin on kirjoitettu laissa Moseksen raamatussa, jossa Herra kieltää, sanoen: ei tule isäin kuolla lasten edestä, eikä lasten isäin edestä; mutta jokaisen pitää kuoleman syntinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Ja Amatsia kokosi Juudan ja asetti heidät isäinsä huoneen jälkeen, tuhanten ja satain päämiehet koko Juudassa ja Benjaminissa, ja luki kahdenkymmenen vuotiset ja sitä vanhemmat, ja löysi heitä kolmesataa tuhatta valittua, jotka olivat kelvolliset sotaan, kantamaan keihästä ja kilpeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Hän palkkasi myös Israelista satatuhatta vahvaa sotamiestä sadalla leiviskällä hopiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Niin tuli Jumalan mies hänen tykönsä ja sanoi: kuningas, älä salli Israelin sotajoukon tulla kanssas; sillä ei Herra ole Israelin kanssa, eikä kaikkein Ephraimin lasten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Sillä jos sinä tulet osoittamaan sinun rohkeuttas sodassa, niin Jumala antaa sinun kaatua vihamiestes eteen; sillä Jumalalla on voima auttaa ja langettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amatsia sanoi Jumalan miehelle: mitäs sadan leiviskän kanssa tehdään, jotka minä Israelin sotamiehille annoin? Jumalan mies sanoi: Herralla on varaa antaa sinulle paljon enemmän kuin se on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Niin eroitti Amatsia ne sotamiehet tyköänsä, jotka Ephraimista olivat hänen tykönsä tulleet, menemään siallensa. Niin he närkästyivät sangen suuresti Juudan päälle ja menivät kotiansa vihoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Ja Amatsia tuli rohkiaksi ja johdatti kansansa ulos, ja meni Suolalaaksoon, ja löi siellä Seirin lapsista kymmenentuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Ja Juudan lapset veivät pois elävältä vankina kymmenentuhatta, ja veivät heidät kallion kukkulalle ja sysäsivät heidät kukkulalta maahan, niin että he kaikki musertuivat liivaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Mutta sotamiehet, jotka Amatsia oli antanut mennä takaisin, niin ettei ne hänen kanssansa päässeet menemään sotaan, hajoittivat itsensä Juudan kaupunkeihin Samariasta Bethoroniin asti, ja löivät heistä kolmetuhatta, ja ottivat paljon saalista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Ja kuin Amatsia palasi Edomilaisten taposta, toi hän myötänsä Seirin lasten epäjumalat ja asetti ne itsellensä jumaliksi, kumarsi niiden edessä ja teki heille suitsutusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Niin Herran viha julmistui Amatsian päälle, ja hän lähetti prophetan hänen tykönsä, joka sanoi: miksis etsit sen kansan jumalia, jotka kansaansa ei taitaneet auttaa sinun käsistäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Kuin hän puhui hänen kanssansa, sanoi hän hänelle: oletkos asetettu kuninkaan neuvonantajaksi? lakkaa, miksis tahdot antaa sinuas lyödä? Niin propheta lakkasi ja sanoi: minä ymmärrän, että Jumala on aikonut sinua turmella, koskas sen tehnyt olet, ja et totellut minun neuvoani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Ja Amatsia Juudan kuningas piti neuvoa, ja lähetti Joaksen Joahaksen pojan, Jehun pojan Israelin kuninkaan tykö, ja käski sanoa hänelle: tule, katselkaamme toinen toistamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Mutta Joas Israelin kuningas lähetti Amatsian Juudan kuninkaan tykö, sanoen: orjantappurapensas Libanonissa lähetti sedripuun tykö Libanonissa, sanoen hänelle: anna tyttäres minun pojalleni emännäksi; mutta pedot Libanonissa juoksivat orjantappurapensaan päälle ja tallasivat sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Sinä ajattelet, katso, sinä olet lyönyt Edomilaiset, siitä sinun sydämes paisuu kerskaamaan itsiäs: pysy kotonas, miksis etsit vahinkoa, langetakses sekä itse että Juuda sinun kanssas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mutta ei Amatsia totellut, sillä se tapahtui Jumalalta, että he piti annettaman käsiin; sillä he olivat etsineet Edomilaisten jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Niin Joas Israelin kuningas meni ylös, ja he katselivat toinen toistansa, hän ja Amatsia Juudan kuningas, Betsemeksessä, joka on Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Mutta Juuda lyötiin Israelilta, ja kukin pakeni majoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Ja Joas Israelin kuningas käsitti Amatsian Juudan kuninkaan Joaksen pojan Joahaksen pojan Betsemeksessä ja vei Jerusalemiin, ja särki Jerusalemin muurin Ephraimin portista kulmaporttiin asti, neljäsataa kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Ja hän otti kaiken kullan ja hopian, ja kaikki astiat jotka löydettiin Jumalan huoneessa Obededomin tykönä, ja kuninkaan huoneen tavarat ja (otti) lapset pantiksi ja palasi Samariaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Ja Amatsia Joaksen poika Juudan kuningas eli Joaksen Joahaksen pojan Israelin kuninkaan kuoleman jälkeen viisitoistakymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Mitä enempää Amatsian menoista sanomista on, sekä ensimäisistä että viimeisistä: eikö se ole kirjoitettu Juudan ja Israelin kuningasten kirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Ja siitä ajasta, jona Amatsia luopui Herrasta, tekivät he häntä vastaan liiton Jerusalemissa; mutta hän pakeni Lakikseen. Niin lähettivät he hänen perässänsä Lakikseen ja tappoivat hänen siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Ja he veivät hänen hevosilla ja hautasivat hänen isäinsä tykö Juudan kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Mutta koko Juudan kansa otti Ussian, joka oli kuudentoistakymmenen ajastaikainen, ja asettivat hänen kuninkaaksi isänsä Amatsian siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Hän rakensi Elotin, ja saatti sen jälleen Juudalle, sitte kuin kuningas oli nukkunut isäinsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Kuudentoistakymmenen vuotinen oli Ussia tullessansa kuninkaaksi, ja hallitsi kaksi ajastaikaa kuudettakymmentä Jerusalemissa. Ja hänen äitinsä nimi oli Jekolia Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Ja hän teki, mitä otollinen oli Herran edessä, kaiketi niinkuin hänen isänsä Amatsia oli tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Ja hän etsi Jumalaa, niinkauvan kuin Sakaria eli, opettaja Jumalan näyissä. Ja niinkauvan kuin hän etsi Herraa, antoi Jumala hänen menestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Sillä hän läksi ja soti Philistealaisia vastaan, ja kukisti Gatin muurin, ja Jabnen muurin, ja Asdodin muurin, ja rakensi kaupungeita Asdodin ympärille ja Philistealaisten keskelle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Sillä Jumala autti häntä Philistealaisia, Arabialaisia, Gurbaalin asuvia ja Meunilaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Ja Ammonilaiset antoivat Ussialle lahjoja; ja hän tuli kuuluisaksi hamaan siihen saakka, josta Egyptiin mennään; sillä hän tuli aina väkevämmäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Ja Ussia rakensi tornit Jerusalemissa Kulmaportin ja Laaksoportin päälle, ja muihin kulmiin, ja vahvisti niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Hän rakensi torneja myös korpeen ja kaivoi monta kaivoa; sillä hänellä oli paljo karjaa laaksoissa ja tasaisella kedolla, ja peltomiehiä ja viinamiehiä vuorilla ja Karmelissa; sillä hän rakasti peltoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Ussialla oli myös hyvin harjoitettu sotajoukko, jotka sotaan menivät joukottain, heidän lukunsa jälkeen, niinkuin he olivat luetut Jejelin kirjoittajan ja Maesejan virkamiehen kautta, Hananian käden alla, joka oli kuninkaan päämiehiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Ja ylimmäisten isäin luku väkevistä sotamiehistä oli kaksituhatta ja kuusisataa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Ja heidän allansa sotajoukko kolmesataa tuhatta ja seitsemäntuhatta, ja viisisataa väkevää ja urhoollista sotamiestä, joiden piti kuningasta auttaman vihamiehiä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Ja Ussia valmisti koko sotajoukolle kilpiä ja keihäitä, rautalakkeja ja rautapaitoja, joutsia ja vielä kiviäkin linkoja varten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Hän teki myös Jerusalemissa varustukset sangen taitavasti, jotka piti oleman tornein päällä ja kulmain päällä, joista piti ammuttaman nuolilla ja suurilla kivillä. Ja hänen sanomansa kuului sangen leviälle; sillä hän tuli ihmeellisesti autetuksi, siihen asti että hän väkeväksi tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Kuin hän oli väkeväksi tullut, paisui hänen sydämensä omaksi kadotukseksensa, ja rikkoi Herraa Jumalaansa vastaan, ja meni Herran templiin sisälle, suitsuttamaan pyhän savun alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Ja Asaria pappi meni hänen perässänsä, ja hänen kanssansa kahdeksankymmentä Herran pappia, väkeviä miehiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Ja seisoivat kuningas Ussiaa vastaan ja sanoivat hänelle: Ussia, ei sinun sovi suitsuttaa Herralle, vaan pappein, Aaronin poikain, jotka ovat pyhitetyt suitsuttamaan: mene ulos pyhästä, sinä olet väärin tehnyt, ei se tule sinulle kunniaksi Herran Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Mutta Ussia vihastui, ja piti kädessänsä pyhän savun astian suitsuttaaksensa. Vaan kuin hän vihastui pappeja vastaan, kävi spitali hänen otsastansa ulos pappein edessä Herran huoneessa, pyhän savun alttarin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Niin katsoi ylimmäinen pappi Asaria hänen puoleensa, ja kaikki muut papit, ja katso, hän oli spitalinen otsassansa. Ja he hoputtivat hänen sieltä ulos, ja hän riensi myös itsekin; sillä hän oli Herralta rangaistu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Ja niin oli kuningas Ussia spitalinen hamaan kuolemaansa asti, ja asui erinäisessä huoneessa spitalisena, sillä hän oli eroitettu Herran huoneesta. Mutta Jotam hänen poikansa hallitsi kuninkaan huoneen ja tuomitsi kansaa maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Mitä enempää Ussian menoista sanomista on, sekä ensimäisistä että viimeisistä, on propheta Jesaia Amotsin poika kirjoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Ja Ussia nukkui isäinsä kanssa, ja he hautasivat hänen isäinsä kanssa kuningasten hautapeltoon; sillä he sanoivat: hän on spitalinen. Ja Jotam hänen poikansa tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotam oli viiden ajastaikainen kolmattakymmentä tulessansa kuninkaaksi, ja hallitsi kuusitoistakymmentä ajastaikaa Jerusalemissa: hänen äitinsä nimi oli Jerusa Zadokin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Ja hän teki mitä Herralle oli kelvollinen, kaiketi niinkuin hänen isänsä Ussia tehnyt oli, paitsi sitä, ettei hän käynyt Herran templissä, ja kansa turmeli vielä itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Hän rakensi ylisen portin Herran huoneesen, ja Ophelin muuria hän paljon rakensi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Ja hän rakensi kaupungit Juudan vuorelle, ja metsiin rakensi hän linnat ja tornit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Ja hän soti Ammonin lasten kuninkaan kanssa, ja voitti heidät, niin että Ammonin lapset antoivat sinä vuonna hänelle sata leiviskää hopiaa, kymmenentuhatta koria nisuja ja kymmenentuhatta koria ohria. Niin paljon antoivat myös Ammonin lapset hänelle toisena ja kolmantena vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Näin tuli Jotam voimalliseksi; sillä hän toimitti tiensä oikein Herran Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Mitä enempää Jotamista sanomista on, ja kaikista hänen sodistansa ja teistänsä: katso, ne ovat kirjoitetut Israelin ja Juudan kuningasten kirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Viidenkolmattakymmenen vuoden vanha oli hän tulessansa kuninkaaksi, ja hallitsi kuusitoistakymmentä vuotta Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Ja Jotam nukkui isäinsä kanssa, ja he hautasivat hänen Davidin kaupunkiin. Ja hänen poikansa Ahas tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ahas oli kahdenkymmenen ajastaikainen tullessansa kuninkaaksi, ja hallitsi kuusitoistakymmentä ajastaikaa Jerusalemissa, ja ei tehnyt, mitä Herralle kelvollinen oli, niinkuin hänen isänsä David;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Vaan hän vaelsi Israelin kuningasten teillä, ja teki myös Baalille valetuita kuvia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Ja hän suitsutti Hinnomin poikain laaksossa, ja poltti poikansa tulella pakanain kauhistusten jälkeen, jotka Herra Israelin lasten edestä oli ajanut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Ja hän uhrasi ja suitsutti korkeuksilla ja kukkuloilla, ja kaikkein viheriäisten puiden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Sentähden antoi Herra hänen Jumalansa hänen Syrian kuninkaan käsiin, niin että he löivät häntä, ja veivät heistä suuren joukon vangiksi Damaskuun. Hän annettiin myös Israelin kuninkaan käsiin, joka heistä sangen paljon tappoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Sillä Peka Remalian poika löi Juudasta sata ja kaksikymmentä tuhatta yhtenä päivänä, jotka kaikki väkevät miehet olivat, että he hylkäsivät Herran isäinsä Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Ja Sikri Ephraimin väkevä tappoi kuninkaan pojan Maesejan, ja Asrikamin kuninkaan huoneen päämiehen, ja Elkanan, joka kuningasta lähimmäinen oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Ja Israelin lapset veivät vankina veljistänsä kaksisataa tuhatta, vaimoja, poikia ja tyttäriä, ja ryöstivät myös heiltä paljon saalista, jonka he veivät Samariaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Ja siellä oli Herran propheta, jonka nimi oli Obed, hän läksi sitä joukkoa vastaan, joka Samariaan tuli, ja sanoi heille: katso, Herra teidän isäinne Jumala on vihastunut Juudan päälle, ja on heidät antanut teidän käsiinne; mutta te olette kiukussa heitä tappaneet, niin että se taivaasen kuuluu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Niin te luulette nyt polkevanne teidän allenne Juudan lapset ja Jerusalemin, teidän palvelioiksenne ja piioiksenne. Eikö teissä vika ole Herraa teidän Jumalaanne vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Niin kuulkaat nyt minua ja viekäät ne vangit sinne jälleen, jotka te otitte teidän veljistänne; sillä Herran viha julmistui teidän päällenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Silloin nousivat muutamat Ephraimin lasten ylimmäisistä: Asaria Johanan poika, Berekia Mesillemotin poika, Jehiskia Sallumin poika ja Amasa Hadlain poika, niitä vastaan, jotka sodasta tulivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'Ja sanoivat heille: ei teidän pidä niitä vankeja tuoman tänne; sillä ette sillä muuta saata kuin vikaa meidän päällemme Herran edessä, lisätäksenne meidän syntejämme ja rikoksiamme; sillä meidän vikamme on paljo, ja viha julmistuu Israelin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Niin sotaväki päästi vangit vallallensa ja asetti saaliin ylimmäisten ja kaiken kansan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Ja ne miehet nousivat, jotka nimeltänsä nimitetyt olivat, ja ottivat vangit ja kaikki jotka heidän seassansa alasti olivat, ja vaatettivat siitä saaliista. Ja kuin he heidät olivat vaatettaneet ja kengittäneet, antoivat he heille ruokaa ja juomaa, ja voitelivat heitä, ja veivät kaikki ne aasein päällä jotka heikoimmat olivat, ja saattivat heidät Jerihon Palmukaupunkiin veljeinsä tykö, ja palasivat sitte Samariaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Siihen aikaan lähetti kuningas Ahas Assurin kuningasten tykö, että he olisivat auttaneet häntä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Sillä Edomilaiset tulivat vielä, ja löivät Juudan ja veivät heitä vankina pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Ja Philistealaiset hajoittivat itsensä ketokaupunkeihin, etelän puolelle Juudaa, ja voittivat Betsemeksen, Ajalonin, Gederotin ja Sokon kylinensä, ja Timnan kylinensä ja Gimson kylinensä, ja asuivat siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Sillä Herra nöyryytti Juudaa Ahaksen Israelin kuninkaan tähden, että hän oli vietellyt Juudan, ja teki väärin Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Ja hänen tykönsä tuli TiglatPilsener Assurin kuningas, joka piiritti hänen, ja ei häntä voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Sillä Ahas otti yhden osan Herran huoneesta ja kuninkaan ja ylimmäisten huoneesta, jotka hän antoi Assyrin kuninkaalle, vaan ei se häntä mitään auttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Silloin teki kuningas Ahas vielä enemmän väärin Herraa vastaan tuskassansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Ja uhrasi Damaskun epäjumalille, jotka olivat lyöneet häntä, ja sanoi: koska Syrian kuningasten jumalat auttivat heitä, sentähden minä uhraan heille, että he myös minua auttaisivat; mutta he olivat hänelle ja kaikelle Israelille lankeemiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Ja Ahas kokosi astiat Jumalan huoneesta ja särki Jumalan huoneen astiat, ja sulki Herran huoneen ovet, ja teki itsellensä alttareita joka nurkkaan Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Ja myös kaikissa Juudan kaupungeissa teki hän korkeuksia siellä ja täällä, suitsuttaaksensa vieraille jumalille, ja vihoitti Herran isäinsä Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Mitä enempi hänestä on sanomista, ja kaikista hänen teistänsä, ensimäisistä ja viimeisistä: katso, se on kirjoitettu Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Ja Ahas nukkui isäinsä kanssa, ja he hautasivat hänen Jerusalemin kaupunkiin; mutta ei he panneet häntä Israelin kuningasten sekaan. Ja hänen poikansa Jehiskia tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Jehiskia oli viiden ajastaikainen kolmattakymmentä tullessansa kuninkaaksi, ja hallitsi yhdeksänkolmattakymmentä ajastaikaa Jerusalemissa. Ja hänen äitinsä nimi oli Abia Sakarian tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Ja hän teki, mitä Herralle oli otollinen, kaiketi niinkuin hänen isänsä David.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Hän avasi Herran huoneen ovet ensimäisenä valtakuntansa kuukautena ensimäisenä vuonna, ja vahvisti ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Ja saatti papit ja Leviläiset sinne, ja kokosi heidät itäiselle kadulle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Ja sanoi heille: kuulkaat minua Leviläiset: pyhittäkäät nyt teitänne, ja pyhittäkäät Herran teidän isäinne Jumalan huone, ja kantakaat saastaisuus ulos pyhästä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Sillä meidän isämme ovat menetelleet väärin, ja tehneet pahaa Herran Jumalamme edessä, ja hyljänneet hänen; sillä he ovat kasvonsa kääntäneet pois Herran majasta, ja kääntäneet selkänsä sen puoleen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Ovat myös sulkeneet esihuoneen ovet, ja sammuttaneet lamput, ja ei suitsuttaneet suitsutusta, eikä uhranneet polttouhria Israelin Jumalalle pyhässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Siitä on Herran viha Juudan ja Jerusalemin päälle tullut, ja on antanut heidän hämmästykseksi ja hävitykseksi, ja viheltämiseksi, niinkuin te näette silmillänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Sillä katso, sentähden ovat meidän isämme langenneet miekan kautta, meidän poikamme, tyttäremme ja emäntämme ovat viedyt pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nyt olen minä aikonut tehdä Herran Israelin Jumalan kanssa liiton, että hän vihansa hirmuisuuden kääntäis meidän päältämme pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Nyt minun poikani, älkäät siekailko; sillä Herra on teidät valinnut seisomaan edessänsä palveluksessa, ja olemaan hänen palveliansa, ja suitsuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Niin nousivat Leviläiset: Mahat Amasain poika, ja Joel Asarian poika Kahatilaisten lapsista; ja Merarin lapsista: Kis Abdin poika, ja Atsaria Jahalleleelin poika; ja Gersonilaisista: Joa Simman poika, ja Eden Joan poika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Ja Elitsaphanin lapsista: Simri ja Jejel; Asaphin lapsista: Zakaria ja Mattania;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Hemanin lapsista: Jehiel ja Simei; Jedutunin lapsista: Semaja ja Ussiel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Ja he kokosivat veljensä ja pyhittivät itsensä, ja menivät kuninkaan käskystä Herran sanan jälkeen puhdistamaan Herran huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Ja papit menivät sisälle Herran huoneesen puhdistamaan sitä, ja kantoivat ulos kaiken saastaisuuden, jonka löysivät Herran templistä, Herran huoneen kartanolle. Ja Leviläiset ottivat sen ja kantoivat Kidronin ojaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Ensimäisenä päivänä ensimäisestä kuusta rupesivat he pyhittämään itseänsä, ja kahdeksantena päivänä siitä kuusta menivät he Herran esihuoneesen ja pyhittivät Herran huonetta kahdeksan päivää, ja päättivät sen kuudentena toistakymmentä ensimäisellä kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Ja he menivät sisälle kuningas Jehiskian tykö ja sanoivat: me olemme puhdistaneet kaiken Herran huoneen ja polttouhrin alttarin, ja kaikki sen astiat, ja näkyleipäin pöydän ja kaikki sen astiat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Kaikki myös ne astiat, jotka kuningas Ahas oli hyljännyt kuninkaana olessansa, koska hän väärin teki, ne olemme me valmistaneet ja pyhittäneet: ja katso, ne ovat Herran alttarin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Niin kuningas Jehiskia nousi varhain aamulla ja kokosi kaupungin ylimmäiset, ja meni Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Ja toivat seitsemän mullia, ja seitsemän oinasta, ja seitsemän karitsaa, ja seitsemän kaurista syntiuhriksi, valtakunnan edestä, pyhän edestä, ja Juudan edestä. Ja hän sanoi papeille Aaronin lapsille, että he uhraisivat ne Herran alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Niin he teurastivat härjät, ja papit ottivat veren ja priiskottivat alttarille; ja he teurastivat oinaat ja priiskottivat veren alttarille, ja teurastivat myös karitsat ja priiskottivat veren alttarille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Ja toivat kauriit syntiuhriksi kuninkaan ja seurakunnan eteen, ja panivat kätensä niiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Ja papit teurastivat ne ja priiskottivat veren alttarille, sovittamaan kaikkea Israelia; sillä kuningas oli heidän käskenyt uhrata polttouhrin ja syntiuhrin kaiken Israelin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Ja hän asetti Leviläiset Herran huoneesen symbaleilla, psaltareilla ja harpuilla, niinkuin David käskenyt oli ja Gad kuninkaan näkiä, ja Natan propheta; sillä se oli Herran käsky hänen prophetainsa kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Ja Leviläiset seisoivat Davidin harppuin kanssa ja papit basunain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Ja Jehiskia käski heidän uhrata polttouhria alttarilla. Ja ruvetessa uhraamaan polttouhria, ruvettiin myös veisaamaan Herralle basunilla ja moninaisilla Davidin Israelin kuninkaan kanteleilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Ja koko seurakunta kumarsi. Ja veisaajain veisuu ja basunan soittajain ääni kuului, siihenasti että kaikki polttouhri täytettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Koska polttouhri uhrattu oli, notkisti kuningas ja kaikki ne, jotka hänen kanssansa olivat, polviansa ja kumarsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Ja kuningas Jehiskia ja kaikki ylimmäiset käskivät Leviläisten kiittää Herraa Davidin ja näkiän Asaphin sanoilla. Ja kiittivät häntä suurella ilolla, ja kallistivat päätänsä ja kumarsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Niin Jehiskia vastaten sanoi: nyt te olette täyttäneet kätenne Herralle, käykäät ja kantakaat uhria ja kiitosuhria Herran huoneesen. Ja seurakunta vei uhria ja kiitosuhria, ja jokainen hyväntahtoinen sydämestä polttouhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Ja polttouhrin luku, jonka seurakunta vei, oli seitsemänkymmentä härkää, sata oinasta ja kaksisataa karitsaa; ja nämät kaikki veivät he polttouhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Ja he pyhittivät kuusisataa härkää ja kolmetuhatta lammasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Vaan pappeja oli vähimmäksi, niin ettei he voineet ottaa pois vuotia kaikilta polttouhreilta, sentähden auttivat heitä heidän veljensä Leviläiset, siihenasti että työ täytettiin ja niin kauvan kuin papit pyhittivät itsiänsä; sillä Leviläiset olivat vireämmät pyhittämässä itsiänsä kuin papit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Ja polttouhria oli paljo kiitosuhrin lihavuuden kanssa, ja juomauhria polttouhriksi. Näin virka valmistettiin Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Ja Jehiskia riemuitsi ja kaikki kansa siitä, mitä Jumala oli kansalle valmistanut; sillä se tapahtui sangen kiiruusti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Ja Jehiskia lähetti kaiken Israelin ja Juudan tykö, ja kirjoitti kirjat Ephraimille ja Manasselle, että heidän piti tuleman Herran huoneesen Jerusalemiin, pitämään Herralle Israelin Jumalalle pääsiäistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Ja kuningas piti neuvoa ylimmäistensä kanssa ja koko seurakunnan kanssa Jerusalemissa, pääsiäisen pitämisestä toisena kuukautena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Sillä ei he taitaneet sitä pitää siihen aikaan, sillä papit ei olleet vielä täydellisesti pyhittäneet itseänsä, eikä kansa ollut tullut kokoon Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Ja tämä kelpasi kuninkaalle ja koko seurakunnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'Ja he toimittivat niin, että se kuulutettiin kaikessa Israelissa Bersebasta Daniin asti, tulemaan ja pitämään Herralle Israelin Jumalalle pääsiäistä Jerusalemissa; sillä ei se pidetty suureen aikaan, niinkuin kirjoitettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Ja sanansaattajat menivät kirjain kanssa, kuninkaan ja hänen päämiestensä kädestä, kaiken Israelin ja Juudan lävitse kuninkaan käskystä, ja sanoivat: te Israelin lapset, kääntäkäät teitänne Herran Abrahamin, Isaakin ja Israelin Jumalan tykö, niin hän kääntää itsensä päässeiden tykö, jotka vielä ovat jääneet Assyrian kuninkaan kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Ja älkäät olko niinkuin isänne ja niinkuin veljenne, jotka väärin tekivät Herraa isäinsä Jumalaa vastaan; ja hän antoi heidät hävitykseksi, niinkuin te itse näette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Niin älkäät nyt olko uppiniskaiset, niinkuin teidän isänne, mutta antakaat kättä Herralle ja tulkaat hänen pyhäänsä, jonka hän on pyhittänyt ijankaikkisesti, ja palvelkaat Herraa Jumalaanne, niin hänen vihansa julmuus kääntyy teistä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Sillä jos te käännytte Herran tykö, niin veljenne ja lapsenne saavat armon niiden edessä, jotka heitä vankina pitävät, että he tulevat tähän maahan jälleen; sillä Herra teidän Jumalanne on armollinen ja laupias, ja ei käännä kasvojansa pois teistä, jos te käännytte hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Ja sanansaattajat menivät yhdestä kaupungista niin toiseen Ephraimin ja Manassen maalla Sebuloniin asti; mutta ne nauroivat ja pilkkasivat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Kuitenkin muutamat Asserista, Manassesta ja Sebulonista nöyryyttivät itsensä ja tulivat Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Ja Jumalan käsi tuli myös Juudaan, että hän antoi heille yksimielisen sydämen, tekemään kuninkaan ja ylimmäisten käskyä, Herran sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Ja paljo kansaa tuli Jerusalemiin kokoon, pitämään happamattoman leivän juhlapäivää, toisena kuukautena, sangen suuri kokous.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Ja he nousivat ja kukistivat alttarit, jotka olivat Jerusalemissa, ja ottivat kaikki suitsutukset pois ja heittivät Kidronin ojaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Ja teurastivat pääsiäisen neljäntenä päivänä toisena kuukautena. Ja papit ja Leviläiset häpesivät, ja pyhittivät itsensä, ja kantoivat polttouhria Herran huoneesen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Ja seisoivat järjestyksessänsä niinkuin pitikin, Moseksen Jumalan miehen lain jälkeen. Ja papit priiskottivat Leviläisten kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Sillä monta oli seurakunnassa, jotka ei olleet pyhittäneet itsiänsä; sentähden teurastivat Leviläiset pääsiäisen kaikkein niiden edestä, jotka ei olleet puhtaat, pyhittääksensä heitä Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Sillä paljo kansaa oli, suuri joukko Ephraimista, Manassesta, Isaskarista ja Sebulonista, jotka ei itsiänsä puhdistaneet, vaan söivät pääsiäislampaan, ei niinkuin kirjoitettu on. Mutta Jehiskia rukoili heidän edestänsä ja sanoi: Herra, joka on hyvä, hän olkoon armollinen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Kaikille, jotka sydämensä asettivat etsimään Herraa isäinsä Jumalaa, vaikka ei he ole pyhän puhtauden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Ja Herra kuuli Jehiskian rukouksen ja paransi kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Niin Israelin lapset, jotka olivat Jerusalemissa, pitivät happamattoman leivän juhlaa seitsemän päivää suurella ilolla. Ja papit ja Leviläiset kiittivät Herraa joka päivä Herran väkevillä kanteleilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Ja Jehiskia puhui ystävällisesti kaikkein Leviläisten kanssa, joilla oli hyvä ymmärrys Herrasta; ja söivät juhlaa koko seitsemän päivää, ja uhrasivat kiitosuhria, ja kiittivät Herraa isäinsä Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Ja koko seurakunta mielistyi pitämään vielä toiset seitsemän päivää, ja he pitivät myös ne seitsemän päivää ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Sillä Jehiskia Juudan kuningas antoi ylennykseksi kansalle tuhannen mullia ja seitsemäntuhatta lammasta. Ja ylimmäiset antoivat ylennykseksi kansalle tuhannen mullia ja kymmenentuhatta lammasta; ja monta pappia pyhitti itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Ja koko Juudan seurakunta iloitsi ja papit ja Leviläiset, ja koko seurakunta, joka oli tullut Israelista, niin myös muukalaiset, jotka olivat tulleet Israelin maalta, ja ne kuin asuivat Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Ja silloin oli suuri ilo Jerusalemissa, että Salomon Davidin pojan Israelin kuninkaan ajasta ei ole senkaltaista ollut Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Ja papit ja Leviläiset nousivat ja siunasivat kansaa, ja heidän äänensä kuultiin, ja heidän rukouksensa tuli hänen pyhään asumiseensa taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Kuin nämät kaikki päätetyt olivat, läksivät kaikki Israelilaiset ulos, jotka Juudan kaupungeissa olivat, ja rikkoivat patsaat, ja hakkasivat maahan metsistöt, ja kukistivat korkeudet ja alttarit koko Juudasta, Benjaminista, Ephraimista ja Manassesta, siihenasti että ne peräti hävittivät. Ja Israelin lapset palasivat jokainen omainsa tykö kaupunkeihinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Mutta Jehiskia asetti papit ja Leviläiset järjestykseensä, kunkin virkansa jälkeen, sekä papit että Leviläiset, polttouhrilla ja kiitosuhrilla, palvelemaan, kiittämään ja kunnioittamaan Herran leirien porteissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Ja kuningas antoi osan tavarastansa huomeneltain ja ehtoona polttouhriksi, ja sabbatin, uuden kuun ja juhlapäivän polttouhriksi, niinkuin kirjoitettu on Herran laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Ja hän sanoi kansalle, joka asui Jerusalemissa, että heidän piti antaman osan papeille ja Leviläisille, että he olisivat vireämmät Herran laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Ja kuin se sanottu oli, antoivat Israelin lapset paljon uutista jyvistä, viinasta, öljystä, hunajasta ja kaikkinaisesta pellon kasvusta, ja kymmenykset kaikista runsaasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Ja Israelin ja Juudan lapset, jotka Juudan kaupungeissa asuivat, toivat myöskin kymmenykset karjasta ja lampaista ja pyhitetystä, jonka he Herralle Jumalallensa pyhittäneet olivat, ja asettivat eri läjiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Kolmantena kuukautena rupesivat he panemaan läjiin, ja seitsemäntenä kuukautena päättivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Ja kuin Jehiskia tuli ylimmäisten kanssa ja näki läjät, kiittivät he Herraa ja hänen kansaansa Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Ja Jehiskia kysyi papeilta ja Leviläisiltä läjistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Ja Asaria, ylimmäinen pappi Zadokin huoneesta, puhui hänelle, sanoen: siitä ajasta, kuin he rupesivat ylennystä tuomaan Herran huoneesen, olemme me syöneet ja tulleet ravituiksi, ja tässä on vielä paljo tähteinä; sillä Herra on siunannut kansaansa, sentähden on tämä paljous jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Niin kuningas käski valmistaa kammiot Herran huoneesen; ja he valmistivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'Ja panivat niihin ylennyksen ja kymmenykset, ja sen mikä pyhitetty oli, uskollisesti. Ja Kanania Leviläinen oli asetettu päämieheksi sen päälle ja Simei hänen veljensä toiseksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Ja Jehiel, Asasia, Nabat, Asahel, Jerimot, Josabad, Eliel, Jismakia, Mahat ja Benaja, asetetut Kananialta, ja hänen veljeltänsä Simeiltä, kuningas Jehiskian käskyn jälkeen, ja Asarialta Jumalan huoneen päämieheltä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Ja Kore Jimnan poika Leviläinen, ovenvartia idän puolella, oli Jumalan vapaaehtoisten lahjain päällä jakamassa niitä, mitkä Herralle annetut olivat ylennykseksi, ja kaikkein pyhimmän päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Ja hänen kätensä alla olivat Eden, Miniamin, Jesua, Semaja, Amaria ja Sakania, pappein kaupungeissa: että heidän piti uskollisesti antaman osan veljillensä heidän järjestyksensä jälkeen, pienimmälle niinkuin suurimmallekin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Niin myös niille, jotka luettiin miehenpuolesta, kolmesta ajastajastansa ja sen ylitse, kaikkein niiden seassa, jotka Herran huoneesen menivät, kukin päivänänsä heidän virkansa, vartionsa ja järjestyksensä jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Niin myös niille, jotka olivat pappein luvussa heidän isäinsä huoneissa, ja Leviläiset kahdestakymmenestä ajastajastansa ja sen ylitse, heidän vartioissansa, heidän järjestyksensä jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'Sitte niille, jotka luetut olivat lastensa, vaimoinsa, poikainsa ja tytärtensä seassa, koko seurakunnan seassa; sillä he pyhittivät uskollisesti sen pyhitetyn;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Niin myös papeille Aaronin pojille esikaupunkein kedolla heidän kaupungeissansa, kussakin kaupungissa miehet nimiltänsä nimitetyt, että heidän piti osan antaman kaikille miehenpuolille pappein seassa ja kaikille niille, jotka Leviläisten sekaan luetut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Näin teki Jehiskia kaikessa Juudassa; ja hän teki mikä hyvä, oikia ja totuus oli Herran hänen Jumalansa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Ja kaikissa teoissansa, jotka hän alkoi Jumalan huoneen palveluksessa, lain ja käskyn jälkeen, etsiäksensä Jumalaansa: sen teki hän kaikesta sydämestänsä, sentähden hän myös menestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Näiden tekoin ja tämän totuuden jälkeen tuli Sanherib Assurin kuningas ja meni Juudaan, ja sioitti itsensä vahvain kaupunkein eteen, ja ajatteli ne itsellensä voitaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Kuin Jehiskia näki Sanheribin tulevan, ja että hänen kasvonsa olivat käännetyt sotimaan Jerusalemia vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Piti hän neuvoa ylimmäistensä ja väkeväinsä kanssa, tukitaksensa vesilähteet, jotka ulkona kaupungista olivat; ja he auttivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Sillä paljo kansaa kokoontui, ja he tukitsivat kaikki lähteet ja vuotavan ojan keskellä maata, ja sanoivat: miksi Assurin kuninkaat tultuansa pitäis paljon vettä löytämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Ja hän vahvisti itsensä ja rakensi kaikki rauvenneet muurit, ja korotti tornin tasalle, ja vielä sitte (rakensi) ulkonaiselle puolelle toisen muurin, ja vahvisti Millon Davidin kaupungissa, ja antoi tehdä paljon aseita ja kilpiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Ja asetti sodanpäämiehet kansan päälle, ja kokosi heitä tykönsä kaupungin portin kadulla, ja puhui sydämellisesti heidän tykönsä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Olkaat rohkiat ja hyvässä turvassa, älkäät peljätkö ja älkäät vavahtuko Assurin kuningasta ja kaikkea sitä joukkoa, joka hänen kanssansa on; sillä meidän kanssamme on enempi kuin hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Hänen kanssansa on lihallinen käsivarsi, vaan meidän kanssamme on Herra meidän Jumalamme, auttamassa meitä ja sotimassa meidän edestämme. Ja kansa luotti Jehiskian Juudan kuninkaan sanoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Sitte lähetti Sanherib Assurin kuningas palveliansa Jerusalemiin, (sillä hän oli Lakiksen edessä ja kaikki hänen sotaväkensä hänen kanssansa) Jehiskian Juudan kuninkaan tykö ja koko Juudan tykö, joka Jerusalemissa oli, ja antoi heille sanoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Näin sanoo Sanherib Assurin kuningas: mihinkä te uskallatte, jotka olette piiritetyssä Jerusalemissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Eikö Jehiskia petä teitä, saattain teitä kuolemaan nälästä ja janosta, ja sanoen: Herra meidän Jumalamme pelastaa meitä Assurin kuninkaan kädestä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Eikö hän ole se Jehiskia, joka hänen korkeutensa ja alttarinsa on heittänyt pois, ja puhunut Juudalle ja Jerusalemille sanoen: teidän pitää rukoileman yhden alttarin edessä ja sen päällä suitsuttaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ettekö te tiedä, mitä minä ja isäni tehneet olemme kaikille kansoille maakunnissa? ovatko pakanain jumalat maakunnissa joskus voineet pelastaa maansa minun kädestäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kuka on kaikista pakanain jumalista, jotka isäni kironneet ovat, joka on voinut ottaa ulos kansansa minun kädestäni, että teidän Jumalanne vois ottaa ulos teitä minun kädestäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Niin älkäät siis nyt antako Jehiskian vietellä teitänne, älkään myös uskottako teitä, ja älkäät te uskoko häntä; sillä jos ei kaikkein pakanain valtakuntain jumalat ole voineet auttaa ulos kansaansa minun kädestäni ja isäni kädestä, paljo vähemmin myös teidän Jumalanne ottaa ulos teitä minun kädestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Ja vielä hänen palveliansa puhuivat enemmän Herraa Jumalaa vastaan ja hänen palveliaansa Jehiskiaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Hän kirjoitti myös kirjat häväistäksensä Herraa Israelin Jumalaa, ja puhui häntä vastaan ja sanoi: niinkuin maakuntain pakanain jumalat ei ole auttaneet kansaansa minun kädestäni, niin ei pidä Jehiskiankaan Jumalan pelastaman kansaansa minun kädestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Ja he huusivat korkialla äänellä Juudan kielellä Jerusalemin kansalle, joka muurin päällä olivat, peljättääksensä ja hämmästyttääksensä heitä, että he olisivat voittaneet kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Ja he puhuivat Jerusalemin Jumalaa vastaan, niinkuin maan kansain jumalia vastaan, jotka ihmisten käsiteot olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Mutta kuningas Jehiskia ja Jesaia propheta Amotsin poika rukoilivat sitä vastaan ja huusivat taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Ja Herra lähetti enkelin, joka surmasi kaikki väkevät sotajoukosta ja päämiehet ja ylimmäiset Assurin kuninkaan leirissä, niin että hän häpiällä palasi maallensa. Ja kuin hän meni jumalansa huoneesen, tappoivat ne, jotka hänen ruumiistansa tulleet olivat, hänen siellä miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Ja niin autti Herra Jehiskiaa ja Jerusalemin kaupungin asuvaisia Sanheribin Assurin kuninkaan kädestä ja kaikkein muiden kädestä, ja varjeli heitä kaikilta, jotka ympäristöllä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Ja moni kantoi Herralle lahjoja Jerusalemiin ja Jehiskialle Juudan kuninkaalle kalliita kaluja; ja niin hän sitte korotettiin kaikkein pakanain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Siihen aikaan sairasti Jehiskia kuolemantautia, ja hän rukoili Herraa; ja hän puhui hänelle ja antoi hänelle ihmeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Vaan Jehiskia ei maksanut mitä hänelle annettu oli; sillä hänen sydämensä oli paisunut; sentähden tuli viha hänen päällensä ja Juudan ja Jerusalemin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Mutta Jehiskia nöyryytti itsensä sydämensä ylpeydestä, hän ja Jerusalemin asuvaiset; sentähden ei Herran viha tullut heidän päällensä Jehiskian elinaikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Ja Jehiskialla oli rikkautta ja kunniaa sangen paljo; sillä hän teki itsellensä suuret tavarat hopiasta, kullasta ja kalliista kivistä, jaloista yrteistä, kilvistä ja kaikkinaisista kalliista kaluista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Ja aittoja jyviä, viinaa ja öljyä varten, ja pihatot kaikkinaisille eläimille ja karsinat lampaille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Ja rakensi itsellensä kaupungeita, ja hänellä oli karjaa, lampaita ja härkiä kyllä; sillä Jumala antoi hänelle sangen paljon rikkautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Hän on se Jehiskia, joka tukitsi ylimmäisen vesijuoksun Gihonissa ja johdatti sen alaskäsin länteen päin Davidin kaupunkiin; sillä Jehiskia oli onnellinen kaikissa teoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Mutta kuin Babelin päämiesten lähetyssana oli hänen tykönsä lähetetty, kysymään sitä ihmettä, joka maalla tapahtunut oli, hylkäsi Jumala hänen, kiusataksensa häntä, että kaikki tiedettäisiin, mitä hänen sydämessänsä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Mitä enempi Jehiskiasta sanomista on ja hänen laupiudestansa: katso, se on kirjoitettu Jesaian prophetan Amotsin pojan näyssä, ja Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Ja Jehiskia nukkui isäinsä kanssa, ja he hautasivat hänen ylemmä Davidin lasten hautoihin. Ja kaikki Juuda ja Jerusalemin asuvaiset tekivät hänelle kunniaa hänen kuollessansa. Ja hänen poikansa Manasse tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasse oli kahdentoistakymmenen ajastaikainen tullessansa kuninkaaksi, ja hallitsi viisi ajastaikaa kuudettakymmentä Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Ja teki pahaa Herran edessä, pakanain kauhistusten jälkeen, jotka Herra Israelin lasten edestä oli ajanut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Ja hän rakensi jälleen korkeudet, jotka hänen isänsä Jehiskia kukistanut oli, ja rakensi Baalille alttareita, ja teki metsistöt, ja kumarsi kaikkea taivaallista sotaväkeä, ja palveli niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Ja hän rakensi myös alttareita Herran huoneesen, josta Herra sanonut oli: Jerusalemissa pitää minun nimeni oleman ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Ja hän rakensi alttareita kaikelle taivaalliselle sotaväelle molempiin Herran huoneen pihoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Ja hän käytti poikiansa tulessa Hinnomin poikain laaksossa, ja valitsi itsellensä päivät, ja otti vaarin lintuin lauluista, ja noitui, ja sääsi velhot ja merkkein tulkitsiat, ja teki paljon pahaa Herran silmäin edessä, kehoittaaksensa häntä vihaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Hän asetti myös valetuita kuvia, jotka hän tehdä antoi Jumalan huoneesen, josta Jumala oli sanonut Davidille ja hänen pojallensa Salomolle: tähän huoneesen ja Jerusalemiin, jonka minä valinnut olen kaikista Israelin sukukunnista, panen minä minun nimeni ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Enkä enää Israelin lasten jalkoja tästä maasta siirrä, jonka minä teidän isillenne säätänyt olen; jos he muutoin pitävät kaikkia, mitä minä heille Moseksen kautta käskenyt olen kaikessa laissa, ja säädyissä ja oikeuksissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Mutta Manasse vietteli Juudan ja Jerusalemin asuvaiset tekemään pahemmin kuin pakanat, jotka Herra Israelin lasten edestä hävittänyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Ja kuin Herra puhui Manasselle ja hänen kansallensa, eikä he sitä totelleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Niin saatti Herra heidän päällensä Assurin kuninkaan sodanpäämiehet; he ottivat Manassen kiinni orjantappurain seasta, ja sitoivat hänen kaksilla vaskikahleilla ja veivät Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Ja kuin hän oli siinä ahdistuksessa, rukoili hän Herraa Jumalaansa ja nöyryytti itsensä suuresti isäinsä Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Ja rukoili häntä hartaasti; ja hän kuuli laupiaasti hänen hartaan rukouksensa ja johdatti hänen jälleen valtakuntaansa Jerusalemiin. Niin Manasse ymmärsi, että Herra on Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Senjälkeen rakensi hän ulkomaisen muurin Davidin kaupunkiin, lännen puoleen, Gihonin laaksoon, josta Kalaporttiin mennään, ja Ophelin ympäri, ja teki sen sangen korkiaksi, ja asetti sodanpäämiehet kaikkiin Juudan vahvoihin kaupunkeihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Ja otti vieraat jumalat ja epäjumalat pois Herran huoneesta, ja kaikki alttarit, jotka hän rakentanut oli Herran huoneen vuorelle ja Jerusalemiin, ja heitti ne kaupungista ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Ja uudisti Herran alttarin, ja uhrasi siellä kiitosuhria ja ylistysuhria, ja käski Juudan palvella Herraa Israelin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Mutta kansa uhrasi vielä korkeuksilla, kuitenkin Herralle Jumalallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Mitä enempää Manassesta sanomista on, ja hänen rukouksestansa Jumalan tykö, ja näkiäin puheesta, jotka Herran Israelin Jumalan nimeen hänen kanssansa puhuneet olivat: katso, ne ovat (kirjoitetut) Israelin kuningasten teoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Ja hänen rukouksensa, ja kuinka häntä kuultiin, ja kaikki hänen syntinsä ja väärät tekonsa, ja paikat, joihin hän korkeudet rakensi ja asetti metsistöt ja valetut epäjumalat, ennenkuin hän nöyryytti itsensä: katso, ne ovat kirjoitetut näkiäin teoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Ja Manasse nukkui isäinsä kanssa, ja he hautasivat hänen omaan huoneeseensa. Ja hänen poikansa Amon tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon oli kahden ajastaikainen kolmattakymmentä tullessansa kuninkaaksi, ja hallitsi kaksi ajastaikaa Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Ja teki pahaa Herran edessä, niinkuin hänen isänsäkin Manasse tehnyt oli; ja Amon uhrasi kaikille epäjumalille, jotka hänen isänsä Manasse tehnyt oli, ja palveli niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Mutta ei hän nöyryyttänyt itseänsä Herran edessä, niinkuin hänen isänsä Manasse itsensä nöyryyttänyt oli; vaan tämä Amon teki paljon syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Ja hänen palveliansa kapinoivat häntä vastaan ja tappoivat hänen omassa huoneessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Niin maan kansa tappoi kaikki ne, jotka olivat liiton tehneet kuningas Amonia vastaan. Ja maan kansa teki hänen poikansa Josian kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josia oli kahdeksan ajastaikainen tullessansa kuninkaaksi, ja hallitsi yhden vuoden neljättäkymmentä Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Ja teki oikein Herran kasvoin edessä, ja vaelsi isänsä Davidin teillä ja ei poikennut oikialle eikä vasemmalle puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Mutta kahdeksantena valtakuntansa vuonna, vielä nuorukaisna ollessansa rupesi hän etsimään isänsä Davidin Jumalaa, ja toisena vuonna toistakymmentä rupesi hän puhdistamaan Juudaa ja Jerusalemia korkeuksista ja metsistöistä, ja epäjumalista ja valetuista kuvista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Ja he kukistivat hänen edessänsä Baalin alttarit, ja hän rikkoi kuvat jotka niiden päällä olivat; hän hakkasi myös metsistöt pois, ja löi epäjumalat ja valetut kuvat murskaksi, ja hajoitti niiden haudoille, jotka niille uhranneet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Ja poltti pappein luut heidän alttarinsa päällä; ja niin puhdisti hän Juudan ja Jerusalemin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Niin myös Manassen, Ephraimin ja Simeonin kaupungeissa, hamaan Naphtaliin asti, heidän korvessansa ympäristöltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'Ja sitte kuin hän oli kukistanut alttarit, metsistöt ja epäjumalat murskaksi musertanut, ja oli kaikki kuvat koko Israelin maalla maahan hakannut, palasi hän Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Mutta valtakuntansa kahdeksantena vuonna toistakymmentä, sittekuin hän maakunnan ja huoneen puhdistanut oli, lähetti hän Saphanin Atsalian pojan, ja Maejesan kaupungin päämiehen, ja Joan Joahaksen pojan, kanslerin, parantamaan Herran Jumalansa huonetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Niin he tulivat Hilkian ylimmäisen papin tykö ja antoivat hänelle rahan, joka Jumalan huoneesen viety oli, jonka ovenvartiat Leviläiset koonneet olivat Manassesta, Ephraimista, ja kaikilta jääneiltä Israelista ja kaikelta Juudalta ja Benjaminilta, ja Jerusalemin asuvaisilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'Ja niin he antoivat sen Herran huoneen teettäjille; ne taas antoivat niille, jotka Herran huoneessa työtä tekivät huoneen rakentamisessa ja parantamisessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Ne sitte antoivat sen sepille ja rakentajille, ostaa hakatuita kiviä ja puita liitteiksi, kaariksi ja maloiksi huoneisiin, jotka Juudan kuninkaat olivat hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Ja miehet tekivät työtä uskollisesti. Ja heidän ylitsensä asetettiin Jahat ja Obadia Leviläiset Merarin lapsista, Sakaria ja Mesullam Kahatilaisten lapsista, työtä kiiruhtamaan. Ja jokainen Leviläinen taisi soittaa kanteletta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Kantajain ja kaikkinaisen työn teettäjäin päällä kaikissa viroissa olivat Leviläisistä kirjoittajat, esimiehet ja ovenvartiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Ja kuin he ottivat rahan ulos, joka Herran huoneesen pantu oli, löysi Hilkia Herran lakikirjan, joka Moseksen kautta annettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Ja Hilkia vastasi ja sanoi Saphanille kirjoittajalle: minä löysin lakikirjan Herran huoneesta; ja Hilkia antoi kirjan Saphanille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Niin Saphan vei kirjan kuninkaalle, ilmoitti kuninkaalle asian ja sanoi: kaikki mitä palvelias käsiin annettu on, sen he tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Ja he kokosivat rahan, joka Herran huoneesta löydetty oli, ja antoivat sen teettäjille ja tekijöille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Niin Saphan kirjoittaja ilmoitti kuninkaalle, sanoen: pappi Hilkia antoi minulle yhden kirjan; ja Saphan luki siitä kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Ja kuin kuningas kuuli lain sanat, repäisi hän vaatteensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Niin kuningas käski Hilkian ja Ahikamin Saphanin pojan, ja Abdonin Miikan pojan, ja Saphanin kirjoittajan, ja Asajan kuninkaan palvelian ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Menkäät ja kysykäät Herralta minun edestäni ja niiden edestä, jotka vielä jääneet ovat Israelissa ja Juudassa, kirjan sanoista, joka löydetty on; sillä Herran viha on hirmuinen, joka meihin on syttynyt, ettei isämme ole pitäneet Herran sanaa ja tehneet niinkuin tässä kirjassa kirjoitettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Niin Hilkia meni niiden kanssa, jotka kuninkaalta lähetetyt olivat, prophetissan Huldan, Sallumin Takehatin pojan, Hasran pojanpojan, vaatetten kätkiän emännän tykö, joka asui toisella puolella Jerusalemissa, ja puhuivat sitä hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Ja hän sanoi heille: näin sanoo Herra Israelin Jumala: sanokaat sille miehelle, joka teidät minun tyköni lähettänyt on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Näin sanoo Herra: katso, minä saatan onnettomuuden tämän paikan päälle ja sen asuvaisten päälle, ja kaikki kiroukset, jotka siinä kirjassa kirjoitetut ovat, joka Juudan kuninkaan edessä luettiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Että he ovat hyljänneet minun ja suitsuttaneet vieraille jumalille, vihoittaaksensa minua kaikilla kättensä töillä, ja minun vihani syttyy tämän paikan päälle ja ei pidä sammutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Ja teidän pitää näin sanoman Juudan kuninkaalle, joka teidät lähettänyt on kysymään Herralta: näin sanoo Herra Israelin Jumala: näistä sanoista, jotka sinä kuulit:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Että sinun sydämes on pehmentynyt ja sinä olet sinus nöyryyttänyt Jumalan edessä, koskas hänen sanansa kuulit tätä paikkaa vastaan ja sen asuvaisia vastaan, ja olet itses nöyryyttänyt minun edessäni, repinyt vaattees ja itkenyt minun edessäni, niin minä myös olen sinua kuullut, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Katso, minä kokoon sinun isäis tykö, ettäs kootaan hautaas rauhassa, ettei sinun silmäs pidä näkemän kaikkea sitä onnettomuutta, jonka minä tämän paikan päälle ja sen asuvaisten päälle saatan. Ja he sanoivat sen kuninkaalle jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Niin kuningas lähetti ja kokosi kaikki vanhimmat Juudasta ja Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Ja kuningas meni ylös Herran huoneesen, ja kaikki Juudan miehet ja Jerusalemin asuvaiset, ja papit ja Leviläiset, ja kaikki kansa, sekä suuret että pienet; ja luettiin heidän korvainsa kuullen kaikki liitonkirjan sanat, joka oli löydetty Herran huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Niin kuningas seisoi siallansa ja teki liiton Herran edessä, että heidän piti vaeltaman Herran jälkeen ja pitämän hänen käskynsä, todistuksensa ja säätynsä kaikesta sydämestänsä ja kaikesta sielustansa, ja tekemän kaikkein liiton sanain jälkeen, kuin ovat kirjoitetut tässä kirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Ja hän antoi seisoa kaikki, jotka olivat Jerusalemissa ja Benjaminissa. Ja Jerusalemin asuvaiset tekivät Jumalan, isäinsä Jumalan liiton jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Ja Josia otti kaikki kauhistukset pois kaikesta maasta, joka Israelin lasten oma oli, ja vaati kaikkia, jotka Israelista löydettiin, palvelemaan Herraa Jumalaansa; kaikkena hänen elinaikanansa ei he luopuneet Herrasta isäinsä Jumalasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Ja Josia piti Jerusalemissa pääsiäistä Herralle ja he teurastivat pääsiäisen neljäntenä päivänä toistakymmentä, ensimmäisellä kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Ja hän asetti papit vartioihinsa ja vahvisti heitä virkaansa Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Ja hän sanoi Leviläisille, jotka koko Israelia opettivat ja Herran pyhitetyt olivat: pankaat pyhä arkki huoneesen, jonka Salomo Davidin poika Israelin kuningas on rakentaa antanut, ja ei teidän pidä sitä kantaman teidän olallanne. Niin palvelkaat nyt Herraa teidän Jumalaanne ja hänen kansaansa Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Ja valmistakaat teitänne isäinne huoneen järjestyksen jälkeen, niinkuin se on kirjoitettu Davidilta Israelin kuninkaalta, ja niinkuin se on kirjoitettu hänen pojaltansa Salomolta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'Ja seisokaat pyhässä, isäin huoneen järjestyksen jälkeen, teidän veljeinne seassa, jotka ovat kansasta syntyneet, ja Leviläisten isäin huoneen järjestyksen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Teurastakaat pääsiäinen ja pyhittäkäät teitänne, valmistakaat myös veljenne, tekemään Herran sanan jälkeen Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Ja Josia antoi ylennysuhriksi yhteisen kansan edestä karitsoita ja vohlia, (kaikki pääsiäiseksi niille, jotka läsnä olivat,) kolmekymmentä tuhatta, niin myös kolmetuhatta härkää. Ja nämät olivat kuninkaan hyvyydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Ja hänen päämiehensä antoivat myös mielellänsä kansan edestä ylennykseksi papeille ja Leviläisille, (jotka olivat: Hilkia, Sakaria ja Jehiel päämiehet Jumalan huoneessa, papeille antoivat he) pääsiäisuhriksi, kaksituhatta ja kuusisataa (karitsaa ja vohlaa), niin myös kolmesataa härkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Mutta Kanania ja Semaja, ja Netaneel hänen veljensä, ja Hasabia, Jejel ja Josabad Leviläisten ylimmäiset antoivat ylennyksen Leviläisille pääsiäisuhriksi, viisituhatta (karitsaa ja vohlaa), niin myös viisisataa härkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Ja niin palvelus asetettiin; ja papit seisoivat siassansa ja Leviläiset järjestyksessänsä, kuninkaan käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Ja he teurastivat pääsiäisen, ja papit priiskottivat niiden veren, ja Leviläiset ottivat pois nahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Ja he eroittivat polttouhrin, antaaksensa isäin huonetten järjestyksen jälkeen yhteiselle joukolle, uhrattaa Herralle, niinkuin kirjoitettu on Moseksen kirjassa; niin tekivät he myös härkäin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Ja he paistivat pääsiäislampaan tulella, lain jälkeen, mutta pyhitetyn keittivät he padoissa, kattiloissa ja pannuissa, ja tekivät sen kiiruusti tariten kaikelle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Sitte valmistivat he itsellensä ja papeille; sillä papeilla Aaronin pojilla oli tekemistä polttouhrin ja lihavuuden kanssa, hamaan yöhön asti; sentähden Leviläisten piti itsellensä ja papeille Aaronin pojille jotain valmistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Ja viesaajat Asaphin lapset seisoivat siassansa Davidin käskyn jälkeen, ja Asaphin ja Hemanin ja Jedutunin kuninkaan näkiän, ja ovenvartiat jokaisen oven tykönä, eikä lähteneet virastansa, sillä Leviläiset heidän veljensä valmistivat heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Niin oli kaikki Herran palvelus toimitettu sinä päivänä, pidettää pääsiäistä ja uhrata polttouhria Herran alttarilla, kuningas Josian käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Niin pitivät Israelin lapset, jotka siinä läsnä olivat, pääsiäistä siihen aikaan, ja happamattoman leivän juhlaa, seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Ei yhtään senkaltaista pääsiäistä ollut Israelissa pidetty, niinkuin tämä, hamasta Samuel prophetan ajasta. Ja ei yksikään kuningas Israelissa ollut senkaltaista pääsiäistä pitänyt, kuin Josia piti, ja papit, Leviläiset ja koko Juuda, ne jotka läsnä olivat Israelista ja asuivat Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Josian valtakunnan kahdeksantena vuonna toistakymmentä pidettiin tämä pääsiäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Kaikkein näiden jälkeen, kuin Josia oli valmistanut huoneen, meni Neko Egyptin kuningas sotimaan Karkemesta vastaan Phratin tykönä, ja Josia meni häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Mutta hän lähetti sanan hänen tykönsä ja käski hänelle sanoa: mitä minun on sinun kanssas tekemistä, Juudan kuningas? En minä tule sinua vastaan tänäpänä, mutta sitä huonetta, joka sotii minua vastaan. Ja Jumala on sanonut, että minun pitää rientämän: lakkaa tekemästä Jumalaa vastaan, joka minun kanssani on, ettei hän sinua hukuttaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mutta ei Josia kääntänyt kasvojansa hänestä, vaan asetti itsensä sotimaan häntä vastaan, ja ei totellut Nekon sanoja Jumalan suusta, vaan tuli sotimaan Megiddon kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Ja ampujat ampuivat kuningas Josiaa. Ja kuningas sanoi palvelioillensa: viekäät minut tästä pois, sillä minä olen sangen pahoin haavoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Ja hänen palveliansa ottivat hänen vaunusta ja panivat hänen toiseen vaunuunsa, ja veivät hänen Jerusalemiin. Ja hän kuoli ja haudattiin isäinsä hautoihin. Ja koko Juuda ja Jerusalem itkivät Josiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Ja Jeremia itki Josiaa, ja kaikki laulajat, miehet ja vaimot, murehtivat häntä itkuvirsillä hamaan tähän päivään asti. Ja he tekivät siitä tavan Israelissa; katso, se on kirjoitettu valitusvirsissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Mitä enempää Josiasta sanomista on ja hänen laupiudestansa kirjoituksen jälkeen Herran laissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Ja hänen teoistansa, ensimäisistä ja viimeisistä: katso, se on kirjoitettu Israelin ja Juudan kuningasten kirjassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Ja maan kansa otti Joahaksen Josian pojan, ja tekivät hänen kuninkaaksi isänsä siaan Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Kolmen vuotinen kolmattakymmentä oli Joahas tullessansa kuninkaaksi, ja hallitsi kolme kuukautta Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Sillä Egyptin kuningas pani hänen pois Jerusalemista, ja sakotti maan sataan leiviskään hopiaa ja leiviskään kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Ja Egyptin kuningas teki Eliakimin hänen veljensä Juudan ja Jerusalemin kuninkaaksi, ja muutti hänen nimensä Jojakimiksi. Mutta Neko otti hänen veljensä Joahaksen ja vei Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Viiden vuotinen kolmattakymmentä oli Jojakim tullessansa kuninkaaksi, ja hallitsi yksitoistakymmentä vuotta Jerusalemissa, ja teki pahaa Herran Jumalansa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Ja Nebukadnetsar Babelin kuningas meni häntä vastaan, ja sitoi hänen kaksilla vaskikahleilla viedäksensä Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Ja Nebukadnetsar vei muutamia Herran huoneen astioita Babeliin ja pani ne templiinsä Babelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Mitä muuta Jojakimista sanomista on, ja hänen kauhistuksistansa, jotka hän teki ja hänessä löydetty oli: katso, ne ovat kirjoitetut Israelin ja Juudan kuningasten kirjassa. Ja hänen poikansa Jojakin tuli kuninkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Kahdeksan vuotinen oli Jojakin tullessansa kuninkaaksi, ja hallitsi kolme kuukautta ja kymmenen päivää Jerusalemissa, ja teki pahaa Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Kuin vuosi kulunut oli, lähetti Nebukadnetsar ja antoi tuoda hänen Babeliin, kallisten Herran huoneen astiain kanssa, ja teki Zidkian hänen veljensä Juudan ja Jerusalemin kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Yhden vuotinen kolmattakymmentä oli Zidkia tullessansa kuninkaaksi, ja hallitsi yksitoistakymmentä vuotta Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Ja teki pahaa Herran Jumalansa edessä ja ei nöyryyttänyt itsiänsä prophetan Jeremian edessä, joka puhui Herran suusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Hän luopui myös Nebukadnetsarista Babelin kuninkaasta, joka häntä Jumalan kautta vannottanut oli, ja tuli uppiniskaiseksi ja kovetti sydämensä, niin ettei hän ollenkaan tahtonut itsiänsä kääntää Herran Israelin Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Ja kaikki pappein päämiehet ja kansa tekivät myös syntiä suuresti kaikkinaisten pakanain kauhistusten jälkeen, ja saastuttivat Herran huoneen, jonka hän oli pyhittänyt Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Ja Herra heidän isäinsä Jumala lähetti heidän tykönsä varhain ja usiasti sanansa saattajain kautta; sillä hän armahti kansansa ja majansa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mutta he pilkkasivat Jumalan lähetyssanoja, ja katsoivat hänen sanansa ylön, ja häpäisivät hänen prophetaitansa, siihenasti että Herran viha kasvoi hänen kansansa päälle, niin ettei heillä enää parannusta ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Niin hän saatti heidän ylitsensä Kaldealaisten kuninkaan, ja hän antoi tappaa heidän nuorukaisensa miekalla heidän pyhänsä huoneessa, eikä armahtanut nuorukaisia eli neitseitä, taikka vanhoja eli ijällisiä isiä; kaikki antoi hän hänen käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Ja kaikki Jumalan huoneen astiat, suuret ja pienet, ja Herran huoneen tavarat, kuninkaan ja hänen päämiestensä tavarat: ne kaikki vei hän pois Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Ja he polttivat Jumalan huoneen ja kukistivat Jerusalemin muurin, ja kaikki heidän koriat huoneensa poltettiin tulella, niin että kaikki heidän kalliit kalunsa hukutettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Ja ne, jotka olivat miekalta päässeet, vietiin Babeliin; ja he olivat hänen ja hänen poikainsa orjat, siihenasti että Persian valtakunta hallitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Että täytettäisiin Herran sana, puhuttu Jeremian suun kautta, ja siihenasti sai maa kyllä sabbatinsa; sillä koko hävityksen aikana oli lepo, siihenasti kuin seitsemänkymmentä ajastaikaa täytettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Mutta ensimäisenä Persian kuninkaan Koreksen vuonna, (että täytettäisiin Herran sana, sanottu Jeremian suun kautta), herätti Herra Koreksen Persian kuninkaan hengen, että hän antoi kuuluttaa koko valtakunnassansa, niin myös kirjoitusten kautta, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Näin sanoo Kores Persian kuningas: Herra taivaan Jumala on antanut minulle kaikki valtakunnat maalla, ja on käskenyt minun rakentaa hänellensä huoneen Jerusalemissa, joka on Juudassa. Kuka nyt on teidän seassansa kaikesta hänen kansastansa? Herra hänen Jumalansa olkoon hänen kanssansa, ja hän menköön sinne ylös!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Ensimäisenä Koreksen Persian kuninkaan vuonna, että Herran sana täytettäisiin, joka oli puhuttu Jeremian suun kautta, herätti Herra Koreksen Persian kuninkaan hengen kuuluttamaan koko valtakunnassansa, ja myös kirjoituksella, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Näin sanoo Kores Persian kuningas: Herra taivaan Jumala on antanut minulle kaikki maan valtakunnat ja käskenyt minun rakentaa hänellensä huoneen Jerusalemiin, joka on Juudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kuka on teidän seassanne kaikesta hänen kansastansa? hänen Jumalansa olkoon hänen kanssansa! ja hän menköön Jerusalemiin, joka on Juudassa, ja rakentakaan Herran Israelin Jumalan huoneen, hän on Jumala, joka Jerusalemissa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Ja kaikkia jääneitä kaikissa paikoissa, kussa he muukalaisina ovat, pitää mielellänsä autettaman sen paikan kansalta hopialla ja kullalla, tavaralla ja juhdilla Jumalan huoneesen, joka on Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Niin valmistivat itsensä isäin päämiehet Juudasta ja Benjaminista, niin myös papit ja Leviläiset, kaikki, jotka Jumalan henki kehoitti menemään ylös, rakentamaan Herran huonetta, joka on Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Ja kaikki, jotka olivat heidän ympärillänsä, vahvistivat heidän kätensä hopia- ja kulta- astioilla, tavaralla ja juhdilla ja kalliilla kaluilla, paitsi mitä he mielellänsä uhrasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Kuningas Kores myös toi Herran huoneen astiat, jotka Nebukadnetsar oli ottanut Jerusalemista ja pannut jumalansa huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Mutta Kores, Persian kuningas, otti ne ulos rahanhaltian Mitridatin käden kautta, joka ne luki Juudan päämiehelle Sesbatsarille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Ja tämä on niiden luku: kolmekymmentä kultamaljaa, tuhannen hopiamaljaa, ja yhdeksänkolmattakymmentä veistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Kolmekymmentä kultaista kuppia, ja toisia hopeaisia maljoja neljäsataa ja kymmenen, ja muita astioita tuhannen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Niin että kaikkia astioita, sekä kullasta että hopiasta, oli viisituhatta ja neljäsataa: ne kaikki vei Sesbatsar niiden kanssa, jotka Babelin vankeudesta menivät Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Nämä ovat maakunnan lapset jotka läksivät vankeudesta jotka Nebukadnetsar Babelin kuningas oli vienyt Babeliin, ja tulivat Jerusalemiin ja Juudaan jälleen, kukin kaupunkiinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Jotka tulivat Serubbabelin, Jesuan, Nehemian, Serajan, Reellajan, Mordekain, Bilsanin, Misparin, Bigvain, Rehumin ja Baanan kanssa; tämä on Israelin kansan miesten luku:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paroksen lapset, kaksituhatta, sata ja kaksikahdettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sephatian lapset, kolmesataa ja kaksikahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Aran lapset, seitsemänsataa ja viisikahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Pahatmoabin lapset, Jesuan ja Joabin lasten seassa, kaksituhatta, kahdeksansataa ja kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Elamin lapset, tuhannen kaksisataa ja neljäkuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Sattun lapset, yhdeksänsataa ja viisiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Sakkain lapset, seitsemänsataa ja kuusikymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Banin lapset, kuusisataa ja kaksiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Bebain lapset, kuusisataa ja kolmekolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Asgadin lapset, tuhannen, kaksisataa ja kaksikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikamin lapset, kuusisataa ja kuusiseitsemättäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvain lapset, kaksituhatta ja kuusikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Adinin lapset, neljäsataa ja neljäkuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Aterin lapset Jehiskiasta, yhdeksänkymmentä ja kahdeksan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Betsain lapset, kolmesataa ja kolmekolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Joran lapset, sata ja kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Hasumin lapset, kaksisataa ja kolmekolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibbarin lapset, yhdeksänkymmentä ja viisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Betlehemin lapset, sata ja kolmekolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Netophan miehet, kuusikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Anatotin miehet, sata ja kahdeksankolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Asmavetin lapset, kaksiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Kirjatjearimin lapset Kephiran ja Berotin, seitsemänsataa ja kolmeviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Raman ja Gabaan lapset, kuusisataa ja yksikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mikmaan miehet, sata ja kaksikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Betelin ja Ain miehet, kaksisataa ja kolmekolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Nebon lapset, kaksikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Magbiksen lapset, sata kuusikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Toisen Elamin lapset, tuhannen, kaksisataa ja neljäkuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Harimin lapset, kolmesataa ja kaksikymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Lodin, Hadidin ja Onon lapset, seitsemänsataa ja viisikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Jerihon lapset, kolmesataa ja viisiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Senaan lapset, kolmetuhatta, kuusisataa ja kolmekymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Papit: Jedajan lapset Jesuan huoneesta, yhdeksänsataa ja kolmekahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Immerin lapset, tuhannen ja kaksikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pashurin lapset, tuhannen, kaksisataa ja seitsemänviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Harimin lapset, tuhannen ja seitsemäntoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leviläiset: Jesuan ja Kadmielin lapset, Hodavian lapsista, neljäkahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Veisaajat: Asaphin lapset, sata ja kahdeksankolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Ovenvartiain lapset: Salumin lapset, Aterin lapset, Talmonin lapset, Akkubin lapset, Hatitan lapset ja Sobain lapset, kaikkiansa sata ja yhdeksänneljättäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Netinimit: Zihan lapset, Hasuphan lapset, Tabaotin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Keroksen lapset, Siahan lapset, Padonin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebanan lapset, Hagaban lapset, Akkubin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Hagabin lapset, Samlain lapset, Hananin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Giddelin lapset, Gaharin lapset, Reajan lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Resinin lapset, Rekodan lapset, Gassamin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Ussan lapset, Pasean lapset, Besain lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asnan lapset, Meunimin lapset, Rephusimin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbukin lapset, Hakuphan lapset, Harhurin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Batslutin lapset, Mehidan lapset, Harsan lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkoksen lapset, Siseran lapset, Taman lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Netsian lapset, Hatiphan lapset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Salomon palveliain lapset: Sotain lapset, Sopheretin lapset, Perudan lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaelan lapset, Darkonin lapset, Giddelin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Sephatian lapset, Hattilin lapset, PokeretZebaimin lapset, Amin lapset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Kaikki Netinimit ja Salomon palveliain lapset kolmesataa, yhdeksänkymmentä ja kaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Nämät myös menivät ylös Telmelasta, Telharsasta: Kerub, Addani ja Immer, jotka ei tietäneet isäinsä huonetta sanoa ja siementänsä, olivatko Israelista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delajan lapset, Tobijan lapset, Nekodan lapset, kuusisataa ja kaksikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Ja pappein lapsista: Habajan lapset, Hakotsin lapset, Barsillain lapset, joka otti itsellensä emännän Barsillain Gileadilaisen tyttäristä, ja kutsuttiin heidän nimellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Nämä etsivät sukukuntansa polvilukukirjaa, ja ei sitä löydetty, sentähden he pantiin pois pappeudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Ja Tirsata sanoi heille, ettei heidän pitänyt syömän kaikkein pyhimmästä, ennenkuin pappi seisois valkeudessa ja täydellisyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Koko joukko yhteen oli kaksiviidettäkymmentä tuhatta, kolmesataa ja kuusikymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Paitsi heidän palvelioitansa ja piikojansa, joita oli seitsemäntuhatta, kolmesataa ja seitsemänneljättäkymmentä; ja heillä oli veisaajia, miehiä ja vaimoja, kaksisataa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Seitsemänsataa ja kuusineljättäkymmentä heidän hevostansa; kaksisataa ja viisiviidettäkymmentä heidän muuliansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Neljäsataa ja viisineljättäkymmentä heidän kameliansa; kuusituhatta, seitsemänsataa ja kaksikymmentä aasia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Ja monikahdat isäin päämiehistä, kuin he menivät Herran huoneesen, joka on Jerusalemissa, uhrasivat hyvällä mielellä Jumalan huoneen rakennukseksi paikallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'Ja he antoivat varansa jälkeen rakennuksen tavaraksi yhdenseitsemättäkymmentä tuhatta kultapenninkiä, ja viisituhatta leiviskää hopiaa, ja sata papin hametta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Niin papit, Leviläiset, ja muutamat kansasta, veisaajat, ja ovenvartiat ja Netinimit asuivat kaupungeissansa, ja koko Israel myös kaupungeissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Kuin seitsemäs kuukausi oli tullut ja Israelin lapset olivat kaupungeissansa, tuli kansa kokoon niinkuin yksi mies Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Niin nousi Jesua Jotsadakin poika, ja papit hänen veljensä, ja Serubbabel Sealtielin poika ja hänen veljensä ja rakensivat Israelin Jumalan alttarin uhrataksensa sen päällä polttouhria, niinkuin kirjoitettu on Moseksen, Jumalan miehen, laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'Ja he laskivat alttarin perustuksensa päälle, vaikka he pelkäsivät sen maan kansoja; ja he uhrasivat sen päällä Herralle polttouhria aamulla ja ehtoolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Ja he pitivät lehtimajan juhlaa niinkuin kirjoitettu on, ja tekivät polttouhria joka päivä, sen luvun jälkeen kuin tapa oli, kunkin päivänänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Senjälkeen alinomaisia polttouhreja, ja uuden kuun, ja kaikkein Jumalalle pyhitettyin juhlain, ja kaikkinaisia mieliuhreja, joita he hyvällä mielellä tekivät Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Seitsemännen kuukauden ensimäisenä päivänä rupesivat he uhraamaan Herralle polttouhria; mutta ei Herran templin perustus ollut vielä laskettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Ja he antoivat kivenhakkaajille ja taitavaille työväelle rahaa, ja ruokaa ja juomaa, ja öljyä Sidonilaisille ja Tyrolaisille, että he toisivat heille sedripuita Libanonista Japhoon merta myöten, Koreksen Persian kuninkaan suomasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Mutta toisena vuonna sittekuin he tulivat Jerusalemiin Herran huoneen tykö, toisena kuukautena, rupesi Serubbabel Sealtielin poika, ja Jesua Jotsadakin poika, ja muut heidän jääneet veljensä, papit ja Leviläiset, ja kaikki, jotka vankeudesta tulivat Jerusalemiin, ja panivat kahdenkymmenen ajastaikaiset ja sitä vanhemmat Leviläiset Herran huoneen työn teettäjiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Ja Jesua seisoi poikinensa ja veljinensä, ja Kadmiel poikinensa, ja Juudan lapset, niinkuin yksi mies teettämässä työväkeä Herran huoneessa, Henadadin lapset poikinensa, ja Leviläiset veljinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Ja kuin rakentajat laskivat Herran templin perustuksen, asettivat he papit puetettuina, vaskitorvien kanssa, ja Leviläiset Asaphin pojat kanteleilla, kiittämään Herraa Davidin Israelin kuninkaan sanoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Ja he veisasivat vuorottain ylistäissänsä ja kiittäissänsä Herraa, että hän on hyvä ja hänen laupiutensa pysyy ijankaikkisesti Israelin ylitse. Ja kaikki kansa huusi korkialla äänellä ja kiitti Herraa, että Herran huoneen perustus oli laskettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Mutta moni vanhoista papeista, ja Leviläisistä ja isäin päämiehistä, jotka olivat nähneet ensimäisen huoneen perustuksellansa, niin myös tämän huoneen silmäinsä edessä, itkivät suurella äänellä; ja moni huusi korkialla äänellä ilon tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Että se huuto oli niin suuri, ettei kansa eroittanut ilon ääntä itkun äänestä; sillä kansa huusi korkialla äänellä, että se ääni kauvas kuului.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Mutta kuin Juudan ja Ben-Jaminin vihamiehet kuulivat, että ne, jotka vankeudesta olivat lähteneet, rakensivat Herralle Israelin Jumalalle templiä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Tulivat he Serubbabelin ja isäin päämiesten tykö ja sanoivat heille: me rakennamme teidän kanssanne; sillä me etsimme teidän Jumalaanne niinkuin tekin, ja emme ole sitte uhranneet kuin Asserhaddon Assurin kuningas meidät tänne vei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Mutta Serubbabel ja Jesua ja muut Israelin isäin päämiehet vastasivat: ei sovi teidän ja meidän rakentaa meidän Jumalallemme huonetta; mutta me rakennamme yksin Herralle Israelin Jumalalle huoneen, niinkuin Kores Persian kuningas meitä käski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Niin sen maakunnan väki heikensi Juudan kansan kädet ja peljätti rakentamasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Ja palkkasivat neuvonantajia heitä vastaan, estämään heidän neuvoansa, niinkauvan kuin Kores Persian kuningas eli, Dariuksen Persian kuninkaan valtakuntaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Mutta kuin Ahasverus tuli kuninkaaksi, hänen valtakuntansa alussa, kirjoittivat he kanteen Juudan ja Jerusalemin asujamia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Ja Artahsastan aikana kirjoitti Bislam, Mitridat, Tabeel ja muut heidän seurastansa Artahsastalle Persian kuninkaalle. Ja kirja oli kirjoitettu Syrian kielellä ja tulkittu Syrian kielellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum kansleri ja Simsai kirjoittaja kirjoittivat kirjan Jerusalemia vastaan kuningas Artahsastalle näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Rehum kansleri ja Simsai kirjoittaja, ja muut heidän kanssaveljensä Dinasta, Apharsakista ja Tarpelasta, Persiasta, Arakasta, Babelista, Susanista, Dehasta ja Elamista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'Ja muut kansat, jotka suuri ja kuuluisa Asnappar toi tänne, ja pani heidät asumaan Samarian kaupunkeihin, ja ne muut toisella puolen virtaa, sillä ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Ja kirja, jonka he lähettivät kuningas Artahsastalle, oli näin kirjoitettu: palvelias, miehet, jotka asuvat toisella puolella virtaa, jotka siihen aikaan olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Se olkoon kuninkaalle tiettävä, että Juudalaiset, jotka sinun tyköäs tulivat meidän tykömme Jerusalemiin, rakentavat kapinallista ja pahaa kaupunkia, ja ovat perustaneet ja korottaneet muurit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Niin olkoon nyt kuninkaalle tiettävä, että jos se kaupunki rakennetaan ja muurit perustetaan, niin ei he sinulle anna tullia, veroa ja ajastaikaista ulostekoa; ja sinä vahingoitset kuningasten veron.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Nyt siis, että meillä on ravinto kuninkaan huoneesta, ei sovi meidän nähdä kuninkaan ylönkatsetta; sentähden olemme me lähteneet matkaan, ilmoittamaan sitä kuninkaalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Ettäs etsisit isäis aikakirjoista, ja sinä löydät niistä ja saat tietää tämän olevan kapinallisen ja vahingollisen kaupungin kuninkaille ja maakunnille, joka saatti jo vanhasta muutkin luopumaan; jonkatähden myös tämä kaupunki on autioksi tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Sentähden me annamme kuninkaan tietää, että jos tämä kaupunki rakennetaan ja muurit tehdään, niin et sinä toista puolta virtaa saa pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Niin kuningas lähetti vastauksen Rehumille kanslerille ja Simsaille kirjoittajalle, ja muille heidän kanssaveljillensä, jotka Samariassa asuivat, ja muille, jotka toisella puolella virtaa olivat: rauhaa tällä ajalla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Lähetyskirja, jonka te meidän tykömme lähetitte, on luettu julkisesti minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Ja on minulta käsketty etsittää, ja on löydetty sen kaupungin jo vanhaan nousseen kuninkaita vastaan, ja luopuneen, niin että kapina on siinä noussut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Ja että Jerusalemissa ovat olleet väkevät kuninkaat ja vallinneet kaikki toisella puolella virtaa, ja heille on annettu tulli, vero ja ajastaikainen ulosteko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Tehkäät siis tämän käskyn jälkeen: estäkäät niitä miehiä rakentamasta kaupunkia, siihenasti kuin minä annan käskyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Niin karttakaat teitänne erehdyksestä tässä asiassa. Miksi semmoinen turmelus pitäis valtaa saaman kuninkaille vahingoksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Kuin kuningas Artahsastan kirja luettiin Rehumin, Simsain kirjoittajan ja heidän kanssaveljeinsä edessä, menivät he kiiruusti Jerusalemiin Juudalaisten tykö ja estivät heidät käsivarrella ja väkevyydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Silloin lakattiin Jumalan huoneen työstä Jerusalemissa, niin että se jäi Dariuksen Persian kuninkaan toiseen vuoteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Ja prophetat Haggai ja Sakaria, Iddon poika, ennustivat Juudalaisille, jotka olivat Juudassa ja Jerusalemissa, Israelin Jumalan nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Silloin nousivat Serubbabel Sealtielin poika, Jesua Jotsadakin poika ja rupesivat rakentamaan Jumalan huonetta Jerusalemissa ja Jumalan prophetat heidän kanssansa, auttain heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Siihen aikaan tuli Tatnai heidän tykönsä, joka oli maaherra toisella puolella virtaa, ja Setarbosnai, ja heidän kanssaveljensä, ja sanoivat näin heille: kuka on käskenyt rakentaa tätä huonetta ja näitä muureja perustaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Niin me sanoimme heille, mitkä niiden miesten nimet olivat, jotka tätä rakennusta rakensivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Ja heidän Jumalansa silmä tuli Juudan vanhimpain päälle, ettei sitä heiltä niinkauvaksi estetty, kuin sanoma vietiin Dariuksen tykö; ja lähetyskirja tuli siitä asiasta takaperin jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Ja kirja, jonka Tatnai maaherra toisella puolella virtaa, ja Setarbosnai, ja hänen kanssaveljensä Apharsakista, jotka olivat toisella puolella virtaa, lähettivät kuningas Dariukselle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Ja sanat, jotka he lähettivät hänelle olivat näin kirjoitetut: kuninkaalle Dariukselle (toivotetaan) kaikkea rauhaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Olkoon kuninkaalle tiettävä, että me tulimme Juudan maakuntaan, kaikkein suurimman Jumalan huoneen tykö; ja sitä rakennetaan jaloista suurista kivistä, hirret pannaan seiniin, ja työ joutuu ja menestyy heidän käsissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Niin me kysyimme vanhimmilta ja sanoimme heille: kuka teille antoi käskyn rakentaa tätä huonetta ja näitä muureja perustaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Me kysyimme myös heiltä heidän nimensä, antaaksemme sinulle ne tietää, ja me kirjoitimme niiden miesten nimet, jotka heidän päämiehensä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Ja senkaltaisen sanan he meille vastasivat, sanoen: me olemme taivaan ja maan Jumalan palveliat, ja rakennamme tätä huonetta, joka ennen monta vuotta oli rakennettu, jonka väkevä Israelin kuningas oli rakentanut ja pannut ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Mutta sittekuin meidän isämme vihoittivat taivaan Jumalan, antoi hän heidät Nebukadnetsarin käsiin, Kaldealaisten kuninkaan Babelista; hän jaotti tämän huoneen ja vei kansan Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Mutta ensimäisenä Koreksen, Babelin kuninkaan vuonna, käski kuningas Kores tämän Jumalan huoneen rakentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Ja ne kulta astiat ja hopia astiat, mitkä olivat siinä Jumalan huoneessa, jotka Nebukadnetsar otti Jerusalemin templistä ja vei Babelin templiin, ne otti kuningas Kores Babelin templistä ja antoi yhdelle Sesbatsar nimeltä, jonka hän pani heidän päämieheksensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Ja sanoi hänelle: ota nämät astiat, mene ja vie ne Jerusalemin templiin, ja anna Jumalan huone rakennettaa paikallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Silloin tuli se Sesbatsar ja laski Jumalan huoneen perustuksen Jerusalemissa; ja siitä ajasta niin tähän asti on sitä rakennettu, ja ei ole vielä täytetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Nyt siis jos kuninkaalle kelpaa, niin antakaan etsiä kuninkaan tavarahuoneessa, joka on Babelissa, jos se on käsketty Kores kuninkaalta, heidän rakentaa tätä Jumalan huonetta, joka on Jerusalemissa, ja antakoon tästä asiasta meidän tietää kuninkaan tahdon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Niin Darius kuningas käski etsiä kantselissa, kuninkaan tavarahuoneessa Babelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Silloin löydettiin Ahmetan linnasta, joka on Median maakunnassa, kirja, jossa oli näin muistoksi kirjoitettu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Ensimäisenä kuningas Koreksen vuonna käski kuningas Kores rakentaa Jumalan huoneen Jerusalemissa paikaksi, jossa uhrataan, ja laskea perustuksen, kuusikymmentä kyynärää korkiaksi ja kuusikymmentä kyynärää leviäksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Kolme seinää vuolluista kivistä ja yksi seinä uusista puista; ja että kuninkaan huoneesta piti annettaman ylöspitämys;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Piti myös Jumalan huoneen hopiaiset ja kultaiset astiat, jotka Nebukadnetsar oli ottanut Jerusalemin kirkosta ja vienyt Babeliin, annettaman ja vietämän jälleen templiin, Jerusalemiin, pantavaksi siallensa Jumalan huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Niin olkaat nyt erinänne heistä, sinä Tatnai maaherra sillä puolella virtaa, ja sinä Setarbosnai, ja teidän kanssaveljenne Apharsakista, te jotka olette sillä puolella virtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Antakaat heidän tehdä työtä Jumalan huoneessa, että Juudalaisten päämies ja heidän vanhimpansa saisivat Jumalan huoneen rakennetuksi entiselle paikallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'On myös käsketty minulta, mitä Juudan vanhimmille pitää annettaman, että he rakentaisivat tämän Jumalan huoneen, nimittäin: että sille väelle pitää juuri kiiruusti ylöspitämys annettaman kuninkaan verokalusta siltä puolelta virtaa, ja ei heitä estettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Ja mitä tarvitaan mullia, ja oinaita, ja karitsoita uhriksi taivaan Jumalalle, nisuja, suoloja, viinaa ja öljyä, Jerusalemin pappein tavan jälkeen, niin pitää heille annettaman joka päivä ilman yhdettäkään erehdyksetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Että he uhraisivat taivaan Jumalalle makiaa hajua, ja rukoilisivat kuninkaan ja hänen lastensa elämän edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Tämä käsky on minulta annettu, että kuka ikänä nämät sanat muuttaa, hänen huoneestansa pitää yksi hirsi reväistämän, joka pitää nostettaman ylös, ja hän siihen ripustettaman, ja hänen huoneensa pitää lokaläjäksi tehtämän sen työn tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Jumala, joka on nimensä pannut asumaan siinä, tappakoon kaikki ne kuninkaat ja kansat, jotka ojentavat kätensä muuttamaan taikka särkemään tätä Jumalan huonetta, joka on Jerusalemissa. Minä Darius olen tämän käskyn antanut, ja se pitää juuri nopiasti tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Silloin Tatnai maaherra sillä puolella virtaa, ja Setarbosnai ja heidän kanssaveljensä, joiden tykö kuningas Darius oli lähettänyt, tekivät sen nopiasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Ja Juudalaisten vanhimmat rakensivat, ja se menestyi, Haggain prophetan ja Sakarian Iddon pojan ennustuksen jälkeen; ja he rakensivat ja päättivät sen Israelin Jumalan käskyn jälkeen; ja Koreksen, Dariuksen ja Artahsastan Persian kuninkain käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Ja huone päätettiin täydellisesti kolmanteen päivään asti Adarin kuuta, kuudentena kuningas Dariuksen valtakunnan vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Ja Israelin lapset, papit, Leviläiset ja muut, jotka vankeudesta tulleet olivat, pitivät ilolla Jumalan huoneen vihkimistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'Ja uhrasivat tässä Jumalan huoneen vihkimyksessä sata mullia, kaksisataa oinasta, neljäsataa karitsaa ja kaksitoistakymmentä kaurista, koko Israelin syntein edestä, Israelin sukukuntain luvun jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Ja asettivat papit vuoroonsa ja Leviläiset järjestykseensä, palvelemaan Jumalaa, joka on Jerusalemissa, niinkuin Moseksen kirjassa on kirjoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Ja ne, jotka vankeudesta olivat tulleet, pitivät pääsiäistä neljäntenä päivänä toistakymmentä ensimäisestä kuukaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Sillä papit ja Leviläiset olivat puhdistaneet itsensä, niin että he kaikki olivat puhtaat niinkuin yksi mies; ja he teurastivat pääsiäislampaan kaikkein vankeuden lasten edestä, ja pappein heidän veljeinsä edestä ja itse edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Ja Israelin lapset jotka vankeudesta palanneet olivat, söivät, ja kaikki, jotka itsensä olivat eroittaneet maan pakanain saastaisuudesta heidän tykönsä, etsimään Herraa Israelin Jumalaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Ja pitivät happamattoman leivän juhlaa ilolla seitsemän päivää; sillä Herra oli heidät iloittanut, ja kääntänyt Assurin kuninkaan sydämen heidän puoleensa, että he tulivat vahvistetuksi Jumalan huoneen työssä, joka on Israelin Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Mutta näiden jälkeen Artahsastan Persian kuninkaan hallitessa oli Esra Serajan poika, Asarian pojan, Hilkian pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Sallumin pojan, Zadokin pojan, Ahitobin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Amarian pojan, Asarian pojan, Merajotin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Serahian pojan, Ussin pojan, Bukkin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Abisuan pojan, Pinehaan pojan, Eleatsarin pojan, ylimmäisen papin Aaronin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Tämä Esra meni ylös Babelista, joka oli toimellinen kirjanoppinut Moseksen laissa, jonka Herra Israelin Jumala oli antanut. Ja kuningas antoi hänelle kaikki, mitä hän anoi, Herran hänen Jumalansa käden jälkeen, joka hänen ylitsensä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Ja siinä meni muutamia Israelin lapsista ja papeista ja Leviläisistä, veisaajista, ovenvartioista ja Netinimeistä ylös Jerusalemiin, seitsemäntenä Artahsastan kuninkaan vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Ja hän tuli Jerusalemiin viidentenä kuukautena, se oli seitsemäs kuninkaan vuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Sillä ensimäisenä päivänä ensimäistä kuuta alkoi hän lähteä Babelista, ja ensimäisenä päivänä viidennettä kuuta tuli hän Jerusalemiin, Jumalan hyvän käden kautta, joka hänen ylitsensä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Sillä Esra oli valmistanut sydämensä etsimään Herran lakia, ja tekemään sitä ja opettamaan Israelille säätyjä ja oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Ja näin on se kirja, jonka Artahsasta antoi papille Esralle, kirjanoppineelle, joka oli opettaja Herran käskysanoissa ja säädyissä Israelille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artahsasta kuningasten kuningas Esralle papille ja kirjanoppineelle taivaan Jumalan laissa: rauhaa tällä ajalla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Minä olen käskenyt, että kenenkä ikänä kelpaa minun valtakunnassani Israelin kansasta, papeista ja Leviläisistä mennä kanssas Jerusalemiin, niin menkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Sinä olet lähetetty kuninkaalta ja seitsemältä neuvonantajalta etsimään Juudaa ja Jerusalemia, sinun Jumalas lain jälkeen, joka käsissäs on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'Ja ettäs otat myötäs sen hopian ja kullan, minkä kuningas ja hänen neuvonantajansa hyvällä mielellä ovat uhranneet Israelin Jumalalle, jonka maja on Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Ja kaikkinaisen hopian ja kullan, minkä sinä saat koko Babelin maakunnasta, kuin kansa ja papit hyvällä mielellä antavat Jumalan huoneesen, joka on Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Sentähden osta nopiasti sillä rahalla mullia, oinaita ja karitsoita, ja ruokauhria ja juomauhria, ja uhraa ne teidän Jumalanne huoneen alttarilla, joka on Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Mutta mitä sinun ja sinun veljes siitä rahasta kelpaa tehdä, joka liiaksi on, se tehkäät teidän Jumalanne tahdon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Ja astiat, jotka sinun haltuus ovat annetut sinun Jumalas huoneen palvelukseksi, anna ne pois Jumalan eteen Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Ja mitä enempää tarvitaan sinun Jumalas huoneesen ja sinä kulutat, niin anna se kuninkaan tavarahuoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Minä kuningas Artahsasta olen käskenyt veronhaltioille sillä puolella virtaa, että mitä ikänä Esra pappi ja kirjanoppinut taivaan Jumalan laissa teiltä anoo, se tehkäät nopiasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Hamaan sataan leiviskään hopiaa, ja sataan koriin nisuja, ja sataan tynnyriin viinaa, ja sataan tynnyriin öljyä, ja suoloja ilman mittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Kaikkia mitä taivaan Jumalan laki anoo, se pitää taivaan Jumalan huoneelle juuri nopiasti tehtämän, ettei hänen vihansa tulisi kuninkaan valtakunnan ja hänen lastensa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Ja se pitää oleman teille kaikille tiettävä, ettei teillä ole valtaa panna jotakin veroa, tullia eli ajastaikaista ulostekoa yhdenkään papin päälle, Leviläisen, veisaajan, ovenvartijan, Netinimin, tämän Jumalan huoneen palveliain päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Ja sinun, Esra, pitää Jumalas viisauden jälkeen, joka sinulla on, paneman tuomarit ja oikeuden tekiät, tuomitsemaan kaiken kansan, joka toisella puolella virtaa on, että kaikki taitaisivat sinun Jumalas lain; ja sitä, joka ei taida, pitää teidän opettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Ja jokainen, joka ei tee visusti sinun Jumalas lakia ja kuninkaan lakia, hänen pitää saaman tuomionsa työnsä jälkeen, joko se on kuolemaan, eli maan kulkemukseen, eli rahasakkoon, taikka vankeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Kiitetty olkoon Herra, meidän isäimme Jumala, joka tainkaltaisen asian on antanut kuninkaan sydämeen, että hän kaunistaa Herran huonetta Jerusalemissa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'Ja hän on kääntänyt laupiuden minun päälleni kuninkaan ja hänen neuvonantajainsa ja kaikkein kuninkaan voimallisten päämiesten edessä. Ja minä vahvistettiin Herran minun Jumalani kädellä, joka oli minun ylitseni, ja kokosin päämiehet Israelista menemään ylös minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Nämät ovat niiden isäin päämiehet, ja heidän polvilukunsa, jotka läksivät minun kanssani Babelista kuningas Artahsastan hallitessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Pinehaan pojista, Gersom; Itamarin pojista, Daniel; Davidin pojista, Hattus;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Sekanian pojista, Paroksen lapsista, Sakaria, ja hänen kanssansa luettu sata ja viisikymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Pahatmoabin pojista, Eljoenai Serahian poika, ja hänen kanssansa kaksisataa miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Sekanian pojista, Jehasielin poika, ja hänen kanssansa kolmesataa miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Adinin pojista, Ebed Jonatanin poika, ja hänen kanssansa viisikymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Elamin pojista, Jesaia Atalian poika, ja hänen kanssansa seitsemänkymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Sephatian pojista, Sebadia Mikaelin poika, ja hänen kanssansa kahdeksankymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Joabin pojista, Obadia Jehielin poika ja hänen kanssansa kaksisataa ja kahdeksantoistakymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Selomitin pojista, Josiphian poika, ja hänen kanssansa sata ja kuusikymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Bebain pojista, Sakaria Bebain poika, ja hänen kanssansa kahdeksankolmattakymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Asgadin pojista, Johanan nuorin poika, ja hänen kanssansa sata ja kymmenen miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Adonikamin viimeisistä pojista, joiden nimet ovat: Eliphelet, Jehiel ja Semaja, ja heidän kanssansa kuusikymmentä miestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Bigvain pojista, Utai ja Sabbud ja heidän kanssansa seitsemänkymmentä miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Ja minä kokosin heidät sen virran tykö, joka tulee Ahavaan, ja oleskelimme siinä kolme päivää. Ja kuin minä visusti katselin kansan ja papit, en minä löytänyt yhtäkään Leviläistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Niin minä lähetin Elieserin, Arielin, Semajan, Elnatanin, Jaribin, Elnatanin, Natanin, Sakarian ja Mesullamin, päämiehet, ja Jojaribin ja Elnatanin, opettajat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Ja lähetin ne Iddon tykö, joka oli päämies Kasiphian paikkakunnassa, tuomaan meille palvelioita Jumalamme huoneesen, ja minä panin heidän suuhunsa sanat, mitä heidän piti Iddolle puhuman ja hänen veljillensä Netinimeille Kasiphian paikkakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Ja he toivat meille, Jumalamme hyvän käden jälkeen meidän ylitsemme, viisaan miehen, Mahelin pojista Levin pojan, Israelin pojan, ja Serebian hänen poikainsa ja veljeinsä kanssa, kahdeksantoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'Ja Hasabian ja Jesaian hänen kanssansa, Merarin pojista, hänen veljensä ja heidän poikainsa kanssa kaksikymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Ja Netinimeistä, jotka David ja päämiehet olivat panneet Leviläisiä palvelemaan, kaksisataa ja kaksikymmentä Netinimiä; kaikki nimeltänsä nimitetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Ja minä kuulutin siellä paaston Ahavan virran tykönä, nöyryyttääksemme mieltämme Jumalamme edessä, ja kysyäksemme häneltä oikiaa tietä meille ja meidän lapsillemme ja kaikille meidän kaluillemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Sillä en minä rohjennut anoa kuninkaalta sotaväkeä ja huovia varjelemaan meitä tiellä vihollisilta; sillä me olimme sanoneet kuninkaalle, että meidän Jumalamme käsi on hyväksi kaikkein ylitse, jotka häntä etsivät; mutta hänen väkevyytensä ja vihansa on kaikkein niiden päällä, jotka hänen hylkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Niin me paastosimme ja rukoilimme meidän Jumalaamme sen edestä; ja hän kuuli meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Ja minä valitsin ylimmäisistä papeista kaksitoistakymmentä: Serebian ja Hasabian, ja kymmenen heidän veljistänsä heidän kanssansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'Ja minä punnitsin heille hopian ja kullan, ja ylennysastiat meidän Jumalamme huoneesen, mitkä kuningas ja hänen neuvonantajansa ja päämiehensä, ja koko Israel, joka saapuvilla oli, olivat antaneet ylennykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Ja punnitsin heidän käteensä hopiaa kuusisataa ja viisikymmentä leiviskää, ja hopia- astioita sata leiviskää, ja sata leiviskää kultaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Ja kaksikymmentä kultaista maljaa, jotka painoivat tuhannen kultapenninkiä, ja kaksi kallista vaskiastiaa, niin kirkasta kuin kulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Ja minä sanoin heille: te olette pyhät Herralle, niin myös ovat astiat pyhät, ja kulta ja hopia on hyvällä mielellä annettu Herralle isäinne Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Valvokaat siis ja pitäkäät ne niinkauvan tallella, että te ne jälleen punnitsette ulos pappein ja Leviläisten, päämiesten ja Israelin ylimmäisten isäin edessä, Jerusalemissa, Herran huoneen arkkuihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Niin papit ja Leviläiset ottivat vastaan punnitun hopian ja kullan ja astiat, viedäksensä Jerusalemiin Jumalamme huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Ja me läksimme Ahavan virran tyköä, toisena päivänä toistakymmentä ensimäistä kuuta, menemään Jerusalemiin. Ja meidän Jumalamme käsi oli meidän päällämme, joka meitä pelasti vihollistemme käsistä ja väijymisestä tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Ja me tulimme Jerusalemiin ja oleskelimme siellä kolme päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Mutta neljäntenä päivänä punnittiin hopia ja kulta, ja astiat meidän Jumalamme huoneesen, papin Urian pojan Meremotin käden alla, ja hänen kanssansa oli Eleatsar Pinehaan poika ja heidän kanssansa Josabad Jesuan poika ja Noadia Binnuin poika, Leviläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Jokaisen luvun ja painon jälkeen; ja kaikki se paino kirjoitettiin siihen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Ja vankeuden lapset, jotka olivat tulleet vankeudesta, uhrasivat Israelin Jumalalle polttouhria, kaksitoistakymmentä mullia, koko Israelin edestä, yhdeksänkymmentä ja kuusi oinasta, seitsemänkahdeksattakymmentä karitsaa, kaksitoistakymmentä kaurista syntiuhriksi, kaikki tyynni polttouhriksi Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Ja he antoivat kuninkaan kirjat ja käskyn kuninkaan maaherroille ja päämiehille tällä puolella virtaa, ja korottivat kansan ja Jumalan huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Kuin nämät kaikki olivat päätetyt, niin tulivat päämiehet minun tyköni ja sanoivat: Israelin kansa ja papit ja Leviläiset ei ole erinneet maan kansain, Kanaanealaisten, Hetiläisten, Pheresiläisten, Jebusilaisten, Ammonilaisten, Moabilaisten, Egyptiläisten ja Amorilaisten kauhistuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Sillä he ovat ottaneet heidän tyttäriänsä itsellensä ja pojillensa ja ovat sekoittaneet pyhän siemenen maan kansain kanssa; ja heidän päämiehensä ja esivaltansa ovat kaikkein ensimäiset siinä pahassa teossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Kuin minä sen kuulin, repäisin minä vaatteeni ja hameeni, ja repelin hiuksiani päästäni ja partaani ja istuin hämmästyksissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Ja kaikki, jotka pelkäsivät Herran Israelin Jumalan sanaa, tulivat kokoon minun tyköni, jälleen tulleiden synnin tähden; ja minä istuin hämmästyksissä hamaan ehtoouhriin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ja ehtoouhrin aikana nousin minä surkeudestani; ja kuin minä repäisin vaatteeni ja hameeni, lankesin minä polvilleni ja hajoitin käteni Herran minun Jumalani tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'Ja sanoin: minun Jumalani! minä häpeen ja en kehtaa silmiäni nostaa sinun tykös, minun Jumalani; sillä meidän syntimme ovat enentyneet päämme ylitse ja meidän pahat tekomme ovat kasvaneet hamaan taivaaseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Hamasta isäimme ajasta niin tähän päivään saakka olemme me olleet suurissa synneissä; ja meidän pahain töidemme tähden olemme me ja meidän kuninkaamme ja pappimme annetut maan kuningasten käsiin, ja miekkaan, ja vankeuteen ja ryöstöksi, ja meidän kasvomme häpiään, niinkuin tänäkin päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Mutta nyt vähällä ajan rahdulla on meille armo tapahtunut Herralta meidän Jumalaltamme, että vielä on muutamia meistä jäljellä ja päässeitä, että hän antoi vielä vaarnan meille pyhään siaansa, että meidän Jumalamme valistais silmämme ja antais meille vähän virvoituksen orjuudessamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Sillä me olemme orjat; ja orjuudessamme ei hyljännyt meitä meidän Jumalamme; ja hän on kääntänyt laupiuden meidän tykömme Persian kuningasten edessä, että he antoivat meidän elää, ja korottaa meidän Jumalamme huoneen, ja korjata jaonneet paikat, ja antoi meille aidan Juudassa ja Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Mitä me siis sanomme, meidän Jumalamme, tästälähin? että me olemme hyljänneet sinun käskys,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Joita sinä olet käskenyt palveliais prohetain kautta, sanoen: maa, johon te menette omistamaan sitä, on saastainen maa, maan kansain saastaisuuden tähden, niiden kauhistusten tähden, joilla he ovat sen täyttäneet saastaisuudellansa, sekä siellä että täällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Niin ei teidän pidä nyt antaman tyttäriänne heidän pojillensa, ja ei teidän pidä ottaman heidän tyttäriänsä pojillenne; älkäät myös etsikö heidän rauhaansa ja hyväänsä ijankaikkisesti, että vahvistuisitte, ja söisitte maan hyvyyttä, ja saisitte antaa sen teidän lapsillenne ijankaikkiseksi perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Ja niiden kaikkein jälkeen mitkä meidän päällemme tulleet ovat, pahain tekoimme tähden ja suurten synteimme tähden, niin olet sinä meidän Jumalamme säästänyt meidän pahoja töitämme ja antanut meille vapahduksen, niinkuin nyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Pitäiskö meidän taas sinun käskys käymän ylitse ja tekemän lankoutta tämän ilkiän kansan kanssa? Etkös mahda vihastua meidän päällemme, siihenasti että peräti hukutat, ettei ketään jää, eikä ole pääsemystä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Herra Israelin Jumala! sinä olet vanhurskas. Sillä me olemme jääneet vapahdettaa, niinkuin se tänäpänä on. Katso, me olemme sinun edessäs synneissämme; sentähden ei kenkään voi edessäs pysyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Kuin Esra näin rukoili ja tunnusti, itki ja makasi Jumalan huoneen edessä, kokoontui suuri joukko Israelista hänen tykönsä, miehistä, vaimoista ja lapsista, ja kansa itki sangen kovin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Ja Sekania Jehielin poika, Elamin lapsista, vastasi Esraa ja sanoi: me olemme rikkoneet Jumalaamme vastaan, että me olemme ottaneet muukalaiset vaimot maan kansoista; mutta vielä on toivo sen vuoksi Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Niin tehkäämme nyt liitto meidän Jumalamme kanssa ajaaksemme kaikki vaimot pois ja ne, jotka heistä syntyneet ovat, Herran neuvon jälkeen ja niiden, jotka pelkäävät meidän Jumalamme käskyä; ja tapahtukoon lain jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Niin nouse, sillä sinun se tulee, me olemme sinun kanssas; ole hyvässä turvassa ja tee niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Silloin nousi Esra ja vannotti ylimmäiset papit ja Leviläiset, ja koko Israelin, tekemään tämän sanan jälkeen; ja he vannoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Ja Esra nousi Jumalan huoneen edestä ja meni Johananin Eliasibin pojan kammioon; ja kuin hän sinne tuli, ei hän syönyt leipää eikä juonut vettä; sillä hän murehti heidän rikostensa tähden, jotka olivat olleet vankeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Ja he kuuluttivat Juudassa ja Jerusalemissa kaikille lapsille, jotka vankina olivat olleet, tulemaan kokoon Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'Ja joka ei kolmena päivänä tullut päämiesten ja vanhimpain neuvon jälkeen, niin kaikki hänen tavaransa piti kirottu oleman, ja hän itse piti eroitettaman niiden joukosta, jotka vankina olivat olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Niin tulivat kaikki Juudan ja Benjaminin miehet Jerusalemiin kolmessa päivässä kokoon, se on, kahdentenakymmenentenä päivänä yhdeksännessä kuussa; ja kaikki kansa istui kadulla Herran huoneen edessä, ja värisivät siitä asiasta ja sateen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Ja pappi Esra nousi ja sanoi heille: te olette rikkoneet, naidessanne muukalaisia vaimoja, ja lisänneet Israelin synnit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Niin tunnustakaat nyt se Herralle isäinne Jumalalle, ja tehkäät sitä, kuin hänelle kelpaa, ja eroittakaat teitänne maan kansoista ja muukalaisista vaimoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Niin vastasi koko seurakunta ja sanoi korkialla äänellä: se pitää niin tapahtuman, kuin sinä meille olet sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Mutta kansaa on paljo, ja on sadeilma, ja ei voi ulkona seisoa, eikä tämä ole yhden eli kahden päivän työ; sillä meitä on paljo, jotka olemme siinä asiassa sangen suuresti syntiä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Anna meidän päämiestemme koko seurakunnassa toimittaa, että kaikki, jotka meidän kaupungeissamme ovat naineet muukalaisia vaimoja, tulevat tänne määrättynä päivänä, jokaisen kaupungin vanhimpain ja tuomarein kanssa, siihenasti kuin meidän Jumalamme viha kääntyy meistä tämän syyn tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Niin astuivat ainoastaan Jonatan Asahelin poika ja Jahasia Tikvan poika tähän toimitukseen; ja Metullam ja Sabtai, Leviläiset, auttivat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Ja vankeuden lapset tekivät niin; ja eroitettiin Esra pappi ja päämiehet heidän isäinsä sukukuntain seassa, ja kaikki, kuin nimitetyt ovat, ja he istuivat ensimäisenä päivänä kymmenennessä kuukaudessa tutkistelemaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'Ja he toimittivat sen kaikkein miesten kanssa, joilla olivat muukalaiset vaimot, ensimäiseen päivään asti ensimäisessä kuussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Ja pappein poikain seasta löydettiin, jotka olivat ottaneet muukalaisia vaimoja: Jesuan Jotsadakin pojan lasten seassa, ja hänen veljeinsä Maeseja, Elieser, Jarib ja Gedalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'Ja he antoivat kätensä, ajamaan vaimonsa ulos ja antamaan jäärän rikosuhriksensa rikoksensa edestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Immerin lasten seassa: Hanani ja Sebadia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Harimin lasten seassa: Maeseja, Elia, Semaja, Jehiel ja Ussia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Pashurin lasten seassa: Eljoenai, Maaseja, Ismael, Netaneel, Josabad ja Eleasa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Leviläisistä: Josabad, Simei ja Kelaja, se on Kelita, Petakia, Juuda ja Elieser;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Veisaajain seassa: Eljasib; ovenvartijain seassa: Sallum, Telem ja Uri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Israelista Paroksen lasten seassa: Ramia, Jesia, Malkia, Mejamin, Eleasar, Malkia ja Benaja;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Elamin lasten seassa: Mattania, Sakaria, Jehiel, Abdi, Jeremot ja Elia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Sattun lasten seassa: Eljoenai, Eljasib, Mattania, Jeremot, Sabad ja Asisa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Bebain lasten seassa: Johanan, Hanania, Sebai ja Atlai;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Banin lasten seassa: Mesullam, Malluk, Adaja, Jasub, Seal ja Jeramoth;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Pahatmoabin lasten seassa: Adna ja Kelal, Benaja, Maeseja, Mattania, Betsaleel, Binnui ja Manasse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Harimin lasten seassa: Elieser, Jesia, Malkia, Semaja, Simeon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluk ja Semaria;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Hasumin lasten seassa: Mattenai, Mattatta, Sabad, Eliphelet, Jeremai, Manasse ja Simei;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Banin lasten seassa: Maadai, Amram, Uel,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedeja, Keluhi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vania, Meremot, Eljasib');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattania, Mattenai, Jaasav,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani, Binnui, Simei,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemia, Natan, Adaja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadbai, Sasai, Sarai,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asareel, Selemia, Semaria,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amaria ja Joseph;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Nebon lasten seassa: Jejel, Mattitia, Sabad, Sebina, Jaddai, Joel ja Benaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Nämät kaikki olivat ottaneet muukalaisia vaimoja, ja olivat monikahdat niistä vaimoista, joiden kanssa he olivat siittäneet lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Nämät ovat Nehemian Hakalian pojan teot. Tapahtui Kislevin kuulla, kahdentenakymmenentenä vuonna, kuin minä olin Susanin linnassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Niin tuli Hanani, yksi veljistäni muutamain Juudan miesten kanssa; ja minä kysyin heiltä Juudalaisista, jotka vankeudesta jääneet ja päässeet olivat, ja Jerusalemin menoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Ja he sanoivat minulle: ne, jotka jäljelle jääneet ovat vankeudesta, ovat siellä maassa suuressa onnettomuudessa ja häpiässä; Jerusalemin muurit ovat jaotetut ja sen portit tulella poltetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Kuin minä senkaltaiset sanat kuulin, niin minä istuin ja murehdin muutamat päivät, paastosin ja rukoilin taivaan Jumalan edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Ja sanoin: Oi Herra, taivaan Jumala, suuri ja peljättävä Jumala, joka pidät liiton ja laupiuden niille, jotka sinua rakastavat ja pitävät sinun käskys!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Anna korvas kuulla ja silmäs avoinna olla, kuulemaan palvelias rukousta, kuin minä nyt rukoilen sinun edessäs yöt ja päivät palveliais Israelin lasten edessä; ja minä tunnustan Israelin lasten synnit, jotka me olemme tehneet sinua vastaan; ja minä ja minun isäni huone olemme syntiä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Me olemme kovin turmelleet itsemme, ettemme ole pitäneet sinun käskyjäs, säätyjäs ja oikeuttas, joitas olet palvelialles Mosekselle käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Mutta muista kuitenkin sitä sanaa, jonka sinä käskit Mosekselle palvelialles ja sanoit: koska te rikotte, niin minä hajoitan teidät kansain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Mutta jos te palajatte minun tyköni, ja pidätte minun käskyni ja teette ne: ja jos te ajetaan hamaan taivaan ääriin, niin minä sieltäkin teidät kokoon ja vien siihen paikkaan, jonka minä olen valinnut nimeni asumasiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'He ovat kuitenkin sinun palvelias ja sinun kansas, jotkas vapahdit suurella voimallas ja väkevällä kädelläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'O Herra! olkoon korvas avoinna palvelias rukoukseen ja sinun palveliais rukouksiin, jotka pyytävät peljätä sinun nimeäs, ja anna palvelias tänäpänä menestyä, ja anna heille armo tämän miehen edessä! Sillä minä olin kuninkaan juomanlaskia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Ja tapahtui kuningas Artahsastan kahdentenakymmenentenä vuonna, Nisanin kuulla, kuin viina oli hänen edessänsä, ja että minä otin viinan ja annoin kuninkaalle; mutta en minä ollut (ennen) murheellinen hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'Niin kuningas sanoi minulle: miksi niin pahoin katsot, ja et kuitenkaan kipeä ole? Ei se muu ole, mutta murhe on sinun sydämessäs. Ja minä pelkäsin sangen kovin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'Niin minä sanoin kuninkaalle: eläköön kuningas ijankaikkisesti! Eikö kasvoni mahda olla murheelliset, kuin se kaupunki, jossa isäni hautaushuone on, kylmillä on, ja sen portit ovat tulella kulutetut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Niin sanoi kuningas minulle: mitäs siis anot? Niin minä rukoilin Taivaan Jumalaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'Ja sanoin kuninkaalle: jos kelpaa kuninkaalle, ja jos palvelias on sinun edessäs kelvollinen: ettäs lähettäisit minut Juudaan, isäni hautauskaupunkiin, rakentamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Niin sanoi kuningas minulle ja kuningatar, joka hänen vieressänsä istui: kuinka kauvan sinä matkassa olet, ja koska sinä palajat? Ja se kelpasi kuninkaalle, ja hän lähetti minun, kuin minä ajan hänelle määrännyt olin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Ja minä sanoin kuninkaalle: jos kuninkaan tahto niin on, niin annettakoon minulle kirjat päämiesten tykö toisella puolella virtaa, että he vievät minun ylitse, siihenasti kuin minä tulen Juudaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'Ja kirjan Asaphille, joka on kuninkaan metsänvartia, että hän lähettää minulle hirsiä salin porttein vuolteiksi, kuin on huoneen tykönä, ja kaupungin muuriin ja siihen huoneesen, johon minä menen. Ja kuningas antoi minulle niinkuin Jumalani hyvä käsi oli minun ylitseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Ja kuin minä tulin sille puolelle virtaa päämiesten tykö, niin minä annoin heille kuninkaan kirjan; kuningas lähetti myös minun kanssani sodanpäämiehiä ja hevosmiehiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Mutta kuin Sanballat Horonilainen ja palvelia Tobia Ammonilainen sen kuulivat, panivat he pahaksensa sangen kovin, että joku ihminen tuli, joka Israelin lasten parasta katsoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Ja kuin minä tulin Jerusalemiin ja olin siellä ollut kolme päivää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Nousin minä yöllä ja vähä väkeä minun kanssani; sillä en minä sanonut kellenkään, mitä minun Jumalani oli antanut sydämeeni, tehdäkseni Jerusalemissa; ja ei minulla ollut yhtään juhtaa myötäni, muuta kuin se, jonka päällä minä istuin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Ja minä ajoin Laaksoportista ulos yöllä, Kärmelähteen kohdalle Sontaporttiin asti ja katselin Jerusalemin muureja, jotka olivat jaotetut, ja portteja, jotka olivat tulella kulutetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Ja minä menin vielä Lähdeporttiin ja Kuninkaan vesilammin tykö; ja ei ollut sielä siaa, että minun juhtani sai käydä minun allani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Kuitenkin menin minä yöllä ojaa myöten ja koettelin muuria; sitte palasin minä ja tulin jälleen Laaksoporttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Ja ei ylimmäiset tietäneet, kuhunka minä menin, taikka mitä minä tein; sillä en minä vielä siihenasti ilmoittanut mitään kellenkään, Juudalaisille eikä papeille, ylimmäisille taikka esivallalle, ja muille työn tekiöille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Ja minä sanoin heille: te näette tämän onnettomuuden, jossa me olemme, että Jerusalem on autiona, ja sen portit ovat tulella kulutetut: tulkaat ja rakentakaamme Jerusalemin muurit, ettemme enää häpiänä olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Ja minä ilmoitin heille minun Jumalani käden, joka oli hyvä minun päälläni, ja myös kuninkaan sanat, jotka hän sanoi minulle. Ja he sanoivat: nouskaamme siis ja rakentakaamme. Ja heidän kätensä vahvistuivat hyvyyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Mutta kun Sanballat Horonilainen, ja palvelia Tobia Ammonilainen, ja Gesem Arabialainen sen kuulivat, häpäisivät he meitä ja katsoivat meidät ylön ja sanoivat: mikä se on, jota te teette? tahdotteko te luopua jälleen kuninkaasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Niin minä vastasin heitä ja sanoin heille: taivaan Jumala antaa meille menestyksen, sillä me hänen palveliansa olemme valmistaneet itsemme ja rakennamme; mutta ei teillä ole yhtäkään osaa eli oikeutta, taikka muistoa Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Ja Eljasib, ylimmäinen pappi, nousi pappein veljeinsä kanssa, rakensivat Lammasportin ja pyhittivät sen, ja panivat siihen ovet; ja he pyhittivät sen Mean torniin asti, hamaan Hananeelin torniin saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Ja Jerihon miehet rakensivat hänen vieressänsä, ja Sakkur Imrin poika rakensi hänen vieressänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Mutta Senaan lapset rakensivat Kalaportin, ja kattivat sen, ja panivat siihen ovet, lukot ja teljet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Ja Meremot Urian poika, Hakkotsin pojan, rakensi heidän vieressänsä, ja Mesullam Berekian poika, Mesesabelin pojan, rakensi heidän vieressänsä; Zadok Baenan poika rakensi heidän vieressänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Niiden tykönä rakensivat Tekoan miehet; mutta heidän sankarinsa ei kääntäneet kaulaansa Herransa palvelukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Vanhan portin rakensi Jojada Passean poika ja Mesullam Besodian poika, ja kattivat sen, ja panivat siihen ovet, lukot ja teljet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Melatia Gibeonilainen ja Jadon Meronotilainen rakensi heidän vieressänsä, Gibeonin ja Mitspan miehet, päämiehen istuimen tykönä, sillä puolella virtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Hänen vieressänsä rakensi Ussiel Harhakan kultasepän poika; hänen vieressänsä rakensi Hanania yrtteinmyyjän poika; ja he rakensivat Jerusalemia leviään muuriin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Hänen vieressänsä rakensi Rephaja Hurin poika, puolen Jerusalemin päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Heidän vieressänsä rakensi Jedaja Harumaphin poika, huoneensa kohdalla; hänen vieressänsä rakensi Hattus, Hasabnejan poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Mutta Malkia Harimin poika ja Hasub Pahatmoabin poika rakensivat toista kulmaa, niin myös Pätsitornin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Hänen vieressänsä rakensi Sallum Haloeksen poika, puolen Jerusalemin päämies: hän itse ja hänen tyttärensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Laaksoportin rakensi Hanun ja Sanoan asujamet; ne rakensivat sen ja panivat siihen ovet, lukot ja teljet, ja tuhannen kyynärää muuria Sontaporttiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Mutta Malkia Rekabin poika, viinamäen kulmakunnan päämies, rakensi Sontaportin, hän rakensi sen ja pani siihen ovet, lukot ja teljet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Mutta Lähdeportin rakensi Sallun Kolhosen poika, Mitspan kulmakunnan päämies; hän rakensi ja katti sen, ja pani siihen ovet, lukot ja teljet; niin myös Selan lammin muurin kuninkaan yrttitarhan tykönä, niihin astuimiin asti, jotka tulevat alas Davidin kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Hänen vieressänsä rakensi Nehemia Asbukin poika, puolen Betsuurin päämies, aina Davidin hautain kohdalle, ja kaivettuun lammikkoon asti väkeväin huoneeseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Häntä likimpänä rakensivat Leviläiset, Rehum Banin poika; hänen vieressänsä rakensi Hasabia, puolen Kegilan päämies kulmakuntansa puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Häntä likimpänä rakensivat heidän veljensä Bavai Hanadadin poika, toisen puolen Kegilan päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Hänen vieressänsä rakensi Eser Jesuan poika, Mitspan päämies, toisen osan siinä kulmassa, asehuoneen puolessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Häntä likinnä rakensi Baruk Sabbain poika kiivaasti toisen osan kulmasta Eljasibin ylimmäisen papin huoneen oveen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Häntä likinnä rakensi Meremot Urian poika, Hakkotsin pojan, toisen osan, Eljasibin huoneen ovesta Eljasibin huoneen loppuun asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Ja hänen jälkeensä rakensivat papit, miehet lakeudelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Heidän jälkeensä rakensi Benjamin ja Hassub oman huoneensa kohdalla; heidän perässänsä rakensi Asaria Maesejan poika, Ananian pojan, huoneensa tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Hänen jälkeensä rakensi Binnui Henadadin poika, toisen osan, Asarian huoneesta niin loukkaasen ja hamaan kulmaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal Usain poika loukasta vastaan ja tornia, joka menee kuninkaan ylisestä huoneesta, joka oli vankikartanon tykönä; hänen jälkeensä Pedaja Paroksen poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'Mutta Netinimit asuivat Ophelin tykönä Vesiporttiin asti itään päin, josta torni käy ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Sitälikin rakensivat Tekoalaiset toisen osan, isoa tornia päin, kuin näkyy ulos, Opelin muuriin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Mutta Hevosportin yläpuolelta rakensivat papit, jokainen huoneensa kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Heidän jälissänsä rakensi Zadok Immerin poika, huoneensa kohdalla; hänen jälissänsä rakensi Semaja Sekanian poika, Itäportin vartia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Hänen jälissänsä rakensi Hananian Selemian poika, ja Hanun kuudes Salaphin poika, toisen osan; hänen jälissänsä rakensi Mesullam Berekian poika, makaushuoneensa kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Hänen jälissänsä rakensi Malkia kultasepän poika, Netinimein ja kauppamiesten huoneesen asti, Käräjäportin kohdalla, hamaan Kulmasaliin saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Kultasepät ja kauppamiehet rakensivat Kulmasalin välillä ja Lammasporttiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Kuin Sanballat kuuli meidän muuria rakentavan, syttyi hän vihaan ja närkästyi sangen suuresti, ja häpäisi Juudalaisia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'Ja puhui veljeinsä ja voimallisten edessä Samariassa ja sanoi: mitä nämät voimattomat Juudalaiset tekevät? pitääkö heille niin sallittaman? pitääkö heidän uhraaman? pitääkö heidän sen täyttämän yhtenä päivänä? pitääkö heidän kiviä eläväksi tekemän, jotka ovat tuhkaläjä ja palaneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Ja Tobia Ammonilainen sanoi hänen jälkeensä: rakentakoot vapaasti; jos ketut sinne menisivät, niin he kyllä jaottaisivat heidän kivimuurinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Kuule meidän Jumalamme, kuinka me olemme katsotut ylön, ja käännä heidän häväistyksensä heidän päänsä päälle, ja saata heitä häpiään vankeuden maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Älä peitä heidän pahoja tekojansa ja älä pyyhi heidän syntiänsä kasvois edestä; sillä he ovat vihan matkaan saattaneet, rakentajain läsnäollessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Mutta me rakensimme muurin ja panimme hänen kaiketi yhteen hamaan puoliväliin asti; ja kansa sai sydämen työtä tehdäksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Kuin Sanballat ja Tobia ja Arabialaiset ja Ammonilaiset ja Asdodilaiset kuulivat Jerusalemin muurit korotetuksi, ja ruvetuksi haljenneita parantamaan, vihastuivat he sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Ja he kaikki tekivät liiton keskenänsä tullaksensa sotimaan Jerusalemia vastaan, ja tekemään heille kapinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Mutta me rukoilimme meidän Jumalaamme ja panimme vartiat öin ja päivin heitä vastaan, heidän tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Ja Juuda sanoi: kantajain voima on heikoksi tullut ja multaa on niin paljo, ettemme saa rakentaa muuria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Ja meidän vihollisemme sanoivat: ei heidän pidä tietämän eli näkemän, ennenkuin me olemme juuri heidän keskellänsä, tapamme heidät ja estämme työn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Ja kuin ne Juudalaiset, jotka heidän tykönänsä asuivat, tulivat ja sanoivat meille kymmenen kertaa: joka paikasta te vielä meidän tykömme palajatte;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Niin minä lähetin kansan alas muurin taa tuiviin paikkoihin, heidän sukukuntainsa jälkeen, miekkoinensa, keihäinensä ja joutsinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Ja minä katselin ja valmistin itseni, ja sanoin ylimmäisille ja päämiehille, ja muulle kansalle: älkäät peljätkö heitä, muistakaat suurta ja peljättävää Herraa, ja sotikaat teidän veljeinne, poikainne, tytärtenne, emäntäinne ja kotonne edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Mutta kuin meidän vihollisemme sen kuulivat, että me olimme tietää saaneet, niin Jumala teki heidän neuvonsa tyhjäksi: ja me palasimme kaikki muurin tykö, jokainen työhönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Ja tapahtui siitä päivästä, että toinen puoli nuoria miehiäni teki työtä, ja toinen puoli piti keihäitä, kilpiä, joutsia ja rautapaitoja. Ja päämiehet seisoivat koko Juudan huoneen takana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Ne, jotka rakensivat muuria ja kantoivat kuormia, ja jotka sälyttivät, yhdellä kädellä he tekivät työtä ja toisessa pitivät aseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Ja jokaisella joka siellä rakensi, oli miekka sidottu vyölle, ja niin he rakensivat. Ja se joka soitti vaskitorvea, oli minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Ja minä sanoin ylimmäisille ja päämiehille ja muulle kansalle: työ on suuri ja avara, ja me olemme hajalla muurin päällä, kaukana toinen toisestamme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Millä paikalla te kuulette vaskitorven äänen, tulkaat sinne kokoon meidän tykömme: meidän Jumalamme sotii meidän edestämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Niin tehkäämme siis työtä; ja toinen puoli heistä piti keihäitä päivän koittamasta niin siihen saakka, että tähdet näkyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Ja minä myös sanoin siihen aikaan kansalle: jokainen olkaan yötä palveliainsa kanssa keskellä Jerusalemia, niin että me yöllä ottaisimme vaarin vartiosta ja päivällä työstä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Mutta minä ja minun veljeni, ja minun palveliani ja vartiat, jotka minua seurasivat, emme riisuneet vaatteitamme; ja jokaisella oli hänen aseensa ja vesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Ja tapahtui sangen suuri kansan ja heidän vaimonsa huuto Juudalaisia heidän veljiänsä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Ja oli muutamia, jotka sanoivat: meillä on poikia ja tyttäriä, ottakaamme siis (niiden hinnalla) jyviä syödäksemme, että me eläisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Mutta monikahdat sanoivat: pankaamme meidän peltomme, viinamäkemme ja huoneemme pantiksi, ja ottakaamme jyviä tällä kalliilla ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Ja monikahdat sanoivat: me otimme rahaa lainaksi kuninkaan veroksi, meidän peltoimme ja viinamäkeimme päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Sillä meidän ruumiimme on niinkuin veljeimmekin ruumis ja meidän lapsemme niinkuin heidänkin lapsensa; mutta katso, me heitämme poikamme ja tyttäremme orjuuteen, ja jo parhaallansa ovat muutamat meidän tyttäristämme sorretut, ja ei ole voimaa meidän käsissämme; meidän peltomme ja viinamäkemme ovat joutuneet muille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Kuin minä tämän puheen ja heidän huutonsa kuulin, vihastuin minä sangen kovin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Ja minä ajattelin sydämessäni, ja nuhtelin ylimmäisiä ja päämiehiä ja sanoin heille: tahdotteko te kukin veljeltänne korkoa ottaa? Ja minä vein suuren joukon heitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Ja sanoin heille: me olemme ostaneet veljemme Juudalaiset jälleen, jotka olivat myydyt pakanoille, varamme jälkeen; ja te vielä nyt tahdotte myydä veljenne, jotka meille myydyt ovat; niin he vaikenivat ja ei taitaneet vastata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Niin minä sanoin: ei se ole hyvä, minkä te teette; eikö teidän pitäisi vaeltaman meidän Jumalamme pelvossa, pakanain meidän vihollistemme häväistyksen tähden?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Minä myös ja minun veljeni ja palveliani olemme lainanneet heille rahaa ja jyviä; mutta jättäkäämme pois tämä korko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Antakaat heille tänäpänä heidän peltonsa, viinamäkensä, öljypuunsa, huoneensa ja sadas osa rahasta, jyvistä, viinasta ja öljystä, jonka te olette heiltä koroksi vaatineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Niin he sanoivat: me annamme jälleen, ja emme ano heiltä mitään; me teemme niinkuin sinä olet sanonut. Ja minä kutsuin papit ja vannotin heitä, että heidän piti niin tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Minä pudistin myös helmani ja sanoin: noin Jumala pudistakoon jokaisen miehen huoneestansa ja työstänsä, joka ei tätä sanaa pidä, ja tulkoon niin pudistetuksi ja tyhjäksi. Ja kansa sanoi: amen! Ja he kiittivät Herraa; ja kansa teki niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Ja siitä ajasta, kuin minua käskettiin olla heidän päämiehensä Juudan maassa, joka oli siitä kahdestakymmenennestä vuodesta niin toiseenneljättäkymmentä kuningas Artahsastan vuoteen, kahdestatoistakymmenessä ajastajassa, minä ja minun veljeni emme syöneet päämiehen ruokaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Sillä ne päämiehet, jotka ennen minua olivat, ne olivat raskauttaneet kansaa ja ottaneet leipää ja viinaa heiltä, ja vielä sitte neljäkymmentä sikliä hopiaa, ja olivat antaneet palveliainsa tehdä väkivaltaa kansalle; mutta en minä niin tehnyt Jumalan pelvon tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Ja minä tein myös työtä muurissa, ja en ostanut yhtään peltoa; ja kaikkein minun palveliaini täytyi tulla sinne kokoon työhön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Vielä päälliseksi oli myös Juudalaisia ja ylimmäisiä sata ja viisikymmentä minun pöytäni tykönä, jotka olivat tulleet minun tyköni pakanoista, jotka ovat tässä meidän ympärillämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Ja minulle valmistettiin joka päivä yksi härkä, ja kuusi valittua lammasta, ja lintuja, ja erilaisia viinoja yltäkyllä joka kymmenes päivä; ja en minä kuitenkaan anonut päämiehen ruokaa, sillä raskas orjuus oli tällä kansalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Minun Jumalani, muista minulle hyväksi kaikki, minkä minä olen tehnyt tälle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Kuin Sanballat, Tobia ja Gesem Arabialainen, ja muut meidän vihollisemme kuulivat minun muurit rakentaneeksi, ja ettei yhtään rakoa siihen jäänyt, (vaikka en minä vielä ollut pannut portteja siallensa);');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Niin Sanballat ja Gesem lähettivät minun tyköni nämät sanat: tule, ja kokoontukaamme maakyliin Onon laaksoon; mutta he ajattelivat minulle tehdä pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Mutta minä lähetin heille sanansaattajat, sanoen: minulla on sangen suuri työ tehtävänä, en minä saa tulla alas. Miksi pitäis työ lakkaaman, minun jättäissäni sitä ja tullessani alas teidän tykönne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Ja he lähettivät minun tyköni täyttä neljä kertaa sillä tavalla; ja minä vastasin heitä jälleen sillä tavalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Niin Sanballat lähetti viidennen kerran palveliansa minun tyköni avoimen kirjan kanssa kädessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Jossa näin oli kirjoitettu: se on pakanain eteen tullut, ja Gasmu on sanonut, että sinä ja Juudalaiset ajattelette luopua pois: ja sentähden sinä rakennat muureja; ja sinä tahdot olla heidän kuninkaansa tässä asiassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Ja sinä olet toimittanut prophetat jotka sinua pitää kuuluttaman Jerusalemissa ja sanoman: hän on Juudalaisten kuningas. Ja nyt pitää se asia tuleman kuninkaan eteen; sentähden tule nyt ja pitäkäämme neuvoa toinen toisemme kanssa siitä asiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Mutta minä lähetin hänen tykönsä ja annoin hänelle sanoa: ei se ole niin tapahtunut kuin sinä sanot; vaan sinä olet sen ajatellut omasta sydämestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Sillä he kaikki tahtoivat meitä peljättää, ja ajattelivat: heidän kätensä pitää väsymän työstä, ettei he enää työtä tekisi. Nyt siis vahvista minun käteni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Ja minä tulin Semajan huoneesen, Delajan pojan, Mehetabelin pojan, joka oli sulkenut itsensä sisälle. Ja hän sanoi: käykäämme kokoon Jumalan huoneesen keskelle templiä ja sulkekaamme templin ovet; sillä he tulevat tappamaan sinua, ja he tulevat yöllä sinua tappamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Minä vastasin; pitääkö senkaltaisen miehen kuin minä olen pakeneman? ja kuka olis niinkuin minä, joka menis templiin, että hän sais elää? En minä mene sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Sillä katso, minä ymmärsin hyvin, ettei Jumala ollut häntä lähettänyt; vaan hän ennusti minua vastaan, sillä Tobia ja Sanballat olivat palkanneet hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Sentähden hän oli palkattu, että minä olisin peljännyt ja olisin niin tehnyt, ja syntiä tehnyt, että he olisivat saaneet pahan huudon, jolla he olisivat minua häväisseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Minun Jumalani! muista Tobiaa ja Sanballatia näiden heidän töidensä jälkeen, ja Noadiaa naisprophetaa ja muita prophetaita jotka minua tahtoivat peljättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Ja muuri tuli valmiiksi viidennellä päivällä kolmattakymmentä Elulin kuuta, kahden päivän kuudettakymmentä kuluttua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Niin tapahtui, että kuin kaikki meidän vihollisemme sen kuulivat, niin kaikki pakanat pelkäsivät, jotka meidän ympärillämme olivat, ja he hämmästyivät kovin keskenänsä; sillä he ymmärsivät tämän työn olevan meidän Jumalaltamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Ja siihen aikaan oli monta Juudan ylimmäisistä siellä, joiden kirjat menivät usein Tobialle ja Tobian kirjat heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Sillä monta oli Juudalaisista, jotka olivat vannoneet hänen kanssansa; sillä hän oli Sekanian Aran pojan vävy, ja hänen pojallansa Johananilla oli Mesullamin Berekian pojan tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Ja he puhuivat hyvin minun edessäni hänestä ja veivät minun puheeni hänen tykönsä; niin Tobia lähetti kirjan minulle peljättääksensä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Mutta sittekuin muurit olivat rakennetut, panin minä portit; ja toimitettiin ovenvartiat, veisaajat ja Leviläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Ja minä käskin veljeäni Hanania, ja Hananiaa, linnan vanhinta Jerusalemissa (sillä hän oli uskollinen ja Jumalaa pelkääväinen mies monen suhteen),');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Ja sanoin heille: ei Jerusalemin portteja ennen pidä avattaman, kuin aurinko lämpiää, ja kuin vielä työtä tehdään, niin pitää portit pantaman kiinni ja teljettämän. Ja vartiat asetettiin Jerusalemin asuvaisista jokainen paikkaansa, ja kukin oman huoneensa kohdalle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Sillä kaupunki oli avara ja suuri, mutta kansaa oli siinä vähän; ja ei olleet huoneet rakennetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Ja minun Jumalani lykkäsi mieleeni, että minä kokosin ylimmäiset ja päämiehet ja kansan, ja luin heidät; ja minä löysin heidän mieslukunsa kirjan, jotka ennen olivat tulleet vankeudesta, ja minä löysin siinä kirjoitettuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Nämät ovat maakunnan lapset, jotka palasivat poisviedyistä vangeista, jotka Nebukadnetsar Babelin kuningas oli vienyt pois; ja he palasivat Jerusalemiin ja Juudaan, jokainen kaupunkiinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Jotka tulivat Serubbabelin, Jesuan, Nehemia, Asarian, Raamian, Nahamanin, Mordekain, Bilsan, Misperetin, Bigvain, Nehumin ja Baenan kanssa. Tämä on Israelin miesten luku:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Baroksen lapsia, kaksituhatta, sata ja kaksikahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sephatian lapsia, kolmesataa ja kaksikahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Aran lapsia, kuusisataa ja kaksikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Pahatmoabin lapsia, Jesuan ja Joabin lasten seassa, kaksituhatta, kahdeksansataa ja kahdeksantoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Elamin lapsia, tuhannen, kaksisataa ja neljäkuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Sattun lapsia, kahdeksansataa ja viisiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Sakkain lapsia seitsemänsataa ja kuusikymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binnuin lapsia, kuusisataa ja kahdeksanviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Bebain lapsia, kuusisataa ja kahdeksankolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Asgadin lapsia, kaksituhatta, kolmesataa ja kaksikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikamin lapsia, kuusisataa ja seitsemänseitsemättäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvain lapsia, kaksituhatta ja seitsemänseitsemättäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Adinin lapsia, kuusisataa ja viisikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Aterin lapsia Hiskiasta, yhdeksänkymmentä ja kahdeksan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Hasumin lapsia, kolmesataa ja kahdeksankolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Besain lapsia, kolmesataa ja neljäkolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Hariphin lapsia, sata ja kaksitoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Gibeonin lapsia, yhdeksänkymmentä ja viisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Betlehemin ja Netophan miehiä sata ja kahdeksanyhdeksättäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Anatotin miehiä, sata ja kahdeksankolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Betasmavetin miehiä, kaksiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Kirjatjearimin, Kaphiran ja Beerotin miehiä, seitsemänsataa ja kolmeviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Raman ja Gabaan miehiä, kuusisataa ja yksikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mikmaan miehiä, sata ja kaksikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Betelin ja Ain miehiä, sata ja kolmekolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Toisen Nebon miehiä, kaksikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Toisen Elamin lapsia, tuhannen, kaksisataa ja neljäkuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Harimin lapsia, kolmesataa ja kaksikymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Jerihon lapsia, kolmesataa ja viisiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Lodin, Hadadin ja Onon lapsia, seitsemänsataa ja yksikolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Senaan lapsia, kolmetuhatta, yhdeksänsataa ja kolmekymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Papit: Jedajan lapsia Jesuan huoneesta, yhdeksänsataa ja kolmekahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Immerin lapsia, tuhannen ja kaksikuudettakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pashurin lapsia, tuhannen, kaksisataa ja seitsemänviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Harimin lapsia, tuhannen ja seitsemäntoistakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Leviläiset: Jesuan lapsia Kadmielista Hodevan lasten seasta, neljäkahdeksattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Veisaajat: Asaphin lapsia, sata ja kahdeksanviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Ovenvartiat olivat Sallumin lapset, Aterin lapset, Talmonin lapset, Akkubin lapset, Hatitan lapset, Sobain lapset, (kaikki yhteen) sata ja kahdeksanneljättäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Netinimit: Zihan lapset, Hasuphan lapset, Taboatin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Keroksen lapset, Sian lapset, Padonin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Libanan lapset, Hagaban lapset, Salmain lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Hananin lapset, Giddelin lapset, Gaharin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reajan lapset, Resinin lapset, Nekodan lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gassamin lapset, Ussan lapset, Passean lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Besain lapset, Megunimin lapset, Nephusesimin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbukin lapset, Haguphan lapset, Harhurin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Batslitin lapset, Mehidan lapset, Harsan lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkoksen lapset, Siseran lapset, Thaman lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Netsian lapset, Hatiphan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Salomon palveliain lapsia oli: Sotain lapset, Sopheretin lapset, Peridan lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaelan lapset, Darkonin lapset, Giddelin lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Sephatian lapset, Hattilin lapset, PokeretZebaimin lapset, Amonin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Kaikkia Netinimein ja Salomon palveliain lapsia oli (yhteen) kolmesataa, yhdeksänkymmentä ja kaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Ja nämä menivät ylös Telmelasta, Telharsasta: Kerubi, Addon ja Immer; mutta ei he tietäneet isäinsä huonetta taikka siementänsä, olivatko he Israelista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delajan lapset, Tobian lapset, Nekodan lapset, kuusisataa ja kaksiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Ja papeista: Hobajan lapset, Hakkotsin lapset, Barsillain lapset, joka otti emännän Barsillain Gileadilaisen tyttäristä, ja kutsuttiin sitte heidän nimellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Nämä etsivät sukukuntansa polvilukukirjaa; ja ettei sitä löydetty, hyljättiin he pappeudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Ja Tirsata sanoi heille, ettei heidän pitänyt syömän siitä kaikkein pyhimmästä, ennenkuin pappi seisois valkeudessa ja täydellisyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Koko joukko yhteen oli kaksiviidettäkymmentä tuhatta, kolmesataa ja kuusikymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Paitsi heidän palvelioitansa ja piikojansa, joita oli seitsemäntuhatta, kolmesataa ja seitsemänneljättäkymmentä. Niin myös heidän seassansa oli veisaajia, miehiä ja vaimoja, kaksisataa ja viisiviidettäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Seitsemänsataa ja kuusineljättäkymmentä hevoista; kaksisataa ja viisiviidettäkymmentä muulia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Neljäsataa ja viisineljättäkymmentä kamelia; kuusituhatta, seitsemänsataa ja kaksikymmentä aasia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Ja muutamat ylimmäistä isistä antoivat rakennukseen: Tirsata antoi tavaraksi tuhannen kultapenninkiä, viisikymmentä maljaa, viisisataa ja kolmekymmentä papin hametta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Ja muutamat ylimmäisistä isistä antoivat rakennuksen tavaraksi kaksikymmentä tuhatta kultapenninkiä, kaksituhatta ja kaksisataa leiviskää hopiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'Ja muu kansa antoi kaksikymmentä tuhatta kultapenninkiä, ja kaksituhatta leiviskää hopiaa, ja seitsemänseitsemättäkymmentä papin hametta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'Ja papit, Leviläiset, ovenvartiat, veisaajat, ja muutamat kansasta ja Netinimit ja koko Israel asuivat kaupungeissa. Ja seitsemännen kuukauden lähestyessä olivat Israelin lapset kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Sitte kokoontui kaikki kansa niinkuin yksi mies sille kadulle, joka on Vesiportin edessä, ja sanoivat Esralle, kirjanoppineelle, että hän tois Moseksen lakikirjan, jonka Herra oli Israelille käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Ja Esra pappi toi lakikirjan kansan eteen, sekä miesten että vaimoin, ja kaikkein jotka ymmärtää ja kuulla taisivat, ensimäisenä päivänä seitsemättä kuuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Ja hän luki siitä kadulla Vesiportin edessä aamusta hamaan puolipäivään asti miesten ja vaimoin edessä, ja jokaisen joka ymmärtää taisi; ja kaiken kansan korvat olivat lakikirjaan käännetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Ja Esra, kirjanoppinut, seisoi korkialla puuistuimella, jonka he sitä varten olivat tehneet; ja Mattitia, Sema, Anaja, Uria, Hilkia ja Maeseja seisoivat hänen vieressänsä hänen oikialla puolellansa; ja hänen vasemmalla puolellansa seisoivat Pedaja, Misael, Malkia, Hasum, Hasbaddana, Sakaria ja Mesullam.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Ja Esra avasi kirjan kaiken kansan edessä; sillä hän seisoi ylempänä kaikkea kansaa. Ja kuin hän sen avasi, niin seisoi kaikki kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Ja Esra kiitti Herraa, suurta Jumalaa, ja kaikki kansa vastasi nostetuilla käsillä: amen! ja he kumarsivat ja rukoilivat Herraa kasvoillansa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Ja Jesua, Bani, Serebia, Jamin, Akub, Sabtai, Hodija, Maeseja, Kelita, Asaria, Josabad, Hanan, Pelaja ja Leviläiset opettivat kansan lakia ymmärtämään; ja kansa seisoi alallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Ja he lukivat Jumalan lakikirjan selkiästi ja niin ymmärrettävästi, että he ymmärsivät, mitä luettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Ja Nehemia, joka on Tirsata, ja Esra pappi, kirjanoppinut, ja Leviläiset jotka kansan opettivat ymmärtämään, sanoivat kansalle: tämä päivä on pyhä Herralle teidän Jumalallenne: älkäät murehtiko ja älkäät itkekö! sillä kuin kansa kuuli lain sanat, niin he kaikki itkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Ja hän sanoi heille: menkäät ja syökäät lihavaa, ja juokaat makiaa, ja lähettäkäät niille myös osa, joilla ei mitään ole valmistettu; tämä päivä on pyhä meidän Herrallemme, sentähden älkäät murehtiko; sillä Herran ilo on teidän väkevyytenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Ja Leviläiset vaikittivat kaiken kansan ja sanoivat: olkaat ääneti, sillä tämä päivä on pyhä, älkäät murehtiko!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Ja kaikki kansa meni syömään ja juomaan, ja lähettämään osia ulos, ja tekivät suuren ilon; sillä he olivat ymmärtäneet ne sanat, jotka heille olivat ilmoitetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Toisena päivänä tulivat ylimmäiset isät kaikesta kansasta, papit ja Leviläiset kokoon, Esran kirjanoppineen tykö, oppimaan lain sanoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Ja he löysivät laissa kirjoitetun, että Herra oli käskenyt Moseksen kautta Israelin lasten asua lehtimajoissa seitsemännen kuun juhlalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'Ja he antoivat sen julkisesti ilmoittaa ja kuuluttaa kaikissa kaupungeissansa ja Jerusalemissa, ja sanoa: menkäät ulos vuorelle ja tuokaat öljypuun oksia, balsamipuun oksia, myrrhamipuun oksia, palmupuun oksia ja paksuista puista oksia, tehdäksenne majoja, niinkuin kirjoitettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Ja kansa menivät ulos ja toivat, ja tekivät itsellensä lehtimajoja, jokainen kattonsa päälle ja kartanoihinsa, ja Jumalan huoneen kartanoihin, ja Vesiportin kadulle, ja Ephraimin portin kadulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Ja kaikki kansa, joka palannut oli vankeudesta, teki lehtimajoja ja asui niissä; sillä ei Israelin lapset niin olleet tehneet hamasta Josuan Nunin pojan ajasta niin siihen päivään asti. Ja siinä oli sangen suuri ilo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Ja luettiin joka päivä Jumalan lakikirjaa, ensimmäisestä päivästä niin viimeiseen. Ja he pitivät juhlaa seitsemän päivää ja kahdeksantena päivänä päätöksen, tavan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Neljäntenä päivänä kolmattakymmentä tätä kuuta tulivat Israelin lapset kokoon, paastoten, säkeissä, ja multaa päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Ja he eroittivat Israelin siemenen kaikista muukalaisista lapsista; ja he tulivat edes ja tunnustivat syntinsä ja isäinsä pahat teot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Ja he nousivat ylös siallensa, ja heidän edessänsä luettiin neljä kertaa päivässä Herran heidän Jumalansa lakikirjasta; ja he tunnustivat, ja rukoilivat Herraa Jumalaansa neljä kertaa päivässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Ja Leviläisten korkopaikalle nousivat Jesua, Bani, Kadmiel, Sebania, Bunni, Serebia, Bani ja Kenani, ja huusivat suurella äänellä Herran Jumalansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'Ja Leviläiset Jesua, Bani, Kadmiel, Hasabnea, Serebia, Hodia, Sebania ja Petahia sanoivat: nouskaat, kiittäkäät Herraa teidän Jumalaanne ijankaikkisesta ijankaikkiseen! Ja sinun kunnias nimi kiitetään, joka on korotettu ylitse kaiken siunauksen ja kiitoksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Sinä olet Herra yksinäs, sinä olet luonut taivaat ja taivasten taivaat kaiken heidän sotaväkensä kanssa, maan ja kaikki, mitä sen päällä on, meret ja kaikki, mitä niissä on; ja sinä teet kaikki nämät eläväksi; ja taivaan sotajoukot kumartaen rukoilevat sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Sinä olet Herra Jumala, joka valitsit Abramin, ja johdatit hänen Kaldean Uurista ja nimitit hänet Abrahamiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Ja löysit hänen sydämensä uskolliseksi sinun edessäs, ja teit liiton hänen kanssansa, antaakses hänen siemenellensä Kanaanealaisten, Hetiläisten, Amorilaisten, Pheresiläisten, Jebusilaisten ja Girgasilaisten maan, ja olet pitänyt sanas, sillä sinä olet vanhurskas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Ja sinä näit isäimme viheliäisyyden Egyptissä, ja kuulit heidän huutonsa Punaisen meren tykönä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Ja teit tunnustähtejä ja ihmeitä Pharaolle, ja kaikissa hänen palvelioissansa, ja kaikessa hänen maansa kansassa; sillä sinä tiesit heidän ylpiäksi heitä vastaan; ja teit itselles nimen, niinkuin se tänäkin päivänä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Ja sinä jaoit meren heidän edessänsä, niin että he kuivalla menivät keskitse meren; ja heidän vainoojansa heitit sinä syvyyteen, niinkuin kiven väkeviin vesiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Ja päivällä sinä johdatit heitä pilven patsaalla ja yöllä tulen patsaalla, valaisten heille tietä, jota he vaelsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Sinä tulit Sinain vuorelta alas ja puhuit heidän kanssansa taivaasta, ja annoit heille oikiat tuomiot ja totisen lain, hyvät säädyt ja käskyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Ja ilmoitit heille pyhän sabbatis, ja annoit heille käskyt, säädyt ja lain palvelias Moseksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Ja annoit heille leipää taivaasta, kuin he isosivat, ja annoit veden vuotaa kalliosta, kuin he janosivat; ja puhuit heille, että heidän piti menemän ja omistaman maan, jonka tähden sinä nostit kätes antaakses sen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Mutta he ja meidän isämme tulivat ylpeiksi ja kovakorvaisiksi, ettei he totelleet sinun käskyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Ja eipä he tahtoneet kuullakaan, ja ei he ajatelleet niitä ihmeitä, jotka sinä teit heidän kanssansa; vaan he tulivat uppiniskaisiksi ja asettivat päämiehen palataksensa takaperin orjuuteensa, vastahakoisuudessansa; mutta sinä Jumala olet anteeksiantaja, armollinen, laupias ja pitkämielinen, sangen suuri laupiudesta, ja et sinä heitä hyljännyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Vaikka he tekivät valetun vasikan ja sanoivat: tämä on sinun Jumalas, joka sinun johdatti Egyptistä, ja tekivät suuren häväistyksen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Et sinä kuitenkaan heitä hyljännyt korvessa, sinun suuren laupiutes tähden. Ja pilven patsas ei mennyt heiltä pois päivällä, johdattamasta heitä tiellä, eikä tulen patsas yöllä, valaisemasta heille tietä, jota he vaelsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Ja sinä annoit heille hyvän henkes opettamaan heitä; et sinä myös kieltänyt mannaas heidän suustansa, ja sinä annoit heille vettä heidän janossansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Sinä ravitsit heitä korvessa neljäkymmentä ajastaikaa, ettei heiltä mitään puuttunut; ei heidän vaatteensa vanhentuneet, eikä heidän jalkansa ajettuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Sinä annoit heille valtakunnat ja kansat, ja jaoit heidät sinne ja tänne, omistamaan Sihonin maata, ja Hesbonin kuninkaan maata ja Ogin Basanin kuninkaan maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Ja sinä enensit heidän lapsensa niinkuin tähdet taivaassa, ja veit heidät siihen maahan, josta sinä heidän isillensä sanonut olit, että heidän piti sinne menemän ja omistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Ja lapset menivät ja omistivat maan; ja sinä nöyryytit Kanaanealaisten maan asujamet heidän edessänsä, ja annoit heitä heidän käsiinsä, niin myös heidän kuninkaansa ja maan kansat, tehdä heille oman tahtonsa perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Ja he voittivat vahvat kaupungit ja lihavan maan, ja omistivat huoneet täynnä kaikkinaista viljaa, vuojonkivisiä kaivoja, viinamäkiä ja öljymäkiä ja paljon hedelmällisiä puita. Ja he söivät ja ravittiin, ja lihoivat, ja elivät herkullisesti sinun suuresta hyvyydestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Mutta he tulivat tottelemattomiksi ja vastahakoisiksi sinua vastaan, ja heittivät sinun lakis selkänsä taa, ja tappoivat sinun prophetas, jotka heidän edessänsä todistivat, että he olisivat kääntyneet sinun tykös; ja he suuresti häpäisivät sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Sentähden sinä annoit heitä vihollistensa käsiin, jotka heitä ahdistivat. Ja he huusivat sinua ahdistuksensa aikana, ja sinä kuulit taivaasta heitä, ja laupiutes tähden annoit sinä heille pelastajat, jotka heitä auttivat vihollistensa käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mutta kun he lepoon tulivat, palasivat he pahaa tekemään sinun edessäs: niin sinä hylkäsit heitä vihollistensa käsiin, jotka heitä hallitsivat. Niin he käänsivät heitänsä ja taas huusivat sinua, ja sinä kuulit heitä taivaasta ja pelastit heitä monta aikaa, sinun suuren laupiutes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Ja sinä annoit heille tiettäväksi tehdä, että heidän piti kääntämän itsensä sinun lakis tykö; mutta he olivat ylpiät ja ei totelleet sinun käskyjäs, ja syntiä tekivät sinun tuomiotas vastaan, joita jos ihminen tekee, hän elää niissä; ja he käänsivät hartionsa ja kovensivat niskansa, ja ei totelleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Ja sinä kärsit heitä monta ajastaikaa, ja annoit heille tehdä tiettäväksi henkes kautta sinun prophetaissas; mutta ei he ottaneet korviinsa; sentähden sinä annoit heitä maan kansain käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Mutta suuren laupiutes tähden et sinä heitä peräti teloittanut eli hyljännyt; sillä sinä olet armollinen ja laupias Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Nyt meidän Jumalamme! sinä suuri Jumala, väkevä ja peljättävä, joka pidät liiton ja laupiuden, älä vähäksy kaikkia niitä vaivoja, jotka meille ja meidän kuninkaillemme, päämiehillemme, papeillemme, prophetaillemme, isillemme ja kaikelle sinun kansalles, Assurin kuninkaan ajasta niin tähän päivään asti, tapahtuneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Sinä olet vanhurskas kaikissa niissä, mitkä sinä meidän päällemme olet tuonut; sillä sinä olet oikein tehnyt, mutta me olemme olleet jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Ja meidän kuninkaamme, päämiehemme, meidän pappimme ja isämme ei ole tehneet sinun lakis jälkeen, eikä lukua pitäneet sinun käskyistäs ja todistuksistas, joita annoit heille ilmoitettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Ja ei he palvelleet sinua valtakunnassansa ja sinun suuressa hyvyydessäs, jonka sinä annoit heille, ja siinä avarassa ja lihavassa maassa, jonkas annoit heidän eteensä; ja ei he palanneet pahoista töistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Katso, me olemme palveliat tänäpänä; ja siinä maassa, jonka annoit meidän isillemme, että he olisivat syöneet hänen hedelmiänsä ja hyvyyttänsä, katso, siinä me olemme palveliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Ja se enentää tulonsa kuninkaille, jotka panit meidän päällemme meidän synteimme tähden; ja he hallitsevat meidän ruumiimme ja karjamme oman tahtonsa jälkeen, ja me olemme juuri suuressa tuskassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Ja näissä kaikissa teemme me vahvan liiton, ja kirjoitamme sen, ja annamme meidän päämiestemme, Leviläistemme sen sinetillänsä vahvistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Ja ne, jotka sinettinsä painoivat, olivat Nehemia Tirsata Hakalian poika, ja Zidkia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Asaria, Jeremia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Amaria, Malkia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebania, Malluk,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremot, Obadia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginnetun, Baruk,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abia, Mijamin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maasia, Bilgai ja Semaja: ne olivat papit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Mutta Leviläiset olivat: Jesua Asanian poika, Binnui, Henadadin lapsista, Kadmiel,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Ja heidän veljensä: Sebania, Hodia, Kelita, Pelaja, Hanan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Miika, Rehob, Hasabia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Sakkur, Serebia, Sebania,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodia, Bani ja Beninu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Kansan päämiehet olivat: Paros, Pahatmoab, Elam, Sattu, Bani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Asgad, Bebai,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonia, Bigvai, Adin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Hiskia, Assur,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodia, Hasum, Betsai,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Hariph, Anatot, Neubai,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesullam, Hesir,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesesabel, Zadok, Jaddua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatia, Hanan, Anaja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hosea, Hanania, Hasub,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Halohes, Pilha, Sobek,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna, Maeseja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ahia, Hanan, Anan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluk, Harim ja Baena;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Ja muu kansa, papit, Leviläiset, ovenvartiat, veisaajat, Netinimit ja kaikki, jotka olivat erinneet maan kansoista Jumalan lain tykö vaimoinsa, poikainsa ja tytärtensä kanssa, ja kaikki, jotka sen ymmärtää taisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Ja heidän voimallisensa ottivat veljeinsä puolesta sen vastaan. Ja he tulivat vannomaan ja lupaamaan valallansa, vaeltaaksensa Jumalan laissa, joka heille oli annettu Moseksen Jumalan palvelian kautta, pitääksensä ja tehdäksensä kaikki Herran meidän Jumalamme käskyt, tuomiot ja säädyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Ja ettei meidän pidä antaman maan kansoille tyttäriämme, emmekä myös ota pojillemme heidän tyttäriänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Ja jos maan kansa tuo sabbatina kauppakalua ja kaikkinaista vuoden tuloa myytäväksi, niin emme ota heiltä sabbatina ja pyhäpäivänä; ja että me seitsemännen vuoden annamme olla vapaana kaikista rasituksista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Ja panemme käskyn itse päällemme, että annamme kolmannen osan yhdestä siklistä ajastajasta Jumalamme huoneen palvelukseen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Näkyleiväksi, alinomaiseksi ruokauhriksi, alinomaiseksi polttouhriksi, sabbatina, uusilla kuilla ja juhlapäivinä, ja pyhitetyille, ja syntiuhriksi, jolla Israel sovitetaan, ja kaikkinaiseksi tarpeeksi Jumalamme huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Ja me heitimme arpaa pappein, Leviläisten ja kansan välillä halkouhrista, joita joka vuosi piti vietämän meidän Jumalamme huoneesen, isäimme huonetten jälkeen, määrätyillä ajoilla poltettaa Herran meidän Jumalamme alttarilla, niinkuin laissa kirjoitettu on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Ja että me joka vuosi tuomme maamme esikoisia ja kaikkinaisten puiden ensimäisiä hedelmiä Herran huoneesen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Ja esikoiset pojistamme ja eläimistämme, niinkuin laissa kirjoitettu on; ja esikoiset härjistämme ja lampaistamme, että meidän pitää viemän meidän Jumalamme huoneesen papeille, jotka palvelevat Jumalamme huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Ja meidän pitää viemän taikinasta ensimäisen, ja ylennyksemme, ja kaikkinaisia puun hedelmiä, viinaa ja öljyä papeille, meidän Jumalamme huoneen kammioihin, ja Leviläisille kymmenykset meidän maastamme, että Leviläiset kaikissa kaupungeissa pitää saaman kymmenykset meidän työstämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Ja papin Aaronin pojan pitää myös saaman Leviläisten kanssa heidän kymmenyksistänsä, ja Leviläisten pitää viemän kymmenyksistänsä kymmenennen osan meidän Jumalamme huoneesen, tavarahuoneen kammioihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Sillä Israelin lapset ja Levin lapset piti myös viemän jyväin, viinan ja öljyn ylennyksen kammioihin; ja siellä pitää oleman pyhät astiat, ja papit, jotka palvelevat, ja ovenvartiat, ja veisaajat. Ja emme luovu meidän Jumalamme huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Ja kansan päämiehet asuivat Jerusalemissa; mutta muu kansa heitti arpaa, saattaaksensa yhden kymmenestä asumaan Jerusalemiin, siihen pyhään kaupunkiin, mutta yhdeksän osaa kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Ja kansa siunasi kaikkia niitä miehiä, jotka mielistyivät asumaan Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Nämä ovat maakunnan päämiehet, jotka asuivat Jerusalemissa; mutta Juudan kaupungeissa asui itsekukin omaisuudessansa kaupungeissansa: Israel, papit, Leviläiset, Netinimit ja Salomon palveliain lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Ja Jerusalemissa asuivat muutamat Juudan ja Benjaminin lapsista. Juudan lapsista: Ataja Ussian poika, Sakarian pojan, Amarian pojan, Sephatian pojan, Mahalaleelin pojan, Peretsen lapsista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Ja Maeseja Barukin poika, Kolhosen pojan, Hasajan pojan, Adajan pojan, Jojaribin pojan, Sakarian pojan, Silomin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Kaikki Peretsen lapset, jotka asuivat Jerusalemissa, neljäsataa ja kahdeksanseitsemättäkymmentä vahvaa miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Nämät olivat Benjaminin lapset: Sallu Mesullamin poika, Joedin pojan, Pedajan pojan, Kolajan pojan, Maasejan pojan, Itielin pojan, Jesajan pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'Ja hänen jälkeensä Gabbai, Sallai, yhdeksänsataa ja kahdeksankolmattakymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Ja Joel Sikrin poika oli heidän esimiehensä, ja Juuda Senuan poika oli toisena kaupungin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Papeista, Jedaja Jojaribin poika, Jakin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja Hilkian poika, Mesullamin pojan, Zadokin pojan, Merajotin pojan, Ahitobin pojan, Jumalan huoneen päämies,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'Ja heidän veljiänsä, jotka huoneessa työtä tekivät, oli kahdeksansataa ja kaksikolmattakymmentä; ja Adaja Jerohamin poika, Pelalian pojan, Amsin pojan, Sakarian pojan, Pashurin pojan, Malkian pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'Ja hänen veljensä isäin päämiehet kaksisataa ja kaksiviidettäkymmentä; ja Amasia Asareelin poika, Ahasain pojan, Mesillemotin pojan, Immerin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'Ja heidän veljensä, väkevät miehet, sata ja kahdeksankolmattakymmentä; ja Sabdiel Gedolimin poika oli heidän esimiehensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Leviläisistä: Semaja Hasubin poika, Asrikamin pojan, Hasabian pojan, Bunnin pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'Ja Sabtai ja Josabad, Leviläisten päämiehistä, Jumalan huoneen ulkonaisessa työssä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'Ja Mattania Miikan poika, Sabdin pojan, Asaphin pojan, joka oli ylimmäinen kiitosta alkamaan rukouksessa; ja Bakbukia toinen veljeinsä keskellä, ja Abda Sammuan poika, Galalin pojan, Jedutunin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Leviläisiä oli kaikkiansa pyhässä kaupungissa kaksisataa ja neljäyhdeksättäkymmentä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Ja ovenvartiat: Akkub, Talmon ja heidän veljensä, jotka porteissa vartioitsivat, sata ja kaksikahdeksattakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Mutta muut Israelista, papit ja Leviläiset olivat kaikissa Juudan kaupungeissa, jokainen omassa perinnössänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Ja Netinimit asuivat Ophelissa: ja Ziha ja Gispa olivat Netinimein päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Mutta Leviläisten esimies oli Jerusalemissa, Ussi Banin poika, Hasabian pojan, Mattanian pojan, Miikan pojan; veisaajat olivat Asaphin pojista, Jumalan huoneen työn tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Sillä se oli kuninkaan käsky heille, että veisaajille piti oleman päiväinen määrä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Ja Petaja Mesesabeelin poika Seran lapsista, Juudan pojan, oli kuninkaan käskyläinen kaikissa asioissa kansan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Ja Juudan lapset, ne jotka ulkona olivat kylissä heidän maassansa; muutamat asuivat Kirjatarbassa ja sen kylissä, ja Dibonissa ja sen kylissä, ja Kabseelissa ja sen kylissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'ja Jesuassa, Moladassa, Betpaletissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'Ja Hasarsualissa, Bersebassa ja sen kylissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Ja Ziklagissa ja Mekonassa ja sen kylissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'Ja Enrimmonissa, Zorgassa, Jarmutissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Zanoassa, Adullamissa ja sen kylissä, Lakiksessa ja sen kedolla Asekassa ja sen kylissä. Ja he oleskelivat hamasta Bersebasta niin Hinnomin laaksoon asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Mutta Benjaminin lapset Gabaasta asuivat Mikmassa, Ajassa ja Betelissä ja niiden kylissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anatotissa, Nobissa, Ananiassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hatsorissa, Ramassa, Gittaimissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadidissa, Ziboimissa, Neballatissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lodissa ja Onossa, Seppäin laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Ja muutamat Leviläiset asuivat Juudan ja Benjaminin rajoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Nämät ovat papit ja Leviläiset, jotka menivät ylös Serubbabelin Sealtielin pojan ja Jesuan kanssa: Seraja, Jeremia, Esra,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaria, Malluk, Hattus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sekania, Rehum, Meremot,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginetoi, Abia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadia, Bilga,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Jojarib, Jedaja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Hilkia ja Jedaja: nämät olivat pappein ja heidän veljeinsä päämiehet Jesuan aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Ja Leviläiset: Jesua, Binnui, Kadmiel, Serebia, Juuda ja Mattania kiitosvirtten päällä, hän ja hänen veljensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'Bakbukia ja Unni veljinensä olivat vartiana heidän tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jesua siitti Jojakimin, Jojakim siitti Eljasibin, Eljasib siitti Jojadan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada siitti Jonatanin, Jonatan siitti Jadduan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Ja Jojakimin aikana olivat nämät ylimmäiset isät pappein seassa: Serajasta Meraja, Jeremiasta Hanania,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Esrasta oli Mesullam, Amariasta Johanan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Mallukista Jonatan, Sebaniasta Joseph,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Harimista Adna, Merajotista Helkai,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Iddosta Sakaria, Ginthonista Mesullam,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abiasta Sikri, Minjaminista ja Moadiasta Piltai,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Bilgasta Sammua, Semajasta Jonatan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Jojaribista Matnai, Jedajasta Ussi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Sallaista Kallai, Amakista Eber,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hilkiasta Hasabia, Jedajasta Natanael.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Leviläiset Eljasibin, Jojadan, Johanan ja Jadduan aikana, kirjoitetut isäin päämiehet; niin myös papit, Dariuksen Persialaisen valtakuntaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Levin lapset, ylimmäiset isät, ovat kirjoitetut Aikakirjaan, Johananin Eljasibin pojan aikaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Ja Leviläisten päämiehet: Hasabia, Serebia ja Jesua Kadmielin poika, ja heidän veljensä heidän vieressänsä, ylistämässä ja kiittämässä, niinkuin David Jumalan mies oli käskenyt, yksi vartia toisen kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Mattania, Bakbukia, Obadia, Mesullam, Talmon ja Akkub olivat ovenvartiat, tavaraporttein vartioitsemisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Nämät olivat Jojakimin Jesuan pojan Jotsadakin pojan aikana, ja Nehemian maanvanhimman, ja Esran papin, kirjanoppineen, aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Ja Jerusalemin muurin vihkimiselle etsivät he Leviläisiä kaikista heidän paikoistansa, tuodaksensa heitä Jerusalemiin pitämään vihkimistä ilolla, kiitoksella, virsillä, symbaleilla, psalmeilla ja harpuilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Ja veisaajain lapset tulivat kokoon Jerusalemin ympäristöltä ja Netophatin kylistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Ja Gilgalin huoneesta, ja Gibean ja Asmavetin pelloilta; sillä veisaajat olivat rakentaneet itsellensä taloja Jerusalemin ympärillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Ja papit ja Leviläiset puhdistivat itsensä: he puhdistivat myös kansan ja portit ja muurit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Ja minä annoin Juudan päämiehet mennä ylös muurille, ja asetin kaksi suurta laulukuntaa ja juhlasaattoa muurin päälle: (yhden) oikialle puolelle Sontaporttia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Ja Hosaja ja toinen puoli Juudan päämiehistä kävivät heidän perässänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Ja Asaria, Esra, Mesullam,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juuda, Benjamin, Semaja ja Jeremia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Ja muutamat pappein lapsista vaskitorvein kanssa: Sakaria Jonatanin poika, Semajan pojan, Mattanian pojan, Mikajan pojan, Sakkurin pojan, Asaphin pojan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'Ja hänen veljensä Semaja, Asareel, Milalai, Gilalai, Maai, Netaneel, Juuda, Hanani, Davidin Jumalan miehen kanteleiden kanssa, ja Esra kirjanoppinut heidän edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Ja Lähdeporttia päin menivät he ylös heidän kohdallansa astuimia myöten Davidin kaupunkiin, (ja siitä) astuimilla muurein päälle, Davidin huoneesta Vesiporttiin asti itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Ja toinen laulukunta kävi vastaan, ja minä sen perässä, ja toinen puoli kansaa muurin päällä, Pätsitornista leviään muuriin saakka,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'Ja Ephraimin portista, Vanhan portin ja Kalaportin ja Hananeelin tornin ja Mean tornin ohitse Lammasporttiin asti; ja seisahtivat Vankiportissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Ja ne kaksi kiitoskuoria seisoivat Jumalan huoneessa, ja minä ja toinen puoli ylimmäisiä minun kanssani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Ja papit Eliakim, Maeseja, Minjamin, Mikaja, Eljoenai, Sakaria, Hanania olivat vaskitorvein kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'Ja Maeseja, Semaja, Eleatsar, Ussi, Johanan, Malkia, Elam ja Asar. Ja veisaajat veisasivat korkiasti, ja Jisrahia oli esimiehenä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Ja he uhrasivat sinä päivänä suuret uhrit, ja olivat iloiset; sillä Jumala oli heitä iloittanut suurella ilolla, että myös vaimot ja lapsetkin iloitsivat, ja Jerusalemin ilo kuului kauvas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Siihen aikaan asetettiin miehet tavarakammioin päälle, joissa ylennykset, ensimäiset hedelmät ja kymmenykset olivat, joita heidän piti kokooman kaupunkein pelloista, papeille ja Leviläisille jaettaa lain jälkeen; sillä Juudalaisilla oli ilo papeista ja Leviläisistä, jotka seisoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Ja he pitivät vaarin Jumalan vartiosta ja puhdistuksen vartiosta, niin myös veisaajista ja ovenvartioista, Davidin ja Salomon hänen poikansa käskyn jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Sillä Davidin ja Asaphin aikana olivat muinen asetetut ylimmäiset veisaajat, ja kiitosvirret ja kiitokset Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Mutta koko Israel antoi veisaajille ja ovenvartioille osan, Serubbabelin ja Nehemian aikana, joka päivä heidän osansa; ja pyhittivät sen Leviläisille, ja Leviläiset pyhittivät Aaronin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Siihen aikaan luettiin Moseksen kirjaa kansan edessä, ja siinä löydettiin kirjoitettuna, ettei kukaan Ammonilainen ja Moabilainen saa ikänänsä tulla Jumalan seurakuntaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Sillä ei he tulleet Israelin lapsia vastaan leivällä ja vedellä, vaan palkkasivat Bileamin heitä vastaan, kiroomaan heitä; mutta meidän Jumalamme käänsi kirouksen siunaukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Kuin he sen lain kuulivat, niin he eroittivat kaiken sekalaisen kansan Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Ja sitä ennen oli pappi Eljasib pantu meidän Jumalan huoneen kammioin päälle, Tobian lähimmäinen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'Ja hän oli tehnyt hänelle suuren kammion, johon he ennen olivat panneet ruokauhria, pyhää savua, astioita ja kymmenykset jyvistä, viinasta ja öljystä, jotka olivat käsketyt annettaa Leviläisille, veisaajille ja ovenvartioille, ja pappein ylennykset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Mutta en minä ollut silloin Jerusalemissa, kuin he kaikkia näitä tekivät; sillä Artahsastan Babelin kuninkaan toisena vuonna neljättäkymmentä tulin minä kuninkaan tykö, ja sain jonkun ajan perästä kuninkaalta luvan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'Ja tulin Jerusalemiin ja ymmärsin sen pahuuden, minkä Eljasib oli tehnyt Tobian tähden, että hän oli tehnyt hänelle kammion Jumalan huoneen kartanolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Ja minä paheksuin sitä kovin, ja heitin kaikki Tobian huoneen astiat kammiosta ulos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Ja käskin puhdistaa kammiot, ja panin niihin jälleen Jumalan huoneen astiat, ruokauhrit ja pyhän savun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Ja minä ymmärsin, ettei Leviläisille ollut annettu heidän osaansa, sentähden olivat Leviläiset ja veisaajat paenneet tekemään työtä kukin pellollensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Niin minä nuhtelin esimiehiä ja sanoin: miksi me Jumalan huoneen hylkäämme? Mutta minä kokosin heitä ja asetin siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Niin koko Juuda toi kymmenykset jyvistä, viinasta ja öljystä tavarakammioihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Ja minä panin sen tavaran päälle papin Selemian ja Zadokin, kirjanoppineen, ja Leviläisistä Padajan, ja heidän kätensä alla oli Hanan Sakkurin poika, Mattanian pojan: sillä he pidettiin uskollisina, ja he käskettiin jakaa veljillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Minun Jumalani, muista minua sen edestä, ja älä pyyhi laupiuttani pois, minkä minä olen tehnyt Jumalani huoneelle ja hänen vartiollensa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Silloin näin minä Juudassa tallattavan viinakuurnia sabbatina ja kannettavan viljalyhteitä, ja ajettavan aaseilla viinaa, viinamarjoja, fikunia, ja kaikkinaisia kuormia, ja tuotavan Jerusalemiin sabbatin päivänä: ja minä todistin heille sinä päivänä, jona he myivät ruokakalua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Siinä asui myös Tyrolaisia, jotka toivat kaloja ja kaikkinaista kauppakalua, ja myivät Juudan lapsille Jerusalemissa sabbatina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Niin minä nuhtelin Juudan päämiehiä ja sanoin heille: mikä paha se on, jonka te teette, ja rikotte sabbatin päivän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Eikö teidän isänne niin tehneet? ja meidän Jumalamme toi kaiken tämän onnettomuuden meidän päällemme ja tämän kaupungin päälle; ja te saatatte vielä nyt vihan enemmäksi Israelin päälle, että te rikotte sabbatin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Ja kuin varjo peitti Jerusalemin portin ennen sabbatia, käskin minä ne sulkea, ja kielsin avaamasta ennenkuin jälkeen sabbatin. Ja minä panin muutamia palvelioitani portteihin, ettei yhtään kantamusta olisi tuotu sisälle sabbatin päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Niin kauppamiehet ja kaikkinaisten kaluin myyjät olivat ulkona Jerusalemista yötä kerran eli kaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Niin minä todistin heidän edessänsä ja sanoin heille: miksi te olette yötä ympäri muurin? Jos te vielä kerran sen teette, niin minä lasken käteni teidän päällenne. Ja siitä ajasta ei he sabbatina tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Ja minä sanoin Leviläisille, jotka puhtaat olivat: tulkaat ja ottakaat porteista vaari, ja pyhittäkäät sabbatin päivä. Minun Jumalani, muista minua senkin edestä, ja säästä minua suuren laupiutes tähden!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Minä näin myös silloin Juudalaiset ottavan Asdodilaisia, Ammonilaisia ja Moabilaisia vaimoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Ja heidän lapsensa puhuivat puolittain Asdodin kielellä, ja ei taitaneet puhua Juudan kielellä, mutta jokaisen kansan kielellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Ja minä nuhtelin heitä ja kirosin heitä, ja löin muutamia miehiä, ja repelin hiuksia heidän päästänsä, ja vannotin heitä Jumalan kautta: ei teidän pidä antaman tyttäriänne heidän pojillensa, eikä ottaman heidän tyttäriänsä teidän pojillenne eli itse teillenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Eikö Salomo Israelin kuningas niiden kanssa syntiä tehnyt? Ja ei kuitenkaan ollut yhtään kuningasta hänen vertaistansa monen pakanan seassa, ja hän oli rakas Jumalallensa, ja Jumala pani hänen koko Israelin kuninkaaksi; kuitenkin saattivat muukalaiset hänenkin syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Ettekö te sitä ole kuulleet, koska te kaikkea tätä suurta pahuutta teette, että te rikotte Jumalaamme vastaan, ottaissanne muukalaisia vaimoja?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Ja yksi Jojadan lapsista, Eljasibin ylimmäisen papin poika, oli Sanballatin Horonilaisen vävy; mutta minä ajoin hänen pois minun tyköäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Muista heitä minun Jumalani, jotka turmelevat pappiuden, ja pappien ja Leviläisten liiton!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Niin minä puhdistin heidät kaikista muukalaisista, ja asetin pappein ja Leviläisten vartiat, kunkin palvelukseensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'Ja uhrihalkoja määrätyillä ajoilla, ja ensimäisiä hedelmiä. Minun Jumalani, muista minua hyvyydellä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Siihen aikaan, kuin Ahasverus hallitsi Indiasta Etiopiaan asti, sataa ja seitsemääkolmattakymmenta maakuntaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Ja kuin hän istui valtakuntansa istuimella, Susanin linnassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Kolmantena hallituksensa vuonna, teki hän pidot kaikille päämiehillensä ja palvelioillensa, Persian ja Median sodanpäämiehille ja maakuntain hallitsioille hänen edessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Näyttäin heille valtakuntansa kunnian rikkaudet ja herrautensa kalliit kaunistukset monta päivää, sata ja kahdeksankymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Ja kuin ne päivät olivat täytetyt, teki kuningas kaikelle kansalle, joka Susanin linnassa oli, sekä suurille että pienille pidot seitsemäksi päiväksi, kuninkaallisen huoneen yrttitarhan salissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Siellä riippuivat valkiat, viheriäiset ja sinertävät seinävaatteet, yhteen sidotut kalliilla liinaisilla ja purppuraisilla siteillä hopiarenkaissa, marmorikivisten patsasten päällä; vuoteet olivat kullasta ja hopiasta, permanto oli laskettu viheriäisistä, valkeista, keltaisista ja mustista marmorikivistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Ja juomaa kannettiin kultaisilla astioilla, ja aina toisilla ja toisilla astioilla, ja kuninkaallista viinaa yltäkyllä, kuninkaan varan perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Ja juominen tapahtui säädöksen jälkeen, niin ettei yksikään toistansa vaatinut; sillä kuningas oli niin käskenyt kaikille edeskäyville huoneessansa, tehdä jokaisen mielen nouteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Ja kuningatar Vasti teki myös pidot vaimoille kuningas Ahasveruksen kuninkaallisessa huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Ja seitsemäntenä päivänä, kuin kuningas oli iloinen viinasta, käski hän Mehumanin, Bistan, Harbonan, Bigtan, Abagtan, Setarin ja Karkaan, seitsemän kamaripalveliaa, jotka palvelivat kuningas Ahasverusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Tuomaan kuningatar Vastia kuninkaan eteen hänen kuninkaallisella kruunullansa, näyttääksensä kansalle ja päämiehille hänen kauneuttansa; sillä hän oli kaunis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Mutta kuningatar Vasti ei tahtonut tulla kuninkaan käskyn jälkeen, kuin hän oli käskenyt kamaripalveliain kautta. Niin kuningas vihastui kovin, ja hänen vihansa syttyi hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Kuningas sanoi viisaille, jotka ymmärsivät maan tavat (sillä kuninkaan asia piti ratkaistaman kaikkein lain ja oikeuden ymmärtäväisten edessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'Ja lähin häntä olivat: Karsena, Setar, Admata, Tarsis, Meres, Marsena ja Memukan, seitsemän Persian ja Median päämiestä, jotka näkivät kuninkaan kasvot ja istuivat ylimmäisinä valtakunnassa:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Mitä kuningatar Vastille pitää tehtämän oikeuden jälkeen, ettei hän tehnyt kuningas Ahasveruksen sanan jälkeen, hänen kamaripalveliainsa kautta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Niin sanoi Memukan kuninkaan ja päämiesten edessä: kuningatar Vasti ei ole ainoastansa tehnyt pahoin kuningasta vastaan, mutta myös kaikkia päämiehiä ja kaikkia kansoja vastaan, jotka ovat kaikissa kuningas Ahasveruksen maakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Sillä tämä kuningattaren teko hajoo kaikkein vaimoin tykö, niin että hekin katsovat miehensä ylön silmäinsä edessä, ja sanovat: kuningas Ahasverus käski kuningatar Vastin tulla eteensä, mutta ei hän tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Niin Persian ja Median päämiesten emännät sanovat tänäpänä kaikille kuninkaan päämiehille, kuin he kuulevat tämän kuningattaren teon; niin siitä tulee kyllä ylönkatsetta ja vihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Jos siis kuninkaalle kelpaa, niin antakaan kuninkaallisen käskyn käydä ulos ja kirjoittaa Persian ja Median lakiin jota ei kenkään rikkoa tohdi: ettei Vasti pidä enää tuleman kuningas Ahasveruksen eteen, ja antakaan kuningas hänen valtakuntansa hänen lähimmäisellensä, joka on parempi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Ja tämä kuninkaan kirja, joka nyt tehdään, kuulukoon ympärinsä koko hänen valtakuntansa, joka suuri on: että jokainen vaimo pitäis miehensä kunniassa, suurten ja pienten seassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Tämä kelpasi kuninkaalle ja päämiehille; ja kuningas teki Memukanin sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Niin kirjat lähetettiin kaikkiin kuninkaan maakuntiin, jokaiseen maakuntaan heidän kirjoituksensa jälkeen, ja kaikkein kansain tykö heidän kielellänsä: että jokainen mies on hallitsia huoneessansa, ja antoi puhuttaa kansansa kielellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Näiden jälkeen, sittekuin kuningas Ahasveruksen viha asettui, muisti hän, mitä Vasti oli tehnyt, ja mitä hänestä päätetty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Niin sanoivat kuninkaan palveliat, jotka häntä palvelivat: etsittäköön kuninkaalle kauniita nuoria neitseitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Ja lähettäköön kuningas katsojat kaikkiin valtakuntansa maakuntiin, kokoomaan kaikkia kauniita nuoria neitseitä Susanin linnaan, vaimoin huoneesen, Hegen, kuninkaan kamaripalvelian käden alle, joka vaimoista piti vaarin ja antoi heille heidän kaunistuksensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Ja piika, joka kuninkaalle kelpaa, tulkoon kuningattareksi Vastin siaan. Tämä kelpasi kuninkaalle, ja hän teki niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Ja Susanin linnassa oli Juudalainen, jonka nimi oli Mordekai Jairin poika, Simein pojan, Kisin pojan, Jeminin mies,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Joka oli viety Jerusalemista sen joukon kanssa, joka vietiin Jekonian Juudan kuninkaan kanssa, jonka Nebukadnetsar Babelin kuningas vei pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Ja hän oli Hadassan, se on, Esterin, setänsä tyttären holhoja; sillä ei hänellä ollut isää eikä äitiä; ja hän oli kaunis ja hyvänmuotoinen piika; ja kuin hänen isänsä ja äitinsä kuolivat, otti Mordekai hänen tyttäreksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Kuin kuninkaan käsky ja laki ilmoitettiin, ja monta piikaa koottiin Susanin linnaan, Hegen käden alle, otettiin myös Ester kuninkaan huoneeseen, Hegen käden alle, joka oli vaimoin vartia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Ja piika kelpasi hänelle, ja hän löysi laupiuden hänen edessänsä, ja hän joudutti hänen kaunistustensa kanssa, antaaksensa hänelle hänen osansa ja siihen seitsemän kaunista piikaa kuninkaan huoneesta; ja hän muutti hänen piikoinensa parhaasen paikkaan vaimoin huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ja ei Ester ilmoittanut hänelle kansaansa ja sukuansa; sillä Mordekai oli häntä kieltänyt ilmoittamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Ja Mordekai käyskenteli joka päivä neitsytten huoneen porstuan edessä, että hän olis saanut tietää, kävikö Esterille hyvin ja mitä hänelle tapahtuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Ja kuin itsekunkin piian määrätty aika tuli mennä kuningas Ahasveruksen tykö, sittekuin hän oli ollut kaksitoistakymmentä kuukautta vaimoin tavan jälkeen kaunistuksessa; (sillä heidän kaunistuksellansa piti oleman niin paljo aikaa: kuusi kuukautta myrhamiöljyllä, ja kuusi kuukautta kalliilla voiteilla, ja muilla vaimoin kaunistuksilla:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Niin piika meni kuninkaan tykö; ja jonka hän tahtoi, se piti hänelle annettaman, joka piti hänen kanssansa menemän vaimoin huoneesta kuninkaan huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Ehtoona hän tuli, ja huomeneltain palasi toiseen vaimoin huoneesen, Saasgaksen, kuninkaan kamaripalvelian käden alle, joka oli vaimoin vartia. Ja ei hänen pitänyt palajaman kuninkaan tykö, muutoin jos kuningas häntä tahtoi ja kutsutti häntä nimeltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Kuin Esterin, Abihailin, Mordekain sedän, tyttären (jonka hän oli ottanut tyttäreksensä) aika joutui tulla kuninkaan tykö, ei hän mitään muuta anonut, vaan mitä Hege kuninkaan kamaripalvelia, vaimoin vartia, sanoi; ja Ester löysi armon kaikkein edessä, jotka hänen näkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ja Ester otettiin kuningas Ahasveruksen tykö kuninkaalliseen huoneesen kymmenentenä kuukautena, joka kutsutaan Tebet, seitsemäntenä hänen valtakuntansa vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Ja kuningas rakasti Esteriä enempi kuin kaikkia muita vaimoja, ja hän löysi armon ja laupiuden hänen edessänsä enempi kuin kaikki muut neitseet; ja hän pani kuninkaallisen kruunun hänen päähänsä ja teki hänen kuningattareksi Vastin siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Ja kuningas teki kaikille päämiehillensä ja palvelioillensa suuret pidot, ja ne pidot olivat Esterin tähden; ja hän teki maakunnille levon, ja antoi lahjoja kuninkaan varan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Ja kuin neitseet toisen kerran koottiin, istui Mordekai kuninkaan portissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Ja ei Ester ollut vielä ilmoittanut sukuansa eikä kansaansa, niinkuin Mordekai hänelle oli käskenyt; sillä Ester teki Mordekain sanan jälkeen, niinkuin silloinkin, kuin hän hänen kasvatti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'Silloin kuin Mordekai istui kuninkaan portissa, vihastuivat kaksi kuninkaan kamaripalveliaa, Bigtan ja Teres, ovenvartiat, ja aikoivat heittää kätensä kuningas Ahasveruksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Ja Mordekai sai sen tietää ja ilmoitti kuningatar Esterille; ja Ester sanoi Mordekain puolesta sen kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Ja kuin sitä tutkisteltiin, löydettiin se todeksi, ja he hirtettiin molemmat puuhun. Ja se kirjoitettiin aikakirjaan kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Kuin nämät olivat tapahtuneet, teki kuningas Ahasverus Hamanin, Medatan pojan, Agagilaisen, suureksi, ja korotti hänen, ja pani hänen istuimensa ylemmäksi kaikkia päämiehiä, jotka hänen tykönänsä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Ja kaikki kuninkaan palveliat, jotka kuninkaan portissa olivat, notkistivat polviansa ja kumarsivat Hamania; sillä niin oli kuningas käskenyt; mutta Mordekai ei notkistanut polviansa eikä kumartanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Niin kuninkaan palveliat, jotka kuninkaan portissa olivat, sanoivat Mordekaille: miksi sinä rikot kuninkaan käskyn?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Ja koska he joka päivä sitä hänelle sanoivat, ja ei hän totellut heitä, ilmoittivat he sen Hamanille, nähdäksensä, olisiko senkaltainen Mordekain työ pysyväinen; sillä hän oli sanonut itsensä Juudalaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Ja kuin Haman näki, ettei Mordekai notkistanut polviansa hänen edessänsä eikä kumartanut häntä, tuli hän kiukkua täyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Ja hän luki vähäksi laskea ainoastansa Mordekain päälle kättänsä; sillä he olivat hänelle tiettäväksi tehneet Mordekain kansan; mutta Haman pyysi teloittaa kaikkea Mordekain kansaa, Juudalaisia, jotka olivat koko kuningas Ahasveruksen valtakunassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Ensimäisellä kuulla, se on Nisan kuu, kuningas Ahasveruksen toisena vuonna toistakymmentä, heitettiin Pur, se on arpa, Hamanin edessä, päivä päivältä, ja kuukaudelta niin toiseen kuuhun toistakymmentä, se on kuu Adar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Ja Haman sanoi kuningas Ahasverukselle: yksi kansa on hajoitettu ja jaettu kansain sekaan kaikissa sinun valtakuntas maakunnissa; ja heidän lakinsa on toisin kuin kaikkein kansain, ja ei he tee kuninkaan lain jälkeen; ei se ole kuninkaalle hyödyllinen, että heidän niin olla annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Jos kuninkaalle kelpaa, niin kirjoitettakoon, että ne hukutettaisiin; niin minä tahdon punnita kymmenentuhatta leiviskää hopiaa virkamiesten käsiin, vietää kuninkaan tavaroihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Silloin kuningas otti sormuksen sormestansa ja antoi sen Hamanille, Medatan Agagilaisen pojalle, Juudalaisten vihamiehelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Ja kuningas sanoi Hamanille: se hopia olkoon annettu sinulle, niin myös kansa, tehdäkses heille, mitäs tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Niin kuninkaan kirjoittajat kutsuttiin kolmantena päivänä toistakymmentä ensimäistä kuuta, ja kirjoitettiin niinkuin Haman käski kuninkaan ylimmäisten ja maaherrain tykö, sinne ja tänne maakuntiin, ja jokaisen kansan päämiesten tykö siellä ja täällä, itsekunkin kansan kirjoituksen jälkeen ja heidän kielellänsä; kuningas Ahasveruksen nimellä oli se kirjoitettu ja kuninkaan sormuksella lukittu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Ja kirjat lähetettiin juoksijain kautta kaikkiin kuninkaan maakuntiin, hukuttamaan, tappamaan ja teloittamaan kaikkia Juudalaisia, nuoria ja vanhoja, lapsia ja vaimoja yhtenä päivänä, kuin oli kolmastoistakymmenes päivä toista kuuta toistakymmentä, se on kuu Adar, ja ryöstämään heidän saaliinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Kirja oli näin: käsky on annettu kaikkiin maakuntiin, julistettaa kaikille kansoille, että heidän piti oleman sinä päivänä valmiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Ja juoksijat menivät kiiruusti kuninkaan käskyn jälkeen; ja käsky annettiin Susanin linnassa. Ja kuningas ja Haman istuivat ja joivat; mutta Susanin kaupunki oli hämmästyksissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Kuin Mordekai ymmärsi kaikki mitä tapahtunut oli, repäisi hän vaatteensa, ja puetti itsensä säkillä ja tuhalla, ja meni keskelle kaupunkia ja huusi suurella äänellä ja surkiasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Ja tuli kuninkaan portin eteen; sillä ei ollut luvallinen yhdenkään mennä kuninkaan portista sisälle, jonka yllä säkki oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Ja Juudalaisilla oli suuri parku kaikissa maakunnissa, joihon kuninkaan sana ja käsky tuli, ja moni paastosi, itki ja murehti, ja makasi säkissä ja tuhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Niin Esterin piiat ja hänen kamaripalveliansa tulivat ja ilmoittivat sen hänelle. Niin kuningatar peljästyi kovin, ja lähetti vaatteet Mordekain yllensä pukea, ja käski säkin panna yltänsä pois; mutta ei hän ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Niin Ester kutsui Hatakin kuninkaan kamaripalvelian, joka hänen edessänsä seisoi, ja käski hänen Mordekain tykö tiedustelemaan, mikä se on ja minkätähden hän niin teki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Niin Hatak meni Mordekain tykö kaupungin kadulle kuninkaan portin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'Ja Mordekai sanoi hänelle kaikki, mitä hänelle tapahtunut oli, ja sen hopian, jonka Haman oli luvannut punnita kuninkaan tavaroihin Juudalaisten tähden, että he surmattaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Ja hän antoi hänelle kirjoituksen siitä käskystä, joka Susanissa oli annettu, että he piti teloitettaman, osoittaaksensa sen Esterille ja antaaksensa hänelle tietää, että hän käskis hänen mennä kuninkaan tykö ja rukoilla häntä hartaasti kansansa edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Ja kuin Hatak tuli ja ilmoitti Esterille Mordekain sanat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Puhui Ester Hatakille ja käski hänen Mordekaille (sanoa):');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Kaikki kuninkaan palveliat ja kuninkaan maakuntain kansa tietävät, että kuka ikänä mies eli vaimo menee kuninkaan tykö sisimäiselle kartanolle, joka ei ole kutsuttu, hänen tuomionsa on, että hänen pitää kuoleman muutoin jos kuningas ojentaa kultaisen valtikan hänen puoleensa, että hän eläis; ja en minä ole kutsuttu kolmenakymmenenä päivänä kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Ja kuin Esterin sanat sanottiin Mordekaille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Käski hän sanoa Esterille jälleen: älä luulekaan, ettäs vapahdat henkes paremmin kuin kaikki muut Juudalaiset, vaikka kuninkaan huoneessa olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Sillä jos sinä tähän aikaan peräti vaikenet, niin Juudalaiset saavat kuitenkin avun ja pelastuksen muualta, ja sinä ja isäs huone pitää sitte hukkuman. Ja kuka tietää, ehkä olet sinä tämän ajan tähden tullut kuninkaan valtakuntaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Ester käski Mordekaita vastata:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Mene ja kokoo kaikki Juudalaiset, jotka Susanissa ovat, ja paastotkaat minun edestäni, ettette syö ettekä juo kolmena päivänä yöllä eli päivällä; minä paastoon myös piikoineni, ja niin minä menen kuninkaan tykö käskyäkin vastaan; jos minä hukun, niin minä hukun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Mordekai meni ja teki kaikki niinkuin Ester hänelle käski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Ja kolmantena päivänä puetti Ester itsensä kuninkaallisiin vaatteisiin ja meni kartanoon kuninkaan huoneen tykö, sisälliselle puolelle kuninkaan huoneen kohdalle. Ja kuningas istui kuninkaallisella istuimellansa kuninkaallisessa huoneessansa, juuri huoneen oven kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Ja kuin kuningas näki kuningatar Esterin seisovan kartanolla, löysi hän armon hänen edessänsä; ja kuningas ojensi kultaisen valtikan, joka oli hänen kädessänsä, Esterin puoleen; niin Ester astui edes ja rupesi valtikan päähän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Ja kuningas sanoi hänelle: kuningatar Ester! mikä sinun on? ja mitäs anot? Puoleen minun valtakuntaani asti pitää sinulle annettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Ester sanoi: jos kuninkaalle kelpaa, niin tulkoon kuningas ja Haman tänäpänä pitoihin, jotka minä olen valmistanut hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Ja kuningas sanoi: kiiruhtakaat, että Haman tekis, mitä Ester on sanonut. Niin kunigas ja Haman tulivat pitoihin, jotka Ester oli valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Ja kuningas sanoi Esterille, sittekuin hän oli viinaa juonut: mitä pyydät, se pitää sinulle annettaman, ja mitä anot, vaikka se olis puoli valtakunnasta, se pitää tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Niin Ester vastasi ja sanoi: minun rukoukseni ja anomiseni on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Jos minä olen löytänyt armon kuninkaan edessä, ja jos se kelpaa kuninkaalle antaa minulle minun rukoukseni ja tehdä minun anomiseni, niin tulkoon kuningas ja Haman pitoihin, jotka minä valmistan heille, niin minä teen huomenna niinkuin kuningas on sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Niin Haman meni ulos sinä päivänä iloissansa ja rohkialla sydämellä. Ja kuin hän näki Mordekain kuninkaan portissa, ettei hän noussut eikä siastansa liikahtanut hänen edessänsä, tuli hän täyteen vihaa Mordekain päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Mutta Haman pidätti itsensä; ja kuin hän tuli kotiansa, lähetti hän ja antoi kutsua ystävänsä ja emäntänsä Sereksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Ja Haman luetteli heille rikkautensa kunnian, ja lastensa paljouden, ja kaikki, kuinka kuningas oli hänen tehnyt niin suureksi, ja että hän oli korotettu kuninkaan päämiesten ja palveliain ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Sanoi myös Haman: ja kuningatar Ester ei antanut yhtäkään kutsua kuninkaan kanssa pitoihin, jotka hän valmisti, paitsi minua; ja minä olen myös huomeneksi kutsuttu hänen tykönsä kuninkaan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Mutta kaikista näistä ei minulle mitäkään kelpaa niinkauvan kuin minä näen Juudalaisen Mordekain istuvan kuninkaan portissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Niin sanoi hänen emäntänsä Seres ja kaikki hänen ystävänsä hänelle: valmistettakoon puu, viisikymmentä kyynärää korkia, ja sano huomenna kuninkaalle, että Mordekai siihen hirtettäisiin, niin sinä menet iloissas kuninkaan kanssa pitoihin. Se kelpasi Hamanille, ja puu valmistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Ja sinä yönä ei saanut kuningas unta, ja hän käski tuotaa aika- ja muistokirjat, ja ne luettiin kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Niin löydettiin kirjoitettuna, kuinka Mordekai oli tietää antanut, että kaksi kuninkaan kamaripalveliaa, Bigtana ja Teres, ovenvartiat, olivat aikoneet heittää kätensä kuningas Ahasveruksen päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Ja kuningas sanoi: mitä kunniaa eli hyvää me olemme Mordekaille sen edestä tehneet? Niin sanoivat kuninkaan palveliat, jotka häntä palvelivat: ei ole hänelle mitään tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Ja kuningas sanoi: kuka kartanolla on? ja Haman käveli ulkona kartanolla kuninkaan huoneen edessä, sanoaksensa kuninkaalle, että Mordekai piti hirtettämän siihen puuhun, jonka hän oli häntä varten valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Ja kuninkaan palveliat sanoivat hänelle: katso, Haman seisoo pihalla. Kuningas sanoi: tulkaan sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Ja kuin Haman tuli, sanoi kuningas hänelle: mitä sille miehelle pitää tehtämän, jota kuningas tahtoo kunnioittaa? Ja Haman ajatteli sydämessänsä: ketäpä kuningas paremmin tahtoo kunnioittaa kuin minua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Ja Haman sanoi kuninkaalle: se mies, jota kuningas tahtoo kunnioittaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Pitää puetettaman kuninkaallisilla vaatteilla, joita kuningas itse pitää, ja tuotaman se hevonen, jolla kuningas ajaa, ja että kuninkaallinen kruunu pantaisiin hänen päähänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Ja vaatteet ja hevonen pitää annettaman yhden kuninkaan päämiehen käteen, joka on ylimmäisistä päämiehistä, että hän puettais sen miehen, jota kuningas tahtoo kunnioittaa, ja antais hänen ajaa hevosen selässä kaupungin kaduilla, ja huutaa hänen edellänsä: näin pitää sille miehelle tehtämän, jota kuningas tahtoo kunnioittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Kuningas sanoi Hamanille: kiiruhda, ota vaatteet ja hevonen, niinkuin sinä olet sanonut, ja tee niin Mordekain Juudalaisen kanssa, joka istuu kuninkaan portissa; ja älä anna mitään puuttua kaikista näistä, mitä sinä puhunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Niin Haman otti vaatteet ja hevosen ja puetti Mordekain, ja antoi hänen ajaa kaupungin kaduilla, ja huusi hänen edellänsä: näin sille miehelle tehdään, jota kuningas tahtoo kunnioittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Ja Mordekai palasi kuninkaan porttiin; mutta Haman meni kiiruusti kotiansa, murehtien ja peitetyllä päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Ja Haman jutteli emännällensä Serekselle ja kaikille ystävillensä kaikki, mitä hänelle tapahtunut oli. Niin sanoivat hänen viisaansa ja hänen emäntänsä Seres hänelle: Jos Mordekai on Juudalaisten siemenestä, jonka edessä sinä olet ruvennut lankeemaan, niin et sinä voi mitään häntä vastaan, vaan sinun täytyy peräti hänen edessänsä langeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Kuin he vielä parhaallaansa hänen kanssansa puhuivat, tulivat kuninkaan kamaripalveliat ja kiiruhtivat Hamania pitoihin, jotka Ester oli valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Kuin kuningas tuli ja Haman pitoon kuningatar Esterin tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'Sanoi kuningas taas toisena päivänä Esterille, sittekuin hän oli viinaa juonut: mitäs rukoilet, kuningatar Ester, sinulles annettaa, ja mitäs anot? ehkä se olis puoli kuninkaan valtakuntaa, se pitää tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Kuningatar Ester vastasi ja sanoi: o kuningas, jos minä olen löytänyt armon sinun edessäs ja jos kuninkaalle kelpaa, niin suokoon minulle henkeni minun rukoukseni tähden, ja kansani minun anomiseni tähden!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Sillä me olemme myydyt, minä ja minun kansani, teloitettaviksi, surmattaviksi ja hukutettaviksi. Ja jos me olisimme myydyt orjiksi ja piioiksi, niin minä olisin vaiti, eikä vihamies sittekään palkitsisi kuninkaalle sitä vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Kuningas Ahasverus puhui ja sanoi kuningatar Esterille: kuka se on, eli kussa se on, joka tohtii senkaltaista ajatella tehdäksensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Ester sanoi: se vihamies ja vainooja on tämä paha Haman; ja Haman peljästyi kuninkaan ja kuningattaren edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Ja kuningas nousi vieraspidosta ja viinan tyköä vihoissansa ja meni salin yrttitarhaan; ja Haman nousi ja rukoili kuningatarta henkensä edestä; sillä hän näki hänellensä olevan valmistetun onnettomuuden kuninkaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Ja kuin kuningas tuli jälleen salin yrttitarhasta siihen huoneesen, jossa he olivat viinaa juoneet, nojasi Haman sille vuoteelle, jolla Ester istui. Niin sanoi kuningas: tahtooko hän kuningattarelle tehdä myös väkivaltaa minun läsnäollessani huoneessa? Kuin se sana tuli kuninkaan suusta ulos, peittivät he Hamanin kasvot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Ja Harbona, kuninkaan kamaripalvelijoista, sanoi kuninkaalle: katso, Hamanin kartanolla seisoo puu viisikymmentä kyynärää korkea, jonka hän teki Mordekaita varten, joka hyvää puhui kuninkaan edestä. Niin sanoi kuningas: hirtettäkään hän siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Niin he hirttivät Hamanin siihen puuhun, jonka hän teki Mordekaita varten; ja niin asettui kuninkaan viha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Sinä päivänä antoi kuningas Ahasverus kuningatar Esterille Hamanin Juudalaisten vihollisen huoneen. Ja Mordekai tuli kuninkaan eteen; sillä Ester ilmoitti, mikä hän hänelle oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Ja kuningas otti sormuksensa, jonka hän oli antanut Hamanilta pois ottaa, ja antoi Mordekaille. Ja Ester pani Mordekain Hamanin kartanon päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Ja Ester puhui vielä kuninkaalle, ja lankesi hänen jalkainsa juureen, itki ja rukoili häntä palauttamaan Hamanin Agagilaisen pahuutta ja hänen aikomustansa, jonka hän oli ajatellut Juudalaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Niin kuningas ojensi kultaisen valtikan Esterin puoleen. Ja Ester nousi ja seisoi kuninkaan edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Ja sanoi: jos kuninkaalle kelpaa, ja jos minä olen armon löytänyt hänen edessänsä, ja jos se on kuninkaalle sovelias, ja minä kelpaan hänelle; niin kirjoitettakoon ja otettakoon takaperin kaikki Hamanin Medatan Agagilaisen pojan aikomuskirjat, jotka hän on kirjoittanut, että kaikki Juudalaiset surmattaisiin kaikissa kuninkaan maakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Sillä kuinka minä voin nähdä sitä pahuutta, joka minun kansalleni tulis? ja kuinka minä voin nähdä, että minun sukukuntani niin teloitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Niin kuningas Ahasverus sanoi kuningatar Esterille ja Mordekaille Juudalaiselle: katso minä olen antanut Esterille Hamanin huoneen, ja hän hirtettiin puuhun, että hän laski kätensä Juudalaisten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Niin kirjoittakaat siis te Juudalaisten puolesta kuninkaan nimeen, niinkuin te itse tahdotte, ja painakaat sinetti kuninkaan sormuksella; sillä sitä kirjoitusta, joka kuninkaan nimellä kirjoitetaan, ja kuninkaan sormuksella sinetti painetaan, ei taideta otettaa takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Silloin kutsuttiin kuninkaan kirjoittajat kolmantena kuukautena, se on Sivan kuu, kolmantena päivänä kolmattakymmentä, ja kirjoitettiin juuri niinkuin Mordekai käski Juudalaisten tykö, ja hallitsiain tykö, maanvanhimpien ja maakuntain päämiesten tykö, Indiasta Etiopiaan asti, joita oli sata ja seitsemänkolmattakymmentä maakuntaa, kunkin maakunnan kirjoituksen jälkeen, jokaisen kansan tykö heidän kielellänsä, ja Juudalaisten tykö heidän kirjoituksensa jälkeen ja heidän kielellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Ja kirjoitettiin kuningas Ahasveruksen nimellä, ja sinetti painettiin kuninkaan sormuksella; ja hän lähetti kirjat hevosilla, nopeimmilla orheilla ja nuorilla muuleilla ajavaisten kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Että kuningas salli Juudalaiset kussakin kaupungissa koota heitänsä, ja varjella henkensä, ja teloittaa, tappaa ja hukuttaa kaikkein kansain ja maakuntain sotaväen, jotka heitä vaivasivat, lapsinensa, ja vaimoinensa, ja ryöstää heidän saaliinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'Yhtenä päivänä kaikissa kuningas Ahasveruksen maakunnissa, kolmantenatoistakymmenentenä päivänä toista kuuta toistakymmentä, se on kuu Adar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Ja kirjoissa oli, että käsky oli annettu kaikkiin maakuntiin julistettaa kaikille kansoille, että Juudalaiset olisivat sinä päivänä valmiit kostamaan vihollisillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Ja liukkailla orheilla ja karkaavaisilla muuleilla ajavaiset sanansaattajat ajoivat nopiasti ja kiiruusti kuninkaan sanan jälkeen; ja se käsky lyötiin Susanin linnassa ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Ja Mordekai läksi kuninkaan tyköä kuninkaallisissa vaatteissa, sinisissä ja valkeissa, ja suurella kultakruunulla, ja kalliilla liinaisella hameella ja purpuralla. Ja Susanin kaupunki iloitsi ja riemuitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Sillä sinne oli tullut valkeus ja ilo, riemu ja kunnia Juudalaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Ja kaikissa maakunnissa ja kaupungeissa, joihin kuninkaan sana ja käsky tuli, oli ilo ja riemu Juudalaisten keskellä, pito ja hyvät päivät. Ja monta maan kansasta tuli Juudalaiseksi; sillä Juudalaisten pelko tuli heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Ja toisena kuukautena toistakymmentä, Adarin kuulla, kolmantena päivänä toistakymmentä, jona kuninkaan sana ja käsky oli tullut, että toimitus piti tapahtuman, juuri sinä päivänä jona Juudalaisten viholliset toivoivat vallitsevansa heitä, kääntyi niin, että Juudalaiset vallitsivat vihollisiansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Niin Juudalaiset kokoontuivat kaupunkeihinsa kaikissa kuningas Ahasveruksen maakunnissa, laskemaan kätensä niiden päälle, jotka heille pahuutta tahtoivat, ja ei yksikään voinut seisoa heitä vastaan; sillä kaikki kansa pelkäsi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Ja kaikki maakuntain päämiehet ja hallitsiat, ja maan vanhimmat ja kuninkaan virkamiehet ylistivät Juudalaisia; sillä Mordekain pelko tuli heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Sillä Mordekai oli suuri kuninkaan huoneessa, ja hänen sanomansa kuului kaikkiin maakuntiin, kuinka Mordekai menestyi ja tuli suureksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Niin Juudalaiset löivät kaikki vihamiehensä miekalla, tappoivat ja hukuttivat heidät, ja tekivät niiden kanssa, jotka heitä vihasivat, oman tahtonsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Ja susanin linnassa löivät Juudalaiset viisisataa miestä kuoliaaksi, ja hukuttivat heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Vielä päälliseksi tappoivat he Parsandatan, Dalphonin, Aspatan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Poratan, Adalian, Aridatan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastan, Arisain, Aridain, Vajesatan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Kymmenen Hamanin poikaa, joka oli Medatanin poika, Juudalaisten vihamies; mutta ei he ruvenneet heidän saaliisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Silloin tuli tapettuin luku Susanin linnaan, kuninkaan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Ja kuningas sanoi kuningatar Esterille: Susanin kaupungissa ovat Juudalaiset tappaneet ja hukuttaneet viisisataa miestä ja kymmenen Hamanin poikaa: mitäs luulet heidän muissa kuninkaan maakunnissa tehneen? mitäs pyydät sinulles annettaa? ja mitäs vielä anot sinulles tehtää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Ester sanoi: jos kuninkaalle kelpaa, niin antakoon Juudalaisten myös huomenna tehdä Susanissa tämän päiväisen käskyn jälkeen; että he hirttäisivät kymmenen Hamanin poikaa puuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Ja kuningas käski niin tehdä: ja se käsky lyötiin Susanissa ylös; ja kymmenen Hamanin poikaa hirtettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Ja Juudalaiset, jotka Susanissa olivat, kokoontuivat neljäntenä päivänä toistakymmentä Adar kuuta, ja tappoivat kolmesataa miestä Susanissa; mutta heidän saaliisensa ei he ruvenneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Mutta muut Juudalaiset kuninkaan maakunnissa tulivat kokoon ja varjelivat henkeänsä, saadaksensa lepoa vihollisiltansa, ja tappoivat vihollisiansa viisikahdeksattakymmentä tuhatta, mutta ei he ruvenneet saaliisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, '(Se tapahtui) kolmantenatoistakymmenentenä päivänä Adar kuuta. Ja he lepäsivät neljäntenätoistakymmenentenä päivänä sitä kuuta; sen he tekivät pito- ja ilopäiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Mutta Juudalaiset, jotka Susanissa olivat, tulivat kokoon kolmantenatoistakymmenentenä ja neljäntenätoistakymmenentenä päivänä, ja lepäsivät viidentenätoistakymmenentenä päivänä; ja tekivät sen päivän pito- ja ilopäiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Sentähden Juudalaiset, jotka asuivat maakylissä ja vähissä kaupungeissa, tekivät neljännentoistakymmenennen päivän Adar kuuta ilo- ja pitopäiväksi, ja lähettivät lahjoja toinen toisellensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Ja Mordekai kirjoitti nämät teot, ja lähetti kirjat kaikille Juudalaisille, jotka olivat kaikissa kuningas Ahasveruksen maakunnissa, sekä lähes että kauvas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Ja asetti heille, että he pitäisivät joka vuosi neljännentoistakymmenennen ja viidennentoistakymmenennen päivän Adar kuuta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Niiden päiväin jälkeen, joina Juudalaiset olivat tulleet lepoon vihollistensa edestä, ja sen kuukauden, jona heidän surunsa on iloksi kääntynyt ja heidän murheensa hyviksi päiviksi: että he ne pitäisivät pito- ja ilopäivinä, ja lähettäisivät lahjoja toinen toisellensa, ja jakaisivat vaivaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Ja Juudalaiset ottivat vastaan tehdäksensä sen, minkä he ennen olivat ruvenneet, ja Mordekai heidän tykönsä kirjoitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Sillä Haman Medatan Agagilaisen poika, kaikkein Juudalaisten vihollinen, oli ajatellut hukuttaa kaikkia Juudalaisia, ja antoi heittää Pur, se on arpaa, murentaaksensa ja hukuttaaksensa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Ja kuin Ester oli mennyt kuninkaan tykö; ja hän puhunut, että hänen paha aikomisensa, jonka hän oli ajatellut Juudalaisia vastaan, käännettiin kirjoitusten kautta hänen oman päänsä päälle, ja kuinka hän ja hänen poikansa ripustettiin puuhun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Siitä he nämät päivät kutsuivat Purim, arvan nimen jälkeen, sekä sen että kaiken tämän kirjan sanan jälkeen, ja mitä he olivat itse nähneet, ja kuinka heille on tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Ja Juudalaiset sääsivät sen, ja ottivat päällensä ja siemenensä päälle, ja kaikkein niiden päälle, jonka itsensä antoivat heidän tykönsä, ettei ne hylkää niitä kahta päivää, vaan pitävät ne joka vuosi, heidän kirjoituksensa ja aikansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'Ettei näitä päiviä pitänyt unhotettaman, mutta pidettämän heidän lastensa lapsilta ja kaikilta heidän sukukunniltansa, kaikissa maakunnissa ja kaupungeissa. Nämät ovat Purimin päivät, joita ei pidä hyljättämän Juudalaisten seassa, ja heidän muistonsa ei pidä unhotettaman heidän siemenessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Ja Ester Abihailin tytär ja Mordekai Juudalainen kirjoittivat kaikella voimalla toisen kerran, vahvistaaksensa Purimin kirjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Ja lähetti kirjat kaikille Juudalaisille sataan ja seitsemäänkolmattakymmeneen Ahasveruksen valtakunnan maakuntaan, rauhan ja totuuden sanoilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Vahvistaaksensa näitä Purimin päiviä heidän määrätyillä ajoillansa, niinkuin Mordekai Juudalainen ja kuningatar Ester olivat heille säätäneet, niinkuin he olivat itse päällensä ottaneet ja siemenensä päälle, sen määrätyn paaston ja heidän huutonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Ja Ester käski ja vahvisti nämät Purimin menot, ja että ne piti kirjaan kirjoittettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Ja kuningas Ahasverus laski veron maan päälle ja luotoin päälle merellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Mutta kaikki hänen työnsä, voimansa ja väkevyytensä, ja Mordekain suuri kunnia, kuin kuningas hänen suureksi teki: eikö ne ole kirjoitetut Median ja Persian kuningasten aikakirjassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Sillä Mordekai, Juudalainen, oli toinen kuningas Ahasveruksesta, ja väkevä Juudalaisten seassa, ja otollinen veljeinsä paljouden keskellä, joka etsi kansansa parasta ja puhui parhain päin kaiken siemenensä puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Yksi mies oli Utsin maalla nimeltä Job; ja se mies oli vakaa ja hurskas, ja Jumalaa pelkääväinen, ja vältti pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Ja hänelle oli syntynyt seitsemän poikaa ja kolme tytärtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Ja hänen karjansa oli seitsemäntuhatta lammasta, kolmetuhatta kamelia, viisisataa paria härkiä ja viisisataa aasia, ja myös sangen paljo perhettä. Ja se mies oli voimallisempi kuin kaikki, jotka itäisellä maalla asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Ja hänen poikansa menivät ja tekivät pidon huoneessansa itsekukin päivänänsä, ja lähettivät ja antoivat kutsua kolme sisartansa syömään ja juomaan kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Ja kuin pitopäivät olivat kuluneet, lähetti Job ja pyhitti heitä, ja nousi aamulla varhain ja uhrasi polttouhria kaikkein heidän lukunsa jälkeen. Sillä Job ajatteli: minun poikani ovat taitaneet syntiä tehdä ja unohtaneet Jumalan sydämessänsä. Näin teki Job joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Mutta tapahtui yhtenä päivänä, että Jumalan lapset tulivat ja astuivat Herran eteen, ja tuli myös saatana heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Mutta Herra sanoi saatanalle: kusta sinä tulet? Saatana vastasi Herraa ja sanoi: minä olen käynyt ja vaeltanut ympäri maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Niin sanoi Herra saatanalle: etkö ole ottanut vaaria palveliastani Jobista? sillä ei hänen vertaistansa ole maalla: hän on vakaa ja hurskas, Jumalaa pelkääväinen mies, ja välttää pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Saatana vastasi Herraa ja sanoi: turhaanko Job pelkää Jumalaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Etkös ole piirittänyt häntä, hänen huonettansa ja kaikkia mitä hänellä on ympäri? sinä olet siunannut hänen käsialansa, ja hänen tavaransa on levitetty maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Mutta ojenna kätes ja tartu kaikkeen hänen saatuunsa, mitämaks hän luopuu sinusta kasvois edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Herra sanoi saatanalle: katso, kaikki hänen tavaransa olkoon sinun kädessäs, ainoastaan älä häneen kättäs satuta. Silloin läksi saatana Herran tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Mutta sinä päivänä, kuin hänen poikansa ja tyttärensä söivät ja joivat viinaa vanhimman veljensä huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Tuli sanansaattaja Jobin tykö ja sanoi: härjillä kynnettiin, ja aasit kävivät läsnä laitumella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'Niin he tulivat rikkaasta Arabiasta ja ottivat ne, ja löivät palveliat miekan terällä; ja minä ainoastaan yksin pääsin sanomaan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Kuin hän vielä puhui, tuli toinen ja sanoi: Jumalan tuli putosi taivaasta ja sytytti lampaat ja palveliat, ja poltti ne; ja minä ainoastaan yksin pääsin sanomaan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Kuin hän vielä puhui, tuli yksi ja sanoi: Kaldealaiset tekivät kolme joukkoa ja hyökkäsivät kamelein päälle, ja ottivat ne pois, ja löivät miekan terällä; ja minä ainoastaan yksin pääsin sanomaan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Kuin hän vielä puhui, tuli yksi ja sanoi: sinun poikas ja tyttäres söivät ja joivat viinaa vanhimman veljensä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'Ja katso, suuri tuulispää tuli korvesta ja sysäsi neljään huoneen nurkkaan, ja se kaatui nuorukaisten päälle, niin että he kuolivat; ja minä ainoastaan yksin pääsin sanomaan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Silloin Job nousi ja repäisi vaatteensa, ja repi päätänsä, ja heittäysi maahan ja rukoili.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Ja sanoi: alasti olen minä tullut äitini kohdusta ja alasti pitää minun sinne jälleen menemän; Herra antoi ja Herra otti: Herran nimi olkoon kiitetty!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Näissä kaikissa ei rikkonut Job, eikä tehnyt tyhmästi Jumalaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Ja tapahtui yhtenä päivänä, kuin Jumalan lapset tulivat ja astuivat Herran eteen, että saatana myös tuli heidän kanssansa ja astui Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Silloin sanoi Herra saatanalle: kusta tulet? Saatana vastasi Herraa ja sanoi: minä olen käynyt ja vaeltanut ympäri maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Ja Herra sanoi saatanalle: etkös ole ottanut vaaria palveliastani Jobista? sillä ei hänen vertaistansa ole maalla: hän on vakaa ja hurskas ja Jumalaa pelkääväinen mies, ja välttää pahaa ja pysyy vielä vakuudessansa, ja sinä yllytit minua häntä hävittämään ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Saatana vastasi Herraa ja sanoi: nahka nahasta, ja kaikki, mitä ihmisessä on, antaa hän henkensä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Mutta ojenna kätes ja rupee hänen luihinsa ja lihaansa; mitämaks hän luopuu sinusta kasvois edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Herra sanoi saatanalle: katso, hän olkoon sinun kädessäs; kuitenkin säästä hänen henkeänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Silloin läksi saatana Herran tyköä ja löi Jobin pahoilla paisumilla, hänen kantapäästä kiireesen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Ja hän otti saviastian ja kaapi itseänsä sillä, ja istui tuhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Ja hänen emäntänsä sanoi hänelle: Vieläkös pysyt vakuudessas? siunaa Jumalaa ja kuole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Mutta hän sanoi hänelle: sinä puhut niinkuin tyhmät vaimot puhuvat. Jos me olemme hyvää saaneet Jumalalta, eikö myös meidän pidä ottaman pahaa vastaan? Kaikissa näissä ei Job syntiä tehnyt huulillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Kuin Jobin kolme ystävää kuulivat kaiken sen onnettomuuden, joka hänelle tullut oli, tulivat he itsekukin paikkakunnastansa: Eliphas Temanista, Bildad Suasta ja Zophar Naemasta, ja kokoontuivat ynnä tulemaan, armahtelemaan ja lohduttamaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Ja kuin he nostivat taampaa silmänsä, ei he häntä tunteneet, ja korottivat äänensä ja itkivät; ja jokainen repäisi vaatteensa, ja heittivät tomua päänsä päälle taivasta kohden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Ja istuivat hänen kanssansa maan päällä seitsemän päivää ja seitsemän yötä, ja ei sanaakaan hänen kanssansa puhuneet; sillä he näkivät hänen kipunsa sangen suureksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Sitte avasi Job suunsa ja kirosi päivänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Ja Job vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Se päivä olkoon kadotettu, jona minä syntynyt olen, ja se yö, jona sanottiin: mies on siinnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Se päivä olkoon pimiä, ja älköön Jumala kysykö ylhäältä sen perään: älköön kirkkaus paistako hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Pimeys ja kuolon varjo peittäköön hänen, olkoon pilvi hänen päällänsä; ja musta päivän sumu tehkään hänen kauhiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Sen yön käsittäköön pimeys, ja älkään iloitko vuosikausien päiväin seassa, ja älkään tulko kuukausien lukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Katso, olkoon se yö yksinäinen ja älköön yhtäkään iloa tulko siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Ne jotka päivää kiroovat, he kirotkoot sitä, ne jotka ovat valmiit herättämään Leviatania.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Sen tähdet olkoot pimiät hämärässänsä, odottakoot valkeutta, ja ei tulko, ja älkööt nähkö aamuruskon silmäripsiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Ettei se sulkenut minun kohtuni ovea, ja ei kätkenyt onnettomuutta silmäini edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Miksi en minä kuollut äitini kohdussa? Miksi en minä läkähtynyt äitini kohdusta tultuani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Miksi he ovat ottaneet minun helmaansa? Miksi minä olen nisiä imenyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Niin minä nyt makaisin, olisin alallani, lepäisin, ja minulla olis lepo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Maan kuningasten ja neuvojain kanssa, jotka heillensä rakentavat sitä mikä kylmillä on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Eli päämiesten kanssa, joilla kultaa on, ja joiden huoneet ovat täynnä hopiaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Eli niinkuin keskensyntyneet kätketyt; ja en oliskaan: niinkuin nuoret lapset, jotka ei koskaan valkeutta nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Siellä täytyy jumalattomain lakata väkivallastansa; siellä ovat ne levossa, jotka paljon vaivaa nähneet ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Siellä on vangeilla rauha muiden kanssa, ja ei kuule vaatian ääntä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Siellä ovat sekä pienet että suuret, ja palveliat vapaat isännistänsä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Miksi valkeus on annettu vaivaisille, ja elämä murheellisille sydämille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Niille, jotka odottavat kuolemaa, ja ei se tule, ja kaivaisivat sitä ennen kuin aarnihautaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Niille, jotka kovin iloitsevat ja riemuitsevat, että he saisivat haudan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Ja sille miehelle, jonka tie kätketty on, ja hänen edestänsä Jumalalta peitetty?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Sillä minun leipäni tykönä minä huokaan, ja minun parkuni vuodatetaan niinkuin vesi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Sillä jota minä pelkäsin, se tuli minun päälleni, ja mitä minä kartin, tapahtui minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Enkö minä ollut onnellinen? enkö minä ollut rauhassa? eikö minulla ollut hyvä lepo? ja nyt senkaltainen levottomuus tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Ja Eliphas Temanilainen vastasi ja sanoi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Jos joku sinun kanssas rupeis puhumaan: mitämaks et sinä sitä kärsi; mutta kuka taitaa vaiti olla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Katso, sinä olet monta neuvonut, ja vahvistanut väsyneitä käsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Sinun puhees on ojentanut langenneita, ja vapisevaisia polvia vahvistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Mutta että se nyt tulee sinun päälles, niin sinä väsyit, ja että se lankesi sinun päälles, niin sinä peljästyit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Tämäkö on sinun (Jumalan) pelkos, sinun uskallukses, sinun toivos ja sinun vakuutes?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Muistele nyt, kussa joku viatoin on hukkunut? eli kussa hurskaat ovat joskus hävinneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Niinkuin minä kyllä nähnyt olen, ne jotka kyntävät vääryyden, ja onnettomuuden kylvävät, sitä he myös niittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'He ovat Jumalan puhalluksen kautta kadonneet, ja hänen vihansa hengeltä hukatut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Jalopeuran kiljumus, ja julma jalopeuran ääni, ja nuorten jalopeurain hampaat ovat lovistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Vanha jalopeura hukkuu, ettei hänellä ole saalista; ja jalopeuran pojat hajoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Ja minun tyköni on tullut salainen sana; ja minun korvani on saanut vähäisen siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'Kuin minä ajattelin yönäkyjä, kuin uni lankee ihmisten päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Niin pelko ja vavistus tuli minun päälleni, ja kaikki minun luuni peljätettiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Ja henki meni minun sivuitseni; kaikki minun karvani nousivat ruumiissani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Silloin seisoi kuva minun silmäini edessä, jonka kasvoja en minä tuntenut; ja minä kuulin hiljaisen hyminän äänen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Kuinka on ihminen hurskaampi kuin JumaIa? eli joku mies puhtaampi kuin se, joka hänen tehnyt on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Katso, palveliainsa seassa ei löydä hän uskollisuutta ja enkeleissänsä löytää hän tyhmyyden:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Kuinka enemmin niissä jotka asuvat savihuoneissa, niissä jotka ovat perustetut maan päälle, jotka toukkain tavalla murentuvat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Se pysyy aamusta ehtoosen asti, niin he muserretaan; ja ennenkuin he sen havaitsevat, he ijankaikkisesti hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Eikö heidän jälkeenjääneensä pois oteta? he kuolevat, vaan ei viisaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Nimitä siis, jos joku on, joka kanssas todistaa, ja kenen tykö pyhistä sinä itses käännät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Mutta tyhmän tappaa viha, ja taitamattoman kuolettaa kiivaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Minä näin tyhmän juurtuneen, ja kirosin kohta hänen huonettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Hänen lapsensa pitää oleman kaukana terveydestä; ja pitää rikki murrettaman portissa, kussa ei yhtään auttajaa ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Hänen elonsa pitää isoovaisen syömän, ja orjantappuroista sen ottaman; ja hänen kalunsa pitää ryövärien nielemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Sillä ei vaiva käy ylös tomusta; ja onnettomuus ei kasva maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Vaan ihminen syntyy onnettomuuteen; niinkuin kuumain hiilten kipinät sinkoilevat ylöskäsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Kuitenkin tahdon minä Jumalasta tutkistella: Jumalasta minä tahdon puhua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Joka voimallisia töitä tekee, joita ei tutkia taideta, ja ihmeitä, joita ei lukea taideta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Joka antaa sateen maan päälle, ja antaa tulla veden teiden päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Joka ylentää nöyrät korkeuteen, ja korottaa sorrettuja autuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Hän tekee kavalain aivoitukset tyhjäksi, ettei heidän kätensä mitään toimittaa taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Hän käsittää taitavat kavaluudessansa, ja pahain neuvo kukistetaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Että he päivällä juoksevat pimeydessä, ja koperoitsevat puolipäivänä niinkuin yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Ja hän auttaa köyhää miekasta, ja heidän suustansa, ja voimallisten kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Ja hän on köyhän turva, että vääryys pitäis suunsa kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Katso, autuas on se ihminen, jota Jumala kurittaa; sentähden älä hylkää Kaikkivaltiaan kuritusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Sillä hän haavoittaa ja sitoo; hän lyö ja hänen kätensä terveeksi tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Kuudesta murheesta päästää hän sinun; ja seitsemännestä ei tule mitään pahaa sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Kalliilla ajalla vapahtaa hän sinun kuolemasta, ja sodassa miekasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Hän peittää sinun kielen ruoskalta; ja ei sinun pidä pelkäämän hävitystä, koska se tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Hävityksessä ja nälässä sinä naurat; ja et pelkää metsän petoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Sillä sinun liittos pitää oleman kivien kanssa kedolla, ja maan pedot pitää sinun kanssas rauhallisesti oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Sinä ymmärrät, että sinun majas on rauhassa, ja sinä oleskelet asuinsiassas ilman syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Ja sinä saat ymmärtää, että siemenes on suureksi tuleva, ja vesas niinkuin ruoho maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Ja sinä tulet vanhalla ijällä hautaan, niinkuin elositoma ajallansa korjataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Katso, sitä me olemme tutkineet, ja se on niin: kuule sitä, ja tunne sinä myös se hyväkses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Niin Job vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'Jos minun surkeuteni punnittaisiin, ja minun kärsimiseni yhtä haavaa laskettaisiin vaa ́an päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Niin se olis raskaampi kuin santa meressä; sentähden ovat minun sanani nielletyt ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Sillä Kaikkivaltiaan nuolet ovat minussa, joiden myrkky särpää minun henkeni; ja Jumalan kauhistus tarkoittaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Huutaako metsä-aasi, kuin hänellä ruohoja on? ammuuko härkä, kuin hänellä on ruokaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Syödäänkö mautointa ilman suolaa? eli maistaako valkuainen munan ruskuaisen ympäriltä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Jota minun sieluni ennen kuoitti, se on nyt minun ruokani minun kipuni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Jospa minun rukoukseni tapahtuis, ja Jumala antais minulle, mitä minä toivon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Että Jumala tahtois ja löis minun rikki, ja päästäis kätensä särkemään minua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Niin olis minulla vielä sitte lohdutus, ja minä vahvistuisin sairaudessani, ellei hän säästäisi minua: en ole mitään kuitenkaan kieltänyt pyhän puhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Mikä on minun väkeni, että minä voisin toivoa? ja mikä on minun loppuni, että minun sieluni vois kärsiväinen olla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Onko minun väkeni kivinen? eli minun lihani vaskinen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Ei ole minulla missään apua; ja minun saatuni on pois ajettu minulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Joka ei osoita lähimmäisellensä laupiutta, hän hylkää Kaikkivaltiaan pelvon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Minun veljeni ovat rikkoneet minua vastaan, niinkuin oja ja niinkuin väkevä virta ohitse menneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Jotka ovat kauhiat jäästä, ja jotka lumi peittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Kuin helle heitä ahdistaa, pitää heidän nääntymän, ja kuin palava on, pitää heidän katooman paikastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Heidän polkunsa poikkeevat pois; he raukeevat tyhjään ja hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'He katsoivat Temanin tietä, rikkaan Arabian polkuja he toivoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Mutta heidän pitää häpiään tuleman, ratki surutoinna ollessansa; ja heidän pitää häpeemän siihen tultuansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Sillä ette nyt mitään ole; ja että te näette surkeuden, pelkäätte te.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Olenko minä sanonut: Tuokaat minulle! eli antakaat minun edestäni lahjoja teidän tavarastanne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Ja pelastakaat minua vihollisten kädestä, ja vapahtakaat minua tyrannein käsistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Opettakaat minua, minä olen ääneti, ja jota en minä tiedä, niin neuvokaat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Kuinka vahvat ovat oikeuden puheet? kuka teissä on se, joka sitä laittaa taitaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Te ajattelette sanoja, ainoastaan nuhdellaksenne, ja teette sanoillanne epäileväisen mielen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Te karkaatte köyhän orvon päälle, ja kaivatte lähimmäisellenne kuoppaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Mutta että te nyt tahdotte, niin katsokaat minun päälleni, jos minä teidän edessänne valhettelen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Palatkaat nyt, olkoon pois vääryys: Tulkaat jälleen; minun vastaukseni pitää oikia oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Onko minun kielessäni vääryyttä? eikö minun suulakeni ymmärrä vaivoja?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Eikö ihminen aina pidä oleman sodassa maan päällä; ja hänen päivänsä ovat niinkuin orjan päivät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Niinkuin palvelia halajaa varjoa, ja orja työnsä loppua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Niin olen minä minulleni saanut turhat kuukaudet, ja minulla on monta murheellista yötä ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Kuin minä levätä panin, sanoin minä: Koskahan minä nousen? ja sitte lueskelen, koska ehtoo tullee: minä olen ravittu kävellyksistä hamaan pimeyteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Minun lihani on puetettu madoilla ja maan tomulla; minun nahkani on ahvettunut ja hyljätyksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Minun päiväni ovat lentäneet nopiammasti pois kuin syöstävä ja kuluneet ilman viivytystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Muista, että minun elämäni on tuuli, ja minun silmäni ei palaja hyvää näkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Ja ei yksikään silmä, joka minun nyt näkee, pidä minua enempi näkemän. Sinun silmäs katsokoon minua, sitte minä hukun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Pilvi raukee ja menee pois: niin myös se, joka menee alas hautaan, ei nouse jälleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Eikä palaja jälleen huoneesensa, ei myös hänen siansa häntä enää tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Sentähden en minä estä suutani; minä puhun henkeni ahtaudessa, ja juttelen sieluni murheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Olenko minä meri eli valaskala, että sinä minun niin kätket?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Kuin minä ajattelin: minun vuoteeni lohduttaa minun, ja minun kehtoni saattaa minulle levon, koska minä itselleni puhun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Niin sinä peljätät minua unilla, ja kauhistat minua näyillä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Että minun sieluni sois itsensä hirtetyksi, ja minun luuni kuolleiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Minä kauhistun, enkä pyydä silleen elää: lakkaa minusta, sillä minun päiväni ovat turhat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Mikä on ihminen,ettäs hänen suurena pidät, ja panet hänen sydämees?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Sinä etsit häntä joka päivä, ja koettelet häntä aina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Miksi et minusta luovu, ja päästä minua, siihen asti että minä sylkeni nielisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Minä olen syntiä tehnyt; mitä minun pitää sinulle tekemän, o sinä ihmisten vartia? miksis minun teit sinulles loukkaukseksi ja itselleni kuormaksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Ja miksi et minun pahaa tekoani anna anteeksi ja ota pois minun vääryyttäni? Sillä nyt pitää minun makaaman mullassa: ja jos minua aamulla etsit, niin en minä enää ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Niin vastasi Bildad Suasta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Kuinka kauvan sinä tahdot näitä puhua? ja sinun suus puheet ovat niinkuin väkevä tuuli?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Väärinkö Jumala tuomitsee, eli rikkooko Kaikkivaltias oikeuden?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Jos poikas ovat syntiä tehneet hänen edessänsä, niin hän on hyljännyt heitä heidän pahain tekoinsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Mutta jos sinä aikanansa etsit Jumalaa, ja rukoilet Kaikkivaltiasta hartaasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Ja jos sinä olet puhdas ja hyvä, niin hän herättää sinun, ja taas tekee rauhalliseksi hurskautes majan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Ja kussa sinulla oli ennen vähä, pitää tästedes sinulle sangen paljon lisääntymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Sillä kysy nyt entisiltä sukukunnilta, ja rupee kysymään heidän isiltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Sillä me olemme niinkuin eilen tulleet, ja emme mitään tiedä: meidän elämämme on niinkuin varjo maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Heidän pitää opettaman sinua, ja sanoman sinulle, ja tuoman puheensa edes sydämestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Kasvaako kaisla, ellei seiso loassa? eli kasvaako ruoho ilman vettä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Koska se vielä kukoistaa ennenkuin se niitetään, kuivettuu se ennenkuin heinä korjataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Niin käy kaikkein niiden, jotka Jumalan unhottavat, ja ulkokullattuin toivo katoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Sillä hänen toivonsa tulee tyhjäksi, ja hänen uskalluksensa niinkuin hämähäkin verkko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Hän luottaa huoneensa päälle, ja ei se pidä seisoman; hän turvaa siihen, ja ei se pidä pysyväinen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Se viheriöitsee kyllä ennen auringon nousemaa, ja sen heikot oksat kasvavat hänen yrttitarhassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Hänen juurensa seisoo paksuna lähteen tykönä, ja huoneet kivien päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Mutta koska hän nielee sen paikastansa, kieltää hän sen, niinkuin ei olis nähnytkään sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Katso, tämä on hänen menonsa riemu; ja toiset taas kasvavat tuhasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Sentähden katso, ei Jumala hyviä hylkää, eikä vahvista pahain kättä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Siihen asti että sinun suus naurulla täytetään ja huules riemulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Mutta ne jotka sinua vihaavat, pitää häpiään tuleman; ja jumalattomain asuinsia ei pidä pysyväinen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Minä kyllä sen tiedän, että niin on, ettei ihminen taida hurskas olla Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Jos hän tahtois riidellä hänen kanssansa, ei hän taitais vastata häntä yhtä tuhanteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Hän on viisas ja voimallinen: kenenkä siitä on hyvää ollut, kuin häntä vastaan on itsensä asettanut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Hän siirtää vuoret ennenkuin he sen ymmärtävät, jotka hän vihassansa kukistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Hän liikuttaa maan siastansa, niin että sen patsaat vapisevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Hän puhuu auringolle, niin ei se nouse; ja hän lukitsee tähdet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Hän yksin levittää taivaat, ja käy meren aaltoin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Hän tekee Otavan ja Kointähden, Seulaiset ja ne tähdet etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Hän tekee suuria töitä, joita ei taideta tutkia, ja epälukuisia ihmeitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Katso, hän käy minun ohitseni ennenkuin minä sen havaitsen, ja menee pois ennenkuin minä sen ymmärrän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Katso, jos hän menee äkisti, kuka noutaa hänen jälleen? kuka sanoo hänelle: mitäs teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Hän on Jumala, hänen vihaansa ei yksikään aseta; hänen allensa pitää itsensä kumartaman ylpiätkin herrat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Kuinka minun pitäisi häntä vastaaman, ja löytämän sanoja häntä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Ehkä minulla vielä oikeus olis, niin en kuitenkaan taida minä häntä vastata; vaan täytyis oikeudessa rukoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Ja ehkä minä vielä häntä avuksihuutaisin, ja hän kuulis minua, niin en minä uskoisi, että hän kuultelis minun ääntäni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Sillä hän hän runtelee minun tuulispäällä, ja enentää minun haavani ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Ei hän anna minun henkeni virota, vaan täyttää minun murheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Jos joku tahtoo voimaa, katso, hän on voimallinen; jos joku tahtoo oikeutta, kuka todistaa minun kanssani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Jos minä sanoisin: minä olen oikia, niin minun suuni kuitenkin tuomitsee minun: eli minä olen vakaa, niin hän kuitenkin tekee minun pahaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Ehkä minä vielä vakaa olisin, niin en minä kuitenkaan tunne itsiäni; vaan minä suutun eIämääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Se on se ainoa minkä minä sanonut olen, hän kadottaa hyvän ja jumalattoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Kuin hän rupee lyömään, niin hän tappaa äkisti, ja pilkkaa viattomain kiusausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Maa annetaan jumalattoman käsiin, hän peittää sen tuomarien kasvot: ellei se niin ole, kuinka se myös toisin on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Minun päiväni ovat olleet nopiammat kuin juoksia: ne ovat paenneet, ja ei mitään hyvää nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Ne ovat pois menneet kuin joutuva haaksi, kuin kotka lentää rualle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Koska minä ajattelen: minä unhotan valitukseni, ja muutan kasvoni ja virvoitan minuni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Niin minä pelkään kaikkia minun kipujani, tietäen, ettes anna minun olla viatoinna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Jos olen jumalatoin, miksi minä nyt itsiäni hukkaan vaivaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Vaikka minä pesisin itseni lumivedessä ja puhdistaisin käteni saippualla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Niin sinä kuitenkin pistäisit minun lokaan; ja minun vaatteeni olisivat minulle kauhistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Sillä ei hän ole minun vertaiseni, jota minä vastata taidan, että me ynnä tulisimme oikeuden eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Ei ole joka meitä eroittaa, joka laskis kätensä meidän kahden välillemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Hän ottakoon vitsansa pois minusta, ja älköön hänen hirmuisuutensa peljättäkö minua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Että minä puhuisin ja en pelkäisi häntä; sillä en minä mitään kanssani tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Minun sieluni suuttuu elämästä; minun valitukseni minusta annan minä olla ja puhun sieluni murheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Sanon Jumalalle: älä minua tuomitse: anna minun tietää, minkätähden sinä riitelet minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Onko sinulla ilo siitä, ettäs väkivaltaa teet, ja hylkäät minun, joka käsialas olen, ja annat jumalattomain aivoitukset kunniaan tulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Onko sinulla lihalliset silmät? eli katsotkos niinkuin ihminen katsoo?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Onko sinun päiväs niinkuin ihmisen päivät? eli vuotes niinkuin ihmisen vuodet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Ettäs kysyt minun vääryyttäni, ja tutkit pahaa tekoani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Vaikka tiedät, etten minä ole jumalatoin; ehkei yhtään ole, joka taitaa sinun kädestäs vapauttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Sinun kätes ovat minun valmistaneet ja tehneet minun kaikki ympäri, ja sinä tahdot hukuttaa minun?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Muista siis, että olet minun tehnyt niinkuin saven, ja annat minun tulla maaksi jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Etkös minua ole lypsänyt kuin rieskaa, ja antanut minun juosta niinkuin juustoa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Sinä olet minun puettanut nahalla ja lihalla: luilla ja suonilla olet sinä minun peittänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Elämän ja hyvän työn olet sinä minulle osoittanut, ja sinun katsomises minun henkeni kätkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Ja vaikka sinä nämät salaat sydämessäs, niin minä tiedän sen kuitenkin, ettäs sen muistat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Jos minä pahaa teen, niin sinä kohta havaitset, ja et jätä minun pahaa tekoani rankaisemata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Jos minä olen jumalatoin, voi minua! jos minä olen hurskas, niin en minä kuitenkaan uskalla nostaa ylös päätäni. Minä olen täynnä ylönkatsetta, katsos minun viheliäisyyttäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Noustessa sinä ajat minua takaa niinkuin jalopeura, ja taas ihmeellisesti minun kanssani menettelet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Sinä uudistat todistukses minua vastaan, ja vihastut kovin minun päälleni. Minua vaivaa yksi toisensa jälkeen niinkuin sota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Miksis minun annoit lähteä äitini kohdusta? jospa minä olisin kuollut, ettei yksikään silmä olisi minua nähnyt!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Niin minä olisin kuin en olisikaan ollut, kannettu äitini kohdusta hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Eikö minun ikäni lyhyt ole? Lakkaa ja päästä minua, ja luovu minusta, että minä vähänkin virvoitusta saisin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Ennenkuin minä menen, enkä palaja, pimeyden ja kuolon varjon maalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Joka on pimeyden maa ja synkiä kuolon varjo, jossa ei yhtään järjestystä ole, joka paisteessansa on niinkuin synkeys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Niin vastasi Zophar Naemasta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Kuin joku on kauvan puhunut, eikö häntä pitäis vastattaman? eli pitääkö suupaltilla oikeus oleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Pitääkö sinun jaarituksiis ihmisten vaikeneman, että sinä pilkkaat, eikä yksikäan sinua häpäisisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Sinä sanot: minun opetukseni on selkiä, ja minä olen puhdas sinun silmäis edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Jospa Jumala puhuis ja avais huulensa sinua vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Ja ilmoittais sinulle salaisen tiedon! sillä hänellä olis vielä enempi tekemistä, ettäs tietäisit, ettei hän muistele kaikkia sinun pahoja töitäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Luuletkos tutkistellessas Jumalan löytäväs? ja Kaikkivaltiaan täydellisesti löytäväs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Hän on korkiampi kuin taivas, mitäs tahdot tehdä? syvempi kuin helvetti, kuinkas taidat tuta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Pitempi kuin maa, ja laviampi kuin meri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Jos hän sen ylösalaisin kääntäis, eli kätkis, eli heittäis kokoon; kuka hänen estäis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Sillä hän tuntee turhatkin ihmiset, ja näkee vääryydet; ja ei hänen pitäis ymmärtämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Turha ihminen ylpeilee, ja syntynyt ihminen on niinkuin metsä-aasin varsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Jos olisit valmistanut sydämes, ja nostanut kätes hänen tykönsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Jos vääryys on sinun kädessäs, niin heitä se kauvas, ettei yhtään vääryyttä asuisi majassas:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Niin sinä ylennät kasvos ilman laitosta, ja olet vahva ja ei pelkääväinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Niin sinä myös unhotat vaivan; ja niinkuin ohitse juossut vesi, tulee se mielees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Ja sinun elämäs aika pitää käymän ylös niinkuin puolipäivä, ja pimeys niinkuin kirkas aamu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Ole hyvässä turvassa, vielä nyt toivo on; sillä vaikkas nyt olet häpiässä, niin sinä kuitenkin olet rauhassa lepäävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Sinä olet makaava, ja ei kenkään sinua peljätä: monen pitää sinua kunnioittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Mutta jumalattomain silmät pitää nääntymän, ja ei voi päästää; sillä heidän toivonsa pitää puuttuman heidän sieluiltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Niin vastasi Job ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Te olette miehet; taito kuolee teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Minulla on niin sydän kuin teilläkin, enkä ole alemmaisempi teitä: kuka se on, joka ei näitä tiedä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Joka lähimmäiseltänsä pilkataan, niinkuin minä, hän rukoilee Jumalaa, ja hän kuulee häntä: hurskas ja vakaa pilkataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Hän on ylönkatsottu kynttiläinen ylpeiden ajatuksissa, valmistettu, että he siihen loukkaavat jalkansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Ryövärein majoissa on kyllä, ja he härsyttelevät rohkiasti Jumalaa, ehkä Jumala on sen antanut heidän käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Kysy siis eläimiltä, ja he opettavat sinua, ja taivaan linnuilta, ja he sanovat sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Taikka puhu maan kanssa, ja hän opettaa sinua; ja kalat meressä ilmoittavat sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kuka se on, joka ei kaikkia näitä tiedä, että Herran käsi on ne tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Että hänen kädessänsä on kaikkein elävien sielu, ja kunkin lihan henki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Eikö korva koettele puhetta, ja suu maista ruokaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Vanhoilla on taito, ja pitkä-ijällisillä ymmärrys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Hänen tykönänsä on taito ja voima; hänen on neuvo ja ymmärrys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Katso, koska hän kukistaa, niin ei auta rakentamaan: koska hän jonkun salpaa, niin ei kenkään taida avata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Katso, koska hän pidättää veden, niin kaikki kuivettuu, ja koska hän laskee, niin se kääntää maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Hän on vahva Ja pysyväinen: hänen on se joka eksyy, ja se joka eksyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Hän johdattaa kavalat niinkuin saaliin, ja saattaa tuomarit tyhmäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Hän päästää kuningasten siteet, ja vyöttää heidän kupeensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Papit vie hän niinkuin saaliin, ja väkevät kukistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Hän vääntää pois totisten huulet, vanhain toimen ottaa hän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Hän kaataa ylönkatseen päämiesten päälle, ja voimallisten väkevyyden hajoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Hän ilmoittaa pimiät perustukset, ja kuoleman varjon saattaa hän valkeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Hän saattaa kansat suureksi, ja taas hukuttaa heidät; hän levittää kansan, ja taas vie pois heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Hän ottaa pois maan kansan ruhtinasten sydämet, ja eksyttää heitä korvessa, jossa ei tietä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Ja he koperoitsevat pimeydessä ilman valkeutta; ja hän eksyttää heitä kuin juopuneita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Katso, kaikkia näitä ovat silmäni nähneet, ja korvani kuulleet, ja on ne ymmärtänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Jota te tiedätte, sitä minäkin tiedän, enkä ole halvempi teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Minä puhun siis Kaikkivaltiaan tykö, ja mielin kamppailla Jumalan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Sillä te olette valheen saarnaajat, ja kaikki kelvottomat lääkärit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Jospa te voisitte juuri ääneti olla, niin te olisitte taitavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Kuulkaat siis minun kamppaustani, ja ottakaat vaari asiasta, kuin minä puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Tahdotteko te Jumalan puolesta vastata vääryydellä? ja hänen puolestansa puhua petosta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Tahdotteko te katsoa hänen mieltänsä? Tahdotteko te riidellä Jumalan puolesta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Pitääkö se teille menestymän, koska hän teitä etsii? luuletteko te hänen pettävänne, niinkuin joku pettää ihmisen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Hän kovin nuhtelee teitä, jos te salaisesti mieliä katsotte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Eikö hänen korkeutensa teitä peljätä? ja hänen pelkonsa lankee teidän päällenne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Teidän muistonne vedetään tuhan verraksi, ja teidän selkänne pitää oleman niinkuin saviroukkio.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Olkaat ääneti minun edessäni, minä puhun, tapahtukoon minulle mitä hyvänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Miksi minun pitää pureman lihaani hampaillani, ja asettaman sieluni minun käsiini?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Katso, vaikka hän minun tappais, enkö minä vielä sittenkin toivoisi? kuitenkin minä nuhtelen teitäni hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Hän on kuitenkin minun autuuteni; sillä ei yksikään ulkokullattu tule hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Kuulkaat juuri visusti minun puhettani, ja minun selitystäni teidän korvainne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Katso, jo minä olen tuomion sanonut: Minä tiedän, että minä olen hurskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kuka tahtoo käydä oikeudelle minun kanssani? Mutta minun täytyy nyt ääneti olla, ja loppua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Ainoastaan älä tee minulle kahta, niin en minä kätke itsiäni sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Anna kätes olla kaukana minusta, ja sinun kauhistukses älköön minua peljättäkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Kutsu minua, ja minä vastaan: eli minä puhun, ja vastaa sinä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Kuinka usiat ovat minun vääryyteni ja pahat tekoni? anna minun saada tietää minun syntini ja rikokseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Miksi sinä peität kasvos, ja pidät minua vihollisena?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Tahdotkos niin kova olla lentävää lehteä vastaan, ja vainota kuivaa oljen kortta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Sillä sinä kirjoitat minulle murhetta, ja annat minun periä nuoruuteni syntejä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Sinä olet pannut minun jalkani jalkapuuhun, ja otat kaikista minun poluistani vaarin, ja katsot kaikkia minun askeleitani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Joka kuitenkin hukun niinkuin mädännyt raato, ja niinkuin koilta syöty vaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Ihminen, vaimosta syntynyt, elää vähän aikaa, ja on täynnä levottomuutta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Kasvaa niinkuin kukkanen, ja kaatuu; pakenee niinkuin varjo, ja ei pysy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Ja senkaltaisen päälle sinä avaat silmäs, ja vedät minun kanssasi oikeuden eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Kuka löytää puhtaan niiden seassa, kussa ei puhdasta ole?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Hänellä on määrätty aika, hänen kuukauttensa luku on sinun tykönäs: sinä olet määrän asettanut hänen eteensä, jota ei hän taida käydä ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Luovu hänestä, että hän sais levätä, niinkauvan kuin hänen aikansa tulee, jota hän odottaa niinkuin palkollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Puulla on toivo, ehkä se hakattaisiin, että se uudistetaan, ja sen vesat kasvavat jälleen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Ehkä sen juuret vanhenevat maassa, ja kanto mätänee mullassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Kuitenkin se versoo jälleen veden märkyydestä, ja kasvaa niinkuin se istutettu olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mutta kussa ihminen on, koska hän kuollut, hukkunut ja pois on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Niinkuin vesi juoksee ulos merestä, ja oja kureentuu ja kuivettuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Niin on ihminen, kuin hän kuollut on, ei hän nouse: niinkauvan kuin taivas pysyy, ei he virkoo eikä herää unestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'O jospa sinä minun hautaan kätkisit ja peittäisit minun, niinkauvan kuin vihas menis pois, ja asettaisit minulle määrän muistaakses minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Luuletkos kuolleen ihmisen tulevan eläväksi jälleen? Minä odotan joka päivä niinkauvan kuin minä sodin, siihenasti että minun muutteeni tulee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Että sinä kutsuisit minua, ja minä vastaisin sinua, ja ettes hylkäisi käsialaas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Sillä sinä olet jo lukenut kaikki minun askeleeni: etkös ota vaaria minun synneistäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Minun rikokseni olet sinä lukinnut lyhteesen, ja pannut kokoon minun vääryyteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Jos tosin vuori kaatuu ja katoo, ja vaha siirtyy sialtansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Vesi kuluttaa kivet, ja virta vie maan pois, ja mitä sen päällä itse kasvaa: niin sinä myös ihmisen toivon kadotat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Sinä olet häntä voimallisempi ijankaikkisesti, ja hänen täytyy mennä pois. Sinä muutat hänen kasvonsa, ja annat hänen mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Ovatko hänen lapsensa kunnniassa, sitä ei hän tiedä, taikka ovatko he ylönkatseessa, sitä ei hän ymmärrä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Kuitenkin niinkauvan kuin hän kantaa lihaa, täytyy hänen olla vaivassa, ja niinkauvan kuin hänen sielunsa on hänessä, täytyy hänen murhetta kärsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Niin vastasi Eliphas Temanilainen ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Pitääkö taitavan niin tuuleen puhuman, ja täyttämän vatsansa tuulella?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Sinä nuhtelet kelvottomilla sanoilla ja puheilla, joista ei ole hyödytystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Sinä olet hyljännyt pelvon, ja puhut ylönkatseella Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Sillä sinun pahuutes opettaa niin sinun suus; ja sinä olet valinnut viekasten kielen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Sinun suus pitää tuomitseman sinun, ja en minä: sinun huules pitää todistaman sinua vastaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Oletkos ensimäinen ihminen, joka syntynyt on? eli ennen (kaikkia) vuoria luotu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Oletko sinä kuullut Jumalan salaisen neuvon? ja onko taito halvempi sinua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Mitä sinä tiedät, jota emme tiedä; mitäs ymmärrät, joka ei ole meidän tykönämme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Harmaapäät ja vanhat ovat meidän tykönämme, jotka ennen ovat eläneet kuin sinun isäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Pitäiskö Jumalan lohdutukset oleman halvat sinulle? Eli onko jotakin salaista tykönäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Mitä sinun sydämes aikoi? ja mitäs vilkutat silmiäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Kuinka sinä asetat mieles Jumalaa vastaan? että sinä senkaltaiset sanat suustas päästät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Mikä on ihminen, että hän olis puhdas? ja että hän olis hurskas, joka vaimosta syntynyt on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Katso, hänen pyhäinsä seassa ei ole yhtään nuhteetointa; ja taivaat ei ole puhtaat hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Kuinka paljon enemmin ihminen on kauhia ja ilkiä, joka juo vääryyttä niinkuin vettä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Minä osoitan sinulle sen, kuule minua: minä luettelen sinulle, mitä minä nähnyt olen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Mitä taitavat sanoneet ovat, jota ei yksikään heidän isistänsä ole salannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Joille ainoille maa annettu on, niin ettei yksikään outo saanut käydä heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Jumalatoin vapisee kaiken elinaikansa, ja tyrannin vuosiluku on peitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Pelvon ääni on hänen korvissansa, että rauhassakin pitää hävittäjä tuleman hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Ei hän usko palajavansa pimeydestä, ja varoo aina miekkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Kuin hän lähtee sinne ja tänne elatuksensa jälkeen, niin hän luulee aina pimeyden päivän käsissänsä olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Ahdistus ja hätä peljättävät häntä, ja yllyttävät hänen, niinkuin kuningas valmis sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Sillä hän on ojentanut kätensä Jumalaa vastaan, ja vahvistanut itsensä Kaikkivaltiasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Hän juoksee päätäpäin häntä vastaan, ja seisoo ynseästi häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Hän on peittänyt kasvonsa lihavuudellansa, ja lihoittanut ja paisuttanut itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'Mutta hänen pitää asuman hävitetyssä kaupungissa ja asumattomissa huoneissa, jotka roukkioksi riutumallansa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Ei hänen pidä rikastuman, eikä hänen tavaransa pysymän, eikä hänen onnensa pidä leviämän maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Ei hänen pidä pääsemän pimeydestä: tulen liekki kuivaa hänen oksansa, ja hänen suunsa hengellä katoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Ei hän taida uskaltaa turhuuteen, että hän on petetty; sillä turhuus on hänen palkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Hän loppuu ennen aikaansa, ja hänen oksansa ei pidä vihoittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Hän poimitaan niinkuin kypsymätöin marja viinapuusta, ja niinkuin öljypuu varistaa kukoistuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Sillä ulkokullattuin kokous pitää oleman yksinäinen, ja tulen pitää polttaman lahjain ottajan huoneen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Hän siittää onnettomuuden, ja synnyttää vaivaisuuden; ja heidän vatsansa valmistaa petoksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Sitte vastasi Job ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Minä olen usein senkaltaista kuullut: te olette kaikki häijyt lohduttajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Koska siis nämät tyhjät puheet loppuvat? eli mikä sinun niin rohkaisee puhumaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Minä taitaisin myös puhua niinkuin tekin. Minä soisin teidän sielunne olevan minun sieluni siassa, niin minä löytäisin myös sanoja teitä vastaan, ja taitaisin vääntää päätäni teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Minä tahtoisin vahvistaa teitä suullani, ja lohduttaa huulillani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Mutta ehkä minä puhuisin, niin ei kuitenkaan minun vaivani lakkaa: jos minä vaikenen, niin ei se kuitenkaan mene minusta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Mutta nyt hän saattaa minulle vaivaisuuden: sinä hävität koko minun seurani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Sinä olet tehnyt minun ryppyiseksi, että olis todistus minua vastaan: minun laihuuteni nousee minua vastaan, ja sanoo minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Hänen vihansa repäisee minun, ja joka minua vihaa, kiristelee hampaitansa minun päälleni; ja minun viholliseni silmät kiiluvat minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'He ammottivat suunsa minua vastaan, ja ovat minua häpiällisesti poskelle piesseet: he ovat sammuttaneet vihansa minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Jumala on minun hyljännyt väärille, ja antanut minun tulla jumalattomain käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Minä olin rauhassa, vaan hän on minun murentanut, hän on tarttunut minun kaulaani, ja särkenyt minun, ja pannut minun hänellensä maaliksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Hänen ampujansa ovat piirittäneet minun: hän on reväissyt minun munaskuuni, eikä säästänyt: hän on vuodattanut minun sappeni maan päälle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Hän on haavoittanut minun yhdellä haavalla toisen perään: Hän karkasi minun päälleni niinkuin joku väkevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Minä ompelin säkin minun nahkani päälle, ja laskin sarveni multaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Minun kasvoni ovat soaistut itkusta, ja silmälautani päällä on kuoleman varjo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Ehkei kuitenkaan minun kädessäni ole vääryys, ja minun rukoukseni on puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Maa, älä peitä minun vertani, ja älkään olko minun huudolleni siaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Ja katso, minun todistajani on taivaassa, ja joka minun tuntee, on korkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Minun ystäväni ovat minun pilkkaajani; mutta minun silmäni vuodattavat kyyneliä Jumalan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Joka ihmisen puolesta vastaa Jumalan tykönä, niinkuin ihmisen lapsi lähimmäisensä puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Mutta määrätyt vuodet ovat tulleet, ja minä menen sitä tietä pois, jota en minä jälleen palaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Minun henkeni on heikko, minun päiväni ovat lyhetyt, ja hauta on käsissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'En minä ketäkään pettänyt, ja kuitenkin minun silmäni täytyy olla murheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Nyt siis taivuta sinus, ja ole itse minun takaukseni! kukas muu olis, joka minua takais?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Ymmärryksen olet sinä heidän sydämistänsä kätkenyt, sentähden et sinä korota heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Hän kerskaa ystävillensä saaliistansa, mutta hänen lastensa silmät pitää vaipuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Hän on minun pannut sananlaskuksi kansain sekaan, ja ääniksi heidän keskellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Minun silmäni ovat pimenneet minun suruni tähden, ja kaikki minun jäseneni ovat niinkuin varjo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Tästä hurskaat hämmästyvät, ja viattomat asettavat heitänsä ulkokullatuita vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Hurskas pysyy tielIänsä: ja jolla on puhtaat kädet, se pysyy vahvana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Kääntäkäät siis teitänne kaikki ja tulkaat nyt: en minä kuitenkaan löydä yhtään taitavaa teidän seassanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Minun päiväni ovat kuluneet: minun aivoitukseni ovat hajoitetut, jotka minun sydämessäni olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Ja ovat yöstä päivän, ja valkeuden pimeydestä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Ja ehkä minä kauvan odottaisin, niin on kuitenkin hauta minun huoneeni, ja minä olen vuoteeni pimeydessä tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Mätänemisen minä kutsuin isäkseni, ja madot äidikseni ja sisarekseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Kussa on nyt minun odottamiseni? ja kuka ottaa minun toivostani vaarin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Hautaan se menee, ja makaa minun kanssani mullassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Niin vastasi Bildad Suasta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Koska te lakkaatte puhumasta? ymmärtäkäät ensin, ja puhukaamme sitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Miksi me pidetään niinkuin juhdat, ja olemme niin saastaiset teidän silmäinne edestä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Tahdotkos revetä kiukussas? luuletkos, että maa sinun tähtes hyljätään ja kallio siirretään siastansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Jumalattoman valkeus pitää myös sammutettaman, ja hänen valkiansa kipinä ei pidä paistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Hänen majassansa pitää valkeus tuleman pimeydeksi, ja hänen kynttilänsä pitää siinä sammutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Hänen voimansa askeleet pitää ahdistettaman; ja hänen neuvonsa pitää hänen maahan sysäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Sillä hän on viety jalkoinensa paulaan, ja vaeltaa verkossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Paula pitää pitämän hänen kantapäänsä, ja ryövärit pitää hänen käsittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Hänen paulansa on viritetty maan päälle, ja hänen satimensa hänen polullensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Kaikin tahoin pitää kauhistukset häntä peljättämän, ja hänen jalkansa eksyttämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Nälkä pitää oleman hänen tavaransa, ja onnettomuus pitää oleman valmistettu hänen kylkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Hänen nahkansa vahvuus pitää kulutettaman, ja hänen väkevyytensä pitää kuoleman esikoisen syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Hänen toivonsa pitää revittämän ylös juurinensa hänen majastansa, ja hän pitää ajettaman pelkoin kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Se on asuva hänen majassansa hänen puutteensa tähden: hänen majansa päälle pitää tulikiveä viskottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Alhaalta pitää hänen juurensa kuivettuman, ja ylhäältä hänen elonsa niitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Hänen muistonsa pitää hukkuman maan päältä, ja ei pidä ensinkään hänellä nimeä oleman kadulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Hän pitää ajettaman valkeudesta pimeyteen, ja pitää maalta heitettämän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Ei hänellä pidä yhtään lasta oleman, eikä lasten lasta hänen kanssansa; ja ei pidä yhtään hänen asuinsioihinsa jäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ne jotka hänen perässänsä tulevat, pitää hämmästymän hänen päivästänsä, ja ne jotka hänen edellänsä ovat olleet, pitää peljästymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Tämä on jumalattoman maja, ja tämä on sen sia, joka ei Jumalasta mitään tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Mutta Job vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Kuinka kauvan te vaivaatte minun sieluani? ja runtelette minua sanoilla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Te olette nyt kymmenen kertaa pilkanneet minua; ja ette häpee minua niin vaivata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Jos minä erehdyn, niin minä itselleni erehdyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Mutta te tosin nousette minua vastaan, ja soimaatte minun pilkkaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Niin tietäkäät nyt, että Jumala hukuttaa minun, ja on piirittänyt minun verkkoihinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Katso, ehkä minä vielä väkivallan tähden huutaisin, niin ei kuitenkaan kuulla minua: jos minä parkuisin, niin ei tässä ole oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Hän on aidannat minun tieni, etten minä taida sitä käydä, ja pannut pimeyden minun poluilleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Hän on riisunut minun kunniani minulta, ja ottanut pois kruunun minun päästäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Hän on maahan kukistanut minun joka kulmalta, ja laskenut minun menemään; ja on reväissyt ylös minun toivoni niinkuin puun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Hän on hirmuisesti vihastunut minun päälleni, ja pitää minun vihamiehenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Hänen sotajoukkonsa ovat kokoontuneet, ja asettaneet tiensä minua kohden, ja piirittäneet minun majani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Hän on eroittanut minun veljeni kauvas minusta, ja minun tuttavani ovat minulle muukalaisiksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Minun lähimmäiseni piiloivat minua, ja minun ystäväni ovat unhottaneet minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Minun huonekuntalaiseni ja piikani pitävät minua vieraana, minä olen tuntemattomaksi tullut heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Minä huusin palveliaani, ja ei hän vastannut minua: minun täytyy rukoilla häntä omalla suullani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Minun emäntäni vieroi minun henkeäni, ja minun täytyy palvella omia lapsiani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Ja nuoretkin lapset minun katsovat ylön: jos minä nousen, niin he puhuvat minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Kaikki uskolliset ystäväni kauhistuvat minua; ja joita minä rakastin, ovat kääntäneet itsensä minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Minun luuni tarttuivat minun nahkaani ja lihaani, ja en minä taida nahallani peittää hampaitani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Armahtakaat minun päälleni, armahtakaat minun päälleni, te minun ystäväni! sillä Jumalan käsi on minuun sattunut!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Miksi te vainootte minua niinkuin Jumalakin, ja ette taida minun lihastani ravittaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Jospa minun puheeni kirjoitettaisiin! jospa ne kirjaan pantaisiin, ja painettaisiin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Raudalla kaivettaisiin lyijy ijankaikkiseksi muistoksi kiveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Sillä minä tiedän minun Lunastajani elävän: ja hän on tästälähin maan päällä seisova.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Ja vaikka vihdoin minun nahkani ja tämä (ruumis) lakastuu, saan minä kuitenkin minun lihassani nähdä Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Hänen minä olen minulleni näkevä, ja minun silmäni katsovat häntä, ja ei kenkään outo. Minun munaskuuni ovat kuluneet minun helmassani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Tosin teidän pitäis sanoman: Miksi me vainoamme häntä? sillä tämän puheen perustus löytyy minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Peljätkäät siis miekkaa, sillä viha on pahain töiden kostomiekka, että te tietäisitte kurituksen tulevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Silloin Zophar Naemasta vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Minun ajatakseni vaativat siis minua vastaamaan, ja en minä taida itsiäni pidättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Minä tahdon kuulla, jos joku minua nuhtelee ja laittaa; sillä minun ymmärrykseni benki vastaa minun puolestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Etkös tiedä sen aina niin käyneen siitä ajasta kuin ibminen on pantu maan päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Että jumalattomien kerskaus ei ulotu kauvas; ulkokullattuin ilo on silmänräpäykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Jos hänen korkeutensa ulottuis taivaasen, ja hänen päänsä sattuis pilviin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Niin pitää hänen viimein katooman niinkuin loka, niin että ne jotka hänen ovat näneet, sanovat: kussa hän on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Niinkuin uni katoo, niin ei pidä häntä löydettämän, ja niinkuin yönäkö pitää hänen raukeaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Se silmä, joka hänen nähnyt on, ei pidä häntä enää näkemän, ja hänen paikkansa ei pidä häntä enää näkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Hänen lapsensa pitää kerjääjiä palveleman, ja hänen kätensä pitää jälleen hänelle antaman, mitä hän ryövännyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Hänen luunsa pitää maksaman hänen salaiset syntinsä, ja pitää makaaman maassa hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Ehkä vielä pahuus maistais makiasti hänen suussansa, kuitenkin pitää hänen sen kätkemän kielensä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Hän säästää, ja ei hylkää sitä, vaan pitää sen suussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Hänen ruokansa pitää muuttuman hänen vatsassansa, kärmeen sapeksi hänen sisälmyksissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Sen tavaran jonka hän niellyt on, pitää hänen ylös oksentaman; ja Jumala ajaa ne ulos hänen vatsastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Hänen pitää imemän kärmeen myrkkyä, ja kyykärmeen kieli on hänen tappava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Ei hänen pidä näkemän ojia ja virtoja, joista hunaja ja voi vuotavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Hän tekee työtä, ja ei saa nautita, ja hänen kalunsa pitää toisen saaman, niin ettei hänellä pidä niistä iloa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Sillä hän on polkenut ja hyljännyt köyhän, hän on repinyt itsellensä huoneita, joita ei hän ole rakentanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Sillä hänen vatsansa ei ole taitanut täyteen tulla, ja hänen kalliit kalunsa ei taida häntä pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Hänen ruastansa ei pidä mitään jäämän; sentähden ei pidä hänen hyvät päivänsä pysyväiset oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Ehkä hänellä olis yltäkyllä, niin pitää hänellä kuitenkin ahdistus oleman: kaikki käden vaiva pitää hänen päällensä tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Hänen vatsansa pitää vihdoin täyteen tuleman, ja hänen pitää lähettämän vihansa hirmuisuuden hänen päällensä: hän antaa sataa sotansa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Hänen pitää pakeneman rautaisia sota-aseita, ja vaskijoutsen pitää hänen lävitsensä käymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Avoin miekka pitää käymän hänen lävitsensä, ja miekan välkkynä, joka hänelle pitää karvas oleman, pitää pelvolla hänen päällensä tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Koko pimeys on hänelle kätketty tavaraksi; tuli pitää hänen kuluttaman, joka ei puhallettu ole, ja sille, joka jää hänen majaansa, pitää pahoin käymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Taivaan pitää ilmoittaman hänen pahuutensa, ja maan pitää asettaman itsensä häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Hänen huoneensa hedelmä pitää vietämän pois, ja hajoitettaman hänen vihansa päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Tämä on jumalattoman ihmisen osa Jumalalta, ja hänen puheensa perintö Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Kuulkaat visusti minun puhettani, ja antakaat neuvoa teitänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Kärsikäät minua, että minä myös puhuisin: ja kuin minä puhunut olen, pilkkaa sitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Puhunko minä ihmisen kanssa? miksi ei minun henkeni pitäisi tästä murehtiman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Katsokaat minun päälleni, ja hämmästykäät, ja pankaat kätenne suun eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Koska minä sitä ajattelen, niin minä peljästyn, ja vavistus tulee minun lihani päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Miksi jumalattomat elävät, tulevat vanhaksi ja lisääntyvät tavarassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Heidän siemenensä on pysyväinen heidän ympärillänsä, ja heidän sikiänsä ovat läsnä heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Heidän huoneensa ovat vapaat pelvosta, ja Jumalan vitsa ei ole heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Heidän sonninsa päästetään, ja ei käy väärin, heidän lehmänsä poikivat, ja ei ole hedelmättömät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Heidän nuoret lapsensa käyvät ulos niinkuin lauma, ja heidän lapsensa hyppäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'He riemuitsevat trumpuilla ja kanteleilla, ja iloitsevat huiluilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'He vanhenevat hyvissä päivissä, ja menevät silmänräpäyksessä helvettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Jotka sanovat Jumalalle: mene pois meidän tyköämme; sillä emme tahdo tietää sinun tietäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kuka on Kaikkivaltias, että meidän pitää häntä palveleman? eli mitä meidän siitä hyvää on, että me häntä rukoilemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Mutta katso, heidän tavaransa ei ole heidän kädessänsä: jumalattomain neuvo pitää kaukana minusta oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Kuinka jumalattoman kynttilä sammuu, ja heidän kadotuksensa tulee heidän päällensä? Hänen pitää jakaman surkeutta vihassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Heidän pitää oleman niinkuin korsi tuulessa, ja niinkuin akanat, jotka tuulispää vie salaisesti pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Jumala säästää hänen onnettomuutensa hänen lapsillensa; koska hän maksaa hänelle, silloin hänen pitää tietämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Hänen silmänsä pitää näkemän hänen kadotuksensa, ja Kaikkivaltiaan vihasta pitää hänen juoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Sillä mitä hän tottelee hänen huonettansa hänen jälkeensä? Ja hänen kuukauttensa luku tuskin tulee puolillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Kuka tahtoo opettaa Jumalaa, joka korkiatkin tuomitsee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Tämä kuolee vauraana ja terveenä, rikkaana ja onnellisena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Hänen piimäastiansa ovat täynnä rieskaa, ja hänen luunsa ovat täynnä ydintä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Mutta toinen kuolee murheellisella mielellä, ja ei koskaan syönyt ilossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Ja he makaavat ynnä maassa, ja madot peittävät heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Katso, minä tunnen teidän ajatuksenne ja teidän väärän aivoituksenne minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Sillä te sanotte: kussa ruhtinaan huone on? ja kussa ovat majat, joissa jumalattomat asuiva?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Ettekö ole tutkineet vaeltavaisilta? ja ettekö tiedä hänen merkkejänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Sillä paha säästetään kadotuksen päivään, ja hän pysyy hamaan vihan päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kuka sanoo hänen edessänsä hänen tiensä? ja kuka kostaa hänelle sen minkä hän tehnyt on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Mutta hän viedään hautaan, ja täytyy joukossa pysyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Ojan multa kelpasi hänelle, ja kaikki ihmiset viedään hänen perässänsä; ja ne jotka ovat hänen edellänsä olleet, ovat epälukuiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Miksi te minua lohdutatte turhaan? ja teidän vastauksenne löydetään vääräksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Silloin vastasi Eliphas Temanilainen, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Mitä mies taitaa Jumalalle hyödyllinen olla? vaan itsiänsä taitaa ymmärtäväinen hyödyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Luuletkos Kaikkivaltiaalle kelpaavan, että sinus luet hurskaaksi? eli mitä se auttais, ehkä sinun ties olisivat ilman rikosta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Luuletkos, että hän pelkää sinua rangaista ja käydä oikeudelle kanssas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Eikö sinun pahuutes ole suuri? Ja sinun vääryydelläs ei ole loppua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Sinä olet ottanut pantin veljeltäs ilman syytä, ja olet riisunut vaatteen alastomalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Et sinä ole antanut väsyneelle vettä juoda; sinä olet kieltänyt isoovaiselta leivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Mutta voimallinen sai omistaa maan, ja arvossa pidettävä sai siinä asua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Lesket olet sinä laskenut tyhjänä, ja taittanut orpoin käsivarret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Sentähden olet sinä kierretty pauloilla, ja hämmästys on sinun äkisti peljättänyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Eli pimeys, ettes näkisi; ja vedenpaljous on peittänyt sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Eikö Jumala ole ylhäällä taivaissa? Ja katsos ylimmäisiä tähtiä, että ne korkiat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Ja sinä sanot: mitä Jumala tietää? taitaneeko hän tuomita sitä, mikä pimeydessä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Pilvet peittävät hänen, ettei hän näe: hän vaeltaa taivaan ympäristöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Tahdotkos tuta maailman polkuja, joita väärät ihmiset käyneet ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Jotka ennen aikaansa hukkuneet ovat, ja vesi on liottanut heidän perustuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Ne jotka sanovat Jumalalle: mene meistä pois! mitä Kaikkivaltias taitais heidän tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Vaikka hän on täyttänyt heidän huoneensa tavaralla; mutta jumalattomain neuvo olkoon kaukana minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Hurskaat näkevät sen ja iloitsevat, ja viatoin pilkkaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Meidän varamme ei pidä hukkuman, vaan heidän tähteensä pitää tulen polttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Niin sovi nyt hänen kanssansa, ja ole rauhallinen; siitä saat paljon hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Kuule lakia hänen suustansa, ja käsitä hänen puheensa sinun sydämees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Jos sinä käännät sinus Kaikkivaltiaan tykö, niin sinä rakennetaan, ja saatat vääryyden kauvas majastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Niin sinä annat kullan mullasta, ja ojan kivistä kalliin kullan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Kaikkivaltias on sinun kultas, ja hopiaa pitää sinulla paljo oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Silloin sinun ilos pitää oleman Kaikkivaltiaassa, ja nostaman kasvos Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Sinä rukoilet häntä, ja hän kuulee sinua, ja sinä maksat lupaukses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Mitä aioit, sen hän antaa sinulle menestyä; ja valkeus paistaa sinun teilläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Sillä ne jotka itsensä nöyryyttävät, korottaa hän, ja se joka silmänsä painaa alas, vapautetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Sekin, joka ei viatoin ole, autetaan ja pelastetaan sinun kättes puhtauden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Minun puheeni on vielä murheellinen, ja minun voimani on heikko huokausteni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Jospa minä tietäisin, kuinka minä hänen löytäisin, ja tulisin hänen istuimensa tykö!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Ja asettaisin oikeuden hänen eteensä, ja täyttäisi suuni perustuksilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Tietäisin, mitä hän vastais minua, ja ymmärtäisin, mitä hän minulle sanova olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Riiteleekö hän suurella voimalla minun kanssani? Ei, vaan itse antaa minulle voimaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Sillä minä vakuuteni osoittaisin hänen edessänsä, ja pääsisin ijäti vapaaksi siitä, joka minun tuomitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Mutta jos minä kohdastansa käyn, niin ei hän ole siellä; jos minä menen takaperin, niin en minä häntä havaitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Jos hän on vasemmalla puolella, niin en minä häntä käsitä; jos hän kätkee itsensä oikialle puolelle, niin en minä häntä näe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Mutta hän tuntee minun tieni; koetelkaan minua, niin minä löydetään niinkuin kulta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Sillä minä panen jalkani hänen askeleillensa, pidän hänen tiensä, ja en poikkee siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Ja en poikkee hänen huultensa käskyistä, ja kätken hänen suunsa sanat, niinkuin minun tapani on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Hän on itse ainoa, kuka estää häntä? hän tekee, mitä hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Sillä hän täyttää aivoitukseni minusta; ja tainkaltaisia on paljo hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Sentähden olen minä hämmästynyt hänen edessänsä, ja koska minä sen ymmärrän, niin minä pelkään häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Ja Jumala on tehnyt minun sydämeni pehmiäksi, ja Kaikkivaltias on minun peljättänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Sillä pimeys ei luovu minusta, ja synkeys ei kätketä minulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Siksi ei Kaikkivaltiaalta ole ajat salatut? ja ne, jotka hänen tuntevat, ei näe hänen päiviänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'He siirtävät rajan, he ryöväävät lauman ja ruokkivat sen. \'');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'He ajavat orpoin aasit pois, ja ottavat leskein härjät pantiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Köyhäin täytyy tiellä paeta heitä, ja siviät maan päällä lymyttävät itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Katso, niinkuin metsä-aasit korvessa, lähtevät he ulos ja samoovat varhain saaliin perään: korvessa on jokaiselle heistä ruokaa, niin myös nuorukaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'He niittävät pellolla hänen tulonsa, ja poimivat ja hakevat jumalattoman viinamäessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Alastoman antavat he maata ilman vaatetta ja peittämättä pakkasessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Vuorten vuotamisesta tulevat he märäksi; ja ettei heillä yhtään turvaa ole, turvaavat he mäkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'He repivät orvot nisistä, ja panttaavat köyhän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Alastoman antavat he käydä verhotta, ja ottavat isoovaiselta jalalliset pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'He pusertavat öljyä huonettensa vaiheella, ja janoovat viinaa kuurnitessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'He saattavat kansan kaupungissa huokaamaan, ja tapettuin sielut huutamaan: ja ei Jumala heitä rankaise.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Sentähden ovat he vilpistyneet valkeudesta, ja ei tunne sen tietä, ja ei palaja sen poluille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Murhaaja nousee varhain ja tappaa köyhän ja tarvitsevan, ja on yöllä niinkuin varas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Salavuoteisen silmät vartioitsevat hämärää, ja sanoo: ei minua yksikään silmä näe; ja luulee itsensä peitetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Pimeässä hän kaivaa itsensä huoneisiin, jotka he päivällä ovat itsellensä merkinneet, ja ei tahdo tietää valkeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Sillä vaikka aamu heille tulis, on se heille niinkuin pimeys; sillä hän tuntee pimeyden kauhistuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Hän on keviä veden päällä, heidän osansa pitää kirotun oleman maalla; ja ei hän katso viinamäkien tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Helvetti ottaa syntiset pois niinkuin pouta, ja niinkuin kuivuus kuluttaa lumisen veden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Laupius pitää unhottaman hänen, madot syövät hänen makeutensa, ei häntä pidä muistettaman; hän pitää särjettämän niinkuin lahopuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Hän on saattanut murheelliseksi hedelmättömän, joka ei synnytä, ja ei tehnyt leskelle mitään hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Ja on vetänyt voimalliset allensa väellänsä; koska hän seisoo, ei pidä hänen tietämän elämästänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Hän tekee itsellensä levon, johon hän luottaa, ja hänen silmänsä katsovat heidän teitänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'He ovat vähän aikaa korotetut, vaan he tulevat tyhjään, ja kukistetaan, ja saavat lopun niinkuin kaikki kappaleet, ja niinkuin oas tähkäpäästä, lyödään he pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Eikö se niin ole? kuka nuhtelee minua valhetteliaksi, ja minun sanani tyhjäksi tekee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Silloin vastasi Bildad Suasta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Hallitus ja pelko on hänen tykönänsä, joka tekee rauhan korkeittensa seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Kuka voi lukea hänen joukkonsa? ja kenen päälle ei paista hänen valkeutensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kuinka on ihminen hurskas Jumalan edessä? eli kuinka vaimon lapsi on puhdas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Katso, kuu ei valaise vielä, eikä tähdet ole vielä kirkkaat hänen silmäinsä edessä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Kuinka paljo vähemmin ihminen, se mato, ja ihmisen lapsi se toukka?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Ketäs autat? sitäkö, jolla ei voimaa ole? autatkos sitä, jolla ei voimaa ole käsivarressa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Ketäs neuvot? sitäkö, joka ei mitään tiedä, ja opetat voimallista toimittamaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Kenen edessä sinä puhut, ja kenen edessä henkes käy ulos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Uljaat huokaavat, niin myös ne, jotka veden alla asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Helvetti on avoinna hänen edessänsä, ja kadotuksella ei ole peitettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Hän venyttää pohjoisen tyhjän päälle, ja maa riippuu tyhjän päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Vedet hän kokoo pilviinsä, ja pilvet ei repee niiden alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Hän pitää istuimensa, ja levittää pilvensä sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Hän on asettanut määrän vetten ympärille, siihenasti kuin valkeus ja pimeys loppuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Taivaan patsaat vapisevat ja hämmästyvät hänen kurituksestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Voimallansa on hän halaissut meren, ja hänen ymmärryksestänsä tyventyy meren ylpeys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Taivas tulee kirkkaaksi hänen ilmansa kautta, ja hän valmistaa kädellänsä pitkän kärmeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Katso, näin tapahtuu hänen tekoinsa kanssa, mutta näistä olemme me vähän kuulleet; vaan kuka voi ymmärtää hänen väkevyytensä jylinän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Ja Job puhui vielä sananlaskunsa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Niin totta kuin Jumala elää, joka minun oikeuteni kieltää, ja Kaikkivaltias, joka minun sieluni murheelliseksi saattaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Niinkauvan kuin minun henkeni on minussa, ja Jumalalta puhallus minun sieraimissani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Ei pidä minun huuleni vääryyttä puhuman, ja minun kieleni ei pidä petosta ottaman eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Pois se minusta, että minä sanoisin teidät hurskaaksi, siihenasti kuin minun loppuni tulee, en minä luovu jumalisuudestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Minun oikeudestani, jonka minä pidän, en minä luovu. Minun omatuntoni ei kalva minua koko elinaikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Mutta minun viholliseni löydetään jumalattomaksi, ja minun vastahakoiseni vääräksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Sillä mikä on ulkokullatun toivo, että hän niin ahne on, koska Jumala ottaa hänen sielunsa pois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Luuletkos Jumalan kuulevan hänen huutoansa, kuin hänelle ahdistus tulee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Kuinka hänellä taitaa olla ilo Kaikkivaltiaalta? ja rukoilla Jumalaa joka aika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Minä opetan teitä Jumalan kädestä, ja mitä Kaikkivaltiaalle kelpaa, en minä salaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Katso, te olette kaikki taitavinanne; miksi siis te senkaltaisia turhia asioita otatte eteenne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Tämä on Jumalalta jumalattoman palkka, ja tyrannein perimys, jonka he Kaikkivaltiaalta saavat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Jos hän saa paljon lapsia, niin ne hukataan miekalla, ja hänen sikiänsä ei ravita leivällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Hänen jälkeenjääneensä pitää haudattaman kuolemaan, ja hänen leskensä ei pidä itkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Jos hän kokoo rahaa niinkuin tuhkaa, ja valmistaa hänellensä vaatteita niinkuin lokaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Niin hänen pitää kyllä valmistaman, mutta hurskas pukee ne yllensä, ja viatoin jakaa rahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Hän rakentaa huoneensa niinkuin toukka, ja niinkuin vartia tekee itsellensä lakan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Rikas kuolee, vaan ei koota: koska joku silmänsä avaa, niin ei häntä enää löydetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Hänen päällensä lankee pelko niinkuin vesi; rajuilma ottaa varkain hänen yöllä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Itätuuli vie hänen pois, että hän hukkuu, ja tuulispää siirtää hänen sialtansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Nämät Jumala hänelle lähettää, ja ei säästä häntä: kaikki pitää hänen kädestänsä puuttuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Hänen tähtensä pitää käsiä paukutettaman ja vihellettämän, kussa hän on ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Hopialla on hänen lähtemisensä, ja kullalla sia, jossa valetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Rauta otetaan maasta, ja kivistä vaski valetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Pimeydelle asetti hän lopun, ja kaiken täydellisyyden hän tutki, niin myös kiven, joka paksussa pimeydessä on, ja kuoleman varjon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Siitä vuotaa senkaltainen osa, että ympäriasuvaiset ei taida siitä jalkaisin käydä ylitse: se tyhjetään ihmisiltä ja vuotaa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Vilja kasvaa maasta, jonka alla se muutetaan niinkuin tuulelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Saphiri löydetään muutamista paikoista, ja maan kokkareita, joissa kultaa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Sitä polkua ei ole yksikään lintu tuntenut, eikä variksen silmä nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Ne ylpiät sikiät ei ole sitä sotkuneet, eikä jalopeura käynyt sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Kädellä kallioon ruvetaan, ja vuoret ylösalaisin kukistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Ojat lasketaan kallioista, ja kaikkein kalliimmatkin näkee silmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Virrat estetään juoksemasta, ja ne ilmoitetaan, mitkä näissä peitetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Mutta kusta taito löydetään, ja kussa on ymmärryksen sia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Ei yksikään ihminen tiedä hänen siaansa, eikä löydeta elävien maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Syvyys sanoo: ei se ole minussa, ja meri sanoo: ei se ole minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Ei hänestä anneta kultaa, eikä hopiaa punnita sen hinnaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Ei Ophirin kulta, eli kalliit Onikin ja Saphirin kivet ole verratut hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Kulta ja kallis kivi ei taideta siihen verrattaa, eikä se taideta vaihetettaa kultaisiin astioihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Ramot ja Gabis ei ole mitään sen suhteen: se pidetään kalliimpana päärlyjä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Topatsi Etiopiasta ei ole siihen verrattava, ja puhtain kulta ei maksa mitään sen suhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Kusta siis taito tulee? ja kussa on ymmärryksen sia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Hän on peitetty kaikkein elävien silmistä, ja salattu taivaan linnuiltakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Kadotus ja kuolema sanovat: me olemme korvillamme kuulleet hänen sanomansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Jumala tietää hänen tiensä, ja hän tuntee hänen siansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Sillä hän katselee maan ääriin, ja näkee kaikki, mitä taivaan alla on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Niin että hän antaa tuulelle hänen painonsa ja vedelle hänen mittansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Koska hän asetti sateelle määrän ja pitkäisen tulen leimauksille hänen tiensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Silloin näki hän sen ja luki sen: hän valmisti sen ja myös tutki sen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Ja sanoi ihmiselle: katso, Herran pelko on taito; ja karttaa pahaa on ymmärrys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Job puhui taas sananlaskunsa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Ah jos minä olisin niinkuin entisinä kuukausina! niinä päivinä, joina Jumala minun kätki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Koska hänen valkeutensa paisti minun pääni päälle, ja minä kävin pimeissä hänen valkeudessansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Niinkuin minä olin nuorena olessani; koska Jumalan salaisuus oli minun majani päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Koska Kaikkivaltias oli vielä minun kanssani, ja minun nuorukaiseni minun ympärilläni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Koska minä pesin minun tieni voilla, ja kallio vuoti minulle öljy-ojat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Koska minä menin kaupunin porteille, ja annoin valmistaa istuimeni kujille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Kuin nuoret näkivät minun, niin he pakenivat, ja vanhat nousivat ja seisoivat minun edessäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Ylimmäiset lakkasivat puhumasta, ja panivat kätensä suunsa päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Ruhtinasten ääni kätkeysi, ja heidän kielensä suun lakeen tarttui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Sillä kenen korva minun kuuli, se kiitti minua onnelliseksi, ja jonka silmä minun näki, se todisti minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Sillä minä autin köyhää, joka huusi, ja orpoa, jolla ei auttajaa ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Niiden siunaus, jotka katoomallansa olivat, tuli minun päälleni; ja minä ilahutin leskein sydämen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Vanhurskaus oli minun pukuni, jonka minä päälleni puin, ja minun oikeuteni oli minulle niinkuin hame ja kaunistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Minä olin sokian silmä ja ontuvan jalka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Minä olin köyhäin isä, ja jonka asiaa en minä ymmärtänyt, sen minä visusti tutkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Minä särjin väärän syömähampaat, ja otin saaliin hänen hampaistansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Minä ajattelin: minä riuduin pesässäni, ja teen päiväni moneksi niinkuin sannan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Minun juureni putkahti veden tykönä, ja kaste pysyi laihoni päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Minun kunniallisuuteni uudistui minun edessäni, ja minun joutseni muuttui uudeksi minun kädessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'He kuulivat minua ja odottivat, ja vaikenivat minun neuvooni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Minun sanani jälkeen ei yksikään enempää puhunut, ja minun puheeni tiukkui heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'He odottivat minua niinkuin sadetta, ja avasivat suunsa niinkuin ehtoosadetta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Jos minä nauroin heidän puoleensa, ei he luottaneet sen päälle, eikä tahtoneet minua murheesen saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Kuin minä tulin heidän kokouksiinsa, niin minun täytyi istua ylimpänä: ja asuin niinkuin kuningas sotaväen keskellä, lohduttaissani murheellisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Nyt minun nuorempani nauravat minua, joiden isiä en minä olisi pannut minun laumani koirain sekaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Joiden voiman minä tyhjänä pidin, jotka ei ijällisiksi tulleet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Ne jotka nälän ja tuskan tähden pakenivat erinänsä korpeen, äsken turmeltuneet ja köyhtyneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Jotka nukulaisia repivät pensasten ympäri; ja katajan juuret olivat heidän ruokansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'He ajettiin ulos, ja huudettiin heitä vastaan niinkuin varasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'He asuivat kauhiain ojain tykönä maan luolissa ja vuorten rotkoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Pensasten keskellä he huusivat, ja ohdakkein sekaan he kokosivat itsensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Turhain ja hyljättyin ihmisten lapset, jotka halvimmat olivat maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Ja nyt minä olen heidän lauluksensa tullut, ja minun täytyy heidän juttunansa olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'He kauhistavat minua, ja erkanevat kauvas minusta; ja ei he häpee sylkeä minun kasvoilleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Sillä hän on minun köyteni päästänyt, ja on nöyryyttänyt minun: He ovat suitset minun edestäni heittäneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Oikialle puolelle nousivat nuorukaiset: He lykkäsivät pois minun jalkani, ja tekivät tien minua kohden, hukuttaaksensa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'He ovat kukistaneet minun polkuni: se oli huokia heille minua vahingoittaa, ilman kenenkään avuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'He ovat tulleet sisälle niinkuin suurten rakoin lävitse, ja ovat sekaseuraisin karaneet sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Pelko on kääntynyt minua vastaan, ja niinkuin tuuli vainonnut minun kunniaani, ja niinkuin pilvi, on minun autuuteni mennyt ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Mutta nyt kääntää minun sieluni itsensä minua vastaan, ja minun murhepäiväni ovat minun käsittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Yöllä minun luuni lävistettiin kaikin paikoin lävitse, ja minun suoneni ei saa lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Suuren voiman kautta minun vaatteeni muutetaan, ja hän on vyöttänyt minun niinkuin hameeni pään lävellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Minä sotkutaan lokaan, ja verrataan tomuun ja tuhkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Jos minä hudan sinun tykös, niin et sinä vastaa minua: jos minä käyn edes, niin et sinä minusta tietävinäs ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Sinä olet muuttunut minulle hirmuiseksi, ja vainoot minua kätes voimalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Sinä nostat minun tuuleen, ja annat minun ajaa sen päällä, ja sulaat minun voimallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Sillä minä tiedän, ettäs annat minun kuolemaan, joka on se huone, joka kaikille eläville on asetettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Ei hän kuitenkaan ojenna kättänsä luutarhaan, eikä he huuda kadotuksestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Minä itkin kovana aikana, ja minun sieluni armahti köyhää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Minä odotin hyvää, ja paha tuli: minä odotin valkeutta, ja pimeys tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Minun sisällykseni kiehuvat lakkaamatta: Murheen aika on minun ennättänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Minä käyn mustettuna, ehkei aurinko minua ruskoittanut: minä nousen kansan seassa ja huudan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Minä olen kärmetten veli, strutsilinnun poikain kumppani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Minun nahkani minun päälläni on mustettunut, ja minun luuni ovat helteestä palaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Minun kanteleeni on muuttunut valitukseksi, ja minun huiluni itkuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Minä olen tehnyt liiton silmäini kanssa, etten minä katsoisi neitseen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Mutta mitä Jumala ylhäältä antaa minulle osaksi ja Kaikkivaltias korkialta perinnöksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Eikö väärän pitäisi näkemän senkaltaista vaivaisuutta, ja pahantekiän senkaltaista surkeutta kärsimän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Eikö hän näe minun teitäni ja lueskele kaikkia minun askeleitani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Olenko minä vaeltanut turhassa menossa, eli minun jalkani kiiruhtaneet petokseen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Punnitkaan hän minua oikialla vaa\'alla, niin Jumala ymmärtää minun vakuuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Jos minun askeleeni ovat poikenneet tieltä, ja minun sydämeni seurannut silmiäni, ja jotakin riippunut minun käsissäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Niin minä kylväisin ja toinen söis, ja minun sikiäni hukkuis juurinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Jos minun sydämeni on vietelty vaimon perään, ja olen väijynyt lähimmäiseni ovella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Niin minun emäntäni häväistäkään muilta, ja muut maatkaan hänen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Sillä se on häpiä ja paha työ tuomarien edessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Sillä se olis tuli joka polttais kadotukseen, ja kaiken minun saatuni peräti hukuttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Jos olen katsonut ylön palveliani eli palkkapiikani oikeuden, riidellessänsä minun kanssani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Mitä minä sitte tekisin kuin Jumala nousee? eli mitä minä vastaisin häntä, kuin hän kostaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Eikö hän ole tehnyt häntä, joka minunkin äitini kohdussa teki? ja on meidät molemmat kohdussa valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Olenko minä kieltänyt tarvitsevaisilta, mitä he minulta ovat pyytäneet, ja antanut leskein silmät heikoksi tulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Olenko minä syönyt palani yksinäni, ettei orpo ole myös siitä syönyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Sillä nuoruudestani olen minä ollut niinkuin isä, ja hamasta äitini kohdusta olen minä mielelläni holhonnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Jos minä olen nähnyt jonkun hukkuvan, ettei hänellä ollut vaatetta, ja sallinut käydä köyhän peittämättä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Jos ei hänen lanteensa ole siunannut minua, kuin hän minun lammasnahoillani lämmitettiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Jos olen nostanut käteni orpoja vastaan, ehkä minä näin minun voimallisena porteissa olevan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Niin kaatukoon minun hartiani lapaluiltani, ja minun käsivarteni särkyköön luinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Sillä Jnmalan rangaistus on minulle vavistukseksi, ja en taida hänen korkeuttansa välttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Olenko minä asettanut kullan turvakseni? ja sanonut puhtaalle kullalle: sinä olet minun uskallukseni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Olenko minä iloinnut tavarani paljoudesta, ja että käteni paljon riistaa koonneet ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Olenko minä katsonut valkeutta, koska se kirkkaasti paisti, ja kuuta, koska se täydellinen oli?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'Onko minun sydämeni salaa minua vietellyt, suuta antamaan kädelleni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'Joka myös vääryys on tuomarien edessä; sillä niin olisin minä kieltänyt Jumalan ylhäältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Olenko minä iloinnut viholliseni vastoinkäymisestä? taikka riemuinnut, että onnettomuus tuli hänen päällensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Sillä en minä antanut minun suuni syntiä tehdä, sadatellakseni hänen sieluansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Eivätkö miehet, jotka minun majassani ovat, sanoisi: jospa emme hänen lihastansa ravittaisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Muukalaisen ei pitänyt yötä ulkona oleman; vaan vaellusväelle avasin minä oveni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Olenko minä niinkuin ihminen peittänyt minun pahuuteni, salatakseni minun vääryyttäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Olenko minä hämmästynyt suurta joukkoa? eli olenko minä sukulaisteni ylönkatsetta peljännyt? ollut ääneti, ja en mennyt ovesta ulos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Kuka antais minulle kuultelian, että Kaikkivaltias kuulis minun pyyntöni, että joku kirjoittais kirjan minun asiastani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Niin minä ottaisin sen hartioilleni, ja sitoisin ympärilleni niinkuin kruunun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Minä ilmoittaisin hänelle minun askeleini luvun, ja niinkuin ruhtinas kantaisin sen edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Jos minun maani huutais minua vastaan, ja sen vaot kaikki ynnä itkisivät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Jos minä olen sen hedelmän maksamatta syönyt, ja tehnyt peltomiesten elämän työlääksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Niin kasvakoon minulle nisuista orjantappuria ja ohrista pahoja ruohoja. Jobin sanat loppuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Niin ne kolme miestä lakkasivat vastaamasta Jobia, että hän piti itsensä hurskaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Mutta Elihu Barakelin poika Busista, Ramin sukukunnasta, vihastui Jobin päälle, että hän piti sielunsa hurskaampana Jumalaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Ja närkästyi kolmen ystävänsä päälle, ettei he mitään vastausta löytäneet, ja kuitenkin tuomitsivat Jobin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Sillä Elihu odotti niinkauvan kuin he puhuivat Jobin kanssa, että he olivat vanhemmat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Kuin Elihu näki, ettei vastausta ollut kolmen miehen suussa, vihastui hän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Ja näin vastasi Elihu Barakelin poika Busista ja sanoi: minä olen nuori, ja te olette vanhat, sentähden minä häpesin ja pelkäsin osoittaa teille minun taitoani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Minä ajattelin: puhukaan vuodet, ja vanhuus osoittakoon taitonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Mutta henki on ihmisessä; ja Kaikkivaltiaan henki tekee hänen ymmärtäväiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Suuret ei ole taitavimmat, eikä vanhat ymmärrä, mikä oikeus on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Sentähden minäkin puhun. Kuulkaat minua: minäkin osoitan tietoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Katso, minä olen odottanut teidän puhuissanne, minä olen ottanut teidän ymmärryksestänne vaarin, siihenasti että te olisitte osanneet oikeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Ja minä olen ottanut teistä vaarin; ja katso, ei ole yksikään teistä Jobia nuhdellen voittanut, eli hänen sanaansa vastata taitanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Ettette sanoisi: me olemme löytäneet taidon; että Jumala on hänen hyljännyt, ja ei yksikään muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Sillä ei hän ole minua vastaan puhunut, enkä minä vastaa häntä niinkuin te puhuitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'He pelkäävät, ja ei taida silleen mitään vastata, eikä mitään puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Että minä olen odottanut, ja ei he taida mitään puhua; vaan he vaikenivat, ja ei enää vastaa mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Niin minä vastaan kuitenkin osani, ja osoitan tietoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Sillä minä olen niin täynnä sanoja, että minun henkeni ahdistaa minun vatsaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Katso, minun vatsani on niinkuin viina, jonka henki ei avattu ole, joka uudet leilit särkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Minun täytyy puhua, että minä saisin henkeni vetää: minun täytyy avata huuleni ja vastata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'En minä muotoa katso, enkä ihmisen mielen perään puhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Sillä en minä tiedä (jos minä niin teen), että minun Luojani tempaa äkisti minun pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Kuule siis, Job, minun puhettani, ja ota vaari kaikista sanoistani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Katso, minä avaan suuni, ja kieleni puhuu minun suussani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Minun sydämeni puhuu oikeuden, ja minun huuleni sanoo puhtaan ymmärryksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Jumalan henki on tehnyt minun, ja KaikkivaItiaan henki on minulle antanut elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Jos taidat, niin vastaa minua; valmista itses, ja tule minun eteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Katso, minä olen Jumalan oma niinkuin sinäkin, ja savesta olen minä myös tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Katso, ei sinun tarvitse hämmästyä minua, ja minun käteni ei ole sinulle raskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Sinä olet puhunut minun korvaini kuullen: sinun ääntäs täytyy minun kuulla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Minä olen puhdas ja ilman laitosta, viatoin ja synnitöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Katso, hän on löytänyt syyn minua vastaan, sentähden pitää hän minun vihollisenansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Hän on pannut minun jalkani jalkapuuhun, ja kätkenyt minun tieni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Katso, juuri siitä minä päätän, ettes ole hurskas; sillä Jumala on suurempi kuin yksikään ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Miksis riitelet hänen kanssansa, ettei hän tee sinulle lukua kaikista töistänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Jos Jumala vihdoin jotakin käskee, ei hän sitä jälistä ajattele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Uninäössä yöllä, kuin uni tulee ihmisten päälle, kuin he makaavat vuoteessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Silloin hän ilmoittaa ihmisten korviin, ja vahvistaa sen heidän nuhtelemisellansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Kääntääksensä ihmistä aivoituksestansa, ja varjellaksensa ylpeydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Hän säästää hänen sieluansa turmeluksesta, ja hänen elämäänsä, ettei se miekkaan lankeaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Ja kurittaa häntä kivulla vuoteessansa, ja kaikki hänen luunsa väkevällä kivulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Ja niin toimittaa hänen kauhistumaan ruokaa, ja hänen mielensä kyylyttämään ravintoa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Että hänen lihansa surkastuu, niin ettei sitä nähdä, ja hänen luunsa särkyvät, niin ettei niitä mielellä katsella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Että hänen sielunsa lähenee turmelusta, ja hänen elämänsä kuolemaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Kuin siis hänen tykönsä tulee enkeli, välimies, joka ainoa on enempi tuhansia, ilmoittamaan sille ihmiselle vanhurskauttansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Ja armahtaa häntä, ja sanoo: pelasta häntä menemästä alas turmelukseen; sillä minä olen löytänyt sovinnon;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Niin hänen lihansa tuorehtii enemmin kuin lapsuudessa ja tulee taas niinkuin nuoruutensa aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Hän rukoilee Jumalaa, joka hänelle osoittaa armon: hän antaa kasvonsa nähdä ilolla, ja maksaa ihmiselle hänen vanhurskautensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Hän tunnustaa ihmiselle ja sanoo: minä olen syntiä tehnyt ja oikeuden vääntänyt; vaan ei se minua auttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Hän pelasti minun sieluni, ettei se tulisi turmelukseen, vaan että minun elämäni näkis valkeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Katso, nämät kaikki tekee Jumala itsekullekin kolme kertaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Tuodaksensa heidän sielunsa jälleen turmeluksesta ja valaistaksensa elävien valkeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Job, ota tästä vaari ja kuule, ole myös ääneti, että minä puhuisin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Mutta jos sinulla on jotakin puhumista, niin vastaa minua. Puhu! sillä minä tahdon, ettäs olisit vanhurskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Jos ei, niin kuule sinä minua, ja ole ääneti; minä opetan sinulle taidon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Ja Elihu vielä sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Te taitavat, kuulkaat minun puhettani, ja te ymmärtäväiset, ottakaat korviinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Sillä korva koettelee puheen, ja suu maistaa ruan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Valitkaamme meillemme oikeus, tietääksemme keskenämme, mikä hyvä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Sillä Job on sanonut: minä olen hurskas, ja Jumala on kieltänyt minulta oikeuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Minun täytyy valhetella, ehkä minulla vielä oikeus olis: minä vaivataan ilman ansiota minun nuoliltani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Kuka on Jobin vertainen, joka irvistystä juo niinkuin vettä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'Ja käy pahantekiäin kanssa tiellä, niin että vaeltaa jumalattomain kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Sillä hän on sanonut: Ei se auta ihmistä, että hän pyytää Jumalalle kelvata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Sentähden, te toimelliset, kuulkaat minua. Pois se, että Jumala olis jumalatoin ja Kaikkivaltias väärä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Sillä hän antaa itsekullekin ihmiselle ansionsa jälkeen, ja maksaa tiensä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Ilman epäilemätä, ei Jumala tuomitse ketään vääryydellä, eikä Kaikkivaltias käännä oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kuka on asettanut ne mitkä maan päällä ovat, ja kuka on pannut koko maanpiirin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Jos hän tahtois, niin hän vois kaikkein hengen ja elämän koota tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Kaikki liha kuolis yhteen, ja ihminen tulis tuhaksi jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Onko sinulla ymmärrystä, niin kuule näitä, ja ota vaari puheeni äänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Taivuttaisko joku sentähden oikeuden, että hän vihaa häntä, ja tahtoisitkos hurskaan ja jalon tuomita jumalattomaksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Pitäiskö sanottaman kuninkaalle: sinä Belial! ja ruhtinaille: te jumalattomat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Joka ei kuitenkaan katso ruhtinain muotoa, eikä pidä eroitusta rikkaan ja köyhän välillä; sillä he ovat kaikki hänen käsialansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Pikaisesti täytyy heidän kuolla vielä puoliyönäkin: kansan täytyy hämmästyä ja hukkua: väkevä voimatoinna otetaan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Sillä hänen silmänsä näkevät jokaisen tien, ja hän katsoo kaikki heidän askeleensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Ei pimiä eikä kuoleman varjo ole siellä, että pahantekiät itsensä siinä salaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Sillä ei ole yhdellekään sallittu, että hän tulis Jumalan kanssa oikeudelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Hän musertaa monta epälukuista tuimaa, ja asettaa muita heidän siaansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Että hän tuntee heidän työnsä, ja kukistaa heitä yöllä, että he muserretaan rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Hän heittää jumalattomat ilmeisesti kokoon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Ettei he häntä seuranneet, ja ei tahtoneet ymmärtää hänen teitänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Että vaivaisten hunto tulis hänen eteensä ja hän kuulis viheliäisten huudon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Jos hän antaa rauhan, kuka tahtoo kadottaa? ja jos hän peittää kasvonsa, kuka taitaa katsoa hänen päällensä, kansan ja ihmisten seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Niin ei hän anna ulkokullatun hallita, kansan lankeemuksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Minä puhun Jumalan edessä, joka sanoo: minä olen säästänyt, en minä turmele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Ellen minä ole osannut, niin opeta sinä minua: jos minä olen tehnyt väärin, niin en minä sitä silleen tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Onko joku, joka vastaa sinun puolestas, koska et sinä tahdo? se on sinun ehdossas, ja ei minun. Jos sinä nyt jotakin tiedät,niin puhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Toimellisten miesten sallin minä kyllä puhua minulleni. Ja taitava mies kuulee minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Mutta Job puhuu tyhmästi, ja hänen puheessansa ei ole ymmärrystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Minun isäni! anna Jobia koeteltaa loppuun asti, että hän kääntää itsensä vääräin ihmisten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Hän on paitsi entisiä syntejänsä vielä nyt pilkannut: anna hänen meidän edessämme lyödyksi tulla, ja sitte hän riidelkään kyllä sanoillansa Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Ja Elihu vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Luuletkos sen oikiaksi, ettäs sanot: minä olen hurskaampi Jumalaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Sillä sinä sanot: mitä siitä hyvää on, mitä se auttaa, jos joku välttää syntiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Minä vastaan sinua sanoilla, ja sinun ystäviäs sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Katso taivaasen ja näe, ja katso pilviin, että ne ovat korkiammat sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Jos sinä syntiä teet, mitäs taidat hänelle tehdä? ja jos sinun pahuutes on suuri, mitäs taidat hänelle tehdä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Ja jos sinä olet hurskas, mitäs taidat hänelle antaa? eli mitä hän ottaa sinun kädestäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Ihmiselle sinun kaltaiselles tekee sinun pahuutes jotakin, ja ihmisen lapselle sinun hurskautes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Ne huutavat, kuin heille paljo väkivaltaa tapahtuu, ja valittavat voimallisten käsivartta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Jotka ei sano: Kussa on Jumala, minun Luojani, joka yöllä tekee virret?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Joka meitä tekee oppineemmaksi eläimiä maan päällä, ja taitavammaksi taivaan lintuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Mutta he valittavat pahain ylpeyttä; ja ei hän kuule heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Sillä ei jumala kuule turhaa, ja Kaikkivaltias ei katso sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Nyt sinä sanot: et sinä näe häntä; mutta tuomio on hänen edessänsä, vaan odota häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Jos ei hänen vihansa niin äkisti kosta, ja ei ole tietävinänsä, että siinä niin monta rikosta on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Sentähden on Job turhaan suunsa avannut ja taitamattomia puheita puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu puhui vielä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Odota vielä vähä, minä osoitan sinulle sen; sillä minulla on vielä nyt jotakin Jumalan puolesta sanomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Minä tuon minun ymmärrykseni kaukaa, ja osoitan, että minun Luojani on hurskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Sillä minun puheessani ei tosin ole petosta, minun ymmärrykseni on vilpitöin sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Katso, Jumala on voimallinen, ei kuitenkaan hän ketään hylkää: Hän on voimallinen sydämensä väestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Jumalatointa ei hän varjele, vaan auttaa köyhää oikeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Ei hän käännä silmiänsä pois hurskaasta: hän on myös kuningasten kanssa istuimella: hän antaa heidän pysyä alinomati, että he korkiaksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Ja ehkä vangit olisivat jalkapuussa, ja sidottuna surkeuden köysillä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Niin hän ilmoittaa heille heidän työnsä ja rikoksensa, että he ovat tehneet väkivaltaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'Ja avaa heidän korvansa kuritukseen, ja sanoo heille, että he kääntyisivät pois vääryydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Jos he kuulevat ja palvelevat häntä, niin he hyvissä päivissä vanhenevat ja ilolla elävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Jos ei he kuule, niin he kaatuvat miekalla, ja hukkuvat ennenkuin he sen havaitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Ulkokullatut kartuttavat vihan: ei he huuda, kuin he vankina ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Niin heidän sielunsa kuolee nuoruudessa, ja heidän elämänsä huorintekiäin seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Mutta vaivaista auttaa hän vaivaisuudessa, ja avaa köyhäin korvan murheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Hän tempaa sinunkin ahdistuksen kidasta avaruuteen, jolla ei pohjaa ole; ja sinun pöydälläs on lepo, täytetty kaikella hyvällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Ja sinä olet täydellisesti havaitseva jumalattoman tuomion; mutta tuomio ja oikeus vahvistaa sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Katso, ettei viha ole vietellyt sinua voimassas, eli suuret lahjat ole kääntäneet sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Luuletkos hänen huolivan jalouttas, kultaa eli jonkun väkevyyttä ja varaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ei sinun tarvitse ikävöidä yötä, karatakses ihmisten päälle siallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Kavahda sinuas, ja älä käännä sinuas vääryyteen, niikuin sinä surkeuden tähden ruvennut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Katso, Jumala on korkia voimassansa: kuka on senkaltainen opettaja kuin hän on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kuka tutkii hänen tiensä? ja kuka sanoo hänelle: sinä teet väärin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Muista, ettäs ylistät hänen töitänsä, niinkuin ihmiset veisaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Sillä kaikki ihmiset sen nähneet ovat: Ihmiset näkevät sen kaukaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Katso, Jumala on suuri, ja emme tiedä sitä: hänen vuosilukunsa ovat arvaamattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Sillä hän tekee veden pieniksi pisaroiksi, ja ajaa pilvensä kokoon sateeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Että pilvet pisaroitsevat ja vuotavat vahvasti ihmisten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Koska hän aikoo hajoittaa pilvensä ja majansa jylinän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Katso, niin hän levittää valkeutensa sen päälle, ja peittää meren syvyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Sillä näillä tuomitsee hän kansan; ja antaa ruokaa runsaasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Hän kätkee valkeuden käsissänsä, ja käskee sen palata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Sen ilmoittaa hänen lähimmäisensä, joka on pitkäisen viha pilvissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Siitä myös hämmästyy minun sydämeni ja vapisee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Kuulkaat visusti hänen vihansa huutoa, ja puhetta, joka hänen suustansa käy ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Hän toimittaa sen oikeuden kaikkein taivasten alla; ja hänen leimauksensa paistaa maan ääristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Senjälkeen kuuluu pitkäisen jylinä, ja se jylisee suurella äänellä; ja koska hänen jylinänsä kuullaan, ei sitä taideta estää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Jumala jylistää pauhinallansa ihmeellisesti, ja tekee suuria ja tutkimattomia töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Hän puhuu lumelle, ja se kohta tulee maan päälle, ja sadekuurolle, ja niin sadekuurolla on voima.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Hänen kädessänsä ovat kaikki ihmiset kätketyt, että kaikki tuntisivat hänen tekonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Metsän pedot pakenevat varjoon ja pysyvät asumapaikoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Etelästä tulee tuulispää ja pohjasta kylmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Jumalan hengestä tulee pakkanen ja ahdistaa laviat vedet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Seijes myös hajoittaa pilvet, ja hänen valkeutensa levittää itsensä pilvien lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Hän kääntää pilvensä kuhunka hän tahtoo, tekemään kaikkia, mitä hän tahtoo maan piirin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Jos se tapahtuu yhdelle sukukunnalle eli maakunnalle, koska hän löydetään laupiaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Kuules näitä Job: seiso ja ota vaari Jumalan ihmeellisistä töistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Tiedätkös, koska Jumala saattaa nämät heidän päällensä, ja koska hän antaa pilviensä valkeuden paistaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Tiedätkös, kuinka pilvet hajoittavat heitänsä? täydellisen viisauden ihmeellisiä töitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Että sinun vaattees lämpeevät, kuin ilma tyventyy etelästä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Levitätkö sinä hänen kanssansa pilviä, jotka vahvat ovat niinkuin valettu peili?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Ilmoita sinä meille, mitä meidän pitäis hänelle sanoman; sillä emme ulotu hänen tykönsä pimeydeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Kuka luettelee hänelle, mitä minä puhun? jos joku puhuu, niin hän niellään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Ei nähdä nyt valkeutta, joka pilvissä leimahtaa; vaan kuin tuuli puhaltaa, niin seijestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Pohjoisesta tulee kulta peljättävän Jumalan kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Mutta Kaikkivaltiasta emme taida löytää, joka on niin suuri voimassa; ja ei hän tarvitse vastata oikeudessansa ja suuressa vanhurskaudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Sentähden täytyy ihmisten häntä peljätä: ja ei hän katso yhtään taitavaa sydämestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Ja Herra vastasi Jobia tuulispäästä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Kuka on se, joka taidossansa niin eksyy ja puhuu niin taitamattomasti?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Vyötä nyt kupees niin kuin mies: Minä kysyn sinulta, opeta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kussas silloin olit, koska minä maan perustin? Ilmoita se, jos sinulla se ymmärrys on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Tiedätkös, kuka hänen määränsä asettanut on? eli kuka on vetänyt ojennusnuoran hänen päällensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Mihinkä ovat hänen jalkansa vajotetut, eli kuka on hänen kulmakivensä laskenut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Kuin aamutähdet ynnä minua kiittivät, ja kaikki Jumalan lapset riemuitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Kuka on sulkenut meren ovinensa, koska se ratkesi ja lähti ulos niinkuin äidin kohdusta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Kuin minä puetin sen pilvillä, ja käärin synkeydellä niinkuin kapaloilla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Kuin minä estin sen paisumisen säädylläni, ja asetin siihen teljen ja ovet eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'Ja sanoin: tähän asti pitää sinun tuleman ja ei edemmäksi: tässä pitää sinun korkiat aaltos asettuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Oletkos eläissäs käskenyt aamulle, ja aamuruskolle osoittanut hänen siansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Käsittää maan ääriä, ja puhdistaa siitä jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Se pitää muutettaman niinkuin sinetin savi; niin että he tulevat niinkuin vaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Ja jumalattomilta otetaan pois heidän valkeutensa, ja ylpeiden käsivarsi rikotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Oletkos tullut meren pohjaan, ja vaeltanut syvyyden jälkiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Onko kuoleman ovet koskaan auvenneet etees, eli oletkos nähnyt kuoleman varjon ovet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Oletkos ymmärtänyt, kuinka leviä maa on? annas kuulla, tiedätkös kaikki nämät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Mikä tie on sinne, kussa valkeus asuu? ja kuka on pimeyden sia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Ettäs saattaisit hänen rajoillensa ja osaisit polut hänen huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Tiesitkös, koska sinä syntyvä olit ja kuinka paljo sinulla päiviä olis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Oletkos siellä ollut, kusta lumi tulee? eli oletkos nähnyt, kusta rakeet tulevat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Jotka minä olen tallella pitänyt murhepäivään asti, sodan ja tappeluksen päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Minkä tien kautta valkeus hajoittaa hänensä, ja itätuuli tuulee maan päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kuka on sadekuurolle jakanut juoksunsa, ja pitkäisen valkialle ja jylinälle hänen tiensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Niin että se sataa senkin maan päälle, jossa ei ketään ole, korvessa, jossa ei yhtään ihmistä ole;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Että se täyttäis erämaan ja korven, ja saattais ruohot vihottamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Onko sateella isää? eli kuka on synnyttänyt kasteen pisarat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Kenen kohdusta jää on tullut? ja kuka on härmän synnyttänyt taivaan alla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Vedet kätkevät itsensä niinkuin kivi, ja syvyydet päältä kiinnitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Taidatkos sitoa Seulaisen siteet, eli päästää Kointähden siteet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Taidatkos tuoda taivaan merkit edes aikanansa, eli johdattaa Otavan lastensa kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Tiedätkös, kuinka taivas hallitaan? eli taidatkos hänen hallituksensa toimittaa maan päällä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Taidatkos korottaa äänes ylös pilviin, että veden paljous sinun peittäis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Taidatkos lähettää pitkäisen leimaukset matkaan menemään ja sanomaan sinulle: tässä me olemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kuka on asettanut taidon salaisuuteen eli kuka on ajatukselle antanut toimen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kuka on niin taitava, että hän pilvet lukea taitaa? ja kuka taitaa tukita vesitydyt taivaassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Kuin tomu kastuu ja juoksee yhteen, ja kokkareet ryhtyvät toinen toiseensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, '(H 39:1) Taidatkos jalopeuralle antaa hänen saaliinsa ajaaksensa takaa? ja ravita nuoret jalopeurat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, '(H 39:2) Niin että he makaavat sioillansa, ja lepäävät luolissansa, joissa he väijyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, '(H 39:3) Kuka valmistaa kaarneelle ruan, kuin hänen poikansa huutavat Jumalaa, ja ei he tietä eksyksissä, kussa heidän ruokansa on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, '(H 39:4) Tiedätkös, koska metsävuohet poikivat, eli oletkos havainnut peurat käyvän tiineenä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, '(H 39:5) Oletkos lukenut heidän kuukautensa, koska ne täydellänsä ovat? eli tiedätkös ajan, koska he poikivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, '(H 39:6) He kumartavat heitänsä poikiessansa, ja ajavat sen pois, josta heillä kipu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, '(H 39:7) Heidän poikansa vahvistuvat ja kasvavat jyvistä: ne menevät ulos, ja ei palaja heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, '(H 39:8) Kuka on metsä-aasin antanut niin vapaana käydä? kuka on metsä-aasin siteen päästänyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, '(H 39:9) Jolle minä olen erämaan huoneeksi antanut ja korven asuinsiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, '(H 39:10) Hän katsoo ylön kaupungin pauhinaa: vartian huutoa ei hän kuule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, '(H 39:11) Hän katsoo vuorella laiduntansa, ja etsii kussa viheriäistä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, '(H 39:12) Luuletkos yksisarvisen palvelevan sinuas, ja makaavan yötä sinun seimelläs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, '(H 39:13) Taidatkos sitoa yksisarvisen vaolle köydellä, niin että hän kiskois ketoa laaksossa sinun perässäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, '(H 39:14) Taidatkos sinus luottaa häneen, ehkä hän paljon voi, ja jättää työs hänen haltuunsa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, '(H 39:15) Uskotkos hänen siemenes kotia tuovan, ja riihees kokoovan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, '(H 39:16) Ovatko riikinkukkoin sulat kauniimmat kuin nälkäkurjen sulat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, '(H 39:17) Joka munansa jättää maahan, ja antaa maan lämpimän hautoa niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, '(H 39:18) Hän unohtaa ne tallattavan,ja että peto kedolla ne rikkois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, '(H 39:19) Hän on niin kova poikiansa vastaan, kuin ei ne hänen olisikaan: Ei hän tottele turhaan työtä tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, '(H 39:20) Sillä Jumala on häneltä taidon ottanut pois, ja ei ole antanut hänelle ymmärrystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, '(H 39:21) Kuin hän ylentää itsensä korkeuteen, nauraa hän hevosta ja miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, '(H 39:22) Taidatkos antaa hevoselle väen, eli taidatkos kaunistaa hänen kaulansa hirnumisella?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, '(H 39:23) Taidatkos peljättää hänen niinkuin heinäsirkan? peljättävä on hänen sieramiensa päristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, '(H 39:24) Hän kaivaa maata kavioillansa, on riemuinen väkevyydessänsä, ja menee sota-aseita vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, '(H 39:25) Hän nauraa pelkoa ja ei hämmästy, eikä pakene miekkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, '(H 39:26) Ehkä vielä viini kalisis häntä vastaan, ja keihäät ja kilvet välkkyisivät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, '(H 39:27) Hän korskuu, pudistelee ja kaivaa maata, ja ei tottele vasikitorven helinää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, '(H 39:28) Kuin vaskitorvi heliästi soi, luihkaa hän: hui, ja haastaa sodan taampaa, niin myös päämiesten huudon ja riemun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, '(H 39:29) Lentääkö haukka sinun ymmärryksestäs, ja hajoittaa siipensä etelään käsin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, '(H 39:30) Lentääkö kotka sinun kädestäs niin korkialle, että hän tekee pesänsä korkeuteen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, '(H 39:31) Hän asuu vuorilla ja yöttelee vuorten kukkuloilla ja vahvoissa paikoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, '(H 39:32) Sieltä hän katsoo ruan perään, ja hänen silmänsä näkevät kauvas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, '(H 39:33) Hänen poikansa särpävät verta; ja kussa raato on, siellä myös hän on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, '(H 39:34) Ja Herra vastasi Jobia ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '(H 39:35) Joka riitelee Kaikkivaltiaan kanssa, eikö hänen pitäis sitä vahvistaman? ja se joka nuhtelee Jumalaa, eikö hänen pitäis vastaaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, '(H 39:36) Job vastasi Herraa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '(H 39:37) Katso, minä olen halpa, mitä minä sinua vastaan? minä lasken käteni suuni päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, '(H 39:38) Minä olen kerran puhunut, en minä enempää vastaa, enkä toiste sitä enää tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, '(H 40:1) Ja Herra vastasi Jobia tuulispäästä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '(H 40:2) Vyötä kupees niinkuin mies: Minä kysyn sinulta, ja vastaa sinä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, '(H 40:3) Pitäiskö sinun minun tuomioni tyhjäksi tekemän, ja minua vääräksi soimaaman, ettäs itse olisit hurskas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, '(H 40:4) Onko sinulla käsivarsi niinkuin Jumalalla? ja taidatkos yhdenkaltaisella äänellä jylistää hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, '(H 40:5) Kaunista sinus suurella kunnialla ja korkeudella: pueta sinus kiitoksella ja kunnialla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, '(H 40:6) Hajoita sinun julmuutes viha, ja katso kaikkia ylpeitä ja nöyryytä heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, '(H 40:7) Katso kaikkia ylpeitä, ja alaspaina heitä, ja kukista jumalattomat paikastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, '(H 40:8) Hautaa heitä kaikkia maahan, ja upota heidän jaloutensa kätköön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, '(H 40:9) Niin minä tunnustan sinun oikian kätes auttavan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, '(H 40:10) Katso nyt Behemotia, jonka minä sinun vierees tehnyt olen, joka syö heiniä niinkuin härkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, '(H 40:11) Katso, hänen väkensä on hänen kupeissansa, ja hänen voimansa hänen vatsansa navassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, '(H 40:12) Hänen häntänsä ojentuu niinkuin sedripuu, ja hänen salaisen kalunsa suonet ovat niinkuin puun oksat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, '(H 40:13) Hänen luunsa ovat vahvat niinkuin vaski, hänen ruotonsa niinkuin rautaiset seipäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, '(H 40:14) Hän on alku Jumalan teistä; joka hänen tehnyt on, hän voittaa hänen miekallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, '(H 40:15) Vuori kantaa hänelle ruohot; ja kaikki pedot leikitsevät siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, '(H 40:16) Hän makaa mielellänsä varjossa, lymyssä kaisloissa ja mudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, '(H 40:17) Pensas peittää hänen varjollansa, ja ojan halavat peittävät hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, '(H 40:18) Katso, koska virta ylöttää häntä, niin ei hän pelkää: hän on rohkia, vaikka Jordan hänen suuhunsa asti kuohuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, '(H 40:19) Hän saavutetaan nähtensä, ja pauloilla pistetään hänen nenänsä lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, '(H 40:20) Taidatkos vetää Leviatanin ongella, ja sitoa hänen kielensä nuoralla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, '(H 40:21) Taidatkos panna ongen hänen sierameensa, ja hänen leukaluunsa pistää naskalilla lävitse?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, '(H 40:22) Luuletkos, että hän sinua paljon rukoilee, ja liehakoitsee sinun edessäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, '(H 40:23) Luuletkos, että hän tekee liiton sinun kanssas, saadakses häntä alinomaiseksi orjakses?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, '(H 40:24) Taidatkos leikitä hänen kanssansa niinkuin linnun kanssa, eli sitoa hänen sinun piikais sekaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, '(H 40:25) Luuletkos hänen kumppaneilta leikattaman, jaettaa kauppamiehille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, '(H 40:26) Taidatkos täyttää koko verkkohuoneen hänen nahallansa, eli kalamiesten kokkoin hänen päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, '(H 40:27) Koska sinä häneen rupeet kädelläs, niin muista, ettäs tulet sotaan, josta et sinä mitään voita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, '(H 40:28) Katso, hänen toivonsa pettää hänen; sillä koska hän hänen näkee, mukeltaneeko hän pois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, '(H 41:1) Ei ole niin rohkiaa, kuin tohtii hänen herättää: kuka siis seisoo minun edessäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, '(H 41:2) Kuka on minulle jotakin ennen antanut, että minä sen hänelle maksaisin? Minun ovat kaikki, mitä kaikkein taivasten alla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, '(H 41:3) Minun täytyy puhua kuinka suuri, kuinka väkevä ja kuinka kaunis hän on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, '(H 41:4) Kuka riisuu hänen vaatteensa? Kuka tohtii ruveta hänen hampaisiinsa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, '(H 41:5) Kuka voi avata hänen leukaluunsa, jotka ovat hirmuiset hänen hammastensa ympäri?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, '(H 41:6) Hänen suomuksensa ovat pulskiat, kiinnitetyt toinen toiseensa, niinkuin sinetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, '(H 41:7) Yksi on kiinni toisessa, niin ettei tuuli pääse lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, '(H 41:8) Ne ovat kiinni toinen toisessansa ja pysyvät yhdessä, ettei heitä taideta eroittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, '(H 41:9) Hänen aivastamisestansa kiiltää valkeus, ja hänen silmänsä ovat niinkuin aamuruskon silmälaudat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, '(H 41:10) Hänen sunstansa käyvät tulisoitot ulos, ja tuliset kipinät sinkoilevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, '(H 41:11) Hänen sieraimistansa käy ulos savu, niinkuin kiehuvasta padasta ja kattilasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, '(H 41:12) Hänen henkensä on niinkuin tulinen hiili, ja hänen suustansa käy liekki ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, '(H 41:13) Hänen kaulansa on vahva; ja se on hänen ilonsa, kuin hän tekee jotakin vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, '(H 41:14) Hänen lihansa jäsenet ovat kiinni toinen toisessansa, ne ovat hänessä kiinni, ettei hän liikuteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, '(H 41:15) Hänen sydämensä on kova niinkuin kivi, ja niin vahva kuin alimmainen myllyn kivi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, '(H 41:16) Kuin hän korottaa itsensä, niin väkevät peljästyvät; kuin hän joutuu edes, niin ei siellä armoa ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '(H 41:17) Jos hänen tykönsä mennään miekalla eli keihäällä, aseilla eli haarniskoilla, niin ei hän itsiänsä liikuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '(H 41:18) Ei hän rautaa tottele enempi kuin kortta, eikä vaskea enempi kuin lahopuuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '(H 41:19) Ei häntä nuolet karkota, ja linkokivet ovat hänelle niinkuin akanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '(H 41:20) Vasara on hänen edssänsä niinkuin korsi; hän pilkkaa liehuvia keihäitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '(H 41:21) Ja hän taitaa maata terävällä kivellä, hän makaa terävällä niinkuin sontatunkiolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '(H 41:22) Hän saattaa syvän meren kiehumaan niinkuin padan, ja liikuttaa yhteen niinkuin voiteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '(H 41:23) Hänen jälkeensä polku valkenee; hän tekee syvyydet sangen harmaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '(H 41:24) Ei ole maalla hänen vertaistansa; hän on tehty pelkäämättömäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '(H 41:25) Hän katsoo kaikki korkiat ylön; hän on kaikkein ylpeiden kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Ja Job vastasi Herraa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Minä tiedän sinun kaikki voivan: ja ei ole sinulta yksikään ajatus peitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Se on turha ihminen, joka ajattelee peittää neuvonsa: sentähden tunnustan minä, että minä taitamattomasti puhunut olen sitä, joka on minun tietoni ylitse ja jota en minä ymmärrä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Niin kuules nyt, anna mimun puhua: minä kysyn sinulta, opeta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Minä olen kuullut sinua tarkoilla korvilla, ja minun silmäni ovat nyt nähneet sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Sentähden pidän minä itseni viallisena, ja kadun tomussa ja tuhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Kuin Herra nämät sanat oli Jobille puhunut, sanoi Herra Eliphaalle Temanilaiselle: minun vihani on julmistunut sinun ja kahden sinun ystäväs päälle; sillä ette ole oikein puhuneet minusta, niinkuin minun palveliani Job.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Niin ottakaat nyt seitsemän mullia ja seitsemän oinasta, ja menkäät palveliani Jobin tykö, ja uhratkaat polttouhria teidän edestänne, ja palveliani Job rukoilkaan teidän edestänne; sillä hänen puoleensa minä katson, niin etten minä tee teille tyhmyytenne jälkeen; sillä ette ole oikein puhuneet minusta, niinkuin minun palveliani Job.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Niin menivät Eliphas Temanilainen, Bildad Suasta ja Zophar Naemasta, ja tekivät niinkuin Herra heille sanonut oli. Ja Herra katsoi Jobin puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Ja Herra käänsi Jobin vankeuden, koska hän rukoili ystäviensä edestä. Ja Herra antoi Jobille kaksi sen vertaa kaikista mitä hänellä ennen ollut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Ja hänen tykönsä tulivat kaikki hänen veljensä, ja kaikki hänen sisarensa, ja kaikki ne jotka hänen ennen tunsivat, ja söivät hänen kanssansa, ja hänen huoneessansa ja käänsivät heitänsä hänen puoleensa, ja lohduttivat häntä kaikesta siitä pahasta, minkä Herra oli antanut tulla hänen päällensä. Ja itsekukin heistä antoi hänelle yhden rahan ja kultarenkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Ja Herra siunasi Jobia sitte enempi kuin ennen, että hän sai neljätoistakymmentä tuhatta lammasta, ja kuusituhatta kamelia, ja tuhannen paria härkiä ja tuhannen aasia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Ja hän sai seitsemän poikaa ja kolme tytärtä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Ja kutsui ensimäisen nimen Jemina, toisen Ketsia ja kolmannen Kerenhapuk.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Ja ei löydetty niin kauniita vaimoja kaikessa maassa, kuin Jobin tyttäret olivat. Ja heidän isänsä antoi heille perimisen heidän veljeinsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Ja Job eli sitte sata ja neljäkymmentä vuotta, niin että hän sai nähdä lapsensa ja lastensa lapset hamaan neljänteen polveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Ja Job kuoli vanhana ja elämästä kyllänsä saaneena');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Autuas on se, joka ei vaella jumalattomain neuvossa, eikä seiso syntisten tiellä, eikä istu kussa pilkkaajat istuvat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Vaan rakastaa Herran lakia, ja ajattelee hänen lakiansa päivät ja yöt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Hän on niinkuin istutettu puu vesiojain tykönä, joka hedelmänsä antaa ajallansa, ja hänen lehtensä ei varise, ja kaikki menestyy, mitä hän tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Mutta jumalattomat ei ole niin, vaan niinkuin akana, jonka tuuli hajoittelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Sentähden ei jumalattomat kestä tuomiota, eikä syntiset vanhurskasten seuraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Sillä Herra tietää vanhurskasten tien; mutta jumalattomain tie hukkuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Miksi pakanat kiukuitsevat, ja kansat turhia ajattelevat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Maan kuninkaat hankitsevat itseänsä, ja päämiehet keskenänsä neuvoa pitävät Herraa ja hänen voideltuansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Katkaiskaamme heidän siteensä, ja heittäkäämme meistä pois heidän köytensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Mutta joka taivaissa asuu, nauraa heitä: Herra pilkkaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Kerran hän puhuu heille vihoissansa, ja hirmuisuudessansa peljättää heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Mutta minä asetin kuninkaani Zioniin, pyhälle vuorelleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Minä tahdon saarnata senkaltaisesta säädystä, josta Herra minulle sanoi: Sinä olet minun poikani, tänäpänä minä sinun synnytin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Ano minulta, niin minä annan pakanat perinnökses ja maailman ääret omakses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Sinun pitää särkemän heitä rautaisella valtikalla, ja niinkuin savisen astian heitä murentaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Nyt te kuninkaat, siis ymmärtäkäät, ja te maan tuomarit, antakaat teitänne kurittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Palvelkaat Herraa pelvossa, ja iloitkaat vavistuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Antakaat suuta pojalle, ettei hän vihastuisi, ja te hukkuisitte tiellä; sillä hänen vihansa syttyy pian. Mutta autuaat ovat kaikki ne, jotka häneen uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Davidin Psalmi, kuin hän pakeni poikaansa Absalomia. (H 3:2) Voi Herra! kuinka monta on minulla vihollista, ja niin usiat karkaavat minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, '(H 3:3) Moni puhuu minun sielustani: ei ole hänellä apua Jumalan tykönä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, '(H 3:4) Mutta sinä, Herra, olet minun kilpeni, joka minun kunniaan saatat, ja minun pääni kohennat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, '(H 3:5) Äänelläni minä huudan Herraa; ja hän kuulee minua pyhästä vuorestansa, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, '(H 3:6) Minä makaan ja nukun: minä herään myös; sillä Herra tukee minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, '(H 3:7) En minä pelkää kymmentätuhatta kansoista, jotka minua piirittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, '(H 3:8) Nouse, Herra, ja auta minua, minun Jumalani! sillä sinä lyöt kaikkia minun vihollisiani poskelle: sinä murennat jumalattomain hampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, '(H 3:9) Herran tykönä apu löydetään: sinun kansas päällä on sinun siunaukses, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Davidin Psalmi, edelläveisaajalle, kanteleilla. (H 4:2) Rukoillessani kuule minua, vanhurskauteni Jumala, joka minua lohdutat ahdistuksessani: ole minulle armollinen, ja kuule rukoukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, '(H 4:3) Te uljaat miehet, kuinka kauvan pitää minun kunniani pilkattaman? miksi te rakastatte turhuutta ja kysytte valhetta? Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, '(H 4:4) Niin tuntekaat, että Herra vie pyhänsä ihmeellisesti: Herra kuulee, kuin minä häntä rukoilen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, '(H 4:5) Jos te vihastutte, niin älkäät syntiä tehkö: puhukaat sydämissänne, teidän vuoteissanne, ja odottakaat, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, '(H 4:6) Uhratkaat vanhurskauden uhria, ja toivokaat Herran päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, '(H 4:7) Moni sanoo: kuka osoittais meille hyvää? Mutta nosta sinä Herra meidän päällemme sinun kasvois paiste.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, '(H 4:8) Sinä ilahutat minun sydämeni; ehkä muilla on jyviä ja viinaa kyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, '(H 4:9) Minä makaan ja lepään juuri rauhassa; sillä sinä Herra yksinäs autat minua turvassa asumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Davidin Psalmi, edelläveisaajalle, perimisestä. (H 5:2) Herra, ota minun sanani korviis, havaitse minun puheeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, '(H 5:3) Ota vaari minun huudostani, minun Kuninkaani ja minun Jumalani; sillä sinua minä rukoilen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, '(H 5:4) Herra kuultele varhain minun ääntäni: varhain hankitsen minä itseni sinun tykös, ja siitä otan vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, '(H 5:5) Sillä et sinä ole se Jumala, jolle jumalatoin meno kelpaa: joka paha on, ei se pysy edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, '(H 5:6) Öykkärit ei pysy sinun silmäis edessä: kaikkia pahantekiöitä sinä vihaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, '(H 5:7) Sinä kadotat valhetteliat: Herra kauhistuu murhaajia ja viekkaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, '(H 5:8) Mutta minä menen sinun huoneeses sinun suuressa laupiudessas, ja kumarran sinun pyhään templiis päin sinun pelvossas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, '(H 5:9) Herra saata minua vanhurskaudessas, minun vihollisteni tähden: ojenna ties minun eteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, '(H 5:10) Sillä heidän suussansa ei ole mitään totuutta, heidän sisällyksensä on sydämen kipu; heidän kitansa on avoin hauta, ja kielellänsä he liehakoitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, '(H 5:11) Nuhtele heitä Jumala, että he lankeisivat ajatuksistansa: syökse heitä ulos heidän suurten ylitsekäymistensä tähden; sillä he ovat sinulle vastahakoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, '(H 5:12) Iloitkaan kaikki, jotka sinuun uskaltavat, anna heidän riemuita ijankaikkisesti; sillä sinä varjelet heitä: iloitkaan sinussa ne, jotka sinun nimeäs rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, '(H 5:13) Sillä sinä Herra siunaat vanhurskaita: sinä kaunistat heitä armollas niinkuin kilvellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Davidin Psalmi, edelläveisaajalle, kahdeksalla kielellä. (H 6:2) Oi Herra, älä rankaise minua vihassas, ja älä minua julmuudessas kurita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, '(H 6:3) Herra, ole minulle armollinen, sillä minä olen heikko: paranna Herra minua, sillä minun luuni ovat peljästyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, '(H 6:4) Ja minun sieluni on sangen kovin hämmästynyt, voi Herra, kuinka kauvan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, '(H 6:5) Käännä sinuas, Herra, ja pelasta sieluni; auta minua sinun hyvyytes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, '(H 6:6) Sillä ei kuolemassa kenkään muista sinua, kuka kiittää sinua tuonelassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, '(H 6:7) Minä olen niin väsynyt huokauksista: minä uitan vuoteeni yli yötä, ja kastan leposiani kyynelilläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, '(H 6:8) Minun muotoni on muuttunut murheesta, ja on vanhentunut; sillä minä ahdistetaan kaikilta puolilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, '(H 6:9) Eritkäät minusta, kaikki pahointekiät; sillä Herra kuulee minun itkuni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, '(H 6:10) Herra kuulee minun rukoukseni: anomiseni Herra ottaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, '(H 6:11) Kaikki minun viholliseni saakoon häpiän, ja suuresti peljättäköön; kääntyköön takaperin, ja nopiasti häväistäköön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Davidin viattomuus, josta hän Herralle veisasi, Kuusin Jeminin pojan sanan tähden: (H 7:2) Sinuun, Herra minun Jumalani, minä uskallan: auta minua kaikista minun vainollisistani, ja pelasta minua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, '(H 7:3) Ettei he repisi minun sieluani niinkuin jalopeura, ja sätkisi ilman holhojaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, '(H 7:4) Herra minun Jumalani, jos minä sen tein ja jos vääryys on minun käsissäni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, '(H 7:5) Jos minä pahalla kostanut olen niille, jotka minun kanssani rauhassa elivät; vaan minä olen niitä pelastanut, jotka ilman syytä minua vihasivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, '(H 7:6) Niin vainotkaan viholliseni minun sieluani ja käsittäköön sen, ja poljeskelkaan maahan elämäni, ja painakaan kunniani tomuun, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, '(H 7:7) Nouse Herra vihassas, korota sinuas ylitse vihollisteni hirmuisuuden, heräjä minun puoleeni; sillä sinä olet käskenyt oikeuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, '(H 7:8) Että kansat kokoontuisivat jälleen sinun tykös; ja tule heidän tähtensä taas ylös,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, '(H 7:9) Herra on kansain tuomari: tuomitse Herra minua vanhurskauteni ja vakuuteni jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, '(H 7:10) Loppukoon jumalattomain pahuus, ja holho vanhurskaita; sillä sinä, vanhurskas Jumala, tutkit sydämet ja munaskuut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, '(H 7:11) Minun kilpeni on Jumalan tykönä, joka vaat sydämet auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, '(H 7:12) Jumala on oikia tuomari; ja Jumala, joka joka päivä uhkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, '(H 7:13) Ellei he palaja, niin hän on miekkansa teroittanut, joutsensa jännittänyt, ja tarkoittaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, '(H 7:14) Ja on pannut sen päälle surmannuolet; hän on valmistanut vasamansa kadottamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, '(H 7:15) Katso, hänellä on pahaa mielessä: hän on onnettomuutta raskas, mutta hän synnyttää puuttumisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, '(H 7:16) Hän kaivoi haudan ja valmisti, ja on kaatunut siihen kuoppaan, jonka hän oli tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, '(H 7:17) Hänen onnettomuutensa pitää hänen päänsä päälle tuleman, ja hänen vääryytensä pitää hänen päänsä laelle lankeeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, '(H 7:18) Minä kiitän Herraa hänen vanhurskautensa tähden, ja kunnioitan ylimmäisen Herran nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Davidin Psalmi, edelläveisaajalle, Gittitin päällä. (H 8:2) Herra meidän Herramme! kuinka ihmeellinen on sinun nimes kaikessa maassa, joka panit kunnias taivasten ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Nuorten lasten ja imeväisten suusta perustit sinä voiman, vihollistes tähden, ettäs vihollisen ja kostajan murentaisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Sillä minä näen taivaat, sinun sormeis teot, kuun ja tähdet, jotka valmistit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Mikä on ihminen, ettäs häntä muistat? eli ihmisen poika, ettäs häntä etsiskelet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Sinä teit hänen vähää vähemmäksi enkeleitä; vaan sinä kaunistat hänen kunnialla ja kaunistuksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Sinä asetat hänen sinun käsitekois herraksi: kaikki olet sinä hänen jalkainsa alle heittänyt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Lampaat ja kaikki karjat, ja myös metsän eläimet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Linnut taivaan alla ja kalat meressä ja mitä meressä vaeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Herra meidän Herramme, kuinka ihmeellinen on sinun nimes kaikessa maassa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Davidin Psalmi, kauniista nuoruudesta, edelläveisaajalle. (H 9:2) Minä kiitän Herraa kaikesta sydämestäni, ja luettelen kaikki sinun ihmees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Minä iloitsen ja riemuitsen sinussa, ja veisaan kiitosta sinun nimelles, sinä kaikkein ylimmäinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Ettäs minun viholliseni olet ajanut takaperin: he lankesivat ja hukkuivat sinun etees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Sillä sinä saatat minun oikeuteni ja asiani toimeen: sinä istuit istuimelle, vanhurskauden tuomari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Sinä nuhtelet pakanoita, ja kadotat jumalattomat: sinä pyyhit heidän nimensä pois aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Vihollisten hävitykset ovat lopetetut ijäisesti, ja kaupungit sinä kukistit heidän muistonsa on heidän kanssansa kadonnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Mutta Herra pysyy ijankaikkisesti: hän on valmistanut istuimensa tuomioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Ja hän tuomitsee maan piirin vanhurskaudessa, ja hallitsee kansat oikein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Ja Herra on köyhän turva: hän on turva hädän aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Sentähden he sinuun toivovat, jotka sinun nimes tuntevat; sillä et sinä niitä hylkää, jotka sinua, Herra, etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Veisatkaat Herralle, joka Zionissa asuu: julistakaat kansoissa hänen tekonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Sillä se joka kostaa verenvikoja, muistaa heitä, eikä unohda köyhäin parkumista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Herra ole minulle armollinen, katso minun ahdistustani niiltä, jotka minua vihaavat, sinä joka ylennät minun surman porteista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Että minä luettelisin kaikki sinun kiitokses Zionin tytärten porteissa, ja iloitsisin sinun avustas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Pakanat ovat vajonneet siihen hautaan, jonka he valmistivat: heidän jalkansa on käsitetty siinä verkossa, jonka he virittivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Niin ymmärretään Herran tekevän oikeuden, koska jumalatoin juuri omissa kättensä töissä käsitetään; se on tutkisteltava asia, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Jospa jumalattomat palajaisivat helvettiin, ja kaikki pakanat, jotka Jumalan unohtavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Sillä ei hän köyhää peräti unohda, ja raadollisten toivo ei huku ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Nouse, Herra, ettei ihminen saisi valtaa: anna kaikki pakanat edessäs tuomittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Herra, anna heille opettaja, että pakanat tuntisivat itsensä ihmisiksi, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Miksis Herra niin kaukana seisot, ja tuskan ajalla sinus peität?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Ylpeydessänsä jumalatoin vainoo köyhää: käsitettäköön he heidän juonissansa, joita he ajattelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Sillä jumalatoin itse kerskaa omaa mielivaltaansa: ahne siunailee itsiänsä, ja vihoittaa Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Jumalatoin on koria ja vihainen, ettei hän ketään tottele: ei hän Jumalaa olevankaan luule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Hänen tiensä menestyvät joka aika, sinun tuomios on kaukana hänestä: hän ylpeilee kaikkein vihollistensa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Sillä hän puhuu sydämessänsä: en minä ikänä kukisteta, ei sukukunnasta sukukuntaan hätää ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Jonka suu on täynnä kirouksia, kavaluutta ja viettelystä, hänen kielensä saattaa vaivan ja työn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Hän istuu ja väijyy kartanoissa, murhataksensa salaa viatointa; hänen silmänsä palaa köyhän puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Hän väijyy salaa niinkuin jalopeura luolassansa, hän väijyy raadollista käsittääksensä, ja hän käsittää hänen, kuin hän tempaa sen verkkoihinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Hän paiskaa ja polkee alas, ja sysää köyhän väkivallalla maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Hän sanoo sydämessänsä: Jumala on hänen unhottanut, ja verhonnut kasvonsa, ei hän ikänä näe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Nouse, Herra! Jumala, ylennä kätes ja älä köyhää unohda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Miksi jumalatoin pilkkaa Jumalaa ja sanoo sydämessänsä: et sinä sitä tottele?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Katso siis; sillä sinä näet tuskat ja surut, se on sinun käsissäs: sinuun köyhä itsensä luottaa, ja sinä olet orpolasten holhoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Särje jumalattoman käsivarsi, ja etsi pahan jumalattomuutta, niin ettei sitä enää löydettäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Herra on kuningas aina ja ijankaikkisesti: pakanain pitää häviämän hänen maastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Köyhäin halauksen sinä, Herra, kuulet: heidän sydämensä sinä vahvistat, että sinun korvas siitä ottaa vaarin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Ettäs oikeuden saatat orvoille ja köyhille, ettei ihminen enää ylpeile heitä vastaan maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Davidin Psalmi, edelläveisaajalle. Herraan minä uskallan: kuinka te sanotte sielulleni, että hän lentäis niinkuin lintu teidän vuoreltanne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Sillä katsos, jumalattomat jännittävät joutsen ja panevat nuolensa jänteelle, salaisesti ampuaksensa hurskaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Sillä he rikkoivat perustuksen: mitä vanhurskas taitaa toimittaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Herra on pyhässä templissänsä, Herran istuin on taivaissa; hänen silmänsä ottavat vaarin, ja hänen silmänsä laudat koettelevat ihmisten lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Herra koettelee vanhurskasta; hänen sielunsa vihaa jumalatointa, ja jotka vääryyttä rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Hän antaa sataa jumalattomain päälle pitkäisen leimauksia, tulta ja tulikiveä, ja antaa heille tuulispäät palkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Sillä Herra on vanhurskas ja rakastaa vanhurskautta, että hänen kasvonsa katsovat oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Davidin Psalmi, edelläveisaajalle, kahdeksalla kielellä. (H 12:2) Auta, Herra; sillä pyhät ovat vähentyneet, ja uskolliset ovat harvat ihmisten lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Jokainen puhuu lähimmäisensä kanssa valhetta: he liehakoitsevat ja opettavat eripuraisuutta sydämistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Katkokoon Herra kaikki ulkokullaiset huulet ja ylpiästi puhuvaiset kielet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Jotka sanovat: meidän kielemme pitää voittaman, meidän tulee puhua: kuka meidän herramme on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Että köyhät hävitetään ja vaivaiset huokaavat, niin minä nyt nousen, sanoo Herra: minä saatan avun, että rohkiasti pitää opetettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Herran puheet ovat kirkkaat, niinkuin selitetty hopia saviastioissa, seitsemän kertaa koeteltu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Sinä Herra, kätke ne, ja varjele meitä tästä suvusta ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Sillä joka paikka on jumalattomia täynnä, koska huonot ihmisten lasten seassa korotetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Davidin Psalmi, edelläveisaajalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Kuinka kauvan sinä Herra peräti tahdot minua unhottaa? kuinka kauvan sinä peität kasvos minusta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Kuinka kauvan minä neuvoa pidän sielussani? ja ahdistetaan sydämessäni joka päivä? kuinka kauvan minun viholliseni yltyy minua vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Katso siis ja kuule minua, Herra minun Jumalani: valista silmäni etten minä koskaan kuolemaan nukkuisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Ettei viholliseni sanoisi: minä voitin hänen, ja minun sortajani iloitsisi, koska minä kompastun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Mutta minä turvaan sinun armoos: minun sydämeni riemuitsee, ettäs niin mielelläs autat: minä veisaan Herralle, että hän minulle niin hyvästi tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Davidin Psalmi, edelläveisaajalle. Tyhmät sanovat sydämessänsä: ei Jumalaa olekaan; ei he mitään kelpaa, ja ovat ilkiät menoissansa; ei ole joka hyvää tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Herra katsoi taivaasta ihmisten lapsia, nähdäksensä, jos joku ymmärtäis eli etsis Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Mutta he ovat kaikki poikenneet pois, ja kaikki ovat kelvottomat: ei ole yksikään, joka hyvää tekee, ei ainoakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Eikö siis kenkään pahointekiöistä sitä havaitse? jotka minun kansaani syövät niinkuin he söisivät leipää; vaan ei he rukoile Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Siellä he kovin pelkäsivät; sillä Jumala on läsnä vanhurskasten sukua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Te häpäisette köyhän neuvon; mutta Jumala on hänen turvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Oi jos apu tulis Israelille Zionista! sillä koska Herra päästää vangitun kansansa, niin Jakob iloitsee ja Israel riemuitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Davidin Psalmi. Herra, kuka asuu sinun majassas? eli kuka on pysyväinen sinun pyhällä vuorellas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Joka vaeltaa ja tekee oikeuden, ja puhuu totuuden sydämestänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Joka ei kielellänsä panettele, eikä lähimmäisellensä mitään pahaa tee, ja ei häpäise lähimmäistänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Joka jumalattomat katsoo ylön, vaan kunnioittaa Jumalaa pelkääväisiä; joka lähimmäisellensä vannoo ja pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Joka ei anna rahaansa korolle, eikä ota lahjoja viatointa vastaan. Joka näin tekee, ei hän horjahda ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Davidin kultainen kappale. Kätke minua Jumala; sillä minä uskallan sinuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Sinä olet Herralle sanonut: sinä olet minun Herrani: minun hyvätyöni ei ole sinun tähtes,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Vaan pyhäin tähden, jotka maan päällä ovat, ja kunniallisten tähden, joissa kaikki minun mielisuosioni on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Mutta jotka toisen jälkeen rientävät, niillä pitää suuri sydämen kipu oleman: en minä uhraa heidän juomauhriansa verestä, enkä mainitse heidän nimiänsä suussani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Mutta Herra on minun tavarani ja osani: sinä tähteelle panet minun perimiseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Arpa lankesi minulle kauniimmissa: minä olen jalon perimisen saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Minä kiitän Herraa, joka minua on neuvonut: niin myös minun munaskuuni ovat yöllä kurittaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Minä pidän aina Herran kasvoini edessä, sillä hän on minun oikialla puolellani, sentähden en minä horju.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Sentähden minun sydämeni reimuitsee ja minun kunniani on iloinen, ja minun lihani lepää toivossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Sillä et sinä hyljää sieluani helvetissä, etkä salli sinun pyhäs näkevän turmelusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Sinä osoitat minulle elämän tien, sinun kasvois edessä on täydellinen ilo, ja riemullinen meno oikialla kädelläs ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Davidin rukous. Kuule, Herra, oikeutta, havaitse minun huutoni, ota vaari minun rukouksestani, joka ei viekkaasta suusta lähde.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Puhu sinä minun asiassani, ja sinun silmäs katsokaan oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Sinä koettelet minun sydämeni, ja etsiskelet sitä yöllä, ja tutkit minua, ja et mitään löydä; minä olen aikonut, ettei minun suuni missäkään riko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Minä varjelen minuni sinun huultes sanoissa, ihmisten töistä, murhaajan tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Hallitse minun käyntöni poluillas, ettei minun askeleeni liukahtaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Minä huudan sinua, ettäs, Jumala, minua kuulisit: kallista korvas minun puoleeni, kuule minun puheeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Osoita ihmeellinen hyvyytes, sinä niiden vapahtaja, jotka sinuun uskaltavat, niitä vastaan, jotka sinun oikiaa kättäs vastaan ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Varjele minua niinkuin silmäterää: suojele minua siipeis varjon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'Jumalattomista, jotka minua hävittävät, vihollisistani, jotka minun sieluuni piirittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Heidän lihavansa yhtä pitävät: he puhuvat suullansa ylpiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Kuhunka me menemme, niin he meitä piirittävät: siihen he silmänsä tarkoittavat meitä kukistaaksensa maahan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Niinkuin jalopeura saalista himoitsee, niinkuin nuori jalopeura, joka luolasta väijyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Nouse, Herra, ennätä hänen kasvonsa, ja polje häntä; vapahda minun sieluni miekallas jumalattomista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Sinun kädelläs ihmisistä, Herra, tämän maailman ihmisistä, joiden osa on tässä elämässä, ja joiden vatsan sinä täytät tavarallas: heidän lapsensa ravitaan, ja he jättävät tähteensä lapsukaisillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Mutta minä saan nähdä sinun kasvos vanhurskaudessa: minä ravitaan herättyäni sinun kuvas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Edelläveisaajalle, Davidin Herran palvelian Psalmi, joka Herralle nämät veisun sanat puhui sinä päivänä, jona Herra hänen vapahti kaikkein vihollistensa käsistä ja Saulin käsistä. (H18:2) Ja hän sanoi: minä rakastan sydämestäni sinua, Herra, minun voimani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Herra, minun kallioni, minun linnani ja minun vapahtajani; minun Jumalani on minun vahani, johon minä turvaan: minun kilpeni, ja minun autuuteni sarvi, ja minun varjelukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Minä kiitän ja avukseni huudan Herraa, niin minä vapahdetaan vihollisistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Sillä kuoleman siteet olivat käärineet minun ympäri, ja Belialin ojat peljättivät minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Helvetin siteet kietoivat minun: kuoleman paulat ennättivät minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Ahdistuksessani minä avukseni huudan Herraa, ja minun Jumalani tykö minä huudan: niin hän kuulee ääneni templistänsä, ja minun huutoni hänen edessänsä tulee hänen korviinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Maa liikkui ja vapisi, ja vuorten perustukset liikkuivat: he värisivät, koska hän vihastui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Savu suitsi hänen sieraimistansa ja kuluttava tuli hänen suustansa, niin että hiilet siitä syttyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Hän notkisti taivaat ja astui alas, ja synkiä pimeys oli hänen jalkainsa alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Hän astui Kerubimin päälle ja lensi, ja hän lensi tuulen sulkain päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Hän pani pimeyden majansa ympärille, ja mustat paksut pilvet, jossa hän lymyssä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Kirkkaudesta hänen edessänsä hajosivat pilvet rakeilla ja leimauksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Ja Herra jylisti taivaissa, Ylimmäinen antoi pauhinansa, rakeilla ja leimauksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Hän ampui nuolensa ja hajoitti heitä: hän iski kovat leimaukset, ja peljätti heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Ja niin ilmestyivät vetten kuljut, ja maan perustukset ilmaantuivat, Herra, sinun kovasta nuhtelemisestas ja sinun sieraimies hengen puhalluksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Hän lähetti korkeudesta ja otti minun, ja veti minun ulos suurista vesistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Hän vapahti minun voimallisista vihollisistani, jotka minua väkevämmät olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Ne ennättivät minun tuskapäivänäni; mutta Herra tuli minun turvakseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Ja hän vei minun lakialle: hän tempasi minun ulos; sillä hän mielistyi minuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Herra maksoi minulle minun vanhurskauteni jälkeen: hän antoi minulle kätteni puhtauden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Sillä minä pidän Herran tiet, ja en ole Jumalaani vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Sillä kaikki hänen oikeutensa ovat silmäini edessä, ja hänen käskyjänsä en minä tyköäni hylkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Vaan olen vakaa hänen edessänsä ja vältän vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Sentähden Herra kostaa minulle vanhurskauteni perästä, kätteni puhtauden jälkeen, silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Pyhäin kanssa sinä pyhä olet, ja toimellisten kanssa toimellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Puhdasten kanssa sinä puhdas olet, ja nurjain kanssa sinä nurja olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Sillä sinä vapahdat ahdistetun kansan, ja korkiat silmät sinä alennat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Sillä minun kynttiläni sinä valaiset; Herra minun Jumalani valaisee minun pimeyteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Sillä sinun kauttas minä sotaväen murran, ja minun Jumalassani karkaan muurin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Jumalan tie on täydellinen. Herran puheet tulella koetellut: hän on kaikkein kilpi, jotka häneen uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Sillä kuka on Jumala, paitsi Herraa? ja kuka on kallio, paitsi Jumalaamme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Jumala vyöttää minun voimalla, ja panee minun tieni viattomaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Hän tekee jalkani niinkuin peurain jalat, ja asettaa minun korkeudelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Hän opettaa käteni sotimaan, ja käsivarteni vaskijoutsea vetämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Ja sinä annoit minulle autuutes kilven, ja sinun oikia kätes vahvistaa minun: ja koskas minun alennat, niin sinä teet minun suureksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Sinä levitit minun askeleeni minun allani, ettei minun kantapääni livistyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Minä ajan vihollisiani takaa ja käsitän heitä, ja en palaja, ennenkuin minä heidät hukutan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Minä runtelen heitä, ettei he taida nousta: heidän täytyy kaatua jalkaini alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Sinä valmistat minun voimalla sotaan: sinä taivutat minun alleni ne, jotka nousevat minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Sinä annat minulle viholliseni kaulan, ja minä kadotan vainoojani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'He huutavat, vaan ei ole auttajaa: Herran tykö, mutta ei hän vastaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Minä survon heitä niinkuin maan tomun tuulen edessä, ja heitän pois niinkuin loan kaduilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Sinä pelastat minua riitaisesta kansasta: sinä asetat minun pakanain pääksi; se kansa, jota en minä tuntenut, palvelee minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Se kuultelee minua kuuliaisilla korvilla: muukalaiset lapset kieltävät minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Muukalaiset lapset vaipuvat ja vapisevat siteissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Herra elää, ja kiitetty olkoon minun kallioni, ja minun autuuteni Jumala olkoon ylistetty!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Jumala, joka minulle koston antaa, ja vaatii kansat minun alleni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Joka minua auttaa vihollisistani: sinä korotat myös minun niistä, jotka karkaavat minua vastaan: sinä pelastat minua väkivaltaisesta miehestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Sentähden minä kiitän sinua, Herra, pakanain seassa, ja veisaan nimelles kiitoksen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Joka suuren autuuden kuninkaallensa osoittaa, ja tekee hyvästi voidellullensa, Davidille, ja hänen siemenellensä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Davidin Psalmi, edelläveisaajalle. (H19:2) Taivaat ilmoittavat Jumalan kunnian, ja vahvuus julistaa hänen kättensä teot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Päivä sanoo päivälle, ja yö ilmoittaa yölle tiedon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Ei ole kieltä eikä puhetta, kussa ei heidän äänensä kuulu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Heidän nuoransa käy ulos kaikkiin maihin, ja heidän puheensa maailman ääreen asti: auringolle hän pani majan heissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Ja hän käy ulos kammiostansa niinkuin ylkä, ja riemuitsee niinkuin sankari tietä juostaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Hän käy ylös taivasten lopulta ja juoksee ympäri hamaan niiden loppuun jälleen; ja ei ole mitään peitetty hänen lämpimänsä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Herran laki on täydellinen ja virvoittaa sielut: Herran todistus on vahva ja tekee yksinkertaiset taitaviksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Herran käskyt ovat oikiat ja ilahuttavat sydämet: Herran käskyt ovat kirkkaat ja valistavat silmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Herran pelko on puhdas ja pysyy ijankaikkisesti: Herran oikeudet ovat todet, kaikki tyynni vanhurskaat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Ne ovat kalliimmat kultaa ja kaikkein parasta kultaa, ja makeammat hunajaa ja mesileipiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Sinun palvelias myös niissä opetetaan: ja joka niitä pitää, hänellä on suuri palkka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Erhetykset kuka ymmärtää? anna minulle anteeksi salaiset rikokset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Varjele myös palvelias ylpeistä, ettei he minua hallitsisi; niin minä olen viatoin ja nuhteetoin suuresta pahasta teosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Kelvatkoon sinulle minun suuni puheet, ja minun sydämeni ajatukset sinun edessäs, Herra, minun vahani ja minun Lunastajani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Davidin Psalmi, edelläveisaajalle. (H20:2) Herra kuulkoon sinua hädässäs, Jakobin Jumalan nimi sinua varjelkoon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Hän lähettäköön sinulle apua pyhästä ja Zionista sinua vahvistakoon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Hän muistakoon kaikki ruokauhris, ja sinun polttouhris olkoon lihavat, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Hän antakoon sinulle, mitä sinun sydämes anoo, ja päättäköön kaikki aivoitukses!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Me kerskaamme sinun avustas, ja meidän Jumalamme nimessä me ylennämme lippumme: Herra täyttäköön kaikki sinun rukoukses!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Nyt minä tunnen Herran voideltuansa auttavan, ja häntä kuulevan pyhästä taivaastansa: hänen oikia kätensä auttaa voimallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Nämät uskaltavat rattaisiin ja oreihin; mutta me muistamme Herran Jumalamme nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'He ovat kukistetut ja langenneet; mutta me nousemme ja pystyällä seisomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Auta Herra! Kuningas meitä kuulkaan, kuin me huudamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Davidin Psalmi, edelläveisaajalle. (H21:2) Herra, Kuningas riemuitsee sinun voimassas: ja kuinka suuresti hän iloitsee avustas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Hänen sydämensä halun sinä annat hänelle, etkä kiellä, mitä hänen suunsa anoo, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Sillä sinä ennätät hänen hyvällä siunauksella: sinä panet kultaisen kruunun hänen päähänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Hän anoi elämää sinulta, niin sinä annoit hänelle pitkän ijän aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Hänellä on suuri kunnia sinun avustas: sinä panet ylistyksen ja kaunistuksen hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Sillä sinä asetat hänen siunaukseksi ijankaikkisesti: sinä ilahutat hänen kasvois edessä ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Sillä Kuningas turvaa Herraan: ja Ylimmäisen laupiudessa ei hän horju.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Sinun kätes löytää kaikki vihollises: sinun oikia kätes löytää ne, jotka sinua kadehtivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Sinä panet heitä niinkuin kuumaan pätsiin sinun vihas aikana: Herra nielee heitä vihassansa, ja tuli syö heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Heidän hedelmänsä sinä kadotat maan päältä, ja heidän siemenensä ihmisten lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Sillä he ajattelivat tehdä sinulle pahaa: he pitivät neuvoa, jota ei he voineet täyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Sillä sinä teet heitä olkapääksi: sinä tarkoitat jänteelläs heidän kasvojansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Herra, ylennä sinuas väkevyydessäs; niin me veisaamme ja kiitämme sinun voimaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Davidin Psalmi, edelläveisaajalle, peurasta, jota varhain väijytään. (H22:2) Minun Jumalani, minun Jumalani! miksis minun hylkäsit? minä parun, vaan minun apuni on kaukana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Minun Jumalani! päivällä minä huudan, ja et sinä vastaa, ja en yölläkään vaikene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Sinä olet pyhä, joka asut Israelin kiitoksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Meidän isämme toivoivat sinuun: ja kuin he toivoivat, niin sinä vapahdit heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Sinua he huusivat, ja vapahdettiin: sinuun he turvasivat, ja ei tulleet häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Mutta minä olen mato ja en ihminen, ihmisten pilkka ja kansan ylönkatse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Kaikki, jotka minun näkevät, häpäisevät minua: he vääristelevät huuliansa ja päätänsä vääntelevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Hän valittaa Herralle, hän vapahtakoon hänen: hän auttakoon häntä, jos hän mielistyy häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Sillä sinä olet minun vetänyt ulos äitini kohdusta: sinä olit minun turvani, ollessani vielä äitini rinnalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Sinun päälles minä olen heitetty äitini kohdusta: sinä olet minun Jumalani hamasta äitini kohdusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Älä ole kaukana minusta; sillä ahdistus on läsnä, ja ei ole auttajaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Suuret mullit ovat minun piirittäneet, lihavat härjät kiertäneet minun ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Kitansa avasivat he minua vastaan, niinkuin raateleva ja kiljuva jalopeura.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Minä olen kaadettu ulos niinkuin vesi, ja luuni ovat kaikki hajoitetut: minun sydämeni on niinkuin salattu vedenvaha ruumiissani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Minun voimani on kuivettunut niinkuin kruusin muru, ja minun kieleni tarttuu suuni lakeen; ja sinä panet minun kuoleman tomuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Sillä koirat ovat minun piirittäneet: julmain parvi saartain lävistänyt kuin jalopeura käteni ja jalkani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Minä lukisin kaikki minun luuni; mutta he katselivat ja näkivät ihastuksensa minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'He jakavat itsellensä minun vaatteeni ja heittävät hameestani arpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Mutta sinä, Herra, älä ole kaukana! minun väkevyyteni, riennä avukseni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Pelasta minun sieluni miekasta, ja ainokaiseni koirilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Vapahda minua jalopeuran suusta, ja päästä minua yksisarvillisista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Minä saarnaan sinun nimeäs veljilleni: minä ylistän sinua seurakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Ylistäkäät Herraa te, jotka häntä pelkäätte: koko Jakobin siemen kunnioittakoon häntä, ja kavahtakoon häntä kaikki Israelin siemen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Sillä ei hän hyljännyt eikä katsonut ylön köyhän raadollisuutta, eikä kääntänyt kasvojansa hänestä pois; vaan kuin se häntä huusi, kuuli hän sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Sinua minä ylistän suuressa seurakunnassa: minä maksan lupaukseni heidän edessänsä, jotka häntä pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Raadolliset syövät ja ravitaan, ja jotka Herraa etsivät, pitää häntä ylistämän: teidän sydämenne pitää elämän ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Kaikki maailman ääret muistakaan ja kääntykään Herran tykö, ja kumartakaan sinun edessäs kaikki pakanain sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Sillä Herralta on valtakunta, ja hän vallitsee pakanoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Kaikki lihavat maan päällä pitää syömän ja kumartaman, hänen edessänsä polviansa notkistaman kaikki, jotka tomussa makaavat ja jotka surussansa elävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Hänen pitää saaman siemenen, joka häntä palvelee: Herrasta pitää ilmoitettaman lasten lapsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'He tulevat ja hänen vanhurskauttansa saarnaavat syntyvälle kansalle, että hän sen tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Davidin Psalmi. Herra on minun paimeneni: ei minulta mitään puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Hän kaitsee minua viheriäisessä niityssä, ja vie minua virvoittavan veden tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Minun sieluni hän virvoittaa: hän vie minun oikialle tielle, nimensä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Ja vaikka minä vaeltaisin pimiässä laaksossa, en minä pelkäisi mitään pahuutta, ettäs olet kanssani: sinun vitsas ja sauvas minun tukevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Sinä valmistat minulle pöydän vihollisteni kohdalle: sinä voitelet minun pääni öljyllä, ja minun maljani on ylitsevuotavainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Hyvyys ja laupius noudattavat minua kaiken elinaikani, ja minä saan asua Herran huoneessa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Davidin Psalmi. Herran on maa, ja kaikki mitkä siinä ovat, maan piiri ja ne jotka sen päällä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Sillä hän on perustanut sen merten päälle, ja virtain päälle sen vahvistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kuka astuu Herran vuorelle? ja kuka taitaa seisoa hänen pyhässä siassansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Jolla viattomat kädet ovat ja on puhdas sydämestä, joka ei halaja turhuutta eikä vanno väärin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Se saa siunauksen Herralta, ja vanhurskauden autuutensa Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Tämä on se sukukunta, joka häntä etsii, joka kysyy sinun kasvojas, Jakob, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Tehkäät portit avaraksi ja ovet maailmassa korkiaksi, kunnian Kuninkaan mennä sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kuka on kunnian Kuningas? se on Herra, väkevä ja voimallinen, Herra voimallinen sodassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Tehkäät portit avaraksi ja ovet maailmassa korkiaksi, kunnian Kuninkaan mennä sisälle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kuka on kunnian Kuningas? se on Herra Zebaot, hän on kunnian Kuningas, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Davidin Psalmi. Sinun tykös, Herra, ylennän minä sieluni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Minun Jumalani! sinuun minä turvaan, älä salli minua häväistä, ettei minun viholliseni iloitsisi minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Sillä ei yksikään tule häpiään, joka sinua odottaa; mutta irralliset pilkkaajat saavat häpiän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Herra, osoita minulle sinun ties, ja opeta minulle sinun polkus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Johdata minua totuudessas, ja opeta minua; sillä sinä olet Jumala, joka minua autat, yli päivää minä odotan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Muista, Herra, laupiuttas ja hyvyyttäs, joka maailman alusta on ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Älä muista nuoruuteni syntejä ja ylitsekäymistäni; mutta muista minua sinun laupiutes jälkeen, sinun hyvyytes tähden, Herra!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Herra on hyvä ja vakaa, sentähden saattaa hän syntiset tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Hän johdattaa oikeudella raadollisen, ja opettaa siveille hänen tiensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Kaikki Herran tiet ovat hyvyys ja totuus niille, jotka hänen liittonsa ja todistuksensa pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Sinun nimes tähden, Herra, ole armollinen minun pahalle teolleni, joka suuri on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kuka on se mies, joka Herraa pelkää? sillä hän opettaa parhaan tien.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Hänen sielunsa asuu hyvyydessä, ja hänen sikiänsä omistaa maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Herran salaisuus on niillä, jotka häntä pelkäävät, ja liittonsa ilmoittaa hän heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Minun silmäni katsovat alati Herraa, sillä hän kirvoittaa minun jalkani verkosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Käännä sinuas minun puoleeni, ja ole minulle armollinen; sillä minä olen yksinäinen ja raadollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Minun sydämeni murheet ovat moninaiset: vie siis minua ulos tuskistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Katsos minun vaivaisuuteni ja raadollisuuteni puoleen, ja anna kaikki minun syntini anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Katsos, kuinka monta vihollista minulla on? ja sulasta kateudesta he minua vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Varjele minun sieluni ja vapahda minua, älä laske minua häpiään; sillä sinuun minä turvaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Vakuus ja oikeus varjelkoon minua; sillä minä odotan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Jumala, vapahda Israel kaikista tuskistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Davidin Psalmi. Tuomitse minua, Herra; sillä minä olen vakuudessani vaeltanut: ja minä toivon Herraan, sentähden en minä livistele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Koettele minua, Herra, ja kiusaa minua: puhdista minun munaskuuni ja sydämeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Sillä sinun hyvyytes on silmäini edessä, ja minä vaellan sinun totuudessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'En minä istu turhain ihmisten seassa, enkä seuraa petollisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Minä vihaan pahain seurakuntaa, enkä istu jumalattomain tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Minä pesen käteni viattomuudessa, ja oleskelen, Herra, alttaris tykönä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Kussa kiitossanan ääni kuullaan, ja kaikki sinun ihmees saarnataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Herra, minä rakastin sinun huonees asuinsiaa ja sitä siaa, jossa sinun kunnias asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Älä tempaa minun sieluani pois syntisten kanssa ja henkeäni verikoirain kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Jotka pahanjuoniset ovat ja mielellänsä lahjoja ottavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mutta minä vaellan viattomuudessani: vapahda minua ja ole minulle armollinen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Minun jalkani käy oikiasti: minä kiitän Herraa seurakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Davidin Psalmi. Herra on minun valistukseni ja autuuteni, ketä minä pelkään? Herra on henkeni väkevyys, ketä minä vapisen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Sentähden, vaikka pahat, vainolliseni ja viholliseni, lähestyvät minun lihaani syömään, täytyy heidän kuintenkin itseänsä loukata ja langeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Ja vaikka sotaväki saartais minua, niin ei sydämeni sentähden pelkäisi; ja jos sota nousis minua vastaan, minä turvaan sittekin häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Yhtä minä Herralta anon, sitä minä pyydän, asuakseni Herran huoneessa kaiken elinaikani: että minä näkisin Herran kauniin jumalanpalveluksen, ja hänen templiänsä etsisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Sillä hän peittää minua majassansa pahana aikana: hän kätkee minun salaiseen majaansa, ja korottaa minun kalliolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Ja hän korottaa nytkin minun pääni vihollisteni ylitse, jotka ympärilläni ovat; niin minä uhraan hänen majassansa kiitosuhria: minä veisaan ja laulan Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Herra, kuule minun ääneni, koska minä huudan: ole minulle armollinen, ja kuultele minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Minun sydämeni sanoo sinulle tämän sinun sanas: etsikäät minun kasvojani! sentähden minä etsin, Herra, sinun kasvojas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Älä peitä kasvojas minulta, ja älä sysää pois palveliaas vihassas; sillä sinä olet minun apuni: älä minua hylkää, älä myös minua anna ylön, minun autuuteni Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Sillä minun isäni ja äitini hylkäsivät minun; mutta Herra korjasi minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Herra, osoita minulle sinun ties, ja johdata minua oikiaa polkua, minun vihollisteni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Älä anna minua vihollisteni tahtoon; sillä väärät todistukset seisovat minua vastaan ja tekevät häpeemättä vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Mutta minä uskon kuitenkin näkeväni Herran hyvyyttä eläväin maalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Odota Herraa, ole hyvässä turvassa, ja hän vahvistaa sinun sydämes: ja odota Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Davidin Psalmi. Koska minä huudan sinua, Herra, uskallukseni, niin älä vaikene minulle; etten, koska sinä vaikenisit minulle, minä tulisi niiden kaltaiseksi, jotka hautaan menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Kuule minun rukoukseni ääni, koska minä huudan sinua, kuin minä nostan käteni sinun pyhää kuorias päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Älä anna minun tulla jumalattomain ja pahointekiäin sekaan, jotka lähimmäistensä kanssa puhuvat ystävällisesti, vaan pahuutta on heidän sydämissänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Anna heille heidän työnsä jälkeen ja heidän pahan menonsa perään: anna heille heidän kättensä töiden perään, maksa heille heidän ansionsa perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Sillä ei he ota vaaria Herran töistä, eikä hänen käsi-aloistansa; sentähden rikkoo hän heitä ja ei rakenna heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Kiitetty olkoon Herra; sillä hän on kuullut minun rukoukseni äänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Herra on minun väkevyyteni ja kilpeni, häneen minun sydämeni toivoo, ja minä olen autettu; ja minun sydämeni riemuitsee, ja minä kiitän häntä veisullani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Herra on heidän väkevyytensä; hän on väkevä, joka voideltuansa auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Auta kansaas ja siunaa perimistäs, ja ravitse heitä ja korota heitä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Davidin Psalmi. Tuokaat Herralle, te väkevät, tuokaat Herralle kunnia ja väkevyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Tuokaat Herralle hänen nimensä kunnia: kumartakaat Herraa pyhässä kaunistuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Herran ääni käy vetten päällä: kunnian Jumala pauhaa, suurten vetten päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Herran ääni käy voimassa: Herran ääni käy suuressa kunniassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Herran ääni särkee sedripuut, ja Herra särkee sedripuut Libanonissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Hän hyppäyttää heitä niinkuin vasikan, sekä Libanonin että Sirionin, niinkuin nuoren yksisarvisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Herran ääni leikkaa niinkuin tulen liekki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Herran ääni häälyttää korven, ja Herra liikuttaa Kadeksen korven.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Herran ääni saattaa peurat poikimaan, ja paljastaa metsät: ja hänen templissänsä pitää koko hänen joukkonsa sanoman hänelle kunnian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Herra istuu vedenpaisumisen päällä: Herra pysyy Kuninkaana ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Herra antaa kansallensa väkevyyden: Herra siunaa kansaansa rauhalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psalmi, veisattava Davidin huoneen vihkimisessä. (H30:2) Minä ylistän sinua, Herra, sillä sinä olet korottanut minua: et myös salli viholliseni iloita minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Herra minun Jumalani, kuin minä huusin sinua, niin sinä teit minun terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Herra, sinä veit sieluni ulos helvetistä: sinä olet minun elävänä pitänyt niiden mennessä kuoppaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Pyhät, veisatkaat kiitosta Herralle, ja kiittäkäät hänen pyhyytensä muistoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Sillä hänen vihansa viipyy silmänräpäyksen, ja hän ihastuu elämästä: ehtoona on itku, mutta aamulla ilo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Mutta minä sanoin myötäkäymisessäni: en minä ikänä kukistu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Sillä sinä, Herra, olet hyvässä tahdossas vuoreni vahvistanut; mutta kuin sinä kasvos peitit, niin minä hämmästyin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Sinua, Herra, minä huudan, ja Herraa minä rukoilen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Mitä hyvää minun veressäni on, kuin minä hautaan alas menen? kiittäneekö tomukin sinua, ja ilmoittaneeko se sinun totuuttas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Herra, kuule, ja ole minulle armollinen: Herra, ole minun auttajani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Sinä olet muuttanut minun valitukseni iloksi: sinä olet riisunut minun säkkini, ja vyötit minun riemulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Että minun kunniani veisais sinulle kiitosta ja ei vaikenisi, Herra minun Jumalani, minä kiitän sinua ijankaikkisesti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Davidin Psalmi edelläveisaajalle. (H31:2) Herra, sinuun minä uskallan, etten minä ikänä häpiään tulisi: vapahda minua sinun vanhurskautes kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Kallista korvas minun puoleeni, auta minua äkisti: ole minulle vahva kallio ja linna minua auttamaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Sillä sinä olet minun kallioni ja minun linnani, ettäs siis sinun nimes tähden minua taluttaisit ja veisit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Ettäs minun kirvottaisit verkosta, jonka he minun eteeni virittivät; sillä sinä olet minun väkevyyteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Sinun käsiis annan minä henkeni, sinä olet minun lunastanut, Herra, sinä totinen Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Minä vihaan niitä, jotka pitävät väärää oppia; mutta minä uskallan Herraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Minä ihastun ja riemuitsen sinun hyvyytes tähden, ettäs katsot minun raadollisuuttani, ja tunnet minun sieluni tuskassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Ja et sinä sulje minua vihollisteni käsiin: sinä asetat minun avaraan paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Herra, ole minulle armollinen, sillä minä ahdistetaan; minun kasvoni ovat muuttuneet murheesta, niin myös minun sieluni ja vatsani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Sillä minun elämäni on kulutettu murheesta, ja minun vuoteni huokauksesta: minun voimani on rauvennut pahain tekoin kautta, ja minun luuni ovat muserretut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Minä olen pilkaksi tullut kaikille vihamiehilleni ja kylällisilleni ylönpalttisesti, ja hämmästykseksi tuttavilleni: jotka minun ulkona näkevät, pakenevat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Minä olen sydämestä unhotettu niinkuin kuollut: minä olen niinkuin rikottu astia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Sillä minä kuulen monen häväistyksen, että jokainen karttaa minua: he pitävät keskenänsä neuvoa minusta, ja tahtovat ottaa minun henkeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Mutta minä toivon sinuun, Herra, ja sanon: sinä olet minun Jumalani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Minun aikani ovat sinun käsissäs: pelasta minua vihollisteni kädestä ja niistä, jotka minua vainoovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Anna kasvos paistaa palvelias päälle: auta minua laupiutes kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Herra, älä minun anna häpiään tulla; sillä sinua minä avuksi huudan: jumalattomat tulkoon häpiään, vaijetkoon helvetissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Tulkoon mykäksi väärät suut, jotka puhuvat vanhurskasta vastaan kovasti ylpeydestä ja ylönkatseesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Kuinka suuri on sinun hyvyytes, jonka panit tallelle niille, jotka sinua pelkäävät! ja jonka niille osoitat, jotka sinuun uskaltavat, ihmisten lasten edessä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Sinä kätket heitä tykönäs salaisesti jokaisen haastosta: sinä peität heitä majassas riiteleväisistä kielistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Herra olkoon kiitetty, että hän on minulle osoittanut ihmeellisen hyvyyden, vahvassa kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Sillä minä sanoin pikaisuudessani: minä olen sinun silmäis edestä sysätty pois: kuitenkin kuulit sinä rukoukseni äänen, koska minä sinun tykös huusin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Rakastakaat Herraa, kaikki hänen pyhänsä; Herra varjelee uskollisia ja runsaasti kostaa niille, jotka ylpeyttä harjoittelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Olkaat hyvässä turvassa, ja hän vahvistaa teidän sydämenne, kaikki jotka Herraa odotatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Davidin opetus. Autuas on se, jonka pahat teot ovat annetut anteeksi ja jonka synnit peitetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Autuas on se ihminen, jolle Herra ei soimaa vääryyttä, jonka hengessä ei vilppiä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Sillä koska minä tahdoin sitä vaieta, musertuivat minun luuni jokapäiväisestä itkustani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Sillä sinun kätes oli yöllä ja päivällä raskas minun päälläni, niin että nesteeni kuivui: niinkuin kesällä kuivuu, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Sentähden minä tunnustan sinun edessäs syntini, ja en peitä pahoja tekojani. Minä sanoin: minä tunnustan Herralle pahat tekoni; niin sinä annoit anteeksi syntini vääryyden, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Tämän tähden pitää kaikkein pyhäin sinua rukoileman oikialla ajalla: sentähden kuin suuret vedenpaisumiset tulevat, ei he niihin ulotu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Sinä olet minun varjelukseni, kätke minua murheesta, että minä pelastettuna sangen riemuisesti kerskaisin, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Minä neuvon sinua ja osoitan sinulle tien, jotas vaellat: minä johdatan sinun silmilläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Älkäät olko niinkuin orhiit ja muulit, joilla ei ymmärrystä ole, joille pitää suitset ja ohjat suuhun pantaman, ellei he lähene sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Jumalattomalla on monta vitsausta; mutta joka Herraan toivoo, hänen hyvyys ympäri piirittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Riemuitkaat teitänne Herrassa, ja olkaat iloiset, te vanhurskaat, ja kerskatkaat, kaikki te yksivakaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Riemuitkaat, te vanhurskaat, Herrassa; vakain pitää häntä kauniisti kiittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Kiittäkäät Herraa kanteleilla, veisatkaat hänelle kiitosta kymmenkielisellä psaltarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Veisatkaat hänelle uusi virsi: veisatkaat jalosti kielten leikissä, helisemisellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Sillä Herran sana on totinen, ja mitä hän lupaa, sen hän vahvana pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Hän rakastaa vanhurskautta ja tuomiota; maa on täynnänsä Herran laupiutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Herran sanalla ovat taivaat tehdyt, ja kaikki heidän joukkonsa hänen suunsa hengellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Hän pitää koossa veden meressä niinkuin roukkiossa, ja kätkee syvyydet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Peljätköön Herraa kaikki maa; häntä peljätköön kaikki maan piirin asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Sillä koska hän sanoo, niin se tapahtuu; jos hän käskee, niin se on tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Herra tekee pakanain neuvot tyhjäksi; hän saattaa kansain ajatukset turhaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Mutta Herran neuvo pysyy ijankaikkisesti, hänen sydämensä ajatukset sukukunnasta sukukuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Autuas on se kansa, jonka Herra on Jumala, se kansa, jonka hän itsellensä on perinnöksi valinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Herra katsoi taivaasta alas, ja näki kaikki ihmisten lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Vahvalta istuimeltansa katsoi hän kaikkia, jotka maan päällä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Hän valmistaa kaikkein heidän sydämensä: hän ymmärtää kaikki heidän työnsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ei kuningasta auta hänen suuri väkensä, eikä sankari vapahdeta suurella voimallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Orhiit ei myös auta; ja heidän suuri väkevyytensä ei pelasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Katso, Herran silmät katsovat niitä, jotka häntä pelkäävät, jotka hänen laupiuteensa toivovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Että hän pelastais heidän sielunsa kuolemasta, ja elättäis heitä nälän aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Meidän sielumme odottaa Herraa, joka on meidän apumme ja kilpemme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Sillä meidän sydämemme iloitsee hänessä, ja me toivomme hänen pyhään nimeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Olkoon sinun laupiutes, Herra, meidän päällämme, niinkuin me sinuun uskallamme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Davidin Psalmi, koska hän muotonsa muutti Abimelekin edessä, joka hänen ajoi pois tyköänsä ja hän meni pois. (H34:2) Minä kiitän Herraa aina: hänen kiitoksensa on alati minun suussani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Minun sieluni kerskaa Herrassa, että raadolliset sen kuulevat ja iloitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Ylistäkäät Herraa minun kanssani, ja korottakaamme ynnä hänen nimeänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Kuin minä Herraa etsin, kuuli hän minun rukoukseni, ja pelasti minun kaikista vavistuksistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Jotka häntä katsovat, ne valaistaan: heidän kasvonsa ei tule häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Kuin raadollinen huusi, kuuli Herra häntä, ja autti hänen kaikista tuskistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Herran enkeli piirittää niitä, jotka häntä pelkäävät, ja pelastaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Maistakaat ja katsokaat, kuinka Herra on suloinen: autuas on se, joka häneen turvaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Peljätkään Herraa kaikki hänen pyhänsä; sillä jotka häntä pelkäävät, ei niiltä mitään puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Nuorten jalopeurain pitää tarvitseman ja isooman; mutta jotka Herraa etsivät, ei heiltä mitään hyvää puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Tulkaat tänne, lapset, kuulkaat minua: Herran pelvon minä teille opetan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kuka on, joka (hyvää) elämää pyytää? ja pitäis mielellänsä hyviä päiviä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Varjele kieles pahuudesta, ja huules vilppiä puhumasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Lakkaa pahasta ja tee hyvää: etsi rauhaa ja noutele häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Herran silmät katsovat vanhurskaita, ja hänen korvansa heidän huutoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Mutta Herran kasvot ovat pahointekiöitä vastaan, hukuttamaan maasta heidän muistoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Kuin (vanhurskaat) huutavat, niin Herra kuulee, ja pelastaa heitä kaikista heidän tuskistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Herra on juuri läsnä niitä, joilla on murheellinen sydän, ja auttaa niitä, joilla on surkia mieli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Vanhurskaalle tapahtuu paljo pahaa; mutta Herra hänen niistä kaikista päästää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Hän kätkee kaikki hänen luunsa, ettei yhtäkään niistä murreta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Pahuus tappaa jumalattoman, ja jotka vanhurskasta vihaavat, ne hukutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Herra lunastaa palveliansa sielut; ja kaikki, jotka häneen toivovat, ei pidä hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Davidin Psalmi. Riitele, Herra, riitaveljeini kanssa: sodi vihollisiani vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Tempaa kilpi ja keihäs, ja nouse minua auttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Sivalla ase ja suojele minua sortajiani vastaan: sano sielulleni: minä olen apus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Häpiään ja pilkkaan tulkoon kaikki, jotka sieluani väijyvät: palatkoon takaperin ja nauruksi tulkoon, jotka minulle pahaa suovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Olkoon he niinkuin akanat tuulessa; ja Herran enkeli sysätköön heitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Heidän tiensä olkaan pimiä ja niljakas; ja Herran enkeli vainotkoon heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Sillä he ovat ilman syytä verkkonsa virittäneet minua kadottaaksensa, ja ilman syytä ovat sielulleni kaivaneet haudan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Tulkoon hänelle vaiva, jota ei hän tiedä, ja verkko, jonka hän viritti, käsittäköön hänen: siihen hän langetkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Mutta minun sieluni iloitkoon Herrassa ja riemuitkaan hänen avustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Kaikki minun luuni sanokaan: Herra, kuka on sinun vertaises? sinä joka päästät nöyrän väkevämmän käsistä, raadollisen ja köyhän raatelialtansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Väärät todistajat astuvat edes, jotka minua niihin soimaavat, joista en mitään tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'He tekevät minulle pahaa hyvästä, minulle mielikarvaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Mutta minä, kuin he sairastivat, puin säkin päälleni, vaivasin itsiäni paastolla, ja rukoilin sydämestäni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Minä käytin itseni kuin he olisivat olleet minun ystäväni ja veljeni: niinkuin se joka äitiänsä murehtii, kävin minä kumarruksissa murhevaatteissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mutta he iloitsevat minun vahingostani ja kokoontuvat: ontuvat myös kokoovat heitänsä havaitsematta minua vastaan, he repivät ja ei lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Ulkokullattuin seassa, jotka leipäkyrsänkin tähden pilkkaavat, kiristävät he hampaitansa minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Herra, kuinka kauvan sinä tätä katselet? Päästä siis sieluni heidän hävityksestänsä, ja yksinäiseni nuorista jalopeuroista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Minä kiitän sinua suuressa seurakunnassa; paljon kansan keskellä minä sinua ylistän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Älä salli niiden iloita minusta, jotka syyttömästi minun viholliseni ovat, eli silmää iskeä, jotka minua ilman syytä vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Sillä ei he puhu ystävällisesti, vaan etsivät vääriä syitä hiljaisia vastaan maan päällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Ja levittävät kitansa avaralta minua vastaan, ja sanovat: niin, niin: sen me mielellämme näemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Herra, sinä sen myös näet, älä siis vaiti ole: Herra, älä kaukana ole minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Herää ja nouse katsomaan minun oikeuttani ja asiatani, minun Jumalani ja Herrani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Herra minun Jumalani, tuomitse minua vanhurskautes jälkeen, ettei he riemuitsisi minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Älä salli heidän sydämissänsä sanoa: niin, niin me tahdomme; ja älä anna heidän sanoa: me olemme hänen nielleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Häväistäköön ja nauruksi joutukoon kaikki, jotka onnettomuudestani iloitsevat: puetettakoon häpiällä ja pilkalla, jotka itsiänsä minusta kerskaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Iloitkaan ja riemuitkaan, jotka minun vanhurskauttani rakastavat, ja sanokaan aina: Herra olkoon suuresti kiitetty, joka suo palveliallensa rauhan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Ja minun kieleni puhuu sinun vanhurskauttas, ja kiittää sinua joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Davidin, Herran palvelian Psalmi, edelläveisaajalle. (H36:2) Se on sydämestäni sanottu jumalattomain menosta: ei he ensinkään Jumalaa pelkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Sillä hän suosittelee itsiänsä silmäinsä edessä, niinkauvan kuin hän löytää pahuutensa, saattaaksensa vihaa matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Hänen suunsa sanat ovat vääryys ja petos; ei hän tahdo enempää ymmärtää, että hän jotakin hyvää tekis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Mutta ajattelee vuoteessansa vahinkoa, ja pysyy vahvasti pahalla tiellä; ja ei he mitään pahaa hylkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Herra, sinun laupiutes ulottuu niin leviältä kuin taivas on, ja sinun totuutes niin avaralta kuin pilvet juoksevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Sinun vanhurskautes on niinkuin Jumalan vuoret, ja sinun oikeutes niinkuin suuri syvyys: Herra, sinä autat sekä ihmiset että eläimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Kuinka kallis on sinun hyvyytes, Jumala! että ihmisten lapset sinun siipeis varjon alle uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'He juopuvat sinun huonees runsaasta tavarasta, ja sinä juotat heitä hekumallas niinkuin virralla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Sillä sinun tykönäs on elävä lähde, ja sinun valkeudessas me näemme valkeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Levitä laupiutes niille, jotka sinun tuntevat, ja sinun vanhurskautes toimellisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Älä salli minua tallattaa ylpeiltä; ja jumalattomain käsi älköön minua kukistako.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Vaan anna pahointekiät siihen langeta, että he syöstäisiin pois, ja ei seisoalla pysyisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Davidin Psalmi. Älä vihastu pahain tähden, ja älä kadehdi pahantekiöitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Sillä niinkuin heinä he pian hakataan pois, ja lakastuvat niinkuin vihoittava ruoho.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Toivo Herraan ja tee hyvää: asu maassa ja elätä itses vakuudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Iloitse Herrassa, ja hän antaa sinulle, mitä sinun sydämes halajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Anna ties Herran haltuun, ja toivo hänen päällensä; kyllä hän sen tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Ja hän tuo edes vanhurskautes niinkuin valkeuden, ja oikeutes niinkuin puolipäivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Tyydy Herraan, ja odota häntä: älä kiivoittele sitä, jonka tie menestyy ja sitä ihmistä, joka vääryyttä tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Lakkaa vihasta ja hylkää tuimuus: älä niin vihastu, ettäs itsekin pahaa teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Sillä pahat hävitetään; mutta Herraa odottavaiset perivät maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Vielä vähä hetki on, niin ei jumalatoin olekaan; ja kuin sinä katsot hänen siaansa, niin hän on poissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Mutta siviät perivät maan, ja iloitsevat suuressa rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Jumalatoin uhkaa vanhurskasta, ja kiristelee hampaitansa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Mutta Herra nauraa häntä; sillä hän näkee hänen päivänsä joutuvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Jumalattomat vetävät miekkansa ja jännittävät joutsensa, kukistaaksensa raadollista ja köyhää, ja teurastaaksensa hurskaita heidän teissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Mutta heidän miekkansa pitää käymän heidän sydämeensä; ja heidän joutsensa pitää särkymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Se vähä, mikä vanhurskaalla on, on parempi kuin monen jumalattoman suuret tavarat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Sillä jumalattoman käsivarsi pitää rikottaman; mutta Herra vahvistaa vanhurskaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Herra tietää hurskasten päivät, ja heidän perimisensä pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Ei he tule häpiään pahalla ajalla; ja nälkävuosina pitää heillä kyllä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Sillä jumalattomat hukkuvat, ja Herran viholliset, ehkä he olisivat niinkuin ihana niitty, niin heidän pitää kuitenkin niinkuin savu katooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Jumalatoin ottaa lainan ja ei maksa; mutta hurskas on laupias ja runsas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Sillä hänen siunattunsa perivät maan; mutta hänen kirottunsa pitää hävitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Herralta senkaltaisen miehen vaellus hallitaan; ja hänen tiensä kelpaa hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Jos hän lankee, niin ei häntä hyljätä; sillä Herra tukee hänen kätensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Minä olin nuori, ja vanhennuin, ja en ikänä nähnyt vanhurskasta hyljätyksi, enkä hänen siemenensä kerjäävän leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Hän on aina laupias, ja lainaa mielellänsä; ja hänen siemenensä on siunattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Vältä pahaa, ja tee hyvää, ja pysy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Sillä Herra rakastaa oikeutta, ja ei hylkää pyhiänsä: ne kätketään ijankaikkisesti; mutta jumalattomain siemen pitää hävitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Hurskaat perivät maan, ja asuvat siinä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Vanhurskaan suu puhuu viisautta, ja hänen kielensä opettaa oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Hänen Jumalansa laki on hänen sydämessänsä; ja ei hänen askeleensa livisty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Jumalatoin väijyy vanhurskasta, ja etsii häntä tappaaksensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Mutta ei Herra jätä häntä hänen käsiinsä, ja ei tuomitse häntä, koska hän tuomitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Odota Herraa, ja kätke hänen tiensä, niin hän sinun korottaa, ettäs perit maan: ja sinä saat nähdä jumalattomat hävitettävän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Minä näin jumalattoman, sangen jalon ja valtiaan, joka levitti itsensä, ja vihotti niinkuin viheriäinen laakeripuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Ja hän meni pois, ja katso ei hän enää ollut; ja minä kysyin häntä, ja ei häntä mistään löydetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Ole viatoin, ja pidä sinus oikein; sillä senkaltaiset viimein menestyvät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Mutta väärät pitää ynnä hukkuman, ja jumalattomat pitää viimein hävitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Mutta Herra auttaa vanhurskaita: hän on heidän väkevyytensä tuskan ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Ja Herra auttaa heitä ja päästää heitä: hän pelastaa heitä jumalattomista ja vapahtaa heitä; sillä he uskalsivat häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Davidin Psalmi muistoksi. (H38:2) Herra, älä rankaise minua vihassas, ja älä kurita minua hirmuisuudessas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Sillä sinun nuoles ovat minuun kiinnitetyt, ja sinun kätes painaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Ei ole terveys minun ruumiissani, sinun uhkauksestas: ja ei ole rauhaa minun luissani, minun synteini tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Sillä minun syntini käyvät pääni ylitse; niinkuin raskas kuorma ovat he ylen raskaaksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Minun haavani haisevat ja mätänevät minun hulluuteni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Minä käyn kymärässä ja kumarruksissa: yli päivää minä käyn murheissani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Sillä minun kupeeni peräti kuivettuvat, ja ei ole mitään tervettä minun ruumiissani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Minä olen ylen paljon runneltu ja lyöty rikki: minä myrisen minun sydämeni kivusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Herra, sinun edessäs on kaikki minun haluni, ja minun huokaukseni ei ole sinulta salattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Minun sydämeni värisee, minun voimani on minusta luopunut, ja minun silmäini valkeus ei ole minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Minun ystäväni ja lähimmäiseni ovat kohdastansa minua vastaan, ja minun omaiseni seisovat kaukana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Jotka minun sieluani etsivät, ne virittelevät paulat minun eteeni, ja jotka minulle pahaa suovat, ne puhuvat sulaa pahuutta, ja petosta joka päivä ajattelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Mutta minun täytyy olla niinkuin kuuron, ja ei mitään kuuleman, ja niinkuin mykän, joka ei avaja suutansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Ja minun täytyy olla niinkuin se, joka ei mitään kuule, ja jonka suussa ei ole vastausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Mutta minä odotan sinua, Herra; sinä, Herra, minun Jumalani, kuultelet minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Sillä minä ajattelen, ettei heidän suinkaan pidä minusta iloitseman: jos minun jalkani kompastuis, niin he kerskaisivat sangen paljon minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Sillä minä olen tehty kärsimään, ja minun kipuni on alati minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Sillä minä julistan pahan tekoni, ja murehdin syntini tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Mutta minun viholliseni elävät ja ovat väkevät: ne ovat suuret, jotka minua syyttömästi vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Ja ne, jotka minulle maksavat pahalla hyvän, asettavat heitänsä minua vastaan, että minä hyvää noudatan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Älä hylkää minua, Herra: minun Jumalani, älä ole kaukana minusta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Riennä minua auttamaan, Herra, minun autuuteni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Davidin Psalmi, Jedutunilta, edelläveisaajalle. (H39:2) Minä olen sanonut: minä tahdon pitää vaarin teistäni, etten minä tekisi syntiä kielelläni: minä hallitsen suuni niinkuin suitsilla, niin kauvan kuin minä näen jumalattoman edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Minä tulin mykäksi, vaikenemisella vaikenin hyvästä; mutta minun murheeni lisääntyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Minun sydämeni on palava minussa, ja kuin minä sitä ajattelen, niin minä sytyn: minä puhun kielelläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Herra, opeta minua ajattelemaan minun loppuani, ja mikä mitta minun elämälläni on, tietääkseni, että minä erkanen täältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Katso, minun päiväni ovat kämmenen leveys tykönäs, ja minun elämäni on niinkuin ei mitään sinun edessäs: kuinka aivan turhat ovat kaikki ihmiset, jotka kuitenkin niin suruttomasti elävät Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Vaan he menevät pois niinkuin varjo, ja tekevät itsellensä hukkaan suuren murheen: he kokoovat ja ei tiedä, kuka sen saa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Ja nyt Herra, mihinkä minä luotan? sinuun minä toivon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Vapahda minua kaikista synneistäni, ja älä anna minun tulla hulluin pilkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Minä vaikenen ja en avaa suutani; kyllä sinä sen teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Käännä sinun rangaistukses pois minusta; sillä minä olen nääntynyt sinun kätes pieksämisestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Koskas jonkun rankaiset synnin tähden, niin hänen kaunistuksensa kulutetaan niinkuin koilta; tosin aivan turhat ovat kaikki ihmiset, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Kuule minun rukoukseni, Herra, ja ota minun huutoni korviis, ja älä vaikene minun kyynelteni tähden; sillä minä olen muukalainen sinun tykönäs ja vieras, niinkuin kaikki minun isäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Luovu minusta, että minä virkoaisin, ennenkuin minä menen pois, ja en silleen tässä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Davidin Psalmi, edelläveisaajalle. (H40:2) Minä hartaasti odotin Herraa: ja hän kallisti itsensä minun tyköni, ja hän kuuli minun huutoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Ja hän veti minun ylös hirmuisesta haudasta ja sontaisesta loasta, ja asetti minun jalkani kalliolle, ja hallitsi minun käymiseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Ja hän antoi minun suuhuni uuden veisun, kiittämään meidän Jumalaamme. Sen pitää monen näkemän, ja pelkäämän Herraa, ja toivoman häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Autuas on se ihminen, joka panee uskalluksensa Herraan, ja ei käänny ylpeiden tykö ja niiden, jotka valheella vaeltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Herra, minun Jumalani, suuret ovat sinun ihmees ja ajatukses, jotka sinä meille osoitat: ei ole mitään sinun vertaas; minä ilmoitan niitä ja sanon, vaikka ne ovat epälukuiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Uhri ja ruokauhri ei sinulle kelpaa, vaan korvat sinä minulle avasit: et sinä tahdo polttouhria eli syntiuhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Silloin minä sanoin: katso, minä tulen: Raamatussa on minusta kirjoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Sinun tahtos, minun Jumalani, teen minä mielelläni; ja sinun lakis on minun sydämessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Minä saarnaan sinun vanhurskauttas suuressa seurakunnassa: katso, en minä anna tukita suutani; Herra, sinä sen tiedät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'En minä salaa vanhurskauttas sydämessäni: minä puhun sinun totuudestas ja autuudestas: en minä peitä laupiuttas ja vakuuttas suuressa seurakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Mutta sinä, Herra, älä käännä laupiuttas minusta pois: sinun laupiutes ja vakuutes aina minua varjelkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Sillä lukemattomat vaivat ovat minun piirittäneet: minun syntini ovat minun ottaneet kiinni, niin etten minä nähdä taida: ne ovat usiammat kuin hiukset päässäni, ja minun sydämeni on minussa vaipunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Kelvatkoon se sinulle, Herra, ettäs minun vapahdat: riennä, Herra, minua auttamaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Hävetköön ja kaikki pilkaksi tulkoon, jotka minun sieluani väijyvät hukataksensa sitä: palatkoon takaperin ja häpiään tulkoon, jotka minulle pahaa suovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Hämmästyköön häpiässänsä, jotka minulle sanovat: niin, niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Iloitkaan ja riemuitkaan kaikki sinussa, jotka sinua etsivät, ja jotka sinun autuuttas rakastavat, sanokaan aina: Herra olkoon korkiasti ylistetty!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Minä olen köyhä ja vaivainen, mutta Herra pitää minusta murheen: sinä olet minun auttajani ja vapahtajani: minun Jumalani, älä viivy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Davidin Psalmi, edelläveisaajalle. (H41:2) Autuas on, joka köyhää holhoo: häntä Herra auttaa pahana päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Herra kätkee hänen ja pitää hänen elävänä, että hän menestyy maan päällä, ja ei hylkää häntä vihollistensa tahtoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Herra virvoittaa häntä tautivuoteessansa: sinä autat hänen kaikesta hänen sairaudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Minä sanoin: Herra, ole minulle armollinen, paranna minun sieluni; sillä minä tein syntiä sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Minun viholliseni puhuivat pahaa minua vastaan: koska hän kuollee ja hänen nimensä kadonnee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Ja kuin he tulevat katselemaan, niin he puhuvat valhetta: heidän sydämensä kokoo vääryyttä; niin he menevät pois ja sitä panettelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Kaikki, jotka minua vihaavat, kuiskuttelevat keskenänsä minua vastaan, ja ajattelevat pahaa minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Paha asia on hänen päällensä tullut; ja koska hän makaa, niin ei hän nouse jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Niin myös minun ystäväni, johon minä uskalsin, joka sai minun leipääni, se tallasi minun jalkainsa alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Mutta sinä, Herra, ole minulle armollinen ja auta minua, niin minä sen heille kostan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Siitä minä ymmärrän, ettäs suot minulle hyvää, ettei viholliseni saa kerskata minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Mutta minua sinä holhot viattomuuteni tähden, ja asetat minun kasvois eteen ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Kiitetty olkoon Herra Israelin Jumala, ijankaikkisesta ijankaikkiseen! Amen, amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Koran lasten opetus, edelläveisaajalle. (H42:2) Niinkuin peura himoitsee tuoretta vettä, niin minun sieluni himoitsee sinua, Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Minun sieluni janoo Jumalaa, elävää Jumalaa: koska minä tulen Jumalan kasvoja näkemään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Minun kyyneleeni ovat minun ruokani päivällä ja yöllä, että joka päivä minulle sanotaan: kussa nyt on Jumalas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Koska minä näitä muistelen, niin minä vuodatan ulos sydämeni itsessäni; sillä minä menisin mielelläni joukon kanssa, ja vaeltaisin heidän kanssansa Jumalan huoneeseen: ihastuksella ja kiitoksella joukon seassa, jotka juhlaa pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Mitäs murehdit, sieluni, ja olet niin levotoin minussa? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän minua auttaa kasvoillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Minun Jumalani! sieluni on murheissansa minussa; sentähden minä muistan sinua Jordanin ja Hermonin maalla, sillä vähällä vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Sinun virtas pauhaavat kovin, niin että yksi syvyys pauhaa tässä ja toinen syvyys siellä: kaikki sinun vesilainees ja aaltos käyvät minun ylitseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Päivällä on Herra luvannut hyvyytensä, ja yöllä minä hänelle veisaan, ja rukoilen elämäni Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Minä sanon Jumalalle minun kalliolleni: miksi sinä olet minun unohtanut? miksi minä käyn niin murheissani, koska minun viholliseni minua ahdistaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Se on niinkuin murha minun luissani, että minun viholliseni häpäisevät minua, koska he jokapäivä sanovat minulle: kussa nyt on Jumalas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Mitäs murehdit, sieluni, ja olet minussa niin levotoin? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän on minun kasvoini apu ja minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Tuomitse minua, Jumala, ja ratkaise minun asiani armotointa kansaa vastaan, ja päästä minua kavaloista ja vääristä ihmisistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Sillä sinä olet minun väkevyyteni Jumala, miksis syökset minun pois? miksis minun annat murheissani käydä, koska vihollinen minua ahdistaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Lähetä valkeutes ja totuutes minua saattamaan, ja tuomaan sinun pyhän vuores tykö ja sinun asumises tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Ja minä kävisin sisälle Jumalan alttarin tykö, sen Jumalan tykö, joka minun iloni ja riemuni on, ja kiittäisin sinua kanteleilla, Jumalani, minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Mitäs murehdit, sieluni, ja olet minussa niin levotoin? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän on minun kasvoini apu ja minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Koran lasten opetus, edelläveisaajalle. (H44:2) Jumala! me olemme korvillamme kuulleet, meidän isämme ovat meille luetelleet, mitäs heidän aikanansa ja muinen tehnyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Sinä olet ajanut pakanat pois kädelläs; mutta heidät sinä olet istuttanut siaan: sinä olet kansat kadottanut, mutta heitä sinä olet levittänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Sillä ei he ole miekallansa maata omistaneet, ja heidän käsivartensa ei auttaneet heitä, vaan sinun oikia kätes ja sinun käsivartes, ja sinun kasvois valkeus; sillä sinä mielistyit heihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Jumala, sinä olet minun kuninkaani, joka autuuden Jakobille lupaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Sinun kauttas me vihollisemme paiskaamme maahan; sinun nimessäs me tallaamme vastaankarkaajamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Sillä en minä luota joutseeni, eikä miekkani auta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Mutta sinä autat meitä vihollisistamme, ja saatat niitä häpiään, jotka meitä vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Jumalasta me kerskaamme joka päivä, ja kiitämme sinun nimeäs ijankaikkisesti, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Miksi sinä nyt sysäät meitä pois, ja annat meidän häpiään tulla, etkä lähde meidän sotajoukkomme kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Sinä annat meidän paeta vihollistemme edessä, että ne raatelisivat meitä, jotka meitä vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Sinä annat meitä syötäviksi niinkuin lampaita, ja hajoitat pakanain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Sinä myit kansas ilman hintaa, ja et mitään siitä ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Sinä panet meitä häpiäksi läsnä-asuvaisillemme, pilkaksi ja nauruksi niille, jotka meidän ympärillämme ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Sinä teet meitä sananlaskuksi pakanain seassa, ja että kansat vääntelevät päätänsä meidän tähtemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Joka päivä on minun häväistykseni minun edessäni; ja minun kasvoini häpiä peittää minun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Että minun pitää pilkkaajia ja laittajia kuuleman, ja viholliset ja tylyt kostajat näkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Nämät kaikki ovat tulleet meidän päällemme; ja emme sentähden ole sinua unhottaneet, emmekä petollisesti sinun liittoas vastaan tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Ja ei meidän sydämemme takaperin kääntynyt, eikä meidän käymisemme poikennut sinun tiestäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Ettäs meitä niin löit rikki lohikärmeiden seassa ja peitit meitä kuoleman varjolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Jos me olisimme meidän Jumalamme nimen unhottaneet, ja meidän kätemme nostaneet vieraalle Jumalalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Eikö Jumala sitä etsisi? vaan hän itse tietää meidän sydämemme pohjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Sillä sinun tähtes me surmataan joka päivä: ja me luetaan teuraslampaiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Herää, Herra, miksis makaat? valvo, ja älä meitä sysää pois kaiketikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Miksis peität kasvos, ja unohdat meidän raadollisuutemme ja ahdistuksemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Sillä meidän sielumme on painettu alas maahan asti: meidän vatsamme riippuu maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Nouse, auta meitä, ja lunasta meitä laupiutes tähden!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Morsiamen opetusvirsi kukkasesta Koran lapsilta edelläveisaajalle. (H45:2) Minun sydämeni ajattelee kauniin laulun: minä veisaan kuninkaasta, minun kieleni on jalon kirjoittajan kynä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Sinä olet kaikkein kaunein ihmisten lasten seassa: armo on vuodatettu sinun huulissas; sentähden siunaa Jumala sinua ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Pane miekkas vyölles, sinä sankari, ja kaunista itses kunniallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Menesty sinun kauneudessas, kiiruhda sinus sanan totuuden, siveyden ja vanhurskauden tähden, niin sinun oikia kätes ihmeellisiä osoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Terävät ovat sinun nuoles, että kansat lankeevat etees maahan, jotka sydämestänsä kuninkaan viholliset ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Jumala, sinun istuimes pysyy aina ja ijankaikkisesti; sinun valtakuntas valtikka on oikeuden valtikka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Sinä rakastit vanhurskautta, ja vihasit jumalatointa menoa: sentähden, oi Jumala, on sinun Jumalas voidellut sinua ilo-öljyllä enempi kuin sinun osaveljes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Kaikki sinun vaattees ovat sula Mirrham, Aloe ja Ketsia. Kuin sinä elephantin luisesta tuvastas lähdet, niin he ilahuttavat sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Sinun kaunistuksessas käyvät kuningasten tyttäret: morsian seisoo oikialla kädelläs sulassa kalliimmassa kullassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Kuule,tytär, katso, ja kallista korvas: unohda kansas ja isäs huone,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Niin kuningas saa halun kauneutees; sillä hän on sinun herras, ja sinun pitää häntä kumartaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Tyron tytär lahjoinensa, rikkaat kansan seassa sinua imartelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Kuninkaan tytär on kokonansa kunniallinen sisältä: hän on kultaisessa vaatteessa puetettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Hän viedään monella tavalla kudotuissa vaatteissa kuninkaan tykö: neitseet, hänen ystävänsä, jotka häntä seuraavat, tuodaan sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Ne viedään ilolla ja riemulla, ja he menevät kuninkaan tupaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Sinun isäis siaan pitää sinun lapsia saaman, jotka asetat päämiehiksi kaikkeen maailmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Minä tahdon muistaa sinun nimeäs sukukunnasta niin sukukuntaan: sentähden pitää kansat sinua kiittämän aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Koran lasten veisu nuoruudesta, edelläveisaajalle. (H46:2) Jumala on meidän turvamme ja väkevyytemme, joka on sangen sovelias apu tuskissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Sentähden emme pelkää, jos vielä maailma hukkuis, ja vuoret keskelle merta vajoisivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Vaikka vielä meri pauhais ja lainehtis, niin että siitä pauhinasta mäet kukistuisivat, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Kuitenkin on Jumalan kaupunki ihana virtoinensa, jossa Korkeimman pyhät asumiset ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Jumala on hänen keskellänsä, sentähden se kyllä pysyy: Jumala auttaa häntä varhain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Pakanain pitää hämmästymän ja valtakunnat lankeeman; ja maa hukkuu, kuin hän äänensä antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Herra Zebaot on meidän kanssamme, Jakobin Jumala on meidän tukemme, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Tulkaat ja katsokaat Herran tekoja, joka maan päällä senkaltaiset hävitykset tekee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Joka hallitsee sodat kaikessa maailmassa, joka joutsen särkee ja rikkoo keihään, ja rattaat tulessa polttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Lakatkaat ja tietäkäät, että minä olen Jumala: minä olen voittava kunnian pakanain seassa ja minä ylennetään maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Herra Zebaot on meidän kanssamme: Jakobin Jumala on meidän tukemme, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Koran lasten Psalmi, edelläveisaajalle. (H47:2) Kaikki kansat, paukuttakaat käsiänne, ja ihastukaat Jumalalle iloisella äänellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Sillä Herra kaikkein korkein on hirmuinen, suuri kuningas koko maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Hän vaatii kansat allemme, ja pakanat meidän jalkaimme alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Hän valitsee meille perimisemme, Jakobin kunnian, jota hän rakastaa, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Jumala astui ylös riemulla, ja Herra helisevällä basunalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Veisatkaat, veisatkaat Jumalalle: veisatkaat, veisatkaat kuninkaallemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Sillä Jumala on koko maan kuningas: veisatkaat hänelle taitavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Jumala on pakanain kuningas: Jumala istuu pyhällä istuimellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Kansain päämiehet ovat kokoontuneet Abrahamin Jumalan kansan tykö; sillä maan edesvastaajat ovat Jumalan: hän on sangen suuresti ylennetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Koran lasten Veisu-Psalmi. (H48:2) Suuri on Herra, ja sangen kiitettävä, meidän Jumalamme kaupungissa, pyhällä vuorellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Zionin vuori on kauniilla paikalla, koko maan ilo, pohjan puolella, suuren kuninkaan kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Jumala on tunnettu huoneessansa, että hän sen varjelia on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Sillä katso, kuninkaat olivat kokoontuneet, ja ynnä menivät ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'He ihmettelivät, kuin he tämän näkivät: he hämmästyivät, ja kiiruhtivat pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Vavistus on heidät siellä käsittänyt, ahdistus niinkuin synnyttäväisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Sinä särjet haahdet meressä itätuulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Niinkuin me kuulimme, niin me sen näemme Herran Zebaotin kaupungissa, meidän Jumalamme kaupungissa: Jumala sen vahvistaa ijankaikkisesti, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Jumala! me odotamme sinun hyvyyttäs sinun templissäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Jumala! niinkuin sinun nimes on, niin myös on sinun kiitokses hamaan maailman ääreen: sinun oikia kätes on täynnä vanhurskautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Riemuitkaan Zionin vuori, ja Juudan tyttäret iloitkaan sinun oikeuttes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Menkäät Zionin ympäri ja piirittäkäät häntä: lukekaat hänen torninsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Turvatkaat hänen muurinsa, vahvistakaat hänen salinsa, että te sitä juttelisitte tulevaisille sukukunnille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Sillä tämä Jumala on meidän Jumalamme aina ja ijankaikkisesti: hän johdattaa meitä kuolemaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Koran lasten Psalmi, edelläveisaajalle. (H49:2) Kuulkaat tätä, kaikki kansat, ottakaat korviinne, kaikki maan asuvaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Sekä yhteinen kansa että herrat, niin rikkaat kuin köyhät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Minun suuni puhuu viisautta, ja minun sydämeni sanoo ymmärryksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Minä tahdon kallistaa korvani vertauksiin, ja minun tapaukseni kanteleella soittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Miksi minun pitäis pelkäämän pahoina päivinä, kuin minun sortajani vääryys käy minua ympäri?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Jotka luottavat tavaroihinsa, ja suuresti kerskaavat paljosta rikkaudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Ei velikään taida ketään lunastaa, eikä Jumalalle ketään sovittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Sillä heidän sielunsa lunastus on ylen kallis, niin että se jää tekemättä ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Vaikka hän vielä kauvankin eläis ja ei näkisi hautaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Sillä hänen täytyy nähdä, että viisasten pitää kuoleman, niin myös tyhmän ja taitamattoman pitää hukkuman, ja pitää vieraille tavaransa jättämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Heidän sydämensä ajatus on, että heidän huoneensa pitää ijankaikkisesti pysymän, ja heidän majansa suvusta sukuun, ja heidän nimensä kuuluisaksi tulemaan maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Mutta ei ihminen taida pysyä kunniassa, vaan verrataan eläimiin, jotka hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Tämä heidän tiensä on sula hulluus; kuitenkin, heidän jälkeentulevaisensa sitä suullansa kiittävät, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'He makaavat helvetissä niinkuin lampaat, kuolema heitä kalvaa; mutta hurskasten pitää varhain heitä hallitseman, ja heidän öykkäyksensä pitää hukkuman, ja heidän täytyy jäädä helvettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Kuitenkin vapahtaa Jumala minun sieluni helvetin vallasta; sillä hän korjasi minun, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Älä sitä tottele, koska joku rikastuu, eli jos hänen huoneensa kunnia suureksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Sillä kuin hän kuolee, niin ei hän mitään myötänsä vie, eikä hänen kunniansa mene alas hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Sillä hän kiittää sieluansa elämästänsä: ja he ylistävät sinua, jos sinä itselles hyvää teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Niin he menevät isäinsä perästä, ja ei saa nähdä ikänä valkeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Koska ihminen on kunniassa, ja ei ole ymmärrystä, niin hän on verrattu eläimiin, jotka hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Asaphin Psalmi. Herra, väkevä Jumala, puhuu, ja kutsuu maailman hamasta auringon koitosta niin laskemiseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Zionista antaa Jumala täydellisen kirkkauden paistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Meidän Jumalamme tulee, ja ei vaikene: kuluttavainen tuli käy hänen edellänsä, ja hänen ympärillänsä väkevä ilma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Hän kutsuu taivaat ylhäältä ja maan, tuomitaksensa kansaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Kootkaat minulle minun pyhäni, jotka liitostani enemmän pitävät kuin uhrista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Ja taivaat pitää hänen vanhurskauttansa ilmoittaman; sillä Jumala on tuomari, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Kuule, kansani! minä tahdon puhua, ja sinun seassas, Israel, todistaa: minä Jumala olen sinun Jumalas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Uhreistas en minä sinua nuhtele; sillä sinun polttouhris ovat alati minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'En minä ota härkiä sinun huoneestas, enkä kauriita navetastas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Sillä kaikki metsän eläimet ovat minun, ja eläimet vuorilla tuhansin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Minä tunnen kaikki linnut vuorten päällä, ja metsän pedot ovat minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Jos minä isoon, en minä sitä sano sinulle; sillä maan piiri on minun, ja kaikki mitä siinä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Luuletkos minun syövän härjän lihaa? ja kauristen verta juovan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Uhraa Jumalalle kiitosuhri, ja maksa Ylimmäiselle lupaukses;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Ja avukses huuda minua hädässäs, niin minä tahdon auttaa sinua, ja sinun pitää kunnioittaman minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mutta jumalattomalle sanoo Jumala: miksi sinä ilmoitat minun säätyjäni? ja otat minun liittoni suulles?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Ettäs kuritusta vihaat, ja heität minun sanani taakses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Koskas varkaan näet, niin sinä juokset hänen kanssansa, ja pidät yhtä huorintekiäin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Sinun suus sallit sinä pahaa puhua, ja kieles saattaa petosta matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Sinä istut ja puhut veljeäs vastaan, äitis poikaa sinä pilkkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Näitä teet, ja minä olen vaiti; niin sinä luulet, että minä olen sinun kaltaises; mutta minä nuhtelen sinua ja asetan näitä silmäis eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Ymmärtäkäät siis näitä te, jotka Jumalan unhotatte; etten minä tempaisi joskus pois, ja ei olisi vapahtajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Joka kiitosta uhraa, se ylistää minua, ja siinä on se tie, että minä osoitan hänelle Jumalan autuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Davidin Psalmi, edelläveisaajalle, (H51:2) Kuin propheta Natan tuli hänen tykönsä, sittekuin hän Batseban tykönä käynyt oli. (H51:3) Jumala, ole minulle armollinen sinun hyvyytes tähden: pyyhi pois minun syntini suuren laupiutes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Pese minua hyvin vääryydestäni, ja puhdista minua synnistäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Sillä minä tunnen pahat tekoni, ja minun syntini on aina edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Sinua, sinua ainoaa vastaan minä syntiä tein, ja pahasti tein sinun edessäs, ettäs olisit oikia sanoissas ja puhdas tuomitessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Katso, minä olen synnissä syntynyt, ja minun äitini on synnissä minun siittänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Katso, sinä halajat totuutta, joka salaudessa on, ja ilmoitat salatun viisauden minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Puhdista minua isopilla, että minä puhdistuisin: pese minua, että minä lumivalkiaksi tulisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Anna minun kuulla iloa ja riemua, että ne luut ihastuisivat, jotka särkenyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Peitä kasvos minun synneistäni, ja pyyhi pois kaikki pahat tekoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Jumala, luo minuun puhdas sydän, ja anna minulle uusi vahva henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Älä heitä minua pois kasvois edestä, ja älä minulta ota pois sinun Pyhää Henkeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Anna minulle taas sinun autuutes ilo, ja sillä hyvällä hengelläs tue minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Minä tahdon väärille opettaa sinun ties, että syntiset tykös palajaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Päästä minua veren vioista, Jumala, minun autuuteni Jumala, että minun kieleni ylistäis sinun vanhurskauttas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Avaa, Herra, minun huuleni, että minun suuni ilmoittais sinun kiitokses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Sillä ei sinulle kelpaa uhri, että minä sen antaisin; ja ei polttouhri sinulle ensinkään kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Ne uhrit, jotka Jumalalle kelpaavat, ovat murheellinen henki: ahdistettua ja särjettyä sydäntä et sinä, Jumala, hylkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Tee Zionille hyvästi sinun armos jälkeen; rakenna Jerusalemin muurit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Silloin sinulle kelpaavat vanhurskauden uhrit, polttouhrit ja muut uhrit: silloin sinun alttarillas härkiä uhrataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Davidin opetus, edelläveisaajalle, (H52:2) Kuin Edomilainen Doeg tuli ja ilmoitti Saulille, ja sanoi hänelle: David on tullut Ahimelekin huoneeseen. (H52:3) Mitäs kerskaat pahuudessas, sinä väkevä? Jumalan laupius pysyy joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Sinun kieles ajattelee vahinkoa ja leikkaa valheellansa niinkuin terävä partaveitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Sinä rakastat enempi pahaa kuin hyvää, ja puhut valhetta pikemmin kuin oikeutta, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Sinä puhut mielelläs kaikkia murhasanoja väärällä kielellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Niin Jumala myös kukistaa sinun ijankaikkisesti: hän murentaa sinun, ja majasta tempaa sinun ulos, ja juurittaa sinun ulos eläväin maalta, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Ja vanhurskasten pitää sen näkemän ja pelkäämän; ja he nauravat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Katso, tämä on se mies, joka ei pitänyt Jumalaa turvanansa, vaan uskalsi suureen rikkauteensa: hän on vahvistunut pahuudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Mutta minä olen niinkuin viheriäinen öljypuu Herran huoneessa: minä uskallan Jumalan laupiuteen aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Minä tahdon sinua kiittää ijankaikkisesti, ettäs sen teit, ja odottaa sinun nimeäs; sillä se on hyvä sinun pyhäis edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Davidin opetus, edelläveisaajalle, Mahelatin päällä. (H53:2) Tyhmät sanovat sydämessänsä: ei Jumalaa olekaan; ei he mitään kelpaa, ja ovat ilkiät menoissansa: ei ole joka hyvää tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Jumala katsoi taivaasta ihmisten lapsia, nähdäksensä, jos joku ymmärtäis, joku Jumalaa etsis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Mutta he ovat kaikki vilpistelleet, ja kaikki ovat kelvottomiksi tulleet: ei ole yksikään, joka hyvää tekee, ei ainoakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Eivätkö pahantekiät sitä huomaitse? jotka minun kansaani syövät, niinkuin he söisivät leipää; vaan ei he Jumalaa avuksensa huuda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Siellä he kovin pelkäsivät, kussa ei mitään peljättävää ollut; sillä Jumala hajoittaa niiden luut, jotka sinua ahdistavat: sinä saatat heitä häpiään, sillä Jumala hylkää heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Oi, jos apu tulis Zionista Israelille! Kuin Jumala vangitun kansansa päästää, niin Jakob iloitsee ja Israel riemuitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Davidin opetus, edelläveisaajalle, kanteleilla, (H54:2) Kuin Siphiläiset tulivat ja sanoivat Saulille: David on lymyttänyt itsensä meidän tykönämme. (H52:3) Auta minua Jumala sinun nimelläs, ja saata minulle oikeus sinun väkevyydelläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Jumala, kuule minun rukoukseni, ota korviis minun suuni sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Sillä muukalaiset karkasivat minua vastaan, ja väkivaltaiset väijyivät minun sieluani: ei he pitäneet Jumalaa silmäinsä edessä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Katso, Jumala auttaa minua: Herra tukee minun sieluani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Hän kostaa minun vihollisteni pahuuden: hajoita ne totuudessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Niin minä mielelläni sinulle uhraan: minä kiitän, Herra, sinun nimeäs, sillä se on hyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Sillä hän on pelastanut minun kaikesta hädästä; ja minun silmäni ovat nähneet minun viholiseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Davidin opetus, edelläveisaajalle, kanteleilla. (H55:2) Jumala, kuule minun rukoukseni, ja älä peitä sinuas minun rukoukseni edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Ota minusta vaari ja kuule minua; että minä surkeasti valitan rukouksissani ja parun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Että vihamies niin huutaa, ja jumalatoin ahdistaa; sillä he kääntävät valheen minun päälleni, ja asettavat itsensä vihassansa minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Minun sydämeni vapisee minussa, ja kuoleman pelko lankesi minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Pelko ja vavistus tulivat minun päälleni, ja kauhistus peitti minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Ja minä sanoin: jospa minulla olisi siivet niinkuin mettisellä, että minä lentäisin, ja (joskus) lepäisin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Katso, niin minä kauvas pakenisin, ja oleskelisin korvessa, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Minä rientäisin, että minä pääsisin tuulen puuskasta ja tuulispäästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Turmele, Herra, ja sekoita heidän kielensä; sillä minä näin väkivallan ja riidan kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'He käyvät sen ympäri päivällä ja yöllä hänen muurinsa päällä: vääryys ja vaiva on sen keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Vääryys on sen keskellä: valhe ja petos ei luovu hänen kaduiltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Sillä jos minun vihamieheni häpäisis minua, sen minä kärsisin: ja jos minun vainoojani nousis minua vastaan, niin minä kätkisin itseni hänen edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Vaan sinä olet minun kumppanini, minun johdattajani ja minun tuttavani:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Me jotka ystävällisesti keskenämme neuvoa pidimme, ja vaelsimme Jumalan huoneesen joukossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Langetkoon kuolema heidän päällensä, ja he menkään elävänä alas helvettiin; sillä sula pahuus on heidän asuinsioissansa heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Mutta minä huudan Jumalan tykö; ja Herra auttaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Ehtoona, aamulla ja puolipäivänä minä valitan ja itken; ja hän kuulee minun ääneni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Hän lunastaa minun sieluni niistä, jotka sotivat minua vastaan, ja saattaa hänelle rauhan; sillä monta on minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Jumala kuulkoon, ja heitä nöyryyttäköön, joka alusta ollut on, Sela! jotka ei paranna heitänsä, eikä pelkää Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'He laskevat kätensä hänen rauhallistensa päälle, ja turmelevat hänen liittonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Heidän suunsa on liukkaampi kuin voi, ja sota on heidän sydämessänsä: heidän sanansa ovat sileämmät kuin öljy, ja ne ovat paljaat miekat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Heitä surus Herran päälle, hän sinusta murheen pitää, ja ei salli vanhurskaan olla kulkiana ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Mutta sinä, Jumala, syökset heitä syvään kuoppaan: murhamiehet ja pettäjät ei pidä tuleman puoli-ikäänsä; vaan minä toivon sinuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Davidin kultainen kappale mykästä mettisestä muukalaisten seassa, kuin Philistealaiset käsittivät hänen Gatissa. (H56:2) Jumala, ole minulle armollinen; sillä ihmiset tahtovat minua niellä ylös: joka päivä he sotivat ja ahdistavat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Minun kadehtiani tahtovat joka päivä minua niellä ylös; sillä moni sotii ylpiästi minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Kuin minä pelkään, niin minä toivon sinuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Jumalassa minä kerskaan hänen sanaansa: Jumalaan minä toivon, en minä pelkää: mitä liha minun tekis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Joka päivä he minun sanojani kääntelevät; kaikki heidän ajatuksensa ovat pahuuteen minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'He pitävät yhtä, ja väijyvät, ja ottavat minun askeleistani vaarin, kuinka he minun sieluni käsittäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Pitäiskö heidän vääryydestänsä pääsemän? Syökse, Jumala, se kansa alas vihassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Sinä olet lukenut minun kulkemukseni: sinä panet minun kyyneleeni leiliis: eikö ne ole sinun kirjassas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Silloin pitää viholliseni kääntämän heitänsä takaperin, sinä päivänä, kuin minä huudan: sen minä tiedän, ettäs minun Jumalani olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Jumalassa minä kerskaan hänen sanaansa: Herrassa minä kerskaan hänen sanaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Jumalaan minä toivon, en minä pelkää: mitä ihminen tekis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Minä olen sinulle, Jumala, luvannut, minä tahdon sinua kiittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Sillä sinä olet pelastanut minun sieluni kuolemasta, minun jalkani lankeemisesta; että minä vaeltaisin Jumalan edessä eläväin valkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Davidin kultainen kappale, edelläveisaajalle, ettei hän hukkunut, kuin hän Saulin edestä pakeni luolaan. (H57:2) Jumala, ole minulle armollinen, ole minulle armollinen; sillä sinuun minun sieluni uskaltaa, ja sinun siipeis varjon alle minä turvaan siihenasti, että ahdistukset ohitse käyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Minä huudan korkeimman Jumalan tykö, sen Jumalan tykö, joka minun vaivani päälle lopun tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Hän lähettää taivaasta, ja varjelee minua, ja antaa ne häpiään tulla, jotka minua tahtovat niellä ylös, Sela! lähettäköön Jumala armonsa ja totuutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Minun sieluni makaa jalopeurain keskellä, jotka ovat niinkuin tulen liekki; ihmisten lapset, joiden hampaat ovat keihäs ja nuolet, ja heidän kielensä terävä miekka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Korota itses, Jumala, taivasten ylitse ja sinun kunnias ylitse kaiken maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Verkon he virittivät minun käymiseni eteen, ja minun sieluni vältti: kuopan he kaivoivat minun eteeni, ja siihen he itse lankesivat, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Valmis on sydämeni, Jumala, valmis on sydämeni veisaamaan ja kiittämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Herää kunniani, herää psaltari ja kantele, varhain minä tahdon herätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Herra, sinua minä tahdon kiittää kansain seassa, ja veisata pakanain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Sillä sinun armos on suuri hamaan taivaisiin asti, ja sinun totuutes pilviin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Korota itses, Jumala, taivasten ylitse, ja sinun kunnias ylitse kaiken maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Davidin kultainen kappale, edelläveisaajalle, ettei hän hukkunut. (H58:2) Oletteko te juuri niin mykät, ettette puhu sitä mikä oikeus on, ettekä tuomitse, mikä kohtuus on, te ihmisten lapset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Sydämestänne te myös vääryyttä teette, ja maakunnassa käsillänne väkivaltaa toimitatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Jumalattomat ovat kääntyneet pois jo äitinsä kohdusta, valhetteliat ovat eksyneet hamasta äitinsä kohdusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Heidän kiukkunsa on niinkuin kärmeen kiukku, niinkuin kuuron kyykärmeen, joka korvansa tukitsee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Ettei hän kuulisi lumojain ääntä, sen joka viisaasti lumota taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Jumala, särje heidän hampaansa heidän suuhunsa: murenna, Herra, nuorten jalopeurain syömähampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Heidän pitää sulaman niinkuin vesi: he ampuvat nuolillansa, mutta ne käyvät rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'He hukkuvat, niinkuin näkin kota raukee, niinkuin vaimon keskeneräinen, eikä saa nähdä aurinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Ennenkuin teidän orjantappuranne puuksi kasvavat, niin pitää vihan heitä elävänä repäisemän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Vanhurskaan pitää iloitseman, koska hän koston näkee, ja pesemän jalkansa jumalattoman veressä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Että jokaisen pitää sanoman: vanhurskaalla on kuitenkin hedelmä; Jumala on kuitenkin se, joka tuomitsee maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Davidin kultainen kappale, ettei hän hukkunut, kuin Saul lähetti hänen huonettansa piirittämään, saadaksensa häntä tappaa. (H59:2) Pelasta minua vihollisistani, Jumala, ja varjele minua niistä, jotka itseänsä asettavat minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Pelasta minua pahointekiöistä, ja auta minua murhamiehistä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Sillä katso, Herra, he väijyvät sieluani: väkevät kokoontuvat minua vastaan, ilman minun syytäni ja rikostani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'He juoksevat ilman syytä, ja valmistavat itseänsä: nouse tulemaan minua vastaan ja katsomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ja sinä, Herra Jumala Zebaot, Israelin Jumala, herää etsimään kaikkia pakanoita: älä ketään heistä armahda, jotka niin väkivaltaisesti vääryyttä tekevät, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'He tulkoon taas ehtoona, ja ulvokaan niinkuin koira, ja samotkaan ympäri kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Katso, he puhuvat suullansa: miekat ovat heidän huulissansa, kuka sen kuulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Mutta sinä, Herra, naurat heitä, ja pilkkaat kaikkia pakanoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Heidän väkevyytensä edestä minä turvaan sinun tykös; sillä Jumala on minun varjelukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Jumala osoittaa minulle runsaasti laupiutensa, Jumala antaa minun nähdä koston vihollisistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Älä heitä tapa, ettei minun kansani sitä unohtaisi: hajoita heitä voimallas, ja lyö heitä maahan, Herra meidän kilpemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Heidän huultensa puhe on heidän suunsa synti: ja he käsitetään ylpeydessänsä: ja he juttelevat kirouksia ja valhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Pyyhi heitä pois vihassas, pyyhi heitä pois, ettei he olisikaan; että he ymmärtäisivät sen, että Jumala hallitsee Jakobissa, hamaan maailman ääriin asti, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'He tulkoon taas ehtoona, ja ulvokaan niinkuin koira, ja samotkaan ympäri kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Anna heidän juosta sinne ja tänne ruoan tähden; ja ulvokaan, koska ei he ravituksi tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Mutta minä veisaan sinun väkevyyttäs, ja varhain kerskaan sinun laupiuttas; sillä sinä olet minun varjelukseni ja turvani minun hädässäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Sinä olet minun väkevyyteni, sinulle minä kiitosta veisaan; sillä sinä Jumala olet minun varjelukseni ja minun armollinen Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Davidin kultainen kappale, edelläveisaajalle, kultaisesta seppeleen kukkaisesta opettamaan, (H60:2) Kuin hän oli sotinut Syrialaisten kanssa Mesopotamiasta, ja Zoban Syrialaisten kanssa; kuin Joab palasi, ja löi Suolalaaksossa kaksitoistakymmentä tuhatta Edomilaista. (H60:3) Jumala, sinä joka olet meitä lykännyt pois, hajoittanut meitä ja ollut vihainen, palaja taas meidän tykömme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Sinä joka maan liikuttanut ja halaissut olet, paranna hänen rakonsa, joka niin haljennut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Sinä olet kansalles kovuutta osoittanut, ja meitä kompastuksen viinalla juottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Sinä annoit lipun niille, jotka sinua pelkäävät, jolla he itsensä ojensivat ylös, totuuden tähden, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Että sinun ystäväs vapahdetuksi tulisivat: niin auta nyt oikialla kädelläs, ja kuule meidän rukouksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Jumala on puhunut pyhässänsä, siitä minä iloitsen: minä tahdon jakaa Sikemin ja mitata Sukkotin laakson.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Gilead on minun, minun on Manasse, Ephrain on minun pääni voima: Juuda on minulle lainopettaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moab on minun pesinpatani, Edomin ylitse heitän minä kenkäni: sinä Philistea, iloitse minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Kuka vie minun vahvaan kaupunkiin? kuka johdattaa minun Edomiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Etkös sinä, Jumala, joka meitä lykkäsit pois? ja etkö sinä, Jumala, lähde ulos meidän sotaväkemme kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Saata meille apu tuskasta; sillä ihmisten apu on turha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Jumalassa tahdomme me voimalliset työt tehdä: ja hän tallaa alas meidän vihollisemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Davidin Psalmi, edelläveisaajalle, kanteleilla. (H61:2) Kuule, Jumala, minun huutoni: ota vaari minun rukouksestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Maan äärestä minä huudan sinun tykös, koska minun sydämeni näännyksissä on: vie minua siis korkialle kalliolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Sillä sinä olet minun turvani, vahva torni vihollisten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Minä tahdon asua sinun majassas ijankaikkisesti, ja uskaltaa sinun siipeis varjon alle, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Sillä sinä, Jumala, kuulet minun lupaukseni, ja annat perinnön niille, jotka sinun nimeäs pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Sinä annat kuninkaalle pitkän ijän, että hänen vuotensa olisivat suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Että hän alati pysyis Jumalan edessä: osoita hänelle laupiutta ja totuutta, jotka häntä varjelisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Niin minä veisaan kiitosta sinun nimelles ijankaikkisesti, maksaakseni minun lupaustani päivä päivältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Davidin Psalmi Jedutunin edestä, edelläveisaajalle. (H62:2) Minun sieluni odottaa ainoastaan Jumalaa, joka minua auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Hän ainoastaan on kallioni, minun autuuteni, minun varjelukseni, etten minä kovin kompastuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Kuinka kauvan te yhtä väijytte, että te kaikin häntä surmaatte, niinkuin kallistuvaa seinää ja raukeevaa muuria?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Kuitenkin he neuvoa pitävät, kukistaaksensa häntä korkeudestansa; he rakastavat valhetta: suullansa he siunaavat, ja sydämessänsä kiroilevat, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Minun sieluni odottaa ainoastaan Jumalaa; sillä hän on minun toivoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Hän ainoastaan on kallioni ja autuuteni, hän varjelukseni, en minä kaadu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Jumalassa on minun autuuteni, minun kunniani, minun väkevyyteni kallio, minun turvani on Jumalassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Te kansat, toivokaat häneen joka aika, vuodattakaat teidän sydämenne hänen eteensä: Jumala on meidän turvamme, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Mutta ihmiset ovat kuitenkin turhat, voimalliset myös puuttuvat: he painavat vähemmän kuin ei mitään, niin monta kuin heitä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Älkäät luottako vääryyteen ja väkivaltaan; älkäät turvatko niihin, mitkä ei mitään ole; jos rikkaudet teidän tykönne lankeevat, niin älkäät panko sydäntänne niiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Jumala on kerran puhunut, sen olen minä kahdesti kuullut: että Jumala (yksinänsä) väkevä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Ja sinä Jumala olet armollinen; sillä sinä maksat jokaiselle työnsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Davidin Psalmi, kuin hän oli Juudan korvessa. (H63:2) Jumala, sinä olet minun Jumalani! Varhain minä sinua etsin: sinua minun sieluni janoo, minun lihani halaa sinua karkiassa ja kuivassa maassa, joka vedetöin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Niinkuin minä näin sinun pyhässä, katsellakseni sinun voimaas ja kunniaas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Sillä sinun laupiutes on parempi kuin elämä: minun huuleni pitää sinua kiittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Niin minä tahdon kunnioittaa sinua minun elinaikanani, ja minun käteni nostaa ylös sinun nimees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Niinkuin lihavuudella ja rasvalla pitää minun sieluni ravittaman: ja minun suuni pitää kiittämän iloisilla huulilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Kuin minä vuoteeseni lasken, niin minä muistan sinua:kuin minä herään, niin minä puhun sinusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Sillä sinä olet minun apuni, ja sinun siipeis varjon alla minä kerskaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Minun sieluni riippuu sinussa: sinun oikia kätes minun tukee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Mutta he etsivät kadottaaksensa minun sieluni: heidän täytyy maan alle mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Heidän pitää miekkaan lankeeman, ketuille osaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Mutta kuninkaan pitää iloitseman Jumalassa: joka hänen kauttansa vannoo, se kunnioitetaan; sillä valhetteliain suu pitää tukittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Davidin Psalmi, edelläveisaajalle. (H64:2) Kuule, Jumala, ääntäni, minun valituksessani: varjele elämäni vihollisen pelvosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Peitä minua pahain neuvosta, väärintekiäin metelistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Jotka kielensä hiovat niinkuin miekan: he ampuvat myrkyllisillä sanoillansa niinkuin nuolilla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Että he salaisesti ampuisivat viatointa: he ampuvat häntä äkisti ilman pelvota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'He vahvistavat itsensä pahoissa juonissansa ja puhuvat, kuinka he paulat virittäisivät, ja sanovat: kuka taitaa ne nähdä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'He ajattelevat vääryyttä, ja täyttävät sen minkä he ajatelleet ovat; viekkaat ihmiset ja salakavalat sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Mutta Jumala ampuu heitä; äkillinen nuoli on heidän rangaistuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Heidän oma kielensä pitää heitä langettaman, että jokainen, joka heidät näkee, pakenee heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Ja kaikkein ihmisten pitää pelkäämän, ja Jumalan työtä ilmoittaman, ja hänen työnsä ymmärtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Vanhurskaat pitää Herrassa riemuitseman, ja häneen uskaltaman; ja kaikki vaat sydämet kerskatkoon siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Davidin Psalmi ja veisu, edelläveisaajalle. (H65:2) Jumala, sinua kiitetään Zionissa hiljaisuudessa; ja sinulle maksetaan lupaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Sinä kuulet rukouksen; sentähden tulee kaikki liha sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Meidän pahat tekomme meitä kovin raskauttavat; mutta anna sinä meille synnit anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Autuas on se, jonkas valitset ja otat tykös, asumaan kartanoissas: hän ravitaan sinun huonees ja pyhän templis hyvyydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Kuule meitä ihmeellisestä vanhurskaudesta, meidän autuutemme Jumala, kaikkein turva maan päällä ja kaukana meressä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Joka vuoret vahvistat voimallas, ja olet hankittu väkevyydellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Sinä joka asetat meren pauhinan ja hänen aaltoinsa pauhinan, ja kansain metelin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Että ne hämmästyisivät, jotka niissä maan äärissä asuvat, sinun ihmeitäs. Sinä iloitat kaikki liikkuvaiset aamulla ja ehtoona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Sinä etsiskelet maan ja liotat sen ja teet sen ylen rikkaaksi: Jumalan virta on vettä täynnä: sinä kasvatat heidän jyvänsä, ettäs näin maan valmistat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Sinä juotat hänen vakonsa ja kastat hänen kyntönsä: sateella sinä ne pehmität, ja siunaat hänen laihonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Sinä kaunistat vuoden hyvyydelläs, ja sinun askelees tiukkuvat rasvasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Korven laitumet myös tiukkuvat, ja kukkulat ovat ympäri iloissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Kedot ovat laumaa täynnä, ja laaksossa on tihkiältä jyviä, niin että siitä ihastutaan ja myös lauletaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Davidin Psalmi ja veisu, edelläveisaajalle. Ihastukaa Jumalalle, kaikki maa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Veisatkaat kiitosta hänen nimensä kunniaksi, ylistäkäät häntä suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sanokaat Jumalalle: kuinka ihmeelliset ovat sinun työs! sinun vihollisiltas pitää puuttuman, sinun suuren väkes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Kaikki maa kumartakoon sinua, ja veisatkaan kiitosta sinun nimelles, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Tulkaat ja katsokaat Jumalan tekoja, joka niin ihmeellinen on töissänsä ihmisten lasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Hän muuttaa meren kuivaksi, niin että jalkaisin käydään veden ylitse: siitä me hänessä iloitsemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Hän hallitsee voimansa kautta ijankaikkisesti, hänen silmänsä katselevat kansoja: eripuraiset ei pidä voiman korottaa itseänsä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Kiittäkäät te pakanat, meidän Jumalaamme: kajahtakaan hänen kiitoksensa ääni kauvas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Joka meidän sielumme elättää, eikä salli jalkamme liukastella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Sillä sinä, Jumala, olet meitä koetellut, ja valanut meitä niinkuin hopia valetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Sinä veit meitä vankeuteen, ja panit kuorman meidän lanteillemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Sinä olet antanut ihmiset meidän päämme päällitse mennä: me olemme tuleen ja veteen tulleet, mutta sinä veit meitä ulos, ja virvoitit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Sentähden minä menen polttouhrilla sinun huoneeses, ja maksan sinulle lupaukseni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Joita minun huuleni lupasivat, ja minun suuni puhunut on tuskassani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Lihavat polttouhrit minä teen sinulle oinasten suitsutuksella: minä uhraan sinulle naudat kauristen kanssa, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Tulkaat, kuulkaat te kaikki, jotka Jumalaa pelkäätte: minä ilmoitan, mitä hän minun sielulleni on tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Häntä minä suullani huusin, ja ylistin kielelläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Jos minä jotakin vääryyttä pitäisin sydämessäni, niin ei Herra minua kuulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Sentähden Jumala on minua kuullut, ja ottanut vaarin minun rukoukseni äänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Kiitetty olkoon Jumala, joka ei hylkää rukoustani, eikä käännä laupiuttansa pois minusta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Psalmi ja veisu, edelläveisaajalle, kanteleilla. (H67:2) Jumala olkoon meille armollinen, ja siunatkoon meitä! hän valistakoon kasvonsa aina meidän päällemme, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Että me maan päällä tuntisimme sinun ties, ja kaikkein pakanain seassa sinun autuutes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Sinua, Jumala, kansat kiittäköön: sinua kaikki kansat kiittäköön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Kansat iloitkaan ja riemuitkaan, ettäs kansat oikein tuomitset, ja hallitset kansat maan päällä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Sinua, Jumala, kansat kiittäköön: sinua kaikki kansat kiittäköön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Maa antaa hedelmänsä; siunatkoon meitä Jumala, meidän Jumalamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Siunatkoon meitä Jumala, ja kaikki maailma peljätköön häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Davidin Psalmi ja veisu, edelläveisaajalle. (H68:2) Nouskaan Jumala, että hänen vihollisensa hajoitettaisiin; ja jotka häntä vihaavat, paetkaat hänen edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Aja heitä pois, niinkuin savu ajetaan pois; niinkuin vedenvaha sulaa tulen edessä, niin hukkukaan jumalattomat Jumalan kasvoin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Mutta vanhurskaat riemuitkaan ja iloitkaan Jumalan edessä, ja riemuitkaan ilossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Veisatkaan Jumalalle, veisatkaat kiitosta hänen nimellensä; tehkäät hänelle tietä, joka istuu ylimmäisten taivasten päällä; hänen nimensä on Herra, ja iloitkaat hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Joka on orpoin isä ja leskein tuomari: hän on Jumala pyhässä asumisessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Jumala, joka yksinäisten antaa asua huoneessa, ja vie vangit ulos oikeudella; mutta vastahakoiset asuvat kuivassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Jumala, koskas kävit kansas edellä, koskas vaelsit korvessa, Sela,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Niin maa vapisi ja taivaat tiukkuivat Jumalan edessä: tämä Sinai, Jumalan edessä, joka Israelin Jumala on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Mutta nyt sinä, Jumala, annat armollisen sateen, ja virvoitat perimises, joka väsynyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Että sinun laumas siinä asuis: Jumala, sinä virvoitat hyvyydelläs raadolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Herra antaa sanan suurella evankelistain joukolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Sotaväen kuninkaat pakenevat, he pakenevat; ja kotona asuva jakaa saaliit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Kuin te tarhain välissä makaatte, niin mettisen sulat ovat silatut hopialla, ja hänen siipensä ruskialla kullalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Kuin Kaikkivaltias siinä joka paikassa kuninkaat levittää, niin Zalmonissa valaisee kuin lumi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Jumalan vuori on hedelmällinen vuori: korkia vuori on se hedelmällinen vuori.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Miksi te, suuret vuoret, kippaatte? Tämä on Jumalan vuori, jossa hän mielistyy asumaan; ja Herra asuu siellä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Jumalan rattaita on monta tuhatta kertaa tuhatta: Herra on heissä, pyhässä Sinaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Sinä astuit ylös korkeuteen, ja olet vangiksi ottanut vankeuden. Sinä olet lahjoja saanut ihmisille: vastahakoiset myös, että Herra Jumala siellä kumminkin asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Kiitetty olkoon Herra joka päivä! Jumala panee kuorman meidän päällemme; mutta hän myös auttaa meitä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Meillä on Jumala, Jumala, joka auttaa, ja Herra, Herra, joka kuolemasta vapahtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Mutta Jumala särkee vihollistensa pään heidän päänlakeinsa kanssa, jotka pysyvät heidän synneissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Herra sanoo: minä palautan (muutamat) lihavista; meren syvyydestä minä heitä palautan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Että sinun jalkas tulis painetuksi veressä, ja koirais kieli sinun vihollisistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'He näkivät, Jumala, kuinkas vaellat; kuinkas, minun Jumalani ja kuninkaani, pyhässä vaellat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Laulajat käyvät edellä, ja sitte leikarit piikain seassa, jotka kanteleita soittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Kiittäkäät Herraa Jumalaa seurakunnissa, te Israelin lähteestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Siellä hallitsee heitä vähä Benjamin, Juudan päämiehet joukkoinensa, Zebulonin päämiehet, Naphtalin päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Sinun Jumalas on käskenyt sinun olla väkevän: vahvista Jumala se, minkä sinä meissä tehnyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Sinun templis tähden, joka on Jerusalemissa, pitää kuninkaat sinulle lahjoja viemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Nuhtele ruovon petoa, härkäin laumaa kansain vasikkain kanssa, jotka kumartaen tuovat hopeakankeja: hajoittanut on hän kansat, jotka mielellänsä sotivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Egyptin päämiehet tulevat: Etiopia ojentaa käsiänsä Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Te maan valtakunnat, veisatkaat Jumalalle, veisatkaat kiitosta Herralle, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Sille joka asuu taivaissa joka paikassa, hamasta alusta: katso, hän antaa jylinälle voiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Antakaat Jumalalle voima: hänen herrautensa on Israelissa, ja hänen voimansa pilvissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Jumala on ihmeellinen pyhässänsä, hän on Israelin Jumala: hän antaa kansalle väen ja voiman: kiitetty olkoon Jumala!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Davidin Psalmi kukkasista, edelläveisaajalle. (H69:2) Jumala,auta minua; sillä vedet käyvät hamaan minun sieluuni asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Minä vajoon syvään mutaan, jossa ei pohjaa ole: minä olen tullut syviin vesiin, ja virta upottaa minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Minä väsyn huutamisesta: minun kurkkuni kuivettuu: minun näkyni vaipuu, toivoissani minun Jumalani päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Niitä on enempi kuin päässäni hiuksia, jotka ilman syytä minua vihaavat, jotka syyttömästi minun viholliseni ovat, ja minua hukuttavat, ovat väkevät: niitä täytyy minun maksaa, joita en minä ryövännyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Jumala, sinäpä tiedät minun tyhmyyteni, ja minun rikokseni ei ole sinulta salatut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Älä salli heitä häpiään tulla minun tähteni, jotka sinua odottavat, Herra, Herra Zebaot: älä anna heitä häväistä minun tähteni, jotka sinua etsivät, Israelin Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Sillä sinun tähtes minä pilkkaa kärsin; minun kasvoni ovat täynnä häpiää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Minä olen muukalaiseksi veljilleni tullut, ja oudoksi äitini lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Sillä sinun huonees kiivaus syö minua: ja heidän pilkkansa, jotka sinua pilkkasivat, lankesi minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Minä itkin ja paastosin hartaasti, ja minä pilkattiin päälliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Ja minä puin säkin ylleni, ja olin heille sananlaskuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Jotka portissa istuvat, ne minusta jaarittelevat, ja juodessansa he minusta lauleskelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Mutta minä rukoilen sinua, Herra, otollisella ajalla, Jumala, sinun suuren laupiutes puolesta: kuule minua sinun autuutes totuuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Pelasta minua loasta, etten minä vajoaisi; että minä pelastettaisiin vihollisistani ja syvistä vesistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Ettei vuo minua upottaisi ja syvyydet minua lainoaisi, eikä kaivon suu suljettaisi minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Kuule minua, Herra; sillä sinun laupiutes on hyvä: käännä sinuas minun puoleeni, sinun suuren laupiutes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Ja älä peitä kasvojas palvelialtas; sillä minä ahdistetaan: kuultele minua nopiasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Lähene minun sieluani, ja lunasta häntä: minun vihollisteni tähden pelasta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Sinäpä tiedät pilkkani, häpiäni ja häväistykseni: kaikki minun viholliseni ovat edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Pilkka särkee minun sydämeni ja vaivaa minua: minä odotan, jos joku armahtais, ja ei ole kenkään, ja lohduttajia, vaan en ketään löydä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Ja he antoivat minulle sappea syödäkseni, ja etikkaa juodakseni minun janossani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Heidän pöytänsä olkoon heille paulaksi, sekä kostoksi että lankeemiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Tulkoon heidän silmänsä pimiäksi, ettei he näkisi, ja salli heidän lanteensa aina horjua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Vuodata närkästykses heidän päällensä, ja hirmuinen vihas käsittäköön heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Olkoon heidän huoneensa kylmillä; ja ei kenkään olko, joka heidän majassansa asuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Sillä he vainoovat sitä, jota lyönyt olet, ja juttelevat niiden kipua, joita haavoittanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Salli heitä langeta synnistä syntiin, ettei he tulisi sinun vanhurskautees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Pyyhi heitä eläväin kirjasta, ettei he kirjoitettaisi vanhurskasten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Mutta minä olen raadollinen ja murheellinen: Jumala, sinun autuutes suojelkoon minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Minä kiitän Jumalan nimeä veisuulla, ja suuresti ylistän häntä kiitoksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Se kelpaa paremmin Herralle kuin härkä taikka mulli, jolla ovat sarvet ja sorkat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Raadolliset näkevät sen ja iloitsevat, ja jotka Jumalaa etsivät, heidän sydämensä pitää elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Sillä Herra kuulee köyhiä, ja ei hän vankiansa katso ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Kiittäkään häntä taivaat ja maa, meri, ja kaikki kuin niissä liikkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Sillä Jumala auttaa Zionia ja rakentaa Juudan kaupungit, että siellä asutaan, ja se perinnöllä omistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Ja hänen palveliainsa siemen sen perii: ja ne, jotka hänen nimeänsä rakastavat, pitää asuman siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Davidin Psalmi edelläveisaajalle, muistoksi. (H70:2) Riennä, Jumala, minua vapahtamaan: kiiruhda, Herra, minua auttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Häpiään tulkoon ja hävetköön, jotka minun sieluani väijyvät: ajettakoon takaperin ja tulkoon häväistyksi, jotka minulle pahaa suovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Että he jälleen häpiään tulisivat, jotka minua pitittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Iloitkaan ja riemuitkaan sinussa kaikki, jotka sinua etsivät; ja jotka sinun autuuttas rakastavat, sanokaan aina: Jumala olkoon suuresti ylistetty!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Mutta minä olen raadollinen ja köyhä, riennä, Jumala, minun tyköni; sillä sinä olet minun auttajani ja pelastajani, Herra, älä viivyttele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Sinuun, Herra, minä uskallan: älä anna minua ikänä häväistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Vapahda minua vanhurskaudessa ja pelasta minua: kallista korvas minun puoleeni ja auta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Ole minulle vahva turva, johon minä aina pakenisin: sinä olet luvannut minua auttaa; sillä sinä olet minun kallioni ja linnani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Minun Jumalani, auta minua jumalattoman kädestä, väärän ja väkivaltaisen kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Sillä sinä olet minun turvani, Herra, Herra: minun toivoni hamasta minun nuoruudestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Sinuun minä olen luottanut hamasta äitini kohdusta, sinä minun vedit ulos äitini kohdusta: sinusta on aina minun kerskaukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Minä olen monelle ihmeeksi tullut; mutta sinä olet minun vahva turvani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Täytä minun suuni sinun kiitoksestas ja sinun kunniastas joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Älä minua heitä pois minun vanhuudessani: älä minua hylkää, kuin minä heikoksi tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Sillä minun viholliseni puhuvat minua vastaan: ja jotka minun sieluani väijyvät, he keskenänsä neuvoa pitävät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Ja sanovat: Jumala hylkäsi hänen; ajakaat takaa ja käsittäkäät häntä, sillä ei ole vapahtajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Jumala, älä erkane kauvas minusta: minun Jumalani, riennä minua auttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Hävetköön ja hukkukoon, jotka minun sieluani vastaan ovat: häpiän ja häväistyksen alle tulkoon, jotka minulle pahaa suovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mutta minä odotan aina, ja korotan aina sinun kiitokses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Minun suuni pitää ilmoittaman sinun vanhurskauttas, joka päivä sinun autuuttas, joita en minä voi kaikkia lukea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Minä vaellan Herran, Herran väkevyydessä: minä tahdon muistaa ainoastaan sinun vanhurskauttas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Jumala, sinä olet minua nuoruudestani opettanut, sentähden minä julistan sinun ihmeitäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Ja minun vanhuudessani ja harmaaksi tultuani älä, Jumala, minua hylkää, siihenasti kuin minä ilmoitan sinun käsivartes lasten lapsille, ja sinun väkevyytes kaikille tulevaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Ja tosin, Jumala, sinun vanhurskautes on sangen korkia, sinä teet suuria: Jumala, kuka on sinun vertaises?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Sillä sinä annat minun nähdä paljon ja suuria ahdistuksia, ja virvoitat minua jälleen; ja taas sinä haet minua ulos maan syvyydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Sinä teet minun sangen suureksi, ja lohdutat minua jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Niin minäkin kiitän sinua psaltarilla, sinun totuuttas, minun Jumalani: minä veisaan kiitosta sinulle kanteleilla, sinä pyhä Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Minun huuleni pitää kiittämän, koska minä sinulle veisaan, ja minun sieluni, jonkas lunastit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Ja minun kieleni puhuu myös joka päivä sinun vanhurskaudestas; sentähden hävetkään he ja häpiään tulkoon, jotka minulle pahaa suovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salomon. Jumala, anna tuomios kuninkaalle, ja vanhurskautes kuninkaan pojalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Että hän veis sinun kansas vanhurskauteen, ja auttais sinun raadollistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Vuoret tuokaan rauhan kansalle, ja kukulat vanhurskauden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Hänen pitää raadollisen kansan oikeudessa pitämän, ja köyhäin lapsia auttaman ja särkemän pilkkaajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Sinua peljätään, niinkauvan kuin aurinko ja kuu ovat, lapsista niin lasten lapsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Hän laskee alas niinkuin sade heinän sängelle, niinkuin pisarat, jotka maan lioittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Hänen aikanansa vanhurskas kukoistaa, ja on suuri rauha siihen asti, ettei kuuta enää olekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Hän hallitsee merestä mereen ja virrasta maailman ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Häntä pitää korven asuvaiset kumartaman, ja hänen vihollisensa pitää tomun nuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Kuninkaat meren tyköä ja luodoista pitää lahjoja kantaman: kuninkaat rikkaasta Arabiasta ja Sebasta pitää annot tuoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Kaikki kuninkaat pitää häntä kumartaman, ja kaikki pakanat pitää häntä palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Sillä hän vapahtaa huutavaisen köyhän, ja raadollisen, jolla ei ole auttajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Hän on armollinen vaivaiselle ja köyhälle, ja köyhäin sielua hän auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Hän lunastaa heidän sielunsa petoksesta ja väkivallasta, ja heidän verensä luetaan kalliiksi hänen silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Ja hän elää ja hänelle pitää annettaman kultaa rikkaasta Arabiasta, ja häntä alati kumartaen rukoiltaman, joka päivä pitää häntä kiitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Pivo jyviä pitää niin oleman maassa ja vuorten kukkuloilla, että sen hedelmä pitää häälymän niinkuin Libanon; ja kaupungin asuvaiset pitää kukoistaman niinkuin ruoho maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Hänen nimensä pysyy ijankaikkisesti: niinkauvan kuin aurinko on, ulottuu hänen nimensä jälkeentulevaisille; ja he tulevat siunatuksi hänen kauttansa: kaikki pakanat ylistävät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Kiitetty olkoon Herra Jumala, Israelin Jumala, joka yksinänsä ihmeitä tekee!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Ja kiitetty olkoon hänen kunniansa nimi ijankaikkisesti; ja kaikki maa täytettäköön hänen kunniastansa, amen! amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Davidin, Isain pojan, rukoukset loppuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Asaphin Psalmi. Totta on Jumala hyvä Israelille, niille, jotka puhtaat sydämestä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Mutta minä olisin pian jaloillani horjunut: minun askeleeni olisivat lähes liukastuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Sillä minä närkästyin öykkäreistä, että minä näin jumalattomat menestyvän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Sillä ei he ole missään kuoleman hädässä, vaan heidän voimansa pysyy vahvana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Ei he ole vastoinkäymisessä niinkuin muut ihmiset, ja ei heitä vaivata niinkuin muita ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Sentähden on heidän ylpeytensä koria, ja heidän väkivaltansa kaunistaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Heidän silmänsä paisuvat lihavuudesta: he tekevät mitä ainoastansa heille kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Kaikkia he katsovat ylön, ja sitte pahasti puhuvat: he puhuvat ja laittavat ylpiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Mitä he puhuvat, sen täytyy olla taivaasta puhuttu: mitä he sanovat, sen täytyy maan päällä kelvata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Sentähden noudattaa heitä yhteinen kansa, ja kokoontuvat heidän tykönsä niinkuin vedet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Ja sanovat: mitä Jumalan pitäis heitä kysymän? mitä pitäis korkeimman heistä lukua pitämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Katso, ne ovat jumalattomat: he ovat onnelliset maailmassa ja rikastuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Pitäiskö siis sen turhaan oleman, että minun sydämeni nuhteetoinna elää, ja minä pesen viattomuudessa minun käteni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Ja minä ruoskitaan joka päivä, ja minun rangaistukseni on joka aamu käsissä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Minä olisin lähes niin sanonut kuin hekin; mutta katso, niin minä olisin tuominnut kaikki sinun lapses, jotka ikänänsä olleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Minä ajattelin sitä tutkia; mutta se oli minulle ylen raskas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Siihenasti kuin minä menin Jumalan pyhään, ja ymmärsin heidän loppunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Tosin sinä asetit heitä liukkaalle, ja syöksit heitä pohjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kuinka he niin pian hukkuvat: he hukkuvat ja saavat kauhian lopun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Niinkuin uni, koska joku herää, niinpä sinä, Herra teet heidän kuvansa kaupungissa ylönkatsotuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Vaan kuin se karvasteli minun sydämessäni ja pisti minun munaskuitani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Silloin olin minä tyhmä ja en mitään tietänyt: minä olin niinkuin nauta sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Kuitenkin minä pysyn alati sinun tykönäs; sillä sinä pidät minun oikiasta kädestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Sinä talutat minua neuvollas, ja korjaat minua viimein kunnialla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kuin sinä ainoastansa minulla olisit, niin en minä ensinkään sitte taivaasta eli maasta tottelisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Vaikka vielä minun ruumiini ja sieluni vaipuis, niin sinä, Jumala, kuitenkin olet aina minun sydämeni uskallus ja minun osani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Sillä katso, jotka sinusta eriävät, ne hukkuvat: sinä kadotat kaikki, jotka sinua vastaan huorin tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mutta se on minun iloni, että minä itseni Jumalan tykö pidän, ja panen toivoni Herran, Herran päälle, ilmoittamaan kaikkia sinun töitäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Asaphin opetus. Jumala, miksis meitä niin ratki pois syökset? ja olet niin hirmuisesti vihainen sinun laitumes lampaille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Muista seurakuntaas, jonkas muinen omistit ja sinulle perimiseksi lunastanut olet, Zionin vuorta, jossas asuit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Tallaa heitä jaloillas, ja sysää heitä ijäiseen hävitykseen: vihollinen on raiskannut kaikki pyhässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Sinun vihollises kiljuvat sinun huoneessas, ja asettavat epäjumalansa siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Kirveet näkyvät välkkyvän ylhäällä, niinkuin metsässä hakattaisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Ja hakkaavat rikki kaikki hänen kuvainsa kaunistukset, sekä keihäillä että kirveillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'He polttavat sinun pyhäs, ja turmelevat sinun nimes asuinsian maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'He puhuvat sydämessänsä: raadelkaamme heitä ynnä; he polttavat kaikki Jumalan huoneet maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Emme näe meidän ihmeitämme, eikä silleen prophetaa ole: ei myös ketään meidän seassamme ole, joka ymmärtää kuinka kauvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Jumala, kuinka kauvan vihamies häpäisee ja vihollinen sinun nimeäs ratki niin pilkkaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Miksis käännät pois sinun kätes? ja oikian kätes niin ratki sinun povestas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Mutta Jumala on alusta minun kuninkaani, joka kaikkinaisen autuuden matkaan saattaa maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Sinä hajoitat meren voimallas: sinä murennat lohikärmeiden päät vesissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Sinä murensit valaskalain päät, ja annat ne kansalle ruaksi metsän korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Sinä kuohutat lähteet ja virrat: sinä kuivaat väkevät kosket.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Päivä ja yö ovat sinun: sinä rakennat valkeuden ja auringon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Sinä sovitit jokaisen maan rajat: sinä teet suven ja talven.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Niin muista siis, että vihollinen häpäisee Herraa, ja hullu kansa pilkkaa sinun nimeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Älä siis anna pedolle mettises sielua, ja älä niin ratki unohda sinun köyhäis joukkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Muista liittoa; sillä maa on joka paikassa surkiasti hävitetty, ja huoneet ovat täynnä vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Älä anna köyhän mennä pois häpiällä; sillä köyhät ja raadolliset kiittävät sinun nimeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Nouse, Jumala, ja aja asias: muista niitä häväistyksiä, jotka sinulle joka päivä hulluilta tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Älä unohda vihollistes ääntä: sinun vainollistes meteli tulee aina suuremmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Asaphin Psalmi ja veisu, ettei hän hukkunut, edelläveisaajalle. (H75:2) Me kiitämme sinua, ja ilmoitamme ihmeitäs, että sinun nimes on niin läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Sillä ajallansa minä oikein tuomitsen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Maa vapisee ja kaikki, jotka sen päällä asuvat; mutta minä vahvistan lujasti hänen patsaansa, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Minä sanoin öykkäreille: älkäät niin kerskatko, ja jumalattomille: älkäät vallan päälle haastako.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Älkäät niin pahoin haastako teidän valtanne päälle: älkäät puhuko niin niskuristi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Niinkuin ei mitään hätää olisi, eikä idästä eikä lännestä, taikka vuorilta korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Sillä Jumala on tuomari, joka tämän alentaa ja toisen ylentää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Sillä Herran kädessä on malja täynnä, väkevällä viinalla täytetty, ja siitä hän panee sisälle; vaan sen rahkan täytyy kaikkein jumalattomain maan päällä juoda, ja ryypätä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Mutta minä ilmoitan ijankaikkisesti, ja veisaan kiitosta Jakobin Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ja minä tahdon särkeä kaiken jumalattomain vallan, että vanhurskasten valta korotettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Asaphin Psalmi ja veisu, kanteleilla, edelläveisaajalle. (H76:2) Jumala on tuttu Juudassa, Israelissa on hänen suuri nimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Salemissa on hänen majansa, ja Zionissa hänen asumisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Siellä hän särkee joutsen nuolet, kilvet, miekan ja sodan, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Sinä olet kirkkaampi ja väkevämpi kuin ryöstövuoret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Urhoolliset pitää ryöstettämän ja uneensa nukkuman; ja kaikki sotamiehet täytyy käsistänsä hermottomaksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Sinun rangaistuksestas, Jakobin Jumala, vajoo uneen orhi ja ratas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Sinä olet peljättävä: kuka voi seisoa sinun edessäs, koskas vihastut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Koskas tuomion annat kuulua taivaasta, niin maa vapisee ja vaikenee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Koska Jumala nousee tuomitsemaan, että hän auttais kaikkia raadollisia maan päällä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Kuin ihmiset kiukuitsevat sinua vastaan, niin sinä voitat kunnian, ja kuin he vielä enemmin kiukuitsevat, niin sinä olet valmis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Luvatkaat ja antakaat Herralle teidän Jumalallenne kaikki, jotka hänen ympärillänsä olette, viekäät lahjoja peljättävälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Joka päämiehiltä ottaa pois rohkeuden, ja on peljättävä maan kuninkaille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Asaphin Psalmi, Jedutunin edestä, edelläveisaajalle. (H77:2) Minä huudan äänelläni Jumalaa: Jumalaa minä huudan, ja hän kuultelee minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Minun hätä-ajallani etsin minä Herraa: minun käteni on yöllä ojettu, ja ei lakkaa; sillä ei minun sieluni salli itseänsä lohduttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Minä ajattelen tosin Jumalan päälle, olen kuitenkin murheissani: minä tutkin, ja henkeni on sittekin ahdistuksessa, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Sinä pidät minun silmäni, että he valvovat: minä olen niin voimatoin, etten minä voi puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Minä ajattelen vanhoja aikoja, entisiä vuosia:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Minä muistan yöllä minun kantelettani: minä puhun sydämelleni, ja minun henkeni tutkii:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Heittäneekö Jumala pois ijankaikkisesti, ja ei yhtään armoa silleen osoittane?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Puuttuneeko hänen laupiutensa ijankaikkisesti, ja olleeko lupauksella jo loppu suvusta sukuhun?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Onko Jumala unohtanut olla armollinen? ja sulkenut laupiutensa vihan tähden? Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Minä sanoin: se on minun heikkouteni; mutta Ylimmäisen oikia käsi voi kaikki muuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Sentähden minä muistan Herran töitä, ja minä ajattelen entisiä ihmeitäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Ja puhun kaikista sinun töistäs, ja sanon sinun teoistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Jumala, sinun ties on pyhä: kussa on niin väkevää Jumalaa kuin sinä Jumala?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Sinä olet se Jumala, joka ihmeitä tekee: sinä osoitit voimas kansain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Sinä lunastit sinun kansas käsivarrellas, Jakobin ja Josephin lapset, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Vedet näkivät sinun, Jumala, vedet näkivät sinun ja vapisivat, ja syvyydet pauhasivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Paksut pilvet kaasivat vettä, pilvet jylisivät ja nuolet lensivät sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Se jylisi taivaassa, ja sinun leimaukses välkkyi maan piirin päälle: maa liikkui ja värisi siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Sinun ties oli meressä, ja sinun polkus olivat suurissa vesissä, ja ei sinun jälkiäs kenkään tuntenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Sinä veit kansas niinkuin lammaslauman, Moseksen ja Aaronin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Asaphin opetus. Kuule, kansani, minun lakini: kallistakaat korvanne minun suuni sanoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Minä avaan suuni sananlaskuun, ja vanhat tapaukset mainitsen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Jotka me kuulleet olemme ja tiedämme, ja meidän isämme meille jutelleet ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Ettemme sitä salaisi heidän lapsiltansa, jälkeentulevaiselta sukukunnalta, julistain Herran kiitoksia, ja hänen voimaansa ja ihmeitänsä, jotka hän on tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Hän sääsi todistuksen Jakobissa, ja antoi lain Israelissa, jonka hän käski meidän isäimme opettaa lapsillensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Että vastatulevaiset oppisivat, ja lapset, jotka vielä syntyvät: kuin he kasvavat, että hekin myös ilmoittaisivat lapsillensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Että he panisivat toivonsa Jumalaan ja ei unohtaisi Jumalan tekoja, vaan pitäisivät hänen käskynsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Ja ei olisi niinkuin heidän isänsä, vastahakoinen ja kankia suku, joka ei vahvistanut sydäntänsä, ja heidän henkensä ei riippunut uskollisesti Jumalassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Niinkuin Ephraimin lapset, sota-aseilla varustetut joutsimiehet, pakenivat sodan ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Ei he pitäneet Jumalan liittoa, ja ei vaeltaneet hänen laissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Ja he unohtivat hänen tekonsa ja ihmeensä, jotka hän heille osottanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Heidän isäinsä edessä teki hän ihmeitä, Egyptin maassa, Zoanin kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Hän halkasi meren ja vei heitä sen lävitse, ja asetti vedet niinkuin roukkion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Ja hän talutti heitä yli päivää pilvellä, yli yötä tulen valolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Hän halkasi kalliot korvessa, ja juotti heitä vedellä yltäkyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Ja hän laski ojat vuotamaan kalliosta, niin että vedet siitä vuosivat niinkuin virrat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Ja vielä he sittenkin syntiä tekivät häntä vastaan, ja vihoittivat korkeimman korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'He kiusasivat Jumalaa sydämessänsä, anoen ruokaa sielullensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'He puhuivat Jumalaa vastaan ja sanoivat: voineeko Jumala valmistaa pöydän korvessa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Katso, kyllä tosin hän kallioon löi, ja vedet vuosivat, ja ojat juoksivat; mutta voineeko hän myös leipää antaa, eli kansallensa lihaa toimittaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Kuin Herra sen kuuli, vihastui hän: ja tuli sytytettiin Jakobissa, ja julmuus tuli Israelin päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Ettei he uskoneet Jumalan päälle, ja ei uskaltaneet hänen apuunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Ja hän käski pilviä ylhäältä, ja avasi taivaan ovet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Ja antoi sataa heille mannaa syödäksensä, ja antoi heille taivaan leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'He söivät väkeväin leipää: hän lähetti heille kyllä ruokaa ravinnoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Hän antoi itätuulen puhaltaa taivaan alla, ja väkevyydellänsä kehoitti hän etelätuulen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Ja antoi sataa, niinkuin tomua, lihaa heille, ja lintuja niinkuin santaa meressä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Ja salli langeta keskelle heidän leiriänsä, joka paikassa kuin he asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Niin he söivät ja yltäkyllä ravittiin: ja hän antoi heille heidän himonsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Kuin ei he vielä lakanneet himoitsemasta, ja ruoka oli vielä heidän suussansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Tuli Jumalan viha heidän päällensä, ja tappoi jaloimmat heidän seastansa, ja parahimmat Israelissa hän maahan löi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Mutta vielä sittenkin kaikissa näissä he syntiä tekivät ja ei uskoneet hänen ihmeitänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Sentähden lopetti hän heidän päivänsä turhuudessa, ja heidän vuotensa kiiruhtain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Kuin hän heitä tappoi, etsivät he häntä: ja he palasivat ja tulivat varhain Jumalan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Ja muistelivat, että Jumala on heidän turvansa, ja Jumala korkein heidän lunastajansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Ja he puhuivat hänelle ulkokullaisesti suullansa, ja valehtelivat hänelle kielellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Mutta heidän sydämensä ei ollut oikia hänen puoleensa, ja ei he pitäneet uskollisesti hänen liittoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Mutta hän oli armollinen, ja antoi pahat teot anteeksi, ja ei hukuttanut heitä; ja hän käänsi pois usein vihansa, ettei hän laskenut kaikkea vihaansa menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Sillä hän muisti heidän lihaksi, tuuleksi, joka menee pois ja ei palaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kuinka usein he vihoittivat hänen korvessa ja kehoittivat hänen erämaassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Ja he kiusasivat taas Jumalaa joka aika, ja laittivat pyhää Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Ei he muistaneet hänen kättänsä sinä päivänä, jona hän lunasti heitä vihollisista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Niinkuin hän oli merkkinsä Egyptissä tehnyt, ja ihmeensä Zoanin kedolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Koska hän heidän virtansa vereksi muutti, ettei he ojistansa taitaneet juoda:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Koska hän turilaat heidän sekaansa lähetti, jotka heitä söivät, ja sammakot, jotka heitä hukuttivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Ja antoi heidän tulonsa ruohomadoille, ja heidän työnsä heinäsirkoille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Koska hän rakeilla heidän viinapuunsa löi, ja heidän metsäfikunansa jääkivillä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Koska hän löi heidän karjansa rakeilla, ja heidän laumansa pitkäisen tulella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Hän lähetti heidän päällensä vihansa, närkästyksen, julmuuden ja ahdistuksen, pahain enkelien lähettämisellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Hän päästi vihansa heidän sekaansa, ja ei päästänyt heidän sielujansa kuolemasta, ja heidän eläimensä rutolla kuoletti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Koska hän kaikki esikoiset löi Egyptissä, ensimäiset perilliset Hamin majoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Ja antoi kansansa vaeltaa niinkuin lampaat, ja vei heidät niinkuin lauman korvessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Ja saatti heitä turvallisesti, ettei he peljänneet; vaan heidän vihollisensa peitti meri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Ja hän vei heitä pyhänsä rajoihin, tämän vuoren tykö, jonka hänen oikia kätensä saanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Ja hän ajoi pois heidän edestänsä pakanat, ja jakoi heille perimisen arvalla: ja niiden majoissa antoi hän Israelin sukukunnat asua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Mutta he kiusasivat ja vihoittivat korkian Jumalan, ja ei pitäneet hänen todistuksiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Vaan he palasivat takaperin ja petollisesti luopuivat pois niinkuin heidän isänsäkin: poikkesivat pois niinkuin hellinnyt joutsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Ja he vihoittivat hänen korkeuksillansa ja kehoittivat häntä epäjumalainsa kuvilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Ja kuin Jumala sen kuuli, niin hän närkästyi, ja hylkäsi kovin Israelin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Niin että hän luopui asuinsiastansa Silossa, siitä majasta, jonka hän ihmisten sekaan asetti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Ja antoi heidän voimansa vankeuteen, ja heidän kauneutensa vihollisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Ja hän hylkäsi kansansa miekan alle, ja närkästyi perimistänsä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Heidän parhaat nuorukaisensa kulutti tuli, ja heidän neitseensä ei tulleet häävirsillä kunnioitetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Heidän pappinsa kaatuivat miekalla; ja heidän leskensä ei itkeneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Ja Herra heräsi niinkuin joku makaavainen, niinkuin joku väkevä luihkaaja viinan juomisesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Ja löi vihollistansa perävieriin, ja pani ijankaikkisen häpiän heidän päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Ja heitti Josephin majan pois, ja ei valinnut Ephraimin sukukuntaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Vaan hän valitsi Juudan sukukunnan, Zionin vuoren, jota hän rakasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Ja rakensi pyhänsä korkialle, niinkuin ijankaikkisesti pysyväisen maan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Ja valitsi palveliansa Davidin, ja otti hänen lammashuoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Imettävistä lampaista haki hän hänen, että hän hänen kanssansa Jakobin kaitsis, ja Israelin hänen perimisensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Ja hän kaitsi heitä kaikella sydämensä vakuudella, ja hallitsi heitä kaikella ahkeruudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Asaphin Psalmi. Jumala, pakanat ovat perikuntaas karanneet: he ovat saastuttaneet pyhän temppelis, ja Jerusalemista kiviraunion tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'He antoivat sinun palveliais ruumiit linnuille taivaan alla ruaksi, ja pyhäis lihan maan pedoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'He vuodattivat heidän verensä niinkuin veden Jerusalemin ympärille, ja ei kenkään haudannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Me olemme läsnäasuvaisillemme nauruksi tulleet, häväistykseksi ja pilkaksi niille, jotka meidän ympärillämme ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Herra, kuinka kauvan sinä taukoomata niin vihainen olet? ja annat kiivautes palaa niinkuin tulen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Vuodata vihas pakanain päälle, jotka ei sinua tunne, ja niiden valtakuntain päälle, jotka ei sinun nimeäs avuksi huuda;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Sillä he ovat Jakobin syöneet, ja hänen huoneensa hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Älä muistele meidän entisiä pahoja tekojamme: armahda sinuas nopiasti meidän päällemme; sillä me olemme sangen viheliäisiksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Auta meitä, meidän autuutemme Jumala, sinun nimes kunnian tähden: pelasta meitä, ja anna meille synnit anteeksi sinun nimes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Miksis sallit pakanain sanoa: kussa on nyt heidän Jumalansa? ilmoitettakaan pakanain seassa, meidän silmäimme edessä, sinun palveliais veren kosto, joka vuodatettu on!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Anna etees tulla vankein huokaukset: suuren käsivartes kautta, korjaa kuoleman lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Ja kosta meidän läsnäasuvaisillemme seitsemin kerroin heidän helmaansa heidän pilkkansa, jolla he sinua, Herra, pilkanneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mutta me sinun kansas, ja sinun laitumes lauma, kiitämme sinua ijankaikkisesti, ja julistamme sinun kiitostas suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Asaphin Psalmi, kultasesta kukkaisesta, edelläveisaajalle. (H80:2) Kuules, Israelin paimen, joka saatat Josephin niinkuin lampaat: ilmoita sinus, joka istut Kerubimin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Herätä voimas, sinä joka Ephraimin, Benjaminin ja Manassen edessä olet, ja tule meidän avuksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Jumala, käännä meitä, ja anna kasvos paistaa, niin me tulemme autetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Herra Jumala Zebaot, kuinka kauvan sinä vihastut kansas rukouksiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Sinä ruokit heitä kyyneleiden leivällä, ja juotat heitä suurella mitalla, täynnä kyyneleitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Sinä olet meidät pannut riidaksi läsnäasuvaisillemme; ja meidän vihollisemme pilkkaavat meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Jumala Zebaot, käännä meitä, ja anna kasvos paistaa, niin me autetuksi tulemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Sinä toit viinapuun Egyptistä, olet pakanat karkoittanut ulos, ja sen istuttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Sinä perkasit tien hänen eteensä, ja annoit hänen hyvästi juurtua, niin että se täytti maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Vuoret ovat sen varjolla peitetyt, ja hänen oksillansa Jumalan sedripuut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Sinä levitit hänen oksansa hamaan mereen asti, ja hänen haaransa hamaan virran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Miksis siis särjit hänen aitansa, että sitä kaikki ohitsekäyvät repivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Metsäsika on sen kaivanut ylös, ja metsän pedot sen syövät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Jumala Zebaot, käännä siis sinuas, katso alas taivaasta ja näe, ja etsi sitä viinapuuta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Ja pidä se kiintiänä, jonka sinun oikia kätes on istuttanut, (ihmisen) pojan tähden, jonka sinulles lujasti valinnut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Se on poltettu tulella ja revitty: sinun uhkauksestas he ovat hukkuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Sinun kätes varjelkoon oikian kätes kansan, ja ihmisen pojan, jonka sinulles lujasti valinnut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Niin emme sinusta luovu: suo meidän elää, niin me sinun nimeäs avuksi huudamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Herra Jumala Zebaot, käännä meitä: anna kasvos paistaa, niin me autetuksi tulemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Gittitin päällä, edelläveisaajalle, Asaphin (Psalmi.) (H81:2) Veisatkaat iloisesti Jumalalle, joka on meidän väkevyytemme: ihastukaat Jakobin Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Ottakaat psalmit ja tuokaat kanteleet, iloiset harput ja psaltari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Soittakaat pasunilla uudessa kuussa, meidän lehtimajamme juhlapäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Sillä se on tapa Israelissa, ja Jakobin Jumalan oikeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Sen hän pani Josephissa todistukseksi, koska he Egyptin maalta läksivät, ja oudon kielen kuulleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Minä olen heidän olkansa kuormasta vapahtanut; ja heidän kätensä pääsivät tiiliä tekemästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Koska sinä tuskassas minua avukses huusit, niin minä autin sinua: minä kuulin sinua, koska tuulispää tuli sinun päälles, ja koettelin sinua riitaveden tykönä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Kuule, minun kansani, minä todistan sinun seassas: Israel, jospa sinä minua kuulisit!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Ei pidä sinun seassas muukalainen jumala oleman, ja ei pidä sinun vierasta jumalaa kumartaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Minä olen Herra sinun Jumalas, joka sinun vein ulos Egyptin maalta: levitä suus, niin minä sen täytän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Mutta minun kansani ei kuullut minun ääntäni, ja Israel ei totellut minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Niin minä laskin heitä sydämensä pahuuteen, vaeltamaan neuvonsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Jos minun kansani kuulis minua, ja Israel minun teissäni kävis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Niin minä pian heidän vihollisensa painaisin alas, ja käteni kääntäisin heidän vihollistensa päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Ja Herran viholliset hukkaan tulisivat; mutta heidän aikansa olisi ijankaikkisesti pysyvä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Ja minä ruokkisin heitä parhailla nisuilla, ja ravitsisin heitä hunajalla kalliosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Asaphin Psalmi. Jumala seisoo Jumalan seurakunnassa: hän on tuomari Jumalain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Kuinka kauvan te väärin tuomitsette, ja jumalattoman muotoa katsotte? Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Tehkää oikeus köyhälle ja orvolle, ja auttakaat raadolliset ja vaivaiset oikeudelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Pelastakaat ylönkatsottua ja köyhää, ja päästäkäät häntä jumalattoman kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Mutta ei he tottele eikä lukua pidä: he käyvät lakkaamata pimeässä: sentähden täytyy kaikki maan perustukset kaatua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Minä tosin sanoin: te olette jumalat, ja kaikki Korkeimman lapset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Kuitenkin täytyy teidän kuolla niinkuin ihmiset, ja niinkuin tyrannit hukkua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Nouse, Jumala, ja tuomitse maa; sillä kaikki pakanat ovat sinun omas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Asaphin Psalmi ja veisu. (H83:2) Jumala, älä niin ratki vaikene, ja älä niin ääneti ole: Jumala, älä sitä niin kärsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Sillä katso, Sinun vihollises kiukuitsevat, ja jotka sinua vihaavat, ylentävät päänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'He pitävät kavaloita juonia sinun kansaas vastaan, ja pitävät neuvoa sinun salatuitas vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Sanoen: tulkaat, hävittäkäämme heitä, niin ettei he ensinkään kansa olisikaan, ettei Israelin nimeä silleen muisteltaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Sillä he ovat sydämessänsä panneet neuvonsa yhteen, ja tehneet liiton sinua vastaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Edomilaiset ja Ismaelilaiset majat, Moabilaiset ja Hagarilaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebalilaiset, Ammonilaiset ja Amalekilaiset, Philistealaiset ja Tyron asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Assur on myös itsensä heihin liittänyt, auttamaan Lotin lapsia, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Tee niille niinkuin Midianilaisille, niinkuin Siseralle, niinkuin Jabinille Kisonin ojan tykönä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Jotka mestattiin Endorin tykönä, ja tulivat loaksi maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Tee heidän pääruhtinaansa niinkuin Orebin ja Seebin, ja kaikki heidän ylimmäisensä niinkuin Seban ja Salmunnan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Jotka sanovat: me omistamme meillemme Jumalan huoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Jumala, tee heitä niinkuin rattaan, niinkuin korren tuulen edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Niinkuin kulo metsän polttaa, ja niinkuin liekki mäet sytyttää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Vainoo juuri niin heitä sinun rajuilmallas, ja hämmästytä heitä tuulispäälläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Täytä heidän kasvonsa häpiällä, että he sinun nimeäs, Herra, etsisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Hävetköön he ja hämmästyköön ijankaikkisesti, ja häpiään tulkoon ja hukkukoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Niin he saavat tuta, että sinä, jonka ainoan nimi on Herra, olet ylimmäinen kaikessa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Koran lasten Psalmi, Gittitin päällä, edelläveisaajalle. (H84:2) Kuinka ihanat ovat sinun asuinsijas, Herra Zebaot!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Minun sieluni ikävöitsee ja halajaa Herran esikartanoihin: minun ruumiini ja sieluni iloitsee elävässä Jumalassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Sillä lintu on huoneen löytänyt, ja pääskynen pesänsä, johonka he poikansa laskevat: sinun alttaris, Herra Zebaot, minun kuninkaani ja minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Autuaat ovat, jotka sinun huoneessas asuvat: he kiittävät sinua ijankaikkisesti, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Autuaat ovat ne ihmiset, jotka sinun pitävät väkenänsä, ja sydämestänsä vaeltavat sinun jälkees,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Jotka käyvät itkun laakson lävitse, ja tekevät siellä kaivoja; ja opettajat monella siunauksella kaunistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'He saavat yhden voiton toisen jälkeen, että tunnettaisiin oikia Jumala Zionissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Herra Jumala Zebaot, kuule minun rukoukseni: ota, Jakobin Jumala, tätä korviis, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Katsele siis, Jumala, meidän kilpemme, katso sinun voideltus kasvoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Sillä yksi päivä esikartanoissas on parempi kuin tuhannen muualla: ennen minä olisin ovenvartia Jumalani huoneessa, kuin asuisin jumalattomain majoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Sillä Herra Jumala on aurinko ja kilpi: Herra antaa armon ja kunnian: ei hän anna hurskailta mitään hyvää puuttua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Herra Zebaot, autuas on se ihminen, joka sinuun uskaltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Koran lasten Psalmi, edelläveisaajalle. (H85:2) Herra, sinä kuin (muinen) olit armollinen sinun maakunnalles, ja Jakobin vangit lunastit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Sinä anteeksi annoit kansas pahat teot, ja kaikki heidän syntinsä peitit, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Sinä lepytit kaiken vihas, ja käänsit sinuas vihas julmuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Käännä meitä, meidän autuutemme Jumala, ja pane pois vihas meistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Tahdotkos siis ijankaikkisesti olla vihainen meidän päällemme? eli vihas pitää sukukunnasta sukukuntaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Etkös käänny, ja meitä virvoita, että kansas sinussa iloitsis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Herra, osoita meille armos, ja sinun autuutes anna meille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Jospa minä kuulisin, mitä Herra Jumala puhuu, että hän rauhan lupasi kansallensa ja pyhillensä, ettei he hulluuteen joutuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Kuitenkin on hänen apunsa niiden tykönä, jotka häntä pelkäävät, että meidän maallamme kunnia asuis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Että laupius ja totuus keskenänsä kohtaisivat: vanhurskaus ja rauha toinen toisellensa suuta antaisivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Että totuus maasta vesois, ja vanhurskaus taivaasta katsois;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Että myös meille Herra hyvin tekis, ja meidän maamme hedemänsä antais;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Että vanhurskaus sittenkin hänen edessänsä pysyis ja menestyis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Davidin rukous. Kallista, Herra, korvas ja kuule minua; sillä minä olen raadollinen ja köyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Kätke minun sieluni; sillä minä olen pyhä. Auta minua, minun Jumalani, palveliaas, joka sinuun luotan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Herra, ole minulle armollinen; sillä minä huudan ylipäivää sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Ilahuta palvelias sielu; sillä sinun tykös, Herra, minä ylennän sieluni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Sillä sinä, Herra, olet hyvä ja armollinen, sangen laupias kaikille, jotka sinua avuksensa huutavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Ota korviis, Herra, minun rukoukseni, ja ota vaari minun rukoukseni äänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Tuskassani minä sinua rukoilen, ettäs minun kuulisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Herra! ei ole yksikään jumalista sinun kaltaises, ja ei ole kenkään, joka niin tehdä taitaa kuin sinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Kaikki pakanat, jotka tehnyt olet, pitää tuleman ja kumartaman sinua, Herra, ja sinun nimeäs kunnioittaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Ettäs niin suuri olet, ja teet ihmeitä; ja sinä olet yksinäs Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Osoita minulle, Herra, sinun ties, vaeltaakseni sinun totuudessas: kiinnitä minun sydämeni siihen yhteen, että minä sinun nimeäs pelkäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Minä kiitän sinua, Herra minun Jumalani, kaikesta sydämestäni, ja kunnioitan sinun nimeäs ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Sillä sinun hyvyytes on suuri minussa, ja sinä olet pelastanut sieluni syvimmästä helvetistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Jumala! ylpiät karkaavat minua vastaan, ja julmain joukot väijyvät minun sieluani, ja ei pidä sinua silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Mutta sinä, Herra Jumala, olet armollinen ja laupias, kärsiväinen ja sangen hyvä ja vakaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Käännä itses minuun päin, ole minulle armollinen; vahvista palveliaas sinun voimallas, ja auta piikas poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Tee merkki minun kanssani, että minulle hyvin kävis, ja he sen näkisivät, jotka minua vihaavat, ja häpeäisivät, että sinä Herra autat ja lohdutat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Psalmi, Koran lasten veisu. Hän on vahvasti perustettu pyhäin vuorten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Herra rakastaa Zionin portteja enempi kuin kaikkia Jakobin asuinsioja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Korkiat ja kunnialliset asiat sinussa saarnataan, sinä Jumalan kaupunki, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Minä annan saarnata Rahabin ja Babelin edessä, että he minun tuntevat: katso, Philistealaiset, Tyrolaiset ja Etiopialaiset syntyvät siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Zionille pitää sanottaman, että kaikkinaiset kansat siellä syntyvät, ja että Korkein sitä rakentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Herra antaa saarnata kirjoituksessa kaikkinaisilla kielillä, että myös muutamat heistä siellä syntyvät, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Ja veisaajat niinkuin tanssissa, kaikki minun lähteeni sinussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Psalmi, Koran lasten veisu, edelläveisaajalle, raadollisten heikkoudesta, Hemanin Esrahilaisen oppi. (H88:2) Herra, minun autuuteni Jumala, minä huudan päivällä ja yöllä sinun edessäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Anna minun rukoukseni etees tulla: kallista korvas huutoni puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Sillä minun sieluni on surkeutta täynnä, ja minun elämäni on juuri liki helvettiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Minä olen arvattu niiden kaltaiseksi, jotka hautaan menevät: minä olen niinkuin se mies, jolla ei yhtään apua ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Minä makaan hyljättynä kuolleiden seassa, niinkuin haavoitetut, jotka haudassa makaavat, joita et sinä enää muista, ja jotka kädestäs eroitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Sinä olet painanut minun alimmaiseen kaivoon, pimeyteen ja syvyyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Sinun hirmuisuutes ahdistaa minua, ja pakottaa minua sinun aalloillas, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Sinä eroitat kauvas ystäväni minusta: sinä olet minun tehnyt heille kauhistukseksi: minä makaan vangittuna, etten minä voi päästä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Minun kasvoni ovat surkiat raadollisuuden tähden: Herra, minä avukseni huudan sinua joka päivä: minä hajoitan käteni sinun puolees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Teetkös siis ihmeitä kuolleiden seassa? eli nousevatko kuolleet sinua kiittämään? Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Luetellaanko haudoissa sinun hyvyyttäs? ja totuuttas kadotuksessa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Tunnetaanko sinun ihmees pimiässä? eli vanhurskautes siinä maassa, jossa kaikki unohdetaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Mutta minä huudan sinua, Herra, ja minun rukoukseni tulee varhain sinun etees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Miksis, Herra, heität pois sieluni, ja peität kasvos minulta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Minä olen raadollinen ja väetöin, että minä niin hylätty olen: minä kärsin sinun hirmuisuuttas, että minä lähes epäilen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Sinun vihas tulee minun päälleni: sinun pelkos likistää minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Ne saartavat minua joka päivä niinkuin vesi, ja ynnä minua piirittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Sinä teet, että minun ystäväni ja lähimmäiseni erkanevat kauvas minusta, ja minun tuttavilleni olen minä pimeydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Etanin sen Esrahilaisen opetus. (H89:2) Minä veisaan Herran armoja ijankaikkisesti, ja ilmoitan sinun totuuttas suullani suvusta sukuun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Ja sanon: ijankaikkinen armo käy ylös: sinä pidät uskollisesti totuutes taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Minä olen liiton tehnyt valittuini kanssa: minä olen vannonut Davidille palvelialleni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Hamaan ijankaikkisuuteen vahvistan minä sinun siemenes, ja rakennan sinun istuimes suvusta sukuun, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Ja taivaat pitää ylistämän, Herra, sinun ihmeitäs, niin myös totuuttas pyhäin seurakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Sillä kuka taidetaan pilvissä verrattaa Herraan? ja kuka on Herran kaltainen jumalain lasten seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Jumala on sangen väkevä pyhäinsä kokouksissa, ja ihmeellinen kaikkein seassa, jotka ovat hänen ympärillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Herra Jumala Zebaot, kuka on niinkuin sinä, väkevä Jumala? ja sinun totuutes on sinun ympärilläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Sinä vallitset pauhaavaisen meren: sinä hillitset paisuvaiset aallot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Sinä lyöt Rahabin kuoliaaksi: sinä hajoitat vihollises urhoollisella käsivarrellas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Taivaat ovat sinun, maa myös on sinun: sinä olet perustanut maan piirin, ja mitä siinä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Pohjan ja etelän olet sinä luonut: Tabor ja Hermon kiittävät sinun nimeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Sinulla on voimallinen käsivarsi: väkevä on sinun kätes, ja korkia on oikia kätes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Vanhurskaus ja tuomio on istuimes vahvistus: armo ja totuus ovat sinun kasvois edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Autuas on se kansa, joka ihastua taitaa: Herra, heidän pitää vaeltaman sinun kasvois valkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Heidän pitää iloitseman joka päivä sinun nimestäs, ja sinun vanhurskaudessas kunnialliset oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Sillä sinä olet heidän väkevyytensä kerskaus, ja sinun armos kautta nostat sinä ylös meidän sarvemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Sillä Herra on meidän kilpemme, ja pyhä Israelissa on meidän kuninkaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Silloin sinä puhuit näyissä pyhilles ja sanoit: minä olen sankarin herättänyt auttamaan: minä olen korottanut valitun kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Minä olen löytänyt palveliani Davidin: minä olen hänen voidellut pyhällä öljylläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Minun käteni tukee häntä, ja minun käsivarteni vahvistaa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Ei pidä viholliset häntä voittaman, ja väärät ei pidä häntä sulloman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Vaan minä lyön hänen vihollisensa hänen edestänsä; ja niitä, jotka häntä vihaavat, tahdon minä vaivata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Mutta minun totuuteni ja armoni pitää hänen tykönänsä oleman, ja hänen sarvensa pitää minun nimeeni nostettaman ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Minä asetan hänen kätensä mereen, ja hänen oikian kätensä virtoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Näin hänen pitää minun kutsuman: sinä olet minun Isäni, Jumalani ja turvani, joka minua auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Ja minä asetan hänen esikoiseksi, kaikkein korkeimmaksi kuningasten seassa maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Minä pidän hänelle armoni tähteellä ijankaikkisesti, ja minun liittoni pitää hänelle vahva oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Minä annan hänelle ijankaikkisen siemenen, ja vahvistan hänen istuimensa niinkauvan kuin taivaat pysyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Mutta jos hänen lapsensa minun lakini hylkäävät, ja ei vaella minun oikeudessani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Jos he minun säätyni turmelevat, ja ei minun käskyjäni pidä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Niin minä heidän syntinsä vitsalla rankaisen, ja heidän pahat tekonsa haavoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Mutta armoani en minä hänestä käännä pois, enkä salli totuuteni vilpistellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'En minä riko liittoani, ja mitä minun suustani käynyt on, en minä muuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Minä olen vihdoin vannonut pyhyyteni kautta: en minä Davidille valehtele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Hänen siemenensä on oleva ijankaikkisesti, ja hänen istuimensa minun edessäni niinkuin aurinko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Ja niinkuin kuu, vahvistetaan se ijankaikkisesti, ja on vahvana niinkuin todistus pilvissä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Vaan nyt sinä syökset ja heität pois, ja vihastut voidellulles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Sinä särjet palvelias liiton, ja tallaat hänen kruununsa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Sinä rikot hänen muurinsa, ja annat hänen linnansa särjettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Häntä raatelevat kaikki ohitsekäyväiset: hän on tullut läsnäolevaisillensa nauruksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Sinä korotat hänen vihollistensa oikian käden, ja ilahutat kaikki hänen vainollisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Hänen miekkansa voiman olet sinä myös ottanut pois, ja et salli hänen voittaa sodassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Sinä hävitit hänen puhtautensa, ja annoit hänen istuimensa kaatua maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Sinä lyhennät hänen nuoruutensa ajat, ja peität hänen häpiällä, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Herra, kuinka kauvan sinä sinus niin salaat? ja annat hirmuisuutes palaa niinkuin tulen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Muista, kuinka lyhyt minun elämäni on: miksis tahdoit kaikki ihmiset hukkaan luoda?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Kuka elää, ja ei näe kuolemaa? kuka sielunsa tuonelan käsistä pelastaa? Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Herra, kussa ovat sinun entiset armos, jotkas Davidille vannonut olet totuudessas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Muista, Herra, palveliais pilkkaa, jonka minä kannan helmassani, kaikista niin monista kansoista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Joilla, Herra, vihollises pilkkaavat, joilla he pilkkaavat voideltus askelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Kiitetty olkoon Herra ijankaikkisesti, amen! ja amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Moseksen Jumalan miehen rukous. Herra, sinä olet meidän turvamme, suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Ennenkuin vuoret olivat, eli maa ja maailma luotiin, olet sinä Jumala ijankaikkisesta ijankaikkiseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Sinä, joka annat ihmiset kuolla, ja sanot: tulkaat jälleen, te ihmisten lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Sillä tuhat ajastaikaa ovat sinun edessäs niinkuin eilinen päivä, joka meni ohitse, ja niinkuin vartio yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Sinä vuodatat heitä niinkuin kosken, ja he ovat niinkuin uni, niinkuin ruoho aamulla, joka kohta lakastuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Joka aamulla kukoistaa ja nopiasti kuivuu, ja ehtoona leikataan ja kuivettuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Sen tekee sinun vihas, että me niin hukumme, ja sinun hirmuisuutes, että me niin äkisti täältä temmataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Sillä meidän pahat tekomme sinä asetat etees, meidän tuntemattomat syntimme valkeuteen sinun kasvois eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Sentähden kuluvat kaikki meidän päivämme sinun vihastas: meidän vuotemme loppuvat pikemmin kuin juttu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Meidän elinaikamme on seitsemänkymmentä vuotta, taikka enintään kahdeksankymmentä vuotta: ja kuin se paras on ollut, niin on se tuska ja työ ollut: sillä se leikataan pois. niinkuin me lentäisimme pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Mutta kuka uskoo sinun niin raskaasti vihastuvan? ja kuka pelkää senkaltaista hirmuisuuttas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Opeta meitä ajattelemaan, että meidän pitää kuoleman, että me ymmärtäväisiksi tulisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Herra! käännä siis itses taas meidän puoleemme, ja ole palvelioilles armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Täytä meitä pian armoillas, niin me riemuitsemme ja iloitsemme kaikkena meidän elinaikanamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Ilahuta nyt meitä jälleen, ettäs meitä niin kauvan vaivannut olet, että me niin kauvan onnettomuutta kärsineet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Osoita palvelialles sinun tekos, ja kunnias heidän lapsillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Ja, Herra meidän Jumalamme olkoon meille leppyinen, ja vahvistakoon meidän kättemme teot meissä: jaa, meidän kättemme teot hän vahvistakoon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Joka Korkeimman varjeluksessa istuu ja Kaikkivaltiaan varjossa oleskelee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Hän sanoo Herralle: minun toivoni ja linnani, minun Jumalani, johon minä uskallan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Sillä hän pelastaa sinun väijyjän paulasta, ja vahingollisesta ruttotaudista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Hän sulillansa sinua varjoo, ja sinun turvas on hänen siipeinsä alla: hänen totuutensa on keihäs ja kilpi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Ettes pelkäisi yön kauhistusta, ja nuolia, jotka päivällä lentävät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Sitä ruttoa, joka pimeässä liikkuu, ja sairautta, joka puolipäivänä turmelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Vaikka tuhannen lankeisi sivullas, ja kymmenentuhatta sinun oikiallas, niin ei se sinuun satu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Ja tosin sinun pitää silmilläs näkemän ja katsoman, kuinka jumalattomille kostetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Sillä Herra on sinun toivos, ja Ylimmäinen on sinun turvas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Ei sinua pidä mikään paha kohtaaman, ja ei yhtään vaivaa pidä sinun majaas lähestymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Sillä hän on antanut käskyn enkeleillensä sinusta, että he kätkevät sinua kaikissa teissäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Että he kantavat sinua käsissä, ettes jalkaas kiveen loukkaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Sinä käyt jalopeuran ja kyykäärmeen päällä, ja tallaat nuoren jalopeuran ja lohikäärmeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Että hän minua halasi, niin minä hänen päästän: hän tuntee minun nimeni, sentähden minä varjelen häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Hän avuksihuutaa minua, sentähden minä kuulen häntä; hänen tykönänsä olen minä tuskassa; siitä minä hänen tempaan pois ja saatan hänen kunniaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Minä ravitsen hänen pitkällä ijällä, ja osoitan hänelle autuuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psalmi sabbatina veisattava. (H92:2) Hyvä on Herraa kiittää, ja veisata kiitosta sinun nimelles, sinä kaikkein Ylimmäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Aamulla julistaa armoas, ja ehtoolla totuuttas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Kymmenkielisellä ja psaltarilla, soittain kanteleilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Sillä sinä ilahutit minua, Herra, sinun teoissas: ja minä iloiten kerskaan kättes töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Herra, kuinka sinun tekos ovat niin suuret? Sinun ajatukses ovat ylen syvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Hullu ei usko sitä, ja tomppeli ei ymmärrä niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Jumalattomat viheriöitsevät niinkuin ruoho, ja pahointekiät kaikki kukoistavat, siihenasti kuin he hukkuvat ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Mutta sinä, Herra, olet korkein, ja pysyt ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Sillä katso, sinun vihollises, Herra, katso, sinun vihollises pitää katooman, ja kaikki pahantekiät pitää hajoitettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Mutta minun sarveni tulee korotetuksi niinkuin yksisarvisen, ja minä voidellaan tuoreella öljyllä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Ja minun silmäni näkevät viholliseni, ja minun korvani kuulevat pahoja, jotka heitänsä asettavat minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Vanhurskaan pitää viheriöitsemän niinkuin palmupuu, ja kasvaman niinkuin sedripuu Libanonissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Jotka ovat istutetut Herran huoneessa, pitää viheriöitsemän meidän Jumalamme kartanoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Heidän pitää vesoman vielä vanhuudessansa, hedelmälliset ja vihannat oleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Ja julistaman, että Herra on niin hurskas, minun turvani, ja ei ole hänessä vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Herra on kuningas: hän on pukenut yllensä suuren kunnian: Herra on pukenut ja vyöttänyt itsensä väkevyydellä, ja on vahvistanut maan piirin, ettei sen pidä liikkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Siitä ajasta pysyy sinun istuimes vahvana: sinä olet ijankaikkinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Herra, vesikosket paisuvat, vesikosket paisuttavat pauhinansa, vesikosket paisuttavat aaltonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Aallot meressä ovat suuret ja pauhaavat hirmuisesti; mutta Herra on vielä väkevämpi korkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Sinun todistukses ovat aivan lujat: pyhyys on sinun huonees kaunistus, Herra, ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Herra Jumala, jonka kostot ovat, Jumala, jonka kostot ovat, selkiästi itses näytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Korota sinuas, maailman tuomari: maksa ylpeille, mitä he ansainneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Herra, kuinka kauvan pitää jumalattomain, kuinka kauvan pitää jumalattomain riemuitseman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Tiuskuman ja puhuman niin ylpiästi, ja kaikki pahantekiät niin kerskaaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Herra, he polkevat alas sinun kansas, ja sinun perimistäs he vaivaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Lesket ja muukalaiset he tappavat, ja orvot he kuolettavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Ja sanovat: ei Herra sitä näe, ja Jakobin Jumala ei sitä tottele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Ymmärtäkäät siis, te hullut kansan seassa! ja, te tyhmät, koska te taitaviksi tulette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Joka korvan on istuttanut, eikö hän kuule? eli joka silmän loi, eikö hän näe?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Joka pakanoita kurittaa, eikö hän rankaise, joka ihmisille opettaa tiedon?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Mutta Herra tietää ihmisten ajatukset, että ne turhat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Autuas on se, jota sinä, Herra, kuritat, ja opetat sinun laistas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Että hänellä kärsivällisyys olis, koska vastoin käy, siihenasti kuin jumalattomalle hauta valmistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Sillä ei Herra heitä kansaansa pois, eli hylkää perimistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Sillä oikeuden pitää sittekin oikeuden oleman, ja kaikki hurskaat sydämet sitä seuraavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kuka seisoo minun kanssani pahoja vastaan? kuka astuu minun tyköni pahointekiöitä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Ellei Herra minua auttaisi, niin minun sieluni makais lähes hiljaisuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Minä sanoin: minun jalkani on horjunut, vaan sinun armos, Herra, minun tukesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Minulla oli paljo surua sydämessäni; mutta sinun lohdutukses ilahutti minun sieluni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Etpäs mielisty koskaan tosin vahingolliseen istuimeen, joka lain häijysti opettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'He kokoovat joukkonsa vanhurskaan sielua vastaan, ja tuomitsevat viattoman veren kadotukseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mutta Herra on minun varjelukseni: minun Jumalani on minun uskallukseni turva,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Ja hän kostaa heidän vääryytensä, ja hukuttaa heitä heidän pahuutensa tähden: Herra, meidän Jumalamme, hukuttaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Tulkaat, veisatkaamme kiitosta Herralle, ja iloitkaamme meidän autuutemme turvalle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Tulkaamme hänen kasvoinsa eteen kiitoksella, ja riemuitkaamme hänelle lauluilla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Sillä Herra on suuri Jumala, ja suuri kuningas kaikkein jumalain ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Sillä hänen kädessänsä on kaikki, mitä maa kantaa, ja vuorten kukkulat ovat myös hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Sillä hänen on meri, ja hän on sen tehnyt, ja hänen kätensä ovat kuivan valmistaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Tulkaat, kumartakaamme ja polvillemme langetkaamme, ja maahan laskeukaamme Herran meidän Luojamme eteen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Sillä hän on meidän Jumalamme ja me hänen elatuskansansa, ja hänen kättensä lauma. Tänäpänä, jos kuulette hänen äänensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Niin älkäät paaduttako sydämiänne, niinkuin Meribassa tapahtui, niinkuin kiusauksen päivänä korvessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Kussa isänne minua kiusasivat, koettelivat minua, ja näkivät myös minun tekoni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Että minä neljäkymmentä ajastaikaa suutuin tähän kansaan, ja sanoin: se on senkaltainen kansa, jonka sydämet aina eksyä tahtovat, ja jotka minun tietäni ei tahtoneet oppia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Joille minä vihoissani vannoin: ettei heidän pidä minun lepooni tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Veisatkaat Herralle uusi veisu: veisatkaat Herralle, kaikki maa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Veisatkaat Herralle, ja kiittäkäät hänen nimeänsä: julistakaat päivä päivältä hänen autuuttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Luetelkaat pakanain seassa hänen kunniaansa, kaikkein kansain seassa hänen ihmeitänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Sillä Herra on suuri ja sangen kiitettävä, ihmeellinen kaikkein jumalain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Sillä kaikki kansain jumalat ovat epäjumalat; mutta Herra on taivaat tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Kunnia ja kaunistus ovat hänen edessänsä, väkevyys ja kauneus hänen pyhässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Kansain sukukunnat, tuokaat Herralle, tuokaat Herralle kunnia ja voima!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Tuokaat Herralle hänen nimensä kunnia: tuokaat lahjoja ja tulkaat hänen esihuoneisiinsa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Kumartakaat Herraa pyhässä kaunistuksessa: peljätkään häntä kaikki maailma!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Sanokaat pakanain seassa: Herra on kuningas, joka maan piirin on vahvistanut, ettei se liiku, ja tuomitsee kansan oikeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Taivaat riemuitkaan, ja maa iloitkaan: meri pauhatkaan ja mitä siinä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Kedot olkaan iloiset, ja kaikki mitkä hänessä ovat, ja kaikki puut ihastukaan metsissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Herran edessä; sillä hän tulee, hän tulee tuomitsemaan maata. Hän tuomitsee maan piirin vanhurskaudessa ja kansat totuudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Herra on kuningas, siitä maa iloitkaan: olkoon saaret riemuiset, niin monta kuin heitä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Pilvet ja pimeys ovat hänen ympärillänsä: vanhurskaus ja tuomio ovat hänen istuimensa vahvistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Tuli käy hänen edellänsä ja polttaa ympärillä hänen vihollisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Hänen leimauksensa välkkyvät maan piirin päällä: maa näkee sen ja vapisee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Vuoret sulavat niinkuin vedenvaha Herran edessä, koko maailman Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Taivaat julistavat hänen vanhurskauttansa, ja kaikki kansat näkevät hänen kunniansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Hävetkäät kaikki, jotka kuvia palvelevat, ja kerskaavat epäjumalista: kumartakaat häntä kaikki enkelit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Zion kuulee sen ja iloitsee, ja Juudan tyttäret ovat riemuissansa, Herra, sinun hallituksestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Sillä sinä, Herra, olet Korkein kaikissa maakunnissa: sinä olet sangen suuresti korotettu kaikkein jumalain ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Te kuin Herraa rakastatte, vihatkaat pahaa! hän kätkee pyhäinsä sielut: jumalattomain käsistä hän heitä pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Vanhurskaalle koittaa valkeus, ja ilo hurskaille sydämille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Vanhurskaat iloitkaat Herrassa, kiittäkäät hänen pyhyytensä muistoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psalmi. Veisatkaat Herralle uusi veisu; sillä hän tekee ihmeitä. Hän saa voiton oikialla kädellänsä ja pyhällä käsivarrellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Herra antaa tiettäväksi tehdä autuutensa: kansain edessä hän ilmoittaa vanhurskautensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Hän muistaa armonsa ja totuutensa Israelin huoneelle: kaikki maailman ääret näkevät meidän Jumalamme autuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Riemuitkaat Herralle kaikki maa: veisatkaat, ylistäkäät ja kiittäkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Kiittäkäät Herraa kanteleella, kanteleella ja psalmilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Vaskitorvilla ja basunilla: riemuitkaat Herran, kuninkaan, edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Meri pauhatkaan ja kaikki, mitä hänessä on, maan piiri ja jotka asuvat sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Kosket pauhatkaan ilosta, ja kaikki vuoret olkaan iloiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Herran edessä; sillä hän tulee maata tuomitsemaan: hän tuomitsee maan piirin vanhurskaudella ja kansat oikeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Herra on Kuningas, kansat kiukuitsevat: hän istuu Kerubimin päällä, sentähden liikkuu maailma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Suuri on Herra Zionissa, ja korkein kaikkein kansain ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Kiittäkään he sinun suurta ja ihmeellistä nimeäs, joka pyhä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Ja Kuninkaan voima rakastaa oikeutta: sinä toimitat oikeuden, sinä saatat tuomion ja vanhurskauden Jakobissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Korottakaat Herraa meidän Jumalaamme, ja kumartakaat hänen astinlautansa juuressa, sillä hän on pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Moses ja Aaron hänen pappeinsa seassa, ja Samuel niiden seassa, jotka hänen nimeänsä avuksensa huutavat: he avuksensa huutavat Herraa, ja hän kuulee heidän rukouksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Hän puhui heille pilven patsaasta: he pitivät hänen todistuksensa ja säätynsä, jonka hän heille antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Herra, sinä olet Jumalamme, sinä kuulit heidän rukouksensa: sinä, Jumala, annoit heille anteeksi, ja laitit heidän työnsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Korottakaat Herraa meidän Jumalaamme, ja kumartakaat hänen pyhällä vuorellansa; sillä Herra meidän Jumalamme on pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Kiitos-Psalmi. Riemuitkaat Herralle, kaikki maa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Palvelkaat Herraa ilolla: tulkaat hänen kasvoinsa eteen riemulla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Tietäkäät, että Herra on Jumala: hänpä meidän teki, ja emme itse meitämme, kansaksensa ja laitumensa lampaiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Menkäät hänen porttiinsa kiitoksella, hänen esihuoneisiinsa veisulla: kiittäkäät häntä ja ylistäkäät hänen nimeänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Sillä Herra on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti, ja hänen totuutensa sukukunnasta sukukuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Davidin Psalmi. Minä veisaan armosta ja oikeudesta: sinulle, Herra, minä veisaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Minä tahdon vaarin ottaa oikiasta tiestä, koskas minun tyköni tulet: minä tahdon vaeltaa sydämeni vakuudessa minun huoneessani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'En minä ota pahaa asiaa eteeni: minä vihaan väärintekiöitä, ja en salli heitä olla tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Nurja sydän olkoon minusta pois: en minä kärsi pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Joka lähimmäistänsä salaa panettelee, sen minä hukutan: en minä kärsi ylpeitä ja röyhkeitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Minun silmäni katsovat uskollisia maan päällä, että he asuisivat minun tykönäni: joka vaeltaa oikialla tiellä, se pitää oleman minun palveliani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Petollisia ihmisiä en minä pidä huoneessani: ei valehteliat menesty minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Varhain minä hukutan kaikki jumalattomat maasta, hävittääkseni kaikkia pahantekiöitä Herran kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Raadollisen rukous, kuin hän murheissansa on, ja valituksensa Herran eteen vuodattaa. (H102:2) Herra, kuule minun rukoukseni, ja anna minun huutoni tykös tulla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Älä kasvojas minulta peitä hädässä: kallista korvas minun puoleeni; koska minä sinua rukoilen, niin kuule pian minun rukoukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Sillä minun päiväni ovat kuluneet niinkuin savu, ja minun luuni ovat poltetut niinkuin kekäle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Minun sydämeni on lyöty ja kuivettunut niinkuin heinä, niin että minä myös unohdan leipäni syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Minun luuni tarttuvat lihaani huokauksestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Minä olen niinkuin ruovonpäristäjä korvessa: minä olen niinkuin hyypiä hävitetyissä kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Minä valvon, ja olen niinkuin yksinäinen lintu katon päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Joka päivä häpäisevät viholliseni minua, ja jotka minua syljeskelevät, vannovat minun kauttani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Sillä minä syön tuhkaa niinkuin leipää, ja sekoitan juomani itkulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Sinun uhkaukses ja vihas tähden, ettäs minun nostanut olet ja paiskannut maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Minun päiväni ovat kuluneet niinkuin varjo, ja minä kuivetun niinkuin ruoho.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Mutta sinä, Herra, pysyt ijankaikkisesti, ja sinun muistos sukukunnasta sukukuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Nouse siis ja armahda Zionia; sillä aika on häntä armahtaa, ja aika on tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Sillä sinun palvelias halajavat sitä rakentaa, ja näkisivät mielellänsä, että hänen kivensä ja kalkkinsa valmiit olisivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Että pakanat Herran nimeä pelkäisivät, ja kaikki kuninkaat maan päällä sinun kunniaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Kuin Herra rakentaa Zionin, niin hän nähdään kunniassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Hän kääntää itsensä hyljättyjen rukouksen puoleen, ja ei katso heidän rukoustansa ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Se pitää kirjoitettaman tulevaisille sukukunnille, ja se kansa, joka luodaan, pitää kiittämän Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Sillä hän katselee pyhästä korkeudestansa: Herra näkee taivaasta maan päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Että hän kuulee vankein huokaukset, ja kirvoittaa kuoleman lapset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Että he saarnaavat Herran nimeä Zionissa, ja hänen kiitostansa Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Koska kansat ynnä kokoontuvat, ja valtakunnat, Herraa palvelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Hän nöyryyttää tiellä minun voimani: hän lyhentää minun päiväni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Minä sanoin: minun Jumalani, älä minua ota pois keski-ijässäni: sinun ajastaikas pysyvät suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Sinä olet muinen maan perustanut, ja taivaat ovat sinun käsialas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Ne katoovat, mutta sinä pysyt: ne kaikki vanhenevat niinkuin vaate: ne muuttuvat niinkuin vaate, koska sinä heitä muuttelet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Mutta sinä pysyt niinkuin sinä olet, ja sinun vuotes ei lopu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Sinun palveliais lapset pysyvät ja heidän sikiänsä sinun edessäs menestyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Davidin Psalmi. Kiitä Herraa, sieluni, ja kaikki mitä minussa on, hänen pyhää nimeänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Kiitä Herraa, sieluni, ja älä unohda, mitä hyvää hän minulle tehnyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Joka sinulle kaikki syntis antaa anteeksi, ja parantaa kaikki rikokses;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Joka henkes päästää turmeluksesta, joka sinun kruunaa armolla ja laupiudella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Joka suus täyttää hyvyydellä, että sinun nuoruutes uudistetaan niinkuin kotkan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Herra saattaa vanhurskauden ja tuomion kaikille, jotka vääryyttä kärsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Hän on tiensä Mosekselle tiettäväksi tehnyt, Israelin lapsille tekonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Laupias ja armollinen on Herra, kärsiväinen ja aivan hyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Ei hän aina riitele, eikä vihastu ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Ei hän synteimme perästä tee meille, eikä kosta meille pahain tekoimme jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Sillä niin korkia kuin taivas on maasta, antaa hän armonsa lisääntyä niille, jotka häntä pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Niin kaukana kuin itä on lännestä, siirsi hän meistä pahat tekomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Niinkuin isä armahtaa lapsia, niin Herrakin armahtaa pelkääväisiänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Sillä hän tietää, minkäkaltainen teko me olemme: hän muistaa meidät tomuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Ihminen on eläissänsä niinkuin ruoho: hän kukoistaa niinkuin kukkanen kedolla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Kuin tuuli käy sen päällitse, niin ei hän enään kestä, eikä hänen siansa tunne häntä ensinkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Mutta Herran armo pysyy ijankaikkisesta ijankaikkiseen, hänen pelkääväistensä päälle, ja hänen vanhurskautensa lasten lapsiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Niille, jotka hänen liittonsa pitävät, ja muistavat hänen käskyjänsä, tehdäksensä niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Herra on valmistanut istuimensa taivaassa, ja hänen valtakuntansa hallitsee kaikkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Kiittäkäät Herraa, te hänen enkelinsä, te väkevät sankarit, jotka hänen käskynsä toimitatte, että hänen sanansa ääni kuultaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Kiittäkäät Herraa, kaikki hänen sotaväkensä, te hänen palveliansa, jotka teette hänen tahtonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Kiittäkäät Herraa, kaikki hänen työnsä, kaikissa hänen valtansa paikoissa: kiitä, sieluni, Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Kiitä Herraa, sieluni! Herra, minun Jumalani, sinä olet sangen suuresti kunnioitettu, suurella kunnialla ja kaunistuksella olet sinä puetettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Sinä puetat itses valkeudella niinkuin vaatteella: sinä levität taivaat niinkuin peitteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Sinä peität sen päällyksen vedellä: sinä menet pilvissä niinkuin ratasten päällä, ja käyt tuulen siipein päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Sinä teet enkelis hengeksi ja palvelias liekitseväiseksi tuleksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Sinä joka maan perustit perustuksensa päälle, ettei sen pidä liikkuman ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Syvyydellä sinä sen peität niinkuin vaatteella, ja vedet seisovat vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Mutta sinun nuhtelemisestas he pakenevat: sinun jylinästäs he menevät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Vuoret astuvat ylös, ja laaksot astuvat alas siallensa, johon heidät perustanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Määrän sinä panit, jota ei he käy ylitse, eikä palaja maata peittämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Sinä annat lähteet laaksoissa kuohua, niin että ne vuorten välitse vuotavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Että kaikki eläimet metsässä joisivat, ja että pedot janonsa sammuttaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Heidän tykönänsä istuvat taivaan linnut, ja visertävät oksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Sinä liotat vuoret ylhäältä: sinä täytät maan hedelmällä, jonka sinä saatat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Sinä kasvatat ruohon karjalle, ja jyvät ihmisten tarpeeksi, tuottaakses leipää maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Ja että viina ihmisen sydämen ilahuttaa, ja hänen kasvonsa kaunistuu öljystä: ja leipä vahvistaa ihmisen sydämen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Että Herran puut nesteestä täynnä olisivat: Libanonin sedripuut, jotka hän on istuttanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Siellä linnut pesiä tekevät, ja haikarat hongissa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Korkiat vuoret ovat metsävuohten turva, ja kivirauniot kaninein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Sinä teet kuun aikoja jakamaan, ja aurinko tietää laskemisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Sinä teet pimeyden ja yö tulee: silloin kaikki metsän eläimet tulevat ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Nuoret jalopeurat saaliin perään kiljuvat, ja elatustansa Jumalalta etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Mutta kuin aurinko koittaa, niin he kokoontuvat, ja luolissansa makaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Niin menee myös ihminen työhönsä, ja askareillensa ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Herra, kuinka suuret ja monet ovat sinun käsialas? Sinä olet kaikki taitavasti säätänyt, ja maa on täynnä sinun tavaraas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Tämä meri, joka niin suuri ja lavia on, siinä epälukuiset liikuvat, sekä pienet että suuret eläimet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Siellä haahdet kuljeskelevat: siinä valaskalat ovat, jotkas tehnyt olet, leikitsemään hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Kaikki odottavat sinua, ettäs heille antaisit ruan ajallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Koskas heille annat, niin he kokoovat: koskas kätes avaat, niin he hyvyydellä ravitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Jos sinä kasvos peität, niin he hämmästyvät: koska sinä otat heidän henkensä pois, niin he hukkuvat, ja tomuksi tulevat jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Sinä lähetät ulos henkes, niin he luoduksi tulevat, ja sinä uudistat maan muodon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Herran kunnia pysyy ijankaikkisesti: Herra iloitsee töissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Hän katsahtaa maan päälle, niin se vapisee: hän rupee vuoriin, niin ne suitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Minä veisaan Herralle minun elinaikanani, ja kiitän minun Jumalaani niinkauvan kuin minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Minun puheeni kelpaa hänelle, ja minä iloitsen Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Syntiset maalta lopetetaan, ja jumalattomat ei pidä silleen oleman: kiitä Herraa, sieluni, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Kiittäkäät Herraa, ja saarnatkaat hänen nimeänsä, julistakaat hänen töitänsä kansain seassa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Veisatkaat hänelle, soittakaat hänelle, puhukaat kaikista hänen ihmeistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Ylistäkäät hänen pyhää nimeänsä: niiden sydän iloitkaan, jotka etsivät Herraa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Kysykäät Herraa ja hänen voimaansa, etsikäät alati hänen kasvojansa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Muistakaat hänen ihmeellisiä töitänsä, jotka hän tehnyt on, hänen ihmeitänsä ja hänen sanojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Te Abrahamin hänen palveliansa siemen, te Jakobin hänen valittunsa lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Hänpä on Herra meidän Jumalamme: hän tuomitsee kaikessa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Hän muistaa liittonsa ijankaikkisesti, sanansa, jonka hän on käskenyt tuhannelle sukukunnalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Jonka hän teki Abrahamin kanssa, ja valansa Isaakin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Ja pani sen Jakobille säädyksi ja Israelille ijankaikkiseksi liitoksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Ja sanoi: sinulle minä annan Kanaanin maan, teidän perimisenne arvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Koska heitä vähä ja harvat olivat, ja he olivat muukalaiset siinä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Ja vaelsivat kansasta kansaan ja valtakunnasta toiseen kansaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Ei hän sallinut yhdenkään ihmisen heitä vahingoittaa, vaan rankaisi kuninkaat heidän tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Älkäät ruvetko minun voideltuihini, ja älkäät tehkö pahaa minun prophetailleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Ja hän kutsui nälän maan päälle, ja vei kaiken leivän varan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Hän lähetti miehen heidän eteensä: Joseph myytiin orjaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'He ahdistivat hänen jalkansa jalkapuuhun: hänen ruumiinsa täytyi raudoissa maata,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Siihenasti että hänen sanansa tuli, ja Herran puhe koetteli hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Niin lähetti kuningas ja päästi hänen: kansain päämies laski hänen vallallensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Ja asetti hänen huoneensa herraksi, ja kaiken tavaransa haltiaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Opettamaan päämiehiänsä oman tahtonsa jälkeen, ja vanhimmille viisautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Ja Israel meni Egyptiin, ja Jakob tuli muukalaiseksi Hamin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Ja hän antoi kansansa sangen suuresti kasvaa, ja teki heitä väkevämmäksi kuin heidän vihollisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Hän käänsi heidän sydämensä vihaamaan hänen kansaansa, ja hänen palvelioitansa viekkaudella painamaan alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Hän lähetti palveliansa Moseksen, ja Aaronin, jonka hän valitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Ne tekivät hänen merkkinsä heidän seassansa, ja hänen ihmeensä Hamin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Hän antoi pimeyden tulla, ja sen pimeytti; ja ei olleet he hänen sanoillensa kuulemattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Hän muutti heidän vetensä vereksi ja kuoletti heidän kalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Heidän maansa kuohutti sammakoita, heidän kuningastensa kammioissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Hän sanoi, niin turilaat ja täit tulivat heidän maansa ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Hän antoi rakeet heille sateeksi, tulen liekit heidän maallensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Ja löi heidän viinapuunsa ja fikunapuunsa, ja särki puut heidän maansa äärissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Hän sanoi, niin tulivat epälukuiset paarmat ja vapsaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Ja ne söivät kaiken ruohon heidän maaltansa, ja ne söivät heidän maansa hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Ja hän löi kaikki esikoiset heidän maallansa, ensimäiset kaikesta heidän voimastansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Ja vei heitä hopialla ja kullalla ulos: ja ei ollut heidän sukukunnissansa yksikään sairas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egypti iloitsi heidän lähtemisestänsä; sillä heidän pelkonsa oli tullut heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Hän levitti pilven verhoksi ja tulen yötä valistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'He anoivat, niin antoi hän metsäkanat tulla, ja ravitsi heitä taivaan leivällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Hän avasi kallion, niin vesi vuoti, ja virrat juoksivat kuivaa myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Sillä hän muisti pyhän sanansa, jonka hän palveliallensa Abrahamille puhunut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Ja vei kansansa ilolla ulos, ja valittunsa riemulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Ja antoi heille pakanain maan, niin että he kansain hyvyydet omistivat heillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Että he pitäisivät hänen säätynsä, ja hänen lakinsa kätkisivät, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja. Kiittäkäät Herraa! sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kuka taitaa puhua ulos Herran suurta voimaa, ja ylistää kaikkia hänen kiitettäviä tekojansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Autuaat ovat, jotka käskyn pitävät ja aina vanhurskauden tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Herra, muista minua armos perästä, jonkas kansalles luvannut olet: opi minua sinun autuudellas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Että minä näkisin valittujes menestyksen, ja iloitsisin kansas ilossa, ja kerskaisin perimises kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Me teimme syntiä meidän isäimme kanssa: me teimme väärin, ja olemme olleet jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Ei meidän isämme tahtoneet ymmärtää Egyptissä sinun ihmeitäs, eikä muistaneet sinun suurta laupiuttas, ja olivat meren tykönä tottelemattomat, Punaisen meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Kuitenkin autti hän heitä nimensä tähden, niin että hän voimansa osoitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Ja hän uhkasi Punaista merta, niin se kuivui; ja vei heitä syvyyden lävitse, niinkuin korvessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Ja vapahti heitä niiden käsistä, joka heitä vihasivat, ja lunasti heitä vihollistensa käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Ja vedet peittivät heidän vainollisensa, niin ettei yksikään eläväksi jäänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Silloin he uskoivat hänen sanansa, ja veisasivat hänen kiitoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Mutta he unohtivat pian hänen työnsä, ja ei ottaneet hänen neuvoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'He kiehuivat himosta korvessa, ja kiusasivat Jumalaa erämaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Mutta hän antoi heille heidän anomisensa, ja lähetti heille laihuuden heidän himonsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Ja he asettuivat Mosesta vastaan leirissä, Aaronia Herran pyhää vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Maa aukeni ja nieli Datanin, ja peitti Abiramin joukon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Ja tuli syttyi heidän joukossansa, ja liekki poltti jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'He tekivät vasikan Horebissa, ja kumarsivat valettua kuvaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Ja he muuttelivat kunniansa härjän muotoon, joka heiniä syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'He unohtivat Jumalan, vapahtajansa, joka oli niin suuria töitä tehnyt Egyptissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Ihmeitä Hamin maalla, ja peljättäviä töitä Punaisen meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Ja hän sanoi heitä hukuttavansa, ellei Moses hänen valittunsa olisi seisonut siinä välissä, ja palauttanut hänen vihaansa, ettei hän ratki heitä kadottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Ja he katsoivat sen ihanan maan ylön, eikä uskoneet hänen sanaansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Ja napisivat majoissansa, eikä olleet kuuliaiset Herran äänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Ja hän nosti kätensä heitä vastaan, maahan lyödäksensä heitä korvessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Ja heittääksensä heidän siemenensä pakanain sekaan, ja hajoittaaksensa heitä maakuntiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Ja he ryhtyivät BaalPeoriin, ja söivät kuolleiden (epäjumalain) uhreista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Ja vihoittivat hänen töillänsä; niin tuli myös rangaistus heidän sekaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Niin Pinehas astui edes, ja lepytti asian, ja rangaistus lakkasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Ja se luettiin hänelle vanhurskaudeksi, suvusta sukuun ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Ja vihoittivat hänen riitaveden tykönä ja tapahtui Mosekselle pahoin heidän tähtensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Sillä he saattivat hänen sydämensä murheelliseksi, niin että hän sanoissansa eksyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Ei he hukuttaneet pakanoita, niinkuin Herra heille käskenyt oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Vaan sekaantuivat pakanain sekaan, ja oppivat heidän töitänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Ja palvelivat heidän epäjumaliansa; ja ne tulivat heille paulaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Ja he uhrasivat poikansa ja tyttärensä perkeleille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Ja vuodattivat viattoman veren, poikainsa ja tyttäriensä veren, jotka he uhrasivat Kanaanealaisten epäjumalille, niin että maa veren vioilla turmeltiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Ja saastuttivat itsensä omissa töissänsä, ja tekivät huorin teoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Niin julmistui Herran viha kansansa päälle, ja hän kauhistui perimistänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Ja hylkäsi ne pakanain käsiin, että ne vallitsivat heitä, jotka heitä vihasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Ja heidän vihollisensa ahdistivat heitä, ja he painettiin heidän kätensä alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Hän monesti heitä pelasti; mutta he vihoittivat hänen neuvoillansa, ja he painettiin alas pahain tekoinsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Ja hän näki heidän tuskansa, kuin hän heidän valituksensa kuuli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Ja muisti liittonsa, jonka hän heidän kanssansa tehnyt oli, ja katui sitä suuresta laupiudestansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Ja antoi heidän löytää armon kaikkein edessä, jotka heitä vanginneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Auta meitä, Herra meidän Jumalamme, ja kokoa meitä pakanoista, että kiittäisimme sinun pyhää nimeäs, ja kehuisimme sinun kiitostas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Kiitetty olkoon Herra Israelin Jumala, ijankaikkisuudesta niin ijankaikkisuuteen: ja sanokaan kaikki kansa: Amen, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Sanokaan Herran lunastetut, jotka hän on tuskasta vapahtanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Ja jotka hän on maakunnista koonnut, idästä ja lännestä, pohjoisesta ja etelästä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Jotka eksyksissä vaelsivat korvessa umpitietä, ja ei he löytäneet kaupunkia asuaksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Isoovaiset ja janoovaiset; ja heidän sielunsa vaipui heissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Ja he huusivat Herraa tuskissansa, ja hän pelasti heitä heidän hädistänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Ja vei heitä oikiaa tietä, että he menivät asuinkaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Että hän ravitsee himoitsevaisen sielun ja täyttää isoovaisen sielun hyvyydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Jotka istuvat pimeässä ja kuoleman varjossa, vangitut ahdistuksessa ja raudoissa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Että he olivat Jumalan käskyä vastaan kovakorvaiset, ja olivat katsoneet ylön ylimmäisen lain;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Sentähden täytyi heidän sydämensä onnettomuudella vaivattaa, niin että he lankesivat, ja ei kenkään heitä auttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Ja vei heitä pimeydestä ulos ja kuoleman varjosta, ja särki heidän siteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Että hän särkee vaskiportit, ja rikkoo rautaiset salvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Hullut, jotka rangaistiin ylitsekäymisensä tähden, ja synteinsä tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Heidän sielunsa kauhistui kaikkea ruokaa, ja saivat kuolintautinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Hän lähetti sanansa ja paransi heitä, ja pelasti heitä, ettei he kuolleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Ja uhratkaan kiitosuhria, ja luetelkaan hänen tekojansa ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Jotka haaksilla meressä vaeltavat, ja asiansa toimittavat suurilla vesillä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'He näkivät Herran työt, ja hänen ihmeensä syvyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Kuin hän sanoi, ja paisutti suuren ilman, joka aallot nosti ylös,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Niin he menivät ylös taivasta kohden ja menivät syvyyteen alas, että heidän sielunsa ahdistuksesta epäili,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Että he horjuivat ja hoipertelivat niinkuin juopuneet, ja ei silleen neuvoa tietäneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Ja hän hillitsi kovan ilman, että aallot asettuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Ja he tulivat iloisiksi, että tyveni, ja hän vei heitä satamaan heidän mielensä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Ja ylistäkään häntä kansan seurakunnassa, ja kiittäkään häntä vanhimpain seassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Joka virrat teki erämaaksi, ja vesilähteet kuivaksi maaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Ettei hedelmällinen maa mitään kantanut, heidän pahuutensa tähden, jotka siinä asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Erämaan teki hän vesilammiksi ja kuivan maan vesilähteeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Ja asetti sinne isoovaiset; ja he valmistivat siihen kaupunkia, jossa he asuivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Ja kylvivät pellot ja viinapuita istuttivat, ja saivat jokavuotisen hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Ja hän siunasi heitä ja he sangen suuresti enenivät, ja hän antoi paljon karjaa heille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Jotka olivat painetut alas ja sorretut pahain väkivallalta ja ahdistukselta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Koska ylönkatse päämiesten päälle vuodatettu oli, ja kaikki maa eksyksissä ja autiona oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Ja hän varjeli köyhää raadollisuudesta, ja enensi hänen sukunsa niinkuin lauman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Näitä vanhurskaat näkevät ja iloitsevat, ja jokainen paha suu pitää tukittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Kuka on taitava ja näitä kätkee, se ymmärtää Herran moninaisen laupiuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Psalmi, Davidin veisu. (H108:2) Jumala! minun sydämeni on valmis: minä veisaan ja kiitän, niin myös minun kunniani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Nouse, psaltari ja kantele; minä nousen varhain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Sinua, Herra, minä kiitän kansain seassa: minä veisaan sinulle kiitosta sukukunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Sillä sinun armos on suuri ylitse taivasten, ja sinun totuutes hamaan pilviin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Korota sinuas, Jumala, taivasten ylitse ja kunnias kaiken maan ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Että sinun rakkaat ystäväs vapaaksi tulisivat; auta oikialla kädelläs, ja kuule minun rukoukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Jumala on puhunut pyhässänsä, siitä minä iloitsen: minä jaan Sikemin, ja mittaan Sukkotin laakson.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gilead on minun, Manasse on myös minun, ja Ephraim on minun pääni väkevyys: Juuda on minun päämieheni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab on minun pesinastiani, minä venytän kenkäni Edomin päälle: Philistealaisten ylitse minä iloitsen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Kuka vie minua vahvaan kaupunkiin? kuka vie minua Edomiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Etkös sinä, Jumala, joka meitä heittänyt olet pois? Ja etkös mene ulos, Jumala, meidän sotaväkemme kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Saata meille apua tuskissamme; sillä ihmisten apu on turha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Jumalassa me tahdomme urhoollisia töitä tehdä; ja hän polkee meidän vihollisemme alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Davidin Psalmi, edelläveisaajalle. Jumala, minun kiitokseni, älä vaikene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Sillä he ovat jumalattoman ja pettäväisen suunsa avanneet minua vastaan: he puhuvat minun kanssani viekkaalla kielellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Ja myrkyllisillä sanoilla ovat he minun piirittäneet, ja sotivat minua vastaan ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Että minä heitä rakastan, ovat he minua vastaan; mutta minä rukoilen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'He osoittavat minulle pahaa hyvän edestä ja vihaa rakkauden edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Aseta jumalattomat hänen päällensä, ja perkele seisokaan hänen oikialla kädellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Koska hän tuomitaan, niin lähtekään siitä ulos jumalattomana, ja hänen rukouksensa olkoon synti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Olkoon hänen päivänsä harvat, ja hänen virkansa ottakoon toinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Hänen lapsensa olkoon orvot, ja hänen emäntänsä leski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Käykään hänen lapsensa kulkiana, ja kerjätkään, ja etsikään elatuksensa köyhyydessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Kaikki mitä hänellä on, korkorahainen ottakoon, ja muukalaiset repikään hänen hyvyytensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Älköön kenkään hänelle hyvää tehkö, eikä yksikään armahtako hänen orpojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Hänen sukunsa olkoon hävitetty: heidän nimensä olkoon toisessa polvessa pyyhitty pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Hänen isäinsä pahat teot tulkaan muistoksi Herran edessä, ja hänen äitinsä synti ei pidä pyyhittämän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Olkoon ne alati Herran kasvoin edessä, ja hukkukoon heidän muistonsa maan päältä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Ettei hänellä ensinkään laupiutta ollut, vaan vainosi raadollista ja köyhää, ja murheellista tappaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Ja hän tahtoi kirousta, sen myös pitää hänelle tuleman: ei hän tahtonut siunausta, sen pitää myös hänestä kauvas erkaneman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Ja hän puki kirouksen päällensä niinkuin paitansa ja se meni hänen sisällyksiinsä niinkuin vesi, ja hänen luihinsa niinkuin öljy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Se olkoon hänelle niinkuin vaate, jolla hän itsensä verhottaa, ja niinkuin vyö, jolla hän aina itsensä vyöttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Aivan näin tapahtukoon heille Herralta, jotka ovat minua vastaan, ja puhuvat pahoin minun sieluani vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Mutta sinä, Herra, Herra, tee minun kanssani sinun nimes tähden; sillä sinun armos on hyvä, pelasta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Sillä minä olen köyhä ja raadollinen: minun sydämeni on särjetty minussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Minä menen pois niinkuin varjo, koska se kulkee pois, ja pudistetaan ulos niinkuin kaskaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Minun polveni ovat heikoksi tulleet paastosta, ja minun lihani on laihtunut lihavuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Ja minun täytyy olla heidän pilkkansa: koska he minun näkevät, niin he päätänsä pudistavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Auta minua, Herra minun Jumalani: auta minua sinun armos perästä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Että he tuntisivat sen sinun kädekses, ja että sinä Herra sen teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Koska he sadattavat, niin siunaa sinä: koska he karkaavat minua vastaan, niin tulkoon he häpiään, mutta sinun palvelias iloitkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Olkoon minun vainolliseni häväistyksellä puetut, ja olkoon häpiällänsä verhotetut niinkuin hameella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Minä kiitän suuresti Herraa suullani, ja ylistän häntä monen seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Sillä hän seisoo köyhän oikialla kädellä, auttamassa häntä niistä, jotka hänen sieluansa tuomitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Davidin Psalmi. Herra sanoi minun Herralleni: istu oikialle kädelleni, siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Herra lähettää sinun väkevyytes valtikan Zionista: vallitse vihollistes seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Sinun voittos päivänä palvelee sinun kansas sinua mielellänsä pyhissä kaunistuksissa: sinun lapses synnytetään sinulle niinkuin kaste aamuruskosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Herra on vannonut, ja ei kadu sitä: sinä olet pappi ijankaikkisesti, Melkisedekin säädyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Herra on sinun oikialla kädelläs: hän musertaa kuninkaat vihansa päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Hän tuomitsee pakanain seassa, hän täyttää maakunnat ruumiilla: hän musertaa monen maakunnan pään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Hän juo ojasta tiellä; sen tähden korottaa hän päänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja! Minä kiitän Herraa kaikesta sydämestäni, hurskasten neuvossa ja seurakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Suuret ovat Herran työt: joka niistä ottaa vaarin, hänellä on sula riemu niistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Mitä hän asettaa, se on kunniallinen ja jalo, ja hänen vanhurskautensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Hän on säätänyt ihmeittensä muiston: armollinen ja laupias on Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Hän antaa ruan pelkääväisillensä: hän muistaa liittonsa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Hän ilmoittaa kansallensa väkevät työnsä, antaaksensa heille pakanain perimisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Hänen kättensä työt ovat totuus ja oikeus: kaikki hänen käskynsä ovat toimelliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Ne pysyvät vahvana aina ja ijankaikkisesti: ne ovat tehdyt totuudessa ja oikeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Hän lähetti kansallensa lunastuksen, hän lupaa liittonsa pysymään ijankaikkisesti: pyhä ja peljättävä on hänen nimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Herran pelko on viisauden alku: se on hyvä ymmärrys kaikille, jotka sen tekevät: hänen kiitoksensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja! Autuas on, joka pelkää Herraa: joka hänen käskyjänsä sangen himoitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Hänen siemenensä on valtias maan päällä: hurskasten suku pitää siunatuksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Rikkaus ja runsaus on hänen huoneessansa, ja hänen vanhurskautensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Hurskaille koittaa valkeus pimeässä, armolliselta, laupiaalta ja vanhurskaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Hyvä ihminen on laupias ja mielellänsä lainaa, ja toimittaa asiansa toimellisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Sillä hän pysyy ijankaikkisesti: ei vanhurskas ikänä unhoteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Koska rangaistus tulee, niin ei hän pelkää: hänen sydämensä uskaltaa lujasti Herran päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Hänen sydämensä on vahvistettu ja ei pelkää, siihenasti kuin hän näkee ilonsa vihollisistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Hän jakaa ja antaa vaivaisille: hänen vanhurskautensa pysyy ijankaikkisesti: hänen sarvensa korotetaan kunnialla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Jumalatoin näkee sen ja närkästyy: hän pureskelee hampaitansa ja nääntyy; sillä mitä jumalattomat halajavat, se tyhjäksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja! Kiittäkäät te, Herran palveliat, kiittäkäät Herran nimeä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Kiitetty olkoon Herran nimi, nyt ja ijankaikkisesti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Auringon koitosta hänen laskemiseensa asti olkoon Herran nimi kiitetty!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Herra on korkia ylitse kaikkein pakanain, ja hänen kunniansa ylitse taivasten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kuka on niinkuin Herra meidän Jumalamme, joka niin korkialla asuu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Ja kuitenkin katsoo alimmaisia taivaassa ja maassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Joka köyhän tomusta ylentää, ja vaivaisen loasta korottaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Istuttaaksensa häntä päämiesten sivuun, kansansa päämiesten sivuun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Joka hedelmättömät saattaa huoneesen asumaan, että hän riemuiseksi lasten äidiksi tulee. Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Kuin Israel Egyptistä läksi, Jakobin huone muukalaisesta kansasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Niin Juuda tuli hänen pyhäksensä: Israel hänen vallaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Sen meri näki ja pakeni: Jordan palasi takaperin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Vuoret hyppäsivät niinkuin oinaat, ja kukkulat niinkuin nuoret lampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Mikä sinun oli meri, ettäs pakenit? ja sinä Jordan, ettäs palasit takaperin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Te vuoret, että te hyppäsitte niinkuin oinaat? te kukkulat niinkuin nuoret lampaat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Herran edessä vapisi maa, Jakobin Jumalan edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Joka kalliot muuttaa vesilammiksi, ja kiven vesilähteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ei meille, Herra, ei meille, vaan sinun nimelles anna kunnia, sinun armos ja totuutes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Miksi pakanat sanovat: kussa on nyt heidän Jumalansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Mutta meidän Jumalamme on taivaissa: mitä ikänä hän tahtoo, sen hän tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Vaan heidän epäjumalansa ovat hopia ja kulta, ihmisten käsillä tehdyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Heillä on suu, ja ei puhu: heillä ovat silmät, ja ei näe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Heillä ovat korvat, ja ei kuule: heillä ovat sieraimet, ja ei haista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Heillä ovat kädet, ja ei rupee: heillä ovat jalat, ja ei käy; ja ei puhu kurkustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Jotka niitä tekevät, ovat niiden kaltaiset, ja kaikki, jotka heihin uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Mutta Israel toivokaan Herran päälle: hän on heidän apunsa ja heidän kilpensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Aaronin huone toivokaan Herran päälle: hän on heidän apunsa ja heidän kilpensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Jotka Herraa pelkäävät, toivokaan myös Herran päälle: hän on heidän apunsa ja heidän kilpensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Herra muistaa meitä ja siunaa meitä: hän siunaa Israelin huoneen, hän siunaa Aaronin huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Hän siunaa ne, jotka Herraa pelkäävät, sekä pienet että suuret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Herra siunatkoon teitä enemmin ja enemmin, teitä ja teidän lapsianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Te olette Herran siunatut, joka taivaat ja maan on tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Taivasten taivaat ovat Herran; mutta maan on hän ihmisten lapsille antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Kuolleet ei taida Herraa kiittää, eikä ne, jotka menevät alas hiljaisuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Mutta me kiitämme Herraa, hamasta nyt ja ijankaikkiseen, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Sitä minä rakastan, että Herra kuulee minun rukoukseni äänen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Että hän korvansa kallistaa minun puoleeni; sentähden minä avukseni huudan häntä elinaikanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Kuoleman paulat ovat minun piirittäneet, ja helvetin ahdistukset ovat minun löytäneet: minä tulin vaivaan ja tuskaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Mutta minä avukseni huudan Herran nimeä: o Herra, pelasta minun sieluni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Herra on armollinen ja vanhurskas, ja meidän Jumalamme on laupias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Herra kätkee yksinkertaiset: kuin minä olin kovin vaivattu, niin hän minua autti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Palaja taas, minun sieluni, sinun lepoos; sillä Herra tekee hyvästi sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Sillä sinä olet sieluni temmannut pois kuolemasta, silmäni kyynelistä, jalkani kompastuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Minä vaellan Herran edessä eläväin maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Minä uskon, sentähden minä puhun; mutta minä sangen vaivataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Minä sanoin hämmästyksessä: kaikki ihmiset ovat valehteliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kuinka minä maksan Herralle kaikki hänen hyvät tekonsa, jotka hän minulle teki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Minä otan sen autuaallisen kalkin, ja saarnaan Herran nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Minä maksan lupaukseni Herralle kaiken hänen kansansa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Hänen pyhäinsä kuolema on kallis Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'O Herra! minä olen sinun palvelias, minä olen sinun palvelias, sinun piikas poika: sinä olet minun siteeni vallallensa päästänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Minä uhraan sinulle kiitosuhria, ja Herran nimeä saarnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Minä maksan Herralle lupaukseni kaiken hänen kansansa edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Herran huoneen esikartanoissa, keskellä sinua, Jerusalem. Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Kiittäkäät Herraa, kaikki pakanat: ylistäkäät häntä kaikki kansat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Sillä hänen armonsa on voimallinen meidän päällemme, ja Herran totuus ijankaikkisesti. Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Sanokaan nyt Israel: hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Sanokaan nyt Aaronin huone: hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Sanokaan nyt kaikki, jotka Herraa pelkäävät: hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Tuskissani minä Herraa avukseni huusin, ja Herra kuuli minua, ja pelasti minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Herra on minun kanssani; sentähden en minä pelkää, mitä ihmiset minulle tekisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Herra on minun kanssani auttamassa minua, ja minä tahdon nähdä iloni minun vihollisistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Parempi on uskaltaa Herran päälle, kuin luottaa ihmisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Parempi on uskaltaa Herran päälle, kuin luottaa päämiehiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Kaikki pakanat piirittävät minua; mutta Herran nimeen minä heitä lyön maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'He piirittävät minua joka kulmalta; mutta Herran nimeen minä heitä lyön maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'He piirittävät minua niinkuin kimalaiset, ja he sammuvat niinkuin tuli orjantappuroissa; mutta Herran nimeen minä heitä lyön maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Minua kovin sysätään lankeemaan; mutta Herra auttaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Herra on minun väkevyyteni, ja minun virteni, ja on minun autuuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Ilon ja autuuden ääni on vanhurskasten majoissa: Herran oikia käsi saa voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Herran oikia käsi on koroitettu: Herran oikia käsi saa voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'En minä kuole, vaan elän, ja Herran tekoja luettelen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Kyllä Herra minua kurittaa, vaan ei hän minua kuolemalle anna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Avatkaat minulle vanhurskauden portit, minun käydäkseni sisälle, kiittämään Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Tämä on Herran portti: vanhurskaat siitä käyvät sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Minä kiitän sinua, ettäs minun rukoukseni kuulit, ja autit minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Herralta se on tapahtunut, ja on ihme meidän silmäimme edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Tämä on se päivä, jonka Herra teki: iloitkaamme ja riemuitkaamme hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'O Herra, auta, o Herra, anna menestyä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Siunattu olkoon se,joka tulee Herran nimeen! me siunaamme teitä Herran huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Herra on Jumala, joka meitä valistaa: kaunistakaat juhlalehdillä hamaan alttarin sarviin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Sinä olet minun Jumalani, ja minä kiitän sinua; minun Jumalani! sinua minä ylistän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Autuaat ovat ne, jotka viattomasti elävät, ja jotka Herran laissa vaeltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Autuaat ovat ne, jotka hänen todistuksiansa pitävät, ja kaikesta sydämestä häntä etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Sillä, jotka hänen teissänsä vaeltavat, ei he tee mitään pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Sinä olet käskenyt sangen visusti pitää sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'O jospa minun tieni ojennettaisiin pitämään sinun säätyjäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Koska minä katson kaikkia sinun käskyjäs, niin en minä tule häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Minä kiitän sinua oikiasta sydämestä, ettäs opetat minulle vanhurskautes oikeudet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Sinun säätys minä pidän, älä minua ikänä hylkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Kuinka nuorukainen tiensä puhdistais? kuin hän itsensä käyttää sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Minä etsin sinua kaikesta sydämestäni: älä salli minun eksyä sinun käskyistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Minä pidän sydämessäni sinun sanas, etten minä rikkoisi sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Kiitetty ole, sinä Herra: opeta minulle sinun säätyjäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Minä luettelen huulillani kaikki sinun suus oikeudet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Minä iloitsen sinun todistustes tiellä, niinkuin kaikkinaisesta rikkaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Minä tutkistelen sinun käskyjäs, ja katselen sinun teitäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Minä halajan sinun oikeuttas, ja en unohda sinun sanojas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tee hyvästi palvelialles, että minä eläisin ja sinun sanas pitäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Avaa minun silmäni näkemään ihmeitä sinun laistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Minä olen vieras maan päällä: älä peitä minulta käskyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Minun sieluni on muserrettu rikki ikävöitsemisestä, alati sinun oikeutes jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Sinä rankaiset ylpiät kirotut, jotka sinun käskyistäs poikkeevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Käännä minusta pois pilkka ja ylönkatse; sillä minä pidän sinun todistukses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Istuvat myös päämiehet ja puhuvat minua vastaan; mutta sinun palvelias tutkistelee sinun säätyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Sinun todistukses ovat minun iloni, ne ovat minun neuvonantajani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Minun sieluni tomussa makaa: virvoita minua sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Minä luen minun teitäni, ja sinä kuulet minua: opeta minulle sinun säätys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Anna minun ymmärtää sinun käskyis tie, niin minä puhun sinun ihmeistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Niin minä suren, että sydän sulaa minussa: vahvista minua sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Käännä minusta pois väärä tie, ja suo minulle sinun lakis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Totuuden tien minä olen valinnut, oikeutes olen minä asettanut eteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Minä riipun sinun todistuksissas: Herra, älä salli minun häpiään tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Koskas minun sydämeni vahvistat, niin minä juoksen sinun käskyis tietä myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Opeta minulle, Herra, sinun säätyis tie, että minä sen loppuun asti kätkisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Anna minulle ymmärrys, kätkeäkseni sinun lakias, ja pitääkseni sitä koko sydämestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Anna minun käydä sinun käskyis tietä; sillä niihin minä halajan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Kallista minun sydämeni sinun todistuksiis, ja ei ahneuden puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Käännä minun silmäni pois katselemasta turhuutta; vaan virvoita minua sinun tiehes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Anna palvelias lujasti sinun käskys pitää, että minä sinua pelkäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Käännä minusta pois se pilkka, jota minä pelkään; sillä sinun oikeutes ovat suloiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Katso, minä pyydän sinun käskyjäs: virvoita minua vanhurskaudellas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Herra, anna armos minulle tapahtua, autuutes sinun sanas jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Että minä voisin vastata minun pilkkaajiani; sillä minä luotan sinun sanaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Älä ota totuuden sanaa peräti pois minun suustani; sillä minä toivon sinun oikeuttas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Minä pidän alati sinun lakis, aina ja ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Ja vaellan ilossa, sillä minä etsin sinun käskyjäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Ja puhun sinun todistuksistas kuningasten edessä, ja en häpee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Ja iloitsen sinun käskyistäs, joita minä rakastan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Ja nostan käsiäni sinun käskyihis, joita minä rakastan, ja puhun sinun säädyistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Muista sanaas sinun palvelialles, jota sinä annoit minun toivoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Tämä on minun turvani minun vaivassani, että sinun sanas virvoittaa minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Ylpiät irvistelevät minua sangen; en minä sentähden sinun laistas poikkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Herra, kuin minä ajattelen, kuinka sinä maailman alusta toiminut olet, niin minä lohdutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Minä hämmästyin jumalattomain tähden, jotka sinun lakis hylkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Sinun oikeutes ovat minun veisuni vaellukseni huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Herra, minä ajattelen yöllä sinun nimeäs, ja pidän sinun lakis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Se olis minun tavarani, että minä sinun käskys pitäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Minä olen sanonut: Herra, se on minun perimiseni, että minä pidän sinun sanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Minä rukoilen sinun kasvois edessä täydestä sydämestä: ole minulle armollinen sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Minä tutkin teitäni, ja käännän jalkani sinun todistustes puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Minä riennän, ja en viivy, sinun käskyjäs pitämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Jumalattomain joukko raatelee minua; mutta en minä unohda sinun lakias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Puoliyöstä minä nousen sinua kiittämään, sinun vanhurskautes oikeuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Minä olen heidän kumppaninsa, jotka sinua pelkäävät ja sinun käskyjäs pitävät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Herra! maa on täynnä sinun hyvyyttäs: opeta minulle sinun säätyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Hyvästi teit sinun palveliaas kohtaan, Herra, sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Opeta minulle hyviä tapoja ja taitoa; sillä minä uskon sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Ennenkuin minä nöyryytettiin, eksyin minä; mutta nyt minä pidän sinun sanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Sinä olet hyvä ja teet hyvin: opeta minulle sinun säätyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Ylpiät ajattelevat valheen minun päälleni; mutta minä pidän täydestä sydämestä sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Heidän sydämensä on lihava niinkuin rasva; mutta minä iloitsen sinun laistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Se on minulle hyvä, ettäs minun nöyryytit, että minä sinun säätyjäs oppisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Sinun suus laki on minulle otollisempi kuin monta tuhatta kappaletta kultaa ja hopiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Sinun kätes ovat minun tehneet ja valmistaneet: anna minulle ymmärrystä oppiakseni sinun käskyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Jotka sinua pelkäävät, ne minun näkevät ja iloitsevat; sillä minä toivon sinun sanaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Herra! minä tiedän sinun tuomios vanhurskaaksi, ja sinä olet minua totuudessa nöyryyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Olkoon siis sinun armos minun lohdutukseni, niinkuin sinä palvelialles luvannut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Anna minulle sinun laupiutes tapahtua, että minä eläisin; sillä sinun lakis on minun iloni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Jospa ylpiät häpiään tulisivat, jotka minua painavat alas valheellansa; mutta minä ajattelen sinun käskyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Tulkaan ne minun tyköni, jotka sinua pelkäävät, ja sinun todistukses tuntevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Olkoon minun sydämeni toimellinen sinun säädyissäs, etten minä häväistäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Minun sieluni ikävöitsee sinun autuuttas: minä toivon sinun sanas päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Minun silmäni hiveltyvät sinun sanas jälkeen, ja sanovat: koskas minua lohdutat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Sillä minä olen niinkuin nahka savussa: en minä unohda sinun säätyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Kuinka kauvan sinun palvelias odottaa? koskas tuomitset minun vainoojani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Ylpiät minulle kuoppia kaivavat, jotka ei ole sinun lakis perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Kaikki sinun käskys ovat sula totuus: he valheella minua vaivaavat: auta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'He olisivat juuri lähes minun maan päällä hukuttaneet; mutta en minä sinun käskyjäs hyljännyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Virvoita minua sinun armoillas, että minä pitäisin sinun suus todistuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Herra! sinun sanas pysyy ijankaikkisesti taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Sinun totuutes pysyy suvusta sukuun: sinä perustit maan, ja se pysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Ne pysyvät tähän päivään asti sinun asetukses jälkeen; sillä kaikki sinua palvelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Ellei sinun lakis olisi ollut minun lohdutukseni, niin minä olisin raadollisuudessani hukkunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'En minä ikänä unohda sinun käskyjäs; sillä niillä sinä minua lohdutat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Sinun minä olen: auta minua! sillä minä etsin sinun käskyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Jumalattomat minua vartioitsevat hukuttaaksensa; mutta sinun todistuksistas minä otan vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Kaikista kappaleista minä olen lopun nähnyt; mutta sinun käskys ovat määrättömät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Kuinka minä rakastan sinun lakias? Joka päivä minä sitä ajattelen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Sinä teit minun taitavammaksi käskyilläs kuin minun viholliseni ovat; sillä se on minun ijankaikkinen tavarani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Minä olen oppineempi kuin kaikki minun opettajani; sillä sinun todistukses ovat minun ajatukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Enemmän minä ymmärrän kuin vanhemmat; sillä minä pidän sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Minä estän jalkani kaikista pahoista teistä, että minä sinun sanas pitäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'En minä poikkee sinun oikeudestas; sillä sinä opetat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Sinun sanas ovat minun suulleni makiammat kuin hunaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Sinun käskys tekevät minun ymmärtäväiseksi; sentähden minä vihaan kaikkia vääriä teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Sinun sanas on minun jalkaini kynttilä, ja valkeus teilläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Minä vannon, ja sen vahvana pidän, että minä sinun vanhurskautes oikeudet pitää tahdon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Minä olen sangen kovin vaivattu: Herra, virvoita minua sinun sanas perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Olkoon sinulle, Herra, otolliset minun suuni mieluiset uhrit, ja opeta minulle sinun oikeutes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Minun sieluni on alati minun käsissäni, ja en unohda sinun lakias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Jumalattomat virittävät minulle paulan; mutta en minä eksy sinun käskyistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Sinun todistukses ovat minun ijankaikkiset perimiseni; sillä ne ovat minun sydämeni ilo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Minä kallistan minun sydämeni tekemään sinun säätys jälkeen, aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Minä vihaan viekkaita henkiä, ja rakastan sinun lakias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Sinä olet minun varjelukseni ja kilpeni: minä toivon sinun sanas päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Poiketkaat minusta, te pahanilkiset; ja minä pidän minun Jumalani käskyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Tue minua sanallas, että minä eläisin, ja älä anna minun toivoni häpiään tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Vahvista minua, että minä autetuksi tulisin, niin minä halajan alati sinun säätyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Sinä tallaat alas kaikki, jotka sinun säädyistäs horjuvat; sillä heidän viettelyksensä on sula valhe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Sinä heität pois kaikki jumalattomat maan päältä niinkuin loan; sentähden minä rakastan sinun todistuksias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Minä pelkään sinua, niin että minun ihoni värisee, ja vapisen sinun tuomioitas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Minä teen oikeuden ja vanhurskauden: älä minua hylkää niille, jotka minulle väkivaltaa tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Vastaa palvelias edestä, ja lohduta häntä, ettei ylpiät tekisi minulle väkivaltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Minun silmäni hiveltyvät sinun autuutes perään, ja sinun vanhurskautes sanan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Tee palvelias kanssa sinun armos jälkeen, ja opeta minulle sinun säätyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Sinun palvelias minä olen: anna minulle ymmärrystä, että minä tuntisin sinun todistukses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Jopa aika on, että Herra siihen jotakin tekis: he ovat sinun lakis särkeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Sentähden minä rakastan sinun käskyjäs, enempi kuin kultaa ja parasta kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Sentähden minä pidän visusti kaikkia sinun käskyjäs: minä vihaan kaikkia vääriä teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Ihmeelliset ovat sinun todistukses; sentähden minun sieluni ne pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Kuin sinun sanas julistetaan, niin se valistaa ja antaa yksinkertaisille ymmärryksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Minä avaan suuni ja huokaan; sillä minä halajan sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Käännä sinuas minun puoleeni, ja ole minulle armollinen, niinkuin sinä olet niille tottunut tekemään, jotka sinun nimeäs rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Vahvista minun käymiseni sinun sanassas, ja älä anna väkivallan minua vallita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Lunasta minua ihmisten väkivallasta, niin minä pidän sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Valista sinun kasvos palvelias päälle, ja opeta minulle sinun säätys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Minun silmäni vettä vuotavat, niinkuin virta, ettei sinun käskyjäs pidetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Herra! sinä olet vanhurskas ja sinun tuomios ovat oikiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Sinä olet vanhurskautes todistukset ja totuuden visusti käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Minä olen lähes surmakseni kiivannut, että minun viholliseni ovat sinun sanas unohtaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Sinun puhees on sangen koeteltu, ja sinun palvelias sen rakkaana pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Minä olen halpa ja ylönkatsottu, mutta en minä unohda sinun käskyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Sinun vanhurskautes on ijankaikkinen vanhurskaus, ja sinun lakis on totuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Ahdistus ja tuska ovat minun saavuttaneet; mutta minä iloitsen sinun käskyistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Sinun todistustes vanhurskaus pysyy ijankaikkisesti: anna minulle ymmärrys, niin minä elän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Minä huudan kaikesta sydämestäni: kuule, Herra, minua, että minä sinun säätys pitäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Sinua minä huudan, auta minua, että minä sinun todistukses pitäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Varhain minä ennätän, ja huudan: sinun sanas päälle minä toivon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Varhain minä herään, tutkistelemaan sinun sanojas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Kuule minun ääneni sinun armos jälkeen: Herra, virvoita minua sinun oikeutes jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Pahanilkiset vainoojat karkaavat minun päälleni, ja ovat kaukana sinun laistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Herra, sinä olet läsnä, ja sinun käskys ovat sula totuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Mutta minä sen aikaa tiesin, että sinä olet todistukses ijankaikkisesti perustanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Katso minun raadollisuuttani, ja pelasta minua; sillä enpä minä unohda sinun lakias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Toimita minun asiani ja päästä minua: virvoita minua sinun sanas kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Autuus on kaukana jumalattomista, sillä ei he tottele säätyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Herra, sinun laupiutes on suuri: virvoita minua sinun oikeutes jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Minun vainoojaani ja vihollistani on monta; mutta en minä poikkee sinun todistuksistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Minä näen ylönkatsojat, ja siihen suutun, ettei he sinun sanaas pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Katso, minä rakastan sinun käskyjäs: Herra, virvoita minua sinun armos jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Sinun sanas on alusta totuus ollut: kaikki sinun vanhurskautes oikeudet pysyvät ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Päämiehet vainoovat minua ilman syytä; mutta minun sydämeni pelkää sinun sanojas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Minä iloitsen sinun puheestas, niinkuin se joka suuren saaliin löytänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Valhetta minä vihaan ja kauhistun; mutta sinun lakias minä rakastan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Seitsemästi päivässä minä kiitän sinua sinun vanhurskautes oikeuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Suuri rauha on niillä, jotka sinun lakias rakastavat, ja ei he itsiänsä loukkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Herra! minä odotan sinun autuuttas, ja teen sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Minun sieluni pitää sinun todistukses, ja minä rakastan niitä sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Minä pidän sinun käskys ja todistukses; sillä kaikki minun tieni ovat edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Herra! anna minun huutoni tulla sinun etees: anna minulle ymmärrystä sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Anna minun rukoukseni tulla sinun etees: pelasta minua sinun sanas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Minun huuleni kiittävät, koskas minulle opetat sinun säätys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Minun kieleni puhuu sinun sanastas; sillä kaikki sinun käskys ovat vanhurskaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Olkoon sinun kätes minulle avullinen; sillä minä olen valinnut sinun käskys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Herra, minä ikävöitsen sinun autuuttas, ja halajan sinun lakias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Anna minun sieluni elää, että hän sinua kiittäis, ja sinun oikeutes auttakoon minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Minä olen eksyvä niinkuin kadotettu lammas, etsi sinun palveliaas; sillä en minä unohda sinun käskyjäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Veisu korkeimmassa Kuorissa. Minä huudan Herraa minun tuskissani, ja hän kuulee minun rukoukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Herra, pelasta minun sieluni valhettelevista suista ja vääristä kielistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Mitä väärä kieli taitaa sinulle tehdä? ja mitä se taitaa toimittaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Se on niinkuin väkevän terävät nuolet, niinkuin tuli katajissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Voi minua, että minä olen muukalainen Mesekin seassa! minun täytyy asua Kedarin majain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Se tulee minun sielulleni ikäväksi, asua niiden tykönä, jotka rauhaa vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Minä pidän rauhan, mutta kuin minä puhun, niin he sodan nostavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Veisu korkeimmassa Kuorissa. Minä nostan silmäni mäkiin päin, joista minulle apu tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Minun apuni tulee Herralta, joka taivaan ja maan tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Ei hän salli jalkas horjua; eikä se torku, joka sinua kätkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Katso, joka Israelia varjelee, ei se torku eli makaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Herra kätkeköön sinua: Herra on sinun varjos, sinun oikialla kädelläs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Ettei aurinko sinua polttaisi päivällä, eikä kuu yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Herra kätkeköön sinun kaikesta pahasta: hän kätkeköön sinun sielus!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Herra kätkeköön sinun uloskäymises ja sisällekäymises, hamasta nyt ja ijankaikkiseen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Davidin veisu korkeimmassa Kuorissa. Minä iloitsen niistä, jotka minulle sanovat: että me menemme Herran huoneeseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Ja että meidän jalkamme pitää seisoman sinun porteissas, Jerusalem.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalem on rakennettu kaupungiksi, johon on tuleminen kokoon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Että sukukunnat astuisivat sinne ylös, Herran sukukunnat, Israelille todistukseksi, kiittämään Herran nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Sillä siellä ovat istuimet rakennetut tuomittaa, Davidin huoneen istuimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Toivottakaat Jerusalemille rauhaa: he menestyköön, jotka sinua rakastavat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Rauha olkoon sinun muureis sisällä, ja onni sinun huoneissas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Minun veljieni ja ystäväini tähden minä toivotan nyt sinulle rauhaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Herran meidän Jumalamme huoneen tähden etsin minä sinun parastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Veisu korkeimmassa Kuorissa. Minä nostan silmäni sinun tykös, joka asut taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Katso, niinkuin palveliain silmät katsovat isäntänsä käsiin, niinkuin piikain silmät katsovat emäntäinsä käsiin, niin meidänkin silmämme katsovat Herraa meidän Jumalaamme, siihenasti että hän meitä armahtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Ole meille armollinen, Herra, ole meille armollinen! sillä me olemme sangen täytetyt ylönkatseesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Sangen täynnä on meidän sielumme rikasten pilkkaa ja ylpeiden ylönkatsetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Davidin veisu korkeimmassa Kuorissa. Ellei Herra olisi meidän kanssamme, niin sanokaan Israel:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Ellei Herra olisi meidän kanssamme, koska ihmiset karkaavat meitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Niin he nielisivät meidät elävältä, kuin heidän vihansa julmistuu meidän päällemme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Niin vesi meitä upottais: kosket kävisivät sieluimme ylitse:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Niin ylpiät veden aallot kävisivät sielumme ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Kiitetty olkoon Herra, joka ei meitä anna raatelukseksi heidän hampaillensa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Meidän sielumme pääsi niinkuin lintu lintumiehen paulasta. Paula on särjetty, ja me olemme päästetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Meidän apumme on Herran nimessä, joka taivaan ja maan tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Veisu korkeimmassa Kuorissa. Jotka Herran päälle uskaltavat, ei he lankee, vaan pysyvät ijankaikkisesti niinkuin Zionin vuori.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jerusalemin ympäri ovat vuoret, ja Herra on kansansa ympärillä, hamasta nyt ja ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Sillä jumalattomain valtikka ei pidä pysymän vanhurskasten joukon päällä, ettei vanhurskaat ojentaisi käsiänsä vääryyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Herra, tee hyvästi hyville ja hurskaille sydämille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Mutta jotka poikkeevat vääriin teihinsä, niitä Herra ajaa pois pahantekiäin kanssa; mutta rauha olkoon Israelille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Veisu korkeimmassa Kuorissa. Koska Herra päästää Zionin vangit, niin me olemme niinkuin unta näkeväiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Silloin meidän suumme naurulla täytetään, ja kielemme on täynnä riemua; silloin sanotaan pakanoissa: Herra on suuria heidän kohtaansa tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Herra on suuria tehnyt meidän kohtaamme: siitä me olemme iloiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Herra! käännä meidän vankiutemme, niinkuin virrat etelässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Jotka kyyneleillä kylvävät, ne ilolla niittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'He menevät matkaan ja itkevät, ja vievät ulos kalliin siemenen, ja tulevat riemulla, ja tuovat lyhteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Salomon veisu korkeimmassa Kuorissa. Jos ei Herra huonetta rakenna, niin hukkaan työtä tekevät, jotka sitä rakentavat: jos ei Herra kaupunkia varjele, niin vartiat hukkaan valvovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Se on turha, että te varhain nousette ja hiljain maata menette, ja syötte leipänne surulla; sillä hän antaa ystävillensä heidän maatessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Katso, lapset ovat Herran lahja, ja kohdun hedelmä on anto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Kuin nuolet väkevän kädessä, niin ovat nuorukaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Autuas on se, jonka viini on niitä täynnänsä: ei ne häväistä, kuin heillä vihollistensa kanssa portissa tekemistä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Veisu korkeimmassa Kuorissa. Autuas on jokainen, joka Herraa pelkää, ja hänen tiellänsä vaeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Sillä sinä elätät itses kättes töistä: autuas sinä olet, ja sinulle käy hyvästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Sinun emäntäs on niinkuin hedelmällinen viinapuu huonees sisimmäisissä loukkaissa: sinun lapses niinkuin öljypuun vesat, pöytäs ympärillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Katsos, näin se mies siunataan, joka Herraa pelkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Herra siunaa sinua Zionista, ettäs näet Jerusalemin onnen kaikkena elinaikanas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Ja saat nähdä lastes lapset: rauha olkoon Israelille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Veisu korkeimmassa Kuorissa. He ovat usein minua ahdistaneet, hamasta nuoruudestani, sanokaan nyt Israel;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'He ovat usein minua ahdistaneet, hamasta nuoruudestani; mutta ei he minua voittaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Kyntäjät ovat minun selkäni päällä kyntäneet, ja vakonsa pitkäksi vetäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Herra, joka vanhurskas on, on jumalattomain köydet katkonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Tulkoon häpiään ja kääntyköön takaperin kaikki, jotka Zionia vihaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Olkoon niinkuin ruoho kattojen päällä, joka kuivettuu ennen kuin se reväistään ylös,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Joista niittäjä ei kättänsä täytä, eikä lyhteensitoja syliänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Eikä yksikään ohitsekäypä sano: olkoon Herran siunaus teidän päällänne: me siunaamme teitä Herran nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Veisu korkeimmassa Kuorissa. Syvyydessä minä huudan sinua, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herra, kuule minun ääneni: vaarinottakaan korvas rukousteni äänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Jos sinä, Herra, soimaat syntiä: Herra, kuka siis pysyy?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Sillä sinun tykönäs on anteeksi antamus, että sinua peljättäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Minä odotan Herraa: sieluni odottaa, ja minä toivon hänen sanansa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Sieluni vartioitsee Herraa huomenvartiosta toiseen huomenvartioon asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Israel toivokaan Herran päälle; sillä Herralla on armo, ja runsas lunastus hänellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Ja hän lunastaa Israelin kaikista synneistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Davidin veisu korkeimmassa Kuorissa. Herra! ei minun sydämeni ole paisunut, eikä minun silmäni ole ylpiät; enkä minä vaella suurissa asioissa, jotka minulle työläät ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Kuin en minä sieluani asettanut ja vaikittanut, niin minun sieluni tuli vieroitetuksi, niinkuin lapsi äidistänsä vieroitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israel toivokaan Herran päälle, hamasta nyt ja ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Veisu korkeimmassa Kuorissa. Muista, Herra, Davidia, ja kaikkia hänen vaivojansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Joka Herralle vannoi, ja lupasi lupauksen Jakobin väkevälle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'En mene huoneeni majaan, enkä vuoteeseeni pane maata;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'En anna silmäini unta saada, enkä silmälautaini torkkua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Siihenasti kuin minä löydän sian Herralle, Jakobin väkevän asumiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Katso, me kuulimme hänestä Ephratassa: me olemme sen löytäneet metsän kedoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Me tahdomme hänen asuinsioihinsa mennä, ja kumartaa hänen jalkainsa astinlaudan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Nouse, Herra, sinun lepoos, sinä ja sinun väkevyytes arkki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Anna pappis pukea heitänsä vanhurskaudella ja sinun pyhäs riemuitkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Älä käännä pois voideltus kasvoja, sinun palvelias Davidin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Herra on vannonut Davidille totisen valan, ja ei hän siitä vilpistele: sinun ruumiis hedelmästä minä istutan istuimelles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Jos sinun lapses minun liittoni pitävät, ja minun todistukseni, jotka minä heille opetan, niin heidän lapsensa myös pitää sinun istuimellas istuman ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Sillä Herra on Zionin valinnut, ja tahtoo sitä asuinsiaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Tämä on minun leponi ijankaikkisesti: tässä minä tahdon asua; sillä se minulle kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Minä hyvästi siunaan hänen elatuksensa, ja hänen köyhillensä kyllä annan leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Hänen pappinsa minä puetan autuudella; ja hänen pyhänsä pitää ilolla riemuitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Siellä minä annan puhjeta Davidin sarven: minä valmistan kynttilän voidellulleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Hänen vihollisensa minä häpiällä puetan; mutta hänen päällänsä pitää hänen kruununsa kukoistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Davidin veisu korkeimmassa Kuorissa. Katsos kuinka hyvä ja kuinka suloinen se on, että veljekset sovinnossa keskenänsä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Niinkuin kallis voide, joka Aaronin päästä vuotaa koko hänen partaansa, joka vuotaa hänen vaatettensa liepeesen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Niinkuin Hermonin kaste, joka tulee alas Zionin vuorelle; sillä siellä lupaa Herra siunauksen ja elämän alati ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Veisu korkeimmassa Kuorissa. Katso, kiittäkäät Herraa, kaikki Herran palveliat, jotka yöllä seisotte Herran huoneessa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Nostakaat kätenne pyhään päin, ja kiittäkäät Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Herra siunatkoon sinua Zionista, joka taivaan ja maan tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja! Ylistäkäät Herran nimeä, kiittäkäät, Herran palveliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Te kuin seisotte Herran huoneessa, meidän Jumalamme esihuoneissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Kiittäkäät Herraa, sillä Herra on hyvä, ja veisatkaat kiitosta hänen nimellensä; sillä se on suloinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Sillä Herra on itsellensä valinnut Jakobin, Israelin omaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Minä tiedän, että Herra on suuri, ja meidän Jumalamme kaikkein jumalain ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Kaikki, mitä Herra tahtoo, niin hän tekee, taivaassa ja maassa, meressä ja kaikessa syvyydessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Joka pilvet nostaa maan ääristä, joka pitkäisen leimauksesta sateen saattaa, ja tuulen tuo ulos tavaroistansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Joka esikoiset Egyptissä löi, sekä ihmisistä että karjasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Ja antoi merkkinsä ja ihmeensä tulla Egyptin keskelle, Pharaolle ja kaikille hänen palvelioillensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Joka monet pakanat löi, ja tappoi väkevät kuninkaat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihonin Amorilaisten kuninkaan, ja Ogin Basanin kuninkaan, ja kaikki Kanaanin valtakunnat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Ja antoi heidän maansa perimiseksi, Israelille kansallensa perimiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Herra, sinun nimes pysyy ijankaikkisesti: Herra, sinun muistos pysyy suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Sillä Herra tuomitsee kansansa, ja on palvelioillensa armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Pakanain epäjumalat ovat hopia ja kulta, ihmisten käsillä tehdyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Heillä on suu, ja ei puhu: heillä ovat silmät, ja ei näe;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Heillä ovat korvat, ja ei kuule: eikä ole henkeä heidän suussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Jotka niitä tekevät, he ovat niiden kaltaiset, ja kaikki, jotka heihin uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Te Israelin huoneesta, kiittäkäät Herraa! te Aaronin huoneesta, kiittäkäät Herraa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Te Levin huoneesta, kiittäkäät Herraa! te jotka Herraa pelkäätte, kiittäkäät Herraa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Kiitetty olkoon Herra Zionista, joka Jerusalemissa asuu! Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Kiittäkäät Herraa, sillä hän on hyvä; sillä hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Kiittäkäät kaikkein jumalain Jumalaa; sillä hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Kiittäkäät kaikkein herrain Herraa; sillä hänen laupiutensa pysyy ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Joka yksinänsä suuret ihmeet tekee; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Joka taivaat toimellisesti on tehnyt; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Joka maan on levittänyt veden päälle; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Joka suuret valkeudet on tehnyt; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Auringon päivää hallitsemaan; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Kuun ja tähdet yötä hallitsemaan; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Joka Egyptin esikoiset löi: sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Ja vei Israelin ulos heidän keskeltänsä; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Väkevällä kädellä ja ojennetulla käsivarrella; sillä hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Joka Punaisen meren jakoi kahtia; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Ja antoi Israelin käydä sen keskeltä; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Joka Pharaon sotaväkinensä Punaiseen mereen upotti; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Joka johdatti kansansa korven lävitse; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Joka suuret kuninkaat löi; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Ja tappoi väkevät kuninkaat; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihonin Amorilaisten kuninkaan; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Ja Ogin Basanin kuninkaan; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Ja antoi heidän maansa perimiseksi; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Perimiseksi palveliallensa Israelille; sillä hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Hän muisti meitä, kuin me olimme painetut alas; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Ja lunasti meitä vihollisistamme; sillä hänen laupiutensa pysyy ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Joka antaa kaikelle lihalle ruan; sillä hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Kiittäkäät taivaan Jumalaa! sillä hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Babelin virtain tykönä me istuimme ja itkimme, kuin me Zionin muistimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Kanteleemme me ripustimme pajuihin, jotka siellä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Siellä he käskivät meidän veisata, jotka meitä vankina pitivät, ja iloita meidän itkussamme: Veisatkaat meille Zionin virsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kuinka me veisaisimme Herran veisun vieraalla maalla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Jos minä unohdan sinua, Jerusalem, niin olkoon oikia käteni unohdettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Tarttukoon kieleni suuni lakeen, ellen minä sinua muista, ellen minä tee Jerusalemia ylimmäiseksi ilokseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Herra, muista Edomin lapsia Jerusalemin päivänä, jotka sanovat: repikäät maahan hamaan hänen perustukseensa asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Sinä hävitetty tytär, Babel; autuas on, se joka sinulle kostaa, niinkuin sinä meille tehnyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Autuas on se, joka piskuiset lapses ottaa ja paiskaa kiviin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Davidin. Minä kiitän sinua kaikesta sydämestäni: jumalain edessä minä sinulle kiitosta veisaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Minä tahdon kumartaen rukoilla sinun pyhän templis puoleen, ja kiittää sinun nimeäs, sinun armos ja totuutes tähden; sillä sinä teit nimes ja sanas suureksi kaikkein ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Koska minä sinua avukseni huudan, niin sinä kuulet minua, ja annat sielulleni suuren väkevyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Herra! sinua kiittävät kaikki kuninkaat maan päällä, että he kuulevat sinun suus sanoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Ja veisaavat Herran teille, että Herran kunnia on suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Sillä Herra on korkia, ja katselee nöyriä, ja ylpiät tuntee kaukaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Jos minä vaeltaisin ahdistuksen keskellä, niin sinä virvoitat minua, ja lähetät kätes vihollisteni vihan päälle: sinun oikia kätes varjelee minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Herra tekee siihen lopun minun tähteni: Herra, sinun laupiutes on ijankaikkinen, älä käsialaas hylkää!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Davidin Psalmi, edelläveisaajalle. Herra! sinä tutkit minua, ja tunnet minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Joko minä istun eli nousen, niin sinä sen tiedät: sinä ymmärrät taampaa ajatukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Joko minä käyn eli makaan, niin sinä olet ympärilläni, ja näet kaikki tieni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Sillä katso, ei ole sanaakaan kieleni päällä, joita et sinä Herra kaikkia tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Sinä olet tehnyt jälkimäiseni ja ensimäiseni, ja pidät sinun kätes minun päälläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Senkaltainen tieto on minulle ylen ihmeellinen ja ylen korkia, etten minä voi sitä käsittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kuhunka minä menen sinun hengestäs? ja kuhunka minä sinun kasvois edestä pakenen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Jos minä astuisin ylös taivaaseen, niin sinä siellä olet: jos minä vuoteeni helvetissä rakentaisin, katso, sinä myös siellä olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Jos minä ottaisin aamuruskon siivet, ja asuisin meren äärissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Niin sinun kätes sielläkin minua johdattais, ja sinun oikia kätes pitäis minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Jos minä sanoisin: pimeys kuitenkin peittää minun, niin on myös yö valkeus minun ympärilläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Sillä ei pimeys sinun edessäs pimitä, ja yö valistaa niinkuin päivä; pimeys on niinkuin valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Sinun hallussas ovat minun munaskuuni: sinä peitit minun äitini kohdussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Minä kiitän sinua sen edestä, että minä niin aivan ihmeellisesti tehty olen: ihmeelliset ovat sinun tekos, ja sen minun sieluni kyllä tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Ei minun luuni olleet sinulta salatut, kuin minä siinä salaisesti tehty olin, kuin minä maan sisällä niin taitavasti koottu olin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Sinun silmäs näkivät minun, kuin en vielä valmistettu ollut, ja kaikki päivät sinun kirjaas olivat kirjoitetut, jotka vielä oleman piti, joista ei yksikään silloin vielä tullut ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Mutta kuinka kalliit ovat minun edessäni, Jumala, sinun ajatukses? kuinka suuri on heidän lukunsa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Jos minä heitä lukisin, niin ne olisivat usiammat kuin santa: kuin minä herään, olen minä vielä tykönäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Jumala, jospa tappaisit jumalattomat, ja verikoirat minusta poikkeisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Sillä he puhuvat sinusta häpiällisesti, ja sinun vihollises turhaan lausuvat (sinun nimes).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Herra, minä tosin vihaan niitä, jotka sinua vihaavat, ja minä närkästyn heistä, jotka karkaavat sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Täydestä todesta minä heitä vihaan; sentähden ovat he minulle viholliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Tutki minua, Jumala, ja koettele sydämeni: kiusaa minua, ja ymmärrä, kuinka minä ajattelen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Ja katsos, jos minä pahalla tiellä lienen, niin saata minua ijankaikkiselle tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Davidin Psalmi, edelläveisaajalle. (H140:2) Herra, pelasta minua pahoista ihmisistä: varjele minua vääristä miehistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Jotka pahaa ajattelevat sydämissänsä, ja joka päivä sotaan hankitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'He hiovat kieltänsä niinkuin kärme: kyykärmeen myrkky on heidän huultensa alla, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Varjele minua, Herra, jumalattomain käsistä, varjele minua vääristä ihmisistä, jotka ajattelevat minun käymiseni kukistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Ylpiät asettavat paulat ja nuorat minun eteeni, ja venyttävät verkot tien viereen: minun eteeni panevat he paulan, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Mutta minä sanoin Herralle: sinä olet minun Jumalani: Herra, kuule minun rukoukseni ääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Herra, Herra, väkevä apuni! sinä varjelet minun pääni sodan aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Herra, älä salli jumalattomalle hänen himoansa: älä vahvista hänen pahaa tahtoansa, ettei hän ylpeytyisi, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Heidän sappensa, jotka minua piirittävät, ja heidän huultensa vaiva langetkoon heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Tuliset hiilet pitää heidän päällensä putooman: hän antaa heidän langeta tuleen ja syvään kuoppaan, ettei heidän pidä nouseman ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Kielilakkarin ei pidä menestymän maan päällä: häijy väärä ihminen karkoitetaan ja kukistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Sillä minä tiedän, että Herra raadollisen asian ja köyhän oikeuden toimittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Tosin vanhurskaat kiittävät sinun nimeäs, ja vakaat asuvat sinun kasvois edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Davidin Psalmi. Herra, minä avukseni huudan sinua: riennä minun puoleeni: ota korviis minun ääneni, koska minä sinua huudan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Kelvatkoon minun rukoukseni sinun edessäs niinkuin savu-uhri, minun kätteni ylennys niinkuin ehtoo-uhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Herra, varjele minun suuni ja varjele minun huuleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Älä kallista minun sydäntäni mihinkään pahuuteen, pitämään jumalatointa menoa pahointekiäin kanssa, etten minä söisi niitä, mitkä heille kelpaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Vanhurskas lyökään minua ystävällisesti, ja nuhdelkaan minua, se olkoon niinkuin öljy minun pääni päällä; sillä minä vielä rukoilen heidän pahuuttansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Heidän opettajansa sysättäköön kiveen, niin sitte kuullaan minun opetukseni suloiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Meidän luumme ovat hajoitetut haudan reunalle, niinkuin joku maan repis ja kaivais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Sillä sinua, Herra, Herra, minun silmäni katsovat: minä uskallan sinuun, älä minun sieluani hylkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Varjele minua siitä paulasta, jonka he asettivat eteeni, ja pahointekiäin ansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Jumalattomat lankeevat toinen toisensa kanssa omiin verkkoihinsa, siihenasti kuin minä pääsen ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Davidin oppi ja rukous, kuin hän luolassa oli. (H142:2) Minä huudan Herran tykö äänelläni, ja rukoilen Herraa äänelläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Minä vuodatan ajatukseni hänen edessänsä, ja osoitan hänelle hätäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Koska henkeni on ahdistuksessa, niin sinä tiedät käymiseni: tielle, jota minä vaellan, asettavat he paulat eteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Katsele oikialle puolelle ja näe, siellä ei yksikään tahdo minua tuta: en minä taida paeta, ei tottele kenkään minun sieluani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Herra, sinua minä huudan ja sanon: sinä olet minun toivoni ja minun osani elävien maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Ota vaari minun rukouksestani, sillä minua vaivataan sangen: pelasta minua vainollisistani; sillä he ovat minua väkevämmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Vie minun sieluni vankeudesta ulos kiittämään sinun nimeäs: vanhurskaat kokoontuvat minun tyköni, koskas minulle hyvästi teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Davidin Psalmi. Herra! kuule minun rukoukseni, ota anomiseni korviis, sinun totuutes tähden, kuule minua sinun vanhurskautes tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Ja älä käy tuomiolle palvelias kanssa; sillä ei yksikään elävä ole vakaa sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Sillä vihollinen vainoo minun sieluani, ja lyö minun elämäni rikki maahan asti: hän panee minun pimeyteen, niinkuin kuolleet maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Minun henkeni on minussa ahdistettu: sydämeni on minussa kulutettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Minä muistelen entisiä aikoja: minä ajattelen kaikkia sinun tekojas, ja tutkistelen sinun kättes töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Minä levitän käteni sinun puolees: minun sieluni janoo sinua, niinkuin karkia maa, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Herra, kuule minua nopiasti, henkeni katoo: älä kasvojas minulta kätke, etten minä niiden kaltaiseksi tulisi, jotka hautaan menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Suo minun varhain kuulla sinun armojas, sillä sinuun minä toivon: ilmoita minulle tie, jota minä käyn; sillä minä ylennän sieluni sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Pelasta minua, Herra, vihollisistani! sinun tykös minä pakenen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Opeta minua tekemään sinun suosios jälkeen; sillä sinä olet minun Jumalani: sinun hyvä henkes viekään minua tasaista tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Herra, virvoita minua nimes tähden: vie sieluni hädästä ulos sinun vanhurskautes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Ja teloita viholliseni sinun laupiutes tähden, ja kadota kaikki, jotka minun sieluani ahdistavat, sillä minä olen palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Davidin Psalmi. Kiitetty olkoon Herra, minun turvani, joka käteni opettaa sotimaan, ja sormeni tappelemaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Minun laupiuteni ja minun linnani, minun varjelukseni ja minun vapahtajani, minun kilpeni, johon minä uskallan, joka minun kansani minun alleni vaatii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Herra, mikä on ihminen, ettäs häntä korjaat? eli ihmisen poika, ettäs hänestä otat vaarin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'On sittekin ihminen tyhjän verta: hänen aikansa katoo niinkuin varjo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Herra, kallista sinun taivaas, ja astu alas: rupee vuoriin, että he suitsisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Anna leimaukset iskeä, ja hajoita heitä: ammu nuolias ja kauhistuta heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Lähetä kätes ylhäältä, ja kirvota minua, ja pelasta minua suurista vesistä ja muukalaisten lasten käsistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Joiden suu puhuu valhetta, ja heidän oikia kätensä on petollinen oikia käsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Jumala, minä veisaan sinulle uuden virren: minä soitan sinulle kymmenkielisellä psaltarilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Sinä joka kuninkaille voiton annat, ja palvelias Davidin vapahdat murhamiekasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Päästä myös minua ja pelasta minua muukalaisten kädestä, joiden suu puhuu valhetta, ja heidän oikia kätensä on petollinen oikia käsi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Että meidän pojat kasvaisivat nuoruudessansa niinkuin vesat, ja meidän tyttäret, niinkuin templin kaunistetut seinät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Meidän aittamme olkoon täynnä, jotka runsaat elatukset antaisivat toinen toisensa perästä, että meidän lampaamme poikisivat tuhannen, ja sata tuhatta, kylissämme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Että härkämme olisivat vahvat työhön; ettei yhtään vahinkoa, eikä valitusta eli kannetta olisi kaduillamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Autuas on se kansa, jolle niin käy; vaan autuas on se kansa, jonka Jumalana Herra on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Davidin kiitos. Minä ylistän sinua, Jumalani, sinä kuningas, ja kiitän sinun nimeäs aina ja ijankaikkiseti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Joka päivä minä kunnioitan sinua, ja kiitän sinun nimeäs aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Suuri on Herra, ja sangen kunniallinen, ja hänen suuruutensa on sanomatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Suku pitää suvulle jutteleman sinun töitäs, ja sinun voimastas puhuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Minä ajattelen sinun suuren kunnias kauneutta ja sinun ihmeitäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Että puhuttaisiin sinun ihmeellisten töittes voimasta: ja sinun suurta herrauttas minä juttelen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Että sinun suuren hyvyytes muisto ylistettäisiin, ja sinun vanhurskautes kiitettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Armollinen ja laupias on Herra, hidas vihaan ja sangen hyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Suloinen on Herra kaikille, ja armahtaa kaikkia tekojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Kiittäkään sinua, Herra, kaikki sinun tekos, ja sinun pyhäs kiittäkään sinua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Julistakaan sinun valtakuntas kunniaa, ja puhukaa sinun voimastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Että sinun voimas tulis ihmisten lapsille tiettäväksi, ja sinun valtakuntas suuri kunnia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Sinun valtakuntas on ijankaikkinen valtakunta, ja sinun herrautes pysyy suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Herra tukee kaikkia kaatuvaisia, ja nostaa kaikkia sullotuita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Kaikkein silmät vartioitsevat sinua, ja sinä annat heille ruan ajallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Sinä avaat kätes, ja ravitset kaikki, kuin elävät, suosiolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Vanhurskas on Herra kaikissa teissänsä, ja laupias kaikissa töissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Läsnä on Herra kaikkia, jotka häntä avuksensa huutavat, kaikkia, jotka totuudessa häntä avuksensa huutavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Hän tekee, mitä häntä pelkääväiset halajavat, ja kuulee heidän huutonsa, ja auttaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Herra varjelee kaikkia, jotka häntä rakastavat, ja hukuttaa kaikki jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Minun suuni pitää puhuman Herran kiitoksen, ja kaikki liha kunnioittakaan hänen pyhää nimeänsä, aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja! Kiitä Herraa, minun sieluni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Minä kiitän Herraa niinkauvan kuin minä elän, ja Jumalalleni kiitoksen veisaan, niinkauvan kuin minä täällä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Älkäät uskaltako päämiehiin; ihmiset he ovat, ei he voi mitään auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Sillä ihmisen henki pitää erkaneman, ja hänen täytyy maaksi tulla jälleen: silloin ovat kaikki hänen aivoituksensa hukassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Autuas on se, jonka apu Jakobin Jumala on, jonka toivo Herrassa hänen Jumalassansa on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Joka taivaan ja maan, meren ja kaikki, jotka niissä ovat, tehnyt on, joka totuuden pitää ijankaikkisesti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Joka oikeuden saattaa niille, jotka väkivaltaa kärsivät, joka isoovaiset ravitsee. Herra kirvottaa vangitut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Herra avaa sokian silmät: Herra nostaa kukistetut: Herra rakastaa vanhurskaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Herra varjelee vieraat, ja holhoo orpoja ja leskiä, ja jumalattomain tien hajoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Herra on kuningas ijankaikkisesti, sinun Jumalas, Zion, suvusta sukuun, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Kiittäkäät Herraa! sillä Jumalaamme kiittää on kallis asia: kiitos on suloinen ja kaunis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Herra rakentaa Jerusalemin, ja kokoo hajoitetut Israelilaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Hän parantaa murretut sydämet, ja sitoo heidän kipunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Hän lukee tähdet, ja kutsuu heitä kaikkia nimeltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Suuri on meidän Herramme, ja suuri hänen voimansa, ja hänen viisautensa on määrätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Herra ojentaa raadolliset, ja jumalattomat maahan paiskaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Vuoroin veisatkaat Herralle kiitossanalla, ja veisatkaat meidän Herrallemme kanteleella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Joka taivaan pilvillä peittää ja antaa sateen maan päälle; joka ruohot vuorilla kasvattaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Joka eläimille antaa heidän ruokansa, ja kaarneen pojille, jotka häntä avuksensa huutavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ei hän mielisty hevosten väkevyyteen, eikä hänelle kelpaa miehen sääriluut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Herralle kelpaavat ne, jotka häntä pelkäävät, ja jotka hänen laupiuteensa uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Ylistä, Jerusalem, Herraa: kiitä, Zion, sinun Jumalaas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Sillä hän vahvistaa sinun porttis salvat, ja siunaa sinussa sinun lapses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Hän saattaa rauhan sinun ääriis, ja ravitsee sinua parhailla nisuilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Hän lähettää puheensa maan päälle: hänen sanansa nopiasti juoksee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Hän antaa lumen niinkuin villan; hän hajoittaa härmän niinkuin tuhan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Hän heittää rakeensa niinkuin palat; kuka hänen pakkasensa edessä kestää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Hän lähettää sanansa, ja sulaa ne; hän antaa tuulen puhaltaa, niin vedet juoksevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Hän ilmoittaa Jakobille sanansa, ja Israelille säätynsä ja oikeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Ei hän niin tehnyt kaikille pakanoille; eikä he tiedä hänen oikeuttansa, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja! Kiittäkäät Herraa taivaissa, kiittäkäät häntä korkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Kiittäkäät häntä kaikki hänen enkelinsä: kiittäkäät häntä kaikki hänen sotaväkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Kiittäkäät häntä aurinko ja kuu: kiittäkäät häntä kaikki kirkkaat tähdet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Kiittäkäät häntä, te taivasten taivaat, ja vedet, jotka taivasten päällä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Heidän pitää Herran nimeä kiittämän; sillä hän käski, ja ne luoduksi tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Hän pitää ylös ne aina ja ijankaikkisesti: hän asettaa heitä, ettei heidän toisin käymän pitäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Kiittäkäät Herraa maan päällä, te valaskalat ja kaikki syvyydet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Tuli ja rakeet, lumi ja sumu, tuulispää, jotka hänen sanansa toimittavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Vuoret ja kaikki kukkulat, hedelmälliset puut ja kaikki sedripuut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Pedot ja kaikki eläimet, madot ja siivelliset linnut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Maan kuninkaat ja kaikki kansat, päämiehet ja kaikki tuomarit maan päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Nuorukaiset ja neitseet, vanhat nuorten kanssa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Kiittäkään Herran nimeä; sillä hänen ainoan nimensä on korotettu, ja hänen suuri kunniansa ylitse maan ja taivaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Ja hän korottaa sarven kansallensa: kaikki hänen pyhänsä kiittäkäät, Israelin lapset, kansa joka häntä lähin on, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja! Veisatkaat Herralle uusi veisu: pyhäin seurakunnan pitää häntä kiittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Iloitkaan Israel tekiässänsä: Zionin lapset riemuitkaan Kuninkaastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Heidän pitää tanssissa hänen nimeänsä kiittämän: harpuilla ja kanteleilla pitää heidän soittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Sillä Herra rakastaa kansaansa: hän kunnioittaa nöyriä autuudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Pyhäin pitää iloitseman kunnialla, ja kiittämän vuoteissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Heidän suussansa pitää Jumalan ylistys oleman, ja kaksiteräiset miekat heidän käsissänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Kostamaan pakanoille, ja rankaisemaan kansoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Heidän kuninkaitansa sitomaan kahleisiin, ja heidän jaloimpiansa rautakahleisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Ja tekemään heille kirjoitetun oikeuden: tämä kunnia pitää kaikille hänen pyhillensä oleman, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja! Kiittäkäät Herraa hänen pyhässänsä: kiittäkäät häntä hänen väkevyytensä avaruudessa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Kiittäkäät häntä hänen voimallisten tekoinsa tähden: kiittäkäät häntä ylenpalttisen suuruutensa tähden!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Kiittäkäät häntä basunilla: kiittäkäät häntä psaltareilla ja kanteleilla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Kiittäkäät häntä harpuilla ja tanssilla: kiittäkäät häntä harpun kielillä ja huiluilla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Kiittäkäät häntä kilisevillä symbaleilla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Kaikki, joilla henki on, kiittäkään Herraa, Halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Salomon, Davidin pojan, Israelin kuninkaan sananlaskut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Oppia viisautta ja kuritusta, ymmärtää tiedon puhetta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Vastaanottaa ymmärryksen neuvoa, vanhurskautta, oikeutta ja siveyttä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Että tyhmät viisaaksi tulisivat ja nuorukaiset taidon ja ymmärryksen saisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Joka viisas on, se kuulkaan, että jän viisaammaksi tulis; ja joka toimellinen on, se ottakoon neuvon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Että hän ymmärtäis sananlaskut ja niiden selityksen, viisasten opin ja heidän tapauksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Herran pelko on viisauden alku; tyhmät hylkäävät viisauden ja opin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Poikani kuule isäs kuritusta, ja älä hylkää äitis käskyä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Sillä se on sinun sinun pääs päällä otollinen kaunistus, ja käädyt kaulassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Poikani! jos pahanjuoniset sinua sinua houkuttelevat, niin älä heihin suostu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Jos he sanovat: käy meidän kanssamme: me väijymme verta, ja viritämme pauloja nuhteettoman eteen ilman syytä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Me nielemme hänen, niinkuin helvetti elävältä, ja hurskaan niinkuin hautaan pudotamme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Me löydämme kaikellaista kallista tavaraa, ja täytämme huoneemme saaliista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Koettele meidän kanssamme: meillä kaikilla pitää yksi kukkaro oleman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Poikani! älä vaella heidän kanssansa: estä jalkas heidän retkiltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Sillä heidän jalkansa juoksevat pahuuteen, ja he kiiruhtavat verta vuodattamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Sillä turhaan verkot viritetään lintuin silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Itse he myös väijyvät toinen toisensa verta, ja petoksella seisovat toinen toisensa hengen perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Niin kaikki ahneet tekevät, ja ahneus on isännillensä surmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Viisaus ulkona valittaa, ja kadulla äänensä ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'Hän huutaa kansan edessä portissa, ja tuottaa sanansa edes kaupungissa, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Kuinka kauvan te tyhmät tahdotte olla taitamattomat, ja pilkkakirveet rakastaa naurua? ja te hullut vihata opetusta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Kääntäkäät itsenne minun kuritukseni puoleen: katso, ja minä tuon teille henkeni edes, ja ilmoitan teille sanani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Että minä kutsuin teitä, ja te estelitte teitänne: minä kokotin käteni, ja ei yksikään ottanut siitä vaaria,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Te hylkäsitte kaiken neuvoni, ja ette tahtoneet kuritustani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Niin minä myös nauran teidän vahinkoanne, ja pilkkaan teitä, kuin teidän päällenne tulee se, jota te pelkäätte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Kuin se tulee, jota te pelkäätte, niinkuin rajuilma, ja tuska niinkuin tuulispää; kuin teidän päällenne tulee ahdistus ja vaiva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Silloin he minua avuksensa huutavat, ja en minä kuule heitä: varhain he etsivät minua, ja ei löydä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Että he vihasivat opetusta, ja ei ottaneet vastaan Herran pelkoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Eikä tyytyneet minun neuvooni, mutta laittivat kaiken kuritukseni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Niin pitää heidän syömän tiensä hedelmästä, ja neuvostansa ravituksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Sillä tyhmäin himo tappaa heidät, ja hulluin onni kadottaa heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Mutta joka minua kuulee, hän asuu turvallisesti, ja ei mitään pahaa pelkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Poikani, jos otat minun puheeni, ja käskyni kätket;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Niin anna korvas kuulla viisautta, ja taivuta sydämes ymmärrykseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Sillä jos ymmärrystä ahkerasti halajat, ja rukoilet taitoa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Jos sitä etsit niinkuin hopiaa, ja pyörit sen perään niinkuin tavaran;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Niin sinä ymmärrät Herran pelvon, ja Herran tunnon löydät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Sillä Herra antaa viisauden, ja hänen suustansa tulee taito ja ymmärrys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Hän antaa toimellisten hyvin käydä, ja suojelee niitä, jotka viattomasti vaeltavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Varjelee hurskaat, ja holhoo pyhäinsä retket.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Silloin sinä ymmärrät vanhurskauden ja tuomion, oikeuden ja kaiken hyvän tien.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Jos viisaus sydämees tulee, ja taito on sinulle kelvollinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Niin hyvä neuvo sinua varjelee, ja ymmärrys kätkee sinun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Tempaamaan sinun pois pahalta tieltä, ja niiden seurasta, jotka toimettomia puhuvat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Ja hylkäävät oikian tien, ja vaeltavat pimeitä retkiä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Jotka iloitsevat pahoista töistänsä, ja riemuitsevat pahoista menoistansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Joiden tiet ovat vastahakoiset, ja retket väärär ja häpiälliset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Ettet sinä ryhtyisi vieraaseen vaimoon, joka ei sinun ole, joka suloisilla sanoilla puhuttelee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Ja hylkää nuoruutensa johdattajan, ja unohtaa Jumalansa liiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Sillä hänen huoneensa kallistuu kuolemaan, ja hänen askeleensa kadotettuin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Jokainen joka menee hänen tykönsä, ei palaja, eikä elämän tielle joudu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Ettäs vaeltasit hyvää tietä, ja pitäisit hurskasten tiet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Sillä vanhurskaat asuvat maassa, ja vakaat siinä pysyvät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Mutta jumalattomat hukutetaan maasta, ja ylönkatsojat siitä teloitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Poikani, älä unohda minun lakiani, mutta sinun sydämes pitäköön käskyni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Sillä ne saatavat sinulle pitkän ijän, hyvät vuodet ja rauhan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Armo ja totuus ei sinua pidä hylkäämän: ripusta ne kaulaas, ja kirjoita sydämes tauluun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Niin sinä löydät armon ja hyvän toimen, Jumalan ja ihmisten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Luota Herraan kaikesta sydämestäs, ja älä luota ymmärryksees;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Mutta ajattele häntä kaikissa teissäs, niin hän sinua oikein johdattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Älä ole viisas mielestäs, vaan pelkääerraa, ja vältä pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Sillä se on navalles terveellinen, ja virvoittaa luus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Kunnioita Herraa tavarastas, ja kaikista vuoden tulos esikoisista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'Niin sinun riihes täytetään kyllyydellä, ja sinun viinakuurnas vuotaa ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Poikani, älä Herran kuritusta hylkää, ja älä ole kärsimätön, kuin hän sinua rankaisee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Sillä, jota Herra rakastaa, sitä hän rankaisee, ja on hänelle otollinen niinkuin poika isällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Autuas on se ihminen, joka viisauden löytää, ja se ihminen, joka ymmärryksen käsittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Sillä parempi on kaupita häntä kuin kaupita hopiaa, ja hänen hedelmänsä on parempi kuin kulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Hän on kalliimpi kuin päärlyt, eikä hänen vertaansa mitään toivottaa taideta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Pitkä ikä on hänen oikialla kädellänsä, rikkaus ja kunnia hänen vasemmallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Hänen tiensä ovat iloiset, ja kaikki hänen askeleensa rauha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Hän on elämän puu niille, jotka häneen rupeevat; ja autuaat ovat ne, jotka hänen pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Sillä Herra on viisaudella maan perustanut, ja taivaat toimella valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Hänen viisaudessansa ovat syvyydet eroitetut, ja pivet pisaroivat kasteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Poikani, älä salli näitä silmistäs tulla pois, niin sinä tulet onnelliseksi ja viisaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'Se on sinun sielus elämä; ja sinun suus on otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Silloin sinä murheetoinna vaellat teissäs, ettet jalkaas loukkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Et sinä pelkää maata pantuas, mutta makaat; ja sinun unes on sinulle makia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ettei sinun tarvitse peljätä äkillistä hirmua, eikä jumalattomain hävitystä, kuin se tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Sillä Herra on sinun lohdutukses; hän varjelee sinun jalkas, ettei sitä saavuteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Älä estele tarvitsevalle hyvää tehdä, jos sinulla on varaa, ettäs sen tehdä taidat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Älä sano ystävälle: mene ja tule jälleen, huomenna minä sinulle annan; koska sinulla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Älä pyydä sinun ystäväs vahinkoa, joka hyvässä toivossa asuu sinun tykönäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Älä kenenkään kanssa toru ilman syytä, jos hän ei mitään pahaa sinulle tehnyt ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Älä kiivoittele väärää miestä, älä noudata hänen retkiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Sillä pahanilkiset ovat Herralle kauhistus; mutta hänen salaisuutensa on hurskasten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Jumalattoman huoneessa on Herran kirous; muttavanhurskaan maja siunataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Hän pilkkaa pilkkaajia; mutta nöyrille hän antaa armon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Viisaat kunnian perivät, mutta tyhmät häpiän saavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Kuulkaat, lapseni, isänne kuritusta, ja ottakaa vaari, oppiaksenne ja viisaammaksi tullaksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Sillä minä annan teille hyvän opetuksen; älkööt hyljätkö minun lakiani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Sillä minä olin isäni poika, hoikka ja ainoa äidilläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Ja hän opetti minua, ja sanoi minulle; anna sydämes ottaa minun sanani vastaan: pidä minun käskyni, niin sinä elää saat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Osta viisaus, osat ymmärrys: älä unohda, älä myös poikkee minun puheestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Älä häntä hylkää, niin hän sinut kätkee: rakasta häntä, niin hän sinua varjelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Sillä viisauden alku on, ostaa viisautta, ja kaikella saadullas ostaa taitoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Pidä häntä korkiassa kunniassa, niin hän sinua korottaa, ja saattaa kunniaan, jos sinä häntä rakastat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Hän sinun pääs jalosti kaunistaa, ja kunnioittaa sinua ihanalla kruunulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Kuule siis, poikani, ja ota minun puheeni, niin ikäs vuotta on monta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Minä johdatan sinua viisauden tielle, ja saatan sinua käymään oikialla retkellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Niin että koskas vaellat, ei sinun käymises ole ahdas; ja koskas juokset, niin et sinä loukkaa sinuas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Pidä kuritus, älä hylkää häntä: kätke häntä; sillä hän on sinun elämäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Älä mene jumalattomain askelille, ja älä astu pahain tielle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Jätä se pois, ja älä käy siinä; karta sitä, ja mene ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Sillä ei he makaa, jollei he ole pahoin tehneet, eikä lepää, jollei he ole vahinkoa tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Sillä he syövät jumalattomuuden leipää, ja juovat vääryyden viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mutta vanhurskasten retki paistaa niinkuin valkeus, käy edes, ja valistaa hamaan isoon päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Mutta jumalattomain tie on niinkuin pimeys; ja ei he tiedä, kussa he lankeevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Poikani, ota vaari sanoistani, ja kallista korvas puheisiini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Älä niiden anna tulla pois silmistäs: pidä ne sydämessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Sillä ne ovat niiden elämä, jotka niitä ovat löytäneet, ja ovat terveelliset koko heidän ruumiillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Varjele sydämes kaikella ahkeruudella: sillä siitä elämä tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Pane pois paha suu, ja väärät huulet anna olla sinustas kaukana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Katsokoon silmäs oikein eteensä, ja sinun silmäs laudat olkoot oikiat edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Koettele jalkais askeleet, niin kaikki sinun ties vahvistuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Älä poikkee oikialle eli vasemmalle puolelle: tempaa jalkas pois pahuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Poikani, ota vaari viisaudestani: kallista korvas oppiini,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Ettäs pitäisit hyvän neuvon, ja sinun huules pitäis toimen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Sillä porton huulet ovat niin kuin mesileipä, ja hänen kitansa liukkaampi kuin öljy;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Mutta viimeiseltä karvas kuin koiruoho, ja terävä kuin kaksiteräinen miekka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Hänen jalkansa menevät alas kuolemaan, ja hänen askeleensa joutuvat helvettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Ei hän käy kohdastansa elämän tielle: huikentelevaiset ovat hänen astumisensa, niin ettei hän tiedä, kuhunka hän menee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Niin kuulkaat nyt minua, lapseni, ja älkäät poiketko minun puheistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Olkoon sinun ties kaukana hänestä, ja älä lähesty hänen hänen huoneensa ovea,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Ettes antaisi kunniaas muukalaisille, ja vuosias julmille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Ettei muukalaiset ravittaisi sinun varastas, ja sinun työs olis toisen huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'Ja sinä viimein huokaisit, koska elämäs ja hyvyytes tuhlannut olet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'Ja sanoisit: voi! kuinka minä olen vihannut hyvää neuvoa, ja sydämeni on hyljännyt kurituksen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Ja en kuullut opettajani ääntä, enkä kallistanut korvaani opettajaini puoleen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Minä olen lähes kaikkeen pahuuteen joutunut, kaiken kansan ja seurakunnan keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Juo vettä kaivostas, ja mitä lähteestäs vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Anna luontolähtees vuotaa ulos, ja vesiojas kujille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Mutta pidä ne yksinäs, ja ei yksikään muukalainen sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Sinun kaivos olkoon siunattu, ja iloitse nuoruutes vaimosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Se on suloinen niinkuin naaras hirvi, ja otollinen niinkuin metsävuohi: hänen rakkautensa sinua aina ravitkoon; ja iloita itseäs aina hänen rakkaudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Poikani, miksis annat muukalaisen sinuas pettää, ja halajat vierasta syliä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Sillä Herran edessä ovat kaikkien ihmisten tiet, ja hän tutkii kaikki heidän askeleensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Jumalattoman vääryys käsittää hänen, ja hänen syntinsä paulat ottavat hänet kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Hänen pitää kuoleman, ettei hän antanut opettaa itsiänsä, ja suuressa tyhmyydessänsä tulee hän petetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Poikani, jos sinää takaat lähimmäises, niin sinä olet kiinnittänyt kätes muukalaiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Sinun sanoissas olet sinä paulaan istunut: sinä olet saavutettu puheissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'ee siis, poikani, näin: pelasta itses: sillä olet tullut lähimmäises käsiin: joudu, nöyryytä itses ja vaadi lähimmäistäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Älä anna silmilles unta, eikä silmälautas torkkua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Kirvoita itses niinkuin metsävuohi pois käsistä, niinkuin lintu pyytäjänsä käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Mene laiska myyriäisen tykö, katso hänen menoansa ja opi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Vaikka ei hänelläyhtään hallitsiaa, teettäjää ja isäntää ole,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Kuitenkin valmistaa hän elatuksensa suvella, ja koo ruokansa eloaikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Kuinka kauan sinä laiska makaat? koskas nouset unesta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Makaa vielä vähä, ota vielä unta päähäs; laske kätes vähä yhteen, ettäs vielä levätä voisit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Niin köyhyys äkisti tulee päälles niinkuin matkamies, ja vaivaisuus niinkuin varustettu mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Jumalatoin ihminen, vahingollinen mies, kävelee suunsa vääryydellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Iskee silmää, nyhtää jalvoillansa, kokottelee sormillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Vääryys on hänen sydämessänsä, ja aikoo pahaa: hän saattaa riidat matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Sentähden tulee pikaisesti hänen kadotuksensa, ja hän äkisti muserretaan rikki, niin ettei hänellä yhtään parannusta ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Kuusi on, joita Herra vihaa, ja seitsemää kauhistuu hänen sielunsa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Ylpiät silmät, petollinen kieli, kädet, jotka vuodattavat viatonta verta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Sydän, joka vahingollisia ajattelee, jalat, jotka ovat nopsat pahuuteen juoksemaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Väärä todistaja, joka valheita tuottaa, ja se, joka saattaa riidan veljesten välille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Poikani, pidä isäs käskyt, ja älä hylkää äitis lakia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Sido ne alati yhteen sydämes päälle, ja ripusta ne kaulaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Koskas vaellat, niin ne johdattavat sinua; koskas lepäät, niin he varjelevat sinua; koskas heräät, niin he puhuttelevat sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Sillä käsky on niinkuin kynttilä, ja laki niinkuin valkeus, ja opin kuritus elämän tie,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Ettäs varjeltaisiin pahasta vaimosta, ja muukalaisen makiasta kielestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Älä himoitse sydämessäs hänen kauneuttansa, ettes vieteltäisi hänen silmäinsä kiillosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Sillä portto saattaa leivältä pois; mutta aviovaimo saattaa kauniin elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Taitaako joku kätkeä tulen poveensa, ettei hänen vaattensa pala?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Eli taitaako joku hiilten päällä kävellä, ettei hän jalkojansa polta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Niin sille tapahtuu, joka lähimmäisensä vaimoa lähentelee; ei se pääse rankaisematta, joka häneen ryhtyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Ei se ole varkaalle niin suuri häpiä, jos hän varastaa henkensä piteeksi, koska nälkä on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Jos hän käsitetään, antaa hän sen seitsemänkertaisesti jälleen, ja kaiken huoneensa saadun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Mutta joka vaimon janssa huoruuteen lankee, se on tyhmä, ja joka sielunsa kadottaa tahtoo, se niin tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Rangaistus ja häpiä tulee hänen päällensä, ja hänen häväistyksensä ei pyyhitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Sillä miehen vihalla on kiivaus: ei hän säästä häntä koston päivänä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Ei hän lukua pidä sovittajasta, eikä ota lahjoja, vaikka paljon antaisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Poikani! kätke minun sanani, ja pidä tykönäs minun käskyni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Ota vaari minun käskyistäni, niin sinä elää saat, ja minun laistani, niinkuin silmäs terästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Sido ne sormiis, kirjoita ne sydämes tauluun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Sano viiisaudelle: sinä olet sisareni, ja kutsu toimi ystäväkses,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Että hän sinua varjelis muukalaisesta vaimosta, ja vieraasta, jonka sanat sileät ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Sillä minä kurkistelin huoneeni akkunasta läpi häkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'Ja näin tyhmän nuorukaisen taitamattomain seassa, ja äkkäsin hänen poikain joukossa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Joka käveli kaduilla hänen nurkkainsa taitse, ja asteli sitä tietä, joka meni hänen huoneeseensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Hämärissä, kuin päivä ehtoolla oli, ja jo yö ja pimiä tuli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Ja katso, häntä kohtasi vaimo porton vaatteilla, kavala,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Tuima ja hillimätöin, jonka jalat ei pysyneet huoneessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Nyt on hän ulkona, nyt kaduilla, ja väijyy joka nurkassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Hän otti hänen kiinni, ja suuta antoi hänen ja sanoi häpeemättä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Minä olen tehnyt kiitosuhrin, ja olen tätäpänä täyttänyt lupaukseni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Sentähden olen minä tullut sinua vastaan, varhain sinua etsimään, ja olen nyt sinut löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Minä olen koreasti valmistanut vuoteeni Egyptin kirjavalla vaatteella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Ja olen hyvänhajuiseksi tehnyt kammioni mirhamilla, aloella ja kanelilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Tule, harjoittakaamme kyllin hekumaa aamuun asti, ja huvitelkaammme meitämme keskenämme rakkaudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Sillä mies ei ole kotona: hän on pitkälle matkalle mennyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Hän on ottanut rahasäkin myötänsä, ja tulee kotia äsken määrätyllä päivällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Ja niin hän houkutteli monelöla sanalla, ja vaati häntä makialla puheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Hän meni hänen kanssansa nopiasti, niinkuin teurastettava härkä, ja niinkuin jalkapuuhun, jolla tyhmät rangoitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Siihenasti kuin hän nuolilla ampuu hänen maksansa lävitse: ja niinkuin lintu itsensä kiiruhtaa paulaan, ja ei tiedä sitä hengellensä vaaralliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Niin kuulkaat siis minua, minun lapseni, ja ottakaat vaari minun suuni sanoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Älköön sydämes poiketko hänen tiellensä: älä salli sinuas vietellä hänen retkillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Sillä hän on monta haavoittanut ja langettanut, ja kaikkinaiset voimalliset ovat häneltä tapetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Hänen huoneensa ovat helvetin tiet, jotka menevät alas kuoleman kammioihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Eikö viisaus huuda, ja toimi julista ääntänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Korkialla paikalla seisoo hän, teiden ja kujain vieressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Porteilla, kaupungin ovilla, joista sisälle käydään, hän huutaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Te miehet! minä huudan teitä, ja minun ääneni on teidän tykönne, te ihmisten lapset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Ymmärtäkäät te tyhmät viisautta, ja te houkkiot pankaat sydämiinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Kuulkaat, sillä minä puhun sitä, mikä korkia on, opetan sitä, mikä oikia on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Sillä minun suuni puhuu totuutta, ja minun huuleni vihaa jamalatointa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Kaikki minun puheeni ovat oikiat: ei ole siinä mitään petosta eli vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Ne kaikki ovat selkiät niille, jotka niitä ymmärtävät, ja oikiat niille, jotka taidon löytävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Ottakaat minun kuritukseni ennenkuin hopia, ja pitäkäät korkiampana minun oppini kuin kallein kulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Sillä viisaus on parempi kuin päärlyt, ja kaikki, mitä ihminen itsellensä toivottaa, ei ole hänen vertaisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Minä viisaus asun toimen tykönä, ja minä taidan antaa hyvän neuvon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Se on Herran pelko: vihata pahaa, ylpeyttä, tuimuutta ja pahoja teitä; sentähden vihaan minä petollista suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Minun on neuvo ja voima, minun on toimi ja väkevyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Minun kauttani kuninkaat hallitsevat, ja neuvonantajat oikeutta saattavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Minun kauttani päämiehet vallitsevat, valtamiehet ja kaikki maan tuomarit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Minä rakastan niitä, jotka minua rakastavat, jotka varhain minua etsivät, ne löytävät minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Rikkaus ja kunnia on minun tykönäni, pysyväinen tavara ja vanhurskaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Minun hedelmäni on parempi kuin kulta ja rikkain kulta, ja minun tuloni parempi kuin valittu hopia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Minä vaellan vanhurskaudentietä ja oikeuden askeleilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Että minä pysyväisen perinnön saattaisin niille, jotka minua rakastavat, ja täyttäisin heidän tavaransa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Minä olen ollut Herran oma hänen teidensä alussa: ennenkuin mitään tehty oli, olin minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Jo ijankaikkisuudesta olen minä asetettu, alussa, ennenkuin maa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Kuin ei syvyys vielä ollut, silloin minä olin jo syntynyt, kuin ei lähteet vielä vettä kuohuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Ennen kuin vuoret olivat perustetut, ja kukkulat valmistetut, olen minä syntynyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Ei hän ollut vielä maata luonut, ja mitä sen päällä on, eikä maan piirin vuoria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Kuin hän valmisti taivaan, olin minä siellä, kuin hän syvyyden visusti mittasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Kuin hän pilvet rakensi ylhäällä, ja sääsi syvyyden lähteet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Kuin hän meren ääret määräsi, ja vetten eteen asetti määrän, ettei he astuisi rantansa ylitse; kuin hän maan perustukset laski,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Silloin minä hänen kanssansa vaikutin, ja iloitsin joka päivä, ja leikitsin hänen hänen edessänsä joka aika;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Ja leikitsin maan piirin päällä; ja minun iloni on olla ihmisten lasten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Niin kuulkaat siis minua, te lapset: autuaat ovat ne, jotka minun tieni pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Kuulkaat kuritusta, olkaat viisaat, ja älkäät hyljätkö sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Autuas on se ihminen, joka minua kuulee, joka minun ovellani valvoo joka päivä, ja vartioitsee minun pihtipielissäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Sillä joka minun löytää, hän elämän löytää, ja on Herralle otollinen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Mutta, joka minua vastaan syntiä tekee, hän vahingoitsee sielunsa: jokainen joka minua vihaa, hän rakastaa kuolemaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Viisaus rakensi huoneensa, ja vuoli siihen seitsemän patsasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Ja teurasti teuraansa, sekoitti viinansa ja valmisti pöytänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Ja lähetti piikansa, korkeista kaupungin saleista kutsumaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Joka tyhmä on, hän tulkaan tänne; ja hulluille sanoi hän:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Tulkaat ja syökäät minun leivästäni, ja juokaat viinaa, jonka minä sekoitin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Hyljätkää hullu meno, niin te saatte elää, ja käykää ymmärryksen tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Joka pilkkaajaa kurittaa, hän saa häpiän, ja joka jumalatointa nuhtelee, hän häväistään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Älä rankaise pilkkaajaa, ettei hän sinua vihaisi: nuhtele viisasta, ja hän rakastaa sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Anna viisaalle, niin hän viisaammaksi tulee: opeta vanhurskasta, niin hän opissaan etenee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Viisauden alku on Herran pelko, ja pyhäin tieto on ymmärrys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Sillä minun kauttani sinun päiväs enennetään, ja ikäs vuodet lisätään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Jos sinä olet viisas, niin sinä itselles viisas olet; mutta jos sinä olet pilkkaaja, niin sinä itse sen kannat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Hullu, huikentelevainen vaimo, mieletöin ei tiedä mitään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Istuu huoneensa ovella, korkialla istuimella, ylimmäisessä siassa kaupungissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Että hän houkuttelis kaikkia, jotka siitä käyvät ohitse, ja tietänsä vaeltavat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Se joka tyhmä on, hän tulkoon tänne; ja hullulle sanoo hän:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Varastettu vesi on makia, ja salattu leipä suloinen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Vaan ei hän tiedä, että siellä kuolleet ovat: hänen vieraansa ovat helvetin syvyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Salomon sananlaskut. Viisas poika on isänsä ilo, mutta hullu poika on äidillensä murheeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Väärin saatu tavara ei ole hyödyllinen; mutta vanhurskaus vapauttaa kuolemasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Ei Herra anna vanhurskasten sielun nälkää kärsiä, mutta jumalattomain väärin saadut hän hajoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Petollinen käsi tekee köyhäksi, mutta ahkera saattaa rikkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Joka suvella kokoo, hän on toimellinen, mutta joka elonaikana makaa, hän tulee häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Siunaus on vanhurskaan pään päällä, mutta jumalattoman suun peittää vääryys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Vanhurskaan muisto pysyy siunauksessa, vaan jumalattomain nimi mätänee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Joka sydämestänsä viisas on, hän ottaa käskyt vastaan; mutta jolla hullut huulet ovat, se saa haavoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Joka nuhteettomasti vaeltaa, hän elää murheetoinna; mutta joka väärällä tiellä vaeltaa, hän tulee ilmi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Joka silmää iskee, hän vaivaa matkaan saattaa, ja jolla hullut huulet ovat, hän saa haavoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Vanhurskaan suu on elämän lähde, mutta jumalattoman suun peittää vääryys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Viha riidan saattaa, mutta rakkaus peittää kaikki rikokset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Toimellisten huulissa löydetään viisaus, vaan tyhmäin selkään tarvitaan vitsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Viisaat opin kätkevät, vaan hulluin suu on täynnä vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Rikkaan tavara on hänen vahva kaupunkinsa; mutta köyhyys tekee köyhän pelkuriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Vanhurskaus tekee työtä hengen ylöspitämiseksi, mutta jumalattoman saalis on symmiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Joka kurituksen ottaa vastaan, hän on elämän tiellä; mutta joka rangaistuksen heittää pois, hän menee väärin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Petolliset suut peittävät vainon, ja joka panettelee,hän on tyhmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Jossa paljo puhutaan, siitä ei synti ole kaukana; mutta joka huulensa hillitsee, hän on toimellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Vanhurskaan kieli on kalliimpi hopiaa, mutta jumalattoman sydän on miinkuin ei mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Vanhurskaan huulet monta ravitsevat, mutta hullut kuolevat hulluudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Herran siunaus tekee rikkaaksi ilman vaivaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Hullu tekee pahaa ja nauraa sitä, vaan viisas pitää siitä vaarinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Mitä jumalatoin pelkää, se hänelle tapahtuu, ja mitä vanhurskaat himoitsevat, sitä heille annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Jumalatoin on niinkuin tuulispää, joka menee ohitse ja tyhjiksi raukee; mutta vanhurskas pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Niin kuin etikka tekee pahaa hampaille ja savu silmille, niin on laiska niiden mielestä paha, jotka hänen lähettävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Herran pelko enentää päiviä, vaan jumalattomain vuodet vähennetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Vanhurskaan toivo on ilo, mutta jumalattomain toivo katoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Herran tie on hurskasten väkevyys, mutta pahointekiät ovat pelkurit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Vanhurskas pysyy aina kohdallansa kukistamatta, mutta jumalattoman ei pidä asuman maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Vanhurskaan suu tuottaa viisauden, vaan vääräin kieli hukutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Vanhurskaan huulet opettavat terveellisiä asioita, vaan jumalattoman suu on täynnä vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Väärä vaaka on Herralle kauhistus, mutta oikia puntari on hänelle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Kussa ylpeys on, siinä on myös ylönkatse; mutta viisaus on nöyräin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Viattomuus johdattaa siviät, vaan pahuus kukistaa pilkkaajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Ei rakkaus auta vihan päivänä, mutta vanhurskaus vapahtaa kuolemasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Viattoman vanhurskaus tekee hänen tiensä tasaiseksi, mutta jumalatoin lankee jumalattomassa menossansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Jumalisten vanhurskaus pelastaa heitä, vaan väärintekiät käsitetään viekkaudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Kuin jumalatoin ihminen kuolee, niin ei ole yhtään toivoa: ja jota väärintekiät odottavat, se tulee tyhjäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Vanhurskas vapahdetaan vaivasta, ja jumalatoin tuleehänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Ulkokullatun ihmisen suun kautta petetään hänen lähimmäisensä; vaan vanhurskaat ymmärtävät sen, ja pelastetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Kaupunki iloitsee, koska vanhurskaan hyvin käy, ja riemuitsee, koska jumalatoin hukkuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Vanhurskasten siunauksen kautta kaupunki korotetaan, vaan jumalattoman suun kautta kukistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Joka lähimmäistänsä häpäisee, se on hullu, mutta toimellinen mies on vaiti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Panettelia ilmoittaa salaisuuden, vaan jolla on uskollinen sydän, hän salaa sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Jossa ei neuvoa ole, siinä kansa hukkuu; vaan jossa monta neuvonantajaa on, siinä hyvin käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Joka toisen takaa, hän tulee vahinkoon; vaan joka siitä itsensä pitää pois, hän on murheetoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Vaimo, joka otollinen on, pitää kunnian; vaan väkevät pitävät rikkauden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Armias mies tekee ruumiillensa hyvää; vaan se, joka julma on, saattaa lihansa murheelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Jumalattoman työ on turha, vaan joka vanhurskautta kylvää, sillä on hyvä palkka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Sillä vanhurskaus saattaa elämän, vaan joka pahaa pyytää, hän saattaa kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Petollinen sydän on kauhistus Herralle, Vaan viattoman tie on hänelle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Ei jumalattoimia auta, vaikka kaikki kätensä yhteen pistäisivät, mutta vanhurskaan siemen pelastetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Kaunis vaimo ilman taidota on niinkuin sika, jolla olis kultainen käädy kuonossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Vanhurskasten himo on ainoastaan hyvä, vaan jumalattomain odotus on kiukku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Muutama jakaa omastansa, ja saa enemmän; toinen säästää, jossa ei pitäisi, ja tulee köyhemmäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Sielu, joka siunaa, tulee rikkaaksi: ja joka juottaa, se myös juotetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Joka jyvät salaa, häntä kansa kiroilee; mutta joka myy, hänelle tulee siunaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Joka varhain hyvää etsii, hänelle hyvin menestyy; mutta joka pahaa noudattaa, hänelle pahoin tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Joka rikkauteensa luottaa, hän hukkuu, vaan vanhurskaat viheriöitsevät niinkuin lehti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Joka huoneensa murheelliseksi tekee, hän saa tuulen perinnöksi: ja hullun täytyy viisasta palvella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Vanhurskaan hedelmä on elämän puu: joka viisas on, hän kääntää sielut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Koska vanhurskas paljon kärsii, kuinka paljoa enemmin jumalatoin ja syntinen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Joka itsensä mielellänsä kurittaa antaa, se tulee toimelliseksi; mutta joka rankaisematta olla tahtoo, se on tyhmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Hyvä saa lohdutuksen Herralta, mutta häijy mies hyljätään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ei ihminen vahvistu jumalattomuudessa, vaan vanhurskaan juuri on pysyväinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Ahkera vaimo on miehensä kruunu, vaan häijy on niinkuin märkä hänen luissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Vanhurskasten ajatukset ovat vilpittömät, vaan jumalattomain aivoitus on petollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Jumalattomain sanat väijyvät verta, vaan hurskasten suu vapahtaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Jumalattomat kaatuvat, ja ei ole sitte enää, mutta vanhurskasten huone pysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Toimellinen mies neuvossansa ylistetään, vaan petollinen tulee katsotuksi ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Parempi on nöyrä, joka omansa katsoo, kuin se, joka tahtoo iso olla, ja kuitenkin puuttuu leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Vanhurskas armahtaa juhtaansa, mutta jumalattoman sydän on halutoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Joka peltonsa viljelee, se saa leipää yltäkylläisesti; vaan joka turhia ajelee takaa, se on tyhmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Jumalatoin halajaa aina pahaa tehdä, mutta vanhurskaan juuri kantaa hedelmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Ilkiä käsitetään omissa sanoissansa, vaan vanhurskas pääsee hädästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Suun hedelmästä tulee paljon hyvää; ja niinkuin kukin käsillänsä tehnyt on, kostetaan hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Tyhmäin mielestä on hänen tiensä otollinen, mutta viisas ottaa neuvon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Tyhmä osoittaa kohta vihansa, vaan joka peittää vääryyden, se on kavala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Joka totuuden puhuu, se vanhurskauden ilmoittaa; mutta joka väärin todistaa, hän pettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Joka ajattelematta puhuu, hän pistää niinkuin miekalla; vaan viisasten kieli on terveellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Totinen suu pysyy vahvana ijankaikkisesti, vain väärä kieli ei pysy kauvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Jotka pahaa ajattelevat, niiden sydämessä on petos; vaan jotka rauhaa neuvovat, niillä on ilo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Ei vanhurskaalle mitään vaaraa tapahdu; vaan jumalattomat pahuudella täytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Petolliset huulet ovat Herralle kauhistus; vaan jotka oikein tekevät, ovat hänelle otolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Kavala salaa taitonsa, vaan hulluin sydän ilmoittaa hulluutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Ahkera käsi saa hallita, vaan laiskan täytyy veronalaiseksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Sydämellinen murhe kivistelee, vaan lohdullinen sana iloittaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Vanhurskas on parempi lähimmäistänsä, mutta jumalattoman tie viettelee hänen');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Ei petollinen asia menesty, mutta ahkera saa hyvän tavaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Vanhurskauden tiellä on elämä, ja hänen poluillansa ei ole kuolemaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Viisas poika ottaa isänsä kurituksen, mutta pilkkaaja ei tottele rangaistusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Suunsa hedelmästä kukin nautitsee hyvää, vaan jumalattomain sielu vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Joka suunsa hallitsee, hän saa elää; vaan joka suunsa toimettomasti avajaa, se tulee hämmästykseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Laiska pyytää ja ei saa, mutta viriät saavat yltäkylläisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Vanhurskas vihaa valhetta, mutta jumalatoin häpäisee ja pilkkaa itsiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Vanhurskaus varjelee nuhteettoman, mutta jumalatoin meno kukistaa syntisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Moni on köyhä suuressa rikkaudessa, ja moni rikas köyhyydessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Rikkaudellansa taitaa joku lunastaa henkensä; mutta joka köyhä on, ei hän kuule kuritusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Vanhurskasten valkeus tekee iloiseksi, vaan jumalattomain kynttilä sammuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Ylpeiden seassa on aina riita, mutta viisaus saattaa ihmisen toimelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Rikkaus vähenee tuhlatessa, vaan koossa pitäin se enenee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Viivytetty toivo vaivaa sydäntä; vaan kuin se tulee, jota hän toivoo, se on elämän puu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Joka sanan katsoo ylön, hän turmelee itsensä; mutta joka käskyä pelkää, hän rauhassa vaeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Viisaan oppi on elämän lähde, Välttämään kuoleman paulaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Hyvä neuvo on otollinen; vaan ylönkatsojain tie on kova.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Viisas tekee kaiken toimellisesti, vaan hullu ilmoittaa tyhmyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Jumalatoin sanansaattaja lankee onnettomuuteen, vaan totinen lähetys on terveellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Joka kurituksen hylkää, hänellä on köyhyys ja häpiä; vaan joka antaa itsensä rangaista, hän tulee kunniaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Kun toivo tulee täytetyksi, niin sydän iloitsee; mutta joka pahuutta välttää; on hulluille kauhistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Joka viisasten kanssa käyskentelee, hän tulee viisaaksi; vaan joka hulluin kumppani on, hän tulee vahinkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Pahuus noudattaa syntisiä, mutta vanhurskaille kostetaan hyvyydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Hyvällä on perilliset lasten lapsissa; vaan syntisen tavara vanhurskaalle säästetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Paljo ruokaa on köyhän kynnössä; vaan jotka vääryyttä tekevät, ne hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Joka vitsaansa säästää, hän vihaa lastansa; vaan joka häntä rakastaa, hän aikanansa sitä kurittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Vanhurskas syö, että hänen sielunsa ravittaisiin; vaan jumalattomain vatsa on tyytymätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Viisas vaimo rakentaa huoneensa, vaan hullu kukistaa sen teollansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Joka vaeltaa oikiaa tietä, se pelkää Herraa; mutta se, joka poikkee pois tieltänsä, ylönkatsoo hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Tyhmän suussa on ylpeyden vitsa; vaan viisasten huulet varjelevat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Jossa ei härkiä ole, siinä seimet puhtaana ovat; vaan jossa juhdat työtä tekevät, siinä tuloa kyllä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Totinen todistaja välttää valhetta; vaan väärä todistaja rohkiasti valhettelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Pilkkaaja etsii viisautta, ja ei löydä; vaan toimelliset viisauden huokiasti saavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Mene pois tyhmän tyköä; sillä et sinä opi mitään häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Toimellisen viisaus on teistänsä ottaa vaarin; vaan tyhmäin hulluus on sula petos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Tyhmä nauraa syntiä, mutta hurskasten välillä on hyvä suosio.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Koska sydän on murheellinen, niin ei auta ulkonainen ilo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Jumalattomain huoneet kukistetaan, vaan jumalisten majat viheriöitsevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Monella on tie mielestänsä oikia, vaan viimeiseltä johdattaa se kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Naurun jälkeen tulee murhe, ja ilon perästä suru.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Tyhmälle tapahtuu laittamisensa jälkeen, vaan hyvä ihminen asetetaan hänen ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Taitamatoin uskoo kaikki, mutta ymmärtäväinen ottaa teistänsä vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Viisas pelkää ja karttaa pahaa, vaan tyhmä päätähavin menee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Äkillinen ihminen tekee hullun töitä, ja kavala ihminen tulee vihattavaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Taitamattomat perivät tyhmyyden; vaan se on toimellisten kruunu, että he toimellisesti tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Häijyn täytyy kumartaa hyviä, ja jumalattomat vanhurskasten porteissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Köyhää vihaavat hänen lähimmäisensäkin; vaan rikkaalla on monta ystävää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Joka katsoo lähimmäisensä ylön. hän tekee syntiä; vaan autuas on se, joka viheliäistä armahtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Jotka viekkaudessa vaeltavat, niiltä puuttuu; mutta jotka hyvää ajattelevat, niille tapahtuu hyvyys ja uskollisuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Jossa työtä tehdään, siinä kyllä on; vaan joka tyhjiin puheisiin tyytyy, siinä on köyhyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Viisasten rikkaus on heidän kruununsa, mutta tyhmäin hulluus on hulluus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Uskollinen todistaja vapahtaa hengen, vaan väärä todistaja pettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Joka Herraa pelkää, hänellä on vahva linna, ja hänen lapsensa varjellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Herran pelko on elämän lähde, että kuoleman nuora välttää taidetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Koska kuninkaalla on paljo väkeä, se on hänen kunniansa; vaan koska vähä on väkeä, se tekee päämiehen kehnoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Joka on pitkämielinen, se on viisas; vaan joka äkillinen on, se ilmoittaa tyhmyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Leppyinen sydän on ruumiin elämä; vaan kateus on märkä luissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Joka köyhälle tekee väkivaltaa, hän laittaa hänen luojaansa; vaan joka armahtaa vaivaista, se kunnioittaa Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Pahuutensa tähden jumalatoin kukistetaan; vaan vanhurskas on kuolemassakin rohkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Toimellisen sydämessä lepää viisaus; mutta mitä tyhmäin mielessä on, se tulee ilmi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Vanhurskaus korottaa kansan, vaan synti on kansan häpiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Toimellinen palvelia on kuninkaalle otollinen; vaan häpiällistä palveliaa ei hän kärsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Suloinen vastaus hillitse vihan, mutta kova sana saattaa mielen karvaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Viisasten kieli saattaa opetuksen suloiseksi, vaan tyhmäin suu aina hulluuta sylkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Herran silmät katselevat joka paikassa, sekä pahat että hyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Terveellinen kieli on elämän puu: vaan valhettelevainen saattaa sydämen kivun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Tyhmä laittaa isänsä kurituksen; vaan joka rangaistuksen ottaa, hän tulee taitavaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Vanhurskaan huoneessa on yltäkyllä; vaan jumalattoman saalis on hävintö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Viisasten huulet jakavat neuvoa; vaan tyhmäin sydän ei ole niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Jumalattoman uhri on Herralle kauhistus; vaan jumalisten rukous on hänelle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Jumalattoman tie on Herralle kauhistus; vaan joka vanhursjautta noudattaa, on hänelle rakas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Kuritus on sille paha, joka hylkää tiensä: ja joka rangaistusta vihaa, hänen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Helvetti ja kadotus on Herran edessä: kunka paljon enemmin ihmisten lasten sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Ei pilkkaaja rakasta sitä, joka häntä rankaisee, ja ei hän mene viisasten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Iloinen sydän tekee iloiset kasvot; vaan koska sydän on surullinen, niin rohkeus raukee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Ymmärtäväinen sydän etsii viisautta; vaan tyhmäin suu tyhmyydellä ravitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Surullisella ihmisellä ei ole koskaan hyvää päivää; vaan jolla hyvä sydän on, hänellä on joka päivä vieraspito.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Parempi on vähä Herran pelvossa, kuin suuri tavara ilman lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Parempi on ateria kaalia rakkaudessa, kuin syötetty härkä vihassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Vihainen mies saattaa toran matkaan; mutta kärsivällinen asettaa riidan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Laiskan tie on orjantappurainen; vaan hurskasten tie on tasainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Viisas poika iloittaa isänsä, ja hullu ihminen häpäisee äitinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Hulluulle on tyhmyys iloksi; vaan toimellinen mies pysyy oikialla tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Aivoitus raukee ilman neuvoaa; vaan jossa monta neuvonantajaa on, se on vahva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Se on ihmisen ilo, että hän toimella vastata taitaa, ja aikanansa sanottu sana on otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Elämän tie johdattaa viisaan ylöspäin, välttämään helvettiä, joka alhaalla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Herra ylpeiden huoneet kukistaa, ja vahvistaa lesken rajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Ilkiäin aivoitukset ovat Herralle kauhistukseksi; vaan toimellinen puhe on otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Ahneudella voitetut kukistavat oman huoneensa; vaan joka lahjoja vihaa, saa elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Vanhurskaan sydän ajattelee vastausta; vaan jumalattoman suu ammuntaa pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Herra on kaukana jumalattomista; vaan hän kuulee vanhurskasten rukoukset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Suloinen kasvo iloittaa sydämen: hyvä sanoma tekee luut lihaviksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Korva, joka kuulee elämän rangaistusta, on asuva viisasten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Joka ei itsiänsä salli kurittaa, se katsoo ylön sielunsa; vaan joka rangaistusta kuulee, hän tulee viisaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Herran pelko on kuritus viisauteen, ja kunnian edellä käy nöyryys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Ihminen aikoo sydämessänsä; vaan Herralta tulee kielen vastaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Jokaisen mielestä on hänen tiensä puhdas; mutta Herra tutkistelee sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Anna Herran haltuun sinun työs, niin sinun aivoitukses menestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Herra tekee kaikki itse tähtensä, niin myös jumalattoman pahaksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Jokainen ylpiä on Herralle kauhistus, ja ei pääse rankaisematta, ehkä he kaikki yhtä pitäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Laupiuden ja totuuden kautta pahateko sovitetaan, ja Herran pelvolla paha vältetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Jos jonkun tiet ovat Herralle kelvolliset, niin hän myös kääntää hänen vihamiehensä rauhaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Parempi on vähä vanhurskaudessa, kuin suuri saalis vääryydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Ihmisen sydän aikoo tiensä; vaan Herra johdattaa hänen käymisensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Ennustus on kuninkaan huulissa: ei hänen suunsa puhu tuomiossa väärin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Oikia puntari ja vaaka on Herralta, ja kaikki painokivet kukkarossa ovat hänen tekoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Kuninkaan edessä on kauhistus väärin tehdä; sillä vanhurskaudella istuin vahvistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Oikia neuvo on kuninkaalle otollinen; ja joka oikein puhuu, häntä rakastetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Kuninkaan viha on kuoleman sanansaattaja; ja viisas mies lepyttää hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Kuin kuninkaan kasvo on leppyinen, siinä on elämä, ja hänen armonsa on niinkuin hiljainen sade.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Ota viisautta tykös, sillä se on parempi kultaa: ja saada ymmärrystä on kalliimpi hopiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Siviän tiet välttävät pahaa, ja joka sielunsa varjelee, se tiestänsä ottaa vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Joka alennetaan, se ensisti tulee ylpiäksi; ja ylpeys on aina lankeemuksen edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Parempi on nöyränä olla siveiden kanssa, kuin jakaa suurta saalista ylpeiden kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Joka jonkun asian viisaasti alkaa, hän löytää onnen; ja se on autuas, joka luottaa Herraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Toimellinen mies ylistetään viisautensa tähden; ja suloinen puhe lisää oppia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Viisaus on elämän lähde hänelle, joka sen saanut on, vaan tyhmäin oppi on hulluus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Viisas sydän puhuu toimellisesti, ja hänen huulensa opettavat hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Suloiset sanat ovat mesileipää; ne lohduttavat sielua, ja virvoittavat luut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Monella on tie mielestänsä oikia, vaan se johdattaa viimein kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Moni tulee suureen vahinkoon oman suunsa kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Jumalatoin ihminen kaivaa onnettomuutta, ja hänen suussansa palaa niinkuin tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Väärä ihminen saattaa riidan, ja panettelia tekee ruhtinaat eripuraisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Viekas ihminen houkuttelee lähimmäistänsä, ja johdattaa hänen pahalle tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Joka silmää iskee, ei se hyvää ajattele, ja joka huuliansa pureskelee, se pahaa matkaan saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Harmaat hiukset ovat kunnian kruunu, joka löydetään vanhurskauden tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Kärsivällinen on parempi kuin väkevä; ja joka hillitsee mielensä, on parempi, kuin se joka kaupungin voittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Arpa heitetään syliin, vaan Herralta tulee kaikki sen meno.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Kuiva pala, siinä jossa rauha on, on parempi kuin huone teurasta täynnä riidassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Toimellinen palvelia hallitsee häpiällisiä lapsia, ja hän jakaa perintöä veljein välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Niinkuin tuli koettelee hopian ja ahjo kullan, niin Herra tutkistelee sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Paha ottaa pahoista suista vaarin, ja petollinen kuuntelee mielellänsä vahingollista kieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Joka köyhää syljeskelee, se häpäisee Luojaansa; ja joka iloitsee toisen vahingosta, ei pääse rankaisematta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'vanhain kruunu ovat lasten lapset, ja lasten kunnia ovat heidän isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Ei sovi tyhmäin puhua korkeista asioista, paljoa vähemmin päämiehen valhetella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Jolla vara on lahja antaa, se on niinkuin kallis kivi: kuhunka hän itsensä kääntää, niin hän viisaana pidetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Joka syntiä peittää, se saattaa itsellensä ystävyyden; vaan joka asian ilmoittaa, se saattaa ruhtinaat eripuraisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Sanat vaikuttavat enemmän toimellisen tykönä, kuin sata haavaa tyhmän tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Niskuri tosin etsii vahinkoa, vaan julma enkeli lähetetään häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Parempi on kohdata karhua, jolta pojat ovat otetut pois, kuin hullua hulluudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Joka kostaa hyvän pahalla, ei hänen huoneestansa pidä pahuus luopuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Riidan alku on niinkuin vewsi, joka itsensä leikkaa ulos: lakkaa riidasta ennenkuin sinä siihen sekaannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Joka jumalattoman hurskaaksi sanoo, ja joka vanhurskaan soimaa jumalattomaksi, ne molemmat ovat Herralle kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Mitä tyhmä tekee kädessänsä rahalla, ettei hänellä ole sydäntä ostaa viisautta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Ystävä rakastaa ainian, ja veli tulee julki hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Se on tyhmä ihminen, joka kätensä taritsee, ja takaa lähimmäisensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Joka toraa rakastaa, se rakastaa syntiä; ja joka ovensa korottaa, se etsii onnettomuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Häijy sydän ei löydä mitään hyvää; ja jolla paha kieli on, se lankee onnettomuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Joka tyhmän synnyttää, hänellä on murhe, ja tyhmän isällä ei ole iloa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Iloinen sydän tekee elämän suloiseksi, vaan surullinen sydän kaivaa luut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Jumalatoin ottaa mielellänsä salaisesti lahjoja, mutkataksensa lain teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Toimellinen mies laittaa itsensä viisaasti, vaan tyhmä heittelee silmiänsä sinne ja tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Hullu popika on isänsä suru, ja äidillensä murhe, joka hänen synnyttänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Ei ole se hyvä, että vanhurskalle tehdään väärin, taikka että sitä ruhtinasta lyödään, joka oikein tuomitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Toimellinen mies taitaa puheensa tallella pitää, ja taitava mies on kallis sielu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Jos tyhmä vaiti olis, niin hän viisaaksi luettaisiin, ja toimelliseksi, jos hän suunsa pitäis kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Eripurainen etsii mitä hänelle kelpaa, ja sekoittaa itsensä kaikkiin asioihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Tyhmällä ei ole himo ymmärrykseen, vaan niitä ilmoittamaan, mitkä ovat hänen sydämessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Jumalattoman tullessa tulee ylönkatse, pilkka ja häpiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Sanat ihmisen suussa ovat niinkuin syvät vedet, ja viisauden lähde on täynnä virtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ei ole hyvä katsoa jumalattomain muotoa, ja sortaa vanhurskasta tuomiossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Tyhmän huulet saattavat toran, ja hänen suunsa noudattaa haavoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Tyhmän suu häpäisee itsensä, ja hänen huulensa ovat paula omalle omalle sielulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Panetteian sanat ovat haavat, ja käyvät läpi sydämen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Joka laiska on työssänsä, hän on sen veli, joka vahinkoa tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Herran nimi on vahva linna: vanhurskas juoksee sinne, ja tulee varjelluksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Rikkaan tavara on hänelle vahva kaupunki, ja niinkuin korkea muuri hänen mielestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Kuin joku lankee, niin hänen sydämensä ensisti tulee ylpiäksi, ja ennenkuin joku kunniaan tulee, pitää hänen nöyrän oleman..');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Joka vastaa ennekuin hän kuulee, se on hänelle hulluudeksi ja häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Ihmisen henki pitää ylös hänen heikkoutensa; vaan murheellista henkeä kuka voi kärsiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Ymmärtäväinen sydän saa viisauden, ja viisasten korva etsii taitoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Ihmisen lahja tekee hänelle avaran sian, ja saattaa suurten herrain eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Jokaisella on ensisti omassa asiassansa oikeus; vaan kuin hänen lähimmäisensä tulee, niin se löydetäään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Arpa asettaa riidan, ja eroitaa voimallisten vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Vihoitettu veli pitää puoltansa lujemmin kuin vahva kaupunki; ja riita pitää kovemmin puolensa kuin telki linnan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Sen jälkeen kullekin maksetaan, kuin hänen suunsa on puhunut; ja hän ravitaan huultensa hedelmästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Kuolema ja elämä on kielen voimassa: joka häntä rakastaa, se saa syösä hänen hedelmästänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Joka aviovaimon osaa, hän löytäää hyvän kappaleen, ja saa mielisuosionsa Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Köyhä mies puhuu nöyrästi, vaan rikas vastaa ylpiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Ihminen, jolla on ystävä, pitää oleman ystävällinen; sillä ystävä pitää lujemmin hänen kanssansa kuin veli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Köyhä joka siveydessä vaeltaa, on parempi kuin väärä huulissansa, joka kuitenkin tyhmä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Joka ei toimella laita, ei hänelle hyvin käy; ja joka on nopsa jaloista, se loukkaa itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Ihmisen tyhmyys eksyttää hänen tiensä, niin että hänen sydämensä vihastuu Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Tavara tekee monta ystävää, vaan köyhä hyljätään ystäviltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Ei väärä todistaja pidä pääsemän rankaisematta; joka rohkiasti valehtelee, ei hänen pidä selkeemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Moni rukoilee päämiestä, ja jokainen on hänen ystävänsä, joka lahjoja jakaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Köyhää vihaavat kaikki hänen veljensä, ja hänen ystävänsä vetäytyvät taamma hänestä; ja joka sanoihin luottaa, ei hän saa mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Joka viisas on, hän rakastaa henkeänsä, ja joka toimellinen on, se löytää hyvän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Väärä todistaja ei pidä pääsemän rankaisematta; ja joka rohkiasti valehtelee, se kadotetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Ei hullulle sovi hyvät päivät, paljoa vähemmin palvelian päämiehiä hallita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Joka on kärsivällinen, se on toimellinen ihminen; ja se on hänelle kunniaksi, että hän viat välttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Kuninkaan viha on niinkuin nuoren jalopeuran kiljuminen; mutta hänen ystävyytensä on niinkuin kaste ruoholle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Hullu poika on isänsä murhe, ja riitainen vaimo on niinkuin alinomainen pisaroitseminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Huoneet ja tavarat peritään vanhemmilta, vaan toimellinen emäntä tulee Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Laiskuus tuo unen, ja joutilas sielu kärsii nälkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Joka käskyt pitää, hän on vapahtanut henkensä; vaan joka tiensä hylkää, hänen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Jöka köyhää armahtaa, hän lainaa Herralle, joka hänen hyvän työnsä hänelle jälleen maksava on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Kurita lastas, koska vielä toivo on; mutta älä pyydä häntä tappaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Sillä suuri julmuus saattaa vahingon: sentähden laske vallallensa, ja kurita häntä toistamiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Kuule neuvoa ja ota kuritus vastaan, tullakses vihdoinkin viisaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Monet aivoitukset oavt miehen sydämessä; mutta Herran neuvo on pysyväinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Ihmiselle kelpaa hänen laupeutensa, ja köyhä mies on parempi kuin valehtelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Herran pelko saattaa elämän, ja se pysyy ravittuna, ettei mikään paha häntä lähesty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Laiska kätkee kätensä poveensa, ja ei vie sitä jälleen suuhunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Jos pilkkaajaa lyödään, niin taitamatoin tulee viisaaksi; ja jos toimellista lyödään, niin hän tulee toimelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Joka vaivaa isäänsä, ja ajaa ulos äitinsä, hän on häpeemätöin ja kirottu lapsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Lakkaa poikani, kuuntelemasta sitä neuvoa, joka sinua viettelee pois toimellisesta opista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Väärä todistus häpäisee tuomion, ja jumalattomain suu nielee vääryyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Pilkkaajille on rangaistus valmistettu, ja haavat hulluin selkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Viina tekee pilkkaajaksi, ja väkevät juotavat tekevät tyhmäksi: joka niitä halajaa, ei hän ikinä viisaaksi tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Kuninkaan peljättämys on niinkuin nuoren jalopeuran kiljuminen: joka hänen vihoittaa, hän tekee omaa henkeänsä vastoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Miehen kunnia on olla ilman riitaa; vaan jotka mielellänsä riitelevät, ovat kaikki tyhmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Kylmän tähden ei tahdo laiska kyntää; sentähden hän elonaikana kerjää, ja ei saa mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Neuvo on miehen sydämessä niinkuin syvä vesi; mutta toimellinen ammuntaa sen ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Monta ihmistä kerskataan hyväksi; vaan kuka löytää jonkun, joka todella hyvä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Vanhurskas siveydessä vaeltaa; hänen lastensa käy hyvin hänen perässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Kuningas, joka istuu istuimella tuomitsemaan, hajoittaa kaikki, jotka pahat ovat, silmillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kuka sanoo: minä olen puhdas sydämessäni, ja vapaa synnistäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Monenlainen vaaka ja mitta ovat molemmat kauhistus herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Nuorukainen tunnetaan menostansa, jos hän siviäksi ja toimelliseksi tuleva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Kuulevaisen korvan ja näkeväisen silmän on Herra molemmat tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Älä rakasta unta, ettes köyhtyisi: avaa silmäs, niin sinä saat kyllän leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Paha, paha, sanoo ostaja; mutta mentyänsä pois hän kerskaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Kultaa ja kalliita kiviä löydetään kyllä, vaan toimellinen suu on kallis kappale.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Ota hänen vaattensa joka muukaisen takaa: ja ota häneltä pantti tuntemattoman edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Varastettu leipä maistuu miehelle hyvin; vaan sitte pitää hänen suunsa oleman täynnä teräviä kiviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Aivoitukset menestyvät, kuin ne neuvotella toimitetaan, ja sodat myös pitää toimella pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Älä sekoita sinuas sen kanssa, joka salaisuuden ilmoittaa, ja joka panettelee, ja jolla petollinen suu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Joka isäänsä ja äitiänsä kiroilee, hänen kynttilänsä pitää sammuman synkiässä pimeydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Perintö, johon varhain kiiruhdetaan, on viimeiseltä ilman siunausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Älä sano: minä kostan pahan; odota Herraa, hän auttaa sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Monenlaiset puntarit ovat Herralle kauhistus, ja väärä vaaka ei ole hyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Jokaisen retket tulevat Herralta: kuka ihminen taitaa ymmärtää tiensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Se on ihmiselle paula, kuin hän pilkkaa pyhää, ja etsii sitte lupauksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Viisas kuningas hajoittaa jumalattomat, ja antaa ratasten käydä heidän päällitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Herran kynttilä on ihmisen henki: hän käy läpi koko sydämen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Laupius ja totuus varjelee kuninkaan, ja hän vahvistaa istuimensa laupiudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Nuorten miesten väkevyys on heidän kunniansa, ja harmaat karvat on vanhain kaunistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Haavoilla pitää pahuus ajettaman pois, ja koko sydämen kivulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Kuninkaan sydän on Herran kädessä, niinkuin vesiojat, ja hän taittaa sen kuhunka tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Jokainen luulee tiensä oikiaksi, vaan Herra koettelee sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Hyvin ja oikein tehdä, on Herralle otollisempi kuin uhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Ylpiät silmät ja paisunut sydän, ja jumalattomain kynttilä on synti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Ahkeran miehen aivoitukset tuovat yltäkylläisyyden; vaan joka pikainen on, se tulee köyhäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Joka tavaran kokoo valheella, se on kulkeva turhuus, niiden seassa, jotka kuolemaa etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Jumalattomain raatelemus pitää heitä peljättämän; sillä ei he tahtoneet tehdä, mitä oikia on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Jumalattoman ihmisen tie on outo; mutta puhtaan työ on oikia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Parempi on asua katon kulmalla, kuin riitaisen vaimon kanssa yhdessä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Jumalattoman sielu toivottaa pahaa, ja ei suo lähimmäisellensä mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Kuin pilkkaaja rangaistaan, niin tyhmät viisaaksi tulevat, ja kuin viisas tulee opetetuksi, niin hän ottaa opin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'vanhurskas pitää itsensä viisaasti jumalattoman huonetta vastaan; vaan jumalattomat kietovat itsensä onnettomuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Joka tukitsee korvansa köyhän huudolta, hänen pitää myös huutaman, ja ei kuultaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Salainen lahja asettaa vihan, ja helmaan anto lepyttä suurimman kiukun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Se on vanhurskaille ilo, tehdä mikä oikia on, vaan pahantekiöillä on pelko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Ihminen joka poikkee viisauden tieltä, pitää oleman kuolleiden joukossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Joka hekumaa rakastaa, se tulee köyhäksi; ja joka viinaa ja öljyä rakastaa, ei hän tule rikkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Jumalatoin pitää annettaman ulos vanhurskaan siaan, ja ylönkatsoja siveiden edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Parempi on asua autiossa maassa kuin riitaisen ja vihaisen vaimon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Viisaan huoneessa on suloinen tavara ja öljy, vaan tyhmä ihminen sen tuhlaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Joka vanhurskautta ja hyvyyttä noudattaa, hän löytää elämän, vanhurskauden ja kunnian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Viisas mies voittaa väkeväin kaupungin, ja kukistaa heidän uskalluksensa vahvuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Joka suunsa ja kielensä hillitsee, hän varjelee sielunsa ahdistuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Joka ynseä ja ylpiä on, hän kutsutaan pilkkaajaksi, joka vihassa ynseytensä näyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Laiskan himo tappaa hänen, ettei hänen kätensä tahtoneet mitään tehdä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Hän himoitsee suuresti kaiken päivän; muuta vanhurskas antaa, ja ei kiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Jumalattomain uhri on kauhistus, semminkin kuin se synnissä uhrataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Väärän todistajan pitää hukkuman; vaan joka tottelee, hän saa aina puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Jumalatoin juoksee päätähavin lävitse: mutta hurskas ojentaa tiensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Ei yksikään viisaus, eli ymmärrys, eikä neuvo, auta herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Hevoset valmistetaan sodan päiväksi; mutta voitto tulee herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Hyvä sanoma on kalliimpi kuin suuri rikkaus, ja suosio on parempi kuin hopia ja kulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Rikas ja köyhä tulevat toinen toistansa vastaan: ja Herra on ne kaikki tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Viisas näkee pahan, ja karttaa; taitamattomat juoksevat lävitse, ja saavat vahingon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Nöyryyden ja Herran pelvon palkka on rikkaus, kunnia ja elämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Orjantappurat ja paulat ovat väärän tiellä; vaan joka siitä taamma vetäytyy, hän varjelee henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Niinkuin sinä lapsen totutat nuoruudessa, niin ei hän siitä luovu, kuin hän vanhenee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Rikas vallitsee köyhiä, ja joka lainaksi ottaa, hän on lainaajan orja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Joka vääryyttä kylvää, se niittäää vaivan, ja hänen pahuutensa hukkuu vitsalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Laupiaat silmät siunataan, sillä hän antaa leivästä köyhälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Aja pilkkaaja pois,niin riita asettuu, ja tora ja häväistys lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Joka sydämen puhtautta rakastaa, sen huulet ovat otolliset, ja kuningas on hänen ystävänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Herran silmät varjelevat hyvän neuvon, ja kukistavat ylönkatsojan sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Laiska sanoo: jalopeura on ulkona, ja minä tapetaan kadulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Porttoin suu on syvä kuoppa: joka ei Herran suosiossa ole, hän lankee siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Hulluus riippuu nuorukaisen sydämessä, vaan kurituksen vitsa ajaa sen kauvas hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Joka köyhälle tekee vääryyttä enentääksensä tavaraansa, hänen pitää itse rikkaalle antaman, ja tosin köyhäksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Kallista korvas ja kuule viisasten sanat, ja pane minun oppini sydämees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Sillä se on sinulle suloinen, jos sinä pidät sen mielessäs, ja ne sovitetaan yhteen sinun huulilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Että sinun toivos olis Herrassa, olen minä sinua tänäpänä neuvonut; niin ota myös sinä näistä vaari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Enkö minä ole suurista asioista kirjoittanut sinun etees, neuvoin ja opettain?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Osoittaakseni sinulle vahvan totuuden perustuksen, vastatakses niitä oikein, jotka sinun lähettävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Älä ryöstä köyhää, vaikka hän köyhä on, ja älä solvaise vaivaista portissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Sillä Herra ajaa heidän asiansa, ja sortaa heidän soortajansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Älä antaudu vihaisen miehen seuraan, ja älä ole julman tykönä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Ettes oppisi hänen teitänsä, ja saisi sielulles paulaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Älä ole niiden tykönä, jotka kättä lyövät ja velkaa takaavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Sillä jos sinulla ei ole varaa maksaa, niin vuotees otetaan altas pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Älä siirrä takaperin entisiä rajoja, jotka esi-isäs tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Jos sinä näet nopsan miehen asiassansa, sen pitää seisoman kuninkaan edessä: ei hänen pidä seisoman halpain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Koskas istus ja syöt jonkun herran kanssa, niin ota visu vaari, kuka edessäs on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Ja pane veitsi kaulaas, jos sinä tahdot henkes pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Älä himoitse hänen herkustansa; sillä se on petollinen leipä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Älä vaivaa sinuas tullakses rikkaksi, ja lakkaa sinun viisaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Älä lennätä silmiäs sen jälkeen, jota et sinä taida saada; sillä se tekee itsellensä siivet niinkuin kotka, ja lentää taivasta päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Älä syö leipää kateen kanssa, ja älä himoitse hänen hänen herkkuansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Sillä niinkuin hän itse sydämessänsä ajattelee, niin se on; hän sanoo sinulle: syö ja juo, ja ei kuitenkaan ole hänen mielensä sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Sinun palas, jotka syönyt olet, pitää sinun oksentaman, ja sinun ystävälliset puhees pitää hukkaan tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Älä puhu hullun korvissa; sillä hän katsoo sinun toimellisen puheen ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Älä siirrä takaperin entisiä rajoja,ja älä mene orpoin pellolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Sillä heidän lunastajansa on voimallinen: hän toimittaa heidän asiansa sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Anna sydämes kuritukseen, ja korvas toimelliseen puheesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Älä lakkaa lasta kurittamasta; sillä jos sinä häntä vitsalla lyöt, niin ei hän kuole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Sinä lyöt häntä vitsalla, vaan sinä vapahdat hänen sielunsa helvetistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Poikani, jos sinä viisas olet, niin myös sydämeni iloitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'Ja minun munaskuuni ovat riemuiset, koska sinun huules puhuvat, mikä oikia on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Älköön sinun sydämes kiivoitelko syntisiä, vaan olkoon Herran pelvossa joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Sillä se on sinulle viimein hyväksi, ja ei sinun odottamises puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Kuule, poikani, ja ole viisas, ja johdata sydämes tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Älä ole juomarien ja syömärien seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Sillä juomarit ja syömärit köyhtyvät, ja unikeko pitää ryysyissä käymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Kuule isääs, joka sinun siittänyt on, ja älä katso äitiäs ylön, kuin hän vanhaksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Osta totuutta, ja älä sitä myy, niin myös viisautta, oppia ja ymmärrystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Vanhurskaan isä suuresti riemuitsee; ja joka viisaan siittänyt on, hän iloitsee hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Anna isäs ja äitis iloita; ja riemuitkaan se, joka sinun synnyttänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Anna minulle, poikani, sydämes, ja sinun silmäs pitäköön minun tieni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Sillä portto on syvä kuoppa, ja vieras vaimo on ahdas kaivo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Ja hän väijyy niinkuin saalista, ja saattaa monta tottelemattomaksi ihmisten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Kussa on kipu? kussa murhe? kussa tora? kussa valitus? kenellä haavat ilman syytä? kenellä punaiset silmät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Siinä, kussa viinan tykönä viivytään, ja tullaan tyhjentämään, mitä sisälle pantu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Älä katsele viinaa, vaikka se punoittaa, ja on selkiänä lasissa, ja huokiasti menee alas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Vaan viimeiseltä puree se niinkuin käärme, ja pistää niinkuin kyykäärme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Niin katsovat sinun silmäs muita vaimoja, ja sinun sydämes puhuu toimettomia asioita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Ja sinä tulet niinkuin se, joka makaa keskellä merta, ja niinkuin se joka makaa ylhäällä haahden pielen päässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Sinä sanot; he löivät minua, vaan en minä kipua tuntenut; he sysivät minua, ja en minä tiennyt. Kuin minä herään, niin tahdon minä vielä niin tehdä, ja sitä enempi etsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Älä ole kiivas pahain ihmisten kanssa, ja älä himoitse olla heitä läsnä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Sillä heidän sydämensä pyytää vahingoittaa, ja heidän huulensa neuvovat pahuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Viisaudella raknnetaan huone, ja toimella se vahvistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Taidolla kammio täytetään kaikkinaisista kalliista ja jaloista tavaroista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Viisas mies on väkevä, ja toimellinen mies on voimallinen väestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Sillä neuvolla sodatkin pidetään: ja jossa monta neuvonantajaa on, siinä on voitto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Viisaus on hullulle ylen korkia, ei hän tohdi avata suutansa portissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Joka ajattelee pahaa tehdäksensä, se kutsutaan pahain ajatusten päämieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Tyhmäin ajatus on synti, ja pilkkaaja on kauhistus ihmisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Ei se ole väkevä, joka ei tuskassa vahva ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Auta niitä, joita tappaa tahdotaan, ja älä vedä sinuas pois pois niiden tyköä, jotka kuoletetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Jos sinä sanot: katso, emme ymmärrä sitä! luuletkos, ettei se, joka sydämet tutkii, sitä ymmärrä? ja se, joka sielustas ottaa vaarin, tunne sitä ja kosta ihmiselle tekonsa jälkeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Syö, poikani, hunajaa; sillä se on hyvä, ja mesileupä on makia suus laelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Niin on myös viisauden oppi sielulles: koskas sen löydät, niin sinun viimein käy hyvin, ja ei sinun toivos ole turha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Älä vartioitse vanhurskaan huonetta, sinä jumalatoin, älä hukkaa hänen lepoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Sillä vanhurskas taitaa langeta seitsemän kertaa, ja nousee jälleen; mutta jumalattomat kaatuvat onnettomuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Älä iloitse vihamiehes vahingosta, ja älköön sinun sydämes riemuitko hänen onnettomuudestansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Ettei Herra näkisi sitä, ja se olis hänelle kelvotoin, ja hän kääntäis vihansa pois hänen päältänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Älä vihastu pahain päälle, älä myös ole kiivas jumalattomain tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Sillä ei häijyllä ole mitään toivomista, ja jumalattomain kynttilä pitää sammuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Poikani, pelkää Herraa ja kuningasta, ja älä sekoita sinuas kapinan nostajain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Sillä heidän kadotuksensa nousee äkisti: ja kuka tietää, koska kummankin onnetomuus tulee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Nämä ovat myös viisasten: ei ole hyvä katsoa muotoa tuomiossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Joka jumalattomalle sanoo: sinä olet hurskas! häntä kiroovat ihmiset, ja kansa vihaa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Mutta jotka rankaisevat, he ovat otolliset, ja runsas siunaus tulee heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Toimellinen vastaus on niinkuin suloinen suun antamus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Toimita työs ulkona, ja valmista peltos, ja rakenna sitte huonees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Älä todista lähimmäistäs vastaan ilman syytä, ja älä petä suullas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Älä sano: niinkuin hän teki minulle, niin minä teen hänelle: minä kostan jokaiselle hänen tekonsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Minä kävin laiskan pellon ohitse, ja tyhmän viinamäen sivuitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Ja katso, siinä olivat paljaat ohdakkeet kasvaneet, ja se oli nukulaista täynnä, ja aidat olivat kaatuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Kuin minä sen bäin, panin minä sen sydämeeni, katselin ja opin siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Sinä tahdot vielä vähä maata ja unelias olla, ja enempi käsiäs yhteen panna lepäämään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'Mutta köyhyytes pitää sinulle tuleman niinkuin matkamies, ja vaivaisuus niinkuin varustettu mies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Nämät ovat myös Salomon sananlaskut, jotka Hiskian ja Juudan kuninkaan miehet ovat tähän panneet tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Se on Jumalan kunnia, salata asiaa; mutta kuninkaan kunnia, tutkia asiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Taivas on korkia ja maa syvä, ja kuninkaan sydän on tutkimatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Raiska otetaan hopiasta pois, niin siitä tulee puhdas astia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Jos jumalatoin otetaan pois kuninkaan kasvoin edestä, niin hänen istuimensa vanhurskaudella vahvistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Älä koreile kuninkaan nähden, ja älä astu suurten sialle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Sillä se on sinulle parempi, koska sinulle sanotaan: astu tänne ylemmä! kuin ettäs ruhtinaan edessä alennettaisiin, jota sinun silmäs näkisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Älä ole pikainen riitelemään, ettes tiedä mitäs teet, koska lähimmäiseltäs häväisty olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Toimita asias lähimmmäises kanssa, älä ilmoita toisen salaisuutta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Ettei se, joka sen kuulee, sinua häpäisisi, ja ettei sinun paha sanomas lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Sana, aikanansa puhuttu, on niinkuin kultainen omena hopiamaljassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Koska viisas rankaisee sitä, jaka häntä kuulee, se on niinkuin korvarengas, ja niinkuin kaunistus parhaasta kullasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Niinkuin lumen kylmä elonaikana, niin on uskollinen sanansaattaja sille, joka hänen lähettänyt on, ja virvoittaa herransa sielun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Joka paljon puhuu ja vähän pitää, hän on niinkuin tuuli ja pilvi ilman sadetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Kärsivällisyydellä päämies lepytetään, ja siviä kieli pehmittää kovuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Jos sinä löydät hunajaa, niin syö tarpeekses, ettes ylönpalttisesti tulisi ravituksi, ja antaisi sitä ylen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Anna jalkas harvoin tulla lähimmäises huoneeseen, ettei hän suuttuis sinuun, ja vihaisi sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Joka väärää todistusta puhuu lähimmäistänsä vastaan, hän on vasara, miekka ja terävä nuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Pilkkaajan toivo hädän aikana on niinkuin murrettu hammas, ja vilpisteleväinen jalka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Joka murheellisen sydämen edessä virsiä veisaa, hän on niinkuin se, joka vaatten tempaa pois talvella, ja etikka pleikun päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Jos sinun vihamiehes isoo, niin ravitse häntä leivällä: jos hän janoo, niin juota häntä vedellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Sillä sinä kokoot hiilet hänen päänsä päälle, ja Herra kostaa sen sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Pohjatuuli tuottaa sateen, ja salainen kieli saattaa kasvot vihaisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Parempi on istus katon kulmalla, kuin riitaisen vaimon kanssa yhdessä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Hyvä sanoma kaukaiselta maalta on kylmän veden kaltainen janoovaiselle sielulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Vanhurskas, joka jumalattoman eteen lankee, on niinkuin sekoitettu kaivo ja turmeltu lähde.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Joka paljon hunajaa syö, ei se ole hyvä, ja joka työtläitä asioita tutkii, se tulee hänelle työlääksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Joka ei taida hillitä henkeänsä, hän on niinkuin hävitetty kaupunki ilman muuria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Niinkuin lumi suvella ja sede elonaikana, niin ei sovi tyhmälle kunnia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Niinkuin lintu menee pois, ja pääskynen lentää, niin ei sovi salvaa kirous ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Hevoselle ruoska ja aasille ohjat, ja hullulle vitsa selkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Älä vastaa tyhmää hänen tyhmyytensä jälkeen, ettes myös sinä hänen kaltaiseksensa tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Vastaa tyhmää hänen tyhmyytensä jälkeen, ettei hän näkyisi viisaaksi silmissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Joka tyhmäin sanansaattajain kautta asian toimittaa, hän on niinkuin rampa jaloista, ja saa vahingon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Niinkuin nilkku voi hypätä, niin tyhmä taitaa puhua viisaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Joka tyhmälle taritsee kunniaa, on niinkuin joku heittäisi kalliin kiven kiviroukkioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Sananlasku on tyhmäin suussa niinkuin orjantappura, joka juopuneen käsiin pistelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Taitava ihminen tekee kappaleen oikein; vaan joka taitamattoman palkkaa, hän sen turmelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Niinkuin koira syö oksennuksensa, niin on hullu joka hulluutensa kertoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Koskas näet jonkun, joka luulee itsensä viisaaksi, enempi on silloin toivoa tyhmästä kuin hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Laiska sanoo: nuori jalopeura on tiellä, ja jalopeura kujalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Laiska kääntelee itsiänsä vuoteella niinkuin ovi saranassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Laiska panee kätensä poveensa: ja se tulee hänelle työlääksi saattaa suuhunsa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Laiska luulee itsensä viisaammaksi kuin seitsemän, jotka hyviä tapoja opettavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Joka käy ohitse ja sekoittaa itsensä muiden riitoihin, hän on senkaltainen, joka koiraa korvista vetää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Niinkuin se, joka salaa ampuu, tarkoittaa joutsella ja tappaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Niin on petollinen ihminen hänen lähimmäisillensä, ja sanoo: leikillä minä sen tein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Kuin halot loppuvat, niin tuli sammuu, ja kuin kielikellot pannaan pois, niin riidat lakkaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Niinkuin hiilet tuleen, ja puut liekkiin, niin riitainen ihminen saattaa metelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Panettelian sanat ovat niinkuin haavat, ja käyvät läpi sydämen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Viekas kieli ja paha sydän on niinkuin saviastia hopian savulla juotettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Vihamien teeskelee itsensä toisin puheellansa; mutta petos on hänen sydämessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Kuin hän liehakoitsee makeilla puheillansa, niin älä usko häntä; sillä seitsemän kauhistusta on hänen sydämessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Joka pitää salavihaa, tehdäksensä vahinkoa, hänen pahuutensa tulee ilmi kokouksissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Joka kuopan kaivaa, hän lankee siihen, ja joka kiven vierittää, se kierittää sen itse päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Petollinen kieli vihaa rangaistusta, ja suu, joka myötäkielin puhuu, saattaa kadotukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Älä kehu huomisesta päivästä; sillä et sinä tiedä, mitä tänäpänä tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Anna toisen sinuas kiittää, ja ei sinun oman suus, muukalaisen, ja ei omin huultes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Kivi on raskas ja santa painaa; vaan tyhmän viha on raskaampi kuin ne molemmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Viha on julma kappale ja karvas mieli on myrsky; ja kuka taitaa olla kateutta vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Julkinen kuritus on parempi kuin salainen rakkaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Hyvänsuovan haavat ovat paremmet kuin petolliset Vainoojain suunantamiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Ravittu sielu polkee hunajaa; vaan isoovaiselle sielulle ovat kaikki karvaatkin makiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Niinkuin lintu, joka pesästänsä kulkee, niin on se mies, joka siastansa siirtää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Voiteesta ja suitsutuksesta sydän iloitsee, ja ystävän hyvä neuvo on sielulle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Älä hylkää ystävääs, ja isäs ystäviä, ja älä mene veljes huoneesen, kuin sinun väärin käy; sillä parempi on kylänmies, joka läsnä on, kuin veli, joka taampana on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Ole viisas, poikani, ja iloita sydämeni, että minä taitaisin vastata sitä, joka minua pilkkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Viisas näkee vaaran, ja lymyttää itsensä; vaan tyhmät menevät siihen, ja saavat vahingon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Ota hänen vaattensa, joka toisen takaa, ja ota häneltä pantti muukalaisen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Joka lähimmäistänsä siunaa korkialla äänellä, ja nousee varhain, se luetaan hänelle kiroukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Riitainen vaimo, ja alinomainen tiukkuminen suuresta sateesta, nämät oikein yhteen verrataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Joka häntä tahtoo kätkeä, hän käsittelee tuulta, ja pivo öljyä kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Veitsi hioo veitsen, ja mies teroittaa ystävänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Joka fikunapuunsa varjelee, se syö siitä hedelmän, ja joka herraansa vartioitsee, se kunnioitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Niinkuin varjo on vedessä ihmisen kasvon suhteen, niin on ihmisen sydän toisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Helvetti ja kadotus ei tule ikänä täyteen, ja ihmisen silmät ovat tyytymättömät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Mies tulee kiusatuksi kiittäjän suun kautta, niinkuin hopia ahjossa ja kulta pätsissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Jos sinä huhmaressa survoisit tyhmän niinkuin ryynit, niin ei kuitenkaan hänen hulluutensa hänestä erkane.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Ota ahkera vaari lampaistas, ja pidä murhe laumastas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Sillä ei tavara ole ijankaikkisesti, eikä kruunu suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Ruoho käy ylös ja kukkaset puhkeevat, ja heinät vuorilla kootaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Lampaat vaatettavat sinua, ja kauriit antavat pellon vuoron.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Sinulla on vuohten rieskaa kyllä sekä omaksi settä huonees ravinnoksi, ja piikais elatukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Jumalatoin pakenee, ja ei kenkään aja häntä takaa; vaan jumalinen on rohkia niinkuin nuori jalopeura.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Maakunnan synnin tähden tulee valtakuntaan monta päämiestä; vaan toimellisten ja ymmärtäväisten ihmisten tähden pysyy se kauvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Nälkäinen, joka köyhiä vaivaa, on niinkuin sadekuuro, joka hedelmän turmelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Jotka lain hylkäävät, ne ylistävät jumalattomia; vaan jotka lain kätkevät, ovat heille vihaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Ei pahat ihmiset oikeudesta lukua pidä; vaan jotka Herraa etsivät, he ottavat kaikista vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Parempi on köyhä joka vakuudessansa vaeltaa, kuin rikas, joka väärillä teillä käyskentelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Joka lain kätkee, se on toimellinen lapsi; mutta joka tuhlaajaa ruokkii, se häpäisee isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Joka tavaransa enentää korolla ja voitolla, se kokoo köyhäin tarpeeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Joka korvansa kääntää pois lain kuulosta, hänen rukouksensakin on kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Joka jumaliset saattaa väärälle tielle, hän lankee omaan kuoppaansa; mutta hurskaat perivät hyvyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Rikas luulee itsensä viisaaksi, vaan toimellinen köyhä ymmärtää hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Kuin vanhurskaat vallitsevat, niin käy sangen hyvin; vaan koska jumalattomat hallitsevat, niin muuttet ovat kansan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Joka pahan tekonsa kieltää, ei hän menesty; vaan joka sen tunnustaa ja hylkää, hänelle tapahtuu laupius.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Autuas on se ihminen, joka aina pelkää; vaan joka sydämensä paaduttaa, se lankee onnettomuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Jumalatoin päämies, joka köyhää kansaa hallitsee, on kiljuva jalopeura ja ahne karhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Kuin hallitsia on ilman toimeta, niin paljon vääryyttä tapahtuu; vaan joka vihaa ahneutta, hän saa kauvan elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ihminen, joka jonkun sielun veressä vääryyttä tekee, ei pääse, vaikka hän hamaan hautaan pakenis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Joka vakuudessa vaeltaa, se on tallessa; mutta joka käy pahaa tietä, hänen täytyy joskus langeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Joka peltonsa viljelee, hän saa leipää yltäisesti; vaan joka pyytää joutilaana käydä, se ravitaan köyhyydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Uskollinen mies runsaasti siunataan; vaan joka pyrkii rikkauden perään, ei hän ole viaton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Ei ole se hyvä, että joku katsoo muotoa; sillä ihminen taitaa tehdä leivän kappaleen tähden väärin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Joka äkisti rikkautta pyytää, ja on kade, hänelle tulee köyhyys, ettei hän tiedäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Joka ihmistä rankaisee, hän löytää paremman ystävyyden kuin se, joka puhuu ymötämielin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Joka ottaa isältänsä ja äidiltänsä, ja sanoo; ei se ole synti, hän on hävittäjän kanssaveli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Ylpiä ihminen saattaa riidan; mutta joka luottaa Herraan, hän kostuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Joka omaan sydämeensä uskaltaa, hän on tyhmä; mutta joka viisaudessa vaeltaa, hän vapahdetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Joka vaivaiselle antaa, ei häneltä puutu; vaan joka silmänsä hänestä kääntää, se tulee pahasti kirotuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Kuin jumalattomat tulevat, niin kansa itsensä kätkee; mutta kuin ne hukkuvat, niin vanhurskaat enenevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Joka kuritukselle on uppiniskainen, hän äkisti kadotetaan ilman yhdetäkään avuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Kuin vanhurskaita monta on, niin kansa iloitsee; vaan kuin jumalatoin hallitsee, niin kansa huokaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Joka viisautta rakastaa, hän iloittaa isänsä; mutta joka huoria elättää, hän tuhlaa tavaraansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Kuningas rakentaa oikeudella valtakunnan; vaan lahjain ottaja sen turmelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Joka lähimmäisensä kanssa liehakoitsee, hän hajoittaa verkon jalkainsa eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Kuin paha syntiä tekee, niin hän hänensä paulaan sekoittaa; vaan vanhurskas riemuitsee, ja hänellä on ilo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Vanhurskas tuntee köyhän asian; vaan jumalatoin ei ymmärrä viisautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Pilkkaajat hajoittavat kaupungin; vaan viisaat asettavat vihan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Kuin viisas tulee tyhmän kanssa oikeutta käymään, joko hän on vihainen eli iloinen, niin ei ole hänellä yhtään lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Verikoirat vihaavat siviää; vaan vanhurskaat holhovat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Tyhmä vuodattaa kaiken henkensä; vaan viisas sen pidättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Päämies, joka valhetta rakastaa, hänen palveliansa ovat kaikki jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Köyhä ja rikas kohtasivat toinen toisensa: Herra valaisee heidän molempain silmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Kuningas, joka uskollisesti tuomitsee köyhiä, hänen istuimensa vahvistetaan ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Vitsa ja rangaistus antaa viisauden; vaan itsevaltainen lapsi häpäisee äitinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Jossa monta jumalatointa on, siinä on monta syntiä; vaan vanhurskaat näkevät heidän lankeemisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Kurita poikaas, niin hän sinua virvoitaa, ja saattaa sielus iloiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Kuin ennustukset loppuvat, niin kansa hajoitetaan; vaan autuas kätkee lain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Palvelia ei anna itsiänsä kurittaa sanoilla; sillä vaikka hän sen ymmärtää, niin ei hän vastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Jos sinä näet jonkun, joka on nopsa puhumaan: enempi on toivoa tyhmästä kuin hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Jos palvelia nuoruudesta herkullisesti pidetään, niin hän tahtoo sitte poikana olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Vihainen mies saattaa riidan, ja kiukkuinen tekee monta syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Ylpeys kukistaa ihmisen; vaan kunnia korottaa nöyrän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Joka varkaan kanssa on osallinen, hän vihaa sieluansa, niin myös se, joka kuulee kirouksen ja ei ilmoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Joka pelkää ihmistä, hän tulee lankeemukseen; mutta joka luottaa Herraan, hän tulee pidetyksi ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Moni etsii päämiehenkasvoja; mutta jokaisen tuomio tulee Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Jumalatoin ihminen on vanhurskaille kauhistus; ja joka oikialla tiellä on, hän on jumalattomalle kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Agurin Jakenin pojan pojan sanat ja opetus, jonka se mies pujui Itielille, Itielille ja Ukkalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Minä olen kaikkein hulluin, ja ihmisten ymmärrys ei ole minussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'En minä ole oppinut viisautta, ja en tiedä pyhäin taitoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kuka taivaaseen menee ylös ja tulee alas? kuka käsittää tuulen pivoonsa? kuka sitoo veden vaatteeseen? kuka 0n asttanut kaikki maan ääret? mikä on hänen nimensä? kuinka hänen poikansa kutsutaan? tiedätkös?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Kaikki Jumalan sanat ovat kirkastetut, ja ovat kilpi niille, jotka uskovat hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Älä lisää hänen sanoihinsa, ettei hän sinua rankaisisi, ja sinä löyttäisiin valehteliaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Kahta minä sinulta anon, ettes minulta niitä kieltäisi, ennenkuin minä kuolen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Väärä oppi ja valhe olkoon minusta kaukana: köyhyyttä ja rikkautta älä minulle anna; vaan anna minun saada määrätty osani ravinnosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Etten minä, jos minä ylen ravituksi tulisin, kieltäisi sinua ja sanoisi: kuka on Herra? eli, jos minä ylen köyhäksi tulisin, varastaisi, ja syntiä tekisi Jumalani nimeä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Älä kanna palvelian päälle hänen isäntänsä edessä, ettei hän sinua kiroilisi ja sinä niin nuhteeseen tulet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'On niitä, jotka kiroilevat isäänsä ja ei siunaa äitiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'On niitäkin, jotka luulevat itsensä puhtaaksi, ja ei ole kuitenkaan saastaisuudestansa pestyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Ovat myös, jotka silmänsä nostavat, ja silmälautansa korottavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Ja ovat, joilla on miekka hammasten siassa, ja veitset heidän syömähampainansa, ja syövät vaivaiset maan päältä, ja köyhät ihmisten seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Verenimijällä on kaksi tytärtä: tuo tänne, tuo tänne. Kolme on tyytymätöintä, ja tosin neljä ei sano kyllä olevan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Helvetti, vaimon suljettu kohtu, maa, joka ei vedellä täytetä: ja tuli ei sano: jo kyllä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Silmä joka häpäisee isäänsä, ja katsoo ylön totella äitiänsä, sen kaarneet ojan tykönä hakkaavat ulos, ja kotkan pojat syövät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Kolme minulle ovat ihmeelliset, ja neljää en minä tiedä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Kotkan tiet taivaan alla, käärmeen retket kalliolla, haahden jäljet meren keskellä, ja miehen jäljet piian tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Niin on myös porton polut: hän syö ja pyyhkii suunsa, ja sanoo: en minä mitään pahaa ole tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Kolmen kautta maakunta tulee levottomuuteen, ja tosin neljää hän ei voi kärsiä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Kuin palvelia rupee hallitsemaan, kuin hullu ylen ravituksi tulee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Kuin ilkiä naitetaan, ja kuin piika tulee emäntänsä perilliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Neljä on pientä maan päällä, ja ovat toimellisemmat viisaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Myyriäiset, heikko väki, jotka kuitenkin elatuksensa suvella toimittavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Kaninit, heikko väki, jotka kuitenkin pesänsä kalliolle tekevät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Heinäsirkoilla ei ole kuningasta, kuitenkin he lähtevät kaikki ylös joukossansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Hämähäkki kehrää käsillänsä, ja on kuninkaan linnoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Kolmella on jalo käyntö, ja tosin neljä astuu hyvin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Jalopeura, voimallinen petoin seassa, joka ei palaja kenenkään edestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Hurtta, jolla vahvat sivut ovat, ja kauris, ja kuningas, jota vastaan ei kenkään tohdi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Jos sinä olet tyhmästi tehnyt, ja korottanut sinuas, ja jos sinä olet jotakin pahaa ajatellut, niin laske käsi suus päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Joka rieskaa kirnuu, hän tekee voita: ja jokaa nenää pusertaa, hän vaatii ulos veren: ja joka vihaa kehoittaa, hän vaatii riitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Kuningas Lemuelin sanat: oppi, jonka hänen äitinsä hänelle opetti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Ah minun poikani, ah minun kohtuni poika, ah minun toivottu poikani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Älä anna vaimon saada tavaraas, ja älä käy niillä retkillä, joissa kuninkaat turmeltuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ei kuningasten, o Lemuel, ei sovi kuningasten viinaa juoda, eli ruhtinasten väkeviä juotavia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Ettei he joisi, ja oikeutta unohtaisi, ja vääntelisi köyhäin asiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Antakaat väkeviä juotavia niille, jotka hukkumallnsa ovat, ja viinaa murheellisille sieluille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Että he joisivat, ja unohtaisivat ahdistuksensa, ja ei enää johdattaisi mieleensä viheliäisyyttänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Avaa suus mykän edessä, ja auta hyljättyin asiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Avaa suus, ja tuomitse oikein, ja pelasta vaivainen ja köyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Joka toimellisen vaimon löytää, se on kalliimpi kuin kaikkein kallimmat päärlyt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Hänen miehensä sydän uskaltaa häneen: hänen elatuksensa ei puutu häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Hän tekee hänelle hyvää ja ei pahaa kaikkena elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Hän harjoittaa itsensä villoissa ja pellavissa, ja tekee mielellänsä työtä käsillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Hän on niinkuin kauppamiehen haaksi, joka elatuksensa tuo kaukaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Hän nousee yöllä, ja antaa perheellensä ruokaa, ja piioillensa heidän osansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Hän pyytää peltoa ja saa sen, ja istutaa viinapuita kättensä hedelmästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Hän vyöttää kupeensa väkevydellä, ja vahvistaa käsivartensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Hän näkee askareensa hyödylliseksi: hänen kynttiläänsä ei sammuteta yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Hän ojentaa kätensä rukkiin, ja tarttuu sormillansa kehrävarteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Hän kohottaa kätensä köyhille, ja ojentaa kätensä tarvitseville.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ei hän pelkää lunta huoneessansa; sillä kaikella hänen perheellänsä ovat kaksinkertaiset vaatteet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Hän tekee itsellensä makausvaatteita: valkia kallis liina ja purppura ovat hänen pukunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Hänen miehensä on tuttu porteissa, istuissansa maan vanhimpain tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Hän tekee kallista liinaa ja myy sitä, ja antaa vyön kauppaajalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Väkevyys ja kunnia on hänen pukunsa, ja hän nauraa seuraavaiselle ajalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Hän avaa suunsa viisaudessa, ja hänen kielensä on suloinen oppi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Hän katselee kurkistellen, kuinka hänen huoneessansa kaikki asiat ovat, ja ei syö laiskuudessa leipäänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Hänen poikansa tulevat ja ylistävät häntä autuaaksi: hänen miehensä kiittää häntä sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Moni tytär käyttää itsensä kauniisti; mutta sinä käyt ylitse heidän kaikkein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Otollinen olla on petollisuus, ihana olla on turha; vaan vaimo, joka Herraa pelkää, ylistetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Antakaat hänelle kättensä hedelmästä, ja hänen kättensä työt kiittäkään häntä porteissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Saarnaajan sanat, Daavidin pojan, joka oli kuninkaana Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Turhuuksien turhuus, sanoi saarnaaja, turhuuksien turhuus; kaikki on turhuutta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Mitä hyötyä on ihmiselle kaikesta vaivannäöstänsä, jolla hän vaivaa itseänsä auringon alla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Sukupolvi menee, ja sukupolvi tulee, mutta maa pysyy iäti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Ja aurinko nousee, ja aurinko laskee ja kiiruhtaa sille sijallensa, josta se jälleen nousee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Tuuli menee etelään ja kiertää pohjoiseen, kiertää yhä kiertämistään, ja samalle kierrollensa tuuli palajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Kaikki joet laskevat mereen, mutta meri ei siitänsä täyty; samaan paikkaan, johon joet ovat laskeneet, ne aina edelleen laskevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Kaikki tyynni itseänsä väsyttää, niin ettei kukaan sitä sanoa saata. Ei saa silmä kylläänsä näkemisestä eikä korva täyttänsä kuulemisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Mitä on ollut, sitä vastakin on; ja mitä on tapahtunut, sitä vastakin tapahtuu. Ei ole mitään uutta auringon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Jos jotakin on, josta sanotaan: \"Katso, tämä on uutta\", niin on sitä kuitenkin ollut jo ennen, ammoisina aikoina, jotka ovat olleet ennen meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Ei jää muistoa esi-isistä; eikä jälkeläisistäkään, jotka tulevat, jää muistoa niille, jotka heidän jälkeensä tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Minä, saarnaaja, olin Israelin kuningas Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Ja minä käänsin sydämeni viisaudella tutkimaan ja miettimään kaikkea, mitä auringon alla tapahtuu. Tämä on vaikea työ, jonka Jumala on antanut ihmislapsille, heidän sillä itseään rasittaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Minä katselin kaikkia tekoja, mitä tehdään auringon alla, ja katso, se on kaikki turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Väärä ei voi suoristua, eikä vajaata voi täydeksi laskea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Minä puhuin sydämessäni näin: Minä olen hankkinut suuren viisauden ja sitä yhä lisännyt, jopa yli kaikkien, jotka ovat ennen minua Jerusalemissa hallinneet, ja paljon on sydämeni nähnyt viisautta ja tietoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Ja minä käänsin sydämeni tutkimaan viisautta ja tietoa, mielettömyyttä ja tyhmyyttä, ja minä tulin tietämään, että sekin oli tuulen tavoittelemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Sillä missä on paljon viisautta, siinä on paljon surua; ja joka tietoa lisää, se tuskaa lisää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Minä sanoin sydämessäni: Tule, minä tahdon koetella sinua ilolla, nauti hyvää. Mutta katso, sekin oli turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Naurusta minä sanoin: \"Mieletöntä!\" ja ilosta: \"Mitä se toimittaa?\"');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Minä mietin mielessäni virkistää ruumistani viinillä - kuitenkin niin, että sydämeni harrastaisi viisautta - ja noudattaa tyhmyyttä, kunnes saisin nähdä, mikä olisi ihmislapsille hyvä, heidän tehdäksensä sitä taivaan alla lyhyinä elämänsä päivinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Minä tein suuria töitä: rakensin itselleni taloja, istutin itselleni viinitarhoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Minä laitoin itselleni puutarhoja ja puistoja ja istutin niihin kaikkinaisia hedelmäpuita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Minä tein itselleni vesilammikoita kastellakseni niistä metsiköitä, joissa puita kasvoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Minä ostin orjia ja orjattaria, ja kotona syntyneitäkin minulla oli; myös oli minulla karjaa, raavaita ja lampaita, paljon enemmän kuin kenelläkään niistä, jotka olivat olleet ennen minua Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Minä kokosin itselleni myöskin hopeata ja kultaa ja kuninkaitten ja maakuntien aarteita ja hankin itselleni laulajia ja laulajattaria ja ihmislasten iloja, vaimon, jopa vaimoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Minä tulin suureksi ja yhä suuremmaksi, yli kaikkien, jotka olivat olleet ennen minua Jerusalemissa. Sen ohessa pysyi minussa viisauteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Enkä minä pidättänyt silmiäni mistään, mitä ne pyysivät, enkä kieltänyt sydämeltäni mitään iloa, sillä minun sydämeni iloitsi kaikesta vaivannäöstäni, ja se oli minun osani kaikesta vaivannäöstäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Mutta kun minä käänsin huomioni kaikkiin töihin, joita minun käteni olivat tehneet, ja vaivannäköön, jolla olin vaivannut itseäni niitä tehdessäni, niin katso: se oli kaikki turhuutta ja tuulen tavoittelua; eikä ole hyötyä mistään auringon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Kun minä käännyin katsomaan viisautta ja mielettömyyttä ja tyhmyyttä - sillä mitä taitaa ihminen, joka tulee kuninkaan jälkeen, muuta kuin tehdä, mitä jo ennen on tehty? -');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'niin minä näin, että viisaus on hyödyllisempi tyhmyyttä, niinkuin valo on pimeyttä hyödyllisempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Viisaalla on silmät päässänsä, tyhmä taas vaeltaa pimeässä; mutta minä tulin tietämään myös sen, että toisen käy niinkuin toisenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Ja minä sanoin sydämessäni: Se, mikä kohtaa tyhmää, kohtaa minuakin; miksi olen sitten niin tuiki viisaaksi tullut? Ja minä sanoin sydämessäni: Tämäkin on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Sillä ei jää viisaasta, niinkuin ei tyhmästäkään, ikuista muistoa, kun kerran tulevina päivinä kaikki unhotetaan; ja eikö kuole viisas niinkuin tyhmäkin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Niin minä kyllästyin elämään, sillä minusta oli pahaa se, mikä tapahtuu auringon alla, koskapa kaikki on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Ja minä kyllästyin kaikkeen vaivannäkööni, jolla olin vaivannut itseäni auringon alla, koska minun täytyy se jättää ihmiselle, joka tulee minun jälkeeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Ja kuka tietää, onko hän viisas vai tyhmä? Mutta hallitsemaan hän tulee kaikkia minun vaivannäköni hedelmiä, joiden tähden minä olen vaivannut itseäni ja ollut viisas auringon alla. Tämäkin on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Niin minä annoin sydämeni vaipua epätoivoon kaikesta vaivannäöstäni, jolla olin vaivannut itseäni auringon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Sillä niin on: ihmisen, joka on vaivaa nähnyt toimien viisaudella, tiedolla ja kunnolla, täytyy antaa kaikki ihmiselle, joka ei ole siitä vaivaa nähnyt, hänen osaksensa. Sekin on turhuutta ja on suuri onnettomuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Sillä mitä saa ihminen kaikesta vaivannäöstänsä ja sydämensä pyrkimyksestä, jolla hän vaivaa itseänsä auringon alla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Ovathan kaikki hänen päivänsä pelkkää tuskaa ja hänen työnsä surua, eikä yölläkään hänen sydämensä saa lepoa. Tämäkin on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Ei ole ihmisellä muuta onnea kuin syödä ja juoda ja antaa sielunsa nauttia hyvää vaivannäkönsä ohessa; mutta minä tulin näkemään, että sekin tulee Jumalan kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, '- \"Sillä kuka voi syödä ja kuka nauttia ilman minua?\" -');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Sillä hän antaa ihmiselle, joka on hänelle otollinen, viisautta, tietoa ja iloa; mutta syntiselle hän antaa työksi koota ja kartuttaa annettavaksi sille, joka on otollinen Jumalalle. Sekin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Kaikella on määräaika, ja aikansa on joka asialla taivaan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Aika on syntyä ja aika kuolla. Aika on istuttaa ja aika repiä istutus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Aika on surmata ja aika parantaa. Aika on purkaa ja aika rakentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Aika on itkeä ja aika nauraa. Aika on valittaa ja aika hypellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Aika on heitellä kiviä ja aika kerätä kivet. Aika on syleillä ja aika olla syleilemättä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Aika on etsiä ja aika kadottaa. Aika on säilyttää ja aika viskata pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Aika on reväistä rikki ja aika ommella yhteen. Aika on olla vaiti ja aika puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Aika on rakastaa ja aika vihata. Aika on sodalla ja aika rauhalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Mitä hyötyä on työntekijällä siitä, mistä hän näkee vaivaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Minä olen katsonut sitä työtä, minkä Jumala on antanut ihmislapsille, heidän sillä itseään rasittaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Kaiken hän on tehnyt kauniisti aikanansa, myös iankaikkisuuden hän on pannut heidän sydämeensä; mutta niin on, ettei ihminen käsitä tekoja, jotka Jumala on tehnyt, ei alkua eikä loppua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Minä tulin tietämään, ettei heillä ole muuta onnea kuin iloita ja tehdä hyvää eläessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Mutta jokaiselle ihmiselle on sekin, että hän syö ja juo ja nauttii hyvää kaiken vaivannäkönsä ohessa, Jumalan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Minä tulin tietämään, että kaikki, mitä Jumala tekee, pysyy iäti. Ei ole siihen lisäämistä eikä siitä vähentämistä. Ja Jumala on sen niin tehnyt, että häntä peljättäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Mitä nyt on, sitä on ollut jo ennenkin; ja mitä vasta on oleva, sitä on ollut jo ennenkin. Jumala etsii jälleen sen, mikä on mennyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Vielä minä näin auringon alla oikeuspaikan, ja siinä oli vääryys, ja vanhurskauden paikan, ja siinä oli vääryys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Minä sanoin sydämessäni: Vanhurskaan ja väärän tuomitsee Jumala, sillä siellä on jokaisella asialla ja jokaisella teolla aikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Minä sanoin sydämessäni: Ihmislasten tähden se niin on, jotta Jumala heitä koettelisi ja he tulisivat näkemään että he omassa olossaan ovat eläimiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Sillä ihmislasten käy niinkuin eläintenkin; sama on kumpienkin kohtalo. Niinkuin toiset kuolevat, niin toisetkin kuolevat; yhtäläinen henki on kaikilla. Ihmisillä ei ole mitään etua eläinten edellä, sillä kaikki on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Kaikki menee samaan paikkaan. Kaikki on tomusta tullut, ja kaikki palajaa tomuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kuka tietää ihmisen hengestä, kohoaako se ylös, ja eläimen hengestä, vajoaako se alas maahan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Niin minä tulin näkemään, että ei ole mitään parempaa, kuin että ihminen iloitsee teoistansa, sillä se on hänen osansa. Sillä kuka tuo hänet takaisin näkemään iloksensa sitä, mikä tulee hänen jälkeensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Taas minä katselin kaikkea sortoa, jota harjoitetaan auringon alla, ja katso, siinä on sorrettujen kyyneleet, eikä ole heillä lohduttajaa; väkivaltaa tekee heidän sortajainsa käsi, eikä ole heillä lohduttajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Ja minä ylistin vainajia, jotka ovat jo kuolleet, onnellisemmiksi kuin eläviä, jotka vielä ovat elossa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'ja onnellisemmaksi kuin nämä kumpikaan sitä, joka ei vielä ole olemassa eikä ole nähnyt sitä pahaa, mikä tapahtuu auringon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Ja minä näin kaikesta vaivannäöstä ja työn kunnollisuudesta, että se on toisen kateutta toista kohtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Sekin on turhuutta ja tuulen tavoittelua. Tyhmä panee kädet ristiin ja kalvaa omaa lihaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Parempi on pivollinen lepoa kuin kahmalollinen vaivannäköä ja tuulen tavoittelua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Taas minä näin turhuuden auringon alla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Tuossa on yksinäinen, ei ole hänellä toista, ei poikaa, ei veljeäkään ole hänellä; mutta ei ole loppua kaikella hänen vaivannäöllänsä, eikä hänen silmänsä saa kylläänsä rikkaudesta. Ja kenen hyväksi minä sitten vaivaa näen ja pidätän itseni nautinnoista? Tämäkin on turhuutta ja on paha asia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Kahden on parempi kuin yksin, sillä heillä on vaivannäöstänsä hyvä palkka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Jos he lankeavat, niin toinen nostaa ylös toverinsa; mutta voi yksinäistä, jos hän lankeaa! Ei ole toista nostamassa häntä ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Myös, jos kaksi makaa yhdessä, on heillä lämmin; mutta kuinka voisi yksinäisellä olla lämmin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Ja yksinäisen kimppuun voi joku käydä, mutta kaksi pitää sille puolensa. Eikä kolmisäinen lanka pian katkea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Parempi on köyhä, mutta viisas nuorukainen kuin vanha ja tyhmä kuningas, joka ei enää ymmärrä ottaa varoituksesta vaaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Sillä vankilasta tuo toinen lähti tullaksensa kuninkaaksi, vaikka oli hänen kuninkaana ollessaan syntynyt köyhänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Minä näin kaikkien, jotka elivät ja vaelsivat auringon alla, olevan nuorukaisen puolella, tuon toisen, joka oli astuva hänen sijaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Ei ollut loppua kaikella sillä väellä, niillä kaikilla, joita hän johti; mutta jälkipolvet eivät hänestä iloitse. Sillä sekin on turhuutta ja tuulen tavoittelemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Varo jalkasi, kun menet Jumalan huoneeseen. Tulo kuulemaan on parempi kuin tyhmäin teurasuhrin-anto, sillä he ovat tietämättömiä, ja niin he tekevät pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Älä ole kerkeä suultasi, älköönkä sydämesi kiirehtikö lausumaan sanaa Jumalan edessä, sillä Jumala on taivaassa ja sinä olet maan päällä; sentähden olkoot sanasi harvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Sillä paljosta työstä tulee unia, ja missä on paljon sanoja, siinä on tyhmä äänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Kun teet lupauksen Jumalalle, niin täytä se viivyttelemättä; sillä ei ole hänellä mielisuosiota tyhmiin: täytä, mitä lupaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'On parempi, ettet lupaa, kuin että lupaat etkä täytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Älä anna suusi saattaa ruumistasi syynalaiseksi, äläkä sano Jumalan sanansaattajan edessä: \"Se oli erehdys\"; miksi pitäisi Jumalan vihastua sinun puheestasi ja turmella sinun kättesi työt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Sillä paljot unet ovat pelkkää turhuutta; samoin paljot puheet. Mutta pelkää sinä Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Jos näet köyhää sorrettavan sekä oikeutta ja vanhurskautta poljettavan maakunnassa, niin älä sitä asiaa ihmettele; sillä ylhäistä vartioitsee vielä ylhäisempi, ja sitäkin ylhäisemmät heitä molempia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Ja maalle on kaikessa hyödyksi, että viljellyllä maalla on kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Joka rakastaa rahaa, ei saa rahaa kylläksensä, eikä voittoa se, joka rakastaa tavaran paljoutta. Sekin on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Omaisuuden karttuessa karttuvat sen syöjätkin; ja mitä muuta etua siitä on haltijallensa, kuin että silmillään sen näkee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Työntekijän uni on makea, söipä hän vähän tai paljon; mutta rikkaan ei hänen yltäkylläisyytensä salli nukkua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'On raskas onnettomuus, jonka minä näin auringon alla: rikkaus, joka on säilytetty onnettomuudeksi haltijallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Se rikkaus katoaa onnettoman tapauksen kautta; ja jos hänelle on syntynyt poika, ei sen käsiin jää mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Niinkuin hän tuli äitinsä kohdusta, niin on hänen alastonna jälleen mentävä pois, samoin kuin tulikin; eikä hän vaivannäöstänsä saa mitään, minkä veisi täältä kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Raskas onnettomuus tämäkin on: aivan niinkuin hän tuli, on hänen mentävä; ja mitä hyötyä hänellä sitten on siitä, että on vaivaa nähnyt tuulen hyväksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Myös kuluttaa hän kaikki päivänsä pimeydessä; ja surua on hänellä paljon, kärsimystä ja mielikarvautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Katso, minkä minä olen tullut näkemään, on hyvää ja kaunista syödä ja juoda ja nauttia hyvää kaiken vaivannäkönsä ohessa, jolla ihminen itseänsä vaivaa auringon alla lyhyinä elämänsä päivinä, jotka Jumala on hänelle antanut; sillä se on hänen osansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Sekin on Jumalan lahja, jos Jumala kenelle ihmiselle antaa rikkautta ja tavaraa ja sallii hänen syödä siitä ja saada osansa ja iloita vaivannäkönsä ohessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Sillä hän ei tule niin paljon ajatelleeksi elämänsä päiviä, kun Jumala suostuu hänen sydämensä iloon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'On onnettomuus tämäkin, jonka olen nähnyt auringon alla ja joka raskaasti painaa ihmistä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'että Jumala antaa miehelle rikkautta ja tavaraa ja kunniaa, niin ettei hänen sielultaan puutu mitään kaikesta siitä, mitä hän halajaa, mutta Jumala ei salli hänen nauttia sitä, vaan sen nauttii vieras. Se on turhuutta ja raskas kärsimys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Vaikka syntyisi miehelle sata lasta ja hän eläisi vuosia paljon ja paljot olisivat hänen vuottensa päivät, mutta hän ei saisi tyydyttää omaa haluaan omaisuudellansa eikä saisi edes hautaustakaan, niin minä sanon, että keskoinen olisi onnellisempi kuin hän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Sillä se turhaan tulee ja pimeyteen menee, ja pimeyteen peittyy sen nimi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Ei se ole aurinkoa nähnyt eikä tuntenut. Sen lepo on parempi kuin hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Ja vaikka hän eläisi kaksi kertaa tuhannen vuotta, mutta ei saisi onnea nähdä - eikö kuitenkin kaikki mene samaan paikkaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Kaikki ihmisen vaivannäkö tapahtuu hänen oman suunsa hyväksi, ja kuitenkaan ei halu täyty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Sillä mitä etua on viisaalla tyhmän edellä, ja mitä kurjalla siitä, että hän osaa oikein vaeltaa elävitten edessä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Parempi silmän näkö kuin halun haihattelu. Tämäkin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Mitä olemassa on, sille on pantu nimi jo ammoin; ja edeltä tunnettua on ollut, mitä ihmisestä on tuleva. Ei voi hän riidellä väkevämpänsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Sillä niin on: puheen paljous enentää turhuutta. Mitä etua on ihmisellä siitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Sillä kuka tietää, mikä on ihmiselle hyvä elämässä, hänen elämänsä lyhyinä, turhina päivinä, jotka hän viettää kuin varjo; ja kuka ilmaisee ihmiselle, mitä on tuleva hänen jälkeensä auringon alla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Hyvä nimi on parempi kuin kallis öljy, ja kuolinpäivä parempi kuin syntymäpäivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Parempi kuin pitotaloon on mennä surutaloon, sillä siinä on kaikkien ihmisten loppu, ja elossa oleva painaa sen mieleensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Suru on parempi kuin nauru, sillä sydämelle on hyväksi, että kasvot ovat murheelliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Viisaitten sydän on surutalossa, tyhmien sydän ilotalossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Parempi on kuulla viisaan nuhdetta, kuin olla kuulemassa tyhmien laulua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'sillä niinkuin orjantappurain rätinä padan alla, on tyhmän nauru. Ja sekin on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Sillä väärä voitto tekee viisaan hulluksi, ja lahja turmelee sydämen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Asian loppu on parempi kuin sen alku, ja pitkämielinen on parempi kuin korkeamielinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Älköön mielesi olko pikainen vihaan, sillä viha majautuu tyhmäin poveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Älä sano: \"Mikä siinä on, että entiset ajat olivat paremmat kuin nykyiset?\" Sillä sitä et viisaudesta kysy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Viisaus on yhtä hyvä kuin perintöosa ja on etu niille, jotka ovat näkemässä aurinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Sillä viisauden varjossa on kuin rahan varjossa, mutta tieto on hyödyllisempi: viisaus pitää haltijansa elossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Katso Jumalan tekoja; sillä kuka voi sen suoristaa, minkä hän on vääräksi tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Hyvänä päivänä ole hyvillä mielin, ja pahana päivänä ymmärrä, että toisen niinkuin toisenkin on Jumala tehnyt, koskapa ihminen ei saa mitään siitä, mikä hänen jälkeensä tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Kaikkea olen tullut näkemään turhina päivinäni: on vanhurskaita, jotka hukkuvat vanhurskaudessaan, ja on jumalattomia, jotka elävät kauan pahuudessaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Älä ole kovin vanhurskas äläkä esiinny ylen viisaana: miksi tuhoaisit itsesi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Älä ole kovin jumalaton, äläkä ole tyhmä: miksi kuolisit ennen aikaasi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Hyvä on, että pidät kiinni toisesta etkä hellitä kättäsi toisestakaan, sillä Jumalaa pelkääväinen selviää näistä kaikista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Viisaus auttaa viisasta voimakkaammin kuin kymmenen vallanpitäjää, jotka ovat kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Sillä ei ole maan päällä ihmistä niin vanhurskasta, että hän tekisi vain hyvää eikä tekisi syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Älä myöskään pane mieleesi kaikkia puheita, mitä puhutaan, ettet kuulisi palvelijasi sinua kiroilevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Sillä oma sydämesikin tietää, että myös sinä olet monta kertaa kiroillut muita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Kaiken tämän olen viisaudella koetellut. Minä sanoin: \"Tahdon tulla viisaaksi\", mutta se pysyi minusta kaukana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Kaukana on kaiken olemus ja syvällä, syvällä; kuka voi sen löytää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Minä ryhdyin sydämessäni oppimaan, miettimään ja etsimään viisautta ja tutkistelun tuloksia, tullakseni tuntemaan jumalattomuuden typeryydeksi ja tyhmyyden mielettömyydeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'Ja minä löysin sen, mikä on kuolemaa katkerampi: naisen, joka on verkko, jonka sydän on paula ja jonka kädet ovat kahleet. Se, joka on otollinen Jumalan edessä, pelastuu hänestä, mutta synnintekijä häneen takertuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Katso, tämän minä olen löytänyt, sanoi saarnaaja, pyrkiessäni asia asialta löytämään tutkistelun tulosta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'mitä sieluni on yhäti etsinyt, mutta mitä en ole löytänyt, on tämä: olen löytänyt tuhannesta yhden miehen, mutta koko siitä luvusta en ole löytänyt yhtäkään naista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Katso, tämän ainoastaan olen löytänyt: että Jumala on tehnyt ihmiset suoriksi, mutta itse he etsivät monia mutkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kuka on viisaan vertainen, ja kuka taitaa selittää asian? Ihmisen viisaus kirkastaa hänen kasvonsa, ja hänen kasvojensa kovuus muuttuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Minä sanon: Ota vaari kuninkaan käskystä, varsinkin Jumalan kautta vannotun valan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Älä ole kerkeä luopumaan hänestä, äläkä asetu pahan asian puolelle, sillä hän tekee, mitä vain tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Sillä kuninkaan sana on voimallinen, ja kuka voi sanoa hänelle: Mitäs teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Joka käskyn pitää, ei tiedä pahasta asiasta; ja viisaan sydän tietää ajan ja tuomion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Sillä itsekullakin asialla on aikansa ja tuomionsa; ihmistä näet painaa raskaasti hänen pahuutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Hän ei tiedä, mitä tuleva on; sillä kuka ilmaisee hänelle, miten se on tuleva?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Ei ole ihminen tuulen valtias, niin että hän voisi sulkea tuulen, ei hallitse kukaan kuoleman päivää, ei ole pääsyä sodasta, eikä jumalattomuus pelasta harjoittajaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Kaiken tämän minä tulin näkemään, kun käänsin sydämeni tarkkaamaan kaikkea, mitä auringon alla tapahtuu aikana, jolloin ihminen vallitsee toista ihmistä hänen onnettomuudekseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Sitten minä näin, kuinka jumalattomat haudattiin ja menivät lepoon, mutta ne, jotka olivat oikein tehneet, saivat lähteä pois pyhästä paikasta ja joutuivat unhotuksiin kaupungissa. Sekin on turhuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Milloin pahan teon tuomio ei tule pian, saavat ihmislapset rohkeutta tehdä pahaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'koskapa syntinen saa tehdä pahaa sata kertaa ja elää kauan; tosin minä tiedän, että Jumalaa pelkääväisille käy hyvin, sentähden että he häntä pelkäävät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'mutta että jumalattomalle ei käy hyvin eikä hän saa jatkaa päiviään pitkiksi kuin varjo, sentähden ettei hän pelkää Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'On turhuutta sekin, mitä tapahtuu maan päällä, kun vanhurskaita on, joiden käy, niinkuin olisivat jumalattomain tekoja tehneet, ja jumalattomia on, joiden käy, niinkuin olisivat vanhurskaitten tekoja tehneet. Minä sanoin: sekin on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Ja minä ylistin iloa, koska ei ihmisellä auringon alla ole mitään parempaa kuin syödä ja juoda ja olla iloinen; se seuraa häntä hänen vaivannäkönsä ohessa hänen elämänsä päivinä, jotka Jumala on antanut hänelle auringon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Kun minä käänsin sydämeni oppimaan viisautta ja katsomaan työtä, jota tehdään maan päällä saamatta untakaan silmiin päivällä tai yöllä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'niin minä tulin näkemään kaikista Jumalan teoista, että ihminen ei voi käsittää sitä, mitä tapahtuu auringon alla; sillä ihminen saa kyllä nähdä vaivaa etsiessään, mutta ei hän käsitä. Ja jos viisas luuleekin tietävänsä, ei hän kuitenkaan voi käsittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Niin minä painoin mieleeni kaiken tämän ja pyrin saamaan kaikkea tätä selville, kuinka näet vanhurskaat ja viisaat ja heidän tekonsa ovat Jumalan kädessä. Ei rakkauskaan eikä viha ole ihmisen tiedettävissä; kaikkea voi hänellä olla edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Kaikkea voi tapahtua kaikille. Sama kohtalo on vanhurskaalla ja jumalattomalla, hyvällä, puhtaalla ja saastaisella, uhraajalla ja uhraamattomalla; hyvän käy niinkuin syntisenkin, vannojan niinkuin valaa pelkäävänkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Se on onnettomuus kaikessa, mitä tapahtuu auringon alla, että kaikilla on sama kohtalo, ja myös se, että ihmislasten sydän on täynnä pahaa ja että mielettömyys on heillä sydämessä heidän elinaikansa; ja senjälkeen - vainajien tykö!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Onhan sillä, jonka vielä on suotu olla kaikkien eläväin seurassa, toivoa. Sillä elävä koira on parempi kuin kuollut leijona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Sillä elävät tietävät, että heidän on kuoltava, mutta kuolleet eivät tiedä mitään, eikä heillä ole paikkaa, vaan heidän muistonsa on unhotettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Myös heidän rakkautensa, vihansa ja intohimonsa on jo aikoja mennyt, eikä heillä ole milloinkaan enää osaa missään, mitä tapahtuu auringon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Tule siis, syö leipäsi ilolla ja juo viinisi hyvillä mielin, sillä jo aikaa on Jumala hyväksynyt nuo tekosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Vaatteesi olkoot aina valkeat, ja öljy älköön puuttuko päästäsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Nauti elämää vaimon kanssa, jota rakastat, kaikkina turhan elämäsi päivinä, jotka Jumala on sinulle antanut auringon alla - kaikkina turhina päivinäsi, sillä se on sinun osasi elämässä ja vaivannäössäsi, jolla vaivaat itseäsi auringon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Tee kaikki, mitä voimallasi tehdyksi saat, sillä ei ole tekoa, ei ajatusta, ei tietoa eikä viisautta tuonelassa, jonne olet menevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Taas minä tulin näkemään auringon alla, että ei ole juoksu nopsain vallassa, ei sota urhojen, ei leipä viisaitten, ei rikkaus ymmärtäväisten eikä suosio taitavain vallassa, vaan aika ja kohtalo kohtaa kaikkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Sillä ei ihminen tiedä aikaansa, niinkuin eivät kalatkaan, jotka tarttuvat pahaan verkkoon, eivätkä linnut, jotka käyvät kiinni paulaan; niinkuin ne, niin pyydystetään ihmislapsetkin pahana aikana, joka yllättää heidät äkisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Tämänkin minä tulin näkemään viisaudeksi auringon alla, ja se oli minusta suuri:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Oli pieni kaupunki ja siinä miehiä vähän. Ja suuri kuningas tuli sitä vastaan, saarsi sen ja rakensi sitä vastaan suuria piiritystorneja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Mutta siellä oli köyhä, viisas mies, ja hän pelasti kaupungin viisaudellaan. Mutta ei kukaan ihminen muistanut sitä köyhää miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Niin minä sanoin: Viisaus on parempi kuin voima, mutta köyhän viisautta halveksitaan, eikä hänen sanojansa kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Viisaitten sanat, hiljaisuudessa kuullut, ovat paremmat kuin tyhmäin päämiehen huuto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Viisaus on parempi kuin sota-aseet, mutta yksi ainoa syntinen saattaa hukkaan paljon hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Myrkkykärpäset saavat haisemaan ja käymään voiteentekijän voiteen. Pieni tyhmyys painaa enemmän kuin viisaus ja kunnia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Viisaan sydän vetää oikealle, tyhmän vasemmalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Tietä käydessäkin puuttuu tyhmältä mieltä: jokaiselle hän ilmaisee olevansa tyhmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Jos hallitsijassa nousee viha sinua kohtaan, niin älä jätä paikkaasi; sillä sävyisyys pidättää suurista synneistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'On onnettomuus se, minkä olen nähnyt auringon alla, vallanpitäjästä lähtenyt erehdys:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'tyhmyys asetetaan arvon korkeuksiin, ja rikkaat saavat istua alhaalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Minä olen nähnyt palvelijat hevosten selässä ja ruhtinaat kävelemässä kuin palvelijat maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Joka kuopan kaivaa, se siihen putoaa; joka muuria purkaa, sitä puree käärme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Joka kiviä louhii, se niihin loukkaantuu; joka puita halkoo, se joutuu siinä vaaraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Jos rauta on tylsynyt eikä teränsuuta tahkota, täytyy ponnistaa voimia; mutta hyödyllinen kuntoonpano on viisautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Jos käärme puree silloin, kun sitä ei ole lumottu, ei lumoojalla ole hyötyä taidostaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Sanat viisaan suusta saavat suosiota, mutta tyhmän nielevät hänen omat huulensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Hänen suunsa sanain alku on tyhmyyttä, ja hänen puheensa loppu pahaa mielettömyyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Tyhmä puhuu paljon; mutta ihminen ei tiedä, mitä tuleva on. Ja kuka ilmaisee hänelle, mitä hänen jälkeensä tulee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Oma vaivannäkö väsyttää tyhmän, joka ei osaa kaupunkiinkaan kulkea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Voi sinua, maa, jolla on kuninkaana poikanen ja jonka ruhtinaat jo aamulla aterioita pitävät!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Onnellinen sinä, maa, jolla on jalosukuinen kuningas ja jonka ruhtinaat pitävät aterioita oikeaan aikaan, miehekkäästi eikä juopotellen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Missä laiskuus on, siinä vuoliaiset vaipuvat; ja missä kädet velttoina riippuvat, tippuu huoneeseen vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Hauskuudeksi ateria laitetaan, ja viini ilahuttaa elämän; mutta raha kaiken hankkii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Älä ajatuksissasikaan kiroile kuningasta, äläkä makuukammiossasikaan kiroile rikasta, sillä taivaan linnut kuljettavat sinun äänesi ja siivelliset ilmaisevat sinun sanasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Lähetä leipäsi vetten yli, sillä ajan pitkään sinä saat sen jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Anna osa seitsemälle, kahdeksallekin, sillä et tiedä, mitä onnettomuutta voi tulla maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Jos pilvet tulevat täyteen sadetta, valavat ne sen maahan. Ja jos puu kaatuu etelää kohti tai pohjoista, niin mihin paikkaan puu kaatui, siihen se jää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Joka tuulta tarkkaa, ei kylvä; ja joka pilviä pälyy, ei leikkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Niinkuin et tiedä tuulen teitä etkä luitten rakentumista raskaana olevan kohdussa, niin et myöskään tiedä Jumalan tekoja, hänen, joka kaikki tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Kylvä siemenesi aamulla äläkä hellitä kättäsi ehtoollakaan; sillä et tiedä, tuoko onnistuu vai tämä vai onko kumpikin yhtä hyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Suloinen on valo, ja silmille tekee hyvää nähdä aurinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Niin, jos ihminen elää vuosia paljonkin, iloitkoon hän niistä kaikista, mutta muistakoon pimeitä päiviä, sillä niitä tulee paljon. Kaikki, mikä tulee, on turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Iloitse, nuorukainen, nuoruudessasi, ja sydämesi ilahuttakoon sinua nuoruusikäsi päivinä. Vaella sydämesi teitä ja silmiesi halun mukaan; mutta tiedä: Jumala tuo sinut tuomiolle kaikesta tästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Karkoita suru sydämestäsi ja torju kärsimys ruumiistasi, sillä nuoruus ja aamurusko ovat turhuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Ja muista Luojaasi nuoruudessasi, ennenkuin pahat päivät tulevat ja joutuvat ne vuodet, joista olet sanova:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, '\"Nämä eivät minua miellytä\"; ennenkuin pimenee aurinko, päivänvalo, kuu ja tähdet, ja pilvet palajavat sateen jälkeenkin -');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'jolloin huoneen vartijat vapisevat ja voiman miehet käyvät koukkuisiksi ja jauhajanaiset ovat joutilaina, kun ovat menneet vähiin, ja akkunoista-kurkistelijat jäävät pimeään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'ja kadulle vievät ovet sulkeutuvat ja myllyn ääni heikkenee ja noustaan linnun lauluun ja kaikki laulun tyttäret hiljentyvät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'myös peljätään mäkiä, ja tiellä on kauhuja, ja mantelipuu kukkii, ja heinäsirkka kulkee kankeasti, ja kapriisinnuppu on tehoton; sillä ihminen menee iankaikkiseen majaansa, ja valittajat kiertelevät kaduilla');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ennenkuin hopealanka katkeaa ja kultamalja särkyy ja vesiastia rikkoutuu lähteellä ja ammennuspyörä särkyneenä putoaa kaivoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Ja tomu palajaa maahan, niinkuin on ollutkin, ja henki palajaa Jumalan tykö, joka sen on antanutkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Turhuuksien turhuus, sanoi saarnaaja; kaikki on turhuutta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Sen lisäksi, että saarnaaja oli viisas, hän myös opetti kansalle tietoa, punnitsi, harkitsi ja sommitteli sananlaskuja paljon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Saarnaaja koki löytää kelvollisia sanoja, oikeassa mielessä kirjoitettuja, totuuden sanoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Viisaitten sanat ovat kuin tutkaimet ja kootut lauseet kuin isketyt naulat; ne ovat saman Paimenen antamia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Ja vielä näiden lisäksi: Poikani, ota varoituksesta vaari; paljolla kirjaintekemisellä ei ole loppua, ja paljo tutkistelu väsyttää ruumiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Loppusana kaikesta, mitä on kuultu, on tämä: Pelkää Jumalaa ja pidä hänen käskynsä, sillä niin tulee jokaisen ihmisen tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Sillä Jumala tuo kaikki teot tuomiolle, joka kohtaa kaikkea salassa olevaa, olkoon se hyvää tai pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Salomon korkia veisu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Hän suuta antakoon minun, suunsa antamisella; sillä sinun rakkautesi on suloisempi kuin viina,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Sinun hyväin voidettes hajuin tähden. Sinun nimes on vuodatettu öljy; sen piikaiset sinua rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Vedä minua, niin me juoksemme perässäs: Kuningas vie minun kammioonsa: Me iloitsemme ja riemuitsemme sinusta, me muistamme sinun rakkauttas enempi kuin viinaa: hurskaat rakastavat sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Minä olen musta, mutta sangen otollinen, te Jerusalemin tyttäret, niinkuin Kedarin majat, niinkuin Salomon kirjoiteltu vaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Älkäät sitä katsoko, että minä niin musta olen; sillä päivä on minun polttanut: minun äitini lapset vihastuivat minun päälleni: he ovat asettaneet minun viinamäen vartiaksi, mutta en minä varjellut viinamäkeäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Sano minulle sinä, jota minun sieluni rakastaa: kussas laidunta pidät, ja kussas lounaalla lepäät? ettei minun pitäisi poikkeeman kumppanies lauman tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Jos et sinä sinuas tunne, sinä kaikkein ihanaisin vaimoin seassa, niin mene lammasten jäljille, ja kaitse vohlias paimenien huonetten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Minä vertaan sinun, ystäväni, ratsaskaluihini, Pharaon vaunuihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Sinun sasupääs ovat ihanat pankkuin keskellä, ja sinun kaulas kultakäädyissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Me teemme sinulle kultaiset pankut, hopianastoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Kuin kuningas istui pöytänsä tykönä, antoi nardukseni hajunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Ystäväni on minun mirrhamkimppuni, joka minun rinnoillani riippuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Minun ystäväni on minulle Kyprin viinamarjan rypäle, Engeddin viinamäessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Katso, armaani, sinä olet ihana: katso, sinä olet ihana, silmäs ovat niinkuin kyhkyläisen silmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Katso, ystäväni, sinä olet ihana ja suloinen, ja meidän vuoteemme myös viheriöitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Meidän huoneemme kaaret ovat sedripuusta, vuolteet hongasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Minä olen Saronin kukkanen, ja kukoistus laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Niinkuin ruusu orjantappuroissa, niin on armaani tytärten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Niinkuin omenapuu metsäpuiden seassa, niin on ystäväni poikain seassa: minä istun hänen varjossansa, jota minä anon, ja hänen hedelmänsä on minun suussani makia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Hän johdattaa minua viinakellariinsa; ja rakkaus on hänen lippunsa minun päälläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Virvoittakaat minua viinaleileillä, ja vahvistakaat minua omenilla; sillä minä olen sairas rakkaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Hänen vasen kätensä on minun pääni alla, hänen oikia kätensä halaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Minä vannotan tietä, Jerusalemin tyttäret, metsävuohten eli naaraspeurain kautta kedolla, ettette herätä eli vaivaa armastani, siihen asti kuin hän itse tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Tämä on ystäväni ääni, katso, hän tulee: hän hyppää vuorilla ja karkaa kukkuloille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Ystäväni on metsävuohen eli nuoren peuran kaltainen: katso, hän seisoo seinän takana, ja katsoo akkunasta sisälle, ja kurkistelee häkin lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Ystäväni vastaa ja sanoo minulle: nouse armaani, ihanaiseni, ja tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Sillä katso, talvi on kulunut, ja sade lakannut ja mennyt pois:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Kukkaset ovat puhjenneet kedolla, kevät on tullut, ja toukomettisen ääni kuuluu meidän maassamme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Fikunapuut puhkeevat, viinapuut kukoistavat ja antavat hajunsa: nouse, armaani, ihanaiseni, ja tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Kyhkyläiseni vuoren raossa ja kivirauniossa, anna minun nähdä kasvos, anna minun kuulla äänes; sillä sinun äänes on suloinen, ja kasvos ihanainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Ottakaat meille ketut kiinni, ne vähät ketut, jotka turmelevat viinamäet; sillä meidän viinamäkemme ovat röhkäleillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Ystäväni on minun, ja minä hänen, joka kaitsee kukkasten keskellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Siihenasti että päivä jäähtyy ja varjot kulkevat pois. Palaja, ole niinkuin metsävuohi, ystäväni, eli niinkuin nuori peura Eroitusvuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Minä etsin yöllä vuoteessani, jota minun sieluni rakastaa: minä etsin häntä, mutta en löytänyt häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Nyt minä nousen, ja käyn kaupunkia ympäri, kaduilla ja kujilla, ja etsin, jota minun sieluni rakastaa: minä etsin häntä, mutta en minä häntä löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Vartiat, jotka käyvät kaupunkia ympäri, löysivät minun. Oletteko nähneet, jota minun sieluni rakastaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Kuin minä heistä vähä erkausin, löysin minä, jota minun sieluni rakastaa; minä tartuin häneen, ja en tahdo häntä laskea, siihenasti että minä hänen saatan äitini huoneesen, äitini kammioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Minä vannotan teitä, Jerusalemin tyttäret, metsävuohten eli naaraspeurain kautta kedolla, ettette herättäisi armastani eli vaivaisi häntä, siihenasti kuin hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kuka on tämä, joka lähtee korvesta, niinkuin nouseva savu, mirrhamin suitsutus, pyhä savu ja kaikkinaiset apotekarin yrtit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Katso, Salomon vuoteen ympärillä seisovat kuusikymmentä väkevää, Israelin väkevistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'He pitävät kaikki miekkaa ja ovat soveliaat sotaa; jokaisella on hänen miekkansa vyöllänsä pelvon tähden yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Kuningas Salomo antoi tehdä itsellänsä lepokammion Libanonin puista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Sen patsaat hän teki hopiasta, ja sen peitteen kullasta, istuimen purpurasta, ja permannon soveliaasti lasketun, Jerusalemin tytärten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Lähtekäät ulos, te Zionin tyttäret, ja katselkaat kuningas Salomoa siinä kruunussa, jolla hänen äitinsä hänen kruunannut on, hänen hääpäivänsä, ja hänen sydämensä ilopäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Katso, armaani! sinä olet ihanainen, katso, ihanainen sinä olet: sinun silmäs ovat niinkuin mettisen silmät palmikkos välillä; sinun hiukses ovat niinkuin vuohilauma, jotka ovat kerityt Gileadin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Sinun hampaas ovat niinkuin laumat kerittyin villain kanssa, jotka pesosta tulevat, jotka kaikki kaksoisia kantavat, ei myös yksikään heistä ole hedelmätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Sinun huules ovat niinkuin tulipunainen rihma, ja sinun puhees ovat suloiset; sinun poskes ovat niinkuin granatin omenan lohko, sinun palmikkos välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Sinun kaulas on niinkuin Davidin torni, joka on rakennettu vahvalla muurilla, jossa tuhannen kilpeä riippuu, ja kaikkinaiset väkeväin sota-aseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Sinun kaksi rintaas ovat niinkuin kaksi nuorta metsävohlaa, jotka kukkasten seassa laitumella käyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Siihenasti että päivä soipeemmaksi tulee, ja varjo katoo: minä menen mirrhamin vuorelle, ja pyhän savun kukkulalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Sinä olet kokonas ihana, minun armaani, ja ei sinussa ole yhtään virhettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Tule kanssani, morsiameni, Libanonista, tule kanssani Libanonista, mene sisälle, astu tänne Amanan kukkulalta, Senirin Hermonin niskalta, jalopeuran luolasta ja leopardein vuorelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Sinä olet ottanut minun sydämeni pois, sisareni, rakas morsiameni: sinä olet ottanut sydämeni pois yhdellä silmälläs ja yhdellä kaulakäädylläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Kuinka ihana on sinun rakkautes, sisareni, rakas morsiameni: sinun rakkautes on suloisempi kuin viina, ja sinun voitees haju voittaa kaikki yrtit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Sinun huules, morsiameni, ovat niinkuin valuva mesileipä: mesi ja maito on sinun kieles alla, ja sinun vaattees haju on niinkuin Libanonin haju.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Minun sisareni, rakas morsiameni, sinä olet suljettu kryytimaa, lukittu lähde, kiinnipantu kaivo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Sinun istutukses ovat niinkuin yrttitarha granatomenista, kalliin hedelmän kanssa, syprit narduksen kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Nardukset saframin kanssa, kalmus ja kaneli, kaikkinaisen pyhän savun puiden kanssa, mirrham ja aloes kaikkein parasten yrttein kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Niinkuin kryytimaan kaivo, ja elävänveden lähde, joka Libanonista vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Nouse pohjatuuli, ja tule lounatuuli ja puhalla yrttitarhani lävitse, että sen yrtit vuotaisivat. Ystäväni tulkoon kryytimaahansa, ja syökään hänen kalliita hedelmiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Minä tulin, sisareni, rakas morsiameni, yrttitarhaani, ja olen mirrhamini ja yrttini leikannut ylös. Minä olen syönyt mesileipäni hunajan kanssa: minä olen juonut viinani minun maitoni kanssa: syökäät armaani, ja juokaat ystäväni, ja juopukaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Minä makaan, ja minun sydämeni valvoo; se on ystäväni ääni, joka kolkuttaa. Avaa minun eteeni, sisareni, armaani, kyhkyläiseni, ihanaiseni; sillä minun pääni on täynnä kastetta, ja minun palmikkoni täynnä yön pisaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Minä olen riisunut hameeni, kuinka minun pitäis taas pukeman ylleni? Minä olen viruttanut jalkani, kuinka minun pitäis sokaiseman ne jälleen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Mutta minun ystäväni pisti kätensä lävestä, ja minun sisällykseni vapisivat siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Silloin nousin minä avaamaan ystävälleni. Minun käteni tiukkuivat mirrhamia, ja mirrham valui minun sormistani lukon salvan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Ja kuin minä ystävälleni avasin, oli ystäväni mennyt pois ja vaeltanut ohitse; niin läksi sieluni ulos hänen sanansa jälkeen; minä etsin häntä, mutta en löytänyt häntä: minä huusin, mutta ei hän minua vastannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Vartiat, jotka käyvät kaupunkia ympäri, löysivät minun, löivät minua ja haavoittivat minun; ja vartiat muurin päällä ottivat pois minun pääliinani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Minä vannotan teitä, Jerusalemin tyttäret, jos te löydätte minun ystäväni, niin ilmoittakaat hänelle, että minä olen sairas rakkaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Millinen on sinun ystäväs muiden ystävien suhteen, sinä kaikkein ihanaisin vaimoin seassa? Minkäkaltainen on sinun ystäväs muiden ystävien suhteen, ettäs meitä olet niin vannottanut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Minun ystäväni on valkia ja punainen, kaunistettu kymmenentuhannen seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hänen päänsä on paras ja kallein kulta; hänen hiuksensa ovat kaharat ja mustat niinkuin kaarne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Hänen silmänsä ovat niinkuin mettisen silmät, vesiojan tykönä, rieskalla pestyt, ja ovat täynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Hänen poskensa ovat niinkuin kaunistettu ryytimaa, niinkuin yrttein kukkaset; hänen huulensa ovat niinkuin ruusut, jotka vuotavat mirrhamin pisaroita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Hänen kätensä ovat niinkuin kultaiset sormukset, täynnä turkosia; hänen ihonsa on niinkuin puhdas elephantin luu, saphirilla kaunistettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Hänen jalkansa ovat niinkuin marmoripatsaat, perustetut kultaisten jalkain päälle; hänen hahmonsa on niinkuin Libanon ja valittu sedri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Hänen suunsa on suloinen, ja hän itse kokonansa ihanainen. Senkaltainen on minun ystäväni, minun rakkaani on senkaltainen, te Jerusalemin tyttäret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Kuhunka ystäväs on mennyt, o sinä kaikkein kaunein vaimoin seassa! kuhunka ystäväs on kääntänyt itsensä? Me etsimme häntä sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Minun ystäväni on mennyt kryytimaahansa, yrttisarkoihinsa, että hän siellä kryytimaassa kaitsis laumaansa, ja hakis ruusuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Minun ystäväni on minun ja minä olen hänen, joka kaitsee kukkasten keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Sinä olet ihana, minun kultani, niinkuin Tirtsa, kaunis niinkuin Jerusalem, peljättävä niinkuin sotajoukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Käännä silmäs pois minusta; sillä ne minun sytyttävät; sinun hiukses ovat niinkuin vuohilauma, jotka Gileadin vuorella kerityt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Sinun hampas ovat niinkuin lammaslauma, jotka pesosta nousevat, ja kaikki kaksoisia kantavat, ja ei yksikään ole heistä hedelmätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Sinun kasvos ovat niinkuin granatomenan lohkot sinun palmikkois välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Kuusikymmentä on drottninkia ja kahdeksankymmentä vaimoa, ja neitseet ovat epälukuiset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Mutta yksi on minun kyhkyläiseni ja minun täydelliseni; yksi on äitinsä rakkain ja synnyttäjänsä valittu: koska tyttäret hänen näkivät, ylistivät he hänen autuaaksi, kuningattaret ja vaimot ylistivät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Kuka on tämä, joka nähdään niinkuin aamurusko, ihana niinkuin kuu, valittu niinkuin aurinko, peljättävä niinkuin sotajoukko?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Minä olen mennyt alas yrttitarhaani, katsomaan vesoja ojan reunalla, kurkistelemaan, jos viinapuut kukoistivat, jos granatomenat viheriöitsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'En minä tiennyt, että minun sieluni minun hamaan minun mieluisen kansani vaunuihin asti asettanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Palaja, palaja Sulamit: palaja, palaja nähdäksemme sinua. Mitä te näitte Sulamitissa, paitsi sotajoukkoin tanssia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Kuinka ihana on sinun käyntös kengissäs, sinä päämiehen tytär; sinun molemmat lantees ovat yhtäläiset niinkuin kaksi käätyä, jotka taitavan kädet tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Sinun napas niinkuin ympyriäinen malja, josta ei koskaan juoma puutu; sinun vatsas on niinkuin nisuläjä, istutettu ympäri ruusuilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Sinun molemmat rintas ovat niinkuin kaksi nuorta metsävuohen kaksoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Sinun kaulas on niinkuin elephantinluinen torni; sinun silmäs ovat niinkuin Hesbonin kalalammikot Batrabbimin portissa; sinun nenäs on niinkuin Libanonin torni, joka katsoo Damaskuun päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Sinun pääs on niinkuin Karmeli, sinun pääs hiukset niinkuin kuninkaan purpura, poimuineen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Kuinka ihana ja suloinen olet sinä minun armaani hekumassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Sinun vartes on niinkuin palmupuu, ja sinun rintas ovat viinimarjarypälten kaltaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Minä sanoin: minun täytyy astua palmupuuhun ja ruveta sen oksiin: anna sinun rintas olla niinkuin viinapuun marjarypäleet, sinun sierantes haju on niinkuin omenain (haju),');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Ja sinun suus niinkuin paras viina, joka huokiasti menee ystävääni, ja saattaa uneliasten huulet puhumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Minun ystäväni on minun, ja hän himoitsee minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Tule, ystäväni, käykäämme tästä kedolle, ja viipykäämme maakylissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Että me nousisimme varhain viinamäkeen ja näkisimme, jos viinapuut kukoistavat ja puhkeemaan rupeevat, jos granatomenat ovat tulleet ulos: siellä minä annan sinulle minun rakkauteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Kukkaset antavat hajunsa, ja meidän ovemme edessä ovat kaikkinaiset hyvät hedelmät: minun ystäväni, minä olen sinulle tallelle pannut sekä uudet että vanhat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Jospa minä sinun löytäisin ulkona, minun veljeni, sinä joka minun äitini nisiä imenyt olet, ja sinun suuta antaisin, ja ettei kenkään minua pilkkaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Mitä ottaisin sinun ja saattaisin sinua minun äitini huoneesen, jossa minua opettaisit; ja minä annan sinulle kryydättyä viinaa ja granatomenan makiaa viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Hänen vasen kätensä on minun pääni alla, ja hänen oikia kätensä halaa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Minä vannotan teitä, Jerusalemin tyttäret, ettette armastani herätä, eli vaivaa häntä siihenasti kuin hän itse tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kuka on se, joka korvesta tulee, ja nojaa ystävänsä päälle? Omenapuun alla minä sinua herätän, jossa sinun äitis sinun synnyttänyt on, jossa hän sinun siitti, joka sinun synnytti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Pane minua niinkuin sinetti sydämees, ja niinkuin sinetti käsivartees; sillä rakkaus on väkevä niinkuin kuolema, ja kiivaus on vahva niinkuin helvetti: hänen hiilensä hehkuvat ja ovat Herran tuli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Niin ettei vedenkään paljous taida rakkautta sammuttaa, eli virrat sitä upottaa. Jos joku antais kaiken taloinsa tavaran rakkaudesta, niin ei se mitään maksaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Meidän sisaremme on vähä, ja ei hänellä ole rintoja. Mitä meidän pitää tekemän sisarellemme sinä päivänä, jona hänestä puhutaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Jos hän on muuri, niin me teemme hopialinnan sen päälle: jos hän on ovi, niin me vahvistamme sen sedrilaudoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Minä olen muuri, ja minun rintani ovat niinkuin tornit; siitä minä olen hänen silmäinsä edessä niinkuin rauhan löytäjä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomolla on viinamäki BaalHamonissa: sen viinamäen antoi hän vartioille, että jokainen antais hänen hedelmistänsä tuhannen hopiapenninkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Minun viinamäkeni, joka on minun omani, on minun edessäni. Sinulle Salomo tulee tuhannen, mutta kaksisataa hedelmäin vartioille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Sinä, joka asut yrttitarhassa, anna minun kuulla sinun äänes: kuulkaan kumppanit päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Pakene, ystäväni, ja ole metsävuohen kaltainen, eli nuoren peuran yrttivuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Jesaian, Amotsin pojan näky, jonka hän näki Juudasta ja Jerusalemista, Ussian, Jotamin, Ahaksen ja Jehiskian, Juudan kuningasten aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Kuulkaat taivaat, ja maa ota korviis, sillä Herra puhuu: minä olen lapsia kasvattanut ja korottanut, ja he ovat minusta luopuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Härkä tuntee omistajansa ja aasi isäntänsä seimen; mutta Israel ei tunne, ja minun kansani ei ymmärrä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Voi syntistä kansaa, kansaa suuresta pahasta teosta, pahanilkistä siementä, vahingollisia lapsia, jotka Herran hylkäsivät ja Israelin Pyhää pilkkasivat, he poikkesivat takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Mitä varten teitä enempi lyödään, koska te aina harhailette? Koko pää on sairas, ja koko sydän on väsynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Hamasta kantapäästä niin kiireeseen asti ei hänessä ole tervettä; vaan haavat, sinimarjat ja veripahat, jotka ei ole puserretut, eikä sidotut, taikka öljyllä sivellyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Teidän maanne on autiona, teidän kaupunkinne ovat tulella poltetut; muukalaiset syövät peltonne silmäin edessä; ja on autio, niinkuin se, joka muukalaisilta raadeltu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Mutta mitä vielä Zionin tyttärestä jäänyt on, se on niinkuin maja viinamäessä, ja niinkuin hakomaja yrttitarhassa, niinkuin hävitetty kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Ellei Herra Zebaot meille jotakin vähää jättäisi, niin me olisimme kuin Sodoma, ja olisimme Gomorran kaltaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Te Sodoman päämiehet, kuulkaat Herran sanaa: ottakaat korviinne meidän Jumalamme laki, sinä Gomorran kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Mitä minulle on teidän uhrienne paljoudesta? sanoo Herra: minä olen oinasten polttouhrista ja syöttiläin rasvasta ravittu, ja en tottele vasikkain, lammasten ja kauristen verta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Kuin te tulette ja ilmestytte minun kasvoini eteen, kuka senkaltaisia vaatii teidän käsistänne, että te vaeltaisitte minun esihuoneessani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Älkäät silleen turhaa ruokauhrianne tuoko edes, se suitsutus on minulle kauhistus: uudella kuulla ja sabbatina, kuin kokous kuulutetaan, en minä voi kärsiä vääryyttä ja juhlapäivää yhdessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Minun sieluni vihaa uusia kuitanne ja juhlapäiviänne, minä olen niistä suuttunut; minä väsyn niitä kärseissäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Ja kuin te parhaallansa käsiänne nostatte, niin minä kuitenkin käännän silmäni teistä pois; ja vaikka te paljon rukoilisitte, en minä kuitenkaan teitä kuule; teidän kätenne ovat verenvikoja täynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Peskäät teitänne, puhdistakaat teitänne, pankaat paha menonne pois minun silmäini edestä, lakatkaat pahaa tekemästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Oppikaat tekemään hyvää, ja etsikäät oikeutta, auttakaat alaspainettua, saattakat orvoille oikeus, ja auttakaat lesken asiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Ja sitte tulkaat, ja katsokaamme, kummalla oikeus on, sanoo Herra. Jos teidän syntinne veriruskiat olisivat, niin heidän pitää lumivalkiaksi tuleman; ja vaikka he olisivat niinkuin ruusunkarvaiset, pitää heidän kuitenkin niinkuin villa tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Jos te tahtoisitte ja (minua) kuulisitte, niin te maan hyvyyden nautita saisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Mutta jos te estelette teitänne ja olette kovakorvaiset, niin miekan pitää teitä syömän; sillä Herran suu puhuu sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Kuinka se tapahtuu, että hurskas kaupunki on portoksi tullut? Hän oli täynnä oikeutta, vanhurskaus asui hänessä; mutta nyt murhaajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Sinun hopias on karreksi tullut, sinun juomas on vedellä sekoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Sinun päämiehes ovat vilpistelleet ja varasten kumppanit; kaikki he mielellänsä lahjoja ottavat, ja pyytävät antimia. Ei he orvoille oikeutta tee, ja leskein asia ei tule heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Sentähden sanoo Herra, Herra Zebaot, väkevä Israelissa: voi! minä tahdon itseni lohduttaa vihollisistani, ja vihamiehissäni vihani sammuttaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Ja käännän käteni sinua vastaan, ja sinun kartes puhtaammaksi selitän, ja vien pois kaiken sinun tinas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Ja saatan sinun tuomaris entisellensä, ja neuvonantajas niinkuin alustakin: sitte sinä kutsutaan vanhurskaaksi ja uskolliseksi kaupungiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Zion lunastetaan oikeudella, ja sen kääntyväiset vanhurskaudella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Että ylitsekäymärit ja syntiset ynnä särjetään, ja jotka Herran hylkäävät, hukutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Sillä heidän täytyy häpiään tulla tammien tähden, joita he himoitsevat, ja häväistyksi tuleman yrttitarhain tähden, jotka he valitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Ja te tulette niinkuin joku tammi surkastuneilla lehdillä, ja niinkuin joku vedetöin yrttitarha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Ja väkevä tulee niinkuin rohdin, ja hänen tekonsa niinkuin kipinä. Ja he sytytetään ynnä molemmat, jota ei kenkään sammuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Tämä on se, minkä Jesaia Amotsin poika näki Juudasta ja Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Viimeisenä aikana pitää sen vuoren, jolla Herran huone on, vahvan oleman, korkiampi kuin kaikki vuoret, ja korotettaman kukkulain ylitse; ja kaikki pakanat pitää sinne juokseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Ja paljo kansaa pitää sinne menemän, ja sanoman: tulkaat, astukaamme ylös Herran vuorelle, Jakobin Jumalan huoneeseen, että hän opettais meille teitänsä, ja me vaeltaisimme hänen poluillansa; sillä Zionista on laki tuleva, ja Herran sana Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Ja hän tuomitsee pakanain seassa, ja rankaisee monta kansaa. Silloin heidän pitää miekkansa vannaksi tekemän, ja keihäänsä vikahteeksi; sillä ei yhdenkään kansan pidä toista kansaa vastaan miekkaa nostaman, eikä silleen tottuman sotimaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Tulkaat, te Jakobin huoneesta, vaeltakaamme Herran valkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Mutta sinä olet sinun kansas Jakobin huoneen hyljännyt; sillä he rikkovat enemmän kuin itäläiset, ja ovat päiväin valitsiat, niinkuin Philistealaiset, ja sallivat muukalaiset lapset moneksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Heidän maansa on täynnä hopiaa ja kultaa, ja heidän rikkaudellansa ei ole loppua; heidän maansa on täynnä hevosia, ja heidän rattaillansa ei ole loppua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Heidän maansa on myös täynnä epäjumalia; he kumartavat käsialaansa, jotka heidän sormensa tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Siellä yhteinen kansa kumartelee, siellä sankarit heitänsä nöyryyttävät, joka et heille anna anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Mene kallioon, ja kätke sinuas maahan, Herran pelvon edestä, ja hänen kunniallisen majesteettinsa edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Sillä kaikki korkiat silmät alennetaan, ja jotka jaloimmat kansoissa ovat, täytyy itsensä notkistaa; sillä Herra on yksinänsä sinä aikana korkein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Sillä Herran Zebaotin päivä käy kaiken koreuden ja korkeuden ylitse, ja kaikkein paisuneiden ylitse, että ne alennettaisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Ja kaikkein korkiain ja korotettuin sedrein ylitse Libanonissa, ja kaikkein tammein ylitse Basanissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Niin myös kaikkein korkiain vuorten ylitse, ja kaikkein korotettuin kukkulain ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Ja jokaisen korkian tornin ylitse, ja kaikkein vahvain muurein ylitse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Niin myös kaikkein haahtein ylitse meressä, ja kaiken kauniin käsialan ylitse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Että kaikki ihmisten korkeus pitää notkistaman hänensä, ja nöyryyttämän itsensä, mitä ihmisessä korkiaa on; ja Herra yksin on silloin korkia oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Ja epäjumalain pitää ratki hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Silloin mennään vuorten rotkoihin ja maan kuoppiin, Herran pelvon tähden, ja hänen kunniallisen majesteettinsa tähden, kuin hän nousee maata peljättämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Silloin pitää jokaisen hopiaiset ja kultaiset epäjumalansa heittämän pois, jotka hän on teettänyt kumartaaksensa, myyräin ja yökköin kuvat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Että he menevät kivien rakoihin ja vuorten rotkoihin, Herran pelvon tähden, ja hänen kunniallisen majesteettinsa tähden, kuin hän nousee maata peljättämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Niin lakatkaat siis ihmisestä, jonka sieramissa henki on; sillä ette tiedä, missä arviossa hän on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Sillä katso, Herra, Herra Zebaot ottaa pois Jerusalemista ja Juudasta kaikkinaisen varan, kaiken leivän varan, ja kaiken veden varan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Väkevät sotamiehet, tuomarit, prophetat, tietäjät ja vanhimmat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Viidenkymmenen päämiehet, ja kunnialliset miehet, neuvonantajat, ja taitavat virkamiehet, ja toimella puhuvaiset miehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Ja tahtoo heille antaa nuorukaiset pääruhtinaiksi, ja lapset heitä hallitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Ja kansan pitää ryöstämän toinen toistansa, ja jokaisen lähimmäistänsä; ja nuoremman pitää ylpiä oleman vanhaa vastaan, ja ylönkatsotun kunniallista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Silloin tarttuu veli veljeensä isänsä huoneesta: sinulla on vaatteet, ole meidän hallitsiamme, auta sinä tätä lankeemusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Mutta silloin hän vannoo ja sanoo: en minä taida parantaa, ei kotonani ole leipää eikä vaatteita: älkäät minun panko kansan hallitsiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Sillä Jerusalem kaatuu, ja Juuda käy ylösalaisin; että heidän kielensä ja tekonsa on Herraa vastaan, niin että he hänen majesteettinsa silmiä vastoin sotivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Heidän kasvoinsa hahmo todistaa heitä vastaan: ja he kerskaavat rikoksistansa, niinkuin Sodoma, ja ei salaa niitä. Voi heidän sielujansa! sillä he itse saattavat päällensä onnettomuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Sanokaat vanhurskaalle, että hänen käy hyvin; sillä hän saa syödä töidensä hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Mutta voi jumalattomia; sillä he ovat pahat, ja heille maksetaan niinkuin he ansaitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Lapset ovat minun kansani vaivaajat, ja vaimot vallitsevat heitä. Minun kansani, sinun lohduttajas häiritsevät sinun, ja turmelevat tien, jota sinun käymän pitäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Mutta Herra seisoo siellä oikeudella, ja on seisahtanut tuomitsemaan kansoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Herra tulee tuomiolle kansansa vanhimpain kanssa ja pääruhtinasten kanssa; sillä te olette turmelleet viinamäen, ja köyhäin ryöstö on teidän huoneessanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Miksi tallaatte kansaani, ja runtelette köyhää? sanoo Herra, Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Ja Herra sanoo: että Zionin tyttäret ovat ylpiät, ja käyvät kenossa kauloin, kiilusilminä, kävelevät ja koriasti astelevat, niinkuin jalat sidotut olisivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'On siis Herra tekevä Zionin tytärten päät rupisiksi, ja Herra on paljastava heidän häpiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Silloin on Herra ottava kenkäin kaunistuksen pois, ja koriasti kudotut rihmat ja soljet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Käädyt, ja rannerenkaat ja seppelit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Kalliit pääliinat, ja polukset, ja päärihmat, ja lemausastiat, ja korvarenkaat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Sormukset ja otsalehdet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Juhlavaatteet, ja kaaput, ja timpit, ja kukkarot,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Peilit ja pienet liinavaatteet, ja lakit ja suvihameet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Ja pitää häijy löyhkä hyvän hajun edestä oleman, ja nuora vyön edestä, ja paljas pää kaharain hiusten edestä, ja ahdas säkki avaran hameen edestä. Nämät kaikki sinun kauneutes siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Sinun miehes kaatuvat miekan kautta, ja sinun väkeväs sodassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Ja heidän porttinsa pitää murehtiman ja valittaman: ja heidän pitää vaikiasti istuman maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Ja seitsemän vaimoa tarttuvat silloin yhteen mieheen, ja sanovat: me tahdomme itseämme elättää ja vaatettaa; anna meitä ainoastaan sinun nimelläs nimitettää, että häväistyksemme otettaisiin meiltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Sinä päivänä on Herran vesa oleva rakas ja kallis; ja maan hedelmä jalo ja kaunis niiden tykönä, jotka Israelista vapahdetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Ja on tapahtuva, että se joka Zionissa jäljellä on, ja se joka Jerusalemissa jäänyt on, pitää pyhäksi kutsuttaman; jokainen kuin kirjoitettu on eläväin seassa Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Silloin Herra pesee Zionin tytärten saastaisuuden, ja viruttaa Jerusalemin verenviat hänestä pois, tuomitsevan ja polttavan hengen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Ja Herra saattaa kaiken Zionin vuoren asumisen ylitse, ja kussa ikänä se koottu on, päivällä pilven ja savun, ja tulen paisteen yöllä palamaan; sillä suojelus pitää oleman kaiken kunnian ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Ja maja pitää oleman päivän varjoksi hellettä vastaan, ja turva ja varjelus rajuilmaa ja sadetta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Minä veisaan ystävästä, ystäväni veisun hänen viinamäestänsä. Ystävälläni on viinamäki lihavassa paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Ja hän aitasi sen ympärinsä, ja perkasi kivet pois, ja istutti parhaat viinapuut, ja rakensi myös siihen tornin, ja pani sinne viinakuurnan, ja odotti sen viinamarjoja kantavan; vaan se kantoi pahoja marjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Te Jerusalemin asujat ja Juudan miehet, tuomitkaat siis nyt minun ja viinamäkeni välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Mitä olis enempi viinamäelleni tekemistä, jota en minä hänessä tehnyt ole? Miksi hän kantoi pahoja marjoja, kuin minä odotin hänen viinamarjoja kantavan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Ja nyt minä tahdon teille ilmoittaa, mitä minä tahdon viinamäelleni tehdä: hänen aitansa pitää otettaman pois, että hänen pitää autiona oleman, ja hänen muurinsa pitää särjettämän, että hän tallattaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Minä tahdon sen saattaa autioksi, ettei kenkään pidä hänessä leikkaaman eli kaivaman, vaan ohdakkeita ja orjantappuroita pitää hänessä kasvaman: ja tahdon pilviä kieltää satamasta hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Mutta Herran Zebaotin viinamäki on Israelin huone, ja Juudan miehet hänen suloinen istuttamansa. Hän odottaa oikeutta, ja katso, ei ole muuta kuin väkivaltaa, vanhurskautta, niin on sula valitus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Voi niitä, jotka yhden huoneen toisen tykö vetävät, ja yhden pellon toisen tykö saattavat, siihen asti ettei enää siaa ole, asuaksenne yksinänne maan päällä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Nämä ovat (sanoo) Herra Zebaot minun korvilleni tulleet: mitämaks, ellei ne monet huoneet tule kylmille, ja ne suuret ja kauniit jää ilman asujia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Sillä kymmenen viinamäen sarkaa pitää vaivoin yhden batin antaman; ja gomer siemeniä tekee ainoastaan ephan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Voi niitä, jotka varhain huomeneltain ylhäällä ovat, juopumusta noutelemaan, ja istuvat hamaan yöhön asti, että he viinasta palavaksi tulisivat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Joilla ovat kanteleet, harput, rummut, huilut, ja viinaa heidän pidoissansa; ja ei katso Herran tekoa, eikä tottele hänen käsialaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Sentähden pitää minun kansani vietämän vankeuteen, ettei heillä ole ymmärrystä; ja hänen kunniallistensa täytyy nälkää kärsiä, ja heidän yhteinen kansansa kuivua janoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Sitä varten on helvetti sielunsa lavialta avannut, ja hänen kitansa on ammollansa ilman määrää, mennä sinne alas sekä heidän kunniallisensa että yhteisen kansansa, sekä heidän rikkaansa että riemullisensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Että jokainen itsensä notkistais ja kukin nöyryytettäisiin; ja koreiden silmät myös nöyryytetyksi tulisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Mutta Herra Zebaot pitää tuomiossa ylistettämän, ja pyhä Jumala pitää vanhurskaudessa pyhitettävän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Silloin pitää lampaat tavallansa kaittaman, ja muukalaiset pitää itsensä elättämän lihavain aukiudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Voi niitä, jotka itsensä sitovat valheen nuoralla yhteen vääryyttä tekemään, ja niinkuin ratasten köydellä syntiä tekemään!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Ja sanovat: anna hänen tekonsa rientää ja pian tulla, sitä nähdäksemme: lähestyköön ja tulkoon Israelin pyhän aivoitus, että me sen tietäisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Voi niitä, jotka pahan hyväksi ja hyvän pahaksi sanovat; jotka pimeydestä valkeuden, ja valkeudesta pimeyden tekevät, jotka karvaasta makian, ja makiasta karvaan tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Voi niitä, jotka viisaat olevinansa ovat, ja itsensä toimellisina pitävät!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Voi niitä, jotka jalot ovat viinaa juomaan, ja juomassa kilvoittelevat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Jotka jumalattoman lahjain tähden vanhurskauttavat, ja kääntävät vanhurskasten oikeuden pois heiltä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Sentähden niinkuin tulen hehku korren kuluttaa, ja liekki sivaltaa akanat pois: aivan niin pitää heidän juurensa mätänemän, ja heidän vesansa hajooman pois niinkuin tomu; sillä he katsovat Herran Zebaotin lain ylön, ja pilkkaavat Israelin pyhän sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Sentähden Herran viha julmistuu kansansa päälle, ja hän ojentaa kätensä heidän päällensä, ja lyö heitä, niin että vuoret vapisevat ja heidän ruumiinsa on niinkuin loka kadulla. Ja kaikissa näissä ei hänen vihansa lakkaa, vaan hänen kätensä on vielä ojennettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Sillä hän nostaa lipun ylös kaukana pakanain seassa, ja viheltää niille maan ääristä: ja katso, he tulevat äkisti ja nopiasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Ei ole kenkään heistä väsynyt eli heikko, eikä kenkään torku eli makaa; ei myös päästä kenkään vyötä lanteestansa, eikä kenenkään kengänrihmoja rikota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Sillä heidän nuolensa ovat terävät, ja kaikki heidän joutsensa jännitetyt; heidän orittensa kaviot ovat niinkuin limsiä, ja heidän ratastensa pyörät niinkuin tuulispää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'He kiljuvat niinkuin jalopeurat, ja kiljuvat niinkuin nuoret jalopeurat. He kilistelevät ja tempaavat saaliin, ja omistavat sen, ettei kenkään sitä saa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Ja silloin pauhataan heidän ylitsensä niinkuin meri pauhaa. Koska silloin katsotaan maan päälle, katso, niin on pimeys ahdistuksesta, ja ei valkeus paista silleen heidän ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Sinä vuonna, jona kuningas Ussia kuoli, näin minä Herran istuvan korkialla ja korotetulla istuimella, ja hänen vaatteensa liepeet täyttivät templin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Seraphit seisoivat häntä ylempänä, ja kullakin oli kuusi siipeä: kahdella he peittivät kasvonsa, kahdella jalkansa, ja kahdella he lensivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Ne huusivat toinen toisellensa ja sanoivat: Pyhä, pyhä, pyhä, Herra Zebaot: kaikki maa on täynnä hänen kunniaansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Niin että pihtipielet vapisivat heidän huutonsa äänestä, ja huone täytettiin savulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Niin minä sanoin: voi minuani! minä hukun, sillä minulla on saastaiset huulet, ja asun sen kansan seassa, jolla on saastaiset huulet; sillä minun silmäni ovat nähneet kuninkaan, Herran Zebaotin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Niin lensi yksi Seraphimeista minun tyköni, jolla oli kädessä tulinen hiili, jonka hän otti hohtimilla alttarilta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Ja rupesi minun suuhuni, ja sanoi: katso, tällä olen minä ruvennut huuliis, että sinun pahat tekos otettaisiin sinulta pois, ja sinun rikokses olis sovitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Ja minä kuulin Herran äänen, että hän sanoi: kenenkä minä lähetän? kuka tahtoo olla meidän sanansaattajamme? Mutta minä sanoin: tässä minä olen, lähetä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Ja hän sanoi: mene ja sano tälle kansalle, kuulten kuulkaat, ja älkäät ymmärtäkö, nähden nähkäät, ja älkäät tähtäkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Paaduta tämän kansan sydän, ja anna heidän korvansa paksuksi tulla, ja sokaise heidän silmänsä, ettei he näkisi silmillänsä, eikä kuulisi korvillansa, eli myös ymmärtäisi sydämellänsä, eli kääntäisi itsiänsä ja parannetuksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Mutta minä sanoin: Herra, kuinka kauvan? Hän sanoi: siihenasti kuin kaupungit tulevat kylmille ja ilman asujia, ja huoneet ilman väetä, ja maa on peräti autiona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Sillä Herra ajaa väen kauvas, niin että maa tulee peräti hyljätyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Ja ehkä kymmenes osa siihen vielä jää, niin sekin taas hävitetään; kuitenkin niinkuin tammelle ja tuomelle jää kanto, vaikka heidän lehtensä varistetaan, niin pitää myös pyhällä siemenellä kanto oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Sitte tapahtui Ahaksen Jotamin pojan, Ussian pojan, Juudan kuninkaan aikana, että Retsin Syrian kuningas, ja Peka Remalian poika, Israelin kuningas, vaelsivat Jerusalemiin, sotimaan sitä vastaan; mutta ei he taitaneet sitä voittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Silloin sanottiin Davidin huoneelle: Syrialaiset luottavat Ephraimiin. Silloin vapisi hänen sydämensä ja hänen kansansa sydän, niinkuin puut vapisevat metsässä tuulesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Mutta Herra puhui Jesaialle: mene nyt Ahasta vastaan, sinä ja poikas SearJasub, ylimmäisen vesilammikon kanavan päähän, tiellä vanuttajakedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Ja sano hänelle: kavahda ja pysy alallas, älä pelkää, älköön myös sydämes vapisko näitä kahta suitsevan kekäleen päätä, Retsinin ja Syrialaisten, ja Remalian pojan vihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Että Syrialaiset ovat pitäneet pahoja juonia sinua vastaan, niin myös Ephraim ja Remalian poika, ja sanovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Me tahdomme mennä ylös Juudaan, ja herättää häntä, ja jakaa sen keskenämme, ja tehdä siihen Tabealin pojan kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Sillä näin sanoo Herra, Herra: ei sen pidä pysymän, eikä näin oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Vaan niinkuin Damasku on Syrian pää, niin pitää Retsinin oleman Damaskun pään. Ja viiden ajastajan perästä seitsemättäkymmentä, pitää Ephraimin tuleman perikatoon, niin ettei heidän enään pidä kansana oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Ja niinkuin Samaria on Ephraimin pää, niin pitää Remalian poika oleman Samarian pään. Jollette usko, niin ette vahvistu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Ja Herra puhui taas Ahakselle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Pyydä sinulles merkkiä Herralta sinun Jumalaltas, taikka alhaalle syvyyteen, eli ylhäälle korkeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Niin Ahas sanoi: en ano ja en tahdo Herraa kiusata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Niin hän sanoi: kuulkaat siis te Davidin huone: vähäkö se teille on, että te ihmisiä vastoin teette, mutta myös teette minun Jumalaani vastoin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Sentähden antaa itse Herra teille merkin: katso, neitsy siittää ja synnyttää pojan, sen nimi pitää kutsuttaman Immanuel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Voita ja hunajaa hän syö, tietääksensä hyljätä pahaa ja valita hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Sillä ennenkuin poikainen oppii hylkäämään pahaa ja valitsemaan hyvää, pitää se maa, jotas kauhistut, kahdelta kuninkaalta hyljättämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Mutta Herra antaa sinun, sinun kansas ja isäs huoneen päälle tulla, Assyrian kuninkaan kautta, ne päivät, jotka ei sitte tulleet ole, kuin Ephraim erkani Juudasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Ja tapahtuu, että Herra viheltää sinä päivänä kärpäsiä Egyptin virtain äärestä, ja kimalaisia Assurin maalta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Että he tulevat ja sioittavat kaikki tyynni itsensä hävinneihin laaksoihin, ja kiven rakoihin, ja kaikkiin mättäisiin ja pensaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Silloin Herra ajelee pään ja karvat jaloista, ja ottaa pois parran palkatulla partaveitsellä, niiden kautta, jotka sillä puolella virtaa ovat, Assyrian kuninkaan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Siihen aikaan pitää yhden miehen yhtä lehmää ja kahta lammasta kaitseman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Ja saaman niin paljon rieskaa, että hän saa syödä voita; sillä se joka jää maahan, saa voita ja hunajaa syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Sillä siihen aikaan tapahtuu, että kussa nyt on tuhannen viinapuuta, jotka maksavat tuhannen hopiapenninkiä, siellä pitää orjantappurat ja ohdakkeet oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Ja sinne mennään nuolella ja joutsella; sillä koko maassa pitää oleman orjantappurat ja ohdakkeet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Niin ettei taideta tulla kaikkiin niihin mäkiin, joita lapiolla kaivetaan, orjantappurain, mätästen ja ohdakkeiden tähden; vaan härjät annetaan siinä käydä, ja lampaat sitä tallata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Ja Herra sanoi minulle: ota suuri kirja etees, ja kirjoita siihen ihmisen kirjoituksella: ryöstä nopiasti, riennä saaliille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Ja minä otin tyköni uskolliset todistajat: papin Urijan, ja Sakarian Jeberekjan pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Ja menin prophetissan tykö, se tuli raskaaksi ja synnytti pojan; ja Herra sanoi minulle: nimitä se: ryöstä pian, ja riennä jakoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Sillä ennenkuin poikainen taitaa sanoa: isäni, äitini, viedään Damaskun tavarat ja Samarian saalis pois Assyrian kuninkaan edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Ja Herra puhui vielä minun kanssani ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Että tämä kansa hylkää Siloan veden, joka hiljaksensa juoksee, ja turvaa Retsiniin ja Remalian poikaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Katso, niin Herra antaa tulla hänen päällensä paljon ja väkevän virtaveden, Assyrian kuninkaan, ja kaiken hänen kunniansa, että se nousee kaikkein parrastensa yli, ja käypi kaikkein rantainsa yli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Ja käypi Juudan lävitse, tulvaa ja nousee, siihenasti kuin se ulottuu kaulaan asti; ja levittää siipensä, niin että ne täyttävät sinun maas, o Immanuel, niin leviä kuin se on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Kokoontukaat kansat, ja paetkaat kuitenkin; kuulkaat kaikki, jotka olette kaukaisissa maakunnissa: hankkikaat sotaan ja paetkaat kuitenkin, hankkikaat ja paetkaat kuitenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Päättäkäät neuvo, ja ei se miksikään tule; puhukaat keskenänne, ja ei sekään seiso, sillä tässä on Immanuel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Sillä näin sanoi Herra minulle, kuin hän käteeni rupesi, ja neuvoi minua, etten minä vaeltaisi tämän kansan tiellä, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Älkäät sanoko liitoksi, mitä tämä kansa liitoksi sanoo: älkäät te peljätkö, niinkuin he tekevät, älkäät myös vapisko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Vaan pyhittäkäät Herra Zebaot; ja hän olkoon teidän pelkonne, hän olkoon teidän vapistuksenne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Niin hän on pyhitys; mutta loukkauskivi ja kompastuskallio kahdelle Israelin huoneelle, paulaksi ja ansaksi Jerusalemin asuville,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Niin että moni heistä loukkaa itsensä, ja lankeevat, särjetään, kiedotaan ja vangitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Sido todistus kiinni, lukitse laki minun opetuslapsissani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Sillä minä toivon Herraan, joka kasvonsa Jakobin huoneelta kätkenyt on; mutta minä odotan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Katso, tässä minä olen, ja ne lapset, jotka Herra minulle antanut on merkiksi ja ihmeeksi Israelissa Herralta Zebaotilta, joka Zionin vuorella asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Kuin siis he teille sanovat: kysykäät noidilta ja tietäjiltä, jotka kuiskuttelevat ja tutkivat, (niin sanokaat:) eikö kansan pidä Jumalaltansa kysymän? (eikö ole parempi kysyä) eläviltä kuin kuolleilta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, '(Ja pikemmin) lain jälkeen ja todistuksen? Ellei he tämän sanan jälkeen sano, niin ei heidän pidä aamuruskoa saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Vaan heidän pitää kävelemän maakunnassa vaivattuina ja nälkäisinä; mutta kuin he nälkää kärsivät, niin he vihastuvat ja kiroilevat kuningastansa ja Jumalaansa, ja katsovat ylöspäin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Ja katselevat maata, vaan ei muuta mitään löydä, kuin murheet ja pimeydet; sillä he ovat pimitetyt ahdistuksessa, ja eksyvät pimeydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Sillä ei ole sillä (maakunnalla) yhtään pääsinpäivää, koska hän ahdistuksessa on; niinkuin entiseen aikaan Sebulonin ja Naphtalin maalle lievitys tapahtui, ja tulivat viimein kunnioitetuksi; niin myös ne meritien vieressä, tällä puolella Jordanin pakanain Galileassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Kansa, joka pimeydessä vaelsi, näki suuren valkeuden, ja jotka asuivat kuoleman varjon maassa, niiden ylitse se kirkkaasti paistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Sinä lisäät kansaa, ja lisäät hänelle iloa; sinun edessäs iloitaan, niinkuin elonaikana iloitaan, niinkuin saaliin jaossa iloitaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Sillä sinä olet heidän kuormansa ikeen, heidän olkainsa vitsan, ja heidän vaatiansa sauvan särkenyt, niinkuin Midianin aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Sillä kaikki sota ja meteli, ja veriset vaatteet pitää poltettaman ja tulella kulutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Sillä meille on lapsi syntynyt, ja poika on meille annettu, jonka hartioilla herraus on; ja hänen nimensä kutsutaan Ihmeellinen, Neuvonantaja, Väkevä Jumala, Ijankaikkinen Isä, Rauhan päämies:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Että hänen herrautensa pitää suureksi tuleman, ja ei rauhalla loppua, Davidin istuimelle ja hänen valtakunnallensa, valmistamaan sitä ja vahvistamaan tuomiolla ja vanhurskaudella: hamasta nyt niin ijankaikkiseen on Herran Jumalan Zebaotin kiivaus tämän tekevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Herra on lähettänyt sanan Jakobissa, ja se on langennut Israelissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Että kaikki Ephraimin kansa ja Samarian asuvaiset pitää sen tietää saaman, jotka ylpeydessä ja korialla mielellä sanovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Tiilikivet ovat pudonneet, mutta me tahdomme sen rakentaa vuojonkivillä jälleen: Muulbärin puut ovat hakatut maahan, mutta me panemme siaan sedripuita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Sillä Herra tahtoo korottaa Retsinin sotaväen heitä vastaan, ja heidän vihollisensa nivoa yhteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Syrialaiset eteen ja Philistealaiset taa, että he söivät Israelin täydellä suulla. Näissä kaikissa ei lakkaa vielä hänen vihansa, vaan hänen kätensä on vielä ojennettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Ei myös kansa käännä itseinsä hänen tykönsä, joka heitä lyö, eikä kysy Herraa Zebaotia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Sentähden karsii Herra Israelilta pois, yhtenä päivänä, pään ja hännän, oksat ja kannon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Vanhat kunnialliset ihmiset ovat pää; mutta prophetat, jotka opettavat väärin, ovat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Sillä tämän kansan johdattajat ovat pettäjät, ja ne, jotka sallivat itsensä johdattaa, ovat kadotetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Sentähden ei Herra taida iloita heidän nuorista miehistänsä, eikä armahda heidän orpolapsiansa ja leskiänsä; sillä he ovat kaikki ulkokullatut ja pahat, ja jokaisen suu puhuu hulluutta; näissä kaikissa ei lakkaa vielä hänen vihansa, vaan hänen kätensä on vielä ojennettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Sillä jumalatoin meno on sytytetty niinkuin tuli, ja kuluttaa orjantappurat ja ohdakkeet; joka palaa niinkuin paksussa metsässä, ja nostaa savun korkialle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Sillä maa on pimennyt Herran Zebaotin vihasta; niin että kansa on niinkuin tulen ruoka, ja ei yksikään armaitse toista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Jos he ryöstävät oikialla puolella, niin he nälkää näkevät; jos he syövät vasemmalla puolella, niin ei he tule ravituksi: jokainen syö käsivartensa lihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manasse Ephraimia, Ephraim Manassea, ja ne molemmat yhdestä puolesta Juudaa vastaan. Ei vielä näissä kaikissa hänen vihansa asetu, vaan hänen kätensä on vielä ojennettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Voi kirjanoppineita, jotka väärän lain tekevät ja väärän tuomion kirjoittavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Että he vääntelisivät köyhän asian, ja tekisivät väkivaltaa raadolliselle oikeudessa, minun kansassani; niin että lesket ovat heidän saaliinsa, ja orpoja he raatelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Mitä te tahdotte tehdä etsikkopäivänä, ja hävityksessä, joka kaukaa tulee? kenen tykö te pakenette apua saamaan? ja kuhunka te tahdotte panna teidän kunnianne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Ettette vangittuin kanssa taivutettaisi, ja lyötyin seassa lankeaisi; näissä kaikissa ei ole hänen vihansa asetettu, vaan hänen kätensä on vielä nyt ojennettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Voi Assur, joka minun vihani vitsa on; joiden käsissä minun julmuuteni sauva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Minä tahdon lähettää hänen ulkokullattua kansaa vastaan, ja antaa hänelle käskyn vihani kansaa vastaan, sitä täydellisesti ryöstämään, ja saalista jakamaan, ja tallaamaan sitä niinkuin lokaa kujilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Vaikka ei hän sitä niin luule, eikä hänen sydämensä niin ajattele; vaan hänen sydämensä on turmelemaan ja hävittämään monta kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Sillä hän sanoo: eikö kaikki minun pääruhtinaani ole kuninkaat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Eikö Kalno ole niinkuin Karkemis? Eikö Hamat ole niinkuin Arpad? Eikö Samaria ole niinkuin Damasku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Niinkuin minun käteni on löytänyt epäjumalain valtakunnat, niin myös heidän epäjumalansa, jotka Jerusalemissa ja Samariassa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Eikö minun tule tehdä Jerusalemille, ja hänen epäjumalillensa, niinkuin minä Samariallekin ja hänen epäjumalillensa tein?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Mutta koska Herra on kaikki tekonsa Zionin vuorella ja Jerusalemissa toimittanut, niin minä tahdon etsiä Assurin kuninkaan ylpeän sydämen hedelmää, ja hänen ylpeiden silmäinsä koreutta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Että hän sanoo: minä olen sen toimittanut minun käteni voimalla ja minun taitoni kautta; sillä minä olen taitava: minä olen kansain rajat siirtänyt, ja heidän tavaransa ryöstänyt, ja niinkuin voimallinen lyönyt heidän asujansa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Ja minun käteni on löytänyt kansain tavaran niinkuin linnunpesän, niin että minä olen kaiken maan koonnut niinkuin hyljätyt munat kootaan, kussa ei yhtään ole, joka siipeänsä liikuttaa, nokkansa avaa, eli kirkaisee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Taitaako kirves kerskata sitä vastaan, joka hänellä hakkaa, eli saha taistella sen kanssa, joka häntä vetää? Se olis niinkuin sauva tahtois liikuttaa sitä, joka sen kantaa, ja sauva nostais itsensä niinkuin ei se puu oliskaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Sentähden on Herra, Herra Zebaot, lähettävä laihuuden hänen lihavainsa sekaan, ja sytyttävä hänen kunniansa palamaan kuin tulipalon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Ja Israelin valkeus on tuleva tuleksi, ja hänen pyhänsä liekiksi, ja pitää palaman, ja kuluttaman hänen orjantappuransa ja ohdakkeensa yhtenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Ja hänen metsänsä ja ketonsa kunnia pitää tyhjään raukeneman, sekä sielu että ruumis, ja pitää tuleman niinkuin koska lipunkantaja nääntyy;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Niin että hänen metsänsä jääneet puut lukea taidetaan, ja että lapsikin ne pyältää taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Silloin ei pidä jääneet Israelissa, ja ne jotka tallella ovat Jakobin huoneesta, enää turvaaman häneen, joka heitä lyö; vaan pitää todella turvaaman Herraan Israelin pyhään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Jääneet pitää kääntymän, Jakobin jääneet, väkevän Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Sillä jos sinun kansas, o Israel, on niinkuin hiekka meressä, niin kuitenkin heidän jääneensä kääntyvät; sillä estetty hävitys pitää vuotaman yltäkylläisen vanhurskauden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Että Herra, Herra Zebaot, antaa tulla aivotun hävityksen koko maahan, ja hallitsee sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Sanoo siis Herra, Herra Zebaot: älä pelkää kansani, joka Zionissa asut, Assuria. Hän lyö sinua vitsalla, ja nostaa sauvansa sinua vastaan niinkuin Egyptissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Sillä aivan vähän ajan perästä pitää armottomuus ja minun vihani täytettämän heidän kadotukseksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Silloin on Herra Zebaot nostava ruoskan heidän päällensä, niinkuin Midianin tapossa Orebin kalliolla, ja on ylentävä sauvansa meren yli, niinkuin Egyptissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Silloin pitää hänen kuormansa pakeneman pois sinun hartioiltas, ja hänen ikeensä sinun kaulastas, sillä ikeen pitää pirstaantuman lihavuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Hän tulee Ajatiin, hän vaeltaa Migronin lävitse, hän katselee aseensa Mikmaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'He vaeltavat luotuspaikan ylitse; he pitävät yösiaa Gebaassa; Raama peljästyy, Saulin Gibea pakenee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Sinä tytär Gallim, huuda vahvasti: ota vaari Laiksesta; sinä raadollinen Anatot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena menee pois tieltä, Gebimin asuvaiset juoksevat matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Ollaan vielä päiväkunta Nobissa; niin hän on kääntävä kätensä Zionin tyttären vuoreen päin, ja Jerusalemin korkeuden puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Katso, Herra, Herra Zebaot, on hakkaava oksat väellä, ja lyhentävä sitä korkiaa; ja korkiat pitää alennettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Ja tihkiä metsä pitää raudalla maahan hakattaman; ja Libanon pitää voimallisen kautta kaatuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Ja vitsa on putkahtava Isain kannosta, ja vesa on hedelmöitsevä hänen juurestansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Jonka päällä Herran henki lepää, viisauden ja ymmärryksen henki, neuvon ja väkevyyden henki, taidon ja Herran pelvon henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Ja hänen haistamisensa on Herran pelvossa oleva: ei hän tuomitse silmäinsä näön jälkeen, eikä nuhtele korvainsa kuulon jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Vaan hän tuomitsee köyhiä vanhurskaudessa, ja nuhtelee maan raadollisia oikeudella, ja lyö maata suunsa sauvalla, ja huultensa hengellä tappaa hän jumalattoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Vanhurskaus on hänen kupeinsa vyö, ja usko hänen munaskuinsa side.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Sudet asuvat lammasten seassa, ja pardi makaa vohlain kanssa; vasikka myös ja nuori jalopeura, ja syötinnaudat käyvät yhdessä, ja vähä poikainen kaitsee heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Niin myös lehmät ja karhut käyvät yhdellä laitumella, ja heidän vasikkansa myös ynnä makaavat; jalopeura syö olkia niinkuin härkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Ja imevä lapsi ihastuu vaskikäärmeen lävestä; ja vieroitettu lapsi pistää kätensä basiliskin luolaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Ei kenkään vahingoitse eikä turmele kaikella pyhyyteni vuorella; sillä maa on täynnä Herran tuntoa, niinkuin meri vedellä peitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Ja tapahtuu sinä päivänä, että Isain juurta, joka seisoo kansan lippuna, pitää pakanain etsimän; ja hänen leponsa on kunniallinen oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Ja tapahtuu sinä päivänä, että Herra vielä toisen kerran kokottaa kätensä ostamaan kansansa tähteitä, jotka jääneet ovat, Assyriasta, Egyptistä, Patroksesta, Etiopista, Elamista, Sinearista, Hamatista ja meren luodoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Ja hän nostaa lipun pakanoissa, tuodaksensa Israelin pakolaiset, ja myös kootaksensa Juudan hajoitetut, neljästä maan äärestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Ja kiivaus Ephraimia vastaan pitää lakkaaman, ja Juudan viholliset pitää peräti katooman, niin ettei Ephraimin pidä kadehtiman Juudaa, ja Juudan ei pidä ahdistaman Ephraimia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Mutta heidän pitää karkaaman Philistealaisten niskaan, länteen päin, ja ryöstämän idän puolella asuvaiset; Edom ja Moab pitää heidän käsiinsä lankeeman, ja Ammonin pojat pitää heille kuuliaiset oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Ja Herra on kiroova Egyptin meren lahden, ja liikuttava kätensä virtaa vastaan, tuulensa väkevyydessä; ja hän lyö sen seitsemäksi ojaksi, niin että kengässä käydään ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Ja rata on oleva hänen jääneelle kansallensa, joka Assyrialaisilta jätetty oli; niinkuin Israelille silloin tapahtui, kuin hän Egyptistä läksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Silloin pitää sinun sanoman: minä kiitän sinua, Herra, ettäs vihainen olet ollut minun päälleni; mutta sinun vihas on palannut, ja sinä lohdutat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Katso, Jumala on minun autuuteni, minä olen turvassa ja en mitään pelkää; sillä Herra, Herra on minun väkevyyteni, ja minun virteni, ja hän on minun autuuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Teidän pitää ammentaman vettä ilolla autuuden lähteistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Ja silloin te sanotte: kiittäkäät Herraa, ja saarnatkaat hänen nimeänsä, julistakaat kansoissa hänen tekojansa, muistakaat kuinka korkia hänen nimensä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Veisatkaat kiitosta Herralle, sillä hän on voimallisesti itsensä asettanut; se olkoon tiettävä kaikessa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Korota äänes ja veisaa, sinä Zionin asuvainen, sillä Israelin pyhä on suuri sinun keskelläs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Babelin kuorma, jonka Jesaia Amotsin poika näki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Nostakaat lippu korkialle vuorelle, huutakaat kovin heitä vastaan; nostakaat kätenne ylös, antakaat pääruhtinasten mennä porteista sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Minä olen käskenyt pyhitetyilleni, ja kutsunut väkeväni minun vihaani, jotka iloitsevat minun kunniassani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Siellä on suuren joukon huuto vuorilla, niinkuin paljon kansan huuto, niinkuin humaus pakanain kootusta valtakunnasta: Herra Zebaot varustaa joukon sotaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Jotka kaukaiselta maalta tulevat, taivaan ääristä: tosin itse Herra vihansa joukolla, hävittämään koko maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Valittakaat, että Herran päivän on juuri läsnä; hän tulee niinkuin hävitys Kaikkivaltiaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Sentähden pitää kaikki kädet lankeeman maahan, ja kaikki ihmisten sydämet vaipuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Hämmästys, tuska ja kipu pitää tuleman heidän päällensä; heillä pitää oleman tuska niinkuin lapsen synnyttäväisellä: yhden pitää toista kauhistuman, heidän kasvonsa pitää oleman punaisen niinkuin tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Sillä katso, Herran päivä tulee kauhiasti vihaisna ja julmana, hävittämään maata, ja siitä teloittamaan syntisiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Ettei tähdet taivaassa, ja hänen kointähtensä paista kirkkaasti; aurinko ylenee synkiästi, ja kuu paistaa pimiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Minä tahdon rangaista maan piirin hänen pahuutensa tähden ja jumalattomat heidän vikainsa tähden, ja tahdon lopettaa koreiden ylpeyden, ja nöyryyttää jaloin ynseyden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Niin että mies pitää oleman kalliimpi puhdasta kultaa, ja ihminen enempi kunnioitettu kuin kappale Ophirin kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Sentähden minä liikutan taivaan, niin että maan pitää vapiseman paikastansa Herran Zebaotin vihan kautta, ja hänen julman vihansa päivän kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Ja hänen pitää oleman niinkuin pois ajetun metsävuohen, ja niinkuin lauman ilman paimenta; niin että jokaisen pitää palajaman kansansa tykö, ja jokaisen pakeneman maallensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Että jokainen, joka löydetään, pitää pistettämän lävitse, ja jokainen, joka siellä läsnä on, pitää miekalla lankeeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Pitää myös heidän lapsensa heidän silmäinsä edessä tapettaman, heidän huoneensa ryöstettämän, ja heidän emäntänsä häväistämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Katso, minä herätän Mediläiset heidän päällensä, jotka ei etsi hopiaa, eikä kysy kultaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Vaan ampuvat nuoria miehiä kuoliaaksi joutsilla, ja ei armahda äidin kohdun hedelmää, eikä säästä lastakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Näin pitää Babeli, se kaikkein kaunein valtakuntain seassa, Kaldealaisten koreus, tuleman; niinkuin Jumala kukisti Sodoman ja Gomorran;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Niin ettei siellä enää pidä asuttaman ijankaikkisesti, eikä siellä asuntoa pidettämän suvusta sukuun. Niin ettei myös Arabialaisten sinne pidä yhtään majaa tekemän, eikä paimenten pidä siellä lounalla makaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Vaan metsän pedot pitää siellä makaaman, ja heidän huoneensa oleman täynnä kauheita petoja, ja yököt pitää siellä asuman, ja siellä liekkiöt hyppelemän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Ja tarhapöllöt laulaman hänen kaunistetuissa huoneissansa, ja lohikäärmeet iloisissa linnoissa. Ja hänen aikansa on pian tuleva, ja hänen päivänsä ei pidä viipymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Sillä Herra armahtaa Jakobia ja valitsee vielä nyt Israelin, ja panee heitä heidän maahansa; ja muukalaisten pitää antaman itsensä heidän allensa, ja suostuman Jakobin huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Ja kansat ottavat heidät, ja vievät heitä heidän paikkaansa, ja Israelin huone on omistava heitä Herran maassa palvelioiksi ja piioiksi; ja pitää heitä vankina pitämän, joilta he olivat vangitut, ja niin he vallitsevat vaivaajiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Ja pitää tapahtuman siihen aikaan kuin Herra on antava sinulle levon sinun surustas ja vaivastas, ja siitä kovasta orjuudesta, jossas orjana pidettiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Että sinun pitää puhuman näin Babelin kuningasta vastaan ja sanoman: kuinka vaivaaja on tullut perikatoon, ja veron laskemus on loppuun joutunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Herra on taittanut jumalattomain sauvan, vallitsiain vitsan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Joka löi kansaa julmuudessa ilman lakkaamata, ja vallitsi pakanoita ankaruudella, ja vaivasi heitä ilman laupiutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Nyt on kuitenkin koko maailmalla lepo, ja on alallansa ja riemuitsee ilossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Ja hongat myös riemuitsevat sinusta, ja sedrit Libanonissa, (ja sanovat): ettäs makaat, niin ei nouse yhtään, joka meitä maahan hakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Helvetti vapisi alhaalla sinua, sinun tulemisestas; se herättää sinulle kuolleet, kaiken maailman päämiehet, ja käski kaikkia pakanain kuninkaita nousta heidän istuimiltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Kaikkein pitää vastaaman ja sanoman sinulle: sinä olet myös lyöty niinkuin mekin, ja sinun kätees käy niinkuin meidänkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Sinun ylpeytes on joutunut helvettiin alas, sinun kanteleis kilisemisellä; koin pitää oleman sinun vuotees, ja madot sinun peittees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Kuinka sinä kaunis kointähti olet pudonnut taivaasta? kuinkas olet maan päälle langennut, joka pakanat teit heikoksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Vaan sinä ajattelit sydämessäs: minä astun taivaaseen, ja korotan istuimeni Jumalan tähtien ylitse: minä istutan itseni todistuksen vuorelle, sille puolelle pohjaa päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Minä tahdon vaeltaa korkeiden pilvien päällä, ja olla kaikkein Korkeimman vertainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Kuitenkin sinä sysätään helvettiin, luolan puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Joka sinun näkee, hänen pitää katseleman sinua ja katsoman päälles, (ja sanoman): onko tämä se mies, joka maailman saatti värisemään, ja valtakunnat vapisemaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Joka maan piirin autioksi saatti, ja kukisti siellä kaupungit, ja ei päästänyt vankejansa kotia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Kaikki pakanain kuninkaat makaavat kuitenkin kunnialla, jokainen huoneessansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Mutta sinä olet hyljätty haudastas niinkuin kauhia vesa, niinkuin lyötyin vaatteet, jotka miekalla ovat kuoliaaksi pistetyt, jotka menevät alas kivikuoppaan, niinkuin tallattu raato.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Ei sinua pidä niin haudattaman kuin ne; sillä sinä olet hävittänyt maas, ja tappanut kansas; sentähden ei pidä ikänä muistettaman ilkiäin siementä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Valmistakaat teurastamaan hänen lapsiansa, heidän isäinsä pahain tekoin tähden, ettei he nousisi eli perisi maata, eikä täyttäisi maan piiriä kaupungeilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Ja minä tulen heidän päällensä, sanoo Herra Zebaot, ja hävitän Babelissa hänen nimensä, hänen jääneensä, sikiänsä ja sukukuntansa, sanoo Herra,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Ja teen hänen tarhapöllöin perinnöksi ja vesikuljuksi; ja käväisen hänen hävityksen luudalla, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Herra Zebaot on vannonut ja sanonut: mitämaks, että sen pitää niin tapahtuman kuin minä ajattelen, ja pitää niin pysymän kuin minun mielessäni on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Että Assur telataan minun maassani, ja minä tallaan hänen minun vuorellani; että hänen ikeensä heiltä otettaisiin, ja hänen kuormansa heidän kaulastansa tulis pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Nämät ovat hänen juonensa, joita hän pitää kaikissa maan paikoissa; ja se on se kohotettu käsi kaikkein pakanain ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Sillä Herra Zebaot on sen päättänyt, kuka tahtoo tyhjäksi tehdä? ja hänen kätensä on kokotettu, kuka voi sen vääntää pois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Sinä vuonna kuin kuningas Ahas kuoli, nähtiin tämä kuorma:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Sinä Philistea, älä niin kovin riemuitse, että se vitsa, joka sinua löi, on taitettu; sillä käärmeen juuresta on tuleva basiliski, ja hänen hedelmänsä on tulinen lentävä kärme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Sillä tarvitsevaisten esikoiset pitää korjaaman itsiänsä, ja köyhät suruttomasti lepäämän; mutta sinun juures tapan minä nälällä, ja suretan sinun jäänees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Surkuttele sinuas, portti, huuda sinä kaupunki, koko Philistealaisten maa on marras! sillä pohjoisesta tulee savu, ja ei yksikään ole majassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Ja mitä pakanain sanansaattajia vastataan? nimittäin, että Herra on perustanut Zionin, ja siellä pitää hänen kansansa raadollisilla turva oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Tämä on Moabin kuorma: yöllä tulee hävitys Arin Moabissa, se on jo pois; yöllä tulee hävitys Kirin Moabissa, se on jo pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Bat ja Dibon menevät ylös kukkulalle itkemään, ja Moab suremaan Neboa ja Metbaa; kaikki päät ovat ajellut, koko parta on leikattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Kaduillansa käyvät he kiedottuina säkkeihin: kattoinsa päällä ja kaduilla he kaikki itsiänsä surkuttelevat ja tulevat itkein alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesboni ja Elale huutavat, niin että heidän äänensä kuuluu hamaan Jahtsaan; sentähden asettenkantajat surkuttelevat itsiänsä Moabissa, että heidän sielullensa käy nurin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Minun sydämeni huutaa Moabia, heidän kulkiansa pakenevat aina Zoariin, kolmikarjaista lehmää; sillä he menevät Luhitin paltaan ja itkevät, ja tiellä Horonaimiin päin nousee vaikia huuto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Sillä Nimrimin vedet kuivuvat, niin että heinä siellä kuivettuu, ja ruoho lakastuu; ja ei yhtään viheriäistä ruohoa kasva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Sillä ne tavarat, jotka he koonneet ovat, ja kansa, jonka he varustaneet ovat, viedään pajuojan ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Huuto hajoo Moabin rajoja ympäri, he itkevät hamaan Eglaimiin, ja itkevät Elimin kaivon tykönä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Että Dimonin vedet ovat verta täynnä. Siihen minä tahdon vielä enempi antaa tulla Dimonin päälle, ja myös heidän päällensä, jotka Moabin jalopeuralta päässeet ovat, ja jääneiden päälle maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Lähettäkäät maaherran karitsat Selasta korven tyköä Zionin tyttären vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Mutta niinkuin lintu lentää pois, joka pesästänsä ajettu on, niin pitää Moabin tyttärelle tapahtuman Arnonin luotuspaikoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Pitäkäät neuvoa yhdessä, sanokaat tuomio, tee sinulles puolipäivän varjo niinkuin yö; kätke pois ajetut, ja älä ilmoita kulkioita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Anna minun pois ajettuni asua tykönäs; ole Moab heidän varjeluksensa hävittäjää vastaan; niin vaivaaja saa lopun, kukistaja lakkaa, ja sotkuja taukoo maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Mutta istuin valmistetaan armosta yhdelle istua, totuudessa, Davidin majassa, tuomita ja etsiä oikeutta, ja pikaisesti toimittaa vanhurskautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Mutta me kuulemme Moabin ylpeydestä, että hän on aivan ylpeä, niin että hänen ylpeytensä, koreutensa ja vihansa on suurempi kuin hänen voimansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Sentähden pitää yhden Moabilaisen itkemän toista, heidän pitää kaikkein itkemän; KirHaresetin (kaupungin) perustuksia pitää teidän huokaaman: ne ovat peräti kukistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Sillä Hesbon on tullut autioksi maaksi, Sibmassa ovat viinapuut turmellut, pakanain herrat ovat sotkuneet hänen parhaat viinapuunsa, ja tulleet Jaeseriin asti, ja vaeltaneet korpea ympäri; hänen viina-oksansa ovat hajoitetut ja viedyt meren ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Sentähden minä itken Jaeserin tähden, ja Sibman viinapuun, ja vuodatan monta pisaraa Hesbonin ja Elalen tähden; sillä huuto on langennut sinun suvees ja tuloos!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Niin että ilo ja riemu lakkaa kedolla, ja ei viinamäissä iloita eikä huudeta, eli puserreta viinaa kuurnissa; minä olen lopettanut ilohuudon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Sentähden minun sydämeni kumisee Moabin tähden kuin kantele, ja minun sisällykseni KirHareksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Silloin pitää ilmoitettaman, kuinka Moab on väsynyt korkeuksissa ja mennyt kirkkoonsa rukoilemaan, ja ei kuitenkaan ole mitään aikoin saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Tämä on se, minkä Herra siihen aikaan puhui Moabia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Mutta nyt puhuu Herra ja sanoo: kolmena vuonna, niinkuin palvelian vuodet ovat, pitää Moabin kunnian, joka suuri on kaikissa kansoissa, tuleman pieneksi, niin että aivan vähä pitää jäämän, ja ei paljo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Tämä on Damaskun kuorma: katso, ei Damaskun pidä enää oleman kaupunkina, vaan rauvenneen kiviroukkion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Aroerin kaupungeista pitää luovuttaman, niin että karja käy siellä laitumella, ja ei heitä kenkään aja ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Ja Ephraimin linnat pitää tuleman perikatoon, ja Damaskun valtakunta. Ja jääneen Syriassa pitää oleman, niinkuin Israelin lasten kunnia, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Silloin pitää Jakobin kunnian ohukaiseksi tuleman, ja hänen lihavan ruumiinsa laihaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Sillä hänen pitää silloin tuleman, niinkuin koska joku kokois laihoa elonaikana, ja niinkuin koska joku korjais tähkäpäitä käsivarrellansa, ja niinkuin joku noukkis tähkäpäitä Rephaimin laaksossa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Ja joku jälkinoukkiminen tulis; niinkuin koska joku puhdistaa öljypuita, ja on kaksi eli kolme marjaa ylhäällä latvassa, eli niinkuin neljä viisi marjaa riippuvat vielä oksissa, sanoo Herra Israelin Jumala,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Silloin pitää ihmisen pysymän hänessä, joka hänen tehnyt on, ja hänen silmänsä pitää katseleman Israelin Pyhää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Ja ei katseleman alttareita, jotka hänen kätensä ovat tehneet, eikä sitä katsoman, jonka hänen sormensa tehneet ovat, eli metsistöitä taikka kuvia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Silloin pitää hänen väkevyytensä kaupungin tuleman niinkuin hyljätyn vesan eli oksan, joka oli Israelin lasten edestä hyljätty, ja pitää tuleman autioksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Sillä sinä olet unhottanut sinun autuutes Jumalan, ja et ajatellut sinun väkevyytes kalliota; sentähden pitää sinun istuttaman ihania vesoja, mutta niin sinä olet istuttanut viina-oksia muukalaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Istuttamisen ajalla sinä kyllä ahkeroitset, että sinun jyväs aikanansa kasvaisivat; mutta syksyllä, kuin sinun lyhteet korjaaman pitäis, saat sinä surullisen murheen siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Voi sitä peräti paljoa kansaa, se on pauhaava niinkuin meri; ja kansan hyminä on kohiseva, niinkuin iso vesi pauhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Tosin niinkuin iso vesi pauhaa, niin on kansa karkaava, mutta hän on kurittava heitä, ja heidän pitää kauvas pakeneman, ja vainoa kärsimän, niinkuin tomulle tapahtuu vuorella tuulelta, ja niinkuin ympyriäiselle tapahtuu tuulispäältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Katso, ehtoona on peljästys käsillä, ja ennen aamua ei he ensinkään ole. Tämä on heidän palkkansa, jotka meiltä ryöstävät, ja heidän perintönsä, jotka meiltä omamme tempaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Voi sitä maata, joka vaeltaa siipein varjon alla, tällä puolella Etiopian virtoja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Joka sanansaattajat lähettää merelle, ja kulkee vedellä ruokoisessa haahdessa: menkäät nopiasti matkaan, sanansaattajat, sen kansan tykö, joka reväisty ja ryöstetty on, sen kansan tykö, joka julmempi on kuin joku muu, sen kansan tykö, joka siellä ja täällä mitattu ja tallattu on, jonka maa virtain hallussa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Te kaikki, jotka asutte maan päällä, ja te, jotka maassa olette, saatte nähdä, kuinka lippu nostetaan vuorella, ja kuulla, kuinka vaskitorvella soitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Sillä näin sanoo Herra minulle: minä olen hiljakseni ja katselen majastani, niinkuin palavuus, joka sateen kuivaa, ja niinkuin kaste elonajan palavuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Sillä ennen elonaikaa, kuin tulo valmiiksi tulee, ja rohkamarjat kypsentyvät, täytyy oksat leikata sirpillä, ja viinapuut hakata ja heittää pois:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Niin että ne jätetään kokonansa linnuille vuorten päällä ja eläimille maassa; niin että linnut suvella tekevät siihen pesänsä, ja kaikkinaiset eläimet makaavat siinä talvella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Silloin se revitty ja ryöstetty kansa, joka julmempi on kuin joku muu, joka siellä ja täällä mitattu on ja tallattu on, jonka maa virtain hallussa on, tuo Herralle Zebaotille lahjoja siihen paikkaan, jossa Herran Zebaotin nimi on, Zionin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Tämä on Egyptin maan kuorma: katso, Herra on vaeltava nopiassa pilvessä, ja tuleva Egyptiin. Silloin pitää epäjumalain Egyptissä vapiseman hänen edessänsä, ja Egyptiläisten sydämen pitää vavahtaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Ja minä yllytän Egyptiläiset toinen toisensa päälle, niin että yhden pitää sotimaan toista vastaan, yhden ystävän toista vastaan, yhden kaupungin toista vastaan, ja yhden valtakunnan toista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Ja ei Egyptiläisillä pidä oleman sydäntä, ja minä teen heidän neuvonsa tyhjäksi. Niin he siis kysyvät epäjumalilta, velhoilta, noidilta, taikureilta ja tietäjiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Mutta minä annan Egyptiläiset julmain herrain käsiin; ja kovan kuninkaan pitää hallitseman heitä, sanoo Herra, Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Ja vesi pitää meressä vähenemän, niin myös virrat pitää kuivuman ja kureentuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Järvien pitää juokseman pois, niin että lampivedet pitää vähenemän ja kuivuman, ruoko ja kaisla katoaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Ja ruoho ojain tykönä, virtain reunalla, ja kaikkinainen jyvä vetten tykönä pitää lakastuman ja tyhjään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Ja kalamiesten pitää murehtiman, ja kaikki, jotka ongen heittävät veteen, pitää valittaman, ja kaikki ne, jotka verkot veteen laskevat, pitää nääntymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Niin pitää häväistämän, jotka hyvää lankaa tekevät ja verkkoa kutovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Ja ne, joilla on kala-arkut, kaikkein niiden kanssa, jotka lammikoita palkan edestä tekevät, pitää sureman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Zoanin pääruhtinaat ovat tyhmät, Pharaon taitavat neuvonantajat ovat neuvossansa hulluiksi tulleet; miksi te siis sanotte Pharaosta: minä olen viisasten poika, ja olen vanhain kuningasten poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Kussa siis nyt ovat sinun taitavas? Anna heidän sanoa, ja opettaa sinuas, mitä Herra Zebaot on Egyptistä aikonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Mutta Zoanin pääruhtinaat ovat tulleet tyhmiksi; Nophin pääruhtinaat ovat petetyt, he peipoittelevat Egyptin sukuin kulmakiven.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Sillä Herra on vuodattanut heidän sekaansa väärän hengen, pettämään Egyptiä kaikissa, mitä he tekevät, niinkuin juopunut horjuu oksentaessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Ja ei pidä Egyptillä oleman päätä eli häntää, oksaa eli kantoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Silloin pitää Egyptin oleman niinkuin vaimot, pelkäämän ja vavahtuman, koska Herra Zebaot häälyttää kättänsä heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Ja Egyptin pitää pelkäämän Juudan maata, niin että sen, joka sitä ajattelee, pitää peljästymän Herran Zebaotin neuvoa, jonka hän siitä on pitänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Siihen aikaan pitää viisi kaupunkia Egyptissä Kanaanin maan kielellä puhuman, ja vannoman Herran Zebaotin kautta; jokainen heistä pitää hävityksen kaupungiksi kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Silloin pitää Herran Zebaotin alttari keskellä Egyptin maata oleman, ja Herran vartiovaha hänen äärissänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Joka pitää merkiksi ja todistukseksi oleman Herralle Zebaotille Egyptin maassa; sillä heidän pitää Herran tykö huutaman vaivaajainsa tähden, niin hän heille lähettää vapahtajan ja sankarin, joka heitä auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Ja sinä päivänä pitää Herra tunnettaman Egyptissä ja Egyptiläisten pitää tunteman Herran. Ja he palvelevat häntä uhrilla ja ruokauhrilla, ja lupaavat Herralle lupausta, ja sen pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Ja Herra on vaivaava Egyptiläisiä, hän on vaivaava ja parantava jälleen; sillä he palajavat Herran tykö, ja he rukoilevat häntä, ja hän parantaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Silloin on tie avoin Egyptistä Assyriaan, Assyrialaisten mennä Egyptiin, ja Egyptiläisten Assyriaan; että Egyptiläiset ja Assyrialaiset ynnä palvelisivat (Jumalaa).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Silloin Israel pitää itse kolmantena oleman, Assyrialaisten ja Egyptiläisten kanssa, sen siunauksen kautta, joka on oleva keskellä maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Sillä Herra Zebaot on siunaava heitä ja sanova: siunattu olkoon Egypti minun kansani, ja Assur minun käsialani, ja Israel minun perimiseni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Sinä vuonna, kuin Tartan tuli Asdodiin, jonka Assyrian kuningas Sargon oli lähettänyt, ja soti Asdodia vastaan ja voitti sen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Silloin puhui Herra Jesaian Amotsin pojan kautta ja sanoi: mene ja riisu säkki kupeistas ja kengät jaloistas: ja hän teki niin, ja kävi alasti ja paljain jaloin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Sanoi siis Herra: niinkuin palveliani Jesaia käy alasti ja paljailla jaloilla, kolmen ajastajan merkiksi ja ihmeeksi Egyptille ja Etiopialle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Niin on Assyrian kuningas ajava vangittua Egyptiä ja hävitettyä Etiopiaa, sekä nuoria että vanhoja, alastomia ja paljasjalkaisia, paljastetun hävyn kanssa, Egyptille hävyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Ja heidän pitää peljästymän ja häpeemän Etiopiaa, johon he luottivat, ja Egyptiläisiä, joista he kerskasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Ja tämän luodon asuvaiset pitää silloin sanoman: onko tämä meidän turvamme, johon olemme paenneet apua saamaan, että me Assyrian kuninkaalta pelastettaisiin? kuinka me olemme päässeet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Tämä on korven kuorma meren tykönä: niinkuin tuulispää tulee etelästä, joka kääntää ylösalaisin, niin se tulee korvesta, kauhiasta maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Sillä minulle on osoitettu kova näky: pettäjä tulee toista vastaan, hävittäjä toista vastaan. Mene ylös Elam, piiritä heitä Madai: minä lopetan kaikki hänen huokauksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Sentähden ovat minun kupeeni täynnä kipua, ja ahdistus on minun käsittänyt, niinkuin lapsen synnyttäjän ahdistus; minä kyyristän minuni, koska minä sen kuulen, ja peljästyn, koska minä sen näen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Minun sydämeni vapisee, kauhistus on minun peljättänyt; sentähden ei ole minulla ollut suloisella yöllä yhtään lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Valmista pöytä, anna valvojain valvoa, syö, juo: nouskaat te pääruhtinaat ja voidelkaat kilvet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Sillä Herra sanoo näin minulle: mene ja toimita vartio, joka katselis ja ilmoittais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Mutta hän näki ratsastajat ajavan ja menevän aaseilla ja kameleilla, ja piti siitä visun vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Ja hän huusi niinkuin jalopeura: Herra, minä olen vartiolla yli päivää, ja olen minun vartiollani kaikki yöt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Ja katso, siellä tulee yksi vaunuissa ja kaksi ratsahin, joka vastaa ja sanoo: kaatunut, kaatunut on Babylon, ja kaikki hänen jumalainsa kuvat lyötiin maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'O minun tappamiseni ja minun riiheni permanto! mitä minä olen Herralta Zebaotilta, Israelin Jumalalta, kuullut, sen minä teille ilmoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Tämä on Duman kuorma: Seiristä huudetaan minua: vartia, mitä yö kuluu? vartia, mitä yö kuluu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Vartia sanoi: kuin aamu tulee, niin vielä yö on; jos te vielä kysytte, niin teidän pitää vielä sitte palajaman ja taas kysymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Tämä on Arabian kuorma: teidän pitää yötymän Arabian metsässä, Dedanimin tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Kantakaat vettä janoovaa vastaan, te jotka asutte Temanin maassa: taritkaat pakenevaisille leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Sillä he pakenevat miekkaa, paljasta miekkaa, jännitettyä jousta ja isoa sotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Sillä näin sanoo Herra minulle: vielä nyt vuosi, niinkuin palkollisen vuodet ovat, niin pitää kaiken Kedarin kunnian hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Ja jääneet ampujat, väkevät Kedarin lapsista, pitää vähemmäksi joutuman; sillä Herra Israelin Jumala on sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Tämä on Näkylaakson kuorma: mikä sinun nyt on, että te niin kaikki olette astuneet kattoin päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Sinä olet täynnä humua: kaupunki täynnä väkeä, iloinen kaupunki: sinun lyötys ei ole miekalla lyödyt, ja ei ole kuolleet sodassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Vaan kaikki sinun päämiehes ovat poikenneet joutsesta pois, ja ovat vangitut; kaikki kuin sinussa löyttiin, ovat vangitut, ja kauvas paenneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Sentähden minä sanon: menkäät pois minun tyköäni, antakaat minun itkeä vaikiasti; älkäät ahkeroitko lohduttaa, minun kansani tyttären hävityksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Sillä se on kapinan, sortamisen ja surun päivä Herralta, Herralta Zebaotilta, Näkylaaksossa muurien kukistamisen tähden, ja huudon tähden vuorella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Että Elam lähtee viinellä, vaunuilla, väellä, ratsasmiehillä, ja Kir välkkyy kilvistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Ja tapahtuu, että sinun valitut laaksos ovat täynnä vaunuja; ja ratsastajat sioittavat itsensä portin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Silloin pitää Juudan peite avattaman, että aseet nähdään silloin metsähuoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Ja te olette näkevä monta reikää Davidin kaupungissa; ja kokootte veden alimmaiseen lammikkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Teidän pitää lukeman huoneet Jerusalemissa, ja teidän pitää jaottaman huoneet vahvistaaksenne muureja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Ja teidän pitää tekemän vesihaudan molempain muurien välille, vanhan kalalammin vedestä; kuitenkin ette katso häntä, joka tämän tekee, ettekä katsele sitä, joka senkaltaisia on kaukaa toimittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Sentähden antaa Herra, Herra Zebaot, silloin julistaa, että itketään ja murehditaan, ja hiukset ajellaan ja puetaan säkkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, '(Vaikka nyt) katso, ilo ja riemu, teurastaa härkiä, tappaa lampaita, syödä lihaa, juoda viinaa, (ja sanoa): syökäämme ja juokaamme, meidän pitää kuitenkin huomenna kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Tämä on, (sanoo) Herra Zebaot, minun korvilleni tullut: mitämaks, jos minä tämän pahan teon annan anteeksi, siihenasti kuin te kuolette, sanoo Herra, Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Näin sanoo Herra, Herra Zebaot: mene tavarahuoneen haltian Sebnan tykö ja sano hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Mitä sinun tässä on, kenenkä oma sinä olet? ettäs annat hakata itselles haudan niinkuin se, joka hakkauttaa itsellensä haudan korkeuteen, ja olet niinkuin se, joka antaa itsellensä tehdä asumasian vuorelle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Katso, Herra ajaa sinun pois, niinkuin väkevä mies heittää jonkun pois, ja peittää sinun kokonansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Ja pyörittää sinun kohta, ja peräti niinkuin kierikan aukialle kedolle; siellä sinun pitää kuoleman, siellä pitää sinun kalliit vaunus, sinun Herras huoneen kanssa, tuleman häväistykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Ja minä kukistan sinun säädystäs, ja sinä pannaan pois viraltas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Ja silloin pitää tapahtuman, että minä kutsun palveliani Eliakimin, Hilkian pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Ja panen hänen yllensä sinun hamees, ja vyötän hänen sinun vyölläs, ja annan sinun valtas hänelle; että hän on niiden isä, jotka Jerusalemissa ja Juudan huoneessa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Ja panen Davidin huoneen avaimen hänen olallensa, että hän avaa, ja ei kenkään sulje, että hän sulkee, ja ei kenkään avaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Ja lyön hänen niinkuin naulan vahvaan paikkaan; ja hänellä on oleva kunnian istuin, hänen isänsä huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Että hänen päällensä ripustetaan kaikki hänen isänsä huoneen kunnia, lapset ja lasten lapset, kaikki pienet kappaleet, juoma-astiat, ja kaikkinaiset kanteleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Silloin, sanoo Herra Zebaot, naula pitää otettaman pois, joka vahvassa paikassa on, niin että hänen pitää rikkoontuman, lankeeman, putooman, ja se kuorma kuin hänen päällänsä on, pitää hukkuman; sillä Herra sen sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Tämä on Tyron kuorma: valittakaat, te haahdet merellä; sillä se on kukistettu, niin ettei siellä ole yhtään huonetta, eikä sinne mene kenkään; Kittimin maasta pitää heidän sen äkkäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Olkaat ääneti, te luotoin asuvaiset: Zidonin kauppamiehet, jotka merellä vaelsivat, täyttivät sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Ja kaikkinainen hedelmä, joka Sihorin tykönä kasvaa, ja jyvät virran tykönä vietiin sinne veden ylitse; ja on pakanain kaupaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Sinä mahdat kyllä hämmästyä, Zidon; sillä meri lausuu ja vahvin meren tykönä sanoo: en minä ole silleen raskas, en minä synnytä, enkä myös kasvata yhtään nuorukaista, enkä ruoki neitsyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Niinkuin kuultaissa Egyptistä hämmästyttiin, niin pitää myös hämmästyttämän, koska Tyrosta kuullaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Menkäät merille, valittakaat, jotka luodoissa asutte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Eikö tämä ole teidän ilokaupunkinne, joka kerskaa itsiänsä vanhuudestansa? Hänen jalkansa pitää viemän hänen pitkän matkan taa vaeltamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kuka olis sitä ajatellut, että kruunatulle Tyrolle piti niin käymän? että sen kauppamiehet ovat pääruhtinaat, ja sen kauppiaat ylimmäiset maassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Herra Zebaot on sen niin ajatellut, että hän kaikki hänen kaunistuksensa prameuden heikoksi tekis; ja tekis ylönkatsotuksi kaikki kuuluisat maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Vaella maas lävitse niinkuin virta, sinä Tarsiksen tytär; ei siellä ole enään yhtään vyötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Hän kokottaa kätensä meren päälle, ja peljättää valtakunnat; Herra käski Kananin hävittämään sen linnat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Ja sanoi: ei sinun pidä enään iloitseman, sinä häväisty neitsy Zidonin tytär: nouse ja mene matkaas Kittimiin, ei sinulla pidä sielläkään lepoa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Katso, Kaldealaisten maassa ei yhtään kansaa ollut, vaan Assur on sen perustanut korven asuvaisille, ja rakentanut hänen linnansa, pannut ylös hänen huoneensa, ja on kuitenkin pantu kukistettavaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Surekaat, te haahdet merillä; sillä teidän voimanne on tyhjä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Silloin pitää Tyro unhotettaman seitsemänkymmentä vuotta, niinkauvan kuin yksi kuningas elää; mutta seitsemänkymmenen vuoden perästä käypi Tyron niinkuin portosta veisataan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Ota kantele, mene ympäri kaupunkia, sinä unhotettu portto: soita vahvasti kantelettas, ja laula lohdullisesti, että sinua taas muistettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Sillä seitsemänkymmenen vuoden perästä on Herra etsivä Tyroa, että hän tulis jälleen porttopalkoillensa, ja huorin tekis kaikkein valtakuntain kanssa maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Mutta hänen kauppansa ja porttopalkkansa pitää oleman pyhä Herralle. Ei sitä koota tavaraksi, eikä salata, vaan jotka asuvat Herran edessä, niillä pitää hänen kauppakalunsa oleman, siitä syödä, ravita ja itsiänsä vaatettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Katso, Herra tekee maan tyhjäksi ja autioksi, ja kukistaa, mitä siinä on, ja hävittää sen asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Ja papeille tapahtuu niinkuin kansallekin, herralle niinkuin palveliallekin, emännälle niinkuin piiallekin, myyjälle niinkuin ostajallekin, lainaajalle niinkuin lainaksi ottajallekin, korkorahan ottajalle niinkuin antajallekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Sillä maan pitää peräti tyhjäksi ja kokonansa ryöstetyksi tuleman; sillä Herra on tämän sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Maa on surkia ja hävitetään, maa pelehtyy ja häviää; kansan ylimmäiset nääntyvät maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Maa on saastaiseksi tullut asuvaisistansa; sillä he tekevät lakia vastaan ja muuttavat säädyt, ja luopuvat ijankaikkisesta liitosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Sentähden kuluttaa kirous maan ja sen asuvaiset hävitetään; sentähden maan asuvaiset kuivettuvat, niin että vähä jää väkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Viina katoo, viinapuu surkastuu, ja kaikki, jotka sydämestänsä iloisina olivat, huokaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Vaskirumpuin riemu taukoo, iloitsevaisten ilo puuttuu, kanteleiden riemu loppuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Ei lauleta viinaa juotaissa, ja hyvä juoma on karvas juoville.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Tyhjä kaupunki on kukistettu maahan; kaikki huoneet ovat teljetyt, niin ettei yksikään sinne mene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Viinan puutteen tähden valitetaan kaduilla: kaikki ilo on pois, kaikki maan riemu on matkassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Ei ole muuta jäänyt kaupunkiin kuin hävitys, ja portit ovat autiot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Sillä kansalle tapahtuu myös maassa niinkuin öljypuillekin, koska siitä on poimittu; niinkuin sitte poimittaisiin kuin oikia viinan kokousaika on pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ne korottavat äänensä ja iloitsevat; Herran kunniasta he iloitsevat, hamasta merestä asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Niin kiittäkäät nyt Herraa laaksoissa, luodoissa Herran, Israelin Jumalan nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Me kuulemme kiitosvirren maailman äärestä, vanhurskaalle kunniaksi. Ja minun pitää sanoman: miksi minä olen niin laiha? miksi minä olen niin laiha? voi minua! sillä ylönkatsojat ylönkatsovat, ja ylönkatsojat ylönkatsovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Sentähden tulee teidän asuvainne päälle maassa hämmästys, kuoppa ja paula.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Ja jos joku pakenis hämmästyksen huutoa, niin hän kuitenkin putoo kuoppaan; ja jos hän pääsee kuopasta ylös, niin hän kuitenkin käsitetään paulaan, sillä korkeuden akkunat avataan, ja maan perustukset vapisevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Maan käy aivan pahoin: ei sen pidä ollenkaan menestymän, vaan pitää peräti raukeaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Maan pitää kovin hoiperteleman niinkuin juopuneen, ja vietämän pois niinkuin majan; sillä sen pahat teot painavat sen, niin että sen pitää lankeeman, ja ei enään nouseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Silloin on Herra etsivä sitä korkiaa sotaväkeä, joka korkeudessa on, ja maan kuninkaita, jotka ovat maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Että he kootaan yhteen niinkuin kuopassa sidotut, ja pitää oleman suljetut vankeudessa, ja suuren ajan perästä taas etsittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Ja kuun pitää häpeemän, ja auringon ujoileman, koska Herra Zebaot on tuleva kuninkaaksi Zionin vuorella ja Jerusalemissa; ja hänen vanhimpainsa edessä pitää kunnia oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Herra, sinä olet minun Jumalani, sinua minä ylistän, minä kiitän sinun nimeäs; sillä sinä teet ihmeitä: sinun vanhat aivoitukses ovat uskolliset ja todet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Sillä sinä teet kaupungin kiviraunioksi, sen vahvan kaupungin, että hän läjässä on; muukalaisten palatsit, niin ettei ne enää ole kaupungit, eikä ikänä enää rakenneta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Sentähden kunnioittaa sinua väkevä kansa, urhoolliset pakanain kaupungit pelkäävät sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Sillä sinä olet heikkoin väkevyys ja köyhäin vahvuus heidän vaivoissansa: myrskyssä turva, varjo helteessä, kuin tyrannit julmistuvat niinkuin raju-ilma seinää vastoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Sinä nöyryytät muukalaisten metelin, niinkuin helteen kuivassa paikassa, niinkuin helle pilven varjolla, niin tyrannein ilo painetaan alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Ja Herra Zebaot tekee kaikille kansoille tällä vuorella lihavan pidon, pidon selkiästä viinasta, rasvasta, ytimestä ja puhtaasta viinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Ja tällä vuorella on hän kääriliinan paneva pois, jolla kaikki ihmiset käärityt ovat, ja peittovaatteen, jolla kaikki pakanat peitetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Sillä kuolema pitää nieltämän ijankaikkisesti, ja Herra, Herra on kyyneleet pyyhkivä pois jokaisen kasvoista, ja on ottava kansansa häväistykset pois kaikissa maakunnissa; sillä Herra on sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Silloin sanotaan: katso, tämä on meidän Jumalamme jota me odotamme, ja hän auttaa meitä; tämä on Herra, häntä me odotamme, iloitaksemme ja riemuitaksemme hänen autuudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Sillä Herran käsi lepää tällä vuorella; mutta Moab runnellaan sen alla, niinkuin korret sotkutaan loassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Ja Herra hajoittaa kätensä heidän sekaansa, niinkuin uija hajoittaa uidaksensa; ja hän on käsivarrellansa heidän prameutensa alentava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Ja sinun muuries korkiat vahvistukset hän kallistaa, alentaa ja heittää tomuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Siihen aikaan pitää Juudan maassa tämä veisu veisattaman: meillä on vahva kaupunki, hän pani autuuden muuriksi ja varjelukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Avatkaat portit, vanhurskaan kansan, joka uskossa pysyy, käydä sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Sinä pidät aina rauhan, vahvan lupaukses jälkeen; sillä sinuun turvataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Sentähden luottakaat Herraan ijankaikkisesti; sillä Herra, Herra on kallio ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Ja hän notkistaa alas ne, jotka korkialla asuvat, hän alentaa korotetun kaupungin; hän sysää sen maahan, niin että se tomussa makaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Että hän jaloilla poljetaan, vaivaisten jaloilla ja köyhäin kantapäillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Mutta vanhurskasten tie on tasainen; sinä ojennat vanhurskasten polut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Herra, me odotamme sinua oikeutes tiellä; sydän himoitsee sinun nimeäs ja muistoas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Minä halajan sinua sydämestäni yöllä, minun henkeni valvoo myös minussa varhain sinun tykös; sillä kussa sinun oikeutes maakunnassa on, niin maan piirin asuvaiset oppivat vanhurskautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Mutta ehkä jumalattomille armoja tarittaisiin, niin ei he opi kuitenkaan vanhurskautta, vaan tekevät ainoastaan pahaa oikeuden maalla; sillä ei he näe Herran kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Herra, sinun kätes on ylennetty, vaan ei he sitä näe; mutta kuin he sen nähdä saavat, niin he häpiään tulevat kansan kiivaudesta, ja vielä sitte tuli sinun vihollises kuluttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Mutta sinä, Herra, saatat meille rauhan; sillä kaikki, mitä me toimitamme, olet sinä meille antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Herra meidän Jumalamme: muut herrat tosin meitä myös vallitsevat paitsi sinua; mutta me muistamme ainoastaan kuitenkin sinussa sinun nimeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Ei kuolleet eläviksi tule ja nukkuneet ei nouse; sillä sinä olet heitä etsinyt ja hävittänyt, ja kaiken heidän muistonsa kadottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Mutta sinä, Herra, olet lisännyt kansaa, sinä Herra olet lisännyt kansaa, sinä olet kunnialliseksi tullut; sinä olet pannut heitä kauvas maailman ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Herra, kuin tuska tulee, niin sinua etsitään: koskas heitä kuritat, niin he parkuvat surkiasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Niinkuin raskaalla vaimolla, kuin hän synnyttämällänsä on, on ahdistus, ja hän parkuu kivullansa, niin meille myös tapahtuu, Herra, sinun kasvois edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Me olemme raskaat ja meillä on kipu, niinkuin tuulen synnyttäväisellä; emme kuitenkaan voi maata auttaa, eikä maan piirin asuvaiset tahtoneet langeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Mutta sinun kuollees elävät, ja minun kuolleet ruumiini nousevat jälleen kuolleista. Herätkäät ja kerskatkaat te, jotka makaatte maan alla; sillä sinun kastees on viheriäisen kedon kaste, ja maa on kuolleet itsestänsä antava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Mene, kansani, ja käy sisälle kammioos, ja sulje sinun oves jälkees; lymytä sinus silmänräpäykseksi, niin kauvan kuin viha käy ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Sillä katso, Herra on käyvä ulos siastansa etsimään maan asuvaisten pahuutta heidän päällensä; niin että maa ilmoittaa heidän verensä, ja ei niitä enää peitä, jotka hänessä tapetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Silloin on Herra kovalla, suurella ja väkevällä miekallansa etsivä Leviatania, joka on pitkä kärme, ja Leviatania, joka on kiperä kärme; ja on tappava lohikärmeen meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Silloin pitää oleman punaisen viinan viinamäen; laulakaat hänestä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Minä Herra varjelen hänen, ja kastan hänen aikanansa, ettei hänen lehtensä hukkuisi, minä varjelen häntä päivällä ja yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'En ole minä vihainen. Voi jos minä saisin sotia ohdakkeiden ja orjantappurain kanssa! niin minä menisin heidän tykönsä, ja polttaisin heidät kaikki tyynni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Hän on minua tallella pitävä, ja toimittava minulle rauhan; rauhan on hän vielä sitte minulle saattava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Siihen on se kuitenkin joutuva, että Jakob juurtuu ja Israel vihoittaa ja kukoistaa, niin että he maan piirin hedelmällä täyttävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Eikö hän kumminkaan tule lyödyksi, niinkuin hänen vihollisensa lyövät häntä? ja eikö hän tule tapetuksi, niinkuin hänen vihollisensa häntä tappavat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Vaan sinä tuomitset heitä määrällä, ja kirvoitat heitä sittekuin sinä ankaralla tuulellas olet heitä murheelliseksi saattanut, koska idästä tuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Sentähden pitää Jakobin synti sen kautta anteeksi annettaman; ja se on siitä kaikki hyödytys, että hänen syntinsä otetaan pois, koska hän tekee kaikki alttarin kivet niinkuin tuhaksi muserretut kivet, ettei yhtään metsistöä eli kuvaa pidä enää jäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Sillä vahvan kaupungin pitää yksinänsä oleman, kauniit huoneet hyljättämän ja jätettämän niinkuin korpi; niin että vasikat käyvät siellä laitumella, oleskelevat siellä ja pureskelevat oksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Hänen oksansa pitää murtuman kuivuuden tähden, niin että vaimot niillä valkeata tekevät; sillä se on ymmärtämätöin kansa, sentähden ei myös se, joka heidät tehnyt on, armahda heitä, ja joka heidät luonut on, ei ole heille armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Silloin on Herra heittävä meren rannasta Egyptin virtaan, ja te Israelin lapset kootaan yksi toisensa perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Silloin soitetaan suurella basunalla, niin tulevat kadotetut Assyrian maalla, ja karkoitetut Egyptin maalla, ja rukoilevat Herraa pyhällä Jerusalemin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Voi ylpiää Ephraimin juopuneiden kruunua! jonka kaunis kunnia on pudonnut kukkanen, joka on ylemmäisellä puolella lihavaa laaksoa, jossa he viinasta hoipertelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Katso, väkevä ja voimallinen Herralta, niinkuin raesade, niinkuin vahingollinen tuuli, niinkuin vesimyrsky, joka väkevästi lankee, pitää väkivallalla maahan päästettämän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Että Ephraimin juopuneiden ylpiä kruunu jaloilla tallatan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Ja hänen kunniansa kaunistuksen pudonneet kukkaset, jotka lihavata laaksoa ylemmäisellä puolella ovat, pitää tuleman niinkuin se, joka varhain suvella kypsyy, jonka joku nähtyänsä ja käsillä pidellessänsä syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Silloin Herra Zebaot on jääneelle kansallensa kunnian kruunu ja kaunis seppele,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Ja tuomion henki hänelle, joka oikeudessa istuu, ja väkevyys niille, jotka sodasta palaavat portin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Siihen myös ovat nämät hulluksi tulleet viinasta, ja hoipertelevat väkevistä juomista; sillä papit ja prophetat ovat hullut väkevästä juomasta, he ovat uponneet viinaan, ja hoipertelevat väkevästä juomasta, he ovat erhettyneet ennustuksessa, ja ei osanneet oikeutta tuomiossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Sillä kaikki pöydät ovat täynnä oksennusta ja riettautta joka paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Kenelle hän siis opettaa viisautta? kenenkä hän antaa ymmärtää saarnaa? Vieroitettuin rieskasta, eroitettuin nisistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Sillä (he sanovat:) käske, käske vielä, käske, käske vielä, odota, odota vielä, odota, odota vielä, tässä vähä, siellä vähä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Sillä hän on vihdoin pilkkaavaisilla huulilla ja toisella kielellä puhuva kansalle, jolle nyt näitä saarnataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Niin saadaan lepo, näin virvoitetaan väsyneet, niin ollaan alallansa; ja ei kuitenkaan tahdota kuulla (tätä saarnaa).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Sentähden pitää myös Herran sana heille juuri niin oleman: käske, käske vielä, käske, käske vielä, odota, odota vielä, odota, odota vielä, tässä vähä, siellä vähä, että heidän pitää menemän pois ja kaatuman takaperin, musertuman, kiedottaman ja vangiksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Kuulkaat siis Herran sanaa, te pilkkakirveet, jotka vallitsette tätä kansaa, joka on Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Sillä te sanotte: me olemme tehneet liiton kuoleman kanssa ja sovinnon helvetin kanssa. Kuin rangaistuksen virta tulee, ei hänen pidä meitä kohtaaman; sillä me olemme tehneet valheen turvaksemme, ja petoksen varjelukseksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Sentähden sanoo Herra, Herra: katso, minä lasken Zioniin perustuskiven, koetellun kiven, kalliin kulmakiven, joka hyvin on perustettu: joka uskoo, ei hänen pidä peljästymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Ja minä teen tuomion ojennusnuoraksi ja vanhurskauden mitaksi, niin pitää rakeet karkoittaman pois väärän turvan, ja veden pitää viemän tulen pois;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Että teidän liittonne kuoleman kanssa pitää tyhjäksi tuleman, ja teidän sovintonne helvetin kanssa ei pidä vahva oleman; ja koska rangaistuksen virta tulee, pitää sen tallaaman teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Niin pian kuin se tulee, niin sen pitää teitä viemän pois: jos se tulee aamulla, niin tapahtuu se aamulla, niin myös päivällä ja yöllä; sillä ainoastaan rangaistus opettaa ottamaan sanoista vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Sillä vuode on niin lyhyt, ettei saa itsiänsä ojentaa, ja peite on niin soukka, ettei sen alla taida mykärässä olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Sillä Herra on nouseva niinkuin Peratsimin vuorella, ja vihastuva niinkuin Gibeonin laaksossa, että hän tekis työnsä, muukalaisen työnsä, ja että hän toimittais tekonsa, oudon tekonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Pankaat siis pilkkanne pois, ettei siteenne kovemmaksi tulisi; sillä minä olen kuullut hävityksen ja teloituksen, joka Herralta, Herralta Zebaotilta on tapahtuva kaikessa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Ottakaat korviinne ja kuulkaat minun ääneni, ymmärtäkäät ja kuulkaat minun puheeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Kyntääkö eli jyrästääkö taikka viljeleekö peltomies peltonsa aina jyviksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Eikö niin ole? koska hän sen on tasoittanut, niin hän kylvää siihen herneitä ja heittää kuminoita, ja kylvää nisuja, ohria, jokaista kuhunka hän tahtoo, ja kaurat paikkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Juuri niin kurittaa myös heidän Jumalansa heitä rangaistuksella, ja opettaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Sillä ei herneitä tapeta varstalla, eikä vaunuratas anneta kuminain päällä käydä, vaan herneet varistetaan sauvalla ja kuminat vitsalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Se jauhetaan ja leivotaan, eikä peräti tyhjäksi tapeta, koska se vaunurattaalla ja hevosilla tapetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Näin tekee myös Herra Zebaot; sillä hänen neuvonsa on ihmeellinen, ja sen jalosti toimittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Voi Ariel, Ariel! sinä Davidin leirin kaupunki! te pidätte vuoden ajat ja pyhäpäivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Mutta minä vaivaan Arielia, niin että hänen pitää murehtiman ja sureman ja oleman minulle oikia Ariel.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Sillä minä piiritän sinun joka kulmalta, ja ahdistan sinun saarrolla, ja annan panna vallit sinun ympärilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Silloin pitää sinun itses alentaman, ja maasta puhuman, ja mutiseman puheellas tomusta; että sinun äänes on niinkuin noidan maasta, ja sinun puhees pitää oleman niinkuin tomusta haisevaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Ja niitä, jotka sinua hajoittavat, pitää oleman niin monta kuin pientä tomua, ja tyranneja niin monta kuin lentäviä akanoita; ja sen pitää ratki äkisti tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Sillä sinun pitää Herralta Zebaotilta etsityksi tuleman pitkäisen jylinällä, maan järinällä, suurella äänellä, tuulen pyöriäisellä, raju-ilmalla ja kuluttavaisen tulen liekillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Mutta niinkuin yön näkö unessa, niin pitää kaikkein pakanain joukko oleman, jotka sotivat Arielia vastaan, kaiken joukkonsa ja saartonsa kanssa, ja niitä, jotka häntä ahdistavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Sillä niinkuin isoovainen on unessa syövinänsä, mutta herättyänsä on hänen sielunsa vielä tyhjä; ja niinkuin janoova on unessa juovinansa, mutta herättyänsä on hän voimatoin ja janoissansa: juuri niin pitää myös kaikkein pakanain joukko oleman, jotka sotivat Zionin vuorta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Olkaat hitaat ja ihmetelkäät, eläkäät hekumassa, huutakaat, ja juopukaat, ei kuitenkaan viinasta; horjukaat, ei kuitenkaan väkevästä juomasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Sillä Herra on teille raskaan unen hengen lähettänyt, ja teidän silmänne sulkenut; teidän prophetanne, päämiehenne ja näkiänne on hän sokaissut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Niin että kaikkein prophetain näyt ovat heille niinkuin lukitun kirjan sanat. Jos joku sen antais sille, joka lukea taitaa, ja sanois: lue tätä, ja hän vastaa: en minä taida, sillä se on lukittu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Eli jos joku antais sille, joka ei lukea taida, ja sanois: lues tätä, ja hän vastaa: en minä taida ensinkään lukea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Ja Herra sanoo: että tämä kansa lähestyy minua suullansa, ja kunnioittaa minua huulillansa; mutta heidän sydämensä on kaukana minusta, ja pelkäävät minua ihmisten käskyin jälkeen, joita he opettavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Niin minä myös teen tälle kansalle ihmeellisesti, hirmuisesti, ja kamalasti, että heidän viisastensa viisaus hukkuu, ja heidän ymmärtäväistensä ymmärrys kätketään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Voi niitä, jotka tahtovat olla salatut Herran edessä, ja peittää aivoituksensa, ja tekonsa pimeydessä pitää, ja sanovat: kukapa meidät näkee? eli kuka tuntee meitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Miksi te niin nurjat olette? Niinkuin savenvalaja pidettäisiin savena; käsiala puhuis tekiästänsä: ei hän ole minua tehnyt, ja teko sanois tekiästänsä: ei hän minua tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Eikö vähän hetken perästä Libanonin pidä hedelmälliseksi kedoksi tuleman, ja hedelmällinen keto metsäksi luettaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Silloin kuulevat kuurot tämän kirjan sanoja; ja sokian silmät näkevät synkeydessä ja pimeydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Ja raadolliset saavat ilon Herrasta; ja köyhät ihmisten seassa riemuitsevat Israelin Pyhässä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Koska tyrannit hukkuvat, ja pilkkaajat loppuvat, ja ne kaikki teloitetaan, jotka valvovat pahaa tehdäksensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Jotka ihmisen tekevät syntiseksi sanan tähden, ja vainoovat rankaisiaansa portissa, ja poikkeevat oikeudesta valheen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Sentähden sanoo Herra, Abrahamin lunastaja, Jakobin huoneelle näin: ei Jakob tule enää häpiään, eikä hänen kasvonsa ole enää häpeevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Sillä koska he saavat lapsensa nähdä, minun käsialani heidän seassansa, niin he pyhittävät minun nimeni; ja heidän pitää Jakobin Pyhän pyhittämän, ja Israelin Jumalaa pelkäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Sillä joilla eksyväinen henki on, ne ottavat ymmärryksen; turhan puhujat sallivat heitänsä opetettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Voi luopuvaisia lapsia! sanoo Herra: jotka ilman minua neuvoa pitävät, ja ilman minun henkeäni varjelusta etsivät, kokoovat syntiä synnin päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Jotka menevät alas Egyptiin, ja ei kysy minun suutani, varustaaksensa itsiänsä Pharaon voimalla, ja varjellaksensa itsensä Egyptin varjolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Ja Pharaon väkevyys pitää oleman teille häpiäksi, ja Egyptin varjon turva häväistykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Sillä heidän pääruhtinaansa ovat olleet Zoanissa; ja heidän sanansaattajansa ovat tulleet Hanekseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Mutta heidän pitää kaikkein kuitenkin häpiään tuleman, sen kansan tähden, joka ei heille hyväksi eli avuksi olla taida, eikä muutoin hyödytykseksi, vaan ainoasti häpiäksi ja myös pilkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Tämä on niiden petoin kuorma, jotka etelään päin ovat, kussa vanha ja nuori jalopeura on, tuliset kyykärmeet ja lentäväiset kärmeet murheen ja ahdistuksen maassa. He vievät riistansa varsoilla, ja tavaransa kamelein selässä sille kansalle, joka ei heille ensinkään hyödytykseksi olla taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Sillä ei Egypti mitään ole, ja hänen apunsa on turha, sentähden minä saarnaan siitä näin: alallansa olla on paras.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Mene siis nyt ja kirjoita tämä heidän eteensä tauluun, ja pane kirjaan, pysymään viimeiseen päivään asti, alati ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Sillä se on tottelematoin kansa, ja valhetteliat lapset: lapset, jotka ei tahdo kuulla Herran lakia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Vaan sanovat näkiöille: ei teidän pidä näkemän, ja katsojille: ei teidän pidä katsoman meille oikeutta; mutta saarnatkaat meille suloisesti, katsokaat petos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Poiketkaat teiltä, luopukaat tästä retkestä: antakaat Israelin Pyhän lakata meistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Sentähden sanoo Israelin Pyhä näin: että te hylkäätte tämän sanan, ja luotatte väkivaltaan ja vääryyteen, ja kerskaatte siitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Niin pitää tämän pahan teon oleman teille niinkuin rako korkiassa muurissa, kuin se rupee hajoomaan, joka äkisti kaatuu maahan ylösalaisin, ja murentuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Niinkuin savi-astia muserrettu olis, joka muserretaan ja ei säästetä, siihenasti ettei siitä löydä niin suurta kappaletta, että tulta tuotaisiin totoista, eli ammennettaisiin vettä kaivosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Sillä näin sanoo Herra, Herra Israelin Pyhä: kääntymisellä ja hiljaisuudella te tulette autetuksi, hiljaisuudessa ja toivossa te väkeväksi tulette, mutta ette tahtoneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Vaan sanoitte: ei, vaan me tahdomme paeta hevosilla; sentähden teidän pitää kulkiana oleman: ja me tahdomme nopiasti ajaa; sentähden pitää teidän vainoojanne myös nopiat oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tuhannen teistä pitää pakeneman yhden miehen uhkauksesta, viiden uhkauksesta pitää teidän pakeneman, siihenasti että teistä jää niinkuin pielipuu vuorelle, ja niinkuin lippu korkeudelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Sentähden Herra odottaa, että hän olis teille armoinen, ja sentähden on hän noussut teitä armahtamaan; sillä Herra on oikeuden Jumala. Autuaat ovat kaikki, jotka häntä odottavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Sillä Zionin kansa on asuva Jerusalemissa, ja et sinä ole katkerasti itkevä. Hän kaiketi armahtaa sinua, kuin sinä huudat; hän vastaa sinua niin pian kuin hän sen kuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Ja Herra antaa teille leipää tuskassanne ja vettä ahdistuksessanne; sillä ei sinun opettajas lennä enää pois, vaan sinun silmäs näkevät opettajas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Ja korvas kuulevat sanan takanas, sanoen: tämä on tie käykäät sitä, kuin te oikialle eli vasemmalle kädelle eksyneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Silloin pitää teidän saastuttaman teidän hopialla silatut kuvanne, ja teidän kuvainne kultaiset vaatteet; ja teidän pitää ne heittämän pois niinkuin saastaisuuden, ja niille sanoman: mene ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Silloin hän antaa sateen siemenelles, jonka pellolles kylvänyt olet, ja leipää pellon tulosta ylen runsaasti; ja karjas kaitaan avaralla kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Härjät ja varsat, jotka peltos kyntävät, syövät sekoitettuja ohria, jotka viskimellä ja pohtimella ovat pohditut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Ja kaikkein suurten vuorten päällä, ja kaikkein suurten kukkulain päällä pitää eroitetut virrat käymän, suuren surmaamisen aikana, ja kuin tornit kaatuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Ja kuun valo on oleva kuin auringon paiste ja auringon paiste on oleva seitsemän kertaa kirkkaampi kuin seitsemän päivän kirkkaus; kuin Herra sitoo kansansa haavat, ja sen loukkaamat parantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Katso, Herran nimi tulee kaukaa, hänen vihansa polttaa ja on sangen raskas; hänen huulensa ovat hirmuisuutta täynnä, ja hänen kielensä on niinkuin kuluttava tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Ja hänen henkensä niinkuin tulvaava virta, joka hamaan kurkkuun asti ulottuu, hajoittamaan pakanoita, siihenasti että he tyhjäksi tulevat, ja ajamaan kansaa sinne ja tänne, suitsilla heidän suussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Silloin pitää teidän veisaaman niinkuin juhlayönä, ja sydämestänne riemuitseman niinkuin huiluilla käytäisiin Herran vuorelle, Israelin turvan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Ja Herra kuuluttaa kunniallisen äänensä, että hänen kokotettu käsivartensa nähtäisiin, vihaisella haastamisella, ja kuluttavaisen tulen liekillä, säteillä, väkevällä sateella ja rakehilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Sillä Assurin pitää peljästymän Herran ääntä, joka häntä lyö vitsalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Sillä vitsan pitää kyllä sattuman ja koskeman, kuin Herra sen vie heidän ylitsensä rummuilla ja kanteleilla, ja joka paikassa sotii heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Sillä kuoppa on jo entisestä valmistettu, ja se on myös kuninkaalle valmistettu, kyllä syvä ja leviä. Siellä on asumus, tuli ja paljo puita; Herran Henki on sen sytyttävä niinkuin jonkun tulikivisen virran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Voi niitä, jotka menevät alas Egyptiin apua kerjäämään, ja luottavat hevosiin, ja turvaavat vaunuihin, että niitä on monta, ja ratsasmiehiin, että he juuri väkevät ovat, eivätkä turvaa Israelin Pyhään, eikä kysy Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Mutta hän on viisas ja antaa tulla onnettomuuden, ja ei muuta sanojansa; vaan asettaa itsensä pahain huonetta vastaan, ja pahantekiäin apua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Sillä Egypti on ihminen ja ei Jumala, ja heidän hevosensa ovat liha ja ei henki. Ja Herra on kokottava kätensä, niin että auttajan pitää hoiperteleman, ja sen, jota autetaan, pitää lankeeman, ja ynnä molemmat toinen toisensa kanssa hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Sillä näin sanoo Herra minulle: niinkuin jalopeura ja nuori jalopeura kiljuu saaliinsa päällä, kuin paimenten joukko on kokoontunut sitä vastaan, ei peljästy heidän huudostansa, eikä hämmästy vaikka heitä monta on: juuri niin on Herra Zebaot menevä alas sotimaan Zionin vuorella ja sen korkeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Niinkuin linnut siivillänsä tekevät, niin Herra Zebaot on varjeleva Jerusalemin: hän on suojeleva, auttava, siellä oleva ja holhova häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Palatkaat, te Israelin lapset, sen tykö, josta te peräti harhailleet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Sillä silloin jokainen hylkää hopia- ja kulta-epäjumalansa, joita omat kätenne ovat tehneet teille synniksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Ja Assurin pitää lankeeman, ei miehen miekalla, ja pitää kulutettaman, ei ihmisen miekalla; ja pitää kuitenkin pakeneman miekkaa, ja hänen nuorukaisensa pitää verollisiksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Ja hänen pitää pelvon tähden menemän kallionsa ohitse, ja hänen pääruhtinaansa pitää lippunsa edestä pakoon menemän, sanoo Herra Zebaot, jolla Zionissa tuli ja Jerusalemissa totto on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Katso, kuningas on hallitseva oikeudella; ja pääruhtinaat vallitsevat, oikeutta pitämään voimassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Että jokainen on niinkuin joku, joka tuulelta varjeltu on, ja niinkuin joku, joka sadekuurolta on peitetty, niinkuin vesi-ojat kuivassa paikassa, niinkuin suuren vuoren varjo kuivassa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Ja näkeväiset silmät ei pidä pimenemän; ja kuulevaisten korvat pitää visun vaarin ottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Ja hulluin pitää oppiman taitoa, ja sopera kieli pitää selkeäksi tuleman ja selkeästi puhuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Ei hullua pidä enää pääruhtinaaksi kutsuttaman, eikä ahnetta herraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Sillä tyhmä puhuu tyhmyydessä, ja hänen sydämensä on pahuudessa; että hän olis ulkokullaisuudessa; ja saarnais Herrasta väärin, että hän sillä isoovaiset sielut nälkään näännyttäis, ja kieltäis janoovaisilta juoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Sillä ahneen hallitus ei ole muu kuin vahinko; sillä hän löytää kavaluuden hävittääksensä raadollisia väärillä sanoilla, silloinkin kun köyhä oikeuttansa puhuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mutta toimellinen päämies pitää toimellisia neuvoja; ja toimellisissa menoissa hän vahvana pysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Nouskaat, te suruttomat vaimot, kuulkaat minun ääntäni; te rohkiat tyttäret, ottakaat korviinne minun puheeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Ajastajan ja päivän perästä pitää teidän vapiseman, jotka niin rohkiat olette; sillä ei tule yhtään viinan eloa, eikä tule yhtään kokoomusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Peljästykäät, te suruttomat vaimot, vaviskaat, te rohkiat; te riisutaan, paljastetaan ja kupeista vyötetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Rinnoille lyödään valittaen ihanaisista pelloista ja hedelmällisistä viinapuista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Sillä minun kansani pellossa pitää orjantappurat ja ohdakkeet kasvaman; niin myös kaikissa ilohuoneissa, iloisessa kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Sillä salit pitää hyljättämän, ja kansan paljous kaupungissa pitää vähenemän; niin että tornit ja linnat pitää tuleman ijankaikkiseksi luolaksi, ja metsän pedoille iloksi, ja laumoille laitumeksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Siihenasti että Henki korkeudesta vuodatetaan meidän päällemme: silloin tulee korpi peltomaaksi, ja peltomaa luetaan metsäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Ja oikeus asuu korvessa, ja vanhurskaus peltomaassas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Ja vanhurskauden työ on rauha, ja vanhurskauden hyödytys ijankaikkinen hiljaisuus ja lepo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Niin että minun kansani on asuva rauhan huoneessa, turvallisissa majoissa ja jalossa levossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Mutta rakeet pitää oleman alhaalla metsissä; ja kaupungin pitää alhaalla mataloissa paikoissa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Hyvin teidän menestyy, jotka kylvätte joka paikassa vetten tykö; ja annatte härkäin ja aasein käydä jaloillansa niiden päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Voi sinuas hävittäjä! luuletkos, ettei sinun pidä hävitetyksi tuleman? ja sinuas ylönkatsoja! luuletkos, ettei sinua ylönkatsota? Koska sinä olet täyttänyt hävitykses, niin sinun myös pitää tuleman hävitetyksi; koska sinä olet täyttänyt ylönkatsees, niin sinua pitää jälleen katsottaman ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Herra, ole meille armollinen; sillä me odotamme sinua: ole heidän käsivartensa varhain, niin myös meidän autuutemme murheen ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Kansat pakenevat sitä suurta pauhinaa; pakanat hajoitetaan, kuin sinä korotetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Silloin pitää teidän saalinne korjattaman niinkuin perhonen otetaan, ja niinkuin heinäsirkat karkoitetaan, koska heidän päällensä tullaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Herra on korotettu; sillä hän asuu korkeudessa: hän on täyttänyt Zionin oikeudella ja vanhurskaudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Ja sinun ajallas pitää oleman usko ja voima, autuus, tieto, toimi, ja Herran pelko pitää oleman hänen tavaransa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Katso, heidän sanansaattajansa huutavat ulkona: rauhan enkelit itkevät haikiasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Polut ovat autiot, ei käy yksikään enään tiellä; ei hän pidä liittoa, hän hylkää kaupungit, ja ei pidä lukua kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Hän murehtii,ja maa on surkialla muodolla, Libanon on häpiällä hakattu; Saron on niinkuin tasainen keto, Basan ja Karmeli ovat hävitetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nyt minä tahdon nousta, sanoo Herra: nyt minä tahdon itseni korottaa, nyt minä tahdon korkiaksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Oljista olette te raskaat, korsia te synnytätte; tulen pitää teitä kuluttaman teidän ylpeytenne kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Sillä kansa pitää poltettaman kalkiksi, niinkuin hakatut orjantappurat tulelle sytytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Niin kuulkaat nyt te, jotka kaukana olette, mitä minä olen tehnyt; ja te, jotka olette läsnä, havaitkaat minun väkevyyteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Syntiset Zionissa ovat peljästyneet, hämmästys on tullut ulkokullattuin päälle (ja sanovat): kuka on meidän seassamme, joka taitaa asua kuluttavaisen tulen tykönä? kuka on meidän seassamme, joka voi asua ijankaikkisten hiilten tykönä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Joka vanhurskaudessa vaeltaa ja puhuu oikeutta; joka vääryyttä ja ahneutta vihaa, ja vetää kätensä pois, ettei hän ota lahjoja; joka tukitsee korvansa kuulemasta veren vikoja, ja peittää silmänsä näkemästä pahaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Hän on korkeudessa asuva, ja kalliot ovat hänen linnansa ja tukeensa: hänelle annetaan hänen leipänsä, eikä hän ole epäilevä vedestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Sinun silmäs näkevät kuninkaan kunniassansa: ne näkevät maan levitettynä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Sinun sydämes ihmettelee, (ja sanoo:) kussa nyt ovat kirjanoppineet? kussa ovat neuvonantajat? kussa tämän maailman tutkia on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Etkä myös sinä ole näkevä sitä väkevää kansaa, sitä syväkielistä kansaa, jota ei ymmärretä, ja oudosta kielestä, jota ei taideta ymmärtää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Katso Zionia, juhlakaupunkiamme; sinun silmäs on näkevä Jerusalemin kauniin asumuksen, majan, jota ei viedä pois, jonka paanuja ei ikänä pidä temmattaman ylös, ja jonka köysiä ei ikänä pidä katkottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Sillä Herra on siellä oleva väkevä meidän tykönämme, ja siellä pitää oleman leviät virrat ja ojat; ei venheellä taideta mennä sieltä ylitse, eikä laiva taida sinne purjehtia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Sillä Herra on meidän tuomarimme, Herra on meidän opettajamme; Herra on meidän kuninkaamme, hän auttaa meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Anna heidän pingoittaa köytensä, ei ne pidä kuitenkaan pitämän, niin ei pidä myös heidän hajoittaman lippua pielten päälle; sillä paljo kalliimpi saalis pitää jaettaman, niin että ontuvat myös ryöstävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Ja ei yhdenkään asuvaisen pidä sanoman: minä olen heikko; että kansalla, joka siellä asuu, pitää oleman syntein päästö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Tulkaat, te pakanat, ja kuulkaat, kansat ottakaat vaari; maa kuulkaan ja mitä siinä on, maan piiri ja kaikki, mitä siinä syntyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Sillä Herra on vihainen kaikille pakanoille, ja on närkästynyt kaikille heidän joukoillensa; hän on heitä kiroova, ja antaa teurastaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Heidän lyötynsä pitää heitettämän pois, niin että pahan hajun pitää tuleman heidän ruumiistansa, ja vuoret kuohuman heidän verestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Ja koko taivaan joukko pitää mätänemän, ja taivas pitää käärittämän kokon niinkuin kirja; ja kaikki hänen joukkonsa putooman niinkuin lehti putoo viinapuusta, ja niinkuin kuivettunut lehti fikunapuusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Sillä minun miekkani on taivaissa juovuksissa; ja katso, sen pitää tuleman alas Edomin päälle ja kirotun kansan päälle, sitä rankaisemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Herran miekka on verta täynnä, ja on paksu lihavuudesta, karitsain ja kauristen verestä, ja jääräin munaskuiden lihavuudesta; sillä Herralla pitää oleman uhri Botsrassa, ja suuri teurastaminen Edomin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Yksisarvillisten pitää myös kulkeman alas heidän kanssansa, ja mullit syötettyin härkäin kanssa; sillä heidän maansa pitää juopuman verestä, ja heidän multansa lihavaksi tuleman lihavuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Sillä ne ovat Herran kostopäivät, ja kostamisen vuodet, Zionin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Silloin sen ojat muutetaan pieksi, ja hänen multansa tulikiveksi; ja sen maakunta pitää muuttuman palavaksi pieksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Jonka ei pidä päivällä eikä yöllä sammuman, mutta savun pitää siitä ijankaikkisesti nouseman; ja se pitää hävitettämän suvusta sukuun, niin ettei yhdenkään pidä käymän sen lävitse ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Vaan ruovonpäristäjäin ja tarhapöllöin pitää sen omistaman, yökköin ja kaarneitten pitää siellä asuman; sillä hän on vetävä nuoran sen ylitse, niin että sen pitää autioksi tuleman, ja ojennuskiven, niin että sen pitää tyhjäksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Niin että sen herrat pitää kutsuttaman herroiksi ilman maakuntaa: ja kaikki sen pääruhtinaat pitää saaman lopun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Ja orjantappurat pitää kasvaman hänen salissansa, nokulaiset ja ohdakkeet sen linnoissa; ja pitää oleman lohikärmeitten asumasia ja yökköin laitumet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Silloin pitää metsän eläimet kohtaaman toinen toistansa, yhden liekkiön pitää toista huutaman; ja kauhiat yölinnut pitää myös siellä asumasiansa saaman ja siellä levon löytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Hyypiän pitää myös siellä pesänsä pitämän ja muniman, hautoman ja kuoriman sen varjon alla; ja korpihaukat parinensa pitää myös sinne kokoontuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Etsikäät nyt Herran kirjaa ja lukekaat: ei yhtään näistä pidä puuttuman, ei pidä näistä kaivattaman yhtä eli toista; sillä hän on se, joka minun suuni kautta käskee, ja hänen henkensä tuo sen kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Hän heittää arpaa heistä, ja kädellänsä jakaa mitan heidän seassansa; että heillä pitää siellä oleman perintö ijankaikkisesti, ja suvusta sukuun siellä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Korvet ja erämaat pitää iloitseman, ja autio sia pitää iloinen oleman, ja niinkuin kukkanen kukoistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Hän on kasvain vihoittava ja seisova riemuisna kaikessa ilossa ja riemussa; sillä Libanonin kunnia annetaan hänelle, Karmelin ja Saronin kaunistus; ja he näkevät Herran kunnian ja meidän Jumalan kauneuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Vahvistakaat väsyneet kädet, ja tuetkaat nääntyneet polvet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Sanokaat heikkomielisille: olkaat turvassa ja älkäät peljätkö; katso, teidän Jumalanne tulee kostamaan, Jumala, joka maksaa, hän tulee ja vapahtaa teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Silloin avataan sokiain silmät, ja kuuroin korvat aukenevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Silloin rammat hyppäävät niinkuin peurat, ja mykkäin kieli pakahtuu kiitokseen; sillä korvessa pitää vedet vuotaman, ja virrat erämaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Ja karkia paikka pitää järveksi tuleman, ja kuiva maa kuohuvaksi vedeksi; ja kuopassa, jossa kärme makasi, pitää heinän, ruovon ja kaislan oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Siinä myös pitää matka ja tie oleman, joka pitää pyhäksi tieksi kutsuttaman, ettei kenkään saastainen sitä vaeltaisi, ja se pitää heidän edessänsä oleman; jota käydään, niin ettei tyhmäkään eksy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Ei siellä jalopeura oleman pidä, eikä joku julma peto mene sitä myöten, eli sieltä löydetä; vaan lunastetut sitä vaeltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Herran lunastetut palajavat ja tulevat sen kautta riemulla Zioniin, ja ijankaikkinen ilo on oleva heidän päänsä päällä. Ilon ja riemun he käsittävät, ja murhe ja huokaus pitää pakeneman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Ja tapahtui kuningas Hiskian neljännellätoistakymmenennellä vuodella, että Assyrian kuningas Sanherib nousi kaikkia Juudan vahvoja kaupungeita vastaan, ja voitti ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Ja Assyrian kuningas lähetti Rabsaken Lakiksesta Jerusalemiin, kuningas Hiskian tykö, suurella väellä; ja hän astui edes ylimmäisen vesilammin kanavan päähän tiellä vanuttajan kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Ja hänen tykönsä menivät ulos Eliakim Hilkian poika, huoneenhaltia, ja Sebna kirjoittaja, ja Joah Assaphin poika, kansleri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Ja Rabsake sanoi heille: sanokaat siis Hiskialle: näin sanoo suuri kuningas, Assyrian kuningas: millainen on se turva, johonkas turvaat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Minä taidan arvata, ettäs luulet itselläs vielä olevan neuvoa ja voimaa sotiakses; keneen sinä siis luotat, ettäs olet minusta luopunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Katso, luotatkos musertuneeseen ruokosauvaan Egyptiin? joka silloin kuin nojataan sen päälle, menee käden lävitse ja pistää sen lävitse: niin on myös Pharao Egyptin kuningas kaikille niille, jotka häneen luottavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Ja jos sinä tahdot sanoa minulle: me luotamme Herraan meidän Jumalaamme: eikö hän ole se, jonka korkeudet ja alttarit Hiskia on heittänyt pois? ja sanonut Juudalle ja Jerusalemille: tämän alttarin edessä pitää teidän rukoileman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Lyö siis nyt veto herrani Assyrian kuninkaan kanssa; minä annan sinulle kaksituhatta hevosta, saa nähdä, jos sinä voit toimittaa niitä tyköäs, jotka niillä ajavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Kuinka sinä siis tahdot ajaa takaperin yhden sodanpäämiehen, joka minun herrani vähimmistä palvelioista on? Mutta sinä luotat Egyptiin, ratasten ja ratsasmiesten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Niin sinä luulet myös, että minä ilman Herraa olen lähtenyt maakuntaan sitä hävittämään? Herra sanoi minulle: mene ylös siihen maakuntaan ja hävitä se.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Mutta Eliakim, Sebna ja Joah sanoivat Rabsakelle: puhu palveliais kanssa Syrian kielellä, sillä me ymmärrämme kyllä sen, ja älä puhu Juudan kielellä meidän kanssamme, kansan kuullen, joka muurin päällä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Niin sanoi Rabsake: luuletkos minun herrani lähettäneen minun sinun herras, eli sinun tykös näitä sanoja puhumaan? ja ei paljo enemmin niille miehille, jotka istuvat muurin päällä, teidän kanssanne syömässä omaa lokaansa, ja juomassa omaa vettänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Ja Rabsake seisoi ja huusi vahvasti Juudan kielellä, ja sanoi: kuulkaat suuren kuninkaan sanoja, Assyrian kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Näin sanoo kuningas: älkäät antako Hiskian pettää teitänne; sillä ei hän voi teitä pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Ja älkäät antako Hiskian saattaa teidät turvaamaan Herraan, sanoen: kyllä Herra auttaa meitä: ei tätä kaupunkia anneta Assyrian kuninkaan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Älkäät kuulko Hiskiaa; sillä näin sanoo Assyrian kuningas: olkaat minun mieleni nouteeksi, ja tulkaat ulos minun tyköni, niin te syötte itsekukin viinapuustansa ja fikunapuustansa, ja juotte vettä kukin kaivostansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Siihenasti että minä tulen ja vien teidät senkaltaiseen maahan kuin teidänkin maanne on, maahan, jossa jyviä ja viinaa on, maahan, jossa leipää ja viinamäkiä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Älkäät antako Hiskian pettää teitänne, että hän sanoo: Herra pelastaa meitä. Ovatko myös pakanain jumalat jokainen maansa vapahtaneet Assyrian kuninkaan käsistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kussa ovat Hamatin ja Arpadin Jumalat? ja kussa ovat Sepharvaimin jumalat? ovatko he myös vapahtaneet Samarian minun kädestäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kuka näistä kaikista maan jumalista on auttanut maansa minun kädestäni? että Herra pelastais Jerusalemin minun kädestäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Mutta he olivat ääneti, ja ei vastanneet häntä mitään; sillä kuningas oli käskenyt ja sanonut: älkäät häntä mitään vastatko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Niin tulivat Eliakim Hilkian poika, huoneenhaltia, ja Sebna kirjoittaja ja Joah Assaphin poika, kansleri, Hiskian tykö, reväistyillä vaatteilla, ja ilmoittivat hänelle Rabsaken sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Kuin kuningas Hiskia tämän kuuli, repäisi hän vaatteensa, ja kääri säkin ympärillensä, ja meni Herran huoneeseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Ja lähetti Eliakimin, huoneenhaltian, ja Sebnan, kirjoittajan, ylimmäisten pappein kanssa, puettuna säkkeihin, propheta Jesaian Amotsin pojan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Sanomaan hänelle: näin sanoo Hiskia: tämä on vaivan, toran ja häväistyksen päivä; sillä lapset ovat tulleet synnyttämiselle ja ei ole voimaa synnyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Jospa siis Herra sinun Jumalas tahtois kuulla Rabsaken sanat, jonka hänen herransa Assyrian kuningas lähetti häpäisemään elävää Jumalaa, ja pilkkaamaan senkaltaisilla sanoilla kuin Herra sinun Jumalas on kuullut; ja ettäs tahtoisit korottaa rukoukses jääneiden edestä, jotka vielä käsissä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Ja kuningas Hiskian palveliat tulivat Jesaian tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Mutta Jesaia sanoi heille: näin sanokaat teidän herrallenne: Herra sanoo näin: älä pelkää niitä sanoja, joita sinä kuulit, joilla Assyrian kuninkaan palveliat ovat häväisseet minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Katso, minä annan hänelle hengen, ja hänen pitää saaman kuulla sanoman, ja palajaman omalle maallensa; ja minä tahdon kaataa hänen miekalla hänen maassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Mutta kuin Rabsake palasi, löysi hän Assyrian kuninkaan sotimasta Libnaa vastaan; sillä hän oli kuullut hänen matkustaneen Lakiksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Sillä sanoma tuli Tirhakasta Etiopian kuninkaasta, sanoen: hän on lähtenyt sotimaan sinua vastaan. Kuin hän tämän kuuli, lähetti hän sanan Hiskialle, ja käski hänelle sanoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Sanokaat Hiskialle Juudan kuninkaalle näin: älä anna sinun Jumalas pettää sinuas, johon sinä luotat, ja sanot: ei Jerusalem anneta Assyrian kuninkaan käteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Katso, sinä olet kuullut, mitä Assyrian kuninkaat kaikille maakunnille tehneet ovat, ja ne hävittäneet; ja sinä pelastettaisiin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Ovatko myös pakanain jumalat auttaneet niitä, joita minun isäni ovat hävittäneet, Gosanin ja Haranin, Resephin, ja Edenin lapset, jotka Telassarissa olivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kussa on Hamatin kuningas, ja Arphadin kuningas, ja Sepharvaimin, Henan ja Ivvan kaupungin kuningas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Ja kuin Hiskia oli saanut kirjan sanansaattajalta ja lukenut sen, meni hän ylös Herran huoneeseen, ja Hiskia levitti sen Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Ja Hiskia rukoili Herraa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Herra Zebaot, Israelin Jumala, joka istut Kerubimin päällä, sinä, joka olet ainoa Jumala kaikkein maakuntain ylitse maan päällä: sinä olet tehnyt taivaan ja maan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Herra, kallista korvas ja kuule, Herra, avaa silmäs ja näe: kuule siis kaikki Sanheribin sanat, joka on lähettänyt häpäisemään elävää Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Tosi se on, Herra, että Assyrian kuninkaat ovat autioksi tehneet kaikki valtakunnat heidän maakuntainsa kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Ja ovat heittäneet heidän Jumalansa tuleen; sillä ei ne olleet jumalat, vaan ihmisten kätten työt, puut ja kivet, ja ne he ovat hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Mutta nyt, Herra meidän Jumalamme, auta meitä hänen kädestänsä; että kaikki valtakunnat maan päällä ymmärtäisivät sinun ainoan olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Silloin lähetti Jesaia Amotsin poika Hiskian tykö, ja käski hänelle sanoa: näin sanoo Herra Israelin Jumala: (minä olen kuullut) sen, kuin sinä minua rukoillut olet Assyrian kuninkaan Sanheribin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Niin on tämä se minkä Herra hänestä sanoo: neitsy, Zionin tytär katsoo sinun ylön, ja pilkkaa sinua, ja Jerusalemin tytär vääntelee päätänsä sinun perääs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Ketäs olet pilkannut ja häväissyt? ketä vastaan sinä olet korottanut äänes? sinä olet nostanut silmäs Israelin Pyhää vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Sinun palveliais kautta olet sinä häväissyt Herraa, ja sanonut: minun monilla rattaillani olen minä mennyt ylös vuorten kukkuloille Libanonin puolelle, ja tahdon hakata maahan hänen korkiat sedripuunsa ja valitut honkansa, ja mennä kukkulain ylitse hänen ääreensä, hänen ihanan vainionsa metsään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Minä olen kaivanut ja juonut vettä; ja minun jalkapöytäni on kuivannut kaikki piiritetyt ojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Etkös ole kaukaa kuullut, että minä muinen juuri niin tehnyt ja sen toimittanut olen, ja vielä nyt niin teen, että vahvat kaupungit kukistetaan kiviraunioiksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Ja heidän asujansa voimattomiksi ja epäileväisiksi tulevat, ja häpiään joutuvat; ja tulevat niinkuin kedon ruoho ja viheriäinen ruoho, niinkuin ruoho kattoin päällä, joka ennen kuivettuu kuin tuleentuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Mutta minä tiedän sinun asumukses hyvin, sinun uloslähtemises ja sisällekäymises; ja sinun kiukuitsemises minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Ettäs kiukuitset minua vastaan, ja sinun ylpeytes on joutunut minun korvilleni, panen minä renkaani sinun sieraimiis ja suitseni sinun suuhus, ja vien sinun sitä tietä jälleen takaperin, jotas tullutkin olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Ja tämä pitää oleman sinulle merkiksi: syö tänä vuonna, mitä kasvanut on, toisena vuonna, mitä itsestänsä kasvaa, kolmantena vuonna kylväkäät ja leikatkaat, istuttakaat viinapuita, ja syökäät heidän hedelmäänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Ja pelastettuin ja jääneiden Juudan huoneesta pitää taas alhaalta juurtuman,ja ylhäältä kantaman hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Sillä Jerusalemista pitää vielä nyt jääneiden tuleman ulos, ja vapahdetut Zionin vuorelta. Tätä on Herran Zebaotin kiivaus tekevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Sentähden sanoo Herra Assyrian kuninkaasta näin: ei hänen pidä tuleman tähän kaupunkiin, eikä yhtään nuolta sinne ampuman, eli yhtä kilpeä tuoman sen eteen, taikka yhtään vallia tekemän sen ympärille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Vaan pitää palajaman sitä tietä takaperin, jota hän tullut on, ja ei tähän kaupunkiin ensinkään tuleman, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Sillä minä varjelen tämän kaupungin, niin että minä autan häntä, minun tähteni ja minun palveliani Davidin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Silloin läksi Herran enkeli ja löi Assyrian leirissä sata ja viisiyhdeksättäkymmentä tuhatta miestä. Ja kuin he varhain huomeneltain nousivat, katso, ne kaikki olivat kuolleiden ruumiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Ja Assyrian kuningas Sanherib läksi matkaansa ja palasi, ja asui Ninivessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Ja tapahtui, kuin hän rukoili jumalansa Nisrokin huoneessa, löivät hänen poikansa Adramelek ja Saretser hänen miekalla, ja pakenivat Araratin maalle. Ja hänen poikansa Assarhaddon tuli kuinkaaksi hänen siaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Silloin tuli Hiskia kuoleman kieliin. Ja propheta Jesaia Amotsinpoika tuli hänen tykönsä ja sanoi hänelle: näin sanoo Herra: toimita talos, sillä sinun pitää kuoleman ja ei elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Niin käänsi Hiskia kasvonsa seinään päin, ja rukoili Herraa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Ja sanoi: ah Herra, muista, kuinka minä sinun edessäs olen totuudessa ja vaalla sydämellä vaeltanut, ja olen tehnyt mitä sinulle on ollut otollinen! ja Hiskia itki katkerasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Ja Herran sana tuli Jesaian tykä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Mene ja sano Hiskialle: näin sanoo Herra sinun isäs Davidin Jumala: Minä olen kuullut sinun rukoukses ja nähnyt sinun kyynelees; katso, minä lisään vielä nyt sinun päiviis viisitoistakymmentä vuotta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Ja minä vapahdan sinun ja tämän kaupungin Assyrian kuninkaan kädestä, ja tahdon hyvin varjella tämän kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Ja tämä olkoon sinulle merkiksi Herralta, että Herra on tämän tekevä niinkuin hän on sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Katso, minä tahdon vetää varjon takaperin Ahaksen Säijäristä, kymmenen juonta, kuin hän on juossut ylitse; ja niin aurinko kävi takaperin kymmenen juonta, jotka hän Säijärissä oli juossut ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Tämä on Hiskian Juudan kuninkaan kirjoitus, kuin hän sairastanut oli, ja taudistansa terveeksi tullut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Minä sanoin minun päiviäni lyhennettäissä: nyt minun täytyy mennä haudan ovelle, ja vuoteni lopettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Minä sanoin: en minä enää Herraa näe, Herraa eläväin maassa; en minä enään ihmisiä näe niiden seassa, jotka maailmassa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Minun aikani kului ja on minulta otettu pois, niinkuin paimenen maja; ja minä leikkasin poikki elämäni niinkuin kankuri. Hän katkaisi minun niinkuin hienon langan, sinä lopetat minun huomenesta ehtooseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Minä asetin itseni niinkuin jalopeura aamuun asti; kuitenkin särki hän kaikki minun luuni; sinä lopetat minun huomenesta ehtooseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Minä kuikutin niinkuin kurki ja pääskynen, ja vaikeroitsin ninkuin mettinen; minun silmäni rupesivat puhkeemaan; Herra, minä kärsin tuskaa, huojenna se minulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Mitä minun pitää puhuman, että hän sen minulle lupasi, ja teki myös sen? Sentähden minä tahdon kaikkena elinaikanani tämän minun sieluni murheen tähden kartella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Herra, siitä eletään, ja minun henkeni elämä on siinä kokonansa; sillä sinä annoit minun nukkua, ja teit minun taas eläväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Katso, suuri hätä oli minulla turvasta; mutta sinä olet minun sieluni sydämellisesti vapahtanut, ettei se hukkuisi; sillä sinä heitit kaikki minun syntini selkäs taa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Sillä ei helvetti sinua kiitä, eikä kuolema sinua ylistä; ei myös ne sinun totuuttas odota, jotka alas kuoppaan menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Vaan ainoastansa elävät kiittävät sinua, niinkuin minäkin nyt teen; isän pitää lapsillensa sinun totuuttas ilmoittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Herra, auta minua; niin me veisaamme minun veisuni, niinkauvan kuin me elämme, Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Ja Jesaia käski ottaa voidetta fikunista ja panna paisuman päälle, että se tulis terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Mutta Hiskia sanoi: mikä merkki on, että minun pitää menemän ylös Herran huoneeseen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Silloin lähetti Merodak Baladan, Baladanin poika, Babelin kuningas kirjoituksen ja lahjoja Hiskialle; sillä hän oli kuullut hänen sairastaneen, ja tulleen terveeksi jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Niin Hiskia tuli iloiseksi heidän kanssansa, ja näytti heille tavarahuoneensa, hopian ja kullan, yrtit, kalliit voiteet, ja kaikki asehuoneensa, ja kaiken tavaran, mikä hänellä oli; ei ollut mitään, jota ei Hiskia heille näyttänyt, hänen huoneessansa ja hänen takanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Niin tuli propheta Jesaia kuningas Hiskian tykö, ja sanoi hänelle: mitä nämät miehet ovat sanoneet, ja kusta he sinun tykös ovat tulleet? Hiskia sanoi: he ovat tulleet kaukaiselta maalta minun tyköni, aina Babelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Mutta hän sanoi: mitä he ovat nähneet sinun huoneessas? Hiskia sanoi: kaikki mitä minun huoneessani on, ovat he nähneet, ja ei ole mitään minun tavaroissani, jota en minä ole näyttänyt heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Ja Jesaia sanoi Hiskialle: kuule Herra Zebaotin sana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Katso, se aika tulee, että kaikki, mitä sinun huoneessas on, ja mitä sinun isäs koonneet ovat tähän päivään asti, pitää vietämän pois Babeliin; niin ettei mitään pidä jäämän, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Heidän pitää myös ottaman sinun lapses, jotka sinusta tulevat, ja sinulle synnytetään; ja heidän pitää oleman kamaripalvelioina Babelin kuninkaan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Ja Hiskia sanoi Jesaialle: Herran sana on hyvä, jonka sinä puhunut olet. Ja sanoi: olkoon kuitenkin rauha ja uskollisuus minun päivinäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Lohduttakaat, lohduttakaat minun kansaani, sanoo teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Puhukaat suloisesti Jerusalemin kanssa, ja saarnatkaat hänelle, että hänen sotimisensa on täytetty; sillä hänen rikoksensa on annettu anteeksi, että hän on saanut kaksinkertaisesti Herran kädestä, kaikkein synteinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Huutavaisen ääni on korvessa: valmistakaat Herran tietä, tehkäät tasaiset polut erämaassa meidän Jumalallemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Kaikki laaksot pitää korotettaman, ja kaikki vuoret ja kukkulat pitää alennettaman, ja mitä on tasoittamatta, pitää tasattaman ja koliat silitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Sillä Herran kunnia ilmoitetaan: ja kaikki liha on ynnä näkevä Herran suun puhuvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Ääni sanoo: saarnaa. Ja hän sanoi: Mitä minun pitää saarnaaman? Kaikki liha on ruoho, ja kaikki hänen hyvyytensä niinkuin kedon kukkanen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Ruoho kuivuu pois ja kukkanen lakastuu, sillä Herra puhalsi siihen. Kansa tosin on ruoho.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Ruoho kuivettuu ja kukkanen lakastuu; mutta meidän Jumalamme sana pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Zion, sinä suloinen saarnaaja, astu korkialle vuorelle; Jerusalem, sinä suloinen saarnaaja, korota äänes väkevästi: korota ja älä pelkää; sano Juudan kaupungeille: katso, teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Sillä katso, Herra, Herra tulee väkevyydessä, ja hänen käsivartensa on hallitseva: katso, hänen palkkansa on hänen myötänsä, ja hänen tekonsa on hänen edessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Niinkuin paimen on hän kaitseva laumaansa, kokoo karitsat syliinsä ja kantaa helmassansa: tiineet lampaat hän johdattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kuka on vedet pivollansa mitannut, ja käsittänyt vaaksallansa taivaat? ja maan tomun sulkenut kolmannekseen? ja vuoret puntarilla punninnut, ja kukkulat vaalla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kuka on Herran henkeä opettanut? eli kuka on hänen neuvonantajansa ollut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Keneltä hän neuvoa kysyy, joka hänelle ymmärrystä antais, ja opettais hänelle oikeuden tien, ja antais hänelle tiedon, ja opettais hänelle ymmärryksen tien?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Katso, pakanat ovat niinkuin pisara, joka jää ämpäriin, ja niinkuin rahtu, joka jää vaakaan; katso, luodot hän kuljettaa niinkuin piskuisen tomun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Libanon olis sangen vähä tuleksi; ja hänen eläimensä ylen harvat polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Kaikki pakanat ovat niinkuin ei mitään hänen edessänsä, ja juuri tyhjän ja turhan edestä pidetään häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Keneenkä te tahdotte verrata Jumalaa? eli mitä kuvaa te tahdotte hänelle tehdä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Seppä valaa kuvan, ja hopiaseppä kultaa sen ja tekee siihen hopiakäädyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Niin myös jolla vähä vara on tehdä ylennysuhria, hän valitsee puun, joka ei mätäne, ja etsii siihen taitavan tekiän valmistamaan kuvaa, joka on kestäväinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Ettekö te tiedä? ettekö te kuule? eikö tämä ole ennen teille ilmoitettu? ettekö te ole sitä ymmärtäneet maan alusta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Hän istuu maan piirin päällä, ja ne, jotka sen päällä asuvat, ovat niinkuin heinäsirkat; joka taivaan venyttää niinkuin ohukaisen nahan, ja levittää sen niinkuin teltan, asuttavaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Joka pääruhtinaat tyhjäksi tekee, ja hävittää tuomarit maan päältä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Niinkuin ei he olisi istutetut, eikä kylvetyt, eli heidän kantonsa juurtuneet maahan; niin että he kuivettuvat, kuin tuuli heidän päällensä puhaltaa, ja tuulispää vie heidät matkaansa niinkuin akanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Keneenkä te siis minun verrata tahdotte, jonka kaltainen minä olisin? sanoo Pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Nostakaat silmänne korkeuteen ja katsokaat, kuka ne kappaleet luonut on, ja vie edes heidän joukkonsa luvulla? kutsuu ne kaikki nimeltänsä? Hänen varansa ja väkevä voimansa on niin suuri, ettei häneltä mitään puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Miksis siis sinä Jakob sanot, ja sinä Israel puhut: minun tieni on Herralta salattu, ja minun oikeuteni käy minun Jumalani ohitse?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Etkös tiedä? etkös ole kuullut? Herra ijankaikkinen Jumala, joka maan ääret on luonut, ei väsy eikä näänny; hänen ymmärryksensä on tutkimatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Hän antaa väsyneille voiman, ja väettömille kyllä väkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Nuorukaiset väsyvät ja nääntyvät, ja nuoret miehet peräti lankeevat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Mutta jotka Herraa odottavat, ne saavat uuden voiman, niin että he menevät siivillä ylös kuin kotkat; että he juoksevat ja ei näänny, he vaeltavat ja ei väsy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Luodot olkaan ääneti minun edessäni, ja kansa vahvistukoon; astukaan edes ja puhukaan: käykäämme oikeudelle toinen toisemme kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kuka on herättänyt vanhurskaan idästä? kuka hänen kutsui käymään? kuka antoi pakanat ja kuninkaat hänen eteensä, että hän tuli voimalliseksi heidän päällensä, ja antoi heidän hänen miekallensa niinkuin tomun, ja hänen joutsellensa niinkuin akanat, jotka hajoitetaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Ja hän ajoi heitä takaa, ja pääsi rauhassa sitä tietä, jota ei hänen jalkansa ennen käyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kuka tekee ja toimittaa sen, ja kutsuu sukukunnat alusta? Minä Herra olen ensimäinen, niin myös viimeinen, itse minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Kuin luodot näkivät sen, pelkäsivät he, ja maan ääret peljästyivät; he lähestyivät ja astuivat edes,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Auttivat toinen toistansa, ja sanoivat lähimmäisellensä: ole hyvässä turvassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Puuseppä rohkaisi hopiaseppää, joka tasoitti vasaralla alasimen päällä, ja sanoi: kyllä se pysyy, ja he vahvistivat sen nauloilla, ettei se sinne tänne huljuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Mutta sinä Israel, minun palveliani Jakob, jonka minä olen valinnut, sinä Abrahamin minun ystäväni siemen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Jonka minä olen ottanut maailman äärestä, ja olen sinun kutsunut hänen voimallisistansa, ja sanoin sinulle: minun palveliani sinä olet; sillä minä valitsin sinun, ja en hylkää sinua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Älä pelkää, sillä minä olen sinun kanssas; älä harhaile; sillä minä olen sinun Jumalas: minä vahvistan sinun, minä autan myös sinua, ja tuen myös sinun vanhurskauteni oikialla kädellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Katso, kaikki ne jotka ovat ankarat sinua vastaan, pitää häpiään tuleman ja häpeämän; ja ne miehet, jotka sinun kanssas riitelevät, pitää joutuman niinkuin tyhjäksi ja hukkuman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Niin että sinun pitää kysymän heitä, ja ei löytämän. Ne miehet, jotka sinun kanssas riitelevät, pitää tuleman niinkuin ei mitään, ja ne miehet, jotka sotivat sinua vastaan, pitää saaman loppunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Sillä minä olen Herra sinun Jumalas, joka tartun sinun oikiaan kätees ja sanon sinulle: älä pelkää, minä autan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Älä siis pelkää, sinä mato Jakob, te vähä joukko Israel, minä autan sinua, sanoo Herra ja sinun vapahtajas, Israelin Pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Katso, minä olen sinun tehnyt uudeksi teräväksi rautaiseksi varstaksi, että sinä tapat vuoria, ja muserrat ne, ja teet kukkulat niinkuin akanaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Sinun pitää hajoittaman heitä, niin että tuuli vie heidät pois, ja tuulispää viskoo heidät sinne ja tänne; mutta sinä iloitset Herrassa, ja kerskaat Israelin Pyhästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Raadolliset ja köyhät etsivät vettä; ja ei ole; heidän kielensä kuivettuu janosta; mutta minä, Herra, tahdon heitä kuulla, minä Israelin Jumala en tahdo heitä hyljätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Vaan minä avaan virrat korkeilla paikoilla, ja lähteet keskellä ketoja; minä teen korven vesilammikoksi ja kuivan maan luontolähteiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Minä annan korvessa sedripuita, sittimipuita, myrttejä, ja öljypuita; minä annan kedolla honkia, böökejä ja buksipuita ynnä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Nähtää, tuta ja ymmärtää ja huomattaa, että Herran käsi on nämät tehnyt, ja Israelin Pyhä on nämät luonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Antakaat siis teidän asianne tulla edes, sanoo Herra; antakaat teidän väkevänne tulla edes, sanoo Jakobin kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Anna heidän astua edes ja ilmoittaa meille tulevaisia asioita, ilmoittakaat ja ennustakaat jotain edellä, ja me tahdomme ottaa sydämellemme vaarin ja ajatella, kuinka tästedes tuleva on, eli antakaat meidän kuulla, mitä tuleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Ilmoittakaat, mitä tästedes on tuleva, niin me ymmärrämme teidän olevan jumalat; tehkäät hyvää eli pahaa, niin me puhumme siitä ja katselemme ynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Katso, te olette tyhjästä, ja teidän tekonne on myös tyhjästä; ja joka teitä valitsee, se on kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Mutta minä herätän yhden pohjasta, ja hän tulee; idästä hän on heille saarnaava minun nimeeni; ja hän käy voimallisten päällä niinkuin saven, ja sotkuu savea niinkuin savenvalaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kuka taitaa jotain ilmoittaa alusta, että me ymmärtäisimme? eli ennustaa edellä, että me sanoa mahtaisimme: sinä olet vanhurskas. Mutta ei tässä ole yhtään ilmoittajaa, ei yhtään joka jotain antaa kuulla, ei yhtään joka teidän sanojanne kuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Minä olen ensimäinen, joka sanon Zionille; katso, siellä on se; ja tahdon antaa Jerusalemille suloisen saarnaajan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Mutta minä katselen, ei siellä ole ketään, ja katson heidän keskellänsä, mutta ei siellä ole yhtään neuvonantajaa; minä kysyn heiltä, ja heidän pitäis vastaaman minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Katso, se on kaikki vääryys, heidän työnsä on turha; heidän epäjumalansa ovat tuuli ja tyhjyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Katso, minun palveliani, minä häntä tuen, ja minun valittuni, jossa minun sieluni mielistyi. Minä olen hänelle minun Henkeni antanut, hänen pitää oikeuden saattaman pakanoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Ei hän huuda, eikä riitele, ja hänen ääntänsä ei kuulla kaduilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Särjettyä ruokoa ei hänen pidä murentaman, ja suitsevaista kynttilän sydäntä ei pidä hänen sammuttaman; hän saattaa oikeuden totuudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Ei hänen pidä nurjan eikä hirmuisen oleman, sillä hänen pitää oikeuden maan päälle säätämän; ja luodotkin pitää hänen lakiansa odottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Näitä sanoo Herra Jumala, joka luo taivaat, ja venyttää ne, joka levittää maan, ja hänen kasvonsa; joka kansalle, joka sen päällä on, hengittämisen antaa, ja hengen niille, jotka siinä käyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Minä Herra olen sinun kutsunut vanhurskaudessa, ja rupesin sinun kätees, ja varjelin sinua, ja olen sinun antanut kansoille liitoksi ja pakanoille valkeudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Avaamaan sokiain silmiä, ja vankeja pelastamaan vankeudesta, ja tornista niitä, jotka pimeydessä istuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Minä Herra, se on minun nimeni: en minä anna toiselle kunniaani, enkä ylistystäni epäjumalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Katso, entiset ovat tapahtuneet, ja vastuutista minä ilmoitan; ennenkuin se tapahtuu, annan minä teidän sen kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Veisatkaat Herralle uutta veisua; hänen ylistyksensä on maailman äärestä, jotka meressä vaellatte, ja mitä siinä on, luodot, ja jotka niissä asutte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Huutakaat korkiasti, te korvet ja kaupungit niissä, ja ne kylät, joissa Kedar asuu; riemuitkaan ne, jotka kallioissa asuvat, ja huutakaan vuorten kukkuloilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Antakaan Herralle kunnia, ja hänen nimensä luodoissa ilmoittakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Herra käy niinkuin sankari ulos, hän herättää kiivautensa niinkuin sotamies; hän riemuitsee ja huutaa, hän voittaa vihollisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Vanhasta minä olen vaiti ollut, olin hiljainen ja pidätin itseni; mutta nyt minä tahdon huutaa niinkuin synnyttäjä, minä tahdon hävittää ja kaikki niellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Minä hävitän vuoret ja kukkulat, ja annan kaikki heidän ruohonsa kuivua; minä teen virrat luodoiksi, ja järvet kuivaan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Mutta sokiat minä johdatan sitä tietä, jota ei he tiedä, minä vien heidät niitä polkuja, joita ei he tunne; minä teen heille pimeyden valkeudeksi ja kolian tasaiseksi, näitä tahdon minä heille tehdä, ja en hylkää heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Mutta niiden pitää kääntymän takaperin, ja häpiään tuleman, jotka uskaltavat epäjumaliin ja sanovat valetuille kuville: te olette meidän Jumalamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Kuulkaat, te kuurot, ja katsokaat, te sokiat, että te näkisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kuka on niin sokia kuin minun palveliani? ja kuka on niin kuuro kuin minun käskyläiseni, jonka minä lähetän? Kuka on niin sokia kuin se täydellinen? ja niin sokia kuin Herran palvelia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Sinä näet paljon, ja et kuitenkaan pidä; korvat ovat avoimet, ja ei kenkään kuule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Kuitenkin suo Herra heille hyvää vanhurskautensa tähden, hän tekee lakinsa suureksi ja kunnialliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Mutta se on raadeltu ja ryöstetty kansa; he ovat kaikki saadut kiinni kuopasta, ja vankein huoneeseen lymytetyt; he ovat tehdyt saaliiksi, eikä ole yhtään auttajaa, raadellut, ja ei kuitenkaan sano: tuo ne jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kuka on teidän seassanne, joka näitä ottaa korviinsa? hän havaitkaan ja kuulkaan, mitä tästedes tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kuka on Jakobin raatelukseksi antanut, ja Israelin ryöväreille? Eikö Herra itse, jota vastaan me syntiä tehneet olemme? Ja ei he tahtoneet hänen teillänsä vaeltaa, eikä totelleet hänen lakiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Sentähden on hän heidän päällensä vuodattanut vihansa hirmuisuuden ja väkevän sodan: ja on heidät sytyttänyt ympäri, mutta ei he tunteneet, ja hän sytytti heitä, mutta ei he sitä ottaneet mieleensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Ja nyt, näin sanoo Herra, joka sinun, Jakob, loi, ja joka sinun, Israel, teki: älä pelkää; sillä minä olen sinun lunastanut; minä olen sinun nimeltäs kutsunut, sinä olet minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Sillä jos sinä vesissä käyt, niin minä olen tykönäs, ettei virrat sinua upota; ja jos sinä tulessa käyt, et sinä pala, ja liekin ei pidä sinua sytyttämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Sillä minä olen Herra sinun Jumalas, Israelin Pyhä, sinun vapahtajas. Minä olen Egyptin, Etiopian ja Seban antanut edestäs sovinnoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Ettäs niin kalliiksi olet luettu minun silmäini edessä, niin sinä olet myös kunniallisena pidetty, ja minä rakastin sinua, ja annan sentähden ihmiset sinun edestäs, ja kansat sinun sielus edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Älä siis nyt pelkää; sillä minä olen sinun tykönäs; idästä tahdon minä siemenes saattaa, ja lännestä tahdon sinua koota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Minä tahdon sanoa pohjoiselle: tuo tänne, ja etelälle: älä kiellä. Tuo tänne minun poikani taampaa, ja minun tyttäreni hamasta maailman ääristä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Kaikki, jotka minun nimelläni ovat nimitetyt, jotka minä luonut olen, valmistanut ja tehnyt minun kunniakseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Tuo edes sokia kansa, jolla kuitenkin silmät ovat, ja kuurot, joilla kuitenkin korvat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Anna kaikki pakanat tulla kokoon, ja kansan kokoontua, kuka on heidän seassansa, joka näitä ilmoittaa tietää, ja kuuluttaa meille edellä, mitä tapahtuman pitää? Anna heidän tuoda edes todistuksensa ja asiansa oikiaksi tehdä, niin saadaan kuulla, ja sanoa: se on totuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Mutta te olette minun todistajani, sanoo Herra, ja minun palveliani, jonka minä valitsin, että te tietäisitte, ja uskoisitte minua, ja ymmärtäisitte, että minä se olen. Ei yhtään Jumalaa ole minun edelläni tehty, ei myös kenkään tule minun jälkeeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Minä, minä olen Herra, ja paitsi minua ei ole yhtään vapahtajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Minä sen olen ilmoittanut, ja olen myös auttanut, ja olen sen teille antanut sanoa, ja ei ole muukalainen (Jumala) teidän seassanne: ja te olette minun todistajani, sanoo Herra, ja minä olen Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Ja minä olen itse ennenkuin joku päivä olikaan, ja ei kenkään voi minun kädestäni pelastaa; minä vaikutan, ja kuka tahtoo sitä estää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Näin sanoo Herra teidän lunastajanne, Israelin Pyhä: teidän tähtenne olen minä lähettänyt Babeliin, ja olen kukistanut kaikki teljet, ja ajanut murheelliset Kaldealaiset haaksiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Minä olen Herra teidän Pyhänne, joka Israelin luonut olen, teidän Kuninkaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Näin sanoo Herra, joka tien tekee meressä ja polun väkevässä vedessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Joka vie rattaan ja hevosen, joukon ja voiman, niin että he yhdessä roukkiossa makaavat, eikä nouse; he sammuvat, niinkuin kynttilän sydän sammuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Älkäät muistelko entisiä, ja älkäät pitäkö lukua vanhoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Sillä katso, minä teen uutta, juuri nyt pitää sen tuleman edes; ettekö te ymmärrä sitä? minä teen tietä korpeen, ja virtoja erämaihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Että eläimet kedolla kunnioittavat minua, lohikärmeet ja yököt; sillä minä annan vettä korvessa, ja virrat erämaassa, antaakseni kansalleni, valituilleni juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Tämän kansan olen minä minulleni valmistanut: sen pitää minun ylistykseni julistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Ja et sinä Jakob huutanut minua avukses, ja et sinä Israel ole työtä tehnyt minun tähteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Etpä sinä minulle tuonut edes polttouhris lampaita, etkä kunnioittanut minua sinun uhrillas. En minä sinua saattanut ruokauhrias uhraamaan, enkä myös vaatinut sinua pyhää savuas tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Etpä sinä minulle ostanut rahalla hajavaa kalmusta, et myös minua uhris rasvalla täyttänyt; vaan sinä sait minun työtä tekemään sinun synnissäs, ja olet tehnyt minulle vaivaa sinun pahoissa teoissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Minä, minä pyyhin sinun ylitsekäymises pois minun tähteni, ja en muista sinun syntejäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Muistuta minulle, koetelkaamme oikeudella: sano sinä, millä tavalla sinä tahdot vanhurskaaksi tulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Sinun ensimäinen isäs on syntiä tehnyt, ja sinun opettajas ovat minua vastaan vääryyttä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Sentähden minä saastutin pyhät esimiehet, ja olen antanut Jakobin raatelukseksi, ja Israelin pilkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Niin kuule nyt, minun palveliani Jakob, ja Israel, jonka minä valitsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Näin sanoo Herra, joka sinun tehnyt ja valmistanut on äitis kohdusta, joka sinua auttaa: älä pelkää, minun palveliani Jakob, ja sinä hurskas, jonka minä valitsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Sillä minä tahdon vuodattaa vedet janoovaisen päälle, ja virrat kuivan päälle; minä tahdon vuodattaa henkeni sinun siemenes päälle, ja siunaukseni jälkeentulevaistes päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Että he kasvaisivat niinkuin ruoho, ja niinkuin pajut vesivirtain tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Tämän pitää sanoman: Herran minä olen, ja se pitää Jakobin nimellä kutsuttaman, ja tämän pitää itsensä omalla kädellänsä Herralle kirjoittaman, ja pitää nimitettämän Israelin nimellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Näin sanoo Herra Israelin kuningas, ja hänen pelastajansa Herra Zebaot: minä olen ensimäinen ja minä olen viimeinen, ja paitsi minua ei ole yhtään Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Ja kuka on minun kaltaiseni, joka kutsuu ja ilmoittaa sen, ja sen minulle valmistaa? minä, joka asetan kansat maailman alusta: anna heidän ilmoittaa merkkejä ja mitä tuleva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Älkää peljätkö ja älkäät hämmästykö. Enkö minä silloin antanut kuulla, ja ilmoittaa sitä sinulle? Sillä te olette minun todistajani. Onko joku Jumala paitsi minua? Ei ole yhtään turvaa, en minä tiedä ketään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Epäjumalain tekiät ovat kaikki turhat, ja joista he paljon pitävät, ei ne ole mitään tarpeelliset; he ovat heidän todistajansa, ja ei näe mitään, eikä mitään ymmärrä: sentähden pitää heidän häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kutka ovat ne, jotka Jumalan tekevät, ja valavat epäjumalan, joka ei mihinkään kelpaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Katso, kaikki heidän kumppaninsa tulevat häpiään, sillä he ovat tekiät ihmisistä. Jos he kaikki kokoontuisivat ja astuisivat edes, niin heidän pitää kuitenkin pelkäämän ja häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Rautaseppä tarttuu rautaan pihdeillä, pitää sen hiilissä ja valmistaa sen vasaralla, ja takoo sitä kaikella käsivartensa väellä; kärsii myös nälkää, siihenasti ettei hän enää voi, eikä juo vettä, siihenasti että hän väsyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Puuseppä veistelee puuta, ja mittaa sitä nuoralla, ja arvoittelee sen langalla, ja hakkaa sen, ja piirittää sen sirkkelillä; ja tekee sen miehen kuvaksi, niinkuin kauniiksi ihmiseksi, jonka pitäis asuman huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Hän hakkaa sedripuita, ja ottaa böökiä ja tammea, joka metsän puiden seassa vahvistuu, ja sedripuuta, joka istutettu on ja sateesta on kasvanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Joka kelpaa ihmiselle polttaa, ja josta lämmitellä saadaan, jonka palamisella myös leipää kypsennetään; siitä hän myös tekee Jumalan, ja palvelee sitä; hän tekee siitä epäjumalan ja lankee sen eteen polvillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Puolen polttaa hän tulessa, ja toisen puolen tykönä syö hän lihaa, hän paistaa paistin ja ravitsee itsensä, lämmittää myös itsiänsä, ja sanoo: hoi! minä olen lämmin, että sain nähdä tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Mutta mitä siitä jää, siitä tekee hän jumalan epäjumalaksensa; sen eteen lankee hän polvillensa, ja kumartelee sitä, rukoilee ja sanoo: vapahda minua, sillä sinä olet minun jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Ei he tiedä eikä ymmärrä mitään; sillä he ovat sovaistut, niin että heidän silmänsä ei näe mitään, ja heidän sydämensä ei äkkää mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Ja ei he johdata sydämeensä, ei ole siinä yhtään tointa eli järkeä, että he sittenkin ajattelisivat: minä olen puolen polttanut tulessa, ja olen hiilillä kypsentänyt leipiä, ja paistanut lihaa ja syönyt; pitäiskö minun nyt tekemän sen, mikä jäänyt on, kauhistukseksi? ja pitäiskö minun kumartaman kantoa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Hän ravitsee itsiänsä tuhalla, hänen vimmattu sydämensä pettää hänen, ettei hän taida sieluansa pelastaa, eikä ajattele: eikö petos ole minun oikiassa kädessääni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Ajattele näitä, Jakob ja Israel, sillä sinä olet minun palveliani; minä olen sinun valmistanut, ettäs minun palveliani olisit, Israel, älä minua unohda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Minä pyyhin sinun pahat tekos pois niinkuin pilven, ja sinun syntis niinkuin sumun; käännä sinuas minun puoleeni, sillä minä sinun lunastin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Iloitkaat te taivaat, sillä Herra itse sen teki; riemuitse sinä maa täällä alhaalla, paukkukaat te vuoret ihastuksella, metsä ja kaikki hänen puunsa; sillä Herra lunasti Jakobin, ja on Israelissa kunniallinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Näitä sanoo Herra sinun lunastajas, joka sinun äitis kohdusta valmistanut on: minä olen Herra joka kaikki teen, joka taivaat yksinäni venytän, ja levitän maan ilman apulaista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Joka noitain merkit tyhjäksi teen, ja tietäjät teen hulluksi; joka viisaat ajan takaperin, ja heidän taitonsa teen hulluudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Mutta hän vahvistaa palveliansa sanan ja käskyläistensä neuvon täyttää. Joka Jerusalemille sanon: ole asuva: ja Juudan kaupungeille: olkaat rakennetut, ja heidän aukionsa minä nostan ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Joka syvyydelle sanon: tule kuivaksi: minä tahdon sinun virtas kuivata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Joka sanon Korekselle: hän on minun paimeneni, ja hänen pitää kaiken minun tahtoni täyttämän; niin että Jerusalemille sanotaan: ole rakennettu, ja templille: ole perustettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Näin sanoo Herra voidellullensa Korekselle, jonka oikiaan käteen minä rupeen: minä taivutan pakanat hänen eteensä, ja päästän kuningasten miekat heidän suoliltansa, että ovet avataan hänen eteensä, eikä uksia suljeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Minä tahdon käydä sinun edelläs, ja tehdä koliat tasaisiksi; minä tahdon rikkoa vaskiovet, ja särkeä rautateljet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Ja annan sinulle salatut tavarat ja kätketyt kalliit kalut, että ymmärtäisit minun olevan Herran Israelin Jumalan, joka sinun nimeltäs kutsun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Jakobin minun palveliani tähden, ja Israelin minun valittuni tähden: minä kutsuin sinun nimeltäs, ja nimitin sinun, kuin et sinä minua vielä tuntenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Minä olen Herra, ja ei yksikään muu; paitsi minua ei ole yhtään Jumalaa. Minä varustin sinun, kuin sinä et vielä minua tuntenut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Että sekä idästä ja lännestä ymmärrettäisiin, ettei ilman minua mitään ole. Minä olen Herra, ja ei kenkään muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Minä joka teen valkeuden ja luon pimeyden, minä joka annan rauhan ja luon pahan; minä olen Herra, joka kaikki nämät teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Te taivaat, tiukkukaat ylhäältä, ja pilvet satakoon vanhurskauden; maa avatkoon itsensä ja kantakoon autuuden, ja vanhurskaus kasvakoon myös. Minä Herra luon sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Voi sitä, joka riitelee Luojansa kanssa, saviastia savenvalajan kanssa. Sanoneeko savi savenvalajalle: mitäs teet? et sinä osoita kättäs sinun teossas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Voi sitä, joka isälle sanoo: miksis minun olet siittänyt? ja vaimolle: miksis minun synnytit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Näin sanoo Herra, Israelin Pyhä ja tekiä: anokaat minulta tulevaisia merkkejä, neuvokaat lapseni ja kätteni työ minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Minä olen tehnyt maan, ja luonut ihmisen sen päälle; minä olen se, jonka kädet ovat levittäneet taivaan, ja antanut käskyn kaikelle sen joukolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Minä olen herättänyt hänen vanhurskaudessa, ja minä teen kaikki hänen tiensä tasaiseksi. Hänen pitää rakentaman minun kaupunkini, ja päästämän minun vankini vallallensa, ei rahan eli lahjan tähden, sanoo Hera Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Näin sanoo Herra: Egyptilästen saanto ja Etiopialaisten kauppa, ja se suuri Seban kansa pitää itsensä antaman sinun alles, ja oleman sinun omas; heidän pitää noudattaman sinua, jalkapuissa pitää heidän käymän, ja pitää lankeeman maahan sinun etees, ja rukoileman sinua, sillä Jumala on sinun tykönäs, ja ei ole yhtään muuta Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Totisesti sinä olet salattu Jumala, sinä Jumala, Israelin Vapahtaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Mutta epäjumalain tekiät täytyy kaikki häpiässä ja häväistyksessä pysyä, ja yksi toisensa kanssa häväistynä mennä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Mutta Israel lunastetaan Herran kautta ijankaikkisella lunastuksella, eikä tule häpiään eli pilkkaan koskaan ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Sillä näin sanoo Herra, joka taivaan luonut on, Jumala, joka maan on valmistanut, ja on sen tehnyt ja vahvistanut sen, ja ei niin sitä tehnyt, että se olis tyhjänä ollut, vaan valmisti sen että siinä asuttaisiin: Minä olen Herra, ja ei kenkään muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'En minä ole salaa puhunut, pimiässä paikassa maan päällä, enkä ole Jakobin siemenelle sanonut: etsikäät minua hukkaan; sillä minä olen Herra, joka vanhurskaudesta puhun, ja ilmoitan oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Anna pakanain sankarien kokoontua ja tulla yhteen, jotka ei mitään tiedä, ja kantavat epäjumalansa kannot, ja rukoilevat sitä jumalaa, joka ei auttaa taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Ilmoittakaat ja tulkaat tänne, pitäkäät neuvoa keskenänne, kuka näitä alusta kuulutti, ja silloin on sen ilmoittanut? Enkö minä Herra? Ja ei ole ensinkään Jumalaa paitsi minua: hurskas Jumala ja Vapahtaja, ei ole yksikään paitsi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Kääntykäät minun tyköni, niin te autuaaksi tulette, kaikki maailman ääret; sillä minä olen Jumala, ja ei kenkään muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Minä vannon itse kauttani, ja minun suustani on vanhurskauden sana käyvä ulos, ja sen pitää vahvana pysymän: minulle pitää kaikki polvet kumartaman, ja kaikki kielet vannoman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Ja sanoman: Herrassa on minulla vanhurskaus ja väkevyys; senkaltaiset tulevat hänen tykönsä, mutta kaikki, jotka seisovat häntä vastaan, ne häpiään tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Sillä Herrassa kaikki Israelin siemen vanhurskautetaan, ja saavat hänestä kerskata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel kallistuu kovin, Nebo on pudonnut; heidän epäjumalansa ovat joutuneet eläinten ja juhtain päälle, että he väsyvät teidän kuormianne kantaissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Ja ne notkistuvat ja kallistuvat kaikki tyynni, ja ei taida kantaa pois kuormaa; vaan heidän sielunsa pitää käymän vankeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Kuulkaat minua, te Jakobin huone, ja kaikki Israelin huoneen tähteet, jotka kohdussa kannetaan ja äidistänne olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Minä, minä tahdon teitä kantaa hamaan vanhuuteen, ja siihenasti kuin te harmaaksi tulette; minä sen teen, minä nostan, kannan ja pelastan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Keneenkä te vertaatte minun, ja kenenkä kaltaiseksi te teette minun? ja kenen verraksi te minua mittaatte, jonka kaltainen minä olisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'He kaatavat kultaa säkistä, ja hopian painolla punnitsevat; ja hopiasepän palkkaavat, että hän jumalan tekis, jonka eteen he polvillensa lankeevat ja sitä kumartavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'He nostavat sen hartioillensa ja kantavat sitä, ja panevat sen siallensa, siinä se seisoo ja ei liiku siastansa. Jos joku häntä huutaa, niin ei hän vastaa, ja ei auta häntä hänen tuskastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Muistakaat tätä, ja olkaat vahvat: te väärintekiät, menkäät sydämiinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Muistakaat entisiä, jotka vanhasta ovat olleet; sillä minä olen Jumala ja ei ole muuta Jumalaa, eikä minun vertaistani ole,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Joka edellä ennustan, mitä vasta tuleva on, ja ennenkuin se tapahtuu, sanon minä. Minun aivoitukseni pysyvät, ja minä teen kaikki mieleni perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Minä kutsun linnun idästä, ja kaukaiselta maalta miehen, joka minun aivoitukseni tekee; minä olen sen puhunut, minä tahdon myös sen tuoda; minä olen sen aikonut ja tahdon myös sen tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Kuulkaat minua, te ylpiät sydämet, te jotka olette kaukana vanhurskaudesta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Minä olen vanhurskauteni antanut lähestyä, ei se ole kaukana, ja ei minun autuuteni viivy; sillä minä annan autuuden Zionissa, ja kunniani Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Astu alas, ja istu tomuun, sinä neitsy Babelin tytär; istu maahan, sillä ei ole yhtään istuinta enään, sinä Kaldean tytär; sillä ei sinua pidä enää kutsuttaman ihanaiseksi ja iloiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Ota mylly ja jauha jauhoja; päästä hiustes palmikot, riisu kenkäs, paljasta sääres, mene virran ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Että sinun häpys ilmoitetuksi, ja sinun riettautes nähdyksi tulis. Minä kostan, ja ei yksikään ihminen pidä rukouksellansa minua siitä estämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, '(Tämän tekee) meidän pelastajamme, Herra Zebaot on hänen nimensä, Israelin Pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Istu alallas, mene pimeyteen, sinä Kaldealaisten tytär; sillä ei sinua enää pidä kutsuttaman valtakuntain kuningattareksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Sillä kuin minä olin vihainen kansalleni, turmelin minä perintöni, ja hylkäsin heidät sinun kätees; mutta et sinä tehnyt heille laupiutta, ja vanhoille teit sinä ikees peräti raskaaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Ja ajattelit: minä olen hallitsia ijankaikkisesti: et sinä tähän päivään asti vielä ole sitä johdattanut sydämees, eli ajatellut, kuinka heille viimein on tapahtuva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Niin kuule nyt tätä, sinä, joka elät hekumassa, ja istut niin surutoinna, ja sanot sydämessäs: minä olen, ja ei yksikään muu; en minä leskeksi eli hedelmättömäksi tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Molemmat nämät pitää sinua äkisti kohtaaman yhtenä päivänä, ettäs tulet hedelmättömäksi ja leskeksi; ja ne pitää sinuun täydellisesti sattuman, sinun monen velhos tähden, ja sinun noitais tähden, joista suuri paljous on sinun tykönäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Sillä sinä olet luottanut pahuutees, koskas ajattelit: ei minua nähdä. Taitos ja tietos on sinun kukistanut, ettäs sanot sydämessäs: minäpä olen, ja ei yksikään muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Sentähden pitää onnettomuuden tuleman sinun päälles, niin ettei sinun pidä tietämän, koska se tulee, ja sinun vastoinkäymises pitää lankeeman sinun päälles, jotka ei sinun pidä taitaman sovittaa; sillä hävitys pitää äkisti tuleman sinun päälles, jota et sinä edellä tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Käy nyt edes velhois kanssa, ja sinun monien noitais kanssa, joiden seassa sinä olet itsiäs nuoruudessas vaivannut: jos taitaisit auttaa itsiäs, jos taitaisit vahvistaa itsiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Sinä olet väsyksissä monen koettelemukses tähden. Tulkaan nyt edes ja auttakoon sinua ne taivaan juoksun tietäjät ja tähtein kurkisteliat, jotka kuukausien jälkeen lukevat, mitä sinulle pitää tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Katso, he ovat niinkuin korret, jotka tuli polttaa, ei he taida pelastaa henkeänsä liekistä; sillä ei pidä yhtään hiilistöä oleman, jossa joku taitais itsensä lämmitellä, eli tulta, jonka tykönä istuttaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Juuri niin ovat ne sinulle, joiden alla sinä sinus vaivannut olet: sinun kauppamiehes sinun nuoruudestas pitää jokaisen käymän sinne ja tänne, ja sinulla ei ole yhtään auttajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Kuulkaat tätä, te Jakobin huone, te, joita kutsutaan Israelin nimellä, ja olette kulkeneet Juudan vedestä, te, jotka vannotte Herran nimeen, ja muistatte Israelin Jumalaa, ei kuitenkaan totuudessa eikä vanhurskaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Sillä he nimittävät itsensä pyhästä kaupungista, ja luottavat Israelin Jumalaan, jonka nimi on Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Minä olen ennen ilmoittanut tulevaisia, minun suustani on se lähtenyt, ja minä olen antanut sitä kuulla, ja teen sen myös äkisti, että se tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Sillä minä tiedän sinun kovaksi, ja sinun niskas on rautasuoni, ja sinun otsas on vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Minä olen sen ilmoittanut ennen, ja olen sinun antanut kuulla, ennenkuin se tulikaan, ettes sanoisi: epäjumalani sen tekee, ja kuvani ja epäjumalani on sen käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Kaikki nämät sinä kuulit ja näit, ja ette ole sitä ilmoittaneet; sillä minä olen edellä antanut sinun kuulla uusia ja salaisia, joita et sinä tietänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Mutta nyt on se luotu, ja ei siihen aikaan; ja et sinä ole kuullut päivääkään ennen, ettei sinun pitäisi sanoman: katso, sen minä hyvin tiesin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Sillä et sinä sitä kuullut, etkä sinä tietänyt, ja sinun korvas ei ollut siihen aikaan avattu; sillä minä kyllä tiesin sinun peräti sen katsovan ylön, joka olet nimitetty rikkojaksi sinun äitis kohdusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Minun nimeni tähden olen minä pitkämielinen, ja minun ylistykseni tähden tahdon minä säästää sinua, ettes tulisi hävitetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Katso, minä tahdon koetella sinua, mutta ei niinkuin hopiata, vaan minä teen sinun valituksi murheen pätsissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Minun tähteni, tosin minun tähteni tahdon minä tehdä, etten minä häväistyksi tulisi; sillä en minä anna kunniatani toiselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Kuule minua, Jakob, ja sinä minun kutsuttuni Israel: minä olen, minä olen ensimmäinen ja viimeinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Minun käteni on myös perustanut maan ja minun oikia käteni on kämmenellä mitannut taivaan: mitä minä kutsun, se on kohta valmis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Kootkaat teitänne kaiki ja kuulkaat, kuka on heidän seassansa näitä ilmoittanut? Herra rakastaa häntä, sentähden on hän osoittava tahtonsa Babelissa, ja käsivartensa Kaldealaisissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Minä, minä olen sen sanonut; minä olen hänen kutsunut, ja hänen johdattanut, ja hänen tiensä menestyy hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Tulkaat tänne minun tyköni, ja kuulkaat tätä: en minä ole ennen salaa puhunut, siitä ajasta, kuin se oli puhuttu, olin minä siellä; ja nyt lähetti minun Herra, Herra, ja hänen henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Näin sanoo Herra sinun pelastajas, Israelin Pyhä: minä olen Herra sinun Jumalas, joka sinulle opetan mikä tarpeellinen on, ja johdatan sinua tietä, jotas käyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'O jospa sinä pitäisit minun käskyistäni vaarin! niin sinun rauhas olis niinkuin virta, ja vanhurskautes niinkuin meren aalto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Ja sinun siemenes olis niinkuin santa ja kohtus hedelmä niinkuin hänen someronsa; joiden nimeä ei pitäisi hävitettämän eli pyyhittämän pois minun edestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Lähtekäät Babelista, paetkaat Kaldealaisten tyköä iloisella äänellä, ilmoittakaat ja kuuluttakaat tätä, viekäät se aina maailman ääriin, ja sanokaat: Herra on pelastanut palveliansa Jakobin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Ei heitä jano vaivannut, kuin hän johdatti heitä korvessa, hän antoi heille vuotaa vettä kalliosta; hän halkasi kallion, ja siitä vuosi vesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Mutta jumalattomalla, sanoo Herra, ei ole rauhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Kuulkaat minua, te luodot, ja te kaukaiset kansat, ottakaat vaari: Herra on minun äidin kohdusta kutsunut, hän muisti minun nimeni, kuin minä vielä äitini kohdussa olin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Ja teki minun suuni niinkuin terävän miekan, kätensä varjolla hän minua peitti; ja pani minun kiiltäväksi nuoleksi; pisti minun viineensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Ja sanoi minulle: sinä olet minun palveliani; Israel, sinussa minä kunnioitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Mutta minä sanoin: hukkaan minä työtä tein, turhaan ja tyhjään minä tässä kulutin väkeni; kuitenkin on minun asiani Herran kanssa, ja minun työni on minun Jumalani kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Ja nyt sanoo Herra, joka loi minun äidin kohdusta itsellensä palveliaksi, palauttamaan Jakobin hänelle, ettei Israel hukkuisi: sentähden olen minä kaunis Herran edessä, ja minun Jumalani on minun väkevyyteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Ja hän sanoi: vähä se on, ettäs olet minun palveliani, korjaamassa Jakobin sukukuntia, ja tuomassa jälleen Israelin hajoitettuja; mutta minä panin sinun myös pakanain valkeudeksi, olemaan minun autuuteni hamaan maailman ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Näin puhuu Herra Israelin lunastaja, hänen Pyhänsä, ylönkatsotuille sieluille, sille kansalle, josta me kauhistumme, sille palvelialle, joka tuimain herrain alla on: kuningasten pitää näkemän ja nouseman, päämiesten pitää rukoileman Herran tähden, joka uskollinen on, Israelin Pyhän tähden, joka sinun valinnut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Näin sanoo Herra: minä olen sinun rukoukses otollisella ajalla kuullut, ja olen autuuden päivänä sinua auttanut; ja olen varjellut sinua, ja liitoksi kansain sekaan olen sinun säätänyt, korjaamaan maata, ja haaskatuita perimisiä omistamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Sanomaan vangituille: menkäät ulos, ja jotka pimiässä ovat: tulkaat edes, että he teiden ohessa heitänsä elättäisivät, ja saisivat joka kukkulalla elatuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Ei heidän pidä isooman eikä janooman, ei helle eikä aurinko pidä heitä polttaman; sillä heidän armahtajansa johdattaa heitä, ja vie heitä vesilähteille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Ja minä panen kaikki vuoreni tieksi, ja minun polkuni pitää korotettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Katso, nämät tulevat kaukaa, ja katso, nämät pohjan puolesta, nämät etelän puolesta, ja muut Sinimin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Iloitkaat te taivaat, riemuitse sinä maa, kiittäkäät te vuoret ihastuksella; sillä Herra on kansaansa lohduttanut, ja on raadollisiansa armahtanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Mutta Zion sanoo: Herra hylkäsi minun, Herra unohti minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Unohtaako vaimo lapsukaisensa, niin ettei hän armahda kohtunsa poikaa? ja vaikka hän unohtais, niin en minä kuitenkaan sinua unohda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Katso, käsiini olen minä sinun pyhältänyt; sinun muuris ovat alati minun silmäini edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Sinun rakentajas rientävät; mutta sinun kukistajas ja hävittäjäs pitää pakeneman sinusta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Nosta silmäs ympäri ja katso, kaikki nämät kootut tulevat sinun tykös. Niin totta kuin minä elän, sanoo Herra, sinun pitää kaikilla näillä niinkuin kaunistuksella itses puettaman, ja sinä käärit ne ympärilles niinkuin morsian;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Sillä sinun autio, hävitetty ja turmeltu maas pitää silloin ahdas oleman asuakses, kuin sinun raatelias sinusta kauvas pakenevat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Niin että sinun hedelmättömyytes lapset pitää vielä korviis sanoman: ahdas on minulla sia, istu puolees, että minäkin asuisin sinun tykönäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Mutta sinä olet sanova sydämessäs: kuka nämät minulle synnytti? sillä minä olen hedelmätöin, yksinäinen, ajettu pois ja syösty ulos. Kuka nämät on minulle kasvattanut? katso, minä olen yksinäni jätetty, kussa nämät silloin olivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Näin sanoo Herra, Herra: katso, minä nostan käteni pakanain puoleen, ja korotan lippuni kansain puoleen, niin he tuovat edes helmassansa sinun poikias, ja sinun tyttäriäs hartioilla kannetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Ja kuninkaat pitää oleman sinun holhojas, ja heidän kuningattarensa sinun imettäjäs, heidän pitää lankeeman kasvoillensa maahan sinun edessäs, ja nuoleskelemaan sinun jalkais tomua. Silloin sinä tiedät, että minä olen Herra, ja ettei kenkään tule häpiään, joka minua toivoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Otetaanko saalis väkevältä pois? taitaako joku päästää hurskaan vangit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Sillä näin sanoo Herra: nyt pitää vangit väkevältä otettaman pois, ja tuimain saalis irralle pääsemän; ja minä tahdon riidellä sinun riitaveljeis kanssa, ja varjella sinun lapsias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Ja minä annan sinun hävittäjäs syödä omaa lihaansa, ja heidän pitää juopuman omasta verestänsä, niinkuin makiasta viinasta; ja kaikki liha pitää tietämän, että minä olen Herra, sinun auttajas ja sinun lunastajas, Jakobin väkevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Näin sanoo Herra: kussa on äitinne erokirja, jolla minä olen hänen hyljännyt? eli kuka on minun korkorahani kantaja, jolle minä teidät olen myynyt? Katso, te olette synteinne tähden myydyt, ja äitinne on teidän rikostenne tähden hyljätty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Miksi minä tulin, ja ei ollut siellä ketään? Minä huusin, ja ei yksikään vastannut? onko minun käteni niin peräti lyhentynyt, ettei hän voi pelastaa? ja eikö minulla ole voimaa vapahtaa? Katso, nuhtelemisellani teen minä meren kuivaksi, ja teen virrat korveksi, niin että kalat haisevat veden puuttumisen tähden ja kuolevat janosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Minä puetan taivaan pimeydellä, ja teen hänen peitteensä niinkuin säkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Herra, Herra antoi minulle oppineen kielen, taitaakseni puhua väsyneille ajallansa. Hän herättää minun joka aamu, hän herättää minulle korvan kuulemaan niinkuin opetuslapsen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Herra, Herra avasi minulle korvan, ja en ole minä tottelematoin, enkä mene takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Minä annoin selkäni niille, jotka minua pieksivät, ja poskeni niille, jotka minua repelivät; en minä kääntänyt kasvojani pois häväistyksistä ja syljestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Ja Herra, Herra minua auttaa, sentähden en minä tule häpiään; sentähden panin minä kasvoni niinkuin limsiön, sillä minä tiedän, etten minä tule häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Se on läsnä, joka minun vanhurskauttaa; kuka tahtoo riidellä minun kanssani? Seisokaamme ynnä; kellä on oikeus minua vastaan, se tulkoon tänne minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Katso, Herra, Herra auttaa minua, kuka tahtoo minua kadottaa? Katso, ne kaikki vanhenevat niinkuin vaate, koit syövät heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kuka on teidän seassanne, joka pelkää Herraa, joka hänen palveliansa ääntä kuultelee. Joka pimeydessä vaeltaa, ja ei näe valkeutta, se toivokaan Herran nimen päälle, ja luottakaan Jumalansa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Katso, te kaikki, jotka tulen sytytätte, jotka olette liekillä hankitut, vaeltakaat teidän tulenne valkeudessa, ja siinä liekissä, jonka te sytytitte. Se tapahtuu teille minun kädestäni; kivussa täytyy teidän levätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Kuulkaat minua te, jotka vanhurskautta noudatatte, te jotka Herraa etsitte. Katsokaat sitä kalliota, josta te lohaistut olette, ja sitä kaivoa, josta te kaivetut olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Katsokaat Abrahamia teidän isäänne, ja Saaraa, joka teidät synnytti; sillä minä kutsuin hänen, kuin hän oli vielä yksinäinen, siunasin ja enensin hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Sillä Herra lohduttaa Zionia, hän lohduttaa kaiken hänen aukiutensa, ja tekee hänen aukiutensa niinkuin Edenin, ja hänen erämaansa niinkuin Herran yrttitarhan; että siellä löytään ilo ja riemu, kiitos ja veisun ääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Ottakaat minusta vaari, minun kansani, ja kuulkaat minua minun sukukuntani; sillä minulta on laki käyvä ulos, ja minä panen oikeuteni kansoille valkeudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Minun vanhurskauteni on läsnä, minun autuuteni käy ulos, ja minun käsivarteni on kansoja tuomitseva. Luodot odottavat minua, ja vartioitsevat minun käsivarttani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Nostakaat teidän silmänne taivaasen, ja katsokaat alas maan päälle; sillä taivas on katoova niinkuin savu, ja maa vanhenee niinkuin vaate, niin myös sen asuvaiset kuolevat; mutta minun autuuteni pysyy ijankaikkisesti, ja minun vanhurskauteni ei ole puuttuva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Kuulkaat minua te, jotka vanhurskauden tunnette, kansa, jonka sydämessä minun lakini on. Älkäät peljätkö, kussa ihmiset teitä häpäisevät, ja älkäät vavisko, kuin he teitä pilkkaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Sillä koin pitää heitä syömän niinkuin vaatetta, ja madot pitää heidän syömän niinkuin villaisia; mutta minun vanhurskauteni pysyy ijankaikkisesti, ja minun autuuteni suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Ylös, ylös, pue päälles väkevyyttä, sinä Herran käsivarsi; ylös, niinkuin muinen vanhaan aikaan. Etkös se ole, joka löit ylpiän, ja haavoitit lohikärmeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Etkös se ole, joka meren, suuren syvän veden kuivasit? joka syvän meren tieksi teit, että lunastetut kävivät sitä myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Niin Herran lunastetut palajavat ja tulevat Zioniin riemulla, ja ijankaikkinen ilo on heidän päänsä päällä oleva; ilon ja riemun he käsittävät, murhe ja huokaus pakenee heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Minä, minä olen teidän lohduttajanne; kuka siis sinä olet, ettäs kuolevaista ihmistä pelkäät, ja ihmisten lapsia, jotka kulutetaan niinkuin heinä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Ja unohdat Herran, joka sinun tehnyt on, joka taivaat levittää, ja maan perustaa? Mutta sinä pelkäät alati yli päivää vaivaajan julmuutta, kuin hän rupee hukuttamaan. Ja kuhunka jäi vaivaajan julmuus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Koska hän vaadittiin rientämään ja juoksemaan ympäri, että hän päästäis, ettei he kuolisi kadotukseen, eikä hänen leipänsä puuttuisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Sillä minä olen Herra sinun Jumalas, joka meren liikutan, että sen aallot pauhaavat: hänen nimensä on Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Minä panen sanani sinun suuhus, ja peitän sinun käteni varjolla, että minä taivaan istuttaisin, ja maan perustaisin ja sanoisin Zionille: sinä olet minun kansani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Herää, herää, nouse Jerusalem, joka joit Herran kädestä hänen vihansa kalkin, sen kompastuskalkin rahkan olet sinä juonut ja särkenyt ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Ei kenkään hänen pojistansa, jotka hän oli synnyttänyt, häntä holhonnut: eikä kenkään kaikista hänen lapsistansa, jotka hän oli kasvattanut, hänen käteensä ruvennut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Nämät kaksi sinua kohtasivat, kuka sinua armahti? hävitys, vahinko, nälkä ja miekka: millä minä sinua lohdutan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Sinun lapses olivat pintuneet ja makasivat kaikissa katujen päissä, niinkuin paulalla sidottu metsähärkä, täynnä Herran vihaa ja sinun Jumalas rangaistusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Sentähden kuule nyt tätä sinä raadollinen, ja sinä juopunut ilman viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Näin sanoo Herra, sinun Herras ja sinun Jumalas, joka kansansa edestä sotii: katso, minä otan kompastuskalkin sinun kädestäs, ja minun vihani kalkin rahkan; ei sinun pidä sitä enään juoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Vaan minä panen sen sinun raateliais käteen, jotka sanoivat sinun sielulles: kumarra sinus, että me kävisimme sinun ylitses, ja pane sinun selkäs maahan, että niinkuin katua myöten sen ylitse mentäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Nouse, nouse, Zion, pue väkevyytes päälles, kaunista sinuas jalosti, sinä pyhä kaupunki Jerusalem; sillä ei tästedes yksikään ympärileikkaamatoin eikä saastainen pidä sinussa hallitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Puhdista itses tomusta, nouse ja istu Jerusalem; päästä sinuas kahleista, sinä vangittu Zionin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Sillä näin sanoo Herra: te olette tyhjään myydyt, ja ilman rahaa te lunastetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Sillä näin sanoo Herra, Herra: minun kansani meni ensin alas Egyptiin, olemaan siellä vieraana; ja Assur on heille väkivaltaa tehnyt ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Vaan mitä nyt minulle tämän edestä tehdään? sanoo Herra; sillä minun kansani ilman syytä viedään pois? että ne, jotka heitä hallitsevat, saattavat heidät itkemään, sanoo Herra, ja minun nimeäni pilkataan päivä päivältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Sentähden pitää minun kansani sinä päivänä minun nimeni tunteman, että minä itse olen se, joka puhun, katso, minä se olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'O kuinka suloiset ovat evankeliumin saarnaajain jalat vuorilla, jotka rauhaa julistavat, jotka hyvää saarnaavat, autuuden ilmoittavat, jotka Zionille sanovat: sinun Jumalas on kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Sinun vartias huutavat korkiasti ja iloitsevat ynnä, sillä se nähdään ilmeisesti, koska Herra kääntää Zionin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Iloitkaat ja riemuitkaat ynnä, te Jerusalemin autiot; sillä Herra on kansaansa lohduttanut, ja Jerusalemin päästänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Herra on ilmoittanut pyhän käsivartensa kaikkein pakanain silmäin edessä, niin että kaikki maailman ääret näkevät meidän Jumalamme autuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Paetkaat, paetkaat, lähtekäät sieltä, ja älkäät mihinkään saastaiseen sattuko; menkäät ulos heidän tyköänsä, puhdistakaat teitänne, te jotka Herran kalua kannatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Sillä ei teidän pidä lähtemän nopiasti, eli vaeltaman pakenemisella; sillä Herra on lähtevä teidän edellänne, ja Israelin Jumala on kokoova teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Katso, minun palveliani tekee toimellisesti: hän korotetaan, nostetaan ylös, ja tulee sangen korkiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Niin että moni sinun ylitses hämmästyy, että hänen muotonsa on rumempi muita ihmisiä, ja hänen hahmonsa huonompi kuin ihmisten lasten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Mutta niin on hän monta pakanaa priiskottava, että myös kuningasten täytyy suunsa hänen edessänsä tukita; sillä joille ei mitään hänestä ilmoitettu ollut, nekin hänen ilolla näkevät, ja jota ei he kuulleet ole, sen ne ymmärtävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kuka uskoo meidän saarnamme, ja kenelle Herran käsivarsi ilmoitetaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Sillä hän nousee ylös hänen edessänsä niinkuin vesa, ja niinkuin juuri kuivasta maasta; ei hänellä ole muotoa, eikä kauneutta; me näimme hänen, vaan ei ollut hänellä sitä muotoa, joka meille olis kelvannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Hän oli kaikkein ylönkatsottava ja kaikkein halvin, kipua ja sairautta täynnä. Hän oli niin ylönkatsottu, ettei kenkään kehdannut katsoa hänen päällensä, sentähden emme häntä minäkään pitäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Totisesti hän kantoi meidän sairautemme, ja meidän kipumme hän sälytti päällensä; mutta me pidimme hänen Jumalalta rangaistuna, piestynä ja vaivattuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Vaan hän on haavoitettu meidän pahain tekoimme tähden, ja meidän synteimme tähden on hän hosuttu. Rangaistus on hänen päällänsä, että meillä rauha olis, ja hänen haavainsa kautta olemme me parannetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Kaikki me vaelsimme eksyksissä niinkuin lampaat: itsekukin meistä poikkesi omalle tiellensä; mutta Herra heitti kaiken meidän vääryytemme hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Kuin hän rangaistiin ja vaivattiin, niin ei hän suutansa avannut; niinkuin karitsa, joka teuraaksi viedään, ja niinkuin lammas, joka keritsiänsä edessä vaikenee, niin ei hänkään suutansa avannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Mutta hän on otettu pois ahdistuksesta ja tuomiosta; kuka taitaa sanoa hänen elämänsä pituuden? sillä hän on sivallettu pois eläväin maalta, kuin hän minun kansani pahain tekoin tähden rangaistiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Hänen hautansa aiottiin jumalattomain sekaan, rikkaan tykö tuli hän kuitenkin kuoltuansa. Ei hän kellenkään vääryyttä tehnyt, eikä petosta ollut hänen suussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Mutta Herra tahtoi hänen niin piestä sairaudella; koska hän on henkensä vikauhriksi antanut, niin hän saa nähdä siemenen ja elää kauvan, ja Herran aivoitus on hänen kädessänsä menestyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Että hänen sielunsa on työtä tehnyt, saa hän ilonsa nähdä, ja tulee ravituksi. Tuntemisensa kautta minun vanhurskas palveliani monta vanhurskauttaa; sillä hän kantaa heidän syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Sentähden annan minä hänelle osan monessa, ja hänen pitää väkeväin kanssa saalista jakaman; sentähden että hän antoi henkensä kuolemaan, ja oli pahantekiäin sekaan luettu, ja hän kantoi monen synnit, ja rukoili pahantekiäin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Riemuitse sinä hedelmätöin, joka et synnytä: iloitse riemulla ja ihastu sinä, joka et raskas ole; sillä yksinäisellä on enempi lapsia kuin sillä, jolla mies on, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Levitä majas sia, ja venytä asumises vaate, älä säästä; pitennä köytes, ja kiinnitä vaajas lujasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Sillä sinun pitää oikialle ja vasemmalle puolelle levenemän, ja sinun siemenes pitää pakanat perimän, ja aukeissa kaupungeissa asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Älä pelkää, sillä et sinä tule häpiään; älä ole kaino, sillä ei sinun pidä häpiään tuleman. Vaan sinun pitää nuoruutes häpiän unohtaman, ja sinun leskeytes kainoutta ei enään muistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Sillä joka sinun tehnyt on, hän on sinun miehes, Herra Zebaot on hänen nimensä; ja Israelin Pyhä sinun lunastajas, joka kaiken maailman Jumalaksi kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Sillä Herra on kutsunut sinun niinkuin hyljätyn ja sydämestä murheellisen vaimon; ja sinä olit niinkuin nuori emäntä, joka hyljätty on, sanoo sinun Jumalas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Minä olen vähäksi silmänräpäykseksi sinun hyljännyt, mutta minä tahdon sinua suurella laupiudella koota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Minä olen vihassani vähäksi silmänräpäykseksi kasvoni kätkenyt sinulta; mutta minä tahdon armahtaa sinua ijankaikkisessa armossa, sanoo Herra, sinun lunastajas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Sillä tämä on minulle oleva niinkuin Noan vesi, josta minä vannoin, ettei Noan vedet pitänyt enään käymän maan ylitse: juuri niin olen minä nyt vannonut, ettei minun enään pidä sinulle vihastuman, eikä sinua rankaiseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Sillä vuoret pitää välttämän ja kukkulat lankeeman; mutta minun armoni ei pidä sinusta poikkeeman, ja minun rauhani liitto ei pidä lankeeman pois, sanoo Herra sinun armahtajas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Sinä raadollinen, kovalta tuulelta häälytetty, ja sinä turvatoin! katso, minä panen sinun kives niinkuin kaunistuksen, ja tahdon sinun perustukses saphireilla laskea,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Ja sinun akkunas kristallista rakentaa, ja sinun porttis rubinista, ja kaikki sinun rajas valituista kivistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Ja kaikki sinun lapses pitää oleman opetetut Herralta, ja suuri rauha sinun lapsilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Vanhurskaudella pitää sinun valmistetuksi tuleman: sinun pitää oleman kaukana väkivallasta, ettei sinun pidä pelkäämän, ja hämmästyksestä; sillä ei sen pidä sinua lähestymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Katso, kuka tahtoo sinua vastaan koota ja sortaa sinua, jos he ilman minua kokoontuvat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Katso, minä teen sepän, joka hiilet tulessa lietsoo, ja tekee aseen työtänsä varten: niin minä myös teen raatelian hukuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Ei yksikään ase, joka valmistetaan sinua vastaan, pidä menestymän; ja kaikki kielet, jotka heitänsä asettavat sinua vastaan, pitää sinun tuomiollas kadotettaman. Tämä on Herran palveliain perimys, ja heidän vanhurskautensa minusta, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Kaikki janoovaiset, tulkaat vetten tykö, tekin, joilla ei ole rahaa, tulkaat, ostakaat ja syökäät; tulkaat, ostakaat, ilman rahaa ja ilman hintaa, viinaa ja rieskaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Miksi te annatte rahan siinä, kussa ei leipää ole, ja teidän työnne siinä, kussa ei ole ravintoa? Kuulkaat minua, ja nauttikaat hyvää, ja teidän sielunne riemuitkaan lihavuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Kallistakaat korvanne ja tulkaat minun tyköni, kuulkaat, niin teidän sielunne saa elää; ja minä teen teidän kanssanne ijankaikkisen liiton, lujat Davidin armot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Katso, minä panin hänen kansoille todistajaksi, päämieheksi ja opettajaksi kansoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Katso, sinun pitää kutsuman pakanat, joita et sinä tunne, ja ne pakanat, jotka ei sinua tunteneet, pitää juokseman sinun tykös, Herran sinun Jumalas tähden, ja Israelin Pyhän tähden, joka sinua kaunisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Etsikäät Herraa, kuin hän löytää taitaan: rukoilkaat häntä, koska hän läsnä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Jumalatoin hyljätköön tiensä, ja pahointekiä ajatuksensa, ja palatkaan Herran tykö, niin hän armahtaa häntä, ja meidän Jumalamme tykö, sillä hänen tykönänsä on paljon anteeksiantamusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Sillä minun ajatukseni ei ole teidän ajatuksenne, ja teidän tienne ei ole minun tieni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Vaan niin paljo korkeampi kuin taivas on maasta, niin ovat myös minun tieni korkeammat teidän teitänne, ja minun ajatukseni teidän ajatuksianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Sillä niinkuin sade ja lumi tulee taivaasta alas, ja ei mene sinne jälleen, vaan tuorettaa maan, ja tekee sen hedelmälliseksi ja antaa sen kasvaa, ja antaa siemenen kylvettää ja leivän syötää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Niin on myös minun sanani, joka minun suustani lähtee, ei sen pidä tyhjänä palajaman minun tyköni, vaan tekemän mitä minulle otollinen on, ja sen pitää menestymän, jota varten minä sen lähettänytkin olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Sillä ilossa teidän pitää lähtemän ja rauhassa saatettaman; vuoret ja kukkulat pitää teidän edessänne kiitosta veisaaman, ja kaikki puut kedolla käsillänsä yhteen lyömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Hongat pitää orjantappurain siassa kasvaman, ja myrttipuu nukulaisten edestä; ja se pitää oleman Herralle nimeksi, ijankaikkiseksi merkiksi, jota ei pidä hävitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Näin sanoo Herra: pitäkäät oikeus, ja tehkäät vanhurskautta; sillä minun autuuteni on läsnä tulemassa, ja minun vanhurskauteni, että se ilmoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Autuas on se ihminen, joka sen tekee, ja se ihmisen lapsi, joka sen käsittää: että hän pitäis sabbatin, eikä sitä arkioksi tekisi, ja pidättäis kätensä, ettei hän mitään pahaa tekisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Ja muukalainen, joka Herraan on suostunut, ei pidä sanoman: Herra kaiketi eroittaa minun kansastansa; ja kuohittu ei pidä sanoman: katso, minä olen kuiva puu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Sillä näin sanoo Herra kuohituille: jotka minun sabbatini pitävät, ja valitsevat mitä minulle kelpaa, ja lujasti pitävät minun liittoni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Niin minä annan heille minun huoneessani ja muurissani paikan, ja paremman nimen kuin pojilla ja tyttärillä on; ijankaikkisen nimen minä heille annan, jota ei pidä hävitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Ja muukalaisten lapsille, jotka Herraan suostuneet ovat häntä palvelemaan ja Herran nimeä rakastamaan, ja hänen palveliansa olemaan: jokainen heistä, joka sabbatin pitää, ettei hän sitä arkioksi tekisi, vaan pitäis lujasti minun liittoni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Ne minä vien pyhän vuoreni tykö, ja ilahutan heitä minun rukoushuoneessani; heidän uhrinsa ja polttouhrinsa pitää minulle otolliset oleman minun alttarillani; sillä minun huoneeni pitää kutsuttaman kaikkein kansain rukoushuoneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Herra, Herra, joka Israelin hyljätyt kokoo, sanoo: minä tahdon vielä enemmän hänen koottuinsa joukkoon koota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Kaikki pedot kedolla, tulkaat ja syökäät, ja kaikki pedot metsässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Kaikki heidän vartiansa ovat sokiat, eikä tiedä mitään, he ovat kaikki mykät koirat, jotka ei voi haukkua; he ovat laiskat, he makaavat ja unta rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Mutta he ovat häpeemättömät väkevät koirat, jotka ei ikänä taida tulla ravituiksi. Ei paimenet itsekään tiedä mitään eli ymmärrä; jokainen ottaa vaarin omasta tiestänsä, kukin noudattaa ahneuttansa hänen tilassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Tulkaat, ottakaamme viinaa ja juopukaamme, ja olkoon huomenna niinkuin tänäpänäkin, ja vielä paljo enempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Vanhurskas hukkuu, ja ei ajattele kenkään sitä sydämessänsä; pyhät miehet temmataan pois, ja ei siitä kenkään pidä vaaria; sillä vanhurskaat otetaan pois onnettomuudesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Ja jotka toimellisesti vaeltaneet ovat, tulevat rauhaan, ja lepäävät kammioissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Tulkaat tänne edes, te noitain lapset, te huorintekiäin ja porttoin siemenet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Kenenkä kanssa te nyt tahdotte iloita hekumassa? Kenenkä päälle te nyt tahdotte suutanne irvistellä, ja kieltänne pistää? Ettekö te ole rikoksen lapset ja väärä siemen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Te jotka olette hempeät epäjumaliin kaikkein viheriäisten puiden alla, ja teurastatte lapsia ojain tykönä vuorten alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Sinun menos on sileiden kivien seassa, ojissa, ne ovat sinun osas; niille sinä vuodatat juomauhris, kuin sinä ruokauhria uhraat: pitäiskö minun siihen mielistymän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Sinä teet vuotees korkialle jyrkälle vuorelle, ja menet myös itse sinne ylös uhria uhraamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Oven ja pihtipielen taa panet sinä muistos; sillä sinä vierität sinus pois minun tyköäni, menet ylös, ja levität vuotees, ja kiinnität itses heihin; sinä rakastat heidän vuodettansa, kussa ikänä sinä heidät näet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Sinä menet kuninkaan tykö öljyllä, ja sinulla on moninaiset voiteet: ja lähetät sanas saattajat kauvas, ja olet alennettu hamaan helvettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Sinä vaivasit itsiäs monissa teissä, ja et sanonut: minä suutun; vaan ettäs löydät sinun kätes elämän, sentähden et sinä väsy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Ketäs kartat ja pelkäät? ettäs valheessa olet, ja et muista minua, etkä johdata mielees; luuletkos minun ijäti olevan ääneti, ettes minua ensinkään pelkää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Minä ilmoitan sinun vanhurskautes, ja sinun tekos: ja ne ei sinua pidä hyödyttämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Kuin sinä huudat, niin auttakoon sinun joukkos sinua; mutta tuulen pitää heidät kaikki viemän pois, ja turhuuden pitää ne ottaman pois; mutta joka minuun uskaltaa, hänen pitää maan perimän ja omistaman minun pyhän vuoreni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Ja sanoman: tehkäät tietä, tehkää tietä, levittäkäät polku, sysätkäät loukkaukset minun kansani tieltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Sillä näin sanoo korkia ja ylistetty, joka asuu ijankaikkisuudessa, ja jonka nimi on Pyhä: minä asun korkeudessa ja pyhyydessä, ja niiden tykönä, joilla särjetty ja nöyrä henki on, että minä virvoittaisin nöyryytetyn hengen, ja saattaisin särjetyn sydämen eläväiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Sillä en minä ijäti tahdo riidellä, enkä vihastua ijankaikkisesti; vaan minun kasvoistani on henki lähtevä, ja minä teen hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Minä olin vihainen heidän ahneutensa vääryyden tähden, ja löin heitä, lymytin itseni ja närkästyin; silloin he menivät eksyksissä oman sydämensä tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Minä näin heidän tiensä, paransin heidät, ja johdatin heitä ja lohdutin niitä, jotka heitä murehtivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Minä olen luonut huulten hedelmän: rauhan, rauhan sekä kaukaisille että läheisille, sanoo Herra, ja olen heitä parantanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mutta jumalattomat ovat niinkuin lainehtiva meri, joka ei voi tyventyä; vaan hänen aaltonsa heittävät loan ja mudan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Jumalattomilla ei ole rauhaa, sanoo minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Huuda rohkiasti, älä säästä, korota äänes niinkuin basuna, ja ilmoita minun kansalleni heidän ylitsekäymisensä, ja Jakobin huoneelle heidän syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Minua tosin he etsivät joka päivä, tahtovat tietää minun tietäni, niinkuin se kansa, joka jo vanhurskauden tehnyt on, ja ei ole heidän Jumalansa oikeutta hyljännyt. He kysyvät minulta oikiaa tuomiota, ja tahtovat lähestyä Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Miksi me paastoamme, ja et sinä sitä katso? miksi me ruumistamme vaivaamme, ja et sinä sitä tahdo tietää? Katso, kuin te paastootte, niin te teette teidän tahtonne, ja vaaditte kaikkia teidän velvollisianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Katso, te paastotte toraksi ja riidaksi, pieksätte rusikalla jumalattomasti. Älkäät paastotko niinkuin te nyt teette, että teidän parkunne kuuluu korkeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Pitäiskö se oleman senkaltainen paasto, jonka minä valitsen: että ihminen ruumistansa päivällä vaivaa eli kallistaa päänsä niinkuin kaisla, taikka säkissä eli tuhassa makaa, senkö te paastoksi kutsutte, ja Herran otolliseksi päiväksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Mutta tämä on paasto, jonka minä valitsen: laske ne vallallensa, jotka vääryydellä sidotut ovat, päästä raskautetut irralle, laske vaivatut vapaaksi, ota pois kaikkinainen kuorma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Taita isoovalle leipäs, vie raadolliset kulkiat huoneesees: kuin sinä näet alastoman, niin vaateta häntä, ja älä käännä itsiäs pois lihas tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Silloin sinun valkeutes puhkee paistamaan niinkuin aamurusko, ja sinun parannukses on nopiasti kasvava; ja sinun vanhurskautes vaeltaa sinun edelläs. ja Herran kunnia on sinun korjaava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Silloin sinä rukoilet, ja Herra kuulee sinun rukoukses; ja koska sinä huudat, niin hän sanoo: katso, tässä minä olen. Ellet sinä ketään tykönäs raskauta, eli sormellas osoita, taikka pahasti puhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Jos avaat sydämes isoovaiselle, ja ravitset raadolliset sielut; niin sinun valkeutes on pimiässä koittava, ja sinun hämäräs on oleva niinkuin puolipäivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Ja Herra johdattaa aina sinua, ja ravitsee sielus poudalla, ja sinun luus vahvistaa; ja sinä olet oleva niinkuin kasvatettu yrttitarha ja niinkuin lähde, josta ei koskaan vesi puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Ja se rakennetaan sinulta, joka kauvan on autiona ollut, ja sinä lasket perustuksen, joka pysyy ijankaikkisesti; ja sinä pitää kutsuttaman rauvenneen tukiaksi, ja teiden parantajaksi, että siinä saataisiin asua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Jos sinä käännät jalkas sabbatista pois, niin ettes tee sinun tahtoas minun pyhäpäivänäni, niin se pitää iloiseksi sabbatiksi kutsuttaman, Herran kunnialliseksi pyhäksi; sillä niin sinä häntä ylistät, kuin et tee sinun teitäs, etkä niistä löydetä, jotka sinulle kelpaavat, eli mitä sinä puhut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Silloin on sinulla ilo oleva Herrassa, ja minä ylennän sinun maan kukkulain päälle, ja tahdon sinua ruokkia Jakobin sinun isäs perimisestä; sillä Herran suu on sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Katso, ei Herran käsi ole lyhennetty, niin ettei hän voi auttaa, ja ei hänen korvansa raskaat, ettei hän kuule;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Vaan teidän pahuutenne eroittaa teidät ja teidän Jumalanne toisen toisestansa, ja teidän syntinne kätkevät pois hänen kasvonsa teiltä, niin ettei teitä kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Sillä teidän kätenne ovat saastutetut verellä, ja sormenne vääryydellä; teidän huulenne puhuvat valhetta, ja kielenne latelevat vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Ei ole yhtään, joka saarnaa vanhurskautta eli tuomitsee uskollisesti. Turhuuteen luotetaan ja puhutaan kelpaamattomia; onnettomuudesta ovat he raskaat, ja synnyttävät tuskan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'He hautovat basiliskin munia, ja kutovat hämähäkin verkkoa: jos joku syö hänen muniansa, niin hänen täytyy kuolla, jos ne rikotaan, niin niistä tulee kyykärme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Heidän hämähäkkinsä verkot ei kelpaa vaatteeksi, ja heidän tekonsa ei kelpaa peitteeksi; sillä heidän työnsä ovat väärät työt, ja heidän käsissänsä on väkivalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Heidän jalkansa juoksevat pahaan ja ovat nopsat vuodattamaan viatonta verta; heidän ajatuksensa ovat väärät ajatukset, heidän teissänsä on hävitys ja vahinko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Ei he tunne rauhan teitä, eikä ole oikeutta heidän käymisissänsä; heidän polkunsa ovat karsaat: joka niitä käy, ei hänellä ole ikänä rauhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Sentähden on meistä oikeus kaukana, ja vanhurskaus ei käsitä meitä; me odotimme valkeutta, katso, niin tulee pimeys: paistetta, ja katso, me vaellamme sumussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Me haparoitsimme seiniä niinkuin sokiat, ja pitelimme niinkuin ne, joilla ei silmiä ole; me loukkaamme itsemme puolipäivänä niinkuin hämärissä, me olemme pimeydessä niinkuin kuolleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Me myrisemme kaikki niinkuin karhut, ja vaikeroitsemme surkiasti niinkuin mettiset, sillä me odotamme oikeutta, ja ei sitä olekaan, autuutta, ja se on meistä kaukana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Sillä meidän rikoksiamme on sinun edessäs aivan paljo, ja meidän syntimme todistavat meitä vastaan; sillä meidän rikoksemme on meitä läsnä, ja me tunnemme pahat tekomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Rikoksella ja valheella Herraa vastaan me luovumme meidän Jumalastamme, puhumaan vääryyttä ja tottelemattomuutta, ajatellaksemme ja ladellaksemme vääriä sanoja sydämestämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Sentähden on myös oikeus palannut takaperin, ja vakuus on kauvas mennyt; sillä totuus putoo kaduille, ja vakuus ei taida tulla edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Totuus on pois, ja joka luopuu pahasta, hänen pitää oleman jokaisen saaliina. Herra näkee sen, ja se on paha hänen silmäinsä edessä, ettei oikeutta ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Ja hän näkee, ettei yhtään miestä ole, ja ihmettelee, ettei kenkään pyydä sitä sovittaa: niin hänen käsivartensa vapahtaa hänen, ja hänen vanhurskautensa pitää hänen tallella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Sillä hän pukee yllensä vanhurskauden niinkuin rautapaidan, ja panee autuuden rautalakin päähänsä; ja puettaa itsensä koston vaatteilla niinkuin puvulla, ja pukee yllensä kiivauden niinkuin hameen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Niinkuin se, joka kostaa vihollisillensa heidän ansionsa jälkeen ja tahtoo maksaa vihamiehillensä julmuudella, ja luodoille tahtoo hän maksaa ansion jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Että Herran nimeä peljättäisiin lännestä, ja hänen kunniaansa idästä, kuin hän on tuleva niinkuin tydytetty virta, jonka Herran tuuli ajaa matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Ja Zionille on tuleva vapahtaja, ja niille, jotka kääntyvät pois synneistä Jakobissa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Ja minä teen tämän liiton heidän kanssansa, sanoo Herra: minun henkeni, joka sinun päälläs on, ja minun sanani, jotka minä sinun suuhus pannut olen, ei pidä lähtemän sinun suustas, eikä sinun siemenes suusta, ja lastes lasten suusta, sanoo Herra, nyt niin ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Nouse, ole kirkas; sillä sinun valkeutes tulee, ja Herran kunnia koittaa sinun ylitses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Sillä katso, pimeys peittää maan, ja synkeys kansan; mutta Herra koittaa sinun ylitses, ja hänen kunniansa pitää sinun päälläs nähtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Ja pakanat pitää vaeltaman sinun valkeudessas, ja kuninkaat sinun paisteessas, joka sinun ylitses koittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Nosta silmäs, katso ympärilles, kaikki nämät kootut tulevat sinun tykös; sinun poikas tulevat kaukaa, ja sinun tyttäres kylkien vieressä kasvatetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Silloin sinä saat sen nähdä ja iloitset, sinun sydämes ihmettelee, ja levittää itsensä, kuin suuri paljous meren tykönä kääntyy sinun tykös, ja pakanain voima tulee sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Kamelein paljous on peittävä sinun, nopsat Midianin ja Ephan kamelit; ne kaikki tulevat Sabasta; kultaa ja pyhää savua he tuovat, ja he ilmoittavat Herran kiitoksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Kaikki Kedarin laumat kokoontuvat sinun tykös, ja Nebajotin oinaat palvelevat sinua: ne pitää minun otolliselle alttarilleni uhrattaman, sillä minä tahdon minun kunniani huoneen kaunistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kutka ovat nuo, jotka lentävät niinkuin pilvet, ja niinkuin mettiset akkunoillensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Sillä minua luodot odottavat, ja haahdet meressä ensimäisinä tuomaan sinun lapses tähän kaukaa; heidän hopiansa ja kultansa heidän kanssansa, Herran sinun Jumalas ja Israelin Pyhän nimeen, joka sinua kunnioitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Muukalaisten lapset pitää sinun muuris rakentaman, ja heidän kuninkaansa pitää sinua palveleman; sillä vihassani löin minä sinua, ja armoissani minä armahdan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Ja sinun porttis pitää alati avoinna oleman, ja ei pidä päivällä eikä yöllä suljettaman, että pakanain voima tuotaisiin, ja heidän kuninkaansa saatettaisiin sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Sillä ne pakanat ja valtakunnat, jotka ei tahdo sinua palvella, pitää hukkuman, ja pakanat pitää peräti hukutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Libanonin kunnia pitää tuleman sinun tykös, honka, tammi ja buksipuu ynnä, kaunistamaan minun pyhää siaani; sillä minä tahdon jalkani sian kunnioittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Heidän pitää myös kumaroissansa sinun tykös tuleman, jotka sinua sortaneet ovat, ja kaikki, jotka sinua pilkanneet ovat, pitää lankeeman sinun jalkais eteen, ja kutsuman sinun Herran kaupungiksi, Israelin Pyhän Zioniksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Ettäs olet hyljätty ja vihattu ollut, kussa ei kenkään vaeltanut, tahdon minä sinua ijankaikkiseksi korkeudeksi tehdä, ja iloksi suvusta sukuun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Että sinun pitää pakanain rieskaa imemän, ja kuningasten nisät pitää sinua imettämän: ettäs tuntisit minun Herraksi sinun vapahtajakses, ja että minä, Jakobin väkevä, olen sinun lunastajas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Minä tahdon saattaa kultaa vasken siaan, ja hopiaa raudan siaan, ja vaskea puiden siaan ja rantaa kivien sijaan ja tahdon tehdä vaivas rauhaksi, ja työs vanhurskaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Ei enään sinun maallas vääryyttä kuuluman pidä, ei vahinkoa, eikä kadotusta sinun äärissäs; vaan sinun muuris pitää autuudeksi ja sinun porttis kiitokseksi kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Ei auringon pidä enään päivällä sinulle paistaman, eikä kuun valon sinua valaiseman; vaan Herra on sinun ijankaikkinen valkeutes, ja sinun Jumalas on sinun ylistykses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Ei sinun aurinkos enään laske, eikä kuus kadota valoansa; sillä Herra on sinun ijankaikkinen valkeutes, ja sinun murhepäiväs loppuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Ja sinun kansas on kaikki vanhurskas oleva, ja maan piirin ijankaikkisesti omistava, niinkuin minun istutukseni vesat ja käsialani ovat minulle ylistykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Vähäinen pitää tuhanneksi tuleman, ja piskuinen väkeväksi kansaksi: minä Herra tahdon sen ajallansa toimittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Herran, Herran henki on minun päälläni, sentähden on Herra minua voidellut, saarnaamaan köyhille hyvää sanomaa; hän on minun lähettänyt parantamaan särjettyjä sydämiä: saarnaamaan vangeille lunastusta ja sidotuille pääsemistä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Saarnaamaan Herran otollista vuotta, ja meidän Jumalamme kostopäivää; lohduttamaan kaikkia murheellisia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Että minä saattaisin murheellisille Zionissa kaunistuksen tuhan edestä, ja iloöljyn murheen edestä, ja kauniit vaatteet murheellisen hengen edestä; että he vanhurskauden puuksi kutsuttaisiin, Herran istuttamisen ylistykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Ja heidän pitää vanhat autiot paikat rakentaman, ja parantaman mitä muinen on hävitetty; heidän pitää autiot kaupungit uudistaman, jotka suvusta sukuun hävitettynä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Muukalaiset pitää seisoman ja teidän laumanne kaitseman; ja vierasten lapset pitää teidän peltomiehenne ja viinamäkenne miehet oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Mutta teitä pitää Herran papiksi kutsuttaman, ja sanottaman: te olette meidän Jumalamme palveliat, ja teidän pitää pakanain hyvyyden syömän, ja heidän kunniastansa pitää teidän kerskaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Teidän häpiänne edestä pitää teidän kaksinkertaisesti saaman, ja häväistyksen edestä pitää heidän riemuitseman osassansa: sentähden pitää heidän kaksinkertaisesti maansa omistaman: heillä pitää ijankaikkinen riemu oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Sillä minä olen Herra, joka oikeutta rakastan, ja vihaan ryövättyä polttouhria: ja tahdon saattaa, ettei heidän työnsä pidä turha oleman, ja teen ijankaikkisen liiton heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Ja heidän siemenensä pitää pakanain seassa tunnettaman, ja heidän jälkeentulevaisensa kansain seassa; että jokainen, joka heidät näkee, pitää heidät tunteman, että he ovat siunattu siemen Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Minä iloitsen suuresti Herrassa, ja minun sieluni riemuitsee minun Jumalassani; sillä hän puetti minun autuuden vaatteilla, ja verhoitti minun vanhurskauden hameella: niinkuin ylkä kaunistettu papillisella kaunistuksella, ja niinkuin morsian kaunistettu kaunistuksessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Sillä niinkuin hedelmä kasvaa maasta, ja siemen yrttitarhassa putkahtaa, niin antaa Herra, Herra vanhurskauden ja kiitoksen käydä ylös kaikkein pakanain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Zionin tähden en minä vaikene, ja Jerusalemin tähden en minä lakkaa, siihenasti että hänen vanhurskautensa koittaa niinkuin paiste, ja hänen autuutensa palaa niinkuin tulisoitto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Että pakanatkin näkisivät sinun vanhurskautes, ja kaikki kuninkaat sinun kunnias. Ja sinä nimitetään uudella nimellä, jonka Herran suu on nimittävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Ja sinun pitää oleman kunnian kruunu Herran kädessä, ja kuninkaan hiippa sinun Jumalas kädessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Et sinä enään kutsuta hyljätyksi, eikä sinun maatas enää sanota hävitetyksi, vaan sinä kutsutaan: minun suosioni on hänessä, ja sinun maas asuttavaksi; sillä Herra on mielistynyt sinuun, ja sinun maallas asutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Sillä niinkuin nuorukainen rakastaa neitsyttä, niin sinun lapses pitää sinua rakastaman; ja niinkuin ylkä iloitsee morsiamestansa, niin myös sinun Jumalas iloitsee sinusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Jerusalem, minä asetan vartiat muuris päälle, jotka ei ikänä päivällä eikä yöllä vaikene; ja jotka Herran muistatte, ei teidän pidä vaiti oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Ja ei teidän pidä hänestä vaikeneman, siihenasti että hän sen vahvistaa, ja asettaa Jerusalemin maan päälle kiitokseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Herra vannoo oikian kätensä kautta, ja voimansa käsivarren kautta: en minä tahdo enään antaa jyviäs vihollistes syödä, enkä viinaas, jonka tähden sinä työtä teit, muukalaisten juoda;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Vaan jotka sen kokoovat, syövät sitä ja kiittävät Herraa; ja jotka sitä kokoovat, juovat sitä minun pyhyyteni esihuoneissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Menkäät, menkäät porttein kautta, peratkaat tietä kansalle: silittäkäät, silittäkäät polut, siirtäkäät kivet pois, ylentäkäät lippu kansain päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Katso, Herra antaa sen kuulua hamaan maailman ääriin asti: sanokaat Zionin tyttärelle: katso, sinun autuutes tulee, katso, hänen palkkansa on hänen myötänsä, ja hänen työnsä hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Ja he pitää kutsuttaman pyhäksi kansaksi, Herran lunastetuiksi; ja sinä kutsutaan etsityksi ja ei hyljätyksi kaupungiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kuka on se, joka tulee Edomista, punaisilla vaatteilla Botsrasta, joka niin on kaunistettu vaatteissansa, ja käy suuressa voimassansa? Minä joka puhun vanhurskautta, ja taidan kyllä auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Miksi ovat siis vaattees niin punaiset, ja pukus niinkuin viinakuurnan sotkujan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Minä sotkun viinakuurnan yksinäni, ja ei yksikään kansasta minun kanssani. Minä tallaan heitä vihassani, ja sotkun heitä julmuudessani; siitä on heidän verensä priiskunut vaatteisiini, ja minä olen saastuttanut kaikki minun pukuni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Sillä minä olen säätänyt itselleni kostopäivän, ja vuosi on tullut omiani pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Sillä minä katsoin ympärilleni, ja ei ollut auttajaa, ja minä hämmästyin, ja ei kenkään holhonut minua; vaan minun käsivarteni vapahti minun, ja minun vihani holhoi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Ja minä olen tallannut kansat vihassani, ja tehnyt heitä juovuksiin minun julmuudessani; ja sysäsin heidän voittonsa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Minä tahdon Herran laupiutta muistaa, ja Herran kiitosta kaikista niistä, mitkä Herra meille tehnyt on, ja sitä suurta hyvyyttä Israelin huoneelle, jonka hän sille tehnyt on, suuren laupiutensa ja hyvyytensä kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Sillä hän sanoo: he ovat tosin minun kansani, lapset, jotka ei valhetteliat ole; ja hän oli heidän vapahtajansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Kaikessa heidän ahdistuksessansa oli hänellä ahdistus, ja enkeli, joka hänen edessänsä on, autti heitä; rakkautensa ja armonsa tähden hän lunasti heitä, ja otti heitä ylös, ja kantoi heitä aina vanhasta tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Mutta he olivat vastahakoiset, ja vihoittivat hänen Pyhän Henkensä; sentähden hän muuttui heidän viholliseksensa, ja soti heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Ja hänen kansansa muisti taas entisiä Moseksen aikoja. Kussa siis nyt se on, joka heidät vei ulos merestä laumansa paimenen kanssa? Kussa on se, joka Pyhän Henkensä heidän sekaansa antoi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Joka oikialla kädellänsä Moseksen vei, kunniallisella käsivarrellansa; joka vedet jakoi heidän edellänsä, tehdäksensä itsellensä ijankaikkista nimeä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Joka heitä vei syvyyden kautta, niinkuin hevoset korvessa, ilman kompastumata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Niinkuin karjan, joka kedolle menee, saatti Herran Henki heidät lepoon, niin sinä myös kansas johdatit, tehdäkses itselles ijankaikkista nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Niin katso nyt taivasta, ja katso tänne alas pyhästä ja kunniallisesta asuinsiastas. Kussa nyt on kiivautes ja voimas? sinun suuri sydämellinen laupiutes kovennetaan minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Sinä olet kuitenkin meidän Isämme; sillä ei Abraham meistä mitään tiedä, ja ei Israel meitä tunne; mutta sinä Herra olet meidän Isämme ja meidän Lunastajamme; ja se on ijäti sinun nimes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Miksis, Herra, sallit meidän eksyä sinun teiltäs, ja annoit sydämemme paatua, ettemme sinua peljänneet? Palaja palveliais tähden ja perimises sukukuntain tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'He omistavat lähes kaiken sinun pyhän kansas; meidän vihollisemme polkevat sinun pyhyytes alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Me olemme juuri niinkuin ennenkin, kuin et sinä meitä hallinnut, ja emme olleetkaan sinun nimees nimitetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Jospa sinä taivaat halkaisisit, ja astuisit alas, että vuoret vuotaisivat sinun edessäs, niinkuin palava vesi kiehuu pois väkevällä tulella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Että sinun nimes tulis tiettäväksi sinun vihollisilles, ja että pakanat sinun edessäs vapisisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Niiden ihmeitten tähden, jotka sinä teet, joita ei kenkään toivonut; koska sinä menit alas, ja vuoret edessäs sulaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Ja ei maailman alusta kuultu, eikä korville tullut ole, eli yksikään silmä nähnyt ole, paitsi sinua Jumala, mikä niille tapahtuu, jotka sinua odottavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Sinä kohtasit niitä iloisna, jotka tekivät vanhurskautta, ja sinua muistelivat sinun teilläs. Katso, sinä vihastuit, koska me syntiä teimme ja kauvan niissä viivyimme, mutta kuitenkin meitä autettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Mutta me olemme kaikki saastaiset, ja kaikki meidän vanhurskautemme on niinkuin saastainen vaate; me olemme kaikki lakastuneet niinkuin lehdet, ja meidän syntimme viskoivat meitä niinkuin tuuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Ja ei ole sitä, joka rukoilee sinun nimeäs, ja nousee sinuun kiinni tarttumaan; sillä sinä peität kasvos meiltä, ja annat meidät nääntyä suurissa synneissämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Mutta nyt Herra, sinä olet meidän Isämme; me olemme savi, sinä olet meidän valajamme, ja me olemme kaikki sinun käsialas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Älä, Herra, niin kovin vihastu, ja älä ijäti ajattele syntiämme; katso sitä, että me olemme kaikki sinun kansas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Sinun pyhyytes kaupungit ovat hävitetyt, Zion on autioksi tehty ja Jerusalem on kylmillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Meidän pyhyytemme ja kunniamme huone, jossa meidän isämme sinua kunnioittivat, on tulella poltettu; ja kaikki meidän kauniimpamme ovat häväistyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Herra, maltatkos sinus näistä niin kovana pitää ja vaiti olla, ja lyödä meitä niin kovin alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Minä etsitään niiltä, jotka ei kysyneet minua; minä löytään niiltä, jotka ei minua etsineet; ja pakanoille, jotka ei rukoilleet minun nimeäni, sanon minä: tässä minä olen, tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Minä kokotan käteni koko päivän tottelemattomalle kansalle, joka vaeltaa ajatustensa jälkeen sitä tietä, joka ei hyvä ole;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Sille kansalle, joka vihoittaa minun, on aina minun kasvoini edessä: uhraa yrttitarhoissa, suitsuttaa tulikivien päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Asuu hautain keskellä, on yötä luolissa, syö sian lihaa, ja heillä on kauhia liemi heidän padoissansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Ja sanovat: mene puolelles, ja älä satu minuun, sillä minä olen pyhempi sinua: näiden pitää oleman savun minun vihassani, ja tulen, joka palaa koko päivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Katso, minun edessäni on kirjoitettu: en minä tahdo olla ääneti, vaan minä tahdon maksaa, ja maksaa heidän helmaansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Sekä teidän pahat tekonne, ja teidän isäinne pahat teot yhtenänsä, sanoo Herra: ne jotka vuorilla suitsuttaneet, ja minua kukkuloilla häväisseet ovat; minä tahdon jälleen mitata heidän entiset työnsä heidän helmaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Näin sanoo Herra: niinkuin viina löytään viinamarjoissa, ja sanotaan: älä sitä hävitä, sillä siinä on siunaus: juuri niin tahdon minä minun palveliani tähden tehdä, etten minä sitä kaikkea hävitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Vaan johdatan Jakobista siemenen, ja Juudasta sen, joka minun vuorellani asuman pitää; sillä minun valittuni pitää sen omistaman, ja minun palveliani siinä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Ja Saaronin pitää oleman laumain huoneen, ja Akorin laakson karjan pihaton, minun kansalleni, joka minua etsii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Mutta te, jotka hylkäätte Herran, ja unohdatte minun pyhän vuoreni, ja nostatte Gadille pöydän ja panette juomauhria täyteen Menille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Olkaan, minä tahdon lukea teitä miekkaan, niin että teidän kaikkein pitää lankeeman teurastamiseen; sillä minä kutsuin, ja ette mitään vastanneet, minä puhuin, ja ette kuulleet, vaan teitte pahaa minun silmäini edessä, ja valitsitte mitä en minä tahtonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Sentähden sanoo Herra, Herra näin: katso, minun palveliani syövät, mutta teidän pitää isooman; katso, minun palveliani juovat, mutta teidän pitää janooman; katso, minun palveliani iloitsevat, mutta teidän pitää häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Katso, minun palveliani riemuitsevat hyvästä mielestä, mutta teidän pitää sydämen kivusta parkuman, ja hengen ahdistuksessa ulvoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Ja teidän pitää jättämän teidän nimenne minun valituilleni valaksi; ja Herra Jumala on tappava sinun, mutta hänen palveliansa nimitetään toisella nimellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Että joka itsensä siunaa maan päällä, hän siunaa itsensä totisessa Jumalassa, ja joka vannoo maan päällä, se vannoo totisen Jumalan kautta; sillä entiset ahdistukset ovat unhotetut, ja ovat minun silmistäni peitetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Sillä katso, minä luon uuden taivaan ja uuden maan, ja entisiä ei pidä muistettaman, eikä mieleen johdatettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Vaan iloitkaat ja riemuitkaat ijankaikkisesti niissä, kuin minä luon; sillä katso, minä luon Jerusalemin iloksi ja hänen kansansa riemuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Ja minä tahdon iloita Jerusalemista ja riemuita minun kansastani; ja ei hänessä enään pidä kuultaman itkun ääntä eikä valituksen ääntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Ei siellä pidä enään lapsia oleman, jotka ei päiviinsä ulotu, eikä vanhoja, jotka ei vuosiansa täytä; sillä sadan vuotiset lapset pitää kuoleman, ja sadan ajastaikaiset syntiset pitää kirotut oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'He rakentavat huoneita, ja niissä asuvat: he istuttavat viinapuita, ja niiden hedelmistä syövät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Ei heidän pidä muiden asua rakentaman, eikä istuttaman muiden syödä; sillä minun kansani päivät pitää oleman niinkuin puun päivät, ja heidän käsialansa pitää vanheneman minun valittuini tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Ei heidän pidä hukkaan työtä tekemän, eikä turmeluksessa synnyttämän; sillä he ovat Herran siunattuin siemen, ja heidän jälkeentulevaisensa heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Ja tapahtuu, että ennenkuin he huutavat, tahdon minä vastata; koska he vielä puhuvat, tahdon minä kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Susi ja lammas pitää ynnä laitumella käymän, jalopeura ja härkä yhdessä korsia syömän, ja kärmeet pitää maata syömän. Ei heidän pidä vahinkoa tekemän, eikä turmeleman koko minun pyhällä vuorellani, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Näin sanoo Herra: taivas on minun istuimeni, ja maa minun jalkaini astinlauta. Mikä siis on se huone, jonka te minulle rakennatte, eli mikä on minun leposiani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Ja minun käteni on kaikki nämät tehnyt ja kaikki nämät ovat tehdyt, sanoo Herra; mutta minä katson sen puoleen, joka raadollinen ja särjetyllä hengellä on, ja joka vapisee minun sanani edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Sillä joka härjän teurastaa, on niinkuin hän miehenkin tappais; joka lampaan uhraa, on niinkuin hän koiran niskat taittais; joka ruokauhria tuo, on niinkuin hän sian verta uhrais; joka pyhää savua muistelee, on niinkuin hän vääryyttä kiittäis: näitä he valitsevat teissänsä, ja heidän sielunsa mielistyy heidän kauhistuksiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Sentähden tahdon minä myös valita heidän pilkkansa, ja jota he pelkäävät, sen saatan minä heidän päällensä; sentähden että minä kutsuin, ja ei kenkään vastannut, minä puhuin, ja ei he kuulleet. Ja he tekivät pahaa minun silmäini edessä, ja valitsivat, jota en minä tahtonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Kuulkaat Herran sanaa te, jotka hänen sanaansa pelkäätte: teidän veljenne, jotka teitä vihasivat, ja eroittivat teidät heistänsä minun nimeni tähden, he sanovat: olkoon Herra ylistetty! vaan ilmaantukaan hän teidän iloonne; mutta heidän pitää häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Sillä metelin ääni (pitää kuuluman) kaupungista, ääni templistä, Herran ääni, joka vihollisensa kostaa ansion jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Hän synnyttää ennenkuin hän saa kivun; hän synnyttää pojan ennenkuin hänen kipunsa tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kuka on ikänä senkaltaista kuullut? kuka on ikänä senkaltaista nähnyt? Saaneeko koko maa yhtenä päivänä synnyttämisen kivun? syntyneekö kaikki kansa yhtä haavaa? kuitenkin on Zion, saatuansa synnyttämisen kivun, myös synnyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Eikö minun, joka muut saatan synnyttämään, pitäisi itse myös synnyttämän? sanoo Herra; pitäiskö minun antaman muiden synnyttää, ja itse hedelmätöin oleman? sanoo sinun Jumalas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Iloitkaat Jerusalemin kanssa, ja ihastukaat hänestä kaikki, jotka häntä rakastatte; iloitkaat suuresti hänen kanssansa kaikki te, jotka tähänasti olette hänen tähtensä murheelliset olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Sillä teidän pitää imemän ja ravittaman hänen lohdutuksensa nisistä; teidän pitää lypsämän ja ilahuttaman teitänne hänen kunniansa kirkkaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Sillä näin sanoo Herra: katso minä levitän hänen tykönänsä rauhan niinkuin virran, ja pakanain kunnian niinkuin vuotavan ojan, jota te saatte imeä; ja teitä pitää sylissä kannettaman, ja polvien päällä ihanteleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Niinkuin äiti poikaansa lohduttaa, niin minä tahdon teitä lohduttaa, ja teidän pitää Jerusalemissa lohdutuksen saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Teidän pitää sen näkemän, ja teidän sydämenne pitää iloitseman, ja teidän luunne pitää vihoittaman niinkuin ruoho; niin tunnetaan Herran käsi hänen palvelioissansa, ja hänen vihollisissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Sillä katso, Herra tulee tulella, ja hänen rattaansa ovat niinkuin tuulispää; että hän kostais vihansa hirmuisuudessa, ja rangaistuksen tulen liekissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Sillä Herra on tuomitseva tulella ja miekallansa kaiken lihan; ja Herralta tapetuita pitää paljo oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Jotka heitänsä pyhittävät ja puhdistavat yrttitarhoissa, yksi täällä, toinen siellä, ja syövät sian lihaa, kauhistuksia ja hiiriä: kaikki nämät pitää lopetettaman yhtä haavaa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Sillä minä tahdon tulla ja koota heidän ajatuksensa ja tekonsa, ynnä kaikkein pakanain ja kielten kanssa, että he tulisivat ja näkisivät minun kunniani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Ja minä asetan merkin heidän sekaansa, ja muutamat niistä, kuin pelastetut ovat, lähetän minä pakanoille meren tykö, joutsimiehen puoleen, Puliin ja Ludiin, Tubaliin ja Javaan päin, ja niihin kaukaisiin saariin, joissa ei tähänasti mitään ole minusta kuultu, ja ei ole minun kunniaani nähneet: ja heidän pitää minun kunniani pakanain seassa ilmoittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Ja tuoman ulos kaikki teidän veljenne kaikista pakanoista, Herralle ruokauhriksi, hevosilla ja rattailla, paareilla, muuleilla ja liukkailla juhdilla Jerusalemiin minun pyhän vuoreni puoleen, sanoo Herra: niinkuin Israelinkin lapset tuovat ruokauhrin puhtaassa astiassa Herran huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Ja minä tahdon niistä ottaa papit ja Leviläiset, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Sillä niinkuin uudet taivaat ja uusi maa, jotka minä teen, ovat minun edessäni, sanoo Herra, juuri niin pitää teidän siemenenne ja nimenne pysymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Ja kaikki liha pitää yhdestä kuukaudesta niin toiseen, ja yhdestä sabbatista niin toiseen, tuleman kumartamaan minun eteeni, sanoo Herra:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Ja heidän pitää menemän ulos, ja katseleman niiden ihmisten raatoja, jotka minua vastaan väärin tekivät; sillä ei heidän matonsa pidä kuoleman, eikä heidän tulensa sammuman, ja heidän pitää kaikelle lihalle kauhistukseksi oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Jeremian Hilkian pojan sanat, joka oli Anatotin papeista, Benjaminin maata,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Jolle Herran sana tapahtui Josian Amonin pojan, Juudan kuninkaan aikana, kolmantenatoistakymmenentenä hänen valtakuntansa vuonna;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Ja sitte Josian pojan, Jojakimin, Juudan kuninkaan aikana, Zedekian Josian pojan, ensimäisen vuoden loppuun toistakymmentä, niin Jerusalemin vankiuteen asti, viidentenä kuukautena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Minä tunsin sinun jo ennenkuin minä sinun valmistin äitis kohdussa, ja pyhitin sinun ennenkuin sinä äidistäs synnyitkään, ja panin sinun kansain prophetaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Mutta minä sanoin: voi Herra, Herra! katso en minä kelpaa saarnaamaan; sillä minä olen nuori.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Niin Herra sanoi minulle: älä sano: minä olen nuori; mutta sinun pitää kaikkiin niihin menemän, mihin minä sinun lähetän, ja puhuman kaikkia, mitä minä sinulle käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Älä pelkää heitä; sillä minä olen tykönäs, ja pelastan sinun, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Ja Herra ojensi kätensä ja tarttui minun suuhuni; ja Herra sanoi minulle: katso, minä panen minun sanani sinun suuhus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Katso, minä panen sinun tänäpänä kansain ja valtakuntain päälle, repimään, särkemään, hukuttamaan ja kukistamaan: rakentamaan ja istuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Ja Herran sana tapahtui minulle ja sanoi: Jeremia, mitäs näet? Minä sanoin: Minä näen mandelpuisen sauvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Ja Herra sanoi minulle: oikein sinä olet nähnyt, sillä minä tahdon kiiruhtaa, tehdäkseni minun sanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Ja Herran sana tapahtui toisen kerran minulle ja sanoi: mitäs näet? Minä sanoin: minä näen kiehuvaisen padan, joka näkyy pohjan puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Ja Herra sanoi minulle: pohjasta on paha tuleva kaikkein maan asuvaisten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Sillä katso, minä kutsun kaikki valtakuntain sukukunnat, jotka ovat pohjassa, sanoo Herra; ja he tulevat ja kukin asettaa istuimensa Jerusalemin portin eteen, ja ympäri kaikkia hänen muurejansa, ja kaikkia Juudan kaupungeita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Ja minä annan oikeuden käydä heidän päällensä kaiken heidän pahuutensa tähden; että he ovat minun hyljänneet, ja muille jumalille suitsuttaneet, ja kumartaneet omaa käsialaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Niin vyötä nyt kupees, nouse ja saarnaa heille kaikki, mitä minä sinun käsken; älä pelkää heitä, etten minä sinua surmaisi heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Ja katso, minä teen tänäpänä sinun vahvaksi kaupungiksi, rautapatsaaksi ja vaskimuuriksi koko maassa: Juudan kuninkaita ja hänen ruhtinaitansa vastaan, hänen pappejansa ja maan kansaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Ja he sotivat sinua vastaan, ei kuitenkaan heidän pidä sinua voittaman; sillä minä olen sinun tykönäs, sanoo Herra, vapahtamassa sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Mene ja saarnaa julkisesti Jerusalemissa, ja sano: Näin sanoo Herra: minä ajattelen sitä hyvää työtä, joka sinulle tapahtui nuoruudessas, ja sitä rakkautta, jonka minä sinulle osoitin, koskas kaunis olit, ja minua korvessa seurasit, siinä maassa, jossa ei kylvetä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Koska Israel oli Herran pyhä ja hänen ensimäinen hedelmänsä; jokainen joka häntä söi, tuli vikapääksi, ja paha tuli hänen päällensä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Kuulkaat Herran sanaa, Jakobin huone ja kaikki Israelin huoneen sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Näin sanoo Herra: mitä vääryyttä teidän isänne minussa löysivät, että he erkanivat minusta ja menivät turhuuteen, ja tulivat turhaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Ja ei ensinkään ajatelleet: kussa se Herra on, joka meitä vei ulos Egyptin maalta, joka johdatti meitä korvessa, autiossa ja erämaassa, kuivassa ja kuoleman varjon maassa, siinä maassa, jossa ei yksikään ihminen vaeltanut eikä asunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Ja minä vein teidät hyvään maahan, sen hedelmää ja hyvyyttä syömään; mutta kuin te sinne tulitte, te minun maani ja minun perintöni teitte kauhistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Papit ei ajatelleet, kussa Herra on; lainoppineet ei tunteneet minua, paimenet luopuivat minusta ja prophetat ennustivat Baalin kautta ja seurasivat kelvottomia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Sentähden minä riitelen vielä teidän kanssanne, sanoo Herra, ja teidän lastenne lasten kanssa riitelen minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Niin menkäät Kittimin luotoihin ja katsokaat, ja lähettäkäät Kedariin, tutkistelkaat visusti ja katsokaat, onko siellä niin tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Muuttavatko pakanat jumaliansa? vaikka ei ne jumalat olekaan; ja kuitenkin minun kansani on muuttanut kunniansa kelvottomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Taivaat hämmästykäät siitä, peljästykäät ja vaviskaat, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Sillä minun kansani tekee kahtalaisen synnin: minun, joka olen elävän veden lähde, he hylkäävät, ja kaivavat itsellensä kaivoja, kelvottomia kaivoja, joissa ei vesi pysy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Onko Israel ostettu orja eli kotona syntynyt? miksi hän on joutunut saaliiksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Sillä nuoret jalopeurat kiljuvat hänestä ja huutavat: he hävittävät hänen maansa; ja hänen kaupunkinsa ovat poltetut, niin ettei niissä kenkään asu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Nophin ja Tahpanheksen lapset musertavat myös sinun pääs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Näitä sinä itselles teet, ettäs hylkäät Herran, sinun Jumalas, kuin hän sinua tahtoo viedä oikiaa tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Ja nyt, mitä sinun on Egyptin tiellä, ettäs tahdot juoda Sihorin vettä? eli mitä sinun on Assyria tiellä, ettäs tahdot juoda virran vedestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Sinun pahuutes tähden sinua nuhdellaan, ja sinun tottelemattomuutes tähden sinua kuritetaan; niin tiedä ja näe, kuinka viheliäinen ja surkia se on, ettäs hylkäät Herran, sinun Jumalas, ja et pelkää minua, sanoo Herra, Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Sillä minä olen jo vanhasta taittanut sinun ikees, ja särkenyt sinun juttas, ja sinä sanoit: en minä tahdo enään niitä palvella; kuitenkin jokaisella korkialla vuorella, ja kaikkein lehtipuiden alla juoksit sinä salavuoteudessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Mutta minä olen istuttanut sinun parhaaksi viinapuuksi ja totiseksi siemeneksi; kuinka sinä olet nyt muuttunut niin karvaaksi ja metsäviikunapuuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Sillä jos sinä vielä lipiällä pesisit itses ja ottaisit paljon saippuaa, kuitenkin sinun pahuutes näkyy minun edessäni, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kuinkas siis sanot: en minä ole saastainen, en minä seuraa Baalia? Katso tietäs laaksossa, ajattele, kuinkas tehnyt olet: sinä nopsa naaras kameli, joka sinne ja tänne juokset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Niinkuin metsä-aasi korvessa, kuin hän helteestä hengittää, kuka hänen taitaa asettaa? kaikki, jotka häntä etsivät, ei pidä väsymän; hänen kuukaudessansa hän löydetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Älä ole paljasjaloin ja älä janoa kärsi. Mutta sinä sanoit: ei se auta, vaan minä rakastan muukalaisia ja juoksen heidän perässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Niinkuin varas tulee häpiään, kuin hän saadaan kiinni, niin pitää myös Israelin huoneen häpiään tuleman, kuningastensa, valtamiestensä, pappeinsa ja prophetainsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Jotka puulle sanovat: sinä olet isäni, ja kivelle: sinä minun synnytit; Sillä he kääntävät selkänsä minun puoleeni ja ei kasvojansa; mutta kuin hätä tulee, sanovat he: nouse ja auta meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Kussa ovat jumalas, jotka sinä itselles tehnyt olet? Nouskaan ne, katso, taitavatko he sinua auttaa sinun hätäs aikana; sillä niin monta kuin sinulla, Juuda, on kaupunkia, niin monta on myös sinulla jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Miksi te tahdotte vielä riidellä minun kanssani? Te olette kaikki minusta luopuneet, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Turhaan minä rankaisin teidän lapsianne, ei he ota kuritusta; sillä teidän miekkanne syö teidän prophetanne, niinkuin turmeleva jalopeura.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Sinä paha sukukunta, ota vaari Herran sanasta: olenko minä nyt tullut Israelille korveksi, eli pimiäksi maaksi? Miksi siis minun kansani sanoo: me olemme herrat, emme enään tule sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Unohtaako neitsy kaunistuksensa eli morsian seppeleensä? Mutta minun kansani unohtaa minun ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Mitäs kaunistat ties, rakkautta etsiäkses? ja myös sentähden totutit sinun ties pahaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Löydetään myös vaivaisten ja viattomain sieluin veri sinun tykönäs joka paikassa, ja ei ne ole löydetty kätkettynä, vaan julki kaikissa niissä paikoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Ja sinä sanot: minä olen viatoin, hän kääntäköön vihansa minusta pois. Katso, minä tahdon oikeudelle käydä sinun kanssas, että sinä sanoit: en minä ole syntiä tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Miksi niin horjahtelet ja menet sinne ja tänne? Mutta sinun pitää Egyptiltä häpiän saaman, niinkuin sinä Assyrialtakin häpiän sait.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Sinä olet myös sieltä lähtevä ja lyövä kätes yhteen pääs päälle, sillä Herra tekee tyhjäksi sinun toivos, ja ei sinulla pidä mitään menestystä niissä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Sananlasku on: katso, kuin mies eroittaa vaimonsa tyköänsä, ja se menee pois hänen tyköänsä, ja ottaa toisen miehen, ottaako hän hänen jälleen? eikö maa niin peräti saastutettaisi? Mutta sinä olet huorin tehnyt monen ystäväs kanssa; mutta tule kuitenkin jälleen minun tyköni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Nosta silmäs ylös korkeuteen ja katso, kuinka sinä jokapaikassa huorin teet. Sinä istut tiellä, ja odotat heitä niinkuin ryöväri korvessa, ja saastutat maan huoruudellas ja pahuudellas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Sentähden pitää aamusateen tuleman pois, eikä ehtoosateen tuleman; sinulla on porton kasvot, et sinä tahdo ensinkään hävetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Ja kuitenkin sinä siitä ajasta huudat minua: minun Isäni, - minun nuoruuteni johdattaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Vihastuuko hän ijankaikkisesti, ja ei käänny julmuudestansa? Katso, sinä opetat, ja teet pahaa ja ei sinua taideta hillitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Ja Herra sanoi minulle, kuningas Josian aikana: oletko sinä nähnyt, mitä vastahakoinen Israel teki? Hän meni kaikille korkeille vuorille, ja jokaisen viheriäisen puun alle, ja teki siellä huoruutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Ja kuin hän näitä kaikkia tehnyt oli, sanoin minä: käännyt minun tyköni; mutta ei hän kääntynytkään; ja hänen petollinen sisarensa Juuda näki sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Ja minä näin, että vastahakoinen Israel kaikissa teki huorin, ja minä hylkäsin hänen, ja annoin hänelle erokirjan; ja ei hänen petollinen Juuda sitä peljännyt, vaan meni ja teki myös huorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Ja hänen huoruutensa sanomasta on maakunta saastutettu; sillä hän tekee huoruutta kiven ja puun kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Ja kaikissa näissä ei hänen petollinen sisarensa Juuda kääntynyt minun tyköni kaikesta sydämestänsä, vaan petollisesti, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Ja Herra sanoi minulle: vastahakoinen Israel on jaloksi luettava petollisen Juudan suhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Mene ja saarnaa nämät sanat pohjaan päin, ja sano: käänny, sinä vastahakoinen Israel, sanoo Herra, niin en minä käännä kasvojani teistä pois; sillä minä olen laupias, sanoo Herra, ja en vihastu ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Tunne ainoastaan sinun pahat tekos, ja ettäs olet Herraa sinun Jumalaas vastaan syntiä tehnyt, ja juossut sinne tänne vierasten jumalain tykö, kaikkein viheriäisten puiden alle; ja ette kuulleet minun ääntäni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Kääntykäät, te vastahakoiset lapset, sanoo Herra; sillä minä kihlaan teidät minulleni, ja otan teidät yhden kaupungista ja kaksi koko sukukunnasta, ja tahdon teidät viedä Zioniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Ja annan teille paimenet minun sydämeni jälkeen, jotka teitä pitää ravitseman opilla ja viisaudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Ja se on silloin tapahtuva, kuin te moneksi tulette ja kasvatte maassa, ettei siihen aikaan, sanoo Herra, pidä enään puhuttaman Herran liitonarkista, eikä ajateltaman, ei myös sitä enään muistettaman, eli etsittämän, taikka enään tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Mutta Jerusalem pitää siihen aikaan kutsuttaman Herran istuimeksi, ja kaikki pakanat pitää sinne kokoontuman Herran nimeen Jerusalemiin: eikä heidän pidä enää vaeltaman pahan sydämensä ajatusten jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Siihen aikaan pitää Juudan huoneen menemän Israelin huoneen tykö, ja pitää ynnä tuleman pohjan puoliselta maalta siihen maahan, jonka minä olen antanut teidän isillenne perinnöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Ja minä sanon: kuinka minä olen monta lasta antava sinulle, ja sen hyvän maan ja ihanaisen perinnön, pakanain joukon. Ja minä sanon: sinä olet kutsuva minun Isäkses, etkä luovu minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Kuitenkin, niinkuin vaimo pettää rakastajansa, niin olette te minusta luopuneet, te Israelin huone, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Sentähden pitää kuuluman valitus, itku ja parku Israelin lapsilta korkeissa paikoissa; sillä he ovat tiensä turmelleet, ja Herran Jumalansa unohtaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Niin palatkaat, te vastahakoiset lapset niin minä parannan teitä teidän tottelemattomuudestanne. Katso, me tulemme sinun tykös; sillä sinä olet Herra meidän Jumalamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Totisesti on sula petos kukkuloilla ja kaikilla vuorilla: totisesti on Israelin autuus (ainoassa) Herrassa meidän Jumalassamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Ja meidän isäimme asetukset, jotka me nuoruudesta olemme pitäneet, pitää häpiällä käymän pois, ynnä heidän lammastensa, karjansa, poikainsa ja tytärtensä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Meidän täytyy maata häpiässämme, ja meidän ylönkatseemme peittää meidät; sillä me teimme syntiä Herraa meidän Jumalaamme vastaan, sekä me että meidän isämme, meidän hamasta nuoruudestamme niin tähän päivään asti, ja emme totelleet Herran meidän Jumalamme ääntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Jos sinä käännyt, Israel, sanoo Herra, niin käänny minun tyköni; ja jos sinä panet kauhistukset pois minun kasvoini edestä, niin et sinä tule ajetuksi pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Silloin sinä olet vannova: niin totta kuin Herra elää, totuudessa oikeudessa ja vanhurskaudessa: ja pakanat siunataan hänessä, ja he kerskaavat hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Sillä näin sanoo Herra: te Juudan ja Jerusalemin miehet, kyntäkäät vastuudesta, ja älkäät kylväkö orjantappurain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Ympärileikatkaat teitänne Herralle, ja pankaat teidän sydämenne esinahka pois, te Juudan miehet ja Jerusalemin asuvaiset; ettei minun julmuuteni pääsisi vallallensa niinkuin tuli, ja niin palaisi, ettei yksikään sitä sammuttaa taida, teidän pahuutenne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Ilmoittakaat Juudassa ja antakaat kuulla Jerusalemissa, ja sanokaat: soittakaat vaskitorvea maassa, huutakaat korkialla äänellä ja sanokaat: kootkaat teitänne, ja käykäämme kaikki vahvoihin kaupunkeihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Nostakaat lippu Zionissa, kootkaat teitänne pakoon ja älkäät viivytelkö; sillä minä annan tulla onnettomuuden pohjasta ja suuren viheliäisyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Jalopeura nousee luolastansa, ja pakanain hävittäjä sanoo ja lähtee paikastansa, hävittämään sinun maatas; sinun kaupunkis pitää kukistettaman, niin ettei kenkään niissä asu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Sentähden pukekaat säkit yllenne, itkekäät ja parkukaat; sillä Herran julma viha ei tahdo meistä lakata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Siihen aikaan, sanoo Herra, pitää kuningasten ja pääruhtinasten sydän lankeeman, pappein pitää peljästymän ja prophetain hämmästymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Mutta minä sanoin: voi! Herra, Herra, sinä olet antanut tämän kansan ja Jerusalemin suuresti pettää itsensä, sanoen: Teillä on oleva rauha; ja kuitenkin miekka hamaan sieluun asti lähestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Silloin pitää sanottaman tälle kansalle ja Jerusalemille; kuiva tuuli on tuleva vuorten ylitse korvesta minun kansani tyttären tielle, joka ei viskaa eli puhdista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Sangen väkevä tuuli pitää niistä minulle tuleman. Niin minä myös nyt tahdon puhua heidän kanssansa oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Katso, hän nousee niinkuin pilvi, ja hänen vaununsa niinkuin tuulispää, hänen hevosensa ovat nopiammat kotkaa. Voi meitä! sillä me hävitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Niin pese nyt, Jerusalem, sinun sydämes pahuudesta, ettäs autetuksi tulisit; kuinka kauvan pitää pahat ajatukset sinun tykönäs pysymän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Sillä Daanista kuuluu sanoma ja ahdistus Ephraimin vuorelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Sanokaat pakanoille: katso, kuuluttakaat Jerusalemissa, vartiat tulevat kaukaiselta maalta, jotka luihkaavat Juudan kaupungeita vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'He piirittävät heidän kaikilta haaroilta, niinkuin vartiat kedolla; sillä he ovat vihoittaneet minun, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Sinun ties ja sinun harjoitukses ovat nämä sinulle tehneet; tämän on sinun pahuutes; että se niin karvas on ja käy sinun sydämees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Kuinka on minun sydämeni kipiä, minun sydämeni tykyttää ruumiissani, ja ei ole lepoa; sillä minun sieluni kuulee vaskitorven äänen ja sodan huudon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Hävitys kuuluu hävityksen perään, sillä koko maa hajoitetaan; ja minun majani ja peitteeni pitää sangen äkisti kukistuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Kuinka kauvan pitää minun näkemän lippuja ja kuuleman vaskitorven ääntä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Että minun kansani on hullu, ja ei tunne minua; he ovat tyhmät lapset, ja ei ymmärrä; viisaat ovat he kyllä pahaa tekemään, vaan hyvää tehdä ei ole heillä taitoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Minä katsoin maan päälle, katso, se oli tyhjä ja autio, ja taivaan päälle, ja se oli pimiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Minä katsoin vuorten päälle, ja katso, ne vapisivat, ja kaikki kukkulat värisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Minä näin, ja katso, ei ollut siellä yhtään ihmistä; kaikki myös taivaan linnut olivat lentäneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Minä katsoin, katso, hedelmällinen pelto oli autiona, ja kaikki kaupungit olivat kukistetut maahan Herralta, ja hänen julmalta vihaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Sillä näin sanoo Herra: koko maa pitää kylmille tuleman; ja en minä kuitenkaan sitä peräti hävitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Sentähden pitää maan oleman surullisen, ja taivaan ylhäältä murheellisen; sillä minä olen sanonut: minä olen sen päättänyt, ja en tahdo sitä katua, enkä siitä lakata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Kaikki kaupungit pitää pakeneman hevosmiesten ja joutsimiesten huutoa, ja juokseman tihkuihin metsiin ja lymyttämän itsensä kiviraunioihin; kaikki kaupungit pitää oleman kylmillä, niin ettei yksikään niissä asu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Mitäs tahdot tehdä sinä hävitetty? Jos sinä vielä kaunistaisit sinus purppuravaatteella ja kultakäädyillä, voitelisit kasvos, niin sinä kuitenkin sinuas turhaan kaunistelet; sillä ne, jotka nyt ovat sinua rakastaneet, pitää katsoman sinua ylön, ja väijymän sinun henkeäs:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Sillä minä kuulin huudon, niinkuin synnyttäväiseltä, tuskan, niinkuin sen, joka ensimäisen lapsen vaivassa on, Zionin tyttären äänen, joka valittaa ja hajoittaa kätensä: voi minuani! sillä sieluni on väsynyt surmaajain tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Käykäät Jerusalemin katuja ympäri, katsokaat, koetelkaat ja etsikäät hänen kaduillansa, löydättekö jonkun, joka oikein tekee ja kysyy totuutta; niin minä olen hänelle armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Ja jos he vielä sanoisivat: niin totta kuin Herra elää; niin he kuitenkin vannovat väärin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Herra, eikö sinun silmäs katso uskoa? Sinä lyöt heitä, ja ei he tunne kipua; sinä vaivaat heitä, mutta ei he tahdo kuritusta vastaanottaa; heillä on kovempi kasvo kuin kivi, ja ei tahdo kääntyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Mutta minä sanoin: se on vaivainen joukko; he ovat ymmärtämättömät, ja ei tiedä Herran tietä eikä Jumalansa oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Minä käyn voimallisten tykö ja puhun heidän kanssansa; sillä heidän pitää tietämän Herran tien ja Jumalansa oikeuden. Mutta ne ovat kaikki ikeen särkeneet, ja katkaisseet siteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Sentähden pitää jalopeuran, joka metsästä tulee, repelemän heidät rikki, ja suden korvesta pitää haaskaaman heitä ja pardin pitää vartioitseman heidän kaupungeitansa, ja kaikki, jotka niistä tulevat ulos, pitää raadeltaman; sillä heidän syntejänsä on juuri monta, ja he ovat paatuneet tottelemattomuudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kuinka siis minun pitää sinulle oleman armollinen? että lapses hylkäävät minun ja vannovat sen kautta, joka ei Jumala olekaan; ja nyt, että minä olen heitä ravinnut, tekevät he huorin ja kokoontuvat porton huoneesen joukkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Kukin hirnuu lähimmäisensä emäntää, niinkuin hyvin ruokitut joutilaat orhiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Eikö minun pitäis heitä senkaltaisista kurittaman, sanoo Herra: ja eikö minun sieluni pitäis kostaman senkaltaiselle kansalle kuin tämä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Kukistakaat hänen muurinsa ylösalaisin, ja älkäät peräti hävittäkö, ottakaat pois hänen torninsa; sillä ei ne ole Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Mutta he ovat petoksella minusta pois luopuneet, sekä Israelin huone että Juudan huone, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'He kieltävät pois Herran ja sanovat: ei hän se ole, ei meille käy niin pahoin, ei miekka ja nälkä tule meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Prophetat puhuvat tuuleen: ei heillä ole (Jumalan) sanaa: niin heille itselleen käyköön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Sentähden näin sanoo Herra Jumala Zebaot: että te senkaltaisia puhutte, katso, niin minä teen minun sanani sinun suussas tuleksi, ja tämän kansan puuksi, ja hänen pitää polttaman heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Katso, minä annan tulla teidän päällenne, Israelin huone, sanoo Herra; kaukaa yhden kansan, väkevän kansan, joka on ollut ensimäinen kansa, kansan, jonka kieltä et sinä ymmärrä, etkä taida ymmärtää, mitä he sanovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Heidän viinensä on avoin hauta; ja he ovat kaikki väkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'He syövät sinun tulos ja leipäs, jota sinun poikas ja tyttäres syöneet olisivat; he nielevät sinun lampaas ja karjas; he syövät sinun viinapuus ja fikunapuus; ja hävittävät sinun vahvat kaupunkis miekalla, joihin sinä luotat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Ja en minä silloinkaan, sanoo Herra, peräti hävitä teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Ja jos sanotte: miksi Herra meidän Jumalamme tekee meille näitä kaikkia? niin vastaa heitä: niinkuin te olette hyljänneet minun, ja palvelleet vieraita jumalia teidän omassa maassanne, niin teidän pitää myös palveleman vieraita siinä maassa, joka ei teidän olekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Näitä teidän pitää ilmoittaman Jakobin huoneessa, ja saarnaaman Juudassa, ja sanoman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Kuulkaat nyt tätä, te hullu kansa, joilla ei taitoa ole, jolla on silmät, ja ei näe, korvat, ja ei kuule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Ettekö te tahdo peljätä minua, sanoo Herra? ja ettekö te pelkää minun kasvoini edessä? joka panen hiedan meren rajaksi ja ijankaikkiseksi määräksi, jota ei hänen pidä käymän ylitse; ja vaikka se pauhais, niin ei se kuitenkaan voi sen ylitse; ja jos hänen aaltonsa paisuvat, niin ei heidän pidä menemän sen ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Mutta tällä kansalla on vilpisteleväinen ja tottelematoin sydän; he ovat harhailleet ja menneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Ja ei sano koskaan sydämessänsä: peljätkäämme nyt Herraa meidän Jumalaamme, joka antaa meille aamu- ja ehtoosateen ajallansa, ja varjelee meille joka ajastaika elonajan uskollisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Mutta teidän pahat tekonne nämä estävät, ja teidän syntinne tämän hyvän teiltä kääntävät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Sillä minun kansassani löytyy jumalattomia, jotka paulat ja pyydykset asettavat ihmisiä käsittääksensä, niinkuin lintumiehet satimella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Ja heidän huoneensa on täynnä petosta, niinkuin häkki lintuja; siitä he tulevat väkeviksi ja rikkaiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'He kiiltävät lihavuudesta; he säkevät pahan asian, ja ei pidä oikeutta: ei he holho orpoa hänen asiassansa, ja ei he auta köyhää oikeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Eikö minun pitäisi sitä kostaman, sanoo Herra, ja eikö minun sieluni pitäisi kostaman senkaltaiselle kansalle kuin tämä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Kuinka julmasti ja kauhiasti eletään maassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Prophetat opettavat valhetta, papit ovat herrat virassansa, ja minun kansani tahtoo sitä mielellänsä. Mitä te viimein teette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Kootkaat teitänne, te Benjaminin lapset, Jerusalemista, ja puhaltakaat torveen Tekoassa, ja nostakaat lippu Betkeremissä; sillä pohjasta on pahuus ja suuri viheliäisyys käsissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Minä olen verrannut Zionin tyttären kauniisen ja ihanaiseen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Mutta paimenet tulevat hänen tykönsä laumoinensa; he panevat majansa hänen ympärillensä, ja kukin kaitsee paikassansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '(Ja sanoo:) pyhittäkäät sota häntä vastaan, nouskaat ja käykäämme puolipäivänä ylös; voi meitä! sillä ehtoo joutuu ja varjo tulee suureksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Nouskaat ja astukaamme ylös yöllä, ja hävittäkäämme hänen jalot huoneensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Sillä näin sanoo Herra Zebaot: kaatakaat puita, ja tehkäät multaseiniä Jerusalemia vastaan; sillä kaupunki pitää kuritettaman, sen sisällä on sula vääryys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Niinkuin lähde kuohuttaa vetensä; niin kuohuu myös hänen pahuutensa; vääryys ja hävitys siinä kuullaan, kitu ja vaiva on aina minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Anna sinuas kurittaa, Jerusalem, ettei minun sydämeni kääntyisi pois sinusta, etten minä sinua hävittäisi, niin ettei kenkään asu siinä maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Näin sanoo Herra Zebaot: mitä Israelissa jäänyt on, se pitää myös sulaksi saaliiksi joutuman niinkuin viinapuu; kokota kätes koriin niinkuin viinamarjain poimia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Kenelle siis minä puhun ja todistan, että joku kuulis? Katso, heidän korvansa ovat ympärileikkaamatta eikä taida kuulla; katso, he pitävät Herran sanan pilkkana ja ei kärsi sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Sentähden olen minä niin täynnä Herran vihaa, etten minä taida lakata vuodattamasta, sekä lasten päälle kaduilla, ja myös nuorukaisten kokouksen päälle yhtä haavaa; sillä sekä mies että vaimo, ijällinen ja ikivanha pitää otettaman kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Heidän huoneensa pitää tuleman muukalaisten käsiin, heidän peltonsa ja emäntänsä yhtä haavaa; sillä minä ojennan käteni maan asujain ylitse, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Sillä he kaikki ahnehtivat, sekä pienet että suuret; prophetat ja papit opettavat väärin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Ja lohduttavat kansaani hänen viheliäisyydessänsä, sitä halpana pitämään, ja sanovat: rauha, rauha; ja ei rauhaa olekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Sentähden pitää heidän häpiään tuleman, että he kauhistuksen tekevät; ja vaikka he tahtovat olla häpäisemättä, eikä taida hävetä, kuitenkin pitää heidän jokaisen lankeeman toinen toisensa päälle; ja koska minä heitä kuritan, silloin pitää heidän lankeeman, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Näin sanoo Herra: seisokaat teillä, katsokaat ja kysykäät entisiä teitä, kuka oikia tie on, sitä te vaeltakaat, niin te löydätte levon teidän sieluillenne. Mutta he sanovat: emme vaella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Ja minä olen pannut teille vartiat: ottakaat vaari torven äänestä; mutta he sanovat: emme ota vaaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Sentähden, te pakanat, kuulkaat, ja ota vaari, sinä kokous, niistä mitkä heidän seassansa tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Maa, kuule sinä; katso, minä annan tulla kovan onnen tälle kansalle, heidän ansaitun palkkansa, ettei he pidä lukua minun sanastani, mutta hylkäävät minun lakini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Mitä minä lukua pidän pyhästä savusta, joka rikkaasta Arabiasta tulee, eli hyvästä kanelista, joka kaukaiselta maalta tulee? Teidän polttouhrinne ei ole minulle otollinen eikä teidän uhrinne kelpaa minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Sentähden sanoo Herra näin: katso, minä annan tälle kansalle lankeemuksen: siihen pitää sekä isät että lapset kaikki itsensä loukkaaman, ja kylän miehet pitää hukkuman toinen toisensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Näin sanoo Herra: katso, kansa on tuleva pohjoisesta maakunnasta, ja suuri kansa on nouseva maan vieristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Jolla on joutset ja kilvet, hän on julma ja armotoin; heidän äänensä pauhaa niinkuin meri; he ajavat hevosilla, he ovat niinkuin varustettu sotaväki sinua vastaan, sinä tytär Zion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Me olemme kuulleet heistä sanoman, ja meidän kätemme ovat nääntyneet; tuska ja ahdistus on meidät käsittänyt niinkuin lapsensynnyttäjän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Älkään kenkään lähtekö pellolle, ja älköön kenkään tielle menkö; sillä joka paikassa on rauhattomuus vihollisen miekan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'O sinä, minun kansani tytär, pue säkki ylles ja aseta itses tuhkaan, sure niinkuin ainoaa poikaa suurella murheella; sillä hävittäjä tulee äkisti meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Minä olen pannut sinun vartian torniksi ja linnaksi minun kansassani, tietämään ja koettelemaan heidän teitänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'He ovat kaikki peräti pois luopuneet, vaeltain petollisesti; he ovat kaikki turmeltu vaski ja rauta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Palkeet ovat tulella poltetut, lyijy raukee pois, sulaaminen on hukassa; sillä ei paha ole eroitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Sentähden he myös kutsutaan hyljätyksi hopiaksi, sillä Herra on heidät hyljännyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Tämä on sana tapahtui Herralta Jeremialle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Seiso Herran huoneen portissa, saarnaa siellä tämä sana ja sano: kuulkaat Herran sanaa, kaikki Juuda, jotka käytte sisälle näistä porteista rukoilemaan Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Näin sanoo Herra Zebaot, Israelin Jumala: parantakaat elämänne ja menonne, ja minä tahdon antaa teidän asua tässä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Älkäät luottako valheesen, sanoen: tässä on Herran templi, tässä on Herran templi, tässä on Herran temppeli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Mutta parantakaat todella elämänne ja menonne, ja tehkäät jalo oikeus yhden ja toisen välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Muukalaisille, orvoille ja leskille älkäät tehkö väkivaltaa, älkäät myös vuodattako viatointa verta tässä paikassa, ja älkäät muita jumalia seuratko itsellenne vahingoksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Niin minä tahdon antaa teidän asua tässä paikassa aina ja ijankaikkisesti, tässä maassa, jonka minä annoin teidän isillenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Mutta te luotatte valheesen, joka ei mitään auta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Ja te olette vielä sittenkin varkaat, murhamiehet, huorintekiät, valapattoiset ja suitsutatte Baalille, ja noudatatte vieraita jumalia, joita ette tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Te tulette myös ja seisotte minun edessäni tässä huoneessa, joka minun nimelläni kutsutaan, ja sanotte: ei meidän mitään hätää ole, vaikka me teemme nämät kauhistukset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Pidättekö te siis tämän huoneen, joka minun nimelläni nimitetty on, ryövärien luolana? Katso, kyllä minä sen näen, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Mutta menkäät nyt minun paikkaani, joka on Silossa, jossa minun nimeni ennen asunut on, ja katsokaat, mitä minä siellä tehnyt olen kansani Israelin pahuuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Että te nyt kaikkia näitä töitä teette, sanoo Herra, ja minä olen varhain noussut ja puhunut teille, ja ette tahdo kuulla, minä huudan, ja ette tahdo vastata;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Niin minä myös tahdon tehdä tämän huoneen kanssa, joka minun nimelläni nimitetty on, johon te luotatte, ja sen paikan kanssa, jonka minä teille ja teidän isillenne annoin, niinkuin minä tein Silon kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Ja heitän teitä pois minun kasvoini edestä, niinkuin minä heitin pois kaikki teidän veljennekin, kaiken Ephraimin siemenen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Ja ei sinun pidä rukoileman tämän kansan edestä, eikä myös yhtäkään valitusta eli rukousta tuoman edes, eli sinuas minun eteeni heidän tähtensä vaivaaman; sillä en minä tahdo sinua kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Etkös näe, mitä he tekevät Juudan kaupungeissa ja kujilla Jerusalemissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Lapset kantavat puita, ja isät tekevät valkiaa, ja vaimot tekevät taikinaa uhrataksensa leipiä taivaan kuningattarelle, ja antaaksensa juomauhria vieraille jumalille, että he minua vihoittaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Mutta ei he minulle tee sillä mielikarvautta, sanoo Herra, vaan itsellensä, ja heidän pitää häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Sentähden näin sanoo Herra, Herra: katso, minun vihani ja minun julmuuteni on vuodatettu tähän paikkaan, sekä ihmisiin että karjaan, puihin metsässä ja maan hedelmään, joka pitää palaman, niin ettei yksikään sitä sammuttaa taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Näin sanoo Herra Zebaot, Israelin Jumala: kootkaat teidän polttouhrinne ja muut uhrinne ja syökäät lihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Sillä sinä päivänä, jona minä teidän isänne johdatin Egyptin maalta, en minä sanonut enkä käskyä antanut heille polttouhrista, enkä muusta uhrista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Vaan minä käskin heille ja sanoin: kuulkaat minun sanaani, niin minä tahdon olla teidän Jumalanne, ja te olette minun kansani; ja vaeltakaat kaikilla niillä teillä, joita minä käsken, että teille kävis hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Mutta ei he tahtoneet kuulla eikä korviansa kallistaa, vaan vaelsivat omassa neuvossansa ja pahan sydämensä halussa, ja kävivät takaperin ja ei edespäin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Ja siitä päivästä, kun teidän isänne läksivät Egyptin maalta, niin tähän päivään asti, olen minä lähettänyt joka päivä teille kaikki minun palveliani, prophetat, minä nousin varhain ja lähetin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Mutta ei he tahtoneet kuulla eikä korviansa kallistaa; vaan olivat niskurit, ja tekivät pahemmin kuin heidän isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Ja jos sinä kaikki nämät sanot heille, niin ei he sittekään kuule sinua; ja jos sinä huudat, niin ei he sittekään sinua vastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Sentähden sano heille: tämä on se kansa, joka ei Herran Jumalansa ääntä kuule, eikä tahdo kuritusta vastaan ottaa; totuus on peräti pois ja on temmattu heidän suustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Leikkaa hiukses ja heitä pois tyköäs, ja surkuttele sinuas valittain korkeuksissa; sillä Herra on hyljännyt ja ajanut tämän sukukunnan pois, jolta hän on vihoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Sillä Juudan lapset tekevät pahaa minun silmäini edessä, sanoo Herra; he panevat siihen huoneesen kauhistuksen, joka minun nimelläni nimitetty on, saastuttaaksensa sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Ja he rakentavat Tophetin alttarin Hinnomin lasten laaksossa, polttaaksensa poikiansa ja tyttäriänsä tulessa; jota en minä käskenyt enkä ajatellut ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Sentähden katso, se aika tulee, sanoo Herra, ettei se pidä kutsuttaman Tophetiksi ja Hinnomin lasten laaksoksi, vaan Murhalaaksoksi; ja Tophetissa pitää haudattaman ruumiita, ettei enään ole siaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Ja tämän kansan ruumiit pitää taivaan lintuin ja maan eläinten ruaksi tuleman, ja ei yksikään pidä heitä siitä ajaman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Ja minä otan pois Juudan kaupungeista ja Jerusalemin kaduilta ilon ja riemun äänen, yljän ja morsiamen äänen; sillä maan pitää kylmille tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Siihen aikaan, sanoo Herra, pitää Juudan kuningasten luut, ja hänen päämiestensä luut, pappein luut, ja prophetain luut, ja Jerusalemissa asuvaisten luut, heitettämän ulos heidän haudoistansa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Ja ne pitää hajoitettaman auringon, kuun ja kaiken taivaan sotajoukon alle, joita he rakastaneet, palvelleet, seuranneet, etsineet ja rukoilleet ovat; ei he pidä enään koottaman eikä haudattaman, vaan pitää oleman lokana maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Ja kaikki jääneet tästä pahasta kansasta, missä ikänä paikassa he ovat, johon minä heitä ajanut olen, pitää paremmin tahtoman olla kuolleina kuin elävinä, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Ja sinun pitää heille sanoman: näin sanoo Herra: kussa on joku, jos hän lankee, joka ei jälleen mielellänsä nouse? kussa on joku, joka käy eksyksissä, eikö hän mielellänsä jälleen oikialle tielle tule?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Miksi siis tämä Jerusalemin kansa tahtoo käydä eksyksissä palajamatta? ja riippuvat niin kovin valheessa, ettei he millään tavalla anna kääntää itseänsä pois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Minä havaitsen ja kuulen, ettei he oikein opeta; ei ole yhtään, joka katuu pahuuttansa ja sanoo: mitä minä tein? He juoksevat kaikki juoksuansa niinkuin ankara hevonen sodassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Haikara taivaan alla tietää aikansa, mettinen, kurki ja pääskynen huomaitsevat aikansa, kuin heidän pitää tuleman jälleen; vaan minun kansani ei tiedä Herran oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Kuinka te siis taidatte sanoa: me olemme viisaat, ja meillä on Herran laki? Katso, se on totisesti kuitenkin valhe, mitä kirjanoppineet kirjoittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Sentähden pitää senkaltaiset opettajat häväistämän, peljätettämän ja otettaman kiinni: katso, he ovat hyljänneet Herran sanan, mitä viisautta pitäis heillä oleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Sentähden annan minä heidän emäntänsä muukalaisille ja heidän peltonsa niille, jotka heitä karkoittavat; sillä he ovat kaikki ahneudelta voitetut, pienimmästä niin suurimpaan, papit ja prophetat opettavat kaikki valhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Ja rohkaisevat minun kansani tytärtä onnettomuudessansa, sitä turhana pitämään, ja sanovat: rauha, rauha, ja rauhaa ei olekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Sentähden pitää heidän häpiään tuleman, että he kauhistuksen tekevät; ja vaikka he tahtovat ilman häväistystä olla, eikä taida hävetä, kuitenkin pitää heidän lankeeman toinen toisensa päälle, ja kuin minä heitä kuritan, silloin pitää heidän lankeeman, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Minä tahdon heitä niin poimia, sanoo Herra, ettei yhtäkään viinimarjaa pidä viinapuussa oleman, eikä yhtäkään fiikunapuussa, lehdet pitää variseman; ja se, minkä minä heille antanut olen, pitää heiltä otettaman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Miksi me niin alallamme istumme? Kootkaat teitänne, käykäämme vahvoihin kaupunkeihin ja odottakaamme niissä apua: sillä Herra meidän Jumalamme on meidän käskenyt odottaa, ja juottanut meitä katkeralla siemenellä, että me niin teimme Herraa vastaan syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Odota rauhaa ja terveyden aikaa, ehkei mitään hyvää ole käsissä, ja että te parannettaisiin, ehkei muuta ole kuin hämmästys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Jo nyt kuuluu hamasta Danista hevosten hirnuminen, ja heidän orhiinsa korskuvat, niin että kaikki maa järisee. He tulevat ja syövät maan, ja kaikki mitä siinä on, kaupungin ja sen asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Sillä katso, minä lähetän kärmeet ja basiliskit teidän sekaanne, joita ei auta lumoomaan; vaan niiden pitää teitä pistämän, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Minun virvoitukseni on murheella sekoitettu, ja minun sydämeni on nääntynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Katso, minun kansani tyttären pitää vieraalta maalta huutaman: eikö Herra tahdo enään olla Zionissa? eli eikö hänellä enään ole kuningasta? Miksi he vihoittivat minun kuvillansa ja turhalla vieraan jumalan palveluksella?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Elonaika on mennyt edes, suvi on loppunut, ja ei meille ei ole apua tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Minä suren suuresti, että minun kansani tytär, niin turmeltu on; minä surkuttelen ja olen hämmästyksissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Eikö Gileadissa ole voidetta, eli eikö siellä ole parantajaa? miksi ei minun kansani tytär ole terveeksi tehty?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Jospa minun päässäni olis kyllä vettä, ja minun silmäni olis kyynelten lähde, että minä voisin itkeä päivää ja yötä lyötyjä minun kansastani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Jospa minulla olis matkamiesten maja korvessa, niin minä jättäisin minun kansani ja menisin pois heidän tyköänsä; sillä he ovat kaikki huorintekiät ja paha joukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'He ampuvat kielellänsä niinkuin joutsellansa valhetta ja ei totuutta; vaeltavat väkivallalla maassa ja menevät yhdestä pahuudesta niin toiseen, ei totellen minua, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Jokainen karttakoon lähimmäistänsä, ja älköön uskoko veljeänsäkään; sillä veli sortaa ja painaa alas veljensä, ja ystävä pettää ystävänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Ystävä pilkkaa ystäväänsä, ja ei puhu totuutta; he totuttavat kielensä puhumaan valhetta, ja ahkeroitsevat pahaa tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Sinä asut petoksen keskellä, ja ei he taida minua tuta petoksen tähden, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Sentähden sanoo Herra Zebaot näin: katso, minä sulaan heitä; ja koettelen heitä; sillä mitä minä muuta teen minun kansani tyttären tähden?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Heidän petolliset kielensä ovat murhanuolet; suullansa he puhuvat lähimmäisensä kanssa ystävällisesti, vaan sydämessänsä he väijyvät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Eikö minun sentähden pitäisi rankaiseman heitä, sanoo Herra? ja eikö minun sieluni pitäisi kostaman senkaltaiselle kansalle kuin tämä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Minä itken ja surkuttelen vuorilla, ja valitan korvessa laitumilla; sillä he ovat peräti hajoitetut, niin ettei siitä enään kenkään vaella, ei myös siellä kuulu karjan ääntä; taivaan linnut ja kaikki karja ovat jo lentäneet ja menneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Ja minä teen Jerusalemin kiviraunioksi, ja lohikärmeiden pesäksi; ja minä hävitän Juudan kaupungit, niin ettei niissä yhtäkään pidä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Joka viisas olis, hän ajattelis sitä, ja ilmoittais, mitä Herran suu hänelle sanoo. Minkätähden siis maa niin hukutetuksi ja hävitetyksi tulee, että se on niinkuin erämaa, josta ei yksikään vaella?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Ja Herra sanoi: sentähden, että he hylkäävät minun lakini, jonka minä heille annoin, ja ei tottele minun ääntäni eikä elä sen jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Vaan seuraavat oman sydämensä tahtoa ja Baalia, niinkuin heidän isänsä heitä opettaneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Sentähden näin sanoo Herra Zebaot, Israelin Jumala: katso, minä syötän tämän kansan koiruoholla, ja annan heidän sappea juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Minä hajoitan heidät pakanain sekaan, joita ei he eikä heidän isänsä tunne, ja lähetän miekan heidän peräänsä, siihenasti että minä heidät kaikki lopetan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Näin sanoo Herra Zebaot: tutkikaat tätä; toimittakaat teillenne itkeväisiä vaimoja, että he tulisivat; ja lähettäkäät niiden perään, jotka taitavat ovat, että he tulisivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Ja kiiruhtaisivat meitä valittamaan, että meidän silmämme kyyneleitä vuodattaisivat, ja meidän silmäripsemme vettä tiukkuisivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Että valitus kuuluis Zionissa (näin:) voi kuinka me olemme näin hävitetyt! me olemme peräti häväistyt, sillä meidän täytyy maalta paeta, että meidän asuinsiamme ovat kukistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Kuulkaa siis, te vaimot, Herran sanaa, ja käsittäkäät korviinne hänen suunsa puhe; antakaat teidän tyttärenne itkeä, ja opettakaan toinen toistansa valittamaan, (näin:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Kuolema on tullut meidän akkunoistamme sisälle ja meidän huoneisiimme langennut, lapsia kaduilla tappamaan ja nuorukaisia kujilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Näin sanoo Herra: sano: ihmisten ruumiit pitää, niinkuin loka maan päällä, kaatuman, ja niinkuin jalalliset jäävät elomiehen perään, jossa ei ole ylösottajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Näin sanoo Herra: älkään viisas kerskatko viisaudestansa, älkään väkevä kerskatko väkevyydestänsä, älkään myös rikas kerskatko rikkaudestansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Vaan joka tahtoo kerskata, niin kerskatkaan siitä, että hän tietää ja tuntee minun, että minä olen Herra, joka teen laupiuden, oikeuden ja vanhurskauden maan päällä; sillä se minulle kelpaa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Katso, se aika tulee, sanoo Herra, että minä rankaisen kaikki ympärileikatut ympärileikkaamattomain kanssa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egyptin, Juudan, Edomin, Ammonin lapset, ja Moabin ja kaikki, jotka maan äärissä korvessa asuvat; sillä kaikilla pakanoilla on ympärileikkaamatoin esinahka, mutta koko Israelin huoneella on ympärileikkaamatoin sydän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Kuulkaat, mitä Herra teille sanoo, te Israelin huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Näitä sanoo Herra: ei teidän pidä oppiman pakanain tapaa, eikä teidän pidä taivaan merkkejä pelkäämän; sillä pakanat niitä pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Sillä pakanain asetukset ei ole muu kuin turhuus; sillä he hakkaavat puun metsästä, ja työmies valmistaa sen kirveellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Ja kaunistaa sen hopialla ja kullalla, ja kiinnittää sen nauloilla ja vasaralla, ettei se järky.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Ne ovat tehdyt niinkuin vahvat palmupuut, vaan ei he taida puhua; ja heitä täytyy myös kantaa, sillä ei he taida käydä; sentähden ei teidän pidä niitä pelkäämän, sillä ei ne taida pahaa eikä hyvää tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Mutta Herra, ei yksikään ole sinun vertaises; sinä olet suuri, ja sinun nimes on suuri; jonka sinä töilläs taidat osoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kenenkä ei pitäisi sinua pelkäämän, sinä pakanain kuningas? Sinua pitää kuultaman; sillä ei kaikkein pakanain viisasten seassa eikä yhdessäkään valtakunnassa ole sinun vertaistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'He ovat kaikki tyhmät ja taitamattomat; sillä puu osoittaa turhuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Taottu hopia tuodaan Tarsiksesta ja kulta Uphasta, valmistettu työmiehiltä ja hopiasepiltä; he puetetaan sinisillä villoilla ja purpuralla, jotka kaikki ovat taitavain työt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mutta Herra on totinen Jumala, elävä Jumala ja ijankaikkinen kuningas; hänen vihansa edessä vapisee maa, ja pakanat ei taida kärsiä hänen uhkaustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Niin sanokaat siis heille näin: jumalat, jotka ei taivasta eikä maata tehneet ole, kadotkaan maasta ja taivaan alta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Mutta hän on tehnyt maan voimallansa, ja vahvistanut maan piirin viisaudellansa, on myös levittänyt taivaan ymmärryksellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Koska hän jylistää, silloin on paljo vettä taivaan alla, ja vetää ylös udun maan ääristä; hän tekee pitkäisen leimauksen sateen kanssa, ja antaa tuulen tulla kammioistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Kaikki ihmiset ovat tyhmät taidossansa, ja kaikki hopiasepät ovat häpiässä kuvinensa; sillä heidän kuvansa ovat petos, ja ei niissä ole henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Se on kaikki turha ja petollinen työ; heidän pitää hukkuman, kuin heitä etsiskellään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Mutta Jakobin osa ei ole senkaltainen; vaan hän on se, joka kaikki luonut on, ja Israel on hänen perintönsä vitsa: Herra Zebaot on hänen nimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Ota sinun kauppas pois maasta, joka asut vahvassa kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Sillä näin sanoo Herra: katso, minä heitän lingolla pois maan asuvaiset tällä erällä, ja vaivaan niin heitä, että heidän pitää sen tunteman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Voi minun murheeni ja sydämeni suru! vaan minä luulen, että se on minun vaivani, jonka minun pitää kärsimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Minun majani on hajoitettu, ja kaikki minun nuorani ovat katkenneet; minun lapseni ovat pois menneet minun tyköäni, eikä yhtään enään ole, eikä ole, joka rakentaa minun majani jälleen, ja ei kenkään pane ylös minun telttaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Sillä paimenet ovat tyhmäksi tulleet, eikä kysy Herraa; sentähden ei he ymmärrä, vaan kaikki heidän laumansa on hajoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Katso, sanoma tulee ja suuri vavistus pohjan maalta, saattamaan Juudan kaupungit kylmille ja lohikärmeiden asuinsiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Minä tiedän, Herra, ettei ihmisen tie ole hänen voimassansa, eikä yhdenkään miehen vallassa kuinka hän vaeltais ja käymisensä ojentais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Kurita Herra minua, mutta kuitenkin kohtuudella, ja ei sinun julmuudessas, ettes minua peräti hukuttaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Mutta vuodata vihas pakanain päälle, jotka ei sinua tunne, ja niiden sukuin päälle, jotka ei sinun nimeäs avuksi huuda; sillä he ovat syöneet ja nielleet Jakobin, he ovat tehneet hänen kanssansa lopun, ja hänen asuinsiansa hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Tämä on se sana, joka tapahtui Herralta Jeremialle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Kuulkaat näitä liiton sanoja, sanoaksemme niitä Juudalaisille ja Jerusalemin asuvaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Ja sano heille: näin sanoo Herra, Israelin Jumala: kirottu olkoon se, joka ei tottele näitä liiton sanoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Jotka minä sinä päivänä teidän isillenne käskin, jona minä johdatin heitä Egyptin maalta, rautapätsistä, ja sanoin: kuulkaat minun ääntäni, ja tehkäät niinkuin minä teidän käskenyt olen, niin teidän pitää minun kansani oleman, ja minä olen teidän Jumalanne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Että minä vahvistaisin sen valan, jonka minä teidän isillenne vannonut olen, antaakseni heille maan, joka rieskaa ja hunajaa vuotaa, niinkuin se tänäpänä on. Minä vastasin ja sanoin: Amen, Herra!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Ja Herra sanoi minulle: saarnaa kaikki nämät sanat Juudan kaupungeissa ja Jerusalemin kaduilla, ja sano: kuulkaat näitä liiton sanoja, ja tehkäät niiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Sillä minä olen kaikella ahkeruudella todistanut teidän isillenne siitä päivästä, jona minä heitä johdatin Egyptin maalta, niin tähän päivään asti, minä nousin varhain, todistin ja sanoin: kuulkaat minun ääntäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Mutta ei he kuulleet, eikä kallistaneet korviansa, vaan kukin meni oman pahan sydämensä tahdon jälkeen; sentähden annan minä myös kaikki nämät liiton sanat tulla heidän päällensä, jonka minä käskin pitää, ja ei he sitä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Herra sanoi minulle: minä kyllä tiedän, kuinka Juudan miehet ja Jerusalemin asuvaiset sitovat itsensä yhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'He kääntävät itsensä entisten isäinsä synteihin, jotka ei minun sanojani kuulleet, mutta seurasivat muita jumalia, ja palvelivat niitä; Israelin ja Juudan huone ovat myös rikkoneet joka paikassa minun liittoni, jonka minä heidän isäinsä kanssa tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Sentähden näin sanoo Herra; katso, minä saatan onnettomuuden heidän päällensä, jota ei heidän pidä saaman välttää; ja kuin he minua huutavat, niin en minä kuule heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Anna siis silloin Juudan kaupungit ja Jerusalemin asuvaiset mennä ja huutaa niitä jumalia, joille he suitsuttaneet ovat; vaan ei he taida heitä auttaa heidän hätänsä aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Sillä niin monta kuin sinulla, Juuda, kaupunkia on, niin monta sinulla jumalaakin on; ja niin monta kuin katua on Jerusalemissa, niin monta häpiällistä alttaria olette te rakentaneet, suisuttaaksenne Baalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Älä siis rukoile tämän kansan edestä, älä myös huuda eli rukoile tämän kansan tähden; sillä en minä kuule heitä, kuin he minua huutavat hädässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Mitä on minun ystävälläni toimittamista minun huoneessani? He tekevät kaikkinaista koiruutta, ja luulevat pyhän lihan sen heiltänsä pois ottavan; ja koska sinä pahoin teet, niin sinä iloitset siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Herra kutsui sinun nimes viheriäiseksi, kauniiksi, hedelmälliseksi öljypuuksi; mutta nyt on hän suurella murhan äänellä sytyttänyt tulen ympärille, niin että sen oksat pitää hävitetyksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Sillä Herra Zebaot, joka sinun on istuttanut, uhkasi sinulle pahaa, Israelin huoneen ja Juudan huoneen pahuuden tähden, jota he tekevät, ja vihoittavat minun suitsuttaissansa Baalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Herra on minulle sen ilmoittanut, niin että minä sen tiedän; silloin sinä osoitit minulle mitä he aikoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Ja minä olen niinkuin karitsa ja niinkuin härkä, joka viedään teurastettaa, ja en minä tietänyt, että he olivat pitäneet neuvoa minua vastaan, (ja sanoneet:) turmelkaamme puu hedelminensä, ja temmatkaamme häntä ylös juurinensa eläväin maasta, ettei hänen nimeänsä ikänä enää muistettaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mutta sinä Herra Zebaot, sinä oikia tuomari, sinä joka tutkistelet munaskuut ja sydämen, anna minun nähdä sinun kostos heidän päällensä; sillä minä olen asiani antanut sinun haltuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Sentähden sanoo Herra näin Anatotin miehiä vastaan, jotka sinun henkeäs väijyvät ja sanovat: älä ennusta meille Herran nimeen, jolles muutoin tahdo kuolla meidän käsissämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Sentähden näin sanoo Herra Zebaot: katso, minä etsin heitä kostolla, nuoret miehet pitää heistä miekalla tapettaman, heidän poikansa ja tyttärensä pitää nälässä kuoleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Niin ettei heistä pidä mitään jäämän; sillä minä saatan Anatotin miehille onnettomuuden sinä vuonna, kuin heitä kostolla pitää etsittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Herra, jos minä vielä kävisin sinun kanssas oikeudelle, niin sinä kuitenkin löydetään hurskaaksi; kuitenkin puhun minä sinun kanssas oikeudesta. Miksi käy jumalattomille niin hyvin, ja suurilla ylönannetuilla on kaikkinaista kyllä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Sinä istutat heitä juurtumaan, kasvamaan ja kantamaan hedelmän; sinä olet läsnä heidän suussansa, vaan kaukana heidän sydämestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mutta minun sinä, Herra, tunnet, näet minun ja tutkistelet sydämeni sinun edessäs; tempaa heitä niinkuin lampaita teuraaksi tehtää, ja pyhitä heitä tappamisen päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Kuinka kauvan siis pitää maan niin surkiasti oleman, ja ruohon kaikissa paikoissa kedolla kuivuman? asuvaisten pahuuden tähden, että sekä eläimet että linnut katoovat; sillä he sanovat: hän kyllä vähän tietää, kuinka meille tästälähin käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Jos ne, jotka jalkaisin käyvät, väsyttävät teidät, kuinka siis silloin käy, kuin sinun täytyy hevosmiesten kanssa juosta? Ja jos sinä etsit niissä maakunnissa suruttomuutta, joissa rauha on, mitä sinulle on tapahtuva sen ylpiän Jordanin tykönä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Sillä sinun veljes ja isäs huone ovat myös sinua vastaan petolliset ja pitittävät sinua täydellä kurkulla; sentähden älä usko heitä, jos he vielä ystävällisesti sinun kanssas puhuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Minun täytyy antaa minun huoneeni ylön, ja paeta minun perintöäni, ja antaa minun rakkaan sieluni vihollisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Minun perintöni on tullut minulle niinkuin jalopeura metsässä, ja räyskyy minua vastaan, sentähden vihaan minä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Minun perintöni on niinkuin kirjava lintu, jonka ympärille linnut heitänsä kokoovat; nouskaat ja kootkaat teitänne kaikki eläimet kedolla, tulkaat ja syökäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Monet paimenet ovat hävittäneet minun viinamäkeni, ja sotkuneet minun sarkani; he ovat tehneet minun kauniin sarkani korveksi ja autioksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, '(Minä näen jo kaiketi) kuinka surkiasti hän on hävitetty, että koko maa on kylmillä; mutta ei yksikään sitä pannut sydämeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Sillä hävittäjät tulevat kaikille kukkuloille korvessa, ja Herran miekka kuluttaa yhdestä maan äärestä niin toiseen, ja ei yhdelläkään lihalla pidä rauhaa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'He kylvävät nisuja, mutta heidän pitää ohdakkeita niittämän, he tekevät itsellensä paljon vaivaa, mutta ei heidän pidä sitä nautitseman, eikä iloitseman vuoden tulostansa, Herran julman vihan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Näin sanoo Herra kaikkia minun pahoja kyläni miehiä vastaan, jotka tarttuvat minun perintööni, jonka minä kansalleni Israelille jakanut olen: katso, minä revin heitä ylös heidän maastansa, ja otan ulos Juudan huoneen juuri heidän keskeltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Ja pitää tapahtuman, että kuin minä olen heidän ottanut ulos, armahdan minä jälleen heitä, ja annan kullekin oman perintönsä ja maansa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Ja se on tapahtuva, jos he minun kansastani kaiketi oppivat vannomaan minun nimeni kautta (niin totta kuin Herra elää), niinkuin he ennen minun kansani opettivat vannomaan Baalin kautta: niin pitää heitä myös rakennettaman minun kansani seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Mutta jollei he kuule, niin minä totisesti revin ylös sen kansan, ja surmaan sen, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Näin sanoo Herra minulle: mene ja osta itselles liinainen vyö, ja vyötä sillä kupees, ja älä sitä kasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Ja minä ostin vyön Herran käskyn jälkeen, ja sidoin sen ympäri minun kupeitani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Niin tapahtui Herran sana toisen kerran minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Ota vyö, jonka ostanut ja ympäri kupeitas sitonut olet; nouse ja mene Phratiin ja kätke se kiviraunioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Minä menin ja kätkin sen Phratin tykö, niinkuin Herra minulle käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Mutta pitkän ajan perästä tapahtui, että Herra sanoi minulle: nouse ja mene Phratiin, ja ota se vyö jälleen, jonka minä käskin sinun sinne kätkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Minä menin Phratiin, ja kaivoin sen ylös, ja otin vyön siitä paikasta, johon minä pannut olin; ja katso, vyö oli mädäntynyt, niin ettei se mitään enään kelvannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Niin tapahtui Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Näin sanoo Herra: niin minä myös hävitän Juudan ja Jerusalemin suuren ylpeyden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Sen pahan kansan, joka ei minun sanaani kuulla tahdo, mutta menee sydämensä tahdon jälkeen, ja seuraa muita jumalia, palvellaksensa ja kumartaaksensa niitä: hänen pitää tuleman niinkuin tämä vyö, joka ei enään kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Sillä niinkuin mies sitoo vyön ympäri kupeitansa, niin ikänä olen minä, sanoo Herra, minun ympärilleni vyöttänyt koko Israelin huoneen ja koko Juudan huoneen olemaan minulleni kansaksi, nimeksi, ylistykseksi ja kunniaksi; mutta ei he tahtoneet kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Niin sano nyt heille tämä sana: näin sanoo Herra, Israelin Jumala: kaikki leilit pitää viinalla täytettämän. Niin pitää heidän sanoman sinulle: kuka ei sitä meistä hyvin tiedä, että kaikki leilit pitää viinalla täytettämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Niin sano heille: näin sanoo Herra: katso, minä täytän kaikki ne, jotka tässä maassa asuvat, kuninkaat, jotka Davidin istuimella istuvat, ja papit ja prophetat, ja kaikki Jerusalemin asuvaiset, niin että he juopuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Ja hajoitan heitä toiset toisistansa, isät lapsinensa, sanoo Herra, en minä armahda eli säästä, enkä ole laupias heidän kadotuksessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Niin kuulkaat nyt ja ottakaat vaari ja älkäät paisuko; sillä Herra on sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Antakaat Herralle teidän Jumalallenne kunnia, ennenkuin hän antaa pimeyden tulla, ja ennenkuin teidän jalkanne loukkaantuu pimiöihin vuoriin, niin että te odotatte valkeutta, ja hänen pitää sen tekemän kuoleman varjoksi ja pimeydeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Mutta jollette näitä kuule, niin on kuitenkin minun sieluni salaisesti itkevä senkaltaista ylpeyttä; minun silmäni on katkerasti ja yltäkyllin vuodattava kyyneleitä, että Herran lauma vangiksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Sano kuninkaalle ja kuningattarelle: nöyryyttäkäät teitänne ja istukaat maahan; sillä kunnian kruunu on teidän päästänne pudonnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Kaupungit etelänpuolessa ovat suljetut, ja ei ole yhtään, joka heitä avaa; koko Juuda on viety pois, se on peräti viety pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Nostakaat silmänne ja katsokaat, kuinka he pohjoisesta tulevat; kussa lauma nyt on, joka sinun haltuus annettu oli, sinun jalo laumas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Mitäs tahdot sanoa, kuin hän näin on kostolla etsivä sinua? sillä sinä olet niin totuttanut heidät sinuas vastaan, että he ruhtinaat ja päämiehet olla tahtovat; mitämaks, sinulle pitää tuska tuleman, niinkuin vaimolle lapsen synnyttämisessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Ja jos sinä sydämessäs sanoa tahtoisit: minkätähden minulle nämät tapahtuvat? Sinun moninaisen pahuutes tähden on sinun saumas ratkenneet, ja sääres väkisin paljastetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Taitaako musta kansa muuttaa nahkansa eli pardi pilkkunsa? niin te myös taidatte tehdä jotain hyvää, että te pahaan tottuneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Sentähden hajoitan minä heidät niinkuin akanat, jotka tuuli korpeen lennättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Se pitää oleman sinun palkkas ja osas, jonka minä sinulle jakanut olen, sanoo Herra, ettäs minun unhotit ja luotit itses valheisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Sentähden kirvotan minä myös paljon sinun saumastas, että sinun häpys nähtämän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Sillä minä olen nähnyt sinun huoruutes, sinun haureutes, sinun häpeemättömän salavuoteutes ja sinun kauhiutes, sekä kukkuloilla että kedoilla. Voi sinuas Jerusalem! koskas siis joskus tahdot puhdistaa itses?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Tämä on se sana, jonka Herra sanoi Jeremialle, kalliista ajasta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Juuda murehtii, ja hänen porttinsa ovat hyljätyt, maassa ollaan surullisesti, ja Jerusalemissa on valitus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Ylimmäiset lähettävät alamaisensa veden perään, mutta kuin he tulevat kaivolle, niin ei he löydä vettä, ja kantavat niin astiansa kotia tyhjänä jälleen; he käyvät surullisina ja häpeevät, ja peittävät päänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Että maa pakahteli, ettei sada maan päälle, peltomiehet käyvät suruissansa ja peittävät päänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Sillä naaraspeurat, jotka kedolla poikivat, hylkäävät vasikkansa, ettei ruoho kasva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Ja metsä-aasit seisovat mäillä ja haistelevat tuulta niinkuin lohikärmeet, ja heidän silmänsä nääntyvät, ettei heinä kasva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Voi Herra, meidän pahat tekomme ovat sen kyllä ansainneet, mutta auta kuitenkin sinun nimes tähden; sillä meidän kovakorvaisuutemme on suuri, kuin me olemme sinua vastaan syntiä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Sinä olet Israelin turva ja auttaja hädässä; miksis olet niinkuin muukalainen maassa, ja niinkuin vieras, joka siihen ainoasti yötyy?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Miksis olet niinkuin mies, joka on pelkuri, ja niinkuin väkevä, joka ei auttaa taida? Sinä olet kuitenkin meidän seassamme, Herra, ja me nimitetään sinun nimelläs; älä meitä hylkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Näin sanoo Herra tästä kansasta: he juoksevat mielellänsä sinne ja tänne, eikä pysy alallansa; sentähden ei he kelpaa Herralle, vaan hän muistaa kyllä heidän pahuutensa, ja tahtoo etsiä heidän syntejänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Ja Herra sanoi minulle: ei sinun pidä rukoileman tämän kansan edestä heidän hyväksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Sillä jos he paastoavat, en minä sittekään kuule heidän rukoustansa, ja jos he polttouhria ja ruokauhria uhraavat, niin ei ne minulle kelpaa; vaan minä lopetan heidät miekalla, nälällä ja rutolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Niin minä sanoin: oi Herra, Herra, katso, prophetat sanovat heille: ei teidän pidä miekkaa näkemän, eikä saaman kallista aikaa, mutta minä annan teille hyvän rauhan tässä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Ja Herra sanoi minulle: prophetat ennustavat valhetta minun nimeeni, en ole minä heitä lähettänyt enkä käskenyt, elikkä puhunut heidän kanssansa; he saarnaavat teille vääriä näkyjä, noituutta, turhuutta ja sydämensä petosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Sentähden näin sanoo Herra niistä prophetaista, jotka minun nimeeni ennustavat: vaikka en minä heitä ole lähettänyt, ja kuitenkin he sanovat: ei miekan ja kalliin ajan pidä tähän maahan tuleman; ne prophetat pitää kuoleman miekalla ja nälällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Ja kansa, jolle he ennustavat, pitää nälästä ja miekasta siellä ja täällä Jerusalemin kaduilla makaavan, ja ei heillä pidä yhtään oleman, joka heitä hautaa, heitä ja heidän vaimojansa, poikiansa ja tyttäriänsä; ja minä tahdon kaataa heidän pahuutensa heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Ja sinun pitää sanoman heille tämän sanan: minun silmäni vuotavat kyyneleitä yli yötä ja päivää, ja ei lakkaa; sillä neitsy, minun kansani tytär, on hirmuisesti vaivattu ja surkiasti lyöty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Jos minä menen kedolle, niin katso, siellä makaavat miekalla lyödyt; jos minä tulen kaupunkiin, niin katso, siellä makaavat nälästä nääntyneet; sillä prophetat ja papit pitää myös menemän pois siihen maahan, jota ei he tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Oletkos Juudan peräti hyljännyt, eli ilvottaako sielus Zionia? miksi sinä olet niin meitä lyönyt, ettei kenkään parantaa taida? Me toivoimme rauhaa, mutta ei tule mitään hyvää: parantamisen aikaa, ja katso, tässä on vielä nyt enempi vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Herra, me tunnemme jumalattoman menomme, ja isäimme pahat teot; sillä me olemme syntiä tehneet sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Mutta sinun nimes tähden älä anna meitä häväistyksi tulla, älä kunnias istuinta anna pilkatuksi tulla; muista siis, ja älä anna liittos meidän kanssamme lakata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Ei ole kuitenkaan pakanain epäjumalain seassa, joka sateen antaa taitaa, ei taida taivas myöskään sataa; sinä ainoa olet Herra meidän Jumalamme, jonka päälle me toivomme, sillä sinä olet kaikki nämät tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Ja Herra sanoi minulle: Jos Moses ja Samuel seisoisivat minun edessäni, niin ei sydämeni olisi sittenkään sen kansan puoleen; aja heitä pois minun edestäni, ja anna heidän mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Ja jos he sinulle sanovat: kuhunka meidän pitää menemän? niin sano heille: näin sanoo Herra: jotka (ovat aiotut) kuolemaan, ne (menkään) kuolemaan; jotka miekkaan, ne miekkaan; jotka nälkään, ne nälkään; ja jotka vankiuteen, ne vankiuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Sillä minä tahdon määrätä heille neljä kuritusta, sanoo Herra: miekan tappamaan, koirat repimään, taivaan linnut ja pedot syömään ja hukuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Ja minä tahdon ajaa heitä sinne ja tänne jokaiseen valtakuntaan maan päällä, Manassen, Hiskian Juudan kuninkaan pojan tähden, niiden tähden, mitkä hän teki Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Sillä kuka tahtoo sinua armahtaa, Jerusalem? kuka sinua surkuttelee? kuka pitää menemän ja saattaman rauhaa sinulle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Sinä olet minun hyljännyt, sanoo Herra, ja olet minusta luopunut; sentähden olen minä ojentanut käteni sinua vastaan, hukuttaakseni sinua; minä suutun jo armahtamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Minä tahdon viskata heitä viskimellä ulos maakunnan porteista; ja minun kansani, joka ei tahdo kääntyä menostansa, ne tahdon minä tehdä kaikki isättömiksi ja kadottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Minulla pitää enempi leskiä oleman heidän seassansa, kuin santaa meressä; minä tahdon antaa tulla nuoren hävittäjän äitiä vastaan, julkisen hävittäjän, ja annan äkisti ja tapaturmaisesti langeta kaupungin päälle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Niin että se, jolla seitsemän lasta on, pitää yksinäiseksi tuleman, ja sydämestänsä huokaaman; sillä hänen aurinkonsa pitää varhain päivällä laskeman, että hänen pitää häpiään tuleman ja häpeemän; ja ne kuin jäävät, tahdon minä antaa miekan alle heidän vihollisillensa, sanoo Herra.\"');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Voi minua, äitini, ettäs minun synnytit riiteliäksi ja vastustajaksi koko maalle! En minä ole korkoa ottanut, eikä he ole minua kasvulle antaneet, kuitenkin kaikki minulle kiroilevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Herra sanoi: sinun jääneilles pitää vielä hyvin käymän; minä tahdon joutua avukses hädän ja ahdistuksen aikana vihollista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Eikö rauta taitane särkeä sitä rautaa ja vaskea, joka pohjoisesta tulee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Vaan minä tahdon (ennen) antaa sinun kalus ja tavaras raatelukseksi, ilman maksoa; ja se on kaikkein sinun synteis tähden kaikissa sinun rajoissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Ja minä tahdon antaa sinun vietää vihollistes kanssa siihen maahan, jota et sinä tunne; sillä tuli on minun vihassani syttynyt ja pitää teidän päällänne palaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Sinä, Herra, sen tiedät, muista minua ja pidä minusta suru, ja kosta minun vihollisilleni minun puolestani, älä viivytä vihaas, ota minua vastaan; sillä sinä tiedät, että minä sinun tähtes häväistään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Sinun sanas ovat saavutetut, ja minä olen ne käsittänyt, ja sinun sanas on minulle ilo ja sydämen lohdutus; ja minä olen nimitetty sinun nimes jälkeen, Herra Jumala Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'En minä anna itsiäni pilkkaajain pariin, enkä iloitse (heidän kanssansa), vaan olen yksinänsä sinun kätes pelvon tähden: sillä sinä vihastut raskaasti minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Miksi minun ahdistukseni kestää niin kauvan, ja minun haavani ovat aivan pahat, niin ettei niitä kukaan parantaa taida? Sinä olet minulle niin kuin lähde, joka ei enään vuotaa tahdo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Sentähden sanoo Herra näin: jos sinä käännyt (minun tyköni), niin minä tahdon kääntää sinun, ja sinun pitää seisoman minun edessäni; ja jos sinä eroitat hyvän pahasta, niin sinun pitää oleman niinkuin minun suuni. Heidän pitää kääntymän sinun tykös, ja et sinä käänny heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Sillä minä teen sinut vahvaksi vaskiseksi muuriksi tätä kansaa vastaan, ja he sotivat sinua vastaan, vaan ei heidän pidä sinua voittaman; sillä minä olen sinun tykönäs auttamassa sinua ja vapahtamassa sinua, sanoo Herra;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Ja tahdon sinun vapahtaa ilkiäin käsistä, ja pelastaa sinua julmain vallasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Ei sinun pidä ottaman itselles vaimoa, eikä siittämän poikia eli tyttäriä tässä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Sillä näin sanoo Herra niistä pojista ja tyttäristä, jotka tässä paikassa syntyvät, ja äideistä, jotka heitä synnyttävät, ja heidän isistänsä, jotka heitä tässä maassa siittävät:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Heidän pitää kuoleman sairaudessansa, ja ei heitä pidä itkettämän eli haudattaman, vaan heidän pitää loaksi kedolle tuleman; ja heidän pitää vielä sitte miekalla ja nälällä hukkuman, ja heidän ruumiinsa pitää linnuille taivaan alla ja eläimille maassa ruaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Sillä näin sanoo Herra: ei sinun pidä menemän murhehuoneesen, eikä menemän itkemään eli surkuttelemaan heitä; sillä minä olen ottanut pois minun rauhani tältä kansalta, sanoo Herra, ja minun armoni ja laupiuteni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Että sekä suuret että pienet pitää tässä maassa kuoleman, ja ei haudatuksi tuleman, ja ei yhdenkään pidä itkemän eli repimän itsiänsä, eikä ajeleman hiuksiansa heidän tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Ja ei myös pidä (leipää) jaettaman murheessa, että heitä lohdutettaisiin kuolleen tähden, eikä pidä annettaman juoda lohdutusmaljasta isänsä tähden ja äitinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Ja ei pidä sinun menemän pitohuoneesen, istumaan heidän viereensä, syömään ja juomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Sillä näin sanoo Herra Zebaot, Israelin Jumala: katso, minä tahdon ottaa pois tästä siasta, teidän silmäinne edestä ja teidän eläissänne, ilon ja riemun äänen, yljän äänen ja morsiamen äänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Ja kuin sinä nämät kaikki tälle kansalle sanonut olet, ja he sanovat sinulle: miksi Herra uhkaa meille kaikkea tätä suurta onnettomuutta? ja mikä on meidän pahatekomme ja syntimme, jolla me olemme rikkoneet Herraa, meidän Jumalaamme, vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Niin sinun pitää sanoman heille: että teidän isänne, sanoo Herra, ovat hyljänneet minun, ja seuranneet muita jumalia, palvelleet niitä ja kumartaneet niitä; mutta minun ovat he hyljänneet, ja ei pitäneet minun lakiani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Ja te teette vielä pahemmin kuin teidän isänne; sillä katso, kukin elää oman pahan sydämensä sisun jälkeen, eikä yksikään tottele minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Sentähden minä tahdon ajaa teidät pois tästä maasta siihen maahan, josta ette te eikä teidän isänne mitään tiedä, siellä saatte te palvella muita jumalia yli päivää ja yötä, ja en minä tahdo siellä armoa näyttää teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Sentähden katso, se aika tulee, sanoo Herra, ettei sitte pidä enään sanottaman: niin totta kuin Herra elää, joka Israelin lapset Egyptin maalta on johdattanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Vaan, niin totta kuin Herra elää, joka Israelin lapset on johdattanut pohjan maasta ja kaikista maista, joihin hän heitä ajanut oli; sillä minä tahdon antaa heidän tulla jälleen heidän maahansa, jonka minä heidän isillensä antanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Katso, minä lähetän monta kalamiestä, sanoo Herra, heitä onkimaan; ja sitte lähetän minä monta metsämiestä, heitä käsittämään kaikilla vuorilla, kaikilla kukkuloilla ja kaikissa kiviraunioissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Sillä minun silmäni näkee kaikki heidän tiensä, ja ei ne ole peitetyt minun edessäni; ja heidän pahatekonsa on minun silmäini edessä salaamatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Ensisti pitää minun kaksinkertaisesti maksaman heidän pahat tekonsa ja syntinsä, että he ovat saastuttaneet minun maani kauhistustensa raadoilla, ja kauhistuksellansa täyttivät he minun perintöni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Herra, sinä olet väkevyyteni ja voimani, ja turvani hädässä; pakanat tulevat sinun tykös maailman ääristä ja sanovat: meidän isämme ovat tosin pitäneet vääriä ja turhia jumalia, jotka ei mitään auttaa taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Kuinka taitaa ihminen tehdä hänellensä jumalia, jotka ei kuitenkaan jumalia olekaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Sentähden katso, minä tahdon opettaa heitä tällä haavalla, ja tehdä heille minun käteni ja valtani tiettäväksi; ja heidän pitää ymmärtämän, että minun nimeni on Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Juudan synti on raudalla ja kovalla timantilla kirjoitettu, ja heidän sydämensä tauluihin kaivettu, ja teidän alttarinne sarviin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Että heidän lapsensa mieleensä johdattaisivat alttarit ja metsistöt viheriäisten puiden tykönä korkeilla vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Mutta minä olen antava sinun korkeutes ryöviöksi, sekä vuorilla että kedoilla, sekä riistas, että kaiken sinun tavaras, niiden syntein tähden, jotka kaikissa sinun maas äärissä on tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Ja sinun pitää tuleman ajetuksi pois sinun perinnöstäs, jonka minä sinulle antanut olen; ja minä tahdon sinun tehdä vihollisten orjaksi siinä maassa, jota et sinä tunne; sillä te olette sytyttäneet vihani tulen, joka ijankaikkisesti palava on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Näin sanoo Herra: kirottu olkoon se mies, joka luottaa ihmiseen, ja panee lihan itsellensä käsivarreksi, ja jonka sydän luopuu pois Herrasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Hänen pitää tuleman niinkuin kanerva korvessa, ja ei pidä saaman nähdä tulevaista lohdutusta; ja hänen pitää asuman kuivuudessa korvessa, hedelmättömässä ja autiossa erämaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Mutta se mies on siunattu, joka luottaa Herraan; ja Herra on hänen turvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Hän on niinkuin se puu, joka veden reunalle on istutettu ja ojan viereen juurtunut; sillä jos vielä palavuus tulee, niin ei hän kuitenkaan pelkää, vaan sen lehdet pysyvät viheriäisinä, eikä murehdi, kuin kuiva vuosi tulee, mutta kantaa hedelmän ilman lakkaamatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Sydän on häijy ja pahanilkinen kappale ylitse kaikkein; kuka taitaa sitä tutkia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Minä Herra tahdon tutkia sydämen ja koetella munaskuut ja annan kullekin hänen töittensä jälkeen ja hänen töittensä hedelmän jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Sillä niinkuin lintu hautoo ja ei kuori, niin on myös se, joka väärin kalua kokoo; sillä hänen pitää jättämän sen kesken aikaansa, ja viimeiseltä tyhjäksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Mutta meidän pyhyytemme sia, (Jumalan) kunnian istuin, on aina lujana pysynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Sinä Herra olet Israelin toivo; kaikki, jotka sinun hylkäävät, pitää häpiään tuleman; ne minusta luopuneet pitää maahan kirjoitettaman; sillä he hylkäävät Herran, joka on elävä vesilähde.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Paranna minua, Herra, niin minä paranen; auta sinä minua, niin minä olen autettu; sillä sinä olet minun kerskaukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Katso, he sanovat minulle: kussa siis on Herran sana? annas nyt tulla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Mutta en minä ole paennut sinusta, minun paimeneni, niin en minä ole myös toivottanut heille surkiaa päivää, sen sinä tiedät; mitä minä saarnannut olen, se on oikea sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Älä ole minulle hämmästykseksi; sinä olet minun turvani hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Anna heidän häpiään tulla, jotka minua vainoovat, ja älä anna minun häpiään tulla; anna heidän peljästyä, ja älä anna minun peljästyä; anna onnetoin päivä heille tulla, ja lyö rikki heitä kaksinkertaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Näin sanoi Herra minulle: mene ja seiso kansan portissa, josta Juudan kuninkaat käyvät ulos ja sisälle, ja kaikissa Jerusalemin porteissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Ja sano heille: kuulkaat Herran sanaa, te Juudan kuninkaat, ja kaikki Juudan ja Jerusalemin asuvaiset, jotka tästä portista sisälle käytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Näin sanoo Herra: kavahtakaat teitänne ja älkäät sabbatina mitään kuormaa kantako, älkäät myös viekö Jerusalemin porttein lävitse;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Ja älkäät viekö yhtään taakkaa sabbatina ulos teidän huoneistanne, ja älkäät tehkö mitään työtä; vaan pyhittäkäät sabbatin päivä, niinkuin minä teidän isillenne käskenyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Mutta ei he kuule eikä kallista korviansa, vaan tulevat kankiaksi, ettei heidän pitäisi kuuleman, eikä salliman heitänsä neuvottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Ja pitää tapahtuman, että, jos te uskollisesti kuulette minua, sanoo Herra, niin ettette yhtään kuormaa kanna sabbatin päivänä tämän kaupungin portin lävitse; vaan pyhitätte sabbatin päivän, niin ettette myös työtä tee sinä päivänä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Niin pitää myös tämän kaupungin portista käymän kuninkaat ja päämiehet ulos ja sisälle, jotka Davidin istuimella istuvat, ratsastavat ja vaeltavat sekä vaunuilla ja hevosilla he, ja heidän pääruhtinaansa, Juudan miehet ja Jerusalemin asuvaiset; ja tässä kaupungissa pitää ijankaikkisesti asuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Ja pitää tuleman Juudan kaupungeista ja niistä, jotka ympäri Jerusalemin ovat, ja Benjaminin maasta, laaksoista ja vuorilta, ja lounaasta päin, ne jotka pitää viemän edes polttouhrit, uhrit, ruokauhrit ja suitsutuksen, niin myös ne, jotka pitää viemän kiitosuhrit Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Mutta jollette minua kuule, niin että te pyhitätte sabbatin päivän, ja ettette yhtään taakkaa kanna Jerusalemin porteista sabbatin päivänä: niin minä sytytän tulen sen portteihin, joka Jerusalemin huoneet kuluttaman pitää, jota ei pidä sammutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Tämä on se sana, joka tapahtui Herralta Jeremialle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Nouse ja mene alas savenvalajan huoneesen; siellä tahdon minä sinun antaa kuulla minun sanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Ja minä menin alas savenvalajan huoneesen; ja katso, hän teki työtä pyöränsä päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Ja astia, jonka hän teki savesta, särkyi savenvalajan käsissä; niin hän teki taas toisen astian, niinkuin hänelle kelpasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Niin tapahtui Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Enkö minä myös taida niin tehdä teille, te Israelin huone, kuin tämä savenvalaja, sanoo Herra? Katso, niinkuin savi on savenvalajan kädessä, niin olette te myös minun kädessäni, Israelin huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Äkisti minä puhun kansaa ja valtakuntaa vastaan, kukistaakseni, hävittääkseni ja hukuttaakseni sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Mutta jos se kansa kääntää itsensä pahuudestansa, jota vastaan minä puhun, niin minäkin kadun sitä pahaa, jota minä ajattelin heille tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Ja minä puhun äkisti kansasta ja valtakunnasta, rakentaakseni ja istuttaakseni sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Mutta jos se tekee pahaa minun edessäni, niin ettei hän kuule minun ääntäni, niin minä kadun myös sitä hyvää, jota minä heille luvannut olin tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Niin sano nyt Juudan miehille ja Jerusalemin asuvaisille: näin sanoo Herra: katso, minä valmistan teille onnettomuuden, ja ajattelen jotakin teitä vastaan; sentähden kääntäköön kukin itsensä pahalta tieltänsä, ja parantakaat teidän menonne ja juonenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Mutta he sanoivat: ei se tapahdu; vaan me tahdomme vaeltaa meidän ajatustemme jälkeen, ja tehdä kukin pahan sydämensä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Sentähden, näin sanoo Herra: kysykäät pakanain seassa, kuka on joskus senkaltaista kuullut, että neitsy Israel niin kauhian työn tekee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Pitääkö kedon hylkäämän Libanonin lumen, yhden vahan tähden? Pitääkö juokseva vesi, vieraan kylmän veden tähden, siirrettämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Kuitenkin unohtaa minun kansani minun: he suitsuttavat jumalille, ja pahennuksen matkaan saattavat ilman lakkaamata, ja käyvät tallaamattomilla teillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Että heidän maansa pitää autioksi tuleman, heille ijäiseksi häpiäksi; niin että jokainen, joka vaeltaa ohitse, ihmettelee ja päätänsä pudistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Sillä minä tahdon niinkuin itätuulella hajoittaa heitä heidän vihollistensa edessä; minä tahdon näyttää heille selkäni, ja en kasvojani heidän kadotuksensa päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Mutta he sanoivat: tulkaat, ja käykäämme neuvoa pitämään Jeremiaa vastaan; sillä ei papit taida väärin mennä laissa, viisasten neuvo ei puutu, ja ei propheta taida väärin opettaa; tulkaat, lyökäämme häntä kielellä ja älkäämme totelko, mitä hän sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Herra, ota vaari minusta, ja kuule vihollisteni ääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Onko se oikein, että hyvä kostetaan pahalla? Sillä he ovat kaivaneet minun sielulleni kuopan; muista siis, kuinka minä olen seisonut sinun edessäs, ja puhunut heidän parastansa, ja käänsin sinun julmuutes heidän puolestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Rankaise siis heidän lapsiansa nälällä ja anna heidän miekalla langeta, että heidän vaimonsa jäisivät lapsettomiksi ja leskiksi, ja heidän miehensä lyötäisiin kuoliaaksi, ja nuoret miehet sodassa miekalla tapettaisiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Että huuto kuuluis heidän huoneistansa, ettäs niin äkisti olet antanut tulla sotaväen heidän päällensä; sillä he ovat kaivaneet kuopan minua käsittääksensä, ja ovat virittäneet paulan minun jalkaini eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Ja että sinä, Herra, tiedät kaikki heidän juonensa minua vastaan, että he tahtovat minua tappaa; niin älä anna anteeksi heidän pahaa tekoansa, ja älä anna heidän syntejänsä pyyhittynä olla sinun edessäs; he olkoon kukistettuna sinun edessäs, ja tee heidän kanssansa sinun vihas jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Näin sanoi Herra: mene ja osta savi-astia savenvalajalta, ja (ota kanssas muutamat) kansan vanhimmista ja pappein vanhimmista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Ja mene Benhinnomin laaksoon, joka on tiiliportin edessä, ja saarnaa siellä ne sanat, jotka minä sanon sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Ja sano: kuulkaat Herran sanaa, te Juudan kuninkaat ja Jerusalemin asuvaiset: näin sanoo Herra Zebaot, Israelin Jumala: katso, minä tahdon antaa kovan onnen tulla tälle paikalle, että jokainen, joka sen kuulee, pitää sen hänen korvissansa soiman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Että he ovat hyljänneet minun, ja antaneet tämän sian vieraalle (jumalalle) ja ovat suitsuttaneet siinä muille jumalille, joita ei he, eikä heidän isänsä eli Juudan kuninkaat tunteneet, ja ovat täyttäneet tämän sian viattomalla verellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Sillä he ovat rakentaneet korkeuksia Baalille, polttaaksensa lapsiansa tulessa Baalille polttouhriksi; jota en minä ole käskenyt eli siitä puhunut, eikä myös minun sydämeeni tullut ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Sentähden katso, se aika pitää tuleman, sanoo Herra, ettei tätä siaa pidä enään kutsuttaman Tophet, eli Benhinnomin laaksoksi, vaan Murhalaaksoksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Sillä minä tahdon hävittää Juudan ja Jerusalemin neuvon tässä siassa, ja tahdon antaa heidän langeta miekalla heidän vihollistensa edessä ja niiden käsiin, jotka seisovat heidän henkensä perään; ja tahdon antaa heidän ruumiinsa taivaan linnuille ja eläimille kedolla ruuaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Ja tahdon tehdä tämän kaupungin autioksi ja nauruksi, niin että kaikki, jotka käyvät tästä ohitse, pitää ihmettelemän ja viheltämän kaikkia hänen vaivojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Minä tahdon antaa heidän syödä poikainsa ja tytärtensä lihaa, ja heidän pitää syömän toinen toisensa lihaa siinä vaivassa ja ahdistuksessa, jolla heidän vihollisensa ja ne, jotka seisovat heidän henkensä perään, heitä ahdistaman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Ja sinun pitää rikkoman savi-astian, niiden miesten nähden, jotka ovat menneet sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Ja sano heille: näin sanoo Herra Zebaot: juuri niinkuin joku rikkoo savenvalajan astian, niin ettei se taida jälleen terveeksi tulla; niin tahdon minä myös rikki lyödä tämän kansan ja tämän kaupungin, ja pitää Tophetissa haudatuksi tuleman, sentähden ettei ole siaa hautaamiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Näin tahdon minä tehdä tälle sialle ja asuvaisille, sanoo Herra, että tämän kaupungin pitää tuleman niinkuin Tophet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Vielä sitte pitää Jerusalemin huoneet ja Juudan kuninkaan huoneet juuri niin saastaisiksi tuleman, kuin se paikka Tophet, kaikkein huonetten tähden, joissa he kattoin päällä kaikelle joukolle suitsuttaneet ja muille jumalille juomauhrin uhranneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Ja kuin Jeremia palasi Tophetista, johon Herra hänet lähettänyt oli ennustamaan, meni hän Herran huoneen pihaan ja sanoi kaikelle kansalle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Näin sanoo Herra Zebaot, Israelin Jumala: katso, minä annan tulla tämän kaupungin ja kaikkein hänen kaupunkeinsa päälle kaiken sen kovan onnen, jonka minä olen puhunut heitä vastaan; että he ovat uppiniskaiset, ja ei tahdo minun sanaani kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Mutta kun Pashur Immerin poika, pappi, joka oli ylimmäikseksi pantu Herran huoneessa, kuuli Jeremian ennustavan näitä sanoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Löi Pashur propheta Jeremiaa, ja heitti tämän vankiuteen, Benjaminin ylimmäisessä portissa, joka Herran huoneessa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Ja toisena päivänä otti Pashur Jeremian vankiudesta. Niin Jeremia sanoi hänelle: ei Herra kutsu sinun nimeäs Pashur, vaan Magor joka taholta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Sillä näin sanoo Herra: katso, minä annan sinun kaikkein sinun ystäväis kanssa pelkoon, ja heidän pitää kaatuman vihollistensa miekan kautta, ja sen pitää sinun silmäs näkemän; ja minä olen hylkäävä koko Juudan Babelin kuninkaan käteen, jonka pitää viemän heitä Babeliin ja tappaman miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Ja minä olen antava kaiken tämän kaupungin kalun, ynnä kaiken hänen työnsä kanssa, ja kaikki kalliit kappaleet, ja kaiken Juudan kuningasten tavaran, tahdon minä antaa heidän vihollistensa käteen, niin että heidän pitää heitä ryöstämän, ottaman pois ja viemän Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Ja sinä Pashur, sinun pitää kaiken perhees kanssa menemän vankiuteen, ja menemän Babeliin; siellä pitää sinun kuoleman ja haudattaman, sinä ynnä kaikkein sinun ystäväis kanssa, joille sinä valhetta ennustanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Herra, sinä olet minun yllyttänyt, ja minä olen yltynyt; sinä olet minulle juuri väkevä ollut, ja olet voittanut; mutta minä olen sentähden tullut syljetyksi joka päivä, että jokainen nauraa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Sillä sittekuin minä puhunut, huutanut ja saarnannut olen siitä tuskasta ja hävityksestä, on Herran sana tullut minulle pilkaksi ja nauruksi joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Niin minä sanoin: en minä tahdo enään ajatella hänen päällensä, enkä tahdo enään saarnata hänen nimeensä; mutta minun sydämessäni oli niinkuin polttavainen tuli, suljettu minun luissani, niin että minä suutuin kärsimästä, enkä enää voinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Sillä minä kuulin monen panetuksen ja pelvon joka paikasta: kantakaat päälle, me tahdomme vahvasti kantaa hänen päällensä, sanovat kaikki minun ystäväni ja kumppanini, jos me taitaisimme voittaa hänen, tulla hänen kanssansa yhteen ja kostaa hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mutta Herra on minun kanssani, niinkuin väkevä sankari; sentähden pitää minun vainoojani lankeeman ja ei voittaman, vaan pitää suureen häpiään tuleman, että he niin tyhmästi toimittavat; se häpiä pitää oleman ijankaikkinen, ja ei pidä unohdettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Ja nyt Herra Zebaot, sinä joka koettelet vanhurskaan, sinä tutkit munaskuut ja sydämen: anna minun nähdä kostos heistä; sillä minä olen antanut sinun haltuus minun asiani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Veisatkaat Herralle, kiittäkäät Herraa, joka auttaa köyhän henkeä pahain käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Kirottu olkoon se päivä, jona minä syntynyt olen; älköön se päivä olko siunattu, jona minun äitini on minun synnyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Kirottu olkoon se mies, joka minun isälleni sanomaa toi ja sanoi: sinä olet saanut nuoren pojan; suuresti ilahuttaaksensa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Se mies olkoon niinkuin ne kaupungit, jotka Herra kukisti, ja ei sitä katunut; hän kuulkaan huomeneltain parun ja puolipäivänä huudon:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Ettes siis tappanut minua äitini kohdussa, että minun äitini olis ollut minun hautani, ja hänen kohtunsa olis ijankaikkisesti kantava ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Miksi minä siis olen äitini kohdusta tullut, tuskaa ja sydämen surua näkemään, ja kuluttamaan päiviäni häpiällä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Tämä on se sana, joka tapahtui Herralta Jeremialle, kuin kuningas Zedekia lähetti hänen tykönsä Pashurin Malkian pojan, ja papin Zephanian, Maesejan pojan, ja antoi hänelle sanoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Kysy Herralta meidän puolestamme; sillä Nebukadnetsar Babelin kuningas sotii meitä vastaan: jos Herra tahtoo meille tehdä kaikkein ihmettensä jälkeen, että hän menis pois meidän tyköämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Jeremia sanoi heille: näin sanokaat Zedekialle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Näin sanoo Herra, Israelin Jumala: katso, minä tahdon kääntää ne sota-aseet takaperin, jotka teidän käsissänne ovat, joilla te soditte Babelin kuningasta vastaan ja Kaldealaisia vastaan, jotka teidän muurinne piirittäneet ovat ympäri, ja tahdon heitä koota keskelle kaupunkia kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Ja minä tahdon tapella teitä vastaan ojennetulla kädellä, väkevällä käsivarrella, julmuudella, närkästyksellä ja suurella vihalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Ja tahdon lyödä tämän kaupungin asuvaisia, sekä kansaa että karjaa, niin että heidän pitää kuoleman suureen ruttoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Ja sitte, sanoo Herra, tahdon minä antaa Zedekian, Juudan kuninkaan, palvelioinensa ja kansoinensa, jotka tähän kaupunkiin rutolta, miekalta ja nälältä jääneet ovat, Nebukadnetsarin, Babelin kuninkaan, käsiin, ja heidän vihollistensa käsiin, ja niiden käsiin, jotka seisovat heidän henkensä perään, että hänen pitää lyömän heitä miekan terällä, ettei siinä yhtään säästetä, eikä armoa eli laupiutta pidä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Ja sano tälle kansalle: näin sanoo Herra: katso, minä panen teidän eteenne elämän tien ja kuoleman tien.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Joka tässä kaupungissa asuu, hänen pitää kuoleman miekkaan, nälkään ja ruttoon; mutta joka lähtee ulos ja pakenee Kaldealaisten tykö, jotka teitä piirittävät, se saa elää ja pitää henkensä niinkuin saaliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Sillä minä olen asettanut kasvoni tätä kaupunkia vastaan onnettomuudeksi ja en hyväksi, sanoo Herra; hän pitää Babelin kuninkaan haltuun annettaman, että hän polttais hänen tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Ja kuulkaat Herran sanaa, te Juudan kuninkaan huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Sinä Davidin huone, näin sanoo Herra: pitäkäät tuomio aamulla, ja auttakaat poljettua väkivaltaisen kädestä, ettei minun julmuuteni läksisi ulos niinkuin tuli, ja palaisi, niin ettei sitä yksikään sammuttaa taida, teidän pahan menonne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Katso, sanoo Herra, minä sanon sinulle, joka asut laaksoissa, vuorilla ja tasaisilla kedoilla, ja jotka sanovat: kuka tahtoo karata meidän päällemme eli tulla meidän linnoihimme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Minä tahdon etsiskellä teitä, sanoo Herra, teidän töidenne hedelmän jälkeen, ja tahdon tulen sytyttää teidän metsäänne, kuluttamaan kaikkia, mitä siinä ympärillä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Näin sanoi Herra: mene alas Juudan kuninkaan huoneeseen, ja puhu siellä nämät sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Ja sano: kuule Herran sanaa, sinä Juudan kuningas, joka istut Davidin istuimella, sekä sinä että sinun palvelias, ja sinun kansas, jotka tästä portista sisälle käytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Näin sanoo Herra: pitäkäät laki ja oikeus, ja auttakaat poljettua väkivaltaisen kädestä, ja älkäät vaivatko muukalaista, orpoja ja leskiä, ja älkäät kellenkään tehkö vääryyttä, ja älkäät vuodattako viatointa verta tässä paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Sillä jos te kaiketi tämän teette, niin pitää kuninkaat, jotka Davidin istuimella istuvat, tämän huoneen portista menemään sisälle, jotka ajavat vaunuilla ja hevosilla, he itse palvelioinensa ja karjoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Mutta jollette näitä kuule, niin olen minä itselläni vannonut, sanoo Herra: tämä huone pitää kukistettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Sillä näin sanoo Herra Juudan kuninkaan huoneesta: Gilead, sinä olet minulle pää Libanonissa: mitämaks, minä tahdon sinun tehdä kylmille, ja laitan kaupungit olemaan ilman asuvia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Ja olen määrännyt sinulle hävittäjät, kukin aseillansa, hakkaamaan maahan sinun valitut sedripuus, ja heittämään tuleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Niin pitää monta pakanaa käymän tämän kaupungin ohitse, ja sanoman keskenänsä: miksi on Herra näin tehnyt tälle suurelle kaupungille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Ja pitää vastattaman: että he Herran Jumalansa liiton hyljänneet ovat, ja kumartaneet muita jumalia, ja palvelleet niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Älkäät itkekö kuolleita, älkäät myös sureko heitä, vaan itkekäät katkerasti sitä, joka menee pois, ja ei pidä ikinä palajaman isänsä maata näkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Sillä näin sanoo Herra Sallumista Josian, Juudan kuninkaan, pojasta, joka isänsä Josian siassa on kuningas, ja on lähtenyt tästä siasta, ettei hänen pidä tähän enään palajaman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Sillä hänen pitää kuoleman siinä paikassa, johonka hän vangiksi viety on, ja ei saa tätä maata enää nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Voi sitä, joka ei vanhurskaudella huonettansa rakenna, vaan sioittaa asuinsiansa vääryydellä; joka antaa lähimmäisensä ilman mitään työtä tehdä, ja ei anna hänelle palkkaansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Vaan ajattelee: minä tahdon rakentaa minulle suuren huoneen ja avaran salin, ja antaa hakata akkunat siihen, ja kaarittaa sen sedripuilla, ja tehdä sen punaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Ajatteletkos sinä kuningas olla, ettäs koreilet sedripuilla? Eikö isäs ole myös syönyt ja juonut? ja pysyi kuitenkin laissa ja oikeudessa, ja menestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Hän autti vaivaista ja köyhää oikeuteen, ja se menestyi hänelle hyvin. Eikö se ole tuta minua? sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Mutta sinun silmäs ja sydämes ei niin ole, vaan sinun ahneutes, vuodattaakses viatonta verta, ja tehdäkses väkivaltaa ja vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Sentähden näin sanoo Herra Jojakimista Josian, Juudan kuninkaan pojasta: ei häntä pidä itkettämän: voi veljeni! voi sisareni! ei häntä pidä itkettämän; voi herra! voi kuuluisa mies!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Hän pitää haudattaman niinkuin aasi, riepoitettaman ja heitettämän ulos Jerusalemin portin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Mene ylös Libanoniin ja huuda, ja anna äänes kuulua Basanissa, ja huuda Abarimista; sillä kaikki rakastajas ovat surkiasti surmatut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Minä olen sinulle sanonut sen, silloin kuin sinun vielä myöten kävi; mutta sinä sanoit: en minä tahdo kuulla. Juuri näin olet sinä tehnyt hamasta nuoruudestas, ettes ole kuullut minun ääntäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Tuuli ajaa pois kaikki sinun paimenes, ja sinun rakastajas menevät vangiksi; siinä pitää sinua sitte syljettämän, ja sinun pitää häpiään tuleman kaiken sinun pahuutes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Sinä, joka nyt asut Libanonissa, ja siellä pesää pidät sedripuissa; kuinka kauniisti sinun pitää katsoman, kuin tuska ja kipu sinulle tulee niinkuin lapsensynnyttäjän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Niin totta kuin minä elän, sanoo Herra: jos Konia Jojakimin, Juudan kuninkaan, poika olis sinettisormus minun oikiassa kädessäni, niin minä sittenkin repäisisin sinun siitä pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Ja antaisin sinun heidän käsiinsä, jotka seisovat sinun henkes perään, ja joitas pelkäät, ja Nebukadnetsarin, Babelin kuninkaan käsiin, ja Kaldealaisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Ja tahdon ajaa sinun ja sinun äitis, joka sinun synnyttänyt on, toiseen maahan, jossa ette syntyneet ole; ja siellä pitää teidän kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Ja siihen maahan, jossa he mielellänsä olisivat, ei pidä heidän palajaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Mikä viheliäinen, ylönkatsottu ja hyljätty mies on Konia? kelvotoin astia. Voi! miksi on hän ynnä siemenensä kanssa ajettu pois, ja tuntemattomaan maahan hyljätty?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Oi maa, maa, maa, kuule Herran sanaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Näin sanoo Herra: kirjoittakaat tämä mies lapsettomaksi ja onnettomaksi kaikkena hänen elinaikanansa: sillä ei hänellä pidä onnea oleman, että joku hänen siemenestänsä istuis Davidin istuimella, eli enää Juudaa hallitsis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Voi teitä paimenet, jotka turmelette ja hajoitatte minun laitumeni lauman! sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Sentähden näin sanoo Herra, Israelin Jumala, niistä paimenista, jotka minun kansaani kaitsevat: te olette hajoittaneet minun laumani ja ajaneet pois, ja ette etsineet sitä; katso, minä tahdon etsiä teitä teidän pahan elämänne tähden, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Ja minä tahdon koota laumani tähteet kaikista maakunnista, joihin minä heidät ajanut olen, ja tahdon saattaa heitä kotia jälleen heidän asuinsioihinsa, ja heidän pitää kasvaman ja enenemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Ja minä tahdon panna heille paimenet, joiden pitää heitä kaitseman, ettei heidän enään pidä pelkäämän eli vapiseman, eikä heitä pidä ahdistettaman, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Katso, se aika tulee, sanoo Herra, että minä herätän Davidille vanhurskaan vesan, joka on kuninkaaksi tuleva, ja on hyvin hallitseva ja toimittava oikeuden ja vanhurskauden maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Hänen aikanansa pitää Juudaa autettaman, ja Israel hyvässä turvassa asuman; ja tämä on hänen nimensä oleva kuin häntä kutsutaan: Herra meidän vanhurskautemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Sentähden katso, se aika tulee, sanoo Herra, ettei heidän pidä enään sanoman: niin totta kuin Herra elää, joka Israelin lapset johdatti Egyptin maalta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Vaan niin totta kuin Herra elää, joka Israelin huoneen siemenen toi ulos ja johdatti pohjoisesta maasta ja kaikista maakunnista, joihin minä heidät ajanut olin; niin että he nyt saavat asua omassa maassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Prophetaita vastaan: Minun sydämeni tahtoo haljeta minussa, kaikki minun luuni vapisevat. Minä olen niinkuin juopunut mies ja niinkuin se, joka viinasta horjuu, Herran edessä ja hänen pyhäin sanainsa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Että maa on niin täynnä huorintekiöitä, että maa niin surkia on, että hän kirottu on, ja kedot metsissä kuivuvat; ja heidän elämänsä on paha, ja ei heidän hallituksensa mitään kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Sillä sekä prophetat että papit ovat pahanilkiset; ja minä löydän heidän pahuutensa minun huoneessanikin, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Sentähden on heidän tiensä niinkuin liukastus pimiässä, jossa heidän pitää livistelemän ja lankeeman; sillä minä tahdon antaa onnettomuuden tulla heille heidän kuritusvuotenansa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Ja Samarian prophetaissa olen minä nähnyt hulluuden; sillä he ennustivat Baalin kautta, ja hukuttelivat minun kansani Israelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Mutta Jerusalemin prophetaissa näen minä kauhistuksen, kuinka he huorin tekevät ja valheessa vaeltavat, ja vahvistavat pahoja, ettei yhdenkään pitäisi pahuudestansa kääntymän; he ovat kaikki minun edessäni niinkuin Sodoma, ja sen asuvaiset niinkuin Gomorra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Sentähden sanoo Herra Zebaot prophetaista näin: katso, minä tahdon syöttää heitä koiruoholla, ja antaa heidän juoda sappea; sillä Jerusalemin prophetaista tulee ulkokullaisuus koko maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Näin sanoo Herra Zebaot: älkäät kuulko prophetain sanoja, jotka teille ennustavat; he pettävät teidät, sillä he saarnaavat sydämensä näkyjä, mutta ei Herran suusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'He sanovat köykäisesti niille, jotka minua pilkkaavat: Herra on sen sanonut: teillä pitää rauha oleman; ja kaikille niille, jotka vaeltavat sydämensä ajatusten jälkeen, sanovat he: ei yksikään onnettomuus tule teidän päällenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Sillä kuka on Herran neuvossa ollut, joka hänen sanansa nähnyt ja kuullut on? kuka kuulteli ja kuuli hänen sanansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Katso, Herran tuuli on julmuuden kanssa tuleva, ja hirmuinen ilma on lankeeva jumalattomain pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Ei Herran viha lakkaa, siihenasti kuin hän tekee ja täyttää sen mikä hänen mielessänsä oli. Viimein pitää teidän sen kyllä ymmärtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'En minä lähettänyt prophetaita, kuitenkin he juoksivat; en minä puhunut heille, kuitenkin he ennustivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Sillä jos he olisivat pysyneet minun neuvossani, ja olisivat saarnanneet kansalleni minun sanaani, niin he olisivat heidät kääntäneet pahasta menostansa ja töidensä pahuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Enkö minä Jumala, joka läsnä olen, sanoo Herra, ja en ole se Jumala, joka kaukana on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Luuletkos, että joku taitaa itsensä niin salaisesti kätkeä, etten minä häntä näe? sanoo Herra; enkö minä se ole, joka täytän taivaan ja maan? sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Minä kuulen, että prophetat saarnaavat ja ennustavat valhetta minun nimeeni, ja sanovat: minä näin unta, minä näin unta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Koska siis prophetat tahtovat lakata? ne jotka valhetta ennustavat, ja ennustavat oman sydämensä petoksia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Ja tahtovat, että minun kansani pitäis unhottaman minun nimeni heidän uniensa tähden, joita he toinen toisellensa saarnaavat, niinkuin heidän isänsäkin unhottivat minun nimeni Baalin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Propheta, jolla unia on, hän saarnatkaan unia; mutta jolla on minun sanani, hän saarnatkaan minun sanaani oikein. Mitä akanat ovat nisujen suhteen? sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Eikö minun sanani ole niinkuin tuli, sanoo Herra, ja niinkuin vasara, joka vuoren murentaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Sentähden katso, minä tahdon tehdä niitä prophetaita vastaan, sanoo Herra, jotka minun sanani toinen toiseltansa varastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Katso, minä tahdon niitä prophetaita vastaan tehdä, sanoo Herra, jotka omia puheitansa puhuvat ja sanovat: hän on sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Katso, minä tahdon tehdä niitä vastaan, jotka pettäväisiä unia ennustavat, sanoo Herra, ja saarnaavat niitä, vietellen minun kansani valheillansa ja turhilla jutuillansa, vaikka en minä ole heitä lähettänyt, enkä heitä käskenyt, ei myös he tälle kansalle ole ensinkään hyödylliset, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Jos tämä kansa, eli joku propheta, taikka pappi kysyy sinulta ja sanoo: Mikä on Herran kuorma? niin sinun pitää vastaaman heille: mikä kuorma? Minä tahdon heittää teidät pois, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Ja jos joku propheta, taikka pappi, elikkä kansa on sanova: tämä on Herran kuorma; sitä tahdon minä kurittaa ja hänen huonettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Mutta näin pitää kukin puhuman toisellensa ja sanoman keskenänsä: mitä Herra vastaa? ja mitä Herra sanoo?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Ja älkäät sitä enään kutsuko Herran kuormaksi; sillä kullekin pitää oma sanansa oleman kuormaksi, että te niin elävän Jumalan, Herran Zebaotin, meidän Jumalamme sanan käännätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Sentähden pitää sinun sanoman prophetalle näin: mitä Herra vastaa? ja mitä Herra sanoo?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Että te sanotte: Herran kuorma, sentähden sanoo Herra näin: että te kutsutte sanan Herran kuormaksi, niin minä olen lähettänyt teidän tykönne ja antanut sanoa, ettei teidän pitänyt sitä kutsuman Herran kuormaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Sentähden katso, minä tahdon teidät peräti unhottaa, ja heittää teitä pois ynnä kaupunkinne kanssa, jonka minä teille ja teidän isillenne antanut olen, minun kasvoini edestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Ja tahdon saattaa teitä ijankaikkiseksi pilkaksi ja ijankaikkiseksi häpiäksi, jota ei ikänä pidä unhotettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Katso, Herra osoitti minulle kaksi fikunakoria, pantua Herran templin eteen, sittekuin Nebukadnetsar, Babelin kuningas, oli vienyt pois Jekonian Jojakimin pojan Juudan kuninkaan, ja Juudan päämiehet, työmiehet ja sepät Jerusalemista, ja tuonut Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Yhdessä korissa olivat aivan hyvät fikunat, niinkuin ensin kypsyneet fikunat; mutta toisessa korissa olivat aivan pahat fikunat, niin ettei niitä taidettu syödä, että he olivat niin pahat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Ja Herra sanoi minulle: Jeremia, mitäs näet? Minä sanoin: fikunia; hyvät fikunat ovat aivan hyvät, ja pahat ovat aivan pahat, ettei niitä taideta syödä, niin pahat ne ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Näin sanoo Herra Israelin Jumala; niinkuin nämät fikunat ovat hyvät, niin minä tahdon myös armollisesti korjata Juudan vankeja, jotka minä tästä kaupungista olen lähettänyt Kaldean maalle hyväksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Ja tahdon armollisesti katsoa heidän puoleensa, ja tuoda heitä tähän maahan jälleen, ja rakentaa heitä ja en tahdo lyödä maahan, minä tahdon heitä istuttaa ja en repiä ylös,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Ja antaa heille sydämen, että he minun tuntevat, että minä olen Herra; ja he ovat minun kansani, ja minä tahdon olla heidän Jumalansa; sillä heidän pitää kaikesta sydämestänsä minun tyköni itsensä kääntämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Mutta niinkuin pahat fikunat ovat pahat, ettei kukaan niitä syödä taida, sanoo Herra, niin tahdon minä myös hyljätä Zedekian, Juudan kuninkaan, niin myös hänen päämiehensä, ja mitä Jerusalemiin jäänyt on, ja jotka tässä maassa vielä ovat, ja jotka Egyptin maassa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Minä tahdon saattaa heille onnettomuuden ja en tahdo antaa heidän olla jossakussa valtakunnassa maan päällä, niin että heidän pitää häpiään tuleman, sananparreksi, jutuksi ja kiroukseksi joka paikassa, kuhunka minä heidät ajava olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Ja tahdon lähettää miekan, nälän ja ruton heidän sekaansa, siihenasti kuin heidän pitää maasta hukkuman, jonka minä heille ja heidän isillensä antanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Tämä on se sana, joka tapahtui Jeremialle koko Juudan kansasta, neljäntenä Jojakimin Josian pojan, Juudan kuninkaan vuotena, joka oli ensimäinen Nebukadnetsarin, Babelin kuninkaan, vuosi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Jonka propheta Jeremia puhui kaikelle Juudan kansalle ja kaikille Jerusalemin asuvaisille, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Herran sana on tapahtunut minulle Josian Amonin pojan, Juudan kuninkaan, kolmannesta vuodesta toistakymmentä tähän päivään asti; ja minä olen sitä kolme ajastaikaa kolmattakymmentä teille ahkerasti saarnannut, vaan ette koskaan tahtoneet kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Niin on myös Herra lähettänyt teidän tykönne kaikki palveliansa, prophetat, juuri ahkerasti; mutta ette kuulleet ettekä kallistaneet korvianne kuulemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Koska hän sanoi: kääntäkäät teitänne kukin pahalta tieltänsä ja teidän pahasta menostanne, niin teidän pitää pysymän siinä maassa, jonka Herra teille ja teidän isillenne antanut on, ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Älkäät muita jumalia seuratko, niin että te palvelette ja kumarratte heitä; ettette minua teidän kättenne töillä vihoittaisi, ja minä teille kovan onnen saattaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Mutta ette tahtoneet kuulla minua, sanoo Herra; että te minun kumminkin vihoititte kättenne töillä omaksi onnettomuudeksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Sentähden sanoo Herra Zebaot: ettette kuulleet minun sanojani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Katso, niin minä tahdon lähettää ja antaa tulla kaikki kansat pohjoisesta, sanoo Herra, ja palveliani Nebukadnetsarin, Babelin kuninkaan, ja tuoda hänen tälle maalle niiden päälle, jotka siinä asuvat, ja kaiken tämän kansan päälle, joka tässä ympäristöllä on; ja tahdon antaa heidät haaskaksi ja hävitykseksi, ja vihellykseksi ja ijankaikkiseksi autioksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Ja tahdon heiltä ottaa pois kaiken ilon ja riemun äänen, yljän äänen ja morsiamen äänen, myllyn äänen, ja kynttilän valistuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Että kaikki tämä maa pitää kylmillä ja hävitettynä oleman, ja nämät kansat pitää Babelin kuningasta palveleman seitsemänkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Ja pitää tapahtuman, että kuin ne seitsemänkymmentä vuotta kuluneet ovat, niin minä tahdon kostaa Babelin kuninkaalle ja tälle kansalle, sanoo Herra, heidän pahain tekoinsa tähden, siihen myös Kaldealaisten maalle, ja tehdä sen ijankaikkiseksi autioksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Ja näin minä tahdon antaa tulla tämän maan päälle kaikki minun sanani, jotka minä olen puhunut häntä vastaan, kaiken sen, mikä tässä Raamatussa on kirjoitettu, jonka Jeremia kaikille kansoille on ennustanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Ja heidän pitää myös palveleman, vaikka he voimallinen kansa ja valtiaat kuninkaat ovat. Näin tahdon minä maksaa heille heidän ansionsa jälkeen ja heidän kättensä tekoin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Sillä näin sanoo Herra, Israelin Jumala, minulle: ota tämä viinamalja minun kädestäni täynnänsä vihaa, ja kaada sitä kaikille kansoille, joiden tykö minä sinun lähetän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Että se joisivat, horjuisivat ja hokariksi tulisivat miekan edessä, jonka minä heidän sekaansa tahdon lähettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Ja minä otin maljan Herran kädestä, ja kaasin kaikille kansoille, joiden tykö Herra minun lähetti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalemille, Juudan kaupungeille, hänen kuninkaillensa ja päämiehillensä, että heidän pitää oleman pilkkana ja kirouksena, niinkuin tänäpänä on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Pharaolle, Egyptin kuninkaalle, palvelioinensa, ruhtinainensa ja kaikelle hänen kansallensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'Kaikille maille etelään päin, kaikille kuninkaille Utsin maalla, kaikille kuninkaille Philistealaisten maalla, Askalonin, Gatsan, Akaronin ja Asdodin jääneiden kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edomilaisille, Moabilaisille ja Ammonin lapsille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'Kaikille Tyron kuninkaille, kaikille Sidonin kuninkaille, luotoin kuninkaille sillä puolen merta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedanille, Temalle, Busille ja kaikille maan äärissä asuvaisille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'kaikille Arabian kuninkaille, kaikille kuninkaille lännen puolessa, jotka korvessa asuvat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Kaikille Simrin kuninkaille, kaikille kuninkaille Elamissa, kaikille kuninkaille Madaissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Kaikille kuninkaille pohjoisessa, sekä läsnä että kaukana toinen toisensa kanssa, ja kaikille valtakunnille maan päällä, jotka maan piirin päällä ovat; ja kuningas Sesakin pitää juoman näiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Ja sano heille: näin sanoo Herra Zebaot, Israelin Jumala: juokaat ja juopukaat, oksentakaat ja langetkaat, ja ette taida nousta miekan edessä, jonka minä teidän sekaanne lähettää tahdon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Ja jollei he tahdo ottaa maljaa sinun kädestäs ja juoda, niin sano heille: näin sanoo Herra Zebaot: teidän pitää kaiketi juoman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Sillä katso, siinä kaupungissa, joka minun nimelläni nimitetty on, rupeen minä vaivaamaan; luuletteko että teidän pitää rankaisematta pääsemän? Ei teidän pidä rankaisematta pääsemän; sillä minä kutsun miekan kaikkein niiden päälle, jotka maalla asuvat, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Ja sinun pitää ennustaman heille kaikki nämät sanat, ja sanoman heille: Herra on kiljuva korkeudesta, ja antava kuulla äänensä pyhästä asuinsiastansa, hän on kaiketi kiljuva majastansa, hän veisaa virren, niinkuin viinan sotkuja, kaikista maan asuvaisista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Jonka ääni on kuuluva maan ääriin; sillä Herra toimittaa pakanat oikeuden eteen, ja tahtoo tuomita kaiken lihan; jumalattomat antaa hän miekan alle, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Näin sanoo Herra Zebaot: katso, vaiva tulee kansasta kansaan, ja suuri ilma nousee maan sivusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Niin pitää Herralta lyötyjä sinä päivänä oleman yhdestä maan äärestä niin toiseen asti; ei pidä heitä itkettämän eikä korjattaman, eli haudattaman, vaan pitää oleman kedolla ja loaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Parkukaat nyt, te paimenet, huutakaat ja vieristelkäät teitänne tuhassa, te lauman valtiaat; sillä aika on tullut teitä teurastaa ja hajoittaa, ja teidän pitää putooman rikki, niinkuin kallis astia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Ja ei paimenten pidä taitaman paeta, ja lauman valtiaat ei pidä pääsemän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Niin pitää paimenet surkiasti huutaman, ja lauman valtiaat surkutteleman, että Herra on niin hävittänyt heidän laitumensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Ja heidän niittynsä, jotka niin kauniit olivat, ovat hävitetyt Herran julmalta vihalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Hän on hyljännyt majansa, niinkuin nuori jalopeura; ja heidän maansa on niin hävitetty hävittäjän vihalta ja hänen julmalta vihaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Jojakimin Josian pojan, Juudan kuninkaan, valtakunnan alussa tapahtui tämä sana Herralta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Näin sanoo Herra: seiso Herran huoneen kartanolla ja saarnaa kaikkein Juudan kaupunkien edessä, jotka tänne tulevat rukoilemaan Herran huoneessa, kaikki ne sanat, jotka minä sinulle käskenyt olen, sanoakses heille; älä mitään siitä vähennä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Jos he mitämaks taitavat kuulla ja kääntyä kukin pahasta menostansa, että minäkin katuisin sitä pahaa, jonka minä heille ajattelin tehdä heidän pahan menonsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Ja sano heille: näin sanoo Herra: jos ette minua kuule, niin että te vaellatte minun laissani, jonka minä olen pannut teidän eteenne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Että te kuulette minun palveliaini, prophetain sanat, jotka minä varhain ja usiasti teille lähettänyt olen, ja ette kuitenkaan tahtoneet kuulla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Niin tahdon minä tehdä tälle huoneelle niinkuin Silolle, ja tahdon tehdä tämän kaupungin kaikille pakanoille maan päällä kiroukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Kuin papit, prophetat ja kaikki kansa kuulivat Jeremian näitä sanoja puhuvan Herran huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Ja kuin Jeremia oli lopettanut puheensa, kaiken sen, minkä Herra hänen käskenyt oli sanoa kaikelle kansalle, tarttuivat papit häneen, ja prophetat ja kaikki kansa, ja sanoivat: sinun pitää kaiketi kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Miksi sinä tohdit ennustaa Herran nimeen ja sanoa: niin pitää tälle huoneelle tapahtuman kuin Silollekin, ja tämä kaupunki pitää niin kylmille tuleman, ettei siinä kenkään enään asu? Ja kaikki kansa kokoontui Herran huoneessa Jeremiaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Kuin Juudan ruhtinaat sen kuulivat, menivät he ylös kuninkaan huoneesta Herran huoneesen, ja istuivat Herran uuden portin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Ja papit ja prophetat puhuivat ruhtinasten ja kaiken kansan edessä ja sanoivat: tämä mies on kuolemaan viallinen; sillä hän on ennustanut tätä kaupunkia vastaan, niinkuin te korvillanne kuulleet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Mutta Jeremia puhui kaikille ruhtinaille ja kaikelle kansalle, sanoen: Herra on minun lähettänyt kaikkia näitä, joita te kuulleet olette, ennustamaan tätä huonetta ja tätä kaupunkia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Niin parantakaat nyt menonne ja olonne, ja kuulkaat Herran Jumalanne ääntä; niin tahtoo myös Herra katua sitä pahaa, jonka hän on puhunut teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Mutta minä, katso, minä olen teidän käsissänne: tehkäät minun kanssani, niinkuin teille parhain kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Kuitenkin pitää teidän täydellisesti tietämän, että jos te minun tapatte, niin te tuotatte viattoman veren teidän päällenne, ja tämän kaupungin ja hänen asuvaistensa päälle; sillä Herra on totisesti minun lähettänyt teidän tykönne, puhumaan näitä kaikkia teidän korvainne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Silloin sanoivat ruhtinaat ja kaikki kansa papeille ja prophetaille: ei tämä mies ole viallinen kuolemaan; sillä hän on puhunut meille Herran Jumalamme nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Ja muutamat maan vanhimmista nousivat, ja puhuivat kaikelle kansan joukolle ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Hiskian, Juudan kuninkaan, aikana oli yksi propheta, nimeltä Miika, Maresasta; hän puhui kaikelle Juudan kansalle ja sanoi: näin sanoo Herra Zebaot: Zion pitää kynnettämän niinkuin pelto, ja Jerusalem pitää kiviraunioksi tuleman ja templin vuori metsän kukkulaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Antoiko Hiskia, Juudan kuningas, ja koko Juudan kansa hänen tappaa? eikö he peljänneet Herraa ja rukoilleet Herran edessä? ja Herra katui sitä pahaa, minkä hän oli puhunut heitä vastaan; sentähden me teemme aivan pahoin meidän sielujamme vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Oli myös yksi mies, joka ennusti Herran nimeen, Uria, Semajan poika Kirjatjearimista; hän ennusti tätä kaupunkia vastaan ja tätä maakuntaa vastaan, niinkuin Jeremiakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Mutta kuin kuningas Jojakim ja kaikki hänen voimallisensa ja valtamiehensä kuulivat hänen sanansa, tahtoi kuningas antaa hänen tappaa. Kuin Uria ymmärsi sen, pelkäsi hän ja pakeni ja meni Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Mutta kuningas Jojakim lähetti miehet Egyptiin, Elnatanin Akborin pojan, ja muita hänen kanssansa, (jotka menivät) Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Ja ne toivat Urian Egyptistä ja veivät kuningas Jojakimin eteen, ja hän antoi hänen tappaa miekalla, ja heittää hänen ruumiinsa yhteisen kansan hautoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Kuitenkin oli Ahikamin, Saphanin pojan käsi Jeremian kanssa, ettei hän tullut kansan käsiin tapettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Jojakimin Josian pojan, Juudan kuninkaan, valtakunnan alussa tapahtui tämä sana Herralta Jeremialle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Näin sanoo Herra minulle: tee sinulles siteet ja pane kaulaas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Ja lähetä ne Edomin kuninkaalle, Moabin kuninkaalle, Ammonin lasten kuninkaalle, Tyron kuninkaalle ja Sidonin kuninkaalle, niiden sanansaattajain kanssa, jotka olivat tulleet Zedekian, Juudan kuninkaan, tykö Jerusalemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Ja käske, että he sanovat herroillensa: näin sanoo Herra Zebaot, Israelin Jumala: näin pitää teidän sanoman herroillenne:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Minä olen tehnyt maan, ja ihmisen, ja eläimet, jotka maan päällä ovat, suurella voimallani ja ojennetulla käsivarrellani, ja annan sen kelle minä tahdon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Mutta nyt olen minä antanut kaikki nämät maakunnat palveliani Nebukadnetsarin, Babelin kuninkaan, käteen, ja olen myös antanut hänelle pedot maan päällä, palvelemaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Ja kaikki kansat pitää häntä palveleman, hänen poikaansa ja hänen poikansa poikaa, siihenasti kuin hänenkin maansa aika tulee; sillä monta kansaa ja suuret kuninkaat pitää häntä palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Vaan sen kansan ja valtakunnan, joka ei tahdo palvella Babelin kuningasta Nebukadnetsaria, eikä anna niskaansa Babelin kuninkaan ikeen alle, tahdon minä kurittaa miekalla, nälällä ja rutolla, sanoo Herra, siihenasti että minä hukutan heidät hänen kätensä kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Sentähden älkäät kuulko prophetaitanne, ennustajianne, unianne, tietäjiänne ja noitianne, jotka teille sanovat: ei teidän pidä palveleman Babelin kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Sillä he ennustavat teille valhetta, saattaaksensa teitä kauvas teidän maastanne; ja minä ajan silloin teitä ulos, ja teidän pitää hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Sillä kuka kansa kumartaa kaulansa Babelin kuninkaan ikeen alle ja palvelee häntä, sen tahdon minä antaa olla maassansa, että he sitä saavat nautita ja siinä asua, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Ja minä puhuin kaikki nämät Zedekialle, Juudan kuninkaalle, ja sanoin: kumartakaat kaulanne Babelin kuninkaan ikeen alle, ja palvelkaat häntä ja hänen kansaansa, niin te saatte elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Miksi te tahdotte kuolla, sinä ja sinun kansas miekalla, nälällä ja rutolla? niinkuin Herra on siitä kansasta sanonut, joka ei Babelin kuningasta palvella tahdo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Sentähden älkäät kuulko prophetainne sanoja, jotka teille sanovat: ei teidän pidä Babelin kuningasta palveleman; sillä he ennustavat teille valhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Sillä en minä ole heitä lähettänyt, sanoo Herra; vaan he ennustavat valhetta minun nimeeni, että minä ajaisin teitä ulos, ja te hukkuisitte ynnä prophetain kanssa, jotka teille ennustavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Ja papeille ja kaikelle tälle kansalle puhuin minä ja sanoin: näin sanoo Herra: älkäät kuulko prophetainne sanoja, jotka teille ennustavat ja sanovat: katso, Herran huoneen astiat tulevat nyt kohta jälleen Babelista; sillä he ennustavat teille valhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Älkäät heitä kuulko, vaan palvelkaat Babelin kuningasta, niin te saatte elää. Miksi pitäis tämän kaupungin kylmille tuleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Jos he ovat prophetat, ja jos heillä on Herran sana, niin rukoilkaat nyt Herralta Zebaotilta, ettei jääneet astiat Herran huoneessa ja Juudan kuninkaan huoneessa, ja Jerusalemissa myös vietäisi Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Sillä näin sanoo Herra Zebaot patsaista, ja merestä, ja istuimista, ja astioista, jotka vielä tähän kaupunkiin jääneet ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Joita Nebukadnetsar, Babelin kuningas ei ottanut pois, kuin hän vei pois Juudan kuninkaan Jekonian Jojakimin pojan Jerusalemista Babeliin, ja kaikki Juudan ja Jerusalemin valtamiehet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Sillä näin sanoo Herra Zebaot, Israelin Jumala, niistä astioista, jotka vielä jääneet ovat Herran huoneesen, ja kuninkaan huoneesen, ja Jerusalemiin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Ne pitää Babeliin vietämän ja siellä pysymän siihen päivään asti, että minä etsin heitä, sanoo Herra, ja annan heidän vietää ylös ja taas tuotaa tähän paikkaan siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Ja tapahtui sinä vuotena, Zedekian Juudan kuninkaan valtakunnan alussa, viidentenä kuukautena neljännellä vuodella, että Hanania Assurin poika, Gibeonin propheta, puhui minulle Herran huoneessa, pappein ja kaiken kansan edessä, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Näin sanoo Herra Zebaot, Israelin Jumala, sanoen: minä olen taittanut rikki Babelin kuninkaan ikeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Ja ennenkuin kaksi ajastaikaa kuluu, tahdon minä antaa tulla jälleen tähän siaan kaikki Herran huoneen astiat, jotka Nebukadnetsar, Babelin kuningas, täältä ottanut ja Babeliin vienyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Vielä sitte tahdon minä myös Jekonian Jojakimin pojan, Juudan kuninkaan, ja kaikki Juudan vangit, jotka Babeliin viedyt ovat, antaa tulla tähän siaan jälleen, sanoo Herra; sillä minä tahdon taittaa rikki Babelin kuninkaan ikeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Niin propheta Jeremia sanoi propheta Hananialle, pappein ja kaiken joukon läsnä ollessa, jotka seisoivat Herran huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Ja propheta Jeremia sanoi: Amen. Herra tehköön niin! Herra vahvistakoon sinun sanas, jonka ennustanut olet, että hän antais Herran huoneen astiat ja kaikki vangit tulla tähän paikkaan jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Mutta kuule kuitenkin tätä sanaa, jonka minä puhun sinun korvais ja kaiken kansan korvain edessä puhun:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Ne prophetat, jotka minun edelläni ja sinun edelläs vanhasta olleet ovat, he ovat ennustaneet monta maakuntaa ja suuria valtakuntia vastaan sotaa, onnettomuutta ja ruttoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Mutta kuin propheta ennustaa rauhaa, niin tunnetaan, kuin hänen sanansa täytetyksi tulee, että Herra hänen totisesti on lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Niin propheta Hanania otti ikeen propheta Jeremian kaulasta ja taitti sen rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Ja Hanania sanoi kaiken kansan edessä: näin sanoo Herra: niin tahdon minä myös taittaa rikki Nebukadnetsarin, Babelin kuninkaan, ikeen kaikkein kansain kaulasta, ennenkuin kaksi ajastaikaa kuluneet ovat. Ja propheta Jeremia meni pois omaa tietänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Mutta Herran sana tapahtui Jeremialle, sittenkuin propheta Hanania oli rikkonut ikeen propheta Jeremian kaulasta, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Mene ja sano Hananialle: näin sanoo Herra: sinä olet taittanut rikki puu-ikeen, niin tee nyt rauta-ijes sen siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Sillä näin sanoo Herra Zebaot Israelin Jumala: minä olen ripustanut rauta-ikeen kaikkien näiden kansain kaulaan, palvelemaan Nebukadnetsaria, Babelin kuningasta, ja heidän pitää palveleman häntä; sillä minä olen myös antanut hänelle pedot kedolta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Ja propheta Jeremia sanoi propheta Hananialle: kuule nyt Hanania, ei Herra ole sinua lähettänyt, ja sinä olet tehnyt, että tämä kansa luottaa valheesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Sentähden sanoo Herra näin: katso, minä tahdon ottaa sinun pois maasta; tänä vuonna pitää sinun kuoleman, sillä sinä olet puheellas kääntänyt heidät Herrasta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Ja niin propheta Hanania kuoli sinä vuonna, seitsemännellä kuukaudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Nämät ovat kirjoituksen sanat, jotka Jeremia propheta lähetti Jerusalemista jääneille vanhimmille, jotka olivat viedyt pois, ja papeille, ja prophetaille ja kaikelle kansalle, jotka Nebukadnetsar oli vienyt Jerusalemista Babeliin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Sittekuin kuningas Jekonia ja kuningatar, kamaripalveliat, ja Juudan ja Jerusalemin päämiehet sekä puuseppäin ja seppäin kanssa olivat pois Jerusalemista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Elasan Saphanin pojan ja Gemarjan Hilkian pojan kautta, jotka Juudan kuningas Zedekia lähetti Nebukadnetsarin, Babelin kuninkaan, tykö Babeliin; sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Näin sanoo Herra Zebaot, Israelin Jumala, kaikille vangeille, jotka minä olen antanut viedä pois Jerusalemista Babeliin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Rakentakaat huoneita, joissa te taidatte asua, istuttakaat puutarhoja, joissa te saisitte syödä hedelmiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Naikaat emäntiä, ja siittäkäät poikia ja tyttäriä, ja antakaat pojillenne emäntiä, ja naittakaat tyttärenne miehille, että he synnyttäisivät poikia ja tyttäriä; enentäkäät itsiänne siellä, ettette vähenisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Katsokaat sen kaupungin parasta, johonka minä olen teitä antanut vietää, ja rukoilkaat sen edestä Herraa; sillä kuin se menestyy, niin myös te menestytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Sillä näin sanoo Herra Zebaot, Israelin Jumala: älkäät antako prophetainne, jotka teidän tykönänne ovat, ja tietäjänne pettää teitä, ja älkäät totelko unianne, joita te unissanne näette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Sillä he ennustavat teille valhetta minun nimeeni: en minä ole heitä lähettänyt, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Sillä näin sanoo Herra: kuin Babelissa seitsemänkymmentä vuotta ovat kuluneet, niin minä tahdon etsiä teitä, ja herättää armollisen sanani teidän päällenne, niin että minä tahdon antaa teidän tulla tähän paikkaan jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Sillä minä kyllä tiedän, mitkä teistä minun ajatukseni ovat, sanoo Herra: rauhan ja ei murheen ajatukset; että minä olen antava teille sen lopun, jonka te toivotte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Ja teidän pitää minua rukoileman, käymän ja anoman minulta, ja minä kuulen teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Teidän pitää etsimän minua ja löytämän minun: sillä jos te etsitte minua kaikesta sydämestänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Niin minä tahdon antaa itseni löytää teiltä, sanoo Herra, ja kääntää teidän vankiutenne, ja koota teidän kaikesta kansasta ja kaikista paikoista, joihin minä teidät ajanut olin, sanoo Herra; ja tahdon antaa teidän tulla jällensä tähän paikkaan, josta minä olen antanut viedä teitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Mutta jos te ajattelette: Herra on herättänyt meille prophetaita Babelissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Niin sanoo Herra näin siitä kuninkaasta, joka istuu Davidin istuimella, ja kaikesta kansasta, joka tässä kaupungissa asuu, teidän veljistänne, jotka ei teidän kanssanne lähteneet vankiuteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Näin tosin sanoo Herra Zebaot: katso, minä lähetän heidän sekaansa miekan, nälän ja ruton, ja teen heille niinkuin pahoille fikunoille, joita ei syödä taideta, että ne niin pahat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Ja vainoon heitä miekalla, nälällä ja rutolla, ja panen heidät kulkiaksi kaikissa valtakunnissa maan päällä, että heidän pitää tuleman kiroukseksi, ihmeeksi, häväistykseksi ja pilkaksi kaikkein kansain seassa, kuhunka minä heidät ajava olen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Ettei he kuulleet minun sanojani, sanoo Herra, joita minä varhain minun palveliaini prophetain kanssa heille lähettänyt olen; mutta ette tahtoneet kuulla, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Mutta te kaikki, jotka vangittuina olette viedyt pois, jotka minä olen Jerusalemista antanut mennä Babeliin, kuulkaat Herran sanaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Näin sanoo Herra Zebaot, Israelin Jumala, Ahabia Kolajan poikaa ja Zedekiaa Maasejan poikaa vastaan, jotka teille minun nimeeni valhetta ennustavat: katso, minä annan heidät Nebukadnetsarin, Babelin kuninkaan, käsiin, hänen pitää antaman heitä lyödä teidän silmäinne edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Ja heitä pitää sadateltaman kaikkein Juudan vankein seassa, jotka ovat Babelissa, ja sanottaman: Herra tehköön sinulle niinkuin Zedekialle ja Ahabille, jotka Babelin kuningas antoi tulessa paistaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Että he tekivät hulluuden Israelissa, ja makasivat muiden emäntiä, ja saarnasivat valhetta minun nimeeni, jota en minä ollut heille käskenyt. Ja minä sen tiedän ja todistan, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Ja Semajaa vastaan Nehalamista pitää sinun puhuman, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Näin puhuu Herra Zebaot, Israelin Jumala, sanoen: että sinä sinun nimelläs olet lähettänyt kirjoituksen kaikelle kansalle, joka on Jerusalemissa, ja papille Zephanialle Maasejan pojalle, ja kaikille papeille, ja sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Herra on asettanut sinun papiksi, papin Jehojadan siaan, olemaan esimiehet Herran huoneessa, ylitse kaikkein mielipuolten ennustajain, panemaan heitä vankiuteen ja jalkapuuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Miksi et sinä siis nuhtele Jeremiaa Anatotista, joka teille ennustaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Sillä hän on lähettänyt meidän tykömme Babeliin, ja antanut meille sanoa: vielä nyt pitää oleman aikaa, rakentakaat huoneita ja asukaat niissä, ja istuttakaat puutarhoja, syödäksenne niistä hedelmiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Ja kuin pappi Zephania oli lukenut sen kirjoituksen Jeremian prophetan kuullen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Niin tapahtui Herran sana Jeremialle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Lähetä kaikkein vankein tykö ja anna heille sanoa: näin sanoo Herra Semajaa vastaan Nehalamista: että Semaja ennustaa teille, ja en kuitenkaan minä ole häntä lähettänyt, ja on tehnyt, että te luotatte valheesen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Sentähden sanoo Herra näin: katso, minä tahdon kostaa Semajalle Nehalamista ja hänen siemenellensä, niin ettei yhdenkään pidä hänen omistansa pysymän tämän kansan seassa, eikä pidä näkemän sitä hyvää, jonka minä tahdon tehdä kansalleni, sanoo Herra; sillä hän on puheellansa kääntänyt heidät pois Herrasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Tämä on se sana, joka tapahtui Herralta Jeremialle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Näin sanoo Herra Israelin Jumala, sanoen: kirjoita itselles kirjaan kaikki ne sanat, jotka minä puhun sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Sillä katso, se aika tulee, sanoo Herra, että minä tahdon kääntää kansani vankiuden, sekä Israelin että Juudan, sanoo Herra, ja annan heidän tulla jälleen siihen maahan, jonka minä heidän isillensä antanut olen, että he sen omistaman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Ja nämät ovat ne sanat, jotka Herra puhui Israelista ja Juudasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Sillä näin sanoo Herra: me kuulemme pelvon äänen, siellä on sula pelko ja ei yhtään rauhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Kysykäät nyt ja katsokaat, taitaako miehenpuoli synnyttää? Kuinkasta siis minä näen kaikkein miesten kädet lanteissansa niinkuin lapsensynnyttäjän, ja että kaikki kasvot ovat niin valjut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Voi! se on suuri päivä, ja ei ole senkaltaista ollut; ja murheen aika on Jakobissa, kuitenkin pitää heitä siitä autettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Mutta sen pitää tapahtuman siihen aikaan, sanoo Herra Zebaot, että minä taitan hänen ikeensä rikki kaulastas, ja repäisen sinun sitees, niin ettei heidän enään siellä pidä muukalaisia palveleman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Vaan heidän pitää palveleman Herraa Jumalaansa ja Davidia kuningastansa, jonka minä heille herättänyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Sentähden älä pelkää palveliani Jakob, sanoo Herra, ja Israel älä hämmästy! sillä katso, minä tahdon auttaa sinua kaukaa, ja sinun siementäs vankiutensa maasta, niin että Jakobin pitää tuleman jällensä, elämän rauhassa ja oleman hyvässä levossa, ja ei kenenkään pidä häntä peljättämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Sillä minä olen sinun tykönäs, sanoo Herra, auttamassa sinua; ja teloitan kaikki pakanat, joihin minä olen sinut hajoittanut; mutta en minä sinua lopeta, vaan tahdon sinua kurittaa kohtuudella, ja en tahdo sinua peräti viattomana pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Sillä näin sanoo Herra: sinun haavas on kuoleman haava, ja sinun kipus juuri paha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Ei toimita kenkään sinun asias sortajaa vastaan; ei kenkään taida sinua parantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Kaikki sinun rakastajas unhottavat sinun, ja ei kysy sinua; sillä minä olen lyönyt sinua, niinkuin vihollista armottomalla kurituksella, suurten pahaintekois tähden ja raskasten synteis tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Mitäs huudat haavais tähden ja suuresta kivustas? Minä olen tämän tehnyt sinulle suurten pahaintekois ja raskasten synteis tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Sentähden kaikki, jotka sinua ovat syöneet, heitä pitää taas syötämän, ja kaikki sinun vihollises pitää vangiksi tuleman; jotka sinua ovat ryöstäneet, pitää jälleen ryöstettämän, ja kaikki ne, jotka sinun ovat ryövänneet, tahdon minä saaliiksi antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Mutta sinun minä jälleen parannan, ja teen terveeksi haavas, sanoo Herra, sillä he ovat sinun kutsuneet ulosajetuksi ja Zionin siksi, jota ei kenkään kysy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Näin sanoo Herra: katso, minä käännän Jakobin majan vankiuden, ja armahdan hänen asumistansa; ja kaupunki pitää jälleen mäelle rakennettaman, ja kirkon pitää oleman entisellä muodollansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Ja kiitoksen ja riemun äänen pitää siitä kuuluman; sillä minä tahdon heitä enentää ja en vähentää, minä tahdon heitä kunnioittaa, ja ei heidän pidä huonoksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Hänen poikansa pitää oleman niinkuin ennenkin, ja hänen yhteinen kansansa pitää menestymän minun edessäni; sillä minä tahdon rangaista kaikki ne, jotka heitä vaivaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Ja hänen ruhtinaansa pitää itse hänestä syntymän, ja hänen hallitsiansa tuleman itse hänestä. Ja minä tahdon antaa hänen lähestyä ja tulla minun eteeni; sillä kuka on se, joka minua niin sydämellisesti lähestyy? sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Ja teidän pitää oleman minun kansani, ja minä olen teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Katso, Herran ilma on tuleva julmuudella, kauhia rajuilma on lankeeva jumalattomain pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Herran julma viha ei ole taukoava, siihenasti kuin hän tekee ja toimittaa, mitä hänen mielessänsä on. Viimein pitää teidän sen kyllä ymmärtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Sillä ajalla, sanoo Herra, tahdon minä kaikkein Israelin sukukuntain Jumala olla; ja heidän pitää minun kansani oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Näin sanoo Herra: se kansa, joka miekalta jäi, on armon korvessa löytänyt siinä, että minä ahkeroitsin saattaa Israelin lepoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Herra ilmestyy minulle kaukaa: minä olen ijankaikkisella rakkaudella sinua rakastanut, sentähden olen minä vetänyt sinua puoleeni sulasta armosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Minä tahdon rakentaa sinua jälleen, ja sinun, neitsy Israel, pitää rakennetuksi tuleman. Sinun pitää kaunistetuksi tuleman sinun kanteleillas, ja menemän niiden kanssa, jotka ilossa hyppäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Sinun pitää taas istuttaman viinapuita Samarian vuorilla, istuttaman ja nautitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Sillä vielä on se aika tuleva, että vartiat pitää Ephraimin vuorella huutaman: nouskaat, käykäämme ylös Zioniin, Herran meidän Jumalamme tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Sillä näin sanoo Herra: huutakaat Jakobista ilolla, ja ihastukaat pakanain pään tähden: huutakaat korkiasti, ylistäkäät ja sanokaat: Herra, auta kansaas, Israelin jääneitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Katso, minä tahdon antaa heidän tulla pohjoisesta maakunnasta, ja tahdon heitä koota maan ääristä, sokiat, rammat, raskaat, synnyttäväiset yhdessä; niin että heidän tänne suuressa joukossa pitää tuleman jällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Heidän pitää itkien ja rukoillen tuleman, niin minä heitä johdatan. Minä tahdon heitä johdattaa vesiojain reunalla tasaista tietä, ettei he loukkaisi itseänsä; sillä minä olen Israelin isä, ja Ephraim on minun esikoiseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Kuulkaat pakanat, Herran sanaa, ja julistakaat kaukana luodoissa, ja sanokaat: joka Israelin hajoitti, se kokoo hänen jälleen, ja on häntä vartioitseva niinkuin paimen laumaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Sillä Herra on lunastava Jaakobin, ja on pelastava häntä sen kädestä, joka häntä väkevämpi on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'He tulevat ja Zionin korkeudella veisaavat, ja heidän pitää joukolla Herran lahjain tykö tuleman, jyväin, viinan, öljyn, karitsain ja vasikkain tykö; niin että heidän sielunsa pitää oleman niinkuin kastettu yrttitarha, eikä enää surullinen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Silloin pitää neitseet hypyssä iloiset oleman, siihen myös nuoret miehet ynnä vanhain kanssa; sillä minä tahdon heidän murheensa iloksi kääntää, ja lohduttaa heitä, ja ilahutan heitä murheestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Ja minä tahdon pappien sydämet ilolla täyttää, ja minun kansani pitää minun lahjastani ravittaman, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Näin sanoo Herra: Raamasta kuuluu parkuvaisten ääni ja katkera itku; Raakel itkee lapsiansa, ja ei tahdo itsiänsä lohdutettaa lastensa tähden, ettei he ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Näin Herra sanoo näin: lakkaa parkumasta ja itkemästä, ja pyyhi silmistäs kyyneleet; sillä sinun työlläs pitää palkka oleman, sanoo Herra, ja heidän pitää palajaman vihollisten maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Ja sinun jälkeentulevaisillas pitää toivo oleman, sanoo Herra; sillä sinun lapses pitää tuleman maallensa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Kyllä minä olen kuullut, kuinka Ephraim valittaa: sinä olet minua kurittanut minua, ja minä olen myös kuritettu, niinkuin hillimätöin vasikka. Palauta minua, niin minä palajan, sillä sinä, Herra, olet minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Koska minä palautettiin, niin minä kaduin; sillä sittekuin minä taitavaksi tulin, niin minä löin lanteitani. Minä olin häväisty ja häpeen myös, sillä minun täytyy kärsiä nuoruuteni pilkkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Eikö Ephraim ole rakas poikani ja ihana lapseni? Sillä minä kyllä hyvin muistan, mitä minä hänelle puhunut olen; sentähden minun sydämeni halkee laupiudesta hänen kohtaansa, että minä kaiketi armahdan häntä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Pane sinulles muistomerkit, ja aseta sinulles murheenmuisto, ja kohenna sydämes oikialle tielle, jota sinun vaeltaman pitää. Palaja, neitsy Israel, palaja näiden sinun kaupunkeis tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Kuinka kauvan sinä tahdot eksyksissä käydä, sinä vastahakoinen tytär? Sillä Herra on jotakin uutta maalla luova, vaimon pitää miestä piirittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Näin sanoo Herra Zebaot, Israelin Jumala: Vielä tämä sana sanotaan Juudan maassa ja hänen kaupungeissansa, kun minä heidän vankiutensa kääntävä olen: Herra siunatkoon sinua, sinä vanhurskauden asumus, sinä pyhä vuori.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Ja Juuda ynnä kaikkein hänen kaupunkeinsa kanssa pitää siellä asuman, niin myös peltomiehet, ja jotka laumansa kanssa vaeltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Sillä minä tahdon väsyneen sielut virvoittaa, ja murheelliset sielut ravita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Sentähden minä heräsin ja katselin, jossa minä olin makiasti maannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Katso, aika tulee, sanoo Herra, että minä tahdon Israelin huoneen ja Juudan huoneen kylvää ihmisen siemenellä ja karjan siemenellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Ja pitää tapahtuman, että niinkuin minä olin valpas heitä hävittämään, repimään, raatelemaan, kadottamaan ja rankaisemaan: niin minä myös tahdon valpas olla heitä rakentamaan ja istuttamaan, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Ei silloin enään pidä sanottaman: isät ovat happamia viinamarjoja syöneet, ja lasten hampaat ovat huoltuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Vaan jokaisen pitää pahan tekonsa tähden kuoleman, ja kuka ihminen syö happamia viinamarjoja, hänen hampaansa pitää huoltuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Katso, se aika tulee, sanoo Herra, että minä teen uuden liiton Israelin huoneen kanssa ja Juudan huoneen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'En senkaltaista kuin entinen liitto oli, jonka minä heidän isäinsä kanssa tein, kun minä heidän käteensä rupesin, heitä Egyptin maalta johdattaakseni; jota liittoa ei he pitäneet, ja minä vallitsin heitä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Mutta tämän pitää se liitto oleman, jonka minä Israelin huoneen kanssa teen tämän ajan perästä, sanoo Herra: minä tahdon minun lakini antaa heidän sydämeensä ja sen heidän mieliinsä kirjoittaa; ja minä tahdon olla heidän Jumalansa, ja heidän pitää minun kansani oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Ja ei pidä kenenkään lähimmäistänsä opettaman, eikä veli veljeänsä, ja sanoman: tunne Herraa; sillä heidän pitää kaikkein minun tunteman, sekä pienten että suurten, sanoo Herra; sillä minä tahdon heidän pahat tekonsa antaa anteeksi, ja en ikinä enään muista heidän syntejänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Näin sanoo Herra, joka auringon antaa päivällä valkeudeksi, kuun ja tähtien järjestyksen yöllä valkeudeksi: joka meren liikuttaa, että hänen aaltonsa pauhaavat, Herra Zebaot on hänen nimensä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Kun senkaltaiset säädyt minun edestäni hukkuvat, sanoo Herra, silloin myös Israelin siemenen pitää puuttuman, ettei se ole enään kansa minun edessäni ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Näin sanoo Herra: jos taivasta taidetaan ylhäällä mitata, ja maan perustusta alhaalla tyynni tutkiskella; niin myös minä tahdon heittää pois koko Israelin siemenen kaikkein, niiden tähden, mitkä he tehneet ovat, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Katso, aika tulee, sanoo Herra, että Herran kaupunki rakennetaan jälleen Hananeelin tornista Kulmaporttiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Ja mittanuora pitää siellä kohdastansa käymän hamaan Garebin kukkulaan asti, ja käymän ympäri Goaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Ja kaiken ruumisten ja tuhkalaakson, ja kaikki pellot, hamaan Kidronin ojaan saakka, ja hamaan Hevosportin kulmaan, itään päin, pitää Herralle pyhä oleman, niin ettei sitä ikänä särjetä eli rikota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Tämä on se sana, joka tapahtui Herralta Jeremialle, kymmenentenä Zedekian, Juudan kuninkaan, vuonna, joka on Nebukadnetsarin kahdeksastoistakymmenes vuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Silloin Babelin kuninkaan sotajoukko piiritti Jerusalemin; mutta propheta Jeremia oli vankina pihassa vankihuoneen edessä, joka oli Juudan kuninkaan huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Johonka Zedekia, Juudan kuningas, oli antanut panna hänen, sanoen: miksi sinä ennustat ja sanot: näitä sanoo Herra: katso, minä annan tämän kaupungin Babelin kuninkaan käsiin, ja hän on voittava sen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Ja Zedekian, Juudan kuninkaan, ei pidä kaldealaisilta pääsemän, vaan minä kaiketi annan hänen Babelin kuninkaan käsiin, niin että hänen pitää suusta suuhun häntä puhutteleman, ja silmillänsä hänen silmänsä näkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Ja hänen pitää viemän Zedekian Babeliin; siellä hänen pitää myös pysymän, siihenasti kuin minä etsin häntä, sanoo Herra. Vaikka te soditte kaldealaisia vastaan, ei sen kuitenkaan pidä teille menestyvän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Ja Jeremia sanoi: Herran sana on tapahtunut minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Katso, Hanamel Sallumin, sinun setäs poika, tulee sinun tykös, ja on sanova: osta minun peltoni Anatotissa, sillä sinulla on lähimmäinen oikeus sitä ostaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Ja niin Hanamel minun setäni poika tuli minun tyköni, niinkuin Herra oli sanonut, pihalla vankihuoneen edessä, ja sanoi minulle: osta minun peltoni Anatotissa, joka on Benjaminin maalla; sillä sinulla on siihen perintö-oikeus, ja sinä olet lähimmäinen: osta se sinulles. Niin minä ymmärsin, sen olevan Herran sanan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Ja ostin Hanamelilta minun setäni pojalta pellon, joka on Anatotissa, ja punnitsin hänelle rahaa seitsemäntoista sikliä ja kymmenen hopea penninkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Ja kirjoitin kirjaan, ja vahvistin sen sinetillä, ja otin todistukset, ja punnitsin rahan vaa\'alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Ja otin sinetillä vahvistetun kauppakirjan tyköni, oikeuden ja tavan jälkeen, ja myös avoimen kirjan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Ja annoin kauppakirjan Barukille Neerijan pojalle, Mahsejan pojan, Hanamelin, minun setäni pojan silmäin edessä ja todistajain silmäin edessä, jotka kauppakirjan allekirjoittaneet olivat, ja kaikkien Juudalaisten silmäin edessä, jotka pihassa vankihuoneen edessä asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'ja minä käskin Barukia heidän silmäinsä edessä ja sanoin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Näin sanoo Herra Zebaot, Israelin Jumala: ota nämä kirjat, tämä sinetillä vahvistettu kauppakirja, ja tämä avoin kirja, ja pane ne saviastiaan, että ne olisivat kauvan aikaa tallella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Sillä näin sanoo Herra Zebaot, Israelin Jumala: vielä nyt pitää ostettaman huoneita, peltoja ja viinamäkiä tässä maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Ja kun minä olin antanut Baarukille Nerian pojalle kauppakirjan, rukoilin minä Herraa ja sanoin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ah Herra, Herra! katso, sinä olet tehnyt taivaat ja maan suurella voimallas ja ojennetulla käsivarrellas; ei ole mitään sinulle mahdotonta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Sinä, joka monelle tuhannelle teet hyvin, ja kostat isäin pahat teot heidän lastensa helmaan heidän jälkeensä; sinä suuri ja väkevä Jumala, Zebaot on sinun nimes,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Suuri neuvossa ja väkevä töissä, ja sinun silmäs ovat avoinna kaikkein ihmisten lasten teiden päälle, antaakses kullekin heidän menonsa jälkeen ja heidän töittensä hedelmän jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Sinä, joka Egyptin maalla merkkejä ja ihmeitä teit, ja aina tähän päivään asti, sekä Israelin että ihmisten kanssa, ja teit sinulles nimen, niinkuin se tänäpänä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Sinä veit kansas Israelin ulos Egyptin maalta merkeillä ja ihmeillä ja väkevällä kädellä, ojennetulla käsivarrella, ja suurella pelvolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Ja annoit heille tämän maan, jonka sinä heidän isillensä vannonut olit, sen heille antaakses: maan, joka rieskaa ja hunajaa vuosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Ja koska he sinne tulivat ja omistivat sen, ei he kuulleet sinun ääntäs, eikä vaeltaneet sinun lakisi jälkeen; ja kaikkea mitä sinä käskenyt olit heidän tehdä, ei he sitä tehneet; sentähden sinä annoit myös kaiken tämän onnettomuuden heille tapahtua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Katso, tämä kaupunki on piiritetty, niin että se pitää voitettaman, ja kaupunki annettaman Kaldealaisten käsiin, jotka sotivat sitä vastaan miekalla, nälällä ja rutolla; ja niinkuin sinä olet sanonut, niin nyt tapahtuu, sen sinä näet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Ja sinä Herra, Herra, sanoit minulle: osta sinulles pelto rahalla, ja ota todistukset, vaikka kaupunki pitää annettaman joutuu kaldealaisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Ja Herran sana tapahtui Jeremialle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Katso, minä Herra olen kaiken lihan Jumala: pitäiskö minulle jotain oleman mahdotointa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Sentähden sanoo Herra näin: katso, minä annan tämän kaupungin Kaldealaisten käsiin ja Nebukadnetsarin, Babelin kuninkaan käteen, ja hän on sen voittava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Ja kaldealaisten, jotka sotivat tätä kaupunkia vastaan, pitää tänne tuleman, ja sytyttävät tämän kaupungin tuleen ja polttavat sen niine taloineen, ja tähän kaupunkiin tulen sytyttämän, ja polttaman sen huoneinensa, kussa he Baalille kattoin päällä suitsuttaneet, ja muille jumalille juomauhreja uhranneet ovat, minua vihoittaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Sillä Israelin lapset ja Juudan lapset ovat tosin nuoruudestansa tehneet pahaa minun silmäini edessä; ja Israelin lapset ovat vihoittaneet minun kättensä töillä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Siitä ajasta, kuin tämä kaupunki rakennettiin, niin tähän päivään asti, on hän tehnyt minun vihaiseksi ja julmaksi, niin että minun täytyi heittää hänen pois kasvojeni edestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Kaikkein Israelin lasten ja Juudan lasten pahuuden tähden, jonka he ovat tehneet, minua vihoittaaksensa, he ja heidän kuninkaansa, ruhtinaansa, pappinsa ja prophetansa, sekä Juudan miehet ja Jerusalemin asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'He ovat kääntäneet selkänsä minulle ja ei kasvojansa; vaikka minä annoin aikanansa ja alinomaa opettaa heitä, mutta ei he tahtoneet kuulla eikä oppia ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Päälliseksi he ovat panneet kauhistuksensa siihen huoneeseen, jolla minusta on nimi, saastuttaaksensa sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Ja ovat rakentaneet Baalin korkeuksia Ben-Hinnomin laaksossa, polttaakseen poikiansa ja tyttäriänsä Molokille, jota en minä ole heidän käskenyt, eikä myös ole minun mieleeni johtunut, että heidän tämän kauhistuksen piti tekemän, jolla he Juudan saattivat syntiä tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Ja nyt sentähden sanoo Herra, Israelin Jumala näin tästä kaupungista, josta te sanotte, että hän pitää miekan, nälän ja ruton kautta Babelin kuninkaan käsiin annettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Katso, minä tahdon heidät koota kaikista maakunnista, joihin minä olen heitä sysännyt pois suuressa vihassani, hirmuisuudessani ja julmuudessani ja tahdon tuottaa heitä jälleen tähän paikkaan, että heidän turvallisesti asuman pitää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Ja heidän pitää minun kansani oleman, ja minä tahdon olla heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Ja tahdon heille yhden sydämen ja yhden tien antaa, että he pelkäisivät minua kaikkena elinaikanansa, että heille ja heidän lapsillensa heidän jälkeensä pitäis hyvästi käymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Ja tahdon ijankaikkisen liiton tehdä heidän kanssansa, niin etten minä lakkaa heille hyvää tekemästä; ja tahdon minun pelkoni antaa heidän sydämihinsä, ettei he poikkeaisi minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Ja se pitää minun iloni oleman, että heille hyvää teen; ja tahdon heitä tähän maahan istuttaa uskollisesti, kaikesta minun sydämestäni ja kaikesta sielustani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Sillä näin sanoo Herra: niinkuin minä olen antanut tulla tämän kansan päälle kaiken tämän tämän suuren onnettomuuden, niin myös minä annan tulla heidän päällensä kaiken sen hyvän, kuin minä olen heille puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Ja vielä nyt pitää peltoja ostettaman tässä maassa, josta te sanotte: sen pitää autiona oleman, niin ettei siinä väkeä eli karjaa oleman pidä, ja pitää Kaldealaisten käsiin annettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Kuitenkin pitää vielä nyt peltoja ostettaman rahalla ja kirjoituksella, niin sinetillä vahvistettaman ja todistajilla: Benjaminin maalla, ja ympäri Jerusalemia, ja Juudan kaupungeissa, jotka vuorilla ovat sillä minä tahdon kääntää heidän vankiutensa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Ja Herran sana tapahtui toisen kerran Jeremialle, kuin hän oli vielä suljettu vankihuoneen pihassa, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Näin sanoo Herra, joka sen tekee, Herra, joka sen päättää ja toimittaa, Herra on hänen nimensä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Huuda minua, niin minä tahdon kuulla sinua, ja tahdon ilmoittaa sinulle suuria ja voimallisia asioita, niitä, joita et tiedäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Sillä näin sanoo Herra Israelin Jumala tämän kaupungin huoneista ja Juudan kuningasten huoneista, jotka ovat maahan kukistetut, niistä tehtää multaseiniä varjelukseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Ja niistä, jotka tänne ovat tulleet sotimaan Kaldealaisia vastaan, että he täyttäisivät ne ihmisten ruumiilla, jotka minä minun vihassani ja julmuudessani lyövä olen; sillä minä olen kätkenyt minun kasvoni tämän kaupungin edestä, kaiken heidän pahuutensa tähden:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Katso, minä tahdon sitoa heidän haavansa ja tehdä heidät terveeksi, ja tahdon kuulla heidän rukouksensa rauhasta ja uskollisuudesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Sillä minä tahdon kääntää Juudan vankiuden ja Israelin vankiuden, ja rakennan heidät niinkuin alusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Ja puhdistan heidät kaikesta pahasta teostansa, joilla he ovat rikkoneet minua vastaan, ja tahdon antaa heille anteeksi kaiken pahan teon, joilla he ovat rikkoneet ja harhailleet minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Ja se on oleva minulle ilonimeksi, ylistykseksi ja kunniaksi kaikkein pakanain seassa maan päällä, kuin he saavat kuulla kaiken sen hyvän, minkä minä heille teen; ja heidän pitää peljästymän ja hämmästymän kaikkea sitä hyvää ja kaikkea sitä rauhaa, jonka minä heille antaa tahdon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Näin sanoo Herra: tässä paikassa, josta te sanotte: se on autio, ettei ihmisiä eikä karjaa Juudan kaupungeissa ja kaduilla Jerusalemissa ole (jotka niin hävitetyt ovat, ettei väkeä eikä asuvaisia, ei myös karjaa siellä ole,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Pitää vielä nyt kuultaman riemun ja ilon ääni, yljän ääni ja morsiamen ääni, ja niiden ääni jotka sanovat: kiittäkäät Herraa Zebaotia, että Herra on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti, ja niidenkin, jotka kiitosuhria Herran huoneeseen kantavat; sillä minä käännän maan vankiuden, niinkuin alusta, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Näin sanoo Herra Zebaot: tässä paikassa, joka autiona on, niin ettei ihmisiä eikä karjaa siinä ole, ja kaikissa hänen kaupungeissansa, pitää vielä nyt paimenten huoneet oleman, jotka ruokkivat laumoja;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Sekä kaupungeissa, jotka vuorilla ovat, ja laaksokaupungeissa, jotka Etelämaassa ovat, Benjaminin maalla ja Jerusalemin ympärillä, ja Juudan kaupungeissa, sieltä pitää vielä menemän ulos ja sisälle luetut laumat, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Katso, aika tulee, sanoo Herra, että minä tahdon sen armollisen sanan herättää, jonka minä olen Israelin huoneelle puhunut, ja Juudan huoneelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Niinä päivinä ja sillä ajalla tahdon minä antaa Daavidille kasvaa vanhurskauden vesan, ja hän on toimittava oikeuden ja vanhurskauden maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Sillä ajalla pitää Juuda autetuksi tuleman, ja Jerusalem levossa asuman, ja häntä kutsutaan: Herra, meidän vanhurskautemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Sillä näin sanoo Herra: ei pidä Daavidilta puuttuman mies, joka istuu Israelin huoneen istuimella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Ei myös pidä koskaan edestäni puuttuman pappeja ja Leviläisiä, jotka polttouhria uhraavat ja ruokauhria sytyttävät, ja uhreja joka aika teurastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Herran sana tapahtui Jeremialle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Näin sanoo Herra: jos te taidatte lakkauttaa minun liittoni päivän ja yön kanssa, ja ettei päivä ja yö ole ajallansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'niin ei myös minun liittoni Daavidin minun palveliani kanssa, pidä miksikään oleman, ettei hänellä enää ole poikaa kuninkaaksi hänen istuimellansa, ja Leviläisten ja pappein, minun palveliaini kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Niinkuin ei taivaan sotaväkeä taideta lukea eikä meren santaa mitata, juuri niin tahdon minä palveliani Daavidin siemenen enentää ja Leviläiset, jotka minua palvelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Ja Herran sana tapahtui Jeremialle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Etkös ole nähnyt, mitä tämä kansa puhuu ja sanoo: Herra on hyljännyt ne kaksi sukukuntaa, jotka hän valinnut oli; ja he häpäisevät minun kansaani, niinkuin ei he enään minun kansani heidän edessään olisikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Näin sanoo Herra: jos en minä pidä liittoani päivän ja yön kanssa, ja järjestystäni taivaan ja maan kanssa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Niin tahdon myös hyljätä Jaakobin ja Daavidin minun palveliaini siemenen, niin etten minä ota niitä hänen siemenestänsä, jotka pitää vallitseman Abrahamin, Isaakin ja Jakobin siementä; sillä minä tahdon kääntää heidän vankiutensa ja armahtaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Tämä on sana, joka tapahtui Jeremialle Herralta, kun Nebukadnetsar, Babelin kuningas, ja kaikki hänen sotajoukkonsa, ja kaikki valtakunnat maan päällä, jotka hänen vallassansa olivat, ja kaikki kansat sotivat Jerusalemia ja kaikkia hänen kaupungeitansa vastaan; ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Näin sanoo Herra, Israelin Jumala: mene ja puhu Zedekian, Juudan kuninkaan kanssa, ja sano hänelle: näin sanoo Herra: katso, minä annan tämän kaupungin Babelin kuninkaan käsiin, ja hänen pitää se tulella polttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Ja ei sinun pääsemän hänen kädestänsä, vaan totisesti käsitettämän ja hänen käteensä annettaman, niin että sinun pitää silmilläs Babelin kuninkaan silmät näkemän, ja hän on suusta suuhun sinua puhutteleva, ja sinä olet menevä Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Mutta kuule siis sinä, Zedekia, Juudan kuningas, Herran sanaa: näin sanoo Herra sinusta: ei sinun pidä miekalla kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Sinun pitää kuoleman rauhassa, ja niinkuin sinun isilles, jotka sinun edelläs ovat kuninkaat olleet, on poltettu, niin pitää myös sinulle poltettaman, ja sinua pitää itkettämän: voi herra! sillä minä olen sen sanonut, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Ja propheta Jeremia puhui kaikki nämä sanat Zedekialle, Juudan kuninkaalle Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Kuin Babelin kuninkaan sotajoukko jo soti Jerusalemia vastaan, ja Juudan jääneitä kaupungeita vastaan, Lakista ja Asekaa vastaan; sillä nämät vahvat kaupungit olivat vielä Juudan kaupungeista jääneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Tämä on sana, joka tapahtui Herralta Jeremialle, sitten kun kuningas Zedekia oli tehnyt liiton kaiken kansan kanssa, joka Jerusalemissa oli, ja luvannut kuuluttaa heille vapautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Niin että jokaisen piti päästämän orjansa, joko se oli miehen eli vaimonpuoli, jotka Hebrealaiset olivat, niin ettei Juudalaisen pitänyt oleman veljensä orjana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Silloin kaikki ruhtinaat ja kaikki kansa, joka siihen liittoon oli mielistynyt, olivat hänelle kuuliaiset, että jokaisen piti päästämän sekä mies- että vaimo-orjansa vapaaksi, ja ei enään pitämän heitä orjanansa, ja he päästivät heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Mutta vähää jälkeen käänsivät he itsensä, ja ottivat orjat miehen- ja vaimonpuolista taas tykönsä, jotka he olivat vapaaksi päästäneet, ja vaativat heitä taas orjaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Silloin tapahtui Herran sana Jeremialle Herralta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Näin sanoo Herra, Israelin Jumala: minä olen tehnyt liiton teidän isäinne kanssa, kun minä vein heidät Egyptin maalta orjuuden huoneista, ja sanoin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Kun seitsemän vuotta ovat kuluneet, pitää jokaisen teistä päästämän veljensä, joka Hebrealainen on ja on itsensä sinulle myynyt, ja on jo kuusi vuotta sinua palvellut; ja sinun pitää hänen vapaaksi päästämän. Mutta ei teidän isänne totelleet minua, eikä kallistaneet siihen korviansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Niin te olette nyt tänäpänä kääntäneet teitänne ja tehneet, mitä minulle kelpaa, että te olette antaneet kuuluttaa vapautta, jokainen lähimmäisellensä, ja olette siitä tehneet liiton minun edessäni siinä huoneessa, joka minun nimelläni nimitetty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Mutta te olette taas siitä poikenneet, ja saastuttaneet minun nimeni, että jokainen on taas ottanut sekä mies- että vaimo-orjansa, jotka te olitte vapaaksi tehneet, että heidän piti oleman itse omansa, ja vaaditte heitä taas orjaksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Sentähden sanoo Herra näin: ettette kuulleet minua, että teidän piti kuuluttaman vapautta, jokainen veljellensä ja lähimmäisellensä; katso, niin minä kuulutan teille vapauden miekkaan, ruttoon ja nälkään, ja panen teidät kulkiaksi kaikissa valtakunnissa maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Ja jotka minun liitostani harhailevat, eikä pidä liiton sanoja, jonka he minun edessäni tehneet ovat, niin minä teen niinkuin sille vasikalle, jonka kahdeksi kappaleeksi hakkasivat, ja kävivät molempain kappalten välitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Juudan pääruhtinaille, Jerusalemin päämiehille, kamaripalvelioille, papeille ja kaikelle maan kansalle, jotka vasikan kappalten välitse käyneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Ja tahdon antaa heitä heidän vihollistensa käsiin ja niiden käsiin, jotka heidän henkeänsä väijyvät, niin että heidän ruumiinsa pitää tuleman taivaan linnuille ja maan pedoille ruaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Ja Zedekian, Juudan kuninkaan, ja hänen pääruhtinaansa annan minä vihollisten käsiin, ja niiden käsiin, jotka heidän henkeänsä väijyvät, ja Babelin kuninkaan sotajoukon käsiin, joka nyt teidän tyköänne on mennyt pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Katso, minä käsken heitä, sanoo Herra, ja annan taas tulla tämän kaupungin eteen, ja heidän pitää sotiman sitä vastaan, ja voittaman sen, ja tulella polttaman, ja minä hävitän Juudan kaupungit, niin ettei kenkään niissä pidä enään asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Tämä on se sana, joka Herralta tapahtui Jeremialle, Jojakimin Josian pojan, Juudan kuninkaan, aikana, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Mene Rekabilaisten huoneeseen, ja puhu heidän kanssansa, ja vie heitä Herran huoneeseen, yhteen kammioon, ja anna heille viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Niin minä otin Jasanin Jeremian pojan, Habatsinin pojan, sekä hänen veljensä ja kaikki hänen poikansa, ja koko Rekabilaisten huoneen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Ja vein heidät Herran huoneeseen, Hananin lasten, Jigdalian pojan, Jumalan miehen kammioon, joka päämiesten kammion tykönä on, ylempänä Maasejan Sallumin pojan, ovenvartian kammiota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Ja minä panin Rekabilaisten huoneen lasten eteen kannut ja maljat täyteen viinaa, ja sanoin heille: juokaat viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Mutta he vastasivat: me emme juo viinaa; sillä meidän isämme Jonadab, Rekabin poika on käskenyt meitä ja sanonut: te ja teidän lapsenne ei pidä ikänä viinaa juoman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Ja ei huonetta rakentaman, ei jyviä kylvämän, ei viinapuuta istuttaman eikä pitämän; vaan pitää asuman majoissa kaikkena teidän elinaikananne, että te kauvan eläisitte maassa, jossa te muukalaiset olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Ja me olemme kuuliaiset meidän isämme Jonadabin Rekabin pojan äänelle kaikissa, mitä hän on meille käskenyt, niin ettemme viinaa juo kaikkena meidän elinaikanamme, me ja meidän emäntämme, poikamme ja tyttäremme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Ja emme rakenna huonetta asuaksemme; ja ei meillä ole viinamäkiä eikä peltoja, eli jyviä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Vaan asumme majoissa, ja olemme kuuliaiset, ja teemme kaikki niinkuin meidän isämme Jonadab on meille käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Mutta kun Nebukadnetsar, Babelin kuningas, meni tänne maahan ylös, sanoimme me: tulkaat, käykäämme Jerusalemiin Kaldealaisten ja Syrialaisten sotajoukon edestä; ja niin me olemme sitte olleet tässä Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Silloin tapahtui Herran sana Jeremialle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Näin sanoo Herra Zebaot, Israelin Jumala: mene ja sano Juudan miehille ja Jerusalemin asuvaisille: ettekö te tahdo itseänne parantaa, niin että te tottelette minun sanaani? sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Jonadabin Rekabin pojan sanat, jotka hän oli käskenyt lapsillensa, ettei heidän pitänyt viinaa juoman, ettei he tähän päivään asti juo viinaa, että he isänsä käskyille kuuliaiset olisivat. Mutta minä olen antanut aikaisin teille sanoa, kuitenkin ette kuule minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Niin olen minä myös lähettänyt varhain ja usein tykönne kaikki minun palveliani prophetat, ja antanut sanoa: kääntäkää teistä jokainen itsensä pahasta menostansa, ja parantakaat teidän elämänne, ja älkäät seuratko muita jumalia, palvellaksenne heitä; niin te saatte olla maassa, jonka minä teille ja teidän isillenne antanut olen; mutta ette tahtoneet kallistaa korvianne siihen,, ettekä kuulleet minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Jonadabin Rekabin pojan lapset ovat pitäneet isänsä käskyn, jonka hän heille oli käskenyt;, mutta tämä kansa ei kuule minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Sentähden näin sanoo Herra Jumala Zebaot, Israelin Jumala: katso, minä annan tulla Juudan ja kaikkein Jerusalemin asuvaisten päälle kaiken sen onnettomuuden, jonka minä heitä vastaan olen puhunut, että minä olen heille puhunut, ja ei he tahdo kuulla: minä olen huutanut, mutta ei he tahdo minua vastata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Ja Rekabilaisten huoneelle sanoi Jeremia: näin sanoo Herra Zebaot, Israelin Jumala: että te teidän isänne Jonadabin käskylle olitte kuuliaiset, ja piditte kaikki hänen käskynsä, ja teitte kaikki, mitä hän teille oli käskenyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Sentähden sanoo Herra Zebaot, Israelin Jumala näin: ei Jonadabilta Rekabin pojalta pidä ikinä puuttuman mies, joka alati minun edessäni seisoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Neljäntenä Jojakimin Josian pojan, Juudan kuninkaan vuonna, tapahtui tämä sana Herralta Jeremialle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Ota kirja ja kirjoita siihen kaikki se puhe, jonka minä sinulle olen puhunut Israelista, Juudasta ja kaikesta kansasta, siitä ajasta kuin minä sinulle olen puhunut, Joosian ajasta, niin tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Jos mitämaks Juudan huone, kuin he kuulevat kaiken sen onnettomuuden, joka minun mielessäni on heille tehdä, on itsensä kääntävä, jokainen pahasta menostansa, että minä antaisin anteeksi heidän pahat tekonsa ja rikoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Silloin Jeremia kutsui Barukin, Nerijan pojan, ja Baruk kirjoitti kirjaan Jeremian suusta kaikki Herran sanat, jotka hän hänelle oli puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Ja Jeremia käski Barukia ja sanoi: minä olen vangittu, niin etten saa mennä Herran huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Mutta mene sinä sinne ja lue kirja, johon sinä Herran sanat minun suustani kirjoittanut olet, kansan korvain edessä Herran huoneessa, paastopäivänä; ja sinun pitää myös ne lukeman koko Juudan korvain edessä, jotka heidän kaupungeistansa tulleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Jos he mitämaks nöyryyttävät itsensä rukouksella Herran edessä, ja kääntyvät jokainen pahasta menostansa; sillä viha ja julmuus on suuri, jonka Herra on tätä kansaa vastaan puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Ja Baruk Nerijan poika teki kaikki, mitä propheta Jeremia oli hänelle käskenyt, ja luki ja luki kirjasta Herran sanat kirjasta Herran huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Mutta tapahtui Jojakimin Josian pojan, Juudan kuninkaan, viidentenä vuonna ja yhdeksäntenä kuukautena, että paasto kuulutettiin Herran edessä kaikelle kansalle Jerusalemissa, ja kaikelle kansalle, joka Juudan kaupungeista tuli Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Ja Baruk luki kirjasta Jeremian sanat Herran huoneessa, Gemarian, Saphanin pojan kirjoittajan kammiossa, ylemmäisessä pihassa, Herran huoneen uuden ovein edessä, kaiken kansan kuullen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Kuin Mikaja Gemarian poika, Saphanin pojan, kaikki Herran sanat kirjasta oli kuullut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Meni hän alas kuninkaan huoneeseen, kirjoittajan kammioon, ja katso, siellä istuivat kaikki pääruhtinaat, Elisama kirjoittaja, Delaja Semajan poika, Elnatan Akborin poika, Gemaria Saphanin poika, ja Zedekia Hannian poika, ja päämiehet kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Ja Mikaja sanoi heille kaikki ne sanat, jotka hän oli kuullut, kuin Baruk luki kirjasta kansan korvain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Silloin lähettivät kaikki pääruhtinaat Juudin Netanian pojan, Selemian pojan, Kusin pojan, Barukin perään, ja käskivät hänelle sanoa: ota myötäs kirja, josta sinä kansan edessä luit, ja tule tänne. Ja Baruk, Nerijan poika otti kirjan myötänsä ja tuli heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Ja he sanoivat hänelle: istu nyt ja lue, että me saisimme kuulla; ja Baruk luki heidän korvainsa kuullen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Ja kuin he kaikki sanat olivat kuulleet, peljästyivät he toinen toisensa kanssa, ja sanoivat Barukille: me tahdomme kaiketi ilmoittaa kuninkaalle kaikki nämät sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Ja he kysyivät Barukilta, sanoen: sanos meille, kuinka sinä olet kaikki nämät sanat kirjoittanut hänen suustansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baruk sanoi heille: hän luki minun edessäni kaikki nämät sanat suullansa, ja minä kirjoitin ne pläkillä kirjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Silloin sanoivat pääruhtinaat Barukille: mene ja lymytä itses Jeremian kanssa, niin ettei kenkään tiedä, kussa te olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Ja menivät kuninkaan eteen esihuoneesen, ja antoivat kirjan jäädä kirjoittajan Elisaman makaushuoneesen, ja sanoivat kuninkaan edessä kaikki nämät sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Niin kuningas lähetti Juudin kirjaa noutamaan, ja hän otti sen Elisaman kirjoittajakammiosta; ja Juudi luki sen kuninkaan edessä ja kaikkein pääruhtinasten, jotka seisoivat kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Mutta kuningas istui talvihuoneessa yhdeksäntenä kuukautena, ja tuli paloi totossa hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Kuin Juudi kolme eli neljä kappaletta oli lukenut, leikkasi hän sen rikki kynäveitsellä ja heitti tuleen, joka totossa oli, siihenasti että kirja peräti paloi tulessa, joka totossa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Ja ei kenkään peljästynyt eikä vaatteitansa reväissyt rikki, ei kuningas eikä hänen palveliansa, jotka kuitenkin kaikki nämät sanat olivat kuulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Vaikka Elnatan, Delaja ja Gemaria rukoilivat kuningasta, ettei hän olisi polttanut kirjaa; ei hän kuitenkaan heitä totellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Päälliseksi käski kuningas Jerahmeelin Hammelekin pojan, Serajan Asrielin pojan, ja Selamian Abdeelin pojan, käsittämään Barukia kirjoittajaa ja Jeremiaa prophetaa; mutta Herra oli heidät kätkenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Silloin tapahtui Herran sana Jeremialle, sittekuin kuningas oli polttanut kirjan ja ne sanat, jotka Baruk Jeremian suusta oli kirjoittanut, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Ota sinulles taas toinen kirja ja kirjoita siihen kaikki entiset sanat, jotka ensimäisessäkin kirjassa olivat, jonka Jojakim, Juudan kuningas, on polttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Ja sano Jojakimille, Juudan kuninkaalle: näin sanoo Herra: sinä olet polttanut sen kirjan ja sanonut; miksi sinä siihen olet kirjoittanut ja sanonut, että Babelin kuningas on kaiketi tuleva ja hävittävä tämän maan, ja tekevä niin, ettei ihmistä eikä karjaa enään siinä pidä oleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Sentähden sanoo Herra Jojakimista, Juudan kuninkaasta, ei pidä yhtään hänen siemenestänsä istuman Davidin istuimella, ja hänen ruumiinsa pitää heitettämän ulos, makaamaan helteessä päivällä ja vilussa yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Ja minä tahdon rangaista häntä ja hänen siementänsä, ja hänen palvelioitansa heidän pahain tekoinsa tähden: ja minä annan tulla heidän päällensä, ja Jerusalemin asuvaisten päälle, ja Juudan miesten päälle, kaiken onnettomuuden, jonka minä heille olen puhunut; ja ei he kuitenkaan tahtoneet kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Niin Jeremia otti toisen kirjan ja antoi Barukille Nerijan pojalle, kirjoittajalle. Ja hän kirjoitti siihen Jeremian suusta kaikki ne sanat, jotka entisessäkin kirjassa olivat, jonka Jojakim, Juudan kuningas, oli tulessa polttanut; ja siihen oli vielä paljon enempi senkaltaisia sanoja lisätty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Ja Zedekia Josian poika tuli kuninkaaksi Konian Jojakimin pojan siaan; sillä Nebukadnetsar, Babelin kuningas, teki hänen Juudan maan kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Mutta hän ja hänen palveliansa ja maan kansa ei totelleet Herran sanaa, jonka hän propheta Jeremian kautta puhui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Kuitenkin lähetti kuningas Zedekia Jukalin Selamjan pojan, ja Zephanian Maasejan pojan, papin, propheta Jeremian tykö sanomaan: rukoile meidän edestämme Herraa meidän Jumalaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Sillä Jeremia kävi ulos ja sisälle kansan seassa, ja ei kenkään pannut häntä vankiuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Niin oli Pharaon sotajoukko lähtenyt Egyptistä; ja Kaldealaiset, jotka olivat Jerusalemin piirittäneet, kuulivat heistä sanoman, ja läksivät pois Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Ja Herran sana tapahtui propheta Jeremialle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Näin sanoo Herra, Israelin Jumala: näin sanokaat Juudan kuninkaalle, joka teidät on minun tyköni lähettänyt kysymään minulta: katso, Pharaon joukko, joka teidän avuksenne on lähtenyt, pitää jälleen menemän kotiansa Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Ja Kaldealaisten pitää palajaman ja sotiman tätä kaupunkia vastaan, ja voittaman sen, ja polttaman sen tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Sentähden sanoo Herra näin: älkäät pettäkö teidän sielujanne, ajatellen: Kaldealaiset menevät peräti pois meidän tyköämme, sillä ei heidän pidä menemän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Ja vaikka te vielä löisitte koko Kaldealaisten sotajoukon, jotka teitä vastaan sotivat, ja muutamat heistä saisivat haavoja; niin pitäis heidän vielä sittenkin kunkin majastansa nouseman, ja polttaman tämän kaupungin tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Kuin Kaldealaisten sotajoukko oli lähtenyt Jerusalemista, Pharaon sotajoukon tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Meni Jeremia ulos Jerusalemista, ja tahtoi mennä Benjaminin maalle, ratkaisemaan ja kirvottamaan itsiänsä siellä kansan seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Ja kuin hän tuli Benjaminin porttiin, niin siellä oli oven vartion päämies, nimeltä Jirja Selemjan poika, Hananian pojan; se tarttui propheta Jeremiaan, ja sanoi: sinä tahdot mennä Kaldealaisten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremia sanoi: ei se ole tosi, en minä mene Kaldealaisten tykö. Mutta ei Jirja tahtonut häntä kuulla, vaan otti Jeremian kiinni ja vei hänen pääruhtinasten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Ja pääruhtinaat olivat Jeremialle vihaiset, ja antoivat lyödä häntä, ja heittivät hänen vankiuteen Jonatanin, kirjoittajan, huoneesen; sillä sen he panivat vankihuoneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Niin meni Jeremia luolaan ja vankiuteen, ja oli siellä kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Ja kuningas Zedekia lähetti noutamaan häntä, ja kysyi salaa häneltä huoneessansa ja sanoi: onko nyt joku sana ilmaantunut Herralta? Jeremia sanoi: on, ja sanoi: sinä pitää annettaman Babelin kuninkaan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Ja Jeremia sanoi kuningas Zedekialle: mitä minä olen rikkonut sinua, palvelioitas ja tätä kansaa vastaan, että te minun vankiuteen olette heittäneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Kussa nyt ovat teidän prophetanne, jotka teille ennustivat ja sanoivat: ei Babelin kuningas tule teidän päällenne, eikä tämän maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Ja nyt, herrani kuningas, kuule minua, ja anna minun rukoukseni tulla sinulta kuulluksi, ja älä minua taas lähetä Jonatanin, kirjoittajan, huoneesen, etten minä siellä kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Silloin käski kuningas Zedekia, että Jeremia piti tallella pidettämän pihassa vankihuoneen edessä, ja käski hänelle antaa päiväksi osan leipää Leipojan kujalta, siihenasti kuin kaikki leivät kaupungista kuluneeksi tulivat. Niin Jeremia siis oli vankihuoneen pihassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Mutta Saphatja Mattanin poika ja Gedalia Pashurin poika, ja Jukal Selamjan poika, ja Pashur Malakian poika kuulivat ne sanat, jotka Jeremia puhui kaikelle kansalle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Näin sanoo Herra: joka pysyy tässä kaupungissa, hänen pitää kuoleman miekkaan, nälkään ja ruttoon; mutta joka menee Kaldealaisten tykö, hän jää elämään, ja pitää henkensä niinkuin saaliin, ja saa elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Sillä näin sanoo Herra: tämä kaupunki pitää totisesti annettaman Babelin kuninkaan sotajoukolle, jotka sen voittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Silloin sanoivat pääruhtinaat kuninkaalle: anna siis tappaa tämä mies; sillä tällä tavalla hän peljättää sen sotaväen, joka vielä on jäljellä tässä kaupungissa, niin myös kaiken kansan, että hän näitä sanoja heille sanoo; sillä ei se mies etsi kansan parasta, vaan vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Niin kuningas Zedekia sanoi: katso, hän on teidän käsissänne; sillä ei kuningas voi mitään teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Niin he ottivat Jeremian ja heittivät Malkian Hammelekin pojan luolaan, joka pihassa vankihuoneen edessä oli, ja laskivat Jeremian alas köydellä luolaan, kussa ei vettä ollut, vaan lokaa; ja Jeremia vajosi lokaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Kuin Ebedmelek Etiopialainen, kuninkaan huoneen kamaripalvelia, kuuli Jeremian luolaan heitetyksi, ja kuningas istui Benjaminin portissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Niin Ebedmelek meni kuninkaan huoneesta ja puhui kuninkaalle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Herrani kuningas, ne miehet tekevät propheta Jeremialle pahoin, että he ovat hänen luolaan heittäneet, kussa hänen täytyy nälkään kuolla, sillä ei kaupungissa ole enään leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Silloin käski kuningas Ebedmelekiä Etiopialaista ja sanoi: ota kolmekymmentä miestä näistä kanssas, ja ota propheta Jeremia ylös luolasta ennenkuin hän kuolee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Ja Ebedmelek otti miehet kanssansa, ja meni kuninkaan huoneesen, kaluhuoneen alle, ja otti sieltä vanhoja rikkinäisiä vaateryysyjä, ja laski ne köydellä Jeremian tykö luolaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Ja Ebedmelek Etiopialainen sanoi Jeremialle: pane nämät vanhat rikkinäiset ryysyt käsivartes alle köysien alle; ja Jeremia teki niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Ja he vetivät Jeremian ylös luolasta köydellä; ja niin Jeremia oli pihassa vankihuoneen edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Ja kuningas Zedekia lähetti noutamaan propheta Jeremiaa tykönsä, kolmanteen Herran huoneen läpikäytävään; ja kuningas sanoi Jeremialle: minä tahdon sinulta jotain kysyä, älä mitään salaa minulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Jeremia sanoi Zedekialle: jos minä sinulle jotain sanon, niin sinä tosin tapat minun, ja jos minä sinua neuvon, niin et sinä tottele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Niin kuningas Zedekia vannoi Jeremialle salaa ja sanoi: niin totta kuin Herra elää, joka meidän sielumme on tehnyt, en minä sinua tapa, enkä anna sinua niiden miesten käsiin, jotka sinun henkeäs väijyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Ja Jeremia sanoi Zedekialle: näin sanoo Herra Jumala Zebaot, Israelin Jumala: jos sinä menet Babelin kuninkaan pääruhtinasten tykö, niin sinä jäät henkiin, ja ei tätä kaupunkia pidä tulella poltettaman; vaan sinä ja sinun huonees jää elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mutta jollet sinä mene Babelin kuninkaan pääruhtinasten tykö, niin tämä kaupunki annetaan Kaldealaisten käsiin, ja heidän pitää sen polttaman tulella: ja et sinäkään pääse heidän käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Kuningas Zedekia sanoi Jeremialle: minä pelkään annettavani Juudalaisten käsiin, jotka ovat Kaldealaisten tykö menneet, niin että he pilkkaavat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Jeremia sanoi: ei sinua anneta; kuule siis Herran ääntä, jonka minä sinulle sanon, niin sinä menestyt ja jäät elämään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Mutta jollet tahdo mennä, niin on tämä se sana, jonka Herra on minulle osoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Katso, kaikki vaimot, jotka vielä jäljellä ovat Juudan kuninkaan huoneessa, viedään ulos Babelin kuninkaan ruhtinasten tykö; niiden pitää silloin sanoman: voi! sinun lohduttajas ovat pettäneet ja vietelleet sinun, ja vieneet sinun alas lokaan, ja menneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Ja pitää vietämän kaikki sinun emäntäs ja lapses ulos Kaldealaisten tykö ja ei sinun itseskään pidä taitaman päästä heidän käsistänsä; vaan sinä pitää Babelin kuninkaalta käsitettämän, ja tämä kaupunki pitää tulella poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Ja Zedekia sanoi Jeremialle: katso, ettei kenkään saa tietää näitä sanoja, niin ei sinua tapeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Ja jos ruhtinaat saavat tietää, että minä olen puhunut sinun kanssas, ja tulevat sinun tykös, ja sanovat: sanos nyt meille, mitä sinä olet kuninkaan kanssa puhunut: älä meiltä sitä salaa, niin emme sinua tapa, ja mitä kuningas on puhunut sinun kanssas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Niin sano heille: minä olen rukoillut kuningasta, ettei hänen pitäisi antaman minua taas tulla Jonatanin huoneesen, etten minä siellä kuolisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Silloin kaikki ruhtinaat tulivat Jeremian tykö, ja kysyivät häneltä. Ja hän sanoi heille niinkuin kuningas oli hänen käskenyt. Niin he vaikenivat ja jättivät hänen, ettei he mitään häneltä saaneet tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Ja Jeremia oli pihassa vankihuoneen edessä, aina siihen päivään asti kuin Jerusalem voitettiin. Ja se tapahtui, että Jerusalem voitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Yhdeksäntenä Zedekian, Juudan kuninkaan vuotena, kymmenentenä kuukautena, tuli Nebukadnetsar, Babelin kuningas, ja kaikki hänen sotajoukkonsa Jerusalemin eteen ja piirittivät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Ja Zedekian ensimäisenä vuotena toistakymmentä, yhdeksäntenä päivänä neljäntenä kuukautena, kukistettiin kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Ja kaikki Babelin kuninkaan ruhtinaat menivät sisälle, ja pysähtyivät keskimäiseen porttiin, Nergalsaretser, Samgarnebo, Sarsekim kamaripalveliain päämies, Nergalsaretser magilaisten päämies ja kaikki muut Babelin kuninkaan ruhtinaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Ja tapahtui, että kuin Zedekia, Juudan kuningas, ja hänen sotaväkensä heidät näkivät, pakenivat he yöllä kaupungista, kuninkaan yrttitarhan tietä, portista, joka oli kahden muurin välillä, ja menivät korven tietä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Mutta Kaldealaisten sotajoukko ajoi heitä takaa, ja käsitti Zedekian Jerikon kedolla, otti hänen ja vei Nebukadnetsarin, Babelin kuninkaan, tykö Riblatiin, joka on Hamatin maalla; ja hän tuomitsi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Ja Babelin kuningas antoi tappaa Zedekian lapset hänen nähtensä Riblatissa; ja kaikki Juudan ruhtinaat antoi Babelin kuningas tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Ja antoi puhkaista ulos Zedekian silmät, ja sitoa hänen kaksilla vaskikahleilla, viedäksensä häntä Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Ja Kaldealaiset polttivat sekä kuninkaan huoneen että asuvaisten huoneet, ja jaottivat Jerusalemin muurit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Mutta mitä jäljellä oli kaupungissa kansasta, ja ne, jotka muutoin olivat hänen allensa itsensä antaneet, ja jääneen kansan, vei Nebusaradan, huovinhaltia, Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Mutta muutamat köyhästä väestä, joilla ei mitään ollut, antoi Nebusaradan, huovinhaltia, jäädä Juudan maalle, ja antoi heille viinamäkiä ja peltoja sinä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Mutta Nebukadnetsar, Babelin kuningas, oli käskenyt Nebusaradania, huovinhaltiaa, Jeremiasta ja sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Ota häntä ja katso hänen parastansa, ja älä hänelle tee mitään pahaa: vaan niinkuin hän anoo sinulta, niin tee hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Silloin lähetti Nebusaradan, huovinhaltia, ja Nebusasban kamaripalveliain päämies, Nergaisaretser magilaisten päämies, ja kaikki Babelin kuninkaan ruhtinaat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'He lähettivät ja antoivat noutaa Jeremian vankihuoneen pihasta, ja antoivat hänen Gedalian Ahikamin pojan, Saphanin pojan, haltuun, että hänen piti ottaman hänen huoneesensa, ja että hän asuis läsnä kansan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Oli myös Herran sana tullut Jeremialle, kuin hän vielä oli vankina vankihuoneen pihassa, ja oli sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Mene ja sano Ebedmelekille Etiopialaiselle: näin sanoo Herra Zebaot, Israelin Jumala: katso, minä tahdon antaa minun sanani tulla tähän kaupunkiin onnettomuudeksi ja ei miksikään hyväksi, ja sinun pitää se siihen aikaan näkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Mutta sinun minä silloin vapahdan, sanoo Herra, ja en anna sinua niiden miesten käsiin, joita sinä pelkäät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Sillä minä tahdon sinua totisesti siitä auttaa, niin ettei sinun pidä miekalla lankeeman, vaan pitämän henkes niinkuin saaliin, ettäs luotit minuun, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Tämä on se sana, joka tapahtui Herralta Jeremialle, kuin Nebusaradan, huovinhaltia, päästi hänen Ramassa vallallensa; sillä hän oli sidottu kahleilla kaikkien niiden seassa, jotka Jerusalemissa ja Juudassa vangitut olivat, vietäviksi pois Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Kuin huovinhaltia oli antanut noutaa Jeremian tykönsä, sanoi hän hänelle: Herra, sinun Jumalas on puhunut tämän onnettomuuden tälle paikalle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Ja on Herra myös antanut tulla ja tehnyt niinkuin hän on sanonut; sillä te olette rikkoneet Herraa vastaan, ja ette totelleet hänen ääntänsä, sentähden on tämä teille tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Ja nyt katso, minä olen sinun tänäpänä päästänyt kahleista, joilla sinun kätes olivat sidotut. Jos sinulle kelpaa mennä minun kanssani Babeliin, niin tule, minä tahdon katsoa sinun parastas; ja jollet sinä tahdo tulla minun kanssani Babeliin, niin anna olla: katso, siellä on sinulle koko maa edessäs: kussa sinä luulet itselles hyvän olevan ja sinulle kelpaa, niin mene sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Sillä tästedes ei ole enään yhtään palausta, sentähden sinä mahdat palata Gedalian Ahikamin pojan, Saphanin pojan, tykö, jonka Babelin kuningas on pannut Juudan kaupunkein päälle, ja asu hänen tykönänsä kansan seassa, eli mene sinne, mihinkä sinulle parahin kelpaa. Ja huovinhaltia antoi hänelle evästä ja lahjoja, ja antoi hänen mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Niin tuli Jeremia Gedalian Ahikamin pojan tykö Mitspaan, ja asui hänen tykönänsä kansan seassa, joka vielä maalle jäänyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Kuin kaikki sodanpäämiehet, jotka kedolla olivat sotaväkensä kanssa, saivat kuulla, että Babelin kuningas oli pannut Gedalian Ahikamin pojan maata hallitsemaan, ja että hän oli jättänyt hänen kanssansa sekä miehiä että vaimoja, lapsia ja pienimpiä, joita ei viety Babeliin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Tulivat Gedalian tykö Mitspaan Ismael Netanjan poika, Johanan ja Jonatan Karean pojat, ja Seraja Tanhumetin poika, ja Ephain pojat Netophatista, Jesania Maakatin poika, he ja heidän miehensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Ja Gedalia Ahikamin poika, Saphanin pojan, teki heille ja heidän miehillensä valan ja sanoi: älkäät peljätkö olla Kaldealaisille alamaiset, pysykäät maassa ja olkaat Babelin kuninkaalle alamaiset, niin te menestytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Ja minä, katso, minä asun tässä Mitspassa, että minä palvelisin Kaldealaisia, jotka tulevat meidän tykömme; kootkaat te sentähden viinaa ja suvituloa ja öljyä ja pankaat teidän astioihinne, ja asukaat teidän kaupungeissanne, jotka te saaneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Niin myös kaikki Juudalaiset, jotka Moabissa olivat, ja Ammonin lasten seassa; ja Edomissa, ja kaikissa maakunnissa, kuin he kuulivat, että Babelin kuningas oli jättänyt muutamia Juudaan, ja oli pannut Gedalian Ahikamin pojan, heitä hallitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Tulivat kaikki Juudalaiset jälleen kaikista paikoista, sieltä kuhunka he olivat ajetut ulos, Juudan maahan Gedalian tykö Mitspaan, ja kokosivat aivan paljon viinaa ja suvituloa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Mutta Johanan Karean poika ynnä kaikkein sodanpäämiesten kanssa, jotka kedolla olivat olleet, tulivat Gedalian tykö Mitspaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Ja sanoivat hänelle: tiedätkös että Baalis, Ammonin lasten kuningas, on lähettänyt Ismaelin Netanjan pojan sinua tappamaan? Mutta ei Gedalia Ahikamin poika uskonut heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Silloin sanoi Johanan Karean poika Gedalialle salaa Mitspassa: minä tahdon nyt mennä ja lyödä Ismaelin Netanjan pojan kuoliaaksi, niin ettei kenenkään pidä saamaan tietää. Miksi hänen pitää lyömän sinua, että kaikki Juudalaiset, jotka sinun tykös ovat kootut, pitää hajoitettaman, ja ne, jotka vielä Juudasta jääneet ovat, hukkuman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Mutta Gedalia Ahikamin poika sanoi Johananille Karean pojalle: ei sinun pidä sitä tekemän; sillä ei se ole tosi, mitä sinä Ismaelista sanot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Mutta seitsemäntenä kuukautena tuli Ismael Netanjan poika, Elisaman pojan, kuninkaallisesta suvusta, ynnä kuninkaan päämiesten kanssa, ja kymmenen miestä hänen kanssansa, Gedalian Ahikamin pojan tykö Mitspaan; ja he söivät toinen toisensa kanssa Mitspassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Mutta Ismael Netanjan poika nousi, ja ne kymmenen miestä, jotka hänen kanssansa olivat, ja löivät Gedalian, Ahikamin pojan, Saphanin pojan, kuoliaaksi miekalla, jonka Babelin kuningas oli pannut koko maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Päälliseksi löi Ismael kaikki Juudalaiset, jotka Gedalian tykönä olivat Mitspassa, ja Kaldealaiset, jotka siellä löydettiin, ja kaikki sotamiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Toisena päivänä kuin Gedalia lyöty oli, ja ei kenkään sitä vielä tietänyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Tuli kahdeksankymmentä miestä Sikemistä, Silosta ja Samariasta, ja olivat ajelleet partansa ja reväisseet vaatteensa, ja haavoittaneet itsensä, ja toivat ruokauhrin ja suitsutuksen myötänsä, viedäksensä Herran huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Ja Ismael Netanjan poika meni Mitspasta heitä vastaan, käyskenteli ja itki. Kuin hän tuli heidän tykönsä, sanoi hän heille: teidän pitää tuleman Gedalian Ahikamin pojan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Mutta kuin he tulivat keskelle kaupunkia, tappio heidät Ismael Netanjan poika, ja ne miehet, jotka hänen kanssansa olivat, kaivon tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Mutta siinä oli seassa kymmenen miestä, jotka sanoivat Ismaelille: älä meitä tapa, meillä on tavaroita pelloissa, nisuja, ohria, öljyä ja hunajaa. Ja niin pidätti hän itsensä, ettei hän heitä heidän veljeinsä kanssa tappanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Mutta kaivo, johon Ismael kaikkein kuolleiden ruumiit heitti, jotka hän oli ynnä Gedalian kanssa tappanut, on se, jonka kuningas Assa antoi tehdä Baesaa, Israelin kuningasta varten; sen täytti Ismael Netanjan poika tapetuilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Ja kaiken kansan, joka oli jäljellä Mitspassa, kuninkaan tyttäret, ja kaiken kansan, joka oli Mitspaan jätetty, vei Ismael Netanjan poika pois vangiksi, joiden päälle Nebusaradan, huovinhaltia, oli pannut Gedalian Ahikamin pojan, ja Ismael Netanjan poika otti ne vangiksi, läksi pois ja tahtoi ylitse Ammonin lasten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Mutta kuin Johanan Karean poika, ja kaikki sodanpäämiehet, jotka hänen kanssansa olivat, saivat tietää kaiken sen pahan, minkä Ismael Netanjan poika tehnyt oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Ottivat he kaiken kansan tykönsä, ja läksivät Ismaelia Netanjan poikaa vastaan sotaan, ja saavuttivat hänen Gibeonissa suuren veden tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Kuin kaikki kansa, joka Ismaelin kanssa oli näki Johanan Karean pojan, ja kaikki sodanpäämiehet, jotka hänen kanssansa olivat, niin he iloitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Ja kaikki kansa, jonka Ismael oli vienyt Mitspasta, palasi ja antautui Johanan Karean pojan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Mutta Ismael Netanjan poika, pääsi Johanan edestä kahdeksan miehen kanssa, ja pakeni Ammonin lasten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Ja Johanan Karean poika ynnä kaikkein sodanpäämiesten kanssa, jotka hänen kanssansa olivat, ottivat kaiken jääneen kansan Mitspasta tykönsä, jonka he Ismaelilta Netanjan pojalta olivat ottaneet, sittekuin hän Gedalian Ahikamin pojan oli tappanut, väkevät sotamiehet, vaimot ja lapset, ja kamaripalveliat, jotka he Gibeonista olivat tuoneet jällensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Menivät pois ja tulivat majoille Kinhamiin, Betlehemin tykö, ja tahtoivat mennä Egyptiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Kaldealaisten edestä; sillä he pelkäsivät heitä, että Ismael Netanjan poika oli tappanut Gedalian Ahikamin pojan, jonka Babelin kuningas on pannut maata hallitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Silloin astuivat kaikki sodanpäämiehet edes, Johanan Karean poika, Jesanja Hosajan poika, ja kaikki kansa sekä pienet että suuret,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'Ja sanoivat propheta Jeremialle: annas meidän rukouksemme tulla kuulluksi sinun edessäs, ja rukoile meidän edestämme Herraa Jumalaas kaikista näistä jätetyistä; sillä meitä on harvat monesta jääneet, niinkuin sinä itse meidät näet silmilläs:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Että Herra sinun Jumalas tahtois ilmoittaa meille, kuhunka meidän vaeltaman ja mitä meidän tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Ja propheta Jeremia sanoi heille: minä tahdon kuulla teitä: katso, minä tahdon rukoilla Herraa teidän Jumalaanne, niinkuin te olette sanoneet, ja kaiken, mitä Herra teille vastaa, sen minä tahdon teille ilmoittaa, enkä tahdo mitään teiltä salata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Ja he sanoivat Jeremialle: Herra olkoon vahva ja totinen todistaja meidän vaiheellamme, jollemme me tee kaikkia, mitä Herra sinun Jumalas on meitä käskevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Olkoon hyvä eli paha, niin me tahdomme olla kuuliaiset Herran Jumalamme äänelle, jonka tykö me sinun lähetämme, että meille menestyis, koska me Herran meidän Jumalamme äänelle olemme kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Kymmenen päivän perästä tapahtui Herran sana Jeremialle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Silloin kutsui hän Johanan Karean pojan, ja kaikki sodanpäämiehet, jotka hänen kanssansa olivat, ja kaiken kansan sekä pienet että suuret,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Ja sanoi heille: näin sanoo Herra Israelin Jumala, jonka tykö te olette minun lähettäneet, että minä teidän rukouksenne kantaisin hänen eteensä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Jos te pysytte tässä maassa, niin minä tahdon rakentaa teitä ja en kukistaa: minä tahdon istuttaa teitä ja en repiä ylös; sillä minä kadun sitä pahaa, jonka minä teille tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Te saatte olla kyllä Babelin kuninkaalta rauhassa, jota te pelkäätte; ei teidän pidä häntä pelkäämän, sanoo Herra; sillä minä tahdon olla teidän tykönänne, niin että minä autan ja vapahdan teitä hänen kädestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Minä tahdon osoittaa teille laupiuden, ja armahtaa teitä, ja vien teitä taas teidän maallenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Mutta jos te sanotte: emme tahdo asua tässä maassa, ettette olisi kuuliaiset Herran teidän Jumalanne äänelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Sanoen: emme suinkaan, vaan me tahdomme mennä Egyptin maalle, ettemme kapinaa näkisi, emmekä kuulisi basunan ääntä, eli kärsisi nälkää leivän puuttumisen tähden: siellä me tahdomme olla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Kuulkaa siis nyt Herran sanaa, te jääneet Juudasta, näin sanoo Herra Zebaot, Israelin Jumala: jos te panette teidän kasvonne menemään Egyptiin, niin että te tahdotte siellä olla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Niin miekan, jota te pelkäätte, pitää sattuman teihin Egyptin maalla, ja nälän, jota te pelkäätte, pitää teitä siellä noudattaman Egyptissä, ja teidän pitää siellä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Sillä olkoon kutka tahansa, jotka kasvonsa sinne asettavat, mennäksensä Egyptiin olemaan siellä, heidän pitää kuoleman miekkaan, nälkään ja ruttoon; ja ei pidä kenenkään jäämän eli pääsemän siitä pahasta jonka minä annan tulla heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Sillä näin sanoo Herra Zebaot, Israelin Jumala; niinkuin minun vihani ja julmuuteni on tullut Jerusalemin asuvaisten päälle, niin pitää minun vihani myös tuleman teidän päällenne, jos te menette Egyptiin, että teidän pitää tuleman kiroukseksi, ihmeeksi, sadatukseksi ja häpiäksi, ja ei pidä teidän ikänä enään tätä paikkaa saaman nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Herran sana tulee teihin, te jääneet Juudasta, ettette menisi Egyptiin; sentähden se täydellisesti tietäkäät, että minä tänäpänä todistan teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Sillä te teette pahoin teidän sielullenne, että te lähetitte minun Herran teidän Jumalanne tykö, ja sanoitte: rukoile Herraa meidän Jumalaamme meidän edestämme, ja kaikki, mitä Herra meidän Jumalamme on sanova, niin ilmoita meille, ja me tahdomme sen jälkeen tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Sen minä olen tänäpänä teidän tietää antanut; mutta ette ole tahtoneet kuulla Herran teidän Jumalanne ääntä, eli kaikkia, mitä Hän minun kauttani on teille käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Niin teidän pitää nyt täydellisesti tietämän, että teidän pitää miekkaan, nälkään ja ruttoon kuoleman siinä paikassa, kuhunka te aiotte mennä asumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Kuin Jeremia oli kaikki Herran heidän Jumalansa sanat kaikelle kansalle puhunut, niinkuin Herra heidän Jumalansa hänen oli lähettänyt sanomaan heille kaikki nämä sanat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Sanoi Asaria Hosajan poika, ja Johanan Karean poika, ja kaikki ylpiät miehet Jeremialle ja puhuivat: sinä valehtelet, ei Herra meidän Jumalamme ole lähettänyt sinua eikä sanonut: ei teidän pidä menemän Egyptiin asumaan siellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Mutta Baruk Nerijan poika yllyttää sinua meitä vastaan, että me annettaisiin Kaldealaisten käsiin, tapettaa ja vietää Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Näin ei tahtonut Johanan Karean poika, ja kaikki sodanpäämiehet, ja kaikki kansa totella Herran ääntä, että he olisivat pysyneet Juudan maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Vaan Johanan Karean poika ja kaikki sodanpäämiehet ottivat tykönsä kaikki jääneet Juudasta, ne jotka kaikista kansoista sinne paenneet ja palanneet olivat asumaan Juudan maalla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Miehet ja vaimot ja lapset, niin myös kuninkaan tyttäret, ja kaikki sielut, jotka Nebusaradan, huovinhaltia, Gedalian Ahikamin pojan, Saphanin pojan, haltuun oli jättänyt, ja propheta Jeremian ja Barukin Nerijan pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Ja menivät Egyptin maalle, sillä ei he tahtoneet kuulla Herran ääntä, ja tulivat Tahpanhekseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Ja Herran sana tapahtui Jeremialle Tahpanheksessa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Ota kätees suuret kivet, ja kaiva ne maahan tiilipätsiin, joka on Pharaon huoneen oven kohdalla Tahpanheksessa, niin että Juudan miehet sen näkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Ja sano heille: näin sanoo Herra Zebaot, Israelin Jumala: katso, minä lähetän ja annan noutaa palveliani Nebukadnetsarin, Babelin kuninkaan, ja asetan hänen istuimensa näiden kivien päälle, jotka minä olen tähän maahan kaivanut; ja hän on paneva majansa sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Ja hän on tuleva ja lyövä Egyptin maata; jotka kuolemaan (aiotut ovat), ne (joutuvat) kuolemaan, ja jotka vankiuteen, ne vankiuteen, ja jotka miekkaan, ne miekkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Ja minä sytytän tulen epäjumalain huoneisiin Egyptissä, niin että hän polttaa ja vie heidät pois; ja hänen pitää puettaman itsensä Egyptin maahan, niinkuin paimen puettaa itsensä hameesensa, ja pitää menemän sieltä matkaansa rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Ja hänen pitää murskaksi lyömän Betsemeksen patsaat Egyptissä, ja polttaman Egyptin epäjumalain huoneet tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Tämä on se sana, joka Jeremialle tapahtui, kaikista Juudalaisista, jotka Egyptin maalla asuivat, jotka asuivat Migdolissa, Tahpanheksessa, Nophissa, Patroksen maalla, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Näin sanoo Herra Zebaot, Israelin Jumala: te olette nähneet kaiken sen pahan, jonka minä olen antanut tulla Jerusalemin päälle, ja kaikkein Juudan kaupunkein päälle; ja katso, tänäpänä ovat ne hävitettynä, niin ettei kenkään niissä asu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Heidän pahuutensa tähden, jonka he tekivät vihoittaen minua, ja menivät ja suitsuttivat ja palvelivat muita jumalia, joita ei he, eli te, eikä teidän isänne tunteneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Ja minä lähetin varhain ja usein teidän tykönne kaikki palveliani prophetat, ja käskin teille sanoa: älkäät tehkö senkaltaisia kauhistuksia, joita minä vihaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Mutta ei he totelleet, eikä kallistaneet korviansa kääntymään pahuudestansa, ja ei suitsuttamaan muille jumalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Sentähden syttyi myös minun vihani ja julmuuteni, ja paloi Juudan kaupunkein päällä, ja Jerusalemin katuin päällä, niin ne ovat kukistetuiksi ja autioiksi tulleet, niinkuin se tänäpänä löydetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Nyt, näin sanoo Herra Jumala Zebaot, Israelin Jumala: miksi te teette tämän suuren pahan vastaan omaa henkeänne? että teidän seassanne pitää hävitettämän sekä mies että vaimo, sekä lapset että imeväiset Juudasta, ja ei pidä yhtään teistä jäämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Että te niin vihoitatte minun kättenne töillä, ja suitsutatte muille jumalille Egyptin maalla, johon te olette menneet asumaan, että teidän pitää hävitetyksi, ja kiroukseksi ja häväistykseksi kaikkein pakanain seassa maan päällä tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Oletteko te unhottaneet isäinne onnettomuuden, Juudan kuningasten onnettomuuden, heidän emäntäinsä onnettomuuden, niin myös teidän oman onnettomuutenne, ja teidän emäntäinne onnettomuuden, joka teille on tapahtunut Juudan maalla ja Jerusalemin kaduilla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Kuitenkin ei he vielä ole tähän päivään asti itsiänsä nöyryyttäneet, ja ei myös mitään pelkää; ja ei vaella minun laissani ja säädyissäni, jotka minä teidän eteenne ja teidän isäinne eteen pannut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Sentähden sanoo Herra Zebaot, Israelin Jumala näin: katso, minä panen minun kasvoni teitä vastaan onnettomuudeksi, ja koko Juudan pitää hävitetyksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Ja minä otan jääneet Juudasta, jotka ovat kasvonsa tavoittaneet mennäksensä Egyptin maalle, asumaan siellä, ja he kaikki pitää lopetettaman, Egyptin maalla pitää heidän miekalla kaatuman ja nälällä hukkuman, sekä pienet että suuret; heidän pitää kuoleman miekalla ja nälällä, ja pitää tuleman sadatukseksi, ihmeeksi, kiroukseksi ja häväistykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Minä tahdon rangaista Egyptin maan asuvaisia miekalla, nälällä ja rutolla, niinkuin minä tein Jerusalemille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Niin ettei Juudan jääneistä ketään pidä pääsemän eikä jäämän, jotka kuitenkin sitä varten tänne Egyptin maalle asumaan tulleet ovat, että he taas Juudan maalle palajaisivat, johonka he mielellänsä jälleen asumaan tulisivat; mutta ei heidän pidä sinne palajaman, paitsi niitä, jotka täältä pakenevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Niin kaikki ne miehet vastasivat Jeremiaa, jotka kyllä tiesivät, että heidän emäntänsä muille jumalille olivat suitsuttaneet, niin myös kaikki vaimot, joita siellä suuri joukko oli, ja kaikki kansa, jotka Egyptin maalla, Patroksessa asuivat, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Sen sanan jälkeen, jonka sinä meille Herran nimeen sanot, emme tahdo sinua suinkaan kuulla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Vaan me tahdomme kaiketi tehdä kaiken sen sanan perään, joka meidän suustamme käy, ja tahdomme taivaan kuningattarelle suitsuttaa, ja hänelle juomauhria uhrata, niinkuin me ja meidän isämme, meidän kuninkaamme ja päämiehemme tehneet ovat Juudan kaupungeissa ja Jerusalemin kaduilla. Silloin meillä oli leipää kyllä, ja me olimme autuaat, ja emme nähneet onnettomuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Mutta sittekuin kuin me lakkasimme suitsuttamasta taivaan kuningattarelle, ja juomauhria hänelle uhraamasta, niin me kaikki köyhiksi tulimme ja olemme miekan ja nälän kautta hukkuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Ja vaikka me taivaan haltiattarelle suitsuttaisimme ja juomauhria uhraisimme, niin emme sitä tee ilman meidän miestemme tahtoa, kuin me hänelle leipiä leivomme ja juomauhria uhraamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Silloin Jeremia sanoi kaikelle kansalle, sekä miehille että vaimoille, ja kaikelle kansalle, joka häntä niin vastannut oli sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Sepä se on, että Herra on muistanut sen suitsuttamisen, jonka Juudan kaupungeissa ja Jerusalemin kaduilla tehneet olette, ynnä teidän isäinne, kuningastenne, päämiestenne ja kaiken maakunnan kansan kanssa, ja pani sen sydämeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Niin ettei Herra voinut teidän pahaa menoanne enään kärsiä ja niitä kauhistuksia, joita te teitte; joista myös teidän maanne on autioksi, ihmeeksi ja kiroukseksi tullut, niin ettei kenkään siinä asu, niinkuin tänäpänä nähtävä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'että te suitsutitte, ja Herraa vastaan syntiä teitte, ja ette totelleet Herran ääntä, ette myös hänen laissansa, säädyissänsä ja todistuksissansa vaeltaneet; sentähden myös tämä onnettomuus teille tapahtuu, niinkuin tänäpänä nähtävä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Ja Jeremia sanoi kaikelle kansalle ja kaikille vaimoille: kuulkaat Herran sanaa kaikki, jotka Juudasta Egyptin maassa olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Näin puhuu Herra Zebaot, Israelin Jumala, sanoen: te ja teidän vaimonne olette suullanne puhuneet ja käsillänne täyttäneet, mitä te sanoitte: meidän lupauksemme me kaiketi tahdomme pitää, jonka me taivaan kuningattarelle luvanneet olemme, että me hänelle pyhää savua suitsuttaisimme, ja juomauhria uhraisimme: te olette lupauksenne kyllä pitäneet, ja lupauksenne työllä täyttäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Niin kuulkaat siis Herran sanaa, kaikki Juudasta, jotka Egyptin maalla asutte: katso, minä vannon suuren nimeni kautta, sanoo Herra: ettei minun nimeni pidä enään jonkun ihmisen suusta Juudasta koko Egyptin maassa nimitettämän, joka sanois: niin totta kuin Herra, Herra elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Katso, minä tahdon valvoa heitä vastaan heidän pahaksensa ja en heidän hyväksensä, niin että jokainen, joka Juudasta Egyptin maalla on, pitää miekalla ja nälällä hukkuman, siihenasti että he lopetetuksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Mutta jotka miekan välttävät, niiden pitää kuitenkin Egyptin maalta Juudan maahan vähässä joukossa palajaman. Ja niin pitää kaikki jääneet Juudasta, jotka Egyptin maahan asumaan menneet olivat, ymmärtämän, kummanko sanat todeksi joutuvat, minun vai heidän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Ja tämä olkoon teille merkiksi, sanoo Herra: sillä minä tahdon teitä tässä paikassa rangaista, että tietäisitte minun sanani tulevan todeksi, teille onnettomuudeksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Näin sanoo Herra: katso, minä tahdon hyljätä Pharao Hophran, Egyptin kuninkaan, hänen vihollistensa käsiin ja niiden käsiin, jotka hänen henkeänsä väijyvät, niinkuin minä Zedekiankin, Juudan kuninkaan, hylkäsin Nebukadnetsarin, Babelin kuninkaan, hänen vihollistensa käteen, ja sen joka hänen henkeänsä väijyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Tämä on se sana, jonka propheta Jeremia puhui Barukille Nerijan pojalle, kuin hän nämät sanat kirjoitti kirjaan Jeremian suusta, neljäntenä Jojakimin Josian pojan, Juudan kuninkaan vuonna, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Näin sanoo Herra Zebaot, Israelin Jumala, sinusta Baruk:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Sinä sanoit: voi nyt minua! kuinka on Herra vaivaa minun kivulleni lisännyt; minä huokaan minuni väsyksiin, ja en löydä lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Sano hänelle näin: näin sanoo Herra: katso, mitä minä rakensin, sen minä kukistan, ja mitä minä istutin, sen minä hävitän, niin myös koko tämän maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Ja sinä etsit itselles suuria kappaleita. Älä niitä pyydä, sillä katso, minä tahdon antaa tulla onnettomuuden kaikelle lihalle, sanoo Herra; mutta sinun sielus minä tahdon sinulle niinkuin saaliin antaa joka paikassa, kuhunka sinä vaellat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Tämä on Herran sana, joka tapahtui propheta Jeremialle, pakanoita vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Egyptiä vastaan, Pharao Nekon, Egyptin kuninkaan, joukkoa vastaan, joka on Phratin virran tykönä Karkemiksessa, jonka Nebukadnetsar, Babelin kuningas, löi neljäntenä Jojakimin Josian pojan, Juudan kuninkaan, vuonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Valmistakaat kilpi ja keihäs, ja lähtekäät sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Valjastakaat hevoset, ja antakaat ratsastajat astua hevosten selkään; pankaat rautalakit päähänne, teroittakaat keihäät, pukekaat rautahame yllenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Mutta kuinka minä näen heidät epäileväiseksi ja takaperin ajetuksi, ja heidän sankarinsa lyödyksi; he pakenevat, niin etteivät he katso taaksensa, hämmästys on joka taholta, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Nopsa ei taida paeta eikä väkevä päästä: pohjaan päin Phratin virran tykönä ovat he kaatuneet ja maahan lyödyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kussa on nyt se, joka tänne menee ylös niinkuin virta? ja hänen aaltonsa nousevat kuin virrat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egypti menee ylös niinkuin virta, ja hänen aaltonsa nostavat itsensä niinkuin virrat, ja sanoo: minä tahdon mennä ylös, ja peittää maan, ja hävittää kaupungin ynnä niiden kanssa, jotka siinä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Istukaat hevosten päälle, samotkaat lentäen vaunuilla, antakaat sankarit mennä ulos, Etiopialaiset ja Lybiasta kilven kantajat, ja ampujat Lydiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Sillä tämä on Herran, Herran Zebaotin päivä, kostopäivä, että hän kostais vihollisiansa: miekan pitää syömän ja heidän verestänsä täyteen tuleman ja juopuman; sillä heidän pitää tuleman Herralle, Herralle Zebaotille teurasuhriksi pohjan maalla, Phratin virran tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Mene ylös Gileadiin ja tuo voidetta, sinä neitsy, Egyptin tytär; mutta se on turha, ettäs paljon parannusta etsit, et sinä kuitenkaan tule terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Sinun häpys on tullut tiettäväksi pakanain seassa, sinun valitustas on maa täynnänsä; sillä toinen sankari kaatuu toisen päälle, ja molemmat makaavat yhdessä ylösalaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Tämä on Herran sana, jonka hän puhui propheta Jeremialle, kuin Nebukadnetsar, Babelin kuningas, läksi matkaan lyömään Egyptin maata:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Ilmoittakaat se Egyptissä ja kuuluttakaat Migdolissa, antakaat kuulla Nophissa ja Tahpanheksessa, ja sanokaat: seiso, valmista sinus, sillä miekan pitää syömän kaikki, mitä sinun ympärilläs on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Kuinka se on, että sinun väkeväs kaatuvat maahan, ja ei taida pysyä seisoalla? sillä Herra on niin lykännyt heidät ylösalaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Hän tekee, että monta heistä kaatuvat, että yksi toisen kanssa makaa maassa ylösalaisin. Niin he sanoivat: ylös, käykäämme meidän kansamme tykö isäimme maahan jälleen, murhaajan miekan edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Sitä siellä huudettakoon; Pharao Egyptin kuningas on metelin nostanut: ei hän ole pitänyt määrättyä aikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Niin totta kuin minä elän, sanoo se Kuningas, jonka nimi on Herra Zebaot, hänen pitää tuleman niin (korkiana) kuin Tabor on vuorten seassa, ja niinkuin Karmel on meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Laita itses matkustamaan, sinä tytär, asuvainen Egyptissä; sillä Nophin pitää autioksi tuleman ja poltettaman, niin ettei kenenkään pidä siellä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Egypti on juuri kaunis vasikka; mutta teurastaja tulee kaiketi pohjoisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Ja hänen päivämiehensä, jotka siinä asuvat, ovat myös kuin syötetyt vasikat; mutta heidän pitää kumminkin palajaman, kaikki tuleman karkuriksi, ja ei taitaman pysyä; sillä heidän onnettomuutensa päivä pitää heidän päällensä tuleman, heidän rangaistuksensa aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'He tulevat havisten niinkuin kärmeet, ja tulevat sotajoukon voimalla, ja tulevat kirveillä hänen päällensä, niinkuin puiden hakkaajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Heidän pitää hävittämän hänen metsänsä, sanoo Herra, ettei pidä voitaman lukea; sillä heitä on enempi kuin heinäsirkkoja, joita ei kenkään lukea taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Egyptin tytär häpee, sillä hän on pohjoisen kansan käsiin annettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Herra Zebaot, Israelin Jumala sanoo: katso, minä tahdon rangaista Noon holhojan, ja Pharaon ja Egyptin, heidän jumalainsa ja kuningastensa kanssa, ja Pharaon kaikkein niiden kanssa, jotka häneen luottavat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Niin että minä annan heidät niiden käsiin, jotka heidän henkeänsä väijyvät, ja Nebukadnetsarin, Babelin kuninkaan käsiin, ja hänen palveliainsa käsiin; ja sitte pitää (siinä) asuttaman, niinkuin muinenkin, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Mutta sinä minun palveliani Jakob, älä mitään pelkää, ja sinä Israel, älä mitään epäile; sillä katso, minä autan sinua kaukaa, ja sinun siemenes vankiutensa maasta, niin että Jakobin pitää tuleman jälleen, ja oleman rauhassa ja levossa, ja ei pidä kenenkään häntä peljättämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Sentähden älä mitään pelkää, sinä Jakob minun palveliani, sanoo Herra, sillä minä olen sinun tykönäs; sillä minä lopetan kaikki pakanat, kuhunka minä olen sinut ajanut; mutta en minä sinua lopeta, vaan tahdon kurittaa sinua kohtuudella, ja en sinua peräti rankaisematta pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Tämä on Herran sana, joka tapahtui propheta Jeremialle Philistealaisia vastaan, ennenkuin Pharao löi Gatsan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Näin sanoo Herra: katso, vedet pitää nouseman pohjoisesta, josta pitää tuleman tulvavirta, niin että se käy ylitse maan, ja mitä sen päällä on, ja kaupungit niiden kanssa, jotka niissä asuvat: ja ihmisten pitää huutaman, kaikkein maan asuvaisten valittaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Humun tähden heidän väkevistä hevosistansa, jotka siellä juoksevat, ja heidän vaununsa töminän tähden, ja heidän ratastensa kopinan tähden; niin ettei isäin pidä ympärillensä katsoman lastensa perään, niin epäilyksissä pitää heidän oleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Sen päivän tähden, joka tulee kukistamaan kaikki Philistealaiset, ja hävittämään Tyroa ja Sidonia, ynnä kaikkein muiden heidän auttajainsa kanssa; sillä Herra on kukistava Philistealaisia, jääneitä Kaphtorin luodossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Gatsan pitää paljaspääksi joutuman, ja Askalon ynnä jääneiden kanssa heidän laaksoissansa hävitettämän; kuinka kauvan sinä itsiäs repelet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Kuinka kauvan sinä, Herran miekka, et tahdo lakata? mene jo tuppees, lepää ja ole alallas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Mutta kuinka sinä taidat lakata, että Herra on antanut sinulle käskyn Askalonia vastaan, ja asettanut sinun meren satamia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Moabia vastaan sanoo Herra Zebaot, Israelin Jumala näin: voi Neboa! sillä se on kukistettu ja on surkiana, Kirjataim on voitettu: linna on surkialla muodolla, ja on kukistettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Moabin kerskaaminen on pois, joka hänellä oli Hesbonista; sillä jotain pahaa hänelle aiotaan: (nimittäin) tulkaat, me tahdomme hävittää hänen peräti, ettei hän enään pidä kansa oleman; ja sinun Madmen pitää myös oleman hävitetyn, miekan pitää sinun perässäs tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Horonaimista kuuluu hävityksen ja suuren valituksen ääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Moab on lyöty maahan; hänen nuoret lapsensa kuuluvat huutavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Sillä he käyvät itkien tietä myöten ylös Luhitiin, ja vihollisten hävityshuuto kuullaan tietä myöten alas Horonaimista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, '(Nimittäin) rientäkäät pois, ja pelastakaat henkenne; mutta teidän pitää oleman niinkuin kanerva korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Että sinä luotit rakennuksees ja tavaroihis, pitää sinun myös tuleman voitetuksi, ja Kamoksen pitää menemän ulos vangittuna ynnä pappeinsa ja ruhtinastensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Sillä hävittäjän pitää tuleman kaikkiin kaupunkeihin, niin ettei yhtään kaupunkia pidä pääsemän; siellä pitää sekä laaksot turmeltuman, ja tasaiset kedot hävitettämän; sillä Herra on sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Antakaat Moabille sulkia; sillä hänen pitää lentäen menemän, ja hänen kaupunkinsa autioksi tuleman, niin ettei yhdenkään pidä niissä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Kirottu olkoon, joka tekee Herran työn laiskasti, ja kirottu olkoon, joka miekkansa antaa lakata verta vuodattamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Moab on nuoruudestansa ollut surutoin, ja on rahkansa päällä alallansa ollut, ja ei ole koskaan vuodatetuksi tullut yhdestä astiasta niin toiseen, eikä koskaan mennyt vankiuteen: sentähden on hänellä hänen makunsa tallella, ja hänen hajunsa ei ole muuttunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Sentähden katso, se aika tulee, sanoo Herra, että minä lähetän hänelle vieraita, jotka hänen pitää laskeman, ja tekemän hänen astiansa tyhjäksi ja rikkoman hänen leilinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Ja Moabin pitää Kamoksen tähden tuleman häpiään, niinkuin Israelin huone on Betelin tähden häpiään tullut, joihinka he luottivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kuinka te rohkeatte sanoa: me olemme sankarit ja miehuulliset sotamiehet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Vaikka Moab pitää hävitetyksi tuleman, ja hänen kaupunkinsa poljettaman, ja hänen parhaat nuoret miehensä käymän alas tapettaviksi, sanoo Kuningas, jonka nimi on Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Sillä Moabin onnettomuus on pian tuleva, ja hänen kova onnensa on kyllä kiiruhtava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Surkutelkaat siis häntä kaikki te, jotka hänen ympärillänsä asutte ja hänen nimensä tunnette, ja sanokaat: kuinka on se vahva vitsa ja se jalo sauva niin taitettu rikki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Astu alas jaloudesta ja istu kuivalle, sinä tytär, joka Dibonissa asut; sillä Moabin hävittäjän pitää tuleman ylös sinun tykös, ja turmeleman sinun linnas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Seiso tiellä ja katsele, sinä Aroerin asuvainen; kysy niiltä, jotka pakenivat ja pääsivät, ja sano: mitä on tapahtunut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Moab on häpiään joutunut, sillä hän on turmeltu; valittakaat ja huutakaat: ilmoittakaat se Arnonissa, että Moab on turmeltu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Rangaistus on tullut tasaiselle kedolle, Holoniin, Jahtsaan, Mephatiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Diboniin, Neboon, Betdiblataimiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Kirjataimiin, Betgamuliin, Betmeoniin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Keriotiin, Bostraan, ja kaikkiin Moabin maan kaupunkeihin, joko he kaukana eli läsnä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Moabin sarvi on lyöty pois, ja hänen käsivartensa on taitettu, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Juovuttakaat häntä, sillä hän on korottanut itsensä Herraa vastaan; että hän oksennuksessansa itseänsä kääntelis, ja myös pilkaksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Sillä Israel on ollut sinun häväistykses, niinkuin hän olis löytty varasten seasta. Ja että sinä senkaltaisia häntä vastaan olet puhunut, pitää sinä vietämän myös pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Te Moabin asuvaiset, jättäkäät kaupungit ja asukaat vuoren kukkuloilla, ja tehkäät niinkuin kyyhkyinen, joka pesänsä tekee luolan reunoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Me olemme kuulleet Moabin ylpeyden, että hän on juuri ylpiä, hänen korkeutensa, röyhkeytensä, öykkäämisensä ja sydämensä paisumisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Minä kyllä tunnen, sanoo Herra, hänen vihansa, ja ei hänellä ole voimaa; hän kerskaa, eikä niin taida tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Sentähden minä valitan Moabin tähden, huudan koko Moabin tähden; Kirhereksen miehiä pitää murehdittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Minä itken sinua yli Jaeserin itkun, sinä Sibman viinapuu; sinun oksas ovat kulkeneet meren ylitse ja tulleet Jaeserin mereen saakka; hävittäjä on hyökännyt sinun eloos ja viinan hakemisees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Ilo ja riemu on paennut kedolta ja Moabin maalta, ja ei pidä ensinkään viinaa enään siellä puserrettaman. Viinan polkian ei pidä enään laulaman ilovirttänsä, ilovirsi ei pidä enään ilovirsi oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Hesbonin huudon tähden hamaan Elealeen, joka kuuluu Jahtsan Zoarista, kolmevuotisesta lehmästä, Horonaimiin asti; sillä Nimrimin vedet pitää myös kuivuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Ja minä teen Moabissa lopun, sanoo Herra, ettei heidän enään pidä uhraaman kukkuloilla, ja suitsuttaman jumalillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Sentähden pauhaa minun sydämeni Moabia vastaan niinkuin huilu, ja Kirhereksen miesten päälle pauhaa minun sydämeni niinkuin huilu; he ovat paljon alkaneet, sentähden pitää heidän hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Sillä kaikki päät pitää tuleman paljaaksi ja kaikki parta ajelluksi; kaikki kädet pitää oleman revityt, ja jokaisen pitää itsensä puettaman säkkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Kaikkein kattoin päällä ja kaduilla joka paikassa Moabissa pitää itkettämän; sillä minä olen särkenyt Moabin, niin kuin kelpaamattoman astian, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Kuinka hän on turmeltu? kuinka hän valittaa, kuinka hän ripustaa päänsä ja häpee? ja Moab on tullut nauruksi ja pelvoksi kaikille ympärillä asuvaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Sillä näin sanoo Herra: katso, hän lentää pois niinkuin kotka, ja ojentaa siipensä Moabin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerijot on voitettu, ja vahvat kaupungit ovat saadut; ja Moabin sankarien sydän pitää oleman silloin niinkuin synnyttäväisen vaimon sydän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Sillä Moabin pitää turmelluksi tuleman, niin ettei hänen enään kansana oleman pidä, että hän on itsensä korottanut Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Pelko, luola ja paula tulee sinun päälles, sinä Moabin asuvainen, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Joka pääsee pelvosta, sen pitää putooman luolaan, ja joka luolasta pääsee, se pitää paulalla saataman. Silloin minä tahdon antaa Moabin päälle tulla hänen rangaistuksensa vuoden, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Jotka taposta pakenevat, pitää etsimän turvaa Hesbonissa; mutta tulen pitää käymän Hesbonista ja liekin Sihonista, joka Moabin paikat ja sotivaisen kansan nielemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Voi sinua Moab! Kamoksen kansa on kadotettu; sillä sinun poikas ja tyttäres ovat otetut ja viedyt vangiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Mutta viimeisinä aikoina tahdon minä kääntää Moabin vankiuden, sanoo Herra. Olkoon se niin sanottu nyt Moabin rangaistuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Ammonin lapsia vastaan sanoo Herra näin: eikö Israelilla lapsia ole, eli eikö hänellä perillistä ole? Miksi siis Malkom omistaa Gadin maan ja hänen kansansa asuu hänen kaupungeissansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Sentähden katso, aika tulee, sanoo Herra, että minä annan kuulla sotariekunan Ammonin lasten Rabbatin ylitse, että sen pitää yhdessä koossa autiona oleman, ja kylinensä tulella poltettaman; mutta Israelin pitää omistaman heidät, joilta he ovat omistetut olleet, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Valita, o Hesbon, sillä Ai on kukistettu; huutakaat, te Rabban kylät, ja pukekaat itsenne säkkeihin, itkekäät ja juoskaat ympäri muureja; sillä Malkom viedään vankina pois, pappeinsa ja ruhtinastensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Mitä sinä röyhkeilet laaksoistas? Sinun laaksos ovat upotetut, sinä tottelematoin tytär, joka luotat tavaroihis, (ja sanot sydämessäs:) kuka tohtii tulla minun tyköni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Katso, minä annan tulla pelvon sinun päälles, sanoo Herra, Herra Zebaot, kaikista niistä, jotka asuvat sinun ympärilläs; niin että te jokainen pitää ajettaman pois toisensa tyköä, ja ei pidä kenenkään karkureita kokooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Mutta sitte minä käännän Ammonin lasten vankiuden, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Edomia vastaan sanoo Herra Zebaot näin: eikö tietoa enään ole Temanissa? Eikö neuvoa enään ole taitavilla? joko heidän tietonsa loppui?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Paetkaat, palatkaat ja kätkekäät teitänne syvälle, Te Dedanin asuvaiset; sillä minä annan Esaulle tulla onnettomuuden, hänen etsikkonsa ajan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Viinan hakiat pitää tuleman sinun päälles, joiden ei pidä mitään sinulle jättämän jälkeensä; ja varkaat pitää yöllä tuleman sinun päälles, heidän pitää kyllä varastaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Sillä minä olen paljastanut Esaun, ja ilmoittanut hänen salaisen paikkansa, niin ettei hän taida itsiänsä kätkeä; hänen siemenensä, hänen veljensä ja hänen kylänsä miehet ovat hävitetyt, niin ettei yhtään enään ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Kuitenkin niiden, jotka jäävät orvoistas, tahdon minä suoda elää; ja sinun leskeis pitää minuun luottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Sillä näin sanoo Herra: katso, jotka ei ole syypäät juomaan kalkkia, niiden pitää totisesti juoman, ja sinun pitäis rankaisematta pääsemän? Ei sinun pidä rankaisematta pääsemän, vaan sinun pitää kaiketi juoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Sillä minä olen vannonut itse kauttani, sanoo Herra, että Botsran pitää tuleman ihmeeksi, häväistykseksi, hävitykseksi ja kiroukseksi; ja kaikki hänen kaupunkinsa ijankaikkiseksi autioksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Minä olen kuullut sanoman Herralta, että sanansaattaja on lähetetty pakanoille: kootkaat teitänne ja tulkaat tänne häntä vastaan, ja sotikaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Sillä katso, minä olen sinun alentanut pakanain seassa, ja tehnyt sinun ylönkatsotuksi ihmisten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Sinun ylpeytes ja sinun sydämes koreus on sinun pettänyt, että sinä asut vuorten raoissa ja vallitset korkiat vuoret. Jos sinä tekisit pesäs niin korkiaksi kuin kotka, niin minä kuitenkin sieltä sinun kukistan alas, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Juuri niin pitää Edom autioksi tuleman; ja kaikkein, jotka siitä käyvät ohitse, pitää ihmettelemän ja viheltämän kaikkia hänen vaivojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Niinkuin Sodoma ja Gomorra lähikyläinsä kanssa kukistetut ovat, sanoo Herra, niin ettei kenkään siellä asu, eikä joku ihminen siellä olla taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Katso, hän tulee ylös niinkuin jalopeura ylpeästä Jordanista vahvoja majoja vastaan; sillä minä tahdon antaa hänen nopiasti sieltä juosta, ja kuka tietää sen nuorukaisen, jonka minä varustan heitä vastaan? Sillä kuka on minun kaltaiseni? kuka tahtoo minun eteeni panna ajan? Ja kuka paimen voi olla minua vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Kuulkaat siis Herran neuvoa, jonka hän piti Edomista, ja hänen ajatuksiansa, jotka hän ajatteli Temanin asuvaisista: mitämaks että karjalapset pitää riepoittaman heitä, ja kukistaman heidän asumasiansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Niin että maan pitää vapiseman heidän lankeemisessansa, ja heidän parkunsa ja huutonsa pitää kuultaman Punaisessa meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Katso, hän lentää ylös niinkuin kotka, ja hajoittaa siipensä Botsran ylitse; silloin pitää Edomin sankarien sydän oleman niinkuin synnyttäväisen vaimon sydän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Damaskua vastaan: Hematissa ja Arpadissa on surkia meno; he epäilevät, sillä he kuulevat pahoja sanomia; asuvaiset meren tykönä ovat hämmästyksissä, niin ettei heillä ole lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damasku epäilee ja pakenee: hän vapisee ja on ahdistuksessa ja kivussa, niinkuin synnyttäväinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Kuinka? Eikö se kuuluisa kaupunki ole hyljätty, minun ilokaupunkini?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Sentähden pitää hänen nuorukaisensa lankeeman hänen kaduillansa, ja kaikki hänen sotaväkensä tapettaman siihen aikaan, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Ja minä sytytän tulen Damaskun muurien päälle, niin että sen pitää polttaman Benhadadin huoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Kedaria vastaan ja Hatsorin valtakuntia vastaan, jotka Nebukadnetsar, Babelin kuningas löi. Näin sanoo Herra: ylös, menkäät Kedariin, ja kukistakaat idän lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Heidän majansa ja laumansa pitää heiltä otettaman pois, heidän telttansa ja kaikki heidän kappaleensa, ja heidän kamelinsa pitää heidän ottaman myötänsä; ja pitää julmasti huutaman heidän tähtensä ympäristöltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Paetkaat, joutukaat kiiruusti, menkäät syvään asumaan, te Hatsorin asuvaiset, sanoo Herra. Sillä Nebukadnetsar, Babelin kuningas, on teistä neuvoa pitänyt, ja ajattelee ja aikoo jotain teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Ylös, menkäät kansaa vastaan, joka levossa on ja asuu suruttomasti, sanoo Herra; ei heillä ole ovea eikä telkeä, ja he asuvat yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Heidän kamelinsa pitää ryöstettämän, ja heidän karjansa paljous otettaman pois; ja minä hajoitan heidät joka tuuleen, jotka nurkissa asuvat, ja joka taholta annan minä heidän onnettomuutensa tulla heidän päällensä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Ja Hatsorin pitää tuleman lohikärmetten asumasiaksi ja ijankaikkiseksi autioksi, niin ettei kenenkään pidä siellä asuman, ja ei yhdenkään ihmisen siellä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Tämä on Herran sana, joka tapahtui Jeremialle, prophetalle Elamia vastaan, Zedekian Juudan kuninkaan valtakunnan alussa, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Näin sanoo Herra Zebaot: katso, minä taitan Elamin joutsen, heidän ylimmäisen voimansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Ja annan tulla Elamin päälle neljä tuulta neljästä taivaan äärestä, ja hajoitan heidät kaikkiin niihin tuuliin, niin ettei yhtään kansaa pidä oleman, kuhunka ei joku Elamin hajoitetuista tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Ja minä saatan Elamin epäilemään heidän vihollistensa edessä ja niiden edessä, jotka väijyvät heidän henkeänsä, ja annan onnettomuuden tulla heidän päällensä, minun julman vihani, sanoo Herra; ja lähetän miekan heidän päällensä, siihenasti että minä heidät lopetan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Minun istuimeni panen minä Elamiin, ja hävitän sieltä sekä kuninkaan että ruhtinaat, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Mutta viimeisellä ajalla käännän minä Elamin vankiuden, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Nämät ovat ne sanat, jotka Herra on propheta Jeremian kautta puhunut Babelin ja Kaldealaisten maata vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Julistakaat pakanain seassa ja tiettäväksi tehkäät, nostakaat lippu ylös, kuuluttakaat ja älkäät sitä salatko, ja sanokaat: Babel on voitettu, Bel on häpiään joutunut, Merodak on rikottu, hänen epäjumalansa ovat häpiään tulleet, ja hänen jumalansa ovat murskaksi lyödyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Sillä pohjoisesta nousee kansa heitä vastaan, jonka pitää heidän maansa hävittämän, niin ettei kenenkään pidä siinä asuman, vaan sekä ihmiset että eläimet sieltä pakeneman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Niinä päivinä ja siihen aikaan, sanoo Herra, pitää Israelin lasten Juudan lasten kanssa tuleman, ja pitää joudukkaasti käymän ja itkemän, ja etsimän Herraa Jumalaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Heidän pitää kysymän tietä Zioniin ja kääntämän itsensä sinne: tulkaat, ja me tahdomme pysyä Herrassa ijankaikkisella liitolla, joka ei ikänä pidä unhotettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Minun kansani on tullut kadonneeksi laumaksi; heidän paimenensa ovat heidät vietelleet ja antaneet heidän eksyksissä kävellä vuorilla, niin että he ovat vuorilta menneet kukkuloille, ja ovat unhottaneet majansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Kuka ikänä heidän tykönsä tuli, se söi heitä, ja heidän vihollisensa sanoivat: emmepä me tee väärin, sillä he ovat rikkoneet Herraa vastaan vanhurskauden asumuksessa, ja Herraa vastaan, joka heidän isänsä toivo on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Paetkaat Babelista ja lähtekäät pois Kaldealaisten maasta ulos, ja laittakaat teitänne niinkuin kauriit lauman edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Sillä katso, minä nostan suuren väen joukoittain pohjan maalta, ja annan heidän tulla Babelin eteen; heidän pitää varustaman itsensä häntä vastaan, ja voittaman hänen. Heidän nuolensa ovat niinkuin taitavan sotamiehen, joka ei tyhjään ammu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Ja Kaldean maa pitää tuleman saaliiksi, niin että kaikkein, jotka sitä ryöstävät, pitää siitä kyllä saaman, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Että te iloitsette siitä ja kerskaatte itsiänne, että te olette minun perintöni ryöstäneet, ja hyppelette niinkuin lihavat vasikat, ja hirnutte niinkuin väkevät (hevoset).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Teidän äitinne on suureen häpiään joutunut, ja se häpee, joka teidät on synnyttänyt; katso, hän on pakanain seassa kaikkein huonoin, autio, kuiva ja hävinnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Herran vihan tähden ei pidä siinä asuttaman, vaan se kokonansa autiona oleman; niin että kaikkein, jotka menevät ohitie Babelia, pitää ihmettelemän ja viheltämän kaikkein hänen vaivainsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Varustakaat teitänne Babelia vastaan, joka taholta kaikki ampujat, ampukaat häntä, älkäät säästäkö nuolia; sillä hän on rikkonut Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Riekukaat häntä vastaan joka taholta; hänen pitää myötä antaman, hänen perustuksensa ovat langenneet, ja hänen muurinsa hajonneet; sillä se on Herran kosto, kostakaat hänelle, ja tehkäät hänelle niinkuin hän on tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Hävittäkäät sekä kylväjä että se, joka sirppiin rupee elonaikana; niin että jokainen kääntää itsensä kansansa tykö hävittäjän miekan tähden, ja jokainen pakenee maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Israelin täytyy olla hajoitetun lammaslauman, jonka jalopeurat ovat hajoittaneet. Ensisti söi Assurian kuningas hänen, sitte särki Nebukadnetsar, Babelin kuningas, hänen luunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Sentähden sanoo Herra Zebaot, Israelin Jumala, näin: minä etsin Babelin kuninkaan ja hänen maansa, niinkuin minä olen Assurian kuninkaan etsinyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Mutta Israelin minä annan tulla jälleen kotia asumasiaansa, niin että hänen pitää itsensä elättämän Karmelissa ja Basanissa, ja Ephraimin vuorella, ja Gileadissa pitää hänen sielunsa ravituksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Niinä päivinä ja siihen aikaan, sanoo Herra, pitää Israelin pahateko etsittämän, ja ei löyttämän, ja Juudan synti, ja ei pidä löyttämän; sillä minä olen armollinen niille, jotka minä jätän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Mene kapinan nostajain maahan, mene sinne ylös, ja etsi etsikon asuvaisia; hävitä ja tapa heidän jälkeentulevaisensa, sanoo Herra, ja tee kaikki, mitä minä olen käskenyt sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Maalla on sodanriekuna ja iso suru.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kuinka se on tullut, että koko maailman vasara on taitettu ja rikottu? Kuinka Babel on autioksi joutunut pakanain seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Minä olen virittänyt paulan sinun etees, Babel, sentähden olet sinä myös vangittu, ennen kuin sinä havaitsitkaan; sinä olet osattu ja olet käsitetty, sillä sinä olet kehoittanut Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Herra on avannut tavarahuoneensa, ja vetänyt edes vihansa aseet; sillä tämä on Herran, Herran Zebaotin työ Kaldealaisten maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Tulkaat tänne häntä vastaan, te viimeisistä ääristä, avatkaa hänen jyvähuoneensa, paiskatkaat häntä kokoon, ja tappakaat häntä, niin ettei hänelle mitään jää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Surettakaat kaikki hänen mullinsa, viekäät häntä alas teurastettaa; voi heitä! sillä päivä on tullut, heidän etsikkonsa aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Huuto kuuluu paenneilta ja päässeiltä Babelin maasta, että heidän pitää julistaman Zionissa Herran meidän Jumalamme kostoa ja hänen kirkkonsa kostoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Kutsukaat monta Babelia vastaan, piirittäkäät häntä kaikki joutsenampujat joka taholta ympäri, ja älkäät yhtään päästäkö; kostakaat hänelle niin kuin hän on ansainnut; kaiken sen jälkeen kuin hän on tehnyt, niin tehkäät hänelle jälleen; sillä hän on ylpiästi tehnyt Herraa vastaan, Pyhää Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Sentähden pitää hänen nuorukaisensa lankeeman hänen kaduillansa, ja kaikki hänen sotamiehensä hukkuman siihen aikaan, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Katso, sinä ylpeä, minä tahdon sinun kimppuus, sanoo Herra, Herra Zebaot: sillä sinun päiväs on tullut, sinun etsikkos aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Silloin pitää ylpeän itsensä loukkaaman ja lankeeman, niin ettei kenenkään pidä häntä auttaman ylös; ja minä sytytän hänen kaupunkinsa palamaan tulella, jonka pitää kuluttaman kaikki, mitä siinä ympärillä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Näin sanoo Herra Zebaot: katso, Israelin lasten ja Juudan lasten pitää ynnä väkivaltaa ja vääryyttä kärsimän; kaikki ne, jotka heidän ovat vankina vieneet, pitävät heidät, ja ei tahdo heitä päästää vallallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Mutta heidän vapahtajansa on väkevä, Herra Zebaot on hänen nimensä, hän on niin toimittava heidän asiansa, että hän saattaa maan lepäämään ja Babelin asuvaiset värisemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Miekan pitää tuleman, sanoo Herra, Kaldealaisten päälle, ja Babelin asuvaisten päälle, ja hänen ruhtinastensa päälle, ja hänen tietäjäinsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Miekan pitää tuleman hänen noitainsa päälle, niin että heidän pitää tyhmäksi tuleman; miekan pitää tuleman hänen väkeväinsä päälle, että heidän pitää epäilemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Miekan pitää tuleman hänen hevostensa ja ratastensa päälle ja kaiken yhteisen kansan päälle, joka hänen keskellänsä on, niin että heidän pitää tuleman niinkuin vaimot; miekan pitää tuleman hänen riistahuoneensa päälle, niin että ne pitää ryöstetyksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Kuivuuden pitää tuleman hänen vettensä päälle, niin että ne pitää kuivuman; sillä se on epäjumalain maa, ja he röyhkeilevät kauheista epäjumalistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Sentähden pitää petoin ja julmain lintuin siellä asuman, ja yökköin pitää myös siellä asuman; ja ei pidä ikänä enään siinä asuttaman, eikä jonkun siinä oleman suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Niinkuin Herra Sodoman ja Gomorran lähikyläinsä kanssa kukistanut on, sanoo Herra, niin ei siellä kenenkään asuman pidä, eli jonkun ihmisen siellä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Katso, kansa tulee pohjoisesta; monta pakanaa ja monta kuningasta pitää nouseman maan ääristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Heillä on joutsi ja kilpi, he ovat julmat ja armottomat; heidän huutonsa on niinkuin meren pauhina; he ajavat hevosilla niinkuin sotamiehet, varustetut sinua vastaan, sinä Babelin tytär.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Kuin Babelin kuningas on kuuleva heidän sanomansa, silloin pitää hänen kätensä maahan putooman; ahdistus pitää tuleman hänen päällensä, niinkuin synnyttäväisen vaiva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Katso, hän nousee ylös niinkuin jalopeura ylpeästä Jordanista vahvoja majoja vastaan, sillä minä annan hänen nopiasti juosta sieltä; ja kuka tietää sen nuorukaisen, jonka minä olen varustava heitä vastaan? Sillä kuka on minun vertaiseni? kuka tahtoo minulle ajan määrätä? ja kuka on se paimen, joka voi olla minua vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Kuulkaat siis nyt Herran neuvoa, jonka hän piti Babelista, ja hänen ajatuksiansa, jotka hän ajatteli Kaldean maan asuvaisista: mitämaks että karjalaisten pitää riepoittaman heitä, ja kukistaman heidän asumansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Ja maan pitää vapiseman riekunasta, ja pitää kuuluman pakanain seassa, kuin Babel voitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Näin sanoo Herra: katso, minä nostan ankaran ilman Babelia vastaan ja hänen asuvaisiansa vastaan, jotka itsensä ovat asettaneet minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Ja lähetän viskaajat Babeliin, joiden pitää häntä viskaaman, ja tyhjentämän hänen maansa; näiden pitää joka paikassa oleman hänen ympärillänsä hänen onnettomuutensa päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Sillä hänen ampujansa ei pidä taitaman ampua, ja hänen varustettunsa ei pidä taitaman itsiänsä varjella. Älkäät siis säästäkö hänen nuorukaisiansa, tappakaat kaikki hänen sotajoukkonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Niin että lyödyt makasivat Kaldean maalla, ja pistetyt hänen kaduillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Sillä Israel ja Juuda ei pidä Jumalaltansa, Herralta Zebaotilta leskeksi hyljättämän; vaikka heidän maansa on kovin rikkonut Israelin Pyhää vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Paetkaat Babelista, että jokainen pelastais sielunsa, ettette hukkuisi hänen pahuudessansa; sillä tämä on Herran koston aika ja hän tahtoo hänelle maksaa hänen ansionsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Kultainen malja on Babel Herran kädessä, joka on koko maailman juovuttanut; pakanat ovat juoneet hänen viinastansa, sentähden ovat pakanat niin hulluiksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Kuinka pian Babel on kaatunut ja murskaksi lyöty! valittakaat häntä, ottakaat myös voidetta hänen haavallensa, jos hän mitämaks taitais parantua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Me paransimme Babelia, mutta ei hän terveeksi tullut; antakaat siis hänen olla, ja käykäämme itsekukin maallensa; sillä hänen rangaistuksensa ulottuu hamaan taivaasen, ja astuu pilviin ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Herra on tuonut edes meidän vanhurskautemme: tulkaat ja luetelkaamme Herran meidän Jumalamme töitä Zionissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Teroittakaat nuolet, ja valmistakaat kilvet: Herra on herättänyt Medin kuningasten sydämen; sillä hänen ajatuksensa on Babelia vastaan, hävittää häntä. Sillä tämä on Herran kosto, hänen temppelinsä kosto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Ripustakaat lippu ylös Babelin muurille, asettakaat vartio, pankaat vartiat, toimittakaat väijyjät; sillä Herra ajattelee jotain, ja on myös täyttävä, mitä hän Babelin asuvaisia vastaan on puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Sinä, joka suuren veden tykönä asut, jolla myös ovat suuret tavarat, sinun loppus on tullut, ja sinun ahneutes on lakannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Herra Zebaot on vannonut itse kauttansa: minä tahdon täyttää sinun ihmisillä, niinkuin ruohomadoilla, heidän pitää laulaman sinusta ilovirren.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Joka maan voimallansa tehnyt on, ja maanpiirin viisaudellansa vahvistanut, ja taivaat toimellisuudellansa venyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Kuin hän jylisee, niin on paljo vettä taivaan alla; hän tempaa pilvet ylös hamasta maan äärestä; hän tekee leimaukset sateessa, ja tuo tuulen kammioistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Kaikki ihmiset ovat tomppelit taidossansa, ja jokainen kultaseppä häväistään kuvinensa; sillä heidän kuvansa ovat petos, ja ei ole niissä henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Ne ovat sula turhuus ja petollinen työ; heidän täytyy hukkua, kuin heitä etsitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Mutta Jakobin osa ei ole senkaltainen, vaan hän on se, joka kaikki luonut on, (Israel on) hänen perimisensä valtikka: Herra Zebaot on hänen nimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Sinä olet minun vasarani, minun sota-aseeni: ja minä lyön kauttas pakanat ja hävitän valtakunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Minä lyön sinun kauttas hevoset, ratsastajat, ja rikon sinun kauttas vaunut ja niiden ajajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Minä lyön sinun kauttas miehet ja vaimot, ja lyön sinun kauttas vanhat ja nuoret, ja sinun kauttas nuorukaiset ja neitseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Minä lyön sinun kauttas paimenet ja heidän laumansa, minä lyön sinun kauttas peltomiehet ja juhdat, ja lyön sinun kauttas ruhtinaat ja päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Sillä minä tahdon maksaa Babelille ja kaikille Kaldean asuvaisille kaiken heidän pahuutensa, jonka he ovat Zionille tehneet, teidän silmänne edessä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Katso, minä tulen sinun tykös, sinä vahingollinen vuori, joka koko maailman turmelet, sanoo Herra, ja ojennan käteni sinun ylitses, ja vieritän sinun alas vuorelta, ja teen poltetun vuoren sinusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Niin ettei sinusta ei kulmakiviä eikä perustuskiviä taideta ottaa; vaan sinun pitää oleman ijankaikkisen aution, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Nostakaat lippu ylös maalla, soittakaat torvella pakanain seassa, varustakaat pakanat häntä vastaan, kutsukaat häntä vastaan (nämät) valtakunnat: Ararat, Minni ja Askenas; toimittakaat sodanpäämiehet häntä vastaan, tuokaat hevoset niinkuin julmat vapsaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Varustakaat pakanat häntä vastaan, Median kuninkaat, hänen ruhtinaansa ja kaikki hänen päämiehensä, ja kaikki hänen valtansa maakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Ja maan pitää vapiseman ja peljästymän; sillä Herran ajatukset tahtovat tulla täytetyksi Babelia vastaan, niin että hän tekee Babelin maan autioksi, jossa ei kenenkään pidä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Babelin sankarit ei pidä uskaltaman mennä sotaan, vaan linnoissa pysymän, heidän väkevyytensä on pois, ja ovat tulleet niinkuin vaimot; hänen asumisensa ovat sytytetyt, ja hänen telkensä taitetut rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Tässä juoksee yksi toisensa editse, ja yksi sanansaattaja kohtaa toista, ilmoittamaan Babelin kuninkaalle, että hänen kaupunkinsa on hamaan loppuun asti voitettu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Ja luotuspaikat suljetut, ja järvet poltetut, ja sotaväki pelkuriksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Sillä näin sanoo Herra Zebaot, Israelin Jumala: Babelin tytär on niinkuin riihen permanto, hänen tappamisensa aika on tullut; vielä vähän ajan perästä tulee hänen niittämisensä aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nebukadnetsar, Babelin kuningas on minun syönyt, ja kukistanut minun; hän on tehnyt minun tyhjäksi astiaksi; hän on niellyt minun niinkuin lohikärme, hän on täyttänyt vatsansa minun herkuistani; hän on minun ajanut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Mutta nyt löytään Babelissa se vääryys, jota minulle ja minun lihalleni on tehty, sanoo Zionin asuva, ja minun vereni Kaldean asuvaisten päälle, sanoo Jerusalem.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Sentähden sanoo Herra näin: katso, minä toimitan sinun asias, ja kostan sinun kostos; minä kuivaan hänen merensä, ja annan kuivata hänen kaivonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Ja Babelin pitää tuleman kiviraunioksi ja lohikärmeiden asumasiaksi, ihmeeksi ja viheltämiseksi, niin ettei kenenkään pidä siellä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Heidän kaikkein pitää kiljuman niinkuin jalopeurat, ja huutaman niinkuin nuoret jalopeurat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Minä panen heidän juomisensa helteesen, ja juovutan heidät, niin että heidän pitää iloiseksi tuleman, ja makaaman ijankaikkista unta, josta ei heidän ikänä pidä heräämän, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Minä vien heidät alas niinkuin karitsat teurastettaa, niinkuin oinaat ja kauriit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kuinka Sesak on niin voitettu, ja ylistetty koko maailmassa niin kiinni otettu? Kuinka on Babel tullut ihmeeksi pakanain seassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Meri on käynyt Babelin ylitse, ja se on peitetty monella aallolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Hänen kaupunkinsa ovat hyljätyt, kuivaksi ja kylmäksi maaksi tulleet, maaksi, jossa ei kenkään asu, ja kussa ei yhtään ihmistä vaella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Sillä minä etsin Beliä Babelissa, ja repäisen hänen kurkustansa ulos sen, minkä hän on niellyt; ja pakanain ei pidä enään juokseman hänen tykönsä; Babelin muurit ovat myös maahan jaonneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Lähtekäät sieltä ulos, minun kansani, ja jokainen pelastakoon sielunsa Herran julmasta vihasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Teidän sydämenne taitais muutoin pehmeäksi tulla ja nääntyä siitä sanomasta, jonka maalla pitää kuuluman; sillä yhtenä vuonna pitää sanoman kuuluman, niin myös toisena vuonna, sanoman väkivallasta maalla, ja yhden ruhtinaan oleman toista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Sentähden katso, aika tulee, että minä Babelin epäjumalat etsin, ja koko hänen maansa pitää tuleman häpiään, ja kaikki hänen lyötynsä pitää siellä makaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Taivaan ja maan ja kaikki, mitä niissä on, pitää iloitseman Babelista, että hänen kukistajansa ovat tulleet pohjasta, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Ja niinkuin Babel Israelissa on kaatanut lyödyt, niin pitää myös lyödyt Babelissa kaattaman kaikessa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Menkäät siis matkaanne te, jotka olette välttäneet miekan, ja älkäät kauvan viipykö; ajatelkaat Herran päälle kaukaisella maalla, ja pitäkäät Jerusalem mielessänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Me olemme häpiään tulleet, kuin me kuulimme sen häväistyksen; ja häpiä peitti meidän kasvomme, kuin muukalaiset tulivat Herran huoneen pyhään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Sentähden katso, aika tulee, sanoo Herra, että minä hänen epäjumalansa etsin; ja koko maalla pitää kuolemahaavoilla lyödyt huokaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Jos Babel astuis ylös taivaasen ja kiinnittäis itsensä korkeuteen, niin pitää kuitenkin minulta kukistajat tuleman hänen päällensä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Ääni kuuluu Babelista, suuri valitus Kaldean maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Sillä Herra hävittää Babelin, hän hävittää hänen niin suurella riekunalla ja kapinalla, että hänen aaltonsa pauhaavat, niinkuin isot vedet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Sillä hävittäjä on tullut Babelin päälle, hänen sankarinsa käsitetään, heidän joutsensa taitetaan; sillä koston Jumala, Herra maksaa täydellisesti hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Minä juovutan hänen ruhtinaansa, tietäjänsä, herransa, päämiehensä ja voimallisensa, niin että heidän pitää lepäämän ijankaikkista unta, josta ei heidän enään pidä heräämän, sanoo Kuningas, jonka nimi on Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Näin sanoo Herra Zebaot: suuren Babelin muurit pitää alta kaivettaman, ja hänen korkiat ovensa tulella poltettaman, että pakanain työn pitää turhan oleman, ja poltettaman, mitä kansa vaivalla on rakentanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Tämän on se sana, jonka propheta Jeremia käski Serajalle Nerijan pojalle, Mahsejan pojan, kuin hän Zedekian, Juudan kuninkaan kanssa meni Babeliin hänen valtakuntansa neljäntenä vuotena. Ja Seraja oli rauhallinen ruhtinas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Ja Jeremia kirjoitti yhteen kirjaan kaiken onnettomuuden, joka piti Babelin päälle tuleman, kaikki nämät sanat, jotka ovat kirjoitetut Babelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Ja Jeremia sanoi Serajalle: kuin sinä tulet Babeliin, niin katso ja lue kaikki nämät sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Ja sano: Herra! sinä olet puhunut tätä paikkaa vastaan, hävittääkses sitä, niin ettei kenenkään pitäisi asuman tässä, ei ihmistä eikä eläintä, vaan oleman ijankaikkisena autiona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Ja kuin olet lukenut kaiken tämän kirjan, niin sido siihen kivi, ja paiskaa se keskelle Phratia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'Ja sano: näin pitää Babeli upotettaman, ja ei jälleen nouseman ylös siitä onnettomuudesta, jonka minä tuotan hänen päällensä, vaan hukkuman. Tähän asti ovat Jeremian sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Zedekia oli yhdenkolmattakymmentä vuoden vanha tullessa kuninkaaksi, ja hallitsi yksitoistakymmentä vuotta Jerusalemissa. Hänen äitinsä nimi oli Hamutal Jeremian tytär Libnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Ja hän teki pahaa Herran edessä, niinkuin Jojakimkin oli tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Sillä Herran viha oli Jerusalemin ja Juudan päällä, siihenasti että hän heitti heidät pois kasvoinsa edestä. Ja Zedekia luopui Babelin kuninkaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Ja tapahtui hänen valtakuntansa yhdeksäntenä vuotena, kymmenentenä päivänä, kymmenennessä kuukaudessa, että Nebukadnetsar, Babelin kuningas tuli kaiken joukkonsa kanssa Jerusalemia vastaan; ja he sioittuivat sen eteen, ja rakensivat saarron sen ympärille joka taholta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Ja kaupunki oli niin piiritetty hamaan yhteentoistakymmenenteen kuningas Zedekian vuoteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Yhdeksäntenä päivänä neljännessä kuukaudessa sai nälkä vallan kaupungissa, ja ei ollut maakunnan kansalla enään mitään syötävää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Niin kukistettiin kaupunki, ja kaikki sotamiehet pakenivat ja menivät ulos kaupungista, yöllä, porttitietä, joka oli kahden muurin välillä kuninkaan yrttitarhaa kohden; mutta Kaldealaiset makasivat kaupungin ympärillä, ja nämät menivät pois tietänsä myöten kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Niin ajoi Kaldealaisten sotajoukko kuningasta takaa, ja saavutti Zedekian Jerikon kedolla, ja kaikki hänen sotajoukkonsa oli hänestä hajonnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Ja he ottivat kuninkaan kiinni ja veivät hänet Babelin kuninkaan tykö Riblatiin, joka on Hamatin maalla, ja hän sanoi tuomion hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Ja Babelin kuningas antoi tappaa Zedekian lapset, hänen silmäinsä edessä; ja tappoi kaikki Juudan ruhtinaat Riblatissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Mutta Zedekialta hän antoi puhkaista silmät, ja antoi hänen sidottaa kaksilla vaskikahleilla; ja Babelin kuningas vei hänen Babeliin, ja hän pani hänen vankihuoneesen, siihenasti kuin hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Kymmenentenä päivänä, viidentenä kuukautena, joka oli Nebukadnetsarin, Babelin kuninkaan yhdeksästoistakymmenes vuosi, tuli Nebusaradan, huovinhaltia, joka seisoi Babelin kuninkaan edessä, Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Ja poltti Herran huoneen ja kuninkaan huoneen, ja kaikki huoneet Jerusalemissa; kaikki suuret huoneet poltti hän tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Ja kaikki Kaldealaisten sotajoukko, joka huovinhaltian kanssa oli, jaotti kaikki muurit Jerusalemissa joka taholta ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Mutta köyhän väen ja muun kansan, joka oli vielä jäänyt kaupunkiin, ja ne, jotka olivat itsensä antaneet Babelin kuninkaan alle, ja jääneet kansasta, vei Nebusaradan, huovinhaltia, vangittuna pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Ja Nebusaradan, huovinhaltia, antoi monikahdat köyhästä maan väestä jäädä viinamäkien ja peltoin rakentajiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Mutta vaskipatsaat, jotka olivat Herran huoneessa, ja istuimet ja vaskimeren, joka Herran huoneessa oli, rikkoivat Kaldealaiset, ja veivät kaiken vasken Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Ja kattilat, lapiot, veitset, vaskimaljat, lusikat ja kaikki vaski-astiat, joilla palveltiin, ottivat he pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Otti myös huovinhaltia pois kaikki, mitkä kullasta ja hopeasta oli, juoma-astiat, savi-astiat, maljat, kattilat, kynttiläjalat, lusikat ja kupit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Ne kaksi patsasta, sen yhden meren, ne kaksitoistakymmentä vaskihärkää, jotka seisoivat jalkain alla, jotka kuningas Salomo oli antanut tehdä Herran huoneesen, näistä astioista karttui ylönpalttinen vaski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Mutta patsaat oli kumpikin kahdeksantoistakymmentä kyynärää korkiat, ja kaksitoista kyynärää nuoraa oli mitta hänen ympäriltänsä, ja oli neljän sormenpaksuus, ja avoin sisältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Ja kruunu sen päällä oli myös vaskesta, joka oli viisi kyynärää korkia, ja verkko ja granatin omenat ympäri kruunun olivat kaikki vaskesta; tainkaltainen oli myös toinen patsas ja granatin omenat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Ja oli sen päällä yhdeksänkymmentä ja kuusi granatin omenaa; kaikki granatin omenat olivat sata yhden verkon päällä aina ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Ja huovinhaltia otti papin Serajan ensimäisestä järjestyksestä, ja papin Zephanian toisesta järjestyksestä ja kolme ovenvartiaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Ja hän otti yhden kamarihaltian kaupungista, joka oli pantu sotaväen päälle, ja seitsemän miestä niistä, jotka aina seisoivat kuninkaan edessä, jotka kaupungissa löydettiin, niin myös joukon ylimmäisen kirjoittajan, joka kirjoitti maan väen, ja kuusikymmentä miestä maan kansasta, jotka kaupungissa löydettiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Nämät otti Nebusaradan, huovinhaltia, ja vei heidät Babelin kuninkaan tykö Riblatiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Ja Babelin kuningas tappoi heidät Riblatissa, Hamatin maalla. Niin Juuda vietiin vankina pois maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Tämä on se kansa, jonka Nebukadnetsar vei pois: seitsemäntenä vuonna, kolmetuhatta ja kolme kolmattakymmentä Juudalaista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Mutta Nebukadnetsarin kahdeksantenatoistakymmenentenä vuotena, kahdeksansataa kaksineljättäkymmentä sielua Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Ja Nebukadnetsarin kolmantena vuonna kolmattakymmentä vei Nebusaradan, huovinhaltia, pois seitsemänsataa ja viisiviidettäkymmentä sielua Juudasta; kaikki sielut ovat neljätuhatta ja kuusisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Mutta seitsemäntenä vuonna neljättäkymmentä sen jälkeen kuin Jojakin, Juudan kuningas, oli viety pois, viidentenä päivänä kolmattakymmentä toisessa kuukaudessa toistakymmentä, nosti Evilmerodak, Babelin kuningas, sinä vuonna, jona hän tuli kuninkaaksi, Jojakinin Juudan kuninkaan pään ylös, ja otti hänen vankihuoneesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Ja puhui hänen kanssansa ystävällisesti, ja asetti hänen istuimensa ylemmäksi niiden kuningasten istuimia, jotka hänen tykönänsä olivat Babelissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Ja muutti hänen vankiutensa vaatteet; ja hän söi hänen edessänsä leipää aina kaikkena elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Ja hänelle annettiin alinomaa Babelin kuninkaalta hänen elatuksensa, niinkuin hänelle oli määrätty kaikeksi hänen elinajaksensa, aina hänen kuolemaansa asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Kuinka se kaupunki niin yksinäinen on, joka täynnä kansaa oli? Hän on niinkuin leski. Joka ylimmäinen oli pakanain seassa ja vallan päällä maakunnissa, sen täytyy nyt veronalaisena olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Yli yötä hän katkerasti itkee, niin että hänen kyynelensä poskilta vuotavat; ei hänen ystävistänsä kenkään häntä lohduta, vaan kaikki hänen lähimmäisensä katsovat hänen ylön, ja ovat hänen vihollisiksensa tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juuda on vangittu raadollisuudessa ja raskaassa orjuudessa; hän asuu pakanain seassa, ja ei löydä lepoa; kaikki hänen vihollisensa pahasti menevät hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Zionin tiet murehtivat, ettei kenkään juhlille tule; kaikki hänen porttinsa ovat autiona, hänen pappinsa huokaavat, ja hänen neitseensä surkiasti katsovat, ja hän itse on murheissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Hänen vihollisensa voitti, hänen vihollisillensa käy hyvästi; sillä Herra on hänen surkeudella täyttänyt hänen pahain tekoinsa paljouden tähden; hänen lapsensa ovat vankina menneet pois vihollisten edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Ja kaikki kaunistus on Zionin tyttäriltä lähtenyt pois; hänen päämiehensä ovat niinkuin ne peurat, jotka ei laidunta löydä, ja voimatoinna käyvät vaatian edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem muistaa tällä ajalla, kuinka raadollinen ja hyljätty hän on, ja kuinka paljo hyvää hänellä vanhaan aikaan ollut on, että hänen kansansa vihollisen kädessä on, ja ei kenkään heitä auta; hänen vihollisensa näkevät hänen, ja nauravat hänen lepoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem on raskaasti syntiä tehnyt, sentähden täytyy hänen olla niinkuin saastainen vaimo; kaikki, jotka häntä kunnioittavat, katsovat hänen ylön, että he hänen häpiänsä näkevät; mutta hän huokaa ja lankee maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Hänen saastaisuutensa tarttuu kiinni hänen liepeesensä; ei hän olisi luullut, että hänelle näin pitäis viimein käymän; hän on tosin ylen hirmuisesti kukistettu maahan, ja ei kenkään sittekään ole, joka häntä lohduttaa: Herra, katso minun raadollisuuttani, sillä vihollinen suuresti kerskaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Vihollinen on pannut kätensä kaikkein hänen kallisten kaluinsa päälle; sillä hänen täytyy katsoa päältä, että pakanat hänen pyhyytensä kävivät, joista sinä kieltänyt olet, ettei heidän pitänyt sinun seurakuntaas tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Kaikki hänen kansansa huokaavat, leipää kerjäten; he antoivat parhaat kappaleensa ruasta, että he sielunsa virvoittaisivat. Herra, katso siis ja näe, kuinka minä olen halvaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Eikö tämä teihin koske, kaikki jotka tästä käytte ohitse, katsokaat siis ja nähkäät, jos joku kipu on niinkuin minun kipuni, joka minua niin syö; sillä Herra täytti minun surulla hirmuisen vihansa päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Korkeudesta hän lähetti tulen minun luihini, ja antoi sen voimallisen olla niissä; minun jalkani eteen viritti hän verkon, ja sysäsi minun takaperin: hän on tehnyt minun autioksi, että minun ylipäivää täytyy murehtia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Minun syntini ijes on sidottu, ne ovat väätyt hänen kädessänsä, ja astuneet minun kaulani päälle; hän on minun voimani heikoksi tehnyt; Herra on antanut minua niiden käsiin, joista en minä voi nousta ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Herra on tallannut kaikki minun väkeväni alas, jotka minulla olivat, hän on antanut minusta kokouksen kuuluttaa, minun nuoria miehiäni kadottamaan; Herra on sotkunut viinakuurnan neitseelle, Juudan tyttärelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Sentähden minä niin itken, ja molemmat minun silmäni vettä vuotavat, että lohduttaja, joka minun sieluani pitäis virvoittaman, on minusta kaukana; minun lapseni ovat pois, sillä vihollinen on voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Zion ojentaa kätensä, vaan ei kenkään ole joka häntä lohduttaa; Herra on käskenyt Jakobista, että ne, jotka hänen ympärillänsä ovat, hänen vihollisensa olisivat; sillä Jerusalem pitää heidän seassansa niinkuin saastainen vaimo oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Herra on vanhurskas; sillä minä olen hänen suullensa tottelematoin ollut. Kuulkaat, kaikki kansat, ja katsokaat minun kipuani; minun neitseeni ja nuorukaiseni ovat vankiuteen menneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Minä kutsuin ystävääni (avukseni), mutta he ovat minun vietelleet; minun pappini ja vanhimmat kaupungeissa ovat nääntyneet, sillä he kerjäävät leipää henkeänsä virvoittaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Herra, katso, kuinka minä olen ahdistuksessa, että se kaikki minun sisällyksiäni kivistelee, minun sydämeni tykyttää minun ruumiissani; sillä minä olen täynnä murhetta; ulkona miekka ja kotona kuolema on minun leskeksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Kyllä se kuuluu, että minä huokaan, ja ei kuitenkaan minulla ole lohduttajaa; kaikki minun viholliseni kuulevat minun onnettomuuteni, ja siitä riemuitsevat, sillä sinä sen teet. Niin anna siis sen päivän tulla, jonka sinä kuuluttanut olet, että heille kävis kuin minullekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Anna kaikki heidän pahuutensa tulla sinun etees, ja tee heille, niinkuin sinä minullekin teit kaikkein minun pahain tekoini tähden; sillä minun huokaukseni on suuri, ja minun sydämeni on murheissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Kuinka Herra on vihoissansa Zionin tyttären pimittänyt? Hän on Israelin kunnian heittänyt taivaasta maan päälle. Ei hän ole muistanut jalkainsa astinlautaa vihapäivänänsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Herra on armottomasti kadottanut kaikki Jakobin asumiset; hän on hirmuisuudessansa Juudan tyttären linnan särkenyt, ja lyönyt heitä maahan; hän on hyljännyt hänen valtakuntansa ja päämiehensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Hän on Israelin kaiken sarven hirmuisessa vihassansa särkenyt, on oikean kätensä vetänyt takaperin, kuin vihollinen tuli, ja on Jakobissa niinkuin tulen liekin sytyttänyt, joka kuluttaa kaikki ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Hän on joutsensa jännittänyt, niinkuin vihollinen; hänen oikean kätensä on hän vienyt, niinkuin vainollinen, ja on tappanut kaikki mitä suloinen oli nähdä; hän on vihansa niinkuin tulen vuodattanut Zionin tyttären majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Herra on niinkuin vihollinen, hän on Israelin raadellut, kaikki hänen huoneensa raadellut, ja hänen linnansa turmellut; hän on Juudan tyttärelle paljon valitusta ja murhetta tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Ja on hajoittanut hänen majansa, niinkuin kryytimaan, ja hänen kokouksensa turmellut; Herra on antanut unhottaa Zionissa sekä juhlat että sabbatit, ja antanut hirmuisessa vihassansa häväistä sekä kuninkaat että papit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Herra on heittänyt alttarinsa pois, ja pyhyytensä alttiiksi antanut, ja hyljännyt huoneensa muurit vihollisen käsiin; niin että he ovat Herran huoneessa huutaneet, niinkuin juhlapäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Herra ajatteli hajoittaaksensa Zionin tyttären muurit, hän on nuoran vetänyt sen ylitse, ja ei vetänyt kättänsä takaperin hukuttamasta; vaan on jaottanut vallit, ja muurit ovat ynnä kukistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Hänen porttinsa ovat vajotetut maahan, hän on särkenyt hänen salpansa, ja tyhjäksi tehnyt. Hänen kuninkaansa ja päämiehensä ovat pakanain seassa, jossa ei he lakia saa kuulla, eikä heidän prophetansa löydä näkyä Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Zionin tyttären vanhimmat makaavat maassa, ja ovat ääneti, heittävät multaa päänsä päälle, ja ovat puettaneet itsensä säkkiin; Jerusalemin neitseet käyvät päät alas päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Niin olen minä itkenyt, että minun silmäni puhkeevat, sisällykseni kivistelevät, maksani on vuodatettu maan päälle, kansani tyttären surkeuden tähden, koska imeväiset ja piskuiset kaupungin kaduilla nääntyivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Koska he sanoivat äidillensä: kussa on leipä ja viina? koska he kaupungin kaduilla nääntyivät, niinkuin surmaan haavoitetut, ja antoivat henkensä ylön äitinsä syliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Voi sinä Jerusalemin tytär, keneen minä vertaan sinun, eli minkä kaltaisena minä sinun pidän? sinä neitsy Zionin tytär, mihinkä minä sinua vertaan, jolla minä sinua lohduttaisin? sillä sinun hävintös on suuri niinkuin meri, kuka taitaa sinua parantaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Sinun prophetas ovat sinulle saarnanneet turhuutta ja hulluja näkyjä, ja ei sinun pahoja tekojas sinulle ilmoittaneet, jolla he olisivat sinun vankiutes estää taitaneet, vaan ovat sinulle saarnanneet turhia saarnoja, joilla he saarnasivat sinun ulos maastas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Kaikki ohitsekäyväiset paukuttavat käsiänsä sinun tähtes, ja viheltelevät sinua, ja pudistelevat päätänsä Jerusalemin tyttären ylitse: tämäkö se kaupunki on, josta sanottiin: se on kaikkein jaloin, josta koko maakunta iloitsee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Kaikki vihollises ammottelevat suutansa sinua vastaan, viheltelevät sinua, ja kiristävät hampaitansa, ja sanovat: me olemme hänen hukuttaneet: tämä on se päivä, jota me halusimme, me olemme sen saaneet ja nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Sen on Herra tehnyt, kuin hän oli ajatellut, hän on täyttänyt sanansa, jonka hän aikaa ennen käskenyt oli; hän on armottomasti hukuttanut, ja on ilahuttanut vihollisen sinusta, ja sinun vainollistes vallan korottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Heidän sydämensä huutaa Herran tykö: Voi sinä Zionin tyttären muuri! anna päivällä ja yöllä kyyneleet vuotaa niinkuin ojan, älä myös lakkaa, ei myös sinun silmämunas mahda lakata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Nouse ja huuda yöllä, ensimäisessä vartiossa, vuodata sydämes niinkuin vettä Herran eteen, nosta kätes hänen puoleensa sinun piskuistes sieluin tähden, jotka nälästä nääntyneet ovat joka kadun päässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Herra näe ja katso sitä, jonka sinä niin turmellut olet; pitääkö siis vaimoin ruumiinsa hedelmän syömän, vähät lapset, jotka vielä käsillä kannetaan? pitääkö papit ja prophetat Herran Pyhässä niin tapetuksi tuleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Kaduilla maassa makasivat nuoret ja vanhat; minun neitseeni ja nuorukaiseni ovat miekan kautta langenneet; sinä olet tappanut vihapäivänäs, sinä olet armottomasti teurastanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Sinä olet minun viholliseni ympäristöltä kutsunut kokoon niinkuin juhlapäiväksi, niin ettei kenkään Herran vihan päivänä ole päässyt eikä jäänyt; sillä jotka minä kasvatin ja ruokin, ne minun viholliseni on hukuttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Minä olen mies, jonka viheliäisyyttä nähdä täytyy hänen hirmuisuutensa vitsan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Hän johdatti minua ja vei pimeyteen ja ei valkeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Hän on kätensä kääntänyt minua vastaan, ja toimittaa toisin aina minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Hän on tehnyt lihani ja nahkani vanhaksi, ja luuni musertanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Hän rakensi minua vastaan, ja sapella ja vaivalla hän minua kääri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Hän on minut pannut pimeyteen, niinkuin aikaa kuolleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Hän on minut muurannut sisälle, etten minä pääse ulos, ja minut kovaan jalkapuuhun pannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Ja vaikka minä huudan ja parun, niin hän kuitenkin korvansa tukitsee minun rukouksestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Hän on muurannut tieni kiinni vuojonkivillä, ja polkuni sulkenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Hän on väijynyt minua niinkuin karhu, niinkuin jalopeura salaisuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Hän on minun antanut tieltä eksyä, ja minut repinyt säpäleiksi, ja minut autioksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Hän on joutsensa jännittänyt, ja asettanut minun nuolella tarkoitettavaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Hän ampui minun munaskuihini viinensä nuolet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Minä olen kaiken minun kansani nauru, ja heidän jokapäiväinen virtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Hän on haikeudella minut ravinnut, ja koiruoholla juovuttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Hän on hampaani somerolla rikki musertanut, hän kieritti minun tuhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Minun sieluni on ajettu pois rauhasta, minun täytyy hyvän unohtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Minä sanoin: minun voimani ja minun toivoni Herran päälle on kadonnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Muista siis, kuinka minä niin raadollinen ja hyljätty, koiruoholla ja sapella juotettu olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Minun sieluni sen kyllä muistaa, ja sitä itsellensä tutkistelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Minä panen sen sydämeeni; sentähden minä vielä nyt toivon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Herran laupiudesta se on, ettemme ratki hukkuneet; ei hänen laupiutensa vielä loppunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Vaan joka huomen se on uusi, ja sinun uskollisuutes on suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Herra on minun osani, sanoo minun sieluni; sentähden tahdon minä häneen toivoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Herra on hyvä niille, jotka häneen toivovat, ja niille sieluille, jotka häntä kysyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Hyvä on olla kärsivällisenä ja Herralta apua toivoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Hyvä on ihmiselle ijestä kantaa nuoruudessansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Että hän istuu yksinänsä, on vaiti, kuin jotakin hänen päällensä tulee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Ja panee suunsa tomuun, ja odottaa toivoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Ja antaa löydä poskillensa, ja paljon pilkkaa kärsii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Sillä ei Herra syökse pois ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Vaan hän saattaa murheelliseksi, ja taas armahtaa suuresta laupiudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Sillä ei hän sydämestänsä ihmisiä kurita eikä murheesen saata,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Niinkuin hän tahtois raadolliset maan päällä ratki jalkainsa alla polkea,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Ja antais jonkun miehen oikeuden Ylimmäisen edessä tulla käännetyksi pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Ja ihmistä väärin tuomita asiassansa, niinkuin ei Herra sitä näkisikään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kuka tohtii siis sanoa: senkaltaiset tapahtuvat ilman Herran käskyä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Eikö paha ja hyvä tule Korkeimman suusta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Miksi siis ihmiset nurisevat eläissänsä? Jokainen nuriskaan syntejänsä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Tutkistelkaamme ja etsikäämme meidän menoamme, ja palatkaamme Herran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Nostakaamme meidän sydämemme ja kätemme taivaasen päin, Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Me, me olemme syntiä tehneet ja kovakorvaiset olleet; (sentähden) et sinä säästänytkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Vaan sinä olet vihalla meitä peittänyt ja vainonnut, ja armottomasti surmannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Sinä verhoitit itses pilvellä, ettei rukous päässyt sen lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Sinä olet meitä tunkioksi ja saastaisuudeksi kansain seassa tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Kaikki meidän vihollisemme ovat suutansa ammottaneet meitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Me painetaan alas ja rangaistaan pelvolla ja ahdistuksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Minun silmäni vuotavat vesi-ojia minun kansani tyttären surkeuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Minun silmäni vuotavat ja ei taida lakata; ei he asetu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Siihenasti että Herra katsoo taivaasta alas ja näkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Minun silmäni kuluttaa minulta elämäni kaikkein minun kaupunkini tytärten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Minun viholliseni ovat minua kovin ajaneet takaa, niinkuin lintua ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'He ovat minun elämäni kuoppaan salvanneet, ja heittäneet kiven minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Ovat myös vedet minun pääni ylitse käyneet; niin minä sanoin: nyt minä ratki hukassa olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Minä huusin avukseni sinun nimeäs, Herra, alhaalta kuopasta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Ja sinä kuulit minun ääneni, älä korvias kätke minun huokauksestani ja huudostani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Sinä lähenet kuin minä sinua huudan, ja sanot: älä pelkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Sinä, Herra, ratkaiset minun sieluni asian, ja lunastat minun henkeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Herra katso, kuinka minulle niin vääryyttä tehdään, ja tuomitse minun oikeuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Sinä näet kaikki heidän kostonsa ja kaikki heidän ajatuksensa minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Herra, sinä kuulet heidän pilkkansa ja kaikki heidän ajatuksensa minua vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Minun vainollisteni huulet ja heidän neuvonsa minua vastaan yli päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Katso, kuin he istuvat eli nousevat, niin he minusta virsiä laulavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Kosta heille, Herra, niinkuin he ansainneet ovat, heidän kättensä töiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Anna heidän sydämensä vavista ja sinun kiroustas tuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Vainoo heitä hirmuisuudella, ja hukuta heitä Herran taivaan alta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kuinka on kulta niin mustunut, ja jalo kulta niin muuttunut? pyhät kivet ovat joka kadun päässä hajoitetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Zionin kempit pojat, puhtaan kullan verraksi luetut, kuinka ne ovat savi-astian kaltaiseksi arvatut, jotka savenvalaja tekee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Lohikärmeet taritsevat nisiä pojillensa ja imettävät heitä; mutta minun kansani tyttären täytyy armotoinna olla, niinkuin yökkö korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Imeväisten kieli tarttuu suun lakeen janon tähden; nuoret lapsukaiset anovat leipää, ja ei ole ketään, joka heille sitä jakaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Jotka ennen söivät herkullisesti, ne ovat kadulla nääntyneet; jotka ennen olivat silkillä vaatetetut, niiden täytyy nyt loassa maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Minun kansani tyttären synti on suurempi kuin Sodoman synti, joka äkisti kukistettiin ja ei yksikään käsi siihen ruvennut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Hänen nasirinsa olivat puhtaammat kuin lumi ja valkeammat kuin rieska; heidän ihonsa oli punaisempi kuin koralli, heidän kauneutensa niinkuin saphir.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Mutta nyt on heidän muotonsa niin mustaksi muuttunut, ettei heitä kaduilla tuta taideta; heidän nahkansa riippuu heidän luissansa, se kuivettui niinkuin puu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Miekalla tapetuille oli parempi kuin niille, jotka nälkään kuolivat, jotka nääntymän ja hukkuman piti maan hedelmän puuttumisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Laupiaammat vaimot ovat omia lapsiansa keittäneet ruaksensa, minun kansani tyttären surkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Herra on vihansa täyttänyt, hän on vuodattanut julman vihansa, ja Zionissa tulen sytyttänyt, joka myös hänen perustuksensa polttanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Ei kuninkaat maan päällä sitä olisi uskoneet, eikä kaikki maan piirin asuvaiset, että vihamiehen ja vihollisen piti tuleman Jerusalemin portista sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Mutta se on hänen prophetainsa syntein tähden ja hänen pappeinsa pahain tekoin tähden, jotka siinä vanhurskasten veren vuodattivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'He kävivat sinne ja tänne kaduilla, niinkuin sokiat, ja olivat itsensä vereen saastuttaneet, ja ei taitaneet heidän vaatteisiinsa ruveta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Vaan he huusivat heitä: välttäkäät, saastaiset, välttäkäät, älkäät mihinkään ruvetko; sillä he välttivät ja pakenivat, niin että myös pakanain seassa sanottiin: ei he kauvan siellä pysy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Sentähden on Herran viha heitä hajoittanut, ja ei enään katso heidän päällensä, ettei he pappeja kunnioittaneet eikä vanhoja armahtaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Kuitenkin meidän silmämme kurkistelevat tyhjäin avun jälkeen, siihenasti että he väsyivät, kuin me odotimme sitä kansaa, joka ei meitä auttaa voinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'He väijyvät meidän askeleitamme, niin ettemme rohkene meidän kaduillamme käydä; meidän loppumme on lähestynyt, meidän päivämme ovat täytetyt, sillä meidän loppumme on tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Meidän vainoojamme olivat nopiammat kuin kotka taivaan alla; vuorilla he myös meitä vainosivat, ja korvessa he meitä vartioitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Herran voideltu, joka meidän turvamme oli, on vangittu heidän verkkoihinsa, josta me sanoimme, että me hänen varjonsa alla elämme pakanain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Iloitse ja riemuitse, sinä Edomin tytär, joka asut Utsin maalla; sillä sen maljan pitää myös sinulle tuleman, ja sinun pitää myös juopuman, ja alasti itses riisuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Mutta sinun vääryydelläs on loppu, sinä Zionin tytär, ei hän enään anna sinua viedä pois, mutta sinun vääryytes, Edomin tytär, hän etsii, ja sinun syntis ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Muista, Herra, kuinka meille tapahtui: katso ja näe meidän ylönkatsettamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Meidän perintömme on muukalaisten osaksi tullut, ja huoneemme ulkonaisten omaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Me olemme orvot ilman isää, ja äitimme ovat niinkuin lesket.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Vettä, joka meidän omamme oli, me joimme rahalla, omat halot me ostimme hinnalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'kaulallamme me vaivaa kärsimme; ja ehkä me jo väsyneet olimme, ei kuitenkaan meille lepoa annettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Meidän piti Egyptin ja Assyrian alle meitämme antaman, että me sittekin leipää ravinnoksemme saaneet olisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Meidän isämme ovat syntiä tehneet, ja ei enään ole käsissä; ja meidän pitää heidän pahoja tekojansa nautitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Orjat meitä vallitsevat; ja ei ole kenkään, joka meitä heidän käsistänsä pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Meidän pitää hakeman leipämme hengen paolla, miekan edessä korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Meidän ihomme on poltettu, niinkuin pätsissä, hirmuisen nälän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'He ovat vaimot Zionissa raiskanneet ja neitseet Juudan kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Ruhtinaat he ovat hirttäneet, ja vanhimpia ei he kunnioittaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Nuorukaiset piti jauhaman, ja piskuisten täytyi puita kantaissansa kompastua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Vanhat puuttuivat porteista, ja nuorukaiset ei enään kanteletta soita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Meidän sydämemme ilo loppui, meidän tanssimme on kääntynyt murheeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Meidän päästämme on kruunu pudonnut; voi nyt meitä, että me niin olemme syntiä tehneet!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Sentähden on myös sydämemme murheissansa; niiden tähden ovat meidän silmämme pimenneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Zionin vuoren tähden, että se niin hävitetty on, että ketut hänessä juoksentelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Mutta sinä Herra, joka ijankaikkisesti olet, ja istuimes ijästä ikään!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Miksis meidät ijankaikkisesti unohdat, ja niin kauvan meitä peräti hylkäät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Palauta, Herra, meitä jälleen sinun tykös, että me taas palaisimme; uudista meidän päivämme niinkuin ne alusta olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Oletkos meitä peräti heittänyt pois, ja sangen suuresti vihastunut meidän päällemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Kolmantenakymmenentenä vuotena, viidentenä päivänä neljännessä kuussa, kuin minä olin vankein seassa Kebarin virran tykönä, aukenivat taivaat ja minä näin Jumalan näyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Viidentenä päivänä kuussa, viidennellä vuodella, sittekuin Jojakin, Juudan kuningas oli viety vankina pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Tapahtui Herran sana Hesekielille, papin Busin pojalle, Kaldean maassa, Kebarin virran tykönä; siellä tuli Herran käsi hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Ja minä näin, ja katso, siellä tuli rajutuuli pohjan puolesta, suuren pilven kanssa, täynnänsä tulta, niin että se kuumotti kaikki ympärinsä, ja tulen keskeltä oli se sangen kirkas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Ja siinä keskellä oli niinkuin neljä eläintä, ja tämä oli heidän muotonsa: he olivat ihmisen muotoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Ja kullakin heillä oli neljät kasvot, ja kullakin neljä siipeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Ja heidän säärensä seisoivat oikiana, mutta heidän pöytäjalkansa olivat niinkuin härjän sorkat, ja paistivat niinkuin kiiltävä vaski.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Ja ihmisen kädet olivat heidän siipeinsä alla, heidän neljällä tahollansa, sillä heillä oli neljät kasvot ja neljä siipeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Ja heidän siipensä olivat yhdistetyt toinen toiseensa; ja kuin he kävivät, ei he erinneet toinen toisestansa; vaan kuhunka he menivät he kohdastansa eteenpäin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Ja niiden neljän kasvot oikialla puolella olivat niinkuin ihmisen kasvot ja jalopeuran kasvot; mutta vasemmalla puolella olivat niillä neljällä kasvot, niinkuin härjän kasvot, ja kotkan kasvot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Ja niin olivat heidän kasvonsa; mutta heidän siipensä olivat eroitetut ylhäältä, niin että kaksi siipeä löi juuri yhteen, ja kahdella siivellä peittivät he ruumiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Kuhunka he menivät, niin he menivät kohdastansa; ja menivät sinne, kuhunka henki ajoi, ja ei erinneet täydessänsä toinen toisestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Ja eläimet olivat näköänsä niinkuin tuliset hiilet, jotka palavat niinkuin tulisoitto, joka kävi eläinten vaiheella; mutta tuli kuumotti, ja tulesta kävi ulos pitkäisen leimaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Ja eläimet juoksivat edes ja takaisin niinkuin pitkäisen tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Kuin minä näin nämät eläimet: katso, niin seisoivat siellä yhdet rattaat maan päällä, neljän eläimen tykönä, ja olivat näköänsä niinkuin neljät rattaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Ja ne rattaat olivat teostansa niinkuin yksi turkos, ja olivat kaikki neljä yhden muotoiset; ja ne olivat näköänsä ja tekoansa niinkuin yhdet rattaat olisivat olleet toinen toisestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Kuin yksi heistä meni, niin menivät kaikki neljä, ja ei erinneet toinen toisestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Niiden pyörät ja korkeus oli sangen ihmeellinen, ja ne olivat täynnä silmiä kaikki ympäri neljää ratasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Ja kuin eläimet kävivät, niin kulkivat myös rattaat heitä myöten; ja kuin eläimet ylensivät itsensä maasta, niin ylensivät myös rattaat itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Kuhunka henki meni, sinne menivät he myös, ja rattaat ylensivät itsensä heidän kanssansa; sillä elävä henki oli rattaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Kuin he menivät, niin menivät nämät myös, kuin he seisoivat, seisoivat nämät myös; ja kuin he ylensivät itsensä maasta, niin ylensivät myös rattaat itsensä heitä myöten; sillä elävä henki oli rattaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Mutta eläinten pään päällä oli niinkuin taivas, kuin peljättävä kristalli, juuri heidän päällitsensä levitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Niin että taivaan alla seisoivat heidän siipensä tasaisesti, yksi juuri toiseen päin; ja kaksi siipeä peitti jokaisen heidän ruumiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Minä kuulin heidän siipiensä äänen, niinkuin suurten vetten pauhinan ja niinkuin Kaikkivaltiaan jylinän, kuin ne liikkuivat, ja pauhinan äänen niinkuin sotajoukon hyminän; mutta kuin he alallansa seisoivat, niin laskivat he siipensä alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Ja ääni kuului taivaasta, joka oli heidän päänsä päällä, kuin he seisoissansa laskivat siipensä alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Ja taivaan päällä, joka heidän ylitsensä oli, oli istuin näkyänsä niinkuin saphir, ja istuimella istui ihmisen muotoinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Ja minä katsoin hänen päällensä, ja hän oli kuin kirkas valkeus, ja sisältä oli se kuin tuli kaikki ympärinsä; hänen kupeistansa ylös ja alas näin minä niinkuin tulen kuumottavan hänen ympärillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Niinkuin taivaan kaari näkyy pilvessä, kuin satanut on, niin oli myös sen kirkkauden näky ympärinsä. Tämä oli Herran kunnian näky. Ja kuin minä sen nähnyt olin, lankesin minä kasvoilleni, ja kuulin äänen puhuvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Ja hän sanoi minulle: sinä ihmisen lapsi, seiso jaloillas, niin minä tahdon puhua sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Ja kuin hän puhui minun kanssani, niin minä vahvistuin hengessä, ja hän asetti minun jaloilleni; ja minä kuulteli häntä, joka puhui minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Ja hän sanoi minulle: sinä ihmisen lapsi, minä lähetän sinun Israelin lasten tykö, jotka minusta luopuneet ovat, jotka isäinsä kanssa hamaan tähän päivään asti ovat minua vastaan rikkoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Mutta ne lapset, joiden tykö minä sinun lähetän, ovat niskurit ja paatuneet sydämestä; niille pitää sinun sanoman; näin sanoo Herra, Herra:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Jos he sen kuulevat, taikka katsovat ylön, sillä se on tottelematoin huone, niin pitää heidän kuitenkin tietämän, että propheta heidän seassansa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Ja sinä ihmisen lapsi, ei sinun pidä pelkäämän heitä, ei myös heidän sanojansa pelkäämän, he ovat tosin vastahakoiset ja terävät orjantappurat sinua vastaan, ja sinä asut skorpionein seassa; mutta ei sinun pidä pelkäämän heidän sanojansa, eikä hämmästymän heidän kasvojansa, vaikka he ovat tottelematoin huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Mutta sinun pitää sanoman heille minun sanani, jos he sen kuulevat taikka katsovat ylön; sillä he ovat vastahakoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Mutta sinä ihmisen lapsi, kuules, mitä minä sinulle sanon, ja älä ole tottelematoin huone. Avaa suus ja syö, mitä minä sinulle annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Ja minä näin, ja katso, käsi oli ojennettu minun puoleeni, ja katso, siinä oli kääritty kirja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Jonka hän avasi minun eteeni, ja se oli kirjoitettu ulkoa ja sisältä; ja siinä olivat kirjoitetut valitukset, ja huokaukset, ja voi!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Ja hän sanoi minulle: sinä ihmisen lapsi, syö mitä sinun edessäs on: syö tämä kirja, ja mene ja saarnaa Israelin huoneelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Niin minä avasin suuni, ja hän antoi sen kirjan minun syödäkseni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Ja hän sanoi minulle: sinä ihmisen lapsi, sinun pitää tämän kirjan, jonka minä annan sinulle, syömän ruumises ja täyttämän sillä vatsas. Niin minä söin sen, ja se oli minun suussani niin makia kuin hunaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Ja hän sanoi minulle: sinä ihmisen lapsi, mene Israelin huoneesen ja saarnaa heille minun sanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Sillä en minä sinua lähetä sen kansan tykö, jolla outo puhe ja vieras kieli on, vaan Israelin huoneesen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Ja en suuren kansan tykö, joilla outo puhe ja vieras kieli olis, joiden puhetta et sinä ymmärrä. Ja jos minä vielä lähettäisin sinun niiden tykö, niin pitäis heidän kuitenkin mielellänsä kuuleman sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Mutta Israelin huone ei tahdo sinua kuulla, sillä ei he tahdo kuulla itse minuakaan; sillä koko Israelin huoneella on kova otsa ja paatunut sydän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Mutta katso, kuitenkin olen minä tehnyt sinun kasvos lujaksi heidän kasvojansa vastaan ja sinun otsas lujaksi heidän otsaansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Ja minä olen tehnyt sinun otas niin kovaksi kuin timantin, joka kovempi on kuin kallio: älä pelkää heitä, älä myös hämmästy heidän edessänsä, ehkä he ovat tottelematoin huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Ja hän sanoi minulle: sinä ihmisen lapsi, kaikki minun sanani, jotka minä sanoin sinulle, ota sinun sydämees ja pane korviis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Ja mene pois sinun kansas vankien tykö, ja saarnaa heille, ja sano heille: näin sanoo Herra, Herra: jos he kuulevat sen, taikka katsovat ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Ja henki otti minun ylös, ja minä kuulin jälissäni suuren humauksen äänen (sanovan): siunattu olkoon Herran kunnia hänen siassansa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Ja minä kuulin eläinten siipien äänen, jotka löivät toiseensa ja ratasten jyrinän, jotka juuri niiden tykönä olivat, ja suuren humauksen äänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Niin henki nosti minut ylös, ja vei minut pois; ja minä menin pois, ja olin suuresti hämmästynyt mutta Herran käsi piti minun vahvana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Ja minä tulin vankien tykö Telabibiin, jotka asuivat Kebarin virran tykönä, ja viivyin heidän tykönänsä, kussa he istuivat, ja olin siellä seitsemän päivää hämmästyksissä heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Ja kuin ne seitsemän päivää olivat kuluneet, tapahtui Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Sinä ihmisen lapsi, minä olen pannut sinun Israelin huoneen vartiaksi; sinun pitää kuuleman sanan minun suustani, ja varaaman heitä minun puolestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Kuin minä sanon jumalattomalle: sinun pitää totisesti kuoleman, ja et sinä varaa häntä etkä sano hänelle sitä, että jumalatoin lakkais jumalattomasta menostansa ja sais elää, niin pitää sen jumalattoman kuoleman synteinsä tähden; mutta hänen verensä tahdon minä vaatia sinun kädestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Mutta jos sinä varaat sitä jumalatointa, ja ei hän käänny jumalattomuudestansa ja jumalattomasta tiestänsä, niin hänen pitää synteinsä tähden kuoleman; mutta sinä olet sielus vapahtanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Ja kuin vanhurskas luopuu vanhurskaudestansa ja tekee pahaa, niin minä sallin hänen loukata itsensä, ja hänen pitää kuoleman; sentähden, ettes ole häntä varannut, pitää hänen synteinsä tähden kuoleman, ja hänen entistä vanhurskauttansa, jonka hän tehnyt on, ei pidä muistettaman; mutta hänen verensä tahdon minä vaatia sinun kädestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Mutta jos sinä varaat vanhurskasta, ettei hän syntiä tekisi, ja ei hän myös syntiä tee, niin pitää hänen totisesti elämän, että hän on neuvon ottanut; olet sinä myös sielus vapahtanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Ja siellä tuli Herran käsi minun päälleni ja sanoi minulle: nouse ja mene ulos kedolle, siellä tahdon minä puhua sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Ja minä nousin ja menin ulos kedolle, ja katso, siellä seisoi Herran kunnia, niinkuin se kunnia, jonka minä Kebarin virran tykönä ennen nähnyt olin; ja minä lankesin maahan kasvoilleni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Ja tulin virvoitetuksi hengessä, ja hän asetti minun jaloilleni, ja puhui minun kanssani, ja sanoi minulle: mene ja sulje itses huoneeses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Ja sinä ihmisen lapsi, katso, nuorat pitää pantaman sinun päälles, ja he sitovat sinun niillä, ettei sinun pidä pääsemän heiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Ja minä tahdon sinun kieles antaa tarttua suus lakeen, niin että sinun pitää tuleman mykäksi, ja ei enään taitaman nuhdella heitä; sillä se on vastahakoinen huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mutta kuin minä puhun sinun kanssas, niin tahdon minä avata sinun suus, että sinun heille sanoman pitää: näin sanoo Herra, Herra: joka kuulee, se kuulkaan, ja joka hylkää, se hyljätkään; sillä se on tottelematoin huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Ja sinä ihmisen lapsi, ota sinulles tiilikivi, pane se etees, ja piirusta sen päälle Jerusalemin kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Ja lyö leiri sen ympärille, ja rakenna siihen aita, ja tee siihen valli, ja aseta siihen sotaväki, ja pane sotaaseet sitä vastaan joka taholta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Mutta ota etees rautapannu, ja anna sen olla rautaisen seinän edestä sinun ja kaupungin välillä, ja aseta kasvos häntä vastaan, niinkuin piiritettävä, ja piiritä se. Se olkoon Israelin huoneelle merkiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Sinun pitää myös makaaman vasemmalla kyljelläs, ja Israelin huoneen pahat teot paneman sen päälle. Niin monta päivää kuin sinä makaat sen päällä, niin kauvan pitää sinun myös kantaman heidän pahoja tekojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Mutta minä tahdon tehdä sinulle heidän pahain tekoinsa vuosikaudet päiviksi: kolmeksisadaksi ja yhdeksäksikymmeneksi päiväksi; niin kauvan pitää sinun kantaman Israelin huoneen pahoja töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Ja kuin ne olet täyttänyt, sitte pitää sinun makaaman Juudan huoneen pahoja töitä neljäkymmentä päivää; sillä minä annan sinulle tässä myös päivän joka vuoden edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Ja aseta kasvos ja paljas käsivartes ympäri piiritettyä Jerusalemia vastaan, ja ennusta häntä vastoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Ja katso, minä panen nuorat sinun päälles, niin ettei sinun pidä saaman kääntää itsiäs yhdeltä kyljeltä toiselle, siihenasti että sinä olet lopettanut piirittämises päivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Niin ota nyt nisuja, rukiita ja ohria, papuja, herneitä ja kauroja, ja pane ne yhteen astiaan, ja tee itselles siitä niin monta leipää kuin monta päivää on, jotka sinun kyljelläs makaaman pitää, että sinulla olis siitä syömistä kolmeksisadaksi ja yhdeksäksikymmeneksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Niin että sinun ruokas, jonka sinun kunakin päivänä syömän pitää, pitää painaman kaksikymmentä sikliä. Tämän sinun syömän pitää yhdestä päivästä niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Vettä pitää sinun myös juoman määrällä, kuudennen osan hinniä; ja sen sinun pitää juoman yhdestä päivästä niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Ohraisia leipiä pitää sinun syömän, jotka sinun heidän silmäinsä edessä ihmisen jäljellä kypsentämän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Ja Herra sanoi: ratki näin pitää Israelin lapset syömän saastaista leipäänsä pakanain seassa, kuhunka minä heitä ajava olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Mutta minä sanoin: voi Herra, Herra, katso, minun sieluni ei ole koskaan vielä saastutettu; sillä en ole minä ikänä, hamasta minun nuoruudestani tähän asti, mitään raatoa taikka raadeltua syönyt, ja ei saastainen liha ole koskaan suuhuni tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Mutta hän sanoi minulle: katso, minä tahdon antaa sinulle karjan sontaa ihmisen jäljen edestä, jolla sinun leipäs tekemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Ja hän sanoi minulle: sinä ihmisen lapsi, katso, minä tahdon ottaa pois leivän aineen Jerusalemista, niin että heidän pitää leipää syömän painolla ja murheella, ja juoman vettä määrällä ja surulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Että leipä ja vesi puuttuman pitää, ja yhden pitää sureman toisen kanssa, ja nääntymän pahoissa teoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Ja sinä, ihmisen lapsi, ota sinulles niin terävä miekka kuin partaveitsi, ja keritse sillä pääs ja partas; ja ota vaaka ja jaa ne sillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Kolmannen osan pitää sinun tulella polttaman keskellä kaupunkia, kuin piirittämisen päivät ovat täytetyt; toinen kolmas osa ota ja hakkaa miekalla kaupungin ympärillä; viimeinen kolmas osa heitä tuleen, että minä vetäisin miekan ulos heidän jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Mutta ota vähä niistä luvalla ja sido hamees kulmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Ja ota taas vähä niistä, ja heitä se tuleen, ja polta se tulessa; siitä pitää tulen tuleman koko Israelin huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Näin sanoo Herra, Herra: tämä on Jerusalem, jonka minä pakanain keskelle asettanut olen, ja maakunnat hänen ympärillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Mutta hän on kääntänyt minun oikeuteni jumalattomuudeksi, enemmin kuin pakanat, ja minun säätyni enemmin kuin ne maakunnat, jotka hänen ympäristöllänsä ovat; sillä he heittävät minun oikeuteni pois, ja ei tahdo elää minun säätyini jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Sentähden sanoo Herra, Herra näin: että te enemmän pahuutta teette kuin pakanat, jotka ovat teidän ympärillänne, ja ette vaella minun säädyissäni, ettekä tee minun oikeuteni jälkeen, ette myös tee pakanainkaan oikeuden jälkeen, jotka ovat teidän ympärillänne:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Sentähden sanoo Herra, Herra näin: katso, minä tulen sinun tykös, minä myös tulen, ja tahdon tuomita sinun pakanain silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Ja tahdon niin tehdä sinun kanssas, kuin en minä ikänä ennen tehnyt ole, enkä myös tästedes tehdä tahdo, kaikkein sinun kauhistustes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Sentähden pitää isäin syömän lapsensa sinun keskelläs, ja lasten syömän isänsä. Ja tahdon sinun niin tuomita, että kaikki sinun jäänees pitää kaikkiin tuuliin hajoitetuksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Sentähden niin totta kuin minä elän, sanoo Herra, Herra: ettäs olet saastuttanut minun Pyhäni kaikilla sinun turmeluksillas ja kaikilla sinun kauhistuksillas, niin tahdon minä myös hukuttaa sinun pois, ja minun silmäni ei pidä sinua säästämän, ei myös armahtaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Kolmas osa sinusta pitää rutolla kuoleman ja nälkään nääntymän sinun keskelläs; ja toinen kolmas osa pitää lankeeman miekalla sinun ympäristölläs; ja sen viimeisen kolmannen osan tahdon minä hajoittaa kaikkiin tuuliin, ja vetää ulos miekan heidän jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Näin pitää minun vihani täytetyksi tuleman, ja minun hirmuisuuteni saatan minä heidän päällensä, että minä saisin lohdutuksen; ja heidän pitää ymmärtämän, että minä Herra minun kiivaudessani puhunut olen, kuin minä hirmuisuuteni heissä täyttänyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Minä tahdon saattaa sinun autioksi ja pilkaksi pakanoille, jotka sinun ympärilläs ovat, kaikkein niiden silmäin eteen, jotka käyvät sieltä ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Ja se häväistys ja pilkka pitää oleman opiksi ja ihmeeksi pakanoille, jotka ovat sinun ympärilläs, kuin minä annan oikeuteni käydä sinun päälles vihan, julmuuden ja rangaistusten kanssa. Minä Herra olen sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Ja kuin minä ne pahat nälän nuolet heidän sekaansa lähettävä olen, jotka vahingolliset oleman pitää, jotka minä lähetän hukkaamaan teitä; ja annan teille nälän enemmäksi ja enemmäksi tulla, ja ottaman pois leivän aineen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Ja nälän ja pahat pedot tahdon minä antaa tulla teidän sekaanne, ne pitää teitä tekemän lapsettomaksi. Ja siellä pitää ruton ja veren liikkuman sinun seassas ja miekan tahdon minä antaa tulla sinun päälles. Minä Herra olen sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Ja Herran sana tapahtui minulle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Sinä ihmisen lapsi, käännä kasvos Israelin vuoria päin, ja ennusta heitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Ja sano: te Israelin vuoret, kuulkaat Herran, Herran sanaa: näin sanoo Herra, Herra sekä vuorille että mäille, sekä ojille että laaksoille: katso, minä, minä tahdon antaa tulla miekan teidän päällenne, ja lyödä teidän kukkulanne maahan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Että teidän alttarinne pitää kukistetuiksi tuleman, ja teidän epäjumalanne rikki lyödyksi; ja minä tahdon antaa teidän ruumiinne tapettaa kuvainne eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Ja lyödä maahan Israelin lasten ruumiit teidän kuvainne eteen, ja hajoittaa teidän luunne ympäri teidän alttareitanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Kussa te ikänä asutte, pitää kaupungit kylmille tuleman, ja kukkulat hävitettämän, että teidän alttarinne pitää lyötämän maahan ja autioksi tehtämän, ja rikottaman teidän epäjumalanne ja hävitettämän, ja särjettämän teidän kuvanne ja teidän työnne tyhjäksi tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Ja maahan lyödyt pitää makaaman teidän seassanne, että teidän tietämän pitää minun olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Mutta minä tahdon antaa muutamat teistä jäädä, jotka pitää miekalta jäämän pakanain sekaan, kuin minä teitä maakuntiin hajoittanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Jääneet teistä pitää muistaman minua pakanain seassa, kussa heidän vankina oleman pitää, että minä olen särjetty heidän haureellisen sydämensä tähden, joka minusta luopunut on, ja heidän kiiluvain silmäinsä tähden, jotka ovat katsoneet epäjumaltensa jälkeen; ja niiden pitää suuttuman itseensä sen pahuuden tähden, jotka he kaikkein kauhistustensa kautta tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Ja heidän pitää tietämän, että minä olen Herra; ja en ole hukkaan puhunut, tehdäkseni heille tätä pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Näin sanoo Herra, Herra: lyö käsiäs yhteen, ja tömistä jalkojas, ja sano: voi! kaikkea pahuuden kauhistusta Israelin huoneessa, jonka tähden he miekan, nälän ja ruton kautta lankeeman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Se joka kaukana on, hänen pitää ruttoon kuoleman, ja se joka juuri läsnä on, hänen pitää miekalla lankeeman; mutta se joka jää ja niistä päässyt on, sen pitää nälkään kuoleman. Näin tahdon minä täyttää minun hirmuisuuteni heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Ja teidän pitää tietämän, että minä olen Herra, kuin heidän tapettunsa pitää makaaman heidän epäjumaltensa seassa ympäri heidän alttareitansa, kaikilla vuorten kukkuloilla, ja kaikkein viheriäisten puiden alla, ja kaikkein paksuin tammien alla, joissa paikoissa he kaikille epäjumalillensa makiaa savu-uhria tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Minä tahdon ojentaa käteni heitä vastaan ja tehdä heidän maansa tyhjäksi ja autioksi, hamasta Diblatin korvesta, kaikissa heidän asumasioissansa; ja heidän pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Sinä ihmisten lapsi, näin sanoo Herra, Herra, Israelin maasta: loppu tulee; koko neljän maan äären loppu tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nyt tulee sinun loppus; sillä minä tahdon lähettää minun hirmuisuuteni sinun päälles, ja tuomita sinua, niinkuin sinä ansainnut olet, ja antaa sinulle, mitä kaikkiin sinun kauhistuksiis tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Minun silmäni ei pidä säästämän sinua, eikä armahtaman; mutta minä tahdon antaa sinulle, niinkuin sinä ansainnut olet, ja sinun kauhistukses pitää tuleman sinun sekaas, että teidän tietämän pitää, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Näin sanoo Herra, Herra: katso, yksi onnettomuus tulee toisen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Loppu tulee, loppu tulee; se valvoo sinua vastaan; katso, se tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Se käy jo ylös ja tulee niinkuin aamu sinun päälles, sinä joka maassa asut; aika tulee, tuskapäivä on juuri läsnä, ettei vuorilla pidä laulettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nyt tahdon minä pian vuodattaa minun hirmuisuuteni sinun päälles, ja täyttää vihani sinussa ja tuomita sinun, niinkuin sinä ansainnut olet, ja antaa sinulle, mitä kaikkiin sinun kauhistuksiis tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Minun silmäni ei pidä säästämän sinua eikä armahtaman; minä tahdon antaa sinulle, niinkuin sinä ansainnut olet, ja sinun kauhistukses pitää tuleman sinun sekaas, että teidän tietämän pitää, että minä olen Herra, joka teitä lyön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Katsos päivää, katso, se tulee; aamu tulee edes, vitsa kukoistaa, ja ylpiä viheriöitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Tyranni on itsensä valmistanut jumalattomain vitsaksi, niin ettei kenkään heitä eli heidän kansaansa taikka heidän joukkoansa pidä valittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Aika tulee, päivä lähestyy, ostaja älköön iloitko, ja myyjä älköön murehtiko; sillä viha tulee kaiken heidän joukkonsa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Sillä myyjän ei pidä enään myydyn kalunsa tykö palajaman, vaikka he vielä hengissäkin olisivat; sillä ennustus kaikesta heidän paljoudestansa ei pidä käymän takaperin, eikä kenkään taida vahvistaa elämäänsä pahuutensa kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Soittakaat vaskitorveen, ja valmistakaat kaikki; ei kuitenkaan yksikään sotaan ole lähtevä; sillä minun vihani tulee kaiken hänen kansansa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Ulkona liikkuu miekka, sisällä rutto ja nälkä; se joka kedolla on, hänen pitää miekalla lankeeman, mutta se joka kaupungissa on, hänen pitää ruttoon ja nälkään vaipuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Ja jotka heiltä pääsevät pakoon, pitää oleman vuorilla niinkuin kyhkyiset laaksoissa, ja kaikkein pitää valittaman, kukin pahuuttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Kaikki kädet pitää nääntymän, ja kaikki polvet horjuman niinkuin vesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Ja heidän pitää itsensä säkkiin puettaman, ja pelko pitää heidät peittämän, ja kaikki kasvot surkiasti katsoman, ja kaikki päät paljaaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Heidän pitää hopiansa heittämän kaduille, ja heidän kultansa kauvas joutuman; sillä heidän hopiansa ja kultansa ei pidä taitaman auttaa heitä Herran vihan päivänä; ja ei taitaman sieluansa ravita, eikä vatsaansa täyttää; sillä se on ollut heille pahennus, heidän pahoihin töihinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Kalliista kaluistansa, joilla he ylpeilivät, ovat he kauhistustensa ja epäjumalainsa kuvat tehneet; sentähden tahdon minä tehdä heille sen saastaisuudeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Ja antaa sen muukalaisten käsiin, että ne sen ryöväämän pitää, ja jumalattomille maan päällä saaliiksi, että ne sen saastuttavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Minä tahdon minun kasvoni kääntää sieltä pois, että he juuri minun majani turmelevat; ja ryövärit pitää tuleman sinne, ja sen saastuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Tee kahleet; sillä maa on täynnä veren vikoja, ja kaupunki täysi väkivaltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Niin tahdon minä antaa tulla kaikkein pahimmat pakanain seasta, että ne pitää heidän huoneensa omistaman, ja tahdon lopettaa voimallisten ylpeyden, ja heidän pyhänsä pitää saastutetuksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Hävittäjä tulee; niin pitää heidän rauhaa etsimän, ja ei se pidä oleman heillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Yksi onnettomuus pitää tuleman toisen jälkeen, yksi sanoma toisen päälle, niin pitää heidän prophetailta näkyä etsimän; mutta siellä ei laki enään ole pappien tykönä, eikä neuvo vanhain tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Kuninkaan pitää murheessa oleman ja päämiehet surullisissa vaatteissa, ja maassa kansan kädet vapiseman. Minä tahdon niin laittaa itseni heidän kanssansa, kuin he eläneet ovat, ja tuomita heitä, niinkuin he ansainneet ovat: ja heidän pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Ja tapahtui kuudentena vuonna, viidentenä päivänä kuudennetta kuuta, että minä istuin huoneessani, ja Juudan vanhimmat istuivat minun edessäni: siellä tuli Herran, Herran käsi minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Ja minä näin, ja katso, se mikä oli hänen kupeensa alla, se oli niinkuin tuli; mutta päältä hänen kupeensa oli se sangen kirkas, niinkuin kaikkein kirkkain valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Ja hän ojensi ulos niinkuin käden, ja otti minun kiinni pääni hiuksista; niin otti minun henki ylös maan ja taivaan välille, ja vei minun Jerusalemiin Jumalan näyissä, sisällisen oven tykö, joka pohjan puolessa on, kussa kiivauksen kuva seisoi, joka kiivauksen kehoitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Ja katso, siellä oli Israelin Jumalan kunnia, niinkuin minä sen ennen nähnyt olin kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Ja hän sanoi minulle: sinä ihmisen lapsi, nosta nyt silmäs pohjoiseen päin. Ja kuin minä silmäni nostin pohjan puoleen, katso, niin seisoi kiivauksen kuva pohjan puolessa alttariportin tykönä, kusta käydään sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Ja hän sanoi minulle: sinä ihmisen lapsi, näetkös, mitä nämät tekevät? niitä suuria kauhistuksia, jotka Israelin huone tässä tekee, että he juuri ajavat minun kauvas minun Pyhästäni? Mutta sinun pitää vielä nyt näkemän suuremmat kauhistukset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Ja hän vei minun kartanon porttiin: siellä minä näin, ja katso, siellä oli läpi seinässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Ja hän sanoi minulle: sinä ihmisen lapsi, kaiva nyt seinä lävitse. Ja kuin minä kaivoin seinän lävitse, katso, niin oli siellä yksi ovi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Ja hän sanoi minulle: mene sisälle ja katso niitä ilkeitä kauhistuksia, joita he tässä tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Ja kuin minä menin sisälle ja katsoin, katso, siellä olivat kaikkinaiset matoin ja eläinten kuvat, kaikki tyynni kauhistus, ja kaikkinaiset Israelin huoneen epäjumalat, joka paikkaan ympäri seiniä tehdyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Joiden edessä seisoivat seitsemänkymmentä miestä Israelin huoneen vanhimmista, ja Jasania Saphanin poika seisoi myös heidän seassansa, ja jokaisella heillä oli pyhän savun astia kädessä, ja paksu löyhkä kävi ylös savu-uhrista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Ja hän sanoi minulle: sinä ihmisen lapsi, näetkös, mitä Israelin huoneen vanhimmat tekevät pimeydessä, itsekukin kauniimmassa kammiossansa? sillä he sanovat: ei Herra näe meitä, Herra on maan hyljännyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Ja hän sanoi minulle: sinun pitää vielä nyt näkemän suurempia kauhistuksia, joita he tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Ja hän vei minut sen portin tykö, Herran huoneessa, joka on pohjan puolessa, ja katso, siellä istuivat vaimot, jotka itkivät Tammusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Ja hän sanoi minulle: sinä ihmisen lapsi, näetkös näitä? Mutta sinun pitää vielä nytkin suurempia kauhistuksia näkemän, kuin nämät ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Ja hän vei minun sisälliseen kartanoon Herran huoneesen päin, ja katso, Herran templin oven edessä, esihuoneen ja alttarin välillä, oli lähes viisikolmattakymmentä miestä, jotka olivat kääntäneet selkänsä Herran templin puoleen ja kasvonsa itään, ja rukoilivat auringon ylenemiseen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Ja hän sanoi minulle: sinä ihmisen lapsi, näetkös näitä? Onko tämä Juudan huoneelle vähä, että he tässä näitä kauhistuksia tekevät, jotka myös muutoin koko maan vääryydellä täyttävät, ja asettavat itsensä minua vihoittamaan? Ja katso, he pitävät viinapuun oksan nenänsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Sentähden tahdon minä myös tehdä minun hirmuisuudessani, ja ei pidä minun silmäni säästämän enkä minä armahda heitä; ja he huutavat korkialla äänellä minun korvissani, en minä kuitenkaan kuule heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Ja hän huusi korkialla äänellä minun korvissani ja sanoi: se on jo käsissä, että kaupunki pitää rangaistaman, ja jokaisella on murha-ase kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Ja katso, kuusi miestä tuli ylimmäisen portin tietä, joka pohjan puolessa on, ja jokaisella oli vahingollinen ase kädessänsä. Mutta yksi mies heidän seassansa oli liinavaatteilla vaatetettu, ja kirjoitustaulu hänen vyöllänsä; ja he menivät sisälle, ja astuivat vaskialttarin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Ja Israelin Jumalan kunnia nousi Kerubimin päältä, jonka päällä hän oli, ja lähestyi huoneen kynnykseen asti, ja huusi sitä miestä, jonka yllä oli liinavaate, ja kirjoitustaulu vyöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Ja Herra sanoi hänelle: mene Jerusalemin kaupungin lävitse, ja kirjoita ne miehet heidän otsissansa, jotka huokaavat ja huutavat sitä kauhistusta, joka siinä tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Mutta muille sanoi hän, minun kuulteni: menkäät hänen jälissänsä kaupungin lävitse, ja lyökäät; teidän silmänne ei pidä säästämän, eikä armoa tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Lyökäät sekä vanhat että nuoret, neitseet, lapset ja vaimot kuoliaaksi; mutta joiden päällä kirjoitus on, ei yhteenkään niihin pidä teidän rupeeman. Ruvetkaat ensin minun Pyhästäni. Ja he rupesivat niistä vanhoista miehistä, jotka huoneen edessä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Ja hän sanoi heille: saastuttakaat huone, ja täyttäkäät kartanot tapetuilla, menkäät sitte ulos. Ja he menivät ulos ja tappoivat kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Ja kuin he olivat tappaneet heidät, jäin minä vielä, ja lankesin kasvoilleni, huusin ja sanoin: ah Herra, Herra, tahdotkos siis hukuttaa kaikki jääneet Israelissa, ettäs niin vuodatat sinun vihas Jerusalemin päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Ja hän sanoi minulle: Israelin ja Juudan huoneen paha työ on sangen suuri, maa on täytetty murhalla, ja kaupunki täynnä pahuutta. Sillä he sanovat: Herra on hyljännyt maan, ja ei Herra näe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Sentähden ei minun silmäni pidä säästämän, enkä minä tahdo armahtaa; mutta minä tahdon antaa heidän päänsä päälle, niinkuin he ansainneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Ja katso, se mies, jonka yllä liinavaate oli, ja kirjoitustaulu vyöllä, vastasi ja sanoi: minä olen tehnyt, niinkuin sinä minulle käskenyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Ja minä näin, ja katso, taivaassa oli Kerubimin päällä niinkuin saphir, ja niiden päällä niinkuin istuin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Ja hän sanoi sille miehelle, joka oli liinavaatteissa: mene sisälle ratasten välille Kerubimin aalle, ja ota kätes täyteen tulisia hiiliä, jotka Kerubimin välillä ovat, ja hajoita ne kaupungin päälle; ja hän meni sisälle minun silmäini edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Mutta Kerubimit seisoivat oikialla puolella huoneessa, kuin mies sisälle meni, ja sumu täytti sisällisen kartanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Ja Herran kunnia nousi Kerubimin päältä huoneen kynnykseen asti, ja huone täytettiin sumulla ja kartano Herran kunnian kirkkaudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Ja Kerubimin siipein humaus kuului hamaan ulkonaiseen kartanoon asti, niinkuin kaikkivaltiaan Jumalan ääni kuin hän puhuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Ja kuin hän oli käskenyt miestä, joka oli liinavaatteissa, ja sanonut: ota tulta ratasten keskeltä Kerubimin alta; niin hän meni sinne sisälle, ja astui rattaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Ja Kerubim ojensi kätensä keskellä Kerubimeja, tuleen päin, joka oli Kerubimin välillä, otti siitä ja antoi sen miehen käsiin, joka oli liinavaatteissa; ja hän otti sen ja meni ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Ja näkyi Kerubimeissa, niikuin ihmisen käsi heidän siipeinsä alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Ja minä näin, ja katso, neljät rattaat seisoivat Kerubimein tykönä, jokaisen Kerubimin tykönä yhdet rattaat, ja rattaat olivat näköänsä niinkuin turkos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Ja olivat kaikki ne neljä yksi niinkuin toinenkin, niinkuin yhdet rattaat olisivat olleet toisten sisällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Kuin yksi heistä meni, niin menivät kaikki neljä, ja ei erinneet toinen toisestansa kulkeissansa; mutta kuhunka ensimmäinen meni, sinne menivät ne jälissä, ja ei erinneet toinen toisestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Ja heidän koko ruumiinsa, selkänsä, kätensä ja siipensä, niin myös rattaat olivat täynnä silmiä kaikki ympärinsä, ne neljät rattaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Ja rattaille sanottiin: pyörikäät, niin että minä sen kuulin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Niin oli myös jokaisella eläimellä neljät kasvot: yhdet kasvot olivat ihmisen kasvot, toiset kasvot olivat ihmisen kasvot, kolmannet jalopeuran kasvot, ja neljännet kotkan kasvot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Ja Kerubimit korotettiin. Tämä on se eläin, jonka minä näin Kebarin virran tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Kuin Kerubimit kävivät, niin kulkivat myös rattaat heitä myöten; ja kuin Kerubimit nostivat siipiänsä, maasta nousemaan, niin ei myös rattaat heistä erinneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Kuin he seisoivat, niin seisoivat nämät myös, kuin he nousivat, niin nousivat myös nämät; sillä elävä henki oli heissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Ja Herran kunnia meni taas huoneen kynnykseltä, ja istui Kerubimein päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Niin ylentelivät Kerubimit siipiänsä, ja nousivat maasta ylös, minun silmäini edessä; ja kuin he menivät ulos, menivät rattaat heitä myöten; ja he astuivat idän puoleiselle ovelle Herran huonetta, ja Israelin kunnia oli heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Tämä on se eläin, jonka minä näin Israelin Jumalan alla Kebarin virran tykönä; ja minä tunsin ne olevan Kerubimit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Jokaisella olivat neljät kasvot ja neljä siipeä, ja siipein alla niinkuin ihmisen kädet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Heidän kasvonsa olivat niinkuin minä ne näin Kebarin virran tykönä; ja ne kukin kävivät kohdastansa eteensä päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Ja henki nosti minun ylös ja vei minun portin eteen Herran huoneen puoleen, joka itään päin on, ja katso: portissa oli viisikolmattakymmentä miestä. Ja minä näin niiden seassa Jasanian Assurin pojan, ja Pelatian Benajan pojan, kansan päämiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Ja hän sanoi minulle: sinä ihmisen poika, näillä miehillä ovat väärät ajatukset ja vahingolliset neuvot tässä kaupungissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Jotka sanovat: ei se vielä niin läsnä ole, rakentakaamme huoneita; tämä on pata, me olemme liha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Sentähden ennusta sinä heitä vastaan, ennusta, sinä ihmisen poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Ja Herran henki lankesi minun päälleni, ja sanoi minulle: sano: näin sanoo Herra: te Israelin huoneesta olette niin puhuneet: minä tiedän kyllä teidän henkenne ajatukset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Te olette monta tappaneet tässä kaupungissa, ja hänen katunsa täyttäneet tapetuilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Sentähden sanoo Herra, Herra näin: ne jotka te siellä tappaneet olette, ne ovat liha, ja tämä on pata; mutta minä tahdon teitä viedä tästä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Miekan, jota te pelkäätte, annan minä tulla teidän päällenne, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Minä tahdon ajaa teitä sieltä ulos, ja antaa teitä muukalaisten käsiin, ja tehdä teille oikeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Teidän pitää miekalla lankeeman; Israelin maan äärissä minä tahdon tuomita teitä, ja teidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Mutta ei tämä pidä oleman teidän patanne, ettekä te lihana siinä; vaan Israelin maan äärissä tahdon minä tuomita teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Ja teidän pitää ymmärtämän, että minä olen Herra; sillä ette ole vaeltaneet minun säätyini jälkeen, ja ette ole pitäneet minun oikeuksiani, mutta olette tehneet pakanain tavan jälkeen, jotka teidän ympärillänne ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Ja kuin minä näin ennustin, niin Pelatia Benjan poika kuoli. Ja minä lankesin kasvoilleni, ja huusin korkialla äänellä ja sanoin: Voi Herra, Herra, sinä lopetat peräti Israelin jääneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Niin tuli Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Sinä ihmisen poika, ne ovat sinun veljes, sinun veljes ja lähimmäiset lankos, ja koko Israelin huone, joille Jerusalemin asuvaiset sanoneet ovat: menkäät kauvas Herrasta, maa on meille annettu omaisuudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Sentähden sano sinä: näin sanoo Herra, Herra: totta minä olen antanut ajaa heitä kauvas pakanain sekaan, ja olen tosin hajoittanut heitä maakuntiin, niin tahdon minä kuitenkin äkisti olla heidän pyhityksensä niissä maakunnissa, joihinka he joutuneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Sano sentähden: näin sanoo Herra, Herra: minä tahdon koota teitä niistä kansoista, ja koota teitä niistä maakunnista, joihinka te hajoitetut olette, ja tahdon antaa teille Israelin maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Sinne pitää heidän tuleman ja ottaman sieltä ulos kaiken hänen saastaisuutensa ja kaikki hänen kauhistuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Ja minä tahdon antaa heille yhden sydämen, ja antaa teihin uuden hengen, ja tahdon ottaa pois kivisen sydämen heidän lihastansa, ja antaa heille lihaisen sydämen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Että heidän pitää vaeltaman minun säädyissäni, ja pitämän minun oikeuteni, ja tekemän sen jälkeen; ja heidän pitää oleman minun kanssani, ja minä tahdon olla heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Mutta niille, jotka vaeltavat sydämensä kauhistuksen ja hirmuisuuden jälkeen, niille minä tahdon panna heidän tekonsa heidän päänsä päälle, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Niin nostivat Kerubimit siipiänsä, ja rattaat kävivät heidän sivussansa, ja Israelin Jumalan kunnia oli heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Ja Herran kunnia kävi keskellä kaupunkia ylös, ja asettui sille vuorelle, joka on itään päin kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Ja henki otti minun, ja johdatti minun näyssä ja Jumalan hengessä Kaldean maalle vankien tykö; ja se näky, jonka minä näin, katosi minun edestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Ja minä sanoin vangeille kaikki Herran sanat, jotka hän minulle osoittanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Ja Herran sana tuli minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Ihmisen poika, sinä asut kovakorvaisen kansan seassa, jolla kyllä silmät ovat nähdä, ja ei kuitenkaan tahdo nähdä, ja korvat kuulla, eikä tahdo kuitenkaan kuulla; sillä se on tottelematoin huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Sentähden sinä ihmisen poika, tee itselles vaellusaseet, ja vaella valkialla päivällä heidän silmäinsä edessä; sinun pitää vaeltaman siastas toiseen paikkaan heidän silmäinsä edessä, jos he, mitämaks, tahtovat ymmärtää, että he kovakorvainen kansa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Ja sinun pitää tuoman sinun asees edes, niinkuin sinä tahtoisit vaeltaa valkialla päivällä heidän silmäinsä edessä, niiden uloslähtemisen tavalla, jotka vaeltaa tahtovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Ja sinun pitää murtaman sinuas seinän lävitse heidän silmäinsä edessä, ja menemän siitä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Ja olallas kantaman heidän silmäinsä edessä, ja kuin pimiä tullut on, menemän matkaas. Sinun pitää kasvos peittämän, ettet sinä saa nähdä maata; sillä minä olen pannut sinun ihmeeksi Israelin huoneelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Ja minä tein, niinkuin minulle käsketty oli, ja kannoin aseeni edes, niikuin minun piti vaeltaman valkialla päivällä, ja ehtoona kangotin minä itseni lävitse seinän kädellä. Ja kuin pimiä oli tullut, otin minä sen olalleni ja kannoin sen ulos heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Ja huomeneltain varhain tuli Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Sinä ihmisen poika, eikö Israelin huone, tottelematoin huone, ole sanonut sinulle: mitä sinä teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Niin sano siis heille: näin sanoo Herra, Herra: tämä kuorma tulee päämiehen päälle Jerusalemissa, ja koko Israelin huoneen päälle, joka siellä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Sano siis: minä olen teidän ihmeenne: niinkuin minä tehnyt olen, niin teille tapahtuman pitää, että teidän pitää vaeltaman ja vankina vietämän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Heidän päämiehensä pitää vietämän pois olkapäillä pimeydessä, ja pitää käymän ulos seinän lävitse, jonka heidän särkemän pitää, että heidän pitää vaeltaman sen lävitse; hänen kasvonsa pitää peitettämän, ettei hän yhdelläkään silmällä näe maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Minä tahdon myös heittää minun verkkoni hänen päällensä, että hän minun verkollani pitää otettaman kiinni; ja minä tahdon antaa hänen tulla Babeliin Kaldean maalle, jota ei hänen kuitenkaan näkemän pidä, ja siellä hänen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Ja kaikki, jotka ovat hänen ympärillensä, hänen apumiehensä, ja kaiken sotajoukkonsa tahdon minä hajoittaa kaikkiin tuuliin, ja vetää ulos miekan heidän jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Ja niin heidän pitää ymmärtämän, että minä olen Herra, kuin minä ajan heitä pois pakanain sekaan, ja hajoitan heitä maakuntiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Mutta minä tahdon muutamia harvoja heistä tallella pitää miekan, nälän ja ruton edestä; että heidän pitää jutteleman kaikki kauhistuksensa pakanain seassa, kuhunka heidän tuleman pitää, ja ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Ja Herran sana tuli minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Sinä ihmisen poika, sinun pitää syömän leipäs vavistuksella, ja juoman vetes väristyksellä ja murheella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Ja sanoman maakunnan kansalle: näin sanoo Herra, Herra Jerusalemin asuvaisista Israelin maalla: heidän pitää syömän leipänsä murheessa, ja juoman vetensä vaivaisuudessa; sillä maa pitää hävitetyksi tuleman kaikista, mitä siinä on, kaikkein asuvaisten pahuuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Ja ne kaupungit, jotka hyvin asetetut ovat, pitää tyhjäksi ja maa kylmille tuleman; ja niin teidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Ja Herran sana tuli minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Sinä ihmisen poika, mikä sananlasku on teillä Israelin maalla, että te sanotte: että se viipyy niin kauvan, niin kaikki ennustus turhaan raukee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Sentähden sano heille: näin sanoo Herra, Herra: minä tahdon hyljätä sen sananlaskun, ettei sitä enään pidä pidettämän Israelissa; ja sano heille: aika on juuri läsnä, ja kaikki, mitä ennustettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Sillä tästedes ei yksikään näky pidä puuttuman, eikä ennustus valehteleman Israelin huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Sillä minä Herra sen puhun, mitä minä puhun, sen pitää tapahtuman, ja ei edemmä viivytettämän; mutta teidän ajallanne, sinä tottelematoin huone, pitää minun tekemän sen minkä minä puhun, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Ja Herran sana tuli minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Sinä ihmisen poika: katso, Israelin huone sanoo: se näky, jonka tämä näkee, on vielä kaukana, ja ennustaa siitä ajasta, joka vielä nyt kaukana on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Sentähden sano heille: näin sanoo Herra, Herra: ei yhtään minun sanastani pidä enään viivytetyksi tuleman; mutta se sana, jonka minä puhun, pitää tapahtuman, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Sinä ihmisen poika, ennusta Israelin prophetaita vastaan, jotka ennustavat, ja sano niille, jotka omasta sydämestänsä ennustavat: kuulkaat Herran sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Näin sanoo Herra, Herra: voi niitä hulluja prophetaita, jotka omaa henkeänsä seuraavat, ja ei ole mitään nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Israel, sinun prophetas ovat niinkuin ketut korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Ei he astu ylös särjetyn paikan eteen, eikä aseta heitänsä muuriksi Israelin huoneen ympärille, ja ei ole seisovaiset sodassa Herran päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Heidän näkynsä on tyhjä, ja heidän ennustuksensa on valhe; he sanovat: Herra on sen sanonut, vaikka ei Herra ole heitä lähettänyt; ja ahkeroitsevat pitääksensä sanansa vahvana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Eikö teidän näkynne ole turha, ja teidän ennustuksenne kaikki tyynni valhe? Te sanotte: Herra on sen sanonut, ja en minä kuitenkaan ole sitä sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Sentähden sanoo Herra, Herra näin: että te puhutte turhaa ja ennustatte valhetta, niin minä tahdon teidän tykönne, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Ja minun käteni tulee niiden prophetain päälle, jotka näkevät turhaa ja ennustavat valhetta. Ei heidän pidä oleman minun kansani seurakunnassa, ja ei Israelin huoneen kirjoituksessa kirjoitetut oleman, taikka tuleman Israelin maalle; ja teidän pitää ymmärtämän, että minä olen Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Sentähden, tosin sentähden, että he viettelevät minun kansani, sanoen: rauha, ja ei siellä ole rauhaa; tämä (kansa) rakentaa seinän; mutta he sivuvat sen sekoittamattomalla kalkilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Sanos niille, jotka sekoittamattomalla kalkilla sivuvat, että sen pitää putooman; sillä iso sade on tuleva, ja suuret rakeet lankeevat, ja tuulispää sitä syöksemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Katso, niin pitää seinän lankeeman; eikö silloin teille sanota: kussa nyt se pyyhkimys on, jonka te sivunneet olette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Näin sanoo Herra, Herra: minä tahdon antaa pauhata suuren tuulispään minun julmuudessani, ja ison sateen minun vihassani, ja suuria raekiviä minun hirmuisuudessani; ne pitää kaikki maahan lyömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Ja niin minä lyön seinän alas, jonka te sekoittamattomalla kalkilla sivunneet olette, ja heitän sen maahan, niin että sen perustus pitää näkymän, ja että se maahan kaatuu, ja teidän myös pitää siinä hukkuman, ja ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Ja niin minä tahdon täyttää minun hirmuisuuteni seinän päälle ja niiden päälle, jotka sen sekoittamattomalla kalkilla sivuvat, ja sanoa teille: ei täällä ole seinää, eikä yhtään sivujaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Nämät ovat Israelin prophetat, jotka Jerusalemille ennustavat ja näkevät hänelle rauhan näkyjä; ja ei siellä rauhaa ole, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Ja sinä ihmisen poika, aseta kasvos kansas tyttäriä vastaan, jotka ennustavat sydämestänsä, ja ennusta heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Ja sano: näin sanoo Herra, Herra: voi teitä, jotka ompelette ihmisille pehmityksiä kainalon alle, ja päänalasia sekä nuorille että vanhoille, käsittääksenne sieluja. Kuin te nyt olette käsittäneet minun kansani sielut, niin te lupaatte heille elämän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Ja saastutatte minun, minun kansani seassa, ohrapivon ja leivän palan tähden, että te tuomitsette ne sielut kuolemaan, jotka ei pidä kuoleman, ja tuomitsette ne elämään, jotka ei pidä elämän, teidän valheenne kautta minun kansani seassa, jotka mielellänsä valhetta kuulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Sentähden näin sanoo Herra, Herra: katso, minä tahdon teidän pehmityksenne tykö, jolla te sieluja käsitätte ja uskotatte, ja tahdon ne repiä pois teidän kainalonne alta, ja tahdon pelastaa ne sielut, jotka te käsitätte ja uskotatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Ja tahdon teidän päänalaisenne reväistä rikki, ja pelastaa minun kansani teidän kädestänne, ettei teidän pidä heitä enään käsittämän; ja teidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Että te petollisesti saatatte surulliseksi vanhurskaan sydämen, jota en minä ole surulliseksi tehnyt, ja olette vahvistaneet jumalattoman kädet, niin ettei se palajaisi pahasta tiestänsä, ja sais elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Sentähden ei teidän pidä enään saarnaaman turhaa oppia, eikä ennustusta ennustaman; mutta minä tahdon vapahtaa minun kansani teidän kädestänne, ja teidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Ja minun tyköni tuli monikahtoja Israelin vanhimpia ja he istuivat minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Niin tapahtui Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Sinä ihmisen poika, nämät miehet riippuvat sydämellänsä epäjumalissansa, ja pysyvät lujana vääryytensä pahennuksessa: pitäisikö heidän ollenkaan minulta kysymän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Sentähden puhuttele heitä ja sano heille: näitä sanoo Herra, Herra: kuka ihminen Israelin huoneesta riippuu sydämellänsä epäjumalissansa, ja pysyy lujana vääryytensä pahennuksessa, ja tulee prophetan tykö, niin tahdon minä Herra vastata häntä, niinkuin hän ansainnut on suurella epäjumalan palveluksellansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Että Israelin huone pitää vietellyksi tuleman sydämissänsä: sentähden että he kaikki ovat minusta luopuneet epäjumalainsa kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Sentähden pitää sinun sanoman Israelin huoneelle: näitä sanoo Herra, Herra: kääntäkäät itsenne ja luopukaat teidän epäjumalan palveluksestanne, ja kääntäkäät teidän kasvonne kaikesta teidän kauhistuksestanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Sillä kuka ihminen Israelin huoneesta, taikka joku muukalainen, joka Israelissa asuu, luopuu minusta ja sydämellänsä riippuu epäjumalissa, ja lujana pysyy epäjumalansa palveluksen pahennuksessa, ja tulee prophetan tykö kysymään minulta hänen kauttansa, hänelle minä Herra tahdon itse vastata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Ja tahdon asettaa minun kasvoni häntä vastaan, ja tehdä häntä autioksi, ihmeeksi ja sananlaskuksi, ja hävittää hänen minun kansastani: ja teidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Mutta jos vietelty propheta jotakin saarnaa, hänen minä Herra annan vietellyksi tulla; ja tahdon ojentaa minun käteni hänen päällensä, ja hävittää hänen minun kansastani Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Ja niin heidän molempain pitää väärän tekonsa maksun saaman; niinkuin kysyjän väärä teko, niin pitää myös prophetan väärä teko oleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Ettei Israelin huone enään pidä erhettymän minua seuraamasta, ja ei enempi saastuttaman itsiänsä kaikissa ylitsekäymisissänsä; mutta heidän pitää oleman minun kansani, ja minä tahdon olla heidän Jumalansa, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Sinä ihmisen poika, kuin maakunta syntiä tekee minua vastaan, ja pyrkii edespäin synnissä, niin minä tahdon ojentaa minun käteni sen päälle, ja ottaa leivän aineen pois, ja lähettää nälän sinne, hukuttaakseni siellä sekä ihmiset että eläimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Ja jos vielä ne kolme miestä, Noa, Daniel ja Job siellä olisivat, niin he ainoastaan pelastaisivat sielunsa vanhurskaudellansa, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Ja jos minä antaisin tulle pahat pedot maakuntaan, jotka sen tekisivät lapsettomaksi ja hävittäisivät, niin ettei yksikään siellä taitaisi vaeltaa petoin tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Ja nämät kolme miestä olisivat siellä, niin totta kuin minä elän, sanoo Herra, Herra, ei pitäisi heidän taitaman vapahtaa poikia eikä tyttäriä; vaan ainoastaan itse vapahdettaman, ja maa autioksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Taikka jos minä antaisin tulla miekan sen maan päälle, ja sanoisin: miekka, käy maan lävitse, ja niin tulisivat sekä ihmiset että eläimet hävitetyksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Ja ne kolme miestä olisivat siellä, niin totta kuin minä elän, sanoo Herra, Herra, ei heidän pitäisi taitaman pelastaa poikia eli tyttäriä, vaan ainoastaan he itse tulisivat vapahdetuiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Taikka jos minä lähettäisin ruton siihen maakuntaan, ja vuodattaisin minun vihani sen päälle verellä, hävittämään sieltä ihmisiä ja eläimiä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Ja Noa, Daniel ja Job olisivat siellä, niin totta kuin minä elän, sanoo Herra, Herra, ei heidän pitäisi taitaman auttaa poikia eli tyttäriä, vaan ainoasti vanhurskaudellansa pelastamaan omia sielujansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Sillä näin sanoo Herra, Herra: kuin minä lähetän ne neljä minun pahaa rangaistustani, miekan, nälän ja pahat pedot, ja ruton Jerusalemiin, hävittämään siellä sekä ihmiset että eläimet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Ja katsos, niin pitää muutamia sinne jätetyitä kirvoitettaman, poikia ja tyttäriä; ja katso, heidän pitää tuleman tänne teidän tykönne, että teidän pitää näkemän, kuinka heidän käy, ja lohduttaman teitä sen onnettomuuden tähden, jonka minä Jerusalemille olen antanut tulla, ja kaikkein muiden tähden, jotka minä olen antanut tulla heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'He pitää oleman teidän lohdutuksenne, kuin te saatte nähdä, kuinka heidän käy, ja taidatte ymmärtää, etten minä ilman syytä tehnyt ole kaikkia, mitä minä siellä tehnyt olen, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Sinä ihmisen poika, mitä on viinapuu parempi muita puita, eli viinapuun oksa parempi metsäpuita?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Otetaanko siitä puu tehtää jotain työtä? taikka tehdäänkö niistä koukku, johonka jotakin ripustetaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Katso, se heitetään tuleen kulutettavaksi, niin että tuli molemmat päät kuluttaa, ja hänen keskipaikkansa palaa: mihinkä se nyt pitäis kelpaaman, kelvanneeko se mihinkään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Katso, kuin se vielä kokonainen oli, ei siitä silloinkaan taidettu mitään tehdä: kuinka paljo vähemmin taidetaan tästälähin siltä jotakin tehdä, kuin tuli sen kuluttanut ja polttanut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Sentähden näin sanoo Herra, Herra: niinkuin minä annan viinapuun oksat tulella poltettaa metsäpuiden kanssa, niin pitää myös minun tekemän Jerusalemin asuvaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Ja tahdon asettaa minun kasvoni heitä vastaan, ettei heidän pidä välttämän tulta; mutta tulen pitää heitä polttaman. Ja teidän pitää ymmärtämän, että minä olen Herra, kuin minä asetan kasvoni heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Ja teen maakunnan kylmille, että he ovat pilkanneet minua, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Sinä ihmisen poika, ilmoita Jerusalemille hänen kauhistuksensa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Ja sano: sinun sukus ja syntys on Kanaanealaisten maalta, sinun isäs Amorilaisista ja sinun äitis Hetiläisistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Sinun sukus ei ole sinulta napaa leikanneet, kuin synnyit, ei ole sinua myös saunoitettu vedellä, ettäs olisit puhtaaksi tullut, eikä suolalla tahottu, eikä kapaloihin kääritty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Sillä ei kenkään sinua surkutellut, että hän olis armahtanut sinua, ja osoittanut sinulle yhdenkin näistä, mutta sinä heitettiin kedolle, niin ylönkatsottu oli sinun sielus, kuin synnyit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Mutta minä kävin sinun ohitses, ja näin sinun veressäs makaavan, ja sanoin sinulle: sinun pitää elämän, kuin sinä niin sinun veressäs makasit; totta sinulle sanoin minä, kuin niin veressäs makasit: sinun pitää elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Ja minä olen enentänyt sinun moneksi tuhanneksi ja antanut sinun suureksi tulla, niinkuin hedelmän maan päällä, ja sinä olit kasvanut isoksi ja aivan kauniiksi tullut, sinun nisäs olivat kasvaneet, ja sinä olit saanut kauniit pitkät hiukset, mutta sinä olit vielä alastoin ja kaino.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Ja minä kävin ohitses ja katsoin päälles, ja katso, sinä olit täysikasvuinen, niin minä hajoitin hameeni liepeen sinun ylitses, ja peitin sinun häpiäs; ja minä vannoin sinulle, ja annoin itseni liittoon sinun kanssas, sanoo Herra, Herra, että sinun piti minun oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Ja pesin sinun vedellä, ja virutin sinun verestäs, ja voitelin sinun öljyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Ja vaatetin sinun neulotuilla vaatteilla, ja kengitin sinun Tekasjimin nahalla, ja annoin sinulle kalliit liinavaatteet, puetin sinun silkkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Ja kaunistin sinun kaunistuksella, ja panin käsirenkaat sinun kätees ja käädyt sinun kaulaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Ja annoin otsalehden sinun otsaas, ja korvarenkaat korviis ja kunnian kruunun päähäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Niin sinä kaunistettiin kullalla ja hopialla, ja vaatetettiin kalliilla liinavaatteella, silkillä ja neulotulla työllä; sinä söit myös sämpyläleipää, hunajaa ja öljyä; ja olit ylenpaljon kaunistettu, ja sait valtakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Ja sinun nimes kuului kauvas pakanain seassa sinun kauneutes tähden, joka juuri täydellinen oli, senkaltaisten kaunistusten kautta, jotka minä olin pannut päälles, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Mutta sinä uskalsit kauneutees; ja ettäs niin ylistetty olit, teit sinä huorin, niin että sinä itses teit yhteiseksi jokaiselle, jotka kävivät ohitses, ja teit hänen tahtonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Ja otit sinun vaatteistas, ja teit siitä kirjavat alttarit itselles, ja teit huoruuttas niiden päällä; joka ei ikänä tapahtunut ole, eikä pidä tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Ja otit sinun kunniakaluistas, jotka minä sinulle minun kullastani ja hopiastani antanut olin, ja teit niistä miehen kuvat itselles, ja teit huorin niiden kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Ja otit neulotut vaattees ja peitit ne niillä, ja minun öljyni ja suitsutukseni asetit sinä heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Ruokani, jonka minä annoin syödäkses, sämpylöitä, öljyä ja hunajaa, asetit sinä heidän eteensä makiaksi hajuksi; ja niin se oli, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Ja sinä otit poikas ja tyttäres, jotka minulle synnyttänyt olit, ja uhrasit ne heille syötää; luuletkos niin halvaksi huoruutes?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Ja sinä teuraaksi teit minun lapseni, ja annoit polttaa heitä heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Et kuitenkaan sinä ole kaikessa kauhistuksessas ja huoruudessas koskaan ajatellut nuoruutes aikaa, kuinka paljas ja alastoin sinä olit, ja makasit veressäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Joka tapahtui kaiken sinun pahuutes jälkeen. Voi! voi sinuas! sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Sinä rakensit itselles korkeudet, ja teit sinulles kukkulat kaikille kaduille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Ja kaikkein teiden suihin rakensit sinä kukkulas, ja teit sinun kauneutes kauhistukseksi; sinä hajoitit jalkas jokaiselle, joka kävi siitä ohitse, ja teit suurta salavuoteutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Ensin sinä teit salavuoteutta lähimmäistes Egyptin lasten kanssa, joilla suuri liha oli, ja teit suurta salavuoteutta kehoittaakses minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Ja katso, minä ojensin käteni sinua vastaan ja hillitsin senkaltaisen tapas, ja hylkäsin sinun vihollistes Philistealaisten tyttärien tahtoon, jotka häpesivät sinun häpeemätöntä työtäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Sitte sinä teit huoruutta Assurin lasten kanssa, ja et taitanut heistä kyllääs saada; ja kuin sinä olit tehnyt huoruutta heidän kanssansa, ja et taitanut heistä kyllääntyä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Enensit sinä vielä sitte sinun huoruuttas Kanaanin maalla, Kaldeaan asti, ja et sinä vielä sittenkään taitanut silläkään kyllääntyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Kuinka siis minun pitäis ympärileikkaaman sinun sydämes, sanoo Herra, Herra: ettäs senkaltaisen julkihuoran töitä teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Siinä, ettäs niin rakennat korkeutes joka tien suuhun, ja teet kukkulas kaikille kaduille, ja et ole niinkuin muu portto, joka rahalla ostettaman pitää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Taikka niinkuin joku huorivaimo, joka miehensä siaan laskee toisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Kaikille portoille annetaan lahjoja; mutta sinä annat kaikille sinun värtämiehilles palkan, ja lahjoitat heitä, että heidän joka paikasta sinun tykös tuleman pitäis, huoruutta tekemään sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Ja löydetään sinun tykönäs sinun huotuudessas juuri vastoin sitä mikä tapa on muiden vaimoin kanssa, ettei sinun perässäs juosta; ja että sinä palkan annat, ja ei sinulle palkkaa anneta, niin sinä teet juuri vastahakoisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Sentähden sinä portto, kuule Herran sanaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Näin sanoo Herra, Herra: ettäs niin mielelläs annat rahaa, ja julistat häpiäs huoruutes kautta värtämiehelles ja kaiken sinun kauhistukses epäjumalain kanssa, ja vuodatat lastes veren, jonkas heille uhraat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Sentähden, katso, minä tahdon koota kaikki sinun värtämiehes, joiden kanssa sinä olet hekumassa elänyt, ynnä kaikkein niiden kanssa, joita ystävinäs pidät, ja joita vihaat; ja minä tahdon ne koota sinua vastaan joka taholta, ja julistaa sinun häpiäs, että heidän kaikki sinun häpiäs näkemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Ja minä annan käydä huoran ja verenvuodattajan oikeuden sinun ylitses, ja annan vuodattaa sinun veres julmuudella ja kiivaudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Ja minä annan sinut heidän käsiinsä, että heidän pitää särkemän sinun korkeutes, ja kukistaman sinun kukkulas, ja riisuman sinun vaattees, ja ottaman sinulta pois sinun kunniakappalees, ja antaman istua sinun alasti ja paljaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Ja heidän pitää antaman tulla sinun vastaas suuren väkijoukon, jotka pitää sinua kivittämän kuoliaaksi ja hakkaaman miekoillansa rikki;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Ja tulella polttaman sinun huonees, ja näyttämän sinulle sinun oikeutes monen vaimon silmäin edessä; ja minä tahdon tehdä lopun sinun huoruudelles, ettei sinun enään pidä antaman rahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Ja kuin minä olen antanut minun vihani levätä sinun päälläs, niin pitää minun kiivauteni sinusta luopuman, että minä mahtaisin olla levossa, ja en enään vihastua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Ettes muistanut nuoruutes aikaa, vaan kehoitit minua näillä kaikilla, sentähden tahdon minä myös panna kaikki sinun menos sinun pääs päälle, sanoo Herra, Herra, ettes tekisi sitä pahaa kaikkein sinun kauhistustes kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Katso, kaikki jotka itsiänsä sananlaskussa harjoittavat, ne pitää tämän sananlaskun sinusta sanoman: tytär on niinkuin äitikin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Sinä olet äitis tytär, joka hylkäsi miehensä ja lapsensa; ja sinä olet sisartes sisar, jotka jättivät pois miehensä ja lapsensa; teidän äitinne on Hetiläinen, ja teidän isänne Amorilainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Samaria on sinun vanhempi sisares tyttärinensä, joka vasemmalla puolellas tykönäs asuu; ja Sodoma on sinun nuorempi sisares tyttärinensä, joka asuu oikialla puolellas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Vaikka et sinä kuitenkaan heidän teillänsä vaeltanut, taikka tehnyt heidän kauhistustensa jälkeen, niin ei siitä paljo puutu, ettet sinä pahempia asioita tehnyt ole kuin he, kaikissa sinun menoissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Niin totta kuin minä elän, sanoo Herra, Herra, Sodoma, sinun sisares tyttärinensä, ei ole niin tehnyt kuin sinä ja sinun tyttäres.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Katso, se oli sinun sisares, Sodoman synti: ylpeys, ja kaikissa yltäkylläisyys, ja hyvä rauha, joka hänellä ja hänen tyttärillänsä oli: mutta köyhiä ja tarvitsevia ei he auttaneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Mutta he olivat ylpiät, ja tekivät kauhistuksen minun edessäni; sentähden olen myös minä heittänyt heidät pois, kuin minä sen näin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Niin ei myös Samaria ole tehnyt puoliakaan sinun syntejäs; mutta sinä olet paljon enemmin tehnyt sinun kauheuttas kuin hän, ettäs olet tehnyt sisares hyväksi kaikkein sinun kauhistustes suhteen, joita sinä tehnyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Niin kanna myös häpiäs, sinä, joka sisares hyväksi teet synteis kautta, joissa sinä suuremmat ja olet tehnyt heitä paremmaksi kuin sinä olet: niin häpee nyt ja kanna häpiäs, ettäs sisares, hyväksi tehnyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Mutta minä tahdon kääntää heidän vankiutensa: Sodoman vankiuden ja hänen tytärtensä, ja Samarian vankiuden ja hänen tytärtensä, ja sinun vankiutes vangit heidän keskellänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Niin että sinun täytyy kantaa sinun häpiäs ja pilkkas kaiken sen edestä, jonka tehnyt olet, jolla heitä olet lohduttava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Ja sinun sisares Sodoma ja hänen tyttärensä pitää käännetyksi tuleman, niinkuin he ennen ovat olleet, ja Samaria ja hänen tyttärensä pitää käännetyksi tuleman, niinkuin he ennen ovat olleet; ja sinun myös tytärtes kanssa pitää käännetyksi tuleman, niinkuin te ennen olleet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Ja ei pidä (enää) Sodoma sinun sisares huutoon tuleman sinun suussas, (niinkuin) ylpeytes aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Kuin pahuutes ei vielä julki ollut, niinkuin siihen aikaan, kuin Syrian ja Philistealaisten tyttäret häpäisivät sinua joka paikassa, ja kaikki sen ympäristö katsoi sinun ylön;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Kuin sinun täytyi kantaa pahuuttas ja kauheuttas, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Sillä näin sanoo Herra, Herra: minä tahdon tehdä sinulle, niinkuin sinä tehnyt olet, ettäs valan katsoit ylön ja särjit liiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Mutta minä tahdon muistaa minun liittoni, jonka minä kanssas tehnyt olen nuoruutes aikana, ja tahdon tehdä ijankaikkisen liiton sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Niin sinun pitää mielees johdattaman sinun teitäs, ja häpeemän, kuin olet ottava tykös vanhemmat ja nuoremmat sisares, jotka minä sinulle tyttärikses antava olen; vaan ei sinun liitostas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Mutta minä tahdon tehdä minun liittoni sinun kanssas, että sinun ymmärtämän pitää, että minä olen Herra:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Ettäs sitä ajattelisit ja häpeäisit, ja et rohkeaisi häpiän tähden suutas avata, koska minä sinulle anteeksi antava olen kaikki, mitäs tehnyt olet, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Sinä ihmisen poika, anna Israelin huoneelle tapaus ja juttele vertaus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Ja sano: näin sanoo Herra, Herra: suuri kotka suurella lennolla ja pitkillä siivillä ja täynnä sulkia, jotka olivat kirjavat, tuli Libanonin päälle, ja otti sedripuun latvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Ja mursi pois sen pienten vesain latvan, ja vei sen kauppamaahan, ja pani sen kauppamiesten kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Ja otti myös siemeniä siitä maakunnasta ja kylvi ne hyvään peltoon, ja asetti siihen, kussa paljo vettä läsnä oli, ja istutti sen taitavasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Ja se kasvoi ja tuli avaraksi viinapuuksi, vaan matalaksi varreltansa, sillä oksat taittivat itsensä siihen päin, ja olivat juuret sen alla; ja se tuli jaloksi viinapuuksi, ja kasvoi oksat, ja putkautti itsestänsä vesat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Ja siellä oli toinen suuri kotka, jolla olivat isot siivet ja paljo sulkia, ja katso, tämä viinapuu sovitti juurensa hänen puoleensa, ja ojensi oksansa hänen puoleensa, että sen piti kastetuksi tuleman hänen ojistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Ja oli kuitenkin hyvällä maalla paljon veden tykönä istutettu, niin että se kyllä sai kasvaa oksia, hedelmää kantaa ja suureksi viinapuuksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Niin sano nyt: näin sanoo Herra, Herra: pitäisikö sen menestymän? eikö sen juuret pidä reväistämän ylös, ja sen hedelmät varistettaman, että se kuivettuis? sen pitää kuivettuman kaikissa vesoissansa, ja ei suuren käsivarren, taikka paljon kansan kautta, juurinensa revittämän ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Katso, se on istutettu; vaan pitäiskö sen menestymän? ja niin pian kuin siihen tulee itätuuli, niin pitää sen kuivettuman paikkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Sanos tälle kovakorvaiselle huoneelle: ettekö te tiedä, mikä tämä on? ja sano: katso, Babelin kuningas tuli Jerusalemiin, ja otti hänen kuninkaansa ja päämiehensä, ja vei heidät tykönsä Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Ja otti yhden kuninkaallisesta siemenestä, ja teki liiton hänen kanssansa, ja otti valan häneltä; mutta ne jalot maakunnassa otti hän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Että valtakunta piti nöyryytetyksi tuleman, ja ei itsiänsä paisuttaman, että liitto piti pidettämän ja seisovainen oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Mutta se luopui hänestä, ja lähetti käskyläisensä Egyptiin, että hänelle piti lähettämän hevosia ja paljon väkeä; pitäiskö se menestymän hänelle? taikka pitäiskö hänen hyvin siitä pääsemän, joka senkaltaista tekee? ja se kuin liiton särkee, pitäiskö sen pääsemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Niin totta kuin minä elän, sanoo Herra, Herra: sen kuninkaan paikassa, joka hänen kuninkaaksi asetti, jonka valan hän katsoi ylön, ja jonka liiton hän särki, siellä hänen pitää kuoleman Babelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Ja Pharaon ei pidä seisovaisen oleman häntä auttaissansa sodassa, sotajoukolla ja paljolla väellä, koska vallit pantaman ylös ja multaseinät rakennettaman pitää, että monta sielua surmattaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Sillä hän on katsonut valan ylön, ja särkenyt liiton; katso, että hän on kätensä ojentanut, ja kaikkia näitä tekee, niin ei hänen pidä pääsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Sentähden sanoo Herra, Herra näin: niin totta kuin minä elän, tahdon minä valani, jonka hän on katsonut ylön, ja liittoni, jonka hän särkenyt on, antaa tulla hänen päänsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Sillä minä tahdon heittää verkkoni hänen päällensä, ja hän pitää minun pyydyksilläni otettaman kiinni; ja minä tahdon antaa hänen vietää Babeliin, ja tahdon siellä olla oikeudella hänen kanssansa, että hän niin itsensä on asettanut minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Ja kaikki, jotka pakenevat ja hänen puoltansa pitävät, pitää miekalla lankeeman, ja ne, jotka heistä pääsevät, pitää kaikkiin tuuliin hajoitetuiksi tuleman; ja teidän pitää ymmärtämän, että minä Herra olen tämän puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Näin sanoo Herra, Herra: minä tahdon myös ottaa korkian sedrin latvasta, ja murtaa nuorten vesain latvan, ja minä tahdon istuttaa sen korkialle vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Minä tahdon sen korkialle Israelin vuorelle istuttaa, että sen pitää oksia saaman, ja hedelmän kantaman, ja suureksi sedripuuksi tuleman: niin että kaikkinaiset linnut pitää taitaman asua hänen allansa, ja hänen oksainsa varjon alla lepäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Ja kaikki puut maan päällä pitää tietämän, että minä Herra olen korkian puun alentanut, ja matalan puun ylentänyt, ja viheriäisen puun kuivannut, ja kuivan puun viheriäiseksi tehnyt; minä Herra sen puhun, ja teen sen myös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Mitä te pidätte keskenänne Israelin maalla tätä sananlaskua, ja sanotte: isät ovat syöneet happamia viinamarjoja, mutta lasten hampaat ovat huoltuneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Niin totta kuin minä elän, sanoo Herra, Herra, senkaltainen sananlasku ei pidä enään oleman teidän seassanne Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Sillä katso, kaikki sielut ovat minun, isän sielu on niin minun kuin pojankin sielu; se sielu, joka syntiä tekee, sen pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Jos joku on hurskas, joka oikein ja hyvin tekee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Joka ei vuorilla syö, joka ei nosta silmiänsä ylös Israelin huoneen epäjumalain puoleen, ja ei saastuta lähimmäisensä emäntää, eikä makaa vaimon kanssa hänen taudissansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Joka ei kenellekään vahinkoa tee, joka velkamiehille antaa panttinsa jälleen, joka ei keltäkään mitään ota pois väkivallalla, joka jakaa leipänsä isoovaiselle, ja vaatettaa alastoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Joka ei korolle anna, joka ei voittoa ota, joka vääryydestä kätensä tempaa pois, joka ihmisten vaiheella oikein tuomitsee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Joka minun säätyini jälkeen vaeltaa, ja minun oikeuteni pitää, niin että hän todesta sen jälkeen tekee; se on hurskas mies, hänen pitää totisesti saaman elää, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Mutta jos hän pojan siittää, ja se tulee murhaajaksi, joka verta vuodattaa, eli tekee jonkun näistä kappaleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Ja ei yhtään niistä muista kappaleista tee; mutta syö myös vuorilla, ja saastuttaa lähimmäisensä emännän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Tekee köyhille ja vaivaisille vahinkoa, ottaa jotain väkivallalla, ei anna panttia jälleen ja nostaa silmänsä epäjumalain puoleen, jolla hän kauhistuksen tekee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Antaa kasvulle, ottaa voittoa: pitäisikö hänen elämän? Ei hänen pidä elämän; mutta että hän senkaltaisen kauhistuksen tehnyt on, niin hänen pitää totisesti kuoleman, hänen verensä pitää hänen päällänsä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Mutta jos hän pojan siittää, joka kaikki näkee, isänsä synnit jotka hän tehnyt on; ja hän pelkää, ja ei tee niin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Ei syö vuorilla, ei silmäinsä nosta Israelin huoneen epäjumalain puoleen, ei saastuta lähimmäisensä emäntää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Ei tee kenellekään vahinkoa, ei pidä panttia tykönänsä, ei mitään ota vääryydellä; jakaa leipänsä isoovaisille, ja vaatettaa alastoman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Ei vaivaisille tee vääryyttä, ei ota korkoa eikä voittoa, mutta pitää minun oikeuteni, ja elää minun säätyini jälkeen: ei hänen pidä kuoleman isäinsä pahan teon tähden, vaan totisesti elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Mutta hänen isänsä, joka paljon väkivaltaa ja suurta vääryyttä tehnyt on veljeänsä vastaan, ja kansansa seassa tehnyt on sitä mikä ei kelpaa, katso, hänen pitää kuoleman pahan tekonsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Niin te sanotte: miksi ei pojan pidä kantaman isänsä pahaa tekoa? että hän on tehnyt oikein ja hyvin, pitänyt ja tehnyt kaikki minun säätyni, niin hän saa totisesti elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Sillä se sielu, joka syntiä tekee, sen pitää kuoleman; ei pojan pidä kantaman isänsä syntiä, eikä isän pojan syntiä; mutta vanhurskaan vanhurskaus pitää hänen itse päällänsä oleman, ja väärän pahuus pitää hänen päällänsä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Mutta jos jumalatoin kääntyy kaikista synneistänsä, joita hän tehnyt on, ja pitää kaikki minun säätyni, ja tekee oikeuden ja vanhurskauden, niin hän saa totisesti elää, ja ei pidä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Kaikkia hänen ylitsekäymisiänsä, joita hän tehnyt on, ei pidä muistettaman; mutta hän saa elää vanhurskauden tähden, jonka hän tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Luuletkos, että minulla on joku ilo jumalattoman kuolemasta, sanoo Herra, Herra, ja ei paljo enempi, että hän palajaa teistänsä, ja saa elää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Ja jos vanhurskas kääntyy vanhurskaudestansa, ja tekee pahaa, ja elää kaiken sen kauhistuksen jälkeen, jonka jumalatoin tekee: pitäiskö hänen saaman elää? Ja tosin kaikkea hänen vanhurskauttansa, jota hän tehnyt on, ei pidä muistettaman; mutta hänen pitää kuoleman ylitsekäymistensä ja synteinsä tähden, joita hän tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Ja vielä sitte te sanotte: ei Herra tee oikein. Niin kuulkaat nyt, te Israelin huoneesta: eikö minulla oikeus ole, ja teillä vääryys?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Kuin vanhurskas kääntyy vanhurskaudestansa, ja tekee pahaa, niin hänen pitää kuoleman; mutta hänen pitää kuoleman pahuutensa tähden, jonka hän tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Ja koska jumalatoin kääntyy vääryydestänsä, jonka hän tehnyt on, ja tekee oikeuden ja vanhurskauden, hän saa pitää sielunsa elävänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Sillä koska hän näkee, ja lakkaa pahuudestansa, niin hänen pitää totisesti elämän ja ei kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Ja Israelin huone sanoo: ei Herra tee oikein. Pitäisikö minulla vääryys oleman, te Israelin huone? Eikö teillä ole vääryys?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Sentähden tahdon minä tuomita teitä, te Israelin huoneesta, jokaisen hänen tiensä jälkeen, sanoo Herra, Herra. Sentähden kääntykäät, ja palatkaat kaikesta vääryydestänne, ettette lankeaisi pahan tekonne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Heittäkäät pois tyköänne kaikki ylitsekäymisenne, jolla te rikkoneet olette, ja tehkää teillenne uusi sydän ja uusi henki; sillä miksi pitäis teidän kuoleman, sinä Israelin huone?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Sillä ei minulla ole yhtään iloa hänen kuolemastansa, joka kuolee, sanoo Herra, Herra: sentähden kääntykäät, niin te saatte elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Mutta tee sinä valitusitku Israelin päämiehistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Ja sano: miksi sinun äitis naaras jalopeura makasi jalopeurain seassa, ja kasvatti penikkansa nuorten jalopeurain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Yhden hän niistä kasvatti, ja siitä tuli nuori jalopeura, se tottui julmasti repimään ja syömään ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Kuin pakanat sen hänestä kuulivat, ottivat he sen kiinni luolassansa, ja veivät sen kahleissa Egyptin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Kuin nyt äiti sen näki, että hänen toivonsa oli pois, otti hän toisen pojistansa ja teki siitä nuoren jalopeuran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Kuin se vaelsi jalopeurain seassa, tuli se nuoreksi jalopeuraksi, joka myös harjaantui julmasti raatelemaan ja syömään ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Se oppi heidän leskensä tuntemaan ja hävitti heidän kaupunkinsa, niin että maa ja mitä siinä oli, kauhistui hänen kiljumisensa ääntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Niin asettivat pakanat itsensä kaikista maakunnista hänen ympärillensä, ja heittivät verkkonsa hänen päällensä, ja käsittivät hänen luolassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Ja panivat hänen kahleissa vankiuteen, ja veivät hänen Babelin kuninkaan tykö; ja hän vietiin varustuksiin, ettei hänen äänensä pitänyt enää kuultaman Israelin vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Sinun äitis on sinun levossas niinkuin viinapuu veden reunalla istutettu; ja sen hedelmät ja oksat kasvoivat siitä paljosta vedestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Että sen oksat niin vahvaksi tulivat, että ne herrain valtikaksi kelpasivat, ja se tuli korkiaksi paksuin oksain seassa. Ja kuin se nähtiin, että se niin korkia oli, ja että hänellä niin monta oksaa oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Reväistiin se maahan vihassa, ja heitettiin pois, itätuuli kuivasi hänen hedelmänsä; ja sen vahvat oksat murrettiin rikki, niin että ne kuivetuksi ja tulelta poltetuiksi tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Mutta nyt se on istutettu korpeen, kuivaan ja karkiaan maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Ja tuli kävi ulos sen vahvoista oksista, se söi sen hedelmän, niin ettei sen päällä enään vahvoja oksia ole herrain valtikaksi. Se on valitettava ja surullinen asia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Ja tapahtui seitsemäntenä vuotena, kymmenentenä päivänä viidennessä kuukaudessa, että muutamia Israelin vanhimmista tuli kysymään Herralta; ja he istuivat minun eteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Silloin tapahtui Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Sinä, ihmisen poika, puhu Israelin vanhimpain kanssa, ja sano heille: näin sanoo Herra, Herra: oletteko te tulleet kysymään minulta? Niin totta kuin minä elän, en tahdo minä teitä vastata, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Mutta jos sinä ihmisen poika tahdot tuomita heitä, niin tuomitse heitä näin: ilmoita heille heidän isäinsä kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Ja sano heille: näin sanoo Herra, Herra: siihen aikaan, kuin minä valitsin Israelin, nostin minä käteni Jakobin huoneen siemenelle, ja annoin heidän tuta minuani Egyptin maalla; ja tosin minä nostin käteni heille, ja sanoin: minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Mutta minä nostin heille käteni sillä ajalla, että minun piti johdattaman heitä Egyptin maalta siihen maakuntaan, jonka minä heille edes katsonut olin, joka rieskaa ja hunajaa vuotaa, joka on paras kaikkein maakuntain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Ja sanoin heille: heittäkään jokainen kauhistuksen pois silmäinsä edestä, ja älkäät saastuttako itsiänne Egyptin epäjumalista; sillä minä olen Herra teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Mutta he olivat minulle kovakorvaiset ja ei tahtoneet kuulla minua; ja ei yksikään heistä heittänyt kauhistustansa pois silmäinsä edestä, ja ei hyljänneet Egyptin epäjumalia. Niin minä ajattelin vuodattaa vihani heidän päällensä, ja antaa minun hirmuisuuteni käydä heidän ylitsensä Egyptin maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Mutta en minä tehnyt sitä minun nimeni tähden, ettei sen pitänyt saastutetuksi tuleman pakanain edessä, joiden seassa he olivat, ja joille minä olin itseni ilmoittanut, että minä heidät tahdoin johdattaa ulos Egyptin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Ja kuin minä heidät Egyptin maalta olin johdattanut ulos, ja antanut heidän tulla korpeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Annoin minä heille minun säätyni, ja minun oikeuteni heille tiettäväksi tein: se ihminen joka ne tekee, hän elää niissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Minä annoin myös heille minun sabbatini merkiksi minun ja heidän vaiheellansa, että heidän piti tietämän, että minä olen Herra, joka heitä pyhitän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Mutta Israelin huone oli minulle kovakorvainen korvessa, ja ei elänyt minun säätyini jälkeen, ja katsoi minun oikeuteni ylön, joissa se ihminen elää, joka ne tekee; ja he saastuttivat minun sabbatini sangen suuresti: niin minä ajattelin vuodattaa minun vihani heidän päällensä korvessa, ja peräti kadottaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Mutta en minä sitä tehnyt minun nimeni tähden, ettei sen pitänyt turmelluksi tuleman pakanain seassa, joista minä heidät olin johdattanut ulos heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Ja minä nostin käteni heitä vastaan korvessa, etten minä tahtonut heitä antaa tulla siihen maahan, jonka minä heille antanut olin, joka rieskaa ja hunajaa vuotaa, joka on paras kaikkein maakuntain seassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Että he katsoivat minun oikeuteni ylön, ja ei eläneet minun säätyini jälkeen, ja turmelivat minun sabbatini; sillä heidän sydämensä vaelsi heidän epäjumalainsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mutta minun silmäni armahti heitä, etten minä heitä kadottanut, enkä peräti tyhjäksi tehnyt heitä korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Ja minä sanoin heidän lapsillensa korvessa: ei teidän pidä elämän teidän isäinne säätyin jälkeen, eikä pitämän heidän oikeuksiansa, eli saastuttaman itsiänne heidän epäjumaliinsa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Sillä minä olen Herra teidän Jumalanne: minun säätyini jälkeen pitää teidän elämän, ja minun oikeuteni pitämän, ja niiden jälkeen tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Ja minun sabbatini pitää teidän pyhittämän, että ne pitää oleman merkiksi minun ja teidän vaiheellanne, että teidän pitää tietämän, että minä Herra olen teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mutta lapset olivat minulle myös kovakorvaiset, ja ei eläneet minun säätyini jälkeen, eikä pitäneet minun oikeuksiani, tehdäksensä niiden jälkeen, joissa ihminen elää, joka ne pitää, ja he turmelivat minun sabbatini; niin minä ajattelin vuodattaa minun vihani heidän päällensä, ja antaa minun hirmuisuuteni käydä heidän ylitsensä korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Mutta minä käänsin käteni, ja en tehnyt sitä minun nimeni tähden, ettei sen pitänyt turmelluksi tuleman pakanain edessä, joista minä heitä olen johdattanut ulos heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Minä nostin myös minun käteni heitä vastaan korvessa, hajoittaakseni heitä pakanain sekaan ja maakuntiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Ettei he pitäneet minun oikeuksiani, ja katsoivat minun säätyni ylön, ja turmelivat minun sabbatini, ja katselivat isäinsä epäjumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Sentähden annoin minä heille säädyt, jotka ei hyvät olleet, ja oikeudet, joissa ei heille ollut elämää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Ja hylkäsin heidän uhrinsa koska he käyttivät tulessa kaikki esikoiset, että minun piti heitä hävittämän, ja että heidän piti tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Sentähden puhu, sinä ihmisen poika, Israelin huoneelle, ja sano heille: näin sanoo Herra, Herra: teidän isänne ovat vielä enemmin minua pilkanneet, hyvällä ehdolla minua vastaan rikkoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Sillä kuin minä olin antanut heidän tulla siihen maahan, jonka ylitse minä käteni nostanut olin, että minun piti sen antaman heille; kussa he joskus näkivät korkean vuoren taikka paksuoksaisen puun, siellä he uhrasivat uhrinsa ja kantoivat sinne uhrinsa vihan kehoitukseksi, ja suitsuttivat siellä makian hajunsa ja vuodattivat siellä juomauhrinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Mutta minä sanoin heille: mihinkä pitää siis oleman sen kukkulan, johonka te menette? Ja siitä kutsutaan se kukkulaksi aina tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Sentähden sano Israelin huoneelle: näin sanoo Herra, Herra: te saastutatte itsenne teidän isäinne menoissa, ja teette huorin heidän kauhistustensa kanssa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Ja saastutatte itsenne teidän epäjumalissanne, joille te uhraatte teidän lahjanne, ja poltatte teidän poikanne tulessa hamaan tähän päivään asti: ja minun pitäis antaman teille vastausta, sinä Israelin huone? Niin totta kuin minä elän, sanoo Herra, Herra: en tahdo minä vastausta antaa teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Ja se mikä tulee teidän mieleenne, ei siitä pidä mitään oleman: että te sanotte: me tahdomme tehdä niinkuin pakanat ja muut kansat maakunnissa, ja palvella kantoja ja kiviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Niin totta kuin minä elän, sanoo Herra, Herra, minä tahdon hallita teitä väkevällä kädellä ja ojennetulla käsivarrella, ja vuodatetulla hirmuisuudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Ja tahdon johdattaa teitä pois kansoista, ja koota teitä niistä maakunnista, joihinka te hajoitetut olette, väkevällä kädellä ja ojennetulla käsivarrella, ja vuodatetulla hirmuisuudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Ja tahdon teidän antaa tulla kansain korpeen, ja olla siellä oikeudella teidän kanssanne, kasvoista niin kasvoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Niinkuin minä teidän isäinne kanssa Egyptin maan korvessa oikeudella olin: juuri sillä tavalla tahdon minä olla oikeudella teidän kanssanne, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Minä tahdon antaa teidän tulla vitsan alle, ja johdattaa teitä liiton siteellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Ja tahdon perata pois vastahakoiset ja minusta luopuvaiset teidän seastanne. Ja tosin minä tahdon johdattaa heitä ulos asumamaastansa, ja en anna heitä tulla Israelin maalle, että teidän tietämän pitää, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Sentähden te, Israelin huone, näin sanoo Herra, Herra: ettette kuitenkaan tahdo kuulla minua, niin tehkäät niinkuin teille kelpaa, ja jokainen teitä palvelkaan epäjumalaansa tästäkin lähin; mutta minun pyhä nimeni antakaat tästedes pilkkaamatta olla teidän uhreissanne ja epäjumalissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Sillä näin sanoo Herra, Herra: minun pyhällä vuorellani, korkialla Israelin vuorella, siellä pitää koko Israelin huone ja kaikki, jotka maakunnassa ovat, palveleman minua; siellä pitää heidän minulle oleman otolliset, ja siellä minä tahdon anoa teiltä ylennysuhria ja teidän uhrinne esikoista kaiken sen kanssa, jolla te minua pyhitätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Te olette minulle otolliset makialla savulla, kuin minä annan teidän tulla pois kansoista, ja kokoon teitä siitä maasta, kuhunka te hajoitetut olette, ja pyhitän itseni teissä, pakanain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Ja teidän pitää ymmärtämän, että minä olen Herra, koska minä olen antanut teidän tulla Israelin maalle, siihen maahan, josta minä nostin käteni, että minun piti teidän isillenne sen antaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Siellä pitää teidän muistaman teidän menonne ja kaikki teidän tekonne, joilla te itsenne saastuttaneet olette, ja teidän pitää suuttuman itseenne kaiken teidän pahuutenne tähden, jonka te tehneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Ja teidän pitää ymmärtämän, että minä olen Herra, koska minä teen teidän kanssanne minun nimeni tähden, ja ei teidän pahan menonne ja vahingollisen työnne jälkeen, sinä Israelin huone, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Sinä, ihmisen poika, aseta kasvos oikian käden puoleen, ja pisaroitse lounaan puoleen, ja ennusta metsää vastaan, kedolla lounaan päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Ja sano lounaan puoliselle metsälle: kuule Herran sanaa: näin sanoo Herra, Herra: katso, minä tahdon sinussa tulen sytyttää, sen pitää sekä tuoreet että kuivat puut polttaman, ettei hänen ankaraa liekkiänsä taideta sammuttaa, vaan kaikki pitää poltettaman, mitä lounaasta pohjaan käsin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'Ja kaikki liha pitää näkemän, että minä Herra sen sytyttänyt olen; ja ei pidä sitä sammutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Ja minä sanoin: ah! Herra, Herra, he sanovat minusta: tämä puhuu paljaita tapauksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Sinä, ihmisen poika, aseta kasvos Jerusalemia vastaan, ja ennusta Israelin maata vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Ja sano Israelin maalle: näin sanoo Herra: katso, minä tahdon sinun kimppuus, minä tahdon vetää miekkani tupesta ulos, ja tahdon sinussa hävittää sekä hurskaat että väärät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Että minä sinussa sekä hurskaat että väärät hävitän, niin minun miekkani tupesta lähtee kaiken lihan päälle etelästä niin pohjoiseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Ja kaikki liha pitää ymmärtämän, että minä Herra olen vetänyt minun miekkani tupesta ulos; ja ei pidä enään siihen pistettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Ja sinä, ihmisen poika, huokaa siihenasti että lantees pakottavat ja kipiäksi tulevat: ja sinun pitää huokaaman, niin että he näkevät sen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Ja kuin he sinulle sanovat: mitäs huokailet? pitää sinun sanoman: sen huudon tähden, joka tulee, jota kaikki sydämet hämmästyvät, ja kaikki kädet putoovat alas, kaikki rohkeus tulee pois, ja kaikki polvet niinkuin vedet vuotavat: katso, se tulee ja tapahtuu, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Sinä, ihmisen poika, ennusta ja sano: näin sanoo Herra: sano: miekka, miekka on teroitettu ja myös hiottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Se on teroitettu teurastamaan, se on hiottu välkkymään. Kuinka me taidamme iloita? minun poikani vitsa katsoo kaikki puut ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Mutta hän on miekan hiottaa antanut, että se käteen otettaman pitää: miekka on teroitettu ja se on hiottu, tappajan käteen annettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Huuda ja ulvo sinä, ihmisen poika, sillä se tapahtuu minun kansalleni ja kaikille Israelin haltioille; pelko miekan tähden pitää minun kansani tykönä oleman; sentähden lyö reisiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Sillä hän on heitä koetellut; vaan mitä se auttaa, jollei ylenkatsova vitsa tule, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Ja sinä ihmisen poika, ennusta ja lyö käsiäs yhteen; sillä miekka pitää kaksinkertaisesti, vielä kolminkertaisestikin tuleman, murhamiekka, suuren tapon miekka, niin että se myös käy lävitse heidän sisimäisiin kammioihinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Minä annan sen miekan helistä, että sydämet pitää hämmästymän, ja monta pitää kaatuman kaikissa heidän porteissansa: voi kuin se välkkyy, ja on hiottu tappamaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Yhdistä sinus, lyö oikialle ja vasemmalle puolelle, mitä edessäs on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Sillä minä tahdon myös käsilläni yhteen lyödä siitä, ja antaa minun vihani mennä: minä Herra olen sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Ja sinä, ihmisen poika, tee kaksi tietä, joita myöten Babelin kuninkaan miekka tuleman pitää, mutta ne molemmat pitää tuleman yhdeltä maalta; ja pane viitta tien haaraan kaupunkia päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Ja tee tie miekan tulla Ammonin lasten Rabbatiin ja Juudan vahvaan kaupunkiin, Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Sillä Babelin kuningas laittaa itsensä ensimmäiseksi kahden tien haaraan, tietämään tietäjältä, ampumaan nuolella arvosta, epäjumalilta kysymään, maksaan katsomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Niin pitää arpa lankeeman hänen oikialle puolellensa Jerusalemia päin, ja hän antaa sinne viedä sotaaseita, ja läven (muuriin) avata, murhaamaan, suurella äänellä huutamaan, panemaan sota-aseita porttien eteen, tekemään saartoa ja rakentamaan multaseiniä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Vaan se näkyy heille heidän silmäinsä edessä turhaksi aavistukseksi, vaikka he valan heidän edessänsä vannoisivat: mutta hän muistaa heidän pahaa tekoansa, että he kiinni otettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Sentähden sanoo Herra, Herra näin: että teidän pahat työnne ovat muistetut, ja teidän kovakorvaisuutenne ilmi on, että teidän syntinne nähdään kaikissa teidän töissänne; ja että teitä muistetaan, pitää te käsillä kiinni otettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Ja sinä paha ja jumalatoin Israelin päämies, jonka päivä lähestyy, koska pahat työt loppuneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Näin sanoo Herra, Herra: pane kuninkaan lakki pois, ja ota kruunu pois; sillä ei niitä pidä siellä enään oleman; alennettu pitää ylennettämän, ja korkia alennettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Minä tahdon sen (kruunun) tyhjäksi, tyhjäksi, tyhjäksi tehdä; ei sen myös pidä oleman siihenasti kuin se tulee, jonka sen saaman pitää, hänelle minä sen annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Ja sinä, ihmisen poika, ennusta ja sano: näin sanoo Herra, Herra, Ammonin lapsista ja heidän häväistyksestänsä; sano siis: miekka, miekka on vedetty tappamaan, se on hiottu surmaamaan ja että se on niin välkkyy;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Ettäs petollisia näkyjä sinulles sanoa annat, ja valhetta ennustaa; että sinä myös hyljättäisiin jumalattomain tapettujen sekaan, joiden päivä tuli, koska pahat työt loppuneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Ja vaikka se tuppeensa jälleen pistettäisiin, niin minä kuitenkin tuomitsen sinun siinä paikassa, kussas luotu olet, ja siinä maassa, kussas syntynyt olet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Ja tahdon vuodattaa minun vihani sinun päälles, minä tahdon minun hirmuisuuteni tulen sinun päälles puhaltaa, ja tahdon antaa sinun kiukkuisten miesten käsiin, jotka hukuttamaan tottuneet ovat, jotka polttaa ja hukuttaa taitavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Sinun pitää tulen ruaksi tuleman, ja sinun veres maalla vuodatettaman, ja ei sinua pidä enään muistettaman; sillä minä Herra olen sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Sinä, ihmisen poika, etkös tahdo nuhdella, etkös tahdo nuhdella murhakaupunkia ja hänelle näyttää kaikkia hänen kauhistuksiansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Sano: näin sanoo Herra, Herra: o sinä kaupunki, joka omais veren vuodatat, että sinun aikas tulis, ja sinä, joka epäjumalia tykönäs teet, ettäs itses saastuttaisit!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Sinä teet itses vikapääksi siihen vereen, jota vuodatat, ja saastutat itses jumalissa, joita teet; näillä sinä joudutat sinun päiväs, ja saatat, että sinun vuotes tuleman pitää; sentähden tahdon minä sinun nauruksi tehdä pakanain seassa, ja saattaa pilkaksi kaikissa maakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Sekä läsnä että kaukana pitää heidän sinua sylkemän, että sinun häpiällisen sanoman ja suuren vaivan kärsimän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Katso, Israelin päämiehet ovat kukin väkevä sinussa verta vuodattamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Isänsä ja äitinsä he katsovat ylön sinussa: muukalaisille he väkivaltaa ja vääryyttä tekevät; orpoja ja leskiä he sortavat sinussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Sinä katsot minun pyhyyteni ylön, ja turmelet minun sabbatini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Pettäjät ovat sinussa verta vuodattamaan; he syövät vuorilla, ja tekevät ylöllistä sinussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'He paljastavat isänsä hävyn sinussa, ja vaivaavat saastaisia vaimoja heidän taudissansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Ja tekevät kauheutta lähimmäisensä vaimon kanssa: he häpäisevät omat miniänsä ilkivaltaisesti, he tekevät väkivaltaa omille sisarillensa, isäinsä tyttärille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'He ottavat lahjoja sinussa, verta vuodattaaksensa; sinä otat koron ja voiton, ja ahnehdit lähimmäiseltäs väkivallalla, ja näin unohdat minun, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Katso, minä lyön käsiäni yhteen sinun ahneutes tähden, jotas tehnyt olet, ja sen veren tähden, joka sinussa vuodatettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Mutta luuletkos sinun sydämes voivan kärsiä, ja sinun kätes kestää niinä päivinä kuin minä sinulle tekevä olen? Minä Herra olen sen puhunut, minä myös teen sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Ja tahdon sinun hajoittaa pakanain sekaan ja ajaa sinun maakuntiin, ja tahdon sinun saastaisuutes lopettaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Niin että sinä pakanain seassa pitää kirottuna pidettämän, ja sinun pitää ymmärtämän minun olevan Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Sinä, ihmisen poika, Israelin huone on minulle karreksi tullut; kaikki heidän vaskensa, tinansa, rautansa ja lyijynsä on ahjossa hopian karreksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Sentähden sanoo Herra, Herra näin: että te kaikki olette karreksi tulleet, sentähden katso, minä kokoon teidät Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Niinkuin hopia, vaski, rauta, lyijy ja tina ahjoon kootaan, että tuli sen alle puhallettaisiin ja ne sulaisivat: niin tahdon minä vihassani ja hirmuisuudessani koota, panna sisälle ja sulata teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Ja minä tahdon koota teidät, ja minun vihani tulen teidän seassanne puhaltaa, että te siellä sulaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Niinkuin hopia ahjossa sulaa, niin teidän pitää myös siinä sulaman; ja teidän pitää ymmärtämän, että minä Herra olen vuodattanut vihani teidän päällenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Sinä, ihmisen poika, sano heille: sinä olet se maa, joka ei ole puhdistettu, niinkuin se, joka ei sadetta saa vihan ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Prophetat, jotka siellä ovat, ovat vannoneet heitänsä yhteen, niinkuin kiljuva jalopeura, kuin se saaliin saa; he syövät sieluja, tempaavat tavaran ja rahan, ja tekevät sinne paljon leskiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Heidän pappinsa rikkovat minun lakini, ja turmelevat minun pyhäni; ei he pidä pyhäin ja saastaisten välillä eroitusta, eikä opeta mikä puhdas ja saastainen on, eikä tottele minun sabbatiani, ja minä saastutetaan heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Heidän päämiehensä heidän seassansa ovat niinkuin raatelevaiset sudet, verta vuodattamaan ja sieluja surmaamaan ahneutensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Ja heidän prophetansa sivuvat heitä sekoittamattomalla kalkilla, saarnaavat turhuutta, ja ennustavat heille valheita, ja sanovat: näin sanoo Herra, Herra; vaikka ei Herra sitä puhunut olekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Maan kansa tekee väkivaltaa, ja he ryöstävät ryövyydellä ja sortavat köyhän ja raadollisen, ja tekevät muukalaiselle väkivaltaa ja vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Minä etsin heidän seassansa sitä miestä, joka aidan panis ja seisois veräjällä minun edessäni, etten minä maata turmelisi; mutta en minä ketään löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Sentähden vuodatan minä vihani heidän päällensä, ja hirmuisuuteni tulella minä lopetan heidät, ja annan heidän tiensä heidän päänsä päälle, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Sinä, ihmisen poika, kaksi vaimoa oli yhden äidin tytärtä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Nämät tekivät huorin Egyptissä, he tekivät huorin nuoruudessansa; siellä antoivat he pidellä rintojansa, ja taputellla neitsyytensä nisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Suuremman nimi oli Ohola, ja hänen sisarensa Oholiba. Ja minä otin heidät aviokseni, ja he synnyttivät poikia ja tyttäriä. Ja Ohola kutsuttiin Samariaksi ja Oholiba Jerusalemiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ohola teki huorin, kuin minä hänen ottanut olin, ja rakasti värtämiehiänsä Assyrialaisia, jotka hänen tykönsä tulivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Silkillä vaatetettuja päämiehiä ja esimiehiä, kaikkia nuoria ihanaisia miehiä, hevosmiehiä, jotka hevosilla ajoivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Ja makasi kaikkein nuorten miesten kanssa Assyriasta, ja saastutti itsensä kaikkiin heidän jumaliinsa, kussa ikänä hän jonkun osasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Vielä sitte ei hän hyljännyt huoruuttansa Egyptin kanssa; että he hänen kanssansa maanneet olivat hänen nuoruudessansa, ja jotka hänen neitsyytensä nisiä taputtelleet, ja suuressa huoruudessa hänen kanssansa olleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Sentähden minä hylkäsin hänet värtämiestensä käsiin, Assurin lasten käsiin, joita hän himostansa rakasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'He paljastivat hänen häpynsä, ja ottivat hänen poikansa ja tyttärensä pois, mutta hänen he miekalla tappoivat. Ja sanoma kuului vaimoin seassa, että tämä rangaistus oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Mutta kuin Oholiba, hänen sisarensa, sen näki, syttyi se rakkaudesta pahemmin kuin toinen, ja teki enemmin huorin kuin hänen sisarensa huoruus oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Ja rakasti Assurin lapsia, päämiehiä ja esimiehiä, jotka hänen tykönsä tulivat kauniisti vaatetettuna, hevosmiehiä, jotka hevosilla ajoivat, kaikkia nuoria ihanaisia miehiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Silloin minä näin, että he molemmat yhdellä tavalla itsensä saastuttaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Mutta tämä teki vielä enemmin huorin; sillä kuin hän näki punaisella maalilla maalatuita miehiä seinissä, Kaldealaisten kuvia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Kupeista vyötetyitä ja kirjavat lakit heidän päässänsä, jotka kaikki olivat nähdä niinkuin päämiehet, niinkuin Babelin lapset ja Kaldealaiset pitävät isänsä maalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Syttyi hän heihin niin pian kuin hän näki heidät, ja hän lähetti sanansaattajat heidän tykönsä Kaldeaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Kuin nyt Babelin lapset hänen tykönsä tulivat, häntä makaaman hekumassansa, saastuttivat he hänen huoruudellansa; ja se saastutti itsensä heidän kanssansa, niin että hän heihin suuttui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Ja kuin hänen huoruutensa ja häpiänsä niin peräti ilmituli, suutuin minä myös häneen, niinkuin minä hänen sisareensa suuttunut olin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Mutta hän teki aina enemmän huorin ja muisti nuoruutensa aikaa, jona hän Egyptissä huorin tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Ja syttyi himoon heidän jalkavaimoinsa kanssa, joiden liha on niinkuin aasien liha, ja heidän himonsa niinkuin hevosten himo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Ja sinä teit häpiäs, niinkuin nuoruudessas, kuin Egyptissä sinun rintaas pideltiin, ja sinun nuoruutes nisiä taputeltiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Sentähden, Oholiba, näin sanoo Herra, Herra: katso, minä tahdon sinun värtämiehes, joihinkas suuttunut olet, kehoittaa sinua vastaan, ja tahdon heitä tuoda joka taholta sinua vastaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Babelin lapset ja kaikki Kaldealaiset, päämiehet, herrat ja valtamiehet, ja kaikki Assyrialaiset heidän kanssansa, kauniit, nuoret miehet, kaikki päämiehet ja esimiehet, valtamiehet, ja ylimmäiset, ja kaikkinaiset hevosmiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Ja he tulevat valmistettuna sinun päälles vaunuilla ja rattailla ja suurella väen joukolla, ja piirittävät sinun keihäillä, kilvillä ja rautalakeilla joka taholta. Niiden haltuun minä oikeuden annan, että he sinun tuomitsevat lakinsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Minä annan minun kiivauteni tulla sinun päälles, että he armottomasti sinun kanssas toimittavat; heidän pitää sinun nenäs ja korvas leikkaaman, ja mitä jää, pitää miekalla lankeeman. Heidän pitää sinun poikas ja tyttäres ottaman pois, ja tähteet pitää poltettaman tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Heidän pitää sinun vaattees riisuman, ja sinun kaunistukses ottaman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Näin minä tahdon sinun haureutes ja sinun huoruutes Egyptin maasta lopettaa, ettes enää silmiäs nosta heidän peräänsä, etkä Egyptiä enää muistaman pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Sillä näin sanoo Herra, Herra: katso, minä tahdon sinun niiden haltuun antaa, joita vihaat, ja joihin suuttunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Ne pitää sinulle tekemän niinkuin viholliset, ja ottaman kaikki, mitäs koonnut olet, ja sinut alastomaksi ja paljaaksi jättämän, että sinun saastainen häpiäs ilmi tulis sinun haureutes ja huoruutes kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Näitä pitää heidän sinulle tekemän sinun huoruutes tähden, jota sinä pakanain kanssa tehnyt olet, joiden jumalissa sinä itses saastuttanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Sinä olet käynyt sisares tietä, sentähden annan minä myös hänen maljansa sinun kätees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Näin sanoo Herra, Herra: sinun pitää juoman sisares maljan, syvän ja leviän; sinun pitää niin suureksi nauruksi ja pilkaksi tuleman, että se on ylönpalttinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Sinun pitää siitä väkevästä juomasta ja vaivasta itses juovuksiin juoman; sillä sinun sisares Samarian malja on vaivan ja hävityksen malja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Sen sinun pitää puhtaaksi juoman, ja lyömän sen kappaleiksi, ja sinun rintas repimän rikki; sillä minä olen sen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Sentähden näin sanoo Herra, Herra: ettäs minun unhottanut ja minun selkäs taa heittänyt olet, niin kanna nyt sinun haureuttas ja huoruuttas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Ja Herra sanoi minulle: sinä ihmisen poika, etkö sinä Oholaa ja Oholibaa nuhdella tahdo? näytä heille heidän kauhistuksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Kuinka he ovat huoruudessa olleet ja verta vuotaneet, ja avionsa rikkoneet epäjumalainsa kanssa; niin myös lapsensa, jotka he minulle synnyttäneet olivat, polttivat he niille uhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Päällisiksi ovat he sen minulle tehneet, että he ovat silloin minun pyhäni saastuttaneet, ja minun sabbatini rikkoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Sillä kuin he lapsensa epäjumalille tappaneet olivat, menivät he sinä päivänä minun pyhääni, sitä saastuttamaan; katso, niin ovat he minun huoneessani tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'He ovat myös lähettäneet miesten perään, jotka kaukaisilta mailta tuleman piti; kuin sana oli lähetetty heidän tykönsä, niin katso, he tulivat; ja sinä pesit itse heidän tähtensä, ja voitelit silmäs ja kaunistit sinus kaunistuksella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Ja istuit kauniilla vuoteella, jonka edessä pöytä oli valmistettu; ja sinä suitsutit ja uhrasit minun öljyni sen päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Siellä oli suruttoman kansan ääni; ja paitsi niitä miehiä yhteisestä kansasta, tuotiin myös sinne Sabealaisia korvesta, jotka antoivat renkaita heidän käsiinsä ja kauniita seppeleitä heidän päähänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Mutta minä ajattelin: se on tottunut huoruuteen vanhuudesta, ei se taida lakata huoruudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Sillä hänen tykönsä mennään niinkuin huoran tykö; juuri niin mennään Oholan ja Oholiban, hävyttömäin vaimoin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Sentähden hurskaat miehet rankaisevat heitä, niinkuin avionsa rikkojat ja veren vuodattajat rangaistaman pitää; sillä he ovat huorat, ja heidän kätensä on verta täynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Näin sanoo Herra, Herra: vie suuri joukko heidän päällensä, ja anna heitä ryöstöksi ja saaliiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Jotka heidät kivittäisivät ja heidät miekoillansa pistäisivät lävitse, ja heidän poikansa ja tyttärensä surmaisivat, ja heidän huoneensa tulella polttaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Näin minä tahdon huoruuden maalta lopettaa; että kaikki vaimot pitää oppiman, eikä tekemän senkaltaista haureutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Ja teidän haureutenne pannaan teidän päällenne, ja teidän pitää epäjumalainne syntiä kantaman, tietääksenne minun olevan Herran, Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Ja Herran sana tapahtui minulle, yhdeksäntenä vuonna, kymmenentenä päivänä kymmenennestä kuusta, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Sinä, ihmisen poika, kirjoita sinulles tämän päivän nimi, juuri tämä päivä; sillä Babelin kuningas on juuri tänäpäivänä Jerusalemia vastaan hankinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Ja pane tottelemattoman kansan eteen vertaus, ja sano heille: näin sanoo Herra, Herra: pane pata ja valmista, ja pane siihen vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Pane kappaleet siihen kokoon, kaikki ne parhaat kappaleet, reisi ja lapa; ja täytä se parhailla luukappaleilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Ota paras laumasta, ja tee valkia alle luukappaleita keittääkses; ja anna vahvasti kiehua, ja luukappaleet hyviä kypsyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Sentähden näin sanoo Herra, Herra: voi murhakaupunkia! joka senkaltainen pata on, jossa ruoste riippuu kiinni, niin ettei sen ruoste tahdo eritä. Ota kappale kappaleen jälkeen siitä ulos, sillä ei tarvita siitä arpaa heittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Sillä hänen verensä on siellä, joka paljaalle kalliolle pantu on, ja ei maan päälle vuodatettu, että se mullalla peitettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Ja minä olen myös sentähden heidän antanut sen veren paljaalle kalliolle vuodattaa, ettei se peitettäisi, että viha tulis heidän päällensä, ja heille kostettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Sentähden sanoo Herra, Herra näin: voi murhakaupunkia! jonka minä suureksi valkiaksi teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Kanna vaivoin paljo puita, sytytä tuli, että liha kypsäksi tulis, ja pane hyvin yrttejä sen päälle, että luukappaleet palaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Pane myös pata tyhjänä hiilille, että se kuumaksi tulis, ja sen vaski palais, jos sen saastaisuus sulais, ja sen ruoste läksis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Vaan ruoste, ehkä se kuinka kovin poltetaan, ei tahdo lähteä, sillä se on aivan kovin ruostunut, se pitää tulessa sulattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Sinun saastaisuutes on sula ilkeys, että vaikka minä sinua mielelläni puhdistaisin, et kuitenkaan sinä tahdo itsiäs puhdistaa antaa; sinun saastaisuudestas et sinä tästedes enää taida puhdistettaa, siihenasti että minun hirmuisuuteni sinussa sammunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Minä Herra olen sen puhunut; se pitää tuleman, minä tahdon tehdä, ja en viivyttää, en minä tahdo armahtaa, enkä kadu; vaan heidän pitää sinun tuomitseman, niinkuin sinä elänyt ja tehnyt olet, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Sinä ihmisen poika, katso, minä tahdon sinulta silmäis himon ottaa pois rangaistuksen kautta; mutta ei sinun pidä valittaman, eikä itkemän, eikä kyyneleitä vuodattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Salaa sinä mahdat huoata, mutta kuolleen valitusta ei sinun pidä pitämän, vaan sinun pitää kaunistukses paneman päälles, ja kengät jalkaas kenkimän; ei sinun pidä suutas peittämän, eikä murheellisten leipää syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Ja kuin minä huomeneltain varhain kansalle puhuin, kuoli minulta ehtoona minun emäntäni. Ja minä tein toisena huomenna, kuin minulle käsketty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Ja kansa sanoi minulle: etkös siis ilmoita meille, mitä tämä meille ennustaa, minkä sinä teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Ja minä sanoin heille: Herra on minun kanssani puhunut ja sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Sano Israelin huoneelle, että Herra näin sanoo: katso, minä tahdon minun pyhäni, teidän korkeimman lohdutuksenne, teidän silmäinne himon ja teidän sydämenne toivon saastuttaa; ja teidän poikanne ja tyttärenne, jotka teidän hylkäämän pitää, lankeevat miekan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Ja teidän täytyy tehdä, niinkuin minä tehnyt olen: teidän suutanne ei teidän pidä peittämän, eikä murheellisen leipää syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Vaan pitää teidän kaunistuksenne teidän päähänne paneman, ja kenkimän itsenne; ei teidän pidä valittaman eikä itkemän, vaan teidän synnissänne nääntymän, ja keskenänne toinen toisenne kanssa huokaileman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Ja pitää niin Hesekiel teille ihmeeksi oleman, että teidän tekemän pitää kaiken sen jälkeen, minkä hän tehnyt on; että kuin se tulee, te ymmärtäisitte, että minä Herra, Herra olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Ja sinä, ihmisen poika, silloin kuin minä heiltä olen ottava pois heidän voimansa ja lohdutuksensa, heidän silmäinsä himon ja heidän sydämensä toivon, heidän poikansa ja tyttärensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Silloin pitää yksi, joka päässyt on, tuleman sinun tykös, ja sinulle ilmoittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Silloin pitää sinun suus avattaman, ja sen joka päässyt on, että sinun puhuman pitää, ja ei enää vaikeneman. Ja sinun pitää heille ihmeeksi oleman, että he ymmärtäisivät minun olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Sinä, ihmisen poika, aseta kasvos Ammonin lasten puoleen, ja ennusta heitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Ja sano Ammonin lapsille: kuulkaat Herran, Herran sanaa: näin sanoo Herra, Herra: että te minun pyhääni pitititte, sanoen: jopa se saastutettu on, ja Israelin maata: se on kylmillä, ja Juudan huonetta, että se on vankina viety pois;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Sentähden katso, minä tahdon sinun antaa itäisen maan lapsille perinnöksi, että heidän linnojansa sinne rakentaman ja asuinsiansa sinne tekemän pitää; ja heidän pitää sinun hedelmäs syömän, ja sinun rieskas juoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Ja tahdon Rabban kamelein huoneeksi tehdä, ja Ammonin lapset lammaspihatoksi; ja teidän pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Sillä näin sanoo Herra, Herra: että sinä käsiäs paukutit, ja tömistelit jaloillas, ja Israelin maasta kaikesta sydämestäs niin äikistellen iloitsit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Sentähden katso, minä tahdon minun käteni ojentaa sinun ylitses, ja antaa sinun pakanoille ryöstöksi, ja hävittää sinun kansoista, ja maakunnista surmata; minä kadotan sinun, ja sinun pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Näin sanoo Herra, Herra: että Moab ja Seir sanovat: katso, Juudan huone on niinkuin kaikki muutkin pakanat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Sentähden katso, niin minä tahdon Moabin kyljen avata kaupungeista, hänen kaupungeistansa ja hänen rajoistansa: sen kalliin maan, Betjesimotin, Baalmeonin ja Kirjataimin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Itäisen maan lapsille, Ammonin lapsia vastaan, ja annan heidät heille perinnöksi, ettei Ammonin lapsia enää muistettaman pidä pakanain seassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Ja annan tuomita Moabin: ja heidän pitää tietämän minun olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Näin sanoo Herra, Herra: että Edom Juudan huoneelle ankarasti kostanut on, ja kostamisellansa itsensä vikapääksi saattanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Sentähden sanoo Herra, Herra näin: minä tahdon käteni ojentaa Edomin päälle, ja tahdon hänestä hävittää sekä ihmiset että eläimet, ja tahdon sen autioksi tehdä Temanista, ja Dedaniin asti pitää heidän miekalla kaatuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Ja kostan jälleen Edomille minun kansani Israelin kautta, ja heidän pitää Edomin kanssa tekemän minun vihani ja hirmuisuuteni jälkeen; että heidän minun kostoni tunteman pitää, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Näin sanoo Herra, Herra: että Philistealaiset kostaneet ovat ja vanhan vihansa sammuttaneet, kaiketi oman tahtonsa perään (minun kansani) vahingoksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Sentähden sanoo Herra, Herra näin: katso, minä tahdon minun käteni ojentaa Philistealaisten päälle; ja Kretiläiset hävittää, ja tahdon jääneet meren satamissa surmata;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Ja tahdon heille suuresti kostaa, ja vihassa heitä rangaista, että heidän ymmärtämän pitää minun olevan Herran, koska minä heille kostanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Ja tapahtui ensimäisenä vuotena toistakymmentä, ensimäisenä päivänä (ensimmäisessä kuussa), että Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Sinä ihmisen poika, että Tyro sanoo Jerusalemista: niin piti! Kansan portit ovat särjetyt: se on kääntynyt minun tyköni; minä täytetään, hän hävitetään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Sentähden näin sanoo Herra, Herra: katso, minä tahdon sinun kimppuus, Tyro, ja tahdon antaa monta pakanaa tulla sinun päälles, niinkuin meri nousee aaltoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Niin pitää heidän kaataman muurit Tyrossa, ja kukistaman hänen torninsa, ja minä tahdon käväistä pois tomunkin siitä, ja tahdon tehdä hänestä paljaan kallion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Hänen pitää tuleman luodoksi keskellä merta, jonka päälle kalaverkot hajoitetaan; sillä minä olen sen puhunut, sanoo Herra, Herra, ja hänen pitää tuleman pakanoille saaliiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Ja hänen tyttärensä, jotka kedolla ovat, pitää miekalla tapettaman; ja hänen pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Sillä näin sanoo Herra, Herra: katso, minä tahdon antaa tulla Tyron päälle Nebukadnetsarin, Babelin kuninkaan, pohjoisesta, kuningasten kuninkaan, hevosilla, vaunuilla, ratsasmiehillä ja suurella kansan joukolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Hänen pitää miekalla tappaman sinun tyttäres, jotka kedolla ovat; mutta sinua vastaan pitää hänen multaseinät rakentaman ja tekemän saarron, ja ylentämän kilvet sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Hänen pitää sota-aseilla sinun muuris maahan sysäämän, ja miekoillansa kukistaman sinun tornis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Hänen monien hevostensa tomun pitää sinun peittämän; niin pitää myös sinun muuris vapiseman hänen hevostensa, vaunuinsa ja ratsumiestensä töminästä, kuin hänen sinun porteistas vaeltaa sisälle, niinkuin siihen kaupunkiin mennään, joka maahan kukistettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Hänen pitää hevostensa kavioilla tallaaman rikki kaikki sinun katus; sinun kansas hän miekalla tappaa, ja sinun vahvat patsaas maahan kaataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Heidän pitää sinun tavaras ryöstämän, ja sinun kauppas ottaman pois, sinun muuris kaataman, ja sinun kauniit huonees kukistaman; ja heittämän sinun kives, puus ja tomus veteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Niin tahdon minä lopettaa sinun laulus äänen, ettei enään kuultaman pidä sinun kantelees helinää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Ja minä tahdon tehdä sinusta paljaan kallion ja luodon, jonka päälle kalaverkot hajoitetaan, ja ei sinun pidä enään rakennettaman; sillä minä Herra olen sen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Näin sanoo Herra, Herra Tyroa vastaan: mitämaks että luotoin pitää vapiseman, kuin sinä niin hirmuisesti kaadut, ja sinun haavoitettus huutavat, jotka sinussa hirmuisesti tapetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Ja kaikki ruhtinaat meren tykönä pitää astuman alas istuimiltansa, ja riisuman hameensa, ja paneman pois yltänsä neulotut vaatteet, ja pitää käymän murhevaatteissa ja istuman maahan, ja pitää hämmästymän ja tyhmistymän, sinun äkillisestä lankeemisestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Heidän pitää valittaman sinua, ja sanoman sinusta: voi, kuinka sinä olet niin peräti autioksi tullut, sinä kuuluisa kaupunki! sinä joka meren tykönä olit, joka niin voimallinen olit meren tykönä ynnä sinun asuvaistes kanssa, että kaiken maan täytyi sinua peljätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Nyt tyhmistyvät luodot sinun lankeemistas, ja luotokunnat meressä hämmästyvät sinun loppuas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Sillä näin sanoo Herra, Herra: minä tahdon sinua tehdä autioksi kaupungiksi, niinkuin ne kaupungit, joissa ei kenkään asu, ja annan tulla suuren virran sinun päälles, suuret vedet sinua peittämään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Ja annan sinun mennä alas niiden kanssa, jotka menevät alas hautaan, muinaisen kansan tykö, ja tahdon kukistaa sinut maan alle, ja teen sinut niinkuin ijäiseksi autioksi niiden kanssa, jotka hautaan menevät, ettei kenenkään sinussa pidä asuman; ja annan kauneuden eläväin maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Ja teen sinun hämmästykseksi, ettei sinun enää pidä oleman; niin että kuin sinua kysytään, niin ei ikänä pidä kenenkään sinua enään löytämän, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Sinä ihmisen poika, tee valitusitku Tyrosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Ja sano Tyrolle, joka asuu meren tykönä ja tekee kauppaa monen luodon kansan kanssa: näin sanoo Herra, Herra: o Tyro, sinä olet sanonut: minä olen kaikkein kaunein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Sinun rajas ovat keskellä merta; ja sinun rakentajas ovat valmistaneet sinun kaikkein kauneimmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Kaikki sinun lautas on hongasta Seniristä, ja olet antanut tuoda sedripuita Libanonista tehdäkses sinulles haahden pielen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Sinun airos olivat tehdyt Basanin tammesta, sinun piittas elephantin luista, Kittimin luodoista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Sinun purjees oli Egyptin kalliista liinasta neulottu, sinulle merkiksi; sinun peittees oli sinivilloista ja Elisan luotoin purpurasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Zidonista ja Arvadista olivat sinun haaksimiehes; ja sinulla olivat toimelliset miehet Tyrosta, haahden haltiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Vanhimmat ja taitavat Gebalista paransivat sinun laivas. Kaikki laivat meressä ja haaksimiehet löyttiin sinun tykönäs; he tekivät kauppaa sinussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persiasta, Lydiasta ja Lybiasta olivat urhoolliset miehet sinun sotajoukossas; jotka kilpensä ja otansa sinussa ripustivat, ne sinun kaunistivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Arvadin lapset olivat sinun sotajoukossas, kaikki ympäri sinun muurias, ja vartiat sinun tornissas. He ripustivat kilpensä sinun muuris päälle kaikki ympäri; ne tekivät niin sinun ihanaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis teki kauppaa sinun kanssas kaikkinaisen kalun paljoudella: hopialla, raudalla, tinalla ja lyijyllä, joita he toivat sinun markkinoilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Tubal ja Mesek teki kauppaa sinun kanssas, ja toivat ihmisiä ja vaskiastioita sinun kaupalles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Togarmasta toivat he hevosia ja vaunuja ja muuleja sinun markkinoilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Dedanin lapset olivat sinun kauppamiehes, ja sinä teit kauppaa joka paikassa luotokunnissa; he antoivat sinulle elephantin luita ja Hebenpuita hinnaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Syrialaiset noutivat sinun töitäs, joitas teit, toivat rubiinia, purppuraa, tapeteja, silkkiä ja samettia, ja kristallia sinun markkinoilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juuda ja Israelin maa teki myös kauppaa sinun kanssas, ja toi sinun markkinoilles nisuja Minnitistä, ja balsamia ja hunajaa, ja öljyä ja mastiksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Nouti myös Damasku sinun töitäs sinusta paljoudessa, ja paljon kaikkinaisia kaluja, väkevän viinan ja kalliin villan edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Dan ja Javanmehusal toivat myös sinun markkinoilles rautakalua, kassia- ja kalmus-yrttejä sinun kauppaa tehdäkses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan osti sinulta kalliita vaatteita, joiden päällä ajoissa istutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Atabia ja kaikki Kebarin ruhtinaat kaupitsivat sinulle lampaita, oinaita ja kauriita; niillä he tekivät sinun kanssas kauppaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Saban ja Ragman kauppamiehet tekivät sinun kanssas kauppaa, ja toivat sinun markkinoilles kaikkinaisia kalliita yrttejä, kalliita kiviä ja kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran ja Kanne, ja Eden ynnä Seban kauppamiesten kanssa, Assur ja Kilmad olivat myös sinun kauppamiehes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Kaikki nämät kaupitsivat sinulle kalliita vaatteita, silkkiä ja neulotuita hameita, jotka he kalliissa sederarkuissa hyvin tallella pantuna toivat sinun markkinoilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Mutta Tarsiksen laivat olivat ylimmäiset sinun kaupassas; niin sinä olet peräti rikkaaksi ja jaloksi tullut keskellä merta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Ja sinun haaksimiehes toivat sinun suurilla vesillä; mutta itätuulen pitää sinun musertaman rikki keskellä merta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Niin että sinun tavaras, kauppakalus, ostajas, haaksimiehes, laivain haltias, laivain rakentajas ja sinun kaupitsias, ja kaikki sinun sotamiehes, ja kaikki kanssa sinussa pitää hukkuman keskellä merta, sinun lankeemises päivänä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Niin että satamatkin pitää vapiseman sinun haahteis haltiain huudosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Ja kaikki, jotka soutavat haaksimiesten ja haahtein haltiain kanssa, pitää laivoista menemän maalle seisomaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Ja pitää kovin huutaman sinun tähtes, ja vaikiasti valittaman, ja heittämän tomua päänsä päälle, ja tuhkaan itsensä tahraaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Heidän pitää ajeleman hiukset päästänsä, ja pukeman säkit yllensä, ja sydämestänsä itkemän sinua, ja haikiasti murehtiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Heidän pitää valituksessansa sinua itkemän ja surkutteleman: voi! kuka on ikänä niin pois tullut merellä kuin Tyro!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Kuin sinä kauppaa teit merellä, ravitsit sinä monta kansaa; ja sinun monella tavarallas ja kaupallas teit sinä maan kuninkaat äveriäiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Mutta nyt sinä olet mereltä sysätty, juuri syvään veteen, niin että sinun kauppas ja kaikki sinun kansas sinussa on hukkunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Kaikki, jotka luodoissa asuvat, hämmästyvät sinua, ja heidän kuninkaansa tyhmistyvät ja katsovat murheellisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Kansain kauppamiehet viheltävät sinua, että sinä niin äkisti hävinnyt olet, ja et silleen enään taida tulla ylös ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Sinä ihmisen poika, sano Tyron ruhtinaalle: näin sanoo Herra, Herra: että sinun sydämes paisuu, ja sinä sanot: minä olen Jumala, minä istun Jumalan istuimella keskellä merta; vaikka sinä olet ihminen ja et Jumala, kuitenkin yltyy sinun sydämes, niin kuin Jumalan sydän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Katso, sinä olet olevinas viisaampi Danielia, ettei sinulta mitään salattu olisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Ja että sinä toimellas ja taidollas olet sen voiman saanut, ja koonnut sinun tavaroihis kultaa ja hopiaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Ja olet sinun suurella viisaudellas ja kaupallas niin suuren voiman saanut; siitä sinä olet niin ylpiäksi tullut, että sinä niin voimallinen olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Sentähden sanoo Herra, Herra näin: että sinun sydämes ylpeilee, niinkuin sinä Jumala olisit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Sentähden katso, minä tahdon lähettää muukalaiset sinun päälles, julmat pakanat; heidän pitää miekkansa vetämän sinun kaunista viisauttas vastaan, ja tekemän sinbun suuren kunnias häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Heidän pitää sinun paiskaaman luolaan, että sinun pitää kuoleman keskellä merta, niinkuin tapetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Mitämaks, jos sinä murhaajalles sanot: minä olen Jumala; vaikka et sinä Jumala ole, vaan ihminen, ja olet sinun murhaajas kädessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Sinun pitää kuoleman, niinkuin ympärileikkaamattomat, muukalaisten käsiin; sillä minä olen sen sanonut, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Sinä, ihmisen poika, itke valitusitku Tyron kuninkaasta, ja sano hänelle: näin sanoo Herra, Herra: sinä olet kauniisti tehty sinetti, täynnä viisautta ja sangen ihana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Sinä olet Edenissä, Jumalan yrttitarhassa, ja kaunistettu kaikkinaisilla kalliilla kivillä, sardilla, topasilla, timantilla, turkosilla, onikilla, jaspiksilla, saphirilla, rubinilla, smaragdilla ja kullalla: sinä päivänä, kuin sinä luotiin, olivat valmiina sinun tykönäs sinun rumpus ja huilus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Sinä olet niinkuin Kerub, voideltu peittämään; ja minä olen sinun asettanut, ja sinä olet Jumalan pyhällä vuorella, että sinun kuumain kivien seassa vaeltaman pitäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Ja olit vakaa sinun teissäs, siitä päivästä kuin sinä luotu olit, siihenasti kuin sinun pahuutes löydettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Sillä sinä olet sisältä täynnä pahuutta sinun suuresta kaupastas, ja olet syntiä tehnyt: sentähden tahdon minä sinun eroittaa Jumalan vuorelta, ja tahdon sysätä pois sinua, sinä peittävä Kerub kuumista kivistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Ja että sinun sydämes paisuu, ettäs niin ihana olet, ja olet antanut kavaluutes sinus pettää koreudessas; sentähden tahdon minä kukistaa sinun maahan, ja tehdä sinun ihmeeksi kuninkaille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Sillä sinä turmelit sinun pyhyytes suurella pahuudellas ja väärällä kaupallas: sentähden tahdon minä antaa tulen sinusta tulla, joka sinun kuluttaman pitää, ja teen sinun tuhaksi maan päällä kaikkein niiden silmäin edessä, jotka sinun näkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Kaikki, jotka sinun tuntevat pakanain seassa, pitää hämmästymän sinun tähtes; sinä olet suureksi pelvoksi, ettes ikänä enään taida tulla ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Sinä ihmisen poika, aseta kasvos Zidonia vastaan, ja ennusta häntä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Ja sano: näin sanoo Herra, Herra: katso, minä tahdon sinun kimppuus, Zidon, ja tahdon voittaa kunnian sinusta, että ymmärrettäisiin, että minä olen Herra, kuin minä annan oikeuden käydä hänen ylitsensä, ja hänessä osoitan, että minä pyhä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Ja lähetän ruton hänen sekaansa ja veren vuodatuksen hänen kaduillensa, ja heidän pitää kuolemahaavoissa lankeeman miekallas, jonka pitää tuleman heidän päällensä joka taholta; ja heidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Ja ei pidä sitte ympäri Israelin huoneita, joissa heidän vihollisensa ovat, orjantappuroita, jotka pistävät, eikä ohdakkeita, jotka heitä vaivaavat, jäämän, että heidän pitää ymmärtämän, että minä olen Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Näin sanoo Herra, Herra: kuin minä Israelin huonetta kokoon kansoista, joihin he hajoitetut ovat, niin minä tahdon heissä osoittaa pakanoille, että minä pyhä olen; ja heidän pitää asuman maallansa, jonka minä palvelialleni Jakobille antanut olin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Ja heidän pitää murheetoinna asuman siinä, ja huoneita rakentaman, ja istuttaman viinapuita, juuri murheetoinna he asuvat, kuin minä annan oikeuden käydä kaikkein heidän vihollistensa ylitse heidän ympäristöllänsä; ja heidän pitää ymmärtämän, että minä Herra olen heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Kymmenentenä vuotena, kymmenentenä päivänä toisessa kuussa toistakymmentä, tapatui Herran sana minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Sinä, ihmisen poika, aseta kasvos Pharaota, Egyptin kuningasta vastaan, ja ennusta häntä ja koko Egyptin maakuntaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Saarnaa ja sano: näin sanoo Herra, Herra: katso, minä tahdon sinun kimppuus, Pharao, sinä Egyptin kuningas, sinä suuri lohikärme, joka makaat keskellä virtoja, ja sanot: virta on minun, minä olen sen minulleni tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Mutta minä tahdon panna ongen sinun suuhus, ja tahdon ripustaa kalat sinun virrassas sinun suomuksiis; ja tahdon vetää sinun ylös virroistas, ynnä kaikkein kalain kanssa sinun virroissas, jotka sinun suomuksissas riippuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Ja tahdon paiskata sinun korpeen, sinun ja kaikki sinun virtas kalat; sinun pitää lankeeman kedolla, ja ei jälleen noudetuksi ja kootuksi tuleman; vaan metsän pedoille ja taivaan linnuille ruaksi annan minä sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Ja kaikki, jotka Egyptissä asuvat, pitää ymmärtämän, että minä olen Herra, että he Israelin huoneelle ruokosauvana olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Kuin he sinuun rupesivat, menit sinä rikki, ja viilsit koko heidän kylkensä; kuin he nojasivat sinun päälles, murruit sinä, ja saatit heidän kupeensa horjumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Sentähden sanoo Herra, Herra näin: katso, minä annan miekan tulla sinun päälles, ja tahdon hävittää sinussa ihmiset ja eläimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Ja Egyptin maa pitää tuleman tyhjäksi ja autioksi, ja heidän pitää ymmärtämän, että minä olen Herra, että hän sanoo: virta on minun, ja minä olen sen tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Sentähden katso, minä tahdon sinun ja sinun virtas kimppuun, ja teen Egyptin maan peräti tyhjäksi ja autioksi, Sevenan tornista Etiopian rajaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Ei sen lävitse pidä ihmisen eikä eläimen jalka käymän, eikä siinä asuttaman neljässäkymmenessä ajastajassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Sillä minä hävitän Egyptin maan hävinneiden maiden keskellä, ja annan sen kaupungit autioksi tulla hävitettyin kaupunkien keskellä neljäksikymmeneksi ajastajaksi; ja tahdon hajoittaa Egyptiläiset pakanain sekaan, ja hajoittaa heitä maakuntiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Sillä näin sanoo Herra, Herra: kuin neljäkymmentä ajastaikaa kuluvat, niin minä taas kokoon Egyptiläiset niistä kansoista, joihinka he hajoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Ja käännän Egyptin vankiuden, ja tuon heitä Patroksen maalle jälleen, jossa heidän asuma-maansa on; ja se pitää oleman halpa valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Sillä sen pitää oleman halvan muiden maakuntain suhteen, ja ei enään hallitseman pakanoita; ja minä tahdon vähentää heitä niin, ettei heidän vallitseman pidä pakanoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Ja Israelin huoneen ei pidä enään luottaman heihin, vaan muistaman syntiänsä, koska he heidän päällensä katsovat, ja ymmärtävät, että minä olen Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Ja se tapahtui seitsemäntenä vuotena kolmattakymmentä, ensimäisenä päivänä ensimäisessä kuussa, että Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Sinä, ihmisen poika, Nebukadnetsar, Babelin kuningas on vienyt sotajoukkonsa suurella vaivalla Tyron eteen; niin että koko pää on paljas, ja kaikki olkapäät kuluneet, ja hänen vaivansa, jonka hän on nähnyt Tyroa vastaan, on vielä hänelle ja hänen sotajoukollensa maksamatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Sentähden sanoo Herra, Herra näin: katso, minä annan Nebukadnetsarille, Babelin kuninkaalle Egyptin maan, että hänen pitää ottaman pois kaikki hänen tavaransa, ja peräti ryöstämän ja ryöväämän hänen saaliinsa, että hän antais sotajoukollensa palkan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Hänen työstänsä, jonka hän siinä tehnyt on, annan minä hänelle Egyptin maan; sillä he ovat sen minulle tehneet, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Silloin minä annan Israelin huoneen sarven kasvaa, ja tahdon avata sinun suus heidän seassansa; että heidän ymmärtämän pitää, että minä Herra olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Sinä, ihmisen poika, ennusta ja sano: näin sanoo Herra, Herra: valittakaat ja sanokaat: voi sitä päivää!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Sillä päivä on sangen läsnä, ja Herran päivä on lähestynyt, pilvinen päivä: aika on käsissä, että pakanat tuleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Ja miekka tulee Egyptin päälle, Etiopian pitää hämmästymän, kuin lyödyt Egyptissä lankeevat, ja sen kansa viedään pois, ja sen perustus revitään ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Etiopia, ja Lydia, ja Lydia, kaikki kansoinensa, ja Kub, ja jotka liiton maakunnasta ovat, kaatuvat miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Näin sanoo Herra, Herra: Egyptin holhoja lankee, ja sen väkevyyden ylpeys on hukkuva: Sevenan tornista pitää heidän miekalla lankeeman, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Ja heidän autiot rajansa pitää kylmille tuleman, hävitettyin maakuntain keskellä, ja heidän kaupunkinsa hävitettämän muiden autioiden kaupunkien seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Että heidän pitää ymmärtämän, että minä olen Herra, kuin minä teen tulen Egyptiin, ja kaikki, jotka heitä auttavat, hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Silloin sanansaattajat lähtevät ulos minun tyköäni haaksilla, peljättämään Etiopiaa, joka nyt niin surutoin on; ja hämmästyksen pitää oleman heidän seassansa, niinkuin se tapahtui Egyptille, kuin hänen aikansa tuli; sillä katso, se tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Näin sanoo Herra, Herra: minä vähennän sen paljouden Egyptistä Nebukadnetsarin, Babelin kuninkaan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Sillä hän ja hänen kansansa, ne pakanain tyrannit, ovat siihen kutsutut hävittämään maata, ja vetämään miekkansa Egyptiä vastaan, että maakunta piti lyödyillä täytettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Ja minä tahdon kuivata virrat, ja myydä maan tylyin ihmisten käsiin, ja hävitän maakunnan ja mitä siinä on, muukalaisten kautta. Minä Herra olen sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Näin sanoo Herra, Herra: minä hävitän kuvat, ja lopetan epäjumalat Nophista; ja Egyptillä ei pidä ruhtinaita oleman, ja minä lähetän hämmästyksen Egyptin maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Ja teen Patroksen autioksi, ja sytytän tulen Zoaniin, ja annan oikeuden käydä Noon päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Ja kaadan minun julmuuteni Sinin päälle, joka Egyptin vahvuus on, ja hävitän Noon paljouden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Ja sytytän tulen Egyptissä, ja Sinissä pitää oleman hädän ja tuskan, ja Noo pitää kukistettaman maahan: ja Nophilla pitää jokapäiväiset viholliset oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Nuoret miehet Avenissa ja Pibastissa pitää miekalla lankeeman; ja vaimot vankina vietämän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Tahpanheksella pitää oleman pimiä päivä, kuin minä siellä Egyptin ijestä lyön, niin että hänen väkevyytensä ylpeys pitää siinä loppuman; hänen pitää pilvellä peitetyksi tuleman, ja hänen tyttärensä viedään pois vankina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Ja minä annan oikeuden käydä Egyptin ylitse; ja heidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Ja tapahtui ensimäisenä vuotena toistakymmentä, seitsemäntenä päivänä ensimäisessä kuussa, että Herran sana tapahtui minlle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Sinä ihmisen poika, minä taitan rikki Pharaon, Egyptin kuninkaan käsivarren; ja katso, ei sitä pidä sidottaman, että hän paranis, eli siteillä käärittämän, että hän vahvistuis, ja miekkaan ruveta taitais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Sentähden näin sanoo Herra, Herra: katso, minä tahdon Pharaon, Egyptin kuninkaan kimppuun, ja taitan hänen käsivartensa rikki, sekä sen vahvan että särjetyn, ja pudotan miekan hänen kädestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Ja hajoitan Egyptiläiset pakanain sekaan, ja ajan heitä maakuntiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Mutta Babelin kuninkaan käsivarren minä vahvistan, ja annan hänelle minun miekkani käteensä, ja muserran Pharaon käsivarret rikki, että hänen pitää huokaaman hänen edessänsä, niinkuin se, joka kuolemahaavan saanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Ja minä vahvistan Babelin kuninkaan käsivarret; ja Pharaon käsivarret pitää muserrettaman rikki, että heidän pitää tietämän, että minä olen Herra, kuin minä annan Babelin kuninkaalle minun miekkani käteen, että hänen sen Egyptiä vastaan vetämän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Ja minä hajoitan Egyptiläiset pakanain sekaan, ja ajan heitä maakuntiin, että heidän ymmärtämän pitää, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Ja tapahtui ensimmäisenä vuotena toistakymmentä ensimmäisenä päivänä kolmannessa kuukaudessa, että Herran sana tapahtui minulle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Sinä, ihmisen poika, sano Pharaolle, Egyptin kuninkaalle ja hänen kansallensa: kenen vertaiseksi sinä luulet itses sinun suuruudessas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Katso, Assur oli niinkuin sedripuu Libanonissa, ihanaisilla oksilla, paksuilla lehdillä, sangen korkia, että hänen latvansa oli kaikkein korkein muiden paksuin oksain seassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vedet tekivät hänen suureksi ja syvyys korkiaksi; hänen virtansa kävivät ympäri hänen kantoansa, ja ojansa antoi hän vuotaa kaikkien puiden tykö maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Sentähden tuli hän muita puita korkiammaksi, ja sai monta oksaa ja pitkää varpua; sillä hänellä oli kyllä vettä, itsiänsä levittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Kaikki taivaan linnut tekivät pesänsä hänen oksiinsa, ja kaikki pedot kedolla poikivat hänen varpujensa alla, ja hänen varjonsa alla asuivat kaikki suuret kansat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Hänellä oli kauniit ja pitkät oksat; sillä hänen juurillansa oli paljon vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Ja ei yksikään sedripuu ollut Jumalan puutarhassa hänen veransa, eikä hongatkaan olleet hänen oksiinsa verrattavat, ei myös plataneapuut olleet mitään hänen oksainsa suhteen; ja ei Jumalan puutarhassa ollut yhtään puuta hänen kaltaistansa kauneudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Minä olen sen kauniiksi tehnyt saamaan niin monta oksaa, että kaikki ihanaiset puut Jumalan puutarhassa kadehtivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Sentähden sanoo Herra, Herra näin että hän niin korkiaksi tullut on, että hänen latvansa seisoi suurten ja korkiain paksuin oksain seassa, ja hänen sydämensä paisui hänen korkeutensa tähden:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Sentähden annoin minä hänen kaikkein väkevimmän käsiin pakanain seassa, joka hänen kanssansa mielensä jälkeen toimittaa; ja minä ajoin hänen pois, niinkuin hän jumalattomalla menollansa ansainnut oli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Että muukalaiset pakanain tyrannit hänen hävittäisivät, ja hajoittaisivat hänen, että hänen oksansa vuorella ja kaikissa laaksoissa makaisivat, ja hänen oksansa murtuneina kaikissa maan ojissa olisivat; että kaikkein kansain maan päällä täytyy hänen varjoansa paeta, ja sen jättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Ja kaikki taivaan linnut istuivat hänen langenneilla kannoillansa, ja kaikki pedot kedolla nojasivat hänen oksiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Ettei enään yksikään puu veden tykönä iso olisi korkeudestansa, eikä sen latva seisoisi korkiana suurten paksuin oksain seassa, ja ettei yksikään puu veden tykönä tekisi itsiänsä suuremmaksi muita; sillä heidän kaikkein pitää maan alle ja kuolemalle annetuksi tuleman, niinkuin muutkin ihmiset, jotka kuoppaan menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Näin sanoo Herra, Herra: siihen aikaan, kuin hän meni alas helvettiin, tein minä murheen, ja annoin syvyyden peittää hänen, ja hänen virtansa piti oleman alallansa, ja ne suuret vedet ei taitaneet juosta, ja tein, että Libanon murehti hänen tähtensä, ja kaikki puut kedolla kuivettuivat hänen tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Minä peljätin pakanat, kuin he kuulivat hänen langenneeksi, ja että minä syöksin hänen alas helvettiin niiden sekaan, jotka kuoppaan menevät; ja kaikki ihanaiset puut maassa, parhaat ja jaloimmat Libanonissa, ja kaikki, jotka olivat seisoneet veden tykönä, saivat siitä lohdutuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Sillä heidän piti myös alas menemän heidän kanssansa helvettiin miekalla tapettuin tykö, että he hänen käsivartensa varjon alla pakanain seassa asuneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Kuinka suureksi sinä (Pharao) luit sinun ylpeytes ja suuruutes niiden ihanain puiden seassa? Sillä sinun täytyy ihanain puiden kanssa mennä alas maan alle, ja ympärileikkaamattomain seassa maata, jotka miekalla tapetut ovat. Niin pitää Pharaolle tapahtuman, ja kaikelle hänen kansallensa, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Ja tapahtui toisena vuotena toistakymmentä, ensimäisenä päivänä toisessa kuukaudessa toistakymmentä, että Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Sinä, ihmisen poika, tee valitus Pharaosta, Egyptin kuninkaasta, ja sano hänelle: sinä olet niinkuin nuori jalopeura pakanain seassa, ja niinkuin valaskala meressä, joka juokset sinun virroissas, ja pyörrät veden jaloissas, ja teet sen virrat sekaisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Näin sanoo Herra, Herra: minä heitän minun verkkoni sinun päälles suurella kansan joukolla, jotka sinun minun verkkooni ajavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Ja minä tahdon sinun maalle vetää ja kedolle paiskata, ja antaa kaikki linnut taivaan alla istua sinun päälles, ja kaikki eläimet maalla sinusta ravituksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Ja tahdon sinun raatos vuorille heittää, ja sinun korkeudellas laaksot täyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Maan, jossa uit, tahdon minä sinun verestäs punaiseksi tehdä vuoriin asti, että ojat sinusta täytettäisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Ja koskas peräti jo poissa olet, tahdon minä taivaan peittää, ja hänen tähtensä pimittää, ja peitän auringon pilvellä, eikä kuun pidä paistaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Kaikki taivaan valkeudet tahdon minä pimiäksi saattaa sinun ylitses, ja pimeyden sinun maalles lähettää, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Tahdon myös monen kansan sydämet peljättää, kuin minä sinun vaivas pakanoille tiettäväksi teen, ja monelle maakunnalle, joita et sinä tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Paljo kansaa pitää sinua ihmettelemän, ja heidän kuninkaansa pitää sinun tähtes kovin pelkäämän, kuin minä annan minun miekkani heitä vastaan välkkyä; ja heidän pitää äkisti peljästymän kukin sydämessänsä sinun lankeemises päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Sillä näin sanoo Herra, Herra: Babelin kuninkaan miekka pitää sinuun sattuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Ja minä tahdon sinun väkes langettaa sankarien miekan kautta ja kaikkinaisten pakanain tyrannein kautta: heidän pitää Egyptin ylpeyden hävittämän, että kaikki hänen kansansa teloitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Ja tahdon kaikki hänen eläimensä suurten vetten tyköä peräti hävittää, ettei yhdenkään ihmisen jalka, eikä yhdenkään eläimen sorkka pidä sitä ollenkaan enään tallaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Silloin tahdon minä heidän vetensä selkiäksi tehdä, että heidän virtansa juoksevat niinkuin öljy, sanoo Herra, Herra;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Kuin minä Egyptin maan, ja mitä siinä maassa on, peräti hävittänyt, ja kaikki jotka siinä asuvat, tappanut olen; että he ymmärtäisivät, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Sepä se surkeus on, jota kyllä valitetaan, ja monta pakanain tytärtä pitää sitä valittaman; Egyptiä ja kaikkea hänen kansaansa pitää valitettaman, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Ja tapahtui toisena vuotena toistakymmentä, viidentenä päivänä toistakymmentä siitä kuukaudesta, että Herran sana tapahtui minulle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Sinä, ihmisen poika, itke Egyptin kansaa, ja syökse heitä väkeväin sankarien tytärten kanssa alas maan alle, niiden tykö, jotka kuoppaan menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Kenen sinä luulit voittavas ihanaisuudessa? astu alas ja pane itses ympärileikkaamattomain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Heidän pitää surmattuin kanssa miekalla kaatuman; jopa miekka on sivallettu ulos; viekäät siis häntä pois hänen joukkoinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Siitä puhuvat väkevät sankarit helvetissä apulaistensa kanssa, jotka kaikki ovat menneet alas, ja makaavat siellä ympärileikkaamattomain miekalla tapettuin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Siinä Assur makaa kaiken kansansa kanssa ympäristölle haudattu, jotka kaikki tapetut ja miekalla kaatuneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Heidän hautansa ovat kuopan vieressä, ja hänen kansansa makaa joka paikassa ympäri haudattuna, jotka kaikki tapetut ja miekalla kaatuneet ovat, joita myös koko maailma pelkäsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Siinä myös makaa Elam koko joukkonsa kanssa ympäristölle haudattu, jotka kaikki tapetut ja miekalla kaatuneet ovat, ja menneet alas niinkuin ympärileikkaamattomat maan alle, joita myös koko maailma pelkäsi, ja heidän täytyy häpiänsä kantaa niiden kanssa, jotka kuoppaan alas menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'He panivat vuoteensa tapettuin sekaan, ynnä koko joukkonsa kanssa, ja makaavat ympäristölle haudatut, ja ovat kaikki ympärileikkaamattomat ja miekalla tapetut, joita myös koko maailma pelkäsi, ja heidän täytyy häpiänsä kantaa niiden kanssa, jotka kuoppaan menevät, ja pitää tapettuin seassa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Siinä makaa Mesek ja Tubal koko joukkonsa kanssa ympäristöllä haudatut, jotka kaikki ympärileikkaamattomat ja miekalla tapetut ovat, joita myös koko maailma pelkäsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Ja ei heidän pidä makaaman sankarien kanssa, jotka ympärileikkaamattomista kaatuneet ovat, jotka sota-aseinensa menivät alas helvettiin, ja panivat miekkansa päänsä alle, ja heidän pahantekonsa oli heidän luissansa, sillä he olivat voimallisten pelko koko maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Niin sinä myös kaiketi ympärileikkaamattomain seassa murskaksi lyödään; ja sinun täytyy niiden seassa maata, jotka miekalla tapetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Siinä makaa Edom kuninkainensa ja kaikki hänen ruhtinaansa, jotka väkevyydessänsä ovat annetut miekalla tapettuin sekaan; ja heidän pitää makaaman ynnä muiden kanssa, jotka kuoppaan menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Sinne pitää myös menemän kaikki päämiehet pohjoisesta ja kaikki Zidonilaiset, jotka tapettuin kanssa ovat menneet alas, ja heidän hirmuinen voimansa häpiään tullut, ja täytyy maata ympärileikkaamattomain seassa ja niiden seassa, jotka miekalla tapetut ovat, ja heidän häpiänsä kantaa ynnä niiden kanssa, jotka kuoppaan menevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Näitä pitää Pharaon näkemän, ja itsiänsä lohduttaman kaiken kansansa kanssa, jotka miekalla tapetut ovat, Pharao ja koko hänen sotajoukkonsa, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Sillä koko maailman pitää myös minua kerran pelkäämän, että Pharao ja koko hänen paljoutensa pitää ympärileikkaamattomain seassa ja miekalla tapettuin seassa makaaman, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Ja Herran sana tapahtui minulle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Sinä ihmisen poika, saarnaa kansas lapsille ja sano heille: jos minä vetäisin miekan maakunnan ylitse, ja maan kansa ottais yhden miehen huonommistansa ja tekis sen vartiaksensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Ja hän näkis miekan tulevan maan ylitse, ja soittais vaskitorvea ja varais kansaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Joka sitte soittamisen kajahduksen täydellisesti kuulee, ja ei tahdo itsiänsä kavahtaa, ja miekka tulis ja ottais hänen pois; sen veri olkoon hänen päänsä päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Sillä hän kuuli soittamisen kajahduksen, ja ei kuitenkaan itsestänsä pitänyt vaaria, sentähden olkoon hänen verensä hänen päällänsä. Mutta joka neuvoa tottelee, hän pelastaa henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Mutta jos vartia näkis miekan tulevan, ja ei soittaisi vaskitorvea, eikä kansa pitäisi vaaria, ja miekka tulis ja ottais jonkun pois: hän tosin otettaisiin pois synteinsä tähden, mutta hänen verensä tahdon minä vartian kädestä vaatia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Ja sinä ihmisen poika, minä olen pannut sinun Israelin huoneen vartiaksi, kuin sinä jotakin minun suustani kuulet, että sinun pitäis heitä minun puolestani varaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Kuin minä sanon jumalattomalle: sinä jumalatoin, sinun pitää totisesti kuoleman, ja et sinä hänelle sitä sano, että jumalatoin ottais vaarin menostansa; niin pitää jumalattoman syntinsä tähden kuoleman, mutta hänen verensä tahdon minä sinun kädestäs vaatia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Mutta jos sinä jumalatointa varoitat hänen tiestänsä, että hän siitä kääntyis, ja hän ei palaja tiestänsä; niin pitää hänen syntinsä tähden kuoleman, ja sinä olet pelastanut sielus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Sentähden sinä, ihmisen poika, sano Israelin huoneelle: te lausutte näin, sanoen: meidän pahatekomme ja rikoksemme makaavat meidän päällämme, että me niiden alla hukumme, kuinka me taidamme elää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Niin sano heille: niin totta kuin minä elän, sanoo Herra, Herra, ei minulle kelpaa jumalattoman kuolema, mutta että jumalatoin kääntyis tiestänsä ja eläis. Palatkaat, palatkaat teidän pahoista teistänne! ja miksi teidän pitäis kuoleman, te Israelin huone?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ja sinä, ihmisen poika, sano sinun kansas lapsille: sinä päivänä, jona hurskas pahaa tekee, ei hänen vanhurskautensa pidä häntä auttaman; ja jumalattoman ei pidä jumalattomuudessansa lankeeman sinä päivänä, kuin hän itsensä kääntää jumalattomuudestansa; ja vanhurskas ei taida elää vanhurskautensa tähden sinä päivänä, jona hän syntiä tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Kuin minä hurskaalle sanon: hänen pitää totisesti elämän, ja hän luottaa vanhurskauteensa, ja tekee pahaa; niin ei pidä hänen vanhurskauttansa ensinkään muistettaman, mutta hänen pitää kuoleman pahuudessansa, jonka hän tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Ja kuin minä jumalattomalle sanon: sinun pitää totisesti kuoleman, ja hän parantaa itsensä synnistänsä, ja tekee oikein ja hyvin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Niin että jumalatoin pantin antaa jälleen, ja maksaa mitä hän on ryövännyt, ja elämän sanan jälkeen elää, ettei hän pahaa tee; niin hän saa totisesti elää, ja ei pidä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Kaikki hänen syntinsä, jotka hän tehnyt on, pitää unhotettaman; sillä hän tekee, mikä hyvä ja oikia on, sentähden hän saa totisesti elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Ja sinun kansas lapset sanovat: ei Herra oikein tuomitse; ja kuitenkin heillä on vääryys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Sillä jos hurskas kääntää itsensä pois hurskaudestansa, ja tekee pahaa, niin hän kuolee syystä sentähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Ja jos jumalatoin parantaa itsensä jumalattomasta menostansa, ja tekee oikein ja hyvin, niin hän saa sentähden kaiketi elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Kuitenkin te sanotte: ei Herra oikein tuomitse; vaikka minä teille, te Israelin huone, kullekin menonsa jälkeen tuomitsen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Ja tapahtui toisena vuotena toistakymmentä meidän vankiudestamme, viidentenä päivänä kymmenennessä kuukaudessa, että minun tyköni tuli yksi paennut Jerusalemista, ja sanoi: kaupunki lyötiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Ja Herran käsi oli minun päälläni ehtoona, ennenkuin se paennut tuli, ja avasi minun suuni, siksi kuin hän tuli huomeneltain minun tyköni; ja niin hän avasi minun suuni, etten minä taitanut enää vaiti olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Sinä ihmisen poika, tämän korven asuvaiset Israelin maalla sanovat näin: Abraham oli ainoasti yksi mies, ja peri tämän maan; mutta meitä on paljo, niin meillä on siis tämä maa sitä oikeammin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Sano siis heille: näin sanoo Herra, Herra: te olette verta syöneet, ja nostaneet teidän silmänne epäjumalain tykö, ja olette verta vuodattaneet, ja te luulette, että te omistatte maan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Te seisotte aina miekka kädessä ja teette kauhistuksia, ja toinen häpäisee toisen emännän ja te luulette, että te omistatte maan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Niin sano heille: näin sanoo Herra, Herra: niin totta kuin minä elän, niin pitää kaikki, jotka korvessa asuvat, miekan kautta lankeeman, ja mitä kedolla on, annan minä pedoille syötää, ja ne jotka linnoissa ja luolissa ovat, pitää ruttoon kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Sillä minä tahdon maan peräti hävittää, ja sen ylpeydelle ja voimalle lopun tehdä, että Israelin vuoret pitää niin autioksi tuleman, ettei kenenkään pidä vaeltaman siitä ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Ja heidän pitää tietämän, että minä olen Herra, koska minä olen maan peräti hävittänyt kaikkein heidän kauhistustensa tähden, joita he tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Ja sinä ihmisen poika, sinun kansas lapset puhuvat sinua vastaan siellä ja täällä, seinillä ja ovien edessä, ja toinen sanoo toisellensa, kukin veljellensä, sanoen: käykäämme kuulemaan, mitä Herra sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Ja he tulevat sinun tykös seurakuntaan, ja istuvat sinun edessäs niinkuin minun kansani, ja kuulevat sinun sanas, mutta ei he tee ensinkään sen jälkeen; he tekevät tosin ystävyyttä suullansa, mutta sydämellänsä he seuraavat ahneuttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Ja katso, sinun täytyy olla heidän ilovirtensä, jota he mielellänsä laulavat ja soittavat; niin he sinun sanas kyllä kuulevat, mutta ei he tee sen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Mutta kuin se tulee, joka tuleva on, katso, niin he saavat nähdä, että propheta on heidän seassansa ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Sinä, ihmisen poika, ennusta Israelin paimenia vastaan, ennusta ja sano heille, jotka paimenet ovat: näin sanoo Herra, Herra: voi Israelin paimenia, jotka itsiänsä ruokkivat! eikö paimenten pitäisi laumaa ruokkiman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Mutta te syötte lihavaa, ja verhoitatte teitänne villoilla, ja teurastatte syötetyitä; mutta ette tahdo ruokkia lampaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Heikkoja ette tue, sairaita ette paranna, haavoitettuja ette sido, eksyneitä ette palauta, kadonneita ette etsi; mutta kovin ja ankarasti hallitsette heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Ja minun lampaani ovat hajoitetut, niinkuin ne, joille ei paimenta ole, ja ovat kaikille pedoille ruaksi tulleet, ja ovat peräti hajoitetut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Ja käyvät eksyksissä kaikilla vuorilla ja korkeilla kukkuloilla; ja ovat kaikkeen maahan hajoitetut, ja ei ole ketään, joka heitä kysyy eli tottelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Sentähden te paimenet, kuulkaat Herran sanaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Niin totta kuin minä elän, sanoo Herra, Herra: että te annatte minun lampaani raatelukseksi ja minun laumani kaikille pedoille ruaksi, ettei heillä ole paimenta, ja minun paimeneni ei pidä lukua minun laumastani; vaan ovat senkaltaiset paimenet, jotka itsiänsä ruokkivat, mutta minun lampaitani ei he tahdo ruokkia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Sentähden, te paimenet, kuulkaat Herran sanaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Näin sanoo Herra, Herra: katso, minä tahdon paimenien kimppuun, ja tahdon minun laumani heidän käsistänsä vaatia, ja tahdon heitä lopettaa, ettei heidän pidä enään paimenena oleman eikä itsiänsä ruokkiman; minä tahdon minun lampaani heidän suustansa temmata ulos, ja ei ne pidä oleman heidän ruokansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Sillä näin sanoo Herra, Herra: katso, minä tahdon itse pitää murheen lampaistani, ja tahdon heitä etsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Niinkuin paimen etsii lampaitansa, kuin he laumastansa eksyneet ovat, niin tahdon minä myös minun lampaitani etsiä; ja tahdon heitä kaikista paikoista pelastaa, joihin he hajoitetut ovat, siihen aikaan kuin sumu ja pimiä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Ja tahdon heitä kaikista kansoista viedä ulos, ja kaikista maakunnista koota, ja heitä omalle maallensa viedä; ja kaita heitä Israelin vuorilla, ojain tykönä kaikissa suloisissa paikoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Ja heitä parhaalle laitumelle viedä, ja heidän majansa pitää korkeilla Israelin vuorilla seisoman; siinä heidän pitää levollisessa varjossa makaaman, ja heillä pitää oleman lihava laidun Israelin vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Minä tahdon itse minun lampaani ruokkia, ja minä tahdon heitä sioittaa, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Kadonneet tahdon minä etsiä ja eksyneet tallelle tuottaa, haavoitetut sitoa, heikkoja vahvistaa; lihavia ja väkeviä tahdon minä hävittää, ja kaitsen heitä toimellisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Mutta teille, minun laumani, sanoo Herra, Herra näin: katso, minä tahdon tuomita lampaan ja lampaan välillä ja oinasten ja kauristen välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Eikö siinä kyllä ole, että teillä niin hyvä laidun on, ja jääneet teidän laitumistanne te jaloillanne tallaatte, ja niin jalot lähteet juoda, että te jäänneet jaloillanne tallaatte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Että minun lampaani pitää syömän sitä, jota te olette jaloillanne sotkuneet, ja pitää myös juoman sitä, jota te tallanneet olette jaloillanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Sentähden näin sanoo Herra, Herra heille: katso, minä tahdon tuomita lihavain ja laihain lammasten välillä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Että te potkitte jaloillanne, ja puskette heikkoja sarvillanne, siihenasti kuin te heidät hajoitatte ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Ja minä tahdon auttaa minun laumaani, ettei sitä pidä enään raatelukseksi annettaman, ja tahdon tuomita lampaan ja lampaan välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Ja minä tahdon yhden ainokaisen paimenen herättää, joka heitä on ravitseva, palveliani Davidin: hän on heitä ravitseva ja on heidän paimenensa oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Ja minä Herra tahdon olla heidän Jumalansa, mutta minun palveliani David on heidän seassansa päämies oleva; minä Herra olen sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Ja minä tahdon rauhan liiton heidän kanssansa tehdä, ja kaikki pahat eläimet maalta ajaa pois, että he surutoinna korvessa asuisivat ja metsissä makaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Ja tahdon heidät ja kaikki minun kukkulani siunata; ja annan heille sataa oikialla ajalla, joka on armon sade oleva,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Että puut kedolla hedelmänsä kantavat ja maa antaa kasvunsa, ja he asuvat surutoinna maassa; ja heidän pitää tietämän, että minä olen Herra, koska minä heidän ikeensä jutan katkaisen, ja heitä olen pelastanut niiden käsistä, joita heidän pitää palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Ja ei heidän pidä enään pakanoille raatelukseksi oleman, ja ei maan pedot pidä enään heitä syömän, mutta heidän pitää surutoinna ja pelkäämättä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Ja minä tahdon heille kuuluisan vesan herättää; ettei heidän pidä enään nälkää maalla kärsimän, eikä heidän pilkkansa pakanain seassa kantaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Ja heidän pitää tietämän, että minä Herra, Heidän Jumalansa, olen heidän tykönänsä, ja Israelin huone on minun kansani, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Ja te ihmiset pitää oleman minun laitumeni lauma; ja minä tahdon olla teidän Jumalanne, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Sinä, ihmisen poika, pane kasvos Seirin vuorta vastaan, ja ennusta sitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Ja sano sille: näin sanoo Herra, Herra: katso, minä tahdon sinun kimppuus, sinä Seirin vuori; ja minun käteni ojennan minä sinua vastaan, ja tahdon sinun peräti hävittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Minä tahdon sinun kaupunkis hävittää, että sinun pitää autioksi tuleman; ja sinun pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Että te aina ja alinomaa vihaatte Israelin lapsia, ja ajoitte heitä miekkaan, kuin heille pahoin kävi, ja heidän rikoksensa loppu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Sentähden, niin totta kuin minä elän, sanoo Herra, Herra, tahdon minä sinun myös veriseksi tehdä, ja ei sinun pidä veren vuotamisesta pääsemän; ja että veri sinulle kelpaa, niin ei sinun pidä verestä pääsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Ja minä tahdon kaiken Seirin vuoren hävittää ja autioksi tehdä, ettei ketään siitä pidä käymän eikä vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Ja minä tahdon hänen vuorensa tapetuilla täyttää; sinun kukkuloilles, laaksoihis ja kaikkiin sinun virtoihis pitää miekalla tapetut lankeeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Minä tahdon sinun tehdä ijankaikkiseksi hävitykseksi, ettei kenenkään pidä sinun kaupungissas asuman; ja teidän pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Ja että sinä sanot: molemmat kansat ja molemmat maakunnat pitää minun oleman, ja me tahdomme ne ottaa, vaikka Herra niissä asuu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Sentähden, niin totta kuin minä elän, sanoo Herra, Herra, tahdon minä sinulle vihas ja vainos jälkeen tehdä, niinkuin sinä hänelle sulasta vainosta tehnyt olet; ja tahdon heidän seassansa ilmoitetuksi tulla, kuin minä sinun rangaissut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Ja sinun pitää tietämän, että minä Herra kaikki sinun pilkkas kuullut olen, jonka sinä Israelin vuoria vastaan puhunut olet, ja sanonut: he ovat hävitetyt ja meille hävittääksemme * annetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Ja olette minua vastaan suullanne suuresti kerskanneet, ja tuimasti puhuneet, jonka minä olen kuullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Näin sanoo Herra, Herra: minä teen sinun autioksi, että koko maakunta pitää iloitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Niinkuin sinä iloinnut olet Israelin perikuntaa ottaissas, että se autiona oli; niin tahdon minä sinun kanssas tehdä; että Seirin vuori pitää autiona oleman, ynnä koko Edomin kanssa, ja heidän pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Ja sinä, ihmisen poika, ennusta Israelin vuorille ja sano: kuulkaat Herran sanaa, te Israelin vuoret!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Näin sanoo Herra, Herra: että vihollinen pitittää, sanoen: ne ijäiset vuoret ovat meidän perintömme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Sentähden ennusta ja sano: näin sanoo Herra, Herra: sentähden, ja tosin sentähden, että te joka paikassa hävitetään ja sorretaan, olette myös jääneille pakanoille osaksi joutuneet, ja kansan kieliin ja pilkaksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Sentähden kuulkaat, te Israelin vuoret, Herran, Herran sanaa: näin sanoo Herra, Herra, sekä vuorille että kukkuloille, ojille ja laaksoille, hävitetylle autiolle ja hyljätyille kaupungeille, jotka jääneille pakanoille joka taholta ympäri saaliiksi ja nauruksi tulleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Sentähden näin sanoo Herra, Herra: minä olen minun palavassa kiivaudessani puhunut jääneitä pakanoita vastaan, ja koko Edomia vastaan, jotka ovat ottaneet minun maani perinnöksensä, sydämellisellä ilolla ja pilkalla sitä hävittääksensä ja sortaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Sentähden ennusta Israelin maasta, ja sano vuorille ja kukkuloille, ojille ja laaksoille: näin sanoo Herra, Herra: katso, minä olen puhunut minun kiivaudessani ja julmuudessani, että te olette senkaltaista häväistystä pakanoilta kärsineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Sentähden sanoo Herra, Herra näin: minä ylennän minun käteni, niin että teidän lähimmäisenne, pakanat joka taholta ympäri, pitää kantaman häpiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Mutta te, Israelin vuoret, teidän pitää viheriöitsemän, joka pian pitää tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Sillä katso, minä käännän itseni taas teidän tykönne, että te viljeltäisiin ja kylvettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Ja teen teidän tykönänne paljon kansaa, koko Israelin huoneen kaikki tyynni; ja kaupungissa pitää taas asuttaman, ja autiot rakennettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Minä annan teidän kansanne ja karjanne lisääntyä, niin että te enenette ja kasvatte; ja panen teidän siihen jälleen asumaan niinkuin muinenkin ja teen teille enempi hyvää kuin joskus ennen; ja teidän pitää ymmärtämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Minä annan kansan tulla teidän tykönne, minun kansani Israelin, heidän pitää sinussa asuman, ja sinun pitää oleman heidän perintönsä, ja ei sinun pidä enään lapsettomaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Näin sanoo Herra: että sinusta sanotaan: sinä olet syönyt ihmisiä, ja olet tehnyt sinun kansas lapsettomaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Sentähden ei enään sinun pidä syömän ihmisiä, eli kansaas tekemän lapsettomaksi, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Ja en minä tahdo antaa enään sinun kuulla pakanain pilkkaa, eikä sinun pidä enään kansain häväistystä kantaman, ei myös sinun kansaas enään lapsettomaksi tekemän, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Ja Herran sana tapahtui vielä minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Sinä ihmisen poika, kuin Israelin huone asui maallansa, ja saastutti sen menollansa ja töillänsä, niin että heidän menonsa oli minun edessäni niinkuin vaimon saastaisuus hänen taudissansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Silloin minä vuodatin vihani heidän päällensä, sen veren tähden, jonka he maalla olivat vuodattaneet, ja olivat sen epäjumalillansa saastuttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Ja minä hajoitin heidät pakanain sekaan, ja he hajoitettiin maakuntiin; ja minä tuomitsin heitä heidän menonsa ja tekoinsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Ja kuin he myös tulivat pakanain tykö, kuhunka he tulivat, häpäisivät he minun pyhän nimeni, että heistä sanottiin: onko tämä Herran kansa, jonka piti maaltansa lähtemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Mutta minä säästin minun pyhän nimeni tähden, jonka Israelin huone häpäisi pakanain seassa, kuhunka he tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Sentähden pitää sinun sanoman Israelin huoneelle: näin sanoo Herra, Herra: en minä sitä tee teidän tähtenne, te Israelin huone, vaan minun pyhän nimeni tähden, jonka te pakanain seassa olette häväisseet, joiden tykö te tulleet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Sillä minä tahdon pyhittää minun suuren nimeni, joka teiltä pakanain seassa suuresti häväisty on, ja pakanain pitää ymmärtämän minun olevan Herran, sanoo Herra, Herra, koska minä itseni osoitan teissä heidän edessänsä, että minä olen pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Sillä minä tuon teidät pakanoista, ja kokoon teitä kaikista maakunnista, ja annan teidän tulla jälleen teidän maahanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Ja priiskotan puhdasta vettä teidän päällenne, niin että te tulette puhtaaksi; kaikesta teidän saastaisuudestanne ja kaikista teidän epäjumalistanne puhdistan minä teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Ja annan teille uuden sydämen, ja uuden hengen annan minä teihin; ja otan pois teidän lihastanne kivisen sydämen, ja annan teille sydämen lihasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Ja annan minun henkeni teihin, ja teen niin, että te vaellatte minun säädyissäni, ja pidätte minun oikeuteni, ja teette niiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Ja teidän pitää asuman sillä maalla, jonka minä olen teidän isillenne antanut; ja teidän pitää oleman minun kansani, ja minä tahdon olla teidän Jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Minä vapahdan teitä kaikesta teidän saastaisuudestanne, ja sanon jyvälle, että hänen pitää hyvin menestymän, enkä anna teidän nähdä nälkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Minä enennän hedelmän puissa ja kasvatan tulon kedolla, ettei pakanain pidä teitä enään nälän tähden pilkkaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Silloin teidän pitää ajatteleman teidän pahaa menoanne ja teidän töitänne, ettei ne olleet hyvät; ja teidän pitää itseenne suuttuman, teidän rikostenne ja teidän epäjumalanpalveluksenne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'En minä näitä tee teidän tähtenne, sanoo Herra, Herra, sen pitää teidän tietämän; vaan teidän pitää suuresti häpeemän teitänne, te Israelin huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Näin sanoo Herra, Herra: sinä päivänä, kuin minä teitä olen puhdistava kaikista teidän rikoksistanne, niin minä taas tahdon panna asujat kaupungeihin, ja autiamet pitää taas rakennettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Ja hävitetty maa pitää kynnettämän, että se oli turmeltu, kaikkein ohitsekäyväisten silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Ja heidän pitää sanoman: tämä maa oli turmeltu, ja se on nyt niinkuin Edenin ilotarha; ja nämät kaupungit olivat kukistetut, jaotetut ja autiot, ja ovat nyt vahvat, ja niissä asutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Ja jääneet pakanat teidän ympärillänne pitää ymmärtämän, että minä Herra olen jaotetut jälleen rakentanut, ja hävitetyn istuttanut. Minä Herra sen sanonut ja tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Näin sanoo Herra, Herra: Israelin huoneen pitää taas minua kysymän, että minä itseni heille osoitan, ja minä enennän heitä, niinkuin ihmisten lauman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Niinkuin pyhän lauman, niinkuin Jerusalemin lauman hänen juhlinansa, niin pitää hävitetyt kaupungit täyteen tuleman ihmisten laumoista; ja heidän pitää ymmärtämän minun olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Ja Herran käsi rupesi minuun, ja Herra vei minun hengessä ja asetti minun lakialle kedolle, joka oli luita täynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Ja hän johdatti minun niiden kautta aina ympärinsä; ja katso, siinä oli sangen paljo luita kedolla, ja katso, ne olivat peräti kuivettuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Ja hän sanoi minulle: sinä ihmisen poika, luuletkos nämät luut jälleen eläväksi tulevan? Ja minä sanoin: sinä Herra, Herra sen tiedät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Ja hän sanoi minulle: ennusta näistä luista, ja sano heille: te kuivettuneet luut, kuulkaat Herran sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Näin sanoo Herra, Herra näistä luista: katso, minä annan tulla teihin hengen, ja teidän pitää eläväksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Ja annan teille suonet, ja kasvatan lihan teidän päällenne, ja vedän nahan teidän päällenne, ja annan teille hengen, että te jälleen eläväksi tulette; ja teidän pitää tietämän, että minä olen Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Ja minä ennustin niinkuin minulle käsketty oli. Niin tuli hyso, ne rupesivat liikkumaan, ja luut tulivat jälleen yhteen kukin jäseneensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Ja minä näin, ja katso, siihen tulivat suonet ja liha päälle, ja hän peitti ne nahalla; mutta ei niissä vielä henkeä ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Ja hän sanoi minulle: ennusta hengelle, ennusta sinä, ihmisen poika, ja sano hengelle: näin sanoo Herra, Herra: sinä henki, tule tähän neljästä tuulesta, ja puhalla näiden tapettuin päälle, että he jälleen eläväksi tulisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Ja minä ennustin niinkuin hän oli minun käskenyt: niin tuli henki heihin, ja he tulivat eläväksi, ja seisoivat jaloillansa, ja heitä oli sangen suuri joukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Ja hän sanoi minulle: sinä ihmisen poika, nämät luut ovat koko Israelin huone; katso, he sanovat: meidän luumme ovat kuivuneet, meidän toivomme on kadonnut, ja me olemme hukkuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Sentähden ennusta ja sano heille: näin sanoo Herra, Herra: katso, minä avaan teidän hautanne ja tahdon teitä, minun kansani, sieltä tuoda ulos, ja saatan teitä Israelin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Ja teidän pitää tietämän, että minä olen Herra, koska minä olen teidän hautanne avannut, ja teitä, minun kansani, sieltä tuonut ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Ja minä tahdon antaa minun henkeni teihin, että te jälleen virkootte, ja tahdon saattaa teitä teidän maallenne; ja teidän pitää ymmärtämän, että minä olen Herra. Minä sen puhun, ja minä myös sen teen, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Sinä ihmisen poika, ota sinulles yksi puu, ja kirjoita siihen Juudasta ja heidän kumppaneistansa Israelin lapsista; ja ota vielä sitte yksi puu, ja kirjoita siihen Josephin ja Ephraimin suku, ja koko Israelin huone, heidän kumppaninsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Ja liitä heitä molempia yhteen, sinulle yhdeksi puuksi, niin että se tulee kaikki yhdeksi kädessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Jos siis sinun kansas lapset puhuvat sinulle, sanoen: etkös tahdo meille ilmoittaa, mitäs sillä ajattelet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Niin sano heille: näin sanoo Herra, Herra: katso, minä otan Josephin puun, joka on Ephraimin tykönä, ynnä heidän kumppaneinsa Israelin sukuin kanssa, ja panen heidät Juudan puun tykö, ja teen heistä molemmista yhden puun minun kädessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Ja sinun pitää ne puut, joihin sinä kirjoittanut olet, sinun kädessäs niin pitämän, että he sen näkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Ja sinun pitää heille sanoman: näin sanoo Herra, Herra: katso, minä tuon jälleen Israelin lapset pakanoista, joihin he menneet ovat, ja kokoon heidät joka paikasta, ja annan heidän tulla maallensa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Ja teen kaikki yhdeksi kansaksi maalla, Israelin vuorilla; ja heillä kaikilla pitää oleman yksi kuningas, ja ei pidä enään kaksi kansaa eli kahteen valtakuntaan jaetut oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Ei heidän myös pidä enään saastuttaman itsiänsä epäjumalistansa, kauhistuksissa ja kaikkinaisissa rikoksissa. Minä autan heitä kaikista paikoista, joissa he ovat rikkoneet, ja puhdistan heitä, ja heidän pitää oleman minun kanssani, ja minä tahdon olla heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Ja minun palvelijani David pitää oleman heidän kuninkaansa, ja kaikkein heidän yksinäinen paimenensa; ja heidän pitää vaeltaman minun oikeudessani, ja pitämän minun säätyni, ja tekemän niiden jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Ja heidän pitää asuman sillä maalla, jonka minä palvelialleni Jakobille antanut olen, jossa teidän isänne asuneet ovat; heidän ja heidän lapsensa ja lastensa lapset pitää siellä ijankaikkisesti asuman; ja minun palvelijani David pitää oleman heidän ruhtinaansa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Ja minä teen heidän kanssansa rauhan liiton, sen pitää heille ijankaikkisen liiton oleman; ja holhon heitä, ja enennän heitä, ja minun pyhäni pitää oleman heidän seassansa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Ja minun majani pitää oleman heidän seassansa, ja minä tahdon olla heidän Jumalansa; ja heidän pitää oleman minun kansani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Niin että pakanainkin pitää ymmärtämän, että minä Herra pyhitän Israelin; ja minun Pyhäni pitää oleman heidän tykönänsä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Sinä, ihmisen poika, käännä itses Gogia vastaan, joka on Magogin maalla, ja on ylimmäinen Mesekin ja Tubalin päämies, ja ennusta hänestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Ja sano: näin sanoo Herra, Herra: katso, minä tulen kimppuus, sinä Gog, joka olet ylimmäinen Mesekin ja Tubalin päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Ja palautan sinun, ja panen suitset sinun suuhus ja vien sinun ulos kaiken sinun joukkos, hevostes ja ratsasmiestes kanssa, jotka kaikki ovat jalosti valmistetut, joita on suuri joukko, ja kantavat kaikki keihäitä, kilpiä ja miekkoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Sinun myötäs ovat Persialaiset, Etiopialaiset ja Putilaiset, jotka kaikki kantavat kilpiä ja rautalakkeja;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer ja kaikki hänen joukkonsa, ja myös Togarman huone, joka pohjaan päin on, kaiken hänen joukkonsa kanssa; ja sinun myötäs on paljo kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Valmista itses, varusta itses hyvin, sinä ja kaikki sinun joukkos, joka sinun myötäs on: ja ole sinä heidän päämiehensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Sinun pitää kuitenkin viimein rangaistuksi tuleman. Viimeisellä ajalla pitää sinun tuleman siihen maahan, joka on jälleen saatu miekalla, on myös koottu monesta kansasta, Israelin vuorelle, joka kauvan aikaa on autiona ollut; ja on nyt monesta kansasta johdatettu ulos, ja kaikki surutoinna asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Sinun pitää menemän ylös ja tuleman suurella raju-ilmalla, ja sinun pitää oleman niinkuin pilvi, joka maan peittää; sinä ja sinun joukkos, ja kansan paljous sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Näin sanoo Herra, Herra: siihen aikaan pitää sinun senkaltaisia aikoman sinun mielessäs, ja pitää pahoja juonia ajatteleman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Sinun pitää sanoman: minä tahdon hyökätä maakyliin, ja menen heidän päällensä, jotka surutoinna ja murheetoinna asuvat; nämät kaikki asuvat ilman muuria, joilla ei telkiä eikä porttia ole,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Ettäs kovin ryöstäisit ja julmasti raatelisit, ja antaisit kätes käydä hävitettyjä vastaan, jotka palaneet ovat, ja sitä kansaa vastaan, joka pakanoista koottu on, jotka karjaa kaitsevat ja kauppaa tekevät, ja asuvat keskellä maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Rikas Arabia, Dedan, ja meren kauppamiehet, ja kaikki voimalliset, jotka siellä ovat, pitää sinun sanoman: oletkos ollenkin tullut ryöstämään, ja koonnut joukkos perin raatelemaan, ottaakses pois hopian ja kullan ja kootakses karjaa ja tavaraa, ja suurta saalista saadakses?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Sentähden ennusta sinä, ihmisen poika, ja sano Gogille: näin sanoo Herra, Herra: etkös ymmärrä, koska minun kansani Israel asuu suruttomasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Niin sinä tulet silloin paikastas, pohjan ääristä, sinä ja paljo kansaa kanssas, kaikki hevosilla, suuri ja väkevä sotajoukko?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Ja sinun pitää menemän ylös minun kansaani Israelia vastaan, niinkuin pilvi, joka maan peittää. Viimeisellä ajalla pitää sinun oleman, mutta minä tahdon sentähden antaa sinun tulla minun maalleni, että pakanain pitää oppiman minua tuntemaan, koska minä sinussa, Gog, pyhitetyksi tulen heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Näin sanoo Herra, Herra: sinä olet se, josta minä olen muinen sanonut minun palvelijaini Israelin prophetain kautta, jotka siihen aikaan ennustivat, minun tahtovani antaa sinun tulla heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Ja sen pitää silloin tapahtuman, koska Gog tulee Israelin maata vastaan sanoo Herra, Herra, pitää minun vihani nouseman minun julmuudessani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Ja minä puhun näitä minun kiivaudessani, ja minun vihani tulessa: että silloin pitää suuren vavistuksen oleman Israelin maalla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Että minun kasvoini edessä pitää kalat meressä vapiseman, linnut taivaan alla, eläimet kedolla, ja kaikki, jotka matelevat ja liikkuvat maan päällä, ja kaikki ihmiset, jotka maan päällä ovat, ja vuoret pitää kukistettaman, ja seinät ja kaikki muurit maahan putooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Mutta minä kutsun miekan häntä vastaan kaikilla minun vuorillani, sanoo Herra, Herra; niin että jokaisen miekan pitää tuleman toinen toistansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Ja minä tuomitsen hänen rutolla ja verellä; ja annan sataa räntää ja raekiviä, tulta ja tulikiveä hänen ja hänen joukkonsa päälle, ja sen paljon kansan päälle, joka hänen kanssansa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Juuri niin pitää minun suureksi, pyhäksi ja tutuksi tuleman monien pakanain edessä, että heidän pitää ymmärtämän minun olevan Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Ja sinä, ihmisen poika, ennusta Gogia vastaan ja sano: näin sanoo Herra, Herra: katso, minä tulen sinun kimppuus, Gog, sinä joka olet Mesekin ja Tubalin ylimmäinen päämies;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Ja tahdon sinun palauttaa ja houkutella ulos *, ja noudan sinun pohjan ääristä, ja annan sinun tulla Israelin vuorille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Ja lyön joutsen pois sinun vasemmasta kädestäs ja heitän sinun nuoles oikiasta kädestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Israelin vuorilla pitää sinun kaatuman, kaiken sinun joukkos kanssa ja sen väen kanssa, joka sinun tykönäs on. Minä annan sinun linnuille, kusta ikänä he lentävät, ja eläimille ruaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Sinun pitää lankeeman kedolla; sillä minä Herra, Herra olen sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Ja minä heitän tulen Magogin päälle ja niiden päälle, jotka luodoissa surutoinna asuvat; ja heidän pitää ymmärtämän minun olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Ja minä tahdon tehdä minun pyhän nimeni tiettäväksi minun kansani Israelin seassa, ja en tahdo enään antaa minun pyhää nimeäni häväistä; vaan pakanain pitää ymmärtämän minun olevan Herran Israelin pyhän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Katso, jos se on parhaallansa tullut ja tapahtunut, sanoo Herra, Herra: se on se päivä, josta minä olen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Ja Israelin kaupunkien asuvaisten pitää lähtemän ulos, ja tekemän valkian, ja polttaman sota-aseet, kaikellaiset kilvet, nuolet, seipäät ja kanget; jotka kestävät palaa seitsemän ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Niin ettei tarvita hakea puita kedolta, eli pidä metsästä hakattaman; sillä he polttavat sota-aseita; ja pitää ryöstämän niitä, joilta he ovat ryöstetyt, ja raateleman niitä, joilta he olivat raadellut, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Ja sen pitää silloin tapahtuman, että minä annan Gogille paikan hautaamiseksi Israelissa, sen laakson, josta meren tykö itään päin mennään, niin että ne, jotka siitä menevät ohitse, pitää sieramensa tukitseman; ja heidän pitää Gogin joukkoinensa siihen hautaaman, ja se pitää kutsuttaman Gogin joukon laaksoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Mutta Israelin huoneen pitää heitä hautaaman, että maa sen kautta pitää puhdistettaman koko seitsemän kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Ja kaikella maakunnan kansalla pitää tekemistä oleman heidän hautaamisessansa, ja pitää saaman siitä kuuluisan nimen; että minä sinä päivänä kunnioitetuksi tulen, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Ja heidän pitää asettaman miehiä käymään joka päivä maata ympäri, ja heidän kanssansa kuolleiden hautain kaivajat, hautaaman jääneitä maan päällä, että se puhdistettaisiin; seitsemän kuukauden perästä pitää heidän rupeeman sitä tutkistelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Ja ne, jotka maata käyvät ympäri ja jossakussa paikassa ihmisen luut näkevät, heidän pitää siihen merkin paneman; siihenasti kuin haudankaivajat ne myös Gogin joukon laaksoon hautaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Kaupunki myös pitää siellä kutsuttaman Hamonaksi: niin pitää heidän maan perkaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Nyt sinä ihmisen poika, näin sanoo Herra, Herra: sano kaikille linnuille, kusta ikänä he lentävät, ja kaikille eläimille kedolla: kokoontukaat ja tulkaat tänne, tulkaat kokoon joka paikasta ympäriltä minun teurasuhrilleni, jonka minä teille teurastan suureksi teurasuhriksi Israelin vuorilla, ja syökäät lihaa, ja juokaat verta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Teidän pitää syömän väkeväin lihaa, ja juoman maan päämiesten verta; oinaisten, karitsain, kauristen, härkäin, jotka kaikki lihavat ja hyvin syötetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Ja teidän pitää syömän lihavuutta, niin että te ravituksi tulette, ja juoman verta, niin että te juovuksiin tulette, siitä teurasuhrista, jonka minä teille teurastan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Ravitkaat teitänne minun pöydälläni hevosista ja ratsastajista, väkevistä ja kaikkinaisesta sotaväestä, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Ja minä annan minun kunniani tulla pakanain sekaan, niin että kaikki pakanat pitää näkemän minun tuomioni, jonka minä olen tehnyt, ja minun käteni, jonka minä olen pannut heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Ja Israelin huoneen pitää ymmärtämän, että minä Herra olen heidän Jumalansa, siitä päivästä ja aina edemmä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Niin myös kaikkein pakanain pitää ymmärtämän Israelin huoneen pahain tekoinsa tähden viedyksi pois, sentähden että he minua vastaan rikkoneet ovat; ja minä peitin kasvoni heidän edestänsä, ja annoin heitä vihollistensa käsiin, niin että heidän kaikkein piti miekan kautta lankeeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Niinkuin heidän saastaisuutensa ja pahat tekonsa ansainneet olivat, tein minä heille, ja peitin minun kasvoni heidän edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Sentähden näin sanoo Herra, Herra: nyt minä tahdon pelastaa Jakobin vangit, ja armahtaa koko Israelin huonetta, ja kiivoitella minun pyhän nimeni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Mutta heidän pitää kantaman häväistyksensä ja rikoksensa, joilla he ovat rikkoneet minua vastaan, koska he surutoinna maallansa asuvat, niin ettei kenkään heitä peljätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Ja minä olen heidät kansoista jälleen kotia tuonut, ja koonnut heitä vihollistensa maalta, ja olen heissä pyhitetyksi tullut monien pakanain silmäin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Ja niin pitää heidän ymmärtämän, että minä Herra olen heidän Jumalansa, joka olen antanut viedä heitä pois pakanain sekaan, ja antanut taas koota heitä maallensa, ja en antanut yhtäkään heistä sinne jäädä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Ja en minä enään tahdo peittää minun kasvojani heidän edestänsä; sillä minä olen vuodattanut minun henkeni Israelin huoneen päälle, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Viidentenä vuotena kolmattakymmentä meidän vankiudestamme, vuoden alussa, kymmenentenä päivänä ensimmäisessä kuukaudessa, se on neljästoistakymmenes vuosi, sittekuin kaupunki hävitettiin, juuri sinä päivänä tuli Herran käsi minun päälleni, ja vei minun sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Ja Jumalan näyissä vei hän minut Israelin maalle ja asetti minun sangen korkialle vuorelle; ja siellä oli niinkuin rakennettu kaupunki etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Ja koska näyissä vei hän minut Israelin maalle ja asetti minun sangen korkialle vuorelle; ja siellä oli niinkuin rakennettu kaupunki etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Ja se mies sanoi minulle: sinä, ihmisen poika, katso silmilläs ja kuule korvillas, ja pane sydämees kaikki, mitä minä sinulle osoitan; sillä sentähden olen minä sinun tänne tuonut osoittaakseni sinulle, ettäs kaikki ne, mitkä sinä tässä näet, Israelin huoneelle ilmoittaisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Ja katso, muuri oli ulkonaisella puolella ympäri kaiken huoneen. Ja miehellä oli mittariuku kädessä, kuusi kyynärää ja kämmenen leveyden pitkä; ja hän mittasi rakennuksen leveydelle ja korkeudelle, kaikki yhdellä riuvulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Ja hän tuli portin tykö, joka oli itään päin, ja meni ylös hänen astuimistansa; ja mittasi portin kynnyksen, kummankin yhden riukumitan leveäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Ja kammiot, jotka olivat molemmilla puolilla porttia, mittasi hän myös yhden riukumitan leveäksi, ja kammioiden välin viisi kyynärää leveäksi, ja hän mittasi myös portin kynnyksen, esihuoneen portin tykönä sisimäisellä puolella, yhden riukumitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Ja mittasi portin esihuoneen sisimäisellä puolella yhden riukumitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Ja mittasi esihuoneen portin kahdeksan kyynärää ja sen kynnykset kaksi kyynärää, ja esihuoneen portin sisimmäisellä puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Ja kammioita oli kolme kummallakin puolella, portin tykönä itään päin, yksi niin avara kuin toinenkin. Ja molemmilla puolilla olivat kynnykset, jotka olivat yhdensuuruiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Sitte mittasi hän oven leveyden kymmenen kyynärää ja portin korkeuden kolmetoistakymmentä kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Ja kammioin edessä oli sia molemmilla puolilla, kyynärän leveydeltä; mutta kammiot olivat kuusi kyynärää molemmille puolille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Ja hän mittasi portin, yhden kammion katosta toiseen, viisikolmattakymmentä kyynärää leveydelle; ja ovet olivat suutasuuksin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Hän teki myös oven päälliset kuusikymmentä kyynärää ja esihuoneen oven päällisen yltäylitse porttia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Ja portin läpikäytävästä esihuoneen tykö sisimäiseen porttiin oli viisikymmentä kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Ja siinä olivat ahtaat akkunat kammioissa ja päällisissä, sisimäisellä puolella yltäylitse portin; juuri niin oli myös sisäpuolella kaikki ympäri, ja oven päällisessä olivat kauniit palmupuut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Ja hän vei minun vielä edemmäksi äärimäiseen kartanoon, ja katso, siellä olivat majat, ja permanto laskettu kartanon yli ympäri, ja kolmekymmentä kammiota permannolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Ja permanto oli molemmissa porteissa niin pitkä kuin portitkin olivat; ja tämä oli alimainen permanto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Ja hän mittasi alimaisesta portista leveyden sisimäiseen kartanoon asti ulkopuolelta, sata kyynärää itään ja pohjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Niin hän myös mittasi pohjaportin äärimäiseen kartanoon asti, pituudelle ja leveydelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Siinä oli myös jokaisella sivulla kolme kammiota; ja hänen oven päällisensä ja esihuoneensa olivat yhdensuuruiset, niinkuin entisenkin portin, viisikymmentä kyynärää pituudelle ja viisikolmattakymmentä kyynärää leveydelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Ja hänen akkunansa, esihuoneensa ja palmupuunsa olivat niinkuin itäisenkin portin, ja siinä oli myös seitsemän astuinta, joita myöten mentiin ylös, ja esihuone oli sen edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Ja sisimäisen esihuoneen portti oli pohjoisen ja itäisen portin kohdalla; ja hän mittasi sata kyynärää yhdestä portista niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Sitte vei hän minun myös etelään päin, ja katso, siellä oli myös yksi portti; ja hän mittasi hänen ovensa päälliset ja esihuoneensa niin suureksi kuin ne muutkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Siinä olivat myös akkunat ja esihuoneet yltympäri niinkuin muutkin akkunat, viisikymmentä kyynärää pitkät ja viisikolmattakymmentä kyynärää leveät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Ja siinä oli myös seitsemän astuinta ylöspäin, ja esihuone sen edessä; ja palmupuut joka sivulla sen oven päällisissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Ja hän mittasi myös sisimäisen kartanon portin etelään päin, sata kyynärää yhdestä eteläportista toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Ja hän vei minun eteläportin kautta sisimäiseen kartanoon, ja mittasi sen portin etelään päin, niin suureksi kuin muutkin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Ja hänen kammionsa, ja oviensa päälliset, ja esihuoneensa juuri sillä suuruudella ja hänen akkunansa ja esihuoneensa joka taholta, viisikymmentä kyynärää pituudelle ja viisikolmattakymmentä kyynärää leveydelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Ja siinä olivat esihuoneet ympärillä, viisikolmattakymmentä kyynärää pitkät ja viisi kyynärää leveät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Ja hänen esihuoneensa olivat äärimäisen kartanon edessä, ja palmupuut hänen ovensa päällisissä; ja siinä oli kahdeksan astuinta, joita myöten mentiin ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Sitte vei hän myös minun sisimäiseen porttiin itään päin ja mittasi sen portin niin suureksi kuin muutkin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Hänen kammioinsa, oviensa päälliset ja esihuoneensa, ja heidän akkunansa ja esihuoneensa entisen suuruiseksi ympärinsä, viisikymmentä kyynärää pitkäksi ja viisikolmattakymmentä kyynärää leveäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Ja hänellä oli myös esihuonee äärimäisen kartanon kohdalla, ja palmupuita oven päällisissä molemmilla sivuilla, ja kahdeksan astuinta ylöspäin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Sitte vei hän minun pohjan puoliseen porttiin; sen hän mittasi niin suureksi kuin ne muutkin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Hänen kammionsa, oviensa päällisten, esihuoneidensa ja heidän akkunainsa kanssa siinä ympärillä, viisikymmentä kyynärää pitkäksi ja viisikolmattakymmentä kyynärää leveäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Hänellä oli myös esihuone äärimäisen kartanon kohdalla, ja palmupuut ovenpäällisissä molemmilla puolilla, ja kahdeksan astuinta ylöspäin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Ja siellä oli kammio, ja sen ovi oli porttien pihtipielissä, kussa polttouhri pestiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Mutta esihuoneessa portin edessä oli jokaisella sivulla kaksi pöytää, joilla polttouhri, rikosuhri ja vikauhri piti teurastettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Ja ulkoisella puolella, kussa pohjaporttia päin mennään ylös, oli myös kaksi pöytää; ja toisella puolella, portin esihuoneen tykönä, oli myös kaksi pöytää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Niin oli jokaisella sivulla porttien edessä neljä pöytää, se on kahdeksan pöytää yhteen, joilla teurastettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Ja ne neljä pöytää olivat tehdyt polttouhria varten vuojonkivistä, puolitoista kyynärää pitkäksi ja puolitoista kyynärää korkeiksi: joille pantiin kaikkinaiset aseet, joilla myös polttouhri ja muut uhrit teurastettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Ja tottoin kivet olivat kämmenen korkiat joka taholta; ja niille pöydille piti pantaman uhriliha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Ja ulkoisella puolella sisällistä porttia olivat kammiot veisaajilla sisimäisessä kartanossa, yksi sivulla pohjan porttia päin, joka katsoi etelään, toinen portin sivulla itään päin, se katsoi pohjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Ja hän sanoi minulle: se kammio, joka on etelään päin, on pappein, joiden pitää huoneessa palveleman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Mutta se kammio pohjaan päin on niiden pappein, jotka alttarilla palvelevat; ne ovat Zadokin lapset, joiden pitää Levin lapsista astuman Herran eteen, häntä palvelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Ja hän mittasi esihuoneen sata kyynärää pitkäksi ja sata kyynärää leveäksi, nelikulmaiseksi; ja alttari oli juuri templin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Ja hän vei minun templin esihuoneesen ja mittasi esihuoneen oven päällisen, viisi kyynärää kummallekin puolelle, ja portin leveyden kolme kyynärää molemmin puolin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Mutta esihuone oli kaksikymmentä kyynärää pitkä ja yksitoistakymmentä kyynärää leveä, ja astuimet, joista mentiin ylös; ja patsaat olivat oven päällisten tykönä, yksi kummallakin puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Ja hän vei minun templin, ja mittasi patsaat seiniä myöten, ja ne olivat joka taholla kuusi kyynärää leveät, niin leveältä kuin huone oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Ja ovi oli kymmenen kyynärää leveä, mutta kukin seinä molemmin puolin ovea viisi kyynärää leveä. Ja hän mittasi sian templissä, se oli neljäkymmentä kyynärää pituudelle ja kaksi kymmentä kyynärää leveydelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Ja hän meni sisimäiselle puolelle, ja mittasi oven patsaat kaksi kyynärää, ja ovi oli kuusi kyynärää, ja oven leveys seitsemän kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Ja hän mittasi sen pituuden kaksikymmentä kyynärää ja leveyden kaksikymmentä kyynärää templissä, ja sanoi minulle: tämä on kaikkien pyhin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Ja hän mittasi huoneen seinän kuusi kyynärää: siellä olivat sivukammiot, neljä kyynärää leveät, joka paikassa ympäri huonetta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Ja sivulla kammiot kaikilla puolilla kolmeneljättäkymmentä toinen toisessansa kiinni; ja siinä olivat patsaat huoneen seinää myöten kaikki ympäri, jotka niitä kiinnittivät; ja ei kuitenkaan olleet huoneen seinässä kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Ja ylhäällä näiden päällä olivat vielä usiammat käytävät ympärinsä, ja ne ylimmäiset käytävät ympäri huoneen olivat leveämmät, niin että alimmaisesta mentiin keskimmäiseen ja keskimmäisestä ylimmäiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Ja minä näin huoneen korkeuden joka taholta, ja kammioin perustukset olevan täyttä mittaa kuusi kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Ja seinän leveys, joka oli kammion ulkoisella puolella, oli viisi kyynärää; ne muut olivat huoneen käytävät sisimäisellä puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Ja kammioiden välillä ympäri huoneen oli leveys kaksikymmentä kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Ja siellä oli kaksi ovea, eripaikan kohdalla, yksi pohjoista päin ja toinen etelää, ja eripaikka viisi kyynärää joka taholta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Ja rakennus länteen päin oli seitsemänkymmentä kyynärää leveä, ja seinä viisi kyynärää leveä ja yhdeksänkymmentä kyynärää pitkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Ja hän mittasi huoneen pituuden sata kyynärää, nimittäin, eripaikan, rakennuksen ja sen seinän pituus oli kaikkiansa sata kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Ja huoneen leveys edestä, sen eripaikan kanssa itään päin, oli myös sata kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Ja hän mittasi rakennuksen pituuden, eripaikan edestä, yhdestä päästä niin toiseen, joka haaralta sata kyynärää, sisällisen templin ja esihuoneen kartanon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Siinä olivat kynnykset ja ne ahtaat akkunat ja käytävät ympäri, niiden kolmen * edessä, olivat kaunistetut puuteolla yltympäri, aina maasta akkunoihin asti; itse akkunat myös olivat kaunistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Sitte oven päältä, niin aina kaikkein pyhimpään, ulkonaiselta ja sisimäiseltä puolelta yltympäri, aina mitalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Ja se oli tehty Kerubimeilla ja palmupuilla, niin että yksi palmupuu oli kunkin Kerubimin välillä, ja Kerubimilla oli kahdet kasvot:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Yhdellä puolella niinkuin ihmisen kasvot palmupuun kohdalla, ja toisella niinkuin nuoren jalopeuran kasvot palmupuun kohdalla: se oli niin tehty kaiken huoneen ympärille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Maasta ylimmäisen oven päälliseen asti olivat Kerubimit ja palmupuut tehdyt, niin myös templin seiniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Ja templin ovipielet olivat nelikulmaiset, ja kaikki pyhässä taitavasti toinen toiseensa sovitetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Ja puualttari kolme kyynärää korkia ja kaksi kyynärää pitkä, ja sen kulmat, leveys ja seinät olivat puusta. Ja hän sanoi minulle: tämän on pöytä, joka pitää Herran edessä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Ja oli myös kaksi ovea sekä templiin että kaikkein pyhimpään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Ja taas olivat kaksinkertaiset ovet, kaksi vähää ovea yhdessä ja kaksi toisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Ja templin oviin olivat tehdyt Kerubimit ja palmupuut, niinkuin seinissäkin; ja siinä oli paksu puu esihuoneen edessä ulkoisella puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Ja olivat ahtaat akkunat ja paljo palmupuita, kaikki ympäri esihuoneen; niin myös huoneen kammiot ja malat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Ja hän vei minun ulos äärimäiseen kartanoon, tielle pohjoista päin, ja vei minun siihen kammioon, joka oli eripaikan kohdalla, joka oli rakennuksen tykönä pohjoista päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Ja se paikka oli sata kyynärää pitkä siitä portista pohjoiseen päin, ja viisikymmentä kyynärää leveä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Niiden kahdenkymmenen kyynärän kohdalla sisimmäisessä kartanossa, ja permannon kohdalla äärimäisessä kartanossa, oli käytävä käytävää vastaan, aina kolmessa kerrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Ja kammioiden edessä oli käytävä kymmenen kyynärää leveä sisältä, ja tie yksi kyynärä; ja niiden ovet olivat pohjoista päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Ja ylimmäiset kammiot olivat ahtaammat muita; sillä käytäviin oli niistä otettu enempi kuin huoneen alimaisista ja keskimmäisistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Se oli kolmen huoneen korkeus, ja ei ollut niissä patsaita niinkuin kartanoin patsaat; sentähden ne olivat ahtaammat kuin alimaiset ja keskimäiset maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Ja ulkonainen muuri, joka oli kammioin tykönä, päin ulkoista kartanoa kammioiden edessä, oli viisikymmentä kyynärää pitkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Sillä kammiot, jotka olivat ulkoisella kartanolla, olivat viisikymmentä kyynärää pitkät; mutta katso, templin edusta oli sata kyynärää pitkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Ja alhaalla kammioiden edessä oli läpikäytävä itään päin, josta äärimmäisestä kartanosta mennään ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Ja esikartanon muurin avaruudessa idän puolella, eripaikan ja rakennuksen kohdalla, oli myös kammioita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Ja siinä oli myös eripaikka niiden edessä, niinkuin niidenkin kammioiden pohjoista päin, ja kaikilla oli yksi pituus ja leveys; ja kaikki heidän uloskäymisensä heidän muotonsa ja oviensa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Ja niiden kammioiden ovien muodon jälkeen, jotka etelään päin olivat, oli ovi tien suussa, joka oli sen jalon muurin edessä, josta itään päin kohdastansa mennään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Ja hän sanoi minulle: ne kammiot pohjoista päin, ja ne kammiot etelään päin eripaikan kohdalla ovat kaikkein pyhimmän sian kammiot, kussa papit pitää syömän, kuin he kaikkein pyhintä uhria Herralle uhraavat, ruokauhria, syntiuhria ja vikauhria; sillä se on pyhä sia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Ja kuin papit siihen sisälle menevät, niin ei heidän pidä jälleen tuleman pyhästä ulos äärimäiseen kartanoon, mutta pitää ennen riisuman vaatteensa, joissa he ovat palvelleet; sillä ne ovat pyhät. Ja heidän pitää ottaman toiset vaatteet yllensä, ja sitte menemän kansan sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Ja kuin hän kaiken huoneen oli sisältä mitannut, vei hän minun ulos porttiin itään päin, ja mittasi siitä kaiken ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Itään päin mittasi hän mittariuvulla viisisataa riukumittaa joka taholta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Pohjoista päin mittasi hän myös viisisataa riukumittaa mittariuvulla ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Niin myös lounaasen päin mittasi hän viisisataa riukumittaa sillä mittariuvulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Ja kuin hän tuli länteen päin, mittasi hän myös viisisataa riukumittaa sillä mittariuvulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Näin oli muuri, jonka hän mittasi, joka neljältä taholta viisisataa riukumittaa pituudelta ja viisisataa leveydeltä, kaikki ympäri; että pyhä piti oleman eroitettu pyhättömästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Ja hän johdatti minun porttiin, siihen porttiin, joka on itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Ja katso, Israelin Jumalan kunnia tuli itätietä, ja pauhasi, niinkuin suuri vesi pauhaa; ja maa kirkastui hänen kunniastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Ja tämä näky, jonka minä näin, oli senkaltainen kuin sekin näky, jonka minä näin, kuin minä tulin kaupunkia hävittämään *; ja nämät näyt olivat juuri niinkuin sekin näky, jonka minä näin Kebarin virran tykönä; ja minä lankesin maahan kasvoilleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Ja Herran kunnia tuli templiin itäisen portin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Ja henki otti minun ja vei sisälliseen esikartanoon; ja katso, huone oli täynnä Herran kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Ja minä kuulin puheen minun tyköni huoneesta, ja yksi mies seisoi minun tykönäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Joka sanoi minulle: sinä ihmisen poika, tämä on minun istuimeni paikka ja minun pöytäjalkaini sia, jossa minä tahdon asua Israelin lasten seassa ijankaikkisesti; ja ei Israelin huone pidä enään saastuttaman minun pyhää nimeäni, ei he itse eikä heidän kuninkaansa huoruudellansa, eli kuningastensa raatoin kautta kukkuloillansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Jotka asettivat kynnyksensä minun kynnykseni viereen ja ovensa minun oveni sivuun, ja seinä oli minun ja heidän vaiheellansa; ja he saastuttivat minun pyhän nimeni kauhistuksillansa, joita he tekivät, jonkatähden minä heitä vihassani hukutin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Mutta nyt heidän pitää huoruutensa kauvas hylkäämän, ja kuningastensa haudat minun tyköäni; niin minä asun heidän tykönänsä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Sinä, ihmisen poika, osoita Israelin huoneelle templi, että he häpeäisivät pahoja töitänsä, ja anna heidän mitata kaikki muoto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Ja kuin he kaikkia töitänsä häpeevät, niin osoita heille huoneen rakennuksen muoto, läpikäytävät, kuvat, kaikki menot, järjestykset ja oikeudet; ja kirjoita heidän eteensä, että he kaikki sen muodot ja kaikki sen säädyt pitäisivät ja tekisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Tämä on huoneen laki: vuorten kukkuloilla pitää kaikki sen rajat joka taholta pyhimmät oleman; katso, tämä on huoneen laki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Mutta tämä on alttarin mitta, sen kyynärän jälkeen, joka on kämmenen leveys pitempi yhteistä kyynärää: sen jalka oli kyynärää korkia ja kyynärää leveä, ja sen äärestä reunaan, ympäri yksi vaaksa; ja tämä on alttarin korkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Ja jalasta maan päältä eroitukseen oli kaksi kyynärää korkeutta ja kyynärä leveyttä; mutta vähemmästä eroituksesta enempää, neljä kyynärää korkeutta ja kyynärä leveyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Mutta Harel neljä kyynärää korkia, ja neljä sarvea ylhäällä Arielista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Ja Ariel oli kaksitoistakymmentä kyynärää pitkä ja kaksitoistakymmentä kyynärää leveä, nelikulmainen joka neljältä taholtansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Ja alttarin päällinen oli neljätoistakymmentä kyynärää pitkä ja neljätoistakymmentä kyynärää leveä, nelikulmainen joka neljätä taholta; ja reuna kävi ympäri, puoli kyynärää leviä, ja sen jalka kyynärää korkia, ja sen astuimet olivat itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Ja hän sanoi minulle: sinä ihmisen poika, näin sanoo Herra, Herra: nämät pitää oleman alttarin säädyt, kuin se tehdään, että uhrattaisiin siinä polttouhria, ja priiskotettaisiin verta sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Ja papeille, Leviläisille Zadokin suvusta, jotka minun edelläni käyvät, palvellen minua, sanoo Herra, Herra, pitää sinun antaman nuoren härjän syntiuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Ja sen verta pitää sinun ottaman ja priiskottaman sillä sen neljä sarvea ja neljä kulmaa reunan ympäri: sillä pitää sinun sen sovittaman ja pyhittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Ja pitää ottaman syntiuhrihärjän, ja polttaman sen huoneen eripaikassa, ulkona pyhästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Ja toisena päivänä pitää sinun uhraaman virheettömän kauriin syntiuhriksi; ja heidän pitää puhdistaman alttarin niinkuin härjälläkin puhdistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Kuin se on tapahtunut, niin sinun pitää uhraaman nuoren virheettömän mullin ja virheettömän oinaan laumasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Ja uhraa ne molemmat Herran edessä; ja heittäkään papit siihen suolaa, ja uhratkaan ne Herran polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Näin sinun pitää seitsemän päivää uhraaman, kauriin joka päivä syntiuhriksi: mullin ja oinaan laumasta, jotka molemmat virheettömät olemaan pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Ja näin heidän pitää alttarin sovittaman seitsemän päivää, ja puhdistaman sen, täyttämän kätensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Ja niiden seitsemän päivän perästä pitää papit, kahdeksantena päivänä ja sitte aina, uhraaman alttarille teidän polttouhrinne ja kiitosuhrinne; niin minä tahdon teille olla armollinen, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Ja hän vei minun jälleen pyhän äärimäisen portin tietä itään päin; mutta se oli kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Ja Herra sanoi minulle: tämä portti pitää oleman kiinni, ja ei pidä avattaman, eikä yksikään pidä siitä käymän; sillä Herra Israelin Jumala on siitä käynyt; ja pitää vielä sitte oleman kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Päämiehen se oleman pitää, päämiehen pitää siinä istuman ja syömän leipää Herran edessä; esihuoneesta pitää hänen menemän sisälle, ja ja siitä jälleen tuleman ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Siitä vei hän minun pohjoisen portin tietä esihuoneen kohdalle; ja minä näin, ja katso, Herran huone oli täynnä Herran kunniaa. Ja minä lankesin kasvoilleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Ja Herra sanoi minulle: sinä, ihmisen poika, pane sydämees, ja katso silmilläs, ja kuule korvillas kaikkia, mitä minä sinulle sanon kaikista Herran huoneen säädyistä ja asetuksista, ja ota vaari, kuinka (ihmisen) itsensä pyhässä käyttäytymän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Ja sano kovakorvaiselle Israelin huoneelle: näin sanoo Herra, Herra: te Israelin huone, olette tähänasti kaikilla teidän kauhistuksillanne kyllä tehneet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Että te annatte muukalaisia, joilla on ympärileikkaamatoin liha, tulla minun pyhääni, jolla te minun huoneeni saastutatte, uhratessanne minun leipääni, lihavuutta ja verta, ja näin rikotte kaikki minun liittoni kaikilla teidän kauhistuksillanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Ja ette pidä minun pyhäni tapoja, mutta olette tehneet itsellenne uuden tavan minun pyhästäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Sentähden sanoo Herra, Herra näin: ei yhdenkään vieraan, jolla on ympärileikkaamatoin sydän ja ympärileikkaamatoin liha, pidä tuleman minun pyhääni, kaikista muukalaisista, jotka Israelin lasten seassa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Ja ei myös ne Leviläiset, jotka minusta luopuneet, ja Israelin kanssa epäjumalainsa jälkeen erhetykseen menneet ovat; sentähden pitää heidän kantaman omat syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Mutta heidän pitää vartioitseman minun pyhäni ovea, ja oleman huoneen palveliat, ja teurastaman polttouhria ja muita uhreja kansan edestä, ja seisoman heidän edessänsä, palvellen heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Että he ovat palvelleet heitä heidän epäjumalansa edessä, ja ovat antaneet Israelin huoneelle pahennuksen; sentähden olen minä ojentanut käteni heidän päällensä, sanoo Herra, Herra, että heidän pitää kantaman heidän syntinsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Ja ei pidä uhraaman minun edessäni, eikä oleman minun pappini, ei myös minun pyhääni tuleman, kaikkein pyhimpään; mutta pitää kantaman häpynsä ja kauhistuksensa, joita he tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Sentähden olen minä tehnyt heitä huoneen oven vartiaksi kaikessa sen palveluksessa, ja kaikissa, mitä siinä tehdään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Mutta papit ja Leviläiset Zadokin pojat, jotka minun pyhäni säädyt pitäneet ovat, kuin Israelin lapset luopuivat minusta, ne pitää minun edelläni käymän, palvellen minua, ja minun edessäni seisoman, ja uhraaman minulle lihavuutta ja verta, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Ja heidän pitää menemän minun pyhääni, ja tuleman minun pöytäni eteen, palvellen minua ja pitäin minun säätyni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Ja kuin he tahtovat mennä portista sisälliseen kartanoon, niin heidän pitää pukeman yllensä liinavaatteet, ja ei villoista tehtyjä, niin kauvan kuin he sisällisessä kartanossa palvelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Ja liinahiipat pitää oleman heidän päässänsä ja liinaiset vaatteet heidän kupeillansa, ja ei pidä sitoman itsiänsä hikiliinoilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Ja kuin he menevät ulkoiseen ja äärimäiseen kartanoon kansan tykö, niin heidän pitää paneman ne vaatteet pois, joissa he palveluksen tehneet ovat, ja kätkemän ne pyhiin kammioihin; ja heidän pitää ottaman toiset vaatteet yllensä, ettei he kansaa pyhittäisi omissa vaatteissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Ei heidän pidä ajeleman päätänsä, eikä pitkiä hiuksia kasvattaman; mutta pitää antaman hiuksensa tasaisesti leikata ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Ei myös yksikään pappi pidä viinaa juoman, kuin hänen sisimäiseen kartanoon sisälle menemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Ei myös pidä ottaman yhtään leskeä eli hyljättyä avioksensa, mutta neitseen Israelin suvusta, eli ottakaan papin lesken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Ja opettakaan minun kansaani tietämään eroituksen pyhän ja pyhättömän välillä, että he puhtaan ja saastaisen välillä eroituksen tietäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Ja kuin riita tulee heidän eteensä, niin heidän pitää seisoman ja tuomitseman ja puhuman minun lakini ja säätyni jälkeen, ja pitämän minun käskyni, ja kaikki minun pyhäpäiväni ja sabbatini pyhittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Ja ei pidä menemän yhdenkään kuolleen ihmisen tykö saastuttamaan itsiänsä; vaan ainoasti isänsä ja äitinsä, poikansa ja tyttärensä, veljensä ja sisarensa, jolla ei miestä ole ollut, niiden tähden joku saa itsensä saastuttaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Mutta että he puhdistavat itsensä jälleen seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Ja kuin hän jälleen menee pyhään, sisimäiseen kartanoon, palvelemaan pyhässä, niin pitää hänen uhraaman syntiuhrinsa, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Ja se on heille perinnöksi; minä tahdon olla heidän perintönsä; sentähden ei teidän pidä heille perimistä antaman Israelissa; sillä minä olen heidän perintönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Heidän pitää saaman elatuksensa ruokauhrista, syntiuhrista ja vikauhrista; ja kaikki kirotut Israelissa pitää heidän oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Ja kaikki ensimmäinen hedelmä ja esikoiset kaikista teidän ylennysuhreistanne pitää pappein oleman. Teidän pitää myös antaman papeille esikoiset teidän taikinastanne, että siunaus olis sinun huoneessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Mutta joka kuollut on eli metsän pedolta haaskattu, linnusta eli eläimestä, sitä ei pidä pappein syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Kuin te maata jaatte arvalla, niin teidän pitää eroittman osan maasta Herralle pyhäksi, viisikolmattakymmentä tuhatta riukumittaa pituudelle ja kymmenentuhatta leveydelle: se paikka on pyhä kaikissa rajoissansa ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Ja tästä pitää oleman pyhään viisisataa riukumittaa, nelikulmainen ympärinsä, ja esikaupungiksi viisikymmentä kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Ja sillä paikalla, joka on viisikolmattakymmentä tuhatta riukua pitkä ja kymmenentuhatta leveä, pitää pyhän oleman, ja kaikkein pyhimmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Se pitää maasta pyhä oleman, ja pitää pappein oleman, jotka pyhässä palvelevat, ja Herran eteen tulevat palvelemaan häntä, että heillä pitää oleman sia huoneelle, se pitää myös pyhä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Mutta Leviläisten, jotka huoneessa palvelevat, pitää myös saaman viisikolmattakymmentä tuhatta riukua pituudelle ja kymmenentuhatta leveydelle heidän osaksensa, kahdellekymmenelle kammiolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Ja kaupungin omaisuudeksi pitää teidän yhden paikan jättämän, viisituhatta riukua leveydelle ja viisikolmattakymmentä tuhatta riukua pituudelle, sen maan sivusta, joka pyhää ylennysuhria varten eroitettu on: se pitää kaikelle Israelin huoneelle oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Päämiehelle pitää teidän myös antaman yhden paikan, molemmille puolille pyhän ylennysuhrin osaa ja kaupungin omaisuutta, juuri pyhän ylennysuhrin osan ja kaupungin omaisuuden eteen läntisestä kulmasta niin länteen ja itäisestä kulmasta itään päin; sen pituus pitää vastaaman yhtä niistä muista osista, länsirajasta niin itärajaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Se pitää oleman hänen oma osansa Israelissa; ettei minun päämieheni pidä enempi ottaman minun kansaltani, joka heidän on, vaan pitää antaman maan Israelin huoneelle heidän sukukunnissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Sillä näin sanoo Herra, Herra: eikö siinä kyllä ole, te Israelin päämiehet? lakatkaat kaikesta vääryydestä ja väkivallasta, ja tehkäät oikeus ja vanhurskaus; ja älkäät enempää rasittako minun kansaani, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Teidän pitää pitämän oikian puntarin, ja oikian vaa ́an, ja oikian mitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Epha ja bat pitää kaikki yhtä oleman, niin että bat pitää kymmenen osan homeria, ja epha kymmenen osan homeria; sillä homerilla pitää ne molemmat mitattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Mutta siklin pitää pitämän kaksikymmentä geraa; ja kaksikymmentä sikliä, viisikolmattakymmentä sikliä ja viisitoistakymmentä sikliä tekevät minan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Tämä on ylennysuhri, jonka teidän antaman pitää: kuudes osa ephaa ja homeria nisuja, ja kuudes osa ephaa ja homeria ohria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Mutta öljyä, joka batilla mitataan, pitää teidän antaman batin, joka on kymmenes osa koria, eli kymmenennes homeria; sillä kymmenen batia tekevät homerin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Ja yksi uuhinen karitsa kahdestasadasta lampaasta, Israelin lammaslaitumelta, ruokauhriksi, polttouhriksi, kiitosuhriksi, sovinnoksi heidän edestänsä, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Kaikki maan kansa pitää tuoman ylennysuhrin Israelin päämiehelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Ja päämiehen pitää uhraaman polttouhrinsa, ruokauhrinsa, ja juomauhrinsa juhlapäivänä, uudella kuulla ja sabbatina, ja kaikkina Israelin huoneen suurina juhlapäivinä; hänen pitää myös tekemän syntiuhrin ja ruokauhrin, polttouhrin ja kiitosuhrin, sovinnoksi Israelin huoneen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Näin sanoo Herra, Herra: ensimäisenä päivänä ensimäistä kuuta pitää sinun ottaman virheettömän mullin, ja puhdistaman pyhän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Ja pappi ottakaan syntiuhrin verestä, ja priiskottakaan sillä huoneen pihtipielet ja neljä alttairn kulmaa, niin myös sisimäisen kartanon portin pihtipielet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Ja näin sinun pitää tekemän seitsemäntenä päivänä kuuta, jos joku tietämättä erehtynyt on, että te huoneen pyhittäisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Neljäntenätoistakymmenentenä päivänä ensimäistä kuuta pitää teidän pääsiäistä pitämän, ja pitämän pyhää seitsemän päivää, ja syömän happamatointa leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Sinä päivänä pitää päämiehen uhraaman itse edestänsä ja kaiken maan kansan edestä mullin syntiuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Mutta niinä seitsemänä päivänä, juhlina, pitää hänen joka päivä tekemän Herralle polttouhria, seitsemän mullia ja seitsemän oinasta, jotka virheettömät ovat, ja kauriin joka päivä syntiuhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Mutta ruokauhriksi pitää hänen uhraaman ephan mullille ja ephan oinaalle, ja hinnin öljyä ephalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Viidentenätoistakymmenentenä päivänä seitsemättä kuukautta pitää hänen pyhänä pitämän seitsemän päivää järjestänsä, niinkuin ne muutkin seitsemän päivää; ja sillä tavalla pitämän syntiuhrin kanssa, polttouhrin, ruokauhrin ja myös öljyn kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Näin sanoo Herra, Herra: sisimäisen kartanon portti, joka itään päin on, pitää kuutena arkipäivänä oleman kiinni, mutta sabbatina ja uudella kuulla avattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Ja päämiehen pitää menemän ulkoiselle puolelle huoneen porttia ja seisahtaman portin kynnykselle; ja pappein pitää uhraaman hänen polttouhrinsa ja kiitosuhrinsa, mutta hänen pitää rukoileman portin kynnyksellä, ja sitte jälleen menemän ulos; mutta portin pitää ehtoosen asti avoinna oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Maan kansan pitää myös rukoileman Herran edessä, sen portin ovessa, sabbatina ja uudella kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Mutta polttouhriksi, jonka päämiehen Herralle uhraaman pitää sabbatina, pitää oleman kuusi virheetöintä karitsaa ja virheettömän oinaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Ja ephan sämpyläjauhoja oinaan kanssa ruokauhriksi, ja karitsain kanssa ruokauhriksi, mitä kukin voi, ja hinnin öljyä ephaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Mutta uudella kuulla pitää uhrattaman nuori virheetöin härkä, ja kuusi karitsaa, ja virheetöin oinas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Ja epha härjän kanssa, ja epha oinaan kanssa ruokauhriksi; mutta karitsan kanssa niin paljo kuin hän käteensä saa, ja hinni öljyä ephaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Ja kuin päämies sinne menee, niin hänen pitää menemän portin esihuoneen kautta, ja siitä tuleman ulos jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Mutta maan kansa, jotka Herran eteen tulevat suurina juhlapäivinä, ja käyvät pohjoisen portin kautta rukoilemaan, ne pitää jälleen tuleman ulos eteläportista; ja jotka eteläportista tulevat, ne pitää käymän ulos pohjoisesta portista. Ja ei pidä tuleman ulos jälleen siitä portista, josta he ovat menneet sisälle, mutta kohdastansa toiselta puolelta menemän ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Päämiehen pitää ulos ja sisälle heidän kanssansa käymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Ja pyhäpäivinä ja juhlapäivinä pitää uhrattaman ruokauhriksi mullin kanssa epha, ja oinaan kanssa epha, ja karitsan kanssa niin paljon kuin hän saa käteensä, ja hinni öljyä ephan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Mutta kuin päämies tahtoo tehdä vapaaehtoisen polttouhrin eli kiitosuhrin Herralle, niin hänelle pitää avattaman itäportti, että hän saa uhrata polttouhrinsa ja kiitosuhrinsa, niinkuin hän sen sabbatinakin uhraa; ja koska hän jälleen tulee ulos, niin pitää portti pantaman kiinni hänen jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Ja sinun pitää tekemän Herralle joka päivä polttouhria, vuotisen virheettömän karitsan; sen pitää sinun uhraaman joka aamulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Ja joka aamulla paneman siihen päälle kuudennen osan ephaa ruokauhriksi, ja kolmannen osan hinniä öljyä, sekoitettu sämpyläjauhoihin: se pitää oleman jokapäiväinen ruokauhrin sääty Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Ja näin pitää heidän aina uhraaman karitsan ruokauhrin ja öljyn kanssa joka aamu alinomaiseksi polttouhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Näin sanoo Herra, Herra: kuin päämies antaa yhdelle pojistansa lahjan hänen perinnöstänsä, sen pitää oleman hänen poikansa oma perintö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Mutta jos hän antaa lahjan yhdelle palvelijoistansa hänen perinnöstänsä, niin se pitää sen oma oleman vapaavuoteen saakka, ja niin pitää se jälleen päämiehelle tuleman; sillä hänen osansa pitää ainoasti hänen poikansa perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Ja ei päämiehen pidä mitään ottaman kansan perinnöstä, eli ajaman heitä pois heidän omastansa; mutta pitää antaman lapsille heidän perintönsä, ettei minun kansani tulisi hajoitetuksi pois omaisuudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Ja hän vei minun läpikäytävän sivulle pohjan porttia päin, pyhän kammioihin, jotka pappein olivat; ja katso, siellä oli yksi sia kahdessa kulmassa länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Ja hän sanoi minulle: tämä on se sia, jossa papit vikauhrin ja syntiuhrin keittämän pitää, ja leipoman ruokauhrin, ettei heidän tarvitse niitä ulkonaiselle kartanolle kantaa, pyhittämään kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Ja hän vei minun ulos ulkonaiseen kartanoon, ja johdatti minun neljään kartanon kulmiin; ja katso, siellä oli esihuone kussakin kulmassa toinen toisensa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Jokaisessa neljässä kartanon kulmassa olivat esihuoneet toinen toisensa kanssa, neljäkymmentä kyynärää pitkät ja kolmekymmentä kyynärää leveät, eroitetut vähiin paikkoihin, niin leviä yksi kuin toinenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Ja siellä kävi yksi vähä muuri ympäri kaikkia niitä neljää; ja siellä olivat totot tehdyt alhaalla ympäri muurin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Ja hän sanoi minulle: nämät ovat keittosiat, joissa palveliat, jotka huoneessa palvelusta tekevät, keittämän pitää kansan uhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Ja hän vei minun jälleen templin oven eteen, ja katso, siellä juoksi vesi templin kynnyksen alitse itään päin; sillä templin ovi oli itään päin; ja vesi juoksi templin oikialta puolelta lounaaseen päin, alttarin ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Ja hän vei minun ulos pohjoista porttia päin, ja vei minun ympäri sitä tietä ulkoisesta portista itään päin; ja katso, vesi juoksi oikialta puolelta sieltä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Ja mies läksi itään päin, ja mittanuora oli hänen kädessänsä, ja mittasi tuhannen kyynärää, ja hän vei minun veteen minun pöytäjalkoihini saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Ja mittasi vielä tuhannes kyynärää, ja vei minun veteen polviini saakka; ja mittasi jälleen tuhannen kyynärää ja antoi minun mennä siihen kupeisiin saakka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Niin hän mittasi vielä tuhannen, että niin syvä tuli, etten minä enään pohjaan ulottunut; sillä vesi oli niin syvä, että siinä täytyi uida, ja ei ulottunut pohjaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Ja hän sanoi minulle: sinä ihmisen poika, tämän olet sinä kyllä nähnyt; ja hän vei minun jälleen ojan reunalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Ja kuin minä itseni käänsin, katso, siellä oli sangen monta puuta rannalla molemmilla puolilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Ja hän sanoi minulle: tämä vesi, joka itään päin juoksee, pitää juokseman paljaan maan lävitse mereen; ja kuin se tulee mereen, niin sen vedet terveellisiksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Ja kaikki, jotka siinä elävät ja liikkuvat, kuhunka nämät virrat tulevat, niiden pitää elämän; ja pitää oleman sangen paljo kaloja; ja kaikki pitää terveet oleman ja elämän, kuhunka tämä virta tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Siinä pitää oleman kalamiehet; Engeddistä niin Eneglaimiin asti pitää verkkoja pantaman; sillä siinä pitää oleman lajinsa jälkeen sangen paljo kaloja, niinkuin suuressakin meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Mutta järvet ja suovedet ei pidä oleman terveelliset, mutta suolaiseksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Ja molemmin puolin ojan rantoja pitää kasvaman kaikkinaisia hedelmällisiä puita, joiden lehdet ei pidä variseman, eikä hedelmät mätänemän; ja heidän pitää joka kuu kantaman uuden hedelmän; sillä heidän vetensä vuotaa pyhästä, heidän hedelmänsä kelpaavat ruoaksi, ja heidän lähteensä lääkitykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Näin sanoo Herra, Herra: nämät ovat rajat, joiden jälkeen teidän pitää kahdelletoistakymmenelle Israelin sukukunnalle maan jakaman; mutta kaksi osaa tulee Josephin suvulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Ja teidän pitää sen yhtäläisesti jakaman, niin yhdelle kuin toisellekin; sillä minä olen vannonut sen antaakseni teidän isillenne, ja tämä maa pitää tuleman teille perinnöksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Tämä on maan raja: pohjaan päin, isosta merestä, Hetlonin tietä niin aina Zedadiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hematiin, Berotoon, Sibraimiin, jotka Damaskun ja Hematin rajain välillä ovat, ja HatsarTikoniin, joka Havran rajaan ulottuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Ja raja merestä niin Hatsar-Enoniin on Damaskun raja, ja Zaphon pohjaan päin Hamatin raja: ja se on pohjan puoleinen kulma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Mutta rajan itään päin pitää teidän mittaaman Havran ja Damaskun väliltä ja Gileadin väliltä, ja koko Israelin väliltä, Jordanin tykönä, rajasta itämereen saakka; se pitää oleman raja itään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Mutta raja lounaaseen päin on Tamarista aina Kadekssen riitaveteen saakka, ja virtaan asti suuren meren tykönä; sen pitää oleman rajan lounaasen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Ja raja länteen päin on isosta merestä, rajasta kohdastansa aina Hamatiin; se on raja länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Ja näin teidän pitää jakaman maan teillenne Israelin sukukunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Ja kuin te arvan heitätte maata jakaissanne teidän välillänne, niin teidän pitää muukalaisia pitämän, jotka asuvat teitä läsnä, ja elävät eli siittävät lapsia teidän seassanne, niinkuin he olisivat Israelin lasten seassa syntyneet lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Ja muukalaisten pitää saaman osansa maasta, kukin sen suvun seassa, jota läsnä hän asuu, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Nämät ovat sukukuntain nimet: pohjoisesta Hetlonin tien vierestä, siihenasti kuin tullaan Hamatiin, HatsarEnoniin, Damaskun rajaan pohjaan päin, Hamatin sivulle; sen pitää Danin pitämän osaksensa, itään ja länteen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Likin Danin rajaa pitää Asserin osa oleman, idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Likin Asseria pitää Naphtalin osa oleman, idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Likin Naphtalin rajaa pitää Manassen osa oleman, idän puolesta länteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Likin Manassen rajaa pitää Ephraim osansa saaman, idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Likin Ephraimin rajaa pitää Rubenin osa oleman, idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Likin Rubenin rajaa pitää Juudan osan oleman, idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Mutta likin Juudan rajaa pitää teidän eroittaman yhden osan idästä niin länteen, joka on viisikolmattakymmentä tuhatta riukua pitkä ja leveä, niinkuin muu osa on idästä niin länteen: siinä pitää pyhän oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Ja siitä pitää teidän eroittaman uhriksi Herralle osan, viisikolmattakymmentä tuhatta riukua pitkän ja kymmenentuhatta riukua leveän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Ja sen pyhän osan pitää pappein oleman, viisikolmattakymmentä tuhatta riukua pitkä, pohjoiseen ja etelään päin, ja kymmenentuhatta leveä, itään ja länteen päin. Ja Herran pyhän pitää siinä keskellä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Se pitää papeille pyhitetty oleman Zadokin lapsista, jotka minun säätyni pitäneet ovat, ja ei ole Israelin lasten kanssa luopuneet, niinkuin Leviläiset luopuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Ja sentähden pitää heillä oleman oma osa eroitetusta maasta, se kaikkein pyhin, joka on Leviläisten rajan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Mutta Leviläisillä pitää myös osa oleman, viisikolmattakymmentä tuhatta leveä, pappein rajan tykönä; sillä kaikki pituus pitää oleman viisikolmattakymmentä tuhatta riukua ja leveys kymmenentuhatta riukua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Ja ei pidä siitä mitään myytämän pois eikä vaihetettaman, ei myös maan uutisesta pidä mitään tuleman pois; sillä se on pyhitetty Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Mutta ne viisituhatta riukua, jotka jäävät leveydelle, viidestäkolmattakymmenestä tuhannesta riukumitasta pituudelle, pitää oleman kaupungille yhteiseksi asuinsijaksi ja esikaupungiksi; ja sen keskellä pitää kaupungin oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Ja tämän pitää oleman hänen mittansa: neljätuhatta ja viisisataa riukua pohjoiseen ja lounaaseen päin, niin myös itään ja länteen päin neljätuhatta ja viisisataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Mutta esikaupunkia varten pitää oleman kaksisataa ja viisikymmentä riukua, pohjaan ja lounaan päin, niin myös itään ja länteen kaksisataa ja viisikymmentä riukua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Mutta mitä jää pituudesta pyhän ylennysuhrin osan kohdalle, kymmenentuhatta riukua itään päin ja kymmenentuhatta riukua länteen päin, juuri pyhän ylennysuhrin osan kohdalla, sen sisälletulo pitää oleman kaupungin palvelioille elatukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Ja jotka kaupungissa palvelevat, ne pitää oleman kaikista Israelin sukukunnista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Ja kaikista näistä eroitetuista osista, joka on molemmilta puolilta pituudelle ja leveydelle viisikolmattakymmentä tuhatta riukua, pitää teidän eroittaman neljännen osan; sen pitää kaupungin oman oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Mutta mitä vielä jää molemmille puolille siitä eroitetusta pyhästä osasta ja kaupungin osasta, viisikolmattakymmentä tuhatta riukua sekä itään että länteen, se pitää päämiehen oma oleman; mutta pyhä maa, jossa pyhä huone on, pitää siitä eroitettu oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Mutta mitä on Leviläisten osan ja kaupungin osan välillä, joka keskellä on, mitä jää Juudan ja Benjaminin rajan välille, se pitää päämiehen oma oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Sitte pitää muut sukukunnat oleman: Benjaminin osa idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Mutta Benjaminin rajan tykönä pitää Simeonin osa oleman idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Simeoinin rajan vieressä pitää Isaskarin osan oleman, idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Isaskarin rajalla pitää Zebulonin osan oleman, idän puolesta länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Zebulonin rajalla pitää Gadin osan oleman, idästä länteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Mutta likin Gadia on lounaan raja, Temanin, Tamarista niin Kadeksen riitaveteen saakka, niin ojaan asti, joka isoon mereen juoksee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Näin pitää maa jaettu oleman Israelin lasten sukukuntain perinnöksi; ja sen pitää oleman heidän osansa, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Ja näin leveltä pitää kaupungin oleman; neljätuhatta ja viisisataa riukua pohjoista päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Ja kaupungin portit pitää Israelin sukukuntain nimeltä nimitetyt oleman: kolme porttia pohjoista päin: ensimäinen Rubenin, toinen Juudan, kolmas Levin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Niin myös itään päin neljätuhatta ja viisisataa riukua, ja kolme porttia: ensimäinen Josephin, toinen Benjaminin, kolmas Danin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Etelään päin myös neljätuhatta ja viisisataa riukua, ja kolme porttia: ensimäinen Simeonin, toinen Isaskarin, kolmas Zebulonin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Niin myös länteen päin neljätuhatta ja viisisataa riukua, ja kolme porttia: ensimmäinen portti Gadin, toinen Asserin, kolmas Naphtalin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Näin pitää tämä kaikki ympäri oleman, kahdeksantoistakymmentä tuhatta riukua: ja niin pitää kaupunki tästä päivästä kutsuttaman: tässä on Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Kolmantena Jojakimin, Juudan kuninkaan, valtakunnan vuotena tuli Nebukadnetsar, Babelin kuningas Jerusalemin eteen, ja piiritti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Ja Herra antoi Jojakimin, Juudan kuninkaan hänen käsiinsä, ja muutamia astioita Jumalan huoneesta; ne antoi hän viedä Sinearin maalle, jumalansa huoneesen, ja pani ne astiat jumalansa tavarahuoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Ja kuningas sanoi Aspenaalle, ylimmäiselle kamaripalveliallensa, että hänen piti Israelin lapsista kuninkaallisesta suvusta ja berrain lapsista valitseman');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Virheettömiä poikia, kauniita, toimellisia, viisaita, ymmärtäväisiä, taitavia, jotka soveliaat olisivat palvelemaan kuninkaan huoneessa, ja piti opettaman heille Kaldean kirjoituksia ja kieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Niille toimitti kuningas, mitä heille joka päivä annettaman piti kuninkaan ruasta ja sitä viinaa, jota hän itse joi; että he niin kolme vuotta kasvatettaman ja sitte kuninkaan edessä palveleman piti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Joiden seassa olivat Juudan lapsista: Daniel, Hanania, Misael ja Asaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Ja ylimmäinen kamaripalvelia antoi heille nimet, ja nimitti Danielin Belsatsariksi ja Hananian Sadrakiksi, ja Misaelin Mesakiksi, ja Asarian Abednegoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Mutta Daniel aikoi sydämessänsä, ettei hän kuninkaan rualla eikä sillä viinalla, jota hän itse joi, itseänsä saastuttaisi; ja rukoili ylimmäistä kamaripalveliaa, ettei hän itseänsä saastuttaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Ja Jumala antoi Danielille, että ylimmäinen kamaripalvelia oli hänelle ystävällinen ja armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Ja ylimmäinen kamaripalvelia sanoi Danielille: minä pelkään minun herraani, kuningasta, joka teille teidän ruokanne ja juomanne toimittanut on; jos hän näkis teidän kasvonne laihemmiksi kuin muiden teidän ikäistenne, niin te minun sitte saatte kuninkaan tykönä pois hengeltäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Niin sanoi Daniel Meltsarille. jolle ylimmäinen kamaripalvelia Danielista, Hananiasta, Misaelista ja Asariasta käskyn antanut oli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Koettele palvelioitas kymmenen päivää, ja annettakaan meille puuroa syödäksemme ja vettä juodaksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Ja anna niin meidän muotomme ja niiden poikain muoto, jotka kuninkaan ruasta syövät, katsottaa; ja niinkuin sinä sitte näet, tee niin palvelioilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Ja hän totteli heitä siinä, ja koetteli heitä kymmenen päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Ja kymmenen päivän perästä olivat he kauniimmat ja lihavammat ruumiilta kuin kaikki nuorukaiset, jotka kuninkaan ruasta söivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Niin pani Meltsari pois heidän määrätyn ruokansa ja viinajuomansa, ja antoi heille puuroa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Vaan näille neljälle nuorukaiselle antoi Jumala taidon ja ymmärryksen kaikkinaisissa kirjoituksissa ja viisaudessa; ja Danielille antoi hän ymmärryksen kaikkinaisissa näyissä ja unissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Ja kuin se aika kulunut oli, jonka kuningas määrännyt oli, että he piti tuotaman edes, vei heidät ylimmäinen kamaripalvelia Nebukadnetsarin eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Ja kuningas puhui heidän kanssansa, ja ei kaikkein seassa yhtäkään löydetty, joka Danielin, Hananian, Misaelin ja Asarian kaltainen oli; ja he tulivat kuninkaan palvelioiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Ja kuningas löysi heidät, kuin hän heitä tutkisteli kaikissa asioissa, kymmenen kertaa toimellisemmiksi ja ymmärtäväisemmiksi kuin kaikki tähtientutkiat ja viisaat koko valtakunnassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Ja Daniel oli siellä hamaan ensimäiseen Koreksen vuoteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Toisena Nebukadnetsarin valtakunnan vuotena näki Nebukadnetsar unta, josta hän hämmästyi, niin että hän heräsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Ja kuningas käski tähtientutkiat ja viisaat ja noidat ja Kaldealaiset kutsuttaa kokoon, sanomaan kuninkaalle hänen untansa. Ja he tulivat ja astuivat kuninkaan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Ja kuningas sanoi heille: minä näin unta, josta minä peljästyin, ja minä mielelläni tahtoisin tietää, mikä se uni oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Niin sanoivat Kaldealaiset kuninkaalle Syrian kielellä: kuningas eläköön kauvan! sano palvelioilles uni, niin me tahdomme selittää sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Kuningas vastasi ja sanoi Kaldealaisille: minä olen unhottanut; jollette minulle ilmoita unta ja selitä sitä, niin te pitää kappaleiksi hakattaman, ja teidän huoneenne lokaläjäksi kukistettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Vaan jos te minun tietää annatte unen ja selityksen, niin teidän pitää saaman lahjoja, antimia ja suuren kunnian minulta: sentähden sanokaat minulle uni ja sen selitys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'He vastasivat jälleen ja sanoivat: kuningas sanokaan palvelioillensa unen, me tahdomme sen selittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Kuningas vastasi ja sanoi: totisesti minä ymmärrän, että te aikaa kulutatte, koska te näette minun sen unohtaneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Mutta jollette minulle unta sano, niin tuomio käy teidän ylitsenne, että te olette aikoneet minun edessäni puhua vääryyttä, siihenasti että aika kuluis: sentähden sanokaat minulle uni, niin minä ymmärrän, että te myös selityksen osaatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Niin vastasivat Kaldealaiset kuninkaan edessä ja sanoivat: ei yhtään ihmistä ole maan päällä, joka sanoa taitaa, mitä kuningas anoo; niin ei ole myös yhtään kuningasta, kuinka suuri ja voimallinen hän olis, joka senkaltaista tähtientutkialta, viisaalta eli Kaldealaiselta vaatii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Sillä se, jota kuningas anoo, on ylen korkia, ja ei yksikään ole, joka sen kuninkaalle sanoa taitaa, paitsi jumalia, jotka ihmisten seassa ei asu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Silloin vihastui kuningas sangen suuresti, ja käski kaikki viisaat Babelissa tapettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Ja tuomio annettiin, että viisaat tapettaman piti; ja Danielia hänen kumppaniensa kanssa myös etsittiin tapettaviksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Silloin saatti Daniel toisen neuvon ja käskyn Ariokille, kuninkaan ylimmäiselle päämiehelle, joka meni ulos tappamaan viisaita Babelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Ja hän vastasi ja sanoi kuninkaan käskyläiselle Ariokille: miksi niin ankara tuomio on käynyt ulos kuninkaalta? Ja Ariok antoi Danielin tietää sen asian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Niin meni Daniel ylös ja rukoili kuningasta, että hän antais hänelle aikaa, sanoaksensa kuninkaalle selitystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Ja Daniel meni kotia ja ilmoitti sen kumppaneillensa Hananialle, Misaelille ja Asarialle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Että he taivaan Jumalalta armoa rukoilisivat sen salaisen asian tähden, ettei Daniel kumppaninensa ynnä muiden viisasten kanssa Babelissa hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Niin ilmoitettiin Danielille se salainen asia yöllä näyssä: niin Daniel kiitti Jumalaa taivaasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Vastasi ja sanoi: kiitetty olkoon Jumalan nimi ijankaikkisesta ijankaikkiseen! sillä hänen on viisaus ja väkevyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Hän muuttaa ajat ja hetket; panee pois kuninkaat ja asettaa kuninkaat; hän antaa viisaille viisauden ja ymmärtäväisille taidon ja ymmärryksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Hän ilmoittaa syvät ja salaiset asiat; hän tietää, mitä pimiässä on, sillä hänen tykönänsä on sula valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Minä kiitän ja ylistän sinua minun isäini Jumala, ettäs minulle viisautta ja väkevyyttä lainaat, ja nyt minulle ilmoittanut olet, jota me sinulta rukoilimme; sinä olet meille kuninkaan asian ilmoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Silloin meni Daniel Ariokin tykö, jolla kuninkaalta käsky oli viisaita Babelissa hukuttaa; hän meni ja sanoi hänelle näin: älä tapa viisaita Babelissa, vaan vie minut ylös kuninkaan tykö, minä tahdon kuninkaalle selityksen sanoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Ariok vei Danielin kiiiruusti kuninkaan eteen, ja sanoi hänelle näin: minä olen löytänyt yhden miehen Juudalaisten vankien seasta, joka kuninkaalle selityksen sanoa taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Kuningas vastasi ja sanoi Danielille, joka Belsatsariksi kutsuttiin: oletko sinä se, joka minulle sen unen, jonka minä nähnyt olen, ja hänen selityksensä ilmoittaa taidat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel vastasi kuninkaan edessä ja sanoi: sitä salautta, jota kuningas anoo, ei viisaat, tähtientutkiat, oppineet ja noidat taida kuninkaalle ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Vaan Jumala on taivaissa, joka taitaa salaiset asiat julistaa, hän tiettäväksi teki kuningas Nebukadnetsarille, mitä tulevaisina aikoina tapahtuman pitää. Tämä on sinun unes ja sinun näkys, kuin sinä makasit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Sinä kuningas vuoteessas ajattelit mitä tästedes tapahtuman pitäis; ja se, joka salaiset ilmoittaa, hän on sinulle osoittanut, kuinka tapahtuman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Niin ovat senkaltaiset asiat minulle ilmoitetut, ei minun viisauteni tähden, niinkuin se olis suurempi kuin kaikkein, jotka elävät, vaan sentähden että sen selitys pitäis kuninkaalle tiettäväksi tuleman, ja sinä saisit sinun sydämes ajatukset tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Sinä kuningas näit, ja katso, suuri ja korkia kuva seisoi suurella kirkkaudella sinun edessäs; ja se oli hirmuinen nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Sen kuvan pää oli parhaimmasta kullasta; mutta sen rinta ja käsivarret olivat hopiasta; sen vatsa ja lanteet olivat vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Sen sääret olivat raudasta; sen jalat olivat puolittain raudasta ja puolittain savesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Sen sinä näit, siihenasti kuin yksi kivi temmattiin ilman käsiä, ja löi sen kuvan jalkoihin, jotka raudasta ja savesta olivat, ja murensi ne rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Silloin tulivat ne kaikki muserretuksi, rauta, savi, vaski, hopia ja kulta, ja tulivat niinkuin akanat suviriihessä, ja tuuli vei ne pois, niin ettei niiden siaa ensinkään löydetty; mutta kivi joka kuvaa löi, tuli suureksi vuoreksi, niin että se kokonaan maan täytti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Tämä on uni; nyt me tahdomme kuninkaalle sen selityksen sanoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Sinä kuningas olet kuningasten kuningas, jolle Jumala taivaasta valtakunnan, voiman, väkevyyden ja kunnian antanut on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Ja kaikki, joissa ihmisen lapset asuvat, ja eläimet kedolla ja linnut taivaan alla on hän sinun käsiis antanut, ja sinulle näiden kaikkein päälle lainasi vallan: sinä se kultainen pää olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Sinun jälkees pitää toisen valtakunnan tuleman, halvemman kuin sinä; sitte se kolmas valtakunta, joka vaskinen on, jonka pitää kaikki maakunnat hallitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Sen neljännen valtakunnan pitää kovan oleman niinkuin raudan; sillä niinkuin rauta särkee ja murentaa kaikki, ja niinkuin rauta kaikki rikkoo, juuri niin tämän piti myös särkemän ja murentaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Mutta ettäs näit jalat ja varpaat, puolittain savesta ja puolittain raudasta, sen pitää jaetun valtakunnan oleman; kuitenkin pitää raudan vahvuudesta siihen jäämän, niinkuin sinä näit raudan olevan savella sekoitetun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Ja että varpaat sen jaloissa puolittain rautaa ja puolittain savea oli, niin sen pitää puolittain vahvan ja puolittain heikon valtakunnan oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Ja ettäs näit raudan sekoitetun savella, niin he kyllä ihmisen siemenellä sekoitetaan, mutta ei he kuitenkaan riipu kiinni toinen toisessansa; niinkuin ei rautaa taideta sekoittaa saven kanssa yhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Mutta näiden kuningasten aikana on Jumala taivaasta yhden valtakunnan asettava, jota ei ikänä kukisteta, ja hänen valtakuntansa ei pidä toiselle kansalle annettaman: sen pitää kaikki nämät valtakunnat särkemän ja hajoittaman, mutta sen pitää ijankaikkisesti pysymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Niinkuin sinä näit kiven, ilman käsiä vuoresta temmatun, joka raudan, vasken, saven, hopian ja kullan murensi: niin on suuri Jumala kuninkaalle näyttänyt, kuinka tästälähin tapahtuman pitää; ja tämä on totinen uni ja sen selitys on oikia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Niin lankesi kuningas Nebukadnetsar kasvoillensa, ja kumarsi Danielia, ja käski tehdä hänelle ruokauhria ja polttouhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Ja kuningas vastasi Danielia ja sanoi: totisesti on teidän Jumalanne kaikkein jumalain Jumala ja kaikkein kuningasten Herra, joka salaiset asiat ilmoittaa, ettäs tämän salaisen asian olet ilmoittaa taitanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Niin kuningas korotti Danielin, ja antoi hänelle suuria ja paljon lahjoja, ja asetti hänen kaikkein Babelin valtakuntain päälle ja päämieheksi kaikkein viisasten päälle Babelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Ja Daniel rukoili kuningasta, että hän pani Babelin maakuntain päälle Sadrakin, Mesakin ja Abednegon; mutta Daniel itse oli kuninkaan tykönä hänen kartanossansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Kuningas Nebukadnetsar teetti kultaisen kuvan, kuusikymmentä kyynärää korkian ja kuusi kyynärää leviän, ja antoi sen panna Duuran kedolle Babelin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Ja kuningas Nebukadnetsar lähetti päämiesten, herrain, maanvanhimpain, tuomarein, käskyläisten, neuvonantajain, virkamiesten ja kaikkein voimallisten perään maalla, että he tulisivat kokoon sitä kuvaa vihkimään, jonka kuningas Nebukadnetsar oli antanut panna ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Silloin tulivat kokoon päämiehet, herrat, maanvanhimmat, tuomarit, käskyläiset, neuvonantajat, virkamiehet ja kaikki voimalliset maalta kuvaa vihkimään, jonka kuningas Nebukadnetsar oli antanut panna ylös; ja heidän piti astuman kuvan eteen, jonka Nebukadnetsar oli antanut panna ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Ja kuuluttaja huusi väkevästi: se olkoon teille sanottu, te kansat, sukukunnat ja kielet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Kuin te kuulette basunan helinän, huilut, harput, kanteleet, psaltarit, trometit ja kaikkinaiset soittamiset, niin teidän pitää lankeeman maahan, ja kumartaman kultaista kuvaa, jonka kuningas Nebukadnetsarin on antanut panna ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Mutta joka ei silloin lankee maahan ja kumarra, se pitää kohta pätsiin heittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Kuin he siis kuulivat basunan helinän, huilut, harput, kanteleet, psaltarit ja kaikkinaiset soittamiset, lankesivat kaikki kansat, maakunnat ja kielet maahan, ja kumarsivat sitä kultaista kuvaa, jonka kuningas Nebukadnetsar oli antanut panna ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Kohta sillä hetkellä astuivat monikahdat Kaldean miehet edes, ja kantoivat Juudalaisten päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Ja sanoivat kuningas Nebukadnetsarille: Kuningas eläköön kauvan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Sinä kuningas olet antanut yhden käskyn, että kaikki ihmiset, jotka kuulivat basunan helinän, harput, huilut, kanteleet, psaltarit, trometit ja kaikkinaiset soittamiset, piti lankeeman maahan, ja kultaista kuvaa kumartaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Vaan joka ei lankeaisi maahan ja kumartaisi, piti tuliseen pätsiin heitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Nyt on Juudan miehiä, jotkas virkoihin Babelin maakunnassa asettanut olet, Sadrak, Mesak ja Abednego, ne miehet katsovat ylön sinun käskys, ja ei kunnioita sinun jumalias, eikä kumarra kultaista kuvaa, jonkas olet antanut panna ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Silloin käski Nebukadnetsar kiukussa ja vihoissansa, että Sadrak, Mesak ja Abednego tuotaisiin edes; ja miehet vietiin kuninkaan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Silloin puhui Nebukadnetsar ja sanoi heille: Kuinka, ettekö te tahdo, Sadrak, Mesak ja Abednego, minun jumaliani kunnioittaa, ja kumartaa kultaista kuvaa, jonka minä olen antanut panna ylös?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nyt siis valmistakaat teitänne, niin pian kuin te kuulette basunan äänen, trometit, harput, huilut, kanteleet, psaltarit ja kaikkinaiset soittamiset, niin langetkaat maahan ja kumartakaat kuvaa, jonka minä olen antanut tehdä. Ja katso, jollette kumarra, niin te pitää tuliseen pätsiin heitettämän. Annas nähdä, kuka se Jumala on, joka teitä minun käsistäni pelastaa taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Silloin vastasivat Sadrak, Mesak ja Abednego ja sanoivat kuninkaalle: Nebukadnetsar, ei tarvita, että me sinua siihen vastaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Katso, meidän Jumalamme, jota me kunnioitamme, taitaa meitä kyllä auttaa tulisesta pätsistä, niin myös sinun kädestäs pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Ja jos ei hän sitä tee, niin tiedä kuitenkin se, kuningas, ettemme sinun jumalias kunnioita, emmekä sitä kultaista kuvaa, jonkas olet antanut panna ylös, kumartaa tahdo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Niin Nebukadnetsar tuli täyteen kiukkua, ja hänen hahmonsa muuttui Sadrakia, Mesakia ja Abednegoa vastaan, ja käski, että pätsi piti seitsemän kertaa kuumemmaksi tehtämän, kuin muulloin tehtiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Ja käski väkeviä miehiä, jotka hänen sotajoukossansa olivat, sitomaan Sadrakia, Mesakia ja Abednegoa ja tuliseen pätsiin heittämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Niin sidottiin nämät miehet hameinensa, lakkinensa, kenkinensä ja muine vaatteinensa, ja heitettiin keskelle tulista pätsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Sillä kuninkaan käsky piti kiiruusti tehtämän, ja pätsi oli lämmitetty aivan kovin, että ne miehet, jotka Sadrakin, Mesakin ja Abednegon sisälle heittivät, kuolivat tulen liekistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Mutta ne kolme miestä Sadrak, Mesak ja Abednego putosivat keskelle tulista pätsiä, niinkuin he sidotut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Silloin hämmästyi kuningas Nebukadnetsar suuresti ja meni nopiasti ylös ja sanoi neuvonantajillensa: Emmekö me kolme miestä sidottuna antaneet tuleen heittää? He vastasivat ja sanoivat kuninkaalle: Totta, herra kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Hän vastasi ja sanoi: Katso, ja minä näen neljä miestä vallallansa käyvän tulen keskellä, ja ovat kulumatta; ja se neljäs on niinkuin Jumalan poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Silloin Nebukadnetsar meni tulisen pätsin suulle ja sanoi: Sadrak, Mesak ja Abednego, te kaikkein korkeimman Jumalan palveliat. Lähtekäät ulos ja tulkaat tänne; silloin läksi Sadrak, Mesak ja Abednego ulos tulesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Ja päämiehet, herrat, käskyläiset ja kuninkaan neuvonantajat tulivat kokoon, ja katselivat näitä miehiä, ettei tuli mitään heidän ruumiillensa tehnyt, eikä heidän hiuskarvaansakaan polttanut, eikä heidän vaatteitansa muuttanut; eikä myös tulen kartuakaan heissä tuntunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Silloin puhui Nebukadnetsar ja sanoi: Kiitetty olkoon Sadrakin, Mesakin ja Abednegon Jumalala, joka enkelinsä lähetti ja palveliansa pelasti, jotka häneen uskalsivat, ja ei kuninkaan käskyä pitäneet, vaan antoivat ruumiinsa vaaraan, ettei he yhtään muuta Jumalaa kunnioittaisi eikä kumartaisi, vaan ainoastaan Jumalaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Niin olkoon nyt tämä minun käskyni: Kuka ikänä kaikissa kansoissa, sukukunnissa ja kielissä Sadrakin, Mesakin ja Abednegon Jumalaa pilkkaa, hän pitää kappaleiksi hakattaman, ja hänen huoneensa lokaläjäksi kukistettaman; sillä ei yhtään muuta Jumalaa ole, joka niin pelastaa taitaa, kuin tämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Ja kuningas antoi suuren vallan Sadrakille, Mesakille ja Abednegolle Babelin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Kuningas Nebukadnetsar kaikille kansoille, sukukunnille ja kielille, jotka asuvat kaikessa maassa: Teille olkoon paljon rauhaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Minä näen sen hyväksi, että minä ilmoitan teille ne merkit ja ihmeet, jotka korkein Jumala minulle tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Sillä hänen merkkinsä ovat suuret ja hänen ihmeensä voimalliset; hänen valtakuntansa on ijankaikkinen valtakunta, ja hänen valtansa pysyy suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Minä Nebukadnetsar, hyvässä levossa ollessani minun huoneessani, ja kuin kaikki hyvin oli minun linnassani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Näin unta, ja hämmästyin; ja ne ajatukset, jotka minulla olivat vuoteessani sen näyn tähden, saattivat minut murheelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Ja minä käskin kaikki viisaat Babelista tuoda minun eteeni, sanomaan minulle, mitä se uni tietäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Niin tulivat edes tähtientutkiat, viisaat, Kaldealaiset ja tietäjät, joiden edessä minä unen juttelin; vaan ei he taitaneet sen selitystä minulle ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Siihenasti että viimein Daniel tuli minun eteeni, joka minun Jumalani nimen jälkeen Belsatsariksi kutsutaan, jolla on pyhäin jumalain henki; ja minä juttelin hänelle unen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Belsatsar, sinä ylimmäinen tähtientutkiain seassa, jolla minä tiedän pyhäin jumalain hengen olevan, ja sinulta ei mitään salattu ole; sano minun uneni näky, jonka minä nähnyt olen, ja mitä se tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Tämä on näky, jonka minä nähnyt olen minun vuoteessani: Katso, keskellä maata seisoi puu, joka oli sangen korkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Se oli suuri ja paksu puu. Sen korkeus ulottui taivaasen asti ja näkyi koko maan ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Sen oksat olivat kauniit, ja kantoivat paljon hedelmää, josta kaikki syödä saivat; kaikki eläimet kedolla löysivät varjon sen alla, ja taivaan linnut istuivat sen oksilla, ja kaikki liha elätti itsensä siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Ja minä näin yhden näyn minun vuoteessani, ja katso, pyhä vartia tuli alas taivaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Se huusi korkiasti ja sanoi näin: Hakatkaat se puu poikki ja karsikaat oksat ja repikäät lehdet ja hajoittakaat sen hedelmät, että eläimet sen alta lähtisivät pois, ja linnut sen oksilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Kuitenkin jättäkäät kanto juurinensa maahan, mutta hänen pitää rautaisissa ja vaskisissa kahleissa kedolla ruohossa käymän. Hänen pitää makaaman taivaan kasteen alla ja kastuman ja ruokkiman itsensä eläinten kanssa maan ruohoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Ja ihmisen sydän pitää otettaman häneltä pois ja eläimen sydän hänelle jälleen annettaman; siihenasti että seitsemän aikaa häneltä kuluneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Se on vartiain neuvossa päätetty, ja pyhäin kanssa puheessa vahvistettu, että elävät tuntisivat Ylimmäisellä vallan olevan ihmisten valtakuntain päälle, ja antavan ne kellenkä hän tahtoo, ja että hän asettaa kaikkein nöyrimmän ihmisen niiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Tämän unen olen minä kuningas Nebukadnetsar nähnyt. Vaan sinä Belsatsar sano sen selitys; sillä kaikki viisaat minun valtakunnassani ei taida minulle ilmoittaa sen selitystä; vaan sinä kyllä taidat, sillä pyhäin jumalain henki on sinun tykönäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Silloin hämmästyi Daniel, joka Belsatsariksi kutsuttiin, hetkeksi aikaa, ja hänen ajatuksensa saattivat hänet murheelliseksi. Mutta kuningas sanoi: Belsatsar, se uni ja sen selitys ei mahda sinua murheelliseksi saattaa. Belsatsar vastasi ja sanoi: Ah minun herrani, tämä uni olkoon sinun vihollisilles ja sen selitys sinun vainoojilles!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Se puu, jonkas nähnyt olet, että se suuri ja paksu oli, ja hänen korkeutensa taivaasen ulottui, ja näytti itsensä kaiken maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Ja sen oksat olivat kauniit, ja sen hedelmiä oli paljo, josta kaikki ravittiin ja eläimet kedolla asuivat sen alla, ja taivaan linnut istuivat sen oksilla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Se olet sinä, kuningas, joka niin suuri ja voimallinen olet; sillä sinun voimas on suuri ja ulottuu taivaasen, ja sinun valtas maailman ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Mutta että kuningas pyhän vartian nähnyt on taivaasta tulevan alas ja sanovan: Hakatkaat se puu poikki ja turmelkaat se. Kuitenkin kanto juurinensa jättäkäät maahan, mutta hänen pitää rautaisissa ja vaskisissa kahleissa kedolIa ruohossa käymän ja pitää makaaman taivaan kasteen alla ja kastuman ja itsensä eläinten kanssa kedolla ruokkiman; siihen asti että seitsemän aikaa häneltä kuluneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Tämä on selitys, herra kuningas, ja tämä on sen Korkeimman neuvo, joka tulee minun herralleni kuninkaalle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Sinä ajetaan pois ihmisten seasta, ja täytyy eläinten seassa kedolla olla, ja annetaan ruohoja syödäkses niinkuin härkäin, ja olet makaava taivaan kasteen alla, ja kastuva, siihenasti kuin seitsemän aikaa sinulta kuluneet ovat, ettäs tuntisit Korkeimmalla vallan olevan ihmisten valtakuntain päälle, ja hänen antavan ne kellenkä hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Mutta että sanottu on, että kanto kuitenkin juurinensa puulle jäämän pitää, niin sinun valtakuntas pysyy sinulle, koska tuntenut olet taivaan vallan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Sentähden, herra kuningas, kelvatkoon sinulle minun neuvoni, ja päästä itses synnistäs vanhurskaudella, ja vapaaksi sinun pahoista töistäs laupiudella vaivaisia kohtaan, niin hän sinun rauhas pitentää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Nämät kaikki tapahtuivat kuningas Nebukadnetsarille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Sillä kahdentoistakymmenen kuukauden perästä, kuin hän kuninkaallisessa linnassansa Babelissa käyskenteli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Puhui kuningas ja sanoi: Eikö tämä ole se suuri Babel, jonka minä rakentanut olen kuninkaalliseksi huoneeksi, minun suuren voimani kautta, minun kunniani ylistykseksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Ennenkuin kuningas nämät sanat puhunut oli, tuli ääni alas taivaasta: Sinulle kuningas Nebukadnetsar sanotaan: Sinun valtakuntas otetaan sinulta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Ja sinä ajetaan pois ihmisten seasta; sinun pitää eläinten seassa kedolla oleman. Ruohoja sinun annetaan syödä niinkuin härkäin siihenasti että seitsemän aikaa sinulta kuluneet ovat, ettäs tuntisit Korkeimmalla vallan olevan ihmisten valtakuntain päälle, ja hänen antavan ne kenelle hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Kohta sillä hetkellä täytettiin sana kuningas Nebukadnetsarissa, ja hän ajettiin pois ihmisten seasta ja söi ruohoja niinkuin härkä, ja hänen ruumiinsa oli taivaan kasteen alla ja kastui siihen asti, että hänen hiuksensa kasvoivat niin suuriksi kuin kotkan höyhenet, ja hänen kyntensä niinkuin linnun kynnet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Sen ajan perästä nostin minä Nebukadnetsar silmäni taivaasen päin ja tulin jälleen taidolleni, ja kiitin sitä Korkeinta. Minä ylistin ja kunnioitin sitä, joka elää ijankaikkisesti, jonka valta on ijankaikkinen valta, ja hänen valtakuntansa pysyy suvusta sukuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'Jonka suhteen kaikki, jotka asuvat maan päällä, ovat luetut niinkuin ei mitään. Hän tekee, kuinka hän tahtoo taivaan sotajoukon kanssa, jotka asuvat maan päällä, ja ei kenkään taida hänen kättänsä estää, eikä hänelle sanoa: Mitäs teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'Silloin tulin minä jälleen taidolleni, ja kuninkaalliseen kunniaani ja jalouteeni ja minun muotooni. Ja minun neuvonantajani ja voimalliseni etsivät minua, ja minä pantiin jälleen valtakuntaani, ja sain vielä suuremman kunnian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Sentähden kiitän minä Nebukadnetsar ja kunnioitan ja ylistän taivaan kuningasta; sillä kaikki hänen työnsä on totuus ja hänen tiensä oikiat; ja joka ylpiä on, sen hän taitaa nöyryyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Kuningas Belsatsar teki kuuluisan pidon tuhannelle päämiehellensä, ja joi itsensä viinasta juovuksiin näiden tuhannen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Ja kuin hän juopunut oli, käski hän tuoda ne kultaiset ja hopiaiset astiat, jotka Nebukadnetsar, hänen isänsä Jerusalemin templistä ottanut oli, juodaksensa niistä voimallistensa, emäntäinsä ja vaimoinsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Niin tuotiin ne kultaiset astiat, jotka templistä, Jumalan huoneesta, Jerusalemista otetut olivat; ja kuningas, hänen voimallisensa, emäntänsä ja vaimonsa joivat niistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Ja kuin he joivat viinaa, kiittivät he kultaisia, hopiaisia, vaskisia, rautaisia, puisia ja kivisiä jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Juuri sillä hetkellä kävivät sormet niinkuin ihmisen käsi, kirjoittamaan kynttiläjalan kohdalle seinään kuninkaan salissa, ja kuningas äkkäsi kirjoittajan käden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Silloin muuttui kuningas, ja hänen ajatuksensa peljättivät hänen, niin että hänen lanteensa horjuivat, ja hänen polvensa vapisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Ja kuningas huusi korkiasti, että viisaat, Kaldealaiset ja tietäjät tuotaisiin; ja käski sanoa viisaille Babelissa: Kuka ikänä tämän kirjoituksen lukee, ja ilmoittaa minulle sen selityksen, hän pitää purpuralla vaatetettaman, ja kultakäädyt kaulassansa kantaman ja kolmas Herra oleman tässä valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Silloin tulivat kaikki kuninkaan viisaat edes, vaan ei he taitaneet sitä kirjoitusta lukea, eikä sen selitystä kuninkaalle ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Siitä hämmästyi kuningas Belsatsar vielä kovemmin, ja hänen muotonsa muuttui, ja hänen voimallisensa tulivat murheellisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Sentähden meni kuningatar kuninkaan ja hänen voimallistensa asian tähden pitohuoneesen, ja sanoi: Kuningas eläköön kauvan! Älä niin peljästy sinun ajatuksistas ja älä niin muotoas muuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Sinun valtakunnassas on mies, jolla on pyhäin jumalain henki, sillä sinun isäs aikana löydettiin hänessä valistus, toimi ja viisaus, niinkuin jumalten viisaus on; ja sinun isäs Nebukadnetsar pani hänen tähtientutkiain, viisasten, Kaldealaisten ja tietäjäin päälle. Niin teki kuningas, sinun isäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Että korkiampi henki hänen tykönänsä löydettiin, niin myös ymmärrys ja taito unia selittämään, osaamaan pimeitä puheita ja salaisia asioita ilmoittamaan. Daniel, jonka kuningas antoi Belsatsariksi nimittää; niin kutsuttakaan Daniel; hän sanoo, mitä se tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Silloin vietiin Daniel kuninkaan eteen. Ja kuningas puhui ja sanoi Danielille: Oletko sinä Daniel, yksi Juudalaisista vangeista, jotka kuningas, minun isäni, Juudeasta tänne tuonut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Minä olen kuullut sinusta, että sinulla on pyhäin jumalain henki, että myös valistus, ymmärrys ja korkia viisaus sinussa löydetty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Minä olen antanat kutsua eteeni toimelliset ja viisaat tätä kirjoitusta lukemaan ja sen selitystä minulle ilmoittamaan, ja ei he taida sanoa, mitä se tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Mutta minä kuulen sinusta, että sinä taidat pimiät asiat selittää ja salatut ilmoittaa. Jos sinä nyt taidat tämän kirjoituksen lukea ja minulle ilmoittaa, mitä se tietää, niin sinä pitää purpuralla puetettaman ja kultakäädyt kaulassas kantaman ja kolmas herra oleman tässä valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Niin vastasi Daniel ja sanoi kuninkaalle: Pidä itse lahjas ja anna antimes muille. Minä luen kuitenkin kuninkaalle kirjoituksen, ja ilmoitan sen selityksen hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Herra kuningas, korkein Jumala on sinun isälles Nebukadnetsarille valtakunnan, voiman, kunnian ja jalouden antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Ja sen voiman tähden, joka hänelle annettu oli, pelkäsivät ja karttoivat häntä kansat, sukukunnat ja kielet. Hän tappoi kenen hän tahtoi, hän jätti elämään kenen hän tahtoi, hän ylensi kenen hän tahtoi, hän alensi kenen hän tahtoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mutta koska hänen sydämensä paisui, ja hänen henkensä ylpeyteen paisuneeksi tuli, hyljättiin hän kuninkaalliselta istuimelta, ja tuli pois kunniastansa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Ja ajettiin pois ihmisten seasta. Ja hänen sydämensä tuli eläinten kaltaiseksi, ja täytyi metsän eläinten kanssa juosta, ja söi ruohoja niinkuin härkä, ja hänen ruumiinsa oli taivaan kasteen alla, ja kastui, siihenasti, että hän oppi, että korkeimmalla Jumalalla on valta ihmisten valtakuntain päälle, ja hän antaa ne kellenkä hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Ja sinä Belsatsar, hänen poikansa, et ole sydäntäs nöyryyttänyt, ehkäs kaikki kyllä ne tiesit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Vaan olet itses korottanut taivaan Herraa vastaan. Ja hänen huoneensa astiat piti kannettaman sinun etees, ja sinä, sinun voimallises, sinun emäntäs ja vaimos olette niistä viinaa juoneet. Niin myös hopiaisia, kultaisia, vaskisia, rautaisia, puisia ja kivisä jumalia kiittäneet, jotka ei näe eikä kuule, eikä tuta taida. Mutta sitä Jumalaa, jonka kädessä sinun henkes on, ja jonka tykönä kaikki sinun ties ovat, et sinä ole kunnioittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Sentähden on häneltä lähetetty tämä käsi, ja tämä kirjoitus kirjoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Ja tämä on kirjoitus, joka siinä kirjoitettu on: Mene, Mene, Tekel, Upharsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Ja tämä on selitys: Mene; se on: Jumala on sinun valtakuntas lukenut ja lopettanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel; se on: Sinä olet vaa\'alla punnittu, ja aivan köykäiseksi löydetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres; se on: Sinun valtakuntas on jaettu ja Mediläisille ja Persialaisille annettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Silloin käski Belsatsar, että Daniel purpuralla puetettaman piti, ja kultakäädyt hänen kaulaansa annettaman, ja antoi hänestä kuuluttaa, että hän kolmas herra on valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Mutta juuri sinä yönä tapettiin Belsatsar, Kaldean kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'Ja Darius Mediläinen sai valtakunnan, kuin hän kahdenseitsemättäkymmentä ajastajan vanha oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Ja Darius näki sen hyväksi panna koko valtakuntaan sata ja kaksikymmentä maanvanhinta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Näiden päälle pani hän kolme päämiestä, joista Daniel yksi oli, joille maanvanhimmat piti luvun tekemän, ettei kuningas kärsisi vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Mutta Daniel voitti kaikki päämiehet ja maanvanhimmat, sillä hänessä oli korkiampi henki. Sentähden ajatteli kuningas pannaksensa hänet koko valtakunnan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Jonka tähden päämiehet ja maanvanhimmat etsivät syytä Danielia vastaan valtakunnan puolesta, vaan ei he taitaneet yhtään syytä eikä rikosta löytää, sillä hän oli uskollinen, ettei hänessä mitään vikaa eikä rikosta löytää taidettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Niin sanoivat ne miehet: Emme löydä yhtään syytä tämän Danielin kanssa, ellemme löydä hänen Jumalansa palveluksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Silloin tulivat päämiehet ja maanvanhimmat joukoittain kuninkaan eteen ja sanoivat hänelle näin: Kuningas Darius eläköön kauvan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Valtakunnan päämiehet, herrat, maanvanhimmat, neuvonantajat ja valtamiehet ovat ajatelleet, että kuninkaallinen käsky annettaisiin ja ankara kielto, että jos joku kolmenakymmenenä päivänä joltakulta jumalalta eli ihmiseltä, paitsi sinulta, kuningas, ainoasti jotakin anoo, pitää jalopeurain luolaan heitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Sentähden, herra kuningas, vahvista se käsky ja kirjoita alle, ettei sitä jälleen muutettaisi, Mediläisten ja Persian oikeuden jälkeen, jota ei kenkään rikkoa tohdi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Niin kirjoitti kuningas Darius sen kirjoituksen ja käskyn alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Kuin Daniel sai tietää kirjoitetuksi sen käskyn alle, meni hän ylös huoneesensa, ja hänen suvihuoneensa akkunat olivat avoimet Jerusalemia päin, ja lankesi kolme kertaa päivässä polvillensa; rukoili, kiitti ja ylisti Jumalaansa, niinkuin hänen tapansa oli ennenkin tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Silloin tulivat ne miehet joukoittain ja löysivät Danielin rukoilevan ja avuksensa huutavan Jumalaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Niin he astuivat edes ja puhuivat kuninkaan kanssa siitä kuninkaallisesta käskystä ja sanoivat: Etkös kirjoittanut käskyn alle, että jos joku ihminen kolmenakymmenenä päivänä jotakin anova olis joltakulta jumalalta eli ihmiseltä, paitsi sinulta ainoastansa, kuningas, se pitää jalopeurain luolaan heitettämän? Kuningas vastasi ja sanoi: Se on tosi, ja Mediläisten ja Persialaisten oikeutta ei pidä kenenkään rikkoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'He vastasivat ja sanoivat kuninkaalle: Daniel, yksi Juudalaisista vangeista, ei tottele sinua, herra kuningas, eikä sinun käskyäs, jonka allekirjoittanut olet; sillä hän rukoilee kolmasti päivässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Kuin Kuningas sen kuuli, tuli hän sangen murheelliseksi ja ahkeroitsi suuresti, että hän Danielin vapahtais; ja vaivasi itsiänsä auringon laskemaan asti, että hän hänet pelastais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Vaan ne miehet tulivat joukoittain kuninkaan tykö ja sanoivat hänelle: Tiedä, herra kuningas, että Mediläisten ja Persialaisten oikeus on, että kaikki kiellot ja käskyt, joita kuningas päättänyt on, pitää muuttumattomat oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Silloin kuningas käski, ja he toivat Danielin edes ja heittivät hänet jalopeurain luolaan. Mutta kuningas puhui ja sanoi Danielille: Sinun Jumalas, jotas lakkaamata palvelet, auttakoon Sinua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Ja he toivat kiven ja panivat luolan ovelle: Sen painoi kuningas omalla sinetillänsä ja voimallistensa sinetillä, ettei kuninkaan tahto muutettaisi Danielia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Ja kuningas meni linnaansa ja kulutti yön syömättä ja ei antanut mitään huvitusta tuoda eteensä, eikä myös yhtään unta saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Aamulla varhain päivän koittaissa nousi kuningas ylös ja meni kiiruusti jalopeurain luolan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Ja kuin hän luolan tykö lähestyi, huusi hän Danielia surkialla äänellä ja kuningas puhui ja sanoi Danielille: Daniel, sinä elävän Jumalan palvelia, onko Jumalas, jotas ilman lakkaamata palvelet, voinut sinut jalopeuroilta pelastaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Niin Daniel puhui kuninkaan kanssa sanoen: Kuningas eläköön kauvan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Minun Jumalani on lähettänyt enkelinsä, joka jalopeurain kidat on pitänyt kiinni, ettei he minulle mitään pahaa tehneet ole, sillä minä olen hänen edessänsä viattomaksi löydetty. En myös ole minä sinua vastaan, herra kuningas, mitään tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Niin kuningas ihastui siitä suuresti, ja käski Danielin luolasta ylös ottaa. Ja he ottivat Danielin ylös luolasta, ja ei hänessä yhtään haavaa löydetty, sillä hän oli turvannut Jumalaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Silloin käski kuningas; ja ne miehet tuotiin edes, jotka olivat kantaneet Danielin päälle, ja jalopeurain luolaan heitettiin lapsinensa ja vaimoinensa. Ja ennenkuin he luolan pohjaan tulivat, tarttuivat heihin jalopeurat ja murensivat heidän luunsakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Silloin antoi kuningas Darius kirjoittaa kaikille kansoille, sukukunnille ja kielille, jotka asuvat kaikessa maassa: Teille olkoon paljon rauhaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Se käsky on minulta asetettu, että kaikessa minun kuninkaan valtakunnassani Danielin Jumalaa peljättämän ja vavistaman pitää, sillä hän on elävä Jumala, joka ijankaikkisesti pysyy, ja hänen valtakuntansa on katoomatoin, ja hänen voimansa loppumatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Hän on vapahtaja ja hädässä auttaja, ja hän tekee tunnustähtiä ja ihmeitä sekä taivaassa että maan päällä. Hän on Danielin jalopeurain käsistä pelastanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Ja Daniel tuli voimalliseksi Dariuksen valtakunnassa ja Koreksen Persialaisen valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Ensimäisenä Belsatsarin, Babelin kuninkaan vuotena näki Daniel unen ja näyn vuoteessansa; ja hän kirjoitti sen unen, ja käsitti sen näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel puhui ja sanoi: Minä näin näyn yöllä, ja katso, neljä tuulta taivaan alla pauhasivat toinen toistansa vastaan suurella merellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Ja neljä suurta petoa nousi merestä, aina toinen toisen muotoinen kuin toinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Ensimäinen niinkuin jalopeura, jolla olivat kotkan siivet. Ja minä katsoin siihen asti, että siivet temmattiin pois häneltä ja hän otettiin ylös maasta, ja seisoi jaloillansa niinkuin ihminen, ja hänelle annettiin ihmisen sydän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Ja katso, toinen peto oli karhun muotoinen ja seisoi yhdellä puolella, ja oli hänen suussansa hammastensa seassa kolme kylkiluuta. Ja hänelle sanottiin: Nouse ja syö paljon lihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Tämän jälkeen minä näin, ja katso, toinen peto oli pardin muotoinen. Hänellä oli neljä linnun siipeä hänen selässänsä, ja sillä pedolla oli neljä päätä, ja hänelle annettiin valta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Senjälkeen minä näin tässä näyssä yöllä, ja katso, neljäs peto oli kauhia ja hirmuinen ja sangen väkevä, ja hänellä olivat suuret rautaiset hampaat. Söi ympäriltänsä ja murensi ja liian hän tallasi jaloillansa. Se oli myös paljon toisin kuin ne muut pedot, jotka hänen edellänsä olivat, ja hänellä oli kymmenen sarvea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Minä katselin tarkasti sarvia, ja katso, niiden seassa puhkesi toinen vähä sarvi, jonka edestä kolme niistä ensimäisistä sarvista reväistiin pois. Ja katso, sillä sarvella olivat silmät niinkuin ihmisen silmät ja suu, joka pahui suuria asioita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Nämät minä näin, siihenasti, että istuimet pantiin. Ja istui vanha-ikäinen, jonka vaatteet olivat lumivalkiat, ja hänen päänsä hiukset niinkuin puhdas villa, hänen istuimensa oli niinkuin tulen liekki, ja hänen rattaansa niinkuin polttava tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Tulinen virta juoksi ja kävi ulos hänen kasvoinsa edestä. Tuhannen kertaa tuhannen palveli häntä ja sata kertaa tuhannen tuhatta seisoi hänen edessänsä. Tuomio pidettiin, ja kirjat avattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Minä katsoin niiden suurten puhetten äänen tähden, joita se sarvi puhui; minä katselin, siihen asti, että peto tapettu oli, ja hänen ruumiinsa hukkui, ja tuleen palamaan heitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Ja muiden petoin valta myös loppui; sillä heillä oli määrätty aika ja hetki, kuinka kauvan kukin oleman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Minä näin tässä näyssä yöllä, ja katso; yksi tuli taivaan pilvissä niinkuin ihmisen poika, ja hän tuli hamaan vanha-ikäisen tykö, ja vietiin hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Ja hän antoi hänelle voiman, kunnian ja valtakunnan, että häntä kaikki kansat, sukukunnat ja kielet palveleman pitää. Hänen valtansa on ijankaikkinen valta, joka ei huku, ja hänen valtakunnallansa ei ole loppua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Minä Daniel hämmästyin sitä minun hengessäni, ja ne minun näkyni peljättivät minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Ja minä menin yhden tykö niistä, jotka siinä seisoivat, ja rukoilin häntä, että hän minulle näistä kaikista tiedon antais. Ja hän puhui minun kanssani, ja ilmoitti minulle niiden sanain selityksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Nämät neljä suurta petoa ovat neljä kuningasta, jotka nousevat maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Vaan sen Korkeimman pyhät pitää valtakunnan omistaman ja pitää siinä asuman ijankaikkisesti ja ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Sitte minä olisin mielelläni tahtonut tietää totista tietoa neljännestä pedosta, joka paljo toisin oli kuin kaikki ne muut; sangen hirmuinen, jolla rautaiset hampaat ja vaskiset kynnet olivat; joka ympäriltänsä söi ja murensi ja liian jaloillansa tallasi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Ja niistä kymmenestä sarvesta hänen päässänsä ja siitä toisesta, joka putkahti ulos; jonka edestä putosivat pois kolme; ja siitä sarvesta, jolla silmät olivat ja suu, joka suuria asioita puhui ja suurempi oli kuin ne, jotka hänen tykönänsä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Ja minä näin sen sarven sotivan pyhiä vastaan ja voittavan heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Siihen asti, että vanha-ikäinen tuli, ja tuomio annettiin sen Korkeimman pyhille, ja aika joutui, että pyhät valtakunnan omistivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Hän sanoi näin: Neljäs peto on neljäs valtakunta maailmassa, joka on erinäinen kaikista valtakunnista. Se syö kaiken maan, tallaa ja turmelee sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Ne kymmenen sarvea ovat kymmenen kuningasta, jotka siitä valtakunnasta nousevat. Ja niiden jälkeen tulee toinen, joka erinäinen on entisistä, ja nöyryyttää kolme kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Hän puhuu Korkeinta vastaan ja hävittää Korkeimman pyhät ja rohkenee ajat ja lain muuttaa. Mutta he annetaan hänen käsiinsä yhdeksi hetkeksi ja monikahdoiksi ajoiksi ja puoleksi ajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Sen jälkeen pidetään tuomio, ja hänen valtansa otetaan pois, että hän peräti hukutetaan ja kadotetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Vaan valtakunta, valta ja voima kaiken taivaan alla annetaan Korkeimman pyhälle kansalle, jonka valtakunta on ijankaikkinen valtakunta, ja kaikki vallat pitää häntä palveleman ja kuuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Tämä oli sen puheen loppu. Vaan minä Daniel olin sangen murheellinen minun ajatuksissani ja minun muotoni muuttui. Kuitenkin minä kätkin puheet sydämessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Kolmantena kuningas Belsatsarin valtakunnan vuotena näin minä Daniel näyn sen jälkeen, joka minulle ensin näkynyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Mutta kuin minä näyn näin, olin minä Susanin linnassa Elamin maalla; ja minä näin näyssäni olevani Ulain virran tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Ja minä nostin silmäni ja näin, ja katso, oinas seisoi virran tykönä, jolla oli kaksi korkiaa sarvea, toinen korkiampi kuin toinen, ja korkiampi puhkesi jälistä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Sitte minä näin oinaan puskevan sarvillansa länteen päin, pohjaan päin ja etelään päin, ja ei yksikään peto taitanut seisoa hänen edessänsä, eikä hänen käsistänsä pelastettaa, vaan hän teki, mitä hän tahtoi ja tuli suureksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Ja kuin minä näistä otin vaarin, katso, niin tuli kauris koko maan päälle, niin ettei hän sattunut maahan, ja kauriilla oli jalo sarvi silmäinsä välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Ja hän tuli hamaan kaksisarvisen oinaan tykö, jonka minä seisovan näin virran tykönä. Ja hän juoksi vihoissansa väkevästi hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Ja minä näin, että hän tuli tuimasti oinaan tykö, ja julmistui hänen päällensä ja puski oinasta ja särki hänen molemmat sarvensa. Ja oinaalla ei ollut voimaa seisoa hänen edessänsä, vaan hän heitti hänet maahan ja tallasi hänet. Ja ei kenkään taitanut oinasta hänen käsistänsä pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Ja kauris tuli sangen suureksi ja kuin hän väkevämmäksi tullut oli, lohaistiin suuri sarvi, ja sen siaan kasvoi neljä kaunista jälleen neljää taivaan tuulta kohden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Ja yhdestä niistä kasvoi yksi vähä sarvi: Se tuli sangen suureksi etelään päin, itään päin ja ihanaisen maan puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Ja se kasvoi taivaan sotajoukkoon asti ja heitti monikahdat sotajoukosta ja tähdeistä maahan ja tallasi ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Ja se tuli suureksi sotajoukon päämieheen asti ja otti häneltä pois jokapäiväisen uhrin ja hävitti hänen pyhänsä huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Vaan senkaltainen voima oli hänelle annettu jokapäiväistä uhria vastaan synnin tähden, että hän totuuden maahan löis. Ja hän tekee sen ja menestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Mutta minä kuulin yhden pyhän puhuvan. Ja se pyhä sanoi yhdelle ja puhui: Kuinka kauvan senkaltainen näky jokapäiväisistä uhreista viipymän pitää ja synnistä, jonka tähden tämä hävitys tapahtuu, että sekä pyhä ja sotajoukko tallataan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Ja hän vastasi minua: Aamusta ehtoosen asti kaksituhatta ja kolmesataa päivää, niin pyhä jälleen vihitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Ja kuin minä Daniel sen näyn näin ja olisin mielelläni ymmärtänyt, katso, niin seisoi minun edessäni niinkuin miehen muotoinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Ja minä kuulin Ulain keskellä ihmisen äänen, joka huusi ja sanoi: Gabriel, selitä hänelle tämä näky, että hän ymmärtäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Ja hän tuli juuri liki minua, mutta minä hämmästyin, kuin hän tuli, ja lankesin kasvoilleni. Ja hän sanoi minulle: Ota vaari, ihmisen poika, sillä tämä näky ajallansa täytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Ja kuin hän minun kanssani puhui, putosin minä näännyksiin maahan kasvoilleni. Ja hän rupesi minuun, ja nosti minut seisoalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Ja sanoi: katso, minä tahdon sinulle osoittaa, kuinka viimeisen vihan aikana käypä on, sillä lopulla on hänen määrätty aikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Kaksisarvinen oinas, jonkas näit, ovat Median ja Persian kuninkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Mutta karvainen kauris on Grekan maan kuningas, ja se suuri sarvi hänen silmäinsä välillä on se ensimäinen kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Mutta että neljä nousivat sen sarven siaan, kuin se särjetty oli, ennustaa, että neljä valtakuntaa siitä kansasta tulee, vaan ei niin väkevää kuin hän oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Näiden valtakuntain jälkeen, kuin pahointekiät vallan saaneet ovat, nousee häpeemätön kuningas ja kavala tapauksissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Se on voimallinen, mutta ei väkensä kautta. Hän hävittää ihmeellisesti ja menestyy ja toimittaa. Hän hukuttaa väkevät ja pyhän kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Ja hänen kavaluutensa kautta menestyy hänen petoksensa. Ja paisuu sydämessänsä ja myötäkäymisen kautta hän monta hävittää. Ja hän korottaa itsensä kaikkein ruhtinasten Ruhtinasta vastaan, vaan ilman käsiä hän pitää rikottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Se näky ehtoosta ja aamusta, joka sinulle sanottu oli, on tosi. Vaan sinun pitää tämän näyn salassa pitämän, sillä siihen on vielä paljo aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Ja minä Daniel väsyin ja sairastin monikahdat päivät. Sen perästä nousin minä ja toimitin kuninkaan askareet. Ja minä ihmettelin sitä näkyä, ja ei kenkään ollut, joka minua neuvoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Ensimäisenä Dariuksen Ahasveruksen pojan vuonna Mediläisten suvusta, joka Kaldean valtakuntaa hallitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Juuri sinä ensimäisenä hänen valtakuntansa vuotena, löysin minä Daniel kirjoista vuosiluvun, josta Herra puhunut oli Jeremialle prophetalle, että Jerusalemin hävitys piti täytettämän seitsemäntenäkymmenentenä ajastaikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Ja minä käänsin minuni etsimään Herraa Jumalaa rukouksella ja anomisella, paastolla säkissä ja tuhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Ja rukoilin Herraa minun Jumalaani, tunnustin ja sanoin: Herra, sinä suuri ja hirmuinen Jumala, joka liiton ja armon pidät niille, jotka sinua rakastavat ja sinun käskys pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Me olemme syntiä ja väärin tehneet, jumalattomat ja tottelemattomat olleet. Me olemme sinun käskyistäs ja oikeuksistas poikenneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Emme totelleet sinun palvelioitas prophetaita, jotka saarnasivat sinun nimees meidän kuninkaillemme, päämiehillemme ja isillemme ja myös kaikelle kansalle maakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Sinä Herra olet vanhurskas. Mutta meidän täytyy hävetä, niinkuin tänäpänä tapahtuu Juudan miehille ja Jerusalemin asuvaisille ja kaikelle Israelille, sekä niille, jotka läsnä että niille, jotka kaukana ovat kaikissa maakunnissa, kuhunka sinä heitä hyljännyt olet heidän pahain tekoinsa tähden, joita he ovat tehneet sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Ja Herra; meidän ja meidän kuninkaamme, meidän päämiehemme ja meidän isämme täytyy hävetä, että me olemme syntiä tehneet sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Herra meidän Jumalamme on laupius ja anteeksi antamus, vaikka me olemme vastahakoiset olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Ja emme totelleet Herran meidän Jumalamme ääntä, että me vaeltaneet olisimme hänen käskyissänsä, jotka hän meille antoi palveliainsa prophetain kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Vaan koko Israel rikkoi sinun lakis ja suuttui kuulemasta sinun ääntäs. Sentähden on myös se kirous ja vala sattunut meihin, joka kirjoitettu on Moseksen Jumalan palvelian laissa, että me olemme syntiä tehneet häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Ja hän on sanansa pitänyt, jonka hän puhunut on meitä ja meidän tuomareitamme vastaan, jotka meitä tuomitsivat; että hän niin suuren onnettomuuden on antanut tulla meidän päällemme, ettei sen kaltaista kaiken taivaan alla tapahtunut ole kuin Jerusalemissa tapahtunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Niinkuin kirjoitettu on Moseksen laissa, niin on kaikki tämä onnettomuus meille tapahtunut. Emme myös rukoilleet Herran meidän Jumalamme edessä, että me synnistä palajaisimme ja sinun totuutes ymmärtäisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Sentähden on myös Herra valvonut tässä onnettomuudessa, ja on sen saattanut meidän päällemme. Sillä Herra meidän Jumalamme on hurskas kaikissa töissänsä, joita hän tekee, koska emme totelleet hänen ääntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Ja nyt Herra meidän Jumalamme, joka sinun kansas Egyptistä olet johdattanut ulos väkevällä kädellä ja tehnyt itselles nimen, niinkuin se tänäpänä on: Me olemme syntiä tehneet, ja jumalattomat olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Ah Herra! Kaiken sinun vanhurskautes tähden kääntyköön nyt sinun vihas ja hirmuisuutes pois sinun kaupungistas Jerusalemista ja sinun pyhästä vuorestas! Sillä meidän syntimme tähden ja meidän isäimme pahain tekoin tähden häväistään Jerusalem ja sinun kansas kaikkein seassa, jotka meidän ympärillämme ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Ja nyt meidän Jumalamme, kuule palvelias rukous ja anomus, ja katso armollisesti sinun pyhäs puoleen, joka kukistettu on, Herran tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Kallista korvas, minun Jumalani ja kuule. Ja avaa silmäs ja näe, kuinka me hävitetyt olemme ja se kaupunki, joka sinun nimelläs nimitetty on. Sillä emme rukoile sinua meidän omassa vanhurskaudessamme, vaan sinun suuren laupiutes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Oi Herra, kuule. Oi Herra, ole armollinen. Oi Herra, ota vaari ja tee se ja älä viivy itse tähtes, minun Jumalani! Sillä sinun kaupunkis ja sinun kansas on sinun nimelläs nimitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Kuin minä vielä puhuin ja rukoilin ja minun syntiäni ja minun kansani Israelin syntiä tunnistin ja olin minun rukouksissani Herran minun Jumalani edessä, minun Jumalani pyhän vuoren tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Juuri silloin, kuin minä näin rukoilin, lensi äkisti minun tyköni se mies Gabriel, jonka minä ennen nähnyt olin näyssä, ja rupesi minuun ehtoouhrin ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Ja hän neuvoi minua, puhui minun kanssani ja sanoi: Daniel, nyt minä olen lähtenyt sinua neuvomaan, ettäs ymmärtäisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Sinun rukoustes alussa kävi ulos käsky, ja minä tulin sinulle ilmoittamaan, sillä sinä olet otollinen. Niin ota nyt vaari sanasta, ettäs näyn ymmärtäisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Seitsemänkymmentä viikkoa on määrätty sinun kansalles ja pyhälle kaupungilles, niin ylitse käyminen lopetetaan ja synnit peitetään ja pahat teot sovitetaan ja ijankaikkinen vanhurskaus tuodaan edes. Ja näky ja ennustus suljetaan ja se kaikkein pyhin voidellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Niin tiedä nyt ja ota vaari, että siitä ajasta kuin käsky annetaan ulos, että heidän pitää jälleen kotia palajaman ja Jerusalem rakennettaman, päämieheen Kristukseen asti, on seitsemän viikkoa. Niin myös kaksiseitsemättäkymmentä viikkoa, joina kadut ja muurit jälleen rakennetaan, vaikka surkialla ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Ja kahden viikon perästä seitsemättäkymmentä surmataan Kristus, ja ei enää ole. Ja päämiehen kansa tulee ja kukistaa kaupungin ja pyhän, niin että ne loppuvat, niinkuin virran kautta. Ja sodan loppuun asti pitää sen hävitettynä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Mutta hän monelle liiton vahvistaa yhdessä viikossa. Ja puolessa viikossa lakkauttaa uhrin ja ruokauhrin. Ja siipien tykönä seisoo hävityksen julmuus. Ja on päätetty, että se loppuan asti pitää hävitetty oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Kolmantena Koreksen, Persian kuninkaan vuonna, ilmoitettiin Danielille, joka myös Belsatsariksi kutsuttiin, totinen asia suuresta sodasta. Ja hän ymmärsi sen asian, ja ymmärrys oli hänellä näyssä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Siihen aikaan murehdin minä Daniel kolme viikkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'En minä syönyt mitään herkullista ruokaa. Liha ja viina ei tullut minun suuhuni, enkä ollenkaan voidellut itsiäni siihen asti kuin kolme viikkoa loppuneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Neljäntenä päivänä kolmattakymmentä ensimäisessä kuussa olin minä sen suuren Hiddekelin virran tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Ja nostin silmäni ja näin ja katso, siinä seisoi yksi mies liinaisissa vaatteissa, ja kultainen vyö oli hänen suolissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Hänen ruumiinsa oli niinkuin turkos, hänen kasvonsa kuin pitkäisen tuli, hänen silmänsä niinkuin tulisoitot, hänen käsivartensa ja jalkansa niinkuin kiiltävä vaski, ja hänen puheensa ääni niinkuin suuri hyminä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Ja minä Daniel näin sen näyn yksinäni, ja ne miehet, jotka minun tykönäni olivat, ei sitä nähneet. Kuitenkin tuli suuri pelko heidän päällensä, että he pakenivat ja lymyttivät heitänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Ja minä jäin yksinäni ja näin tämän suuren näyn, ja ei minuun mitään väkeä jäänyt, ja minä tulin sangen rumaksi, ja ei minussa enää väkeä ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Ja minä kuulin hänen puheensa äänen. Ja kuin minä kuulin hänen puheensa äänen, putosin minä näännyksiin kasvoilleni, ja minun kasvoni olivat maahan päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Ja katso, yksi käsi tarttui minuun ja autti minua ylös polvilleni ja minun kätteni päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Ja sanoi minulle: Daniel, sinä otollinen mies. Ota näistä sanoista vaari, joita minä sinun kanssas puhun ja ojenna itses seisomaan, sillä minä olen sinun tykös nyt lähetetty. Ja kuin hän tämän sanan minun kanssani puhui, ojensin minä itseni ja vapisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Ja hän sanoi minulle: Älä pelkää Daniel, sillä siitä ensimäisestä päivästä, kuin sinä sydämestäs pyysit tietää ja vaivasit sinuas sinun Jumalas edessä, ovat sinun sanas kuullut. Ja minä olen tullut sinun sanais tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Mutta Persian valtakunnan päämies on ollut minua vastaan yhden päivän kolmattakymmentä. Ja katso; Mikael, yksi niistä ylimmäisistä päämiehistä, tuli minun avukseni, niin minä pysyin siellä Persian kuningasten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Mutta nyt minä tulen neuvomaan sinua, kuinka sinun kansalles viimeisinä aikoina tapahtuu, sillä näky pitää tapahtuman hetken ajan perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Ja kuin hän näitä minun kanssani puhui, käänsin minä kasvoni maahan päin ja olin ääneti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Ja katso, yksi ihmisen muotoinen rupesi minun huuliini, niin minä avasin suuni ja puhuin ja sanoin sille, joka seisoi minun edessäni: Minun herrani, minun jäseneni vapisevat siitä näystä, ja ei minussa ole enään ensinkään väkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Ja kuinka taitaa minun herrani palvelia puhua minun herrani kanssa, ettei minussa ensinkään enää väkeä ole, eikä myös minussa enää henkeä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Niin rupesi taas minuun ihmisen muotoinen ja vahvisti minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Ja sanoi: Älä pelkää, sinä otollinen mies, rauha olkoon sinulle! Vahvista sinus ja rohkaise sinus! Ja kuin hän minun kanssani puhui, vahvistuin minä ja sanoin: Puhu minun herrani, sillä sinä olet minun vahvistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Ja hän sanoi: Tiedätkös, minkä tähden minä olen tullut sinun tykös? Nyt minä jälleen menen sotimaan Persian päämiehen kanssa. Mutta kuin minä menen pois, katso, niin tulee Grekan maan päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Kuitenkin tahdon minä sinulle ilmoittaa, mitä kirjoitettu on, että se pitää totisesti tapahtuman. Ja ei kenkään ole, joka minua auttaa häntä vastaan, vaan teidän päämiehenne Mikael!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Niin minä myös seisoin hänen kanssansa ensimäisenä Dariuksen Mediläisen vuotena, auttamassa ja vahvistamassa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Ja nyt minä ilmoitan sinulle totuuden: Katso, kolme kuningasta pitää vielä Persiassa oleman, vaan neljäs saa enemmän rikkautta, kuin kaikki muut. Ja koska hän rikkaudessansa väkeväksi tulee, nostaa hän kaikki Grekan valtakuntaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Sen perästä tulee voimallinen kuningas ja voimallisesti hallitsee. Ja mitä hän tahtoo, sen hän tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Ja kuin hän korkeimmalle joutunut on, särjetään hänen valtakuntansa ja jaetaan neljään taivaan tuuleen. Ei hänen jälkeen tulevaisillensa eikä senkaltaisella voimalla, mikä hänellä ollut on, sillä hänen valtakuntansa hävitetään, ja tulee muiden osaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Ja etelän kuningas, joka yksi hänen päämiehistänsä on, tulee voimalliseksi. Mutta häntä vastaan tulee myös yksi väkeväksi ja hallitsee, jonka valta on suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Mutta monikahtain vuotten jälkeen yhdistävät he itsensä toinen toisensa kanssa. Ja etelän kuninkaan tytär tulee pohjan kuninkaan tykö ystävyyttä tekemään. Mutta ei hän pysy käsivarren voimassa. Eikä hänen käsivartensa ole pysyväinen, vaan hän hyljätään niiden kanssa, jotka hänen tuoneet ovat ja sen kanssa, joka hänen siittänyt on ja niiden kanssa, jotka hänen hetkeksi aikaa vahvistaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Mutta vesa tulee hänen suvustansa, joka tulee sotajoukon voimalla ja menee pohjan kuninkaan vahvoihin paikkoihin ja toimittaa ja voittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Ja vie pois heidän jumalansa ja ruhtinaansa ja kalliit kappaleensa hopian ja kullan Egyptiin ja menestyy monikahdat vuodet pohjan kuningasta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Ja kuin etelän kuningas on vaeltanut hänen valtakuntansa lävitse, palajaa hän omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Vaan hänen poikansa vihastuvat ja kokoovat suuren sotajoukon, ja yksi tulee ja menee edeskäsin niinkuin virta ja taas kehoittaa muut vihaan valtakuntaansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Silloin julmistuu etelän kuningas ja menee ulos ja sotii pohjan kuningasta vastaan ja kokoo niin suuren joukon, että toinen joukko hänen käsiinsä annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Ja hän vie pois sen suuren joukon ja paisuttaa sydämensä, että hän on lyönyt niin monta tuhatta maahan. Mutta ei hän siitä väkevämmäksi tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Sillä pohjan kuningas tulee jälleen ja kokoo suuremman joukon kuin entinen oli. Ja monikahtain vuotten perästä tulee hän kaiketi suuren sotajoukon ja paljon tavaran kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Ja siihen aikaan asettaa moni itsensä etelän kuningasta vastaan. Korottavat myös muutamat huikentelevaiset sinun kansastas itsensä ja täyttävät näyn ja lankeevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Niin pohjan kuningas tulee ja tekee vallit ja voittaa vahvat kaupungit ja etelän käsivarret. Ja hänen paras väkensä ei voi seisoa eikä ole yhtään voimaa vastaan seisoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Vaan hän, kuin hän tulee hänen tykönsä, tekee tahtonsa jälkeen. Ja ei kenkään taida seisoa hänen edessänsä. Ja hän tulee myös siihen ihanaiseen maahan ja hävittää sen kätensä kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Ja kääntää kasvonsa tullaksensa kaiken valtakuntansa voimalla. Mutta hän sopii hänen kanssansa ja antaa tyttärensä hänelle emännäksi, että hän hänen hävittäis. Mutta ei se menesty hänelle, eikä siitä mitään tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Sitte kääntää hän itsensä luotoja vastaan ja monta niistä voittaa. Vaan päämies opettaa hänen häpiällä lakkaamaan, ettei hän häntä enää häpäisisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Ja niin hän jälleen palajaa maansa linnoihin ja loukkaa itsensä ja lankee, ettei häntä enään löydetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Ja hänen siaansa tulee se, joka vaatian antaa käydä ympäri valtakunnalle kunniaksi. Mutta muutamain päiväin perästä hän särjetään; ei kuitenkaan vihan eikä sodan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Hänen siaansa tulee kelvotoin mies, jolle kuninkaallinen kunnia ei ollut aiottu. Hän tulee ja menestyy ja saa valtakunnan makeilla sanoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Ja käsivarret, jotka niinkuin virta juoksevat, hänen edessänsä virralla voitetaan ja särjetään. Niin myös se päämies, jonka kanssa liitto tehty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Sillä sittekuin hän hänen kanssansa itsensä yhdistänyt on, tekee hän kavalasti häntä vastaan ja menee ylös ja vähällä väellä itsensä vahvistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Ja hän menestyy, että hän parhaisiin maan kaupunkeihin tuleva on ja niitä tekee, joita ei hänen isänsä eikä esivanhempansa tehdä taitaneet. Heidän ryöstämisensä, saaliinsa ja tavaransa hän hajoittaa ja ajattelee juoniansa heidän linnojansa vastaan kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Ja hän kehoittaa voimansa ja sydämensä etelän kuningasta vastaan suurella sotajoukolla. Silloin etelän kuningas tulee kehoitetuksi sotaan suuren, väkevän sotajoukon kanssa. Mutta ei hän voi pysyä, sillä häntä vastaan pidetään juonia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ja juuri ne, jotka hänen leipäänsä syövät, auttavat häntä turmelukseen ja hänen joukkoansa sortamaan, että sangen paljon lyödyksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Ja molempain kuningasten sydän ajattelee, kuinka he toinen toisellensa vahinkoa tekisivät. Ja yhden pöydän tykönä petollisesti toinen toisensa kanssa puhuvat, vaan ei se menesty, sillä loppu on vielä toiseksi ajaksi määrätty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Ja hän menee taas kotiansa suurella tavaralla, ja asettaa sydämensä sitä pyhää liittoa vastaan. Siinä hän jotakin toimittaa ja niin hän menee kotia omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Määrätyllä ajalla menee hän jälleen etelään päin, mutta ei hänelle menesty toisella erällä, niinkuin ensimäisellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Sillä Kittimistä tulevat haahdet häntä vastaan, niin että hän epäilee ja palajaa ja vihastuu sitä pyhää liittoa vastaan. Ja menestyy ja kääntää itsensä ja suostuu niihin, jotka pyhän liiton hylkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Ja hänen käsivartensa pitää hänen puolestansa seisoman. Ne saastuttavat pyhän vahvistuksen ja saattavat pois jokapäiväisen uhrin ja nostavat hävityksen kauhistuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Ja hän saattaa liiton rikkojat ulkokullatuksi makeilla sanoilla. Mutta se kansa, joka Jumalansa tuntee, rohkaisee itsensä ja menestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Ja ne ymmärtäväiset kansan seassa opettavat monta. Sentähden heitä vainotaan miekalla, tulella, vankiudella ja ryöstämisellä kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Ja kuin he niin kaatuvat, tapahtuu heille kuitenkin vähä apua. Mutta monta menevät heidän tykönsä petollisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Ja ymmärtäväisistä muutamat lankeevat, että he koeteltaisiin, puhtaaksi ja selkiäksi tulisivat siihenasti, että loppu tulee, sillä se viipyy vielä määrättyyn aikaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Ja kuningas tekee, mitä hän tahtoo ja korottaa itsensä ja ylentää itsensä kaikkia vastaan, mikä Jumala on. Ja puhuu hirmuisesti jumalain Jumalaa vastaan. Ja se on hänelle menestyvä siihenasti kuin viha täytetään, sillä se on päätetty, kuinka kauvan se on oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Isäinsä Jumalaa ei hän tottele, eikä vaimoin rakkautta. Eli ei yhdestäkään Jumalasta lukua pidä, sillä kaikkia vastaan hän itsensä korottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Mutta jumalaansa Maosimia hän palvelee paikallansa, sitä jumalaa, josta ei hänen isänsä mitään tietäneet, pitää hänen kunnioittaman kullalla, hopialla, kalliilla kivillä ja kauniilla kaluilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Ja hän on niille, jotka häntä auttavat Maosimia vahvistamaan, sen muukalaisen jumalan kanssa, jonka hän valinnut on, suuren kunnian tekevä. Ja asettaa heitä monen herraksi ja jakaa heille maan palkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Ja lopun ajalla pitää etelän kuninkaan hänen kanssansa puskeleman. Ja pohjoisen kuninkaan pitää äkisti karkaaman häntä vastaan rattailla, ratsasmiehillä ja monella haahdella. Ja hänen pitää maakuntiin sisälle menemän ja haaskaaman ja vaeltaman lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Ja ihanaan maahan tuleman, ja monta pitää lankeeman. Mutta nämät pitää hänen kädestänsä pääsemän: Edom, Moab ja Ammonin lasten esikoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Ja hänen pitää kätensä maakuntiin ojentaman ja ei Egyptinkään maan pidä häneltä pääsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Vaan hänen pitää omistaman itsellensä kullan ja hopian ja kaiken Egyptin tavaran. Lybian ja Etiopian pitää häntä seuraaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Mutta sanoma idästä ja pohjasta pitää häntä peljättämän. Ja hän käy ulos suuressa vihassa monta kadottamaan ja hukuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Ja hänen pitää majansa asettaman kahden meren välille, sen ihanan pyhän vuoren tykö siihen asti kuin hänen loppunsa tulee, ja ei kenkään häntä auta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Silloin nousee suuri päämies Mikael, joka sinun kansas lasten edessä seisoo, sillä surkia aika on tuleva, jonka kaltaista ei ikänä ole ollut sittekuin ihmiset rupesivat olemaan, hamaan tähän aikaan asti. Sillä ajalla sinun kansas vapahdetaan. Kaikki, jotka kirjassa kirjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Ja monta, jotka maan tomussa makaavat, heräävät, muutamat ijankaikkiseen elämään, ja muutamat ijankaikkiseen pilkkaan ja häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Mutta opettajat paistavat, niinkuin taivaan kirkkaus, ja jotka monta opettavat vanhurskauteen, niinkuin tähdet alati ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Ja sinä Daniel, peitä nämät sanat ja sulje kirjaan hamaan viimeiseen aikaan asti. Siloin pitää sen tykö monta tuleman ja suuren ymmärryksen löytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Ja minä Daniel näin ja katso, kaksi muuta seisoi siellä, toinen tällä virran reunalla ja toinen toisella virran reunalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Ja hän sanoi sille miehelle, joka oli liinaisilla vaatteilla puetettu, joka seisoi ylempänä virtaa: Koska näiden ihmetten loppu tulee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Niin minä otin hänestä vaarin, joka liinaisilla vaatteilla puetettu oli, joka seisoi ylempänä virtaa. Ja hän nosti oikian ja vasemman kätensä taivaasen päin ja vannoi sen kautta, joka ijankaikkisesti elää, että sen pitää ajan, ja muutamat ajat ja puolen aikaa viipymän. Ja kuin pyhän kansan hajoitus saa lopun, silloin kaikki nämät tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Minä tosin kuulin tämän, vaan en minä ymmärtänyt. Ja minä sanoin: Herra, mitä näiden lopulla tapahtunee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Mutta hän sanoi: Mene Daniel, sillä se on peitetty ja suljettu hamaan viimeiseen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Monta puhdistetaan, kirkastetaan ja koetellaan, mutta jumalattomat pitävät jumalattoman menon ja jumalattomat ei näitä tottele, mutta ymmärtäväiset ottavat näistä vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Ja siitä ajasta, kuin se jokapäiväinen uhri on otettu pois ja hävityksen kauhistus sinne pannaan, on tuhannen kaksisataa ja yhdeksänkymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Autuas on, joka odottaa ja ulottuu tuhanteen kolmeensataan ja viiteen päivään neljättäkymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Mutta sinä mene pois, siihen asti kuin loppu tulee ja lepää, ettäs nousisit sinun osaas päiväin lopulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Tämä on Herran sana, joka tapahtui Hosealle, Beerin pojalle, Ussian, Jotamin, Ahaksen, Hiskian, Juudan kuningasten ajalla, ja Jerobeamin Joaksen pojan, Israelin kuninkaan ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Kuin Herra rupesi ensisti Hosean kautta puhumaan, sanoi Herra Hosealle: Mene, ota portto aviokses, ja porton lapset; sillä maakunta karkaa pois Herralta huoruuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Ja hän meni ja otti Gomerin, Diblaimin tyttären, joka tuli raskaaksi, ja synnytti hänelle pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Ja Herra sanoi hänelle: Nimitä häntä Jisreeliksi; sillä vielä on vähän aikaa, ja minä tahdon etsiä veren viat Jisreelissä, Jehun huoneen päälle, ja lopettaa Israelin huoneen valtakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Ja siihen aikaan pitää tapahtuman, että minä tahdon rikkoa Israelin joutsen Jisreelin laaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Ja hän taas tuli raskaaksi ja synnytti tyttären. Ja hän sanoi hänelle: Nimitä se Loryhhamaksi; sillä en minä enää armahda Israelin huonetta, mutta tahdon heidät peräti heittää pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Juudan huonetta tahdon minä kuitenkin armahtaa, ja auttaa heitä Herran, heidän Jumalansa kautta; ja en minä tahdo heitä auttaa joutsella, miekalla, sodalla, oriilla taikka ratsasmiehillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Ja kuin hän oli Loryhhaman vieroittanut, niin hän taas siitti ja synnytti pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Ja hän sanoi: Nimitä häntä Loammiksi; sillä ette ole minun kansani, niin en minäkään ole teidän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Mutta Israelin lasten luku pitää oleman niinkuin meren hiekka, jota ei mitata eikä luettaa taideta; ja pitää tapahtuman, että siinä paikassa, missä heille sanottiin: Ette ole minun kansani, pitää heille sanottaman: Te elävän Jumalan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Sillä Juudan lapset ja Israelin lapset pitää kokoontuman ja pitämän heitänsä yhden pään alla, ja menemän ylös pois maasta; sillä Jisreelin päivä pitää suuri oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Sanokaat teidän veljillenne: He ovat minun kansani, ja teidän sisarillenne: He ovat armossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Riidelkäät teidän äitinne kanssa, riidelkäät, sillä ei hän ole minun emäntäni, enkä minä ole hänen miehensä, että hän heittäis pois haureutensa kasvoistansa ja huoruutensa rinnoistansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Etten minä häntä alasti riisuisi, ja panisi häntä niinkuin hän syntyissänsä oli, ja panisi myös häntä niinkuin hävitettyä ja niinkuin karkiaa maata, enkä janoon häntä kuolettaisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Ja en armahtaisi hänen lapsiansa; sillä he ovat huoran lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Sillä heidän äitinsä on huorin tehnyt, ja se, joka heidät siitti,käytti itsensä häpiällisesti, ja sanoi: Minä tahdon juosta rakastajaini perässä, jotka minulle antavat leipää, vettä, villoja, pellavia, öljyä ja juomaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Sentähden katso, minä aitaan sinun ties orjantappuroilla ja panen aidan eteen, ettei hän löytäisi polkujansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Ja kuin hän juoksee rakastajainsa perässä, niin ei hänen pidä heitä käsittämän, eikä löytämän, kuin hän heitä etsii; ja hänen pitää sanoman: Minä menen ja palajan entisen mieheni tykö, sillä silloin oli minun parempi kuin nyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Ja ei hän tahdo tietää minua siksi, joka hänelle annoin jyviä, viinaa ja öljyä, ja että minä annoin hänelle paljon hopiaa ja kultaa, josta he Baalimit tekivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Sentähden minä palajan ja otan aikanansa jälleen minun jyväni, ja minun viinani ajallansa, ja otan pois villani ja pellavani, joilla hän häpiänsä peittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Ja minä tahdon paljastaa hänen häpiänsä, hänen rakastajainsa silmäin eteen; ja ei pidä kenenkään häntä minun käsistäni päästämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Ja minä lakkautan kaiken hänen ilonsa, juhlansa, uuden kuunsa, lepopäivänsä ja kaikki hänen pyhäpäivänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Minä hävitän myös hänen viinapuunsa ja fikunapuunsa, että hän sanoi: Se on minun palkkani, jonka minun rakastajani minulle antaneet ovat; minä teen niistä metsän, että metsän pedot ne syövät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Juuri niin etsin minä häntä Baalimin päivinä, joina hän heille savu-uhria sytytti, ja kaunisti itsensä kultalehdillä ja kaulakaunistuksella, ja juoksi rakastajainsa perässä; ja niin unhotti minun, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Sentähden katso, minä tahdon häntä houkutella, viedä hänen korpeen ja puhua suloisesti hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Silloin annan minä hänelle hänen viinamäkensä ja Akorin laakson, ja tahdon toivon avata; siellä hän on lauleskeleva, niinkuin nuorella ijällänsä ja niinkuin sinä päivänä, jona hän Egyptin maalta läksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Ja sinä päivänä pitää tapahtuman, sanoo Herra, ettäs minun kutsut miehekses, ja et enään minua kutsu Baalimiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Sillä minä tahdon Baalimin nimet ottaa pois hänen suustansa, niin ettei kenenkään pidä sitä nimeä enään muistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Vaan minä tahdon tehdä heille sillä ajalla liiton, petoin kanssa kedolla, lintuin kanssa taivaan alla ja matoin kanssa maan päällä; ja tahdon ottaa pois joutsen, miekan ja sodan maalta, ja annan heidän asua turvallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Minä kihlaan sinun itselleni ijankaikkisesti; ja minä kihlaan sinun itselleni vanhurskaudessa, tuomiossa, armossa ja laupiudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Minä kihlaan tosin sinun itselleni uskossa, ja sinun pitää Herran tunteman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Sillä ajalla, sanoo Herra; tahdon minä kuulla, minä tahdon taivaasta kuulla, ja taivaan pitää maata kuuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Mutta maan pitää kuuleman jyviä, viinaa ja öljyä, ja niiden pitää Jisreeliä kuuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Ja minä tahdon sen itselleni pitää siemeneksi maan päälle, ja tahdon sitä armahtaa, jota ei ole armahdettu. Ja sanon hänelle, joka ei ollut minun kansani: Sinä olet minun kansani, ja hänen pitää sanoman: Sinä olet minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Ja Herra sanoi minulle: Mene vielä ja rakasta salavuoteista vaimoa ja porttoa, niinkuin Herra rakastaa Israelin lapsia, jotka kuitenkin kääntyivät muukalaisten jumalain tykö, ja rakastavat viinaleiliä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Ja minä sovin hänen kanssansa, viiteentoistakymmeneen hopiapenninkiin ja puoleentoista homeriin ohria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Ja sanoin hänelle: Pidä sinus minun tyköni monta päivää, ja älä huorin tee ja älä toiseen ryhdy; niin minä tahdon myös sinun tykös itseni pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Sentähden että Israelin lapset pitää monta päivää ilman kuningasta, ilman päämiestä, ilman uhria, ilman alttaria, ilman päällishametta ja ilman epäjumalain kuvia olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Sitte Israelin lapset palajavat ja Herraa heidän Jumalaansa etsivät, ja Davidia kuningastansa; ja heidän pitää pelvolla tuleman Herran ja hänen hyvyytensä tykö viimeisillä ajoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Kuulkaat Herran sanaa, te Israelin lapset! Sillä Herralla on syy niitä nuhdella, jotka maassa asuvat; sentähden ettei totuutta, eikä laupiutta, eikä Jumalan tuntoa ole maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Mutta valapattoisuus, valhe, murha, varkaus ja huoruus, ne ovat vallan saaneet, ja yksi veren vika tapahtuu toisen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Sentähden pitää maakunnan surkiana oleman, ja kaikki, jotka siinä asuvat, pitää nääntymän, ynnä eläinten kanssa kedolla ja taivaan lintuin kanssa; ja kalat meressä pitää myös hukkaantuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Tosin ei saa kenkään nuhdella eikä rangaista ketään; sillä sinun kansas on niinkuin pappein nuhtelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Sentähden pitää sinun päivällä lankeeman, ja propheta sinun kanssas yöllä; ja minä tahdon äitis hukuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Minun kansani on turmeltu, ettei heillä ole ymmärrystä; että sinä hylkäsit ymmärryksen, tahdon minä myös sinun hyljätä, ettei sinun pidä enään minun pappini oleman: ja sinä unohdit sinun Jumalas lain, sentähden tahdon minä myös unohtaa sinunkin lapses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Jota enempi heitä on, sitä enemmin he tekevät syntiä minua vastaan; sentähden teen minä heidän kunniansa häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'He syövät minun kansani syntiuhria ja himoitsevat heidän syntejänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Kansalle pitää niinkuin papeillekin tapahtuman; sillä minä tahdon heidän pahat tekonsa etsiä, ja kostan heille niinkuin he ansainneet ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Niin että he syövät, ja ei tule ravituksi; he tekevät huoruutta, ja ei heidän pidä menestymän; sillä he ovat hyljänneet Herran, ja ei totelleet häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Huoruus, viina ja väkevä juoma hulluksi saattavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Minun kansani kysyy neuvoa puulta ja hänen sauvansa saarnaa hänelle; sillä huoruuden henki vietteli heitä, niin että he tekivät huorin Jumalaansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Vuorten kukkuloilla he uhraavat, ja korkeuksilla he suitsuttavat, tammien alla, haapain ja saarnien alla, että ne antavat suloisen varjon; sentähden tulevat teidän tyttärenne portoiksi ja teidän morsiamenne huoraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'En minä tahdo etsiä teidän tyttäriänne, koska he salavuoteudessa elävät, enkä teidän morsiamianne, koska he huorin tekevät; sillä he eroittavat itsensä huorain sekaan, ja porttoin kanssa uhraavat; ja se ymmärtämätöin kansa saa haavoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Israel, jos sinä kuitenkin tahdot huorin tehdä, niin älköön Juuda sentähden vialliseksi tulko! Älkäät menkö Gilgaliin, ja älkäät tulko ylös Betaveniin, ja älkäät vannoko: Niin totta kuin Herra elää!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Sillä Israel on hillimätöin niinkuin kiiliväinen lehmä; niin Herra on myös kaitseva heitä, kuin lammasta avarassa paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Sillä Ephraim on suostunut epäjumaliin; anna hänen mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'He ovat itsensä juopumiseen ja huoruuteen laskeneet, ja heidän valtamiehensä rakastavat antimia häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Tuulispään pitää siivillänsä heidät sidottuina ajaman pois, ja heidän pitää häpiään tuleman uhreistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Kuulkaat siis papit, ja Israelin huone, ottakaat vaari, ja ota korviis sinä kuninkaan huone; sillä tuomio pitää tuleman teidän päällenne, te, jotka Mitspassa paulan ja levitetyn verkon Taborissa virittäneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Ne luopuvaiset teurastavat sangen paljon; sentähden tulee minun heitä kaikkia rangaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Kyllä minä tunnen Ephraimin, ja ei Israel ole minun edestäni peitetty; että Ephraim on nyt portto ja Israel saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Ei he ajattele palata Jumalansa tykö; sillä huoruuden henki on heidän sydämessänsä, ja ei he tottele Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Sentähden pitää Israelin ylpeys hänen kasvoinsa edessä nöyryytettämän; ja Israel ja Ephraim pitää pahain tekoinsa tähden lankeeman; Juudan pitää myös heidän kanssansa lankeeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'He menevät sitte etsimään Herraa lampaillansa ja karjallansa, vaan ei heidän pidä sittekään häntä löytämän; hän on itsensä heiltä kääntänyt pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'He ovat rikkoneet Herraa vastaan ja synnyttäneet vieraita lapsia; sentähden pitää myös uuden kuun syömän heitä ynnä heidän osainsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Soittakaat basunaa Gibeassa, soittakaat torvea Ramassa, huutakaat Betavenissa: Sinun jälkees Benjamin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Sillä Ephraimin pitää rangaistuksen päivänä kylmillä oleman; josta minä Israelin sukukuntia uskollisesti olen neuvonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Juudan päämiehet ovat niinkuin rajan siirtäjät; sentähden tahdon minä vihani vuodattaa heidän päällensä, niinkuin veden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Ephraim kärsii väkivaltaa ja ahdistetaan, joka hänelle oikein tapahtuu; sillä hän antoi itsensä (ihmisten) käskyihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Minä olin Ephraimille niinkuin koi, ja Juudan huoneelle turmelus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Mutta kuin Ephraim tunsi sairautensa ja Juuda haavansa, niin Ephraim meni Assyriaan, ja lähetti kuninkaan Jarebin tykö; vaan ei hän voinut teitä auttaa, eikä parantaa teidän haavojanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Sillä minä olen Ephraimille niinkuin julma jalopeura, ja Juudan huoneelle niinkuin nuori jalopeura. Minä, minä itse heitä raatelen, ja menen pois, minä vien heidät pois, ja ei kenkään heitä voi pelastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Minä menen ja palajan taas sijalleni, siihenasti kuin he syntinsä tuntevat, ja minun kasvojani etsivät; kuin heille pahoin käy, niin heidän pitää varhain minua etsimän (ja sanoman:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Kuulkaat ja palatkaamme Herran tykö; sillä hän on meitä repinyt, hän myös meidät parantaa; hän on meitä lyönyt, hän myös meitä sitoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Hän tekee meitä eläväksi kahden päivän perästä; kolmantena päivänä hän meitä virvoittaa, niin että me saamme elää hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Niin me otamme siitä vaarin, ja sitä pyytelemme, että me Herran tuntisimme; sillä hän koittaa niinkuin kaunis aamurusko, ja hän tulee meille niinkuin sade, niinkuin ehtoosade aikanansa maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Mitä minun pitäis sinulle Ephraim tekemän? Mitä minun pitäis sinulle Juuda tekemän? Teidän jumalisuutenne on niinkuin aamullinen pilvi, ja niinkuin varhainen kaste, joka pois raukee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Sentähden vuoleskelen minä heitä prophetain kautta, ja kuoletan heitä minun suuni sanoilla, että sinun Jumalas sanat ilmaantuisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Sillä minulle kelpaa armo ja ei uhri; Jumalan tunto ja ei polttouhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Mutta he käyvät sen liiton ylitse niinkuin Adam; siinä he ovat petollisesti tehneet minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Sillä Gilead on kaupunki vääryyttä ja veren vikoja täynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Papit ovat joukkoinensa niinkuin ryövärit, jotka väijyvät; he murhaavat Sikemin tiellä; sillä he tekevät, mitä he tahtovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Minä näen Israelin huoneessa, jota minä kauhistun; sillä Ephraim tekee huorin, ja Israel saastuttaa itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Juuda on myös sinulle pannut elon ajan, kuin minä kansani vankiuden palautan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Kuin minä Israelin parantaa tahdon, niin äsken nähdään Ephraimin vääryys ja Samarian pahuus; sillä he tekevät petollisuutta: varas menee sisälle, ja ryövärit ulkona ryöstävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Ja ei he kuitenkaan ajattele sydämessänsä, että minä muistan kaiken heidän pahuutensa; nyt ovat heidän työnsä heidän ympärillänsä, ja ovat julki minun kasvoini edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'He ilahuttavat kuninkaan pahuudellansa ja päämiehet valheellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Ja ovat kaikki huorintekiät, niinkuin pätsi, jonka leipoja lämmittää; joka lakkaa valvomasta, sitte kuin hän on taikinan sotkunut, siihen asti kuin se happanee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Tänäpänä on meidän kuninkaamme juhla, ja päämiehet ovat sairaaksi tulleet viinasta; hän kutsuttaa pilkkaajat tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Sillä heidän sydämensä on palava niinkuin pätsi, kuin he väijyvät; mutta heidän leipojansa makaa kaiken yötä, ja palaa aamulla niinkuin tulen liekki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'He ovat kaikki palavat niinkuin pätsi: he syövät tuomarinsa; kaikki heidän kuninkaansa lankeevat; ei ole yhtäkään heissä, joka minua avuksensa huutaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Ephraim sekoittaa itsensä kansoihin: Ephraim on niinkuin kyrsä, jota ei kenkään käännä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Vaan muukalaiset syövät hänen voimansa, jota ei hän kuitenkaan tottele. Hän on myös harmaat karvat saanut, ei hän sittekään sitä huoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Ja Israelin ylpeys nöyryytetään heidän silmäinsä edessä; vaan ei he käännä itsiänsä Herran Jumalansa tykö, eikä hänestä pidä lukua näissä kaikissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Sillä Ephraim on niinkuin hullu kyhkyinen, joka ei mitään huomaitse; he avuksensa huutavat Egyptiä, he juoksevat Assuriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Mutta kuhunka ikänä he juoksentelevat, heitän minä verkkoni heidän päällensä, ja tempaan alas niinkuin linnut taivaan alta. Minä tahdon heitä rangaista, niinkuin he seurakunnissansa kuulleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Voi heitä, että he minusta luopuneet ovat! Heidän täytyy turmeltua; sillä he ovat minua vastaan rikkoneet. Minä olisin heidät kyllä päästänyt, jollei he olisi valhetta opettaneet minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Niin ei he myös minua huuda sydämestänsä, vaan ulvovat vuoteissansa. He kokoontuvat jyväin ja viinan tähden, ja ovat minulle kovakorvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Minä kuritan heitä ja vahvistan heidän käsivartensa; mutta he ajattelevat pahaa minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'He palajavat, mutta ei Korkeimman tykö, vaan ovat niinkuin hellinnyt joutsi; sentähden pitää heidän päämiehensä miekan kautta lankeeman, heidän uhkauksensa tähden: Tämä on heidän pilkkansa Egyptin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Huuda selkiästi niinkuin basuna (ja sano): Hän tulee jo Herran huoneen ylitse niinkuin kotka, että he ovat minun liittoni rikkoneet, ja ovat minun laistani luopuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Niin heidän pitää minua huutaman: Sinä olet minun Jumalani; me Israel tunnemme sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israel hylkää hyvän; sentähden pitää vihollisen heitä vaivaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'He asettavat kuninkaita ilman minua, he panevat päämiehiä ilman minun tietämättäni; hopiastansa ja kullastansa tekevät he epäjumalia, että he juuri nopiasti häviäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Sinun vasikkas, Samaria, sysää sinun pois; minun vihani on julmistunut; ei se taida kauvan olla, heitä pitää rangaistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Sillä se on myös tullut Israelista, jonka seppä on tehnyt, ja ei se ole Jumala: Sentähden pitää Samarian vasikka tomuksi tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Sillä he kylvivät tuulen; ja heidän pitää jälleen tuulispään niittämän; ei heidän siemenensä pidä tuleman ylös, eikä hedelmänsä jauhoja antaman; ja jos hän vielä antais, niin muukalaiset pitää ne syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Israel tulee syödyksi; pakanat pitävät hänen nyt kelvottomana astiana;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Että he juoksivat ylös Assurin tykö, niinkuin yksinäinen metsä-aasi: Ephraim palkkaa itsellensä lahjoilla rakastajia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Ja että he lahjoja lähettävät pakanoille, niin tahdon minä nyt heitä koota; ja heidän pitää kuninkaan ja päämiesten kuormaan pian suuttuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Sillä Ephraim on tehnyt monta alttaria syntiä tehdäksensä; niin pitää myös alttarit hänelle synniksi luettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Vaikka minä paljon heille minun laistani kirjoitan; niin he lukevat sen kuitenkin muukalaiseksi opiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Ehkä he nyt paljon uhraavat, ja lihaa tuovat edes ja syövät, niin ei se kuitenkaan ole Herralle otollinen; mutta hän tahtoo muistaa heidän pahuutensa, ja heidän syntinsä etsiä, jotka Egyptiin kääntyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Israel unhotti Luojansa, ja rakensi templiä, ja Juuda teki myös monta vahvaa kaupunkia; mutta minä lasken tulen hänen kaupunkeihinsa, joka hänen huoneensa polttaman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Älä riemuitse, Israel, äläkä öykkää niinkuin kansat; sillä sinä olet huorin tehnyt sinun Jumalaas vastaan, sinä etsit porton palkkaa kaikkein jyväluvain tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Sentähden ei luvat eikä kuurnat pidä heitä elättämän, eikä viinan pidä hänelle menestymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ja ei heidän pidä asuman Herran maalla; mutta Ephraimin pitää jälleen menemän Egyptiin, ja pitää Assyriassa saastaista syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Jossa ei taideta Herralle viinasta juomauhria tehdä, eli muuta tehdä hänen mielensä nouteeksi; heidän uhrinsa pitää oleman niinkuin murheellisten leipä, josta kaikki saastuttavat itsensä, jotka sitä syövät; sillä heidän leipänsä pitää heidän itse syömän, ja ei sitä pidä Herran huoneesen vietämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Mitä te silloin tahdotte vuosikauden pyhinä ja Herran juhlapäivinä tehdä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Sillä katso, heidän pitää raateliaa pakeneman; Egyptin pitää heidät kokooman, ja Moph pitää heidät hautaaman. Nukulaiset pitää siellä kasvaman, jossa nyt heidän rakkaan epäjumalansa hopiat ovat, ja orjantappurat pitää oleman heidän majoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Etsikon aika on tullut, ja kostamisen aika on tullut, jonka Israelin pitää kyllä tunteman: Prophetat ovat tomppelit, ja kerskaajat ovat mielipuolet, sinun suurten pahain tekois tähden ja suuren vastahakoisuuden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Vartiat Ephraimissa pitivät heitänsä hetken minun Jumalani tykö; mutta nyt he ovat prophetat, jotka hänelle paulan kaikilla hänen teillänsä panevat, sillä vainollisella epäjumalan palveluksella heidän Jumalansa huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'He ovat syvästi itsensä turmelleet, niinkuin Gibean aikana; sentähden pitää hänen heidän pahat tekonsa muistaman, ja heidän syntinsä etsimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Minä löysin Israelin niinkuin viinamarjat korvessa, ja näin teidän isänne niinkuin fikunapuussa uutisfikunat; mutta he menivät sitte Baalpeorin tykö, ja lupasivat heitänsä sille häpiälliselle epäjumalalle, ja tulivat niin julmaksi kuin se, jota he rakastivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Sentähden pitää Ephraimin kunnian lentämän pois niinkuin lintu; niin ettei heidän pidä synnyttämän, eikä kantaman eli siittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Ja ehkä vielä lapsiansa kasvattaisivat, niin minä tahdon kuitenkin heidät lapsettomaksi tehdä, ettei heidän pidä ensinkään kansa oleman. Voi myös heitä, kuin minä heistä luovun!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Ephraim, jonka minä näen, on istutettu ja kaunis niinkuin Tyro; mutta hänen täytyy nyt surmaajalle lapsensa antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Herra, anna heille; mutta mitäs tahdot heille antaa? Anna heille hedelmätöin kohtu ja tyhjät nisät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Kaikki heidän pahuutensa tapahtuu Gilgalissa; siellä minä heitä vihaan, ja ajan heidät pois minun huoneestani, heidän pahan menonsa tähden, enkä tahdo heitä enään rakastaa; sillä kaikki heidän päämiehensä ovat langenneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Ephraim on lyöty; hänen juurensa ovat kuivettuneet, ettei ne enään taida hedelmää kantaa; ja vaikka he vielä kantaisivat, niin minä tahdon kuitenkin heidän ruumiinsa ihanat hedelmät kuolettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Minun Jumalani on heittävä heidät pois, ettei he häntä kuulleet; ja heidän pitää pakanain seassa kulkiana vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel on tyhjä viinapuu, hedelmän hän itsellensä pitää: Ja niin paljo kuin hänellä hedelmää on, niin monta alttaria hän myös tekee; siinä, jossa maa paras on, siihen he rakentavat kauniimmat kuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Heidän sydämensä on jaettu; ja he löytävät syntinsä; mutta hän tahtoo heidän alttarinsa kukistaa, ja heidän kuvansa hävittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Sillä nyt pitää heidän sanoman: Ei meillä kuningasta ole; sillä emme ole Herraa peljänneet, mitä kuninkaan pitäis meitä auttaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'He vannovat turhaan liittoa tehdessänsä; ja senkaltainen neuvo vihoittaa niinkuin myrkyllinen ruoho pellon vaoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Samarian asuvaiset pelkäävät Betavenin vasikkain tähden; sillä hänen kansansa on murehtinut häntä, ja hänen pappinsa, jotka hänen tähtensä olivat (ennen) riemuinneet, hänen kunniansa puolesta; sillä hän on viety heiltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Ja se (vasikka) on viety Assyriaan kuninkaalle Jarebille lahjaksi; niin pitää myös Ephraimin häpiään tuleman, ja Israelin pitää häpeemän neuvonsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Sillä Samarian kuningas on rauvennut niinkuin vaahto veden päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Avenin kukkulat ovat pyyhityt pois, joilla Israel on syntiä tehnyt. Ohdakkeet ja orjantappurat kasvavat heidän alttareillansa; ja heidän pitää sanoman vuorille: peittäkäät meitä, ja kukkuloille: kaatukaat meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Israel, sinä olet syntiä tehnyt hamasta Gibean ajasta; siihen myös he ovat jääneet; mutta senkaltainen sota, mikä pahoja ihmisiä vastaan Gibeassa tapahtui, ei pidä heitä käsittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Vaan minä rankaisen heitä minun mieleni jälkeen, niin että kansat pitää heidän ylitsensä kokoontuman, kuin minä heitä rankaisen heidän kahden syntinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Ephraim on vasikka, joka on tottunat mielellänsä riihtä tappamaan, ja niin minäkin tahdon käydä hänen kauniin kaulansa päällä; minä ajan Ephraimilla, Juudan pitää kyntämän, ja Jakobin itsellensä äestämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Kylväkäät teillenne vanhurskaudeksi, niittäkäät laupiudeksi, kyntäkäät teillenne kyntö; että nyt on aika Herraa etsiä, siihen asti kuin hän tulee, ja saattaa teille vanhurskauden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Te kynnätte jumalattomuutta, ja niitätte vääryyttä, ja syötte valheen hedelmiä. Että sinä turvaat omaan menoos ja sinun moneen sankariis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Niin pitää meteli nouseman sinun kansas seassa, ja kaikki sinun linnas pitää hävitettämän, niinkuin Salman hävitti Arbelin huoneen sodan aikana, ja äiti lapsinensa kuoliaaksi lyötiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Niin pitää teillekin Betelissä tapahtuman, teidän suuren pahuutenne tähden; että Israelin kuningas pitää aamulla varhain lyötämän maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Kuin Israel nuori oli, pidin minä hänen rakkaana, ja minä kutsuin Egyptistä minun poikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Mutta kuin heitä nyt kutsutaan, niin he kääntyvät pois, ja uhraavat Baalimille, ja suitsuttavat kuville.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Minä opetin Ephraimin käymään, ja talutin häntä käsivarsista, vaan nyt ei he tahdo tietää, että minä heitä parantanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Minä annoin heidän vetää ihmisen ijestä, ja käydä rakkauden ohjissa, ja minä autin heitä, otin ikeen heidän kaulastansa, ja annoin heille elatuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Ei heidän pidä palajaman Egyptin maalle, vaan Assur pitää heidän kuninkaansa oleman; sillä ei he tahdo itsiänsä kääntää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Sentähden pitää miekan tuleman heidän kaupunkinsa päälle, ja heidän salpansa tempaaman ylös, ja syömän ne, heidän neuvonsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Minun kansani väsyy kääntymästä minun puoleeni; ehkä kuinka heille saarnattaisiin, niin ei kenkään hankitse kuulemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Mitä minun pitää sinusta tekemän, Ephraim? Varjelenko minä sinua, Israel? Pitäiskö minun sinulle tekemän niinkuin Adamalle, ja asettaman sinun niinkuin Zeboimin? Mutta minun sydämelläni on toinen mieli, minun laupiuteni on ylen palava:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Etten minä tee hirmuisen vihani jälkeen, enkä palaja Ephraimia kadottamaan; sillä minä olen Jumala, ja en ihminen, ja olen Pyhä teidän keskellänne, ja en tahdo tulla kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Silloin Herraa seurataan, ja hän on kiljuva niinkuin jalopeura; ja kuin hän kiljuu, niin ne peljästyvät, jotka lännessä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Ja Egyptissä ne myös peljästyvät niinkuin lintu, ja ne Assurin maasta niinkuin kyhkyinen; ja minä tahdon heitä asettaa huoneisiinsa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Ephraimissa on joka paikassa valhe minua vastaan, ja Israelin huoneessa petos; mutta Juuda hallitsee vielä Jumalan kanssa, ja on uskollinen pyhäin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Ephraim ruokkii itsensä tuulella, ja samoo itätuulen perään, ja enentää joka päivä valhetta ja vahinkoa. He tekevät Assurin kanssa liiton, ja vievät öljyä Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'On myös Herralla riita Juudan kanssa, etsiä Jakobia hänen menonsa jälkeen, ja kostaa hänelle hänen ansionsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Hän on äitinsä kohdussa polkenut alas veljensä, ja kaikella voimallansa Jumalan kanssa taistellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Hän paineli myös enkelin kanssa ja voitti; hän itki ja rukoili häntä; Betelissä löysi hän hänen, ja siellä hän on puhunut meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Mutta se Herra on Jumala Zebaot, Herra on hänen muistonimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Niin käänny nyt sinun Jumalas tykö; tee laupius ja oikeus, ja turvaa alati sinun Jumalaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Mutta kauppamiehellä on väärä vaaka kädessä, ja pettää mielellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Ja Ephraim sanoo: Minä olen rikas, minulla on kyllä; ei yhdessäkään minun työssäni löydetä pahatekoa, joka synti olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Mutta minä olen Herra sinun Jumalas hamasta Egyptin maasta; minä annan sinun vielä majoissa asua, niinkuin juhlina tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Ja puhun prophetaille, olen myös se, joka niin monet ennustukset annan, ja prophetain kautta minuni julistan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Sillä Gileadissa on epäjumalan palvelus, ja Gilgalissa he uhraavat härkiä hukkaan, ja heillä on niin monta alttaria, kuin kuhilaita on pellolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Jakobin täytyy Syrian maahan paeta, ja Israelin täytyy palvella vaimon tähden; vaimon tähden tosin täytyy hänen karjaa kaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Mutta sitte vei Herra Israelin Egyptistä prophetan kautta, ja antoi prophetan kautta häntä korjata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Vaan Ephraim vihoittaa hänen nyt epäjumalillansa; sentähden pitää heidän verensä tuleman heidän päällensä, ja heidän Herransa on kostava heidän pilkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Kuin Ephraim puhui, niin siitä tuli pelko; hän korotti itsensä Israelissa, ja teki syntiä Baalimin kautta, ja kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Mutta nyt he vielä enemmin syntiä tekevät, ja valavat kuvia hopiastansa, ymmärryksensä jälkeen epäjumalia, joka kaikki sepän työ on; joista he saarnaavat: Joka tahtoo niiden vasikkain suuta antaa, sen pitää ihmisiä uhraaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Sentähden pitää heidän oleman niinkuin aamu-utu ja varhain lankeeva kaste, joka raukee, niinkuin akanat, jotka puhalletaan pois luvasta, ja niinkuin savu totosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Mutta minä olen Herra sinun Jumalas hamasta Egyptin maasta; ei tosin sinun pitäisi muuta jumaIaa tunteman paitsi minua, eikä yhtään vapahtajaa, vaan minua ainoaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Minä tunsin sinun korvessa, karkiassa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Mutta että he ovat ravitut, ja kyllänsä saaneet; he saivat kyllänsä ja heidän sydämensä paisui: Sentähden he minun unhottavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Minä myös tahdon olla heidän kohtaansa niinkuin jalopeura, ja tahdon heitä väijyä niinkuin pardi tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Minä tahdon heitä kohdata niinkuin karhu, jonka pojat ovat otetut pois, ja reväistä heidän paatuneen sydämensä rikki, ja tahdon heidät siellä syödä ylös, niinkuin jalopeura; metsän pedot pitää heidät rikki repimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Itse sinä olet sinun kadotukses, Israel! Vaan minussa on sinun apus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Missä on sinun kuninkaas, joka sinua taitais auttaa kaikissa sinun kaupungeissas? Ja sinun tuomaris, joista sinä sanoit: Anna minulle kuningas ja päämiehiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Minä tosin annoin sinulle kuninkaan minun vihassani, ja otan sen sinulta pois minun hirmuisuudessani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Ephraimin pahateko on sidottu kokoon, ja hänen syntinsä ovat salatut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Hänelle pitää tuleman synnyttäväisen kipu; hän on tyhmä lapsi, sillä ei hän taida sitä aikaa lasten synnyttämisessä pysyväinen olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Mutta minä tahdon heitä päästää helvetin vallasta, ja vapahtaa heitä kuolemasta. Kuolema, minä tahdon olla sinulle myrkky, helvetti, minä tahdon olla sinulle surma! Kuitenkin on se lohdutus minun silmäini edestä peitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Sillä hänen pitää veljesten vaiheella hedelmää tekemän: Herran itätuulen pitää tuleman korvesta, ja hänen kaivonsa pitää kurehtuman, ja hänen lähteensä kuivuman, sen pitää raateleman kaikkein kalleimmat kalut ja tavarat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samaria pitää autioksi tuleman, sillä hän on Jumalallensa kovakorvainen ollut; heidän pitää miekalla lankeeman, ja heidän nuoret lapsensa paiskattaman rikki, ja heidän raskaat vaimonsa pitää reväistämän rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Käänny, Israel, Herran sinun Jumalas tykö; sillä sinä olet langennut sinun pahain tekois tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Ottakaat teillenne nämät sanat, ja kääntykäät Herran tykö, ja sanokaat hänelle: Anna meille kaikki synnit anteeksi, ja tee meille hyvin, niin me uhraamme sinulle meidän huultemme mullit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Ei Assur meitä auta, emme myös tahdo enään astua orhitten päälle, emmekä sano enään meidän käsialallemme: Te olette meidän jumalamme; sillä sinun tykönäs löytää orpo armon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Niin minä taas olen parantava heidän erhetyksensä, mielelläni minä heitä rakastan; sillä minun vihani on käännetty heistä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Minä tahdon Israelille olla niinkuin kaste, että hän kukoistaa niinkuin kukkanen, ja hänen juurensa leviävät niinkuin Libanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Hänen oksansa pitää hajooman, että hän itse olis ihanainen niinkuin öljypuu, ja hänen pitää hajuaman niinkuin Libanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Ja heidän pitää taas istuman hänen varjonsa alla, ja jyvistä itsensä ravitseman, ja kukoistuman niinkuin viinapuu. Ja hänen muistonsa pitää niinkuin Libanonin viina oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Ephraim (sanokaan): Mitä minun on enää epäjumalain kanssa? Minä tahdon häntä kuulla ja katsoa; minä tahdon olla niinkuin viheriäinen honka; minussa pitää sinun hedelmäs löydettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kuka on viisas, että hän näitä ymmärtäis? Ja ymmärtäväinen, joka näitä huomaitsis? Sillä Herran tiet ovat oikiat, ja vanhurskaat vaeltavat niillä, mutta ylitsekäymärit niissä lankeevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Tämä on Herran sana, joka tapahtui Joelille Petuelin pojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Kuulkaat tätä vanhimmat, ja ottakaat korviinne kaikki maan asuvaiset; onko tämä teidän eli teidän isäinne aikana tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Sanokaat siitä teidän lapsillenne, ja antakaat teidän lastenne sitä lapsillensa sanoa, ja nekin lapset muille jälkeentulevaisillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Mitä ruohomato jättää, sen heinäsirkka syö, ja mitä heinäsirkka jättää, sen lehtimato syö, ja mitä lehtimato jättää, sen jyvämato syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Herätkäät juopuneet, ja itkekäät ja ulvokaat kaikki viinan juomarit nuoren viinan tähden; sillä se on temmattu pois teidän suustanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Sillä väkevä kansa menee pois minun maani päälle, joka on lukematoin; hänen hampaansa ovat niinkuin jalopeuran hampaat, ja syömähampaat niinkuin julmalla jalopeuralla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'He hävittivät minun viinamäkeni, ja minun fikunapuuni kaivoivat, kuorivat ja heittivät pois, että sen oksat valkiana ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Valita niinkuin neitsyt, joka säkin yllensä pukee nuoruutensa yljän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Sillä ruokauhri ja juomauhri on pois Herran huoneesta; ja papit Herran huoneesta; ja papit Herran palveliat murehtivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Pelto on hävitetty, maa on murheissansa, että jyvät ovat turmellut, viina on kuivunut pois, ja öljy puuttunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Peltomiehet katsovat huonosti, ja viinamäen miehet parkuvat nisuin ja ohrain tähden, ettei vainiossa ole mitään tuloa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Viinapuu kuivettui ja fikunapuu on lahonnut; granatipuu, palmupuu, omenapuu ja kaikki kedon puut ovat kuivettuneet; sillä ihmisten riemu on surkeudeksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Sonnustakaat teitänne ja valittakaat, te papit! parkukaat, te alttarin palveliat, menkäät (templiin), ja levätkäät, te minun Jumalani palveliat, säkeissä oli yötä; sillä ruokauhri ja juomauhri on pois teidän Jumalanne huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Pyhittäkäät paasto, kutsukaat seurakunta kokoon, ja kootkaat vanhimmat, ja kaikki maakunnan asuvaiset, Herran teidän Jumalanne huoneesen, ja huutakaat Herran tykö:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Voi, voi sitä päivää! sillä Herran päivä on juuri läsnä, ja tulee niinkuin kadotus Kaikkivaltiaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Eikö ruoka oteta pois meidän silmäimme edestä, ja meidän Jumalamme huoneesta ilo ja riemu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Siemenet mätänivät maassa, jyväaitat ovat hävitetyt, riihet ovat hajoitetut; sillä elo on kuivunut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Voi, kuinka karja huokaa, ja laumat ammuvat! ettei heillä ole laidunta, ja lammaslaumat nääntyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Herra, sinun tykös minä huudan, että kulo on polttanut laitumet korvessa, ja liekki on kaikki puut vainiossa sytyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Metsän eläimet myös sinun tykös huutavat, että vesi-ojat kuivuneet ovat, ja että kulo on polttanut laitumet korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Soittakaat basunalla Zionissa, huutakaat minun pyhällä vuorellani, vaviskaat kaikki maan asuvaiset; sillä Herran päivä tulee ja on läsnä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Pimiä päivä, synkiä päivä, sumuinen päivä ja utuinen päivä; niinkuin aamurusko itsensä levittää vuorten ylitse; suuri ja väkevä kansa, jonka kaltaista ei ikänä ole ollut, eikä vasta tule ijankaikkiseen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Hänen edellänsä käy kuluttavainen tuli, ja hänen jälissänsä polttavainen liekki. Maa on hänen edessänsä niinkuin Edenin puutarha, mutta hänen jälissänsä niinkuin autio erämaa, ja ei pidä kenenkään pääsemän häneltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Hänen muotonsa on niinkuin hevosten muoto; ja he karkaavat niinkuin ratsasmiehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'He hyppäävät ylhäällä vuorten kukkuloilla niinkuin rattaat kitisevät, niinkuin liekki korsissa kihisis; niinkuin väkevä kansa, joka sotaan on hankittu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Kansat pitää hänen edessänsä hämmästymän, että kaikki kasvot valjuksi muuttuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'He juoksevat niinkuin uljaat, ja karkaavat muurien ylitse niinkuin sotamiehet; ja kukin käy kohdastansa edes, ja ei poikkee ulos tiestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Ei estä kenkään kumppaniansa, vaan kukin matkustaa asetuksessansa; ja kuin he sota-aseiden välistä tunkevat sisälle, niin ei heitä haavoiteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'He ajelevat ympäri kaupungissa, ja muurien päällä juoksevat, ja kiipeevät huoneisiin, ja tulevat akkunoista sisälle, niinkuin varas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Hänen edessänsä vapisee maa, ja taivas värisee: aurinko ja kuu pimenevät, ja tähdet peittävät valkeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Sillä Herra on paneva jylinänsä hänen sotaväkensä edellä; sillä hänen sotaväkensä on sangen suuri ja väkevä, joka hänen käskynsä toimittaa; sillä Herran päivä on suuri ja sangen hirmuinen, kuka sitä voi kärsiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Niin sanoo nyt Herra: kääntykäät kaikesta sydämestänne minun tyköni, paastolla, itkulla ja murheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Leikatkaat teidän sydämenne, ja älkäät teidän vaatteitanne, ja palatkaat Herran teidän Jumalanne tykö; sillä hän on armollinen ja laupias, pitkämielinen ja suuresta hyvyydestä, ja katuu rangaistusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Kukaties hän kääntyy ja katuu, ja jättää jälkeensä siunauksen, ruokauhrin ja juomauhrin Herralle teidän Jumalallenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Soittakaat basunalla Zionissa, pyhittäkäät paasto, kutsukaat seurakunta kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Kootkaat kansa, pyhittäkäät kokous, kutsukaat yhteen vanhimmat, saattakaat yhteen nuorukaiset ja imeväiset; ylkä lähtekään kammiostansa, ja morsian makaushuoneestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Papit, Herran palveliat, itkekään esihuoneen ja alttarin välillä, ja sanokaan: armahda, Herra, sinun kansaas, ja älä laske sinun perikuntaas pilkkaan, niin ettei pakanat saisi valtaa heidän päällensä! miksi pitäis sanottaman kansain seassa: kussa on nyt heidän Jumalansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Niin Herralla on kiivaus maastansa; ja hän armahtaa kansaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Ja Herra vastaa ja sanoo kansallensa: katso, minä lähetin teille jyviä, viinaa ja öljyä, että teillä piti niistä kyllä oleman; ja en salli teitä enään häpiään tulla pakanain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Ja tahdon sen, joka pohjoisesta tullut on, teiltä kauvas saattaa, ja ajaa hänen pois korkiaan ja hävitettyyn maahan, hänen kasvonsa itäistä merta päin, ja hänen loppunsa äärimäisen meren puoleen; ja hänen pitää mätänemän ja haiseman; sillä hän on suuria tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Älä pelkää, sinä maa, vaan iloise ja riemuitse; sillä Herra taitaa myös suuria tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Älkäät peljätkö, te pedot kedolla; sillä laitumet korvessa pitää viheriöitsemän, ja puut hedelmänsä kantaman, fikunapuut ja viinapuut kyllä hedelmöitsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Ja te, Zionin lapset, iloitkaat ja riemuitkaat Herrassa teidän Jumalassanne, joka teille antaa vanhurskauden opettajan, ja laskee alas teille aamu- ja ehtoosateen niinkuin ennenkin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Että aitat jyviä täynnä olisivat, ja kuurnat nuoresta viinasta ja öljystä ylitse vuotaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Ja minä saatan teille jälleen ne vuodet, jotka heinäsirkka, lehtimato, jyvämato ja ruohomato söi; se minun suuri sotaväkeni, jonka minä teidän sekaanne lähetin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Että teidän pitää kyllä syömän ja ravituksi tuleman, ja ylistämän Herran teidän Jumalanne nimeä, joka teidän seassanne on ihmeitä tehnyt; ja ei minun kansani pidä ikänä häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Ja teidän pitää ymmärtämän, että minä olen Israelin keskellä, ja että minä olen Herra teidän Jumalanne ja ei kenkään muu; eikä minun kansani pidä ikänä häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Ja sitte pitää tapahtuman, että minä tahdon vuodattaa minun Henkeni kaiken lihan päälle; ja teidän poikanne ja tyttärenne pitää ennustaman, teidän vanhimpanne pitää unia uneksuman, ja teidän nuorukaisenne pitää näkyjä näkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Ja myös niinä päivinä tahdon minä palveliain ja piikain päälle vuodattaa minun Henkeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Ja tahdon antaa tapahtua tunnustähdet taivaassa ja maassa, veren, tulen ja savun suitsun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Auringon pitää muuttuman pimiäksi, ja kuun vereksi; ennenkuin se suuri ja hirmuinen Herran päivä tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Ja on tapahtuva, että jokainen, joka Herran nimeä avuksensa huutaa, se tulee autuaaksi; sillä Zionin vuorella ja Jerusalemissa on vapaus oleva, niinkuin Herra on luvannut, ja jääneiden tykönä, jotka Herra kutsuva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Sillä katso, niinä päivinä ja sillä ajalla, kuin minä Juudan ja Jerusalemin vankiuden palautan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Tahdon minä koota kaikki pakanat, ja viedä heitä alas Josaphatin laaksoon; ja tahdon siellä heidän kanssansa riidellä, minun kansani ja minun perimiseni Israelin tähden, jonka he pakanain sekaan hajoittivat, ja jakoivat minun maani itsellensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Ja ovat minun kansastani arpaa heittäneet; ja ovat pojan porton edestä antaneet, ja piian myyneet viinan edestä, ja sen juoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Mitä myös minun on teidän kanssanne, te Tyrosta ja Zidonista, ja te kaikki Philistealaisten rajat? vai tahdotteko te minulle kaiketi kostaa? Jos te minulle tahdotte kostaa, niin minä tahdon sen äkisti ja pian kostaa teidän päänne päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Sillä te olette minun hopiani ja kultani ottaneet, ja minun kauniit kappaleeni teidän kirkkoihinne vieneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'Ja myyneet Juudan ja Jerusalemin lapset Grekiläisille, heitä kauvas heidän rajoistansa saattaaksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Katso, minä tahdon heidät sieltä herättää, johonka te heidät myyneet olette; ja tahdon sen kostaa teidän päänne päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'Ja tahdon myydä jälleen teidän poikanne ja tyttärenne Juudan lasten kautta; ne pitää heidät rikkaasen Arabiaan, kaukaisen maan kansalle myymän; sillä Herra on sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Julistakaat näitä pakanain seassa, pyhittäkäät sota, herättäkäät väkevät, käyköön edes, ja menköön ylös kaikki sotaväki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Tehkäät vannanne miekoiksi ja viikahteenne keihäiksi. Ja joka heikko on, se sanokaan: minä olen väkevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Kootkaat teitänne, ja tulkaat tänne kaikki pakanat ympäristöltä, ja kootkaat teitänne; anna, Herra, sinun väkevät sinne astua alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Nouskaat pakanat ja menkäät ylös Josaphatin laaksoon; sillä minä tahdon siellä istua, ja tuomita kaikki pakanat ympäristöltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Sivaltakaat viikahteella, sillä elo on kypsä; tulkaat ja astukaat alas; sillä kuurnat ovat täydet, ja kuurnaastiat kuohuvat; sillä heidän pahuutensa on suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Paljo kansaa pitää oleman ympärillä joka paikassa Tuomiolaaksossa; sillä Herran päivä on läsnä Tuomiolaaksossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Aurinko ja kuu pimenevät, ja tähdet peittävät valkeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Ja Herra on Zionista kiljuva, ja antaa kuulla äänensä Jerusalemista, että taivaan ja maan pitää vapiseman. Mutta Herra on kansansa turva, ja linna Israelin lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Ja teidän pitää tietämän, että minä Herra teidän Jumalanne asun Zionissa minun pyhällä vuorellani; silloin on Jerusalem pyhäksi tuleva, ja ei pidä muukalaisen käymän enään sen lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Sillä ajalla pitää vuoret makiaa viinaa tiukkuman, ja kukkulat rieskaa vuotaman, ja kaikki Juudan ojat pitää vettä täynnä oleman; ja lähde pitää Herran huoneessa käymän, ja Sittimin ojaan juokseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Vaan Egyptin pitää autioksi tuleman, ja Edom synkiäksi erämaaksi; sen vääryyden tähden, mikä Juudan lapsille tehty on, että he viattoman veren heidän maassansa vuodattaneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Mutta Juudassa pitää ijankaikkisesti asuttaman, ja Jerusalemissa ijankaikkiseen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Ja minä tahdon puhdistaa heidän verensä, jota en minä ennen ole puhdistanut; ja Herra on asuva Zionissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Tämä on se, minkä Amos, joka paimenien seassa Tekoassa oli, näki Israelissa, Ussian Juudan kuninkaan ajalla, ja Jerobeamin Joaksen pojan, Israelin kuninkaan ajalla, kahta vuotta ennen maan järistystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Ja sanoi: Herra on Zionista kiljuva, ja Jerusalemista antaa hän äänensä kuulla, että paimenien laidun surkiana oleman pitää, ja Karmeli ylhäältä kuivuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Näin sanoo Herra: kolmen ja neljän Damaskun vian tähden en tahdo minä häntä säästää, että he Gileadin rautaisilla vaunuilla runtelivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Vaan minä lähetän tulen Hasaelin huoneesen; sen pitää Benhadadin huoneet kuluttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Ja rikon Damaskun salvat, ja hävitän Avenin laakson asuvaiset, ja sen, joka valtikkaa pitää, siitä kauniista huoneesta; niin että Syrian kansa pitää Kiriin vietämän, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Näin sanoo Herra: kolmen ja neljän Gatsan vian tähden en minä tahdo häntä säästää, että he ovat vangitut vielä vanginneet, ja heidät Edomiin ajaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Vaan minä lähetän tulen Gatsan muuriin, joka heidän huoneensa pitää kuluttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Ja tahdon Asdodin asuvaiset, ja sen, joka valtikkaa pitää, Askalonista hävittää; ja minun käteni on oleva Akronia vastaan, niin että hukkuman pitää, mitä Philistealaisista jäänyt on, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Näin sanoo Herra: kolmen ja neljän Tyron vian tähden en tahdo minä häntä säästää, että he ovat vangit edemmä Edomin maata ajaneet, ja ei ole muistaneet veljesten liittoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Vaan minä tahdon tulen Tyron muuriin lähettää, jonka pitää kuluttaman hänen huoneensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Näin sanoo Herra: kolmen ja neljän Edomin vian tähden en tahdo minä häntä säästää, että hän on veljeänsä miekalla vainonnut, ja turmellut halunsa, ja on ollut aina hänelle paha vihoillansa ja alati hirmuisuutensa näyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Vaan minä lähetän tulen Temaniin, jonka pitää kuluttaman Botsran huoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Näin sanoo Herra: kolmen ja neljän Ammonin lasten vian tähden en tahdo minä heitä säästää, että he ovat raskaat vaimot halki leikanneet Gileadissa, levittääksensä rajojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Vaan minä sytytän tulen Rabban muuriin; sen pitää kuluttaman hänen huoneensa. Niinkuin sodan aikana parutaan, ja niinkuin tuuli tulee tuulispään aikana:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Niin pitää myös heidän kuninkaansa ja päämiehensä ynnä vietämän pois vangittuina, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Näin sanoo Herra: kolmen ja neljän Moabin vian tähden en tahdo minä heitä säästää, että he ovat Edomin kuninkaan luut tuhaksi polttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Vaan minä tahdon tulen Moabiin lähettää; sen pitää Kerijotissa huoneet kuluttaman; ja Moab on metelissä kuoleva, huudossa ja vaskitorven helinässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Ja minä tahdon tuomarin temmata pois häneltä, ja tappaa kaikki hänen päämiehensä ynnä hänen kanssansa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Näin sanoo Herra: kolmen ja neljän Juudan vian tähden en tahdo minä säästää, että he katsovat Herran lain ylön, ja ei pitäneet hänen säätyjänsä, ja antavat itseänsä valheella vietellä, jota heidän isänsä ovat seuranneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Vaan minä tahdon tulen Juudaan lähettää; sen pitää Jerusalemin huoneet kuluttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Näin sanoo Herra: kolmen ja neljän Israelin vian tähden en minä tahdo säästää, että he vanhurskaat rahaan ja köyhät kenkäpariin myyneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'He tallaavat vaivaisen maan tomuun, ja estävät raadollisia joka paikassa; poika ja isä makaa yhden vaimon kanssa, jolla he minun pyhän nimeni häpäisevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Ja jokaisen alttarin tykönä he pitoa pitävät panttivaatteista, ja juovat viinaa sakkorahoista epäjumalainsa huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Ja minä olen kuitenkin Amorilaisen heidän edestänsä kadottanut, jonka korkeus oli niinkuin sedripuiden korkeus, ja joka oli niin vahva kuin tammet; ja minä turmelin ylhäältä hänen hedelmänsä, ja hänen juurensa alhaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Minä olen se, joka teitä Egyptin maalta toin, ja johdattain teitä korvessa neljäkymmentä ajastaikaa, että te Amorilaisten maan omistitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Ja olen teidän lapsistanne prophetat herättänyt, ja teidän nuorukaisistanne nasiirit; eikö se niin ole, te Israelin lapset? sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Mutta te annoitte nasiirein viinaa juoda, ja prophetaita te haastoitte, sanoen: ei teidän pidä ennustaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Katso, minä tahdon teitä niin ahdistaa kuin kuorma on kiinnitetty, eloja täynnä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Että se, joka nopia on, ei pidä pääsemän pakenemaan, eikä väkevä mitään voiman; ja ei urhoollisen pidä voiman henkeänsä vapahtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Ja ei joutsimiesten pidä seisoman, ja joka nopia on juoksemaan, ei pidä pääsemän; ja joka hevosella ajaa, ei pidä henkeänsä vapahtaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Ja joka väkeväin seassa kaikkein miehuullisin on, sen pitää alasti pakeneman sillä ajalla, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Kuulkaat tätä sanaa, jonka Herra puhuu teistä, te Israelin lapset, kaikista sukukunnista, jotka minä olen vienyt ulos Egyptin maalta, ja sanoin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Kaikista sukukunnista maan päällä olen minä teidät ainoastaan korjannut; sen tähden tahdon minä myös teitä etsiä kaikissa teidän pahoissa töissänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Taitaako kaksi yhdessä vaeltaa, ellei he yhteen sovi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Kiljuuko jalopeura metsässä, jos ei hänellä ruokaa ole? Parkuuko jalopeuran penikka luolastansa, ellei hän jotakin saanut ole?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Menneekö lintu paulaan maan päällä, kussa ei pyytäjää ole? Ottaneeko hän paulansa maasta, joka ei mitään vielä saanut ole?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Soitetaanko vaskitorvea kaupungissa, ja ei kansa hämmästy? Onko myös jotain pahaa kaupungissa, jota ei Herra tee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Sillä ei Herra, Herra tee mitään, ellei hän ilmoita salauttansa palvelioillensa prophetaille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Jalopeura kiljuu, kuka ei pelkää? Herra, Herra puhuu, kuka ei ennusta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Julistakaat Asdodin huoneissa ja Egyptin maan huoneissa, ja sanokaat: kootkaat teitänne Samarian vuorille, ja katsokaat, kuinka suuri vääryys ja väkivalta siellä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Ei he taida oikeutta tehdä, sanoo Herra; vaan kokoovat tavaroita huoneissansa väkivallalla ja ryöstämisellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Sentähden näin sanoo Herra, Herra: tämä maa piiritetään; ja sinä paiskataan alas sinun vallastas, ja sinun huonees raadellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Näin sanoo Herra: Niinkuin paimen tempaa ulos jalopeuran suusta kaksi reittä eli korvan kappaleen; niin myös Israelin lapset pitää temmatuksi tuleman, jotka Samariassa asuvat, vuoteen loukkaassa ja kehdon kulmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Kuulkaat ja todistakaat Jakobin huoneessa, sanoo Herra, Herra Jumala Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Sillä silloin, kuin minä Israelin synnit etsin, tahdon minä myös Betelin alttarin etsiä; ja alttarin sarvet pitää hakattaman pois, ja ne lankeeman maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Ja tahdon talvihuoneen ja suvihuoneen maahan lyödä; ja elephantin luiset huoneet pitää hukkuman, ja paljo huoneita pitää häviämän, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Kuulkaat tätä sanaa, te lihavat lehmät, jotka Samarian vuorella olette, ja teette köyhille vääryyttä, ja murennatte vaivaisen, ja sanotte teidän herroillenne: tuos tänne, anna meidän juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Herra, Herra on pyhyytensä kautta vannonut: katso, se aika pitää tuleman teidän päällenne, että te temmataan pois orjantappuroilla, ja teidän jälkeentulevaisenne kalain ongella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Ja itsekunkin teistä pitää menemän ulos särjetyn muurin lävitse, ja ylönantamaan huoneensa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Tulkaat Beteliin, ja tehkäät syntiä, ja Gilgaliin, että te syntiä lisäisitte; ja tuokaat aamulla teidän uhrinne, ja teidän kymmenyksenne kolmena päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Ja suitsuttakaat hapatuksesta kiitosuhriksi, ja kuuluttakaat ja kootkaat vapaaehdon uhreja; sillä niin te sen mielellänne pidätte, te Israelin lapset, sanoo Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Sentähden minä myös olen kaikissa kaupungeissa teille joutilaat hampaat antanut, ja leivän puuttumisen jokaisissa teidän paikoissanne; ja ette sittekään kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Olen myös minä pidättänyt teiltä sateen, kuin vielä kolme kuukautta oli elonaikaan, ja minä annoin sataa yhden kaupungin päälle, ja toisen kaupungin päälle en antanutkaan sataa; yhden saran päälle satoi, ja toinen sarka, jonka päälle ei satanut, kuivettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Ja kaksi eli kolme kaupunkia meni yhteen kaupunkiin vettä juomaan, ja ei saaneet tarvettansa; ja ette sittekään kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Minä rankaisin teitä poudalla ja nokipäillä, ja ruohomadot söivät kaikki, mitä teidän yrttitarhoissanne, viinamäissänne, fikunapuissanne ja öljypuissanne kasvoi; ette sittekään kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Minä lähetin ruton teidän sekaanne niinkuin Egyptiin, ja tapoin miekalla teidän nuoret miehenne, ja annoin viedä pois teidän hevosenne vankina; ja annoin haisun teidän leirissänne teidän sieramiinne mennä; ette sittekään kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Minä kukistin ylösalaisin muutamat teistä, niinkuin Jumala Sodoman ja Gomorran kukisti, ja te olitte niinkuin tulesta otettu kekäle; ette sittekään kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Sentähden tahdon minä sinulle näin tehdä, Israel; että minä nyt näin sinulle tehdä tahdon, niin valmista sinuas, Israel, ja mene Jumalaas vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Sillä katso, hän on se, joka on tehnyt vuoret, ja luonut tuulen, ja ilmoittaa ihmiselle, mitä hänen puhuman pitää; hän tekee aamuruskon ja pimeyden; hän käy maan korkeutten päällä; hänen nimensä on Herra Jumala Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Kuulkaat te, Israelin huone, näitä sanoja; sillä minun täytyy tämän valitusveisun teistä nostaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Neitsy Israel on langennut, niin ettei hän voi jälleen nousta ylös; hän on kukistettu maahan, ja ei kenkään häntä auta ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Sillä näin sanoo Herra, Herra: siihen kaupunkiin, josta tuhannen käy ulos, pitää ainoasti sata jäämän, ja josta sata käy ulos, pitää kymmenen jäämän, Israelin huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Sentähden näin sanoo Herra Israelin huoneelle: etsikäät minua, niin te saatte elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Ja älkäät Beteliä etsikö, ja älkäät tulko Gilgaliin, älkäät myös Bersebaan menkö; sillä Gilgal pitää vietämän vangittuna pois, ja Betel tyhjäksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Etsikäät Herraa, niin te saatte elää, ettei tuli Josephin huoneeseen sytytettäisi, ja kuluttais, ja ei olisi sammuttajaa Betelissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Te käännätte oikeuden koiruohoksi, ja kukistatte maahan vanhurskauden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Hän tekee Otavan ja Kointähden, ja muuttaa kuoleman varjon aamuksi, ja päivästä pimiän yön tekee; joka vedet meressä kutsuu, ja kaataa ne maan piirin päälle, hänen nimensä on Herra;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Joka raateluksen asettaa väkevän ylitse, ja että raatelia uskaltaa vahvan kaupungin päälle karata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Mutta he vihaavat sitä, joka heitä julkisesti nuhtelee, ja sitä he kauhistuvat, joka oikein opettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Sentähden, että te köyhää sorratte, ja otatte häneltä suuret kuormat jyviä, ei pidä teidän niissä huoneissa asuman, jotka te vuojonkivistä rakentaneet olette; te olette istuttaneet kauniit viinamäet, vaan ei teidän pidä niistä viinaa juoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Sillä minä tiedän teidän pahat tekonne, joita paljo on, ja teidän syntinne, jotka raskaat ovat: te ahdistatte vanhurskaita ja otatte sovinnon, vaivaisia myös tuomion edessä sorratte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Sentähden täytyy ymmärtäväisen sillä ajalla vaijeta; sillä se on paha aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Etsikäät hyvää, ja älkäät pahaa, että te eläisitte; niin Herra Jumala Zebaot on teidän kanssanne, niinkuin te kerskaattekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Vihatkaat pahaa, ja rakastakaat hyvää, toimittakaat oikeus porteissa: niin Herra Jumala Zebaot on armollinen Josephin jääneille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Sentähden näin sanoo Herra Jumala, Herra Zebaot: jokaisella kadulla on parku oleva, ja jokaisessa kujassa sanottava: voi! voi! ja peltomiehes kutsutaan murheeseen parkumaan niiden kanssa, jotka valitusveisun taitavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Niin myös jokaisessa viinamäessä on parku oleva; sillä minä tahdon sinun kauttas vaeltaa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Voi niitä, jotka Herran päivää pyytävät! Sillä mitä siitä on teille? Se Herran päivä on pimeys ja ei valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Niinkuin joku pakenis jalopeuran edestä, ja karhu kohtais häntä; ja niinkuin joku tulis huoneesen, ja nojais kätensä seinälle, ja kärmeeltä pistettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Eikö Herran päivä ole pimiä, ja ei valkia, synkiä ja ei selkiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Minä vihaan ja hylkään teidän juhlapäivänne, en myös tahdo haistaa teidän uhrianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Ja vaikka te minulle uhraisitte polttouhria ja ruokauhria, en minä kuitenkaan ota niitä otolliseksi, enkä katso teidän lihavaa kiitosuhrianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Vie pois minun edestäni sinun virtes jyrinä; sillä en minä voi sinun kanteleittes laulua kuunnella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Mutta oikeus pitää julistettaman niinkuin vesi, ja vanhurskaus niinkuin väkevä virta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Oletteko te, Israelin huone, minulle teurasuhria ja ruokauhria tehneet neljänäkymmenenä vuotena korvessa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Te kannoitte teidän Melekinne majoja, ja teidän epäjumalainne kuvia, teidän jumalainne tähteä, jotka te itse teillenne tehneet olitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Niin minä siis annan teidän tästä edemmä Damaskua viedä, sanoo Herra, jonka nimi on Jumala Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Voi suruttomia Zionissa, ja niitä, jotka Samarian vuoreen luottavat, jotka kutsutaan ylimmäisiksi pakanain seassa, ja Israelin huoneessa hallitsevat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Menkäät Kalneen ja katsokaat, ja menkäät sieltä suureen Hamatin kaupunkiin, ja sieltä käykäät alas Philistealaisten Gatiin: ovatko ne paremmat kuin nämät valtakunnat, ovatko heidän rajansa laviammat, kuin teidän rajanne:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Te jotka luulette itsenne kaukana olevan pahoista päivistä, ja vedätte puoleenne väkivaltaisen istuimen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Ja makaatte elephantin luisessa vuoteessa, ja koreilette ylönpalttisuudessa teidän makaussiallanne, ja syötte parhaimmat laumasta ja syötetyt vasikat karjan seasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Ja soitatte psaltarilla, ja ajattelette teillenne lauluja niinkuin David,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Ja juotte viinaa maljoista, ja voitelette teitänne parhaalla voiteella; ja ei kenkään sure Josephin vahinkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Sentähden pitää heidän nyt käymän niiden edellä, jotka viedään pois vangittuna, ja öykkärien vieraspito on lakkaava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Sillä Herra, Herra on vannonut itse kauttansa, sanoo Herra Jumala Zebaot: minua kauhistaa Jakobin ylpeys, ja minä vihaan hänen koreita huoneitansa, ja tahdon sen kaupungin hyljätä ja kaikki mitä hänessä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Ja pitää tapahtuman, että vaikka kymmenen miestä yhteen huoneeseen jäisi, niin pitää heidän kuitenkin kuoleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Että hänen setänsä ja enonsa veis hänen luunsa ulos huoneesta, ja sanois sille, joka sen huoneen vieressä on: vieläkö sinun tykönäs ketään on? ja se vastaa: jo ovat kaikki pois. Ja niiden pitää sanoman: ole vaiti, sillä ei he tahtoneet, että Herran nimeä olis muistutettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Sillä katso, Herra on käskenyt lyödä suuria huoneita rikki, ja vähiä huoneita hajoomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Taitavatko hevoset kalliolla samota? taidetaanko sitä härjillä kyntää? sillä te muuttelette oikeuden sapeksi ja vanhurskauden hedelmän koiruohoksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Ja iloitsette tyhjästä asiasta, ja sanotte: emmekö me kyllä väkevät ole meidän sarvillamme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Sentähden katso, minä tahdon teidän päällenne, te Israelin huone, kansan herättää, sanoo Herra Jumala Zebaot; joka teitä pitää siitä paikasta ahdistaman, kuin Hamatiin mennään, hamaan korven ojaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Niin Herra, Herra osoitti minulle näyssä; ja katso, yksi seisoi, joka heinäsirkkoja teki, juuri silloin, kuin oras rupesi käymään ylös, toisen kerran sittekuin kuningas oli antanut niittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Kuin ne niin tahtoivat kaiken tulon syödä maalta, sanoin minä: voi Herra, Herra, ole armollinen! kuka tahtoo Jakobin taas auttaa? sillä hän on aivan vähä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Niin Herra katui sitä: ei sen pidä tapahtuman, sanoi Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Niin Herra, Herra osoitti minulla näyssä, ja katso, Herra, Herra kutsui tulen rankaisemaan, jonka piti suuren syvyyden syömän, ja se söi jo parhaan osan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Niin minä sanoin: voi Herra, Herra, lakkaa nyt, kuka tahtoo Jakobia taas auttaa? sillä hän on aivan vähä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Niin Herra katui myös sitä: ei senkään pidä tapahtuman, sanoi Herra, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Mutta hän osoitti minulle tämän näyssä, ja katso, Herra seisoi muurin päällä, joka mittanuoralla mitattu oli, ja hän piti mittanuoran kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Ja Herra sanoi minulle: mitäs näet, Amos? minä sanoin: mittanuoran. Herra sanoi: katso, minä tahdon vetää mittanuoran keskelle minun kansaani Israelia, ja en käy enään häntä ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Vaan Isaakin korkeudet pitää autioksi tuleman, ja Israelin pyhyydet pitää hävitettämän; ja minä tahdon nostaa miekan Jerobeamin huonetta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Niin Betelin pappi Amatsia lähetti Israelin kuninkaan tykö, sanoen: Amos tekee kapinan sinua vastaan Israelin huoneessa, eipä maakaan voi kaikkia hänen sanojansa kärsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Sillä näin sanoo Amos: Jerobeamin täytyy miekalla kuolla, ja Israel pitää vietämän vangittuna pois maastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Ja Amatsia sanoi Amokselle: sinä näkiä, mene pois, ja ennusta siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Ja älä Betelissä enään ennusta; se on kuninkaan pyhä sia ja valtakunnan huone.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Amos vastasi ja sanoi Amatsialle: en minä ole propheta enkä prophetan poika, vaan minä olen karjan paimen ja marjain hakia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Mutta Herra otti minun karjasta, ja sanoi minulle: mene ja ennusta minun kansaani Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Niin kuule siis Herran sanaa: sinä sanot: älä ennusta Israelia vastaan, älä myös puhu Isaakin huonetta vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Sentähden sanoo Herra näin: sinun emäntäs pitää kaupungissa raiskattaman, ja sinun poikas ja tyttäres pitää miekalla lankeeman, ja sinun peltos pitää nuoralla jaettaman; mutta itse sinun pitää saastaisessa maassa kuoleman, ja Israel pitää ajettaman peräti pois maastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Herra, Herra osoitti minulle näyssä, ja katso, siellä oli kori suvituloa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Ja hän sanoi: mitäs näet, Amos? minä vastasin: korin suvituloa. Niin Herra sanoi minulle: minun kansani Israelin loppu on tullut, en minä tahdo enään mennä häntä ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Ja sinä päivänä pitää veisut templissä itkuksi kääntymän, sanoo Herra, Herra; monta kuollutta ruumista pitää joka paikassa makaaman, jotka viedään salassa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Kuulkaat tätä te, jotka köyhää sorratte, ja vaivaisia maakunnassa hävitätte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Ja sanotte: koska uusi kuu loppuu, että me saisimme jyviä myydä; ja sabbati, että me ohria kauppaisimme, ja mitan vähentäisimme, ja hinnan korottaisimme, ja vaa\'at vääriksi tekisimme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Että me saisimme köyhät rahallamme haltuumme ja hätäytyneet kenkäparilla, ja myisimme akanat jyväin edestä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Herra on vannonut Jakobin korkeutta vastaan: mitämaks, jos minä ikänä kaikki ne heidän työnsä unohdan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Eikö maan sentähden pitäisi vapiseman, ja kaikki sen asuvaiset murehtiman? Ja pitää nouseman kaiken sen päälle niinkuin virta, vietämän pois ja upotettaman niinkuin Egyptin virralla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Sillä ajalla, sanoo Herra, Herra, tahdon minä laskea auringon alas puolipäivästä, ja pimittää maan valkialla päivällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Minä tahdon teidän juhlapäivänne kääntää murheeksi, ja kaikki teidän veisunne valitukseksi, ja tahdon antaa säkin jokaisen kupeisiin tulla, ja kaikki päät paljaaksi tehdä; ja tahdon heille murheen saattaa, niinkuin joku ainoaa poikaa murehtii; ja heidän pitää surkian lopun saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Katso, ne päivät tulevat, sanoo Herra, Herra, että minä lähetän nälän maan päälle; ei nälkää leivän perään, eli janoa veden perään, vaan Herran sanan kuulemisen jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Niin että heidän pitää juokseman yhdestä merestä niin toiseen, pohjasta niin itään; heidän pitää juoksenteleman etsimään Herran sanaa, ja ei kuitenkaan pidä löytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Sinä päivänä pitää kauniit neitseet ja nuorukaiset nääntymän janosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Ja jotka nyt Samarian rikoksen kautta vannovat ja sanovat: niin totta kuin sinun jumalas Danissa elää, niin totta kuin sinun jumalas Bersebassa elää: niiden pitää niin lankeeman, ettei he voi jälleen nousta ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Minä näin Herran seisovan alttarilla; ja hän sanoi: lyö oven päälliseen, niin että pihtipielet värisevät; sillä minä tahdon haavoittaa niitä kaikkia, jotka heille päänä ovat, ja heidän alamaisensa miekalla tappaa. Ei sen pidä pääsemän, joka paennut on, eikä itsiänsä pelastaman, jotka välttänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Ja vaikka he itsiänsä hamaan helvettiin kaivaisivat, niin minun käteni on kuitenkin heitä sieltäkin hakeva; ja jos he astuisivat ylös taivaaseen, niin minä kuitenkin tahdon syöstä heidät sieltä alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Ja jos he lymyttäisivät itsensä Karmelin kukkulalle, niin minä tahdon heidät sieltäkin etsiä ja temmata pois; ja jos he itseänsä minun silmäini edestä kätkisivät meren syvyyteen, niin minä käsken kärmettä, että se heitä siellä pistäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Ja jos he vihollisillensa vangiksi tulevat, niin minä sieltä käsken miekkaa, että se heitä tappais: sillä minä pidän silmäni heidän ylitsensä pahaksi ja en hyväksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Sillä kuin Herra, Herra Zebaot maahan rupee, niin se sulaa, että kaikki asuvaiset murehtiman pitää; ja että se pitää nouseman sen päälle niinkuin virta, ja se upotettaman niinkuin Egyptin virralla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Hän on se, joka salinsa taivaasen rakentaa, ja perustaa majansa maan päälle; hän kutsuu meren vedet, ja vuodattaa maan päälle: hänen nimensä on Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Ettekö te, Israelin lapset, minulle ole niinkuin Etiopialaiset? sanoo Herra. Enkö minä vienyt Israelia ulos Egyptin maalta, ja Philistealaiset Kaphtorista, ja Syrialaiset Kiiristä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Katso, Herran, Herran silmät näkevät syntisen valtakunnan, niin että minä sen juuri maan päältä peräti kadotan; vaikka en minä kuitenkaan Jakobin huonetta ratki kadota, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Sillä katso, minä tahdon käskeä, ja antaa Israelin huoneen kaikkein pakanain seassa seulottaa, niinkuin seulalla seulotaan, ja ei jyvänkään pidä lankeeman maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Kaikki syntiset minun kanssani pitää miekalla kuoletettaman, jotka sanovat: ei onnettomuus ole niin läsnä, eikä kohtaa meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Sillä ajalla tahdon minä taas kaatuneen Davidin majan rakentaa, ja hänen reikänsä paikata, ja parantaa jälleen mitä särjetty on, ja tahdon sen rakentaa, niinkuin se entisellä ajalla tullut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Että he saavat nautita Edomin jääneet ja kaikki pakanat, joiden seassa minun nimeni pitää saarnattaman; sanoo Herra, joka näitä tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Katso, se aika tulee, sanoo Herra, että yhtä haavaa kynnetään ja niitetään, ja yhtä haavaa viinamarjat sotkutaan ja kylvetään, ja vuoret makiaa viinaa tiukkuvat, ja kaikki mäet ovat hedelmälliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Sillä minä käännän minun kansani Israelin vankiuden, että he rakentavat autiot kaupungit, ja niissä asuvat; istuttavat viinapuita, ja niistä viinaa juovat, tekevät puutarhoja, ja niistä hedelmiä syövät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Ja minä tahdon heitä heidän maassansa istuttaa; niin ettei heitä enään temmata pois maastansa, jonka minä heille antanut olen, sanoo Herra sinun Jumalas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Tämä on Obadjan näky. Näin sanoo Herra, Herra Edomista: me olemme Herralta sanoman kuulleet, että sanansaattaja on pakanain sekaan lähetetty: nouskaat, ja käykäämme häntä vastaan sotaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Katso, minä olen sinun alentanut pakanain seassa, ja sangen ylönkatsotuksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Sinun sydämes ylpeys on sinun vietellyt, ettäs vuorten rotkoissa asut, sinun korkeissa linnoissas, ja sanot sydämessäs: kuka taitaa minun syöstä maahan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Vaikkas ylös korkialle menisit niinkuin kotka, ja tekisit pesäs tähtien keskelle; niin minä kuitenkin syöksen sinun alas sieltä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Jos varkaat eli raateliat tulevat yöllä sinun tykös, kuinka sinä niin lyöty olet? Eikö he varasta niin paljon, että heillä kyllä on? Jos viinanhakiat tulevat sinun tykös, eikö he jätä viinamarjan oksia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Voi kuinka heidän pitää Esaun tutkiman, ja hänen kätketyt tavaransa etsimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Kaikki, jotka sinun kanssas liitossa ovat, pitää ajaman sinun pois maaltas; miehet, joihin sinä turvaat, pettävät sinun, ja voittavat sinun; jotka sinun leipäs syövät, pettävät sinun; ei sinulla ole ymmärrystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Mitämaks, sanoo Herra, minä kadotan silloin Edomin viisaat ja ymmärryksen Esaun vuorelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Sillä sinun väkeväs, Teman, pitää hämmästymän, että heidän kaikkein pitää murhasta Esaun vuorella hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Sen vääryyden tähden, jonka sinä veljelles Jakobille tehnyt olet, pitää sinun häpiään tuleman, ja ijankaikkisesti hävitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Silloin sinä seisoit häntä vastaan, kuin muukalaiset hänen sotaväkensä veivät pois vangittuna, ja vieraat menivät sisälle hänen porteistansa, ja Jerusalemista arvan heittivät; silloin sinä olit niinkuin yksi heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Ei sinun pidä mielelläs katseleman veljes viheliäisyyden aikaa, eikä riemuitseman Juudalaisten surkeuden aikana, ei myös sinun suus pidä niin suuria sanoja puhuman heidän tuskansa aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Ei sinun pidä menemän sisälle minun kansani porteista heidän surkeutensa aikana, eikä mielelläs katseleman heidän onnettomuuttansa heidän vaivansa aikana, eikä kättäs ojentaman heidän kaluunsa heidän surkeutensa aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Ei sinun pidä teiden haaroissa seisoman, murhaamassa heidän pakenevaisiansa, ei myös kiinni ottaman heidän jääneitänsä ahdistuksensa aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Sillä Herran päivä on läsnä kaikkia pakanoita; niinkuin sinä tehnyt olet, niin pitää sinulle jälleen tapahtuman, ja niinkuin sinä ansainnut olet, niin pitää sinun pääs päälle jälleen tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Sillä niinkuin te olette minun pyhällä vuorellani juoneet, niin pitää kaikki pakanat alati juoman, ryyppäämän ja nielemän, ja oleman niinkuin ei he olleetkaan olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Mutta Zionin vuorella pitää vapaus oleman, ja heidän pitää pyhät oleman, ja Jakobin huoneen pitää perintönsä omistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Ja Jakobin huone pitää tuli oleman, ja Josephin huonen tulen liekki, mutta Esaun huone kortena, jonka heidän pitää sytyttämän ja kuluttaman, niin ettei Esaun huoneesta pidä mitään jäämän; sillä Herra on sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Ja heidän pitää perimän koko etelänpuolisen maan, ynnä Esaun vuoren kanssa, ja lakeuden Philistealaisten kanssa, ja heidän pitää myös Ephraimin ja Samarian kedon omistaman, ja Benjaminin Gileadin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Ja ne viedyt pois Israelin lasten sotaväestä, jotka Kanaanealaisten seassa hamaan Sarpattiin asti ovat, ja ne viedyt pois Jerusalemin kaupungista, jotka Sepharadissa ovat, pitää kaupungit etelään päin omistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Ja vapahtajat pitää Zionin vuorelle tuleman tuomitsemaan Esaun vuorta; ja niin pitää valtakunta Herran oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Ja Herran sana tapahtui Jonalle Amittain pojalle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Nouse ja mene suureen kaupunkiin Niniveen, ja saarnaa siinä; sillä heidän pahuutensa on tullut minun kasvoini eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Mutta Jona nousi ja tahtoi paeta Tarsikseen Herran kasvoin edestä. Ja hän tuli Japhoon, ja kuin hän löysi haahden, joka tahtoi Tarsikseen mennä, antoi hän palkan, ja astui siihen menemään heidän kanssansa Tarsikseen Herran kasvoin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Niin Herra antoi suuren tuulen tulla merelle, ja suuri ilma nousi merellä, niin että haaksi luultiin rikkaantuvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Ja haaksimiehet pelkäsivät, ja kukin huusi jumalansa tykö, ja he heittivät kalut, jotka haahdessa olivat, mereen keviämmäksi tullaksensa. Mutta Jona oli astunut alas haahden toiselle pohjalle, ja makasi uneen nukkuneena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Niin haahdenhaltia meni hänen tykönsä, ja sanoi hänelle: miksis makaat? nouse, ja rukoile Jumalaas, että Jumala muistais meitä, ettemme hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Niin he sanoivat toinen toisellensa: tulkaat, ja heittäkäämme arpaa, tietääksemme, kenenkä tähden tämä onnettomuus meillä on; ja kuin he heittivät arpaa, lankesi arpa Jonan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Niin he sanoivat hänelle: ilmoita nyt meille, kenen tähden tämä onnettomuus meillä on? mikä sinun tekos on, ja kustas tulet? kusta maakunnasta eli kansasta sinä olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Hän sanoi heille: minä olen Hebrealainen, ja minä pelkään Herraa Jumalaa taivaasta, joka meren ja karkian on tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Niin ne miehet pelkäsivät suuresti, ja sanoivat hänelle: miksis näin teit? Sillä ne miehet tiesivät hänen Herran edestä paenneen; sillä hän oli heille sen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Niin he sanoivat hänelle: mitä meidän pitää sinulle tekemän, että meri meille tyventyis? Sillä meri kävi ja lainehti heidän ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Hän sanoi heille: ottakaat minut ja heittäkäät mereen, niin meri teille tyvenee; sillä minä tiedän, että tämä suuri ilma tulee teidän päällenne minun tähteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Ja miehet koettivat saada haahden kuivalle; mutta ei he voineet, sillä meri kävi väkevästi heidän ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Niin he huusivat Herran tykö ja sanoivat: voi Herra! älä anna meidän hukkua tämän miehen sielun tähden, ja älä lue meillen tätä viatointa verta! sillä sinä, Herra, teet niinkuin sinä tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Niin he ottivat Jonan ja heittivät mereen; ja meri asettui lainehtimasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Ja miehet pelkäsivät Herraa suuresti, ja tekivät Herralle uhria ja lupausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'Mutta Herra toimitti suuren kalan, nielemään Jonaa. Ja Jona oli kalan vatsassa kolme päivää ja kolme yötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Ja Jona rukoili Herraa Jumalaansa kalan vatsassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Ja sanoi: minä huusin Herraa minun ahdistuksessani, ja hän vastasi minua; minä paruin helvetin vatsasta, ja sinä kuulit minun ääneni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Sinä heitit minun syvyyteen keskelle merta, niin että aallot minua pyörsivät ympäriinsä; kaikki sinun lainees ja aaltos kävivät minun päällitseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Minä ajattelin minuni hyljätyksi sinun silmäis edestä; kuitenkin saan minä vielä nähdä sinun pyhän templis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Vedet piirsivät minua ympäri sieluuni asti; syvyydet piirittivät minun; kaislisto peitti minun pääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Minä vajosin vuorten perustukseen asti; maa salpasi minun teljillänsä ijankaikkisesti; mutta sinä otit minun elämäni ulos kadotuksesta, Herra minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Kuin minun sieluni epäili minussa, niin minä muistin Herraa; ja minun rukoukseni tuli sinun tykös, sinun pyhään templiis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Mutta jotka luottavat turhaan valheeseen, ne hylkäävät laupiuden itse kohtaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Mutta minä tahdon uhrata sinulle kiitoksella, minä tahdon maksaa lupaukseni; Herran tykönä on apu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ja Herra sanoi kalalle, että hän oksensi Jonan maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Niin Herran sana tapahtui toisen kerran Jonalle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Nouse, mene suureen kaupunkiin Niniveen, saarnaamaan siellä sitä saarnaa, jonka minä sinulle sanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Silloin Jona nousi ja meni Niniveen Herran sanan jälkeen. Ja Ninive oli Jumalan suuri kaupunki, kolmen päiväkunnan matka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Ja kuin Jona rupesi siinä käymään yhden päiväkunnan matkan, huusi hän ja sanoi: vielä on neljäkymmentä päivää; niin Niniven pitää hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Niin Niniven miehet uskoivat Jumalan päälle, ja antoivat saarnata, että paastottaisiin, ja pukivat säkit yllensä sekä pienet että suuret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Ja kuin Niniven kuningas sen kuuli, nousi hän istuimeltansa ja riisui kalliit vaatteensa, kääri itsensä säkkiin ja istui tuhkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Ja antoi kuuluttaa ja sanoa Ninivessä kuninkaan tahdosta ja hänen sankareinsa käskystä, sanoen: ettei yksikään ihminen taikka eläin, karja eli lampaat pidä mitään maistaman eikä laitumelle ajettaman, ja ei vettäkään juoman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Vaan ihmiset ja eläimet pitää säkkiin puetettaman, ja heidän pitää lujasti Jumalan tykö huutaman. Ja jokainen palatkaan pahasta tiestänsä ja kätensä väkivallasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kukaties Jumala taitaa kääntyä ja katua, ja lakata hirmuisesta vihastansa, ettemme huku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Kuin Jumala näki heidän työnsä, että he palasivat pahasta tiestänsä, katui Jumala sitä pahaa, jota hän oli puhunut heille tehdäksensä, ja ei tehnytkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Niin Jona pani sen kovin pahaksensa, ja vihastui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Rukoili Herraa ja sanoi: voi Herra! sepä se on, minkä minä sanoin, kuin minä olin vielä maassani, sentähden minä tahdoin myös Tarsikseen paeta; sillä minä tiedän, että sinä Jumala olet armollinen, laupias, pitkämielinen, suuresta hyvyydestä ja kadut pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Niin ota nyt, Herra, minun sieluni minusta pois; sillä minä kuolisin paremmin kuin eläisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Mutta Herra sanoi: luuletkos oikein vihastunees?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Ja Jona läksi kaupungista ja istui kaupungista itään päin, ja teki siellä itsellensä majan ja istui sen alla varjossa, siihenasti kuin hän näkis, mitä kaupungille tapahtuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Mutta Herra Jumala toimitti yhden pensaan, joka kasvoi Jonan ylitse, että se olis hänen päänsä varjonnut, ja virvoittanut häntä hänen vaivassansa; ja Jona riemuitsi siitä pensaasta suurella ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Mutta Herra toimitti madon huomeneltain, kuin aamurusko koitti, joka söi sitä pensasta, että se kuivettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Mutta kuin aurinko noussut oli, toimitti Jumala suuren itätuulen, ja aurinko paisti Jonan päähän, että hän tuli voimattomaksi. Niin hän toivotti sielullensa kuolemaa, ja sanoi: minä kuolisin ennenkuin minä eläisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Niin Jumala sanoi Jonalle: luuletkos oikein vihastunees siitä pensaasta? Ja hän sanoi: minä vihastun hamaan kuolemaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Ja Herra sanoi: sinä armahdat pensasta, josta et mitään vaivaa nähnyt, etkä sitä kasvattanut, joka ynnä kasvoi ja ynnä katosi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Eikö minun pitänyt armahtaman suurta kaupunkin Niniveä, jossa on enempi kuin sata tuhatta ja kaksikymmentä tuhatta ihmistä, jotka ei tiedä eroittaa kumpi oikia eli kumpi vasen käsi on, niin myös paljo eläimiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Tämä on Herran sana, joka tapahtui Miikalle Moresasta, Jotamin, Ahaksen ja Jehiskian, Juudan kuningasten aikana, jonka hän näki Samariasta ja Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Kuulkaat kaikki kansat; sinä maa, ota vaari, ja kaikki, mitä siinä on; ja Herra Jumala olkoon todistaja teitä vastaan, Herra pyhästä templistänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Katso, Herra lähtee siastansa, astuu alas ja polkee maan korkeuksia:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Niin että vuoret sulavat hänen allansa, ja laaksot halkeevat, niinkuin medenvaha sulaa tulen edessä, ja niinkuin vedet, jotka korkialta alas vuotavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Kaikki nämät tapahtuvat Jakobin ylitsekäymisen tähden, ja Israelin huoneen syntein tähden. Kuka siis on Jakobin ylitsekäymys? Eikö Samaria? ja kutka ovat Juudan korkeudet? Eikö Jerusalem?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Minä teen Samarian kiviraunioksi kedolla, joka pannaan viinamäen ympäri, ja vieritän hänen kivensä laaksoon, ja särjen perustukseen asti maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Kaikki heidän epäjumalansa pitää rikottaman, ja kaikki heidän palkkansa tulella poltettaman, ja minä hävitän kaikki heidän kuvansa; sillä he ovat porton palkasta kootut; sentähden pitää heidän jälleen porton palkaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Sitä minun täytyy valittaa ja parkua, minun täytyy riisuttuna ja alasti käydä; minun pitää valittaman niinkuin lohikärmeet ja murehtiman niinkuin nälkäkurki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Sillä tähän vitsaukseen ei ole yhtään neuvoa; joka jo Juudaan asti on tullut, ja pitää ulottuman minun kansani porttiin asti, Jerusalemiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Älkäät sitä Gatissa ilmoittako, älkäät antako kuulla teidän itkuanne; vaan menkäät tuhkahuoneeseen ja istukaat tuhkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Lähde pois, sinä kauniin kaupungin asuvainen, häpiällä paljastettu. Karjakaupungin asuvaiset ei tule ulos, että valitus on lähipaikoissa, jotka saavat teiltä ylöspitämisensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Se surullinen kaupunki murehtii sen hyvän tähden; sillä onnettomuus pitää Herralta tuleman hamaan Jerusalemiin porttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Sinä kaupunki Lakis, valjasta ratasten eteen liukkaat hevoset, ja mene matkaas; sinä olet Zionin tyttärelle synnin alku ollut, sillä sinussa on löydetty Israelin rikoksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Sinun täytyy niin lahjat antaa kuin Gatikin; Aksibin huoneen pitää Israelin kuningasten liitosta luopuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Minä saatan sinulle, Maresa, oikian perillisen, ja Israelin kunnian pitää Adullamiin asti tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Tee pääs paljaaksi, ja keritse sinus, sinun kaunisten lastes tähden; ajele pääs paljaaksi niinkuin kotka, sillä he ovat viedyt sinulta pois vangittuina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Voi niitä, jotka vahinkoa ajattelevat, ja pahoja juonia vuoteissansa ahkeroitsevat! että he sen täyttäisivät kuin aamu valistaa; sillä heilläpä valta on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'He ahnehtivat peltoja, jotka he väkivallalla ottavat, ja huoneita, jotka he omistavat; ja tekevät ylöllistä jokaisen huoneen kanssa ja jokaisen perinnön kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Sentähden sanoo Herra näin: katso, minä ajattelen tälle sukukunnalle pahaa, josta ei teidän pidä voiman vetää pois teidän kansaanne, eikä teidän pidä niin ylpiästi käymän; sillä paha aika tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Sillä ajalla pitää teistä sananlasku otettaman, ja surkia valitus valitettaman, sanoen: me olemme peräti hävitetyt; minun kansani osa on muutettu; kuinka hän meiltä pellot ottaa pois, ja ne jakaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Ja tosin ei teillä pidä osaa Herran seurakunnassa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Ei teidän pidä (sanovat he) saarnaaman, muiden pitää saarnaaman; ei niiden pidä saarnaaman niinkuin te: emme niin ratki häpiään tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Niin Jakobin huone itsensä lohduttaa: luuletkos Herran hengen lyhennetyksi? eikö hänen näitä pitäisi tekemän? eikö minun puheeni ole hyvä sille, joka oikein vaeltaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Mutta minun kansani on jo ennen tätä hankkinut niinkuin vihollinen; he ryöstävät sekä hameen että päällisvaatteen niinkuin sodassa niiltä, jotka suruttomasti vaeltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Te ajatte pois minun kansani vaimot kauniista huoneistansa, ja alati otatte pois heidän nuorukaisiltansa minun kaunistukseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Sentähden nouskaat ja menkäät pois; sillä ette saa tässä olla; saastaisuutensa tähden pitää heidän armottomasti häviämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Jos joku lipilaari olis ja valheen saarnaaja, (joka sanois:) minä tahdon saarnata, kuinka teidän pitää viinaa ja väkevää juomaa juoman; senkaltainen saarnaaja olis tälle kansalle sovelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Mutta minä tahdon sinua, Jadob, kokonansa koota, ja jääneet Israelissa saattaa kokoon, ja tahdon heitä, niinkuin Botsran lauman, yhteen saattaa; niinkuin lauma pihatossa, niin myös sen pitää ihmisistä kopiseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Yksi särkiä pitää astuman ylös heidän edellänsä; heidän pitää särkemän lävitse, ja käymän portista ulos ja sisälle; ja heidän kuninkaansa pitää käymän heidän edellänsä, ja Herra kaikkein ensin heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Ja minä sanoin: kuulkaat siis te Jakobin päämiehet, ja te Israelin huoneen esimiehet: eikö teidän pitäisi oikeutta tietämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Mutta te vihaatte hyvää ja rakastatte pahaa; te nyljette heiltä heidän nahkansa, ja kalvatte lihan heidän luistansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Ja syötte minun kansani lihan, ja kuin te olette heiltä nahan nylkeneet, niin te särjette heidän luunsa, ja hakkaatte rikki ne niinkuin pataan, ja niinkuin lihan kattilaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Sentähden kuin te Herran tykö huudatte, niin ei hän teitä kuule, vaan peittää silloin teiltä kasvonsa, niinkuin te olette teidän pahalla menollanne ansainneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Näin sanoo Herra niistä prophetaista, jotka minun kansaani viettelevät: he saarnaavat rauhaa, kuin heille syötävää annetaan; mutta kuin ei heidän suuhunsa mitää anneta, saarnaavat he sodan tulevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Sentähden pitää teidän näkynne yöksi, ja teidän aavistuksenne pimeydeksi tuleman. Auringon pitää laskeman niiden prophetain ylitse, ja päivän pitää pimenemän heidän päältänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Ja näkiäin pitää häpiään tuleman, ja ennustajain häpeemän, ja kaikkein täytyy suunsa peittää, ettei siellä ole Jumalan sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Mutta minä olen täynnä Herran hengen voimaa, ja oikeutta ja väkevyyttä, että minä tohdin ilmoittaa Jakobille ylitsekäymisensä ja Israelille syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Niin kuulkaat siis tätä, te Jakobin huoneen päämiehet, ja te Israelin huoneen esimiehet: te, jotka oikeutta kauhistutte, ja käännätte toisin kaikki, mikä toimellinen on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Te jotka Zionin verellä rakennatte, ja Jerusalemin vääryydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Hänen päämiehensä tuomitsevat lahjain tähden, hänen pappinsa opettavat palkan tähden, ja heidän prophetansa aavistavat rahan tähden; luottavat kuitenkin Herraan, ja sanovat: eikö Herra ole meidän seassamme? Ei taida onnettomuus meitä käsittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Sentähden pitää Zion kynnettämän teidän tähtenne niinkuin pelto, ja Jerusalem pitää tuleman kiviraunioksi, ja templin vuori metsän kukkulaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Mutta viimeisinä päivinä pitää sen vuoren, jolla Herran huone on, vahvistuman, ja oleman korkeimman kaikkia muita vuoria, ja korotettaman kukkulain ylitse; ja kansat pitää sinne juokseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Ja moninaiset pakanat sinne menemän ja sanoman: tulkaat ja astukaamme ylös Herran vuorelle ja Jakobin Jumalan huoneen tykö, että hän opettais meille teitänsä, ja me vaeltaisimme hänen poluillansa. Sillä Zionista on laki tuleva, ja Herran sana Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Ja hän on tuomitseva paljon kansan seassa, ja rankaiseva väkevät pakanat kaukaisissa maakunnissa; silloin pitää heidän miekkansa vannaiksi tekemän ja keihäänsä viikahteiksi. Ei yhdenkään kansan pidä toista kansaa vastaan miekkaa nostaman, eikä enään tottuman sotimaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Jokaisen pitää viinapuunsa ja fikunapuunsa alla pelkäämättä asuman; sillä Herran Zebaotin suu on sen puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Jokainen kansa pitää Jumalansa nimessä vaeltaman; mutta meidän pitää vaeltaman Herran meidän Jumalamme nimeen, aina ja ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Sillä ajalla, sanoo Herra, tahdon minä ontuvaiset koota, ja saattaa hyljätyt kokoon, ja sen, jota minä vaivannut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Ja tahdon ontuvaiselle perillisiä saattaa, ja heikon suureksi kansaksi tehdä. Ja Herra on itse oleva heidän kuninkaansa Zionin vuorella tästä ajasta hamaan ijankaikkisuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Ja sinä Ederin torni, Zionin tyttären linna, sinun tykös pitää tuleman, ja pitää tuleman sen entinen esivalta, Jerusalemin tyttären valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Miksi sinä nyt niin lakkaamatta huudat? Eikö kuningas ole sinun kanssas? Ovatko sinun neuvonantajas hukkuneet, että kipu tarttui sinuun niinkuin synnyttäväiseen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Murehdi ja huokaa sinä, Zionin tytär, niinkuin synnyttäväinen: sillä sinun täytyy mennä ulos kaupungista ja kedolla asua, ja mennä hamaan Babeliin; mutta sinä päästetään taas sieltä, siellä on Herra sinun päästävä sinun vihollises kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Sillä monet pakanat pitää kokoontuman sinua vastaan, ja sanoman: hän on alttiiksi annettu, me tahdomme meidän himomme nähdä Zionista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Mutta ei he Herran ajatuksista mitään tiedä, eikä ota vaaria hänen neuvostansa; sillä hän on hakenut heitä kokoon, niinkuin lyhteet riiheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Sentähden nouse ja tapa riihtä sinä Zionin tytär; sillä minä tahdon sinulle tehdä rautaiset sarvet ja vaskiset kynnet, ettäs paljon kansaa runtelet. Niin minä tahdon myös heidän tavaransa alttiiksi antaa Herralle, ja heidän hyvyytensä kaiken maailman hallitsialle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Mutta hankitse nyt, sinä sotanainen: sillä meitä piiritetään; ja Israelin tuomaria vitsalla poskelle lyödään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Ja sinä, Betlehem Ephrata, joka vähäinen olet Juudan tuhanten seassa, sinusta on minulle se tuleva, joka Israelissa on hallitsia oleva, jonka uloskäymys on ollut alusta ja ijankaikkisuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Hän antaa heitä siihen aikaan asti vaivattaa, kuin se on synnyttänyt, jonka pitää synnyttämän; ja jääneet hänen veljistänsä pitää tuleman jälleen Israelin lasten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Mutta hän on astuva edes, ja kaitseva Herran väkevyyden kautta, ja Herran Jumalansa nimen korkeuden kautta, ja heidän pitää levossa asuman; sillä hän on nyt kuuluisaksi tuleva niin lavialta kuin maailma on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Me saamme myös rauhan Assurilta, joka nyt meidän maallemme tullut on, ja meidän huoneemme tallannut on; sillä häntä vastaan pitää seitsemän paimenta ja kahdeksan päämiestä herätettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Jotka Assurin maan miekalla hävittävät, ja Nimrodin maan heidän omissansa; niin me Assurista päästetyksi tulemme, joka meidän maallemme tullut on, ja meidän rajamme tallannut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Ja jääneet Jakobissa pitää myös monen kansan seassa oleman, niinkuin kaste Herralta, ja niinkuin sateen pisarat ruoholla, joka ei ketään odota, eikä ihmistä tottele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Ja jääneet Jakobista pitää pakanain seassa, monen kansan tykönä oleman, niinkuin jalopeura metsän petoin seassa, ja niinkuin nuori jalopeura lammaslauman seassa, jota ei kenkään voi karkottaa, kuin hän menee lävitse, sotkuu ja repelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Sinun kätes saa voiton kaikkia vihollisias vastaan, että kaikki sinun vihollises hävitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Sillä ajalla, sanoo Herra, tahdon minä ottaa sinulta pois sinun hevoses, ja kadottaa sinun rattaas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Ja tahdon sinun maas kaupungit hävittää, ja kaikki sinun linnas särkeä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Ja tahdon velhot sinussa hävittää, ettei yksikään tietäjä pidä sinun tykönäs oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Minä tahdon temmata pois sinun kuvas ja epäjumalas sinusta, ettei sinun pidä enää kumartaman sinun kättes tekoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Ja tahdon hakata maahan sinun metsistös, ja sinun kaupunkis hävittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'Ja minä tahdon kostaa hirmuisuudella ja vihalla kaikki pakanat, jotka ei tahdo kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Kuulkaat siis, mitä Herra sanoo: nouse ja nuhtele vuoria, ja kuulkaan kukkulat sinun ääntäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Kuulkaat, te vuoret, Herran riitaa, ja te väkevät maan perustukset; sillä Herralla on riita kansansa kanssa, ja Israelin kanssa tahtoo hän kamppailla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Minun kansani, mitä minä olen sinulle tehnyt, eli millä minä olen sinua raskauttanut? Sano minulle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Minä olen kuitenkin sinun Egyptin maalta vienyt ylös, ja lunastin sinun orjuuden huoneesta; ja lähetin sinun etees Moseksen, Aaronin ja Mirjamin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Minun kansani, muista siis, mitä neuvoa Balak Moabin kuningas piti, ja mitä Bileam Peorin poika häntä vastasi, Sittimistä hamaan Gilgaliin asti, että te tietäisitte Herran vanhurskaita töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Millä minun pitää Herraa lepyttämän? kumarruksellako korkian Jumalan edessä? pitääkö minun häntä lepyttämän polttouhrilla ja vuosikuntaisilla vasikoilla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Luuletkos, että Herra mielistyy moneen tuhanteen oinaasen, taikka öljyyn, vaikka sitä epälukuiset virrat täynnä olisivat? Eli pitääkö minun antaman esikoisen poikani minun ylitsekäymiseni tähden, eli minun ruumiini hedelmän minun sieluni synnin tähden?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Se on sinulle sanottu, ihminen, mikä hyvä on, ja mitä Herra sinulta vaatii, nimittäin, ettäs kätket Jumalan sanan, ja harjoitat rakkautta, ja olet nöyrä sinun Jumalas edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Herran äänen pitää kuuluman kaupungin ylitse, mutta joka sinun nimeäs pelkää, pitää menestymän: kuulkaat vitsaa, ja kuka sen on toimittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Eikö vielä ole väärä tavara jumalattomain huoneissa, ja vähä mitta kauhistukseksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Eli pitäiskö minun väärät vaa\'at ja petolliset puntarit säkeissä kohtuulliseksi arvaaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Joiden kautta hänen rikkaansa paljon vääryyttä tekevät, ja hänen asuvaisensa valhettelevat; ja pettäväinen kieli on heidän suussansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Sentähden minä rupeen myös sinua rankaisemaan, ja hävitän sinua sinun synteis tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Sinä syöt, ja et taida ravituksi tulla, ja sinä pitää sinussas nöyryytettämän. Mitäs kätket, ei sen pidä pääsemän, ja mitä pääsee, sen minä miekalle annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Sinä kylvät, ja et leikkaa; sinä sotkut öljypuita, ja et saa itsiäs öljyllä voidella, ja kuurnitset viinaa, ja et saa sitä juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Sillä Omrin säädyt ahkerasti pidetään, ja kaikki Ahabin huoneen teot, ja te vaellatte heidän neuvoissansa; sentähden tahdon minä sinun autioksi tehdä, ja sen maan asuvaiset pilkaksi, ja teidän pitää minun kansani häpiän kantaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Voi minua! sillä minulle tapahtuu niinkuin sille, joka viinamäessä tähteitä hakee, kussa ei viinamarjoja löytä syötää; ja minun sieluni himoitsee varhaista hedelmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Hyvät ovat maasta kadonneet pois, ja vanhurskaat ei ole enään ihmisten seassa; kaikki he väijyvät verta vuodattaaksensa, jokainen vakoo toista, käsittääksensä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Ja luulevat hyvästi tekevänsä, koska he pahasti tekevät. Mitä päämies tahtoo, sitä tuomari sanoo, että se hänelle jotakin hyvää jälleen tekis; väkevät puhuvat oman tahtonsa jälkeen vahingoittaaksensa, ja vääntelevät niinkuin he tahtovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Kaikkein paras on heidän seassansa niinkuin orjantappura, ja kaikkein toimellisin on niinkuin ohdakkeet. Mutta kuin sinun saarnaajais päivät tulevat, ja sinä tulet rangaistuksi, silloin ei he tiedä, kuhunka heidän menemän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Älköön kenkään uskoko lähimmäistänsä; älköön kenkään uskaltako päämiesten päälle; kätke sinun suus ovi siltä, joka makaa helmassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Sillä poika katsoo ylön isänsä, tytär karkaa äitiänsä vastaan, ja miniä anoppiansa vastaan; ja ihmisen viholliset ovat hänen oma perheensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Mutta minä tahdon katsoa Herran päälle, ja minun autuuteni Jumalaa odottaa; minun Jumalani on minua kuuleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Älä iloitse, minun viholliseni, minusta, että minä lankesin, minä olen taas nouseva, ja vaikka minä pimeydessä istun, niin Herra on kuitenkin minun valkeuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Minä tahdon kantaa Herran vihan, sillä minä olen häntä vastaan syntiä tehnyt, siihenasti kuin hän minun asiani toimittaa, ja saattaa minulle oikeuden; hän vie minun ulos valkeuteen, että minä saan nähdä hänen vanhurskautensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Minun viholliseni pitää sen näkemän, ja peräti häpiään tuleman, joka nyt sanoo minulle: kussa on Herra sinun Jumalas? Minun silmäni pitää hänen näkemän, että hän pitää niinkuin loka kaduilla poljettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Sillä ajalla pitää rakennettaman jälleen sinun muuris, ja Jumalan sana lavialta julistettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Sillä ajalla pitää sinun tykös Assyriasta ja vahvoista kaupungeista tultaman, hamasta vahvoista kaupungeista niin virtaan asti, yhdestä merestä niin toiseen, yhdestä vuoresta niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Sillä maan pitää autioksi tuleman asuvaistensa tähden, heidän töittensä hedelmän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Kaitse kansaas sinun sauvallas, sinun perimises laumaa, joka asuu yksinänsä, metsässä vainioin keskellä; anna heitä kaita Basanissa ja Gileadissa, niinkuin entiseen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Minä annan heidän ihmeitä nähdä, niinkuin muinen, kuin he Egyptin maalta läksivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Että pakanat sen näkisivät, ja kaikki heidän voimallisena häpeäisivät, ja panisivat kätensä suunsa päälle, ja korvansa tukitsisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Heidän pitää tomua nuoleman niinkuin kärme, ja niinkuin madot maan päällä pesästänsä liikkuman. Heidän pitää pelkäämän Herraa meidän Jumalaamme, ja vapiseman sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kuka on senkaltainen Jumala kuin sinä olet, joka synnit annat anteeksi? hän menee ohitse perimisensä jääneiden rikoksia; ei hän pidä vihaa ijäti, sillä hänellä on halu laupiuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Hän kääntyy, ja armahtaa meidän päällemme, ja polkee alas meidän pahat tekomme, ja kaikki meidän syntimme meren syvyyteen heittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Sinä pidät Jakobille uskollisuuden, ja Abrahamille sen armon, jonka muinen meidän isillemme vannonut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Tämä on Niniven kuorma, ja Nahumin Elkosilaisen ennustuskirja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Herra on kiivas Jumala ja kostaja, ja Herra on kostaja ja vihainen; Herra on kostaja vihollisiansa vastaan, joka ei vainollisiansa unohda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Herra on pitkämielinen ja suuri voimassa, jonka edessä ei kenkään ole viatoin; Herran tie on tuulessa ja tuulispäässä jonka jalkain tomu pilvi on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Joka nuhtelee merta, ja kuivaa sen, ja tekee kaikki virrat kuivaksi; Basan ja Karmel taipuu, ja se nääntyy mitä Libanonin vuorella kukoistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Vuoret vapisevat hänen edessänsä, ja kukkulat sulavat; maa palaa hänen edessänsä, ja maan piiri, ja kaikki, jotka siinä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Ja kuka seisoo hänen vihansa edessä? eli kuka voi pysyä hänen hirmuisuutensa edessä? hänen vihansa palaa niinkuin tuli, ja kalliot lohkeevat hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Herra on laupias, ja turva hädän aikana; ja tuntee ne, jotka uskaltavat hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Kuin vedenpaisumus juoksee, niin hän sen lopettaa; mutta hänen vihollisiansa hän vainoo pimeydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Mitä te ajattelette Herraa vastaan? Hän on se, joka kuitenkin tekee lopun; ei ahdistus kahdesti tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Sillä niinkuin orjantappurat, jotka sekaseuraisin kasvavat ja kaikkein tuoreimmat ovat, poltetaan niinkuin kuivat korret;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Niin pitää oleman se kavala juoni, joka sinusta tulee ulos, ja pahaa ajattelee Herraa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Näin sanoo Herra: vaikka he ovat rauhassa, ja heitä on tosin monta, kuitenkin heidän pitää maahan hakatuksi tuleman ja menemän pois; sillä minä olen sinua nöyryyttänyt, mutta en tahdo kuitenkaan enempää vaivata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Vaan tahdon silloin hänen ikeensä sinusta särkeä, ja reväistä rikki sinun sitees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Mutta sinua vastaan on Herra käskenyt, ettei yksikään sinun nimes siemen pysymän pidä. Sinun Jumalas huoneesta tahdon minä hukuttaa sinun epäjumalas, ja kuvas tahdon minä sinulle haudaksi tehdä; sillä sinä olet tyhjäksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Katso, suloisten saarnaajain jalat ovat vuorilla, niiden jotka rauhaa julistavat; pidä sinun juhlapäiväs, Juuda, ja maksa lupaukses; sillä ei se jumalatoin pidä enään tuleman sinun päälles, joka on kokonaan hävitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Haaskaaja astuu ylös sinua vastaan, ja piirittää linnan; mutta ota ahkerasti vaari teistäs, hankitse itses jalosti, ja vahvista sinun voimas väkevästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Sillä Herra tuo jälleen Jakobin suuren kunnian, niinkuin Israelinkin suuren kunnian, vaikka ryöstäjät ovat hänen tyhjentäneet ja viinapuunsa oksat turmelleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Hänen väkeväinsä kilvet ovat punaiset, hänen sotaväkensä on niinkuin purpura; hänen rattaansa valistavat niinkuin tulisoihdut, kuin sotaan mennään: heidän keihäänsä häälyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Rattaat vierivät kaduilla, ja kolisevat kujilla; he välkkyvät niinkuin tulisoitto, ja juoksevat niinkuin pitkäisen leimaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Mutta hän ajattelee väkeviänsä; kuitenkin heidän pitää lankeeman, vaikka kuhunka he tahtovat; ja heidän pitää rientämän muureihinsa päin, ja siihen varjelukseen, kussa he irstaana olisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Mutta portit virtain tykönä kuitenkin avataan, ja huone hajoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Kuningatar pitää vietämän pois vangittuna, ja hänen piikansa huokaaman niinkuin mettiset, ja rintoihinsa lyömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Ninive on ollut aikanansa niinkuin kalalammikko vettä täynnä, mutta nyt he pakenevat. Seisokaat, seisokaat, (pitää heitä huutaman); vaan ei ole ketään, joka taaksensa katsoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Niin ryöstäkäät hopiaa, ryöstäkäät kultaa; sillä tässä on tavaraa ilman loppumata, ja kaikkinaisten kalliiden kappaleiden paljous.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Mutta nyt sen täytyy tyhjennetyksi, peräti paljastetuksi ja hävitetyksi tulla; sydän on rauvennut pois, polvet horjuvat, ja kaikki lanteet vapisevat, ja kaikkein kasvot mustaksi muuttuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Kussa nyt on jalopeurain asuinsia ja nuorten jalopeurain laidun, johon jalopeura meni, ja naaras jalopeura, jalopeuran penikan kanssa, ja ei tohtinut kenkään heitä karkottaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Vaan jalopeura raateli kyllä penikoillensa ja mursi naarasjalopeuroillensa; ja täytti luolansa raateluksesta ja pesänsä ryöstämisestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Katso, minä tulen sinun tykös, sanoo Herra Zebaot, ja sytytän sinun rattaas savuun, ja miekan pitää sinun nuoret jalopeuras syömän; ja minä teen lopun sinun ryöstämisestäs maassa, ettei enään pidä sinun sanansaattajas ääntä kuuluman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Voi sitä murhakaupunkia, joka on täynnä valhetta ja ryöstöä, eikä tahdo ryöstöstänsä lakata!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Sillä siinä kuullaan ruoskat vinkuvan ja ratasten pyörät kitisevän, hevoset hirnuvan ja rattaat vierivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Hän vie ratsastajat välkkyväisillä miekoilla, ja kiiltävillä keihäillä; siinä monta tapettua makaa, ja suuret ruumisten läjät, niin että ruumiit ovat lukemattomat ja niihin täytyy langeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Kaikki nämät sen kauniin ja rakkaan porton suuren huoruuden tähden, joka on taitava noita, joka huoruudellansa pakanat, ja velhoudellansa maat ja kansat myynyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Katso, minä tulen sinun kimppuus, sanoo Herra Zebaot, minä avaan sinun vaattees palteen sinun kasvoistas, ja näytän sinun häpys pakanoille, ja sinun häpiäs valtakunnille osoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Ja teen sinun sangen kauhistavaiseksi, ja häpäisen sinun, ja teen sinun saastaisuudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Ja pitää tapahtuman, että kaikki, jotka sinun näkevät, pitää sinua pakeneman, ja sanoman: Ninive on raadeltu, ja kuka tahtoo häntä armahtaa, ja kusta minun pitäis sinulle lohduttajaa etsimän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Oletkos parempi kuin hallitsiain kaupunki No? joka virtain keskellä oli, ja vesi juoksi hänen ympärillänsä, jonka muurit ja vahvistukset olivat meren reunassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Etiopia ja Egypti oli hänen lukematoin väkensä; Put ja Lybia olivat sinun apunas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Ja kuitenkin hänen täytyi pois ajettuna olla, ja mennä pois vangittuna; ja hänen lapsensa ovat kaikkein katuin suissa lyödyt, ja hänen kunniallisistansa heitettiin arpaa, ja kaikki hänen ylimmäisensä pantiin kahleisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Juuri niin täytyy sinun myös juopua, ja sinuas lymyttää, ja turvaa vihollistes edestä etsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Kaikki sinun vahvat kaupunkis ovat niinkuin fikunapuut, joissa kypsät fikunat ovat: kuin niitä pudistetaan, niin he putoovat sen suuhun, joka niitä syödä tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Katso, sinun kansas pitää tuleman niinkuin vaimot, ja sinun maas ovet pitää sinun vihollisilles kokonansa aukeneman, ja tulen pitää sinun salpas syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Ammenna sinulles vettä siinä, missä sinä piiritetään; vahvista sinun linnas, mene saveen ja sotke sitä, ja tee vahvoja tiilejä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Mutta tulen pitää sinua syömän, ja miekan sinua surmaaman; sen pitää sinun syömän niinkuin paarmat; sen pitää lankeeman sinun päälles niinkuin ruohomadot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Enempi sinulla on kauppamiehiä kuin tähtiä taivaassa; mutta nyt heidän pitää itsensä hajoittaman niinkuin paarmat, ja lentämän siitä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Sinun ylimmäistäs on niin monta niinkuin ruohomatoja, ja päämiehiäs niinkuin paarmoja, jotka heitänsä aidoille vilun aikana sioittavat; mutta kuin aurinko nousee, niin he sieltä lähtevät, ettei siaakaan tuta, kussa he olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Sinun paimenes, sinä Assurin kuningas, pitää makaaman, ja sinun voimallises pitää maata paneman; sinun kansas pitää vuorille hajoitettaman, ja ei pidä kenenkään heitä kokooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Ei pidä kenenkään sinun vahinkoas parantaman, eikä sinun rangaistuksestas sureman; vaan kaikki, jotka näitä sinusta kuulevat, pitää käsiänsä sinusta yhteen lyömän; sillä ketä ei ole sinun pahuutes ilman lakkaamata kohdannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Tämä on se raskaus, jonka propheta Habakuk on nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Herra, kuinka kauvan minun pitää huutaman, ja et sinä tahdo kuulla? kuinka kauvan minun pitää parkuman väkivallan tähden, ja et sinä tahdo auttaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Miksis minulle vaivaa ja työtä osoitat? miksis minun annat nähdä ryövyyttä ja väkivaltaa minun ympärilläni? riita ja tora saa vallan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Sentähden hyljätään laki, ja oikeus ei koskaan saa edes käydä; sillä jumalatoin sortaa vanhurskasta, sentähden tehdään väärät tuomiot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Katsokaat pakanain seassa, katsokaat ja ihmetelkäät, ja hämmästykäät; sillä minä teen työn teidän aikananne, jota ei teidän pidä uskoman, kuin siitä puhutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Sillä katso, minä herätän Kaldealaiset, haikian ja nopian kansan, jonka pitä vaeltaman niin leviältä kuin maa on, ja omistaman ne asumiset, jotka ei heidän omansa ole;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Joka pitää hirmuinen ja julma oleman, käskemän ja vaatiman, niinkuin hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Hänen hevosensa ovat nopiammat kuin pardit, ja purevaisemmat kuin sudet ehtoolla; hänen ratsasmiehensä vaeltavat lavialta; ja hänen ratsasmiehensä tulevat kaukaa, ja lentävät, niinkuin kotka rientää raadolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'He tulevat kaikki vahingoittamaan; he kääntävät kasvonsa itään päin, ja kokoovat vankeja niinkuin santaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Heidän pitää kuninkaita pilkkaaman ja päämiehiä nauraman; kaikki linnat pitää heidän leikkinänsä oleman; sillä he tekevät vähät vallit, ja voittavat ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Silloin he muuttavat mielensä, ylitsekäyvät ja rikkovat, että he kerskaavat voimansa olevan jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Etkös sinä, Herra, ole alusta, minun Jumalani, minun pyhäni. Älä anna meidän kuolla, vaan anna heidän olla, o Herra, meille ainoasti rangaistukseksi, ja anna heidän, o meidän turvamme, meitä ainoasti kurittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Sinun silmäs ovat puhtaat, niin ettes voi pahaa nähdä, ja et tahdo katsoa surkeutta; miksis katsot siis ylönkatsojia, ja vaikenet, kuin jumalatoin nielee sen, joka häntä hurskaampi on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Ja miksis teet ihmisen niinkuin kalat meressä, niinkuin madot, joilla ei haltiaa ole?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'He onkivat kaikki ongella, ja vetävät nuotallansa ja saavat verkoillansa; josta he iloitsevat ja riemuitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Sentähden he uhraavat nuotillensa ja suitsuttavat verkoillensa; että heidän osansa niiden kautta lihavaksi tullut on, ja ruokansa herkulliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Sentähden he vielä alati heittävät nuottansa ulos, eikä lakkaa kansaa tappamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Tässä minä seison minun vartiossani, ja astun minun linnaani; ja katselen nähdäkseni, mitä minulle sanotaan, ja mitä minulle sanotaan, ja mitä minä sitä vastaan, joka minua nuhtelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Mutta Herra vastasi minua ja sanoi: kirjoita se näky, ja piirrä tauluun, että ohitsekäypä sen lukis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Sillä se ennustus pitää ajallansa täytettämän, ja pitää sittekin ilmaantuman ja ei vilpistelemän. Jos se viipyy, niin odota häntä; hän tulee totisesti, ja ei viivyttele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Mutta joka sitä vastaan on, ei hänen sielunsa pidä menestymän; sillä vanhurskas on elävä uskostansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Mutta viina tekee ylpiän miehen petolliseksi, ettei hän taida pysyä siassansa; joka sielunsa levittää niinkuin helvetti, ja on niinkuin kuolema, joka tyytymätöin on; hän tempaa puoleensa kaikki pakanat, ja kokoo tykönsä kaikki kansat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Mitämaks, nämät kaikki pitää hänestä sananlaskun tekemän, ja puheen ja tapauksen, ja sanoman: voi sitä, joka kokoo tavaransa muiden hyvyydestä! kuinka kauvan se kestää? ja sälyttää paljon lokaa päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Oo kuinka äkisti ne pitää tuleman, jotka sinua purevat, ja ne heräävät, jotka sinun syöksevät pois? ja sinun täytyy tulla heille saaliiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Että sinä olet monet pakanat ryövännyt, niin pitää kaikki jääneet kansoista taas sinua ryöväämän, ihmisten veren tähden, ja maan ja kaupungin ja kaikkein sen asuvaisten tähden, jotka ryöstetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Voi sitä, joka ahne on oman huoneensa pahuudeksi, että hän panis pesänsä korkeuteen, ja pelastais itsensä onnettomuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Mutta sinun neuvos pitää sinun huonees häpiäksi joutuman; sillä sinä olet ylen paljon kansoja lyönyt, ja ylpiästi syntiä tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Sillä kivetkin seinässä pitää huutaman, ja malat harjalta pitää heitä vastaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Voi sitä, joka kaupungin verellä rakentaa, ja valmistaa kaupunkia vääryydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Katso, eikö nämät Herralta Zebaotilta tapahdu? Mitä kansat ovat sinulle tehneet, se poltetaan tulessa, ja jonka tähden ihmiset ovat väsytetyt, se täytyy hukutettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Sillä maan pitää oleman täynnä Herran kunnian tuntoa, niinkuin vedet, jotka meren peittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Voi sinua, joka lähimmäiselles panet sisälle, sekoitat siihen julmuutes ja juovutat häntä, ettäs hänen häpiänsä näkisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Sinun pitää häpiällä ravittaman kunnian edestä: niin juo sinä myös nyt, ettäs häpys paljastaisit; sillä Herran oikian käden malja pitää sinun tykös poikkeeman, ja sinun täytyy häpiällisesti oksentaa sinun kunniaas vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Sillä se väkivalta, joka Libanonissa tehty on, pitää lankeeman sinun päälles, ja haaskatut eläimet pitää sinua peljättämän, ihmisten veren tähden, ja maan ja kaupungin ja kaikkein sen asuvaisten tähden, jotka ryöstetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Mitä siis kuva auttaa taitaa, jonka puuseppä tehnyt on? eli valettu kuva ja valheen saarnaaja? Miksi se, joka niitä tekee, luottaa siihen, että hän mykkiä epäjumalia tehdä taitaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Voi sitä, joka sanoo kannolle: heräjä! ja mykälle kivelle: nouse! Senkö pitäis opettaman? Katso, se on kullalla ja hopialla silattu, ja ei ole siinä ensinkään henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Mutta Herra on pyhässä templissänsä; vaijetkoon kaikki maailma hänen kasvoinsa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Tämä on propheta Habakukin rukous viattomain edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Herra, minä kuulin sinun sanomas, ja hämmästyin. Herra, virvoita sinun käsialas vuosikautten keskellä, ja tee se tiettäväksi vuosikautten keskellä; vihassa muista laupiutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Jumala tuli etelästä ja pyhä Paranin vuorelta, Sela! hänen kunniansa peitti taivaat, ja hänen kiitoksensa täytti maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Hänen paisteensa oli niinkuin valkeus, säteet kävivät hänen käsistänsä; siellä oli hänen väkevyytensä salattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Hänen edellänsä kävi rutto, ja vitsaus hänen jalkainsa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Hän seisoi ja mittasi maan, hän katseli ja hajoitti pakanat, niin että ijankaikkiset vuoret musertuivat, ja ijäiset kukkulat notkistuivat; kuin hän maailmassa vaelsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Minä näin Etiopian majat surkiana, ja Midianilaisten teltat vapisevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Etkös, Herra, ollut vihainen virrassa, ja sinun hirmuisuutes vesissä ja närkästykses meressä? kuin ajoit hevosillas, ja sinun rattaas saivat voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Sinä veit sinun joutses edes, niinkuin sinä olet sukukunnille vannonut ja sanonut, Sela! ja jaoit virrat maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Vuoret näkivät sinun, ja vapisivat, virta meni pois, syvyys antoi itsestänsä äänen, ja nosti sivunsa korkeuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Aurinko ja kuu seisoivat siallansa; sinun nuoles menivät kirkkaudella, ja sinun sauvas pitkäisen leimauksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Sinä tallasit maan vihassas, ja survoit rikki pakanat hirmuisuudessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Sinä läksit kansaas auttamaan, auttamaan voideltus kanssa; sinä särjit jumalattomain huoneessa, ja paljastit perustukset, kaulaan asti, Sela!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Jospa sinä vielä kiroisit pään valtikkaa kylinensä! jotka tulevat niinkuin tuulispää minua hajoittamaan, ja iloitsevat niinkuin he olisivat köyhän syöneet salaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Sinä ajoit hevosillas meressä suurten vetten loassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Että minä sen kuulen, niin minun sydämeni murehtii, minun huuleni värisevät huudosta; märkä on mennyt minun luihini, minä olen murheellinen minussani; jospa minä saisin levätä vaivani ajallla, kuin me menemme sen kansan tykö, joka sotii meitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Sillä ei fikunapuun pidä vihoittaman eikä viinapuussa pidä hedelmää oleman: öljypuiden työ vilpistelee, ja ei pellot anna elatusta; ja lampaat pitää pihatosta karkoitettaman, eikä karjaa pidä navetassa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Mutta minä iloitsen Herrassa, ja riemuitsen Jumalassa minun lunastajassani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Herra, Herra on minun voimani, joka asettaa minun jalkani niinkuin peuran jalat, ja vie minun korkialle, niin että minä soitan kanteleitani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Tämä on Herran sana, joka tapahtui Zephanjalle Kusin pojalle, Gedalian pojalle, Amarian pojalle, Hiskian pojalle, Josian Amonin pojan, Juudan kuninkaan ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Minä tahdon kaikki maalta ottaa peräti pois, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Minä tahdon ottaa pois ihmiset ja karjan, linnut taivaan alta ja kalat merestä otan minä pois, niin myös pahennuksen ja jumalattoman, ja minä tahdon ihmiset maan päältä hävittää, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Minä ojennan minun käteni Juudan päälle ja kaikkein niiden päälle, jotka Jerusalemissa asuvat, ja hävitän Baalin jääneet, ja munkkien ja pappien nimen tästä paikasta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Ja ne, jotka kattoin päällä taivaan sotaväkeä kumartavat, ja jotka kumartavat ja vannovat Herran kautta, ja vannovat myös Molokinsa kautta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Ja ne, jotka Herrasta luopuvat, ja jotka ei Herraa ensinkään etsi, eikä häntä tottele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Vaijetkaat Herran, Herran edessä; sillä Herran päivä on läsnä, ja Herra on teurasuhrin valmistanut, ja vieraansa siihen kutsunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Ja Herran teurasuhrin päivänä on tapahtuva, että minä etsin päämiehiä ja kuninkaan lapsia, ja kaikkia, jotka outoja vaatteita kantavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Minä etsin myös niitä sillä ajalla, jotka hyppäävät kynnyksen ylitse, jotka herrainsa huoneet varkaudella ja petoksella täyttävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Sillä ajalla, sanoo Herra, pitää huudon ääni kuuluman kalaportissa, ja ulvominen toisella puolella, ja suuri surkeus kukkuloilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Ulvokaat te, jotka myllyssä asutte; sillä kaikki kaupitsia-kansa on hävitetty, ja kaikki, jotka rahaa kokoovat, ovat kadotetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Sillä ajalla tahdon minä Jerusalemin kynttilällä etsiä, ja etsiskellä niitä miehiä, jotka rahkansa päällä makaavat, ja sanovat sydämessänsä: ei Herra tee hyvästi eikä pahasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Ja heidän tavaransa pitää raatelukseksi tuleman ja huoneensa autioksi; he rakentavat huonetta, ja ei saa niissä asua, ja istuttavat viinapuita, mutta ei he saa niistä viinaa juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Sillä Herran suuri päivä on läsnä, se on läsnä sangen kiiruusti; kuin Herran päivän parku on tuleva, niin väkeväin pitää silloin haikiasti huutaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Sillä se päivä on kauheuden päivä, vaivan ja ahdistuksen päivä, tuulen ja tuulispään päivä, pimeyden ja synkeyden päivä, pilven ja sumun päivä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Basunan ja vaskitorven päivä, vahvoja kaupungeita ja korkeita linnoja vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Minä tahdon ihmisille ahdistuksen tehdä, ja heidän pitää käymän niinkuin sokiat, että he ovat Herraa vastaan syntiä tehneet; heidän verensä pitää vuodatettaman, niinkuin tomu, ja heidän lihansa niinkuin loka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ei heidän hopiansa eikä kultansa pidä heitä sinä Herran vihan päivänä voiman auttaa, vaan koko maa pitää hänen kiivautensa tulelta kulutettaman; sillä hän tekee nopiasti lopun kaikkein kanssa, jotka maassa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Kootkaat teitänne ja tulkaat tänne, te vihattava kansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Ennenkuin tuomio tulee: että te sivalletaan päivällä pois niinkuin akanat, ennekuin Herran hirmuinen vihan tulee teidän päällenne, ennekuin Herran vihan päivä tulee teidän päällenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Etsikäät Herraa, kaikkia siviät maassa, te jotka hänen oikeutensa pidätte; etsikäät vanhurskautta, etsikäät nöyryyttä, että te Herran vihan päivänä varjelluksi tulisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Sillä Gatsa pitää hyljättämän, ja Askalon autioksi tehtämän; Asdod pitää puolipäivästä ajettaman pois, ja Ekron hävitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Voi niitä, jotka meren puolessa asuvat ja ovat vahvat sotamiehet! Herran sana on tuleva teidän päällenne, te Kanaanealaiset Philistealaisten maakunnassa; minä tahdon sinun hukuttaa, ettei kenenkään pidä sinussa asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Se maa merta liki pitää paimenten majoiksi ja lammasten pihatoiksi ja laitumiksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Ja se maa pitää Juudan huoneen jääneitten oma oleman, joissa heidän pitää kaitseman, ja Askalonin huoneissa ehtoona makaaman; sillä Herra, heidän Jumalansa on heitä etsinyt, ja heidän vankiutensa palauttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Minä olen Moabin pilkan ja Ammonin lasten häväistyksen kuullut, kuin he minun kansaani häväisseet ovat, ja kerskanneet heidän rajoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Niin totta kuin minä elän, sanoo Herra Zebaot, Israelin Jumala, Moab pitää tuleman niinkuin Sodoma, ja Ammonin lapset niinkuin Gomorra, ja niinkuin nokulaspensaan ja suolakuopan, ja ijankaikkisesti hävitettynä oleman; jääneet minun kansastani pitää heitä ryöstämän, ja jääneet minun kansastani pitää heitä perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Sen pitää heille tapahtuman heidän ylpeytensä tähden, että he ovat Herran Zebaotin kansaa pilkanneet, ja siitä kerskanneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Herra on hirmuinen heitä vastaan oleva, sillä hän on kaikki jumalat maan päältä kadottava; ja kaikki pakanain luodot pitää häntä kumartaman, kukin paikastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Etiopialaiset pitää myös minun miekallani tapettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Ja hänen pitää kätensä pohjaan päin ojentaman ja Assurin kadottaman; Niniven on hän tekevä autioksi ja karkiaksi niinkuin korven.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Ja laumat pitää keskellä sitä makaaman, niiden pakanain kaikkinaiset eläimet; niin myös ruovonpäristäjät ja tarhapöllöt pitää heidän torneissansa asuman, ja äänen pitää laulaman heidän akkunissansa, ja hävitys heidän kynnyksillänsä; sillä sedrilaudat pitää revittämän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Tämä on se iloinen kaupunki, joka niin irstaana asui, ja sanoi sydämessänsä: minä olen, ja ei yksikään muu. Kuinka hän on niin autioksi tehty, että eläimet siinä makaavat? Ja joka käy sen ohitse, hän viheltää häntä, ja paukuttaa käsiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Voi sitä kauhiaa, rietasta ja väkivaltaista kaupunkia!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Ei hän tahdo kuulla, eikä antaa itsiänsä kurittaa; ei hän tahdo uskaltaa Herran päälle, eikä pidä itsiänsä Jumalansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Hänen päämiehensä ovat hänessä niinkuin kiljuvat jalopeurat, ja hänen tuomarinsa niinkuin sudet ehtoolla, jotka ei mitään jätä huomeneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Hänen prophetansa ovat irstaiset ja petturit; hänen pappinsa saastuttavat pyhyyden, ja kääntävät lain väkivaltaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Mutta Herra, joka heidän seassansa on, on vanhurskas, ja ei tee mitään väärin; vaan antaa joka aamulla oikeutensa julkisesti opettaa, eikä lakkaa; vaan väärintekiä ei taida hävetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Minä olen antanut pakanat hävittää ja heidän linnansa autioksi tehdä, ja heidän katunsa niin tyhjentää, ettei kenkään niitä pidä käymän. Heidän kaupunkinsa ovat hävitetyt, ettei kenenkään pidä niissä enään asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Minä annoin sinulle sanoa: kuitenkin pitää sinun minua pelkäämän, ja antaman sinuas kurittaa, niin ei pidä hänen asuinsiansa hävitettämän, eikä mitään, josta minä olen häntä nuhdellut; mutta he ahkeroitsevat kaikkinaista pahuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Sentähden, sanoo Herra, täytyy myös teidän minua odottaa, siihenasti kuin minäkin aikanani nousen saaliille; kuin minä myös tuomitsen, ja kokoon pakanat, ja valtakunnat yhteen saatan ja vihani heidän päällensä vuodatan, ja kaiken minun vihani hirmuisuuden; sillä koko maan pitää minun kiivauteni tuli syömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Silloin minä tahdon kansoille tosin antaa saarnata suloisilla huulilla, että heidän kaikkein pitää Herran nimeä avuksensa huutaman, ja häntä yksimielisesti palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Jotka minua kumartavat, ne hajoitetut siltä puolelta Etiopian virtoja, pitää minulle lahjaksi tuotaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Siihen aikaan ei pidä sinun enään häpeemän kaikkia sinun tekojas, joilla minua vastaan olet syntiä tehnyt; sillä minä tahdon ylpiät pyhät silloin sinun seastas ottaa pois, niin ettes enää tohdi itsiäs korottaa minun vuoreni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Minä tahdon sinusta antaa jäädä köyhän ja halvan kansan; heidän pitää Herran nimeen turvaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Jääneet Israelista ei pidä mitään pahaa tekemän, eikä valhetta puhuman, ja ei heidän suussansa pidä viekasta kieltä löydettämän; vaan he elätetään levossa, ja ei ole ketään peljättäjää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Riemuitse, sinä Zionin tytär, huuda, Israel, iloitse ja riemuitse kaikesta sydämestäs, sinä tytär Jerusalem.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Sillä Herra on sinun rangaistukses ottanut pois, ja sinun vihollises kääntänyt pois; Herra Israelin kuningas on sinun tykönäs, ettes enään pelkää onnettomuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Siihen aikaan sanotaan Jerusalemille: älä pelkää, ja Zionille: älä käsiäs laske alas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Sillä Herra sinun Jumalas on sinun tykönäs, väkevä vapahtaja; hän on sinusta suuresti riemuitseva, ja on oleva sinulle suloinen, ja antava anteeksi, ja sinusta pitää kiitoksella riemuittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Jotka murehtivat sitä, ettei he ole tulleet juhlakokoukseen, ja ovat sinusta, ne minä tahdon koota; tämä pilkka on heille kuormaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Katso, minä tahdon siihen aikaan kaikki lopettaa, jotka sinua vaivaavat, ja tahdon ontuvaisia auttaa, ja hyljätyt koota, ja saatan heidät kiitokseksi ja nimeksi kaikessa maassa, jossa he katsottiin ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Siihen aikaan tahdon minä teidät tänne tuoda, ja sillä ajalla teitä koota; sillä minä asetan teidät nimeksi ja ylistykseksi kaikkein kansain seassa maan päällä, kuin minä teidän vankiutenne käännän teidän silmäinne edessä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Toisena kuningas Dariuksen vuotena, kuudentena kuukautena, ensimäisenä päivänä kuuta, tapahtui Herran sana prophetan Haggain kautta Serubbabelille Sealtielin pojalle, Juudan päämiehelle, ja Josualle Jotsadakin pojalle, ylimmäiselle papille, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Näin puhuu Herra Zebaot, sanoen: tämä kansa sanoo: ei aika vielä ole tullut Herran huonetta rakentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Ja Herran sana tapahtui propheta Haggain kautta, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Kylläpä teidän aikanne on tullut asua kaunistetuissa huoneissanne, ja tämän huoneen täytyy autiona olla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nyt siis sanoo Herra Zebaot näin: katsokaat, kuinka teidän käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Te kylvätte paljon, ja vähän viette aittaan; te syötte, ja ette tule ravituksi; te juotte, ja ette saa kylläänne; te verhootte teitänne, ja ette tule lämpimäksi; ja joka rahaa ansaitsee, hän panee sen lävelliseen kukkaroon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Näin sanoo Herra Zebaot: katsokaat siis, kuinka teidän käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Menkäät vuorille ja hakekaat puita, ja rakentakaat huone; se on minulle otollinen oleva, ja minä tahdon minun kunniani osoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Kyllä tosin te paljon toivotte, vaan se tulee vähäksi; ja vaikka te parhaallansa kotia veisitte, niin minä sen kuitenkin puhallan pois. Miksi niin? sanoo Herra Zebaot: minun huoneeni tähden, että se on autiona, ja kukin teistä rientää oman huoneensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Sentähden on taivas teiltä kasteen pidättänyt, ja maa kieltänyt hedelmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Ja minä olen poudan kutsunut, sekä maan että vuorten päälle, jyväin, viinan, öljyn ja kaiken päälle, mitä maasta tulee, ihmisten ja karjan päälle, ja kaiken kätten työn päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Niin kuuli Serubbabel Sealtielin poika, ja Josua Jotsadakin poika, ylimmäinen pappi, ja kaikki jääneet kansasta, Herran Jumalansa äänen ja propheta Haggain sanat, niinkuin Herra heidän Jumalansa hänen lähettänyt oli; ja kansa pelkäsi Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Niin sanoi Haggai, Herran sanansaattaja, Herran käskystä kansan tykö: minä olen teidän kanssanne, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Ja Herra herätti Serubbabelin Sealtielin pojan, Juudan päämiehen hengen, ja Josuan Jotsadakin pojan, ylimmäisen papin hengen, ja kaiken jääneen kansan hengen, tulemaan ja työtä tekemään Herran Zebaotin heidän Jumalansa huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Neljäntenä päivänä kolmattakymmentä, kuudentena kuukautena, kuningas Dariuksen toisena vuotena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Ensimäisenä päivänä kolmattakymmentä, seitsemäntenä kuukautena, tapahtui Herran sana propheta Haggain kautta ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Puhu nyt Serubbabelille Sealtielin pojalle, Juudan päämiehelle, ja Josualle Jotsadakin pojalle, ylimmäiselle papille, ja jätetylle kansalle, ja sano:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kuka on jääneissä, joka tämän huoneen entisessä kunniassansa nähnyt on? ja kuinka se nyt teille näyttää? eikö se ole sen suhteen niinkuin ei mitään teidän silmäinne edessä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Ja nyt Serubbabel, ole hyvässä turvassa, sanoo Herra; ole sinäkin hyvässä turvassa, Josua Jotsadakin poika, ylimmäinen pappi; olkaat kaikka kansa maakunnassa hyvässä turvassa, sanoo Herra, ja tehkäät työtä; sillä minä olen teidän kanssanne, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Sen sanan jälkeen kuin minä tein teidän kanssanne liiton, kuin te Egyptistä vaelsitte, ja minun henkeni pitää teidän keskellänne pysymän: älkäät peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Sillä näin sanoo Herra Zebaot: vielä on vähä aikaa, niin minä taivaan, maan, meren ja mantereen saatan liikkumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Ja tahdon saattaa kaikki pakanat liikkumaan; silloin tulee kaikkein pakanain toivo, ja minä täytän tämän huoneen kunnialla, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Sillä minun on hopia ja minun on kulta, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Tämän jälkimäisen huoneen kunnia on suurempi oleva kuin ensimäisen, sanoo Herra Zebaot; ja minä tahdon antaa rauhan tälle paikalle, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Neljäntenä päivänä kolmattakymmentä, yhdeksäntenä kuukautena toisena Dariuksen vuotena, tapahtui Herran sana propheta Haggaille ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Näin sanoo Herra Zebaot: kysy papeilta lakia ja sano:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Jos joku kantais pyhitettyä lihaa helmassansa, ja satuttais sitte vaatteensa helman leipään, puuroon, viinaan, öljyyn, eli mikä ruoka se olis, tulisko se myös pyhäksi? ja papit vastasivat ja sanoivat: ei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Haggai sanoi: jos joku raadosta saastutettu yhteen näistä sattuis, tulisko se saastaiseksi? Papit vastasivat ja sanoivat: se tulee saastaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Niin Haggai vastasi ja sanoi: juuri niin on tämä kansa, ja nämät ihmiset minun edessäni, sanoo Herra, ja kaikki heidän kättensä työt, ja mitä he uhraavat, on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Ja katsokaat, kuinka teille käynyt on tästä päivästä ja ennenkuin joku kivi pantiin toisen päälle Herran templissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Että kuin joku tuli ohraläjän tykö, jolla piti kaksikymmentä mittaa oleman, niin siellä oli kymmenen; koska hän tuli viinakuurnan tykö, ja luuli viisikymmentä aamia täyttävänsä, niin siellä oli kaksikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Sillä minä vaivasin teitä poudalla, nokipäillä ja rakeilla, kaikissa teidän kättenne töissä; ette kuitenkaan kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Niin pankaat nyt mieleenne tästä päivästä ja ennen, nimittäin neljännestä päivästä kolmattakymmentä, yhdeksäntenä kuukautena, hamaan siihen päivään, jona Herran templi perustettiin, pankaat mieleenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Sillä siemenet ovat vielä salvossa, ja ei vielä mitään kasva, ei viinapuu, fikunapuu, granatipuu, eikä öljypuu; mutta tämän päivän perästä tahdon minä antaa siunauksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Ja Herran sana tapahtui toisen kerran Haggaille, neljäntenä päivänä kolmattakymmentä siinä kuukaudessa, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Sano Serubbabelille, Juudan päämiehelle: minä tahdon taivaan ja maan liikuttaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Ja tahdon valtakuntain istuimet kukistaa, ja pakanain voimalliset valtakunnat kadottaa; ja kukistan rattaat ja ratsasmiehet, niin että hevonen ja mies pitää kukistettaman, kukin kumppaninsa miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Sillä ajalla, sanoo Herra Zebaot, tahdon minä sinua korjata, sinä Serubbabel Sealtielin poika, minun palveliani, sanoo Herra, ja tahdon sinun pitää niinkuin sinettisormuksen; sillä minä olen sinun valinnut, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Kahdeksantena kuukautena toisena Dariuksen vuotena, tapahtui Herran sana Sakarjalle Berekian pojalle, Iddon pojalle, prophetalle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Herra on ollut vihainen teidän isillenne sangen kovasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Sano siis heille: näin sanoo Herra Zebaot: kääntykäät minun tyköni, sanoo Herra Zebaot; niin minä käännyn teidän tykönne, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Älkäät olko niinkuin teidän isänne, joille entiset prophetat saarnasivat, sanoen: näin sanoo Herra Zebaot: palatkaat teidän pahoista teistänne ja teidän häijystä menostanne; mutta ei he kuulleet, eikä totelleet minua, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Kussa nyt ovat teidän isänne? ja vieläkö prophetat elävät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Eikö niin ole tapahtunut, että minun sanani ja oikeuteni, jotka minä minun palveliaini prophetain kautta käskin, ovat teidän isiinne sattuneet? että heidän täytyi palata ja sanoa: niinkuin Herra Zebaot ajatteli meille tehdä meidän teittemme ja töittemme jälkeen, niin hän on myös meille tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Neljäntenä päivänä kolmattakymmentä ensimäisessä kuukaudessa toistakymmentä, joka on Sebatin kuu, toisena Dariuksen vuotena, tapahtui Herran sana Sakarjalle Berekian pojalle, Iddon pojalle, prophetalle, ja hän sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Minä näin yöllä, ja katso, mies istui ruskian hevosen päällä, ja seisahti myrttien sekaan laaksossa, ja hänen takanansa olivat ruskiat ja maksankarvaiset ja valkiat hevoset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Ja minä sanoin: minun herrani, kutka nämät ovat? Ja enkeli, joka minun kanssani puhui, sanoi minulle: minä osoitan sinulle, kutka nämät ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Ja mies, joka myrttien seassa oli, vastasi ja sanoi: nämät ovat ne, jotka Herra on lähettänyt vaeltamaan lävitse maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Mutta he vastasivat Herran enkelille, joka myrttien seassa oli, ja sanoivat: me olemme vaeltaneet maan lävitse, ja katso, kaikki maa istuu alallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Niin vastasi Herran enkeli ja sanoi: Herra Zebaot, kuinka kauvan et sinä tahdo armahtaa Jerusalemia, ja Juudan kaupungeita, joille vihainen olet ollut nyt seitsemänkymmentä ajastaikaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Ja Herra vastasi sille enkelille, joka minun kanssani puhui, hyvillä ja lohdullisilla sanoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Ja enkeli, joka minua puhutteli, sanoi minulle: saarnaa ja sano: näin sanoo Herra Zebaot: minä olen suuresti kiivastunut Jerusalemille ja Zionille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Mutta minä olen juuri vihainen myös suruttomille pakanoille; sillä minä olin ainoasti vähän vihainen, mutta he auttivat hävitykseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Sentähden näin sanoo Herra: minä palajan Jerusalemiin laupiudella, ja minun huoneeni pitää hänessä rakennettaman, sanoo Herra Zebaot; ja Jerusalemin päälle pitää mittanuora vedettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Ja saarnaa vielä ja sano: näin sanoo Herra Zebaot: taas pitää minun kaupungeilleni hyvin käymän, ja Herra on Zionia taas lohduttava, ja Jerusalem taas valitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Ja minä nostin silmäni ja näin: ja katso, siellä oli neljä sarvea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Ja minä sanoin enkelille, joka puhui minun kanssani: mitä nämät ovat? Hän sanoi minulle: nämät ovat ne sarvet, jotka Juudan, Israelin ja Jerusalemin hajoittaneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Ja Herra osoitti minulle neljä seppää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Silloin minä sanoin: mitä ne tahtovat tehdä? Hän sanoi: ne ovat ne sarvet, jotka Juudan hajoittaneet ovat, juuri niin, ettei kenkään ole voinut päätänsä nostaa; nämät ovat tulleet niitä karkottamaan, ja lohkaisemaan pakanain sarvia, jotka Juudan maan ylitse sarven nostaneet ovat sitä hajoittaaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Ja minä nostin silmäni ja näin, ja katso, miehen kädessä oli mittanuora.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Ja minä sanoin: kuhunkas menet? Mutta hän sanoi minulle: mittaamaan Jerusalemia, ja katsomaan, kuinka pitkä ja leviä se on oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Ja katso, enkeli, joka puhui minun kanssani, läksi ulos, ja toinen enkeli meni häntä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Ja sanoi hänelle: juokse tuonne, ja puhu sille pojalle ja sano: Jerusalemissa pitää ilman muureja asuttaman, ihmisten ja karjan paljouden tähden, joka siinä oleva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Ja minä tahdon olla, sanoo Herra, tulinen muuri hänen ympärillänsä, ja tahdon itse olla kunniaksi hänen keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Hoi! hoi! paetkaat pohjan maasta, sanoo Herra; sillä minä hajoitin teitä neljään tuuleen taivaan alla, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Hoi Zion, joka asut Babelin tyttären tykönä! pelasta sinus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Sillä näin sanoo Herra Zebaot: joka sen (ilmoitetun) kunnian jälkeen lähetti minun niiden pakanain tykö, jotka teitä raatelivat: joka teihin rupee, se rupee hänen silmänsä terään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Sillä katso, minä nostan käteni heidän ylitsensä, että heidän pitää oleman niille saaliiksi, jotka ennen heitä palvelivat; että teidän pitää ymmärtämän Herran Zebaotin minua lähettäneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Veisaa ja riemuitse, Zionin tytär; sillä katso, minä tulen ja tahdon asua sinun tykönäs, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Silloin pitää paljon pakanoita Herrassa kiinni riippuman, jotka minun kansani pitää oleman: ja minä tahdon asua sinun tykönäs, ettäs ymmärtäisit Herran Zebaotin lähettäneen minun sinun tykös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Ja Herra on perivä Juudan osaksensa siinä pyhässä maassa, ja on taas Jerusalemin valitseva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Vaijetkoon kaikki liha Herran edessä; sillä hän on noussut pyhästä asuinsiastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Ja hän osoitti minulle ylimmäisen papin Josuan, joka seisoi Herran enkelin edessä: ja saatana seisoi hänen oikialla kädellänsä, seisomassa häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Ja Herra sanoi saatanalle: Herra rangaiskoon sinua, saatana, se Herra sinua rangaiskoon, joka Jerusalemin valitsi! Eikö tämä ole kekäle, joka tulesta temmattu on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Ja Josua oli puetettu saastaisilla vaatteilla, ja seisoi enkelin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Joka vastasi ja sanoi niille, jotka hänen tykönänsä olivat, sanoen: ottakaat häneltä pois saastaiset vaatteet; ja hän sanoi hänelle: katso, minä olen ottanut sinulta pois sinun syntis, ja puettanut sinun juhlavaatteisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Ja sanoi: pankaat puhdas lakki hänen päähänsä. Ja he panivat puhtaan lakin hänen päähänsä, ja puettivat hänen vaatteisiin. Ja Herran enkeli seisoi siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Ja Herran enkeli todisti Josualle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Näin sanoo Herra Zebaot: jos sinä vaellat minun teilläni, ja jos sinä pidät minun vartioni, niin sinä saat minun huonettani hallita, ja minun kartanoitani varjella; ja minä annan sinulle näistä muutamia, jotka tässä seisovat, saattamaan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Kuule nyt, Josua, sinä ylimmäinen pappi, sinä ja sinun ystäväs, jotka sinun edessäs asuvat; sillä he ovat ihmeelliset miehet: katso, minä annan palveliani, Vesan tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Sillä katso, se on se kivi, jonka minä panen Josuan eteen, ja sillä yhdellä kivellä on seitsemän silmää; katso, minä tahdon sen vuolla, sanoo Herra Zebaot, ja tahdon sen maan synnit ottaa pois yhtenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Silloin, sanoo Herra Zebaot, kukin kutsuu kumppaninsa viinapuunsa ja fikunapuunsa alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Ja enkeli, joka minun kanssani puhui, tuli jälleen ja herätti minun, niinkuin joku unestansa herätettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Ja sanoi minulle: mitäs näet? Mutta minä sanoin: minä näen, ja katso, kynttiläjalka seisoi kokonansa kullasta, ja malja sen pään päällä, ja seitsemän lamppua oli hänessä, ja seitsemän kauhaa kussakin lampussa, jotka olivat sen pään päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Oli myös sen tykönä kaksi öljypuuta: yksi maljan oikialla puolella ja toinen vasemmalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Ja minä vastasin ja sanoin sille enkelille, joka minun kanssani puhui, sanoen: minun herrani, mikä se on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Ja enkeli, joka minun kanssani puhui, vastasi ja sanoi minulle: etkös tiedä, mikä se on? Mutta minä sanoin: en, minun herrani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Ja hän vastasi ja puhui minulle, sanoen: se on Herran sana Serubbabelista, joka sanoo: ei se pidä tapahtuman sotaväellä eikä voimalla, vaan minun hengelläni, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Kuka sinä olet, suuri vuori? jonka kuitenkin täytyy Serubbabelin edessä tasaiseksi kedoksi tulla; ja hänen pitää ensimäisen kiven laskeman, ja pitää huutaman: armo, armo olkoon hänelle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Serubbabelin kädet ovat tämän huoneen perustaneet, hänen kätensä pitää myös sen päättämän, tietääkses, että Herra on minun lähettänyt teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Sillä kuka on se, joka nämät halvat päivät katsoo ylön? jossa kuitenkin pitää iloittaman, ja nähtämän muurin luoti Serubbabelin kädessä, ja ne seitsemän Herran silmää, jotka katselevat kaikkea maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Ja minä vastasin ja sanoin hänelle: mitä nämät kaksi öljypuuta, jotka ovat oikialla ja vasemmalla puolella kynttilänjalkaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Ja minä vastasin toisen kerran ja sanoin hänelle: mitä nämät kaksi öljypuun oksaa, jotka ovat kahden kultaisen piipun keskellä, joista kultainen öljy vuotaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Ja hän sanoi minulle: etkös tiedä, mitä nämät ovat? Ja minä sanoin; en, minun herrani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Ja hän sanoi: ne ovat kaksi öljypuuta täynnä öljyä, jotka aina seisovat kaiken maan Herran tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Ja minä taas nostin silmäni ja näin, ja katso, siinä oli lentävä kirja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Ja hän sanoi minulle: mitäs näet? Mutta minä sanoin: minä näen lentävän kirjan, joka on kaksikymmentä kyynärää pitkä ja kymmenen kyynärää leviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Ja hän sanoi minulle: se on se kirous, joka käy kaiken maan ylitse: sillä jokainen varas tästä (kansasta) niinkuin muistakin sanoo itsensä viattomaksi; ja kaikki valapattoiset tästä niinkuin muutkin sanovat itseänsä viattomaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Mutta minä tahdon sen tuottaa edes, sanoo Herra Zebaot, että sen pitää tuleman varkaan huoneesen, ja sen huoneesen, joka minun nimeni kautta väärin vannoo: ja sen pitää pysymän heidän huoneessansa; ja se on sen kuluttava puinensa ja kivinensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Ja enkeli, joka minun kanssani puhui, läksi ulos, ja sanoi minulle: nosta nyt silmäs ja katso, mitä sieltä käy ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Ja minä sanoin: mikä se on? Hän sanoi: sieltä käy ephan mitta ulos; ja sanoi: se on heidän näkönsä kaikessa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Ja katso, lyijyinen kansi nousi auki; ja siellä istui yksi vaimo keskellä ephaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Ja hän sanoi: se on jumalattomuus; ja hän heitti sen keskelle mittaa, ja laski lyijyn kappaleen myös mitan suulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Ja minä nostin silmäni ja näin, ja katso, kaksi vaimoa läksi ulos, joilla olivat siivet, joita tuuli ajoi, ja heidän siipensä olivat niinkuin nälkäkurjen siivet, ja ne nostivat ephan mitan maan ja taivaan välille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Ja minä sanoin enkelille, joka minun kanssani puhui: kuhunka he sen mitan vievät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Hän sanoi minulle: että hänelle rakennettaisiin huone Sinearin maalla, ja se valmistettaisiin, ja asetettaisiin perustuksensa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Ja minä taas nostin silmäni ja näin: ja katso, siellä olivat neljät rattaat, jotka lähtivät kahden vuoren välistä; ja ne vuoret olivat vaskiset vuoret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Ensimäisten ratasten edessä olivat ruskiat orhiit, ja toisten ratasten edessä mustat orhiit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'Mutta kolmanten ratasten edessä valkiat orhiit, ja neljänten ratasten edessä kirjavat, väkevät orhiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Ja minä vastasin ja sanoin enkelille, joka minun kanssani puhui: minun herrani, mitä nämät ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Ja enkeli vastasi ja sanoi minulle: ne ovat neljä tuulta taivaan alla, jotka tulevat ulos, astumaan kaiken maan hallitsian eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Jossa ne mustat orhiit, ne menivät pohjaa päin, ja valkiat noudattivat niitä; mutta kirjavat menivät etelää päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Ja ne väkevät läksivät ja menivät ympärinsä, niin että he kaikki maat vaelsivat. Ja hän sanoi: menkäät ja vaeltakaat maata ympäri; ja he vaelsivat maan lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Ja hän kutsui minua, puhutteli minua ja sanoi: katso, ne jotka pohjaan menevät, antavat minun henkeni levätä pohjan maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Ja Herran sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Ota vangeilta, Heldailta ja Tobialta ja Jedajalta, ja tule jälleen sinä päivänä, ja mene Josian Zephanjan pojan huoneeseen, jotka Babelista tulleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Mutta ota hopiaa ja kultaa, ja tee kruunuja, ja pane Josuan Jotsadakin pojan, ylimmäisen papin päähän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Ja sano hänelle: näin sanoo Herra Zebaot: katso, yksi mies on, jonka nimi on Vesa; sillä hänen allansa pitää kasvaman, ja hän on rakentava Herran templin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Ja Herran templin on hän rakentava, ja hänen pitää kunnian kantaman, istuman ja hallitseman istuimellansa, ja oleman papin istuimellansa, ja heillä pitää molemmilla rauha oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Ja ne kruunut pitää oleman Helemin, Tobian, Jedajan ja Henin, Zephanjan pojan, muistoksi Herran templissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Heidän pitää kaukaa tuleman ja rakentaman Herran templin, ja teidän pitää ymmärtämän Herran Zebaotin lähettäneen minun teidän tykönne. Tämä pitää tapahtuman, jos te muutoin Herran teidän Jumalanne äänelle hyvin kuuliaiset olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Ja neljäntenä kuningas Dariuksen vuotena tapahtui Herran sana Sakarjalle, neljäntenä päivänä yhdeksännessä kuukaudessa, joka kutsutaan Kislev.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Kuin he lähettivät Sareserin, ja Regemmelekin, ja heidän miehensä Jumalan huoneeseen rukoilemaan Herran eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'Ja sanomaan papeille, jotka olivat Herran Zebaotin huoneessa, ja prophetaille: vieläkö minun nyt pitää itkemän viidentenä kuukautena, ja vaivaaman minuani, niinkuin minä tähän asti muutamina vuosina tehnyt olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Ja Herran Zebaotin sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Puhu kaikelle maan kansalle ja papeille, sanoen: kuin te paastositte ja paruitte viidennellä ja seitsemännellä kuukaudella, nyt seitsemänkymmentä vuotta, oletteko te minulle paastonneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Ja kuin te syötte ja juotte, ettekö te syö ja juo itse teillenne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Eikö tämä se ole, jota Herra antoi entisten prophetain saarnata, kuin vielä Jerusalemissa asuttiin, ja oli lepo kaupungeissa ympärillä, kuin asuttiin sekä etelään päin että laaksoissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Ja Herran sana tapahtui Sakarjalle, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Näin sanoo Herra Zebaot: tuomitkaat oikein, ja tehkäät jokainen hyvää ja laupiutta veljellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Ja älkäät tehkö vääryyttä leskille ja orvoille, muukalaisille ja köyhille: ja älkään kenkään ajatelko pahaa sydämessänsä veljiänsä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Mutta ei he näistä tahtoneet ottaa vaaria, vaan käänsivät selkänsä minua vastaan, ja tukitsivat korviansa, ettei he kuulisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Ja asettivat sydämensä niinkuin timantin, ettei he kuulisi lakia ja sanoja, jotka Herra Zebaot hengellänsä lähetti entisten prophetain kautta: sentähden on niin suuri viha Herralta Zebaotilta tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Ja se on niin tapahtunut kuin saarnattiinkin; mutta ettei he tahtoneet kuulla, niin en minäkään tahtonut kuulla, kuin he huusivat, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Ja niin minä olen heidät hajoittanut kaikkein pakanain sekaan, joita ei he tunteneet; ja maa on heidän jälkeensä autioksi jäänyt, ettei kenkään siinä vaella eikä asu; sillä he ovat sen ihanan maan hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Ja Herran Zebaotin sana tapahtui (minulle) ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Näin sanoo Herra Zebaot: minä olen Zionin tähden suuresti kiivannut, ja olen suuressa vihassa sentähden kiivannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Näin sanoo Herra: minä käännyn taas Zionin tykö, ja tahdon asua Jerusalemin keskellä; niin että Jerusalem pitää totuuden kaupungiksi kutsuttaman, ja Herran Zebaotin vuori pyhyyden vuoreksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Näin sanoo Herra Zebaot: vielä nyt pitää Jerusalemin kaduilla asuman vanhat miehet ja vaimot, jotka sauvan päälle nojaavat vanhuutensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Ja kaupungin kadut pitää oleman täynnä pieniä poikia ja piikaisia, jotka sen kaduilla leikitsevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Näin sanoo Herra Zebaot: jos tämä on ihmeellinen tämän jääneen kansan silmäin edessä, pitäiskö se sentähden oleman ihmeellinen minun silmäini edessä? sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Näin sanoo Herra Zebaot: katso, minä tahdon lunastaa minun kansani itäiseltä maalta ja länsimaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Ja minä tahdon heitä saattaa Jerusalemiin asumaan; ja heidän pitää minun kansani oleman, ja minä tahdon olla heidän Jumalansa totuudessa ja vanhurskaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Näin sanoo Herra Zebaot: vahvistakaat kätenne, te jotka tällä ajalla nämät sanat kuulette prophetain suun kautta, sinä päivänä, jona Herran Zebaotin huoneen perustus laskettiin, sen rakennettavaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Sillä ennen näitä päiviä olivat ihmisten työt turhat, ei juhtain työ myös mitään ollut; eikä ollut niillä rauhaa vihollisilta, jotka menivät ulos ja sisälle; vaan minä sallin kaikki ihmiset mennä, jokaisen lähimmäistänsä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Mutta en minä niin tahdo nyt tehdä tälle jääneelle kansalle, niinkuin entisinä päivinä, sanoo Herra Zebaot;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Vaan heidän pitää rauhan siemen oleman: viinapuu pitää hedelmänsä antaman, ja maa kasvunsa, taivas pitää kasteensa antaman, ja jääneet minun kansastani pitää nämät kaikki omistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Ja pitää tapahtuman, että teitä, jotka Juudan ja Israelin huoneesta olette olleet kirous pakanain seassa, tahdon minä lunastaa, että teidän pitää siunauksen oleman. Niin älkäät siis peljätkö, mutta vahvistakaat kätenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Sillä näin sanoo Herra Zebaot: niinkuin minä ajattelin teitä kadottaa, kuin teidän isänne minun vihoittivat, sanoo Herra Zebaot, ja en sitä katunut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Niin minä nyt jälleen ajattelen näinä päivinä tehdä hyvää Jerusalemille ja Juudan huoneelle. Älkäät peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Mutta tämä on se, minkä teidän tekemän pitää: jokainen puhukaan totuutta lähimmäisensä kanssa; tuomitkaat oikein ja saattakaat rauha teidän portteihinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Ja älkään kenkään ajatelko pahaa sydämessänsä, lähimmäistänsä vastaan, ja älkäät rakastako vääriä valoja; sillä näitä kaikkia minä vihaan, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Ja Herran Zebaotin sana tapahtui minulle ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Näin sanoo Herra Zebaot: neljännen, viidennen, seitsemännen ja kymmenennen kuukauden paastot pitää kääntymän Juudan huoneelle iloksi ja riemuksi ja ihanaiseksi vuoden juhlaksi. Rakastakaat ainoasti totuutta ja rauhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Näin sanoo Herra Zebaot: tästedes pitää vielä paljo kansaa tuleman, ja monen kaupungin asuvaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Ja yhden asuvaiset pitää menemän toisen tykö ja sanoman; käykäämme vilpittömästi rukoilemaan Herran kasvoin eteen, ja etsimään Herraa Zebaotia; minä tahdon myös käydä teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Niin tulee paljo kansaa ja pakanat tulevat joukoin, etsimään Herraa Zebaotia Jerusalemiin, ja rukoilemaan Herran kasvojen eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Näin sanoo Herra Zebaot: sillä ajalla pitää kymmenen miestä kaikkinaisista pakanain kielistä todella tarttuman yhden Juudan miehen vaatteen palteesen, ja sanoman: me tahdomme käydän teidän kanssanne; sillä me kuulimme, että Jumala on teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Tämä on Herran sanan kuorma Hadrakin maasta, ja Damaskusta, jossa se on pysyvä; sillä Herralla on silmä, joka näkee ihmiset ja kaikki Israelin sukukunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Niin myös Hamatista, joka heidän rajassansa on, ja Tyrosta ja Sidonista, jotka ylen viisaat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Sillä Tyro rakentaa itsellensä linnaa ja kokoo hopiaa niinkuin santaa, ja kultaa niinkuin lokaa kaduilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Katso, Herra ajaa ulos hänen, ja lyö alas hänen voimansa, joka hänellä merellä on: ja hän pitää tulella kulutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Kuin Askalon sen näkee, niin hän peljästyy, ja Gatsan pitää kovin surullisen oleman, niin myös Ekron, että hänen toivonsa on häpiään tullut; sillä ei Gatsassa pidä kuningasta oleman, eikä Askalonissa asuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Asdodissa pitää muukalaisen äpärän asuman, ja niin pitää Philistealaisten ylpeys lyötämän maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Ja minä tahdon ottaa pois heidän verensä heidän suustansa ja heidän kauhistuksensa heidän hampaistansa; että he myös jäisivät meidän Jumalallemme, ja olisivat niinkuin päämiehet Juudassa, ja Ekron olis niinkuin Jebusilaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Ja minä tahdon itse minun huoneeni piirittää sotaväellä, jotka vaeltavat ulos ja sisälle, ettei heitä enään pidä vaatian vaivaaman; sillä minä katsoin nyt sitä minun silmilläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Iloitse, sinä Zionin tytär, suuresti, ja riemuitse, sinä Jerusalemin tytär! Katso, sinun kuninkaas tulee sinulle, vanhurskas, ja auttaja, köyhä, ja ajaa aasilla ja aasin tamman varsalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Sillä minä tahdon maahan lyödä rattaan Ephraimista ja hevosen Jerusalemista, ja sodan joutsi pitää särjettämän; sillä hän puhuu ystävällisesti pakanain seassa, ja hänen hallituksensa on oleva merestä hamaan mereen asti, ja virrasta hamaan maailman loppuun asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Sinä lasket myös liittos veren kautta vankis ulos vedettömästä kuopasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Niin palatkaat siis linnaan, te jotka toivossa vangitut olette; sillä tänäpänä minä tahdon myös ilmoittaa, ja kaksinkertaisesti sinulle maksaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Sillä minä olen Juudan minulleni joutseksi vetänyt, ja Ephraimin valmistanut; ja tahdon sinun lapses, Zion, herättää Grekan maan lapsia vastaan, ja asetan sinun niinkuin sankarin miekan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Herra on heille ilmestyvä, ja hänen nuolensa pitää lähtemän ulos niinkuin pitkäisen leimaus; ja Herra, Herra, on basunalla soittava, ja menee niinkuin lounatuulen pyöriäiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Herra Zebaot on heitä suojeleva, että he söisivät, ja saisivat allensa linkokivillä, ja joisivat ja riemuitsisivat niinkuin viinasta, ja tulisivat täyteen niinkuin malja, ja niinkuin alttarin kulmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Ja Herra heidän Jumalansa on heitä sillä ajalla auttava, niinkuin kansansa laumaa; sillä pyhät kivet pitää merkiksi hänen maallensa nostettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Sillä kuinka paljo hyvää heillä on, ja kuinka suuri kauneus heillä on? Jyvät siittävät nuorukaiset ja viina neitseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Anokaat Herralta ehtoo sadetta, niin Herra tekee pilven, ja antaa teille kyllä sataa, kaikelle kedon kasvulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Sillä epäjumalat puhuvat turhuutta, ja aavistajat näkevät valheen; ja puhuvat turhia unia, ja heidän lohdutuksensa ei ole mitään: sentähden he käyvät eksyksissä niinkuin lampaat, ja nääntyvät, ettei heillä ole yhtään paimenta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Minun vihani on julmistunut paimenten päälle, ja minä tahdon kauriit etsiä; sillä Herran Zebaot on etsivä laumansa, Juudan huoneen, ja valmistaa heitä niinkuin hankituita sotahevosia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Häneltä ovat nurkat, häneltä naulat, häneltä sotajoutsi, häneltä myös ynnä kaikki vaatiat tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Ja heidän pitää kuitenkin oleman niinkuin sankarit, jotka loan tallaavat kaduilla sodassa, ja pitää sotiman, sillä Herra on heidän kanssansa, että ratsasmiehet häpiään tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Ja minä tahdon vahvistaa Juudan huoneen, ja varjella Josephin huonetta, ja tahdon heitä asettaa jälleen sijoillensa; sillä minä armahdan heitä; ja he ovat niinkuin he ennenkin olivat, kuin minä heidät sysäsin pois; sillä minä Herra heidän Jumalansa tahdon heitä kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Ja Ephraim on oleva niinkuin sankari, ja heidän sydämensä on iloitseva niinkuin viinasta; ja heidän lapsensa saavat myös sen nähdä, ja riemuitsevat, että heidän sydämensä on iloinen Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Minä tahdon heille viheltää, ja koota heitä, sillä minä tahdon heitä lunastaa; ja he lisääntyvät niinkuin he ennenkin olleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Ja tahdon kylvää heitä kansain sekaan, että he muistaisivat minua kaukaisissa maakunnissa, ja eläisivät lastensa kanssa ja palajaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Sillä minä tahdon heitä tuoda jälleen Egyptin maalta, ja koota heitä Assyriasta, ja saattaa heitä Gileadin maahan ja Libanoniin, ja ei siinäkään pidä heillä kyllä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Ja hänen pitää käymän sen ahtaan meren lävitse, ja meren aaltoja lyömän, että kaikki ojain syvyydet kuivuisivat; silloin Assyrian ylpeys alennetaan, ja Egyptin valtikka lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Minä tahdon heitä vahvistaa Herrassa, ja heidän pitää vaeltaman hänen nimeensä, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Avaa, Libanon, porttis, että tuli sinun sedripuus polttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Ulvokaat, te hongat, sillä sedripuut ovat langenneet, ja ylimmäiset ovat hävitetyt. Ulvokaat, te Basanin tammet; sillä vahva metsä on hakattu pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Paimenet kuullaan ulvovan, sillä heidän väkevänsä ovat hävitetyt; jalopeurain penikkain kiljumus kuullaan, sillä Jordanin ylpeys on hävitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Näin sanoo Herra minun Jumalani: kaitse teuraslampaita;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Sillä heidän omistajansa teurastavat niitä, ja ei luule siitä syntiä olevan; myyvät niitä, ja sanovat: kiitetty olkoon Herra, että minä olen rikastunut; ja ei heidän paimenensa heitä säästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Sentähden en minä tahdo enää säästää maan asuvaisia, sanoo Herra; ja katso, minä jätän ihmisen jokaisen kumppaninsa käsiin, ja heitä kuninkainsa käsiin, että he maan musertaisivat, enkä tahdo heitä auttaa heidän käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Ja minä kaitsen teuraslampaita, raadollisten lammasten tähden. Ja minä otin minulleni kaksi sauvaa: yhden minä kutsuin suloiseksi, mutta toisen sitovaiseksi, ja kaitsin lampaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Ja minä hukutin kolme paimenta yhtenä kuukautena; sillä en minä voinut heitä kärsiä, eikä he minuakaan kärsineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Ja minä sanoin: en minä tahdo teitä kaita; joka kuolee, se kuolkaan, joka nääntyy, se nääntyköön, ja jääneet syököön toinen toisensa lihan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Ja minä otin suloisen sauvani ja särjin sen, rikkoakseni minun liittoni, jonka minä kaikille kansoille tehnyt olin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Ja se rikottiin sinä päivänä; ja raadolliset lampaat, jotka minun kanssani pitivät, tunsivat siitä, että se Herran sana oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Ja minä myös sanoin heille: jos teille niin kelpaa, niin tuokaat tänne niin paljon kuin minä maksan; jollei, niin sallikaat olla; ja he punnitsivat niin paljon kuin minä maksoin, kolmekymmentä hopiapenninkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Niin sanoi Herra minulle: heitä se pois, annettavaksi savenvalajalle; sitä suurta hintaa, johon minä heiltä arvattu olen! Ja minä oltin ne kolmekymmentä hopiapenninkiä ja heitin Herran huoneeseen, annettavaksi savenvalajalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Ja minä särjin minun toisen sitovaisen sauvani, rikkoakseni veljeyden Juudan ja Israelin vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Ja Herra sanoi minulle: ota vielä itselles hullun paimenen aseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Sillä katso, minä herätän paimenen maassa, joka ei etsi nääntyvää, ei holho nuorta heikkoa, ei paranna särjettyä, eikä tottele tervettä; vaan syö lihavain lihaa, ja repäisee heidän sorkkansa rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Voi sitä kelvotointa paimenta, joka lauman hylkää! tulkaan miekka hänen käsivarteensa ja oikiaan silmään; kuivukoon hänen käsivartensa peräti, ja hänen oikea silmänsä tulkoon kokonansa pimiäksi!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Tämä on Herran sanan kuorma Israelista: Herra, joka taivaat venyttää, ja maan perustaa, ja tekee ihmisen hengen hänessä, sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Katso, minä tahdon Jerusalemin tehdä unimaljaksi kaikille kansoille siinä ympärillä; sillä sen pitää myös Juudaa kohtaaman, kuin Jerusalem piiritetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Ja sillä ajalla tahdon minä Jerusalemin tehdä kaikille kansoille kuormakiveksi; niin monta kuin häntä siirtää tahtovat, pitää itsensä siihen rikki repimän; sillä kaikki pakanat maan päällä kokoontuvat häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Silloin, sanoo Herra, tahdon minä kaikki hevoset pelkuriksi saattaa, ja heidän ratsastajansa tyhmäksi; mutta Juudan huoneelle tahdon minä avata minun silmäni, ja kaikki kansain hevoset lyödä sokeudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Ja Juudan päämiesten pitää sanoman sydämessänsä: olkoon Jerusalemin asuvaiset vain hyvässä turvassa, Herrassa Zebaotissa, heidän Jumalassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Sillä ajalla tahdon minä panna Juudan päämiehet niinkuin tulipätsiksi puiden sekaan, ja niinkuin tulisoiton jalallisen, syömään sekä oikialta että vasemmalta puolelta kaikki kansat ympäriltä; ja Jerusalem asutaan taas siallansa Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Ja Herra on vapahtava Juudan majat niinkuin alustakin, ettei Davidin huoneen kunnia ylen paljo kerskaisi, eikä Jerusalemin asuvaisen kunnia, Juudaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Niinä päivinä on Herra Jerusalemin asuvaiset varjelevat; ja on tapahtuva, että se, joka silloin heidän seassansa heikko on, on oleva niinkuin David, ja Davidin huone on oleva niinkuin Jumalan huone, niinkuin Herran enkeli heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Silloin ajattelin minä hukuttaa kaikkia pakanoita, jotka ovat lähteneet Jerusalemia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Mutta Davidin huoneelle ja Jerusalemin asuvaisille tahdon minä vuodattaa armon ja rukouksen hengen; sillä heidän pitää katsoman minun puoleeni, jonka he lävitse pistäneet ovat; ja pitää valittaman, niinkuin joku valittaa ainokaista poikaansa, ja heidän pitää häntä murehtiman, niinkuin joku itkis esikoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Silloin pitää suuren valitusitkun oleman Jerusalemissa, niinkuin Hadadrimmonin itku Megiddon kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Ja maan pitää valittaman, jokainen sukukunta erinänsä; Davidin huoneen sukukunta erinänsä, ja heidän vaimonsa erinänsä; Natanin huoneen sukukunta erinänsä, ja heidän vaimonsa erinänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Levin huoneen sukukunta erinänsä, ja heidän vaimonsa erinänsä; Simein huoneen sukukunta erinänsä, ja heidän vaimonsa erinänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Niin myös kaikki muut jääneet sukukunnat, kukin erinänsä, ja heidän vaimonsa myös erinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Sillä ajalla on avoin lähde Davidin huoneelle ja Jerusalemin asuvaisille oleva syntiä ja saastaisuutta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Sillä ajalla, sanoo Herra Zebaot, tahdon minä epäjumalain nimet maasta kadottaa, ettei heitä enään pidä muistettaman; tahdon myös väärät prophetat ja saastaisen hengen ajaa pois maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Ja pitää tapahtuman, että jos joku vielä ennustais, niin hänen isänsä ja äitinsä, jotka hänen synnyttäneet ovat, pitää hänelle sanoman: et sinä saa elää, sillä sinä olet valehdellut Herran nimeen. Ja niin hänen isänsä ja äitinsä, jotka hänen synnyttäneet ovat, pitää hänen pistämän lävitse, kuin hän ennustaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Sillä silloin pitää tapahtuman, että prophetat näkyinsä kanssa tulevat häpiään, kuin he ennustavat; ja ei heidän pidä enää yllensä pukevan karvavaatteita, joilla he viettelevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Mutta pitää sanoman: en minä ole propheta, vaan minä olen peltomies; sillä minä olen nuoruudestani orjana ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Mutta jos hänelle sanottaisiin: mitkä haavat ovat sinun käsissäs? niin hänen pitää vastaaman: niin minä olen haavoitettu niiden huoneessa, jotka minua rakastivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Herää, miekka minun paimeneni päälle ja sen miehen päälle, joka minulle lähinen on, sanoo Herra Zebaot: lyö paimenta, niin lampaat hajoovat! ja niin minä käteni käännän piskuisia päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Ja pitää tapahtuman, sanoo Herra, että jokaisessa maakunnassa kaksi osaa häviää ja hukkuu, ja kolmas osa siihen jääpi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Ja kolmannen osan tahdon minä viedä tulen lävitse, ja puhdistaa sen, niinkuin hopia puhdistetaan, ja tahdon sen kirkastaa, niinkuin kulta kirkastetaan. Nämät minun nimeäni avuksi huutavat, ja minä tahdon heitä kuulla, ja sanoa: se on minun kansani; ja heidän pitää sanoman: Herra minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Katso, päivä tulee Herralle, jona sinun saaliis sinussa jaetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Sillä minä olen kokoova kaikkinaiset pakanat sotaan Jerusalemia vastaan, ja kaupunki voitetaan, huoneet ryöstetään ja vaimot raiskataan. Puoli osaa kaupunkia viedään vangiksi, ja jääneitä kansasta ei ajeta ulos kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Mutta Herra on lähtevä sotimaan pakanoita vastaan, niinkuin hän on tottunut sodan ajalla sotimaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Silloin hänen jalkansa pitää Öljymäellä seisoman, joka on läsnä Jerusalemia itään päin; ja Öljymäen pitää halkeeman keskeltä itään ja länteen, sangen leviältä toinen toisestansa; toinen osa mäkeä pitää erkaneman pohjoiseen päin ja toinen etelään päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Ja teidän pitää pakeneman sitä laaksoa, joka on näiden vuorten vaiheella, sillä se laakso mäkien vaiheella pitää ulottuman Atsaliin asti; ja pitää paettaman niinkuin muinen paettiin maanjäristyksen tähden, Ussian Juudan kuninkaan aikana. Silloin Herra minun Jumalani on tuleva, ja kaikki pyhät hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Ja siihen aikaan pitää tapahtuman, ettei valkeus pidä oleman kallis eikä sumuinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Ja yksi päivä on oleva, joka Herralle tuttu on, ei päivä eikä yö; vaan pitää tapahtuman, että ehtoona pitää valkeus oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Silloin pitää Jerusalemista elävät vedet vuotaman, puoli osa itäistä merta päin, ja toinen puoli hamaan äärimäiseen mereen; ja sen pitää sekä kesällä että talvella tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Ja Herra on kaiken maan Kuningas oleva; siihen aikaan on ainoastaan yksi Herra oleva, ja hänen nimensä yksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Ja koko maakunnassa pitää käytämän ympäri niinkuin tasaisella kedolla, Gibeasta niin Rimmoniin asti, lounaan puolella Jerusalemia; sillä se korotetaan ja asutaan hänen siassansa, Benjaminin portista hamaan ensimäisen portin paikkaan, hamaan Kulmaporttiin, ja Hananeelin tornista niin kuninkaan viinakuurniin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Ja hänessä pitää asuttaman, eikä enään pidä yhtään kirousta oleman, sillä Jerusalemin pitää turvallisesti asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Ja tämä on rangaistus oleva, jolla Herra kaikkia kansoja on rankaiseva, jotka ovat sotineet Jerusalemia vastaan: heidän lihansa pitää raukeaman jaloillansa seisoissansa, ja heidän silmänsä pitää lävissänsä vaipuman, ja heidän kielensä suussansa raukeaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Siihen aikaan on Herra suuren metelin heidän sekaansa nostava, että jokainen pitää kumppaninsa käteen rupeeman, ja paneman kätensä kumppaninsa käden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Sillä Juuda on myös Jerusalemissa sotiva; ja sen ympärille kootaan kaikkein pakanain tavarat, kultaa, hopiaa ja sangen paljo vaatteita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Ja niin on tämä rangaistus tapahtuva hevosille, muuleille, kameleille, aaseille ja kaikkinaisille eläimille, jotka heidän leirissänsä ovat, niinkuin tämä rangaistus on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Ja kaikki jääneet kaikkein pakanain seassa, jotka läksivät Jerusalemia vastaan, menevät joka vuosi kumartamaan Kuningasta, Herraa Zebaotia, ja lehtimajan juhlaa pitämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Ja on tapahtuva, että joka maan sukukunnista ei mene ylös Jerusalemiin tätä Kuningasta, Herraa Zebaotia, kumartamaan, ei pidä heille sadetta tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Ja ellei Egyptiläisten sukukunta menisi ylös ja tulisi, niin ei heidänkään päällensä pidä sataman; tämä on se rangaistus, jolla Herra on pakanat rankaiseva, jotka ei tule lehtimajan juhlaa pitämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Sillä se on Egyptiläisten synti ja kaikkein pakanain synti, jotka ei tule lehtimajan juhlaa pitämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Siihen aikaan pitää hevosten kelloin päälle (kirjoitettu) oleman: Herran pyhyys; ja kattilat Herran huoneessa pitää oleman niinkuin maljat alttarin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Sillä kaikki kattilat Jerusalemissa ja Juudassa pitää Herralle Zebaotille pyhitetyt oleman; että kaikkein, jotka uhrata tahtovat, pitää tuleman ja ne ottaman ja niissä keittämän. Ja ei yksikään Kanaanealainen pidä enää Herran Zebaotin huoneessa oleman siihen aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Tämä on Herran sanan kuorma Israelin tykö, Malakian kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Minä rakastin teitä, sanoo Herra. Niin te sanotte: missäs meitä rakastit? Eikö Esau ole Jakobin veli, sanoo Herra? ja minä rakastin Jakobia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Ja vihasin Esauta; olen myös autioksi tehnyt hänen vuorensa, ja hänen perimisensä lohikärmeille erämaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Ja jos Edom sanois: me olemme köyhtyneet, mutta me tahdomme autiot jälleen rakentaa; niin sanoo Herra Zebaot näin: jos he rakentavat, niin minä tahdon maahan kukistaa; ja ne pitää kutsuttaman jumalattomuuden rajaksi ja siksi kansaksi, jolle Herra on vihainen ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Sen pitää teidän silmänne näkemän, ja teidän pitää sanoman: Herra on ylistetty Israelin maan äärissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Pojan pitää kunnioittaman isäänsä, ja palvelian isäntäänsä. Jos minä siis isä olen, kussa on minun kunniani? Jos minä isäntä olen, kussa on minun pelkoni? sanoo Herra Zebaot teille, papit, jotka katsotte ylön minun nimeni. Niin te sanotte: missä me katsomme ylön sinun nimes?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Silloin kuin te uhraatte minun alttarilleni saastaista leipää. Niin te sanotte: kuinka me uhraamme sinulle saastaista? Siinä että te sanotte: Herran pöytä on katsottu ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Ja kuin te uhraatte jotakin, joka sokia on, niin ette sano sitä pahaksi; ja kuin te uhraatte jotakin ontuvaa eli sairasta, niin ei sitäkään sanota pahaksi. Vie senkaltaista sinun päämiehilles, mitämaks, jos sinä olet hänelle otollinen, eli jos hän katsoo sinun puolees, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Niin rukoilkaat nyt Jumalaa, että hän armahtais meidän päällemme, sillä se on tapahtunut teiltä. Luuletteko, että hän katsoo teidän puoleenne? sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Kuka on myös teidän seassanne, joka sulkee oven (ilman palkkaa)? ette myös viritä tulta minun alttarilleni ilman mitäkään. Ei minulla ole suosiota teihin, sanoo Herra Zebaot, ja ruokauhri teidän käsistänne ei ole minulle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Vaan hamasta auringon koitosta niin laskemiseen asti pitää minun nimeni suureksi tuleman pakanain seassa, ja jokapaikassa pitää minun nimelleni suitsutettaman, ja puhdas ruokauhri uhrattaman; sillä minun nimeni pitää suureksi tuleman pakanain seassa, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Mutta te turmelette sen sillä, kuin te sanotte: Herran pöytä on saastutettu, ja sen uhri on katsottu ylön ja hänen ruokansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Ja te sanotte: katso, se on sula vaiva, ja lyötte sen tuleen, sanoo Herra Zebaot. Ja te uhraatte ryövättyä, ontuvaa ja sairasta, ja ne te uhraatte ruokauhriksi. Pitäiskö se minulle otollinen oleman teidän käsistänne? sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Mutta kirottu olkoon pettäjä, jonka laumassa on oinas, ja kuin hän tekee lupauksen, niin hän uhraa Herralle kelvottoman; sillä minä olen suuri kuningas, sanoo Herra Zebaot, ja minun nimeni on peljättävä pakanain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Ja te papit, tämä käsky tulee nyt teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Ellette sitä kuule, ja ellette pane sydämeenne, että te niin antaisitte minun nimelleni kunnian, sanoo Herra Zebaot, niin minä lähetän teidän sekaanne kirouksen, ja kiroon teidän siunauksianne; jopa minä olen myös niitä kironnut, ettette sitä tahtoneet panna sydämeenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Katso, minä tahdon turmella teidän siemenenne, ja paiskaan sonnan teidän kasvoillenne, teidän juhlapäiväinne sonnan, niin että se ijäksi teihin tarttuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Niin te saatte tuta, että minä sen käskyn teille lähettänyt olen, että sen piti minun liittoni Levin kanssa oleman, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Sillä minun liittoni oli hänen kanssansa elämään ja rauhaan, ja minä annoin ne pelvoksi hänelle, pelkäämään minua, ja minun nimeäni hämmästymään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Totuuden laki oli hänen suussansa, ja ei löydetty mitään pahaa hänen huulissansa; hän vaelsi rauhallisesti ja toimellisesti minun edessäni, ja käänsi monta pois synnistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Sillä papin huulet pitää opin kätkemän, että lakia hänen suustansa kysyttäisiin; sillä hän on Herran Zebaotin enkeli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mutta te olette tieltä poikenneet, pahoitatte monta laissa, ja olette Levin liiton rikkoneet, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Sentähden olen minä myös tehnyt, että te olette hyljätyt ja ylönkatsotut kaiken kansan edessä, ettette pidä minun teitäni, mutta katsotte ihmisten muotoa laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Eikö meillä kaikilla ole yksi Isä? eikö yksi Jumala meitä luonut ole? Miksi me katsomme ylön toinen toisemme, ja rikomme sen liiton, joka meidän isäimme kanssa tehty oli?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Sillä Juuda on ylönkatsojaksi tullut, Israelissa ja Jerusalemissa on tapahtunut kauhistus; sillä Juuda turmelee Herran pyhän, jota hän itse rakasti, ja ottaa vieraan jumalan tyttäriä emänniksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Vaan Herra hävittää hänen, joka sen tekee, Jakobin majasta, sekä opettajan että opetuslapsen, ja sen, joka vie Herralle Zebaotille ruokauhria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Te teette myös sen toisen, että Herran alttarin edessä ovat kyyneleet, itkut ja huokaukset, niin etten minä enään tahdo katsoa ruokauhria päin, eli ottaa vastaan jotakin otollisesti teidän käsistänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Ja te sanotte: minkätähden? Sentähden, että Herra on sinun ja sinun nuoruutes vaimon vaiheella todistanut, jonka katsot ylön, joka on sinun kumppanis ja sinun vaimos, johon sinä liitolla itses kiinni sitonut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Sillä eikö hän heitä yhdeksi tehnyt, vaikka hänellä olis ollut muita henkiä? Mutta mitä se yksi tekee? Hän etsii Jumalan siementä. Sentähden karttakaat teidän henkeänne, ja älköön kenkään katsoko ylön nuoruutensa vaimoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Että (Jumala) vihaa sitä hylkäämistä, sanoo Herra Israelin Jumala, kuin joku peittää vääryytensä niinkuin vaatteella, sanoo Herra Zebaot: sentähden karttakaat teidän henkeänne, ja älkäät katsoko heitä ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Te olette Herraa teidän puheellanne vaivanneet; ja te sanotte: missä me häntä olemme vaivanneet? Siinä kuin te sanotte: jokainen, joka pahaa tekee, se kelpaa Herralle, ja että senkaltaiset ovat hänelle otolliset; eli kussa on se Jumala, joka rankaisee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Katso, minä lähetän minun enkelini, joka minun eteeni pitää tien valmistaman; ja kohta tulee templiinsä se Herra, jota te etsitte, ja liiton enkeli, jota te tahdotte; katso, hän tulee, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mutta kuka voi hänen tulemisensa päivää kärsiä? ja kuka voi seisoa, kuin hän ilmaantuu? Sillä hän on niinkuin hopiasepän tuli ja niinkuin pesiän saippua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Hän on istuva ja sulaava ja selittävä hopian; hän on puhdistava ja hivuttava Levin pojat, niinkuin kullan ja hopian. Silloin pitää heidän tuoman Herralle ruokauhria vanhurskaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Ja Juudan ja Jerusalemin ruokauhrit pitää kyllä Herralle kelpaaman, niinkuin muinen ja entisinä vuosina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Ja minä tahdon tulla teidän tykönne ja rangaista teitä, ja tahdon olla nopia todistaja noitia vastaan, huorintekiöitä ja valapattoisia vastaan, ja niitä vastaan, jotka palkolliselta palkan pidättävät, leskille ja orvoille väkivaltaa ja vääryyttä tekevät, ja jotka muukalaista sortavat, eikä pelkää minua, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Sillä minä olen Herra, joka en muutu; ja te Jakobin lapset, ette ole hukkuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Te olette hamasta teidän isäinne ajasta alati poikenneet pois minun säädyistäni, ja ette ole niitä pitäneet; niin kääntykäät nyt minun tyköni, niin minä tahdon myös kääntyä teidän tykönne, sanoo Herra Zebaot. Niin te sanotte: missä meidän pitää meitämme kääntämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Onko se oikein, että ihminen pettää Jumalan, niinkuin te minun petätte? niin te sanotte: missä me sinun petämme? Kymmenyksissä ja ylennysuhrissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Sentähden te olette kirouksella kirotut, että te minun petätte, kaikki kansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Mutta tuokaat täydelliset kymmenykset minun aittaani, että minun huoneessani ruokaa olis; ja niin koetelkaat minua, sanoo Herra Zebaot, ellen minä myös avaa teille taivaan akkunia, ja vuodata sieltä runsaasti siunausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Ja minä tahdon teiltä syöjän rangaista ettei se teiltä maan hedelmää hukuttaisi, ja ettei viinapuu teidän pellossanne olisi hedelmätöin, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Niin että kaikki pakanat pitää teidän autuaaksi sanoman; sillä teidän pitää kallis maa oleman, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Kovasti te puhutte minua vastaan, sanoo Herra. Ja te sanotte: mitä me puhumme sinua vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Te sanotte: se on turha, kuin Jumalaa palvellaan, ja mitä se auttaa, että me pidämme hänen käskynsä, ja vaivaamme meidän elämäämme Herran Zebaotin edessä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Sentähden me ylistämme ylönkatsojia; sillä jumalattomat menestyvät; he kiusaavat Jumalaa, ja se heille menestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Silloin ne, jotka Herraa pelkäävät, lohduttavat toinen toistansa näin: Herra ottaa siitä vaarin ja kuulee sen, ja muistokirja on kirjoitettu hänen eteensä niille, jotka Herraa pelkäävät ja muistavat hänen nimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Niiden pitää, sanoo Herra Zebaot, sinä päivänä, jonka minä teen, oleman minun omani; ja minä tahdon heitä armahtaa, niinkuin mies armahtaa poikaansa, joka häntä palvelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Ja teidän pitää jälleen sitä vastaan näkemän, mikä eroitus on vanhurskaan ja jumalattoman vaiheella, ja sen vaiheella, joka Jumalaa palvelee, ja sen, joka ei häntä palvele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Sillä katso, se päivä tulee, joka on palava niinkuin pätsi: silloin pitää kaikki ylönkatsojat ja jumalattomat olkena oleman, ja se tuleva päivä pitää heidät sytyttämän, sanoo Herra Zebaot, ja ei pidä heille jättämän juurta eikä oksaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Mutta teille, jotka minun nimeäni pelkäätte, on vanhurskauden aurinko koittava, ja autuus hänen siipeinsä alla; ja teidän pitää käymän ulos ja sisälle, lisääntymän niinkuin syöttiläät vasikat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'Teidän pitää jumalattomat tallaaman; sillä heidän pitää tuhkana teidän jalkainne alla oleman, sinä päivänä, jonka minä tehdä tahdon, sanoo Herra Zebaot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Muistakaat Moseksen minun palveliani lakia, jonka minä hänelle käskin Horebissa, kaikelle Israelille säädyksi ja oikeudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Katso, minä lähetän teille Elian, prophetan, ennenkuin se suuri ja hirmuinen Herran päivä tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Hän on kääntävä isäin sydämet lasten tykö, ja lasten sydämet isäinsä tykö, etten minä tulisi ja löisi maahan kirouksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Oli yksi mies, nimeltä Tobia, Naphtalin suvusta, yhdestä ylimmäisen Galilean kaupungista, ylempänä Asseria, tien vieressä vasemmalla kädellä merta kohden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Se myös vangiksi vietiin Salmanasserin, Assyrian kuninkaan aikana. Ja vaikka hän niin muukalaisten seassa vankina oli, ei hän kuitenkaan Jumalan sanasta luopunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Ja kaikki mitä hänellä oli, jakoi hän veljillensä ja tuttavillensa, jotka hänen kanssansa vankina olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Ja ehkä hän nuorin mies oli Naphtalin suvusta, ei kuitenkaan hän itsiänsä lapsellisesti käyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Ja kuin muutoin jokainen palveli kultaisia vasikoita, jotka Jerobeam, Israelin kuningas, oli tehdä antanut, vältti hän sitä kauhistusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Ja piti itsensä templiin ja Jerusalemin jumalanpalvelukseen, ja palveli siellä Herraa, ja rukoili Israelin Jumalaa, antoi myös esikoisensa ja kymmenyksensä aivan uskollisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Niin että hän aina kolmantena vuotena muukalaisille, leskille ja orvoille heidän kymmenyksensä antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Ne hän piti nuoruudestansa, Herran lain jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Kuin hän nyt mieheksi kasvanut oli, otti hän vaimon Naphtalin suvusta, Hannan nimeltä, ja siitti pojan, jonka hän myös Tobiaksi nimitti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ja opetti hänen nuoruudesta Jumalan sanassa, Jumalaa pelkäämään ja syntiä välttämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Ja kuin hän kaiken sukunsa, vaimonsa ja poikansa kanssa vietiin pois vankein seassa, Niniven kaupunkiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Ja jokainen söi pakanain uhrista ja ruasta, vältti hän sitä ja ei saastuttanut itsiänsä senkaltaisella rualla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Ja että hän koko sydämestänsä Herraa pelkäsi, antoi Jumala hänelle armon Salmanasserin, Assyrian kuninkaan edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Että hän antoi hänelle luvan käydäksensä, kuhunka hän tahtoi, ja toimittaa, mitä hänellä tekemistä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Niin hän meni kaikkein tykö, jotka vankina olivat, ja lohdutti heitä Jumalan sanalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Ja tuli Median kaupunkiin Ragekseen, ja hänen myötänsä oli kymmenen leiviskää hopiaa, jotka kuningas hänelle antanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Ja kuin hän muiden Israelilaisten seassa näki yhden suvustansa, nimeltä Gabelin, joka sangen köyhä oli, antoi hän hänelle sen rahan, ja otti kirjoituksen häneltä');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Sitoo pitkän ajan perästä, Salmanasserin kuoleman jälkeen, kuin hänen poikansa Sennaherib hänen jälkeensä hallitsi, joka Israelin lasten vihamies oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Kävi Tobia joka päivä kaikkein Israelilaisten tykönä, ja lohdutti heitä, ja jakoi itsekullekin hyvyydestänsä voimansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Isoovaisia hän ruokki, alastomia hän vaatetti, tapetuita ja kuolleita hän hautasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Mutta kuningas Sennaherib oli paennut Juudeasta, kuin Jumala hänen lyönyt oli, hänen pilkkaamisensa tähden. Kun hän nyt palasi, oli hän kiukuissansa ja antoi tappaa paljo Israelin lapsia; niiden ruumiit toimitti Tobia hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Mutta koska kuningas sen tietää sai, käski hän hänen tapettaa, ja otti häneltä kaiken hänen tavaransa. Vaan Tobia pakeni vaimonsa ja poikansa kanssa, ja piti itsensä salaa hyväin ystäväinsä tykönä. Vaan viiden päivän perästä viidettäkymmentä tapettiin kuningas omilta pojiltansa. Ja Tobia tuli jälleen kotiansa, ja kaikki hänen tavaransa annettiin hänelle jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Senjälkeen, Herran juhlapäivänä, kuin Tobia huoneessansa kuuluisan vieraspidon valmistanut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Sanoi hän pojallensa: mene ja kutsu ne jumaliset meidän suvustamme meidän kanssamme rualle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Ja kuin hän palasi, sanoi hän isällensä Tobialle: yksi Israelilainen on kuolleena kadulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Niin nousi Tobia kohta pöydästä, ennenkuin hän söi, ja meni kuolleen ruumiin tykö, ja otti sen, ja kantoi salaa huoneesensa, että hän sen salaa hautais yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Ja kuin hän ruumiin salaa kätkenyt oli, söi hän leipäänsä murheessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Ja ajatteli sitä sanaa: jonka Herra Amos prophetan kautta puhunut oli: teidän juhlapäivänne pitää murhepäiväksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Ja meni yöllä ja hautasi kuolleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Mutta hänen ystävänsä nuhtelivat häntä ja sanoivat: äsken käski kuningas sinun tapettaa sen asian tähden, ja sinä olet tuskin siitä päässyt, ja kuitenkin hautaat kuolleita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Mutta Tobia pelkäsi Jumalaa enemmän kuin kuningasta, ja kantoi salaisesti kokoon ne tapetut, ja piti salaa huoneessansa, ja yöllä hän hautasi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Mutta se tapahtui yhtenä päivänä, kuin hän kotia tuli kuolleita hautaamasta, ja oli väsyksissä, ja nojasi seinukselle, ja nukkui,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Putosi pääskysen pesästä palava sonta hänen silmiinsä, josta hän tuli sokiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Mutta senkaltaisen vaivan antoi Jumala tulla hänen päällensä, että jälkeentulevaiset oppisivat kärsimään, niinkuin pyhästä Jobista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Ja että hän aina nuoruudestansa Jumalaa peljännyt ja hänen käskynsä pitänyt oli, ei hän vihastunut eikä napissut Jumalaa vastaan, että hän oli antanut hänen sokiaksi tulla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Vaan pysyi lujana Jumalan pelvossa ja kiitti Jumalaa kaiken elinaikansa. Ja niinkuin kuninkaat pyhää Jobia nauroivat, niin myös Tobiaa nauroivat hänen ystävänsä, Ja sanoivat: kussa nyt sinun uskallukses on, jonka tähden sinä almujas jakanut ja niin paljo kuolleita haudannut olet? Ja Tobia nuhteli heitä ja sanoi: älkäät sanoko niin; Sillä me olemme pyhäin lapset, ja odotamme elämää, jonka Jumala antaa niille, jotka uskossa vahvana ja lujana pysyvät hänen edessänsä. Mutta Hanna, hänen emäntäinsä, teki viriästi työtä käsillänsä, ja ruokki hänen kehräämisellä. Mutta se tapahtui, että hän nuoren vuohen toi kotia, Ja kuin hänen miehensä Tobia kuuli sen määkyvän, sanoi hän: katsokaat ettei se varastettu ole, antakaat häntä isännällensä jälleen; sillä ei meidän sovi syödä varastetusta kalusta, eikä siihen ryhtyä. Siitä puheesta vihastui hänen emäntänsä, vastasi ja sanoi: tästä nähdään, että sinun uskallukses ei ole mitään, ja sinun almus ovat hukkuneet. Senkaltaisilla ja muilla sanoilla soimasi hän hänelle hänen viheliäisyyttänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Silloin huokasi Tobia raskaasti ja rupesi itkemään ja rukoilemaan la sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Herra, sinä olet hurskas, ja kaikki sinun työs ovat oikiat, ja sula hyvyys ja uskollisuus!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Ja nyt minun Herrani, ole minulle armollinen, ja älä kosta minun syntiäni, älä muistele minun eli minun isäni pahoja tekoja;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Sillä ettemme sinun käskyjäs pitäneet, niin me myös olemme annetut meidän vihollisillemme, että he meitä ryöstävät, vankina pitävät ja tappavat, ja olemme häväistykseksi, nauruksi ja pilkaksi tulleet muukalaisille, kuhunkas meidät hajoittanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Ja nyt, Herra! hirmuiset ovat sinun tuomios, ettemme sinun käskyjäs pitäneet ole, emmekä oikein sinun edessäs vaeltaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Ah Herra, osoita minulle armo, ja korjaa minun henkeni rauhassa; sillä minä tahtoisin paljoa paremmin kuolla kuin elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Ja se tapahtui sinä päivänä, että Saara Raguelin tytär, Mediläisten kaupungista Rageksesta, myös pahoin häväistiin ja soimattiin isänsä piialta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Hän oli annettu seitsemälle miehelle toinen toisensa jälkeen, ja paha henki, Asmodi nimeltä, oli heidät kaikki tappanut, kohta kuin he vuoteesen tulivat hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Sentähden soimasi häntä hänen isänsä piika ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Jumala tehköön, ettemme ikänä sinusta näkisi poikaa eli tytärtä maan päällä, sinä miestes murhaaja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Tahdotkos minunkin tappaa, niinkuin sinä ne seitsemän miestä tappanut olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Niiden sanain tähden meni hän kammioon huoneen päälle, ja ei syönyt eikä juonut kolmena päivänä, ja ei lakannut rukoilemasta ja itkemästä, ja rukoili Jumalaa, että hän hänen siitä häväistyksestä vapahtais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Sitte kolmantena päivänä, kuin hän rukouksensa päättänyt oli, kiitti hän Jumalaa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Kiitetty olkoon sinun nimes, Herra, meidän isäimme Jumala! Sillä koska sinä vihastut, osoitat sinä armon ja hyvyyden, ja ahdistuksessa sinä synnit anteeksi annat niille, jotka sinua avuksensa huutavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Sinun puolees, minun Herrani, käännän minä kasvoni; sinun tykös minä nostan silmäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Ja rukoilen sinua, ettäs minun pelastaisit tästä raskaasta häväistyksestä, eli minun täältä korjaisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Sinä tiedät, Herra, etten minä miestä himoinnut ole, ja olen minun sieluni puhtaana pitänyt kaikista pahoista himoista, enkä ole koskaan häpeemättömäin ja rivoin joukossa ollut. Miestä ottamaan olen minä mielistynyt sinun pelvossas ja en hempeydestä. Taikka en ole minä heidän, elikkä ei he minun vertaiseni olleet, ja sinä olet minua mitämaks säästänyt toiselle miehelle; Sillä sinun neuvos ei ole ihmisen voimassa. Mutta sen minä kyllä todeksi tiedän: joka Jumalaa palvelee, se kiusauksen jälkeen lohdutetaan, ja murheesta pelastetaan, ja kurituksen jälkeen löytää armon. Sillä et sinä mielisty meidän kadotukseemme; sillä pahan ilman perästä annat sinä auringon paistaa, ja parun ja itkun perästä täytät sinä meidät ilolla. Sinun nimelles, Israelin Jumala, olkoon ijankaikkinen kiitos ja ylistys! Sillä hetkellä kuultiin heidän molempain rukouksensa Herralta taivaassa. Ja Pyhä Raphael, Herran enkeli, lähetettiin heitä molempia auttamaan, että heidän rukouksensa yhtä haavaa tuotiin Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Kuin Tobia luuli rukouksensa kuulluksi, että hänen kuoleman piti, kutsui hän poikansa tykönsä, ja sanoi hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Minun poikani, kuule minun sanani, ja pidä ne lujasti sinun sydämessäs!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Kuin Jumala minun sieluni korjaa, niin hautaa minun ruumiini, ja kunnioita sinun äitiäsi kaikkena elinaikanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Muista, mitä vaaraa hän kärsi, kuin hän sinun sydämensä alla kantoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Ja kuin hän kuolee niin hautaa häntä minun viereeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Ja kaikkena sinun elinaikanas pidä Jumala silmäis edessä ja sydämessäs, ja karta, ettet mihinkään syntiin mielisty ja Jumalan käskyä vastaan tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Sinun tavarastas auta köyhiä, ja älä käännä itsiäs pois köyhästä, niin Jumala taas armollisesti katsoo sinun päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Kussas taidat, niin auta tarvitsevaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Jos sinulla paljo on, niin anna runsaasti: jos sinulla vähä, niin anna vähästä hyvällä mielellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Sillä sinä kokoot sinulles hyvän palkan tuskassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Sillä almu pelastaa kaikesta synnistä ja kuolemasta, ja ei hylkää hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Almu on hyvä lohdutus korkeimman Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Karta, poikani, kaikkinaista huoruutta, ja paitsi omaa vaimoas älä keneenkään muuhun suostut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Älä anna ylpeyden hallita ei sydämessäs eli sanoissas; sillä se on kaiken kadotuksen alku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Joka sinun työtäs tekee, anna hänelle kohta hänen palkkansa, ja älä pidä keltäkään ansaittua palkkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Jota et tahdo keneltäkään sinulles tehtää, katso, ettet sitä myös toiselle tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Jaa leipäs isoovaiselle, ja peitä alastomia vaatteillas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Anna almua leivästäs ja viinastas jumalisten hautaamisissa, ja älä syö elikkä juo syntisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Kysy aina neuvoa viisailta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Ja kiitä aina Jumalaa, ja rukoile, että hän sinun hallitsis, ja ettäs kaikissa töissäs seuraisit hänen sanaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Sinun pitää myös tietämän, poikani, että minä kymmenen leiviskää hopiaa, läsnäollessas, lainasin Gabelille Rageksen kaupungissa Mediassa, ja hänen kirjoituksensa on minulla. Sen tähden ajattele, kuinka hänen tykönsä tulisit ja anoisit rahan, ja antaisit jälleen hänen kirjoituksensa. Älä murehdi, poikani! Me olemme tosin köyhät, mutta me saamme paljo hyvää, jos me Jumalaa pelkäämme, vältämme syntiä ja teemme hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Silloin vastasi nuori Tobia isäänsä ja sanoi: kaikki, mitäs minulle sanonut olet, minun isäni, tahdon minä tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Mutta kuinka minun tätä rahaa anoman pitää, en minä tiedä: ei hän minua tunne, enkä minä häntä. Mitä minun pitää merkiksi viemän; että hän minun uskois? En tiedä minä myös tietä sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Niin vastasi häntä hänen isänsä, ja sanoi: hänen kirjoituksensa on minulla; koskas sen hänelle näytät, niin hän kohta sinulle antaa rahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Mene nyt ja etsi sinulles uskollinen kumppani, joka palkan edestä sinun kanssas menis, ettäs sen rahan minun eläissäni jälleen saisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Niin meni nuori Tobia ulos, Ja löysi kauniin nuorukaisen seisomasta, joka oli itsensä vyöttänyt ja valmistanut vaeltamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Ja ei tietänyt, että se Jumalan enkeli oli, tervehti häntä ja sanoi: kustas olet, hyvä nuorukainen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Ja hän sanoi: minä olen Israelin lapsista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Tobia sanoi hänelle: tiedätkös tien Median maalle? Hän vastasi: tiedän kyllä, ja olen usein sitä vaeltanut, ja olen majaa ollut meidän veljemme Gabelln tykönä, joka asuu Rageksessa Mediassa, joka on Ekbatanan vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Ja Tobia sanoi hänelle: odotas vähä aikaa, siihenasti että minä sen isälleni sanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Ja Tobia meni ja sanoi sen isällensä; ja isä ihmetteli, ja rukoili, että se nuorukainen tulis sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Ja hän meni sisälle vanhan tykö, ja tervehti häntä, ja sanoi: Jumala antakoon sinulle iloa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Ja Tobia sanoi hänelle: mikä ilo minulla oleman pitäis, jonka pimeydessä istuman pitää, ja taivaan valkeutta en nähdä taida?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ja nuorukainen sanoi hänelle: ole kärsivällinen; Jumala sinua pian auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ja Tobia sanoi hänelle: tahdotkos minun poikani johdattaa Ragekseen Mediaan Gabelin tykö? niin minä annan sinulle sinun palkkas, kuin palajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Ja enkeli sanoi hänelle: minä tahdon hänen sinne viedä, ja jälleen sinun tykös tänne tuoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Ja Tobia sanoi hänelle: minä rukoilen sinua: sano minulle: mistä suvusta ja kenenkä sukukunnasta sinä olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ja enkeli Raphael sanoi: ole ääneti! eikö siinä kyllä ole, että sinulla on sanansaattaja; mitä sinun tarvitsee tietää, kusta minä olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Kuitenkin ettäs sitä vähemmin pelkäisit, niin minä sanon sinulle: minä olen Atsaria, suuren Ananian poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Ja Tobia sanoi: sinä olet hyvästä suvusta. Minä rukoilen sinua, ettet vihastuisi, että minä sinun sukuas kysynyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Ja enkeli sanoi: minä tahdon sinun poikas terveenä sinne ja jälleen tänne saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Tobia vastasi: niin menkäät matkaan, Jumala olkoon teidän kanssanne tiellä, ja hänen enkelinsä johdattakoon teitä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Silloin valmisti Tobia itsensä ja kaikki, mitä hän kanssansa ottaa tahtoi, ja siunasi isänsä ja ja äitinsä, ja meni matkaansa kumppaninensa. Ja hänen äitinsä rupesi itkemään ja sanoi: meidän vanhuuden lohdutuksen olet sinä ottanut ja lähettänyt pois. Minä soisin, ettei se raha ikänä olisi ollut, jonka tähden sinä hänen olet lähettänyt pois. Me olisimme tyytyneet meidän köyhyytemme; se olis suuri rikkaus, että meidän poikamme tykönämme olis. Ja Tobia sanoi: älä itke! meidän poikamme menee raittiina ja palajaa terveenä, ja sinun silmäs pitää näkemän hänen. Sillä minä uskon, että Jumalan hyvä enkeli johdattaa hänen, ja kaikki hyvin toimittaa, mitä hänellä toimittamista on, niin että hän ilolla jälleen meidän tykömme palajaa. Niin hänen äitinsä vaikeni ja tyytyi siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Ja Tobia meni matkaansa, ja koira juoksi hänen kanssansa, ja ensimäisen päivän matkana tulivat he Tygriksen virran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Ja hän meni pesemään jalkojansa; ja katso, suuri kala hyppäsi sieltä, ja tahtoi niellä hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Jota Tobia hämmästyi, ja huusi täydellä äänellä ja sanoi: Herra, hän tahtoo minun syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Ja enkeli sanoi hänelle: tartu hänen kiduksiinsa, ja vedä häntä ylös. Ja hän veti hänen maalle, niin hän pyrisi hänen jalkainsa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Silloin sanoi enkeli: halkaise kala kahtia: sydän, maksa ja sappi pidä itselles; sillä ne ovat sangen hyvät voiteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Ja monikahdat kappaleet kalasta he paistoivat ja ottivat kanssansa matkalle: ne muut he suolasivat evääksi matkalle, siihenasti että he tulisivat Rageksen Mediaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Niin Tobia kysyi enkeliltä Ja sanoi hänelle: minä rukoilen sinua, Atsaria veljeni. ettäs sanoisit minulle, mitä voiteita niistä kappaleista tehdä taidetaan, jotka minun käskit tähdellä pitää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Niin enkeli sanoi: koska kappaleen sydäntä ja maksaa panet tulisten hiilten päälle, niin se savu karkottaa kaikkinaiset kyöpelit miehen ja vaimon tyköä, niin ettei he enää vahingoittaa taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Ja kalan maksa on hyvä silmiä voidella, että kalvo pois kuluu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Ja Tobia sanoi: kuhunka me poikkeemme? Ja enkeli vastasi ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Tässä on yksi mies, Raguel nimeltä, sinun lankos sinun suvustas, hänellä on ainoastaan yksi tytär, Saara nimeltä, ja ei yhtään muuta lasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Sinulle ovat kaikki hänen tavaransa aiotut, ja sinä otat hänen tyttärensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Ano siis häntä hänen isältänsä niin hän antaa hänen sinulle emännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Niin sanoi Tobia: minä olen kuullut, että hän jo ennen seitsemälle miehelle annettu on, ne kaikki ovat kuolleet; päälliseksi sanotaan, että paha henki on heidät tappanut. 3: 7, etc.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Sentähden pelkään minä, ettei minun myös niin kävisi, niin kuolisivat minun vanhempani murheisiinsa, että minä ainoa poika olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Silloin sanoi enkeli Raphael: kuule, minä sanon sinulle, keiden päälle perkeleellä valta on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Nimittäin niiden päälle, jotka katsovat Jumalan ylön, ja vaivoin haureuden tähden vaimoja ottavat, niinkuin järjettömät eläimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Mutta sinä, kuin morsiames kanssa kammioon tulet, pitää sinun kolme päivää pitämän sinus pois hänestä, ja hänen kanssansa rukoileman. Ja sinä yönä, kuin panet kalan sydämen ja maksan tulisten hiilten päälle, niin perkele tulee karkotetuksi. Toisena yönä pitää sinun hänen tykönsä menemän puhtaudessa, niinkuin pyhät patriarkat. Kolmantena yönä sinä saat! siunauksen, että terveet lapset teistä syntyvät. Mutta kuin kolmas yö kulunut on, niin sinun pitää neitseen tykö Jumalan pelvossa menemän enempi hedelmän himosta, kuin pahasta halusta, että sinä ja sinun lapses siunauksen saisitte, joka Abrahamin siemenelle luvattu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ja he menivät Raguelin tykö, Ja Raguel otti vastaan heidät ilolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Ja katsoi Tobian päälle, Ja sanoi Ednalle emännällensä: kuinka tämä nuori mies on meidän lankomme muotoinen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Ja kuin hän sen puhunut oli, sanoi hän: kusta te olette, minun veljeni? He sanoivat: me olemme Naphtalin suvusta niistä vangeista, jotka Ninivessä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Raguel sanoi heille: tunnetteko minun veljeni Tobian? Ja he sanoivat: me tunnemme hänen hyvin');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Ja kuin hän nyt paljon hyvää puhui Tobiasta, sanoi enkeli Raguelille: Tobia, jonkas perään kysyt, on tämän nuoren miehen isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ja Raguel nojasi hänen puoleensa, itki, rupesi hänen kaulaansa, ja suuta antoi hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Ja sanoi: hyvästi siunattu ole sinä, minun rakas poikani; sillä sinä olet juuri jalon miehen poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Ja Edna hänen emäntänsä, ja Saara hänen tyttärensä rupesivat myös itkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Sitte käski Raguel tappaa lampaan ja valmistaa ruokaa. Ja kuin he heitä rukoilivat pöydän tykö istumaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Sanoi Tobia: en minä tänäpänä syö enkä juo, ellet sinä myöten anna minulle minun rukoustani, ja lupaa minulle Saaraa, sinun tytärtäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Kuin Raguel sen kuuli, peljästyi hän, muistain, mitä niille seitsemälle miehelle tapahtunut oli, joille hän ennen tyttärensä antanut oli, ja pelkäsi, että tälle myös niin tapahtuman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Ja kuin ei hän vastata tahtonut, sanoi enkeli hänelle: älä pelkää hänelle antaa piikaa: sinun tyttäres on hänelle aiottu vaimoksi; sillä hän pelkää Jumalaa, sentähden ei pitänyt yksikään muu sinun tytärtäs saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Silloin sanoi Raguel: en minä epäile, ettei Jumala minun katkeroita kyyneleitäni ja rukouksiani kuullut ole,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Ja uskon, että hän sitä varten on teidän antanut minun tyköni tulla, että minun tyttäreni tämän sais hänen suvustansa, Moseksen lain jälkeen; ja älä nyt mitään epäile, minä annan hänen sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Ja otti tyttärensä käden ja löi Tobian käteen, ja sanoi: Abrahamin Jumala, Isakin Jumala, Jakobin Jumala olkoon teidän kanssanne, ja auttakoon teitä yhteen, ja antakoon siunauksensa runsaasti teille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Ja he ottivat kirjan ja kirjoittivat avioliiton, Ja kiittivät Jumalaa ja pitivät vieraspitoa. Ja Raguel kutsui tykönsä emäntänsä Ednan, ja käski hänen toisen kammion valmistaa. Ja he veivät sinne tyttärensä Saaran, ja hän itki. Ja hän sanoi hänelle: ole hyvässä turvassa, minun tyttäreni: taivaan Herra antakoon sinulle ilon siitä murheesta, jonka sinä kärsinyt olet!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Ja ehtoollisen jälkeen veivät he nuoren Tobian neitseen tykö kammioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Ja Tobia muisti enkelin sanat, ja otti säkistänsä kappaleen sydäntä ja maksaa, ja pani ne tuo tulisille hiilille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Ja enkeli Raphael otti sen hengen vangiksi, ja sitoi hänen kauvas Egyptin korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Sitte neuvoi Tobia neitsyttä ja sanoi: Saara, nouse, ja rukoilkaamme Jumalaa tänäpänä ja huomenna; sillä nämät kolme yötä me rukoilkaamme, ja senjälkeen olkaamme yhdessä niinkuin avioväki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Sillä me olemme pyhäin lapset: ei meidän sovi sitä säätyä niin alkaa kuin pakanat, jotka Jumalan katsovat ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Ja he nousivat ylös, ja rukoilivat ynnä hartaasti, että Jumala heitä varjelis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Ja Tobia rukoili ja sanoi: Herra minun Jumalani, sinä meidän isäimme Jumala, sinua kiittäkään taivaat, maa, meri, kaikki vedet ja lähteet, ja kaikki luontokappaleet, kuin niissä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Sinä olet tehnyt Adamin maan tomusta ja olet hänelle antanut Hevan apulaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Ja nyt, Herra! sinä tiedät, etten minä pahasta himosta tätä minun sisartani vaimokseni ottanut ole, vaan että minä lapsia siittäisin, jonka kautta sinun pyhä\' nimes iankaikkisesti kiitettäisiin ja ylistettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Ja Saara sanoi: Herra, armahda meidän päällemme, että me molemmin terveinä mahtaisimme vanhuutemme saavuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Puoliyöstä huusi Raguel palveliansa, ja meni hänen kanssansa hautaa tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Sillä hän sanoi: mitämaks hänelle on niin tapahtunut, kuin muillekin seitsemälle, jotka hänen kihlanneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Ja kuin he haudan tehneet olivat, tuli Raguel emäntänsä tykö ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Lähetä piika, ja anna katsoa, jos hänkin kuollut on, että me hänen ennen päivää hautaisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Ja piika meni kammioon, ja löysi heidät molemmat terveinä ja raittiina makaavan toinen toisensa tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Ja hän toi heille hyvän sanoman. Ja Raguel emäntinensä kiittivät Jumalaa ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Me kiitämme sinua, Herra Israelin Jumala, ettei se tapahtunut, jota me pelkäsimme; sillä sinä olet laupiutes meille näyttänyt, ja olet meidän vihollisemme, joka meidän pahaa teki, ajanut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Sinä olet armahtanut näitä kahta ainoaa lasta. Ja nyt, Herra, anna heidän aina sinua kiittää senkaltaisen armon edestä, ja sinulle aina kiitosta uhrata, että muut ihmiset heissä tuntisivat, että sinä olet ainoa Jumala kaikessa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Ja Raguel käski kohta täyttää haudan ennenkuin päivä tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Ja käski emäntänsä taas valmistaa vieraspidon, ja toimittaa heille kaikkinaiset tarpeet tielle');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Ja hän antoi tappaa kaksi lihavaa härkää, ja neljä lammasta, ja kutsui kaikki lähimmäisensä ja ystävänsä vieraiksi Ja Raguel neuvoi ja rukoili suuresti Tobiaa viipymään tykönänsä kaksi viikkoa. Ja kaikesta tavarastansa antoi hän puolen Tobialle, ja teki kirjoituksen, että hänen kuolemansa jälkeen toinen puoli myös Tobian olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Silloin kutsui Tobia enkelin tykönsä, sillä hän luuli hänen ihmiseksi, ja sanoi hänelle: Atsaria, veljeni, minä rukoilen sinua, kuule minun sanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Vaikka minä itseni sinulle omaksi orjakses antaisin, niin ei kuitenkaan se mitään olisi sinun hyväin tekois suhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Kuitenkin rukoilen minä, ota tämä palvelia ja kamelit, ja mene Gabelin tykö Rageksen Mediassa, ja anna hänelle tämä kirjoitus, ja ota häneltä se raha, ja rukoile häntä minun häihini tulemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Sillä sinä tiedät, minun isäni lukee hetket ja päivät, ja jos minä päivänkin enempi viivyn, niin hänen sielunsa tulee murheelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Ja sinä tiedät, kuinka hartaasti Raguel minua rukoillut on, etten minä häneltä kieltää taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Silloin otti enkeli Raphael Raguelin palvelian ja kaksi kamelia, ja meni Ragekseen ja löysi Gabelin, ja antoi hänelle kirjoituksen ja sai rahan häneltä, Ja ilmoitti hänelle kaikki, mitä tapahtunut oli Tobian pojalle, ja kutsui häntä häihin. Ja kuin he tulivat Raguelin huoneesen, löysivät he Tobian pöydän tykönä, ja katso, hän nousi hänen tähtensä ja antoivat suuta toinen toisensa. Ja Gabel itki, ja kiitti Jumalaa, ja sanoi: Israelin Jumala siunatkoon sinua; sillä sinä olet kunniallisen, hurskaan ja jumalisen miehen poika, joka vaivaisille paljo hyvää tehnyt on. Siunattu olkoon sinun vaimos ja sinun vanhempas. Ja Jumala antakoon teidän nähdä teidän lapsenne ja lastenne lapset kolmanteen ja neljänteen polveen, ja siunattu olkoon sinun siemenes Israelin Jumalalta, joka hallitsee ja vallitsee ijankaikkiseen! Ja kuin he kaikki amen! sanoneet olivat, istuivat he pöydän tykö, vaan he aterioitsivat ja iloitsivat Jumalan pelvossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Kuin nuori Tobia häittensä tähden kauvan oli poissa, rupesi vanha Tobia, hänen isänsä, murehtimaan ja sanoi: miksi minun poikani niin kauvan poissa on, ja mikä häntä viivyttää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Mitämaks Gabel on kuollut, ja ei kenkään tahdo hänelle rahaa maksaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Ja tulivat sangen murheellisiksi, Tobia ja Hanna hänen emäntänsä, ja itkivät molemmin, ettei heidän poikansa määrätyllä ajalla kotia tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Ja hänen äitinsä itki niin ettei hän tahtonut itsiänsä lohduttaa antaa, ja sanoi: voi minun poikani! voi minun poikani! miksi me olemme päästäneet sinun vaeltamaan? meidän ainoan ilomme meidän ainoan lohdutuksemme vanhuudessamme, meidän sydämemme ja meidän perillisemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Meillä olisi kyllä tavaraa ollut, jos emme sinua olisi päästäneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Ja Tobia sanoi hänelle: ole ääneti ja hyvässä turvassa! ei meidän pojallamme Jumalan avulla hätää ole, hänellä on uskollinen kumppani kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Vaan ei hän tahtonut itsiänsä antaa lohduttaa, ja juoksi joka päivä ulos ja katsoi joka kujalle kusta hänen tuleman piti, jos hän, jossakussa hänen näkis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Mutta Raguel sanoi vävyllensä Tobialle: pysy meidän tykönämme, minä tahdon sanan lähettää Tobialle sinun isälles, ja hänen tietää antaa, ettäs terveenä olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ja Tobia sanoi: minä tiedän että minun isäni ja äitini parhaallansa lukevat jokaisen päivän ja hetken, ja ovat minun tähteni kovin murheissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ja kuin Raguel monilla sanoilla rukoili Tobiaa, ja ei hän millään muotoa sitä tehdä tahtonut, antoi hän hänelle Saaran, ja antoi hänelle puolen kaikesta tavarastansa, palvelioista, piioista, karjasta, kameleista ja härjistä ja paljon rahaa, ja antoi hänen terveenä ja iloisena tyköänsä mennä pois, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Herran pyhä enkeli olkoon sinun kanssas tiellä, ja saattakoon sinun terveenä kotia jälleen, ettäs löytäisit vanhempas terveenä; ja Jumala antakoon minun silmäni nähdä teidän lapsenne ennen kuin minä kuolen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Ja vanhemmat ottivat tyttärensä, ja suuta antoivat hänen, ja päästivät hänen tyköänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Ja neuvoivat häntä, että hän pitäis miehensä vanhemmat kunniassa, niinkuin omat vanhempansa, rakastais miestänsä, hallitsis visusti perheen, pitäis itsensä kunniallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Ja tiellä, kuin he tulivat Haraniin, joka on puolivälissä Ninivetä, ensimmäisenä päivänä toistakymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Sanoi enkeli: veljeni Tobia, sinä tiedät, mihinkä tilaan sinä jätit isäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Jos sinun tahtos on, niin käykäämme edellä, ja antakaamme sinun emäntäs väen ja karjan kanssa jäljestä tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Ja kuin se Tobialle kelpasi, sanoi Raphael: ota myötäs kalan sappea, sillä se on tarpeellinen. Niin Tobias otti tykönsä kalan sappea, ja he menivät niin edellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Mutta Hanna istui joka päivä tien vieressä mäellä, niin että hän sai katsoa kauvas ympärillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Ja kuin hän siinä paikassa katseli, näki hän poikansa kaukaa ja tunsi kohta hänen, ja juoksi ilmoittamaan miehellensä, ja sanoi: katso, sinun poikas tulee!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Ja Raphael sanoi Tobialle: kohta kuin sinä huoneesen tulet, niin rnkoile ja huuda Herran tykö, ja kiitä häntä, ja mene sitte isäs tykö, ja anna hänelle suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Ja voitele kohta hänen silmänsä kalan sapella, joka sinulla on, niin hänen silmänsä kohta aukenevat, ja sinun isäs taas näkee ja suuresti iloitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Niin juoksi koira edellä, jonka he kanssansa ottaneet olivat, ja liehakoitsi hännällänsä, hyppeli ja oli iloinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Ja hänen sokia isänsä nousi äkisti, ja kiiruhti niin kovin, että hän loukkasi itsensä; niin hän kutsui palvelian tykönsä, joka häntä talutti kädestä kohtaamaan poikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Sitä teki myös äiti, ja he suuta antoivat hänelle, ja itkivät molemmin ilosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Ja kuin he rukoilleet olivat ja kiittäneet Jumalaa, istuivat he kaikki maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Silloin otti Tobia kalan sappea, ja voiteli isänsä silmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Ja hän kärsi sitä puolen hetkeä, ja kaihi läksi hänen silmistänsä, niinkuin munan kalvo!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Ja Tobia otti sen ja repäisi pois hänen silmistänsä, ja hän sai kohta näkönsä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Ja he kiittivät Jumalaa, hän ja hänen emäntänsä, ja kaikki jotka sen tietää saivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Ja Tobia sanoi: minä kiitän sinua Herra, Israelin Jumala, ettäs minua kuritit, ja autit minua jälleen, niin että minä rakkaan poikani saan nähdä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Ja seitsemän päivän perästä tuli Saara, hänen poikansa vaimo, kaiken perheensä, karjansa ja kameleinsa kanssa, ja toi paljo rahaa kanssansa, niin myös sen rahan, jonka hän Gabelilta saanut oli. Ja Tobia jutteli vanhemmillensa, kuinka paljon hyvää Jumala hänelle tehnyt oli, sen kumppanin kautta, Joka hänen kanssansa vaeltanut oli. Akior ja Nabat, Tobian langot, tulivat hänen tykönsä ja toivottivat hänelle onnea, ja iloitsivat hänen kanssansa kaikesta siitä hyvästä, jonka Herra hänelle antanut oli. Ja he söivät yhdessä seitsemän päivää, ja olivat iloiset');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Sitte kutsui Tobia poikansa tykönsä, ja sanoi: mitä me annamme sille pyhälle miehelle, joka sinun kanssas vaeltanut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Ja Tobia vastasi isäänsä: kuinka me taidamme maksaa hänelle ne hyvät työt, Jotka hän minulle tehnyt on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Hän on minun terveenä vienyt pois, ja tuonut kotia jälleen: hän toi sen rahan Gabelilta itse, ja autti minua tälle emännälle, niin hän myös ajoi pois pahan hengen, ja teki hänen vanhempansa iloisiksi. Jopa hän autti minua itse, kuin minun suuri kala niellä tahtoi, ja antoi sinulle näkös jälleen, ja on tehnyt meille sangen paljon hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Kuinka siis me taidamme maksaa hänelle senkaltaiset hyvät työt? Mutta minä rukoilen sinua, isäni, taritse hänelle puoli kaikesta siitä tavarasta, jonka me myötämme tuoneet olemme, että hän ne ottais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ja molemmat sekä isä että poika kutsuivat hänen erinänsä, ja rukoilivat häntä ottamaan puolen kaikesta siitä tavarasta, jonka he myötänsä tuoneet olivat. Ja minä olen Raphael, yksi niistä seitsemästä enkelistä, jotka seisomme Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ja hän sanoi heille salaisesti: kiittäkäät te ja kunnioittakaat taivaan Jumalaa jokaisen edessä, että hän teille senkaltaisen armon näyttänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Kuningasten ja päämiesten neuvoa ja salaisuutta pitää salattaman; mutta Jumalan töitä pitää korkiasti ylistettämän ja julistettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Senkaltainen rukous paastolla ja almuilla on parempi kuin kultaa koota tavaraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Sillä almut vapahtavat kuolemasta, pyyhkivät pois synnit, ja pitävät elämässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Mutta jumalattomat saattavat itsensä pois hengeltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Niin minä nyt ilmoitan teille totuuden, ja en salaa teiltä sitä salaista käskyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Kuin sinä niin katkerasti itkit ja rukoilit, ja nousit rualta, ja hautasit kuolleita, kätkit ruumiit salaa huoneeses, ja hautasit ne yöllä, silloin minä kannoin sinun rukoukses Herran eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Ja ettäs Jumalalle kelpasit, niin sen piti niin oleman; ilman kiusausta ei sinun pitänyt oleman, ettäs olisit koetelluksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Ja Jumala on minun lähettänyt parantamaan sinua, ja ajamaan pois sitä pahaa henkeä, joka Saaran sinun poikas emännän tykönä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Ja kuin he sen kuulivat, hämmästyivät he, vapisivat ja lankesivat maahan kasvoillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Ja. enkeli sanoi heille: Olkaat hyvässä turvassa, ja älkäät peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Sillä se kuin minä teidän tykönänne ollut olen, sen on Jumala niin tahtonut; kiittäkäät ja kunnioittakaat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Minä olin syövinäni ja juovinani teidän kanssanne, mutta minä nautitsen näkymätöintä ruokaa, jota ei yksikään ihminen nähdä taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Ja nyt on aika, että minä menen taas hänen tykönsä, joka minun on lähettänyt; kunnioittakaat te Jumalaa ja ilmoittakaat hänen ihmeitänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Ja kuin hän sen sanonut oli, katosi hän heidän silmäinsä edestä, ja ei he häntä enää nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Ja he lankesivat maahan kolmeksi hetkeksi, ja kunnioittivat Jumalaa; sitte nousivat he ja sanelivat niitä, ja ilmoittivat hänen suuria ihmeitänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Mutta Tobia avasi suunsa, kiitti Jumalaa ja sanoi: Herra, sinä olet suuri ja väkevä Jumala, ja sinun valtakuntas pysyy ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Sinä kuritat, ja lohdutat jälleen; sinä taidat sysätä helvettiin, ja taas ottaa sieltä ulos; sinun kättäs ei taida kenkään välttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Te Israelin lapset, kiittäkäät Herraa, ja ylistäkäät häntä pakanain edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Sillä sen tähden on hän teidät hajoittanut pakanain sekaan, jotka ei häntä tunne, ilmoittamaan hänen ihmeitänsä, ja että pakanat ymmärtäisivät, ettei kenkään ole kaikkivaltias Jumala, vaan hän ainoastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Hän on kurittanut meitä meidän synteimme tähden, ja laupiudestansa hän meitä jälleen auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Katsokaat, mitä hän meidän kanssamme tehnyt on, ja kiittäkäät häntä pelvolla ja vavistuksella; kiittäkäät häntä hänen töissänsä, ylistäkäät häntä, joka ijankaikkisesti hallitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Ja minä myös tahdon kiittää häntä tässä maassa, jossa me vankina olemme; sillä hän on näyttänyt ihmeensä syntiselle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Sentähden palatkaat, te syntiset, ja tehkäät vanhurskantta Jumalan edessä, ja uskokaat, että hän teille laupiutensa osoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Ja minä tahdon nyt sydämestäni iloita Jumalassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Kiittäkäät Herraa, te hänen valittunsa, pitäkäät ilopäiviä, ja kiittäkäät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Jerusalem, sinä Jumalan kaupunki! Jumala kurittaa sinua sinun töittes tähden, mutta hän taas armahtaa sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Kiitä Herraa hänen lahjainsa edessä, ja ylistä ijankaikkista Jumalaa, että hän taas rakentais sinun majas ja tois jälleen kaikki sinun vankis, niin ettäs iloitsisit ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Sinun pitää paistaman niinkuin kirkas valkeus, ja kaikissa maailman äärissä pitää sinua kunnioitettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Kaukaiselta maalta pitää sinun tykös tultaman, ja lahjoja kannettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Sinussa pitää rukoiltaman Herraa, ja sinua pitää pyhäksi kutsuttaman. Herran suurta nimeä pitää sinussa avuksihuudettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Kirotut pitää kaikki oleman, jotka katsovat sinua ylön; kadotetuksi pitää tuleman kaikki, jotka sinua pilkkaavat; siunatut pitää oleman kaikki, jotka sinua rakentavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Mutta sinun pitää iloitseman sinun lapsistas; sillä he tulevat kaikki siunatuksi, ja pitää koottaman Herran tykö. Autuaat ovat ne, jotka sinua rakastavat, ja jotka sinulle onnea toivottavat. Minun sieluni kiittäkään Herraa; sillä Herra meidän Jumalamme lunastaa Jerusalemin kaupungin kaikista murheistansa. Autuas minäkin olen, jos jääneet minun suvustani saavat nähdä Jerusalemin kunniassansa. Jerusalemin portit pitää saphirista ja smaragdista rakennetut oleman, ja kaikki hänen muurinsa kalliista kivistä joka puolelta. Valkiasta ja puhtaasta marmorista pitää kaikki hänen katunsa lasketut oleman, ja joka kadulla pitää veisattaman Halleluja! Kiitetty olkoon Jumala, joka hänen on korottanut, ja hänen valtakuntansa pysyköön ijankaikkisesti hänen päällänsä, amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Kuin nämät olivat tapahtuneet, ja Tobia oli näkönsä saanut jälleen, eli hän vielä sitte kaksiviidettäkymmentä ajastaikaa, ja näki lapsensa lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Ja kuin hän sadan ja kahden ajastajan vanhana oli, haudattiin hän Ninivessä kunniallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Sillä kuin hän kuudenkuudettakymmentä ajastajan vanha oli, tuli hän sokiaksi, ja kuudentenakymmenentenä vuonna sai hän näkönsä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Ja sen muun ikänsä kulutti hän ilolla ja menestyi Jumalan pelvossa, ja kuoli hyvässä rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Mutta ennen kuolemaansa kutsui hän poikansa Tobian eteensä, ja seitsemän nuorta poikaista, hänen poikansa lasta, ja sanoi heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Ninive pitää pian hävitettämän, sillä ei Herran sana puutu; mutta Mediassa pitää vielä sitte kauvan rauhan oleman, ja meidän veljemme, jotka Israelin maalta hajoitetut ovat, pitää tuleman jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Ja meidän maamme, joka nyt kylmillä on, pitää joka paikassa asutuksi tuleman. Ja Jumalan huone, joka poltettu on, pitää rakennettaman jälleen, ja kaikki, jotka Jumalaa pelkäävät, sinne tuleman jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Ja pakanat pitää myös hylkäämän epäjumalansa, ja tuleman Jerusalemiin ja siellä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Ja kaikki pakanat ja kuninkaat pitää siellä iloitseman, ja palveleman Israelin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Niin kuulkaat nyt, minun poikani, teidän isäänne: palvelkaat Herraa totuudessa, ja olkaat vaat hänessä, ja turvatkaat häneen täydellisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Tehkäät, mitä hän käskenyt on, ja opettakaat se teidän lapsillenne, että he myös almua antaisivat, että he aina Jumalaa pelkäisivät ja luottaisivat hänen päällensä kaikesta sydämestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Ja, rakkaat lapset, kuulkaat minua, ja älkäät pysykö tässä Ninivessä, vaan kuin te äitinne haudanneet olette minun tyköni minun hautaani, niin nouskaat menemään täältä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Sillä minä näen, että Niniven synti lopettaa hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Ja kohta äitinsä kuoleman jälkeen meni Tobia Ninivestä, emäntänsä, lastensa ja lasten lastensa kanssa Mediaan appensa ja emäntänsä sukuin tykö, ja löysi heidät terveinä hyvässä voimassansa, ja hän holhosi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Ja kuin he kuolivat, painoi hän myös heidän silmänsä kiinni, ja sai niin kaiken perinnön ja Raguelin tavaran, ja eli hamaan viidenteen polveen, ja näki lapsensa ja lastensa lapset. Ja kuin hän yhdeksänkymmenen ja yhdeksän vuotinen oli, jotka hän Jumalan pelvossa ilolla elänyt oli, hautasivat hänen sukunsa hänen. Ja kaikki hänen sukunsa elivät jumalisesti ja kunniallisesti, niin että he sekä Jumalalle että ihmisille ja kaikille, jotka maakunnassa asuivat, otolliset olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Arphaksad, Median kuningas, oli saanut allensa monta maakuntaa ja kansaa; ja hän rakensi jalon ja Suuren kaupungin, jonka hän kutsui Ekbatanaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Sen muurit teki hän vuojonkivistä, seitsemänkymmentä kyynärää korkiaksi ja kolmekymmentä kyynärää paksuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Hän teki sen tornit sata kyynärää korkiaksi ja kaksikymmentä kyynärää paksuksi, nelikulmaiseksi; ja kaupungin portit teki hän niin korkiaksi kuin tornitkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Ja luotti suureen sotaväkeensä ja voimaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Mutta Nebukadnetsar, Assyrian kuningas, hallitsi suuressa kaupungissa Ninivessä; ja toisena vuotena toistakymmentä hänen hallituksensa ajalla soti hän Arphaksania vastaan, ja voitti hänen Euphratin, Tygrin ja Hydaspen virran tykönä, sillä suurella Ragauin kedolla, joka muinen Ariokin Elassarin kuninkaan oli ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Silloit tuli Nebukadnetsarin valtakunta voimalliseksi, ja hänen sydämensä ylpiäksi; ja hän lähetti sanan kaikille niille, jotka asuivat Kilikiassa, Damaskuksessa, Libanonissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Karmelissa ja Kedarissa, ja niille Galileassa ja nilla suurella Esdrelomin kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ja kaikille niille, jotka olivat Samariassa ja toisella puolella Jordania, hamaan Jerusalemiin asti ja koko Gesemin maalle, hamaan Etiopian rajoihin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Kaikkein niiden tykö lähetti Nebukadnetsar, Assyrin kuningas sanansaattajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Mutta he katsoivat ne kaikkia ylön, ja antoivat sanansaattajat häpiällä kotia palata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Silloin vihastui kuningas Nebukadnetsar sangen kovia kaikkein maakuntain päälle, ja vannoi kuninkaallisen istuimensa ja valtakuntansa kautta, että hän kaikille näille maakunnille tahtoi kostaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Kolmantenatoistakymmenentenä kuningas Nebukadnetsarin vuotena, toisena päivänä kolmattakymmentä ensimmäisellä kuulla tuli päätetyksi Nebukadnetsarin, Assyrian kuninkaan huoneessa, että hänen piti kostaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Ja hän kutsutti tykönsä kaikki neuvonantajansa, ruhtinaansa ja päämiehensä, ja piti neuvoa salaisesti heidän kanssansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Ja ilmoitti heille, kuinka hän oli aikonut kaikki nämät maakunnat saattaa valtakuntansa alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Koska se heille kaikille niin kelpasi, kutsui kuningas Nebukadnetsar sotapäämiehensä Holoferneksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Ja sanoi hänelle: mene kaikkia valtakuntia vastaan, jotka lännessä ovat; ja erinomattain niitä vastaan, jotka ovat katsoneet ylön minun sanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Ei sinun pidä yhtään valtakuntaa säästämän; mutta kaikki vahvat kaupungit pitää sinun minulle alamaiseksi tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Niin Holofernes kutsui kokoon sodanpäämiehet ja Assyrian sotaväen ruhtinaat, ja valmisti väkeä sotaan, niin kuin kuningas hänelle käskenyt oli, sata ja kaksitoistakymmentä tuhatta jalkamiestä ja kaksitoistakymmentä tuhatta ampuvaista hevosmiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Ja antoi kaiken sotaväen mennä edellänsä, epälukuiset kamelit, äärettömän viljan, härjät ja lampaat, kansallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Ja antoi tuoda kaikesta Syriasta jyviä leiriinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Mutta kultaa ja rahaa otti hän sangen paljo myötänsä kuninkaan huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Ja meni matkaan koko sotajoukon kanssa, vaunuin, ratsasmiesten ja ampujain kanssa, jotka peittivät maan niin kuin heinäsirkat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Sittekuin hän oli vaeltanut Assyrian maan äären ylitse, tuli hän Angen vuorten tykö, vasemmalle puolen Kilikiata, ja voitti kaikki heidän kylänsä ja vahvat kaupunkinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Ja kukisti kuuluisan Melotin kaupungin ja ryösti kaiken väen Tarsiksessa ja Ismaelin lapset, jotka korvessa asuivat lounaan päin Kelonin maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Ja hän vaelsi Phratin virran ylitse ja tuli Mesopotamiaan ja kukisti kaikki korkiat kaupungit, jotka hän löysi, Mamren ojasta hamaan mereen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Ja voitti siellä Kilikian rajat Joppen rajoihin asti, jotka lounaasta päin ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Ja vei myös kaikki Madianin lapset pois, ja ryösti kaikki heidän tavaransa; ja tappoi kaikki ne, jotka olivat häntä vastaan, miekan terällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Sitte meni hän alas Damaskun maalle elonaikana, ja poltti kaiken heidän elonsa, ja antoi hakata maahan kaikki heidän puunsa ja viinapuunsa. Ja koko maakunta pelkäsi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Silloin lähettivät kuninkaat ja ruhtinaat Syriasta, Mesopotamiasta, Syrian Sobalista, Lybiasta ja Kilikiasta sanansaattajansa kaikista kaupungeista ja maakunnista, jotka tulivat Holoferneksen tykö ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Käännä vihas pois meidän päältämme; sillä se on parempi, että me elämme ja palvelemme suurten kuningasta Nebukadnetsaria, ja olemme sinulle alamaiset, kuin että hukumme, ja emme kuitenkaan mitään voita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'kaikki kaupunkimme, tavaramme, vuoremme, kukkulamme, peltomme, härkämme, lampaamme, vuohemme, hevosemme ja kamelimme, ja kaikki mitä meillä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Niin myös meidän perheemme, ovat sinun; tee niiden kanssa, mitäs tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Me myös ja meidän lapsemme olemme sinun palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Tule meidän tykömme ja ole meidän armollinen herramme; pidä meitä palvelianas, niin kuin sinä tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Niin läksi Holofernes alas vuorelta kaiken sotaväkensä kanssa, ja voitti vahvat kaupungit ja kaikki maan asuvaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Ja otti kaikista kaupungeista väkevät miehet palvelukseensa, valitut sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Josta kaikki maakunnat suuresti hämmästyivät, niin että ruhtinaat ja ylimmäiset kaikista kaupungeista ynnä kansan kanssa tulivat häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Ja ottivat hänen vastaan seppeleillä, hypyllä, rummuilla ja huiluilla. Ja ei kuitenkaan taitaneet niinkään armoa löytää: Sillä hän kukisti heidän kaupunkinsa, ja hakkasi maahan heidän metsistönsä. Sillä Nebukadnetsar oli hänen käskenyt hävittää kaikki jumalat maakunnista, että kaikki kansa, jotka Holefernes oli vaativa allensa, pitäis hänen ainoana jumalana. Kuin hän oli Syrian Sobalin, ja kaiken Aramean ja Mesopotamian lävitse vaeltanut, tuli hän Edomilaisten tykö Gabaan maalle. Ja voitti heidän kaupunkinsa, ja oli sillä kolmekymmentä päivää; sillä välillä antoi hän kaikki sotaväkensä tulla kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Kuin Israelin lapset, jotka Juudan maalla asuivat, sen kuulivat, pelkäsivät he häntä suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Ja vavistus ja hämmästys oli heidän päällensä tullut; sillä he pelkäsivät hänen niin tekevän Jerusalemille ja Herran templille, kuin hän muillekin epäjumalansa huoneille oli tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Sentähden lähettivät he koko Samarian hamaan Jerichoon asti, ja vahvistivat kaikki linnat vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Ja tekivät muurit kyläinsä ympärille, ja toimittivat itsellensä viljaa sodan varaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Ja ylimmäinen pappi Jojakim kirjoitti kaikkein tykö, jotka asuivat Esdrelomia päin&, se on sen suuren kedon tykönä Dotaimissa ja kaikkein niiden tykönä, joiden kautta vihollinen oli tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Että he varjelisivat kukkulat vuorilla, Jerusalemiin päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Ja Israelin lapset tekivät niin kuin Jojakim, Herran pappi, heille oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Ja kaikki kansa huusi hartaasti Herran tykö, ja nöyryyttivät heitänsä, he ja heidän vaimonsa, paastolla ja rukouksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Mutta papit pukivat säkit yllensä, ja lapset makasivat Herran templin edessä; ja he peittivät Herran alttarin säkillä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Ja huusivat Herran Israelin Jumalan tykö yksimielisesti, ettei heidän lapsensa ja vaimonsa vietäisi pois saaliiksi jaettaviksi ja ettei heidän kaupunkinsa hävitettäisi ja heidän pyhänsä saastutettaisi, ja ettei he pakanoilta häväistyksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Ja Jojakim, Herran ylimmäinen pappi kävi ympäri, neuvoi koko Israelin kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Ja sanoi: teidän pitää tietämän, että Herra on teidän rukouksenne kuuleva, jos ette lakkaa paastoomasta ja rukoilemasta Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Ajatelkaat Moosesta Herran palveliaa, joka ei miekalla, vaan pyhällä rukouksella löi Amalekin, joka luotti voimaansa ja väkeensä ja sotajoukkoonsa, kilpeensä, vaunuihinsa ja ratsasmiehiinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Niin se myös pitää tapahtuman kaikille Israelin vihollisille, jos te niin itsenne parantaa tahdotte, kuin te nyt ruvenneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Tämän neuvon jälkeen rukoilivat he Herraa, ja jäivät Herran eteen: niin että papit kävivät säkissä, ja pitivät tuhkaa päänsä päällä, ja tekivät Herralle polttouhria; Ja rukoilivat kaikki Herraa kaikesta sydämestänsä, että hän tahtoi etsiä kansaansa Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Ja Holofernekselle, Assyrian sotapäämiehelle sanottiin, että Israelin lapset varustivat itsensä, ja tahtoivat itsensä varjella, ja kuinka he olivat ottaneet vaarin kukkuloista mäillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Silloin julmistui Holofernes, ja kutsui kaikki Moabilaisten ja Ammonilaisten ylimmäiset ja päämiehet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Ja sanoi heille: sanokaat minulle, mikä kansa se on, joka vuorilla asuu? Kutka heidän suuret kaupunkinsa ovat, mitä he voivat, ja mitkä heidän sotaväkensä ovat, ja kuka heidän kuninkaansa on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Että he ainoasti kaikista muista itäisellä maalla katsovat meitä ylön, ja ei ole tulleet meitä vastaan, ottamaan meitä vastaan rauhalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Silloin vastasi Akior, kaikkien Ammonin lasten päämies, ja sanoi: minun herrani, jos sinä tahdot mielelläs kuulla, niin minä sanon sinulle totuuden tästä kansasta, joka vuorilla asuu; ja en minä tahdo valhetella sinun edessäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Tämä kansa on Kaldeasta tullut; ja on ensisti asunut Mesopotamiassa; ettei he tahtoneet seurata isäinsä jumalia Kaldeassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Sentähden hylkäsivät he isäinsä säädyt, joilla paljon jumalia oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Ja palvelivat yhtä ainoaa taivaan Jumalaa, joka heidän käski mennä sieltä pois, ja asua Haranissa. Kuin kaikissa niissä maakunnissa kallis aika oli. vaelsivat he alas Egyptin maalle; siellä ovat he paljoksi tulleet neljässä sadassa ajastajassa, ettei heidän joukkoansa taidettu lukea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Mutta kuin Egyptin kuningas vaivasi heitä saven kantamisella ja tiilien teolla, rakentaa hänen kaupunkiansa. huusivat he Herransa tykö, joka löi koko Egyptin moninaisilla vitsauksilla');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Kuin Egyptiläiset olivat ajaneet pois heidät tyköänsä, ja vaiva lakkasi heistä, ja tahtoivat heitä taas käsittää, ja viedä orjuuteen jälleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Avasi taivaan Jumala meren, niin että vedet kahden puolen seisoivat, niin kuin muurit; ja he kävivät kuivin jaloin meren pohjaa myöten, ja pääsivät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Mutta kuin Egyptiläiset kiiruhtivat heidän peräänsä koko joukkonsa kanssa, tulivat he kaikki upotetuksi mereen, niin ettei yksikään jäänyt, joka sen muille olis ilmoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Ja kuin tämä kansa tuli Punaisesta merestä, sioittivat he itsensä Sinain vuorten korpeen, jossa ei yksikään ihminen ennen asua eli elää taitanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Siellä tuli halkia vesi makiaksi, niin he saivat juoda, ja he saivat leipää taivaasta neljäkymmentä ajastaikaa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Ja kuhunka he menivät ilman jousia ja nuolia, ilman kilpeä ja miekkaa, siellä soti heidän Jumalansa heidän edestänsä, ja he saivat voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Ja ei yksikään taitanut tätä vahingoittaa, mutta ainoastaan silloin, kun he luopuivat Herran Jumalansa käskyistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Sillä niin usein kuin he rukoilivat muita paitsi Jumalaansa, niin heidät lyötiin ja vietiin pois häpiällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Mutta niin usein kuin he katuivat, että heidän Jumalansa käskyistä poikenneet olivat, antoi taivaan Jumala heille taas voiton vihollisiansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Sentähden hävittivät he Kanaanealaisten kuninkaat, Jebusilaiset, Phereläiset, Hetiläiset, Heviläiset, Amorilaiset, ja kaikki voimalliset Hesbonissa, ja ottivat heidän maansa ja kaupunkinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Ja he menestyivät niin kauan kuin ei he syntiä tehneet Jumalaansa vastaan; sillä heidän Jumalansa vihaa vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'He ovat myös usein ennen tätä aikaa olleet ajetut pois monelta kansalta, ja viedyt pois vieraalle maalle, että he olivat poikenneet siitä käskystä, jonka Jumala heille oli antanut, että heidän piti siinä vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Mutta he ovat äsken tulleet siitä viheliäisyydestä, jossa he olleet olivat, sittekuin he olivat kääntyneet Herran Jumalansa tykö, ja niin ovat asettaneet itsensä tälle vuorelle: ja asuvat Jerusalemissa, jossa heidän pyhänsä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Sentähden, minun herrani, anna kysellä, jos tämä kansa on syntiä tehnyt Jumalaansa vastaan, niin me menemme sinne ylös, ja heidän Jumalansa antaa totisesti heitä sinun käsiis; niin että sinä heitä saat vaatia sinua vainos ikeen alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Mutta jos ei he ole syntiä tehneet Jumalaansa vastaan, niin emme voi mitään heitä vastaan; sillä heidän Jumalansa varjelee heidät, ja me tulemme häpiään kaikessa maassa. Kuin Akior näitä sanonut oli, tulivat kaikki Holoferneksen päämiehet vihaisiksi, ja ajattelivat häntä tappaa, ja sanoivat toinen toisellensa: Kuka tämä on, joka sitä sanoa tohtii, että Israelin lapset taitavat varjella itsensä kuningas Nebukadnetsaria ja hänen sotajoukkoansa vastaan? Eikö he kaikki ole aseettomat, ja ei yksikään ole sotamies. Mutta että Akior näkis itsensä valhetelleeksi, niin käykäämme sinne ylös; ja kuin me heidän parhaan väkensä käsitämme, niin me annamme pistää Akiorin lävitse ynnä heidän kanssansa. Että kaikki kansa ymmärtäis Nebukadnetsarin olevan jumalan maan päällä, ja ei yhdenkään muun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Silloin julmistui Holofernes Akiorin päälle, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Kuinka sinä rohkeat ennustaa, että Israelin kansalla on varjelus Jumalaltansa? Kuin me nyt lyömme heidät, niinkuin yhden miehen, pitää sinun näkemän, ettei yhtään muuta Jumalaa ole paitsi Nebukadnetsaria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ja päälliseksi pitää sinäkin Assyrian miekalla pistettämän lävitse; ja koko Israelin pitää sinun kanssas hukkuman');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Niin sinä saat ymmärtää, että Nebukadnetsar kaiken maailman herra on, kuin sinä minun sotaväkeni miekalla pistetään lävitse, ja makaat Israelin lyötyin kanssa kuolleena, ja sinun täytyy kuolla ja hukkua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Mutta jos sinä luulet, että sinun ennustukses on tosi, niin ei sinun tarvitse hämmästyä eli vaalistua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Niinkuin heille käy, niin pitää myös sinulle käymän; sillä minä lähetän nyt sinun heille, että minä rankaisisin sinua ynnä heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Niin käski Holofernes palveliainsa ottaa Akiorin kiinni, ja viedä Betuliaan Israelin lasten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Ja Holoferneksen palveliat ottivat hänen kiinni. Ja kuin he tulivat kedon ylitse vuorten tykö, menivät ampuja heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Silloin poikkesivat he vuoren sivulle, ja sitoivat Akiorin käsistä ja jaloista puuhun, sysäsivät maahan, ja jättivät riippumaan, ja menivät herransa tykö jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Mutta Israelin lapset tulivat alas Betuliasta hänen tykönsä ja, ja päästivät hänen vallallensa, ja veivät Betuliaan, ja asettivat hänen kansansa keskelle, ja kyselivät häneltä, kuinka hänen kanssansa menty oli, ja minkätähden Assyrialaiset olivat hänen hirttäneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Silloin olivat siellä kaupungin päämiehet, Otsia Miikan poika, Simeonin suvusta, ja Karmi, joka myös Otonieliksi kutsuttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Akior sanoi vanhinten ja kaiken kansan edessä kaikki, mitä Holofernes häneltä kysynyt, ja hän hänelle vastannut oli, ja kuinka Holoferneksen väki siitä vastauksesta tahtoivat hänen tappaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Ja kuinka Holofernes oli vihastunut ja käskenyt hänen antaa Israelin lasten käsiin, että kuin hän Israelin lapset sais lyödyksi, rankaisis ja surmais hän myös Akiorin, etä hän oli sanonut: taivaan Jumala on heidän varjeluksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Kuin Akior kaikkia näitä puhunut oli, lankesi kaikki kansa kasvoillensa, rukoilivat Herraa ja itkivät yhteen suuhun, ja rukoilivat yksimielisesti Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'ja sanoivat: Herra taivaan ja maan Jumala, katso heidän ylpeyttänsä ja meidän nöyryyttämme, ja katso armollisesti sinun pyhiäs, ja osoita, ettet niitä hylkää, jotka toivovat sinun päälles; ja ettäs kukistat ne maahan, jotka itseensä ja väkeensä luottavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Ja niin he itkivät ja rukoilivat kaiken sen päivän, ja lohduttivat Akioria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Ja sanoivat: meidän isäimme Jumala, jonka voiman sinä ylistänyt olet, on sinulle niin kostava, ettei he saa iloita sinusta; mutta sinä saat nähdä, kuinka he lyödyksi ja maahan kaadetuksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Ja kuin Herra meidän Jumalamme pelastaa meidät, niin olkoon Jumala sinun kanssasi meidän seassamme. Ja jos sinä tahdot, niin sinä saat kaikkein sinun omaistes kanssa asua meidän seassamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Kuin nyt kansa toinen toisestansa erkanivat, otti Otsi hänen huoneeseensa kanssansa ja valmisti suuren ehtoollisen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Ja kutsui tykönsä kaikki vanhimmat, ja virvoitti itsiänsä, että he kauvan olivat ennen paastonneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Niin kansa taas kutsuttiin kokoon; ja rukoilivat apua Israelin Jumalalta kokouksissansa kaiken yön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Toisena päivänä käski Holofernes sotaväkensä olla valmiina Betuliaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Ja hänellä oli sata ja kaksikymmentä tuhatta jalkamiestä ja kaksitoistakymmentä tuhatta hevosmiestä, paitsi sitä joukkoa, jonka hän oli ottanut kaikista nuorukaisista joka kaupungista, kussa hän jonkun maakunnan saanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Tämä sotajoukko valmisti itsensä Israelin lapsia vastaan, ja sioitti itsensä vuorille, Dotaimin kohdalle, aina Belmasta hamaan Kelmoniin asti, joka oli Esdrelomin kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Kuin Israelin lapset näkivät Assyrian kansan paljouden, lankesivat he maahan, ja priiskottivat tuhkaa päänsä päälle, ja rukoilivat kaikki yksimielisesti, että Israelin Jumala tahtois näyttää laupiutensa kansallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'ja he varustivat itsensä sota-aseinensa, ja pitivät vaarin vuortensa kukkuloista, ja varjelivat niitä yöt ja päivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Mutta kuin Holofernes vaelsi siinä ympäriinsä, ymmärsi hän, että ulkoisella puolella kaupunkia oli kaivo, joka torvilla kaupunkiin johdatettu oli; nämät torvet antoi hän poikki hakata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Ja vaikka vähät kaivot ei olleet kaukana muurista, joista he salaa vettä toivat; niin niissä oli kuitenkin tuskin niin paljon, että he itsensä virvoittaa taisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Sentähden tulivat Ammonilaiset ja Moabilaiset Holoferneksen tykö, ja sanoivat: ei Israelin lapset tohdi varjella itsiänsä meitä vastaan keihäillä ja nuolilla; mutta vuorilla ja kukkuloilla, joissa he rauhassa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Sentähden anna varjella kaivot, ettei he saisi vettä; niin täytyy heidän kuolla ilman miekkaa, eli hätä vaatii heidät antamaan kaupungin, jonka he luulevat voittamattoman olevan, että se on vuorilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Tämä neuvo kelpasi Holofernekselle ja hänen sotaväellensä; ja hän asetti miestä joka kaivon tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Kuin he kaksikymmentä päivää olivat kaivoja vartioineet, ja Betulisaas ei ollut enää vettä, ei kaivoissa eikä muualla, niin ettei he yhtään päivää enään itsiänsä taitaneet virvoittaa, ja heidän täytyi joka päivä antaa mitalla vettä kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Silloin tulivat kaikki miehet ja vaimot, nuoret ja vanhat Otsian tykö, vanhimmat ja lapset, valittivat kaikki yhteen suuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Ja sanoivat: Jumala olkoon teidän ja meidän vaiheellamme tuomari, että te saatatte meidät senkaltaiseen hätään, ettette anna meidän tehdä rauhaa Assyrialaisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Ja sentähden Jumala on meidät myynyt heidän käsiinsä, ja ei meillä ole yhtään apua, mutta meidän täytyy nääntyä janoon heidän silmiensä edessä, ja hukkua surkiasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Sentähden kutsukaat kokoon kaikki, jotka kaupungissa ovat, että me antaisimme itsemme Holoferneksen haltuun;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Sillä on parempi, että me annamme itsemme ja pääsemme henkiin, kunnioittain Jumalaa, kun että me hukumme, ja tulemme kaikelle maailmalle häpiäksi, kuin meidän täytyy nähdä, että meidän vaimomme ja lapsemme surkiasti meidän silmäimme edessä kuoleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Me todistamme tänäpänä taivaan ja maan ja meidän isäimme Jumalan edessä, joka meitä rankaisee meidän syntiemme tähden, että me olemme rukoilleet teitä antamaan Holofernekselle kaupunkia, ettemme äkisti kuolisi miekalla, ja ettemme kaikki nääntyisi janosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Silloin oli suuri itku ja valitus kaikella kansalla; muutamat seisoivat kauvan ja huusivat Jumalaa tykö ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Me olemme syntiä tehneet ynnä meidän isäimme kanssa, me olemme väärin tehneet ja olleet jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Mutta sinä olet laupias, sentähden ole meille armollinen ja rankaise itse meitä: ja että me sinun tunnustamme, niin älä meitä hylkää pakanain käsiin, jotka eivät sinua tunne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Ettei he kerskaisi, sanoen, kussa on nyt heidän Jumalansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Kuin he jo kauvan huutaneet ja itkeneet olivat ja jo jotakin jälleen vaikenivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Nousi Otsia, itki ja sanoi, hyvät veljet, olkaat kuitenkin kärsivälliset, ja odottakaamme vielä viisi päivää Jumalan apua:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Jos hän tahtoo meille armon osoittaa, ja nimensä kuuluisaksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Jos ei meitä näinä viitenä päivänä auteta, niin me teemme, niinkuin te anoneet olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Tämä tuli Juditin eteen, joka leski oli, Meratin tytär, Utsin pojan, Josephin pojan, Otsian pojan, Jamnorin pojan, Gedeonin pojan, Raphaimin pojan, Akitobin pojan, Malkian pojan, Enanin pojan, Natanian pojan, Sealtielin pojan, Simeonin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Ja hänen miehensä oli Manasse, joka elonaikana kuollut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Sillä, kuin hän ooli kedolla työväen tykönä, tuli hän helteessä sairaaksi, ja kuoli Betuliassa omassa kaupungissansa, ja haudattiin isäinsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Hän jätti Juditin jälkeensä, joka kolme ajastaikaa oli leskenä ollut ja neljä kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Ja oli tehnyt huoneensa päälle salaisen makaushuoneen, jossa hän piikoineen oleskeli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Ja oli puettu säkkiin, ja paastosi joka päivä, paitsi sabbatia, uutta kuuta ja muita Israelin huoneen juhlia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Ja hän oli aivan ihana ja rikas, ja hänellä oli paljon palkollisia, ja tarhat täynnä härkiä ja lampaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Ja hänestä puhui jokainen hyvin, että hän pelkäsi Jumalaa; ja ei yksikään tiennyt hänestä mitään pahuutta sanoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Kuin tämä Judit kuuli, että Otsia oli luvannut antaa kaupungin viiden päivän perästä Assyrialaisille, lähetti hän vanhinten Kambrin ja Kamrin perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Ja kuin he tulivat hänen tykönsä, sanoi hän heille: mikä se pitää oleman, että Otsia on luvannut antaa kaupungin Assyrialaisille, jos ei meitä viidessä päivässä auteta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Mitkä te olette, että kiusaatte Jumalaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Ei niin sovi armoa kerjätä, mutta pikemmin vihaa ja vainoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Tahdotteko te asettaa Herralle ajan ja päivän tiedän mielenne jälkeen, kuin hänen pitäisi auttaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Kuitenkin on Herra kärsivällinen; sentähden pitää meidän katuman, ja etsiä armoa kyynelillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Sillä ei Jumala vihastu niinkuin joku ihminen, ettei hän itsiänsä anna lepyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Sentähden pitää meidän nöyryyttämän itsiämme sydämestä ja nöyryydessä häntä palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Ja meidän pitää itkien häntä rukoileman, että hän suosionsa perästä tahtois osoitta meille laupiuden: ja niinkuin meidän nyt täytyy murehtia heidän ylpeytensä tähden, että me tämän surun jälkeen taas iloitsisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Ettemme meidän isiäimme syntiä ole seuranneet, joka Jumalansa hylkäsivät, ja palvelivat vieraita jumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Jonka tähden he vihollisillensa annettiin, lyötiin, vangittiin ja häväistiin; mutta emme tunne muuta jumalaa, kuin hänen ainoan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Ja tahdomme nöyryydellä toivoa häneltä apua ja lohdutusta; niin Herra meidän Jumalamme vapahtaa meidän veremme meidän vihollisiltamme, ja sortaa ja häpiään saattaa kaikki pakanat, jotka meitä vainoovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Ja te, rakkaat veljet, jotka vanhimmat Jumalan kansan seassa olette, lohduttakaat kansaa puheillanne ajattelemaan, kuinka meidän isämme myös kiusattiin, että heitä koeteltaisiin, jos he olisivat palvelleet Jumalaa sydämestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Muistuttakaat heille, kuinka meidän isämme Abraham monella tavalla koeteltiin, ja tuli Jumalan ystäväksi, sittekuin hän moninaisella ahdistuksella koeteltu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Niin myös Isaak, Jakob, Moses ja kaikki, jotka Jumalalle ovat otolliset olleet, ovat monta vaivaa voittaneet ja pysyneet vahvana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Mutta muut, jotka ei tahtoneet ottaa murheita vastaan Jumalan pelvossa, vaan ovat kärsimättömyydestä nurisseet Jumalaa vastaan ja pilkanneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Ne kadotettiin turmelialta ja kärmeiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Älkäämme sentähden olko kärsimättömät tässä vaivassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Mutta tunnustakaamme, että tämä rangaistus on Jumalalta paljon vähempi kuin meidän syntimme ovat, ja uskokaamme, että meitä kuritetaan, niinkuin hänen palvelioitansa parannukseen, ja ei kadotukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Siihen vastasi Otsia ja vanhimmat: se on kaikki toisi, minkä sinä sanonut olet, ja sinun sanoissas ei ole mitään vilppiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Rukoile sentähden meidän edestämme Herraa; silla sinä olet pyhä ja jumalinen vaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Ja Judit sanoi heille: että te luulette sen olevan Jumalalta, jonka minä sanonut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Niin koetelkaat nyt, onko se, jota minä olen aikonut tehdä Jumalalta: ja rukoilkaat, että Jumala antais sen menestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Olkaat tämä yö portin tykönä, kuin minä menen siitä ulos piikoineni, ja rukoilkaat, että Herra näinä viitenä päivänä, joissa te sanoneet olette, tahtois lohduttaa kansaansa Israelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Mutta mitä minä aikonut olen, ei teidän pidä sitä tutkiman; vaan rukoilkaat ainoasti minun edestäni Herraa Jumalaamme, siihenasti kuin minä ilmoitan teille, mitä teidän pitää tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Ja Otsia, Juudan päämies, sanoi hänelle: mene rauhaan, Herra olkoon sinun kanssas, ja kostakoon meidän tähtemme vihollisille! ja niin he läksivät pois hänen tyköänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Sitte meni Judit kammioonsa, ja puetti itsensä säkkiin, ja priiskotti tuhkaa päänsä päälle, ja lankesi Herran eteen, huusi häntä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Herra, minun isäni Simeonin Jumala, joka annoit hänelle miekan, rangaista pakanoita, jotka neitseitä häpäisivät ja häpiään saattivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Ja annoit vangita heidän vaimonsa ja tyttärensä, ja ryöstätit heitä sinun palvelias kautta, joka sinun kiivaudessas palavat olivat: auta minua köyhää leskeä, Herra, minun Jumalani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Sillä kaikki apu, joka muinen ja sitte joskus on tapahtunut, On sinulta tullut; ja mitä sinä tahdot, sen pitää tapahtuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Sillä kaikki sinun ties ovat valmistetut, ja sinun tuomios olet sinä pannut sinun edeskatsomisees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Katso nyt Assyrialaisten sotajoukkoa, niinkuin sinä muinen Egyptiläisten sotajoukkoa katsoit, kuin he sinun palvelioitas ajoivat takaa suurella joukolla, ja luottivat vaunuihinsa, ratsasmiehiinsä ja paljoon väkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Mutta kuin sinä katsoit heidän päällensä, niin pimeys peljästytti heidät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Ja syvyys kiiruhti heidän ylitsensä, ja vedet upottivat heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Niin myös nyt näillekin tapahtukoon, Herra, jotka luottavat omaan väkeensä, vaunuihinsa, keihäisiinsä ja joutsiinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Ja ei tunne sinua, että sinä Herra meidän Jumalamme olet se, joka sodat asetat alusta, ja sinun nimes on Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Ojenna käsivartes niinkuin entisinä aikoina, ja lyö vihollisia sinun voimallas, että he sinun vihassas hukkuisivat, jotka kehuvat, että he tahtovat sinun pyhäs kukistaa, ja lupaavat miekalla lyödä maahan sinun alttaris.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Rankaise heidän ylpeytensä heidän omalla miekallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Että hän omain silmäinsä kautta käsitettäisiin, kun hän katsoo minun päälleni; ja niin minun suloisten sanaini kautta vietellyksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Anna minulle rohkeus, etten minä häntä eli hänen väkeänsä hämmästyisi, mutta että hänet kukistaisin. Sillä se on sinun nimelles kunniaksi, että vaimo on kaatanut hänet maahan. Silla sinä, Herra, taidat ilman väen paljoutta antaa voiton, ja ei ole sinulla halua hevosten väkevyyteen; et myös ylpiät ole koskaan sinulle otolliset olleet, mutta sinulle ovat aina otolliset siviäin ja nöyräin rukoukset. O Herra taivaan Jumala, vetten Luoja ja kaikkein luotuin Herra! kuule minun köyhän rukoukseni, joka ainoasti sinun laupeuteesi luotan. Muista sinun liittoas, Herra, ja anna minun suuhuni sanat; mitä minun pitää puhuman ja ajatteleman pitää, anna minulle siihen onni, Että sinun huonees pyhänä pysyis, ja kaikki pakanat ymmärtäisivät, että sinä olet Jumala, ja ei yhtäkään muuta, paitsi sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Kuin hän rukoilemasta lakannut oli, nousi hän ja kutsui piikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'ja meni huoneeseen alas, ja riisui säkin, ja pani pois leskenvaatteensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Ja pesi itsensä, ja voiteli kalliilla vesillä, ja palmikoitsi hiuksensa, ja pani pääliinan päähänsä, ja otti kauniit vaatteet yllensä, ja kaunisti itsensä otsarihmoilla ja seppeleillä, ja puki yllensä kaikki kaunistuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'ja Herra antoi hänelle armon, että hän oli sangen ihana nähdä; sillä hän ei kaunistanut itseänsä hekumasta, mutta Jumalan kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Ja hän antoi piiallensa viinaleilin ja öljyastian, ja fikunia, jauhoja ja leipiä, ja hän meni matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'ja hän löysi portin tyköä Otsian ja vanhimmat, jotka häntä odottivat, niinkuin määrätty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Ja kuin hänen näkivät, ihmettelivät he suuresti hänen kauneuttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Mutta ei he kysyneet, mitä hän aikonut oli, vaan päästivät hänen ulos, ja sanoivat: meidän isäimme Jumala antakoon sinulle armon, ja sinun aikomises menestyä! että Israel iloitsis sinusta, ja sinun nimes tulis luetuksi pyhäin hurskaiden sekaan');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'ja kaikki, jotka siinä olivat, sanoivat: Amen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Mutta Judit rukoili Herraa, ja meni matkaansa piikansa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'ja kuin hän varhain aamulla meni alas vuorelta, kohtasivat häntä Assyrialaisten vartiat, ja karkasivat hänen tykönsä, ja kysyivät häneltä, kusta hän oli tullut, ja kuhunka hän tahtoi mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Hän vastasi: minä olen Hebrealainen vaimo, ja olen heidän tyköänsä paennut; sillä minä tiedän heidät tulevan teidän käsiinne, että he ovat katsoneet teitä ylön, ja ei tahdo armoa etsiä, ja itsiänsä mielellänsä antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Sentähden olen minä aikonut tulla päämiehen Holoferneksen eteen, että minä ilmoittaisin hänelle heidän salautensä, ja sanoisin hänelle, kuinka huokiasti hän heidät taitais voittaa, niin ettei hän yhtään miestä tarvitse siinä hukata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Kuin ne miehet kuulivat hänen sanansa, katsoivat he hänen päällensä, ja ihmettelivät sangen suuresti, että hän oli niin ihana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'ja sanoivat hänelle: se sinua kyllä auttava on, ettäs sen neuvon löytänyt olet, tullakses meidän herramme tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Sillä kuin sinä tulet hänen eteensä, niin on hän sinulle armollinen, ja sinä olet sangen sydämestä hänelle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'ja he veivät hänen Holoferneksen majaan, ja sanoivat hänestä hänelle. Ja kuinka hän tuli hänen eteensä, syttyi hän häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Ja hänen palveliansa sanoivat toinen toisillensa: Hebrean kansa ei ole suinkaan ylönkatsottava, jossa niin ihanat vaimot ovat; emmekö me senkaltaisten ihanaisten vaimoin tähden sotisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Kuin Judit näki Holoferneksen istuvan telttansa alla, joka kauniisti kudottu oli, purpurasta ja kullasta, smaragdilla ja monella kalliilla kivillä kaunistettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Lankesi hän hänen eteensä maahan, ja kumarsi häntä. Ja Holofernes käski hänen nousta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Ja Holofernes sanoi hänelle: ole hyvässä turvassa, ja älä pelkää, sillä en minä ikänä ole kellenkään vahinkoa tehnyt, joka itsensä kuningas Nebukadnetsarin alle mielellänsä antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Ja jos ei sinun kansas olisi katsonut minua ylön, niin en minä koskaan yhtäkään asetta heitä vastaan ylentänyt olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Sano siis, minkätähden sinä ole heidän tyköänsä paennut, ja tullut meidän tykömme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Judit vastasi ja sanoi: kuule sinun piikaas armollisesti; jos sinä niin tehdä tahdot, kuin sinun piikasi sinulle sanova on, niin Herra antaa sinulle onnen ja voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Jumala antakoon Nebukadnetsarille onnea ja terveyttä, koko maan kuninkaalle, joka on sinun lähettänyt kaikkia uppiniskaisia rankaiseman; sillä sinä taidat hänelle alamaiseksi tehdä, ei ainoasti kansaa, mutta myös kaikki pedot kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Sinun toimes ja viisautes on kuuluisa koko maailmassa, ja joka mies tietää sinun olevan jaloimman ruhtinaan koko valtakunnassa, ja sinun hyvä hallitukses ylistetään kaikkien ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Me tiedämme myös, mitä Akior sanonut on, ja kuinka sinä sitä vastaan hänelle tehnyt olet');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Sillä meidän Jumalamme on niin vihainen meidän synteimme tähden, että hän on prophetain kautta antanut ilmoittaa tahtovansa rangaista kansaa heidän synteinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Että nyt Israelin lapset tietävät vihoittaneensa Jumalansa, niin he ovat sinua hämmästyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Kärsivät myös päälliseksi suurta nälkää, ja heidän täytyy janon tähden nääntyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'He ovat nyt aikoneet teurastaa karjansa, juodaksensa niiden verta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Ja syödäksensä sitä pyhää uhria jyvistä, viinasta ja öljystä, josta Jumala heitä kieltänyt on, ettei heidän siihen pitäisi ryhtymän. Sentähden on se tosi, että meidän pitää hukkuman, jotka senkaltaista tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Ja että minä, sinun piikas, sen tiedän, olen minä heiltä paennut; ja Herra on minun lähettänyt sinun tykös näitä sinulle sanoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Sillä vaikka minä olen tullut sinun tykös, niin en minä ole kuitenkaan sentähden Jumalasta luopunut, mutta tahdon vielä nyt minun jumalaani palvella sinun tykönäs; ja sinun piikas tahtoo mennä ulos Jumalaa rukoilemaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Joka minulle ilmoittaa, koska hän tahtoo heitä rangaista heidän synteinsä tähden; niin minä tulen ja teen sinulle tiettäväksi ja vien sinun keskelle Jerusalemia, niin sinä saat haltuus kaiken Israelin kansan, niinkuin lampaat, joilla ei paimenta ole, ja ei koirakaan tohdi haukkua sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Sillä Jumala on minulle nämät ilmoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Että hän on heille vihainen, ja niiin on minun tänne lähettänyt sinulle sanomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Tämä puhe kelpasi Holofernekselle ja hänen palvelioillensa; ja he ihmettelivät hänen viisauttansa, ja sanoivat keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Ei ole tämän vaimon kaltaista maan päällä kauneudessa ja viisaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Ja Holofernes sanoi hänelle: sen on Jumala niin laittanut, ja lähettänyt sinun tänne, ennenkuin kansa minun käsiini tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Jos sinun Jumalas tämän niin tekee kuin sinä sanot, niin hänen pitää myös oleman minun Jumalani; ja sinä olet suureksi tuleva Nebukadnetsarin tykönä, ja sinun nimes tulee kuuluisaksi koko valtakunnassa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Silloin käski hän hänen mennä tavaramajaansa olemaan, ja käski ruokkia häntä omalta pöydältänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Mutta Judit vastasi ja sanoi: en minä vielä tohdi syödä sinun ruoastas etten minä syntiä tekisi; mutta minulla on itselläni vähä myötäni, josta minä tahdon syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Holofernes sanoi hänelle: koskas sen syöt, kuin sinun myötäs on, kusta me sitte enempää saamme sinulle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Judit vastasi: niin totta kuin sielus elää, minun herrani, ennen kuin sinun piikas sen kaiken on syönyt, niin Jumala on minun kauttani toimittava, mitä hänen mielessänsä on, Ja palveliat veivät hänen majaan, niinkuin käsketty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Ja hän rukoili, että he sallisivat hänen mennä ulos ehtoolla ja aamulla, rukoilemaan Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Niin Holofernes käski kamaripalvelijoittensa sallia hänen kolme päivää vapaasti käydä ulos ja sisälle, rukoilemaan Jumalaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Ja hän läksi ehtoona ulos laaksoon Betunian eteen, ja pesi itsensä vedessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Sitte rukoili hän Herraa Israelin Jumalaa, että hän tahtois antaa hänen tiensä menestyä, vapahtamaan hänen kansaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Ja meni jälleen majaan, ja piti itsensä puhtaana, eikä syönyt mitään ennen ehtoota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Ja neljäntenä päivänä teki Holofernes ainoastaan palvelioillensa ehtoollisen, ja sanon Bagoalle, kamaripalveliallensa: mene ja puhu sille Hebrean vaimolle, ettei hän estele tullaksensa minun tyköni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Sillä se olis suuri häpeä Assyrialaisille, että senkaltainen vaimo pääsis makaamatta meidän tyköämme, ja niin viettelis miehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Niin tuli Bagoa Juditin tykö, ja sanoi: oi ihanainen vaimo, älä estele tulla minun herrani tykö kunniaksi, syömään, ja juomaan ja iloitsemaan hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Silloin sanoi Judit: kuinka minä tohdin sen kieltää minun herraltani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Kaikki, mitä hänelle otollinen on, tahdon minä mielelläni tehdä kaikkena minun elinaikanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'ja hän nousi ja kaunisti itsensä, meni hänen eteensä, ja seisoi hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Silloin liikkui Holoferneksen sydän; sillä hän syttyi himoon hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Ja hän sanoi hänelle: istu, juo ja ole iloinen; sillä sinä olet löytänyt armon minun tykönäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Judit vastasi: jopa herra, minä tahdon olla iloinen; sillä minä ole ollut minun elinaikanani niin korkiasti kunnioitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Ja hän söi ja joi hänen edessänsä, mitä hänen piikansa hänelle valmistanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Ja Holofernes oli iloinen hänen tähtensä, ja joi ylen paljon viinaa, ettei hän ikänä niin paljon juonut ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Ehtoona hiljaan menivät palveliansa majoihinsa ja olivat kaikki juopuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Ja Bagoa lukitsi Holoferneksen majan, ja meni matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Ja Judit jäi yksinänsä hänen tykönsä majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Kuin Holofernes makasi vuoteessa, ja oli kovin juovuksissa nukkunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Sanoi Judit piiallensa, että hän seisois oven edessä ja vartioitsis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Ja Judit seisoi vuoteen edessä, ja rukoili salaisesti kyyneleillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Ja sanoi: Herra Israelin Jumala, vahvista minua ja auta nyt minua armollisesti täyttämään sitä työtä, jota minä, sinuun luottain, olen aikonut tehdä; ettäs korottaisit kaupunkis Jerusalemin, niinkuin sinä luvannut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Sen rukouksen jälkeen meni hän pään puoleen vuodetta ja otti miekan, joka siinä riippui, ja veti sen ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Ja tarttui hänen hiuksiinsa ja sanoi taas: Oi Herra Jumala, vahvista minua tällä hetkellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Ja hän hakkasi häntä kahdesti kurkkuun kaikella voimalla; sitte leikkasi hän pois hänen päänsä, ja vieritti ruumiin vuoteesta ulos, ja otti peitteen myötänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Sitte meni hän ulos ja antoi piiallensa Holoferneksen pään, ja pani sen evässäkkiinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Ja he menivät ynnä ulos niinkuin heidän tapansa oli mennä rukoilemaan; ja menivät läpi leirin, ja kävivät ympäri sen laakson, että he olisivat salaisesti tulleet kaupungin portin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Ja Judit huusi vartioita: avatkaat portti; sillä Jumala on meidän kanssamme, joka on antanut Israelille voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Kuin vartiat kuulivat hänen äänensä, kutsuivat he kohta sinne kaupungin vanhimmat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Jotka kaikki tulivat hänen tykönsä; sillä he epäilivät jo, ettei hänen pitänyt palajaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Ja he virittivät tulisoittoja, ja kävivät häntä ympäri niinkauvan kuin hän lakialle tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Ja hän käski heidän olla vaiti ja kuulla, ja sanoi näin: kiittäkäät Herraa meidän Jumalaamme, joka ei niitä hylkää, jotka hänen päällensä uskovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Hän on osoittanut laupiuden minun, hänen piikansa kautta, niinkuin hän Israelin huoneelle on luvannut, ja on tänä yönä maahan lyönyt vihollisen minun kätteni kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Ja hän veti ulos säkistä Holoferneksen pään, osoitti heille sen, ja sanoi: katsokaat, tämä on Holoferneksen, Assyrialaisten sodanpäämiehen pää: ja katsokaat, ja katsokaat, tässä on vaate, jossa Herra meidän Jumalamme vaimon käden kautta on hänen surmannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Niin totta kuin Herra elää, niin on hän minua enkelinsä kautta varjellut, etten minä ole saastutetuksi tullut, niinkauvan kuin minä olen ulkona ollut; ja on antanut minun tänne ilman syntiä jälleen palata suurella voitolla ja ilolla. Sentähden kiittäkäät häntä kaikki; sillä hän on hyvä, ja auttaa aina. Ja he kaikki kiittivät Herraa, ja sanoivat hänelle: kiitetty olkoon Herra, joka tänäpänä on sinut kauttas saattanut meidän vihollisemme häpiään! Ja Otsia, Israelin kansan päämies sanoi hänelle: siunattu ole sinä tytär Herralta, kaikkein ylimmäiseltä Jumalalta, ylitse kaikkia vaimoja maan päällä. Ja kiitetty olkoon Herra, joka taivaan ja maan luonut on, joka sinulle onnen on antanut tappaa meidän vihollisemme päämiestä; Ja on tehnyt sinun nimes kuuluisaksi, ylistettää kaikilta, jotka Herran töitä tutkivat, ettei ole säästänyt henkeäs sinun kansas murheessa ja hädässä, mutta olet sen vapahtanut Herran meidän Jumalamme edessä. ja kaikki kansa sanoi: Amen, amen! Sitte toivat he Akiorin edes, jolle Judit sanoi: Israelin Jumala, jota sinä kunnioitit, että hän sinun vihollisilles kostaa taitaa, hän on tänä yönä jumalattoman pään särkenyt minun kätteni kautta. Ja että sinä sen näkisit, silla on tässä Holoferneksen pää, joka Israelin Jumalaa ylpeydessä häpäisi, ja sinua kuolemalla uhkasi, sanoen: kuin Israelin kansa käsitetään, niin tahdon minä myös sinun antaa pistää lävitse. 5:28 ja kuin Akior näki Holoferneksen pään, hämmästyi hän sangen suuresti. Mutta kuin hän jälleen toipui, lankesi hän hänen jalkainsa juureen, sanoi: Siunattu olet sinä sinun Jumalaltas kaikissa Jakobin majoissa; sillä Israelin Jumala tulee sinun kauttas ylistetyksi kaikkein kansain seassa, jotka sinusta kuulla saavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Sitte sanoi Judit kansalle: rakkaat veljet, kuulkaat minua, ripustakaat tämä pää ulos muurin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Ja niin pian kuin päivä tulee, niin ottakaat teidän sota-aseenne, ja karatkaat kaikki ulos yhdessä joukossa suurella huudolla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Niin vartiat pakenevat herättämään herransa sotimaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Ja kuin päämiehet tulevat Holoferneksen majaan ja saavat nähdä ruumiin makaavan veressänsä, niin he peljästyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Ja kuin te ymmärrätte, että he ovat epäilyksessä, ja pakenevat, niin seuratkaat vahvasti perässä; sillä Herra on antanut heitä teidän jalkainne alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Kuin Akior näki sen voiman, jonka Israelin Jumala tehnyt oli, hylkäsi hän pakanallisen menon, ja uskoi Jumalan päälle, ja antoi itsensä ympärileikata, ja tuli Israelin joukkoon luetuksi, hän ja kaikki hänen jälkeentulevaisensa, hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Ja kuin päivä koitti, ripustivat he Holoferneksen pään muurin päälle, ja ottivat kukin sota-aseensa ja karkasivat ulos yhdessä joukossa suurelle riekunalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Kuin vartiat sen näkivät, juoksivät he Holoferneksen majan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Ja ne, jotka siellä olivat, nostivat kapinan hänen majansa edessä, josta hänen piti heräämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Sillä ei he tohtineet kolkuttaa, eikä mennä sisälle Assyrian päämiehen majaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Mutta kuin ne muut Assyrian päämiehet tulivat, sanoivat he majan vartialle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Menkäät sisälle ja herättäkäät häntä, sillä hiiret ovat juosseet ulos lävistänsä, ja ovat niin rohkiaksi tulleet, että he uskaltavat meitä härsytellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Niin Bagoa meni sisälle, ja astui vaatteen tykö, ja kolkutti kädellänsä; sillä hän luuli hänen makaavan Juditin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Ja hän kuunteli, jos hän liikkuis; koska ei hän sitä kuullut, niin hän nosti vaatetta; ja kuin hän näki Holoferneksen ruumiin päätöinnä veressä makaavan maan päällä, huusi hän suurella äänellä, itki ja repäisi vaatteensa rikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Ja katsoi Juditin majaan, ja kuin ei hän löytänyt häntä, juoksi hän ulos sotaväen tykö ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Yksinäinen Hebrean vaimo on kuningas Nebukadnetsarin huoneen häväissyt, ja saattanut nauruksi koko maailman edessä; sillä Holofernes makaa siellä kuolleena maassa, ja hänen päänsä on häneltä hakattu pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Kuin Assyrian sodanpäämiehet sen kuulivat, repäisivät he rikki vaatteensa, ja hämmästyivät sangen suuresti; ja heidän seassansa oli sangen suuri huuto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Kun sotaväki sen kuuli, että Holoferneksen pää oli pois, hämmästyivät he, ja tyhmistyivät, ja ei tietäneet, mitä heidän piti tekemän, ja niin katosi heidän rohkeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Ja pakenivat, että he itsensä pelastaisivat Hebrealaisilta, jotka he näkivät tulevan vastaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Ja kuin Israelin lapset näkivät vihollisensa pakenevan, kiiruhtivat he heidän perässänsä suurella huudolla ja vaskitorvien soittamisella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Mutta että Assyrialaisten joukko hajoitettu oli, ja Israelin lapset heidän joukkoonsa tulivat, löivät he kaikki, jotka he käsittivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Ja Otsia, lähetti kaikkiin Israelin kaupunkeihin ja maakuntiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Että heidän piti valmiit oleman jokaisessa kaupungissa, vihollisia ajamaan takaa maakunnasta ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Mutta se väki, joka jäi Betuliaan, tuli Assyrian leiriin, ryöstivät ja veivät pois, mitä Assyrialaiset siihen jättäneet olivat, ja saivat siitä paljon kalua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Mutta kuin ne toiset palasivat Betuliaan, toivat he myötänsä kaikki, mitä ne olivat kanssansa vieneet eläimistä ja muista kaluista. Ja koko maakunta tuli rikkaaksi heidän saaliistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Sitte tuli Jojakim, ylimmäinen pappi, Jerusalemista Betuliaan, kaikkein pappein kanssa, katsomaan Juditia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Ja hän meni heidän tykönsa. niin kaikki ylistivät häntä ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Sinä olet Jerusalemin kruunu, Israelin ilo, sinä olet meidän kansan kunnia, joka niin jalon työn tehnyt olet, ja niin suuren hyvän työn Israelille osoittanut, että Jumala on taas heitä lunastanut. Siunattu olet sinä Jumalan edessä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Ja kaikki kansa sanoi: Amen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'ja kun he kolmekymmentä päivää saaliista jakaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Antoivat he Juditille kalliit kappaleet, jotka Holoferneksellä olivat, kullasta, hopiasta, vaatteista ja kalliista kivistä. Ja jokainen oli iloinen, veisasivat ja hyppäsivät, sekä nuoret että vanhat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Niin veisasi Judit Herralle tämän veisun, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Soittakaat Herralle kantelella, ja helistäkäät hänelle symbaleilla; veisatkaat hänelle uusi virsi; olkaat iloiset ja avuksenne huutakaat hänen nimeänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Herra on se, joka sodat asettaa taitaa, Herra on hänen nimensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Hän soti kansansa edestä, että hän meitä vapahtais kaikilta meidän vihollisiltamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Assur tuli siltä vuorelta pohjasta, suurella väellä; hänen paljoutensa peitti vedet, ja hänen hevosensa peittivät maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Hän uhkasi polttaa minun maani ja tappaa minun nuoret mieheni, lapset ja neitseet viedä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Mutta Herra kaikkivaltias Jumala on hänen rangaissut, ja antoi hänen vaimon käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Sillä ei yksikään mies eikä sankari ole häntä lyönyt maahan, ja ei yksikään uljas ole häneen ruvennut; mutta Judit Merarin tytär on kauneudellansa hänen lyönyt maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Sillä hän riisui pois lesken vaatteet, ja otti yllensä ilovaatteet, Israelin lasten iloksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Hän pesi itsensä kalliilla voiteella, palmikoitsi hiuksensa, pettämään häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Hänen kauniit kenkänsä tekivät hänen sokiaksi, hänen ihana muotonsa käänsi hänen sydämensä; mutta hän hakkasi miekalla pois hänen päänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Niin että Persialaiset ja Mediläiset hämmästyivät senkaltaista miehuullista työtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Ja Assyrialaisten sotajoukko murehti, kuin minun viheliäiseni tulivat edes, jotka janosta nääntyneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Nuoret poikaiset pistivät heitä lävitse, ja löivät heitä pakoon niinkuin lapsia. He ovat lyödyt maahan sodassa, Herran minun Jumalani sotajoukolta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Veisatkaamme uutta virttä Herralle, meidän Jumalallemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Herra Jumala, sinä olet voimallinen Jumala, joka teet suuria töitä, ja ei yksikään taida olla sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'kaikki luontokappaleet pitää sinua palveleman, ja mitä sinä sanot, sen pitää tapahtuman, Kuin sinä annat jollekulle rohkeuden, sen täytyy käytä edes, ja ei yksikään taida olla sinun sanaas vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Vuorten täytyy väristä, ja kivet sulavat sinun edessäs niinkuin meden vaha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Mutta jotka sinua pelkäävät, niille sinä tahdot osoittaa suuren armon; sillä kaikki uhri ja lihavuus on ylen huono sinun edessäs; mutta Herran pelko on sangen suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Voi pakanoita, jotka minun kansaani vainoovat! Sillä kaikkivaltias Herra kostaa heille, ja etsii heitä kostopäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 21, 'Hän on kostava heidän ruumiissansa tulella ja madoilla, ja heidän pitää palaman ja kituman ijankaikkisesti');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 22, 'Sen voiton jälkeen meni kaikki kansa Betuliasta Jerusalemiin rukoilemaan Herraa, ja puhdistivat itsensä, ja uhrasivat polttouhria, ja mitä he luvanneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 23, 'Ja Judit ripusti kaikki Holoferneksen sota-aseet templiin, ja sen vaatteen, jonka hän hänen vuoteestaan ottanut oli, että sen piti oleman annettu Herralle alttiiksi ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 24, 'Ja kansa oli iloinen Jerusalemissa, Juditin kanssa, pyhän tykönä, kolme kuukautta, ja pitivät juhlaa voitosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 25, 'Sitte meni kukin kotiansa jälleen. Ja Judit tuli myös kotiansa jälleen Betuliaan, ja tuli suuresti kunnioitetuksi koko Israelin maalla. Ja hän ei ottanut miestä ensimmäisen miehensä Manassen kuoleman jälkeen. Ja hän tuli sangen vanhaksi, ja oli miehensä huoneessa, siihenasti hän tuli sadan ja viiden ajastajan vanhaksi. Ja hän teki piikansa vapaaksi. Sitte kuoli hän Betuliassa, ja haudattiin miehensä Manassen viereen. Ja kansalla oli murhe ja valitus hänestä seitsemän päivää. Ja hän jakoi kaikki kalunsa miehensä Manassen lähimmäisille sukulaisille, niin myös omille lähimmäisille sukulaisillensa. Ja niin kauvan kuin hän eli, ja vielä kauvan sen jälkeen, ei kenkään rohjennut mennä Israelia vastaan. Ja he pitivät sen voittopäivän Hebrealaisten seassa suurena juhlana ja pyhänä ijankaikkisesti.');
