INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, '[]');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ja Mardokai sanoi: Jumala on sen kaiken toimittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'Minä muistelen untani, ja se on juuri niin tapahtunut kuin minä olen unta nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Vähä lähde, joka suureksi virraksi tuli, kuin aurinko paisti ja kirkkaaksi tuli, se on Ester, jonka kuningas puolisoksensa ottanut ja kuningattareksi tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'Kaksi lohikärmettä olen minä ja Haman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Toinen tietää pakanoita, jotka tulivat kokoon ja Juudalaisten nimeä hävittää tahtoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Toinen tietää minun kansaani Israelia, joka Herran tykö huusi, ja Herra autti kansaansa, ja vapahti meidät tästä hädästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'Hän teki suuria ihmeitä ja tunnustähtejä pakanain seassa; sillä hän on aina eroituksen pitänyt kansansa ja pakanain välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Ja kuin hetki tullut on, että pakanat ylpeimmällänsä ja me heikoimmallamme olleet olemme, ja että Jumala oli tuomitseva, niin hän on muistanut kansaansa, ja on perinnöllensä voiton antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Ja tämä päivä pitää pidettämän Adarin kuulla, neljäntenä ja viidentenätoistakymmenentenä päivänä sillä kuulla, kaikella ilolla ja suurella ahkeruudella, kuin kansa tulee kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Ja pitää niin ijankaikkisesti pidettämän Israelin kansassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Artakserkseen lähetyskirja Juudalaisten säästämisestä. Neljäntenä kuningas Ptolomeuksen ja Kleopatran vuotena toivat Dositeus (joka itsensä sanoi papiksi Levin suvusta) ja Ptolomeus, hänen poikansa, tämän kirjan Purimista ja sanoivat, että Lysimakus, Ptolomeuksen poika, oli sen kääntänyt Jerusalemissa: Toisena suuren kuninkaan Artakserkseen vuotena, ensimäisenä päivänä Nisanin kuuta');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Näki Mardokai unta, joka oli Juudalainen, Jairin poika, Semein pojan, Kisin pojan, Benjaminin suvusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Ja asui Susanin kaupungissa, kunniallinen mies, kuninkaan huoneessa suurena pidetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Mutta hän oli yksi niistä vangeista, jotka Nebukadnetsar, Babelin kuningas, oli Jerusalemista Jekonian, Juudan kuninkaan, kanssa vienyt pois. Ja tämä oli hänen unensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Kapina ja meteli, jylinä ja maanjäristys ja hämmästys nousi maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Ja katso, siellä oli kaksi suurta lohikäärmettä, jotka menivät sotimaan toinen toistansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Ja huuto oli niin suuri, että kaikki maakunnat nousivat sotimaan pyhää kansaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Ja se oli suuri pimiä päivä, murheellinen ja ahdistavainen, ja suuri surkeus ja hämmästys oli maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Ja pyhä kansa oli kovin murheellinen, ja pelkäsivät onnettomuuttansa, ja ei muuta heidän edessänsä ollut kuin kuolema, ja he huusivat Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Ja sen huudon jälkeen puhkesi suuri virta yhdestä vähästä lähteestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Ja aurinko nousi ja tuli kirkkaaksi, ja raadolliset voittivat ja tappoivat ne ylpiät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Kuin Mardokai heräsi unestansa, ajatteli hän, mitä Jumala sen kanssa aikoi, ja piti unen sydämessänsä, ja ajatteli sitä yöhön asti, ja olis mielellänsä tahtonut tietää, mitä se aavisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Artakserkseen lähetyskirja Juudalaisten surmaamisesta. Mutta kirja oli näin: Suuri kuningas Artakserkses Indiasta Etiopiaan asti tervehtii sataa ja seitsemää kolmattakymmentä päämiestä, ynnä alamaisten kanssa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Vaikka minä voimallinen kuningas olen ja suurin herra maan päällä, niin en minä ole kuitenkaan voimastani tahtonut ylpiäksi tulla, vaan ahkeroinut armollisesti ja siviästi hallita, ja rauhan, josta jokainen iloitsee, voimassansa pitää, että jokainen rauhallisesti eläis ja asiansa toimittais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Pidin sentähden päämiesteni kanssa neuvoa, kuinka se parhain tapahtuis. Niin ilmoitti minulle Haman, toimellisin, rakkain ja uskollisin neuvonantajani, joka kuninkaan jälkeen on ylimmäinen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Kuinka yksi kansa on, joka kaikkiin maakuntiin hajoitetun on, joilla erinomainen laki on vastoin kaikkein maakuntain ja kansain tapaa, ja katsoo joka paikassa kuninkaan käskyn ylön, jonka kautta he rauhan ja yksimielisyyden valtakunnassa estävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Koska me siis ymmärsimme, että yksi ainoa kansa koko maailmaa vastaan itsensä asettaa, ja oman tapansa pitää, ja ne meidän käskyillemme ovat tottelemattomat, jonka kautta he suuren vahingon tekevät, ja rauhan ja yksimielisyyden valtakunnassamme turmelevat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Käskimme me, että kaikki ne, jotka Haman, ylimmäinen päämies ja ylimmäinen kuninkaan jälkeen, meidän isämme, tietää antava on, pitää vihollistensa miekoilla vaimoinensa ja lapsinensa, ilman yhtäkään armoa surmattaman, eikä ketään armahdettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Ja neljäntenätoistakymmenentenä päivänä Adarista, toisesta kuukaudesta toistakymmentä, tänä vuotena, pitää kaikki ne tottelemattomat yhtenä päivänä tapettaman, että vahva rauha pysyis valtakunnassamme. Tämä kappale luettakaan neljännen luvun jälkeen, ennen kuin viides aljetaan: Mardokain rukous Jumalan tykö Juudalaisten säästämisestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Ja Mardokai rukoili Herraa, ja luetteli hänen ihmeellisiä töitänsä ja sanoi: Herra Jumala, sinä olet kaikkivaltias kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Kaikki ovat sinun hallussas, ja ei sinun tahtoas vastaan voi kenkään olla, kuin sinä Israelia auttaa tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Sinä olet taivaan ja maan tehnyt, ja kaikki, mitä niissä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Sinä olet kaikkein Herra, ja ei kenkään voi olla sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Sinä tiedät kaikki: sinä olet nähnyt, etten minä ylpeydestä eli ylönkatseesta ylpiää Hamania ole palvella tahtonut; Sillä minä olisin valmis lsraelin hyväksi mielelläni hänen jalkainsakin suuta antamaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Vaan olen tehnyt pelvosta, etten minä sitä kunniaa, joka minun Jumalalleni tulee, antaisi ihmisille, enkä ketään muuta kumartaisi kuin minun Jumalaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Ja nyt Herra, sinä Kuningas ja Abrahamin Jumala, armahda sinun kansas päälle! sillä meidän vihollisemme tahtovat meitä hävittää, ja sinun perikuntas, joka sinun alusta on ollut, hukuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Älä katso ylön sinun joukkoas, jonkas Egyptistä pelastanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Kuule minun rukoukseni, ja ole kansalles armollinen, ja käännä meidän murheemme iloksi, että me eläisimme ja sinun nimeäs ylistäisimme, ja älä anna niiden suuta tukittaa, jotka sinua kiittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Ja koko Israel huusi kaikesta voimastansa Herran tykö; sillä he olivat kuoleman hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Ja kuningatar Ester käänsi myös itsensä Herran tykö senkaltaisessa kuoleman hädässä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Ja riisui kuninkaalliset vaatteet, ja puki itsensä murhevaatteisiin, ja kalliin veden ja balsamin edestä hajoitti hän tuhkaa ja tomua päänsä päälle, ja nöyryytti ruumiinsa paastolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Ja joka paikassa, kussa hän ennen iloinen oli ollut, repi hän hiuksiansa, ja rukoili Israelin Jumalaa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Herra, joka meidän ainoa Kuninkaamme olet, auta minua viheliäistä, ei minulla ole muuta auttajaa kuin sinä yksinäs, ja hätä on käsissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Minä olen minun isältäni kuullut, Herra, ettäs Israelin kaikista pakanoista eroittanut, ja meidän isämme vanhasta ijankaikkiseksi perinnöksi omistanut olet, ja pitänyt, mitäs heille puhunutkin olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Me olemme sinun edessäs syntiä tehneet; sentähden olet sinä meitä antanut meidän vihollistemme käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Herra, sinä olet vanhurskas; sillä me olemme heidän jumaliansa palvelleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Mutta ei he nyt siihen tyydy, että he suuresti meitä vaivaavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Vaan voittonsa he lukevat jumalainsa voimaksi, ja tahtovat sinun lupaukses tyhjäksi tehdä, ja sinun perintös hävittää, ja niiden suut, jotka sinua kiittävät, tukkia, ja sinun templis ja alttaris kunnian hävittää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Ja pakanain suut avata ylistämään jumaliansa, Ja kuolevaista kuningasta ijankaikkisesti ylistämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Herra, älä anna valtikkaas niille, jotka ei mitään ole, ettei he meidän vaivaisuuttamme nauraisi, vaan käännä heidän aivoituksensa itse päällensä, ja muista sitä, joka sen meitä vastaan matkaan saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Muista meitä, Herra, ja ilmoita itses meidän tuskassamme, ja vahvista minua, Herra, sinä kaikkein jumalain ja sotajoukkoin Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Opeta minua, kuinka minun jalopeuran edessä pitää puhuman, ja käännä hänen sydämensä, että hän meidän vihollistamme rupeais vihaamaan, niin että hän itse joukkoinensa hukkuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Ja holhoo meitä kädelläs, ja auta minua, sinun piikaas, jolla ei muuta apua ole kuin sinä, Herra, ainoasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Sinä, joka kaikki asiat tiedät ja tunnet, ettei minulla ole iloa siitä kunniasta, joka minulla jumalattomain tykönä olla taitaa, eikä mielisuosiota pakanalliseen ja muukalaiseen naimiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Sinä tiedät, että minun se tehdä täytyi, ja en lue miksikään sitä kunniallista kaunistusta, jota minä pääni päällä kannan, kuin minun koreileman pitää, vaan pidän sen niinkuin saastaisen rääpäleen, ja en sitä kanna muulloin, vaan silloin kuin minun koreileman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Ja en minä ole koskaan Hamanin kanssa syönyt, enkä iloissani ollut kuninkaan pöydällä, en myös ole juonut uhrien viinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Ja sinun piikas ei ole koskaan iloissansa ollut, sittenkuin; minä tänne tulin tähänasti, vaan ainoasti sinussa, Herra, Abrahamin Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Kuule hyljättyin ääni, sinä väkevä Jumala ylitse kaikkein, ja pelasta meitä jumalattoman käsistä, ja vapahda minua minun tuskistani! Tämä olkoon viidennen luvun alun selitys: Ester löytää armon kuninkaan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, '[]');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Ja kolmantena päivänä riisui hän jokapäiväiset vaatteensa, ja puki itsensä kuninkaalliseen kaunistukseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Ja oli sangen ihana, ja huusi Jumalan ja Vapahtajan tykö, joka kaikki näkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Ja otti myötänsä kaksi piikaa ja nojasi itse toisen päälle hiljaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Mutta toinen seurasi häntä ja kantoi hänen hameensa lievettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ja hänen kasvonsa olivat sangen kauniit, ihanat ja ilon muotoiset, vaan hänen sydämensä oli täynnä ahdistusta ja murhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Ja kuin hän kaikista ovista sisälle tuli, meni hän kuninkaan kohdalle, kussa hän istui kuninkaallisella istuimellansa, kuninkaallisissa vaatteissansa, jotka kullasta ja kalliista kivistä olivat, ja oli sangen peljättävä nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Kuin hän nyt silmänsä nosti ja katsoi vihaisesti hänen päällensä, niin kuningatar pyörtyi, ja raukesi voimattomuudesta, ja laski päänsä piian päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Niin Jumala käänsi kuninkaan sydämen hyvyyteen, ja hän hämmästyi hänen tähtensä, hyppäsi istuimeltansa ja sai hänen syliinsä, siihen asti että hän tointui, ja sanoi ystävällisesti hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Mikä sinun on, Ester?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Minä olen sinun veljes, älä pelkää; ei sinun pidä kuoleman; sillä ei se käsky tule sinuun, vaan kaikkiin muihin; tule edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Ja hän ojensi kultaisen valtikan, ja laski hänen olallensa, ja antoi hänen suuta, ja sanoi: sano, mitäs tahdot?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Ja hän vastasi: kuin minä katsoin sinun päälles, luulin minä näkeväni Jumalan enkelin; sentähden minä hämmästyin sinun suuren majesteettis tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Sillä sinä olet sangen peljättävä, ja sinun muotos on suurta kunniaa täynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Mutta kuningas hämmästyi palvelioinensa, ja lohduttivat häntä. Artakserkses, suuri kuningas Indiasta Etiopiaan asti, tervehtii niitä sataa seitsemääkolmattakymmentä päämiestä, ynnä alamaisten kanssa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Me ymmärrämme, että moni on päämiesten ystävyydestä ja kunniasta, joka heille tapahtuu, ylpiäksi ja ilkiäksi tullut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Niin ettei he ainoastaan sorra alamaisia, vaan aikovat myös itse herrat, joilta he ylennetyt ovat, jalkainsa alle polkea,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Ja ei tee ainoasti luonnollista kohtuullisuutta vastaan, kiittämättömyyden kautta; vaan ovat ylpeydellä soaistut, niin ettei he luule Jumalan (joka hurskaita holhoo) senkaltaista petosta rankaisevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'He pettävät myös hyvät ruhtinaat, viatointa verta vuodattaissansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Ja ne, jotka heitä uskollisesti ja toimellisesti palvelevat, saattavat he kaikkinaiseen onnettomuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Joka löydetään ei ainoasti vanhoista historioista, mutta myös vielä joka päivä nähdään, kuinka paljon senkaltaiset neuvonantajat pahuutta matkaan saattavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Että meidän siis pitää ottaman vaarin, että rauha tästedes pysyis valtakunnassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Täytyy meidän, asian tilan jälkeen, toisinansa käskyt muuttaa, koska me toisin löydämme, kuin me olemme ennen neuvotut, ja ei äkisti mitään päättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Että nyt Haman, Hamadatin poika, Makedoniasta, ei Persian verestä eikä meidän hyvästä luonnostamme ole, vaan meidän tykönämme on muukalainen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Jolle me (niinkuin myös joka maakunnallekin) kaikkea armoa näyttäneet ja hänen niin korottaneet olemme, että me kutsuimme hänen meidän isäksemme, ja jokaiselta, niinkuin lähimmäinen kuninkaasta, kunnioitettiin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'On niin ylpiäksi tullut, että hän on aikonut saattaa meitä pois valtakunnastamme ja hengeltämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Sillä hän on Mardokain (joka uskollisuutensa ja hyvän työnsä kautta meidän henkemme on pelastanut) ja viattoman puolisomme Esterin ja kaiken hänen kansansa päälle väärin ja petollisesti kantanut, että he kaikki surmattaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Ja niin, kuin ne olisivat poissa, jotka meitä varjelevat, on hän aikonut surmata meitä, ja Persian valtakunnan Makedonialaisille saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Mutta me ymmärrämme, että Juudalaiset, jotka se ilkiä ajellus tahtoi kuolettaa, ovat viattomat, joilla hyvä laki on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Ja sen korkeimman, suurimman ja ijankaikkisen Jumalan lapset ovat, joka meidän isillemme ja meille tämän valtakunnan antanut on, ja vieläkin pitää ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Sentähden ei teidän pidä totteleman sitä kirjaa, jonka Haman matkaan saanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Sillä sen työn tähden on hän kaiken sukunsa kanssa Susanin portin eteen hirtetty, ja Jumala on hänelle kohta maksanut, niinkuin hän ansainnutkin oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Vaan tämän käskyn, jonka me nyt teille lähetämme, pitää teidän joka kaupungissa ilmoittaman, että Juudalaiset lakinsa vapaana pitäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Ja jos joku tahtoo heille väkivaltaa tehdä kolmantenatoistakymmenentenä päivänä, toisella kuukaudella toistakymmentä, joka on Adar, niin teidän pitää varjeleman heitä, että he niille kostaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Sillä sen päivän on kaikkivaltias Jumala heille iloksi tehnyt, jona valittu kansa hukkuman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Sentähden pitää myös teidän, muiden juhlain kanssa, tämän kaikella ilolla juhlana pitämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Että meille menestyis ja kaikille, jotka Persialaisille uskolliset ovat, ja niin olis opiksi, kuinka petos rangaistaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Mutta kuka maakunta eli kaupunki tätä käskyä ei pidä, hän pitää miekalla ja tulella hävitettämän, niin ettei siinä ihminen eikä eläin eli lintukaan enää asua taida. Tämä kappale luettakoon alussa eli lopussa; sillä uni on nähty ennenkuin nämät tapahtuivat, ja selitys sitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Rakastakaat oikeutta, te jotka maata hallitsette: ajatelkaa Herraa hyvyydessä,ja etsikäät häntä sydämen yksinkertaisuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Sillä hän antaa löytää itsensä niiltä, jotka ei häntä koettele ja ilmoittaa itsensä niille, jotka ei epäile hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Vaan väärät ajatukset eroittavat Jumalasta, mutta koeteltu voima rankaisee tyhmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'Sillä ei viisaus tule häijyyn sieluun, ja ei asu siinä ruumiissa, joka synnin alle annettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Sillä Pyhä Henki, joka oikein opettaa, pakenee epäjumalan palvelioita, ja lähtee pois vääräin tyköä, jotka synnillä rangaistaan, johon he joutuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Sillä viisaus on niin hyvä, ettei se anna laittajan rankaisematta olla; sillä Jumala on hänen ajatustensa todistaja, ja tuntee totisesti kaikki hänen sydämensä ja kuulee kaikki sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Sillä maan piiri on täynnä Herran henkeä, joka puheet tuntee, on joka paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Sentähden ei taida se salattu olla, joka häntä rankaiseman pitää, ei pidä ohitse menemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Sillä jumalattoman aivoitus pitää tuomiolle tuleman, ja hänen puheensa, Herran eteen, että hänen pahuutensa rangaistaisiin');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Sillä kiivas korva kuulee kaikki ja laittajan häväistys ei ole salassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Niin ottakaat nyt vaari, ettette häpäise, ja pitäkään kielenne pois parjauksesta; sillä mitä te salaisesti puhutte, ei pidä turhaan menemän; sillä se suu, joka valhettelee, tappaa sielun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Älkäät niin pyytäkö kuolemaa teidän erhetyksillänne, ja älkäät etsikö kadotusta kättenne töillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Sillä ei Jumala ole tehnyt kuolemaa, ja ei hänelle kelpaa eläväin kadotus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Mutta hän on kaikki luonut, että ne olemisessansa oleman pitäis, ja mitä maailmassa luotu on, se on hyvä, ja ei siinä ole mitäkään vahingollista, ei myös helvetin valtakunta maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Mutta vanhurskas on kuolematoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Vaan jumalattomat pyytävät kuolemaa sekä sanalla että työllä; sillä he pitävät hänen ystävänsä, menevät pois, ja yhdistävät itsensä hänen kanssansa; sillä he ovat myös sen ansainneet§ että he ovat hänen omansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Sillä he ovat jumalattomat, ja sanovat: meidän elämämme on lyhykäinen ja vaivaloinen; ja kuin ihminen on kuollut, niin on hän peräti loppunut §, ja ei ole ketään tunnettu, joka on helvetistä palannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Me olemme siis tapaturmaisesti syntyneet, ja menemme pois niinkin emme ikänä olleetkaan olis; sillä hengen vetämys on savu, ja meidän puheemme on kipinä, joka meidän sydämestämme käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Kun se sammutettu on, niin on meidän ruumiinne pois niinkuin nöhtä, ja meidän henkemme katoo niinkuin löyhkä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Ja meidän nimemme tulee ajan jälkeen unhotetuksi, ja ei yksikään ajattele, mitä me tehneet olemme; meidän elämämme menee niinkuin pilvi, ja katoo niinkuin sumu, joka auringon paisteelta ajetaan pois, ja hänen palavuudellansa hajoitetut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Meidän aikamme on niinkuin varjo, ja kuin me tulemme pois, niin ei tulla jälleen; sillä on niin päätetty§, ettei yksikään pidä tuleman jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Niin tulkaa siis, ja eläkäämme hyvästi, niin kauvan kuin me taidamme ja nautitkaamme elämäämme niin kauvan kuin me nuoret olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Me tahdomme täyttää meitämme parhaalla viinalla ja voiteella, älkäämme unhoittako kevätkukkasia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Kantakaamme seppeleitä nuotista kukkasista, ennenkuin ne lakastuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Älköön yksikään olko osatoin meidän röyhkeydestämme, että joka paikassa kuulla saatasiin, kuinka me olemme iloiset olleet; sillä ei tämä tästä muuta ole kuin tämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Ahdistakaamme köyhää vanhurskasta ja älkäämme säästäkö leskiä eli ijällistä miestä, älkäämme lukua pitäkö vanhain harmaapäiden nuhtelemisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Kaikki, mitä me tehdä taidamme, pitää oikein oleman; silla joka ei taida tehdä, mitä hänen mielessänsä on, ei hän mitään maksa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Väijykäämme vanhurskasta, sillä hän tekee meille paljon vaivaa, ja asettaa itsensä meidän töitämme vastaan, ja nuhtelee meitä, että me syntiä teimme lakia vastaan, ja soimaa meidän menomme synniksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Hän sanoo tuntevansa Jumalan, ja kehuu, että hän on Jumalan poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Ja nuhtelee, mitä meidän sydämessämme on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Työläästi me voimme hänen nähdä; silla ei hänen elämänsä sovi muiden kanssa, ja hänen menonsa on peräti vastahakoinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Hän pitää meitä tyhminä, ja välttää teitämme niinkuin saastasuutta, ja sanoo vanhurskaille viimein hyvin käyvän, ja kehuu, että Jumala on hänen isänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Niin katsokaamme siis, jos hänen sanansa ovat todet, ja koetelkaamme, mikä loppu hänellä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Jos hän on totinen Jumalan poika, niin hän häntä auttaa, ja vapahtaa hänen vainomiesten käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Häpiällä ja pilkalla me kidutamme häntä, että me näkisimme, kuinka jumalinen hän on ja ymmärtäisimme, kuinka kärsivällinen hän on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Me tahdomme häntä tuomita häpiälliseen kuolemaan; silloinhan tunnetaan sanoistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Senkaltaista he aikovat ja menevät väärin; heidän pahuutensa on heidät sokiaksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Ja ei he tunne Jumalan salaisia neuvoja, eikä ole toivoneet, että pyhä elämä pitää palkan saaman, ja katsovat ylön sen kunnian, jonka pyhäin sielut saaman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Sillä Jumala on luonut ihmisen ijankaikkiseen elämään; ja on hänen luonut kaltaiseksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Mutta perkeleen kateudesta on kuolema maailmaan tullut, ja ne, jotka hänen puoltansa pitävät, auttavat myös itsensä siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Mutta vanhurskasten sielut ovat Jumalan kädessä, ja ei kuoleman vaiva lähesty heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Taitamattomain mielestä näkyvät he kuolevan, jä heidän lähdentönsä luetaan kivuksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Ja heidän loppunsa kadotukseksi; mutta he ovat rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Jos he vielä ihmisten silmäin edessä paljon kärsivät, niin on heillä kuitenkin vahva toivo, ettei heidän ikänä kuoleman pidä§.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'He tulevat vähä vaivatuksi, mutta heille pitää paljo hyvää tapahtuman; sillä Jumala koettelee heitä§, ja löytää heidät mahdolliseksi itsellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Hän koettelee heitä niinkuin kulta ahjossa, ja ottaa heitä vastaan niinkuin täydellisen uhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ja siihen aikaan kuin Jumala katsoo sitä, niin he kirkkaasti paistavat, ja menevät niinkuin kipinät orsissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Heidän pitää tuomitseman pakanoita, ja hallitseman kansoja; ja Herra hallitsee heitä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Sillä jotka häneen turvaavat, ymmärtävät totuuden, ja jotka lujat ovat rakkaudessa, ei pidä hänestä luovutettaman. Sillä hänen pyhänsä ovat armossa ja laupiudessa, ja hän katsoo valituitansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Mutta jumalattomat rangaistaan niinkuin he pelkäsivätkin; silla ei he vanhurskaasta lukua pitäneet, ja luopuivat Herrasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Sillä joka viisauden ja kurituksen katsoo ylön, se on onneton, ja heidän toivonsa on tyhjä, heidän työnsä turha, ja heidän tekonsa hedelmätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Heidän vaimonsa ovat hullut, ja heidän lapsensa pahanilkiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Kirottu on kaikki, mikä heistä on syntynyt; sillä autuas on hedelmätöin, joka on saastuttamatoin, ja ei ole ryhtynyt syntisen vuoteeseen, se hänelle silloin hyväksi tulee, kuin sielut etsitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Niin myös hedelmätöin, joka ei vääryyttä tee kädellänsä, eikä mitään pahaa ajattele Herraa vastaan; hänelle annetaan uskonsa edestä erinomainen lahja, ja parempi osa Herran templissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Sillä hyvä työ antaa hyvän palkan, ja ymmärryksen juuri ei häviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Mutta äpärät ei pidä menestymän, ja salavuoteisen siemenen pitää hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Ja jos he vielä kauvan elävät, niin täytyy heidän kuitenkin viimein häpiään tulla, ja heidän ikänsä pitää kuitenkin lopulla ilman kunniaa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Jos he varhain kuolevat, niin ei heillä ole toivoa, eli lohdutusta tuomiopäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Sillä jumalattomat saavat pahan lopun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Parempi on lapsetonna olla puhtaudessa; sillä sille on loppumaton ylistys, ja siitä Jumala ja ihmiset paljon pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, 'Kussa se on, sitä seurataan, kussa ei se ole, niin sitä kaivataan; ja siitä koreillaan ijankaikkisella kaunistuksella ja saadaan voitto puhtauden kilvoittelemisella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Mutta jumalattomain suuri hedelmällinen joukko on kelvotoin,ja mitä huoruudessa istutetaan, ei se syvältä juurru, eikä vahvasti perusteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Jos he hetken aikaa oksissa vihoittavat, niin he liikutetaan tuulelta; ja että he ovat valtoimet, niin he tulevat myrskyltä hävitetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Hyötyvesat murtuvat, ja heidän hedelmänsä on kelvotoin, jäävät röhkäleeksi ja ei kelpaa syödä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Sillä ne lapset, jotka ei aviovuoteesta synnytetä, tunnustavat vanhempainsa pahuuden, kuin heiltä kysytään. 3: 16.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Mutta jos vanhurskas varhain kuolee, hän hän on kuitenkin levossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Sillä ei ikä siitä kunniallinen ole, että hän kauvan elää, ja hänellä on monta vuotta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Vaan toimi ihmisten seassa ovat oikiat harmaat karvat, ja virheetöin elämä on oikia vanha ikä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Sillä hän kelpasi Jumalalle ja on hänelle rakas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Hän on oteltu pois elämästä syntisten seasta, ja on temmattu pois, ettei pahuus hänen ymmärrystänsä kääntäisi, eli väärä oppi hänen sieluansa viettelisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Sillä paha tapa turmelee hyvät, ja paha himo kääntää viattoman sydämen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Hän on nopiasti täydelliseksi tullut, ja on täyttänyt monta vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Sillä hänen sielunsa kelpasi Jumalalle: sen tähden kiiruhti hän hänen pois tästä pahasta elämästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Mutta ihmiset, jotka sen näkevät, ei siitä lukua pidä, eikä sitä sydämeensä pane, että Jumalan pyhät armossa ja laupiudessa ovat, ja että hän katsoo valittujensa puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Sillä kuollut vanhurskas tuomitsee eläviä jumalattomia, ja nuori, joka pian täydelliseksi tullut on, tuomitsee vääräin pitkän elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'He näkevät kyllä viisaan lopun, mutta ei he tiedä, mitä Herra hänestä ajattelee, ja minkätähden hän häntä varjelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'He kyllä sen näkevät, ja ei pidä lukua: mutta Herra nauraa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Ja heidän pitää sentähden häpiällä lankeeman, ja oleman häväistys kuolleiden seassa ijankaikkisesti; ja hän kukistaa heitä maahan tapaturmaisesti, ja repii heitä pois perustukseen asti, että he peräti hävitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Heidän pitää oleman ahdistuksessa, ja heidän muistonsa pitää hukkuman, mutta heidän pitää tuleman epäileväiseksi syntinsä tunnustuksessa, ja heidän syntinsä pitää heitä nuhteleman vastoin heidän silmiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Silloin vanhurskas seisoo suurella rohkeudella niitä vastaan, jotka häntä ahdistaneet ja hänen työnsä hyljänneet ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Koska he sen näkevät, niin he hämmästyvät sangen hirmuisesti, ja tyhmistyvät sitä autuutta. jota ei he toivoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'Puhuvat toinen toisellensa, ja katuvat, ja huokaavat henkensä ahdistuksesta, ja sanovat: tämä on se, jonka me ennen pidimme nauruna ja pilkka-sananlaskuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Me hullut pidimme hänen elämänsä tyhmänä ja hänen loppunsa häpiänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Kuinka hän nyt on luettu Jumalan lasten sekaan, ja hänen perintönsä pyhäin sekaan\'?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Sen tähden olemme eksyneet oikialta tieltä, ja vanhurskauden kynttilä ei ole meitä valistanut, eikä vanhurskauden aurinko meille koittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Me olemme kaikki käyneet vääriä ja vahingollisia teitä, ja olemme vaeltaneet harhoja retkiä; mutta Herran teitä emme ole tietäneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Mitä autti meitä koreutemme? mitä hyödytti meitä rikkaus ja ylpeys?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Kaikki ovat menneet ohitse niinkuin varjo, ja niinkuin sanansaattaja, joka juosten menee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Niinkuin laiva, joka aalloissa juoksee, jonka jälkeä ja vanaa, sittekuin se on mennyt ohitse, ei löydetä aalloissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Eli niinkuin lintu, joka tuulessa lentää, jonka rataa ei enään löydetä, sillä hän laukuilee ja pieksää tuulta, ajaa ja eroittaa sitä liehuvaisilla siivillänsä, ja sitte ei löydetä merkkiä senkaltaisesta lennosta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Eli niinkuin nuoli, joka jotakuta kohden lasketaan, hajoittaa tuulen, joka kohta kokoontuu jälleen, ettei tuta taideta, kusta se mennyt on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Niin myös me, kohta kuin me syntyneet olimme, saimme lopun, ja emme mitään hyvää työtä ole tehneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Vaan me olemme kulutetut meidän pahuudessamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Sillä jumalattoman toivo on kuin tomut tuulelta hajoitettu, ja niinkuin vetelä vaahto, joka myrskyltä on ajettu, ja niinkuin savu, joka tuulelta on puhallettu pois, ja niinkuin se kohta unhotetaan, joka ainoastaan päivän vieraana on ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Mutta vanhurskaat elävät ijankaikkisesti, ja Herrassa on heidän palkkansa, ja kaikkein Korkein pitää heistä murheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Sentähden saavat he Kunniallisen valtakunnan ja kauniin kruunun Herran kädestä; sillä hän varjelee heitä oikialla kädellänsä, ja suojelee heitä käsivarrellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Hän ottaa kiivautensa haarniskaksi, ja varustaa luontokappaleen vihollisten kostoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Hän pukee päällensä vanhurskauden pantsariksi, ja panee ankaran tuomion kilveksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Hän ottaa oikeuden voittamattomaksi turvaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Hän teroittaa julman vihansa miekaksi, maailman pitää menemän sotaan hänen kanssansa taitamattomia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Pitkäisen tulen ampuma pitää osaaman oikein, ja pitää pilvistä tuleman, niinkuin kovan jännitetyn joutsen jotakuta kohden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Ja taajat rakeet, jylinän sateen vihasta lankeeman, niin pitää myös meren vedet julmistuman heidän päällensä. Ja virrat pitää suuresti kuohuman. Ja suuren myrskyn pitää puhaltaman heitä vastaan, ja lennättämän heitä niinkuin tuulispään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Vääryys kaikki maakunnat hävittää, ja paha elämä kukistaa voimallisten istuimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Niin kuulkaat, te kuninkaat, ja ottakaat vaari: oppikaat, te tuomarit maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Ottakaat korviinne te, jotka monta hallitsette, te jotka korotatte teitänne kansain päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Sillä teille on annettu valta Herralta, ja voima kaikkein Korkeimmalta, joka tahtoo kysyä, kuinka te hallitsette, ja koetella kuinka te asetatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Te olette hänen valtakuntansa virkamiehet, mutta ette tee oikein teidän virkanne töitä, ja ette pidä oikeutta, ette myöskään vaella Herran tahdon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Hän tulee hirmuisesti ja äkisti teidän päällenne; ja esivallan pitää kovan tuomion saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Sillä huonoille tapahtuu armo, vaan voimalliset voimallisesti rangaistaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Sillä, joka kaikkein päälle Herra on, ei hän pelkää ketään, eikä karta kenenkään voimaa; hän on tehnyt sekä pienet että suuret, ja hänellä on yhtäläinen suru kaikista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Mutta voimallisesta pitää kova tuomio pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Teille tyranneille minä puhun, että oppisitte viisautta, ja ette vilpistelisi');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Sillä joka pyhän opin pyhänä pitää, hän pidetään pyhänä; ja joka hänen hyvin oppii, hän on kyllä pysyväinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Niin antakaat minun puheeni teille kelvata, pyytäkäät sitä, ja antakaat opettaa teitänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Sillä viisaus on ihana ja katoomatoin, ja osoittaa mieluisesti itsensä niille, jotka häntä rakastavat, ja antaa itsensä niiltä löyttää, jotka häntä etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Hän kohtaa ja ilmoittaa itsensä niille, jotka häntä mielellänsä pyytävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Joka varhain nousee häntä varten, ei se näe paljon vaivaa; hän löytää hänen oven edestä vartioitsemasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Sillä häntä pyytää, on täydellinen taito; ja joka hänen tähtensä valvoo, ei se kärsi pitkällistä murhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Sillä hän käy ympäri, ja etsii sitä, joka hänelle on mahdollinen, ja näyttää itsensä mielellänsä tiellä, vartioiden häntä, että hän hänen kohtais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Sillä joka itsensä antaa mielellänsä opetettaa, siinä on viisauden alku; ja joka häntä tottelee, se antaa itsensä mielellänsä opetettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Joka itsensä antaa mielellänsä opetettaa, se pitää hänen käskynsä; mutta kussa käskyt pidetään, siinä on totisesti pyhä elämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Mutta joka pyhää elämää pitää, se lähestyy Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Joka viisautta rakastaa, sen Hän tekee herraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Jos te tyrannit tahdotte kansan kuninkaat ja ruhtinaat olla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Niin pitäkäät viisaus silmäinne edessä, että te ijankaikkisesti hallitsisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Mutta mikä viisaus on, ja kusta se tulee, tahdon minä teille ilmoittaa, ja en tahdo salata teiltä salautta; mutta tahdon tutkistella luotuin alusta ja julkisesti hänen tuoda edes, ja en totuutta säästää');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Ei minun ole mitään tekemistä myrkyllisen kateuden kanssa; sillä ei sen kaltaisella ole osaa viisaudessa. Mutta kussa monta viisasta on, siellä hyvin on maailmassa, ja toimellinen kuningas on kansan turva. Sentähden antakaat itsenne opetettaa minun sanoillani, ja sen pitää tuleman teidän hyväksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Minä myös olen kuolevainen ihminen niinkuin muutkin, syntynyt sen ihmisen suvusta, joka ensisti luotiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Ja olen äidin kohdussa tehty lihaksi, kymmenessä kuukaudessa veressä juossut kokoon miehen siemenestä, himossa sekoitettu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Ja olen myös, kuin minä synnyin, hengen vedon saanut yhteisestä tuulesta, ja olen pudonnut maan päälle, joka meitä kaikkia kantaa; ja on myös minunkin ensimäinen ääneni ollut itku, niinkuin kaikkein muidenkin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Ja olen kasvatettu kapaloissa murheen pidolla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Sillä ei kuninkaallakaan ole muuta alkua syntymiseensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Vaan kaikilla on yhtäläinen tulemus elämään ja yhtäläinen lähdentö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Sentähden minä rukoilin, ja minulle annettiin ymmärrys; minä huusin, ja viisauden henki tuli minuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Minä pidin hänestä enempi kuin kuninkaan valtakunnasta ja istuimesta, ja rikkauden minä pidin tyhjänä hänen suhteensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'En minä pitänyt kallista kiveä hänen vertanansa; sillä kaikki kulta on hänen suhteensa niinkuin huono hieta, ja hopia on niinkuin loka hänen ehtoonsa arvattava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Minä rakastin häntä enemmän kuin terveyttä ja kauneutta, ja valitsin hänen minulleni valkeudeksi; sillä se paiste, joka hänestä tulee, ei sammu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Mutta kaikki hyvyys on minulle tullut hänestä, ja lukematoin rikkaus on hänen kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Minä olin iloinen kaikissa, että viisaus kävi minun edessäni kaikissa niissä; mutta en minä tietänyt, että senkaltaiset tulivat hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Yksivakaisesti olen minä sen oppinut, hyvällä mielellä minä häntä jaan: hänen rikkauttansa en minä salaa; sillä hän on ihmisille ääretöin tavara.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Jotka häntä pitävät, tulevat Jumalan ystäviksi, ja ovat otolliset, että heille on annettu sallia itsensä opettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Jumala on antanut minun viisaasti puhua, ja senkaltaisen viisauden lahjaa oikein ajatella; sillä hän johdattaa viisauden tielle ja hallitsee viisaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Sillä hänen kädessänsä me olemme sekä myös meidän puheemme, niin myös kaikki toimi ja taito kaikissa asioissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Sillä hän on antanut minulle vahvan tiedon kaikissa asioissa, ettii minä tiedän, kuinka maailma on tehty, ja elementteinkin voiman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Ajan alun, lopun ja välin, kuinka päivä pitenee ja lyhenee, kuinka vuoden ajat muuttuvat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Ja kuinka ajastaika kuluu, kuinka tähdet asetetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Eläinten luonnon ja metsän petoin vihan, tuulten voiman, ja mitä ihmisten mielessä on, moninaisten ruohoin luonnon, ja juurten väen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Minä tiedän kaikki, mitä salattu ja julki on; sillä viisaus, joka kaiken taidon opettaa, on minulle sen opettanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Sillä hänessä on ymmärtäväinen henki, pyhä, ainoa, moninainen, terävä, nopsa, vakaa, puhdas, kirkas, hiljainen, ystävällinen, tarkka, vapaa, hyväntahtoinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Suloinen, luja, vahva, surutoin, kaikkivoipa, kaikkinäkevä, joka käy kaikkein henkein lävitse, ehkä kuinka toimelliset, kirkkaat ja terävät ne olisivatkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Sillä viisaus on kaikkein selvin: hän menee ja käy kaikkein lävitse, hän on aivan kirkas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Sillä hän on Jumalan voiman löyhkä ja Kaikkivaltiaan kunnian paiste.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Sentähden ei taida mitään saastaista tulla hänen tykönsä; sillä hän on ijankaikkisen valkeuden valo, Jumalan vaikuttavaisen voiman saastuttamatoin peili ja hänen hyvyytensä kuva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Hän on ainoa tekee, ja tekee kuitenkin kaikki; sillä hän pysyy sinänsä ja uudistaa kaikki, ja vaikuttaa alati (a) pyhäin sieluissa, ja hän tekee Jumalan ystäviksi ja prophetaiksi. (a) Gr. sukukunnittain');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Sillä ei Jumala rakasta ketään. jos ei pysytä viisaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Hän on jalompi aurinkoa ja kaikkia tähtiä:kuin häntä valkeuteen verrataan, niin hän on vielä parempi. sillä valkeuden täytyy yötä paeta; mutta pahuus ei voita ikänä viisautta');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Sitä minä olen rakastanut ja etsinyt häntä hamasta minun nuoruudestani, ja ajattelin häntä ottaa morsiamekseni; sillä minä olen ruvennut rakastamaan hänen kauneuttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Hän on kunniallisesta suvusta; sillä hänen menonsa on Jumalan tykönä, ja kaikkein kappalten Herra rakastaa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Hän on salainen neuvo Jumalan tunnossa, ja hänen työnsä valitsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Jos rikkaus on kallis kappale elettäissä: mikä on rikkaampi viisautta, joka kaikki tekee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Jos taito sen tekee: kuka on taitavampi opettaja kuin hän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Jos joku rakastaa vanhurskautta, hänen työnsä ovat hyvät tavat; sillä hän opettaa raittiuden, toimen, oikeuden ja väkevyyden, jotka kaikkein tarpeellisimmat ovat ihmisten elämässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Jos joku pyytää paljon tietää, niin hän osaa sekä menneet, että tulevaiset; hän ymmärtää pimiät puheet, ja arvaa työläät tapaukset; ihmeet ja kamalat hän edellä tietää, mitä tapahtuu kullakin ajalla ja hetkellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Minä olen aikonut ottaakseni häntä seuraani; sillä minä tiedän hänen minulle antavan hyvää neuvoa, ja että hän lohduttaa minua surussa ja murheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Hänen kauttansa on nuorukaisella kunnia kansan seassa ja ylistys vanhain tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Minä löydetään ymmärtäväiseksi tuomiossa ja ihmeelliseksi voimallisten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Kuin minä vaikenen, odottavat he minua, kuin minä puhun, ottavat he vaarin, ja jos minä kauvan puhun, pitävät he kätensä suunsa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Hänen kauttansa minä saan kuolemattoman nimen, ja jätän ijäisen muiston jälkeentulevaisilleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Minä hallitsen kansoja, ja pakanat tulevat minulle alamaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Julmat tyrannit pelkäävät, kuin he minun kuulevat; kansan seassa minä olen hyvä ja sodassa sankari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Kotia tultuani kulutan minä aikani hänen kanssansa. Sillä ei häneen suututa, eikä hänestä ole mielen karvautta, vaan ilo ja riemu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Näitä minä ajattelin, ja panin sydämeeni; sillä kuolemattomuus on viisauden ajatuksessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Ja jotka hänen ystävyydessänsä ovat, niillä on puhdas ilo, ja ääretöin rikkaus tulee hänen kättensä töistä, ja toimi hänen puheestansa, ja hyvä ylistys hänen seurastansa ja sanoistansa: minä menin ympäri etsimään ja saattamaan häntä minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Minä olin hyvänkurinen lapsi, ja sain hyvän sielun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Mutta kuin minä hyvin kasvatettiin, kasvoin minä saastuttamattomaksi ruumiiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Ja minä ymmärsin, etten minä muutoin taitanut puhtaana pysyä, jollei Jumala sitä antaisi, ja se myös oli taito, tuta kenenkä armo se on; niin menin minä Herran tykö, ja rukoilin häntä, ja sanoin kaikesta sydämestäni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, '0 minun isäini Jumala ja kaiken laupeuden Herra, sinä, joka kaikki sanallas tehnyt olet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Ja ihmiset viisaudellas valmistanut olet, että hän hallitsis kaikki luontokappaleet, jotka sinulta luodut ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Että hän maailmaa hallitsis oikeudella ja vanhurskaudella, ja tuomitsis oikealla sydämellä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Anna minulle viisautta, joka on joka paikassa sinun istuimes ympärillä, ja älä hylkää minua sinun lastes seasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Sillä minä olen sinun palvelias ja sinun piikas poika, heikko ihminen, joka ei kauvan elä, jolla on vähän ymmärrystä sinun laistas ja oikeudestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Ja jos joku vielä ihmisten lapsista olis täydellinen, niin ei hän mitään maksa, jos ei hänellä ole sitä viisautta, joka sinulta tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Sinä olet minun valinnut sinun kansas kuninkaaksi ja sinun poikais ja tytärtes tuomariksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Ja käskit minun rakentaa sinulles templin pyhälle vuorelles ja alttarin sinun asuinkaupunkiis, joka olis sinun pyhän tabernaklis kaltainen, jonka sinä muinen annoit valmistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Ja sinun viisautes on sinun kanssas, joka sinun tekos tietää, ja oli tykönäs, kuin sinä maailman teit, ja tietää, mikä sinulle kelpaa, ja mikä oikea on sinun käskyissäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Lähetä häntä alas pyhästä taivaastas ja kunnias istuimelta: lähetä häntä, että hän olis minun tykönäni, ja työtä tekis minun kanssani, että minä ymmärtäisin, mikä sinulle otollinen on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Sillä hän tietää kaikki ja ymmärtää; ja anna hänen taluttaa minua töissäni toimellisesti ja varjella minua hänen voimassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Niin minun työni tulevat sinulle otollisiksi, ja niin minä tuomitsen sinun kansaas oikein, ja tulen mahdolliseksi istumaan minun isäni istuimella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Sillä kuka ihminen tietää Jumalan neuvon? eli kuka taitaa ajatella mitä Jumala tahtoo?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Sillä kuolevaisen ihmisen ajatukset ovat epäileväiset, ja meidän aivoituksemme ovat huikentelevaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Sillä kuolevainen ruumis vaivaa sielua, ja maallinen asuinsia rasittaa mieltä, joka paljon ajattelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Tuskin me osaamme maallisia, ja työläästi löydämme niitä, jotka käsillä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Kuka siis tahtoo tutkia taivaallisia? kuka taitaa tietää sinun neuvos, jos et sinä anna viisautta ja lähetä Pyhää Henkeäs korkeudesta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Ja niin niiden tiet ojentuvat, jotka ovat maan päällä, ja ihmiset oppivat, mitä sinulle on otollinen, Ja viisaudella autuaiksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Viisaus suojeli hänen, joka ensisti tehtiin ja luotiin maailman isäksi, ja pelasti hänen synnistänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Ja antoi hänelle voiman hallita kaikkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Kuin jumalatoin hänestä luopui vihassansa, niin hän tuli kadotetuksi, veljensä julman murhan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Ja kuin maa sen syyn tähden veden paisumisella turmeltiin, autti viisaus taas ja hallitsi vanhurskasta halvalla puulla..');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Kuin kaikki pakanat erhetyksessä irstaasti elivät, löysi se vanhurskaan, ja piti hänen nuhteetoinna Jumalan edessä, ja vahvisti häntä vastoin isällistä sydäntä poikaansa kohtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Se pelasti myös vanhurskaan, kuin jnmalattomat hukkuivat, kuin hän tulta pakeni, joka viiden kaupungin päälle lankesi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Joka maa autiolla on ja vielä suitsee pahuuden todistukseksi, ja puut, jotka raakaa hedelmää kantavat, ja suolapatsas, jotka seisoo epäuskoisen sielun muistoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Sillä joka ei tottele viisautta, heillä ei ole ainoasti se vahingoksi, ettei he tunne hyvää, vaan jättävät jälkeensä eläville tyhmyytensä muiston, ettei salata taideta, missä he erehtyneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Mutta viisaus vapahtaa heitä kaikesta tuskasta, jotka häneen turvaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Se johdatti myös vanhurskasta, jonka täytyi veljensä vihan tähden paeta, oikiaa tietä, ja osoitti hänelle Jumalan valtakunnan, ja antoi hänelle pyhäin tiedon; autti häntä hänen työssänsä, ja hän menestyi ja sai paljon tavaraa työllänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ja oli hänen kanssansa, kuin hänelle vääryyttä tehtiin niiltä, jotka hänelle tekivät väkivaltaa, ja teki hänen rikkaaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Ja suojeli häntä vihamiehiltänsä, ja varjeli niiltä, jotka häntä ajoivat takaa; se antoi hänelle voiton väkevässä taistelemisessa, että hän ymmärtäis jumalisuuden olevan voimallisemman kaikkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Ei se hyljännyt vanhurskasta, kuin hän myytiin pois, vaan varjeli häntä synnistä, ja seurasi häntä vankihuoneesen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ja ei hyljännyt häntä siteissä., siihenasti että se antoi hänen saada valtakunnan valtikan ja vallan niiden ylitse, jotka hänelle tekivät väkivaltaa: ja saatti heitä valhetteliaksi, jotka häntä laittivat, ja antoi hänelle iankaikkisen kunnian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Se vapahti pyhän kansan ja nuhteettoman siemenen pakanoista, jotka heitä vaivasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Se tuli Herran palvelian sieluun., ja seisoi julmia kuninkaita vastaan ihmeillä ja tunnustähdillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Se maksoi pyhille heidän työnsä palkan, ja johdatti heitä ihmeellistä tietä, ja oli heille päivällä varjelus ja yöllä liekki niin kuin tähdet');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Hän vei heitä Punaisen meren lävitse, talutti heitä suurten vetten keskeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Mutta heidän vihollisensa hän upotti ja nämät hän veti syvyyden pohjasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Sentähden ottivat vanhurskaat saaliin jumalattomilta, ja ylistivät. sinun pyhää nimeäs, Herra, ja kiittivät yksimielisesti sinun voitollista kättäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Sillä viisaus avasi mykkäin suun ja teki lasten kielet puhumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Se antoi menestyä heidän tekonsa pyhän prophetan käden kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Ja johdatti heitä synkän korven lävitse, niin että he majansa rakensivat korpeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Ja seisoivat vihollisiansa vastaan, ja kostivat vihamiehillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Kuin he janosivat, rukoilivat he sinua, Ja heille annettiin vettä korkiasta vuoresta, ja he sammuttivat janonsa kovasta kivestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Ja jolla heidän vihamiehensä vaivattiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Se tuli heille hyväksi, kuin he hätää kärsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Sillä niinkuin he hämmästyivät verta, joka tuli vuotavan veden siaan, käskyn rangaistukseksi, että lapsia tapettaman piti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Niin sinä annoit näille vettä yltäkylläisesti tietämättä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Ja annoit silloin nähdä heidän janostansa, kuinka sinä vihollisia vaivasit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Sillä koska nämät kiusattiin ja armolla kuritettiin, ymmärsivät he, kuinka jumalattomat vihassa tuomittiin ja rangaistiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Näitä sinä olet niinkuin isä neuvonut ja koetellut; mutta niitä muita niinkuin ankara kuningas rangaissut ja tuominnut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Ja tulivat rangaistuksi, sekä ne, jotka läsnä, että ne, jotka taampana olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Sillä heille tuli kaksinkertainen murhe ja huokaus, kuin he ajattelivat niitä, mitkä edes menneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Sillä koska he kuulivat heillensä hyväksi tapahtuvan sen, kuin heitä vaivattiin, tunsivat he Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Sillä joita he ennen ajoivat pois ylönkatseesta, hylkäsivät ja pilkkasivat, niitä täytyi heidän viimein ihmetellä, koska niin tapahtui, ettei heidän janonsa ollut niinkuin vanhurskasten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Niin myös heidän väärän menonsa tyhmäin ajatusten tähden, jonka kautta he niin petetyksi tulivat, että he rukoilivat järjettömiä matoja ja ylönkatsotuita petoja, lähetit sinä heidän sekaansa suuren joukon metsän petoja rangaistukseksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Että he ymmärtäisivät, että millä joku syntiä tekee, sillä hän myös vaivataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Sillä sinun kaikkivaltiaalle kädelles, jolla sinä maailman valmistamattomasta aineesta luonut olet, ei ollut mahdotoin, lähettää heidän päällensä karhujoukkoja ja rohkeita jalopeuroja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Eli vastuudesta luoda julmia ja tuntemattomia petoja, taikka niitä, jotka tulta sylkivät, taikka jotka julman savun puhalsivat, taikka jotka hirmuisia kipeniä silmistänsä laskivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Jotka ei ainoastaan olisi haavoittamisella heitä hukuttaa taitaneet, mutta myös hirmuisella katsannollansa heitä tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Ja he olisivat taitaneet paitsi sitä langeta yhdellä puhalluksella koston vainosta, ja sinun voimas hengellä hukkua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Mutta sinä olet kaikki asettanut mitalla, luvulla ja painolla. Sillä suuri voima on aina sinussa; ja kuka voi olla sinun käsivartes väkevyyttä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Sillä koko maailma on sinun edessäs niinkuin vaa\'an kieli ja niinkuin aamukasteen pisara joka putoo maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Mutta sinä armahdat kaikkia; sillä sinulla on voima kaikkein ylitse, ja kärsit ihmisten syntiä, että he itsensä parantaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Sillä sinä rakastat kaikkia, kuin on, ja et vihaa, mitäs tehnyt olet; sillä et sinä ole mitään valmistanut, jota sinä vihata taitaisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Kuinka taitaa mitään olla, jota et sinä tahtoisi? eli kuinka se taitais pysyä, jota et sinä kutsunut ole? Mutta sinä säästät kaikkia; sillä ne ovat sinun, Herra, sinä joka elämää rakastat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Ja sinun katoomatoin henkes on kaikissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Sentähden sinä vitkaan rankaiset heitä, jotka lankeevat, ja neuvot heitä kurituksella, missä he syntiä tekevät, että he pahuudesta pelastettaisiin, ja uskoisivat sinun päälles, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Sillä koska sinä olit vihainen sinun pyhän maas entisille asuville,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Että he kauheita töitä tekivät noitumisella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Tahdoit sinä meidän isäimme käsillä hävittää jumalattomat uhrin kantajat, ja jotka lapsensa haluttomasti tappoivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Jotka söivät ihmisen lihaa ja joivat hirmuisesti verta, jolla he luulivat sinulle tekevänsä palveluksen; ja ne, jotka vanhemmat olivat, tappoivat ne sielut, joilla ei yhtään apua ollut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Että se maa, joka sinun edessäs kaikkein seassa jaloin oli, tulis Jumalan lasten mahdolliseksi asuinsiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Kuitenkin säästit sinä heitä niinkuin ihmisiä, ja lähetit sinun sotajoukkos edelläjuoksiat hörhöläiset, että niiden piti heitä vähittäin hävittämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Ei tosin ollut sinulle mahdotoin antaa jumalattomia vanhurskasten alle sodassa, eli hukuttaa heitä hirmuisten petoin kautta, taikka kovalla sanalla kaikkia tyynni hukuttaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Mutta sinä tuomitsit heitä vitkaan, ja annoit heille siaa parannukseen, vaikka sinä tiesit heidät pahansisuisiksi, ja heidän pahuutensa luonnolliseksi, ettei heidän ikänä pitänyt toista mieltä saaman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Sillä he olivat kirottu siemen alusta. Niin et sinä myös peljännyt ketään, annoit anteeksi heidän rikoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Sillä kuka sanoo sinulle: mitäs teet? eli kuka seisoo sinun tuomiotas vastaan? eli kuka nuhtelee sinua hukkuneiden pakanain tähden, jotka sinä luonut olet? eli kuka asettaa itsensä kostajaksi sinua vastaan jumalattomain ihmisten tähden?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Sillä paitsi sinua ei ole yhtään jumalaa, joka murheen pidät kaikista; osoittaakses, ettet tuomitse väärin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Sillä ei kuninkaat eikä tylyt taida astua sinua vastaan, koska sinä rankaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Ettäs vanhurskas olet, niin sinä hallitset myös kaikki oikein, ja tiedät, ettei se sinun majesteetilles sovi, ettäs jonkun tuomitset, jota ei rangaistaman pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Sillä sinun väkevyytes on oikeuden alku, ja ettäs kaikkia hallitset, niin sinä säästät myös kaikkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Sillä sinä olet osoittanut väkevyytes heissä, jotka ei uskoneet, ettäs niin kaiketi voimallinen olit, ja osoitit itses niissä, jotka ylpiät olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Mutta sinä väkevä hallitsia tuomitset hiljaisuudessa, ja hallitset meitä paljolla kärsivällisyydellä; sillä sinä voit tehdä, mitäs tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Mutta sinä opetat kansaas senkaltaisIlla töillä, että vanhurskaana ja hyvänä oltaman pitäis; ja sinä annat sinun lapses tietää,.että he olisivat hyvässä toivossa, ettäs otat parannuksen syntien edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Sillä jos sinä lastes viholliset ja ne, jotka kuolemaan vikapäät olivat, senkaltaisella säästämisellä ja kärsivällisyydellä rankaisit, ja annoit heille aikaa ja tilaa itsensä parantaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Kuinka paljoa enempi sinä olet pitkämielinen, koskas tuomitset lapsias, joiden isäin kanssa sinä valan ja liiton monesta hyvästä lupauksesta tehnyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Sen tähden, niin usiasti kuin sinä meidän vihollisiamme vaivaat, teet sinä sen meille kuritukseksi, että me ottaisimme visusti vaarin sinun hyvyydestäs: jos me tuomitut olisimme, että me kuitenkin turvaisimme sinun laupiutees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Sentähden sinä rankaisit jumalattomat omilla kauhistuksillansa, jotka järjetöintä elämää pitivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Sillä he olivat niin peräti syvälle tulleet erhetykseen, että he myös pitivät ne pedot, joita heidän vihollisensa katsoivat ylön, jumalinansa, petetyt niinkuin taitamattomat lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Sen tähden olet sinä myös lähettänyt heidän sekaansa häpiällisen rangaistuksen, niinkuin järjettömille lapsille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Ja koska ei he senkaltaista häpiällistä rangaistusta totelleet, tulivat he Jumalan ankaran rangaistuksen alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Sillä he vaivattiin niiltä, jotka he jumalinansa pitivät, joka heille oli suureksi ylönkatseeksi, koska he näkivät hänen, jota ei he ennen tuta tahtoneet, ja oikiaksi Jumalaksi tunnustivat; sentähden tuli kadotus viimein heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Kaikki ihmiset ovat luonnostansa turhat, jotka ei Jumalasta mitään tiedä ja ei tunne häntä näkyväisestä hyvyydestä, eikä katso töistä, kuka tekiä on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Vaan pitävät taikka tulen, eli tuulen, eli puuskauksen, eli tähdet, eli väkevät vedet, auringon ja kuun taivaassa, jotka maailmaa haIlitsevat, jumalina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Mutta jos heillä olis hyvä suosio niiden kauniisen muotoon, niin että he sentähden pitäisivät niitä jumalain siassa, pitäis heidän oikeutta myöten ymmärtämän, kuinka paljoa parempi se on, joka niiden Herra on; sillä se, joka kaiken kauneuden tekiä on, hän on nämät luonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Ja jos he ihmettelisivät niiden voimaa ja väkeä, pitäis heidän myös oikeudella ajatteleman, kuinka paljoa voimallisempi se on, joka kaikki nämät valmistanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Sillä senkaltaisesta suuresta kauneudesta ja luomisesta taitaa Luoja niinkuin yhdessä kuvassa tunnetuksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Vaikka ei näiden ylitse niin suuresti valittamista ole; sillä he myös taitavat erehtyä, koska he etsivät Jumalaa, ja pyysivät mielellänsä häntä löytää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Sillä koska he katselivat hänen luontokappaleitansa ja tutkistelivat niitä, tulivat he petetyksi niiden katselemisessa, että luontokappaleet, jotka he näkivät, olivat niin ihanat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Kuitenkin ei he sentähden ole ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Sillä jos he ovat niin paljon ymmärtäneet, että he taisivat luontokappaleen niin korkiassa arvossa pitää: miksi ei he pikemmin häntä löytäneet, joka niiden Herra on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Mutta he ovat viheliäiset, ja heidän toivonsa on luettava kuolleiden sekaan, jotka sen jumalaksi kutsuvat, jonka ihmiset tehneet ovat, niinkuin kullan ja hopian, joka taitavasti valmistettu on, ja petoin kuvan, eli kelvottomat kivet, jotka vanhaan aikaan valmistetut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Niinkuin puuseppä, kuin hän työtä etsii, hakkaa puun, veistää ja silittää sen hyvin, ja siitä visua ja taitavaa työtä tekee, joka maailman tarpeissa tarvitaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Mutta sen työn lastut kokoo hän, ja keittää ruokaa syödäksensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vaan mitä liiaksi on, ja ei mihinkään kelpaa, kuin väärä ja oksainen on, ottaa hän ja visusti leikkaa, kuin hän joutaa, leikkaa taitavasti, ja tekee ihmisen eli jonkun järjettömän eläimen muotoiseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Ja panee sen punaiseksi ja valkiaksi, ja maalaa kauniiksi, ja jos siinä joku virhe on, sen hän vastuudesta maalilla sivuu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Sitte tekee hän sille kauniin huoneen, ja kiinnittää sen seinään raudalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Niin ettei se putoo, ja niin hyvin katsoo sen; sillä hän tietää hyvin, ettei se itsiänsä auttaa taida; sillä ei se muu ole kuin kuva, ja tarvitsee apua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Ja kuin hän rukoilee tavaransa, emäntänsä ja lastensa edestä, ei hän häpee puhutella sitä, jolla ei henkeä ole,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ja anoo heikolta terveyttä, rukoilee kuolleelta elämää, ja pyytää häneltä apua, joka ei mitään voi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Ja siltä, joka ei käydä taida, hyvää matkaa, ja että hänen askareensa, asiansa ja tekonsa menestyis, pyytää hän voimattomalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Niin myös se tekee, joka tahtoo purjehtia, ja on aikonut vaeltaa julmissa aalloissa: hän rukoilee puuta, joka heikompi sitä laivaa on, jonka päällä hän vaeltaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Sillä se on sentähden tehty, että sillä pitää ravintoa etsittämän, ja tekiä on sen taidolla valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Mutta sinun edeskatsomises, oi Isä, hallitsee sitä; sillä sinä annat tien meressä ja aaltoin keskellä pelkäämättömän juoksun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Jolla osoitat, kuinka sinä kaikissa paikoissa voimallinen olet auttamaan, vaikka joku itsensä antais merelle ilman laivaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Kuitenkin, ettes tahdo sitä turhana pitää, jota sinä viisaudessas luonut olet, tapahtuu se, että ihmiset uskaltavat henkensä sen kaltaisen huonon puun päälle, ja tulevat laivassa talteen, jossa he vaeltavat aaltoin lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Sillä muinen, kun uljaat sankarit hukutettiin, pakenivat ne laivaan, joilla toivo oli, että heidän piti lisäämän maailmaa jälleen, jonka sinun kätes hallitsi, he jättivät niin maailmalle siemenen jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Sillä se puu on siunattu, jonka kautta vanhurskas tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Mutta sitä pitää kirottaman, joka käsillä valmistetaan, se myös, joka sen tekee: tämä sentähden että hän sen teki, se sentähden, että se jumalaksi kutsutaan,.kuitenkin on katoovainen kappale');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Sillä Jumala vihaa yhtäläisesti molempia, jumalatointa ja hänen jumalatointa työtänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ja työ tulee tekiänsänsä vaivatuksi.,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Seutähden myös pakanain epäjumalat kuritetaan; sillä ovat Jumalan luontokappaleista tulleet kauhistukseksi ja ihmissieluille pahennukseksi ja ymmärtämättömille paulaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Sillä epäjumalten asetus suurin huoruus, ja heidän alkunsa, on vahingollinen pahennus maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Sillä ei ne alusta olleet, eikä ijankaikkisesti pysy;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Vaan ihmisten turhalla kunnioittamisella he ovat tulleet maailmaan, ja sentähden ajatellut ettei ihmiset saa kauan elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Sillä isä, koska hän suri ja itki poikaansa, joka häneltä, varhain tuli pois, antoi hän tehdä kuvan ja rupesi pitämään hänen joka kuollut ihminen oli, jumalana, ja asetti palvelioillensa jumalanpalveluksen ja uhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Sitte ajankululla pidettiin senkaltainen jumalatoin tapa lakina, että myös knvaa täytyi kunnioittaa tyrannein käskystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Niin myös kansa, joka ei läsnä ollen saanut kunnioittaa, että he niin kaukana asuivat, antoivat tehdä sen muodon kaukaisella maalla, ja teettivät kauniit voimallisten kuningasten kuvat, että he ahkerasti olisivat heille mielennouteeksi, sekä poissa että läsnäollessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Niin autti myös tekiän suuri ahkeruus vahvistamaan ymmärtämättömiä senkaltaiseen jumalanpalvelukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Sillä koska joku tahtoi palvella ruhtinaan mieliksi, teki hän kuvan kaikella taidolla kaikkein kauneimmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Mutta kansa, joka senkaltaisella kauniilla työllä oli kehoitettu, rupesi sitä jumalana pitämään, joka vähää ennen ihmisenä kunnioitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Senkaltaisesta asiasta tuli petollisuus maailmaan, koska ihmisiä jotenkin ahdistettiin, eli he tahtoivat tehdä tyrannille jotain mielennouteeksi, antoivat he kiville ja puille senkaltaisen nimen, kuin ei pitänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Sitte ei he siihen tyytyneet, että he Jumalan tunnosta erehtyivät, vaan vaikka he elivät senkaltaisessa tyhmässä ja hullussa menossa, kutsuivat he kuitenkin senkaltaisen sodan ja vahingon rauhaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Sillä taikka he lapsensa tappavat uhriksi, eli pitävät jonkun jumalanpalveluksen, jota ei tarvita mainittaa, taikka harjoittavat itsiänsä ylönsyömisessä pahalla tavalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Ja ei ole heillä enempi puhdasta elämää aviokäskyssä, vaan toinen tappaa toisen petoksella, eli murheelliseksi tekee huoruudella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Ja heidän seassansa käy kaikki sekaisin: veri, murha, varkaus, petos, vilppi, vaatimus, väärä vala, hurskasten levottomuus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Kiittämättömyys, nuorten sydänten pahennus, mykät synnit, sukurutsaus, huoruus ja salavuoteus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Sillä häpiällisten epäjumalain palvelus on alku, syy ja loppu kaikkeen pahuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Jos he pyhäpäivää pitävät, niin he tekevät kuin hullut; jos he ennustavat, niin se on kaikki valhe; ei he oikein elä, ja ovat nopsat valalla pettämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Sillä he uskovat hengettömäin jumalten päälle, niin ei he pelkää vahinkoa, kuin he vannovat väärin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Kuitenkin oikein heille se tapahtuu, sekä ettei heillä ole oikiaa tietoa Jumalasta, että he epäjumalista ottavat vaarin, ja että he vannovat väärin, ja ei he pyhästä lukua pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Sillä jumalattomain pahuus saa lopun, ei siitä vallasta, joka heillä on vannoissansa, vaan siitä rangaistuksesta, jonka he synnillänsä ansaitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Mutta sinä meidän Jumalamme olet armollinen, vakaa ja kärsivällinen, ja hallitset kaikki laupiudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Ja jos me syntiä teemme, olemme me kuitenkin sinun, ja tunnemme sinun voimas; mutta että me sen tiedämme, niin emme tahdo syntiä tehdä; sillä me pidetään sinun omanas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Mutta tuta sinua, on täydellinen vanhurskaus, ja tietää sinun voimas, on ijankaikkisen elämän juuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Sillä ei ihmisen pahat aivoitukset meitä niin viettele, eikä maalarin turha työ, kirjava ja monenkarvainen kuva,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Jonka muoto pahentaa ymmärtämättömät, ja jotka pahaa mielellänsä tekevät, rakastavat hengettömiä ja kuolleita kuvia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Senkaltaisia hedelmiä ovat he mahdolliset saamaan, sekä ne, jotka niitä tekevät, että ne, jotka niitä ikävöitsevät ja palvelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Jos savenvalaja, joka pehmeää savea vaivalla valmistaa, tekee kaikkinaiset astiat meidän tarpeeksemme; mutta hän tekee siitä samasta savesta sekä ne astiat, jotka puhtauteen että saastaisuuteen sopivat; mutta mihinkä kukin pitää pantaman, se on savenvalajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Mutta se on viheliäinen työ, kuin hän siitä savesta voimattoman jumalan tekee, ja on kuitenkin itse, ei paljoa ennen, maasta tehty, Ja vähän hetken perästä menee sinne jälleen, josta hän otettu on, koska sielu, joka hänellä oli, häneltä otetaan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Mutta ei hänen murheensa siinä ole, että hänen työtä tekemän pitää, eikä että hänellä on niin lyhyt ikä, vaan että hän kilvoittelis kultaja hopiaseppäin kanssa, että hän tekis vaskenvalajan tavalla, ja pitää sen kunniana, että hän petollista työtä tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Sillä hänen sydämensä ajatukset ovat kuin tuhka, ja hänen toivonsa on huonompi maata, ja hänen elämänsä ylönkatsottu kuin savi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Ettei hän tuntenut sitä, jo. ka hänen tehnyt oli, ja antoi hänelle sielun, joka hänessä vaikuttaa, ja puhalsi häneen elävän hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'He pitivät ihmisen elämän tyhjänä ja ihmisen menon kaupantekona, sanoen: aina pitää voittoa etsittämän pahallakin kalulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Nämät tietävät kaiketi kyllä, että he syntiä tekevät, koska he senkaltaisia turhia kappaleita ja kuvia maasta ja savesta tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Mutta he ovat tyhmemmät ja viheliäisemmät kuin lapsi, sinun kansas viholliset, jotka heitä sortavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Että he kaikki pakanain epäjumalat jumalina pitävät, joiden silmät ei näe, ja heidän nenänsä ei haista, eikä heidän korvansa kuule, heidän sormensa käsissänsä ei tunne, ja heidän jalkansa ovat sangen hitaat käymään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Sillä ihminen on tehnyt heidät, ja joka hengen saanut on, on valmistanut heitä; mutta ihminen ei taida tehdä sitä, joka hänen kaltaisensa on, paljoa vähemmin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Ja että hän kuolevainen on, niin hän kuolleen tekee jumalattomilla käsillänsä; hän on itse parempi kuin se, jota hän palvelee; sillä hän itse elää, mutta se ei koskaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Sikälikin palvelevat he myös kaikkein kauheimpia petoja: jos he muihin järjettömiin luontokappaleihin verrataan, niin he ovat paljoa pahemmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Sillä ei ne ole aljut niinkuin muut eläimet, jotka ovat suloiset nähdä, ja ei ole Jumalalta ylistetyt eli siunatut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Sentähden he senkaltaisilla rangaistiin, joita he ansainneet olivat, niin että he paljoilta pedoilta vaivattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Jota vitsausta vastaan sinä teit kansalles hyvää, ja valmistit heille himoruokaa, peltokanoja ravinnoksi, jota he himoitsivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Että ne, jotka sitä ruokaa himoinneet olivat, piti senkaltaisten annettuin ja säättyin peltokanain kautta oppiman itsensä pitämään pois luonnollisista tarpeista; mutta muut, joilla vähä aikaa puuttumus oli, piti uudesta elatuksesta osallisiksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Sillä sen piti niin tapahtuman, että heille, jotka niin julmasti tekivät, piti senkaltainen puuttumus tuleman, joka ei pitänyt lakkaaman; mutta näille ainoastaan osoitettiin, kuinka heidän vihollisensa tulivat vaivatuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Tulivat myös näille pahat ja julmat pedot ja pahoilta kärmeiltä pistettiin ja turmeltiin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Ei kuitenkaan ollut se vitsaus kauvan, vaan he olivat vähän aikaa peljätetyt parannukseen; sillä heillä oli terveyden merkki, että heidän piti ajatteleman sinun käskyjäs sinun laissas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Sillä jotka käänsivät itsensä sen merkin puoleen, ne tulivat terveeksi, ei katsomisella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Vaan sinun kauttas, joka olet kaikkein vapahtaja; jolla sinä osoitit meidän vihollisillemme, että sinä olet se, joka autat kaikesta pahasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Mutta ne heinäsirkoilta ja kärpäsiltä kuoliaaksi purtiin, ja ei taitaneet apua löytää hengellensä; sillä he olivat sen ansainneet, että heidän piti sillä vaivatuksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Mutta sinun lapsias ei taitaneet ne myrkylliset lohikärmetten hampaat vahingoittaa; sillä sinun laupiutes tuli heille avuksi ja paransi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Sillä sentähden he niin rangaistiin ja kohta parattiin jälleen, että he oppisivat ajattelemaan sinun sanaas, ja ettei he niin syvältä unhotukseen tulisi, vaan pysyisivät huikentelematta sinun hyvissä töissäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Sillä ei yrtit eikä voiteet heitä parantaneet, vaan sinun sanas, Herra, joka kaikki parantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Sillä sinun hallussas on sekä elämä että kuolema, ja sinä johdatat helvetin portille, ja sieltä ylös jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Mutta jos ihminen jonkun tappaa pahuudellansa, niin ei hän taida tuoda jälleen henkeä, joka siitä on lähtenyt, eli palauttaa sielua, joka eroitettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Mutta mahdotoin on välttää sinun kättäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Sillä jumalattomat, jotka ei tahtoneet sinua tuta, hosuttiin sinun voimallisella käsivarrellas, kuin he hirmuisella sateella, rakeella, vedellä, jota ei he paeta taitaneet, vaivattiin, ja tulella kulutettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Ja se oli kaikkein kamalin, että tuli enimmästi paloi vedessä, joka kuitenkin kaikki sammuttaa; sillä maailma sotii vanhurskasten edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Toisinaan oli tulen liekki niin masia, ettei se polttanut niitä petoja, jotka jumalattomille lähetettiin, vaan että heidän itse nähdä täytyi heitänsä Jumalan tuomiolta niin rangaistavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Toisinaan paloi liekki vedessä vastoin tulen voimaa, että hän väärän suvun maan päältä hukuttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Sitä vastaan ruokit sinä kansas enkelein rualla, ja lähetit leipää taivaasta ilman työtä valmistettua, joka taisi antaa kaikkinaista himoa, ja oli jokaiselle hänen makunsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Sillä jos sinuun turvataan, ilmoittaa se sinun lapsilles, kuinka makia sinä olet, ja jokainen teki siitä, mitä hän tahtoi, niinkuin hänen himonsa oli, että se niin ja niin maisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Mutta näille pysyi lumi ja jää sulamatta tulessa, että he olisivat ymmärtäneet, kuinka tuli, joka rakeissa paloi, ja sateessa leimahti, turmeli vihollisten hedelmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Että vanhurskaat olisivat ravituksi tulleet, täytyi sen voimiansa unohtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Sillä koska luontokappale sinua palvelee niinkuin Luojaansa, on se voimallinen rankaisemaan vääriä, ja asettaa itsensä niille hyväksi, jotka uskovat sinun päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Sen tähden se antoi itsensä silloin moneksi muuttaa, ja oli sinun lahjalles kuuliainen, joka kaikki ravitsee, itse kunkin tahtonsa jälkeen, niinknin joku sitä tarvitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Että sinun lapses, joita sinä, Herra, rakastit, oppisivat, ettei kasvanut hedelmä elätä ihmistä, vaan sinun sanas ne ravitsee, jotka uskovat sinun päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Sillä se, joka ei tulelta kulutettu, suli kohta vähästä auringon paisteesta, koska se palavaksi tuli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Että ilmoitettaisiin, että sinua pitää kiitettämän jo ennenkuin aurinko nousee, ja astuttaman sinun etees päivän valjetessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Sillä kiittämättömän ihmisen toivo pitää hukkuman niinkuin härmä talvella, ja vuotaman pois niinkuin kelvotoin vesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Suuret ja sanomattomat ovat sinun tuomios, Herra; sentähden ovat myös tyhmät ihmiset erehtyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Sillä koska ne väärät luulivat polkevansa pyhän kansan, tulivat he pimeydellä sidotuksi, ja pitkällä yöltä vangituksi, ja niinkuin karkurit olivat he suljetut katon alla ijankaikkiselta viisaudelta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Ja kuin he luulivat syntinsä salatuksi ja pimiän peitteen alla unhotetuksi, tulivat he hirmuisesti hajoitetuksi ja peljästyksellä kauhistetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ettei se loukaskaan, jossa he olivat, taitanut heitä ilman pelkoa kätkeä: silloin oli hyminä heidän ympärillänsä, josta he peljästyivät, ja hirmuiset näyt näkivät, joista he hämmästyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Ja tuli ei taitanut millään muotoa valistaa heitä, eikä kirkasten tähtien paiste taitanut sitä hirmuista yötä valistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Mutta heille näkyi palavainen tuli täynnänsä kauhistusta; silloin hämmästyivät he senkaltaista peljästystä, joka kuitenkin tyhjä oli, ja ajattelivat vielä pahempaa tarjona olevan kuin he näkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Noitain tieto oli tyhjä, ja sen ylistys tuli häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Sillä ne, jotka olivat tottuneet ajamaan pois pelkoa ja hämmästystä sairaista sieluista, tulivat se sairaiksi, niin että heidän pelkoansa pilkattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Ja jos ei senkaltaiset kauhistukset olis peljättäneet heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Niin heidän olis kuitenkin täytynyt hukkua hämmästyksestä, koska pedot heidän sekaansa tulivat, ja kärmeet joukossa niin havisivat, ettei he mielellänsä katsoneet ilmaa, jota ei he kuitenkaan saaneet paitsi olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Sillä joka niin epäileväinen on, sen tekee hänen oma pahuuntensa, joka hänestä todistaa ja tuomitsee, ja paha omatunto aina pahimmin päin ajattelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Sillä pelko tulee siitä, ettei joku edestänsä vastata taida, ja ei tiedä mistään apua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Mutta kussa vähä lohdutusta on sydämessä, niin epäilys tekee enempi vaivaa kuin itse rangaistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Mutta ne, jotka ynnä makasivat sinä yönä, joka hirmuinen ja oikia yö oli, ja siitä kauhiasta ja syvästä helvetistä tullut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Toisinansa vaivattiin hirmuisilla näyillä, toisinansa niin joutuivat, ettei he muuta toivoneet kuin kuolemaa; sillä äkillinen ja tapaturmainen pelko tuli heidän päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Niin että kussa joku löydettiin, siinä hän oli niinkuin hän olis ollut pantu kiinni ja ilman kahleita kätketty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Joko hän oli peltomies, eli paimen, eli työn tekiä korvessa, hänen täytyi, ehkä kusta hän löydettiin, kärsiä välttämätöintä ahdistusta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Sillä he olivat kaikki yhtäläisillä pimeyden kahleilla sidotut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Jos tuuli kuului puhaltavan, eli linnut suloisesti visertelevän paksuilla oksilla, eli joku töminä juoksevaisesta vedestä eli putoovaisista ja kolisevaisista kivistä, eli että intoiset eläimet juoksivat, joita ei he nähneet, eli että hirmuiset pedot ulvoivat eli kajaus kävi vuorten raoista: niin he hämmästyivät siitä, niin että he peräti tyhmistyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Koko maailmalla oli kirkas vaIkeus, ettei työt tulleet estetyiksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Ainoasti näillä oli synkiä yö, joka oli sen pimeyden kuva, joka heille tuleva oli; mutta he olivat itsellensä suuremmaksi rasitukseksi kuin pimeys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Mutta sinun pyhilläs oli suuri valkeus, ja viholliset kuulivat kyllä heidän äänensä, mutta ei he nähneet heitä. lä heidän äänensä, mutta ei he nähneet heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Ja he ylistivät sinua, ettei he senkaltaista kärsineet, ja kiittivät, ettei he, jotka heiltä vahingoittiin, heille kostaneet, ja toivottivat, että he olisivat kaukana heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Sitä vastaan annoit sinä näille tulipatsaan, joka heitä valisti oudolla tiellä, ja et antanut auringon vahingoittaa heitä sillä jalolla matkalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Sillä ne olivatkin mahdolliset olemaan ilman valkeutta, ja pitikin pimeydessä niinkuin kahleissa makaaman, että he sinun lapsias vankina pitivät, jonka kautta lain katoomatoin valkeus maailmalle annettaman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Ja kuin he ajattelivat tappaa: pyhäin lapsia, (mutta yksi ulosheitetyistä kätkettiin heille rangaistukseksi), otit sinä suuren joukon heidän lapsistansa, ja hukutit heidät yhtä haavaa väkevässä vedessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Se yö oli meidän isillemme ennen ilmoitettu, että he vahvistettaisiin ja iloitsisivat lupauksesta, jonka he uskoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Ja sinun kansas toivoi niin vanhurskasten autuutta ja vihollisten kadotusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Sillä kuin sinä vihollisia vaivasit, teit sinä meitä, joita tykös kutsuit, jaloksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Ja kuin jumalisten pyhät lapset uhrasivat sinulle salaisesti, ja yksimielisesti pitivät Jumalan lakia, silloin he tahtoivat niinkuin pyhät kärsiä pahaa ja hyvää toinen toisensa kanssa; ja isät veisasivat kiitosvirsiä heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Mutta sitä vastaan kuului vihollisten huuto paljo toisin, ja kuultiin vaikia valitus siellä ja täällä lapsilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Sillä yhtäläinen vitsaus oli herralla ja palvelialla, ja kuninkaankin täytyi sitä kärsiä kuin alamaisten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Ja jokaisella heillä oli sangen monta kuollutta, Jotka yhdenkaltaisella kuolemalla kuolivat, niin ettei elävät kerinneet heitä hautaamaan; sillä yhdellä hetkellä tulivat heidän parhaat sikiänsä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Ja jotka ei ennen tahtoneet uskoa, estetyt noidilta, niiden täytyi nyt, sittekuin kaikki esikoiset tapetut olivat, tunnustaa, että tämä kansa oli Jumalan lapsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Sillä koska kaikki alallansa ja vaiti olivat, ja juuri puoliyö oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Tuli sinun kaikkivaltias sanas alas taivaasta kuninkaalliselta istuimelta, niinkuin voimallinen sotamies, keskelle maata, joka piti hävitettämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Se terävä miekka, joka sinun ankaraa käskyäs kantoi, seisoi, ja täytti kaikki paikat kuolleilla, ja vaikka se seisoi maassa, ulottui se kuitenkin taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Silloin peljätti heitä äkisti hirmuinen unen näky, ja tapaturmainen hämmästys tuli heidän päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Ja tässä makasi yksi, ja toinen siellä puolikuolleena, niin että kyllä hänessä nähtiin, minkä syyn tähden hän kuoli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Sillä unet, jotka heitä peljättivät, antoivat heille kyllä tietää, ettei he olisi hukkuneet tietämättä, minkä tähden he niin pahoin rangaistiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Tuli myös vihdoin kuoleman kiusaus vanhurskaille, ja korvessa tapahtui vahinko kansassa; mutta viha ei ollut kauvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Sillä se nuhteetoin mies kiiruhti, joka heidän edestänsä soti, ja kantoi virkansa kilven, rukouksen ja sovinnon suitsutuksella, ja seisoi vihaa vastaan, ja lopetti sen surkeuden, jolla hän osoitti, että hän oli sinun palvelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Mutta hän voitti sen hirmuisen menon, ei ruumiillisella väellä eli miekan voimalla, vaan sanalla paiskasi hän vaivaajan allensa, koska hän ilmoitti valan ja liiton, joka isille luvattu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Sillä koska kuolleet lankesivat toinen toisensa päälle, seisoi hän siellä keskellä, ja asetti vihan, ja esti, ettei hän päässyt eläväin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Sillä hänen pitkässä hameessansa oli kaikki kaunistus, ja isäin kunnia neljässä kivirivissä kaivettu, ja sinun jaloutes hänen päänsä lakissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Senkaltaisista täytyi turmelian paeta ja sitä peljätä; sillä siinä oli kyllä, että viha ainoasti sillä koeteltiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Mutta jumalattomille tuli viha ilman laupiutta loppuun asti; sillä kyllä hän ennen tiesi, mitä heidän vasta tekemän piti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Että heidän piti käskemän heidän mennä matkaansa, ja johdattaman heitä visusti, että heidän piti sitä katuman, ja ajaman heitä takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Sillä kuin he vielä murehtivat ja valitusitkua pitivät kuolleiden hautain tykönä, joutuivat he toiseen tyhmään aivoitukseen, että he tahtoivat heitä ajaa takaa niinkuin karkureita, joita he kuitenkin olivat ajaneet pois suurella rukouksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Mutta sen piti niin käymän, että he tulivat hukatuksi senkaltaisella lopulla, jonka he ansainneet olivat, ja unhottivat, mitä heille oli tapahtunut, että he saivat täydellisen vitsauksen, joka heille vielä tarjona oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Ja sinun kansas piti vaeltaman ihmeellistä matkaa, mutta nämät uuden kuolemisen tavan löytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Sillä kaikki luontokappaleet, joilla oma luonto oli, muuttivat itsensä sinun käskys perään, jota he palvelivat, että sinun lapses ilman vahinkoa olisivat vaeltaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Pilvi oli siellä ja varjosi leirin: jossa ennen vesi oli, näkyi kuiva maa, Punaisesta merestä, tuli tie ilman estettä, ja väkevistä aalloista viheriäinen keto,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Josta kaikki kansa kävi, jotka sinun kätes alla suojeltiin. nähden senkaltaista ihmeellistä ihmettä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Ja kävivät niinkuin hevoset laitumella, ja hyppäsivät niin: kuin karitsat, ja kiittivät sinua l Herra, joka heitä pelastit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Sillä he johdattivat mieleensä, mitä heille oli tapahtunut heidän viheliäisyydessänsä, kuinka maa, sen siassa kuin hän ennen antoi eläimiä, nyt antoi kärpäsiä ja vesi antoi paljo sammakoita kalain edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Senjälkeen näkivät he myös uuden lintuin lajin, kuin he himoitsivat, ja anoivat herkullista ruokaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Sillä peltokanat tulivat heidän tykönsä merestä, lakkauttamaan heidän himoansa. Tuli myös rangaistus syntisille ihmeen kanssa, joka väkevällä pitkäisen leimauksella tapahtui; sillä se oli. oikein, että he senkaltaista kärsivät tuimuutensa tähden, että he olivat pahoin tehneet vieraita vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Muutamat, kuin ne tulivat, jotka ei tietäneet, kuhunka heidän piti menemän, ei ottaneet heitä vastaan; mutta muutamat vaativat vieraita, jotka heille olivat hyvää tehneet, orjuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, '(Ja ei siinä ainoasti, vaan yksi rangaistus piti tuleman heidän päällensä, että he pahaa tekivät muukalaisille.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Mutta muutamat vaivasivat suurella tuskalla niitä, jotka he ottivat ilolla vastaan, ja antoivat kanssansa nautita kaupungin oikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Mutta ne myös tulivat sokeudella lyödyksi (niinkuin ne, vanhurskaan oven edessä) paksulla pimeydellä saavutettiin, että jokainen etsi tietä omaan oveensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Sillä elementit kävivät toinen toisensa sekaan edestakaisin, niinkuin kanteleen kielet soivat toinen toisensa jälkeen ja kauniisti kuuluvat, niinkuin silmäin edessä nähdään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Sillä joka tottunut oli maalla olemaan, se oli vedessä, ja joka vedessä oli tottunut olemaan, se kävi maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Tuli oli voimallinen vedessä vastoin luontoansa, vesi unhotti voimansa sammuttamisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Sitä vastaan tulen liekki ei kuluttanut kuolevaisten eläimien lihaa, jotka siinä kävivät, eikä sulattanut kuolematointa ruokaa, joka kuitenkin niinkuin jää kohta suli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Herra, sinä olet kaikissa kunnioittanut ja jaloksi tehnyt sinun kansas, ja et katsonut heitä ylön, vaan aina ja joka paikassa olet ollut heille avullinen. Viisauden kirjan loppu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Kaikki viisaus on Herralta Jumalalta, ja pysyy hänen tykönänsä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Kuka on lukenut meren sannan, ja sateen pisarat, ja maailman päivät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Kuka on mitannut taivaan korkeuden, ja maan leveyden, ja meren syvyyden? Kuka on Jumalan viisauden tutkinut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Sillä hänen viisautensa on ennen kaikkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Jumalan, kaikkein Korkeimman, sana on viisauden kaivo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Ja Ijankaikkinen käsky on hänen lähteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Kuka taitais muutoin tietää, kuinka ihmisen pitää viisauden ja toimen käsittämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Yksi on kaikkein Korkein, kaikkein Luoja, Kaikkivaltias, väkevä Kuningas, ja sangen hirmuinen, joka istuu istuimellansa, hallitseva Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Hän on Pyhän Henkensä kautta sen luonut, ja nähnyt, tietänyt ja mitannut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Ja on vuodattanut viisauden kaikkein tekoinsa päälle ja kaiken lihan päälle, armonsa perästä, ja antaa sen niille, jotka häntä rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Herran pelko on kunnia ja ylistys, riemu ja kaunis kruunu');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Herran pelko ilahuttaa sydämen ja antaa ilon ja riemun, ja pitkän ijän!.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Joka Herraa pelkää, hänelle käy hyvin viimeisessä hädässä, ja hän saa lopulta siunauksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Rakastaa Jumalaa, on kaikkein kaunein viisaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'Ja joka sen näkee, hän rakastaa sitä; sillä hän näkee, kuinka suuria ihmeitä se tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Herran pelko on viisauden alku., joka on uskollisten sydänten pohjassa, ja asuu valittuin vaimoin tykönä, ja löydetään ainoasti vanhurskasten ja uskollisten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Herran pelko on oikia jumalanpalvelus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Joka sydämet varjelee, ja tekee hurskaaksi, ja antaa ilon ja riemun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Joka Herraa pelkää, hänelle käy hyvin, ja kuin hän lohdutusta tarvitsee, niin hän tulee siunatuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Peljätä Jumalaa on täydellinen viisaus. joka tekee rikkaaksi ja tuo myötänsä kaikkea hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Se täyttää koko huoneen lahjallansa ja kaikki paikat tavarallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Herran pelko on viisauden kruunu, ja antaa hyvän rauhan terveyden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Ja ne molemmat ovat Jumalan lahjat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Tämä viisaus tekee ihmiset oikein toimellisiksi; ja joka siinä vahvasti riippuu kiinni, se auttaa häntä kunnialla..');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Sillä Herran pelko on viisauden juuri,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Ja hänen oksansa kukoistaa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 27, 'Herran pelko ajaa synnin pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 28, 'Sillä joka on ilman pelkoa, ei se kelpaa Jumalalle, ja hänen ylpeytensä maahan kukistaa hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 29, 'Mutta siviä odottaa sitä aikaa, joka häntä lohduttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 30, 'Sillä vaikka hänen asiansa on sorrettu ajaksi, niin kuitenkin kiittävät toimelliset hänen viisauttansa. Jumalan sana on jumalattomalle kauhistus; sillä se on viisauden tavara, joka häneltä kätketty on. Minun poikani, jos sinä tahdot viisaaksi tulla, niin opi käskysanat, ja Jumala antaa sinulle viisauden. Sillä Herran pelko on oikea viisaus ja kuritus; usko ja kärsivällisyys kelpaa Jumalalle. Katso, ettei sinun Jumalan pelkos ole ulkokullaisuus, ja älä palvele häntä petollisella sydämellä. Älä etsi kiitosta ihmisten tykönä ulkokullaisesti; ja katso, mitä sinä puhut, uskot ja aiot; Ja älä itsiäs korota, ettet lankeaisi ja häpiään tulisi. Ja Herra ilmoittaa sinun salaisuutes, ja maahan kukistaa sinun julkisesti ihmisten nähden, Ettes ole palvellut oikiassa Jumalanpelvossa, ja sinun sydämes on ollut petollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Poikani, jos sinä tahdot olla Jumalan palvelia, niin valmista sinuas kiusaukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Pysy vahvana ja kärsi, ja älä ole nopia seuraamaan, jos sinua siitä houkutellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Pidä sinuas Jumalan tykö, ja älä poikkee, ettäs vihdoin vahvistuisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Kärsi mielelläs kaikkia, mikä sinun päälles tulee, ja ole kärsivällinen kaikessa murheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Sillä niinkuin kulta tulen kautta, niin myös ne, jotka Jumalalle kelpaavat, murheen tulen kautta koetellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Luota Jumalaan, niin hän auttaa sinua; ojenna ties, ja toivo häneen');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Te, jotka Herraa pelkäätte, luottakaat; sillä hän puutu teiltä');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Te, jotka Herraa pelkäätte, toivokaat häneltä hyvää, niin te löydätte armon ja lohdutuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Jotka Herraa pelkäätte, odottakaat hänen armoansa ja älkööt poiketko, ettette hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Katselkaat vanhain esimerkkejä; ja ottakaat niistä vaari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Kuka on koskaan häpiään tullut, joka on toivonut häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Kuka on koskaan hyljätty, joka Jumalan pelvossa on pysynyt? eli kuka on koskaan häneltä hyljätty, joka on häntä avuksensa huutanut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Sillä Herra on armollinen ja laupias, hän antaa synnit anteeksi, ja auttaa hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Voi niitä, jotka Jumalaa epäilevät, ja ei pysy vahvana! voi jumalatointa, joka sinne ja tänne kääntyy!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Voi epäuskoisia, ettei he usko! sentähden ei pidä heidän myös varjelluksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Voi niitä, jotka ei ole kärsivälliset!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'Kuinka heidän silloin käy, kuin Herra on heitä etsivä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Jotka Herraa pelkäävät, uskovat hänen sanansa, ja jotka häntä rakastavat, ne pitävät hänen käskynsä. Jotka Herraa pelkäävät, tekevät mitä hänelle on otollinen, ja jotka häntä rakastavat, ne pitävät lain oikein. Jotka Herraa pelkäävät, ne ojentavat sydämensä, ja nöyryyttävät itsensä hänen eteensä, ja sanovat, Me tahdomme ennemmin langeta Herran käsiin, kuin ihmisten käsiin; sillä hänen laupiutensa on niin suuri kuin hän itsekin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Rakkaat lapset, kuulkaat minua, teidän isäänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Ja tehkäät niin, että teille hyvin kävisi');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Sillä Herra tahtoo, että lapset isäänsä kunnioittavat, ja mitä äiti käskee lapsille, sitä hän tahtoo pidettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Joka isäänsä kunnioittaa, hänen syntiänsä ei Jumala rankaise,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Ja joka äitiänsä kunnioittaa, se kokoo itsellensä hyvän tavaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Joka isäänsä kunnioittaa, se saa ilon lapsistansa; ja kuin hän rukoilee, niin hän tulee kuulluksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Joka isäänsä kunnioittaa, se saa kauvan elää, ja joka Herran tähden on kuuliainen, se lohduttaa äitinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Joka Herraa pelkää, se kunnioittaa myös isäänsä ja palvelee vanhempiansa, ja pitää heitä herranansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Kunnioita isääs ja äitiäs työllä, puheella ja kärsivällisyydellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Että heidän siunauksensa tulis sinun päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Sillä isän siunaus rakentaa lapsille huoneet, mutta äidin kirous ne maahan kukistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'älä naura isäs ylönkatsetta, sillä ei sinun ole siitä kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Kunnioittaa isääs on sinun oma kunnias, ja katsoa ylön äitiäs on sinun oma häpiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Rakas lapsi! korjaa isääs hänen vanhalla ijällänsä, ja älä saata häntä murheelliseksi niinkauvan kuin hän elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Kärsi häntä, jos hän tulee lapselliseksi, ja älä katso häntä ylön, vaikka, sinä olet jalompi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Sillä mitä hyvää vanhemmille tehdään, sitä ei ikänä unohdeta; ja vaikkas olet syntinen, niin sinulle kuitenkin hyvin tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Sinun pitää tuskassa muistettaman, ja sinun syntis pitää hukkuman, niinkuin jää auringonpaisteessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Joka isänsä hylkää, pitää häväistämän, ja joka äitinsä murheelliseksi saattaa, se on kirottu Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Rakas lapsi! pysy mielelläs alammaisessa säädyssä, se on parempi kuin kaikki, jota maailma pyytää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Jota sinä olet korkiampi, sitä enempi nöyryytä sinuas, niin on Herra sinulle armias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Sillä Herra on kaikkein korkein, joka tekee suuria töitä nöyräin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Älä pyydä korkeampaa virkaa ja älä ajattele ylitse sinun voimas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Mutta mitä Jumala on sinun käskenyt, ota siitä vaari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Sillä ei se hyödytä sinua, jos sinä sitä pyydät, jota ei sinulle ole käsketty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Joka sinun virkaas ei sovi, älä siitä tottele; sillä sinulle on enempi käsketty, kuin sinä taidat toimittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Senkaltainen mieli on monta pettänyt, ja heidän ylpeytensä on heitä kukistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 27, 'Sillä joka mielellänsä an taa itseänsä vaaraan, se hukkuu siinä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 28, 'Ja ylönannetun ihmisen käy lopulla pahoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 29, 'Ylpiä ihminen tekee itsellensä paljon pahaa, ja syntinen tekee syntiä synnin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 30, 'Sillä ylpiä sydän ei tee mitään hyvää, ja ei matkaan saata muuta kuin pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 31, 'Toimellinen ihminen oppii mielellänsä Jumalan sanaa; ja joka viisautta rakastaa, se kuultelee mielellänsä. Niinkuin vesi tulen sammuttaa, niin myös anto pyyhkii synnit: Ylimmäinen kostaja on sen muistava, ja varjelee hänen vahingosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Rakas lapsi, älä köyhää hätäytä, ja älä ole kova tarvitsevaiselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Älä isoovaista katso ylön, ja älä tee murheelliseksi tarvitsevaa hänen vaivaisuudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Murheellista sydäntä älä tee enemmin murheelliseksi, ja älä viivytä lahjaa köyhältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Älä katso viheliäisen rukousta ylön, ja älä käännä kasvojas pois köyhän puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Älä käännä pois silmiäs tarvitsevalta, ettei hän sinun ylitses valittaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Sillä se, joka hänen tehnyt on, kuulee hänen rukouksensa, kuin hän murheellisella sydämellä sinun ylitses valittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Älä ole riitainen oikeuden edessä, ja pidä tuomari kunniassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Kuule köyhää mielelläs, ja vastaa häntä suloisesti ja siviästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Jolle väkivaltaa tehdään, niin auta häntä siltä, joka hänelle tekee vääryyttä; ja älä hämmästy, kun sinun pitää tuomitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Ole isättömille isä ja heidän äidillensä niinkuin perheen isäntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Niin sinä ole niinkuin kaikkein Korkeimman poika, ja hän on sinua rakastava enempi kuin sinun oma äitis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Viisaus ylentää lapsensa, ja korottaa ne, jotka häntä etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Jotka sitä rakastaa, se elämää rakastaa; ja joka häntä ahkerasti etsii. se on saava snuren ilon');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Joka siinä itsensä vahvana pitää, se on saava suuren kunniaa; jaa mitä hän aikoo, sen Herra antaa menestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Joka Jumalan sanaa kunnioittaa, se tekee oikian jumalanpalveluksen; ja joka sitä rakastaa häntä myös Herra rakastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Joka viisautta kuulee, hän taitaa muitakin ihmisiä opettaa, ja joka pitää hänen puoltansa, se saa asua levossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Joka on vilpitöin, se saa hänen, ja hänen jälkeentulevaisensa pitää menestymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Ja jos se ensin itsensä toisin käyttää häntä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Ja tekee hänelle vaivan ja ahdistuksen, ja koettelee häntä vitsallansa, ja tutkii kurituksellansa siihenasti kuin se löytää hänen vilpittömäksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Niin se tulee jälleen hänen tykönsä oikialla tiellä, ja ilahuttaa häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Ja ilmoittaa hänelle salaisuutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Mutta jos hänessä löydetään vilppi, niin se hylkää hänen, ja hänen täytyy hukkua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Rakas lapsi, ota ajasta vaari, ja vältä vääriä asioita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Älä häpee tunnustaa henkes edestä sitä mikä oikein on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Sillä ihminen taitaa niin hävetä, että hän siinä syntiä tekee, ja ihminen taitaa myös niin hävetä, että hänen siitä armo ja kunnia on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Älä anna yhdenkään sinuas kehoittaa vahinkoon, eli peljättää sinuas kadotukseen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Mutta tunnusta rohkiasti se, mikä oikein on, kuin sinun kansaa auttamaan pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Sillä tunnustuksen kautta totuus ja oikeus ilmi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Älä puhu totuutta vastaan, mutta anna häpiän tulla päälles, jos sinä viallinen olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Älä häpee tunnustaissas, jos rikkonut olet, ja älä sodi virkaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Älä tyhmää palvele hänen siassansa, ja älä katso hänen jalouttansa. Mutta vastaa totuuden puolesta kuolemaan asti, niin Herra Jumala on sotiva sinun edestäs. Älä ole niinkuin ne, jotka paljon lupaavat, ja kuitenkaan ei saa mitään aikoin. Älä ole jalopeura huoneessas ja julma perhettäs vastaan. Ei sinun kätes pidä oleman aina avoin ottamaan ja pivottu antamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Älä luota rikkautees, ja älä ajattele: minulla on kyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Älä seuraa omaa ylpeyttäs, vaikka jotakin taidat matkaan saattaa; ja älä tee, mitäs tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Älä ajattele itselläs: kuka sen minulta kieltää? sillä Herra, ylimmäinen kostaja, on sen kostava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Älä ajattele: jo minä olen ennenkin syntiä tehnyt, ja ei minulle mitään pahaa tapahtunut; sillä Herra on tosin kärsivällinen, mutta ei hän pidä sinua rankaisematta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Älä ole surutoin, Jos syntis on vielä rankaisematta, ja tahdot aina sentähden syntiä tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Älä ajattele: Jumala on ylen laupias, ei hän rankaise minua, minä teen syntiä niin paljon kuin minä tahdon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Hän taitaa niin pian olla vihainen kuin armollinenkin, ja hänen vihansa ei lakkaa jumalattomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Sentähden älä viivyttele kääntymästä Herran tykö, ja älä lykkää yhdestä päivästä toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Sillä hänen vihansa tulee nopiasti, ja kostaa sinun ja kadottaa sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Älä luota väärään kaluun; sillä ei se auta sinua, kuin kiusaukset tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Älä anna sinuas ympäri vietellä kaikkinaisilta tuulilta, älä myös jokaista tietä seuraa, niin. kuin huikentelevaiset sydämet tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Mutta ole vahva sanoissas, ja pysy yhdessä puheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Ole valmis kuulemaan ja vastaamaan, mitä oikein on, ja älä hoputa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Jos sinä asias ymmärrät, niin neuvo lähimmäistäs, jos et, niin ole ääneti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Sillä puhe saattaa kunnian, ja puhe myös saattaa häpiän, Ja oma kieli ihmisen langettaa. Älä ole panettelia, älä myös väijy kielelläs. Varas on häpiällinen, mutta panettelia ja kaksikielinen on paljo pahempi Älä mitään pidä halpana, Joko se olis vähä eli paljo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Älä tule ystäväs vihamieheksi; sillä siitä sinä saat pahan nimen, häpiän ja häväistyksen. Niin myös panetteliat tulevat viimein häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Älä itsiäs ylen viisaana pidä joka miestä nuhtelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Ettei sinun lehtes surkastu, ja sinun hedelmäs turmellu, ettäs viimein tulet niinkuin kuiva puu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Sillä senkaltainen häijy ihminen vahingoittaa itsensä, ja tulee vihamiestensä pilkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Mutta se, joka kaikki asiat parhain toimittaa. saa itsellensä monta ystävää; ja se, joka asian parhain päin puhuu, hänestä muut jälleen hyvin puhuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Pidä itses joka miehen kanssa ystävällisesti; mutta usko tuskin yhtä tuhannesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Älä usko yhtäkään ystävää, jolles ole häntä koetellut hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Sillä monta on ystävää niin kauvan kuin heidän siitä hyvää on; mutta ei he pysy vahvana hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Moni on ystävä, ja tulee pian vihamieheksi; ja jos hän tietäis murhan sinun kanssas, kyllä hän sen sanois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Muutamat ovat myös pöytäystävät, ja ei nekään pysy vahvana hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Kuin sinun käy hyvin, niin hän on sinun kumppanis, ja elää sinun huoneessas niinkuin hän siellä kotomies olis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Mutta jos sinun käy pahoin niin hän on sinua vastaan, ja ei häntä myös mistään löydetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Eroita sinus vihamiehistäs ja karta myös ystäviäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Uskollinen ystävä on vahva turva; joka sen löytää, hän löytää suuren tavaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Uskollinen ystävä ei taideta maksettaa paljolla kalulla ja rahalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 16, 'Uskollinen ystävä on elämän turva; joka Jumalaa pelkää, hän saa senkaltaisen ystävän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 17, 'Joka Jumalaa pelkää, hänellä on menestys ystäväin kanssa, ja niinkuin hän itse on, niin on myös hänen ystävänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 18, 'Rakas lapsi! anna opettaa sinulles viisautta nuoruudesta\', niin sinusta tulee viisas mies aina vanhuuteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 19, 'Suostu häneen, niinkuin se, joka kyntää ja kylvää, ja odota hänen hyviä hedelmiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 20, 'Vähä aikaa pitää sinun hänen tähtensä työtä ja vaivaa kärsimän; mutta juuri pian saat sinä nautita hänen hedelmiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 21, 'Karvas on hän niille, jotka ei ole häntä koetelleet, ja itsevaltainen ei pysy hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 22, 'Sillä se on hänelle kova koetuskivi, ja hän heittää sen pian pois tyköänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 23, 'Moni kerskaa viisaudesta, mutta vähän siitä tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 24, 'Rakas lapsi, kuule minun oppiani, ja älä katso ylön minun neuvoani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 25, 'Anna jalkas hänen kahleisiinsa, ja kaulas hänen ikeensä alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 26, 'Kallista olkas ja kanna häntä, ja älä ole hänen siteitänsä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 27, 'Pidä sinuas hänen tykönsä kaikesta sydämestä, ja pysy kaikella voimalla hänen teillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 28, 'Kysy häntä ja etsi häntä, ja niin sinä löydät hänen; ja kuin hänen saanut olet, niin älä pane häntä pois tyköäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 29, 'Sillä sinä olet lopulla saava.levon hänestä, ja sinun murhees on iloksi kääntyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 30, 'Hänen kahleensa pitää oleman sinulle vahva turva, ja hänen ikeensä kunniavaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 31, 'Hänellä on kultainen kruunu, ja hänen siteensä ovat purpurainen kaunistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 32, 'Sen kunniavaatteen pitää sinun pukeman ylles, ja sen kauniin kruunun päähäs paneman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 33, 'Rakas lapsi! jos sinä tottelet, niin sinä tulet viisaaksi, ja jos sinä panet sydämees, niin sinä tulet toimelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 34, 'Jos sinä mielelläs kuulet, niin sinä saat ymmärryksen ja jos sinä korvaa kallistat, niin sinä tulet viisaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 35, 'Ole mielelläs vanhain joukossa, ja kussa viisas mies on, niin ole hänen seurassansa. Kuule mielelläsi Jumalan sanaa ja ota vaari viisauden sananlaskuista');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 36, 'Kussas näet toimellisen miehen, niin riennä hänen tykönsä, ja käy joka paikassa. ulos ja sisälle hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 37, 'Tutki aina Jumalan käskyjä, ja muista hänen sanaansa: se vahvistaa sinun sydämes, ja antaa sinulle viisauden, jotas himoitset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Älä tee pahaa, niin ei myös sinulle pahaa tapahdu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Vältä vääryyttä, niin ei sinulle vahinkoa tapahdu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'Älä kylvä vääryyden peltoa, niin et sinä siltä seitsemänkertaisesti jälleen niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Älä tunge mihinkään virkaan Jumalan edessä, ja älä pyydä kuninkaalta valtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Älä Jumalan edessä ole olevinas hyvä siihen, älä myös kuninkaan nähden ole olevinas viisas siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Älä pyydä tuomarin virkaa; sillä et sinä voi estää vääryyttä. Taitaa tapahtua, ettäs pelkäät korkiaa, ja annat oikeuden häpiällä poljettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Älä antaudu kapinan nostajain sekaan kaupungissa, älä myös riipu kiinni yhteisessä kansassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Ettei kahtalainen syy tule sinun päälles; sillä ei kenkään pääse rankaisematta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Älä myös ajattele: Jumala ottaa sentähden minun uhrini otolliseksi');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Ja kuin minä uhraan Jumalalle, kaikkein Korkeimmalle, niin: hän ottaa sen otolliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Kuin rukoilet, niin älä epäile, älä myös ole hidas almua antamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Älä häpäise murheellista; sillä yksi on, joka taitaa alentaa ja ylentää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Älä valhetta ajattele ystävääs eli veljeäs vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Älä totuta itsiäs valheeseen; sillä se on vahingollinen tapa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Älä ole suupaltti vanhain joukossa; ja kuin rukoilet, niin älä paljon puhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Jos sinä työläästi elatukses saat peltos viljelemisestä, niin älä sitä pane pahakses; sillä Jumala on sen niin säätänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Älä luota siihen, että se joukko on suuri, jonka kanssa sinä pahaa teet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Mutta muista, ettei rangaistus ole kaukana sinusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Sentähden nöyryytä itses sydämestä; sillä tuli ja mato on kosto jumalattomille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Älä hylkää ystävääs kalun tähden ja sinun uskollista veljeäs parhaan kullan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Älä eroita sinuas toimellisesta ja hyvästä vaimosta; sillä hän on kalliimpi kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Uskollista orjaa ja hyväntahtoista työntekiää älä pidä pahoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Rakasta toimellista orjaa. ja jos hän vapaaksi tulla taitaa, niin älä estä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Jos sinulla on karjaa, niin niin holho niitä ja jos ne on tarpeelliset, niin pidä niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Jos sinulla on lapsia, niin kurita heitä, ja notkista heidän kaulansa nuoruudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Jos sinulla on tyttäriä, niin holho heidän ruumistansa, ja älä salli heille itsevaltaisuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Naita tyttäres, niin sinä olet suuren työn tehnyt, ja anna häntä toimelliselle miehelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Jos sinulla on vaimo, joka sinua rakastaa, niin älä anna sinuas hänestä kääntää pois, ja älä usko vihansuopaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Kunnioita isääs kaikesta sydämestä, ja älä unhota, kuinka rakas sinä olet ollut äidilles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Muista, että sinä olet heistä syntynyt, ja mitä sinä taidat heille siitä tehdä, mitä he sinulle tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Pelkää Herraa kaikesta sydämestäs. ja kunnioita hänen pappiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Rakasta häntä kaikesta voimastas, joka sinun tehnyt on, älä hylkää hänen palvelioitansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Pelkää Herraa ja kunnioita pappia, ja anna hänelle hänelle osansa, niinkuin sinulle käsketty on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Esikoisista ja syntiuhrista, ja ylennysuhrista, ja kaikista, jotka uhriksi pyhitetään, ja kaikista esikoisista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Ojenna köyhälle kätes, ettäs runsaasti siunatuksi tulisit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Ja sinun hyvä työs tekis: sinun otolliseksi kaikkein elävä ihmisten edessä; ja osoita myös hyvät työs kuolleiden päälle. Lohduta itkeväisiä ja murehdi murehtivaisten kanssa. Älä väsy sairaita oppimasta; sillä näiden tähden sinä rakastetaan Mitä sinä ikänä teet, niin ajattele loppua, ja niin et sinä koskaan syntiä tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Älä riitele voimallisten kanssa, ettet lankee hänen käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Älä riitele rikkaan kanssa, ettei hän tule sinulle raskaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Sillä moni antaa itsensä lahjoa rahalla, ja lahjat kääntävät kuningastenkin sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Älä riitele riitaisen kanssa, ettet kantaisi puuta hänen valkiallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Älä tee leikkiä taitamattoman kanssa, ettei hän häpiäisi sinun sukuas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Älä sen syntiä soimaa, joka itsensä parantaa; mutta muista, että me kaikki vielä nyt olemme vialliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Älä katso vanhuutta ylön; sillä me aiomme myös vanhaksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Älä iloitse vihollises kuolemasta; vaan muista, että meidän pitää myös kaikkein kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Älä katso ylön, mitä viisaat puhuvat, mutta aseta itses heidän sananlaskunsa jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Sillä sinä taidat heiltä oppia hyvää neuvoa, ja kuinka sinun ylimmäisiä toimellisesti palveleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Älä hylkää vanhain puhetta, sillä he ovat myös oppineet isiltänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Ja sinä taidat heistä oppia, kuinka sinun pitää vastaaman, kuin tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Älä viritä jumalattoman valkiaa, ettet myös sinä palaisi hänen tulensa liekistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Älä härsyttele pilkkaajaa. ettei hän sinun sanojas kääntäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Älä lainaa voimallisemmille sinua; mutta jos lainaat heille, niin pidä se kadotettuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Älä takaa ylitse voimaas; jos sinä sen teet, niin ajattele maksavas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Älä riitele tuomaria vastaan; sillä tuomio sanotaan, niinkuin hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Älä vaella ylönannetun kanssa, ettei hän saata sinua vahinkoon; sillä hän tekee, mitä hän tahtoo, ja hänen hulluutensa tähden pitää sinun vahinkoa kärsimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Älä riitele vihaisen kanssa, älä myös mene metsään yksin hänen kanssansa; sillä hän vuodattaa veren, ja ei hän sitä minään pidä; kuin ei myös sinulla ole apua, niin tappaa hän sinun. Älä pidä hullun kanssa neuvoa; sillä ei hän pane sitä sydämeensä. Älä tee vieraan nähden, mitäs salata tahtoisit; sillä et sinä tiedä, mitä siitä seuraa. Älä joka miehelle sydäntäs ilmoita; taitaa tapahtua, että sinua pahoin kiitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Älä pahoja luulottele emännästäs, joka sinulle rakas on; sillä senkaltainen luulo ei saata mitään hyvää matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Älä anna vaimolle sinun ylitses valtaa, ettei hän rupeaisi sinua hallitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Vältä porttoa, ettet tulisi hänen paulaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Älä harjoita sinuas laulajan vaimon tykö, ettei hän käsittäisi sinua liehakoitsemisellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Älä katsele piikoja, ettet heihin syttyisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Älä ryhdy porttoihin, ettet omastas pääsisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Älä kurkistele sinne ja tänne kaupungissa, ja älä juokse joka loukkaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Käännä pois kasvos kauniista vaimosta, ja älä katso muiden vaimoin kauneutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Sillä kauniit vaimot ovat monta hulluiksi tehneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Ja paha himo syttyy niinkuin tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Älä istu toisen miehen emännän tykönä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Älä myös halaa häntä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Älä pidä pitoa hänen kanssansa, ettei sinun sydämes suostuisi häneen, ja ettei sinun mieles tulisi tyhmyyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Älä hylkää vanhaa ystävää; sillä ei uusi ole hänen kaltaisensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Uusi ystävä on niinkuin uusi viina: anna hänen vanheta, niin hän hyvin sinulle maistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Älä tottele jumalatointa suuressa kunniassansa; sillä et sinä tiedä, minkä lopun hän saa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Älä mielisty jumalattomain aivoituksiin; sillä ei he tule koskaan hyväksi, ei helvettiinkään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Ole kaukana siitä, jolla on voima tappaa, niin ei sinun tarvitse peljätä, että hän sinun tappaa. Jos sinun täytyy olla hänen kanssansa, niin älä loukkaa sinuas, ettei hän ottaisi sinun henkeäs, kuin vähimmän sitä ajattelet. Tiedä, ettäs vaellat paulain keskellä, ja käyt ylhäällä korkiain tutkainten päällä. Opi kaikella vireydellä tuntemaan lähimmäistäs; ja jos sinä neuvoa tarvitset, niin etsi sitä viisailta ihmisiltä. Ja kysele toimellisilta, Ja toimita kaikki asias Jumalan sanan jälkeen. Ole hyvänlaisten ihmisten seurassa, ja ole iloinen, mutta kuitenkin Jumalan pelvossa. Työ tekiäänsä kiittää, ja toimellista päämiestä hänen työnsä. Se on vaarallinen hallitusvirassa, joka pyytää paljon puhua; ja se, joka nopsa on puhumaan, tulee häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Viisas hallitsia hallitsee hyvin kansaansa, ja kussa toimellinen esivalta on, siellä kaikki soveliaasti toimitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Niinkuin hallitsia on, niin ovat myös hänen käskyläisensä; niinkuin valtamiehet ovat, niin myös kaupungin asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Taitamatoin kuningas turmelee maan ja kansan, mutta kuin päämiehet ovat toimelllset, silloin kaupunki on hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Hallitusvirka maan päällä on Jumalan kädessä, joka hänelle toisinansa antaa kelvollisen hallitsian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Jos ihminen menestyy, se Jumalan kädestä; hän antaa myös hänelle jalon neuvonantajan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Älä lähimmäiselles kaikkea vääryyttä kosta, ja älä pyydä vihaas sammuttaa, kuin sinun pitää rankaiseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Jumala ja ihmiset vihaavat ylpeitä, sillä he tekevät väärin molempia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Väkivallan, vääryyden ja ahneuden tähden siirretään valtakunnan hallitus kansasta kansaan');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Mitä koreilet, sinä vaivainen tuhka ja multa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Joka et kuitenkaan mitään muuta ole kuin likiä loka eläissäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Ja vaikka parantajat kauvan itsensä siitä vaivaavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Niin se kuitenkin siihen loppuu: tänäpänä kuningas, huomenna kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Ja kuin ihminen on kuollut, niin madot ja toukat syövät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Siitä tulee kaikki ylpeys, kuin ihminen luopuu Jumalasta ja hänen sydämensä kääntyy Luojastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Ylpeys yllyttää kaikkein synteihin; jolla se on, se monta kauhistusta matkaan saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Sentähden on Herra antanut aina ylpeyden tulla häpiään ja on sen viimeiseltä kukistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Jumala on ylpiät päämiehet istuimelta kukistanut, ja antanut nöyräin istua heidän siassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Jumala on hävittänyt ylpiän pakanain juuret, ja on siihen siaan istuttanut nöyrät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Jumala on pakanain maan ylösalaisin kääntänyt ja peräti hävittänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Hän on antanut heidän kuivettua ja hävitä, ja on pyyhkinyt pois heidän nimensä maan päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Ei ihmiset ole luodut ylpiäksi, eikä ne tuimaksi, jotka vaimosta syntyneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Mutta joka pelkää Jumalaa, se pysyy kunnialla vahvana;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Vaan joka Jumalan käskyn rikkoo, se tulee häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Jotka Jumalaa pelkäävät, ne pitävät päämiehensä kunniassa, sentähden varjelee hän heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Ei yksikään rikas eikä köyhä, ei suuri eikä pieni, pidä muusta kerskaaman, kuin siitä, että hän pelkää Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Ei se kelpaa mitään, että ihminen toimellista köyhää ylenkatsoo, ja jumalatointa rikasta kunnioittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Päämiehet, herrat ja hallitsiat ovat suuressa kunniassa; mutta ei he ole niin suuret kuin se, joka Jumalaa pelkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Viisasta palveliaa täytyy herran palvella, ja toimellinen herra ei nurise sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Älä tee virassa oman pääs perään, ja älä ylpeile kuin sinua tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Se on parempi, että ihminen ottaa vaarin askareistansa, joilla hän itsensä auttaa, kuin se, että hän paljon aikoo, ja tulee sen kautta kerjääjäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Poikani, ole rohkia vastoinkäymisessä, ja luota virkaas. Sillä se, joka epäilee virastansa, kuka tahtoo häntä auttaa? ja kuka tahtoo häntä kunniassa pitää, joka oman virkansa häpäisee? Köyhä kunnioitetaan viisautensa tähden, ja rikas tavaransa tähden. Mutta jos viisaus on ylistettävä köyhässä, kuinka paljon ennemmin rikkaassa? Ja mitä rikkaalle pahoin sopii, se sopii köyhälle paljon pahemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Nöyrän miehen viisaus saattaa hänen kunniaan, ja istuttaa hänen päämiesten sivuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Ei sinun pidä ketään kiittämän jaloutensa tähden, eikä ketään katsoman ylön muotonsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Sillä mettinen on pieni lintu, ja antaa kuitenkin kaikkein makeimman hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Älä koreile vaatteillas, ja älä ole ylpiä kunniassas; sillä Herra on töissänsä ihmeellinen, ja ei kenkään tiedä, mitä hän tehdä tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Monen kuninkaan ja tyrannin täytyy istua maahan, ja kruunu on pantu sen päähän, jota ei ajatella taidettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Monta suurta herraa on langennut, ja jalot kuninkaat ovat muiden käsiin joutuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Älä ketään tuomitse ennen kuin sinä asian tiedät; tutki ensin ja rankaise sitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Älä tuomitse ennen kuin sinä asian kuullut olet, ja anna kansan ensin asian puhua ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Älä sekoita itsiäs toisen miehen asioihin, ja älä istu väärässä tuomiossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Poikani, älä anna itsiäs moneen asiaan; sillä jos sinä otat moninaista etees, niin et sinä siitä paljon voita. Jos sinä vielä kovin pyydät sitä, niin et sinä kuitenkaan saa, ja vaikka kuhunka sinä sinus käännät, niin et sinä siitä kuitenkaan pääse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Moni pyrkii ja pyytää rikkautta, mutta ei hän muuta saa, kuin viivyttää sillä itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Mutta moni taas hiljaksensa oleskelee, joka aina on tarvitsevainen, ja on myös heikko ja köyhä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Häntä katsoo Jumala armollisesti, ja auttaa häntä viheliäisyydestä, ja saattaa hänen kunniaan, niin että moni häntä ihmettelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Kaikki tulee Jumalalta, onni ja onnettomuus, elämä ja kuolema, köyhyys ja rikkaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Jumalisille antaa Jumala pysyväiset rikkaudet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Ja mitä hän aikoo, niin se aina menestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Moni on saita ja säästää, ja tulee sen kautta rikkaaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Luulee kyllä itsellensä kokoovansa, ja sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Nyt minä tahdon elää hyvin, syödä ja juoda minun tavarastani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Ja ei tiedä, että hetki on tullut, jona hänen pitää kaikki muille jättämän, ja kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Pysy Jumalan sanassa, ja harjoita itses siinä, ja pysy virassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Älä tottele, kuinka jumalattomat kalua pyytävät: turvaa sinä Jumalaan, ja pysy virassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Sillä se on Herran edessä huokia äkisti köyhän rikkaaksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Jumala siunaa hyväin tavaran, ja kuin aika tulee, niin he äkisti kostuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Älä sano: mitä se auttaa minua, ja mitä nyt minun siitä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Älä sano: minulla on kyllä, kuinka minulta taitaa jotakin puuttua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'Kuin sinun hyvin käy, niin ajattele, että sinun taitaa myös pahoin käydä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Ja kuin sinun pahoin käy, niin ajattele, että sinun taitaa myös hyvin käydä; sillä Herra taitaa jokaiselle kostaa kuolemassa niinkuin ansaittu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Paha hetki tekee, että ihminen kaiken ilonsa unohtaa, ja kuin ihminen kuolee, niin hän saa tietää, kuinka hän on elänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Sen tähden ei sinun pidä ketään ennen loppua kiittämän; millainen hän on ollut, se löydetään hänen jääneidensä tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 31, 'Älä joka miestä ota huoneeses; sillä maailma on täynnä viekkautta ja petosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 32, 'Petollinen sydän on niin. kuin houkutella lintu satimessa, ja vartioitsee sitä, kuinka hän taitais sinun ottaa kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 33, 'Sillä se hyvä, minkä hän näkee, sen hän kääntää pahemmaksi, ja sitä, mikä kaikkein paras on, hän enimmän laittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 34, 'Kipinästä tulee suuri tuli. ja jumalatoin ei lakkaa ennenkuin hän verta vuodattaa. Vältä senkaltaisia pahanjuonisia; ei ole heillä hyvää sydämessä, ettei he saata sinulle ijäistä häpiää. Jos sinä otat muukalaisen tykös, niin hän tekee sinun rauhattomaksi ja karkottaa sinun omaisuudestas pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Jos siis tahdot hyvää tehdä, niin katso, kenelle teet, niin sinä saat kiitoksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Tee hyvää jumaliselle, niin se sinulle runsaasti maksetaan jälleen, jos ei häneltä, niin kuitenkin totisesti Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Mutta pahanjuonisille, jotka ei hyvän työn edestä kiitä, ei pidä, hyvin käymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Anna jumaliselle, ja älä jumalatointa armahda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Tee hyvää vaivaiselle, mutta älä jumalattomalle anna mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Pidä itse leipäs, ja älä anna hänelle, ettei hän siitä vahvistu ja tallaa sinua allensa; hän tekee sinulle niin paljon pahaa, kuin sinäkin olet hänelle hyvää tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Sillä kaikkein Korkein vihaa jumalatointa, ja tahtoo häntä rangaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Kuin hyvin käy, niin ei taideta ystävää oikein tuta; mutta kuin pahoin käy, niin ei vihansuopa taida itsiänsä salata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Sillä kuin hyvin käy, niin vihansuopa kadehtii sitä; mutta jos pahoin käy, niin ystävät myös luopuvat pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Älä vihamiestäs ikänä usko. Sillä niinkuin rauta taitaa jälleen ruostua, niiu ei hän myös lakkaa pahuudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Jos hän vielä kumartelee ja lyykistää, niin pidä kuitenkin vaaris ja karta häntä; jos sinä hänen kirkastat niinkuin peilin, niin hän kuitenkin ruostuu jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Älä ota häntä tykös, ettei hän sinua aja pois, ja astu sialles. Älä häntä vierees istuta, ettei hän rupee sinun istuintas pyytämään, ja sinä muistat viimein minun sanani ja kadut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Niinkuin koska mato pistää lumoojansa, ei häntä kenkään armahda; niinkuin myös koska joku petoin kanssa seuraa pitää ja niiltä revitään, juuri niin myös sille käy, joka suostuu jumalattomaan, ja sekoittaa itsensä hänen syntiinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Kyllä hän hetken pysyy sinun tykönäs; mutta jos sinä kompastut, niin ei hän odota sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Vihamies antaa hyviä sanoja, ja valittaa sinua, ja on olevinansa sinun ystäväs, taitaa myös itkeä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Mutta sydämessänsä ajattelee hän, kuinka hän sinun hautaan langettais, ja jos hän saa tilan, niin ei hän taida tulla ravituksi sinun verestäs. Jos joku tahtoo vahingoittaa sinua, niin on hän ensimäinen: hän on tahtovinansa auttaa sinua, ja kuitenkin sinun salaisesti lykkää maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Hän vääntää päätänsä ja nauraa salaisesti, pitittää sinua ja suutansa ammottelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Joka tervaan rupee, se saastuttaa itsensä, ja joka antaa itsensä ylpiäin seuraan, se oppii ylpiäksi');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Älä anna itsiäs voimallisen ja rikkaan seuraan; muutoin sinä otat raskaan kuorman päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Mitä on saviastia vaskipadan tykönä? Sillä jos he loukkaavat toinen toistansa, niin se rikkoutuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Rikas tekee vääryyttä ja öykkää sitä; mutta köyhän täytyy kärsiä, ja päälliseksi kiittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'Niinkauvan kuin hänellä on sinusta hyvää, niin hän tahtoo sinua; mutta kuin et sinä enää voi, niin hän hylkää sinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Niinkauvan kuin sinulla on jotakin, niin hän nautitsee sinun kanssas; mutta jos sinä häviät, niin ei hän sitä tottele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Kuin hän sinua tarvitsee, niin hän taitaa kyllä suositella sinua ja nauraa sinulle, lupaa sinulle paljon, antaa hyviä sanoja, ja sanoo: tarvitsetkos mitään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Ja kutsuu sinut petollisesta sydämestä vieraaksensa, kahdesti eli kolmasti, niinkauvan kuin hän saa sinun omas sinulta pois;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Mutta viimeiseltä häpäisee hän sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Ja jos hän näkee sinun hätäs, niin hän laskee sinun menemään ja vääntelee päätänsä sinun päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Ota sentähden vaari, ettei sinun yksinkertaisuutes petä sinua, ja saata sinua vahinkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Jos voimallinen tahtoo vetää sinua tykönsä, niin kiellä, ja hän vetää sitä enemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Älä tunge sinuas hänen tykönsä, ettet ajettaisi pois; älä myös sinuas ylen kauvas siirrä, että sinua tarpeen aikana nautita saataisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Älä kiellä, jos hän sinun jotakin käskee; mutta älä luota häneen, vaikka hän on ystävällinen sinun kanssas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Sillä hän koettelee sinua, ja tutkii sinua suloisella käyttämisellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Kuin hän sinulle vihastuu, niin ei hän enää pidä ystävällistä puhetta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Eikä tee leikkiä rangaistuksella ja vankiudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Ota sentähden vaari, ja katso hyvin etees; sillä sinä elät suuressa vaarassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Jokainen eläin rakastaa vertaistansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Niin myös jokainen ihminen pitää vertaisensa tykö itsensä pitämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Se on juuri niinkuin susi menis lammasten joukkoon, kuin jumalatoin tulee jumalisten seuraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Niinkuin hyena antaa itsensä koiran seuraan, niin tekee rikas köyhän kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Niinkuin jalopeura syö metsäaasin korvessa, niin myös rikkaat syövät köyhiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Niinkuin ylpiä suuttuu nöyrään, niin myös rikas suuttuu köyhään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Kuin rikas lankee, niin hänen ystävänsä auttavat häntä ylös; mutta kuin köyhä lankee, lykkäävät hänen ystävänsä häntä perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Kuin rikas tekee väärin, niin on monta häntä auttamassa, ja kuin hän puhuu väärin, niin se annetaan olla niinkuin se oikein olis. Mutta jos köyhä osaa tehdä väärin, niin se punnitaan ylen tarkasti; ja vaikka hän vielä viisaasti puhuis, niin ei se kuitenkaan löydä siaansa. Kuin rikas puhuu, niin kaikki vaikenevat, ja korottavat hänen puheensa taivaasen asti; Mutta jos köyhä puhuu, niin he sanovat: kuka tämä on ja jos hän jotakin horjahtaa, niin hänelle pahoin kostetaan. Rikkaus on tosin hyvä, kuin se ilman syntiä nautitaan; mutta jumalattoman köyhyys opettaa hänen paljon pahaa puhumaan. Mitä ihmisen sydämessä on, se nähdään hänen silmistänsä, olkoon se paha eli hyvä. Jos hyvää on hänen mielessänsä, niin hän katsoo suloisesti; Mutta jolla on pahaa sydämessä, ei sillä ole lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Autuas on se, joka ei anna pahaa neuvoa., ja ei hänellä ole pahaa tuntoa siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Autuas on se, jolla ei ole pahaa tuntoa, ja ei hänen toivonsa ole turha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Saidan ei sovi rikkaan olla, ja miksi kalu ja raha olis saidalle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Joka paljon kokoo, ja ei tee itsellensä siitä hyvää, hän kokoo muille., ja muut pitää sen tuhlaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Joka ei tee itsellensä hyvää., kuinka hän taitaa muille hyvää tehdä? Ei hänellä ole ikänä iloa kaluistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Ei ole yhtäkään pahempaa kuin se on, koska ei ihminen suo itsellensä hyvää, ja se on oikia rangaistus hänen pahuutensa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Jos hän jotakin hyvää tekee, niin ei hän ymmärrä sitä, ja hän tulee viimein sentähden kirriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'Se on paha ihminen, joka ei suo ihmisille hyvää tehtävän, mutta kääntää kasvonsa pois ja ei armahda ketään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Ei ahne ihminen ikänä tyydy osaansa., eikä taida ahneuden tähden menestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Ei saita tahdo mielellänsä, että ihminen söis, ja se tekee hänen pahaa, että hänen ruokaa antaman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Poikani. tee omastas itselles hyvää, ja anna Herralle uhri niin paljo kuin hänelle tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Muista, ettei kuolema viivyttele, ja sinä kyllä tiedät, mikä liitto sinulla on kuoleman kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Tee ystävilles hyvää ennen loppuas, ja anna köyhälle varasi jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Älä unohda köyhää, kuin sinulla on iloinen päivä, niin sinulle myös ilo tapahtuu, jotas halajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Sinun täytyy kuitenkin vaivaloisen hikes muille jättää, ja sinun työs perillisille antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Anna mielelläs, niin sinulle myös annetaan, ja pyhitä sinun sielus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Sillä kuin sinä kuollut olet, niin on se kaikki pois kulutettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Kaikki liha kuluu pois niinkuin vaate, sillä se on vanha liitto: sinun pitää kuoleman');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Niinkuin tapahtuu viheriäisen lehden kanssa kauniissa puussa: muutamat putoovat pois, muutamat kasvavat jälleen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Niin myös tapahtuu ihmisten kanssa: muutamat kuolevat ja muutamat syntyvät jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Kaikki turmellut kappaleet saavat lopun, ja ne, jotka niissä ovat, myös hukkuvat ynnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Autuas on, joka aina Jumalan sanaa rakastaa, ja sitä selittää ja opettaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Tutkii sitä sydämessänsä ja oppii oikein ymmärtämään, ja etsii enemmin ja enemmin viisautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Ja rientää sen jälkeen, ehkä kuhunka se menee, kurkistelee hänen akkunassansa, Ja kuultelee hänen ovensa edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Pyytää majaa lähes hänen huonettansa, ja asettaa majansa hänen seinänsä tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Joka hänelle on hyvä asuinsija; hän panee lapsensa hänen suojaansa, ja hänen oksainsa alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Sen alla hän varjellaan palavuudelta ja siellä on hänelle kaunis asuinsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Joka Herraa pelkää, se tekee hyvää, ja joka itsensä pitää Jumalan sanassa, se löytää viisauden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Ja hän kohtaa häntä niinkuin äiti, ja ottaa hänen vastaan niinkuin kihlattu morsian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Hän ravitsee hänen ymmärryksen leivällä, ja antaa hänen viisauden vettä juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Siitä hän vahvistuu, että hän taitaa vahvana olla; hän pitää itsensä sen tykö, ettei hän tule häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Se ylentää hänen lähimmäisensä ylitse, ja avaa hänen suunsa seurakunnassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Kruunaa hänen ilolla ja riemulla, ja lahjoittaa hänen ijankaikkisella nimellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Mutta ei tomppelit löydä sitä, ja ei jumalattomat saa nähdä sitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Sillä se on ylpeistä kaukana, ja ei ulkokullatut tiedä mitään siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Ei jumalatoin taida oikein, opettaa; sillä ei se tule Jumalalta. Grekan tekstin jälkeen kuuluu tämä värsy näin: Ei ole kiitos kaunis syntisen suussa, sillä ei se ole lähetetty Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Oikiassa opissa tarvitaan viisaus, ja Jumala antaa siihen armonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Ei sinun pidä sanoman: jos minä olen opettanut väärin, niin sen on Jumala tehnyt; sillä jota hän vihaa, sitä ei pitäisi sinun tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Ei sinun pidä sanoman: jos minä olen opettanut väärin, niin hän on minun pettänyt; sillä ei hän tarvitse jumalatointa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Sillä Herra vihaa kaikkea epäjumalan palvelusta, ja se, joka häntä pelkää, välttää sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Hän loi ihmisen alusta ja antoi hänelle ehdon:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Jos sinä tahdot, niin pidä käskyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Ja tee hyvässä uskalluksessa sitä, mikä hänelle kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Hän pani tulen ja veden sinun etees; ota, kumman sinä tahdot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Ihmisen edessä on elämä ja kuolema; kumman hän tahtoo, se hänelle annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Sillä Jumalan viisaus on suuri, hän on sangen voimallinen, ja näkee kaikki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Ja hänen silmänsä katsovat niitä, jotka häntä pelkäävät; hän tietää kyllä, mikä oikein on tehty, ja mikä ulkokullaisuus on. Ei hän käske yhdenkään olla jumalattoman, eikä anna kenellekään lupaa syntiä tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Älä iloitse, että sinulla on monta hillimätöintä lasta, ja älä luota itsiäs siihen, että sinulla on monta lasta, jos ei he pelkää Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Älä luota heihin, älä myös uskalla heidän varaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Sillä parempi on yksi hyvä lapsi, kuin tuhannen jumalatointa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Ja parempi on kuolla lapsetoinna, kuin että olis jumalattomia lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Hyvänlainen mies taitaa kaupunkia auttaa; mutta vaikka monta olis jumalatointa, niin ne kuitenkin hänen hävittävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Siitä olen minä elinaikanani paljon nähnyt, ja vielä enemmän kuullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Tuli poltti kaiken jumalattoman joukon, ja viha sattui jumalattomiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Ei hän säästänyt vanhoja sankareita, jotka hukkuivat väkevyydessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Ei hän niitäkään säästänyt, joiden tykönä Lot muukalainen oli, mutta kadotti heitä heidän sydämensä koreuden tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Ja hävitti kaiken sen maakunnan armottomasti, jonka he synneillänsä täyttäneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Niin hän myös hukutti kuusisataa tuhatta, että he olivat kovakorvaiset; kuinka hän siis pitäis kovakorvaisen rankaisematta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Hän on tosin laupias, mutta hän on myös vihainen. Hän leppyy kyllä, mutta hän rankaisee myös kauhiasti. Niin suuri kuin hänen laupiutensa on, niin suuri on myös hänen rangaistuksensa, ja hän tuomitsee jokaisen ansionsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Jumalattoman ei pidä vääryytensä kanssa pääsemän rankaisematta, ja hyvän toivo ei pidä turha oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Jokainen hyvä työ pitää siansa löytämän, ja kullekin pitää tapahtuman ansionsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Älä sano: ei Herra katsele minua; kuka kysyy minua taivaassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Ei hän muista minua niin suuressa joukossa; mitä minä olen suuren maailman suhteen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Sillä katso, taivas, meri ja maa vapisevat, vuoret ja ja laaksot värisevät, kuin hän niitä etsii:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Eikö siis hänen pitäis näkemän sinun sydäntäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Mutta mitä hän tehdä tahtoo, sitä ei yksikään näe, ja tuulta, joka on hänen kädessänsä, ei näe yksikään ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Hän taitaa paljon tehdä, jota ei kenkään näe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Ja kuka taitaa puhua ja kärsiä, kuin hän tuomitsee? Mutta senkaltainen vaatimus on kaukana silmäin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Kuin tyhmä ihminen sen kuulee, niin hän kuitenkin pysyy hulluudessansa ja erehdyksessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Poikani, kuule minua, opi viisautta, ja tottele minun sanaani täydellä todella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Minä tahdon antaa sinulle totisen opin, ja neuvon sinua selkiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Jumala on alusta työnsä hyvin asettanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Ja antanut heille jokaiselle oman työnsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Ja pitää heitä ijäti senkaltaisessa järjestyksessä, että he aina virkansa toimittavat, ja ei yksi estä toista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Mutta ovat aina hänen käskyllensä kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Vielä sitte on hän myös katsonut maan päälle, ja on sen hyvyydellänsä täyttänyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Ja täytti maan eläimillä, jotka maaksi jälleen tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Jumala loi ihmisen maasta., ja teki hänen jälleen maaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Ja määräsi heille heidän elinaikansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Ja loi heidät molemmat, ja antoi luontonsa kummallekin, ja teki heitä omaksi kuvaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Hän antoi kaiken lihan heitä peljätä, ja että heidän piti hallitseman kaikkia eläimiä ja lintuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Hän antoi heille järjen, puheen, silmät, korvat, ymmärryksen ja tunnon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Ja osoitti heille sekä pahan että hyvän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Hän katsoi heidän puoleensa erinomaisesti muiden eläinten suhteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Osoittaaksensa heille suuren majesteettinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Hän opetti heitä, ja antoi heille elämän lain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Hän teki heidän kanssansa ijankaikkisen liiton, ja ilmoitti oikeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'He näkivät silmillänsä hänen majesteettinsa, ja kuulivat hänen julkisen äänensä korvillansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Ja hän sanoi heille: karttakaat kaikkea vääryyttä! ja antoi myös jokaiselle käskyn lähimmäisestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Heidän menonsa on joka paikassa hänen edessänsä, ja ei ole mitään salattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Jokaiseen maakuntaan asetti hän hallitsian;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Mutta itse on hän Israelin Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Kaikki heidän tekonsa ovat julki hänen edessänsä niinkuin aurinko, ja hänen silmänsä näkevät lakkaamatta kaikkein heidän menonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Kaikki heidän pahuutensa on ilmi hänen edessänsä, ja kaikki heidän syntinsä ovat julki hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Hän kätkee ihmisten hyvät työt niinkuin sinettisormuksen, ja hyvät teot niinkuin silmäterän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Viimeiseltä herää hän, ja kostaa jokaisen pään päälle, niinkuin hän on ansainnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Mutta jotka parantavat itsensä, ne antaa hän tulla armoihin, ja niitä, jotka väsyneet ovat, lohduttaa hän, ettei he epäilisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Niin käännä siis nyt sinuas Herran tykö, ja hylkää syntinen elämäs;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Rukoile Herraa ja lakkaa pahasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Pidä sinuas Korkeimman tykö, eriä vääryydestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Ja vihaa epäjumalanpalvelusta totuudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Kuka tahtoo Korkeinta kiittää helvetissä; sillä elävät taitavat ainoasti kiittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Kuolleet, jotka ei silleen ole, ei taida kiittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Sentähden kiitä Herraa niinkauvan kuin sinä elät ja terveenä olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Oi kuinka suuri on Herran laupius! Hän on kaikille armollinen. jotka kääntyvät hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Sillä mikä taitaa ihminen olla, ettei hän ole kuolematoin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Mikä on kirkkaampi aurinkoa, jonka kuitenkin täytyy hukkua? Ja mitä liha ja veri ajattelee, se on paha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Hän näkee mittaamattoman taivaan korkeuden; mutta kaikki ihmiset ovat tuhka ja multa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Mutta se, joka elää ijankaikkisesti, kaikki, mitä hän tekee, se on täydellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Herra on yksinänsä vanhurskas; ei taida kenkään puhua ulos hänen töitänsä..');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Kuka voi käsittää hänen suuret ihmeensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Kuka taitaa mitata hänen suuren voimansa? Kuka taitaa luetella hänen suuren laupiutensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Ei ihminen taida sitä vähentää eikä enentää, ja hänen suuria ihmeitänsä ei taida hän käsittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Mutta ihminen kuin hän parhaansa tehnyt on, niin on se tuskin aljettu; ja kuin hän luulee sen päättäneensä, silloin vielä paljo puuttuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Sillä mikä on ihminen? mihinkä hän kelpaa? mitä hän taitaa auttaa eli vahingoittaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Jos hän kauvan elää, niin hän elää sata ajastaikaa. Niinkuin pisara vettä on koko merta vastaan, ja niinkuin sannan hiekka on meren santaa vastaan: niin harvat ovat hänen vuotensa ijankaikkisuuden suhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Sentähden kärsii Jumala heitä, ja vuodattaa laupiutensa heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Hän näkee kyllä ja tietää, kuinka he kaikki ovat kuoleman omat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Sentähden hän armahtaa heitä sitä runsaammin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Ihmisen laupius ulottuu ainoastaan lähimmäisellensä, mutta Jumalan laupius käy kaiken maailman ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Hän kurittaa ja rankaisee,.hän opettaa ja kaitsee, niinkuin paimen laumaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Hän armahtaa kaikkia niitä, jotka itsensä opettaa antavat ja ahkerasti kuulevat Jumalan sanaa..');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Poikani! kuin jonkun hyvää teet, niin älä nurise, ja kuin jotakin annat, niin älä tee häntä murheelliseksi kovilla sanoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Kaste palavuuden jäähdyttää, niin myös hyvä sana on parempi kuin lahja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Ja yksi sana on toisinansa parempi kuin suuri lahja; ja toimellinen ihminen antaa ne molemmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Mutta tyhmä soimaa toista hävyttömästi, ja ylönmielinen lahja ei ole otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Opi ensin itse, ennenkuin sinä muita opetat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Auta ensin itsiäs, ennenkuin sinä muita autat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Nuhtele ensin itsiäs, ennenkuin sinä muita tuomitset, niin sinä löydät armon, kuin muita rangaistaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Älä viivytä katumustas siihen asti kuin sinä sairaaksi tulet, mutta paranna sinus, kuin vielä syntiä tehdä taidat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Älä viivytä hyväksi tulla, ja älä viivytä katumustas kuolemaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Ja jos sinä tahdot Jumalaa palvella, niin tee se vilpittömästi, ettet kiusaisi Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Muista sitä vihaa, joka lopulla on tuleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Sillä kuin ihminen ravittu on, niin muistakaan, että hän jälleen isoaa; ja kuin ihminen rikas on, niin ajatelkaan, että hän jälleen köyhäksi tulla taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Sillä ehtoona taitaa toisin olla kuin aamulla oli, ja kaikki nämät äkisti Jumalan edessä tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Viisas ihminen pitää näissä kaikissa vaarinsa ja välttää syntiä, kuin hän vielä syntiä tehdä taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 29, 'Joka toimellinen on, hän ottaa senkaltaisen viisauden tykönsä ja joka sen saa, hän kiittää sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 30, 'Joka sen opin oikein oppinut on, se taitaa visusti itsensä käyttää, ja hyvin siitä puhua parannukseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 31, 'Älä seuraa pahaa himoas, mutta käännä pois sinun tahtos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 32, 'Sillä jos sinä seuraat pahaa himoas, niin sinä saatat itses vihamiestes pilkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 33, 'Älä ole tuhlaaja, älä myös harjoita sinuas tuhlaamaan, ettet tulisi kerjääjäksi. Ja kuin ei sinulla ole silleen rahaa kukkarossa, niin sinun täytyy kasvulle lainaksi ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Juomari työmies ei rikastu, ja joka ei vähääkään kätke, se enemmin ja enemmin häviää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Viina ja vaimot tekevät viisaat miehet hulluiksi, ja ne, jotka porttoin kanssa yhteyttä pitävät, tulevat mielipuoliksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Koi ja mato on heidän palkkansa, ja he kuivettuvat muille julkiseksi opiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Joka pikaisesti uskoo, se on köykäinen, ja kuin hän antaa hänensä vietellä, niin hän vahingoittaa itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Joka koiruudestansa iloitsee, se tulee ylönkatsotuksi; mutta joka vihaa kelvottomia panettelioita, se varjelee itsensä vahingosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Jos sinä jotakin pahaa kuulet, niin älä sano sitä; sillä vaiti olla ei vahingoitse ketään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Ei sinun pidä sanoman ystävälle eikä vihamiehelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Älä myös ilmoita sitä, jos sinä sen taidat tehdä ilman pahaa omaatuntoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Sillä kyllä sinua kuunnellaan ja otetaan vaari sinun puheestas, ja kuitenkin sinua sentähden vihataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Jos sinä olet jotakin kuullut, niin anna sen kuolla sinussas, niin sinulla on levollinen sydän, ja et sinä sentähden kahtia pakahdu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Mutta tyhmä tahtoo sen kanssa ulos, niinkuin täysiaikainen lapsi tahtoo ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Kuin tyhmä sanankin kuulee, niin se on niinkuin nuoli istuis kiinni hänen reidessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'llmoita sitä lähimmäiselles, mitämaks ettei hän ole sitä tehnyt; mutta jos hän on sen tehnyt, ettei hän sitä enään tekisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Puhu siitä ystävälles: sillä kyllä paljo ihmisten päälle valhetellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Älä siis usko kaikkea, mitäs kuulet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Toisinansa pääsee ihmiseltä sana tapaturmasta, jonka hän toisin ymmärtää; sillä kuka on se, joka ei toisinansakaan sanoissansa eksy?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Puhu siitä lähimmäiselle, ennenkuin sinä riitelet hänen kanssansa, ja muista Jumalan käskyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Sillä Jumalan pelko tekee ihmisen itsensä kaikissa asioissa visusti käyttämään, ja Jumalan käsky opettaa kaikki asiat toimellisesti tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Kavaluus ei ole viisaus, ja jumalattomain petos ei ole toimellisuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Mutta se on pahuus ja epäjumalan palvelus, ja on kaikki hulluus ja tyhmyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Parempi on vähä ymmärrys Jumalan pelvossa, kuin suuri ymmärrys Jumalan ylönkatseen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Moni in tarkka ymmärryksestä, ja on kuitenkin pahanjuoninen, ja taitaa vääntää asian, kuhunka hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Hän kallistaa päänsä, ja katsoo yksivakaisesti, ja on kuitenkin kaikki petos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Hän laskee silmänsä alas, ja kuultelee korvillansa, ja jos et sinä ota vaaria, niin hän sinun pettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Ja jos hän on heikko sinua vahingoittamaan, ei hän kuitenkaan tottele sitä, jos hän tilansa näkee, niin hän tekee pahaa; kyllä se hänestä nähdään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Toimellinen mies havaitaan käyttämisestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Sillä hänen vaatteensa, naurunsa ja käymisensä ilmoittavat hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Ihminen nuhtelee usein lähimmäistänsä sopimattomalla ajalla, ja tekis viisaammin, jos hän olis vaiti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Parempi on julki nuhdella, kuin salaa vihata; ja jolle se kelpaa, niin se tulee hänelle hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Joka väkivaltaa tekee oikeudessa, hän on niinkuin se huoneenvartia, joka sen neitseen häpäisee, jota hänen piti varjeleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Muutamat ovat ääneti, ettei he taida edestänsä vastata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Muutamat ovat vaiti ja odottavat aikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Viisas on siihenasti ääneti kuin hän aikansa näkee, mutta rohkia tyhmä ei taida odottaa aikaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Joka suupaltti on, hän suututtaa ihmiset itseensä, ja joka paljon valtaa ottaa itsellensä, häntä vihataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Monelle käy pahassa asiassa myöten, mutta se tapahtuu hänelle vahingoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Moni antaa usein, ja ei hän siitä hyödy; mutta sitä vastaan moni myös antaa, joka hänelle tulee parhaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Joka paljon koreilee, se saa siitä vahingon; mutta joka itsensä alentaa, se ylennetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Moni ensin ostaa halvasti, mutta sitte maksaa sen kalliisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Viisas tekee lahjansa otolliseksi suloisella sanalla; mutta mitä tyhmät antavat, sen he itse tekevät kelvottomaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Ei tyhmän lahja tule paljo sinun hyväkses; sillä yhdellä silmällä hän antaa, mutta seitsemällä silmällä hän katsoo, mitä hänen siitä jälleen saaman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Hän antaa vähän ja sanoo paljon antaneensa, ja huutaa siitä niinkuin viinanlaskia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Tänäpänä hän lainaa ja huomenna tahtoo jälleen. Nämät ovat ne ihmiset, joita ei voida kärsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Tyhmä valittaa; ei yksikään ole minulle uskollinen, ei kenkään kiitä minua hyvästä työstä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Ja jotka minun leipääni syövät, ei puhu minusta hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Oi kuinka usein ja monelta hän häväistään!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'senkaltainen puhe tekee hänelle pahempaa kuin jos hän putois alas korkiasta huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Juuri niin tapahtuu pahoille, joiden viimein äkisti lankeeman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Häpeemättömällä ihmisellä on suuri suu, hän puhuu ajattelematta kaikki, mikä hänen mieleensä joutuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Vaikka tyhmä jotakin hyvää puhuis, ei se kuitenkaan kelpaa; sillä ei hän sitä puhu oikialla ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Köyhyys estää monta pahaa tekemästä; siitä on hänellä se voitto,, ettei hänellä ole paha tunto');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Moni tekee ennen pahaa kuin hän hukkais kunniansa, ja tekee sitä jumalattoman ihmisen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Moni palvelee toista väärässä asiassa, ja saattaa niin hänen vihamieheksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Valhe on suuri häpiä ihmiselle, ja se löydetään enimmästi pahain ihmisten tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Ei varas ole niin paha kuin valehtelia; mutta viimeiseltä he molemmin vahinkoon tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Valhe on ihmiselle häpiällinen, ja eihän tule ikänä kunniaan');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Viisas mies kunnioittaa itsensä viisaalla puheellansa, ja toimellisesta miehestä päämiehet paljon pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Joka peltonsa hyvin rakentaa, hän täyttää salvonsa; ja joka itsensä pitää päämiesten tykö, niin, että hän heille kelpaa, se taitaa paljon pahaa estää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Antimet ja lahjat sokaisevat viisaat ja panevat suitset heidän suuhunsa, ettei he taida rangaista. Kätketty viisaus ja salattu tavara, mihinkä ne molemmat kelpaavat? Parempi on se ihminen, joka tyhmyytensä kätkee, kuin se, joka viisautensa kätkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Poikani, jos sinä olet syntiä tehnyt, niin lakkaa, ja rukoile, että ennen tehty sinulle annettaisiin anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Pakene syntiä niinkuin kärmettä; sillä jos sinä tulet häntä lähes, niin hän puree sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Hänen hampaansa ovat niinkuin jalopeuran hampaat ja tappavat ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Jokainen synti on niinkuin kaksiteräinen miekka, ja tekee senkaltaisen haavan, jota ei kenkään parantaa taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Joka väkivaltaa ja vääryyttä tekee, se tulee viimein kerjääjäksi; ja se joka ylpiä on, se tulee viimeiseltä pois huoneestansa ja talostansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Sillä kuin raadollinen huutaa, niin Jumala kuulee, ja kosto tulee nopiasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Joka ei salli neuvoa itsiänsä, hän on jo parhaallansa jumalattoman tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Joka Jumalaa pelkää, se taittaa itsensä, mutta joka niskuri on, sen Jumala taampaa näkee, ja taitava havaitsee hänen hukkuvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Joka huoneensa rakentaa toisen miehen rahalla, se kokoo kiviä haudaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Jumalattomain joukko on niinkuin rohtimet, jotka tulella pitää poltettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Jumalattomat käyvät tosin tasaista tietä, jonka loppu on helvetin syvyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Joka Jumalan käskyt pitää, ei hän seuraa omaa päätänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Peljätä yksitotisesti Jumalaa on viisaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Kussa ei järkeä ole, ei siellä oteta oppia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Muutamat ovat kyllä toimelliset, mutta he matkaan saattavat sillä paljon pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Viisaan miehen oppi vuotaa niinkuin virta ja niinkuin elävä lähde.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Tyhmäin sydän on niinkuin vuotava astia, ja ei taida pitää oppia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Kuin toimellinen kuulee hyvän opin, niin hän kiittää sitä. ja levittelee häntä; mutta jos tyhmä sen kuulee, niin ei se kelpaa hänelle, ja hän heittää sen selkänsä taa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Tyhmän puhe painaa niin kuin taakka tien päällä; mutta kuin viisas puhuu, se on suloinen kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Neuvon pitämisestä otetaan vaari viisaan puheesta, ja mitä hän neuvoo, se on seisovainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Tyhmän puhe on niinkuin kaatunut huone, ja taitamattoman neuvosta ei tiedä kenkään mitään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Kuin joku tahtoo neuvoa tyhmää, niin hän asettaa itsensä niinkuin joku tahtois sitoa hänen kätensä ja jalkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Mutta viisas lukee sen itsellensä kultaiseksi kaunistukseksi ja rannerenkaaksi oikiassa kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Tyhmä juoksee rohkiasti toisen huoneesen, mutta toimellinen pitää suuren eroituksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Tyhmä kurkistelee rohkiasti toisen akkunasta, mutta toimellinen seisoo ulkona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Tyhmä kuultelee oven takana, mutta toimellinen pitää sen häpiänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Paljopuhuvaiset sanovat paljon sitä, mikä ei sovi asiaan; mutta viisaat punnitsevat sanansa kultavaa\'alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Tyhmäin sydän on suussa, mutta viisasten suu on sydämessä. Tyhmä nauraa korkiasti, mutta viisas nauraa kohtuullisesti. Kuin jumalatoin kiroilee pahaa, silloin hän kiroilee itsiänsä. Korvankuiskuttelia vahingoitsee itsensä, ja ei kenkään pidä häntä mielellänsä tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Laiska ihminen on niinkuin kivi, joka loassa makaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Joka sen ottaa ylös, hänen pitää sitte kätensä pyyhkimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Hävytöin poika on isällensä häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Toimellinen tytär kyllä naidaan, mutta pahantapainen tytär annetaan olla, ja hän saattaa isänsä murheelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Joka ylen rohkia on, hän on sekä isällensä, että miehellensä häpiäksi, ja heiltä molemmilta vihataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Puhe, joka sopimattomaan aikaan puhutaan, on niinkuin harpun soitto murheelliselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Oikialla ajalla pitää ihmisiä kuritettaman ja opetettaman; mutta joka tyhmää opettaa, se tahtoo liittää rikotun saviastian kappaleita, ja tekee niinkuin se, joka jonkun raskaasta unesta herättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Joka tyhmää puhuttelee, hän puhuu makaavan kanssa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Kuin se on loppunut, niin hän kysyy: mikä se on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Kuollutta itketään, ettei hänellä enää ole valkeutta; mutta tyhmää pitää sinun itkemän, ettei hänellä ole ymmärrystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Ei ihmisen pidä ylen paljon kuolleita itkemän, sillä he ovat lepoon tulleet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Mutta tyhmän elämä on pahempi kuin kuolema.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Seitsemän päivää kuollutta itketään, mutta tyhmää ja jumalatointa koko hänen elinaikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Älä tyhmän kanssa paljon puhu, älä myös ole taitamattomain seurassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Väitä häntä, ettet tulisi tuskaan hänen kanssansa, ja tahratuksi hänen saastaisuudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Pakene häntä, niin sinä olet rauhassa, ja et tule ahdistukseen ja hätään hänen tyhmyytensä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Mikä on raskaampi lyijyä? Ja kuinka pitää ihmisen kutsuman tyhmää muuksi kuin lyijyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Keveämpi on kantaa santaa, suolaa ja rantaa, kuin taitamatointa ihmistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Niinkuin huone, joka toisen huoneen kanssa on vahvasti sidottu yhteen, ei tuulispäätä kukisteta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Niin myös se sydän, joka asiansa hyvin tietää, ei pelkää yhtään peljätystä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Niinkuin kauniisti kalkilla sivuttu tasainen seinä ei pysy sateessa kauniina, eli aita korkealla tuulen edessä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Niin myös tyhmän sydämen huono aivoitus ei ole seisovainen peljätystä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Jos ihminen silmäänsä painottelee, niin siitä kyyneleet vuotavat; jos joku osaa toista sydämeen, niin se ilmoittaa aivoituksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Joka laskettaa kiviä lintuin sekaan, se peljättää heidät pois; Ja joka ystävänsä häpäisee, se rikkoo ystävyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Vaikkas vetäisit miekkaas ystävääs vastaan, et sinä kuitenkaan sillä niin pahoin tee kuin häväistyksellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Sillä sinä taidat jälleen tulla ystäväksi, kuin et sinä pakene häntä, mutta puhut hänen kanssansa; sillä kaikki asiat taitaan kyllä sovitettaa, paitsi häväistystä, ylönkatsetta, salaisuuden ilmoitusta ja pahoja juonia: näillä ystävyys ajetaan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Ole uskollinen ystävälles hänen köyhyydessänsä, ettäs hänen kanssansa iloitsisit, kuin hänelle hyvin käy. Ole vahva hänen kanssansa, kuin hänelle pahoin käy, että sinäkin nautitsisit hänen onnensa hyväkses. Savu ja tomu käy edellä, kussa tuli palaa tahtoo: niin myös häväistyksestä tulee veren vuodatus. Älä häpeä vastata ystäväs edestä, älä myös häntä pakene. Jos sinulle jotakin pahaa häneltä tapahtuu, niin jokainen joka sen kuulee, välttää myös häntä. Jospa minä taitaisin panna lukon suuni eteen, ja painaa vahvan sinetin huulteni päälle, etten minä sen kautta lankeaisi, eikä minun kieleni vahingoittaisi minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Herra Isä Jumala, ja minun elämäni Herra! älä anna minun joutua pilkkaajain keskelle, ja älä anna minua heidän seassansa turmeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Jospa minä taitaisin hillitä ajatukseni suitsilla, ja kurittaa sydämeni Jumalan sanalla, ja etten minä säästäisi minuani erhetyksessäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Etten minä syntiä tekisi ja tulisi suureen erhetykseen, ja tekisi paljon pahaa, jolla minun täytyis langeta vihamiesteni edessä ja olla heidän naurunansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Herra Isä Jumala, ja minun elämäni Herra, varjele minua hävyttömistä silmistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Ja käännä minusta pois kaikki pahat himot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Älä salli minun tulla tuhlaajaksi ja saastaiseksi, ja varjele minua häpeemättömistä sydämistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Rakkaat lapset, oppikaat suunne pitämään kiinni; sillä joka suunsa pitää kiinni, ei se eksy sanoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Niinkuin jumalattomat pilkkaajat ja ylpiät sen kautta lankeevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Älä harjoita suutas vannomaan, ja lausumaan turhaan Jumalan nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Sillä niinkuin palvelia, joka usein vitsalla piestään, ei ole ilman vanteita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Niin ei myös se taida olla synnistä puhdas, joka usein vannoo ja Jumalan nimeä turhaan lausuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Joka usein vannoo, se usein syntiä tekee, ja ei rangaistus pidä hänen huoneestansa luopuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Jos hän vannoo, ja ei ymmärrä sitä, niin hän kuitenkin syntiä tekee; jos hän sen ymmärtää ja katsoo ylön, niin hän tekee syntiä kaksinkertaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Mutta jos hän turhaan vannoo, niin ei hän kuitenkaan ole ilman syntiä, ja hänen huoneensa pitää kovin rangaistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Se on myös kuolettavainen kiroilemus, josta Jumala Jakobin huonetta varjelkoon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Ja jumaliset senkaltaista välttävät, eikä tahraa itsiänsä siinä synnissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Älä harjoita suutas keviästi vannomaan, sillä se tulee pahasta aivoituksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Älä unohda isäs ja äitis oppia, niin sinä olet herrain seassa istuva, eikä sinua pidä unhotettaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Ettet harjaantuisi tyhmyyteen, ja soisit viimeiseltä, ettet syntynytkään olisi, ja sinä kiroot syntymäpäiväsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Joka itsensä harjoittaa panettelemaan, ei se paranna itsiänsä kaikkena elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Toistamiseen syntiä tehdä on ylenpaljon; sillä kolmannella kerralla tulee rangaistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Joka haureudesta on syttynyt, se on niinkuin palava tuli, eikä lakkaa siihenasti kuin hän itsensä polttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Hekumallisella ihmisellä ei ole lepoa ruumiissansa, siihenasti kuin hän tulen sytyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Hekumallisen ihmisen on kaikki ruoka makia, ja ei lakkaa ennen kuin hän himonsa täyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Mies, joka aviokäskynsä rikkoo, ja ajattelee itseksensä: kuka minun näkee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Pimeys on minun ympärilläni, ja seinät verhottavat minun, niin ettei kenkään näe minua: ketä minun pitäis karttaman? Korkein ei tottele minun syntiäni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Tämä välttää ainoasti ihmisten silmät, ja ei muista Herran silmää paljoa kirkkaammaksi aurinkoa, Joka näkee kaikki, mitä ihmiset tekevät, ja katsoo salaisiinkin loukkaisiin. Hän tietää kaikki kappaleet, ennenkuin ne luoduksi tulevat, niinkuin sittekin, kuin he luodut ovat. Se mies pitää julkisesti kaupungissa rangaistaman, Ja pitää otettaman kiinni, kuin hän vähimmän eteensä katsoo. Juuri niin pitää myös sille vaimolle tapahtuman, joka miehensä hylkää, ja saa toisesta perillisen. Ensisti on hän kovakorvainen Jumalan käskylle, sitälikin tekee myös syntiä miestänsä vastaan, ja kolmanneksi saa huoruudestansa lapsen. Nämä pitää eroitettaman seurakunnasta, ja hänen lapsensa pitää sen maksaman. Ei hänen lapsensa pidä juurtuman, eikä hänen oksansa hedelmää kantaman. Hän jättää kirotun muiston jälkeensä, ja hänen häpiänsä ei pidä ikänä pyyhittämän pois. Siitä oppivat jälkeentulevaiset, ettei mitään ole parempaa kuin peljätä Jumalaa, ja ei ole mitään makiampaa ottaa vaarin Jumalan käskystä');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Viisaus kiittää itsiänsä, ja kunnioittaa itsiänsä kansan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Hän saarnaa Jumalan seurakunnassa, ja ylistää itsiänsä valtakunnassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Ja sanoo: minä olen Jumalan sana, ja liikun ympäri kaikkea maata niinkuin pilvi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Minun asuinsiani on ylhäällä korkeudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Ja minun Istuimeni pilvissä; minä yksinäni olen joka paikassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Niin avaralta kuin taivas on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Ja niin syvältä, kuin syvyyden perustus on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Joka paikassa meressä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Joka paikassa maan päällä, kaikkein kansain seassa ja kaikkein pakanain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Näiden kaikkein tykönä olen minä etsinyt asuinsiaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Löytääkseni siaani johon kuhun paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Silloin käski minua kaikkein Luoja, ja se, joka minun luonut on, sääsi minulle asuinsian, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Jakobissa pitää sinun asuman, ja Israel pitää sinun perintös oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Ennen maailmaa, alusta olen minä luotu, ja pysyn ijankaikkisesti, ja olen pyhässä majassa palvellut hänen edessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Ja olen sitte saanut Zionissa vahvan paikan. Ja hän pani minun pyhään kaupunkiin, Jerusalemia hallitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Minä olen juurtunut kunnioitetussa kansassa, joka Jumalan perintö on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Minä olen korkiaksi kasvanut, niinkuin sedripnu Libanonissa, ja niinkuin sypressi Hermonin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Minä olen kasvanut niinkuin palmupuu virran tykönä, ja niinkuin ruusun vesat, jotka Jerihossa kasvavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Niinkuin kaunis öljypuu lakialla kedolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Minä olen kasvanut niinkuin vaahtera; minä annoin itsestäni suloisen hajun niinikuin kaneli ja kalliit yrtit, ja niinkuin paras mirham');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Niinkuin galbaan ja onik ja mirham, ja niinikuin pyhä savu templissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Minä ojensin oksani niinkuin tammi, ja minun oksani olivat kauniit ja suloiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Minä annoin makian hajun minustani niinkuin viinapuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Ja minun kukkaseni kantoivat joka vuosi runsaan hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Tulkaat tänne minun tyköni kaikki, jotka minua anotte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Ja ravitkaat teitänne minun hedelmästäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Minun saarnani on makiampi hunajaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 28, 'Jaa minun lahjani ovat makiammat kuin mesileipä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 29, 'Joka minusta syö, se enemmin isoo minua; ja joka minusta juo, se janoo enemmin minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 30, 'Joka kuulee minua, ei se tule häpiään; ja joka seuraa minua, sen pitää nuhteetoinna oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 31, 'Kaikki nämät ovat liiton kirja, joka kaikkein korkeimman Jumalan kanssa tehty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 32, 'Nimittäin laki, jonka Moses Jakobin huoneelle tavaraksi antanut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 33, 'Josta viisaus on vuotanut, niinkuin Pisonin virta, kuin se suuri on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 34, 'Ja niinkuin Tigris, kuin se keväällä kuohuu. Siitä on ymmärrys vuotanut, niinkuin Phratin virta, kuin se suuri on, ja niinkuin Jordan elonaikana. Siitä kuritus on tullut niinkuin valkeus ja niinkuin Niilin virta syksyllä. Ei ole yhtään ollut, joka sen kaiken oppinut on, ei tule myös yksikään ikänä, joka sen täydellisesti tutkia taitaa. Sillä sen mieli on rikkaampi merta, ja sen neuvo syvyyttä syvempi. Minusta vuotaa monta ojaa ryytimaihin, Niinkuin sinne vettä johdatettaisiin. Sillä minä kastan minun ryytimaani, ja juotan minun niittyni. Sillä minun ojani suureksi virraksi tulevat, ja minun virtani isoksi mereksi. Sillä minun oppini valistaa niin avaralta kuin aamuvalkeus, ja taampaa paistaa, Ja minun oppini vuodattaa prophetian, joka on ijankaikkisesti pysyvä. Siinä te näette, etten minä ainoasti itselleni työtä tee, mutta myös kaikille, jotka viisautta anovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Kolme on kaunista kappaletta, jotka Jumalalle Ja ihmisille kelpaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Kuin veljekset ovat yksimieliset, kylänmiehet rakastavat toinen toistansa, Ja mies ja vaimo keskenänsä hyvin sopivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Kolmea kappaletta minä sydämestäni vihaan, ja heidän menonsa saattaa minulle mielikarvauden:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Kuin köyhä on ylpiä, ja rikas mielellänsä valhettelee, ja vanha tyhmä on huorintekiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Jos et sinä nuorena kokoo, mitäs tahdot löytää vanhalla ijälläs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Oi kuinka kaunis se on, kuin harmaapäät viisaat ovat, Ja vanhat taitavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Ja herrat toimelliset ja ymmärtäväiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Se on vanhain kruunu, että he paljon koetelleet ovat, Ja se on heille kunniaksi, että he Jumalaa pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Yhdeksää kappaletta minä sydämessäni pidän korkiasti ylistettävänä, ja kymmenettä minä suullani kiitän:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Ihmistä, jolla on ilo lapsistansa; joka niin kauvan elää, että hän näkee vihamiehensä olevan maahan lyödyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Autuas on se, jolla on toimellinen vaimo; joka ei puheellansa ketään vahingoita; jonka ei pidä pahempaansa palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Autuas on se, jolla on uskollinen ystävä; autuas on se, joka on taitava,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Ja joka silloin opettaa, kuin häntä mieluisesti kuullaan');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Oi kuinka suuri se on, joka viisas on!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Mutta joka Jumalaa pelkää, ei häntä ylempänä ole kenkään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Sillä Jumalanpelko voittaa kaikki:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Joka sen vahvasti omistaa, keneenkä taidan minä hänen verrata?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Ei yksikään kipu ole niin suuri kuin sydämen murhe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Ei yhdenkään kavaluus voita vaimoin kavaluutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Ei yhdenkään väijyminen voita vihamiehen väijymistä; ei yksikään kosto ole pahempi vihamiehen kostoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Ei yksikään pää ole niin kavala kuin kärmeen pää; ei yhdenkään viha ole niin katkera kuin vaimon viha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Ennen minä asuisin jalopeurain ja lohikärmeen kanssa, kuin pahan vaimon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Kuin hän vihastuu, niin hän muuttaa hahmonsa, ja tulee rumaksi kuin säkki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Hänen miehellensä on häpiä hänestä, ja kuin hänelle sitä soimataan, niin se tekee hänen sydämensä kipiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Kaikki viekkaus on vähä vaimoin viekkauden suhteen, hänelle tapahtukoon niinkuin jumalattomalle tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Suupaltti, vaimo siviällä miehellä on niinkuin santainen tie ylöspäin vanhalle miehelle. Älä hänen kauneutensa anna sinuas pettää, älä myös sentähden himoitse häntä. Jos vaimo saattaa miehen rikkaaksi, niin ei siitä seuraa muuta kuin riita, tora, ylönkatse ja suuri pilkka. Paha vaimo saattaa murheellisen sydämen, surkian katsannon ja sydämen ahdistuksen. Vaimo, josta ei miehelle iloa ole, se suututtaa hänen kaikkiin kappaleihin. Synti on tullut vaimosta. ja sen tähden täytyy meidän kaikkein kuolla. Niinkuin ihmisen ei pidä antaman vedelle siaa: Niin ei pidä myös miehen salliman vaimolle hänen tahtoansa. Jos ei hän tahdo olla sinun mieltäs myöten, niin eroita häntä sinustas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Autuas on se mies, jolla on toimellinen vaimo: siitä hän kaksi sen vertaa elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Hyvä talon vaimo on miehellensä iloksi ja tekee hänen elämänsä levolliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Hyväntapainen vaimo on kallis lahja, ja annetaan sille, joka pelkää Jumalaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Joko hän on rikas eli köyhä, niin hän on kuitenkin hänelle lohdutukseksi, ja aina häntä ilahuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Kolme on hirmuista kappaletta, ja neljäs on kauhia:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Petos, kapina, viattoman veren vuodatus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Jotka kaikki ovat pahemmat kuolemaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Mutta se on sydämen murhe, kuin luulia vaimo toisen kanssa riitelee, ja häpäisee häntä jokaisen kuullen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Kuin miehellä on paha vaimo, niin he ovat niinkuin sopimatoin pari härkiä, joiden ynnä vetämän pitää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Joka sen saa, hän saa skorpionin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Juoppo vaimo on suuri rangaistus; sillä ei hän taida peittää häpiäänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Portto tunnetaan hävyttömästä katsannostansa ja silmistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Jos ei tyttäres ole häveliäs, niin pidä häntä kurituksessa, ettei hän pahaa tekisi, kuin hänelle tila annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Kuin ymmärrät hänen ylen rohkiasti katsovan ympärillensä, niin ota vaari; ja jos et sinä sitä tee, ja hän sitte tekee sinua vastaan, niin ei sinun sitä tarvitse ihmetellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Niinkuin matkustavainen, joka janoo, niin myös hän avaa suunsa ja juo vettä, lähin on, ja istuu, kussa hän kannon löytää, Ja ottaa, mitä hän saada taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Suloinen vaimo ilahuttaa miehensä, ja kuin hän pitää itsensä, toimellisesti, niin hän virvoittaa hänen sydämensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Vaimo, joka taitaa vaiti olla, on Jumalan lahja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Ja hyvin opetettu vaimo ei taideta maksettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Ei ole mitään rakkaampaa maan päällä, kuin häveliäs vaimo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Ja ei ole mitään kalliimpaa kuin puhdas vaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Niinkuin aurinko noustuansa kaunistaa Herran korkian taivaan, niin myös hyväntapainen vaimo kaunistaa huoneensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Kaunis vaimo, joka hyvyydessä kaiken elinaikansa vahvana pysyy, on niinkuin kirkas lamppu pyhässä kynttiläjalassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Yksivakainen vaimo on niinkuin kultaiset patsaat hopiajalkain päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Kaksi saattavat minulle mielikarvauden, ja kolmas vihoittaa minun:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Kuin vahva sotamies viimeiseltä köyhyyttä kärsii, ja viisaat neuvonantajat viimeiseltä katsotaan ylön,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Ja joka oikiasta uskosta luopuu väärään uskoon; sen on Jumala tuominnut miekan alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Kauppamies välttää työläästi vääryyden, ja myyjä synnin. Sillä rahan tähden tekee moni vääryyttä, ja jotka rikkaaksi tulla tahtovat, kääntävät pois silmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Niinkuin vaaja kahden kiven välille tungetaan muuriin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Niin myös synti tunkee ostajan ja myyjän välille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Jos ei hän itsiänsä pidä ahkerasti Herran pelvossa, niin hänen huoneensa pian kukistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Kuin seulotaan, niin kaunat jäävät: niin myös, mitä ihminen aikoo tehdä, niin siihen aina jotakin saastaista tarttuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Niinkuin pätsi koettelee uudet padat, niin myös murhe koettelee ihmisen mielen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Hedelmistä tuntuu, kuinka puu on katsottu: niin myös puheesta ymmärretään, millainen sydän on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Ei sinun pidä ketään kiittämän ennen kuin sinä hänen kuullut olet; sillä mies tunnetaan puheestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Jos sinä vanhurskautta seuraat, niin sinä sen saavutat, ja puet sen päälles niinkuin kauniin hameen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Linnut lähistelevät vertaisiansa: niin myös totuus pitää itsensä sen tykönä, joka häntä kuulee..');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Niinkuin jalopeura vartioitsee saalista, niin myös synti viimein ottaa kiinni pahantekiän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Jumalinen puhuu aina terveellisiä, mutta tyhmä muuttuu niinkuin kuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Kuin sinä taitamattomain seassa olet, niin ota vaari, mitä aika sallii; mutta ole viisasten seassa ahkera.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Tyhmäin puhe on ylen nurja, ja heidän naurunsa on sula synti, ja kuitenkin he sitä ailakoitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Kussa ihminen kuulee paljon vannottavan. siellä hänen karvansa nousee, ja heidän riitansa saattaa ihmiset korvansa tukitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Kuin ylpiät riitelevät, siitä seuraa verenvuodatus, Ja se on nurja kuulla, kuin he toistansa häpäisevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Joka salaisuuden ilmoittaa se kadottaa uskon, eikä saa sitten uskollista ystävää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Pidä ystäväs hyvänä, Ja ole hänelle uskollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Mutta, jos sinä ilmoitat hänen salaisuutensa, niin et sinä saa häntä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Jolta ystävä tulee pois, hänen on siitä niin paljon pahaa kuin sen, jonka vihamies pääsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Niinkuin sinä linnun päästät kädestäs, niin on myös se, kuin pääset ystävästäs, niin et sinä saa häntä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Ei sinun tarvitse juosta hänen peräänsä: hän on taampana, ja on hypännyt pois niinkuin metsäkauris verkosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Haava taidetaan sitoa, ja ylpiät sanat taidetaan sovitettaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Mutta joka salaisuuden ilmoittaa, ei hänestä sitte mitään ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Joka silmää iskee, sillä on pahaa sydämessä, ja ei se anna kääntää pois itsiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Edessäs taitaa hän kyllä makiasti puhua, ja ylistää sinun puhettas, mutta takana puhuu hän toisin, ja kääntää sinun sanas pahemmin päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'En minä taida mitään niin pahoin kärsiä kuin sitä. ja ei Herrakaan häntä kärsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Joka kiven heittää korkialle, se putoo hänen päähänsä; ja joka jonkun salaisesti pistää, se haavoittaa itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Joka haudan kaivaa, se putoo itse siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Joka paulan virittää toisen eteen, hän kietoo itsensä. Joka toista tahtoo vahingoittaa, se tulee tietämättä hänen omaan kaulaansa. Ylpiät pilkkaavat ja häpäisevät, mutta kosto vartioitsee heitä niinkuin jalopeura. Jotka iloitsevat, kuin hyville pahoin käy, ne vangitaan paulalla, ja sydämen murhe kalvaa heidät ennen kuin he kuolevat. Viha ja julmuus ovat kauhiat, jotka molemmat jumalattomalle ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Joka itse kostaa, hänelle Herra jälleen kostaa, ja hän pitää myös hänen syntinsä hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Anna anteeksi lähimmäiselles, mitä hän on rikkonut sinua vastaan, ja rukoile sitte, niin sinun syntis annetaan sinulle anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Ihminen vihaa toista, ja etsii armoa Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Hän on armotoin vertaistansa vastaan, ja tahtoo rukoilla synteinsä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Hän, joka liha on, pitää vihaa: kuka siis antais hänelle anteeksi hänen syntinsä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Muista loppua, ja pane pois viha, joka kuoleman ja kadotuksen etsii,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Ja pysy käskysanoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Muista käskyt, ja hylkää uhkaukses lähimmäistä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Muista Korkeimman liittoa, ja anna rikos anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Vältä riitaa, niin monta syntiä jää takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Sillä vihainen ihminen saattaa kapinan, ja jumalatoin sytyttää sekaannuksen hyväinkin ystäväin välille, ja yllyttää ne toisen toistansa vastaan, joilla hyvä rauha on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Kuin paljon puita on, silloin tuli enenee, ja kuin ihmiset uljaat ovat, niin viha tulee suuremmaksi. Ja jos ihmiset ovat rikkaat, niin viha tulee sitä väkevämmäksi; ja jos riita kauvan pysyy, niin se sitä enemmän palaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Olla valmis riitelemään, sytyttää tulen, ja olla nopia kapinaan, se vuodattaa verta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Jos sinä kipinää puhallat, niin se tulee suureksi liekiksi; mutta jos sinä syljet kipinän päälle, niin se sammuu; ja ne molemmat taitavat sinun suustas tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Korvankuiskutteliat ja väärät viekkaat suut ovat kirotut; sillä ne turmelevat monta, joilla on hyvä rauha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Paha kieli tekee monta ihmistä eripuraisiksi, Ja tunkee heitä ulos yhdestä maasta niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Se kukistaa vahvat kaupungit, Ja särkee valtakunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Paha kieli ajaa pois jalot vaimot,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Ja tyhjäksi tekee heitä siitä, josta heidän vaivaa ja työtä on ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Joka sitä kuulee, ei hänellä ole ikänä lepoa, eikä saa missään olla rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Ruoska tekee vanteet, mutta paha kieli särkee luut ja kaikki tyynni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Monta on langennut miekan terän kautta, mutta ei ikänä niin usia kuin pahan kielen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Hyvin sille tapahtuu, joka on siltä varjeltu, ja ei sitä vaivata, eikä täydy kantaa sen ijestä, ei myös ole sidottu sen kahleisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Sillä sen ijes on rautainen, Ja sen kahleet ovat vaskesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Se kipu on katkerampi kuolemaa ja pahempi helvettiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Mutta jumalisia ei voi se polkea alas, ja ei heidän pidä sen tulessa palaman. Joka Herran hylkää, hänen pitää siihen lankeeman ja siinä palaman, jota ei pidä sammutettaman. Sen pitää hänen päällensä hyökkäämän niinkuin jalopeura, ja turmeleman hänen niinkuin pardi. Sinä aitaat tavaras orjantappuroilla, miksi et paremmin tee ovea ja telkeä suus eteen? Sinä punnitset hopias ja kultas, miksi et myös sanojas kultavaa\'alla punnitse? Ota vaari, ettet sen kautta horjahda ja lankee vihamiestes käsiin, jotka sinua väijyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 1, 'Joka lähimmäisellensä lainaa, hän tekee laupiudentyön.; ja jolla tavaraa on, hänen tulee se tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 2, 'Lainaa lähimmäiselles, kuin hän tarvitsee, ja anna (a) sinä lähimmäiselles jälleen määrätyllä ajalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 3, 'Pidä, mitäs puhunut olet, ja älä ole petollinen hänen kanssansa, niin sinä aina saat sinun tarpees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 4, 'Moni luulee sen löytyksi, jonka hän lainaksi ottaa, ja tekee sen murheelliseksi. joka häntä on auttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 5, 'Hän antaa kätensä suuta, häneltä lainan ottaissansa, ja puhuu nöyrästi lähimmäisensä rahan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 6, 'Mutta kuin hänen pitäis maksaman jälleen, niin hän viivyttelee ja valittaa suuresti, että aika on kallis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 7, 'Ja vaikka hän vielä vois, niin hän antaa työläästi puolen jälleen, ja lukee sen hänelle voitoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 8, 'Jos ei hän voi, niin hän tekee hänen tyhjäksi rahastansa: niin on se itsellensä ostanut vihamiehen rahallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 9, 'Ja se maksaa hänen kirouksella ja häväistyksellä, ja antaa hänelle kiitoksesta pilkkasanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 10, 'Moni lainaa ylönmielin, ei pahasta ajatuksesta, mutta pelkää tyhjäksi jäävänsä omastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 11, 'Kärsi kuitenkin lähimmäistäs hädässä, ja tee myös se armo, ettäs annat hänelle aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 12, 'Auta köyhää käskyn tähden, ja älä anna hänen tyköäs lähteä tyhjänä hädässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 13, 'Ole mielelläs rahaas paitsi veljes ja lähimmäises tähden, ja älä kätke sitä kiven alle, kussa se kumminkin hukkaantuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 14, 'Kokoo itselles tavaraa Ylimmäisen käskyn jälkeen: se on sinulle parempi kuin kulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 15, 'Pane almus erinomaiseen paikkaan, joka sinua on kaikesta onnettomuudesta auttava,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 16, 'Ja on sotiva sinun puolestas sinun vihamiehiäs vastaan, paremmin kuin kilpi ja keihäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 17, 'Hyväntahtoinen mies takaa lähimmäisensä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 18, 'Mutta häpeemätöin ihminen jättää hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 19, 'Älä unohda takausmiehes hyvää työtä; sinä hän on pannut itsensä sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 20, 'Jumalatoin vie takausmiehensä vahinkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 21, 'Ja kiittämätöin antaa vapahtajansa istua vahingossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 22, 'Takaus on monta rikasta ihmistä hävittänyt, ja on heitä heittänyt sinne ja tänne, niinkuin aallot meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 23, 'Se on ajanut pois jalot miehet, joiden täytyy vieraalla maalla kulkiana käydä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 24, 'Jos jumalatoin on taannut, ja juonittelee siitä päästäksensä. kuitenkin ei hänen pidä rangaistusta välttämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 25, 'Auta lähimmäistäs voimas perästä, ja katso, ettet itse sentähden tule vahinkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 26, 'Siinä on kyllä tähän elämään, että ihmisellä on vettä ja leipää, vaatteet ja huone, joilla hän tarpeensa peittää taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 27, 'Parempi on köyhän elo lautakaton alla, joka oma on, kuin herkullinen pöytä muukalaisten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 29, 28, 'Tyydy siihen. mitä sinulla on, vähä eli paljo; sillä se on häpiällinen elämä. siirtää huoneesta huoneesen. Kussa joku on muukalainen, ei hän siellä tohdi suutansa avata. Hänen täytyy heitä vieraanansa pitää, ja antaa heidän juoda kanssansa, ja ei saa yhtään kiitosta. Hänen täytyy myös kuulla pahoja sanoja, Nimittäin: sinä muukalainen, mene ja valmista pöytä; Anna minun syödä kanssas, mitä sinulla on. Mene tästä ulos, sinä muukalainen, minä olen saanut kunniallisemman vieraan: minun veljeni tulee minun tyköni. Senkaltaiset ovat toimelliselle miehelle työläät, että hänen asuinsian tähden niitä sanoja kuuleman pitää, ja että hänelle soimataan sitä, mikä hänelle lainattu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 1, 'Joka lastansa rakastaa, se pitää hänen aina kurituksen alla, että hän sitte saa ilon hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 2, 'Joka lapsensa pitää pelvon alla, se saa ilon hänestä, eikä tarvitse hänen tähtensä tuttavainsa tykönä hävetä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 3, 'Kuin joku poikaansa kurittaa, niin hän tekee vihamiehensä mielen pahaksi, ja iloittaa ystävänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 4, 'Sillä jos hänen isänsä kuolee, niin se on niinkuin ei hän olisikaan kuollut; sillä hän on kaltaisensa jälkeensä jättänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 5, 'Kuin hän eli, näki hän hänen, ja iloitsi hänestä; kuin hän kuoli, niin ei hänen tarvinnut murehtia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 6, 'Sillä hän jätti jälkeensä vastuksen vihamiehiänsä vastaan, ja sen, joka ystäväin mielen jälleen noutaa taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 7, 'Mutta joka lapsillensa pehmeä on, hän valittaa sen vanteita; ja niin usein kuin se itkee, niin hän peljästyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 8, 'Kurittamatoin lapsi tulee niin kankeaksi kuin hillimätöin hevonen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 9, 'Ole pehmiä pojalles, niin sinun täytyy edespäin peljätä häntä; leikitse hänen kanssansa, niin hän sinun viimein saattaa murheelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 10, 'Älä tee leikkiä hänen kanssansa, ettei sinun sitte pidä hänen kanssansa murehtiman, ja niin sinun täytyy viimein hänen tähtensä hampaita kiristää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 11, 'Älä anna hänelle valtaa nuorella ijällänsä, ja älä vastaa hänen tyhmyytensä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 12, 'Kumarra hänen kaulansa nuorena, ja lyö häneltä selkään vähänä, ettei hän tulisi sinulle niskuriksi ja tottelemattomaksi. 7:25.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 13, 'Opeta lastas, ja älä anna hänen joutilaana käydä, ettes tulisi häpiään hänen tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 14, 'Parempi on jonkun olla köyhänä, raittiina ja terveenä, kuin rikkaana ja kipiänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 15, 'Olla raittiina ja terveenä on parempi kultaa, ja raitis ruumis on parempi kuin paljo kalua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 16, 'Ei mikään rikkaus ole verrattava raittiisen ruumiisen, ja ei yksikään ilo ole sydämellisen ilon vertainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 17, 'Kuolema on parempi kuin kivulloinen elämä ja alinomainen sairaus:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 18, 'Se on niinkuin hyvä herkku sen suun edessä, joka ei voi syödä, ja niinkuin se ruoka, joka kuolleen haudalle pannaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 19, 'Sillä mitä uhri on tarpeellinen epäjumalalle, joka ei taida syödä eikä haistaa? Niin se on myös rikkaalle, jonka Jumala sairaaksi tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 20, 'Kyllä hän näkee sen silmillänsä ja huokaa sitä, ja on niinkuin kuohittu, joka neitseen ohessa makaa ja huokaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 21, 'Älä tee itselles murhetta, älä myös vaivaa sinuas omilla ajatuksillas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 22, 'Sillä iloinen sydän on ihmisen elämä, ja hänen ilonsa on hänen pitkä ikänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 23, 'Tee itselles hyvää ja vahvista sydäntäs, ja aja murhe kauvas tyköäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 24, 'Sillä murhe on tappanut monta ihmistä, ja ei kelpaa mihinkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 30, 25, 'Kiivaus ja viha lyhentää elämän, ja murhe tekee ihmisen ennen aikaansa vanhaksi. Iloiselle sydämelle maistavat kaikki hyvin, mitä hän syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 1, 'Valvoa rikkautta syö ruumiin ja siitä murehtia ei anna maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 2, 'Kuin joku makaa ja murehtii, niin hän aina herää, niinkuin suuri sairauskin aina herättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 3, 'se on rikas, joka aina työtä tekee ja rahaa kokoo, ja välistä lakkaa, ja nautitsee sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 4, 'Mutta se on köyhä, joka työtä tekee, ja ei mitään menesty, ja vaikka hän vielä lakkaa, niin on hän kuitenkin vaivainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 5, 'Joka rahaa rakastaa, ei se ole synnitöin, ja joka katoovaista etsii, sen täytyy ynnä hukkua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 6, 'Moni rahan tähden tulee vahinkoon, ja sen kautta turmellaan omain silmäinsä nähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 7, 'Jotka sille uhraavat, se kukistaa ne maahan, ja taitamattomat se ottaa kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 8, 'Autuas on se rikas, joka nuhteettomaksi löydetään, ja ei etsi rahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 9, 'Kuka se on? ja me tahdomme kiittää häntä; sillä hän tekee väkeviä töitä kansansa seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 10, 'Joka tässä koetelluksi ja yksivakaiseksi löydetään, sitä syystä ylistetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 11, 'Hän taisi kyllä pahaa tehdä, ja ei kuitenkaan tehnyt; hän taisi vahingoittaa, ja ei vahingoittanutkaan; sentähden pysyy hänen tavaransa, ja pyhät ylistävät hänen almuansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 12, 'Kuin istut rikkaan pöydän tykönä, niin älä suutas ammottele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 13, 'Älä myös ajattele: kyllä tässä syömistä on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 14, 'Mutta muista paha silmä saidaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 15, 'Sillä mikä on tiiviimpi kuin senkaltainen silmä, joka itkee, kuin hän näkee jonkun ottavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 16, 'Älä rupee kaikkiin, mitä siinä näet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 17, 'Älä myös siihen rupee, joka hänen edessänsä vadissa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 18, 'Ajattele itselläs, mitä sinun lähimmäises mielellänsä eli ylönmielen hyvänä pitää, ja käytä itses toimellisesti kaikissa kappaleissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 19, 'Syö niinkuin ihminen, mitä etees pantu on; älä myös ylen paljon syö, ettei ihmiset sinulle vihastuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 20, 'Lakkaa ensin kunnian tähden syömästä; älä myös ole tyytymätöin, ettet voittaisi vihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 21, 'Kuin istut monen keskellä, niin älä ensin ota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 22, 'Hyväntapainen ihminen tyytyy vähäänkin, sentähden ei hän tarvitse nikuttaa vuoteessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 23, 'Ja kuin vatsa kohtuullisesti ravitaan, silloin ihminen suloisesti lepää, ja taitaa varhain aamulla nousta ja olla iloinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 24, 'Mutta tyytymätöin syömäri makaa levottomasti, ja hänellä on väänne ja vatsan tauti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 25, 'Jos sinä olet ylen paljon syönyt, niin nouse, ja mene ja pane levätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 26, 'Poikani, kuule minua, ja älä katso minua ylön, ettei minun sanani viimein sinua kohtaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 27, 'Ota jotakin tehdäkses, niin ei tauti tule sinun päälles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 28, 'Antiasta miestä kiittävät ihmiset ja sanovat: hän on kunniallinen mies, ja senkaltainen puhe on hyvä kiitos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 29, 'Mutta tylystä ja nälkäisestä puhuu koko kaupunki pahoin, ja sen hän oikein sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 30, 'Älä ole viinan juomari; sillä viina on monta turmellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 31, 31, 'Ahjo koettelee juotetun raudan, niin koettelee myös viina ylönannetut sydämet, kuin ne juovuksissa ovat. Viina pidentää ihmisen elämän, jos sitä kohtuullisesti juodaan. Ja mikä elämä se on, kussa ei viinaa ole? Viina on sitä varten luotu, että sen pitää ihmistä iloittaman. Viina, tarpeeksi juotu, iloittaa ihmisen ruumiin ja sielun; Mutta jos sitä paljon juodaan, Niin se tuo paljon pahaa myötänsä. Juopumus tekee hullun vielä hullummaksi, Niin että hän haastaa ja uhkaa, Siihenasti kuin hän loukataan, lyödään ja haavoitetaan. Älä nuhtele lähimmäistäs juomingissa, älä myös ylenkatso häntä ilossansa. Älä anna hänelle pahaa sanaa, älä myös kohtaa häntä kovalla puheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 1, 'Jos he ovat, sinun asettaneet johdattajaksensa, niin älä siitä ylpeile, vaan pidä itses heidän kaltaisenansa, ja aseta itses niinkuin hekin, niin sinä istut oikein;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 2, 'Ja anna siihen, mitä sinun tulee, jos sinä tahdot siinä kanssa istua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 3, 'Että he olisivat iloiset sinun kanssas, niin sinä saat kunnian, ja kutsutaan taitavaksi ja hyvin eläneeksi mieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 4, 'Vanhimman pitää puhuman; sillä se tulee hänen tehdä, niinkuin sen, joka koetellut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 5, 'Älä estä soittajoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 6, 'Jos myös virsiä veisataan, niin älä sekoita itsiäs niiden sekaan, mutta säästä viisautes toiseksi ajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 7, 'Niinkuin rubiini valistaa kauniissa kullassa, niin myös veisu kaunistaa pidon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 8, 'Niinkuin smaragdi on kauniissa kullassa ihana,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 9, 'Niin myös virret ovat hyvän viinan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 10, 'Puhukaan nuorukainen kerran eli kaksi, kuin niin tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 11, 'Ja kuin häneltä kysytään, niin hänen pitää vastaaman lyhykäisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 12, 'Ja pitämän itsensä niinkuin se, joka ei paljon tietäisi, ja paremmin vaiti oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 13, 'Ei hänen pidä itsiänsä herrain vertaisena pitämän, ja kuin vanha puhuu, ei itsiänsä sekoittaman hänen puheesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 14, 'Ukkosella on suuri tulen leimaus myötä; häveliäisyys tekee suuren mielisuosion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 15, 'Nouse pöydän tyköä aikanansa, ja älä ole viimeinen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 16, 'Mutta mene nopiasti kotias, iloitse siellä ja tee, mitäs tahdot: kuitenkin, ettet mitään pahaa tee, eli ylpiästi puhu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 17, 'Mutta kiitä häntä kaikkein niiden edestä, joka sinun luonut ja hyvyydellänsä ravinnut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 18, 'Joka Herraa pelkää, se antaa itsensä mielellänsä opettaa, ja joka aikanansa itsensä siihen sovittaa, se löytää armon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 19, 'Joka kysyy Jumalan sanaa, hän on sen runsaasti saava; mutta joka ei sitä täydestä todesta ajattele, hän pahenee siitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 20, 'Joka Herraa pelkää, se saa oikian opin, ja saattaa vanhurskauden valistamaan niinkuin valkeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 21, 'Ei jumalatoin anna itsiänsä kurittaa, ja tietää kuitenkin aivoituksessansa auttaa itsiänsä toisen elämällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 22, 'Ei toimellinen mies katso ylön hyvää neuvoa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 23, 'Mutta ylönannettu ja ylpiä ei pelkää, vaikka hän on tehnyt, mitä hän on tahtonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 32, 24, 'Älä tee mitään ilman neuvoa, niin et sinä kadu sitä sitte kuin se tehty on. Älä käy sitä tietä, jolla lankeat, taikka niissä, joissa itses kiviin loukkaat. Älä siihen luota, että tie on tasainen, ja kavahda myös omia lapsias. Ehkä mitä sinä teet, niin turvaa Jumalaan. kaikesta sydämestäs; sillä se on pitää Jumalan käskyjä. Joka uskoo Jumalan sanan, se pitää käskysanat; ja joka Herraan luottaa, ei häneltä pidä mitään puuttuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 1, 'Joka Herraa pelkää, ei hänelle tapahdu mitään pahaa; mutta kuin hän kiusattu on, niin hänen pitää jälleen vapahdetuksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 2, 'Viisas mies ei vihaa Jumalan sanaa; mutta ulkokullattu häälyy niinkuin haaksi suuressa ilmassa merellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 3, 'Ymmärtäväinen ihminen pitää itsensä Jumalan sanassa. ja Jumalan sana on hänelle vahva niinkuin selkiä puhe.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 4, 'Tutki hyvin asia, ja puhu sitte siitä: anna itses ensin hyvin opettaa, niin sinä vastata taidat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 5, 'Tyhmän sydän on niinkuin vaunuin ratas, ja hänen ajatuksensa juoksee ympäri niinkuin rattaan pyörä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 6, 'Niinkuin suodanhaltia hirnuu jokaista tammaa vastaan, niin myös ulkokullattu riippuu jokaisessa pilkkaajassa, ja sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 7, 'Miksi pitää yksi päivä oleman pyhempi toista? sillä aurinko käy joka päivä vuosikautena yhtäläisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 8, 'Herran viisaus on ne niin eroittanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 9, 'Ja hän on niin asettanut vuoden ajat ja pyhäpäivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 10, 'Hän muutamat valinnut ja pyhittänyt muiden päiväin suhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 11, 'Niinkuin kaikki ihmiset ovat maasta, ja Adam on mullasta luotu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 12, 'Ja Herra on kuitenkin eroittanut heitä sanomattomasta viisaudestansa, ja on asettanut moninaiset tavat heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 13, 'Muutamat on hän siunannut, korottanut ja pyhittänyt, ja palvelukseensa kutsunut: mutta muutamat on hän kironnut, alentanut ja heittänyt pois heidän säädystänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 14, 'Sillä he ovat hänen kädessänsä niinkuin savi valajan kädessä: hän tekee kaikki työnsä niinkuin hän tahtoo;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 15, 'Juuri niin ovat myös ihmiset hänen kädessänsä, joka heidät tehnyt on, ja hän antaa jokaiselle, niinkuin hänelle näkyy hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 16, 'Niin on myös hyvä asettua pahaa vastaan, ja elämä kuolemaa vastaan, ja jumalinen jumalatointa vastaan. Katso näin kaikkia sen Korkeimman töitä, niin on kaksi asetettu kahta vastaan, ja yksi yhtä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 17, 'Minä olen jälkinnä herännyt, niinkuin se, joka syksyllä jälissä poimii. Ja Jumala antoi minulle siunauksen, että minä olen myös täyttänyt minun viinakuurnani, niinkuin täydellä syksyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 18, 'Katsokaat, etten minä ole itselleni työtä tehnyt, mutta kaikille niille, jotka mielellänsä oppia tahtovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 19, 'Kuulkaat minua, te suuret herrat, ja te, kansan haltiat, pankaat sitä sydämeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 20, 'Älä anna poikas, emäntäs, veljes, ja ystäväs vallita sinuas niinkauvan kuin sinä elät; älä myös anna tavaraas kenenkään haltuun, ettet kadu sitä, ja sinun täytyy sentähden heitä rukoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 21, 'Niinkauvan kuin sinä elät, niin älä anna itsiäs yhdenkään ihmisen haltuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 22, 'Se on parempi, että sinun lapses tarvitsevat sinua, kuin se, että sinun pitää heidän käsiinsä katseleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 23, 'Ole itse tavaras haltia, älä myös anna ottaa pois sinun kunniaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 24, 'Kuin sinun loppus tulee, ja sinun pitää täältä eriämän, niin jaa silloin perintös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 25, 'Aasin tulee saada hänen ruokansa, ruoska ja kuorma: niin myös palvelian hänen leipänsä, kurituksensa ja työnsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 26, 'Pidä palvelias työssä, niin sinä saat häneltä levon; mutta jos sinä annat hänen käydä joutilaana, niin hän tulee ylpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 27, 'Ies ja ohjat notkistavat kaulan, niin pahan palvelian haavat ja lyömiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 28, 'Aja häntä työhön, ettei hän käy joutilaana; käydä joutilaana opettaa paljon pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 29, 'Pane työ hänen eteensä, se mikä palvelialle sopii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 30, 'Jos ei hän kuule sinua, niin pane häntä jalkapuuhun; älä kuitenkaan kellenkään ylen paljon tee, mutta pidä kohtuus kaikissa asioissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 31, 'Jos sinulla on palvelia, niin pidä hänestä vaari niinkuin itse sinustas; sillä se, joka hänelle jotakin tekee, se väijyy sinun henkeäs ja elämääs. Jos sinulla on palvelia, niin anna häntä pidettää niinkuin sinä itse olisit; sillä sinä tarvitset häntä niinkuin omaa henkeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 32, 'Jos sinä pidät hänen pahana, niin että hän karkaa sinun tyköäs, kustas tahdot etsiä häntä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 33, 33, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 1, 'Tyhmät ihmiset pitävät itsensä hullulla toivolla, ja hullut luottavat hourauksiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 2, 'Joka unia tottelee, se rupee varjoon, ja tuulta takaa ajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 3, 'Ei unet ole muuta kuin kuvat ilman olentoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 4, 'Se joka saastainen on, kuinka se taitaa puhdas olla? ja se mikä petos on, kuinka taitaa se tosi olla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 5, 'Oma arvo, ja selitys, ja unet ei ole mitään, ja ne saattavat kuitenkin raskaat ajatukset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 6, 'Ja jos ei se tule Korkeimman ilmoituksesta, niin älä siitä pidä mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 7, 'Sillä unet ovat monta pettäneet, ja ne häpiään tulleet, jotka niihin ovat luottaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 8, 'Ei siihen tarvita valhetta, että ihmisen pitää Jumalan käskyt pitämän, ja Jumalan sanassa on kyllä, kuin ihminen oikein opettaa tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 9, 'Hyvin harjoitettu mies ymmärtää paljon, ja hyvin koeteltu taitaa puhua viisaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 10, 'Mutta joka ei ole mitään harjoitettu, se vähän ymmärtää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 11, 'Ja erhettyväiset henget saattavat paljon pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 12, 'Kuin minä vielä eksyksissä olin, taisin minä myös paljon oppia, ja olin niin oppinut, etten minä taitanut kaikkia sanoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 13, '\'Ja tulin sentähden kuoleman vaaraan, siihenasti kuin minä siitä vapahdettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 14, 'Nyt minä näen, että jumalisilla on oikia henki;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 15, 'Sillä heidän toivonsa on hänen tykönsä, joka auttaa taitaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 16, 'Joka Herraa pelkää, ei hänen tarvitse hämmästyä eli vapista; sillä hän on hänen toivonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 17, 'Autuas on, joka Herraa pelkää.: mihinkä hän uskaltaa? ja mikä on hänen lohdutuksensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 18, 'Herran silmät katsovat niiden päälle, jotka häntä rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 19, 'Hän on voimallinen turva, suuri väkevyys, varjo palavuutta vastaan, peite kuumaa puolipäivää vastaan, varjelus kompastusta vastaan, apu lankeemista vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 20, 'Joka sydämen ilmoittaa, kasvot ihastuttaa, antaa myös terveyden, elämän ja siunauksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 21, 'Joka väärin saatua kalua uhraa, sen uhri on pilkka,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 22, 'Ja senkaltainen jumalattomain häväistys ei millään muotoa kelpaa Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 23, 'Jumalattomain lahjat ei kelpaa ensinkään Korkeimmalle, ja synnit ei tule sovitetuksi uhrien paljoudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 24, 'Joka uhraa köyhän tavarasta, hän tekee niinkuin se, joka pojan teurastaa isän silmäin nähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 25, 'Ei köyhällä ole mitään muuta kuin vähäinen leipä; joka sen ottaa häneltä pois, se on murhaaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 26, 'Joka toiselta ottaa pois hänen elatuksensa, se tappaa lähimmäisensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 27, 'Joka ei anna työntekiälle hänen palkkaansa, se on veren vuodattaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 28, 'Kuin joku rakentaa ja jälleen rikkoo maahan: mitä hänen siitä muuta on kuin työtä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 29, 'Kuin joku rukoilee ja jälleen kiroilee: kuinka Herra kuulee hänen rukouksensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 30, 'Joka itsensä pesee, koska hän kuolleesen sattunut on, ja rupee siihen jälleen: mitä hänen pesonsa auttaa häntä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 34, 31, 'Juuri niin on se ihminen, joka synteinsä tähden paastoo, ja aina jälleen syntiä tekee; kenen pitäis hänen rukouksensa kuuleman, ja mitä hänen paastonsa häntä auttaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 1, 'Pitää Jumalan käskyt, se on rikas uhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 2, 'Korkiana pitää Jumalan käskyt, se uhri auttaa hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 3, 'Joka Jumalaa kiittää, se on oikia sämpyläuhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 4, 'Joka laupiutta harjoittaa, se tekee oikian kiitosuhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 5, 'Hyljätä syntiä on jumalanpalvelus, joka Herralle kelpaa; ja lakata pahaa tekemästä on oikia sovintouhri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 6, 'Mutta ei sinun pidä sentähden hänen eteensä tyhjänä tuleman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 7, 'Sillä sen pitää myös meidän tekemän Herran käskyn tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 8, 'Vanhurskaan uhri tekee alttarin rikkaaksi, ja hänen suitsuttamisensa on makia Korkeimman edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 9, 'Vanhurskaan uhri on otollinen, ja ei häntä pidä ikänä unhotettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 10, 'Anna Jumalalle kunnia iloisella mielellä ja sinun esikoises ilman puuttumusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 11, 'Mitäs annat, niin anna mielelläs, ja pyhitä sinun kymmenykses iloisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 12, 'Anna sille Korkeimmalle, niinkuin hän sinulle antanut on, ja mitäs voit, niin anna se iloisella mielellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 13, 'Sillä Herra, joka maksaa jälleen, on sen sinulle maksava seitsemänkertaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 14, 'Älä vähennä lahjaas; sillä ei se ole otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 15, 'Älä etsi omaa parastas, kuin sinun pitää uhraaman; sillä Herra on kostaja, joka ei katso yhdenkään muodon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 16, 'Hän auttaa köyhää, ja ei katso kenenkään muotoa, joka myös kuulee sorretun rukouksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 17, 'Ei hän katso ylön orpoin rukousta, eikä lesken valitusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 18, 'Lesken kyyneleet tosin vuotavat alas sasupäin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 19, 'Mutta ne huutavat ylöspäin sitä vastaan, joka niitä vuodattanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 20, 'Joka Jumalaa mielellänsä palvelee, hän on otollinen, ja hänen rukouksensa ulottuu hamaan pilviin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 21, 'Viheliäisen rukous tunkee pilvien lävitse ja ei seisahda, siihenasti kuin hän tulee eteen, eikä lakkaa ennen kuin se Korkein katsoo sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 22, 'Ja Herra on oikein tuomitseva ja rankaiseva, eikä viivy eli kärsi viivytystä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 23, 'Siihenasti kuin hän rikkoo armottomain lanteet, ja kostaa senkaltaisille ihmisille, ja kadottaa kaikki, jotka ovat häntä vastaan, ja kukistaa maahan pahantekiäin voiman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 24, 'Ja antaa jokaiselle heidän töittensä jälkeen, ja maksaa heille niinkuin he ansainneet ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 25, 'Ja kostaa kansansa puolesta, ja ilahuttaa heitä laupiudellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 35, 26, 'Niinkuin sade on poudalla tarpeellinen, niin myös laupius tulee hädässä oikiaan aikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 1, 'Herra, kaikkivaltias Jumala! armahda meitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 2, 'Ja katso tänne ja peljätä kaikki kansat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 3, 'Nosta kätes muukalaisten päälle, että he sielun voimas näkisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 4, 'Niinkuin sinä heidän nähtensä meidän seassamme pyhitetään, niin näytä myös itses kunnialliseksi heidän päällensä meidän nähtemme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 5, 'Että he tuntisivat, niinkuin me tunnemme, ettei yhtään muuta Jumalaa ole kuin sinä, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 6, 'Tee uudet ihmeet ja tunnustähdet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 7, 'Osoita kätes ja oikia käsivartes kunniallisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 8, 'Herätä viha ja vuodata julmuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 9, 'Tempaa pois vastaanseisova, muserra vihamies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 10, 'Riennä ja muista valas, että ihmiset ylistäisivät sinun ihmeellisiä töitäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 11, 'Tulen viha kuluttakoon ne, jotka suruttomasti elävät, ja ne hukkukoon, jotka sinun kansalles pahaa tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 12, 'Särje päämiesten pää, jotka meidän vihamiehemme ovat, ja sanovat: me olemme yksinämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 13, 'Kokoo kaikki Jakobin sukukunnat, ja anna heidän olla sinun perikuntanas, niinkuin alustakin');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 14, 'Armahda kansaas, jolla sinusta nimi on, ja Israelia, jonka sinä kutsut esikoisekses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 15, 'Armahda Jerusalemin kaupunkia, jossa sinun pyhäs on ja jossa asut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 16, 'Rakenna taas Zion, että sinun sanas siellä saarnattaisiin, ja kunnias tulis kansan seassa suureksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 17, 'Osoita sinus heille, jotka alusta sinun omaa olleet ovat, ja täytä ne ennustukset, jotka sinun nimees ilmoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 18, 'Kosta niille, jotka sinua odottavat, että sinun prophetas totiseksi löydettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 19, 'Kuule, Herra, sinun palveliais rukous, Aaronin siunauksen jälkeen sinun kansas ylitse, että kaikki, jotka asuvat maan päällä, tuntisivat sinun olevan Herran, ijankaikkisen Jumalan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 20, 'Vatsa ottaa kaikkinaista ruokaa tykönsä, kuitenkin on yksi ruoka parempi kuin toinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 21, 'Niinkuin kieli maistaa metsänotuksen, niin myös toimellinen sydän ymmärtää petolliset sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 22, 'Viekas ihminen taitaa toisen saattaa vahinkoon, mutta joka hyvin koeteltu on, se taitaa ottaa vaarin itsestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 23, 'Kaikki äidit rakastavat poikiansa, kuitenkin on tytär toisinansa parempi kuin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 24, 'Kaunis vaimo iloittaa miehensä, ja ei miehelle ole mitään rakkaampaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 25, 'Jos hän on myös ystävällinen ja hyvä, niin ei löydetä sen miehen vertaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 26, 'Jolla emäntä on, sen hyvyys enenee, ja hänellä on uskollinen apu ja tuki, johon hän taitaa nojata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 27, 'Kussa ei ole aitaa ympärillä, siinä kalu hajoitetaan, ja kussa ei emäntää ole, siellä perheen isäntä epätiedossa kävelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 28, 'Niinkuin ei ihminen usko ryöväriä, jotka yhdestä kaupungista toiseen juoksee, niin ei myös sitä miestä uskota, jolla ei pesää ole, vaan siinä oleskelee, kussa ehtoo tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 29, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 30, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 36, 31, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 1, 'Jokainen ystävä tosin sanoo: minä olen myös ystävä, mutta muutamat ovat ainoastaan nimeltä ystävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 2, 'Kuin ystävät toinen toisensa kanssa vihastuvat, niin viha pysyy hamaan kuolemaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 3, 'Voi! kusta siis se pahuus tulee, että koko maailma on petosta täynnä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 4, 'Kuin ystävälle hyvin käy, iloitsevat he hänen kanssansa, mutta kuin hänelle pahoin käy, tulevat he hänen vihamiehiksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 5, 'He murehtivat hänen kanssansa vatsan tähden, mutta kuin hätä tulee, turvaavat he kilpeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 6, 'Älä unhota ystävääs ilossas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 7, 'Ja muista häntä, kuin rikastut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 8, 'Jokainen neuvonantaja tahtoo antaa neuvoa, mutta muutamat neuvovat omaksi hyväksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 9, 'Ota sentähden vaari neuvonantajista, ajattele ensin, jos se hyvä on; sillä mitämaks hän ajattelee neuvoaksensa itsellensä parhaaksi ja antaa sinun koetella, ja sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 10, 'Sinä olet oikialla tiellä, ja hän seisoo kuitenkin sinua vastaan, katsomassa, kuinka se sinulle menestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 11, 'Älä neuvoa sen kanssa pidä, jolla paha ajatus on sinua vastaan, ja älä ota niitä neuvoos, jotka sinua kadehtivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 12, 'Niinkuin sinä vaimolta neuvoa kysyisit, kuinka sinun pitäis ystävällisesti oleman hänen riitasisarensa kanssa, eli pelkurilta, kuinka sinun pitää sotiman, eli kauppamieheltä, kuinka kalliiksi hän tahtoo arvata sinun riistas hänen kaluansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 13, 'Taikka ostajalta, kuinka kalliisti sinua omas antaman pitäis, eli tiiviiltä, kuinka hyvää pitäis tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 14, 'Eli armottomalta. kuinka armahdettaman pitää, eli laiskalta raskaasta työstä, eli vuoden palkolliselta, kuinka työ täytettämän pitää? eli laiskalta palvelialta monesta askareesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 15, 'Älä näiden ihmisten kanssa neuvoa pidä; mutta pidä itses joka paikassa jumalisten ihmisten tykö, joiden tiedät pitävän Jumalan käskyn,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 16, 'Jotka sillä mielellä ovat kuin sinäkin, ja kärsivät sinun kanssas, jos sinä osaat horjahtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 17, 'Niin pysy heidän neuvossansa; sillä et sinä löydä uskollisempaa neuvoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 18, 'Ja yksi senkaltaisista taitaa usein paremmin nähdä asian, kuin seitsemän vartiaa, jotka ylhäällä vartioitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 19, 'Kuitenkin kaikissa näissä rukoile Korkeinta auttamaan sinun työtäs, ja ettei hän sinulta antaisi mitään puuttua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 20, 'Ennenkuin sinä jotakin alat, niin kysele, ja ennenkuin sinä jotakin teet, niin ota neuvo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 21, 'Sillä jos jotakin uutta aljetaan, niin siihen tulee yksi näistä neljästä: hyvä eli paha, elämä eli kuolema, jotka kaikki kieli aina hillitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 22, 'Moni on sovelias muita neuvomaan, mutta itsellensä on neuvotoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 23, 'Moni tahtoo viisaasti neuvoa, ja ei kuitenkaan kuulla häntä mielellänsä, joka tulee kerjääjäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 24, 'Sillä ei hänellä ole Herralta armoa siihen, ja ei hänessä ole viisautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 25, 'Moni on viisas oman harjoituksensa kautta, ja saattaa neuvoansa hyödytyksen, ja osaa oikein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 26, 'Viisas mies taitaa opettaa väkensä, tuottaa hyödytyksen neuvollansa, ja osaa oikein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 27, 'Viisas mies korkiasti kunnioitetaan, ja kaikki, jotka hänen näkevät, ne ylistävät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 28, 'Jokaisella on määrätty elinaikansa, mutta Israelin aika on määrätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 29, 'Viisas on kansansa edessä suuressa kunniassa, ja hänen nimensä pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 30, 'Poikani, koettele, mitä ruumiilles terveellinen on, ja katso, mikä ei sille ole terveeIlinen, älä sille sitä anna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 37, 31, 'Sillä ei kaikki sovi kaikille, ei myös jokaiselle kaikki kelpaa. Älä täytä itsiäs ylen täyteen kaikkinaisilla herkullisilla ruilla, ja älä syö ylen ahneesti. Sillä ylensyömys tekee ihmisen kipiäksi, ja tyytymätöin syömän saa taudin. Moni on itsensä kuoliaaksi syönyt, mutta joka kohtuuden pitää, hän sitä enemmän elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 1, 'Kunnioita parantajaa kohtuullisesti, että saisit hänen hädän aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 2, 'Sillä Herra on luonut hänen, ja parannus tulee Korkeimmalta, ja kuninkaat kunnioittavat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 3, 'Parantajan taito korottaa hänen, ja tekee hänen suureksi päämiesten ja herrain tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 4, 'Herra antaa parannuksen kasvaa maasta, ja toimellinen ei katso sitä ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 5, 'Karvas vesi tuli puusta makiaksi, että sen voima piti tunnettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 6, 'Hän on senkaltaisen taidon antanut ihmiselle, että hänen piti ylistetyksi tuleman hänen ihmeellisissä töissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 7, 'Sen kanssa hän parantaa ja ajaa pois kivun, ja voiteen keittäjä tekee siitä voiteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 8, '(Lyhykäisesti) kaikkea Jumalan työtä ei taida kenkään luetella, joka kaikkea hyvää antaa maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 9, 'Poikani, kuin sairas olet, niin älä katso sitä ylön, mutta rukoile Herraa, niin hän tekee sinun terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 10, 'Lakkaa syntiä tekemästä, ja tee kätes nuhteettomaksi, ja puhdista sydämes kaikista pahoista töistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 11, 'Uhraa makiaa savua ja sämpylöitä ajatusuhriksi, ja anna, lihava uhri, niinkuin sinun pitäis pois täältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 12, 'Sitte salli parantajan tulla tykös; sillä Herra on hänen luonut; ja älä päästä häntä pois tyköäs, ettäs kuitenkin tarvitset häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 13, 'Sillä hetki taitaa tulla, että sairas ainoastaan näiden kautta tulee autetuksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 14, 'Kuin he rukoilevat Herraa, että hän hänen parantais, ja hän sais terveytensä kauvan elääksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 15, 'Joka Luojansa edessä syntiä tekee, sen täytyy tulla parantajan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 16, 'Poikani, kuin joku kuolee, niin itke häntä, ja valita niinkuin se, joka suuren surun on saanut, ja kääri hänen ruumiinsa kohtuullisesti, ja anna hänen kunniallisesti tulla hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 17, 'Sinun pitää katkerasti itkemän, ja sydämestä murheellinen oleman, ja valitusitkua pitämän, senjälkeen kuin hän on ollut, vähimmäksikin yksi päivä eli kaksi, ettei sinua paneteltaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 18, 'Ja ota jälleen lohdutus, ettet murheella täytettäisi; sillä murheesta tulee kuolema., ja sydämen ahdistus tekee voimattomaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 19, 'Murhe ja köyhyys saattavat sydämen valittamaan ylitse määrän kiusauksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 20, 'Älä päästä murhetta sydämees, mutta estä häntä tyköäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 21, 'Ajattele loppua, ja älä unhota sitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 22, 'Sillä ei sieltä ole palausta, eikä se auta häntä mitään, mutta sinä teet itselles vahingon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 23, 'Muista häntä, niinkuin hän on kuollut, niin pitää myös sinunkin kuoleman: eilen piti minun, tänäpänä sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 24, 'Sittekuin kuollut rauhassa makaa, niin lakkaa myös sinäkin häntä ajattelemasta, ja lohduta sinuas hänen tähtensä, että hänen henkensä on täältä niin vieroitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 25, 'Joka Raamattua oppiman pitää, ei se, saa muuta työtä tehdä, ja kuin joku pitää opettaman, niin ei sillä pidä muuta tekemistä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 26, 'Kuinka se taitaa opista vaarin ottaa, jonka pitää kyntämän ja joka härkiä mielellänsä ruoskalla ajaa, ja muuta senkaltaista työtä tekee, eikä tiedä muusta kuin härjistä puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 27, 'Hänen pitää ajatteleman, kuinka hän pellon rakentaa, ja hänen täytyy hiljain ja varhain lehmiä ruokkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 28, 'Juuri niin myös rakentajat ja puusepät, jotka yötä ja päivää työtä tekevät, ja kuvaa leikkaavat, ja niin ahkeroitsevat heitänsä moninaista työtä tekemään. Heidän pitää ajatteleman, että se tulis oikein tehdyksi, ja varhain ja hiljain siitä ahkeroitseman, että se tulis tehdyiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 29, 'Niin myös seppä: hänen pitää oleman alasimensa tykönä, ja ottaman vaarin pajastansa, hän tulee voimattomaksi liekistä, ja tekee työtä itsensä väsyksiin ahjon tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 30, 'Vasara lukitsee hänen korvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 31, 'Hän ahkeroitsee siitä, kuinka hän työnsä taitais oikein tehdä, ja pitää ajatteleman, kuinka hän sen saa valmiiksi, ja varhain ja hiljain ahkeroitsee siitä, kuinka hän sen taitais hyvin päättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 32, 'Niin myös savenvalajan pitää työstänsä ottaman vaarin, jaloillansa pitää hänen pyörää kääntämän, ja aina tekemän työnsä murheella, ja hänellä on määrätty päivätyönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 33, 'Hänen pitää käsivarrellansa savesta astian valmistaman, ja täytyy kumartaa jalkainsa tykö väsyksiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 38, 34, 'Hänen pitää ajatteleman, kuinka hän sen hyvin sileäksi sivuu sisältä, ja pitää varhain ja hiljain käväisemän pätsin. Kaikki nämät turvaavat virkaansa, ja jokainen ahkeroitsee, että hän taitais työnsä tehdä. Ei niitä paitsi saada olla kaupungissa. Mutta ei heitä taideta valtakunnan asioille lähettää, ei heille taideta myös valtaa antaa, ja ei he taida hallita yhteistä kansaa. Ei heillä ole ymmärrystä opettaa Raamattua, eikä saarnata oikeutta ja vanhurskautta. Ei he taida lukea sananlaskuja, mutta heidän täytyy ottaa vaarin ajallisesta elatuksesta. eikä edemmä ajattele kuin he työllänsä voittaa taitavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 1, 'Mutta joka tahtoo itsensä siihen antaa, että hänen pitää oppiman Korkeimman lakia, hänen pitää tutkiman kaikkein vanhain viisautta, ja ahkerasti lukeman prophetain ennustuksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 2, 'Hänen pitää katseleman viisasten miesten kirjoituksia, ja ottaman vaarin, mitä ne merkitsevät ja opettavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 3, 'Hänen pitää oppiman hengelliset sananlaskut, ja harjoittelemaan itsensä syvissä puheissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 4, 'Hän taitaa palvella päämiehiä, ja olla herrain seassa, hän tietää itsensä käyttää vieraalla maalla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 5, 'Sillä hän on koetellut, mitä ihmisten seassa kelpaa ja ei kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 6, 'Ja ajattelee, kuinka hänen pitää varhain nouseman Herraa etsimään, joka hänen luonut on, ja rukoilemaan Korkeimman edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 7, 'Hän avaa suunsa rohkiasti ja rukoilee kaiken kansan syntein tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 8, 'Ja kuin Herra lepytetty on, niin hän antaa hänelle runsaasti viisauden hengen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 9, 'Että hän taitaa antaa viisasta neuvoa ja opettaa voimalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 10, 'Sentähden kiittää hän Herraa rukouksessansa, ja Herra antaa armon, että hänen neuvonsa ja oppinsa menestyy,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 11, 'Jonka hän ensin ajattelee itseksensä, ja sanoo sitte neuvonsa ja oppinsa ulos, ja vahvistaa sen pyhällä kirjoituksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 12, 'Ja moni ihmettelee hänen viisauttansa, jonka ei ikänä pidä hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 13, 'Ei häntä koskaan unohdeta, mutta hänen nimensä pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 14, 'Mitä hän on opettanut, pitää vastakin saarnattaman, ja seurakunnan pitää häntä ylistämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 15, 'Niinkauvan kuin hän elää, niin hänellä on suurempi nimi kuin tuhannella muulla, joka myös hänellä kuolemansakin jälkeen pysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 16, 'Minulla on vielä jotakin sanomista; sillä minä olen niinkuin täysi kuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 17, 'Kuulkaat minua, te pyhät lapset, ja kasvakaat niinkuin istutetut kukkaset juoksevan ojan reunalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 18, 'Ja antakaat makia haju teistänne niinkuin pyhä savu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 19, 'Kukoistakaat niinkuin valmut, ja hyvälle hajatkaat, veisatkaat kiitosvirttä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 20, 'Ja kiittäkäät Herraa kaikissa hänen töissänsä, ylistäkäät hänen nimeänsä suurella kunnialla. Kiittäkäät häntä ja ylistäkäät virsillä ja kanteleilla, ja sanokaat kiitos näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 21, 'Kaikki Herran työt ovat sangen hyvät, ja mitä hän käskee, se tapahtuu oikialla ajalla; ja ei kenkään rohkea sanoa: mihinkä tämä? sillä he tulevat ajallansa toivotettuna,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 22, 'Niinkuin silloin, kuin vesi seisoi hänen käskystänsä niinkuin muurit, ja vedet hänen sanansa jälkeen niinkuin he olisivat olleet suljetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 23, 'Sillä mitä hän käskyllänsä toimittaa, se on suloinen, ja ei kenenkään ole valittamista, että jotakin hänen avustansa puuttuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 24, 'Kaikki ihmisten työt ovat hänen edessänsä, ja ei hänen silmäinsä edestä ole mitään salattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 25, 'Hän näkee kaikki kappaleet maailman alusta hamaan maailman loppuun asti, ja ei hänen edessänsä ole yhtäkään kappaletta uutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 26, 'Ei ihmisen pidä sanoman: mihinkä tämä? Sillä hän on luonut jokaisen, niin että ne johonkuhun kelpaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 27, 'Sillä hänen siunauksensa vuotaa niinkuin virta, ja tuoreuttaa maan niinkuin juokseva vesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 28, 'Sitä vastaan hänen vihansa sattuu pakanoihin, niinkuin silloin, kuin hän antaa vesisen maan kuivua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 29, 'Hänen työnsä ovat pyhäin edessä oikiat, mutta jumalattomat loukkautuvat niihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 30, 'Kaikki, mikä alusta luotu on, se on hyville hyvä, mutta jumalattomille vahingollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 31, 'Ihminen tarvitsee elämäänsä vettä, valkeata, rautaa, suolaa, jauhoja, hunajaa, rieskaa, viinaa, öljyä ja vaatteita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 32, 'Kaikki nämät tulevat hyville hyväksi, ja jumalattomille vahingoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 33, 'Tuulet ovat myös puolittain luodut kostoksi, ja puhalluksellansa tekevät ne vahinkoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 34, 'Ja kuin rangaistus pitää tuleman, niin ovat ne julmat, ja täyttävät Luojansa vihan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 39, 35, 'Tuli, rakeet, nälkä, kuolema, kaikki nämät ovat luodut kostamaan. Metsän pedot, skorpionit, kärmeet ja miekka ovat myös luodut kostoksi, kadottamaan jumalattomia. Ne tekevät ilolla hänen käskynsä, ja ovat valmiit, kuhunka hän heitä tarvitsee maan päällä, ja kuin hetki tulee, niin ei ne ole joutilaat. Tämä on se, josta minä rupesin ja ajattelin kirjoittaa: (Nimittäin) että kaikki Herran työt ovat hyvät, ja kukin on ajallansa tarpeellinen, Niin ettei ihmisen tarvitse sanoa: ei ne kaikki ole hyvät; sillä jokainen on ajallansa kallis. Sentähden pitää ihmisen kiittämän ja ylistämän Herran nimeä sydämellä ja suulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 1, 'Viheliäinen ja surkia meno on kaikkein ihmisten elämällä, hamasta äidin kohdusta niin siihen asti kuin he jälleen maahan haudataan, joka on meidän kaikkein äitimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 2, 'Täällä on aina murhe, pelko ja viimein kuolema odotettavana,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 3, 'Niin sen, joka Suuressa kunniassa istuu, kuin halvimmankin maan päällä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 4, 'Niin sen, joka silkkiä ja kruunua kantaa, kuin senkin, joka rohtimiin on puetettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 5, 'Täällä on aina viha, kiivaus, tuska, sota ja kuoleman vaara, riita ja tora; ja kuin ihminen yöllä lepää ja makaa vuoteessansa, niin tulevat monet ajatukset eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 6, 'Ja vaikka hän vähän lepoa saa, niin ei se kuitenkaan mitään ole; sillä hän peljätetään unissansa, niinkuin hän vihamiehet näkis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 7, 'Ja kuin hän herää, ja näkee olevansa ilman vaaraa, niin se on hänelle niinkuin sille, joka sodasta on päässyt ja ihmettelee, ettei siellä hätää ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 8, 'Senkaltaista tapahtuu kaikelle lihalle, sekä ihmisille että eläimille, mutta jumalattomille seitsemän kertaa enempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 9, 'Murha, veri, riita, miekka, vahinko, nälkä, hukka ja vaiva, kaikki nämät ovat asetetut jumalattomia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 10, 'Sillä vedenpaisumus piti myös heidän tähtensä tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 11, 'Kaikki mitä maasta tulee, pitää maaksi jälleen tuleman, niinkuin kaikki vedet mereen jälleen juoksevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 12, 'Kaikki lahjat ja väärin saatu kalu pitää hukkuman, mutta totuus pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 13, 'Jumalattoman kalu raukee tyhjään, ja kuivuu niinkuin oja, ja niinkuin ukkonen sateesta lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 14, 'He ovat iloiset niinkauvan kuin he lahjoja ottavat, mutta viimeiseltä pitää heidän kuitenkin hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 15, 'Jumalattomain jälkeentulevaisten ei pidä vesoman, ja väärintekiäin juuri pitää seisoman paljaalla karilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 16, 'Ja vaikka hän vielä seisois jokseenkin syvässä ja veden tykönä, niin hän pitää kuitenkin hävitettämän, ennenkuin hän kypsyy. Mutta hyvin tehdä on niinkuin siunattu yrttitarha, ja laupius pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 17, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 18, 'Joka itsensä työllänsä elättää ja tyytyy siihen, hänellä on levollinen elämä, se on, löytää kaikkein parhaan tavaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 19, 'Lapsia synnyttää, ja kaupunkia parantaa, saattaa ijäisen muiston; mutta kunniallinen vaimo enemmän kuin nämät molemmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 20, 'Viina ja kantele iloittavat sydämen; mutta viisaus on suloisempi niitä molempia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 21, 'Pillit ja harput kuuluvat hyvin; mutta ystävällinen puhe on niitä parempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 22, 'Sinun silmäs katsovat mielellänsä sitä, mikä otollinen ja kaunis on; mutta viheriäinen kylvö on parempi niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 23, 'Ystävä tulee ystävänsä tykö tuskassa; mutta mies ja vaimo paljoa ennemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 24, 'Veli auttaa veljeänsä hädässä; mutta laupius auttaa paljoa enemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 25, 'Kulta ja hopia tukevat miehen; mutta hyvä neuvo paljoa enemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 26, 'Raha ja riista rohkaisevat; mutta Herran pelko paljoa enemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 27, 'Ei Herran pelvolta mitään puutu, eikä se tarvitse yhdenkään apua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 28, 'Herran pelko on siunattu yrttitarha, ja ei ole mitään niin kaunista kuin se on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 29, 'Poikani, älä pyydä kerjätä, parempi on kuolla kuin kerjätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 40, 30, 'Joka luottaa toisen pöytään, ei se ajattele itsiänsä elättää kunniallisesti; sillä hänen täytyy tehdä syntiä toisen miehen ruan tähden; Mutta toimellinen mies kavahtaa sitä. Kerjäys maistaa häpeemättömän suulle hyvin; mutta se tulee viimein hänelle pahaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 1, 'Oi kuolema! kuinka katkera sinä olet, kuin ihmisen sinua ajattelee, jolla on hyvät päivät ja paljo kalua, ja elää ilman surua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 2, 'Ja jolle kaikki asiat hyvin käyvät ja vielä hyvin syödä voi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 3, 'Oi kuolema! kuinka hyvin sinä teet tarvitsevalle, joka heikko ja vanha on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 4, 'Ja kaikessa murheessa elää, eikä ole parempaa toivottavaa eli odotettavaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 5, 'Älä pelkää kuolemaa; johdata mielees, että tämä on näin asetettu Herralta kaikelle lihalle, sekä niille, jotka sinun edelläs olleet ovat, että niille, jotka sinun jälkees tuleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 6, 'Mitäs olet Jumalan tahtoa vastaan, jokos elät kymmenen, sata eli tuhannen ajastaikaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 7, 'Sillä ei kuolemassa kysytä, kuinka kauvan ihminen elänyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 8, 'Jumalattomain lapset, ja jotka jumalattomain seuraan antauvat, tulevat kauhistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 9, 'Jumalattomain lasten perintökalu pitää hukkuman ja heidän jälkeentulevaisensa pitää oleman ylönkatsotut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 10, 'Lasten täytyy valittaa jumalatointa isää; sillä he ovat hänen tähtensä katsotut ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 11, 'Voi teitä, te jumalattomat! jotka hylkäätte Korkeimman lain:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 12, 'Joko te elätte eli kuolette, niin te olette kirotut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 13, 'Niinkuin kaikki, mikä on maasta, tulee jälleen maaksi, niin tulevat myös jumalattomat kirouksesta kadotukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 14, 'Ihmisen kärsimys olkoon täällä niinkauvan kuin hän elää, mutta jumalattomain nimi pitää pyyhittämän pois, joka ei mitään kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 15, 'Katso, ettäs pidät hyvän nimen, joka vahvempana pysyy kuin tuhannen suurta kultaista tavaraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 16, 'Olkoon elämä niin hyvä kuin se taitaa, kuitenkin se pysyy vähän aikaa; mutta hyvä nimi pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 17, 'Poikani, kuin teille hyvin käy, niin katsokaat, ja pysykäät Jumalan pelvossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 18, 'Miksi te häpeette minun sanojani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 19, 'Ihminen häpee silloin usein, kuin ei hänen pitäisi häpeemän, ja mielistyy usein siihen, mihin ei hänen pitäisi mielistymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 20, 'Hävetkään isä ja äiti huoruudesta, päämies ja herra valheesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 21, 'Tuomari ja neuvonantaja vääryydestä., ja yhteinen kansa kovakorvaisuudesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 41, 22, 'Lähimmäinen ja ystävä vahinkoa tekemästä, ja kylänmies varkaudesta. Häpee, että käsivarrellas makaat pöydällä leivän päällä. Häpee, ettet kestä luvun laskemisessa, ja ettet kiitä, kuin sinua tervehditään. Häpee, ettäs porttoja katsot, ja käännät kasvos pois sukulaisestas. Häpee, ettäs muutat perinnön ja huomenlahjan, ja ettäs himoitset toisen emäntää. Häpee sinuas himoitakses toisen piikaa, ja seisoakses hänen vuoteensa tykönä. Häpee, ettäs soimaat ystävääs; ja kuin sinä hänelle jotakin annat, niin älä sitä soimaa hänelle. Häpee sanoa kaikkia, mitäs kuullut olet, ja ilmoittaa salaista ja uskottua puhetta.. Niin sinä oikein häpeet ja tulet rakastetuksi ja ylistetyksi kaikilta ihmisiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 1, 'Mutta älä näiden tähden ensinkään häpee, älä myös tee kenenkään tähden väärin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 2, 'Älä häpee Jumalan lakia ja. Korkeimman liittoa, ja auta jumalisia oikeuteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 3, 'Olla uskollinen lähimmäiselles ja kumppanilles, antaa sukulaisten saada perintönsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 4, 'Ahkeroida pitämään oikiaa mittaa ja vaakaa, tyytyä, joko voitat paljon eli vähän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 5, 'Oikein tehdä ajallisen kalun ostamisessa ja myymisessä, opettaa lapsia ahkerasti, lyödä pahoja palvelioita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 6, 'Kätkeä hyvin omas pahalta vaimolta, kaikki hyvin lukita, kussa paljon ottamista on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 7, 'Mitä heille on antaminen, kaikki lukea ja punnita, kaikki anto ja otto kirjoittaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 8, 'Neuvoa taitamattomia ja pöhköjä ja peräti vanhoja ihmisiä, ettei he nuorten kanssa riitelisi: näin sinä tulet soveliaaksi ihmiseksi ja joka mieheltä kiitetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 9, 'Naittamatoin tytär saattaa isänsä paljon valvomaan, ja murhe hänestä ottaa paljon unta häneltä pois: kuin hän nuori on, ettei hän naiduksi tule, eli kuin hän miehen saa, ettei hän siltä vihattavaksi tulisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 10, 'Eli kuin hän vielä neitsyt on, mahtaisi häväistyksi ja isänsä huoneessa raskaaksi tulla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 11, 'Eli kuin hän miehensä tykönä on, ettei hän pidä itsiänsä kunniallisesti, eli ettei hän saata hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 12, 'Jos ei sinun tyttäres ole häveliäs, niin ole kova hänen kanssansa., ettei hän tee sinua vihamiehes pilkaksi, ja koko kaupunki saa sinusta puhumista, ja sinun pitää jokaiselta häpiän kuuleman, ja joka miehen edessä häpeemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 13, 'Älä katsele ympäri kauniita ihmisiä, ja älä mielelläs ole vaimoväen seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 14, 'Sillä niinkuin vaatteista tulee koi, niin myös paljo pahaa tulee vaimoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 15, 'Parempi on olla pahan miehen kanssa, kuin ystävällisen vaimon kanssa, sen vaimon kanssa, joka nauruksi ja pilkaksi saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 16, 'Minä ylistän Herran töitä, ja pyhästä Raamatusta niitä ilmoitan, niinkuin minä niistä lukenut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 17, 'Aurinko valistaa kaiken maailman, ja on täynnä Herran kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 18, 'Ei se ole vielä nytkään annettu pyhille Herralta, että he kaikki hänen ihmeensä ulos sanoa taitavat, sillä kaikkivaltias Herra on tehnyt ne niin suuriksi, ja kaikki kappaleet ovat ylen suuret niin ylistettää kuin tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 19, 'Hän yksinänsä tutkii syvyyden ja ihmisten sydämet, ja tietää, mitä he ajattelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 20, 'Sillä Herra tietää kaikki kappaleet, ja näkee, miltä ajalla kukin pitää tapahtuman. Hän ilmoittaa, mitä tapahtunut on, ja mitä tapahtuva on, ja ilmoittaa, mitä salattu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 21, 'Hän ymmärtää kaiken salaisuuden, ja ei yksikään asia ole häneltä peitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 22, 'Hän osoittaa viisautensa suurella kunnialla, ja hän pysyy ijanikaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 23, 'Ei ihminen taida tehdä häntä suuremmaksi eikä vähemmäksi; ei hän myös tarvitse yhtäkään neuvoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 24, 'Oi kuinka suloiset ovat kaikki hänen työnsä, vaikka ihminen työläästi taitaa ainoasti kipinän siitä ymmärtää!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 42, 25, 'Ne elävät kaikki, ja niin myös ijankaikkisesti pysyvät, ja mihinkä hän heitä tarvitsee, niin ne ovat hänelle kuuliaiset. Kaikissa paikoissa ovat kaksi kahta vastaan, ja yksi yhtä vastaan; ja mitä hän tekee, niin ei siitä mitään puutu. Ja hän on asettanut jokaisen, kuhunka se tarpeellinen oleman pitää; ja kuka suuttuu katsomasta hänen suurta kunniaansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 1, 'Herran kunnia näkyy ylen suuressa korkeudessa, vahvuuden kirkkaudessa ja taivaan kauneudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 2, 'Kuin aurinko nousee, niin hän ilmoittaa päivän, se joka on yksi Korkeimman ihmetyö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 3, 'Puolipäivästä kuivaa hän maan, ja kuka voi olla hänen palavuudessansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 4, 'Hän on palavampi kuin monta pätsiä, ja polttaa vuoret, ja hohtaa palavuutta tyköänsä, ja antaa niin kirkkaan paisteen itsestänsä, että se silmät häikäisee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 5, 'Se mahtaa suuri Herra olla, joka hänen tehnyt on, ja on käskenyt hänen niin nopiasti juosta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 6, 'Ja kuun pitää kaikessa maailmassa ajallansa paistaman, ja eroittaman kuukaudet ja jakaman vuoden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 7, 'Kuun jälkeen luetaan juhlapäivät, se on valkeus, joka vähenee ja kasvaa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 8, 'Se tekee kuukaudet, kasvaa ja muuttaa itsensä ihmeellisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 9, 'Valistaa myös kaiken taivaan sotajoukon ylhäällä vahvuudessa, ja kirkkaat tähdet kaunistavat taivaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 10, 'Niin on Herra korkeudessa käskenyt niiden maailmaa valistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 11, 'Jumalan sanan kautta pitävät ne säätynsä, ja ei väsy valvomasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 12, 'Katso taivaan kaarta, ja kiitä häntä, joka sen tehnyt on; sillä se on sangen kaunis kirkkaudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 13, 'Hän on tehnyt taivaan kauniisti ympyriäiseksi, ja Korkeimman käsi on sen venyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 14, 'Hänen sanansa kautta sataa paljon lunta, ja hän antaa ihmeellisesti tulen leimahtaa sekaisin, niin että taivas avaa itsensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 15, 'Ja pilvet häälyvät, niinkuin linnut lentävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 16, 'Hän tekee voimallansa pilvet paksuksi, niin että rakeet sieltä satavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 17, 'Hänen ukkosensa jylinä peljättää maan, että vuoretkin hänen edessänsä värisevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 18, 'Hänen tahdostansa puhaltaa etelätuuli ja pohjatuuli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 19, 'Ja niinkuin linnut lentävät, niin kääntyvät myös tuulet, ja puhaltavat lunta kokoon, niin että hän ajaa kinokseen, ja se putoo alas niinkuin heinäsirkat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 20, 'Se on niin valkia, että se häikäisee silmät, ja sydämen täytyy ihmetellä senkaltaista kamalaa sadetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 21, 'Hän vuodattaa härmän maan päälle niinkuin suolan, ja kuin se kylmettyy, niin siitä tulee jää, niinkuin teroitetut seipäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 22, 'Ja kuin kylmä pohjatuuli puhaltaa, niin vesi tulee jääksi; kussa vettä on, siellä se puhaltaa, ja pukee veden päällensä, niinkuin haarniskan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 23, 'Hän turmelee vuoret ja polttaa korvet, ja kuivaa kaiken vihannon niinkuin tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 24, 'Sitä vastaan auttaa synkiä pilvi ja kaste virvoittaa kaikki jälleen poudan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 25, 'Sanallansa estää hän meren pysymään siassansa, ettei se edemmä pääse, ja hän on pannut luodot siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 26, 'Jotka merellä vaeltavat, ne juttelevat sen vaaroista, ja me, jotka sitä kuulemme, ihmettelemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 27, 'Siellä ovat kamalat ihmeet, moninaiset eläimet ja valaskalat, ja niiden keskeltä he purjehtivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 28, 'Hänen sanallansa pysyvät kaikki kappaleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 29, 'Ja jos me vielä paljonkin sanoisimme, niin emme kuitenkaan kerkiä kaikkiin; lyhykäisesti: hän on kaikki tyynni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 30, 'Ja vaikka me vielä kaikkia korkiasti kunnioittaisimme, mitä se olis? Hän on vielä sittenkin paljoa korkiampi kuin kaikki hänen työnsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 31, 'Herra on sanomattomasti suuri, ja hänen voimansa on ihmeellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 32, 'Kiittäkäät ja kunnioittakaat Herraa teidän voimanne perästä hän on sittekin korkiampi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 43, 33, 'Ylistäkäät häntä kaikesta voimasta ja älkäät lakatko, ette kuitenkaan taida käsittää. Kuka on hänen nähnyt, että hänestä sanoa taitais? Kuka taitaa häntä niin korkiasti ylistää kuin hän on? Me näemme ainoastaan vähimmän hänen töistänsä; sillä paljo suuremmat ovat meiltä vielä peitetyt. Sillä kaikki on Herra tehnyt, jotka hän antaa jumalisten tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 1, 'Kiittäkäämme kunniallisia miehiä ja meidän isiämme, yhtä toisensa jälkeen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 2, 'Monta kunniallista työtä on Herra tehnyt heidän kauttansa jo alusta suurella voimallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 3, 'He ovat valtakuntansa hyvin hallinneet ja jaloja töitä tehneet; he ovat viisaasti neuvoneet ja ennustaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 4, 'He ovat maakuntia ja kansoja hallinneet neuvolla ja Raamatun ymmärryksellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 5, 'He ovat lauluja opettaneet ja hengellisiä veisuja ajatelleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 6, 'He ovat olleet rikkaat, ja heillä on ollut paljo tavaraa, ja ovat rauhassa hallinneet niinkauvan kuin he täällä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 7, 'Näin ovat he kaikki aikanansa olleet kiitettävät, ja niinkauvan kuin he elivät, suuressa kunniassa pidetyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 8, 'Ja jättäneet jälkeensä kunniallisen nimen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 9, 'Mutta muilla ei ole yhtään kiitosta, jotka ovat hukkuneet, niinkuin ei he ensinkään olisi eläneet, ja ovat syntyneet, niinkuin ei he olisikaan olleet, niin myös heidän lapsensa heidän jälkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 10, 'Mutta pyhille ihmisille, joiden vanhurskaus ei unohdeta, on hyvä perintö jäänyt, niin myös heidän lapsillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 11, 'Heidän jälkeentulevaisensa pysyivät liitossa, ja heidän tähtensä pysyivät heidän lastensa lapset ijankaikkisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 12, 'Ja heidän kiitoksensa ei pidä hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 13, 'He ovat rauhassa haudatut, mutta heidän nimensä elää ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 14, 'Kansa puhuu heidän viisaudestansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 15, 'Ja seurakunta ilmoittaa heidän kiitoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 16, 'Enok kelpasi Herralle, ja otettiin pois, että hän olis maailmalle neuvo katumukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 17, 'Noa löydettiin nuhteettomaksi, ja vihan aikana löysi hän armon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 18, 'Ja tallella pidettiin maan päällä, kuin vedenpaisumus tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 19, 'Hän sai liiton maailman: puolesta, ettei yksikään liha pidä silleen vedenpaisumisella hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 20, 'Abraham, korkiasti kunnioitettu monen kansan isä, jolla ei ole vertaa kunniassa, hän piti Korkeimman lain, ja Jumala teki hänen kanssansa liiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 21, 'Hänen lihaansa asetti hän sen liiton; ja hän löydettiin silloin uskolliseksi kuin hän kiusattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 22, 'Sentähden Jumala valalla lupasi hänelle, että hänen siemenensä kautta piti kaikki pakanat siunattaman, ja hän niinkuin maan tomu enennettämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 44, 23, 'Ja hänen siemenensä korotettaman niinkuin tähdet, ja oleman perilliset yhdestä merestä niin toiseen ja virrasta hamaan maailman ääreen asti. Niin hän myös vahvisti liiton Isaakin kanssa, hänen isänsä Abrahamin tähden, Ja antoi hänelle kaikkein ihmisten siunauksen ja liiton, ja vahvisti sen Jakobin pään päälle. Hänen siunasi hän armollisesti, antoi hänelle perinnön, eroitti hänen osansa ja jakoi hänen kahteentoistakymmeneen sukukuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 1, 'Hän antoi hänestä tulla pyhän miehen Moseksen, joka kaikelle maailmalle rakas ja otollinen oli, jota sekä Jumala että ihmiset rakastivat, jonka nimi korkiasti kunnioitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 2, 'Häntä kunnioitti hän niinkuin pyhiä isiä, ja korotti hänen suuresti, niin että vihamiesten täytyi häntä peljätä; ja antoi hänen tehdä monta ihmettä sanoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 3, 'Hän teki hänen kuninkaalliseksi kuningasten edessä, ja antoi hänelle käskyn kansansa tykö, ja osoitti hänelle kunniansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 4, 'Hän valitsi hänen pyhään säätyyn, hänen uskonsa ja siveytensä tähden, ja valitsi hänen kaikista ihmisistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 5, 'Hän antoi hänen kuulla oman äänensä, ja otti hänen synkiään pilveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 6, 'Hän antoi hänelle läsnäollessansa käskysanat, elämän ja viisauden lain, että hänen piti opettaman Jakobille hänen liittonsa ja Israelille hänen oikeutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 7, 'Hän korotti myös Aaronin. pyhäksi, hänen kaltaiseksensa, hänen veljensä Levin sukukunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 8, 'Hän teki ijankaikkisen liiton hänen kanssansa, ja antoi hänelle pappeuden kansan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 9, 'Hän vaatetti hänen kunniallisesti ja kauniisti, ja puetti kunniahameen hänen yllensä, ja kaunisti hänen kaikkinaisilla kaunistuksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 10, 'Hän valmisti hänelle kalliin käädyn, hän puki alaisen vaatteen hänen yllensä, pitkän hameen ja päällishameen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 11, 'Ja ripusti monta kultaista kulkuista ja nastaa hänen päällensä, aina ympärinsä, helisemään, kuin hän kävi ulos ja sisälle; ja se helinä piti kuuluman pyhään, jolla piti Jumalan edessä hänen kansaansa muistuttaman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 12, 'Ja pyhän hameen kullalla, sinisillä villoilla ja purpuralla neulotun, väkikilven rinnalle, valkeuden ja oikeuden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 13, 'Taitavasti ommellun kalliilla kivillä, joihin kahdentoistakymmenen Israelin sukukunnan nimet kaivetut olivat, ja kivien vuolialta kultaan sioitellut, että heitä Jumalan edessä piti muistettaman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 14, 'Kultalehden lakissa, johon pyhyys kaivettu oli, joka kaikki oli kaunis, kallis ja ihanainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 15, 'Jonka kaltaista ei ennen ole nähty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 16, 'Ei sitä saanut kenkään panna yllensä, mutta ainoastaan hänen poikansa ja hänen poikansa pojat ijankaikkiseen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 17, 'Hänen uhrinsa tehtiin kahdesti joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 18, 'Moses täytti hänen kätensä, Ja voiteli hänen pyhällä öljyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 19, 'Hänen kanssansa tehtiin liitto, että hän ja hänen poikansa piti häntä palveleman ijankaikkisesti; niinkauvan kuin taivaan päivät olivat, piti papit oleman siunaamassa hänen kansaansa hänen nimeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 20, 'Hän valitsi hänen kaikista elävistä, ruoka uhria ja savu-uhria uhraamaan Herralle makiaksi hajuksi ja muistoksi kansaa sovittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 21, 'Hän antoi hänen haltuunsa sanansa viran, opettaa Jakobille hänen todistuksensa, ja hänen laillansa Israelia valistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 22, 'Muut asettivat tosin itsensä häntä vastaan ja kadehtivat häntä korvessa, jotka Datanin ja Abiramin kanssa olivat, ja kiukuitseva Koran joukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 23, 'Mutta Herra näki sen, ja ei se kelvannut hänelle, ja he nieltiin julmassa vihassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 24, 'Hän antoi nähdä heissä kauhian ihmeen ja kulutti heitä tulellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 25, 'Hän kunnioitti myös vielä Aaronin, ja antoi hänelle perinnön, nimittäin, hän jakoi hänelle kaikki esikoiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 45, 26, 'Kaikkein muiden suhteen lähetti hän hänelle kaikkein ensin leipää kyllä; sillä heidän piti syömän Herran uhrin, jonka hän hänelle ja hänen siemenellensä antoi Mutta ei heillä pitänyt osaa maassa oleman, eikä perintöä ottaman kansan seassa, mutta Herra itse oli heidän osansa ja perintönsä. Pinehas Eleatsarin poika oli kolmas tässä kunniassa; hänellä oli kiivaus Jumalan pelvossa. Ja kuin kansa lankesi pois, oli hän uskollinen, vahva ja rohkia, ja sovitti Israelin. Sentähden annettiin hänelle rauhan liitto, hallitsemaan pyhää kansaa, jonka myös piti ynnä siemenensä kanssa pitämän papillisen kunnian ijankaikkisesti. Niinkuin liitto tehtiin Davidin kanssa Juudan sukukunnasta, että ainoastaan hänen pojistansa piti yksi kuninkaaksi tuleman; Niin myös Aaron ja hänen siemenensä piti oleman sen perilliset, opettamassa meille viisautta ja hallitsemassa hänen kansaansa oikein, ettei heidän säätynsä ja kunniansa olisi hukkunut, mutta pysynyt heillä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 1, 'Josua Naven poika oli uljas sodassa ja propheta Moseksen jälkeen, joka nimensä jälkeen sai suuren voiton Jumalan valittuin pelastuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 2, 'Ja he kostivat vihamiehensä, jotka nousivat heitä vastaan, että lsrael olis saanut perimisensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 3, 'Hän sai kunnian, kuin hän ojensi kätensä, ja veti miekkansa kaupungeita vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 4, 'Kuka on ennen häntä niin miehuullinen ollut? Hän otti vangiksi Herran viholliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 5, 'Hänen tähtensä seisoi aurinko, ja yksi päivä oli niin pitkä kuin kaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 6, 'Hän avuksensa huusi korkeinta ja väkevintä, kuin hän vihollisensa ahdisti kaikilta puolilta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 7, 'Ja suuri Herra kuuli hänen rukouksensa, ja antoi suuret kivirakeet langeta vihollisten päälle, ja tappoi ne uppiniskaiset mennessänsä alas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 8, 'Että pakanat havaitsivat, mitkä sota-aseet näillä olivat, ja että Herra itse oli läsnä sodassa, ja ajoi jaloja takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 9, 'Ja Moseksen aikana teki hän myös Kaleb Jephunnen pojalle hyvän työn, kuin he olivat joukkoa vastaan, ja estivät kansaa syntiä tekemästä, ja asettivat vahingollisen kapinan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 10, 'Sentähden vapahdettiin ainoastaan kaksi niistä kuudestasadasta tuhannesta miehestä, jotka kansan johdattivat perintöönsä, siihen maahan, jossa rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 11, 'Ja Herra piti Kalebin väessänsä hamaan vanhuuteen asti menemään vuorelle maakunnassa, jonka siemen myös piti perinnön,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 12, 'Että kaikkein Israelin lasten piti näkemän, kuinka hyvä on kuulla Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 13, 'Ja tuomarit, jokainen nimeltänsä, jotka ei epäjumalia palvelleet eikä Herrasta luopuneet, myös ylistetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 14, 'Heidän luunsa vielä nytkin viheriöitsevät, kussa he makaavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 15, 'Ja heidän nimensä ylistetään heidän lapsissansa, jotka sen perineet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 16, 'Ja Samuel, Herran propheta, joka Jumalaltansa rakastettiin: hän asetti valtakunnan, ja voiteli päämiehet hänen kansaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 17, 'Hän tuomitsi kansaa Herran lain jälkeen, ja Herra katsoi jälleen Jakobin puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 18, 'Ja hän löydettiin vaaksi ja uskolliseksi prophetaksi, että hän ymmärrettäisiin olevan ennustuksessansa totinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 19, 'Hän rukoili väkevää Herraa, kuin hän vihollistansa joka haaralta ahdisti, ja uhrasi nuoria karitsoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 46, 20, 'Ja Herra jylisi alas taivaasta, ja antoi kuulla itsensä suuressa tulessa, Ja löi Tyron päämiehet ja Philistean herrat. Ja loppunsa edellä ennen kuolemaansa tunnusti hän, Herran ja hänen voideltunsa edessä, ettei hän yhdeltäkään ihmiseltä ollut rahaa ottanut, ei yhtään kenkääkään, niin ettei yksikään ihminen taitanut häntä laittaa. Ja kuin hän pois nukkunut oli, ennusti hän ja ilmoitti kuninkaalle hänen loppunsa, ja antoi itsensä kuulla maasta, ja aavisti jumalattoman kansan hukkuvan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 1, 'Davidista, Salomonista, Rehabeamista ja Jerobeamista. Sitte ennusti Davidin aikana Natan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 2, 'Ja David oli Israelin lapsista valittu, ja niinkuin lihava uhri Jumalalle omistettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 3, 'Hän oli jalopeurain kanssa niinkuin vohlan, ja karhuin kanssa niinkuin karitsain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 4, 'Nuorella ijällänsä tappoi hän sankarin, ja otti pois häpiän kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 5, 'Hän nosti kätensä ja paiskasi lingolla ja löi maahan ylpiän goljatin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 6, 'Sillä hän rukoili Herraa, Korkeinta, joka vahvisti hänen kätensä lyömään väkevää sotamiestä, ja korotti niin kansansa sarven.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 7, 'Hän antoi häntä ylistää kymmenentuhannen edestä, ja kunnioitti häntä Jumalan siunauksella, että hän sai kuninkaan kruunun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 8, 'Hän löi viholliset joka paikassa, ja löi maahan vastaanseisoviansa Philistealaiset, ja musersi rikki heidän sarvensa niinkuin se vielä tänäpänä rikki muserrettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 9, 'Jokaisesta työstä kiitti hän Pyhää, Korkeinta, kauniilla veisulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 10, 'Hän veisasi kaikesta sydämestä, ja rakasti sitä, joka hänen tehnyt oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 11, 'Hän asetti laulajat alttarin tykö, ja antoi heidän veisata hänen suloisia veisujansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 12, 'Hän asetti kunniallisesti pidettää pyhäpäivät, että koko ajastajassa pitäis kauniisti vuodenajat muistettaman Herran nimen kiitoksella, veisaten aamulla pyhässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 13, 'Herra antoi hänen syntinsä anteeksi ja korotti hänen sarven ijankaikkisesti, ja teki liiton hänen kanssansa, että valtakunta ja kuninkaallinen istuin Israelissa piti hänellä pysymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 14, 'Hänen jälkeensä tuli hänen viisas poikansa Salomo kuninkaaksi, jolle isä oli saattanut levon, hallitsemaan rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 15, 'Sillä Jumala oli kaikki sodat asettanut ympäristöllä, että hän olis rakentanut hänen nimellensä huoneen, Ja pannut ylös pyhän, pysymään ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 16, 'Oi kuinka hyvin sinä olet oppinut nuorella ijälläs, ja sinä olit täynnä ymmärrystä, niinkuin vesi, joka maan peittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 17, 'Ja sinä olet kaikki täyttänyt sananlaskuilla ja opetuksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 18, 'Ja sinun nimes kuullun kaukana luodoissa ja sinun rauhas tähden rakastettiin sinua, ja paljon sinusta pidettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 19, 'Kaikki maakunnat ihmettelivät sinun veisujas, sananlaskujas, vertauksias ja selityksiäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 20, 'Ja kiittivät Herraa, joka Israelin Jumalaksi kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 21, 'Sinä saatit kultaa niin paljon kuin tinaa, ja hopiaa niin paljon kuin lyijyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 22, 'Sinun sydämes suostui vaimoihin, ja sinä annoit eksyttää sinus, ja annoit virheen tulla kunniaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 23, 'Sinä teit, että sinun lapses hyljättiin, ja viha sattui sinun jälkeentulevaisiis, sinun tyhmyytes rangaistukseksi, kuin valtakunta hajoitettiin ja Ephraimissa epäjumalinen valtakunta tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 24, 'Mutta ei Herra palannut laupiudestansa, eikä muuttanut luvattua työtänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 47, 25, 'Ei myös peräti kadottanut valittunsa jälkeentulevia eikä hyljännyt rakastajansa siementä; Mutta tallella piti jotakin Jakobin kansasta ja juuren Davidista. Ja Salomo nukkui isänsä kanssa, Ja jätti siemenestänsä Rehabeamin, taitamattoman miehen, kansaa hallitsemaan, jolla ei ymmärrystä ollut, joka neuvollansa saatti kansan luopumaan; Ja Jerobeamin Nebatin pojan, joka Israelin vei epäjumalan palvelukseen, ja saatti Ephraimin syntiä tekemään, Joiden synnit olivat monet, että he viimein ajettiin pois maaltansa; Sillä he sääsivät kaikkinaiset epäjumalan palvelukset, siihenasti että kosto tuli heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 1, 'Ja propheta Elia tuli edes niinkuin tuli, ja hänen sanansa paloi niinkuin tulisoitto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 2, 'Hän antoi heille kovat vuodet tulla, ja vähensi heitä kiivaudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 3, 'Sillä hän sulki Herran sanalla taivaan, ja antoi kolmasti tulen tulla alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 4, 'Oi kuinka kuuluisa olet sinä Elia sinun tunnustähdeilläs ollut! kuinka on niin kuuluisa kuin sinä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 5, 'Sen Korkeimman sanalla olet sinä herättänyt kuolleen, ja toit hänen haudasta jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 6, 'Sinä kukistit, ylpiät kuninkaat vuoteistansa, ja hukutit heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 7, 'Sinä kuulit Sinain vuorella tulevaisen rangaistuksen ja koston Horebilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 8, 'Sinä ennustit kuninkaille, jotka piti rankaiseman, ja asetit sinun jälkees prophetat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 9, 'Sinä otettiin pois tuulispäässä, tulisilla rattailla ja hevosilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 10, 'Sinä lähetettiin rankaisemaan ajallansa, ja asettamaan vihaa ennenkuin hirmuisuus tuli, kääntämään isäin sydämet lasten tykö, ja saattamaan Jakobin suvulle oikian menon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 11, 'Autuaat ovat ne, jotka sinun nähdä saavat, ja sinun ystävyytes tähden kunnioitetuksi tulevat; siellä me saamme oikian elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 12, 'Kuin Elia oli poissa tuulessa, tuli hänen henkensä Elisan päälle runsaasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 13, 'Ei hän peljännyt aikanansa yhtään päämiestä, ei myös kenkään häntä voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 14, 'Ei hän antanut itsiänsä vaatia, ja kuin hän jo kuollut oli, niin hänen ruumiinsa vielä sitte ennusti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 15, 'Hän teki eläissänsä tunnustähtiä ja kuolleena ihmeitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 16, 'Näistä kaikista ei kuitenkaan kansa kääntynyt parannukseen, eikä lakanneet synneistänsä, siihenasti kuin he ajettiin ulos omasta maastansa, ja hajoitettiin kaikkiin maakuntiin ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 17, 'Kuitenkin jäi piskuinen joukko ja päämies Davidin huoneesen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 18, 'Joiden seassa muutamat tekivät sitä, mikä Jumalalle kelpasi; mutta muutamat tekivät syntiä sangen raskaasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 19, 'Hiskia vahvisti kaupunkinsa, ja johdatti sinne veden; hän antoi kaivaa kallioita ja tehdä kaivoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 20, 'Hänen ajallansa meni Sanherib ylös, ja lähetti Rabsaken, joka nosti kätensä Zionia vastaan, ja uhkasi sitä suurella ylpeydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 21, 'Silloin värisi heidän sydämensä ja kätensä, ja he surkuttelivat itsiänsä niinkuin vaimo lapsen kivussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 22, 'He rukoilivat laupiasta Herraa, ja nostivat kätensä hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 23, 'Ja Pyhä taivaasta kuuli nopiasti heidän rukouksensa, ja pelasti heitä Jesaian kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 24, 'Hän löi Assyrialaisten sotajoukon, ja hänen enkelinsä hukutti heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 48, 25, 'Sillä Hiskia teki sitä, mikä Herralle kelpasi, ja pysyi isänsä Davidin tiellä, niinkuin Jesaia hänen opettanut oli, joka oli suuri ja totinen propheta ennustuksissansa. Sillä ajalla kävi aurinko takaperin, ja hän pitensi kuninkaan ijän. Hän ennusti suurella hengellä, mitä viimeiseltä tapahtuva oli, Ja antoi murheellisille Zionissa lohdutuksen, jolla he itsensä ijankaikkisesti piti lohduttaman. Hän ilmoitti tulevaiset ja salaiset asiat, ennenkuin ne tapahtuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 1, 'Josian muisto on niinkuin kallis savu taitavasti tehty voiteen keittäjältä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 2, 'Joka on makia suussa niinkuin hunaja, ja niinkuin kanteleen soitto viinaa juotaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 3, 'Hänellä oli suuri lahja kääntää kansaa, ja panna pois epäjumalan kauhistusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 4, 'Hän piti sydämensä Herran tykö, ja ojensi jälleen oikian jumalanpalveluksen, kuin maakunta oli täynnä epäjumalan palvelusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 5, 'Kaikki kuninkaat, paitsi Davidia, Hiskiaa ja Josiaa, ovat rikkoneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 6, 'Sillä he hylkäsivät Korkeimman lain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 7, 'Senjälkeen saivat Juudan kuninkaat lopun; sillä heidän täytyi valtakuntansa antaa muille, ja kunniansa muukalaiselle kansalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 8, 'Jotka polttivat valitun pyhän kaupungin, ja tekivät hänen kujansa autioksi, niinkuin Jeremia oli ennustanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 9, 'Jota he pahoin vaivasivat, joka äitinsä kohdussa prophetaksi valittu oli, hävittämään, särkemään ja kukistamaan, niin myös jälleen rakentamaan ja istuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 10, 'Hesekiel näki Herran kunnian näyssä, jonka hän näytti hänelle Kerubimin rattaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 11, 'Hän ennusti vihollisia vastaan, ja ilmoitti lohdutuksen niille, jotka tekivät oikeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 12, 'Ja kahdentoistakymmenen prophetan luut vielä nyt viheröitsevät, kussa he makaavat, sillä he ovat lohduttaneet Jakobia ja luvanneet vapauden, johon heidän lujasti luottaman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 13, 'Kuinka me ylistämme Serubabelia? joka oli niinkuin sormus oikiassa kädessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 14, 'Ja Jesusta Josedekin poikaa, jotka aikanansa templin rakensivat, ja Herralle pyhän huoneen jälleen tekivät ijankaikkiseksi kunniaksi pysymään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 15, 'Ja Nehemiaa pitää aina kiitettämän, joka meille kukistetut muurit jälleen rakensi, ja sioitti portit ja teljet, ja rakensi huoneemme jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 49, 16, 'Ei ole maan päällä yhtään luotu Enokin vertaiseksi, joka on otettu pois maasta; Ei Josephinkaan, joka veljeinsä herra oli ja kansansa holhoja, jonka luut vietiin kotia jälleen. Set ja Bem olivat suuressa kunniassa kansan seassa. Mutta Adam on kunnioitettu kaikkein eläväin seassa, joka kaikkein ensin Jumalalta luotiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 1, 'Simon Onian poika, ylimmäinen pappi, joka aikanansa rakensi käytävät huoneen ympärille, ja teetti sinne patsaat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 2, 'Ja korotti perustuksen kahta sen vertaa ylemmä, ja valmisti ympärikäytävän templin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 3, 'Hänen aikanansa olivat lähteet soenneet, jotka hän vaskella varusti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 4, 'Hän murehti kansansa vahinkoa, ja vahvisti kaupungin vihollista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 5, 'Hän teki kunniallisen työn, joka antoi kansan tulla jälleen oikiaan järjestyksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 6, 'Kuin hän tuli ulos huoneesta esiripun eteen, niin hän valisti kuin kointähti pilven lävitse, niinkuin täysi kuu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 7, 'Niinkuin aurinko paistaa Korkeimman templin päälle, ja niinkuin taivaankaari on hänen kauneudessansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 8, 'Niinkuin kaunis kukkanen keväällä, ja niinkuin kukkaset veden reunalla, niinkuin pyhän savun puu keväällä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 9, 'Niinkuin sytytetty pyhä savu astiassansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 10, 'Niinkuin kultainen astia, kaikkinaisella kalliilla kivillä kaunistettu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 11, 'Niinkuin hedelmällinen öljypuu ja niinkuin korkia sypressipuu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 12, 'Kuin hän puki yllensä kauniin pitkän hameen ja koko puvun, ja tuli pyhän alttarin tykö, silloin kaunisti hän kaiken pyhän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 13, 'Mutta kuin hän otti uhrin kappaleet pappein käsistä, ja seisoi tulen tykönä, joka alttarilla paloi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 14, 'Silloin seisoivat hänen veljensä hänen ympärillänsä niinkuin istutettu sedripuu Libanonissa, ja piirittivät hänen niinkuin palmupuun oksat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 15, 'Ja kaikki Aaronin pojat kunniassansa, ja Herran uhrit olivat heidän käsissänsä koko Israelin sukukunnan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 16, 'Ja hän päätti virkansa alttarin edessä, ja teki niin Korkeimmalle ja Kaikkivaltiaalle kauniin uhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 17, 'Hän ojensi kätensä juomauhrin kanssa, ja uhrasi punaista viinaa, ja vuodatti alttarin pohjaan makiaksi hajuksi Korkeimmalle, joka on kaikkein Kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 18, 'Silloin huusivat Aaronin pojat korkiasti, ja puhalsivat vaskitorviin, tekivät suuren huminan, että heitä muistettaisiin Korkeimman edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 19, 'Silloin kaikki kansa lankesi äkisti maahan kasvoillensa, ja rukoili Herraa kaikkivaltiasta, korkeinta Jumalaansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 20, 'Ja veisaajat kiittivät häntä psalmeilla, että se kajahti koko huoneessa siitä suloisesta äänestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 21, 'Ja kansa rukoili korkeinta Jumalaa olemaan armollisen, siihenasti kuin jumalanpalvelus loppui ja he virkansa päättäneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 22, 'Kuin hän jälleen meni alas, niin hän ojensi kätensä koko Israelin seurakunnalle, ja antoi heille suullansa Herran siunauksen, ja toivotti heille terveyden hänen nimeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 23, 'Niin rukoilivat he jälleen, ja ottivat vastaan siunauksen Korkeimmalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 24, 'Ja sanoivat: kiittäkäät nyt kaikki Jumalaa, joka suuria töitä tekee kaikissa paikoissa, joka meitä elävinä varjelee hamasta äidin kohdusta, ja tekee meille kaikkea hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 25, 'Hän antakoon meille iloisen sydämen, ja lainatkoon rauhan joka paikassa Israelissa meidän elinaikanamme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 26, 'Ja että hänen armonsa aina pysyis meidän tykönämme, ja vapahtais meitä, niinkauvan kuin me elämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 27, 'Kahtalaista väkeä vihaan minä sydämestäni, ja kolmannelle olen minä niin julma, etten minä ole kellekään niinkuin heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 28, 'Samarialaisille, Philistealaisille ja hullulle väelle Sikemissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 50, 29, 'Tämän opin ja viisauden on tähän kirjaan kirjoittanut Jesus Sirakin poika Jerusalemista, ja on vuodattanut sydämestänsä tämän opetuksen. Autuas on se, joka itsensä tähän harjoittaa ja tämän panee sydämeensä: hän tulee viisaaksi, Ja jos hän sen jälkeen tekee, niin hän on kaikkiin kelvollinen; sillä Herran vaikeus johdattaa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 1, 'Minä kiitän sinua, Herra Kuningas, ja ylistän sinua, Jumala, minun vapahtajani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 2, 'Minä kiitän sinun nimeäs, ettäs minun varjelukseni ja apuni olet, ja olet lunastanut minun ruumiini kadotuksesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 3, 'Viekkaan kielen paulasta ja niistä, jotka valheella liikkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 4, 'Ja olet auttanut minua vihollisia vastaan, ja vapahtanut minua sinun suuren ja korkiasti ylistettävän laupiutes jälkeen niiden kiljunnasta, jotka minun niellä tahtoivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 5, 'Niiden kädestä, jotka minun henkeni perään seisoivat, ja suuresta murheesta, jossa minä makasin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 6, 'Tulisista kekäleistä, jotka minun olivat piirittäneet, keskeltä tulta, etten minä siinä palanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 7, 'Syvästä helvetin juovasta, petollisista panettelioista, valhettelioista kuninkaan edessä ja väärästä tuomiosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 8, 'Minä olin sangen läsnä kuolemaa, ja minun elämäni tahtoi vajota helvettiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 9, 'Minä olin piiritetty, ja ei kenkään auttanut minua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 10, 'Minä etsin ihmisiltä apua, ja en löytänyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 11, 'Silloin minä ajattelin sinun laupiuttas, Herra ja kuinka sinä aina auttanut olet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 12, 'Sillä sinä autat kaikkia niitä, jotka sinua odottavat, ja pelastat heitä pakanain käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 13, 'Minä rukoilin Jumalaa heidän julmuuttansa vastaan, ja rukoilin lunastusta kuolemasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 14, 'Ja avuksi huusin Herraa, minun Isääni ja hallitsiaani, ettei hän hylkäisi minua tuskassa, kuin ne kovat sydämestä pukkailivat, ja ei minulla yhtään apua ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 15, 'Minä kiitän sinun nimeäs lakkaamatta, ja ylistän ja kiitän sinua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 16, 'Sillä minun rukoukseni tuli kuulluksi, ja sinä olet auttanut minua kadotuksesta ja kaikesta pahasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 17, 'Sentähden tahdon minä kiittää ja ylistää sinua, Herra, ja kunnioittaa sinun nimeäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 18, 'Kuin minä vielä nuori olin ennenkuin minä tulin vietellyksi etsin minä viisautta julkisesti minun rukouksellani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 19, 'Templissä rukoilin minä sitä, ja tahdon etsiä hamaan loppuuni asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 20, 'Minun sydämeni iloitsi siitä, niinkuin silloin kuin viinamarjat kypsyvät. Minä kävin oikiaa tietä hänen tykönsä, ja etsin häntä nuoruudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 21, 'Minä etsin häntä, ja otin hänen vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 22, 'Silloin opin minä hyvin ja enensin minuani vahvasti hänen kauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 23, 'Sentähden minä kiitän häntä, joka minulle antoi viisauden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 24, 'Minä aioin tehdä sen jälkeen, ja ahkeroida hyvää, ja en tullut siitä häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 25, 'Minä pyysin sitä sydämestäni, ja ahkeroitsin tehdä sen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 26, 'Minä nostin käteni taivaasen päin; silloin valaistiin minun sieluni viisaudesta, että minä tunsin hulluuteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 27, 'Minä pyysin häntä vakuudella; hän ja minä olimme yksi sydän alusta, ja minä löysin hänen puhtaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 28, 'Sentähden en minä tule hyljätyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 29, 'Minun sydämeni ikävöitsi häntä, ja minä sain hyvän tavaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 51, 30, 'Herra on antanut minulle hänen kauttansa uuden kielen, sillä tahdon minä häntä kiittää. Lähestykäät tänne minun tyköni, te jotka ette mitään koetelleet ole, Ja tulkaat minun kouluuni, jos teiltä jotain puuttuu, niin te taidatte täällä oppia; sillä te olet te tosin suuresti janoovaiset. Minä olen avannut suuni ja olen opettanut: ajatelkaat nyt ja ostakaat viisautta, koska te sen ilman rahaa saada taidatte, Ja antakaat teidän niskanne hänen ikeensä alle, ja antakaat opettaa teitänne: nyt löytään hän sangen läsnä. Katsokaat minua: minulla on vähä aika ollut vaivaa ja työtä, ja olen löytänyt kuitenkin suuren lohdutuksen. Ottakaat oppi, niinkuin suuri hopiatavara, ja kätkekäät sitä niinkuin suurta kultaläjää. Iloitkaat Jumalan laupiudesta, ja älkäät hävetkö hänen kiitostansa. Tehkäät mitä teille on käsketty, niinkauvan kuin teillä aikaa on, niin hän teille ajallansa hyvin maksaa. Jesus Sirakin pojan kirjan loppu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Barokin kirja luetaan, ja,jutellaan, mitä se vaikutti. Tämä on se puhe, jonka Baruk Nerian poika, Mahasian pojan, Sedekian pojan, Zedein pojan, Helkian pojan, kirjoitti kirjaan Babelissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Viidentenä vuotena, seitsemäntenä päivänä kuukaudessa, siihen aikaan kuin Kaldealaiset olivat Jerusalemin voittaneet, ja sen tulella polttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Ja Baruk luki tämän kirjan Jekanjan, Joakimin pojan, Juudan kuninkaan edessä, ja kaiken kansan korvain kuullen, jotka sitä kuulemaan tulivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Ja päämiesten korvain edessä, ja kuningasten poikain edessä, ja vanhimpain edessä, ja kaiken kansan edessä, sekä pienten että suurten, jotka asuivat Babelissa Suddin virran tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Ja he itkivät, paastosivat ja rukoilivat totisesti Herran edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Ja kokosivat rahaa niin paljon kuin kullakin varaa oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Ja lähettivät Jerusalemiin papille Joakimille Helkan pojalle, Salomin pojan, ja (muille) papeille, ja kaikelle kansalle, jotka hänen kanssansa olivat Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Viemässä Juudan maalle ne Herran huoneen astiat, jotka muinen olivat otetut templistä pois, Sibanin kuun kymmenentenä päivänä: nimittäin, ne hopia-astiat, jotka Zedekia Hosian poika, Juudan kuningas, oli antanut tehdä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Sittekuin Nebukadnetsar Babelin kuningas oli vienyt pois Jekanjan ja päämiehet, ja vangit, ja voimalliset ja maan kansan Jerusalemista, ja tuonut Babeliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Ja he kirjoittivat heidän tykönsä näin: katso, me lähetämme teille rahaa, ostakaat sillä polttouhria, rikosuhria, suitsutusta, ja tehkäät ruokauhria ja uhratkaat se Herran meidän Jumalamme alttarilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Ja rukoilkaat Nebukadnetsarin, Babelin kuninkaan, hengen edestä, Ja hänen poikansa Belsatsarin hengen edestä, että heidän päivänsä olisivat niinkuin taivaan päivät maan päällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Niin Herra antaa meille voimaa, ja valaisee meidän silmämme, ja me saamme elää Babelin kuninkaan Nebukadnetsarin varjon alla, ja hänen poikansa Belsatsarin varjon alla, Ja parvella heitä kauvan, ja löydämme armon heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Ja rukoilkaat meidän edestämme Herraa meidän Jumalamme; sillä me olemme rikkoneet Herraa meidän Jumalaamme vastaan, ja hänen julmuutensa ja vihansa ei ole käännetty meistä pois, aina tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Ja lukekaat tämä kirja; sillä sentähden olemme me sen lähettäneet teille, että teidän pitäis sitä lukeman Herran huoneessa pyhäpäivinä ja vuoden ajoilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Ja sanokaat: Herra meidän Jumalamme on vanhurskas, mutta meidän täytyy hävetä., niinkuin se nyt tapahtuu niille Juudasta ja niille Jerusalemista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Ja meidän kuninkaillemme ja päämiehillemme, ja papeillemme ja prophetaillemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Että me Herran edessä rikkoneet olemme, ja emme häntä uskoneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Ja emme totelleet Herran meidän Jumalamme ääntä, että me olisimme vaeltaneet hänen käskynsä jälkeen, jotka hän meille on antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Ja siitä ajasta, kuin hän meidän isämme toi Egyptin maalta, aina tähän päivään asti, olemme me olleet Herralle meidän Jumalallemme kovakorvaiset, ja emme totelleet hänen ääntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Sentähden on nyt meidän päällemme tullut se rangaistus ja kirous, jonka Herra on julistanut palveliansa Moseksen kautta, kuin Herra johdatti meidän isämme ulos Egyptin maalta, antaaksensa meille maan, joka rieskaa ja hunajaa vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Ja emme totelleet Herran meidän Jumalamme ääntä, niinkuin prophetat meille sanoivat, jotka hän meille lähetti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Vaan jokainen meni pahan sydämensä ajatuksen jälkeen, ja palvelimme vieraita jumalia, ja teimme pahaa Herran meidän Jumalamme edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Ja Herra on pitänyt sanansa, jonka hän puhui meille ja meidän tuomareillemme, jotka Israelia hallitsivat, ja meidän kuninkaillemme ja päämiehillemme, ja Israelin ja Juudan miehille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Ja on antanut senkaltaisen suuren rangaistuksen tulla meidän päällemme, niin ettei sen vertaa taivaan alla ole tapahtunut kuin Jerusalemille, niinkuin Moseksen laissa on kirjoitettu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Että ihmisen piti syömän poikansa ja tyttärensä lihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ja hän antoi heidät pois orjaksi kaikkiin valtakuntiin, jotka joka paikassa ympärillä ovat, häväistykseksi ja kiroukseksi kaikkein kansain seassa, jotka ovat meidän ympärillämme, joiden sekaan Herra heidät hajoittanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Ja he ovat tulleet alimmaiseksi, ja ei ylimmäiseksi; sillä me olemme rikkoneet Herraa meidän Jumalaamme vastaan, siinä ettemme ole totelleet hänen ääntänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Herra meidän Jumalamme on vanhurskas, mutta meidän ja meidän isämme täytyy hävetä, niinkuin se nyt tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Kaikki se paha, minkä Herra on puhunut meitä vastaan, on tullut meidän päällemme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Ja emme ole rukoilleet Herraa, että jokaisen pitäis kääntymän pahan sydämensä ajatuksista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Ja Herra on valvonut meidän onnettomuudeksemme, jonka hän on antanut meidän päällemme tulla; sillä Herra on vanhurskas kaikissa töissänsä, jotka hän on meille käskenyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Mutta emme totelleet hänen ääntänsä, vaeltaaksemme Herran käskyin jälkeen, jotka hän meille antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Ja nyt Herra, Israelin Jumala! joka sinun kansas Egyptin maalta olet vienyt väkevällä kädellä, suurella voimalla ja korkialla vallalla, tunnustähtein ja ihmetten kautta, ja olet tehnyt sinun nimes, niinkuin se nyt on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Me olemme rikkoneet ja olleet jumalattomat, ja väärin tehneet kaikkia sinun käskyjäs vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Voi Herra meidän Jumalamme! lakkaa julmuudestas meitä vastaan, sillä me olemme juuri vähäksi joutuneet pakanain seassa, joihin sinä meidät hajoittanut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Kuule, Herra, meidän rukouksemme ja meidän anomuksemme, ja auta meitä sinun tähtes, ja anna meidän löytää armon heidän tykönänsä, jotka meidät ovat vieneet pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Että koko maailma tietäis sinun olevan Herran meidän Jumalamme! sillä Israel ja hänen siemenensä on nimitetty sinun nimes jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'Katso, Herra, sinun pyhästä huoneestas, ja ajattele meidän päällemme; kallista, Herra, korvas ja kuule;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Avaa silmäs, Herra, ja näe! sillä kuolleet tuonelassa, joiden henki on lähtenyt ruumiista, ei puhu Herran kunniasta ja vanhurskaudesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'Vaan sielu, joka on sangen murheellinen, ja käy kumarruksissa surkiasti, ja on silmänsä pian itkenyt puhki, ja isoovainen sielu ylistää, Herra, sinun kunniaas ja vanhurskauttas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Ja nyt Herra, meidän Jumalamme! me olemme edessäs meidän rukouksillamme, ei meidän isäimme ja meidän kuningastemme tähden, vaan sinun laupiutes tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Ettäs olet antanut julmuutes ja vihas tulla meidän päällemme, niinkuin sinä sinun palvelias prophetan kautta olet puhunut ja sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Näin sanoo Herra: kumartakaat teidän olkanne, ja antakaat teitänne Babelin kuninkaan alle, niin te saatte olla siinä maassa, jonka minä teidän isillenne olen antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Mutta jollette Herran ääntä kuule, antain teitänne Babelin kuninkaan alle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Niin minä Juudan kaupungeista ja Jerusalemista otan pois ilon ja riemun äänen, ja yljän ja morsiamen äänen, ja koko maan, pitää oleman autiona, ja ei kenenkään siinä asuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Mutta emme totelleet sinun ääntäs, että me olisimme antaneet itsemme Babelin kuninkaan alle; sentähden olet sinä vahva ollut sanoissas, jotka olet puhunut sinun palvelias prophetain kautta, niin, että meidän kuningastemme luut ja meidän isäimme luut haudoistansa pois heitetyt ja hajoitetut ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Niin että he päivällä auringossa ja yöllä kasteessa maanneet ovat, ja juuri surkiasti kuolleet nälän, miekan ja vankiuden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Ja Israelin huoneen ja Juudan huoneen pahuuden tähden olet sinä sinun huonees, kussa sinun nimeäs rukoillaan, antanut kukistettaa, niinkuin se tänäpänä tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Ja sinä, Herra meidän Jumalamme, olet meidän kanssamme juuri armollisesti ja kaiken sinun suuren laupiutes jälkeen tehnyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Niinkuin sinä palvelias Moseksen kautta puhunut olet, sinä päivänä, kuin sinä käskit hänen kirjoittaa sinun lakis Israelin lasten edessä, ja sanoit:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Jollette kuule minun ääntäni, niin pitää totisesti tämän joukon, joka on kyllä suuri, sangen vähäksi joutuman pakanain seassa, kuhunka minä heidät hajoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 30, 'Sillä minä tiedän, ettei he tottele minua; sillä se on kankia kansa. Mutta heidän pitää kääntymän sillä maalla, jossa he ovat vankina,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 31, 'Ja pitää oppiman tietämään minun olevan Herran heidän Jumalansa. Ja minä annan heille ymmärtäväisen sydämen ja korvat, jotka kuulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 32, 'Niin pitää heidän siis ylistämän minua sillä maalla, jossa he ovat vankina, ja ajatteleman minun nimeäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 33, 'Ja kääntymän kankeista niskoistansa ja rikoksistansa; sillä heidän pitää ajatteleman, kuinka heidän isäinsä käteen kävi, jotka olivat rikkoneet Herran edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 34, 'Ja minä vien heidät jälleen siihen maahan., jonka minä heidän isillensä, Abrahamille, Isakille ja Jakobille vannonut olin; ja heidän pitää siellä vallitseman, ja minä tahdon enentää heitä, ja en vähentää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 35, 'Ja tahdon tehdä ijankaikkisen liiton heidän kanssansa, niin että minä tahdon olla heidän Jumalansa ja heidän pitää oleman minun kansani.. Ja en tahdo enää ajaa pois minun kansaani Israelia maalta, jonka minä heille antanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Herra, Israelin Jumala! tässä suuressa ahdistuksessa ja tuskassa huudan minä sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Herra, Israelin Jumala! tässä suuressa ahdistuksessa ja tuskassa huudan minä sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Herra, Israelin Jumala! tässä suuressa ahdistuksessa ja tuskassa huudan minä sinua.');
