INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 35, 'Herra, Israelin Jumala! tässä suuressa ahdistuksessa ja tuskassa huudan minä sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 36, 'Herra, Israelin Jumala! tässä suuressa ahdistuksessa ja tuskassa huudan minä sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 37, 'Herra, Israelin Jumala! tässä suuressa ahdistuksessa ja tuskassa huudan minä sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Tämä on Jumalan käskysanain kirja ja laki, joka ijankaikkisesti pysyy. Kaikki, jotka sen pitävät, saavat elää, mutta jotka sen hylkäävät, niiden pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Palaja siihen, Jakob, jälleen ja rupee siihen, vaella sen valkeuden jälkeen, joka edessäs paistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Älä muille jätä kunniaas ja sinun tavaraas muukalaiselle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Oi autuaat me Israelissa! sillä Jumala on meille tahtonsa ilmoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Ole hyvällä mielellä, minun kansani, sinä Israelin ylistys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Te olette myydyt pakanoille, ei kadotukseen; mutta että te olette Jumalan vihoittaneet, olette te teidän vihollistenne haltuun annetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Sillä te olette vihoittaneet sen, joka teidät on luonut, siinä ettette ole Jumalalle, mutta perkeleille uhranneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Te olette unohtaneet ijankaikkisen Jumalan, joka teidät on luonut, ja murheelliseksi tehneet Jerusalemin, joka teidät on kasvattanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Sillä hän on nähnyt Jumalan vihan, joka teidän päällenne pitää tuleman, ja sanonut: kuulkaat, te Zionin asuvaiset! Jumala on antanut minulle suuren murheen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Sillä minä olen nähnyt minun poikaini ja tytärteni vankiuden, jonka Ijankaikkinen heidän päällensä on antanut tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Minä olen kasvattanut heidät ilolla, mutta itkulla ja murheella olen minä nähnyt heitä vietävän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Älköön kenkään iloitko minusta, että minä leski ja monelta hyljätty olen, minä olen hävitetty minun lasteni rikosten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Sillä he ovat poikenneet Jumalan laista, ja ei ole hänen oikeuttansa tunteneet; ei he ole eläneet Jumalan käskyn jälkeen, eikä pitäneet hänen käskyjänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Tulkaat tänne Zionin asuvaiset, ja julistakaat minun poikaini ja tytärteni vankius, jonka Ijankaikkinen on antanut tulla heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Sillä hän on antanut kansan kaukaa tulla heidän päällensä, julman kansan, tuntemattomasta kielestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Jotka ei karta vanhaa, eikä armahda lapsia. Ne ovat vieneet pois lesken rakkaat (pojat) ja yksinäiseltä tyttäret temmanneet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'Mutta kuinka minä taidan teitä auttaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Sillä joka tämän onnettomuuden on saattanut teidän päällenne, hän on pelastava teitä teidän vihollistenne käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Lähtekäät pois, te rakkaat lapset, lähtekäät pois, mutta minä olen hyljätty yksinäiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Minä olen riisunut ilovaatteeni ja pukenut päälleni murhevaatteet; minä tahdon huutaa Ijankaikkisen tykö kaikkena minun elinaikanani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Olkaat hyvällä mielellä, lapset, huutakaat Jumalan tykö, niin hän pelastaa teitä vihollisten vallasta ja käsistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Sillä vielä minä toivon Ijankaikkisen auttavan teitä, ja minä olen saava ilon Pyhältä, sen laupiuden tähden, joka teille pian meidän ijankaikkiselta Vapahtajaltamme on tapahtuva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Minä olen antanut teidän mennä murheella ja itkulla; mutta Jumala on antava teidät minulle jälleen ilolla ja riemulla ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Ja niinkuin Zionin asuvaiset ovat nähneet teidän vankiutenne, niin pitää myös heidän pian näkemän avun teidän Jumalaltanne, joka on tuleva teidän päällenne suurella kunnialla ja ijankaikkisella lohdutuksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Te lapset, kärsikäät kärsivällisesti sitä vihaa, joka Jumalalta teidän päällenne tulee; sillä sinun vihollises on vainonnut sinua, ja sinä olet pian näkevä hänen hävityksensä, ja polkeva hänen kaulansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 26, 'Minun lapsukaiseni pitää käymän pahaa tietä, he ovat viedyt pois niinkuin lauma vihollisilta ryöstetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 27, 'Olkaat hyvällä mielellä, te lapset, ja huutakaat Jumalan tykö; sillä hän, joka on antanut teitä vietää pois, ei ole teitä unhottava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 28, 'Sentähden niinkuin te olette ahkeroineet poikkeemaan Jumalasta pois, juuri niin myös nyt palatkaat, ja ahkeroitkaat kymmenen kertaa enempi etsimään Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 29, 'Sillä joka tämän rangaistuksen on antanut tulla teidän päällenne, hän on auttava teitä, ja ijankaikkisen ilon toimittava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 30, 'Jerusalem, ole hyvällä mielellä; sillä se on sinua lohduttava, jonka nimen jälkeen sinä nimitetty olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 31, 'Olkoon ne vaivaiset, jotka sinua vaivanneet ja sinun lankeemisestas iloinneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 32, 'Olkoon ne kaupungit vaivaiset, joita sinun lapses palvelleet ovat; ja vaivainen olkoon se, joka sinun lapses vankina pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 33, 'Sillä niinkuin hän sinun lankeemisestas iloinnut ja sinun hävityksestäs riemuinnut on, juuri niin pitää hänen murheelliseksi tuleman, kuin hän tulee hävitetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 34, 'Ja minä otan pois hänen suuren ilonsa, ja käännän hänen kerskauksensa valitusitkuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 35, 'Sillä tulen pitää hänen päällensä tuleman Ijankaikkiselta monta päivää, ja perkeleillä pitää siellä kauvan asumasia oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 36, 'Katso ympärilles, Jerusalem, itään päin, ja katso sitä lohdutusta, joka sinulle tulee Jumalalta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 37, 'Katso, sinun lapses, jotka ovat viedyt pois, tulevat; he tulevat kootut sekä idästä että lännestä, pyhän sanan kautta, ja iloitsevat Jumalan kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Riisu pois yltäs, Jerusalem, murhevaattees, ja pue ylles pyhä kaunistus Jumalalta ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Pue ylles Jumalan vanhurskauden hame, ja pane Ijankaikkisen kunnian kruunu päähäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Sillä Jumala on julistava sinun kunnias koko taivaan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Sillä sinun nimes pitää kutsuttaman Jumalalta ijankaikkisesti vanhurskauden rauhaksi ja jumalisuuden kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Nouse, Jerusalem, ja astu korkeuteen, ja katso ympärilles itään päin, ja katso lapsias, jotka sekä idästä että lännestä kootut ovat, pyhän sanan kautta, ja iloitsevat, että Jumala on taas ajatellut heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'He ovat jalkaisin vihollisilta viedyt pois sinun tyköäs, mutta Jumala tuo heitä sinun tykös korotettuna kunnialla, niinkuin valtakunnan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Sillä Jumala tahtoo alentaa kaikki korkiat vuoret ja pitkät rannat, ja laaksot täyttää maan tasalle, että Israel sais levollisesti vaeltaa Jumalan kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Mutta metsät ja kaikki hyvin hajavaiset puut pitää Jumalan käskystä Israelia varjooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Sillä Jumala on tuova Israelin tänne jälleen ilolla, jalolla lohdutuksellansa, laupiudellansa ja vanhurskaudellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Teidän rikostenne tähden, joita te olette tehneet Jumalaa vastaan, pitää te vietämän vangittuna Babeliin Nebukadnetsarilta, Babelin kuninkaalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Ja Babelissa pitää teidän oleman kauvan aikaa, nimittäin seitsemänkymmentä vuotta; sitte minä taas vien teitä sieltä rauhassa ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Mutta sillä välillä pitää teidän näkemän Babelissa olkapäillä kannettavan hopia-, kulta- ja puujumalia, joita pakanat pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Sentähden kavahtakaat, ettette tee senkaltaisia heidän perässänsä, ja ettette tule pakanain vertaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Ja kuin te saatte nähdä kansan, joka edellä ja perässä käy, rukoilevan epäjumalia, niin sanokaat sydämissänne: Herra, sinua pitää rukoiltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Sillä minun enkelini pitää oleman teidän tykönänne, ja hän on kysyvä teidän sieluinne perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Sillä heidän kielensä on tekiältä hyvin kaunistettu, ja sijattu kullalla ja hopialla, ja heillä ovat leikatut kielet; mutta ei ne ole oikiat kielet, eikä taida puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'He kaunistavat niitä kullalla, niinkuin neitsyttä, joka koreutta rakastaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Panevat kruunun niiden päähän; ja papit varastavat epäjumalilta hopiaa ja kultaa, ja kuluttavat keskenänsä, syövät ja juovat porttoin kanssa huorahuoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Ja kaunistelevat hopia-, kulta- ja puujumalia vaatteilla, niinkuin ne olisivat ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Mutta ei ne taida varjella itsiänsä ruosteelta ja koilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Ja jos purpurahame puetaan heidän yllensä, niin pitää tomu pyyhittämän pois, joka laskeutuu niiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Ja se kantaa valtikan kädessänsä niinkuin kuningas, ja ei taida rangaista yhtään, joka tekee häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Sillä on myös miekka ja kirves kädessä, mutta ei taida itsiänsä varjella varkailta ja ryöstäjiltä; siitä kyllä nähdään, ettei ne ole jumalat: sentähden älkäät niitä peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Niinkuin astia, jota tarvitaan, on kelpaamatoin, kuin se on särjetty, juuri niin on heidän epäjumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Kuin ne pannaan huoneisiinsa, niin niiden silmät tulevat täyteen tomua niiden jaloista, jotka tulevat sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Ja papit varjelevat epäjumalain templin ovilla, lukoilla ja teljillä, ettei ne ryöstäjiltä varastettaisi, niinkuin koska joku pannaan vankiuteen ja tallella pidetään, se kuin on tehnyt kuningasta vastaan ja on kuolemaan tuomittu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'He sytyttävät niiden eteen lamppuja, ja paljon enemmän kuin itse eteensä, ja ei ne kuitenkaan näe; ne ovat niinkuin malat huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Ja matelevaiset madot maan päällä syövät heidän sydämensä ja vaatteensa, ja ei ne kuitenkaan mitään tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Niiden kasvot ovat mustat huoneen savusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Yököt, pääskyset ja muut linnut istuvat heidän päänsä päälle, niin myös kissat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Josta te mahdatte ymmärtää, ettei ne ole Jumalat; sentähden älkäät niitä peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Kulta, joka niiden päälle pantu on kaunistukseksi, ei se kiillä, jos ei ne ruosteesta perata; ja kuin ne valettiin, ei ne mitään tunteneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 24, 'Kaikkinaisesta kalliista aineesta ovat ne tehdyt, joissa ei kuitenkaan ole henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 25, 'Ettei he taida käydä, niin pitää niitä olkapäillä kannettaman, josta ihmiset kyllä taitavat ne huonoiksi nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 26, 'Niiden pitää häpeemän, jotka niitä kunnioittavat, ettei ne eikä itse nousta taida, kuin he putoovat maahan, eikä liikuttaa itsiänsä, kuin joku ne panee johonkuhun paikkaan pystyälle, ja jos se kallistuu, ei se taida ojentaa itsiänsä ylös. Ja niinkuin uhri kuolleiden eteen, Juuri niin pannaan myös heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 27, 'Mutta heidän pappinsa tuhlaavat niiden uhrit, jotka niille annetaan, niin myös heidän vaimonsa koreilevat niistä, eikä anna siitä jotain vaivaiselle eli sairaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 28, 'Saastaiset vaimot ja ne, jotka makaavat lapsen vuoteessa, sattuvat heidän uhriinsa, josta te kyllä ymmärrätte, ettei ne ole jumalat; sentähden älkäät niitä peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 29, 'Ja mistä niitä pitäis Jumalaksi kutsuttaman? sillä vaimot korjaavat kulta-, hopia-, ja puujumalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 30, 'Ja papit istuvat heidän templissänsä leviällä kuorikapalla, ajelevat partansa, ja heillä on tukka päässänsä, istuvat paljaspäänä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 31, 'ulvovat ja huutavat epäjumalainsa edessä, niinkuin tapa on kuolleiden hautaamisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 32, 'Papit varastavat niiden vaatteet, ja vaatettavat niillä emäntänsä ja lapsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 33, 'Joko hyvää eli pahaa niille tehdään, niin ei ne kuitenkaan taida kostaa, eikä asettaa ketään kuninkaan virkaan, eli panna pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 34, 'Ei ne taida antaa rahaa eli kalua; jos joku jotain niille lupaa, ja ei sitä pidä, niin ei ne valvo sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 35, 'Ei ne taida yhtäkään ihmistä pelastaa kuolemasta, eikä auttaa heikkoa väkevältä, eikä yhtäkään sokiaa tehdä näkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 36, 'Ei ne taida ensinkään ihmistä auttaa hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 37, 'Ei ne armahda leskiä, eikä auta orpoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 38, 'Sillä ne ovat puu, kullalla ja hopialla kaunistetut, kiven kaltaiset, jotka vuoresta lohkaistaan; sen tähden pitää heidän häpiään tuleman, jotka niitä kunnioittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 39, 'Kuinka siis pitää ne jumalina pidettämän, eli niin kutsuttaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 40, 'Ei myös Kaldealaisetkaan heistä paljon pidä. Sillä koska he näkevät mykän, joka ei taida puhua, sen he vievät Belin eteen, ja sanovat: mykän pitää häntä rukoileman, niinkuin hän sen ymmärtäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 41, 'Ja vaikka he tietävät, ettei sillä ole henkeä, kuitenkin juoksevat he niiden tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 42, 'Mutta vaimot istuvat kirkon edessä, vyötetyt köydellä, ja kantavat hedelmiä uhriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 43, 'Ja jos joku, joka menee ohitse, ottaa yhden heistä, ja makaa hänen, niin se kehuu sitä muita vastaan, ettei he ole niin mahdolliset olleet kuin hän, että köysi olis heistä kirvotetuksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 44, 'Kaikki, mitä heiltä tapahtuu, se on sula petos; kuinka siis ne pitää jumalina pidettämän, eli niin kutsuttaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 45, 'Sepiltä ja kultasepiltä ovat ne tehdyt, ja mitä virkamiehet tahtovat, se pitää siitä tuleman, ei muuta mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 46, 'Ja jotka ne tehneet ovat, ei taida kauvan elää; kuinka ne ovat Jumalat, jotka heiltä tehdyt ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 47, 'Sillä he ovat jättäneet petoksen Ja häpiän jälkeentulevaisillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 48, 'Sillä kuin sota eli muutoin joku paha nousis, niin papit neuvoa pitävät keskenänsä, kuinka he heitänsä epäjumalinensa lymyttämän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 49, 'Sentähden kyllä taidetaan ymmärtää, ettei ne ole jumalat, jotka itseänsä, ei sodasta eikä muusta onnettomuudesta, varjella taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 50, 'Sillä ei ne kuitenkaan muu ole, kuin puujumalat, kullatut ja hopialla silatut; sentähden taidetaan tästälähin kyllä tietää, että se on petos, kaikille pakanoille ja kuninkaille ilmoitettu, että ei ne ole jumalat, vaan ihmisten käsillä tehdyt, ja ei niissä ole yhtään Jumalan työtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 51, 'Sentähden taitaa jokainen ymmärtää, ettei ne ole jumalat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 52, 'Sillä ei ne pane yhtään kuningasta maalle, eikä anna ihmisille sadetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 53, 'Ei ne hallitse eikä rankaise, enempi kuin linnutkaan, jotka tuulessa sinne ja tänne lentelevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 54, 'Kuin puujumalain, kullattuin ja hopialla silattuin jumalain huoneet tulelta poltetuksi tulevat, niin niiden papit juoksevat siitä pois, ja varjelevat itsensä vahingosta; mutta ne palavat niinkuin muutkin malat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 55, 'Ei ne taida olla kuninkaita eli jotakuta sotaväkeä vastaan. Kuinka siis niitä pitää jumalina pidettämän, eli siksi kutsuttaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 56, 'Puujumalat, hopialla silatut jumalat ja kullatut jumalat ei taida itsiänsä varkailta ja ryöstäjiltä varjella; sillä ne ovat heitä väkevämmät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 57, 'Niin että, kuin he ryöstävät heidät ja riisuvat heidät alasti, ottavat heidän kultansa, hopiansa, vaatteensa, ja pakenevat; niin ei ne taida auttaa itseänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 58, 'Sen tähden on yksi kuningas paljoa parempi, joka taitaa osoittaa voimansa, eli tarpeellinen talon kappale, joka talossa tarvitaan, eli ovi, joka varjelee huoneen, eli puupatsas kuninkaallisessa salissa, kuin väärät jumalat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 59, 'Aurinko, kuu ja tähdet paistavat, ja ovat kuuliaiset siinä, mihinkä Jumala heitä käskee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 60, 'Niin myös pitkäisen leimaus valaisee, niin että se nähdään; tuuli puhaltaa kaikessa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 61, 'Ja kuin Jumala käskee pilvet juoksemaan koko maailman ylitse, niin he tekevät, mitä hän heille käskee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 62, 'Niin myös tuli ylhäältä polttaa ja kuluttaa vuoret ja metsät, ja tekee, mitä hänen on käsketty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 63, 'Mutta epäjumalat ei taida liikuttaa itsiänsä, eikä jotain tehdä; sen tähden ei pidä niitä pidettämän jumalina, eikä niin kutsuttaman, sillä ei ne taida rangaista eikä auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 64, 'Että te nyt tiedätte, ettei ne ole jumalat, niin älkäät myös niitä peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 65, 'Sillä ei ne taida kuninkaita kirota eikä siunata,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 66, 'Ei myös näyttää pakanoille jotain ihmettä taivaassa, ei valaista niinkuin aurinko, eikä valoa antaa niinkuin kuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 67, 'Järjettömät luontokappaleet ovat paremmat niitä, ne taitavat juosta luolaan ja varjella itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 68, 'Sentähden on se peräti selkiä, ettei ne ole jumalat; sentähden älkäät niitä peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 69, 'Sillä niinkuin ei peljätys taida mitään varjella yrttitarhassa, niin ovat myös heidän epäjumalansa, kullatut ja hopialla silatut jumalat, ei mihinkään kelpaavaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 70, 'Ja niinkuin pensas yrttitarhassa, jonka päällä kaikkinaiset linnut istuvat, eli niinkuin kuollut, joka on haudassa, niin ovat heidän puujumalansa, kullatut ja hopialla silatut jumalat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 71, 'Ja siitä taidetaan ymmärtää, ettei ne ole jumalat, sillä purppuravaate, joka heidän yllänsä on, syödään koilta, ja ne itse kanssa viimein, niin että jokainen heitä sylkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 72, 'Oi sitä onnellista ihmistä, joka on vanhurskas, jolla ei yhtään epäjumalaa ole! ei se tule nauruksi eikä pilkaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 73, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Ja Asaria seisoi keskellä tulista pätsiä, avasi suunsa, rukoili ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Ole kiitetty Herra, meidän isäimme Jumala, ja sinun nimes olkoon ylistetty ja kunnioitettu ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Sillä sinä olet hurskas kaikissa, mitä sinä meille tehnyt olet; kaikki sinun työs ovat totiset, ja mitä sinä teet, se on oikia, ja kaikki sinun tuomios ovat laittamattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Sinä teet meille oikein, ettäs meitä rangaissut olet senkaltaisella rangaistuksella, jonka sinä meidän päällemme olet antanut tulla, ja Jerusalemin, meidän isäimme pyhän kaupungin päälle; tosin sinä teet siinä oikein meidän synteimme tähden. 29, Sillä me olemme syntiä ja pahoin tehneet, että me sinusta luopuneet olemme ja joka paikassa tehneet sinua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Emme myös ole totelleet sinun käskyjäs, emmekä niistä lukua pitäneet, että me olisimme tehneet niiden jälkeen, niinkuin sinä meille käskenyt olit, että me menestyisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Sentähden olet sinä oikein tehnyt, ettäs ne kaikki olet antanut tulla meidän päällemme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Ja antanut meitä vihollistemme, jumalattomain ja pahain ihmisten, ja väärän ja julmimman: kuninkaan käsiin maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Ja emme rohkene suutamme avata: niin me olemme häpiän ja naurun alaiseksi tulleet sinun palveliais edessä ja kaikkein niiden edessä, jotka sinua pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Mutta älä kuitenkaan meitä peräti hylkää, sinun pyhän nimes tähden, ja älä heitä pois sinun liittoas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Ja älä ota laupiuttas meiltä pois, Abrahamin, rakkaan ystäväs; tähden, ja sinun palvelias Isaakin, ja Israelin sinun pyhäs tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Joille sinä olet luvannut heidän siemenensä lisätä niinkuin tähdet taivaassa ja sannan meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Sillä me olemme halvemmaksi tulleet kaikkia pakanoita ja olemme nyt kaikkein suurimmasti ylönkatsotut maan päällä, meidän synteimme tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Ettei meillä yhtään ruhtinasta, prophetaa eikä opettajaa ole, ei polttouhria eikä jokapäiväistä uhria, ei ruokauhria eikä suitsutusta, ei myös ole yhtään paikkaa, kussa me sinun edessäs uhraisimme ja löytäisimme armon;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Vaan särjetyllä sydämellä ja murheellisella hengellä tulemme me sinun etees, niinkuin me toisimme polttouhria oinaista ja mulleista, ja monta tuhatta lihavaa lammasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Niin anna meidän uhrimme tänäpänä sinulle kelvata ja otolliset olla; sillä et sinä anna niitä häpiään tulla, jotka sinun päälles toivovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Näin tulemme me nyt kaikella sydämellä ja etsimme sinun kasvojas pelvolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Sen tähden älä anna meidän häpiään tulla, vaan tee meille, Herra, sinun armos ja suuren laupiutes jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Ja kirvota meitä sinun ihmeellisten tekois perästä, ja anna sinun nimelles kunnia:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Että ne häpeäisivät, jotka sinun palvelioilles pahaa tekevät, ja häpiään tulisivat sinun suuren voimas edessä, että heidän voimansa kukistetuksi tulis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Että he ymmärtäisivät sinun olevan Herran ainoan Jumalan, suuressa kunniassa maanpiirin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Ja kuninkaan palveliat, jotka heidät pätsiin heittäneet olivat, ei lakanneet, vaan heittivät lakkaamatta tulikiveä, pikiä, rohtimia ja kuivia varpuja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Että liekki löi pätsistä yhdeksänviidettäkymmentä kyynärää korkialle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Ja kulutti ympäriltänsä ja poltti Kaldealaiset, joihinka se ulottui, pätsin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Mutta Herran enkeli käveli heidän kanssansa, jotka Asarian tykönä pätsissä olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Ja ajoi ulos tulen liekin pätsistä, ja teki pätsissä niinkuin kylmän kasteen, ettei tuli ensinkään heihin sattunut eikä polttanut eli vahingoittanut heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Silloin rupesivat ne kolme toinen toisensa kanssa veisaamaan, kiittivät ja ylistivät Jumalaa pätsissä, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Kiitetty ole sinä, Herra, meidän isäimme Jumala! ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti. Kiitetty olkoon sinun kunniallinen ja pyhä nimes, ja se pitää kiitetty ja ylistetty oleman ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Kiitetty ole sinä sinun pyhässä ja kuuluisassa templissäs, ja sinun pitää kiitetyn ja ylistetyn oleman ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Kiitetty ole sinä, joka istut Kerubimin päällä ja näet syvyyteen, ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Kiitetty ole sinä sinun kunniallisella kuninkaallisella istuimellas, ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Kiitetty ole sinä taivaan vahvuudessa, ja sinua pitää kiitettämän ja ylistettämän ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 32, 'Kiittäkään Herraa kaikki hänen työnsä, ja niiden pitää häntä kunnioittaman ja ylistämän ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 33, 'Te taivaat, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 34, 'Kiittäkäät Herraa, te Herran enkelit, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 35, 'Kaikki vedet taivasten päällä, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 36, 'Kaikki Herran sotajoukko, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 37, 'Aurinko ja kuu, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 38, 'Kaikki tähdet taivaassa, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 39, 'Sade ja kaste, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 40, 'Kaikki tuulet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 41, 'Tuli ja palavuus, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti. 67, Räntä ja rakeet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 42, 'Päivä ja yö, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 43, 'Vaikeus ja pimeys, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 44, 'Jää ja pakkanen, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 45, 'Härmä ja lumi, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 46, 'Pitkäisen leimaus ja pilvet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 47, 'Maa kiittäkään Herraa, kunnioittakaan ja ylistäkään häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 48, 'Vuoret ja kukkulat., kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 49, 'Kaikki, mitä maan päällä kasvaa, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 50, 'Lähteet kiittäkään Herraa, kunnioittakaan ja ylistäkään häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 51, 'Meret ja virrat, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 52, 'Valaskalat ja kaikki, kuin vesissä liikkuu, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä 79. Kaikki linnut taivaan alla, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 53, 'Kaikki metsän pedot ja eläimet, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 54, 'Te ihmisten lapset, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 55, 'Israel kiittäkään Herraa, kunnioittakaan ja ylistäkään häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 56, 'Te Herran papit, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 57, 'Te Herran palveliat, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 58, 'Te vanhurskasten henget ja sielut, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 59, 'Te pyhät, jotka raadolliset ja murheelliset olette, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 60, 'Anania, Asaria ja Misael, kiittäkäät Herraa, kunnioittakaat ja ylistäkäät häntä ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 61, 'Sillä hän on meitä helvetistä pelastanut ja auttanut meitä kuolemasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 62, 'Ja on pelastanut meidät tulisesta pätsistä, ja on meidät tulen keskellä varjellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 63, 'Kiittäkäät Herraa; sillä hän on hyvä ja hänen hyvyytensä pysyy ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 64, 'Kaikki, jotka Herraa pelkäävät, kiittäkään kaikkein jumalten Jumalaa, kunnioittakaat ja ylistäkäät, että hänen hyvyytensä pysyy ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 65, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 66, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 67, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 68, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Oli mies Babelissa, Jojakim nimeltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Jolla oli emäntä, ja sen nimi oli Susanna, Helkian tytär, joka oli sangen ihana ja jumalinen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Sillä hänellä oli jumaliset vanhemmat, jotka hänen olivat opettaneet Jumalan laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Ja hänen miehensä Jojakim oli sangen rikas, ja hänellä oli kaunis yrttitarha huoneensa tykönä. Ja Juudalaiset tulivat alati kokoon hänen tykönsä, että hän oli ylimmäinen mies kaikkein heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Mutta sinä vuotena oli kaksi vanhaa kansasta tuomariksi pantu; ne olivat senkaltaiset ihmiset, joista Herra sanonut oli: heidän tuomarinsa tekevät kaikkinaista pahuutta Babelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Ne tulivat joka päivä Jojakimin tykö; ja jolla joku asia oli, sen piti siellä tuleman heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Ja kuin kansa oli mennyt pois puolipäivästä, oli Susannan tapa mennä miehensä yrttitarhaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Ja kuin ne vanhat joka päivä näkivät hänen sinne menevän, syttyivät he pahasta himosta häntä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Ja tulivat tyhmiksi, ja katsoivat tarkasti hänen päällensä, ettei he taitaneet taivaasen päin katsoa, ei ajatelleet Jumalan sanaa eikä rangaistusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Mutta he himoitsivat molemmat häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Ja häpesivät toinen toisellensa ilmoittaa, ja kumpikin olis mielellänsä hänen kanssansa maannut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Ja vartioitsivat joka päivä viriästi häntä, että he ainoasti hänen nähneetkin olisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Mutta toinen sanoi toiselle: käykäämme kotia, sillä nyt on ruan aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Ja kuin he toinen toisestansa erinneet olivat, palasi kumpikin takaperin, ja tulivat jälleen yhteen. Kuin toinen kysyi toiselta, tunnustivat he molemmat pahan himonsa. Sitte mielistyivät he vartioitsemaan, koska he löytäisivät vaimon yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Ja kuin he soveliaan päivän olivat määränneet häntä väijyäksensä, tuli Susanna kahden piikansa kanssa, niinkuin hänen tapansa oli, yrttitarhaan pesemään itsiänsä; sillä silloin oli sangen palava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Ja ei yrttitarhassa ollut yhtään ihmistä, paitsi näitä kahta vanhaa, jotka itsensä lymyttäneet olivat, ja vartioitsivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Ja hän sanoi piioillensa: tuokaat minulle balsamia ja saippuaa, ja sulkekaat yrttitarha, että minä itseni pesisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Ja piiat tekivät niinkuin hän oli käskenyt, ja sulkivat yrttitarhan, ja menivät pois salaportista, tuomaan hänelle, mitä hän tahtoi; ja ei huomanneet miehiä, sillä he olivat itsensä lymyttäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Kuin piiat olivat menneet pois, tulivat ne kaksi vanhaa, ja juoksivat hänen tykönsä, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Katso, yrttitarha on suljettu, ja ei kenkään näe meitä, ja me olemme syttyneet sinun rakkaudestas, tee siis meidän tahtomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Mutta jos et sinä tahdo, niin me tunnustamme sinun päälles, että me nuoren miehen yksin sinun tykönäs löytäneet olemme, ja että sinä piikas olet sen tähden lähettänyt pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Niin Susanna huokasi ja sanoi: voi, kuinka suuressa tuskassa minä olen! sillä jos minä sen teen, niin minun pitää kuoleman; mutta jos en minä sitä tee, niin en minä pääse teidän käsistänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Kuitenkin ennen tahdon minä viatoinna ihmisten käsiin tulla, kuin Herraa vastaan syntiä tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Ja rupesi ilmeisesti huutamaan; vaan ne vanhat huusivat myös häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 25, 'Ja toinen juoksi yrttitarhan oveen ja avasi sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 26, 'Kuin talon väki kuuli huudon, juoksivat he salaportista yrttitarhaan, katsomaan, mitä hänelle tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 27, 'Ja ne vanhat rupesivat hänestä sanomaan, niin että palveliat rupesivat hänen tähtensä häpeemään; sillä ei senkaltaista ollut koskaan Susannasta kuultu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 28, 'Toisena päivänä, kuin kansa tuli Jojakimin hänen miehensä huoneesen kokoon, tulivat myös ne kaksi vanhaa täynnänsä vääryyttä ja kavaluutta Susannaa vastaan, saattaaksensa häntä kuolemaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 29, 'Ja sanoivat kaikelle kansalle: lähettäkäät ja antakaat tänne tuoda Susannan, Helkian tyttären, Jojakimin emännän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 30, 'Ja kuin hän kutsuttu oli, tuli hän vanhempainsa, lastensa ja kaiken sukunsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 31, 'Mutta hän oli sangen ihana ja kaunis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 32, 'Sen tähden käskivät nämät pahanjuoniset ottaa pois häneltä kääriliinan, jolla hän itsensä peittänyt oli, että he hänen kauneudestansa himonsa olisivat sammuttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 33, 'Ja kaikki, jotka hänen tykönänsä seisoivat, ja hänen tunsivat, itkivät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 34, 'Ja ne kaksi vanhaa nousivat kansan seasta ja panivat kätensä hänen päänsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 35, 'Mutta hän itki ja nosti silmänsä taivaasen päin; sillä hänen sydämensä uskalsi Herraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 36, 'Ja vanhat rupesivat sanomaan: kuin me kahden ainoastaan yrttitarhassa käyskentelimme, tuli hän kahden piikansa kanssa sisälle, ja sulki yrttitarhan ja lähetti piiat pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 37, 'Niin yksi nuori mies tuli hänen tykönsä, joka itsensä lymyttänyt oli, ja pani levätä hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 38, 'Mutta kuin me yrttitarhan loukkaasta senkaltaisen häpiän näimme, juoksimme me sinne kiiruusti ja löysimme heidät toinen toisensa tyköä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 39, 'Mutta sitä nuorta miestä emme voittaneet; sillä hän oli meitä väkevämpi, ja lykkäsi oven auki, ja hyppäsi pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 40, 'Mutta hänen me kiinni otimme ja kysyimme, kuka se nuori mies oli, vaan ei hän tahtonut meille sanoa. Sen me todistamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 41, 'Ja kansa uskoi ne kaksi, niinkuin tuomarit ja ylimmäiset kansan seassa, ja tuomitsi Susannan kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 42, 'Mutta hän huusi suurella äänellä ja sanoi: Herra ijankaikkinen Jumala, joka kaikki salaisuudet tunnet, ja kaikki asiat tiedät, ennen kuin ne tapahtuvat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 43, 'Sinä tiedät, että nämät väärin minua vastaan todistaneet ovat. Ja nyt katso, minun pitää kuoleman, vaikka minä viatoin olen siinä, jota he minun päälleni: häpiällisesti valhetelleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 44, 'Ja Jumala kuuli hänen huutonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 45, 'Ja kuin hän kuolemaan vietiin, kehoitti Jumala yhden nuorukaisen sydämen, jonka nimi oli Daniel, hän huusi korkiasti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 46, 'Minä tahdon olla viatoin tämän veressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 47, 'Ja kaikki kansa kääntyi hänen puoleensa, ja kysyivät häneltä, mitä hän niillä sanoilla ajattelis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 48, 'Mutta hän astui heidän keskellensä, ja sanoi: oletteko te Israelissa niin tyhmät, että te tuomitsette Israelin tyttären, ennenkuin te asian tutkitte ja toden tiedätte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 49, 'Palatkaat jälleen oikeuden eteen; sillä nämät ovat väärin häntä vastaan todistaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 50, 'Ja kaikki kansa palasi kiiruusti ympärinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 51, 'Ja vanhat sanoivat Danielille: istu meidän tykömme ja opeta meitä, että Jumala senkaltaiseen tuomarin virkaan sinun on kutsunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 52, 'Ja Daniel sanoi heille: eroittakaat heitä toinen toisestansa, niin minä tahdon kummankin erinänsä kuunnella. Ja kuin he toinen toisestansa eroitetut olivat, kutsui hän ensimäisen, ja sanoi hänelle: sinä vanha pahanilkinen! tällä haavaa käsittävät sinun syntis sinun, joitas ennen tehnyt olet, koskas väärin tuomitsit ja viattomat hukutit, vaan vialliset vapaiksi sanoit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 53, 'Ja kuitenkin on Herra kieltänyt: ei sinun pidä hurskaita ja viattomia kuolettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 54, 'Oletkos nämät nähnyt, niin sano, minkä puun alla sinä olet nämät yhdessä löytänyt? Mutta hän vastasi: lehmuksen alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 55, 'Niin Daniel sanoi: oikein, Herran enkeli löytää sinun ja kahtia leikkaa sinun; sillä valheellas saatat sinä itses pois hengeltäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 56, 'Ja kuin tämä otettiin pois, kutsui hän myös toisen eteensä tulemaan, ja sanoi hänelle: sinä Kanaanin suku ja et Juudan! kauneus on sinun pettänyt, ja paha himo on sinun sydämes kääntänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 57, 'Näin te olette Israelin tyttärille tehneet, ja heidän on pelvosta täytynyt teidän mieltänne noutaa, vaan tämä Juudan tytär ei ole teidän pahuuteenne suostunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 58, 'Sanos nyt, minkä puun alla sinä olet heidät yhdessä käsittänyt? Mutta hän vastasi: tammen alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 59, 'Niin Daniel sanoi: oikein, Herran enkelillä on miekka sinua kahtia jakaa ja tappaa; sillä valheellas saatat sinä itses hengeltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 60, 'Niin kaikki kansa rupesi suurella äänellä huutamaan ja kiittämään Jumalaa, joka niitä auttaa, jotka häneen luottavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 61, 'Ja nousivat niitä kahta tuomaria vastaan, että Daniel heidän omista sanoistansa oli heidät voittanut vääriksi todistajiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 62, 'Ja tekivät heille Moseksen lain jälkeen, niinkuin he heidän lähimmäistänsä vastaan pahoin tehneet olivat, ja tappoivat heidät. Ja näin silloin viatoin veri pelastettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 63, 'Mutta Helkia emäntänsä kanssa ylisti Jumalaa, tyttärensä Susannan tähden, Jojakimin hänen miehensä kanssa ja kaiken sukunsa kanssa, ettei mitään häpiällistä hänessä löydetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 64, 'Ja Daniel tuli suureksi kansan edessä siitä päivästä, ja sitte enemmin ja enemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Ja Daniel oli alati kuninkaan tykönä ja pidettiin kunniallisempana kuin kaikki kuninkaan ystävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Ja Babelissa oli epäjumala, joka kutsuttiin Beliksi: sille piti uhrattaman joka päivä kaksitoista kymmentä mittaa (a) nisuja ja neljäkymmentä lammasta. ja kolme aamia viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Ja kuningas palveli itse sitä epäjumalaa, ja meni joka päivä sitä kumartamaan; vaan Daniel palveli Jumalaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Ja kuningas sanoi hänelle: miksi et sinä myös Beliä rukoile? Mutta hän sanoi: en minä palvele epäjumalia. jotka käsillä tehdyt ovat, vaan elävää Jumalaa, joka taivaan ja maan on tehnyt, ja on kaikkein elävien Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Niin kuningas sanoi hänelle: etkö Beliä pidit elävänä jumalana? etkös näe, kuinka paljon hän joka päivä syö ja juo?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Mutta Daniel naurahti, ja sanoi: herra kuningas, älä anna itsiäs vietellä; sillä ei Bel ole sisältä muu kuin savi ja ulkoa vaski, ja ei se ole koskaan syönyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Niin kuningas vihastui, ja antoi kutsua kaikki hänen pappinsa ja sanoi heille: jollette minulle sano, kuka tämän uhrin syö, niin teidän pitää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Mutta jos te taidatte näyttää Belin sen syövän, niin pitää Danielin kuoleman; sillä hän on Beliä pilkannut. Ja Daniel sanoi: jopa, herra kuningas, tapahtukoon niin. kuin sinä puhunut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Mutta Belin pappia oli seitsemänkymmentä, ilman vaimoja ja lapsia. Ja kuningas meni Danielin kanssa Belin templiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Niin hänen pappinsa sanoivat: katso, me tahdomme mennä ulos, ja sinun, herra kuningas, pitää itse sinne ruan paneman ja juoman, ja oven perääs paneman kiinni, ja omalla sormuksellas lukitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Ja kuin sinä aamulla varhain jälleen tulet ja löydät, ettei Bel niitä kaikkia ole kuluttanut, niin me mielellämme kuolemme, eli Daniel pitää tapettaman, joka senkaltaista meidän päällemme on valhetellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Mutta he luottivat siihen, että he olivat tehneet salaisen tien pöydän alle, jonka kautta he alati sisälle menivät ja kuluttivat, mitä siellä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Kuin papit ulkona olivat, antoi kuningas Belin eteen ruan panna. Mutta Daniel käski palveliansa tuhkaa tuoda, ja antoi sitä priiskottaa koko kirkon ympäri kuninkaan nähden. Sitte he menivät pois, ja sulkivat oven, ja lukitsivat kuninkaan sormuksella, ja menivät matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Mutta papit menivät yöllä sisälle tapansa jälkeen vaimoinensa ja lapsinensa, söivät ja joivat kaikki, mitä siellä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Aamulla varhain oli kuningas ylhäällä, ja Daniel hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Ja kuningas sanoi Danielille: onko sinetti rikkomatta? Mutta hän vastasi: on, herra kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Ja niin pian kuin ovi avattiin, katsoi kuningas pöydälle ja huusi suurella äänellä: Bel, sinä olet suuri jumala, eikä sinussa ole petosta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Vaan Daniel nauroi, ja piteli kuningasta, ettei hän sisälle menisi, ja sanoi: katso permannolle ja ymmärrä, kenenkä jäljet nämät ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Kuningas sanoi: minä näen kyllä miesten, vaimoin ja lasten jäljet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Niin kuningas vihastui ja antoi papit ottaa kiinni, vaimoinensa ja lapsinensa: ja heidän täytyi osoittaa hänelle sen salaisen tien, jonka kautta he olivat käyneet ulos ja sisälle ja syöneet, mitä pöydällä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Ja kuningas antoi tappaa heidät, ja antoi Belin Danielin haltuun, joka hävitti sen ja hänen templinsä. Daniel saa luvan surmata lohikärmeen, jota Babylonialaiset palvelivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Siellä oli myös suuri lohikärme, jota he Babelissa palvelivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Ja kuningas sanoi Danielille: kuinka, tahdotko myös hänestä sanoa, ettei hänkään ole muu kuin vaskinen epäjumala? Katso, hän elää; sillä hän syö ja juo; sentähden et sinä taida sanoa, ettei hän ole elävä jumala, palvele siis häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Mutta Daniel vastasi: minä palvelen Herraa minun Jumalaani; sillä hän on elävä Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 25, 'Vaan sinä, herra kuningas, salli, niin minä tämän lohikärmeen surmaan ilman yhtäkään miekkaa eli korentoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 26, 'Ja kuningas sanoi: se olkoon sinulle luvallinen. Niin Daniel otti tervaa, rasvaa ja karvoja, ja keitti ne sekaisin, ja teki siitä kyrsäisiä, ja heitti lohikärmeen suuhun, ja lohikärme pakahtui kahtia. Ja Danie1 sanoi: katso, nämät ovat teidän jumalanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 27, 'Kuin Babylonialaiset sen kuulivat, ottivat he sen sangen pahaksi, ja nostivat kapinan kuningasta vastaan, ja sanoivat: meidän kuninkaamme on Juudalaiseksi tullut; sillä hän on Belin kukistanut, lohikärmeen tappanut ja papit surmannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 28, 'Ja he astuivat kuninkaan eteen, ja sanoivat: anna meille tänne Daniel; mutta jollet anna, niin me sinun ja koko sinun huonees tapamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 29, 'Kuin kuningas näki, että he väkivallalla hänen päällensä tunkivat, täytyi hänen antaa heille Danielin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 30, 'Ja he heittivät hänen jalopeurain eteen luolaan, jossa hän oli kuusi päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 31, 'Ja luolassa oli seitsemän jalopeuraa, joille joka päivä annettiin kaksi ihmistä (a) ja kaksi lammasta; mutta ei heille annettu niinä päivinä mitään, että he olisivat Danielin syöneet. (a) Gr. ruumista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 32, 'Mutta Juudeassa oli propheta Habakuk, joka oli keittänyt lientä ja leikannut leipää syvään lstiaan, ja meni niiden kanssa kedolle, viedäksensä eloväelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 33, 'Ja Herran enkeli sanoi Habakukille: sinun pitää sen ruan, jotas kannat, viemän Danielille Jabeliin, jalopeurain luolaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 34, 'Ja Habakuk vastasi: Herra, en minä ole Babelin kaupunkia lähnyt, enkä tiedä, kussa luola on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 35, 'Silloin tarttui enkeli hänen kiireesensä, ja vei hänen niinkuin väkevä tuuli Babelia päin luolan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 36, 'Ja Habakuk huusi ja sanoi: Daniel, Daniel, ota tämä ruoka, jonka Jumala on sinulle lähettänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 37, 'Ja Daniel sanoi: Herra Jumala, sinä muistat kuitenkin vielä minua, ja et hylkää niitä, jotka sinua rukoilevat ja sinua rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 38, 'Ja hän nousi ja söi. Vaan Herran enkeli vei Habakukin sillä hetkellä entiseen paikkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 39, 'Ja kuningas tuli seitsemäntenä päivänä Danielia valittamaan. Ja kuin hän haudalle tuli, ja katsoi sisälle, katso, niin Daniel istui jalopeurain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 40, 'Ja kuningas huusi suuresti ja sanoi: oi Herra, sinä Danielin Jumala, sinä olet suuri Jumala, ja ei ole yhtään muuta jumalaa paitsi sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 41, 'Ja hän antoi ottaa hänen ylös luolasta. Mutta ne muut, jotka hänen kuolemaan saattaa tahtoivat, antoi hän luolaan heittää, jotka kohta hänen silmäinsä edessä jalopeuroilta nieltiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 42, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Antiokus Epiphaneksen jumalattomuudesta ja julmuudesta Jerusalemia vastaan. Aleksander, Philippuksen poika, Makedonian kuningas, joka ennen Grekan maalla hallinnut oli, läksi Kittimin maakunnasta, nosti suuret sodat, otti vahvat kaupungit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Ja löi Dariuksen, Persian ja Median kuninkaan, ja hallitsi hänen siassansa, ja voitti sen jälkeen muut kuninkaat kaikissa maakunnissa allensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Ja vaelsi aina edemmäksi, ja otti kaikki maat ja valtakunnat, ja ei kenkään rohjennut asettna häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Ja hänen sydämensä paisui ja tuli ylpiäksi; oli myös hänellä sangen väkevä sotajoukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Kuin hän ne valtakunnat oli saanut allensa, tuli hän sairaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Vaan kuin hän havaitsi, että hänen piti kuoleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'kutsui hän päämiehensä tykönsä, jotka nuoruudesta olivat hänen kanssansa kasvaneet. ja sääsi eläissänsä heidät maakuntain ruhtinaiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Ja Aleksander kuoli, kuin hän kaksitoistakymmentä vuotta oli vallinnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Jälkeen hänen kuolemansa tuli valtakunta hänen ruhtinaillensa, he ottivat maakunnat kukin paikkansa, ja tekivät itsensä kuninkaiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Ja he ja heidän jälkeentulevaisensa hallitsivat kauvan aikaa, ja suuri sota oli heidän välillänsä, ja paljo tuskaa joka paikassa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Ja yhdestä näistä ruhtinaista syntyi vahingollinen pahuuden juuri, nimeltä Antiokus Epiphanes, joka Roomissa oli ollut takauksena isänsä, suuren Antiokuksen edestä. Ja tämä Antiokus Epiphanes rupesi hallitsemaan sadannella ja seitsemännelläneljättäkymmentä Grekan valtakunnan vuodella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Niihin aikoin olivat Israelissa väärät miehet, jotka yllyttivät kansaa ja sanoivat: tehkäämme liitto ympärillä asuvaisten pakanain kanssa, ja ruvetkaamme heidän jumalanpalvelukseensa; sillä meidän on täytynyt kärsiä paljon pahuutta siitä ajasta, kuin me olemme heistä luopuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Tämä neuvo kelpasi heille hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Ja he lähettivät muutamia kansasta kuninkaan tykö, joka käski heidän ottaa pakanain säädyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Silloin he asettivat Jerusalemissa pakanallisen harjoitushuoneen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Eikä ympärileikkausta pitäneet, vaan lankesivat pois pyhästä liitosta, ja pitivät itsensä niinkuin pakanat ja olivat peräti paatuneet tekemään kaikkinaista syntiä ja häpiää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Kuin Antiokus oli vahvistanut valtakuntansa, aikoi hän myös saada Egyptin valtakunnan, ja niin pitää molemmat valtakunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Ja hän meni Egyptiin sangen vahvana, vaunuin, elephanttein, hevosmiesten ja laivain paljoudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Vaan Ptolomeus pelkäsi ja pakeni, ja monta Egyptin miestä kaatui haavoitettuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Ja Antiokus sai vahvimmat kaupungit Egyptissä, ja kiskoi suuren saaliin ja vei pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Mutta kuin Antiokus Egyptissä tämän voiton saanut oli, ja palasi kotia sadannella ja kolmannella vuodella viidettäkymmentä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Meni hän ylös Israeliin ja Jerusalemiin suurella joukolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Ja meni röyhkeästi pyhään., ja antoi ottaa pois kultaisen alttarin, kynttiläjalan ja kaikki ne kappaleet, jotka sen päällä olivat, ja leipäuhripöydän, ja pikarit, ja maljat, kultaiset lusikat, esiripun ja kruunut, ja kultaiset templin kaunistukset, ja löi kaikki rikki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 24, 'Ja otti hopian ja kullan, ja kaikki kalliit astiat ja kätketyt tavarat, mitkä hän löysi, ja vei kaikki myötänsä omalle maallensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 25, 'Ja antoi surmata paljon väkeä, ja puhui juuri ylpiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 26, 'Ja suuri sydämen suru oli koko Israelissa ja kaikissa paikoissa, joissa he asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 27, 'Ja päämiehet ja vanhimmat murehtivat, neitseet ja nuorukaiset suuresti surkastuivat, miehet ja vaimot valittivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 28, 'Ja koko maakunta oli surullinen siitä julmuudesta, joka siellä tapahtui;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 29, 'Ja koko Jakobin huone oli täytetty katkeruudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 30, 'Ja kahden vuoden perästä lähetti kuningas veropäämiehen Juudeaan; se tuli Jerusalemiin suurella väellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 31, 'Ja anoi ystävällisesti, että hänen piti pääsemän sisälle, ja ei luvannut mitään vahinkoa tehdä, vaan se oli kaikki petos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 32, 'Ja he uskoivat hänen, ja sallivat tulla sisälle, ja hän karkasi petoksella kaupungin päälle, ja löi paljon kansaa Israelista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 33, 'Ja ryösti kaupungin, ja poltti huoneet, kukisti muurit,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 34, 'Ja vei pois vaimot, lapset ja karjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 35, 'Ja Davidin linnan hän vahvisti vahvoilla muureilla ja torneilla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 36, 'Ja asetti siihen jumalattoman joukon, joka siinä kaikkea pahuutta teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 37, 'Ja he ryöväsivät sota-aseet ja elatuksen Jerusalemin kaupungista, ja panivat sinne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 38, 'Ja piirittivät pyhän, ja väijyivät kansaa, jotka templiin menivät, ja hyökkäsivät linnasta pyhään, estääksensä jumalanpalvelusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 39, 'Ja vuodattivat pyhässä siassa paljon viatointa verta, ja saastuttivat sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 40, 'Ja Jerusalemin asuvaiset pakenivat ja muukalaiset jäivät siaan; vaan ne, jotka siinä syntyneet olivat, piti lähtemän pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 41, 'Pyhä sia oli kylmillä, pyhäpäivät tulivat kaikki murhepäiviksi ja sabbatit surkeudeksi, ja kaikki heidän kunniansa raukesi tyhjään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 42, 'Niin kuuluisa kuin Jerusalem oli ennen ollut, niin surkian ja vaivaloisen täytyi sen siihen aikaan olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 43, 'Ja Antiokus antoi myös ympäri kaiken valtakuntansa käskyn, että kaikki kansa yksimielisesti piti yhdenkaltaisen jumalanpalveluksen pitämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 44, 'Silloin hylkäsi kaikki kansa lakinsa, ja mielistyivät Antiokuksen käskyyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 45, 'Ja monta Israelista lankesi siihen, ja uhrasi epäjumalille ja turmeli sabbatin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 46, 'Antiokus lähetti myös kirjat Jerusalemiin ja kaikkiin Juudan kaupunkeihin, joissa hän käski, että heidän piti pakanain jumalanpalveluksen ottaman vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 47, 'Ja polttouhrin ja ruokauhrin ja syntiuhrin pyhässä siassa, sabbatin ja muut juhlapäivät maahan lyömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 48, 'Ja käski, että pyhä ja pyhä kansa piti saastutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 49, 'Ja antoi rakentaa alttarit, kirkot ja epäjumalat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 50, 'Ja uhrata sianlihoja ja muita saastaisia eläimiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 51, 'Ja kielsi ympärileikkauksen, ja käski kansan totutettaa kaikkiin kauhistuksiin, että heidän piti Jumalan lain ja oikeuden unhottaman, ja toiset tavat ottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 52, 'Ja kuka ikänä ei ollut tässä asiassa Antiokukselle kuuliainen, se piti surmattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 53, 'Tämän käskyn antoi hän käydä ulos kaikkeen valtakuntaansa, ja asetti päämiehet, jotka kansan piti vaatiman kaikkia senkaltaisia pitämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 54, 'Nämät toimittivat, että Juudan maalla uhrattiin, ja käskivät, että niin piti pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 55, 'Ja monta kansasta luopui Jumalan laista heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 56, 'He tekivät kaikkea pahuutta maakunnassa, ja karkoittivat Israelin pois, että heidän täytyi lymyttää ja kätkeä itsensä luoliin, paossansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 57, 'Sadannella ja viidennellä vuodella viidettäkymmentä, viidentenä päivänä toistakymmentä Kasleun kuulla, antoi kuningas Antiokus panna hävityksen kauhistuksen Jumalan alttarille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 58, 'Ja antoi panna alttarit ylös joka Juudan kaupungissa, niin että joka miehen kadulla julkisesti ja huoneensa edessä suitsuttaman ja uhraaman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 59, 'Ja antoi repiä rikki ja polttaa Herran lakikirjat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 60, 'Ja murhata kaikki ne, joiden tykönä Jumalan liiton kirjat löydettiin, ja jotka Herran lain pitivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 61, 'Ja tätä he tekivät sotaväellänsä joka kuu, kuin kansa tuli kokoon kaupungeissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 62, 'Ja viidentenä päivänä kolmattakymmentä kuusta uhrasivat he alttarilla, jonka he rakentaneet olivat Herran alttaria vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 63, 'Ja ne vaimot, jotka lapsensa ympärileikkasivat, tapettiin, niinkuin Antiokus oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 64, 'Vanhimmat tapettiin huoneissansa, ja lapset hirtettiin. Mutta monta Israelin kansasta olivat vahvat, ja ei tahtoneet syödä saastaista, Ja antoivat ennen itsensä tapettaa, kuin he itsensä saastuttivat, Eikä tahtoneet luopua Jumalan pyhästä laista, sentähden he tulivat surmatuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Niinä päivinä nousi pappi Matatias, Johanneksen poika, Simeonin pojan, Joarimin suvusta Jerusalemista, joka asui Modin vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'Ja hänellä oli viisi poikaa: Johannes, liialta nimeltä Gaddis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Simon, liialta nimeltä Tassi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Juudas, liialta nimeltä Makkabealainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Eleatsar, liialta nimeltä Aaron, ja Jonatan, liialta nimeltä Apphus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Nämät murehtivat sangen kovin sitä suurta surkeutta, joka Juudeassa ja Jerusalemissa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Ja Matatias valitti ja sanoi: voi että minä sitä varten synnyin, että minun pitää näkemän minun kansani ja pyhän kaupungin hävityksen, ja vielä sittenkin alallani oleman, ja antaman vihollisen tehdä niinkuin hän itse tahtoo!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Muukalaiset pitävät hallussansa pyhän, ja Jumalan templi on niinkuin kunniatoin ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Sen kaunistukset ovat viedyt pois, lapset ovat kaduilla lyödyt, ja nuoret miehet muukalaisilta syöstyt lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Valtakunta on tullut kaikkein pakanain saaliiksi, ja he ryöstävät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Kaikki sen kunnia on tullut pois; joka ennen oli niinkuin suuri kuningatar, se on nyt ylönkatsotuksi orjaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Katso, meidän pyhämme, kerskauksemme ja kunniamme on poissa; pakanat ovat sen hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Kellä olis ilo enään elää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Ja Matatias repäisi vaatteensa, hän ja hänen poikansa, ja pukivat säkit yllensä ja murehtivat sangen raskaasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Kuin Antiokuksen käskyläiset sinne tulivat vaatimaan myös niitä, jotka Modin kaupunkiin paenneet olivat, luopumaan Jumalan laista, ja epäjumalille uhraamaan ja pyhää savua suitsuttamaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Silloin luopui monta Israelin kansasta heidän tykönsä; mutta Matatias ja hänen poikansa pysyivät vahvana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Ja Antiokuksen käskyläiset sanoivat Matatiakselle: sinä olet ylimmäinen ja voimallisin tässä kanpungissa, ja sinulla on monta poikaa ja sukulaista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Sentähden astu sinä ensin edes, ja tee, mitä kuningas on käskenyt, niinkuin kaikki maakunnat, niin myös Juudan miehet, jotka vielä Jerusalemissa ovat, tehneet ovat, niin kuningas leppyy sinulle ja sinun pojilles, ja lahjoittaa sinulle hopiaa ja kultaa ja suuria lahjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Ja Matatias vastasi lujasti ja sanoi: jos vielä kaikki maakunnat Antiokukselle kuuliaiset olisivat, ja jokainen isäinsä laista luopuis, ja mielistyis kuninkaan käskyyn;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'En kuitenkaan minä, ja minun poikani ja veljeni tahdo hyljätä isäin lakia: siitä meitä Jumala varjelkoon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Ei se olisi meille hyvää, että me Jumalan sanasta ja laista luopuisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Emme tahdo mielistyä Antiokuksen käskyyn, ja uhrata, emmekä luopua laistamme, ja toisia säätyjä ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 23, 'Kuin hän nämät sanat puhunut oli, tuli yksi Juudalainen kaikkein silmäin nähden ja uhrasi epäjumalalle alttarilla Modin kaupungissa, niinkuin kuningas oli, käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 24, 'Ja Matatias näki sen, ja se pisti hänen sydäntänsä, ja hänen kiivauksensa syttyi lain tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 25, 'Ja hän juoksi ja tappoi sen Juudalaisen alttarin edessä, ja Antiokuksen käskyläisen, joka uhraamaan vaati, ja kukisti alttarin maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 26, 'Sen hän teki kiivaudessa lain tähden, niinkuin Pinehas teki Zambrille Salomin pojalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 27, 'Ja Matatias korotti äänensä kaiken kaupungin ylitse, sanoen: jolla on kiivaus laista, ja tahtoo pitää liiton, hän käykään minun kanssani kaupungista ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 28, 'Niin pakeni hän ja hänen poikansa vuorille, ja jättivät kaupunkiin kaikki, mitä heillä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 29, 'Ja monta hurskasta ihmistä läksi ulos erämaihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 30, 'Ja olivat siellä valmoinensa, lapsinensa ja karjoinensa; sillä julmuus oli sangen suureksi paisunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 31, 'Mutta kuin kuninkaan väki Jerusalemissa, Davidin kaupungissa, kuulla saivat, että muutamat olivat asettuneet kuninkaan käskyä vastaan, ja antauneet kaupungista ulos erämaihin, salaisiin paikkoihin, lymyttääksensä ja pelastaaksensa itsensä, ja että paljo kansaa oli heidän seuraansa mennyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 32, 'Kiiruhtivat he karkaamaan heidän päällensä sabbatin päivänä, ja antoivat heille sanoa: vieläkö te nyt \'tahdotte kovakorvaiset olla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 33, 'Käykäät ulos ja tehkäät mitä kuningas on käskenyt, ja te saatte olla rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 34, 'Ja he vastasivat: emme tahdo lähteä, emmekä rikkoa sabbatia, niinkuin kuningas käskee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 35, 'Ja he hyökkäsivät sodalla heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 36, 'Ja ne, jotka siellä olivat, ei itseänsä puolustaneet, eikä kiveäkään heittäneet, eikä myös luolankaan suuta tukinneet, vaan sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 37, 'Me tahdomme näin kuolla viattomuudessamme: taivas ja maa todistavat, että te meitä väärin ja viattomasti tapatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 38, 'Ja niin he hyökkäsivät heidän päällensä sabbatina, ja tappoivat heidät, ja heidän vaimonsa ja lapsensa, tuhannen ihmistä, ja heidän karjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 39, 'Kuin Matatias ja hänen ystävänsä sen kuulla saivat, murehtivat he sangen kovin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 40, 'Ja sanoivat toinen toisellensa: jos me kaikki niin tehdä tahdomme, kuin meidän veljemme tehneet ovat, ja emme sodi pakanoita vastaan, että me varjelisimme henkemme ja lakimme, niin ei heidän ole työtä meitä peräti hukuttaa maan päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 41, 'Ja he päättivät keskenänsä, sanoen: jos he tulevat meidän päällemme sabbatina, niin varjelkaamme meitämme, ettemme kaikki hukkuisi, niinkuin meidän veljemme vuorten rotkoissa murhatut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 42, 'Ja suuri joukko hurskaita ihmisiä kokoontuivat yhteen, jotka kaikki laissa olivat pysyväiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 43, 'Ja kaikki, jotka julmuuden tähden paenneet olivat, tulivat; heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 44, 'Ja he myös nousivat ja löivät monta jumalatointa ja eriseuraista kiivaudessansa ja vihassansa; mutta muut pakenivat, ja pääsivät pakanain sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 45, 'Sitte Matatias ja hänen ystävänsä vaelsivat lujasti Israelin maata ympäri ja kukistivat maahan heidän alttarinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 46, 'Ja ympärileikkasivat lapset, jotka vielä ympärileikkaamatta olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 47, 'Ja hyökkäsivät jumalattomain päälle; ja se menestyi heille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 48, 'Niin että he pysyivät laissa kaikkein pakanain ja kuningasten voimaa vastaan, ettei jumalattomat yhtäkään voimusta heistä saaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 49, 'Mutta kuin Matatias juuri vanha oli, sanoi hän ennen kuolemaansa pojillensa: nyt on tullut meidän päällemme suuri ahdistus ja vaino, ja suuri julmuus ja raskas rangaistus;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 50, 'Sen tähden, rakkaat poikani, pitäkäät kiivaus lain tähden, ja älkäät säästäkö henkeänne meidän: isäimme liiton tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 51, 'Ja mieleenne johdattakaat, mitkä työt isämme aikanansa tehneet ovat, niin te voitatte suuren kunnian ja ijankaikkisen nimen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 52, 'Abraham kiusattiin ja löydettiin vahvaksi uskossa, se luettiin hänelle vanhurskaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 53, 'Joseph vaivassansa piti käskyn, ja tuli Egyptin herraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 54, 'Pinehas, meidän isämme, piti kiivauden Jumalan kunnian tähden, ja sai todistuksen, että pappeus piti hänellä ijäti oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 55, 'Josua toimitti sen käskyn, joka hänelle annettu oli, sentähden tuli hän ylimmäiseksi päämieheksi Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 56, 'Kaleb antoi todistuksen ja nuhteli kansaa; sentähden sai hän erinomaisen perimisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 57, 'David jumalisuudessansa peri kuninkaallisen valtakunnan ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 58, 'Elia piti kiivauden laista, ja otettiin ylös taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 59, 'Anania, Atsaria ja Misael uskoivat ja tulesta pelastettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 60, 'Daniel viattomuutensa tähden pelastettiin jalopeuran kidasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 61, 'Näin mieleenne johdattakaat, mitä kullakin ajalla tapahtunut on, niin te löydätte, että kaikki ne, jotka Jumalaan uskaltavat, pysyvät vahvana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 62, 'Sentähden älkäät peljätkö jumalattomain uhkauksia; sillä heidän kunniansa on loka ja toukka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 63, 'Tänäpänä hän on korotettu, huomenna ei häntä mistään löydetä; sillä hän on tullut maaksi jälleen, ja hänen ajatuksensa on hukkunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 64, 'Sentähden, rakkaat lapset, olkaat rohkiat ja miehuulliset laissa, niin Jumala teitä korottaa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 65, 'Katso, teidän veljenne Simon on viisas neuvossa, kuulkaat häntä aina niinkuin isää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 66, 'Juudas Makkabealainen on väkevä ja jalo sotamies hamasta nuoruudestansa, hänen pitää oleman päämiehen ja sotiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 67, 'Ja ottakaat tykönne kaikki ne, jotka lain pitävät; kostakaat se väkivalta, joka teidän kansallenne tehty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 68, 'Ja maksakaat pakanoille sen jälkeen, minkä he ansainneet ovat, ja pysykäät lujasti laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 69, 'Sitte hän siunasi heitä, ja tuli kutsutuksi isäinsä tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 70, 'Ja kuoli, kuin hän oli sadan ja kuuden ajastaikainen viidettäkymmentä. Ja hänen poikansa hautasivat hänen isänsä hautaan Modin kaupungissa, ja koko Israel murehti häntä suurella murheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Juudas Makkabealaisen sotavalmistuksesta ja hänen vihollisistansa. Ja Juudas, joka kutsuttiin Makkabealaiseksi, tuli isänsä siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Ja kaikki hänen veljensä, ja kaikki, jotka hänen isänsä kanssa yhtä pitäneet olivat, auttivat häntä (vihollisia vastaan) ja sotivat Israelin edestä ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Ja Juudas saatti suuren kunnian kansallensa, hän oli haarniskoissansa niinkuin sankari, ja varjeli miekallansa sotajoukkonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Hän oli rohkia niinkuin jalopeura, ja pelkäämätöin niinkuin nuori kiljuva jalopeura, kuin se juoksee saaliin jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Hän etsi luopuneita ja jumalattomia, jotka vaativat kansaa luopumaan laista, rankaisi ja poltti heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Niin että hänen vihollisensa pelkäsivät häntä kaikissa paikoissa ja pakenivat, ja luopuneet tulivat poljetuksi, ja hän sai onnen ja voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Tästä sai moni kuningas karvaan mielen, vaan Jakobille oli se iloksi, ja hänelle itselle ijankaikkiseksi muistoksi ja kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Hän vaelsi Juudan kaupunkien lävitse, ja surmasi jumalattomia, ja käänsi pois vihan Israelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Ja hän oli kuuluisa hamaan maan ääreen, niin että kaikki maahan poljetut pakenivat hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Sentähden kokosi Apollonius pakanoista ja Samariasta suuren sotaväen, sotimaan Israelia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Kuin Juudas sen kuuli, meni hän häntä vastaan, löi ja tappoi hänen ja suuren joukon vihollisia, ynnä hänen kanssansa vaan ne, jotka pääsivät, pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'Ja Juudas sai heidän kalunsa, ja otti Apolloniuksen miekan, jonka hän sitte kantoi kaiken elinaikansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Senjälkeen, kuin Seron, Syrian sodanpäämies, sai kuulla uskollisten joukon pitävän yhtä Juudaan kanssa, ja siellä olevan koossa suuren sotaväen joukon, sanoi hän:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Minä tahdon voittaa kunnian, että minä ylistettäisiin koko valtakunnassa, ja tahdon lyödä Juudaan ja hänen joukkonsa, jotka kuninkaan käskyn ovat katsoneet ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Sentähden hankitsi hän itsensä ja suuri väki meni hänen kanssansa kostamaan Israelia, ja tulivat hamaan Bethoronin paltaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Silloin meni Juudas häntä vastaan vähällä joukolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Mutta kuin he saivat nähdä viholliset, sanoivat he Juudaalle: meitä on vähä, ja me olemme myös heikot paastosta, kuinka siis me voimme lyödä niin suurta väkevää joukkoa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Mutta Juudas sanoi: se taitaa kyllä tapahtua, että vähä joukko voittaa suuren; sillä Jumala taitaa kyllä antaa voiton, niin vähän joukon kuin paljonkin kautta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Sillä voitto tulee taivaasta, ja ei väen paljoudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'He uskaltavat suureen väkeensä, ja aikovat tappaa ja hävittää meitä, meidän vaimomme ja lapsemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Vaan meidän pitää meitämme varjeleman ja sotiman meidän henkemme edestä ja meidän lakimme edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 22, 'Sentähden on Jumala heitä maahan lyövä meidän silmäimme edessä: ei teidän pidä heitä pelkäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 23, 'Kuin hän näin puhunut oli, hyökkäsi hän hopusti vihollisten päälle, ennen kuin he sen äkkäsivät, ja löi Seronin ja hänen väkensä pakoon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 24, 'Ja ajoi heitä takaa Bethoronista alaspäin, niin lakialle kedolle, ja löi heitä kuoliaaksi kahdeksansataa; ja ne, jotka pääsivät, pakenivat Philistealaisten maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 25, 'Niin tuli suuri pelko kaikille kansoille ympäristöllä Juudaan ja hänen veljeinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 26, 'Ja kaikissa maakunnissa puhuttiin Juudaasta ja hänen teoistansa; ja se tuli myös kuninkaan korville.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 27, 'Kuin Antiokus nämät kaikki kuulla sai, julmistui hän ylönpalttisesti, lähetti ja antoi käskyn kaikkeen valtakuntaansa, ja kokosi suuren väen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 28, 'Ja otti tavarastansa ja valmisti vuoden palkan, ja antoi käskyn, että kaikissa paikoissa piti oltaman valmiina sotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 29, 'Mutta kuin hän näki, ettei hänellä ollut rahaa täydeksi, ja ettei maakunta niin paljon antaa voinut, sen sodan tähden, jonka hän kauvan oli pitänyt lakia vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 30, 'Pelkäsi hän, ettei hän voinut senkaltaista kulutusta vasta tehdä, kuin siihen päivään asti; sillä hän oli palkkaa ja lahjoja enemmän antanut ulos, kuin kaikki kuninkaat hänen edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 31, 'Sentähden tuli hän surulliseksi, ja matkusti Persian maata verolliseksi laskemaan, ja kokoomaan paljon rahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 32, 'Ja hän jätti siaansa yhden päämiehen kuninkaan asiain päälle koko valtakuntaansa, ruveten Euphratista, niin hamaan Egyptiin asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 33, 'Ja antoi hänen kasvattaa poikaansa, nuorta Antiokusta, siihen asti kuin hän palajava oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 34, 'Ja antoi hänelle puolen sotaväestä ja elephanteista, ja käski häntä kaikista asioista ja Juudan ja Jerusalemin asuvaisista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 35, 'Että hänen piti lähettämän sotajoukon heitä vastaan surettamaan jääneen kansan Israelissa ja Jerusalemissa, ja hukuttamaan heidän muistonsa siitä paikasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 36, 'Ja asettamaan muukalaisia sinne asumaan, ja että pakanoille piti maa jaettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 37, 'Sillä seitsemäntenä vuotena viidettäkymmentä toista sataa läksi kuningas kaupungistansa Antiokiasta ja meni Euphratin virran ylitse, ja vaelsi ylimmäisten maakuntain lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 38, 'Mutta Lysias valitsi muutamia voimallisia miehiä kuninkaan ystävistä päämiehiksi, nimittäin: Ptolomeuksen Dorimenin pojan, Nikanorin ja Gorgian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 39, 'Ja antoi heille neljäkymmentä tuhatta jalkamiestä ja seitsemäntuhatta hevosmiestä, että heidän piti menemän Juudan maahan ja hävittämän Juudalaisia, niinkuin kuningas oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 40, 'Kuin he nyt tällä väellä lähteneet olivat, tulivat he ja sioittivat heitänsä Emmaonin tykö, tasaiselle kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 41, 'Kuin sen maakunnan kauppamiehet ympäristöllä sen kuulivat, tulivat he leiriin, ja toivat myötänsä paljon rahaa, ostaaksensa Israelin lapsia orjaksensa. Ja Syriasta ja muista pakanoista meni enempi sotaväkeä heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 42, 'Kuin nyt Juudas Ja hänen veljensä näkivät, että vaino eneni ja vihollinen makasi heidän rajoillansa, ja he saivat ymmärtää, että kuningas oli käskenyt hukuttaa kaiken Juudean,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 43, 'Rohkaisivat he itsensä, Ja olivat yhtäpitäväiset, että he tahtoivat kansansa avuksi ehtiä ja sotia pyhän edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 44, 'Sentähden kokosivat he sotaväkensä yhteen, että he olisivat aikanansa valmiit sotimaan ja rukoilemaan Jumalalta armoa ja apua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 45, 'Mutta siihen aikaan oli Jerusalem autio, ja ei siellä yksikään Israelin lapsista enään asunut, ja pyhä oli saastutettu epäjumalilla, jotka sinne pannut olivat, ja pakanat asuivat linnassa, ja kaikki kunnia oli Jakobista otettu pois, ei myös siellä kuulunut huilua eikä kanteletta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 46, 'Sentähden tuli kansa yhteen Mitspassa, joka on Jerusalemin kohdalla; sillä Mitspassa piti Israelin entisiin aikoin rukoileman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 47, 'Tässä paikassa tulivat he myös nyt kokoon, paastosivat ja pukivat säkit yllensä, ja panivat tuhkaa päänsä päälle, ja repäisivät vaatteensa rikki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 48, 'Ja toivat lakikirjat edes, joita pakanat olivat etsiä antaneet kirjoittaaksensa niihin epäjumalainsa kuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 49, 'He veivät sinne myös pappein vaatteet, esikoiset ja kymmenykset, tekivät nasiiria, joiden määrätystä ajasta piti ottaman vaarin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 50, 'Ja huusivat surkiasti taivaasen, sanoen: mitä me nyt näillä teemme? ja kuhunka me nämät viemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 51, 'Sillä sinun pyhäs on saastutettu, ja papit ovat ajetut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 52, 'Ja katso, pakanat kokoontuvat meitä vastaan, että he meidät peräti kadottaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 53, 'Sinä tiedät, mitä heidän mielessänsä on meitä vastaan. Kuinka me taidamme heidän edessänsä seisoa, jollet sinä meitä auta, meidän Jumalamme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 54, 'Senjälkeen antoi Juudas kutsua kansan vaskitorvilla kokoon, ja asetti hallituksen päämiehet, esimiehet, väen asettajat, ja tuhanten, satain, viidenkymmenten ja kymmenten johdattajat');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 55, 'Ja antoi kuuluttaa, että jotka kartanoita rakentaneet olivat, ja vaimon kihlanneet, ja viinapuita istuttaneet, eli jotka pelkurit olivat, piti kotiansa palajaman, niinkuin laki antaa myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 56, 'Sitte he läksivät matkaan, ja sioittivat itsensä myös Emmaonin tykö, etelän puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 57, 'Ja Juudas neuvoi väkeänsä ja sanoi: hankitkaat ja älkäät hämmästykö, että te huomeneksi valmiit olisitte sotimaan pakanoita vastaan, jotka meitä ja meidän pyhäämme aikovat maahan lyödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 58, 'Sillä se on meille parempi, että me kuolemme sodassa, kuin se, että me näemme senkaltaista tuskaa, joka on tullut meidän kansamme ja jumalanpalveluksemme päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 59, 'Mutta niinkuin Jumalan tahto on taivaassa, niin tapahtukoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 60, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Juudaan voitosta Gorgiaa vastaan, niin myös pyhän ja jumalanpalveluksen uudistamisesta. Ja Gorgias otti viisituhatta jalkamiestä ja tuhannen parasta ratsasmiestä, ja meni yöllä salaisesti Juudalaisten leiriin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Että hän olis tietämättä karannut heidän päällensä ja muutamat niistä, jotka linnassa maanneet olivat, olivat heidän johdattajansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Vaan kuin Juudas sai sen ymmärtää, niin hän nousi, ja vahvin väki hänen kanssansa, ennättämään ja pettämään vihollisia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Ja lyömään heitä, kuin he vielä siellä ja täällä hajalla olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Kuin Gorgias Juudaan leiriin tuli, ja ei sieltä ketään löytänyt, etsi hän heitä vuorten päällä; sillä hän luuli heidän paenneen hänen edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Mutta Juudas riensi, että hän varhain aamulla olis joutunut kedolle väljään, kolmellatuhannella miehellä, joilla ei kuitenkaan haarniskoita ollut, vaan ainoastaan heidän vaatteensa ja miekkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Kuin he näkivät, että viholliset hyvin hankitut ja raudoitetut olivat, ja että heillä olivat jalot sota-aseet ja harjoitettu sotaväki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Sanoi Juudas väellensä: älkäät peljätkö tätä suurta joukkoa, ja älkäät hämmästykö heidän voimaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Muistakaat, kuinka meidän isämme Punaisessa meressä tulivat pelastetuksi, kuin Pharao suurella sotajoukolla heitä ajoi takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Ja huutakaamme nyt taivaasen, niin Herra myös meitä armahtaa, ja muistaa liiton, jonka hän meidän isillemme tehnyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Ja lyö meidän vihollisemme maahan meidän silmäimme edessä tänäpänä. Ja kaikki pakanat pitää ymmärtämän, että se on Jumala, joka auttaa ja pelastaa Israelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Kuin pakanat näkivät, että Juudas tuli heitä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Läksivät he myös leiristänsä sotimaan Juudaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Mutta Juudas antoi puhaltaa vaskitorviin ja löi vihollisia; ja pakanat lyötiin pakoon, ja he pakenivat siltä väliltä ja ne jälkimäiset lankesivat miekan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Sillä Juudas ajoi heitä takaa hamaan Assaremotin ja Edomin ketoon asti, Asdodiin ja Jamniaan asti, ja heistä laukesi siellä kolmetuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Mutta kuin Juudas ja hänen sotaväkensä palasi heitä takaa ajamasta, haastoi hän väkeänsä ja sanoi: ei teidän pidä mitään saalista ottaman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Sillä meidän pitää vielä kerran sotiman vihollisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Gorgias on väkinensä meidän edessämme mäellä; sentähden seisokaat nyt niinkuin te asetetut olette vihollista vastaan, ja puolustakaat teitänne, ja kuin te olette viholliset lyöneet, niin te saatte pelkäämättä ja ilman vaaraa saaliin ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Kuin Juudas näitä puhui, näkyi yksi joukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Ja Gorgias näki, että hänen väkensä lyöty oli ja heidän leirinsä poltettu, sillä hän näki savun, josta hän ymmärsi, mitä tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Näkivät he myös Juudaan ja hänen sotaväkensä väljällä olevan, hankitut sotaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Sentähden hämmästyi Gorgias sangen kovin, ja pakeni pakanain maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Ja niin käänsi Juudas itsensä takaperin saaliin päälle, joka leirissä oli, ja sai suuren tavaran, paljon kultaa, hopiaa, silkkiä, purppuraa ja paljon muuta riistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'Sitte menivät he kotiansa, kiittivät ja kunnioittivat Jumalaa veisuilla, ja sanoivat: kiittäkäät Herraa, sillä hän on laupias, ja hänen laupiutensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Tänäpänä sai Israel kuuluisan voiton.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Mutta ne pakanat, jotka päässeet olivat, tulivat Lysiaan tykö, ja sanoivat hänelle, kuinka heille tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Kuin hän sen kuuli, tuli hän sangen murheelliseksi, ettei se niin tapahtunut, kuin kuningas oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Sentähden kokosi Lysias taas toisena vuotena kohta sen perästä paljon sotaväkeä, kuusikymmentä tuhatta jalkamiestä ja viisituhatta ratsasmiestä lyömään Juudalaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Tämä sotajoukko meni Idumeaan, ja sioitti itsensä Betsuran tykö; sinne tuli myös Juudas kymmenellätuhannella miehellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Mutta kuin hän näki, että vihollisella niin paljo väkeä oli, rukoili hän ja sanoi: kiitos olkoon sinulle, sinä Israelin vapahtaja, sinä, joka sinun palveIias Davidin käden kautta löit suuren sankarin, ja koko pakanain sotajoukon annoit Jonatanin Saulin pojan ja hänen palveliansa käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Minä rukoilen sinua, ettäs myös tahtoisit nämät meidän vihollisemme antaa.kansas Israelin käsiin, että he väkensä ja ratsasmiestensä kanssa häpiään tulisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Anna heille hämmästynyt ja vapiseva sydän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 33, 'Ja lyö heitä niiden miekalla, jotka sinua rakastavat, että kaikki mahtaisivat sinua kiittää ja kunnioittaa, jotka sinun nimes tuntevat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 34, 'Sitte löi hän heitä, ja Lysiaan väestä lankesi viisituhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 35, 'Mutta kuin Lysias näki, että hänen väkensä pakeni, ja Juudalaiset olivat rohkiat ja valmiit sekä kunniallisesti elämään että kunniallisesti kuolemaan, meni hän Antiokiaan ottamaan sotaväkeä jälleen, että hän vielä vahvempana olis tullut Juudalaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 36, 'Mutta Juudas ja hänen veljensä sanoivat: että meidäu vihollisemme on karkotettu, niin käykäämme puhdistamaan ja uudistamaan pyhä sia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 37, 'Sen tähden tuli sotaväki yhteen, ja menivät kaikki ylös Zionin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 38, 'Ja kuin he näkivät, että pyhä sia oli hävitetty, ja alttari saastutettu, portit poltetut, ja esikartanoissa vesat ja ruohot kasvoivat, niinkuin metsässä ja mäellä, ja pappein asumasiat maahan rauvenneeksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 39, 'Silloin he repäisivät vaatteensa, ja itkivät katkerasti ja panivat tuhkaa päänsä päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 40, 'Lankesivat maahan kasvoillensa, ja antoivat soittaa vaskitorvella, ja huusivat taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 41, 'Ja Juudas asetti yhden joukon estämään vihollisia, jotka linnassa olivat, kuin hän oli puhdistava pyhää siaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 42, 'Ja asetti siihen papit, jotka ei itsiänsä saastuttaneet, vaan olivat olleet pysyväiset laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 43, 'Nämät puhdistivat pyhän sian, ja veivät pois kauhistuksen ja saastaiset kivet saastaiseen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 44, 'Ja että polttouhrln alttari myös saastutettu oli, pitivät he neuvoa, kuinka heidän sen kanssa piti tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 45, 'Ja löysivät hyvän neuvon: että se piti peräti maahan purettaman, ettei siitä pahennusta pitänyt tuleman, että pakanat olivat saastuttaneet sen; sen tähden lyötiin se kaikki maahan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 46, 'Ja panivat tallelle kivet mäelle lähes huonetta, erinomaiseen paikkaan, siihenasti kuin joku propheta olis tullut ja sanonut, mitä niillä piti tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 47, 'Mutta he ottivat toiset uudet vuolemattomat kivet lain jälkeen, ja tekivät uuden alttarin, senkaltaisen kuin se entinenkin oli ollut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 48, 'Ja rakensivat pyhän huoneen jälleen, ja istuimet ja pappein olinsiat huoneissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 49, 'Ja antoivat uudet pyhät astiat tehdä, kultaisen kynttiläjalan, suitsutusalttarin ja pöydän. ja veivät ne jälleen templiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 50, 'Ja panivat savukaluin alttarille, ja sytyttivät lamput kynttiläjalassa valistamaan templissä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 51, 'Panivat leivät pöydälle, ja ripustivat ylös esiripun, ja toimittivat templin kauniisti jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 52, 'Ja viidentenä päivänä kolmattakymmentä yhdeksännessä kuukaudessa, joka kutsutaan Kasleu, kahdeksantena vuotena viidettäkymmentä toista sataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 53, 'Nousivat he varhain ylös ja uhrasivat lain jälkeen polttouhrin alttarilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 54, 'Tämä oli ensimmäinen uhri, sittekuin pakanat pyhän saastuttaneet olivat, ja tämä uhri uudistettiiu veisuilla, huiluilla, kanteleilla ja symbaleilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 55, 'Ja kaikki kansa lankesi kasvoillensa, rukoilivat ja kiittivät Herraa taivaasta, joka heille onnen ja voiton antanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 56, 'Ja pitivät uuden alttarin juhlaa kahdeksan päivää, ja uhrasivat sen päällä polttouhria ja kiitosuhria ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 57, 'Ja kaunistivat templin kultaisilla seppeleillä ja kilvillä, ja tekivät uudet portit ja asuinhuoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 58, 'Ja suuri ilo oli kansan seassa, että se häpiä heiltä otettiin pois, jonka pakanat olivat saattaneet heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 59, 'Ja Juudas ja hänen veljensä, ja kaikki Israelin kansa asettivat joka vuosi pidettää viidennestä päivästä kolmattakymmentä Kasleyn kuulla, kahdeksan päivää, sen uuden alttarin juhlaa ilolla ja kiitoksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 60, 'Ja he rakensivat lujat muurit ja tornit templin ympäri Zionin vuorelle, ettei pakanat olisi taitaneet saada ja hävittää pyhää, niinkuin ennen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 61, 'Ja Juudas pani sotaväkeä varjelemaan pyhää; hän vahvisti myös Betsuran, että kansalla olis linna Idumeaa vastaan, jossa he olisivat taitaneet varjella itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Mutta kuin pakanat ympäristöllä kuulivat, että alttari oli jälleen pantu ylös ja pyhä puhdistettu, julmistuivat he sangen kovin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Ja ajattelivat, kuinka he voisivat hävittää koko Jakobin sukukunnan, ja rupesivat tappamaan kaikkia Juudalaisia heidän rajoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Mutta Juudas vaelsi Idumeaan Esaun lapsia vastaan, ja hyökkäsi heidän päällensä Arabatissa, kussa he Israelin lapset piirittäneet olivat, ja löi monta Idumealaista kuoliaaksi, Ja otti heidän kalunsa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Ja että myös Beanin lapset olivat tiellä pettäneet ja murhanneet Israelin lapsia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Ajatteli Juudas myös sitä, ja peräti hukutti heidät, ja poltti heidän linnansa, kaikkein niiden kanssa, jotka siinä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Senjälkeen vaelsi hän Ammonin lapsia vastaan, jotka hyvin varustetut olivat ja heillä oli paljo sotaväkeä, ja heidän päämiehensä oli Timoteus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Ja Juudas piti heidän kanssansa monta sotaa ja sai voiton,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Ja voitti Jatserin kaupungin ja muut ympäriolevaiset kylät, ja palasi Juudeaan jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Mutta pakanat Galaadissa hankitsivat myös Israelia vastaan rajoissansa, heitä surettamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Vaan kansa pakeni Dateman linnaan, ja kirjoittivat Juudaan ja hänen veljeinsä tykö näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Kaikki pakanat tässä ympäristöllä ovat kokoontuneet meitä vastaan, meitä kaikkia hävittämään, ja heidän päämiehensä on Timoteus: nämät tahtovat tulla väkirynnäköllä linnaamme, johonka me olemme paenneet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Sen tähden me rukoilemme, että sinä tulisit meille avuksi varjelemaan meitä; meitä on vähä, sillä viholliset ovat monta maahan lyöneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Ja Tubissa tappaneet liki tuhannen miestä, ja vieneet pois heidän vaimonsa, lapsensa ja tavaransa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Kuin tätä kirjaa luettiin, tulivat toiset sanansaattajat Galileasta reväistyilIä vaatteilla, surkuttelivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Ja sanoivat, että pakanat kaikista kaupungeista siinä ympäri Ptolomaista, Tyrosta ja Sidonista, ovat vaeltaneet suurella voimalla Galilean lävitse ja että koko Galilea oli täynnä vihollisia, jotka tulleet olivat Israelia hävittämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Kuin Juudas ja kansa tämän kuulivat, pitivät he neuvoa, kuinka he olisivat voineet auttaa veijiänsä tässä vaivassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Ja Juudas käski veljensä Simonin valita itsellensä erinomaisen väen ja mennä Galileaan, auttamaan veljiänsä, ja itse tahtoi hän veljensä Jonatanin kanssa matkustaa Galaadiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Ja teki Josephin, Sakarian pojan, ja Atsarian sen väen päämieheksi, joka kotia jäi varjelemaan Juudaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Ja käski heidän hallita kansaa, ja kielsi lähtemästä vihollisia käsittelemään, siihenasti kuin hän olis tullut jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Ja Simon vaelsi Galileaan kolmellatuhannella miehellä, ja Juudas Galaadiin kahdeksallatuhannella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Kuin Simon tuli Galileaan, tappeli hän monasti pakanain kanssa, ja voitti ja ajoi heitä takaa hamaan Ptolomain portin eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Niin että liki kolmetuhatta pakanaa tapettiin, ja Simon otti heidän tavaransa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Sitte tuli hän jälleen veljeinsä tykö Galileaan ja Arabatiin, ja käski heidät vaimoinensa ja lapsinensa matkustaa hänen kanssansa Juudeaan, ja vei heidät sinne suurella ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Mutta Juudas Makkabealainen ja Jonatan hänen veljensä matkustivat Jordanin ylitse erämaahan, kolmen päiväkunnan matkan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'SilIoln tullvat heidän tykönsä Nabatealaiset, ja ottivat heidät ystävällisesti vastaan, ja juttelivat heille, kuinka heidän veljillensä Galaadissa kävi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Ja että monta oli viety vankina pois Barasaan, Bosoriin, Alimaan, Kasboon, Magethiin ja Karnaimiin, jotka kaikki olivat suuret ja lujat kaupungit, että myös monta niissä muissa Galaadin kaupungeissa vankina olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Sentähden he päättivät, että he kohta huomeneltain sen jälkeen tahtoivat matkustaa vahvoja kaupungeita vastaan, niitä väkisin ottamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Ja Juudas palasi päiväkunnan matkan takaperin, ja meni Bosorin kaupungin päälle, ennenkuin he taisivat pitää vaarinsa, ja sai sen väkisin ja antoi siinä tappaa kaiken miehenpuolen, ja otti heidän tavaransa, ja poltti kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Senjälkeen meni hän kohta yöllä linnaan, johon hänen veljensä ahdistetut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Ja kuin hän huomeneltain sinne tuli, näki hän siellä sangen suuren joukon väkeä, joiden lukua ei tiedetty, jotka tikapuita ja sota-aseita kantoivat, ja rupesivat rintarynnäköllä hyökkäämään sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Ja kaupungissa oli surkia huuto, niin että se kajahti ylös taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Silloin neuvoi Juudas väkensä sotimaan veljeinsä edestä ja auttamaan heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Ja teki kolme joukkoa, ja löi takaa heidän päällensä, ja antoi vaskitorvet soida, vaan kansa, huusi korkiasti ja rukoili Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 34, 'Mutta kuin Timoteuksen sotajoukko näki, että Juudas oli heidän takanansa, pakenivat he, ja lyötiin kovin, niin että heistä kuo- li sinä päivänä liki kahdeksantuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 35, 'Sitte matkusti Juudas Matsphaan ja kävi sen päälle väkirynnäköllä ja voitti sen, ja antoi myös siinä tappaa kaikki miehenpuolen, otti tavaran, ja poltti kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 36, 'Sitte voitti hän Kasbonin, Magetin, Bosorin ja muut kaupungit Galaadissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 37, 'Mutta Timoteus kokosi taas suuren joukon, ja sioitti itsensä Raphouin kohdalle sillä puolella ojaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 38, 'Niin lähetti Juudas miehet sinne tutkimaan ja katsomaan, kuinka vahva vihollinen oli, ja kuinka he makasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 39, 'Nämät toivat hänelle tiedon, että se oli sangen suuri joukko kaikista pakanoista ympäristöltä, ja heillä oli myös palkkaväkeä Arabiasta, ja tämä väki makasi toisella puolella ojaa, ja olivat varustetut tappelemaan; sentähden meni Juudas ylös heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 40, 'Ja Timoteus sanoi päämiehillensä: jos Juudas tulee ojan tykö, ja on niin rohkia, että hän ehtii tänne tulla ylitse, niin emme voi olla häntä vastaan, vaan hän lyö meidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 41, 'Mutta jos hän pelkää, ja ei uskalla tänne ojan ylitse, niin me tahdomme veden ylitse hänen tykönsä, hyökätä hänen päällensä, ja lyömme hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 42, 'Kuin Juudas tuli ojan tykö, asetti hän papit rantaan, ja antoi heille käskyn kaikkea väkeä vaatimaan, ettei yksikään olisi jäänyt, vaan olleet avulliset lyömään vihollisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 43, 'Kuin Juudas tuli joukkoinensa veden ylitse, pakenivat viholliset, ja pudottivat aseensa maahan, tulivat yhteen templiin Karnaimin kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 44, 'Mutta Juudas sai kaupungin, ja poltti templin ja kaikki ne, jotka siinä olivat. Näin Karnaim kukistettiin, ja ei voinut itsiänsä varjella Juudaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 45, 'Sitte antoi Juudas tulla kokoon kaiken Israelin kansan kuin Galaadissa oli, pienet ja suuret, vaimot ja lapset, menemään kanssansa Juudeaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 46, 'Ja matkallansa tulivat he yhden suuren vahvan kaupungin tykö, Ephron nimeltä, joka oli valtamaantiessä, jonka ympäri ei saatu mennä, vaan heidän piti vaeltaman sen lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 47, 'Ja ne Ephronista ei tahtoneet päästää Juudaa sen lävitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 48, 'Vaan olivat kaupungissa, ja pitivät portit kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 49, 'Mutta Juudas lähetti heidän tykönsä, sanoi heille rauhan, ja rukoili ystävällisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 50, 'Että he olisivat heidät laskeneet lävitse, niin ei heille pitänyt yhtään vahinkoa tapahtuman hänen kansaltansa; ei hän mitään muuta anonut, vaan ainoastaan vaeltaa lävitse; mutta ne Ephronissa ei tahtoneet heitä päästää sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 51, 'Niin Juudas kuulutti ja sanoi kaikelle sotaväelle, että itsekukin heistä piti astuman siallensa, ja hyökkäämän väkirynnäköllä kaupunkiin, kukin joukko paikastansa; ja niin he tekivät koko sen päivän ja kaiken sen yön, ja voittivat kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 52, 'Ja Juudas antoi siinä tappaa kaiken miehenpuolen, otti heidän tavaransa, ja kukisti kaupungin ja vaelsi sen lävitse kuolleiden ruumisten ylitse, ja he tulivat Jordanin ylitse tasaiselle kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 53, 'Ja Juudas vaati kansan, joka perässä oli, joutumaan, ja lohdutti heitä kaiken sen matkan siihen asti, kuin hän vei heidät Juudan maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 54, 'Silloin menivät he ylös Zionin vuorelle suurella ilolla, ja uhrasivat polttouhrin, että Jumala oli heille voiton antanut, ja saattanut heitä ilolla kotiansa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 55, 'Mutta kuin Juudas ja Jonatan vielä Galaadissa olivat, ja Simon heidän veljensä, Galileassa Ptolemain edessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 56, 'Ja Joseph Sakarian poika ja Atsaria, päämiehet, kuulivat heidän voitostansa ja suurista töistänsä, sanoivat he:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 57, 'Me tahdomme myös voittaa kunnian, ja lyödä pakanoita, jotka tässä ympäri asnvat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 58, 'Ja antoivat käskyn sotaväellensä, että heidän piti nouseman, ja matkustivat Jamniaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 59, 'Niin Gorgias kävi ulos heitä vastaan sotaväkinensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 60, 'Ja löi Josephin ja Atsarian pakoon, ja ajoi heitä takaa hamaan Juudan maalle. Ja Israelista tuli pois sinä päivänä paljo väkeä, liki kaksituhatta miestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 61, 'Ettei he Juudaan ja hänen veljeinsä käskyä totelleet, ja olivat sen tehneet omasta röyhkeydestänsä, voittaaksensa kunniaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 62, 'Ehkei he olleet ne miehet, jotka Jumalalta suodut olivat, että Israel heidän kauttansa piti autetuksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 63, 'Mutta Juudaasta ja hänen veljistänsä pidettiin paljon koko Israelissa, ja kaikkein pakanain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 64, 'Ja kussa heidän nimensä mainittiin, siinä he ylistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 65, 'Ja Juudas meni ulos veljiensä Esaun lapsia vastaan lounaan päin, ja voitti Hebronin ja le kylät ympäristöltä, ja poltti hänen muurinsa ja torninsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 66, 'Ja palasi jälleen pakanain maalle Samariaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 67, 'Jossa oli monta pappia tapettu, jotka myös röyhkeät olivat olleet ja käsitelleet pakanoita neuvomatta ja ilman käskyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 68, 'Sitte vaelsi Juudas Asdodiin, pakanain maalle, ja epäjumalain alttarit kukisti, ja poltti epäjumalat, ja otti saaliin kaupungeista, ja tuli jälleen kotiansa Juudan maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Antiokus Epiphaneksen kuoltua, tulee hänen poikansa Antiokus Eupator hänen siaansa. Mutta kuin kuningas Antiokus vaelsi sinne ja tänne ylimmäisessä valtakunnassa, sanottiin hänelle siitä kuuluisasta kaupungista Elimadista, joka oli Persian maakunnassa, että siinä oli paljo kultaa ja hopiaa ja suuret rikkaudet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Ja että templissä olivat suuret tavarat ja kultaiset vaatteet, haarniskat ja kilvet, jotka Philippuksen poika, kuningas Aleksander Makedoniasta, siihen antanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Tuli sentähden Antiokus sen kaupungin alle, saamaan ja ryöstämään sitä; mutta ne, jotka kaupungissa olivat varustetut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Sen tähden olivat he valmiit varjelemaan itseänsä. Ja ei Antiokus taitanut mitään toimittaa, vaan täytyi palata jälleen tietänsä myöten Babeliin päin suurella murheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Silloin sai hän sanoman, että hänen sotaväkensä, jonka hän Juudan maalle lähettänyt oli, lyöty oli, ja Lysiaan oli täytynyt paeta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Ja että Juudalaiset olivat voittaneet hänen leiristänsä suuret tavarat ja paljon sota-aseita, joilla he sitte olivat itsensä paremmin varustaneet, ja tulleet voimallisemmaksi');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Ja olivat heittäneet ulos kauhistuksen Jerusalemin templistä, ja vahvistaneet pyhän jälleen vahvalla muurilla niinkuin ennenkin, ja myös vahvistaneet Betsuran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Kuin Antiokns tämän puheen kuuli, hämmästyi hän sangen suuresti, ja tuli ylönpalttisesti murheelliseksi, ja laski itsensä vuoteelle, ja tuli murheesta sairaaksi, ettei hänen aikomuksensa menestynyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Ja viipyi kauvan siinä kaupungissa; sillä murhe, jota pitemmältä, sitä raskaampi se oli hänelle, ja teki hänen niin heikoksi, että hän ymmärsi sen kautta kuolevansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Sentähden kutsui hän ystävänsä tykönsä, ja sanoi heille: en minä taida enään unta saada suuren murheen ja sydämen surun tähden, joka minulla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Voi kuinka kaikki minun menoni toisin päin kääntynyt on! Niinkauvan kuin minä olen hallinnut, on minulla ilo ja voitto ollut, ja olen minun omiltani rakastettu ja suurena pidetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Mutta nyt olen minä niin sydämestä murheellinen, ja minun mieleeni johtuu se paha, jonka minä Jerusalemissa tehnyt olen, kuin minä kaikki kulta. ja hopia-astiat templistä vein pois, ja annoin tappaa viattomat ihmiset Juudeassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Siitä tulee nyt minulle kaikki tämä onnettomuus, ja täytyy vieraalla maalla tässä surussa kuolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Ja hän kutsui ystävänsä Philippuksen, sen hän asetti koko valtakunnan päämieheksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Ja antoi hänelle kruunun, kaapun ja sormuksen, ja käski hänen kasvattaa hänen poikansa nuoren Antiokuksen ja asettaa valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Ja niin Antiokus kuoli siinä kaupungissa, yhdeksäntenä ajastaikana viidettäkymmentä toistasataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Kuin Lysias kuuli, että kuningas kuollut oli, teki hän Antiokus Epiphaneksen pojan kuninkaaksi, nuoren Antiokuksen, jonka opetusisä hän oli ollut, ja nimitti hänen Eupatoriksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Ja pakanat, joiden hallussa Zionin linna vielä oli, tekivät Israelin kansalle paljon vahinkoa pyhässä; sillä heillä oli hyvä luja linna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Sentähden ajatteli Juudas ahdistaa heitä, että hän olis heidät surettanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Ja kansa tuli kokoon viidentenäkymmenentenä vuotena toista sataa, ja toi sen eteen kaikkinaisia sota-aseita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Ja muutamat pakanoista läksivät ulos linnasta menemään kuninkaan tykö apua anomaan. Heidän seuraansa antoivat itsensä monta, jotka Israelista luopuneet olivat, ja menivät heidän kanssansa kuninkaan tykö, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Miksi et tahdo rangaista, ja meidän veljeimme tähden kostaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Sillä me tahdoimme olla sinun isälles alamaiset ja hänen käskyllensä kuuliaiset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Sentähden meidän kansa luopui meistä, ja kussa he saivat meistä jonkun kiinni, niin he tappoivat sen, ja jakoivat meidän perimisemme keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 25, 'Ja ei ainoastaan ole vaivanneet meitä, mutta senkaltaisia ovat he tehneet koko maakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 26, 'Ja nyt ahdistavat linnan Jerusalemissa, ottaaksensa sitä, ja ovat vahvaksi rakentaneet pyhän ja Betsuran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 27, 'Ellet sinä nyt riennä sinuas estämään heitä, niin he tulevat vahvemmiksi, ja tekevät enempi vahinkoa, ja et sinä taida sitte enään heitä hillitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 28, 'Kuin kuningas senkaltaisia kuuli, julmistui hän sangen suuresti, ja antoi kutsua kokoon ruhtinaansa, ja jalkaväen ja hevosväen päämiehet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 29, 'Ja otti muukalaista palkkaväkeä luotokunnista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 30, 'Ja kokosi satatuhatta miestä jalkaväkeä, ja kaksikymmentä tuhatta ratsasmiestä, ja kaksineljättäkymmentä elephanttia, jotka sotaan olivat harjoitetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 31, 'Tämä sotaväki vaelsi Idumean lävitse; ja kuin he tulivat maalle, piirittivät he Betsuran, ja asettivat sen alle monenkaltaiset sodanneuvot, mennäksensä väkirynnäköllä sisälle. Mutta Juudalaiset tulivat ulos, ja polttivat ne rakennukset, ja sotivat miehuullisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 32, 'Ja Juudas luopui Zionin linnasta, ja tuli sotaväen kanssa Betsakaraan kuninkaan leiriä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 33, 'Silloin oli kuningas huomeneltain varhain ylhäällä ennen päivää, ja johdatti sotaväen Betsakaran tielle, ja antoi asettaa rintasodan, ja vaskitorvea soittaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 34, 'Ja priiskottaa elephantit punaisella viinalla ja morin marjan nesteellä, kehoittaaksensa heitä käymään edes ja vihastumaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 35, 'Ja jakoi elephantit joukkoin keskelle, että kunkin elephantin tykö oli asetettu tuhannen jalkamiestä rautalakeilla ja haarniskoilla, ja viisisataa hevosmiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 36, 'Nämät ottivat vaarin elephantista niin ettei he välttäneet pois sen tyköä, ja kuhunka elephantti käännettiin, sinne myös heidän piti kääntymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 37, 'Ja kukin elephantti kantoi selässänsä puutornia, jossa kaksi neljättäkymmentä sotamiestä oli, ja se mies, joka eläintä ajoi ja hallitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 38, 'Ne muut hevosmiehet asetti hän molemmille puolille estämään jalkaväkeä toinen toisestansa hajoamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 39, 'Ja kuin aurinko koitti ja paisti kultaisten kilpien päälle, leimahti koko vuori siitä, niinkuin se kaikki olis ollut tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 40, 'Ja kuninkaan sotaväestä meni osa vuorelle ja osa alas lakialle kedolle visusti, hyvässä järjestyksessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 41, 'Ja joka heidät kuuli, se peljästyi siitä hirmuisesta pauhinasta ja suuresta väen paljoudesta, ja siitä helinästä, jonka heidän haarniskansa ja rautansa antoivat; sillä se oli sangen suuri ja hyvin varustettu sotajoukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 42, 'Ja Juudas myös kävi edes joukkoinensa varjelemaan itsiänsä, ja löi kuusisataa kuoliaaksi kuninkaan väestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 43, 'Ja Eleasar, Sauran poika, otti vaaria yhdestä elephantista, että se oli suurin ja paremmin valmistettu kuin muut, ja luuli kuninkaan sen päällä olevan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 44, 'Ja rohkeni sen kimppuun, että hän olis avun saattanut kansallensa Israelille, ja saanut ijankaikkisen nimen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 45, 'Ja juoksi sen tykö suurella rohkeudella, ja tunki itsensä vihollisten lävitse, ja tappoi monta heistä molemmilta puoliltansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 46, 'Ja antoi itsensä elephantin alle ja pisti sen, niin että elephantti lankesi hänen päällensä ja kuoli, kuoli hän myös itse sen alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 47, 'Mutta että juudalaiset näkivät, että kuninkaan sotaväki niin väkevä oli, välttivät he sivulle, ja hylkäsivät viholliset sillä erällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 48, 'Sentähden meni kuninkaan sotaväki Jerusalemiin, ja tulivat Juudeaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 49, 'Mutta ne, jotka Betsurassa olivat, ei voineet enään siinä olla nälän tähden; sillä se oli seitsemäs vuosi, jolla piti maalle lepo oleman; ja he saivat luvan kuninkaalta, että heidän piti menemän ulos pelkäämättä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 50, 'Niin kuningas otti Betsuran, ja pani siihen sotaväen, varjelemaan linnaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 51, 'Ja vaelsi Zioniin, ja piiritti pyhän kauvaksi aikaa, ja valmisti siinä kaikkinaiset sota-aseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 52, 'Mutta Israelin kansa varjeli itsensä pyhässä monta päivää, ja tekivät he myös moninaisia sota-aseita vihollisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 53, 'Mutta ei heilläkään ollut mitään syötävää, että se oli se seitsemäs vuosi, ja ne vieraat Juudalaiset, jotka pakanain maalta Juudeaan tuodut olivat, että he olisivat siellä olleet varjellut, olivat kaiken ravinnon kuluttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 54, 'Ja pyhät olivat sangen harvat; sillä he kuolivat nälästä, sen. tähden täytyi heidän erota toinen toisestansa, ja itsensä jakaa kukin paikkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 55, 'Sillä välillä sai Lysias kuulla, että Philippus, jonka haltuun kuninkaan isä nuoren kuninkaan, ja valtakunnan eläissänsä oli antanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 56, 'Oli jälleen tullut Persiasta ja Mediasta sillä sotaväellä, jonka kuningas sinne vienyt oli; ja että Philippus rupesi hallitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 57, 'Sentähden riensi hän pois Juudeasta kotiansa jälleen valtakuntaan, ja sanoi kuninkaalle ja päämiehille: me kärsimme tässä vaivaa ja ei ole meillä mitään syötävää, ja meiltä on paljo väkeä tullut pois, ja tämä sia, jonka me piirittäneet olemme, on sangen vahva, ja meillä on kyllä kotona valtakunnassa toimittamista, jotka asiat korkeammat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 58, 'Tehkäämme rauha tämän kansan kanssa, ja sallikaamme heidän pitää lakinsa, niinkuin he ennenkin pitäneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 59, 'Sillä ainoasti sentähden he vihaiset ovat ja sotivat, että me tahdomme panna pois heidän lakinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 60, 'Tämä puhe kelpasi kuninkaalle ja päämiehille hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 61, 'Ja kuningas lähetti heidän tykönsä, tekemään rauhaa heidän kanssansa; johon he suostuivat, sillä kuningas päämiehinensä vannoi sen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 62, 'Mutta kuin he tulivat ulos linnasta, meni kuningas sinne sisälle; ja kuin kuningas näki, että se niin vahva oli, niin ei hän pitänyt valaansa, vaan käski kaikki muurit ympäriltä lyödä jälleen maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 63, 'Sitte vaelsi hän kiiruusti Antiokiaan. Silloin sai hän ymmärtää, että Philippus oli siellä itsensä tehnyt kuninkaaksi, sen tähden soti hän hänen kanssansa, ja otti kaupungin jälleen väkiväellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 1, 'Ensimäisenä vuotena kuudettakymmeutä toista sataa tuli Demetrius Seleukuksen poika Roomista jälleen valtakuntaansa, ja sai yhden merikaupungin vähällä väellä, ja hallitsi siinä kuninkaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 2, 'Ja kuin hän pääkaupunkiin Antiokiaan tuli, otti sotaväki Antiokuksen ja Lysiaan kiinni, antaaksensa heitä Demetriuksen haltuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 3, 'Vaan kuin se Demetriukselle sanottiin, kielsi hän heitä antamasta hänen tulla silmäinsä eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 4, 'Sentähden tappoi sotaväki heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 5, 'Kuin Demetrius oli valtakunnan saanut, tuli hänen tykönsä monta jumalatointa ja luopunutta Israelista, ja ylimmäinen heistä oli Alkimus, joka olis mielellänsä ollut ylimmäinen pappi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 6, 'Nämät kantelivat Juudaan ja oman kansansa päälle, ja sanoivat: Juudas ja hänen veljensä ovat tappaneet eli ajaneet ulos meidän maaltamme kaikki, jotka sinulle tahtoivat kuuliaiset olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 7, 'Sentähden lähetä sinne joku, jonka sinä uskot, ja anna katsoa kuinka he meidän ja kuninkaan maan ovat hävittäneet, ja anna heitä rangaista ja kaikkia, jotka pitävät heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 8, 'Sen tähden teki kuningas ystävänsä Bakkideksen (joka jalo oli valtakunnassa, ja johon kuningas paljon uskoi,) koko sen maakunnan päämieheksi, tuolla puolella Euphratin virran,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 9, 'Ja lähetti hänen kanssansa luopuneen Alkimuksen, jonka hän myös ylimmäiseksi papiksi teki, ja käski hänen Israelin kansaa rangaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 10, 'Ja he menivät Juudan maalle suurella sotajoukolla, ja hän lähetti sanansaattajat Juudaan ja hänen veljeinsä tykö sovintoa toimittamaan, Ja teettelivät itsensä niinkuin he olisivat tahtoneet pitää rauhan heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 11, 'Vaan se oli kaikki petos; sentähden ei Juudas heitä uskonut, sillä hän näki, että he niin jalosti varustetut olivat, ja näin suurella sotajoukolla vaelsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 12, 'Mutta monta pappia tuli Alkimuksen ja Bakkideksen tykö, ja monta muuta hurskasta, jotka Israelissa olivat, ja toivoivat hyvää Alkimuksesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 13, 'Ja anoivat rauhaa, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 14, 'Alkimus on pappi Aaronin suvusta, ei hän meitä petä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 15, 'Alkimus lupasi heille rauhan, ja teki valan ja sanoi: emme tahdo teille eikä teidän ystävillenne mitään pahaa tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 16, 'Kuin he niin uskoivat hänen, antoi hän ottaa kiinni kuusikymmentä heistä, ja tappoi kaikki yhtenä päivänä, niinkuin kirjoitettu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 17, 'Sinun pyhäis lihat ovat he pedoille antaneet; he ovat vuodattaneet verta ympäri Jerusalemin niinkuin vettä, ja ei ollut siellä ketään, joka heitä hautasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 18, 'Sen tähden tuli sangen suuri pelko ja vavistus kansalle, jotka valittivat, ettei Alkimuksessa ollut totuutta eikä uskollisuutta; sillä ei hän pitänyt valaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 19, 'Ja Bakkides vaelsi matkaansa Jerusalemista, ja piiritti Betsetan, ja lähetti ja antoi ottaa monta kiinni, jotka ensin olivat itsensä antaneet hänen tykönsä, vaan petoksen tähden jälleen luopuneet hänestä, ja antoi monta heistä tappaa ja heittää suureen luolaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 20, 'Sitte antoi Bakkides maan Alkimuksen haltuun, ja jätti sotaväkeä hänelle, ja meni jälleen kuninkaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 21, 'Ja Alkimus aikoi väkivallalla olla ylimmäinen pappi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 22, 'Ja veti tykönsä kaikki luopuneet Israelista, ja otti väkisin Juudan maan allensa, ja vaivasi Israelin kansaa sangen raskaasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 23, 'Kuin Juudas näki, että Alkimus ja ne luopuneet Israelista tekivät paljon vahinkoa Israelissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 24, 'Meni hän taas ympäri koko Juudan ja rankaisi ne luopuneet, ja esti, ettei he enään sinne eikä tänne rohjenneet maakunnassa vaeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 25, 'Mutta kuin Alkimus näki, että Juudas ja hänen väkensä jälleen voimaansa tulivat ja ettei hän taitanut olla heitä vastaan, meni hän jälleen kuninkaan tykö, ja kantoi kovin heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 26, 'Sentähden lähetti kuningas sinne yhden suuren ruhtinaan Nikanorin, joka Israelin kansalle juuri armotoin oli, ja käski hänen peräti hävittää Israelin kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 27, 'Ja Nikanor meni suurella sotajoukolla Jerusalemiin, ja lähetti sanan Juudaan ja hänen veljeinsä tykö petoksella, niinkuin hän tahtonut olis rauhaa heidän kanssansa tehdä, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 28, 'Minä tahdon pitää rauhan teidän kanssanne, ja vähällä väellä tulla sovinnossa puhuttelemaan sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 29, 'Näin tuli Nikanor Juudaan tykö, ja ottivat toinen toisensa vastaan, ja puhuttelivat keskenänsä sovinnolla; vaan se oli toimitettu, että Juudas piti siellä otettaman kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 30, 'Se tuli Juudaalle tiettäväksi, että Nikanor oli tullut ottamaan häntä kiinni petoksella, sen. tähden kartti hän häntä, eikä tahtonut enää tulla hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 31, 'Ja kuin Nikanor sen havaitsi, että hänen aivoituksensa oli julki tullut, meni hän Juudaa vastaan, ja tappeli hänen kanssansa Kaphar Salaman tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 32, 'Siinä tuli pois Nikanorilta viisituhatta miestä, ja hänen väkensä täytyi paeta Davidin linnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 33, 'Tuli myös Nikanor senjälkeen ylös pyhään Zionin vuorelle, ja papit ja vanhimmat menivät ulos ottamaan häntä rauhallisesti vastaan, ja antamaan hänen nähdä, että he kuninkaan tähden suuren uhrin tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 34, 'Mutta Nikanor sylki heitä ja heidän jumalanpalvelustansa, häpäisi ja saastutti uhrin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 35, 'Ja vannoi valan ja sanoi: ellette saata Juudaa ja hänen väkeänsä minun käsiini, niin minä tahdon polttaa tämän huoneen niin pian kuin minä rauhassa tähän jälleen tulen; ja vaelsi matkaansa suuressa julmuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 36, 'Mutta papit menivät sisälle, ja astuivat alttarin eteen templissä, itkivät ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 37, 'Herra, että sinä tämän huoneen valinnut olet, sinua tässä rukoiltaa ja sinusta saarnattaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 38, 'Niin me rukoilemme, ettäs tahtoisit kostaa Nikanorin ja hänen joukkonsa, ja muistaa. että he sinun pyhäs ja sinua pilkanneet ovat, ja ettäs tahtoisit heitä karkottaa pois maasta ja hukuttaa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 39, 'Ja Nikanor vaelsi matkaansa Jerusalemista, ja sioitti itsensä Bethoronin tykö. Siihen tuli myös yksi joukko Syriasta häntä auttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 40, 'Mutta Juudas asetti väkensä häntä vastaan Adassarissa, kolmetuhatta miestä, rukoili Jumalaa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 41, 'Herra Jumala! koska kuningas Sennaheribilta lähetetyt miehet sinua pilkkasivat, lähetit sinä enkelin, joka löi maahan sata kahdeksankymmentä ja viisituhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 42, 'Niin lyö myös tänäpänäkin nämät meidän vihollisemme meidän nähtemme, ja tuomitse Nikanor hänen suurten pahain tekoinsa jälkeen, että muut ymmärtäisivät sinun häntä sentähden rangaisseen, että hän sinun pyhääs häväissyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 43, 'Ja kolmantena päivänä toistakymmentä Adarin kuuta tappelivat he toinen toisensa kanssa. ja Nikanor tuli kaikkein ensimäisenä lyödyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 44, 'Ja kuin hänen väkensä sen näki, heittivät he aseensa pois ja pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 45, 'Mutta Juudas ajoi heitä takaa päiväkunnan matkan Adassarasta hamaan Gasaraan asti, ja antoi vaskitorvella soittaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 46, 'Että kaikki kansa kaikista kylistä ympäri sen maakunnan olisivat tulleet hänen tykönsä häntäi auttamaan, ja lyömään vihollisia; ja he tulivat Juudaan tykö, ja pitivät taas yhtä hänen kanssansa. Näin tuli Nikanorin väki lyödyksi, ettei yksikään heistä päässyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 47, 'Ja Juudas otti heidän saaliinsa ja kalunsa ja vei myötänsä. Vaan Nikanorilta antoi hän pään hakata pois, ja oikian käden, jonka hän valassansa oli nostanut ylös, kuin hän pilkkasi ja uhkasi pyhää; ja antoi sekä pään että käden viedä pois ja Jerusalemissa ripustaa ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 48, 'Silloin kansa tuli jälleen suuresti iloiseksi, ja piti tämän päivän pyhänä suurella ilolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 49, 'Ja sääsi, että sinä päivänä joka vuosi, nimittäin kolmantena päivänä toistakymmentä Adarin kuulla, piti pyhää pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 7, 50, 'Ja näin tuli rauha jälleen Israelin maalle vähäksi ajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 1, 'Juudalaisten liitosta Roomalaisten kanssa. Mutta Juudas kuuli, että Roomalaiset olivat sangen voimalliset ja mielellänsä ottivat muukalaisia varjeluksensa alle, jotka heiltä apua etsivät ja pitivät sanansa uskollisuudessa ja toimellisuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 2, 'Sillä hän kuuli, kuinka voimallisia töitä he olivat Frankriikin asuvaisia vastaan tehneet, joita he vaatineet ja allensa saattaneet olivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 3, 'Ja kuinka suurta sotaa he Hispaniassa pitäneet olivat, ja olivat sen vuoren, josta kultaa ja hopiaa kaivetaan, heiltä ottaneet pois, ja että he monta kaukaista maakuntaa Roomista suurella toimella ja vahvuudella olivat voittaneet ja allensa saattaneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 4, 'Että he myös monta jaloa kuningasta, jotka heidän maakuntaansa olivat voimallisesti astuneet, maahan lyöneet olivat ja ajaneet pois, ja heidän valtakuntansa ottaneet allensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 5, 'Ja että he myös äsken Philippuksen, Kittimin kuninkaan ja sen jälkeen hänen poikansa Perseun olivat voittaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 6, 'Kuuli hän myös siitä suuresta Antiokuksesta, Asian kuninkaasta, joka Roomalaisia vastaan oli mennyt sadalla ja kahdellakymmenellä elephantilla, jalosti hankituilla sotaneuvoilla ja vaunuilla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 7, 'Vaan roomalaiset löivät hänen sotaväkensä ja ahdistivat hänen niin, että hänen täytyi rauhaa rukoilla, ja laskivat hänen ja hänen jälkeentulevaisten perillistensä päälle suuren veron, jonka heidän piti roomalaisille joka vuosi antaman, ja vielä päälliseksi täytyi lähettää Roomalaisille yhden miehen panttivangiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 8, 'Ottivat he myös häneltä pois Jonian, Asian ja Lydian, kaikkein parhaat maakunnat, ja antoivat ne kuningas Eumenille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 9, 'Nousivat myös Grekiläiset heitä vastaan suurella väellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 10, 'Vaan he lähettivät yhden päämiehen heitä vastaan, joka löi heidät ja sai maan ja antoi kaupungeista muurit jaottaa, että heidän täytyi rauhan pitää ja kuuliaiset olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 11, 'Senkaltaisen miehuuden osoittivat he kaikkia vihollisiansa vastaan, niin että he kaikkia niitä ahdistivat, jotka heitä vastaan itsensä asettivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 12, 'Mutta ystäviensä ja liittoveljiensä kanssa pitivät he hyvän rauhan uskollisesti, ja olivat niin valtiaat, että heitä kaikissa maakunnissa peljättiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 13, 'Jota he auttivat, se tuli varjelluksi ja sai olla maallansa; vaan jota he tahtoivat sortaa, se tuli ajetuksi pois maaltansa ja valtakunnastansa; he olivat sangen valtiaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 14, 'He olivat niin yksivakaiset, ettei yksikään heistä tehnyt itsiänsä kuninkaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 15, 'Ja ei heillä myös ollut kuningasta, mutta neuvonantajat, kolmesataa ja kaksikymmentä miestä, jotka hyvin hallitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 16, 'Ja joka vuosi he valitsivat yhden päämiehen, joka vallitsi kaikki heidän maakuntansa, ja häntä piti kaikkein kuuleman. Ei myös siellä ollut ylpeyttä, kateutta, taikka eripuraisuutta heidän keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 17, 'Ja Juudas valitsi Eupolemon Johanneksen pojan, joka oli Jakobin poika, ja Jasonin Eleatsarin pojan, ja lähetti heidät Roomiin tekemään ystävyyttä ja liittoa Roomalaisten kanssa, että he olisivat heille avulliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 18, 'Ettei Israelin kuninkaan valtakunta olisi tullut poljetuksi alas Grekiläisten kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 19, 'Nämät vaelsivat Roomiin sangen pitkän matkan, ja tulivat hallituksen eteen ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 20, 'Juudas Makkabealainen ja hänen veljensä ja Juudan kansa ovat lähettäneet meidät teidän tykönne, tekemään rauhaa ja liittoa teidän kanssanne, että te tahtoisitte meitä ottaa teidän varjeluksenne alle, niinkuin ystäviä ja liittoveljiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 21, 'Se kelpasi Roomalaisille hyvin');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 22, 'Ja antoivat kirjoittaa liiton vaskisiin tauluihin, jotka he lähettivät Jerusalemiin, muistoksi senkaltaisesta rauhasta ja liitosta, ja oli näin kirjoitettu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 23, 'Jumala antakoon Roomalaisille ja Juudalaisille onnea ja rauhaa sekä vedellä että maalla, ja varjelkoon heitä sodista ja vihollisista ijankaikkisesti!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 24, 'Mutta jos Roomalaisille sota tapahtuu, taikka Roomissa, eli heidän maakunnissansa ja paikkakunnissansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 25, 'Niin Juudalaisten pitää uskollisesti auttaman Roomalaisia, sen jälkeen kuin tarve on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 26, 'Ja ei pidä heidän Roomin vihollisille mitään elatusta, aseita, rahaa, laivoja eli muuta tarvetta lähettämän. Näitä anovat Rooma laiset Juudalaisilta, ja Juudalaisten tulee nämät kappaleet uskollisesti pitää ilman petosta ja vilppiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 27, 'Sitä vastaan, jos Juudalaisille sota tarjona on, niin pitää Roomalaisten uskollisesti heitä auttaman, senjälkeen kuin tarve vaatii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 28, 'Ja ei pidä heidän Juudalaisten vihollisille elatusta, aseita, rahaa, laivoja taikka muita tarpeita lähettämän. Tätä lupaavat Roomalaiset Juudalaisille, ja tahtovat senkaltaisen liiton uskollisesti ja ilman petosta pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 29, 'Näin on liitto Roomalaisten ja Juudalaisten välille tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 30, 'Mutta jos tästedes jompi kumpi puoli ajattelee siihen enempää lisätä, taikka jotakin muuttaa, eli siitä vähentää, siihen pitää molemmilla puolilla voima oleman; ja mitä he siihen lisäävät, taikka siitä vähentävät, se pitää kaikki lujana ja vahvana pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 31, 'Jos myös kuningas Demetrius Juudan kansalle väkivaltaa tekee, siitä me olemme kirjoittaneet hänen tykönsä tällä tavalla: miksi sinä vaivaat meidän ystäviämme ja liittoveljiämme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 8, 32, 'Jos he tästälähin kantavat sinun päälles, niin meidän pitää heitä varjeleman, ja tahdomme sinun kimppuus sekä vedellä että maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 1, 'Jonatan tulee sodassa tapetun veljensä Juudaan siaan. Sillä välillä kuin Demetrius ymmärsi, että Nikanor sotajoukkoinensa lyöty ja voitettu oli, lähetti hän jälleen Juudeaan nämät kaksi, Bakkideksen ja Alkimuksen, ja heidän kanssansa parhaan sotaväkensä, jotka sodissa alati oikialla puolella pidettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 2, 'Nämät menivät Galgalaan päin, piirittivät ja voittivat Maslotin Arbelassa ja tappoivat siellä paljon väkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 3, 'Senjälkeen toisena vuotena kuudettakymmentä toista sataa, ensimäisellä kuulla, matkustivat he Jerusalemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 4, 'Ja sieltä Bereaan kahdellakymmenellä tuhannella jalkamiehellä ja kahdellatuhannella hevosmiehellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 5, 'Ja Juudas sioitti itsensä Laisan tykönä kolmellatuhannella miehellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 6, 'Vaan kuin hänen väkensä näki, että vihollisia niin suuri joukko oli, hämmästyivät he ja pakenivat, niin ettei enempi Juudaan tykö jäänyt kuin kahdeksansataa miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 7, 'Kuin Juudas tämän näki, ettei hänen sotaväkensä yhdessä pysynyt, ja viholliset kumminkin täyttivät hänen päällensä, tuli hän surulliseksi; ja kuin hän näki, ettei hänellä tilaa ollut rohkaista väkeänsä, ja saattaa heitä yhteen jälleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 8, 'Sanoi hän tässä ahdistuksessa jääneille: ylös, ja koetelkaamme, jos me vihollisten kimppuun tohdimme, ja heitä lyödä taidamme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 9, 'Mutta ei he tahtoneet, vaan estelivät sen pois, ja sanoivat: ei se ole mahdollinen, että me jotain taidamme tehdä; mutta anna meidän tällä erällä välttää ja palata pois, ja hakea meidän veljemme yhteen, jotka meiltä paenneet ovat; sitte me tahdomme jälleen tulla vihollisten tykö, ja lyödä heitä: nyt on meitä sangen vähä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 10, 'Mutta Juudas sanoi: pois se, että meidän pitää pakeneman; jos meidän aikamme on tullut, niin me tahdomme kunniallisesti kuolla meidän veljeimme tähden, ja ei sallia meidän kunniaamme häpiäksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 11, 'Ja viholliset nousivat ja asettuivat kukin paikkaansa näin: ensimäiset olivat ampujat, ja parhaat sotamiehet seisoivat ensimäisinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 12, 'Hevosmiehet olivat jaetut kahteen joukkoon, yksi joukko kummallekin puolelle. Pääruhtinas Bakkides oli oikialla puolella. Tällä järjestyksellä astuivat he edes suurella huudolla ja vaskitorvien äänellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 13, 'Niin antoi myös Juudas vaskitorviin puhaltaa, ja meni heidän tykönsä, ja tappeli heidän kanssansa huomenesta hamaan ehtoosen asti, niin että maa järisi siitä suuresta metelistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 14, 'Kuin Juudas näki, että Bakkides itse ja suuri joukko oli oikialla puolella, niin hän karkasi itse sen päälle, hän ja ne muut, jotka ei henkeänsä säästäneet, ja peljättivät heidät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 15, 'Ja löivät joukon oikialta puolelta pakoon, ja ajoivat heitä takaa aina Asdodin vuoren tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 16, 'Mutta koska ne, jotka vasemmalla puolella olivat, näkivät sen, että Juudas ajoi heitä takaa, riensivät he myös Juudaan perässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 17, 'Niin täytyi Juudaan kääntyä niitä vastaan, ja varjeli itsensä kauvan; ja siinä tapahtui suuri veren vuodatus, niin että monta tuli haavoitetuksi ja kuoliaaksi lyödyksi molemmilta puolilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 18, 'Ja Juudas myös viimeiseltä tuli lyödyksi; niin pakenivat ne, jotka jääneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 19, 'Jonatan ja Simon ottivat veljensä Juudaan ruumiin, ja hautasivat hänen isänsä hautaan Modin kaupungissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 20, 'Ja Israelin kansa suri Juudaa kauvan aikaa, ja valitti häntä sangen raskaasti, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 21, 'Voi että sankari on kaatunut, joka Israelia varjellut ja vapahtanut on!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 22, 'Tämä on historia Juudaasta; mutta hän on vielä monta muuta miehuullista asiaa tehnyt, jotka ei kaikki paljouden tähden ole kirjoitetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 23, 'Juudaan kuoleman jälkeen tulivat jumalattomat ja luopuneet jälleen voimallisiksi koko Israelin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 24, 'Ja siihen aikaan oli suuri nälkä maalla, niin että kaikki kansa antoi itsensä Bakkideksen alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 25, 'Silloin valitsi Bakkides jumalattomia miehiä, jotka hän teki virkamiehiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 26, 'Ja antoi joka paikassa etsiä Juudaan kumppaneita ja ystäviä, ja eteensä tuoda, että hän olis kostanut heille, ja pilkannut heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 27, 'Ja Israelissa oli senkaltainen suru ja ahdistus, ettei sen vertaa ole ollut jälkeen prophetain ajan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 28, 'Sentähden tulivat Juudaan kumppanit kokoon, ja sanoivat Jonatanille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 29, 'Sinun veljes Juudaan kuoleman jälkeen ei ole meillä yhtään enään hänen kaltaistansa, joka meitä varjelis meidän vihollisiltamme ja Bakkideksen käsistä, jotka meitä vainoovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 30, 'Sentähden valitsemme me sinut hänen siaansa esimieheksi ja pääruhtinaaksi, pitämään tätä sotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 31, 'Ja niin tuli Jonatan heidän esimieheksensä, ja hallitsi veljensä siassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 32, 'Kuin Bakkides tämän ymmärsi, antoi hän etsiä häntä, että hän olis surettanut hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 33, 'Koska Jonatan ja Simon hänen veljensä sen ymmärsivät, pakenivat he ja kaikki ne, jotka heidän kanssansa olivat, Tekoen korpeen, ja sioittivat itsensä Asparin veden tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 34, 'Tämän sai Bakkides tietää, joka nousi ja meni heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 35, 'Ja Jonatan oli lähettänyt päämiehen veljen Johanneksen ystäväinsä Nabatealaisten tykö, rukoilemaan heitä, että he riistansa ja tavaransa kaupunkiinsa ottaisivat ja tallella pitäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 36, 'Mutta Jambrin pojat läksivät ulos Magdabanin kaupungista ja karkasivat Johanneksen päälle, ja ottivat hänen kiinni, ja ottivat häneltä kaikki, mitä hänen myötänsä oli, ja veivät heidät kaupunkiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 37, 'Senjälkeen ilmoitettiin Jonatanille ja Simonille hänen veljellensä, että Jambrin pojat valmistivat suuret häät, ja piti tuoman morsiamen Nadabasta suurella koreudella; sillä se oli päämiehen tytär Kanaanin maalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 38, 'Niin Jonatan ja Simon ajattelivat sitä, että nämät tappaneet olivat heidän veljensä Johanneksen; sen tähden menivät he ylös, ja kätkivät itsensä vuorten onkaloihin ja vartioitsivat Jambrin lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 39, 'Kuin ylkä siitä matkusti ystävinensä, ja paljolla väellä ja tavaralla, huiluilla ja rummuilla ja kalliilla kaunistuksilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 40, 'Karkasi Simon ja Jonatan alas vuorelta, ja löivät heitä ja tappoivat monta, niin että ne, jotka pääsivät, täytyi paeta vuorelle, ja ottivat pois heidän riistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 41, 'Silloin häät murheeksi muuttuivat, ja huilun ilo itkuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 42, 'Näin kostivat he sen murhan, joka heidän veljellensä tehty oli, ja palasivat jälleen ja vaelsivat Jordanin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 43, 'Niin tuli myös Bakkides Jordanin tykö suurella sotajoukolla, sabbatina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 44, 'Ja Jonatan sanoi kansallensa: ylös, ja varustakaat teitänne tappelemaan, sillä ette saa tässä nyt levossa olla niinkuin ennen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 45, 'Sillä viholliset ovat saapuvilla: meidän täytyy varjella meitämme, emme kuitenkaan taida välttää; sillä meillä on viholliset sekä edessämme että perässämme; niin on Jordanin virta yhdellä puolella, toisella ovat suot ja vuoret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 46, 'Sentähden pitää teidän huutaman taivaasen, että te vihollisten käsistä autettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 47, 'Ja he tulivat tappelemaan, ja Jonatan löi Bakkidesta; mutta Bakkides vetäytyi takaperin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 48, 'Silloin hyppäsi Jonatan ja hänen väkensä Jordaniin, ja tulivat virran ylitse; vaan Bakkidek sen väki ei tohtineet antaa itsiänsä virtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 49, 'Ja sinä päivänä kaatui Bakkideksen puolelta tuhannen miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 50, 'Sentähden palasi Bakkides Jerusalemiin, ja rupesi vahvistamaan kaupungeita maassa; hän antoi rakentaa portit ja korkiat muurit Jerihon ympäri, Emmaonin, Bethoronin, Betelin, Tamnatanin, Pharanin ja Toponin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 51, 'Ja pani niihin sotaväkeä vartiaksi, joiden Israelia vaivaaman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 52, 'Niin antoi hän myös vahvistaa Betsuran, Gatsan ja linnan Jerusalemissa, ja pani myös siihen sotaväkeä ja toimitti heille ravinnon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 53, 'Ja otti ylimmäisten lapset pantiksi, ja piti ne kiinni Jerusalemin linnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 54, 'Kolmantena vuotena kuudettakymmentä toista sataa, toisella kuukaudella, käski Alkimus myös maahan jaottaa sisälliset muurit kartanosta, joka kaikkein likin templin edessä oli, jotka pyhät prophetat olivat antaneet rakentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 55, 'Ja kuin tähän työhön ruvettiin, löi Jumala Alkimuksen, niin että tämä aivoitus tuli taas estetyksi; sillä hän halvattiin niin, ettei hän saanut mitään puhua, taikka jotain toimittaa, ja laittaa asioitansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 56, 'Ja niin hän kuoli suuressa kivussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 57, 'Mutta koska Bakkides näki, että Alkimus kuoli, matkusti hän jälleen kuninkaan tykö; niin oli rauha ja lepo maassa kaksi vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 58, 'Mutta ne luopuneet maalla pitivät neuvoa, ja sanoivat: Jonatan ja hänen seuransa istuvat alallansa, heillä on rauha, ja ovat suruttomat, kutsukaamme nyt taas Bakkides: hän taitais kaikki heidät ottaa kiinni yhtenä yönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 59, 'Ja he menivät Bakkideksen tykö, ja sanoivat hänelle neuvonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 60, 'Niin Bakkides nousi ylös suurella väellä, ja lähetti kirjat salaisesti kumppaniensa tykö Juudan maalle, että he Jonatanin ja kaikki ne, jotka hänen kanssansa olivat, piti ottaman kiinni. Mutta tämä neuvo tuli Jonatanille tiettäväksi, sen tähden ei he mitään matkaan saaneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 61, 'Vaan Jonatan otti kiinni liki viisikymmentä ylimmäistä poisluopuneiden ja jumattomien joukosta, ja antoi tappaa heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 62, 'Sitte poikkesivat Jonatan ja Simon väkinensä korpeen yhteen hävitettyyn kaupunkiin Betbeseniin; sen hän rakensi jälleen, ja teki vahvaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 63, 'Kuin nyt Bakkides sen tietää sai, nousi hän kaiken väkensä kanssa, siihen myös ajoi Juudalaiset kanssansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 64, 'Ja meni Betbeseniin, ja oli sen alla kauvan aikaa, ja kävi väkirynnäköllä sen päälle, ja teki ampumus- ja muut sota-aseet sen eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 65, 'Mutta Jonatan antoi kaupungin veljensä Simonin haltuun, ja meni yhdellä joukolla ulos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 66, 'Ja löi Odarenin ja hänen veljensä, ja Phaseronin lapset heidän majoissansa. Vaan että se menestyi hänelle, saapui enempi kansaa hänen tykönsä, niin että hän tuli väkevämmäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 67, 'Silloin tuli myös Simon kaupungista vihollisten leiriin, ja poltti sodan rakennukset, ja löi Bakkideksen pakoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 68, 'Ja Bakkides sai sangen katkeran sydämen, että hänen aivoituksensa ja neuvonsa oli turha,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 69, 'Ja vihastui petollisten Juudalaisten päälle, jotka hänelle sitä neuvoa olivat antaneet, että hän jälleen tuli siihen maakuntaan, ja antoi tappaa heistä monta, ja valmisti itsensä menemään matkaansa jälleen omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 70, 'Kuin Jonatan sen ymmärsi, lähetti hän sanan hänelle, tehdäksensä rauhaa hänen kanssansa, ja rukoili häntä, että hän olis antanut saaliin jälleen ja vangit irralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 71, 'Siihen mielistyi Bakkides mielellänsä, ja teki niinkuin Jonatan anoi, ja vannoi hänelle valan, ettei hän enään tahtonut tehdä hänelle pahaa kaikkena elinaikanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 72, 'Ja antoi hänelle jälleen kalun ja Juudan vangit irrallensa, ja palasi omalle maallensa, ja ei enään tullut Juudan maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 9, 73, 'Niin taas tuli rauha Israeliin, ja Jonatan asui Makmassa, ja hallitsi siinä kansaa, ja suretti ne petolliset poisluopuneet lsraelista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 1, 'Kuudentenakymmenentenä vuotena toista sataa tuli Aleksander, Antiokuksen Epiphaneksen poika, ja voitti Ptolemain kaupungin, ja hallitsi siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 2, 'Mutta kun Demetrius sen tietää sai, kokosi hän suuren sotaväen, ja meni Aleksanderia vastaan, ajamaan häntä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 3, 'Sentähden kirjoitti Demetrius Jonatanille, ja sanoi hänelle, että hän tahtoi pitää rauhan hänen kanssansa ja tehdä hänelle kaikkea hyvää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 4, 'Sillä hän ajatteli: se on parempi, että minä vedän hänen minun tyköni, ennenkuin hän menee Aleksanderin puolelle minua vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 5, 'Että minä tapoin hänen veljensä, ja hänelle ja hänen kansallensa paljon pahaa tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 6, 'Ja Demetrius kirjoitti Jonatanille ja antoi hänelle luvan ottaa ylös ja pitää sotaväkeä, ja tehdä sota-aseita, ja että hän hänen liittoveljensä piti oleman, ja käski, että Jonatanille piti annettaman ne panttivangit jälleen irralle, jotka linnassa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 7, 'Sentähden tuli Jonatan Jerusalemiin, ja antoi lukea tämän kirjan kaiken kansan edessä ja niiden edessä, jotka linnassa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 8, 'Knin he nyt kuulivat, että kuningas hänelle antoi luvan ja vallan ottaa sotaväkeä, ja tehdä sota-aseita, ja että kuningas piti hänen liittoveljenä, pelkäsivät he häntä sangen suuresti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 9, 'Ja antoivat hänelle panttivangit irralle, ja Jonatan antoi ne jälleen heidän vanhimmillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 10, 'Näin rupesi Jonatan asumaan Jerusalemissa, ja rakentamaan ja parantamaan kaupunkia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 11, 'Ja antoi rakentaa muurit ja vahvistaa Zionin vuoren hyvillä vahvoilla muureilla, kaikki hakatuista kivistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 12, 'Näin tuli Jerusalem jälleen vahvaksi raketuksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 13, 'Ja pakanat vähistä kaupungeista, jotka Bakkides oli antanut vahvaksi tehdä, pakenivat pois omalle maallensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 14, 'Mutta pitivät ainoastaan Betsuran, ja ne luopuneet juoksivat sinne; sillä se oli heidän asuinsiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 15, 'Koska Aleksander ymmärsi, että Demetrius pyysi ystävyyttä pitää Jonatanin kanssa, ja kuuli ne kiitettävät työt, jotka Jonatan ja hänen veljensä tehneet olivat, sanoi hän:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 16, 'Senkaltaista jaloa miestä emme taida löytää; sen tähden tahdomme me kirjoittaa hänen tykönsä, että hän meidän ystävämme ja liittoveljemme oleman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 17, 'Ja kirjoitti näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 18, 'Kuningas Aleksander toivottaa veljellensä Jonatanille terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 19, 'Me kuulemme sinua ylistettävän voimalliseksi mieheksi ja mahdolliseksi meidän ystävyyteemme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 20, 'Sentähden asetamme me sinun kansas ylimmäiseksi papiksi, ja sinä pitää kutsuttaman kuninkaan ystäväksi, ja nyt lähetämme me sinulle purpuravaatteen ja kultaisen kruunun, sentähden pidä uskollisesti meidän kanssamme ja ole meidän ystävämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 21, 'Ja niin puki Jonatan päällensä papin vaatteet, kuudentenakymmenentenä vuotena toista sataa, seitsemännellä kuukaudella, lehtimajan juhlapäivänä, ja kokosi sotajoukon ja antoi tehdä paljon sota-aseita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 22, 'Mutta kun Demetrius tämän ymmärsi, tuli hän sangen surulliseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 23, 'Että Aleksander häneltä Juudalaiset väänsi pois tykönsä ja sen kautta tuli voimallisemmaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 24, 'Ja ajatteli hän myös ystävällisesti kirjoittaa heidän tykönsä, ja kunniaa ja tavaraa luvata, että heidän piti hänelle apua lupaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 25, 'Ja kirjoitti näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 26, 'Kuningas Demetrius toivottaa Juudalaisille terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 27, 'Me olemme mielellämme kuulleet Ja siitä iloinneet, ettette meistä luovu meidän vihollistemme puolelle, vaan kaikella uskollisuudella meidän kanssamme pidätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 28, 'Sentähden rukoilemme me, että te vielä nyt niin tästedes tahtoisitte meille uskolliset olla, Ja ei antaa vääntää teitänne pois meidän puoleltamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 29, 'Tämän teidän uskollisuutenne me tahdomme maksaa, ja keventää teiltä monet taakat ja antaa enempi vapautta, ja armoa tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 30, 'Ja nyt minä annan kaikille Juudalaisille veron vapaaksi, suolatullin, kruunun teon, kolmannen mitan jyvistä ja puolen kaikkinaisesta puiden hedelmästä, joka minulle tulis; tämän kuorman alta pitää tästedes Juudan maa ja ne kolme kihlakuntaa, jotka siihen lisätyt ovat Samariasta ja Galileasta, aina vapaat oleman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 31, 'Ja Jerusalem pitää pyhä ja vapaa oleman kaikesta rasituksesta, verosta ja kymmenyksistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 32, 'Minä tahdon myös Jerusalemin linnan teille jälleen avata ja ylimmäisen papin haltuun antaa, että hänen pitää sen saaman ja pitää paneman väkeä sinne, jotka hän tahtoo sitä varjelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 33, 'Ja kaikki ne Juudalaiset, jotka minun valtakunnassani vankina ovat, pitää vallallensa annettaman, ja vapaat oleman, ja he ja heidän karjansa pitää verosta vapaat oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 34, 'Ja pitää heille vapaus oleman, kaikessa minun valtakunnassani pitää heidän sabbatinsa, uudet kuunsa ja muut määrätyt pyhäpäivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 35, 'Ja kolme päivää sekä edellä että jälkeen juhlapäivän, joka mieheltä estämättä oleman heidän jumalan palveluksessansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 36, 'Ja pitää kolmekymmentä tuhatta miestä Juudeassa valittaman, niin minä tahdon palkan antaa, niinkuin muillekin minun sotaväelleni, ja ne pitää kuninkaan vahvoihin kaupunkeihin asetettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 37, 'Ja niistä pitää muutamat valittaman, jotka kuninkaalle hänen korkeimmissa asioissansa niinkuin hänen hyvin uskotut neuvonantajansa oleman pitää. Ei pidä myös Juudalaisilla yhtään muukalaista, vaan omasta kansasta vapaat päämiehet oleman, että he lakinsa pitäisivät, niinkuin Juudankin maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 38, 'Ja ne kolme kihlakuntaa Samarian maassa ja Galileassa, jotka Juudean omat ovat, ei pidä yhdenkään alle annetut oleman, vaan ainoastaan ylimmäisen papin, että se tiettävä olis, että hän yksinänsä sen herra on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 39, 'Ptolomain kaupungin ja ne maakunnat ympärillä, jotka siihen tulevat, annan minä Jerusalemin templin, siihen kulutukseen kuin uhriin tarvitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 40, 'Ja tahdon myös toimittaa templin rakennukseen joka vuosi viisitoistakymmentä tuhatta sikliä hopiaa minun omastani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 41, 'Ja mitä minä vanhasta minun virkani puolesta olen velkapää ollut antamaan templiin, se pitää tästedes myös annettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 42, 'Ja ne viisituhatta sikliä hopiaa, jotka minun virkamieheni templin ylöskannosta ovat ottaneet pois, ne pitää taas vuosi vuodelta pappein omat oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 43, 'Ja pitää templillä tämä vapaus oleman, että kaikessa minun valtakunnassani joka jonkun rangaistuksen ansainnut on, ja pakenee templiin, hänen pitää siellä murheetoin oleman henkensä ja tavaransa puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 44, 'Templin rakennukseen, ja muurien ja tornien parannukseen Jerusalemissa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 45, 'Ja muualla maassa tahtoo kuningas myös omasta otostansa kulutuksen antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 46, 'Mutta kuin tämä kirja luettiin Jonatanin ja kansan edessä, ei he tahtoneet uskoa häntä, eikä siitä tietävinänsä olleet, sillä he tiesivät hyvin, minkä kaltaisen petoksen ja hirmuisen hirmuval-taisuuden hän ennen Israelia vastaan tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 47, 'Ja päättivät tehdäksensä apua Aleksanderille, Joka ennen jo ystävyyttä heiltä anoi, ja rauhan luvannut oli; häntä he auttivat joka aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 48, 'Kuin nyt Aleksander ja Demetrius toinen toistansa vastaan menivät tappelemaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 49, 'Niin pakeni Demetriuksen sotaväki, ja Aleksander kiiruhti heidän jälkeensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 50, 'Ja teki hirmuisen verenvuodatuksen huomenesta hamaan ehtoosen asti, ja Demetrius tuli lyödyksi sinä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 51, 'Senjälkeen lähetti Aleksander sanan Egyptin kuninkaan Ptolomeuksen tykö, tämän asian kanssa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 52, 'Että minä olen tullut minun valtakuntaani jälleen, ja istun kuninkaallisella istuimella, ja olen saanut hallituksen ja olen karkottanut Demetriuksen, ja perintömaani voittanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 53, 'Niin minä pyydän sinulta ystävyyttä, ja rukoilen sinua, että sinä tahtoisit antaa tyttäres minulle avioksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 54, 'Niin minä tahdon olla sinua kohtaan niinkuin vävyn tulee, ja kiitollinen olla, ja antaa hänelle kuninkaallisen huomenlahjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 55, 'Siihen vastasi Ptolomeus, ja toivotti Aleksanderille onnea, että hän isänsä maalle jälleen tullut ja valtakuntansa voittanut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 56, 'Ja lupasi hänelle niin tehdä kuin hän kirjoittanut oli, ja käski hänen tulla tykönsä Ptolomaidiin; siellä he tahtoivat keskenänsä toinen toistansa puhutella ja sen naimisen päättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 57, 'Toisena vuonna seitsemättäkymmentä toista sataa vaelsi Ptolomeus tyttärensä Kleopatran kanssa Egyptistä ja tuli Ptolomaidiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 58, 'Sinne tuli myös kuningas Aleksander, ja Kleopatra annettiin Aleksanderille, ja häät pidettiin suurella kuninkaallisella koreudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 59, 'Ja kuningas Aleksander kirjoitti Jonatanille ja kutsui hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 60, 'Niin tuli Jonatan suurella kunnialla Ptolomaidiin molempain kuningasten tykö ja lahjoitti heille ja heidän ystävillensä kalliita lahjoja kullasta ja hopiasta, ja sai ystävyyden heiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 61, 'Ja muutamat luopuneet Israelista tulivat sinne kantamaan Jonatanin päälle; vaan ei kuningas tahtonut kuulla heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 62, 'Mutta käski Jonatanin panna pois vaatteensa ja pukea purpuravaatteet yllensä, joka myös niin tapahtui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 63, 'Silloin istutti kuningas hänen sivuunsa, ja antoi käskyn ylimmäisillensä, että he hänen kanssansa ympäri kaupunkia käymän piti ja kuuluttaman, ettei kenenkään pitänyt kantaman hänen päällensä, taikka muutoin häntä vaivaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 64, 'Mutta koska hänen päällekantajansa näkivät, että kuningas häntä niin korkiasti kunnioitti, sekä purpuralla että tällä kuulutuksella, niin pakenivat he kaikki matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 65, 'Ja kuningas teki hänelle suuren kunnian, ja antoi kirjoittaa hänen ylimmäisten ystäviensä sekaan, ja teki hänen päämieheksi ja lähimmäiseksi neuvonantajaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 66, 'Sitte vaelsi Jonatan jälleen Jerusalemiin ilolla ja hyvässä rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 67, 'Viidennellä vuodella seitsemättäkymmentä toista sataa tuli kuningas Demetrius, entisen Demetriuksen poika Kretasta perintövaltaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 68, 'Silloin Aleksander peräti suuresti hämmästyi, ja tuli Antiokiaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 69, 'Mutta Demetrius saatti Apolloniuksen, joka olI päämies alimmaisessa Syriassa, puolellensa; hän kokosi sotajoukon, ja tuli Jamniaan, ja lähetti Jonatanin ylimmäisen papin tykö, ja antoi sanoa hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 70, 'Ei yksikään tee meille vastusta, vaan sinä ainoa, ja saatat sen, että minä katsotaan ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 71, 'Sinä olet röyhkeä vuorilla; mutta jos sinä tahdot urhoollisen työn tehdä, niin tule alas lakialle kedolle, siinä koetelkaamme toinen toistamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 72, 'Jos sinä tahdot kysyä, kuinka vahvat me olemme, minä ja ne muut, jotka minua seuraavat ja minua auttavat, niin pitää sinulle sanottaman: ette taida seisovaiset olla tämän kansan edessä, joilta teidän isänne kahdesti lyödyt ovat omassa maassansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 73, 'Paljoa vähemmin taidat sinä lakialla kedolla senkaltaisen väkevän kansan edessä sekä hevosmiehistä että jalkamiehistä seisovainen olla, siinä paikassa, jossa ei yhtään vuorta eikä vahaa ole, joiden varjoon joku paeta taitais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 74, 'Kuin Jonatan senkaltaisen kerskauksen kuuli, vihastui hän, ja valitsi kymmenentuhatta miestä, ja läksi Jerusalemista, tuli myös hänen tykönsä Simon, hänen veljensä, auttamaan häntä, ja sioittivat itsensä Jopen eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 75, 'Mutta Jopen kaupungin asuvaiset ei päästäneet heitä sisälle, sillä Apollonius oli pannut siihen väkeä varjelukseksi; sentähden Jonatan karkasi heidän päällensä väkirynnäköllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 76, 'Ja kaupunkilaiset peljästyivät ja avasivat portit. Näin sai Jonatan Jopen kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 77, 'Kuin Apollonius tämän kuuli, asetti hän itsensä Jopen eteen kolmellatuhannella hevosmiehellä ja paljolla jalkaväellä, ja teeskeli itsensä niinkuin hän olis tahtonut vaeltaa Asdodiin, että hän olis houkutellut Jonatanin ulos väljälle; sillä hänellä oli suuri joukko hevosväkeä, joihin hän uskalsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 78, 'Jonatan riensi hänen perässänsä Asdodiin, ja vaelsi kukin joukko järjestyksessänsä, valmiina tappelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 79, 'Mutta Apollonius oli salaisesti jättänyt leiriin tuhannen ratsasmiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 80, 'Niin ymmärsi Jonatan, että väki oli salattuna hänen takanansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 81, 'Sentähden kuin ne hänen väkeänsä lähenivät, pidätti Jonatan joukkonsa niinkuin hän oli heidät sioittanut. Silloin ampuivat ratsasmiehet väen päälle koko sen päivän, huomenesta niin ehtoosen, siihen asti että heidän hevosensa väsyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 82, 'Sitte otti Simon väkensä ja löi vihollisia, niin ratsasmiehet pakenivat; sillä he olivat väsyneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 83, 'Ja tulivat sinne ja tänne väljällä hajoitetuksi, ja pakenivat Asdodiin, ja riensivät epäjumalan Dagonin templiin., että he siellä olisivat pelastaneet henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 84, 'Mutta Jonatan hävitti Asdodin kaupungin ja ne kylät ympäriltä, ja poltti ne. Hän poltti myös epäjumalan templin kaikkein niiden kanssa, jotka sinne paenneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 85, 'Ja niiden luku, jotka lyödyt ja poltetut olivat, oli yhteen liki kahdeksantuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 86, 'Senjälkeen vaelsi Jonatan sotaväellä Askalonin tykö ja kauppamiehet läksivät kaupungista häntä vastaan, ja antoivat itsensä, ja ottivat hänet vastaan suurella kunnialla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 87, 'Näin palasi taas Jonatan Jerusalemlin sotaväkensä ja saaliinsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 88, 'Ja kuin Aleksander nämät kuuli, kunnioitti hän Jonatania vielä suuremmasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 10, 89, 'Ja lähetti. hänelle kultaisen vyön, niinkuin tapa on antaa ainoastaan kuningasten langoIle. Siihen myös antoi hän hänelle lahjaksi ja omaksi Akkaronin ja mitä sen alla oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 1, 'Ja Egyptin kuningas kokosi väkeä, niin paljon kuin santaa on meren pohjassa, ja paljon haaksia, ja meni Aleksanderin valtakuntaa petoksella saamaan allensa, ja molempia valtakuntia hallitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 2, 'Sentähden meni hän Syriaan, ja oli hyvä ystävä olevinansa. Niin avattiin hänen eteensä kaikkein kaupunkein portit, ja käytiin häntä vastaan, ja otettiin kunniallisesti vastaan, niinkuin Aleksander oli käskenyt, että hän oli hänen appensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 3, 'Mutta kuhunka kaupunkiin Ptolomeus tuli, siihen myös jätti sotajoukon vartiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 4, 'Ja kuin hän Asdodiin tuli, osoittivat he hänelle, kuinka Jonatan Dagonin templin ja kaupungin polttanut ja maahan lyönyt oli, ja kuinka kuolleiden ruumiit siellä ja täällä hajoitettuna makasivat, ja teiden vieriin, suuriin joukkoihin haudatut olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 5, 'Ja sanoivat kuninkaalle, että Jonatan sen vahingon oli tehnyt, saattaaksensa häntä kuninkaan vihoihin. Mutta ei kuningas siihen mitään vastannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 6, 'Ja Jonatan meni myös kuningasta vastaan Joppeen; siellä he puhuttelivat toinen toistansa, ja olivat yhdessä sen yön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 7, 'Ja Jonatan seurasi kuningasta hamaan Eleuteruksen virtaan asti, sitten meni hän jälleen Jerusalemiin kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 8, 'Ja kuningas Ptolomeus sai kaupungit hamaan Seleukiaan asti, lähes merta, ja ajatteli ajaa Aleksanderia pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 9, 'Ja lähetti sanan Demetriukselle, että hän tulis hänen tykönsä tekemään liittoa hänen kanssansa ja lupasi hänelle tyttärensä, joka Aleksanderilla oli, lupasi myös auttaa häntä kuninkaaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 10, 'Ja sanoi katuvansa sitä, että hän Aleksanderille tyttärensä oli antanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 11, 'Ja sanoi Aleksanderin syyn, hänen seisoneen hänen henkensä ja valtakuntansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 12, 'Ja osoitti vihansa julkisesti, ja eroitti itsensä Aleksanderin ystävyydestä, ja otti häneltä tyttärensä pois, ja antoi Demetriukselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 13, 'Ja kuin Ptolomeus tuli Antiokiaan, pani hän molemmat kruunut päähänsä sekä Egyptin että Asian kruunun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 14, 'Mutta kuningas Aleksander oli siihen aikaan Kilikiassa; sillä muutamat kaupungit olivat siellä hänestä erinneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 15, 'Kuin hän sai kuulla Ptolomeuksesta, meni hän häntä vastaan sotimaan hänen kanssansa; mutta Ptolomeus oli paremmin varustettu, ja meni häntä vastaan ja ajoi hänen pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 16, 'Ja Aleksander pakeni Arabiaan, että hän siellä olis saanut rauhassa olla, mutta kuningas Ptolomeus oli sangen voimallinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 17, 'Sentähden antoi Zabdiel Arabiasta vieraansa Aleksanderin pään hakata pois, ja lähetti sen kuningas Ptolomeukselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 18, 'Ptolomeus kuoli kolmantena päivänä sen jälkeen; silloin myös ne sotamiehet, jotka Ptolomeus oli asettanut kaupunkeihin, tapettiin niiltä, jotka kaupungeissa asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 19, 'Näin sai Demetrius valtakunnan, seitsemäntenä vuotena seitsemättäkymmentä toista sataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 20, 'Siihen aikaan kokosi Jonatan väkensä Juudean maalla, omistaaksensa Jerusalemin linnaa jälleen, ja antoi sen eteen panna rakennukset ja sota-aseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 21, 'Niin muutamat luopuneista menivät kuningas Demetriuksen tykö, ja kantoivat Jonatanin päälle, ja sanoivat, että hän oli linnan piirittänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 22, 'Silloin vihastui kuningas suuresti ja meni kiiruusti Ptolomaidiin, ja kirjoitti Jonatanille, ettei hän linnaa olisi ahdistanut, mutta kohta tullut hänen tykönsä Ptolomaidiin; siellä hän tahtoi häntä muutamista asioista puhutella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 23, 'Mutta kuin tämä sana tuli Jonatanille, antoi hän linnan olla piiritettynä, ja valitsi muutamia vanhimmista Israelissa ja papeista, jotka häntä seuraaman piti, ja nousi ja antoi itsensä hengenvaaraan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 24, 'Ja otti monta kallista kappaletta myötänsä, kullasta, hopiasta ja vaatteista, ja meni Ptolomaidiin kuninkaan tykö, ja löysi armon ja ystävyyden hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 25, 'Kuin siis ne, jotka hänen kansastansa luopuneet olivat, kantelivat hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 26, 'Piti kuningas hänen kunniassa, niinkuin hän myös ennenkin pidetty oli, ja teki hänelle suuren kunnian kaikkein päämiestensä edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 27, 'Ja vahvisti hänen ylimmäisen papin virkaan ja kaikkinaiseen muuhun kunniaan, joka hänellä siihen päivään asti oli ollut, ja piti hänen ylimmäisenä ystävänänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 28, 'Jonatan rukoili myös kuningasta, että hän kaiken Juudean ja ne kolme kihlakuntaa Samariassa ja Galileassa olis antanut verotoinna olla, ja lupasi hänelle sen vapauden edestä kolmesataa leiviskää kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 29, 'Se kelpasi kuninkaalle, ja antoi Jonatanille kirjan näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 30, 'Kuningas Demetrius toivottaa veljellensä Jonatanille ja Juudan kansalle terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 31, 'Me lähetämme teille kopion, kirjasta, jonka me isällemme Lastenekselle teidän tähtenne kirjoittaneet olemme, että teidän sen tietämän pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 32, 'Kuningas Demetrius toivottaa isällensä Laskenekselle terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 33, 'Me olemme ajatelleet ystävillemme ja uskollisille liittoveljillemme Juudalaisille tehdä hyvää, heidän uskollisen ystävyytensä tähden meitä kohtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 34, 'Sentähden me asetamme, että papit Jerusalemissa kaiken Juudean ja ne kolme kaupunkia, Aphereman, Lyddan ja Raman, jotka Samariasta ovat Juudean tykö pantu, rajoinensa pitää omistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 35, 'Me teemme heidät myös vapaaksi kaikesta siitä, minkä heidän ennen piti kuninkaalle joka vuosi antaman: jyvistä, hedelmistä, kymmenyksistä, veroista, suolatullista ja muista kruunun teoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 36, 'Näistä kaikista pitää heidän tästedes vapaat oleman; ja senkaltainen vapaus pitää heille vahvana ja lujana pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 37, 'Tämän kaltainen kirja pitää annettaman Jonatanille, jonka hänen pitää paneman pyhälle vuorelle kunnialliseen ja julkiseen siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 38, 'Koska kuningas Demetrius näki, että kaikessa valtakunnassa rauha oli, ja ettei yksikään enää asettanut itsiänsä häntä vastaan, päästi hän kaiken oman maan sotaväen menemään kunkin majoillensa. Mutta muukalaisen sotaväen, jonka hän pakanoilta luodoista ottanut oli, piti hän tykönänsä, jonka tähden myös oman maakunnan sotaväki häntä suuresti vihasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 39, 'Mutta kuin Tryphon, yksi päämiehistä, joka muinen Aleksanderin ystävä oli ollut, näki, että sotaväki kuningas Demetriusta vihasi, meni hän Emalkuelin Arabialaisen tykö, joka nuoren Antiokuksen, Aleksanderin pojan, kasvattanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 40, 'Sitä hän neuvoi antamaan nuorukaista hänen haltuunsa, ja lupasi asettaa hänen isänsä valtakuntaan jälleen. Ja jutteli Arabialaiselle, kuinka ja minkätähden sotaväki rupesi vihaamaan kuningas Demetriusta, ja niin viipyi hän Arabialaisen tykönä kauvan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 41, 'Silloin Jonatan kirjoitti Demetriukselle, ja rukoili häntä käskemään niitä, jotka linnassa olivat, menemään pois ja linnaa hänelle antamaan; sillä he tekivät Israelille paljon pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 42, 'Silloin kirjoitti Demetrius Jonatanille näin: en ainoasti tätä, jota sinä anot, mutta paljoa suuremman kunnian ja hyvyyden minä tahdon sinulle ja sinun kansalles tehdä, niin pian kuin minä taidan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 43, 'Mutta nyt minä olen suuressa vaarassa: sentähden tee niin hyvin minua kohtaan ja lähetä minulle apua: sillä kaikki minun sotaväkeni on minun hyljännyt ja asettanut itsensä minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 44, 'Sen tähden lähetti Jonatan hänelle kolmetuhatta jaloa sotamiestä. Ne tulivat Antiokiaan kuninkaan tykö, ja kuningas ihastui heidän tulemisestansa sangen suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 45, 'Niin kansa nosti kaupungissa kapinan, joita oli sata ja kaksikymmentä tuhatta miestä, ja tahtoivat tappaa kuninkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 46, 'Mutta kuningas pakeni linnaansa. Silloin sotaväki omisti kaupungin kujat ja tahtoi väkisellä linnaa saada.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 47, 'Sen tähden kutsui kuningas Juudalaiset häntä varjelemaan. Niin juoksivat kaikki Juudalaiset kuninkaan avuksi, ja jakoivat itsensä kaupungin kujille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 48, 'Ja löivät sinä päivänä satatuhatta miestä, ja sytyttivät tulen kaupungissa, ja ottivat heidän tavaransa. Näin he auttivat kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 49, 'Kuin kaupungin kansa näki, että Juudalaiset kaupungin saivat haltuunsa, myöntyivät he, ja huusivat kuninkaalle, ja rukoilivat rauhaa, että Juudalaiset olisivat asetetut, ettei he myös enää väkeä tappaneet olisi, ja kaupunkia peräti hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 50, 'Niin tehtiin rauha, ja Juudalaiset heittivät aseensa pois, ja suuresti kunnioitettiin kuninkaalta, ja saivat korkian nimen koko valtakunnassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 51, 'Ja menivät jälleen kotiansa Jerusalemiin, ja veivät myötänsä paljon hyvyyttä, jonka he olivat sodassa voittaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 52, 'Koska siis Demetrius taas surutoin oli, ja rauha oli kaikissa paikoissa hänen valtakunnassansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 53, 'Ei hän ensinkään pitänyt sitä, mitä hän Jonatanille luvannut oli, mutta peräti eroitti itsensä hänestä, ja oli hänelle kiittämätöin hänen hyväin tekoinsa edestä, ja osoitti hänelle petollisuutensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 54, 'Vähää jälkeen tuli Tryphon jälleen nuoren Antiokuksen kanssa. Tämä Antiokus tuli kuninkaaksi, ja pantiin kruunu hänen päähänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 55, 'Ja hänen tykönsä tuli kaikki se sotaväki, jolle kuningas oli luvan antanut. Kuin he sotivat Demetriuksen kanssa, löivät he hänet pakoon, ja ajoivat häntä takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 56, 'Ja Tryphon otti elephantit ja voitti Antiokian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 57, 'Ja nuori Antiokus kirjoitti Jonatanille, ja vahvisti hänen ylimmäisen papin virkaan ja myöten antoi, että hänen ne neljä kaupunkia piti omistaman ja pitämän, ja oleman kuninkaan ystävänä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 58, 'Ja lähetti hänelle kultaisia astioita, ja antoi luvan hänelle pitää kultaa pöydällänsä ja purpuraa ja kultaisen vyön kantaa suolillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 59, 'Ja Simonin, Jonatanin veljen, teki hän sen maakunnan päämieheksi Tyrosta niin hamaan Egyptiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 60, 'Ja Jonatan läksi ulos ja meni, virran ylitse, ja tuli niihin kaupunkeihin, jotka olivat ympäristöllä. Ja hänen tykönsä meni kaikki sotaväki Syriasta, auttamaan häntä. Ja kuin hän tuli Askalonin alle, kävivät kaupungin asukkaat hänen tykönsä, ja ottivat hänen kunniallisesti vastaan, ja antautuivat hänen allensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 61, 'Senjälkeen meni hän Gatsan eteen; mutta ne, jotka Gatsassa olivat, ei tahtoneet häntä päästää sisälle; sentähden piiritti hän kaupungin, ja poltti läheiset esikaupungit ja otti saaliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 62, 'Niin rukoilivat Gatsan asuvaiset rauhaa, ja Jonatan teki rauhan heidän kanssansa, ja otti muutamia heidän lapsiansa panttivangiksi, ja lähetti Jerusalemiin; mutta hän meni lävitse maakunnan Damaskuun asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 63, 'Mutta kuin hän kuuli, että kuningas Demetriuksen päämiehet olivat suurella sotajoukolla tulleet Kedekseen, joka on Galileassa, omistamaan sitä maakuntaa, jonka kuningas oli hänelle antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 64, 'Meni hän heitä vastaan, ja jätti veljensä Simonin siaansa siihen maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 65, 'Ja Simon meni Betsuraan, Ja sitä niin kovin ahdisti kauvan aikaa, ettei siitä yksikään tohtinut tulla ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 66, 'Sentähden ne rukoilivat rauhaa, ja hän teki heidän kanssansa rauhan, ja antoi heidän pelkäämättä käydä ulos, ja omisti kaupungin, ja pani siihen sotaväkeä sitä varjelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 67, 'Mutta Jonatan meni sotaväkensä Genesaretin meren tykö, ja oli huomeneltain varhain ylhäällä, ja he tulivat Batsarin kedolle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 68, 'Niin menivät pakanat häntä vastaan lakialle, ja heitä oli salainen joukko vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 69, 'Kuin Jonatan löi sitä toista joukkoa, niin tuli salainen joukko vuorelta hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 70, 'Niin pakeni kaikki Jonatanin sotaväki, niin ettei muita jäänyt hänen tykönsä kuin ainoasti sodan päämiehet, Matatias Absalomin poika ja Juudas Kalphin poika:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 71, 'Silloin repäisi Jonatan vaatteensa, ja pani multaa päänsä päälle, rukoili,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 72, 'Ja meni jälleen vihollisten tykö, ja löi heidät pakoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 73, 'Koska hänen väkensä, jotka ennen olivat paenneet, sen näkivät, kääntyivät he auttamaan Jonatania jälleen, ja ajoivat vihollisiansa takaa hamaan Kedeksen leiriin asti, ja he myös sioittivat itsensä siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 11, 74, 'Ja siinä tuli sinä päivänä tapetuksi liki kolmetuhatta pakanaa. Senjälkeen meni Jonatan Jerusalemiin jälleen');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 1, 'Mutta koska Jonatan näki hänellänsä tilan olevan, valitsi hän muutamia, jotka hän Roomiin lähetti uudistamaan ja vahvistamaan liittoa jälleen Roomalaisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 2, 'Hän kirjoitti myös Spartan, asuvaisten tykö ja muihin maan paikkoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 3, 'Kuin lähetetyt miehet tulivat Roomiin, menivät he kaupungin hallituksen eteen, ja sanoivat: Jonatan, ylimmäinen pappi, ja Juudan kansa ovat meitä tänne lähettäneet, uudistamaan jälleen sitä liittoa, joka meidän välillämme muinen tehtiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 4, 'Ja Roomalaiset antoivat heille tiekirjan, että heidän piti saaman rauhassa kotiansa palata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 5, 'Ja Jonatan kirjoitti Spartan asuvaisten tykö näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 6, 'Jonatan, ylimmäinen pappi, kansan vanhimmat ja muut papit, ja Juudan kansa, toivottavat veljillensä, jotka Spartassa ovat, terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 7, 'Ennen muutamia ajastaikoja kirjoitti teidän kuninkaanne Areus meidän ylimmäisen papin Onian tykö, että te olette meidän veljemme, niinkuin se kirja sen todeksi osoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 8, 'Ja Onia otti teidän lähetetyt miehet kunniallisesti vastaan, ja otti teidän ystävyytenne ja liittonne vastaan, niinkuin kirjassa oli kirjoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 9, 'Ja vaikka emme tällä erällä muukalaisten apua tarvitse, sillä me turvaamme meidän Jumalamme sanaan, jota me joka päivä luemme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 10, 'Niin kuitenkin me lähetämme teille sanan, että te uudistaisitte ja vahvistaisitte veljellisen ja ystävällisen liiton meidän välillemme, ettemme sitä unhottaisi; sillä sitte on suuri aika kuin te meidän tykömme lähetitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 11, 'Se te myös tietäkäät, että me aina juhlapäivinä ja muina päivinä, kuin uhrataan, rukouksissamme ja uhreissamme teitä ajattelemme, niinkuin myös veljiä tuleekin ajatella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 12, 'Ja teidän kunnianne ja terveytenne on meidän ilomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 13, 'Mutta sillä välillä on meillä suuri vaiva ollut, ja suuri sota kuningasten kanssa tässä ympäristöllä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 14, 'Mutta emme ole tahtoneet teitä, ja muita meidän ystäviämme ja liittoveljiämme vaivata niissä sodissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 15, 'Sillä meillä on apu ollut taivaasta, ja Jumala on meitä varjellut ja maahan lyönyt meidän vihollisemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 16, 'Mutta että me nyt lähetämme nämät meidän asianajajat, Numeniuksen, Antiokuksen pojan ja Antipatrin Jasonin pojan, Roomalaisten tykö, uudistamaan ystävyyttä ja liittoa heidän kanssansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 17, 'Niin me olemme myös siinä heille käskyn antaneet, että heidän pitäis myös tuleman teidän tykönne, ja tervehtimän teitä meidän puolestamme, ja antaman teille tämän lähetyskirjan, uudistettaa meidän veljellistä liittoamme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 18, 'Ja rukoilemme tähän vastausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 19, 'Mutta tämä on kopio siitä lähetyskirjasta, jonka Areus, Spartan kuningas, muinen meidän tykömme lähetti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 20, 'Areus, Spartan kuningas, toivottaa Onialle, ylimmäiselle papille, terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 21, 'Me löydämme vanhoista kirjoista, että Spartan asuvaiset ja Juudalaiset ovat keskenänsä olleet veljekset, (sillä molemmat kansat ovat Abrahamista tulleet).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 22, 'Että me nyt sen tiedämme, rukoilemme me teitä, että te kirjoittaisitte meidän tykömme, kuinka teidän käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 23, 'Ja jos teille niin kelpaa, niin pitää meidän karjamme, hyvyytemme ja tavaramme ja mitä meillä on, oleman niinkuin se olis teidän omanne; ja mitä teillä on, pitää oleman niinkuin se meidän omamme olis. Tämän me olemme käskeneet teille tiettäväksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 24, 'Sitten kuuli Jonatan, että Demetriuksen sodanpäämiehet jälleen tulivat paljon suuremmalla voimalla kuin ennen, ja tahtoivat tulla häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 25, 'Sentähden meni hän ulos Jerusalemista heitä vastaan Hematin maalle; sillä ei hän tahtonut odottaa niinkauvan että he olisivat kerinneet hänen maakuntaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 26, 'Kuin hän vakoojat lähetti vihollisten leiriin, tulivat ne jälleen ja sanoivat, että viholliset olivat aikoneet sinä yönä karata heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 27, 'Sen tähden antoi Jonatan käskyn sotaväelle ehtoona, että heidän piti valvoman, ja kaiken sen yön oleman haarniskoissa ja valmistettuna; ja asetti väkeä ympäri leiriä vartiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 28, 'Mutta koska viholliset näkivät, että Jonatan oli hänensä valmistanut sotimaan, tuli heille pelko, niin että he nousivat ja menivät matkaansa; ja ettei kenkään sitä olisi ymmärtänyt, antoivat he valkian tehdä usiaan paikkaan leiriinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 29, 'Sentähden Jonatan ei luullut heidän menevän pois huomeniseen asti; sillä hän näki tulen olevan usiassa paikassa heidän leirissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 30, 'Mutta huomeneltain ajoi hän heitä takaa, vaan ei hän käsittänyt heitä; sillä he ennättivät päästä ylitse Eleuterin virran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 31, 'Silloin palasi Jonatan Arabialaisten tykö, jotka kutsutaan Zabilaisiksi, löi heidät ja otti heidän saaliinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 32, 'Niin hän myös palasi sieltä, ja meni Damaskuun, ja hävitti maakunnat kaikissa paikoissa sen ympäriltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 33, 'Mutta Simon meni Askaloniin ja muihin vahvoihin kaupunkeihin, jotka läsnä olivat. Sitte käänsi hän itsensä Joppeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 34, 'Sillä hän ymmärsi, että ne tahtoivat itsensä antaa Demetriuksen päämiesten haltuun. Sentähden tuli hän ennakolta ja omisti Jopen kaupungin, ja asetti sotaväkeä siihen varjelemaan kaupunkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 35, 'Senjälkeen tuli Jonatan kotia jälleen, ja piti neuvoa kansan vanhimpain kanssa, että muutamia kaupungeita Juudeassa piti vahvistettaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 36, 'Ja Jerusalemin muurit korotettaman, ja yksi korkia muuri linnan ja kaupungin välillä rakettaman, että kaupunki linnasta olis tullut eroitetuksi, niin ettei ne, jotka linnassa asuivat, olisi saaneet tulla niiden päälle, jotka kaupungeissa asuivat, ja ettei kenkään olisi saanut heidän tykönsä viedä, eikä heille mitään myydä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 37, 'Kuin väki tuli yhteen, niin he rupesivat rakentamaan; ja että se muuri, joka oli idän puolella ojan ylitse, oli maahan langennut, rakensivat he sen kappaleen ylös jälleen, joka kutsutaan Kaphnata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 38, 'Ja Simon rakensi sen linnan, joka kutsutaan Adida Sephelas, ja teki sen vahvaksi, ja varusti sen vahvalla portilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 39, 'Niin aikoi Tryphon Asian valtakuntaa ottaa allensa, ja panna kruunun päähänsä ja tappaa kuninkaan, nuoren Antiokuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 40, 'Mutta että hän pelkäsi, että Jonatanin piti sen estämän ja häntä vastaan nouseman, etsi hän myös tilaa, kuinka hän olis saanut ottaa Jonatanin kiinni ja surmata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 41, 'Sentähden meni hän Betsaan; sinne tuli myös Jonatan neljälläkymmennellä tuhannella hyvin varustetulla miehellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 42, 'Mutta kuin Tryphon näki, että Jonatanilla niin suuri väki oli, pelkäsi hän ja ei tohtinut julkisesti olla häntä vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 43, 'Mutta otti hänen vastaan kunnialla, ja käski myös ystävänsä hänen kunniassa pitää, ja antoi hänelle lahjoja, ja käski sotaväkensä niin Jonatanille kuuliaiset olla kuin itse hänellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 44, 'Ja sanoi Jonatanille: miksi sinä teet kansalle niin suurta vaivaa, koska ei meidän välillämme ole yhtään sotaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 45, 'Anna heidän palata kotiansa, ja ota sinulles vähä väkeä, jotka sinun tykönäs ovat, ja käy minun kanssani Ptolomaidiin. Sen kaupungin minä tahdon antaa sinulle, ja ne muut vahvat kaupungit, ja tahdon sinun haltuus antaa kaiken sotaväen ja päämiehet. Sillä minun pitää menemän takaperin jälleen, ja ainoasti sen syyn tähden minä olen tänne tullut; sentähden kuitenkin seuraa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 46, 'Jonatan uskoi häneen, ja antoi väkensä mennä pois tyköänsä Juudeaan kotiansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 47, 'Ja piti kolmetuhatta vaivoin tykönänsä, joista hän kaksituhatta lähetti Galileaan, mutta se yksi tuhat ainoasti seurasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 48, 'Kuin Jonatan tuli Ptolomaidin kaupunkiin, antoi Tryphon sulkea portit, ja Jonatanin ottaa kiinni ja hänen väkensä tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 49, 'Ja lähetti sekä jalkamiehiä että ratsasmiehiä Galileaan, leviälle kedolle, hukuttamaan Jonatanin toista sotajoukkoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 50, 'Mutta koska he ymmärsivät, että Jonatan oli vangiksi otettu väkinensä, neuvoivat he toinen toistansa valmistamaan itsensä sotaan ja menemään rohkiasti vihollista vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 51, 'Mutta kuin viholliset näkivät itsensä siinä olevan hengen vaarassa, ja että nämät tahtoivat heitänsä varjella, kääntyivät he takaperin ja menivät matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 52, 'Niin se väki myös meni kotiansa jälleen rauhassa, ja itkivät Jonatania ja muita, jotka hänen seurassansa tapetut olivat, ja kaikki Israelissa olivat surulliset Jonatanin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 12, 53, 'Ja kaikki pakanat ympäristöltä rupesivat karkaamaan heidän päällensä ja vaivaamaan kansaa, ja sanoivat: Ei heillä ole yhtään päämiestä eikä holhojaa enää: käykäämme nyt heitä vastaan, ja hävittäkäämme heitä, ja pyyhkikäämme pois heidän nimensä maan päältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 1, 'Kuin Simon. kuuli, että Tryphon suuren sotaväen koonnut oli, menemään Juudalaisia vastaan ja hävittämään heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 2, 'Ja näki kansan peljästyneen ja hämmästyneen, tuli hän Jerusalemiin, vahvisti heitä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 3, 'Te tiedätte, kuinka suurta sotaa minä ja minun veljeni ja isäni lain ja pyhän edestä olemme pitäneet, ja olette nähneet sen vaivan, jossa kaikki Israel on ollut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 4, 'Jossa myös kaikki minun veljeni Israelin tähden ovat hukkuneet, ja ei heistä silleen yhtään muuta elä kuin minä yksinäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 5, 'Nyt en minä tahdo säästää henkeäni tässä surussa ja vaivassa, sillä en minä ole parempi kuin minun veljenikään, enkä myös pyydä parempaa menoa kuin heillä oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 6, 'Mutta minä tahdon kostaa minun kansani edestä, meidän pyhämme, meidän vaimoimme ja lastemme edestä; sillä kaikki pakanat tässä ympäristöllä ovat julmistuneet meidän päällemme, ja kokoontuvat meitä hukuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 7, 'Tästä puheesta sai kansa lohdutuksen jälleen, vahvistuivat, ja vastasivat ja huusivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 8, 'Sinun pitää oleman meidän päämiehemme Juudaan ja Jonatanin sinun veljes siassa, sotimaan vihollisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 9, 'Ja me tahdomme olla sinulle kuuliaiset niissä kaikissa, joita sinä meille käsket.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 10, 'Niin kutsui Simon sotaväen yhteen, ja antoi käskyn, että Jerusalemin muurit olisivat äkisti paratut, ja kaupunki tulis ympärinsä hyvin turvatuksi ja vahvistetuksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 11, 'Ja lähetti Jonatanin Absalomin pojan sotajoukon kanssa Joppeen; ja Jonatan ajoi viholliset ulos Jopesta ja omisti kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 12, 'Silloin meni Tryphon ulos Ptolomaidista suurella sotaväellä, ja aikoi mennä Juudeaan, ja vei Jonatanin vankina myötänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 13, 'Mutta Simon kävi häntä vastaan, ja asetti leirinsä lakialle kedolle lähes Addusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 14, 'Mutta kuin Tryphon ymmärsi, että Simon veljensä Jonatanin siaan oli tullut päämieheksi, ja ajatteli tapella hänen kanssansa, lähetti hän sanan Simonille ja antoi hänelle sanoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 15, 'Minä olen Jonatanin pitänyt kiinni rahan tähden, jonka hän virkansa puolesta on kuninkaalle velkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 16, 'Jos sinä tahdot lähettää minulle sata leiviskää hopiaa, ja antaa kaksi hänen poikaansa pantiksi, ettei hän meidän tyköämme pakenisi pois, eikä asettelisi itsiänsä meitä vastaan, kuin hän vallallensa pääsee, niin minä tahdon hänen irralle päästää, ja sinulle antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 17, 'Vaikka Simon ymmärsi sen kaiken olevan petoksen, kuitenkin hän niin toimitti, että raha ja lapset tulivat Tryphonille lähetetyksi, ettei kansa olisi hänen ylitsensä valittanut ja sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 18, 'Jonatanin täytyi sentähden hukkua, ettei hän tahtonut häntä lunastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 19, 'Sentähden lähetti hän hänelle ne lapset ja sata leiviskää hopiaa. Mutta Tryphon ei pitänyt lupaustansa, eikä Jonatania irralle päästänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 20, 'Ja vielä sitte meni Tryphon edemmä, että hän olis taitanut tulla maalle vahinkoa tekemään, ja vaelsi Hadorin tietä. Mutta Simon sotaväkinensä oli joka paikassa hänen sivullansa, ja kuhunka hän tahtoi mennä, sen ennätti häneltä Simon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 21, 'Niin myös ne, jotka linnassa olivat, lähettivät sanan Tryphonille, että hän olis vaeltanut heidän tykönsä korven lävitse, ennen kuin Simon olis ennättänyt, ja että hän olis antanut heille viljaa tuoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 22, 'Sentähden kiiruhti Tryphon kaikkein ratsasmiestensä kanssa menemään heidän tykönsä, mutta sinä yönä tuli sangen suuri lumi ja esti hänen sieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 23, 'Sitte hän meni Galaadiin, ja Baskaman tykönä antoi tappaa Jonatanin poikinensa, jotka siinä haudattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 24, 'Ja Tryphon meni jälleen omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 25, 'Niin Simon lähetti noutamaan veljensä ruumiin, ja pani sen oman isänsä hautaan Modin kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 26, 'Ja koko Israel valitti kauvan ja itki Jonatania.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 27, 'Ja Simon antoi tehdä isällensä ja veljillensä korkian haudan vuolluista kivistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 28, 'Jonka päälle hän pani seitsemän patsasta, liki toinen toistansa, isällensä, äidillensä ja neljälle veljellensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 29, 'Ja antoi suuret patsaat sen ympärille tehdä, ja asetti niiden päälle heidän aseensa ijankaikkiseksi muistoksi, ja aseitten sivuun antoi panna hakatut haahdet, jotka purjehtivaiset meressä näkemän piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 30, 'Tämä hauta on Modissa vielä tänäpänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 31, 'Mutta Tryphon johdatteli nuorta Antiokusta petollisesti sinne ja tänne maakunnissa, siihen asti kuin hän salaisesti hänen tappoi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 32, 'Ja sitte pani itse kruunun päähänsä, tuli Asian kuninkaaksi ja vaivasi Juudan maakuntaa sangen kovin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 33, 'Mutta Simon rakensi monta kaupunkia Juudeassa paksuilla muureilla, korkeilla torneilla ja vahvoilla porteilla, ja toimitti viljaa vahvimpiin kaupunkeihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 34, 'Ja lähetti valituita miehiä kuningas Demetriuksen tykö, rukoilemaan häneltä lievitystä siitä kuormasta, jonka Tryphon oli laskenut hänen päällensä; sillä ei Tryphon muuta tehnyt maakunnassa, vaan väkivaltaa ja murhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 35, 'Siihen vastasi Demetrius ja kirjoitti näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 36, 'Kuningas Demetrius toivottaa ylimmäiselle papille Simonille, ja vanhimmille, ja Juudan kansalle terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 37, 'Kultaisen kruunun ynnä palmun kanssa, jonka te minulle lähetitte, olemme me saaneet, ja olemme valmiit tekemään hyvän rauhan teidän kanssanne, ja kirjoittamaan meidän käskyläistemme tykö, että heidän pitää antaman teitä kaikesta siltä kuormasta vapaana olla, josta me ennen olemme luvanneet teille vapauden antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 38, 'Ja mitä me teille luvanneet olemme, se pitää uskollisesti lujana ja vahvana pidettämän. Kaikki ne linnat, jotka te olette rakentaneet, pitää teidän pitämän ja nautitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 39, 'Ja me annamme anteeksi kaikki, mitä te toisinansa olette tehneet meitä vastaan, kruunun teot ja muut verot, jotka Jerusalem piti tekemän, ne me annamme teille anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 40, 'Ja jotka meitä tahtovat palvella, ne me tahdomme ottaa vastaan, ja meidän välillämme pitää hyvä rauha oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 41, 'Seitsemäntenäkymmenentenä vuotena toista sataa, tuli Israel vapahdetuksi pakanain ikeen alta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 42, 'Ja ruvettiin kirjoittamaan heidän asiakirjoihinsa näin: ensimäisenä Simonin, ylimmäisen papin ja Juudalalsten päämiehen vuotena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 43, 'Niinä päivinä piiritti Simon Gatsan kaupungin, ja asetti sen eteen vahvat sodan rakennukset, ja väkisellä voitti kaupungin, ja sai yhden tornin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 44, 'Ja ne, jotka tulivat tornin päälle, hyppäsivät kaupunkiin. Ja kansa, joka oli kaupungissa, hämmästyi ja peräti peljästyi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 45, 'Ja juoksivat vaimoinensa ja lapsinensa muurien päälle, repäisivät vaatteensa ja huusivat korkiasti, anoivat armoa ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 46, 'Älä meitä rankaise meidän pahuutemme jälkeen, mutta ole meille armollinen, niin me tahdomme hyvällä mielellä kuuliaiset olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 47, 'Tämä lepytti Simonin niin, ettei hän antanut heitä tappaa; mutta käski heitä mennä kaupungista pois, ja antoi puhdistaa ne huoneet, Joihin epäjumalat pannut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 48, 'Sitten meni hän kaupunkiin, kiitti ja kunnioitti Jumalaa, ja antoi kaikki kauhistukset ottaa pois ja hävittää, ja pani siihen kansaa, Joka Jumalan lain piti, ja teki kaupungin vahvaksi, ja rakensi jällensä siihen itsellensä huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 49, 'Ja ne, jotka Jerusalemin linnassa olivat, suljettiin, niin ettei yksikään saanut käydä ulos taikka sisälle, eikä mitään ostaa taikka myydä, mutta kärsivät suurta nälkää, niin että monen täytyi nälästä kuolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 50, 'Ja sentähden he huusivat Simonin tykö, Ja rukoilivat rauhaa ja antoivat itsensä. Niin teki Simon armon heidän kanssansa ja antoi heidän elää. Mutta heidän piti linnasta menemän pois, ja Simon antoi linnan jälleen puhdistaa kaikista kauhistuksista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 51, 'Ja sai sen kolmantena päivänä kolmattakymmentä toisena kuuna, ensimäisenä vuotena kahdeksattakymmentä toista sataa, ja meni sinne kiitosvirsillä, palmuoksilla ja kaikkinaisilla kanteleilla, kiitti Jumalaa, että he siitä suuresta julmuudesta, joka Israelin päällä oli, tulivat vapahdetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 52, 'Ja käski sen päivän joka vuosi ilolla pyhitettää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 13, 53, 'Ja rakensi vuorella muurit ympäri templiä, läsnä linnaa, ja teki ne vielä vahvemmiksi, ja asui itse siellä, hän ja ne, jotka hän tykönänsä piti. Ja että hän näki poikansa Johanneksen toimellisen ja kelvollisen miehen olevan, asetti hän hänen kaiken sotaväen päämieheksi, ja pani asumaan Gatsaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 1, 'Toisena vuonna kahdeksattakymmentä toista sataa kokosi kuningas Demetrius sotaväkensä, ja meni Mediaan apua saamaan Tryphonia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 2, 'Mutta kuin Arsases, Persian ja Median kuningas, ymmärsi, että Demetrius oli mennyt valtakuntaansa, lähetti hän yhden päämiehistänsä häntä vastaan, ja käski vangiksi ottaa hänen ja elävänä tykönsä tuoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 3, 'Se päämies löi Demetriuksen sotaväen, otti hänen kiinni ja vei kuningas Arsaseksen tykö; niin piti Arsases hänen vankina, ja antoi hänestä ottaa vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 4, 'Silloin oli Juudeassa lepo ja hyvä rauha, niinkauvan kuin Simon eli; ja Simon hallitsi sangen hyvin, ja teki maakunnalle paljon hyvää, niin että hän hyvällä mielellä pidettiin herrana kaikkina ikäpäivinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 5, 'Ja hän voitti suurella kunnialla Jopen kaupungin ja sen sataman, josta hän sai purjehtia merelle luotolaisten tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 6, 'Ja voitti allensa maakuntia, ja rajat omassa maassansa siirsi edemmäksi, ja päästi monta, jotka ennen olivat poljetut alas ja vankina olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 7, 'Hänellä myös oli Gatsa ja Betsura ja Jerusalemin linna, jonka hän vastuudesta puhdisti, ja ei yksikään tohtinut olla häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 8, 'Jokainen kynti peltojansa hyvässä rauhassa, maa kasvoi viljan, ja puut kantoivat hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 9, 'Vanhimmat hallitsivat ilman estettä, ja toimittivat kaikki hyvin; kauppamiehet menestyivät ja hyötyivät kaupoissansa, ja valmistivat itsellensä aseita ja varaa vihollisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 10, 'Simon myös toimitti jyviä ja viljaa kaupunkeihin, niin että tarpeen aikanakin piti heillä kyllä oleman, ja hän oli kuuluisa mies kaikessa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 11, 'Hän piti rauhan maakunnassa, niin että kaikki Israel iloitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 12, 'Ja jokainen nautitsi viinamäkensä ja yrttitarhansa rauhassa, ja ei he ketään peljänneet, sillä ei yksikään tohtinut heitä vaivata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 13, 'Ja ei Syrian kuninkaat tohtineet siihen aikaan heille mitään pahaa tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 14, 'Ja hän teki oikeuden maakunnassa, ja varjeli köyhiä kansansa seassa väkivaltaa vastaan, ja rankaisi kaikki väärät, ja hukutti jumalattomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 15, 'Pyhän saatti hän jälleen kunniaan, ja antoi pyhää kalua siihen lisätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 16, 'Ja kuin se sanoma kuului Roomissa ja Spartassa, että Jonatan tapettu oli, tulivat he kaikki surullisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 17, 'Mutta kuin Roomalaiset kuulivat, että Simon hänen veljensä oli ylimmäinen pappi, ja oli maakunnan omistanut, ja viholliset ajanut pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 18, 'Niin he uudistivat sen liiton, jonka he ennen Juudaan ja hänen veljensä Jonatanin kanssa tehneet olivat, ja kirjoittivat vaskitauluihin ja lähettivät hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 19, 'Se kirjoitus luettiin julkisesti kansan edessä Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 20, 'Ja Spartasta kirjoitettiin Simonin tykö näin: neuvonantajat ja Spartan asuvaiset toivottavat ylimmäiselle papille Simonille, ja vanhimmille, ja papeille, ja Juudan kansalle, omille veljillensä, terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 21, 'Teidän asianajajat tulivat meidän tykömme ja sanoivat, että te teidän vihollisenne olette lyöneet suurella kunnialla, ja olette nyt hyvässä rauhassa, josta meillä on suuri ilo. Me olemme myös meidän kaupungin kirjoihin antaneet kirjoittaa, mitä he toimittaneet ovat, näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 22, 'Juudalaisten asianajajat, Numeuius Antiokuksen poika ja Antipater Jasonin poika, tulivat meidän tykömme uudistamaan ystävyyttä Juudalaisten ja meidän välillämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 23, 'Ja me toimitimme yksimielisesti, että ne sanansaattajat kunniallisesti piti otettaman vastaan, ja heidän puheensa kaupungin kirjaan kirjoitettaman ijankaikkiseksi muistoksi. Tämän vastauksen he kirjoittivat Simonille, ylimmäiselle papille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 24, 'Senjälkeen lähetti Simon Numeniuksen jällensä Roomiin, viemään suurta kultaista kilpeä, joka painoi tuhannen leiviskää, ja uudistamaan liittoa heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 25, 'Kuin Roomalaiset kuulivat hänen asiansa, sanoivat he: meidän pitää ilman estettä tekemän Simonille ja hänen lapsillensa kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 26, 'Sillä hän ja hänen veljensä ovat miehuulliset olleet, ja Israelin varjelleet, ja viholliset ajaneet pois, sentähden vahvistivat Roomalaiset sen yksimielisesti, että Juudalaiset piti vapaat oleman; ja he antoivat sen kirjoittaa vaskitauluihin, jotka piti patsaisiin lyötämän Zionin vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 27, 'Tämä seuraavainen kirjoitus on tehty kahdeksantena päivänä toistakymmentä Elulin kuulla, toisena vuotena kahdeksattakymmentä toista sataa, ylimmäisen papin Simonin Saramelista kolmantena hallituksen vuotena,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 28, 'Suuressa vanhimpain, pappein ja kaiken Juudan kansan kokouksessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 29, 'Jokaiselle olkoon tiettävä ja julkinen, että niissä suurissa sodissa, jotka meidän maakunnissa ovat olleet, Simon Matatiaan poika, Jaribin suvusta., ja hänen veljensä ovat henkensä antaneet vaaraan, ja olleet oman kansansa vihollisia vastaan, ettei pyhä ja Jumalan laki olisi tullut maahan lyödyksi ja hävitetyksi, ja ovat saaneet kansansa suureen kunniaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 30, 'Sillä Jonatan kokosi kansan jälleen, ja otti hallitusviran ja tuli ylimmäiseksi papiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 31, 'Mutta kuin hän kuoli, tulivat viholliset jälleen, ja tahtoivat hävittää maakunnan ja pyhän. 13: 23.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 32, 'Niin Simon nousi ja soti meidän vihollisiamme vastaan, ja toimitti meidän sotaväelle aseita, ja maksoi heidän palkkansa omasta rahastansa ja hyvyydestänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 33, 'Ja vahvisti kaupungit Juudeassa ja Betsuran rajakaupungin, jossa viholliset ennen sota-aseensa ja sodan valmistukset pitivät, ja pani Juudalaisia sitä varjelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 34, 'Hän vahvisti myös Jopen, joka on merikaupunki, ja Gatsan, joka on Asdodin rajoilla; sillä Gatsa oli ennen ollut vihollisten linna, mutta Simon omisti sen, ja pani siihen Juudalaisia, ja asetti siihen hyvän hallituksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 35, 'Kuin kansa Simonin uskollisuuden ymmärsi, ja tiesi ne hyvät työt, jotka hän heille tehnyt oli, valitsivat he hänen päämieheksensä ja ylimmäiseksi papiksensa hänen hyvyytensä ja uskollisuutensa tähden, jonka hän kaikelle kansalle osoitti, ja ahkeroitsi alamaisillensa kaikkea hyvää tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 36, 'Sillä hänen aikanansa antoi Jumala menestyksen hänen kättensä kautta, niin että pakanat meidän maakunnasta ja Jerusalemista ja linnasta tulivat ajetuksi pois, jossa he olivat, josta he myös läksivät ja hävittivät pyhän, ja puhtaan jumalanpalveluksen sokaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 37, 'Mutta Simon omisti linnan, ja pani siihen Juudalaisia varjelemaan Jerusalemin kaupunkia ja maakuntaa, ja korotti Jerusalemin muurit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 38, 'Ja kuningas Demetrius vahvisti hänen ylimmäisen papin virkaan');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 39, 'Ja piti ystävänänsä, ja teki hänelle suuren kunnian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 40, 'Sillä hän ymmärsi, että Roomalaiset Juudalaisten asiamiehiä kunniallisesti ottivat vastaan, ja olivat tehneet liiton heidän kanssansa, ja ottaneet heitä varjelukseensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 41, 'Ja että Juudan kansalla ja heidän papeillansa yksimielisesti se neuvo oli, että Simon piti heidän päämiehensä ja ylimmäinen pappinsa alinomaisesti oleman, siihenasti että Jumala heille sen oikian Prophetan olis herättänyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 42, 'Ja että hänen piti päämiehen oleman, ja pyhän varjeleman, ja asettaman käskyläiset maakuntaan, ja kaikki sodan neuvot ja linnat pitämän hallussansa ja voimassansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 43, 'Ja että jokaisen piti häntä kuuleman, ja kaikki käskyt hänen nimellänsä käymän ulos; ja että hänen piti purpurassa ja kullassa käymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 44, 'Kaikki nämät piti uskollisesti ja vahvasti kaikelta kansalta ja kaikilta papeilta pidettämän, ja ei yhdenkään pitänyt asettaman itsiänsä tätä vastaan, eikä yhdelläkään oleman voimaa maakunnassa kansaa yhteen kutsua, eikä purpuraa taikka kultaista vyötä kantaa, vaan hänellä ainoasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 45, 'Mutta joka tekee tätä vastaan ja tämän säädyn rikkoo, sen pitää vikapään oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 46, 'Näin lupasi kaikki kansa Simonille olla kuuliainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 47, 'Siihen myös Simon tyytyi ja tuli ylimmäiseksi papiksi, ja Juudan kansan päämieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 48, 'Ja yhteinen kansa käski tämän päätöksen vaskisiin tauluihin kirjoittaa, ja pantaa templin läpikäytävään julkiseen paikkaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 14, 49, 'Ja yhden senkaltaisen kirjoituksen siitä panna veroarkkuun, josta Simon ja hänen jälkeentulevaisensa piti sen aina löytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 1, 'Kuinka erinkaltaisesti Antiokus ja Roomalaiset Juudalaisia kohtaavat. Ja kuningas Antiokus Demetriuksen poika kirjoitti luodoista Simonin ja Juudan kansan tykö näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 2, 'Kuningas Antiokus toivottaa Simonille, ylimmäiselle papille, ja Juudan kansalle terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 3, 'Että muutamat kapinan nostajat ovat ottaneet minulta pois minun perintövaltakuntani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 4, 'Niin minä tahdon sen jälleen alleni ottaa, ja antaa sen olikian perillisten alle tulla: ja sentähden olen minä muukalaista sotaväkeä ottanut ja haaksia teettänyt, ja tahdon valtakuntaani käydä, että minä kapinan nostajat rankaisisin, jotka minun valtakunnassani paljon vahinkoa tehneet ovat ja monta kaupunkia hävittäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 5, 'Sentähden minä annan sinulle kaikki ne, mitä kuninkaat ennen sinulle antaneet ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 6, 'Ja annan sinulle voiman rahaa lyödä omassa maakunnassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 7, 'Ja Jerusalem ja pyhä saa vapaa olla. Sinun omas pitää myös oleman kaikki ne linnat, jotkas rakentanut olet, ja kaikki, mitäs tähän asti pitänyt olet, ja kaikki ne sota-aseet, jotka sinä tehnyt olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 8, 'Ja annan sinulle vapauden kaikista niistä, mitkä kuninkaalle tehtämän pitäis, ja muutoin kuninkaan omat ovat, tästä ajasta ruveten, niin ijäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 9, 'Ja kuin me valtakuntamme jälleen saamme, niin me tahdomme sinulle, ja sinun kansalles ja templille vielä suuremman kunnian tehdä, niin että teidän pitää kaikessa valtakunnassa kuuluisat oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 10, 'Neljäntenä vuotena kahdeksattakymmentä toista sataa tuli Antiokus jälleen perintövaltakuntaansa, ja kaikki sotaväki hylkäsi Tryphonin, ja meni hänen tykönsä, ja sangen harvat jäivät Tryphonin puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 11, 'Kuin kuningas Antiokus meni hänen jälkeensä, pakeni hän Doraan, joka on meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 12, 'Sillä hän näki olevansa vaarassa, että sotaväki hänen jätti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 13, 'Mutta Antiokus meni hänen jälkeensä Doraan sadalla ja kahdellakymmenellä tuhannella jalkamiehellä ja kahdeksallatuhannella ratsasmiehellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 14, 'Ja piiritti kaupungin sekä maalta että vedeltä, niin ettei yksikään saanut siitä käydä ulos taikka sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 15, 'Siihen aikaan tuli Numenius Roomista ja muut, jotka hänen kanssansa lähetetyt olivat, ja toivat kirjoja kuningasten tykö ja maakuntiin, joissa oli kirjoitettu näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 16, 'Lukius, Roomin kaupungin haltia, toivottaa kuningas Ptolomeukselle terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 17, 'Simon, ylimmäinen pappi, ja Juudan kansa ovat lähettäneet asiansa ajajat meidän tykömme, uudistamaan ystävyyttä ja liittoa meidän välillämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 18, 'Ja ovat myös lähettäneet meille kultaisen kilven, joka painaa tuhannen leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 19, 'Sentähden me kirjoitamme kuningasten ja muiden herrain tykö, ettei heidän Juudalaisia vastaan mitään tekemän pidä, eikä heidän kaupunkeihinsa ja maakuntiinsa menemän, eikä myös pidä heidän ketään auttaman sotimaan heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 20, 'Sillä me olemme ottaneet heiltä sen kilven tykömme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 21, 'Ja jos muutamia kovakorvaisia heidän maakunnastansa teidän tykönne on paenneet, ne teidän pitää lähettämän ylimmäisen papin Simonin tykö, että hän heitä lakinsa jälkeen sais rangaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 22, 'Näin olemme me myös kirjoittaneet kuningas Demetriuksen, Attaluksen, Aretan Ja Alsasen tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 23, 'Ja kaikkiin maakuntiin, Ja Sampsasiin ja Spartalaisten tykö, ja niiden tykö, jotka Delossa, Myndossa, Sikyonissa, Kariassa, Samossa, Pamphyliassa, Lysiassa, Halikarnassossa, Rodossa, Faselissa, Koossa, Sidonissa, Gortynassa, Knidossa, Kyprissä Ja Kyrenessä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 24, 'Ja tämänkaltaisen kirjan me olemme lähettäneet ylimmäiselle papille Simonille ja Juudan kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 25, 'Silloin vei Antiokus vielä toisen sotaväen Doran alle, kovemmin sitä piirittämään, ja pani sodan rakennukset sen eteen, ja ahdisti kaupungin joka taholta ja sulki Tryphonin sinne, ettei hän saanut käydä ulos eikä sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 26, 'Ja Simon lähetti Antiokuksen avuksi kaksituhatta hyvää ja valittua miestä, ja paljon kultaa, ja hopiaa ja aseita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 27, 'Mutta Antiokus ei ottanut niitä vastaan, eikä sitä pitänyt, mitä hän ennen luvannut oli vaan peräti kylmeni Simonia vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 28, 'Ja lähetti yhden ystävistänsä hänen tykönsä, nimeltä Atenobiuksen, häntä puhuttelemaan ja sanomaan: te olette Jopen, ja Gatsan ja Jerusalemin linnan omistaneet, jotka kaikki minun valtakuntaani tulevat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 29, 'Ja olette maakunnan niiden ympäristöltä hävittäneet, ja suuren vahingon tehneet minun valtakunnassani, ja olette omistaneet minun perintömaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 30, 'Sentähden anon minä teiltä nämät kaupungit jällensä, jotka te olette ottaneet minulta pois, ja kaiken veron niistä kaupungeista, jotka teillä on paitsi Juudan maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 31, 'Mutta jos ette sitä tahdo tehdä, niin antakaat minulle niiden kaupunkein edestä viisisataa leiviskää hopiaa, ja sen vahingon ja veron edestä toiset viisisataa leiviskää, mutta jos ette sitä tottele, niin me tahdomme sotia teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 32, 'Kuin Atenobius, kuninkaan ystävä, tuli Jerusalemiin ja näki Simonin suuren kunnian ja sen koreuden, joka hänellä oli kullasta ja hopiasta, ja kuinka hän muutoinkin oli jalosti valmistettu, ihmetteli hän sitä sangen suuresti, ja jutteli hänen edessänsä, mitä kuningas oli käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 33, 'Siihen antoi Simon hänelle tämän vastauksen: se maakunta, jonka me jälleen omistaneet olemme, on meidän isäimme perintö, ja ei se kenenkään muiden oma ole; mutta meidän vihollisemme ovat sen kauvan aikaa väkivallalla ja vääryydellä omanansa pitäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 34, 'Sentähden olemme me nyt meidän omamme jälleen ottaneet, ja emme kenenkään toisen omaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 35, 'Mutta että sinä sitä valitat, että me Jopen ja Gatsan olemme ottaneet, siihen oli se syy, että niistä tehtiin meidän maakunnallemme ja kansallemme suuri vahinko; mutta kuitenkin me tahdomme niiden edestä antaa sata leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 36, 'Siihen ei Atenobius mitään vastannut, vaan vihastui ja meni matkaansa kuninkaan tykö, ja ilmoitti hänelle Simonin vastauksen, ja hänen kunniansa ja jaloutensa ja kaikki, mitä hän nähnyt oli. Silloin kuningas vihastui sangen hirmuisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 37, 'Mutta Tryphon pääsi pois sieltä, ja haahdella pakeni Ortosiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 38, 'Niin kuningas teki Kendebeuksen merimaakunnan päämieheksi, ja antoi hänelle sotaväkeä sekä ratsasmiehiä että jalkamiehiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 39, 'Ja käski hänen sioittaa itsensä Juudan maan rajoille, ja vahvistaa Kedronin kaupungin, ja rakentaa linnan vuorelle, josta heidän piti Juudeaan menemän: mutta kuningas ajoi Tryphonia takaa, käsittääksensä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 40, 'Kuin siis Kendebeus tuli Jamniaan, löi hän Juudalaisia ja ryösti heidän maakuntansa, ja antoi tappaa paljon kansaa, ja otti monta kiinni ja vei pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 15, 41, 'Ja rakensi Kedronin kaupungin, ja pani siihen sotaväkeä, että he sieltä rajoilta olisivat karanneet ulos, ja sulkeneet Juudalalsten sotaväen tien, niinkuin kuningas heidän käskenyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 1, 'Johanneksen Simonin pojan urhoollisuudesta, niin myös Ptolomeuksen murhatyöstä appiansa Simonia vastaan. Sentähden meni Johannes Gatsasta isänsä Simonin tykö, ja ilmoitti hänelle, että Kendebeus oli maalle tullut, ja paljon vahinkoa tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 2, 'Silloin Simon kutsui kaksi vanhinta poikaansa tykönsä, Juudaan ja Johanneksen, ja sanoi heille: minä ja minun veljeni ja koko minun isäni huone olemme hamasta nuoruudesta niin tähän aikaan asti sotineet Israelin vihollisia vastaan, ja Jumala on meille onnen antanut, ja Israel on monasti meidän kättemme kautta holhottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 3, 'Mutta että minä vanha ja heikko olen, niin teidän pitää nyt astuman minun ja minun veljeni siaan, ja menemän sotimaan kansanne edestä. Jumala taivaasta auttakoon teitä ja olkoon teidän kanssanne!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 4, 'Niin hän antoi valita maakunnasta kaksikymmentä tuhatta jalkamiestä ja muutamia hevosmiehiä; tällä joukolla meni Johannes ja Juudas Kendebeusta vastaan, ja olivat yötä Modissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 5, 'Mutta huomeneltain, kuin he Modista tulivat lakialle kedolle, tuli suuri sotaväki heitä vastaan, sekä ratsasmiehiä että jalkaväkeä. Ja siellä oli virta molempain sotajoukkojen välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 6, 'Niin Johannes meni virran tykö, ja käänsi itsensä vihollisia vastaan, ja kuin hän näki, ettei sotaväki tahtonut virtaan mennä, niin hän rohkaisi itsensä, ja meni ensisti ylitse, ja kuin muu väki sen näki, menivät he myös ylitse hänen perässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 7, 'Niin Johannes asetti väkensä rinnan vihollisia vastaan, ja pani hevosmiehet jalkaväen tykö, mutta vihollisilla oli paljoa enempi sotaväkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 8, 'Kuin siis Johannes antoi pappein vaskitorviin puhaltaa, ja löi vihollista, niin Kendebeus pakeni sotajoukkoinensa, ja siinä tuli monta haavoitetuksi ja lyödyksi; ja ne muut pakenivat vähään, vahvaan kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 9, 'Siinä sodassa tuli myös Juudas, Johanneksen veli, haavoitetuksi, mutta Johannes ajoi takaa vihollisia Kedronin linnaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 10, 'Ja viholliset pakenivat Atsodin maan paikoille linnoihin. Silloin Johannes poltti ne linnat, niin että vihollisista liki kaksituhatta miestä tuli surmatuiksi. Senjälkeen meni Johannes rauhassa kotiansa Juudeaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 11, 'Mutta siellä oli yksi asetettu Jerihon maan päämieheksi, nimeltä Ptolomeus, Abodin poika, joka oli sangen rikas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 12, 'Ja ylimmäinen pappi Simon oli hänelle antanut tyttärensä avioksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 13, 'Jonka tähden hän myös oli ylpiä sydämestä, ja pyysi maan ruhtinaaksi, ja etsi tilaa Simonia ja hänen poikiansa petoksella päiviltä ottaa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 14, 'Kuin Simon vaelsi ympäri Juudan maata, kaikkia paikkoja katselemassa, ja hallitusta hyvin toimittamassa, ja tuli Jerihoon kahden poikansa Matatiaan ja Juudaan kanssa, seitsemäntenä vuotena kahdeksattakymmentä toista sataa, ensimäisenä kuuna toistakymmentä, joka kutsutaan Sabat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 15, 'Silloin otti Abodin poika heidät vastaan linnassa, joka kutsutaan Dok, ja valmisti heille suuren pidon, mutta se oli petosta täynnä, sillä hänellä oli siinä sotaväki kätkettynä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 16, 'Ja kuin Simon ja hänen poikansa tulivat iloisiksi ja juopuneiksi, nousi Ptolomeus palvelioinensa, ja otti aseensa ja karkasi Simonin päälle, siinä kussa hän istui, ja löi hänen ja kaksi hänen poikaansa, ja heidän palveliansa kuoliaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 17, 'Tämän häpiällisen petoksen teki Ptolomeos Israelissa, ja osoitti pahuutensa hyväin töiden edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 18, 'Senjälkeen kirjoitti hän kuningas Antiokuksen tykö, ja rukoili häneltä sotaväkeä avuksensa, omistaaksensa maakuntaa ja kaupungeita ja mitä niissä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 19, 'Hän lähetti myös joukon Gatsaan, surmaamaan Johannesta, ja kirjoitti päämiesten tykö, ja kutsui heitä tykönsä, ja lupasi heille antaa suuren palkan ja lahjat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 20, 'Ja lähetti sotaväkensä Jerusalemia ja templiä omistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 21, 'Mutta yksi sanansaattaja joutui edellä Gatsaan, joka ilmoitti Johannekselle, että hänen isänsä ja veljensä tapetut olivat, ja että myös häntä oli aiottu tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 22, 'Kuin Johannes nämät kuuli, peljästyi hän sangen kovin, Ja antoi ottaa kiinni ne, jotka lähetetyt olivat häntä tappamaan, ja kuin hän ymmärsi, että tämä on heidän ajatuksensa, niin hän antoi heidät tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 23, 'Mutta mitä Johannes sen jälkeen muuta teki, Ja millaisia sotia hän piti vihollisia vastaan, ja kuinka hän hallitsi ja muurit rakensi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 16, 24, 'Se on kirjoitettu erinomaiseen kirjaan, hänen aikansa hallituksesta, niinkauvan kuin hän isänsä jälkeen ylimmäinen pappi oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Kirkon puhdistusjuhlan pitämisestä, ja pyhän tulen jälleen löytämisestä. Me Juudalaiset, teidän veljenne, jotka Jerusalemissa ja koko Juudan maalla asumme, toivotamme teille Juudalaisille, meidän veljillemme, jotka Egyptissä olette, onnea ja terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Jumala siunatkoon teitä, ja muistakoon liittonsa, jonka hän Abrahamille, Isaakille ja Jakobille, uskollisille palvelijoillensa luvannut on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Ja antakoon teille vaan sydämen, että te hänen laissansa luojana ja vahvana pysyisitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Ja lainatkoon teille, että te viriät olisitte hänen käskynsä, ja lohduttakoon teitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Hän kuulkoon teidän rukouksenne, olkoon teille armollinen: ja älköön teitä hyljätkö tuskassa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Näin me alati teidän edestänne rukoilemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Me olemme teidän tykönne kirjoittaneet suurimmassa tuskassamme, (kuin Jason ja hänen joukkonsa pyhästä maasta ja valtakunnasta erkanivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Ja polttivat meidän porttimme, ja vuodattivat viatointa verta. Niin me rukoilimme, ja Herra kuuli meitä, ja me uhrasimme hänelle sämpyläjauhoja, ja sytytimme lamput, ja panimme näkyleivät edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Ja anomme, että te nyt meidän kanssamme pitäisitte lehtimajan juhlapäiviä Kasleun kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Kirjoitettu yhdeksäntenävuotena seitsemättäkymmentä toista sataa kuningas Demetriuksen aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Me Jerusalemissa ja kaikessa Juudeassa vanhimpain kanssa, ja Johannes, toivotamme Aristobulukselle, kuningas Ptolomeuksen opetusisälle, joka paplllisesta suvusta on, ja muille Juudalaisille, jotka Egyptissä ovat, onnea ja terveyttä! Me kiitämme täydestä syystä Jumalaa, että hän meidät niin suuresta tuskasta pelastanut on, joiden itsiämme niin väkevää kuningasta vastaan varjeleman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Sillä Jumala on ajanut pois meidän vihollisemme pyhästä kaupungista Persiaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Siellä kuningas voittamattoman joukkonsa kansa Nanen kirkossa tapettiin, Nanen pappein kavaluudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Sillä hän Antiokus sinne tuli ystävinensä, naisjumalan Dianan tykö, niinkuin naimaan häntä, ja kaiken rahan templistä huomenlahjaksi ottamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Ja kuin Nanen papit sen ymmärsivät, ja hän muutamain kanssa kappeliin mennyt oli, lukitsivat he hänen peräänsä kirkon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Ja laskettivat hänen ja kaikki, jotka hänen kanssansa olivat kivillä kuoliaaksi; sitte hakkasivat he hänen kappaleiksi, ja heittivät heidät sieltä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Jumalan olkoon alati kiitos, että hän jumalattomat niin on pois ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Että me viidentenä päivänä kolmattakymmentä Kasleun kuulla ajattelemme templin puhdistusta pitää, olemme me tahtoneet teille tietää antaa, että te myös meidän kanssamme sitä juhlaa pitäisitte, niinkuin se päivä pidetään, jona Nehemia tulen löytänyt on, kuin hän templin ja alttarin rakensi, ja taas uhrasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Sillä kuin meidän isämme Persiaan vietiin, ovat papit tulen alttarilta syvään, kuivaan kuoppaan kätkeneet ja tähteellä pitäneet, ettei sitä kenkään tietänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Kuin nyt Nehemia, ei monta vuotta sitte, Jumalan tahdosta kuninkaalta kotia lähetettiin, lähetti hän niiden pappein jääneet sukulaiset, jotka sen tulen kätkeneet olivat, että he sen jälleen etsisivät. vaan, niinkuin he meille ilmoittaneet ovat, ei he löytäneet tulta, vaan sakian veden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Sitä hän on käskenyt ammuntaa ja tuoda. Kuin nyt kaikki uhriksi valmistettu oli, on Nehemia käskenyt, että heidän piti valaman veden halkoin ja uhrin päälle, joka halkoin päällä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Kuin he sen tehneet olivat, ja aurinko hyvin noussut oli, ja pilvet kadonneet pois, niin syttyi suuri tuli, jota he kaikki ihmettelivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Niin rupesivat papit ja kansa rukoilemaan, siihenasti kuin uhri palanut oli; ja Jonatan veisasi edellä, mutta muut vastasivat häntä Nehemian kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Mutta tämä oli Nehemian rukous: Herra meidän Jumalamme, joka kaikki kappaleet luonut olet, ja olet peljättävä, väkevä, ja hurskas, ja laupias, ja ainoa oikia kuningas ja voideltu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Joka ainoa kaikki lahjat annat, sinä ainoa hurskas, kaikkivaltias ja ijankaikkinen olet, sinä joka Israelin pelastat kaikesta pahasta, joka meidän isämme valinnut ja pyhittänyt olet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Ota tämä uhri koko Israelin edestä, ja varjele ja pyhitä sinun perintös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Kokoo meitä hajoitettuja jälleen yhteen, pelasta heitä, jotka pakanoita palveleman pitää, ja näe meitä ylönkatsotuita, joita jokainen ilvoittaa, että pakanat ymmärtäisivät, että sinä meidän Jumalamme olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Rankaise heitä, jotka meitä sortavat, ja suurella pilkalla meitä häpäisevät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Istuta jälleen sinun kansas sinun pyhään paikkaas, niinkuin Moses sanonut on!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Sitälikin veisasivat papit kiitosvirsiä, siihenasti kuin uhri kulunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 31, 'Sitte käski Nehemia sen illan veden suurten kivien päälle kaataa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 32, 'Sieltä myös kävi liekki ulos; mutta se kulutettiin alttarin tulen liekiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 33, 'Se on kohta ilmi tullut ja Persian kuninkaan korviin, kuinka siitä paikasta, kuhunka tuli kätketty oli, vesi löydetty ja se uhrit sytyttänyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 34, 'Niin koetteli sitä myös kuningas, ja antoi sen palkan eroittaa ja pyhittää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 35, 'Ja antoi paljon rahaa siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 36, 'Ja Nehemian kumppanit nimittivät sen paikan Nekpariksi, se on puhdistus; muutamat kutsuvat sen myös Nephtariksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Raamatuista myös löydetään, että Jeremia propheta käskenyt oli niiden, jotka vietiin pois, ottaa tulen myötänsä, niinkuin ennen sanottu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Ja antanut heille lain ja käskenyt, ettei he Herran käskyjä unhottaisi, eikä antaisi itsiänsä vietellä, kuin he kultaiset ja hopiaiset jumalat ja heidän kaunistuksensa näkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Ja on senkaltaisia muita paljon heille käskenyt, ettei he lakia sydämestänsä unhottaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Niin oli se myös siinä kirjoituksessa, että propheta Jumalan käskystä heille käskenyt oli, että he todistuksen majan ja arkin myötänsä ottaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Kuin he nyt vuoren tykö tulivat, jonka päällä Moses ollut oli, ja Herran perintömaan nähnyt, löysi Jeremia luolan, sinne hän pisti majan ja arkin ja savu-uhrin alttarin, ja peitti luolan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Mutta muutamat, jotka kanssa menivät, tahtoivat sen luolan merkitä, mutta ei taitaneet löytää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Kuin Jeremia sen ymmärsi, nuhteli hän heitä, ja sanoi: tätä paikkaa ei pidä yhdenkään ihmisen tietämän, siihen asti kuin Herra kansansa kokoo ja heille leppyy, silloin Herra heille sen kyllä ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Ja Herran kunnia nähdään pilvessä, niinkuin se Moseksen aikana näkyi, ja kuin Salomo rukoili, että hän sen paikan pyhittäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Ja Jeremia luetteli myös heille, kuinka Salomo uhrannut oli, kuin kirkko vihittiin ja templi valmis oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Kuinka Moses Herraa rukoillut ja tuli taivaasta uhrit kuluttanut oli: niin rukoili myös Salomo, ja tuli kulutti myös polttouhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Ja kuin Moses sanonut oli, että hänen uhrinsa oli tulelta kulutettu ja ei syöty:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Niin myös Salomo on kahdeksan päivää uhrannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Ne kaikki löydetään niissä kirjoituksissa, jotka Nehemian aikana kirjoitetut ovat: ja niinkuin hän kuningasten, prophetain ja Davidin kirjat ja kuningasten kirjoitukset uhrista hakenut oli, ja yhden kirjaläjän niistä koonnut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Niin myös Juudas on tehnyt, ja mitä kirjoja sodan ollessa maalla oli tullut pois, on jälleen hakenut kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Ja ne ovat meidän tykönämme: jos te tahdotte niitä lukea, niin antakaat ne meiltä tuoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Että me nyt senkaltaista juhlaa pitää tahdomme, tahdoimme me kirjoittaa teidän tykönne, sillä teidän tulee myös sitä pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Mutta me toivomme Jumalan tykö, että Herra, joka kansaansa auttaa ja perinnön meille jälleen antaa, nimittäin valtakunnan ja pappeuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Niinkuin hän laissa luvannut on, pian meidän päällemme armahtaa, ja kokoo meidät jälleen yhteen avarasta maailmasta pyhään paikkaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Niinkuin hän jo suuresta tuskasta meitä pelastanut, ja sen paikan puhdistanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Mutta historia Juudas Makkabealaisesta ja hänen veljistänsä, ja ylimmäisen papin puhdistuksesta ja alttarin vihkimisestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Ja sodasta Antiokus Epiphanesta vastaan, ja hänen poikaansa Eupatoria vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ja siitä merkistä taivaassa, joka niille, jotka Juudalaisia urhoollisesti varjelivat, ilmaantunut on, että heitä niin vähä joukko koko maan ryöstäneet, ja suuren pakanain paljouden pakoon lyöneet, ja heidän perässänsä kiiruhtaneet ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Ja päälliseksi templistä, kuinka se jälleen rakennettiin, niinkuin joka paikassa jo siitä tiedetään, ja kaupunki vapautensa jälleen saanut on, että kaikki muut lait kielletyt ovat, ja ainoastaan Herran laki pidettämän pitää, joka meille nyt hyvää suo ja armollinen on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Nämät ja monta muuta, jotka Jason viidessä kirjassa kirjoittanut on, aiomme tässä lyhykäisesti koota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Sillä me näemme, kuinka luku sekoitettu on, että työläs on historiaa oikein ymmärtää, että se niin on sekoitettu yhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Sen tähden olemme me tahtoneet tehdä, että sitä hyvällä mielellä luettaisiin, paremmin ymmärrettäisiin ja jokaiselle hyödyllinen olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Ja tosin me tiedämme, että meidän myös niin työlääksi tulee, että me siihen vaivaan ruvenneet olemme; sillä siihen tarvitaan paljon työtä ja suuri vireys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Niinkuin ei se ilman vaivaa tapahdu, joka pidon valmistaa tahtoo ja vierasten hyvää tehdä. Kuitenkin emme siitä lukua pidä, vaan mielellämme tähän työhön rupeemme muiden hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Itse historiassa emme mitään muuta, vaan annamme olla niinkuin se ennen kirjoitettu on, ainoasti että me sen lyhemmäksi tahdomme koota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Ja niinkuin puuseppä, kuin hän uuden huoneen rakentaa, ei muusta lukua pidä, vaan että hän sen niin tekis, että se vahva olis; vaan kuinka se maalattaman ja kaunistettaman pitää, siitä antaa hän muiden murehtia:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 31, 'Niin myös me teemme ja annamme sen, joka tämän historian ensisti kirjoittanut on, siitä murheen pitää, kuinka hän kaikki puhunut ja kaikki kappaleet vireästi tehnyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 32, 'Emme muuta tahdo tehdä, vaan lyhemmäksi koota. Ja rupeemme nyt historiaan, ja tahdomme tämän ainoasti esipuheeksi sanoa, ettei esipuhe enempi olisi kuin koko historia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Kuin nyt jälleen Jerusalemissa hyvässä rauhassa asuttiin ja laki voimassansa oli, että ylimmäinen pappi Onias niin jumalinen oli ja niin visusti siltä vaarin piti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Myöntyivät myös kuninkaat kaupunkia kunnioittamaan, ja lähettivät jaloja lahjoja templiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Niin että Seleukus, Asian kuningas, määräsi tavaroistansa kaiken kulutuksen mikä uhriin tarvittiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Siihen aikaan oli yksi templin haltia, Simon nimeltä, yksi Benjaminilainen, se oli ylimmäisen papin vihamies, ettei hän hänen ilkivaltaisuuttansa kaupungissa sallinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Mutta että Onias oli häntä väkevämpi, meni hän Apolloniuksen, Trasein pojan, alemmaisen Syrian ja Phenikian päämiehen tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Ja sanoi hänelle, kuinka Jumalan arkku Jerusalemissa määrätöin rikas oli kullasta, ja sangen paljon liiaksi siitä mitä uhriksi tarvittiin, ja että kuningas sen kyllä sais ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Kuin nyt Apollonius tuli kuninkaan tykö, sanoi hän hänelle, mitä Simon hänelle rahasta ilmoittanut oli. Silloin määräsi kuningas kamrerinsa Heliodoruksen, ja käski hänen sen rahan tuoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Hän valmisti itsensä ja sanoi, että hän alemmaisessa Syriassa ja Phenikiassa veroa vastaan ottava oli; mutta hänen aivoituksensa oli, että hän kuninkaan käskyn toimittaa tahtoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Kuin nyt Heliodorus Jerusalemiin tuli, ja ylimmäinen pappi oli hänen ottanut ystävällisesti vastaan, jutteli hän hänelle, mitä hänen herransa hänelle käskenyt oli, ja mitä varten hän siellä oli, ja kysyi, jos niin olis taikka ei?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Niin ylimmäinen pappi vastasi: yksi osa on meidän haltuumme pantu, joka on leskein ja orpoin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Toinen on Hilkanin Tobian, joka kuuluisa mies oli. Ja ei ensinkään niin ole, kuin se pettäjä Simon sanonut on; sillä ei enempää ole kuin neljäsataa leiviskää hopiaa ja kaksisataa leiviskää kultaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Niin olis se suuri vääryys, jos se niin otettaisiin pois, ja ne, jotka kalunsa uskoneet ovat pyhään templiin, joka kaikessa maailmassa niin korkiasti kunnioitettu ja pelastettu on, tulis omaansa paitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Mutta Heliodorus piti kuninkaan käskyn, hänen piti sen ottaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Ja tuli määrättynä päivänä templiin ja tahtoi sitä nähdä. Niin nousi suuri valitus koko kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Papit olivat pyhässä kaunistuksessansa alttarin edessä ja huusivat Jumalan tykö taivaasen, joka itse käskenyt on, ettei tallelle pantua kalua tuhlattaisi; että hän niille, jotka siihen paikkaan tallelle panneet olivat, tallella pitäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Mutta ylimmäinen pappi käytti itsensä surkiasti, ettei kenkään häntä ilman armahtelemata nähdä voinut; sillä se nähtiin hänessä, koska hän niin kasvoilta muuttunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Sillä hän oli niin peräti hämmästynyt, että hän kokonansa vapisi; josta kyllä ymmärrettiin, kuinka paha hänen mielensä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Mutta kansa juoksi sinne ja tänne kokoon huoneessa ja rukoili keskenänsä; sillä he näkivät templin ylönkatsotuksi tulevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Ja vaimot pukivat säkit yllensä, juoksentelivat ympäri katuja, ja neitseet, jotka ei muutoin ihmisten seassa olleet, juoksivat porttien ja muurien päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Monikahdat olivat akkunoilla ja nostivat kaikki kätensä taivaasen päin, ja rukoilivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Molemmat olivat surkiat: että kansa niin keskenänsä hämmästyksissä oli, ja ylimmäinen pappi niin murheellinen oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 22, 'Kuin he näin kaikkivaltiasta Jumalaa rukoilivat, että hän heidän tavaransa, jotka sen sinne panneet olivat, varjelis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 23, 'Aikoi Heliodorus aivoituksensa päättää. Ja kuin hän Jumalan arkun tykönä seisoi sotaväen kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 24, 'Teki kaikkivaltias Jumala suuren ihmeen, että hän ja ne, jotka hänen ympärillänsä olivat, hämmästyivät Jumalan voimasta, ja tulivat suureen pelkoon ja vavistukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 25, 'Sillä he näkivät hyvin valmistetun hevosen, sen selässä istui hirmuinen ratsasmies, karkasi kaikella voimallansa Heliodoruksen päälle, ja löi häntä molemmilla etisillä jaloillansa, ja sillä miehellä, joka hevosen selässä oli, oli kultahaarniska päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 26, 'He näkivät myös kaksi nuorta miestä, jotka olivat väkevät ja kauniit, ja sangen jalosti vaatetetut, ne seisoivat Heliodoruksen kahden puolen, ja löivät vahvasti häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 27, 'Että hän nääntyneenä maahan putosi, ja näky katosi häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 28, 'Niin he ottivat hänen, joka äsken suuressa kunniassa ja kaiken sotaväkensä kanssa, tavarahuoneesen mennyt oli, ja kantoivat hänen sieltä pois istuimella, ja hänen voimansa ei häntä mitäkään auttanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 29, 'Että julkisesti Herran voima tuta taidettiin, ja hän oli niin kuoleman kielissä eikä yhtään sanaa puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 30, 'Mutta Juudalaiset kiittivät Jumalaa, että hän templinsä niin kunnioittanut oli. Ja templi, joka ennen pelkoa ja vavistusta täynnä oli, tuli iloa ja riemua täyteen tästä kaikkivaltiaan Jumalan ihmeestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 31, 'Mutta muutamat Heliodoruksen ystävät tulivat ja rukoilivat Oniaa rukoilemaan Herraa, että hän Heliodorukselle, joka parhaallansa viimeisessä hengen hädässä oli, elämän lainais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 32, 'Ja että ylimmäinen pappi pelkäsi pahan luulon Juudalaisista tulevan, niinkuin he olisivat Heliodorukselle jotain tehneet, uhrasi hän hänen edestänsä, että hän terveeksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 33, 'Ja kuin hän rukoili, näkyivät ne kaksi nuorta miestä jälleen entisissä vaatteissansa ja sanoivat Heliodorukselle: kiitä ylimmäistä pappia Oniaa suuresti; sillä hänen tähtenså on Herra sinulle elämän antanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 34, 'Ja ilmoita joka paikassa Herran suurta voimaa, ettäs taivaasta piesty olet. Ja kuin he sen puhuneet olivat, katosivat he.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 35, 'Mutta Heliodorus uhrasi Herralle ja kiitti häntä suuresti, että hän hänelle elämän antanut oli, ja kiitti Oniaa ja meni sitte jälleen kuninkaan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 36, 'Ja sanoi jokaiselle, kuinka hän silmillänsä korkeimman Jumalan työt nähnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 37, 'Mutta kuin kuningas kysyi häneltä, kenenkä hän lähettäis Jerusalemiin, joka jotain toimittaa taitais,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 38, 'Vastasi häntä Heliodorus: jos sinulla joku vihamies on, taikka joku, joka sinun tahtoo sysätä pois valtakunnasta, lähetä se sinne; koska se niin piestään kuin minä, ja elävänä sieltä palajaa, niin sinä hänen jälleen kyllä mahdat ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 39, 'Sillä Jumala on voimallisesti siinä paikassa, ja jonka asuinsia taivaassa on, katselee sitä ja varjelee sen, ja jotka sitä vahingoittaa tahtovat, ne hän rankaisee, ja lyö heidät kuoliaaksi. Tässä olkoon kyllä tavarahuoneesta ja Heliodoruksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 40, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Mutta Simon, joka tavaran ilmoittanut ja isänsä maan pettänyt oli, panetteli Oniaa, kuinka hän oli sen onnettomuuden matkaan saattanut, joka Heliodorukselle tapahtunut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Ja antoi hänelle syyn, että hän hankitsi herraksi maalle, joka kuitenkin kaupungille hyvää teki, ja kansallensa uskollisesti hyvää soi, ja lujasti piti Jumalan lain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Koska nyt viha ja vaino niin suuri oli, että Simonin joukko monikahtoja sentähden surmasi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Ja Onias näki, että paljo pahuutta siitä eripuraisuudesta tuleva oli, että Apollonius, alemmaisen Syrian päämies, niin kiukuitsi ja Simonin koiruutta vahvisti, meni hän kuninkaan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Ei kantamaan kansansa päälle, vaan maakunnan ja kansan hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Sillä hän näki, että jollei kuningas siihen mitään tekis, niin ei olis mahdollinen pitkältä rauhaa pitää, eikä Simonin koiruutta estää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Mutta kuin Seleukus kuollut oli, ja hallitus Antiokus Epiphanekselle tuli, pyysi Jason, Onian veli, ylimmäiseksi papiksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Ja lupasi kuninkaalle jos hän sen toimittais kolmesataa ja kuusikymmentä leiviskää hopiaa, ja muusta saaliistansa kahdeksankymmentä leiviskää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Ja päälliseksi lupasi hän myös muutoin hänelle kirjoituksella sata ja viisikymmentä leiviskää, jos hänen sallittaisiin harjoitushuoneita ja leikkihuoneita rakentaa, ja niitä Jerusalemiin Antiokuksen tavalla viedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Kuin kuningas siihen mielistyi, ja Jason pappiuden sai, harjoitti hän kohta kansaansa pakanain tavoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ja ne hyvät kunnialliset tavat, jotka vanhoilta kuninkailta asetetut olivat, pani hän peräti pois Johanneksen Eupolemin isän kautta, joka Roomiin lähetetty oli, Roomalaisten kanssa liittoa tekemään, ja hävitti vanhat kunnialliset lait, ja asetti toiset häpiälliset tavat siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Linnan alle rakensi hän harjoitushuoneet, ja sääsi, että väkevimmät nuoret miehet siellä itsiänsä harjoittelisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Ja pakanallinen meno sai niin vallan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Ettei papit enään uhrista eikä templistä lukua pitäneet, vaan juoksivat harjoitushuoneeseen ja katsoivat, kuinka pallia lyötiin ja muita koiran paria tehtiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Ja hylkäsivät niin isäinsä tavat ja pitivät pakanalliset parempana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Heidän täytyi myös sen kyllä maksaa. Sillä Jumala lähetti heidän päällensä juuri ne, joidenka perässä he niitä harjoituksia tehdä tahtoivat, rankaisemaan heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Sillä ei Jumalan sanasta pidä leikkiä tehtämän, kyllä se viimein maksetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Kuin nyt suuri harjoitus Tyrossa pidettiin ja kuningas itse läsnä oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Lähetti pahanilkinen Jason monikahtoja Antiokialaisia, niin. kuin he olisivat olleet Jerusamista, että he myös harjoituksia katselisivat, ja lähetti heidän myötänsä kolmesataa drakmaa, että siitä Herkulekselle uhrattaisiin. Mutta ne, joiden se käsketty oli, näkivät, ettei se sovelias ollut, eikä tahtoneet siihen panna, vaan johonkuhun muuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Sen tähden, vaikka hän Herkulekselle uhriksi lähettänyt oli, toimittivat he kuitenkin laivat sen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Mutta että Ptolomeus Philometor, nuori Egyptin kuningas, ensimäiset herrainpäivänsä kirjoittanut oli, lähetti Antiokus Apolloniuksen, Menestein pojan, herrainpäivilie Egyptiin. Mutta koska hän ymmärsi, ettei häntä tahdottu esimieheksi, palasi hän takaperin ja ajatteli, kuinka hän valtakuntansa rauhassa pitäis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Ja tuli Joppeen ja sieltä Jerusalemiin, ja otettiin Jasonilta ja kaupungilta kunniallisesti vastaan, ja johdatettiin sisälle tulisoitoilla ja suurella ilolla; sitte vaelsi hän jälleen Phenikiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Mutta kolmen vuoden perästä lähetti Jason Menelauksen, ennennimitetyn Simonin veljen, kuninkaalle rahaa viemään ja hänelle monikahtoja tarpeellisia asioita muistuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 24, 'Ja koska hän kuninkaan tykönä armoon tuli, liehakoitsi hän hänen edessänsä, ja saatti ylimmäisen papin viran itsellensä, ja antoi kuninkaalle kolmesataa leiviskää hopiaa enemmän kuin Jason,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 25, 'Ja tuli niin kuninkaan käskystä Jerusalemiin, ja teki, ei niinkuin ylimmäinen pappi, vaan niinkuin kiukkuinen ja tyly mies, ja niinkuin julma metsän peto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 26, 'Näin Jason, joka oli sysännyt pois virasta hänen veljensä, toisen kautta jälleen tuli siitä sysätyksi pois, ja täytyi Ammonilaisten maalle paeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 27, 'Ja Menelaus piti vallan, mutta koska ei hän sitä rahaa, jonka hän kuninkaalle luvannut oli, voinut antaa, kuin Sostratus linnan päämies häneltä sitä anoi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 28, 'Niinkuin kuningas hänen käskenyt oli; antoi kuningas heidät molemmat kutsua eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 29, 'Ja Pani Menelauksen pois, ja pani hänen veljensä Lysimakuksen hänen siaansa, ja Sostratuksen hän pani Kypriin päämieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 30, 'Kuin se niin toimitettu oli, nostivat Tarsilaiset ja Ballottilaiset kapinan, että he kuninkaan jalkavaimoiile annetut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 31, 'Niin kuningas valmisti itsensä kiiruusti kapinaa asettamaan, ja jätti siaansa päämiehen Andronikuksen linnan isännäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 32, 'Kuin Menelaus sen tietää sai, ajatteli hän tilan olevan vanhaan virkaansa päästäksensä, ja varasti monikahtoja kultakaluja kirkosta, ja antoi Andronikukselle ja monikahtoja myi Tyroon ja muihin ympäri olevaisiin kaupunkeihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 33, 'Kuin Onia sen kuuli, meni hän yhteen rauhalliseen paikkaan Daphneen, joka Antiokian edessä on, ja nuhteli häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 34, 'Mutta Menelaus tuli Andronikuksen tykö yksin, ja neuvoi häntä ottamaan Oniaa kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 35, 'Hän teki niin, ja meni hänen tykönsä ja puhui hänen kanssansa petollisesti, antoi hänelle myös kätensä ja valan, että hän olis saanut pois hänen vapaasta paikastansa; sillä hän tiesi, ettei Onia mitään hyvää häneltä toivonut. Ja kuin hän niin makeilla sanoilla vietellyt oli, pisti hän hänen kuoliaaksi, vastoin kaikkea lakia. Se ei ainoasti ollut Juudalaisten mielestä paha, mutta oli myös mielikarvaus monelle pakanoista, että hän hurskaan miehen niin petollisesti surmannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 36, 'Kuin nyt kuningas Kilikiassa kaikki toimittanut oli ja jälleen kotia vaelsi, juoksivat Juudalaiset joka kaupungissa hänen tykönänsä, ja monikahdat pakanoista, ja valittivat hänen edessänsä että Onia viatoinna murhattu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 37, 'Ja Antiokus murehti sydämestänsä, ja surkutteli, että hurskas, kunniallinen mies oli niin surkiasti pois tullut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 38, 'Ja julmistul Andronikuksen päälle, ja antoi purpuravaatteen ja muut kaunistukset hänen yltänsä riisua pois, ja hänen vietää kaiken kaupungin lävitse, ja viimein mestata siinä paikassa, kussa hän Onian pistänyt oli. Niin on hänen Jumala jälleen ansionsa jälkeen rangaissut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 39, 'Mutta kuin Lysimakus veljensä Menelauksen neuvosta paljon templistä varastanut oli, ja se oli kansan seassa ilmi tullut, kokosi kansa itsensä Lysimakusta vastaan, kuin kultaiset kalut jo olivat tulleet pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 40, 'Kuin kansa itsensä koonnut ja sangen vihoissansa oli, valmisti Lysimakus kolmetuhatta miestä, tahtoi itsensä väkivallalla varjella ja pani heidän päällensä yhden vanhan, kavalan päämiehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 41, 'Kuin kaupungin asuvaiset sen näkivät, ottivat monikahdat kiviä, monikahdat vahvat korennot, monikahdat heittivät tuhkaa silmille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 42, 'Että niin monta heistä haavoitettiin, ja monikahdat peräti maahan lyötiin, muut kaikki juoksivat sieltä pois ja ottivat kirkon ryöstäjän kiinni tavara-arkun tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 43, 'Sitte ottivat he hänen oikeuden eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 44, 'Ja että kuningas Tyroon päin tullut oli, antoivat kolme vanhimmilta lähetetyt asian tulla hänen eteensä, että hän siitä tuomitsis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 45, 'Kuin Menelaus voitettiin, lupasi hän Ptolomeukselle paljon rahaa, jos hän hänen kuninkaan tykönä vallallensa rukoilis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 46, 'Niin meni Ptolomeus yksinänsä kuninkaan tykö hänen saliinsa, jossa hän itsiänsä vilvoitteli, ja vietteli kuninkaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 47, 'Että hän Menelauksen, joka kaikkea pahuutta matkaan saattanut oli, valallensa päästi, ja ne köyhät kuolemaan tuomitsi, jotka kuitenkin Tattarienkin tykönä viattomaksi löydetty ja tunnetut olisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 48, 'Niin surmattiin viattomasti ne, jotka kansan ja templin asioita uskollisesti toimittaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 49, 'Siitä oli monikahtain mieli Tyrossa paha, ja saattoivat heidät kunniallisesti maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 50, 'Mutta Menelaus pysyi virassa monikahtain voimallisten avusta, joiden hänestä hyödytys oli, ja tuli päivä päivältä pahemmaksi, ja toimitti kaupungin asuville paljon pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 1, 'Silloin meni Antiokus toisen kerran Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 2, 'Mutta koko kaupungissa nähtiin neljäkymmentä päivää järjestänsä ilmassa ratsasmiehet kultaisissa haarniskoissa, pitkäin keihästen kanssa sodassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 3, 'Ja nähtiin, kuinka he toinen: toisensa kanssa taistelivat ja kilvillä ja kelhäillä heitänsä varjelivat, ja kuinka he miekkansa vetivät toinen toisensa päälle ampuivat, ja kuinka ne kultaiset haarniskat kilisivät, ja kuinka heillä moninaiset haarniskat olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 4, 'Silloin jokainen rukoili, ettei se mitään pahaa aavistaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 5, 'Mutta valhehuuto nousi, kuinka Antiokus piti kuolleen. Silloin otti Jason tuhannen miestä tykönsä, ja karkasi äkisti kaupungin päälle. Ja kuin hän väkinensä muurin päälle noussut oli ja kaupungin voittanut, pakeni Menelaus linnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 6, 'Mutta Jason tappoi kaupunkinsa asuvaiset surkiasti ja ei ajatellut, vaikka hänelle menestyi ystäviänsä vastaan, että se suuri onnettomuus oli, vaan ajatteli voittaneensa vihollisensa, kuin hän voitti oman kaupunkinsa asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 7, 'Ei kuitenkaan saanut hän valtakuntaa, vaan sai palkkansa, jonka hän ansainnutkin oli, ja pakeni häpiällä jälleen Amorilaisten maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 8, 'Siellä viimein kannettiin hänen päällensä Aretaan, Arabian kuninkaan edessä, että hänen kaupungista paeta täytyi, eikä kussakaan rauhaa saanut. Ja jokainen häntä vihasi niinkuin sitä, joka laistansa luopui; ja jokainen häntä kiroili, niinkuin pettäjää ja oman isänsä maan vihamiestä, ja on niin Egyptiin ajettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 9, 'Ja niinkuin hän paljon väkeä isänsä maalta oli ajanut pois, niin hänen myös itse täytyi viheliäisyydessä kuolla Lakedemoniassa, kussa hän itsensä luuli turvissa olevan, että he keskenänsä ystävät olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 10, 'Mutta niinkuin hän monta hautaamatta oli heittänyt pois, niin on hän myös kuollut, ettei kenkään häntä murehtinut, ja ei ole ainoasti niin onnetoin ollut, ettei hän omalle isänsä maalle haudatuksi tullut, mutta ei ole myös muuallakaan hautaa saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 11, 'Kuin kuningas sen kuuli, ajatteli hän Juudean peräti hänestä luopuvan, Ja meni kiukussansa Egyptistä, ja otti Jerusalemin väkivallalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 12, 'Ja käski sotamiehet kuoliaaksi lyödä ilman armoa, jotka he löysivät kaduilta ja huoneista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 13, 'Niin tapettiin yksi toisen kanssa, nuoret ja vanhat, miehet ja vaimot, lapset ja neitseet, niin myös lapset kehdossa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 14, 'Niin että kolmena päivänä teloitettiin kahdeksankymmentä tuhatta, neljäkymmentä tuhatta vangiksi otettiin ja liki kahdeksankymmentä tuhatta myytiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 15, 'Mutta ei Antiokus näihin vielä tyytynyt, vaan sattui myös kaikkein pyhimpään siaan, mikä maan päällä on; ja Menelaus pettäjä vei hänen sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 16, 'Silloin ryöväsi hän kirotuilla käsillänsä pyhät astiat, ja kaikki, mitä muut kuninkaat templiin antaneet olivat kaunistukseksi ja kunniaksi, ne tempasi hän syntisillä käsillänsä pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 17, 'Ja ylpeili suuresti, ja ei nähnyt, että Herra sen salli niille tapahtuvan, jotka kaupungissa olivat, heidän synteinsä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 18, 'Se oli syy, että Jumala pyhän paikan niin häpiällisesti toimitettaa antoi; muutoin olis Antiokukselle niin tapahtunut kuin Heliodoruksellekin, joka kuningas Seleukselta lähetettiin tavara-arkkua katsomaan, ja sentähden hyvin hosuttiin, että hänen täytyi ylpiästä aivoituksestansa lakata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 19, 'Sillä ei Jumala ole kansaa valinnut paikan tähden, vaan paikan kansan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 20, 'Sentähden pyhä templi myös kärsi, kuin kansaa rangaistiin, niinkuin se myös kansan kanssa sitte hyvää nautitsi. Sillä niinkuin templi vihollisilta voitettiin, kuin Herra vihastui, niin on se tullut jälleen kunniaan ja toimeen, kuin Herra heille jälleen leppyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 21, 'Mutta luku kaikista, mitä Antiokus templistä ottanut oli, on kahdeksan toistakymmentä sataa leiviskää hopiaa: ne hän otti myötänsä, ja meni kohta Antiokiaan senkaltaisella koreudella ja ylpeydella, että hän ajatteli maan tehdä purjehdittavaksi niinkuin meren, ja meren vaellettavaksi niinkuin maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 22, 'Ja jätti Jerusalemiin peräänsä muutamia virkamiehiä, häijyjä koiranparisia: Philippuksen Phrygiasta, joka vielä pahempi ja hullumpi oli kuin hänen isäntänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 23, 'Garitsimiin Andronikuksen, ja molempain heidän kanssansa Menelauksen, joka vielä pahempi oli kuin kaikki muut vaivaamaan omaa kansaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 24, 'Että Antiokns Juudalaisia niin peräti vihasi, lähetti hän heille häpeemättömän, pahanilkisen Apolloniuksen kahdellatuhannella kolmattakymmentä miehellä maalle, ja käski hänen kaikki kasvaneet miehet tappaa, mutta vaimot ja nuoren väen myydä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 25, 'Kuin hän Jerusalemin eteen tuli, teeskeli hän itsensä rauhalliseksi sabbatin päivään asti, jona Juudalaiset pyhää pitävät: silloin käski hän väkensä nopiasti valmistaa itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 26, 'Kuin nyt jokainen juoksi katsomaan, mitä tapahtuman piti, antoi hän kaikki ne pistää lävitse, ja tuli niin koko joukon kanssa kaupunkiin, ja tappoi sangen paljon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 5, 27, 'Mutta Juudas Makkabealainen pakeni sieltä yhdeksän veljensä kanssa korpeen vuorelle. ja eli siellä kaikkein kanssa, jotka hänen tykönsä tulleet olivat, ruohoilla, ettei hän olisi saastainen pakanain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 1, 'Mutta vähän ajan perästä lähetti kuningas vanhan miehen Antiokiasta, vaatimaan Juudalaisia luopumaan isäinsä laista, ja ettei he Jumalan laista enään mitään pitäisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 2, 'Ja että hän Jerusalemin templin saastuttais, ja kutsuis sen Jovis Olympiuksen kirkoksi, ja Garitsimin templin Jovis Kseniuksen kirkoksi, että muukalainen väki siellä asui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 3, 'Mutta senkaltainen surkia meno teki jokaiselle sangen pahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 4, 'Sillä pakanat söivät ja joivat templissä, ja tekivät kaikkinaista häpiällistä menoa vaimoin kanssa pyhässä siassa, ja veivät paljon sisälle, joita ei pitänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 5, 'Alttarilla uhrattiin laissa kiellettyjä uhreja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 6, 'Ja ei pidetty sabbatia eikä entisiä juhlia; eikä yksikään uskaltanut ilmoittaa itsiänsä Juudalaiseksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 7, 'Vaan he vaadittiin väkivallalla joka kuukausi uhraamaan, kuin kuninkaan syntymäpäivä oli. Mutta kuin Bakkuksen päivää pidettiin, silloin vaadittiin Juudalaiset käymään viheriäisillä seppeleillä Bakkuksen kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 8, 'Oli myös Ptolomeuksen neuvosta käsky annettu pakanain kaupunkeihin, jotka Jerusalemin ympärillä olivat, että heidän piti vaatiman Juudalaisia joka paikassa uhraamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 9, 'Ja jos monikahdat lujana pysyivät, ettei he pakanain kanssa pitää tahtoneet, ne kohta piti tapettaman. Siinä nähtiin suuri surkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 10, 'Kaksi vaimoa tuotiin edes, että he poikansa ympärileikanneet olivat; niiden rintoihin sidottiin lapsukaiset, ja vietiin ympäri kaiken kaupungin, ja heitettiin viimein muurin ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 11, 'Muutamat olivat yöllä itsensä lymyttäneet luoliin, että he olisivat sabbatia pitäneet: ne, (kuin Philippus sen tietää sai), poltettiin; sillä ei he tahtoneet itsiänsä varjella, ettei he sabbatia rikkoneet olisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 12, 'Mutta minä neuvon lukiaa, ettei hän pahentuisi tästä surkeudesta, vaan muistais, ettei se rangaistus tapahtunut heille kadotukseksi, vaan meille karttamiseksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 13, 'Sillä se on suuri armo, kuin Jumala syntisiä estää, ettei heille aina menesty, ja on kohta heidän tykönänsä rankaisemassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 14, 'Sillä meidän Herra Jumala ei kärsi meitä niin kauvan kuin muita pakanoita, jotka hän antaa mennä siihen asti kuin he syntinsä mitan täyttäneet ovat, että hän heitä sitte rankaisis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 15, 'Vaan estää meitä, ettemme aivan paljon tekisi, ja hän viimein meille kostais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 16, 'Sentähden ei ikänä hän peräti meiltä armoansa ole ottanut pois; ja vähän meitä onnettomuudella kurittanut on, ei hän kuitenkaan kansaansa peräti hyljännyt ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 17, 'Tämän minä olen tässä neuvoksi sanoa tahtonut. Nyt me jälleen palajamme historiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 18, 'Oli yksi erinomainen kirjanoppinut, Eleatsar, vanha ja kuitenkin kaunis mies; sen suun he väkivallalla avasivat, että hän söis sian lihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 19, 'Mutta hän tahtoi ennen kunnialla kuolla kuin häpiällä elää, ja kärsi sen kärsivällisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 20, 'Ja kuin hän vaivattavaksi vietiin, nuhteli hän niitä, jotka kiellettyä lihaa söivät tämän elämän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 21, 'Mutta ne, jotka asetetut olivat kansaa vaatimaan vastoin lakia sian lihaa syömään, että he niin kauvan hänen tunteneet olivat, ottivat he hänen yhteen paikkaan, ja sanoivat tahtovansa tuoda hänelle lihaa, jota hän syödä tohtis, vaan hän teeskelis, niinkuin se olis uhrattu sian liha, ja söis kuninkaan mielen nouteeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 22, 'Että hän niin henkensä pitäis, ja nautitsis vanhaa ystävyyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 23, 'Mutta hän ajatteli, kuinka se hänen vanhalle ijällensä ja harmaalle päällensä, niin myös hänen kunnialliselle elämällensä hamasta nuoruudesta, kuin myös Jumalan pyhälle laille sovelias oli, ja sanoi rohkiasti: lähettäkäät minua maan alle hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 24, 'Sillä se sopis pahoin minun vanhalle ijälleni, että minä niin teeskelisin, että nuoret ajattelisivat: Eleatsar, joka yhdeksänkymmenen ajastaikainen oli, on myös pakanaksi tullut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 25, 'Ja he niin minun teeskelemiseni kautta vieteltäisiin, että minä itseni ihmisten edessä niin laittaisin, ja minun elämäni, niin piskuiseksi ajaksi kuin minulla vielä elämistä on, niin pelastaisin: se olis minulle ijankaikkinen häpiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 26, 'Ja mitä minun siitä olis, vaikka minä nyt ihmisten rangaistuksen välttäisin, koska en minä, Jumalan käsiä elävänä taikka kuolleena välttää taida?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 27, 'Sentähden tahdon minä nyt iloisesti kuolla, niinkuin minun, vanhan miehen, sopii,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 28, 'Ja nuorille jättää hyvän esimerkin minun jälkeeni, että he mielellänsä ja iloisesti kunniallisen ja pyhän lain tähden kuolisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 29, 'Kuin hän nämät sanat puhunut oli, vietiin hän vaivattavaksi. Mutta ne, jotka häntä johdattivat ja ennen hänen ystävänsä olleet olivat, julmistuivat hänen päällensä niiden sanain tähden; sillä he luulivat hänen kiusalla sanoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 30, 'Mutta kuin he häntä lyöneet olivat, että hänen jo kuoleman piti, huokasi hän ja sanoi: se Herra, jolta ei mitään salattu ole, tietää, että minä ne haavat ja suuren kivun, jotka minä minun ruumiissani kärsin, olisin kyllä välttää taitanut, jos minä tahtonut olisin, mutta sielun puolesta kärsin minä mielelläni Jumalan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 6, 31, 'Ja niin hän täältä erkani ja kuolemallansa lohdullisen esimerkin jälkeensä jätti, ettei se ainoasti nuoria, vaan jokaista kunniallisuuteen neuvoman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 1, 'Otettiin myös seitsemän veljestä äitinsä kanssa vangiksi, ja ruoskilla ja nauhoilla piestiin, ja vaadittiin kuninkaalta sianlihaa syömään, joka heiltä laissa kielletty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 2, 'Niin sanoi vanhin heistä: mitäs paljon kysyä tahdot, ja meiltä tietää? Me tahdomme ennen kuolla, kuin jotain tehdä meidän isäimme lakia vastoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 3, 'Silloin julmistui kuningas ja käski nopiasti panna pannut ja kattilat tulelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 4, 'Kuin se tehty oli, käski hän vanhimmalta leikata pois kielen, ja hakata pois kädet ja jalat, että muut veljet ja äidin näkemän piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 5, 'Kuin hän nyt näin raajarikoksi tehty oli, antoi hän hänen tuleen viedä ja pannussa paistaa. Ja kuin liekki joka paikasta pannuun löi, neuvoivat he toinen toistansa keskenänsä äitinsä kanssa, että he rohkiasti kuolisivat, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 6, 'Herra Jumala kyllä näkee oikeuden, ja on meille armollinen, niinkuin Moses virressänsä todistaa, ja on palvelioillensa armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 7, 'Kuin ensimäinen niin erinnyt oli, vietiin myös toinen sinne, että he koiruutensa hänelle näyttäisivät, ja vetivät häneltä nahan ja hiukset pois päästä, ja kysyivät häneltä, jos hän sian lihaa syödä tahtois, eli kaiken ruumiin kaikkein jäsentensä kanssa vaivattavaksi antaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 8, 'Hän vastasi kielellänsä ja sanoi: en minä sitä tee! Niin he ottivat hänen ja vaivasivat häntä niinkuin ensimäistäkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 9, 'Kuin hän viimeisessä hengen riutumassa oli, sanoi hän: sinä kirottu ihminen otat minulta tosin tämän ajallisen elämän, vaan kaiken maailman Herra herättää meidät, jotka hänen lakinsa tähden kuolemme, ijankaikkiseen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 10, 'Sitte ottivat he kolmannen, ja tekivät myös koiruuttansa hänelle. Ja kuin he häneltä sitä vaativat, lykkäsi hän kielensä rohkiasti ulos, ja ojensi kätensä, ja sanoi rohkiasti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 11, 'Nämät jäsenet Jumala taivaasta on minulle antanut, sentähden annan minä ne mielelläni otettaa hänen lakinsa tähden; sillä minä toivon, että hän ne minulle antaa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 12, 'Mutta kuningas ja hänen palveliansa ihmettelivät, että nuorukainen niin rohkia oli, eikä kipua mitään totellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 13, 'Kuin tämä myös kuollut oli, piinasivat he myös neljättä, ja ruoskivat hänen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 14, 'Mutta kuin hänen jo kuoleman piti, sanoi hän: se on suuri lohdutus, että me toivomme, kuin ihmiset meitä surmaavat, että Jumala meidän herättää jälleen: mutta et sinä herätetä elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 15, 'Senjälkeen ottivat he viidennen, ja ruoskivat myös hänen. Se katsoi Antirykuksen päälle, ja sanoi hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 16, 'Sinä olet ihminen, ja sinun täytyy kuolla. Mutta ettäs maan päällä voimallinen olet, niin sinä teet, mitäs tahdot. Mutta et sinä sitä mahda ajatella, että Jumala meidät peräti hyljännyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 17, 'Odota vähä aika, niin sinä saat ymmärtää, kuinka väkevä Jumala on, joka sinun ja sinun sukus rankaisee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 18, 'Tämän perästä vietiin myös kuudes edes, joka myös sanoi, kuin hänen jo kuoleman piti: et sinä minua niin petä; sillä me olemme tämän piinan kyllä ansainneet siinä että me olemme tehneet syntiä meidän Jumalaamme vastaan ja hän tekee hirmuisesti meille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 19, 'Mutta et sinä niin pääse, ettäs kiukuitset Jumalaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 20, 'Mutta se oli suuri ihme äidissä, ja on senkaltainen esimerkki kyllä mahdollinen hänestä kirjoitettaa; sillä hän näki kaikki seitsemän poikaansa yhtenä päivänä toinen toisensa perästä piinattavan, ja kärsi sen suurella kärsivällisyydellä, sen toivon tähden, joka hänellä oli Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 21, 'Siitä tuli hän niin rohkiaksi, että hän poikiansa yhtä toisen perään kielellänsä lohdutti, ja sai urhoollisen sydämen, ja sanoi heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 22, 'Minä olen teidän äitinne, ja olen teidät synnyttänyt, mutta henkeä ja elämää en ole minä teille antanut, enkä teidän jäseniänne niin tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 23, 'Sen tähden se, joka maailman ja kaikki ihmiset luonut on, antaa teille hengen ja elämän jälleen., niinkuin te nyt hänen lakinsa tähden sen vaaraan ja alttiiksi annatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 24, 'Kuin Antonius sen kuuli, luuli hän äidin katsovan ylön häntä ja pilkkaavan kielellänsä, ja otti nuorimman pojan eteensä, joka vielä jäänyt oli, ja neuvoi häntä hyvillä sanoilla, ja puhui hänen kanssansa valalla vannoin, jos hän isänsä laista luopua tahtois, niin löytäis hän hänestä armollisen herran, joka tekis hänen rikkaaksi ja herraksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 25, 'Mutta kuin ei se tahtonut antaa vietellä itsiänsä, antoi kuningas äidin eteensä tulla, ja neuvoi häntä poikaansa niin neuvomaan, että hän hengissä pysyis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 26, 'Kuin hän häntä monilla sanoilla rukoillut oli, lupasi hän sen tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 27, 'Mutta hän pilkkasl ainoasti tyrannia; sillä hän meni poikansa tykö, ja puhui salaa kielellänsä hänen kanssansa ja sanoi: sinä, minun rakas lapseni, jota minä yhdeksän kuukautta sydämeni alla kantanut olen, ja kolme ajastaikaa imettänyt olen, ja suurella vaivalla kasvattanut, armahda siis minun päälleni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 28, 'Katso taivasta ja maata ja kaikkia mitä niissä on: nämät kaikki on Jumala tyhjästä tehnyt, ja me ihmiset olemme myös niin tehdyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 29, 'Sen tähden älä pelkää murhaajaa, vaan kuole mielelläs, niinkuin veljeskin, että armollinen Jumala veljeis kanssa tekis sinun eläväksi jälleen, ja antais minulle jälleen. Hebr. 11: 35.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 30, 'Kuin Äiti vielä poikansa kanssa näin puhui, sanoi nuorukainen: mitä te odotatte? Älkäät sitä ajatelko, että minä tyrannille tässä kuuliainen olen, vaan minä tahdon lain pitää, joka meidän isillemme Moseksen kautta annettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 31, 'Mutta sinä, joka Juudalaisille kaikkea pahaa teet, et pääse niin Herralta meidän Jumalaltamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 32, 'Me kärsimme meidän synteimme tähden, se on tosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 33, 'Ja vaikka elävä Jumala hetken aikaa meidän päällemme vihainen on, ja meitä rankaisee ja kurittaa, niin kuitenkin hän palvelioillensa armollinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 34, 'Mutta sinä jumalatoin, kirottu ihminen! älä vallastas paljon ylpeile, ja älä luota turhan toivon päälle, ettäs Jumalan lapsia vainoot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 35, 'Sillä et sinä ole vielä kaikkivaltiaan Jumalan tuomioita, joka kaikki näkee, välttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 36, 'Minun veljeni, jotka vähän aikaa itsiänsä piinattaa antoivat, he odottavat nyt ijankalkkista elämää Jumalan lupauksen jälkeen, mutta sinun pitää Jumalan tuomion jälkeen rangaistuksi tuleman, niinkuin sinä ylpeydelläs ansainnut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 37, 'Minä tahdon ruumiini ja henkeni minun isäini lain tähden antaa niinkuin veljenikin, ja Jumalan tykö huutaa, että hän pian kansallensa armollinen olis; mutta sinun täytyy vielä tunnustaa suuren piinan ja vaivan kautta, että hän ainoasti oikia Jumala on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 38, 'Mutta Jumalan viha minussa ja minun veljissäni lakkaa, joka oikiasta syystä on tullut koko meidän kansamme päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 39, 'Kuin kuningas sen kuuli, tuli hän hulluksi ja kiukkuun, ja antoi häntä vielä kovemmin piinata kuin muita, sillä se oli hänelle ylönkatse, että he vielä häntä pilkkasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 40, 'Niin myös tämä kauniisti kuoli, ja on kaiken turvansa pannut Jumalan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 41, 'Viimeiseltä myös äiti mestattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 7, 42, 'Niin paljon olkoon kyllä pakanallisista uhreista ja hirmuisesta piinasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 1, 'Mutta Juudas Makkabealainen ja hänen kumppaninsa menivät salaa sieltä ja täältä kyliin, ja huusivat kokoon lankonsa, ja jotka muutoin Juudalaisten uskossa pysyneet olivat, että hän lähes kuusituhatta miestä kokoon sai.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 2, 'Ja he rukoilivat Jumalaa, katsomaan köyhän kansan puoleen, joka jokaiselta vaivattu oli, ja armahtamaan templiä, jonka jumalattomat ihmiset saastuttaneet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 3, 'Ja turmeltua kaupunkia, joka peräti autiona oli: että hän kuitenkin viatointa verta, joka hänen tykönsä huutaa, kuulis:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 4, 'Ja viattomia lapsia, jotka vastoin kaikkea oikeutta pistettiin lävitse, muistais ja kostais nimensä pilkan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 5, 'Ja Makkabealainen joukkoinensa vaivasi pakanoita jalosti; sillä Herra lakkasi vihastansa, ja oli heille taas armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 6, 'Hän karkasi tietämättä kaupunkein ja kyläin päälle, ja sytytti ne, ja voitti ne soveliaammat paikat, ja teki vihollisille suuren vahingon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 7, 'Mutta enimmästi teki hän ne yöllä, että hänen töistänsä leviältä puhuttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 8, 'Mutta kuin Philippus näki, että hän enemmin ja enemmin väkevämmäksi tuli, ja että hän niin menestyi, kirjoitti hän Ptolomeuksen, alemmaisen Syrian ja Phenikian päämiehen tykö, apua anoin kuninkaalle hyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 9, 'Silloin lähetti Ptolomeus parhaan ystävänsä, Nikanorin Patroklin pojan, kahdellakymmenellä tuhannella miehellä Juudalaisia peräti hävittämään, ja antoi hänelle päämiehen kanssansa, Gorgiaan nimeltä, joka hyvin harjaantunut sotamies oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 10, 'Mutta Nikanor ajatteli, että hän vangituista Juudalaisista sen rahan tahtoi saada, jonka kuninkaan vuosi vuodelta piti antaman Roomalaisille, nimittäin kaksituhatta leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 11, 'Sentähden lähetti hän kohta sinne ja tänne kaupunkeihin meren tykö, ja antoi kuuluttaa, kuinka hän Juudalaisia myydä tahtoi, yhdeksänkymmentä yhteen leiviskään; sillä ei hän luullut rangaistusta Jumalalta niin läsnä olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 12, 'Kuin Juudas kuuli siitä joukosta, joka Nikanorilla oli, sanoi hän Juudalaisille, jotka hänen tykönänsä olivat, että sotajoukko tuleva oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 13, 'Jotka pelkurit olivat, ja ei ollut sitä uskallusta Jumalan tykö, että hän rankaiseva oli, ne juoksivat sieltä ja pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 14, 'Mutta ne muut myivät kaikki, mitä heillä oli, ja rukoilivat Herraa, että hän pelastais ne, jotka Nikanor myynyt oli, ennen kuin hän heidät vangiksi saanut oli..');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 15, 'Ja vaikka ei hän sitä heidän tähtensä tekisi, että hän kuitenkin tekis sen liiton tähden, jonka hän heidän isäinsä kanssa tehnyt oli, ja kuuluisan suuren nimensä tähden, jonka jälkeen he nimitetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 16, 'Kuin nyt Makkabealainen väkensä oli koonnut, liki kuusituhatta miestä, neuvoi hän heitä ensisti, ettei he hämmästyisi vihollisia, eikä pelkäisi pakanain paljoutta, jotka heitä, vastoin oikeutta, vääryydellä vaivasivat, vaan varjelisivat itsensä miehullisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 17, 'Ja muistaisivat sitä pilkkaa, jonka he pyhälle kaupungille tehneet olivat, ja kuinka he kaupungin häväisseet ja vaivanneet ja lain pois panneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 18, 'He luottavat (sanoi hän) haarniskoihinsa, ja ovat täynnä uhkausta, mutta me luotamme meidän kaikkivaltiaan Jumalamme päälle, joka taitaa ei ainoasti yhdessä silmänräpäyksessä niitä, jotka nyt tulevat meitä vastaan, mutta myös koko maailman ylösalaisin kukistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 19, 'Hän luetteli myös heille kaikki historiat, kuinka Jumala niin usein armollisesti heidän isiänsä auttanut oli; kuinka Sennaheribin alla sata viisiyhdeksättäkymmentä tuhatta miestä yhtenä yönä lyötiin maahan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 20, 'Kuinka siinä tappeluksessa Babelissa oli käynyt Galatalaisia vastaan, koska he kaikki suureen tuskaan joutuneet olivat, kahdeksantuhatta Juudalaista ja neljätuhatta Makedonialaista, kuinka Makedonialaiset pelvosta alallansa olivat, ja ne kahdeksantuhatta Juudalaista, ainoasti Jumalan avulla, sata ja kaksikymmentä tuhatta miestä lyöneet ja suuren tavaran sen kautta saaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 21, 'Kuin hän tämänkaltaisilla sanoilla heidän sydäntänsä rohkaissut oli, että he lain ja isänsä maan edestä mielellänsä kuolisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 22, 'Teki hän neljä joukkoa, ja asetti veljensä ensimäiseksi rintasotaan, että he sen johdattaisivat, nimittäin Simonin, Josephin ja Jonatanin, ja antoi kullekin viisitoistakymmentä sataa miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 23, 'Sitte antoi hän Eleatsarin pyhää kirjaa lukea, ja antoi heille merkin, että heitä Jumala auttava oli, ja meni niin muiden edellä sotaan ja otti yhteen Nikanorin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 24, 'Mutta kaikkivaltias Jumala autti heitä, että he koko joukon pakoon löivät, ja haavoittivat monta, ja tappoivat liki yhdeksäntuhatta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 25, 'Ja ajoivat niitä takaa, jotka Juudalaisia ostamaan tulleet olivat, ja ottivat heidän rahansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 26, 'Kuitenkin heidän täytyi palata; sillä se oli sabbatin ehtoo, se oli syy, että he lakkasivat heitä ajamasta takaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 27, 'Sitte he ottivat saaliin, ja ottivat haarniskat ja sota-aseet ja pitivät sabbatin, ja ylistivät ja kiittivät Jumalaa, joka heidät sinä päivänä pelastanut oli, ja jälleen ruvennut armonsa heille osoittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 28, 'Sabbatin päivän jälkeen jakoivat he saaliin vaivaisille, leskille ja orvoille, ja liian pitivät he itsellensä ja lapsillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 29, 'Ja he pitivät yhteiset rukoukset, että laupias Jumala vihansa peräti heistä kääntäis pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 30, 'Sitte tappelivat he usein Timoteuksen ja Bakkideksen kanssa, ja löivät enemmän kuin kaksikymmentä tuhatta miestä, ja voittivat linnat, jakoivat saaliin tasan välillänsä, ja maan kulkiain, orpoin, leskein ja vanhain välillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 31, 'Ja kuin he saaliin ottaneet olivat, veivät he sota-aseet linnoihin, ja veivät suuren saaliin Jerusalemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 32, 'Ja tappoivat yhden päämiehen Timoteuksen puolelta, jumalattoman miehen, joka Juudalaisia sangen kovin vaivannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 33, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 34, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 35, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 8, 36, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 1, 'Juuri siihen aikaan täytyi Antiokuksen Persiasta häpiällä mennä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 2, 'Sillä kuin hän Persepoliin mennyt oli, ja oli siellä ruvennut kirkkoa ryöstämään ja kaupunkia voittamaan, nousivat sen asuvaiset ylös, ja varjelivat itsensä, ja ajoivat Antiokuksen takaperin, että hänen häpiällä täytyi mennä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 3, 'Kuin hän Ekbatanassa oli, sai hän kuulla, kuinka Nikanorin ja Timoteuksen käynyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 4, 'Niin hän julmistui ja aikoi Juudalaisille sen häpiän kostaa, ja vaelsi päivät ja yöt, että hän pian olis sinne joutunut; sillä Jumalan viha vaati häntä, sillä hän oli niin ylpiästi puhunut, että niin pian kuin hän Jerusalemiin tulis, hän tahtois kaupungista kuolleiden haudan tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 5, 'Sen tähden rankaisi hänen kaikkivaltias Herra, Israelin Jumala, salaisella rangaistuksella, jota ei kenkään parantaa taitanut. Sillä niin pian kuin hän sen puhunut oli, tuli hänelle senkaltainen vatsatauti ja niin suuri kipu suoliinsa, ettei häntä auttaa taidettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 6, 'Ja tosin hänelle tapahtui juuri oikein, että hän muita moninaisilla ja ennen kuulumattomilla piinoilla vaivannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 7, 'Ei hän kuitenkaan luopunut ylpeydestänsä, vaan tuli kiukkuisemmaksi, ja paloi pahuudesta Juudalaisia vastaan, ja kiiruhti. ja ajaissansa putosi hän vaunuista niin kovin, että kaikki hänen jäsenensä kipiät olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 8, 'Silloin täytyi hänen (joka ennen suuresta ylpeydestä luuli taitavansa meren aallot hallita ja vuoret toinen toisensa päälle panna) antaa yhdestä ainoasta lankeemisesta hänensä kannettaa paarein päällä, että jokainen ilmeisesti näki hänessä Jumalan voiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 9, 'Kasvoivat myös madot siitä kirotusta ruumiista, ja hänen lihansa mätäni suurella kivulla, että koko kappaleet hänen ruumiistansa putosivat, ja haisi niin pahoin, ettei kenkään sitä kärsiä voinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 10, 'Ja joka ennen ajatteli taivaan liikuttavansa, sitä ei kenkään kantaa taitanut sen kärsimättömän hajun tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 11, 'Silloin hänen täytyi ylpeydestänsä lakata ja tuta, että häneen Jumala niin ruvennut oli, ja kipu aina eneni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 12, 'Ja kuin hän itse viimeiseltä, sitä hajua ei enään kärsiä voinut, niin hän sanoi: se on oikein, että ihminen Jumalan edessä nöyryyttää itsensä, ja ettei kuolevainen ihminen niin röyhkeä olisi, että hän itsensä luulis Jumalan kaltaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 13, 'Ja se pahanilkinen rupesi rukoilemaan Herraa, joka ei silleen tahtonut armahtaa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 14, 'Ja lupasi pyhän kaupungin vapaaksi tehdä, jonka hän ennen hävittää aikoi ja kuolleiden haudaksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 15, 'Ja Juudalaiset, joita ei hän ennen kelvolliseksi lukenut haudattaa, vaan linnuille ja pedoille syödä antaa, ne hän tahtoi vapaaksi tehdä niinkuin Atenankin asuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 16, 'Ja pyhän templin, jonka hän ennen ryöstänyt oli, tahtoi hän kaikkinaisella kaunistuksella kaunistaa jälleen, ja paljoa enempi pyhiä kaluja sinne antaa kuin siellä ennen ollut oli; ja mitä vuosi vuodelta uhriin menemän piti, sen tahtoi hän omastansa antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 17, 'Niin myös itse tahtoi Juudalaiseksl tulla, ja joka paikassa Jumalan voimaa kiittää ja julistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 18, 'Mutta että tauti ei tahtonut luopua hänestä, sillä Jumalan vanhurskas viha oli tullut raskaasti hänen päällensä, epäili hän hengestänsä, ja kirjoitti tämän nöyrän kirjan Juudalaisten tykö, joka seuraa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 19, 'Antiokus kuningas ja ruhtinas taritsee jumalisille Juudalaisille tervehdystänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 20, 'Jos te lapsinenne raittiina ja terveinä olette, ja teidän käy hyvin, siitä minä kiitän Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 21, 'Vaan minä olen sangen kovin klpiä. Että minä mielelläni tahtoisin yhteisen rauhan pitää, niinkuin tarve myös vaatii; sitte kuin minä Persian tiellä kipiäksi tulin, olen minä armollisesti ajatellut teidän uskollisuutenne ja ystävyytenne päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 22, 'Ehkä minä toivon itseni paranevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 23, 'Ja niinkuin minun isäni, kuin hän ylimmäisiin maakuntiin meni, teki kuninkaan peräänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 24, 'Että tiedettämän piti, (jos jotakin olis tapahtunut, eli muutoin riita noussut) kuka olis herra ollut, ja ettei valtakunta olis hajoitettu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 25, 'Niin myös minä, että minä näen, kuinka ympäriasuvaiset päämiehet minun valtakuntaani himoitsevat, jos minun pahoin kävis, olen minun poikani Antiokuksen kuninkaaksi tehnyt, jonka minä usein teille kuuluttanut olen, kuin minä ylimmäisiin maakuntiin vaelsin, sen minä myös nyt teille kuulutan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 26, 'Sen tähden minä neuvon ja rukoilen teitä kaikkein hyväin töiden tähden, joita minä kaikille yhteisesti ja erinomaisesti itsekullekin osoittanut olen, että te minulle ja minun pojalleni tästälähin ystävälliset ja uskolliset olisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 27, 'Sillä minä toivon hänen ystävällisen ja armollisen teille olevan, ja minun tapaani seuraavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 28, 'Niin kuoli murhaaja ja Jumalan pilkkaaja Antiokus suuressa kivussa, niinkuin hän muille tehnyt oli, muukalaisella maalla ja korvessa, surkialla kuolemalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 9, 29, 'Ja Philippus, joka hänen kanssansa kasvatettu oli, saatti hänen maahan, ja että hän Antiokuksen poikaa pelkäsi, pakeni hän Egyptiin kuningas Ptolomeus Philometorin tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 1, 'Niin antoi Jumala Makkabealaiselle ja hänen joukollensa rohkeuden, että he templin ja kaupungin voittivat jälleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 2, 'Ja kukistivat ne muut alttarit ja kirkot, jotka pakanat sinne ja tänne kaduille rakentaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 3, 'Ja sittekuin he templin puhdistaneet olivat, tekivät he toisen alttarin, ja ottivat limpsiötä ja iskivät valkian, ja uhrasivat taas, joka ei kahdessa ajastajassa ja kuudessa kuukaudessa tapahtunut ollut, ja uhrasivat suitsutusta, ja sytyttivät lamput, ja panivat näkyleivät edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 4, 'Kuin nämät kaikki tapahtuneet olivat, lankesivat he kasvoillensa maahan Herran eteen, ja rukoilivat, ettei hän heitä enää senkaltaiseen tuskaan tulla antaisi; vaan jos he enempi olivat syntiä tekevät häntä vastaan, että hän itse heitä armollisesti rankaisis, eikä antais heitä Jumalan pilkkaajain ja julmain pakanain käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 5, 'Ja Jumala laitti sen niin, että sinä päivänä templi puhdistettiin, jona pakanat sen saastuttaneet olivat, viidentenä päivänä kolmattakymmentä Kasleun kuusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 6, 'Ja he pitivät ilolla kahdeksan päivää pyhää, niinkuin lehtimajan juhlaa, ja ajattelivat sitä, kuin he ennen vähää aikaa lehtimajan juhlansa korvessa ja luolissa, niinkuin metsän pedot, pitäneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 7, 'Ja kantoivat kukkasia ja viheriäisiä oksia ja palmuja, ja kiittivät Jumalaa, joka heille voiton antanut oli hänen templiänsä puhdistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 8, 'He antoivat myös käskyn kaikille Juudalaisille, että se päivä vuosi vuodelta pyhitettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 9, 'Ja näin on Antiokus Epiphaneksesta loppu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 10, 'Nyt seuraa Antiokus Eupatorista, jumalattoman Antiokuksen pojasta, mitä sotaa hänen ajallansa alati ollut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 11, 'Kuin Eupator kuninkaaksi tuli, pani hän Lysiaan, joka ennen päämies Phenikiassa ja Koilosyriassa oli, yllmmäiseksi ruhtinaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 12, 'Mutta Ptolomeus Makron, joka mielellänsä Juudalaiset olis oikeudella varjellut, että he siihen asti niin paljon väkivaltaa ja vääryyttä kärsineet olivat, ahkeroitsi siitä, että heidän piti saaman rauhassa olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 13, 'Sentähden kantoivat hänen ystävänsä hänen päällensä Eupatorin edessä, ja kutsuivat hänen julkisesti pettäjäksi, että hän Kyprin luodon, jonka Philometor hänen haltuunsa antoi, Antiokus Epiphanekselle antanut oli; ja niin täytyi hänen halvimmassa virassa olla. Ja hän murehti niin kovin, että hän itsensä myrkyllä surmasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 14, 'Kuin Gorgias näiden paikkain päämieheksi tuli, otti hän sotaväkeä, Ja asetti itsensä erinomaisesti Juudalaisia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 15, 'Sitä myös rupesivat Edomealaiset tekemään, kussa he voivat, ajoivat Juudalaiset pois linnoista ja soveliaista kylistä, ja ottivat tykönsä luopuneet Juudalaiset, jotka olivat ajetut pois Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 16, 'Silloin tuli kokoon Makkabealainen ja hänen joukkonsa ja rukoilivat, että Jumala heitä auttais,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 17, 'Ja karkasivat Edomealaisten päälle vahvoihin kaupunkeihin, ja ottivat heidät väkivallalla, surmasivat kaikki, mitä muurin päällä heitä vastassa oli, ja mitä he muutoin käsittivät, kahteenkymmeneen tuhanteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 18, 'Mutta heiltä pääsi kahteen vahvaan torniin yhdeksän tuhatta, jotka itsensä olivat varustaneet päällekarkausta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 19, 'Silloin asetti Makkabealainen Simonin, Josephin ja Zakeuksen, ja antoi heille niin paljon väkeä, että he väkevät kyllä olivat karkaamaan päälle; mutta itse meni hän edemmä muiden kaupunkien eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 20, 'Mutta Simonin joukko antoi itsensä vietellä rahalla niiltä, jotka tornissa olivat, ja ottivat viisineljättäkymmentä tuhatta kultapenninkiä niiltä, ja päästivät heidät sieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 21, 'Kun Makkabealainen sen tietää sai, kutsui hän kokoon päämiehet, ja kantoi heidän päällensä, että he veljensä olivat rahaan myyneet, ja vihamiehet sieltä päästäneet pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 22, 'Ja antoi tappaa heidät niinkuin pettäjät, ja karkasi kohta niiden kahden toruin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 23, 'Ja hänelle menestyi, ja surmasi niissä kahdessa linnassa enempi kuin kaksikymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 24, 'Mutta Timoteus, jonka Juudalaiset ennen lyöneet olivat, valmisti itsensä paljolla muukalaisella väellä, ja kokosi suuren joukon hevosmiehiä Asiasta, ja tuli sillä ajatuksella, että hän Juudalaiset peräti hävittäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 25, 'Ja kuin hän maalle tuli, rukoili Makkabealainen ja hänen joukkonsa Herraa, ja panivat tuhkaa päittensä päälle, ja pukivat säkit yllensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 26, 'Ja lankesivat maahan alttarin eteen, ja rukoilivat, että Jumala heille armollinen ja heidän vihollisillensa armotoin olis, ja asettais itsensä niitä vastaan, jotka itsensä asettavat häntä vastaan, niinkuin laissa kirjoitettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 27, 'Kuin he nyt näin rukoilleet olivat, ottivat he aseensa, ja menivät hyvän matkan ulos, kaupungin eteen, siihenasti että he vihollisten tykö tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 28, 'Ja niin pian kuin aurinko nousi, tappelivat he, vaikka ei se yhtäläinen joukko ollut; sillä Juudalaisilla oli hyvä turva Jumalan tykö, (joka vahva voiton merkki on), ne toiset olivat alkaneet sodan ainoastansa sulasta koiruudesta ja ylpeydestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 29, 'Kuin sota kovimmallansa oli, näkyi vihollisille taivaasta viisi jaloa miestä hevosten päällä kultaisilla suitsilla, jotka kävivät Juudalaisten edellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 30, 'Ja kaksi olivat Makkabealaisen tykönä ja varjelivat hänen aseillansa, ettei häntä kenkään haavoittaa taitanut, ja ampuivat nuolia ja pitkäisen leimauksia vihollisten päälle, että he sekautuivat ja pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 31, 'Ja lyötiin kaksikymmentä tuhatta ja viisisataa jalkaväestä, ja kuusisataa hevosmiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 32, 'Mutta Timoteus pakeni Gatsaraan päin vahvaan kaupunkiin, joka Kereaksella päämiehellä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 33, 'Niin piiritti Makkabealainen ja hänen joukkonsa sen neljäksi päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 34, 'Mutta jotka kaupungissa olivat, luottivat sen päälle, että se niin korkialla oli, ja pilkkasivat ja häpäisivät ylen muodottomasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 35, 'Mutta viidentenä päivänä vihastui kaksikymmentä nuorta miestä sen pilkan tähden, ja juoksivat miehuullisesti, karaten muurin tykö, ja tappoivat tuimuudessa kaikki, mitä heidän vastaansa tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 36, 'Niitä seurasivat muut ja astuivat muurin päälle, ja sytyttivät tornin, ja polttivat ne Jumalan pilkkaajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 37, 'Monikahdat hakkasivat portteja, että koko joukko pääsi sisälle, ja voittivat niin kaupungin, ja tappoivat Timoteuksen, joka itsensä kuoppaan lymyttänyt oli, ja hänen veljensä Kerean ja Apollophaneksen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 10, 38, 'Kuin he nämät toimittaneet olivat, ylistivät he Herraa kiitosvirrellä, joka Israelille niin suuren hyvän työn näyttänyt ja heille voiton antanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 1, 'Kuin Lysias, kuninkaan edustusmies ja lanko ja ylimmäinen neuvonantaja, nämät kaikki tietää sai, oli hänen mielensä sangen paha,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 2, 'Ja kokosi yhteen kahdeksankymmentä tuhatta miestä ja kaiken hevosmiesjonkon, ja meni Juudalaisia vastaan siinä luulossa, että hän pakanat kaupunkiin panis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 3, 'Ja että hän templin nautitsis, voittaaksensa sillä rahaa, niinkuin muutkin pakanain kirkot, ja ylimmäisen papin virkaa vuosi vuodelta myydäksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 4, 'Mutta ei hän ajatellut, että Jumala vielä väkevämpi on, vaan luotti suuren joukkonsa päälle, joka hänellä oli hevos- ja jalkaväestä, ja kahdeksankymmenen elephantin päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 5, 'Kuin hän nyt Juudeaan tuli, sioitti hän itsensä yhden kaupungin eteen, Betsura nimeltä, joka Jerusalemista oli viiden vakomitan takana vuorella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 6, 'Kuin Makkabealalnen ja ne, jotka hänen kanssansa olivat, sen kuulivat, että hän kaupungin piirittänyt oli, rukoilivat he ja kaikki joukko Herraa huokauksilla ja kyyneleillä, että hän yhden hyvän enkelin lähettäis, joka Israelia auttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 7, 'Ja Makkabealainen oli ensimäinen, joka itsensä varusti, ja neuvoi muita, että he hänen kanssansa koettelisivat ja veljiänsä auttaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 8, 'Ja menivät niin toinen toisensa kanssa ulos. Mutta niin pian kuin he ulos Jerusalemin eteen tulivat, näkyi heille yksi hevosinensa valkeissa vaatteissa ja kultaisissa haarniskoissa, joka meni heidän edellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 9, 'Niin he kiittivät laupiasta Jumalaa, ja olivat rohkiat lyömään vihollisiansa, vaikka he vielä julmimmat pedot olisivat olleet, ja olis rautainen muuri heidän edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 10, 'Senkaltaisella sydämellä vaelsi koko joukko edeskäsin auttajansa kanssa, jonka heille laupias Jumala taivaasta lähettänyt oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 11, 'Ja karkasivat vihollisten päälle niinkuin jalopeurat, ja löivät heistä yksitoistakymmentä tuhatta jalkaväkeä ja kuusitoista kymmentä sataa hevosmiestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 12, 'Ja kaikki muut pakoon karkottivat, että enin osa, joka sieltä palasi haavoitettu oli. Ja Lysias itse myös häpiällisesti pakeni ja pääsi pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 13, 'Kuitenkin oli Lysias toimellinen mies. Kuin hän nyt sitä tappelusta, jonka hän kadottanut oli, itsellensä ajatteli, ja näki Juudalaiset voittamattomaksi, että heitä kaikkivaltias Jumala niin autti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 14, 'Lähetti hän heidän tykönsä ja taritsi heille rauhan, ja lupasi myös kuninkaan saattaa heidän ystäväksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 15, 'Se kelpasi Makkabealaiselle; sillä hän näki sen parhaaksi. Ja kuningas mielistyi siihen sovintoon, jonka Lysias Makkabealaisen ja Juudalaisten kanssa tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 16, 'Ja kirja, jonka Lysias kirjoltti Juudalaisten tykö, oli näin: Lysias toivottaa Juudalaisille terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 17, 'Johannes ja Absalom, teidän lähetyksenne, toivat yhden kirjan ja ovat rukoilleet sitä asiaa, jonka tähden he lähetetyt olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 18, 'Mitä nyt kuninkaalle ilmoittamista on ollut, olen minä tehnyt, ja hän on kaikkiin, mitä tarpeellinen on, suostunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 19, 'Jos te nyt sananne ja lupauksenne pidätte, niin minä myös edespäin ahkeroitsen teidän parastanne katsoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 20, 'Ja joka kappaleesta erinänsä on teidän ja minun lähetykselläni käsky, teitä pitemmälti neuvoa. Tällänsä olkaat Jumalan huomassa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 21, 'Annettu 148 vuonna, 24 päivänä Dioskorin kuuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 22, 'Kuninkaan kirja oli näin: Antiokus kuningas tervehtii veljeänsä Lysiasta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 23, 'Että meidän isämme täältä erinnyt on ja jumalien sekaan tullut, ei ole meille mitään rakkaampaa kuin se että rauha meidän valtakunnassamme olis, että jokainen omaansa katsoa sais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 24, 'Me kuulemme nyt, ettei Juudalaiset ole tahtoneet suostua jumalanpalveluksensa muutokseen pakanain tavalla, vaan tahtovat uskossansa pysyä ja anovat, että he siinä saisivat pysyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 25, 'Että me nyt sen hyväksi löydämme, että tämä kansa myös rauhassa eläisi ja alallansa olis, niin on meidän tahtomme, että heille heidän templinsä jälleen annettaan, ja he saavat olla hallituksessansa ja menoissansa, niinkuin heidän esi-isänsäkin olleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 26, 'Sentähden tee sinä hyvin, ja lähetä muutamia heidän tykönsä, heidän kanssansa rauhaa tekemään, että koska he meidän tahtomme tietävät, surutoinna ovat ja töistänsä pelkäämättä pitävät vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 27, 'Kuninkaan kirja Juudalaisten tykö oli näin: Antiokus kuningas toivottaa Juudalaisten hallitukselle ja kansalle terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 28, 'Jos teidän kaikkein hyvin kävis, sen me mielellämme kuulisimme; meidän käy hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 29, 'Menelaus on meille ilmoittanut, että tahdotte vaeltaa meidän maallemme, ja teidän asianne meidän tykönämme toimittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 30, 'Sen tähden kaikille niille Juudalaisille, jotka tämän ja kolmenkymmenen päivän välillä Huhtikuuta vaeltavat, pitää vapaa tie oleman, itsensä pitää ruassa ja muussa lakinsa jälkeen, niinkuin ennenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 31, 'Ei myös kenellekään pidä mitään pahaa tapahtuman, sentähden mitä tähän asti meille tehty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 32, 'Todistukseksi olen minä Menelauksen teidän tykönne lähettänyt, teille leviämmältä tätä ilmoittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 33, 'Tällänsä olkaat Jumalan huomassa! 148 vuonna, 15 päivänä Huhtikuuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 34, 'Kirjoittivat myös Roomalalaiset Juudalaisten tykö, kuin seuraa: Kvintus Memmius ja Titus Manlius, Roomalaisten sanansaattajat, taritsevat Juudalaisille tervehdystänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 35, 'Kaikkiin, mitä Lysias, kuninkaan sukulainen, teille myöten antanut on, suostumme me myös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 36, 'Mutta että hänelle näkyy se hyväksi, muutamat asiat kuninkaan tykö antaa tulla, niin sovitelkaat keskenänne, ja lähettäkäät nopiasti joku meidän tykömme, että me yhdistäisimme itsemme toinen toisemme kanssa; sillä me menemme parhaallamme Antiokiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 37, 'Sen tähden kiiruhtakaat, ja lähettäkäät monikahtoja, että me tietäisimme teidän mielenne. Tällänsä olkaat Jumalan huomassa! 148 vuonna, 15. päivänä Huhtikuuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 11, 38, '');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 1, 'Kuin tämä sovinto näin päätetty oli, meni Lysias kuninkaan tykö, vaan Juudalailset viljelivät peltoansa');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 2, 'Mutta sen paikan päämiehet, Timoteus ja Apollonius, vapaasukuisen Apolloniuksen poika, ja Hieronymus ja Demophon, niin myös Nikanor, Kyprin päämies, ei antanut heille rauhaa eikä lepoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 3, 'Ja Jopen asuvaiset tekivät petollisen työn. Sillä he saattivat Juudalaiset, jotka heidän tykönänsä asuivat, siihen mieleen, että he vaimoinensa ja lapsinensa menivät niihin haaksiin, jotka he valmistaneet olivat, niinkuin he hyvät ystävät olisi olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 4, 'Kuin Juudalaiset sen tekivät, mikä kaupungissa päätetty oli, eikä mitään vaaraa peljänneet, ja tulivat merelle, upottivat he heidät kaikki, kaksisataa ihmistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 5, 'Kuin Juudas kuuli, kuinka hirmuisesti hänen veljeinsä kanssa tehty oli, käski hän sotaväkensä ylös, ja avuksensa huusi Jumalaa, vanhurskasta tuomaria,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 6, 'Ja meni niitä vastaan, jotka hänen veljensä murhanneet olivat, ja sytytti yöllä sataman, ja poltti kaikki haahdet, ja mitä väkeä tulesta pääsi, ne tappoi hän miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 7, 'Mutta että kaupunki suljettu oli, meni hän pois sillä mielellä, että hän pian jälleen tulis ja kaiken kaupungin peräti hävittäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 8, 'Ilmoitettiin myös hänelle, kuinka myös Jamnian asuvaiset senkaltaista aikoivat Juudalaisille, jotka asuivat heidän tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 9, 'Sentähden karkasi hän myös yöllä heidän päällensä, ja poltti heidän satamansa, ja kaikki haahdet, että valkia Jerusalemiin näkyi, joiden väli kuitenkin kaksisataa ja neljäkymmentä vakomittaa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 10, 'Sitte meni hän yhdeksän vakomittaa edes Timoteusta vastaan, niin karkasivat viisituhatta Arabialaista ja viisisataa hevosmiestä hänen päällensä, ja tappelivat hänen kanssansa, ja siinä oli suuri sota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 11, 'Ja Juudas joukkoinensa sai Jumalan avulla voiton. Ja että Arabialaiset voitetut olivat, rukoilivat he Juudaalta rauhaa, ja lupasivat hänelle eläimiä ja myös muutoin häntä auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 12, 'Juudas ajatteli, niinkuin myös tosi oli, he taitaisivat hänelle tarpeelliset olla, ja lupasi heille rauhan. Ja kuin he sen toinen toisellensa luvanneet olivat, menivät he kotiansa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 13, 'Hän tunkeutui myös yhteen kaupunkiin, joka silloilta varjeltu ja muurilla suljettu oli, kussa moninaista kansaa asui, ja kutsuttiin Kaspiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 14, 'Vaan ne, jotka kaupungissa olivat, luottivat vahvain muureinsa päälle ja suuren ruokavaransa päälle, ja ei paljon Juudaasta eikä hänen väestänsä lukua pitäneet, ja he päälliseksi pilkkasivat heitä, ja häpäisivät ja pahasti kiroilivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 15, 'Niin huusi Juudas ja hänen joukkonsa kaiken maailman väkevän Herran tykö, joka Josuan aikana ilman kaikkia sota-aseita Jerihon kukistanut oli maahan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 16, 'Ja juoksivat juuri vihaisesti muurin tykö, ja voittivat kaupungin, ja tappoivat määrättömän paljon ihmisiä, niin että se lampi, joka siinä tykönä oli, kahta vakomittaa leviä, näkyi niinkuin meri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 17, 'Sitälikin menivät he edemmäksi seitsemän sataa ja viisikymmentä vakomittaa, ja tulivat Taran puoleen Juudalaisten tykö, jotka Tubeanilaisiksi kutsuttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 18, 'Mutta ei he löytäneet Timoteusta; sillä hän oli sieltä paennut ja ei mitään toimittanut, vaan että hän yhden kylän vahvasti varustanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 19, 'Niin nousi kaksi päämiestä Makkabealaisen joukosta, nimittäin Dositeus ja Sosipater, ja tappoivat kaikki, jotka Timoteus varjelukseksi jättänyt oli, enempi kuin kymmenentuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 20, 'Mutta Makkabealainen asetti väkensä, ja jakoi monikahtoihin joukkoihin, ja meni Timoteusta vastaan, jolla oli sata ja kaksikymmentä tuhatta jalkamiestä ja viisitoistakymmentä sataa hevosmiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 21, 'Kuin Timoteus ymmärsi, että Juudas tuli häntä vastaan, lähetti hän vaimot ja lapset, ja jotka ei sotaan kelvanneet, linnaan, Karnioon, joka soukalla vuorella oli, ettei sitä piirittää saatu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 22, 'Mutta kuin hän ensimäisen Makkabealaisen joukon nähdä sai, tuli vihollisille pelko, että se heitä vastaan oli, ja itsensä näytti, joka kaikki näkee, ja rupesivat pakenemaan yksi sinne, toinen tänne, että he itsensä keskenänsä vahingoitsivat ja haavoittivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 23, 'Mutta Juudas meni perässä, ja löi ne jumalattomat, ja tappoi kolmekymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 24, 'Ja Timoteus tuli Dositeuksen ja Sosipaterin käsiin, ja rukoili heitä hartaasti, ettei he häntä tappaisi; siliä hänellä oli paljo heidän isiänsä ja veljiänsä, joidenka myös täytyis kuolla, jos hän tapettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 25, 'Kuin hän nyt luvannut oli määrättynä päivänä vahingoittamatta heidät jälleen antaa heille, päästivät he hänen veljeinsä tähden vallallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 26, 'Sitte meni Makkabealainen Karniota ja Atargatiota päin, ja tappoi viisikolmattakymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 27, 'Tämän matkan ja tapon perästä meni Juudas vahvaa kaupunkia Ephronia vastaan, kussa Lysias ja muutoin paljo väkeä oli. Mutta ne nuoret miehet, jotka kaupungin edessä olivat, varjelivat itsensä urhoollisesti; sillä heillä oli nuolia ja sota-aseita kyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 28, 'Niin he huusivat Herran tykö, joka voimallisesti vihollisen väkevyyden särkee, ja voittivat kaupungin, ja tappoivat viisikolmattakymmentä tuhatta ihmistä. 2 Aika K. 20: 3.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 29, 'Sitte menivät he sieltä Skytian kaupunkia vastaan, joka kuusisataa vakomittaa Jerusalemista on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 30, 'Mutta että Juudalaiset, jotka Skytialaisten seassa asuivat, todistivat heistä, että he kaikkea ystävyyttä heille kovalla ajalla näyttäneet olivat, käyttivät he myös itsensä ystävällisesti heitä kohtaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 31, 'Ja kiittivät heitä sen edestä, ja neuvoivat heitä edespäinkin heidän kansaansa kohtaan niin hyväntahtoiset olemaan. Ja palasivat niin Jerusalemiin, ja tulivat helluntaina kotia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 32, 'Mutta helluntain jälkeen menivät he Gorgiasta, Edomealaisten päämiestä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 33, 'Se tuli heitä vastaan kolmella tuhannella jalkamielellä ja neljälläsadalla hevosmiehellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 34, 'Ja kuin tappelemaan ruvettiin, tuli siinä monikahtoja Juudalaisia pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 35, 'Ja Dositeus, väkevä hevosmies Bakenorin joukosta, sai Gorgiaan kiinni, ja piteli häntä hameesta, ja vei häntä väkivallalla, ja tahtoi hänen elävältä vangiksi ottaa. Mutta Trasian hevosmies ajoi hänen tykönsä, ja hakkasi häneltä käsivarren pois, niin että Gorgias pääsi Moresaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 36, 'Koska Gorgiaan joukko vielä itsiänsä varjeli, ja Juudalaiset jo väsyksissä olivat, huusi Juudas Herran tykö, että hän heitä auttais ja heidän puolestansa sotis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 37, 'Ja hänen väkensä huusi Hebrean kielellä, ja rupesi veisaamaan suureen ääneen, ja karkasi Gorgiaan väen päälle tapaturmasti, ja ne kääntyivät pakoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 38, 'Ja Juudas meni väkinensä Odollamin kaupunkiin: ja että se vielä helluntaiviikko oli, puhdistivat he itsensä lain jälkeen, ja pitivät siellä sabbatia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 39, 'Toisena päivänä tulivat he Juudaan tykö, kuolleitansa ottamaan, niinkuin tapa on, ja hautaamaan heitä isäinsä tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 40, 'Kuin he niitä riisuivat, löysivät he kukin kuolleen paidan alta koristuksia Jamnian epäjumalista, jotka Juudalaisilta laissa kielletyt ovat. Niin se tuli jokaiselle ilmi, minkätähden nämät tapetut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 41, 'Silloin he kiittivät Jumalaa, vanhurskasta tuomaria, joka salatyön niin ilmi saattanut oli; Ps. 9: 5.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 42, 'Ja rukoilivat häntä, ettei hän tämän synnin tähden heitä kaikkia hävittäisi. Ja Juudas, se jalo sankari, neuvoi joukkoa lohdullisesti, että he edespäin synnistä itsensä varjelisivat, koska he silmillänsä näkivät nämät synteinsä tähden tapetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 43, 'Sitte käski hän heidän koota avun, kaksituhatta drakmaa hopiaa; ne hän lähetti Jerusalemiin rikosuhriksi, ja teki hyvin ja jalosti, että hän heitä ylösnousemisesta neuvoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 44, 'Sillä jos ei hän olisi toivonut ne ylösnousevan, niin olis turha ja hulluus ollut kuolleiden edestä rukoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 12, 45, 'Vaan että hän muisti, että jota oikiassa uskossa kuolevat, toivovat iloa ja autuutta, on se hyvä ja pyhä ajatus ollut. Sentähden on hän myös näiden kuolleiden edestä rukoillut, että heilie synnit anteeksi annettaisiin. N. B. Rukoilla kuolleille syntein anteeksi antamista, ei sovi uskon perustuksen kanssa yhteen; josta taitaan nähdä, ettei tämä kirja ole joku perustuskirja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 1, 'Yhdeksäntenä vuotena viidettäkymmentä toista sataa ilmoitettiin Juudaalle ja hänen joukollensa, että Antiokus Eupator suurella joukolla Juudeaa vastaan tuli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 2, 'Ja Lysias, hänen edustusmiehensä ja ylimmäinen neuvonantajansa, hänen kanssansa, ja heillä oli sata ja kymmenentuhatta Grekiläistä jalkamiestä, ja viisituhatta ja kolmesataa hevosmiestä, ja kaksikolmattakymmentä elephanttia, ja kolmesataa vaunua rantaisilla piikeillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 3, 'Oli myös Menelaus antanut itsensä heidän puolellensa ja neuvonut Antiokusta suuresta ulkokullaisuudesta isänsä maata hävittämään, että hän sen kautta ylimmäisen papin viran olis saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 4, 'Mutta kaikkein kuningasten Kuningas käänsi Antiokuksen mielen, että hän sen pahanilkisen karkurin rankaisi. Sillä Lysias teki hänen kaiken tämän levottomuuden syyksi, sentähden antoi hän hänen viedä Bereaan, ja heidän maansa tavalla siellä tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 5, 'Sillä siellä oli torni viisikymmentä kyynärää korkia, täynnä tuhkaa, ja tuhan päällä oli ympäri juoksevainen ja piikkinen ratas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 6, 'Sen päällä murrettiin Jumalan pilkkaajat ja suuret pahantekiät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 7, 'Senkaltaisella kuolemalla täytyi myös luopuneen Menelauksen kuolla, ja ei maahan haudattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 8, 'Ja hänelle tapahtui oikein; sillä että hän usein Herran alttaria vastaan, kussa pyhä tuli ja tuhka oli, syntiä tehnyt oli, piti hänen myös tuhan päällä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 9, 'Mutta kuningas oli sangen suuressa kiukussa Juudalaisten päälle, ja aikoi niin hirmuisesti heille tehdä, kuin hänen isänsäkin tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 10, 'Sen ymmärsi Juudas, ja käski kaiken kansan rukoilla Herraa päivällä ja yöllä, että hän heitä nyt, niinkuin usein ennenkin, auttais niitä vastaan, jotka lain, isänmaan ja pyhän templin ryöstää tahtoivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 11, 'Ja ettei hän kansaansa, joka nepiästi henkensä vetänyt oli, kirottuin pakanain käsiin antaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 12, 'Kuin he nyt sitä yksimielisesti tekivät, ja rukoilivat laupiasta Jumalaa itkulla ja paastolla, ja makasivat koko kolme päivää maassa, lohdutti heitä Juudas ja käski tykönsä tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 13, 'Ja kuin hän ja vanhimmat yhdessä olivat, piti hän neuvoa heidän kanssansa, että hän tahtoi ennen kuin kuningas joukkoinensa Juudeaan tulis Ja kaupungin voittais, häntä vastaan mennä, ja Jumalan avulla lopettaa asian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 14, 'Ja antoi niin itsensä Jumalan haltuun, ja neuvoi väkensä sotimaan rohkiasti kuolemaan asti, varjellaksensa lakia, templiä, kaupunkia, isänmaata ja hallitusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 15, 'Ja sioitti itsensä Modiin, Ja antoi heille tämän sanan merkiksi: Jumala antaa voiton. Sitte nousi hän ylös yöllä parasten sotamiesten kanssa, ja karkasi kuninkaan leiriin, ja löi kuoliaaksi neljätuhatta miestä ja ensimäiset elephantit kaikkein niiden kanssa, jotka tornissa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 16, 'Niin saattivat he suuren hämmästyksen ja pelvon koko leiriin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 17, 'Ja menivät kunniallisesti ja onnellisesti sieltä huomeneltain, kuin päivä koitti; sillä Jumala oli heidän auttajansa ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 18, 'Mutta kuningas, kuin hän koetellut oli, että Juudalaiset niin rohkiat olivat, palasi takaisin ja meni sieltä tietöintä matkaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 19, 'Ja vei väkensä Betsuraan, Juudalaisten linnan eteen, jossa ei vartioita ollut. Mutta hän lyötiin sieltä myös pakoon, ja ei mitään toimittanut, vaan sai vahingon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 20, 'Sillä Juudas toimitti kaikki, mitä linnassa tarvittiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 21, 'Mutta Juudalaisten seassa oli yksi Rodokus nimeltä, se ilmoitti vihollisille kaikki salaudet; mutta hän sai tietää, ja sai hänen kiinni, ja ajoi sieltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 22, 'Sitte sai kuningas toisen mielen, ja teki rauhan niiden kanssa Betsurasta, ja meni sieltä ja tappeli Juudaan kanssa, Ja voitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 23, 'Ja että hän oli tietää saanut, että Philippus hänestä luopunut oli, jonka hän Antiokiaan peräänsä linnan isännäksi jättänyt oli, hämmästyi hän kovin, Ja antoi suositella Juudalaisten kanssa, ja teki sovinnon heidän kanssansa, ja vannoi sen valan pitävänsä, ja oli niin heidän ystävänsä, ja uhrasi ja kunnioitti templiä ja piti itsensä ystävällisesti kaupunkia kohtaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 24, 'Ja otti Makkabealaisen ystäväksensä, ja teki hänen päämieheksi Ptolemaidista Gerreniläisiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 25, 'Mutta kuin kuningas Ptolemaidiin tuli, ei Ptolemaidilaiset mielellänsä sitä sovintoa nähneet; sillä he pelkäsivät, ettei heitä uskottaisi, niinkuin ei hekään sanaansa pitäneet olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 13, 26, 'Silloin astui Lysias julkisesti edes, ja vastasi kuninkaan puolesta, ja puhui niin heidän kanssansa, että he siihen tyytyivät, Ja asetti heidät, että heidän kaikkea hyvää häneltä toivoman piti. Sitte vaelsi hän takaperin Antiokiaan jälleen. Näin on tämän kuninkaan matkustus ja kotia palajaminen ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 1, 'Kolmen vuoden perästä ymmärsi Juudas ja hänen joukkonsa, että Demetrius Seleukuksen poika Tripoliin paljolla väellä ja paljoilla haaksilla tullut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 2, 'Ja maan voittanut, ja Antiokuksen edustusmiehensä Lysiaan kanssa lyönyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 3, 'Mutta Alkimus, joka ennen ylimmäinen pappi oli ollut ja kiusauksen ajalla häpiällisesti luopunut, ja nyt, ajatteli, ettei hän hengissä pysyä eikä jälleen ylimmäisen papin virkaan tulla taitanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 4, 'Meni kuningas Demetriuksen tykö ensimäisenä vuotena kuudettakymmentä toista sataa, ja vei hänelle kultaisen kruunun, palmut ja öljypuun oksat, jotka templin omat olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 5, 'Ja ensimäisen päivän hän viivytteli, että hän soveliaan aikansa näkis hänen kiukkuunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 6, 'Kuin Demetrius antoi kutsua hänen hallituksensa eteen ja häneltä kysyä, kuinka Juudalaisten menoin laita oli, ja mitä he tekivät? vastasi hän näin: Juudalaiset, jotka itsensä kutsuvat Juudalaisiksi, joidenka päämies Juudas Makkabealainen on, kehoittavat aina sotaa ja kapinaa, eikä suo valtakunnalle rauhaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 7, 'Ovat myös minulta isällisen kunniani, nimittäin pappeuden, ryövänneet; sen tähden olen minä tänne tullut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 8, 'Ensisti kuninkaalle hyväksi, ja että minä uskollinen olisin; toiseksi, että minä myös mielelläni kansalleni neuvoa toimittaisin. Sillä senmuotoisella pahalla menolla koko meidän sukukuntamme hukkuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 9, 'Sentähden katsakaan kuningas niihin asioihin, ja kuuluisan hyvyytensä tähden maakuntaa ja koko meidän sukukuntaamme tässä asiassa neuvokoon ja auttakoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 10, 'Sillä niinkauvan kuin Juudas elää, on mahdotoin, että rauha maalla olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 11, 'Kuin hän nämät puhunut oli, julmistuivat myös ne muut Juudaa vastaan, ja kehoittivat Demetriuksen häntä vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 12, 'Että hän kohta kutsui Nikanorin, päämiehen elephanttein kalun päällä, ja asetti hänen päämieheksi Juudalaisia vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 13, 'Ja käski hänen Juudaan tappaa, ja hänen joukkonsa hajoittaa, ja Alkimuksen ylimmäiseksi papiksi panna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 14, 'Silloin kokoontuivat Nikanorin tykö kaikki pakanat, jotka Juudas oli ajanut pois maalta, ja toivoivat Juudalaisten vahingosta itsellensä onnea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 15, 'Kuin Juudas ja hänen joukkonsa kuulivat, että Nikanor oli tulossa heitä vastaan, ja pakanat joka haaralta joukottain hänen tykönsä tulivat, tuhkasivat he itsensä ja huusivat Jumalan tykö, joka kansaansa maailman alusta varjellut ja joukkoansa ilmeisesti auttanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 16, 'Kuin heidän päämiehensä heitä käski, nousivat he ylös, ja karkasivat vihollisten päälle vähän kaupungin Dessan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 17, 'Mutta Simon, Juudaan veli, tarttui Nikanoriin, ja Nikanor olis pikimmältänsä lyöty, että viholliset hänen saavuttaneet olivat, ennenkuin hän heidät huomaitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 18, 'Kuin Nikanor kuuli Juudaalla senkaltaisia tuimia miehiä olevan, jotka ei henkeänsä ja tavaraansa säästäneet isänsä maan tähden, pelkäsi hän, eikä tahtonut heidän kanssansa enää tapella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 19, 'Vaan lähetti hänen tykönsä Possidoniuksen, Teodotuksen ja Matatiaan, rauhaa hänen kanssansa tekemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 20, 'Kuin he nyt kauvan sitä neuvoa pitäneet olivat, ja heidän päämiehensä väelle kaikki asiat tietää antanut oli, ja he asiasta sopivat, suostuivat he siihen sovintoon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 21, 'Ja määräsivät yhden päivän, jona he molemmat yksinänsä piti tuleman yhteen. Kuin se päivä joutui, pantiin kummallekin istuin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 22, 'Ja Juudas asetti monikahtoja haarniskoihin, ei kauvas siitä, ettei viholliset olisi tapaturmasti häntä pettäneet. Ja puhuivat toinen toisensa kanssa tarpeensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 23, 'Ja Nikanor oli Jerusalemissa kauvan, ja ei mitään tehnyt heitä vastaan, ja antoi sotaväkensä mennä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 24, 'Ja piti Juudaan kunniassa kansan edessä, ja käytti itsensä ystävällisesti hänen kanssansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 25, 'Neuvoi myös häntä naimaan ja lapsia siittämään. Niin otti Juudas emännän, ja oli yhdessä sen kanssa hyvässä rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 26, 'Kuin Alkimus näki nämät kaksi sopivan ja rauhan tehneen, meni hän jälleen Demetriuksen tykö ja kantoi Nikanorin päälle, että hän petolliseksi tullut oli; sillä hän oli Juudaan, kuninkaan vihamiehen, hänen siaansa ylimmäiseksi papiksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 27, 'Niin käännettiin kuningas tämän pahanilkisen valheesta ja vihastui suuresti, ja kirjoitti Nikanorille, ettei hänelle millään muotoa se kelvannut, että hän Juudalaisten kanssa rauhan tehnyt oli, ja käski hänen kiiruusti ottaa kiinni Makkabealaisen ja Antiokiaan lähettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 28, 'Kuin tämä käsky Nikanorille tuli, tuli hän murheelliseksi, ja oli pahalla mielellä, ettei hän lupaustansa pitää taitanut, ja ei kuitenkaan Juudas mitään rikkonut ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 29, 'Mutta kuitenkin, ettei hän kuningasta vastaan mitään tehdä tohtinut, aikoi hän hänen ottaa kiinni kavaluudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 30, 'Mutta kuin Makkabealainen ymmärsi, ettei hän niin ystävällisesti hänen kanssansa ollut kuin ennen, ja näkyi, ettei se mitään hyvää aavistanut, otti hän monikahtoja tykönsä ja lymytti itsensä hänen edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 31, 'Mutta kuin Nikanor näki, että Makkabealainen hänen kavalasti ennättänyt oli, meni hän kauniisen pyhään templiin, ja käski pappein, jotka siellä uhrasivat, miestä sieltä antamaan ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 32, 'Mutta kuin he korkiasti ja kalliisti vannoivat, ettei he tietäneet, kussa hän oli, ojensi hän oikian kätensä templin puoleen, ja vannoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 33, 'Jos ette minulle Juudaa sidottuna anna, niin minä tämän Jumalan huoneen kukistan ja alttarin maahan revin, ja panen Bakkuksen kauniin kirkon siihen siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 34, 'Ja kuin hän nämät puhunut oli, meni hän sieltä pois. Mutta papit nostivat kätensä taivaasen päin, ja huusivat hänen tykönsä, joka aina meidän kansaamme varjellut on, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 35, 'Herra, vaikka et sinä mitään tarvitse, on se kuitenkin sinun hyvä tahtos ollut, että sinun templis, jossa sinä asut, meidän seassamme olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 36, 'Sen tähden, pyhä Jumala, jonka kaikki pyhät omat ovat, varjele vielä huonees, jonka me äskettäin puhdistaneet olemme, ettei sitä jälleen saastutettaisi, ja tukitse pahain suut!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 37, 'Mutta Nikanorille sanottiin Jerusalemissa olevan yksi mies vanhimmista, Ratsis nimeltä, joka isällisiä käskyjä rakasti, ja jolla joka paikassa hyvä kiitos ja senkaltainen ystävyys, että jokainen hänen Juudalaisten isäksi kutsui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 38, 'Hänen päällensä oli myös ennen tätä aikaa kannettu ja häntä vainottu, ja oli henkensä miehuullisesti vaaraan antanut Juudalaisten uskon tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 39, 'Kuin Nikanor näyttää tahtoi, kuinka kovin hän Juudalaisten päälle vihainen oli, lähetti hän enempi kuin viisisataa sotamiestä, ottamaan häntä kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 40, 'Sillä hän luuli, kuin hän hänen vangiksi saanut olis, heille suuren vahingon tehneensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 41, 'Mutta kuin he tornin porttiin, kussa hän oli, karkasivat, ja käskivät tulta tuoda, porttia sytyttääksensä, ja hän ymmärsi vankina olevansa, tahtoi hän itsensä pistää lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 42, 'Sillä hän tahtoi ennen kunnialla kuolla, kuin jumalattomain käsiin tulla, ja heiltä häpiällisesti pilkattaa; mutta siinä hädässä ei hän itsiänsä oikein osannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 43, 'Kuin he joukottain hänen tykönsä sisälle menivät, juoksi hän muurin päälle, Ja syöksi itsensä rohkiasti kansan sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 44, 'Mutta he välttivät, että hänellä siaa olis ollut. Ja hän putosi kuvettensa päälle, mutta vielä hän kuitenkin eli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 45, 'Ja nousi vihoissansa ylös, vaikka hän kovin verta vuosi, ja haavat kipiät olivat, ja juoksi kansan lävitse, ja astui korkian kallion päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 14, 46, 'Kuin hänestä kaikki veri oli juossut ulos, otti hän kuitenkin suolet ruumiistansa, ja heitti ne sotamiesten keskelle, ja huusi Jumalan tykö, joka elämän ja hengen Herra on, että hän ne kaikki hänelle jälleen antais; ja niin hän kuoli. Tämän työn sopimattomuus selitetään tämän kirjan esipuheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 1, 'Mutta kuin Nikanor kuuli, että.Juudas väkinensä Samariassa oli, ajatteli hän sabbatina heidän päällensä ilman vaaraa karata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 2, 'Ja kuin Juudalaiset, jotka hän kanssansa menemään vaatinut oli, häntä neuvoivat, ettei hän niin surkiasti heitä surmaisi, vaan säästäis pyhäpäivän tähden, jonka Jumala itse kunnioittanut ja pyhittänyt oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 3, 'Kysyi heiltä se pääkoira: joka sabbatin pitää käskenyt on, onko hän Herra taivaassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 4, 'Ja kuin he vastasivat häntä: on, hän on elävä Herra, hän on taivaan Herra, joka seitsemännen päivän pyhittää käskenyt on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 5, 'Vastasi hän siihen: niin olen minä herra maan päällä, ja käsken teidän teitänne valmistaa, ja kuninkaan tahtoa toimittaa. Mutta ei hän kuitenkaan taitanut aivoitustansa täyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 6, 'Ja Nikanor öykkäsi ja kerskasi, ja oli vahva siitä, että hänen suuren kunnian saaman piti Juudaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 7, 'Mutta Makkabealaisella oli vahva turva ja toivo, että Herra oli häntä auttava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 8, 'Ja lohdutti niitä, jotka hänen kanssansa olivat, ettei he pelkäisi pakanoita, jotka tulivat heitä vastaan, vaan muistaisivat sitä apua, joka heille usein taivaasta tapahtunut oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 9, 'Ja myös nyt toivoisivat seuraavaista voittoa ja apua, jonka heille Herra lähettävä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 10, 'Näin lohdutti hän heitä laista ja prophetaista, ja muistutti heille ne onnelliset entiset tappelukset, ja niin teki heidät rohkiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 11, 'Ja kuin hän heitä niin neuvonut oli, luetteli hän myös heille, kuinka pakanat rikkoneet olivat ja tehneet vastaan valaansa, ja niin varusti heitä, ei luottain keihästen ja kilpien päälle, vaan lohdutukseen Jumalan sanasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 12, 'Hän sanoi myös heille yhden näyn, joka uskottava oli, jonka hän nähnyt oli, josta he kaikki sydäntä saivat. Ja tämä oli se näky: Onias ylimmäinen pappi, jalo, kunniallinen, laupias ja puhelias mies, joka nuoruudestansa kaikissa hyvissä avuissa harjoitellut olit, ojensi kätensä, ja rukoili kaiken Juudan kansan edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 13, 'Sitte näkyi hänelle toinen vanha, kunniallinen mies kalliissa vaatteissa ja sangen kunniallisella muodolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 14, 'Ja Onias sanoi Juudaalle: tämä on Jeremia, Jumalan propheta, joka sinun veljiäs sangen suuresti rakastaa, ja rukoilee alati kansan ja pyhän kaupungin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 15, 'Sitte antoi Jeremia käsillänsä Juudaalle kultaisen miekan, ja sanoi hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 16, 'Ota tämä pyhä miekka, jonka Jumala sinulle antaa; sillä sinun pitää viholliset lyömän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 17, 'Kuin Juudas heitä senkaltaisilla kauniilla sanoilla, jotka heille sydäntä ja rohkeutta antoivat, lohduttanut oli, mielistyivät he siihen, ettei he leiriä tehdä tahtoneet, vaan kohta vihamiesten tykö mennä, ja karata rohkiasti heidän päällensä, ja lopettaa asian; sillä kaupunki, jumalanpalvelus ja templi olivat vaarassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 18, 'Ja tosin, vaimoja ja lapsia, veljiä ja lankoja ei he niin paljon totelleet, vaan heidän suurin murheensa oli pyhästä templistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 19, 'Ja ne, jotka kaupunkiin jäivät, olivat suuressa murheessa heidän sotaväestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 20, 'Kuin sotimisen aika joutui, ja viholliset kokoontuneet olivat, järjestyksensä tehneet, elephantit siallensa asettaneet ja hevosmiehet molemmille puolille panneet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 21, 'Ja Makkabealainen viholliset näki, ja heidän moninaiset aseensa ja hirmuiset pedot, nosti hän kätensä taivaasen päin, ja rukoili ihmeellistä Jumalaa, joka kaikki näkee; sillä hän kyllä tiesi, ettei voitto haarniskain kautta tule, vaan Jumala antaa sen kellenkä hän suo; ja hän rukoili näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 22, 'Herra, sinä olet enkelis, Hiskian, Juudan kuninkaan aikana, lähettänyt, ja se löi Sennaheribin leirissä sata ja viisiyhdeksättäkymmentä tuhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 23, 'Niin lähetä myös nyt sinä, taivaan Herra, hyvä enkeli meidän edellämme vihollisia peljättämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 24, 'Anna heidän hämmästyä sinun väkevää käsivarttas, jotka Jumalan pilkalla sinun pyhää kansaas vastaan tulevat. Ja niin Juudas lakkasi puhumasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 25, 'Niin tuli Nikanor ja hänen joukkonsa vaskitorven soitolla ja suurella huudolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 26, 'Mutta Juudas ja hänen joukkonsa löivät vihollisia rukouksella ja huutamisella Jumalan tykö; ja käsillänsä he tappelivat, mutta sydämellänsä huusivat Jumalan tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 27, 'Ja löivät viisineljättäkymmentä tuhatta miestä, ja iloitsivat suuresti, että Jumala itsensä niin armolliseksi näyttänyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 28, 'Kuin tappo loppui ja he menivät pois jälleen, tunnettiin Nikanor haarniskoistansa, että hän myös tapettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 29, 'Silloin nousi suuri huuto ja riemu, ja he kiittivät Jumalaa kielellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 30, 'Ja Juudas, joka henkensä ja tavaransa kansansa edestä alttiiksi antanut, ja hamasta nuoruudestansa kansallensa paljon hyvää tehnyt oli, käski hakata pois Nikanorin pään ja kädet olkapäinensä, ja kanssansa Jerusalemiin viedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 31, 'Kuin hän sinne tuli, kutsui hän väkensä kokoon, ja asetti papit alttarin eteen, ja lähetti linnaan vihollisten perään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 32, 'Ja näytti Nikanorin pään ja pilkkaajan käden, jonka hän Kaikkivaltiaan pyhää huonetta vastaan ojentanut ja itsestänsä paljon kerskannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 33, 'Hän leikkasi myös jumalattomalta Nikanorilta kielen, ja käski kappaleiksi lintuin eteen hakata ja käden, jolla hän hulluutta tehnyt oli, templin puoleen ripustaa ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 34, 'Ja kaikki kansa kiitti Jumalaa taivaasta, ja sanoivat: kiitetty olkoon se, joka kaupunkinsa varjellut on, ettei se ole saastutetuksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 35, 'Ja pani Nikanorin pään ylös, että sen jokainen linnasta nähdä taisi, julkiseksi tiedoksi, että Herra heitä auttanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 36, 'Se myös yksimielisesti kaikilta päätettiin, ettei sitä päivää unhotettaisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 37, 'Vaan pyhänä pidettäisiin, nimittäin, kolmas päivä toistakymmentä toisesta kuusta toistakymmentä, joka Syrian kielellä Adariksi kutsutaan, päivää ennen Mardokain juhlaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 38, 'Näin tahdon minä nyt tämän kirjan tällänsä päättää, sittekuin Nikanor tuli pois ja Juudalaiset kaupungin jälleen voittivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 15, 39, 'Ja jos minä sen otolliseksi tehnyt olen, niin minä sen mielelläni tahtoisin, mutta jos se halpa on, niin olen minä kuitenkin tehnyt niin paljon kuin minä voinut olen. Sillä viinaa eli vettä aina juoda, ei ole otollinen; vaan toisinansa viinaa, toisinansa vettä, se on suloinen; niin on myös suloinen, kuin moninaisia luetaan. Tämä olkoon loppu.');
