INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Herra kaikkivaltias, meidän Isäimme Abrahamin, Isaakin ja Jakobin, ja heidän vanhurskaan siemenensä Jumala!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Joka taivaan ja maan ja kaikki, mitä niissä on, tehnyt olet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Ja olet meren kiinnittänyt sinun käskylläs, ja syvyyden peittänyt ja kiinnittänyt sinun peljättävän ja kuuluisan nimes kunniaksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Että jokainen hämmästyis sinun edessäs ja pelkäis sinun suurta voimaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Sillä sinun vihas on sangen raskas, jolla sinä uhkaat syntisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Mutta se laupius, jonka sinä lupaat, on määrätöin ja tutkimatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Sillä sinä, Herra, kaikkein Korkein koko maan piirin päällä, olet kärsivällinen ja sangen armollinen, ja et mielelläs ihmisiä rankaise, ja olet sinun hyvyydessäs luvannut katumuksen syntein anteeksi saamiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Mutta että sinä olet vanhurskasten Jumala, niin et sinä ole pannut katumusta vanhurskaalle Abrahamille, Isaakille ja Jakobille, jotka ei sinua vastaan syntiä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Mutta minä olen syntiä tehnyt, ja minun syntiäni on enempi kuin santaa meressä, ja olen kämärtynyt raskaissa rautakahleissa, eikä ole minulla yhtään lepoa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'Sillä minä olen kehoittanut sinun vihaan ja suuren kauhistuksen sinun edessäs tehnyt, että minä senkaltaisen kauhistuksen ja niin paljon pahennusta olen matkaan saattanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 11, 'Sen tähden notkistan minä nyt minun sydämeni polvet ja rukoilen sinulta, Herra, armoa. Oi Herra, minä olen syntiä tehnyt, tosin minä olen syntiä tehnyt, ja minä tunnustan minun pahat tekoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 12, 'Minä rukoilen ja parun: anna minulle anteeksi; oi Herra, anteeksi anna minulle; älä anna minun synnissäni hukkua, ja älä anna rangaistusta ijankaikkisesti minun päälläni olla;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 13, 'Vaan auta minua epäkelvotointa sinun suuren laupiutes tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 14, 'Niin minä kaikkena elinaikanani sinua kiitän. Sillä sinua kiittää kaiken taivaan sotajoukko, ja sinua pitää ylistettämän ilman lakkaamatta ijankaikkisesti, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 15, '');
