INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Jesuksen Kristuksen syntymäkirja, Davidin pojan, Abrahamin pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Abraham siitti Isaakin. Mutta Isaak siitti Jakobin. Jakob siitti Juudan, ja hänen veljensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Juuda siitti Phareksen ja Saramin Tamarista. Phares siitti Hetsronin. Hetsron siitti Aramin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Aram siitti Aminadabin. Aminadab siitti Nahassonin. Nahasson siitti Salmonin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Salmon siitti Boaksen Rahabista. Boas siitti Obedin Ruutista. Obed siitti Jessen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Jesse siitti kuningas Davidin. Kuningas David siitti Salomonin Urian emännästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Salomon siitti Rehabeamin. Rehabeam siitti Abian. Abia siitti Assan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Assa siitti Josaphatin. Josaphat siitti Joramin. Joram siitti Ussian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Ussia siitti Jotamin. Jotam siitti Akaksen. Akas siitti Etsekian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Etsekia siitti Manassen. Manasse siitti Amonin. Amon siitti Josian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Josia siitti (Jojakimin. Jojakim siitti) Jekonian ja hänen veljensä, Babelin vankiudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Mutta Babelin vankiuden jälkeen siitti Jekonia Sealtielin. Sealtiel siitti Zorobabelin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Zorobabel siitti Abiudin. Abiud siitti Eliakimin. Eliakim siitti Asorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Asor siitti Sadokin. Sadok siitti Akimin. Akim siitti Eliudin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Eliud siitti Eleatsarin. Eleatsar siitti Matanin. Matan siitti Jakobin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Jakob siitti Josephin, Marian miehen, josta (Mariasta) on syntynyt Jesus, joka kutsutaan Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Niin ovat kaikki polvet Abrahamista Davidiin asti neljätoistakymmentä polvea; Davidista Babelin vankiuteen myös neljätoistakymmentä polvea, ja Babelin vankiudesta Kristukseen asti neljätoistakymmentä polvea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Jesuksen Kristuksen syntymys oli näin: koska Maria hänen äitinsä oli Josephiin kihlattu, ennen kuin he yhteen tulivat, löyttiin hän raskaaksi Pyhästä Hengestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Mutta että Joseph hänen miehensä oli hurskas ja ei tahtonut häntä huutoon saattaa, ajatteli hän salaisesti hyljätä hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Kuin hän näitä ajatteli, katso, niin Herran enkeli ilmestyi hänelle unessa ja sanoi: Joseph, Davidin poika! älä pelkää ottaakses Mariaa puolisoas tykös; sillä se, mikä hänessä on siinnyt, on Pyhästä Hengestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Ja hänen pitää synnyttämän Pojan, jonka nimen sinun pitää kutsuman Jesus; sillä hän on vapahtava kansansa heidän synneistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Mutta tämä on kaikki tapahtunut, että täytettäisiin, mitä Herralta on sanottu prophetan kautta, joka sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Katso, neitseen pitää raskaaksi tuleman ja synnyttämän Pojan, ja hänen nimensä pitää kutsuttaman Emmanuel; se on niin paljo sanottu: Jumala meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Kuin Joseph unesta heräsi, niin hän teki kuin Herran enkeli hänen käski, ja otti puolisonsa tykönsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Ja ei tuntenut häntä, siihenasti kuin hän poikansa esikoisensa synnytti, ja kutsui hänen nimensä Jesus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 1, 'Koska siis Jesus syntynyt oli Betlehemissä Juudan maalla, kuningas Herodeksen aikaan, katso, tietäjät tulivat idästä Jerusalemiin ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 2, 'Kussa on se syntynyt Juudalaisten kuningas? sillä me näimme hänen tähtensä idässä, ja tulimme häntä kumartaen rukoilemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 3, 'Kuin kuningas Herodes sen kuuli, hämmästyi hän ja kaikki Jerusalem hänen kanssansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 4, 'Ja kokosi kaikki ylimmät papit ja kirjanoppineet kansan seassa, ja kyseli heiltä, kussa Kristuksen syntymän piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 5, 'Ja he sanoivat hänelle: Betlehemissä Juudan maalla; sillä niin on prophetan kautta kirjoitettu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 6, 'Ja sinä Betlehem Juudan maassa, et sinä ole suinkaan vähin Juudan pääruhtinasten seassa; sillä sinusta on tuleva se Ruhtinas, jonka minun kansaani Israelia pitää hallitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 7, 'Silloin kutsui Herodes tietäjät salaa, ja tutkisteli visusti heiltä, millä ajalla tähti ilmestyi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 8, 'Ja lähetti heidät Betlehemiin, ja sanoi: menkäät ja kysykäät visusti lapsesta, ja kuin te löydätte, niin ilmoittakaat minulle, että minäkin tulisin ja kumartaisin häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 9, 'Kuin he olivat kuninkaan kuulleet, menivät he matkaansa, ja katso, tähti, jonka he olivat nähneet idässä, kävi heidän edellänsä, niinkauvan kuin hän edellä käyden seisahti sen paikan päälle, jossa lapsi oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 10, 'Kuin he tähden näkivät, ihastuivat he sangen suurella ilolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 11, 'Ja menivät huoneeseen, löysivät lapsen äitinsä Marian kanssa, maahan lankesivat ja rukoilivat häntä, ja avasivat tavaransa, ja lahjoittivat hänelle kultaa ja pyhää savua ja mirhamia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 12, 'Ja Jumala kielsi heitä unessa Herodeksen tykö palajamasta; ja he menivät toista tietä omalle maallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 13, 'Mutta kuin he olivat menneet pois, katso, niin Herran enkeli ilmestyi Josephille unessa, sanoen: nouse ja ota lapsi äitinensä tykös, ja pakene Egyptiin, ja ole siellä siihen asti kuin minä sinulle sanon; sillä Herodes on etsivä lasta, hukuttaaksensa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 14, 'Niin hän nousi ja otti lapsen äitinensä yöllä tykönsä, ja pakeni Egyptiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 15, 'Ja oli siellä Herodeksen kuolemaan asti: että täytettäisiin mitä sanottu oli Herralta prophetan kautta, joka sanoo: Egyptistä kutsuin minä poikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 16, 'Kuin Herodes näki itsensä tietäjiltä vietellyksi, vihastui hän sangen kovin, ja lähetti tappamaan kaikki poikalapset Betlehemissä ja kaikissa sen äärissä, jotka kaksivuotiset olivat taikka nuoremmat, sen ajan jälkeen, jonka hän oli tarkasti tietäjiltä tutkinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 17, 'Silloin se täytettiin, mitä Jeremialta prophetalta sanottu oli, joka sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 18, 'Ramassa on ääni kuulunut, suuri valitus, itku ja iso parku: Rakel itkee lapsiansa, ja ei tahtonut itsiänsä antaa lohdutettaa, ettei he ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 19, 'Mutta kuin Herodes oli kuollut, katso, niin Herran enkeli ilmestyi Josephille unessa Egyptissä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 20, 'Nouse ja ota lapsi äitinensä, ja mene Israelin maalle; sillä ne ovat kuolleet, jotka lapsen henkeä väijyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 21, 'Niin hän nousi ja otti lapsen äitinensä, ja meni Israelin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 22, 'Mutta kuin hän kuuli, että Arkelaus oli kuningas Juudeassa, isänsä Herodeksen siassa, pelkäsi hän sinne mennä. Ja hän sai Jumalalta käskyn unessa, ja poikkesi Galilean ääriin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 23, 'Ja tuli ja asui kaupungissa, joka kutsutaan Natsaret, että täytettäisiin mitä prophetain kautta sanottu oli: hän pitää Natsarealaiseksi kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 1, 'Niinä päivinä tuli Johannes Kastaja, ja saarnasi Juudean korvessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 2, 'Ja sanoi: tehkäät parannus; sillä taivaan valtakunta on lähestynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 3, 'Sillä tämä on se, josta sanottu on Jesaialta prophetalta, joka sanoo: huutavan ääni on korvessa, valmistakaat Herran tietä, tehkäät hänen polkunsa oikiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 4, 'Mutta Johanneksella oli vaate kamelin karvoista ja hihnainen vyö hänen vyöllänsä, ja hänen ruokansa oli heinäsirkat ja metsähunaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 5, 'Silloin meni hänen tykönsä Jerusalem, ja koko Juudea, ja kaikki maakunta Jordanin ympäriltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 6, 'Ja he kastettiin häneltä Jordanissa, ja tunnustivat heidän syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 7, 'Mutta kuin hän monta Pharisealaisista ja Saddukealaisista näki tulevan kasteensa tykö, sanoi hän heille: te kyykärmetten sikiät, kuka teitä neuvoi pakenemaan tulevaista vihaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 8, 'Tehkäät siis parannuksen soveliaita hedelmiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 9, 'Ja älkäät ajatelko itsellenne sanoa: Abraham on meidän isämme. Millä minä sanon teille: Jumala voi näistä kivistä Abrahamille lapset herättää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 10, 'Mutta jo myös on kirves pantu puiden juurelle: sentähden jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja tuleen heitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 11, 'Minä tosin kastan teitä vedellä parannukseen; mutta se, joka minun jälkeeni tulee, on väkevämpi minua, jonka kenkiä en minä ole kelvollinen kantamaan, hän kastaa teitä Pyhällä Hengellä ja tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 12, 'Jonka viskin on hänen kädessänsä, ja hän perkaa riihensä ja kokoo nisunsa aittaansa, mutta ruumenet polttaa hän sammumattomalla tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 13, 'Silloin tuli Jesus Galileasta Jordaniin Johanneksen tykö, kastettaa häneltä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 14, 'Mutta Johannes kielsi häneltä, sanoen: minä tarvitsen sinulta kastettaa, ja sinä tulet minun tyköni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 15, 'Niin vastasi Jesus ja sanoi hänelle: salli nyt; sillä näin meidän sopii kaikkea vanhurskautta täyttää. Ja hän salli hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 16, 'Kuin Jesus kastettu oli, astui hän kohta ylös vedestä: ja katso, taivaat aukenivat hänelle, ja hän näki Jumalan Hengen tulevan alas, niinkuin kyyhkyisen, ja tulevan hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 17, 'Ja katso, ääni taivaasta sanoi: tämä on se minun rakas Poikani, johonka minä mielistyin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 1, 'Silloin vietiin Jesus hengeltä korpeen kiusattaa perkeleeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 2, 'Ja kuin hän oli paastonnut neljäkymmentä päivää ja neljäkymmentä yötä, sitte hän isosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 3, 'Ja kiusaaja tuli hänen tykönsä ja sanoi: jos sinä olet Jumalan Poika, niin sano, että nämät kivet leiviksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 4, 'Mutta hän vastasi ja sanoi: kirjoitettu on: ei ihminen elä ainoasti leivästä, mutta jokaisesta sanasta, joka Jumalan suusta lähtee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 5, 'Silloin otti perkele hänen kanssansa pyhään kaupunkiin, ja asetti hänen templin harjalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 6, 'Ja sanoi hänelle: jos sinä olet Jumalan Poika, niin laske sinus alaspäin; sillä kirjoitettu on: hän antaa käskyn enkeleillensä sinusta, ja he käsissä kantavat sinun, ettet joskus jalkaas kiveen loukkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 7, 'Niin Jesus sanoi hänelle: taas on kirjoitettu: ei sinun pidä kiusaaman Herraa sinun Jumalaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 8, 'Taas vei hänen perkele sangen korkialle vuorelle, ja osoitti hänelle kaikki maailman valtakunnat ja niiden kunnian,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 9, 'Ja sanoi hänelle: nämät kaikki minä annan sinulle, jos sinä lankeat maahan ja rukoilet minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 10, 'Niin sanoi Jesus hänelle: mene pois, saatana! Sillä kirjoitettu on: Herraa sinun Jumalaas pitää sinun kumartaman, ja häntä ainoaa palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 11, 'Silloin jätti hänen perkele; ja katso, enkelit tulivat ja palvelivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 12, 'Mutta kuin Jesus kuuli, että Johannes oli vankiuteen annettu ylön, poikkesi hän Galileaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 13, 'Ja jätti Natsaretin, tuli ja asui Kapernaumissa, joka on merikaupunki, Zebulonin ja Naphtalin äärissä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 14, 'Että täytettäisiin se mikä sanottu oli Jesaias prophetan kautta, joka sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 15, 'Zebulonin maa ja Naphtalin maa, läsnä meritietä, sillä puolella Jordanin, pakanain Galilea,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 16, 'Kansa, joka pimiässä istui, näki suuren valkeuden, ja niille, jotka kuoleman maassa ja varjossa istuivat, koitti valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 17, 'Siitä ajasta rupesi Jesus saarnaamaan ja sanomaan: tehtäät parannus; sillä taivaan valtakunta lähestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 18, 'Mutta kuin Jesus käveli Galilean meren tykönä, näki hän kaksi veljestä, Simonin, joka kutsutaan Pietariksi, ja Andreaksen hänen veljensä, laskevan verkkoa mereen; (Sillä he olivat kalamiehet,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 19, 'Ja sanoi heille: seuratkaat minua, ja minä teen teidät ihmisten kalamiehiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 20, 'Niin he jättivät kohta verkot ja seurasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 21, 'Ja kuin hän sieltä edemmä kävi, näki hän toiset kaksi veljestä, Jakobin Zebedeuksen pojan ja Johanneksen hänen veljensä, venheessä isänsä Zebedeuksen kanssa, parantavan verkkojansa; ja hän kutsui heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 22, 'Niin he kohta jättivät venheen ja isänsä, ja seurasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 23, 'Ja Jesus vaelsi ympäri kaiken Galilean, ja opetti heidän synagogissansa, ja saarnasi valtakunnan evankeliumia, ja paransi kaikkinaiset taudit ja kaiken sairauden kansan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 24, 'Ja sanoma kuului hänestä kaikkeen Syrian maahan. Ja he toivat hänen tykönsä kaikkinaisia sairaita, moninaisilla taudeilla ja kivuilla vaivatuita ja piruilta riivatuita, ja kuutaudillisia ja halvatuita; ja hän paransi ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 25, 'Ja häntä seurasi paljo väkeä Galileasta ja kymmenestä kaupungista, ja Jerusalemista ja Juudeasta, ja maakunnista sillä puolella Jordania.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 1, 'Mutta kuin hän näki kansan, astui hän ylös vuorelle, ja kuin hän oli istunut, tulivat hänen opetuslapsensa hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 2, 'Niin hän avasi suunsa, opetti heitä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 3, 'Autuaat ovat hengellisesti vaivaiset; sillä heidän on taivaan valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 4, 'Autuaat ovat murheelliset; sillä he saavat lohdutuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 5, 'Autuaat ovat siviät; sillä he saavat maan periä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 6, 'Autuaat ovat, jotka isoovat ja janoovat vanhurskautta; sillä he ravitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 7, 'Autuaat ovat laupiaat; sillä he saavat laupiuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 8, 'Autuaat ovat puhtaat sydämestä; sillä he saavat nähdä Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 9, 'Autuaat ovat rauhan tekiät; sillä ne pitää Jumalan pojiksi kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 10, 'Autuaat ovat, jotka vanhurskauden tähden vainotaan; sillä heidän on taivaan valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 11, 'Autuaat olette te, kuin he pilkkaavat ja vainoovat teitä, ja puhuvat kaikkinaista pahuutta teitä vastaan, valhetellen minun tähteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 12, 'Iloitkaat ja riemuitkaat; sillä teidän palkkanne on suuri taivaissa. Sillä näin he vainosivat prophetaita, jotka teidän edellänne olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 13, 'Te olette maan suola: jos siis suola tulee mauttomaksi, millä sitte suolataan? ei se enään kelpaa mihinkään, vaan heitettää pois ja ihmisiltä tallattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 14, 'Te olette maailman valkeus. Ei sitä kaupunkia taideta peittää, joka vuorella on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 15, 'Eikä kynttilää sytytetä ja panna vakan alle, vaan kynttiläjalkaan, valaisemaan kaikkia, jotka huoneessa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 16, 'Näin valistakoon teidän valkeutenne ihmisten edessä, että he näkisivät teidän hyvät työnne, ja kunnioittaisivat teidän Isäänne, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 17, 'Älkäät luulko, että minä tulin lakia ja prophetaita päästämään: en minä tullut päästämään, vaan täyttämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 18, 'Sillä totisesti sanon minä teille: siihenasti kuin taivas ja maa katoo, ei pidä vähinkään piirto eikä joku rahtu laista katooman, siihenasti kuin kaikki tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 19, 'Kuka siis jonkun näistä vähimmistä käskyistä päästää, ja näin ihmisiä opettaa, hän pitää taivaan valtakunnassa vähimmäksi kutsuttaman; mutta joka sen tekee ja opettaa, se pitää suureksi taivaan valtakunnassa kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 20, 'Sillä minä sanon teille: ellei teidän vanhurskautenne ole paljoa enempi kuin kirjanoppineiden ja Pharisealaisten, niin ette tule taivaan valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 21, 'Te kuulitte mitä sanottu oli vanhoille: ei sinun pidä tappaman; mutta jokainen, joka tappaa, hänen pitää tuomioon vikapää oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 22, 'Mutta minä sanon teille: että jokainen, joka tyhmästi vihastuu veljellensä, hänen pitää tuomioon vikapää oleman; mutta jokainen, joka sanoo veljellensä: raka, hänen pitää neuvon alle vikapää oleman; mutta jokainen, joka sanoo: sinä tyhmä, hänen pitää helvetin tuleen vikapää oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 23, 'Sentähden, jos sinä uhraat lahjas alttarille, ja siellä muistat, että veljelläs on jotakin sinua vastaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 24, 'Niin jätä sinne lahjas alttarin eteen, ja mene ensin sopimaan veljes kanssa, ja tule sitte lahjas uhraamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 25, 'Sovi nopiasti riitaveljes kanssa, koskas vielä hänen kanssansa tiellä olet, ettei riitaveljes anna sinua joskus tuomarille, ja tuomari antaa sinun palvelialle, ja sinä heitetään torniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 26, 'Totisesti sanon minä sinulle: et sinä suinkaan pääse sieltä ulos, siihenasti kuin sinä maksat viimeisen rovon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 27, 'Te kuulitte sanotuksi vanhoille: ei sinun pidä huorin tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 28, 'Mutta minä sanon teille: jokainen, joka katsoo vaimon päälle himoitaksensa häntä, hän teki jo huorin hänen kanssansa sydämessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 29, 'Jos oikia silmäs pahentaa sinun, niin puhkaise se ulos, ja heitä pois tyköäs; sillä parempi on sinulle, että yksi jäsenistäs hukutetaan, kuin että koko ruumis pitäis heitettämän helvettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 30, 'Ja jos oikia kätes pahentaa sinun, niin hakkaa se poikki, ja heitä pois tyköäs! sillä parempi on sinulle, että yksi jäsenistäs hukutetaan, kuin että koko ruumis pitäis helvettiin heitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 31, 'On myös sanottu: jokainen joka emäntänsä hylkää, hän antakaan hänelle erokirjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 32, 'Mutta minä sanon teille: joka emäntänsä hylkää, muutoin kuin huoruuden tähden, hän saattaa hänen huorin tekemään; ja joka nai sen hyljätyn, hän tekee huorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 33, 'Taas te kuulitte sanotuksi vanhoille: älä vanno väärin, vaan pidä valas Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 34, 'Mutta minä sanon teille: älkäät ensinkään vannoko, ei taivaan kautta, sillä se on Jumalan istuin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 35, 'Eikä maan kautta, sillä se on hänen astinlautansa: ei myös Jerusalemin kautta, sillä se on suuren kuninkaan kaupunki:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 36, 'Ei sinun myös pidä vannoman pääs kautta, sillä et sinä voi yhtään hiusta valkiaksi eli mustaksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 37, 'Vaan teidän puheenne pitää oleman: on, on, ei, ei; mutta mitä siihen lisätään, se on pahasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 38, 'Te kuulitte sanotuksi: silmä silmästä, ja hammas hampaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 39, 'Mutta minä sanon teille: älkäät olko pahaa vastaan; vaan joka sinua lyö oikialle poskelle, niin käännä myös hänelle toinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 40, 'Ja joka sinua tahtoo oikeuden eteen, jo ottaa hamees, niin salli myös hänelle muukin vaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 41, 'Ja joka sinua vaatii peninkulman, mene hänen kanssansa kaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 42, 'Anna sille, joka sinulta anoo, ja älä käänny siltä pois, joka lainan pyytää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 43, 'Te kuulitte sanotuksi: rakasta lähimmäistäs, ja vihaa vihollistas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 44, 'Mutta minä sanon teille: rakastakaat vihollisianne; siunatkaat niitä, jotka teitä sadattavat; tehkäät niille hyvin, jotka teitä vihaavat, ja rukoilkaat niiden edestä, jotka teitä vainoovat ja vahingoittavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 45, 'Että te olisitte teidän Isänne pojat, joka on taivaissa; sillä hän sallii aurinkonsa koittaa niin pahain ylitse kuin hyväinkin, ja antaa sataa niin väärille kuin vanhurskaillekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 46, 'Sillä jos te rakastatte niitä, jotka teitäkin rakastavat, mitä teidän siitä palkkaa on? eikö Publikanit myös niin tee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 47, 'Ja jos te ainoastaan veljeinne kanssa soveliaat olette, mitä te sen kanssa erinomaista teette? eikö Publikanit myös niin tee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 48, 'Olkaat siis te täydelliset, niinkuin teidän taivaallinen Isänne täydellinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 1, 'Kavahtakaat, ettette anna almujanne ihmisten edessä, että te heiltä nähtäisiin: niin ette saa palkkaa Isältänne, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 2, 'Kuin siis almua annat, niin älä edelläs torvella soita, niinkuin ulkokullatut synagogissa ja kujilla tekevät, että he ihmisiltä kunnioitettaisiin. Totisesti sanon minä teille: he ovat saaneet palkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 3, 'Mutta kuin sinä almua annat, niin älköön vasen kätes tietäkö, mitä oikia kätes tekee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 4, 'Että almus olis salaisuudessa, ja Isäs, joka salaisuudessa näkee, maksais sinulle julkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 5, 'Ja kuin rukoilet, niin ei sinun pidä oleman niinkuin ulkokullatut; sillä he mielellänsä seisovat ja rukoilevat synagogissa ja kujain kulmissa, että he ihmisiltä nähtäisiin. Totisesti sanon minä teille: he ovat saaneet palkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 6, 'Vaan kuin sinä rukoilet, niin mene kammioos, ja sulje oves, ja rukoile Isääs, joka on salaisuudessa: ja Isäs, joka salaisuudessa näkee, maksaa sinulle julkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 7, 'Ja kuin te rukoilette, niin älkää olko paljon puhuvaiset, niinkuin pakanat; sillä he luulevat heitä paljon puheensa tähden kuultavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 8, 'Sentähden älkäät olko heidän kaltaisensa; sillä Isänne tietää kyllä, mitä tarvitsette, ennen kuin te häneltä rukoilettekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 9, 'Näin teidän siis pitää rukoileman: Isä meidän, joka olet taivaissa! Pyhitetty olkoon sinun nimes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 10, 'Lähestyköön sinun valtakuntas. Olkoon sinun tahtos niin maassa kuin taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 11, 'Anna meille tänäpäivänä meidän jokapäiväinen leipämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 12, 'Ja anna meille meidän velkamme anteeksi, niinkuin mekin anteeksi annamme meidän velvollistemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 13, 'Ja älä johdata meitä kiusaukseen. Mutta päästä meitä pahasta. Sillä sinun on valtakunta, ja voima, ja kunnia, ijankaikkisesti. Amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 14, 'Sillä jos te anteeksi annatte ihmisille heidän rikoksensa, niin myös teidän taivaallinen Isänne antaa teille anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 15, 'Vaan jollette anteeksi anna ihmisille heidän rikoksiansa, niin ei myös teidän Isänne anteeksi anna teidän rikoksianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 16, 'Mutta kuin te paastootte, niin älkäät olko surulliset niinkuin ulkokullatut; sillä he muuttavat muotonsa, että he ihmisiltä nähtäisiin paastoovan. Totisesti sanon minä teille: he ovat saaneet palkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 17, 'Vaan sinä kuin paastoot, niin voitele pääs ja pese kasvos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 18, 'Ettet ihmisiltä nähtäis paastoovan, mutta Isältäs, joka on salaisuudessa: ja Isäs, joka salaisuudessa näkee, maksaa sinulle julkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 19, 'Älkäät tavaraa kootko maan päällä, kussa koi ja ruoste raiskaavat, ja kussa varkaat kaivavat ja varastavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 20, 'Vaan kootkaat teillenne tavaraa taivaassa, kussa ei koi eikä ruoste raiskaa, ja kussa ei varkaat kaiva eikä varasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 21, 'Sillä kussa teidän tavaranne on, siellä on myös teidän sydämenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 22, 'Silmä on ruumin valkeus; jos siis silmäs on yksinkertainen, niin koko ruumiis on valaistu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 23, 'Mutta jos silmäs on paha, niin koko ruumiis on pimiä. Jos siis se valkeus, joka sinussa on, on pimeys, kuinka suuri on itse pimeys?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 24, 'Ei kenkään voi palvella kahta herraa; sillä taikka hän tätä vihaa ja toista rakastaa, taikka hän tähän suostuu ja toisen ylönkatsoo. Ette voi palvella Jumalaa ja mammonaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 25, 'Sentähden sanon minä teille: älkäät murehtiko henkenne tähden, mitä te syötte ja mitä te juotte, eikä ruumiinne tähden, millä te teitänne verhootte. Eikö henki enempi ole kuin ruoka? ja ruumis parempi kuin vaate?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 26, 'Katsokaat taivaan lintuja, ei he kylvä eikä niitä, ei myös kokoa riiheen, ja teidän taivaallinen Isänne ruokkii heidät. Ettekö te paljoa enempi ole kuin he?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 27, 'Mutta kuka teistä voi surullansa lisätä yhden kyynärän pituudellensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 28, 'Ja mitä te surette vaatteista? Katsokaat kukkasia kedolla, kuinka he kasvavat: ei he työtä tee, eikä kehrää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 29, 'Kuitenkin sanon minä teille, ettei Salomon kaikessa kunniassansa ollut niin vaatetettu kuin yksi heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 30, 'Jos Jumala näin vaatettaa pellon ruohon, joka tänäpänä seisoo ja huomenna pätsiin heitetään, eikö hän paljoa enemmin teidän sitä tee, te vähäuskoiset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 31, 'Älkäät siis surulliset olko, sanoen: mitä me syömme, taikka mitä me juomme? eli millä me meitämme verhoomme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 32, 'Sillä kaikkia näitä pakanat etsivät; sillä teidän taivaallinen Isänne kyllä tietää teidän kaikkia näitä tarvitsevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 33, 'Vaan etsikäät ensin Jumalan valtakuntaa ja hänen vanhurskauttansa, ja niin kaikki nämät teille annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 34, 'Älkäät sentähden sureko huomisesta päivästä; sillä huomisella päivällä on suru itsestänsä. Tyytykään kukin päivä surullensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 1, 'Älkäät tuomitko, ettei teitä tuomittaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 2, 'Sillä millä tuomiolla te tuomitsette, pitää teitä tuomittaman, ja sillä mitalla, jolla te mittaatte, pitää teille jälleen mitattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 3, 'Miksis siis näet raiskan, joka on veljes silmässä, ja et äkkää malkaa omassa silmässäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 4, 'Taikka, kuinka sinä sanot veljelles: pidäs, minä otan raiskan silmästäs; ja katso, malka on omassa silmässäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 5, 'Sinä ulkokullattu, heitä ensin malka ulos sinun silmästäs, ja katso sitte, kuinka saisit raiskan ulos veljes silmästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 6, 'Älkäät antako koirille pyhää, ja älkäät päärlyjänne heittäkö sikain eteen, ettei he niitä joskus tallaa jaloillansa, ja käännä itsiänsä, ja repele teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 7, 'Anokaat, niin teille annetaan: etsikäät, niin te löydätte: kolkuttakaat, niin teille avataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 8, 'Sillä jokainen, joka anoo, hän saa, ja joka etsii, hän löytää, ja kolkuttavalle avataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 9, 'Eli onko teistä joku ihminen, jolta hänen poikansa anois leipää: antaisko hän hänelle kiven?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 10, 'Eli jos hän kalaa anois: antaisko hän hänelle käärmeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 11, 'Jos siis te, jotka pahat olette, taidatte hyviä lahjoja antaa teidän lapsillenne, kuinka paljoa enempi teidän Isänne, joka on taivaissa, antaa niille hyviä, jotka häneltä anovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 12, 'Kaikki siis, mitä te tahdotte, että ihmiset pitää teille tekemän, niin te myös heille tehkäät; sillä tämä on laki ja prophetat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 13, 'Menkäät ahtaasta portista sisälle; sillä se portti on lavia ja avara tie, joka vie kadotukseen, ja niitä on monta, jotka siitä sisälle menevät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 14, 'Ja se portti on ahdas, ja tie kaita, joka vie elämään, ja harvat ovat, jotka sen löytävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 15, 'Mutta kavahtakaat teitänne vääristä prophetaista, jotka teidän tykönne lammasten vaatteilla tulevat, mutta sisältä he ovat raatelevaiset sudet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 16, 'Heidän hedelmistänsä te tunnette heidät: hakeeko joku viinamarjoja orjantappuroista, taikka fikunia ohdakkeista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 17, 'Niin jokainen hyvä puu kasvaa hyvät hedelmät; mutta mädännyt puu kasvaa häijyt hedelmät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 18, 'Hyvä puu ei taida häijyjä hedelmiä kasvaa, eikä mädännyt puu hyviä hedelmiä kasvaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 19, 'Jokainen puu, joka ei kasva hyvää hedelmää, hakataan pois, ja tuleen heitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 20, 'Sentähden tuntekaat heitä hedelmistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 21, 'Ei jokainen, joka sanoo minulle: Herra, Herra! pidä tuleman taivaan valtakuntaan; mutta joka tekee minun isäni tahdon, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 22, 'Moni sanoo minulle sinä päivänä: Herra, Herra! emmekö me sinun nimes kautta ennustaneet, ja sinun nimelläs ajaneet ulos perkeleitä, ja ole sinun nimes kautta monta väkevää työtä tehneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 23, 'Ja silloin minä tunnustan, en minä teitä ikänä tuntenut: menkäät pois minun tyköäni, te väärintekiät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 24, 'Sentähden jokaisen, joka minulta nämät puheet kuulee ja ne tekee, vertaan minä toimelliseen mieheen, joka huoneensa kalliolle rakensi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 25, 'Ja sade lankesi, ja virrat tulivat, ja tuulet puhalsivat, ja sitä huonetta sysäsivät, joka ei kuitenkaan kukistunut; sillä se oli kalliolle perustettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 26, 'Ja jokainen, joka kuulee minulta nämä puheet, ja ei tee niitä, hän verrataan tyhmään mieheen, joka huoneensa sannalle rakensi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 27, 'Ja sade lankesi, ja virrat tulivat, ja tuulet puhalsivat, ja sitä huonetta sysäsivät, joka kukistui, ja sen lankeemus oli suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 28, 'Ja se tapahtui, kuin Jesus oli lopettanut nämät puheet, että kansat hämmästyivät hänen oppiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 29, 'Sillä hän opetti heitä voimallisesti, ja ei niinkuin kirjanoppineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 1, 'Kuin hän astui alas vuorelta, seurasi häntä paljo kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 2, 'Ja katso, niin tuli spitalinen mies, kumarsi häntä ja sanoi: Herra, jos sinä tahdot, niin sinä voit minun puhdistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 3, 'Niin Jesus ojensi kätensä ja rupesi häneen, sanoen: minä tahdon, ole puhdas. Ja hän puhdistettiin kohta spitalistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 4, 'Ja Jesus sanoi hänelle: katso, ettet kenellekään sano: mutta mene ja näytä itses papille, ja uhraa lahjas, jonka Moses on käskenyt, heille todistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 5, 'Mutta kuin Jesus meni Kapernaumiin, tuli sadanpäämies hänen tykönsä, ja rukoili häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 6, 'Ja sanoi: Herra! minun palveliani sairastaa kotona halvattuna, ja kovin vaivataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 7, 'Jesus sanoi hänelle: minä tulen ja parannan hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 8, 'Niin sadanpäämies vastasi ja sanoi: Herra, en ole minä mahdollinen, että sinä tulet minun kattoni alle; vaan sano ainoasti sana, niin palveliani paranee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 9, 'Sillä minä olen myös ihminen toisen vallan alla, ja minun allani on sotamiehiä, ja sanon tälle: mene! ja hän menee, ja toiselle: tule! ja hän tulee, ja palvelialleni: tee tämä! ja hän tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 10, 'Kuin Jesus tämän kuuli, ihmetteli hän, ja sanoi heille, jotka seurasivat: totisesti sanon minä teille: en ole minä löytänyt senkaltaista uskoa Israelissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 11, 'Mutta minä sanon teille: monta tulevat idästä ja lännestä, ja pitää Abrahamin, Isaakin ja Jakobin kanssa taivaan valtakunnassa istuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 12, 'Mutta valtakunnan lapset heitetään ulkonaiseen pimeyteen: siellä pitää oleman itku ja hammasten kiristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 13, 'Ja Jesus sanoi sadanpäämiehelle: mene, ja niinkuin sinä uskoit, niin sinulle tapahtukoon. Ja sillä hetkellä parani hänen palveliansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 14, 'Ja kuin Jesus tuli Pietarin huoneeseen, näki hän hänen anoppinsa makaavan ja sairastavan vilutautia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 15, 'Niin hän tarttui hänen käteensä, ja vilutauti luopui hänestä. Ja hän nousi, ja palveli heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 16, 'Mutta kuin ehtoo tuli, niin he toivat hänen tykönsä monta pirulta riivattua; ja hän ajoi ulos sanalla henget, ja teki kaikkinaisia sairaita terveeksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 17, 'Että täytettäisiin, mitä sanottu oli Jesaias prophetan kautta, joka sanoo: hän on ottanut meidän heikkoutemme, ja hän kantoi meidän tautimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 18, 'Kuin Jesus näki paljon kansaa ympärillänsä, käski hän mennä toiselle puolelle (merta).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 19, 'Ja kirjanoppinut tuli ja sanoi hänelle: Mestari, minä tahdon sinua seurata, kuhunka ikänä sinä menet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 20, 'Niin Jesus sanoi hänelle: ketuilla ovat luolat, ja taivaan linnuilla ovat pesät; mutta Ihmisen Pojalla ei ole, kuhunka hän päänsä kallistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 21, 'Toinen hänen opetuslapsistansa sanoi hänelle: Herra, salli minun ensin mennä hautaamaan isääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 22, 'Niin Jesus sanoi hänelle: seuraa minua, ja anna kuolleet haudata kuolleitansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 23, 'Ja kuin hän oli haahteen astunut, seurasivat häntä hänen opetuslapsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 24, 'Mutta katso, suuri ilma nousi merellä, niin että haaksi aalloilta peitettiin. Mutta hän makasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 25, 'Niin tulivat hänen opetuslapsensa ja herättivät hänen, ja sanoivat: Herra, auta meitä, me hukumme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 26, 'Ja hän sanoi heille: te heikko-uskoiset, miksi te olette pelkurit? Niin hän nousi ja asetti tuulen ja meren, ja tuli juuri tyveneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 27, 'Niin ihmiset ihmettelivät, sanoen: millainen tämä on? sillä tuulet ja meri ovat myös hänelle kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 28, 'Ja kuin hän tuli sille puolelle merta, Gerasalaisten maakuntaan, niin häntä vastaan juoksi kaksi pirulta riivattua, jotka olivat haudoista lähteneet, ja olivat sangen hirmuiset, niin ettei kenkään taitanut sitä tietä vaeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 29, 'Ja katso, he huusivat sanoen: Jesus, Jumalan Poika, mitä meidän on sinun kanssas? Oletkos tullut tänne meitä vaivaamaan ennen aikaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 30, 'Ja kaukana heistä kävi sangen suuri sikalauma laitumella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 31, 'Niin perkeleet rukoilivat häntä ja sanoivat: jos ajat meidät ulos, niin salli meidän mennä sikalaumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 32, 'Ja hän sanoi heille: menkäät. Niin he läksivät ulos ja menivät sikalaumaan; ja katso, koko sikalauma syöksi äkisti itsensä jyrkältä mereen ja upposi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 33, 'Mutta paimenet pakenivat ja menivät kaupunkiin ja ilmoittivat kaikki, ja kuinka pirulta riivatuille oli tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 34, 'Ja katso, koko kaupunki meni ulos Jesusta vastaan. Ja kuin he hänen näkivät, rukoilivat he häntä menemään pois heidän maansa ääristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 1, 'Ja hän astui haahteen, meni jälleen ylitse ja tuli omaan kaupunkiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 2, 'Ja katso, he toivat hänen eteensä halvatun, joka makasi vuoteella. Ja kuin Jesus näki heidän uskonsa, sanoi hän halvatulle: poikani, ole hyvässä turvassa, syntis annetaan anteeksi sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 3, 'Ja katso, muutamat kirjanoppineista sanoivat keskenänsä: tämä pilkkaa (Jumalaa).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 4, 'Ja kuin Jesus näki heidän ajatuksensa, sanoi hän: miksi ajattelette pahaa sydämessänne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 5, 'Sillä kumpi on keviämpi sanoa: synnit annetaan anteeksi sinulle, taikka sanoa: nouse ja käy?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 6, 'Mutta että teidän pitää tietämän Ihmisen Pojalla olevan vallan maan päällä synnit anteeksi antaa, (niin sanoi hän halvatulle:) nouse ja ota vuotees, ja mene kotias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 7, 'Ja hän nousi ja meni kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 8, 'Ja kuin kansa sen näki, ihmettelivät he ja kunnioittivat Jumalaa, joka oli ihmisille antanut senkaltaisen vallan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 9, 'Ja kuin Jesus sieltä kävi ohitse, näki hän ihmisen istuvan tullihuoneessa, nimeltä Matteus, ja sanoi hänelle: seuraa minua. Niin hän nousi ja seurasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 10, 'Ja tapahtui, kuin hän atrioitsi huoneessa, katso, niin tuli monta Publikania ja syntistä, ja atrioitsivat Jesuksen ja hänen opetuslastensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 11, 'Ja kuin Pharisealaiset sen näkivät, sanoivat he hänen opetuslapsillensa: miksi teidän Mestarinne syö Publikanien ja syntisten kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 12, 'Mutta kuin Jesus sen kuuli, sanoi hän heille: ei terve tarvitse parantajaa, vaan sairaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 13, 'Mutta menkäät ja oppikaat, mikä se on: laupiutta minä tahdon, enkä uhria; sillä en minä tullut vanhurskaita kutsumaan, vaan syntisiä parannukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 14, 'Silloin tulivat Johanneksen opetuslapset hänen tykönsä, ja sanoivat: minkätähden me ja Pharisealaiset niin paljo paastoomme, mutta ei sinun opetuslapses paastoo?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 15, 'Niin Jesus sanoi heille: taitaako hääjoukko niinkauvan murehtia, kuin ylkä on heidän kanssansa? mutta päivät tulevat, että ylkä otetaan heiltä pois, ja silloin heidän pitää paastooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 16, 'Mutta ei kenkään paikkaa vanhaa vaatetta uuden veran tilalla; sillä paikka repee pois vaatteesta, ja läpi tulee pahemmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 17, 'Ei myös pane kenkään nuorta viinaa vanhoihin leileihin; muutoin leilit pakahtuvat, ja viina vuotaa pois, ja leilit turmellaan; vaan nuorta viinaa lasketaan uusiin leileihin, ja niin he molemmat tähdellä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 18, 'Kuin hän nämät heille puhunut oli, katso, niin päämies tuli ja kumarsi häntä, sanoen: nyt on minun tyttäreni kuolemallansa; mutta tule ja pane kätes hänen päällensä, niin hän virkoaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 19, 'Niin Jesus nousi ja seurasi häntä, ja hänen opetuslapsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 20, 'Ja katso, vaimo, joka oli kaksitoistakymmentä ajastaikaa punaista tautia sairastanut, kävi takana, ja tarttui hänen vaatteensa liepeeseen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 21, 'Sillä hän oli itsellensä sanonut; jos minä ainoastaan rupeen hänen vaatteesensa, niin minä tulen terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 22, 'Niin Jesus käänsi itsensä, näki hänen ja sanoi: ole hyvässä turvassa, tyttäreni! sinun uskos on sinun terveeksi tehnyt. Ja vaimo tuli sillä hetkellä terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 23, 'Ja kuin Jesus tuli päämiehen huoneeseen, ja näki pillein soittajat ja kansan hymisevän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 24, 'Sanoi hän heille: menkäät pois; sillä ei piika ole kuollut, vaan hän makaa. Ja he nauroivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 25, 'Mutta kuin kansa oli ajettu ulos, meni hän sisälle ja tarttui hänen käteensä, ja piika nousi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 26, 'Ja sen sanoma kuului kaikkeen siihen maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 27, 'Ja kuin Jesus sieltä läksi, seurasi häntä kaksi sokiaa, huutain ja sanoen: Davidin poika, armahda meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 28, 'Ja kuin hän tuli huoneeseen, tulivat sokiat hänen tykönsä, ja Jesus sanoi heille: uskotteko minun sen voivan teille tehdä? He sanoivat hänelle: Herra, me uskomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 29, 'Niin hän rupesi heidän silmiinsä, sanoen: tapahtukoon teille uskonne jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 30, 'Ja heidän silmänsä aukenivat. Niin Jesus haastoi heitä, sanoen: katsokaat, ettei kenkään saa tätä tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 31, 'Vaan kuin he menivät pois, niin he julistivat hänen sanomansa kaikessa siinä maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 32, 'Kuin nämät olivat menneet ulos, katso, niin he toivat mykän ja pirulta riivatun ihmisen hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 33, 'Ja kuin perkele oli ajettu ulos, niin mykkä puhui. Ja kansa ihmetteli ja sanoi: ei senkaltaista ole ikänä Israelissa nähty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 34, 'Mutta Pharisealaiset sanoivat: hän ajaa ulos perkeleet perkeleitten pääruhtinasten kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 35, 'Ja Jesus kävi kaikkia kaupungeita ja kyliä ympäri, ja opetti heidän synagogissansa, ja saarnasi valtakunnan evankeliumia, ja paransi kaikkinaisia tauteja ja kaikkea sairautta kansassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 36, 'Ja kuin hän näki kansat, armahti hän heidän päällensä, että he olivat niin nääntyneet ja hajoitetut kuin lampaat, joilla ei ole paimenta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 37, 'Silloin hän sanoi opetuslapsillensa: eloa on tosin paljo, mutta työväkeä on vähä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 38, 'Rukoilkaat sentähden elon Herraa, että hän työväkeä lähettäis eloonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 1, 'Ja hän kutsui tykönsä kaksitoistakymmentä opetuslastansa, ja antoi heille vallan riettaisia henkiä vastaan, niitä ajaa ulos, ja parantaa kaikkinaisia tauteja ja kaikkea sairautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 2, 'Mutta nämät ovat kahdentoistakymmenen apostolin nimet: ensimmäinen Simon, joka Pietariksi kutsutaan, ja Andreas, hänen veljensä, Jakobus Zebedeuksen poika, ja Johannes, hänen veljensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 3, 'Philippus ja Bartolomeus, Tomas ja Matteus, Publikani, Jakobus Alpheuksen poika, ja Lebbeus, liialta nimeltä Taddeus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 4, 'Simon Kananeus ja Juudas Iskariot, joka myös hänen petti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 5, 'Nämät kaksitoistakymmentä lähetti Jesus, joille hän oli käskenyt, sanoen: älkäät menkö pakanain teille, ja Samarialaisten kaupunkiin älkäät sisälle menkö;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 6, 'Mutta menkäät paremmin kadotettuin lammasten tykö Israelin huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 7, 'Niin menkäät ja saarnatkaat, sanoen: taivaan valtakunta on lähestynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 8, 'Sairaita parantakaat, spitalisia puhdistakaat, kuolleita herättäkäät, perkeleitä ajakaat ulos. Lahjaksi te saitte, niin myös lahjaksi antakaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 9, 'Ei teidän pidä varustaman itsiänne kullalla eikä hopialla, eikä vaskella teidän vyöllenne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 10, 'Eikä evässäkillä matkalle, eikä kahdella hameella, eikä kengillä, eikä sauvalla; sillä työmies on ruokansa ansainnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 11, 'Vaan kuhunka ikänä kaupunkiin taikka kylään te sisälle menette, niin kyselkäät, kuka siinä on mahdollinen, ja olkaat siellä siihenasti kuin te lähdette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 12, 'Mutta kuin te huoneeseen sisälle menette, niin tervehtikäät sitä (ja sanokaat: rauha olkoon tälle huoneelle!)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 13, 'Ja jos huone on mahdollinen, niin tulkaan teidän rauhanne hänelle; jollei hän ole mahdollinen, niin teidän rauhanne teille palajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 14, 'Ja kussa ei kenkään ota teitä vastaan eikä kuule teidän sanojanne, niin menkäät ulos siitä huoneesta taikka siitä kaupungista, ja puhdistakaat tomu jaloistanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 15, 'Totisesti sanon minä teille: huokeampi pitää oleman Sodoman ja Gomorran maalle tuomiopäivänä kuin sille kaupungille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 16, 'Katso, minä lähetän teidät niinkuin lampaat sutten keskelle: olkaat sentähden taitavat niinkuin käärmeet, ja vakaat niinkuin kyyhkyiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 17, 'Mutta kavahtakaat ihmisiä; sillä he ylönantavat teidät raastupiinsa, ja synagogissansa he hosuvat teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 18, 'Te viedään myös päämiesten ja kuningasten eteen minun tähteni, heille ja pakanoille todistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 19, 'Kuin he teitä ylönantavat, älkäät murehtiko, kuinka eli mitä teidän pitää puhuman; sillä teille annetaan sillä hetkellä, mitä teidän pitää puhuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 20, 'Sillä ette te ole, jotka puhutte, vaan teidän Isänne Henki, joka teissä puhuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 21, 'Mutta veli antaa ylön veljensä kuolemaan, ja isä pojan, ja lapset karkaavat vanhempia vastaan, ja antavat tappaa heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 22, 'Ja te tulette vihattavaksi kaikilta minun nimeni tähden. Mutta joka loppuun asti vahvana pysyy, hän tulee autuaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 23, 'Mutta koska he teitä siinä kaupungissa vainoovat, niin paetkaat toiseen. Totisesti sanon minä teille: ette ehdi kaikkia Israelin kaupungeita toimittaa, siihenasti kuin Ihmisen Poika tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 24, 'Ei ole opetuslapsi parempi opettajaansa, eikä palvelia parempi isäntäänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 25, 'Siinä on opetuslapselle kyllä, että hän on niinkuin hänen opettajansa, ja palvelia niinkuin hänen isäntänsä. Jos he ovat itse isännän beelsebubiksi kutsuneet, kuinka paljoa ennemmin he hänen perheensä kutsuvat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 26, 'Älkäät sentähden heitä peljätkö; sillä ei ole mitään peitetty, joka ei pidä ilmoitettaman, ja salattu, joka ei tule tiettäväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 27, 'Jota minä teille pimeissä sanon, sitä sanokaat valkeudessa, ja mitä te korvissanne kuulette, sitä saarnatkaat kattoin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 28, 'Ja älkäät peljätkö niitä, jotka ruumiin tappavat, ja ei voi sielua tappaa; mutta peljätkäät enemmin sitä, joka voi sekä sielun että ruumiin helvetissä hukuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 29, 'Eikö kaksi varpusta yhteen ropoon myydä? ja yksi heistä ei putoo maan päälle ilman teidän Isättänne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 30, 'Niin ovat myös kaikki teidän päänne hiukset luetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 31, 'Älkäät siis peljätkö: te olette paremmat, kuin monta varpusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 32, 'Sentähden jokainen joka minun tunnustaa ihmisten edessä, sen tunnustan myös minä Isäni edessä, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 33, 'Mutta joka minun kieltää ihmisten edessä, hänen minä myös kiellän Isäni edessä, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 34, 'Älkäät luulko, että minä olen tullut rauhaa lähettämään maan päälle: en ole minä tullut rauhaa, vaan miekkaa lähettämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 35, 'Sillä minä tulin ihmistä isäänsä vastaan riitaiseksi tekemään, ja tytärtä äitiänsä vastaan ja miniää anoppiansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 36, 'Ja ihmisen vihamiehet on hänen perheensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 37, 'Joka rakastaa isäänsä taikka äitiänsä enempi kuin minua, ei se ole minulle sovelias; joka rakastaa poikaansa taikka tytärtänsä enempi kuin minua, ei se ole minulle sovelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 38, 'Ja kuka ei ota ristiänsä ja seuraa minua, ei se ole minulle sovelias;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 39, 'Joka löytää henkensä, hänen pitää sen hukuttaman, ja joka henkensä hukuttaa minun tähteni, hänen pitää sen löytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 40, 'Joka teitä holhoo, hän holhoo minua, ja joka minua holhoo, hän holhoo sitä, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 41, 'Joka prophetaa holhoo prophetan nimellä, hän saa prophetan palkan, ja joka vanhurskasta holhoo vanhurskaan nimellä, hän saa vanhurskaan palkan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 42, 'Ja kuka ikänä juottaa yhden näistä vähimmistä kylmällä vesipikarilla ainoastaan, opetuslapsen nimellä, totisesti sanon minä teille: ei hän pidä palkatta oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 1, 'Ja tapahtui, kuin Jesus lakkasi senkaltaisia kahdelletoistakymmenelle opetuslapsellensa käskemästä, meni hän sieltä edemmä opettamaan ja saarnaamaan heidän kaupunkeihinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 2, 'Mutta kuin Johannes vankiudessa kuuli Kristuksen työt, lähetti hän kaksi opetuslastansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 3, 'Sanomaan hänelle: oletko sinä se tuleva, eli pitääkö meidän toista odottaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 4, 'Niin Jesus vastasi ja sanoi heille: menkäät ja sanokaat jälleen Johannekselle, ne mitkä te kuulette ja näette:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 5, 'Sokiat saavat näkönsä, ja ontuvat käyvät, spitaliset puhdistetaan, ja kuurot kuulevat, kuolleet herätetään, ja köyhille saarnataan evankeliumi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 6, 'Ja autuas on se, joka ei pahene minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 7, 'Kuin he menivät pois, rupesi Jesus sanomaan kansalle Johanneksesta: mitä te läksitte korpeen katsomaan? ruokoako, joka tuulelta häälytetään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 8, 'Taikka mitä te läksitte katsomaan? ihmistäkö, vaatetettua pehmeillä vaatteilla? Katso, jotka pehmeitä kantavat, ne ovat kuningasten huoneissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 9, 'Taikka mitä te läksitte katsomaan? Prophetaako? totisesti sanon minä teille: tämä on jalompi kuin propheta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 10, 'Sillä tämä on se, josta kirjoitettu on: katso, minä lähetän enkelini sinun kasvois eteen, joka on valmistava sinun ties sinun etees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 11, 'Totisesti sanon minä teille: kaikkein niiden seassa, jotka vaimoista syntyneet ovat, ei ole yhtäkään suurempaa kuin Johannes Kastaja tullut; mutta kuitenkin se, joka vähin on taivaan valtakunnassa, on häntä suurempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 12, 'Mutta hamasta Johannes Kastajan päivistä, niin tähän asti, kärsii taivaan valtakunta väkivaltaa, ja väkevät repivät sen itsellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 13, 'Sillä kaikki prophetat ja laki ovat Johannekseen asti ennustaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 14, 'Ja jos te tahdotte ottaa vastaan: hän on se Elias, joka tuleva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 15, 'Jolla on korvat kuulla, se kuulkaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 16, 'Vaan minkä verraksi minä tämän sukukunnan vedän? hän on lasten vertainen, jotka turulla istuvat ja huutavat kumppaneillensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 17, 'Ja sanovat: me soitimme huilua teidän edessänne, ja ette hypänneet: me olemme veisanneet teille murhevirsiä, ja ette itkeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 18, 'Sillä Johannes tuli ei syöden eikä juoden, ja he sanovat: hänellä on perkele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 19, 'Ihmisen Poika tuli syöden ja juoden, ja he sanovat: katso ihmistä, syömäriä ja viinan juomaria, Publikanein ja syntisten ystävää. Mutta viisaus vanhurskautetaan lapsiltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 20, 'Silloin hän rupesi soimaamaan niitä kaupungeita, joissa olivat tehdyt usiammat hänen väkevät työnsä, ettei he itsiänsä parantaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 21, 'Voi sinuas Koratsin, voi sinus Betsaida! Jos senkaltaiset väkevät työt olisivät tehdyt Tyrossa ja Sidonissa kuin teissä tehdyt ovat, niin he olisivat aikaa säkissä ja tuhassa tehneet parannuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 22, 'Jonka tähden sanon minä teille: Tyrolle ja Sidonille pitää oleman huokiamman tuomiopäivänä kuin teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 23, 'Ja sinä Kapernaum, joka olet korotettu taivaaseen asti! sinä pitää hamaan helvettiin sysättämän; sillä jos Sodomassa olisivat senkaltaiset väkevät työt tehdyt kuin sinussa, niin he vielä tänäpänä seisoisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 24, 'Jonka tähden sanon minä teille: Sodoman maalle pitää huokiamman oleman tuomiopäivänä kuin sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 25, 'Sillä ajalla vastasi Jesus ja sanoi: minä kiitän sinua, Isä, taivaan ja maan Herra, ettäs olet kätkenyt nämät viisailta ja toimellisilta, ja olet ne ilmoittanut pienille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 26, 'Tosin Isä, sillä niin oli sinun hyvä tahtos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 27, 'Kaikki ovat minulle annetut minun Isältäni, ja ei kenkään tunne Poikaa, mutta Isä; eikä Isää tunne yksikään, mutta Poika, ja kenelle ikänä Poika tahtoo sen ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 28, 'Tulkaat minun tyköni kaikki, jotka työtä teette ja olette raskautetut, ja minä tahdon teitä virvoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 29, 'Ottakaat minun ikeeni teidän päällenne, ja oppikaat minusta, että minä olen siviä ja nöyrä sydämestä: ja te löydätte levon teidän sieluillenne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 30, 'Sillä minun ikeeni on sovelias ja minun kuormani on keviä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 1, 'Siihen aikaan kävi Jesus sabbatina laihoin lävitse; niin hänen opetuslapsensa isosivat, ja rupesivat tähkäpäitä noukkimaan ja syömään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 2, 'Mutta kuin Pharisealaiset sen näkivät, sanoivat he hänelle: katso, sinun opetuslapses tekevät sitä, mitä ei sovi sabbatina tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 3, 'Mutta hän sanoi heille: ettekö te ole lukeneet, mitä David teki, kuin hän isosi, ja ne, jotka hänen kanssansa olivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 4, 'Kuinka hän meni Jumalan huoneeseen, ja söi näkyleivät, joita ei hänen sopinut syödä, eikä niidenkään, jotka hänen kanssansa olivat, mutta ainoastaan pappein?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 5, 'Taikka ettekö te laissa ole lukeneet, että papit sabbatina rikkovat templissä sabbatin, ja ovat kuitenkin nuhteettomat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 6, 'Mutta minä sanon teille: tässä on se, joka on suurempi kuin templi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 7, 'Mutta jos te tietäisitte, mikä se on: laupiutta minä tahdon, ja en uhria, sitte ette suinkaan tuomitsisi viattomia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 8, 'Sillä Ihmisen Poika on myös sabbatin Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 9, 'Ja hän läksi sieltä, ja tuli heidän synagogaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 10, 'Ja katso, siellä oli ihminen, jolla oli kuivettunut käsi. Ja he kysyivät häneltä, sanoen: sopiiko sabbatina parantaa? että he olisivat saaneet kantaa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 11, 'Niin hän sanoi heille: kuka on teistä ihminen, jolla olis yksi lammas, ja jos se sabbatina putoais kaivoon, eikö hän tarttuisi siihen ja vetäisi ylös?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 12, 'Kuinka paljoa jalompi on ihminen kuin lammas? Sentähden sopii kyllä sabbatina hyvää tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 13, 'Niin hän sanoi sille ihmiselle: ojenna kätes! ja hän ojensi, ja se tuli terveeksi niinkuin toinenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 14, 'Mutta Pharisealaiset menivät ja neuvoa pitivät häntä vastaan, kuinka he hänen hukuttaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 15, 'Mutta kuin Jesus sen ymmärsi, meni hän sieltä pois, ja paljo kansaa seurasi häntä, ja hän teki kaikki terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 16, 'Ja hän haastoi heitä, häntä ilmoittamasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 17, 'Että täytettäisiin, mitä sanottu oli Jesaias prophetan kautta, joka sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 18, 'Katso, minun palveliani, jonka minä valitsin, minun rakkaani, johonka minun sieluni mielistyi: minä panen hänen päällensä minun henkeni, ja hänen pitää tuomion pakanoille julistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 19, 'Ei hän riitele eikä huuda, eikä yhdenkään pidä kuuleman hänen ääntänsä kujilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 20, 'Särjettyä ruokoa ei hänen pidä murentaman ja suitsuvaista kynttilän sydäntä ei hänen pidä sammuttaman, siihenasti kuin hän saattaa tuomion voitoksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 21, 'Ja hänen nimensä päälle pitää pakanain toivoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 22, 'Silloin tuotiin hänen tykönsä pirulta riivattu, sokia ja mykkä; ja hän paransi hänen, niin että sokia ja mykkä sekä puhui että näki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 23, 'Ja kaikki kansa hämmästyi ja sanoi: olleeko tämä se Davidin poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 24, 'Mutta kuin Pharisealaiset sen kuulivat, sanoivat he: ei tämä aja ulos perkeleitä, vaan beelsebubin, perkeleitten päämiehen, kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 25, 'Mutta kuin Jesus tiesi heidän ajatuksensa, sanoi hän heille: jokainen valtakunta, itsiänsä vastaan erinnyt, tulee kylmille, ja jokainen kaupunki taikka huone, itsiänsä vastaan erinnyt, ei seiso.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 26, 'Ja jos saatana ajaa ulos saatanan, niin hän on erinnyt itsiänsä vastaan: kuinka siis hänen valtakuntansa seisois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 27, 'Ja jos minä beelsebubin kautta ajaisin perkeleitä ulos, kenenkä kautta siis poikanne ajavat niitä ulos? Sentähden pitää heidän oleman teidän tuomarinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 28, 'Mutta jos minä ajan ulos perkeleitä Jumalan Hengellä, niin Jumalan valtakunta tuli teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 29, 'Taikka kuinka joku taitaa jonkun väkevän huoneeseen mennä, ja hänen kaluansa ryöstää, ellei hän ensin sido väkevää, ja sitte ryöstä hänen huonettansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 30, 'Joka ei ole minun kanssani, hän on minua vastaan, ja joka ei minun kanssani kokoo, hän hajoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 31, 'Sentähden sanon minä teille: kaikki synnit ja pilkka annetaan ihmisille anteeksi; mutta pilkkaa Henkeä vastaan ei anteeksi anneta ihmisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 32, 'Ja kuka ikänä sanoo jonkun sanan Ihmisen Poikaa vastaan, se hänelle anteeksi annetaan; mutta joka sanoo jotakin Pyhää Henkeä vastaan, ei sitä hänelle anteeksi anneta, ei tässä eikä tulevaisessa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 33, 'Taikka tehkäät hyvä puu, niin hänen hedelmänsä tulee hyväksi, taikka tehkäät mädännyt puu, niin hänen hedelmänsä tulee mädänneeksi; sillä hedelmästä puu tunnetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 34, 'Te kyykärmetten sikiät, kuinka te taidatte hyvää puhua, koska te itse pahat olette? sillä sydämen kyllyydestä suu puhuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 35, 'Hyvä ihminen tuo edes hyvästä sydämen tavarasta hyviä, ja paha ihminen tuo edes pahasta tavarasta pahoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 36, 'Mutta minä sanon teille: jokaisesta turhasta sanasta, jonka ihmiset puhuvat, pitää heidän luvun tekemän tuomiopäivänä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 37, 'Sillä sanoistas sinä hurskaaksi tehdään, ja sanoistas sinä tuomitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 38, 'Silloin vastasivat muutamat kirjanoppineista ja Pharisealaisista, sanoen: Mestari, me tahdomme nähdä sinulta merkkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 39, 'Niin hän vastasi ja sanoi heille: tämä häijy ja huorintekiä suku etsii merkkiä, ja ei hänelle pidä merkkiä annettaman, vaan Jonan prophetan merkki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 40, 'Sillä niinkuin Jona oli valaskalan vatsassa kolme päivää ja kolme yötä, niin pitää myös Ihmisen Pojan maan sydämessä kolme päivää ja kolme yötä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 41, 'Niniven miehet pitää nouseman tuomiolle tämän suvun kanssa ja hänen tuomitseman; sillä he paransivat heitänsä Jonan saarnasta. Ja katso, tässä on enempi kuin Jona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 42, 'Etelän kuningatar on nouseva tuomiolle tämän suvun kanssa ja hänen tuomitseva; sillä hän tuli maan ääristä kuulemaan Salomonin viisautta. Ja katso, tässä on enempi kuin Salomon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 43, 'Mutta kuin rietas henki on lähtenyt ihmisestä, niin hän vaeltaa lävitse kuivia paikkoja, etsein lepoa, ja ei löydä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 44, 'Silloin hän sanoo: minä palajan jälleen minun huoneeseeni, kusta minä läksin. Ja kuin hän tulee, niin hän löytää sen tyhjäksi, käväistyksi ja kaunistetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 45, 'Silloin hän menee ja ottaa kanssansa seitsemän muuta henkeä, itseänsä pahempaa, ja ne sisälle menevät ja asuvat siellä, ja sen ihmisen viimeiset tulevat pahemmaksi kuin ensimäiset. Näin myös tapahtuu tälle pahalle sukukunnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 46, 'Kuin hän vielä kansalle puhui, katso, hänen äitinsä ja veljensä seisoivat ulkona ja pyysivät häntä puhutella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 47, 'Niin yksi sanoi hänelle: katso, äitis ja veljes seisovat ulkona, ja tahtovat sinua puhutella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 48, 'Niin hän vastasi ja sanoi sille, joka hänelle sitä sanoi: kuka on minun äitini ja kutka ovat minun veljeni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 49, 'Ja hän ojensi kätensä opetuslastensa puoleen ja sanoi: minun äitini ja minun veljeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 50, 'Sillä jokainen, joka tekee Isäni tahdon, joka on taivaissa, hän on minun veljeni, ja sisareni, ja äitini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 1, 'Mutta sinä päivänä läksi Jesus huoneesta ja istui meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 2, 'Ja hänen tykönsä kokoontui paljo kansaa, niin että hän meni haahteen, ja istui: ja kaikki kansa seisoi rannalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 3, 'Ja hän puhui heille paljon vertauksilla, sanoen: katso, kylväjä meni kylvämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 4, 'Ja hänen kylväissänsä lankesivat muutamat tien oheen, ja linnut tulivat ja söivät ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 5, 'Muutamat taas lankesivat kivistöön, kussa ei heillä ollut paljo maata, ja nousivat pian päälle, ettei heillä ollut syvää maata;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 6, 'Mutta kuin aurinko nousi, niin he poudittiin, ja ettei heillä ollut juurta, niin he kuivettuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 7, 'Mutta muutamat lankesivat orjantappuroihin, ja orjantappurat kävivät ylös, ja tukahuttivat ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 8, 'Muutamat taas lankesivat hyvään maahan, ja tekivät hedelmän, muutama satakertaisen, muutama kuudenkymmenen kertaisen ja muutama kolmenkymmenen kertaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 9, 'Jolla on korvat kuulla, se kuulkaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 10, 'Niin opetuslapset tulivat ja sanoivat hänelle: miksi sinä puhut heille vertauksilla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 11, 'Mutta hän vastasi ja sanoi: teille on annettu tuta taivaan valtakunnan salaisuudet, vaan ei heille ole annettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 12, 'Sillä jolla on, hänelle pitää annettaman, ja hänellä pitää kyllä oleman; mutta siltä, jolla ei ole, pitää sekin otettaman pois, mikä hänellä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 13, 'Sentähden minä puhun heille vertauksilla, ettei he nähden näe, eikä kuullen kuule, ei myös ymmärrä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 14, 'Ja heissä täytetään Jesaiaan ennustus, joka sanoo: korvillanne pitää teidän kuuleman, ja ei ymmärtämän, ja nähden näkemän, ja ei äkkäämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 15, 'Sillä tämän kansan sydän on kovettunut, ja he korvillansa työläästi kuulivat, ja silmänsä panivat umpeen, ettei he joskus näkisi silmillänsä, ja kuulisi korvillansa, ja ymmärtäisi sydämellänsä, ja palajaisivat, ja minä parantaisin heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 16, 'Mutta autuaat ovat teidän silmänne, sillä he näkevät, ja teidän korvanne, sillä he kuulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 17, 'Sillä totisesti sanon minä teille: monta prophetaa ja vanhurskasta pyysi nähdä, joita te näette, ja ei nähneet, ja kuulla, joita te kuulette, ja ei kuulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 18, 'Niin kuulkaat siis te kylväjän vertaus:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 19, 'Kuin joku kuulee valtakunnan sanan ja ei ymmärrä, niin tulee pahuus ja tempaa pois sen mikä hänen sydämeensä kylvettiin. Tämä on se, joka tien oheen oli kylvetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 20, 'Mutta kivistöön kylvetty on se, joka kuulee sanan, ja kohta ilolla sen vastaan ottaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 21, 'Mutta ei ole hänellä juurta itsessänsä, vaan ajan pysyy: kuin siis vaiva eli vaino tulee sanan tähden, niin hän kohta pahenee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 22, 'Mutta orjantappurain sekaan kylvetty on se, joka sanan kuulee; ja tämän mailman suru ja rikkauden petos tukahuttaa sanan, ja hän tulee hedelmättömäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 23, 'Mutta hyvään maahan kylvetty on se, joka kuulee sanan ja ymmärtää, joka tosin tuottaa hedelmän ja tekee, muutama satakertaisen, muutama kuudenkymmenen kertaisen, muutama kolmenkymmenen kertaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 24, 'Toisen vertauksen pani hän heidän eteensä, sanoen: taivaan valtakunta on ihmisen vertainen, joka kylvi hyvän siemenen peltoonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 25, 'Mutta ihmisten maatessa tuli hänen vihollisensa ja kylvi ohdakkeita nisuin sekaan, ja meni pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 26, 'Mutta kuin oras rupesi kasvamaan ja hedelmän kantoi, silloin näkyivät myös ohdakkeet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 27, 'Mutta perheen isännän palvelijat tulivat ja sanoivat hänelle: Herra, etkös hyvää siementä kylvänyt peltoos? kusta siis sillä on ohdakkeet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 28, 'Niin sanoi hän heille: vihamies sen teki. Mutta palveliat sanoivat hänelle: tahdotkos, että me menemme ja kokoomme ne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 29, 'Mutta hän sanoi: en, ettette ohdakkeita kootessanne myös tempaisi ynnä heidän kanssansa nisuja pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 30, 'Sallikaat molemmat kasvaa elon-aikaan asti; ja elon-ajalla sanon minä elomiehille: kootkaat ensin ohdakkeet, ja sitokaat heitä lyhteisiin poltettaa, mutta nisut kootkaat minun aittaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 31, 'Toisen vertauksen pani hän heidän eteensä, sanoen: taivaan valtakunta on sinapin siemenen vertainen, jonka ihminen otti ja kylvi peltoonsa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 32, 'Joka on pienin kaikkia siemeniä, mutta kuin se kasvanut on, niin hän on suurin kaalein seassa, ja tulee puuksi, niin että taivaan linnut tulevat ja tekevät pesänsä sen oksille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 33, 'Toisen vertauksen sanoi hän heille: taivaan valtakunta on hapatuksen vertainen, jonka vaimo otti, ja sekoitti kolmeen vakkaan jauhoja, siihen asti kuin kaikki happani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 34, 'Nämät kaikki puhui Jesus kansalle vertauksilla, ja ilman vertauksia ei hän mitään puhunut heille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 35, 'Että täytettäisiin mitä oli prophetan kautta sanottu, joka sanoo: minä avaan suuni vertauksiin ja puhun ulos salatut maailman alusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 36, 'Silloin laski Jesus kansan menemään, ja tuli kotia. Ja hänen opetuslapsensa tulivat hänen tykönsä, sanoen: selitä meille sen vertaus pellon ohdakkeista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 37, 'Niin hän vastasi ja sanoi heille: joka kylvää hyvän siemenen, se on Ihmisen Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 38, 'Mutta pelto on maailma; vaan hyvä siemen, ne ovat valtakunnan lapset; mutta ohdakkeet ovat pahan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 39, 'Vihollinen, joka ne kylvi, on perkele; elonaika on maailman loppu; mutta elomiehet ovat enkelit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 40, 'Niinkuin siis ohdakkeet haetaan kokoon ja tulella poltetaan, niin pitää myös tämän maailman lopulla oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 41, 'Ihmisen Poika lähettää enkelinsä, ja heidän pitää kokooman hänen valtakunnastansa kaikki pahennukset, ja ne jotka vääryyttä tekevät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 42, 'Ja heittävät heidät tuliseen pätsiin: siellä pitää oleman itku ja hammasten kiristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 43, 'Silloin pitää vanhurskaat kiiltämän niinkuin aurinko isänsä valtakunnassa. Jolla on korvat kuulla, se kuulkaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 44, 'Taas on taivaan valtakunta tavaran vertainen, joka on peltoon kätketty, jonka ihminen löysi, ja kätki sen: ja ilon tähden, mikä hänellä siitä oli, meni hän pois ja myi kaikki mitä hänellä oli ja osti sen pellon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 45, 'Taas on taivaan valtakunta kauppamiehen vertainen, joka etsi hyviä päärlyjä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 46, 'Ja kuin hän löysi yhden kalliin päärlyn, meni hän pois, myi kaikki, mitä hänellä oli, ja osti sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 47, 'Taas on taivaan valtakunta verkon vertainen, joka on mereen heitetty, ja kaikenlaisia kokosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 48, 'Kuin se täyteen tuli, vetivät he sen rannalle, ja istuivat ja eroittivat hyvät astioihinsa, mutta mädänneet he heittivät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 49, 'Näin on tapahtuva maailman lopulla: Enkelit menevät ulos ja eroittavat pahat vanhurskasten keskeltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 50, 'Ja heittävät heidät tuliseen pätsiin: siellä pitää oleman itku ja hammasten kiristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 51, 'Sanoi Jesus heille: ymmärsittekö te nämät kaikki? He sanoivat hänelle: ymmärsimme, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 52, 'Mutta hän sanoi heille: sentähden jokainen kirjanoppinut, joka on taivaan valtakuntaan oppinut, se on perheenisännän vertainen, joka tavarastansa tuo edes uusia ja vanhoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 53, 'Ja tapahtui, kuin Jesus lopetti nämät vertaukset, läksi hän sieltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 54, 'Ja kuin hän tuli isänsä maalle, opetti hän heitä heidän synagogassansa, niin että he hämmästyivät ja sanoivat: kusta tällä on tämä viisaus ja nämät väkevät työt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 55, 'Eikö tämä ole tuo sepän poika? eikö hänen äitinsä kutsuta Mariaksi ja hänen veljensä Jakob ja Joses, ja Simon ja Juudas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 56, 'Ja hänen sisarensa, eikö ne kaikki ole meidän tykönämme? Kusta siis tällä on nämät kaikki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 57, 'Ja he pahenivat hänessä. Niin sanoi Jesus heille: ei prophetaa kussakaan halvempana pidetä kuin isänsä maalla ja kotonansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 58, 'Ja ei hän siellä monta väkevää työtä tehnyt, heidän epäuskonsa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 1, 'Siihen aikaan kuuli Herodes tetrarka Jesuksen sanoman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 2, 'Ja sanoi palvelioillensa: tämä on Johannes Kastaja: hän on noussut kuolleista, ja sentähden tekee hän senkaltaisia väkeviä töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 3, 'Sillä Herodes oli ottanut Johanneksen kiinni, sitonut ja vankiuteen pannut, Herodiaksen, veljensä Philippuksen emännän tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 4, 'Sillä Johannes oli hänelle sanonut: ei sinulle ole luvallinen häntä pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 5, 'Ja kuin hän tahtoi hänen tappaa, pelkäsi hän kansaa; sillä he pitivät hänen prophetana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 6, 'Mutta kun Herodeksen syntymäjuhlaa pidettiin, hyppäsi Herodiaksen tytär heidän edessänsä; ja se kelpasi Herodekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 7, 'Sentähden lupasi hän hänelle vannotulla valalla antaa, mitä hän anois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 8, 'Mutta niinkuin hän äidiltänsä ennen neuvottu oli, anna minulle, hän sanoi, tässä vadissa Johannes Kastajan pää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 9, 'Ja kuningas tuli murheelliseksi; mutta kuitenkin valan tähden ja niiden, jotka ynnä atrioitsivat, käski hän antaa hänelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 10, 'Ja lähetti leikkaamaan Johanneksen kaulaa tornissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 11, 'Ja hänen päänsä kannettiin vadissa ja annettiin piialle, ja hän vei sen äidillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 12, 'Ja hänen opetuslapsensa tulivat, ja ottivat pois hänen ruumiinsa, ja hautasivat sen; ja menivät ja ilmoittivat Jesukselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 13, 'Ja kuin Jesus sen kuuli, meni hän sieltä pois haahdella erämaahan yksinänsä. Ja kuin kansa se kuuli, noudattivat he häntä jalkaisin kaupungeista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 14, 'Ja Jesus meni ulos, ja näki paljon kansaa, ja armahti heidän päällensä, ja paransi heidän sairaitansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 15, 'Mutta kun ehtoo tuli, tulivat hänen opetuslapsensa hänen tykönsä, ja sanoivat: tämä on erämaa, ja aika on jo kulunut: laske kansa, että he menisivät kyliin itsellensä ruokaa ostamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 16, 'Niin Jesus sanoi heille: ei tarvitse heidän mennä pois: antakaat te heidän syödä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 17, 'Mutta he sanoivat hänelle: ei meillä ole tässä enempi kuin viisi leipää ja kaksi kalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 18, 'Hän sanoi: tuokaat minulle ne tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 19, 'Ja hän käski kansan istua ruoholle, ja otti ne viisi leipää ja kaksi kalaa, katsahti ylös taivaasen, kiitti, ja mursi, ja antoi leivät opetuslapsille, ja opetuslapset antoivat kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 20, 'Ja he söivät kaikki, ja ravittiin. Niin he kokosivat tähteistä muruja, kaksitoistakymmentä koria täyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 21, 'Mutta niitä, jotka olivat syöneet, oli lähes viisituhatta miestä, ilman vaimoja ja lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 22, 'Ja kohta vaati Jesus opetuslapsiansa haahteen astumaan, ja menemään hänen edellään toiselle rannalle, niinkauvan kuin hän kansan olis tyköänsä laskenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 23, 'Ja kuin hän oli kansan laskenut, astui hän yksinänsä vuorelle rukoilemaan. Ja kuin ehtoo joutui, oli hän siellä yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 24, 'Mutta haaksi oli jo keskellä merta, ja ahdistettiin aalloilta; sillä vastatuuli oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 25, 'Mutta yöllä, neljännessä vartiossa, tuli Jesus heidän tykönsä, käyden merellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 26, 'Ja kuin opetuslapset näkivät hänen merellä käyvän, peljästyivät he, ja sanoivat: kyöpeli se on; ja huusivat pelvon tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 27, 'Niin Jesus puhui kohta heille ja sanoi: olkaat hyvässä turvassa! minä olen: älkäät peljästykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 28, 'Niin vastasi Pietari häntä ja sanoi: Herra, jos sinä olet, niin käske minun tulla tykös vetten päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 29, 'Niin hän sanoi: tule! Ja Pietari astui ulos haahdesta ja kävi vetten päällä, että hän menis Jesuksen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 30, 'Ja kuin hän näki ankaran tuulen, niin hän peljästyi, ja rupesi vajoomaan, huusi sanoen: Herra, auta minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 31, 'Niin Jesus ojensi kohta kätensä, ja tarttui häneen, ja sanoi hänelle: oi sinä heikko-uskoinen, miksis epäilit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 32, 'Kuin he astuivat haahteen, niin tuuli tyveni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 33, 'Mutta ne, jotka olivat haahdessa, tulivat ja kumarsivat häntä, ja sanoivat: totisesti olet sinä Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 34, 'Ja kuin he olivat menneet ylitse, tulivat he Genesaretin maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 35, 'Ja kuin sen paikan miehet tunsivat hänen, lähettivät he ympäri kaikkea sitä maata, ja toivat hänen tykönsä kaikkinaisia sairaita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 36, 'Ja rukoilivat häntä, että he ainoastaan hänen vaatteensa palteeseen saisivat ruveta. Ja kaikki, jotka siihen rupesivat, tulivat terveiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 1, 'Silloin tulivat Jesuksen tykö kirjanoppineet ja Pharisealaiset Jerusalemista, ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 2, 'Miksi sinun opetuslapses rikkovat vanhinten säädyn? sillä ei he pese käsiänsä leipää syödessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 3, 'Niin hän vastaten sanoi heille: miksi tekin rikotte Jumalan käskyn, teidän säätynne tähden?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 4, 'Sillä Jumala käski, sanoen: kunnioita isääs ja äitiäs: ja joka kiroilee isää eli äitiä, hänen pitää kuolemalla kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 5, 'Mutta te sanotte: jokainen sanokaan isälle taikka äidille: se on uhrattu, jolla sinua piti minulta autettaman: ja ei ensinkään kunnoittaisi isäänsä eikä äitiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 6, 'Ja te olette rikkoneet Jumalan käskyn teidän säätynne tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 7, 'Te ulkokullatut! Jesaias ennusti teistä oikein, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 8, 'Tämä kansa lähestyy minua suullansa, ja kunnioittaa minua huulillansa; mutta heidän sydämensä on kaukana minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 9, 'Vaan turhaan he minua palvelevat, opettain niitä opetuksia, jotka ovat ihmisten käskyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 10, 'Ja hän kutsui kansan tykönsä, ja sanoi heille: kuulkaat ja ymmärtäkäät!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 11, 'Ei se ihmistä saastuta, mikä suusta menee sisälle, mutta se, mikä suusta tulee ulos, saastuttaa ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 12, 'Niin tulivat hänen opetuslapsensa, ja sanoivat hänelle: tiesitkös, että Pharisealaiset pahenivat, kuin he tämän puheen kuulivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 13, 'Mutta hän vastasi ja sanoi: jokainen istutus, jota ei minun taivaallinen Isäni ole istuttanut, pitää juurinensa revittämän ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 14, 'Antakaat heidän olla: he ovat sokiat sokiain taluttajat; jos sokia sokiaa taluttaa, niin he molemmat kuoppaan lankeevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 15, 'Niin vastasi Pietari ja sanoi hänelle: selitä meille tämä vertaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 16, 'Niin Jesus sanoi: vieläkö tekin olette ymmärtämättömät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 17, 'Ettekö te vielä ymmärrä, että kaikki, mitä suuhun sisälle menee, se menee vatsaan, ja sillä on luonnollinen uloskäyminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 18, 'Mutta jotka suusta tulevat ulos, ne lähtevät sydämestä ulos, ja saastuttavat ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 19, 'Sillä sydämestä tulevat ulos pahat ajatukset, murhat, salavuoteudet, huoruudet, varkaudet, väärät todistukset, pilkat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 20, 'Nämät ovat ne, jotka saastuttavat ihmisen; mutta pesemättömillä käsillä syödä, ei saastuta ihmistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 21, 'Ja Jesus läksi sieltä ja poikkesi Tyron ja Sidonin maan ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 22, 'Ja katso, Kanaanean vaimo, joka niistä maan ääristä oli tullut, huusi häntä, sanoen: Herra, Davidin poika, armahda minua: minun tyttäreni vaivataan hirmuisesti perkeleeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 23, 'Mutta ei hän sanaakaan häntä vastannut. Niin hänen opetuslapsensa tulivat ja rukoilivat häntä, sanoen: eroita häntä sinustas; sillä hän huutaa meidän jälkeemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 24, 'Niin hän vastaten sanoi: en ole minä lähetetty, vaan kadotettuin lammasten tykö Israelin huoneesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 25, 'Mutta se tuli ja kumarsi häntä, sanoen: Herra, auta minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 26, 'Niin hän vastaten sanoi: ei ole sovelias ottaa lasten leipää ja heittää penikoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 27, 'Niin se vastasi: totta Herra, syövät kuitenkin penikatkin niistä muruista, jotka heidän herrainsa pöydältä putoovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 28, 'Silloin Jesus vastaten sanoi hänelle: oi vaimo, suuri on sinun uskos, tapahtukoon sinulle niinkuin sinä tahdot. Ja hänen tyttärensä tuli sillä hetkellä terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 29, 'Ja Jesus läksi sieltä ja tuli Galilean meren tykö, ja astui vuorelle, ja istui siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 30, 'Ja paljo kansaa tuli hänen tykönsä, ja toivat kanssansa ontuvia, sokeita, mykkiä, raajarikkoja ja paljon muita, ja laskivat Jesuksen jalkain eteen; ja hän paransi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 31, 'Niin että kansa ihmetteli, kuin he näkivät mykät puhuvan, raajarikot terveinä, ontuvat käyvän ja sokiat näkevän, ja kunnioittivat Israelin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 32, 'Ja Jesus kutsui opetuslapsensa tykönsä, ja sanoi: minä armahdan kansaa, että he ovat jo kolme päivää minun tykönäni viipyneet, ja ei ole heillä mitään syötävää: ja en minä tahdo heitä tyköäni syömättä laskea pois, ettei he tiellä vaipuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 33, 'Niin sanoivat hänen opetuslapsensa hänelle: kusta me saamme tässä erämaassa niin monta leipää, että me ravitsemme niin paljon kansaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 34, 'Ja Jesus sanoi heille: kuinka monta leipää teillä on? He sanoivat: seitsemän, ja vähä kalasia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 35, 'Niin hän käski kansan istua maan päälle atrioitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 36, 'Ja hän otti ne seitsemän leipää ja kalat, kiitti, mursi ja antoi opetuslapsillensa, ja opetuslapset antoivat kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 37, 'Ja he söivät kaikki ja ravittiin, ja ottivat ylös mitä liiaksi jäi, seitsemän täysinäistä koria muruja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 38, 'Mutta niitä jotka söivät, oli neljätuhatta miestä, ilman vaimoja ja lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 39, 'Ja kuin hän oli kansan tyköänsä laskenut, astui hän haahteen, ja tuli Magdalan rajoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 1, 'Niin tulivat hänen tykönsä Pharisealaiset ja Saddukealaiset ja kiusaten anoivat häneltä, että hän merkin taivaasta osoittais heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 2, 'Niin hän vastasi ja sanoi heille: kuin ehtoo tulee, niin te sanotte: seijes tulee; sillä taivas ruskottaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 3, 'Ja huomeneltain: tänäpänä tulee kova ilma; sillä taivas ruskottaa ja on valju. Te ulkokullatut! te taidatte taivaan muodon tuomita, mutta aikain merkkejä ette taida tuomita?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 4, 'Tämä häijy ja huorintekijä sukukunta etsii merkkiä, ja ei hänelle pidä merkkiä annettaman, vaan Jonan prophetan merkki. Ja hän jätti heidät, ja meni pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 5, 'Ja kuin hänen opetuslapsensa olivat tulleet ylitse toiselle rannalle, olivat he unohtaneet ottaa leipiä myötänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 6, 'Mutta Jesus sanoi heille: katsokaat ja kavahtakaat teitänne Pharisealaisten ja Saddukealaisten hapatuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 7, 'Niin he ajattelivat itsellensä, sanoen: se on, ettemme ottaneet leipiä myötämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 8, 'Mutta kuin Jesus sen ymmärsi, sanoi hän heille: te vähäuskoiset! mitä te ajattelette keskenänne, ettette leipiä myötänne ottaneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 9, 'Ettekö vielä ymmärrä, taikka ettekö te muista niitä viittä leipää viidelletuhannelle, ja kuinka monta koria te korjasitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 10, 'Niin myös niitä seitsemää leipää neljälletuhannelle, ja kuinka monta koria te korjasitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 11, 'Kuinka ette ymmärrä, etten minä leivästä teille sitä sanonut, että teidän pitäis kavahtaman teitänne Pharisealaisten ja Saddukealaisten hapatuksesta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 12, 'Silloin he ymmärsivät, ettei hän käskenyt heitä kavahtamaan itsiänsä leivän hapatuksesta, vaan Pharisealaisten ja Saddukealaisten opista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 13, 'Mutta kuin Jesus tuli Kesarean maan ääriin, joka kutsutaan Philippuksen, kysyi hän opetuslapsiltansa ja sanoi: kenenkä sanovat ihmiset minun, Ihmisen Pojan, olevan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 14, 'Niin he sanoivat: monikahdat Johannes Kastajan; mutta muutamat Eliaan; muutamat taas Jeremiaan, taikka jonkun prophetaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 15, 'Sanoi hän heille: mutta kenenkä te sanotte minun olevan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 16, 'Vastasi Simon Pietari ja sanoi: sinä olet Kristus, elävän Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 17, 'Ja Jesus vastaten sanoi hänelle: autuas olet sinä, Simon Jonan poika! sillä ei liha eikä veri ilmoittanut sitä sinulle, vaan Isäni, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 18, 'Mutta minä myös sanon sinulle: sinä ole Pietari, ja tämän kallion päälle tahdon minä rakentaa minun seurakuntani, ja helvetin portit ei pidä häntä voittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 19, 'Ja minä annan sinulle taivaan valtakunnan avaimet: ja mitä sinä maan päällä sidot, pitää sidotun oleman taivaissa, ja mitä sinä päästät maan päällä, sen pitää oleman päästetyn taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 20, 'Niin hän haastoi opetuslapsiansa kellenkään sanomasta, että hän oli Jesus Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 21, 'Siitä ajasta rupesi Jesus julistamaan opetuslapsillensa, että hänen piti Jerusalemiin menemän, ja paljon vanhimmilta ja pappein päämiehiltä ja kirjanoppineilta kärsimän, ja tapettaman, ja kolmantena päivänä ylösnouseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 22, 'Ja Pietari otti hänen erinänsä, rupesi häntä nuhtelemaan, sanoen: armahda itsiäs, Herra: älköön sinulle se tapahtuko!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 23, 'Niin hän käänsi itsensä ympäri ja sanoi Pietarille: mene pois minun tyköäni, saatana! sinä olet minulle pahennukseksi: ettes ymmärrä niitä, jotka Jumalan ovat, mutta ne, jotka ihmisen ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 24, 'Silloin Jesus sanoi opetuslapsillensa: jos joku tahtoo minun perässäni tulla, hän kieltäkään itsensä, ja ottakaan ristinsä, ja seuratkaan minua;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 25, 'Sillä joka tahtoo henkensä vapahtaa, hän hukuttaa sen; mutta joka henkensä hukuttaa minun tähteni, hän löytää sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 26, 'Sillä mitä se auttaa ihmistä, jos hän kaiken maailman voittais, ja sielullensa sais vahingon? taikka mitä antaa ihminen sielunsa lunastukseksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 27, 'Sillä Ihmisen Poika on tuleva Isänsä kunniassa enkelittensä kanssa, ja silloin hän maksaa kullekin töittensä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 28, 'Totisesti minä sanon teille: muutamat seisovat tässä, joiden ei suinkaan pidä kuolemaa maistaman, siihenasti kuin he näkevät Ihmisen Pojan tulevan hänen valtakunnassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 1, 'Ja kuuden päivän perästä otti Jesus Pietarin ja Jakobin ja Johanneksen hänen veljensä, ja vei heidät erinänsä korkialle vuorelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 2, 'Ja kirkastettiin heidän edessänsä, ja hänen kasvonsa paistivat niinkuin aurinko, ja hänen vaatteensa tulivat valkiaksi niinkuin valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 3, 'Ja katso, heille näkyivät Moses ja Elias, jotka puhuivat hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 4, 'Niin vastasi Pietari ja sanoi Jesukselle: Herra, meidän on tässä hyvä olla: jos sinä tahdot, niin me teemme tähän kolme majaa, sinulle yhden, ja Mosekselle yhden, ja Eliaalle yhden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 5, 'Vielä hänen puhuissansa, katso, paistava pilvi ympäri varjosi heidät, ja katso, ääni pilvestä sanoi: tämä on minun rakas Poikani, johonka minä mielistyin: kuulkaat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 6, 'Ja kuin opetuslapset sen kuulivat, lankesivat he kasvoillensa, ja peljästyivät sangen kovin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 7, 'Ja Jesus tuli, ja rupesi heihin, ja sanoi: nouskaat, ja älkäät peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 8, 'Mutta kuin he silmänsä nostivat, ei he ketään nähneet, vaan Jesuksen yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 9, 'Ja kuin he menivät vuorelta alas, haastoi Jesus heitä, sanoen: älkäät kellenkään tätä näkyä sanoko, siihenasti kuin Ihmisen Poika kuolleista nousee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 10, 'Niin hänen opetuslapsensa kysyivät häneltä, sanoen: miksi siis kirjanoppineet sanovat, että Eliaan pitää ennen tuleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 11, 'Niin Jesus vastaten sanoi heille: Elias tosin tulee ennen, ja kohentaa kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 12, 'Mutta minä sanon teille: Elias on jo tullut; ja ei he tunteneet häntä, mutta tekivät hänelle mitä he tahtoivat. Niin myös Ihmisen Poika on heiltä kärsivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 13, 'Silloin ymmärsivät opetuslapset hänen Johannes Kastajasta sanoneen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 14, 'Ja kuin he kansan tykö tulivat, tuli yksi mies hänen tykönsä ja lankesi polvillensa hänen eteensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 15, 'Ja sanoi: Herra, armahda minun poikaani, sillä hän on kuutaudillinen ja kovin vaivataan; sillä hän lankee usein tuleen ja usein veteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 16, 'Ja minä toin hänen opetuslastes tykö, ja ei he voineet häntä parantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 17, 'Niin Jesus vastaten sanoi: oi epäuskoinen ja nurja sukukunta! kuinka kauvan minun pitää teidän kanssanne oleman? kuinka kauvan minun pitää teitä kärsimän? Tuokaat häntä minulle tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 18, 'Ja Jesus rankaisi sitä, ja perkele meni hänestä ulos; ja poika parani sillä hetkellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 19, 'Silloin menivät opetuslapset Jesuksen tykö erinänsä, ja sanoivat: miksi emme voineet sitä ajaa ulos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 20, 'Niin Jesus sanoi heille: epäuskonne tähden. Sillä totisesti minä sanon teille: jos teillä olis usko niinkuin sinapin siemen, niin te taitaisitte sanoa tälle vuorelle: siirry tästä sinne, niin se siirtyis, ja ei teille mitään olisi mahdotointa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 21, 'Vaan tämä suku ei mene muutoin ulos kuin rukouksella ja paastolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 22, 'Kuin he asuivat Galileassa, sanoi Jesus heille: tapahtuva on, että Ihmisen Poika annetaan ylön ihmisten käsiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 23, 'Ja he tappavat hänen, ja kolmantena päivänä hän nousee ylös. Ja he tulivat sangen murheellisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 24, 'Mutta kuin he menivät Kapernaumiin, tulivat verorahan ottajat Pietarin tykö, ja sanoivat: eikö Mestarinne ole tottunut verorahaa maksamaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 25, 'Sanoi hän: on. Ja kuin hän tuli huoneeseen, ennätti hänen Jesus, ja sanoi: mitäs luulet, Simon? keiltä maan kuninkaat ottavat tullin eli veron? omilta lapsiltansa, taikka vierailta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 26, 'Pietari sanoi hänelle: vierailta. Sanoi Jesus hänelle: niin lapset ovat vapaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 27, 'Mutta ettemme heitä pahentaisi, niin mene merelle, heitä onkes, ja ota se kala, joka ensin tulee ylös, ja avaa hänen suunsa, niin sinä löydät rahan: ota se, ja anna heille minun ja sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 1, 'Sillä hetkellä tulivat opetuslapset Jesuksen tykö, sanoen: kuka siis on suurin taivaan valtakunnassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 2, 'Ja Jesus kutsui tykönsä lapsen, ja asetti sen heidän keskellensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 3, 'Ja sanoi: totisesti minä sanon teille: ellette käänny ja tule niinkuin lapset, niin ette suinkaan tule sisälle taivaan valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 4, 'Sentähden joka itsensä alentaa niinkuin tämä lapsi, se on suurin taivaan valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 5, 'Ja joka holhoo senkaltaisen lapsen minun nimeeni, hän holhoo minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 6, 'Mutta joka pahentaa yhden näistä pienimmistä, jotka uskovat minun päälleni, parempi hänen olis, että myllyn kivi ripustettaisiin hänen kaulaansa, ja hän upotettaisiin meren syvyyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 7, 'Voi maailmaa pahennusten tähden, sillä pahennukset kumminkin tulevat! Voi kuitenkin sitä ihmistä, jonka kautta pahennus tulee!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 8, 'Mutta jos kätes taikka jalkas pahentaa sinun, niin leikkaa ne pois, ja heitä pois tyköäs. Parempi on sinun elämään sisälle mennä ontuvana taikka raajarikkona, kuin että sinulla olis kaksi kättä eli kaksi jalkaa, ja sinä heitettäisiin ijankaikkiseen tuleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 9, 'Ja jos silmäs pahentaa sinun, niin puhkaise se ulos, ja heitä pois tyköäs. Parempi on sinun silmäpuolena elämään sisälle mennä, kuin että sinulla olis kaksi silmää, ja sinä heitettäisiin helvetin tuleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 10, 'Katsokaat, ettette katso ylön yhtäkään näistä pienimmistä; sillä minä sanon teille: heidän enkelinsä taivaissa näkevät aina minun isäni kasvot, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 11, 'Sillä Ihmisen Poika tuli autuaaksi tekemään sitä, mikä kadonnut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 12, 'Mitä te luulette? jos jollakin ihmisellä olis sata lammasta, ja yksi heistä eksyis: eikö hän jättäisi yhdeksänkymmentä ja yhdeksän, ja menis vuorelle, ja etsis eksynyttä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 13, 'Ja jos niin tapahtuu, että hän löytää sen, totisesti sanon minä teille: hän iloitsee enemmin siitä kuin yhdeksästäkymmenestä ja yhdeksästä, jotka ei eksyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 14, 'Niin ei ole myös teidän Isänne tahto, joka on taivaissa, että joku näistä pienimmistä hukkuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 15, 'Mutta jos sinun veljes rikkoo sinua vstaan, niin mene ja nuhtele häntä kahden kesken yksinänsä. Jos hän sinua kuulee, niin sinä olet veljes voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 16, 'Mutta jos ei hän sinua kuule, niin ota vielä yksi eli kaksi kanssas, että kaikki asia kahden eli kolmen todistajan suussa olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 17, 'Mutta ellei hän niitä tahdo kuulla, niin sano seurakunnalle; ellei hän seurakuntaa tottele, niin pidä häntä pakanana ja Publikanina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 18, 'Totisesti sanon minä teille: kaikki, mitä te maan päällä sidotte, pitää myös oleman sidotut taivaissa: ja kaikki, mitä te päästätte maan päällä, pitää myös oleman päästetyt taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 19, 'Taas sanon minä teille: missä ikänä asiassa kaksi teistä sopivat maan päällä; jota he rukoilevat, sen heidän pitää saaman minun Isältäni, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 20, 'Sillä kussa kaksi taikka kolme tulevat kokoon minun nimeeni, siinä minä olen heidän keskellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 21, 'Silloin Pietari tuli hänen tykönsä, ja sanoi: Herra, kuinka usein minun pitää veljelleni, joka rikkoo minua vastaan, antaman anteeksi? onko seitsemässä kerrassa kyllä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 22, 'Sanoi Jesus hänelle: en minä sano sinulle ainoastaan seitsemän kertaa, mutta seitsemänkymmentä kertaa seitsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 23, 'Sentähden on taivaan valtakunta kuninkaaseen verrattu, joka tahtoi lukua laskea palveliainsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 24, 'Ja kuin hän rupesi laskemaan, tuli yksi hänen eteensä, joka oli hänelle velkaa kymmenentuhatta leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 25, 'Mutta ettei hänellä ollut varaa maksaa, käski hänen herransa hänen myytää, ja hänen emäntänsä ja lapsensa, ja kaikki mitä hänellä oli, ja maksettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 26, 'Niin palvelia lankesi maahan ja rukoili häntä, sanoen: herra, ole kärsivällinen minun kanssani, ja minä maksan kaikki sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 27, 'Niin armahti herra palveliaa, päästi hänen, ja antoi hänelle velan anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 28, 'Niin palvelia meni ulos, ja löysi yhden kanssapalvelioistansa, joka hänelle oli velkaa sata penninkiä; ja hän tarttui häneen, ja kiristi häntä kurkusta, sanoen: maksa minulle velkas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 29, 'Niin hänen kanssapalveliansa lankesi maahan hänen jalkainsa juureen, ja rukoili häntä, sanoen: ole kärsivällinen minun kanssani, ja minä maksan kaikki sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 30, 'Mutta ei hän tahtonut, vaan meni ja heitti hänen torniin, siihenasti kuin hän velan maksais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 31, 'Mutta kuin muut hänen kanssapalveliainsa näkivät mitä tehtiin, murehtivat he sangen kovin, tulivat ja ilmoittivat herrallensa kaiken, mitä tehty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 32, 'Silloin kutsui herra hänen eteensä, ja sanoi hänelle: sinä paha palvelia, minä annoin sinulle anteeksi kaiken velan, ettäs minua rukoilit:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 33, 'Eikö myös sinun pitänyt armahtaman kanssapalveliaas, niinkuin minäkin armahdin sinua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 34, 'Ja hänen herransa vihastui, ja antoi hänen pyöveleille, siihenasti kuin hän maksais kaikki, mitä hän oli hänelle velkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 35, 'Niin myös minun taivaallinen Isäni tekee teille, jollette kukin veljellensä teidän sydämistänne anna anteeksi heidän rikoksiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 1, 'Ja tapahtui, kuin Jesus oli lopettanut nämät puheet, läksi hän Galileasta ja tuli Juudean maan rajoille, sille puolelle Jordania.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 2, 'Ja paljo kansaa seurasi häntä, ja hän paransi heitä siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 3, 'Ja Pharisealaiset tulivat hänen tykönsä, kiusasivat häntä, ja sanoivat hänelle: saako mies eritä vaimostaan kaikkinaisen syyn tähden?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 4, 'Niin hän vastasi ja sanoi heille: ettekö te ole lukeneet: joka alusta ihmisen teki, mieheksi ja vaimoksi hän heidät teki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 5, 'Ja sanoi: sentähden pitää ihmisen luopuman isästänsä ja äidistänsä, ja vaimoonsa sidottu oleman, ja ne kaksi tulevat yhdeksi lihaksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 6, 'Niin ei he ole enään kaksi, mutta yksi liha. Jonka siis Jumala yhteen sovitti, ei pidä ihmisen sitä eroittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 7, 'He sanoivat hänelle: miksi Moses käski antaa erokirjan ja hyljätä hänen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 8, 'Sanoi hän heille: teidän sydämenne kovuuden tähden salli Moses teidän eritä vaimoistanne; vaan ei alusta niin ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 9, 'Mutta minä sanon teille: kuka ikänä hylkää vaimonsa muutoin kuin huoruuden tähden, ja nai toisen, hän tekee huorin; ja joka hyljätyn ottaa, hän tekee huorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 10, 'Hänen opetuslapsensa sanoivat hänelle: jos miehen asia niin on vaimon kanssa, ei sitte ole hyvä naida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 11, 'Niin hän sanoi heille: ei tätä sanaa kaikki käsitä, vaan ne, joille se annettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 12, 'Sillä muutamat ovat kuohitut, jotka äitinsä kohdusta niin syntyneet ovat: ja ovat kuohitut, jotka ihmisiltä kuohitut ovat: ja ovat kuohitut, jotka taivaan valtakunnan tähden itse kuohinneet ovat. Joka sen taitaa käsittää, se käsittäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 13, 'Silloin vietiin hänen tykönsä lapsia, että hän laskis kätensä heidän päällensä ja rukoilis; mutta opetuslapset nuhtelivat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 14, 'Mutta Jesus sanoi: sallikaat lasten olla, ja älkäät kieltäkö heitä tulemasta minun tyköni: sillä senkaltaisten on taivaan valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 15, 'Ja kuin hän oli pannut kätensä heidän päällensä, meni hän sieltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 16, 'Ja katso, yksi tuli ja sanoi hänelle: hyvä Mestari! mitä hyvää minun pitää tekemän, että minä saisin ijankaikkisen elämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 17, 'Niin hän sanoi hänelle: miksi sinä kutsut minun hyväksi? Ei ole kenkään hyvä, vaan yksi, Jumala. Mutta jos sinä tahdot elämään sisälle tulla, niin pidä käskyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 18, 'Hän sanoi hänelle: kutka? Jesus sanoi: ei sinun pidä tappaman: ei sinun pidä huorin tekemän: ei sinun pidä varastaman: ei sinun pidä väärin todistaman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 19, 'Kunnioita isääs ja äitiäs: ja sinun pitää rakastaman lähimmäistäs niinkuin itse sinuas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 20, 'Sanoi nuorukainen hänelle: kaikki nämät olen minä pitänyt nuoruudestani; mitä vielä minulta puuttuu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 21, 'Sanoi Jesus hänelle: jos sinä tahdot olla täydellinen, niin mene ja myy mitä sinulla on, ja anna vaivaisille: ja sinun pitää saaman tavaran taivaassa; ja tule ja seuraa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 22, 'Mutta kuin nuorukainen kuuli sen puheen, meni hän pois murheissansa; sillä hänellä oli paljo tavaraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 23, 'Mutta Jesus sanoi opetuslapsillensa: totisesti sanon minä teille: rikas tulee työläästi taivaan valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 24, 'Ja taas sanon minä teille: huokiampi on kamelin käydä neulan silmän lävitse, kuin rikkaan tulla Jumalan valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 25, 'Mutta koska hänen opetuslapsensa sen kuulivat, peljästyivät he sangen kovin, sanoen: kuka siis taitaa autuaaksi tulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 26, 'Niin Jesus katsahti heidän päällensä ja sanoi heille: ihmisten tykönä on se mahdotoin, mutta Jumalan tykönä ovat kaikki mahdolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 27, 'Silloin vastasi Pietari ja sanoi hänelle: katso, me luovuimme kaikista ja seuraamme sinua: mitä siis meidän siitä on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 28, 'Niin sanoi Jesus heille: totisesti sanon minä teille, te, jotka minua olette seuranneet, uudessa syntymisessä, kuin Ihmisen Poika istuu kunniansa istuimella, pitää myös teidän istuman kahdellatoistakymmenellä istuimella, tuomiten kahtatoistakymmentä Israelin sukukuntaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 29, 'Ja jokainen, joka luopui huoneista, taikka veljistä, taikka sisarista, taikka isästä, taikka äidistä, taikka emännästä, taikka lapsista, taikka pellosta, minun nimeni tähden, hänen pitää satakertaisesti saaman, ja ijankaikkisen elämän perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 30, 'Mutta monta ensimäistä tulee viimeiseksi ja viimeistä ensimäiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 1, 'Sillä taivaan valtakunta on perheenisännän vertainen, joka varhain huomeneltain läksi ulos palkkaamaan työväkeä viinamäkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 2, 'Ja kuin hän oli sopinut työmiesten kanssa päiväpenningistä, lähetti hän heidät viinamäkeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 3, 'Ja hän meni ulos liki kolmannella hetkellä, ja näki muita seisovan turulla joutilaina,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 4, 'Ja sanoi heille: menkäät tekin viinamäkeen, ja mitä kohtuullinen on, minä annan teille. Niin he menivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 5, 'Taas hän meni ulos liki kuudennella ja yhdeksännellä hetkellä, ja teki myös niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 6, 'Mutta yhdellätoistakymmenennellä hetkellä läksi hän ulos, ja löysi muita joutilaina seisomasta, ja sanoi heille: miksi te tässä kaiken päivän joutilaina seisotte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 7, 'He sanoivat hänelle: sillä ei ole kenkään meitä palkannut. Hän sanoi heille: menkäät tekin minun viinamäkeeni, ja mitä kohtuus on, pitää teidän saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 8, 'Mutta kuin ehtoo tuli, sanoi viinamäen isäntä perheensä haltialle: kutsu työväki, ja maksa heidän palkkansa, ruveten viimeisistä ensimäisiin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 9, 'Ja kuin ne tulivat, jotka liki yhdellätoistakymmenennellä hetkellä tulleet olivat, saivat he kukin penninkinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 10, 'Mutta kuin ensimäiset tulivat, luulivat he enemmän saavansa; ja he myös saivat kukin penninkinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 11, 'Ja kuin he saivat, napisivat he perheenisäntää vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 12, 'Sanoen: nämät viimeiset ovat yhden hetken työtä tehneet, ja sinä teit heidät meidän verraksemme, jotka olemme kantaneet päivän kuorman ja helteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 13, 'Niin hän vastasi ja sanoi yhdelle heistä: ystäväni, en tee minä sinulle vääryyttä; etkös sopinut minun kanssani määrätystä penningistä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 14, 'Ota se, mikä sinun tulee, ja mene matkaas; mutta minä tahdon tälle viimeiselle antaa niinkuin sinullekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 15, 'Vai enkö minä saa tehdä minun kalustani mitä minä tahdon? taikka katsotkos sentähden karsaasti, että minä hyvä olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 16, 'Niin viimeiset tulevat ensimäisiksi ja ensimäiset viimeisiksi. Sillä monta ovat kutsutut, mutta harvat valitut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 17, 'Ja Jesus meni ylös Jerusalemiin, ja otti kaksitoistakymmentä opetuslastansa erinänsä tiellä tykönsä, ja sanoi heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 18, 'Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika ylönannetaan pappein päämiehille ja kirjanoppineille; ja he tuomitsevat hänen kuolemaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 19, 'Ja antavat ylön hänen pakanoille pilkattaa, ja ruoskittaa, ja ristiinnaulittaa: ja kolmantena päivänä on hän nouseva ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 20, 'Silloin tuli hänen tykönsä Zebedeuksen poikain äiti poikinensa, kumarsi ja anoi jotakin häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 21, 'Vaan hän sanoi hänelle: mitäs tahdot? Sanoi hän hänelle: sano, että nämät kaksi minun poikaani istuisivat, yksi sinun oikialla kädelläs ja toinen vasemmallas, sinun valtakunnassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 22, 'Niin Jesus vastaten sanoi: ette tiedä, mitä te anotte. Voitteko juoda sen kalkin, jonka minun pitää juoman, ja kastettaa sillä kasteella, jolla minä kastetaan? He sanoivat hänelle: me voimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 23, 'Ja hän sanoi heille: minun kalkkini tosin te juotte ja sillä kasteella, jolla minä kastetaan, te kastetaan; mutta istua minun oikialla kädelläni, taikka vasemmalla, ei ole minun antamisellani, vaan joille se on valmistettu minun Isältäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 24, 'Ja kuin ne kymmenen sen kuulivat, närkästyivät he niistä kahdesta veljeksestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 25, 'Mutta Jesus kutsui heidät tykönsä ja sanoi: te tiedätte, että kansain päämiehet vallitsevat heitä, ja ylimmäisillä on valta heidän ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 26, 'Vaan ei niin pidä oleman teidän keskenänne; mutta joka tahtoo teidän seassanne suurin olla, se olkoon teidän palvelianne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 27, 'Ja joka tahtoo teidän seassanne ensimäinen olla, se olkoon teidän palvelianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 28, 'Niinkuin ei Ihmisen Poika tullut, että häntä piti palveltaman, mutta että hän palvelis, ja antais henkensä lunastukseksi monen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 29, 'Ja heidän lähteissänsä Jerikosta, seurasi häntä paljo kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 30, 'Ja katso, kaksi sokiaa istuivat tien ohessa. Kuin he kuulivat, että Jesus kävi ohitse, huusivat he, sanoen: Herra, Davidin Poika, armahda meitä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 31, 'Niin kansa torui heitä vaikenemaan. Mutta he huusivat enemmin, sanoen: Herra, Davidin Poika, armahda meitä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 32, 'Ja Jesus seisahti, ja kutsui heidät tykönsä, ja sanoi: mitä te tahdotte, että minun pitää teille tekemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 33, 'Sanoivat he hänelle: Herra, että meidän silmämme aukenisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 34, 'Niin Jesus armahti heitä ja tarttui heidän silmiinsä, ja he saivat kohta näkönsä ja seurasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 1, 'Ja kuin he lähestyivät Jerusalemia ja tulivat Betphageen öljymäen tykö, lähetti Jesus kaksi opetuslasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 2, 'Sanoen heille: menkäät kylään, joka on edessänne, ja te löydätte kohta aasintamman sidottuna, ja varsan hänen kanssansa: päästäkäät ne ja tuokaat minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 3, 'Ja jos joku teille jotakin sanoo, niin sanokaat: Herra niitä tarvitsee, ja kohta hän laskee heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 4, 'Mutta tämä kaikki tapahtui, että täytettäisiin, mikä sanottu oli prophetan kautta, joka sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 5, 'Sanokaat Zionin tyttärelle: katso, sinun Kuninkaas tulee sinulle siviä, istuen aasintamman päällä ja ikeen alaisen aasin varsan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 6, 'Niin opetuslapset menivät ja tekivät niinkuin Jesus heille käskenyt oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 7, 'Ja taluttivat aasintamman ja varsan, ja panivat niiden päälle vaatteensa, ja istuttivat hänen niiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 8, 'Niin enin osa kansasta hajoitti vaatteensa tielle, ja muut karsivat oksia puista ja hajoittivat tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 9, 'Mutta kansa, joka edellä kävi, ja jotka seurasivat, huusivat, sanoen: hosianna Davidin Pojalle! kiitetty olkoon se, joka tulee Herran nimeen! hosianna korkeudessa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 10, 'Ja kuin hän tuli Jerusalemiin, nousi koko kaupunki, sanoen: kuka on tämä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 11, 'Niin kansa sanoi: tämä on Jesus, propheta Galilean Natsaretista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 12, 'Ja Jesus meni sisälle Jumalan templiin, ja ajoi ulos kaikki, jotka myivät ja ostivat templissä, ja vaihettajain pöydät ja kyyhkyisten kaupitsiain istuimet hän kukisti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 13, 'Ja sanoi heille: kirjoitettu on: minun huoneeni pitää rukoushuoneeksi kutsuttaman; mutta te olette sen tehneet ryöväritten luolaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 14, 'Ja hänen tykönsä tulivat sokiat ja ontuvat templissä, ja hän paransi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 15, 'Mutta kuin pappein päämiehet ja kirjanoppineet näkivät ne ihmeet, jotka hän teki, ja lapset templissä huutavan ja sanovan: hosianna Davidin Pojalle! närkästyivät he,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 16, 'Ja sanoivat hänelle: kuuletkos, mitä nämät sanovat? Niin Jesus sanoi heille: kuulen kyllä. Ettekö te koskaan ole lukeneet: lasten ja imeväisten suusta olet sinä kiitoksen valmistanut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 17, 'Ja hän luopui heistä, ja meni ulos kaupungista Betaniaan, ja oli siellä yötä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 18, 'Mutta huomeneltain kaupunkiin palatessansa isosi hän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 19, 'Ja kuin hän näki fikunapuun tien ohessa, meni hän sen tykö, ja ei löytänyt siinä mitään muuta kuin lehdet ainoastaan; ja hän sanoi sille: älköön ikänä tästäkään edes sinusta hedelmää kasvako. Ja fikunapuu kohta kuivettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 20, 'Ja kuin opetuslapset sen näkivät, ihmettelivät he, sanoen: kuinka fikunapuu niin kohta kuivettui?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 21, 'Jesus vastaten sanoi heille: totisesti sanon minä teille: jos teillä olis usko, ja ette epäilisi, niin ette ainoastaan tätä tekisi, mikä fikunapuulle tapahtui, vaan myös jos te sanoisitte tälle vuorelle: siirry ja kukistu mereen, niin se tapahtuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 22, 'Ja kaikki, mitä te anotte rukouksessa, uskoen, sen te saatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 23, 'Ja kuin hän meni templiin, tulivat hänen opettaissansa hänen tykönsä pappein päämiehet ja kansan vanhimmat, sanoen: millä voimalla sinä näitä teet? taikka kuka sinulle antoi sen voiman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 24, 'Niin Jesus vastaten sanoi heille: minä tahdon myös teiltä kysyä yhden sanan: jos te sen minulle sanotte, niin minä myös teille sanon, millä voimalla minä näitä teen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 25, 'Kusta Johanneksen kaste oli, taivaastako taikka ihmisistä? Niin he ajattelivat isellensä, sanoen: jos me sanomme: taivaasta, niin hän sanoo meille: miksi ette siis häntä uskoneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 26, 'Mutta jos me sanomme: se oli ihmisistä, niin me pelkäämme kansaa; sillä kaikki pitivät Johanneksen prophetana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 27, 'Ja he vastaten sanoivat Jesukselle: emme tiedä. Sanoi hän heille: en minä myös sano teille, millä voimalla minä näitä teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 28, 'Mutta kuinka te luulette? Yhdellä miehellä oli kaksi poikaa, ja hän meni ensimmäisen tykö, ja sanoi: poikani, mene tänäpänä tekemään työtä minun viinamäkeeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 29, 'Niin hän vastaten sanoi: en tahdo. Mutta sitte katui hän, ja meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 30, 'Niin hän meni toisen tykö, ja sanoi myös niin. Mutta hän vastaten sanoi: kyllä minä menen, herra, ja ei mennytkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 31, 'Kumpi näistä kahdesta teki isänsä tahdon? He sanoivat hänelle: ensimäinen. Sanoi Jesus heille: totisesti sanon minä teille: Publikanit ja portot käyvät teidän edellänne Jumalan valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 32, 'Sillä Johannes tuli teidän tykönne vanhurskauden tiessä, ja ette häntä uskoneet: mutta Publikanit ja portot uskoivat hänen. Mutta te, jotka sen näitte, ette sittenkään parannusta tehneet, että te häntä olisitte uskoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 33, 'Kuulkaat toinen vertaus: oli perheenisäntä, joka istutti viinamäen, ja pani aidan sen ympärille, ja kaivoi siihen viinakuurnan, ja rakensi tornin, ja pani sen vuorolle peltomiehille, ja vaelsi muille maille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 34, 'Mutta kuin hedelmäin aika lähestyi, lähetti hän palveliansa peltomiesten tykö, ottamaan sen hedelmiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 35, 'Ja peltomiehet ottivat kiinni hänen palveliansa, ja yhden he pieksivät, toisen he tappoivat, kolmannen he kivittivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 36, 'Taas hän lähetti toiset palveliat, usiammat kuin ensimäiset, ja he tekivät heille myös niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 37, 'Mutta viimein lähetti hän heidän tykönsä poikansa, sanoen: he karttavat poikaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 38, 'Mutta kuin peltomiehet näkivät pojan, sanoivat he keskenänsä: tämä on perillinen; tulkaat, tappakaamme häntä, ja niin me saamme hänen perintönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 39, 'Ja he ottivat hänen kiinni, sysäsivät ulos viinamäestä ja tappoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 40, 'Kun siis viinamäen isäntä tulee, mitä hän niiden peltomiesten tekee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 41, 'He sanoivat hänelle: ne pahat hän pahasti hukuttaa, ja antaa viinamäkensä toisille viinamäen miehille, jotka hänelle antavat hedelmät ajallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 42, 'Sanoi Jesus heille: ettekö te ikänä Raamatuissa ole lukeneet: jonka kiven rakentajat hylkäsivät, se on tullut kulmakiveksi. Herralta on se tapahtunut, ja on ihmeellinen meidän silmäimme edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 43, 'Sentähden sanon minä teille: Jumalan valtakunta pitää teiltä otettaman pois ja annettaman pakanoille, jotka sen hedelmän tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 44, 'Ja joka lankee tähän kiveen, hän runnellaan. Mutta jonka päälle hän lankee, sen hän murentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 45, 'Ja kuin pappein päämiehet ja Pharisealaiset kuulivat hänen vertauksensa, ymmärsivät he, että hän heistä sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 46, 'Ja kuin he pyysivät häntä ottaa kiinni, pelkäsivät he kansaa, sillä he pitivät hänen prophetana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 1, 'Ja Jesus vastaten puhui taas heille vertauksilla, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 2, 'Taivaan valtakunta on kuninkaan vertainen, joka teki häitä pojallensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 3, 'Ja lähetti palveliansa kutsumaan kutsutuita häihin, ja ei he tahtoneet tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 4, 'Taas hän lähetti toiset palveliat, sanoen: sanokaat kutsutuille: katso, minä valmistin atriani, härkäni ja syöttilääni ovat tapetut, ja kaikki ovat valmistetut: tulkaat häihin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 5, 'Mutta he katsoivat ylön, ja menivät pois, yksi pellollensa, toinen kaupallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 6, 'Mutta muut ottivat kiinni hänen palveliansa, ja pilkkasivat heitä, ja tappoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 7, 'Mutta kuin kuningas sen kuuli, vihastui hän, ja lähetti sotaväkensä, ja hukutti ne murhamiehet, ja heidän kaupunkinsa poltti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 8, 'Silloin hän sanoi palvelioillensa: häät tosin ovat valmistetut, mutta kutsutut ei olleet mahdolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 9, 'Menkäät siis teiden haaroihin, ja kaikki, jotka te löydätte, kutsukaat häihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 10, 'Ja palveliat menivät ulos teille, ja kokosivat kaikki, jotka he löysivät, pahat ja hyvät; ja häähuone täytettiin vieraista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 11, 'Niin kuningas meni katsomaan vieraita, ja näki siellä yhden ihmisen, joka ei ollut vaatetettu häävaatteilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 12, 'Niin hän sanoi hänelle: ystäväni, kuinkas tänne tulit, ja ei sinulla ole häävaatteita? Mutta hän vaikeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 13, 'Silloin sanoi kuningas palvelioille: sitokaat hänen kätensä ja jalkansa, ottakaat ja heittäkäät häntä ulkoiseen pimeyteen; siellä pitää oleman itku ja hammasten kiristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 14, 'Sillä monta on kutsuttu, mutta harvat ovat valitut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 15, 'Silloin Pharisealaiset menivät pitämään neuvoa, kuinka he hänen sanoissa solmeaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 16, 'Ja he lähettivät hänen tykönsä opetuslapsensa Herodilaisten kanssa, sanoen: Mestari, me tiedämme sinun totiseksi, ja sinä opetat Jumalan tien totuudessa, et myös tottele ketään; sillä et sinä katso ihmisten muotoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 17, 'Sano siis meille, kuinkas luulet: sopiiko keisarille antaa veroa taikka ei?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 18, 'Mutta kuin Jeesus ymmärsi heidän pahuutensa, sanoi hän: mitä te ulkokullatut kiusaatte minua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 19, 'Osoittakaat minulle veroraha. Niin he antoivat hänelle verorahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 20, 'Ja hän sanoi heille: kenenkä on tämä kuva ja päällekirjoitus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 21, 'He sanoivat hänelle: keisarin. Niin hän sanoi heille: antakaat keisarille, mitkä keisarin ovat, ja Jumalalle, mitkä Jumalan ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 22, 'Ja kuin he nämät kuulivat, ihmettelivät he, ja luopuivat hänestä, ja menivät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 23, 'Sinä päivänä tulivat Saddukealaiset hänen tykönsä, jotka sanovat, ettei ylösnousemusta ole, ja kysyivät häneltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 24, 'Sanoen: Mestari! Moses sanoi: jos joku kuolee lapsetoinna, niin hänen veljensä pitää naiman hänen emäntänsä ja herättämän veljellensä siemenen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 25, 'Niin oli meidän seassamme seitsemän veljestä, ja kuin ensimäinen nai, niin se kuoli. Ja ettei hänellä ollut siementä, jätti hän emäntänsä veljellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 26, 'Niin myös toinen ja kolmas, hamaan seitsemänteen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 27, 'Mutta kaikkein viimein kuoli myös se vaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 28, 'Kenenkä emännän siis näistä seitsemästä pitää hänen ylösnousemisessa oleman? Sillä kaikki ovat häntä pitäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 29, 'Niin Jesus vastaten sanoi heille: te eksytte ja ette tiedä Raamatuita, eikä Jumalan voimaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 30, 'Sillä ylösnousemisessa ei naida eikä huolla, mutta he ovat niinkuin Jumalan enkelit taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 31, 'Mutta ettekö te ole lukeneet kuolleitten ylösnousemisesta, mitä teille on Jumalalta sanottu, joka sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 32, 'Minä olen Abrahamin Jumala, ja Isaakin Jumala, ja Jakobin Jumala? Ei ole Jumala kuolleiden Jumala, mutta elävien.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 33, 'Ja kuin kansa sen kuuli, hämmästyivät he hänen oppiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 34, 'Mutta kuin Pharisealaiset sen kuulivat, että hän oli Saddukealaisten suun tukinnut, kokoontuivat he yhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 35, 'Ja yksi lain-opettaja heistä kysyi häneltä, kiusaten häntä, ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 36, 'Mestari, mikä on suurin käsky laissa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 37, 'Niin Jesus sanoi hänelle: sinun pitää rakastaman Herraa sinun Jumalaas, kaikesta sydämestäs, ja kaikesta sielustas, ja kaikesta mielestäs:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 38, 'Tämä on ensimäinen ja suurin käsky.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 39, 'Toinen on tämän kaltainen: sinun pitää rakastaman lähimmäistäs niinkuin itse sinuas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 40, 'Näissä kahdessa käskyssä kaikki laki ja prophetat riippuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 41, 'Koska Pharisealaiset koossa olivat, kysyi heiltä Jesus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 42, 'Sanoen: mitä teille näkyy Kristuksesta, kenenkä poika hän on? he sanoivat hänelle: Davidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 43, 'Hän sanoi heille: kuinka siis David kutsuu hengessä hänen Herraksi? sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 44, 'Herra sanoi minun Herralleni: istu minun oikealla kädelläni, siihenasti kuin minä panen vihollises sinun jalkais astinlaudaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 45, 'Jos siis David kutsuu hänen Herraksi, kuinka hän on hänen poikansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 46, 'Ja ei kenkään taitanut häntä mitään vastata: ei myös yksikään rohjennut sen päivän perästä häneltä enempää kysyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 1, 'Silloin Jesus puhui kansalle ja hänen opetuslapsillensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 2, 'Sanoen: Moseksen istuimella istuvat kirjanoppineet ja Pharisealaiset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 3, 'Kaikki siis, mitä he teidän käskevät pitää, se pitäkäät ja tehkäät; mutta heidän töittensä jälkeen älkäät te tehkö, sillä he sanovat, ja ei tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 4, 'Sillä he sitovat raskaat kuormat, joita ei voida kantaa, ja panevat ne ihmisten olille, mutta ei he sormellansakaan itse tahdo niitä liikuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 5, 'Mutta kaikki työnsä tekevät he, että ne ihmisiltä nähtäisiin. He levittelevät muistokirjansa, ja tekevät suureksi vaatteensa liepeet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 6, 'Ja rakastavat ylimmäisiä sijoja pidoissa ja ylimmäisiä istuimia synagogissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 7, 'Ja tervehdyksiä turulla, ja tahtovat kutsuttaa ihmisiltä: rabbi, rabbi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 8, 'Mutta älkäät te antako teitä kutsuttaa rabbiksi; sillä yksi on teidän Mestarinne, joka on Kristus, mutta te olette kaikki veljekset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 9, 'Ja älkäät ketäkään kutsuko isäksenne maan päällä; sillä yksi on Isänne, joka on taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 10, 'Ja älkäät antako teitä kutsuttaa mestariksi; sillä yksi on teidän Mestarinne, joka on Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 11, 'Joka teistä suurin on, se olkoon teidän palvelianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 12, 'Mutta joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 13, 'Mutta voi teitä, kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka suljette taivaan valtakunnan ihmisten edestä; sillä ette itse sinne mene, ettekä salli meneväisiä sinne mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 14, 'Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka syötte leskein huoneet, ja muodoksi pidätte pitkät rukoukset: sentähden te saatte sitä kovemman kadotuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 15, 'Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka merta ja mannerta ympäri vaellatte, tehdäksenne yhtä uutta Juudalaista; ja kuin se tehty on, niin te hänestä teette kaksikertaa enemmän helvetin lapsen kuin te itse olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 16, 'Voi teitä, te sokiat taluttajat! jotka sanotte: joka vannoo templin kautta, ei se mitään ole, mutta joka vannoo templin kullan kautta, se on velvollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 17, 'Te hullut ja sokiat! sillä kumpi on suurempi: kulta, eli templi, joka kullan pyhittää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 18, 'Ja joka vannoo alttarin kautta, ei se mitään ole; mutta joka vannoo lahjan kautta, joka sen päällä on, se on velvollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 19, 'Te hullut ja sokiat! sillä kumpi on suurempi: lahja, eli alttari, joka lahjan pyhittää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 20, 'Joka siis vannoo alttarin kautta, hän vannoo sen kautta ja kaikkein, mikä sen päällä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 21, 'Ja joka vannoo templin kautta, se vannoo hänen kauttansa ja sen kautta, joka siinä asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 22, 'Ja joka vannoo taivaan kautta, se vannoo Jumalan istuimen kautta ja hänen kauttansa, joka sen päällä istuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 23, 'Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka kymmenykset teette mintuista, tilleistä ja kuminoista, ja jätätte pois ne raskaammat laista, tuomion, laupiuden ja uskon: näitä piti tehtämän, ja toisia ei jätettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 24, 'Te sokiat taluttajat! te kuurnitsette hyttysen ja kamelin nielette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 25, 'Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka puhdistatte juoma-astian ja ruoka-astian ulkoiselta puolelta, mutta sisältä ovat ne täynnä raatelemista ja tyytymättömyyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 26, 'Sinä sokia Pharisealainen! puhdista ensin juoma-astia ja ruoka-astia sisältä, että myös ulkonainenkin puoli puhtaaksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 27, 'Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut; sillä te olette valkiaksi sivuttuin hautain kaltaiset, jotka ulkoa kauniit ovat, mutta sisältä ovat he täynnä kuolleiden luita ja kaikkea riettautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 28, 'Niin myös te olette ulkoa tosin nähdä ihmisten edessä hurskaat, mutta sisältä te olette täynnä ulkokullaisuutta ja vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 29, 'Voi teitä kirjanoppineet ja Pharisealaiset, te ulkokullatut! jotka rakennatte prophetain hautoja ja kaunistatte vanhurskasten hautoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 30, 'Ja sanotte: jos me olisimme olleet meidän isäimme aikoina, emme olisi olleet osalliset heidän kanssansa prophetain veressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 31, 'Niin te siis itseänne tunnustatte, että olette niiden lapset, jotka tappoivat prophetat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 32, 'Niin tekin täyttäkäät teidän isäinne määrä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 33, 'Te kärmeet, te kyykärmetten sikiät! kuinka te vältätte helvetin kadotuksen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 34, 'Sentähden, katso, minä lähetän teille prophetat, ja viisaat, ja kirjanoppineet; ja niistä te muutamat tapatte ja ristiinnaulitsette, ja muutamat te pieksätte teidän synagogissanne, ja vainootte kaupungista kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 35, 'Että teidän päällenne pitää tuleman kaikki vanhurskas veri, joka vuodatettu on maan päälle hamasta vanhurskaan Abelin verestä niin Sakariaan, Barakiaan pojan vereen asti, jonka te tapoitte templin ja alttarin vaiheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 36, 'Totisesti sanon minä teille: kaikki nämät pitää tuleman tämän suvun päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 37, 'Jerusalem, Jerusalem, sinä joka tapat prophetat ja kivillä surmaat ne, jotka sinun tykös lähetetyt ovat! kuinka usein minä tahdoin koota sinun lapses, niinkuin kana kokoo poikansa siipeinsä alle? ja ette tahtoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 38, 'Katso, teidän huoneenne pitää teille jäämän kylmille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 39, 'Sillä minä sanon teille: ette suinkaan minua tästedes näe, siihenasti kuin te sanotte: kiitetty olkoon se, joka tulee Herran nimeen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 1, 'Ja Jesus meni ulos ja läksi pois templistä, ja hänen opetuslapsensa tulivat osoittamaan hänelle templin rakennuksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 2, 'Niin sanoi Jesus heille: ettekö te kaikkia näitä näe? Totisesti sanon minä teille: ei pidä tässä jätettämän kiveä kiven päälle, joka ei maahan jaoteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 3, 'Mutta kuin hän istui Öljymäellä, menivät opetuslapset hänen tykönsä erinänsä ja sanoivat: sano meille: koska tämä tapahtuu, ja mikä sinun tulemises ja maailman lopun merkki ollee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 4, 'Ja Jesus vastasi ja sanoi heille: katsokaat, ettei kenkään teitä viettele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 5, 'Sillä monta tulevat minun nimeeni, sanoen: minä olen Kristus! ja viettelevät monta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 6, 'Niin te saatte kuulla sotia ja sanomia sodista. Katsokaat, ettette peljästy; sillä kaikki nämät pitää tapahtuman, mutta ei vielä ole loppu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 7, 'Sillä kansan pitää kansaa vastaan nouseman ja valtakunnan valtakuntaa vastaan, ja tulee ruttotauti ja nälkä ja maanjäristys moneen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 8, 'Mutta kaikki nämät ovat murhetten alku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 9, 'Silloin he ylönantavat teitä vaivaan ja tappavat teidät, ja te tulette vihattavaksi kaikilta pakanoilta minun nimeni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 10, 'Ja silloin monta pahenevat, ja keskenänsä pettävät toinen toisensa, ja vihaavat toinen toistansa keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 11, 'Ja monta väärää prophetaa nousevat ja viettelevät monta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 12, 'Ja että vääryys saa vallan, niin rakkaus monessa kylmenee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 13, 'Mutta joka vahvana pysyy loppuun asti, se tulee autuaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 14, 'Ja tämä valtakunnan evankeliumi pitää saarnattaman kaikessa maailmassa, kaikille pakanoille todistukseksi; ja silloin tulee loppu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 15, 'Kuin te siis näette hävityksen kauhistuksen, josta sanottu on Daniel prophetan kautta, seisovan pyhässä siassa; (joka tämän lukee, hän ymmärtäköön!)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 16, 'Silloin ne, jotka Juudeassa ovat, paetkoot vuorille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 17, 'Ja joka katon päällä on, älköön astuko alas ottamaan jotakin huoneestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 18, 'Ja joka pellolla on, älköön palatko vaatteitansa ottamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 19, 'Voi raskaita ja imettäväisiä niinä päivinä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 20, 'Mutta rukoilkaat, ettei teidän pakonne tapahtuisi talvella eikä sabbatina;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 21, 'Sillä silloin pitää suuren vaivan oleman, jonka kaltaista ei ole ollut maailman alusta niin tähän asti, ei myös tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 22, 'Ja ellei ne päivät olisi lyhennetyt, niin ei yksikään liha tulisi autuaaksi; mutta valittuin tähden pitää ne päivät lyhennettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 23, 'Silloin jos joku teille sanois: katso, tässä on Kristus taikka siellä! älkäät uskoko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 24, 'Sillä väärät Kristukset ja väärät prophetat nousevat, ja tekevät suuria ihmeitä ja merkkejä: niin että myös, jos taitais tapahtua, valitutkin eksytettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 25, 'Katso, minä olen teille sen ennen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 26, 'Jos he siis teille sanovat: katso, hän on korvessa! niin älkäät menkö ulos; katso, hän on kammiossa! älkäät uskoko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 27, 'Sillä niinkuin pitkäisen tuli leimahtaa idästä ja näkyy hamaan länteen, niin on myös Ihmisen Pojan tulemus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 28, 'Sillä kussa raato on, siihen kotkat kokoontuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 29, 'Mutta kohta sen ajan vaivan jälkeen aurinko pimenee, ja kuu ei anna valoansa, ja tähden putoavat taivaasta, ja taivaan voimat pitää liikutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 30, 'Ja silloin näkyy Ihmisen Pojan merkki taivaassa, ja silloin kaikki sukukunnat maassa parkuvat ja saavat nähdä Ihmisen Pojan tulevan taivaan pilvissä suurella voimalla ja kunnialla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 31, 'Ja hän lähettää enkelinsä suurella basunan äänellä, ja he kokoovat hänen valittunsa neljästä tuulesta, yhdestä taivasten äärestä niin toiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 32, 'Mutta oppikaat fikunapuusta vertaus: kuin sen oksa on tuores ja lehdet puhkeavat, niin te tiedätte suven läsnä olevan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 33, 'Niin myös te, kuin te näette nämät kaikki, tietäkäät, että se on läsnä, oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 34, 'Totisesti sanon minä teille: ei suinkaan tämän sukukunnan pidä hukkuman ennen kuin kaikki nämät tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 35, 'Taivas ja maa pitää hukkuman, mutta minun sanani ei pidä suinkaan hukkaantuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 36, 'Vaan siitä päivästä ja hetkestä ei tiedä kenkään, ei taivaan enkelitkään, vaan minun Isäni yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 37, 'Mutta niinkuin Noan ajat olivat, niin pitää myös Ihmisen Pojan tulemus oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 38, 'Sillä niinkuin he niinä päivinä vedenpaisumisen edellä olivat, söivät ja joivat, naivat ja huolivat, hamaan siihen päivään asti, jona Noa arkkiin sisälle meni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 39, 'Ja ei tietäneet ennen kuin vedenpaisumus tuli, ja otti pois kaikki: niin pitää myös Ihmisen Pojan tulemus oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 40, 'Silloin on kaksi kedolla: yksi otetaan ylös, ja toinen jätetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 41, 'Kaksi jauhavat myllyssä: yksi otetaan ylös, ja toinen jätetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 42, 'Valvokaat siis; sillä ette tiedä, millä hetkellä teidän Herranne on tuleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 43, 'Mutta se tietäkäät: jos perheenisäntä tietäis, millä hetkellä varas on tuleva, kaiketi hän valvois, eikä sallisi kaivaa huonettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 44, 'Sentähden olkaat te myös valmiit; sillä millä hetkellä ette luulekaan, tulee Ihmisen Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 45, 'Kuka siis on uskollinen ja toimellinen palvelia, jonka Herra pani perheensä päälle, antamaan heille ruokaa ajallansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 46, 'Autuas on se palvelia, jonka Herra löytää niin tehneeksi, kuin hän tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 47, 'Totisesti sanon minä teille: hän panee hänen kaiken hyvyytensä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 48, 'Mutta jos paha palvelia sanoo sydämessänsä: minun Herrani viipyy tulemasta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 49, 'Ja rupee pieksämään leipäveljiänsä, niin myös syömään ja juomaan juomarien kanssa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 50, 'Niin sen palvelian Herra tulee sinä päivänä, jona ei hän luulekaan, ja sillä hetkellä, jolla ei hän tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 51, 'Ja hän eroittaa hänen, ja antaa hänelle osan ulkokullattuin kanssa: siellä pitää oleman itku ja hammasten kiristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 1, 'Silloin pitää taivaan valtakunta oleman kymmenen neitseen kaltainen, jotka ottivat lamppunsa ja menivät ulos ylkää vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 2, 'Mutta viisi heistä oli taitavaa, ja viisi tyhmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 3, 'Tyhmät ottivat lamppunsa, ja ei ottaneet öljyä myötänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 4, 'Mutta taitavat ottiva öljyä astioihinsa, ynnä lamppunsa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 5, 'Kuin ylkä viipyi, tulivat he kaikki uneliaiksi ja makasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 6, 'Mutta puoli-yönä tuli huuto: katso, ylkä tulee, menkäät ulos häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 7, 'Niin nousivat kaikki nämät neitseet ja valmistivat lamppunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 8, 'Mutta tyhmät sanoivat taitaville: antakaat meille öljystänne; sillä meidän lamppumme sammuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 9, 'Niin vastasivat taitavat, sanoen: ei suinkaan, ettei meiltä ja teiltä puuttuisi; mutta menkäät paremmin niiden tykö, jotka myyvät, ja ostakaat itsellenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 10, 'Mutta kuin he menivät ostamaan, tuli ylkä. Ja jotka valmiit olivat, ne menivät hänen kanssansa häihin, ja ovi suljettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 11, 'Viimein tulivat nekin toiset neitseet, ja sanoivat: Herra, Herra, avaa meidän eteemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 12, 'Mutta hän vastasi ja sanoi: totisesti sanon minä teille: en tunne minä teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 13, 'Valvokaat sentähden, sillä ette tiedä päivää eikä hetkeä, jona Ihmisen Poika tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 14, 'Sillä niinkuin ihminen matkusti kauvas ja kutsui palveliansa, ja antoi heille tavaransa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 15, 'Ja antoi yhdelle viisi leiviskää, toiselle kaksi ja kolmannelle yhden, jokaiselle varansa jälkeen: ja meni kohta matkaansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 16, 'Niin meni se, joka viisi leiviskää oli ottanut, teki niillä kauppaa ja voitti toiset viisi leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 17, 'Niin myös se, joka kaksi oli ottanut, voitti myös toiset kaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 18, 'Mutta joka yhden oli ottanut, hän meni pois ja kaivoi maahan, ja kätki herransa rahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 19, 'Niin pitkän ajan perästä tuli palveliain herra ja laski lukua heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 20, 'Ja tuli se, joka oli ottanut viisi leiviskää, ja toi toiset viisi leiviskää, sanoen: herra, viisi leiviskää sinä annoit minulle, katso, minä olen toiset viisi leiviskää niillä voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 21, 'Sanoi hänen herransa hänelle: hyvin, sinä hyvä ja uskollinen palvelia! vähän päällä sinä olit uskollinen, minä panen sinun paljon päälle: mene sinun herras iloon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 22, 'Niin tuli se, joka oli kaksi leiviskää ottanut, ja sanoi: herra, kaksi leiviskää sinä annoit minulle, katso, toiset kaksi olen minä niillä voittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 23, 'Sanoi hänen herransa hänelle: hyvin, sinä hyvä ja uskollinen palvelia! vähän päällä sinä olit uskollinen, minä panen sinun paljon päälle: mene sinun herras iloon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 24, 'Niin myös se tuli, joka yhden leiviskän oli ottanut, ja sanoi: herra, minä tiesin sinun kovaksi mieheksi: sinä niität siitä, kuhunkas et kylvänyt, ja siitä sinä kokoot, kuhunka sinä et hajoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 25, 'Ja minä peljäten menin pois ja kätkin sinun leiviskäs maahan: katso, tässä on sinun omas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 26, 'Mutta hänen herransa vastasi ja sanoi hänelle: sinä paha ja laiska palvelia! jos tiesit minun siitä niittävän, kuhunka en minä kylvänyt, ja sieltä kokoovan, johonka en minä ole hajoittanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 27, 'Niin sinun siis olis tullut antaa minun rahani vaihettajille, ja minä tultuani olisin omani jälleen saanut kasvun kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 28, 'Ottakaat siis häneltä leiviskä, ja antakaat sille, jolla on kymmenen leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 29, '(Sillä jokaiselle, jolla on, pitää annettaman, ja hänellä pitää kyllä oleman; mutta jolla ei ole, sekin kuin hänellä on, pitää häneltä otettaman pois).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 30, 'Ja heittäkäät se kelvotoin palvelia ulkonaiseen pimeyteen: siellä pitää oleman itku ja hammasten kiristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 31, 'Mutta kuin Ihmisen Poika tulee kunniassansa ja kaikki pyhät enkelit hänen kanssansa, silloin hän istuu kunniansa istuimella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 32, 'Ja hänen eteensä kootaan kaikki kansat. Ja hän eroittaa toiset toisistansa, niinkuin paimen eroittaa lampaat vuohista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 33, 'ja asettaa lampaat tosin oikialle puolellensa, mutta vuohet vasemmallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 34, 'Silloin sanoo kuningas niille, jotka hänen oikialla puolellansa ovat: tulkaat, minun Isäni siunatut, omistakaat se valtakunta, joka teille on valmistettu maailman alusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 35, 'Sillä minä isosin, ja te ruokitte minun: minä janosin, ja te juotitte minun: minä olin outo, ja te minun huoneeseen otitte:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 36, 'Alasti, ja te vaatetitte minun: sairaana, ja te opitte minua: minä olin vankina, ja te tulitte minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 37, 'Silloin vanhurskaat häntä vastaavat ja sanovat: Herra, koska me näimme sinun isoovan, ja ruokimme sinun? taikka janoovan, ja annoimme sinun juoda?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 38, 'Mutta koska me näimme sinun outona, ja huoneeseen otimme sinun? taikka alastoinna, ja vaatetimme sinua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 39, 'Eli koska me näimme sinun sairaana, taikka vankina, ja tulimme sinun tykös?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 40, 'Niin vastaa kuningas ja sanoo heille: totisesti sanon minä teille: sen minkä te olette tehneet yhdelle näistä vähimmistä minun veljistäni, sen te teitte minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 41, 'Silloin hän myös sanoo niille, jotka vasemmalla ovat: menkäät pois minun tyköäni, te kirotut, ijankaikkiseen tuleen, joka valmistettu on perkeleelle ja hänen enkeleillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 42, 'Sillä minä isosin, ja ette minua ruokkineet: minä janosin, ja ette minua juottaneet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 43, 'Minä olin outo, ja ette minua huoneeseen ottaneet: alastoin, ja ette minua vaatettaneet: sairas ja vankina, ja ette minua oppineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 44, 'Silloin nekin häntä vastaavat, sanoen: Herra, koska me näimme sinun isoovan, taikka janoovan, taikka outona, eli alastoinna, eli sairaana, taikka vankina, ja emme sinua palvelleet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 45, 'Silloin hän vastaa heitä, sanoen: totisesti sanon minä teille, mitä ette tehneet yhdelle näistä vähimmistä, sitä ette tehneet minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 46, 'Ja niiden pitää menemän ijankaikkiseen vaivaan, mutta vanhurskaat ijankaikkiseen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 1, 'Ja tapahtui, kuin Jesus oli lopettanut kaikki nämät puheet, sanoi hän opetuslapsillensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 2, 'Te tiedätte, että kahden päivän perästä tulee pääsiäinen, ja Ihmisen Poika ylönannetaan ristiinnaulittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 3, 'Silloin kokoontuivat pappein päämiehet ja kirjanoppineet ja kansan vanhimmat ylimmäisen papin saliin, joka kutsuttiin Kaiphas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 4, 'Ja neuvoa pitivät, kuinka he Jesuksen kavalluksella kiinniottaisivat ja tappaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 5, 'Mutta he sanoivat, ei juhlapäivänä, ettei kansassa tule meteli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 6, 'Kuin Jesus oli Betaniassa, spitaalisen Simonin huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 7, 'Tuli vaimo hänen tykönsä, jolla oli lasi kallista voidetta, ja kaasi sen hänen päänsä päälle atrioitessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 8, 'Mutta kuin hänen opetuslapsensa sen näkivät, närkästyivät he ja sanoivat: mihinkä kelpaa tämä haaskaus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 9, 'Sillä tämä voide olis kalliisti taittu myytää ja annettaa vaivaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 10, 'Mutta kuin Jesus sen ymmärsi, sanoi hän heille: mitä te vaivaatte tätä vaimoa? Sillä hän teki hyvän työn minun kohtaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 11, 'Sillä teidän tykönänne ovat aina vaivaiset; mutta en minä teillä aina ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 12, 'Sillä että hän kaasi sen voiteen minun ruumiini päälle, sen on hän tehnyt minun hautaamisekseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 13, 'Totisesti sanon minä teille: kussa ikänä tämä evankeliumi saarnataan kaikessa maailmassa, niin tämä myös, minkä hän teki, pitää mainittaman hänen muistoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 14, 'Silloin yksi kahdestatoistakymmenestä, joka kutsuttiin Juudas Iskariot, läksi pois pappein päämiesten tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 15, 'Ja sanoi: mitä te tahdotte minulle antaa, ja minä teille hänen saatan? Ja he määräsivät hänelle kolmekymmentä hopiapenninkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 16, 'Ja siitä ajasta etsi hän soveliasta aikaa pettääksensä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 17, 'Mutta ensimäisen makian leivän päivänä tulivat opetuslapset Jesuksen tykö, sanoen hänelle: kussas tahdot, että meidän pitää sinulle valmistaman pääsiäislampaan syötää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 18, 'Niin hän sanoi: menkäät kaupunkiin yhden tykö, ja sanokaat hänelle: Mestari sanoo: minun aikani on läsnä, sinun tykönäs tahdon minä pääsiäistä pitää minun opetuslasteni kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 19, 'Ja opetuslapset tekivät niinkuin Jesus oli heitä käskenyt, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 20, 'Mutta kuin ehtoo tuli, istui hän pöydän tykönä kahdentoistakymmenen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 21, 'Ja heidän syödessänsä sanoi hän: totisesti sanon minä teille: yksi teistä minun pettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 22, 'Ja he tulivat sangen murheellisiksi, ja rupesi jokainen heistä sanomaan hänelle: Herra, lienenkö minä se?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 23, 'Mutta hän vastasi ja sanoi: joka minun kanssani pistää kätensä vatiin, se pettää minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 24, 'Ihmisen Poika tosin menee, niinkuin hänestä on kirjoitettu; mutta voi sitä ihmistä, jonka kautta Ihmisen Poika petetään! parempi olis sille ihmiselle ollut, jos ei hän olisi syntynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 25, 'Niin vastasi Juudas, joka hänen petti, ja sanoi: Mestari, olenko minä se? hän sanoi hänelle: sinäpä sen sanoit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 26, 'Mutta kuin he söivät, otti Jesus leivän, ja kiitti, mursi ja antoi opetuslapsille, ja sanoi: ottakaat, syökäät: tämä on minun ruumiini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 27, 'Ja hän otti kalkin, ja kiitti, antoi heille ja sanoi: juokaat tästä kaikki;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 28, 'Sillä tämä on minun vereni, sen uuden Testamentin, joka monen tähden vuodatetaan syntein anteeksi antamiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 29, 'Mutta minä sanon teille: en suinkaan minä silleen juo tästä viinapuun hedelmästä, siihen päivään asti kuin minä juon teidän kanssanne sen uuden minun Isäni valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 30, 'Ja kuin he olivat kiitosvirren veisanneet, menivät he ulos Öljymäelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 31, 'Silloin sanoi Jesus heille: tänä yönä te kaikki pahenette minussa; sillä kirjoitettu on: minä lyön paimenta, ja lampaat laumasta pitää hajoitettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 32, 'Mutta sittenkuin minä nousen ylös, käyn minä teidän edellänne Galileaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 33, 'Niin vastasi Pietari ja sanoi hänelle: jos vielä kaikki sinussa pahenisivat, en minä ikänä pahene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 34, 'Jesus sanoi hänelle: totisesti sanon minä sinulle: tänä yönä, ennenkuin kukko laulaa, kolmasti sinä minun kiellät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 35, 'Pietari sanoi hänelle: ja vaikka minun pitäis sinun kanssas kuoleman, en kiellä minä sinua. Niin sanoivat myös kaikki opetuslapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 36, 'Silloin tuli Jesus heidän kanssansa kylään, jota kutsutaan Getsemaneksi, ja sanoi opetuslapsillensa: istukaat tässä, niinkauvan kuin minä menen ja rukoilen tuolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 37, 'Ja hän otti tykönsä Pietarin ja kaksi Zebedeuksen poikaa, rupesi murehtimaan ja vapisemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 38, 'Niin sanoi Jesus helle: minun sieluni on suuresti murheissansa kuolemaan asti; olkaat tässä ja valvokaat minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 39, 'Ja hän meni vähän taamma, lankesi kasvoillensa, rukoillen ja sanoen: minun Isäni! jos mahdollinen on, niin menkään pois minulta tämä kalkki: ei kuitenkaan niinkuin minä tahdon, mutta niinkuin sinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 40, 'Ja hän tuli opetuslasten tykö, ja löysi heidät makaamasta, ja sanoi Pietarille: niin ette voineet yhtä hetkeä valvoa minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 41, 'Valvokaat ja rukoilkaat, ettette kiusaukseen lankeaisi. Henki tosin on altis, mutta liha on heikko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 42, 'Taas meni hän toisen kerran ja rukoili, sanoen: minun Isäni! ellei tämä kalkki taida mennä pois minulta, muutoin jos en minä sitä juo, niin tapahtukoon sinun tahtos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 43, 'Ja hän tuli ja löysi taas heidät makaamasta; sillä heidän silmänsä olivat raskaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 44, 'Ja hän jätti heidät, meni taas ja rukoili kolmannen kerran, ja sanoi entisen sanan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 45, 'Silloin hän tuli opetuslastensa tykö, ja sanoi heille: maatkaat vielä ja levätkäät! katso, hetki on lähestynyt, ja Ihmisen Poika annetaan ylön syntisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 46, 'Nouskaat, käykäämme: katso, se lähestyi, joka minun pettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 47, 'Ja vielä hänen puhuessansa, katso, Juudas, yksi kahdestatoistakymmenestä, tuli ja hänen kanssansa paljo väkeä miekoilla ja seipäillä, pappein päämiehiltä ja kansan vanhimmilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 48, 'Mutta se, joka hänen petti, oli antanut heille merkin, sanoen: kenenkä minä suuta annan, se on, kiinniottakaat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 49, 'Ja hän astui kohta Jesuksen tykö ja sanoi: terve, Rabbi! ja suuta antoi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 50, 'Niin sanoi Jesus hänelle: ystäväni! mitä varten sinä tulit? Silloin he astuivat edes ja laskivat kätensä Jesuksen päälle, ja ottivat hänen kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 51, 'Ja katso, yksi niistä, jotka olivat Jesuksen kanssa, ojensi kätensä, veti miekkansa, ja löi ylimmäisen papin palveliaa, ja hakkasi pois hänen korvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 52, 'Niin Jesus sanoi hänelle: pistä miekkas siallensa; sillä kaikki, jotka miekkaan rupeevat, ne miekkaan hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 53, 'Taikka luuletkos, etten minä voisi vielä rukoilla minun Isääni, lähettämään minulle enemmän kuin kaksitoistakymmentä legiota enkeleitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 54, 'Kuinka siis Raamattu täytetään, että niin pitää tapahtuman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 55, 'Sillä hetkellä sanoi Jesus joukolle: niinkuin ryövärin tykö te läksitte miekoilla ja seipäillä minua kiinniottamaan: minä istuin teidän tykönänne joka päivä, opettain templissä, ja ette minua kiinniottaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 56, 'Mutta tämä on kaikki tapahtunut, että prophetain kirjoitukset täytettäisiin. Silloin kaikki opetuslapset jättivät hänen ja pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 57, 'Mutta ne, jotka Jesuksen olivat kiinniottaneet, veivät hänen Kaiphaan, ylimmäisen papin, tykö, kussa kirjanoppineet ja vanhimmat olivat kokoontuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 58, 'Mutta Pietari seurasi häntä taampana hamaan ylimmäisen papin salin porstuaan, ja meni sisälle, ja istui palveliain sekaan, näkemään loppua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 59, 'Mutta pappein päämiehet ja vanhimmat ja kaikki raati etsivät väärää todistusta Jesusta vastaan, saadaksensa häntä tappaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 60, 'Ja ei löytäneet. Ja vaikka monta väärää todistajaa tuli, niin ei he sittenkään löytäneet. Mutta viimein tuli kaksi väärää todistajaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 61, 'Ja sanoivat: tämä on sanonut: minä voin maahan jaottaa Jumalan templin, ja kolmena päivänä sen rakentaa ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 62, 'Ja pappein päämies nousi ja sanoi hänelle: etkös mitään vastaa, mitä nämät sinua vastaan todistavat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 63, 'Mutta Jesus oli ääneti. Ja pappein päämies vastasi ja sanoi hänelle: minä vannotan sinua elävän Jumalan kautta, ettäs sanot meille, jos olet Kristus, Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 64, 'Sanoi Jesus hänelle: sinäpä sen sanoit; kuitenkin sanon minä teille: tästedes pitää teidän näkemän Ihmisen Pojan istuvan voiman oikialla puolella ja tulevan taivaan pilvissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 65, 'Silloin repäisi pappein päämies vaatteensa, sanoen: hän on pilkannut (Jumalaa); mitä me silleen todistajia tarvitsemme? Katso, nyt te kuulitte hänen pilkkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 66, 'Mitä te luulette? Mutta he vastasivat ja sanoivat: hän on vikapää kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 67, 'Silloin he syljeskelivät hänen kasvoillensa ja löivät häntä poskelle, ja muutamat pieksivät häntä sauvoillansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 68, 'Sanoen: arvaa meille, Kristus, kuka on, joka sinua löi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 69, 'Mutta Pietari istui ulkona salista, ja hänen tykönsä tuli yksi piika ja sanoi: sinä olit myös Jesuksen kanssa Galileasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 70, 'Mutta hän kielsi kaikkein edessä ja sanoi: en minä tiedä, mitäs sanot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 71, 'Kuin hän läksi ulos ovesta, näki hänen toinen piika ja sanoi niille, jotka siellä olivat: ja tämä oli Jesuksen Natsaretilaisen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 72, 'Ja hän kielsi taas vannotulla valalla: en tunne minä sitä ihmistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 73, 'Mutta vähän hetken perästä tulivat ne, jotka siellä seisoivat ja sanoivat Pietarille: totisesti olet sinä myös yksi heistä; sillä sinun puheeskin ilmoittaa sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 74, 'Niin hän rupesi itsiänsä sadattelemaan ja vannomaan: en tunne minä sitä ihmistä. Ja kohta kukko lauloi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 75, 'Niin Pietari muisti Jesuksen sanan, joka oli hänelle sanonut: ennenkuin kukko laulaa, kolmasti sinä minun kiellät. Ja hän meni ulos ja itki katkerasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 1, 'Mutta kuin aamu tuli, pitivät kaikki pappein päämiehet ja kansan vanhimmat neuvoa Jesusta vastaan, häntä kuolettaaksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 2, 'Ja sitoivat hänen, menivät pois ja ylönantoivat hänen maaherralle Pontius Pilatukselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 3, 'Kuin Juudas, joka hänen petti, näki hänen kuolemaan tuomituksi, katui hän, ja toi jälleen ne kolmekymmentä hopiapenninkiä pappein päämiehille ja vanhimmille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 4, 'Sanoen: minä pahasti tein, että minä petin viattoman veren. Mutta he sanoivat: mitä meidän siihen tulee? katso itsiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 5, 'Ja hän heitti hopiapenningit templiin, läksi sieltä, meni pois ja hirtti itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 6, 'Mutta pappein päämiehet ottivat hopiapenningit ja sanoivat: ei näitä sovi panna uhriarkkuun; sillä se on veren hinta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 7, 'Niin he pitivät neuvoa, ja ostivat niillä savenvalajan pellon, vierasten hautaamiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 8, 'Sentähden se pelto on kutsuttu tähän päivään asti veripelloksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 9, 'Silloin täytettiin se mikä sanottu oli Jeremias prophetalta, joka sanoo: ja he ottivat kolmekymmentä hopiapenninkiä, sen arvatun hinnan, jonka he arvasivat Israelin lapsilta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 10, 'Ja antoivat ne savenvalajan pellosta, niinkuin Herra on minun käskenyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 11, 'Mutta Jesus seisoi maaherran edessä. Niin maaherra kysyi häneltä, sanoen: oletkos sinä Juudalaisten kuningas? Jesus sanoi hänelle: sinäpä sen sanot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 12, 'Ja kuin hänen päällensä kannettiin pappein päämiehiltä ja vanhimmilta, ei hän mitään vastannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 13, 'Silloin sanoi Pilatus hänelle: etkös kuule, kuinka paljon he sinua vastaan todistavat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 14, 'Ja ei hän vastannut häntä yhtäkään sanaa, niin että maaherra suuresti ihmetteli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 15, 'Mutta juhlana oli maaherra tottunut päästämään kansalle jonkun vangin irralle, jonka he tahtoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 16, 'Niin oli heillä silloin yksi kuuluisa vanki sidottuna, joka kutsuttiin Barabbas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 17, 'Kuin he siis koossa olivat, sanoi Pilatus heille: kumman te tahdotte, että minä päästän teille? Barabbaan, taikka Jesuksen, joka kutsutaan Kristus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 18, 'Sillä hän tiesi, että he hänen kateuden tähden olivat antaneet ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 19, 'Mutta kuin hän tuomio-istuimelle istui, lähetti hänen emäntänsä hänen tykönsä, sanoen: älä sinä mitään tee sille vanhurskaalle; sillä minä olen paljon kärsinyt tänäpänä unessani hänen tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 20, 'Mutta pappein päämiehet ja vanhimmat yllyttivät kansaa anomaan Barabbasta, mutta Jesusta hukkaamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 21, 'Niin vastasi maaherra ja sanoi heille: kumman näistä kahdesta te tahdotte, että minä päästän teille? mutta he sanoivat: Barabbaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 22, 'Pilatus sanoi heille: mitä siis minun pitää tekemän Jesukselle, joka kutsutaan Kristus? Sanoivat he kaikki hänelle: ristiinnaulittakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 23, 'Niin sanoi maaherra: mitä hän pahaa teki? Mutta he huusivat sitä enemmin ja sanoivat: ristiinnaulittakaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 24, 'Kuin Pilatus näki, ettei hän mitään auttaa taitanut, mutta enempi pauhina tuli, otti hän vettä ja pesi kätensä kansan edessä, sanoen: viatoin olen minä tämän vanhurskaan vereen: katsokaat itsiänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 25, 'Ja kaikki kansa vastasi ja sanoi: hänen verensä tulkaan meidän päällemme ja lastemme päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 26, 'Silloin päästi hän heille Barabbaan; mutta Jesuksen, kuin hän hänen ruoskinut oli, antoi hän ylön ristiinnaulittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 27, 'Silloin maaherran huovit veivät Jesuksen raastupaan, ja kokosivat hänen tykönsä kaiken joukon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 28, 'Ja kuin he olivat hänen riisuneet, puettivat he hänen purpuraiseen kaapuun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 29, 'Ja tekivät orjantappuroista kruunun ja panivat hänen päähänsä ja ruovon hänen oikiaan käteensä, ja kumarsivat polviansa hänen edessänsä, pilkkasivat häntä ja sanoivat: terve, Juudalaisten kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 30, 'Ja kuin he olivat sylkeneet hänen päällensä, ottivat he ruovon ja löivät häntä päähän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 31, 'Ja sittekuin he olivat häntä pilkanneet, riisuivat he häneltä kaapun, ja puettivat hänen omiin vaatteisiinsa, ja veivät hänen ristiinnaulittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 32, 'Mutta kuin he menivät ulos, löysivät he yhden miehen Kyrenistä, nimeltä Simon: sen he vaativat hänen ristiänsä kantamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 33, 'Ja tulivat siihen paikkaan, joka kutsutaan Golgata, se on: pääkallon paikka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 34, 'He antoivat hänelle etikkaa juoda sapella sekoitettua; ja kuin hän maisti, niin ei hän tahtonut juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 35, 'Mutta sitte kuin he olivat hänen ristiinnaulinneet, jakoivat he hänen vaatteensa ja heittivät arpaa, että täytettäisiin, mitä sanottu oli prophetan kautta; he ovat minun vaatteeni jakaneet, ja minun vaatteistani ovat he heittäneet arpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 36, 'Ja istuen he vartioitsivat häntä siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 37, 'Ja he panivat hänen päänsä päälle hänen syynsä kirjoitetun: TÄMÄ ON JESUS, JUUDALAISTEN KUNINGAS.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 38, 'Silloin ristiinnaulittiin kaksi ryöväriä hänen kanssansa, yksi oikialle puolelle ja toinen vasemmalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 39, 'Mutta ohitsekäyväiset pilkkasivat häntä, vääntelivät päätänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 40, 'Ja sanoivat: sinä joka maahan jaotat Jumalan templin ja kolmena päivänä sen rakennat, auta itsiäs: jos olet Jumalan Poika, niin astu alas rististä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 41, 'Niin myös pappein päämiehet, kirjanoppineitten ja vanhimmitten kanssa, pilkkasivat häntä ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 42, 'Muita hän on auttanut, itsiänsä ei hän voi auttaa. Jos hän on Israelin kuningas, niin astukaan nyt alas rististä, niin me uskomme hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 43, 'Hän turvasi Jumalaan: päästäköön nyt hänen, jos hän mielistyy häneen. Sillä hän sanoi: Jumalan Poika minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 44, 'Sitä myös ryövärit hänelle soimasivat, jotka olivat ristiinnaulitut hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 45, 'Mutta kuudennesta hetkestä hamaan yhdeksänteen asti oli pimiä kaikessa maassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 46, 'Ja liki yhdeksättä hetkeä huusi Jesus suurella äänellä, sanoen: Eli, Eli, lamma sabaktani? se on: minun Jumalani, minun Jumalani, miksis minun ylenannoit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 47, 'Mutta muutamat niistä, jotka siinä seisoivat, kuin he sen kuulivat, sanoivat: Eliasta hän huutaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 48, 'Ja kohta juoksi yksi heistä ja otti sienen, ja täytti sen etikalla, pani sen ruovon päähän, ja antoi hänen juoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 49, 'Mutta muut sanoivat: pidäs, katsokaamme, jos Elias tulee häntä päästämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 50, 'Niin Jesus taas huusi suurella äänellä, ja antoi henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 51, 'Ja katso, templin esivaate repesi kahtia ylhäältä hamaan alas, ja maa järisi, ja kalliot halkesivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 52, 'Ja haudat aukenivat, ja monta pyhäin ruumista, jotka maanneet olivat, nousi ylös,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 53, 'Ja läksivät ulos haudoista, hänen ylösnousemisensa jälkeen, tulivat pyhään kaupunkiin, ja ilmestyivät monelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 54, 'Mutta kuin sadanpäämies ja ne, jotka hänen kanssansa olivat vartioitsemassa Jesusta, näkivät maan järinän ja ne, mitkä tapahtuivat, pelkäsivät he suuresti ja sanoivat: totisesti oli tämä Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 55, 'Mutta siellä oli paljo vaimoja taampana katselemassa, jotka Jesusta olivat seuranneet Galileasta, palvellen häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 56, 'Joiden seassa oli Maria Magdalena, ja Maria Jakobin ja Joseen äiti, ja Zebedeuksen poikain äiti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 57, 'Mutta kuin ehtoo tuli, tuli yksi rikas mies Arimatiasta, jonka nimi oli Joseph, joka myös itse oli Jesuksen opetuslapsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 58, 'Tämä meni Pilatuksen tykö ja pyysi Jesuksen ruumista. Silloin Pilatus käski annettaa ruumiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 59, 'Ja kuin Joseph oli ruumiin ottanut, kääri hän sen puhtaasen liinaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 60, 'Ja pani omaan uuteen hautaansa, jonka hän oli hakannut kallioon, ja vieritti suuren kiven haudan ovelle, ja meni pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 61, 'Silloin olivat siellä Maria Magdalena ja toinen Maria, ja istuivat haudan kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 62, 'Mutta toisena päivänä valmistuksen päivästä kokoontuivat pappein päämiehet ja Pharisealaiset Pilatuksen tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 63, 'Sanoen: herra, me muistamme sen vietteliän sanoneen eläissänsä: kolmen päivän perästä minä nousen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 64, 'Käske siis varjeltaa hautaa kolmanteen päivään asti, ettei hänen opetuslapsensa tulisi yöllä ja varastaisi häntä, ja sanoisi kansalle: hän nousi kuolleista: ja niin jälkimäinen villitys tulee pahemmaksi kuin ensimäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 65, 'Pilatus sanoi heille: teillä on vartiat: menkäät, vartioitkaat niinkuin te tiedätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 66, 'Mutta he menivät pois, ja vahvistivat haudan vartiain kanssa, ja lukitsivat kiven sinetillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 1, 'Mutta sabbatin päivän lopulla, joka rupesi valaisemaan toista sabbatia, tuli Maria Magdalena ja toinen Maria katsomaan hautaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 2, 'Ja katso, suuri maanjäristys tapahtui; sillä Herran enkeli astui alas taivaasta, tuli ja vieritti kiven ovelta, ja istui sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 3, 'Ja hän oli nähdä niinkuin pitkäisen tuli ja hänen vaatteensa olivat valkiat niinkuin lumi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 4, 'Mutta hänen pelvostansa hämmästyivät vartiat ja tulivat niinkuin he olisivat kuolleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 5, 'Mutta enkeli vastasi ja sanoi vaimoille: älkäät peljätkö, sillä minä tiedän teidän etsivän ristiinnaulittua Jesusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 6, 'Ei hän ole tässä; sillä hän nousi ylös, niinkuin hän sanoi. Tulkaat, katsokaat siaa, kuhunka Herra pantu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 7, 'Ja menkäät pian ja sanokaat hänen opetuslapsillensa, että hän nousi kuolleista. Ja katso, hän menee teidän edellänne Galileaan: siellä teidän pitää hänen näkemän, katso, minä sen teille sanoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 8, 'Ja he menivät nopiasti haudalta suurella pelvolla ja ilolla, ja juoksivat ilmoittamaan hänen opetuslapsillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 9, 'Mutta heidän mennessänsä ilmoittamaan hänen opetuslapsillensa, katso, niin tuli Jesus heitä vastaan ja sanoi: terve teille! Niin he tulivat ja rupesivat hänen jalkoihinsa, ja kumartaen rukoilivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 10, 'Silloin sanoi Jesus heille: älkäät peljätkö! menkäät, ilmoittakaat minun veljilleni, että he menisivät Galileaan: siellä he saavat minun nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 11, 'Mutta kuin he menivät pois, katso, niin tulivat muutamat vartioista kaupunkiin ja ilmoittivat ylimmäisille papeille kaikki, mitä tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 12, 'Niin he kokoontuivat vanhimpain kanssa, ja neuvoa pitivät, ja antoivat sotamiehille paljon rahaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 13, 'Sanoen: sanokaat, että hänen opetuslapsensa tulivat yöllä ja varastivat hänen meidän maatessamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 14, 'Ja jos se tulee maaherran korville, niin me tahdomme hänen lepyttää ja saattaa teidät suruttomaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 15, 'Ja he ottivat rahan, ja tekivät niinkuin he olivat opetetut. Ja tämä puhe on ääneksi otettu Juudalaisten seassa hamaan tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 16, 'Mutta ne yksitoistakymmentä opetuslasta menivät Galileaan, sille mäelle, jonka Jesus oli heille määrännyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 17, 'Ja kuin he näkivät hänen, kumarsivat he häntä, mutta muutamat epäilivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 18, 'Ja Jesus tuli ja puhutteli heitä, sanoen: minulle on annettu kaikki voima taivaassa ja maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 19, 'Menkäät siis ja opettakaat* kaikkea kansaa, ja kastakaat heitä nimeen Isän ja Pojan ja Pyhän Hengen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 20, 'Ja opettakaat heitä pitämään kaikki, mitä minä olen teille käskenyt. Ja katso, minä olen teidän kanssanne joka päivä, maailman loppuun asti. Amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Jesuksen Kristuksen, Jumalan Pojan, evankeliumin alku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Niinkuin prophetaissa kirjoitettu on: katso, minä lähetän minun enkelini sinun kasvois eteen, joka on valmistava sinun ties sinun etees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Huutavan ääni on korvessa: valmistakaat Herran tietä, tehkäät hänen polkunsa oikiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Johannes kasti korvessa ja saarnasi parannuksen kastetta syntein anteeksi antamiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Ja hänen tykönsä meni ulos koko Juudean maakunta ja Jerusalemin asuvaiset, ja kastettiin kaikki häneltä Jordanin virrassa, tunnustain syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Ja Johannes oli puetettu kamelin karvoilla, ja ympäri hänen suoliansa oli hihnainen vyö, ja söi heinäsirkkoja ja metsähunajaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Ja saarnasi, sanoen: se tulee minun jälkeeni, joka on minua väkevämpi, jonka en minä ole kelvollinen kumarruksissa kenkäin rihmaa päästämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Minä tosin kastan teitä vedellä; mutta hän kastaa teitä Pyhällä Hengellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Ja tapahtui niinä päivinä, että Jesus tuli Galilean Natsaretista ja kastettiin Johannekselta Jordanissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Ja kohta kuin hän astui vedestä ylös, näki hän taivaat aukenevan ja Hengen tulevan alas hänen päällensä niinkuin kyyhkyisen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ja ääni tuli taivaasta: sinä olet minun rakas Poikani, johonka minä mielistyin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Ja Henki ajoi hänen kohta korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Ja hän oli siellä korvessa neljäkymmentä päivää, ja kiusattiin perkeleeltä, ja oli petoin seassa; ja enkelit palvelivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Mutta sitte kuin Johannes oli vankiuteen annettu ylön, tuli Jesus Galileaan, saarnaten Jumalan valtakunnan evankeliumia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'Ja sanoi: aika on täytetty, ja Jumalan valtakunta on lähestynyt: tehkäät parannus ja uskokaat evankeliumi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, 'Ja kuin hän käveli Galilean meren tykönä, näki hän Simonin ja Andreaksen hänen veljensä laskevan verkkoa mereen: (sillä he olivat kalamiehet:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, 'Ja Jesus sanoi heille: seuratkaat minua, ja minä teen teidät, että te tulette ihmisten kalamiehiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, 'Ja he jättivät kohta verkkonsa ja seurasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'Ja kuin hän sieltä vähää edemmä kävi, näki hän Jakobin Zebedeuksen pojan ja Johanneksen, hänen veljensä, parantavan venheessä verkkojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'Ja hän kutsui kohta heitä. Ja he jättivät isänsä Zebedeuksen venheeseen palkollisten kanssa, ja seurasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'Ja he menivät sisälle Kapernaumiin; ja hän meni kohta lepopäivinä synagogaan, ja opetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'Ja he hämmästyivät hänen opetustansa; sillä hän opetti heitä voimallisesti, ja ei niinkuin kirjanoppineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, 'Ja heidän synagogassansa oli ihminen riivattu saastaiselta hengeltä, ja hän huusi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'Sanoen: voi, mitä meidän on sinun kanssas, Jesus Natsarealainen! tulitkos meitä hukuttamaan? Minä tunnen sinun, kukas olet, Jumalan pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 25, 'Ja Jesus nuhteli häntä, sanoen: vaikene ja mene ulos hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 26, 'Ja kuin se saastainen henki repäisi häntä ja huusi suurella äänellä, niin hän läksi ulos hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 27, 'Ja he hämmästyivät kaikki, niin että he kyselivät keskenänsä, sanoen: mitä tämä on? mikä uusi oppi tämä on? Sillä hän käskee myös voimalla saastaisia henkiä, ja he kuulevat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 28, 'Ja hänen sanomansa kuului kohta ympäri kaiken Galilean lähimaakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 29, 'Ja he menivät kohta ulos synagogasta ja tulivat Simonin ja Andreaksen huoneeseen, Jakobin ja Johanneksen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 30, 'Mutta Simonin anoppi makasi vilutaudissa, ja he sanoivat hänestä kohta hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 31, 'Ja hän meni ja nosti häntä, ja rupesi hänen käteensä, ja vilutauti jätti hänen kohta; ja hän palveli heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 32, 'Mutta ehtoona, kuin aurinko laski, toivat he hänen tykönsä kaikkinaisia sairaita ja perkeleiltä riivatuita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 33, 'Ja koko kaupunki tuli kokoon oven eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 34, 'Ja hän paransi monta, jotka sairastivat moninaisia tauteja, ja hän ajoi ulos paljon perkeleitä, eikä sallinut perkeleiden puhua; sillä he tunsivat hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 35, 'Ja huomeneltain sangen varhain ennen päivää, kuin hän nousi, meni hän ulos. Ja Jesus meni erinäiseen asiaan ja rukoili siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 36, 'Ja Simon riensi hänen perässänsä ja ne jotka hänen kanssansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 37, 'Ja kuin he löysivät hänen, sanoivat he hänelle: jokainen etsii sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 38, 'Ja hän sanoi heille: menkäämme lähimmäisiin kyliin, että minä sielläkin saarnaisin; sillä sitä varten olen minä tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 39, 'Ja hän saarnasi heidän synagogissansa, koko Galileassa, ja ajoi ulos perkeleitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 40, 'Ja hänen tykönsä tuli spitalinen, rukoili häntä, lankesi polvillensa hänen eteensä ja sanoi hänelle: jos sinä tahdot, niin sinä voit minun puhdistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 41, 'Ja Jesus armahti häntä ja ojensi kätensä, rupesi häneen ja sanoi hänelle: minä tahdon, ole puhdas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 42, 'Ja kuin hän sen oli sanonut, niin spitali läksi hänestä kohta pois, ja hän tuli puhtaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 43, 'Ja Jesus haasti häntä, ja lähetti hänen kohta pois tyköänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 44, 'Ja sanoi hänelle: katso, ettes kellenkään mitään sano, mutta mene, osoita itses papille ja uhraa puhdistukses edestä ne, mitkä Moses käski, heille todistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 45, 'Mutta kuin hän meni ulos, rupesi hän paljon saarnaamaan ja ilmoittamaan sitä asiaa, niin ettei hän sitte taitanut julkisesti kaupunkiin mennä; mutta oli ulkona erinäisissä paikoissa, ja joka taholta tultiin hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Ja taas muutamain päiväin jälkeen meni hän Kapernaumiin, ja se kuultiin, että hän huoneessa oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Ja kohta kokoontuivat monta, niin ettei enää siaa ollut, ei ovenkaan tykönä; ja hän puhui heille sanan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Ja hänen tykönsä tulivat, jotka toivat yhtä halvattua, joka neljältä kannettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Ja kuin ei he saaneet häntä lähestyä kansan tähden, niin he kiskoivat huoneen katon, jossa hän oli, ja kaivoivat lävitse, ja laskivat vuoteen alas, jossa halvattu makasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Mutta kuin Jesus näki heidän uskonsa, sanoi hän halvatulle: poikani, sinun syntis annetaan sinulle anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Niin siellä olivat muutamat kirjanoppineista, jotka istuivat ja ajattelivat sydämessänsä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Mitä tämä niin pilkkaa puhuu? Kuka voi synnit antaa anteeksi paitsi ainoaa Jumalaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Ja kohta kuin Jesus tunsi hengessänsä, että he niin itsellänsä ajattelivat, sanoi hän heille: mitä te näitä ajattelette teidän sydämessänne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Kumpi on keviämpi, sanoa halvatulle: synnit annetaan sinulle anteeksi, taikka sanoa: nouse, ja ota sinun vuotees ja käy?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Mutta että teidän pitää tietämän Ihmisen Pojalla olevan vallan maan päällä synnit anteeksi antaa, (sanoi hän halvatulle:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Minä sanon sinulle: nouse ja ota vuotees, ja mene kotias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Ja hän nousi kohta ja otti vuoteen ja meni ulos kaikkein nähden, että he kaikki hämmästyivät ja kunnioittivat Jumalaa, sanoen: emme ole ikänä sen muotoista nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Ja hän läksi taas ulos meren puoleen, ja kaikki kansa tuli hänen tykönsä, ja hän opetti heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ja kuin hän meni ohitse, näki hän Levin Alphein pojan istuvan tullihuoneessa, ja sanoi hänelle: seuraa minua. Ja hän nousi ja seurasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Ja tapahtui, kuin hän atrioitsi hänen huoneessansa, atrioitsi myös monta Publikania ja syntistä Jesuksen ja hänen opetuslastensa kanssa; sillä niitä oli paljo, jotka häntä olivat seuranneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Ja kuin kirjanoppineet ja Pharisealaiset näkivät hänen syövän Publikanien ja syntisten kanssa, sanoivat he hänen opetuslapsillensa: miksi hän syö ja juo Publikanien ja syntisten kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Ja kuin Jesus sen kuuli, sanoi hän heille: ei terveet tarvitse parantajaa, vaan sairaat: en minä ole tullut kutsumaan vanhurskaita, vaan syntisiä parannukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Ja Johanneksen ja Pharisealaisten opetuslapset paastosivat; niin he tulivat ja sanoivat hänelle: miksi Johanneksen ja Pharisealaisten opetuslapset paastoovat, mutta ei sinun opetuslapses paastoo?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, 'Ja Jesus sanoi heille: kuinka hääjoukko taitaa paastota, niinkauvan kuin ylkä on heidän kanssansa? Niinkauvan kuin ylkä on heidän kanssansa, ei he voi paastota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'Mutta ne päivät tulevat, että ylkä heiltä otetaan pois, ja niinä päivinä pitää heidän paastooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, 'Ja ei ompele kenkään uutta paikkaa vanhaan vaatteeseen; sillä uusi paikka repäisee itsensä kuitenkin vanhasta, ja läpi tulee pahemmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 22, 'Ja ei pane kenkään nuorta viinaa vanhoihin leileihin; muutoin nuori viina särkee leilit, ja niin viina vuotaa pois, ja leilit turmellaan; mutta nuori viina pitää uusiin leileihin pantaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 23, 'Ja tapahtui, että hän kävi sabbatina laihoin lävitse, niin hänen opetuslapsensa rupesivat käydessänsä tähkäpäitä katkomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 24, 'Ja Pharisealaiset sanoivat hänelle: katso miksi he tekevät sabbatina, jota ei sovi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 25, 'Ja hän sanoi heille: ettekö te ole ikänä lukeneet, mitä David teki hädillänsä, kuin hän isosi ja ne, jotka hänen kanssansa olivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 26, 'Kuinka hän meni Jumalan huoneeseen, ylimmäisen papin Abjatarin aikana, ja söi näkyleivät, joita ei sopinut syödä, vaan ainoasti pappein, ja hän antoi myös niille, jotka hänen kanssansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 27, 'Ja hän sanoi heille: sabbati on ihmistä varten tehty ja ei ihminen sabbatia varten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 28, 'Niin on myös Ihmisen poika sabbatin Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Ja hän meni sisälle jälleen synagogaan, ja siellä oli ihminen, jolla oli kuivettunut käsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Ja he ottivat hänestä vaarin, jos hän hänen sabbatina parantais, kantaaksensa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Ja hän sanoi sille ihmiselle, jolla kuivettunut käsi oli: astu edes!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Ja hän sanoi heille: sopiiko sabbatina hyvää tehdä eli pahaa tehdä? henkeä vapahtaa taikka tappaa? Mutta he vaikenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Niin hän katsoi heidän päällensä vihaisesti ja oli murheissansa heidän sydämensä kovuuden tähden, ja sanoi ihmiselle: ojenna kätes! ja hän ojensi, ja käsi tuli terveeksi niinkuin toinenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Ja Pharisealaiset menivät ulos ja pitivät kohta Herodilaisten kanssa neuvoa häntä vastaan, kuinka he hänen hukuttaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Mutta Jesus poikkesi opetuslastensa kanssa meren tykö, ja paljo kansaa seurasi häntä Galileasta ja Juudeasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Ja Jerusalemista, ja Idumeasta, ja tuolta puolen Jordania, ja jotka Tyron ja Sidonin ympärillä asuivat, suuri joukko: jotka hänen tekonsa kuulivat, ne tulivat hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Ja hän sanoi opetuslapsillensa, että venhe olis aina häntä läsnä kansan tähden, ettei he häntä ahdistaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Sillä hän oli monta parantanut, niin että kaikki, joita vaivattiin, tunkivat hänen päällensä rupeemaan häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Ja kuin saastaiset henget näkivät hänen, lankesivat he hänen eteensä maahan, huusivat, sanoen: sinä olet Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Ja hän haasti heitä kovin häntä ilmoittamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Ja hän astui ylös vuorelle ja kutsui tykönsä, jotka hän itse tahtoi, ja he tulivat hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Ja hän sääsi ne kaksitoistakymmentä olemaan tykönänsä, että hän heitä lähettäis saarnaamaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Ja että heillä piti voima oleman taudit parantaa ja perkeleitä ajaa ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Ja pani Simonille nimen Pietari,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Ja Jakobille Zebedeuksen pojalle ja Johannekselle Jakobin veljelle: (ja antoi heille nimet Boanerges, se on, pitkäisen pojat),');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Ja Andreaksen, ja Philippuksen, ja Bartolomeuksen, ja Matteuksen, ja Toomaan, ja Jakobin Alphein pojan, ja Taddeuksen, ja Simonin Kananealaisen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Ja Juudaan Iskariotilaisen, joka myös hänen petti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 20, 'Ja he tulivat huoneeseen; ja kansa taas kokoontui, niin ettei heillä ollut tilaa syödäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 21, 'Ja kuin hänen omaisensa sen kuulivat, menivät he ulos ottamaan häntä kiinni; sillä he sanoivat: hän on mielettömäksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 22, 'Mutta kirjanoppineet, jotka Jerusalemista olivat tulleet alas, sanoivat: hänellä on beelsebub, ja perkeleiden pääruhtinaan kautta hän ajaa ulos perkeleitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 23, 'Ja hän kutsui heidät tykönsä, ja sanoi heille vertauksilla: kuinka taitaa saatana saatanan ajaa ulos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 24, 'Ja jos valtakunta erkanee itsiänsä vastaan, niin ei se valtakunta taida seisoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 25, 'Ja jos huone erkanee itsiänsä vastaan, niin ei se huone taida seisoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 26, 'Ja jos saatana karkaa ja eroittaa itsensä itsiänsä vastaan, niin ei hän taida seisoa, mutta saa lopun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 27, 'Ei taida kenkään väkevän huoneeseen mennä ja hänen kaluansa ryöstää, ellei hän ensin sido väkevää kiinni, ja sitte ryöstä hänen huonettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 28, 'Totisesti sanon minä teille: kaikki synnit annetaan anteeksi ihmisten lapsille, pilkatkin, joilla he Jumalaa pilkkaavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 29, 'Mutta joka puhuu pilkkaa Pyhää Henkeä vastaan, ei hän saa ijankaikkisesti anteeksi, vaan hän on vikapää ijankaikkiseen tuomioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 30, 'Sillä he sanoivat: hänellä on saastainen henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 31, 'Niin tuli hänen veljensä ja äitinsä ja seisoivat ulkona, ja lähettivät hänen tykönsä kutsumaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 32, 'Ja kansa istui hänen ympärillänsä ja sanoivat hänelle: katso, äitis ja veljes kysyvät sinua ulkona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 33, 'Ja hän vastasi heitä, sanoen: kuka on minun äitini taikka minun veljeni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 34, 'Ja kuin hän oli ympäri katsonut niiden päälle, jotka hänen ympärillänsä istuivat, sanoi hän: katso, minun äitini ja minun veljeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 35, 'Sillä joka tekee Jumalan tahdon, hän on veljeni sisareni ja äitini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Ja hän rupesi taas opettamaan meren tykönä, ja paljo kansaa kokoontui hänen tykönsä, niin että hänen piti astuman haahteen ja istuman merellä, ja kaikki kansa oli maalla meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Ja hän opetti heitä paljon vertauksilla, ja sanoi opettaissansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Kuulkaat: katso, kylväjä meni ulos kylvämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Ja kylväissä tapahtui, että muutama lankesi tien oheen, niin tulivat taivaan linnut ja söivät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Muutama lankesi kivistöön, jossa ei paljo maata ollut; joka kohta nousi päälle, ettei sillä ollut syvää maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Kuin aurinko nousi, niin se poudittiin; ja ettei sillä ollut juurta, niin se kuivettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Ja muutama lankesi orjantappuroihin, ja orjantappurat kävivät ylös ja tukahuttivat sen, eikä kantanut hedelmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Ja muutama lankesi hyvään maahan, ja kantoi hedelmän, joka kävi ylös ja kasvoi. Ja muutama kantoi kolmenkymmenen kertaiset, ja muutama kuudenkymmenen kertaiset, ja muutama sadan kertaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Ja hän sanoi heille: jolla on korvat kuulla, se kuulkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Mutta kuin hän yksinänsä oli, kysyivät ne, jotka hänen ympärillänsä kahdentoistakymmenen kanssa olivat, häneltä sitä vertausta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Ja hän sanoi heille: teille on annettu tuta Jumalan valtakunnan salaisuus; mutta niille, jotka ulkona ovat, tapahtuvat kaikki vertausten kautta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Että he nähden näkisivät ja ei huomaitsisi, ja kuullen kuulisivat ja ei ymmärtäisi: ettei he joskus palajaisi, ja heille annettaisiin synnit anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Ja sanoi heille: ettekö te tiedä tätä vertausta? ja kuinka te kaikki vertaukset ymmärtäisitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Kylväjä kylvää sanan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Mutta nämä ovat, ne jotka tien vieressä ovat: kussa sana kylvetään, ja kuin he sen ovat kuulleet, tulee kohta saatana ja ottaa pois sanan, joka heidän sydämiinsä kylvetty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Ja ne ovat senkaltaiset, jotka kivistöön kylvetyt ovat: kuin he sanan kuulleet ovat, ottavat he sen kohta ilolla vastaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'Ja ei ole heissä juurta, mutta ovat ajalliset; sitte kuin murhe taikka vaino tulee sanan tähden, niin he kohta pahenevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, 'Ja muutamat ovat, jotka orjantappuroihin kylvetyt ovat: ne kuulevat sanan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 19, 'Ja tämän maailman suru, ja rikkauden viettelys ja muut himot tulevat ja tukahuttavat sanan, ja saatetaan hedelmättömäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 20, 'Ja ne ovat, jotka hyvään maahan kylvetyt ovat: jotka kuulevat sanan ja ottavat sen vastaan, ja hedelmän kantavat, muutama kolminkymmenin, ja muutama kuusinkymmenin, ja muutama sadoin kerroin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 21, 'Ja hän sanoi heille: sytytetäänkö kynttilä pantaa vakan alle eli pöydän alle? eikö, että se pantaisiin kynttilänjalkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 22, 'Sillä ei ole mitään peitetty, jota ei ilmoiteta, eikä ole salaista, vaan että se julki tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 23, 'Jos jollakin on korvat kuulla, se kuulkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 24, 'Ja hän sanoi heille: katsokaat, mitä te kuulette. Jolla mitalla te mittaatte, pitää teille mitattaman, ja vielä lisätään teille, jotka kuulette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 25, 'Sillä jolla on, hänelle annetaan; ja jolla ei ole, sekin, mitä hänellä on, otetaan häneltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 26, 'Ja hän sanoi: niin on Jumalan valtakunta kuin jos ihminen heittäis siemenen maahan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 27, 'Ja makais, ja nousis yöllä ja päivällä: ja siemen puhkeais ulos ja kasvais ylös, koska ei hän tiedäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 28, 'Sillä maa kantaa hedelmän itsestänsä, ensin oraan, sitte tähkäpään, ja niin täyden jyvän tähkäpäässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 29, 'Mutta kuin hedelmä tulee edes, lähettää hän kohta sinne sirpin; sillä elonaika on läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 30, 'Ja hän sanoi: mihinkä me Jumalan valtakunnan vertaamme? eli millä vertauksella me sen vertaamme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 31, 'Niinkuin sinapin siemeneen: kuin se maahan kylvetään, on se vähin kaikkia siemeniä, mitä maassa on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 32, 'Ja kuin hän kylvetty on, niin hän nousee, ja tulee suuremmaksi kaikkia kaaleja, ja tekee suuret oksat, niin että taivaan linnut hänen varjonsa alle taitavat pesät tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 33, 'Ja sen muotoisilla monilla vertauksilla puhui hän heille sanan, sen perästä kuin he voivat kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 34, 'Mutta ei hän ilman vertausta mitään heille puhunut, vaan selitti kaikki opetuslapsillensa erinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 35, 'Ja hän sanoi heille sinä päivänä, kuin ehtoo tuli: menkäämme ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 36, 'Ja he laskivat kansan, ja ottivat hänen, kuin hän oli haahdessa; oli myös muita venheitä hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 37, 'Ja suuri tuulispää nousi ja aallot löivät sisälle haahteen, niin että se jo täytettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 38, 'Ja hän oli perällä ja makasi päänalaisen päällä. Ja he herättivät hänen ja sanoivat hänelle: Mestari, etkös sitä tottele, että me hukumme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 39, 'Ja kuin hän herätettiin, nuhteli hän tuulta ja sanoi merelle: vaikene, ole ääneti. Niin tuuli asettui ja tuli juuri tyveneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 40, 'Ja hän sanoi heille: mitä te niin pelkurit olette? Kuinka ei teillä ole uskoa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 41, 'Ja he peljästyivät sangen suuresti ja sanoivat keskenänsä: kuka tämä on? sillä tuuli ja meri ovat hänelle kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Ja he tulivat ylitse meren Gadaralaisten maakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Ja kuin hän läksi haahdesta, kohtasi häntä kohta haudoista ihminen, jossa oli saastainen henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Jolla oli maja haudoissa, ja ei voinut kenkään häntä kahleilla sitoa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Sillä hän oli usein jalkapuissa ja kahleissa sidottuna, ja hän oli särkenyt kahleet ja jalkapuut rikkonut, ja ei kenkään voinut häntä asettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Ja hän oli aina yötä ja päivää vuorissa ja haudoissa, ja parkui, ja hosui itsiänsä kivillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Mutta kuin hän näki taampana Jesuksen, juoksi hän ja lankesi maahan hänen eteensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Ja huutain suurella äänellä sanoi: mitä minun on sinun kanssas, Jesus, korkeimman Jumalan Poika? Minä vannotan sinua Jumalan kautta, ettet minua vaivaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, '(Sillä hän sanoi hänelle: lähde ulos saastainen henki ihmisestä.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Ja hän kysyi häneltä: mikä nimes on? Ja hän vastasi, sanoen: legio on minun nimeni; sillä meitä on monta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Ja hän rukoili häntä suuresti, ettei hän lähettäisi heitä ulos siitä maakunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Niin oli siinä vuorten tykönä suuri sikalauma laitumella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Ja kaikki ne perkeleet rukoilivat häntä, sanoen: laske meitä sikoihin, että me heihin menisimme sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Ja Jesus salli kohta heidän. Ja saastaiset henget läksivät ulos ja menivät sikain sisälle. Ja lauma syöksi itsensä kohdastansa mereen (mutta heitä oli lähes kaksituhatta), ja he upposivat mereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Mutta sikain kaitsiat pakenivat ja saattivat sanoman kaupunkiin ja kyliin. Ja he menivät ulos katsomaan, mikä se oli joka tapahtui,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 15, 'Ja tulivat Jesuksen tykö ja näkivät sen, joka perkeleeltä riivattu oli, istuvan ja vaatetettuna ja toimellisena, jossa legio oli ollut; ja he pelkäsivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 16, 'Ja ne, jotka sen nähneet olivat, juttelivat heille, kuinka perkeleeltä riivatulle tapahtunut oli, ja sioista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 17, 'Ja he rupesivat häntä rukoilemaan menemään pois heidän maaltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 18, 'Ja kuin hän astui haahteen, niin se, joka perkeleeltä riivattu oli, rukoili, että hän sais hänen kanssansa olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 19, 'Mutta ei Jesus häntä sallinut, vaan sanoi hänelle: mene kotias omaistes tykö, ja ilmoita heille, kuinka suuret työt Herra on sinulle tehnyt, ja on sinua armahtanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 20, 'Ja hän meni ja rupesi saarnaamaan niissä kymmenessä kaupungissa, kuinka suuret työt Jesus oli hänelle tehnyt; ja he kaikki ihmettelivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 21, 'Ja kuin Jesus taas meni haahdella ylitse, kokoontui paljo kansaa hänen tykönsä, ja hän oli läsnä merta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 22, 'Ja katso, synagogan päämies, Jairus nimeltä, tuli, ja kuin hän näki hänen, lankesi hän hänen jalkainsa tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 23, 'Ja rukoili häntä suuresti, sanoen: minun vähä tyttäreni on viimeisillänsä; tule ja pane kätes hänen päällensä, että hän paranis ja eläis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 24, 'Niin hän meni hänen kanssansa; ja paljo kansaa seurasi häntä, ja ahdistivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 25, 'Ja vaimo, joka oli sairastanut punaista tautia kaksitoistakymmentä ajastaikaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 26, 'Ja oli paljon kärsinyt monelta parantajalta, ja oli kuluttanut kaiken hyvyytensä, eikä mitään apua tuntenut, vaan tullut paljon pahemmaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 27, 'Kuin hän kuuli Jesuksesta, tuli hän kansan seassa takaa ja rupesi hänen vaatteisiinsa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 28, 'Sillä hän sanoi: jos minä ainoasti saan ruveta hänen vaatteisiinsa, niin minä paranen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 29, 'Ja hänen verilähteensä kohta kuivettui, ja hän tunsi ruumiissansa, että hän oli vitsauksestansa parantunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 30, 'Ja Jesus tunsi kohta itsessänsä voiman, joka hänestä lähtenyt oli, ja käänsi itsensä kansan seassa ja sanoi: kuka rupesi minun vaatteisiini?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 31, 'Ja hänen opetuslapsensa sanoivat hänelle: sinä näet, että kansa sinua ahdistaa ympäri, ja sinä sanoit: kuka minuun rupesi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 32, 'Ja hän katsoi ympärinsä, että hän sen näkis, joka sen teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 33, 'Mutta vaimo pelkäsi ja vapisi, että hän tiesi, mitä hänen kohtaansa tapahtunut oli, tuli ja lankesi hänen eteensä, ja sanoi hänelle kaiken totuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 34, 'Mutta hän sanoi hänelle: tyttäreni, sinun uskosi paransi sinun; mene rauhaan ja ole terve vitsauksestas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 35, 'Kuin hän vielä puhui, tulivat muutamat synagogan päämieheltä, jotka sanoivat: sinun tyttäres on kuollut: mitäs silleen Mestaria vaivaat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 36, 'Mutta Jesus kohta kuultuansa sen sanan sanottavan, sanoi synagogan päämiehelle: älä pelkää, ainoastaan usko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 37, 'Ja ei hän sallinut kenenkään itsiänsä seurata, vaan Pietarin ja Jakobin ja Johanneksen, Jakobin veljen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 38, 'Ja hän tuli synagogan päämiehen huoneeseen, ja näki pauhinan ja ne, jotka itkivät ja porasivat paljon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 39, 'Ja hän meni sisälle, ja sanoi heille: mitä te pauhaatte ja itkette? Lapsi ei ole kuollut, vaan makaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 40, 'Ja he nauroivat häntä. Mutta kuin hän oli kaikki ajanut ulos, otti hän lapsen isän ja äidin kanssansa ja ne, jotka hänen kanssansa olivat, ja meni sisälle, kussa lapsi makasi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 41, 'Ja tarttui lapsen käteen ja sanoi hänelle: talita kumi, se on sanottu: piikainen, (sinulle minä sanon), nouse ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 42, 'Ja kohta piika nousi ja kävi; sillä hän oli kahdentoistakymmenen ajastaikainen. Ja he hämmästyivät suurella hämmästyksellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 43, 'Ja hän haasti heitä kovin, ettei kenkään sitä saisi tietää, ja hän käski antaa hänelle syötävää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Ja hän läksi sieltä ja meni isänsä maalle, ja hänen opetuslapsensa seurasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Ja kuin sabbati tuli, rupesi hän synagogassa opettamaan; ja monta, jotka kuulivat, hämmästyivät, sanoen: kusta tällä nämät ovat? ja mikä viisaus hänelle annettu on, että myös senkaltaiset väkevät työt hänen kättensä kautta tapahtuvat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Eikö tämä ole se seppä, Marian poika, Jakobin ja Joseen ja Juudaan ja Simonin veli? eikö myös hänen sisarensa ole tässä meidän kanssamme? ja he pahenivat hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Mutta Jesus sanoi heille: ei propheta muualla ole katsottu ylön kuin isänsä maalla ja lankoinsa seassa ja kotonansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Ja ei hän voinut siellä yhtään väkevää työtä tehdä, vaan ainoastaan pani kätensä harvain sairasten päälle ja paransi heitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Ja ihmetteli heidän epäuskoansa. Ja hän vaelsi ympäri kyliä, opettain ympäristöllä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Ja kutsui ne kaksitoistakymmentä, ja rupesi niitä kaksin ja kaksin lähettämään, ja antoi heille voiman saastaisia henkiä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Ja kielsi heitä mitään ottamasta tielle, mutta ainoasti sauvan, ei evässäkkiä, ei leipää, ei rahaa kukkaroon;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Mutta olemaan kengässä, ja ettei he pukisi kahta hametta yllensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Ja hän sanoi heille: kussa ikänä te huoneeseen menette sisälle, niin olkaat siinä, niinkauvan kuin te sieltä menette pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Ja jotka ei teitä vastaan ota, eikä kuule teitä, niin menkäät pois sieltä ja pyyhkikäät tomu, joka teidän jalkainne alla on, heille todistukseksi. Totisesti sanon minä teille: Sodomalle ja Gomorralle on tuomiopäivänä huokiampi kuin sille kaupungille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Ja he läksivät ulos ja saarnasivat, että he parannuksen tekisivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Ja ajoivat ulos monta perkelettä, ja voitelivat öljyllä monta sairasta, ja paransivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Ja kuningas Herodes sai sen kuulla (sillä hänen nimensä oli jo julistettu), ja sanoi: Johannes, joka kastoi, on noussut kuolleista, ja sentähden voimat vaikuttavat hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Muut sanoivat: se on Elias: mutta toiset sanoivat: se on propheta, taikka niinkuin joku prophetaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Mutta kuin Herodes se kuuli, sanoi hän: se on Johannes, jonka kaulan minä annoin leikata, hän on kuolleista noussut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Sillä Herodes oli lähettänyt Johannesta ottamaan kiinni, ja pani hänen torniin, Herodiaksen, veljensä Philippuksen emännän tähden, jonka hän oli nainut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Sillä Johannes oli Herodekselle sanonut: ei sinulle ole luvallista pitää veljes emäntää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Ja Herodias väijyi häntä, ja tahtoi häntä tappaa; mutta ei hän saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Sillä Herodes pelkäsi Johannesta, että hän tiesi hänen hurskaaksi ja pyhäksi mieheksi, ja otti vaarin hänestä, ja kuuli häntä monessa asiassa, ja kuulteli häntä mielellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 21, 'Ja kuin sovelias päivä tuli, että Herodes syntymäpäivänänsä teki ehtoollisen ylimmäisillensä ja päämiehille ja esimiehille Galileassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 22, 'Ja Herodiaksen tytär tuli sisälle ja hyppäsi, ja se kelpasi Herodekselle ja ynnä atrioitseville, sanoi kuningas piialle: ano minulta mitäs tahdot, ja minä annan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 23, 'Ja hän vannoi hänelle: mitä ikänä sinä minulta anot, niin minä annan sinulle, puoleen minun valtakuntaani asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 24, 'Mutta se meni ulos ja sanoi äidillensä: mitä minun pitää anoman? vaan se sanoi: Johannes Kastajan päätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 25, 'Ja hän kohta meni sisälle kiiruusti kuninkaan tykö, anoi sanoen: minä tahdon, ettäs minulle annat juuri nyt Johannes Kastajan pään vadissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 26, 'Niin kuningas tuli sangen murheelliseksi; kuitenkin valan tähden ja niiden, jotka ynnä atrioitsivat, ei tahtonut häneltä kieltää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 27, 'Ja kuningas lähetti kohta murhaajan, ja käski hänen päänsä tuoda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 28, 'Niin se meni ja leikkasi hänen kaulansa tornissa, ja toi hänen päänsä vadissa, ja antoi sen piialle; ja piika antoi sen äidillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 29, 'Ja kuin hänen opetuslapsensa sen kuulivat, tulivat he ja ottivat hänen ruumiinsa, ja panivat sen hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 30, 'Ja apostolit kokoontuivat Jesuksen tykö, ja ilmoittivat hänelle kaikki sekä ne, mitkä he tekivät, ja mitä he opettivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 31, 'Ja hän sanoi heille: tulkaat te yksinänne erinäiseen paikkaan ja levätkäät vähä; sillä monta oli, jotka tulivat ja menivät, niin ettei he syödäkään joutaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 32, 'Ja he menivät korpeen haahdella erinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 33, 'Ja kansa näki heidän menevän, ja moni tunsi hänen, ja juoksivat sinne jalkaisin kaikista kaupungeista, ja he ennättivät heitä, ja he kokoontuivat hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 34, 'Ja Jesus läksi ulos ja näki paljon kansaa, ja hän armahti heitä; sillä he olivat niinkuin lampaat, joilla ei ole paimenta, ja rupesi heitä opettamaan paljon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 35, 'Ja kuin päivä paljon kulunut oli, tulivat hänen opetuslapsensa hänen tykönsä, sanoen: tämä on erämaa, ja aika on jo kulunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 36, 'Laske heitä, että he menisivät ympäri kyliin ja majoihin, ostamaan itsellensä leipiä; sillä ei heillä ole syötävää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 37, 'Mutta hän vastaten sanoi heille: antakaa te heille syötävää. Ja he sanoivat hänelle: pitääkö meidän menemän kahdellasadalla penningillä leipiä ostamaan, ja antamaan heidän syödä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 38, 'Mutta hän sanoi heille: kuinka monta leipää teillä on? menkäät ja katsokaat. Ja kuin he katsoivat, sanoivat he: viisi, ja kaksi kalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 39, 'Ja hän käski heidän istuttaa kaikki atrioitsemaan eri joukkoihin viheriäisen ruohon päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 40, 'Ja he istuivat joukoissa sadoin ja viisinkymmenin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 41, 'Ja kuin hän otti ne viisi leipää ja kaksi kalaa, katsoi hän taivaaseen, kiitti ja mursi leivät, ja antoi opetuslapsillensa pantaa niiden eteen: ja ne kaksi kalaa jakoi hän kaikille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 42, 'Ja he söivät kaikki ja ravittiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 43, 'Ja he korjasivat kaksitoistakymmentä täysinäistä koria muruja, ja myös kaloista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 44, 'Ja niitä, kuin söivät, oli lähes viisituhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 45, 'Ja hän ajoi kohta opetuslapsensa astumaan haahteen ja edellä menemään meren ylitse Betsaidaan, siihenasti kuin hän päästäis kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 46, 'Ja kuin hän oli päästänyt heidät, meni hän vuorelle rukoilemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 47, 'Ja kuin ehtoo tuli, oli haaksi keskellä merta, ja hän yksinänsä maalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 48, 'Ja hän näki heidän olevan hädässä soutamisessa; (sillä heillä oli vastainen). Ja liki neljäntenä yön vartiona tuli hän heidän tykönsä, käyden meren päällä, ja tahtoi mennä heidän ohitsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 49, 'Mutta kuin he näkivät hänen käyvän meren päällä, luulivat he olevan kyöpelin ja huusivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 50, '(Sillä kaikki näkivät hänen ja hämmästyivät.) Ja hän puhui kohta heidän kanssansa ja sanoi heille: olkaat hyvässä turvassa, minä olen, älkäät peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 51, 'Ja hän astui heidän tykönsä haahteen, ja tuuli heikkeni. Ja he paljoa enemmän keskenänsä hämmästyivät ja ihmettelivät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 52, 'Sillä ei he ymmärtäneet leivistäkään, vaan heidän sydämensä oli paatunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 53, 'Ja kuin he olivat menneet ylitse, tulivat he Genesaretin maalle ja laskivat satamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 54, 'Ja kuin he menivät ulos haahdesta, niin he kohta tunsivat hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 55, 'Ja juoksivat ympäri kaiken sen ympäristön, ja rupesivat sairaita viemään vuoteissansa, kussa he kuulivat hänen olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 56, 'Ja kuhunka hän meni sisälle kyliin eli kaupunkeihin taikka majoihin, niin he panivat kujille sairaita, ja rukoilivat häntä, että he ainoastaan hänen vaatteensa palteeseen saisivat ruveta, ja niin monta kuin häneen rupesi, ne paranivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Ja hänen tykönsä kokoontuivat Pharisealaiset ja muutamat kirjanoppineista, jotka Jerusalemista tulleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Ja kuin he näkivät muutamat hänen opetuslapsistansa yhteisillä (se on: pesemättömillä) käsillä syövän leipää, laittivat he sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Sillä pharisealaiset ja kaikki Juudalaiset ei syö, ellei he usein pese käsiänsä, pitäin vanhimpain säätyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Ja kuin he turulta tulevat, ei he syö pesemättä. Ja monta muuta on, jotka he ovat ottaneet pitääksensä, jota on: juoma-astiain, kivi-astiain, ja vaski-astiain ja pöytäin pesemiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Sitte kysyivät Pharisealaiset ja kirjanoppineet häneltä: miksi ei sinun opetuslapses vaella vanhinpain säädyn jälkeen, vaan syövät pesemättömillä käsillä leipää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Mutta hän vastaten sanoi heille: Jesaias on hyvästi teistä ulkokullaisista ennustanut, niinkuin kirjoitettu on: tämä kansa kunnioittaa minua huulilla, vaan heidän sydämensä on kaukana minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Mutta turhaan he minua palvelevat, opettain sitä oppia, joka on ihmisten käskyjä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Sillä te hylkäätte Jumalan käskyn, ja pidätte ihmisten säädyn, kivi-astiain ja juoma-astiain pesemiset, ja muita senkaltaisia te paljon teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Ja hän sanoi heille: hyvin te hylkäätte Jumalan käskyn, että te teidän säätynne pitäisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Sillä Moses sanoi: kunnioita isääs ja äitiäs! ja joka kiroilee isää eli äitiä, hänen pitää kuolemalla kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Mutta te sanotte: jos ihminen sanoo isälle taikka äidille: korban, (se on uhrattu) jolla sinua piti minulta autettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Ja ette salli hänen mitään tehdä isällensä taikka äidillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Ja hylkäätte Jumalan sanan teidän säädyllänne, jonka te säätäneet olette, ja senkaltaisia paljon te teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Ja hän kutsui tykönsä kaiken kansan ja sanoi heille: kuulkaat kaikki minua, ja ymmärtäkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Ei ole ulkona ihmisestä mitään, joka häneen menee sisälle, ja taitaa hänen saastuttaa; mutta ne, mitkä hänestä tulevat ulos, ne ovat ne, jotka saastuttavat ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Jos jollakin on korvat kuulla, se kuulkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Ja kuin hän kansan tyköä meni huoneeseen, kysyivät hänen opetuslapsensa häneltä tästä vertauksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Ja hän sanoi heille: oletteko tekin niin ymmärtämättömät? ettekö ymmärrä, että kaikki mikä ulkoa menee ihmiseen, ei se häntä taida saastuttaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Sillä ei se mene hänen sydämeensä, vaan vatsaan, ja menee luonnollisesti ulos, kaikki ruat puhdistain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Ja hän sanoi: mitä ihmisestä tulee ulos, se saastuttaa ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Sillä sisältä ihmisten sydämestä tulevat ulos pahat ajatukset, huoruudet, salavuoteudet, miestapot,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Varkaudet, ahneudet, pahat juonet, petos, irstaisuus, pahansuomuus, Jumalan pilkka, ylpeys, hulluus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Kaikki nämät pahuudet sisältä tulevat ulos ja saastuttavat ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Niin hän nousi ja meni sieltä Tyron ja Sidonin maan ääriin, ja meni sisälle huoneeseen, eikä tahtonut sitä kenellekään antaa tietää: ja ei hän taitanut salaa olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Sillä kuin yksi vaimo kuuli hänestä, jonka vähällä tyttärellä oli saastainen henki, niin se tuli ja lankesi hänen jalkainsa juureen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, '(Mutta vaimo oli Gregiläinen, Syrophenisiassa syntynyt) ja hän rukoili häntä ajamaan pois perkelettä hänen tyttärestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Niin Jesus sanoi hänelle: salli ensin lapset ravittaa; sillä ei se ole kohtuullinen, ottaa lasten leipää ja heittää penikoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Mutta hän vastasi ja sanoi hänelle: tosin Herra: syövät penikatkin pöydän alla lasten muruista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 29, 'Ja hän sanoi hänelle: tämän puheen tähden mene: perkele läksi ulos sinun tyttärestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 30, 'Ja kuin hän meni kotiansa, löysi hän perkeleen lähteneeksi ulos ja tyttärensä makaavan vuoteessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 31, 'Ja taas kuin hän läksi Tyron ja Sidonin maan ääristä, tuli hän Galilean meren tykö, kymmenen kaupungin maan äärten keskitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 32, 'Ja he toivat hänen tykönsä kuuron, joka myös mykkä oli, ja he rukoilivat häntä panemaan kätensä hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 33, 'Ja hän otti hänen erinänsä kansasta ja pisti sormensa hänen korviinsa, sylki ja rupesi hänen kieleensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 34, 'Ja katsahtain taivaaseen huokasi, ja sanoi hänelle; ephphata, se on: aukene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 35, 'Ja kohta aukenivat hänen korvansa, ja hänen kielensä side pääsi vallallensa ja puhui selkiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 36, 'Ja hän haasti heidät kellenkään sanomasta. Mutta jota enemmän hän haasti, sitä enemmin he ilmoittivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 37, 'Ja he suuresti hämmästyivät, sanoen: hyvästi hän kaikki teki: kuurot hän tekee kuulemaan ja mykät puhumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Niinä päivinä, koska sangen paljo kansaa oli, eikä ollut heillä mitään syömistä, kutsui Jesus opetuslapsensa tykönsä ja sanoi heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Minä surkuttelen kansaa; sillä he ovat jo kolme päivää viipyneet minun tykönäni, ja ei ole heillä, mitä he söisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Ja jos minä päästän heidät kotiansa syömättä, niin he vaipuvat tiellä; sillä muutamat heistä olivat kaukaa tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Niin vastasivat häntä hänen opetuslapsensa: kusta joku voi näitä ravita leivillä tässä erämaassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Ja hän kysyi heiltä: kuinka monta leipää teillä on? He sanoivat: seitsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Ja hän käski kansan istua atrioitsemaan maan päälle. Ja hän otti ne seitsemän leipää, kuin hän kiittänyt oli, mursi ja antoi opetuslapsillensa, että he olisivat panneet eteen; ja he panivat kansan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Ja heillä oli myös vähä kalasia; ja hän kiitti, ja käski ne myös pantaa eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Niin he söivät ja ravittiin; ja he korjasivat tähteet, jotka jääneet olivat, seitsemän koria muruja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Ja niitä jotka söivät, oli liki neljätuhatta; ja hän päästi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Ja hän astui kohta opetuslastensa kanssa haahteen, ja tuli Dalmanutan maan ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Ja Pharisealaiset tulivat ja rupesivat kamppailemaan hänen kanssansa, pyytäen häneltä merkkiä taivaasta, kiusaten häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Ja hän huokasi hengessänsä ja sanoi: miksi tämä suku merkkiä pyytää? Totisesti sanon minä teille: ei tälle sukukunnalle anneta merkkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Ja hän jätti heidät, ja astui taas haahteen, ja meni ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 14, 'Ja he olivat unohtaneet ottaa leipiä, eikä ollut heillä enempi kuin yksi leipä haahdessa myötänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 15, 'Ja hän käski heitä, sanoen: katsokaat ja karttakaat teitänne Pharisealaisten hapatuksesta ja Herodeksen hapatuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 16, 'Ja he ajattelivat keskenänsä, sanoen: ei meillä ole leipiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 17, 'Ja kun Jesus sen ymmärsi, sanoi hän heille: mitä te ajattelette, ettei teillä ole leipää? ettekö te vielä huomaitse, ettekä ymmärrä? vieläkö teillä nyt on paatunut sydän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 18, 'Silmät teillä on ja ette näe? ja korvat teillä on, ja ette kuule? ettekö myös muista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 19, 'Kuin minä viisi leipää mursin viidelletuhannelle, kuinka monta täysinäistä koria te tähteitä korjasitte? He sanoivat: kaksitoistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 20, 'Niin myös kuin minä ne seitsemän mursin neljälletuhannelle, kuinka monta täysinäistä koria tähteitä te korjasitte? he sanoivat: seitsemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 21, 'Ja hän sanoi heille: miksi ette siis ymmärrä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 22, 'Ja hän tuli Betsaidaan, ja he toivat sokian ja rukoilivat häntä, että hän rupeais häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 23, 'Ja hän tarttui sokian käteen, ja vei ulos hänen kylästä, ja sylki hänen silmiinsä, ja pani kätensä hänen päällensä, ja kysyi häneltä, josko hän jotakin näkis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 24, 'Niin hän katsoi ylös ja sanoi: minä näen ihmiset niinkuin puut käyskentelevän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 25, 'Sitte hän taas pani kätensä hänen silmäinsä päälle, ja antoi hänen taas katsoa. Ja se tuli parannetuksi, niin että hän näki kaikki kaukaa ja selkiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 26, 'Ja hän lähetti hänen kotiansa, sanoen: älä mene kylään sisälle, älä myös kellenkään tätä kylässä sano.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 27, 'Ja Jesus meni ulos ja hänen opetuslapsensa Kesarean kyliin, joka kutsutaan Philippi; ja hän kysyi tiellä opetuslapsiltansa, sanoen heille: kenenkä sanovat ihmiset minun olevan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 28, 'Niin he vastasivat: Johannes Kastajan, ja muutamat Eliaan, vaan muutamat jonkun prophetaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 29, 'Ja hän sanoi heille: kenenkäs te sanotte minun olevan? Pietari vastasi ja sanoi hänelle: sinä olet Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 30, 'Ja hän haasti heitä kellenkään hänestä sanomasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 31, 'Ja hän rupesi heitä opettamaan, että Ihmisen Pojan pitää paljo kärsimän, ja hyljättämän vanhimmilta ja ylimmäisiltä papeilta ja kirjanoppineilta, ja tapettaman, ja kolmantena päivänä ylösnouseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 32, 'Ja hän puhui sen puheen julki rohkiasti. Ja Pietari otti hänen tykönsä, rupesi häntä nuhtelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 33, 'Mutta hän käänsi itsensä ja katsoi opetuslastensa puoleen, nuhteli Pietaria, sanoen: mene pois minun tyköäni, saatana; sillä et sinä ymmärrä niitä, mitkä Jumalan ovat, vaan niitä, mitkä ihmisten ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 34, 'Ja hän kutsui tykönsä kansan ja opetuslapsensa, ja sanoi heille: kuka ikänä tahtoo tulla minun perässäni, hän kieltäköön itsensä, ja ottakoon ristinsä, ja seuratkoon minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 35, 'Sillä kuka ikänä tahtoo henkensä vapahtaa, hän hukuttaa sen; mutta joka ikänä henkensä hukuttaa minun ja evankeliumin tähden, hän vapahtaa sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 36, 'Sillä mitä se auttaa ihmistä, jos hän voittais kaiken maailman, ja sais sielullensa vahingon?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 37, 'Eli mitä ihminen antaa sielunsa lunastukseksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 38, 'Sillä joka häpee minua ja minun sanojani tässä huorintekiässä ja syntisessä suvussa, sitä myös pitää Ihmisen Pojan häpeemän, koska hän tulee Isänsä kunniassa pyhäin enkelien kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Ja hän sanoi heille: totisesti sanon minä teille: muutamat näistä, jotka tässä seisovat, ei pidä kuolemaa maistavan siihen asti kuin he näkevät Jumalan valtakunnan voimalla tulevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Ja kuuden päivän perästä, otti Jesus tykönsä Pietarin ja Jakobin ja Johanneksen, ja vei heidät erinänsä korkialle vuorelle yksinänsä: ja hän kirkastettiin * heidän edessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Ja hänen vaatteensa tulivat kiiltäväksi ja sangen valkiaksi niinkuin lumi, ettei yksikään vaatteen painaja taida niin valkiaksi painaa maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Ja heille ilmestyi Elias Moseksen kanssa, jotka puhuivat Jesuksen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Ja Pietari vastaten sanoi Jesukselle: Rabbi, hyvä on meidän tässä olla: tehkäämme siis tähän kolme majaa, sinulle yhden, Mosekselle yhden ja Eliaalle yhden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Vaan ei hän tietänyt, mitä hän puhui; sillä he olivat hämmästyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Ja pilvi tuli, joka ympäri varjosi heidät, ja ääni tuli pilvestä, sanoen: tämä on minun rakas Poikani, kuulkaat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Ja kohta kuin he ympäri katsahtivat, ei he enään ketään nähneet, vaan Jesuksen yksin heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Mutta kuin he menivät alas vuorelta, kielsi hän heidät kellenkään niitä sanomasta, mitä he näkivät, vaan sitte kuin Ihmisen Poika on kuolleista noussut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Ja he pitivät sanan mielessänsä, ja tutkivat keskenänsä, mitä se olis, nousta ylös kuolleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Ja he kysyivät häneltä sanoen: mitä kirjanoppineet sanovat, että Eliaan pitää ensin tuleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Mutta hän vastaten sanoi heille: Elias tosin tulee ensin ja ojentaa kaikki: ja niinkuin on Ihmisen Pojasta kirjoitettu, että hänen pitää paljon kärsimän ja katsottaman ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Mutta minä sanon teille, että Elias on myös tullut, ja he tekivät hänelle, mitä he tahtoivat, niinkuin hänestä kirjoitettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Ja kuin hän tuli opetuslasten tykö, näki hän paljon kansaa heidän ympärillänsä, ja kirjanoppineet kamppailevan heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Ja kohta kuin kaikki kansa näki hänen, hämmästyivät he ja juosten tykö tervehtivät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Ja hän kysyi kirjanoppineilta: mitä te kamppailette keskenänne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Niin yksi kansan seasta vastasi ja sanoi: Mestari, minä toin sinun tykös poikani, jolla on mykkä henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Ja kuin hän rupee hänen kimppuunsa, niin hän repelee häntä, ja hän vaahtuu, ja kiristelee hampaitansa, ja kuivettuu. Ja minä sanoin sinun opetuslapsilles, että he ajaisivat hänen ulos, ja ei he voineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Niin hän vastasi ja sanoi: oi sinä uskotoin sukukunta! kuinka kauvan minun pitää oleman teidän kanssanne? kuinka kauvan minä teitä kärsin? Tuokaat häntä minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Ja he toivat sen hänen tykönsä. Ja kuin hän näki hänen, repäisi kohta henki häntä, ja hän lankesi maahan, ja kieritteli itsiänsä ja vaahtui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Ja hän kysyi hänen isältänsä: kuinka paljon aikaa sitte on kuin tämä on hänelle tullut? Hän sanoi: lapsuudesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Ja hän heitti hänen usein tuleen ja vesiin, että hän hukuttais hänen. Mutta jos sinä jotakin voit, niin auta meitä ja armahda meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Niin sanoi Jesus hänelle: jos sinä sen voit uskoa, kaikki ovat uskovaiselle mahdolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Ja kohta pojan isä huusi itkien ja sanoi: Herra, minä uskon, auta minun epäuskoani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Mutta kuin Jesus sen näki, että kansa ynnä juoksi tykö, nuhteli hän sitä saastaista henkeä, sanoen hänelle: sinä mykkä ja kuuro henki! minä käsken sinua, mene ulos hänestä, ja älä tästedes hänen sisällensä mene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Niin se huusi ja repeli kovin häntä, ja läksi ulos. Ja se tuli niinkuin kuollut, niin että moni sanoi: hän on kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Mutta Jesus tarttui hänen käteensä ja nosti hänen, ja hän nousi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Ja kuin hän oli huoneeseen mennyt sisälle, kysyivät hänen opetuslapsensa häneltä erinänsä: miksi emme voineet häntä ajaa ulos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 29, 'Ja hän sanoi heille: tämä suku ei taida millään muulla kuin rukouksella ja paastolla mennä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 30, 'Ja he läksivät ulos sieltä ja vaelsivat Galilean lävitse, ja ei hän tahtonut sitä kenenkään tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 31, 'Sillä hän opetti opetuslapsiansa ja sanoi heille: Ihmisen Poika annetaan ylön ihmisten käsiin, ja he tappavat hänen; ja kuin hän on tapettu, niin hän kolmantena päivänä nousee ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 32, 'Mutta ei he ymmärtäneet sitä mitä hän sanoi, ja pelkäsivät häneltä kysyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 33, 'Ja hän tuli Kapernaumiin, ja kotona ollessa kysyi hän heiltä: mitä te tiellä keskenänne kamppailitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 34, 'Mutta he vaikenivat; sillä he olivat kamppailleet tiellä keskenänsä, kuka heistä suurin olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 35, 'Ja kuin hän istui, kutsui hän ne kaksitoistakymmentä ja sanoi heille: jos joku tahtoo ensimmäinen olla, sen pitää oleman kaikkein viimeinen ja kaikkein palvelian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 36, 'Ja hän otti lapsen ja asetti sen heidän keskellensä. Ja kuin hän otti sen syliinsä, sanoi hän heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 37, 'Kuka ikänä yhden tainkaltaisen lapsen korjaa minun nimeeni, se korjaa minun: ja joka minun korjaa, ei hän minua korjaa, vaan sen, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 38, 'Mutta Johannes vastasi häntä sanoen: Mestari, me näimme yhden sinun nimelläs perkeleitä ajavan ulos, joka ei seuraa meitä, ja me kielsimme häntä, ettei hän seuraa meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 39, 'Niin Jesus sanoi: älkäät häntä kieltäkö; sillä ei ole ketään, joka tekee voimallisen työn minun nimeni kautta, ja taitaa kohta pahasti puhua minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 40, 'Sillä joka ei ole meitä vastaan, se on meidän edestämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 41, 'Sillä kuka ikänä juottaa teitä vesipikarilla minun nimeeni, että te olette Kristuksen, totisesti sanon minä teille: ei hän suinkaan kadota palkkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 42, 'Ja kuka ikänä pahentaa yhden vähimmistä, jotka uskovat minun päälleni, parempi olis hänelle, jos myllyn kivi pantaisiin hänen kaulaansa ja heitettäisiin mereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 43, 'Jos kätes on sinulle pahennukseksi, niin hakkaa se pois: parempi on sinun käsipuolena elämään mennä, kuin jos sinulla olis kaksi kättä ja menisit helvettiin, sammumattomaan tuleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 44, 'Kussa ei heidän matonsa kuole, eikä tuli sammuteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 45, 'Ja jos jalkas on sinulle pahennukseksi, hakkaa se pois: parempi on sinulle, että ontuvana elämään menet, kuin jos sinulla olis kaksi jalkaa ja heitettäisiin helvettiin, sammumattomaan tuleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 46, 'Kussa ei heidän matonsa kuole, eikä tuli sammuteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 47, 'Ja jos silmäs on sinulle pahennukseksi, niin heitä se pois: parempi on sinun silmäpuolena Jumalan valtakuntaan sisälle mennä, kuin jos sinulla olis kaksi silmää ja heitettäisiin helvetin tuleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 48, 'Kussa ei heidän matonsa kuole, eikä tuli sammuteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 49, 'Sillä kaikki pitää tulella suolattaman, ja jokainen uhri pitää suolalla suolattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 50, 'Suola on hyvä; mutta jos suola tulee mauttomaksi, millä te sen höystätte? Pitäkäät itse teissänne suola, ja rauha teidän keskenänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Ja kuin hän sieltä läksi, tuli hän Juudan maan äärille sen maakunnan kautta, joka on sillä puolella Jordania. Ja kansa kokoontui taas hänen tykönsä, ja niinkuin hän oli tottunut, niin hän taas opetti heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Ja Pharisealaiset tulivat ja kysyivät häneltä: saako mies vaimonsa hyljätä? kiusaten häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Mutta hän vastaten sanoi heille: mitä Moses teille käski?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'He sanoivat: Moses salli kirjoittaa erokirjan ja hyljätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Ja Jesus vastaten sanoi heille: teidän sydämenne kovuuden tähden kirjoitti hän teille sen käskyn.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Mutta luomisen alusta on Jumala heidät luonut mieheksi ja vaimoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Sentähden pitää ihmisen eriämän isästänsä ja äidistänsä, ja pitää vaimoonsa yhdistymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Ja niin tulevat kaksi yhdeksi lihaksi, niin ettei he ole silleen kaksi, mutta yksi liha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Mitä siis Jumala on yhteen sovittanut, ei ihmisen pidä sitä eroittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Ja hänen opetuslapsensa kysyivät taas häneltä kotona siitä asiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Ja hän sanoi heille: kuka ikänä hylkää vaimonsa, ja nai toisen, se tekee huorin häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Ja jos vaimo hylkää miehensä ja huolee toiselle, hän tekee huorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Ja he toivat hänen tykönsä lapsia, että hän heihin rupeais; niin opetuslapset nuhtelivat niitä, jotka heitä toivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Mutta kuin Jesus sen näki, närkästyi hän ja sanoi heille: sallikaat lasten tulla minun tyköni, ja älkäät kieltäkö heitä; sillä senkaltaisten on Jumalan valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Totisesti sanon minä teille: jokainen, joka ei Jumalan valtakuntaa ota vastaan niinkuin lapsi, ei hän suinkaan siihen tule sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Ja hän otti heitä syliinsä, ja pani kätensä heidän päällensä, ja siunasi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Ja kuin hän oli lähtenyt ulos tielle, tuli yksi juosten, lankesi polvillensa hänen eteensä ja kysyi häneltä: hyvä Mestari! mitä minun pitää tekemän, että minä ijankaikkisen elämän perisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Niin Jesus sanoi hänelle: miksis sanot minun hyväksi? Ei kenkään ole hyvä, vaan yksin Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Kylläs käskyt tiedät: ei sinun pidä huorin tekemän: ei sinun pidä tappaman: ei sinun pidä varastaman: ei sinun pidä väärää todistusta sanoman: ei sinun pidä pettämän: kunnioita isääs ja äitiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Mutta se vastasi ja sanoi hänelle: Mestari, nämä kaikki olen minä pitänyt hamasta minun nuoruudestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Mutta kuin Jesus katsahti hänen päällensä, rakasti hän häntä, ja sanoi hänelle: yksi sinulta puuttuu: mene, myy kaikki, mitä sinulla on, ja anna vaivaisille; ja sinulla pitää oleman tavara taivaassa: ja tule, seuraa minua, ottain risti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Mutta hän tuli siitä puheesta murheelliseksi, ja meni pois murheissansa; sillä hänellä oli paljo tavaraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Ja kuin Jesus katsahti ympärillensä, sanoi hän opetuslapsillensa: kuinka työläästi ne, joilla varaa on, tulevat Jumalan valtakuntaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Mutta opetuslapset hämmästyivät näistä hänen sanoistansa. Niin Jesus taas vastaten sanoi: rakkaat pojat! kuinkas työläs on niiden tulla Jumalan valtakuntaan, jotka tavaroihinsa uskaltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Huokiampi on kamelin käydä neulan silmän lävitse, kuin rikkaan Jumalan valtakuntaan sisälle tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Mutta he hämmästyivät vielä sitte sangen suuresti, sanoen keskenänsä: ja kuka taitaa autuaaksi tulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Niin Jesus katsahti heidän päällensä, ja sanoi: ihmisten tykönä on se mahdotoin, mutta ei Jumalan tykönä; sillä kaikki ovat Jumalan tykönä mahdolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Niin Pietari rupesi sanomaan hänelle: katso, me olemme kaikki antaneet ylön, ja seuranneet sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Mutta Jesus vastasi ja sanoi: totisesti sanon minä teille: ei ole kenkään, joka jätti huoneen, taikka veljet eli sisaret, taikka isän eli äidin, taikka vaimon eli lapset, taikka pellot, minun ja evankeliumin tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Ellei hän saa jälleen satakertaisesti nyt tällä ajalla huoneita ja veljiä, ja sisaria, ja äitejä, ja lapsia, ja peltoja vastoinkäymisillä *, ja tulevaisessa maailmassa ijankaikkisen elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Mutta monta ensimäistä tulee jälkimäiseksi, ja jälkimäistä ensimäiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Mutta he olivat tiellä menemässä ylös Jerusalemiin; ja Jesus kävi heidän edellänsä, ja he hämmästyivät, ja seurasivat häntä ja pelkäsivät. Ja hän otti taas ne kaksitoistakymmentä tykönsä ja rupesi heille sanomaan, mitä hänelle tapahtuva oli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylön pappein päämiehille ja kirjanoppineille, ja he tuomitsevat hänen kuolemaan ja antavat ylön hänen pakanoille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Ja he pilkkaavat häntä, ja pieksävät hänen, ja sylkevät hänen päällensä, ja tappavat hänen; ja kolmantena päivänä hän nousee ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Niin tuli hänen tykönsä Jakob ja Johannes, Zebedeuksen pojat, sanoen: Mestari! me tahdomme, ettäs meille tekisit, mitä me anomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Niin hän sanoi heille: mitä te tahdotte minua teillenne tekemään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Vaan he sanoivat hänelle: anna toisen meistä istua oikialla ja toisen vasemmalla puolellas sinun kunniassas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Mutta Jesus sanoi heille: ette tiedä, mitä te anotte. Voitteko juoda sen kalkin, jonka minä juon, ja sillä kasteella kastettaa, jolla minä kastetaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Vaan he sanoivat hänelle: voimme. Niin sanoi Jesus heille: sen kalkin tosin te juotte, jonka minä juon, ja sillä kasteella te kastetaan, jolla minä kastetaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 40, 'Mutta istua minun oikialla ja vasemmalla puolellani, ei ole minun antamisellani, mutta niille, joille se valmistettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 41, 'Ja kuin ne kymmenen sen kuulivat, rupesivat he närkästymään Jakobin ja Johanneksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 42, 'Mutta kuin Jesus kutsui heidät tykönsä, sanoi hän heille: te tiedätte, että ne, jotka ovat asetetut kansain päämiehiksi, hallitsevat heitä, ja heidän ylimmäisillänsä on valta heidän ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 43, 'Mutta ei niin pidä oleman teidän keskenänne; vaan joka teidän seassanne tahtoo suurin olla, se olkaan teidän palvelianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 44, 'Ja joka teistä tahtoo tulla ensimäiseksi, hän olkaan kaikkein orja;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 45, 'Sillä ei myös Ihmisen Poika ole tullut, että häntä palveltaisiin, mutta palvelemaan ja antamaan henkensä lunastuksen hinnaksi monen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 46, 'Ja he tulivat Jerikoon. Ja kuin hän läksi Jerikosta ja hänen opetuslapsensa ja paljo kansaa, niin istui tien ohessa sokia, Bartimeus Timein poika, kerjäten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 47, 'Ja kuin hän kuuli, että se oli Jesus Natsaretista, rupesi hän huutamaan ja sanomaan: Jesus, Davidin poika, armahda minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 48, 'Ja moni nuhteli häntä, että hän olis ollut ääneti. Mutta hän huusi paljoa enemmin: Davidin Poika, armahda minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 49, 'Ja Jesus seisahti ja käski kutsua häntä. Ja he kutsuivat sokian ja sanoivat hänelle: ole hyvällä mielellä, nouse! hän kutsuu sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 50, 'Niin hän heitti pois vaatteensa yltänsä, nousi ja tuli Jesuksen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 51, 'Ja Jesus vastaten sanoi hänelle: mitäs tahdot, että minä sinulle tekisin? Niin sokia sanoi hänelle: Rabboni, että minä saisin näköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 52, 'Mutta Jesus sanoi hänelle: mene, sinun uskos vapahti sinun. Ja hän sai kohta näkönsä jälleen, ja seurasi Jesusta tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Ja kuin he lähestyivät Jerusalemia, Betphageen ja Betaniaan, Öljymäen tykö, lähetti hän kaksi opetuslapsistansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Ja sanoi heille: menkäät kylään, joka on teidän edessänne, ja kohta kuin te siihen tulette sisälle, löydätte te varsan sidottuna, jonka päällä ei yksikään ihminen istunut ole; päästäkäät se ja tuokaat tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Ja jos joku teille sanoo: miksi te sen teette? niin sanokaat: Herra sitä tarvitsee; ja kohta hän laskee hänen tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Niin he menivät, ja löysivät varsan sidottuna ulkona oven tykönä tien haarassa, ja he päästivät sen vallallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Ja muutamat niistä, jotka siellä seisoivat, sanoivat heille: mitä te teette, että te varsan päästätte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Mutta he sanoivat heille, niinkuin Jesus oli käskenyt; niin he päästivät heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Ja he toivat varsan Jesuksen tykö ja heittivät vaatteensa sen päälle, ja hän istui sen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Mutta moni hajoitti vaatteensa tielle, ja ne muut karsivat oksia puista ja hajoittivat tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Ja jotka edellä kävivät ja myös seurasivat, huusivat, sanoen: hosianna, hyvästi siunattu olkoon se, joka tulee Herran nimeen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Hyvästi siunattu olkoon Davidin meidän isän valtakunta, joka tulee Herran nimeen: hosianna korkeudessa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Ja Jesus meni Jerusalemiin ja templiin, ja kuin hän kaikki ympäri katseli, koska jo ehtooaika oli, läksi hän ulos Betaniaan kahdentoistakymmenen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Ja toisena päivänä, kuin he Betaniasta läksivät, isosi hän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Ja näki taampana fikunapuun, jolla olivat lehdet, niin hän meni lähes, jos hän jotakin hänestä löytänyt olis. Ja kuin hän tuli tykö, ei hän muuta löytänyt kuin lehtiä; sillä ei ollut vielä fikunain aika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Ja Jesus vastaten sanoi hänelle: älköön tästedeskään kenkään sinusta syökö hedelmää ijankaikkisesti. Ja hänen opetuslapsensa kuulivat sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Ja he tulivat Jerusalemiin. Ja Jesus meni templiin, rupesi ajamaan ulos kaupitsioita ja ostajia templissä, ja vaihettajain pöydät ja kyhkyläisten myyjäin istuimet hän kukisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Ei hän myös sallinut jonkun kantaa astiaa templin lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Ja hän opetti, sanoen heille: eikö kirjoitettu ole: minun huoneeni pitää kutsuttaman rukoushuoneeksi kaikille kansoille? mutta te olette sen tehneet ryövärien luolaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Ja kirjanoppineet ja pappein päämiehet kuulivat sen, ja etsivät, kuinka he olisivat hänen hukuttaneet; sillä he pelkäsivät häntä, että kaikki kansa hämmästyi hänen oppiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Ja kuin ehtoo tuli, meni Jesus ulos kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Ja kuin he aamulla kävivät ohitse, näkivät he fikunapuun kuivettuneen juurinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Ja Pietari muisti, ja sanoi hänelle: Rabbi, katso, fikunapuu, jotas kirosit, on kuivettunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Niin vastasi Jesus ja sanoi heille: pitäkäät usko Jumalan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Sillä totisesti sanon minä teille: jokainen, joka tälle vuorelle sanois: siirrä itses ja kukistu mereen! eikä epäilisi sydämessänsä, vaan uskois ne tapahtuvan mitä hän sanoo; niin hänelle tapahtuu, mitä hän sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Sentähden sanon minä teille: kaikki, mitä te rukoillen anotte, se uskokaat saavanne; niin se tapahtuu teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Ja kuin te seisotte ja rukoilette, niin anteeksi antakaat, jos teillä on jotakin jotakuta vastaan, että myös teidän Isänne, joka on taivaissa, antais teille anteeksi teidän rikoksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Mutta jos ette anteeksi anna, ei myös teidän Isänne, joka on taivaissa, anna anteeksi teidän rikoksianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Ja he tulivat taas Jerusalemiin; ja kuin hän käveli templissä, tulivat hänen tykönsä pappein päämiehet, kirjanoppineet ja vanhimmat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Ja sanoivat hänelle: millä voimalla sinä näitä teet? ja kuka antoi sinulle sen voiman, ettäs näitä teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Mutta Jesus vastaten sanoi heille: minä myös kysyn teiltä yhden sanan: vastatkaat siis minua, niin minäkin sanon teille, millä voimalla minä näitä teen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Johanneksen kaste, oliko se taivaasta, eli ihmisiltä? vastatkaat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Niin he ajattelivat keskenänsä, sanoen: jos me sanomme: taivaasta, niin hän sanoo: miksi ette siis häntä uskoneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Mutta jos me sanomme: ihmisiltä, niin me pelkäämme kansaa: sillä kaikki pitivät Johanneksen totisena prophetana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Ja he vastasivat, sanoen Jesukselle: emme tiedä. Ja Jesus vastasi ja sanoi heille: en minäkään sano teille, millä voimalla minä näitä teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Ja hän rupesi heille puhumaan vertauksilla: ihminen istutti viinamäen, ja pani aidan sen ympärille, ja kaivoi kuopan, ja rakensi tornin, ja pani sen vuorolle peltomiehille, ja matkusti muille maille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Ja lähetti ajallansa palveliansa peltomiesten tykö, ottamaan peltomiehiltä viinamäen hedelmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Mutta he ottivat hänen kiinni, hosuivat hänen ja lähettivät hänen pois tyhjänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ja taas lähetti hän heidän tykönsä toisen palvelian, ja sen he kivittivät ja pään särkivät, ja lähettivät hänen pois pilkattuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Ja hän lähetti taas toisen; sen he tappoivat: ja monta muuta, muutamat he hosuivat, ja muutamat tappoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Niin hänellä oli vielä rakas ainoa poikansa; hän lähetti myös sen viimeiseksi heidän tykönsä, sanoen: he karttavat minun poikaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Mutta ne peltomiehet sanoiat keskenänsä: tämä on perillinen: tulkaat, tappakaamme häntä, niin perintö jää meille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Ja he ottivat hänen ja tappoivat, ja heittivät ulos viinamäestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Mitäs viinamäen Herra on tekevä? Hän tulee ja hukkaa ne peltomiehet, ja antaa viinamäen muille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Ettekö te ole lukeneet tätä kirjoitusta: jonka kiven rakentajat hylkäsivät, se on tullut nurkkakiveksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Herralta on tämä tullut, ja on ihmeellinen meidän silmissämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Ja he etsivät häntä kiinni ottaaksensa, ja pelkäsivät kansaa; sillä he ymmärsivät, että hän heille tämän vertauksen sanonut oli. Ja he jättivät hänen ja menivät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Ja he lähettivät hänen tykönsä muutamat Pharisealaisista ja Herodilaisista, solmeamaan häntä sanoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Ja he tulivat ja sanoivat hänelle: Mestari, me tiedämme, ettäs olet totinen ja et tottele ketään; sillä et sinä katso ihmisten muotoa, mutta opetat Jumalan tien totuudessa. Sopiiko keisarille antaa veron, taikka ei? Pitääkö meidän antaman, taikka ei antaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Niin hän tiesi heidän viekkautensa, ja sanoi heille: mitä te kiusaatte minua? Tuokaat minulle raha nähdäkseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Niin he toivat. Ja hän sanoi heille: kenenkä on tämä kuva ja päällekirjoitus? He sanoivat hänelle: keisarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Niin Jesus vastasi ja sanoi heille: antakaat keisarille, kuin keisarin ovat, ja Jumalalle, kuin Jumalan ovat. Ja he ihmettelivät häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Niin hänen tykönsä tulivat Saddukealaiset, jotka sanovat, ettei nousemusta ole, ja kysyivät häneltä sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Mestari! Moses kirjoitti meille: jos jonkun veli kuolis, ja jättäis vaimon, ja ei lapsia, niin hänen veljensä pitää ottaman hänen vaimonsa ja herättämän veljellensä siemenen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Niin oli seitsemän veljeä. Ja ensimäinen otti vaimon, ja ei jättänyt kuoltuansa siementä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Ja toinen otti hänen, ja kuoli, ja ei hänkään jättänyt siementä. Niin myös kolmas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Ja hänen ottivat ne seitsemän, ja ei jättäneet siementä. Kaikkein viimein kuoli vaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Sentähden ylösnousemisessa, kuin he nousevat ylös, kenenkä heistä vaimo pitää oleman? Sillä hän oli niille seitsemälle emäntänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Ja Jesus vastaten sanoi heille: ettekö te sentähden eksy, ettette tiedä kirjoituksia, eikä Jumalan voimaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Sillä kuin he kuolleista nousevat ylös, ei he nai eikä huole, mutta ovat niinkuin enkelit, jotka ovat taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Mutta kuolleista, että he nousevat, ettekö te ole lukeneet Moseksen Raamatussa, kuinka Jumala pensaassa hänelle puhui, sanoen: minä olen Abrahamin Jumala, ja Isaakin Jumala, ja Jakobin Jumala?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Ei Jumala ole kuolleiden, vaan elävien Jumala: te sentähden suuresti eksytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Ja kuin yksi kirjanoppineista tuli, joka kuuli heidän kamppailevan keskenänsä, ja näki, että hän hyvästi vastasi heitä, kysyi hän häneltä: kuka on kaikkein suurin käsky?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Mutta Jesus vastasi häntä: tämä on kaikkein suurin käsky: kuule, Israel, Herra meidän Jumalamme on yksi Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 30, 'Ja sinun pitää rakastaman Herraa sinun Jumalaas kaikesta sydämestäs, ja kaikesta sinun sielustas, ja kaikesta sinun mielestäs, ja kaikesta sinun voimastas. Tämä on suurin käsky.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 31, 'Ja toinen senkaltainen on tämä: sinun pitää rakastaman sinun lähimmäistäs niinkuin itse sinuas. Ei ole näitä suurempaa käskyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 32, 'Ja kirjanoppinut sanoi hänelle: oikein, Mestari, sinä sanoit totuuden; sillä yksi on Jumala, ja ei ole toista paitsi häntä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 33, 'Ja rakastaa häntä kaikesta sydämestä, ja kaikesta ymmärryksestä, ja kaikesta sielusta ja kaikesta väestä, ja rakastaa lähimmäistä niinkuin itsiänsä, se on enempi kuin kaikki polttouhrit ja muut uhrit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 34, 'Ja koska Jesus näki, että hän toimellisesti vastasi, sanoi hän hänelle: et sinä ole kaukana Jumalan valtakunnasta. Ja ei tohtinut kenkään sitte häneltä enempää kysyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 35, 'Ja Jesus vastasi ja sanoi, opettain templissä: kuinka sanovat kirjanoppineet, että Kristus on Davidin poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 36, 'Sillä David sanoi itse Pyhän Hengen kautta: Herra sanoi minun Herralleni: istu minun oikialle kädelleni siihenasti kuin minä panen sinun vihollises sinun jalkas astinlaudaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 37, 'Itse siis David sanoo hänen Herraksi; kuinka hän siis on hänen poikansa? Ja paljo kansaa kuuli häntä mielellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 38, 'Ja hän opetti heitä ja sanoi heille: kavahtakaat kirjanoppineita, jotka mielellänsä pitkissä vaatteissa käyvät, ja antavat itseänsä turulla tervehtiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 39, 'Ja rakastavat ylimmäisiä istuimia kokouksissa ja ensimäisiä sijoja ehtoollisissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 40, 'Jotka syövät leskein huoneet, ja muodoksi pitävät pitkät rukoukset. Nämät saavat sitä raskaamman kadotuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 41, 'Ja kuin Jesus istui uhri-arkun kohdalla ja katseli, kuinka kansa pani rahaa uhri-arkkuun, ja monta rikasta pani paljon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 42, 'Niin tuli köyhä leski, ja pani kaksi ropoa, se on kuusinainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 43, 'Niin hän kutsui opetuslapsensa tykönsä, ja sanoi heille: Totisesti sanon minä teille: tämä köyhä leski pani enemmän uhri-arkkuun kuin kaikki ne, jotka siihen panivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 44, 'Sillä he ovat kaikki panneet siitä, mitä heille liiaksi oli; mutta tämä köyhyydestänsä pani kaiken, mitä hänellä oli, kaiken tavaransa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Ja kuin hän meni ulos templistä, sanoi yksi hänen opetuslapsistansa: Mestari! katso, minkäkaltaiset kivet ja minkäkaltaiset rakennukset ovat nämät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Ja Jesus vastaten sanoi hänelle: näetkös nämä suuret rakennukset? Ei näistä jätetä kiveä kiven päälle, jota ei maahan jaoteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Ja kuin hän istui Öljymäellä, templin kohdalla, kysyivät häneltä erinänsä Pietari ja Jakob, ja Johannes ja Andreas:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Sano meille, koska nämä tapahtuvat? Ja mikä merkki on, koska nämät kaikki päätetään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Niin Jesus, vastaten heitä, rupesi sanomaan: katsokaat, ettei joku teitä petä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Sillä monta tulevat minun nimeeni, sanoen: minä olen, ja pettävät monta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Mutta kuin te kuulette sotia ja sotain sanomia, niin älkäät hämmästykö; sillä ne pitää tapahtuman; vaan ei vielä loppu ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Sillä kansa pitää nouseman kansaa vastaan ja valtakunta valtakuntaa vastaan, ja maanjäristykset pitää oleman jokaisessa paikassa, ja tulee nälkä ja metelit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Nämät ovat murhetten alut. Mutta kavahtakaat itse teitänne; sillä he antavat ylön teidät raastupiin ja synagogiin. Ja te pieksetään ja johdatetaan päämiesten ja kuningasten eteen minun tähteni, heille todistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Ja ennen pitää saarnattaman evankeliumi kaikessa kansassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Kuin he niin teitä vievät ja antavat ylön, niin älkäät edellä murehtiko, mitä teidän puhuman pitää, älkäät myös ennen ajatelko: vaan mitä teille sillä hetkellä annetaan, se puhukaat; sillä ette te ole, jotka puhutte, vaan Pyhä Henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Niin on veli antava ylön veljensä kuolemaan, ja isä pojan; ja lapset nousevat vanhempia vastaan, ja antavat tappaa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Ja tulette vihattavaksi kaikilta minun nimeni tähden; vaan joka vahvana pysyy loppuun asti, se tulee autuaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Mutta kuin te saatte nähdä hävityksen kauhistuksen, josta Daniel prophetan kautta sanottu on, seisovan kussa ei pitäisi: (joka sen lukee, hän ymmärtäköön;) silloin, jotka Juudeassa ovat, ne paetkaan vuorille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Ja joka katon päällä on, älköön astuko alas huoneeseen, ja älköön menkö sisälle jotakin ottamaan huoneestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Ja joka pellolla on, älköön palatko takaisin ottamaan vaatettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Voi raskaita vaimoja ja imettäväisiä niinä päivinä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Mutta rukoilkaat, ettei pakonne tapahtuisi talvella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Sillä niinä aikoina pitää oleman senkaltainen vaiva, jonka kaltaista ei ole ollut luomisen alusta, kuin Jumala luonut on, niin tähän asti, eikä tuleman pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Ja ellei Herra olisi lyhentänyt niitä päiviä, niin ei yksikään liha tulisi autuaaksi; mutta valittujen tähden, jotka hän on valinnut, lyhensi hän ne päivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Ja silloin, jos joku sanoo teille: katso, tässä on Kristus, taikka: katso, siellä; niin älkäät uskoko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Sillä väärät Kristukset ja väärät prophetat nousevat, ja merkkejä ja ihmeitä tekevät, pettääksensä, jos mahdollinen olis, valituitakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Mutta te kavahtakaat: katso, minä olen teille kaikki ennen sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Mutta niinä päivinä, sen vaivan jälkeen, pitää auringon pimenemän ja kuu ei anna valoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Ja taivaan tähdet pitää putooman, ja taivasten voimat pitää liikutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 26, 'Ja silloin heidän pitää näkemän Ihmisen Pojan tulevan pilvissä suurella voimalla ja kunnialla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 27, 'Ja silloin hän lähettää enkelinsä, ja kokoo valittunsa neljästä tuulesta, hamasta maan äärestä niin taivaan ääreen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 28, 'Mutta fikunapuusta oppikaat vertaus: kuin sen oksa on tuores ja lehdet puhkeavat, niin te tiedätte, että suvi on läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 29, 'Niin myös te, kuin te nämät näette tapahtuvan, niin tietäkäät, että se on läsnä oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 30, 'Totisesti sanon minä teille: ei suinkaan tämän sukukunnan pidä hukkuman ennen kuin kaikki nämät tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 31, 'Taivas ja maa pitää hukkuman; mutta minun sanani ei pidä suinkaan hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 32, 'Mutta siitä päivästä ja hetkestä ei tiedä kenkään, ei enkelitkään, jotka ovat taivaassa, ei Poikakaan, vaan Isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 33, 'Kavahtakaat, valvokaat ja rukoilkaat, sillä ette tiedä, koska se aika tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 34, 'Niinkuin ihminen, joka muille maille vaelsi, jätti huoneensa ja antoi palveliainsa haltuun, ja kullekin hänen askareensa, ja käski ovenvartiain valvoa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 35, 'Niin valvokaat siis: (sillä ette tiedä, koska huoneen Herra tuleva on, ehtoona, taikka puoliyönä, eli kukon laulaissa, eli aamulla:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 36, 'Ettei hän äkisti tullessansa löytäisi teitä makaamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 37, 'Mutta mitä minä teille sanoin, sen minä kaikille sanon: valvokaat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 1, 'Niin oli kahden päivän perästä pääsiäinen ja makianleivän päivät. Ja ylimmäiset papit ja kirjanoppineet etsivät, kuinka he kavaluudella hänen kiinniottaisivat ja tappaisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 2, 'Mutta he sanoivat: ei juhlapäivänä, ettei kapina nousisi kansassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 3, 'Ja kuin hän oli Betaniassa spitalisen Simonin huoneessa, ja atrioitsi, niin tuli yksi vaimo, jolla oli lasi turmelematointa ja kallista nardusvoidetta, ja hän särki lasin ja vuodatti hänen päänsä päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 4, 'Niin muutamat närkästyivät itsellensä ja sanoivat: mihinkä on tapahtunut tämä voiteen haaskaus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 5, 'Sillä tämä olis taidettu myytää enempää kuin kolmeensataan penninkiin, ja annettaa vaivaisille. Ja he napisivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 6, 'Niin Jesus sanoi: sallikaat hänen olla rauhassa! miksi te häntä vaivaatte? Hän teki hyvän työn minun kohtaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 7, 'Sillä teillä ovat aina vaivaiset, ja koska ikänä te tahdotte, niin te saatte heille hyvin tehdä. Mutta en minä teillä aina ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 8, 'Tämä teki, mitä hän voi, ja ennätti voitelemaan minun ruumistani hautaamiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 9, 'Totisesti sanon minä teille: kussa ikänä tämä evankeliumi saarnataan kaikessa maailmassa, niin myös tämä, minkä hän teki, pitää mainittaman hänen muistoksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 10, 'Ja Juudas Iskariot, yksi kahdestatoistakymmenestä, meni ylimmäisten pappein tykö, että hän pettäis hänen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 11, 'Kuin he sen kuulivat, ihastuivat he, ja lupasivat hänelle rahaa antaa. Ja hän etsi, kuinka hän soveliaalla ajalla hänen pettäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 12, 'Ja ensimäisenä makian leivän päivänä, kuin pääsiäislammas teurastettiin, sanoivat hänelle hänen opetuslapsensa: kussas tahdot, että me menemme ja valmistamme syödäkses pääsiäislampaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 13, 'Ja hän lähetti kaksi opetuslapsistansa, ja sanoi heille: menkäät kaupunkiin, ja yksi ihminen kohtaa teitä, kantain vesiastiaa; noudattakaat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 14, 'Ja kuhunka hän menee sisälle, sanokaat perheen isännälle: Mestari sanoo: kussa on vierasten huone, jossa minä opetuslasteni kanssa söisin pääsiäislampaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 15, 'Ja hän osoittaa teille suuren salin, rakennetun ja valmistetun, valmistakaat siellä meille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 16, 'Ja hänen opetuslapsensa menivät ja tulivat kaupunkiin, ja löysivät niinkuin hän oli heille sanonut, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 17, 'Ja kuin ehtoo tuli, tuli hän kahdentoistakymmenen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 18, 'Ja kuin he istuivat pöydän tykönä ja söivät, sanoi Jesus: totisesti sanon minä teille: yksi teistä, joka syö minun kanssani, on minun pettävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 19, 'Mutta he rupesivat murehtimaan ja yksi toisen jälkeen sanomaan: ollenko minä se? ja toinen ollenko minä se?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 20, 'Hän vastasi ja sanoi heille: yksi kahdestatoistakymmenestä, joka minun kanssani vatiin rupee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 21, 'Ihmisen Poika tosin menee, niinkuin hänestä on kirjoitettu; mutta voi sitä ihmistä, jonka kautta Ihmisen Poika petetään! se olis hänelle parempi, jos ei se ihminen olis syntynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 22, 'Ja heidän syödessänsä otti Jesus leivän, kiitti, mursi ja antoi heille, ja sanoi: ottakaat, syökäät: tämä on minun ruumiini.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 23, 'Ja hän otti kalkin, kiitti ja antoi heille. Ja he joivat siitä kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 24, 'Ja hän sanoi heille: tämä on minun vereni, sen Uuden Testamentin, joka monen edestä vuodatetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 25, 'Totisesti sanon minä teille: en minä suinkaan silleen juo viinapuun hedelmästä, siihen päivään asti kuin minä sen juon uuden, Jumalan valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 26, 'Ja kuin he kiitosvirren olivat sanoneet, menivät he ulos Öljymäelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 27, 'Ja Jesus sanoi heille: kaikki te tänä yönä pahenette minussa, niinkuin kirjoitettu on: minä lyön paimenta, ja lampaat hajoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 28, 'Mutta sitte kuin minä nousen ylös, niin minä käyn teidän edellänne Galileaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 29, 'Niin Pietari sanoi hänelle: ja jos vielä kaikki muut pahenisivat, en kuitenkaan minä pahene.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 30, 'Ja Jesus sanoi hänelle: totisesti sanon minä sinulle: tänäpänä, tänä yönä, ennenkuin kukko kahdesti laulaa, sinä kolmasti minun kiellät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 31, 'Mutta hän sanoi vielä enemmin: jos minun pitäis kuoleman sinun kanssas, en minä ikänä kiellä sinua. Niin sanoivat myös kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 32, 'Ja he tulivat kylään, jonka nimi oli Getsemane. Ja hän sanoi opetuslapsillensa: istukaat tässä niinkauvan kuin minä rukoilen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 33, 'Ja hän otti Pietarin ja Jakobin ja Johanneksen kanssansa, ja rupesi vapisemaan ja kauhistumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 34, 'Ja sanoi heille: minun sieluni on suuresti murheissansa kuolemaan asti. Olkaat tässä ja valvokaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 35, 'Ja hän kävi vähää edemmä, lankesi maahan ja rukoili, jos mahdollinen olis, että aika hänen ohitsensa kävis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 36, 'Ja sanoi: Abba minun Isäni! kaikki ovat sinulle mahdolliset: ota pois minulta tämä kalkki, ei kuitenkaan niinkuin minä tahdon, mutta niinkuin sinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 37, 'Ja hän tuli ja löysi heidät makaamasta ja sanoi Pietarille: Simon, makaatkos? Etkös voinut yhtä hetkeä valvoa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 38, 'Valvokaat, ja rukoilkaat, ettette tulisi kiusaukseen. Henki tosin on altis, mutta liha on heikko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 39, 'Niin hän taas meni pois ja rukoili, sanoen entisen sanan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 40, 'Ja palatessansa löysi taas heidät makaamasta, (sillä heidän silmänsä olivat raskaat,) eikä tietäneet, mitä heidän piti häntä vastaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 41, 'Ja hän tuli kolmannen kerran ja sanoi heille: maatkaat vielä ja levätkäät! jo nyt kyllä on, hetki on tullut: katso, Ihmisen Poika annetaan ylön syntisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 42, 'Nouskaat, käykäämme: katso, joka minun pettää, se lähestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 43, 'Ja kohta vielä hänen puhuissansa tuli Juudas, joka oli yksi kahdestatoistakymmenestä, ja hänen kanssansa paljo väkeä miekoilla ja seipäillä, ylimmäisiltä papeilta ja kirjanoppineilta ja vanhimmilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 44, 'Mutta se, joka hänen petti, oli antanut heille yhteisen merkin, sanoen: kenenkä minä suuta annan, se on: kiinni ottakaat häntä, ja viekäät pois visusti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 45, 'Ja kuin hän tuli, astui hän kohta hänen tykönsä ja sanoi: Rabbi! ja antoi hänen suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 46, 'Mutta ne panivat kätensä hänen päällensä, ja ottivat hänen kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 47, 'Niin yksi niistä, jotka siinä läsnä seisoivat, veti ulos miekkansa ja löi ylimmäisen papin palveliaa, ja hakkasi pois hänen korvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 48, 'Ja Jesus vastaten sanoi heille: niinkuin ryövärin tykö te tulitte ulos miekoilla ja seipäillä minua kiinni ottamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 49, 'Minä olen joka päivä ollut teidän tykönänne ja opettanut templissä, ja ette minua ottaneet kiinni. Mutta nämät tapahtuvat, että Raamattu täytettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 50, 'Ja kaikki antoivat ylön hänen ja pakenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 51, 'Ja yksi nuorukainen seurasi häntä, jolla oli liinainen vaate paljaan ihon päällä. Ja nuoret miehet ottivat hänen kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 52, 'Mutta hän jätti liinaisen vaatteen ja pakeni alasti heiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 53, 'Ja he veivät pois Jesuksen ylimmäisen papin tykö, jonka tykö kaikki ylimmäiset papit ja vanhimmat ja kirjanoppineet olivat kokoon tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 54, 'Mutta Pietari noudatti häntä taampana, hamaan ylimmäisen papin salin porstuaan, ja istui ynnä palveliain kanssa ja lämmitteli valkian tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 55, 'Mutta ylimmäiset papit ja kaikki raati etsivät todistusta Jesusta vastaan, että he hänen kuolemaan saattaisivat, ja ei löytäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 56, 'Sillä moni todisti väärin häntä vastaan, mutta ei heidän todistuksensa olleet soveliaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 57, 'Ja muutamat nousivat ja todistivat väärin häntä vastaan, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 58, 'Me olemme kuulleet hänen sanovan: minä tahdon tämän templin, joka käsillä tehty on, maahan jaottaa ja kolmena päivänä toisen rakentaa ylös, joka ei ole käsillä tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 59, 'Ja ei niinkään ollut heidän todistuksensa sovelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 60, 'Ja ylimmäinen pappi astui edes, ja kysyi Jesukselta, sanoen: etkös mitään vastaa? mitä nämät sinua vastaan todistavat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 61, 'Mutta hän oli ääneti, eikä mitään vastannut. Taas ylimmäinen pappi kysyi häneltä ja sanoi hänelle: oletkos sinä Kristus, sen siunatun Poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 62, 'Niin Jesus sanoi: minä olen. Ja teidän pitää näkemän Ihmisen Pojan istuvan voiman oikialla puolella, ja tulevan taivaan pilvissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 63, 'Niin ylimmäinen pappi repäisi vaatteensa ja sanoi: mitä me silleen todistuksia tarvitsemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 64, 'Te olette kuulleet Jumalan pilkan. Mitä te luulette? Niin he kaikki tuomitsivat hänen olevan vikapään kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 65, 'Ja muutamat rupesivat sylkemään hänen päällensä, ja peittämään hänen kasvojansa, ja lyömään häntä poskelle, ja sanomaan hänelle: arvaa! Ja palveliat pieksivät häntä sauvoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 66, 'Ja Pietari oli alhaalla salissa, niin tuli yksi ylimmäisen papin piioista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 67, 'Ja koska hän näki Pietarin lämmittelevän, katsahti hän hänen päällensä ja sanoi: ja sinäkin olit Jesuksen Natsarealaisen kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 68, 'Mutta hän kielsi sanoen: en tunne minä häntä, enkä tiedä, mitäs sanot. Ja hän meni ulos porstuaan; ja kukko lauloi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 69, 'Ja piika näki taas hänen ja rupesi sanomaan niille, jotka siinä seisoivat: tämä on yksi heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 70, 'Mutta hän kielsi jälleen. Ja taas vähän hetken perästä sanoivat Pietarille ne, jotka läsnä seisoivat: totisesti olet sinä yksi heistä; sillä sinä olet Galilealainen, ja sinun puhees on senkaltainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 71, 'Niin hän rupesi itsiänsä sadattelemaan ja vannomaan: en tunne minä sitä ihmistä, jota te sanotte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 72, 'Ja kukko lauloi toisen kerran. Niin Pietari muisti sen sanan, minkä Jesus hänelle sanonut oli: ennenkuin kukko kahdesti laulaa, sinä kolmasti minun kiellät. Ja hän kiiruusti läksi ulos ja itki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 1, 'Ja kohta aamulla varhain pitivät ylimmäiset papit neuvoa vanhimpain ja kirjanoppineitten kanssa ja kaikki raati, ja veivät pois Jesuksen sidottuna ja antoivat ylön Pilatukselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 2, 'Ja Pilatus kysyi häneltä: oletkos sinä Juudalaisten kuningas? Hän vastasi ja sanoi hänelle: sinäpä sen sanot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 3, 'Ja ylimmäiset papit kantoivat hänen päällensä paljon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 4, 'Niin Pilatus kysyi taas häneltä ja sanoi: etkös mitään vastaa? Katso, kuinka paljon he sinua vastaan todistavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 5, 'Mutta ei Jesus sitte ensinkään vastannut, niin että Pilatus ihmetteli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 6, 'Mutta juhlana päästi hän heille yhden vangin irralle, kenenkä he anoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 7, 'Niin oli yksi nimeltä Barabbas, joka oli sidottu kapinan nostajitten kanssa, jotka kapinassa murhan tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 8, 'Ja kansa huusi ja rupesi häntä rukoilemaan, että hän tekis niinkuin hän aina heille tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 9, 'Niin Pilatus vastasi heitä, sanoen: tahdotteko, että minä päästän teille Juudalaisten kuninkaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 10, '(Sillä hän tiesi, että ylimmäiset papit olivat hänen kateudesta antaneet ylön.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 11, 'Mutta ylimmäiset papit yllyttivät kansaa, että hän heille ennen päästäis Barabbaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 12, 'Niin Pilatus vastasi ja taas sanoi heille: mitä te siis tahdotte, että minun pitää tälle tekemän, jonka te Juudalaisten kuninkaaksi kutsutte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 13, 'Niin he taas huusivat: ristiinnaulitse häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 14, 'Mutta Pilatus sanoi heille: mitäs hän pahaa on tehnyt? Mutta he huusivat vielä kovemmin: ristiinnaulitse häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 15, 'Mutta Pilatus tahtoi kansan mielen noutaa ja päästi heille Barabbaan. Ja Jesuksen, kuin hän hänen ruoskinut oli, antoi ylös ristiinnaulittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 16, 'Niin huovit veivät hänen raastupaan ja kutsuivat kokoon kaiken joukon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 17, 'Ja puettivat hänen purpuraan ja panivat hänen päähänsä väännetyn orjantappuraisen kruunun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 18, 'Ja rupesivat häntä tervehtimään: terve Juudalaisten kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 19, 'Ja he löivät häntä päähän ruovolla ja sylkivät hänen päällensä, panivat polvillensa ja kumartaen rukoilivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 20, 'Ja kuin he olivat häntä pilkanneet, riisuivat he häneltä purpuran, ja puettivat hänen omiin vaatteisiinsa, ja veivät hänen ulos ristiinnaulittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 21, 'Ja niin he vaativat yhden, joka ohitse kävi (ja tuli pellolta, Simonin Kyreniläisen, Aleksanderin ja Rufin isän), kantamaan hänen ristiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 22, 'Ja he veivät hänen siihen paikkaan, joka kutsutaan Golgata, se on niin paljo kuin Pääkallon paikka,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 23, 'Ja he antoivat hänelle viinaa juoda myrrhamilla sekoitettua. Vaan ei hän ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 24, 'Ja kuin he olivat hänen ristiinnaulinneet, jakoivat he hänen vaatteensa ja heittivät niistä arpaa, mitä kunkin piti saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 25, 'Mutta se oli kolmas hetki, kun he hänen ristiinnaulitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 26, 'Ja oli päällekirjoitettu hänen syynsä kirjoitus: JUUDALAISTEN KUNINGAS.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 27, 'Ja he ristiinnaulitsivat kaksi ryöväriä hänen kanssansa, yhden hänen oikialle ja toisen vasemmalle puolellensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 28, 'Ja niin täytettiin se kirjoitus, joka sanoo: ja hän on pahantekiäin sekaan luettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 29, 'Ja ne, jotka siitä ohitse kävivät, pilkkasivat häntä ja vääntelivät päätänsä, sanoen: voi sinuas, joka templin maahan jaotat ja kolmena päivänä rakennat ylös!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 30, 'Vapahda itses ja astu alas rististä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 31, 'Niin myös ylimmäiset papit pilkkasivat häntä keskenänsä kirjanoppineiden kanssa, sanoen: muita hän autti, ei hän voi itsiänsä auttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 32, 'Kristus, Israelin kuningas, astukaan nyt alas rististä, että me näkisimme ja uskoisimme. Ja ne, jotka hänen kanssansa ristiinnaulitut olivat, pilkkasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 33, 'Mutta kuin kuudes hetki tuli, tuli pimeys kaiken maan päälle hamaan yhdeksänteen hetkeen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 34, 'Ja yhdeksännellä hetkellä huusi Jesus suurella äänellä, sanoen: Eli, Eli, lamma sabaktani? se on niin paljo kuin: minun Jumalani, minun Jumalani, miksis minut annoit ylön?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 35, 'Ja kuin muutamat, jotka siinä seisoivat, sen kuulivat, sanoivat he: katso, hän huutaa Eliasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 36, 'Niin juoksi yksi ja täytti sienen etikalla ja pani sen ruovon ympärille, taritsi hänen juoda, sanoen: pidäs! katsokaamme, tuleeko Elias häntä ottamaan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 37, 'Mutta Jesus huusi suurella äänellä ja antoi henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 38, 'Ja templin esivaate repesi kahtia, ylhäältä hamaan alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 39, 'Mutta kuin päämies, joka siinä hänen kohdallansa seisoi, näki, että hän niin huutain henkensä antoi, sanoi hän: totisesti oli tämä ihminen Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 40, 'Ja siellä oli myös vaimoja, jotka taampaa katselivat, joiden seassa oli Maria Magdalena ja Maria, vähemmän Jakobin ja Joseen äiti, ja Salome,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 41, 'Jotka myös häntä Galileassa seuranneet ja palvelleet olivat; ja monta muuta, jotka hänen kanssansa Jerusalemiin menneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 42, 'Ja kuin jo ehtoo tuli (että valmistuspäivä oli, joka on esisabbatti),');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 43, 'Tuli Joseph Arimatiasta, kunniallinen raatimies, joka myös odotti Jumalan valtakuntaa, hän rohkeni mennä Pilatuksen tykö ja anoi Jesuksen ruumista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 44, 'Niin Pilatus ihmetteli, että hän jo kuollut oli, ja kutsui tykönsä päämiehen ja kysyi häneltä, oliko hän jo aikaa kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 45, 'Ja kuin hän asian päämiehiltä ymmärsi, antoi hän Josephille ruumiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 46, 'Ja hän osti liinavaatteen, otti hänen alas ja kääri liinavaatteeseen, ja pani hänen hautaan, joka kallioon hakattu oli, ja vieritti kiven haudan ovelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 47, 'Mutta Maria Magdalena ja Joseen Maria katselivat, kuhunka hän pantiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 1, 'Ja kuin sabbatti kulunut oli, osti Maria Magdalena ja Maria Jakobin ja Salome hyvänhajullisia voiteita, tullaksensa voitelemaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 2, 'Ja tulivat haudalle ensimäisenä sabbatin päivänä sangen varhain auringon noustessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 3, 'Ja puhuivat keskenänsä: kuka meille vierittää kiven haudan ovelta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 4, 'Ja kuin he katsoivat, näkivät he kiven vieritetyksi; sillä se oli sangen suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 5, 'Ja kuin he olivat hautaan menneet sisälle, näkivät he yhden nuorukaisen istuvan oikealla puolella, joka oli vaatetettu pitkällä valkialla vaatteella; ja he hämmästyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 6, 'Mutta hän sanoi heille: älkäät hämmästykö! te etsitte Jesusta Natsarealaista, joka ristiinnaulittu oli. Hän nousi ylös, ei hän ole täällä: katso siaa, kuhunka he hänen panivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 7, 'Mutta menkäät ja sanokaat hänen opetuslapsillensa ja Pietarille, että hän käy teidän edellänne Galileaan: siellä te hänen näette, niinkuin hän sanoi teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 8, 'Ja he menivät nopiasti ulos ja pakenivat haudalta; sillä vapistus ja suuri hämmästys oli heidän päällensä tullut, ei he myös kellenkään mitään sanoneet; sillä he pelkäsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 9, 'Mutta kuin Jesus oli varhain ensimäisenä sabbatin päivänä noussut ylös, ilmestyi hän ensin Maria Magdalenalle, josta hän seitsemän perkelettä oli ajanut ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 10, 'Se meni ja ilmoitti niille, jotka hänen kanssansa olleet olivat, jotka murehtivat ja itkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 11, 'Ja kuin he kuulivat hänen elävän, ja että hän häneltä nähty oli, ei he uskoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 12, 'SItte kuin kaksi heistä vaelsi, ilmestyi hän heille toisenmuotoisena, kuin he maakylään menivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 13, 'Ne myös menivät ja julistivat muille. Ja ei he niitäkään uskoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 14, 'Viimein, kuin yksitoistakymmentä atrioitsivat, ilmestyi hän, ja soimasi heidän epäuskoansa ja heidän sydämensä kankiutta, ettei he uskoneet niitä, jotka nänen nähneet olivat nousseeksi ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 15, 'Ja sanoi heille: menkäät kaikkeen maailmaan, ja saarnatkaat evankeliumia kaikille luoduille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 16, 'Joka uskoo ja kastetaan, se tulee autuaaksi; mutta joka ei usko, se kadotetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 17, 'Mutta nämä ovat ne merkit, jotka niitä seuraavat, jotka uskovat: minun nimeni kautta pitää heidän perkeleet ajaman ulos, uusilla kielillä puhuman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 18, 'Käärmeet ajaman pois, ja jos he jotakin myrkkyä juovat, niin ei heille mitään vahingoita; sairasten päälle pitää heidän kätensä paneman, ja ne paranevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 19, 'Ja Herra, sitte kuin hän oli heille puhunut, otettiin ylös taivaaseen ja istui Jumalan oikialle kädelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 20, 'Mutta he menivät ja saarnasivat joka paikassa, ja Herra vaikutti heidän kanssansa ja vahvisti sanan seuraavaisten merkkien kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Että moni on ruvennut järjestänsä kirjoittamaan niistä asioista, joista meillä täydellinen tieto on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Niinkuin ne meille sanoneet ovat, jotka sen alusta itse nähneet ja sananpalveliat olleet ovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Näkyy myös minulle se hyväksi, sitte kuin minä alusta kaikki visusti tutkinut olen, että minä niitä järjestänsä sinulle kirjoittaisin, hyvä Teophilus:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Ettäs ymmärtäisit selkiästi niiden asiain vahvan totuuden, joista sinä opetettu olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Herodeksen, Juudean kuninkaan, aikana oli pappi, Sakarias nimeltä, Abian vuorosta; ja hänen emäntänsä Aaronin tyttäristä, ja hänen nimensä Elisabet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Ja he olivat molemmat hurskaita Jumalan edessä, vaeltavaiset kaikissa Herran käskyissä ja säädyissä laittamattomasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Ja heillä ei ollut lasta; sillä Elisabet oli hedelmätöin, ja he olivat jo molemmat ijälliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Ja tapahtui, kuin hän vuorollansa papin virkaa toimitti Jumalan edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Papin viran tavan jälkeen, lankesi arpa hänelle, että hänen piti suitsuttaman, sitte kuin hän oli mennyt sisälle Herran templiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Ja kaikki kansan paljous rukoili ulkona suitsutuksen aikana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Mutta hänelle ilmestyi Herran enkeli, seisoin suitsutusalttarin oikealla puolella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Ja kuin Sakarias hänen näki, hämmästyi hän ja pelko lankesi hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Mutta enkeli sanoi hänelle: älä pelkää, Sakarias! sillä sinun rukoukses on kuultu ja sinun emäntäs Elisabet synnyttää sinulle pojan, ja sinun pitää kutsuman hänen nimensä Johannes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Ja sinulle tulee ilo ja ihastus, ja monta iloitsevat hänen syntymisestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Sillä hän tulee suureksi Herran edessä, ja viinaa ja väkevää juomaa ei hän juo, ja hän täytetään Pyhällä Hengellä jo äitinsä kohdusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'ja hän kääntää monta Israelin lapsista Herran, heidän Jumalansa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Ja hän käy edellä hänen edessänsä Eliaan Hengellä ja voimalla, kääntäin isäin sydämet lasten tykö ja tottelemattomat hurskasten toimen tykö, toimittaakseen Herralle valmistetun kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Ja Sakarias sanoi enkelille: mistä minä sen ymmärrän? sillä minä olen vanha ja emäntäni on jo ijällinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Niin enkeli vastasi ja sanoi hänelle: minä olen Gabriel, joka seison Jumalan edessä, ja olen lähetetty puhumaan sinulle ja saattamaan näitä iloisia sanomia sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Ja katso, sinä tulet kielettömäksi ja et saa puhua hamaan siihen päivään asti, jona nämä tapahtuvat, ettet uskonut sanojani, jotka ajallansa täytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Mutta kansa odotti Sakariasta, ja ihmettelivät, että hän niin templissä viipyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Vaan kuin hän tuli ulos, niin ei hän saanut puhua heille. Ja he ymmärsivät, että hän oli näyn templissä nähnyt. Ja hän viittasi heille, ja jäi mykäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Ja tapahtui, että hänen virkansa päivät olivat täytetyt, niin hän meni kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Mutta niiden päiväin jälkeen tuli hänen emäntänsä Elisabet raskaaksi ja salasi itsensä viisi kuukautta, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Ja näin on Herra minulle tehnyt niinä päivinä, kuin hän minun puoleeni katsoi, että hän ottais pois minun ylönkatseeni ihmisten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Mutta kuudentena kuukautena lähetettiin enkeli Gabriel Jumalalta Galilean kaupunkiin, jonka nimi oli Nasaret,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Neitseen tykö, joka oli kihlattu miehelle, jonka nimi oli Joseph, Davidin huoneesta; ja neitseen nimi oli Maria.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 28, 'Ja enkeli tuli sisälle hänen tykönsä ja sanoi: terve, armoitettu! Herra on sinun kanssas: siunattu sinä vaimoin seassa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 29, 'Mutta kuin hän näki hänen, hämmästyi hän hänen puheestansa ja ajatteli, millainen se tervehdys oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 30, 'Ja enkeli sanoi hänelle: älä pelkää, Maria! sillä sinä löysit armon Jumalan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 31, 'Ja katso, sinä siität kohdussas ja synnytät Pojan, ja sinun pitää kutsua hänen nimensä Jesus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 32, 'Sen pitää oleman suuren ja pitää kutsuttaman Ylimmäisen Pojaksi. Ja Herra Jumala antaa hänelle Davidin hänen isänsä istuimen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 33, 'Ja hänen pitää Jakobin huoneen kuningas ijankaikkisesti oleman ja hänen valtakunnallansa ei pidä loppua oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 34, 'Niin sanoi Maria enkelille: kuinka tämä tulee, sillä en minä miehestä mitään tiedä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 35, 'Ja enkeli vastasi ja sanoi hänelle: Pyhä Henki tulee sinun päälles ja Ylimmäisen voima varjoo sinun: sentähden myös se pyhä, joka sinusta syntyy, pitää kutsuttaman Jumalan Pojaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 36, 'Ja katso, Elisabet sinun lankos siitti myös pojan vanhalla ijällänsä, ja tämä on kuudes kuukausi hänelle, joka kutsuttiin hedelmättömäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 37, 'Sillä ei Jumalan edessä ole yhtään asiaa mahdotointa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 38, 'Niin sanoi Maria: katso, Herran piika! tapahtukoon minulle sinun sanas jälkeen! Ja enkeli läksi hänen tyköänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 39, 'Mutta Maria nousi niinä päivinä ja meni kiiruusti ylös mäkikyliin Juudan kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 40, 'Ja tuli Sakariaan huoneeseen ja tervehti Elisabetia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 41, 'Ja tapahtui, kuin Elisabet kuuli Marian tervehdyksen, hyppäsi lapsi hänen kohdussansa. Ja Elisabet täytettiin Pyhällä Hengellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 42, 'Ja hän huusi suurella äänellä ja sanoi: siunattu olet sinä vaimoin seassa, ja siunattu on sinun kohtus hedelmä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 43, 'Ja kusta se minulle tulee, että minun Herrani äiti tulee minun tyköni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 44, 'Sillä katso, kuin sinun tervehdykses ääni tuli minun korviini, hyppäsi lapsi ilosta minun kohdussani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 45, 'Ja autuas sinä, joka uskoit; sillä ne täytetään, mitkä sinulle ovat sanotut Herralta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 46, 'Ja Maria sanoi: Minun sieluni suuresti ylistää Herraa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 47, 'Ja minun henkeni iloitsee Jumalassa, minun vapahtajassani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 48, 'Että hän katsoi piikansa nöyryyttä; sillä katso, tästedes pitää kaikkein sukukuntain minua autuaaksi kutsuttaman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 49, 'Sillä Voimallinen on suuria ihmeitä tehnyt minun kohtaani, ja hänen nimensä on pyhä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 50, 'Ja hänen laupiutensa pysyy suvusta sukuun niille, jotka häntä pelkäävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 51, 'Hän osoitti voiman käsivarrellansa ja hajotti koriat heidän sydämensä mielestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 52, 'Voimalliset on hän kukistanut istuimelta ja korotti nöyrät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 53, 'Isoovat täytti hän hyvyydellä ja jätti rikkaat tyhjäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 54, 'Hän korjasi palvelijansa Israelin, muistain omaa laupiuttansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 55, '(Niinkuin hän on puhunut meidän isillemme, Abrahamille ja hänen siemenellensä) ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 56, 'Ja Maria oli hänen tykönänsä lähes kolme kuukautta ja palasi kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 57, 'Mutta Elisabetin synnyttämisen aika täytettiin, ja hän synnytti pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 58, 'Ja hänen kylällisensä ja lankonsa kuulivat, että Herra oli tehnyt suuren laupiuden hänen kanssansa, ja he iloitsivat hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 59, 'Ja tapahtui kahdeksantena päivänä, että he tulivat lasta ympärileikkaamaan, ja kutsuivat hänen isänsä nimeltä Sakarias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 60, 'Niin vastasi hänen äitinsä ja sanoi: ei suinkaan; vaan hän pitää kutsuttaman Johannes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 61, 'Ja he sanoivat hänelle: ei ole ketään sinun sukukunnassas, joka kutsutaan sillä nimellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 62, 'Niin he viittasivat hänen isällensä, miksi hän tahtoi hänen nimittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 63, 'Ja hän anoi taulua ja kirjoitti: Johannes on hänen nimensä. Ja kaikki ihmettelivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 64, 'Niin kohta aukeni hänen suunsa ja hänen kielensä, ja puhui kiittäin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 65, 'Ja pelko tuli kaikkein heidän kylällistensä päälle, ja kaikissa Juudean mäkikylissä ilmoitettiin kaikki nämä sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 66, 'Ja kaikki, jotka tämän kuulivat, panivat sydämiinsä, sanoen: minkäs luulet tästä lapsesta tulevan? Sillä Herran käsi oli hänen kanssaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 67, 'Ja Sakarias ja hänen isänsä täytettiin Pyhällä Hengellä ja ennusti, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 68, 'Kiitetty olkoon Herra, Israelin Jumala! sillä hän on etsinyt ja lunastanut kansansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 69, 'Ja on meille korottanut autuuden sarven, Davidin palveliansa huoneessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 70, 'Niinkuin hän on muinen puhunut pyhäin prophetainsa suun kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 71, 'Vapahtaaksensa meitä meidän vihollisiltamme ja kaikkein kädestä, jotka meitä vihaavat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 72, 'Osoittaaksensa laupiutta meidän isillemme ja muistaaksensa pyhää liittoansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 73, 'Ja sitä valaa, jonka hän vannoi Abrahamille, meidän isällemme, meille antaaksensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 74, 'Että me, vapahdetut vihollistemme kädestä, häntä pelkäämättä palvelisimme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 75, 'Pyhyydessä ja hurskaudessa hänen edessänsä kaikkena meidän elinaikanamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 76, 'Ja sinä poikainen pitää kutsuttaman Ylimmäisen prophetaksi; sillä sinun pitää käymän Herran kasvoin edessä, valmistamaan hänen teitänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 77, 'Ja antaman autuuden tunnon hänen kansallensa, heidäin synteinsä anteeksi saamiseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 78, 'Meidän Jumalan sydämellisen laupiuden kautta, jolla meitä on etsinyt koitto ylhäältä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 79, 'Valaisemaan niille, jotka pimeissä ja kuolon varjoissa istuvat, ja ojentamaan meidän jalkamme rauhan tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 80, 'Mutta lapsi kasvoi ja vahvistui hengessä, ja oli korvessa siihen päivään asti, jona hänen piti Israelin kansan eteen tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Mutta niinä päivinä tapahtui, että käsky kävi ulos keisarilta Augustukselta, että kaikki maailma piti verolliseksi laskettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Ja tämä veron-laskemus oli ensimmäinen, joka tapahtui silloin, kun Kyrenius oli maaherra Syriassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Ja kukin meni kaupunkiinsa antamaan itsiänsä arvattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Niin myös Joseph Galileasta, Natsaretin kaupungista, meni ylös Juudeaan, Davidin kaupunkiin, joka kutsutaan Betlehem, (sillä hän oli Davidin huoneesta ja suvusta)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Antamaan itsiänsä arvattaa, Marian, kihlatun emäntänsä kanssa, joka raskas oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Niin tapahtui heidän siellä ollessaan, että hänen synnyttämisensä päivät tulivat täytetyksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Ja hän synnytti pojan, esikoisensa, ja kapaloitsi hänen ja pani seimeen, ettei heillä ollut siaa majassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Ja paimenet valvoivat siinä paikkakunnassa ja vartioitsivat yöllä laumaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Ja katso, Herran enkeli seisoi heidän tykönänsä ja Herran kirkkaus ympäri valaisi heitä, ja he suuresti peljästyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Ja enkeli sanoi heille: älkäät peljätkö! sillä katso, minä ilmoitan teille suuren ilon, joka on tuleva kaikelle kansalle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Teille on tänäpäivänä syntynyt vapahtaja, joka on Kristus, Herra, Davidin kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Ja tämä on teille merkiksi: te löydätte lapsen kapaloituna makaavan seimessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Ja kohta oli enkelin kanssa suuri taivaallisen sotaväen joukko, jotka kiittivät Jumalaa ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Kunnia olkoon Jumalalle korkeudessa, ja maassa rauha, ja ihmisille hyvä tahto!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Ja tapahtui, että enkelit menivät heidän tyköänsä taivaaseen, niin ne paimenet puhuivat keskenänsä: käykäämme Betlehemiin ja katsokaamme sitä mikä tapahtunut on, jonka Herra meille ilmoitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Ja he tulivat kiiruhtain, ja löysivät Marian ja Josephin, niin myös lapsen, joka makasi seimessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Kuin he tämän nähneet olivat, julistivat he sen sanoman, joka heille tästä lapsesta sanottu oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Ja kaikki, jotka sen kuulivat, ihmettelivät niitä, mitä heille paimenilta sanottu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Mutta Maria kätki kaikki nämät sanat, tutkistellen sydämessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Ja paimenet palasivat, ylistäin ja kunnioittain Jumalaa kaikista, mitä he kuulleet ja nähneet olivat, niinkuin heille sanottu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Ja kuin kahdeksan päivää kulunut oli, että lapsi piti ympärileikattaman, kutsuttiin hänen nimensä Jesus, joka niin oli enkeliltä kutsuttu jo ennen kuin hän sikisi äitinsä kohdussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Ja kuin heidän puhdistuspäivänsä olivat täytetyt Moseksen lain jälkeen, veivät he hänet Jerusalemiin, asettaaksensa häntä Herran eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, '(Niinkuin kirjoitettu on Herran laissa: kaikki miehenpuoli, joka ensin avaa äitinsä kohdun, pitää kutsuttaman Herralle pyhäksi,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Ja uhrataksensa, niinkuin sanottu on Herran laissa, pari mettistä eli kaksi kyhkyläisen poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Ja katso, mies oli Jerusalemissa, jonka nimi oli Simeon: tämä oli hurskas ja jumalinen mies, odottain Israelin lohdutusta, ja Pyhä Henki oli hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Ja hänelle oli sanottu Pyhältä Hengeltä, ettei hänen pitänyt ennen kuolemaa näkemän, kuin hän näkis Herran Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 27, 'Ja hän tuli Hengen kautta templiin. Ja kuin vanhemmat toivat lapsen Jesuksen sisälle, tehdäksensä hänen edestänsä lain tavan jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 28, 'Niin hän otti hänen syliinsä, ja kiitti Jumalaa ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 29, 'Nyt sinä, Herra, lasket palvelias rauhaan menemään, sanas jälkeen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 30, 'Sillä minun silmäni ovat nähneet sinun autuutes,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 31, 'Jonka sinä valmistit kaikkein kansain eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 32, 'Valkeudeksi valistamaan pakanoita ja sinun kansas Israelin kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 33, 'Ja Joseph ja hänen äitinsä ihmettelivät niitä, joita hänestä sanottiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 34, 'Simeon siunasi heitä ja sanoi Marialle, hänen äidillensä: katso, tämä on pantu lankeemiseksi ja nousemiseksi monelle Israelissa, ja merkiksi, jota vastaan sanotaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 35, '(Ja sinunkin sielus lävitse pitää miekan käymän:) että monen sydämen ajatukset ilmoitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 36, 'Ja Anna prophetissa, Phanuelin tytär, Asserin suvusta, se oli joutunut pitkälle ijälle ja elänyt miehensä kanssa seitsemän ajastaikaa neitsyestänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 37, 'Ja oli leskenä lähes neljäyhdeksättäkymmentä ajastaikaa, ja ei lähtenyt templistä, palvelemasta Jumalaa paastoissa ja rukouksissa yötä ja päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 38, 'Ja tämä tuli sillä hetkellä siihen ja kunnioitti myös Herraa, ja puhui hänestä kaikille, jotka lunastusta Jerusalemissa odottivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 39, 'Ja sittekuin he olivat kaikki tehneet Herran lain jälkeen, palasivat he Galileaan, kaupunkiinsa Natsaretiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 40, 'Mutta lapsi kasvoi ja vahvistui hengessä, ja täytettiin viisaudella, ja Jumalan armo oli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 41, 'Ja hänen vanhempansa vaelsivat joka vuosi pääsiäisjuhlille Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 42, 'Ja kuin hän kahdentoistakymmenen ajastajan vanha oli, menivät he Jerusalemiin juhlapäivän tavan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 43, 'Ja kuin ne päivät olivat kuluneet, siinä kuin he palasivat, jäi poikainen Jesus Jerusalemiin: jota ei Joseph ja hänen äitinsä huomanneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 44, 'Vaan luulivat hänen olevan seurassa. Ja he kävivät yhden päivän matkan, ja etsivät häntä lankoin ja tuttavien seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 45, 'Ja kuin ei he häntä löytäneet, palasivat he Jerusalemiin, etsien häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 46, 'Ja tapahtui kolmen päivän perästä, että he löysivät hänen templissä istuvan opettajain keskellä, kuultelevan heitä ja kysyvän heiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 47, 'Ja kaikki, jotka hänen kuulivat, hämmästyivät hänen ymmärrystänsä ja vastauksiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 48, 'Ja kuin he hänen näkivät, niin he hämmästyivät, ja hänen äitinsä sanoi hänelle: Poikani, miksis meille näin teit? katso, sinun isäs ja minä olemme murehtien etsineet sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 49, 'Ja hän sanoi heille: mitäs te minua etsitte? ettekö tienneet, että minun pitää niissä oleman, jotka minun Isäni ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 50, 'Ja ei he ymmärtäneet sitä sanaa, jonka hän heille sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 51, 'Ja hän meni alas heidän kanssansa ja tuli Natsaretiin, ja oli heille alamainen. Ja hänen äitinsä kätki kaikki nämät sanat sydämeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 52, 'Ja Jesus menestyi viisaudessa ja ijässä ja armossa Jumalan ja ihmisten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Mutta viidennellätoistakymmenellä keisari Tiberiuksen hallituksen vuodella, kuin Pontius Pilatus oli Juudean maaherra, ja Herodes tetrarka Galileassa, ja hänen veljensä Philippus tetrarka Itureassa ja Trakonitin maakunnassa, ja Lysanias oli tetrarka Abilenessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Kuin Hannas ja Kaiphas ylimmäiset papit olivat: silloin tapahtui Jumalan sana Johannekselle Sakariaan pojalle korvessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Ja hän tuli kaikkiin maan paikkoihin Jordanin ympäri ja saarnasi parannuksen kastetta syntein anteeksi antamiseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Niinkuin kirjoitettu on Jesaias prophetan saarnaraamatussa, joka sanoo: huutavan ääni on korvessa: valmistakaat Herran tietä ja tehkäät hänen polkunsa oikiaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Kaikki laaksot pitää täytettämän ja kaikki vuoret ja mäet alennettaman, väärät pitää ojennettaman, ja koliat tasaiseksi tieksi tehtämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Ja kaikki liha pitää näkemän Jumalan autuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Niin hän sanoi kansalle, joka tuli antamaan itsiänsä kastaa häneltä: te kyykärmetten sikiät, kuka teitä neuvoi välttämään tulevaista vihaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Tehkäät siis soveliaat parannuksen hedelmät ja älkäät ruvetko sanomaan itsellänne: Abraham on meidän isämme; sillä minä sanon teille, että Jumala taitaa näistä kivistä herättää Abrahamille lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Mutta jo on myös kirves pantu puiden juurelle; sentähden jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja tuleen heitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Ja kansa kysyi häneltä, sanoen: mitä meidän pitää tekemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Niin hän vastaten sanoi heille: jolla on kaksi hametta, antakaan sille, jolla ei yhtään ole, ja jolla on ruokaa, hän tehkään myös niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Mutta Publikanit tulivat myös antamaan heitänsä kastaa ja sanoivat hänelle: Mestari, mitä meidän pitää tekemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Vaan hän sanoi heille: älkäät enempää vaatiko kuin teille säätty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Niin kysyivät myös häneltä sotamiehet, sanoen: mitä myös meidän pitää tekemän? Ja hän sanoi heille: älkäät kenellekään väkivaltaa taikka vääryyttä tehkö, ja tyytykäät palkkaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Mutta kuin kansa odotti, ja kaikki ajattelivat sydämessänsä Johanneksesta: lieneekö hän Kristus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Vastasi Johannes, sanoen kaikille: minä tosin kastan teitä vedellä; mutta minua väkevämpi tulee, jonka kengän nauhoja en minä ole kelvollinen päästämään: hän kastaa teitä Pyhällä Hengellä ja tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Jonka viskin on hänen kädessänsä, ja hän perkaa riihensä ja kokoo nisunsa aittaansa, mutta ruumenet polttaa hän sammumattomalla tulella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Monta tosin myös muuta hän neuvoi ja saarnasi kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 19, 'Mutta kun Herodes tetrarka nuhdeltiin häneltä, Herodiaksen veljensä Philippuksen emännän tähden ja kaikesta pahuudesta, jota Herodes teki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 20, 'Niin hän ylitse kaikkein teki myös sen, että hän salpasi Johanneksen vankiuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 21, 'Ja tapahtui, kuin kaikki kansa kastettiin, ja Jesus myös oli kastettu, ja hän rukoili, niin taivas aukeni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 22, 'Ja Pyhä Henki tuli alas ruumiillisella muodolla hänen päällensä niinkuin kyyhkynen, ja ääni tuli taivaasta, joka sanoi: sinä olet minun rakas Poikani, sinuun minä mielistyin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 23, 'Ja Jesus oli lähes kolmenkymmenen vuotinen, joka oli (niinkuin luultiin) Josephin poika, Elin pojan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 24, 'Joka oli Mattatin poika, joka oli Levin poika, joka oli Melkin poika, joka oli Jannan poika, joka oli Josephin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 25, 'Joka oli Mattatian poika, joka oli Amoksen poika, joka oli Naumin poika, joka oli Eslin poika, joka oli Naggain poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 26, 'Joka oli Maatin poika, joka oli Mattatian poika, joka oli Semein poika, joka oli Josephin poika, joka oli Juudan poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 27, 'Joka oli Joannan poika, joka oli Resan poika, joka oli Zorobabelin poika, joka oli Salatielin poika, joka oli Nerin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 28, 'Joka oli Melkin poika, joka oli Addin poika, joka oli Kosamin poika, joka oli Elmodamin poika, joka oli Eerin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 29, 'Joka oli Josen poika, joka oli Elieserin poika, joka oli Jorimin poika, joka oli Mattatin poika, joka oli Levin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 30, 'Joka oli Simeonin poika, joka oli Juudan poika, joka oli Josephin poika, joka oli Jonain poika, joka oli Eliakimin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 31, 'Joka oli Melean poika, joka oli Mainanin poika, joka oli Mattatan poika, joka oli Natanin poika, joka oli Davidin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 32, 'Joka oli Jessen poika, joka oli Obedin poika, joka oli Bootsin poika, joka oli Salmonin poika, joka oli Naassonin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 33, 'Joka oli Aminadabin poika, joka oli Aramin poika, joka oli Esromin poika, joka oli Phareksen poika, joka oli Juudan poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 34, 'Joka oli Jakobin poika, joka oli Isaakin poika, joka oli Abrahamin poika, joka oli Taran poika, joka oli Nahorin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 35, 'Joka oli Sarukin poika, joka oli Ragaun poika, joka oli Phalekin poika, joka oli Eberin poika, joka oli Salan poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 36, 'Joka oli Kainanin poika, joka oli Arphaksadin poika, joka oli Semin poika, joka oli Noan poika, joka oli Lamekin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 37, 'Joka oli Matusalan poika, joka oli joka oli Enokin poika, joka oli Jaredin poika, joka oli Maleleelin poika, joka oli Kainanin poika,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 38, 'Joka oli Enoksen poika, joka oli Setin poika, joka oli Adamin poika, joka oli Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Niin Jesus täynnänsä Pyhää Henkeä palasi Jordanista ja vietiin Hengeltä korpeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Ja kiusattiin neljäkymmentä päivää perkeleeltä, eikä syönyt mitään niinä päivinä; mutta kuin ne kuluneet olivat, sitte hän isosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Niin perkele sanoi hänelle: jos sinä olet Jumalan Poika, niin sanos tälle kivelle, että se leiväksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Ja Jesus vastasi, sanoen hänelle: kirjoitettu on: ei ihminen elä ainoasti leivästä, vaan jokaisesta Jumalan sanasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ja perkele vei hänen korkialle vuorelle ja osoitti hänelle kaikki maan piirin valtakunnat silmänräpäyksellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Ja perkele sanoi hänelle: kaiken tämän vallan ja heidän kunniansa minä annan sinulle; sillä minun haltuuni ovat ne annetut, ja minä annan ne kenelle minä tahdon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Jos sinä siis kumarrat ja rukoilet minua, ne kaikki pitää sinun omas oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Ja Jesus vastaten sanoi hänelle: mene matkaas minun tyköäni, saatana! sillä kirjoitettu on: Herraa sinun Jumalaas pitää sinun kumartaman ja häntä ainoaa palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Ja hän vei hänen Jerusalemiin ja asetti hänen templin harjalle, ja sanoi hänelle: jos sinä olet Jumalan Poika, niin laske tästä itses alas;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Sillä kirjoitettu on: hän antaa käskyn enkeleillensä sinusta varjelemaan sinua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Ja että he käsissä kantavat sinua, ettet joskus jalkaas kiveen loukkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Ja Jesus vastaten sanoi hänelle: sanottu on: ei sinun pidä kiusaaman Herraa sinun Jumalaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Ja kuin kaikki kiusaus oli päätetty, meni perkele pois hetkeksi hänen tyköänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Ja Jesus palasi Hengen väessä taas Galileaan, ja sanoma kuului hänestä ympäri kaiken lähimaakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Ja hän opetti heidän synagogissansa, ja kunnioitettiin kaikkialta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Ja tuli Natsaretiin, kussa hän kasvatettu oli, ja meni tapansa jälkeen sabbatin päivänä synagogaan, ja nousi lukemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Ja hänelle annettiin Jesaias prophetan Raamattu. Ja kuin hän Raamatun avasi, löysi hän sen paikan, kussa kirjoitettu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, 'Herran Henki on minun päälläni, sentähden on hän minut voidellut ja lähettänyt minun saarnaamaan köyhille hyvää sanomaa, parantamaan särjetyitä sydämiä, saarnaamaan vangeille lunastusta ja sokeille näkönsä jälleen saamista, särjetyitä vapauteen saattamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 19, 'Saarnaamaan Herran otollista vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 20, 'Ja kun hän pani Raamatun kiinni, antoi hän sen palvelialle ja istui, ja kaikkein silmät, jotka synagogassa olivat, katselivat hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 21, 'Ja hän rupesi heille sanomaan: tänäpänä on tämä kirjoitus täytetty, jonka te nyt kuulette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 22, 'Ja kaikki antoivat hänelle todistuksen ja ihmettelivät niitä armon sanoja, jotka hänen suustansa läksivät ulos, ja he sanoivat: eikö tämä ole Josephin poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 23, 'Ja hän sanoi heille: sanokaat kaiketi minulle tämä sananlasku: parantaja, paranna itses; ne mitkä me kuulimme tapahtuneen Kapernaumissa, tee myös tässä isäs maalla!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 24, 'Mutta hän sanoi: totisesti sanon minä teille: ei yksikään propheta ole isänsä maalla otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 25, 'Vaan minä sanon teille totuudessa: monta leskeä oli Israelissa Eliaan ajalla, kuin taivas oli suljettu kolme vuotta ja kuusi kuukautta, niin että suuri nälkä tapahtui kaikessa maakunnassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 26, 'Ja ei Elias lähetetty yhdenkään heidän tykönsä, vaan leskivaimon tykö Sidonin Sareptaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 27, 'Ja monta spitalista oli Israelissa Elisa prophetan ajalla, ja ei yksikään heistä puhdistettu, vaan Naeman Syrialainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 28, 'Ja kaikki jotka synagogassa olivat, tulivat vihoja täyteen, kuin he nämät kuulivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 29, 'Ja he nousivat ylös ja ajoivat hänen ulos kaupungista, ja veivät hänen hamaan vuoren kukkulalle, jonka päälle heidän kaupunkinsa rakettu oli, syöstäksensä häntä alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 30, 'Mutta hän kävi ohitse heidän keskeltänsä ja meni pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 31, 'Ja meni alas Kapernaumiin, Galilean kaupunkiin, ja opetti heitä siellä sabbatin päivinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 32, 'Ja he hämmästyivät hänen opetustansa; sillä hänen puheensa oli voimallinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 33, 'Ja synagogassa oli ihminen, jolla oli riettaisen perkeleen henki, ja hän huusi suurella äänellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 34, 'Sanoen: voi! mitä sinun on meidän kanssamme, Jesus Natsarealainen? tulitkos meitä hukuttamaan? minä tiedän, kukas olet, Jumalan pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 35, 'Ja Jesus nuhteli häntä, sanoen: vaikene ja mene ulos hänestä. Ja kuin perkele oli hänen heidän keskellänsä heittänyt, niin hän meni ulos hänestä ja ei häntä vahingoittanut mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 36, 'Ja pelko tuli kaikkein päälle, ja puhuivat keskenänsä, sanoen: mitä tämä lieneekään? sillä hän haastaa väellä ja voimalla riettaisia henkiä, ja lähtevät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 37, 'Ja sanoma hänestä kaikui ympäri kaikkiin sen maakunnan lähipaikkoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 38, 'Mutta kuin hän läksi synagogasta, meni hän Simonin huoneeseen sisälle; mutta Simonin anoppi sairasti kovin vilutautia, ja he rukoilivat häntä hänen edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 39, 'Ja hän seisoi hänen tykönänsä, ja nuhteli vilutautia, ja se luopui hänestä; ja hän nousi kohta ja palveli heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 40, 'Mutta kuin aurinko laski, niin kaikki, joilla oli sairaita moninaisissa taudeissa, veivät ne hänen tykönsä. Ja hän pani jokaisen päälle kätensä ja paransi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 41, 'Ja monesta läksivät myös perkeleet, huutain ja sanoen: sinä olet Kristus, Jumalan Poika. Niin hän nuhteli niitä eikä sallinut heidän puhua, sillä he tiesivät hänen olevan Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 42, 'Mutta kuin päivä tuli, meni hän erämaahan, ja kansa etsi häntä, ja he menivät hänen tykönsä, ja pidättivät hänen, ettei hän heidän tyköänsä olisi mennyt pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 43, 'Vaan hän sanoi heille: minun pitää myös muillekin evankeliumia Jumalan valtakunnasta saarnaaman; sillä sitä varten minä olen lähetetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 44, 'Ja hän saarnasi Galilean synagogissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Niin tapahtui, kuin kansa tunki hänen tykönsä, kuulemaan Jumalan sanaa, että hän seisoi Genesaretin meren tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Ja näki kaksi venhettä olevan meren tykönä; mutta kalamiehet olivat niistä lähteneet ja pesivät verkkoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Niin hän meni yhteen venheeseen, joka oli Simonin, ja käski * hänen vähän maasta laskea ulos; ja hän istui ja opetti kansaa venheestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Mutta kuin hän lakkasi puhumasta, sanoi hän Simonille: vie syvälle, ja heittäkää verkkonne apajalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Ja Simon vastaten sanoi hänelle: Mestari! me olemme kaiken yön työtä tehneet ja emme mitään saaneet; mutta sinun käskystäs minä heitän ulos verkon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Ja kuin he sen tekivät, sulkivat he suuren kalain paljouden, ja heidän verkkonsa repesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Ja he viittasivat kumppaneillensa, jotka olivat toisessa venheessä, tulemaan ja auttamaan heitä. Ja he tulivat ja täyttivät molemmat venheet, niin että he rupesivat vajoomaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Kuin Simon Pietari sen näki, lankesi hän Jesuksen polvien tykö, sanoen: Herra, mene pois minun tyköäni, sillä minä olen syntinen ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Sillä hämmästys oli hänen käsittänyt ja kaikki, jotka hänen kanssaan olivat, kalan saaliin tähden, jonka he saaneet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Niin myös Jakobin ja Johanneksen, Zebedeuksen pojat, jotka olivat Simonin kumppanit. Ja Jesus sanoi Simonille: älä pelkää, tästedes sinä saat ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Ja he vetivät venheet maalle ja antoivat ylön kaikki, ja seurasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Ja tapahtui, kuin hän oli yhdessä kaupungissa, katso, niin siinä oli mies spitalia täynnä; ja kuin hän näki Jesuksen, lankesi hän kasvoillensa, rukoili häntä, sanoen: Herra, jos sinä tahdot, niin sinä voit minut puhdistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Ja hän ojensi kätensä ja rupesi häneen, sanoen: minä tahdon, ole puhdas! Ja kohta spitali läksi hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ja hän kielsi hänen kellenkään sanomasta: vaan mene, (sanoi hän) ja osoita itses papille, ja uhraa sinun puhditukses edestä, niin kuin Moses käski, heille todistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Niin sanoma levisi enemmin hänestä, ja paljo kansaa kokoontui kuulemaan ja että he parannettaisiin häneltä taudeistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Mutta hän meni korpeen, ja rukoili.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Ja tapahtui yhtenä päivänä, kuin hän opetti, ja Pharisealaiset myös istuivat ja lainopettajat, jotka tulleet olivat jokaisesta Galilean ja Juudean kylästä ja Jerusalemista: ja Herran voima oli parantamassa heitä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Ja katso, miehet kantoivat vuoteessa ihmisen, joka oli halvattu, ja he pyysivät häntä viedä sisähälle ja panna hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Ja kuin ei he löytäneet kansan tähden, kusta puolesta he olisivat hänen saaneet sisälle, astuivat he katon päälle ja laskivat hänen lävitse katon vuoteinensa juuri Jeesuksen eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Ja kuin hän näki heidän uskonsa, sanoi hän sille: ihminen, sinun syntis anteeksi annetaan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, 'Ja kirjanoppineet ja Pharisealaiset rupesivat ajattelemaan, sanoen: kuka tämä on, joka pilkkasanoja puhuu? kuka voi synnit antaa anteeksi, paitsi ainoastaan Jumala?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 22, 'Mutta kuin Jesus tunsi heidän ajatuksensa, vastasi hän ja sanoi heille: mitä te ajattelette sydämessänne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 23, 'Kumpi on keveämpi? sanoa: sinun syntis anteeksi annetaan sinulle! taikka sanoa: nouse ja käy!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 24, 'Vaan että te tietäisitte Ihmisen Pojalla olevan vallan maan päällä synnit anteeksi antaa (sanoi hän halvatulle:) minä sanon sinulle: nouse ja ota vuotees, ja mene kotias!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 25, 'Ja hän nousi kohta heidän nähtensä ja korjasi vuotehensa, jossa hän maannut oli, ja meni kotiansa, kunnioittain Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 26, 'Ja suuri hämmästys tuli kaikkiin ja kunnioittivat Jumalaa, ja he täytettiin pelvolla, sanoen: me näimme tänäpänä kamalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 27, 'Sitte läksi hän ulos ja näki Publikanin nimeltä Levin, istuvan tullihuoneessa, ja sanoi hänelle: seuraa minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 28, 'Ja hän antoi ylön kaikki, nousi ja seurasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 29, 'Ja Levi teki hänelle kotonansa suuren pidon, ja paljo Publikaneja ja muita atrioitsivat heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 30, 'Ja heidän kirjanoppineensa ja Pharisealaiset napisivat hänen opetuslapsiansa, sanoen: miksi te Publikanien ja syntisten kanssa syötte ja juotte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 31, 'Ja Jesus vastaten sanoi heille: ei terveet tarvitse parantajaa, vaan sairaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 32, 'En ole minä tullut vanhurskaita kutsumaan, vaan syntisiä parannukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 33, 'Niin he sanoivat hänelle: miksi Johanneksen opetuslapset usein paastoavat ja rukouksia pitävät, niin myös Pharisealaisten (opetuslapset), mutta sinun syövät ja juovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 34, 'Mutta hän sanoi heille: ette voi hääjoukkoa niinkauvan paastoomaan vaatia, kuin ylkä on heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 35, 'Mutta päivät tulevat, että ylkä otetaan heiltä pois, silloin pitää heidän paastooman niinä päivinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 36, 'Mutta hän sanoi myös heille vertauksen: ei paikkaa kenkään uuden veran tilalla vanhaa vaatetta: muutoin myös se uusi repäisee, ja uusi paikka ei sovi vanhaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 37, 'ja ei pane kenkään nuorta viinaa vanhoihin leileihin: muutoin nuori viina rikkoo leilit, ja se vuotaa ulos, ja leilit turmellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 38, 'Mutta nuorta viinaa pitää pantaman uusiin leileihin: niin ne molemmat tallella ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 39, 'Ja ei tahdo kenkään, joka juo vanhaa viinaa, kohta nuorta juoda; sillä hän sanoo: vanha on parempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 1, 'Ja tapahtui jälkisabbattina, että hän kävi laihon lävitse, ja hänen opetuslapsensa katkoivat tähkäpäitä ja hiersivät käsillänsä, ja söivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 2, 'Niin muutamat Pharisealaiset sanoivat heille: miksi te teette, jota ei sovi sabbatina tehdä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 3, 'Ja Jesus vastaten sanoi heille: ettekö te ole lukeneet, mitä David teki, kuin hän isosi, ja ne, jotka hänen kanssaan olivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 4, 'Kuinka hän meni Jumalan huoneeseen, ja otti näkyleivät, ja söi, ja antoi myös niille, jotka hänen kanssaan olivat; joita ei muiden kuin pappein syödä sopinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 5, 'Ja hän sanoi heille: Ihmisen Poika on myös sabbatin Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 6, 'Niin tapahtui myös toisena sabbatina, että hän meni synagogaan sisälle ja opetti; ja siellä oli ihminen, jonka oikea käsi oli kuivettunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 7, 'Niin kirjanoppineet ja Pharisealaiset vartiotsivat häntä, josko hän sabbatina parantais, että he olisivat löytäneet kanteen häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 8, 'Mutta hän tiesi heidän ajatuksensa ja sanoi sille ihmiselle, jolla kuivettunut käsi oli: nouse ja tule edes! Niin hän nousi ja seisoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 9, 'Niin Jesus sanoi hänelle: minä kysyn teiltä: mitä sabbatina sopii, hyvää tehdä, taikka pahaa tehdä? henkeä vapahtaa eli kadottaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 10, 'Ja kuin hän katsahti ympäri heidän kaikkein päällensä, sanoi hän sille ihmiselle: ojenna kätes! ja se teki niin, ja hänen kätensä tuli terveeksi niinkuin toinenkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 11, 'Mutta he tulivat tyhmyyttä täyteen ja puhuivat keskenänsä, mitä heidän pitäis Jesukselle tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 12, 'Mutta niinä päivinä tapahtui, että hän meni vuorelle rukoilemaan, ja hän oli yli yötä Jumalan tykö rukouksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 13, 'Ja kuin päivä tuli, kutsui hän opetuslapsensa ja valitsi heistä kaksitoistakymmentä, jotka hän myös apostoleiksi nimitti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 14, 'Simonin, jonka hän myös Pietariksi kutsui, ja Andreaksen, hänen veljensä, Jakobin ja Johanneksen, Philippuksen ja Bartolomeuksen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 15, 'Matteuksen ja Toomaan, Jakobin Alphein pojan, ja Simonin, joka kutsutaan Zelotes,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 16, 'Juudaan Jakobin pojan, ja Juudas Iskariotin, joka myös oli pettäjä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 17, 'Ja kuin hän meni alas heidän kanssansa, seisoi hän lakialla paikalla, ja hänen opetuslastensa joukko, ja suuri kansan paljous kaikesta Juudeasta ja Jerusalemista, ja rantalaiset Tyrosta ja Sidonista, jotka olivat tulleet häntä kuulemaan, ja että he parannettaisiin taudeistansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 18, 'Ja jotka vaivattiin riettasilta hengiltä; ja he paranivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 19, 'Ja kaikki kansa pyysi häneen ruveta; sillä voima läksi hänestä ja paransi kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 20, 'Ja hän nosti silmänsä opetuslastensa puoleen, ja sanoi: autuaat te vaivaiset; sillä teidän on Jumalan valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 21, 'Autuaat, jotka nyt isootte; sillä teidät ravitaan. Autuaat, jotka nyt itkette; sillä teidän pitää nauraman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 22, 'Autuaat olette te, kuin ihmiset vihaavat teitä, ja eroittavat teidät, ja pilkkaavat teitä, ja hylkäävät teidän nimenne niinkuin kelvottoman, Ihmisen Pojan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 23, 'Iloitkaat sinä päivänä ja riemuitkaat, sillä katso, teidän palkkanne on suuri taivaassa; niin tekivät myös heidän isänsä prophetaille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 24, 'Mutta voi teitä rikkaita! sillä teillä on teidän lohdutuksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 25, 'Voi teitä, jotka ravitut olette! sillä teidän pitää isooman. Voi teitä, jotka nyt nauratte! sillä teidän pitää murehtiman ja itkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 26, 'Voi teitä, kuin kaikki ihmiset teitä kiittävät! sillä niin tekivät myös heidän isänsä väärille prophetoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 27, 'Mutta minä sanon teille, jotka kuulette: rakastakaa vihollisianne: tehkäät hyvää niille, jotka teitä vihaavat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 28, 'Siunatkaat niitä, jotka teitä kiroilevat: rukoilkaat niiden edestä, jotka teitä vahingoittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 29, 'Ja joka sinua lyö poskelle, taritse myös hänelle toinen, ja joka sinulta vie kaapun, älä myös häneltä kiellä hametta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 30, 'Vaan anna jokaiselle, joka sinulta anoo, ja siltä, joka sinun omas ottaa, älä jälleen ano.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 31, 'Ja niinkuin te tahdotte, että ihmisten pitää teille tekemän, niin tehkäät te heillekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 32, 'Ja jos te rakastatte niitä, jotka teitä rakastavat, mikä kiitos teille siitä on? sillä syntisetkin rakastavat niitä, joilta he rakastetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 33, 'Ja jos te teette hyvää hyväntekijöillenne, mikä kiitos teillä siinä on? sillä syntiset sen myös tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 34, 'Ja jos te lainaatte niille, joilta te toivotte jälleen saavanne, mikä kiitos teillä siitä on? sillä syntisetkin lainaavat syntisille, että he tasan jälleen saisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 35, 'Kuitenkin rakastakaat teidän vihollisianne ja tehkäät hyvää, ja lainatkaat, ja älkäät mitään siitä toivoko: niin teidän palkkanne on suuri, ja teidän pitää oleman Ylimmäisen pojat; sillä hän on laupias kiittämättömiä ja pahoja kohtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 36, 'Olkaat sentähden laupiaat, niinkuin teidän Isännekin laupias on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 37, 'Älkäät tuomitko, ettei teitä tuomittaisi: älkäät sadatelko, ettei teitä sadateltaisi: anteeksi antakaat, niin teille anteeksi annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 38, 'Antakaat, ja teille annetaan: hyvän mitan, likistetyn ja sullotun, ja ylitsevuotavan he antavat teidän helmaanne; sillä juuri sillä mitalla, jolla te mittaatte, pitää teille jälleen mitattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 39, 'Mutta hän sanoi heille vertauksen: taitaako sokia sokiaa taluttaa? eikö he molemmat hautaan lankee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 40, 'Ei ole opetuslapsi ylitse mestarinsa, mutta jokainen on täydellinen, kuin hän on niinkuin hänen mestarinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 41, 'Mutta kuinkas näet raiskan, joka on veljes silmässä, vaan et havaitse malkaa, joka on omassa silmässäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 42, 'Eli kuinkas taidat sanoa veljelles: veljeni, pidä, minä otan raiskan, joka on silmässäs, ja et itse näe malkaa, joka on omassa silmässäs? Sinä ulkokullattu, ota ensin malka omasta silmästäs, ja katso sitte, jos taidat ottaa raiskan, joka on veljes silmässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 43, 'Sillä ei ole se hyvä puu, joka tekee pahan hedelmän, eikä paha puu, joka tekee hyvän hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 44, 'Sillä jokainen puu tunnetaan hedelmästänsä; sillä ei orjantappuroista koota fikunia, eikä ohdakkeista haeta viinamarjoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 45, 'Hyvä ihminen tuottaa edes sydämensä hyvästä tavarasta hyvää, ja paha ihminen sydämensä pahasta tavarasta tuottaa edes pahaa. Sillä sydämen kyllyydestä hänen suunsa puhuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 46, 'Mitä te siis minua kutsutte Herra, Herra! ja ette tee, mitä minä sanon?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 47, 'Kuka ikänä tulee minun tyköni, ja kuulee minun sanani, ja tekee ne, sen minä osoitan teille, kenen kaltainen hän on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 48, 'Hän on sen ihmisen kaltainen, joka huoneensa rakensi, ja kaivoi syvään, ja pani perustuksen kallion päälle. Kuin siis vuo tuli, sysäsi virta sitä huonetta, ja ei voinut häntä liikuttaa; sillä se oli perustettu kallion päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 49, 'Mutta joka kuulee ja ei tee, se on sen ihmisen kaltainen, joka huoneensa rakensi maan päälle ilman perustusta, jota virta sysäsi, ja se kohta kukistui: jonka huoneen lankeemus oli suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 1, 'Mutta kuin hän kansan kuullen oli päättänyt kaikki sanansa, meni hän Kapernaumiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 2, 'Ja yhden sadanpäämiehen palvelia sairasti kuolemallansa, josta hän paljon piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 3, 'Kuin hän siis Jesuksesta kuuli, lähetti hän Juudalaisten vanhimmat hänen tykönsä rukoilemaan häntä, että hän tulis ja parantais hänen palveliansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 4, 'Kuin he tulivat Jesuksen tykö, rukoilivat he häntä hartaasti ja sanoivat: hän on mahdollinen, ettäs hänelle sen teet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 5, 'Sillä hän rakastaa meidän kansaamme ja rakensi meille synagogan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 6, 'Niin Jesus meni heidän kanssansa. Ja kuin ei hän silleen ollut kaukana huoneesta, lähetti sadanpäämies ystäviänsä hänen tykönsä, sanoen hänelle: Herra, älä vaivaa sinuas; sillä en ole minä mahdollinen, ettäs minun kattoni alle tulisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 7, 'Sentähden en minä myös itsiäni lukenut mahdolliseksi tuleman sinun tykös; mutta sano sanalla, niin minun palveliani paranee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 8, 'Sillä minä olen myös ihminen vallan alle asetettu, ja minun allani on sotamiehiä, ja sanon tälle: mene! niin hän menee, ja toiselle: tule! ja hän tulee, ja minun palvelialleni: tee se! ja hän tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 9, 'Mutta kuin Jesus sen kuuli, ihmetteli hän häntä, kääntyi ja sanoi kansalle, joka häntä seurasi: minä sanon teille: en ole minä Israelissa senkaltaista uskoa löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 10, 'Ja kuin ne, jotka lähetetyt olivat, kotia palasivat, löysivät he palvelian terveenä, joka sairastanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 11, 'Ja tapahtui sen jälkeen, että hän meni kaupunkiin, joka Nain kutsutaan, ja hänen kanssansa meni monta hänen opetuslastansa ja paljo väkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 12, 'Mutta kuin hän kaupungin porttia lähestyi, katso, kuollut kannettiin ulos, joka oli äitinsä ainoa poika, ja se oli leski. Ja paljo kaupungin kansasta kävi hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 13, 'Kuin Herra hänen näki, armahti hän hänen päällensä ja sanoi hänelle: älä itke!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 14, 'Ja meni ja rupesi paariin (ja kantajat seisahtivat,) ja hän sanoi: nuorukainen, minä sanon sinulle: nouse ylös!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 15, 'Ja kuollut nousi istualle ja rupesi puhumaan. Ja hän antoi sen äidillensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 16, 'Ja pelko tuli kaikille, ja kunnioittivat Jumalaa, sanoen: suuri propheta on noussut meidän sekaamme, ja Jumala on kansaansa etsinyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 17, 'Ja tämä sanoma kuului hänestä kaikkeen Juudeaan ja kaiken sen lähimaakunnan ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 18, 'Ja Johannekselle ilmoittivat hänen opetuslapsensa näistä kaikista. Ja Johannes kutsui tykönsä kaksi opetuslastansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 19, 'Ja lähetti Jesuksen tykö, sanoen: oletko se tuleva, eli pitääkö meidän toista odottaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 20, 'Kuin nämät miehet tulivat hänen tykönsä, sanoivat he: Johannes Kastaja lähetti meidät sinun tykös, sanoen: oletkos sinä se tuleva, eli pitääkö meidän toista odottaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 21, 'Sillä hetkellä paransi hän monta taudeista ja vitsauksista ja pahoista hengistä, ja antoi monelle sokialle näön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 22, 'Ja Jesus vastasi ja sanoi heille: menkäät ja sanokaat jälleen Johannekselle, mitä te nähneet ja kuulleet olette: sokiat saavat näkönsä, ontuvat käyvät, spitaliset puhdistetaan, kuurot kuulevat, kuolleet herätetään, köyhille saarnataan evankeliumi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 23, 'Ja autuas on se, joka ei pahene minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 24, 'Ja kuin Johanneksen sanansaattajat menivät pois, rupes hän sanomaan Johanneksesta kansalle: mitä te läksitte korpeen katsomaan? ruokoako, joka tuulelta häälytetään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 25, 'Eli mitä te läksitte katsomaan? ihmistäkö, pehmeisiin vaatteisiin puettua? Katso, ne jotka koreissa vaatteissa ovat ja herkullisesti elävät, ovat kuninkaallisissa kartanoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 26, 'Taikka mitä te menitte katsomaan? prophetaako? minä sanon teille: ja enempi kuin propheta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 27, 'Tämä on se, josta kirjoitettu on: katso, minä lähetän minun enkelini sinun kasvois eteen, valmistamaan sinun tietäs sinun etees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 28, 'Sillä minä sanon teille: niiden seassa, jotka vaimoista syntyneet ovat, ei ole yhtään suurempaa prophetaa kuin Johannes Kastaja: kuitenkin se, joka vähempi on Jumalan valtakunnassa, on suurempi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 29, 'Ja kaikki kansa, joka hänen kuuli, ja Publikanit antoivat Jumalalle oikeuden ja kastettiin Johanneksen kasteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 30, 'Mutta Pharisealaiset ja lainoppineet katsoivat ylön Jumalan neuvon itseänsä kohtaan, ja ei heitä kastettu häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 31, 'Niin Herra sanoi: keneen siis minä tämän sukukunnan ihmiset vertaan? Ja kenenkä kaltaiset he ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 32, 'Ne ovat niiden lasten kaltaiset, jotka turulla istuvat ja huutavat toinen toisellensa ja sanovat: me olemme huilua soittaneet teidän edessänne, ja ette hypänneet: me olemme teille veisanneet murhevirsiä, ja ette itkeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 33, 'Sillä Johannes Kastaja tuli, ja ei syönyt leipää eikä juonut viinaa, ja te sanotte: hänellä on perkele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 34, 'Ihmisen Poika on tullut, syö ja juo, ja te sanotte: katso ihmistä, syömäriä ja viinan juomaria, Publikanien ja syntisten ystävää:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 35, 'Ja viisaus on vanhurskautettu kaikilta hänen lapsiltansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 36, 'Niin yksi Pharisealaisista rukoili häntä ruualle kanssansa. Ja hän meni Phariseuksen huoneeseen ja aterioitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 37, 'Ja katso, yksi vaimo oli kaupungissa, joka oli syntinen, ja kuin hän sai kuulla, että hän aterioitsi Pharisealaisen huoneessa, toi hän lasin kallista voidetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 38, 'Ja seisoi takana hänen jalkainsa juuressa itkien, ja rupesi kyyneleillänsä kastamaan hänen jalkojansa, ja niitä päänsä hiuksilla kuivasi, ja suuta antoi hänen jalkainsa, ja voiteli ne voiteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 39, 'Mutta kuin Pharisealainen sen näki, joka hänen kutsunut oli, sanoi hän itsellensä: jos tämä olis propheta, niin hän tietäis, mikä ja millainen tämä vaimo on, joka häneen rupee, että hän on syntinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 40, 'Ja Jesus vastaten sanoi hänelle: Simon, minulla on jotakin sinulle sanomista. Hän sanoi: Mestari, sanos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 41, 'Kaksi velkamiestä oli yhdellä lainaajalla: yksi oli velkaa viisisataa penninkiä ja toinen viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 42, 'Koska ei heillä ollut varaa maksaa, antoi hän molempain anteeksi. Sano siis, kumpi näistä häntä enemmän rakastaman pitää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 43, 'Simon vastaten sanoi: minä luulen, että se, jolle hän enemmän anteeksi antoi; hän sanoi: oikein sinä tuomitsit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 44, 'Ja hän käänsi itsensä vaimoa päin, ja sanoi Simonille: näetkös tämän vaimon? minä tulin sinun huoneeses, etkä sinä antanut vettä minun jaloilleni; mutta tämä kyynelillä kasti minun jalkani ja ne hiuksillansa kuivasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 45, 'Et sinä minun suuta antanut, mutta tämä, sittenkuin hän tähän tuli, ei ole lakannut minun jalkaini suuta antamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 46, 'Et sinä minun päätäni öljyllä voidellut; mutta tämä voiteella minun jalkani voiteli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 47, 'Minä sanon sinulle: sentähden että hänelle paljo syntiä anteeksi annettiin, niin hän paljon rakasti; mutta jolle vähempi anteeksi annetaan, se vähemmän rakastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 48, 'Niin hän sanoi hänelle: sinun syntis ovat anteeksi annetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 49, 'Niin rupesivat ne, jotka myös aterioitsivat, sanomaan keskenänsä: kuka tämä on, joka synnitkin anteeksi antaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 50, 'Niin hän sanoi vaimolle: sinun uskos on sinun vapaaksi tehnyt: mene rauhaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 1, 'Ja sitte tapahtui, että hän vaelsi lävitse kaupungeita ja kyliä saarnaten ja ilmoittain evankeliumia Jumalan valtakunnasta, ja ne kaksitoistakymmentä hänen kanssansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 2, 'Ja muutamat vaimot, jotka olivat parannetut pahoista hengistä ja taudeista, nimittäin: Maria, joka kutsuttiin Magdalena, josta seitsemän perkelettä oli lähtenyt ulos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 3, 'Ja Johanna, Kusaan, Herodeksen voudin emäntä, ja Susanna ja monta muuta, jotka tavarastansa häntä palvelivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 4, 'Mutta kuin paljo kansaa kokoontui, ja he riensivät jokaisesta kaupungista hänen tykönsä, sanoi hän vertauksella:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 5, 'Kylväjä meni ulos siementänsä kylvämään; ja kuin hän kylvi, lankesi muutama tien oheen, ja se tallattiin, ja taivaan linnut söivät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 6, 'Ja muutama lankesi kivistöön, ja kuin se tuli ylös, kuivettui se, ettei ollut märkyyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 7, 'Ja muutama lankesi orjantappuroihin, ja orjantappurat ynnä kävivät ylös ja tukahduttivat sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 8, 'Ja muutama lankesi hyvään maahan, ja kuin se kävi ylös, teki se satakertaisen hedelmän. Kuin hän tämän sanoi, huusi hän: jolla on korvat kuulla, se kuulkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 9, 'Niin hänen opetuslapsensa kysyivät häneltä, sanoen: mikä olis tämä vertaus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 10, 'Niin hän sanoi: teille on annettu tuta Jumalan valtakunnan salaudet, mutta muille vertausten kautta, ettei heidän sitä pitäis näkemän, vaikka näkisivät, eikä ymmärtämän, vaikka he kuulisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 11, 'Mutta tämä on vertaus: siemen on Jumalan sana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 12, 'Mutta jotka tien oheen, ovat ne, jotka kuulevat; sitte tulee perkele ja ottaa sanan heidän sydämestänsä, ettei he uskoisi ja vapaaksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 13, 'Mutta jotka kivistöön, ovat ne, kuin he kuulevat, ottavat he sanan ilolla vastaan; ja ei heillä ole juurta, hetkeksi he uskovat, ja kiusauksen ajalla lankeevat pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 14, 'Mutta se mikä orjantappuroihin lankesi, ovat ne, jotka kuulevat, ja menevät pois, ja tukahutetaan surusta, rikkaudesta ja elämän hekumasta, eikä kanna hedelmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 15, 'Mutta jotka hyvään maahan, ovat ne, jotka sanan kuulevat ja kätkevät hyvällä ja toimellisella sydämellä, ja saattavat hedelmän kärsivällisyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 16, 'Niin ei kenkään, joka kynttilän sytyttää, peitä sitä astialla eli pane pöydän alle; mutta panee sen kynttilänjalkaan, että sisälle tulevaiset näkisivät valkeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 17, 'Sillä ei ole mitään salattu, joka ei ilmi tule, eikä peitetty, joka ei tiettäväksi ja julki tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 18, 'Katsokaat siis, kuinka te kuulette; sillä jolla on, hänelle pitää annettaman: jolla taas ei ole, sekin kuin hänellä näkyy olevan, otetaan häneltä pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 19, 'Niin tulivat hänen äitinsä ja veljensä hänen tykönsä, eikä saaneet häntä puhutella kansalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 20, 'Ja se ilmoitettiin hänelle, sanoen: sinun äitis ja veljes seisovat ulkona ja tahtovat sinua nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 21, 'Niin hän vastasi ja sanoi heille: minun äitini ja veljeni ovat ne, jotka Jumalan sanan kuulevat ja tekevät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 22, 'Ja yhtenä päivänä tapahtui, että hän haahteen astui ja hänen opetuslapsensa, ja sanoi heille: menkäämme ylitse toiselle rannalle, ja he menivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 23, 'Mutta kuin he purjehtivat, niin hän nukkui, ja tuulispää nosti aallon meressä; ja he laineilta täytettiin, ja olivat suuressa hädässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 24, 'Niin he menivät ja herättivät häntä sanoen: Mestari, Mestari! me hukumme. Niin hän nousi ylös, nuhteli tuulta ja veden aaltoa; ja ne lakkasivat, ja tuli tyveneksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 25, 'Niin hän sanoi heille: kussa teidän uskonne on? Mutta he peljästyivät ja ihmettelivät, sanoen keskenänsä: kuka siis tämä on? sillä hän käskee myös tuulta ja vettä, ja nekin ovat hänelle kuuliaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 26, 'Ja he purjehtivat Gadaralaisten maan puoleen, ja joka on Galilean kohdalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 27, 'Ja kuin hän maalle meni, kohtasi hänen kaupungista mies, jolla olivat perkeleet jo kauvan aikaa olleet, ja joka ei pukenut vaatteita yllensä, eikä ollut huoneessa, vaan haudoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 28, 'Mutta kuin hän näki Jesuksen, huusi hän ja lankesi hänen eteensä maahan, ja sanoi suurella äänellä: mitä minun on sinun kanssas, Jesus, ylimmäisen Jumalan Poika? Minä rukoilen sinua, älä minua vaivaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 29, 'Sillä hän oli käskenyt riettaisen hengen ihmisestä mennä ulos, joka kauvan aikaa oli häntä vaivannut: ja hän oli kahleilla sidottu, ja jalkaraudoissa pidetty, ja rikkoi siteet, ja vietiin perkeleeltä korpeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 30, 'Mutta Jesus kysyi häneltä ja sanoi: mikä sinun nimes on? hän sanoi: legio; sillä monta perkelettä oli häneen mennyt sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 31, 'Ja he rukoilivat häntä, ettei hän käskisi heitä syvyyteen mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 32, 'Niin siellä oli suuri lauma sikoja syömässä vuorella. Ja he rukoilivat häntä, että hän sallis heidän niihin mennä. Ja hän salli heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 33, 'Niin perkeleet läksivät ulos ihmisestä ja menivät sikoihin, ja lauma syöksi itsensä äkisti jyrkältä mereen ja läkähtyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 34, 'Mutta kuin paimenet näkivät, mitä tapahtui, pakenivat he, menivät pois ja ilmoittivat sen kaupungissa ja kylissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 35, 'Niin he menivät ulos katsomaan sitä, mikä tapahtunut oli, ja tulivat Jesuksen tykö, ja löysivät sen ihmisen, josta perkeleet lähteneet olivat, istuvan vaatetettuna ja taidossansa Jesuksen jalkain juuressa; ja he pelkäsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 36, 'Mutta myös ne, jotka sen nähneet olivat, ilmoittivat heille, kuinka se perkeleeltä riivattu oli terveeksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 37, 'Ja kaikki Gadaralaiset lähimaakunnan joukko rukoili häntä menemään pois heidän tyköänsä; sillä heidän päällensä oli tullut suuri pelko. Niin hän meni haahteen ja tuli jälleen takaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 38, 'Mutta mies, josta perkeleet olivat lähteneet ulos, rukoili häntä, että hän sais olla hänen kanssansa. Mutta Jesus laski hänen pois, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 39, 'Palaja kotias ja ilmoita, kuinka suuret työt Jumala sinulle teki. Ja hän meni pois ja saarnasi ympäri kaiken kaupungin, kuinka suuret työt Jesus hänelle teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 40, 'Ja tapahtui, kuin Jesus palasi, otti kansa hänen vastaan; sillä kaikki odottivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 41, 'Ja katso, mies tuli, jonka nimi oli Jairus, ja se oli synagogan päämies, ja lankesi Jesuksen jalkain juureen ja rukoili häntä tulemaan huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 42, 'Sillä hänellä oli ainoa tytär, lähes kahdentoistakymmenen vuotinen, ja se kuoli. Mutta hänen mennessänsä ahdisti kansa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 43, 'Ja yksi vaimo, joka oli punaista tautia kaksitoistakymmentä vuotta sairastanut, ja oli kaiken saatunsa parantajille kuluttanut, ja ei voitu keltään parannettaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 44, 'Mutta kuin hän kävi takana ja rupesi hänen vaatteensa palteesen, niin kohta hänen verensä juoksu asettui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 45, 'Ja Jesus sanoi: kuka on se, joka minuun rupesi? Mutta kuin he kaikki kielsivät, sanoi Pietari ja ne, jotka hänen kanssansa olivat: Mestari, kansa ahdistaa ja tunkee sinua, ja sinä sanot: kuka minuun rupesi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 46, 'Mutta Jesus sanoi: joku minuun rupesi, sillä minä tunsin voiman minusta lähteneen ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 47, 'Mutta kuin vaimo näki, ettei se salaa ollut, tuli hän vapisten, ja maahan lankesi hänen eteensä, ja julisti kaikelle kansalle, minkä syyn tähden hän oli häneen ruvennut, ja kuinka hän niin äkisti terveeksi tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 48, 'Mutta hän sanoi hänelle: ole hyvässä turvassa, tyttäreni, sinun uskos on sinua auttanut: mene rauhaan!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 49, 'Kuin hän vielä puhui, tuli yksi synagogan päämiehiltä, sanoen hänelle: sinun tyttäres on kuollut: älä Mestaria vaivaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 50, 'Vaan kuin Jesus sen kuuli, vastasi hän häntä, sanoen: älä pelkää: usko ainoastaan, niin hän paranee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 51, 'Mutta kuin hän huoneesen tuli sisälle; niin ei hän sallinut ketään tulla sisälle, vaan Pietarin ja Jakobin ja Johanneksen, ja sen lapsen isän ja äidin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 52, 'Ja he kaikki itkivät ja parkuivat häntä. Vaan hän sanoi: älkäät itkekö: ei hän ole kuollut, vaan makaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 53, 'Ja he nauroivat häntä, tietäen, että se kuollut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 54, 'Niin hän ajoi kaikki ulos, rupesi hänen käteensä ja huusi, sanoen: piikainen, nouse ylös!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 55, 'Ja hänen henkensä palasi, ja hän kohta nousi ylös. Ja käski hänelle antaa ruokaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 56, 'Ja hänen vanhempansa hämmästyivät: mutta hän haastoi heitä kellekään sanomasta sitä mikä tapahtui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 1, 'Mutta hän kutsui kokoon kaksitoistakymmentä opetuslastansa, ja antoi heille voiman ja vallan kaikkein perkeleiden ylitse, ja taudit parantaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 2, 'Ja lähetti heitä saarnaamaan Jumalan valtakuntaa ja parantamaan sairaita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 3, 'Ja sanoi heille: älkäät ottako mitään myötänne tielle, ei sauvoja, eikä myös säkkiä, eikä leipää, eikä rahaa: älkää myös kahta hametta pitäkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 4, 'Ja johon huoneesen te tulette sisälle, siinä te olkaat ja siitä lähtekäät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 5, 'Ja kuka ikänä ei teitä ota vastaan, niin menkäät pois siitä kaupungista ja puhdistakaat tomu teidän jaloistanne, todistukseksi heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 6, 'Ja he menivät ulos ja vaelsivat kylissä, saarnaten evankeliumia, ja paransivat joka paikassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 7, 'Mutta Herodes tetrarka kuuli kaikki, mitä häneltä tehty oli, ja hän epäili, että muutamat sanoivat Johanneksen nousseeksi kuolleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 8, 'Muutamat taas Eliaan ilmaantuneen, ja muut, että joku prophetaista oli noussut ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 9, 'Ja Herodes sanoi: Johanneksen kaulan minä leikkasin; vaan kuka tämä lienee, josta minä senkaltaisia kuulen? Ja hän pyysi nähdä häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 10, 'Ja apostolit palasivat, ja juttelivat hänelle kaikki, mitä he olivat tehneet. Ja hän otti heidät tykönsä ja meni erinänsä Betsaidan kaupungin erämaahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 11, 'Kuin kansa sen ymmärsi, seurasivat he häntä, ja hän otti heitä vastaan, ja puhui heille Jumalan valtakunnasta, ja jotka parannusta tarvitsivat, teki hän terveeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 12, 'Mutta päivä rupesi jo laskemaan ja ne kaksitoistakymmentä tulivat ja sanoivat hänelle: päästä kansa menemään lähikyliin ja majoihin poikkeamaan, ruokaa saamaan; sillä me olemme täällä erämaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 13, 'Niin hän sanoi heille: antakaat te heille syötävää; mutta he sanoivat: ei meillä enempi ole kuin viisi leipää ja kaksi kalaa, ellemme mene ja osta ruokaa kaikelle tälle kansalle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 14, 'Sillä heitä oli lähes viisituhatta miestä. Niin hän sanoi opetuslapsillensa: pankaat heitä istumaan kuhunkin joukkoon viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 15, 'Ja he tekivät niin ja asettivat heidät kaikki aterioitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 16, 'Niin hän otti ne viisi leipää ja kaksi kalaa, ja katsoi taivaasen ja siunasi niitä, ja mursi ja antoi opetuslapsille panna kansan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 17, 'Ja he söivät kaikki ja ravittiin; ja koottiin tähteitä, jotka jäi, kaksitoistakymmentä koria muruja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 18, 'Ja tapahtui, kuin hän yksinänsä rukoilemassa oli, olivat myös opetuslapset hänen kanssansa, ja hän kysyi heiltä, sanoen: kenenkä sanoo kansa minun olevan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 19, 'Mutta ha vastasivat ja sanoivat: Johannes Kastajan, ja muutamat Eliaan, muutamat taas jonkun vanhoista prophetaista nousseen ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 20, 'Niin hän sanoi heille: kenenkäs te sanotte minun olevan? Vastasi Pietari ja sanoi: sinä olet Jumalan Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 21, 'Ja hän haastoi heitä, ja kielsi heidät kellekään sitä sanomasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 22, 'Ja sanoi: Ihmisen Pojan pitää paljo kärsimän, ja hyljättämän vanhimmita ja pappein päämiehiltä ja kirjanoppineilta, ja tapettaman, ja kolmantena päivänä hän on nouseva ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 23, 'Niin hän sanoi kaikille: jos joku tahtoo minun perässäni tulla, hän kieltäkään itsensä, ja ottakaan ristinsä joka päivä, ja seuratkaan minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 24, 'Sillä joka henkensä tähdellä pitää tahtoo, hänen pitää sen kadottaman; mutta joka henkensä kadottaa minun tähteni, hän pitää sen tallella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 25, 'Sillä mitä se hyödyttää ihmistä, jos hän kaiken maailman voittais, ja itsensä kadottais, eli vahinkoon saattais?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 26, 'Sillä kuka ikänä minua häpee ja minun sanojani, sitä Ihmisen Pojan pitää häpeemän, kuin hän ole tuleva hänen ja Isän ja pyhäin enkelien kunniassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 27, 'Mutta minä totisesti sanon teille: muutamat ovat, jotka tässä seisovat, jotka ei maista kuolemaa, siihen asti kuin he näkevät Jumalan valtakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 28, 'Ja tapahtui kahdeksan päivän perästä näiden sanain jälkeen, että hän otti tykönsä Pietarin ja Johanneksen ja Jakobin, ja meni ylös vuorelle rukoilemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 29, 'Ja kuin hän rukoile, muuttui hänen kasvonsa ja hänen vaatteensa tulivat valkiaksi ja kiiltäväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 30, 'Ja katso, kaksi miestä puhui hänen kanssansa, jotka olivat Moses ja Elias,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 31, 'Jotka näkyivät kunniassa ja ja puhuivat hänen menostansa, jonka hän täyttävä oli Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 32, 'Mutta Pietari ja jotka hänen kanssansa olivat, olivat unesta raskautetut; mutta koska he heräsivät, näkivät he hänen kunniansa ja ne kaksi miestä, jotka seisoivat hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 33, 'Ja tapahtui, kuin he läksivät hänen tyköänsä, sanoi Pietari Jesukselle: Mestari, hyvä on meidän tässä olla, tehkäämme tähän kolme majaa, sinulle yhden, Mosekselle yhden ja Eliaalle yhden; eikä tietänyt, mitä sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 34, 'Ja hänen näitä puhuissansa, tuli pilvi ja varjosi ympäri heidät; mutta he peljästyivät, koska tulivat pilven sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 35, 'Ja ääni tuli pilvestä, sanoen: tämä on minun rakas Poikani, kuulkaat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 36, 'Ja kuin ääni parhaallansa kuului, löysivät he Jesuksen yksin. Ja he vaikenivat, eikä mitään kellenkään niinä päivinä jutelleet niistä, mitkä he nähneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 37, 'Mutta tapahtui toisena päivänä, kuin he menivät alas vuorelta, kohtasi heitä paljo väkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 38, 'Ja katso, yksi mies huusi kansasta, sanoen: Mestari! minä rukoilen sinua, katso minun poikani puoleen; sillä hän on minulle ainokainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 39, 'Ja katso, henki ottaa hänen, ja hän huutaa kohta, ja se repii häntä, niin että hän vaahtuu, ja se luopuu tuskalla hänestä, kuin hän häntä runtelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 40, 'Ja minä rukoilin sinun opetuslapsias häntä ajamaan ulos, mutta ei he voineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 41, 'Niin Jesus vastasi ja sanoi: oi uskomatoin ja nurja sukukunta! kuinka kauvan minun pitää teidän tykönänne oleman ja teitä kärsimän? Tuo poikas tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 42, 'Ja kuin hän vielä tulossa oli, repeli häntä perkele ja muserteli; mutta Jesus nuhteli rietasta henkeä, ja paransi pojan, ja antoi hänen jälleen isällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 43, 'Niin he kaikki hämmästyivät Jumalan kunniallista voimaa. Mutta koska kaikki ihmettelivät kaikkia niitä, mitä Jesus teki, sanoi hän opetuslapsillensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 44, 'Pankaat te nämät puheet korviinne; sillä tuleva on, että Ihmisen Poika annetaan ylön ihmisten käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 45, 'Mutta ei he ymmärtäneet sitä sanaa, ja se oli heiltä peitetty, niin ettei he sitä ymmärtäneet; ja he pelkäsivät kysyä sitä sanaa häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 46, 'Niin tuli myös kamppaus heidän keskenänsä, kuka heistä suurin olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 47, 'Kuin Jesus näki heidän sydämensä ajatuksen, otti hän lapsen ja asetti tykönsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 48, 'Ja sanoi heille: kuka ikänä tämän poikaisen ottaa vastaan minun nimeeni, hän ottaa vastaan minun; ja kuka ikänä minun ottaa vastaan, hän ottaa vastaan sen, joka minun lähetti. Sillä joka vähin on teidän keskenänne, se pitää oleman suurin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 49, 'Niin Johannes vastasi ja sanoi: Mestari! me näimme yhden sinun nimes kautta perkeleitä ajavan ulos, ja me kielsimme häntä; sillä ei hän seuraa meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 50, 'Ja Jesus sanoi hänelle: älkäät kieltäkö; sillä joka ei ole meitä vastaan, hän on meidän puolestamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 51, 'Mutta tapahtui, kuin aika täytetty oli, että hän piti täältä otettaman ylös, käänsi hän kasvonsa menemään Jerusalemin puoleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 52, 'Ja lähetti sanansaattajat edellänsä, ja he menivät yhteen Samarialaisten kylään, majaa hänelle valmistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 53, 'Ja ei ne häntä ottaneet vastaan, että hänen kasvonsa oli käännetty menemään Jerusalemia päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 54, 'Mutta kuin hänen opetuslapsensa Jakob ja Johannes sen näkivät, sanoivat he: Herra, tahdotkos, niin me sanomme, että tuli tulee taivaasta ja kadottaa heidät, niinkuin Eliaskin teki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 55, 'Mutta Jesus käänsi itsensä ja nuhteli heitä, sanoen: ette tiedä, minkäkaltaisen hengen te olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 56, 'Sillä Ihmisen Poika ei ole tullut kadottamaan ihmisten sieluja, mutta vapahtamaan. Ja he menivät toiseen kylään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 57, 'Ja tapahtui heidän vaeltaissansa, että yksi tiellä sanoi: minä seuraan sinua, kuhunkas ikänä menet, Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 58, 'Ja Jesus sanoi hänelle: ketuilla ovat luolat ja taivaan linnuilla pesät; mutta ei ihmisen Pojalla ole, kuhunka hän päänsä kallistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 59, 'Mutta hän sanoi toiselle: seuraa minua! niin se sanoi: Herra, salli minun ensin mennä hautaamaan isääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 60, 'Niin Jesus sanoi hänelle: anna kuolleet haudata kuolleitansa; mutta mene sinä ja julista Jumalan valtakuntaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 61, 'Ja toinen myös sanoi: Herra, minä seuraan sinua, mutta salli minun ensin mennä hyvästi jättämään niitä, jotka kotonani ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 62, 'Mutta Jesus sanoi hänelle: kuka ikänä kätensä auraan laskee ja taaksensa katsoo, ei se ole sovelias Jumalan valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 1, 'Niin asetti Herra toiset seitsemänkymmentä, ja lähetti heitä kaksin ja kaksin edellänsä joka kaupunkiin ja paikkaan, kuhunka hän itse oli tuleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 2, 'Niin hän sanoi heille: eloa tosin on paljo, vaan työväkeä on vähä: rukoilkaat siis elon Herraa, työväkeä lähettämään eloonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 3, 'Menkäät: katso, minä lähetän teidät niinkuin karitsat sutten keskelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 4, 'Älkäät ottako säkkiä, eikä kukkaroa, eikä kenkiä, ja älkäät ketään tervehtikö tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 5, 'Mutta kuhunka huoneesen te menette sisälle, niin sanokaat ensisti: rauha olkoon tälle huoneelle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 6, 'Ja jos siellä on rauhan lapsi, niin teidän rauhanne jää hänen päällensä; mutta jos ei, niin se palajaa teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 7, 'Mutta siinä huoneessa viipykäät, syökäät ja juokaat sitä, mitä heillä on; sillä työmies on palkkansa ansiollinen. Älkäät huoneesta huoneeseen käykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 8, 'Mutta kuhunka kaupunkiin te tulette sisälle, ja he teitä ottavat vastaan, niin syökäät mitä teidän eteenne pannaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 9, 'Ja parantakaat sairaita, joita siinä on, ja sanokaat heille: Jumalan valtakunta on teitä lähestynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 10, 'Mutta kuhunka kaupunkiin te tulette sisälle, ja ei he teitä ota vastaan, niin menkäät ulos sen kaduille, ja sanokaat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 11, 'Tomunkin, joka teidän kaupungistanne tarttui meihin, me pudistamme teille: kuitenkin se tietäkäät, että Jumalan valtakunta oli teitä lähestynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 12, 'Minä sanon teille: Sodomalle pitää sinä päivänä huokiampi oleman kuin sille kaupungille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 13, 'Voi sinua Koratsin! voi sinua Betsaida! sillä jos Tyrossa ja Sidonissa olisivat senkaltaiset voimalliset työt tehdyt kuin teidän tykönänne ovat tehdyt, niin he olisivat jo aikaa säkissä ja tuhassa istuneet ja parannuksen tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 14, 'Kuitenkin Tyrolle ja Sidonille pitää huokiampi tuomiolle oleman kuin teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 15, 'Ja sinä Kapernaum, joka olet taivaasen asti korotettu, sinä pitää hamaan helvettiin alas sysättämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 16, 'Joka teitä kuulee, se minua kuulee, ja joka teidät katsoo ylön, se katsoo ylön minun; mutta joka minun katsoo ylön, hän katsoo ylön sen, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 17, 'Niin ne seitsemänkymmentä palasivat ilolla, sanoen: Herra, perkeleetkin ovat sinun nimes kautta meidän allemme annetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 18, 'Niin hän sanoi heille: minä näin saatanan taivaasta lankeevan niinkuin pitkäisen tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 19, 'Katso, minä annan teille vallan tallata käärmeitä ja skorpioneja ja kaikkea vihollisen voimaa, ja ei teitä mikään ole vahingoitseva,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 20, 'Kuitenkin älkäät siitä iloitko, että henget teidän allenne annetaan; vaan iloitkaat paremmin, että teidän nimenne ovat kirjoitetut taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 21, 'Sillä hetkellä riemuitsi Jesus hengessä ja sanoi: minä kiitän sinua, Isä, taivaan ja maan Herra, ettäs nämät salasit viisailta ja toimellisilta, ja olet ne ilmoittanut pienille: tosin, Isä, niin oli sinun hyvä tahtos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 22, 'Kaikki ovat minulle annetut Isältäni: ja ei tiedä kenkään, kuka on Poika, vaan Isä: ja kuka on Isä, vaan Poika ja kelle Poika tahtoo ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 23, 'Ja hän kääntyi opetuslastensa puoleen erinänsä, ja sanoi: autuaat ovat ne silmät, jotka näkevät, joita te näette:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 24, 'Sillä minä sanon teille: monta prophetaa ja kuningasta tahtoivat nähdä, joita te näette, ja ei nähneet, ja kuulla, joita te kuulette, ja ei kuulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 25, 'Ja katso, yksi lainoppinut nousi ja kiusasi häntä, sanoen: Mestari, mitä minun pitää tekemän, että minä ijankaikkisen elämän perisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 26, 'Mutta hän sanoi hänelle: mitä laissa on kirjoitettu? kuinkas luet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 27, 'Ja hän vastasi ja sanoi: sinun pitää rakastaman Herraa sinun Jumalaas kaikesta sinun sydämestäs, ja kaikesta sinun sielustas, ja kaikesta sinun voimastas, ja kaikesta sinun mieleltäs: ja sinun lähimmäistäs niinkuin itsiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 28, 'Niin hän sanoi hänelle: oikein sinä vastasit; tee se, niin sinä saat elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 29, 'Mutta hän tahtoi itsensä vanhurskaaksi tehdä ja sanoi Jesukselle: kukas minun lähimmäiseni on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 30, 'Jesus vastasi ja sanoi: yksi ihminen meni alas Jerusalemista Jerikoon, ja tuli ryövärien käsiin, jotka hänen alasti riisuivat ja haavoittivat, menivät pois ja jättivät hänen puolikuolleeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 31, 'Niin tapahtui, että yksi pappi sitä tietä vaelsi, ja kuin hän hänen näki, meni hän ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 32, 'Niin myös Leviläinen, kuin hän tuli sille paikalle, ja näki hänen, ja meni ohitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 33, 'Mutta yksi Samarialainen vaelsi, ja tuli hänen tykönsä, ja kuin hän näki hänen, armahti hän häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 34, 'Ja tuli ja sitoi hänen haavansa ja vuodatti siihen öljyä ja viinaa, ja pani juhtansa päälle, ja vei hänen majaan, ja korjasi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 35, 'Ja toisena päivänä matkusti hän, ja otti kaksi penninkiä ja antoi isännälle, ja sanoi hänelle: korjaa häntä, ja jos sinä enemmän kulutat, niin minä palatessani maksan sinulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 36, 'Kuka siis näistä kolmesta oli sinun nähdäkses hänen lähimmäisensä, joka ryövärien käsiin oli tullut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 37, 'Niin hän sanoi: joka laupiuden teki hänen kohtaansa. Niin sanoi Jesus hänelle: mene ja tee sinä myös niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 38, 'Niin tapahtui, kuin he vaelsivat, meni hän yhteen kylään, ja yksi vaimo, Martta nimeltä, otti hänen huoneesensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 39, 'Ja hänellä oli sisar, joka kutsuttiin Maria, joka myös istui Jesuksen jalkain juureen ja kuulteli hänen puhettansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 40, 'Mutta Martta teki paljon askareita palvellen heitä; hän tuli ja sanoi: Herra, etkös tottele, että minun sisareni jätti minun yksin askaroitsemaan? Sano siis hänelle, että hän minua auttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 41, 'Niin Jesus vastasi ja sanoi hänelle: Martta, Martta, paljon sinä suret ja pyrit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 42, 'Vaan yksi on tarpeellinen: Maria on hyvän osan valinnut, joka ei häneltä pidä otettaman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 1, 'Ja tapahtui, että hän rukoili yhdessä paikassa, ja kuin hän lakkasi, sanoi hänelle yksi hänen opetuslapsistansa: Herra, opeta meitä rukoilemaan, niinkuin Johanneskin opetti opetuslapsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 2, 'Niin hän sanoi heille: kuin te rukoilette, niin sanokaat: Isä meidän, joka olet taivaissa. Pyhitetty olkoon sinun nimes. Lähestyköön sinun valtakuntas. Tapahtukoon sinun tahtos niin maassa, kuin taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 3, 'Anna meille tänäpäivänä meidän jokapäiväinen leipämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 4, 'Ja anna meille meidän syntimme anteeksi, sillä mekin kaikille meidän velvollisillemme anteeksi annamme. Ja älä johdata meitä kiusaukseen. Mutta päästä meitä pahasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 5, 'Ja hän sanoi heille: kellä teistä on ystävä, ja menee puoliyöstä hänen tykönsä, ja sanoo hänelle: ystäväni, lainaas minulle kolme leipää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 6, 'Sillä minun ystäväni tuli matkasta minun tyköni, ja ei minulla ole, mitä minä panen hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 7, 'Ja hän vastaa huoneestansa ja sanoo: älä minua vaivaa! ovi on jo suljettu, ja minun lapseni minun kanssani ovat vuoteessa: en minä voi nousta sinulle antamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 8, 'Minä sanon teille: ellei hän nouse ja anna hänelle, että hän on hänen ystävänsä, niin hän kuitenkin hänen ahkeruutensa tähden nousee ja antaa hänelle niin monta kuin hän tarvitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 9, 'Ja minä myös sanon teille: anokaat, niin teille annetaan: etsikäät, niin te löydätte: kolkuttakaat niin teille avataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 10, 'Sillä jokainen joka anoo, se saa, ja joka etsii, se löytää, ja joka kolkuttaa, sille avataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 11, 'Kuka teistä on isä, jolta poika anoo leipää, antaako hän hänelle kiven? eli jos hän anoo kalaa, antaako hän kalan edestä hänelle kärmeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 12, 'Eli jos hän anoo munaa, antaako hän hänelle skorpionin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 13, 'Jos siis te, jotka pahat olette, taidatte hyviä lahjoja antaa teidän lapsillenne, paljoa enemmin teidän taivaallinen Isänne antaa Pyhän Hengen sitä anovaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 14, 'Ja hän ajoi ulos perkeleen, joka oli mykkä. Ja tapahtui, kuin perkele oli ajettu ulos, niin mykkä puhui ja kansa ihmetteli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 15, 'Mutta muutamat heistä sanoivat: hän ajaa ulos perkeleitä beelsebubin, perkeleiden päämiehen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 16, 'Mutta muut kiusasivat häntä ja anoivat häneltä tunnustähteä taivaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 17, 'Mutta että hän tiesi heidän ajatuksensa, sanoi hän heille: jokainen valtakunta, joka erkanee itsiänsä vastaan, se tulee kylmille, ja huone lankee huoneen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 18, 'Jos myös saatana on erinnyt itsiänsä vastaan, kuinka hänen valtakuntansa on seisovainen? että te sanotte minun perkeleitä belsebubin kautta ajavan ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 19, 'Mutta jos minä perkeleitä belsebubin kautta ajan ulos, kenenkä kautta teidän poikanne niitä ajavat ulos? Sentähden heidän pitää oleman teidän tuomarinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 20, 'Mutta jos minä Jumalan sormella perkeleitä ajan ulos, niin tosin on Jumalan valtakunta teidän tykönne tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 21, 'Kuin väkevä haarniskoitu kotonsa varjelee, niin hänen omansa ovat rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 22, 'Mutta kuin häntä väkevämpi tulee ja voittaa hänen, niin hän ottaa pois kaikki hänen sota-aseensa, joihin hän turvasi, ja jakaa hänen saaliinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 23, 'Joka ei ole minun kanssani, se on minua vastaan, ja joka ei minun kanssani kokoo, hän hajoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 24, 'Kuin rietas henki lähtee ihmisestä, niin hän vaeltaa karkeita paikkoja, ja etsii lepoa; ja kuin ei hän löydä, niin hän sanoo: minä palajan minun huoneeseni, josta minä läksin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 25, 'Ja kuin hän tulee, löytää hän sen luudilla lakaistuksi ja kaunistetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 26, 'Silloin hän menee ja ottaa kanssansa seitsemän muuta häntä pahempaa henkeä, ja kuin he sinne tulevat, asuvat he siellä: ja sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 27, 'Ja tapahtui, kuin hän näitä sanoi, korotti yksi vaimo kansan seasta äänensä ja sanoi: autuas on se kohtu, joka sinun kantanut on, ja ne nisät, joitas imit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 28, 'Niin hän sanoi: ja tosin, autuaat ovat ne, jotka kuulevat Jumalan sanan ja kätkevät sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 29, 'Mutta kuin kansa kokoon tuli, rupesi hän sanomaan: tämä sukukunta on paha, etsii merkkiä, ja ei hänelle anneta merkkiä, vaan Jonan prophetan merkki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 30, 'Sillä niinkuin Jona oli Niniveläisille merkiksi, niin pitää myös Ihmisen Poika oleman tälle sukukunnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 31, 'Etelän kuningatar pitää nouseman tuomiolle tämän sukukunnan miesten kanssa, ja heitä tuomitseman: sillä hän oli maan ääristä kuuleman Salomonin viisautta, ja katso, tässä on enempi kuin Salomon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 32, 'Niniven miehet pitää tuleman tuomiolle tämän sukukunnan kanssa, ja sen kadottaman; sillä he tekivät parannuksen Jonan saarnasta, ja katso tässä on enempi kuin Jona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 33, 'Ei sytytä kenkään kynttilää ja pane kätköön eikä vakan alle, mutta kynttiläjalkaan, että sisälle tulevaiset valkeuden näkisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 34, 'Silmä on ruumiin valkeus: kuin siis sinun silmäs on yksinkertainen, niin myös koko sinun ruumiis on valaistu; mutta kuin se paha on, niin myös sinun ruumiis on pimiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 35, 'Katso siis, ettei se valkeus, joka sinussa on, olisi pimeys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 36, 'Sentähden jos koko sinun ruumiis on valaistu, ja ei ole siinä yhtään pimiää paikkaa, niin se tulee kokonansa valaistuksi, koska valkeus niinkuin kirkkaalla leimauksella sinun valaisee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 37, 'Ja hänen puhuissansa rukoili häntä yksi Pharisealainen ruoalle kanssansa; niin hän meni ja atrioitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 38, 'Mutta kuin Pharisealainen näki, ihmetteli hän, ettei hän ensin itsiänsä pessyt ennen ruan aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 39, 'Niin sanoi Herra hänelle: nyt te Pharisealaiset, ulkoa te maljan ja vadin puhdistatte, mutta sisälliset teissä ovat täynnä raatelusta ja pahuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 40, 'Te hullut, eikö se, joka ulkoisen puolen teki, tehnyt myös sisälmäistä puolta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 41, 'Kuitenkin antakaa almua niistä, mitä teillä on, ja katso, niin teille ovat kaikki puhtaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 42, 'Mutta voi teitä, te Pharisealaiset! että te kymmenykset teette mintuista ja ruuasta, ja kaikkinaisista kaaleista, ja jätätte pois tuomion ja Jumalan rakkauden: näitä piti tehtämän, ja toisia ei jätettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 43, 'Voi teitä, te Pharisealaiset! jotka rakastatte ylimmäisiä istuimia synagogissa ja tervehdyksiä turulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 44, 'Voi teitä, te kirjanoppineet ja Pharisealaiset, te ulkokullatut! sillä te olette niinkuin peitetyt haudat, joiden päällä ihmiset tietämättä käyvät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 45, 'Niin vastasi yksi lainoppineista ja sanoi hänelle: Mestari, näillä sanoilla sinä myös meitä pilkkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 46, 'Niin hän sanoi: voi teitäkin, te lainoppineet! sillä te raskautatte ihmiset kuormilla, jotka ovat työläät kantaa, ja ette itse yhdellä sormellannekaan tahdo niihin kuormiin ruveta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 47, 'Voi teitä, että te rakennatte prophetain hautoja, mutta tiedän isänne tappoivat ne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 48, 'Niin te tosin todistatte ja suostutte teidän isäinne töihin; sillä he tappoivat ne, mutta te rakennatte niiden haudat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 49, 'Sentähden myös Jumalan viisaus sanoi: minä lähetän heidän tykönsä prophetat ja apostolit, ja muutamat niistä he tappavat ja vainoovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 50, 'Että tältä sukukunnalta pitää etsittämän kaikkein prophetain veri, joka on vuodatettu maailman alusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 51, 'Abelin verestä hamaan Sakariaan vereen asti, joka hukattiin alttarin ja templin vaiheella; tosin minä sanon teille, se pitää etsittämän tältä sukukunnalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 52, 'Voi teitä lainoppineet! sillä te olette ottaneet taidon avaimen: itse ette menneet sisälle, ja sisälle meneväisiä te kielsitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 53, 'Mutta kuin hän oli nämät heille sanonut, rupesivat lainoppineet ja Pharisealaiset kovin häntä ahdistamaan ja viettelemään häntä puhumaan monesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 54, 'Ja väijyivät häntä ja pyysivät jotakin onkia hänen suustansa, kantaaksensa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 1, 'Kuin monta tuhatta ihmistä kokoontuivat, niin että he toinen toistansa tallasivat, rupesi hän sanomaan opetuslapsillensa: kavahtakaat ensisti Pharisealaisten hapatusta, joka on ulkokullaisuus;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 2, 'Sillä ei ole mitään peitetty, joka ei ilmi tule, eikä ole salattu, mikä ei tiettäväksi tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 3, 'Sentähden ne, mitä te pimeydessä sanotte, pitää valkeudessa kuultaman, ja mitä te korvaan puhuneet olette kammioissa, se pitää saarnattaman kattoin päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 4, 'Mutta minä sanon teille, minun ystävilleni: älkäät niitä peljätkö, jotka ruumiin tappavat, ja ei ole heidän sitte enempää tekemistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 5, 'Mutta minä tahdon osoittaa teille, ketä teidän tulee peljätä: peljätkää sitä, jolla on valta, sittekuin hän tappanut on, myös helvettiin sysätä; totta minä sanon teille: sitä te peljätkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 6, 'Eikö viisi varpusta myydä kahteen ropoon? ja ei yksikään heistä ole Jumalan edessä unohdettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 7, 'Ovat myös kaikki teidän päänne hiukset luetut. Älkäät siis peljätkö: te olette paremmat kuin monta varpusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 8, 'Mutta minä sanon teille: jokainen joka minun tunnustaa ihmisten edessä, sen myös Ihmisen Poika on tunnustava Jumalan enkelien edessä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 9, 'Mutta joka minun kieltää ihmisten edessä, se pitää kiellettämän Jumalan enkelien edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 10, 'Ja joka puhuu sanan Ihmisen Poikaa vastaan, se hänelle anteeksi annetaan; mutta joka Pyhää Henkeä pilkkaa, ei sitä anteeksi anneta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 11, 'Kuin he teitä vetävät synagogiin, esivallan ja valtamiesten eteen, niin älkäät murehtiko, kuinka taikka mitä teidän edestänne vastaaman pitää, eli mitä teidän pitää sanoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 12, 'Sillä Pyhä Henki opettaa teitä sillä hetkellä, mitä teidän tulee sanoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 13, 'Niin sanoi hänelle yksi kansasta: Mestari, sanos minun veljelleni, että hän jakais minun kanssani perinnön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 14, 'Mutta hän sanoi hänelle: ihminen, kuka pani minun tuomariksi eli jakomieheksi teidän välillänne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 15, 'Ja hän sanoi heille: katsokaat ja kavahtakaat ahneutta; sillä ei jonkun elämä siinä seiso, että hänellä paljo kalua on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 16, 'Niin hän sanoi heille vertauksen, sanoen: yhden rikkaan miehen maa kasvoi hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 17, 'Ja hän ajatteli itsellänsä ja sanoi: mitä minä teen, ettei minulla ole, kuhunka minä kokoon eloni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 18, 'Ja sanoi: sen minä teen: minä maahan jaotan aittani, ja rakennan suuremmat, ja kokoon sinne kaiken tuloni ja hyvyyteni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 19, 'Ja sanon sielulleni: sielu, sinulla on pantu paljo hyvyyttä moneksi vuodeksi: lepää, syö, juo, riemuitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 20, 'Mutta Jumala sanoi hänelle: sinä tyhmä! tänä yönä sinun sielus sinulta pois otetaan: kuka ne sitte saa, joita sinä valmistanut olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 21, 'Niin on myös se, joka itsellensä tavaraa kokoo, ja ei ole rikas Jumalassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 22, 'Niin hän sanoi opetuslapsillensa: sentähden sanon minä teille: älkäät murehtiko elämästänne, mitä teidän pitä syömän, eikä ruumiistanne, millä te itseänne verhoitatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 23, 'Henki on enempi kuin ruoka, ja ruumis parempi kuin vaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 24, 'Katselkaat kaarneita: ei he kylvä eikä niitä, ei heillä ole myös kellaria eikä aittaa, ja Jumala elättää heidät: kuinka paljoa paremmat te olette kuin linnut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 25, 'Mutta kuka teistä murheellansa voi lisätä varrellensa yhden kyynärän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 26, 'Sentähden ellette siis voi sitä, mikä vähin on, miksi te muista murehditte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 27, 'Katselkaat kukkasia, kuinka ne kasvavat: ei he työtä tee, eikä kehrää; ja minä sanon teille: ei Salomo kaikessa kunniassansa niin ollut vaatetettu kuin yksi heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 28, 'Jos siis ruohon, joka tänäpänä kedolla seisoo jo huomenna pätsiin heitetään, Jumala niin vaatettaa, eikö hän paljoa enemmin teidän sitä te, te vähäuskoiset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 29, 'Sentähden, älkäät etsikö, mitä teidän syömän eli juoman pitää, ja älkäät surulliset olko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 30, 'Sillä näitä kaikkia pakanat maailmassa pyytävät; mutta teidän Isänne tietää, että te näitä tarvitsette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 31, 'Vaan paremmin etsikäät Jumalan valtakuntaa, niin nämät kaikki teille annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 32, 'Älä pelkää, piskuinen lauma; sillä teidän Isällänne on hyvä tahto antaa teille valtakunnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 33, 'Myykäät, mitä teillä on, ja antakaat almua. Tehkäät teillenne säkit, jotka ei vanhene, puuttumatoin tavara taivaissa, kuhunka ei varas ulotu, ja kussa ei koi raiskaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 34, 'Sillä kussa teidän tavaranne on, siellä on myös teidän sydämenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 35, 'Olkoon teidän kupeenne vyötetyt ja teidän kynttilänne sytytetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 36, 'Ja olkaat te niiden ihmisten kaltaiset, jotka odottavat Herraansa häistä palajavan: että kuin hän tulee ja kolkuttaa, niin he hänelle avaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 37, 'Autuaat ovat ne palveliat, jotka Herra tultuansa löytää valvomasta. Totisesti sanon minä teille: hän sonnustaa itsensä ja asettaa heidät aterioitsemaan, ja tulee ja palvelee heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 38, 'Ja jos hän tulee toisessa vartiossa, eli kolmannessa vartiossa tulee, ja näin löytää, autuaat ovat ne palvelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 39, 'Mutta se tietäkäät, että jos perheen-isäntä tietäis, millä hetkellä varas on tuleva, tosin hän valvois eikä sallisi huonettansa kaivettaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 40, 'Sentähden olkaat te myös valmiit: sillä, millä hetkellä ette luulekaan, tulee Ihmisen Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 41, 'Niin sanoi Pietari hänelle: Herra, sanotkos tämän vertauksen meille, eli myös kaikille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 42, 'Mutta Herra sanoi: kuka on uskollinen ja toimellinen perheenhaltia, jonka Herra asettaa perheensä päälle, oikialla ajalla määrättyä osaa antamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 43, 'Autuas on se palvelia, jonka Herra tultuansa niin löytää tehneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 44, 'Totisesti sanon minä teille: hän asettaa hänen kaiken tavaransa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 45, 'Mutta jos palvelia sanoo sydämessänsä: minun Herrani viipyy tulemasta, ja rupee palkollisia hosumaan, ja syömään ja juomaan ja juopumaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 46, 'Niin tulee palvelian herra sinä päivänä, jona ei hän luulekaan, ja sillä hetkellä, jota ei hän tiedä, ja eroittaa hänen, ja antaa hänelle osan uskottomain kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 47, 'Mutta sen palvelian, joka tiesi Herransa tahdon, ja ei itsiänsä valmistanut eikä tehnyt hänen tahtonsa jälkeen, täytyy paljon haavoja kärsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 48, 'Joka taas ei tietänyt, ja kuitenkin teki haavain ansion, sen pitää vähemmän haavoja kärsimän; sillä kenelle paljo annettu on, siltä paljon etsitään, ja jonka haltuun paljo on annettu, sitä enempi anotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 49, 'Minä tuli sytyttämään tulta maan päälle, ja mitä minä tahdon, vaan että se jo palais?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 50, 'Mutta minun pitää kasteella kastettaman, ja kuinka minä ahdistetaan siihenasti että se täytetään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 51, 'Luuletteko, että minä tulin rauhaa lähettämään maan päälle? En, sanon minä teille, vaan eripuraisuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 52, 'Sillä tästedes pitää viisi oleman eroitetut yhdessä huoneessa, kolme kahta vastaan ja kaksi kolmea vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 53, 'Isä eroitetaan poikaansa vastaan ja poika isää vastaan, äiti tytärtä vastaan ja tytär äitiä vastaan, anoppi miniäänsä vastaan, miniä anoppiansa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 54, 'Niin hän sanoi myös kansalle: kuin te näette pilven lännestä nousevan, niin te kohta sanotte: sade tulee; niin myös tuleekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 55, 'Ja kuin te näette etelän tuulevan, niin te sanotte: helle tulee; niin myös tuleekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 56, 'Te ulkokullatut, maan ja taivaan muodon te taidatte koetella, miksi ette siis tätä aikaa koettele?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 57, 'Minkätähden siis ette myös itsestänne tuomitse, mikä oikia on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 58, 'Sillä kuin sinä menet riitaveljes kanssa esivallan eteen, niin pyydä tiellä hänestä päästä; ettei hän sinua tuomarin eteen vetäisi, ja tuomari antais sinua ylön pyövelille, ja pyöveli heittäis sinun torniin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 59, 'Minä sanon sinulle: et sinä sieltä ennen pääse ulos, kuin sinä viimeisen rovon maksat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 1, 'Ja olivat muutamat sillä ajalla siinä, jotka ilmoittivat hänelle Galilealaisista, joiden veren Pilatus oli heidän uhriensa kanssa sekoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 2, 'Ja Jesus vastasi ja sanoi heille: luuletteko, että nämät Galilealaiset olivat syntiset kaikkein Galilealaisten suhteen, että heidän senkaltaista täytyi kärsiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 3, 'Ei suinkaan, sanon minä teille, vaan ellette paranna teitänne, niin te kaikki niin hukkaan tulette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 4, 'Taikka luuletteko, että ne kahdeksantoistakymmentä, joiden päälle Siloan torni lankesi ja tappoi heidät, olivat vialliset kaikkein ihmisten suhteen, jotka Jerusalemissa asuvat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 5, 'Ei suinkaan, sanon minä teille, vaan ellette paranna teitänne, niin te kaikki niin hukkaan tulette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 6, 'Mutta hän sanoi tämän vertauksen: yhdellä oli fikunapuu, hänen viinamäessänsä istutettu, ja hän tuli etsein hedelmää hänestä ja ei löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 7, 'Niin hän sanoi viinamäen rakentajalle: katso, minä olen kolme vuotta tullut ja etsinyt hedelmää tästä fikunapuusta, ja en löydä, hakkaa se pois: miksi se myös maata turmelee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 8, 'Mutta hän vastasi ja sanoi hänelle: herra, anna hänen vielä tämä vuosi olla, niin kauvan kuin minä kaivan hänen ympärinsä ja sonnitan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 9, 'Jos hän sittekin hedelmän tekis; jollei, niin hakkaa se sitte pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 10, 'Mutta hän opetti sabbatina yhdessä synagogassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 11, 'Ja katso, siellä oli vaimo, jolla oli sairauden henki kahdeksantoistakymmentä vuotta ollu, ja kävi kumarruksissa, eikä voinut ikänä itsiänsä ojentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 12, 'Mutta kuin Jesus sen näki, kutsui hän hänen tykönsä ja sanoi hänelle: vaimo, sinä olet päässyt taudistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 13, 'Ja hän pani kätensä hänen päällensä, ja kohta se ojensi ylös itsensä ja kiitti Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 14, 'Niin vastasi synagogan päämies ja närkästyi, että Jesus paransi sabbatina, ja sanoi kansalle: kuusi päivää ovat, joina sopii työtä tehdä; niinä te tulkaat ja antakaat teitä parantaa, ja ei sabbatin päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 15, 'Niin vastasi häntä Herra ja sanoi: sinä ulkokullattu! eikö kukin teistä päästä nautaansa eli aasiansa sabbatina seimestä ja johdata juomaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 16, 'Eikö myös tämä Abrahamin tytär pitäisi sabbatina päästettämän tästä siteestä, jonka, katso, saatana on kahdeksantoistakymmentä vuotta sitonut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 17, 'Ja kuin hän näitä sanoi, niin häpesivät kaikki, jotka häntä vastaan olivat. Ja kaikki kansa iloitsi kaikista kunniallisista töistä, joita häneltä tehtiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 18, 'Niin hän sanoi: kenenkä vertainen on Jumalan valtakunta, ja kenenkä kaltaiseksi minä sen teen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 19, 'Se on sinapin siemenen vertainen, jonka ihminen otti ja kylvi yrttitarhaansa; ja se kasvoi ja tuli suureksi puuksi ja taivaan linnut tekivät pesänsä sen oksille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 20, 'Ja hän taas sanoi: kenenkä vertaiseksi minä Jumalan valtakunnan teen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 21, 'Se on hapatuksen kaltainen, jonka vaimo otti, ja pani sen kolmeen jauhovakkaan, siihenasti kuin se kaikki happani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 22, 'Ja hän vaelsi kaupunkien ja kyläin kautta opettain, ja matkusti Jerusalemia päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 23, 'Niin sanoi yksi hänelle: Herra, vähäkö niitä on, jotka autuaaksi tulevat? Ja hän sanoi heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 24, 'Pyytäkäät ahtaasta portista mennä sisälle, sillä monta on, sanon minä teille, jotka pyytävät mennä sisälle, ja ei taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 25, 'Kuin perheenisäntä on noussut ja oven sulkenut, ja te rupeette ulkona seisomaan ja oven päälle kolkuttamaan ja sanomaan: Herra, Herra, avaa meille! ja hän vastaa ja sanoo teille: en minä teitä tunne, kusta te olette;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 26, 'Niin te rupeette sanomaan: me olemme syöneet ja juoneet sinun edessäs, ja meidän kaduillamme sinä opetit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 27, 'Ja hän on sanova: minä sanon teille: en minä teitä tunne, kusta te olette; menkäät pois minun tyköäni, kaikki te väärintekiät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 28, 'Siellä pitää oleman itku ja hammasten kiristys, kuin te näette Abrahamin ja Isaakin ja Jakobin ja kaikki prophetat Jumalan valtakunnassa, mutta itsenne ajettavan ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 29, 'Ja heidän pitää tuleman idästä ja lännestä, pohjoisesta ja etelästä, ja Jumalan valtakunnassa istuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 30, 'Ja katso, ne ovat viimeiset, jotka tulevat ensimäisiksi, ja ne ovat ensimäiset, jotka tulevat viimeisiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 31, 'Sinä päivänä tulivat muutamat Pharisealaiset ja sanoivat hänelle: lähde ulos ja mene täältä pois; sillä Herodes tahtoo sinua tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 32, 'Ja hän sanoi heille: menkäät ja sanokaat sille ketulle: katso, minä ajan ulos perkeleitä, ja parannan tänäpänä ja huomenna, ja kolmantena päivänä minä lopetetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 33, 'Kuitenkin pitää minun tänäpänä ja huomenna ja toisena huomenna vaeltaman; sillä ei tapahdu, että propheta muualla hukataan kuin Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 34, 'Jerusalem, Jerusalem, joka tapat prophetat ja kivität niitä, jotka sinun tykös lähetetään, kuinka usein minä tahdoin koota sinun lapses, niinkuin kana kokoo poikansa siipiensä alle, ja ette tahtoneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 35, 'Katso, teidän huoneenne jätetään teille kylmille. Totisesti sanon minä teille: ei teidän pidä minua näkemän, siihenasti kuin se aika tulee, jona te sanotte: siunattu olkoon se, joka tulee Herran nimeen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 1, 'Ja tapahtui, että hän tuli yhden Pharisealaisten päämiehen huoneesen sabbatina rualle, ja he vartioitsivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 2, 'Ja katso, siinä oli vesitautinen ihminen hänen edessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 3, 'Niin Jesus vastaten sanoi lainoppineille ja Pharisealaisille: sopiiko sabbatina parantaa? Niin he vaikenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 4, 'Mutta hän rupesi häneen, ja paransi hänen, ja pääsi menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 5, 'Ja hän vastaten sanoi heille: kenenkä teistä nauta eli aasi putoo kaivoon, eikö hän kohta sabbatin päivänä häntä ota ylös?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 6, 'Ja ei he taitaneet häntä tähän vastata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 7, 'Mutta hän sanoi vieraille vertauksen, koska hän ymmärsi, kuinka he valitsivat ylimmäisiä istuimia, sanoen heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 8, 'Kuinka joltakulta häihin kutsuttu olet, niin älä istu ylimmäiseen siaan, ettei joku kunniallisempi sinua ole häneltä kutsuttu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 9, 'Ja tulee se, joka sinun ja hänen on kutsunut, ja sanoo sinulle: anna tälle siaa! ja niin sinä häpiällä menet alemma istumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 10, 'Mutta kuin kutsuttu olet, niin mene ja istu alemmaiseen siaan, että se, joka sinun kutsunut on, tulis ja sanois sinulle: ystäväni, nouse ylemmä; silloin on sinulle kunnia niiden edessä, jotka ynnä kanssas atrioitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 11, 'Sillä jokainen, joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 12, 'Mutta hän sanoi myös sille, joka hänen kutsunut oli: kuin päivällistä tai ehtoollista teet, niin älä kutsu ystäviäs, eli veljiäs, ei lankojas, taikka rikkaita kylänmiehiäs: ettei he joskus sinua myös jälleen kutsu, ja sinulle maksa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 13, 'Mutta kuin pidot teet, niin kutsut köyhiä, raajarikkoja, ontuvia, sokeita:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 14, 'Niin sinä olet autua; sillä ei heillä ole varaa sinulle maksaa, sillä sinulle pitää maksettaman vanhurskasten ylösnousemisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 15, 'Mutta kuin yksi ynnä atrioitsevista nämät kuuli, sanoi hän hänelle: autuas on se, joka syö leipää Jumalan valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 16, 'Niin hän sanoi hänelle: yksi ihminen teki suuren ehtoollisen ja kutsui monta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 17, 'Ja lähetti palveliansa ehtoollisen hetkellä sanomaan kutsutuille: tulkaat, sillä kaikki ovat valmistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 18, 'Ja he rupesivat järjestänsä kaikki itseänsä estelemään: ensimäinen sanoi hänelle: minä ostin pellon, ja minun pitää menemän sitä katsomaan: minä rukoilen sinua, sano minun esteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 19, 'Ja toinen sanoi: minä ostin viisi paria härkiä, ja menen niitä koettelemaan: minä rukoilen sinua, sano minun esteeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 20, 'Ja kolmas sanoi: minä olen emännän nainut, ja en taida sentähden tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 21, 'Ja kuin se palvelia tuli, sanoi hän nämät herrallensa. Silloin perheenisäntä vihastui ja sanoi palveliallensa: mene nopiasti kaupungin kaduille ja kujille ja saata tänne vaivaiset ja raajarikot, ontuvat ja sokiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 22, 'Ja palvelia sanoi: herra, minä olen tehnyt niinkuin sinä käskit, ja vielä nyt siaa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 23, 'Ja herra sanoi palvelialle: men maanteille ja aidoille, ja vaadi heitä sisälle tulemaan, että minun huoneeni täytettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 24, 'Sillä minä sanon teille, ettei yksikään niistä miehistä, jotka kutsuttiin, pidä maistaman minun ehtoollistani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 25, 'Niin vaelsi paljo väkeä hänen kanssansa, ja hän kääntyi ja sanoi heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 26, 'Jos joku tulee minun tyköni, ja ei vihaa isäänsä ja äitiänsä, ja emäntäänsä ja lapsiansa, ja veljiänsä ja sisariansa, ja päälliseksi omaa henkeänsä, ei se taida olla minun opetuslapseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 27, 'Ja joka ei kanna ristiänsä ja seuraa minua, ei se taida olla minun opetuslapseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 28, 'Sillä kuka teistä on, joka tahtoo tornia rakentaa; eikö hän ennen istu ja laske kulutusta, jos hänellä on varaa sitä täyttää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 29, 'Ettei, kuin hän perustuksen laskenut on, ja ei voi sitä täyttää, kaikki, jotka sen näkevät, rupee pilkkaamaan häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 30, 'Sanoen: tämä ihminen rupesi rakentamaan, ja ei voinut täyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 31, 'Taikka kuka kuningas tahtoo mennä sotimaan toista kuningasta vastaan; eikö hän ennen istu ja ajattele, jos hän voi kymmenellä tuhannella kohdata sen, joka häntä vastaan tulee kahdellakymmenellä tuhannella?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 32, 'Muutoin, kuin hän vielä kaukana on, niin hän lähettää hänelle sanan ja rukoilee rauhaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 33, 'Niin siis jokainen teistä, joka ei luovu kaikista mitä hänellä on, ei se taida olla minun opetuslapseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 34, 'Suola on hyvä; mutta jos suola tulee mauttomaksi, milläs sitte suolataan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 35, 'Ei se maahan eikä sontaan ole sovelias: he heittävät sen pois. Jolla on korvat kuulla, se kuulkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 1, 'Mutta hänen tykönsä tulivat kaikki Publikanit ja syntiset, kuulemaan häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 2, 'Ja Pharisealaiset ja kirjanoppineet napisivat ja sanoivat: tämä syntisiä vastaan ottaa ja syö heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 3, 'Niin hän sanoi heille tämän vertauksen, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 4, 'Kuka on teistä se ihminen, jolla on sata lammasta, ja jos hän yhden niistä kadottaa, eikö hän jätä yhdeksänkymmentä ja yhdeksän korpeen, ja mene sen jälkeen, joka kadonnut on, siihenasti että hän sen löytää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 5, 'Ja kuin hän sen löytää, niin hän panee sen olallensa, iloiten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 6, 'Ja kuin hän tulee kotiansa, niin hän kutsuu kokoon ystävänsä ja kylänsä miehet, ja sanoo heille: iloitkaat minun kanssani: sillä minä löysin lampaani, joka kadonnut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 7, 'Minä sanon teille: niin pitää ilo oleman taivaassa yhdestä syntisestä, joka itsensä parantaa, enemmin kuin yhdeksästäkymmenestä ja yhdeksästä hurskaasta, jotka ei parannusta tarvitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 8, 'Taikka kuka vaimo on, jolla on kymmenen penninkiä, jos hän yhden niistä kadottaa, eikö hän sytytä kynttilää, ja lakaise huonetta, ja etsi visusti niinkauvan kuin hän sen löytää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 9, 'Ja kuin hän sen löytänyt on, kutsuu hän kokoon ystävänsä ja kylänsä vaimot, ja sanoo: iloitkaat minun kanssani; sillä minä löysin penninkini, jonka minä kadotin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 10, 'Niin myös, sanon minä teille, pitää ilo oleman Jumalan enkeleillä yhdestä syntisestä, joka itsensä parantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 11, 'Ja hän sanoi: yhdellä miehellä oli kaksi poikaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 12, 'Ja nuorempi heistä sanoi isällensä: isä, anna minulle osa tavarasta, joka minulle tulee. Ja hän jakoi heille tavaran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 13, 'Ja ei kauvan sen jälkeen, kuin nuorempi poika oli kaikki koonnut, meni hän kaukaiselle maakunnalle, ja hukkasi siellä tavaransa irstaisuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 14, 'Mutta kuin hän kaikki oli tuhlannut, niin tuli suuri nälkä kaikkeen siihen maakuntaan; ja hän rupesi hätääntymään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 15, 'Ja meni pois ja suostui yhteen sen maakunnan kauppamieheen, joka hänen lähetti maakyliinsä kaitsemaan sikojansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 16, 'Ja hän pyysi vatsaansa ravalla täyttää, jota siat söivät, ja ei kenkään hänelle sitäkään antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 17, 'Mutta kuin hän mielensä malttoi, sanoi hän: kuinka monella minun isäni palkollisella on kyllä leipää, ja minä kuolen nälkään!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 18, 'Minä nousen ja käyn minun isäni tykö ja sanon hänelle: isä, minä olen syntiä tehnyt taivasta vastaan ja sinun edessäs,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 19, 'Ja en ole silleen mahdollinen sinun pojakses kutsuttaa: tee minua niinkuin yhden palkollisistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 20, 'Ja hän nousi ja tuli isänsä tykö. Mutta kuin hän vielä taampana oli, näki hänen isänsä hänen, ja armahti hänen päällensä, ja juosten lankesi hänen kaulaansa, ja suuta antoi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 21, 'Mutta poika sanoi hänelle: isä, minä olen syntiä tehnyt taivasta vastaan ja sinun edessäs, ja en ole mahdollinen tästedes sinun pojakses kutsuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 22, 'Niin sanoi isä palvelioillensa: tuokaat tänne ne parhaat vaatteet, ja pukekaat hänen yllensä, ja antakaat sormus hänen käteensä, ja kengät hänen jalkoihinsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 23, 'Ja tuokaat syötetty vasikka, ja tappakaat se, ja syökäämme ja riemuitkaamme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 24, 'Sillä tämä minun poikani oli kuollut, ja virkosi jälleen: hän oli kadonnut, ja on taas löydetty; ja rupesivat riemuitsemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 25, 'Mutta hänen vanhempi poikansa oli pellolla, ja kuin hän tuli ja huonettä lähestyi, kuuli hän laulun ja hypyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 26, 'Niin hän kutsui yhden palvelioistansa ja kysyi: mikä se on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 27, 'Niin se sanoi hänelle: sinun veljes tuli, ja isäs antoi tappaa syötetyn vasikan, että hän sai hänen terveenä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 28, 'Niin hän vihastui eikä tahtonut mennä sisälle; hänen isänsä meni siis ulos, ja neuvoi häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 29, 'Mutta hän vastasi ja sanoi isällensä: katso, niin monta vuotta minä palvelen sinua, ja en ole koskaan sinun käskyäs käynyt ylitse, ja et sinä ole minulle vohlaakaan antanut, riemuitakseni ystäväini kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 30, 'Mutta että tämä sinun poikas tuli, joka tavaransa on tuhlannut porttoin kanssa, tapoit sinä hänelle syötetyn vasikan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 31, 'Mutta hän sanoi hänelle: poikani! sinä olet aina minun tykönäni, ja kaikki mitä minun on, se on sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 32, 'Niin piti sinunkin riemuitseman ja iloitseman; sillä tämä sinun veljes oli kuollut ja virkosi jälleen, hän oli kadonnut ja on taas löydetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 1, 'Mutta hän sanoi myöskin opetuslapsillensa: oli rikas mies, jolla oli huoneenhaltia, ja hänen edessänsä kannettiin hänen päällensä, että hän oli hukuttanut hänen hyvyytensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 2, 'Ja hän kutsui hänen ja sanoi hänelle: miksi minä sinusta sen kuulen? tee luku hallituksestas; sillä et sinä saa tästedes hallita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 3, 'Niin huoneenhaltia sanoi itsellensä: mitä minä teen, sillä minun herrani ottaa minulta pois hallituksen? en minä voi kaivaa, häpeen minä kerjätä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 4, 'Minä tiedän, mitä minä teen, että kuin minä viralta pannaan pois, niin he korjaavat minun huoneesensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 5, 'Ja hän kutsui tykönsä kaikki herransa velvolliset ja sanoi ensimäiselle: kuinka paljo sinä olet minun herralleni velkaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 6, 'Mutta se sanoi: sata tynnyriä öljyä. Ja hän sanoi hänelle: ota kirjas ja istu pian, ja kirjoita viisikymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 7, 'Sitte hän sanoi toiselle: kuinka paljon sinä olet velkaa? ja se sanoi: sata puntaa nisuja. Hän sanoi hänelle: ota kirjas ja kirjoita kahdeksankymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 8, 'Ja herra kiitti väärää huoneenhaltiata, että hän toimellisesti teki; sillä tämän maailman lapset ovat toimellisemmat kuin valkeuden lapset heidän sukukunnassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 9, 'Ja minä myös sanon teille: tehkäät teillenne ystäviä väärästä mammonasta, että kuin te tarvitsette, niin he korjaavat teitä ijankaikkisiin majoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 10, 'Joka vähemmässä on uskollinen, se on myös paljossa uskollinen, ja joka vähemmässä on väärä, se on myös paljossa petollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 11, 'Jollette siis ole olleet uskolliset väärässä mammonassa, kuka teille sitä uskoo, mikä oikia on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 12, 'Ja ellette ole olleet toisen omassa uskolliset, kuka teille antaa sen, mikä teidän omanne on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 13, 'Ei yksikään palvelia taida kahta herraa palvella; sillä taikka hän yhtä vihaa ja toista rakastaa, eli yhdessä hän kiinni riippuu ja toisen katsoo ylön. Ette taida palvella Jumalaa ja mammonaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 14, 'Mutta kaikki nämät kuulivat nekin Pharisealaiset, jotka ahneet olivat, ja pilkkasivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 15, 'Ja hän sanoi heille: te olette ne, jotka itsenne hurskaiksi teette ihmisten edessä; mutta Jumala tuntee teidän sydämenne; sillä se mikä ihmisille on korkia, se on Jumalan edessä kauhistus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 16, 'Laki ja prophetat ovat Johannekseen asti, ja siitä ajasta ilmoitetaan Jumalan valtakunta, ja jokainen siihen itseänsä väellä tunkee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 17, 'Pikemmin taivas ja maa hukkuu, kuin rahtukaan laista putoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 18, 'Joka emäntänsä hylkää ja nai toisen, hän tekee huorin, ja joka sen mieheltä hyljätyn nai, hän tekee huorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 19, 'Oli yksi rikas mies, joka vaatetti itsensä purpuralla ja kalliilla liinavaatteilla, ja eli joka päivä ilossa herkullisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 20, 'Oli myös kerjääjä, nimeltä Latsarus, joka makasi hänen ovensa edessä täynnänsä paisumia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 21, 'Ja pyysi ravittaa niistä muruista, jotka rikkaan pöydältä putosivat; mutta koirat myös tulivat ja nuolivat hänen paisumansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 22, 'Niin tapahtui, että kerjääjä kuoli ja vietiin enkeleiltä Abrahamin helmaan: niin kuoli myös rikas ja haudattiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 23, 'Ja kuin hän helvetissä vaivassa oli, nosti hän silmänsä ja näki Abrahamin taampana ja Latsaruksen hänen helmassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 24, 'Ja hän huusi, sanoen: isä Abraham, armahda minun päälleni ja lähetä Latsarus kastamaan sormensa pää veteen, että hän jäähdyttäis minun kieleni; sillä minä kovin vaivataan tässä liekissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 25, 'Niin sanoi Abraham: poikani, muista, että sinä sait sinun hyvääs elämässä, niin myös Latsarus pahaa. Mutta nyt hän lohdutetaan, ja sinä vaivataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 26, 'Ja paitsi kaikkia näitä on meidän ja teidän välillä suuri juopa kiinnitetty, että ne, jotka tahtovat, ei he voi, eikä sieltä tännekään tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 27, 'Niin hän sanoi: minä rukoilen siis sinua, isä, ettäs lähetät hänen minun isäni kotoon;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 28, 'Sillä minulla on viisi veljeä, todistamaan heille, ettei hekin tulisi tähän vaivan siaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 29, 'Sanoi hänelle Abraham: heillä on Moses ja prophetat; kuulkoot niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 30, 'Mutta hän sanoi: ei, isä Abraham: vaan jos joku kuolleista menis heidän tykönsä, niin he parannuksen tekisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 31, 'Hän sanoi hänelle: ellei he Mosesta ja prophetaita kuule, niin ei he myös usko, jos joku kuolleista nousis ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 1, 'Niin hän sanoi opetuslapsillensa: se on mahdotoin, ettei pahennukset tule. Mutta voi häntä, jonka kautta ne tulevat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 2, 'Se olis hänelle parempi, että myllyn kivi ripustettaisiin hänen kaulaansa, ja heitettäisiin mereen, kuin että hän jonkun näistä pienistä pahentais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 3, 'Kavahtakaat teitänne. Jos veljes rikkoo sinua vastaan, niin nuhtele häntä: ja jos hän itsensä parantaa, niin anna hänelle anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 4, 'Ja jos hän seitsemän kertaa päivässä rikkoo sinua vastaan, ja seitsemän kertaa päivässä sinun tykös palajaa, sanoen: minä kadun; niin anna hänelle anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 5, 'Ja apostolit sanoivat Herralle: lisää meille uskoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 6, 'Mutta Herra sanoi: jos teillä olis usko niinkuin sinapin siemen, ja te sanoisitte tälle metsäfikunalle: nouse ylös juurines ja istuta sinus mereen, niin se kuulis teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 7, 'Mutta kenellä teistä on palvelia, joka kyntää taikka karjaa kaitsee, ja kuin hän metsästä kotia tulee, että hän sanoo kohta hänelle: mene rualle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 8, 'Vaan eikö hän pikemmin sano hänelle: valmista minulle ehtoollista, sonnusta sinus, ja palvele minua, niinkauvan kuin minä syön ja juon; ja syö ja juo sinä sitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 9, 'Vai kiittääkö hän palveliaansa, että hän teki, mitä hänelle käsketty oli? En luule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 10, 'Niin myös te, kuin te olette kaikki tehneet, mitä teille käsketty on, niin sanokaat: me olemme kelvottomat palveliat: me teimme sen, minkä meidän piti tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 11, 'Ja tapahtui, kuin hän meni Jerusalemia päin, että hän matkusti keskeltä Samarian ja Galilean.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 12, 'Ja kuin hän tuli yhteen kylään, kohtasivat häntä kymmenen spitalista miestä, jotka taampana seisoivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 13, 'Ja korottivat äänensä, sanoen: Jesus, rakas Mestari, armahda meidän päällemme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 14, 'Ja kuin hän ne näki, sanoi hän heille: menkäät ja osoittakaat teitänne papeille. Ja tapahtui, että he mennessänsä tulivat puhtaiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 15, 'Niin yksi heistä, kuin hän näki, että hän parantunut oli, palasi jälleen ja kunnioitti Jumalaa suurella äänellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 16, 'Ja lankesi kasvoillensa hänen jalkainsa juureen ja kiitti häntä. Ja se oli Samarialainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 17, 'Mutta Jesus vastaten sanoi: eikö kymmenen puhdistettu? kussa yhdeksän ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 18, 'Ei ole muita löydetty, jotka palasivat Jumalaa kunnioittamaan, kuin tämä muukalainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 19, 'Ja hän sanoi hänelle: nouse ja mene! sinun uskos on sinun vapahtanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 20, 'Ja Pharisealaiset kysyivät häneltä: koska Jumalan valtakunta olis tuleva? Vastasi hän heitä ja snaoi: ei Jumalan valtakunta tule niin, että se taidettaisiin nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 21, 'Ei myös heidän pidä sanoman: katso tässä, katso siellä; sillä katso, Jumalan valtakunta on teidän keskellänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 22, 'Niin hän sanoi opetuslapsille: se aika tulee, että te halajatte nähdä yhtäkin Ihmisen Pojan päivää, ja ette saa nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 23, 'Ja he sanovat teille: katso tässä, katso siellä: älkäät menkö ulos, älkäät myös seuratko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 24, 'Sillä niinkuin pitkäisen tuli taivaan alla leimahtaa ja paistaa kaikkein päälle, mitkä taivaan alla ovat, niin on myös Ihmisen Pojan päivänänsä oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 25, 'Mutta ennen tulee hänen paljo kärsiä ja hyljättää tältä sukukunnalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 26, 'Ja niinkuin tapahtui Noan päivinä, niin myös tapahtuu Ihmisen Pojan päivinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 27, 'He söivät, joivat, naivat ja huolivat, hamaan siihen päivään asti, jona Noa arkkiin meni sisälle, ja vedenpaisumus tuli ja hukutti kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 28, 'Niin myös tapahtui Lotin päivinä: he söivät, joivat, ostivat, myivät, istuttivat, rakensivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 29, 'Mutta sinä päivänä, kuin Lot Sodomasta läksi, satoi tulta ja tulikiveä taivaasta, ja hukutti kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 30, 'Niin pitää myös sinä päivänä oleman, jona Ihmisen Poika ilmoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 31, 'Joka sinä päivänä katon päällä on, ja hänen kalunsa ovat huoneessa, niin älköön astuko alas niitä ottamaan. Ja joka pellolla on, niin älköön myös palatko takaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 32, 'Muistakaa Lotin emäntää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 33, 'Jokainen joka pyytää henkensä vapahtaa, hän sen kadottaa, ja jokainen joka sen kadottaa, hän saattaa sen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 34, 'Minä sanon teille: sinä yönä ovat kaksi yhdellä vuoteella, yksi otetaan ylös, ja toinen jätetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 35, 'Kaksi ynnä jauhavat: yksi otetaan ylös, ja toinen jätetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 36, 'Kaksi ovat kedolla: yksi otetaan ylös, ja toinen jätetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 37, 'Ja he vastaten sanoivat hänelle: Herra, kussa siis? Niin sanoi hän heille: kussa raato on, sinne myös kotkat kokoontuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 1, 'Niin hän sanoi myös heille vertauksen, että aina tulee rukoilla ja ei väsyä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 2, 'Sanoen: yksi tuomari oli yhdessä kaupungissa, joka ei peljännyt Jumalaa eikä hävennyt ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 3, 'Niin oli myös yksi leski siinä kaupungissa, joka tuli hänen tykönsä, sanoen: auta minua riitaveljeltäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 4, 'Ja ei hän tahtonut kauvan aikaa. Mutta viimein sanoi hän itsellensä: vaikka en minä Jumalaa pelkää, enkä häpee ihmisiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 5, 'Kuitenkin, että tämä leski vaivaa minua, tahdon minä häntä auttaa, ettei hän viimein tulisi ja nurisisi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 6, 'Niin Herra sanoi: kuulkaat, mitä tämä väärä tuomari sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 7, 'Eikös Jumalan pitäisi valituita auttaman, jotka yötä ja päivää häntä huutavat, pitäiskö hänen sitä kärsimän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 8, 'Minä sanon teille: hän auttaa heitä pian. Kuitenkin, kuin Ihmisen Poika on tuleva, löytäneekö hän uskoa maan päältä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 9, 'Niin hän myös sanoi muutamille, jotka itse päällensä uskalsivat, että he olivat hurskaat, ja muita katsoivat ylön, tämän vertauksen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 10, 'Kaksi ihmistä meni ylös templiin rukoilemaan, yksi Pharisealainen ja toinen Publikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 11, 'Pharisealainen seisoi ja rukoili näin itsellensä: minä kiitän sinua, Jumala, etten minä ole niinkuin muut ihmiset, ryöväri, väärä, huorintekiä, taikka myös niinkuin tämä Publikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 12, 'Kahdesti viikossa minä paastoon, ja annan kymmenykset kaikista mitä minulla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 13, 'Ja Publikani seisoi taampana, eikä tahtonut silmiänsäkään nostaa ylös taivaasen päin, mutta löi rintoihinsa ja sanoi: Jumala, armahda minun syntisen päälleni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 14, 'Minä sanon teille: tämä meni kotiansa hurskaampana kuin toinen; sillä jokainen joka itsensä ylentää, se alennetaan, ja joka itsensä alentaa, se ylennetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 15, 'Niin he toivat myös hänen tykönsä lapsia, että hän heihin rupeais. Mutta kuin opetuslapset sen näkivät, nuhtelivat he niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 16, 'Mutta kuin Jesus oli heitä kutsunut tykönsä, sanoi hän: sallikaat lasten tulla minun tyköni, ja älkäät heitä kieltäkö; sillä senkaltaisten on Jumalan valtakunta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 17, 'Totisesti sanon minä teille: joka ei ota vastaan Jumalan valtakuntaa niinkuin lapsi, ei hän ikinä siihen tule siihen sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 18, 'Ja häneltä kysyi yksi päämiehistä ja sanoi: hyvä Mestari, mitä minun pitää tekemän, että minä ijankaikkisen elämän saisin? *');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 19, 'Niin Jesus sanoi hänelle: mitäs minua hyväksi kutsut? Ei ole kenenkään hyvä, vaan yksi, Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 20, 'Käskysanat sinä tiedät: ei sinun pidä huorin tekemän: ei sinun pidä tappaman: ei sinun pidä varastaman: ei sinun pidä väärää todistusta sanoman: kunnioita isääs ja äitiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 21, 'Niin hän sanoi: nämät kaikki olen minä minun nuoruudestani pitänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 22, 'Kuin Jesus sen kuuli, sanoi hän hänelle: yksi sinulta vielä puuttuu: myy kaikki, mitä sinulla on ja vaivaisille, niin sinulla pitää oleman tavara taivaassa: ja tule, seuraa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 23, 'Vaan kuin hän sen kuuli, tuli hän murheelliseksi; sillä hän oli sangen rikas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 24, 'Mutta kuin Jesus näki hänen murheissansa olevan, sanoi hän: kuinka työläästi rikkaat tulevat Jumalan valtakuntaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 25, 'Sillä huokiampi on kamelin käydä neulan silmän lävitse, kuin rikkaan tulla Jumalan valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 26, 'Niin he sanoivat, jotka sen kuulivat: ja kuka taitaa autuaaksi tulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 27, 'Mutta hän sanoi: ne mitkä ovat mahdottomat ihmisten tykönä, ne ovat mahdolliset Jumalan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 28, 'Niin Pietari sanoi: katso, me jätimme kaikki ja seurasimme sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 29, 'Vaan hän sanoi heille: totisesti sanon minä teille: ei ole kenkään, joka jätti huoneen taikka vanhemmat taikka veljet taikka emännän taikka lapset Jumalan valtakunnan tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 30, 'Joka ei paljoa enempää saa tällä ajalla jällensä, ja tulevaisessa maailmassa ijankaikkisen elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 31, 'Ja hän otti tykönsä ne kaksitoistakymmentä, ja sanoi heille: katso, me menemme Jerusalemiin, ja kaikki pitää täytettämän mitkä prophetailta Ihmisen Pojasta kirjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 32, 'Sillä hän annetaan ylön pakanoille, ja pilkataan, ja häväistään, ja syljetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 33, 'Ja kuin he ovat hänen ruoskineet, tappavat he hänen, ja kolmantena päivänä on hän nouseva ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 34, 'Ja ei he mitään näistä ymmärtäneet. Ja tämä puhe oli heiltä niin peitetty, ettei he ymmärtäneet, mitä sanottiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 35, 'Niin tapahtui, kuin hän Jerikoa lähestyi, että yksi sokia istui tien vieressä kerjäten,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 36, 'Ja kuin hän kuuli kansan käyvän ohitse, kysyi hän, mikä se olis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 37, 'He sanoivat hänelle: Jesus Natsarealainen tästä meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 38, 'Ja hän huusi ja sanoi: Jesus, Davidin Poika, armahda minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 39, 'Niin ne, jotka menivät ohitse, toruivat häntä vaikenemaan. Mutta hän huusi sitä enemmin: Davidin Poika, armahda minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 40, 'Niin Jesus seisahti ja käski häntä taluttaa tykönsä. Ja kuin hän lähestyi, kysyi hän häneltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 41, 'Sanoen: mitäs tahdot, että minun pitää sinulle tekemän? Hän sanoi: Herra, että minä näköni jälleen saisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 42, 'Ja Jesus sanoi hänelle: ole näkevä! sinun uskos autti sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 43, 'Ja hän sai kohta näkönsä, ja seurasi häntä, ja kunnioitti Jumalaa. Ja kaikki kansa, jotka sen näkivät, kiittivät Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 1, 'Ja hän meni sisälle ja vaelsi Jerikon lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 2, 'Ja katso, yksi mies oli nimeltä Zakeus, joka oli Publikanien päämies ja hän oli rikas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 3, 'Ja hän pyysi nähdä Jesusta, kuka hän olis, eikä saanut kansalta; sillä hän oli varttansa vähäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 4, 'Ja hän samosi edelle, meni ylös yhteen metsä-fikunapuuhun, että hän olis saanut hänen nähdä; sillä sen kautta oli hän vaeltava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 5, 'Ja kuin hän tuli siihen paikkaan, katsoi Jesus ylös, ja näki hänen, ja sanoi hänelle: Zakeus, astu nopiasti alas! sillä minun pitää tänäpänä oleman sinun huoneessas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 6, 'Ja hän astui nopiasti alas ja otti hänen iloiten vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 7, 'Ja kuin he sen näkivät, napisivat he kaikki, että hän meni sisälle syntisen miehen tykö olemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 8, 'Mutta Zakeus seisoi ja sanoi Herralle: katso, Herra, puolen minun tavaraani annan minä vaivaisille; ja jos minä jonkun pettänyt olen, sen minä neljäkertaisesti jälleen annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 9, 'Niin Jesus sanoi hänelle: tänäpänä on tälle huoneelle autuus tapahtunut, että hänkin on Abrahamin poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 10, 'Sillä Ihmisen Poika tuli etsimään ja vapahtamaan sitä, mikä kadonnut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 11, 'Mutta kuin he nämät kuulleet olivat, sanoi hän vielä yhden vertauksen: että hän oli juuri läsnä Jerusalemia, ja että he luulivat Jumalan valtakunnan kohta ilmoitettavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 12, 'Sanoi hän siis: yksi herrasmies matkusti kaukaiseen maakuntaan, itsellensä valtakuntaa ottamaan, ja aikoi jälleen palata:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 13, 'Niin hän kutsui tykönsä kymmenen palveliaansa ja antoi heille kymmenen leiviskää, ja sanoi heille: tehkäät kauppaa niinkauvan kuin minä tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 14, 'Mutta hänen kylänsä asujat vihasivat häntä, ja lähettivät sanansaattajat hänen jälkeensä, sanoen: emme tahdo, että tämä meitä vallitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 15, 'Ja tapahtui kuin hän palasi, sitte kuin hän sai valtakunnan, käski hän kutsua ne palveliat tykönsä, joille hän oli rahansa antanut, tietääksensä, mitä kukin kaupallansa toimittanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 16, 'Niin tuli ensimäinen ja sanoi: herra, sinun leiviskäs on kymmenen leiviskää kasvattanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 17, 'Ja hän sanoi hänelle: oikein, hyvä palvelia, ettäs vähässä olit uskollinen, sinulla pitää valta kymmenen kaupungin päälle oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 18, 'Toinen myös tuli ja sanoi: herra, sinun leiviskäs on viisi leiviskää kasvattanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 19, 'Niin hän myös sanoi hänelle: ole sinäkin viiden kaupungin haltia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 20, 'Ja kolmas tuli ja sanoi: herra, katso, tässä on sinun leiviskäs, joka minulla hikiliinassa kätketty oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 21, 'Sillä minä pelkäsin sinua, ettäs kova mies olet; sinä otat, jota et tallelle pannut, ja niität, jota et kylvänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 22, 'Hän sanoi hänelle: sinun suustas minä sinun tuomitsen, sinä paha palvelia, sinä tiesit minun kovaksi mieheksi, joka otan, jota en minä tallelle pannut, ja leikkaan, jota en minä kylvänyt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 23, 'Ja miksi et sinä antanut minun rahaani vaihetuspöydälle? ja minä olisin tultuani sen kasvun kanssa jälleen saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 24, 'Niin hän sanoi tykönä seisoville: ottakaat pois leiviskä häneltä, ja antakaat sille, jolla kymmenen leiviskää on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 25, 'Niin he sanoivat hänelle: herra, hänellä on kymmenen leiviskää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 26, 'Sillä minä sanon teille, jolla on, hänelle pitää annettaman, ja häneltä, jolla ei ole, sekin, mikä hänellä on, pitää otettaman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 27, 'Kuitenkin ne minun viholliseni, jotka ei tahtoneet minun antaa vallita heitä, tuokaat tänne ja mestatkaa heitä minun edessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 28, 'Ja kuin hän nämät puhunut oli, meni hän edellä ja vaelsi ylös Jerusalemia päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 29, 'Ja tapahtui, kuin hän lähestyi Betphagea ja Betaniaa, ja tuli sen vuoren tykö, joka öljymäeksi kutsutaan kutsutaan, lähetti hän kaksi opetuslapsistansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 30, 'Sanoen: menkäät kylään, joka on teidän edessänne, ja kuin te siihen tulette sisälle, niin te löydätte varsan sidottuna, jonka päällä ei yksikään ihminen koskaan istunut ole: päästäkäät se ja tuokaat tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 31, 'Ja jos joku teiltä kysyy: miksi te sitä päästätte? niin sanokaat hänelle: Herra tätä tarvitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 32, 'Niin lähetetyt menivät ja löysivät niinkuin hän oli heille sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 33, 'Kuin he nyt päästivät varsaa, sanoi sen isäntä heille: miksi te päästätte varsaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 34, 'Vaan he sanoivat: Herra tätä tarvitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 35, 'Ja he veivät sen Jesuksen tykö, ja panivat vaatteensa varsan päälle, ja istuttivat Jesuksen se päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 36, 'Ja kuin hän matkusti, levittivät he vaatteensa tielle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 37, 'Ja kuin hän jo lähestyi menemään alas Öljymäeltä, rupesi koko opetuslasten joukko iloiten kiittämään Jumalaa suurella äänellä kaikistä niistä voimallisista töistä, jotka he nähneet olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 38, 'Sanoen: siunattu olkoon se, joka tulee, kuningas Herran nimeen! rauha taivaassa ja kunnia korkeuksissa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 39, 'Ja muutamat Pharisealaisista kansan seasta sanoivat hänelle: Mestari, nuhtele opetuslapsias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 40, 'Ja hän vastaten sanoi heille: minä sanon teille: jos nämät vaikenevat, niin kivet pitää huutaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 41, 'Ja kuin hän lähemmä tuli, katsoi hän kaupungin päälle, itki häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 42, 'Ja sanoi: jos sinäkin tietäisit, niin sinä ajattelisit tosin tällä sinun ajallas, mitä sinun rauhaas sopis. Mutta nyt ovat ne kätketyt sinun silmäis edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 43, 'Sillä ne päivät pitää tuleman sinun ylitses, että sinun vihollises skantsaavat * sinun, ja ympäri piirittävät sinun, ja ahdistavat sinun joka kulmalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 44, 'Ja maahan tasoittavat sinun ja sinun lapses, jotka sinussa ovat, ja ei jätä sinussa kiveä kiven päälle; ettet etsikkos aikaa tuntenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 45, 'Ja hän meni sisälle templiin, rupesi ajamaan siitä ulos ostajia ja myyjiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 46, 'Sanoen heille: kirjoitettu on: minun huoneeni on rukoushuone; mutta te olette sen tehneet ryövärien luolaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 47, 'Ja hän opetti joka päivä templissä, mutta pappein päämiehet ja kirjanoppineet ja kansan vanhimmat etsivät häntä surmataksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 48, 'Ja ei tietäneet, mitä heidän piti tekemän; sillä kaikki kansa riippui hänessä, ja kuulivat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 1, 'Ja tapahtui yhtenä niistä päivistä, kuin hän kansaa opetti templissä ja saarnasi evankeliumia, tulivat ylimmäiset papit ja kirjanoppineet ja vanhimmat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 2, 'Ja puhuivat hänelle, sanoen: sanos meille, millä vallalla sinä tätä teet? eli kuka sinulle tämän vallan on antanut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 3, 'Niin Jesus vastaten sanoi heille: minä kysyn myös teiltä yhtä asiaa, vastatkaat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 4, 'Oliko Johanneksen kaste taivaasta, vaiko ihmisiltä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 5, 'Niin he ajattelivat itsellänsä, sanoen: jo me sanomme: taivaasta, niin hän sanoo: miksi ette siis uskoneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 6, 'Mutta jos me sanomme: ihmisiltä, niin kaikki kansa kivittää meidät; sillä he uskoivat, että Johannes oli propheta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 7, 'Ja he vastasivat, ettei he tietäneet, kusta se oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 8, 'Niin sanoi Jesus heille: en minä myös sano teille, millä voimalla minä näitä teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 9, 'Niin hän rupesi sanomaan kansalle tämän vertauksen: yksi mies istutti viinamäen ja pani sen vuorolle peltomiehille, ja meni muille maille kauvaksi aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 10, 'Ja ajallansa lähetti hän palvelian peltomiesten tykö, että he antaisivat hänelle viinamäen hedelmästä. Mutta ne peltomiehet pieksivät sen ja lähettivät pois tyhjänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 11, 'Ja hän lähetti vielä toisen palvelian; mutta he myös sen pieksivät, ja pilkkasivat, ja lähettivät pois tyhjänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 12, 'Ja hän lähetti vielä kolmannen. Mutta he myös sen haavoittivat ja syöksivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 13, 'Niin viinamäen isäntä sanoi: mitä minä teen? minä lähetän minun rakkaan poikani: kuin he hänen näkevät, niin he karttavat häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 14, 'Mutta kuin peltomiehet sen näkivät, ajattelivat he itsellänsä, sanoen: tämä on perillinen: tulkaat, tappakaamme häntä, että perintö tulis meidän omaksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 15, 'Ja he syöksivät ulos hänen viinamäestä ja tappoivat. Mitä viinamäen isäntä on tekevä heille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 16, 'Hän tulee ja hukkaa nämät peltomiehet, ja antaa viinamäen muille. Kuin he sen kuulivat, sanoivat he: pois se!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 17, 'Mutta hän katsahti heidän päällensä ja sanoi: mitä se on, mikä kirjoitettu on: Se kivi, jonka rakentajat hylkäsivät, on tullut nurkkakiveksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 18, 'Jokainen joka lankee sen kiven päälle, se runnellaan; mutta jonka päälle se lankee, sen hän musertaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 19, 'Ja pappein päämiehet ja kirjanoppineet pyysivät häntä sillä hetkellä kiinni ottaa, vaan he pelkäsivät kansaa; sillä he ymmärsivät, että hän heille tämän vertauksen sanonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 20, 'Ja he vartioitsivat häntä ja lähettivät väijyjät, jotka piti itsensä hurskaiksi teettelemän, että he hänen puheessa saisivat kiinni, ja antaisivat ylön esivallalle ja maanvanhimman haltuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 21, 'Ja he kysyivät häneltä ja sanoivat: Mestari, me tiedämme, ettäs oikein sanot ja opetat, etkä katso ihmisen muotoa, vaan opetat Jumalan tien totuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 22, 'Sopiiko meidän antaa keisarille veroa, taikka ei?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 23, 'Mutta kuin hän ymmärsi heidän kavaluutensa, sanoi hän heille: mitä te minua kiusaatte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 24, 'Osoittakaat minulle veroraha, kenenkä kuva ja päällekirjoitus siinä on? He vastasivat ja sanoivat: keisarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 25, 'Niin hän sanoi heille: antakaat keisarille, mitkä keisarin ovat, ja Jumalalle, mitkä Jumalan ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 26, 'Ja ei he taitaneet hänen puhettansa kansan edessä laittaa, vaan ihmettelivät hänen vastaustansa, ja vaikenivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 27, 'Niin tulivat muutamat Saddukealaisista, (jotka kieltävät ylösnousemisen,) ja kysyivät häneltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 28, 'Sanoen: Mestari, Moses kirjoitti meille: jos jonkun veli kuolee, jolla emäntä oli, ja se kuolis lapsetonna, niin hänen veljensä pitää sen vaimon ottaman ja veljellensä siemenen herättämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 29, 'Niin oli seitsemän veljeä: ensimäinen otti emännän ja kuoli lapsetonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 30, 'Ja toinen otti sen vaimon, ja se myös kuoli lapsetonna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 31, 'Ja kolmas otti myös sen: ja niin kaikki seitsemän, eikä jättäneet lapsia, ja kuolivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 32, 'Kaikkein viimein kuoli myös vaimo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 33, 'Sentähden ylösnousemisessa, kenenkä heistä vaimo pitää oleman? sillä kaikki seitsemän ovat sen vaimonansa pitäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 34, 'Ja Jesus vastaten sanoi heille: tämän maailman lapset naivat ja huolevat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 35, 'Mutta ne, jotka otolliseksi tulevat sille maailmalle ja ylösnousemiselle kuolleista, ei he nai eikä huole;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 36, 'Sillä ei he enään kuolla taida; sillä he ovat enkelien kaltaiset, ja he ovat Jumalan lapset, että he ovat ylösnousemisen lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 37, 'Mutta että kuolleet ylösnousevat, sen on myös Moses pensaan tykönä osoittanut, kuin hän sanoi Herran Abrahamin Jumalaksi ja Isaakin Jumalaksi ja Jakobin Jumalaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 38, 'Mutta ei Jumala ole kuolleiden Jumala, vaan elävien; sillä kaikki hänelle elävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 39, 'Niin vastasivat muutamat kirjanoppineista ja sanoivat: Mestari, oikein sinä sanoit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 40, 'Ja ei he rohjenneet häneltä mitään enempää kysyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 41, 'Niin hän sanoi heille: kuinka he sanovat Kristuksen Davidin pojaksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 42, 'Ja David itse sanoo Psalmiraamatussa: Herra sanoi minun Herralleni: istu minun oikialle kädelleni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 43, 'Siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 44, 'Koska siis David kutsuu hänen Herraksensa, kuin hän on hänen Poikansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 45, 'Mutta kuin kaikki kansa sen kuuli, sanoi hän opetuslapsillensa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 46, 'Kavahtakaat kirjanoppineita, jotka tahtovat käydä pitkissä vaatteissa ja ottavat hyväksi tervehdykset turulla, ja ylimmäiset istuimet synagogissa, ja ylimmäiset siat ehtoollisissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 47, 'Jotka syövä leskein huoneet, ja muodoksi pitävät pitkät rukoukset: heidän pitää saaman sitä raskaamman tuomion.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 1, 'Mutta kuin hän katsoi, näki hän rikkaat panevan lahjojansa uhri-arkkuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 2, 'Hän näki myös köyhän lesken panevan siihen kaksi ropoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 3, 'Ja sanoi: totisesti sanon minä teille: tämä köyhä leski pani enemmän kuin nämät kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 4, 'Sillä kaikki nämät panivat siitä, mitä heillä liiaksi oli, Jumalan uhriksi, vaan tämä pani köyhyydestänsä kaiken tavaransa, mikä hänellä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 5, 'Ja kuin muutamat sanoivat hänelle templistä, kuinka kauniilla kivillä ja kappaleilla se kaunistettu oli, niin hän sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 6, 'Näitäkö te katselette? Ne päivät pitää tuleman, joina ei pidä kiveä kiven päälle jätettämän, jota ei maahan jaoteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 7, 'Niin he kysyivät häneltä ja sanoivat: Mestari, koskas nämät tapahtuvat? ja mikä merkki on, koska nämät tulevat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 8, 'Hän sanoi: katsokaat, ettei teitä petetä; sillä moni tulee minun nimeeni ja sanoo: minä se olen! aika on kyllä läsnä, älkäät kuitenkaan heitä seuratko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 9, 'Mutta kuin te kuulette sotia ja kapinoita, niin älkäät peljästykö; sillä nämät pitää ensin tapahtuman, vaan ei kohta loppu ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 10, 'Niin hän sanoi heille: kansa nousee kansaa vastaan, ja valtakunta valtakuntaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 11, 'Ja suuret maan vapistukset pitä joka paikassa tuleman, nälkä ja rutto, kauhistukset ja suuret ihmeet taivaasta tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 12, 'Mutta ennen näitä kaikkia heittävät he kätensä teidän päällenne, vainoovat ja antavat ylön teitä synagogiin ja vankiuteen, ja vetävät teitä kuningasten ja esimiesten eteen, minun nimeni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 13, 'Mutta se tapahtuu teille todistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 14, 'Niin pankaat nyt se teidän sydämeenne, ettette ennen ajattelisi, kuinka teidän pitää edestänne vastaaman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 15, 'Sillä minä annan teille suun ja viisauden, jota ei he voi puhua vastaan eikä seisoa vastaan, kaikki jotka teitä vastaan ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 16, 'Niin te myös annetaan ylön vanhimmilta, veljiltä, langoilta ja ystäviltä, ja muutamat teistä he tappavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 17, 'Ja te tulette vihattaviksi kaikilta, minun nimeni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 18, 'Vaan ei hiuskarvakaan pidä teidän päästänne hukkuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 19, 'Pitäkäät teidän sielunne kärsivällisyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 20, 'Mutta kuin te näette Jerusalemin sotaväeltä piiritettävän, niin tietäkäät, että hänen perikatonsa on lähestynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 21, 'Silloin ne, jotka Juudeassa ovat, paetkaan vuorille, ja jotka hänen keskellänsä ovat, ne lähtekään sieltä ulos, ja jotka maalla ovat, älkään häneen menkö sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 22, 'Sillä ne ovat kostopäivät, että kaikki täytettäisiin, mitkä kirjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 23, 'Mutta voi raskaita ja imettäväisiä niinä päivinä! Sillä suuri vaiva pitää maan päällä oleman ja viha tämän kansan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 24, 'Ja heidän pitää lankeeman miekan terään, ja he viedään vangiksi kaikkinaisen kansan sekaan. Ja Jerusalem pitää tallattaman pakanoilta, siihen asti kuin pakanain aika täytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 25, 'Ja merkit pitää oleman auringossa ja kuussa ja tähdissä, ja maassa kansalla ahdistus epäilyksen tähden. Ja meri ja aallot pitää pauhaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 26, 'Ja ihmiset maassa pitää nääntymän pelvon ja odottamisen tähden niitä, mitkä maan piirin päälle tulevat; sillä taivaan voimat pitää liikutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 27, 'Ja silloin heidän pitää näkemän Ihmisen Pojan tulevan pilvissä suurella voimalla ja kunnialla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 28, 'Mutta kuin nämät rupeevat tapahtumaan, niin katsokaat, ja nostakaat päänne ylös; sillä teidän lunastuksenne silloin lähestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 29, 'Ja hän sanoi heille vertauksen: katsokaat fikunapuuta ja kaikkia puita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 30, 'Kuin ne jo puhkeevat, niin te näette ja itse teistänne ymmärrätte, että suvi on jo läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 31, 'Niin myös te, kuin te näette nämät tapahtuvan, tietäkäät, että Jumalan valtakunta on läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 32, 'Totisesti minä sanon teille: ei tämän sukukunnan pidä suinkaan hukkuman, siihenasti kuin nämät kaikki tapahtuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 33, 'Taivas ja maa on hukkuva, vaan minun sanani ei pidä ikänä hukkaantuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 34, 'Mutta kavahtakaat, ettei teidän sydämenne koskaan raskauteta ylönsyömisestä ja juopumisesta ja elatuksen murheesta, ja se päivä tulee äkisti teidän päällenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 35, 'Sillä se tulee niinkuin paula kaikkein ylitse, jotka koko maan päällä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 36, 'Sentähden valvokaat ja aina rukoilkaat, että te mahdolliset olisitte kaikkia näit välttämään, jotka pitää tapahtuman, ja seisomaan Ihmisen Pojan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 37, 'Ja hän opetti päivällä templissä, mutta yöllä meni hän ulos ja oli yötä vuorella, joka kutsutaan Öljymäeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 38, 'Ja kaikki kansa tuli varhain hänen tykönsä templiin, häntä kuulemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 1, 'Niin lähestyi makian leivän juhlapäivä, joka pääsiäiseksi kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 2, 'Ja ylimmäiset papit ja kirjanoppineet etsivät, kuinka he olisivat hänen saaneet tappaa. Mutta he pelkäsivät kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 3, 'Niin saatana oli mennyt Juudaan sisälle, jonka liikanimi oli Iskariot, joka oli kahdentoistakymmenen luvusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 4, 'Ja hän meni pois ja puhutteli ylimmäisiä pappeja ja päämiehiä, kuin hän oli hänen heille pettävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 5, 'Ja he ihastuivat ja lupasivat hänelle rahaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 6, 'Ja hän lupasi sen heille, ja etsi soveliasta aikaa, saadaksensa häntä pettää ilman hasuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 7, 'Niin makian leivän päivä tuli, jona pääsiäislammas piti teurastettaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 8, 'Ja hän lähetti Pietarin ja Johanneksen, sanoen: menkäät valmistamaan meille pääsiäislammas syödäksemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 9, 'Niin he sanoivat hänelle: kussas tahdot meitä valmistamaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 10, 'Hän sanoi heille: katso, kuin te kaupunkiin tulette sisälle, kohtaa teitä ihminen, kantain vesiastiaa: seuratkaat häntä siihen huoneesen, johonka hän menee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 11, 'Ja sanokaat sen huoneen perheenisännälle: Mestari sanoo sinulle: kussa on maja, jossa minä syön pääsiäislampaan opetuslasteni kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 12, 'Ja hän osoittaa teille suuren salin rakennetun; valmistakaat siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 13, 'Niin he menivät ja löysivät niinkuin hän heille sanonut oli, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 14, 'Ja kuin jo aika tullut oli, istui hän pöydän tykönä ja kaksitoistakymmentä apostolia hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 15, 'Ja hän sanoi heille: minä olen halulla halainnut syödä tätä pääsiäislammasta teidän kanssanne, ennekuin minä kärsin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 16, 'Sillä minä sanon teille, etten minä suinkaan silleen siitä syö, siihenasti kuin se täytetään Jumalan valtakunnassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 17, 'Ja hän otti kalkin, kiitti, ja sanoi: ottakaat ja jakakaat keskenänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 18, 'Sillä minä sanon teille, etten minä suinkaan juo viinapuun hedelmää, siihenasti kuin Jumalan valtakunta tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 19, 'Ja hän otti leivän, kiitti ja mursi, ja antoi heille, sanoen: tämä on minun ruumiini, joka teidän edestänne annetaan: se tehkäät minun muistokseni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 20, 'Niin myös kalkin ehtoollisen jälkeen, sanoen: tämä kalkki on uusi Testamentti, minun veressäni, joka teidän edestänne vuodatetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 21, 'Kuitenkin, katso, minun pettäjäni käsi on minun kanssani pöydällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 22, 'Ja tosin Ihmisen Poika menee niinkuin päätetty on: kuitenkin voi sitä ihmistä, jolta hän petetään!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 23, 'Ja he rupesivat kyselemään keskenänsä: kuka olis se heistä, joka sen tekevä olis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 24, 'Mutta heidän välillänsä tuli myös riita, kuka heistä näkyis suurin olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 25, 'Niin hän sanoi heille: kansain kuninkaat vallitsevat heitä, ja joilla valta on heidän ylitsensä, ne kutsutaan armollisiksi herroiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 26, 'Mutta ette te niin: vaan joka teistä suurin on, se olkoon niinkuin nuorin, ja joka ylimmäinen on, se olkoon niinkuin se, joka palvelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 27, 'Sillä kumpi suurempi on: se joka atrioitsee, taikka se joka palvelee? eikö se joka atrioitsee? mutta minä olen teidän keskellänne niinkuin se, joka palvelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 28, 'Mutta te olette ne, jotka minun kiusauksissani minun kanssani pysyitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 29, 'Ja minä säädin teille, niinkuin minun Isäni sääsi minulle, valtakunnan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 30, 'Että teidän pitää syömän ja juoman minun pöydälläni minun valtakunnassani, ja istuman istuimilla, ja tuomitseman kaksitoistakymmentä Israelin sukukuntaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 31, 'Niin sanoi myös Herra: Simon, Simon, katso, saatana on teitä pyytänyt seuloaksensa niinkuin nisuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 32, 'Vaan minä rukoilin sinun edestäs, ettei sinun uskos puuttuman pidä. Ja kuin sinä kerran palajat, niin vahvista veljiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 33, 'Niin hän sanoi hänelle: Herra, minä olen valmis sinun kanssas sekä vankiuteen että kuolemaan menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 34, 'Mutta hän sanoi: Pietari, minä sanon sinulle, ei laula tänäpänä kukko ennen kuin sinä kolmasti kiellät tuntevas minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 35, 'Ja hän sanoi heille: kuin minä lähetin teidät ilman säkkiä ja kukkaroa ja kenkiä, puuttuiko teiltä mitään? He sanoivat: ei mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 36, 'Niin hän sanoi heille: vaan nyt, jolla säkki on, ottakoon sen, niin myös kukkaron; ja jolla ei ole, se myykään hameensa ja ostakaan miekan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 37, 'Sillä minä sanon teille: vielä sekin mikä kirjoitettu on, pitää minussa täytettämän: hän on pahantekiäin sekaan luettu; sillä ne, mitkä minusta kirjoitetut ovat, pitää loppuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 38, 'Niin he sanoivat: Herra, katso, tässä on kaksi miekkaa. Hän sanoi heille: kyllä siinä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 39, 'Ja hän läksi ulos ja meni, niinkuin hänen tapansa oli, Öljymäelle; niin seurasivat myös häntä hänen opetuslapsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 40, 'Ja kuin hän siihen paikkaan tuli, sanoi hän heille: rukoilkaat, ettette tulisi kiusaukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 41, 'Ja hän erkani heistä lähes kivellä heittää ja laski polvillensa, rukoili,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 42, 'Sanoen: Isä, jos sinä tahdot, niin ota pois minulta tämä kalkki, kuitenkin ei minun tahtoni, mutta sinun olkoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 43, 'Niin enkeli taivaasta ilmestyi hänelle ja vahvisti häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 44, 'Ja kuin hän sangen suuressa ahdistuksessa oli, rukoili hän hartaammin. Ja oli hänen hikensä niinkuin verenpisarat, jotka maan päälle putosivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 45, 'Ja kuin hän nousi rukoilemasta ja tuli opetuslastensa tykö, löysi hän ne murheen tähden makaamasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 46, 'Ja hän sanoi heille: mitä te makaatte? nouskaat ja rukoilkaat, ettette kiusaukseen lankeaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 47, 'Vielä hänen puhuissansa, katso, joukko ja se, joka kutsuttiin Juudas, yksi kahdestatoistakymmenestä, kävi heidän edellänsä, ja lähestyi Jesusta suuta antamaan hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 48, 'Niin Jesus sanoi hänelle: Juudas, suun antamisellako sinä Ihmisen Pojan petät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 49, 'Kuin ne, jotka hänen ympärillänsä olivat, näkivät, mitä tuleva oli, sanoivat he hänelle: Herra, emmekö me lyö miekalla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 50, 'Ja yksi heistä löi pappein päämiehen palveliaa ja hakkasi pois hänen oikian korvansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 51, 'Mutta Jesus vastaten sanoi: sallikaat tähän asti tulla. Ja kuin hän rupesi hänen korvaansa, paransi hän sen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 52, 'Mutta Jesus sanoi niille, jotka häntä vastaan olivat tulleet, ylimmäisille papeille ja templin haltioille ja vanhimmille: niinkuin ryövärin tykö te läksitte miekoilla ja seipäillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 53, 'Minä olin joka päivä teidän kanssanne templissä, ja ette ojentaneet kättä minun päälleni; mutta tämä on teidän hetkenne ja pimeyden valta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 54, 'Niin he kiinni ottivat hänen ja taluttivat, ja veivät hänen sisälle ylimmäisen papin huoneesen. Mutta Pietari seurasi taampana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 55, 'Ja niin he virittivät valkian keskelle kartanoa, ja ynnä yhdessä istuivat, istui myös Pietari heidän seassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 56, 'Mutta kuin yksi piika näki hänen valkian tykönä istuvan, katsoi hän hänen päällensä, ja sanoi: tämä oli myös hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 57, 'Vaan hän kielsi hänen ja sanoi: vaimo, en minä tunne häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 58, 'Ja vähän hetken perästä näki toinen hänen, ja sanoi: sinä myös olet yksi heistä. Pietari sanoi: ihminen, en ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 59, 'Ja lähes yhden hetken perästä todisti myös toinen, sanoen: totisesti tämä oli myös hänen kanssansa; sillä hän on Galileasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 60, 'Niin Pietari sanoi: ihminen, en minä tiedä, mitäs sanot. Ja kohta, vielä hänen puhuissansa, lauloi kukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 61, 'Ja Herra käänsi itsensä ja katsoi Pietarin päälle, ja Pietari muisti Herran puheen, kuin hän hänelle sanoi: ennenkuin kukko laulaa, kolmasti sinä minun kiellät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 62, 'Ja Pietari meni ulos ja itki katkerasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 63, 'Mutta miehet, jotka Jesusta kiinni pitivät, pilkkasivat häntä ja löivät häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 64, 'Peittivät hänen silmänsä, ja löivät häntä poskelle, ja kysyivät häneltä, sanoen: arvaa, kuka se on, joka sinua löi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 65, 'Ja paljon muuta pilkkaa sanoivat he häntä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 66, 'Ja kuin päivä tuli, kokoontuivat kansan vanhimmat ja ylimmäiset papit ja kirjanoppineet ja veivät hänen oikeutensa eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 67, 'Sanoen: oletkos Kristus? sano meille. Niin hän sanoi heille: jos minä sanon teille, ette usko,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 68, 'Ja jos minä myös kysyn, niin ette vastaa minua, ette myös päästä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 69, 'Tästedes istuu Ihmisen Poika Jumalan voiman oikialla kädellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 70, 'Niin he sanoivat kaikki: sinä olet siis Jumalan Poika? sanoi hän heille: tepä sen sanotte, että minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 71, 'Niin he sanoivat: mitä me silleen todistusta tarvitsemme, sillä me olemme sen kuulleet hänen omasta suustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 1, 'Ja kaikki heidän joukkonsa nousi ylös, ja he veivät hänen Pilatuksen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 2, 'Ja he rupesivat kantamaan hänen päällensä, sanoen: tämän me löysimme kansaa viettelevän ja kieltävän keisarille veroa antamasta ja sanovan itsensä olevan kuninkaan Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 3, 'Niin Pilatus kysyi häneltä, sanoen: oletkos Juudalaisten kuningas? Hän vastasi häntä ja sanoi: sinäpä sen sanot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 4, 'Mutta Pilatus sanoi pappein päämiehille ja kansalle: en minä löydä yhtään vikaa tässä ihmisessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 5, 'Mutta he kävivät päälle, sanoen: hän kehoittaa kansan, opettain koko Juudeassa, ja on ruvennut Galileasta hamaan tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 6, 'Mutta kuin Pilatus kuuli Galileaa mainittavan, kysyi hän, josko hän Galileasta oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 7, 'Ja kuin hän ymmärsi, että hän Herodeksen läänistä oli, lähetti hän hänen Herodeksen tykö, joka myös silloin oli Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 8, 'Kuin Herodes näki Jesuksen, ihastui hän sangen suuresti; sillä hän oli jo kauvan aikaa häntä halainnut nähdäksensä, että hän oli paljon hänestä kuullut, ja toivoi häneltä jonkun ihmeen näkevänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 9, 'Ja kysyi häneltä moninaisista; mutta ei hän mitään häntä vastannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 10, 'Niin ylimmäiset papit ja kirjanoppineet seisoivat ja kantoivat kovin hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 11, 'Mutta Herodes huovinensa katsoi hänen ylön, ja pilkkasi häntä, pani hänen päällensä valkian vaatteen, ja lähetti jälleen Pilatuksen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 12, 'Sinä päivänä tuli Pilatus ja Herodes ystäviksi keskenänsä; sillä he olivat ennen vihamiehet olleet keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 13, 'Niin Pilatus kutsui kokoon ylimmäiset papit ja valtamiehet ja kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 14, 'Ja sanoi heille: te olette tämän ihmisen minulle tuoneet niinkuin kansan häiritsiän, ja katso, minä olen häntä tutkinut teidän edessänne ja en löydä yhtään vikaa tässä ihmisessä, joista te kannatte hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 15, 'Eikä Herodeskaan; sillä minä lähetin teidät hänen tykönsä, ja katso, ei häneltä yhtään hengen rikosta ole tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 16, 'Sentähden tahdon minä hänen rangaistuna päästää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 17, 'Mutta hänen piti joka juhlana päästämän heille yhden vallallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 18, 'Niin koko joukko huusi ja sanoi: ota tämä pois, ja päästä meille Barabbas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 19, 'Joka oli kapinan ja miestapoin tähden, kuin kaupungissa tapahtunut oli, vankiuteen heitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 20, 'Niin Pilatus taas puhui heille ja tahtoi Jesuksen päästää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 21, 'Mutta he huusivat sitä vastaan, sanoen: ristiinnaulitse, ristiinnaulitse häntä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 22, 'Mutta hän sanoi kolmannen kerran heille: mitäs hän pahaa teki? en minä löydä yhtään hengenrikosta hänessä: sentähden tahdon minä hänen rangaistuna päästää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 23, 'Mutta he kävivät päälle suurella äänellä, pyytäin häntä ristiinnaulittaa. Ja heidän ja ylimmäisten pappein ääni sai vallan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 24, 'Ja Pilatus tuomitsi heidän anomisensa jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 25, 'Ja päästi sen heille, joka kapinan ja miestapon tähden oli vankiuteen heitetty, jota he anoivat; mutta Jesuksen antoi hän heidän haltuunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 26, 'Ja kuin he hänen veivät ulos, käsittivät he yhden, Simonin Kyrenistä, joka maalta tuli, ja panivat hänen päällensä ristin, sitä Jesuksen jäljessä kantamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 27, 'Mutta häntä seurasi suuri joukko kansaa ja vaimoja, jotka häntä itkivät ja parkuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 28, 'Niin Jesus käänsi itsensä heidän puoleensa, ja sanoi: Jerusalemin tyttäret, älkäät minua itkekö, vaan itkekäät itse teitänne ja teidän lapsianne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 29, 'Sillä katso, päivät tulevat, joina he sanovat: autuaat ovat hedelmättömät, ja ne kohdat, jotka ei synnyttäneet, ja ne nisät, jotka ei imettäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 30, 'Silloin he rupeevat sanomaan vuorille: langetkaat meidän päällemme, ja kukkuloille: peittäkäät meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 31, 'Sillä jos he nämät tekevät tuoreessa puussa, mitä sitte kuivassa tapahtuu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 32, 'Niin vietiin myös hänen kanssansa kaksi muuta pahantekiää surmattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 33, 'Ja kuin he siihen siaan tulivat, joka Pääkallon paikaksi kutsutaan, siinä he hänen ristiinnaulitsivat ja ne pahantekiät, yhden oikialle ja toisen vasemmalle puolelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 34, 'Niin sanoi Jesus: Isä, anna heille anteeksi, sillä ei he tiedä, mitä he tekevät. Ja he jakoivat hänen vaatteensa ja heittivät niistä arpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 35, 'Ja kansa seisoi ja katseli, mutta päämiehet pilkkasivat häntä heidän kanssansa ja sanoivat: muita hän vapahti, vapahtakaan itsensä, jos hän on Kristus, Jumalan valittu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 36, 'Ja huovit myös pilkkasivat häntä, menivät ja kokottivat hänelle etikkaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 37, 'Ja sanoivat: jos olet Juudalaisten kuningas, niin vapahda itse sinus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 38, 'Oli myös hänestä päällekirjoitus Grekan, Latinan ja Hebrean puustaveilla kirjoitettu: Tämä on Juudalaisten kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 39, 'Niin yksi pahantekiöistä, jotka ripustetut olivat, pilkkasi häntä ja sanoi: jos sinä olet Kristus, niin vapahda sinus ja meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 40, 'Mutta toinen vastasi ja nuhteli häntä sanoen: etkö sinäkään Jumalaa pelkää, ettäs olet yhdessä kadotuksessa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 41, 'Ja tosin me olemme oikein siinä, sillä me saamme meidän töidemme ansion jälkeen; mutta ei tämä mitään pahaa tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 42, 'Ja sanoi Jesukselle: Herra, muista minua, kuin tulet valtakuntaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 43, 'Niin Jesus sanoi hänelle: totisesti sanon minä sinulle: tänäpänä pitää sinun oleman minun kanssani paradisissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 44, 'Ja se oli lähes kuudes hetki, ja pimeys tuli kaiken maan päälle, hamaan yhdeksänteen hetkeen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 45, 'Ja aurinko pimeni, ja templin esivaate repesi kahtia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 46, 'Ja Jesus huusi suurella äänellä ja sanoi: Isä, sinun käsiis minä annan henkeni. Ja kuin hän sen oli sanonut, antoi hän henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 47, 'Mutta kuin sadanpäämies näki, mitä tapahtui, kunnioitti hän Jumalaa ja sanoi: tosin oli tämä ihminen hurskas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 48, 'Ja kaikki kansa, joka sinne katselemaan meni, kuin he näkivät, mitä siellä tapahtui, löivät rintoihinsa ja palasivat kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 49, 'Mutta kaikki hänen tuttavansa seisoivat taampana ja vaimot, jotka häntä Galileasta seuranneet olivat, näkivät nämät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 50, 'Ja katso, raatimies, nimeltä Joseph, joka oli jalo ja hurskas mies,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 51, 'Joka ei ollut mieltynyt heidän neuvoonsa ja tekoonsa, syntynyt Arimatiassa, Juudalaisten kaupungissa, joka myös itse odotti Jumalan valtakuntaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 52, 'Tämä meni Pilatuksen tykö ja anoi Jesuksen ruumista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 53, 'Ja otti sen alas ja kääri liinavaatteesen ja pani sen hautaan, joka kallioon hakattu oli, johonka ei yksikään ennen pantu ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 54, 'Ja se oli valmistuspäivä, ja sabbati lähestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 55, 'Niin vaimot seurasivat jäljestä, jotka hänen kanssansa tulleet olivat Galileasta, ja katselivat hautaa, ja kuinka hänen ruumiinsa pantu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 56, 'Mutta he palasivat ja valmistivat hyvänhajuisia yrttejä ja voiteita; vaan sabbatina he lepäsivät lain käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 1, 'Mutta ensimäisenä sabbatin päivänä, sangen varhain, tulivat he haudalle ja kantoivat hyvänhajuisia yrttejä, jotka he olivat valmistaneet, ja muutamat heidän kanssansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 2, 'Niin he löysivät kiven haudalta vieritetyksi pois,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 3, 'Ja menivät siihen sisälle eikä löytäneet Herran Jesuksen ruumista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 4, 'Ja tapahtui, kuin he siitä epäilivät, katso, kaksi miestä seisoi heidän tykönänsä kiiltävissä vaatteissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 5, 'Niin he peljästyivät ja löivät kasvonsa maata päin. He sanoivat heille: miksi te elävää kuolleiden seassa etsitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 6, 'Ei hän ole täällä, mutta nousi ylös; muistakaat, kuinka hän teille sanoi, kuin hän vielä Galileassa oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 7, 'Sanoen: Ihmisen Poika pitää annettaman ylön syntisten ihmisten käsiin, ja ristiinnaulittaman, ja kolmantena päivänä nouseman ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 8, 'Ja he muistivat hänen sanansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 9, 'Ja palasivat jälleen haudalta ja ilmoittivat kaikki nämät yhdelletoistakymmenelle ja kaikille muille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 10, 'Ja ne olivat Maria Magdalena ja Johanna ja Maria, Jakobin äiti,ja muita heidän kanssansa, jotka näitä apostoleille ilmoittivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 11, 'Ja heidän puheensa näkyi heille houraukseksi, eikä he uskoneet heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 12, 'Mutta Pietari nousi ja juoksi haudalle, ja kuin hän kurkisti sisälle, näki hän ainoasti liinavaatteet pantuna, ja meni pois ihmetellen itsellänsä sitä, mikä tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 13, 'Ja katso, kaksi heistä meni sinä päivänä yhteen kylään, joka oli Jerusalemista kuudenkymmenen vakomitan päässä, Emaus nimeltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 14, 'Ja puhuivat keskenänsä kaikista niistä, mitkä tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 15, 'Ja tapahtui heidän puhuissansa ja tutkistellessansa keskenänsä, että Jesus itse heitä lähestyi ja matkusti heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 16, 'Mutta heidän silmänsä pidettiin, ettei he häntä tunteneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 17, 'Niin hän sanoi heille: mitkä puheet ne ovat, joita te pidätte keskenänne käydessänne, ja olette murheelliset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 18, 'Niin vastasi yksi, Kleopas nimeltä, ja sanoi hänelle: oletkos ainoa muukalainen Jerusalemissa, joka et tiedä, mitä siellä näinä päivinä tapahtui?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 19, 'Ja hän sanoi heille: mitä? He sanoivat hänelle: Jesuksesta Natsarealaisesta, joka oli väkevä propheta töissä ja sanoissa, Jumalan ja kaiken kansan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 20, 'Kuinka meidän ylimmäiset papit ja päämiehet antoivat ylön hänen kuoleman kadotukseen, ja ristiinnaulitsivat hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 21, 'Mutta me luulimme hänen siksi, joka Israelin piti lunastaman. Ja paitsi kaikkia näitä on jo kolmas päivä tänäpänä, kuin nämät tapahtuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 22, 'Mutta myös muutamat vaimot meistä ovat meitä peljättäneet, jotka varhain aamulla tulivat haudalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 23, 'Ja kuin ei löytäneet hänen ruumistansa, tulivat he ja sanoivat, että he enkeleinkin näyn nähneet olivat, jotka sanoivat hänen elävän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 24, 'Ja muutamat niistä, jotka meidän kanssamme olivat, menivät haudalle ja löysivät niinkuin vaimot olivat sanoneet; mutta ei he häntä nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 25, 'Ja hän sanoi heille: oi te tomppelit ja hitaan sydämestä uskomaan niitä kaikkia, mitä prophetat puhuneet ovat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 26, 'Eikö Kristuksen pitänyt näitä kärsimän ja kunniaansa käymän sisälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 27, 'Ja hän rupesi Moseksesta ja kaikista prophetaista, ja selitti heille kirjoitukset, jotka hänestä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 28, 'Ja he lähestyivät kylää, johonka he menivät, ja hän teetteli itsensä edemmä käymään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 29, 'Ja he vaativat häntä, sanoen: ole meidän kanssamme, sillä ehtoo joutuu ja päivä on laskenut; ja hän meni olemaan heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 30, 'Ja tapahtui, kuin hän atrioitsi heidän kanssansa, otti hän leivän, kiitti, mursi ja antoi heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 31, 'Niin heidän silmänsä aukenivat ja he tunsivat hänen. Ja hän katosi heidän edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 32, 'Ja he sanoivat keskenänsä: eikö meidän sydämemme meissä palanut, kuin hän tiellä meitä puhutteli ja selitti meille kirjoitukset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 33, 'Ja he nousivat sillä hetkellä ja palasivat Jerusalemiin, ja löysivät ne yksitoistakymmentä koossa ja ne, jotka niiden kanssa olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 34, 'Jotka sanoivat: Herra on totisesti noussut ylös ja ilmaantui Simonille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 35, 'Ja he juttelivat heille, mitä tiellä tapahtunut oli, ja kuinka hän heiltä oli tuttu leivän murtamisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 36, 'Mutta kuin he näitä puhuivat, seisoi itse Jesus heidän keskellänsä ja sanoi heille: rauha olkoon teille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 37, 'Niin he hämmästyivät ja peljästyivät, ja luulivat näkevänsä hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 38, 'Ja hän sanoi heille: mitä te pelkäätte? ja miksi senkaltaiset ajatukset tulevat sydämeenne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 39, 'Katsokaat käsiäni ja jalkojani, että minä itse olen: ruvetkaat minuun ja katsokaat; sillä ei hengellä ole lihaa eikä luita, niinkuin näette minulla olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 40, 'Ja kuin hän nämät sanonut oli, osoitti hän heille kätensä ja jalkansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 41, 'Mutta koska ei he vielä uskoneet ilon tähden, vaan ihmettelivät, sanoi hän heille: onko teillä tässä mitään syötävää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 42, 'Niin he panivat hänen eteensä kappaleen paistettua kalaa ja vähän kimalaisen hunajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 43, 'Ja hän otti sen ja söi heidän nähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 44, 'Niin hän sanoi heille: nämät ovat ne sanat, jotka minä puhuin teille, kuin minä vielä tiedän kanssanne olin; sillä kaikki pitää täytettämän, mitä kirjoitettu on Moseksen laissa ja prophetaissa ja psalmeissa minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 45, 'Silloin hän avasi heidän ymmärryksensä, kirjoituksia ymmärtämään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 46, 'Ja sanoi heille: niin on kirjoitettu, ja niin tuli Kristuksen kärsiä ja nousta kuolleista kolmantena päivänä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 47, 'Ja saarnattaman hänen nimeensä parannusta ja syntein anteeksi antamusta kaikissa kansoissa, ruveten Jerusalemista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 48, 'Mutta te olette näiden todistajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 49, 'Ja katso, minä lähetän minun Isäni lupauksen teidän päällenne. Mutta te olkaat Jerusalemissa siihenasti kuin te puetetaan voimalla korkeudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 50, 'Niin hän vei heidät ulos hamaan Betaniaan, ja nosti kätensä ja siunasi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 51, 'Ja tapahtui, kuin hän heitä siunannut oli, erkani hän heistä ja meni ylös taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 52, 'Mutta kuin he häntä kumartaneet ja rukoilleet olivat, palasivat he Jerusalemiin suurella ilolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 53, 'Ja olivat aina templissä, kiittivät ja kunnioittivat Jumalaa. Amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Alussa oli sana, ja se Sana oli Jumalan tykönä, ja Jumala oli se Sana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Tämä oli alussa Jumalan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Kaikki ovat sen kautta tehdyt, ja ilman sitä ei ole mitään tehty, joka tehty on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Hänessä oli elämä, ja elämä oli ihmisten valkeus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Ja valkeus paistaa pimeydessä, jota ei pimeys käsittänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Yksi mies oli lähetetty Jumalalta, jonka nimi oli Johannes:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Se tuli valkeudesta todistamaan, että kaikki uskoisivat hänen kauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Ei hän ollut valkeus, mutta hän oli lähetetty valkeudesta todistamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Se oli totinen valkeus, joka valistaa kaikki ihmiset, jotka maailmaan tulevat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Se oli maailmassa, ja maailma oli hänen kauttansa tehty, ja ei maailma häntä tuntenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Hän tuli omillensa, ja ei hänen omansa häntä ottaneet vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Mutta niille, jotka hänen ottivat vastaan, antoi hän voiman Jumalan lapsiksi tulla, jotka uskovat hänen nimensä päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Jotka ei verestä eikä lihan tahdosta ei myös miehen tahdosta, mutta Jumalasta syntyneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Ja Sana tuli lihaksi ja asui meidän seassamme, (ja me näimme hänen kunniansa niinkuin ainoan Pojan kunnian Isästä,) täynnä armoa ja totuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Johannes todisti hänestä, ja huusi, sanoen: tämä oli se, josta minä sanoin: minun jälkeeni on tuleva, joka minun edelläni on ollut; sillä hän oli ennen kuin minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Ja me olemme kaikki hänen täydellisyydestänsä saaneet ja armon armosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Sillä laki on Moseksen kautta annettu: armo ja totuus on Jesuksen Kristuksen kautta tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Ei ole kenkään koskaan Jumalaa nähnyt: ainokainen Poika, joka on Isän helmassa, hän ilmoitti meille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Ja tämä on Johenneksen todistus, kuin Juudalaiset lähettivät Jerusalemista papit ja Leviläiset kysymään häneltä: kukas olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Ja hän todisti ja ei kieltänyt, ja hän todisti, sanoen: en minä ole Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Ja he kysyivät häneltä: kukas siis? oletkos Elias? Hän sanoi: en. Oletkos propheta? Hän vastasi: en.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Niin he sanoivat hänelle: kukas olet? että me antaisimme niille vastauksen, jotka meidät lähettivät: mitäs sanot itsestäs?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Hän sanoi: minä olen huutava ääni korvessa: valmistakaat Herran tietä, niinkuin Jesaias propheta sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Ja jotka lähetetyt olivat, olivat Pharisealaisista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Ja he kysyivät häneltä ja sanoivat hänelle: miksi siis sinä kastat, jos et ole Kristus, etkä Elias, etkä propheta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 26, 'Johannes vastasi heitä ja sanoi: minä kastan vedellä; mutta teidän keskellänne seisoo, jota ette tunne:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 27, 'Hän on se, joka minun jälkeeni tulee, joka minun edelläni on ollut, jonka kengän rihmoja en minä ole kelvollinen päästämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 28, 'Nämät tapahtuivat Betabarassa, sillä puolella Jordania, kussa Johannes kasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 29, 'Toisena päivänä näki Johannes Jesuksen tykönsä tulevan, ja sanoi: katso, Jumalan Karitsa, joka pois ottaa maailman synnin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 30, 'Tämä on se, josta minä sanoin: minun jälkeeni tulee mies, joka minun edelläni on ollut; sillä hän oli ennen kuin minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 31, 'Ja en minä häntä tuntenut; mutta että hän ilmestyisi Israelissa, sentähden tulin minä vedellä kastamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 32, 'Ja Johannes todisti, sanoen: minä näin Hengen taivaasta tulevan alas niinkuin kyyhkyisen ja seisahtavan hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 33, 'Ja en minä häntä tuntenut; mutta joka minun lähetti vedellä kastamaan, se sanoi minulle: jonka päälle sinä näet Hengen tulevan alas ja seisahtavan hänen päällesä, hän on se, joka kastaa Pyhällä Hengellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 34, 'Ja minä näin sen ja todistin hänen olevan Jumalan Pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 35, 'Toisena päivänä seisoi Johannes taas ja kaksi hänen opetuslapsistansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 36, 'Ja kuin hän näki Jesuksen käyvän, sanoi hän: katso, Jumalan Karitsa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 37, 'Ja ne kaksi opetuslasta kuulivat hänen puhuvan, ja seurasivat Jesusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 38, 'Mutta Jesus käänsi itsensä ja näki ne seuraavan, ja sanoi heille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 39, 'Mitä te etsitte? Niin he sanoivat hänelle: Rabbi (se on niin paljo sanottu: opettaja) kussas asut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 40, 'Hän sanoi heille: tulkaat ja katsokaat; ja he tulivat ja näkivät, kussa hän asui, ja olivat sen päivän hänen tykönänsä, ja se oli lähes kymmenes hetki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 41, 'Andreas, Simon Pietarin veli, oli yksi niistä kahdesta, jotka sen Johannekselta kuulleet olivat ja häntä seurasivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 42, 'Tämä löysi ensin veljensä Simonin, ja sanoi hänelle: me löysimme Messiaan; se on niin paljo kuin: voideltu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 43, 'Ja hän toi hänen Jesuksen tykö. Mutta kuin Jesus katsoi hänen päällensä, sanoi hän: sinä olet Simon Jonan poika, ja sinä pitää kutsuttaman Kephas; se on niin paljo kuin: kallio.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 44, 'Toisena päivänä tahtoi Jesus mennä Galileaan, ja löysi Philippuksen ja sanoi hänelle: seuraa minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 45, 'Mutta Philippus oli Betsaidasta, Andreaksen ja Pietarin kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 46, 'Philippus löysi Natanaelin ja sanoi hänelle: me olemme löytäneet sen, josta Moses kirjoitti laissa ja prophetat, Jesuksen, Josephin pojan Natsaretista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 47, 'Ja Natanael sanoi hänelle: tulleeko Natsaretista jotain hyvää? Philippus sanoi hänelle: tule ja katso.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 48, 'Jesus näki Natanaelin tykönsä tulevan, ja sanoi hänestä: katso, totisesti oikia Israelilainen, jossa ei petosta ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 49, 'Natanael sanoi hänelle: mistäs minut tunnet? Jesus vastasi ja sanoi hänelle: ennen kuin Philippus kutsui sinua fikunapuun alla ollessas, näin minä sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 50, 'Vastasi Natanael ja sanoi hänelle: Rabbi, sinä olet Jumalan Poika, sinä olet Israelin kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 51, 'Jesus vastasi ja sanoi hänelle: sinä uskot, että minä sanoin sinulle: minä näin sinut fikunapuun alla. Sinä saat vielä suurempia nähdä. Ja sanoi hänelle: totisesti, totisesti sanon minä teille: tästedes pitää teidän näkemän taivaan avoinna, ja Jumalan enkelit astuvan ylös ja tulevan alas Ihmisen Pojan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Ja kolmantena päivänä olivat häät Galilean Kaanassa, ja Jesuksen äiti oli siellä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Niin Jesus ja hänen opetuslapsensa kutsuttiin myös häihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Ja kun viina puuttui, sanoi Jesuksen äiti hänelle: ei heillä ole viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Jesus sanoi hänelle: vaimo! mitä minun on sinun kanssas? ei minun aikani ole vielä tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Hänen äitinsä sanoi palvelijoille: mitä hän teille sanoo, se tehkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Niin siellä oli kuusi kivistä vesi-astiaa pantuna Juudalaisten puhdistamisen tavan jälkeen, ja kukin veti kaksi eli kolme mittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Jesus sanoi heille: täyttäkäät vesi-astiat vedellä. Ja he täyttivät ne ylen täyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Ja hän sanoi heille: pankaat nyt sisälle ja viekäät edeskäyvälle. Ja he veivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mutta kuin edeskäypä maisti sitä vettä, joka viinaksi tullut oli, (eikä tietänyt, kusta se tuli, mutta palveliat tiesivät, jotka veden ammensivat,) kutsui edeskäypä yljän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Ja sanoi hänelle: jokainen antaa ensisti hyvää viinaa, ja kuin juovutaan, niin sitte huonompaa: sinä kätkit hyvän viinan tähän asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Tämä on ensimäinen tunnustähti, jonka Jesus teki Galilean Kaanassa, ja ilmoitti kunniansa. Ja hänen opetuslapsensa uskoivat hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Sitte meni hän alas Kapernaumiin ja hänen äitinsä ja hänen veljensä ja hänen opetuslapsensa, eikä siellä kauvan viipyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Ja Juudalaisten pääsiäinen oli läsnä, ja Jesus meni ylös Jerusalemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Ja löysi templissä istuvan ne, jotka karjaa, lampaita ja kyykyläisiä myyskentelivät, ja vaihettajat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Ja hän teki ruoskan köysistä, ja ajoi ulos ne kaikki temppelistä ja lampaat ja karjan, ja heitti pois vaihettajain rahat ja maahan kukisti pöydät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Ja sanoi niille, jotka kyhkyisiä myivät: viekäät nämät täältä pois ja älkäät tehkö minun Isäni huonetta kauppahuoneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Mutta hänen opetuslapsensa muistivat kirjoitetuksi: sinun huonees kiivaus on minun syönyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Niin vastasivat Juudalaiset ja sanoivat hänelle: mitä merkkiä sinä meille osoitat, ettäs näitä teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Jesus vastasi ja sanoi heille: jaottakaat maahan tämä templi, ja minä tahdon sen kolmantena päivänä rakentaa ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Niin Juudalaiset sanoivat: tätä templiä on rakennettu kuusiviidettäkymmentä ajastaikaa, ja sinä rakennat sen kolmena päivänä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Mutta hän sanoi ruumiinsa templistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Kuin hän siis oli kuolleista noussut, muistivat hänen opetuslapsensa hänen sen heille sanoneeksi, ja uskoivat Raamatun ja puheen, minkä Jesus oli puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Mutta kuin hän pääsiäis-juhlapäivänä oli Jerusalemissa, uskoivat monta hänen nimensä päälle, kuin he näkivät ne tunnustähdet mitkä hän teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Mutta ei Jesus uskonut itsiänsä heille; sillä hän tunsi heidät kaikki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Ja ei tarvinnut, että joku olis ihmisestä todistanut; sillä hän tiesi, mitä ihmisessä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Niin oli yksi mies Pharisealaisista, Nikodemus nimeltä, Juudalaisten ylimmäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Se tuli yöllä Jesuksen tykö ja sanoi hänelle: Mestari, me tiedämme, että sinä olet Jumalasta opettajaksi tullut; sillä ei taida kenkään niitä tunnustähtiä tehdä, joita sinä teet, jollei Jumala ole hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Jesus vastasi ja sanoi hänelle: totisesti, totisesti sanon minä sinulle: ellei joku vastuudesta synny, ei hän taida Jumalan valtakuntaa nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Nikodemus sanoi hänelle: kuinka taitaa ihminen vanhana syntyä? taitaako hän äitinsä kohtuun jälleen mennä, ja syntyä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Jesus vastasi: totisesti, totisesti sanon minä sinulle: ellei joku synny vedestä ja Hengestä ei hän taida Jumalan valtakuntaan sisälle tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Mitä lihasta syntynyt on, se on liha, ja mitä Hengestä syntynyt on se on henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Älä ihmettele, että minä sanoin sinulle: teidän pitää uudesta syntymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Tuuli puhaltaa, kussa hän tahtoo, ja sinä kuulet hänen humunsa, ja et tiedä, kusta hän tulee taikka kuhunka hän menee: näin on jokainen, joka Hengestä syntynyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Vastasi Nikodemus ja sanoi hänelle: kuinka ne taitavat tapahtua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Jesus vastasi ja sanoi hänelle: sinä olet mestari Israelissa, ja et näitä tiedä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Totisesti, totisesti sanon minä sinulle: me puhumme, mitä me tiedämme, ja todistamme, mitä me näemme, ja ette ota vastaan meidän todistustamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Jos minä maallisia teille sanoin, ja ette usko: kuinka te uskoisitte, jos minä taivaallisia teille sanoisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Ei astu kenkään ylös taivaasen, vaan joka taivaasta astui alas, Ihmisen Poika, joka on taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ja niinkuin Moses ylensi kärmeen korvessa, niin myös Ihmisen Poika pitää ylennettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Että jokainen, joka uskoo hänen päällensä, ei pidä hukkuman, mutta ijankaikkisen elämän saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Sillä niin on Jumala maailmaa rakastanut, että hän antoi ainoan Poikansa, että jokainen, joka uskoo hänen päällensä, ei pidä hukkuman, mutta ijankaikkisen elämän saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Sillä ei Jumala lähettänyt Poikaansa maailmaan, tuomitsemaan maailmaa, mutta että maailma pitää hänen kauttansa vapahdettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Joka hänen päällensä uskoo, ei häntä tuomita; mutta joka ei usko, se on jo tuomittu; sillä ei hän uskonut Jumalan ainoan Pojan nimen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Mutta tämä on tuomio: että valkeus tuli maailmaan, ja ihmiset rakastivat enemmin pimeyttä kuin valkeutta; sillä heidän työnsä olivat pahat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Sillä jokainen, joka pahaa tekee, se vihaa valkeutta eikä tule valkeuteen, ettei hänen töitänsä pitäisi laitettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Mutta joka totuuden tekee, se tulee valkeuteen, että hänen työnsä nähtäisiin; sillä ne ovat Jumalassa tehdyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Sitte tuli Jesus ja hänen opetuslapsensa Juudean maahan, ja asui siellä heidän kanssansa, ja kasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 23, 'Mutta Johannes kasti myös Enonissa läsnä Salimia, sillä siellä oli palto vettä; ja he tulivat ja kastettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 24, 'Sillä ei Johannes ollut vielä silloin vankiuteen heitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 25, 'Niin tuli kysymys Johanneksen opetuslasten ja Juudalaisten välillä puhdistuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 26, 'Ja he tulivat Johanneksen tykö ja sanoivat hänelle: opettaja, se joka sinun kanssas oli toisella puolella Jordania, josta sinä todistit, katso, hän kastaa, ja jokainen menee hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 27, 'Johannes vastasi ja sanoi: ei ihminen taida mitään ottaa, ellei hänelle anneta taivaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 28, 'Te olette itse minun todistajani, että minä olen sanonut: en minä ole Kristus, vaan minä olen hänen edellänsä lähetetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 29, 'Jolla on morsian, se on ylkä; mutta yljän ystävä, joka seisoo ja kuultelee häntä, se iloittaa itsiänsä yljän äänestä sangen suuresti; sentähden on tämä minun iloni täytetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 30, 'Hänen tulee kasvaa, mutta minun pitää vähenemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 31, 'Joka ylhäältä tulee, se on kaikkein päällä, ja joka maasta on, se on maasta ja puhuu maasta. Joka taivaasta tulee, hän on kaikkein ylin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 32, 'Ja mitä hän nähnyt ja kuullut on, sen hän todistaa, ja ei kenkään ota vastaan hänen todistustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 33, 'Joka hänen todistuksensa otti vastaan, se päätti Jumalan olevan totisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 34, 'Sillä jonka Jumala lähetti, se puhuu Jumalan sanoja; sillä ei Jumala anna Henkeä mitalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 35, 'Isä rakastaa Poikaa, ja antoi kaikki hänen käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 36, 'Joka uskoo Pojan päälle, hänellä on ijankaikkinen elämä; mutta joka ei usko Pojan päälle, ei hänen pidä elämää näkemän, mutta Jumalan viha pysyy hänen päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Kuin siis Herra ymmärsi Pharisealaisten kuulleeksi, että Jesus teki enemmin opetuslapsia ja kasti kuin Johannes;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, '(Vaikka ei Jesus itse kastanut, mutta hänen opetuslapsensa,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Jätti hän Juudean ja meni jälleen Galileaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Mutta hänen piti Samarian kautta vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Niin hän tuli Samarian kaupunkiin, joka kutsuttiin Sikar, lähes sitä maakartanoa, jonka Jakob oli pojallensa Josephille antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Niin siellä oli Jakobin lähde. Kuin Jesus matkasta oli väsynyt, istui hän lähteen päälle, ja se oli liki kuudetta hetkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Niin tuli yksi Samarian vaimo vettä ammentamaan, ja Jesus sanoi hänelle: anna minun juodakseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Sillä hänen opetuslapsensa olivat menneet kaupunkiin ruokaa ostamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Sanoi Samarian vaimo hänelle: kuinka sinä minulta juoda anot, joka olet Juudalainen, ja minä olen Samarialainen? sillä ei Juudalaiset pidä yhtään kanssakäymistä Samarialaisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Jesus vastasi ja sanoi hänelle: jos sinä tietäisit Jumalan lahjan, ja kuka se on, joka sinulle sanoo: anna minun juodakseni! niin sinä anoisit häneltä, ja hän antaisi sinulle elävää vettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Sanoi vaimo hänelle: Herra, eipä sinulla ole, milläs ammennat, ja lähde on syvä: kusta siis sinulla on elävää vettä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Oletkos sinä suurempi kuin meidän isämme Jakob, joka meille tämän kaivon antoi? ja hän joi itse siitä, ja hänen lapsensa, ja hänen karjansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Jesus vastasi ja sanoi hänelle: jokainen, joka juo tästä vedestä, hän janoo jälleen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Mutta joka siitä vedestä juo, jonka minä hänelle annan, ei hän janoo ijankaikkisesti; vaan se vesi, jonka minä hänelle annan, tulee hänessä sen veden lähteeksi, joka kuohuu ijankaikkiseen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Sanoi vaimo hänelle: Herra, anna minulle sitä vettä, etten minä janoaisi enkä tarvitsisi tulla tänne ammentamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Jesus sanoi hänelle: mene, kutsu miehes, ja tule tänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Vaimo vastasi ja sanoi hänelle: ei minulla ole miestä. Sanoi Jesus hänelle: oikein sinä sanoit: ei minulla ole miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Sillä viisi miestä on sinulla ollut, ja se joka sinulla nyt on, ei ole sinun miehes. Sen sinä oikein sanoit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Vaimo sanoi hänelle: Herra, minä näen, että sinä olet propheta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 20, 'Meidän isämme ovat tällä vuorella kumartaneet ja rukoilleet, ja te sanotte: Jerusalemissa on se sia, jossa pitää rukoiltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 21, 'Jesus sanoi hänelle: vaimo, usko minua: se aika tulee, ettette tällä vuorella eikä Jerusalemissa Isää rukoile.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 22, 'Ette tiedä, mitä te rukoilette, mutta me tiedämme, mitä me rukoilemme; sillä autuus on Juudalaisista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 23, 'Mutta hetki tulee, ja jo nyt on, että totiset rukoiliat rukoilevat Isää hengessä ja totuudessa; sillä Isä tahtoo myös senkaltaisia, jotka häntä rukoilevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 24, 'Jumala on Henki, ja jotka häntä rukoilevat, niiden pitää hengessä ja totuudessa häntä rukoileman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 25, 'Vaimo sanoi hänelle: minä tiedän, että Messias on tuleva, joka kutsutaan Kristus: kuin hän tulee, niin hän ilmoittaa meille kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 26, 'Jesus sanoi hänelle: minä olen se, joka sinun kanssas puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 27, 'Silloin tulivat hänen opetuslapsensa ja ihmettelivät, että hän sitä vaimoa puhutteli: ei kuitenkaan kenkään sanonut: mitäs kysyt? eli mitäs häntä puhuttelet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 28, 'Niin vaimo jätti vesi-astiansa, ja meni kaupunkiin, ja sanoi niille ihmisille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 29, 'Tulkaa katsomaan sitä ihmistä, joka minulle sanoi kaikki, mitä minä tehnyt olen: olleeko hän Kristus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 30, 'Niin he läksivät kaupungista ja menivät hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 31, 'Mutta sillä välillä rukoilivat opetuslapset häntä, sanoen: Rabbi, syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 32, 'Vaan hän sanoi heille: minulla on ruokaa syödäkseni, jota ette tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 33, 'Niin opetuslapset sanoivat keskenänsä: lieneekö joku hänelle syötävää tuonut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 34, 'Jesus sanoi heille: minun ruokani on se, että minä teen hänen tahtonsa, joka minun lähetti, ja täytän hänen tekonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 35, 'Ettekö te sano: vielä ovat neljä kuukautta ja elonaika tulee? katso, minä sanon teille: nostakaat silmänne ylös ja katsokaat vainioita: sillä ne ovat jo valkiat elonajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 36, 'Ja joka niittää, hän saa palkan ja kokoo hedelmän ijankaikkiseen elämään: että kylväjä ja niittäjä ynnä iloitsisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 37, 'Sillä tässä on se sana tosi; toinen on, joka kylvää, ja toinen, joka niittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 38, 'Minä lähetin teidät niittämään, jossa ette ole työtä tehneet: muut ovat työtä tehneet ja te olette heidän työnsä päälle tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 39, 'Mutta monta Samarialaista siitä kaupungista uskoivat hänen päällensä sen vaimon puheen tähden, joka sanoi: hän on minulle kaikki sanonut, mitä minä tehnyt olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 40, 'Kuin siis Samarialaiset tulivat hänen tykönsä, rukoilivat he häntä viipymään heidän tykönänsä. Ja hän viipyi siellä kaksi päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 41, 'Ja paljo usiammat uskoivat hänen sanansa tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 42, 'Ja sanoivat sille vaimolle: emme nyt silleen usko sinun puhees tähden; sillä me olemme itse kuulleet ja tiedämme, että hän on totisesti Kristus, maailman Vapahtaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 43, 'Mutta kahden päivän perästä läksi hän sieltä ja meni Galileaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 44, 'Sillä Jesus todisti itse, ettei propheta maksa isänsä maalla mitään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 45, 'Kuin hän siis tuli Galileaan, ottivat Galilealaiset hänen vastaan, jotka olivat nähneet kaikki ne, mitä hän Jerusalemissa juhlana tehnyt oli: sillä he olivat myös juhlalle tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 46, 'Niin Jesus tuli taas Galilean Kaanaan, kussa hän meden viinaksi tehnyt oli. Ja oli kuninkaan mies, jonka poika sairasti Kapernaumissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 47, 'Kuin hän kuuli, että Jesus oli tullut Juudeasta Galileaan, meni hän hänen tykönsä ja rukoili häntä tulemaan alas ja parantamaan hänen poikansa, joka oli kuolemallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 48, 'Sanoi siis Jesus hänelle: ellette näe tunnustähtiä ja ihmeitä, niin ette usko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 49, 'Sanoi kuninkaan mies hänelle: Herra, tule alas ennenkuin minun poikani kuolee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 50, 'Jesus sanoi hänelle: mene, sinun poikas elää. Ja mies uskoi sanan, jonka Jesus sanoi hänelle, ja meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 51, 'Niin hänen mennessänsä, kohtasivat hänen palveliansa hänen ja ilmoittivat hänelle, sanoen: sinun poikas elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 52, 'Niin hän tutki heiltä hetkeä, jolla hän parani, ja he sanoivat hänelle: eilen seitsemännellä hetkellä antoi vilutauti hänen ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 53, 'Niin isä ymmärsi sen siksi hetkeksi, jolla Jesus sanoi hänelle: sinun poikas elää. Ja hän uskoi ja koko hänen huoneensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 54, 'Tämä on toinen tunnustähti, jonka Jesus teki tullessansa Juudeasta Galileaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Sitte oli Juudalaisten juhlapäivä, ja Jesus meni ylös Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Mutta Jerusalemissa on Lammasportin tykönä lammikko, joka Hebrean kielellä kutsutaan Betesda, jossa oli viisi vajaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Joissa makasi suuri joukko sairaita, sokeita, ontuvia, halvatuita, jotka veden liikuttamista odottivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'Sillä enkeli tuli alas määrätyllä ajalla lammikkoon ja sekoitti veden: joka siis ensimäisenä veteen astui, kuin se sekoitettu oli, niin se parani, ehkä missä ikänä taudissa hän oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Niin oli siellä mies, joka kahdeksanneljättäkymmentä ajastaikaa oli sairastanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Kuin Jesus hänen näki makaavan ja tunsi hänen jo kauvan sairastaneen, sanoi hän hänelle: tahdotkos tulla terveeksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Sairas vastasi häntä: Herra, ei ole minulla sitä ihmistä, joka minun vie, kuin vesi sekoitettu on, lammikkoon; mutta kuin minä tulen, niin on toinen minun edelläni siihen astunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Jesus sanoi hänelle: nouse, ota vuotees ja käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Ja kohta parani se ihminen, ja otti vuoteensa ja kävi. Ja se päivä oli sabbati.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Sanoivat siis Juudalaiset paratulle: nyt on sabbati, ei sinun sovi vuodetta kantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Hän vastasi heitä: joka minun paransi, se sanoi minulle: ota vuotees ja käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Niin he kysyivät häneltä: kuka on se ihminen, joka sinulle sanoi: ota vuotees ja käy?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Mutta ei parattu tietänyt, kuka se oli; sillä Jesus oli mennyt pois kansan tähden, joka siinä paikassa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Sitte löysi Jesus hänen templissä ja sanoi hänelle: katso, sinä olet parattu: älä silleen syntiä tee, ettei jotain pahempaa sinulle tapahtuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 15, 'Niin se ihminen meni pois ja ilmoitti Juudalaisille, että Jesus oli se, joka hänen parantanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 16, 'Ja Juudalaiset vainosivat sentähden Jesusta ja etsivät häntä tappaaksensa, että hän senkaltaisia teki sabbatina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 17, 'Niin Jesus vastasi heitä: minun isäni tekee työtä hamaan tähän asti, ja minä myös teen työtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 18, 'Sentähden etsivät Juudalaiset häntä vielä enemmin tappaaksensa, ettei hän ainoastaan sabbatia rikkonut, mutta myös sanoi Jumalan isäksensä, ja teki itsensä Jumalan kaltaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 19, 'Niin Jesus vastasi ja sanoi heille: totisesti, totisesti sanon minä teille: ei taida Poika itsestänsä mitään tehdä, ellei hän näe Isän tekevän; sillä mitä ikänä hän tekee, sitä myös Poika niin tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 20, 'Sillä Isä rakastaa Poikaa ja osoittaa hänelle kaikki, mitä hän itse tekee, ja hän on vielä suurempia töitä hänelle osoittava, kuin nämät ovat, että teidän pitää ihmettelemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 21, 'Sillä niinkuin Isä herättää ja virvoittaa kuolleita, niin myös Poika virvoittaa, joita hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 22, 'Sillä ei Isä ketään tuomitse, vaan antoi kaiken tuomion Pojalle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 23, 'Että kaikki Poikaa kunnioittaisivat, niinkuin he Isää kunnioittavat. Joka ei Poikaa kunnioita, ei se kunnioita Isää, joka hänen lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 24, 'Totisesti, totisesti sanon minä teille: joka kuulee minun sanani ja uskoo sen, joka minun lähetti, hänellä on ijankaikkinen elämä, ja ei hän tule tuomioon, vaan menee kuolemasta elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 25, 'Totisesti, totisesti sanon minä teille: hetki tulee, ja nyt jo on, että kuolleet saavat kuulla Jumalan Pojan äänen; ja jotka sen kuulevat, ne saavat elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 26, 'Sillä niinkuin Isällä on elämä itsessänsä, niin antoi hän myös elämän Pojalle itsessänsä olemaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 27, 'Ja on hänellä myös antanut vallan tuomita, että hän on Ihmisen Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 28, 'Älkää tätä ihmetelkö; sillä hetki tulee, jona kaikki ne, jotka haudoissa ovat, saavat kuulla hänen äänensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 29, 'Ja pitää tuleman edes ne, jotka hyvää tehneet ovat, elämän ylösnousemiseen, mutta jotka pahaa tehneet ovat, tuomion ylösnousemiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 30, 'En minä itsestäni taida mitään tehdä: niinkuin minä kuulen, niin minä tuomitsen, ja minun tuomioni on oikia; sillä en minä etsi minun tahtoani, vaan Isän tahtoa, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 31, 'Jos minä itsestäni todistaisin, niin ei minun todistukseni olisi tosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 32, 'Toinen on, joka todistaa minusta, ja minä tiedän, että hänen todistuksensa on tosi, jonka hän minusta todistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 33, 'Te lähetitte Johanneksen tykö, ja hän todisti totuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 34, 'Mutta en minä ihmiseltä todistusta ota; vaan minä sanoin näitä, että te autuaaksi tulisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 35, 'Hän oli palavainen ja paistavainen kynttilä; mutta te tahdoitte ainoastaan vähän aikaan riemuita hänen valkeudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 36, 'Mutta minulla on suurempi todistus kuin Johanneksen; sillä ne työt, jotka Isä antoi minulle täyttääkseni, ne työt, jotka minä teen, todistavat minusta, että Isä minun lähetti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 37, 'Ja Isä, joka minun lähetti, hän todistaa minusta. Ette ole koskaan hänen ääntänsä kuulleet eli hänen muotoansa nähneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 38, 'Ja ei teillä ole hänen sanansa pysyväinen; sillä ette usko sitä, jonka hän lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 39, 'Tutkikaat Raamatuita; sillä niissä te luulette teillänne ijankaikkisen elämän olevan, ja ne ovat, jotka todistavat minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 40, 'Ja ette tahdo tulla minun tyköni, että te saisitte elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 41, 'En minä pyydä kunniaa ihmisiltä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 42, 'Vaan minä tunnen teidät, ettei teissä ole Jumalan rakkaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 43, 'Minä tulin Isäni nimeen, ja ette minua ota vastaan; jos joku tulee omalla nimellänsä, niin te sen otatte vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 44, 'Kuinka te taidatte uskoa, jotka otatte kunnian toinen toiseltanne, ja sitä kunniaa, joka ainoalta Jumalalta tulee, ette etsi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 45, 'Älkäät luulko, että minä minä kannan Isän edessä teidän päällenne: se on, joka teidän päällenne kantaa, Moses, johonka te turvaatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 46, 'Sillä jos te olisitte Moseksen uskoneet, niin te olisitte minun uskoneet; sillä minusta on hän kirjoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 47, 'Jos ette hänen kirjoituksiansa usko, kuinkas te minun sanani uskotte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 1, 'Sitte meni Jesus Galilean meren ylitse, joka on Tiberiaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 2, 'Ja häntä seurasi paljo kansaa, että he näkivät hänen merkkinsä, joita hän teki sairaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 3, 'Niin Jesus meni ylös vuorelle ja istui siellä opetuslastensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 4, 'Ja lähestyi pääsiäinen, Juudalaisten juhla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 5, 'Kuin siis Jesus nosti silmänsä ja näki tulevan paljon kansaa tykönsä, sanoi hän Philippukselle: kusta me ostamme leipiä näiden syödä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 6, '(Mutta sen hän sanoi, kiusaten häntä: sillä hän tiesi, mitä hän tekevä oli.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 7, 'Vastasi Philippus häntä: kahdensadan penningin leivät ei täytyisi heille, että kukin heistä vähänkin sais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 8, 'Sanoi yksi hänen opetuslapsistansa hänelle: Andreas, Simon Pietarin veli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 9, 'Tässä on poikainen, jolla on viisi ohrasta leipää ja kaksi kalaista; vaan mitä ne ovat näin paljolle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 10, 'Mutta Jesus sanoi: asettakaat kansa atrioitsemaan. ja siinä paikassa oli paljo ruohoa. Niin atrioitsi lähes viisituhatta miestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 11, 'Ja Jesus otti leivät, kiitti ja antoi opetuslapsille, mutta opetuslapset jakoivat atrioitseville, niin myös kaloista niin paljo kuin hän tahtoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 12, 'Mutta kuin he ravitut olivat, sanoi hän opetuslapsillensa: kootkaat murut, jotka jäivät, ettei mitään hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 13, 'Niin he kokosivat ja täyttivät kaksitoistakymmentä koria muruilla, viidestä ohraisesta leivästä, jotka niiltä liiaksi olivat, jotka atrioitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 14, 'Kuin siis ne ihmiset sen merkin näkivät, minkä Jesus teki, sanoivat he: tämä on totisesti se Propheta, joka maailmaan tuleva oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 15, 'Kuin Jesus ymmärsi, että he tahtoivat tulla ja väkivallalla tehdä hänen kuninkaaksi, meni hän pois taas vuorelle yksinänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 16, 'Mutta kuin ehtoo tuli, menivät hänen opetuslapsensa alas meren tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 17, 'Ja astuivat haahteen ja menivät ylitse meren Kapernaumia päin. Ja jo oli pimiä tullut, ja ei Jesus tullut heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 18, 'Niin meri nousi, että suuri tuuli puhalsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 19, 'Ja kuin he olivat soutaneet lähes viisikolmattakymmentä eli kolmekymmentä vakomittaa, näkivät he Jesuksen käyvän meren päällä ja lähenevän haahta; ja he peljästyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 20, 'Niin hän sanoi heille: minä olen; älkäät peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 21, 'Niin he tahtoivat ottaa hänen haahteen; ja haaksi oli jo sen maan tykönä, johonka he menivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 22, 'Toisena päivänä, kuin kansa, joka sillä puolella merta oli, näki, ettei siellä muuta venhettä ollut kuin se yksi, johonka hänen opetuslapsensa olivat astuneet, ja ettei Jesus ollut astunut haahteen opetuslastensa kanssa, vaan hänen opetuslapsensa olivat ainoastaan matkaan lähteneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 23, 'Mutta muut venheet tulivat Tiberiaasta, lähes sitä paikkaa, jossa he olivat leipää syöneet, sitte kuin Herra oli kiittänyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 24, 'Koska kansa sen näki, ettei Jesus siellä ollut eikä hänen opetuslapsensa, astuivat he myös haaksiin ja menivät Kapernaumiin etsein Jesusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 25, 'Ja kuin he hänen siltä puolen merta löysivät, sanoivat he hänelle: Rabbi, koskas tänne tulit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 26, 'Jesus vastasi heitä ja sanoi: totisesti, totisesti sanon minä teille: ette etsi minua, että te näitte ihmeen, vaan että te saitte leipää syödä ja olette ravitut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 27, 'Älkäät tehkö sitä ruokaa, joka on katoovainen, vaan sitä ruokaa, joka pysyy ijankaikkiseen elämään, jonka Ihmisen Poika teille antava on; sillä Isä Jumala on sen vahvistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 28, 'Niin he sanoivat hänelle: mitä meidän pitää tekemän, että me taitaisimme Jumalan töitä tehdä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 29, 'Jesus vastasi ja sanoi heille: se on Jumalan työ, että te uskotte sen päälle, jonka hän lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 30, 'Niin he sanoivat hänelle: mitä ihmettä siis sinä teet, että me näkisimme ja uskoisimme sinun päälles? Mitä työtä sinä teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 31, 'Meidän isämme söivät mannaa korvessa, niinkuin kirjoitettu on: hän antoi heille leipää taivaasta syödäksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 32, 'Niin Jesus sanoi heille: totisesti, totisesti sanon minä teille: ei Moses sitä leipää antanut teille taivaasta; mutta minun Isäni antaa totisen leivän taivaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 33, 'Sillä Jumalan leipä on se, joka taivaasta tulee alas ja antaa maailmalle elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 34, 'Niin he sanoivat hänelle: Herra, anna meille aina sitä leipää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 35, 'Jesus sanoi heille: minä olen elämän leipä: joka tulee minun tyköni, ei hän suinkaan isoo, ja joka uskoo minun päälleni, ei hän koskaan janoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 36, 'Mutta minä sanoin teille, että te näitte minun, ette sittekään usko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 37, 'Kaikki, mitä minun Isäni antaa minulle, se tulee minun tyköni: ja joka minun tyköni tulee, sitä en minä heitä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 38, 'Sillä minä tulin taivaasta alas, en tekemään minun tahtoani, vaan sen tahtoa, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 39, 'Mutta se on Isän tahto, joka minun lähetti, ettei minun pidä yhtäkään niistä kaikista kadottaman, jotka hän minulle antoi, mutta olen ne herättävä viimeisenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 40, 'Tämä on sen tahto, joka minun lähetti, että jokainen joka näkee Pojan ja uskoo hänen päällensä, hänellä pitää ijankaikkinen elämä oleman, ja minä herätän hänen viimeisenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 41, 'Niin Juudalaiset napisivat sitä, kuin hän sanoi: minä olen se leipä, joka taivaasta tuli alas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 42, 'Ja sanoivat: eikö tämä ole Jesus, Josephin poika, jonka isän ja äidin me tunnemme? Kuinkas hän sanoo: minä olen tullut taivaasta alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 43, 'Niin Jesus vastasi ja sanoi heille: älkäät napisko keskenänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 44, 'Ei taida kenkään minun tyköni tulla, ellei Isä, joka minun lähetti, vedä häntä, ja minä herätän hänen viimeisenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 45, 'Se on prophetaissa kirjoitettu: heidän pitää kaikki Jumalalta opetetuksi tuleman. Sentähden jokainen, joka sen on Isältä kuullut ja oppinut, hän tulee minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 46, 'Ei niin, että joku on Isän nähnyt, vaan joka on Jumalasta, se on Isän nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 47, 'Totisesti, totisesti sanon minä teille: joka uskoo minun päälleni, hänellä on ijankaikkinen elämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 48, 'Minä olen elämän leipä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 49, 'Teidän isänne söivät mannaa korvessa ja kuolivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 50, 'Tämä on se leipä, joka taivaasta tuli alas, ja joka siitä syö, ei hänen pidä kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 51, 'Minä olen elävä leipä, joka taivaasta tuli alas: se joka tästä leivästä syö, hän elää ijankaikkisesti. Ja se leipä, jonka minä annan, on minun lihani, jonka minun pitää antaman maailman elämän edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 52, 'Niin Juudalaiset riitelivät keskenänsä, sanoen: kuinka tämä taitaa antaa lihansa meille syödä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 53, 'Jesus sanoi heille: totisesti, totisesti sanon minä teille: ellette syö Ihmisen Pojan lihaa ja juo hänen vertansa, niin ei ole elämä teissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 54, 'Joka syö minun lihani ja juo minun vereni, hänellä on ijankaikkinen elämä, ja minä olen herättävä hänen viimeisenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 55, 'sillä minun lihani on totinen ruoka, ja minun vereni on totinen juoma.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 56, 'Joka syö minun lihani ja juo minun vereni, hän on minussa ja minä hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 57, 'Niinkuin elävä Isä minun lähetti ja minä elän Isäni tähden, niin myös se, joka minua syö, hän elää minun tähteni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 58, 'Tämä on se leipä, joka taivaasta tuli alas: ei niinkuin teidän isänne söivät mannaa ja kuolivat: Joka tätä leipää syö, hän saa elää ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 59, 'Näitä sanoi hän synagogassa, opettaissansa Kapernaumissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 60, 'Niin monta hänen opetuslapsistansa, kuin he tämän kuulivat, sanoivat: tämä on kova puhe: kuka voi sitä kuulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 61, 'Mutta kuin Jesus tiesi itsestänsä, että hänen opetuslapsensa siitä napisivat, sanoi hän heille: pahoittaako tämä teitä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 62, 'Mitä sitte, jos te näette Ihmisen Pojan sinne menevän ylös, kussa hän ennen oli?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 63, 'Henki on se, joka eläväksi tekee, ei liha mitään auta: ne sanat, jotka minä teille puhun, ovat henki ja elämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 64, 'Mutta muutamat teistä ovat, jotka ei usko. Sillä Jesus tiesi alusta, kutka ovat, jotka ei uskoneet, ja kuka hänen oli pettävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 65, 'Ja hän sanoi: sentähden sanoin minä teille: ei taida kenkään tulla minun tyköni, ellei se ole annettu hänelle minun Isältäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 66, 'Siitä ajasta luopuivat monta hänen opetuslastansa hänestä ja menivät pois, eikä hänen kanssansa enempi vaeltaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 67, 'Niin Jesus sanoi niille kahdelletoistakymmenelle: ettekö te myös tahdo mennä pois?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 68, 'Simon Pietari vastasi häntä: Herra, kenenkäs tykö me menemme? sinulla on ijankaikkisen elämän sanat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 69, 'Ja me uskomme ja olemme ymmärtäneet, että sinä olet Kristus, elävän Jumalan Poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 70, 'Jesus vastasi heitä: enkö minä ole teitä kahtatoistakymmentä valinnut? ja yksi teistä on perkele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 71, 'Mutta sen hän sanoi Juudaasta, Simonin pojasta Iskariotista; sillä hän oli hänen pettävä, ja oli yksi niistä kahdestatoistakymmenestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 1, 'Ja sitte vaelsi Jesus Galileassa; sillä ei hän tahtonut vaeltaa Juudeassa, että Juudalaiset pyysivät häntä tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 2, 'Niin Juudalaisten lehtimajan juhla oli läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 3, 'Ja hänen veljensä sanoivat hänelle: lähde täältä ja mene Juudeaan, että myös sinun opetuslapses näkisivät sinun työs, joita sinä teet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 4, 'Sillä ei kenkään tee mitään salaa, ja tahtoo itse julki olla. Jos siis sinä näitä teet, niin julista itses maailman edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 5, 'Sillä ei hänen veljensäkään uskoneet hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 6, 'Niin Jesus sanoi heille: ei ole minun aikani vielä tullut; vaan teidän aikanne on aina valmis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 7, 'Ei maailma taida teitä vihata, mutta minua hän vihaa; sillä minä todistan hänestä, että hänen työnsä ovat pahat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 8, 'Menkäät te ylös juhlalle: en minä vielä tälle juhlalle mene, sillä ei minun aikani ole vielä täytetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 9, 'Ja kuin hän näitä heille puhunut oli, niin hän jäi Galileaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 10, 'Mutta kuin hänen veljensä olivat menneet ylös, meni hän myös juhlalle, ei julki, vaan niinkuin salaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 11, 'Niin Juudalaiset etsivät häntä juhlana ja sanoivat: kussa hän on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 12, 'Ja suuri napina oli hänestä kansan seassa; sillä muutamat sanoivat: hän on hyvä, mutta toiset sanoivat: ei, vaan hän viettelee kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 13, 'Ei kuitenkaan yksikään hänestä julkisesti puhunut; sillä he pelkäsivät Juudalaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 14, 'Mutta kuin jo puoli juhlaa oli kulunut, meni Jesus ylös templiin, ja opetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 15, 'Ja Juudalaiset ihmettelivät, sanoen: kuinka tämä taitaa kirjaa, joka ei ole oppinut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 16, 'Vastasi Jesus ja sanoi heille: ei minun oppini ole minun, mutta sen, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 17, 'Jos joku tahtoo tehdä hänen tahtonsa, niin hänen pitää tietämän tästä opista, josko se on Jumalasta, eli jos minä itsestäni puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 18, 'Joka itsestänsä puhuu, se etsii omaa kunniaansa: mutta joka etsii sen kunniaa, joka hänen lähetti, se on vakaa ja ei hänessä ole vääryyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 19, 'Eikö Moses antanut teille lakia, ja ei kenkään teistä lakia taytä? Miksi te etsitte minua tappaaksenne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 20, 'Vastasi kansa ja sanoi: sinulla on perkele: kuka sinua etsii tappaaksensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 21, 'Jesus vastasi ja sanoi heille: yhden työn minä tein, ja te kaikki ihmettelette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 22, 'Sentähden antoi Moses teille ympärileikkauksen, (ei että se Mosekselta oli, vaan isiltä), ja te ympärileikkaatte sabbatina ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 23, 'Jos ihminen sabbatina ympärileikataan, ettei Moseksen laki rikottaisi: närkästyttekö te minusta, että minä koko ihmisen sabbatina paransin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 24, 'Älkäät tuomitko näkemisen jälkeen, vaan sanokaat oikia tuomio.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 25, 'Sanoivat siis muutamat Jerusalemin asuvaisista: eikö tämä se ole, jota he etsivät tappaaksensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 26, 'Ja katso, hän puhuu rohkiasti, ja ei he hänelle mitään puhu: tietänevätkö ylimmäiset oikein, että hän on totisesti Kristus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 27, 'Mutta me kyllä tiedämme, kusta tämä on: vaan kusta Kristus tulee ja kusta hän on, ei kenkään tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 28, 'Niin Jesus huusi templissä, opetti ja sanoi: ja te tunnette minun, ja tiedätte, kusta minä olen: ja en minä ole tullut itsestäni, mutta hän on vakaa, joka minun lähetti, jota ette tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 29, 'Mutta minä tunnen hänen, sillä minä olen hänestä, ja hän lähetti minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 30, 'Niin he etsivät häntä käsittääksensä; vaan ei kenkään laskenut kättänsä hänen päällensä, sillä ei hänen aikansa ollut vielä tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 31, 'Mutta paljo kansasta uskoivat hänen päällensä ja sanoivat: kuin Kristus tulee, tehneekö hän enemmän ihmeitä kuin tämä on tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 32, 'Pharisealaiset kuulivat kansan hänestä senkaltaisia napisevan, ja Pharisealaiset ja ylimmäiset papit lähettivät palveliat häntä ottamaan kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 33, 'Niin Jesus sanoi heille: minä olen vielä vähän aikaa teidän kanssanne, ja menen sitte hänen tykönsä, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 34, 'Teidän pitää minua etsimän ja ei löytämän, ja kussa minä olen, ette taida sinne tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 35, 'Niin Juudalaiset sanoivat keskenänsä: kuhunkas hän menee, ettemme häntä löydä? meneekö hän Grekiläisten sekaan, jotka sinne ja tänne hajoitetut ovat, Grekiläisiä opettamaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 36, 'Mikä puhe se on, minkä hän sanoi: teidän pitää etsimän minua ja ei löytämän, ja kussa minä olen, ette taida sinne tulla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 37, 'Mutta viimeisenä suurena juhlapäivänä seisoi Jesus ja huusi, sanoen: joka janoo, se tulkaan minun tyköni ja juokaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 38, 'Joka uskoo minun päälleni, niinkuin Raamattu sanoo, hänen kohdustansa pitää vuotaman elämän veden virrat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 39, '(Mutta sen hän sanoi siitä hengestä, jonka niiden piti saaman, jotka uskovat hänen päällensä; sillä ei Pyhä Henki vielä silloin saapuvilla ollut, ettei Jesus ollut vielä kirkastettu.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 40, 'Monta siis kansasta, jotka tämän puheen kuulivat, sanoivat: tämä on totisesti propheta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 41, 'Muut sanoivat: tämä on Kristus; mutta muutamat sanoivat: tulleeko Kristus Galileasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 42, 'Eikö Raamattu sano Davidin siemenestä ja Betlehemin kaupungista, kussa David oli, Kristuksen tulevan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 43, 'Niin nousi riita kansan seassa hänen tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 44, 'Mutta muutamat tahtoivat hänen ottaa kiinni, ja ei kuitenkaan kenkään laskenut käsiänsä hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 45, 'Niin palveliat tulivat Pharisealaisten ja ylimmäisten pappein tykö, ja he sanoivat heille: miksi ette häntä tänne tuoneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 46, 'Palveliat vastasivat: ei ole ihminen ikänä niin puhunut kuin se ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 47, 'Pharisealaiset vastasivat heitä: oletteko te myös vietellyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 48, 'Onko joku päämiehistä taikka Pharisealaisista uskonut hänen päällensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 49, 'Vaan tämä kansa, joka ei tiedä lakia, on kirottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 50, 'Niin sanoi heille Nikodemus, joka yöllä oli hänen tykönsä tullut, ja oli yksi heistä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 51, 'Tuomitseeko meidän lakimme jonkun ihmisen, ennenkuin kuullaan eli tietää saadaan, mitä hän teki?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 52, 'He vastasivat ja sanoivat hänelle: oletko sinäkin Galilealainen? tutki ja näe, ettei Galileasta ole yhtään prophetaa tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 53, 'Ja niin kukin meni kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 1, 'Mutta Jesus meni Öljymäelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 2, 'Ja tuli varhain huomeneltain jälleen templiin ja kaikki kansa tuli hänen tykönsä, ja hän istui ja opetti heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 3, 'Mutta kirjanoppineet ja Pharisealaiset toivat vaimon hänen tykönsä huoruudesta otetun kiinni. Ja kuin he olivat sen hänen eteensä asettaneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 4, 'Sanoivat he hänelle: Mestari, tämä vaimo on löydetty itse työssä, kuin hän teki huorin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 5, 'Mutta Moses on laissa meitä käskenyt, että senkaltaiset kivillä surmattaisiin. Mitäs sinä sanot?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 6, 'Mutta sen he sanoivat, kiusaten häntä, kantaaksensa hänen päällensä. Mutta Jesus kumarsi ja kirjoitti sormellansa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 7, 'Mutta kuin he seisoivat kysymyksensä päälle, ojensi hän itsensä ja sanoi heille: joka teistä on synnitön, se heittäkään ensin häntä kivellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 8, 'Ja hän kumarsi taas ja kirjoitti maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 9, 'Kuin he tämän kuulivat ja olivat omaltatunnoltansa voitetut, läksivät he ulos yksittäin, ruveten vanhimmista, viimeisiin asti; ja Jesus jäi yksinänsä, ja vaimo seisoi siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 10, 'Mutta kuin Jesus ojensi itsensä, ja ei nähnyt ketään paitsi vaimoa, sanoi hän hänelle: vaimo, kussa ovat sinun päällekantajas? Onko sinua kenkään tuominnut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 11, 'Hän sanoi: Herra, ei kenkään. Niin Jesus sanoi: en minä myös sinua tuomitse: mene, ja älä silleen syntiä tee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 12, 'Niin Jesus puhui taas heille ja sanoi: minä olen maailman valkeus: joka minua seuraa, ei hän pimeydessä vaella, mutta saa elämän valkeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 13, 'Pharisealaiset sanoivat hänelle: sinä todistat itsestäs; ei sinun todistukses ole tosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 14, 'Jesus vastasi ja sanoi heille: vaikka minä itsestäni todistan, niin minun todistukseni on tosi; sillä minä tiedän, kusta minä tulin ja kuhunka minä menen; mutta ette tiedä, kusta minä tulin ja kuhunka minä menen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 15, 'Te tuomitsette lihan jälkeen, en minä ketään tuomitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 16, 'Ja vaikka minä tuomitsisin, niin minun tuomioni on tosi; sillä en minä ole yksinäni, vaan minä ja Isä, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 17, 'Ja teidän laissanne on myös kirjoitettu, että kahden ihmisen todistus on tosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 18, 'Minä olen se, joka itsestäni todistan, ja Isä, joka minun lähetti, todistaa myös minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 19, 'Niin he sanoivat hänelle: kussas Isäs on? Jesus vastasi: ette tunne minua ettekä minun Isääni: jos te tuntisitte minun, niin te tuntisitte myös minun Isäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 20, 'Nämät sanat puhui Jesus uhri-arkun tykönä, opettain tenplissä, ja ei häntä kenkään ottanut kiinni; sillä ei hänen aikansa ollut vielä tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 21, 'Niin Jesus sanoi taas heille: minä menen pois, ja te etsitte minua, ja teidän pitää kuoleman teidän synneissänne. Kuhunka minä menen, ette sinne taida tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 22, 'Niin sanoivat Juudalaiset; tappaneeko hän itsensä, sillä hän sanoo: kuhunka minä menen, ette sinne taida tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 23, 'Ja hän sanoi heille: te olette alhaalta, ja minä olen ylhäältä: te olette maailmasta, en minä ole maailmasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 24, 'Sentähden sanoin minä teille: teidän pitää kuoleman synneissänne; sillä jos ette usko, että minä se olen, niin teidän pitää kuoleman synneissänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 25, 'Niin he sanoivat hänelle: kuka sinä olet? Jesus sanoi heille: se kuin minä alusta puhuin teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 26, 'Minulla on paljon teistä puhumista ja tuomitsemista, vaan se on totinen, joka minun lähetti; ja mitä minä olen häneltä kuullut, niitä minä puhun maailmalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 27, 'Mutta ei he ymmärtäneet, että hän puhui heille Isästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 28, 'Sanoi siis Jesus heille: kuin te olette Ihmisen Pojan ylentäneet, niin te ymmärrätte, että minä se olen, ja etten minä tee itsestäni mitään, vaan niinkuin Isä on minun opettanut, niitä minä puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 29, 'Ja se, joka minun lähetti, on minun kanssani. Ei Isä jättänyt minua yksinäni, sillä minä teen aina niitä, mitkä hänelle kelvolliset ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 30, 'Kuin hän näitä puhui, niin moni uskoi hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 31, 'Niin Jesus sanoi niille Juudalaisille, jotka hänen uskoivat: jos te pysytte minun puheessani, niin te totisesti minun opetuslapseni olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 32, 'Ja teidän pitää totuuden ymmärtämän, ja totuuden pitää teidät vapahtaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 33, 'Niin he vastasivat häntä: me olemme Abrahamin siemen, emmekä ole koskaan kenenkään orjina olleet; kuinka siis sinä sanot: teidän pitää vapaiksi tuleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 34, 'Jesus vastasi heitä ja sanoi: totisesti, totisesti sanon minä teille: jokainen, joka tekee syntiä, hän on synnin orja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 35, 'Mutta ei orja pysy ijankaikkisesti huoneessa; vaan Poika pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 36, 'Jos siis Poika teidät vapaiksi tekee, niin te totisesti olette vapaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 37, 'Minä tiedän, että te olette Abrahamin siemen, vaan te etsitte kuolettaaksenne minua; sillä ei minun puheellani ole teissä siaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 38, 'Minä puhun, mitä minä olen isäni tykönä nähnyt, ja te teette, mitä te olette nähneet teidän isänne tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 39, 'He vastasivat ja sanoivat hänelle: Abraham on meidän isämme. Jesus sanoi heille: jos te olisitte Abrahamin lapset: niin te tekisitte Abrahamin töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 40, 'Mutta nyt te etsitte minua tappaaksenne, sitä ihmistä, joka totuuden on teille puhunut, jonka hän on Jumalalta kuullut: sitä ei Abraham tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 41, 'Te teette teidän isänne tekoja. Niin he sanoivat hänelle: emme ole äpärinä syntyneet: meillä on yksi Isä, Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 42, 'Jesus sanoi heille: jos Jumala olis teidän Isänne, niin te tosin rakastaisitte minua; sillä minä läksin ja tulin Jumalasta, en minä itsestäni tullut, vaan hän lähetti minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 43, 'Miksi ette ymmärrä tätä minun puhettani? Ette taida kuulla sitä minun sanaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 44, 'Te olette isästä perkeleestä, ja teidän isänne himoja te tahdotte tehdä. Hän on ollut murhaaja alusta, ja ei pysynyt totuudessa; sillä ei totuus ole hänessä. Kuin hän puhuu valhetta, niin hän puhuu omastansa; sillä hän on valehtelia ja valheen isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 45, 'Mutta että minä sanon totuuden, niin ette usko minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 46, 'Kuka teistä nuhtelee minua synnin tähden? jos minä sanon teille totuuden, miksi ette usko minua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 47, 'Joka on Jumalasta, se kuulee Jumalan sanat; sentähden ette kuule, ettette Jumalasta ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 48, 'Niin vastasivat Juudalaiset ja sanoivat hänelle: emmekö me oikein sano, että sinä olet Samarialainen, ja sinulla on perkele?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 49, 'Jesus vastasi: ei minulla ole perkele, vaan minä kunnioitan minun Isääni, ja te häpäisette minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 50, 'En minä etsi omaa kunniaani, yksi on, joka sitä kysyy ja tuomitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 51, 'Totisesti, totisesti sanon minä teille: joka kätkee minun sanani, ei hänen pidä näkemän kuolemaa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 52, 'Niin Juudalaiset sanoivat hänelle: nyt me ymmärsimme, että sinulla on perkele. Abraham on kuollut ja prophetat, ja sinä sanot: joka kätkee minun sanani, ei hänen pidä maistaman kuolemaa ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 53, 'Oletkos sinä suurempi kuin meidän isämme Abraham, joka kuollut on? ja prophetat ovat kuolleet: miksi sinä itses teet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 54, 'Jesus vastasi: jos minä itsiäni kunnioitan, niin ei minun kunniani ole mitään: minun Isäni on se, joka kunnioittaa minua, jonka te teidän Jumalaksenne sanotte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 55, 'Ja ette tunne häntä, mutta minä tunnen hänen: ja jos minä sanoisin, etten minä häntä tuntisi, niin minä olisin valehtelia kuin tekin; mutta minä tunnen hänen ja kätken hänen sanansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 56, 'Abraham teidän isänne iloitsi, nähdäksensä minun päiväni; hän näki sen, ja ihastui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 57, 'Niin Juudalaiset sanoivat hänelle: et sinä ole vielä viidenkymmenen ajastajan vanha ja olet nähnyt Abrahamin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 58, 'Jesus sanoi heille: totisesti, totisesti sanon minä teille: ennenkuin Abraham olikaan, olen minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 59, 'Niin he poimivat kiviä, laskettaaksensa häntä. Mutta Jesus lymyi ja läksi ulos templistä, käyden heidän keskeltänsä; ja niin hän pääsi ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 1, 'Ja Jesus, käyden ohitse, näki ihmisen, joka oli sokiana syntynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 2, 'Ja hänen opetuslapsensa kysyivät häneltä, sanoen: Mestari, kuka syntiä teki, tämäkö eli hänen vanhempansa, että hänen piti sokiana syntymän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 3, 'Jesus vastasi: ei tämä syntiä tehnyt eikä hänen vanhempansa; mutta että Jumalan työt hänessä ilmoitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 4, 'Minun tulee tehdä hänen töitänsä, joka minun lähetti, niin kauvan kuin päivä on. Yö tulee, koska ei kenkään taida työtä tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 5, 'Niinkauvan kuin minä olen maailmassa, niin olen minä maailman valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 6, 'Kuin hän tämän sanonut oli, sylki hän maahan ja teki loan syljestä ja voiteli sokian silmät loalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 7, 'Ja sanoi hänelle: mene ja pese itses lammikossa Siloam, se on niin paljo kuin: lähetetty. Niin hän meni ja pesi itsensä ja tuli näkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 8, 'Niin kylän miehet ja ne, jotka hänen ennen olivat nähneet sokiana, sanoivat: eikö tämä se ole, joka istui ja kerjäsi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 9, 'Muutamat vastasivat: hän se on. Mutta muut sanoivat: hän on sen muotoinen; vaan hän itse sanoi: minä se olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 10, 'Niin he sanoivat hänelle: kuinka sinun silmäs aukenivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 11, 'Vastasi hän ja sanoi: se ihminen, joka Jesukseksi kutsutaan, teki loan, ja voiteli minun silmäni, ja sanoi minulle: mene ja pese Siloamin lammikossa. Ja kuin minä menin ja pesin, niin minä sain näköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 12, 'Niin he sanoivat hänelle: kussas hän on? Hän sanoi: en minä tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 13, 'Niin he veivät sen, joka ennen sokiana ollut oli, Pharisealaisten tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 14, 'Ja se oli sabbatin päivä, jona Jesus teki loan ja avasi hänen silmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 15, 'Niin kysyivät taas häneltä Pharisealaiset, kuinka hän näkönsä saanut oli. Hän sanoi heille: hän pani loan minun silmäini päälle, ja minä pesin, ja näen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 16, 'Niin muutamat Pharisealaisista sanoivat: ei se ihminen ole Jumalasta, ettei hän pidä sabbatia. Muut sanoivat: kuinka taitaa joku syntinen ihminen senkaltaisia ihmeitä tehdä? Ja riita oli heillä keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 17, 'He sanoivat taas sokiallle: mitä sinä hänestä sanot, joka sinun silmäs avasi? Hän sanoi: hän on propheta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 18, 'Mutta ei Juudalaiset sitä uskoneet, että hän oli sokiana ollut ja näkemään tullut, siihenasti kuin he kutsuivat sen vanhemmat, joka näkönsä saanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 19, 'Ja he kysyivät heiltä, sanoen: onko tämä teidän poikanne, jonka te sanotte sokiana syntyneen? kuinka siis hän nyt näkee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 20, 'Hänen vanhempansa vastasivat heitä ja sanoivat: me tiedämme tämän meidän pojaksemme, ja että hän sokiana syntynyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 21, 'Mutta kuika hän nyt näkee, sitä emme tiedä, ja kuka hänen silmänsä avasi, emme tiedä; hänellä on kyllä ikää, kysykäät häneltä; puhukaan itsestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 22, 'Niin sanoivat hänen vanhempansa, sillä he pelkäsivät Juudalaisia; sillä Juudalaiset olivat jo niin keskenänsä päättäneet, että jos joku hänen tunnustais Kristukseksi, sen piti synagogasta oleman suljettu ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 23, 'Sentähden sanoivat hänen vanhempansa: hänellä on kyllä ikää, kysykäät häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 24, 'Niin he kutsuivat toisen kerran sen ihmisen, joka sokiana oli ollut, ja sanoivat hänelle: anna Jumalalle kunnia! me tiedämme sen ihmisen syntiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 25, 'Hän vastasi ja sanoi: jos hän on syntinen, sitä en minä tiedä: vaan sen minä ainoasti tiedän, että minä, joka sokia olin, nyt näen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 26, 'He sanoivat taas hänelle: mitä hän sinulle teki? kuinka hän sinun silmäs avasi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 27, 'Hän vastasi: jo minä sanoin teille, ettekö te kuulleet? Miksi te taas sitä tahdotte kuulla? Tahdotteko te myös hänen opetuslapsiksensa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 28, 'Niin he kiroilivat häntä ja sanoivat: sinä olet hänen opetuslapsensa; mutta me olemme Moseksen opetuslapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 29, 'Me tiedämme Jumalan Mosesta puhutelleen: mutta kusta tämä on, emme tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 30, 'Niin ihminen vastasi ja sanoi heille: se on tosin ihmeellinen, ettette tiedä, kusta hän on, ja kuitenkin hän avasi minun silmäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 31, 'Mutta me tiedämme, ettei Jumala kuule syntisiä; vaan joka on Jumalan palvelia ja tekee hänen tahtonsa, sitä hän kuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 32, 'Ei ole maailman alusta kuultu, että joku on sen silmät avannut, joka sokiana syntynyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 33, 'Ellei hän olisi Jumalasta, niin ei hän taitaisi mitään tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 34, 'He vastasivat ja sanoivat hänelle: sinä olet päänänsä synnissä syntynyt, ja sinä opetat meitä? Ja he ajoivat hänen ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 35, 'Ja Jesus sai sen kuulla, että he olivat hänen ajaneet ulos, ja kuin hän löysi hänen, sanoi hän hänelle: uskotkos sinä Jumalan Pojan päälle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 36, 'Hän vastasi ja sanoi: Herra, kuka se on, että minä hänen päällensä uskoisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 37, 'Niin Jesus sanoi hänelle: sinä olet hänen nähnyt, ja hän on se, joka puhuu sinun kanssas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 38, 'Niin hän sanoi: Herra, minä uskon. Ja hän kumarsi ja rukoili häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 39, 'Ja Jesus sanoi: minä tulin tuomiolle tähän maailmaan, että ne, jotka ei näe, pitää näkemän, ja ne, jotka näkevät, pitää sokiaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 40, 'Ja muutamat Pharisealaisista, jotka hänen tykönänsä olivat, kuulivat nämät ja sanoivat hänelle: olemmeko mekin sokiat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 41, 'Jesus sanoi heille: jos te sokiat olisitte, niin ei olisi teillä syntiä; mutta että te sanotte: me näemme, sentähden teidän syntinne pysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 1, 'Totisesti, totisesti sanon minä teille: joka ei ovesta mene sisälle lammashuoneesen, vaan astuu siihen muualta, se on varas ja ryöväri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 2, 'Mutta joka oven kautta sisälle menee, se on lammasten paimen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 3, 'Sille ovenvartia avaa, ja lampaat kuulevat hänen äänensä. Ja omia lampaitansa kutsuu hän nimeltänsä, ja vie heidät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 4, 'Ja kuin hän omat lampaansa päästää ulos, käy hän heidän edellänsä, ja lampaat seuraavat häntä, sillä he tuntevat hänen äänensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 5, 'Mutta ei he muukalaista seuraa, vaan pakenevat häntä; sillä ei he tunne muukalaisten ääntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 6, 'Tämän tapauksen sanoi Jesus heille; mutta ei he niitä ymmärtäneet, mitä hän heille sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 7, 'Niin Jesus sanoi taas heille: totisesti, totisesti sanon minä teille: minä olen lammasten ovi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 8, 'Kaikki, jotka minun edelläni ovat tulleet, ovat varkaat ja ryövärit: vaan ei lampaat kuulleet heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 9, 'Minä olen ovi: jos joku minun kauttani menee sisälle, se tulee autuaaksi, ja menee sisälle ja ulos, ja löytää laitumen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 10, 'Ei varas tule muuta kuin varastamaan ja tappamaan ja kadottamaan: minä tulin, että heillä pitää elämä oleman ja yltäkyllä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 11, 'Minä olen hyvä paimen: hyvä paimen antaa henkensä lammasten edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 12, 'Mutta palkollinen, joka ei ole paimen, eikä lampaat ole hänen omansa: kuin hän näkee suden tulevan, niin hän jättää lampaat ja pakenee; ja susi raatelee ja haaskaa lampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 13, 'Mutta palkollinen pakenee, sillä hän on palkollinen, eikä tottele lampaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 14, 'Minä olen hyvä paimen, joka tunnen omani, ja minä tunnetaan myös omiltani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 15, 'Niinkuin Isä minun tuntee, ja minä tunnen Isän: ja panen henkeni lammasten edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 16, 'Minulla on myös muita lampaita, jotka ei ole tästä lammashuoneesta: ne pitää minun myös tänne saattaman: ja he saavat kuulla minun ääneni; ja pitää oleman yksi lammashuone ja yksi paimen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 17, 'Sentähden Isä minua rakastaa, sillä minä panen henkeni, että minä sen jälleen otan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 18, 'Ei ota kenkään sitä minulta, vaan minä panen sen itsestäni. Minulla on valta sitä panna, ja minulla on valta sitä taas ottaa. Sen käskyn minä sain Isältäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 19, 'Niin tuli taas riita Juudalaisten keskellä näiden puhetten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 20, 'Ja moni heistä sanoi: hänellä on perkele, ja hän on mieletöin: mitä te häntä kuultelette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 21, 'Mutta muut sanoivat: ei ne ole riivatun puheet: taitaako perkele sokian silmät avata?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 22, 'Ja Jerusalemissa oli kirkkomessu, ja talvi oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 23, 'Ja Jesus käveli templissä Salomon esihuoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 24, 'Niin Juudalaiset piirittivät hänen ja sanoivat hänelle: kuinka kauvan sinä meitä pidät ylös? Jos olet Kristus, niin sano meille selkiästi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 25, 'Jesus vastasi heitä: minä olen sen teille sanonut, ja ette usko: ne työt, jotka minä teen Isäni nimeen, todistavat minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 26, 'Mutta ette usko: sillä ette ole minun lampaistani, niinkuin minä teille sanoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 27, 'Minun lampaani kuulevat minun ääneni, ja minä tunnen heidät, ja he seuraavat minua:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 28, 'Ja minä annan heille ijankaikkisen elämän, ja ei heidän pidä hukkuman ijankaikkisesti, eikä pidä yhdenkään repäisemän heitä minun kädestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 29, 'Minun isäni, joka ne minulle antoi, on suurempi kaikkia: ja ei kenkään taida heitä reväistä minun Isäni kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 30, 'Minä ja Isä olemme yhtä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 31, 'Niin Juudalaiset poimivat taas kiviä häntä kivittääksensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 32, 'Jesus vastasi heitä: minä osoitin teille Isältäni monta hyvää työtä: minkä työn tähden niistä te siis minun kivitätte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 33, 'Juudalaiset vastasivat häntä, sanoen: emme sinua hyvän työn tähden kivitä, vaan pilkan tähden, ja että sinä, joka ihminen olet, teet itses Jumalaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 34, 'Jesus vastasi heitä: eikö teidän laissanne ole kirjoitettu: minä sanon, te olette jumalat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 35, 'Jos hän ne kutsui jumaliksi, joille Jumalan sana tapahtui, ja ei kirjoitus taideta rikottaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 36, 'Ja te sanotte hänelle, jonka Isä on pyhittänyt ja lähettänyt maailmaan: sinä pilkkaat Jumalaa, että minä sanoin: minä olen Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 37, 'Ellen minä tee minun Isäni töitä, niin älkäät minua uskoko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 38, 'Mutta jos minä niitä teen, ja jos ette minua usko, niin uskokaat ne työt, että te tuntisitte ja uskoisitte Isän olevan minussa ja minun hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 39, 'Niin he etsivät taas häntä kiinni ottaaksensa, mutta hän läksi heidän käsistänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 40, 'Ja meni jälleen toiselle puolelle Jordania, siihen paikkaan, jossa Johannes ensin kasti, ja viipyi siinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 41, 'Ja monta tuli hänen tykönsä, ja sanoivat: ei Johannes yhtäkään ihmettä tehnyt; mutta kaikki mitä Johannes tästä sanoi, ne ovat todet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 42, 'Ja monta uskoi sillä hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 1, 'Niin mies sairasti, nimeltä Latsarus, Betaniasta, Marian ja hänen sisarensa Martan kylästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 2, 'Mutta Maria oli se, joka voiteli Herran voiteella ja hänen jalkansa hiuksillansa kuivaksi, jonka veli Latsarus sairasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 3, 'Niin hänen sisarensa lähettivät hänen tykönsä, ja sanoivat: Herra, katso, se sairastaa, jotas rakastat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 4, 'Kuin Jesus sen kuuli, sanoi hän: ei tämä tauti ole kuolemaksi, vaan Jumalan kunniaksi, että Jumalan Poika sen kautta kunnioitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 5, 'Mutta Jesus rakasti Marttaa, ha hänen sisartansa, ja Latsarusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 6, 'Kuin hän siis kuuli hänen sairastavan, niin hän viipyi siinä paikassa kaksi päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 7, 'Sitte sanoi hän opetuslapsillensa: menkäämme jälleen Juudeaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 8, 'Sanoivat hänelle opetuslapset: Rabbi, äsken etsivät Juudalaiset sinua kivittääksensä, ja sinä menet taas sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 9, 'Vastasi Jesus: eikö kaksitoistakymmentä ole päivän hetkeä? Jos joku päivällä vaeltaa, ei hän loukkaa itsiänsä; sillä hän näkee tämän maailman valkeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 10, 'Mutta jos joku yöllä vaeltaa, hän loukkaa itsensä; sillä ei valkeus ole hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 11, 'Näitä hän puhui, ja sanoi sitte heille: ystävämme Latsarus makaa, mutta minä menen häntä unesta herättämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 12, 'Niin sanoivat hänen opetuslapsensa: Herra, jos hän makaa, kyllä hän paranee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 13, 'Mutta Jesus sanoi hänen kuolemastansa; vaan he luulivat hänen sanovan unen makaamisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 14, 'Niin Jesus sanoi heille selkiästi: Latsarus on kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 15, 'Ja minä iloitsen teidän tähtenne, etten minä siellä ollut, että te uskoisitte. Mutta menkäämme hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 16, 'Niin sanoi Toomas, joka kutsutaan kaksoiseksi, muille opetuslapsille: käykäämme myös me, että me kuolisimme hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 17, 'niin Jesus tuli ja löysi hänen jo neljä päivää maanneen haudassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 18, 'Mutta Betania oli läsnä Jerusalemia, lähes viisitoistakymmentä vakomittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 19, 'Ja monta Juudalaisista oli tullut Martan ja Marian tykö, lohduttamaan heitä heidän veljensä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 20, 'Kuin Martta kuuli Jesuksen tulevan, juoksi hän häntä vastaa; mutta Maria istui kotona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 21, 'Niin Martta sanoi Jesukselle: Herra, jos sinä olisit täällä ollut, niin ei minun veljeni olisi kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 22, 'Mutta minä tiedän vielä, että kaikki, mitä sinä anot Jumalalta, ne Jumala sinulle antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 23, 'Jesus sanoi hänelle: sinun veljes on nouseva ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 24, 'Martta sanoi hänelle: minä tiedän hänen nousevan ylösnousemisessa viimeisenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 25, 'Sanoi Jesus hänelle: minä olen ylösnousemus ja elämä: joka uskoo minun päälleni, hän elää, ehkä hän olis kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 26, 'Ja jokainen, joka elää ja uskoo minun päälleni, ei hänen pidä kuoleman ijankaikkisesti: uskotkos sen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 27, 'Hän sanoi hänelle: jaa Herra, minä uskon sinun Kristukseksi, Jumalan Pojaksi, joka tuleva oli maailmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 28, 'Ja kuin hän näitä sanonut oli, meni hän pois ja kutsui sisarensa Marian salaa, sanoen: Mestari on tullut ja kutsuu sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 29, 'Kuin hän sen kuuli, nousi hän kohta ja tuli hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 30, '(Sillä ei Jesus ollut vielä kylään tullut, vaan oli siinä paikassa, jossa Martta oli hänen kohdannut.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 31, 'Kuin siis Juudalaiset, jotka hänen kanssansa huoneessa olivat lohduttamassa häntä, näkivät Marian nousevan ja menevän ulos, seurasivat he häntä, sanoen: hän menee haudalle itkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 32, 'Kuin Maria sinne tuli, kussa Jesus oli, ja näki hänen, lankesi hän hänen jalkainsa juureen ja sanoi hänelle: Herra, jos olisit täällä ollut, ei olisi minun veljeni kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 33, 'Kuin Jesus näki hänen itkevän ja Juudalaiset, jotka hänen kanssansa tulleet olivat, itkevän, kauhistui hän hengessä ja tuli sangen murheelliseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 34, 'Ja sanoi: kuhunka te hänen panitte? He sanoivat hänelle: Herra, tule ja katso.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 35, 'Ja Jesus itki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 36, 'Niin sanoivat Juudalaiset: katso, kuinka hän rakasti häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 37, 'Mutta muutamat heistä sanoivat: eikö tämä, joka sokian silmät avasi, tainnut tehdä, ettei tämäkään kuollut olisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 38, 'Niin Jesus kauhistui taas itsessänsä, ja tuli haudan tykö. Mutta siinä oli kuoppa, ja kivi sen päälle pantu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 39, 'Jesus sanoi: ottakaat kivi pois. Sanoi hänelle Martta, sen sisar, joka kuollut oli: Herra, jo hän haisee, sillä hän on neljä päivää kuolleena ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 40, 'Jesus sanoi hänelle: enkö minä sinulle sanonut: jos sinä uskoisit, niin sinä näkisit Jumalan kunnian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 41, 'Ja he ottivat kiven pois sialtansa, johon kuollut pantu oli. Niin Jesus nosti silmänsä ylös ja sanoi: Isä, minä kiitän sinua, ettäs minua kuulit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 42, 'Mutta minä tiedän myös, ettäs aina minua kuulet; vaan kansan tähden, joka tässä ympäri seisoo, sanon minä, että he uskoisivat sinun minun lähettäneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 43, 'Ja kuin hän nämät sanonut oli, huusi hän suurella äänellä: Latsarus, tule ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 44, 'Ja se kuollut tuli ulos sidottuna käsistä ja jaloista kääriliinalla, ja hänen kasvonsa olivat sidotut ympäri hikiliinalla. Jesus sanoi heille: päästäkäät häntä ja antakaat hänen mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 45, 'Niin monta Juudalaista, jotka olivat Marian tykö tulleet, ja näkivät mitä Jesus teki, uskoivat hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 46, 'Mutta muutamat heistä menivät Pharisealaisten tykö ja ilmoittivat heille, mitä Jesus oli tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 47, 'Niin ylimmäiset papit ja Pharisealaiset kokosivat neuvon, ja sanoivat: mitä me teemme? sillä tämä ihminen tekee monta ihmettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 48, 'Jos me sallimme hänen niin olla, niin kaikki uskovat hänen päällensä, ja Roomalaiset tulevat ja ottavat pois sekä meidän maamme että kansamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 49, 'Mutta yksi heistä, Kaiphas nimeltä, joka oli sinä vuonna ylimmäinne pappi, sanoi heille: ette mitään tiedä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 50, 'Ette myös ajattele, että se on meille tarpeellinen, että yksi ihminen kuolee kansan tähden, ettei kaikki kansa hukkuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 51, 'Mutta ei hän sitä itsestänsä sanonut; vaan että hän oli sinä vuonna ylimmäinen pappi, niin hän ennusti, että Jesuksen piti kuoleman kansan tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 52, 'Ja ei ainoastaan kansan tähden, mutta että hänen piti ne Jumalan lapset, jotka hajoitetut olivat, yhteen kokooman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 53, 'Mutta siitä päivästä pitivät he yhteen neuvoa, kuolettaaksensa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 54, 'Ei siis Jesus vaeltanut enää Juudalaisten seassa julkisesti, vaan meni sieltä yhteen maan paikkaan lähes korpea, siihen kaupunkiin, joka kutsutaan Epharaim, ja oleskeli siellä opetuslastensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 55, 'Mutta Juudalaisten pääsiäinen lähestyi, ja monta siitä maakunnasta meni pääsiäisen edellä Jerusalemiin puhdistamaan itsiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 56, 'Niin he etsivät Jesusta ja puhuivat keskenänsä, seisoen templissä: mitä te luulette, ettei hän ole juhlalle tullut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 57, 'Ja ylimmäiset papit ja Pharisealaiset olivat käskyn antaneet, että jos joku tietäis, kussa hän olis, niin hänen piti sen ilmoittaman, että he ottaisivat hänen kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 1, 'Kuusi päivää enne pääsiäistä tuli Jesus Betaniaan, jossa Latsarus oli, joka kuollut oli, jonka hän kuolleista herätti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 2, 'Niin he valmistivat hänelle siellä ehtoollisen, ja Martta palveli; mutta Latsarus oli yksi niistä, jotka hänen kanssansa atrioitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 3, 'Niin Maria otti naulan turmelematointa ja kallista nardusvoidetta, ja voiteli Jesuksen jalat, ja kuivasi hänen jalkansa hiuksillansa. Ja huone täytettiin voiteen hajusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 4, 'Niin sanoi yksi hänen opetuslapsistansa, Juudas Simonin poika Iskariot, joka hänen sitte petti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 5, 'Miksi et tätä voidetta myyty kolmeensataan penninkiin, ja annettu vaivaisille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 6, 'Mutta hän sanoi sen, ei että hän murhetta piti vaivaisista, vaan että hän oli varas, ja hänellä oli kukkaro, jossa hän sen kantoi, mikä siihen pantu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 7, 'Niin Jesus sanoi: anna hänen olla, hän on sen kätkenyt minun hautaamiseni päiväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 8, 'Sillä teidän tykönänne ovat aina vaivaiset, mutta en minä aina teillä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 9, 'Niin paljo kansaa Juudalaisista ymmärsi hänen siellä olevan, ja tulivat sinne, ei ainoastaan Jesuksen tähden, vaan että he olisivat myös Latsaruksen nähneet, jonka hän oli kuolleista herättänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 10, 'Mutta ylimmäiset papit pitivät neuvoa myös Latsarusta tappaaksensa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 11, 'Sillä monta Juudalaisista meni sinne hänen tähtensä, ja uskoi Jesuksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 12, 'Toisena päivänä, kuin paljon kansaa, joka juhlalle tullut oli, kuuli Jesuksen tulleen Jerusalemiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 13, 'Ottivat he palmu-oksia, menivät häntä vastaan ja huusivat: Hosianna! siunattu on se, joka tulee Herran nimeen, Israelin kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 14, 'Mutta Jesus sai yhden aasin ja istui sen päälle, niinkuin kirjoitettu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 15, 'Älä pelkää, Sionin tytär! katso, sinun Kuninkaas tulee ja istuu aasin varsan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 16, 'Mutta ei hänen opetuslapsensa näitä ensisti ymmärtäneet; vaan sittekuin Jesus oli kirkastettu, silloin he muistivat, että nämät ovat hänestä kirjoitetut, ja että he näitä hänelle tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 17, 'Mutta se kansa todisti, joka hänen kanssansa oli, että hän Latsaruksen haudasta kutsui ja kuolleista herätti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 18, 'Sentähden myös kansa meni häntä vastaan, että he kuulivat hänen sen ihmeen tehneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 19, 'Niin Pharisealaiset sanoivat keskenänsä: te näette, ettette mitään aikoihin saa; katso, koko maailma juoksee hänen perässänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 20, 'Mutta muutamat Grekiläiset olivat niistä, jotka menivät ylös juhlana rukoilemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 21, 'Niin he menivät Philippuksen tykö, joka oli Galilean Betsaidasta, ja rukoilivat häntä, sanoen: herra, me tahdomme nähdä Jesusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 22, 'Philippus meni ja sanoi sen Andreakselle, ja Andreas taas ja Philippus sanoivat sen Jesukselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 23, 'Mutta Jesus vastasi heitä ja sanoi: aika on tullut, että Ihmisen Poika pitää kirkastettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 24, 'Totisesti, totisesti sanon minä teille: ellei maahan pudonnut nisun jyvä kuole, niin se jää yksinänsä; mutta jos se kuolee, niin se tuo paljon hedelmää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 25, 'Joka rakastaa henkeänsä, hän kadottaa sen; mutta joka tässä maailmassa vihaa henkeänsä, hän tuottaa sen ijankaikkiseen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 26, 'Jos joku minua palvelee, hän seuratkaan minua: ja kussa minä olen, siellä pitää myös minun palveliani oleman: ja jos joku minua palvelee, häntä on Isä kunnioittava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 27, 'Nyt on minun sieluni suuresti murheissansa, ja mitä minun pitää sanoman? Isä, vapahda minun tästä hetkestä: kuitenkin olen minä sentähden tähän hetkeen tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 28, 'Isä, kirkasta sinun nimes. Niin ääni tuli taivaasta ja sanoi: minä olen sen kirkastanut, ja tahdon vielä nyt kirkastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 29, 'Niin kansa, joka läsnä seisoi ja sen kuuli, sanoi pitkäisen jylisseen. Muut sanoivat: enkeli puhutteli häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 30, 'Jesus vastasi ja sanoi: ei tämä ääni tullut minun, vaan teidän tähtenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 31, 'Nyt tämä maailma tuomitaan: nyt tämän maailman päämies pitää heittämän ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 32, 'Ja kuin minä maasta nostetaan ylös, niin minä vedän kaikki minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 33, '(Mutta sen hän sanoi, muistuttain millä kuolemalla hänen piti kuoleman.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 34, 'Niin kansa vastasi häntä ja sanoi: me olemme laista kuulleet Kristuksen pysyvän ijankaikkisesti: ja kuinka sinä sanot, että Ihmisen Poika pitää nostettaman ylös? Kuka on se Ihmisen Poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 35, 'Niin Jesus sanoi heille: valkeus on vielä vähän aikaa teidän kanssanne, vaeltakaat niinkauvan kuin teillä valkeus on, ettei pimeys teitä käsittäisi. Joka pimeydessä vaeltaa, ei hän tiedä, kuhunka hän menee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 36, 'Uskokaat valkeuden päälle, niinkauvan kuin teillä valkeus on, että te tulisitte valkeuden lapsiksi. Näitä puhui Jesus ja meni pois, ja lymyi heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 37, 'Ja vaikka hän teki monta ihmettä heidän nähtensä, ei he kuitenkaan uskoneet hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 38, 'Että Jesaias prophetan puhe täytettäisiin, jonka hän sanoi: Herra, kuka uskoi meidän saarnamme? ja kenelle on Herran käsivarsi ilmoitettu?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 39, 'Sentähden ei he tainneet uskoa, sillä Jesaias on taas sanonut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 40, 'Hän sokaisi heidän silmänsä, ja paadutti heidän sydämensä, ettei he näkisi silmillä, eikä ymmärtäisi sydämellä, ja kääntäisi itsiänsä, ja minä parantaisin heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 41, 'Nämät sanoi Jesaias, koska hän näki hänen kunniansa ja puhui hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 42, 'Kuitenkin monta myös ylimmäisistä uskoivat hänen päällensä; vaan ei he Pharisealaisten tähden sitä tunnustaneet, ettei he olisi pannaan kuulutettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 43, 'Sillä he rakastivat enemmin ihmisten kunniaa, kuin Jumalan kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 44, 'Mutta Jesus huusi ja sanoi: joka uskoo minun päälleni, ei se usko minun päälleni, vaan sen päälle, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 45, 'Ja joka minun näkee, hän näkee sen, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 46, 'Minä tulin valkeudeksi maailmaan, että jokainen, joka uskoo minun päälleni, ei pidä pimeissä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 47, 'Mutta jos joku minun sanani kuulee, ja ei usko, en minä häntä tuomitse; sillä en minä tullut maailmaa tuomitsemaan, vaan vapahtamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 48, 'Joka minun katsoo ylön, ja ei ota vastaan minun sanojani, hänellä on se, joka hänen tuomitsee: se puhe, jonka minä puhuin, pitää hänen tuomitseman viimeisenä päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 49, 'Sillä en minä ole itsestäni puhunut; vaan Isä, joka minun lähetti, hän on minulle käskyn antanut, mitä minun tekemän ja puhuman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 50, 'Ja minä tiedän, että hänen käskynsä on ijankaikkinen elämä. Sentähden mitä minä puhun, sen minä puhun, niinkuin Isä on minulle sanonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 1, 'Mutta ennen pääsiäisjuhlaa, kuin Jesus tiesi hetkensä tulleeksi, että hänen piti tästä maailmasta Isän tykö menemän, niinkuin hän oli rakastanut omiansa, jotka olivat maailmassa, niin hän loppuun asti rakasti heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 2, 'Ja ehtoolisen jälkeen, (kuin perkele oli jo Juudaan Simonin Iskariotin sydämeen lykännyt, että hänen piti hänen pettämän,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 3, 'Tiesi Jesus Isän kaikki hänen käsiinsä antaneen, ja että hän oli Jumalasta lähtenyt ulos ja oli Jumalan tykö menevä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 4, 'Nousi hän ehtoolliselta ja riisui vaatteensa, ja otti liinaisen, ja vyötti itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 5, 'Pani hän sitte vettä maljaan, ja rupesi pesemään opetuslasten jalkoja, ja kuivasi ne sillä liinaisella, jolla hän vyötetty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 6, 'Niin hän tuli Simon Pietarin tykö, joka sanoi hänelle: Herra, sinäkö minun jalkani peset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 7, 'Jesus vastasi ja sanoi hänelle: mitä minä teen, et sinä sitä nyt tiedä, mutta tästedes saat sinä sen tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 8, 'Pietari sanoi hänelle: ei sinun pidä ikänä pesemän minun jalkojani. Vastasi häntä Jesus: ellen minä sinua pese, niin ei sinulla ole osaa minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 9, 'Simon Pietari sanoi hänelle: Herra, ei ainoastaan minun jalkojani, mutta myös kädet ja pää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 10, 'Sanoi Jesus hänelle: joka pesty on, ei se muuta tarvitse, vaan että jalat pestään, ja niin hän on kokonansa puhdas: ja te olette puhtaat, ette kuitenkaan kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 11, 'Sillä hän tiesi pettäjänsä; sentähden hän sanoi: ette kaikki ole puhtaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 12, 'Sittekuin hän oli pessyt heidän jalkansa ja vaatteensa ottanut, istui hän taas ja sanoi heille: tiedättekö, mitä minä teille tehnyt olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 13, 'Te kutsutte minun Mestariksi ja Herraksi, ja te sanotte oikein; sillä minä myös olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 14, 'Sentähden, jos minä, joka olen Herra ja Mestari, olen teidän jalkanne pessyt, niin pitää myös teidänkin toinen toisenne jalat pesemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 15, 'Sillä minä annoin teille esikuvan, että te niin tekisitte, kuin minä tein teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 16, 'Totisesti, totisesti sanon minä teille: ei ole palvelia suurempi herraansa, eikä sanansaattaja suurempi kuin se, joka hänen lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 17, 'Jos te nämät tiedätte, te olette autuaat, jos te niitä teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 18, 'En minä kaikista teistä puhu: minä tiedän ne, jotka minä valitsin: mutta että Raamattu täytettäisiin: joka syö leipää minun kanssani, hän tallasi minun jalallansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 19, 'Nyt minä sanon teille ennenkuin se tapahtuu, että sittekuin se tapahtunut on, te uskoisitte minun siksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 20, 'Totisesti, totisesti sanon minä teille: joka korjaa sen, jonka minä lähetän, hän korjaa minun; mutta joka minun korjaa, hän korjaa sen, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 21, 'Kuin Jesus nämät oli sanonut, tuli hän murheelliseksi hengessä, ja todisti ja sanoi: totisesti, totisesti sanon minä teille: yksi on teistä minun pettävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 22, 'Niin opetuslapset katselivat toinen toisensa päälle, ja epäilivät, kenestä hän sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 23, 'Ja yksi hänen opetuslapsistansa istui pöydän tykönä Jesuksen helmassa, jota Jesus rakasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 24, 'Niin Simon Pietari viittasi sille, visusti kysymään, kuka se olis, josta hän sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 25, 'Kuin hän nojasi Jesuksen rintaa vastaan, sanoi hän hänelle: Herra, kuka se on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 26, 'Jesus vastasi: se on se, jolle minä kastetun palan annan. Ja kuin hän oli kastanut leivän, antoi hän sen Juudaalle Simon Iskariotille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 27, 'Ja sen palan jälkeen meni silloin häneen perkele. Niin Jesus sanoi hänelle: mitäs teet, niin tee pikemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 28, 'Mutta sitä ei yksikään atrioitsevista ymmärtänyt, mitä varten hän sen hänelle sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 29, 'Sillä muutamat luulivat, koska Juudaalla oli kukkaro, Jesuksen hänelle sanovan: osta, mitä me juhlapäiväksi tarvitsemme, eli että hän vaivaisille jotakin antais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 30, 'Kuin hän siis sen palan ottanut oli, meni hän kohta ulos; ja yö oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 31, 'Kuin hän oli mennyt ulos, sanoi Jesus: nyt on Ihmisen Poika kirkastettu, ja Jumala on kirkastettu hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 32, 'Jos Jumala on kirkastettu hänessä, niin on myös Jumala kirkastava hänen itsessänsä, ja kirkastaa hänen pian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 33, 'Rakkaat lapsukaiset, minä olen vielä vähän aikaa teidän kanssanne: teidän pitää minua etsimän, ja niinkuin minä sanoin Juudalaisille: ette taida sinne tulla, kuhunka minä menen, niin minä sanon myös nyt teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 34, 'Uuden käskyn minä teille annan, että te rakastaisitte teitänne keskenänne, niinkuin minä teitä rakastin, että te myös toinen toistanne rakastaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 35, 'Siitä pitää kaikkein tunteman teidät minun opetuslapsikseni, jos te keskenänne rakkauden pidätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 36, 'Sanoi Simon Pietari hänelle: Herra, kuhunkas menet? Jesus vastasi häntä: kuhunka minä menen, et sinä taida nyt minua seurata, mutta tästälähin sinä olet minua seuraava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 37, 'Pietari sanoi hänelle: Herra, miksi en minä nyt taida sinua seurata? minä panen henkeni sinun edestäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 38, 'Jesus vastasi häntä: sinä panet henkes minun edestäni? Totisesti, totisesti sanon minä sinulle: ei laula kukko ennenkuin sinä olet kolmasti minun kieltänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 1, '(Ja hän sanoi opetuslapsillensa:) älkööt teidän sydämenne murheellinen olko; jos te uskotte Jumalan päälle, niin uskokaat myös minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 2, 'Minun Isäni huoneessa on monta asuinsiaa; jos ei niin olisi, niin minä sanoisin teille: minä menen valmistamaan teille siaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 3, 'Ja vaikka minä menen pois valmistamaan teille siaa, niin minä tulen jälleen ja otan teidät tyköni, että kussa minä olen, siellä pitää myös teidän oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 4, 'Ja kuhunka minä menen, te tiedätte, ja tien te myös tiedätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 5, 'Sanoi Toomas hänelle: Herra, emme tiedä, kuhunkas menet: kuinka siis me taidamme tietää tien?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 6, 'Jesus sanoi hänelle: minä olen tie, totuus ja elämä. Ei kenkään tule Isän tykö, vaan minun kauttani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 7, 'Jos te tuntisitte minun, niin te tosin myös tuntisitte Isäni; ja nyt te tunnette hänen, ja te näette hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 8, 'Philippus sanoi hänelle: Herra, osoita meille Isä, niin me tyydymme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 9, 'Jesus sanoi hänelle: minä olen niin kauvan aikaa teidän tykönänne, ja et sinä minua tunne? Philippus, joka näki minun, hän näki myös Isän: kuinka siis sinä sanot: osoita minulle Isä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 10, 'Etkös usko minun olevan Isässä ja Isän minussa? Ne sanat, jotka minä teille puhun, en minä itsestäni puhu: mutta Isä, joka minussa on, hän tekee työt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 11, 'Uskokaat minua, että minä olen Isässä ja Isä on minussa; mutta jos ei, niin töiden tähden uskokaat minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 12, 'Totisesti, totisesti sanon minä teille: joka uskoo minun päälleni, ne työt, joita minä teen, hän on myös tekevä, ja suurempia, kuin ne ovat, on hän tekevä; sillä minä menen Isäni tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 13, 'Ja mitä ikänä te anotte minun nimeeni, sen minä teen: että Isä kunnioitettaisiin Pojan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 14, 'Mitä te anotte minun nimeeni, sen minä teen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 15, 'Jos te rakastatte minua, niin pitäkäät minun käskyni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 16, 'Ja minä olen rukoileva Isää, ja hän antaa teille toisen Lohduttajan, että hän teidän kanssanne olis ijankaikkisesti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 17, 'Totuuden Hengen, jota ei maailma taida ottaa vastaan, sillä ei he näe häntä, eikä tunne häntä: mutta te tunnette hänen, sillä hän pysyy teidän tykönänne ja on teissä oleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 18, 'En minä jätä teitä orvoiksi, vaan minä tulen teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 19, 'Vielä on vähän aikaa, ja ei maailma silleen minua näe, mutta te näette minun; sillä minä elän, ja te myös elätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 20, 'Sinä päivänä pitää teidän ymmärtämän, että minä olen Isässä, ja te minussa ja minä teissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 21, 'Jolla minun käskyni ovat ja ne kätkee, se rakastaa minua: mutta joka minua rakastaa, hän rakastetaan minun Isältäni, ja minä tahdon häntä rakastaa, ja ilmoitan itseni hänelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 22, 'Sanoi hänelle Juudas: (ei se Iskariot) Herra, kuinka se tulee, ettäs tahdot meille itses ilmoittaa, ja et maailmalle?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 23, 'Jesus vastasi ja sanoi hänelle: joka minua rakastaa, se pitää minun sanani; ja minun Isäni rakastaa häntä, ja me tulemme hänen tykönsä, ja asumme hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 24, 'Joka ei minua rakasta, ei se minun sanojani kätke: ja se sana, jonka te kuulette, ei ole minun, vaan Isän joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 25, 'Näitä olen minä teille puhunut, ollessani teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 26, 'Mutta Lohduttaja, Pyhä Henki, jonka Isä on lähettävä minun nimeeni, hän opettaa teille kaikki ja muistuttaa teille kaikki, mitä minä teille sanonut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 27, 'Rauhan minä jätän teille, minun rauhani minä annan teille: en minä anna teille niinkuin maailma antaa. Älkään teidän sydämenne murheellinen olko, älkään myös peljätkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 28, 'Te kuulitte minun sanovan: minä menen pois ja tulen jälleen teidän tykönne. Jos te minua rakastaisitte, niin te tosin iloitsisitte, että minä sanoin: minä menen Isän tykö; sillä Isä on suurempi minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 29, 'Ja nyt minä sanon teille ennen kuin se tapahtuu, että te uskoisitte, kuin se tapahtunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 30, 'En minä tästedes puhu paljon teidän kanssanne; sillä tämän maailman päämies tulee, jolla ei ole mitään minussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 31, 'Mutta että maailma ymmärtäis minun Isää rakastavan, ja niinkuin Isä minulle käski, niin minä myös teen. Nouskaat, lähtekäämme täältä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 1, 'Minä olen totinen viinipuu, ja minun Isäni on peltomies:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 2, 'Jokaisen oksan minussa, joka ei kanna hedelmää, hän karsii pois, ja jokaisen, joka hedelmän kantaa, hän puhdistaa, että se kantais runsaamman hedelmän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 3, 'Te olette nyt puhtaat, sen sanan tähden, jonka minä teille puhuin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 4, 'Pysykäät te minussa, ja minä teissä. Niinkuin ei oksa taida itsestänsä hedelmää kantaa, ellei hän viinapuussa kiinni ole, niin ette tekään, jollette minussa pysy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 5, 'Minä olen viinapuu, te olette oksat: joka minussa pysyy ja minä hänessä, hän kantaa paljon hedelmää; sillä ilman minua ette voi mitään tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 6, 'Jos ei joku minussa pysy, se heitetään ulos niinkuin oksa, ja kuivettuu, ja ne sidotaan kokoon, ja heitetään tuleen, ja palavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 7, 'Jos te minussa pysytte ja minun sanani pysyvät teissä, mitkä ikänä te tahdotte, niin anokaat, ja te saatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 8, 'Siinä minun Isäni kunnioitetaan, että te paljon hedelmää kantaisitte, ja tulette minun opetuslapsikseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 9, 'Niinkuin Isä rakasti minua, niin minä myös rakastin teitä: pysykäät minun rakkaudessani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 10, 'Jos te minun käskyni pidätte, niin te pysytte minun rakkaudessani, niinkuin minä pidän Isäni käskyn ja pysyn hänen rakkaudessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 11, 'Näitä olen minä teille puhunut, että minun iloni teissä pysyis ja teidän ilonne tulis täydelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 12, 'Se on minun käskyni, että te rakastatte teitänne keskenänne, niinkuin minä teitä rakastin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 13, 'Ei ole kellään sitä suurempaa rakkautta, kuin että joku panis henkensä ystäväinsä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 14, 'Te olette minun ystäväni, jos te teette, mitä minä teidän käsken.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 15, 'En minä tästedes sano teitä palvelijoiksi; sillä ei palvelia tiedä, mitä hänen herransa tekee; mutta minä kutsun teitä ystäviksi, sillä kaikki, mitä minä Isältäni kuulin, ne minä teille ilmoitin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 16, 'Ette minua valinneet, vaan minä valitsin teidät, ja sääsin teidät, että te menisitte hedelmää tekemään ja teidän hedelmänne pysyis: että mitä te anotte Isältä minun nimeeni, sen hän antaa teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 17, 'Näitä minä käsken teille, että te toinen toistanne rakastaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 18, 'Jos maailma teitä vihaa, niin tietäkäät hänen ennen minua vihanneen kuin teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 19, 'Jos te maailmasta olisitte, niin maailma omaansa rakastais; mutta ette ole maailmasta, vaan minä valitsin teidät maailmasta, sentähden maailma vihaa teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 20, 'Muistakaat sitä sanaa, jonka minä teille sanoin: ei ole palvelia suurempi herraansa. Jos he minua vainosivat, niin he myös teitä vainoovat: jos he minun sanani kätkivät, niin he teidänkin sananne kätkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 21, 'Mutta kaikkia näitä tekevät he teille minun nimeni tähden; sillä ei he tunne sitä, joka minun lähetti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 22, 'Jos en minä olisi tullut ja heitä puhutellut, niin ei heillä olisi syntiä; mutta nyt ei heillä ole, millä he syntinsä verhoovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 23, 'Joka minua vihaa, hän vihaa myös minun Isääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 24, 'Ellen minä olisi niitä töitä heidän seassansa tehnyt, joita ei kenkään muu ole tehnyt, niin ei heillä olisi syntiä; mutta nyt he näkivät, ja vihasivat sekä minua että minun Isääni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 25, 'Vaan (se tapahtui) että se täytettäisiin, mitä heidän laissansa on kirjoitettu: he vihasivat minua ilman syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 26, 'Mutta kuin Lohduttaja tulee, jonka minä teille Isältä lähetän, totuuden Henki, joka Isästä käy ulos, se on minusta todistava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 27, 'Ja teidän pitää myös todistaman; sillä te olette alusta minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 1, 'Näitä olen minä puhunut teille, ette pahenisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 2, 'He panevat teitä pannaan. Ja aika tulee, että jokainen, joka teidät tappaa, se luulee tekevänsä Jumalalle palveluksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 3, 'Ja näitä he tekevät teille, ettei he tunne Isää eikä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 4, 'Vaan minä puhuin näitä teille, että kuin se aika tulee, te niistä muistaisitte, että minä teille sanonut olen; mutta en minä ole teille näitä alusta sanonut, sillä minä olin teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 5, 'Mutta nyt minä menen sen tykö, joka minun lähetti, ja ei teistä minulta kenkään kysy: kuhunkas menet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 6, 'Vaan että minä olen näitä teille puhunut, niin murhe täyttää teidän sydämenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 7, 'Kuitenkin sanon minä teille totuuden: se on teille tarpeellinen, että minä menen pois; sillä ellen minä mene pois, niin ei Lohduttaja tule teidän tykönne; mutta jos minä menen pois, niin minä hänen teille lähetän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 8, 'Ja kuin hän tulee, niin hän nuhtelee maailmaa synnin tähden, ja vanhurskauden tähden, ja tuomion tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 9, 'Synnin tähden tosin, ettei he usko minun päälleni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 10, 'Mutta vanhurskauden tähden, että minä menen Isäni tykö, ja ettette minua silleen näe;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 11, 'Mutta tuomion tähden, että tämän maailman päämies on tuomittu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 12, 'Minulla on vielä paljo sanomista, mutta ette voi nyt kantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 13, 'Vaan kuin se tulee, totuuden Henki, hän johdattaa teitä kaikkeen totuuteen; sillä ei hän puhu itsestänsä, vaan mitä hän kuulee, sitä hän puhuu, ja tulevaisia hän teille ilmoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 14, 'Hän on minua kunnioittava; sillä hän ottaa minun omastani ja ilmoittaa teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 15, 'Kaikki, mitä Isällä on, ne ovat minun; sentähden minä sanoin, että hän ottaa minun omastani ja ilmoittaa teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 16, 'Vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä te näette minun; sillä minä menen Isäni tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 17, 'Niin muutamat hänen opetuslapsistansa puhuivat keskenänsä: mikä se on, kuin hän sanoo meille: vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä ja te näette minun, ja: minä menen Isän tykö?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 18, 'Niin he sanoivat: mikä se on, kuin hän sanoo: vähän ajan perästä? emme tiedä, mitä hän puhuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 19, 'Niin Jesus ymmärsi, että he tahtoivat kysyä häneltä, ja sanoi heille: sitä te kysytte keskenänne, että minä sanoin: vähän ajan perästä ja ette näe minua, ja taas vähän ajan perästä ja te näette minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 20, 'Totisesti, totisesti sanon minä teille: teidän pitää itkemän ja parkuman, mutta maailma iloitsee: te tulette murheellisiksi, mutta teidän murheenne käännetään iloksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 21, 'Kuin vaimo synnyttää, niin hänellä on kipu, sillä hänen hetkensä tuli; mutta kuin hän on lapsen synnyttänyt, niin ei hän enään muista vaivaansa ilon tähden, että ihminen on syntynyt maailmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 22, 'Niin teillä on myös nyt murhe; mutta minä tahdon teitä jällensä nähdä, ja teidän sydämenne on iloitseva, ja ei kenenkään pidä teidän iloanne teiltä ottaman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 23, 'Ja sinä päivänä ette mitään kysy minulta. Totisesti, totisesti sanon minä teille: mitä ikänä te anotte Isältä minun nimeeni, niin hän antaa teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 24, 'Ette ole mitään minun nimeeni tähän asti anoneet: rukoilkaat, niin te saatte, että teidän ilonne olis täydellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 25, 'Näitä olen minä teille puhunut tapauksissa; mutta aika tulee, etten minä silleen puhu teille tapauksissa, vaan ilmoitan julkisesti teille minun Isästäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 26, 'Sinä päivänä pitää teidän rukoileman minun nimeeni. Ja en minä sano teille, että minä rukoilen Isää teidän tähtenne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 27, 'Sillä Isä rakastaa itse teitä, että te minua rakastitte ja uskoitte minun Jumalasta lähteneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 28, 'Minä läksin Isästä ja tulin maailmaan: taas minä jätän maailman ja menen Isän tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 29, 'Sanoivat hänen opetuslapsensa hänelle: katso, nyt sinä julkisesti puhut, ja et yhtään tapausta sano.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 30, 'Nyt me tiedämme sinun kaikki tietävän, ja et sinä tarvitse, että joku sinulta kysyy, sentähden me uskomme sinun Jumalasta lähteneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 31, 'Jesus vastasi heitä: nyt te uskotte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 32, 'Katso, aika tulee, ja nyt tuli, että te jokainen hajoitetaan omillensa, ja minun te yksinäni jätätte. En minä kuitenkaan yksinäni ole, sillä Isä on minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 33, 'Näitä olen minä teille puhunut, että teillä minussa rauha olis. Maailmassa on teillä tuska; mutta olkaat hyvässä turvassa, minä voitin maailman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 1, 'Näitä puhui Jesus, ja nosti silmänsä taivasta päin ja sanoi: Isä, hetki tuli, kirkasta sinun Poikas, että sinun Poikas kirkastais myös sinun!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 2, 'Niinkuin sinä annoit hänelle vallan kaiken lihan päälle, antaa ijankaikkisen elämän kaikille, jotka sinä hänelle annoit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 3, 'Mutta tämä on ijankaikkinen elämä, että he sinun ainoan totisen Jumalan tuntisivat, ja jonkas lähetit, Jesuksen Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 4, 'Minä kirkastin sinun maan päällä: minä täytin sen työn, jonkas minulle annoit tehdäkseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 5, 'Ja nyt Isä, kirkasta sinä minua itse tykänäs sillä kirkkaudella, joka minulla sinun tykönäs oli ennenkuin tämä maailma olikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 6, 'Minä ilmoitin sinun nimes ihmisille, jotkas minulle maailmasta annoit: he olivat sinun, ja minulle sinä ne annoit, ja sinun sanas he kätkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 7, 'He tiesivät nyt kaikki olevan sinusta, mitkä sinä minulle annoit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 8, 'Sillä ne sanat, jotka sinä minulle annoit, annoin minä heille; ja he ne ottivat vastaan, ja totisesti tunsivat minun sinusta lähteneen, ja uskoivat, että sinä minun lähetit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 9, 'Minä rukoilen heidän edestänsä: en minä maailman edestä rukoile, vaan niiden edestä, jotka sinä minulle annoit, että he ovat sinun omas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 10, 'Ja kaikki minun omani ovat sinun, ja sinun omas ovat minun: ja minä olen kirkastettu heissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 11, 'En minä silleen ole maailmassa, mutta he ovat maailmassa, ja minä tulen sinun tykös. Pyhä Isä! kätke niitä, jotka sinä minulle annoit, sinun nimes tähden, että he olisivat yksi niinkuin mekin!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 12, 'Kuin minä olin heidän kanssansa maailmassa, niin minä kätkin heitä sinun nimessäs: ne, jotkas minulle annoit, kätkin minä, ja ei niistä kenkään kadonnut, vaan se kadotuksen lapsi, että Raamattu täytettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 13, 'Mutta nyt minä tulen sinun tykös ja puhun näitä maailmassa, että heissä olis minun iloni täydellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 14, 'Minä annoin heille sinun sanas, ja maailma vihasi heitä; sillä ei he ole maailmasta, niinkuin en minäkään maailmasta ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 15, 'En minä rukoile, ettäs heitä ottaisit pois maailmasta, vaan ettäs heitä pahasta varjelisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 16, 'Ei he ole maailmasta, niinkuin en minäkään maailmasta ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 17, 'Pyhitä heitä totuudessas! Sinun puhees on totuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 18, 'Niinkuin sinä minun lähetit maailmaan, niin minä myös lähetin heidät maailmaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 19, 'Ja minä pyhitän itseni heidän tähtensä, että hekin olisivat totuudessa pyhitetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 20, 'Mutta en minä ainoasti heidän edestänsä rukoile, vaan myös niiden edestä, jotka heidän sanansa kautta uskovat minun päälleni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 21, 'Että he kaikki yhtä olisivat, niinkuin sinä Isä minussa olet ja minä sinussa, että hekin meissä niin yhtä olisivat: että maailma uskois sinun minua lähettäneeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 22, 'Ja minä annoin heille sen kunnian, jonka sinä minulle annoit, että he yhtä olisivat, niinkuin mekin yhtä olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 23, 'Minä olen heissä ja sinä minussa, että he niin yhdessä täydelliset olisivat, ja maailma tietäis, että sinä minun lähetit, ja että sinä heitä rakastit, niinkuin sinä minua rakastit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 24, 'Isä, minä tahdon, että kussa minä olen, siellä nekin olisivat minun kanssani, jotka sinä minulle antanut olet: että he minun kunniani näkisivät, jonkas minulle annoit; sillä sinä rakastit minua ennenkuin maailman perustus laskettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 25, 'Vanhurskas Isä! ei maailma sinua tuntenut, mutta minä tunsin sinun, ja nämät ymmärsivät, että sinä minun lähetit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 26, 'Ja minä julistin heille sinun nimes, ja vielä julistan: että se rakkaus, jolla sinä minua rakastit, heissä olis, ja minä myös heissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 1, 'Kuin Jesus nämät oli sanonut, meni hän ulos opetuslastensa kanssa Kedronin ojan ylitse: siellä oli yrttitarha, johon hän meni sisälle ja hänen opetuslapsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 2, 'Mutta Juudas, joka hänen petti, tiesi myös sen paikan; sillä Jesus tuli sinne usein opetuslastensa kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 3, 'Kuin siis Juudas oli joukon kanssansa ottanut ja palveliat ylimmäisiltä papeilta ja Pharisealaisilta, tuli hän sinne lyhdyillä, tulisoitoilla ja sota-aseilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 4, 'Kuin siis Jesus tiesi kaikki, mitä hänelle tapahtuman piti, niin hän läksi ja sanoi heille: ketä etsitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 5, 'He vastasivat häntä: Jesusta Natsaretilaista. Sanoi Jesus heille: minä olen! Mutta Juudas, jonka hänen petti, seisoi myös heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 6, 'Kuin siis Jesus sanoi heille: minä olen, astuivat he takaperin ja lankesivat maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 7, 'Niin hän taas kysyi heiltä: ketä te etsitte? Mutta he sanoivat: Jesusta Natsarealaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 8, 'Jesus vastasi: minä sanoin teille, että minä olen. Jos te siis minua etsitte, niin antakaat näiden mennä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 9, 'Että se puhe täytettäisiin, jonka hän oli sanonut: en minä niistä yhtään kadottanut, jotka sinä minulle annoit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 10, 'Niin Simon Pietarilla oli miekka, jonka hän veti ulos, ja löi ylimmäisen papin palveliaa ja hakkasi pois hänen oikian korvansa; jonka palvelian nimi oli Malkus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 11, 'Niin Jesus sanoi Pietarille: pistä miekkas tuppeen: eikö minun pidä juoman sitä kalkkia, jonka Isä minulle antoi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 12, 'Niin joukko ja ylimmäinen päämies ja Juudalaisten palveliat ottivat kiinni Jesuksen ja sitoivat hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 13, 'Ja veivät ensin Hannaksen tykö, sillä hän oli Kaiphaan appi, joka oli sinä vuonna ylimmäinen pappi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 14, 'Ja Kaiphas oli se, joka Juudalaisille oli neuvon antanut, että yhtä ihmistä olis tarpeellinen kuolettaa kansan edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 15, 'Ja Simon Pietari seurasi Jesusta, ja toinen opetuslapsi. Mutta se opetuslapsi oli ylimmäisen papin tuttava ja meni sisälle Jesuksen kanssa ylimmäisen papin saliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 16, 'Mutta Pietari jäi ulos oven eteen. Niin toinen opetuslapsi, joka ylimmäisen papin tuttava oli, meni ulos ja puhui ovenvartialle, ja toi Pietarin sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 17, 'Niin sanoi ovenvartiapiika Pietarille: etkö sinäkin olen tämän miehen opetuslapsia? Hän sanoi: en ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 18, 'Mutta palveliat, jotka hiilistä olivat tulen tehneet, sillä kylmä oli, seisoivat ja lämmittelivät. Ja Pietari seisoi myös heidän kanssansa ja lämmitteli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 19, 'Niin ylimmäinen pappi kysyi Jesukselta hänen opetuslapsestansa ja opetuksestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 20, 'Jesus vastasi häntä: minä olen maailman edessä julkisesti puhunut: minä olen synagogassa opettanut ja templissä, johonka Juudalaiset joka paikasta kokoon tulevat, ja en ole mitään salaisuudessa puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 21, 'Mitäs minulta kysyt? Kysy niiltä, jotka kuulivat, mitä minä heille puhunut olen. Katso, ne tietävät, mitä minä sanonut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 22, 'Mutta kuin hän näitä puhui, antoi yksi niistä palvelioita, jotka läsnä seisoivat, Jesukselle korvapuustin ja sanoi: niinkö sinä vastaat ylimmäistä pappia!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 23, 'Jesus vastasi häntä: jos minä pahasti puhuin, niin tunnusta se pahaksi, mutta jos minä oikein puhuin, miksis minua lyöt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 24, 'Niin Hannas lähetti hänen sidottuna ylimmäisen papin Kaiphaan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 25, 'Mutta Simon Pietari seisoi ja lämmitteli. Niin he sanoivat hänelle: etkö sinä ole myös hänen opetuslapsiansa? Hän kielsi ja sanoi: en ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 26, 'Sanoi hänelle yksi ylimmäisen papin palvelioista, sen lanko, jonka korvan Pietari hakkasi pois: enkö minä sinua nähnyt yrttitarhassa hänen kanssansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 27, 'Niin Pietari taas kielsi, ja kohta kukko lauloi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 28, 'Niin he veivät Jesuksen Kaiphaan tyköä raastupaan. Mutta se oli aamu, ja ei he menneet raastupaan, ettei he itsiänsä saastuttaisi, vaan söisivät pääsiäislampaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 29, 'Niin Pilatus meni ulos heidän tykönsä ja sanoi: mitä kannetta te tuotte tätä miestä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 30, 'He vastasivat ja sanoivat hänelle: ellei hän pahantekiä olisi, emme olisi häntä sinun haltuus antaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 31, 'Niin Pilatus sanoi heille: ottakaat te häntä ja tuomitkaat häntä teidän lakinne jälkeen. Juudalaiset sanoivat siis hänelle: meidän ei sovi ketään tappaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 32, 'Että jesuksen puhe täytettäisiin, kuin hän sanoi, merkiten, millä kuolemalla hänen piti kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 33, 'Niin Pilatus taas meni raastupaan, kutsui Jesuksen ja sanoi hänelle: oletkos sinä Juudalaisten kuningas?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 34, 'Jesus vastasi häntä: sanotko sinä sen itsestäs, eli ovatko muut sen minusta sinulle sanoneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 35, 'Pilatus vastasi: olenko minä Juudalainen? Sinun kansas ja ylimmäiset papit antoivat ylön sinun minulle: mitäs tehnyt olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 36, 'Jesus vastasi: ei minun valtakuntani ole tästä maailmasta. Jos minun valtakuntani olis tästä maailmasta, niin tosin minun palveliani olisivat sotineet, etten minä olisi tullut annetuksi ylön Juudalaisille; mutta ei minun valtakuntakuntani ole täältä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 37, 'Niin Pilatus sanoi hänelle: niin sinä olet kuningas? Jesus vastasi: sinä sen sanot, että minä olen kuningas. Sitä varten olen minä syntynyt ja sitä varten maailmaan tullut, että minä totuden tunnustan. Jokainen, joka on totuudesta, se kuulee minun ääneni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 38, 'Pilatus sanoi hänelle: minä on totuus? Ja kuin hän sen sanonut oli, meni hän taas ulos Juudalaisten tykö ja sanoi heille: en minä löydä yhtään syytä hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 39, 'Mutta teillä on tapa, että minun pitää teille päästämän yhden pääsiäisenä: tahdotteko siis, että minä päästän teille Juudalaisten kuninkaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 40, 'Niin he huusivat taas kaikki, sanoen: ei tätä, vaan Barabbasta. Mutta Barabbas oli ryöväri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 1, 'Niin Pilatus otti silloin Jesuksen ja ruoskitsi hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 2, 'Ja sotamiehet väänsivät kruunun orjantappuroista, panivat sen hänen päähänsä ja puettivat hänen purpuravaatteesen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 3, 'Ja sanoivat: terve, Juudalaisten kuningas! ja antoivat hänelle korvapuusteja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 4, 'Taas tuli Pilatus ulos ja sanoi heille: katsokaat, minä tuon hänen teille ulos, että te tietäisitte, etten minä löydä yhtään syytä hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 5, 'Niin Jesus meni ulos, kantain orjantappuraista kruunua ja purpuraista vaatetta. Ja hän sanoi heille: katso ihmistä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 6, 'Mutta kuin ylimmäiset papit ja palveliat hänen näkivät, huusivat he, sanoen: ristiinnaulitse, ristiinnaulitse häntä! Pilatus sanoi heille: ottakaat te häntä ja ristiinnaulitkaat; sillä en minä löydä yhtään syytä hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 7, 'Vastasivat häntä Juudalaiset: meillä on laki, ja meidän lakimme jälkeen pitää hänen kuoleman, että hän teki itsensä Jumalan Pojaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 8, 'Kun siis Pilatus tämän puheen kuuli, pelkäsi hän vielä enemmin');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 9, 'Ja meni taas raastupaan ja sanoi Jesukselle: kusta sinä olet? Mutta ei Jesus vastannut häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 10, 'Niin Pilatus sanoi hänelle: etkös mitään minulle puhu? Etkös tiedä, että minulla on valta sinua ristiinnaulita ja valta sinua päästää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 11, 'Jesus vastasi: ei sinulla olisi yhtään valtaa minua vastaan, jos ei se olisi sinulle annettu ylhäältä: sentähden on hänellä suurempi synti, joka minun sinulle antoi ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 12, 'Ja siitä ajasta pyysi Pilatus häntä päästää. Mutta Juudalaiset huusivat, sanoen: jos sinä hänen päästät, niin et sinä ole keisarin ystävä; sillä jokainen, joka itsensä tekee kuninkaaksi, hän on keisaria vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 13, 'Kuin Pilatus tämän puheen kuuli, vei hän Jesuksen ulos ja istui tuomio-istuimelle, siihen paikkaan, joka kutsutaan Litostroton, mutta Hebreaksi Gabbata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 14, 'Mutta se oli pääsiäisen valmistuspäivä, lähes kuudennella hetkellä. Ja hän sanoi Juudalaisille: katso, teidän kuninkaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 15, 'Mutta he huusivat: ota pois, ota pois, ristiinnaulitse häntä! Pilatus sanoi heille: pitääkö minun ristiinnaulitseman teidän kuninkaanne? Ylimmäiset papit vastasivat: ei meillä ole kuningasta, vaan keisari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 16, 'Niin silloin hän antoi hänen heille ristiinnaulittaa. Mutta he ottivat Jesuksen ja veivät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 17, 'Ja hän kantoi ristiänsä ja meni siihen paikkaan, joka kutsutaan Pääkallon paikaksi, mutta Hebreaksi Golgata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 18, 'Siellä he ristiinnaulitsivat hänen ja kaksi muuta hänen kanssansa kahden puolen, mutta Jesuksen keskelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 19, 'Niin Pilatus kirjoitti myös päällekirjoituksen ja pani ristin päälle, ja oli näin kirjoitettu: JESUS NATSARENUS JUUDALAISTEN KUNINGAS.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 20, 'Tämän päällekirjoituksen luki monta Juudalaisista; sillä se paikka oli läsnä kaupunkia, jossa Jesus ristiinnaulittiin. Ja oli kirjoitettu Hebreaksi, Grekaksi ja Latinaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 21, 'Niin sanoivat Juudalaisten ylimmäiset papit Pilatukselle: älä kirjoita: Juudalaisten kuningas; vaan että hän on sanonut: minä olen Juudalaisten kuningas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 22, 'Pilatus vastasi: mitä minä kirjoitin, sen minä kirjoitin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 23, 'Kuin siis sotamiehet olivat Jesuksen ristiinnaulinneet, ottivat he hänen vaatteensa (ja tekivät neljä osaa, kullekin sotamiehelle osan), ja hameen; mutta hame ei ollut ommeltu, vaan kokonansa ylhäältä (alaspäin) kudottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 24, 'Niin he sanoivat keskenänsä: älkäämme tätä rikkoko, vaan heittäkäämme tästä arpaa, kenenkä se pitää oleman: että Raamattu täytettäisiin, joka sanoo: he ovat minun vaatteeni itsellensä jakaneet ja ovat heittäneet minun hameestani arpaa. Ja sotamiehet tosin näin tekivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 25, 'Mutta Jesuksen ristin tykönä seisoi hänen äitinsä ja hänen äitinsä sisar Maria, Kleopaan emäntä, ja Maria Magdalena.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 26, 'Kuin siis Jesus näki äidin ja opetuslapsen siinä seisovan, jota hän rakasti, sanoi hän äidillensä: vaimo, katso sinun poikaas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 27, 'Sitte sanoi hän opetuslapselle: katso sinun äitiäs. Ja siitä hetkestä otti opetuslapsi hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 28, 'Sitte, kuin Jesus tiesi jo kaikki täytetyksi, ja että Raamattu täytettäisiin, sanoi hän: minä janoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 29, 'Oli siis yksi astia pantu etikkaa täyteen, ja he täyttivät sienen etikalla ja panivat sen ympärille isoppia, ja panivat sen hänen suunsa eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 30, 'Kuin siis Jesus oli etikkaa ottanut, sanoi hän: se on täytetty! ja kallisti päänsä ja antoi henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 31, 'Mutta että valmistuspäivä oli, ja ei ruumiit pitänyt ristissä oleman sabbatina, (sillä se sabbatin päivä oli suuri,) rukoilivat siis Juudalaiset Pilatusta, että heidän sääriluunsa piti rikottaman ja he otettaman alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 32, 'Niin sotamiehet tulivat ja rikkoivat ensimmäisen luut ja toisen, joka hänen kanssansa oli ristiinnaulittu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 33, 'Mutta kuin he tulivat Jesuksen tykö ja näkivät hänen jo kuolleeksi, niin ei he rikkoneet hänen luitansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 34, 'Vaan yksi sotamiehistä avasi hänen kylkensä keihäällä, josta kohta vuoti veri ja vesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 35, 'Ja joka tämän näki, hän on sen todistanut ja hänen todistuksensa on tosi, ja hän tietää totta sanovansa, että te myös uskoisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 36, 'Sillä nämät ovat tapahtuneet, että Raamattu täytettäisiin: ei teidän pidä luuta rikkoman hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 37, 'Ja taas toinen kirjoitus sanoo: he saavat nähdä, ketä he ovat pistäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 38, 'Mutta sen jälkeen rukoili Pilatusta Joseph Arimatiasta, (joka oli Jesuksen opetuslapsi, vaan salaa Juudalaisten pelvon tähden), että hän olis saanut ottaa Jesuksen ruumiin; ja Pilatus salli sen. Niin hän tuli ja otti Jesuksen ruumiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 39, 'Niin tuli myös Nikodemus, (joka oli ensin yöllä Jesuksen tykö tullut,) ja toi mirhamia ja aloeta sekoitettua, lähes sata naulaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 40, 'Niin he ottivat Jesuksen ruumiin ja käärivät sen liinaiseen, hyvän-hajullisten yrttein kanssa, niinkuin Juudalaisten tapa on haudata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 41, 'Mutta siinä paikassa, jossa hän ristiinnaulittiin, oli yrttitarha, ja yrttitarhassa uusi hauta, johonka ei vielä kenkään ollut pantu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 42, 'Siihen he panivat Jesuksen Juudalaisten valmistuspäivän tähden, että se hauta oli läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 1, 'Mutta ensimmäisenä päivänä viikossa tuli Maria Magdalena varhain, kuin vielä pimiä oli, haudalle ja näki kiven otetuksi pois haudalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 2, 'Niin hän juoksi ja tuli Simon Pietarin tykö ja sen opetuslapsen tykö, jota Jesus rakasti, ja sanoi heille: he ovat Herran ottaneet pois haudasta, ja emme tiedä, kuhunka he hänen panivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 3, 'Niin Pietari meni ulos ja toinen opetuslapsi, ja tulivat haudalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 4, 'Mutta he juoksivat kahden ynnä, ja toinen opetuslapsi juoksi edellä nopeammin kuin Pietari, ja tuli ensin haudalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 5, 'Ja kuin hän itsensä kumarsi, näki hän liinaiset pantuna, mutta ei hän kuitenkaan mennyt sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 6, 'Niin Simon Pietari tuli seuraten häntä, ja meni hautaan, ja näki kääriliinat pantuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 7, 'Ja hikiliinan, joka hänen päänsä päällä oli ollut, ei kääriliinan kanssa, vaan erinänsä käärittynä yhteen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 8, 'Niin meni myös toinen opetuslapsi sisälle, joka ensin haudalle tullut oli, ja näki sen ja uskoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 9, 'Sillä ei he vielä Raamattua ymmärtäneet, että hän oli nouseva kuolleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 10, 'Niin ne opetuslapset menivät taas yhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 11, 'Mutta Maria seisoi ulkona haudan edessä ja itki. Ja kuin hän niin itki, kumarsi hän itsensä hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 12, 'Ja näki kaksi enkeliä valkeissa vaatteissa istuvan, yhden pään puolessa ja toisen jalkain puolessa, siinä missä Jesuksen ruumis pantu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 13, 'Ne sanoivat hänelle: vaimo, mitäs itket? Hän sanoi heille: he ovat minun Herrani ottaneet pois, ja en tiedä, kuhunka he hänen ovat panneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 14, 'Ja kuin hän nämät sanonut oli, käänsi hän itsensä taapäin, ja näki Jesuksen seisovan, eikä tietänyt, että se oli Jesus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 15, 'Sanoi Jesus hänelle: vaimo, mitäs itket? ketäs etsit? Mutta hän luuli sen yrttitarhan haltiaksi, ja sanoi hänelle: Herra, jos sinä hänen kannoit pois, niin sano minulle, kuhunkas hänen panit, ja minä tahdon hänen ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 16, 'Jesus sanoi hänelle: Maria! niin hän käänsi itsensä ja sanoi hänelle: Rabboni, se on: Mestari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 17, 'Jesus sanoi hänelle: älä minuun rupee; sillä en minä ole vielä mennyt ylös minun Isäni tykö, vaan mene minun veljeini tykö ja sano heille: minä menen ylös minun Isäni tykö ja teidän Isänne tykö, ja minun Jumalani tykö ja teidän Jumalanne tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 18, 'Maria Magdalena tuli ja ilmoitti opetuslapsille, että hän oli nähnyt Herran, ja että hän näitä hänelle sanoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 19, 'Kuin siis sen sabbatin päivän ehtoo oli, ja ovet olivat suljetut, jossa opetuslapset kokoontuneet olivat Juudalaisten pelvon tähden, tuli Jesus ja seisoi heidän keskellänsä ja sanoi heille: rauha olkoon teille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 20, 'Ja kuin hän sen sanonut oli, osoitti hän heille kätensä ja kylkensä. Niin opetuslapset ihastuivat, että he näkivät Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 21, 'Ja Jesus taas sanoi heille: rauha olkoon teille! niinkuin Isä minun lähetti, niin minä myös lähetän teidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 22, 'Ja kuin hän nämät sanonut oli, puhalsi hän heidän päällensä ja sanoi heille: ottakaat Pyhä Henki:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 23, 'Joille te synnit anteeksi annatte, niille ne anteeksi annetaan, ja joille te ne pidätte, niille ne ovat pidetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 24, 'Mutta Toomas, yksi kahdestatoistakymmenestä, joka kaksoiseksi kutsutaan, ei ollut heidän kanssansa, kuin Jesus tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 25, 'Niin muut opetuslapset sanoivat hänelle: me näimme Herran. Mutta hän sanoi heille: ellen minä näe hänen käsissänsä naulan reikää, ja pistä sormeani naulain siaan, ja pistä kättäni hänen kylkeensä, en minä usko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 26, 'Ja kahdeksan päivän perästä olivat opetuslapset taas sisällä, ja Toomas heidän kanssansa. Niin Jesus tuli, kuin ovet suljetut olivat, ja seisoi heidän keskellänsä, ja sanoi: rauha olkoon teille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 27, 'Sitte sanoi hän Toomaalle: pistä sormes tänne, ja katso minun käsiäni, ja ojenna tänne kätes, ja pistä minun kylkeeni, ja älä ole epäuskoinen, vaan uskovainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 28, 'Toomas vastasi ja sanoi hänelle: minun Herrani ja minun Jumalani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 29, 'Jesus sanoi hänelle: ettäs näit minun, Toomas, niin sinä uskoit: autuaat ovat ne, jotka ei näe, ja kuitenkin uskovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 30, 'Niin teki myös Jesus monta muuta merkkiä opetuslastensa nähden, jotka ei tässä kirjassa ole kirjoitetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 31, 'Mutta nämät ovat kirjoitetut, että te uskoisitte, että Jesus on Kristus, Jumalan Poika, ja että te saisitte elämän uskon kautta hänen nimeensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 1, 'Sitte ilmoitti Jesus taas itsensä opetuslapsille Tiberiaan meren tykönä, ja hän ilmoitti itsensä näin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 2, 'Simon Pietari ja Toomas, joka kaksoiseksi kutsutaan, olivat ynnä ja Natanael, joka oli Galilean Kaanasta, ja Zebedeuksen pojat ja kaksi muuta hänen opetuslapsistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 3, 'Sanoi Simon Pietari heille: minä menen kalaan: ne sanoivat hänelle: me menemme myös kanssas. Niin he menivät ja astuivat kohta venheesen, ja ei he sinä yönä mitään saaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 4, 'Mutta kuin jo aamu oli, niin Jesus seisoi rannalle; mutta ei opetuslapset tietäneet, että se oli Jesus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 5, 'Niin sanoi Jesus heille: lapset, onko teillä mitään syötävää? He vastasivat häntä: ei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 6, 'Hän sanoi heille: laskekaat verkko oikialle puolelle venhettä, niin te löydätte. Niin he laskivat, ja tuli niin paljo kaloja, ettei he voineet vetää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 7, 'Niin sanoi se opetuslapsi, jota Jesus rakasti, Pietarille: Herra se on. Kuin Simon Pietari sen kuuli, että se oli Herra, vyötti hän hameen ympärillensä, (sillä hän oli alasti,) ja heitti itsensä mereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 8, 'Mutta muut opetuslapset tulivat venheellä, (sillä ei he olleet kaukana maalta, vaan lähes kaksisataa kyynärää,) ja vetivät verkon kaloinensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 9, 'Kuin he siis olivat maalle tulleet, näkivät he hiilet ja kalan, niiden päällä pantuna, ja leivän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 10, 'Jesus sanoi heille: tuokaat tänne niistä kaloista, jotka te nyt saitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 11, 'Simon Pietari meni ja veti verkon maalle, täynnä suuria kaloja, sata ja kolmekuudettakymmentä. Ja vaikka niitä niin monta oli, ei kuitenkaan verkko revennyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 12, 'Jesus sanoi heille: tulkaat rualle; mutta ei yksikään opetuslapsista uskaltanut häntä kysyä: kukas olet? sillä he tiesivät sen olevan Herran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 13, 'Niin Jesus tuli, otti leivän ja antoi heille, niin myös kalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 14, 'Tämä on kolmas kerta, kuin Jesus opetuslapsillensa ilmestyi, sitte kuin hän oli noussut ylös kuolleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 15, 'Kuin he siis syöneet olivat, sanoi Jesus Simon Pietarille: Simon Jonan poika! rakastatkos minua enempi kuin nämät? Hän sanoi: jaa, Herra, sinä tiedät, että minä sinua rakastan. Hän sanoi hänelle: ruoki minun karitsoitani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 16, 'Ja sanoi taas toisen kerran hänelle: Simon Jonan poika! rakastatkos minua? Hän vastasi: jaa, Herra, sinä tiedät, että minä sinua rakastan. Sanoi hän hänelle: kaitse minun lampaitani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 17, 'Hän sanoi kolmannen kerran hänelle: Simon Jonan poika! rakastatkos minua? Pietari tuli murheelliseksi, että hän kolmannen kerran sanoi hänelle: rakastatkos minua? ja sanoi hänelle: Herra, sinä tiedät kaikki: sinä tiedät, että minä rakastan sinua. Jesus sanoi hänelle: ruoki minun lampaitani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 18, 'Totisesti, totisesti sanon minä sinulle: kuin sinä olit nuori, niin sinä vyötit itses ja menit, kuhunkas tahdoit; mutta kuin vanhenet, niin sinä ojennat kätes, ja toinen vyöttää sinun, ja vie, kuhunka et sinä tahdo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 19, 'Mutta sen hän sanoi, antain tietää, millä kuolemalla hänen piti kunnioittaman Jumalaa. Ja kuin hän sen sanonut oli, sanoi hän hänelle: seuraa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 20, 'Pietari käänsi itsensä, ja näki sen opetuslapsen seuraavan, jota Jesus rakasti, joka myös oli Jesuksen rinnoilla ehtoollisessa maannut, ja sanonut: Herra, kuka se on, joka sinun pettää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 21, 'Kuin siis Pietari hänen näki, sanoi hän Jesukselle: Herra, mitästä tämä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 22, 'Jesus sanoi hänelle: jos minä tahtoisin hänen siihenasti olevan kuin minä tulen, mitä sinun siihen tulee? Seuraa sinä minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 23, 'Niin veljesten seassa kävi ulos se puhe, ettei sen opetuslapsen pitänyt kuoleman. Mutta ei Jesus hänelle sanonut: ei hän kuole, vaan: jos minä tahdon hänen siihenasti olevan kuin minä tulen, mitä sinun siihen tulee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 24, 'Tämä on se opetuslapsi, joka todistaa näistä ja on nämät kirjoittanut, ja me tiedämme hänen todistuksensa todeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 25, 'On myös paljon muuta, mitä Jesus teki, jos ne erinänsä kirjoitettaisiin, en minä luulisi koko maailman käsittävän niitä kirjoja, joita pitäis kirjoitettaman. Amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Ennen olen minä tosin, oi Teophilus, puhunut kaikista niistä, mitä Jesus rupesi sekä tekemään että opettamaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Hamaan siihen päivään asti, jona hän otettiin ylös, sitte kuin hän apostoleille, jotka hän valinnut oli, Pyhän Hengen kautta oli käskyn antanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Joille hän myös kärsimisensä jälkeen oli itsensä eläväksi osoittanut moninaisilla merkeillä, ja näkyi heille neljäkymmentä päivää, ja puhui heille Jumalan valtakunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Ja kuin hän heidät oli koonnut, kielsi hän heitä lähtemästä Jerusalemista, vaan että he Isän lupausta odottaisivat, josta te olette (sanoi hän) kuulleet minulta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Sillä Johannes tosin kasti vedellä, mutta te kastetaan Pyhällä Hengellä, ei monen päivän perästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'Kuin he siis kokoontuneet olivat, kysyivät he häneltä, sanoen: Herra, tällä ajallakos Israelille valtakunnan jälleen rakennat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Mutta hän sanoi heille: ei teidän tule tietää aikaa eikä hetkeä, jotka Isä on omaan voimaansa pannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Vaan teidän pitää saaman Pyhän Hengen voiman, joka on tuleva teidän päällenne, ja teidän pitää minun todistajani oleman, sekä Jerusalemissa, että koko Juudeassa ja Samariassa, ja sitte maailman ääreen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Ja kuin hän nämät sanonut oli, otettiin hän ylös heidän nähtensä, ja pilvi vei hänen ylös heidän silmäinsä edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Ja kuin he katselivat taivaaseen, hänen mennessänsä, katso, heidän tykönänsä seisoi kaksi miestä valkeissa vaatteissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Jotka myös sanoivat: Galilean miehet, mitä te seisotte ja katsotte taivaasen? Tämä Jesus, joka teiltä otettiin ylös taivaasen, on niin tuleva kuin te hänen taivaasen menevän näitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Silloin he palasivat Jerusalemiin vuorelta, joka Öljymäeksi kutsutaan ja on läsnä Jerusalemia sabbatin matkan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Ja kuin he tulivat sisälle, niin he astuivat ylös saliin, kussa he oleskelivat: Pietari ja Jakob, ja Johannes ja Andreas, Philippus ja Toomas, Bartolomeus ja Matteus, Jakob Alphein poika ja Simon Zelotes, ja Juudas Jakobin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Nämät kaikki olivat yksimielisesti pysyväiset rukouksessa ja anomisessa, vaimoin kanssa ja Marian Jesuksen äidin ja hänen veljeinsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Ja niinä päivinä nousi Pietari opetuslasten keskellä ja sanoi: (ja joukko oli nimiltä yhteen lähes kaksikymmentä toista sataa:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Te miehet ja veljet! se kirjoitus piti täytettämän, jonka Pyhä Henki oli Davidin suun kautta Juudaasta ennen sanonut, joka niiden johdattajaksi tuli, jotka Jesuksen ottivat kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Sillä hän oli meidän lukuumme luettu, ja oli tämän viran meidän kanssamme saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Hän siis on ansainnut pellon vääryyden palkasta, ja kuin hän pudotettiin alas, on hän keskeltä kahtia pakahtunut, että kaikki hänen sisällyksensä läksivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Ja se oli tiettävä kaikille, jotka Jerusalemissa asuvat, että se pelto heidän kielellänsä kutsutaan Akeldama, se on: veripelto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Sillä se on kirjoitettu Psaltari-raamatussa: hänen kotonsa tulkoon kylmille eikä siinä pidä asujanta oleman, ja toisen pitää hänen piispautensa saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Niin pitää näistä miehistä, jotka meidän kanssamme olleet ovat kaiken sen ajan kuin Herra Jesus meidän kanssamme ulos ja sisälle kävi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 22, 'Ruveten Johanneksen kasteesta hamaan siihen päivään asti, jona hän meiltä otettiin ylös, yksi tuleman hänen ylösnousemisensa todistajaksi ynnä meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 23, 'Ja he asettivat kaksi ehdolle: Josephin, joka kutsuttiin Barsabas ja liialta nimeltä Justus, ja Mattiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 24, 'Ja he rukoilivat ja sanoivat: sinä Herra, joka kaikkein sydämet tiedät! osoita, kumman sinä näistä kahdesta olet valinnut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 25, 'Saamaan tämän palveluksen ja apostolin viran arpaa, josta Juudas on vilpistynyt pois, menemään pois siallensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 26, 'Ja he heittivät heistä arpaa, ja arpa lankesi Mattiaan päälle, ja hän valittiin yksimielisesti yhdentoistakymmenen apostolin sekaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Ja kuin viideskymmenes päivä täytettiin, olivat he kaikki yksimielisesti koossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Ja humaus tapahtui äkisti taivaasta, niinkuin suuri tuulispää olis tullut, ja täytti koko huoneen, kussa he olivat istumassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Ja heille näkyivät viileskellyt kielet, niinkuin tuliset, ja istuivat kunkin heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Ja he täytettiin kaikki Pyhällä Hengellä ja rupesivat puhumaan muilla kielillä, senjälkeen kuin Henki antoi heidän puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Niin Jerusalemissa asui Juudalaisia, Jumalaa pelkääväisiä miehiä, kaikkinaisesta kansasta, joka taivaan alla on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Ja kuin tämä ääni tapahtui, niin kokoontui suuri kansan paljous, ja hämmästyivät; sillä kukin kuuli niiden puhuvan omalla kielellänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Ja he tyhmistyivät kaikki ja ihmettelivät, sanoen keskenänsä: katso, eikö nämät kaikki, jotka puhuvat, ole Galilealaiset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Ja kuinka me kukin kuulemme heidän puhuvan meidän omalla kielellämme, jossa me syntyneet olemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Partilaiset ja Mediläiset ja Elamilaiset, ja jotka asumme Mesopotamiassa ja Juudeassa ja Kappadokiassa, Pontossa ja Asiassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Phrygiassa ja Pamphiliassa, Egyptissä ja Libian maan rajoilla, liki Kyreniä, ja muukalaiset Roomista, Juudalaiset ja uudet Juudalaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Kretalaiset ja Arabialaiset, me kuulemme heidän puhuvan meidän kielillämme Jumalan suuria tekoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Niin he kaikki tyhmistyivät ja epäilivät, sanoen toinen toisellensa: mitäs luulet tämän olevan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Vaan muut nauroivat heitä ja sanoivat: he ovat täynnänsä makiaa viinaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Niin Pietari seisoi yhdentoistakymmenen kanssa, korotti äänensä ja puhui heille: te Juudan miehet ja kaikki, jotka asutte Jerusalemissa! tämä olkoon teille tiettävä, ja ottakaat minun sanani teidän korviinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Sillä ei nämät juovuksissa ole, niinkuin te luulette; sillä nyt on kolmas hetki päivästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Vaan tämä on se, mikä ennen sanottu on Joelin prophetan kautta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ja pitää tapahtuman viimeisinä päivinä (sanoo Jumala), että minä tahdon vuodattaa minun Hengestäni kaiken lihan päälle: ja teidän poikanne ja tyttärenne pitää ennustaman, ja teidän nuorukaisenne pitää näkyjä näkemän, ja teidän vanhimpanne pitää unia uneksuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Ja myös minun palveliaini päälle ja minun piikaini päälle niinä päivinä vuodatan minä minun Hengestäni, ja heidän pitää ennustaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Ja minä annan tunnustähtiä ylhäällä taivaassa ja merkkejä alhaalla maan päällä, veren ja tulen ja savun ja suitsun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Auringon pitää muuttuman pimeydeksi ja kuun vereksi, ennenkuin se suuri ja julkinen Herran päivä on tuleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Ja pitää tapahtuman, että jokainen, joka avuksi huutaa Herran nimeä, se tulee autuaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Te Israelin miehet! kuulkaat näitä sanoja: Jesuksen Natsarelaisen, sen miehen, joka teidän tykönänne on Jumalalta vahvistettu voimallisten tekoin, ihmetten ja merkkein kanssa, jotka Jumala hänen kauttansa teidän keskellänne teki, niinkuin te itsekin tiedätte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 23, 'Sen, joka Jumalan aivotun neuvon ja säännön jälkeen oli annettu ulos, te otitte ja vääräin miesten kätten kautta ristiinnaulitsitte ja surmasitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 24, 'Jonka Jumala herätti ylös ja päästi kuoleman kivuista, että se oli mahdotoin, että hän piti siltä pidettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 25, 'Sillä David sanoo hänestä: minä olen aina Herran minun kasvoini eteen pannut, sillä hän on minun oikialla puolellani, etten minä horjahtaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 26, 'Sentähden iloitsi minun sydämeni, ja minun kieleni riemuitsi, ja minun lihani on myös lepäävä toivossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 27, 'Sillä et sinä anna ylön minun sieluani helvetissä, etkä salli sinun pyhäs näkevän turmelusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 28, 'Sinä olet minulle tiettäväksi tehnyt elämän tiet, sinä täytät minun ilolla sinun kasvois edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 29, 'Te miehet, rakkaat veljet, olkoon lupa rohkiasti teille puhua patriarkasta Davidista! hän on sekä kuollut että haudattu ja hänen hautansa on meidän tykönämme hamaan tähän päivään asti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 30, 'Että hän siis oli propheta ja tiesi Jumalan hänelle valalla vannoneen, että hän oli hänen kupeensa hedelmästä lihan jälkeen herättävä Kristuksen hänen istuimellansa istumaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 31, 'Näki hän ennen ja puhui Kristuksen ylösnousemisesta, ettei hänen sieluansa annettu ylön helvetissä, eikä hänen lihansa nähnyt turmelusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 32, 'Tämän Jesuksen on Jumala herättänyt, jonka todistajat me kaikki olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 33, 'Hän on siis Jumalan oikialle kädelle korotettu ja on Isältä saanut lupauksen Pyhästä Hengestä: hän on tämän vuodattanut, kuin te nyt näette ja kuulette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 34, 'Sillä ei David ole taivaasen astunut, vaan hän sanoo: Herra sanoi minun Herralleni: istu minun oikialle kädelleni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 35, 'Siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 36, 'Niin pitää siis totisesti kaiken Israelin huoneen tietämän, että Jumala on tämän Jesuksen, jonka te ristiinnaulitsitte, Herraksi ja Kristukseksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 37, 'Mutta kuin he nämät kuulivat, kävi se läpi heidän sydämensä, ja sanoivat Pietarille ja muille apostoleille: te miehet, rakkaat veljet! mitä meidän pitää tekemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 38, 'Vaan Pietari sanoi heille: tehkäät parannus, ja antakaan jokainen itsensä kastaa Jesuksen Kristuksen nimeen, syntein anteeksi antamiseksi, niin te saatte Pyhän Hengen lahjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 39, 'Sillä teille ja teidän lapsillenne on tämä lupaus annettu, ja kaikille, jotka taampana ovat, kutka ikänä Herra meidän Jumalamme kutsuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 40, 'Ja monilla muillakin sanoilla todisti hän, ja neuvoi heitä, sanoen: antakaat teitänne autettaa tästä pahanilkisestä suvusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 41, 'Jotka siis mielellänsä hänen sanansa ottivat vastaan, ne kastettiin; ja sinä päivänä lisääntyi lähes kolmetuhatta sielua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 42, 'Ja he pysyivät alati apostolien opissa ja osallisuudessa, ja leivän murtamisessa ja rukouksissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 43, 'Mutta jokaiselle sielulle tuli pelko; ja tehtiin apostolien kautta monta ihmettä ja merkkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 44, 'Mutta kaikki, jotka uskoivat, olivat yhdessä ja pitivät kaikki yhteisenä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 45, 'Ja he myivät hyvyytensä ja tavaransa, ja jakoivat ne kaikille, sen jälkeen kuin kukin tarvitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 46, 'Ja he pysyivät joka päivä yksimielisesti templissä, ja mursivat huoneessa leipää, ja ottivat ruokaa riemulla ja sydämen yksinkertaisuudella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 47, 'Ja kiittäin Jumalaa olivat kaiken kansan suosiossa. Ja Herra lisäsi joka päivä autuaaksi tulevaisia seurakunnalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Niin Pietari ja Johannes menivät ynnä ylös templiin yhdeksännellä rukouksen hetkelle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Ja mies, saattamatoin hamasta äitinsä kohdusta, kannettiin; jonka he panivat joka päivä sen templin oven eteen, joka kutsutaan Kauniiksi, anomaan niiltä almua, jotka templiin menivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Kuin hän näki Pietarin ja Johanneksen tahtovan mennä templiin, anoi hän heiltä almua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Niin Pietari Johanneksen kanssa katsoi hänen päällensä, ja sanoi: katso meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Ja hän katseli heidän päällensä, toivoen heiltä jotakin saavansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Niin Pietari sanoi: hopiaa ja kultaa ei minulla ole; vaan sitä mitä minulla on, annan minä sinulle: Jesuksen Kristuksen Natsarealaisen nimeen nouse ja käy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Ja hän tarttui hänen oikiaan käteensä ja ojensi hänen, ja kohta hänen säärensä ja kantansa vahvistuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Ja hän karkasi ylös, seisoi ja kävi, ja meni heidän kanssansa templiin, käyden ja hypäten ja kiittäen Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Ja kaikki kansa näki hänen käyvän ja kiittävän Jumalaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Ja tunsi hänen siksi, joka almun tähden istui templin Kauniin oven edessä; ja he olivat täynnänsä pelkoa ja suurta hämmästystä siitä, mitä hänelle tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Mutta kuin tämä saattamatoin, joka parannettu oli, piti itsensä Pietarin ja Johanneksen tykö, juoksi kaikki kansa hämmästyksissä heidän tykönsä porstuaan, joka kutsutaan Salomon porstuaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Kuin Pietari sen näki, vastasi hän kansalle: Israelin miehet! mitä te tätä ihmettelette? eli mitä te meidän päällemme katsotte, niinkuin me olisimme meidän omalla voimallamme eli jumalisuudellamme tämän käymään saattaneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Abrahamin ja Isaakin ja Jakobin Jumala, meidän isäimme Jumala, on Poikansa Jesuksen kirkastanut, jonka te annoitte ylön ja kielsitte Pilatuksen edessä, kuin hän tuomitsi, että hän piti päästettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Mutta te kielsitte pyhän ja hurskaan, ja anoitte teillenne murhamiestä annettaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Mutta elämän Pääruhtinaan te tapoitte: sen on Jumala kuolleista herättänyt, jonka todistajat me olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Ja uskon kautta hänen nimensä päälle on hän tässä, jonka te näette ja tunnette, nimensä vahvistanut: ja usko hänen kauttansa antoi tälle terveytensä, kaikkein teidän nähtenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ja nyt rakkaat veljet! minä tiedän, että te sen tyhmyydestä tehneet olette, niinkuin teidän ylimmäisennekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Mutta Jumala, mitä hän kaikkein prophetainsa suun kautta oli ennustanut, että hänen Kristuksensa piti kärsimän, sen hän täytti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 19, 'Niin tehkäät parannus ja palatkaat, että teidän syntinne pyyhittäisiin pois, kuin virvoittamisen ajat tulevat Herran kasvoin edestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 20, 'Ja hän lähettää sen, josta teille ennen saarnattu on, Jesuksen Kristuksen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 21, 'Jonka tosin tulee omistaa taivas, niihin aikoihin asti kuin ne kaikki jälleen asetetaan, mitkä Jumala on puhunut kaikkein pyhäin prophetainsa suun kautta, hamasta maailman alusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 22, 'Sillä Moses on tosin isille sanonut: Herra teidän Jumalanne on teille herättävä Prophetan teidän veljistänne, niinkuin minun: kuulkaat häntä kaikissa, mitä hän teille sanoo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 23, 'Ja pitää tapahtuman, että jokainen sielu, joka ei tätä Prophetaa kuule, pitää hävitettämän pois kansasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 24, 'Ja kaikki prophetat hamasta Samuelista, ja sitte edespäin, niin monta, jotka puhuneet ovat, ovat myös kaikki näitä päiviä ennustaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 25, 'Te olette prophetain ja sen liiton lapset, jonka Jumala meidän isäimme kanssa teki, sanoen Abrahamille: ja sinun siemenessäs pitää kaikki kansat maan päällä siunattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 26, 'Teille on Jumala ensin Poikansa Jesuksen herättänyt ja on hänen lähettänyt teitä siunaamaan, että te kukin teidän pahuudestanne palajaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, 'Mutta kuin he kansalle puhuivat, niin papit ja templin esimies ja Saddukealaiset tulivat sinne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, 'Ja närkästyivät, että he kansaa opettivat ja ilmoittivat Jesuksen kautta ylösnousemisen kuolleista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'Ja heittivät kätensä heidän päällensä ja panivat heidät huomeneksi kiinni; sillä jo oli ehtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'Mutta monta niistä, jotka sanan kuulivat, uskoivat ja miesten luku tuli lähes viisituhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'Mutta toisena päivänä tapahtui, että heidän ylimmäisensä ja vanhimpansa kokoontuivat ja kirjanoppineet Jerusalemissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'Ja Hannas ylimmäinen pappi, ja Kaiphas, ja Johannes, ja Aleksander, ja niin monta kuin ylimmäisten pappein suvusta oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, 'Ja asettivat heidät keskellensä ja kysyivät heiltä: millä voimalla taikka kenenkä nimeen te olette tämän tehneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'Niin Pietari, täynnänsä Pyhää Henkeä, sanoi heille: te kansan ylimmäiset ja Israelin vanhimmat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'Jos me tänäpänä tuomitaan sen hyvän työn edestä sille sairaalle miehelle, jonka kautta hän parannettu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'Niin olkoon teille ja kaikelle Israelin kansalle tiettävä, että Jesuksen Kristuksen Natsarealaisen nimeen, jonka te ristiinnaulitsitte, jonka Jumala kuolleista herätti, sen kautta tämä seisoo teidän edessänne terveenä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'Hän on se kivi, joka teiltä rakentajilta hyljätty on, joka on nurkkakiveksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Ja ei yhdessäkään toisessa ole autuutta; sillä ei myös ole muuta nimeä taivaan alla ihmisille annettu, jossa meidän pitää autuaaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'Mutta kuin he näkivät Pietarin ja Johanneksen puheen rohkeuden, sillä he ymmärsivät heidät oppimattomiksi ja kirjantaitamattomiksi miehiksi, ihmettelivät he ja tunsivat heidät, että he Jesuksen kanssa olleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'Mutta kuin he näkivät sen ihmisen seisovan heidän kanssansa, joka parannettu oli, ei he taitaneet mitään sitä vastaan puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'Mutta he käskivät heitä ulos raadista mennä pois, ja pitivät neuvoa keskenänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, 'Sanoen: mitä me näille miehille teemme? Sillä julkinen merkki on heidän kauttansa tehty, joka kaikille Jerusalemin asuvaisille tiettävä on, ja emme taida kieltää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 17, 'Mutta ettei se enempi kansan keskelle hajoisi, niin haastakaamme heitä kovin, ettei he tästedes yhdellekään ihmiselle tästä nimestä puhuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 18, 'Ja he kutsuivat heidät ja kaiketi kielsivät heitä puhumasta ja opettamasta Jesuksen nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 19, 'Mutta Pietari ja Johannes vastasivat heitä ja sanoivat: tuomitkaat itse, jos se on oikia Jumalan edessä, että me teitä enemmän kuulemme kuin Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 20, 'Sillä emme taida niitä puhumatta olla, joita me nähneet ja kuulleet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 21, 'Mutta he uhkasivat heitä, ja antoivat heidän mennä, ja ei löytäneet mitään, josta he olisivat heitä vaivanneet, kansan tähden; sillä kaikki kiittivät Jumalaa sen edestä mikä tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 22, 'Sillä se ihminen oli ylitse neljänkymmenen ajastajan vanha, jossa tämä parantamisen tunnusmerkki tehty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 23, 'Mutta kuin he päästetyt olivat, tulivat he omainsa tykö ja ilmoittivat, mitä pappein päämiehet ja vanhimmat heille sanoneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 24, 'Kuin he sen kuulivat, korottivat he yksimielisesti äänensä Jumalan tykö ja sanoivat: Herra, sinä olet Jumala, joka taivaan ja maan ja meren, ja kaikki, mitä niissä on, tehnyt olet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 25, 'Joka Davidin sinun palvelias suun kautta puhunut olet: miksi pakanat kiukuitsevat ja kansat turhaa aikovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 26, 'Vaan kuninkaat yhteen menevät ja päämiehet kokoovat heitänsä Herraa vastaan ja hänen Kristustansa vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 27, 'Sillä he ovat tosin kokoontuneet sinun pyhää Poikaas Jesusta vastaan, jonka sinä voitelit, sekä Herodes että Pontius Pilatus pakanain ja Israelin kansan kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 28, 'Tekemään mitä sinun kätes ja neuvos ennen aikonut oli, että tapahtuman pitäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 29, 'Ja nyt Herra, katso heidän uhkaustansa ja anna sinun palveliais kaikella uskalluksella sinun sanaas puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 30, 'Ja ojenna kätes parantamaan, ja että merkit ja ihmeet sinun pyhän Poikas Jesuksen nimen kautta tehtäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 31, 'Ja kuin he rukoilleet olivat, liikkui se paikka, jossa he koossa olivat, ja he täytettiin kaikki Pyhällä Hengellä ja puhuivat Jumalan sanaa uskalluksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 32, 'Ja niiden paljoudessa, jotka uskoivat, oli yksi sydän ja yksi sielu, ei myös kenkään heistä sanonut mitään omaksensa, mitä hänellä oli, vaan kaikki olivat heillä yhteiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 33, 'Ja apostolit todistivat suurella voimalla Herran Jesuksen ylösnousemisesta, ja suuri armo oli kaikkein heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 34, 'Ja ei myös ollut yhtään tarvitsevaa heissä; sillä niin monta, joilla pellot eli huoneet olivat, ne myivät ja toivat myytyin hinnan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 35, 'Ja panivat apostolien jalkain eteen: ja jokaiselle jaettiin niinkuin kukin tarvitsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 36, 'Mutta Joses, joka liialta nimeltä apostoleilta kutsutaan Barnabas (se on niin paljo sanottu kuin lohdutuksen poika) Leviläinen, Kypristä sukuisin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 37, 'Hänellä oli pelto, sen hän myi, ja toi hinnan ja pani apostolitten jalkain eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 1, 'Mutta mies, Ananias nimeltä, emäntänsä Saphiran kanssa myi tavaransa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 2, 'Ja kätki jotain hinnasta emäntänsä tieten, ja toi osan edes ja pani apostolitten jalkain eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 3, 'Niin Pietari sanoi: Ananias, miksi saatana täytti sinun sydämes Pyhän Hengen edessä valhettelemaan, että jotakin pellon hinnasta kätkit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 4, 'Etkös olisi saanut sitä pitää, kuin se sinulla oli, ja se myytykin oli sinun hallussas? miksis senkaltaista olet sydämees päästänyt? Et sinä ole ihmisten, vaan Jumalan edessä valehdellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 5, 'Kuin Ananias nämät sanat kuuli, lankesi hän maahan ja antoi henkensä. Ja suuri pelko tuli kaikkein niiden päälle, jotka tämän kuulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 6, 'Niin nuoret miehet nousivat ja korjasivat hänen, veivät pois ja hautasivat hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 7, 'Mutta tapahtui liki kolmen hetken perästä, että myös hänen emäntänsä tuli sisälle eikä tietänyt, mitä tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 8, 'Niin Pietari vastasi häntä: sanos minulle: oletteko sen pellon siihen hintaan myyneet? mutta hän sanoi: olemme niinkin siihen hintaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 9, 'Sanoi Pietari hänelle: miksi te olette mielistyneet keskenänne Herran Henkeä kiusaamaan? Katso, niiden jalat, jotka sinun miehes hautasivat, ovat oven edessä ja vievät pois sinun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 10, 'Ja hän kohta lankesi maahan hänen jalkainsa eteen ja antoi henkensä. Niin nuoret miehet tulivat sisälle ja löysivät hänen kuolleena, ja he veivät hänen ulos ja hautasivat miehensä tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 11, 'Ja suuri pelko tuli koko seurakunnalle ja kaikille niille, jotka tämän kuulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 12, 'Ja apostolitten kätten kautta tehtiin monta merkkiä ja ihmettä kansan seassa. Ja olivat kaikki yksimielisesti Salomon esihuoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 13, 'Mutta ei niistä muista uskaltanut yksikään itsiänsä antaa heidän sekaansa; vaan kansa piti paljon heistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 14, 'Ja joukko paljon eneni miehistä ja vaimoista, jotka Herran päälle uskoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 15, 'Niin että he kantoivat sairaita kaduille ja panivat niitä vuoteille ja paareille, että Pietarin tullessa ainoasti hänen varjonsa jonkun heistä olis varjonnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 16, 'Ja tuli myös suuri joukko kokoon lähimmäisistä kaupungeista Jerusalemiin, ja toviat sairaita ja saastaisilta hengiltä vaivatuita, jotka kaikki parannettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 17, 'Niin nousi ylimmäinen pappi, ja kaikki, jotka hänen kanssansa olivat, Saddukealaisten lahko, ja olivat täynnänsä kiivautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 18, 'Ja paiskasivat kätensä apostolitten päälle ja panivat heidät yhteiseen vankihuoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 19, 'Mutta Herran enkeli avasi yöllä tornin oven, ja vei heidät sieltä ulos ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 20, 'Menkäät, seisokaat ja puhukaat templissä kansalle kaikki tämän elämän sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 21, 'Mutta kuin he sen kuulivat, menivät he varhain aamulla templiin ja opettivat. Niin ylimmäinen pappi tuli, ja ne, jotka hänen kanssansa olivat, kutsuivat raadin kokoon ja kaikki Israelin lasten vanhimmat, ja lähettivät vankihuoneesen heitä noutamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 22, 'Kuin palveliat menivät, eikä heitä tornista löytäneet, niin he palasivat ja ilmoittivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 23, 'Sanoen: tornin me tosin löysimme kyllä visusti suljetuksi ja vartiat ulkona oven edessä seisovan; mutta kuin me sen avasimme, emme ketään sieltä löytäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 24, 'Kuin ylimmäinen pappi ja templin esimies ja pappein päämiehet nämät kuulivat, epäilivät he heistä, miksi se viimeinkin tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 25, 'Niin tuli yksi ja ilmoitti heille, sanoen: katso, ne miehet, jotka te torniin panitte, ovat templissa ja seisovat opettamassa kansaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 26, 'Niin esimies meni palvelijoinensa ja toi heidät suosiolla sieltä (sillä he pelkäsivät kansan heitä kivittävän).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 27, 'Ja kuin he toivat heidät, asettivat he heidät raadin eteen. Ja ylimmäinen pappi kysyi heiltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 28, 'Sanoen: emmekö ole kovasti teitä kieltäneet puhumasta kansalle tähän nimeen? Ja katso, te olette Jerusalemin täyttäneet teidän opetuksellanne, ja tahdotte tämän ihmisen veren vetää meidän päällemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 29, 'Mutta Pietari ja muut apostolit vastasivat ja sanoivat: enempi tulee kuulla Jumalaa kuin Ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 30, 'Meidän isäimme Jumala herätti Jesuksen, jonka te tapoitte ja ripustitte puuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 31, 'Sen on Jumala korottanut oikialle kädellensä Päämieheksi ja Vapahtajaksi, antamaan Israelille parannusta ja syntein anteeksi antamusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 32, 'Ja me olemme näiden sanain todistajat, ja myös Pyhä Henki, jonka Jumala on niille antanut, jotka häntä kuulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 33, 'Mutta kuin he nämät kuulivat, kävi se lävitse heidän sydämensä, ja he pitivät neuvoa tappaaksensa heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 34, 'Niin nousi raadista yksi Pharisealainen, nimeltä Gamaliel, lainopettaja, josta kaikki kansa paljon piti: se käsi apostoleita pikimältänsä viedä ulos,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 35, 'Ja sanoi heille: Israelin miehet! kavahtakaat itseänne, mitä te mielitte tehdä näille miehille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 36, 'Sillä ennen näitä päiviä nousi Teudas ja sanoi itsensä joksikin, niin hänen tykönsä tuli lähes neljäsataa miestä: joka sitte tapettiin ja kaikki, jotka häneen mielistyivät, ne hajoitettiin ja hävitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 37, 'Tämän jälkeen nousi Juudas Galileasta veronlaskemisen päivinä ja käänsi paljon kansaa jälkeensä; hän myös hukkui ja kaikki, jotka häneen mielistyivät, hajoitettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 38, 'Ja nyt sanon minä teille: lakatkaat näistä miehistä ja sallikaat heidän olla; sillä jos tämä neuvo eli teko on ihmisistä, niin se tyhjään raukee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 39, 'Vaan jos se on Jumalalta, niin ette voi sitä tyhjäksi tehdä, ettette myös löydettäisi sotineen jumalaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 40, 'Niin kaikki mielistyivät hänen neuvoonsa; ja kuin he apostolit sisälle kutsuivat, niin he hosuivat heitä ja kielsivät heitä Jesuksen nimeen puhumasta, ja päästivät heidät menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 41, 'Niin he menivät pois raadin edestä, iloiten että he olivat mahdolliset pilkkaa kärsimään hänen nimensä tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 42, 'Ja ei lakanneet joka päivä templissä ja joka huoneessa opettamasta ja saarnaamasta evankeliumia Jesuksesta Kristuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 1, 'Mutta niinä päivinä, koska opetuslasten luku eneni, napisivat Grekiläiset Hebrealaisia vastaan, että heidän leskensä katsottiin ylön jokapäiväisessä palveluksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 2, 'Niin ne kaksi toistakymmentä kutsuivat kokoon opetuslasten joukon, ja sanoivat: ei se ole kohtuullinen, että me annamme ylön Jumalan sanan, ja pöytäin edessä palvelemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 3, 'Sentähden, rakkaat veljet, valitkaat teistä seitsemän miestä joista hyvä todistus on, jotka ovat Pyhää Henkeä ja viisautta täynnänsä, joiden haltuun me tämän viran annamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 4, 'Mutta me tahdomme rukouksessa ja sanan palveluksessa pysyväiset olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 5, 'Ja se puhe kelpasi kaikelle joukolle, ja he valitsivat Stephanin, miehen täynnä uskoa ja Pyhää Henkeä, ja Philippuksen, ja Prokoron, ja Nikanorin, ja Timonin, ja Parmenaan, ja Nikolaon, uuden Juudalaisen Antiokiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 6, 'Nämät he asettivat apostoleitten eteen: ja rukoilivat, ja panivat kätensä heidän päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 7, 'Ja Jumalan sana kasvoi ja opetuslasten luku tuli sangen suureksi Jerusalemissa; ja suuri joukko pappeja oli myös uskolle kuuliainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 8, 'Mutta Stephanus, joka oli uskoa täynnänsä ja väkevyyttä, teki ihmeitä ja suuria tunnustähtiä kansan seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 9, 'Niin nousivat muutamat Libertinein synagogasta, ja Kyreniläisten, ja Aleksandrialaisten, ja jotka Kilikiasta ja Asiasta olivat, ja riitelivät Stephanin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 10, 'Ja eivät voineet sitä viisautta vastaan olla ja sitä Henkeä, jonka kautta hän puhui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 11, 'Niin he sääsivät miehiä, jotka sanoivat: me olemme hänen kuulleet puhuvan pilkkasanoja Mosesta ja Jumalaa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 12, 'Niin he yllyttivät kansan ja vanhimmat ja kirjanoppineet, ja menivät ja ottivat hänen kiinni, ja veivät hänen raadin eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 13, 'Ja asettivat väärät todistajat sanomaan: ei tämä mies lakkaa puhumasta pilkkasanoja tätä pyhää siaa ja lakia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 14, 'Sillä me olemme kuulleet hänen sanovan: Jesus Natsarealainen hävittää tämän sian, ja muuttaa säädyt, jotka Moses meille antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 15, 'Ja kaikki ne, jotka raadissa istuivat, katsoivat hänen päällensä ja näkivät hänen kasvonsa niinkuin enkelin kasvot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 1, 'Niin ylimmäinen pappi sanoi: lienevätkö nämät näin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 2, 'Vaan hän sanoi: miehet, rakkaat veljet ja isät, kuulkaat: kunnian Jumala ilmestyi Abrahamille meidän isällemme, kuin hän oli Mesopotamiassa, ennenkuin hän Haranissa asui,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 3, 'Ja sanoi hänelle: lähde sinun maaltas ja suvustas, ja tule siihen maahan, jonka minä sinulle osoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 4, 'Silloin hän läksi Kaldeasta, ja asui Haranissa. Ja kuin hänen isänsä kuollut oli, toi hän hänen sieltä tähän maahan, jossa te nyt asutte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 5, 'Ja ei antanut hänelle siinä perintöä, ei jalankaan leveyttä; ja hän lupasi hänelle sen antaa asuaksensa, ja hänen siemenellensä hänen jälkeensä, kuin ei hänellä vielä lasta ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 6, 'Ja Jumala puhui hänelle näin: sinun siemenes pitää oleman muukalainen vieraalla maalla, ja heidän pitää sen orjaksi tekemän, ja pahasti sen kanssa menemän neljäsataa ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 7, 'Ja sen kansan, jota he palvelevat, tahdon minä tuomita, sanoi Jumala, ja sitte pitää heidän lähtemän ja minua tässä siassa palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 8, 'Ja hän antoi hänelle ympärileikkauksen liiton; ja niin hän siitti Isaakin, ja ympärileikkasi hänen kahdeksantena päivänä. Ja Isaak siitti Jakobin, ja Jakob kaksitoistakymmentä patriarkkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 9, 'Ja ne patriarkat myivät kateudesta Josefin Egyptiin. Ja Jumala oli hänen kanssansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 10, 'Ja pelasti hänen kaikista tuskistansa, ja antoi hänelle armon ja viisauden Pharaon, Egyptin kuninkaan, kasvoin edessä, ja hän pani hänen Egyptin valtamieheksi ja kaiken huoneensa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 11, 'Mutta nälkä tuli kaikkeen Egyptiin ja Kanaanin maahan, ja suuri tuska; ja ei meidän isämme löytäneet ravintoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 12, 'Mutta kuin Jakob kuuli Egyptissä jyviä olevan, lähetti hän sinne meidän isämme ensimmäisen kerran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 13, 'Ja kuin hän toistamiseen heidät lähetti, tunnettiin Joseph veljiltänsä; ja Josephin suku tuli Pharaolle tiettäväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 14, 'Niin Joseph lähetti ja antoi tuoda isänsä Jakobin ja kaiken hänen sukunsa, viisi sielua kahdeksattakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 15, 'Ja Jakob meni alas Egyptiin, ja hän kuoli, niin myös meidän isämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 16, 'Ja he vietiin Sikemiin ja pantiin siihen hautaan, jonka Abraham oli Hemorin lapsilta rahalla ostanut Sikemissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 17, 'Mutta kuin lupauksen aika lähestyi, josta Jumala oli Abrahamille vannonut, kasvoi ja eneni kansa Egyptissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 18, 'Siihenasti kuin toinen kuningas tuli, joka ei Josephista mitään tietänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 19, 'Tämä meidän sukuamme kavalasti juonitteli, ja meni pahasti meidän isäimme kanssa, niin että heidän piti nuoret lapsensa heittämän pois, ettei he olisi saaneet elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 20, 'Siihen aikaan syntyi Moses, ja hän oli Jumalalle otollinen, ja elätettiin kolme kuukautta isänsä huoneessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 21, 'Mutta kuin hän heitetty oli ulos, otti Pharaon tytär hänen ja kasvatti itsellensä pojaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 22, 'Ja Moses opetettiin kaikessa Egyptiläisten viisaudessa, ja oli voimallinen sanoissa ja töissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 23, 'Mutta kuin hän oli neljänkymmenen ajastajan vanha, joukahtui hänen sydämeensä mennä katsomaan veljiänsä Israelin lapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 24, 'Ja kuin hän näki yhdelle vääryyttä tehtävän, autti hän häntä ja kosti hänen puolestansa, joka vääryyttä kärsi, ja löi Egyptin miehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 25, 'Mutta hän luuli veljiensä sen ymmärtävän, että Jumala hänen kätensä kautta oli heille vapauden antava; vaan eivät he ymmärtäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 26, 'Ja hän tuli toisena päivänä heidän tykönsä, jotka keskenänsä riitelivät, ja sovitti heitä, sanoen: rakkaat miehet, te olette veljekset: miksi te toinen toisellenne vääryyttä teette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 27, 'Mutta se, joka lähimmäisellensä vääryyttä teki, lykkäsi häntä, sanoen: kuka sinun on pannut päämieheksi ja tuomariksi meidän ylitsemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 28, 'Vai tahdotkos sinä minua niin tappaa, kuin sinä Egyptiläisen eilen tapoit?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 29, 'Niin Moses pakeni tämän puheen tähden, ja oli Madiamin maakunnassa muukalainen, jossa hän kaksi poikaa siitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 30, 'Ja neljänkymmenen ajastajan perästä ilmestyi hänelle Herran enkeli korvessa, Sinain vuorella, pensaan tulen liekissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 31, 'Mutta kuin Moses sen näki, ihmetteli hän sitä näkyä, ja kuin hän meni lähes katsomaan, niin tapahtui Herran ääni hänelle:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 32, 'Minä olen sinun isäis Jumala, Abrahamin Jumala, ja Isaakin Jumala, ja Jakobin Jumala. Niin Moses vapisi eikä tohtinut sinne katsoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 33, 'Ja Herra sanoi hänelle: riisu kenkäs jaloistas; sillä sia, jossas seisot, on pyhä maa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 34, 'Minä olen nähden nähnyt kansani tuskan Egyptissä, ja olen heidän huokauksensa kuullut, ja tulin alas heitä ottamaan ulos: tule siis nyt tänne, minä lähetän sinun Egyptiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 35, 'Tämän Moseksen, jota he kielsivät, sanoen: kuka sinun on pannut päämieheksi ja tuomariksi? tämän on Jumala lähettänyt päämieheksi ja vapahtajaksi, enkelin käden kautta, joka hänelle pensaassa ilmestyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 36, 'Tämä johdatti heitä ulos, ja teki ihmeitä ja merkkejä Egyptin maassa ja Punaisessa meressä ja korvessa, neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 37, 'Tämä on se Moses, joka sanoi Israelin lapsille: Herra teidän Jumalanne herättää teille teidän veljistänne yhden Prophetan, niinkuin minun, jota teidän pitää kuuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 38, 'Tämä oli seurakunnassa enkelin kanssa korvessa, joka puhui hänen kanssansa Sinain vuorella, ja meidän isäimme kanssa. Tämä sai elämän puheen meille antaaksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 39, 'Jota ei meidän isämme totelleet, vaan sysäsivät pois sen tyköänsä, ja palasivat sydämessänsä Egyptiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 40, 'Sanoen Aaronille: tee meille jumalia, jotka meidän edellämme kävisivät; sillä emme tiedä, mitä Mosekselle, joka meidän Egyptin maasta toi ulos, on tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 41, 'Ja niinä päivinä tekivät he vasikan, ja uhrasivat epäjumalille uhria, ja riemuitsivat kättensä töistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 42, 'Niin Jumala käänsi itsensä, ja antoi ylön heidät palvelemaan taivaan sotajoukkoa, niinkuin prophetain Raamatussa on kirjoitettu: oletteko te Israelin huoneesta minulle teurasuhria ja ruokauhria tehneet neljänäkymmenenä ajastaikana korvessa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 43, 'Ja te kannoitte Molokin majaa ja teidän jumalanne Remphan tähteä, joita kuvia te teitte kumartaaksenne niitä, ja minä tahdon teidät viedä pois edemmä Babelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 44, 'Meidän isillä oli todistuksen maja korvessa, niinkuin se oli säätänyt, joka Moseksen kanssa puhui, että hänen piti sen tekemän sen esikuvan perään, jonka hän nähnyt oli;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 45, 'Jonka myös meidän isämme vastaan ottivat, ja veivät Josuan kanssa siihen maahan, jossa pakanat asuivat, jotka Jumala hävitti meidän isäimme kasvoin edestä, hamaan Davidin aikaan asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 46, 'Joka löysi armon Jumalan tykönä, ja anoi, että hän olis majan löytänyt Jakobin Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 47, 'Mutta Salomo rakensi hänelle huoneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 48, 'Vaan se kaikkein Ylimmäinen ei asu käsillä tehdyissä templeissä, niinkuin propheta sanoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 49, 'Taivas on minun istuimeni ja maa jalkaini astinlauta. Minkä huoneen te siis tahdotte minulle rakentaa, sanoo Herra, eli kuka on minun leposiani?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 50, 'Eikö minun käteni ole kaikkia näitä tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 51, 'Te niskurit ja ympärileikkaamattomat sydämestä ja korvista! te olette aina Pyhää Henkeä vastaan, niinkuin teidän isänne, niin myös tekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 52, 'Ketä prophetaista ei teidän isänne vainonneet? Ja he tappoivat ne, jotka vanhurskaan tulemista ennustivat, jonka pettäjät ja murhaajat te nyt olitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 53, 'Jotka saitte lain enkelien asetuksen kautta, jota ette pitäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 54, 'Mutta kuin he nämät kuulivat, kävi se läpi heidän sydämensä, ja kiristelivät hampaitansa hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 55, 'Mutta että hän oli täynnä Pyhää Henkeä, katsahti hän ylös taivaasen, näki Jumalan kunnian ja Jesuksen seisovan Jumalan oikialla kädellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 56, 'Ja sanoi: katso, minä näen taivaat avoinna, ja Ihmisen Pojan seisovan Jumalan oikialla kädellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 57, 'Niin he huusivat suurella äänellä, ja tukitsivat korviansa, ja karkasivat kaikki yksimielisesti hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 58, 'Ja ajoivat hänen ulos kaupungista, ja kivittivät. Ja todistajat panivat vaatteensa nuorukaisen jalkain juureen, joka kutsuttiin Saulus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 59, 'Ja he kivittivät Stephanin, joka rukoili ja sanoi: Herra Jesus, ota minun henkeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 60, 'Niin hän pani polvillensa, ja huusi suurella äänellä: Herra, älä lue heille tätä syntiä. Ja kuin hän tämän sanonut oli, niin hän nukkui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 1, 'Ja Saulus oli myös mielistynyt hänen kuolemaansa. Niin sinä päivänä nousi suuri vaino seurakuntaa vastaan, joka oli Jerusalemissa; ja hajosivat kaikki ympäri Juudan ja Samarian maakuntaa, paitsi apostoleita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 2, 'Ja muutamat Jumalaa pelkääväiset miehet korjasivat Stephanin, ja valittivat häntä suuresti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 3, 'Mutta Saulus raateli seurakuntaa ja kävi huone huoneelta, otti miehet ja vaimot ja panetti vankiuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 4, 'Ja ne hajonneet vaelsivat ympärinsä ja saarnasivat Jumalan sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 5, 'Niin Philippus tuli Samarian kaupunkiin ja saarnasi heille Kristuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 6, 'Mutta kansa otti vaarin yksimielisesti ja visusti Philippuksen sanoista, kuullen ja nähden ne merkit, jotka hän teki:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 7, 'Sillä rumat henget läksivät ulos monesta, huutain suurella äänellä ja monta halvattua ja saattamatointa parani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 8, 'Ja suuri ilo tuli siihen kaupunkiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 9, 'Mutta siellä oli mies, Simon nimeltä, joka siinä kaupungissa ennen noituuden virkaa piti ja oli Samarian kansan villinnyt, sanoen itsensä olevan jonkun suuren,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 10, 'Jota kaikki sekä pienet että suuret kuulivat, sanoen: tämä on Jumalan voima, joka suuri on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 11, 'Mutta he kuultelivat häntä mielellänsä, että hän kauvan aikaa oli heitä noituudellansa villinnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 12, 'Mutta kuin he uskoivat Philippuksen, joka saarnasi Jumalan valtakunnasta ja Jesuksen Kristuksen nimestä, niin he kastettiin sekä miehet että vaimot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 13, 'Niin Simon myös itse uskoi, ja kuin hän kastettu oli, viipyi hän Philippuksen tykönä. Ja kuin hän näki ne merkit ja suuret voimalliset työt tapahtuvan, niin hän hämmästyi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 14, 'Mutta kuin apostolit, jotka Jerusalemissa olivat, kuulivat Samarian Jumalan sanan ottaneen vastaan, lähettivät he heidän tykönsä Pietarin ja Johanneksen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 15, 'Jotka, kuin he sinne tulivat alas, rukoilivat niiden edestä, että he olisivat saaneet Pyhän Hengen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 16, '(Sillä ei hän ollut vielä yhdenkään niiden päälle laskettu alas, vaan olivat ainoastaan Herran Jesuksen nimeen kastetut.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 17, 'Niin he panivat kätensä heidän päällensä, ja he saivat Pyhän Hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 18, 'Mutta kuin Simon näki, että apostolien kätten päälle-panemisen kautta Pyhä Henki annettiin, taritsi hän heille rahaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 19, 'Sanoen: antakaat minullekin se voima, että kenenkä päälle minä käteni panen, se sais Pyhän Hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 20, 'Vaan Pietari sanoi hänelle: sinun rahas olkoon sinun kanssas kadotuksessa, että Jumalan lahjan luulet rahoilla ostettavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 21, 'Ei sinulla ole osaa eikä arpaa tässä sanassa; sillä ei sinun sydämes ole oikia Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 22, 'Sentähden tee parannus sinun pahuudestas, ja rukoile Jumalaa, että sydämes ajatukset sinulle anteeksi annettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 23, 'Sillä minä näen sinun olevan katkerassa sapessa ja vääryyden solmussa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 24, 'Niin Simon vastasi ja sanoi: rukoilkaat te Herraa minun edestäni, ettei mitään näistä, mitä te sanoitte, minun päälleni tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 25, 'Mutta kuin he olivat todistaneet ja puhuneet Herran sanan, palasivat he Jerusalemiin, ja saarnasivat evankeliumia monessa Samarian kylässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 26, 'Mutta Herran enkeli puhui Philippukselle ja sanoi: nouse ja mene lounaaseen päin, sitä tietä, joka Jerusalemista menee alas Gatsaan, joka kylmillä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 27, 'Niin hän nousi ja meni. Ja katso, yksi Etiopian mies, Etiopian kuningattaren Kandasen voimallinen kamaripalvelia, joka oli pantu kaiken hänen tavaransa päälle, se oli tullut Jerusalemiin rukoilemaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 28, 'Ja palasi sieltä, istuen vaunuissansa, ja luki Jesaias prophetaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 29, 'Niin Henki sanoi Philippukselle: käy ja mene lähemmä tätä vaunua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 30, 'Niin Philippus juoksi lähemmä, ja kuuli hänen lukevan Jesaias prophetaa, ja sanoi: ymmärrätkös, mitäs luet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 31, 'Mutta hän sanoi: kuinka minä taidan ymmärtää, ellei joku minua johdata? Ja hän rukoili Philippusta, että hän tulis ja istuis hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 32, 'Mutta se, mitä hän Raamatusta luki, oli tämä: hän on niinkuin lammas teuraaksi talutettu: ja niinkuin karitsa keritsiänsä edessä on ääneti, niin ei hänkään avannut suutansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 33, 'Hänen nöyryydessänsä on hänen tuomionsa otettu pois, mutta kuka taitaa sanoa ulos hänen elämänsä pituuden? sillä hänen elämänsä otetaan pois maasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 34, 'Niin kamaripalvelija vastasi Philippusta: minä rukoilen sinua, sanos: kenestä propheta näitä puhuu? itsestäänkö eli jostakin toisesta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 35, 'Niin Philippus avasi suunsa ja rupesi tästä kirjoituksesta hänelle saarnaamaan evankeliumia Jesuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 36, 'Ja kuin he tiellä vaelsivat, tulivat he veden tykö, ja kamaripalvelia sanoi: katso, tässä on vesi: mikä estää minua kastamasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 37, 'Mutta Philippus sanoi: jos sinä kaikesta sydämestä uskot, niin tapahtukoon. Hän vastasi ja sanoi: minä uskon Jesuksen Kristuksen Jumalan Pojaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 38, 'Niin hän käski seisahtaa vaunun; ja he astuivat molemmat veteen, Philippus ja kamaripalvelia, ja hän kasti hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 39, 'Mutta kuin he vedestä astuivat ylös, tempasi Herran Henki Philippuksen, ja ei kamaripalvelia häntä enään nähnyt, vaan meni iloiten tietänsä myöten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 40, 'Mutta Philippus löydettiin Atsotissa, ja vaelsi ympäri ja saarnasi joka kaupungissa evankeliumia, siihenasti kuin hän tuli Kesareaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 1, 'Mutta Saulus puskui vielä uhkauksia ja murhaa Herran opetuslapsia vastaan ja meni ylimmäisen papin tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 2, 'Ja anoi häneltä kirjaa Damaskuun synagogain tykö, että kutka ikänä hän sen tien miehistä eli vaimoista löytäis, ne hän olis vienyt sidottuna Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 3, 'Mutta kuin hän matkusti, tapahtui, että hän Damaskua lähestyi, ja äkisti leimahti valkeus taivaasta ympäri häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 4, 'Ja hän lankesi maahan ja kuuli äänen hänelle sanovan: Saul, Saul, miksi vainoot minua?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 5, 'Mutta hän sanoi: kuka sinä olet, Herra? Ja Herra sanoi: minä olen Jesus, jota sinä vainoot: työläs on sinun potkia tutkainta vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 6, 'Niin hän vapisi, hämmästyi ja sanoi: Herra, mitäs minua tahdot tekemään? Ja Herra sanoi hänelle: nouse ja mene kaupunkiin; siellä sinulle sanotaan, mitä sinun pitää tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 7, 'Mutta ne miehet, jotka hänen seurassansa olivat, seisoivat hämmästyksissä; he kuulivat tosin äänen, mutta ei he ketään nähneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 8, 'Niin Saulus nousi maasta ja ei nähnyt ketään avoimilla silmillä; mutta he taluttivat häntä kädestä ja veivät Damaskuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 9, 'Ja hän oli kolme päivää näkemättä ja ei syönyt eikä juonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 10, 'Niin yksi opetuslapsi oli Damaskussa, Ananias nimeltä, jolle Herra sanoi näyssä: Ananias! Hän sanoi: Herra, tässä minä olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 11, 'Herra sanoi hänelle: nouse ja mene sille kadulle, joka Oikiaksi kutsutaan, ja kysy Juudan huoneessa sitä, joka Saulus Tarsilaiseksi kutsutaan; sillä katso, hän rukoilee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 12, 'Ja hän näki näyssä yhden miehen, nimeltä Ananias, tulevan sisälle ja panevan kätensä hänen päällensä, että hän sais näkönsä jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 13, 'Niin Ananias vastasi: Herra, minä olen kuullut monelta tästä miehestä, kuinka paljon pahaa hän sinun pyhilles on tehnyt Jerusalemissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 14, 'Ja hänellä on nytkin valta ylimmäisiltä papeilta täällä kiinni sitoa kaikki ne, jotka sinun nimeäs rukoilevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 15, 'Niin sanoi Herra hänelle: mene! sillä hän on minulle valittu ase, kantamaan minun nimeäni pakanain, ja kuningasten, ja Israelin lasten eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 16, 'Sillä minä tahdon hänelle näyttää, kuinka paljon hänen pitää kärsimän minun nimeni tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 17, 'Niin Ananias meni sinne ja tuli huoneeseen sisälle ja pani kätensä hänen päällensä, ja sanoi: rakas veljeni Saul! se Herra lähetti minun, (Jesus, joka sinulle ilmestyi tiellä, jotas vaelsit,) että sinä saisit näkös jälleen, ja Pyhällä Hengellä täytettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 18, 'Ja hänen silmistänsä putosivat kohta niinkuin suomukset, ja hän sai sillä hetkellä näkönsä jällensä, nousi ja kastettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 19, 'Ja kuin hän otti ruokaa, niin hän vahvistui. Ja Saulus oli muutamat päivät opetuslasten kanssa, jotka olivat Damaskussa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 20, 'Ja saarnasi kohta synagogassa Kristuksesta, että hän on Jumalan Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 21, 'Niin kaikki, jotka sen kuulivat, hämmästyivät ja sanoivat: eikö tämä ole se, joka kaikkia niitä hävitti Jerusalemissa, jotka sitä nimeä rukoilivat, ja tuli myös tänne sitä varten, että hän ne sidottuna veis ylimmäisille papeille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 22, 'Mutta Saulus tuli aina jalommaksi ja ajoi Juudalaisia takaperin, jotka Damaskussa olivat, täydellisesti vahvistain, että tämä on Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 23, 'Ja monen päivän perästä pitivät Juudalaiset neuvoa keskenänsä tappaaksensa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 24, 'Mutta Saulukselle ilmoitettiin heidän väijymisensä. Ja he vartioitsivat portissa yötä ja päivää tappaaksensa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 25, 'Niin opetuslapset ottivat hänen yöllä, päästivät alas ylitse muurin, ja laskivat korissa maahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 26, 'Mutta kuin Saulus tuli Jerusalemiin, tahtoi hän itsiänsä antaa opetuslasten sekaan, mutta he pelkäsivät kaikki häntä, eikä uskoneet häntä opetuslapseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 27, 'Vaan Barnabas otti hänen ja vei apostolien tykö, ja jutteli heille, kuinka hän tiellä Herran nähnyt oli, ja että hän oli puhunut hänen kanssansa, ja kuinka hän oli rohkiasti Damaskussa Jesuksen nimestä puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 28, 'Ja niin hän oli heidän kanssansa Jerusalemissa, kävi sisälle ja ulos, ja saarnasi pelkäämättä Herran Jesuksen nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 29, 'Hän puhui myös ja kamppaili Grekiläisiä vastaan; mutta ne pyysivät häntä tappaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 30, 'Kuin veljet sen ymmärsivät, niin he veivät hänen Kesareaan ja lähettivät Tarsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 31, 'Ja niin seurakunnilla oli rauha kaikessa Juudeassa, ja Galileassa, ja Samariassa, ja enenivät vaeltain Herran pelvossa, ja täytettiin Pyhän Hengen lohdutuksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 32, 'Niin tapahtui, kuin Pietari vaelsi joka paikassa, että hän myös tuli pyhäin tykö, jotka Lyddassa asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 33, 'Niin hän löysi siellä yhden miehen, Eneas nimeltä, joka jo kahdeksan ajastaikaa oli vuoteessa halvattuna maannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 34, 'Ja Pietari sanoi hänelle: Eneas, Jesus Kristus sinun paratkoon! nouse ja tee itse vuotees; ja hän kohta nousi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 35, 'Ja kaikki Lyddan ja Saronin asuvaiset näkivät hänen, jotka tulivat käännetyksi Herran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 36, 'Mutta Jopessa oli yksi opetuspiika, nimeltä Tabita, joka tulkiten on niin paljon sanottu kuin: metsävuohi (a); tämä oli täynnänsä hyviä töitä ja almua, joita hän teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 37, 'Niin tapahtui niinä päivinä, että se sairasti ja kuoli; jonka he pesivät ja panivat saliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 38, 'Ja että Lydda oli läsnä Joppea, niin opetuslapset, kuin he kuulivat Pietarin siellä olevan, lähettivät hänen tykönsä kaksi miestä rukoilemaan, ettei hän viivyttelisi heidän tykönsä tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 39, 'Niin Pietari nousi ja tuli heidän kanssansa; ja kuin hän sinne tuli, veivät he hänen saliin. Ja hänen ympärillänsä seisoivat kaikki lesket, jotka itkivät ja osoittivat hänelle niitä hameita ja vaatteita, joita Dorkas heille tehnyt oli, ollessansa heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 40, 'Mutta kuin Pietari oli heidät kaikki ajanut ulos, laski hän polvillensa ja rukoili, ja käänsi itsensä ruumiin puoleen, ja sanoi: Tabita, nouse ylös! niin se avasi silmänsä; ja kuin hän Pietarin näki, nousi hän istualle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 41, 'Ja hän antoi hänelle kättä ja ojensi hänen, ja kutsui pyhät ja lesket, ja antoi hänen heille elävänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 42, 'Ja se tuli kaikelle Jopelle tiettäväksi; ja moni uskoi Herran päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 43, 'Ja tapahtui, että hän viipyi Jopessa kauvan aikaa Simon parkkarin tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 1, 'Niin oli Kesareassa mies, nimeltä Kornelius, sadanpäämies, Italian joukosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 2, 'Jumalinen ja Jumalaa pelkääväinen kaiken huoneensa kanssa, joka jakoi paljon almua kansalle, ja rukoili alati Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 3, 'Hän näki julkisesti näyssä, liki yhdeksättä hetkeä päivästä, Jumalan enkelin tulevan tykönsä ja sanovan hänelle: Kornelius!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 4, 'Ja hän katseli hänen päällensä, peljästyi ja sanoi: Herra, mikä on? Hän sanoi hänelle: sinun rukoukses ja almus ovat tulleet muistoon Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 5, 'Ja nyt lähetä miehiä Joppeen, ja anna noutaa Simonin, jota Pietariksi kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 6, 'Hän pitää majaa Simon parkkarilla, jonka huone on meren tykönä; hän sanoo sinulle, mitä sinun pitää tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 7, 'Ja kuin enkeli, joka Korneliusta puhutteli, meni pois, kutsui hän kaksi palveliaansa ja yhden Jumalaa pelkääväisen sotamiehen niistä, jotka hänen tykönänsä oleskelivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 8, 'Ja hän jutteli kaikki nämät niille, ja lähetti ne Joppeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 9, 'Toisena päivänä, kuin he matkassa olivat ja kaupunkia lähestyivät, meni Pietari ylös katon päälle rukoilemaan, liki kuudetta hetkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 10, 'Ja kuin hän isosi, tahtoi hän suurustaa. Mutta kuin he hänelle valmistivat, tuli hän horroksiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 11, 'Ja näki taivaan auki, ja tulevan alas tykönsä yhden astian, niinkuin suuren liinaisen, neljältä kulmalta sidotun, joka laskettiin alas taivaasta maan päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 12, 'Jossa oli kaikkinaisia nelijalkaisia maan eläimiä ja metsillisiä, ja matelevaisia, ja taivaan lintuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 13, 'Ja ääni tuli hänelle: Pietari, nouse, tapa ja syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 14, 'Pietari sanoi: en suinkaan, Herra; sillä en ole minä ikänä syönyt mitään yhteistä eli saastaista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 15, 'Ja ääni sanoi taas toisen kerran hänelle: mitä Jumala on puhdistanut, älä sitä sinä sano yhteiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 16, 'Ja se tapahtui kolme kertaa ja astia otettiin jälleen ylös taivaaseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 17, 'Ja kuin Pietari itsellänsä epäili, mikä näky se olis, jonka hän näki, niin katso, miehet, jotka lähetetyt olivat Korneliukselta, kyselivät Simonin huonetta ja seisoivat oven edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 18, 'Ja kutsuivat yhden ulos ja kysyivät, pitikö Simon, joka liialta nimeltä Pietariksi kutsutaan, siellä majaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 19, 'Mutta kuin Pietari sitä näkyä ajatteli, sanoi Henki hänelle: katso, kolme miestä etsivät sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 20, 'Nouse siis, astu alas ja mene ilman epäilemättä heidän kanssansa; sillä minä lähetin heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 21, 'Niin Pietari astui alas miesten tykö, jotka hänen tykönsä Korneliukselta lähetetyt olivat, ja sanoi: katso, minä se olen, jota te etsitte; mitä varten te tulleet olette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 22, 'Mutta he sanoivat: sadanpäämies Kornelius, hurskas ja Jumalaa pelkääväinen mies, jolla on todistus kaikelta Juudan kansalta, on pyhältä enkeliltä käskyn saanut, että hänen piti sinun antaman kutsua huoneesensa, sinulta sanoja kuullaksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 23, 'Niin hän kutsui heitä sisälle, ja otti heidät majaan. Toisena päivänä meni Pietari heidän kanssansa, ja muutamat veljet Jopesta seurasivat myös häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 24, 'Ja toisena päivänä tulivat he Kesareaan; ja Kornelius odotti heitä, ja oli kutsunut kokoon lankonsa ja parhaat ystävänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 25, 'Mutta kuin Pietari tuli sisälle, meni Kornelius häntä vastaan, ja lankesi hänen jalkainsa juureen, ja rukoili häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 26, 'Mutta Pietari nosti häntä ja sanoi: nouse! minäkin olen ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 27, 'Ja kuin hän oli häntä puhutellut, meni hän sisälle ja löysi monta tulleen kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 28, 'Ja hän sanoi heille: te tiedätte, ettei ole ollut luvallinen Juudalaisen olla jonkun muukalaisen tykönä eli hänen tykönsä mennä; mutta minulle osoitti Jumala, etten minä ketään ihmistä yhteisenä eli saastaisena pitäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 29, 'Sentähden minä myös epäilemättä tulin, teiltä kutsuttu. Niin minä siis teiltä kysyn: mitä varten te minua kutsuitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 30, 'Ja Kornelius sanoi: minä olen neljä päivää sitten paastonnut tähän hetkeen asti, ja rukoilin huoneessani yhdeksännellä hetkellä, ja katso, mies seisoi kiiltävissä vaatteissa minun edessäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 31, 'Ja sanoi: Kornelius, rukoukses on kuultu ja almus ovat Jumalan edessä muistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 32, 'Niin lähetä Joppeen ja kutsuta Simonin, joka Pietariksi kutsutaan; hän pitää majaa Simon Parkkarin huoneessa, meren tykönä: se puhuttelee sinua, kuin hän tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 33, 'Niin minä lähetin kohta sinun tykös, ja sinä teit hyvin, ettäs tulit. Ja me olemme siis kaikki nyt Jumalan edessä, kuulemassa kaikkia, mitä sinulle on Jumalalta käsketty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 34, 'Niin Pietari avasi suunsa ja sanoi: nyt minä todeksi löydän, ettei Jumala katso ihmisen muotoa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 35, 'Vaan kaikissa kansoissa, joka häntä pelkää ja tekee vanhurskautta, se on Jumalalle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 36, 'Sen sanan, jonka Jumala Israelin lapsille lähetti ja julisti rauhan Jesuksen Kristuksen kautta, joka kaikkein Herra on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 37, 'Te tiedätte sen sanan, joka on tapahtunut ympäri kaiken Juudean, ensin alkain Galileasta, sen kasteen jälkeen, josta Johannes saarnasi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 38, 'Kuinka Jumala oli voidellut Jesuksen Nasaretista Pyhällä Hengellä ja voimalla, joka vaelsi ympäri, teki hyvää ja paransi kaikki, jotka perkeleeltä vaivattiin; sillä Jumala oli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 39, 'Ja me olemme kaikkien niiden todistajat, mitkä hän Juudean maakunnassa ja Jerusalemissa teki, jonka he tappoivat ja ripustivat puuhun:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 40, 'Sen Jumala herätti kolmantena päivänä, ja ilmoitti hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 41, 'Ei kaikelle kansalle, vaan meille, jotka Jumala oli ennen todistajiksi valinnut, me jotka söimme ja joimme hänen kanssansa, sittenkuin hän nousi kuolleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 42, 'Ja hän käski meitä kansalle saarnaamaan ja todistamaan, että hän on se, joka Jumalalta on säätty elävien ja kuolleiden tuomariksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 43, 'Hänestä kaikki prophetat todistavat, että jokainen, joka uskoo hänen päällensä, pitää hänen nimensä kautta synnit anteeksi saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 44, 'Kuin Pietari vielä näitä puhui, lankesi Pyhä Henki kaikkein niiden päälle, jotka puheen kuulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 45, 'Niin ne uskovaiset ympärileikkauksesta, jotka Pietarin kanssa tulleet olivat, hämmästyivät, että pakanainkin päälle Pyhän Hengen lahja vuodatettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 46, 'Sillä he kuulivat heidän kielillä puhuvan ja Jumalaa ylistävän. Niin vastasi Pietari:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 47, 'Taitaako joku kieltää näitä, jotka ovat niin Pyhän Hengen saaneet kuin mekin, vedellä kastamasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 48, 'Ja hän käski kastaa heitä Herran nimeen. Silloin he rukoilivat häntä siellä muutamia päiviä viipymään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 1, 'Mutta apostolit ja veljet, jotka Juudeassa olivat, kuulivat, että pakanatkin Jumalan sanan ottivat vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 2, 'Ja kuin Pietari tuli ylös Jerusalemiin, riitelivät ne hänen kanssansa, jotka ympärileikkauksesta olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 3, 'Sanoen: sinä olet mennyt niiden miesten tykö, joilla esinahka on, ja söit heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 4, 'Niin Pietari rupesi heille järjestänsä luettelemaan, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 5, 'Minä olin Jopen kaupungissa rukouksissa, ja tulin horroksiin, ja näin näyn, yhden astian tulevan alas, niinkuin suuren liinaisen neljältä kulmalta lasketun alas taivaasta, joka tuli juuri minun tyköni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 6, 'Kuin minä katsoin sen päälle, äkkäsin minä ja näin maan neljäjalkaisia eläimiä, ja petoja, ja matelevaisia, ja taivaan lintuja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 7, 'Mutta minä kuulin äänen minulle sanovan: Pietari, nouse, tapa ja syö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 8, 'Mutta minä sanoin: en suinkaan, Herra; sillä ei ole mitään yhteistä eli saastaista minun suuhuni koskaan tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 9, 'Mutta ääni vastasi minua toisen kerran taivaasta: mitä Jumala on puhdistanut, älä sinä sano yhteiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 10, 'Ja se tapahtui kolmasti, ja vietiin taas kaikki ylös taivaaseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 11, 'Ja katso, kolme miestä seisoi kohta huoneen edessä, jossa minä olin, jotka Kesareasta olivat minun perääni lähetetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 12, 'Mutta Henki käski minun epäilemättä mennä heidän kanssansa; ja nämät kuusi veljeä seurasivat myös minua, ja me menimme sen miehen huoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 13, 'Ja hän jutteli meille, kuinka hän oli enkelin nähnyt huoneessansa seisovan ja sanovan hänelle: lähetä miehiä Joppeen, ja anna noutaa Simonin, joka Pietariksi kutsutaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 14, 'Hän on sanova sinulle ne sanat, joiden kautta sinä autuaaksi tulet ja kaikki sinun huonees.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 15, 'Mutta kuin minä rupesin puhumaan, lankesi Pyhä Henki heidän päällensä, niinkuin hän alussa meidänkin päällemme lankesi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 16, 'Niin minä muistin Herran sanan, jonka hän sanonut oli: Johannes tosin kasti vedellä, mutta te kastetaan Pyhällä Hengellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 17, 'Että nyt Jumala yhdenkaltaisen lahjan heille antoi kuin meillekin, jotka Herran Jesuksen Kristuksen päälle uskoimme: mikäs minä olisin, joka voisin kieltää Jumalaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 18, 'Kuin he nämät kuulivat, vaikenivat he ja kunnioittivat Jumalaa, sanoen: niin on siis Jumala antanut pakanoillekin kääntymyksen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 19, 'Ja ne, jotka siitä vainosta hajonneet olivat, joka Stephanin tähden tapahtui, vaelsivat ympäri hamaan Phenisiaan ja Kypriin ja Antiokiaan asti, eikä kellenkään sitä sanaa puhuneet, vaan ainoasti Juudalaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 20, 'Ja oli muutamia miehiä heidän seassansa Kypristä ja Kyrenistä: kuin ne tulivat Antiokiaan, puhuivat he Grekiläisille ja saarnasivat evankeliumia Herrasta Jesuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 21, 'Ja Herran käsi oli heidän kanssansa, ja suuri joukko uskoi ja kääntyi Herran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 22, 'Niin tämä sanoma heistä tuli seurakunnan korville, joka Jerusalemissa oli, ja he lähettivät Barnabaan Antiokiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 23, 'Kuin hän sinne tuli ja näki Jumalan armon, ihastui hän, ja neuvoi kaikkia vahvalla sydämellä Herrassa pysymään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 24, 'Sillä hän oli jalo mies ja täynnänsä Pyhää Henkeä ja uskoa, ja suuri joukko kansaa eneni Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 25, 'Niin Barnabas meni Tarsiin Saulusta etsimään; ja kuin hän löysi hänen, toi hän hänen Antiokiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 26, 'Ja tapahtui, että he koko ajastajan kokoontuivat seurakunnassa ja opettivat paljon kansaa; ja opetuslapsia ruvettiin ensin Antiokiassa kristityiksi kutsumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 27, 'Ja niinä päivinä tuli prophetaita Jerusalemista Antiokiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 28, 'Ja yksi heistä, Agabus nimeltä, nousi ja ilmoitti heille hengen kautta, kaikkeen maailmaan suuren nälän tulevan, joka myös Klaudius keisarin alla tapahtui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 29, 'Mutta opetuslapset sääsivät jotakin lähettää, kuin kullakin varaa oli, veljien avuksi, jotka Juudeassa asuivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 30, 'Niinkuin he tekivätkin, ja lähettivät vanhimmille Barnabaan ja Sauluksen kätten kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 1, 'Mutta sillä ajalla otti kuningas Herodes muutamia seurakunnasta kiinni, vaivataksensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 2, 'Ja mestasi Jakobin, Johanneksen veljen miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 3, 'Ja kuin hän näki sen Juudalaisille kelpaavan, pyysi hän myös Pietaria käsittää, (ja se oli makian leivän päivänä.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 4, 'Jonka hän myös käsitti, ja pani vankiuteen, ja antoi hänen neljän sotamiesten neljänneksen haltuun vartioida häntä, ja ajatteli pääsiäisen jälkeen asettaa hänen kansan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 5, 'Niin Pietari pidettiin tornissa; mutta seurakunnassa tapahtuivat rukoukset hartaasti hänen edestänsä Jumalan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 6, 'Ja kuin Herodes tahtoi hänen ottaa edes, makasi Pietari sinä yönä kahden sotamiehen vaiheella, sidottuna kaksilla kahleilla, ja vartiat oven edessä vartioitsivat tornia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 7, 'Ja katso, Herran enkeli seisoi hänen tykönänsä ja kirkkaus paisti huoneessa, lykkäsi Pietaria kylkeen, herätti hänen ja sanoi: nouse nopiasti. Ja kahleet putosivat hänen käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 8, 'Niin enkeli sanoi hänelle: sonnusta ja kengitä sinus. Ja hän teki niin. Ja hän sanoi vielä hänelle: pue itses vaatteisiis ja seuraa minua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 9, 'Ja hän meni ulos ja seurasi häntä, eikä tietänyt sitä todeksi, mitä enkeliltä tehtiin, vaan luuli näyn näkevänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 10, 'Mutta kuin he menivät ensimäisen ja toisen vartion lävitse, ja tulivat rautaiseen porttiin, joka vie kaupunkiin, niin se aukeni heille itsestänsä; ja he menivät siitä ulos, käyden katua myöten, ja kohta erkani enkeli hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 11, 'Ja kuin Pietari tointui entisellensä, sanoi hän: nyt minä totisesti tiedän, että Herra on enkelinsä lähettänyt, ja minun Herodeksen käsistä päästänyt ja kaikesta Juudan kansan toivosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 12, 'Ja kuin hän tätä ajatellut oli, tuli hän Marian, Johanneksen äidin, huoneen tykö, joka Markukseksi kutsuttiin, jossa monta oli koossa, ja rukoilivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 13, 'Mutta kuin Pietari porstuan oveen kolkutti, tuli piika, Roode nimeltä, kuultelemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 14, 'Ja kuin hän Pietarin äänen tunsi, ei hän ovea ilon tähden avannutkaan, vaan juoksi sisälle ja ilmoitti heille Pietarin porstuan edessä seisovan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 15, 'Niin he sanoivat hänelle: oletkos hullu? Vaan hän sanoi totisesti niin olevan. Niin he sanoivat: se on hänen enkelinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 16, 'Mutta Pietari kolkutti lakkaamatta. Kuin he avasivat, niin he näkivät hänen ja hämmästyivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 17, 'Mutta hän viittasi kädellänsä heitä vaikenemaan, ja jutteli heille, kuinka Herra oli hänen vankiudesta johdattanut ulos, ja sanoi: ilmoittakaat näitä Jakobille ja veljille. Ja läksi ulos ja meni toiseen paikkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 18, 'Mutta kuin päivä tuli, niin ei sotamiehillä ollut vähin kapina, kuhunka Pietari tullut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 19, 'Ja kuin Herodes piti sanan hänen perässänsä, eikä häntä löytänyt, antoi hän vartiat tutkia ja käski heitä rangaista. Ja meni Juudeasta alas Kesareaan ja viipyi siellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 20, 'Ja Herodes oli vihoissansa Tyron ja Sidonin asuvaisille; mutta he tulivat yksimielisesti hänen tykönsä ja lepyttivät kuninkaan kamaripalvelian Blastuksen, ja anoivat rauhaa; sillä heidän maakuntansa sai kuninkaan maasta elatuksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 21, 'Mutta määrättynä päivänä oli Herodes puetettu kuninkaallisissa vaatteissa, istuen tuomioistuimella, ja piti puheen heidän tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 22, 'Mutta kansa huusi: Jumalan ääni, ja ei ihmisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 23, 'Ja Herran enkeli löi kohta häntä, ettei hän kunniaa Jumalalle antanut. Ja hän syötiin madoilta, ja antoi henkensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 24, 'Mutta Jumalan sana kasvoi ja eneni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 25, 'Mutta Barnabas ja Saulus palasivat Jerusalemista, kuin he olivat palveluksen päättäneet, ja ottivat Johanneksen kanssansa, joka myös Markukseksi kutsuttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 1, 'Mutta Antiokian seurakunnassa oli muutamia prophetaita ja opettajia, Barnabas ja Simeon, joka Nigeriksi kutsuttiin, ja Lukius Kyreniläinen, ja Manahen, joka Herodes tetrarkan kanssa kasvatettu oli, ja Saulus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 2, 'Kuin siis nämät Herraa palvelivat ja paastosivat, sanoi Pyhä Henki: eroittakaat minulle Barnabas ja Saulus siihen työhön, johon minä heidät olen kutsunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 3, 'Ja kuin he olivat paastonneet ja rukoilleet, ja kätensä heidän päällensä panneet, päästivät he heidät menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 4, 'Ja kuin he Pyhältä Hengeltä lähetetyt olivat, menivät he Seleukiaan ja purjehtivat sieltä Kypriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 5, 'Ja kuin he Salaminassa olivat, ilmoittivat he Jumalan sanan Juudalaisten synagogissa; ja heillä oli myös Johannes palveliana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 6, 'Ja kuin he sen luodon lävitse matkustaneet olivat hamaan Paphoon asti, löysivät he velhon, väärän prophetan, Juudalaisen, jonka nimi oli Barjesus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 7, 'Joka oli maaherran Sergius Pauluksen, toimellisen miehen kanssa. Se kutsui Barnabaan ja Sauluksen tykönsä, ja halusi kuulla Jumalan sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 8, 'Mutta heitä vastaan seisoi Elimas velho (sillä niin tulkitaan hänen nimensä) ja pyysi kääntää maaherraa pois uskosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 9, 'Mutta Saulus (joka myös Paavaliksi kutsutaan,) oli täynnä Pyhää Henkeä, katsoi hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 10, 'Ja sanoi: voi sinä perkeleen poika, täynnä kaikkea vilppiä ja petosta, ja kaiken vanhurskauden vihamies, et sinä lakkaa vääntelemästä Herran oikeita teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 11, 'Ja nyt katso, Herran käsi on sinun päälläs; ja sinun pitää sokiana oleman eikä näkemän aurinkoa hetkessä aikaa. Ja hänen päällensä lankesi kohta synkeys ja pimeys, ja hän kävi ympäri, etsein kuka häntä kädestä taluttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 12, 'Kuin maaherra näki, mitä tapahtui, uskoi hän ja ihmetteli Herran opetusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 13, 'Mutta kuin Paavali ja ne, jotka hänen kanssansa olivat, Paphosta purjehtivat, tulivat he Pamphilian Pergeen; mutta Johannes erkani heistä ja palasi Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 14, 'Mutta he vaelsivat Pergestä ja tulivat Pisidian Antiokiaan, ja menivät sabbatina synagogaan, ja istuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 15, 'Ja sitte kuin laki ja prophetat olivat luetut, lähettivät synagogan päämiehet heidän tykönsä, sanoen: miehet, rakkaat veljet, onko teillä mitään kansaa neuvomista, niin sanokaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 16, 'Niin Paavali nousi ja viittasi kädellänsä heitä vaikenemaan, ja sanoi: Israelin miehet, ja jotka Jumalaa pelkäätte, kuulkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 17, 'Tämän kansan, Israelin, Jumala valitsi meidän isämme, ja korotti tämän kansan, muukalaisena ollessa Egyptin maalla, ja toi heidät sieltä ulos korkialla käsivarrella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 18, 'Ja kärsi heidän tapojansa korvessa lähes neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 19, 'Ja peräti kadotti Kanaanin maalla seitsemän kansaa, ja arvalla jakoi heille niiden maan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 20, 'Ja sitte lähes neljäsataa ja viisikymmentä ajastaikaa antoi hän heille tuomarit, Samuel prophetaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 21, 'Ja he pyysivät sitte kuningasta, ja Jumala antoi heille Saulin, Kisin pojan, miehen Benjaminin suvusta, neljäksikymmeneksi vuodeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 22, 'Ja kuin hän oli sen pannut pois, herätti hän Davidin heidän kuninkaaksensa, josta hän myös todisti ja sanoi: minä löysin Davidin, Jessen pojan, miehen minun sydämeni jälkeen, joka on kaikki minun tahtoni tekevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 23, 'Tämän siemenestä on Jumala lupauksensa perään herättänyt Jesuksen Israelille Vapahtajaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 24, 'Niinkuin Johannes saarnasi hänen tulemisensa edellä kaikelle Israelin kansalle parannuksen kastetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 25, 'Mutta kuin Johannes juoksun täyttänyt oli, sanoi hän: kenenkä te luulette minun olevan? En minä se ole, mutta katso, hän tulee minun jälkeeni, jonka kenkiä en minä ole kelvollinen jaloista riisumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 26, 'Miehet, rakkaat veljet, Abrahamin suvun lapset, ja jotka teissä ovat Jumalaa pelkääväiset, teille on tämän autuuden sana lähetetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 27, 'Sillä Jerusalemin asuvaiset ja heidän ylimmäisensä, ettei he tätä tunteneet, ovat he myös prophetain äänet, joita kunakin sabbatina luetaan, tuomitessansa täyttäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 28, 'Ja vaikka ei he yhtään kuoleman syytä löytäneet, anoivat he kuitenkin Pilatukselta, että hän piti tapettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 29, 'Ja kuin he kaikki olivat täyttäneet, mitä hänestä kirjoitettu oli, ottivat he hänen puun päältä ja panivat hautaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 30, 'Mutta Jumala herätti hänen kuolleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 31, 'Ja hän on monta päivää niiltä nähty, jotka hänen kanssansa Galileasta Jerusalemiin olivat menneet ylös, jotka ovat hänen todistajansa kansan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 32, 'Ja me ilmoitamme myös teille sen lupauksen, joka isille luvattiin, että Jumala on sen meille heidän lapsillensa täyttänyt, herättäin Jesuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 33, 'Niinkuin toisessa psalmissa kirjoitettu on: sinä olet minun Poikani, tänäpänä minä sinun synnytin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 34, 'Mutta siitä, että hän hänen kuolleista herätti, eikä silleen tule turmelukseen, sanoi hän näin: minä tahdon teille antaa ne lujat Davidin armot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 35, 'Sentähden hän myös sanoo toisessa paikassa: et sinä salli sinun Pyhäs turmelusta näkevän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 36, 'Sillä David, kuin hän ajallansa oli Jumalan tahtoa palvellut, nukkui, ja pantiin isäinsä tykö, ja näki turmeluksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 37, 'Mutta se, jonka Jumala herätti, ei ole nähnyt turmelusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 38, 'Sentähden olkoon teille tiettävä, miehet, rakkaat veljet, että teille tämän kautta ilmoitetaan syntein anteeksi antamus:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 39, 'Ja kaikista niistä, joista ette voineet Moseksen lain kautta vanhurskaaksi tulla, tämän kautta jokainen, joka uskoo, tulee vanhurskaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 40, 'Katsokaat siis, ettei teidän päällenne se tule, mitä prophetain kautta sanottu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 41, 'Katsokaat, te ylönkatsojat, ja ihmetelkäät ja hukkukaat; sillä minä teen yhden työn teidän aikananne, sen työn, jota ei teidän pidä uskoman, jos joku sanois teille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 42, 'Kuin Juudalaiset synagogasta läksivät, rukoilivat pakanat, että sabbatin välissä heille niitä sanoja puhuttaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 43, 'Ja kuin synagogan joukko erkani, seurasi monta Juudalaista ja myös monta jumalista uutta Juudalaista Paavalia ja Barnabasta, jotka heille puhuivat, ja heitä neuvoivat Jumalan armossa pysymään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 44, 'Mutta sitte lähimmäisenä lepopäivänä kokoontui lähes kaikki kaupunki Jumalan sanaa kuulemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 45, 'Kuin Juudalaiset näkivät kansan, täytettiin he kateudesta, ja sanoivat vastaan niitä, mitä Paavalilta sanoittiin, sanoen vastaan ja pilkaten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 46, 'Niin Paavali ja Barnabas puhuivat rohkiasti ja sanoivat: teille piti ensin Jumalan sanaa puhuttaman; vaan että te sen hylkäätte ja luette itsenne mahdottomaksi ijankaikkiseen elämään, katso, niin me käännymme pakanain tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 47, 'Sillä niin on Herra meitä käskenyt: minä panin sinun pakanain valkeudeksi, ettäs olisit autuus, maan ääriin asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 48, 'Ja kuin pakanat sen kuulivat, iloitsivat he ja kunnioittivat Herran sanaa; ja niin monta uskoi, kuin ijankaikkiseen elämään säädetty oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 49, 'Ja Herran sana leveni kaikkeen siihen maakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 50, 'Mutta Juudalaiset yllyttivät jumalisia ja kunniallisia vaimoja, niin myös kaupungin ylimmäisiä, ja kehoittivat vainon Paavalia ja Barnabasta vastaan; ja he sysäsivät heidät ulos maansa ääristä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 51, 'Mutta he pudistivat tomun jaloistansa heidän päällensä, ja tulivat Ikonioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 52, 'Niin opetuslapset täytettiin ilolla ja Pyhällä Hengellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 1, 'Niin Ikoniossa tapahtui, että he ynnä menivät sisälle Juudalaisten synagogaan, ja niin puhuivat, että suuri joukko Juudalaisia ja Grekiläisiä uskoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 2, 'Mutta uskomattomat Juudalaiset yllyttivät ja pahoittivat pakanain sielut veljiä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 3, 'Niin he olivat siellä kauvan aikaa ja puhuivat rohkiasti Herrassa, joka antoi todistuksen armonsa sanoihin, ja antoi merkit ja ihmeet heidän kättensä kautta tapahtua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 4, 'Niin sen kaupungin väki erkani: muutamat pitivät Juudalaisten kanssa, ja muutamat apostolien kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 5, 'Kuin siis pakanoilta ja Juudalaisilta kapina nousi, ynnä heidän päämiestensä kanssa, pilkkaamaan ja kivittämään heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 6, 'Ja kuin he sen ymmärsivät, pakenivat he Lykaonian kaupunkeihin Lystraan ja Derbeen, ja ympäri sitä lähimaakuntaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 7, 'Ja saarnasivat niissä evankeliumia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 8, 'Ja mies Lystrassa, sairas jaloista, istui, rampa hamasta äitinsä kohdusta, joka ei ikänänsä ollut käynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 9, 'Tämä kuuli Paavalin puhuvan; ja kuin hän katsahti hänen päällensä, ja näki hänellä uskon olevan terveeksi tulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 10, 'Sanoi hän suurella äänellä: ojenna sinus jalkais päälle. Ja hän karkasi ylös ja kävi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 11, 'Kuin kansa sen näki, mitä Paavali tehnyt oli, korottivat he äänensä Lykaonian kielellä sanoen: jumalat ovat ihmisten hahmolla alas meidän tykömme tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 12, 'Ja he kutsuivat Barnabaan Jupiteriksi ja Paavalin Merkuriukseksi; sillä hän oli sanansaattaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 13, 'Ja pappi Jupiterin templissä, joka heidän kaupunkinsa edessä oli, toi härkiä ja seppeleitä oven eteen, ja tahtoi ynnä kaupungin väen kanssa uhrata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 14, 'Kuin apostolit Barnabas ja Paavali sen kuulivat, repäisivät he vaattensa ja karkasivat kansan sekaan, huutain,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 15, 'Ja sanoen: miehet, miksi te tätä teette? Mekin olemme ihmiset, puuttuvaiset kuin tekin. Ja me saarnaamme teille evankeliumia, että te näistä turhista kääntyisitte elävän Jumalan tykö, joka teki taivaan, ja maan, ja meren, ja kaikki mitä niissä on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 16, 'Joka entisillä ajoilla antoi kaikki pakanat vaeltaa omilla teillänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 17, 'Vaikka ei hän itsiänsä antanut olla ilman todistusta, tehden hyvää, antain meille taivaasta sateen ja hedelmälliset ajat, täyttäin meidän sydämemme rualla ja ilolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 18, 'Ja kuin he näitä sanoivat, saivat he kansan tuskalla hillityksi, ettei he heille uhranneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 19, 'Niin sinne myös tuli muutamia Juudalaisia Antiokiasta ja Ikoniosta, ja kuin he kansan olivat saattaneet Paavalia kivittämään, riepoittivat he hänen ulos kaupungista, ja luulivat hänen kuolleeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 20, 'Mutta kuin opetuslapset hänen ympärillänsä seisoivat, nousi hän ja meni kaupunkiin, ja vaelsi toisena päivänä Barnabaan kanssa Derbeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 21, 'Ja kuin he olivat saarnanneet siinä kaupungissa evankeliumia ja monta opettaneet, palasivat he Lystraan ja Ikonioon ja Antiokiaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 22, 'Vahvistain opetuslasten sieluja, ja neuvoivat heitä uskossa pysymään (sanoen): että meidän pitää monen vaivan kautta Jumalan valtakuntaan tuleman sisälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 23, 'Ja kuin he olivat valinneet vanhimmat jokaiselle seurakunnalle, ja rukoilleet ja paastonneet, antoivat he heidät Herran haltuun, jonka päälle he uskoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 24, 'Ja he vaelsivat lävitse Pisidian ja tulivat Pamphiliaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 25, 'Ja kuin he olivat saarnanneet sanaa Pergessä, menivät he alas Attaliaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 26, 'Ja purjehtivat sieltä Antiokiaan, jossa he olivat Jumalan armon haltuun annetut, siihen työhön, jonka he toimittaneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 27, 'Mutta kuin he sinne tulivat ja seurakunnan kokosivat, ilmoittivat he, kuinka paljon Jumala oli heidän kanssansa tehnyt ja pakanoille uskon oven avannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 28, 'Ja he viipyivät siellä opetuslasten kanssa hetken aikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 1, 'Ja muutamat tulivat alas Juudeasta ja opettivat veljiä: ellei teitä ympärileikata Moseksen tavan jälkeen, niin ette taida autuaaksi tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 2, 'Koska siis kapina nousi, ja ei ollut vähin kamppaus Paavalilla ja Barnabaalla heitä vastaan, sääsivät he, että Paavali ja Barnabas ja muutamia muita heistä, piti menemän apostolien ja vanhimpain tykö ylös Jerusalemiin tämän kysymyksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 3, 'Ja he saatettiin seurakunnalta, ja vaelsivat Phenisian ja Samarian lävitse, julistain pakanain kääntymystä, ja saattivat suuren ilon kaikille veljille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 4, 'Kuin he tulivat Jerusalemiin, otettiin he vastaan seurakunnalta ja apostoleilta ja vanhimmilta, ja he ilmoittivat, kuinka suuria töitä Jumala heidän kanssansa tehnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 5, 'Niin nousivat muutaman Pharisealaisten lahkokunnassa, jotka uskoneet olivat, sanoen: he pitää ympärileikattaman ja käskettämän Moseksen lakia pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 6, 'Niin apostolit ja vanhimmat tulivat kokoon, tätä puhetta tutkimaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 7, 'Mutta kuin suuri kamppaus ollut oli, nousi Pietari ja sanoi heille: miehet, rakkaat veljet! te tiedätte, että Jumala kauvan ennen tätä aikaa valitsi meidän seassamme, että pakanat piti minun suuni kautta evankeliumin sanan kuuleman ja uskoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 8, 'Ja Jumala sydänten tutkia todisti heille ja antoi heille Pyhän Hengen niinkuin meillekin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 9, 'Ja ei tehnyt yhtään eroitusta meidän ja heidän välillänsä, puhdistain uskolla heidän sydämensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 10, 'Miksi te siis nyt kiusaatte Jumalaa, että te tahdotte opetuslasten kaulaan panna sen ikeen, jota ei meidän isämme emmekä me voineet kantaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 11, 'Vaan me uskomme Herran Jesuksen Kristuksen armon kautta autuaaksi tulevamme niinkuin hekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 12, 'Ja kaikki joukko vaikeni ja kuulteli Barnabasta ja Paavalia, jotka juttelivat, kuinka suuret merkit ja ihmeet Jumala oli heidän kauttansa pakanoissa tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 13, 'Vaan sitte kuin he vaikenivat, vastasi Jakob ja sanoi: miehet, rakkaat veljet, kuulkaat minua!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 14, 'Simon jutteli, kuinka Jumala ensin on etsinyt omistaaksensa kansaa nimellensä pakanoista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 15, 'Ja tämän kanssa prophetain sanat pitävät yhtä, niinkuin kirjoitettu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 16, 'Senjälkeen tahdon minä palata, ja Davidin kaatuneen majan jälleen rakentaa, ja hänen reikänsä paikata, ja sen ojentaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 17, 'Että ne, jotka ihmisistä jääneet ovat, pitää Herran perään kysymän, niin myös kaikki pakanat, joissa minun nimeni avuksihuudettu on, sanoo Herra, joka nämät tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 18, 'Jumalalle ovat kaikki hänen työnsä tiettävät maailman alusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 19, 'Sentähden minä päätän, ettemme niitä häiritsisi, jotka pakanoista Jumalan tykö kääntyvät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 20, 'Vaan kirjoittaisimme heille, että he välttäisivät epäjumalain saastaisuutta, ja salavuoteutta, ja läkähtynyttä ja verta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 21, 'Sillä Moseksella on muinaiselta jokaisessa kaupungissa niitä, jotka häntä saarnaavat, koska se joka sabbatina synagogassa luetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 22, 'Silloin kelpasi apostoleille ja vanhimmille, koko seurakunnan kanssa, joukostansa valita miehiä ja lähettää Antiokiaan, Paavalin ja Barnabaan kanssa: nimittäin Juudaan, joka kutsuttiin Barsabas, ja Silaan, ylimmäiset miehet veljesten seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 23, 'Ja kirjoittivat heidän kättensä kautta tällä tavalla: me apostolit ja vanhimmat veljet toivotamme veljille, jotka pakanoista Antiokiassa ja Syriassa ja Kilikiassa ovat, terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 24, 'Että me olemme kuulleet, kuinka muutamat meiltä lähteneet ovat teitä opillansa eksyttäneet ja teidän sielujanne vaivanneet, sanoen: teidän pitää itsenne antaman ympärileikata ja lain pitämän; joille emme ole käskeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 25, 'Niin kelpasi meille yksimielisesti kokoontuneille valita miehiä ja teidän tykönne lähettää, meidän rakkaan Barnabaan ja Paavalin kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 26, 'Jotka miehet ovat sielunsa meidän Herramme Jesuksen Kristuksen nimen tähden alttiiksi antaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 27, 'Niin me olemme lähettäneet Juudaan ja Silaan, jotka myös sen suusanalla teille ilmoittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 28, 'Sillä niin kelpasi Pyhälle Hengelle ja meille, ettei yhtään enempää raskautta pidä teidän päällenne pantaman kuin nämät tarpeelliset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 29, 'Että te vältätte epäjumalain uhria, ja verta, ja läkähtynyttä, ja salavuoteutta. Jos te niitä vältätte, niin te teette hyvin. Olkaat hyvästi!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 30, 'Kuin he siis olivat lähteneet, tulivat he Antiokiaan, ja kokosivat kansan paljouden, ja antoivat heille kirjan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 31, 'Kuin he sen olivat lukeneet, ihastuivat he siitä lohdutuksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 32, 'Mutta Juudas ja Silas, että hekin olivat prophetat, neuvoivat monilla sanoilla veljiä ja vahvistivat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 33, 'Ja kuin he siellä hetken aikaa viipyivät, lähetettiin he veljiltä jälleen rauhassa apostolien tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 34, 'Niin Silaan kelpasi siellä olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 35, 'Mutta Paavali ja Barnabas viipyivät Antiokiassa opettamassa ja ilmoittamassa Herran sanaa monen muun kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 36, 'Mutta muutamain päiväin perästä sanoi Paavali Barnabaalle: palatkaamme taas takaperin veljiä katsomaan kaikkiin kaupunkeihin, joissa me Herran sanaa ilmoittaneet olemme, kuinka he itsensä pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 37, 'Mutta Barnabas neuvoi kanssansa ottamaan Johannesta, joka Markukseksi kutsuttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 38, 'Mutta Paavali päätti sen kohtuulliseksi, ettei sitä pitänyt kanssa otettaman, joka oli luopunut heistä Pamphiliassa eikä tullut heidän kanssansa työhön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 39, 'Ja he riitelivät niin kovin keskenänsä, että he toinen toisestansa erkanivat. Ja Barnabas otti Markuksen kanssansa ja purjehti Kypriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 40, 'Mutta Paavali valitsi Silaan ja matkusti, Jumalan armon haltuun annettu veljiltä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 41, 'Ja vaelsi Syrian ja Kilikian kautta, ja vahvisti seurakunnat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 1, 'Niin hän tuli Derbeen ja Lystraan. Ja katso, siellä oli yksi opetuslapsi, Timoteus nimeltä, uskovaisen Juudalaisvaimon poika, mutta isä oli Grekiläinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 2, 'Sillä oli hyvä todistus veljiltä, jotka Lystrassa ja Ikoniossa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 3, 'Tätä tahtoi Paavali kanssansa vaeltamaan, otti ja ympärileikkasi hänen Juudalaisten tähden, jotka niissä paikoissa olivat; sillä he tiesivät kaikki, että hänen isänsä oli Grekiläinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 4, 'Mutta kuin he kaupungeita lävitse vaelsivat, antoivat he heille pidettäväksi ne säädyt, jotka asetetut olivat apostoleilta ja vanhimmilta, jotka Jerusalemissa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 5, 'Niin seurakunnat vahvistuivat uskossa ja heidän lukunsa eneni joka päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 6, 'Mutta kuin he Phrygian ja Galatian maakunnan lävitse vaelsivat, kiellettiin heitä Pyhältä Hengeltä puhumasta Jumalan sanaa Asiassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 7, 'Kuin he olivat tulleet Mysiaan, kiusasivat he vaeltaa Bitynian lävitse; mutta ei Henki sitä sallinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 8, 'Kuin he siis Mysian ohitse vaeltaneet olivat, menivät he alas Troadiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 9, 'Ja Paavali näki näyn yöllä: yksi Makedonian mies seisoi, rukoili häntä ja sanoi: tule Makedoniaan ja auta meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 10, 'Ja kuin hän näyn näki, hankitsimme me kohta Makedoniaan menemään, tietäen täydellisesti Herran meitä kutsuneen heille evankeliumia saarnaamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 11, 'Kuin me siis Troadista purjehdimme, niin me juoksimme kohdastansa Samotrakiaan, ja toisena päivänä Neapoliin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 12, 'Ja sieltä Philippiin, joka on Makedonian maakunnan pääkaupunki ja vapaa kaupunki; ja siinä kaupungissa me muutamia päiviä oleskelimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 13, 'Ja me menimme lepopäivänä ulos kaupungista, virran tykö, kussa tapa oli rukoilla: jossa me istuimme ja puhuttelimme vaimoja, jotka sinne tulleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 14, 'Ja vaimo, Lydia nimeltä, purpurain myyjä Tyatiron kaupungista, Jumalaa palvelevainen, kuulteli: jonka sydämen Herra avasi ottamaan vaaria niistä, mitä Paavalilta sanottiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 15, 'Ja kuin hän ja hänen huoneensa kastettu oli, rukoili hän meitä, sanoen: jos te minun Herralle uskollisena pidätte, niin tulkaat minun huoneeseeni ja olkaat siinä. Ja hän vaati heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 16, 'Ja tapahtui, kuin me rukoukseen menimme, kohtasi meitä piika, jolla noituuden henki oli, joka isännillensä saatti suuren saaliin noitumisellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 17, 'Tämä noudatti alati Paavalia ja meitä, ja huusi, sanoen: nämät miehet ovat korkeimman Jumalan palveliat, jotka meille autuuden tien ilmoittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 18, 'Ja sitä hän teki monta päivää. Mutta Paavali otti sen pahaksi, käänsi itsensä ja sanoi sille hengelle: minä käsken sinun Jesuksen Kristuksen nimeen hänestä mennä ulos; ja hän läksi ulos sillä hetkellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 19, 'Mutta kuin hänen isäntänsä sen näkivät, että heidän saaliinsa tuli pois, ottivat he Paavalin ja Silaan kiinni ja veivät heidät turulle päämiesten tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 20, 'Ja veivät heidän esivallan eteen, ja sanoivat: nämät miehet meidän kaupungin häiritsevät, jotka ovat Juudalaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 21, 'Ja opettavat niitä tapoja, joita ei meidän sovi ottaa vastaan eikä tehdä, sillä me olemme Roomalaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 22, 'Ja kansa nousi ynnä heitä vastaan, ja esivalta antoi heidän vaatteensa repiä, ja käski heitä piestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 23, 'Kuin he olivat heidät juuri pahoin pieksäneet, heittivät he heidät torniin ja käskivät vartian visusti heitä vartioida,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 24, 'Joka, kuin hän senkaltaisen käskyn sai, heitti heidät sisimmäiseen torniin ja pani heidät jalkapuuhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 25, 'Mutta puoliyön aikana oli Paavali ja Silas rukouksissa, ylistäin Jumalaa kiitosvirsillä, ja vangit, jotka siellä olivat, sen myös kuulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 26, 'Niin tapahtui äkisti suuri maan järistys, niin että tornin perustus vapisi; ja kohta kaikki ovet aukenivat, ja jokaisen siteet pääsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 27, 'Kuin vartia heräsi ja näki tornin ovet avoinna olevan, veti hän ulos miekkansa ja tahtoi surmata itsensä, ja luuli vangit paenneen pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 28, 'Niin Paavali huusi suurella äänellä ja sanoi: älä itselles mitään pahaa tee; sillä me olemme kaikki täällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 29, 'Niin hän anoi kynttilää, meni sisälle ja lankesi peljästyksissä Paavalin ja Silaan jalkain juureen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 30, 'Ja toi heidät ulos ja sanoi: herrat, mitä minun pitää tekemän, että minä autuaaksi tulisin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 31, 'Mutta he sanoivat: usko Herran Jesuksen Kristuksen päälle, niin sinä ja sinun huonees autuaaksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 32, 'Ja he puhuivat hänelle Herran sanaa ja kaikille, jotka hänen huoneessansa olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 33, 'Ja hän otti heidät sillä hetkellä yöstä tykönsä ja pesi heidän haavansa, ja hän kohta kastettiin ja kaikki hänen perheensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 34, 'Ja vei heidät kotiansa, ja valmisti heille pöydän, ja iloitsi, että hän koko huoneensa kanssa tuli Jumalan päälle uskovaiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 35, 'Ja kuin päivä tuli, niin esivalta lähetti kylänlapset sanomaan: päästä ne miehet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 36, 'Niin tornin vartia ilmoitti nämät sanat Paavalille, sanoen: esivalta on käskenyt päästää teidät: menkäät siis nyt ulos rauhassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 37, 'Mutta Paavali sanoi heille: he ovat julkisesti tuomitsematta pieksäneet meidät, jotka olemme Roomalaiset, ja heittäneet torniin, ja nyt salaa tahtoisivat sysätä meidät ulos. Ei niin, vaan tulkaan he itse meitä ottamaan täältä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 38, 'Niin kylänlapset ilmoittivat nämät sanat esivallalle jällensä; ja he pelkäsivät, että he heidät Roomalaisiksi kuulivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 39, 'Ja tulivat ja rukoilivat heitä, ja veivät heidät ulos, ja käskivät heidän mennä pois kaupungista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 40, 'Niin he läksivät tornista ja menivät Lydian tykö. Ja kuin he veljet nähneet olivat ja heitä lohduttaneet, vaelsivat he matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 1, 'Mutta kuin he Amphipolin ja Apollonian lävitse vaeltaneet olivat, tulivat he Tessalonikaan, jossa Juudalaisten synagoga oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 2, 'Ja Paavali, tapansa jälkeen, meni sisälle heidän tykönsä ja jutteli heille kolme lepopäivää Raamatuista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 3, 'Selitti ne ja todisti, että Kristuksen tuli kärsiä ja nousta ylös kuolleista, ja että tämä Jesus, josta minä (sanoi hän,) teille ilmoitan, on Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 4, 'Ja muutamat suostuivat heihin, antain itsensä Paavalin ja Silaan seuraan, niin myös suuri joukko jumalisia Grekiläisiä ja ei vähä ylimmäisiä vaimoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 5, 'Mutta epäuskoiset Juudalaiset kadehtivat sitä ja saattivat tykönsä muutamia pahanilkisiä miehiä joutoväestä, ja kokoontuivat yhteen joukkoon, nostivat kapinan kaupungissa ja tunkeutuivat Jasonin huoneeseen, ja etsivät heitä viedäksensä kansan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 6, 'Ja ettei he heitä löytäneet, riepoittivat he Jasonin ja muutamia veljiä kaupungin päämiesten eteen ja huusivat: nämät koko maan piirin vietteliät ovat myös täällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 7, 'Jotka Jason otti vastaan; ja nämät kaikki tekevät keisarin käskyä vastaan, sanoen toisen kuninkaan olevan, nimittäin Jesuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 8, 'Ja he kehoittivat kansan ja kaupungin päämiehet, jotka näitä kuultelivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 9, 'Ja kuin he Jasonilta ja niiltä muilta olivat puhdistuksen ottaneet, päästivät he heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 10, 'Mutta veljet lähettivät kohta yöllä Paavalin ja Silaan Bereaan. Kuin he sinne tulivat, menivät he Juudalaisten synagogaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 11, 'Sillä he olivat jalompaa sukua kuin ne, jotka Tessalonikassa olivat, ja ottivat juuri mielellänsä sanan vastaan ja tutkivat joka päivä Raamatuita, jos ne niin olisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 12, 'Niin monta heistä uskoivat, niin myös kunniallisista Grekiläisvaimoista ja miehistä ei harvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 13, 'Kuin Juudalaiset Tessalonikassa ymmärsivät, että Jumalan sana oli myös Bereassa Paavalilta ilmoitettu, tulivat he sinnekin ja kehoittivat kansan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 14, 'Mutta veljet lähettivät kohta Paavalin ulos menemään hamaan mereen asti; vaan Silas ja Timoteus jäivät sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 15, 'Ja ne, jotka Paavalia saattivat, johdattivat hänen hamaan Ateniin. Ja kuin he saivat käskyn Silaan ja Timoteuksen tykö, että he rientäisivät hänen tykönsä, läksivät he matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 16, 'Ja kuin Paavali odotti heitä Atenissa, syttyi hänen henkensä, että hän näki kaupungin aivan epäjumaliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 17, 'Niin hän puheli Juudalaisten ja muiden jumalisten kanssa synagogassa, niin myös turulla joka päivä niiden kanssa, jotka tulivat hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 18, 'Ja muutamat Epikurilaiset ja Stoalaiset philosophit riitelivät hänen kanssansa, ja muutamat sanoivat: mitä tämä lipilaari tahtoo sanoa? Mutta muut sanoivat: hän näkyy tahtovan outoja jumalia ilmoittaa: että hän saarnasi heille evankeliumia Jesuksesta ja ylösnousemisen kuolleista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 19, 'Ja he ottivat hänen ja veivät oikeuden paikkaan ja sanoivat: emmekö me mahda tietää, mikä uusi opetus tämä on, josta sinä puhut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 20, 'Sillä sinä tuotat jotakin outoa meidän korvillemme. Sentähden tahdomme me tietää, mitä ne ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 21, '(Mutta kaikki Atenalaiset ja muukalaiset vieraat ei olleet mihinkään muuhun soveliaat kuin jotakin uutta sanomaan ja kuultelemaan.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 22, 'Niin Paavali seisoi keskellä oikeuspaikkaa, ja sanoi: Atenan miehet! minä näen teidät kaikissa kappaleissa epäjumalisiksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 23, 'Sillä minä kävelin tässä ympäri ja katselin teidän jumalanpalvelustanne, ja löysin alttarin, jossa oli kirjoitettu: tuntemattomalle Jumalalle. Jota te siis tietämättä palvelette, sen minä teille ilmoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 24, 'Jumala, joka maailman teki ja kaikki mitä siinä on, joka on taivaan ja maan Herra, ei hän asu käsillä rakennetuissa templeissä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 25, 'Eikä häntä ihmisten käsillä palvella, niinkuin hän jotakin tarvitsis; sillä hän itse antaa jokaiselle elämän ja hengen sekä kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 26, 'Ja hän on tehnyt kaiken ihmisten sukukunnan yhdestä verestä kaiken maan piirin päälle asumaan, ja määräsi aivotut ajat ja heidän asumisensa rajat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 27, 'Että heidän piti Jumalaa etsimän, jos he hänen taitaisivat tuta ja löytää; vaikka ei hän tosin ole kaukana yhdestäkään meistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 28, 'Sillä hänessä me elämme, ja liikumme, ja olemme: niinkuin muutamat teidän runosepistänne sanoneet ovat: sillä me olemme myös hänen sukunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 29, 'Koska me siis Jumalan sukua olemme, niin ei meidän pidä luuleman, että Jumala on kullan eli hopian eli kiven kaltaisen kuvan kaltainen, joka ihmisen taidon ja ajatuksen jälkeen on kaivettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 30, 'Nämät eksytyksen ajat on tosin Jumala sallinut, ja ilmoittaa nyt kaikille ihmisille joka paikassa, että he parannuksen tekisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 31, 'Sillä hän on päivän säätänyt, jona hän on maan piirin tuomitseva vanhurskaudessa, sen miehen kautta, jonka hän on säätänyt, ja jokaiselle ilmoittaa uskon, siinä että hän hänen kuolleista herätti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 32, 'Kuin he kuulivat kuolleiden ylösnousemisen, niin muutamat nauroivat sitä, vaan toiset sanoivat: me tahdomme sinua siitä vielä kuunnella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 33, 'Ja niin Paavali läksi heidän keskeltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 34, 'Ja muutamat miehet riippuivat hänessä ja uskoivat: joidenka seassa myös Dionysius oli, yksi raadista, ja vaimo, nimeltä Damaris, ja muita heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 1, 'Senjälkeen läksi Paavali Atenasta ja tuli Korintoon,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 2, 'Ja löysi siellä Juudalaisen, Akvila nimeltä, Pontosta sukuisin, joka äsken Italiasta tullut oli, ja Priskillan hänen emäntänsä, (että Klaudius oli käskenyt kaikki Juudalaiset Roomista mennä pois,) joiden tykö hän meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 3, 'Ja että hän oli yhdessä ammatissa, viipyi hän heidän tykönänsä, ja teki työtä; sillä heidän ammattinsa oli telttoja tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 4, 'Mutta hän opetti synagogassa joka lepopäivä ja sai uskomaan sekä Juudalaisia että Grekiläisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 5, 'Mutta kuin Silas ja Timoteus Makedoniasta tulivat, oli Paavali hengeltä vaadittu, ja todisti Juudalaisille, että Jesus on Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 6, 'Kuin he puhuivat vastaan ja pilkkasivat, pudisti hän vaattensa ja sanoi heille: teidän verenne olkoon teidän päänne päälle: tästedes minä menen viatoinna pakanain tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 7, 'Ja hän siirsi itsensä sieltä ja meni yhden huoneesen, jonka nimi oli Justus: se oli Jumalaa palvelevainen, jonka huone oli läsnä synagogaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 8, 'Mutta Krispus, synagogan ylimmäinen, uskoi Herran päälle kaiken huoneensa kanssa. Ja monta Korintolaisista, jotka kuulivat, uskoivat ja kastettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 9, 'Mutta Herra sanoi yöllä Paavalille näyn kautta: älä pelkää, vaan puhu, äläkä vaikene;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 10, 'Sillä minä olen sinun kanssas, eikä yhdenkään pidä karkaaman sinun päälles vahingoittamaan sinua; sillä minulla on paljo kansaa tässä kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 11, 'Niin hän istui siellä ajastajan ja kuusi kuukautta, ja opetti heille Jumalan sanaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 12, 'Mutta kuin Gallio oli maanvanhin Akajassa, karkasivat Juudalaiset yksimielisesti Paavalin päälle ja veivät hänen tuomioistuimen eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 13, 'Sanoen: tämä neuvoo kansaa palvelemaan Jumalaa vastoin lakia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 14, 'Kuin Paavali rupesi suutansa avaamaan, sanoi Gallio Juudalaisille: jos olis jotakin vääryyttä eli jotakin hirmuista työtä tehty, oi Juudalaiset, niin olis kohtuullinen, että minä teitä kuulisin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 15, 'Mutta jos kysymys on opista ja sanoista ja teidän laistanne, niin katsokaat itse: en minä tahdo niiden tuomari olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 16, 'Ja ajoi pois heidät tuomioistuimen edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 17, 'Niin kaikki Grekiläiset ottivat kiinni Sosteneen, synagogan päämiehen, ja pieksivät hänen tuomioistuimen edessä; ja ei Gallio niitä mitään totellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 18, 'Mutta Paavali oli vielä siellä pitkän ajan, ja jätti veljet hyvästi, ja purjehti Syriaan, ja hänen kanssansa Priskilla ja Akvila, ja hän ajeli päänsä Kenkreissä; sillä hänellä oli lupaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 19, 'Ja tuli Ephesoon ja jätti ne sinne; mutta itse hän meni synagogaan ja puhui Juudalaisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 20, 'Ja he rukoilivat häntä, että hän enemmän aikaa viipyis heidän tykönänsä; vaan ei hän tahtonut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 21, 'Mutta jätti heidät hyvästi, sanoen: minun tulee kaiketi mennä Jerusalemiin tälle juhlalle, joka nyt lähestyy. Mutta sitte minä palajan, jos Jumala suo, teidän tykönne. Ja niin hän läksi matkaan Ephesosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 22, 'Ja tuli Kesareaan, meni ylös ja tervehti seurakuntaa, ja meni alas Antioikiaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 23, 'Ja vietti siellä hetken aikaa, ja meni sitten matkaansa, ja vaelsi järjestänsä Galatian ja Phrygian maakunnan lävitse, vahvistain kaikkia opetuslapsia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 24, 'Niin tuli Ephesoon Juudalainen, Apollos nimeltä, Aleksandriasta sukuisin, puhelias mies ja taitava Raamatuissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 25, 'Tämä oli opetettu Herran tielle ja oli palava hengessä, puhui ja opetti visusti Herrasta, ja tiesi ainoasti Johanneksen kasteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 26, 'Tämä rupesi rohkiasti synagogassa opettamaan. Kuin Akvila ja Priskilla hänen kuulivat, ottivat he hänen tykönsä ja selittivät tarkemmasti hänelle Jumalan tien.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 27, 'Mutta kuin hän tahtoi mennä Akajaan, kirjoittivat veljet ja neuvoivat opetuslapsia häntä korjaamaan. Ja kuin hän sinne tuli, autti hän paljon niitä, jotka uskoivat armon kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 28, 'Sillä hän voitti miehuullisesti Juudalaiset ja osoitti julkisesti Raamatuista, että Jesus on Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 1, 'Niin tapahtui, kuin Apollos oli Korintossa, että Paavali matkusti lävitse ylimaakuntain, ja tuli Ephesoon, ja löysi muutamia opetuslapsia,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 2, 'Ja sanoi heille: oletteko te saaneet Pyhän Hengen, sittenkuin te uskoitte? He sanoivat hänelle: emme ensinkään ole kuulleet, josko Pyhää Henkeä lieneekään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 3, 'Ja hän sanoi heille: milläs te olette kastetut? He sanoivat: Johanneksen kasteella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 4, 'Niin sanoi Paavali: Johannes tosin kasti parannuksen kasteella, sanoen kansalle, että heidän piti uskoman sen päälle, joka hänen jälkeensä tuleva oli, se on, Kristuksen Jesuksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 5, 'Niin ne, jotka sen kuulivat, kastettiin Herran Jesuksen nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 6, 'Ja kuin Paavali pani kätensä heidän päällensä, tuli Pyhä Henki heidän päällensä, ja he puhuivat kielillä ja ennustivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 7, 'Ja kaikki ne miehet olivat lähes kaksitoistakymmentä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 8, 'Niin hän meni synagogaan ja saarnasi rohkiasti kolme kuukautta, opetti ja neuvoi heitä Jumalan valtakunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 9, 'Mutta kuin muutamat heistä paatuivat ja ei uskoneet, vaan panettelivat Herran tietä yhteiselle kansalle, meni hän pois heidän tyköänsä, ja eroitti opetuslapset, ja puhui joka päivä yhden miehen koulussa, joka kutsuttiin Tyrannus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 10, 'Ja sitä tehtiin kaksi ajastaikaa, niin että kaikki ne, jota Asiassa asuivat, saivat kuulla Herran Jesuksen sanan, sekä Juudalaiset että Grekiläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 11, 'Ja Jumala teki Paavalin kätten kautta ei vähiä voimallisia töitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 12, 'Niin että hikiliinat ja esiliinat hänen iholtansa sairasten päälle tuotiin, ja taudit luopuivat heistä, ja pahat henget heistä läksivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 13, 'Niin muutamat Juudalaiset, jotka olivat lumoojat, vaelsivat ympäri, ja kiusasivat mainita Herran Jesuksen nimeä niiden päälle, joilla pahat henget olivat, ja sanoivat: me vannotamme teitä Jesuksen puolesta, jota Paavali saarnaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 14, 'Ja muutamat niiden seassa, jotka tätä tekivät, olivat Skevan, Juudalaisten ylimmäisen papin, seitsemän poikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 15, 'Mutta paha henki vastasi ja sanoi: Jesuksen minä tunnen, ja Paavalin minä tiedän, mutta mitkä te olette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 16, 'Ja ihminen, jossa paha henki oli, karkasi heidän päällensä, ja voitti heidät ja paiskasi heidät allensa, niin, että he alasti ja haavoitettuna pääsivät siitä huoneesta ulos pakenemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 17, 'Ja tämä tuli tiettäväksi sekä kaikille Juudalaisille että Grekiläisille, jotka Ephesossa asuivat, ja pelko tuli kaikkein päälle ja Herran Jesuksen nimi suuresti ylistettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 18, 'Ja tuli myös monta niistä, jotka uskoivat, tunnustivat ja ilmoittivat tekonsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 19, 'Ja monta niistä, jotka hempeitä juonia harjoitelleet olivat, toivat kirjat ja polttivat kaikkein nähden. Ja kuin niiden hinnat laskettu oli, niin löydettiin viisikymmentä tuhatta hopiapenninkiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 20, 'Niin voimallisesti kasvoi Herran sana ja vahvistui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 21, 'Kuin nämät toimitetut olivat, aikoi Paavali hengessä Makedonian ja Akajan lävitse vaeltaa Jerusalemiin, sanoen: sittekuin minä siellä ollut olen, täytyy minun myös Roomiin mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 22, 'Niin hän lähetti Makedoniaan kaksi niistä, jotka häntä palvelivat, Timoteuksen ja Erastuksen, mutta itse hän jäi hetkeksi aikaa Asiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 23, 'Mutta sillä ajalla nousi ei vähin kapina siitä tiestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 24, 'Sillä hopiaseppä, Demetrius nimeltä, teki hopiaisia Diana-templiä, josta niille, jotka sitä ammattia pitivät, oli ei vähin voitto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 25, 'Ne hän kutsui kokoon, ja jotka senkaltaista työtä tekivät, ja sanoi: miehet, te tiedätte, että meillä on tästä työstä jalo voitto,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 26, 'Ja te näette ja kuulette, ettei ainoasti Ephesossa, mutta lähes kaikessa Asiassa on tämä Paavali uskottanut ja kääntänyt pois paljon kansaa, sanoen, ettei ne ole jumalat, joita ihmisten käsillä tehdään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 27, 'Niin ei ainoasti vaara ole, että tämä meidän elatuksemme häpiään joutuisi, vaan myös että suuren naisjumalan Dianan tepliä ei minäkään pidettäisi ja hänen korkia kunniansa hukkuisi, jota koko Asia ja kaikki maailma palvelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 28, 'Mutta kuin he nämät kuulivat, tulivat he täyteen vihaa ja huusivat, sanoen: suuri on Ephesiläisten Diana!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 29, 'Ja kaikki kaupunki tuli meteliä täyteen, ja he karkasivat yksimielisesti katseluspaikkaan, ja ottivat kiinni Gajuksen ja Aristarkuksen, jotka olivat Makedoniasta Paavalin matkakumppanit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 30, 'Mutta kuin Paavali tahtoi kansan sekaan mennä, niin ei opetuslapset häntä laskeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 31, 'Ja muutamat päämiehet Asiasta, jotka hänen ystävänsä olivat, lähettivät hänen tykönsä ja rukoilivat, ettei hänen pitänyt katseluspaikkaan itsiänsä antaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 32, 'Ja muutamat muuta huusivat, niin että joukko oli peräti sekaseuraisin, ja enin osa ei tietänyt, minkätähden he olivat tulleet kokoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 33, 'Niin väkijoukosta vedettiin edes Aleksanteri, jonka Juudalaiset eteen syöksivät. Ja Aleksanteri viittasi kädellänsä, ja tahtoi edestänsä vastata kansan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 34, 'Kuin he siis ymmärsivät, että hän Juudalainen oli, huusivat he kaikki yhteen suuhun, lähes kaksi hetkeä, ja sanoivat: suuri on Ephesiläisten Diana!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 35, 'Mutta kuin kansleri oli hillinnyt kansan, sanoi hän: Epheson miehet! kuka on se ihminen, joka ei tiedä, että Epheson kaupunki palvelee suurta Dianaa ja taivaista pudonnutta kuvaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 36, 'Koska ei siis taideta sanoa sitä vastaan, niin asettakaat teitänne ja älkäät mitään tyhmiä tehkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 37, 'Sillä te olette nämät miehet vetäneet edes, jotka ei ole kirkon varkaita eikä teidän jumalanne pilkkaajia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 38, 'Jos siis Demetriuksella ja niillä, jotka hänen kanssansa työkumppanit ovat, on jonkun kanssa asiaa, niin pidetään laki ja oikeus; ovat myös maanvanhimmat: kantakaan toinen toisensa päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 39, 'Mutta jos teillä on riita muista asioista, niin ratkaistakoon asia laillisessa kokouksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 40, 'Sillä vaara on, että me nuhteesen tulemme tämänpäiväisen kapinan tähden, koska ei yhtään syytä ole, josta me taitaisimme tämän metelin tähden tilin tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 41, 'Ja kuin hän nämät sanonut oli, laski hän kansan menemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 1, 'Sittekuin kapina lakkasi, kutsui Paavali opetuslapset tykönsä ja tervehti heitä, ja läksi matkaansa Makedoniaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 2, 'Ja kuin hän ne maakunnat vaelsi, ja oli heitä monilla sanoilla neuvonut, tuli hän Grekan maalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 3, 'Ja viipyi siellä kolme kuukautta, ja että Juudalaiset väijyivät häntä, kuin hänen piti Syriaan menemään, aikoi hän palata Makedonian kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 4, 'Mutta Sopater Bereasta seurasi häntä Asiaan asti, ja Tessalonikasta Aristarkus ja Sekundus, ja Gajus Derbestä, ja Timoteus; mutta Asiasta Tykikus ja Trophimus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 5, 'Nämät läksivät edellä ja odottivat meitä Troadassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 6, 'Mutta me purjehdimme jälkeen pääsiäisen Philipistä ja tulimme heidän tykönsä Troadaan viitenä päivänä, ja viivyimme siellä seitsemän päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 7, 'Mutta ensimmäisenä viikonpäivänä, kuin opetuslapset kokoontuivat leipää taittamaan, saarnasi heille Paavali, ja aikoen toisena päivänä matkustaa, pitensi saarnan puoli-yöhön asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 8, 'Ja monta kynttilää oli sytytetty salissa, jossa me olimme koossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 9, 'Niin nuorukainen, nimeltä Eutykus, istui akkunalla, ja raukesi syvään uneen, ja Paavalin kauvan puhuessa, tuli hän unelta voitetuksi ja putosi alas kolmannesta ullakosta, ja otettiin kuolleena ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 10, 'Niin Paavali astui alas, ja laski itsensä hänen päällensä, ja otti syliinsä, ja sanoi: älkäät kapinoitko; sillä hänen sielunsa on vielä hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 11, 'Niin hän nousi, ja taitti leipää, ja söi, ja puheli kauvan heidän kanssansa, päivän koittamaan asti, niin hän läksi matkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 12, 'Niin he toivat nuorukaisen elävänä ja tulivat siitä lohdutetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 13, 'Mutta me astuimme edellä haahteen ja purhjehdimme Assoon, aikoen siellä ottaa Paavalin sisälle; sillä hän oli niin käskenyt, ja tahtoi itse maata myöten mennä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 14, 'Kuin hän Assossa meidän kanssamme yhteen tuli, otimme me hänen sisälle ja tulimme Mityleneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 15, 'Sieltä me purhjehdimme ja tulimme toisena päivänä Kion kohdalle. Ja taas pävää jälkeen tulimme me Samoon, ja viivyimme Trogylliossa. Ja päivää jälkeen tulimme me Miletoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 16, 'Sillä Paavali oli päättänyt purjehtia Epheson ohitse, ettei hän Asiassa aikaa kuluttaisi; sillä hän kiiruhti, jos hänelle olis mahdollinen ollut, helluntaiksi Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 17, 'Mutta hän lähetti Miletosta sanan Ephesoon ja kutsutti seurakunnan vanhimmat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 18, 'Kuin he tulivat hänen tykönsä, sanoi hän heille: te tiedätte, kuinka minä olen ollut kaiken ajan teidän tykönänne ensimmäisestä päivästä, jona minä Asiaan tulin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 19, 'Palvellen Herraa kaikella sydämen nöyryydellä, ja monilla kyyneleillä, ja kiusauksilla, jotka minulle Juudalaisten väijymisistä tapahtuivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 20, 'Etten minä ole mitään tarpeellista teiltä salannut, jota en minä ole teille ilmoittanut, ja olen teille opettanut julkisesti ja huone huoneelta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 21, 'Todistain sekä Juudalaisille että Grekiläisille sitä kääntymystä, joka Jumalan tykö on, ja sitä uskoa, joka meidän Herran Jesuksen Kristuksen päälle on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 22, 'Ja nyt katso, minä sidottuna hengessä matkustan Jerusalemiin, enkä tiedä, mitä minulle siellä tapahtuman pitää:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 23, 'Vaan että Pyhä Henki jokaisessa kaupungissa tunnustaa ja sanoo siteet ja murheet minun edessäni olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 24, 'Mutta en minä siitä lukua pidä, enkä tottele paljon hengestäni: että minä juoksuni päättäisin ilolla ja sen viran, jonka minä olen Herralta Jesukselta saanut, todistaakseni evankeliumia Jumalan armosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 25, 'Ja nyt katso, minä tiedän, ettette silleen saa nähdä minun kasvojani, kaikki te, joiden kautta minä olen vaeltanut ja Jumalan valtakuntaa saarnannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 26, 'Sentähden minä todistan teille tänäpänä, että minä olen viatoin kaikkein verestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 27, 'Sillä en minä ole estänyt itsiäni ilmoittamasta teille kaikkea Jumalan neuvoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 28, 'Niin ottakaat siis itsestänne vaari ja kaikesta laumasta, johon Pyhä Henki on teidät piispoiksi pannut, kaitsemaan Jumalan seurakuntaa, jonka hän omalla verellänsä ansainnut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 29, 'Sillä minä tiedän minun lähtemiseni jälkeen tulevan teidän sekaanne hirmuiset sudet, jotka ei laumaa säästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 30, 'Ja itse teistänne nousevat miehet, jotka vääryyttä puhuvat, vetääksensä pois opetuslapsia peräänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 31, 'Sentähden valvokaat, muistain etten minä kolmena ajastaikana ole lakannut yöllä ja päivällä teitä kyyneleillä neuvomasta itsekutakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 32, 'Ja nyt, rakkaat veljet, minä annan teidät Jumalan ja hänen armonsa sanan haltuun, joka väkevä on teitä rakentamaan ja antamaan teille perinnön kaikkein pyhitettyin seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 33, 'En minä ole yhdenkään hopiaa eikä kultaa eikä vaatteita pyytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 34, 'Vaan te itse tiedätte, että nämät kädet ovat minua tarpeissani ja niitä, jotka minun kanssani olivat, palvelleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 35, 'Kaikki olen minä teille osoittanut, että niin pitää työtä tehtämän: heikkoja korjattaman ja muistettaman Herran Jesuksen sanoja, jotka hän sanoi: autuaampi on antaa kuin ottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 36, 'Ja kuin hän nämät sanonut oli, lankesi hän polvillensa ja rukoili kaikkein heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 37, 'Ja suuri itku tuli heille kaikille ja lankesivat Paavalin kaulaan ja suuta antoivat hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 38, 'Murehtien suuresti sen sanan tähden, jonka hän oli sanonut, ettei heidän pitänyt enempi hänen kasvojansa näkemän. Ja he saattivat häntä haahteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 1, 'Kuin siis tapahtui, että me laskimme ulos ja heistä luovuimme, menimme me kohdastansa Koon saareen, ja toisena päivänä Rodoon, ja sieltä Pataraan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 2, 'Ja kuin me sieltä haahden löysimme, joka Phenikiaan hankitsi, siihen me astuimme, ja läksimme matkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 3, 'Ja kuin Kypros rupesi näkymään ja me sen vasemmalle puolelle jättäneet olimme, purjehdimme me Syriaan ja tulimme Tyroon; sillä siellä piti se haaksi tyhjennettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 4, 'Ja kuin me löysimme opetuslapsia, niin me olimme siellä seitsemän päivää. Ja ne sanoivat Paavalille hengen kautta, ettei hänen pitänyt Jerusalemiin menemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 5, 'Ja tapahtui, kuin me ne päivät olimme viettäneet, niin me läksimme matkaan, ja he saattivat kaikki meitä vaimoin ja lasten kanssa ulos kaupungista, ja me lankesimme rannassa polvillemme ja rukoilimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 6, 'Ja sittekuin me toinen toistamme tervehdimme, niin me astuimme haahteen; vaan he palasivat kotiansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 7, 'Mutta me päätimme meidän purjehdusretkemme, tulimme Tyrosta Ptolemaidaan, tervehdimme veljiä ja olimme päivän heidän tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 8, 'Toisena päivänä läksimme me matkaan, jotka Paavalin kanssa olimme, ja tulimme Kesareaan, ja menimme Philippus evankelistan huoneeseen, (joka oli yksi niistä seitsemästä,) ja jäimme hänen tykönsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 9, 'Ja hänellä oli neljä tytärtä, neitsyttä, jotka ennustivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 10, 'Ja että me olimme siellä monta päivää, tuli alas Juudeasta propheta, Agabus nimeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 11, 'Kuin hän tuli meidän tykömme, otti hän Paavalin vyön, sitoi jalkansa ja kätensä, ja sanoi: näin sanoo Pyhä Henki: sen miehen, jonka tämä vyö on, pitää Juudalaiset niin Jerusalemissa sitoman ja antaman ylön pakanain käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 12, 'Mutta kuin me sen kuulimme, rukoilimme sekä me että muut, jotka siinä olivat, ettei hänen pitänyt Jerusalemiin menemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 13, 'Niin Paavali vastasi: mitä te teette, että te itkette ja raskautatte minun sydäntäni? Sillä minä olen valmis, en ainoasti sidottaa, mutta myös kuolemaan Jerusalemissa, Herran Jesuksen nimen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 14, 'Ja ettei hän antanut itsiänsä puhuttaa ylitse, niin me siihen tyydyimme, sanoen: tapahtukoon Herran tahto!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 15, 'Ja niiden päiväin jälkeen tulimme me valmiiksi ja menimme ylös Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 16, 'Ja tulivat muutamat opetuslapset Kesareasta meidän kanssamme ja toivat vanhan opetuslapsen Kypristä, nimeltä Mnason, joka meitä piti huoneesensa ottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 17, 'Vaan kuin me tulimme Jerusalemiin, niin veljet mielellänsä meidät ottivat vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 18, 'Toisena päivänä meni Paavali meidän kanssamme Jakobin tykö, ja kaikki vanhimmat olivat läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 19, 'Kuin hän heitä oli tervehtinyt, jutteli hän järjestänsä, mitä Jumala oli hänen virkansa kutta pakanain seassa tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 20, 'Mutta kuin he nämät kuulivat, kunnioittivat he Herraa ja sanoivat hänelle: sinä näet, rakas veli, kuinka monta tuhatta Juudalaista ovat uskoneet, ja ne kaikki lain puolesta kiivaat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 21, 'Mutta he ovat sinusta kuulleet, että sinä opetat luopumista Moseksesta kaikille Juudalaisille, jotka pakanain seassa asuvat, sanoen ettei heidän pidä ympärileikkaaman lapsiansa eikä säätyin jälkeen vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 22, 'Mikä siis on? Kaiketi pitää kansan tuleman kokoon; sillä heidän pitää saaman tietää sinun tulleeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 23, 'Niin tee siis se, mitä me sinulle sanomme. Meillä on tässä neljä miestä, joilla on lupaus päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 24, 'Ota ne tykös, ja puhdista itses heidän kanssansa, ja kuluta jotakin heidän tähtensä, että he ajelisivat päänsä, ja siitä he kaikki ymmärtäisivät, ettei se mitään ole, mitä he sinusta kuulleet ovat, mutta että sinäkin vaellat, niinkuin sinä olisit lain pitävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 25, 'Mutta niistä, jotka uskoivat pakanoista, olemme me kirjoittaneet ja päättäneet, ettei heidän tarvitse näistä mitään pitää, vaan että he niitä välttäisivät, jotka epäjumalille ovat uhratut, ja verta, läkähtynyttä ja salavuoteutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 26, 'Silloin Paavali otti ne miehet tykönsä ja puhdisti itsensä toisena päivänä heidän kanssansa, ja meni templiin, ja ilmoitti, että puhdistuksen päivät olivat täytetyt, siihenasti kuin jokaisen edestä heidän seassansa uhri oli uhrattu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 27, 'Mutta kuin jo lähes seitsemän päivää kulunut oli, näkivät hänen Juudalaiset, jotka Asiasta olivat, templissä ja kehoittivat kaiken kansan, paiskasivat kätensä hänen päällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 28, 'Huutain: Israelin miehet, auttakaat! Tämä on se mies, joka kaikkia kaikissa paikoissa opettaa vastoin tätä kansaa ja lakia ja tätä siaa. Ja vieläkin hän on vienyt Grekiläisiäkin templiin, ja riivasi tämän pyhän sian.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 29, '(Sillä he olivat ennen nähneet Trophimon Ephesosta hänen kanssansa kaupungissa, ja he luulivat, että Paavali oli hänen templiin vienyt.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 30, 'Niin koko kaupunki nosti metelin, ja väki juoksi kokoon; ja he ottivat Paavalin kiinni ja riepoittivat hänen ulos templistä, ja kohta ovet suljettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 31, 'Ja kuin he tahtoivat hänen tappaa, niin ylimmäinen sotajoukon päämies sai sanan, että koko Jerusalem oli kehoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 32, 'Se otti kohta sotaväkeä ja sadanpäämiehiä, ja tuli juosten heidän tykönsä. Mutta kuin he näkivät sodanpäämiehen ja sotaväen, lakkasivat he Paavalia hosumasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 33, 'Kuin päämies lähestyi, otti hän hänen kiinni ja käski sitoa kaksilla kahleilla, ja kysyi, kuka hän oli, eli mitä hän oli tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 34, 'Mutta kansasta huusi yksi sitä, toinen tätä. Koska ei hän oikein taitanut ymmärtää huminan tähden, käski hän hänen vietää leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 35, 'Ja kuin hän astumien eteen tuli, kannettiin hän sotamiehiltä kansan väkivallan tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 36, 'Sillä paljo kansaa noudatti häntä, huutain: ota pois häntä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 37, 'Ja kuin Paavali oli leiriin tulemallansa, sanoi hän sodanpäämiehelle: onko minulla lupa sinulle jotakin sanoa? Hän sanoi: taidatkos Grekan kielen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 38, 'Etkös sinä siis ole Egyptin mies, joka ennen näitä päiviä kapinan nostit ja veit korpeen neljätuhatta murhamiestä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 39, 'Niin Paavali sanoi: minä olen Juudalainen Tarsin, kuuluisan kaupungin asuvainen Kilikiasta. Minä rukoilen sinua, salli minun puhua kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 40, 'Ja kuin hän salli, niin Paavali seisoi astuttavilla ja viittasi kädellänsä kansalle. Kuin suuri vaikeneminen tuli, puhutteli hän heitä Hebrean kielellä ja sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 1, 'Miehet, rakkat veljet ja isät! kuulkaat minun edesvastaustani, jonka minä teille sanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 2, '(Kuin he kuulivat hänen Hebrean kielellä heille puhuvan, vaikenivat he enemmin. Ja hän sanoi:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 3, 'Minä olen Juudalainen, Tarsossa Kilikiassa syntynyt ja tässä kaupungissa kasvatettu Gamalielin jalkain juuressa, opetettu visusti vanhimpain laissa, ja olin Jumalan puolesta kiivas, niinkuin tekin kaikki olette tänäpänä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 4, 'Ja olen tätä tietä vainonnut kuolemaan asti, sitoin ja antain ylön vankiuteen sekä miehiä että vaimoja,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 5, 'Niinkuin myös ylimmäinen pappi ja koko vanhimpain joukko minun todistajani ovat, joilta minä otin lähetyskirjat veljein tykö, ja vaelsin Damaskuun, että minä ne, jotka siellä olivat, olisin sidottuna tuonut Jerusalemiin rangaistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 6, 'Niin tapahtui minun matkassa ollessani ja lähestyissäni Damaskua puolipäivän aikaan, että suuri kirkkaus valaisi äkisti taivaasta minua ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 7, 'Ja minä lankesin maahan ja kuulin äänen minulle sanovan: Saul, Saul, miksis minua vainoot?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 8, 'Niin minä vastasin: kuka sinä olet, Herra? Hän sanoi minulle: minä olen Jesus Natsaretista, jota sinä vainoot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 9, 'Mutta ne, jotka minun kanssani olivat, näkivät kyllä kirkkauden ja peljästyivät, vaan ei he hänen ääntänsä kuulleet, joka minua puhutteli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 10, 'Niin minä sanoin: Herra, mitä minun pitää tekemän? Mutta Herra sanoi minulle: nouse ja mene Damaskuun, ja siellä sinulle sanotaan kaikki, mitä sinun on säätty tehdäkses.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 11, 'Ja koska en minä nähnyt sen valkeuden kirkkauden tähden, talutettiin minä käsistä niiltä, jotka minun kanssani olivat, ja tulin Damaskuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 12, 'Ja siellä oli jumalinen mies lain jälkeen, Ananias niemeltä; hänellä oli hyvä todistus kaikilta Juudalaisilta, jotka siellä asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 13, 'Hän tuli minun tyköni, seisoi ja sanoi minulle: rakas veljeni Saul, saa sinun näkös jälleen. Ja minä katsoin sillä hetkellä hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 14, 'Niin hän sanoi: meidän isäimme Jumala on sinun valmistanut, että sinun pitää tunteman hänen tahtonsa, ja näkemän vanhurskaan, ja kuuleman ääntä hänen suustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 15, 'Sillä sinun pitää oleman hänen todistajansa kaikkein ihmisten edessä niistä, joita sinä nähnyt ja kuullut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 16, 'Ja mitäs nyt viivyttelet? Nouse ja anna sinus kastettaa ja pestä pois sinun syntis, ja huuda avuksi Herran nimeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 17, 'Niin tapahtui, kuin minä Jerusalemiin palasin ja rukoilin templissä, että minä tulin horroksiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 18, 'Ja näin hänen minulle sanovan: riennä ja lähde kiiruusti Jerusalemista; sillä ei he ota vastaan sinun todistustas minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 19, 'Ja minä sanoin: Herra, itse he tietävät, että minä panin torniin ja pieksin jokaisessa synagogassa niitä, jotka sinun päälles uskoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 20, 'Ja kuin Stephanin sinun palvelias veri vuodatettiin, olin minä myös siinä läsnä, ja mielistyin hänen kuolemaansa, ja vartioitsin niiden vaatteita, jotka hänen tappoivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 21, 'Ja hän sanoi minulle: mene, sillä minä lähetän sinun kauvas pakanain tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 22, 'Ja he kuulivat häntä tähän sanaan asti, niin he korottivat äänensä ja sanoivat: ota pois senkaltainen ihminen maan päältä; sillä ei hänen ole luvallinen elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 23, 'Ja kuin he niin huusivat, heittelivät vaatteitansa ja paiskasivat tomua tuuleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 24, 'Antoi sodanpäämies hänen viedä leiriin, ja käski piestä ja tutkittaa, että hän olis saanut tietää, minkätähden hänen päällensä niin huudettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 25, 'Kuin hän häntä nuorilla sitoi, sanoi Paavali sadanpäämiehelle, joka läsnä seisoi: onkos teidän kohtuullinen Roomalaista hosua ilman tuomitsematta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 26, 'Kuin sadanpäämies sen kuuli, meni hän sodanpäämiehen tykö, ilmoitti hänelle ja sanoi: mitäs tahdot tehdä? sillä tämä mies on Roomalainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 27, 'Niin sodanpäämies meni hänen tykönsä ja sanoi hänelle: sanos minulle, oletko sinä Roomalainen? Hän sanoi: olen niinkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 28, 'Ja sodanpäämies vastasi: minä olen suurella rahalla tämän kaupungin oikeuden voittanut. Mutta Paavali sanoi: minä olen myös syntynyt (Roomalainen.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 29, 'Ja he läksivät kohta hänen tyköänsä tutkimasta. Ja sodanpäämies rupesi pelkäämään, sittekuin hän sai tietää, hänen Roomalaisen olevan, että hän hänen sitonut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 30, 'Mutta toisena päivänä tahtoi hän visummasti tietää, minkätähden hänen päällensä Juudalaisilta kannettiin, ja päästi hänen siteistä, ja käski ylimmäiset papit ja kaiken heidän raatinsa tulla kokoon, ja antoi Paavalin tulla heidän eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 1, 'Niin Paavali katsahti raadin päälle ja sanoi: miehet, rakkaat veljet! minä olen kaikella hyvällä tunnolla vaeltanut Jumalan edessä tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 2, 'Niin ylimmäinen pappi Ananias käski niitä, jotka läsnä seisoivat, lyödä häntä vasten suuta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 3, 'Paavali sanoi hänelle: lyököön sinua Jumala, sinä valkeaksi tehty seinä! istutko sinä ja tuomitset minua lain jälkeen, ja käsket minua lyödä vastoin lakia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 4, 'Mutta ne, jotka läsnä seisoivat, sanoivat: kiroiletko sinä ylimmäistä Jumalan pappia?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 5, 'Paavali sanoi: en minä tietänyt, rakkaat veljet, häntä ylimmäiseksi papiksi; sillä kirjoitettu on: sinun kansas ylimmäistä ei sinun pidä kiroileman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 6, 'Kuin Paavali tiesi, että heitä oli yksi osa Saddukealaisia ja toinen osa Pharisealaisia, huusi hän raadin edessä: miehet, rakkaat veljet! minä olen Pharisealainen ja Pharisealaisen poika. Minun päälleni kannetaan toivon ja kuolleiden ylösnousemisen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 7, 'Ja kuin hän sen sanonut oli, tuli riita Pharisealaisten ja Saddukealaisten välille, ja joukko erkani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 8, 'Sillä Saddukealaiset sanovat: ettei kuolleiden ylösnousemista, eikä enkeleitä, eikä henkeä ole; mutta Pharisealaiset tunnustavat molemmat olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 9, 'Niin tuli suuri huuto, ja kirjanoppineet Pharisealaisten lahkosta nousivat, kilvoittelivat ja sanoivat: emme mitään pahaa löydä tässä miehessä: jos henki taikka enkeli on hänelle puhunut, niin emme mahda Jumalaa vastaan sotia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 10, 'Ja että suuri kapina nousi, pelkäsi sodanpäämies, ettei he Paavalia rikki repäisisi, ja käski sotaväen mennä alas, ja temmata pois häntä heidän seastansa, ja leiriin viedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 11, 'Mutta yöllä sen jälkeen seisoi Herra hänen tykönänsä ja sanoi: ole vahvassa turvassa, Paavali! sillä niinkuin sinä olet minusta Jerusalemissa todistanut, niin sinun pitää Roomissakin todistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 12, 'Ja kuin päivä tuli, kokoontuivat muutamat Juudalaisista ja sadattelivat itsiänsä, sanoen, ettei heidän pitänyt ennen syömän eikä juoman, kuin he Paavalin olisivat tappaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 13, 'Ja niitä oli enempi kuin neljäkymmentä miestä, jotka tämän valan tehneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 14, 'Ne menivät ylimmäisten pappein ja vanhimpain tykö, ja sanoivat: me olemme sadatuksilla meitämme kironneet, ei ennen einettä maistavamme kuin me Paavalin tapamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 15, 'Nyt siis ilmoittakaat sodanpäämiehelle ja raadille, että hän huomenna tois hänen teidän eteenne, niinkuin te tahtoisitte jotakin todempaa häneltä tiedustaa; mutta ennenkuin hän lähestyy, olemme me valmiit häntä tappamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 16, 'Kuin Paavalin sisaren poika heidän väijymisensä kuuli, meni hän leiriin ja ilmoitti nämät Paavalille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 17, 'Niin Paavali kutsui yhden sadanpäämiehistä tykönsä ja sanoi: vie tämä nuorukainen sodanpäämiehen tykö; sillä hänellä on jotakin hänelle sanomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 18, 'Niin hän otti sen ja saatti hänen sodanpäämiehen tykö, ja sanoi: sidottu Paavali kutsui minun tykönsä ja rukoili minua tätä nuorukaista sinun tykös saattaa, jolla on sinulle jotakin sanomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 19, 'Niin sodanpäämies rupesi hänen käteensä, ja vei hänen erinänsä, ja kyseli häneltä: mitä se on, mitä sinulla on minulle ilmoittamista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 20, 'Niin hän sanoi: Juudalaiset ovat päättäneet sinua rukoilla, ettäs huomenna tuottaisit Paavalin raadin eteen, niinkuin he jotakin todempaa häneltä kuuntelisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 21, 'Mutta älä heitä tottele; sillä enempi kuin neljäkymmentä miestä väijyy häntä, jotka ovat heitänsä sadattaneet, ei ennen syövänsä eikä juovansa, kuin he hänen tappaisivat: ja he ovat nyt valmiit odottamassa sinun lupaamistas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 22, 'Niin sodanpäämies laski nuorukaisen matkaansa ja haasti häntä kellenkään sanomasta, että hän nämät hänelle ilmoittanut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 23, 'Ja hän kutsui tykönsä kaksi sadanpäämiestä ja sanoi: valmistakaat kaksisataa sotamiestä menemään Kesareaan, ja seitsemänkymmentä ratsasmiestä, ja kaksisataa keihäsmiestä kolmannella hetkellä yöstä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 24, 'Ja valmistakaat muutamia juhtia, että he Paavalin niiden päälle istuttavat ja vievät terveenä maanvanhimman Feliksen tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 25, 'Ja kirjoitti kirjan tällä tavalla:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 26, 'Klaudius Lysias sille jalolle maanvanhimmalle Felikselle terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 27, 'Tämän miehen olivat Juudalaiset ottaneet kiinni ja tahtoivat hänen tappaa. Niin tulin minä parhaallansa sotaväellä sekaan ja tempasin hänen pois, että minä ymmärsin hänen Roomalaisen olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 28, 'Ja kuin minä pyysin syytä tietää, mistä he häntä nuhtelivat, niin minä vein hänen heidän raatinsa eteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 29, 'Ja löysin kannettavan hänen päällensä heidän lakinsa kysymyksistä. Ja ei kuitenkaan heillä ollut yhtään kuoleman eli sidetten syytä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 30, 'Ja kuin minulle siitä väijymisestä ilmoitettiin, jota Juudalaiset hänelle valmistivat, lähetin minä kohta hänen sinun tykös, ja sanoin hänen päällekantajillensa: mitä teillä on häntä vastaan, niin sanokaat maanvanhimman edessä. Ole hyvästi!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 31, 'Ja sotamiehet ottivat Paavalin, niinkuin heille käsketty oli, ja veivät hänen yöllä Antipatrideen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 32, 'Ja toisena päivän antoivat he ratsasmiesten häntä seurata ja palasivat leiriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 33, 'Kuin he tulivat Kesareaan ja antoivat kirjan maanvanhimmalle, niin he asettivat myös Paavalin hänen eteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 34, 'Kuin maanvanhin oli kirjan lukenut ja kysynyt, kusta maakunnasta hänen piti oleman; ja että hän ymmärsi hänen Kilikiasta olevan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 35, 'Minä tahdon sinua kuulla, sanoi hän, kuin myös sinun päällekantajas tulevat edes. Ja käski kätkeä hänen Herodeksen raatihuoneeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 1, 'Viiden päivän perästä meni Ananias, ylimmäinen pappi, vanhimpain ja selväkielisen Tertulluksen kanssa maanvanhimman tykö Paavalia vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 2, 'Ja kuin hän oli eteen kutsuttu, rupesi Tertullus kantamaan, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 3, 'Me elämme hyvässä rauhassa sinun kauttas, ja ne asiat, jotka tässä kansassa oikein ja hyvin tehnyt ovat sinun toimellas, voimallinen Feliks, me aina ja joka paikassa hyväksi otamme kaikella kiitoksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 4, 'Vaan etten minä sinua kauvan viivyttäisi, rukoilen minä sinua, ettäs pikimiltäs meitä kuulisit, sinun vakuutes tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 5, 'Sillä me olemme löytäneet tämän miehen vahingolliseksi, joka nostaa kapinan kaikille Juudalaisille ympäri koko maanpiirin, ja on Natsarealaisten eriseuran päämies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 6, 'Hän on kiusannut templiäkin riivata; jonka tähden me otimme hänen kiinni ja tahdoimme tuomita hänen meidän lakimme jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 7, 'Mutta sodanpäämies Lysias tuli suurella väellä siihen sekaan ja päästi hänen meidän käsistämme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 8, 'Ja käski hänen päällekantajansa tulla sinun tykös; josta sinä taidat itse tutkien ymmärtää kaikista niistä, joita me hänen päällensä kannamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 9, 'Ja Juudalaiset tähän myös mielistyivät, sanoen niin olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 10, 'Niin Paavali vastasi, kuin maanvanhin häntä viittasi puhumaan: että minä tiedän sinun monta ajastaikaa olleen tämän kansan tuomarina, tahdon minä pelkäämättä edestäni vastata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 11, 'Sillä sinä taidat ymmärtää, ettei enempi ole kuin kaksitoistakymmentä päivää, sittekuin minä menin ylös Jerusalemiin rukoilemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 12, 'Ja ei he ole minua templissäkään löytäneet kamppailemasta yhdenkään kanssa, ei kapinaa nostamasta kansan seassa, ei synagogissa, eikä kaupungissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 13, 'Ei he myös taida niitä vahvistaa, mitä he nyt minun päälleni kantavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 14, 'Mutta sen minä sinulle tunnustan, että minä tämän tien kautta, jonka he eriseuraksi kutsuvat, niin palvelen minun isäini Jumalaa, että minä uskon kaikki, mitkä laissa ja prophetaissa kirjoitetut ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 15, 'Ja pidän sen toivon Jumalan puoleen, jota hekin itse odottavat, että kuolleiden ylösnousemus pitää oleman, sekä vanhurskasten että vääräin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 16, 'Ja sentähden minä harjoitan itsiäni aina pitämään pahentamattoman omantunnon Jumalan ja ihmisten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 17, 'Mutta kuin minä monen ajastajan perästä tulin almua ja uhria kansalleni tekemään:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 18, 'Joissa muutamat Juudalaiset Asiasta löysivät minun puhdistettuna templissä, ilman yhtäkään kapinaa ja meteliä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 19, 'Joidenka tulis sinun tykönäs läsnä olla ja kantaa, jos heillä jotakin on minua vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 20, 'Eli sanokaan nämät itse, jos he jotakin vääryyttä ovat minussa löytäneet, koska minä seisoin raadin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 21, 'Mutta tämän yhden sanan tähden, jonka minä heidän seassansa seisoissani, kuolleiden ylösnousemisesta, huusin, minä teiltä tänäpänä tuomitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 22, 'Kuin Feliks tämän kuuli, viivytti hän heitä; sillä hän tiesi hyvin tämän tien menon, ja sanoi: kuin Lysias sodanpäämies alas tulee, niin minä tahdon tutkia teidän asianne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 23, 'Ja käski sadanpäämiehen kätkeä Paavalin, ja antoi hänen saada levon, ja ettei yhtäkään hänen omistansa kiellettäisi häntä palvelemasta taikka käymästä hänen tykönänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 24, 'Mutta muutamain päiväin perästä tuli Feliks emäntänsä Drusillan kanssa, joka Juudalainen oli, ja kutsutti Paavalin eteensä, ja kuulteli häntä uskosta Kristuksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 25, 'Mutta kuin hän puhui vanhurskaudesta ja puhtaasta elämästä ja tulevaisesta tuomiosta, peljästyi Feliks, ja vastasi: mene tällä haavalla matkaas; vaan kuin minä saan tilan, niin minä sinun tyköni kutsutan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 26, 'Toivoi myös Paavalilta hänellensä rahaa annettavan, että hän olis hänen päästänyt, jonka tähden hän myös usein hänen tykönsä kutsutti ja puheli hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 27, 'Kuin kaksi ajastaikaa kulunut oli, tuli Porkius Festus Feliksen siaan. Mutta Feliks tahtoi Juudalaisten mieltä noutaa ja jätti Paavalin sidottuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 1, 'Kuin siis Festus oli tullut maakuntaan, meni hän Kesareasta kolmannen päivän perästä ylös Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 2, 'Niin ylimmäinen pappi ja ylimmäiset Juudalaisista tulivat hänen eteensä Paavalia vastaan, ja rukoilivat häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 3, 'Ja pyysivät häneltä suosiota häntä kohtaan, että hän kutsuttais hänen Jerusalemiin, ja väijyivät häntä tappaaksensa tiellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 4, 'Niin Festus vastasi, että Paavali piti hyvin kätkettämän Kesareassa, ja että hän tahtoi itse pian sinne vaeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 5, 'Jotka siis teidän seassanne, sanoi hän, voimalliset ovat, ne tulkaan alas meidän kanssamme, ja jos jotakin vääryyttä on tässä miehessä, niin kantakaan he hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 6, 'Kuin hän siis oli heidän tykönänsä viipynyt enempi kuin kymmenen päivää, läksi hän alas Kesareaan. Ja toisena päivänä istui hän tuomioistuimelle ja käski Paavalin tuoda edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 7, 'Kuin hän oli tullut edes, seisoivat ne Juudalaiset ympärillä, jotka olivat Jerusalemista tulleet alas, ja toivat edes monta ja suurta vikaa Paavalia vastaan, joita ei he voineet vahvistaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 8, 'Sillä hän vastasi edestänsä: en minä ole mitään rikkonut Juudalaisten lakia, en templiä, enkä keisaria vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 9, 'Niin Festus tahtoi Juudalaisten mieltä noutaa, vastasi Paavalia ja sanoi: tahdotkos mennä ylös Jerusalemiin ja siellä näistä oikeudella seisoa minun edessäni?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 10, 'Mutta Paavali sanoi: minä seison keisarin oikeudessa, ja siinä tulee minua tuomita: en minä ole Juudalaisille mitään vääryyttä tehnyt, kuin sinä itsekin paremmin tiedät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 11, 'Sillä jos minä olen jonkun vahingoittanut, eli minun henkeni rikkonut, niin en minä tahdo välttää kuolemaa: jos ei taas mitään niistä ole, mitä he minun päälleni kantavat, niin ei yksikään taida minua antaa heidän käsiinsä: minä turvaan keisariin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 12, 'Silloin Festus puhutteli raatia ja vastasi: keisariin sinä turvasit, keisarin tykö pitää myös sinun menemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 13, 'Mutta kuin muutamat päivät olivat kuluneet, tuli kuningas Agrippa ja Bernise alas Kesareaan Festusta tervehtimään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 14, 'Ja kuin he siellä monta päivää viipyivät, jutteli Festus Paavalin asian kuninkaalle ja sanoi: yksi mies on jäänyt Felikseltä sidottuna,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 15, 'Josta, kuin minä Jerusalemissa olin, ylimmäiset papit ja Juudalaisten vanhimmat tulivat ja ilmoittivat minulle, pyytäin tuomiota hänen ylitsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 16, 'Joille minä vastasin: ei se ole Roomalaisten tapa, että joku ihminen ennen annetaan surmata, kuin se, jonka päälle kannetaan, saa päällekantajat rinnallensa ja saa tilan edestänsä vastata kanteesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 17, 'Sentähden kuin he tänne kokoon tulivat, istuin minä kohta toisena päivänä viivyttelemättä tuomioistuimelle, ja käskin miehen tuoda edes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 18, 'Kuin päällekantajat tulivat, niin ei he yhtään syytä tuoneet edes niistä, mitä minä luulin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 19, 'Mutta heillä oli muutamia kysymyksiä häntä vastaan heidän taikauksistansa ja yhdestä kuolleesta Jesuksesta, jonka Paavali todisti elävän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 20, 'Vaan että minä siitä kysymyksestä epäilin, kysyin minä, josko hän olis tahtonut mennä Jerusalemiin ja siellä näistä tuomittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 21, 'Mutta koska Paavali lykkäsi asiansa keisarin tutkimisen alle, annoin minä hänen kätkettää, siihen asti kuin minä hänen keisarin tykö lähettäisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 22, 'Niin Agrippa sanoi Festukselle: minäkin kuulisin mielelläni sitä miestä. Hän sanoi: huomenna saat sinä häntä kuulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 23, 'Ja toisena päivänä tuli Agrippa ja Bernise suurella koreudella, ja menivät raastupaan, päämiesten ja kaupungin ylimmäisten kanssa, ja Paavali tuotiin edes Festuksen käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 24, 'Ja Festus sanoi: kuningas Agrippa ja kaikki miehet, jotka tässä meidän kanssamme olette, te näette sen, josta kaikki Juudalaisten joukko on minua rukoillut Jerusalemissa ja myös täällä, huutain, ettei hänen pitäisi enempi elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 25, 'Mutta kuin minä ymmärsin, ettei hän ollut mitään kuoleman ansiota tehnyt, ja että hän myös itse turvasi keisariin, niin minä aioin hänen sinne lähettää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 26, 'Josta ei minulla ole mitään vahvaa herralle kirjoittaa: sentähden tuotin minä hänen teidän eteenne, ja enimmiten sinun etees, kuningas Agrippa, että kuin hänen asiansa visummasti tutkittaisiin, minulla olis jotakin kirjoittamista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 27, 'Sillä se on minun nähdäkseni toimetoin, että hän sidottuna lähetetään, ja ei hänen syytänsä ilmoiteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 1, 'Niin Agrippa sanoi Paavalille: sinun on lupa puhua edestäs. Silloin Paavali ojensi kätensä ja vastasi edestänsä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 2, 'Minä pidän itseni onnellisena, rakas kuningas Agrippa, että minä tänäpänä saan sinun edessäs vastata kaikista niistä, mitä minun päälleni Juudalaisilta kannetaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 3, 'Liiatenkin että sinä tiedät kaikki tavat ja Juudalaisten kysymykset: sentähden rukoilen minä sinua, että kärsivällisesti minua kuulisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 4, 'Kaikki tosin Juudalaiset tietävät minun elämäni hamasta nuoruudesta, kuin se alusta on ollut minun kansani seassa Jerusalemissa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 5, 'Jotka minun ennen ovat tunteneet, (jos he tahtoisivat todistaa,) että minä meidän jumalanpalveluksen kaikkein ahkerimman eriseuran jälkeen olin Pharisealainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 6, 'Ja minä seison nyt tässä oikeuden edessä toivon tähden sen lupauksen päälle, joka Jumalalta on meidän isillemme tapahtunut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 7, 'Johonka meidän kaksitoistakymmentä sukukuntaa toivovat tulevansa, palvellen Jumalaa yötä ja päivää. Tämän toivon tähden kannetaan Juudalaisilta minun päälleni, rakas kuningas Agrippa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 8, 'Miksi se luotaan mahdottomaksi uskoa teidän tykönänne, että Jumala kuolleet herättää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 9, 'Minä tosin luulin itselläni, että minun piti paljo vastahakoisuutta tekemän Jesuksen Natsarealaisen nimeä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 10, 'Niinkuin minä myös tein Jerusalemissa, ja salpasin monta pyhää vankihuoneisiin, kuin minä ylimmäisiltä papeilta olin saanut vallan; ja kuin he tapettiin, mielistyin minä heidän tuomioonsa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 11, 'Ja rankaisin heitä usein jokaisessa synagogassa, ja vaadin heitä pilkkaamaan, ja olin heitä vastaan ylönpalttisesti vimmattu, ja vainosin heitä hamaan ulkokaupunkeihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 12, 'Jonka tähden minä myös matkustin Damaskuun ylimmäisten pappein voimalla ja käskyllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 13, 'Puolipäivän aikaan, rakas kuningas, näin minä tiellä yhden kirkkauden taivaasta, kirkkaamman kuin auringon paisteen, joka valkeus ympäri valaisi minun ja ne, jotka minun kanssani vaelsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 14, 'Kuin me siis kaikki maahan lankesimme, kuulin minä äänen puhuvan minulleni ja sanovan Hebrean kielellä: Saul, Saul, miksis minua vainoot? työläs on sinun tutkainta vastaan potkia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 15, 'Niin minä sanoin: Herra, kukas olet? Hän sanoi: minä olen Jesus, jota sinä vainoot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 16, 'Mutta nouse ylös ja seiso jaloillas: sillä sitä varten minä sinulle ilmestyin, että minä asetan sinun palveliaksi ja niiden todistajaksi, joita sinä näit, niin myös niiden, joita minä vielä sinulle ilmoittava olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 17, 'Ja tahdon sinun päästää tästä kansasta ja pakanoista, joiden tykö minä nyt sinun lähetän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 18, 'Heidän silmiänsä avaamaan ja heitä pimeydestä valkeuteen kääntämään, että he eriäisivät saatanan vallasta Jumalan tykö, saamaan syntein anteeksiantamista ja perimistä ynnä niiden kanssa, jotka pyhitetään uskon kautta minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 19, 'Niin siis, rakas kuningas Agrippa! en minä ollut taivaalliselle näylle kovakorvainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 20, 'Vaan ilmoitin ensin niille, jotka Damaskussa ja Jerusalemissa ovat ja kaikessa Juudan maakunnassa, ja myös pakanoille, että he parannuksen tekisivät, ja kääntyisivät Jumalan puoleen, ja tekisivät parannuksen kelvollisia töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 21, 'Tämän tähden ovat Juudalaiset minun templissä ottaneet kiinni ja tahtoivat minun surmata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 22, 'Mutta Jumalan avun olen minä saanut ja seisonut tähän päivään asti, todistaen sekä pienille että suurille, enkä mitään muuta sanoen kuin mitä prophetat ja Moses ovat sanoneet tulevaksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 23, 'Että Kristuksen piti kärsimän ja oleman ensimäisen kuolleiden ylösnousemisesta julistamassa valkeutta tälle kansalle ja pakanoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 24, 'Kuin hän näin edestänsä vastasi, sanoi Festus suurella äänellä: Paavali, sinä hulluttelet, suuri oppi hulluttaa sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 25, 'Niin hän sanoi: en minä hulluttele, voimallinen Festus, vaan totuuden ja toimen sanoja puhun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 26, 'Sillä kyllä kuningas nämät tietää, jonka tykönä minä myös rohkiasti puhun, ja en minä luule näistä mitään olevan häneltä salatun: sillä ei tämä ole loukkaassa tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 27, 'Uskotkos, kuningas Agrippa, prophetat? minä tiedän, ettäs uskot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 28, 'Niin Agrippa sanoi Paavalille: ei paljo puutu, ettes minua saa kristityksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 29, 'Paavali sanoi: minä toivoisin Jumalalta, joko siitä puuttuis vähä eli paljo, että et ainoasti sinä, mutta myös kaikki, jotka minua tänäpänä kuulevat, tulisivat senkaltaiseksi kuin minäkin olen, paitsi näitä siteitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 30, 'Ja kuin hän nämät sanonut oli, nousi kuningas ylös, ja maanvanhin, ja Bernise, ja jotka heidän kanssansa istuneet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 31, 'Ja kuin he menivät pois, puhuivat he keskenänsä, sanoen: eipä tämä mies ole mitään tehnyt, mikä kuoleman eli siteet ansainnut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 32, 'Mutta Agrippa sanoi Festukselle: kyllä tämä mies olis taidettu päästää, ellei hän olisi keisariin turvannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 1, 'Mutta sittenkuin päätetty oli, että meidän piti Italiaan purjehtiman, antoivat he Paavalin muiden vankien kanssa yhden sadanpäämiehen haltuun, joka kutsuttiin Julius, keisarin sotajoukosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 2, 'Kuin me siis astuimme Adramytin haahteen, ja meidän piti purjehtiman Asian ohitse, laskimme me ulos maalta. Ja meidän kanssamme oli Aristarkus, Makedonian mies, Tessalonikasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 3, 'Ja me tulimme toisena päivänä Sidoniin. Ja Julius meni hyvästi Paavalin kanssa, ja salli hänen mennä ystäväinsä tykö ja heiltä holhottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 4, 'Ja kuin me sieltä laskimme ulos, niin me purjehdimme Kyprin ohitse, että vastatuulet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 5, 'Ja kuin me olimme purjehtineet yli meren, joka Kilikian ja Pamphilian kohdalla on, ja tulimme Myraan, joka on Lykiassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 6, 'Niin löysi sadanpäämies siellä yhden Aleksandrialaisen haahden, joka Italiaan purjehti, ja pani meidät siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 7, 'Kuin me monta päivää hitaasti purjehdimme ja tuskalla Knidon saavutimme, ettemme päässeet tuulelta, niin me purjehdimme Kretan alle, Salmoneen päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 8, 'Ja kuin me tuskin sen ohitse pääsimme, niin me tulimme yhteen paikkaan, joka Kauniiksi satamaksi kutsutaan, jota läsnä oli Lasean kaupunki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 9, 'Koska paljo aikaa oli kulunut, ja purjehdus oli vaarallinen, ja paaston aika oli jo kulunut, neuvoi Paavali heitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 10, 'Sanoen: armaat miehet! minä näen, että purjehdus tulee vaaralliseksi ja vahingolliseksi, ei ainoastaan kalulle ja haahdelle, mutta myös meidän hengellemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 11, 'Mutta sadanpäämies uskoi enemmin haahdenhaltiaa ja peränpitäjää kuin Paavalin sanoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 12, 'Ja kuin ei satama ollut sovelias yli talvea olla, niin he enimmitten mielistyivät siihen neuvoon, että sieltä piti laskettaman pois, jos he jollakin muotoa olisivat voineet tulla Phoinikaan talvea pitämään, joka on Kretan satama, etelälänteä ja luodepohjaa päin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 13, 'Mutta kuin etelätuuli rupesi puhaltamaan, luulivat he aikomisensa käyvän edes, läksivät matkaan ja purjehtivat Kretan ohitse lähempänä maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 14, 'Mutta ei kauvan aikaa jälkeen löi sen päälle ankara puuskatuuli, joka itäpohjaksi kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 15, 'Ja kuin haaksi tuli sen valtaan eikä voinut tuulta vastaan seisoa, laskimme me sen tuulen haltuun kulkemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 16, 'Ja kuin me tulimme yhden vähän saaren alle, joka kutsutaan Klauda, saimme me tuskalla venheesen ruveta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 17, 'Jonka me otimme avuksemme ja sidoimme haahteen, peljäten, ettei sen pitänyt kariin sattuman; ja he laskivat alas purheen ja antoivat kulkea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 18, 'Mutta koska suuri ilma kävi päälle, heittivät he toisena päivänä kalun ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 19, 'Ja kolmantena päivänä heitimme me omilla käsillämme ulos haahden kaluja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 20, 'Mutta kuin emme monena päivänä aurinkoa emmekä tähtiä nähneet, eikä vähin ilma meidän päällemme käynyt, niin meidän elämämme toivo oli jo kaikki pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 21, 'Ja koska me kauvan aikaa olimme syömättä, silloin seisoi Paavali heidän keskellänsä ja sanoi: miehet, teidän olis tullut minua kuulla ja ei Kretasta laskea ulos, että me olisimme välttäneet tainkaltaisen tuskan ja vahingon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 22, 'Ja nytkin minä neuvon teitä, olkaat hyvässä uskalluksesta, ei teistä yksikään huku, vaan ainoastaan haaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 23, 'Sillä minun tykönäni seisoi tänä yönä Jumalan enkeli, jonka oma minä olen, jota minä myös palvelen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 24, 'Ja sanoi: älä pelkää, Paavali, sinä pitää keisarin eteen asetettaman, ja katso, Jumala on sinulle lahjoittanut ne kaikki, jotka sinun kanssas purjehtivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 25, 'Sentähden miehet, olkaat hyvässä uskalluksessa! Sillä minä uskon Jumalan päälle, että se niin tapahtuu, kuin minulle sanottu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 26, 'Mutta yhteen luotoon pitää meidän kulkeman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 27, 'Kuin neljästoistakymmenes yö joutui, ja me ajeltiin Adrian merellä, äkkäsivät haaksimiehet puoliyön aikaan jonkun maan heitä lähestyvän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 28, 'Ja heittivät ulos luotirihman ja löysivät kaksikymmentä kyynärää syväksi; kuin he tulivat vähää edemmä, heittivät he taas ulos luotirihman ja löysivät viisitoistakymmentä kyynärää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 29, 'Niin he pelkäsivät joutuvansa johonkuhun kariin, ja heittivät ulos neljä ankkuria perältä haahta, ja toivoivat päivän koittavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 30, 'Mutta kuin haaksimiehet pyysivät haahdesta paeta, ja lykkäsivät venheen mereen, sanoen että he tahtoivat ankkuria viedä ulos haahden keulasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 31, 'Niin Paavali sanoi sadanpäämiehelle ja sotamiehille: ellei nämät haahdessa pysy, ette suinkaan henkeänne pelasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 32, 'Niin sotamiehet hakkasivat poikki venheen pestin, ja antoivat sen pudota.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 33, 'Ja kuin päivä rupesi valkenemaan, neuvoi Paavali kaikkia heitä ruokaa ottamaan, sanoen: tänäpänä on neljästoistakymmenes päivä, kuin te odottaneet olette, ja syömättä olleet, ja ette mitään ole tykönne ottaneet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 34, 'Sentähden neuvon minä teitä ruokaa ottamaan, joka on teille terveydeksi; sillä ei yhdenkään teidän päästänne ole hiuskarva putoova.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 35, 'Ja kuin hän sen oli sanonut, otti hän leivän, ja kiitti Jumalaa kaikkein nähden, mursi, ja rupesi syömään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 36, 'Ja kuin he kaikki itsensä vahvistivat, rupesivat he myös syömään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 37, 'Mutta meitä oli haahdessa kaikki yhteen kaksisataa ja kuusikahdeksattakymmentä henkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 38, 'Ja kuin he olivat ravitut, kevensivät he haahden ja heittivät jyvät mereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 39, 'Mutta kuin päivä tuli, niin ei he tunteneet maata, mutta havaitsivat lahden, jossa ranta oli, jonka päälle he mielivät antaa haahden ajaa, jos he olisivat taitaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 40, 'Ja kuin he ankkurit olivat ottaneet ylös, läksivät he mereen ja päästivät perälautain siteet, ja asettivat purjeen tuuleen, ja antoivat juosta rantaa kohden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 41, 'Vaan kuin me tulimme yhden niemen tykö, loukkaantui haaksi, ja sen keula tarttui kiinni ja jäi seisomaan, mutta kastari tuli valallensa aaltoin väestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 42, 'Mutta sotamiesten neuvo oli vankeja tappaa, ettei joku uiden olisi karannut pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 43, 'Mutta sadanpäämies tahtoi Paavalia vapahtaa, ja esti heidät siitä neuvosta, ja käski niitä, jotka uida taisivat, että he ensin itsensä antaisivat ulos ja maalle pääsisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 44, 'Mutta muita lautain päällä, muutamia taas haahden kappaleilla (kulkea). Ja niin tapahtui, että jokainen tuli hengissä maalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 1, 'Ja kuin he terveinä päässeet olivat, tunsivat he, että se luoto Meliteksi kutsutaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 2, 'Mutta se kansa osoitti meille ei vähintä rakkauden halua; sillä he tekivät meille valkian, ja kaikki ottivat vastaan meidät, sen sateen ja vilun tähden, joka meidän päällemme tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 3, 'Mutta kuin Paavali kokosi kasan risuja ja pani valkialle, tuli yksi kärme palavuudesta ja karkasi hänen käteensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 4, 'Kuin kansa näki kärmeen riippuvan hänen kädessänsä, sanoivat he keskenänsä: kaiketi tämä ihminen on miehentappaja, jota ei koston jumalatar saali elää, vaikka hän on meren hädästä päässyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 5, 'Mutta hän pudisti kärmeen tuleen eikä mitään kipua tuntenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 6, 'Mutta he odottivat hänen ajettuvan eli kohta maahan lankeevan ja kuolevan; vaan kuin he kauvan sitä odottivat ja näkivät, ettei hänelle mitään vahinkoa tapahtunut, saivat he toisen mielen ja sanoivat hänen jumalaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 7, 'Mutta vähän matkan takana siitä olivat sen luodon päämiehellä, jonka nimi oli Publius, maakartanot, joka meitä otti vastaan ja piti meidän kunniallisesti vierainansa kolme päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 8, 'Niin tapahtui, että Publiuksen isä sairasti vilutautia ja vatsankipua, jonka tykö Paavali meni, rukoili ja pani kätensä hänen päällensä, ja paransi hänen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 9, 'Kuin siis se oli tehty, tulivat myös muut sairaat siitä luodosta, ja parannettiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 10, 'Jotka myös meille tekivät paljon kunniaa, ja kuin me sieltä purjehdimme, panivat he meidän myötämme, mitä me tarvitsimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 11, 'Mutta kolmen kuukauden perästä purjehdimme me sieltä Aleksandrian haahdessa, joka sen luodon tykönä oli talvea pitänyt, jolla oli lipun merkki kaksoinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 12, 'Ja kuin me tulimme Syrakusaan, olimme me siellä kolme päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 13, 'Ja kuin me sieltä ympäri purjehdimme ja tulimme Regioon, ja päivää jälkeen puhalsi lounatuuli, niin että me toisena päivänä tulimme Puteoliin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 14, 'Kuin me sieltä löysimme veljet, niin meitä rukoiltiin olemaan heidän tykönänsä seitsemän päivää; ja niin me tulimme Roomiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 15, 'Ja kuin siellä veljet kuulivat meistä, tulivat he meitä vastaan hamaan Appiforuun ja Tretaberniin. Kuin Paavali heidät näki, kiitti hän Jumalaa ja sai uskalluksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 16, 'Mutta kuin me Roomiin tulimme, antoi sadanpäämies vangit sodanpäämiehen haltuun. Mutta Paavali sallittiin olevan itsellänsä yhden sotamiehen kanssa, joka hänestä otti vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 17, 'Niin tapahtui kolmen päivän jälkeen, että Paavali kutsui kokoon ylimmäiset Juudalaisista. Ja kuin he tulivat kokoon, sanoi hän heille: miehet, veljet, vaikka en minä ole mitään tehnyt kansaa eli isäin säätyjä vastaan, kuitenkin olen minä sidottuna annettu Jerusalemista Roomalaisten käsiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 18, 'Jotka, koska he olivat minun tutkineet, tahtoivat minua päästää, ettei yhtään hengen rikosta minussa ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 19, 'Mutta koska Juudalaiset sitä vastaan sanoivat, täytyi minun turvata keisariin, ei niin, että minulla olis jotakin kantamista minun kansani päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 20, 'Tämän syyn tähden olen minä kutsunut teitä, että minä saisin teitä nähdä ja puhutella; sillä minä olen Israelin toivon tähden tällä kahleella sidottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 21, 'Niin he sanoivat hänelle: emme ole kirjaa saaneet sinusta Juudeasta, ei myös yksikään veljistä ole sieltä tullut ja meille ilmoittanut, eikä jotakuta pahuutta sinusta puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 22, 'Mutta me tahdomme sinulta kuulla, mitä sinun mielessäs on; sillä tästä seurasta on meille tiettävä, että sitä vastaan joka paikassa sanotaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 23, 'Ja kuin he olivat hänelle päivän määränneet, niin tuli monta hänen tykönsä majaan, joille hän selitti ja todisti Jumalan valtakunnasta, ja opetti heille Jesuksesta, Moseksen laista ja prophetaista huomenesta ehtoosen asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 24, 'Ja muutamat uskoivat ne, mitkä sanottiin, mutta muutamat ei uskoneetkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 25, 'Mutta kuin he tulivat riitaisiksi keskenänsä, menivät he matkaansa, että Paavali oli yhden sanan sanonut: Pyhä Henki on oikein meidän isillemme Jesaias prophetan kautta puhunut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 26, 'Sanoen: mene tämän kansan tykö ja sano: korvillanne pitää teidän kuuleman ja ei ymmärtämän, ja silmillänne pitää teidän näkemän ja ei tunteman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 27, 'Sillä tämän kansan sydän on kovettunut, ja he kuulevat raskaasti korvillansa, ja panevat silmänsä umpeen, ettei he joskus silmillänsä näkisi, eikä korvillansa kuulisi, ei myös ymmärtäisi sydämellänsä, eikä kääntäisi heitänsä, että minä heitä parantaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 28, 'Niin olkoon se teille tiettävä, että tämä Jumalan autuus on lähetetty pakanoille, ja he myös sen kuulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 29, 'Ja kuin hän näitä puhunut oli, läksivät Juudalaiset pois ja riitelivät paljo keskenänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 30, 'Mutta Paavali oli täyttä kaksi ajastaikaa omassa palkkahuoneessansa ja otti kaikki vastaan, jotka hänen tykönsä tulivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 31, 'Ja saarnasi Jumalan valtakunnasta, ja opetti Herrasta Jesuksesta Kristuksesta kaikella uskalluksella, ja ei häntä yksikään kieltänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Paavali, Jesuksen Kristuksen palvelia, kutsuttu apostoliksi, eroitettu Jumalan evankeliumiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(Jonka hän on ennen prophetainsa kautta pyhissä Raamatuissa luvannut,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Hänen Pojassansa, (joka on Davidin siemenestä lihan puolesta syntynyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Ja on väkevästi ilmoitettu Jumalan Pojaksi pyhityksen hengen jälkeen, että hän on noussut ylös kuolleista,) se on, Jesuksesta Kristuksesta meidän Herrastamme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Jonka kautta me olemme armon ja apostolin viran saaneet, uskon kuuliaisuudeksi, kaikkein pakanain seassa, hänen nimensä päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Joista tekin olette Jesuksen Kristuksen kutsutut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Kaikille, jotka Roomissa ovat, Jumalan rakkaille ja kutsutuille pyhille: armo olkoon teidän kanssanne, ja rauha Jumalalta meidän Isältämme ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ensin kiitän minä Jumalaani, Jesuksen Kristuksen kautta, teidän kaikkein tähtenne, että teidän uskoanne kaikessa maailmassa mainitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Sillä Jumala on minun todistajani, jota minä hengessäni hänen Poikansa evankeliumissa palvelen, että minä lakkaamatta teitä muistan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Rukoillen aina minun rukouksissani, että minä saisin jollakin tavalla vihdoin joskus, jos Jumala tahtoo, onnellisen tien tulla teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 11, 'Sillä minä ikävöitsen teitä nähdä, että minä jotain hengellistä lahjaa teille jakaisin, että te vahvistetuksi tulisitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 12, 'Se on, että minä saisin ynnä teidän kanssanne lohdutuksen, uskon kautta, joka meillä keskenämme on, sekä teidän että minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 13, 'Mutta en minä tahdo salata teiltä, rakkaat veljet, että minä olen usein aikonut tulla teidän tykönne, (ja olen tähän asti estetty) että minä teidänkin seassanne jonkun hedelmän saisin, niinkuin muidenkin pakanain seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 14, 'Minä olen velkapää Grekiläisille ja muukalaisille, viisaille ja tyhmille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 15, 'Sentähden niin paljo kuin minussa on, olen minä teillekin, jotka Roomissa olette, valmis evankeliumia saarnaamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 16, 'Sillä en minä häpee Kristuksen evankeliumia; sillä se on Jumalan voima itsekullekin uskovaiselle autuudeksi. Ensin Juudalaiselle, niin myös Grekiläiselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 17, 'Sillä siinä se vanhurskaus, joka Jumalan edessä kelpaa, ilmoitetaan uskosta uskoon, niinkuin kirjoitettu on: vanhurskaan pitää elämän uskosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 18, 'Sillä Jumalan viha ilmestyy taivaasta kaiken ihmisten jumalattomuuden ja vääryyden tähden, jotka totuuden vääryydessä pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 19, 'Sentähden se, mikä taidetaan Jumalasta tuta, on heille tiettävä; sillä Jumala ilmoitti sen heille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 20, 'Sillä hänen näkymättömät menonsa, nimittäin, ijankaikkinen voimansa ja jumaluutensa nähdään hamasta maailman luomisesta, jotka ymmärretään niistä, jotka tehdyt ovat: ettei he taitaisi itseänsä syyttömiksi sanoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 21, 'Että he tunsivat Jumalan, ja ei ylistäneet häntä niinkuin Jumalaa eikä kiittäneet, vaan vilpistelivät omissa ajatuksissansa, ja heidän järjetöin sydämensä on pimennyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 22, 'Kuin he itsensä viisaiksi luulivat, niin he ovat tyhmiksi tulleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 23, 'Ja ovat katoomattoman Jumalan kunnian muuttaneet katoovaisen ihmisen ja lintuin ja neljäjalkaisten ja matelevaisten kuvan muotoiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 24, 'Sentähden on myös Jumala heidät laskenut sydämensä himoihin, saastauteen, häpäisemään keskenänsä omaa ruumistansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 25, 'Jotka Jumalan totuuden ovat valheeksi muuttaneet ja ovat kunnioittaneet ja palvelleet enemmän luontokappaletta kuin Luojaa, joka on siunattu ijankaikkisesti, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 26, 'Sentähden on Jumala heidät antanut ylön häpiällisiin himoihin, että myös heidän vaimonsa ovat muuttaneet luonnollisen tavan luontoa vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 27, 'Niin myös miehet ovat antaneet ylön vaimon luonnollisen pitämisen, toinen toisensa puoleen himoissansa palaneet, miehet miesten kanssa riettauden tehneet ja saaneet, niinkuin pitikin, eksymisensä palkan itsessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 28, 'Ja niinkuin ei he tahtoneet Jumalaa tuta, niin Jumala laski heidät häijyyn mieleen tekemään niitä, mitä ei sovi tehdä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 29, 'Täynnänsä kaikkea vääryyttä, salavuoteutta, koiruutta, ahneutta, pahuutta: täynnä kateutta, murhaa, riitaa, petosta, pahan suomuutta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 30, 'Korvankuiskutteliat, panetteliat, Jumalaa vihaajat, häpäisiät, ylpiät öykkärit, pahain neuvoin pesät, vanhemmillensa tottelemattomat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 31, 'Tomppelit, liiton rikkojat, haluttomat, sovittamattomat, armottomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 32, 'Jotka Jumalan oikeuden tietävät, (että ne, jotka näitä tekevät, ovat kuoleman ansainneet) ei ainoastaan niitä tee, mutta myös suostuvat niihin, jotka niitä tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Sentähden, oi ihminen, et sinä taida itsiäs syyttömäksi tehdä, vaikka kuka sinä olet, joka tuomitset; sillä jossa sinä toista tuomitset, siinä sinä itses tuomitset, ettäs niitä teet, joita sinä tuomitset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Mutta me tiedämme, että Jumalan tuomio on oikia niiden ylitse, jotka senkaltaisia tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Eli luuletkos, ihminen, sinä joka niitä tuomitset, jotka senkaltaisia tekevät, ja itse myös niitä teet, että sinä vältät Jumalan tuomion?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Eli katsotkos ylön hänen hyvyytensä, kärsiväisyytensä ja pitkämielisyytensä rikkauden, ettet tiedä, että Jumalan hyvyys vetää sinua parannukseen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Mutta kovuutes ja katumattoman sydämes jälkeen kartutat sinä vihan itselles vihan päivänä, kuin Jumalan oikia tuomio ilmaantuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Joka antaa itsekullekin hänen töittensä jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Niille, jotka pyytävät ylistystä, kunniaa ja katoomatointa menoa kärsiväisyydellä hyvissä töissä, ijankaikkisen elämän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Mutta niille, jotka riitaiset ovat, eikä kuule totuutta, vaan kuulevat vääryyttä, on tuleva närkästys ja viha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Murhe ja vaiva kunkin ihmisen sielun päälle, joka pahaa tekee, ensisti Juudalaisen, niin myös Grekiläisen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Mutta ylistys, kunnia ja rauha jokaiselle, joka hyvää tekee, ensisti Juudalaiselle, niin myös Grekiläiselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Sillä ei Jumala katso ihmisen muodon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Kaikki, jotka ilman lakia ovat syntiä tehneet, niiden pitää myös ilman lakia hukkuman, ja kaikki, jotka laissa ovat syntiä tehneet, ne pitää lain kautta tuomittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Sillä ei ne ole Jumalan edessä vanhurskaat, jotka lain kuulevat; mutta ne, jotka lain töillänsä täyttävät, ne pitää vanhurskaaksi tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Sillä koska pakanat, joilla ei lakia ole, tekevät luonnostansa sitä, mitä laki anoo, niin he, vaikka ei heillä lakia ole, ovat itsellensä laki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Että he osoittavat lain työn olevan kirjoitetun sydämiinsä, ja niin heidän omatuntonsa ynnä todistaa, ja heidän ajatuksensa keskenänsä itse päällensä kantavat eli myös heitänsä syyttömäksi tekevät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Sinä päivänä, jona Jumala ihmisten salaisuudet on tuomitseva, minun evankeliumini perästä Jesuksen Kristuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Katso, sinä kutsutaan Juudalaiseksi, ja sinä luotat lakiin ja kerskaat Jumalasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Ja tiedät hänen tahtonsa, ja että sinä olet laista neuvottu, niin sinä koettelet ne parhaat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Ja luulet itses sokiain johdattajaksi ja niiden valkeudeksi, jotka pimeydessä ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Ja tyhmäin kurittajaksi, ja lasten opettajaksi, ja sinullas olevan tunnon ja totuuden muodon laissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Sinä joka siis opetat toista ja et itsiäs opeta; joka saarnaat: ei pidä varastaman, ja sinä itse varastat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Joka sanot: ei pidä huorin tehtämän, ja sinä itse teet huorin; joka kauhistut epäjumalia, ja raatelet sitä Jumalalta, mikä hänelle tulee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Joka kerskaat laista ja häpäiset Jumalaa lain ylitsekäymisellä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Sillä teidän tähtenne tulee Jumalan nimi pilkatuksi pakanain seassa, niinkuin kirjoitettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Sillä ympärileikkaus kelpaa, jos sinä lain pidät; mutta jos sinä olet lain rikkoja, niin sinun ympärileikkaukses on esinahaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Jos siis esinahka lain oikeuden pitää, eikö hänen esinahkansa pidä luettaman hänelle ympärileikkaukseksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Ja se joka luonnostansa esinahka on ja täyttää lain, pitää sinun tuomitseman, joka puustavin ja ympärileikkauksen lain käyt ylitse?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Sillä ei se ole Juudalainen, joka ulkonaisesti (Juudalainen) on: ei myös se ole ympärileikkaus, mikä ulkonaisessa lihassa tapahtuu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Mutta se on Juudalainen, joka sisällisesti salattu on, ja sydämen ympärileikkaus on ympärileikkaus, joka hengessä tapahtuu, ei puustavissa; jonka ylistys ei ole ihmisiltä, vaan Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Mitäs siis Juudalainen on parempi? Eli mitä ympärileikkaus auttaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Tosin sangen paljo. Sillä ensin on se, että heille on uskottu, mitä Jumala puhunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Mutta ettei muutamat niitä uskoneet, mikä siitä on? Pitäiskö heidän epäuskonsa Jumalan uskon turhaksi tekemän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Pois se! vaan paremmin, olkoon Jumala totinen, vaan jokainen ihminen valehtelia, niinkuin kirjoitettu on: ettäs olisit oikia sanoissas ja voittaisit, kuin sinä tuomitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Jos siis meidän vääryytemme Jumalan oikeutta ylistää, mitäs me sanomme? Onko Jumala väärä, että hän siitä vihastuu? (minä puhun ihmisten tavalla.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Pois se! kuinka Jumala sitte taitais maailmaa tuomita?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Sillä jos Jumalan totuus minun valheeni kautta kunniallisemmaksi tulis, hänen ylistykseksensä, minkätahden pitäis vielä sitte minä niinkuin syntinen tuomittaman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Ja ei, (niinkuin meitä pilkataan ja niinkuin muutamat puhuvat meidän sanovan,) että meidän pitäis tekemän pahaa, että siitä hyvää tulis? Joiden kadotus on oikia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Mitäs siis? Olemmeko me paremmat kuin he? Emme ensinkään; sillä me olemme ennen osoittaneet, että sekä Juudalaiset ja Grekiläiset ovat kaikki synnin alla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Niinkuin kirjoitettu on: ei ole kenkään vanhurskas, ei yksikään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Ei ole yhtäkään ymmärtäväistä, ei ole ketään, joka etsii Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Kaikki ovat poikenneet pois ja ynnä kelvottomaksi tulleet: ei ole yhtään, joka hyvää tekee, ei yhtäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Heidän kurkkunsa on avoin hauta, kielellänsä he pettävät, kyykäärmeen myrkky on heidän huultensa alla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Joiden suu on täynnänsä kirousta ja haikeutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Heidän jalkansa ovat nopiat verta vuodattamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Heidän teissänsä on sula tuska ja sydämen kipu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Ja ei he rauhan tietä tunteneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Ei ole Jumalan pelko heidän silmäinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Mutta sen me tiedämme, että kaikki, mitä laki sanoo, sen hän sanoo niille, jotka lain alla ovat: että jokainen suu pitää tukittaman ja kaiken maailman pitää Jumalan edessä vikapää oleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Sentähden ettei yksikään liha taida lain töiden kautta hänen edessänsä vanhurskautetuksi tulla; sillä lain kautta synnin tunto tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mutta nyt on se vanhurskaus, joka Jumalan edessä kelpaa, ilman lakia julistettu, lain ja prophetain kautta todistettu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'Se Jumalan vanhurskaus, (sanon minä), joka tulee Jesuksen Kristuksen uskon kautta, kaikkein tykö ja kaikkein päälle, jotka uskovat: sillä ei ole yhtään eroitusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Sillä kaikki ovat he syntiä tehneet ja ei heillä ole mitään kerskattavaa Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'He tulevat ilman ansiotansa vanhurskaaksi, hänen armostansa, sen lunastuksen kautta, joka on Jesuksessa Kristuksessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 25, 'Jonka Jumala on armonistuimeksi asettanut, uskon kautta hänen veressänsä, osoittaaksensa sitä vanhurskautta, joka hänen edessänsä kelpaa, edelläkäyväisten syntein anteeksi antamisen kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 26, 'Joita Jumala kärsinyt on, osoittaaksensa vanhurskauttansa tällä ajalla: että hän itse vanhurskas olis ja sen vanhurskaaksi tekis, joka Jesuksen uskosta on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 27, 'Kussa siis on kerskaus? Se on suljettu ulos. Minkä lain kautta? Töidenkö lain kautta? Ei, vaan uskon lain kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 28, 'Niin me siis sen siksi pidämme, että ihminen tulee vanhurskaaksi uskon kautta, ilman lain töitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 29, 'Eli onko Jumala ainoastaan Juudalaisten Jumala? eikö hän ole myös pakanain Jumala? Tosin pakanainkin Jumala,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 30, 'Että yksi on Jumala, joka ympärileikkauksen tekee vanhurskaaksi uskosta, ja esinahan uskon kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 31, 'Teemmekö me lain tyhjäksi uskon kautta? Pois se; vaan me vahvistamme lain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mitäs me siis sanomme meidän isämme Abrahamin lihan puolesta löytäneen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Sillä jos Abraham on töiden kautta vanhurskaaksi tullut, niin hänellä on kerskaamista, vaan ei Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Mutta mitä Raamattu sano: Abraham uskoi Jumalan, ja se luettiin hänelle vanhurskaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Mutta sille, joka työtä tekee, ei lueta palkkaa armosta, vaan ansiosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Mutta joka ei työtä tee, vaan uskoo sen päälle, joka jumalattoman vanhurskaaksi tekee, hänen uskonsa luetaan hänelle vanhurskaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Niinkuin myös David sanoo: autuus on sen ihmisen, jolle Jumala vanhurskauden lukee ilman töitä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Autuaat ovat ne, joidenka vääryydet ovat anteeksi annetut, ja joidenka synnit peitetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Autuas on se mies, jolle Jumala ei syntiä lue.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Lieneekö siis tämä autuus ainoastaan ympärileikkaukselle tullut, elikkä myös esinahalle? Niinpä me sanomme: Abrahamille luettiin usko vanhurskaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Kuinkas se hänelle luettiin: koska hän oli ympärileikkauksessa, eli esinahassa? Ei ympärileikkauksessa, vaan esinahassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Ja hän sai ympärileikkauksen merkin vahvistukseksi, että hän oli uskon kautta vanhurskaaksi tehty, joka hänellä esinahassa oli, että hänen piti oleman kaikkein uskovaisten isä esinahassa, että se niillekin vanhurskaudeksi luettaisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Ja hän tulis myös ympärileikkauksen isäksi, ei ainoasti niiden, jotka ympärileikatuista syntyneet ovat, mutta myös niiden, jotka sen uskon jälkiä vaeltavat, joka meidän isän Abrahamin esinahassa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Sillä se lupaus, että hänen piti maailman perilliseksi tuleman, ei ole Abrahamille eikä hänen siemenellensä lain kautta tapahtunut, vaan uskon vanhurskauden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Sillä jos ne, jotka laista ovat, ovat perilliset, niin usko on turha ja lupaus on hukkaan tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Sillä laki kehoittaa vihan; sillä kussa ei lakia ole, ei siellä ole myös ylitsekäymistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Sentähden tulee se uskosta, että sen pitää armosta oleman: että se lupaus pitää vahva oleman kaikelle siemenelle, ei sille ainoastaan, joka lain alla on, mutta myös sille, joka Abrahamin uskosta on, joka on meidän kaikkein isämme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, '(Niinkuin kirjoitettu on: minä asetin sinun monen pakanan isäksi) Jumalan edessä, jonka hän uskonut on, joka kuolleet eläväksi tekee ja kutsuu ne, jotka ei ole, niinkuin ne olisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Ja hän uskoo sen toivon, jossa ei toivoa ollut, että hänen piti oleman monen pakanan isän, sen jälkeen kuin hänelle sanottu oli: niin pitää sinun siemenes oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Ja ei hän tullut heikoksi uskossa eikä katsonut kuollutta ruumistansa, ehkä hän jo lähes sadan ajastajan vanha oli, eikä Saaran kuollutta kohtua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Mutta ei hän epäillyt ensinkään Jumalan lupauksesta epäuskolla, vaan oli vahva uskossa ja antoi Jumalalle kunnian,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Ja oli täydellisesti vahva siitä, että mitä Jumala lupaa, sen hän myös voi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 22, 'Sentähden se on myös hänelle vanhurskaudeksi luettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 23, 'Niin ei se ole ainoastaan hänen tähtensä kirjoitettu, että se hänelle luettu oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 24, 'Vaan myös meidän tähtemme, joille se myös pitää luettaman, kuin me sen päälle uskomme, joka meidän Herran Jesuksen kuolleista herätti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 25, 'Joka meidän synteimme tähden on annettu ulos, ja meidän vanhurskauttamisemme tähden herätetty ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Että me siis olemme uskosta vanhurskaiksi tulleet, niin meillä on rauha Jumalan kanssa meidän Herran Jesuksen Kristuksen kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Jonka kautta myös meillä oli tykökäymys uskossa tähän armoon, jossa me seisomme ja kerskaamme Jumalan kunnian toivosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Mutta ei ainoasti siitä, vaan me kerskaamme myös vaivoissa; sillä me tiedämme, että vaiva saattaa kärsivällisyyden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Mutta kärsivällisyys koettelemuksen, koettelemus toivon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Mutta toivo ei anna häpiään tulla, että Jumalan rakkaus on vuodatettu meidän sydämiimme Pyhän Hengen kautta, joka meille annettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Sillä Kristus, kuin me vielä heikot olimme, on ajallansa jumalattomain edestä kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Tuskalla nyt joku kuolis vanhurskaan edestä, ehkä hyvän edestä mitämaks joku tohtis kuolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Mutta Jumala ylistää rakkauttansa meidän kohtaamme, että kuin me vielä syntiset olimme, on Kristus meidän edestämme kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Niin me siis paljoa enemmin varjellaan hänen kauttansa vihan edestä, että me nyt hänen verensä kautta vanhurskaiksi tulleet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Sillä jos me Jumalan kanssa olimme sovitetut hänen Poikansa kuoleman kautta, kuin me vielä hänen vihollisensa olimme, paljoa ennemmin me autuaiksi tulemme hänen elämänsä kautta, että me sovitetut olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Mutta ei ainoasti siitä, vaan me kerskaamme myös Jumalasta, meidän Herran Jesuksen Kristuksen kautta, jonka kautta me nyt olemme sovinnon saaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Sentähden, niinkuin yhden ihmisen kautta on synti maailmaan tullut ja synnin kautta kuolema, niin on kuolema tullut kaikkein ihmisten päälle, että kaikki ovat syntiä tehneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Sillä lakiin asti oli synti maailmassa; mutta kussa ei lakia ole, ei siellä syntiä lueta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Vaan kuolema vallitsi Adamista Mosekseen asti niitäkin, jotka ei syntiä tehneet olleet senkaltaisella ylitsekäymisellä kuin Adam, joka on sen esikuva, joka jälkeen tuleva oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Mutta ei niin lahjan kanssa ole kuin synnin; sillä jos monta ovat sen yhden synnin tähden kuolleet, niin on paljoa enemmin Jumalan armo ja lahja sen yhden ihmisen Jesuksen Kristuksen armossa monen päälle runsaasti tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Ja ei niinkuin (se tuli) yhden kautta, joka syntiä teki, niin myös lahja; sillä tuomio on tosin yhdestä kadotukseen, mutta lahja monesta synnistä vanhurskauteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Sillä jos kuolema on yhden synnin tähden vallinnut sen yhden kautta, paljoa enemmin ne, jotka saavat armon ja vanhurskauden lahjan yltäkylläisyyden, pitää vallitsemassa elämässä yhden Jesuksen Kristuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Niinkuin siis yhden synnin kautta on kadotus tullut kaikkein ihmisten päälle, niin on myös yhden vanhurskauden kautta elämän vanhurskaus tullut kaikkein ihmisten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Sillä niinkuin yhden ihmisen kuulemattomuuden tähden monta ovat syntisiksi tulleet, niin myös monta tulevat yhden kuuliaisuuden tähden vanhurskaiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Mutta laki on myös tähän tullut, että synti suuremmaksi tuttaisiin; mutta kussa synti on suureksi tuttu, siinä on armo ylönpalttiseksi tuttu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Että niinkuin synti on vallinnut kuolemaan, niin myös armo on vallitseva vanhurskauden kautta ijankaikkiseen elämään, Jesuksen Kristuksen meidän Herramme kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 1, 'Mitäs siis meidän pitää sanoman? Pitääkö meidän vielä synnissä oleman, että armo suuremmaksi tulis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 2, 'Pois se! Me, jotka synnille kuolleet olemme, kuinkas meidän vielä pitäis siinä elämän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 3, 'Ettekö te tiedä, että me kaikki, jotka olemme Jesuksessa Kristuksessa kastetut, me olemme hänen kuolemaansa kastetut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 4, 'Niin me olemme siis hänen kanssansa haudatut kasteen kautta kuolemaan: että niinkuin Kristus on kuolleista Isän kunnian kautta herätetty, niin pitää meidänkin uudessa elämässä vaeltaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 5, 'Sillä jos me ynnä hänen kanssansa olemme istutetut yhdenkaltaiseen kuolemaan, niin me myös tulemme yhdenkaltaiseksi ylösnousemisessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 6, 'Tietäen sen, että meidän vanha ihminen on ristiinnaulittu hänen kanssansa, että synnin ruumis pitää turmeltaman, ettemme tästedes syntiä palvelisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 7, 'Sillä se, joka kuollut on, hän on synnistä vanhurskaaksi tehty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 8, 'Mutta jos me olemme Kristuksen kanssa kuolleet, niin me uskomme, että me saamme myös elää hänen kanssansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 9, 'Ja tiedämme, ettei Kristus, joka kuolleista herätetty on, silleen kuole, eikä kuolema saa tästedes hänen päällensä valtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 10, 'Sillä sen, kuin hän kuollut on, sen hän synnille kuoli yhden kerran; vaan sen, kuin hän elää, sen hän elää Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 11, 'Niin myös te siksi teitänne pitäkäät, että te olette kuolleet synnille, mutta elätte Jumalalle, Jesuksen Kristuksen meidän Herran kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 12, 'Niin älkäät salliko synnin vallita kuolevaisessa ruumiissanne, niin että te häntä kuulisitte hänen himoissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 13, 'Ja älkäät antako teidän jäseniänne vääryyden sota-aseiksi synnille, mutta antakaat teitänne Jumalalle, niinkuin kuolleista eläviksi tulleet, ja teidän jäsenenne Jumalalle vanhurskauden sota-aseiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 14, 'Sillä ei synnin pidä teitä vallitseman, ettette ole lain, vaan armon alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 15, 'Kuinkas siis? Pitääkö meidän syntiä tekemän, ettemme lain alla ole, vaan armon? Pois se!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 16, 'Ettekö te tiedä, että jolle te annatte itsenne palvelioiksi kuulemaan, sen palveliat te olette, jolle te kuuliaiset olette, taikka synnille kuolemaksi eli kuuliaisuudelle vanhurskaudeksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 17, 'Mutta Jumalan olkoon kiitos, että olitte synnin palveliat, mutta nyt te olette sydämestänne kuuliaiset sen opin esikuvalle, johonka te annetut olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 18, 'Ja että te olette vapahdetut synnistä, niin te olette vanhurskauden palvelioiksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 19, 'Minä puhun ihmisten tavalla, teidän lihanne heikkouden tähden. Sillä niinkuin te ennen annoitte jäsenenne saastaisuutta ja vääryyttä palvelemaan vääryyteen, niin antakaat nyt jäsenenne vanhurskautta palvelemaan pyhitykseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 20, 'Sillä koska te olitte synnin palveliat, niin te olitte vapaat vanhurskaudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 21, 'Mitä hedelmää siis teidän silloin niistä oli, joita te nyt häpeätte? Sillä niiden loppu on kuolema.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 22, 'Mutte että te nyt olette synnistä vapautetut ja Jumalan palvelioiksi tulleet, niin teillä on teidän hedelmänne pyhyyteen, mutta lopuksi ijankaikkinen elämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 23, 'Sillä kuolema on synnin palkka, mutta ijankaikkinen elämä on Jumalan lahja Jesuksessa Kristuksessa meidän Herrassamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 1, 'Ettekö te tiedä, rakkaat veljet, (sillä minä puhun lain taitaville) että laki vallitsee ihmistä niinkauvan kuin hän elää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 2, 'Sillä vaimo, joka miehen hallussa on, niinkauvan kuin mies elää, on häneen lailla sidottu, mutta jos mies kuolee, niin hän on miehen laista vapaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 3, 'Sentähden jos hän toisen miehen kanssa on miehensä eläissä, niin hän huoraksi kutsutaan; mutta jos mies kuolee, niin hän on laista vapaa, ettei hän huoraksi tule, jos hän toisen miehen kanssa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 4, 'Niin olette te myös, minun veljeni, laille kuoletetut Kristuksen ruumiin kautta, että teidän pitää toisen kanssa oleman, joka on noussut kuolleista, että me Jumalalle hedelmän kantaisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 5, 'Sillä kuin me lihassa olimme, niin ne syntein himot, jotka lain kautta olivat meidän jäsenissämme, vaikuttivat kuolemalle hedelmää saattamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 6, 'Mutta nyt me olemme laista vapahdetut ja hänelle kuolleet, jossa me pidettiin kiinni: että me palvelisimme hengen uudistuksessa ja ei puustavin vanhuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 7, 'Mitäs me siis sanomme? Onko laki synti? Pois se! Mutta en minä muutoin syntiä olisi tuntenut, ellei lain kautta; sillä en minä olisi himoistakaan mitään tiennyt, ellei laki olisi sanonut: ei sinun pidä himoitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 8, 'Mutta synti otti tilan käskystä ja kehoitti minussa kaikkinaisen himon; sillä ilman lakia oli synti kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 9, 'Mutta minä elin muinen ilman lakia. Kuin siis käsky tuli, niin synti taas virkosi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 10, 'Ja minä kuolin: ja niin löydettiin, että käsky, joka minulle oli elämäksi, tuli minulle kuolemaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 11, 'Sillä synti, joka otti tilan käskystä, petti minun ja tappoi sen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 12, 'Laki on kuitenkin itsestänsä pyhä ja käsky on myös pyhä, oikia ja hyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 13, 'Onko siis se, mikä hyvä on, minulle kuolemaksi tullut? Pois se! Mutta että synti synniksi nähtäisiin, on hän minulle hyvän kautta kuoleman saattanut, että synti ylitse määrän synniksi tulis, käskyn kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 14, 'Sillä me tiedämme, että laki on hengellinen: vaan minä olen lihallinen, synnin alle myyty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 15, 'Sillä en minä tiedä, mitä minä teen, etten minä tee sitä, mitä minä tahdon, vaan sitä, mitä minä vihaan, teen minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 16, 'Mutta jos minä teen, jota en minä tahdo, niin minä suostun lakiin, että se on hyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 17, 'Niin en minä sitä enää tee, vaan synti, joka minussa asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 18, 'Sillä minä tiedän, ettei minussa (se on: minun lihassani) mitään hyvää asu. Sillä tahto minulla on, vaan täyttää hyvää, en minä sitä löydä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 19, 'Sillä hyvää, jota minä tahdon, en minä tee, vaan pahaa, jota en minä tahdo, teen minä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 20, 'Mutta jos minä teen, jota en minä tahdo, niin en minä sitä enää tee, vaan synti, joka minussa asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 21, 'Niin minä löydän itsessäni lain, joka tahtoo hyvää tehdä, että minussa pahuus riippuu kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 22, 'Sillä minulla on halu Jumalan lakiin, sisällisen ihmisen puolesta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 23, 'Mutta minä näen toisen lain minun jäsenissäni, joka sotii minun mieleni lakia vastaan ja ottaa minun vangiksi synnin laissa, joka minun jäsenissäni on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 24, 'Minä viheliäinen ihminen: kuka päästää minun tästä kuoleman ruumiista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 25, 'Minä kiitän Jumalaa Jesuksen Kristuksen meidän Herramme kautta. Niin minä itse palvelen nyt mielellä Jumalan lakia, mutta lihalla synnin lakia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 1, 'Niin ei ole nyt yhtään kadotusta niissä, jotka Jesuksessa Kristuksessa ovat, ja ei vaella lihan, vaan hengen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 2, 'Sillä hengen laki, joka eläväksi tekee Kristuksessa Jesuksessa, on minun synnin ja kuoleman laista vapahtanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 3, 'Sillä se, mikä laille oli mahdotoin, että hän lihan kautta oli heikoksi tullut, sen Jumala teki, ja lähetti Poikansa syntisen lihan hahmossa ja tuomitsi synnin lihassa, synnin kautta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 4, 'Että lain vanhurskaus täytetyksi tulis meissä, jotka emme lihan jälkeen vaella, vaan hengen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 5, 'Sillä ne, jotka lihan jälkeen ovat, ajattelevat niitä, mitkä lihan ovat; mutta ne, jotka hengen jälkeen ovat, ajattelevat hengellisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 6, 'Sillä lihan halu on kuolema, ja hengen halu on elämä ja rauha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 7, 'Että lihan halu on viha Jumalaa vastaan, ettei se ole Jumalan laille kuuliainen, sillä ei se voikaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 8, 'Mutta jotka lihassa ovat, ei ne taida olla Jumalalle otolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 9, 'Mutta ette ole lihassa, vaan hengessä, jos muutoin Jumalan Henki asuu teissä; mutta jolla ei ole Kristuksen Henkeä, ei se ole hänen omansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 10, 'Jos siis Kristus teissä on, niin ruumis tosin on kuollut synnin tähden, mutta henki on elämä vanhurskauden tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 11, 'Jos nyt sen Henki, joka Jesuksen kuolleista herätti, asuu teissä, niin myös se, joka Kristuksen kuolleista herätti, on teidän kuolevaiset ruumiinne eläväksi tekevä, sen teissä asuvaisen hengen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 12, 'Niin emme nyt ole, rakkaat veljet, velkapäät lihalle, lihan jälkeen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 13, 'Sillä jos te lihan jälkeen elätte, niin teidän pitää kuoleman; mutta jos te lihan työt hengen kautta kuoletatte, niin te saatte elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 14, 'Sillä kaikki, jotka Jumalan Hengeltä vaikutetaan, ne ovat Jumalan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 15, 'Sillä ette ole saaneet orjuuden henkeä, että teidän vielä pitäis pelkäämän, mutta te olette saaneet valittuin lasten hengen, jossa me huudamme: Abba, rakas Isä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 16, 'Se Henki todistaa meidän henkemme kanssa, että me olemme Jumalan lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 17, 'Jos me olemme lapset, niin me olemme myös perilliset, nimittäin Jumalan perilliset ja Kristuksen kanssaperilliset: jos me muutoin ynnä kärsimme, että me ynnä hänen kanssansa kunniaan tulisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 18, 'Sillä siksi minä sen pidän, ettei tämän nykyisen ajan vaivat ole sen kunnian vertaa, joka meille ilmoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 19, 'Sillä ikävä luontokappaleen ikävöitsemys odottaa Jumalan lasten ilmoitusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 20, 'Että luontokappale on turmeluksen alle annettu, ei mielellänsä, vaan sentähden, joka ne alle antanut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 21, 'Toivossa, että myös itse luontokappale pitää turmeluksen orjuudesta vapaaksi tuleman, Jumalan lasten kunnian vapauteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 22, 'Sillä me tiedämme, että jokainen luontokappale huokaa ja ahdistetaan aina tähän asti meidän kanssamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 23, 'Mutta ei ainoastaan ne, vaan myös itse me, joilla hengen uutiset ovat, huokaamme itsellämme, odottain sitä lapseksi ottamista, meidän ruumiimme lunastusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 24, 'Sillä me olemme toivossa vapahdetut. Mutta jos toivo näkyy, niin ei se ole toivo; sillä kuinka joku taitaa toivoa jota hän näkee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 25, 'Mutta jos me sitä toivomme, jota emme näe, niin me odotamme sitä kärsivällisyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 26, 'Mutta niin myös Henki auttaa meidän heikkouttamme; sillä emmepä me tiedä mitään rukoilla niinkuin tulis, vaan Henki rukoilee meidän edestämme sanomattomilla huokauksilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 27, 'Mutta joka sydämet tutkii, hän tietää, mitä Hengen mielessä on; sillä hän rukoilee pyhäin edestä Jumalan tahdon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 28, 'Mutta me tiedämme niille, jotka Jumalaa rakastavat, kaikki kappaleet ynnä parhaaksi kääntyvän, niille, jotka aivoituksen jälkeen kutsutut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 29, 'Sillä jotka hän on katsonut edes, ne hän on Poikansa kuvan kaltaiseksi säätänyt, että hän olis esikoinen monen veljen keskellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 30, 'Mutta jotka hän on säätänyt, ne hän on myös kutsunut, ja jotka hän kutsunut on, ne hän on myös vanhurskaiksi tehnyt, ja jotka hän vanhurskaiksi teki, ne hän on myös kunniallisiksi tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 31, 'Mitäs me siis näihin sanomme? Jos Jumala on meidän edestämme, kuka voi meitä vastaan olla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 32, 'Joka ei omaakaan Poikaansa armahtanut, vaan antoi hänen kaikkein meidän edestämme, eikös hän myös lahjoita meille kaikkia hänen kanssansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 33, 'Kuka tahtoo Jumalan valittuin päälle kantaa? Jumala on, joka tekee vanhurskaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 34, 'Kuka on, joka tahtoo kadottaa? Kristus on kuollut. Ja, hän on myös herätetty ylös, on myös Jumalan oikialla kädellä, joka myös rukoilee meidän edestämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 35, 'Kuka pitää meitä Kristuksen rakkaudesta eroittaman? vaivako, eli ahdistus, eli vaino, eli nälkä, eli alastomuus, eli hätä, eli miekka?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 36, 'Niinkuin kirjoitettu on: sinun tähtes me kuoletetaan yli päivää: me pidetään niinkuin teurastettavat lampaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 37, 'Mutta niissä kaikissa me voitamme hänen kauttansa, joka meitä on rakastanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 38, 'Sillä minä olen vahva siitä, ettei kuolema, eikä elämä, eikä enkelit, eikä esivallat, eikä väkevyydet, eikä nykyiset, eikä tulevaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 39, 'Eikä korkeus, eikä syvyys, eli joku muu luontokappale taida meitä Jumalan rakkaudesta eroittaa, joka on Jesuksessa Kristuksessa, meidän Herrassamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 1, 'Minä sanon totuuden Kristuksessa ja en valehtele, (niinkuin minun omatuntoni minun kanssani Pyhässä Hengessä todistaa,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 2, 'Että minulla on suuri murhe ja alinomainen kipu sydämessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 3, 'Minä olen pyytänyt kirottuna olla Kristukselta minun veljieni tähden, jotka lihan puolesta minun lankoni ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 4, 'Jotka ovat Israelilaiset, joiden on lasten oikeus ja kunnia, ja liitot ja laki, ja jumalanpalvelus ja lupaukset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 5, 'Joiden myös isät ovat, joista Kristus lihan puolesta syntynyt on, joka on Jumala ylitse kaikkein ylistetty ijankaikkisesti, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 6, 'Mutta ei niin, että Jumalan sana on hukkunut; sillä ei ne ole kaikki Israelilaiset, jotka Israelista ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 7, 'Ei myös ne ole kaikki lapset, jotka Abrahamin siemen ovat; vaan Isakissa pitää sinulle siemen kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 8, 'Se on: ei ne ole Jumalan lapset, jotka lihan puolesta lapset ovat; mutta ne, jotka lupauksen lapset ovat, ne siemeneksi luetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 9, 'Sillä tämä on lupauksen sana: tällä ajalla minä tulen ja Saaralla pitää poika oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 10, 'Mutta ei se ainoastaan, mutta myös Rebekka siitti yhdestä Isaakista meidän isästämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 11, 'Sillä ennen kuin lapset syntyivätkään ja kuin ei he vielä hyvää eikä pahaa tehneet olleet, että Jumalan aivoitus pitäis valitsemisen jälkeen seisovainen oleman, ei töiden tähden, vaan kutsujan armosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 12, 'Sanottiin hänelle: suuremman pitää vähempää palveleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 13, 'Niinkuin kirjoitettu on: Jakobia minä rakastin, mutta Esauta vihasin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 14, 'Mitäs me siis sanomme? Onko Jumalan tykönä vääryyttä? Pois se!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 15, 'Sillä hän sanoo Mosekselle: jota minä armahdan, sitä minä tahdon armahtaa, ja tahdon olla laupias, jolle minä laupias olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 16, 'Niin ei se nyt ole sen, joka tahtoo, eikä sen, joka juoksee, vaan sen, joka armahtaa, nimittäin Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 17, 'Sillä Raamattu sanoo Pharaolle: juuri sentähden olen minä sinun herättänyt, osoittaakseni minun voimani sinussa, että minun nimeni kaikessa maassa julistettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 18, 'Niin hän siis armahtaa, ketä hän tahtoo, ja paaduttaa, kenenkä hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 19, 'Niin sinä sanot minulle: mitä hän siis nuhtelee? sillä kuka taitaa hänen tahtoansa vastaan olla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 20, 'Ja tosin, oi ihminen, kuka sinä olet, joka Jumalaa vastaan riitelet? Sanooko työ tekiällensä: miksis minut tainkaltaiseksi tehnyt olet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 21, 'Eli eikö savenvalajalla ole saven päälle valtaa, yhdestä kappaleesta tehdä yhtä astiaa kunnialliseksi ja toista huonoksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 22, 'Sentähden, jos Jumala tahtoo vihansa osoittaa ja voimansa ilmoittaa, on hän suurella kärsivällisyydellä kärsinyt vihansa astioita, jotka ovat kadotukseen valmistetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 23, 'Ja että hän tiettäväksi tekis kunniansa rikkauden laupiutensa astioille, jotka hän kunniaan on valmistanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 24, 'Jotka hän myös kutsunut on, nimittäin meitä, ei ainoasti Juudalaisista, vaan myös pakanoista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 25, 'Niinkuin hän myös Hosean kautta sanoo: minä tahdon kutsua sen minun kansakseni, joka ei ollut minun kansani, ja minun rakkaakseni, joka ei minun rakkaani ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 26, 'Ja pitää tapahtuman, että siinä paikassa, missä heille sanottiin: ette ole minun kansani, siellä pitää heitä elävän Jumalan lapsiksi kutsuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 27, 'Mutta Jesaias huutaa Israelin edestä: jos Israelin lasten luku olis niinkuin santa meressä, niin kuitenkin tähteet autuaaksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 28, 'Sillä kuluttamus ja lyhentämys pitää tapahtuman vanhurskaudeksi, että Herra tekee hävityksen maan päällä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 29, 'Ja niinkuin Jesaias ennen sanoi: ellei Herra Zebaot olisi meille siementä jättänyt, niin me olisimme olleet kuin Sodoma ja senkaltaiset kuin Gomorra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 30, 'Mitäs me siis sanomme? (Me sanomme:) pakanat, jotka ei ole vanhurskautta etsineet, ovat saaneet vanhurskauden, mutta sen vanhurskauden, joka uskosta on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 31, 'Mutta Israel, joka vanhurskauden lakia on etsinyt, ei ole vanhurskauden lakia saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 32, 'Minkätähden? Ettei he sitä uskosta, mutta niinkuin lain töistä etsivät. Sillä he ovat loukanneet itsensä loukkauskiveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 33, 'Niinkuin kirjoitettu on: katso, minä panen Zioniin loukkauskiven ja pahennuksen kallion, ja jokainen, joka hänen päällensä uskoo, ei pidä häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 1, 'Veljet, minun sydämeni halu ja rukous on Jumalan tykö Israelin edestä, että he autuaaksi tulisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 2, 'Sillä minä annan heille todistuksen, että heillä on kiivaus Jumalan puoleen, mutta ei taidon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 3, 'Sillä ei he ymmärrä Jumalan vanhurskautta, vaan pyytävät omaa vanhurskauttansa vahvistaa, eikä ole Jumalan vanhurskaudelle kuuliaiset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 4, 'Sillä Kristus on lain loppu, jokaiselle uskovaiselle vanhurskaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 5, 'Sillä Moses kirjoittaa siitä vanhurskaudesta, joka laista on, että kuka ihminen ne tekee, hänen pitää niissä elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 6, 'Mutta se vanhurskaus, joka uskosta on, sanoo näin: älä sano sydämessäs: kuka tahtoo astua ylös taivaasen? se on Kristusta tänne tuoda alas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 7, 'Eli kuka tahtoo astua alas syvyyteen: se on: Kristusta kuolleista jälleen tuoda?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 8, 'Vaan mitä hän sanoo? Se sana on juuri sinun tykönäs, nimittäin sinun suussas ja sydämessäs. Tämä on se sana uskosta, jota me saarnaamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 9, 'Sillä, jos sinä suullas tunnustat Herran Jesuksen ja uskot sydämessäs, että Jumala on hänet kuolleista herättänyt, niin sinä tulet autuaaksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 10, 'Sillä sydämen uskolla me vanhurskaaksi tulemme, ja suun tunnustuksella me autuaaksi tulemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 11, 'Sillä Raamattu sanoo: jokainen, joka uskoo hänen päällensä, ei pidä häpiään tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 12, 'Ei ole yhtään eroitusta Juudalaisen ja Grekiläisen välillä; sillä yksi on kaikkein Herra, rikas kaikkein kohtaan, jotka häntä rukoilevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 13, 'Sillä jokainen, joka Herran nimeä avuksensa huutaa, tulee autuaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 14, 'Mutta kuinka he sitä avuksensa huutavat, jonka päälle ei he uskoneet? Ja kuinka he sen uskovat, josta ei he ole kuulleet? Mutta kuinka he kuulevat ilman saarnaajaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 15, 'Ja kuinka he saarnaavat, ellei heitä lähetetä? Niinkuin kirjoitettu on: oi kuinka suloiset ovat niiden jalat, jotka rauhaa julistavat, niiden jotka hyvää julistavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 16, 'Mutta ei he ole kaikki evankeliumille kuuliaiset; sillä Jesaias sanoo: Herra, kuka uskoo meidän saarnamme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 17, 'Niin tulee siis usko kuulosta, mutta kuulo Jumalan sanan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 18, 'Mutta minä sanon: eikö he sitä ole kuulleet? Heidän äänensä tosin on lähtenyt kaikkeen maailmaan ja heidän sanansa maailman ääriin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 19, 'Vaan minä sanon: eikös Israel tietänyt? Ensimäinen Moses sanoo: minä tahdon teitä yllyttää kateuteen sen kansan kautta, joka ei minun kansani ole, ja tyhmän kansan kautta tahdon minä teitä härsytellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 20, 'Mutta Jesaias on rohkia ja sanoo: minä olen niiltä löydetty, jotka ei minua etsineet, ja olen niille ilmaantunut, jotka ei minua kysyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 21, 'Mutta Israelille hän sanoo: koko päivän olen minä käteni ojentanut tottelemattomalle ja vastahakoiselle kansalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 1, 'Niin minä siis sanon: onkos Jumala kansansa hyljännyt? Pois se! sillä minä olen myös Israelilainen, Abrahamin siemenestä, Benjaminin suvusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 2, 'Ei Jumala ole kansaansa hyljännyt, jonka hän ennen on tuntenut. Ettekö te tiedä, mitä Raamattu Eliaasta sanoo? kuinka hän rukoilee Jumalaa Israelia vastaan, sanoen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 3, 'Herra, he ovat tappaneet sinun prophetas ja sinun alttaris kukistaneet, ja minä yksinäni jäin, ja he etsivät minunkin henkeäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 4, 'Mutta mitä Jumalan vastaus sanoo hänelle? Minä olen itselleni jättänyt seitsemäntuhatta miestä, jotka ei ole Baalille polviansa taivuttaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 5, 'Niin ovat jääneet tälläkin ajalla armon valitsemisen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 6, 'Mutta jos se armosta on, niin ei se ole enään töistä, sillä ei armo muutoin armo olisikaan. Mutta jos se on töistä, niin ei se silleen armo ole; muutoin ei työ enään ole työ.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 7, 'Kuinkas siis? Jota Israel etsii, sitä ei hän ole saanut; mutta valitut sen ovat saaneet ja ne muut ovat paatuneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 8, '(Niinkuin kirjoitettu on: Jumala on antanut heille uppiniskaisen hengen, silmät, ettei he näkisi, ja korvat, ettei he kuulisi) tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 9, 'Ja David sanoo: heidän pöytänsä tulkoon heille paulaksi, ja satimeksi, ja pahennukseksi, ja kostoksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 10, 'Heidän silmänsä soetkoon, ettei he näkisi, ja taita aina heidän selkänsä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 11, 'Niin minä siis sanon: ovatko he sentähden itsensä loukanneet, että heidän piti lankeeman? Pois se! vaan heidän lankeemisestansa tapahtui pakanoille autuus, että hän sais heitä kiivaaksi heidän tähtensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 12, 'Mutta jos heidän lankeemisensa on maailman rikkaus ja heidän vähennöksensä on pakanain rikkaus; kuinka paljoa enemmin heidän täydellisyytensä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 13, 'Sillä teille pakanoille minä puhun: että minä pakanain apostoli olen, ylistän minä minun virkaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 14, 'Jos minä taitaisin jollakin tavalla niitä, jotka minun lihani ovat, kiivaaksi saada ja muutamatkin heistä autuaaksi saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 15, 'Sillä jos heidän hylkäämisensä on maailman sovinto, mitäs heidän korjaamisensa muuta on kuin elämä kuolleista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 16, 'Sillä jos alku on pyhä, niin on myös koko taikina, ja jos juuri on pyhä, niin ovat myös oksat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 17, 'Mutta jos muutamat oksista ovat murtuneet, ja sinä, joka metsä-öljypuu olit, olet niihin istutettu, ja olet öljypuun juuresta ja lihavuudesta osalliseksi tullut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 18, 'Niin älä ylpeile oksia vastaan; mutta jos sinä heitä vastaan ylpeilet, niin tiedä, ettet sinä juurta kanna, vaan juuri kantaa sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 19, 'Niin sanot; oksat ovat murtuneet, että minun piti siihen jälleen istutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 20, 'Oikein: he ovat murtuneet epäuskonsa tähden, mutta sinä pysyt uskon kautta: älä ole röyhkeä, vaan pelkää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 21, 'Sillä jos ei Jumala luonnollisia oksia armahtanut, katso, ei hän sinuakaan armahda.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 22, 'Sentähden katso tässä Jumalan hyvyyttä ja ankaruutta: ankaruutta niissä, jotka lankesivat, mutta hyvyyttä itse sinussas, jos sinä ainoastaan hyvyydessä pysyt; muutoin sinäkin leikataan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 23, 'Ja ne jälleen istutetaan, ellei he epäuskossansa pysy; sillä Jumala on voimallinen heitä jälleen istuttamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 24, 'Sillä jos sinä olet luonnollisesta metsä-öljypuusta karsittu, ja olet vastoin luontoa hyvään öljypuuhun istutettu, kuinka paljon enemmin ne, jotka luonnolliset ovat, omaan öljypuuhunsa istutetaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 25, 'Sillä en minä tahdo salata teiltä, rakkaat veljet, tätä salaisuutta, (ettette itsellänne ylpeilisi,) että paatumus on puolittain Israelille tullut, siihenasti kuin pakanain täydellisyys tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 26, 'Ja niin kaikki Israel pitää autuaaksi tuleman, niinkuin kirjoitettu on: se tulee Zionista, joka päästää ja jumalattoman menon Jakobista kääntää pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 27, 'Ja tämä on minun liittoni heidän kanssansa, kuin minä otan pois heidän syntinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 28, 'Evankeliumin puolesta tosin ovat he viholliset teidän tähtenne; mutta valitsemisen puolesta rakastetaan heitä isäin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 29, 'Sillä ei Jumala lahjojansa ja kutsumistansa kadu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 30, 'Sillä niinkuin ette tekään muinen Jumalan päälle uskoneet, mutta olette nyt laupiuden heidän epäuskonsa kautta saaneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 31, 'Niin ei he ole myös nyt uskoneet sitä laupiutta, joka teille on tapahtunut, että heillekin laupius tapahtuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 32, 'Sillä Jumala on kaikki epäuskon alle sulkenut, että hän kaikkia armahtais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 33, 'Oi sitä Jumalan rikkauden, ja viisauden, ja tunnon syvyyttä! kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 34, 'Sillä kuka on Herran mielen tietänyt? Eli kuka on hänen neuvonantajansa ollut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 35, 'Eli kuka on hänelle jotakin ennen antanut, jota hänelle pitäis jälleen maksettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 36, 'Sillä hänestä ja hänen kauttansa ja hänessä ovat kaikki: hänelle olkoon kunnia ijankaikkisesti, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 1, 'Niin neuvon minä teitä, rakkaat veljet, Jumalan sydämellisen laupiuden kautta, että te antaisitte teidän ruumiinne eläväksi, pyhäksi ja Jumalalle otolliseksi uhriksi, joka on teidän toimellinen jumalanpalveluksenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 2, 'Ja älkäät sovittako teitänne tämän maailman muodon jälkeen, vaan muuttakaat teitänne teidän mielenne uudistuksen kautta, että te koettelisitte, mikä Jumalan hyvä, otollinen ja täydellinen tahto olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 3, 'Sillä minä sanon siitä armosta, joka minulle annettu on, jokaiselle, joka teidän seassanne on, ettei yksikään itsestänsä enempää pitäisi kuin hänen tulee pitää; vaan pitäkään kohtuullisesti itsestänsä sen jälkeen kuin Jumala on kullekin uskon mitan jakanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 4, 'Sillä niinkuin meillä on yhdessä ruumiissa monta jäsentä, mutta ei kaikilla jäsenillä ole yhtäläinen työ,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 5, 'Niin mekin olemme monta yksi ruumis Kristuksessa, mutta keskenämme olemme me toinen toisemme jäsenet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 6, 'Ja meillä ovat moninaiset lahjat siitä armosta, kuin meille annettu on. Jos jollakin on prophetia, niin olkoon uskon kanssa yhteinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 7, 'Jos jollakin on joku virka, niin pitäkään virastansa vaarin. Jos joku opettaa, niin ottakaan opetuksestansa vaarin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 8, 'Jos joku neuvoo, niin pitäkään neuvostansa vaarin. Jos joku antaa, niin antakaan yksinkertaisuudessa. Jos joku hallitsee, niin pitäkään siitä murheen. Jos joku armahtaa, niin tehkään sen ilolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 9, 'Olkoon rakkaus vilpitöin. Vihatkaat pahaa ja riippukaat kiinni hyvässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 10, 'Veljellinen rakkaus olkoon sydämellinen teidän keskenänne. Ennättäkään toinen toisensa kunniaa tekemässä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 11, 'Älkäät olko hitaat töissänne. Olkaat palavat hengessä. Palvelkaat Herraa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 12, 'Olkaat toivossa iloiset, kärsivälliset murheessa. Olkaat alati rukouksissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 13, 'Jakakaat omanne pyhäin tarpeeksi. Ottakaat mielellänne huoneesen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 14, 'Siunatkaat vainollisianne: siunatkaat ja älkäät sadatelko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 15, 'Iloitkaat iloisten kanssa, ja itkekäät itkeväisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 16, 'Olkaat keskenänne yksimieliset. Älkäät itsestänne paljon pitäkö, vaan pitäkäät teitänne nöyräin kaltaisena. Älkäät itsiänne ylen viisaina pitäkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 17, 'Älkäät kellenkään pahaa pahalla kostako. Ahkeroitkaat sitä, mikä kunniallinen on kaikkein ihmisten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 18, 'Jos mahdollinen on, niin paljo kuin teissä on, niin pitäkäät rauha kaikkein ihmisten kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 19, 'Älkäät itse kostako, minun rakkaani, vaan antakaat (Jumalan) vihan siaa saada. Sillä kirjoitettu on: minun on kosto, minä tahdon kostaa, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 20, 'Sentähden, jos vihollises isoo, niin syötä häntä, ja jos hän janoo, niin juota häntä; sillä koskas tämän teet, niin sinä tuliset hiilet hänen päänsä päälle kokoot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 21, 'Älä anna sinuas voitettaa pahalta, vaan voita sinä paha hyvällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 1, 'Jokainen olkoon esivallalle, jolla valta on, alamainen; sillä ei esivalta ole muutoin kuin Jumalalta: ne vallat, jotka ovat, Jumalalta ne säädetyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 2, 'Sentähden jokainen, joka itsensä esivaltaa vastaan asettaa, se on Jumalan säätyä vastaan; mutta ne, jotka vastaan ovat, saavat tuomion päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 3, 'Sillä ne, jotka vallan päällä ovat, ei ole hyvintekiöille, vaan pahoille pelvoksi. Ellet tahdo esivaltaa peljätä, niin tee hyvää, ja sinä saat häneltä kiitoksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 4, 'Sillä hän on Jumalan palvelia sinun hyväkses. Vaan jos sinä pahaa teet, niin pelkää; sillä ei hän miekkaa hukkaan kanna; sillä hän on Jumalan palvelia ja kostaja sille rangaistukseksi, joka pahaa tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 5, 'Sentähden tulee alamainen olla, ei ainoastaan vihan tähden, vaan myös omantunnon tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 6, 'Sillä sentähden te myös veron maksatte; sillä he ovat Jumalan palveliat, joiden senkaltaisista tulee lukua pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 7, 'Niin antakaat siis kaikille, mitä te velvolliset olette: sille vero, jolle vero tulee; sille tulli, jolle tulli tulee; sille pelko, jolle pelko tulee; sille kunnia, jolle kunnia tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 8, 'Älkäät kellenkään velvolliset olko, vaan ainoastaan että te toinen toistanne rakastatte; sillä joka toista rakastaa, se on täyttänyt lain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 9, 'Sillä se: ei sinun pidä huorin tekemän; ei sinun pidä tappaman; ei sinun pidä varastaman; ei sinun pidä väärää todistusta sanoman; ei sinun pidä himoitseman, ja mitä muuta käskyä on, se tähän sanaan suljetaan: sinun pitää rakastaman lähimmäistäs niinkuin itsiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 10, 'Ei rakkaus tee lähimmäiselle mitään pahaa; sentähden on rakkaus lain täyttämys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 11, 'Ja että me sen tiedämme, nimittäin ajan, että nyt on aika unesta nousta; sillä meidän autuutemme on nyt lähempänä kuin silloin, kuin me uskoimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 12, 'Yö on kulunut ja päivä on tullut; sentähden hyljätkäämme pimeyden työt ja pukekaamme meitämme valkeuden sota-aseilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 13, 'Vaeltakaamme soveliaasti, niinkuin päivällä: ei ylönsyömisessä, eikä juopumisessa, ei kammioissa, eikä haureudessa, ei riidassa ja kateudessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 14, 'Vaan pukekaat päällenne Herra Jesus Kristus ja älkäät holhoko ruumistannen haureuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 1, 'Heikkouskoista korjatkaat, ei kamppausten riidoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 2, 'Yksi kyllä uskoo saavansa kaikkinaista syödä, vaan heikko syö kaalia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 3, 'Joka syö, älkään sitä katsoko ylön, joka ei syö; ja se, joka ei syö, älkään tuomitko sitä, joka syö; sillä Jumala on hänen ottanut vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 4, 'Kuka sinä olet, joka toisen palveliaa tuomitse? Omalle isännällensä hän seisoo eli lankee. Mutta hän taidetaan ojentaa ylös; sillä Jumala on voimallinen häntä ojentamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 5, 'Yksi eroittaa yhden päivän toisesta, toinen pitää kaikki päivät yhtäläisenä: jokainen olkoon vahva mielessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 6, 'Joka päivää tottelee, sen hän Herralle tekee; ja joka ei päivää tottele, se myös sen Herralle tekee. Joka syö, hän syö Herralle; sillä hän kiittää Jumalaa: ja joka ei syö, se ei syö Herralle, ja kiittää Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 7, 'Sillä ei yksikään meistä itsellensä elä, eikä yksikään itsellensä kuole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 8, 'Sillä jos me elämme niin me Herralle elämme; jos me kuolemme, niin me Herralle kuolemme. Sentähden joko me elämme tai kuolemme, niin me Herran omat olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 9, 'Sillä sentähden on myös Kristus kuollut ja noussut ylös ja jälleen eläväksi tullut, että hän olis kuolleiden ja elävien Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 10, 'Mutta miksi sinä veljes tuomitset? Eli miksi sinä veljes katsot ylön? sillä me asetetaan kaikki Kristuksen tuomio-istuimen eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 11, 'Sillä kirjoitettu on: niin totta kuin minä elän, sanoo Herra, minua pitää kaikki polvet kumartaman, ja kaikki kielet pitää Jumalaa tunnustaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 12, 'Sentähden jokaisen meistä pitää edestänsä Jumalalle luvun tekemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 13, 'Älkäämme siis tästedes toinen toistamme tuomitko, vaan tuomitkaat paremmin niin, ettei yksikään veljensä eteen pane loukkausta eli pahennusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 14, 'Minä tiedän ja olen vahva Herrassa Jesuksessa, ettei mitään itsestänsä yhteistä ole, vaan joka jotakin yhteiseksi luulee, hänelle se on yhteinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 15, 'Mutta jos sinun veljes sinun ruastas surulliseksi tulee, niin et sinä enään vaella rakkaudessa. Älä sitä ruallas kadota, jonka tähden Kristus on kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 16, 'Sentähden sovittakaat niin, ettei teidän hyvyyttänne laitettaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 17, 'Sillä ei Jumalan valtakunta ole ruoka ja juoma, mutta vanhurskaus, ja rauha, ja ilo Pyhässä Hengessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 18, 'Sillä joka niissä Kristusta palvelee, hän on Jumalalle otollinen ja ihmisille kelvollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 19, 'Sentähden noudattakaamme niitä, mitkä rauhaan sopivat, ja sitä, mikä keskenämme parannukseksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 20, 'Älä ruan tähden Jumalan työtä turmele. Kaikki tosin ovat puhtaat; vaan sille ihmiselle on se paha, joka syö omantuntonsa pahennuksen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 21, 'Se on hyvä, ettet lihaa söisi etkä viinaa joisi eli jotakin, josta veljes loukkaantuu, taikka pahenee, elikkä heikoksi tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 22, 'Jos sinulla on usko, niin pidä se itsessäs Jumalan edessä. Autuas on, joka ei tee itsellensä omaatuntoa niissä, mitkä hän koettelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 23, 'Mutta joka siitä epäilee ja kuitenkin syö, se on kadotettu; sillä ei hän syönyt uskossa, mutta kaikki, mikä ei uskosta ole, se on synti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 1, 'Mutta meidän, jotka väkevät olemme, tulee heikkoin voimattomuutta kärsiä, eikä itsellemme kelvata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 2, 'Niin jokainen meistä kelvatkoon lähimmäisellensä siinä, mikä hyvä on, parannukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 3, 'Sillä ei Kristuskaan itsellensä kelvannut, vaan niinkuin kirjoitettu on: heidän pilkkansa, jotka sinua pilkkasivat, lankesivat minun päälleni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 4, 'Sillä mitä ennen kirjoitettu on, se on meille opiksi kirjoitettu, että meillä kärsivällisyyden ja Raamattuin lohdutuksen kautta toivo olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 5, 'Mutta kärsivällisyyden ja lohdutuksen Jumala antakoon teille, että te keskenänne yksimieliset olisitte Jesuksen Kristuksen perään:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 6, 'Että te yksimielisesti yhdestä suusta kiittäisitte Jumalaa ja meidän Herran Jesuksen Kristuksen Isää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 7, 'Sentähden korjatkaat toinen toistanne, niinkuin Kristuskin on meitä Jumalan kunniaksi korjannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 8, 'Mutta minä sanon: Jesus Kristus on ollut ympärileikkauksen palvelia Jumalan totuuden tähden, vahvistamaan sitä lupausta, joka isille tapahtunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 9, 'Mutta että pakanat laupiuden edestä Jumalaa kiittäisivät, niinkuin kirjoitettu on: sentähden kiitän minä sinua pakanain seassa ja veisaan sinun nimelles.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 10, 'Ja taas hän sanoo: iloitkaat pakanat hänen kansansa kanssa!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 11, 'Ja taas: kiittäkäät Herraa, kaikki pakanat, ja kaikki kansa ylistäkään häntä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 12, 'Ja taas sanoo Jesaias: sen pitää oleman Jessen juuren, joka on nouseva pakanoita hallitsemaan, jonka päälle pakanat toivoman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 13, 'Mutta toivon Jumala täyttäköön teitä kaikella riemulla ja rauhalla uskossa, että teillä Pyhän Hengen voiman kautta yltäkylläinen toivo olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 14, 'Mutta minä tiedän hyvästi, rakkaat veljeni, teistä, että te olette hyvyyttä täynnä, kaikella tuntemisella täytetyt, että te voitte toinen toistanne neuvoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 15, 'Minä olen kuitenkin puolittain rohkiasti teidän tykönne, rakkaat veljet, kirjoittanut, niinkuin muistuttain teille sen armon puolesta, joka minulle Jumalalta on annettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 16, 'Että minun pitää oleman pakanain seassa Jesuksen Kristuksen palvelian, Jumalan evankeliumia uhraamassa, että pakanatkin olisivat Jumalalle otollinen uhri, Pyhän Hengen kautta pyhitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 17, 'Sentähden minulla on se, josta minä Jesuksessa Kristuksessa kerskaan, niissä mitkä Jumalan ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 18, 'Sillä en minä rohkene mitään puhua niistä, mitä ei Kristus minun kauttani vaikuttanut pakanain kuuliaisuudeksi, sanalla ja työllä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 19, 'Merkkien ja ihmeiden voimalla, Jumalan Hengen väellä; niin että minä hamasta Jerusalemista ja niissä ympäri Illyrikoon asti olen kaikki Kristuksen evankeliumilla täyttänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 20, 'Ja minä olen ollut ahkera evankeliumia saarnaamaan, joissa Kristuksen nimi ei mainittu ollut, etten minä muukalaisen perustuksen päälle rakentaisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 21, 'Vaan niinkuin kirjoitettu on: joille ei ensinkään hänestä julistettu ollut, niiden pitää sen näkemän, ja jotka ei kuulleet ole, niiden pitää ymmärtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 22, 'Sentähden myös minä olen usein estetty teidän tykönne tulemasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 23, 'Mutta nyt, ettei minulla ole näissä maakunnissa enempi siaa ja minä olen jo monta vuotta halainnut teidän tykönne tulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 24, 'Sentähden kuin minä Hispaniaan vaellan, niin minä tulen teidän tykönne; sillä minä toivon, että kuin minä sen kautta matkustan, niin minä saan teidät nähdä, ja niin teiltä sinne saatettaisiin; kuitenkin, että minä ennen saisin kerran minuni teistä ilahuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 25, 'Mutta nyt minä vaellan Jerusalemiin pyhille palvelusta tekemään;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 26, 'Sillä ne Makedoniasta ja Akajasta ovat mielellänsä Jerusalemin köyhiä pyhiä varten yhteisen avun koonneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 27, 'He ovat sen mielellänsä tehneet, niinkuin he siihen heille velkapäätkin ovat; sillä jos pakanat ovat heidän hengellisestä tavarastansa osallisiksi tulleet, niin on kohtuullinen, että he myös heitä ruumiillisella tavarallansa palvelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 28, 'Kuin minä siis sen asian päättänyt olen ja heille tämän hedelmän lukinnut, tahdon minä teidän kauttannen Hispaniaan palata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 29, 'Mutta minä tiedän, kuin minä teidän tykönne tulen, että minä tulen Kristuksen evankeliumin täydellisellä siunauksella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 30, 'Mutta minä neuvon teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen kautta ja Hengen rakkauden kautta, että te minun kanssani kilvoittelisitte rukouksissa minun edestäni Jumalan tykö:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 31, 'Että minä Juudeassa epäuskoisista pelastettaisiin, ja että minun palvelukseni Jerusalemissa olis pyhille otollinen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 32, 'Että minä ilolla teidän tykönne tulisin Jumalan tahdon kautta, ja minuani ynnä teidän kanssanne virvoittaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 33, 'Mutta rauhan Jumala olkoon teidän kaikkein kanssanne! Amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 1, 'Minä annan teidän haltuunne Pheben, meidän sisaremme, joka on Kenkrean seurakunnan palveluspiika:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 2, 'Että te häntä ottaisitte vastaan Herrassa, niinkuin pyhäin sopii. Ja olkaat hänelle kaikissa asioissa avulliset, joissa hän teitä tarvitsee; sillä hän on monelle avullinen ollut ja itse minulle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 3, 'Tervehtikäät Priskillaa ja Akvilaa, minun auttajiani Kristuksessa Jesuksessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 4, '(Jotka ovat kaulansa minun henkeni tähden alttiiksi antaneet: joita en minä ainoasti kiitä, vaan kaikki pakanainkin seurakunnat.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 5, 'Niin myös sitä seurakuntaa, joka heidän huoneessansa on. Tervehtikäät Epenetusta, minun rakkaintani, joka on Akajasta uutinen Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 6, 'Tervehtikäät Mariaa, joka paljon vaivaa meistä näki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 7, 'Tervehtikäät Andronikusta ja Juniaa, minun lankojani ja kanssavankejani, jotka ovat kuuluisat apostolien seassa, jotka myös olivat ennen minua Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 8, 'Tervehtikäät Ampliaa, minun rakastani Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 9, 'Tervehtikäät Urbanusta, meidän auttajaamme Kristuksessa, ja Stakya, minun rakastani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 10, 'Tervehtikäät Apellesta, joka on koeteltu Kristuksessa. Tervehtikäät Aristobulin perhettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 11, 'Tervehtikäät Herodionia, minun lankoani. Tervehtikäät Narkissuksen perhettä, jotka ovat Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 12, 'Tervehtikäät Tryphenaa ja Tryphosaa, jotka työtä tekevät Herrassa. Tervehtikäät Persistä, minun rakastani, joka paljon työtä tehnyt on Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 13, 'Tervehtikäät Rufusta, valittua Herrassa, ja hänen ja minun äitiäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 14, 'Tervehtikäät Asynkritusta ja Phlegonia, Hermasta, Patrobasta, Hermestä ja veljiä, jotka heidän kanssansa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 15, 'Tervehtikäät Philologusta ja Juliaa, Nereusta, ja hänen sisartansa, ja Olympaa, ja kaikkia pyhiä, jotka ovat heidän kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 16, 'Tervehtikäät teitänne keskenänne pyhällä suunantamisella. Kristuksen seurakunnat tervehtivät teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 17, 'Mutta minä neuvon teitä, rakkaat veljet, että te kavahtaisitte eripuraisuuden ja pahennuksen matkaan saattajia sitä oppia vastaan, jonka te oppineet olette: ja välttäkäät niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 18, 'Sillä ei senkaltaiset Herraa Jesusta Kristusta palvele, vaan omaa vatsaansa ja viettelevät makeilla puheillansa ja liehakoitsemisellansa yksinkertaisten sydämet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 19, 'Sillä teidän kuuliaisuutenne on kaikille julistettu, jonka tähden minä iloitsen teidän ylitsenne. Mutta minä tahdon, että teidän pitää hyvässä viisaat oleman ja pahuudessa yksinkertaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 20, 'Mutta rauhan Jumala on tallaava saatanan pian teidän jalkainne alle. Meidän Herran Jesuksen Kristuksen armo olkoon teidän kanssanne! Amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 21, 'Teitä tervehtivät Timoteus, minun auttajani, ja Lukius, ja Jason ja Sosipater, minun lankoni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 22, 'Minä Tertius, joka tämän lähetyskirjan kirjoitin, tervehdin teitä Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 23, 'Teitä tervehtii Gajus, minun ja kaiken seurakunnan holhoja. Teitä tervehtii Erastus, kaupungin rahanhaltia, ja Kvartus veli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 24, 'Meidän Herran Jesuksen Kristuksen armo olkoon teidän kaikkein kanssanne! Amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 25, 'Mutta hänelle, joka voi teitä vahvistaa minun evankeliumini ja Jesuksen Kristuksen saarnan jälkeen, sen salaisuuden ilmestyksen jälkeen, joka ijäisiin aikoihin on salattu ollut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 26, 'Mutta nyt ilmoitettu ja tiettäväksi tehty prophetain Raamattuin kautta, ijankaikkisen Jumalan käskyn jälkeen, uskon kuuliaisuudeksi kaikkein pakanain seassa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 27, 'Jumalalle, joka yksinänsä viisas on, olkoon kunnia Jesuksen Kristuksen kautta ijankaikkisesti! Amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Paavali, kutsuttu Jesuksen Kristuksen apostoliksi Jumalan tahdon kautta, ja Sostenes veli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Sille Jumalan seurakunnalle, joka on Korintossa, pyhitetyille Kristuksessa Jesuksessa, kutsutuille pyhille ynnä kaikkein niiden kanssa, jotka meidän Herran Jesuksen Kristuksen nimeä avuksensa huutavat, jokaisessa heidän ja meidän siassamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Armo olkoon teille ja rauha Jumalalta, meidän isältämme, ja Herralta Jesukselta Kristukselta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Minä kiitän Jumalaani aina teidän tähtenne, sen Jumalan armon edestä, joka teille Jesuksessa Kristuksessa annettu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Että te olette kaikissa rikkaaksi tehdyt hänessä, kaikessa opissa ja kaikessa tuntemisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Sillä todistus Kristuksesta on teissä vahvistettu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Niin ettei teiltä jossakussa lahjassa mitään puutu, jotka odotatte meidän Herran Jesuksen Kristuksen ilmoitusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Joka myös teitä loppuun asti vahvistaa, että te olisitte nuhteettomat meidän Herran Jesuksen Kristuksen päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Sillä Jumala on uskollinen, jonka kautta te kutsutut olette hänen Poikansa Jesuksen Kristuksen, meidän Herramme yhteyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Mutta minä neuvon teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen nimen kautta, että te kaikki yhdenkaltaisen puheen pitäisitte, ja ettei teidän seassanne eriseuroja olisi, vaan olkaat sovitetut yhdessä mielessä ja yhdessä neuvossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Sillä minun korvilleni on tullut teistä, rakkaat veljet, Kloen perheen kautta, että riidat ovat teillä keskenänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Niin minä sanon sitä, että kukin teistä sanoo: minä olen Paavalin, minä olen Apollon, minä Kephaan, minä Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Lieneekö Kristus jaettu, vai onko Paavali teidän edestänne ristiinnaulittu? eli oletteko te Paavalin nimeen kastetut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 14, 'Minä kiitän Jumalaa, etten minä ole yhtään teistä kastanut, vaan Krispuksen ja Gajuksen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 15, 'Ettei kenkään saa sanoa, että minä minun nimeeni ketään kastin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 16, 'Minä kastin myös Stephanaan perheen; sitte en minä tiedä, jos minä jonkun muun kastanut olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 17, 'Sillä ei Kristus minua lähettänyt kastamaan, vaan evankeliumia saarnaamaan, ei sanan viisaudella, ettei Kristuksen risti turhaan menisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 18, 'Sillä se puhe rististä on niille hulluus, jotka kadotetaan; mutta meille, jotka autuaaksi tulemme, on se Jumalan voima.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 19, 'Sillä kirjoitettu on: minä kadotan viisasten viisauden, ja ymmärtäväisten ymmärryksen minä hylkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 20, 'Kussas on viisas? kussas on kirjanoppinut? kussas tämän maailman tutkia on? Eikö Jumala ole tämän maailman viisautta hulluudeksi tehnyt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 21, 'Sillä että Jumalan viisaudessa ei maailma tuntenut Jumalaa viisauden kautta, niin kelpasi Jumalalle tyhmän saarnan kautta niitä vapahtaa, jotka sen uskovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 22, 'Sentähden että Juudalaiset merkkiä anovat ja Grekiläiset viisautta etsivät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 23, 'Mutta me saarnaamme ristiinnaulitun Kristuksen Juudalaisille pahennukseksi ja Grekiläisille hulluudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 24, 'Mutta kutsutuille sekä Juudalaisille että Grekiläisille saarnaamme me Kristuksen Jumalan voimaksi ja Jumalan viisaudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 25, 'Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 26, 'Te näette, rakkaat veljet, teidän kutsumisenne, ettei monta lihallista viisasta, ei monta voimallista, ei myös monta suuresta suvusta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 27, 'Vaan ne, jotka maailman edessä hullut ovat, on Jumala valinnut, että hän viisaat häpiään saattais; ja ne, jotka heikot ovat maailman edessä, on Jumala valinnut, että hän väkevät häpiään saattais;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 28, 'Ja ne alimmaisesta suvusta ja ylönkatsotut maailmassa on Jumala valinnut, ja ne, jotka ei mitään ole, että hän ne, jotka jotakin ovat, turhaksi tekis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 29, 'Ettei hänen edessänsä yksikään liha kerskaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 30, 'Mutta te olette hänestä Kristuksessa Jesuksessa, joka meille on Jumalalta tehty viisaudeksi, ja vanhurskaudeksi, ja pyhitykseksi ja lunastukseksi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 31, 'Että niinkuin kirjoitettu on: joka itsiänsä kerskaa, hän kerskatkaan itsiänsä Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, 'Ja, rakkaat veljet, kuin minä teidän tykönne tulin, en minä tullut korkeilla sanoilla enkä syvällä viisaudella ilmoittamaan teille Jumalan todistusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'Sillä en minä itsiäni pitänyt teidän seassanne mitäkään tietämäni, vaan ainoasti Jesuksen Kristuksen ja sen ristiinnaulitun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'Ja minä olin teidän kanssanne heikkoudessa, ja pelvossa, ja suuressa vapistuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'Ja minun puheeni ja saarnani ei ollut kaunistetuissa sanoissa ihmisten viisauden jälkeen, mutta hengen ja voiman osoituksessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'Ettei teidän uskonne olisi ihmisten viisaudessa, vaan Jumalan voimassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, 'Mutta me puhumme siitä viisaudesta, joka on täydellisten tykönä, ei tämän maailman viisaudesta, eikä tämän maailman päämiesten, jotka hukkuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'Vaan me puhumme siitä salatusta Jumalan viisaudesta, jonka Jumala on ennen maailman alkua säätänyt meidän kunniaksemme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'Jota ei yksikään tämän maailman päämiehistä tuntenut; sillä jos he olisivat tunteneet, niin ei he olisi kunnian Herraa ristiinnaulinneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'Vaan niinkuin kirjoitettu on: joita ei silmä ole nähnyt, eikä korva ole kuullut, ja ei ihmisen sydämeen ole astunut, joita Jumala on niille valmistanut, jotka häntä rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'Mutta meille on Jumala sen ilmoittanut Henkensä kautta; sillä Henki kaikki tutkistelee, Jumalan syvyydetkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Sillä kuka ihminen tietää, mitä ihmisessä on, vaan ihmisen henki, joka hänessä on? Niin myös ei yksikään tiedä, mitä Jumalassa on, vaan Jumalan Henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, 'Mutta emme ole saaneet tämän maailman henkeä, vaan sen Hengen, joka Jumalasta on, että me tietäisimme, mitä meille Jumalalta annettu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'Jota me myös puhumme, ei niillä sanoilla, joita inhimillinen viisaus opettaa, vaan niillä, joita Pyhä Henki opettaa, ja me tuomitsemme hengelliset asiat hengellisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'Mutta ei luonnollinen ihminen ymmärrä niitä, mitkä Jumalan Hengen ovat; sillä ne ovat hänelle hulluus, ja ei taida käsittää, sillä ne hengellisesti tuomitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'Mutta hengellinen tuomitsee tosin kaikkia, vaan ei hän keltäkään tuomita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 16, 'Sillä kuka on tietänyt Herran mielen, joka tahtoo hänelle neuvoa antaa? Mutta meillä on Kristuksen mieli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, 'Ja, rakkaat veljet! en minä taitanut teille puhua niinkuin hengellisille, vaan niinkuin lihallisille, niinkuin lapsille Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'Rieskaa minä olen teille juoda antanut, ja en ruokaa; sillä ette sitä vielä voineet, ja ette vielä nytkään voi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'Sillä te olette vielä lihalliset, sillä niinkauvan kuin teidän seassanne kateus ja riita ja eripuraisuus on, ettekö te ole lihalliset ja vaella ihmisten tavan jälkeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'Sillä koska joku sanoo: minä olen Paavalin, ja toinen: minä Apollon: ettekö te siis ole lihalliset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'Mitäs Paavali on ja mikä Apollo muuta kuin palveliat, joiden kautta te olette uskoneet, ja niinkuin Jumala kullekin antanut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'Minä olen istuttanut, Apollo on kastanut mutta Jumala on kasvun antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'Niin ei se mitään ole, joka istuttaa, eikä se, joka kastaa, vaan Jumala, joka kasvun on antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'Mutta se, joka istuttaa, ja se, joka kastaa, ovat yhtä: kumpikin saa palkkansa työnsä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, 'Sillä me olemme Jumalan apulaiset: te olette Jumalan pelto ja Jumalan rakennus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'Sen Jumalan armon jälkeen, joka minulle annettu on, olen minä perustuksen laskenut, niinkuin taitava rakentaja, vaan toinen sen päälle rakentaa; mutta katsokaan jokainen, kuinka hän sen päälle rakentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'Sillä muuta perustusta, ei taida yksikään panna, vaan sen, joka pantu on, joka on Jesus Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'Jos nyt joku rakentaa tämän perustuksen päälle kultaa, hopiaa, kalliita kiviä, puita, heiniä, olkia:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, 'Jokainen teko tulee julkiseksi; sillä se päivä sen on selittävä, joka tulessa ilmaantuu: ja minkäkaltainen kunkin teko on, sen tuli koettelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, 'Jos jonkun teko pysyy, jonka hän sen päälle rakentanut on, niin hän saa palkan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, 'Jos jonkun teko palaa, niin hän saa vahingon; mutta hän tulee itse autuaaksi, kuitenkin niinkuin tulen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 16, 'Ettekö te tiedä teitänne Jumalan templiksi, ja että Jumalan Henki asuu teissä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 17, 'Jos joku Jumalan templin turmelee, sen Jumala turmelee; sillä Jumalan templi on pyhä, niinkuin tekin olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 18, 'Älkään kenkään itseänsä pettäkö: jos joku teistä luulee itsensä viisaaksi tässä maailmassa, se tulkoon tyhmäksi, että hän viisaaksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 19, 'Sillä tämän maailman viisaus on hulluus Jumalan tykönä. Sillä kirjoitettu on: hän käsittää taitavat heidän kavaluudessansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 20, 'Ja taas: Herra tietää viisasten ajatukset, että ne turhat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 21, 'Sentähden älkään yksikään ihmisistä kerskatko; sillä kaikki ovat teidän omanne:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 22, 'Joko se olis Paavali eli Apollo, eli Kephas, taikka maailma, eli elämä, eli kuolema, taikka nykyiset eli tulevaiset: kaikki ovat teidän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 23, 'Mutta te olette Kristuksen, vaan Kristus on Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 1, 'Jokainen pitäköön meitä Kristuksen palvelioina ja Jumalan salaisuutten huoneenhaltioina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 2, 'Mutta ainoastaan se huoneenhaltiain seassa etsitään, että joku uskolliseksi löydettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 3, 'Mutta vähän minä sitä tottelen, että minä teiltä tuomitaan eli inhimilliseltä päivältä: ja en minä itsekään tuomitse minuani;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 4, 'Sillä en minä tiedä mitään kanssani; mutta en minä sentähden vanhurskautettu ole, vaan Herra on se, joka minun tuomitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 5, 'Sentähden älkäät tuomitko ennen aikaa, siihenasti kuin Herra tulee, joka nekin valkeuteen saattaa, mitkä pimeydessä peitetyt ovat, ja ilmoittaa sydänten aivoitukset: ja silloin kukin saa kunnian Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 6, 'Mutta näitä, rakkaat veljet, olen minä minustani ja Apollosta ulostoimittanut teidän tähtenne, että te meistä oppisitte, ettei kenkään enempää itsestänsä ajattelisi kuin kirjoitettu on, ettei yksikään teistä toistansa vastaan pidä jonkun tähden itsiänsä paisuttaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 7, 'Sillä kuka sinun eroittaa? Taikka mitä sinulla on, jota et sinä ole saanut? Jos siitä siis saanut olet, mitäs kerskaat niinkuin et sinä saanut olisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 8, 'Jo te olette ravitut, jo te olette rikastuneet, ilman meitä te vallitsette: ja oi jospa te tosin vallitsisitte, että mekin teidän kanssanne vallitsisimme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 9, 'Sillä minä luulen, että Jumala on meitä apostoleita viimeisiksi asettanut, niinkuin surmattaviksi; sillä me olemme maailmalle, ja enkeleille, ja ihmisille ihmeeksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 10, 'Me olemme tomppelit Kristuksen tähden, mutta te toimelliset Kristuksessa: me heikot, mutta te väkevät: te kunnialliset, mutta me katsotut ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 11, 'Hamaan tähän hetkeen asti kärsimme me nälkää ja janoa, ja olemme alasti, ja meitä lyödään korvalle ja ei meillä ole vahvaa asuinsiaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 12, 'Ja me näemme vaivaa, työtä tehden omilla käsillämme. Kuin meitä soimataan, niin me hyvästi lausumme: kuin meitä vainotaan, niin me kärsimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 13, 'Kuin meitä pilkataan, niin me rukoilemme: me olemme tulleet niinkuin maailman tunkioksi ja kaikkein saastaisuudeksi tähän päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 14, 'En minä näitä kirjoita häväistäkseni teitä, vaan minä neuvon teitä niinkuin rakkaita lapsiani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 15, 'Sillä ehkä teillä olis kymmenentuhatta opettajaa Kristuksessa, niin ei teillä kuitenkaan ole monta isää; sillä minä olen teitä Kristuksessa Jesuksessa siittänyt evankeliumin kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 16, 'Sentähden neuvon minä teitä, olkaat minun tavoittajani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 17, 'Sentähden lähetin minä teille Timoteuksen, joka on minun rakas ja uskollinen poikani Herrassa, jonka pitää muistuttaman teille minun tieni, jotka ovat Kristuksessa, niinkuin minä joka paikassa kaikissa seurakunnissa opetan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 18, 'Mutta muutamat ovat teistä paisuneet, niinkuin en minä teidän tykönne tuleva oliskaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 19, 'Mutta ennen paljoa aikaa tulen minä teidän tykönne, jos Herra tahtoo, ja tahdon tietää, ei paisuneitten sanojen, vaan voimaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 20, 'Sillä Jumalan valtakunta ei ole puheessa, vaan voimassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 21, 'Kumman te tahdotte: että minä tulen vitsalla teidän tykönne, taikka rakkaudella ja hengen siveydellä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 1, 'Täydellisesti kuuluu teidän seassanne huoruus, ja senkaltainen huoruus, josta ei pakanatkaan sanoa tiedä, niin että joku isänsä emäntää pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 2, 'Ja te olette paisuneet, ja miksi ette enemmin murehtineet, että se, joka senkaltaisen työn tehnyt on, teidän seastanne otettaisiin pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 3, 'Mutta minä tosin, joka niinkuin ruumiin puolesta poissa ollen, kuitenkin hengessä tykönä ollen, olen jo niinkuin tykönä oleva sen tuominnut, että hän, joka sen niin tehnyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 4, 'Meidän Herran Jesuksen Kristuksen nimeen, teidän kokoontulemisessanne, ynnä minun henkeni kanssa, meidän Herran Jesuksen Kristuksen voimalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 5, 'Annetaan saatanan haltuun lihan kadotukseksi, että henki autuaaksi tulis Herran Jesuksen päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 6, 'Ei ole teidän kerskauksenne hyvä: ettekö te tiedä, että vähä hapatus kaiken taikinan hapattaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 7, 'Sentähden peratkaat se vanha taikina, että te olisitte uusi taikina, niinkuin te happamattomat olette; sillä meidän pääsiäislampaamme on meidän edestämme uhrattu, joka on Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 8, 'Sentähden pitäkäämme juhlaa, ei vanhassa hapatuksessa, eikä pahuuden ja vääryyden hapatuksessa, vaan vakuuden ja totuuden happamattomassa taikinassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 9, 'Minä olen teille lähetyskirjassa kirjoittanut, ettei teidän pitäisi sekaantuman huorintekiäin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 10, 'Ja ei kaiketi tämän maailman huorintekiäin kanssa, eli ahneitten, eli raateliain, eli epäjumalain palveliain; sillä niin tulis teidän maailmasta paeta pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 11, 'Mutta nyt minä olen kirjoittanut, ettei teidän pidä heihin sekaantuman, jos joku, joka veljeksi kutsutaan, olis huorintekiä, taikka ahne, eli epäjumalain palvelia, taikka pilkkaaja, eli juomari, taikka raatelia; älkäät senkaltaisen kanssa syökö;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 12, 'Sillä mitä minun tulee tuomita niitä, jotka ulkona ovat? Ettekö te niitä tuomitse, jotka sisällä ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 13, 'Mutta Jumala ne tuomitsee, jotka ulkona ovat. Ajakaat itsekin paha pois tyköänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 1, 'Miksi joku teistä, jolla on toisen kanssa jotakin asiaa, rohkenee riidellä vääräin ja ei pyhäin edestä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 2, 'Ettekö te tiedä, että pyhät pitää maailmaa tuomitseman? Ja jos maailma pitää teidän kauttanne tuomittaman, ettekö siis te kelpaa pienempiä asioita tuomitsemaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 3, 'Ettekö te tiedä, että meidän pitää enkeleitäkin tuomitseman? kuinka siis ei ajallisia asioita?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 4, 'Kuin siis teillä on jotakuta asiaa ajallisesta hyvyydestä, niin te otatte ne, jotka seurakunnassa ovat katsotut ylön, ja asetatte tuomariksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 5, 'Teille minä sanon näitä häpiäksi: eikö niin yhtään viisasta ole teidän seassanne, joka taitais tuomita veljiensä välillä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 6, 'Vaan veli riitelee veljensä kanssa, ja sittenkin uskottoman edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 7, 'Niin on siis kaiketi vika teidän seassanne, että te toinen toisenne kanssa käytte oikeuden eteen. Miksi ette paremmin vääryyttä kärsi? miksi ette ennen suo teitänne vahingoittaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 8, 'Vaan te itse vääryyden ja vahingon teette, ja semminkin teidän veljillenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 9, 'Ettekö te tiedä, ettei väärät pidä Jumalan valtakuntaa perimän? Älkäät eksykö; ei huorintekiäin, eikä epäjumalten palvelijain, eikä salavuoteisten, eikä pehmiäin, eikä miesten kanssa makaajain,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 10, 'Eikä varasten, eikä ahnetten, eikä juomarien, eikä pilkkaajain eikä raateliain pidä Jumalan valtakuntaa perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 11, 'Ja senkaltaiset te muutamat olitte; mutta te olette pestyt, te olette pyhitetyt, te olette vanhurskaaksi tulleet Herran Jesuksen nimen kautta ja meidän Jumalamme hengen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 12, 'Kaikissa on minulla valta, vaan ei kaikki ole hyväksi: kaikissa on minulla valta, mutta en minä kenenkään alamainen ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 13, 'Ruoka on vatsalle säätty ja vatsa rualle; mutta Jumala on tämän ja sen hukuttava. Ei ruumis ole säätty huoruuteen, vaan Herralle, ja Herra ruumiille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 14, 'Mutta Jumala on Herran herättänyt, niin hän on myös meitäkin voimallansa herättävä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 15, 'Ettekö te tiedä, että teidän ruumiinne ovat Kristuksen jäsenet? Pitäiskö siis minun Kristuksen jäsenet ottaman ja porton jäseniksi tekemän? Pois se!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 16, 'Taikka ettekö te tiedä, että se, joka porttoon ryhtyy, hän on yksi ruumis sen kanssa? Sillä he tulevat, sanoo hän, kaksi yhdeksi lihaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 17, 'Mutta joka Herraan ryhtyy, se on yksi henki hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 18, 'Välttäkäät huoruutta. Kaikki synnit, joita ihminen tekee, ovat ulkona ruumiista; vaan joka huorin tekee, tekee syntiä omassa ruumiissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 19, 'Vai ettekö te tiedä, että teidän ruumiinne on Pyhän Hengen templi, joka teissä on, jonka te Jumalalta saitte, ja ettepä te ole teidän omanne?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 20, 'Sillä te olette kalliisti ostetut; kunnioittakaat siis Jumalaa teidän ruumiissanne ja teidän hengessänne, jotka Jumalan ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 1, 'Mutta niistä, joita te minulle kirjoititte, hyvä on miehelle, ettei hän vaimoon ryhdy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 2, 'Mutta huoruuden tähden pitäköön kukin oman vaimonsa, ja jokainen pitäköön oman miehensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 3, 'Mies antakoon vaimolle velvollisen mielisuosion, niin myös vaimo miehelle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 4, 'Ei ole vaimolla valtaa omalle ruumiillensa, vaan miehellä: ei myös miehellä ole valtaa ruumiillensa, vaan vaimolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 5, 'Älkäät toinen toistanne vältkö, jollei se ole molempain suosiosta hetkeksi, että teillä jouto olis paastota ja rukoilla: ja tulkaat jälleen yhteen, ettei saatana teitä kiusaisi teidän himonne hillimättömyyden puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 6, 'Mutta sen sanon minä teille suomisen ja ei käskyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 7, 'Sillä minä tahtoisin, että kaikki ihmiset niin olisivat kuin minäkin olen; mutta jokaisella on oma lahja Jumalalta, yhdellä niin ja toisella näin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 8, 'Vaan minä sanon naimattomille ja leskille: se on heille hyvä, jos he ovat niinkuin minäkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 9, 'Vaan ellei he voi itsiänsä pidättää, niin naikaan; sillä parempi on naida kuin palaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 10, 'Mutta naineelle käsken, en minä, vaan Herra, ettei vaimon pidä miehestänsä eriämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 11, 'Mutta jos hän eriää, niin olkoon naimatta taikka sopikaan miehensä kanssa, ja älköön mies hyljätkö vaimoansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 12, 'Vaan muille sanon minä ja ei Herra: jos jollakin veljellä on uskotoin vaimo, ja se mielistyy hänen kanssansa asumaan, älköön sitä itsestänsä eroittako.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 13, 'Ja jos jollakin vaimolla on uskotoin mies, ja hän tahtoo sen kanssa asua, älköön häntä itsestänsä eroittako.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 14, 'Sillä uskotoin mies on vaimonsa kautta pyhitetty, ja uskotoin vaimo on pyhitetty miehensä kautta: Muutoin olisivat teidän lapsenne saastaiset, vaan nyt ne ovat pyhitetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 15, 'Mutta jos uskotoin itsensä eroittaa, niin olkoot eroitetut. Eipä veli taikka sisar ole sidottu orjuuteen senmuotoisissa menoissa; mutta rauhassa on Jumala meitä kutsunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 16, 'Sillä kuinkas tiedät, vaimo, jos sinä miehes taidat autuaaksi saattaa? Eli sinä mies, kuinkas tiedät, jos sinä taidat vaimos autuaaksi saattaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 17, 'Kuitenkin niinkuin Jumala kullekin on jakanut: jokainen niin vaeltakaan, kuin Herra on hänen kutsunut: ja niin minäkin kaikissa seurakunnissa säädän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 18, 'Jos joku ympärileikattu on kutsuttu, älkään se esinahkaa pyytäkö: jos joku on esinahasta kutsuttu, älkään se antako itsiänsä ympärileikata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 19, 'Ympärileikkaus ei ole mitään, eikä esinahka mitään ole, vaan Jumalan käskyin pitämys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 20, 'Jokainen pysyköön siinä kutsumisessa, johonka hän kutsuttu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 21, 'Jos sinä olet orjaksi kutsuttu, älä sitä murehdi: kuitenkin jos sinä taidat vapaaksi tulla, niin nautitse sitä paremmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 22, 'Sillä joka orjaksi on Herrassa kutsuttu, se on Herran vapaa: niin myös joka vapaaksi on kutsuttu, hän on Kristuksen orja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 23, 'Te olette kalliisti ostetut! älkäät ihmisten orjat olko!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 24, 'Itsekukin, rakkaat veljet, jossa hän kutsuttu on, olkaan siinä Jumalan tykönä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 25, 'Mutta neitseistä ei ole minulla Herran käskyä; kuitenkin sanon minä minun neuvoni niinkuin laupiuden saanut Herralta uskollisena ollakseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 26, 'Minä luulen siis sen hyväksi, nykyisen tuskan tähden, että ihmisen on niin hyvä olla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 27, 'Jos sinä olet vaimoon sidottu, älä pyydä eroa; jos sinä olet vaimotoin, niin älä pyydä vaimoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 28, 'Mutta jos sinä myös olet nainut, et sinä syntiä tehnyt, ja jos neitsy huoli, ei hänkään syntiä tehnyt. Kuitenkin senkaltaiset saavat vaivan ruumiisensa. Mutta minä säästäisin mielelläni teitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 29, 'Mutta sen minä sanon, rakkaat veljet, aika on lyhetty. Mitä enempi? Joilla vaimot ovat, olkaan niinkuin ei heillä olisikaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 30, 'Ja jotka itkevät, niinkuin ei he itkisikään: ja jotka iloitsevat, niinkuin ei iloitsisikaan: ja jotka ostavat, niinkuin ei nautitsisikaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 31, 'Ja jotka tätä maailmaa viljelevät, ettei he sitä väärin käyttäisi; sillä tämän maailman meno on menevä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 32, 'Mutta minä tahtoisin, että te ilman murhetta olisitte: naimatoin tottelee niitä, jotka Herran ovat, kuinka hänen pitää Herralle kelpaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 33, 'Mutta joka nai, hän suree maailmallisista, kuinka hän emännällensä kelpais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 34, 'Nämät ovat eroitetut, vaimo ja neitsy, joka ei naitu ole, se murehtii niitä, jotka Herran ovat, että hän pyhä olis sekä ruumiilla että hengellä; mutta se, joka naitu on, murehtii maailmallisista, kuinka hänen pitää miehellensä kelpaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 35, 'Mutta senkaltaista sanon minä teidän tarpeeksenne: ei, että minä paulan teidän päällenne heittäisin, vaan että te soveliaasti ja hyvin Herrassa riippuisitte, ilman eroittamatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 36, 'Mutta jos joku luulee, ettei se sovi hänen neitseellensä, sittekuin hän jo naitavissa on, eikä saa toisin olla, niin tehkään, mitä hän tahtoo, ei hän syntiä tee; sallikaan hänen huolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 37, 'Mutta joka seisoo vahvana sydämessänsä ja ei ole vaadittu, vaan hänellä on oma ehtonsa ja päättää sen sydämessänsä, että hän tahtoo neitseensä pitää, se tekee hyvin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 38, 'Sentähden joka naittaa, se tekee hyvin; mutta joka ei naita, hän tekee paremmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 39, 'Vaimo on sidottu lakiin, niinkauvan kuin hänen miehensä elää; vaan kuin hänen miehensä kuollut on, niin hän on vapaa toiselle huolemaan, kelle hän tahtoo; ainoasti että se Herrassa tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 40, 'Vaan hän on autuaampi, minun luullakseni, jos hän sillänsä pysyy; sillä minä luulen, että minullakin on Jumalan Henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 1, 'Epäjumalain uhreista me tiedämme, että kaikilla meillä on tieto. Tieto paisuttaa, mutta rakkaus rakentaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 2, 'Mutta jos joku luulee jotakin tietävänsä, ei hän vielä mitään tiedä, kuin hänen tulis tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 3, 'Mutta jos joku Jumalaa rakastaa, se on tuttu häneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 4, 'Niin me nyt tiedämme siitä ruasta, joka epäjumalille uhrataan, ettei yhtään epäjumalaa maailmassa olekaan, ja ettei yhtään muuta Jumalaa ole kuin yksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 5, 'Ja vaikka muutamat ovat, jotka jumaliksi kutsutaan, olkoon se taivaassa eli maan päällä, (niinkuin monta jumalaa ja monta herraa on:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 6, 'Niin on kuitenkin meillä yksi Jumala, Isä, josta kaikki ovat, ja me hänessä, ja yksi Herra Jesus Kristus, jonka kautta kaikki ovat, ja me hänen kauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 7, 'Mutta ei jokaisella ole tietoa; sillä muutamat tekevät itsellensä omantunnon epäjumalista ja syövät niinkuin epäjumalille uhrattua, ja että heidän omatuntonsa on heikko, niin se saastutetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 8, 'Mutta ei ruoka meitä saata otolliseksi Jumalan edessä; jos me syömme, emme siitä rikkaammaksi tule; ellemme taas syö, emmepä me sentähden köyhemmäksi tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 9, 'Vaan katsokaat, ettei tämä teidän vapautenne tulisi heikoille pahennukseksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 10, 'Sillä jos joku näkee sinun, jolla tieto on, atrioitsevan epäjumalain huoneissa, eikö siitä omatunto, joka heikko on, yllytetä epäjumalain uhria syömään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 11, 'Ja niin sinun tietos kautta sinun veljes hukkaantuu, joka heikko on, jonka tähden Kristus on kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 12, 'Mutta kuin te niin syntiä teette veljiänne vastaan ja särjette heidän heikon omantuntonsa, niin te Kristusta vastaan syntiä teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 13, 'Sentähden jos ruoka minun veljeni pahentais, niin en minä ikänäni söisi lihaa, etten minä veljeäni pahentaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 1, 'Enkö minä ole apostoli? Enkö minä vapaa ole? Enkö minä meidän Herraa Jesusta Kristusta nähnyt? Ettekö te ole minun työni Herrassa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 2, 'Ellen minä ole muille apostoli, niin minä tosin teille olen; sillä te olette minun apostolivirkani sinetti Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 3, 'Niille, jotka minulta kysyvät, on tämä minun edesvastaukseni:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 4, 'Eikö meillä ole valta syödä ja juoda?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 5, 'Eikö meillä ole valta sisarta vaimona kanssamme ympäri viedä, niinkuin muillakin apostoleilla, ja Herran veljillä, ja Kephaalla?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 6, 'Eli minullako yksin ja Barnabaalla ei ole valtaa olla työtä tekemättä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 7, 'Kuka sotii koskaan omalla kulutuksellansa? Kuka istuttaa viinatarhan ja ei syö sen hedelmästä? Eli kuka karjaa kaitsee ja ei syö karjan rieskasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 8, 'Puhunenko minä näitä ihmisten tavalla? Eikö myös laki sitä sano?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 9, 'Sillä Moseksen laissa on kirjoitettu: Ei sinun pidä sitoman kiinni riihtä tappavan härjän suuta. Sureneeko Jumala härkiä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 10, 'Taikka, eikö hän sitä kaiketi meidän tähtemme sano? sillä meidän tähtemme on se kirjoitettu: että se joka kyntää, hänen pitää toivossa kyntämän, ja joka riihtä tappaa, hänen pitää toivossa riihtä tappaman, että hän toivostansa osalliseksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 11, 'Jos me olemme teille hengellisiä kylväneet; paljoko se on, jos me teidän ruumiillisianne niitämme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 12, 'Jos muut ovat tässä vallassa osalliset teidän tykönänne, miksi emme siis paljoa enemmin? mutta emmepä me ole sitä valtaa pitäneet, vaan me kärsimme kaikkinaisia, ettemme Kristuksen evankeliumille mitään estettä tekisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 13, 'Ettekö te tiedä, että ne, jotka uhraavat, ne syövät uhrista, ja ne, jotka alttaria valmistavat, ne alttarista osalliseksi tulevat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 14, 'Niin on myös Herra säätänyt, että ne, jotka evankeliumia ilmoittavat, pitää evankeliumista elatuksensa saaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 15, 'Mutta en minä ole kuitenkaan mitään näistä tehnyt. Vaan en minä sentähden sitä kirjoita, että niin pitäis minun kanssani tapahtuman. Parempi olis minun kuolla kuin että joku minun kerskaamiseni tyhjäksi tekis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 16, 'Mutta että minä evankeliumia saarnaan, niin ei minun tarvitse siitä öykätä; sillä minun tulee se tehdä. Voi minua, ellen minä evankeliumia ilmoita!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 17, 'Sillä jos minä sen mielelläni teen, niin minulla on palkka; mutta jos minä ylönmielin sen teen, niin on se virka kuitenkin minulle uskottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 18, 'Mitäs siis minun palkkani on? että minä Kristuksen evankeliumia saarnaan, ja teen sen ilman vapauttani evankeliumissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 19, 'Sillä ehkä minä olen vapaa jokaisesta, niin minä olen kuitenkin minuni tehnyt jokaisen palveliaksi, että minä sitä usiammat voittaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 20, 'Ja olen Juudalaisille tehty niinkuin Juudalainen, että minä Juudalaiset voittaisin; niille jotka lain alla ovat, niinkuin lain alainen, että minä ne, jotka lain alla ovat, voittaisin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 21, 'Niille jotka ilman lakia ovat, niinkuin minä ilman lakia olisin, (vaikka en minä ilman lakia Jumalan edessä ole, vaan olen Kristuksen laissa,) että minä ne, jotka ilman lakia ovat, voittaisin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 22, 'Heikoille olen minä tehty niinkuin heikko, että minä heikot voittaisin. Minä olen kaikille tehty kaikiksi, että minä kaiketi muutamat autuaaksi saattaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 23, 'Mutta sen minä teen evankeliumin tähden, että minä siitä osalliseksi tulisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 24, 'Ettekö te tiedä, että ne, jotka kiistassa juoksevat, kaikki tosin he juoksevat, vaan yksi palkan ennättää? Juoskaat siis niin, että te käsittäisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 25, 'Mutta jokainen joka kilvoittelee, kaikista hän itsensä pitää pois. Ne tosin sitä varten, että he katoovaisen kruunun saisivat; mutta me katoomattoman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 26, 'Mutta en minä niin juokse kuin tietämättömän puoleen, ja minä kilvoittelen, ei niinkuin tuulta pieksäin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 27, 'Vaan minä kuritan ruumistani ja painan sitä alas, etten minä, joka muille saarnaan, itse hyljättäväksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 1, 'Mutta en minä tahdo sitä teiltä, rakkaat veljet, salata, että meidän isämme ovat kaikki pilven alla olleet ja kaikki meren lävitse vaeltaneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 2, 'Ja kaikki Mosekseen kastetut pilvessä ja meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 3, 'Ja ovat kaikki yhtäläistä hengellistä ruokaa syöneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 4, 'Ja kaikki yhtäläistä hengellistä juomaa juoneet; sillä he joivat siitä hengellisestä kalliosta, joka heitä seurasi; mutta se kallio oli Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 5, 'Mutta ei heistä monta olleet Jumalalle otolliset; sillä he maahan lyötiin korvessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 6, 'Mutta nämä olivat meille esikuvaksi, ettemme pahaa himoitsisi, niinkuin he himoitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 7, 'Älkäät siis olko epäjumalain palveliat, niinkuin muutamat heistä, niinkuin kirjoitettu on: kansa istui syömään ja juomaan, ja nousi mässäämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 8, 'Älkäämme huorin tehkö, niinkuin muutamat heistä itsensä huoruudella saastuttivat ja lankesivat yhtenä päivänä kolmekolmattakymmentä tuhatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 9, 'Älkäämme Kristusta kiusatko, niinkuin myös muutamat heistä kiusasivat ja surmattiin kärmeiltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 10, 'Älkäät napisko, niinkuin muutamat heistä napisivat ja hukattiin kadottajalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 11, 'Mutta kaikki nämä tulivat heidän kohtaansa esikuvaksi; vaan se on kirjoitettu meille karttamiseksi, joidenka päälle maailman loput tulleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 12, 'Sentähden joka luulee seisovansa, katsokaan, ettei hän lankee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 13, 'Eipä yksikään kiusaus ole teitä käsittänyt, vaan inhimillinen; mutta Jumala on uskollinen, joka ei salli teitä kiusattaa ylitse teidän voimanne; vaan hän tekee myös kiusauksesta lopun, että te sen voisitte kärsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 14, 'Sentähden, minun rakkaani, paetkaat epäjumalain palvelusta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 15, 'Minä puhun niinkuin toimellisille: tuomitkaat te, mitä minä sanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 16, 'Se siunattu kalkki, jota me siunaamme, eikö se ole Kristuksen veren osallisuus? Se leipä, jonka me murramme, eikö se ole Kristuksen ruumiin osallisuus?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 17, 'Sillä se on yksi leipä, niin mekin monta olemme yksi ruumis; sillä me kaikki yhdestä leivästä olemme osalliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 18, 'Katsokaat Israelia lihan jälkeen: eikö ne, jotka uhria syövät, ole alttarista osalliset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 19, 'Mitäs siis minä sanon, että epäjumalat jotakin ovat, eli jos epäjumalain uhri jotakin on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 20, 'Mutta sen minä sanon: mitä pakanat uhraavat, sen he perkeleille uhraavat ja ei Jumalalle. En minä tahdo, että teidän pitää oleman perkeleistä osalliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 21, 'Ette taida Herran kalkkia juoda ja perkeleiden kalkkia. Ette taida osalliset olla Herran pöydästä ja perkeleiden pöydästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 22, 'Eli tahdommeko me Herraa härsytellä? Olemmeko me häntä väkevämmät?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 23, 'Kaikki tosin ovat minulle luvalliset, vaan ei kaikki ole tarpeelliset. Kaikki ovat minulle luvalliset, mutta ei kaikki tapahdu parannukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 24, 'Älkään kenkään omaa parastansa katsoko, vaan toisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 25, 'Kaikkea, mitä teurashuoneessa myydään, syökäät ja älkäät omantunnon tähden kyselkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 26, 'Sillä maa on Herran, ja kaikki mitä siinä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 27, 'Mutta kuin joku uskomatoin teitä vieraaksi kutsuu ja te mennä tahdotte, niin syökäät kaikkia, mitä teidän eteenne tuodaan ja älkäät omantunnon tähden kyselkö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 28, 'Mutta jos joku silloin teille sanois: tämä on epäjumalain uhri, niin älkäät syökö, hänen tähtensä, joka sen ilmoitti, ja omantunnon tähden. Sillä maa on Herran ja kaikki mitä siinä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 29, 'Mutta minä sanon omastatunnosta: ei sinun, vaan toisen; sillä minkätähden minun vapauteni tuomitaan toisen omaltatunnolta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 30, 'Sillä koska minä sen kiitoksella nautitsen, miksis minua pilkataan sen edestä, josta minä kiitän?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 31, 'Jos te nyt syötte eli juotte, eli mitä te teette, niin tehkäät kaikki Jumalan kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 32, 'Olkaat ilman pahennusta sekä Juudalaisille että Grekiläisille ja Jumalan seurakunnalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 33, 'Niinkuin minä kaikissa kaikille kelpaan ja en etsi omaa parastani, vaan monen, että he autuaaksi tulisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 1, 'Olkaat minun seuraajani, niinkuin minäkin Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 2, 'Mutta minä kiitän teitä, rakkaat veljeni, että te minua kaikissa muistatte, ja että te pidätte ne säädyt, jotka minä teille annoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 3, 'Mutta minä tahdon, että teidän pitää tietämän, että Kristus on jokaisen miehen pää; mutta mies on vaimon pää, ja Jumala on Kristuksen pää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 4, 'Jokainen mies, joka rukoilee eli propheteeraa, ja pitää jotakin päänsä päällä, se häpäisee päänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 5, 'Mutta jokainen vaimo, joka rukoilee eli propheteeraa peittämättömällä päällä, se häpäisee päänsä; sillä se on niinkuin se ajeltu olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 6, 'Sillä ellei vaimo anna itsiänsä peittää, niin kerittäkään myös hänen hiuksensa; vaan että se on ruma, että vaimon pitäis keritty eli ajeltu oleman, niin peittäkään päänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 7, 'Mutta ei miehen pidä päätänsä peittämän, sillä hän on Jumalan kuva ja kunnia; mutta vaimo on miehen kunnia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 8, 'Sillä ei mies ole vaimosta, mutta vaimo on miehestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 9, 'Ja ei mies ole luotu vaimon tähden, mutta vaimo on luotu miehen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 10, 'Sentähden pitää vaimon pitämän voiman päänsä päällä enkelitten tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 11, 'Muutoin ei ole mies paitsi vaimoa, eikä vaimo paitsi miestä, Herrassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 12, 'Sillä niinkuin vaimo on miehestä, niin on myös mies vaimon kautta; mutta kaikki Jumalasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 13, 'Tuomitkaat itse keskenänne: onko se kaunis, että vaimo avopäin Jumalaa rukoilee?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 14, 'Eikö luontokin sitä teille opeta, että se on miehelle häpiäksi, jos hänellä on pitkät hiukset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 15, 'Mutta vaimolle on se kunniaksi, että hänellä on pitkät hiukset; sillä hiukset ovat hänelle peitteeksi annetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 16, 'Mutta jos joku näkyy riitainen olevan, ei meillä eikä Jumalan seurakunnilla se tapa ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 17, 'Mutta kuin minä tätä teille ilmoitan, en minä teitä kiitä, ettette kokoon tule parannukseksi, vaan pahennukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 18, 'Sillä ensin, kuin te seurakuntaan tulette, niin minä kuulen eripuraisuudet olevan seassanne; jonka minä myös puolittain uskon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 19, 'Sillä teidän seassanne pitää myös eriseurat oleman, että ne, jotka koetellut ovat, teidän seassanne ilmoitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 20, 'Kuin te siis kokoon tulette yhteen, ei se ole Herran ehtoollista pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 21, 'Sillä jokainen ennättää syödä oman ehtoollisensa, yksi isoo, toinen juovuksissa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 22, 'Vai eikö teillä huoneita ole, joissa te syödä ja juoda saatte? Taikka katsotteko te ylön Jumalan seurakunnan ja häpäisette ne, joilla ei mitään ole? Mitä minun pitää teille sanoman? Pitääkö minun teitä kiittämän? Tässä en minä kiitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 23, 'Sillä minä olen sen Herralta saanut, jonka minä myös teille annoin. Sillä Herra Jesus, sinä yönä, jona hän petettiin, otti leivän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 24, 'Ja kiitti, mursi ja sanoi: ottakaat, syökäät! tämä on minun ruumiini, joka teidän edestänne murretaan: se tehkäät minun muistokseni;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 25, 'Niin myös kalkin ehtoollisen jälkeen ja sanoi: tämä kalkki on se Uusi Testamentti minun veressäni; se tehkäät, niin usein kuin te juotte, minun muistokseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 26, 'Sillä niin usein kuin te syötte tästä leivästä ja juotte tästä kalkista, pitää teidän Herran kuoleman julistaman, siihenasti kuin hän tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 27, 'Sentähden joka kelvottomasti syö tästä leivästä ja juo Herran kalkista, se on vikapää Herran ruumiiseen ja vereen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 28, 'Mutta koetelkaan ihminen itsiänsä, ja niin syökään tästä leivästä ja juokaan tästä kalkista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 29, 'Sillä joka syö taikka juo kelvottomasti, hän syö ja juo tuomion itsellensä, ettei hän Herran ruumista eroita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 30, 'Sentähden on myös monta heikkoa ja sairasta teidän seassanne, ja moni makaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 31, 'Sillä jos me itsemme tuomitsisimme, niin emme ensinkään tuomittaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 32, 'Vaan kuin me tuomitaan, niin me Herralta kuritetaan, ettemme maailman kanssa kadotettaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 33, 'Sentähden, rakkaat veljeni! kuin te kokoon tulette syömään, niin odottakaat toinen toistanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 34, 'Mutta jos joku isoo, hän syököön kotonansa, ettette kokoon tulisi kadotukseksi. Ne muut minä tultuani tahdon toimittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 1, 'Mutta hengellisistä lahjoista, rakkaat veljet, en minä tahdo teiltä salata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 2, 'Te tiedätte, että te olette pakanat olleet ja käyneet mykkäin epäjumalain tykö, niinkuin te viedyt olitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 3, 'Sentähden teen minä teille tiettäväksi, ettei yksikään, joka Jumalan Hengen kautta puhuu, Jesusta kiroile: ja ei yksikään taida Jesusta kutsua Herraksi, vaan Pyhän Hengen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 4, 'Lahjat ovat moninaiset, mutta yksi on Henki;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 5, 'Ja virat ovat moninaiset, mutta yksi on Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 6, 'Ja voimat ovat moninaiset, mutta yksi on Jumala, joka kaikki kaikissa vaikuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 7, 'Mutta jokaiselle annetaan Hengen ilmoitus hyödytykseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 8, 'Sillä yhdelle annetaan Hengen kautta puhua viisaudesta, toiselle puhua tiedosta, sen yhden Hengen kautta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 9, 'Mutta toiselle usko siitä yhdestä Hengestä: toiselle lahjat terveeksi tehdä siinä yhdessä Hengessä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 10, 'Toiselle voimallisia töitä tehdä, toiselle ennustus, toiselle henget eroittaa, toiselle moninaiset kielet, toiselle moninaisten kielten selitys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 11, 'Mutta nämät kaikki se yksi Henki vaikuttaa, jakaen kullekin omansa niinkuin hän tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 12, 'Sillä niinkuin ruumis on yksi, ja hänellä on monta jäsentä, mutta kaikki ruumiin jäsenet, ehkä heitä on usia, ovat kuitenkin yksi ruumis; niin on myös Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 13, 'Sillä me olemme myös yhdessä Hengessä kaikki yhdeksi ruumiiksi kastetut, sekä Juudalaiset että Grekiläiset, sekä orjat että vapaat, ja kaikki me olemme yhteen Henkeen juotetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 14, 'Sillä ei ruumis ole yksi jäsen, vaan usia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 15, 'Jos jalka sanois: en minä ole käsi, sentähden en minä ole ruumiista: eikö hän senvuoksi ole ruumiista?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 16, 'Ja jos korva sanois: en minä ole silmä, sentähden en minä ole ruumiista: eikö hän senvuoksi ruumiista ole?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 17, 'Jos koko ruumis silmänä olis, kussas siis kuulo? Jos se kaikki kuulona, kussas siis haisto?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 18, 'Mutta nyt on Jumala pannut jäsenet erinänsä itsekunkin ruumiissa niinkuin hän on tahtonut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 19, 'Vai jos kaikki olisivat yksi jäsen, kussa sitte ruumis olis?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 20, 'Mutta nyt on monta jäsentä, vaan yksi ruumis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 21, 'Mutta ei silmä taida kädelle sanoa: en minä sinua tarvitse, eli taas pää jaloille: en minä teitä tarvitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 22, 'Vaan paljoa enemmin ne ruumiin jäsenet, jotka heikommaksi näkyvät, ovat tarpeelliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 23, 'Ja jotka me luulemme häpiällisemmäksi ruumiissa, niiden päälle me enimmän kunnian panemme; ja jotka häijymmäksi näkyvät, niillä on enin kaunistusta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 24, 'Sillä jotka meissä kauniit ovat, ei ne mitään tarvitse; mutta Jumala on ruumiin kokoon liittänyt ja sille puuttuvaiselle enemmän kunnian antanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 25, 'Ettei eripuraisuutta ruumiissa olisi; vaan kaikki jäsenet pitää toinen toisestansa surun pitämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 26, 'Ja jos yksi jäsen kärsii jotakin, niin kaikki muut jäsenet kanssa kärsivät, ja jos yksi jäsen kunniassa pidetään, niin kaikki jäsenet myös riemuitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 27, 'Mutta te olette Kristuksen ruumis ja jäsenet, jokainen osansa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 28, 'Ja Jumala on pannut seurakuntaan ensin apostolit, sitte prophetat, senjälkeen opettajat, sitte voimalliset työt, jälleen parantamisen lahjat, avut, hallitukset, moninaiset kielet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 29, 'Ovatko kaikki apostolit? Ovatko kaikki prophetat? Ovatko kaikki opettajat? Onko kaikilla voimalliset työt?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 30, 'Onko kaikilla parantamisen lahjat? Puhuvatko kaikki moninaisilla kielillä? Taitavatko kaikki selittää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 31, 'Mutta noudattakaat te paraita lahjoja. Ja vielä minä teille korkiamman tien osoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 1, 'Jos minä ihmisten ja enkelein kielillä puhuisin, ja ei minulla olisi rakkautta, niin minä olisin kuin helisevä vaski tai kilisevä kulkuinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 2, 'Ja jos minä propheteerata taitaisin, ja kaikki salaisuudet tietäisin ja kaiken tiedon, ja minulla olis kaikki usko, niin että minä vuoret siirtäisin, ja ei olisi minulla rakkautta, niin en minä mitään olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 3, 'Ja jos minä kaiken tavarani kuluttaisin köyhäin ravinnoksi, ja jos minä antaisin ruumiini poltettaa, ja ei olisi minulla rakkautta, niin ei se olisi minulle mitään hyödyllinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 4, 'Rakkaus on kärsivällinen ja laupias. Ei rakkaus kadehdi, ei rakkaus ole tyly, ei hän paisu:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 5, 'Ei hän käytä itsiänsä sopimattomasti, ei omaansa etsi, ei hän vihaan syty, ei hän pahaa ajattele,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 6, 'Ei hän vääryydestä iloitse, mutta hän iloitsee totuudesta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 7, 'Kaikki hän peittää, kaikki hän uskoo, kaikki hän toivoo, kaikki hän kärsii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 8, 'Ei rakkaus koskaan väsy; vaikka prophetiat lakkaavat, ja kielet vaikenevat, ja tieto katoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 9, 'Sillä me ymmärrämme puolittain, ja propheteeraamme puolittain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 10, 'Mutta kuin täydellinen tulee, sitte vajaa lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 11, 'Kuin minä olin lapsi, niin minä puhuin kuin lapsi, minulla oli lapsen mieli ja ajattelin kuin lapsi; mutta sitte kuin minä mieheksi tulin, niin minä hylkäsin lapselliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 12, 'Sillä nyt me näemme niinkuin peilistä tapauksessa, mutta silloin kasvoista kasvoihin: nyt minä tunnen puolittain, vaan silloin minä tunnen niiinkuin minä tuttu olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 13, 'Mutta nyt pysyvät usko, toivo, rakkaus, nämät kolme; vaan rakkaus on suurin niistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 1, 'Noudattakaat rakkautta, olkaat ahkerat hengellisten lahjain perään; mutta enemmin propheteeraamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 2, 'Sillä joka kielillä puhuu, ei hän ihmisille puhu, vaan Jumalalle; sillä ei kenkään kuule, vaan hän puhuu salaisuudet hengessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 3, 'Mutta joka propheteeraa, se puhuu ihmisille parannukseksi ja neuvoksi ja lohdutukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 4, 'Joka kielillä puhuu, hän parantaa itsensä; mutta joka propheteeraa, hän seurakunnan parantaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 5, 'Mutta minä tahtoisin, että te kaikki kielillä puhuisitte, mutta paljoa enemmin, että te propheteeraisitte; sillä se, joka propheteeraa, on suurempi kuin se, joka kielillä puhuu, paitsi sitä jos hän sen selittää, että seurakunta sais siitä parannuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 6, 'Vaan nyt, rakkaat veljeni! jos minä tulen teidän tykönne kielillä puhuen, mitä minä olisin teille hyödyllinen, ellen minä puhuisi teille eli ilmoituksen kautta, eli tiedon kautta, eli prophetian kautta, taikka opin kautta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 7, 'Kuitenkin ne hengettömät, jotka äänen antavat, joko se on huilu eli kantele, koska ei ne anna eri ääntä itsestänsä, kuinka se tiedetään, mitä huilulla eli mitä kanteleella soitettu on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 8, 'Ja jos vaskitorvi antaa ymmärtämättömän äänen itsestänsä, kuka tietää sotaan hankita?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 9, 'Niin myös te, jos te kielillä puhutte ja ette puhu selkiästi; kuinka se ymmärretään, mitä puhuttu on? Sillä te puhutte tuuleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 10, 'Moninaiset tosin ovat äänet maailmassa, ja ei yhtään niistä ole äänetöintä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 11, 'Sentähden, ellen minä tiedä äänen tointa, niin minä olen puhujalle outo, ja se, joka puhuu, on myös minulle outo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 12, 'Niin tekin, koska te ahkerasti hengellisiä lahjoja etsitte, niin ahkeroitkaat seurakunnan parannukseksi, että teillä kyllä olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 13, 'Sentähden, joka kielillä puhuu, se rukoilkaan, että hän sen taitais myös selittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 14, 'Sillä jos minä kielillä rukoilen, niin minun henkeni rukoilee, mutta minun mieleni on hedelmätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 15, 'Kuinkas se siis on? Minä rukoilen hengessä, ja rukoilen myös mielessäni: minä veisaan hengessä, ja veisaan myös mielessäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 16, 'Mutta koska sinä hengessä siunaat, kuinkas se, joka oppimattoman siassa on, pitää sinun kiitoksees amen sanoman? sillä ei hän ymmärrä, mitäs sanot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 17, 'Sinä tosin hyvästi kiität, vaan ei se toinen siitä parane.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 18, 'Minä kiitän minun Jumalaani, että minä taidan usiammalla kielellä puhua kuin te kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 19, 'Mutta seurakunnassa tahdon minä paremmin viisi sanaa puhua minun mielestäni, muita neuvoakseni, ennen kuin kymmenentuhatta sanaa kielillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 20, 'Rakkaat veljet, älkäät olko lapset taidossa; vaan olkaat lapset pahuudessa, mutta olkaat taidossa täydelliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 21, 'Laissa on kirjoitettu: minä tahdon puhua tälle kansalle toisilla kielillä ja toisilla huulilla, ja ei he sittekään minua kuule, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 22, 'Niin siis kielet ovat merkiksi, ei niille, jotka uskovat, vaan niille, jotka ei usko; mutta ei prophetiat ole uskottomain, vaan uskovaisten tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 23, 'Sentähden jos koko seurakunta yhteen paikkaan kokoontuis ja kaikki puhuisivat kielillä ja sinne tulisivat oppimattomat taikka uskottomat; eikö he teitä mielipuoleksi sanoisi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 24, 'Mutta jos te kaikki propheteeraisitte, ja sinne tulis joku uskomatoin taikka oppimatoin, ja hän nuhdeltaisiin kaikilta ja tuomittaisiin kaikilta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 25, 'Ja niin hänen sydämensä salaudet julki tulisivat, ja hän lankeais kasvoillensa ja rukoilis Jumalaa, tunnustain että Jumala olis totisesti teissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 26, 'Kuinkas se on, rakkaat veljet? Koska te kokoon tulette, niin kullakin teistä on psalmi, hänellä on opetus, hänellä on kieli, hänellä on ilmoitus, hänellä on selitys: ne tapahtukoon kaikki parannukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 27, 'Jos joku kielillä puhuu, se puhukaan itse toisena, taikka ensinnäkin itse kolmantena, ja vuorottain, ja yksi sen selittäkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 28, 'Ellei hän selittäjä ole, niin olkaan seurakunnassa ääneti ja puhukaan itsellensä ja Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 29, 'Mutta prophetat puhukaan itse toisena, eli itse kolmantena, ja ne muut tuomitkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 30, 'Ja jos jollekulle tykönä istuvalle ilmoitus tapahtuu, niin olkaan ensimäinen ääneti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 31, 'Sillä kyllä te kaikki propheteerata taidatte, yksi toisenne perään, että kaikki oppisivat ja tulisivat neuvotuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 32, 'Ja prophetain henget ovat prophetaille alamaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 33, 'Sillä ei Jumala ole sekaseuraisuuden, vaan rauhan Jumala, niinkuin kaikissa pyhäin seurakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 34, 'Teidän vaimonne pitää seurakunnissa ääneti oleman; sillä ei heille ole sallittu puhua, vaan että he ovat alamaiset, niinkuin myös laki sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 35, 'Mutta jos he jotain oppia tahtovat, niin kysykööt miehiltänsä kotona; sillä häijysti se vaimoille sopii, että he seurakunnassa puhuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 36, 'Eli onko Jumalan sana teistä tullut? Taikka onko se ainoasti teidän tykönne tullut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 37, 'Jos joku luulee itsensä prophetaksi, eli hengelliseksi, se tutkikaan, mitä minä teille kirjoitan, että ne ovat Herran käskyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 38, 'Mutta jos joku on tietämätöin, se olkoon tietämätöin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 39, 'Sentähden rakkaat veljet, ahkeroitkaat propheteerata ja älkäät kieltäkö kielillä puhumasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 40, 'Kaikki tapahtukoon soveliaasti ja säädyllisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 1, 'Mutta minä teen teille tiettäväksi, rakkaat veljet, sen evankeliumin, jonka minä teille ilmoitin, jonka te myös saaneet olette, jossa te myös seisotte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 2, 'Jonka kautta te myös autuaaksi tulette, jos te sen pidätte, minkä minä teille olen ilmoittanut, ellette hukkaan ole uskoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 3, 'Sillä minä olen sen ensin teille antanut, jonka minä myös saanut olen, että Kristus on kuollut meidän synteimme tähden, Raamattuin jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 4, 'Ja että hän oli haudattu ja nousi ylös kolmantena päivänä Raamattuin jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 5, 'Ja että hän nähtiin Kephaalta ja sitte kahdeltatoistakymmeneltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 6, 'Senjälkeen hän nähtiin usiammalta kuin viideltäsadalta veljeltä yhdellä haavalla, joista monta vielä elävät, mutta muutamat ovat nukkuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 7, 'Sitälähin nähtiin hän Jakobilta ja sen jälkeen kaikilta apostoleilta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 8, 'Vaan kaikkein viimein on hän myös minulta nähty, niinkuin keskensyntyneeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 9, 'Sillä minä olen kaikkein huonoin apostolitten seassa enkä ole kelvollinen apostoliksi kutsuttaa, että minä olen Jumalan seurakuntaa vainonnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 10, 'Mutta Jumalan armosta minä olen se, mikä minä olen, ja hänen armonsa minun kohtaani ei ole tyhjä ollut, vaan minä olen enemmän työtä tehnyt kuin muut kaikki; mutta en kuitenkaan minä, vaan Jumalan armo, joka minussa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 11, 'Olisin siis minä eli he, näin me saarnaamme ja näin te olette myös uskoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 12, 'Mutta jos Kristus saarnataan kuolleista nousseeksi ylös; miksi siis teidän seassanne muutamat sanovat, ettei kuolleitten ylösnousemista ole?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 13, 'Mutta ellei kuolleitten ylösnousemus ole, niin ei Kristuskaan noussut ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 14, 'Mutta jollei Kristus noussut ylös, niin on meidän saarnamme turha ja teidän uskonne on myös turha,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 15, 'Ja me löydetään Jumalan vääriksi todistajiksi, että me Jumalaa vastaan todistaneet olemme, että hän on herättänyt ylös Kristuksen, jota ei hän ole herättänyt ylös, ellei kuolleet nouse ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 16, 'Sillä jollei kuolleet nouse ylös, eipä Kristuskaan noussut ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 17, 'Mutta ellei Kristus ole noussut ylös, niin on teidän uskonne turha, ja te olette vielä teidän synneissänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 18, 'Niin ovat myös ne, jotka Kristuksessa nukkuneet ovat, kadotetut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 19, 'Jos meillä ainoastaan tässä elämässä on toivo Kristuksen päälle, niin me olemme viheliäisemmät kaikkia muita ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 20, 'Mutta nyt on Kristus kuolleista noussut ylös ja on tullut uutiseksi nukkuneiden seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 21, 'Sillä että ihmisen kautta kuolema on, niin on myös ihmisen kautta kuolleitten ylösnousemus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 22, 'Sillä niinkuin kaikki Adamissa kuolevat, niin he myös kaikki pitää Kristuksessa eläväksi tehtämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 23, 'Mutta kukin järjestyksessänsä: uutinen Kristus, sitte ne, jotka Kristuksen omat ovat, hänen tulemisessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 24, 'Sitte on loppu, koska hän antaa valtakunnan Jumalan ja Isän haltuun, ja panee pois kaiken herrauden ja kaiken vallan ja voiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 25, 'Sillä hänen tulee hallita, siihenasti kuin hän kaikki vihollisensa panee hänen jalkainsa alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 26, 'Viimeinen vihollinen, joka pannaan pois, on kuolema.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 27, 'Sillä hän on kaikki hänen jalkainsa alle heittänyt. Mutta koska hän sanoo, että kaikki hänen allensa heitetyt ovat, niin on julki, että se on eroitettu, joka hänelle kaikki heitti alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 28, 'Kuin nyt kaikki hänen allensa heitetyksi tulevat, silloin myös itse Poika hänen allensa heitetään, joka kaikki hänen allensa heitti, että Jumala kaikki kaikessa olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 29, 'Mitä ne muutoin tekevät, jotka itsensä kastaa antavat kuolleitten päälle, jollei kuolleet nouse ylös? Miksi he siis antavat kuolleitten päälle itseänsä kastaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 30, 'Miksi myös me joka aika vaarassa olemme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 31, 'Minä kuolen joka päivä meidän kerskaamisen puolesta, joka minulla on Kristuksessa Jesuksessa meidän Herrassamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 32, 'Jos minä olen ihmisten tavalla Ephesossa petoin kanssa sotinut, mitä se minua auttaa, ellei kuolleet nouse ylös? Syökäämme ja juokaamme; sillä huomenna me kuolemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 33, 'Älkäät antako pettää teitänne: pahat jaaritukset turmelevat hyvät tavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 34, 'Herätkäät ylös hurskaasti ja älkäät syntiä tehkö; sillä ei muutamat Jumalasta mitään tiedä. Häpiäksi minä näitä teille sanon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 35, 'Vaan joku taitais sanoa: kuinkas kuolleet nousevat? ja minkäkaltaisilla ruumiilla he tulevat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 36, 'Sinä tomppeli! Se, minkä sinä kylvät, ei tule eläväksi, ellei hän (ensin) kuole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 37, 'Ja jonka sinä kylvät, ei se ole se ruumis, joka tuleva on, vaan paljas jyvä, nimittäin nisun jyvä eli joku muu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 38, 'Mutta Jumala antaa hänelle ruumiin niinkuin hän tahtoi, ja kullekin siemenelle oman ruumiinsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 39, 'Ei kaikki liha ole yhtäläinen liha; vaan toinen on ihmisten liha, toinen on karjan liha, toinen on kalain, toinen on lintuin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 40, 'Ja ovat taivaalliset ruumiit ja maalliset ruumiit; mutta toinen kirkkaus on taivaallisilla ja toinen maallisilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 41, 'Toinen kirkkaus on auringolla ja toinen kirkkaus kuulla, ja toinen kirkkaus tähdillä; sillä yksi tähti voittaa toisen kirkkaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 42, 'Niin myös kuolleitten ylösnousemus: se kylvetään turmeluksessa ja nousee ylös turmelematoin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 43, 'Se kylvetään huonona ja nousee ylös kunniassa, se kylvetään heikkoudessa ja nousee ylös väkevyydessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 44, 'Se kylvetään luonnollinen ruumis ja nousee hengellinen ruumis. Meillä on luonnollinen ruumis, on myös hengellinen ruumis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 45, 'Niinkuin myös kirjoitettu on: ensimäinen ihminen Adam on tehty eläväksi sieluksi, ja viimeinen Adam eläväksi tekeväiseksi hengeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 46, 'Mutta hengellinen ei ole ensimäinen, vaan luonnollinen, senjälkeen hengellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 47, 'Ensimäinen ihminen on maasta ja maallinen, toinen ihminen on itse Herra taivaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 48, 'Minkäkaltainen maallinen on, senkaltaiset ovat myös maalliset, ja minkäkaltainen taivaallinen on, senkaltaiset ovat myös taivaalliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 49, 'Ja niinkuin me olemme kantaneet maallisen kuvaa, niin pitää myös meidän kantaman taivaallisen kuvaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 50, 'Mutta minä sanon, rakkaat veljet, ei liha ja veri taida Jumalan valtakuntaa periä, ja ei turmeltu pidä turmelematointa perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 51, 'Katso, minä sanon teille salaisuuden: emme tosin kaikki nuku, vaan kaikki me muutetaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 52, 'Ajan rahdussa, silmänräpäyksessä, viimeisellä basunalla; sillä basuna soi, ja kuolleet pitää turmelematoinna nouseman ylös ja me tulemme muutetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 53, 'Sillä tämä katoova pitää pukeman päällensä katoomattomuuden ja kuoleva pukee päällensä kuolemattomuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 54, 'Mutta koska katoova pukee päällensä katoomattomuuden ja kuoleva pukee päällensä kuolemattomuuden, silloin täytetään se sana, joka kirjoitettu on: kuolema on nielty voitossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 55, 'Kuolema, kussa on sinun otas? Helvetti, kussa on sinun voittos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 56, 'Mutta kuoleman ota on synti ja synnin voima on laki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 57, 'Mutta kiitos olkoon Jumalan, joka meille voiton antanut on meidän Herran Jesuksen Kristuksen kautta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 58, 'Sentähden, minun rakkaat veljeni, olkaat vahvat, järkähtymättä ja aina yltäkylläiset Herran töissä, tietäen, ettei teidän työnne ole turha Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 1, 'Mutta avun hakemisessa pyhiä varten, niinkuin minä Galatin seurakunnille säätänyt olen, niin te myös tehkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 2, 'Ensimäisenä sabbattina ottakaan jokainen teistä tykönsä jotakin ja kootkaan varansa jälkeen, ettei äsken silloin, kuin minä tulen, niitä hakemaan ruveta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 3, 'Mutta kuin minä tullut olen, jotka te kirjoilla valitsette, ne minä tahdon lähettää viemään teidän lahjojanne Jerusalemiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 4, 'Jos taas niin on sovelias, että minä itse sinne vaellan, niin he saavat minun kanssani vaeltaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 5, 'Mutta minä tahdon teidän tykönne tulla, kuin minä Makedonian kautta vaellan. (Sillä minun pitää Makedonian lävitse vaeltaman.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 6, 'Mutta teidän tyköänne minä mitämaks viivyn eli myös talvea pidän, että te minua saattaisitte, kuhunka minä matkustan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 7, 'Sillä en minä nyt mennessäni tahdo teitä nähdä; sillä minä toivon saavani jonkun ajan viipyä teidän tykönänne, jos Herra sallii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 8, 'Mutta minä tahdon Ephesossa viipyä helluntaihin asti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 9, 'Sillä minulle on suuri ja väkevä ovi avattu, ja on monta vastaanseisojaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 10, 'Mutta jos Timoteus tulee, niin katsokaat, että hän pelkäämättä olis teidän tykönänne; sillä hän tekee myös Herran työtä niinkuin minäkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 11, 'Älkään häntä kenkään katsoko ylön, mutta saattakaat häntä rauhassa minun tyköni tulemaan; sillä minä odotan häntä veljien kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 12, 'Mutta veljestä Apollosta tietäkäät, että minä olen häntä paljon neuvonut veljien kanssa teidän tykönne tulemaan, mutta ei hän nyt tahtonut tulla; kuitenkin on hän tuleva, kuin hänellä sovelias aika on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 13, 'Valvokaat, pysykäät uskossa, olkaat urhoolliset, olkaat vahvat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 14, 'Kaikki teidän menonne tapahtukoon rakkaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 15, 'Mutta minä neuvon teitä, rakkaat veljet: te tunnette Stephanaan perheen, että he ovat alkeet Akajassa ja ovat ruvenneet pyhiä palvelemaan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 16, 'Että te myös olisitte senkaltaisille alamaiset ja jokaiselle apulaiselle ja auttajalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 17, 'Mutta minä iloitsen Stephanaan, Fortunatuksen ja Akaikuksen tulemisesta; sillä he ovat teidän puuttumisenne täyttäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 18, 'Sillä he virvoittivat minun henkeni ja teidän; sentähden tuntekaat senkaltaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 19, 'Teitä tervehtivät Asian seurakunnat. Teitä tervehtivät suuresti Akvila ja Priskilla Herrassa, ja seurakunta, joka heidän huoneessansa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 20, 'Teitä tervehtivät kaikki veljet. Tervehtikäät toinen toistanne pyhällä suunantamisella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 21, 'Minä Paavali tervehdin teitä omalla kädelläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 22, 'Joka ei Herraa Jesusta Kristusta rakasta, se olkoon anatema maranata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 23, 'Herran Jesuksen Kristuksen armo olkoon teidän kanssanne!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 24, 'Minun rakkauteni olkoon kaikkein teidän kanssanne Kristuksessa Jesuksessa! Amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Paavali, Jesuksen Kristuksen apostoli Jumalan tahdon kautta, ja Timoteus veli, Jumalan seurakunnalle, joka on Korintossa, ja kaikille pyhille, jotka koko Akajassa ovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Armo olkoon teille ja rauha Jumalalta meidän Isältämme ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Kiitetty olkoon Jumala ja meidän Herran Jesuksen Kristuksen Isä, laupiuden Isä, ja kaiken lohdutuksen Jumala!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Joka meitä lohduttaa kaikessa meidän vaivassamme, että me taitaisimme lohduttaa niitä, jotka kaikkinaisessa vaivassa ovat, sillä lohdutuksella, jolla Jumala meitä lohduttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Sillä niinkuin Kristuksen kärsimys on paljo tullut meidän päällemme, niin myös meille tulee paljo lohdutusta Kristuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Mutta jos meitä vaivataan, niin se tapahtuu teille lohdutukseksi ja autuudeksi, joka vaikuttaa niiden vaivain kärsivällisyydessä, joita myös me kärsimme, eli jos meitä lohdutetaan, niin se tulee teille lohdutukseksi ja autuudeksi; ja meidän toivomme on vahva teistä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Että me tiedämme, että niinkuin te olette kärsimisessä osalliset, niin te myös tulette lohdutuksesta osalliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Sillä emme tahdo salata teiltä, rakkaat veljet, meidän vaivaamme, joka meille Asiassa tapahtui: että me olimme sangen suuresti rasitetut ylitse meidän voimamme, niin että me jo meidän hengestämme epäilimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Mutta me itsellämme juuri niin päätimme, että meidän piti kuoleman, ettei meidän pitäisi itse päällemme uskaltaman, vaan Jumalan päälle, joka kuolleetkin herättää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Joka meitä niin suuresta kuolemasta päästi ja päästää; ja me turvaamme hänen päällensä, että hän tästedeskin meitä päästää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Ynnä myös teidän rukoustenne avulla meidän edestämme, että meidän tähtemme, siitä lahjasta, joka meille annettu on, pitäis monelta ihmiseltä kiitos tehtämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Sillä se on meidän kerskauksemme, nimittäin meidän omantuntomme todistus, että me yksinkertaisuudessa ja Jumalan vakuudessa, ei lihallisessa viisaudessa, vaan Jumalan armossa olemme maailmassa vaeltaneet, mutta enimmästi teidän tykönänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Sillä emmepä me muuta teille kirjoita, vaan sitä, mitä te luette eli myös tiedätte; mutta minä toivon, että te myös loppuun asti tiedätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Niinkuin te puolittain meidät tietäneet olette, että me olemme teidän kerskaamisenne, niinkuin tekin meidän kerskauksemme Herran Jesuksen päivänä olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Ja senkaltaisella uskalluksella tahdoin minä ennen tulla teidän tykönne, että te toisen kerran olisitte saaneet minulta jonkun hyvän työn,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'Ja minä olisin vaeltanut teidän kauttanne Makedoniaan, ja Makedoniasta teidän tykönne takaperin tullut, ja niin teiltä Juudeaan johdatetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'Koska minä tätä ajattelin, lienenkö minä sen tehnyt hempeydestä? Eli ovatko minun aivoitukseni, joita minä aivon, lihalliset? että minun tykönäni olis niin, niin, ja ei, ei.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, 'Mutta Jumala on vakaa, ettei meidän puheemme ole teille niin ja ei ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'Sillä Jumalan Poika, Jesus Kristus, joka teidän seassanne meiltä saarnattu on, nimittäin minulta ja Silvanukselta ja Timoteukselta, ei ollut niin ja ei, vaan oli hänessä niin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'Sillä kaikki Jumalan lupaukset ovat niin hänessä ja ovat amen hänessä, Jumalan kunniaksi meidän kauttamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 21, 'Mutta Jumala on se, joka meitä teidän kanssanne Kristuksessa vahvistaa, ja on meitä voidellut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 22, 'Joka myös on meitä lukinnut, ja antoi Hengen pantiksi meidän sydämiimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 23, 'Mutta minä rukoilen Jumalaa todistajaksi sieluni päälle, että minä olen säästänyt teitä, etten minä vielä ole Korintoon tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 24, 'Ei niin, että me hallitsisimme teidän uskoanne, vaan me olemme auttajat teidän iloonne, sillä te seisotte uskossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 1, 'Mutta sitä minä olen itselläni aikonut, etten minä taas murheella teidän tykönne tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 2, 'Sillä jos minä teidät murheeseen saatan, kukas minua ilahuttaa, vaan se, joka minulta on murheelliseksi tehty?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 3, 'Ja sen minä olen teille kirjoittanut, etten minä tultuani saisi niistä murhetta, joista minun tulis ilo saada; sillä minulla on senkaltainen uskallus kaikkein teidän tykönne, että minun iloni kaikkein teidän ilonne on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 4, 'Sillä minä kirjoitin teille suuressa vaivassa ja sydämen kivussa, monilla kyyneleillä, ei, että teidän pitäis murehtiman, vaan että te ymmärtäisitte sen erinomaisen rakkauden, joka minulla on teidän kohtaanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 5, 'Jos joku on murheen matkaan saattanut, ei hän ole minua murheelliseksi saattanut, vaan puolittain, etten minä teitä kaikkia rasittaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 6, 'Mutta kyllä siinä on, että se monelta niin rangaistu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 7, 'Että te tästedes sitä enemmän häntä armahtaisitte ja lohduttaisitte, ettei hän uppoaisi ylönpalttisessa murheessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 8, 'Sentähden neuvon minä teitä, että te hänen kohtaansa rakkautta osoittaisitte;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 9, 'Sillä sentähden minä myös olen kirjoittanut, koetellakseni teitä, jos te olette kaikkiin kuuliaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 10, 'Mutta joille te jotain anteeksi annatte, sen minä myös anteeksi annan; sillä jolle minä jotain anteeksi annoin, sen minä anteeksi annoin teidän tähtenne Kristuksen puolesta, ettemme saatanalta voitetuksi tulisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 11, 'Sillä eipä meiltä ole salattu, mitä hänen mielessänsä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 12, 'Mutta kuin minä tulin Troadaan Kristuksen evankeliumia saarnaamaan, ja minulle avattiin ovi Herrassa, niin ei minulla ollut yhtään lepoa hengessäni, etten minä Titusta minun veljeäni löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 13, 'Mutta kuin minä olin heidän hyvästi jättänyt, menin minä sieltä Makedoniaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 14, 'Mutta kiitetty olkoon Jumala, joka aina antaa meille voiton Kristuksessa, ja julistaa joka paikassa hänen tuntemisensa hajun meidän kauttamme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 15, 'Sillä me olemme Jumalalle yksi hyvä haju Kristuksessa, sekä niiden seassa, jotka autuaaksi tulevat, että myös niiden seassa, jotka hukkuvat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 16, 'Näille tosin surman haju kuolemaksi, mutta toisille elämän haju elämäksi: ja kuka on nyt tähän kelvollinen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 17, 'Sillä emmepä me ole senkaltaiset kuin muutamat, jotka Jumalan sanaa myyskentelevät; vaan vakuudesta ja niinkuin Jumalasta me puhumme Jumalan kasvoin edessä, Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 1, 'Rupeemmeko me siis itsiämme taas kehumaan? eli tarvitsemmeko me, niinkuin muutamat, kiitoskirjaa teidän tykönne, eli kiitoskirjaa teiltä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 2, 'Te olette meidän kirjamme, meidän sydämiimme kirjoitetut, joka kaikilta ihmisiltä tunnetaan ja luetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 3, 'Ja te olette ilmoitetut, että te Kristuksen lähetyskirja olette, meidän palveluksemme kautta valmistettu, ei pläkillä kirjoitettu, vaan elävän Jumalan hengellä, ei kivisiin tauluihin, vaan lihallisiin sydämen tauluihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 4, 'Mutta senkaltainen uskallus on meillä Kristuksen kautta Jumalan puoleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 5, 'Ei niin, että me olemme itse meistämme soveliaat jotakin ajattelemaan, niinkuin itse meistämme, vaan jos me olemme johonkuhun soveliaat, niin on se Jumalalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 6, 'Joka meitä soveliaiksi tehnyt on Uuden Testamentin virkaa pitämään, ei puustavin, vaan Hengen; sillä puustavi kuolettaa, vaan Henki tekee eläväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 7, 'Mutta jos sillä viralla, joka puustavin kautta kuolettaa ja kiviin kuvattu oli, oli senkaltainen kirkkaus, niin ettei Israelin lapset taitaneet katsoa Moseksen kasvoihin, hänen kasvoinsa kirkkauden tähden, joka kuitenkin katoo:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 8, 'Miksi ei siis paljoa enemmin sillä viralla, joka hengen antaa, pitäisi kirkkaus oleman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 9, 'Sillä, jos viralla, joka kadotuksesta saarnaa, kirkkaus oli, paljoa enemmin sillä viralla, joka vanhurskaudesta saarnaa, on ylönpalttinen kirkkaus;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 10, 'Sillä se toinen, joka kirkastettu oli, ei ole ensinkään kirkkaudeksi luettava, sen ylönpalttisen kirkkauden suhteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 11, 'Sillä jos sillä oli kirkkaus, joka katoo, paljoa enemmin on sillä kirkkaus, joka pysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 12, 'Että meillä siis senkaltainen toivo on, niin me puhumme rohkiasti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 13, 'Ja emme tee niinkuin Moses, joka kasvoillensa peitteen pani, ettei Israelin lapset taitaneet sen loppua katsoa, joka katoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 14, 'Vaan heidän taitonsa olivat paatuneet. Sillä tähän päivään asti, kuin vanhaa Testamenttia luetaan, pysyy se peite ottamatta pois, joka Kristuksessa lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 15, 'Mutta tähän päivään asti, kuin Mosesta luetaan, riippuu se peite heidän sydämensä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 16, 'Mutta kuin he palajavat Herran puoleen, niin peite otetaan pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 17, 'Sillä Herra on Henki; mutta kussa Herran Henki on, siinä on vapaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 18, 'Mutta me kaikki avoimilla kasvoilla Herran kirkkautta katselemme, niinkuin peilissä, ja me muutetaan siihen kuvaan kirkkaudesta niin kirkkauteen niinkuin Herran Hengestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 1, 'Sentähden, että meillä senkaltainen virka on, sen jälkeen kuin armo meidän kohtaamme tapahtunut on, niin emme suutu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 2, 'Vaan vältämme salaiset häpiät ja emme vaella kavaluudella, emmekä petoksella Jumalan sanaa turmele, vaan me ilmoitamme totuuden ja meitämme julkisesti kaikkein ihmisten omaatuntoa kohtaan Jumalan edessä osoitamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 3, 'Jos nyt meidän evankeliumimme on peitetty, niin se on niille peitetty, jotka kadotetaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 4, 'Joissa tämän maailman jumala on uskottomain taidot soaissut, ettei evenkeliumin paiste heille pitäisi Kristuksen kirkkaudesta valistaman, joka on Jumalan kuva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 5, 'Sillä emme itse meistämme saarnaa, vaan Kristuksesta Jesuksesta, että hän on Herra; mutta me olemme teidän palvelianne Jesuksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 6, 'Että Jumala, joka käski valkeuden pimeydestä paistaa, se paisti tunnon valkeuden meidän sydämissämme Jumalan kirkkaudesta Jesuksen Kristuksen kasvoissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 7, 'Mutta meillä on tämä tavara savisissa astioissa, että se ylönpalttinen voima pitää oleman Jumalalta ja ei meistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 8, 'Meillä on joka paikassa ahdistus, mutta emme sitä sure: meillä on pakko, mutta emme epäile.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 9, 'Me kärsimme vainoa, mutta ei meitä anneta ylön; me painetaan alas, mutta emme huku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 10, 'Me viemme ympäri aina Herran Jesuksen kuoleman meidän ruumiissamme, että Herran Jesuksen elämäkin meidän ruumiissamme ilmoitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 11, 'Sillä me, jotka elämme, annetaan ylön aina kuolemaan Jesuksen tähden, että Jesuksen elämäkin meidän kuolevaisessa lihassamme ilmoitettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 12, 'Sentähden on kuolema meissä voimallinen, mutta teissä elämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 13, 'Mutta että meillä on yksi uskon henki, niinkuin kirjoitettu on: minä uskoin, sentähden minä puhuin; niin me myös uskomme, ja sentähden me myös puhumme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 14, 'Ja tiedämme sen, että joka Herran Jesuksen herätti, hän meidätkin Jesuksen kautta herättää ja asettaa meitä teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 15, 'Sillä kaikki teidän tähtenne tapahtuu, että se ylönpalttinen armo monen kiitoksen kautta runsaasti Jumalan ylistykseksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 16, 'Sentähden emme väsy; sillä vaikka meidän ulkonainen ihminen turmellaan, niin sisällinen kuitenkin päivä päivältä uudistetaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 17, 'Sillä meidän vaivamme, joka ajallinen ja keviä on, saattaa meille ijankaikkisen ja määrättömän kunnian:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 18, 'Jotka emme näkyväisiä katso, vaan näkymättömiä; sillä näkyväiset ovat ajalliset, mutta näkymättömät ijankaikkiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 1, 'Sillä me tiedämme, että jos tämän majan meidän maallinen huone puretaan, meillä olevan rakennuksen Jumalalta, huoneen, ei käsillä tehdyn, joka on ijankaikkinen taivaissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 2, 'Jota me myös huokaamme, ikävöiden, että me meidän majallamme, joka taivaasta on, puetetuksi tulisimme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 3, 'Jos me muutoin puetettuna, ja ei alasti löydettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 4, 'Sillä me, jotka tässä majassa olemme, huokaamme, että me rasitetut olemme, jossa emme tahdo riisuttuna, vaan puetettuna olla, että se kuolevainen elämältä nieltäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 5, 'Mutta joka meitä siihen valmistaa, se on Jumala, joka myös Hengen on meille pantiksi antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 6, 'Niin me olemme sentähden aina hyvässä turvassa ja tiedämme, että niinkauvan kuin me ruumiissa asumme, niin me olemme kaukana Herrasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 7, '(Sillä me vaellamme uskossa ja emme katsomisessa.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 8, 'Mutta meillä on turva, ja paljo halaamme enemmin olla kaukana pois ruumiista ja mennä asumaan Herran tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 9, 'Sentähden, joko me kotona olemme eli ulkona vaellamme, niin me ahkeroitsemme siitä, että me hänelle kelpaisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 10, 'Sillä meidän kaikkein pitää ilmestymän Kristuksen tuomio-istuimen eteen, että jokainen sais senjälkeen mitä hän ruumiissansa tehnyt on, olkoon se hyvä eli paha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 11, 'Että me siis tiedämme, että Herraa pitää peljättämän, niin me neuvomme ihmisiä, mutta Jumalalle olemme me julkiset: kuitenkin minä toivon, että me olemme myös julki teidänkin omassatunnossanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 12, 'Emme taas kerskaa itsiämme teidän edessänne; vaan me annamme teille tilan kerskataksenne meistä, että teilläkin olis kerskaamista niitä vastaan, jotka itsiänsä kasvoin jälkeen kerskaavat ja ei sydämen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 13, 'Sillä jos me tyhmistyneet olemme, niin me sen Jumalalle olemme, eli jos me taidossa olemme, niin me teille taidossa olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 14, 'Sillä Kristuksen rakkaus vaatii meitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 15, 'Että me sen niin pidämme, että jos yksi on kuollut kaikkein edestä, niin he kaikki ovat kuolleet, ja hän on sentähden kaikkein edestä kuollut, että ne, jotka elävät, ei nyt enään eläisi itsellensä, vaan hänelle, joka heidän edestänsä kuollut ja noussut on ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 16, 'Sentähden emme tästedes lihan puolesta ketään tunne. Ja jos me olemme Kristuksen lihan puolesta tunteneet, niin emme kuitenkaan silleen tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 17, 'Sentähden jos joku on Kristuksessa, niin hän on uusi luontokappale; sillä vanhat ovat kadonneet, katso, kaikki ovat uudeksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 18, 'Mutta ne kaikki ovat Jumalasta, joka meitä on itse kanssansa sovittanut Jesuksen Kristuksen kautta, ja antoi meille viran sovinnosta saarnata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 19, 'Sillä Jumala oli Kristuksessa ja sovitti maailman itse kanssansa, ja ei lukenut heille heidän syntiänsä, ja on meissä sovintosaarnan säätänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 20, 'Niin olemme me Kristuksen puolesta käskyläiset; sillä Jumala neuvoo meidän kauttamme. Niin me rukoilemme siis Kristuksen puolesta, että te Jumalan kanssa sovitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 21, 'Sillä hän on sen, joka ei mitään synnistä tietänyt, meidän edestämme synniksi tehnyt, että me hänessä tulisimme siksi vanhurskaudeksi, joka Jumalan edessä kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 1, 'Mutta me niinkuin apulaiset neuvomme teitä, ettette Jumalan armoa hukkaan ottaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 2, 'Sillä hän sanoo: minä olen otollisella ajalla sinua kuullut ja olen sinua autuuden päivänä auttanut. Katso, nyt on otollinen aika, katso, nyt on autuuden päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 3, 'Älkäämme kellenkään jossakussa pahennusta antako, ettei meidän virkaamme laitettaisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 4, 'Vaan osoittakaamme meitämme kaikissa asioissa niinkuin Jumalan palveliat: suuressa kärsivällisyydessä, vaivoissa, hädissä, suruissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 5, 'Haavoissa, vankiuksissa, kapinoissa, töissä, valvomisissa, paastoissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 6, 'Puhtaassa elämässä, taidossa, pitkämielisyydessä, suloisuudessa, Pyhässä Hengessä, vilpittömässä rakkaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 7, 'Totuuden sanassa, Jumalan väessä vanhurskauden sota-aseiden kautta oikialla ja vasemmalla puolella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 8, 'Kunnian kautta ja pilkan, panetuksen ja kiitoksen kautta, niinkuin vietteliät ja kuitenkin vakaat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 9, 'Niinkuin tuntemattomat ja kuitenkin tutut, niinkuin kuolevaiset ja katso, me elämme, niinkuin rangaistut ja ei kuitenkaan tapetut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 10, 'Niinkuin murheelliset ja kuitenkin aina iloiset, niinkuin köyhät, mutta kuitenkin monta rikkaaksi tekeväiset, niinkuin ne, joilla ei mitään ole ja joiden kuitenkin kaikki omat ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 11, 'Te Korintilaiset! meidän suumme on hänensä avannut teidän kohtaanne, meidän sydämemme on levinnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 12, 'Ette ole ahtaalla meissä; mutta itse teissänne te ahtaalla olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 13, 'Minä sanon niinkuin lapsilleni, että te myös minua vastaan teitänne niin asettaisitte, ja levittäkäät teitänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 14, 'Älkäät vetäkö ijestä epäuskoisten kanssa; sillä mitä oikeuden on vääryyden kanssa tekemistä? eli mitä osallisuutta on valkeudella pimeyden kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 15, 'Ja mikä sovinto on Kristuksella belialin kanssa? taikka mikä osa on uskovaisella uskottoman kanssa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 16, 'Eli kuinka Jumalan templi sopii epäjumalain kanssa? Sillä te olette elävän Jumalan templi, niinkuin Jumala sanoo: minä tahdon heissä asua ja heissä vaeltaa, ja minä tahdon olla heidän Jumalansa, ja heidän pitää oleman minun kansani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 17, 'Sentähden paetkaat heidän seastansa ja eroittakaat teitänne, sanoo Herra: ja älkäät saastaiseen ruvetko, ja niin minä korjaan teitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 18, 'Ja olen teidän Isänne, ja teidän pitää oleman minun poikani ja tyttäreni, sanoo kaikkivaltias Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 1, 'Että meillä nyt senkaltaiset lupaukset ovat, minun rakkaani, puhdistakaamme siis itsemme kaikesta lihan ja hengen saastaisuudesta, täyttäin pyhyyttä Jumalan pelvossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 2, 'Ottakaat meitä vastaan: emme kellenkään vääryyttä tehneet, emme ketään turmelleet, emme keneltäkään mitään vaatineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 3, 'Senkaltaista en sano minä teille kadotukseksi; sillä minä olen ennen sanonut, että te olette meidän sydämessämme ynnä kuolla ja ynnä elää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 4, 'Minä puhun teille suurella rohkeudella, minä kerskaan paljon teistä, minä olen lohdutuksella täytetty, minä olen ylönpalttisessa ilossa kaikessa meidän vaivassamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 5, 'Sillä kuin me Makedoniaan tulimme, ei meidän lihallamme ollut yhtään lepoa, vaan kaikissa paikoissa olimme me vaivatut, ulkona sota, sisällä pelko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 6, 'Mutta Jumala, joka nöyriä lohduttaa, hän lohdutti meitä Tituksen tulemisella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 7, 'Vaan ei ainoastaan hänen tulemisellansa, mutta myös sillä lohdutuksella, jonka hän teiltä saanut oli, ja ilmoitti meille teidän halunne, teidän itkunne ja teidän kiivautenne minusta, niin että minä vielä enemmin ihastuin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 8, 'Sillä jos minä lähetyskirjallani saatinkin teitä murheesen, enpä minä sitä kadu, ehkä minä olisin katunut; sillä minä näen sen lähetyskirjan teitä hetken aikaa murheessa pitäneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 9, 'Nyt minä iloitsen, en siitä, että te murheissa olitte, vaan että te olitte murheissa parannukseksi; sillä te olitte murheelliset Jumalan mielen jälkeen, ettei teillä meistä missään vahinkoa olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 10, 'Sillä se murhe, joka Jumalan mielen jälkeen tapahtuu, saattaa katumisen autuudeksi, jota ei yksikään kadu; mutta maailman murhe saattaa kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 11, 'Sillä katso, että te olitte Jumalan mielen jälkeen murheelliset, kuinka suuren ahkeruuden se on teissä vaikuttanut! Ja tosin edesvastauksen, närkästyksen, pelvon, ikävöitsemisen, kiivauden ja koston. Te olette kaikissa teitänne puhtaiksi osoittaneet tässä asiassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 12, 'Sentähden vaikka minä teille kirjoitin, niin ei se ole kuitenkaan sen tähden tapahtunut, joka rikkonut oli, eikä sen tähden, jolle vääryys tehtiin, mutta sentähden, että teidän ahkeruutenne meidän kohtaamme Jumalan edessä julkiseksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 13, 'Sentähden me olemme saaneet lohdutuksen, että tekin olette lohdutetut. Mutta vielä enemmin iloitsimme me Tituksen ilosta; sillä hänen henkensä oli teiltä kaikilta virvoitettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 14, 'Ja mitä minä hänen edessänsä teistä kerskannut olen, en minä sitä häpee; vaan niinkuin kaikki ovat todet, mitkä minä teille puhunut olen, niin on myös meidän kerskauksemme Tituksen edessä todeksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 15, 'Ja hänellä on sangen suuri sydämellinen halu teidän puoleenne, kuin hän kaikkein teidän kuuliaisuutenne muistaa, kuinka te pelvolla ja vavistuksella häntä otitte vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 16, 'Minä siis iloitsen, että minä kaikissa asioissa teihin taidan luottaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 1, 'Mutta minä teen teille tiettäväksi, rakkaat veljet, Jumalan armon, joka Makedonian seurakuntiin annettu on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 2, 'Sillä heidän ilonsa oli ylönpalttinen, kuin heitä monen vaivan kautta koeteltiin, ja vaikka he sangen köyhät olivat, ovat he kuitenkin runsaasti kaikessa yksinkertaisuudessa antaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 3, 'Sillä he olivat kaikesta voimastansa (sen minä todistan) ja ylitsekin voimansa hyväntahtoiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 4, 'Ja meitä suurella ahkeruudella rukoilivat, että me ottaisimme vastaan sen hyvän työn ja sen palveluksen osallisuuden, joka pyhäin varaksi koottu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 5, 'Ja ei niinkuin me toivoimme, vaan he antoivat itsensä ensisti Herralle ja (sitte) meille Jumalan tahdon kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 6, 'Että meidän pitäis Titusta neuvoman, että, niinkuin hän oli ennen ruvennut, hänen pitäis senkaltaisen hyvän työn niin teidän seassanne päättämän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 7, 'Mutta niinkuin te olette kaikissa rikkaat, uskossa ja sanassa, ja taidossa ja kaikkinaisessa ahkeruudessa, ja teidän rakkaudessanne meidän kohtaamme, (niin sovittakaat siis), että te myös tässä armossa rikkaat olisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 8, 'Enpä minä vaatimisesta sitä sano, vaan muiden ahkeruudesta koettelen minä myös teidän rakkautenne vakuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 9, 'Sillä te tiedätte meidän Herran Jesuksen Kristuksen armon, että hän rikkaana ollessansa tuli kuitenkin teidän tähtenne köyhäksi, että te hänen köyhyytensä kautta rikkaaksi tulisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 10, 'Minun neuvoni minä tästä annan; sillä se on teille hyödyllinen, että te olette ennen ruvenneet ei ainoasti sitä tekemään, vaan jo menneenä vuonna tahdoitte sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 11, 'Täyttäkäät siis nyt se työ, jonka te rupesitte, että niinkuin tahto valmis oli, te myös sen voimanne perästä täyttäisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 12, 'Sillä jos joku edellä mielellinen on, niin hän on otollinen varansa jälkeen, ja ei sen jälkeen, joka ei hänellä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 13, 'Ei niin luullen, että muilla pitää oleman huojennus ja teillä ahdistus, vaan että se tasan olis, niin palvelkaan teidän rikkautenne heidän köyhyyttänsä tällä ajalla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 14, 'Että myös heidän rikkautensa teidän puuttumistanne palvelis, että tasan tapahtuis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 15, 'Niinkuin kirjoitettu on: joka paljon kokosi, ei hänellä ollut liiaksi, ja joka vähän kokosi, ei häneltä mitään puuttunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 16, 'Mutta Jumalan olkoon kiitos, joka senkaltaisen ahkeruuden antoi Tituksen sydämeen teidän tähtenne!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 17, 'Sillä hän otti sen neuvon hyväksi, ja tosin oli sitä ahkerampi, että hän läksi mielellänsä teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 18, 'Mutta me olemme hänen kanssansa lähettäneet veljen, jota evankeliumissa kiitetään kaikissa seurakunnissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 19, '(Mutta ei se ainoasti, vaan hän on myös säätty seurakunnilta meidän matkakumppaniksemme tämän armon kanssa, joka meidän kauttamme Herran kunniaksi toimitetaan, ja teidän hyvän tahtonne koettelemiseksi,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 20, 'Karttain sitä, ettei kenkään meitä panettelisi senkaltaisen rikkaan avun puolesta, joka meidän kauttamme toimitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 21, 'Sillä me ahkeroitsemme sitä, mikä kunniallinen on, ei ainoasti Herran edessä, vaan myös ihmisten edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 22, 'Ja me olemme heidän kanssansa lähettäneet meidän veljemme, jonka me monessa olemme usiasti koetelleet, että hän ahkera on, ja vielä nyt paljoa ahkerampi, suurella uskalluksella, joka on teidän tykönne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 23, 'Sekä Tituksen puolesta, joka minun kumppanini on ja apulaiseni teidän seassanne, että myös meidän veljeimme tähden, jotka ovat seurakuntain apostolit, Kristuksen kunnia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 24, 'Osoittakaat siis teidän rakkautenne merkki ja meidän kerskaamisemme teistänne niitä kohtaan, julkisesti seurakunnankin edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 1, 'Sillä siitä avusta, joka pyhille annetaan, ei tarvitse minun teille kirjoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 2, 'Sillä minä tiedän teidän hyvä tahtonne, jota minä teidän tähtenne kehun Makedonialaisille, että Akaja on ollut jo ajastajan valmis ja että te olette monta siihen kiivaudellanne kehoittaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 3, 'Kuitenkin minä olen tämän veljen sentähden lähettänyt, ettei meidän kerskaamisemme teistä tässä asiassa tyhjäksi tulisi, että (niinkuin minä sanoin) te valmiit olisitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 4, 'Ettemme, jos Makedonialaiset minun kanssani tulevat, ja ei löydä teitä valmiina, me silloin (en minä sano: te) senkaltaisesta kerskauksesta häpiään tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 5, 'Sentähden näin minä tarpeelliseksi veljiä neuvoa, että he ensin menevät teidän tykönne ja edellä valmistavat teidän ennen luvatun hyvän lahjanne, että se valmis olis, niinkuin hyvä teko ja ei niinkuin vaatimus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 6, 'Mutta sen minä sanon: joka tiiviisti kylvää, sen pitää myös tiiviisti niittämän, joka siunauksessa kylvää, sen pitää myös siunauksessa niittämän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 7, 'Kukin sydämensä ehdon jälkeen, ei ylönmielin eli vaatein; sillä iloista antajaa Jumala rakastaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 8, 'Mutta Jumala on väkevä niin sovittamaan, että kaikkinainen armo teidän seassanne ylönpalttiseksi tulis, että teillä kaikissa aina yltäkyllä olis, ja olisitte rikkaat kaikkiin hyviin töihin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 9, '(Niinkuin kirjoitettu on: hän on hajoittanut ja antanut köyhille: hänen vanhurskautensa pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 10, 'Mutta joka siemenen kylväjälle antaa, hän teillekin antaa leivän syödäksenne, ja lisää teidän siemenenne, ja kasvattaa teidän vanhurskautenne hedelmän,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 11, 'Että te kaikissa rikkaaksi tulisitte, kaikella yksinkertaisuudella, joka meidän kauttamme Jumalalle kiitoksen vaikuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 12, 'Sillä tämän viran palvelus ei ainoastaan täytä sitä, mikä pyhiltä puuttuu, vaan on siihen yltäkylläinen, että moni kiittää Jumalaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 13, '(Tämän palveluksen koettelemuksen kautta ylistäin Jumalaa teidän nöyrän tunnustuksenne tähden Kristuksen evankeliumissa, ja myös teidän yksinkertaisen tasajaon tähden, heidän ja kaikkein kohtaan,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 14, 'Ja heidän rukouksissansa teidän edestänne, jotka teitä ikävöitsevät, sen ylönpalttisen Jumalan armon tähden, joka teissä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 15, 'Mutta kiitos olkoon Jumalan hänen sanomattoman lahjansa edestä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 1, 'Mutta minä Paavali neuvon teitä Kristuksen siveyden ja vakuuden tähden, minä, joka teidän tykönänne ollessani kehno olen, vaan poissa ollessani olen rohkia teitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 2, 'Mutta minä rukoilen teitä, ettei minua vaadittaisi rohkiaksi tykönä ollessani, niinkuin minulla luullaan rohkeus muutamia vastaan olevan, jotka meidän luulevat lihan jälkeen vaeltavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 3, 'Sillä ehkä me lihassa vaellamme, emmepä me sentähden lihan jälkeen sodi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 4, 'Sillä meidän sota-aseemme ei ole lihalliset, vaan väkevät Jumalan edessä kukistamaan varjeluksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 5, 'Ja me maahan lyömme aivoitukset ja kaiken korkeuden, joka hänensä korottaa Jumalan tuntemista vastaan, ja vangiksi otamme kaiken ajatuksen Kristuksen kuuliaisuuden alle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 6, 'Ja olemme valmiit kostamaan kaikkea kovakorvaisuutta, kuin teidän kuuliaisuutenne täytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 7, 'Katsotteko te niiden jälkeen, mitkä silmäin edessä ovat? Jos joku uskaltaa sen päälle, että hän on Kristuksen oma, se ajatelkaan itsellänsä, että niinkuin hän on Kristuksen oma, niin olemme mekin Kristuksen omat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 8, 'Sillä jos minä vielä enemmän kerskaisin meidän vallastamme, jonka Herra meille antanut on teidän parannukseksenne, ja ei kadotukseksenne, enpä minä häpeäisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 9, 'Etten minä näkyisi teitä lähetyskirjoilla peljättäväni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 10, 'Sillä lähetyskirjat (sanovat he) ovat raskaat ja väkevät, mutta ruumiillinen läsnäolemus on heikko ja puhe on ylönkatsottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 11, 'Senkaltainen ajatelkaan, että niinkuin me olemme lähetysvirkain kautta sanoissa poissa-ollessamme, niin me myös olemme itse työllä läsnä-ollessamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 12, 'Sillä emmepä me rohkene meitämme lukea eli verrata niihin, jotka itsiänsä ylistävät; mutta että he itse heillänsä heitänsä mittaavat ja pitävät ainoastaan itse heistänsä, niin ei he mitään ymmärrä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 13, 'Mutta emme meitämme kerskaa ylitse määrän, vaan ainoastaan kohtuullisen määrätyn mitan jälkeen, jonka Jumala meille mitannut on, joka myös teihinkin ulottuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 14, 'Sillä emmepä me itsiämme leviämmältä anna ulos kuin sopii, niinkuin emme oliskaan teihin ulottuneet; sillä me olemme jo hamaan teidän tykönne Kristuksen evankeliumilla tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 15, 'Ja emme kerskaa meitämme ylitse määrän vieraissa töissä; vaan me toivomme, kuin teidän uskonne kasvaa teissä, että mekin meidän määrämme jälkeen tahdomme levitä yltäkylläisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 16, 'Evankeliumia saarnaamaan niille, jotka tuolla puolen teitä asuvat: emmekä meitämme kerskaa niistä, jotka vieraan mitan jälkeen valmistetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 17, 'Mutta joka kerskaa, se kerskatkaan Herrassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 18, 'Sillä joka itsiänsä kiittää, ei se ole koeteltu, vaan se, jota Herra kiittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 1, 'Oi jospa te vähänkin minun tyhmyyttäni kärsisitte! Ja tosin te minua kärsitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 2, 'Sillä minä kiivaan teitä Jumalan kiivaudella. Sillä minä olen teitä kihlannut yhdelle miehelle, että minä puhtaan neitseen Kristukselle tuottaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 3, 'Mutta minä pelkään, että niinkuin kärme vietteli Evan kavaluudellansa, niin myös teidän taitonne turmellaan siitä yksinkertaisuudesta, joka on Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 4, 'Sillä jos se, joka teidän tykönne tulee, toisesta Jesuksesta teille saarnaa, josta emme saarnanneet, taikka jos te toisen hengen saatte, jota ette ole saaneet, eli toisen evankeliumin, jota ette ole ottaneet vastaan, niin te sen oikein kärsitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 5, 'Sillä minä arvaan, etten minä ole ollut halvempi niitä kaikkein korkeimpia apostoleita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 6, 'Ja ehkä minä olen puheessa yksinkertainen, niin en minä ole tiedossa yksinkertainen; kuitenkin olemme me kyllä kaikille teille tiettävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 7, 'Eli olenko minä syntiä tehnyt, että minä olen itseni alentanut, että te ylennettäisiin, että minä olen teille Jumalan evankeliumia ilman palkkaa ilmoittanut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 8, 'Ja olen muut seurakunnat ryöstänyt, ja heiltä palkan ottanut, jolla minä teitä palvelin? Ja kuin minä olin teidän tykönänne ja minulta jotakin puuttui, enpä minä ketään rasittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 9, 'Sillä mitä minulta puuttui, sen veljet täyttivät, jotka Makedoniasta tulivat. Ja niin minä pidin itseni kaikissa, etten minä kenenkään kuormana ollut, ja tahdon vieläkin minuni niin pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 10, 'Niin totta kuin Kristuksen totuus minussa on, niin ei tämä kerskaus pidä minulta Akajan maakunnissa otettaman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 11, 'Minkätähden? Senkötähden, etten minä teitä rakasta? Sen Jumala tietää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 12, 'Mutta mitä minä teen, sen minä tahdon tehdä, että minä heiltä tilan ottaisin pois, jotka etsivät tilaa kerskata, että he ovat niin kuin me.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 13, 'Sillä senkaltaiset väärät apostolit ja petolliset työntekijät teeskelevät itsensä Kristuksen apostoleiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 14, 'Ei myös ihmekään ole; sillä itse saatana muuttaa itsensä valkeuden enkeliksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 15, 'Ei siis se ole suuri, jos myös hänen palveliansa itsensä asettelevat niinkuin he olisivat vanhurskauden saarnaajat, joiden loppu pitää oleman heidän töittensä perään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 16, 'Taas sanon minä, ettei yhdenkään pidä minua tyhmäksi luuleman; vaan ellei niin ole, niin ottakaat minua vastaan niinkuin tyhmääkin, että minä myös vähä kerskaisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 17, 'Sitä mitä minä nyt puhun, en minä puhu niinkuin Herrassa, vaan niinkuin tyhmyydessä, että me nyt kerskaamaan ruvenneet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 18, 'Koska moni kerskaa lihan jälkeen, niin minäkin tahdon kerskata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 19, 'Sillä te kärsitte mielellänne tyhmiä, että te viisaat olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 20, 'Te kärsitte, jos joku teitä orjuuteen vaatii, jos joku teitä syö, jos joku teiltä jotakin ottaa, jos joku itsensä korottaa, jos joku teitä lyö kasvoille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 21, 'Sen minä sanon häväistyksen tähden, niinkuin me heikot olisimme: mihinkä joku uskaltaa, (minä puhun tyhmyydessä,) siihen minäkin uskallan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 22, 'He ovat Hebrealaiset, minä myös. He ovat Israelilaiset, minä myös. He ovat Abrahamin siemen, minä myös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 23, 'He ovat Kristuksen palveliat, (minä puhun tyhmästi,) paljoa enemmin minä olen. Minä olen enemmän työtä tehnyt. Minä olen enemmän haavoja kärsinyt. Minä olen useammin vankina ollut. Usein olen kuoleman hädässä ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 24, 'Juudalaisilta olen minä viidesti neljäkymmentä haavaa saanut, yhtä vailla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 25, 'Kolmasti olen vitsoilla piesty. Olin kerran kivitetty. Kolmasti olen minä tullut haaksirikkoon. Yön ja päivän olin minä meren syvyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 26, 'Minä olen usein vaeltanut, minä olen ollut veden hädässä, ryövärien keskellä, hädässä Juudalaisten keskellä, hädässä pakanain keskellä, hädässä kaupungeissa, hädässä korvessa, hädässä merellä, hädässä viekasten veljien seassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 27, 'Työssä ja tuskassa, paljossa valvomisessa, nälässä ja janossa, paljossa paastossa, vilussa ja alastomuudessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 28, 'Ilman niitä mitkä muutoin tapahtuvat, nimittäin, että minua joka päivä vaivataan ja pidän surun kaikista seurakunnista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 29, 'Kuka on heikko, ja en minä myös heikoksi tule? Kuka pahoitetaan, ja en minä pala?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 30, 'Että minun pitää nyt kerskaaman, niin minä kerskaan heikkoudestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 31, 'Jumala ja meidän Herran Jesuksen Kristuksen Isä, joka olkoon ylistetty ijankaikkisesti! tietää, etten minä valehtele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 32, 'Damaskussa Aretaan kuninkaan maanvanhin vartioitsi Damaskun kaupunkia ja tahtoi minun ottaa kiinni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 33, 'Ja minä laskettiin maahan muurin akkunasta korissa, ja pääsin niin hänen käsistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 1, 'Ei minun ole hyvää kerskaamisestani; tulen kuitenkin näkyihin ja Herran ilmoituksiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 2, 'Minä tunnen ihmisen Kristuksessa ennen neljäätoistakymmentä ajastaikaa, (oliko hän ruumiissa, en minä tiedä, eli oliko hän ulkona ruumiista, en minä sitäkään tiedä; Jumala sen tietää:) se temmattiin ylös hamaan kolmanteen taivaasen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 3, 'Ja minä tunnen sen ihmisen, (jos hän ruumiissa taikka ulkona ruumiista oli, en minä tiedä; Jumala sen tietää:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 4, 'Hän temmattiin ylös paradisiin ja kuuli sanomattomia sanoja, joita ei yhdenkään ihmisen sovi puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 5, 'Siitä minä kerskaan; mutta en minä itsestäni kerskaa, vaan minun heikkoudestani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 6, 'Sillä jos minä tahtoisin kerskata, niin en minä tekisi tyhmästi; sillä minä tahdon totuuden sanoa. Mutta kuitenkin minä itseni siinä pidätän, ettei joku minua korkiammaksi lukisi, kuin hän minun näkee eli minusta kuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 7, 'Ja ettei ilmoitusten ylönpalttisuus minua ylen paljon korottaisi, on pistin annettu minun lihaani, nimittäin saatanan enkeli, rusikoitsemaan minua, etten minä itsiäni ylen paljon korottaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 8, 'Sentähden olen minä kolmasti Herraa rukoillut, että hän läksis minusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 9, 'Ja hän sanoi minulle: tyydy minun armooni; sillä minun voimani on heikoissa väkevä. Sentähden minä mielelläni kerskaan heikkoudestani, että Kristuksen voima minussa asuis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 10, 'Sentähden iloitsen minä heikkoudessa, ylönkatseissa, hädissä, vainoissa ja ahdistuksissa Kristuksen tähden; sillä koska minä heikko olen, niin minä väkeväkin olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 11, 'Minä olen tällä kerskaamisella tyhmäksi tullut; te olette minua siihen vaatineet. Sillä minua piti teiltä kiitettämän, etten minä ensinkään vähempi ole kuin korkeimmatkaan apostolit, ehken minä mitään ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 12, 'Niin ovat tosin apostolin merkit teidän seassanne tapahtuneet kaikella kärsivällisyydellä, merkeillä, ihmeillä ja voimallisilla töillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 13, 'Mitäs te muita seurakuntia huonommat olette, paitsi sitä, etten minä itse teidän kuormananne ollut? Antakaat minulle se vääryys anteeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 14, 'Katso, minä olen valmis kolmannen kerran teidän tykönne tulemaan, ja en tahdo ensinkään teitä rasittaa; sillä enpä minä etsi teidän omaanne, vaan teitä; sillä ei lasten pidä tavaraa kokooman vanhempainsa varaksi, vaan vanhemmat lapsillensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 15, 'Mutta mielelläni minä tahdon kuluttaa ja itseni annettaa ulos teidän sieluinne edestä, vaikka te vähän minua rakastatte, joka kuitenkin sangen paljon teitä rakastan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 16, 'Mutta olkoon sillänsä, etten minä ole teitä raskauttanut; mutta että minä olin kavala, niin minä olen teidät petoksella saavuttanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 17, 'Olenko minä keltään mitään vaatinut niiden tähden, jotka minä teille lähettänyt olen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 18, 'Minä olen Titusta neuvonut, ja lähetin hänen kanssansa yhden veljen: onkos Titus jotakin teiltä vaatinut? Emmekö me ole yhdessä hengessä vaeltaneet? Emmekö me ole yksiä jälkiä myöten käyneet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 19, 'Luuletteko taas, että me vastaamme edestämme teidän edessänne? Me puhumme Kristuksessa, Jumalan edessä; mutta kaikki nämät, rakkaat veljet, teidän parannukseksenne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 20, 'Sillä minä pelkään, etten minä tultuani teitä löydä senkaltaisena kuin minä tahdon, ja te myös löydätte minun, ei niinkuin te tahtoisitte: ettei siellä riidat, kateudet, vihat, torat, panetukset, parjaukset, paisumiset ja kapinat olisi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 21, 'Ettei taas minun palattuani minun Jumalani teidän tykönänne minua nöyryyttäisi ja minun pitäis monen tähden murehtiman, jotka ennen rikkoneet ovat ja ei ole itsiänsä parantaneet siitä saastaisuudesta ja huoruudesta ja haureudesta, jota he tehneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 1, 'Nyt minä kolmannen kerran tulen teidän tykönne. Niin pitää kahden eli kolmen suun kautta kaikkinaiset asiat kiinnitettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 2, 'Minä olen ennenkin sen teille sanonut ja vieläkin edellä sanon, niinkuin toisella kerralla läsnäollessani, ja kirjoitan nyt poissa-ollessani niille, jotka ennen syntiä tehneet olivat, ja muille kaikille, että jos minä sinne tulen, niin en minä säästä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 3, 'Että te kerran saatte tietää, kuka minussa puhuu, nimittäin Kristus, joka ei suinkaan ole heikko teidän kohtaanne, vaan hän on väkevä teissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 4, 'Ja ehkä hän oli ristiinnaulittu heikkoudessa, niin hän kuitenkin elää Jumalan voimassa; sillä myös me olemme heikot hänessä, mutta meidän pitää elämän hänen kanssansa Jumalan voimassa teidän tykönänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 5, 'Koetelkaat teitänne, jos te olette uskossa, kokekaat teitänne: eli ettekö te itsiänne tunne, että Jesus Kristus on teissä? ellei niin ole, että te kelvottomat olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 6, 'Mutta minä toivon, että te tunnette, ettemme kelvottomat ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 7, 'Ja minä rukoilen Jumalaa, ettette mitään pahaa tekisi, ei että me kelvolliseksi näkyisimme, vaan että te hyvää tekisitte ja me olisimme niinkuin kelvottomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 8, 'Sillä emme mitään voi totuutta vastaan, vaan totuuden puolesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 9, 'Mutta me iloitsemme, kuin me heikot olemme ja te voimalliset olette, jota me myös toivotamme, nimittäin teidän täydellisyyttänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 10, 'Sentähden minä myös poissa-ollessani näitä kirjoitan, ettei minun pitäisi läsnä-ollessani kova oleman, sen voiman jälkeen, jonka Herra antoi minulle rakennukseksi ja ei kukistukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 11, 'Viimein, rakkaat veljet, iloitkaat, olkaat täydelliset, lohduttakaat teitänne, olkaat yksimieliset, olkaat rauhalliset, niin rakkauden ja rauhan Jumala on teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 12, 'Tervehtikäät teitänne keskenänne pyhällä suunantamisella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 13, 'Kaikki pyhät teitä tervehtivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 14, 'Meidän Herran Jesuksen Kristuksen armo ja Jumalan rakkaus ja Pyhän Hengen osallisuus olkoon kaikkein teidän kanssanne! Amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Paavali, apostoli, (ei ihmisiltä eikä ihmisten kautta, vaan Jesuksen Kristuksen kautta ja Isän Jumalan, joka hänen kuolleista herättänyt on,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Ja kaikki veljet, jotka minun kanssani ovat, Galatian seurakunnille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Armo olkoon teille ja rauha Isältä Jumalalta ja meidän Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Joka itsensä meidän synteimme edestä antanut on, että hän meitä vapahtais tästä nykyisestä pahasta maailmasta, Jumalan ja meidän Isämme tahdon jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Jolle olkoon kiitos ijankaikkisesta ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Minä ihmettelen, että te niin pian annatte teitänne kääntää pois siitä, joka teitä Kristuksen armoon kutsunut on, toiseen evankeliumiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Joka ei muuta ole, vaan että muutamat eksyttävät teitä ja tahtovat Kristuksen evankeliumia toisin kääntää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Mutta ehkä me taikka joku enkeli taivaasta saarnais teille toisin evankeliumia, kuin me olemme teille saarnanneet, se olkoon kirottu!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Niinkuin me ennen sanoimme, niin minä vielä sanon: jos joku teille toisin saarnaa evankeliumia, kuin te ottaneet olette, olkoon kirottu!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Saarnaanko minä nyt ihmisten eli Jumalan mielen jälkeen? eli pyydänkö minä ihmiselle kelvata? Sillä jos minä tähän asti olisin tahtonut ihmisille kelvata, niin en minä olisi Kristuksen palvelia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Mutta minä teen teille tiettäväksi, rakkaat veljet, ettei se evankeliumi, joka minulta saarnattu on, ole ihmisen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Sillä en minä ole sitä ihmiseltä saanut enkä oppinut, vaan Jesuksen Kristuksen ilmoituksesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Sillä te olette kuulleet minun muinaisen olentoni Juudalaisten tavoissa, kuinka ylönpalttisesti minä Jumalan seurakuntaa vainosin ja hävitin sitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Ja menestyin Juudalaisten menoissa, ylitse monen minun vertaiseni minun suvussani, ja olin ylen kiivas isäin säätyin tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Mutta koska Jumala tahtoi, joka minun oli eroittanut äitini kohdusta, ja armonsa kautta kutsui,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Että hän Poikansa minun kauttani ilmoittais, ja minä julistaisin hänen evankeliumin kautta pakanain seassa, niin en minä ensinkään lihan ja veren kautta tutkinut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'En myös Jerusalemiin niiden tykö palannut, jotka ennen minua apostolit olivat; vaan menin pois Arabiaan ja palasin jällensä Damaskuun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Sitte kolmen vuoden perästä tulin minä Jerusalemiin Pietaria oppimaan ja olin hänen kanssansa viisitoistakymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Mutta en minä muita apostoleita yhtään nähnyt paitsi Jakobia, Herran veljeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Mutta sen, mitä minä teille kirjoitan, katso, Jumala tietää, etten minä valehtele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Sitte tulin minä Syrian ja Kilikian maakuntiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Ja minä olin tuntematoin kasvoista niille Juudean seurakunnille, jotka olivat Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Mutta he olivat ainoastaan kuulleet, että se, joka meitä muinen vainosi, hän saarnaa nyt uskoa, jota hän muinen hävitti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Ja kiittivät minun tähteni Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Sitte neljäntoistakymmenen vuoden perästä menin minä taas Barnabaan kanssa ylös Jerusalemiin ja otin Tituksen kanssani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'Ja minä menin ylös ilmoituksen jälkeen ja asetin heidän eteensä sen evankeliumin, jota minä pakanain seassa julistan: mutta erinomaisesti niiden eteen, jotka jonakin pidetään, etten minä hukkaan juoksisi elikkä olisi jo juossut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'Mutta ei Titustakaan, joka minun kanssani oli, vaadittu itsiänsä ympärileikkauttamaan, vaikka hän Grekiläinen oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'Sillä kuin muutamat väärät veljet tunkeutuivat sisälle, ja jo olivat tulleet sisälle koettelemaan meidän vapauttamme, joka meillä Kristuksessa Jesuksessa on, että he meitä orjuuteen vaatisivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, 'Emmepä me tosin niille hetkeksikään myöntyneet kuuliaisuuteen, että evankeliumin totuus teidän tykönänne pysyväinen olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Mutta niihin, jotka jonakin pidetään, minkäkaltaiset he muinen olivat, ei minun mitään tule: ei Jumala katso ihmisen muotoa; sillä ne, jotka jonakin pidetään, ei minulle mitään opettaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'Vaan sitä vastaan, kuin he näkivät, että minulle evankeliumi esinahan puoleen uskottu oli, niinkuin Pietarille ympärileikkauksen puoleen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, '(Sillä joka Pietarin kanssa oli voimallinen apostolin virassa ympärileikkauksen seassa, se on minunkin kanssani pakanain seassa voimallinen ollut,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'Ja kuin he tunsivat sen armon, joka minulle annettu oli, niin Jakob ja Kephas ja Johannes, jotka patsaina pidettiin, antoivat minulle ja Barnabaalle kättä ja sopivat niin meidän kanssamme, että meidän pakanain seassa ja heidän ympärileikkauksen seassa saarnaaman piti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'Ainoastaan että meidän piti vaivaisia muistaman, jota minä myös olen ahkeroinut tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'Mutta kuin Pietari Antiokiaan tuli, niin minä olin julkisesti häntä vastaan, että kanne oli tullut hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, 'Sillä ennenkuin joku Jakobin tyköä tuli, söi hän pakanain kanssa; vaan kuin ne tulivat, vältti hän, ja eroitti itsensä heistä, peljäten niitä, jotka ympärileikkauksesta olivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'Ja muutkin Juudalaiset viekastelivat hänen kanssansa, niin että Barnabaskin vieteltiin heidän ulkokullaisuudellansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, 'Mutta kuin minä sen näin, ettei he oikein vaeltaneet evankeliumin totuuden jälkeen, sanoin minä Pietarille julkisesti kaikkein kuullen: jos sinä, joka Juudalainen olet, pakanain tavalla elät ja et Juudalaisten, miksis vaadit pakanoita Juudalaisten tavalla elämään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'Me jotka olemme Juudalaiset luonnon puolesta ja emme syntiset pakanoista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'Että me tiedämme, ettei ihminen lain töiden kautta vanhurskaaksi tule, vaan uskon kautta Jesuksen Kristuksen päälle: niin me myös olemme uskoneet Jesuksen Kristuksen päälle, että me vanhurskaaksi tulemme uskon kautta Kristuksen päälle, ja emme lain töiden kautta, sentähden ettei yksikään liha tule lain töiden kautta vanhurskaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'Mutta jos me, koska me tahdomme Kristuksen kautta vanhurskaaksi tulla, löydetään myös itse syntisiksi, onko siis Kristus synnin palvelia? Pois se!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 18, 'Sillä jos minä sitä taas rakennan, jota minä särkenyt olen, niin minä teen itseni ylitsekäyväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 19, 'Mutta minä olen lain kautta laista kuollut pois, että minä Jumalassa eläisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 20, 'Minä olen Kristuksen kanssa ristiinnaulittu. Mutta minä elän, en silleen minä, vaan Kristus elää minussa; sillä jota minä nyt elän lihassa, sen minä elän Jumalan Pojan uskossa, joka on minua rakastanut ja antoi itsensä minun edestäni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 21, 'En minä hylkää Jumalan armoa; sillä jos vanhurskaus tulee laista, niin on Kristus hukkaan kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, 'Te hullut Galatalaiset! kuka teidät on vimmannut totuutta uskomasta? joiden silmäin eteen Jesus Kristus kirjoitettu oli, teidän seassanne ristiinnaulittu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'Sen tahdon minä ainoastaan teiltä tietää: oletteko te Hengen saaneet lain töiden kautta eli uskon saarnaamisen kautta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'Oletteko te niin tomppelit? Hengessä te olette alkaneet, tahdotteko te nyt lihassa lopettaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, 'Oletteko te niin paljon hukkaan kärsineet? Jos se muutoin hukassa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'Joka siis teille hengen antaa ja tekee voimalliset työt teidän seassanne, tekeekö hän sen lain töiden kautta eli uskon saarnaamisen kautta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'Niinkuin Abraham oli Jumalan uskonut, ja se on luettu hänelle vanhurskaudeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, 'Niin te myös jo tiedätte, että jotka uskossa ovat, ne ovat Abrahamin lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'Mutta Raamattu oli sitä jo ennen katsonut, että Jumala pakanatkin uskon kautta vanhurskaaksi tekee; sentähden hän edellä ilmoitti Abrahamille: sinussa (sanoo hän) kaikki pakanat pitää siunatut oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'Niin tulevat kaikki ne, jotka uskosta ovat, siunatuksi uskovaisen Abrahamin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'Sillä niin monta, jotka lain töissä riippuvat, ovat kirouksen alla; sillä kirjoitettu on: kirottu olkoon jokainen, joka ei pysy kaikissa mitä lakiraamatussa kirjoitettu on, että hän niitä tekis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'Mutta ettei kenkään vanhurskaaksi tule Jumalan edessä lain kautta, se on tiettävä; sillä vanhurskaan pitää elämän uskosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, 'Mutta laki ei ole uskosta, vaan ihminen, joka ne tekee, hän elää niissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'Mutta Kristus on meitä lunastanut lain kirouksesta, koska hän tuli kiroukseksi meidän edestämme; sillä kirjoitettu on: kirottu on jokainen, joka puussa riippuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'Että Abrahamin siunaus pitäis pakanain ylitse Jesuksessa Kristuksessa tuleman, ja me niin saisimme uskon kautta sen luvatun Hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'Rakkaat veljet! minä puhun ihmisten tavalla. Ei yksikään riko ihmisen testamenttia, koska se vahvistettu on, eikä siihen mitään lisää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Lupaukset ovat tosin Abrahamille ja hänen siemenellensä annetut; ei hän sano: ja siemenille, niinkuin monesta, vaan niinkuin yhdestä: ja sinun siemenessäs, joka on Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'Mutta sen minä sanon: testamenttia, joka Jumalalta on vahvistettu Kristuksen päälle, ei rikota, ettei lupaus turhaan raukeaisi lain kautta, joka sitte neljänsadan ja kolmenkymmenen vuoden perästä annettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 18, 'Sillä jos perintö on laista, niin ei se silleen ole lupauksesta; mutta Jumala on sen Abrahamille lupauksen kautta lahjoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 19, 'Mihinkä siis laki? Hän on tullut ylitsekäymisten tähden, siihenasti kuin siemen oli tuleva, jolle lupaus tapahtunut oli, ja on enkeleiltä asetettu välimiehen käden kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 20, 'Mutta välimies ei ole yhden, vaan Jumala on yksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 21, 'Onko siis laki Jumalan lupauksia vastaan? Pois se! Sillä jos laki olis annettu eläväksi tekemään, niin tosin vanhurskaus tulis laista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 22, 'Mutta Raamattu on kaikki sulkenut synnin alle, että lupaus annettaisiin uskon kautta Jesuksen Kristuksen päälle uskovaisille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 23, 'Mutta ennenkuin usko tuli, olimme me lain alla kätketyt ja siihen uskoon suljetut, joka piti ilmoitettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 24, 'Niin on laki ollut meidän opettajamme Kristuksen tykö, että me uskon kautta vanhurskaaksi tulisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 25, 'Mutta sitte kuin usko tuli, niin emme enempi ole sen opettajan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 26, 'Sillä te olette kaikki Jumalan lapset uskon kautta Jesuksen Kristuksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 27, 'Sillä niin monta kuin te Kristukseen kastetut olette, niin te olette Kristuksen päällenne pukeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 28, 'Ei ole tässä Juudalainen eli Grekiläinen, ei orja eli vapaa, ei mies eli vaimo; sillä te olette kaikki yksi Kristuksessa Jesuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 29, 'Mutta jos te olette Kristuksen, niin te olette myös Abrahamin siemen ja lupauksen jälkeen perilliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, 'Mutta minä sanon: niin kauvan kuin perillinen on lapsi, ei ole hänen ja palvelian välillä eroitusta, vaikka hän on kaiken tavaran herra;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'Vaan hän on esimiesten ja haltiain hallussa, isältä määrättyyn aikaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'Niin myös me, kuin me olimme lapset, niin me olimme vaaditut orjuuteen ulkonaisten säätyin alle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'Mutta koska aika oli täytetty, lähetti Jumala Poikansa, syntyneen vaimosta, lain alaiseksi tehdyn,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'Että hän ne, jotka lain alaiset olivat, lunastais, että me hänen lapsiksensa luettaisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Mutta että te olette lapset, lähetti Jumala Poikansa Hengen teidän sydämiinne, joka huutaa: Abba, rakas Isä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, 'Niin ei silleen ole orja, vaan poika; mutta jos poika, niin myös Jumalan perillinen Kristuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'Mutta sillä ajalla, koska ette Jumalaa tunteneet, palvelitte te niitä, jotka ei luonnostansa jumalat olleetkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'Mutta nyt, sittekuin te Jumalan tunnette ja tosin enemmin Jumalalta tutut olette, kuinka te siis käännytte jälleen heikkoihin ja köyhiin säätyihin, joita te vasta-uudesta palvella tahdotte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'Te otatte vaarin päivistä, ja kuukausista, ja ajoista, ja vuosista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'Minä pelkään teidän tähtenne, etten minä turhaan olisi teidän tähtenne työtä tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Olkaat niinkuin minä olen, että minäkin olen niinkuin te. Rakkaat veljet! minä rukoilen teitä: ette ole mitään minua vastaan tehneet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, 'Mutta te tiedätte, että minä olen lihan heikkoudessa teille ensisti evankeliumia saarnannut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'Ja minun kiusaustani, jota minä lihan puolesta kärsin, ette ole katsoneet ylön ettekä hyljänneet, vaan korjasitte minun niinkuin Jumalan enkelin, niinkuin Kristuksen Jesuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'Kuinka autuaat te silloin olitte! Minä olen teidän todistajanne, että jos se olis mahdollinen ollut, niin te olisitte teidän silmänne kaivaneet ulos ja minulle antaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, 'Olenko minä siis nyt teidän viholliseksenne tullut, että minä teille totuuden sanon?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 17, 'Ei he teitä oikein kiivaudesta rakasta, vaan he tahtovat teitä minusta pois kääntää, että te heitä kiivaudessa rakastaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 18, 'Kyllä kiivaten rakastaa hyvä on, aina hyvyydessä, ja ei ainoastaan silloin, kuin minä teidän tykönänne olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 19, 'Minun rakkaat lapseni, jotka minun täytyy vasta-uudesta kivulla synnyttää, siihenasti kuin Kristus teissä jonkun muodon sais!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 20, 'Mutta minä soisin olevani teidän tykönänne, että minä taitaisin äänenikin muuttaa; enpä minä tiedä, mitä minä tästedes teen teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 21, 'Sanokaat minulle te, jotka lain alla olla tahdotte: ettekö te lakia kuule?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 22, 'Sillä kirjoitettu on: Abrahamilla oli kaksi poikaa, yksi palkkavaimosta ja yksi vapaasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 23, 'Mutta joka palkkavaimosta oli, se oli lihan jälkeen syntynyt, ja joka vapaasta oli, se oli lupauksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 24, 'Nämät jotakin merkitsevät; sillä nämät ovat ne kaksi Testamenttia: yksi Sinain vuoresta, joka orjuuteen synnyttää, joka on Agar.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 25, 'Sillä Agar on Sinain vuori Arabiassa ja ulottuu hamaan Jerusalemiin, joka nyt on, ja on lastensa kanssa orjana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 26, 'Mutta se Jerusalem, joka ylhäältä on, on vapaa, joka on kaikkein meidän äitimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 27, 'Sillä kirjoitettu on: iloitse, sinä hedelmätöin, joka et synnytä, pakahda ja huuda sinä, joka et raskas ole; sillä yksinäisellä on enempi lapsia kuin sillä, jolla mies on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 28, 'Mutta me, rakkaat veljet, olemme niinkuin Isaakikin, lupauksen lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 29, 'Mutta niinkuin se silloin, joka lihan jälkeen syntynyt oli, vainosi sitä, joka hengen jälkeen syntynyt oli, niin se nytkin tapahtuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 30, 'Mutta mitä Raamattu sanoo? aja palkkavaimo poikinensa ulos; sillä ei palkkavaimon pojan pidä perimän vapaan pojan kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 31, 'Niin me siis olemme, rakkaat veljet, emme palkkavaimon poikia, vaan vapaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 1, 'Niin pysykäät siis siinä vapaudessa, jolla Kristus meitä vapahtanut on, ja älkäät taas teitänne sekoittako orjuuden ikeeseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 2, 'Katso, minä Paavali sanon teille: jos te annatte ympärileikata teitänne, niin ei ole Kristus teille hyödyllinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 3, 'Mutta minä taas todistan, että jokainen ihminen, joka ympärileikataan, se on kaikkea lakia velkapää pitämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 4, 'Te olette Kristuksen kadottaneet, jotka lain töillä tahdotte vanhurskaiksi tulla, ja olette armosta luopuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 5, 'Mutta me odotamme hengessä uskon kautta vanhurskauden toivoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 6, 'Sillä ei Kristuksessa Jesuksessa ympärileikkaus eikä esinahka mitään kelpaa, vaan usko, joka rakkauden kautta työtä tekee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 7, 'Te juoksitte hyvin; kukas teidät esti totuutta uskomasta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 8, 'Ei senkaltainen yllytys ole hänestä, joka teitä kutsuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 9, 'Vähä hapatus kaikentaikinan hapattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 10, 'Minä turvaan teihin Herrassa, ettette toista mieltä ottaisi; mutta joka teitä eksyttää, hänen pitää tuomionsa kantaman, olkaan kuka hän olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 11, 'Mutta jos minä vielä, rakkaat veljet, ympärileikkausta saarnaan, minkätähden minä siis vainoa kärsin? Ja niin olis ristin pahennus hävinnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 12, 'Oi jospa ne eroitettaisiin, jotka teitä houkuttelevat!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 13, 'Sillä te, rakkaat veljet, olette vapauteen kutsutut; ainoastaan karttakaat, ettette salli vapauden lihalle tilaa antaa, vaan palvelkaat rakkaudessa toinen toistanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 14, 'Sillä kaikki laki yhdessä sanassa täytetään, nimittäin: rakasta lähimmäistäs niinkuin itsiäs.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 15, 'Mutta jos te toinen toistanne purette ja syötte, niin katsokaat, ettette toinen toiseltanne syödyksi tule.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 16, 'Mutta minä sanon: vaeltakaat Hengessä, niin ette lihan himoa täytä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 17, 'Sillä liha himoitsee Henkeä vastaan, ja Henki lihaa vastaan: nämät ovat vastaan toinen toistansa, niin ettette tee, mitä te tahdotte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 18, 'Mutta jos te Hengeltä hallitaan, niin ette ole lain alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 19, 'Mutta lihan työt ovat julkiset, kuin on huoruus, salavuoteus, saastaisuus, haureus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 20, 'Epäjumalain palvelus, noituus, vaino, riita, kateus, viha, torat, eripuraisuus, eriseura,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 21, 'Pahansuomuus, murha, juopumus, ylönsyömyys ja muut senkaltaiset, joista minä teille edellä sanon, niinkuin minä ennenkin sanonut olen, että ne, jotka senkaltaisia tekevät, ei pidä Jumalan valtakuntaa perimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 22, 'Mutta Hengen hedelmä on: rakkaus, ilo, rauha, pitkämielisyys, ystävyys, hyvyys, usko, hiljaisuus, puhtaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 23, 'Senkaltaisia vastaan ei ole laki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 24, 'Mutta jotka Kristuksen omat ovat, ne ovat ristiinnaulinneet lihansa, himoin ja haluin kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 25, 'Jos me Hengessä elämme, niin vaeltakaamme myös Hengessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 26, 'Älkäämme turhaa kunniaa pyytäkö, vihoittain ja kadehtien toinen toistamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 1, 'Rakkaat veljet! jos ihminen osaa johonkuhun vikaan tulla, niin te, jotka hengelliset olette, ojentakaat senkaltaista siveyden hengessä: ja katso itsiäs, ettes sinä myös kiusattaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 2, 'Kantakaat toinen toisenne kuormaa ja niin Kristuksen lakia täyttäkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 3, 'Sillä jos joku luulee itsensä jotakin olevan, joka ei kuitenkaan mitään ole, hän viettelee itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 4, 'Mutta koetelkaan kukin oman tekonsa, ja sitte hän taitaa ainoasti itsestänsä kerskata, ja ei yhdessäkään muussa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 5, 'Sillä kukin pitää oman kuormansa kantaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 6, 'Joka sanalla neuvotaan, se jakakaan kaikkea hyvää sille, joka häntä neuvoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 7, 'Älkäät eksykö; ei Jumala anna itsiänsä pilkata: sillä mitä ihminen kylvää, sitä hän myös niittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 8, 'Joka lihassansa kylvää, se lihastansa turmeluksen niittää; mutta joka hengessä kylvää, se hengestä ijankaikkisen elämän niittää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 9, 'Ja koska me hyvää teemme, niin älkäämme suuttuko; sillä aikanansa mekin saamme niittää ilman lakkaamatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 10, 'Koska siis meillä aika on, niin tehkäämme jokaiselle hyvää, mutta enimmiten niille, jotka meidän kanssaveljemme uskossa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 11, 'Katsokaat, kuinka suuren lähetyskirjan minä olen teille omalla kädelläni kirjoittanut!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 12, 'Jotka tahtovat myös näön jälkeen lihassa kelvata, ne teitä ympärileikkaukseen vaativat, ainoastaan ettei heitä Kristuksen ristillä vainottaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 13, 'Sillä ei nekään, jotka ympärileikataan, lakia pidä; vaan he tahtovat teidät ympärileikata, että he teidän lihastanne kerskata saisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 14, 'Mutta pois se minusta, että minä muusta kerskaisin, vaan ainoastansa meidän Herran Jesuksen Kristuksen rististä, jonka kautta maailma minulle ristiinnaulittu on ja minä maailmalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 15, 'Sillä Kristuksessa Jesuksessa ei ympärileikkaus eikä esinahka mitään kelpaa, vaan uusi luontokappale.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 16, 'Ja niin monta, jotka tämän ojennusnuoran jälkeen vaeltavat, heidän päällänsä olkoon rauha ja laupius, ja Jumalan Israelin päällä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 17, 'Älköön yksikään tästälähin minua silleen vaivatko; sillä minä kannan minun ruumiissani meidän Herran Jesuksen Kristuksen arvet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 18, 'Meidän Herran Jesuksen Kristuksen armo olkoon teidän henkenne kanssa, rakkaat veljet, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Paavali, Jesuksen Kristuksen apostoli Jumalan tahdon kautta, pyhille, jotka Ephesossa asuvat ja Kristuksen Jesuksen päälle uskovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Armo olkoon teille ja rauha Jumalalta meidän Isältämme ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Kiitetty olkoon Jumala ja meidän Herran Jesuksen Kristuksen Isä, joka meitä on siunannut kaikkinaisella hengellisellä siunauksella taivaallisissa Kristuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Niinkuin hän meitä on sen kautta valinnut, ennenkuin maailman perustus laskettu oli, että me olisimme pyhät ja laittamattomat rakkaudessa hänen edessänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Ja on säätänyt meitä korjattaa lapsiksensa, Jesuksen Kristuksen kautta, hyvän tahtonsa jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'Kunniallisen armonsa kiitokseksi, jonka kautta hän on meitä otolliseksi tehnyt siinä rakkaassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Jossa meillä on lunastus hänen verensä kautta, nimittäin syntein anteeksi-antamus, hänen armonsa rikkauden jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Jonka hän meille runsaasti kaikkinaisen viisauden ja taidon kautta antanut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ja on meille tahtonsa salaisuuden hyvästä suomastansa tiettäväksi tehnyt, ja sen hänen kauttansa tuottanut edes,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Kuin aika täytetty oli, että hän kaikki kappaleet päältä-iskein Kristuksessa yhdistäis, sekä ne, jotka taivaassa, että myös ne, jotka maan päällä ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Hänessä, jonka kautta me myös perillisiksi tulleet olemme, jo ennen hänen aivoituksensa jälkeen säädetyt, joka kaikki kappaleet oman tahtonsa neuvon jälkeen vaikuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Että me olisimme hänen kunniansa kiitokseksi, me jotka ennen Kristuksen päälle toivoimme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Jonka kautta te myös totuuden sanan kuulleet olette, nimittäin evankeliumin teidän autuudestanne: jonka kautta te myös, sittekuin te uskoitte, kiinnitetyt olette lupauksen Pyhällä Hengellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Joka meidän perintömme pantti on meidän lunastukseemme, että me hänen omaisensa olisimme, hänen kunniansa kiitokseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Sentähden minäkin, sittekuin minä kuulin siitä uskosta, joka teillä Herran Jesuksen päälle on, ja teidän rakkaudestanne kaikkein pyhäin tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'En lakkaa kiittämästä Jumalaa teidän edestänne, ajatellen aina teitä minun rukouksissani:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Että meidän Herran Jesuksen Kristuksen Jumala, kunnian Isä, antais teille viisauden ja ilmoituksen hengen hänen tuntemiseensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Ja valaisis teidän ymmärryksenne silmät, että te tietäisitte, minkä hänen kutsumisensa toivo on ja mikä hänen kunniansa perimisen rikkaus on hänen pyhissänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Ja kuinka suuri hänen voimansa meidän kohtaamme on, jotka hänen väkevän voimansa vaikuttamisen jälkeen uskomme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Jonka hän Kristuksessa vaikutti, kuin hän hänen kuolleista herätti ja pani istumaan oikialle kädellensä taivaissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 21, 'Kaiken hallituksen ja vallan ja väkevyyden ja herrauden päälle, ja kaiken sen päälle, joka nimittää taidetaan ei ainoastaan tässä maailmassa, mutta myös tulevaisessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 22, 'Ja on kaikki pannut hänen jalkainsa alle, ja on myös hänen pannut pääksi kaikkein päälle seurakunnalle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 23, 'Joka on hänen ruumiinsa, sen täyttämys, joka kaikki kaikissa täyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Ja myös (herätti) teidät, kuin te kuolleet olitte ylitsekäymisten ja syntein tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Joissa te muinen vaelsitte, tämän maailman juoksun jälkeen ja sen pääruhtinaan, jolla tuulessa valta on, nimittäin sen hengen jälkeen, joka nyt epäuskoisissa lapsissa vaikuttaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Joiden seassa me myös kaikki muinen meidän lihamme himoissa vaelsimme ja teimme lihan ja toimen tahdon jälkeen, ja me olimme luonnostamme vihan lapset niinkuin muutkin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Mutta Jumala, joka rikas on laupiudesta, suuren rakkautensa tähden, jolla hän on meitä rakastanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Ja kuin me vielä synnissä kuolleet olimme, on hän meitä Kristuksen kanssa eläväksi tehnyt; (sillä armosta olette te autuaiksi tulleet:)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Ja on meidät ynnä hänen kanssansa herättänyt, ja istuttanut taivaallisiin menoihin Kristuksessa Jesuksessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Että hän tulevaisilla ajoilla ylönpalttisen armonsa rikkauden hyvyydestänsä meidän kohtaamme Kristuksessa Jesuksessa osoittais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Sillä armosta te olette autuaiksi tulleet, uskon kautta, ja ette itse teissänne: Jumalan lahja se on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Ei töistä, ettei yksikään kerskaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Sillä me olemme hänen tekonsa, luodut Kristuksessa Jesuksessa hyviin töihin, joihin Jumala meidät on jo ennen vaeltamaan valmistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Sentähden muistakaat, että te olitte muinen pakanat lihan jälkeen, ja niiltä kutsuttiin esinahaksi, jotka lihan jälkeen ympärileikkaukseksi kutsuttiin, joka käsillä tehdään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Että te siihen aikaan ilman Kristusta olitte muukalaiset Israelin kyläkunnasta, ja vieraat lupauksen Testamentista, ja ei teillä toivoakaan ollut, ja olitte maailmassa ilman Jumalaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Mutta nyt te Kristuksessa Jesuksessa olette. Jotka muinen taampana olitte, nyt te Kristuksen veren kautta olette lähes päässeet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Sillä hän on meidän rauhamme, joka molemmista on yhden tehnyt ja vaihe-aidan särkenyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Että hän lihansa kautta vihan otti pois, nimittäin lain, joka käskyihin päätetty oli; että hän kahdesta yhden uuden ihmisen lois itsessänsä, ja tekis rauhan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Ja että hän ne molemmat Jumalan kanssa yhdessä ruumiissa ristin kautta sovittais, ja on vihan itse kauttansa kuolettanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Ja on tullut evankeliumin kautta rauhaa ilmoittamaan teille, jotka taampana olitte, ja niille, jotka läsnä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Sillä hänen kauttansa me molemmin yhdessä hengessä saamme Isää lähestyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Niin ettepä te silleen ole vieraat ja muukalaiset, vaan pyhäin kylänmiehet ja Jumalan perhe,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Apostolein ja prophetain perustuksen päälle rakennetut, jossa Jesus Kristus paras kulmakivi on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Jonka päälle kaikki rakennus toinen toiseensa liitetään ja kasvaa pyhäksi templiksi Herrassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Jonka päälle te myös rakennetaan Jumalalle asuinsiaksi Hengessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Sentähden minä Paavali, Jesuksen Kristuksen vanki, teidän pakanain tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Jos te muutoin kuulleet olette Jumalan armon huoneenhallituksesta, joka minulle teidän puoleenne annettu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Että minulle on tämä salaus ilmoituksen kautta tiettäväksi tehty, niinkuin minä jo ennen lyhykäisesti kirjoitin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Josta te lukein taidatte minun ymmärrykseni Kristuksen salaisuudessa tuta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Joka ei ole entisiin aikoihin niin ihmisten lapsille tiettäväksi tehty, kuin se nyt hänen pyhille apostoleillensa ja prophetaillensa Hengen kautta ilmoitettu on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Nimittäin, että pakanat pitää kanssaperilliset ja yksi ruumis oleman ja osalliset hänen lupauksestansa Kristuksessa, evankeliumin kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Jonka palveliaksi minä tullut olen Jumalan armon lahjan kautta, joka hänen voimansa vaikutuksesta minulle annettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Minulle, joka kaikkein vähin pyhäin seassa olen, on tämä armo annettu, että minä pakanain seassa tutkimattoman Kristuksen rikkauden julistaisin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Ja jokaiselle valkeuteen saattaisin, mikä osallisuus siinä salaisuudessa on, joka ijankaikkisesti on salattu ollut Jumalassa, joka kaikki Jesuksen Kristuksen kautta luonut on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Että nyt haltioille ja esivalloille taivaallisissa Jumalan moninainen viisaus seurakunnan kautta tiettäväksi tulis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Sen ijankaikkisen aivoituksen jälkeen, jonka hän Kristuksessa Jesuksessa meidän Herrassamme osoittanut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Jonka kautta meillä on uskallus ja tykökäymys kaikella rohkeudella, uskon kautta hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Sentähden minä rukoilen, ettette minun vaivaini tähden väsyisi, joita minä teidän edestänne kärsin, joka teidän kunnianne on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Sentähden kumarran minä polveni meidän Herran Jesuksen Kristuksen Isän puoleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Joka kaikkein oikia Isä on, jotka taivaissa ja maassa lapsiksi kutsutaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Että hän antais teille voimaa kunniansa rikkauden jälkeen, että te hänen Henkensä kautta väkeväksi tulisitte sisällisessä ihmisessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Ja että Kristus asuis uskon kautta teidän sydämissänne;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Että te olisitte rakkauden kautta juurtuneet ja perustetut; että te selkiästi käsittäisitte kaikkein pyhäin kanssa, mikä leveys ja pituus, ja syvyys ja korkeus olis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ja Kristuksen rakkauden tuntisitte, joka kaiken tuntemisen ylitse käy; että te olisitte kaikella Jumalan täydellisyydellä täytetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Mutta hänelle, joka kaikki ylönpalttisesti voi tehdä, kaiken senkin ylitse, kuin me rukoilemme taikka ymmärrämme, sen voiman jälkeen, joka meissä vaikuttaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Hänelle olkoon kunnia seurakunnassa, joka on Kristuksessa Jesuksessa, kaikkiin aikoihin ijankaikkisesta niin ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Niin minä vangittu Herrassa neuvon teitä, että te siinä kutsumisessa, johon te kutsutut olette, niin vaeltaisitte kuin sopii,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Kaikella nöyryydellä, siveydellä ja pitkämielisyydellä, ja kärsikäät toinen toistanne rakkaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Ahkeroitkaat myös pitämään hengen yhteyttä rauhan siteen kautta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Yksi ruumis ja yksi henki, niinkuin tekin olette teidän kutsumisessanne yhdenkaltaiseen toivoon kutsutut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Yksi Herra, yksi usko, yksi kaste,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Yksi Jumala ja kaikkein Isä, joka kaikkein päällä on, ja kaikkein kautta, ja teissä kaikissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Mutta jokaiselle meille on armo annettu Kristuksen lahjan mitan jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Sentähden hän sanoo: hän on astunut ylös korkeuteen, ja on vankiuden vangiksi vienyt, ja ihmisille lahjoja antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Mutta se, että hän astui ylös, ei ole mikään muu kuin että hän ennen tänne astui alas, alimmaisiin maan paikkoihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Joka on astunut alas, hän on se, joka kaikkein taivasten päälle astui ylös, että hän kaikki täyttäis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Ja hän on pannut muutamat apostoleiksi, muutamat prophetaiksi, muutamat evankelistaiksi, muutamat paimeniksi ja opettajiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 12, 'Pyhäin täydellisyyteen, palveluksen työhön ja Kristuksen ruumiin rakennukseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 13, 'Siihenasti kuin me kaikki tulemme uskon ja Jumalan Pojan tuntemisen yhteydessä täydeksi mieheksi, Kristuksen täydellisen varren mitan jälkeen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 14, 'Ettemme silleen lapset olisi, jotka horjuisimme ja kaikkinaisilta opetuksen tuulilta vieteltäisiin, ihmisten koiruuden ja kavaluuden kautta, jolla he meitä käyvät ympäri, saadaksensa pettää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 15, 'Mutta olkaamme toimelliset rakkaudessa ja kasvakaamme kaikissa, hänessä, joka pää on, Kristus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 16, 'Josta koko ruumis on koottu ja yhteen liitetty, kaiken yhdistyksen kautta, joka siihen lisääntyy, sen vaikutuksen ja määrän jälkeen, joka kullakin jäsenellä on, siitä kasvaa ruumis omaksi rakennukseksensa rakkaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 17, 'Niin minä nyt sanon ja todistan Herrassa, ettette silleen vaella niinkuin muut pakanat vaeltavat mielensä tyhmyydessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 18, 'Joiden ymmärrys pimitetty on ja ovat vieraantuneet siitä elämästä, joka Jumalasta on, tyhmyyden kautta, joka heissä on, ja heidän sydämensä kovuuden kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 19, 'Jotka, sitten kuin he olivat paatuneet, antoivat ylön heitänsä haureuteen ja tekivät kaikkinaista saastaisuutta ylönpalttisessa himossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 20, 'Mutta ette niin Kristusta ole oppineet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 21, 'Jos te muutoin hänestä kuulleet olette ja hänessä opetetut olette, niinkuin totuus Jesuksessa on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 22, 'Niin pankaat pois vanha ihminen, jonka kanssa te ennen vaelsitte, joka himoin kautta eksyksissä itsensä turmelee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 23, 'Mutta uudistakaat teitänne teidän mielenne hengessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 24, 'Ja pukekaat päällenne uusi ihminen, joka Jumalan jälkeen luotu on, totisessa vahurskaudessa ja pyhyydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 25, 'Sentähden pankaat pois valhe, ja puhukaan jokainen lähimmäisensä kanssa totuutta; sillä me olemme jäsenet keskenämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 26, 'Vihastukaat ja älkäät syntiä tehkö, älkäät antako auringon laskea ylitse teidän vihanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 27, 'Älkäät antako laittajalle siaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 28, 'Joka varastanut on, älkään silleen varastako, vaan paremmin tehkään työtä ja toimittakaan käsillänsä jotakin hyvää, että hänellä olis tarvitsevalle jakamista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 29, 'Älköön yksikään rietas puhe teidän suustanne lähtekö, vaan mitä sovelias on parannuksen tarpeeksi, että se kelvollinen kuulla olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 30, 'Ja älkäät Jumalan Pyhää Henkeä murheelliseksi saattako, jossa te lunastuksen päivään asti kiinnitetyt olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 31, 'Kaikki haikeus, ja närkästys, ja viha, ja huuto, ja sadatus olkoon kaukana teistä kaiken pahuuden kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 32, 'Mutta olkaat keskenänne ystävälliset ja laupiaat, ja anteeksi antakaat toinen toisellenne niinkuin Jumala teillekin Kristuksen kautta anteeksi antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Niin olkaat siis Jumalan seuraajat, niinkuin rakkaat lapset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Ja vaeltakaat rakkaudessa, niinkuin myös Kristus meitä rakasti ja antoi itsensä ulos meidän edestämme lahjaksi, uhriksi ja Jumalalle makiaksi hajuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Mutta huoruutta ja kaikkea riettautta eli ahneutta älkäät antako teidän seassanne mainitakaan, niinkuin pyhäin sopii,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Ja häpiällisiä sanoja ja hulluja puheita eli jaarituksia, jotka ei mihinkään kelpaa, vaan paremmin kiitossanoja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Sillä se te tietäkäät, ettei yksikään huorintekiä, taikka saastainen, eli ahne, joka epäjumalan palvelia on, ole Kristuksen ja Jumalan valtakunnan perillinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Älkäät antako yhdenkään pettää teitänne turhilla puheilla; sillä sentähden Jumalan viha epäuskoisten päälle tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Älkäät sentähden olko heidän osaveljensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Sillä muinen te olitte pimeys, mutta nyt te olette valkeus Herrassa. Vaeltakaat niinkuin valkeuden lapset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, '(Sillä Hengen hedelmä on kaikessa hyvyydessä ja vanhurskaudessa ja totuudessa,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Ja koetelkaat, mikä Herralle otollinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Älkäät olko osalliset pimeyden hedelmättömissä töissä, vaan paremmin nuhdelkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Sillä mitä salaa heilta tapahtuu, se on häpiä sanoakin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Mutta kaikki ne ilmi tulevat, kuin he valkeudelta rangaistaan; sillä kaikki, mikä ilmi tulee, se on valkeus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Sentähden hän sanoo: heräjä sinä, joka makaat, ja nouse kuolleista, niin Kristus sinua valaisee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 15, 'Niin katsokaat, että te visusti vaellatte, ei niinkuin tyhmät, vaan niinkuin viisaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 16, 'Ja hankitkaat teitänne ajallansa; sillä aika on paha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 17, 'Älkäät sentähden olko taitamattomat, vaan ymmärtäväiset, mikä Herran tahto on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 18, 'Ja älkäät juopuko viinasta, josta paha meno tulee, vaan olkaat täytetyt (Pyhällä) Hengellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 19, 'Ja puhukaat keskenänne psalmeilla, ja kiitosvirsillä, ja hengellisillä lauluilla, veisaten ja soittain Herralle teidän sydämessänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 20, 'Kiittäin aina Jumalaa ja Isää, jokaisen edestä, meidän Herran Jesuksen Kristuksen nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 21, 'Ja olkaat toinen toisellenne alamaiset Jumalan pelvossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 22, 'Vaimot olkaat omille miehillenne alamaiset niinkuin Herralle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 23, 'Sillä mies on vaimon pää, niinkuin Kristus on seurakunnan pää, ja hän on ruumiin vapahtaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 24, 'Mutta niinkuin seurakunta on Kristukselle alamainen, niin myös vaimot pitää miehillensä kaikissa alamaiset oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 25, 'Miehet, rakastakaat teidän vaimojanne, niinkuin myös Kristus seurakuntaa rakasti ja antoi ulos itsensä hänen edestänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 26, 'Että hän sen pyhittäis, ja on sen jo puhdistanut veden pesossa sanan kautta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 27, 'Että hän saattais itsellensä kunniallisen seurakunnan, jolla ei saastaisuutta eikä ryppyä ole eli jotakuta muuta senkaltaista, vaan että hän pyhä ja laittamatoin olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 28, 'Miehet pitää vaimojansa rakastaman niinkuin omia ruumiitansa; joka vaimoansa rakastaa, se rakastaa itsiänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 29, 'Sillä ei yksikään ole omaa lihaansa koskaan vihannut, vaan elättää ja holhoo sitä, niinkuin myös Herra seurakuntaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 30, 'Sillä me olemme hänen ruumiinsa jäsenet, hänen lihastansa ja luistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 31, 'Sentähden pitää ihmisen antaman ylön isänsä ja äitinsä, ja vaimoonsa sidottu oleman, ja ne kaksi tulevat yhdeksi lihaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 32, 'Tämä salaisuus on suuri; mutta minä puhun Kristuksesta ja seurakunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 33, 'Kuitenkin rakastakaan myös kukin teistä vaimoansa niinkuin itsiänsä; mutta peljätköön vaimo miestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Lapset, olkaat kuuliaiset teidän vanhemmillenne Herrassa; sillä se on oikein.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Kunnioita isääs ja äitiäs, (joka on ensimäinen käsky, jolla lupaus on,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Ettäs menestyisit ja kauvan eläisit maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Ja te isät, älkäät yllyttäkö lapsianne vihaan, vaan kasvattakaat heitä kurituksessa ja Herran nuhteessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Palveliat, olkaat kuuliaiset teidän ruumiillisille isännillenne, pelvolla ja vapistuksella, teidän sydämenne yksinkertaisuudessa, niinkuin Kristukselle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Ei silmäin edessä palvellen, niinkuin ihmisten mieltä noutain, vaan niinkuin Kristuksen palveliat, tehden sydämestä, mitä Jumala tahtoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Hyvällä mielellä palvellen Herraa, ja ei ihmisiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Tietäen, että mitä hyvää kukin tekee, sen hän on jälleen Herralta saapa, olkoon orja eli vapaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Ja te isännät, tehkäät myös niin heitä kohtaan, ja pankaat pois uhkaukset, tietäen, että teidän Herranne on myös taivaissa, jonka edessä ei ole ihmisen muodon katsomusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Viimein, rakkaat veljeni, olkaat väkevät Herrassa ja hänen väkevyytensä voimassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Pukekaat päällenne kaikki Jumalan sota-aseet, että te perkeleen kavalia päällekarkaamisia voisitte seisoa vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Sillä ei meillä ole sota verta ja lihaa vastaan, vaan pääruhtinaita ja valtoja vastaan, maailman herroja vastaan, jotka tämän maailman pimeydessä vallitsevat, pahoja henkiä vastaan taivaan alla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Sentähden ottakaat kaikki Jumalan sota-aseet, että te voisitte pahana päivänä seisoa vastaan ja kaikissa asioissa pysyväiset olisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Niin seisokaat vyötetyt kupeista totuudella, ja vanhurskauden rintaraudalla puetetut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Ja jalat valmiiksi kengitetyt, saarnaamaan rauhan evankeliumia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Mutta kaikissa ottakaat uskon kilpi, jolla te voitte sammuttaa kaikki ruman tuliset nuolet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Ja ottakaat päähänne autuuden rautalakki, ja hengen miekka, joka on Jumalan sana,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 18, 'Ja rukoilkaat joka aika kaikella rukoilemisella ja anomisella hengessä, ja siinä valvokaat kaikella ahkeruudella ja rukouksella kaikkein pyhäin tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 19, 'Ja minunkin tähteni, että minulle puhetta annettaisiin avoimella suulla rohkiasti puhuakseni, ja niin tiettäväksi tekisin evankeliumin salaisuuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 20, 'Jonka käskyläinen minä näissä kahleissa olen, että minä niissä rohkiasti puhuisin, niinkuin minun puhua tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 21, 'Mutta että te myös tietäisitte minun tilani ja mitä minä teen, kaiken sen on Tykikus, minun rakas veljeni ja uskollinen palvelia Herrassa, teille tiettäväksi tekevä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 22, 'Jonka minä teidän tykönne lähetin sen syyn tähden, että te saisitte tietää meidän tilamme ja hän teidän sydämenne lohduttais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 23, 'Rauha olkoon veljille, ja rakkaus uskon kanssa, Isältä Jumalalta ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 24, 'Armo olkoon kaikkein kanssa, jotka meidän Herraa Jesusta Kristusta lakkaamatta rakastavat, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, 'Paavali ja Timoteus, Jesuksen Kristuksen palveliat, kaikille pyhille Kristuksessa Jesuksessa, jotka Philipissä ovat, ynnä piispoille ja palvelioille:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'Armo olkoon ja rauha Jumalalta, meidän Isältämme, ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, 'Minä kiitän minun Jumalaani, niin usein kuin minä teitä muistan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, '(Aina kaikissa minun rukouksissani teidän edestänne, ja rukoilen ilolla,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'Että te olette evankeliumista osalliseksi tulleet, ensimäisestä päivästä niin tähän asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, 'Sen totisesti tietäen, että se, joka teissä on hyvän työn alkanut, on sen Jesuksen Kristuksen päivään asti päättävä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'Niinkuin minulle on myös kohtuullinen teistä kaikista niin ajatella, sentähden, että minä teidät sydämessäni pidän, sekä minun kahleissani, että evankeliumin edesvastauksessa ja vahvistuksessa, te kaikki, jotka minun kanssani armosta osalliset olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, 'Sillä Jumala on minun todistajani, että minä sydämen pohjasta kaikkia teitä Jesuksessa Kristuksessa halajan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'Ja sitä rukoilen, että teidän rakkautenne enemmin ja enemmin yltäkylläiseksi tulis kaikkinaisessa tuntemisessa ja ymmärryksessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'Että te koettelisitte, mikä paras olis, ja olisitte vilpittömät, ei kellenkään pahennukseksi Kristuksen päivään asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'Täytetyt vanhurskauden hedelmillä, jotka Jesuksen Kristuksen kautta teissä tapahtuvat, Jumalan kiitokseksi ja kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'Mutta minä tahdon, että te, rakkaat veljet, tietäisitte, että ne, mitkä minulle tapahtuneet ovat, ovat enemmäksi evankeliumin menestykseksi tulleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 13, 'Niin että minun siteeni ovat ilmi tulleet Kristuksessa koko raastuvassa ja myös kaikille muille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 14, 'Ja että monta veljeä Herrassa, minun siteistäni vahvistetut, ovat paljoa rohkiammaksi tulleet pelkäämättä sanaa puhumaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 15, 'Muutamat tosin saarnaavat Kristusta kateudesta ja riidasta, mutta muutamat hyvästä tahdosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 16, 'Ne ilmoittavat Kristusta eripuraisuudesta, ei puhtaalla sydämellä, vaan luulevat niin lisäävänsä minun siteihini murhetta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 17, 'Mutta nämät rakkaudesta; sillä he tietävät minun olevan pantuna evankeliumin edesvastaamiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 18, 'Mitäs siis? Että Kristus kuitenkin ilmoitetaan, ehkä kuinka se tapahtuu, joko se olis muodoksi, eli totuudella; niin minä siitä iloitsen ja vielä tahdon iloita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 19, 'Sillä minä tiedän sen minulleni joutuvan autuudeksi teidän rukouksenne ja Jesuksen Kristuksen hengen avun kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 20, 'Niinkuin minä ikävöiden odotan ja toivon, etten minä missään häpiään tule, vaan että Kristus nyt, niinkuin ainakin, kaikella vapaudella minun ruumiissani ylistetään, joko elämän eli kuoleman kautta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 21, 'Sillä Kristus on minulle elämä, ja kuolema on minulle voitto.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 22, 'Mutta jos lihassa elää, se on minulle tarpeellinen, ja mitä minä valitsen, en minä tiedä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 23, 'Sillä molemmilta minä ahdistetaan: minä halajan täältä eritä ja olla Kristuksen kanssa; sillä se paljoa parempi olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 24, 'Mutta paljoa tarpeellisempi on lihassa olla teidän tähtenne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 25, 'Ja minä tiedän totisesti, että minun pitää oleman ja teidän kaikkein kansanne pysymän, teidän menestykseksenne ja uskonne iloksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 26, 'Että teidän kerskaamisenne olis yltäkylläinen Kristuksessa Jesuksessa minusta, minun läsnäolemiseni kautta taas teidän tykönänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 27, 'Ainoastaan käyttäkäät itsenne niinkuin Kristuksen evankeliumille sovelias on, että jos minä tulen ja näen teidät eli poissa ollessani saan kuulla teistä, että te olette yhdessä hengessä ja yhdessä sielussa meidän kanssamme evankeliumin uskossa kilvoitelleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 28, 'Ja älkäät antako missään peljättää teitänne vastaanseisojilta, joka tosin heille kadotuksen merkki on, mutta teille autuudeksi, ja se on Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 29, 'Sillä teille on lahjaksi annettu Kristuksen puolesta, ei ainoasti että te hänen päällensä uskotte, mutta myös kärsitte hänen tähtensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 30, 'Ja pysytte siinä kilvoituksessa, jonka te minussa näitte ja nyt minusta kuulette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 1, 'Jos siis joku neuvo on teidän tykönänne Kristuksessa, jos joku rakkauden lohdutus, jos joku hengen osallisuus, jos joku sydämellinen rakkaus ja laupius,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 2, 'Niin täyttäkäät minun iloni, että teillä olis yksi mieli, yhtäläinen rakkaus, ja te olisitte yksimieliset ja yhtäpitäväiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 3, 'Älkäät tehkö mitään riidan eli turhan kunnian kautta, vaan nöyryydessä pitäin toinen toisensa parempana kuin itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 4, 'Ja älkään jokainen omaa parastansa katsoko, vaan myös toisen parasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 5, 'Kullakin olkoon se ajatus, joka Kristuksella Jesuksella oli,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 6, 'Joka, vaikka hän oli Jumalan muodossa, ei lukenut saaliiksi Jumalan kaltainen olla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 7, 'Vaan alensi itsensä, otti orjan muodon päällensä ja tuli muiden ihmisten vertaiseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 8, 'Ja löydettiin menoissa niinkuin ihminen, nöyryytti itsensä ja oli kuolemaan saakka kuuliainen, ja ristin kuolemaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 9, 'Sentähden on Jumala hänen myös korottanut ja antanut hänelle nimen, joka kaikkia nimiä suurin on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 10, 'Että Jesuksen nimeen pitää kaikki polvet heitänsä kumartaman, jotka taivaassa ja maan päällä ja maan alla ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 11, 'Ja kaikki kielet pitää tunnustaman, että Jesus Kristus on Herra, Isän Jumalan kunniaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 12, 'Sentähden, minun rakkaani, niinkuin te aina olette kuuliaiset olleet, (ei ainoastansa minun läsnäollessani, mutta nyt paljoa enemmin minun poissa-ollessani), laittakaat pelvolla ja vapistuksella, että te autuaaksi tulisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 13, 'Sillä Jumala vaikuttaa teissä sekä tahdon että toimituksen, hyvän suosionsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 14, 'Tehkäät kaikki napisematta ja kamppailematta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 15, 'Että te olisitte laittamattomat ja yksivakaiset, nuhteettomat Jumalan lapset pahanilkisen ja nurjan sukukunnan keskellä, joiden seassa te paistakaat niinkuin kynttilät maailmassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 16, 'Että te elämän sanassa pysytte, minulle Kristuksen päivänä kerskaamiseksi, etten minä hukkaan juossut olisi eli turhaan työtä tehnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 17, 'Ja jos minä uhrattaisiin teidän uhrin ja uskon palveluksenne tähden, niin minä iloitsen ja riemuitsen kaikkein teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 18, 'Sentähden tekin minun kanssani iloitkaat ja riemuitkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 19, 'Mutta minä toivon Herrassa Jesuksessa, että minä pian Timoteuksen teidän tykönne lähetän, että minäkin ihastuisin, kuin minä tietää saan, kuinka teidän tilanne on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 20, 'Sillä ei minulla ole ketään, jolla yksi mieli minun kanssani on ja joka niin visusti murheen teistä pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 21, 'Sillä he etsivät kaikki omaansa ja ei niitä mitkä Jesuksen Kristuksen ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 22, 'Mutta te tiedätte hänen koettelemuksensa; sillä niinkuin lapsi isänsä kanssa on, niin on hän minun kanssani evankeliumissa palvellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 23, 'Tämän siis minä toivon lähettäväni, kuin minä olen asiani toimittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 24, 'Mutta minä uskallan Herran päälle, että minä itsekin olen pian tuleva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 25, 'Vaan minä olen nähnyt tarpeelliseksi teidän tykönne lähettää veljeä Epaphroditusta, joka minun virkaveljeni ja sotakumppanini ja teidän myös apostolinne on, joka minua myös tarpeessani autti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 26, 'Sillä hän ikävöitsi kaikkia teitä, ja oli kovin suruissansa, että te hänen sairaaksi kuulleet olitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 27, 'Ja tosin hän oli jo kuoleman kielissä; mutta Jumala armahti hänen päällensä, ja ei ainoastaan hänen, vaan myös minun päälleni, etten minä murhetta murheen päälle olisi saanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 28, 'Sentähden olen minä hänen sitä pikemmin lähettänyt, että te taas hänen saisitte nähdä ja iloitsisitte, ja minulla myös vähempi murhetta olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 29, 'Niin ottakaat häntä Herrassa vastaan kaikella ilolla ja pitäkäät senkaltaiset kunniassa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 30, 'Sillä Kristuksen työn tähden oli hän niin kuolemaa lähestynyt, ettei hän hengestänsä totellut, että hän olis minua teidän puolestanne palvellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 1, 'Vielä, minun veljeni, iloitkaat Herrassa. Että minä teille yhdellä tavalla kirjoitan, en minä siitä suutu; sillä se tekee teidän vahvemmaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 2, 'Kavahtakaat teitänne koirilta, kavahtakaat teitänne pahoilta työmiehiltä, kavahtakaat poisleikkaamisesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 3, 'Sillä me olemme se ympärileikkaus, jotka Jumalaa hengessä palvelemme ja kerskaamme meitämme Kristuksessa Jesuksessa, ja emme turvaa lihaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 4, 'Ehkä minulla on, johon minä lihassakin turvaan. Jos joku näkyy lihaan uskaltavan, minä paljoa enemmin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 5, 'Joka kahdeksantena päivänä ympärileikattu olen, Israelin kansasta, Benjaminin suvusta, Hebrealainen Hebrealaisista, lain jälkeen Pharisealainen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 6, 'Kiivaudesta seurakunnan vainooja, vanhurskaudessa, joka laista tulee, laittamatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 7, 'Mutta ne, mitkä minulla olivat voittona, olen minä Kristuksen tähden vahingoksi lukenut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 8, 'Sillä minä luen kaikki vahingoksi sen ylönpalttisen Kristuksen Jesuksen, minun Herrani tuntemisen suhteen, jonka tähden minä olen kaikki vahingoksi lukenut, ja ne raiskana pidän, että minä Kristuksen voittaisin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 9, 'Ja hänessä löydettäisiin, ettei minun vanhurskauteni laista olisi, vaan joka tulee uskosta Kristuksen päälle, nimittäin se vanhurskaus, joka Jumalalta uskolle omistetaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 10, 'Häntä tutakseni, ja hänen ylösnousemisensa voimaa ja kärsimisensä osallisuutta, koska minä tulen hänen kuolemansa kaltaiseksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 11, 'Jolla muodolla minä kuolleitten ylösnousemisessa tuleva olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 12, 'Ei niin, että minä sen jo käsittänyt olen, eli jo täydellinen olen; mutta minä ahkeroitsen suuresti, että minä sen myös käsittäisin, niinkuin minäkin Jesuksessa Kristuksessa käsitetty olen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 13, 'Minun veljeni! enpä minä pidä itseni sitä käsittäneen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 14, 'Mutta yksi on se: minä unohdan ne, mitkä takaperin ovat, ja kokotan niiden perään, jotka edessä ovat, ja samoan eteenpannun määrän jälkeen, sen kalliin tavaran jälkeen, joka Jumalan kutsumisen kautta ylhäältä Kristuksessa Jesuksessa ilmoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 15, 'Niin monta siis, jotka meistä täydellistä on, ajatelkaamme niin, ja jos te toisin ajattelette, niin Jumala on sen teille ilmoittava.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 16, 'Kuitenkin että me yhden mitan jälkeen siinä vaellamme, johon me joutuneet olemme, ja että me yksimieliset olisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 17, 'Seuratkaat, rakkaat veljet, minua ja katsokaat niitä, jotka niin vaeltavat, kuin me teille esikuva olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 18, 'Sillä monta vaeltavat, joista minä jo usein olen teille sanonut, ja nytkin itkien sanon: he ovat Kristuksen ristin viholliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 19, 'Joidenka loppu on kadotus, ja heidän vatsansa on heidän jumalansa ja heidän kunniansa joutuu heille häpiäksi, jotka maallisia rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 20, 'Mutta meidän menomme on taivaissa, josta me myös lunastajaa Herraa Jesusta Kristusta odotamme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 21, 'Joka meidän heikon ruumiimme kirkastaa, että se hänen kirkkaan ruumiinsa kaltainen olis, sillä voimalla, jolla hän myös voi kaikki itsellensä alamaiseksi tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 1, 'Sentähden minun rakkaat ja ihanat veljeni, minun iloni ja minun kruununi, seisokaat niin Herrassa, minun rakkaani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 2, 'Euodiaa minä neuvon ja Syntykeä minä neuvon, että he Herrassa yksimieliset olisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 3, 'Ja minä rukoilen sinua, minun uskollinen kumppanini, ole niille avullinen, jotka minun kanssani evankeliumissa kilvoitelleet ovat, ynnä Klementin ja muiden minun auttajaini kanssa, joiden nimet elämän kirjassa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 4, 'Iloitkaat aina Herrassa, ja taas minä sanon: iloitkaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 5, 'Olkoon teidän siveytenne kaikille ihmisille tiettävä: Herra on läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 6, 'Älkäät mistään murehtiko, vaan olkoon teidän anomuksenne kaikissa asioissa Jumalalle tiettävä, kaikella rukouksella ja pyytämisellä kiitoksen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 7, 'Ja Jumalan rauha, joka ylitse kaiken ymmärryksen käy, varjelkoon teidän sydämenne ja teidän taitonne Kristuksessa Jesuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 8, 'Vielä, rakkaat veljet, mikä tosi, mikä kunniallinen, mikä oikein, mikä puhdas, mikä otollinen on, mikä hyvin kuuluu, jos joku hyvä tapa ja jos joku kiitos on, ajatelkaat niitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 9, 'Mitä te myös opitte, ja saitte, ja kuulitte, ja nähneet olette minussa, se tehkäät, niin rauhan Jumala on teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 10, 'Mutta minä olen suuresti iloinen Herrassa, että te olette taas virvonneet minusta murhetta pitämään, ehkä te sen tehneetkin olette, vaan ei teillä ollut tilaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 11, 'Enpä minä sitä sentähden sano, että minulta jotakin puuttuu; sillä minä olen oppinut, joissa minä olen, niihin tyytymään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 12, 'Minä taidan nöyrä olla ja taidan myös korkia olla, minä olen aina ja kaikissa harjoitettu, taidan ravittu olla ja isota, hyötyä ja köyhtyä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 13, 'Minä voin kaikki sen kautta, joka minun väkeväksi tekee, Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 14, 'Kuitenkin te teitte hyvin, että te minun murheeni päällenne otitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 15, 'Mutta te Philippiläiset tiedätte, ettei ensin evankeliumin alusta, kuin minä Makedoniasta läksin, yksikään seurakunta minulle mitään ollut jakanut antamisessa ja ottamisessa, vaan ainoastaan te;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 16, 'Sillä kuin myös minä Tessalonikassa olin, lähetitte te kerran ja kaksi minun tarpeeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 17, 'Ei niin, että minä lahjoja pyydän, vaan ahkeroitsen sitä, että teidän luvussanne ylitsevuotava hedelmä olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 18, 'Sillä minulla on kaikki ja yltäkyllä, minä olen täytetty, sitte kuin minä Epaphroditukselta sain sen, mikä teiltä lähetetty oli, makian hajun, otollisen ja Jumalalle kelvollisen uhrin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 19, 'Mutta minun Jumalani on teille antava, rikkaudestansa kaikki teidän tarpeenne, kunniassa, Jesuksen Kristuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 20, 'Mutta Jumalalle ja meidän Isällemme olkoon kunnia ijankaikkisesta ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 21, 'Tervehtikäät jokaista pyhää Kristuksessa Jesuksessa. Teitä tervehtivät ne veljet, jotka minun kanssani ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 22, 'Teitä tervehtivät kaikki pyhät, erinomattain ne, jotka keisarin huoneesta ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 23, 'Meidän Herran Jesuksen Kristuksen armo olkoon kaikkein teidän kanssanne, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, 'Paavali, Jesuksen Kristuksen apostoli Jumalan tahdon kautta, ja veli Timoteus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'Niille, jotka ovat Kolossissa, pyhille ja uskollisille veljille Kristuksessa: armo olkoon teille ja rauha Jumalalta meidän isältämme ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, 'Me kiitämme Jumalaa ja meidän Herran Jesuksen Kristuksen Isää, ja rukoilemme aina teidän edestänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'Sittekuin me kuulimme teidän uskonne Kristuksessa Jesuksessa ja teidän rakkautenne kaikkia pyhiä kohtaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'Sen toivon tähden, joka teille taivaissa tallelle pantu on, josta te ennen sen totisen evankeliumin saarnan kautta kuulleet olette,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'Joka teidän tykönne tullut on, niinkuin myös kaikkeen maailmaan, ja hedelmän kantaa, niinkuin teissäkin hamasta siitä päivästä, jona te sen kuulleet olette ja Jumalan armon totuudessa tunsitte;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'Niinkuin te myös meidän rakkaalta kanssa palvelialtamme Epaphraalta opitte, joka teidän edestänne Kristuksen uskollinen palvelia on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'Joka myös on meille ilmoittanut teidän rakkautenne hengessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'Sentähden myös me siitä päivästä, jona me sen kuulimme, emme lakanneet teidän edestänne rukoilemasta ja anomasta, että te hänen tahtonsa tuntemisella täytettäisiin kaikkinaisessa hengellisessä viisaudessa ja toimessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'Että te soveliaasti vaeltaisitte, kelvaten kaikissa Herralle, ja hedelmän tekisitte kaikissa hyvissä töissä ja kasvaisitte Jumalan tuntemisessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'Ja vahvistetuksi tulisitte kaikella voimalla, hänen kunniansa väkevyyden jälkeen, kaikkeen kärsivällisyyteen ja pitkämielisyyteen ilon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, 'Ja kiittäkäät Isää, joka meitä soveliaaksi tehnyt on pyhäin perimisen osallisuuteen valkeudessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'Joka meitä pimeyden vallasta pelasti ja on meidät siirtänyt rakkaan Poikansa valtakuntaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'Jonka kautta meillä on lunastus hänen verensä kautta, nimittäin syntein anteeksi antamus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, 'Joka näkymättömän Jumalan kuva on, esikoinen ennen kaikkia luontokappaleita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'Sillä hänen kauttansa ovat kaikki luodut, jotka taivaassa ja maan päällä ovat, näkyväiset ja näkymättömät, thronit ja herraudet, vallat ja hallitukset: ne ovat kaikki hänen kauttansa ja häneen luodut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'Ja hän on ennen kaikkia ja kaikki ovat hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'Ja hän on ruumiin, nimittäin seurakunnan pää, joka on alku ja esikoinen kuolleista, että hän kaikkein ylitse kävis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'Sillä niin kelpasi Isälle, että hänessä kokonainen täydellisyys asuis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'Ja kaikki olisivat hänen kauttansa hänen itse kanssansa sovitetut, sekä ne jotka maassa että ne jotka taivaissa ovat; sillä hän teki verensä kautta ristin päällä rauhan, itse kauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 21, 'Ja te olitte muinen oudot ja viholliset ymmärryksen puolesta, pahoissa töissä; mutta nyt hän on teidät sovittanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 22, 'Lihansa ruumiissa kuoleman kautta, että hän teidät saattais pyhäksi, laittamattomaksi ja nuhteettomaksi kasvoinsa edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 23, 'Jos te muutoin uskossa pysytte perustettuna ja vahvana ja horjumattomana evankeliumin toivosta, jonka te kuulitte, joka on saarnattu kaikkein luontokappalten edessä, jotka taivaan alla ovat; jonka palveliaksi minä Paavali tullut olen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 24, 'Joka nyt minun vaivoistani iloitsen, jotka minä kärsin teidän edestänne, ja täytän Kristuksen kärsimiset minun lihassani hänen ruumiinsa edestä, joka on seurakunta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 25, 'Jonka palveliaksi minä tullut olen Jumalan toimituksen jälkeen, joka minulle teidän kohtaanne annettu on, täyttämään Jumalan sanaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 26, 'Sitä salaisuutta, joka ijankaikkisesta ja sukukunnista on salattu ollut, mutta nyt hänen pyhillensä ilmoitettu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 27, 'Joille Jumala tahtoi sen julistaa, mikä tämän salaisuuden kunniallinen rikkaus pakanain seassa on, joka on Kristus teissä, kunnian toivo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 28, 'Jonka me ilmoitamme, ja kaikkia ihmisiä neuvomme, ja kaikkia ihmisiä kaikkinaisessa viisaudessa opetamme, että me jokaisen ihmisen Kristuksessa Jesuksessa täydelliseksi saattaisimme:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 29, 'Jota minä myös ahkeroitsen ja hänen vaikutuksensa jälkeen kilvoittelen, joka minussa väkevästi vaikuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, 'Sillä minä soisin teidän tietävän, kuinka suuri kilvoitus minulla on teistä ja niistä, jotka Laodikeassa ovat, ja kaikista niistä, jotka ei minun kasvojani lihassa nähneet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'Että heidän sydämensä saisivat lohdutuksen ja liitetyksi tulisivat rakkaudessa kaikkeen rikkauteen, täydellisessä ymmärryksessä Jumalan ja Isän ja Kristuksen salaisuuden tuntemiseen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'Jossa kaikki viisauden ja taidon tavarat kätketyt ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'Mutta sen minä sanon, ettei joku teitä viettelisi kavalalla puheella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'Sillä vaikka en minä lihassa läsnä ole, niin minä kuitenkin hengessä teidän tykönänne olen, iloitsen ja näen teidän toimellisuutenne ja teidän vahvan uskonne Kristuksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'Niinkuin te nyt Herran Jesuksen Kristuksen olette ottaneet vastaan, niin vaeltakaat hänessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'Ja olkaat hänessä juuritetut ja rakennetut ja uskossa vahvistetut, niinkuin te oppineet olette, ja olkaat siinä runsaasti kiitolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'Katsokaat, ettei joku teitä viettele philosophian ja turhain jaaritusten kautta, ihmisten opin ja maailmallisten säätyin jälkeen, ja ei Kristuksen jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'Sillä hänessä asuu koko jumaluuden täydellisyys ruumiillisesti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'Ja te olette hänessä täydelliset, joka kaiken herrauden ja esivallan pää on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'Jonka kautta te myös ympärileikatut olette sillä ympärileikkauksella, joka käsittä tapahtuu, syntisen ruumiin pois panemisen kautta, lihassa, Kristuksen ympärileikkauksella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, 'Ynnä hänen kanssansa kasteen kautta haudatut, jossa te myös hänen kanssansa olette nousseet ylös uskon kautta, jonka Jumala vaikuttaa, joka hänen kuolleista herättänyt on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, 'Ja on teidät hänen kanssansa eläväksi tehnyt, kuin te synnissä kuolleet olitte, ja teidän lihanne esinahassa, ja on meille kaikki synnit anteeksi antanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, 'Ja on pyyhkinyt pois sen käsikirjoituksen, joka säätyin kautta meitä vastaan oli ja oli meille vastahakoinen: sen hän otti pois ja naulitsi ristiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'Ja on ryöstänyt vallitukset ja väkevyydet, ja toi heidät näkyviin, ja sai heistä voittokunnian itse kauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 16, 'Älkään siis kenkään teitä tuomitko ruasta eli juomasta, taikka määrätyistä pyhäpäivistä, ei uudesta kuusta, eikä sabbateista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 17, 'Jotka ovat tulevaisten varjo, mutta itse ruumis on Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 18, 'Älkäät antako kenenkään voittaa teidän kilvoituksenne palkkaa, joka tahtoo teitä nöyryyteen ja enkelien palvelukseen, vaeltain niissä, joita ei hän nähnyt ole, ja on tyhmästi lihallisessa mielessänsä paisunut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 19, 'Ja ei riipu kiinni Päässä, josta koko ruumis jäsenistä ja ravioista saa väkevyyden ja kokoon liitetty on, ja niin siinä lisäämisessä kasvaa, jonka Jumala antaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 20, 'Jos te siis olette Kristuksen kanssa maailman säädyistä kuolleet, miksi te teitänne annatte säädyillä solmita, niinkuin te maailmassa eläisitte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 21, 'Älä siihen rupee, (sanovat ne,) älä maista, älä pitele,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 22, 'Jotka kaikki kulumisessa hukkuvat, ja ihmisten käskyt ja opit ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 23, 'Joilla kyllä viisauden muoto on itsevalitussa palveluksessa ja nöyryydessä, ja siinä, ettei he ruumistansa armahda eikä tee lihalle kunniaa hänen tarpeissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, 'Jos te siis Kristuksen kanssa olette nousseet ylös, niin etsikäät niitä, jotka ylhäällä ovat, kussa Kristus istuu Jumalan oikialla kädellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, 'Pyrkikäät niiden perään, jotka ylhäällä ovat, ja ei niiden, jotka maan päällä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'Sillä te olette kuolleet ja teidän elämänne on kätketty Kristuksen kanssa Jumalassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'Kuin Kristus, meidän elämämme, ilmoitetuksi tulee, silloin tekin hänen kanssansa kunniassa ilmoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'Niin kuolettakaat sentähden teidän jäsenenne, jotka maan päällä ovat, huoruus, saastaisuus, häpiällinen himo, rietas halaus ja ahneus, joka on epäjumalan palvelus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'Joidenka tähden Jumalan viha epäuskoisten lasten päälle tulee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'Joissa tekin muinen vaelsitte, kuin te niissä elitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Mutta nyt pankaat myös te pois nämät kaikki, viha, närkästys, pahuus, pilkka, ilkiät sanat, teidän suustanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'Älkäät valehdelko keskenänne, ja riisukaat pois teistänne vanha ihminen tekoinensa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'Ja pukekaat päällenne uusi, joka hänen tuntemiseensa uudistetaan, hänen kuvansa jälkeen, joka sen luonut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'Kussa ei ole Grekiläinen ja Juudalainen, ympärileikkaus ja esinahka, Barbarus ja Skyta, orja ja vapaa, vaan kaikki ja kaikissa Kristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, 'Niin pukekaat siis teitänne niinkuin Jumalan valitut, pyhät ja rakkaat, sydämellisellä laupiudella, ystävyydellä, nöyryydellä, hiljaisuudella ja pitkämielisyydellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'Ja kärsikäät toinen toistanne ja anteeksi antakaat toinen toisellenne, jos jollakin on kannetta toista vastaan; niinkuin myös Kristus teille on anteeksi antanut, niin myös tekin tehkäät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'Mutta ylitse näiden kaikkein pukekaat päällenne rakkaus, joka on täydellisyyden side.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'Ja Jumalan rauha hallitkoon teidän sydämissänne, johonka te myös kutsutut olette yhteen ruumiiseen, ja olkaat kiitolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'Asukaan Jumalan sana runsaasti teissä, kaikella viisaudella. Opettakaat ja neuvokaat teitänne keskenänne psalmeilla ja kiitosvirsillä ja hengellisillä lauluilla, veisaten armon kautta Herralle teidän sydämissänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 17, 'Ja kaikki, mitä te teette puheella eli työllä, niin tehkäät kaikki Herran Jesuksen nimeen, ja kiittäkäät Jumalaa ja Isää hänen kauttansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 18, 'Vaimot, olkaat teidän miehillenne alamaiset Herrassa, niinkuin kohtuullinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 19, 'Miehet, rakastakaat vaimojanne, ja älkäät olko tylyt heitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 20, 'Lapset, olkaat kuuliaiset vanhemmillenne kaikissa; sillä se on Herralle hyvin otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 21, 'Isät, älkäät kehoittako teidän lapsianne vihaan, ettei he araksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 22, 'Palveliat, olkaat kuuliaiset kaikissa teidän ruumiillisille isännillenne, ei silmäin edessä palvellen, niinkuin ne, jotka ihmisten mieltä noutavat, vaan sydämen yksinkertaisuudessa ja Jumalan pelvossa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 23, 'Ja kaikki, mitä te teette, se tehkäät sydämestänne, niinkuin Herralle ja ei ihmisille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 24, 'Ja tietäkäät, että te saatte Herralta perimisen palkan; sillä te palvelette Herraa Kristusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 25, 'Mutta joka väärin tekee, sen pitää saaman sen jälkeen kuin hän väärin tehnyt on, ja ei pidä muotoa katsottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 1, 'Isännät, se mikä oikeus ja kohtuus on, osoittakaat palvelioille, tietäen, että teilläkin on Herra taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 2, 'Olkaat alinomaisesti rukouksissa, valvoin niissä kiitoksen kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 3, 'Rukoillen ynnä meidänkin edestämme, että Jumala meille sanansa oven avais, Kristuksen salaisuutta puhumaan, jonka tähden minä myös sidottu olen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 4, 'Että minä sen julistaisin, niinkuin minun puhua tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 5, 'Vaeltakaat viisaasti niiden kanssa, jotka ulkona ovat, ja ottakaat ajasta vaari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 6, 'Teidän puheenne olkoon aina otollinen ja suolalla sekoitettu, että te tietäisitte, kuinka teidän pitää jokaista vastaaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 7, 'Kaikista minun menoistani pitää Tykikuksen, rakkaan veljen ja uskollisen palvelian ja kanssapalvelian Herrassa, teille tiettäväksi tekemän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 8, 'Jonka minä sitä varten lähetin teidän tykönne, että minä saisin tietää teidän tilanne, ja että hän teidän sydämenne lohduttais,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 9, 'Ynnä Onesimuksen, uskollisen ja rakkaan veljen kanssa, joka yksi teistä on: kuinka kaikki täällä ovat, he teillä tiettäväksi tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 10, 'Aristarkus, minun kanssavankini, tervehtii teitä, ja Markus, Barnabaan nepas, josta te käskyt saaneet olette: jos hän tulee teidän tykönne, niin ottakaat häntä vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 11, 'Ja Jesus, joka Justukseksi kutsutaan, jotka ympärileikkauksesta ovat: nämät ainoat ovat minun auttajani Jumalan valtakuntaan, jotka minulle lohdutukseksi olleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 12, 'Teitä tervehtii Epaphras, joka on teistä Kristuksen palvelia, ja rukoilee ahkerasti teidän edestänne, että te täydelliset olisitte, kaikella Jumalan tahdolla täytetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 13, 'Sillä minä todistan hänestä, että hän suuren kiivauden teistä pitää ja niistä, jotka Laodikeassa ja Hierapolissa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 14, 'Teitä tervehtii Luukas lääkäri, se rakas, ja Demas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 15, 'Tervehtikäät veljiä, jotka ovat Laodikeassa, ja Nymphaa, ja sitä seurakuntaa, joka hänen huoneessansa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 16, 'Ja kuin tämä lähetyskirja on teidän edessänne luettu, niin laittakaat, että se Laodikeankin seurakunnassa luettaisiin, ja että tekin sen lukisitte, joka Laodikeasta kirjoitettu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 17, 'Ja sanokaat Arkippukselle: pidä virastas vaaria, jonkas Herrassa saanut olet, ettäs sen toimittaisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 18, 'Tervehdys minun, Paavalin, kädelläni. Muistakaat minun siteitäni. Armo olkoon teidän kanssanne! Amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, 'Paavali ja Silvanus ja Timoteus Tessalonikan seurakunnalle, Isässä Jumalassa ja Herrassa Jesuksessa Kristuksessa: armo olkoon teille ja rauha Jumalalta meidän Isältämme, ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'Me kiitämme aina Jumalaa kaikkein teidän edestänne ja muistamme meidän rukouksissamme teitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, 'Ja lakkaamatta muistamme teidän tekojanne uskossa, ja teidän töitänne rakkaudessa, ja teidän kärsivällisyyttänne toivossa, joka on meidän Herramme Jesuksen Kristuksen päälle Jumalan ja meidän Isämme edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'Sillä, rakkaat veljet, Jumalalta rakastetut, me tiedämme, kuinka te valitut olette,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'Että meidän evankeliumi on teidän tykönänne ollut, ei ainoastansa puheessa, vaan myös voimassa ja Pyhässä Hengessä, ja vahvassa tiedossa; niinkuin te tiedätte, minkäkaltaiset me teidän tykönänne teidän tähtenne olimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'Ja te olette meitä ja Herra seuraamaan ruvenneet ja olette sanan monessa vaivassa, ilolla Pyhässä Hengessä, ottaneet vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'Niin että te olette tulleet esikuvaksi kaikille uskovaisille Makedoniassa ja Akajassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'Sillä teistä on Herran sana kajahtanut, ei ainoastaan Makedoniassa ja Akajassa, mutta myös joka paikassa on teidän uskonne Jumalan tykö kuulunut, niin ettei meidän tarvitse mitään puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, 'Sillä he itse ilmoittavat meistä, minkäkaltainen tulemus meillä on ollut teidän tykönne, ja kuinka te Jumalan tykö epäjumalista käännetyt olette, elävää ja totista Jumalaa palvelemaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'Ja hänen Poikaansa taivaista odottamaan, jonka hän on kuolleista herättänyt, Jesuksen, joka meitä tulevaisesta vihasta vapahtaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, 'Sillä te tiedätte, rakkaat veljet, meidän tulemisemme teidän tykönne, ettei se ole turha ollut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'Vaan niinkuin me ennen kärsineet ja häväistyt olimme Philipissä, niinkuin te tiedätte, kuitenkin olimme me rohkiat meidän Jumalassamme, puhumaan teille Jumalan evankeliumia suuressa kilvoittelemisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'Sillä ei meidän neuvomme ollut eksytyksessä, eikä saastaisuudessa, ei myös petoksessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'Vaan niinkuin me Jumalalta koetellut olemme, ja meille on evankeliumi uskottu, niin me myös puhumme; ei niin että me tahtoisimme ihmisille kelvata, vaan Jumalalle, joka meidän sydämemme koettelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'Sillä emmepä me koskaan vaeltaneet liukkailla sanoilla, niinkuin te tiedätte, emmekä ahneuden tilalla; Jumala on todistaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, 'Emme myös ole ihmisiltä kunniaa pyytäneet, ei teiltä eikä muilta, vaikka me olisimme taitaneet teitä rasittaa, niinkuin Kristuksen apostolit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'Mutta me olimme hienot teidän keskellänne: niinkuin imettäjä lapsiansa holhoo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, 'Niin oli myös meidän sydämemme halu teihin, jakamaan teille, ei ainoastaan Jumalan evankeliumia, mutta myös meidän henkeämme; sillä te olette meille rakkaiksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'Sillä te muistatte, rakkaat veljet, meidän työmme ja vaivamme; sillä yöllä ja päivällä me työtä teimme, ettemme ketään teistä rasittaisi, ja saarnasimme Jumalan evankeliumia teidän edessänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'Siihen te olette todistajat ja Jumala, kuinka pyhästi, hurskaasti ja nuhteettomasti me olimme teidän tykönänne, jotka uskotte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'Niinkuin te tiedätte, kuinka me jokaista teitä niinkuin isä lapsiansa olemme neuvoneet ja lohduttaneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'Ja todistaneet, että te otollisesti Jumalan edessä vaeltaisitte, joka teitä valtakuntaansa ja kunniaansa kutsunut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'Sentähden me myös lakkaamatta kiitämme Jumalaa, että kuin te saitte sen sanan Jumalasta, jonka te meiltä kuulitte, niin te sen otitte vastaan, ei niinkuin ihmisen sanan, vaan (niinkuin se totisesti on) kuin Jumalan sanan, joka myös teissä uskovaisissa vaikuttaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'Sillä te olette tulleet, rakkaat veljet, Jumalan seurakuntain, jotka ovat Juudeassa, tavoittajaksi, Kristuksessa Jesuksessa, että te olette myös niitä kärsineet teidän omilta langoiltanne, niinkuin hekin Juudalaisilta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'Jotka myös tappoivat Herran Jesuksen ja omat prophetansa, ja ovat meitä vainonneet, ja ei he Jumalalle kelpaa, ja ovat kaikille ihmisille vastahakoiset;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, 'Jotka meidän kieltävät pakanoille puhumasta, että he autuaiksi tulisivat, että he aina syntinsä täyttäisivät; sillä viha on jo peräti heidän päällensä tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'Mutta me, rakkaat veljet, sitte kuin me hetkeksi olemme teiltä otetut pois, näkyvistä, ei sydämestä, niin me olemme sitä enemmin suurella halulla pyytäneet teidän kasvojanne nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'Sentähden tahdoimme me tulla teidän tykönne, (minä Paavali,) kerran ja kaksi, mutta saatana esti meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'Sillä mikä on meidän toivomme taikka ilomme, eli meidän kerskauksemme kruunu? Ettekö myös te meidän Herran Jesuksen Kristuksen edessä hänen tulemisessansa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, 'Sillä te olette meidän kunniamme ja ilomme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, 'Sentähden emme saaneet sitä enempi viivyttää, vaan olemme mielistyneet jäämään Atenaan yksinänsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'Ja lähetimme Timoteuksen, meidän veljemme, Jumalan palvelian ja meidän apulaisemme Kristuksen evankeliumissa, vahvistamaan ja lohduttamaan teitä teidän uskossanne:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'Ettei kenkään näissä vaivoissa murehtisi; sillä te tiedätte, että me olemme sitä varten pannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'Ja tosin, kuin me olimme teidän tykönänne, niin me sen teille edellä sanoimme, että meidän piti vaivaa kärsimän, niinkuin te tapahtuneenkin tiedätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, 'Sentähden myös minä en taitanut enään malttaa itsiäni, mutta lähetin tietämään teidän uskoanne, ettei kiusaaja olisi teitä kiusannut, ja niin meidän työmme turhaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'Mutta nyt, kuin Timoteus tuli teiltä meidän tykömme ja ilmoitti meille teidän uskonne ja rakkautenne, että te aina meitä hyvässä muistossa pidätte ja halajatte meitä nähdä, niinkuin mekin teitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'Niin me saimme teistä, rakkaat veljet, lohdutuksen kaikessa meidän vaivassamme ja tuskassamme, teidän uskonne tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'Sillä nyt me elämme, jos te Herrassa pysytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Minkä kiitoksen siis me taidamme Jumalalle antaa teidän tähtenne, kaikesta tästä ilosta, jolla me iloitsemme teistä meidän Jumalamme edessä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'Yötä ja päivää rukoillen ahkerasti, että me teidän kasvonne näkisimme ja täyttäisimme, mitä teidän uskostanne puuttuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'Mutta itse Jumala ja meidän Isämme, ja meidän Herra Jesus Kristus saattakoon meidän tiemme teidän tykönne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, 'Mutta Herra lisätköön teitä ja antakoon rakkauden yltäkylläisen olla teidän seassanne ja jokaista kohtaan, niinkuin mekin teille olemme:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'Että hän teidän laittamattomat sydämenne vahvistais pyhyydessä, Jumalan ja meidän Isämme edessä meidän Herran Jesuksen Kristuksen tulemisessa, kaikkein hänen pyhäinsä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 1, 'Vielä siis, rakkaat veljet, rukoilemme me teitä ja neuvomme Herrassa Jesuksessa, niinkuin te meiltä saaneet olette, kuinka teidän vaeltaman ja Jumalalle kelpaaman pitää, että te täydellisemmäksi tulisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 2, 'Sillä te tiedätte ne käskyt, jotka me Herran Jesuksen kautta teille annoimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 3, 'Sillä se on Jumalan tahto, teidän pyhyytenne, että te huoruutta vältätte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 4, 'Että jokainen tietäis pitää astiansa pyhyydessä ja kunniassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 5, 'Ei himoin halauksissa niinkuin pakanat, jotka ei Jumalasta mitään tiedä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 6, 'Ja ettei yksikään sortaisi eikä pettäisi veljeänsä jossakussa asiassa; sillä Herra on kaikkein näiden kostaja, kuin me myös teille ennen sanoneet ja todistaneet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 7, 'Sillä ei Jumala ole meitä kutsunut saastaisuuteen, vaan pyhyyteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 8, 'Joka siis nämät katsoo ylön, ei hän katso ylön ihmistä, vaan Jumalan, joka myös Pyhän Henkensä meihin antanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 9, 'Mutta veljellisestä rakkaudesta ei minun tarvitse teille kirjoittaa; sillä te olette itse Jumalalta opetellut rakastamaan toinen toistanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 10, 'Ja sen te myös kaikille veljille teette, jotka koko Makedoniassa ovat; mutta me neuvomme teitä, rakkaat veljet, että te vielä täydellisemmäksi tulisitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 11, 'Ja pyytäkäät olla levolliset ja ottakaat vaari omista askareistanne, tehden työtä käsillänne, niinkuin me käskeneet olemme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 12, 'Että te itsenne kunniallisesti ulkonaisten kohtaan käyttäisitte, ettette mitään tarvitsisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 13, 'Mutta emme myös tahdo teiltä salata, rakkaat veljet, niistä, jotka nukkuneet ovat, ettette murehtisi niinkuin muut, joilla ei toivoa ole:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 14, 'Sillä jos me uskomme, että Jesus on kuollut ja noussut ylös, niin on Jumala myös ne, jotka nukkuneet ovat, Jesuksen kautta tuova edes hänen kanssansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 15, 'Sillä sen me sanomme teille Herran puolesta: että me, jotka elämme ja jälkeen jäämme Herran tulemiseen, emme suinkaan ennätä niitä, jotka nukkuneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 16, 'Sillä itse Herra astuu alas taivaasta, suurella huudolla, ja ylimmäisen enkelin äänellä ja Jumalan basunalla, ja kuolleet Kristuksessa ensin nousevat ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 17, 'Sitte me, jotka elämme ja jälkeen jäämme, temmataan ynnä heidän kanssansa pilvihin, Herraa vastaan tuulihin, ja niin me aina Herran kanssa olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 18, 'Lohduttakaat siis teitänne keskenänne näillä sanoilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 1, 'Mutta ajoista ja hetkistä, rakkaat veljet, ei teille tarvitse kirjoittaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 2, 'Sillä te itse visusti tiedätte, että Herran päivä on tuleva niinkuin varas yöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 3, 'Sillä kuin he sanovat: nyt on rauha ja ei mitään hätää, silloin kadotus lankee äkisti heidän päällensä, niinkuin raskaan vaimon kipu, ja ei he suinkaan saa paeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 4, 'Mutta te, rakkaat veljet, ettepä te ole pimeydessä, ettei se päivä teitä käsittäisi niinkuin varas.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 5, 'Te olette kaikki valkeuden lapset ja päivän lapset: emme ole yön emmekä pimeyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 6, 'Niin älkäämme siis maatko niinkuin muut, vaan valvokaamme ja olkaamme raittiit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 7, 'Sillä jotka makaavat, ne yöllä makaavat, ja ne, jotka juopuvat, ne yöllä juovuksissa ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 8, 'Mutta me, jotka päivän lapset olemme, olkaamme raittiit, puetut uskon ja rakkauden rintaraudalla ja autuuden toivon rautalakilla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 9, 'Sillä ei Jumala ole meitä pannut vihaan, vaan autuutta omistamaan, meidän Herran Jesuksen Kristuksen kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 10, 'Joka meidän edestämme kuollut on: että jos me valvomme eli makaamme, me ynnä hänen kanssaan eläisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 11, 'Sentähden neuvokaat teitänne keskenänne ja rakentakaat toinen toistanne, niinkuin te myös teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 12, 'Mutta me rukoilemme teitä, rakkaat veljet, että te ne tuntisitte, jotka teidän seassanne työtä tekevät, ja teidän esimiehenne ovat Herrassa, ja teitä neuvovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 13, 'Pitäkäät heitä sitä rakkaampana heidän tekonsa tähden. Olkaat rauhalliset keskenänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 14, 'Mutta me neuvomme teitä, rakkaat veljet: neuvokaat tavattomia, lohduttakaat heikkomielisiä, holhokaat heikkoja, olkaat kärsiväiset jokaisen kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 15, 'Katsokaat, ettei joku pahaa pahalla kosta, vaan noudattakaat hyvää, sekä keskenänne, että jokaista kohtaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 16, 'Olkaat aina iloiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 17, 'Rukoilkaat lakkaamatta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 18, 'Kiittäkäät kaikkein edestä; sillä se on Jumalan tahto teistä Kristuksessa Jesuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 19, 'Älkäät henkeä sammuttako.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 20, 'Älkäät prophetiaa katsoko ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 21, 'Koetelkaat kaikki, ja pitäkäät se mikä hyvä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 22, 'Välttäkäät kaikkea, mikä pahaksi näkyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 23, 'Mutta itse rauhan Jumala pyhittäköön teitä kokonansa, että koko teidän henkenne ja sielunne ja ruumiinne meidän Herran Jesuksen Kristuksen tulemisessa nuhteetoinna pidettäisiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 24, 'Hän on uskollinen, joka teitä kutsunut on ja sen myös täyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 25, 'Rakkaat veljet, rukoilkaat meidän edestämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 26, 'Tervehtikäät kaikkia veljiä pyhällä suunannolla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 27, 'Minä vannotan teitä Herran kautta, että te tämän lähetyskirjan kaikkein pyhäin veljein edessä lukea annatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 28, 'Meidän Herran Jesuksen Kristuksen armo olkoon teidän kanssanne, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, 'Paavali ja Silvanus ja Timoteus Tessalonikan seurakunnalle Jumalassa, meidän Isässämme, ja Herrassa Jesuksessa Kristuksessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, 'Armo olkoon teille ja rauha Jumalalta, meidän Isältämme ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'Meidän pitää aina teidän edestänne, rakkaat veljet, Jumalaa kiittämän, niinkuin kohtuullinen on: sillä teidän uskonne kasvaa jalosti ja kaikkein teidän rakkautenne lisääntyy jokaista kohtaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'Niin että me teistä Jumalan seurakunnissa kerskaamme, teidän kärsivällisyydestänne ja uskostanne kaikessa teidän vainossanne ja vaivassanne, jota te kärsitte:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'Jotka osoittavat, että Jumala on oikein tuomitseva, ja te Jumalan valtakuntaan soveliaaksi tulette, jonka tähden te myös kärsitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'Että se on oikein Jumalan edessä niitä taas vaivata, jotka teitä vaivaavat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'Mutta teille, jotka vaivataan, antaa levon meidän kanssamme, kuin Herra Jesus taivaasta ilmaantuu, voimansa enkelien kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, 'Ja tulen leimauksella, joka niille kostaa, jotka ei Jumalaa tunteneet, ja niille, jotka ei meidän Herran Jesuksen Kristuksen evankeliumia tottele,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'Jotka vaivaa kärsimän pitää, ijankaikkisen kadotuksen, Herran kasvoista ja hänen kunniansa väkevyydestä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'Kuin hän tuleva on, kirkastettaa pyhäinsä kanssa, ja ihmeelliseksi tulemaan kaikkein uskovaisten kanssa; sillä meidän todistuksemme teidän tykönne siitä päivästä olette te uskoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 11, 'Ja sentähden me myös aina rukoilemme teidän edestänne, että meidän Jumalamme teitä otolliseksi tekis siihen kutsumiseen, ja täyttäis kaiken hyvyyden suosion ja uskon vaikutuksen, voimassa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 12, 'Että meidän Herran Jesuksen Kristuksen nimi teissä ylistettäisiin, ja te taas hänessä, meidän Jumalan ja Herran Jesuksen Kristuksen armon kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 1, 'Mutta me rukoilemme teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen tulemisen ja meidän kokoontumisemme kautta hänen tykönsä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 2, 'Ettette aivan nopiasti teitänne salli teidän mielestänne kääntää pois eli peljätettää, ei hengen, eikä puheen, eikä kirjan kautta, niin kuin se meiltä lähetetty olis, niinkuin Kristuksen päivä jo käsissä olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 3, 'Älkäät antako kenenkään teitänne vietellä millään tavalla; sillä ei hän ennen tule kuin luopumus tapahtuu ja synnin ihminen ilmoitetaan, kadotuksen lapsi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 4, 'Joka on vastaanseisoja, ja korottaa itsensä kaikkein päälle, mikä jumalaksi taikka jumalanpalveluksi kutsutaan, niin että hän istuttaa itsensä Jumalan templiin niinkuin Jumala, ja tekee itsensä jumalaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 5, 'Ettekö te muista, että minä teidän tykönänne ollessani näitä jo teille sanoin?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 6, 'Ja mikä nyt estää, te tiedätte, että hän pitää ajallansa ilmoitettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 7, 'Sillä hän nyt pahuutta vaikuttaa salaisesti, ainoastaan että se, mikä nyt estää, tulee pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 8, 'Ja silloin se pahanilkinen ilmoitetaan, jonka Herra suunsa hengellä tappaa, ja tekee hänen kanssansa lopun, tulemisensa ilmoituksen kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 9, 'Jonka tulemus saatanan vaikutuksen jälkeen tapahtuu, kaikella voimalla ja merkeillä ja petollisilla ihmeillä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 10, 'Ja kaikella vääryyden petoksella niiden seassa, jotka kadotukseen tulevat, ettei he rakkautta totuuden puoleen ottaneet, autuaaksi tullaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 11, 'Sentähden on Jumala heille lähettävä väkevän eksytyksen, niin että he valheen uskovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 12, 'Että ne kaikki tuomittaisiin, jotka ei totuutta uskoneet, vaan vääryyteen suostuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 13, 'Mutta meidän pitää aina teidän edestänne Jumalaa kiittämän, rakkaat veljet Herrassa, että Jumala on teidät alusta autuuteen valinnut, Hengen pyhityksen kautta ja totuuden uskossa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 14, 'Johonka hän teitä meidän evankeliumin kautta kutsunut on, meidän Herran Jesuksen Kristuksen kunnian omaisuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 15, 'Niin olkaat siis, rakkaat veljet, pysyväiset ja pitäkäät ne säädyt, jotka te oppineet olette, olkoon se meidän saarnastamme taikka kirjastamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 16, 'Mutta itse meidän Herra Jesus Kristus, ja Jumala ja meidän Isämme, joka meitä rakasti ja antoi meille ijankaikkisen lohdutuksen ja hyvän toivon armon kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 17, 'Lohduttakoon teidän sydämenne, ja teitä kaikkinaisessa opissa ja hyvässä työssä vahvistakoon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 1, 'Vielä, rakkaat veljet, rukoilkaat meidän edestämme, että Herran sana menestyis ja niin kunnioitettaisiin kuin teidänkin tykönänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 2, 'Ja että me häijyistä ja pahoista ihmisistä pelastettaisiin; sillä ei usko ole joka miehen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 3, 'Mutta Herra on uskollinen, joka teitä vahvistaa ja pahasta varjelee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 4, 'Mutta me toivomme Herrassa teistä, että te teette ja tekeväiset olette, mitä me teille olemme käskeneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 5, 'Mutta Herra ojentakoon teidän sydämenne Jumalan rakkauteen ja Kristuksen kärsivällisyyteen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 6, 'Mutta me käskemme teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen nimeen, että te teitänne eroittaisitte jokaisesta veljestä, joka häijysti itsensä käyttää ja ei sen säädyn jälkeen, jonka hän meiltä saanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 7, 'Sillä te itse tiedätte, kuinka teidän meitä seuraaman pitää: emmepä me ole tavattomasti teidän seassanne olleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 8, 'Emme myös ole leipää keltään ilman ottaneet, vaan työllä ja hiellä: yöllä ja päivällä olemme me työtä tehneet, ettemme kellenkään teidän seassanne kuormaksi olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 9, 'Ei, ettei meillä se valta olisi, vaan että me itsemme opiksi teille antaisimme, seurataksenne meitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 10, 'Ja kuin me teidän tykönänne olimme, niin me senkaltaisia teille käskimme, että jos ei joku tahdo työtä tehdä, niin ei hänen syömänkään pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 11, 'Sillä me kuulemme, että muutamat teidän seassanne tavattomasti vaeltavat, ja ei tee työtä, vaan joutilaina ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 12, 'Mutta senkaltaisia me käskemme ja neuvomme meidän Herran Jesuksen Kristuksen kautta, että he hiljaisuudessa työtä tekisivät ja omaa leipäänsä söisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 13, 'Mutta te, rakkaat veljet, älkäät väsykö hyvää tekemästä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 14, 'Ellei siis joku tottele meidän sanaamme lähetyskirjan kautta, niin merkitkäät se ja älkäät kanssakäymistä pitäkö hänen kanssansa, että hän häpeäis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 15, 'Ja älkäät häntä pitäkö niinkuin vihollisena, vaan neuvokaat niinkuin veljeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 16, 'Mutta itse rauhan Herra antakoon teille rauhan aina kaikella tavalla! Herra olkoon teidän kanssanne!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 17, 'Tervehdys minun Paavalin kädelläni, joka on merkki kaikissa lähetyskirjoissa: näin minä kirjoitan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 18, 'Meidän Herran Jesuksen Kristuksen armo olkoon kaikkein teidän kanssanne, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, 'Paavali, Jesuksen Kristuksen apostoli Jumalan meidän Lunastajamme asetuksen jälkeen, ja Herran Jesuksen Kristuksen, joka meidän toivomme on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'Timoteukselle, minun vakaalle pojalleni uskossa, armo, laupius ja rauha Jumalalta, meidän Isältämme, ja meidän Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, 'Niinkuin minä Makedoniaan lähteissäni käskin sinun olla Ephesossa, niin neuvo muutamia, ettei he toisin opettaisi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'Eikä juttuja tottelisi ja polvilukuja, joilla ei loppua ole, jotka enemmin tutkimiset matkaan saattavat kuin parannuksen Jumalan tykö, joka on uskossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'Mutta käskyn päätös on rakkaus puhtaasta sydämestä, ja hyvästä omastatunnosta, ja vilpittömästä uskosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'Joista muutamat ovat hairahtuneet ja ovat turhiin jaarituksiin kääntyneet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'Ja tahtovat lainopettajat olla, ja ei ymmärrä, mitä he puhuvat eli päättävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'Mutta me tiedämme lain hyväksi, jos se oikein käytetään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'Tietäen sen, ettei vanhurskaalle ole laki pantu, vaan väärille ja tottelemattomille, jumalattomille ja syntisille, pakanallisille ja kelvottomille, isänsä tappajille ja äitinsä tappajille, miehentappajille,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'Huorintekiöille, miesten kanssa makaajille, ihmisten varkaille, valehtelijoille, valapattoisille, ja mitä muuta senkaltaista sitä terveellistä oppia on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'Autuaan Jumalan kunniallisen evankeliumin jälkeen, joka minulle uskottu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'Ja minä kiitän meidän Herraamme Kristusta Jesusta, joka minun voimalliseksi tehnyt on, ja luki minun uskolliseksi, asettain tähän virkaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 13, 'Joka ennen pilkkaaja ja vainooja ja häpäisiä olin, mutta minulle on laupius tapahtunut; sillä minä tein sitä tietämättä epäuskossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 14, 'Mutta meidän Herramme armo oli sitä runsaampi, uskon ja rakkauden kanssa, joka Kristuksessa Jesuksessa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 15, 'Se on totinen sana ja kaiketi mahdollinen ottaa vastaan, että Kristus Jesus on tullut maailmaan syntisiä vapahtamaan, joista minä suurin olen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 16, 'Mutta sentähden on minulle laupius tapahtunut, että Jesus Kristus minussa ensin osoittais kaiken pitkämielisyyden niille esikuvaksi jotka hänen päällensä pitää uskoman ijankaikkiseen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 17, 'Mutta Jumalalle, ijankaikkiselle kuninkaalle, kuolemattomalle ja näkymättömälle, ja ainoalle viisaalle olkoon kunnia ja ylistys ijankaikkisesta ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 18, 'Tämän käskyn minä annan sinulle, minun poikani Timoteus, entisten ennustusten jälkeen sinusta, ettäs niissä sotisit niinkuin jalo sotamies,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 19, 'Ja pitäisit uskon ja hyvän omantunnon, jonka muutamat ovat hyljänneet ja ovat uskon puolesta haaksirikkoon tulleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 20, 'Joista on Hymeneus ja Aleksander, jotka minä olen saatanan haltuun antanut, että he tulisivat kuritetuksi enempi pilkkaamasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 1, 'Niin minä siis neuvon, että ennen kaikkia pidettäisiin rukoukset, anomiset, toivotukset ja kiitokset kaikkein ihmisten edestä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 2, 'Kuningasten ja kaiken esivallan edestä, että me rauhassa ja levossa eläisimme, kaikessa jumalisuudessa ja kunniallisuudessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 3, 'Sillä se on hyvä ja otollinen Jumalan meidän Vapahtajamme edessä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 4, 'Joka tahtoo kaikkia ihmisiä autuaaksi, ja että he totuuden tuntoon tulisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 5, 'Sillä yksi on Jumala, ja yksi välimies Jumalan ja ihmisten välillä, ihminen Kristus Jesus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 6, 'Joka itsensä kaikkein edestä lunastuksen hinnaksi on antanut, että senkaltaista piti ajallansa saarnattaman:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 7, 'Johonka minä myös olen saarnaajaksi ja apostoliksi asetettu (minä sanon toden Kristuksessa ja en valehtele,) pakanain opettajaksi uskossa ja totuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 8, 'Niin minä tahdon siis, että miehet rukoilisivat joka paikassa ja nostaisivat ylös pyhät kädet, ilman vihaa ja epäilystä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 9, 'Niin myös että vaimot kohtuullisissa vaatteissa olisivat ja kaunistaisivat itsensä hävyllä ja kainoudella, ei kahara-hiuksilla, eli kullalla, eli päärlyillä, eli kalliilla vaatteilla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 10, 'Vaan niinkuin niille vaimoille sopii, jotka jumalisuuden hyväin töiden kautta osoittavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 11, 'Oppikaan vaimo hiljaisuudessa, kaikella nöyryydellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 12, 'Mutta en minä salli vaimon opettaa enkä miestänsä vallita, vaan että hän on hiljaisuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 13, 'Sillä Adam on ensin luotu ja sitte Eva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 14, 'Ja ei Adam petetty; mutta vaimo petettiin ja saatti ylitsekäymisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 15, 'Mutta kuitenkin hän lasten synnyttämisen kautta autuaaksi tulee, jos hän pysyy uskossa ja rakkaudessa ja pyhyydessä siveyden kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 1, 'Se on totinen sana: jos joku piispan virkaa pyytää, hän hyvää työtä halajaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 2, 'Niin pitää siis piispan oleman nuhteettoman, yhden emännän miehen, valppaan, raittiin, siviän, vierasten holhojan, opettavaisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 3, 'Ei juomarin, ei tappelian, ei ilkiän voiton pyytäjän, vaan armeliaan, ei riitaisen eikä ahneen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 4, 'Joka oman huoneensa hyvin hallitsee, jolla kuuliaiset lapset ovat, kaikella kunniallisuudella:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 5, '(Mutta jos joku ei taida omaa huonettansa hallita, kuinkas hän Jumalan seurakunnan taitaa hallita?)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 6, 'Ei äsken kristityn, ettei hän paisuneena laittajan tuomioon lankeaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 7, 'Mutta hänellä pitää myös hyvä todistus oleman niiltä, jotka ulkona ovat, ettei hän laittajan pilkkaan ja paulaan lankeaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 8, 'Niin pitää myös seurakunnan palveliat toimelliset oleman, ei kaksikieliset, ei juomarit, ei häpiällisen voiton pyytäjät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 9, 'Jotka uskon salaisuuden puhtaassa omassatunnossa pitävät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 10, 'Jotka pitää ensin koeteltaman, ja palvelkaan sitte kuin he nuhteettomiksi löydetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 11, 'Heidän emäntänsä pitää myös siviät oleman, ei laittajat, vaan raittiit, kaikissa uskolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 12, 'Seurakunnan palveliat olkoon yhden emännän miehet, jotka lapsensa ja oman huoneensa hyvin hallitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 13, 'Sillä jotka hyvin palvelevat, he hyvän menestyksen ansaitsevat ja suuren vapauden uskossa, joka on Kristuksessa Jesuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 14, 'Näitä minä kirjoitan sinulle, ja toivon pian tulevani sinun tykös;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 15, 'Mutta jos minä viivyn, ettäs tietäisit kuinka sinun pitää Jumalan huoneessa vaeltaman, joka on elävän Jumalan seurakunta, totuuden patsas ja perustus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 16, 'Ja se on julkisesti suuri jumalisuuden salaisuus, että Jumala on ilmoitettu lihassa, vanhurskautettu hengessä, nähty enkeleiltä, saarnattu pakanoille, uskottu maailmassa ja otettu ylös kunniaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 1, 'Mutta Henki sanoo selkiästi, että viimeisillä ajoilla muutamat luopuvat uskosta ja ottavat vaarin viettelevistä hengistä ja perkeleiden opetuksista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 2, 'Niiden kautta, jotka ulkokullaisuudessa valheenpuhujat ovat, joiden omatunto on poltinraudalla merkitty,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 3, 'Ja kieltävät naimasta ja ottamasta ruokaa, jonka Jumala loi uskollisille kiitoksella nautittavaksi ja niille, jotka totuuden ymmärtäneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 4, 'Sillä kaikki, mitä Jumala luonut on, on hyvää, ja ei ole mitään hyljättävää, kuin se kiitoksella nautitaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 5, 'Sillä se Jumalan sanalla ja rukouksella pyhitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 6, 'Kuin nyt senkaltaista veljille opetat, niin sinä Jesuksen Kristuksen uskollinen palvelia olet, uskon sanoissa, hyvässä opissa kasvatettu, jotka sinä seurannut olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 7, 'Mutta vältä kelvottomia ämmän juttuja, ja harjoita sinuas jumalisuuteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 8, 'Sillä ruumiillinen harjoitus vähän kelpaa; mutta jumalisuus on tarpeellinen kaikissa asioissa, jolla on sekä nykyisen että tulevaisen elämän lupaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 9, 'Tämä on totinen sana, ja kaiketi mahdollinen ottaa vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 10, 'Sillä sitä vasten me työtäkin teemme ja meitä pilkataan, että me elävän Jumalan päälle toivoneet olemme, joka kaikkein ihmisten vapahtaja on, erinomattain uskovaisten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 11, 'Näitä sinä neuvo ja opeta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 12, 'Älköön kenkään sinun nuoruuttas katsoko ylön, vaan ole sinä uskovaisille esikuva sanassa, kanssakäymisessä, rakkaudessa, hengessä, uskossa, puhtaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 13, 'Ota lukemisesta, neuvosta ja opista vaari, siihenasti kuin minä tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 14, 'Älä unohda sitä lahjaa, joka sinulle prophetian kautta annettu on, vanhimpain kätten päällepanemisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 15, 'Ota näistä vaari, pysy näissä, että sinun menestykses kaikille julistetuksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 16, 'Ota itsestäs vaari ja opista, pysy alati näissä; sillä jos sinä sen teet, niin sinä itses autuaaksi saatat ja ne, jotka sinua kuulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 1, 'Älä vanhaa kovin nuhtele, vaan neuvo häntä niinkuin isää, nuoria niinkuin veljiä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 2, 'Vanhoja vaimoja niinkuin äitejä, nuoria niinkuin sisaria, kaikella puhtaudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 3, 'Kunnioita niitä leskiä, jotka oikiat lesket ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 4, 'Mutta jos jollakulla leskellä lapsia on eli lasten lapsia, ne oppikaan ensin oman huoneensa jumalisesti hallitsemaan ja vanhempainsa hyvän työn maksamaan; sillä se on hyvin tehty ja Jumalalle otollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 5, 'Ja se on oikia leski, joka yksinänsä on ja asettaa toivonsa Jumalan päälle, pysyin aina rukouksissa ja avuksihuutamisessa yötä ja päivää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 6, 'Mutta joka hekumassa elää, se on elävältä kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 7, 'Senkaltaisia neuvo, että he nuhteettomat olisivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 8, 'Mutta jos ei joku omistansa, liiatenkin perheestänsä, murhetta pidä, se on uskon kieltänyt ja on pakanaa pahempi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 9, 'Älä salli nuorempaa leskeä otettaa kuin kuudenkymmenen ajastaikaista, joka yhden miehen emäntä on ollut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 10, 'Ja jolla on hyvistä töistä todistus, jos hän lapsia kasvattanut on, jos hän vierasten holhooja ollut on, jos hän pyhäin jalkoja pessyt on, jos hän murheellisia auttanut on, jos hän on kaikessa hyvässä työssä ahkera ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 11, 'Mutta nuoret lesket hylkää; sillä koska he suuttuvat Kristukseen, niin he tahtovat huolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 12, 'Joilla on heidän tuomionsa, että he sen ensimäisen uskon rikkoneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 13, 'Niin myös joutilaina ollessansa oppivat he huoneita ympärinsä juoksentelemaan; vaan ei he ainoastaan ole joutilaat, mutta myös kielevät, hempeät ja puhuvat luvattomia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 14, 'Sentähden minä tahdon, että nuoret lesket huolisivat, lapsia kasvattaisivat, huoneen hallituksesta vaaria pitäisivät, eikä antaisi tilaa vastaanseisojille pahoin puhua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 15, 'Sillä muutamat ovat jo saatanan jälkeen palanneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 16, 'Jos nyt jollakin uskollisella miehellä eli vaimolla leskiä on, se heitä holhokoon ja älkään seurakuntaa rasittako, että oikeille leskille täytyis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 17, 'Vanhimmat, jotka hyvin hallitsevat, pitää kaksinkertaisessa kunniassa pidettämän, erinomattain ne, jotka sanassa ja opissa työtä tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 18, 'Sillä Raamattu sanoo: ei sinun pidä riihtä tappavan härjän suuta sitoman kiinni, ja työmies on palkkansa ansainnut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 19, 'Älä salli vanhinta vastaan yhtään kannetta, vaan kahden eli kolmen todistuksen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 20, 'Nuhtele niitä, jotka syntiä tekevät, kaikkein kuullen, että muutkin pelkäisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 21, 'Minä rukoilen Jumalan ja Herran Jesuksen Kristuksen ja valittuin enkelien edessä, ettäs nämät pidät ilman valitsemista, ja älä mitään tee toisen puolta pitäin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 22, 'Älä pikaisesti jonkun päälle käsiäs pane, ja älä ole muiden synneistä osallinen: pidä itses puhtaana.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 23, 'Älä silleen vettä juo, vaan nautitse jotakin viinaa sydämes tähden ja ettäs myös usein sairastat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 24, 'Muutamain ihmisten synnit ovat kyllä julkiset, että ne ennen tuomita taidetaan; mutta muutamain äsken jälistä julkiseksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 25, 'Niin myös muutamat hyvät työt ovat jo ennen julkiset, ja ne mitkä muutoin tapahtuvat, ei taideta salattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 1, 'Palveliat, jotka ikeen alla ovat, pitää isäntänsä kaikessa kunniassa pitämän, ettei Jumalan nimi ja oppi pilkatuksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 2, 'Mutta joilla uskolliset isännät ovat, niin älköön niitä katsoko ylön, että he veljekset ovat; vaan olkoon sitä kuuliaisemmat, että he uskolliset ovat ja rakkaat, jotka hyvästä työstä osalliset ovat. Näitä opeta ja neuvo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 3, 'Jos joku toisin opettaa, ja ei pysy meidän Herran Jesuksen Kristuksen terveellisissä sanoissa ja siinä opissa, joka jumalisuudesta on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 4, 'Hän on paisunut ja ei taida mitään, vaan on sairas kysymyksissä ja sanain kilvoituksissa, joista kateus, riita, häväistys ja pahat luulot tulevat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 5, 'Häijyt kamppaukset niiden ihmisten seassa, jotka mielessänsä riivatut ovat, ja joilta totuus otettu pois on, jotka jumalisuuden voitoksi luulevat. Eroita sinus senkaltaisista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 6, 'Mutta se on suuri voitto, olla jumalinen ja tyytyä onneensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 7, 'Sillä emmepä me ole mitään maailmaan tuoneet, on siis tiettävä, ettemme myös mitään täältä taida viedä ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 8, 'Mutta koska meillä on elatus ja vaatteet, niin tyytykäämme niihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 9, 'Mutta ne, jotka rikastua tahtovat, lankeevat kiusaukseen ja paulaan ja moniin tyhmiin ja vahingollisiin himoihin, jotka ihmiset vahinkoon ja kadotukseen upottavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 10, 'Sillä ahneus on kaiken pahuuden juuri, jota muutamat ovat himoinneet, ja ovat uskosta eksyneet ja itsellensä paljon murhetta saattaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 11, 'Mutta sinä, Jumalan ihminen, karta niitä ja noudata vanhurskautta, jumalisuutta, uskoa, rakkautta, kärsivällisyyttä ja hiljaisuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 12, 'Kilvoittele hyvä uskon kilvoitus, käsitä ijankaikkinen elämä, johonka sinä kutsuttu olet, ja olet tunnustanut hyvän tunnustuksen monen todistajan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 13, 'Minä käsken sinua Jumalan edessä, joka kaikki eläväksi tekee, ja Jesuksen Kristuksen edessä, joka Pontius Pilatuksen alla hyvän todistuksen tunnusti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 14, 'Ettäs käskyn saastatoinna ja nuhteetoinna pidät, hamaan meidän Herran Jesuksen Kristuksen ilmoitukseen asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 15, 'Jonka meille aikanansa osoittaa se autuas ja ainoa valtias, kuningasten Kuningas ja kaikkein herrain Herra,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 16, 'Jolla ainoalla on kuolemattomuus, joka asuu kirkkaudessa, johon ei yksikään tulla taida, jota ei yksikään ihminen nähnyt ole eikä taida nähdä: jolle olkoon kunnia ja ijankaikkinen voima, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 17, 'Käske niitä, jotka rikkaat tässä maailmassa ovat, ettei he ylpeilisi eikä panisi toivoansa katoovaisen rikkauden, vaan elävän Jumalan päälle, joka meille antaa nautitaksemme runsaasti kaikkinaista:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 18, 'Että he tekisivät hyvää ja hyvissä töissä rikastuisivat, antaisivat hyvällä mielellä, olisivat avulliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 19, 'Ja tallelle panisivat itsellensä hyvän perustuksen edespäin, käsittääksensä ijankaikkista elämää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 20, 'Oi Timoteus! kätke se, mikä sinulle uskottu on, ja vältä turhia ja kelvottomia juttuja ja niitä riitoja, jotka väärin kerskatusta taidosta tulevat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 21, 'Josta muutamat paljon pitävät, ja uskosta eksyneet ovat. Armo olkoon sinun kanssas, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, 'Paavali, Jesuksen Kristuksen apostoli Jumalan tahdon kautta elämän lupauksen jälkeen, joka on Kristuksessa Jesuksessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'Minun rakkaalle pojalleni Timoteukselle armo, laupius ja rauha Isältä Jumalalta ja Jesukselta Kristukselta meidän Herraltamme!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, 'Minä kiitän Jumalaa, jota minä hamasta minun esivanhemmistani palvelen puhtaalla omallatunnolla, että minä lakkaamatta sinua yöllä ja päivällä minun rukouksissani muistan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'Ja haluan sinua nähdä, koska minä sinun kyynelees muistan, että minä ilolla täytettäisiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'Kuin minun mieleeni tulee se vilpitön usko, joka sinussa on, joka ennen sinun isossa äidissäs Loidassa myös asui ja sinun äidissäs Eunikassa ja, kuin minä totisesti tiedän, sinussakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'Jonka tähden minä sinua neuvon, ettäs herätät sen Jumalan lahjan, joka sinussa on, minun kätteni päällepanemisen kautta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'Sillä ei Jumala ole meille antanut pelvon henkeä, vaan väkevyyden, rakkauden ja raittiuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, 'Sentähden älä häpeä meidän Herran Jesuksen Kristuksen todistusta eikä minua, joka hänen vankinsa olen; vaan ole osallinen evankeliumin vaivassa, Jumalan voiman jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'Joka meitä on autuaaksi tehnyt ja pyhällä kutsumisella kutsunut, ei meidän töidemme perästä, vaan aivoituksensa ja armonsa jälkeen, joka meille Kristuksessa Jesuksessa ennen ijankaikkisia aikoja annettu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'Mutta nyt meidän Vapahtajamme Jesuksen Kristuksen ilmestyksen kautta julistettu, joka kuoleman otti pois ja elämän ja kuolemattomuuden toi evankeliumin kautta valkeuteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'Johonka minä olen pantu saarnaajaksi ja apostoliksi ja pakanain opettajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, 'Jonka tähden minä myös näitä kärsin, ja en kuitenkaan häpee; sillä minä tiedän, kenen päälle minä uskon, ja olen luja, että hän voi minulle kätkeä minun uskotun kaluni siihen päivään asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'Pysy siis niiden terveellisten sanain muodossa, jotka sinä minulta kuullut olet, uskossa ja rakkaudessa, joka on Kristuksessa Jesuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'Tämä hyvä uskottu kalu kätke Pyhän Hengen kautta, joka meissä asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 15, 'Sinä tiedät sen, että kaikki, jotka Asiassa ovat, luopuivat minusta, joista on Phygellus ja Hermogenes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 16, 'Herra antakoon laupiutensa Onesiphorin perheelle, joka minun usein virvoittanut on ja ei minun kahleitani hävennyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 17, 'Vaan etsi minua visusti Roomissa ollessansa, ja löysi minun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 18, 'Herra antakoon hänen löytää laupiuden sinä päivänä Herran tykönä! Ja kuinka monessa asiassa hän minulle Ephesossa oli avullinen, sinä parhain tiedät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 1, 'Vahvista siis sinus, minun poikani, sen armon kautta, joka Jesuksessa Kristuksessa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 2, 'Ja mitä sinä olet minulta monen todistajan kautta kuullut, niin käske uskollisille ihmisille, jotka myös muita olisivat soveliaat opettamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 3, 'Kärsi vaivaa niinkuin luja Jesuksen Kristuksen sotamies.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 4, 'Ei yksikään sotamies sekoita itsiänsä elatuksen menoihin, sille kelvataksensa, joka hänen sotaan ottanut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 5, 'Ja jos joku kilvoittelee, niin ei hän kruunata, ellei hän toimellisesti kilvoittele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 6, 'Peltomiehen, joka pellon rakentaa, pitää ensin hedelmästä nautitseman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 7, 'Ymmärrä, mitä minä sanon: Herra antakoon sinulle ymmärryksen kaikissa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 8, 'Muista Jesuksen Kristuksen päälle, joka kuolleista noussut on: Davidin siemenestä minun evankeliumini jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 9, 'Jossa minä vaivaa kärsin kahleisiin asti niinkuin pahantekiä; vaan ei Jumalan sana ole sidottu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 10, 'Sentähden minä kärsin kaikki valittuin tähden, että hekin saisivat Jesuksessa Kristuksessa autuuden, ijankaikkisen kunnian kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 11, 'Se on totinen sana: jos me ynnä olemme kuolleet, niin me myös ynnä elämme;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 12, 'Jos me kärsimme, niin me myös ynnä hallitsemme; jos me hänen kiellämme, niin hän meidätkin kieltää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 13, 'Ellemme usko, niin hän pysyy kuitenkin uskollisena, joka ei itsiänsä kieltää taida.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 14, 'Näitä neuvo ja todista Herran edessä, ettei he sanoista riitelisi, joka ei mihinkään kelpaa, vaan ainoastaan luovuttamaan niitä jotka kuulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 15, 'Pyydä itses Jumalalle osoittaa toimelliseksi ja laittamattomaksi työntekijäksi, joka oikein totuuden sanan jakaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 16, 'Mutta siivottomat ja kelvottomat sanat hylkää, jotka paljon jumalatointa menoa saattavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 17, 'Ja heidän puheensa syö ympäriltänsä niinkuin ruumiin mato; joista on Hymeneus ja Philetus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 18, 'Jotka totuudesta ovat erehtyneet, sanoen ylösnousemisen jo tapahtuneen, ja ovat muutamat uskosta kääntäneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 19, 'Mutta Jumalan vahva perustus kuitenkin pysyy, joka tällä kiinnitetty on: Herra tuntee omansa: ja lakatkaan jokainen vääryydestä, joka Kristuksen nimeä mainitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 20, 'Mutta suuressa huoneessa ei ole ainoastaan kultaiset ja hopiaiset astiat, vaan myös puiset ja saviset, ja muutamat tosin kunniaksi, mutta muutamat häpiäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 21, 'Jos joku itsensä senkaltaisista ihmisistä puhdistaa, se tulee kunniaan pyhitetyksi astiaksi, perheenisännälle tarpeelliseksi ja kaikkiin hyviin töihin valmistetuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 22, 'Nuoruuden himot vältä; mutta noudata vanhurskautta, uskoa, rakkautta ja rauhaa kaikkein niiden kanssa, jotka puhtaasta sydämestä Herraa rukoilevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 23, 'Hullut ja turhat kysymykset hylkää, tietäen, että ne ainoastaan riidat synnyttävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 24, 'Mutta ei Herran palvelian tule riitaisen olla, vaan siviän jokaista kohtaan, opettavaisen, pahoja kärsiväisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 25, 'Hiljaisuudessa nuhtelevaisen vastahakoisia; jos Jumala heille joskus antais parannuksen totuutta ymmärtämään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 26, 'Ja he jälleen katuisivat ja perkeleen paulasta pääsisivät, jolta he hänen tahtonsa jälkeen vangitut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 1, 'Mutta sen sinun pitää tietämän, että viimeisinä päivinä vaaralliset ajat lähenevät;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 2, 'Sillä ne ihmiset, jotka itsiänsä rakastavat, ahneet, kerskaajat, ylpiät, pilkkaajat, vanhemmillensa tottelemattomat, kiittämättömät, jumalattomat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 3, 'Haluttomat, sopimattomat, laittajat, irtaalliset, kiukkuiset, kateet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 4, 'Pettäjät, tuimat, paisuneet, jotka enemmin hekumaa kuin Jumalaa rakastavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 5, 'Joilla on jumalinen meno olevinansa, mutta sen voiman he kieltävät pois. Karta siis senkaltaisia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 6, 'Sillä ne ovat niitä, jotka huoneesta huoneeseen juoksevat ja vaimoväen vangiksi vievät, jotka synneillä rasitetut ovat ja moninaisten himoin kanssa käyvät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 7, 'Aina oppivaiset, ja ei koskaan totuuden tuntoon tulevaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 8, 'Mutta niinkuin Jannes ja Jambres olivat Mosesta vastaan, niin nämätkin ovat totuutta vastaan: ne ovat ihmiset taidosta turmellut ja kelvottomat uskoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 9, 'Mutta ei heidän pidä silleen menestymän; sillä heidän hulluutensa pitää kaikille julki tuleman, niinkuin niidenkin oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 10, 'Mutta sinä olet seurannut minun opetustani, säätyäni, aivoitustani, uskoani, pitkämielisyyttäni, rakkauttani, kärsivällisyyttäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 11, 'Vainoomisiani, vaivojani, jotka minulle Antiokiassa, Ikoniossa ja Lystrassa tapahtuivat, jotka vainoomiset minä kärsin, ja kaikista on minun Herra päästänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 12, 'Mutta myös kaikkein, jotka jumalisesti Jesuksessa Kristuksessa elää tahtovat, pitää vainoa kärsimän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 13, 'Mutta pahoille ja petollisille ihmisille on tapahtuva jota edemmä sitä pahemmin, sekä vietteliöille että vietellyille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 14, 'Mutta pysy niissä, joita sinä oppinut olet ja sinulle uskottu on, tietäen keneltäs oppinut olet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 15, 'Ja ettäs jo lapsuudesta olet Pyhän Raamatun taitanut, joka sinun taitaa autuuteen neuvoa, sen uskon kautta, joka on Kristuksessa Jesuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 16, 'Sillä kaikkinainen kirjoitus on Jumalalta annettu, ja tarpeellinen opiksi, nuhteeksi, ojennukseksi, kuritukseksi, joka on vanhurskaudessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 17, 'Että Jumalan ihminen täydellinen olis, ja kaikkiin hyviin töihin sovelias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 1, 'Niin minä siis todistan Jumalan ja Herran Jesuksen Kristuksen edessä, joka on tuleva tuomitsemaan eläviä ja kuolleita, hänen ilmestyksessänsä ja valtakunnassansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 2, 'Saarnaa sanaa, pidä päälle sekä hyvällä että sopimattomalla ajalla, rankaise, nuhtele, neuvo kaikella siveydellä ja opetuksella;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 3, 'Sillä aika tulee, jona ei he voi terveellistä oppia kärsiä, vaan omain himoinsa jälkeen kokoovat itsellensä opettajat, että heidän korvansa syyhyvät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 4, 'Ja kääntävät korvansa pois totuudesta, ja turhiin juttuihin poikkeevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 5, 'Mutta valvo sinä kaikissa, kärsi ja kestä vaivoissa, tee evankeliumin saarnaajan työ ja toimita virkas täydellisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 6, 'Sillä minä jo uhrataan ja minun pääsemiseni aika lähestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 7, 'Minä olen hyvän kilvoituksen kilvoitellut, juoksun päättänyt, uskon pitänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 8, 'Tästedes on minulle tallelle pantu vanhurskauden kruunu, jonka Herra, vanhurskas tuomari, sinä päivänä minulle antaa, mutta ei ainoastansa minulle, vaan myös kaikille, jotka hänen ilmestystänsä rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 9, 'Ahkeroitse, ettäs pian minun tyköni tulet;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 10, 'Sillä Demas antoi minun ylön ja halasi tätä maailmaa ja meni Tessalonikaan, Kreskens Galatiaan, Titus Dalmatiaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 11, 'Ainoastaan Luukas on minun kanssani. Ota Markus tykös ja tuo häntä kanssas; sillä hän on sangen tarpeellinen minulle palvelukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 12, 'Tykikuksen minä lähetin Ephesoon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 13, 'Se hame, jonka minä Troadassa Karpuksen tykö jätin, tuo tullessas ja kirjat, mutta liiatenkin pärmäkirjat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 14, 'Aleksander vaskiseppä on minulle paljon pahaa tehnyt: Herra maksakoon hänelle hänen työnsä jälkeen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 15, 'Jota sinä kavahda; sillä hän on kovin meidän saarnojamme vastaan ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 16, 'Minun ensimäisessä edesvastauksessani ei yksikään minun kanssani ollut, vaan kaikki antoivat ylön minun; (älköön se heille olko soimattu!)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 17, 'Mutta Herra oli minun puolellani ja vahvisti minun, että saarna minun kauttani piti vahvistettaman, ja kaikki pakanat piti sen kuuleman; ja minä pelastettiin jalopeuran suusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 18, 'Ja Herra pelastaa minun kaikesta pahasta teosta, ja auttaa taivaalliseen valtakuntaansa, jolle olkoon kunnia ijankaikkisesta ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 19, 'Tervehdi Priskaa ja Akvilaa ja Onesiphorin perhettä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 20, 'Erastus jäi Korintiin, mutta Trophimon minä jätin Miletoon sairastamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 21, 'Ahkeroitse ennen talvea tulla. Sinua tervehtii Eubulus, ja Pudens, ja Linus, ja Klaudia, ja kaikki veljet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 22, 'Herra Jesus Kristus olkoon sinun henkes kanssa! Armo olkoon teidän kanssanne, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, 'Paavali, Jumalan palvelia ja Jesuksen Kristuksen apostoli, Jumalan valittuin uskon jälkeen ja totuuden tunnon, joka jumalisuuden jälkeen on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'Ijankaikkisen elämän toivoon, jonka Jumala, joka ei valehdella taida, ennen ijankaikkisia aikoja luvannut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, 'Mutta ajallansa sanansa ilmoitti saarnan kautta, joka minulle uskottu on, Jumalan meidän Vapahtajamme käskyn jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'Titukselle, toimelliselle pojalleni, meidän molempain uskomme jälkeen: armo, laupius, rauha Isältä Jumalalta ja meidän Vapahtajaltamme, Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'Sentähden minä sinun Kretaan jätin, että sinun pitää toimittaman, mitä vielä puuttuu, ja pappeja kuhunkin kaupunkiin asettamaan, niinkuin minä sinulle käskenyt olen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'Jos joku nuhteetoin ja yhden emännän mies on, jolla uskolliset lapset ovat, ei juomariksi eli kankeiksi soimatut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Sillä piispan tulee nuhteettoman olla, niinkuin Jumalan huoneen haltian, ei röyhkiän, ei tylyn, ei juomarin, ei tappelian, ei ilkiän voiton pyytäjän,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, 'Mutta vierasten holhojan, hyväntahtoisen, siivollisen, hurskaan, pyhän ja puhtaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'Ja kiinnipitävän puhtaasta ja opettavaisesta sanasta, että hän olis väkevä terveellisen opin kautta neuvomaan ja vastaanseisojia voittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'Sillä monta on tottelematointa, turhan puhujaa ja mielen kääntäjää, enimmästi ne, jotka ympärileikkauksesta ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'Joidenka suu pitää tukittaman, jotka koko huoneet kääntävät pois ja häpiällisen voiton tähden kelvottomia opettavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'Yksi heistä sanoi, heidän oma prophetansa: Kretalaiset ovat aina valehteliat, pahat pedot ja laiskat vatsat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'Tämä todistus on tosi; sentähden nuhtele heitä kovin, että he uskossa terveet olisivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'Eikä Juudalaisten turhia juttuja ja ihmisten käskyjä tottelisi, jotka itsensä totuudesta kääntävät pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 15, 'Kaikki ovat puhtaille puhtaat, mutta saastaisille ja uskottomille ei mikään puhdas ole, vaan sekä heidän mielensä että omatuntonsa on saastainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 16, 'He sanovat tuntevansa Jumalan, mutta töillänsä he sen kieltävät, ja ovat kauhiat ja kovakorvaiset ja kaikkiin hyviin töihin kelvottomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, 'Mutta puhu sinä niitä, mitkä ovat terveelliseen oppiin soveliaat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'Että vanhat olisivat raittiit, kunnialliset, siivolliset, lujat uskossa, rakkaudessa ja kärsivällisyydessä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'Vanhat vaimot myös käyttäisivät itsensä niin kuin pyhäin sopii, ei panetteliat, eikä juomarit, mutta hyvin opettavaiset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'Että nuoret vaimot heiltä hyviä tapoja oppisivat, miehiänsä rakastaisivat, lapsensa rakkaina pitäisivät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'Olisivat siviät, puhtaat, kotonansa pysyväiset, hyvät, miehillensä alamaiset, ettei Jumalan sana pilkatuksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'Neuvo myös nuoria miehiä siviästi olemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, 'Aseta itses kaikissa hyväin töiden esikuvaksi, vilpittömällä opetuksella ja kunniallisuudella,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, 'Terveellisellä ja nuhteettomalla sanalla, että se, joka itsensä vastaan panee, häpeäis eikä mitään löytäisi meistä pahoin puhuaksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'Neuvo palvelioita isännillensä alamaiset olemaan, ja kaikissa kelvolliseksi, ei vastaan sanojat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'Ei pettäväiset, vaan kaiken hyvän uskollisuuden näyttäväiset, että he Jumalan meidän Vapahtajamme opin kaikissa kaunistavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, 'Sillä Jumalan armo, kaikille ihmisille terveellinen, on ilmestynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'Joka meidät opettaa kaiken jumalattoman menon hylkäämään ja maailmalliset himot, ja tässä maailmassa siviästi ja hurskaasti ja jumalisesti elämään,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'Ja odottamaan autuaallista toivoa, ja suuren Jumalan ja meidän Lunastajamme Jesuksen Kristuksen ilmestystä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, 'Joka itsensä antoi meidän edestämme, että hän meitä kaikesta vääryydestä lunastais ja itsellensä erinomaiseksi kansaksi puhdistais, ahkeraksi hyviin töihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'Näitä sinä puhu ja neuvo, ja kaikella todella nuhtele: ei myös kenenkään pidä sinun katsoman ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, 'Neuvo heitä, että he päämiehille ja esivallalle kuuliaiset olisivat, että he kaikkiin hyviin töihin valmiit olisivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'Ettei he ketään pilkkaisi, eikä riitaiset olisi, vaan sopivaiset, osoittain kaikille ihmisille siveyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'Sillä me olimme myös muinen taitamattomat, kovakorvaiset, eksyväiset, palvellen himoja ja moninaisia hekumia, ja vaelsimme pahuudessa ja kateudessa, vainoten ja vihaten toinen toistamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'Mutta sittekuin Jumalan meidän Vapahtajamme hyvyys ja rakkaus ihmisille ilmestyi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, 'Ei vanhurskauden töiden kautta, joita me tehneet olemme, vaan laupiutensa kautta hän meidät autuaaksi teki, uuden syntymisen peson ja Pyhän Hengen uudistuksen kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, 'Jonka hän meidän päällemme, Jesuksen Kristuksen meidän Vapahtajamme kautta, runsaasti vuodattanut on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'Että me hänen armonsa kautta vanhurskaiksi tulisimme ja ijankaikkisen elämän perillisiksi toivon jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'Tämä on totinen sana ja näitä minä tahdon sinun vahvasti opettaman, että ne, jotka Jumalan päälle uskoneet ovat, ahkeroitsisivat hyvissä töissä muiden edellä käydä: nämät ovat ihmisille hyvät ja tarpeelliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'Mutta hulluja tutkimisia, polvilukuja, riitoja ja kilvoituksia laista vältä; sillä ne ovat turhat ja kelvottomat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, 'Eriseuraista ihmistä pakene, kun häntä kerta taikka kahdesti neuvottu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'Tietäen, että senkaltainen on käännetty pois ja syntiä tekee, niinkuin se, joka itsensä tuominnut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, 'Kuin minä Artemaan eli Tykikuksen sinun tykös lähetän, niin riennä sinä minun tyköni Nikopoliin; sillä minä olen aikonut siellä talvea pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, 'Lähetä Zenas, lainoppinut, ja Apollo visusti matkaan, ettei heiltä mitään puuttuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'Mutta anna myös niidenkin, jotka meidän ovat, oppia hyvissä töissä muiden edellä käymään, kussa niin tarvitaan, ettei hekään hedelmättömät olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'Sinua tervehtivät kaikki, jotka minun kanssani ovat. Tervehdi niitä, jotka meitä uskossa rakastavat. Armo olkoon teidän kaikkein kanssanne, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 1, 'Paavali, Kristuksen Jesuksen vanki, ja veli Timoteus, rakkaalle Philemonille, ja meidän apulaisellemme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 2, 'Ja rakkaalle Appialle ja Arkippukselle, meidän kanssapalveliallemme, ja seurakunnalle, joka sinun huoneessas on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 3, 'Armo olkoon teille ja rauha Jumalalta, meidän Isältämme ja Herralta Jesukselta Kristukselta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 4, 'Minä kiitän minun Jumalaani ja muistan aina sinua minun rukouksissani,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 5, 'Että minä kuulen siitä rakkaudesta ja uskosta, joka sinulla Herran Jesuksen päälle on ja kaikkein pyhäin tykö:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 6, 'Että sinun uskos, joka meille yhteinen on, tulis sinussa kaiken hyvyyden tuntemisen kautta voimalliseksi, joka teillä Kristuksessa Jesuksessa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 7, 'Sillä meillä on suuri ilo ja lohdutus sinun rakkaudestas, että pyhäin sydämet sinun kauttas, rakas veljeni, virvoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 8, 'Sentähden vaikka minulla on suuri uskallus Kristuksessa käskeä sinua, mitä sinun tehdä tulee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 9, 'Niin minä kuitenkin tahdon rakkauden puolesta ennen rukoilla, minä, joka tainkaltainen olen, nimittäin vanha Paavali, mutta nyt myös Jesuksen Kristuksen vanki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 10, 'Niin minä siis neuvon sinua, minun poikani Onesimuksen puolesta, jonka minä siteissäni siitin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 11, 'Joka sinulle muinen kelvotoin oli, mutta nyt sinulle ja minulle kyllä tarpeellinen, jonka minä nyt olen lähettänyt jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 12, 'Mutta ota häntä vastaan; sillä hän on minun oma sydämeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 13, 'Minä tahdoin häntä pitää minun tykönäni, että hän minua sinun puolestas evankeliumin siteissä palvelis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 14, 'Mutta en minä tahtonut mitään ilman sinun suosiotas tehdä, ettei sinun hyvyytes pitänyt oleman niinkuin vaadittu, vaan vapaamielinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 15, 'Sillä sentähden hän hetkeksi sinulta läksi, ettäs hänen ijäksi saisit jällensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 16, 'Ei nyt silleen niinkuin palvelian, vaan enemmin palvelian ja niinkuin rakkaan veljen, erinomattain minulle, mutta kuinka paljoa enemmin sinulle, sekä lihan kautta että Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 17, 'Jos sinä siis minun kumppaninas pidät, niin ota häntä vastaan niinkuin minuakin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 18, 'Mutta jos hän jotakin sinua vahingoittanut on eli on sinulle velkaa, niin sano minun syykseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 19, 'Minä Paavali olen tämän omalla kädelläni kirjoittanut ja tahdon sen sinulle maksaa, etten minä sinulle sanoisi, ettäs myös sinun itses minulle velkapää olet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 20, 'Armas veljeni! suo minun ihastua sinusta Herrassa, virvoita minun sydämeni Herrassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 21, 'Minä kirjoitin sinulle luottain sinun kuuliaisuutees, tietäen sinun enemmin tekevän kuin minä sanonkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 22, 'Valmista myös minulle majaa; sillä minä toivon, että minä teidän rukoustenne kautta teille lahjoitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 23, 'Sinua tervehtivät Epaphras, (minun kanssavankini Kristuksessa Jesuksessa,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 24, 'Markus, Aristarkus, Demas, Luukas, minun apulaiseni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 25, 'Meidän Herran Jesuksen Kristuksen armo olkoon teidän henkenne kanssa, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 1, 'Jumala puhui muinen usein ja monella muotoa isille prophetain kautta; näinä viimeisinä päivinä on hän meille puhunut Poikansa kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 2, 'Jonka on hän kaikkein perilliseksi pannut, ja on myös hänen kauttansa maailman tehnyt;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 3, 'Joka, että hän on hänen kunniansa kirkkaus ja hänen olemuksensa juurikuva, ja kantaa kaikki voimansa sanalla, ja on itse kauttansa meidän synteimme puhdistuksen tehnyt, ja istunut majesteetin oikialla puolella korkeuksissa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 4, 'On tullut niin paljoa paremmaksi enkeleitä, että hän ylimmäisemmän nimen on heidän suhteensa perinyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 5, 'Sillä kenelle hän on koskaan enkeleistä sanonut: sinä olet minun Poikani, tänäpänä minä sinun synnytin! ja taas: minä olen hänen Isänsä ja hän on minun Poikani!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 6, 'Ja taas: koska hän tuo esikoisen maailmaan, sanoo hän: häntä pitää kaikki Jumalan enkelit kumartaen rukoileman?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 7, 'Mutta enkeleistä hän sanoo: hän tekee enkelinsä hengeksi ja palveliansa tulenleimaukseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 8, 'Mutta Pojalle: Jumala! sinun istuimes pysyy ijankaikkisesta ijankaikkiseen: sinun valtakuntas valtikka on oikeuden valtikka.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 9, 'Sinä rakastit vanhurskautta ja vihasit vääryyttä, sentähden on sinun, oi Jumala, sinun Jumalas voidellut ilo-öljyllä enempi kuin sinun osaveljes.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 10, 'Ja: sinä Herra olet alusta maan perustanut, ja taivaat ovat sinun käsialas:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 11, 'Ne katoovat, mutta sinä pysyt; ja he kaikki vanhenevat niinkuin vaate.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 12, 'Ja niinkuin puvun sinä heitä muuttelet, ja he muuttuvat: mutta sinä kohdallasi pysyt ja ei sinun ajastaikas puutu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 13, 'Mutta kelle enkeleistä on hän koskaan sanonut: istu minun oikialle kädelleni, siihenasti kuin minä panen vihollises sinun jalkais astinlaudaksi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 14, 'Eikö he kaikki ole palvelevaiset henget, palvelukseen lähetetyt niille, jotka autuuden perimän pitää?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 1, 'Sentähden pitää meidän sitä visummin niistä vaarin ottaman, joita me kuulleet olemme, ettemme joskus pahenisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 2, 'Sillä jos se sana oli vahva, joka enkelitten kautta puhuttiin, ja kaikki ylitsekäymys ja tottelemattomuus on jo ansaitun palkkansa saanut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 3, 'Kuinkas me välttäisimme, jos me senkaltaisen autuuden katsomme ylön? joka sitte, kuin se ensin Herralta saarnattu oli, meissä vahvistetuksi tuli niiden kautta, jotka sen kuulleet olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 4, 'Ja Jumala on siihen todistuksensa antanut sekä ihmeillä että tunnustähdillä, niin myös moninaisilla voimallisilla töillä ja Pyhän Hengen jakamisilla tahtonsa jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 5, 'Sillä ei hän ole enkelitten alle antanut tulevaista maailmaa, josta me puhumme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 6, 'Mutta yksi sen todistaa toisessa paikassa ja sanoo: mikä on ihminen, että sinä häntä muistat, eli ihmisen poika, ettäs häntä etsiskelet?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 7, 'Sinä olet hänen vähäksi hetkeksi enkelitten suhteen alentanut: sinä olet hänen kunnialla ja ylistyksellä kaunistanut, ja asettanut kättes töiden päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 8, 'Kaikki olet sinä heittänyt hänen jalkainsa alle. Sillä siinä, että hän kaikki on hänen allensa heittänyt, ei hän mitään jättänyt, jota ei hän ole hänen allensa heittänyt; mutta nyt emme vielä näe kaikkia hänen allensa heitetyksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 9, 'Vaan Jesuksen, joka vähäksi hetkeksi enkelitten suhteen alennettu oli, näemme me kuoleman kärsimisen kautta kaunistetuksi kunnialla ja ylistyksellä, että hänen piti Jumalan armosta kaikkein edestä kuolemaa maistaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 10, 'Sillä se sopi hänen, jonka tähden kaikki ovat ja jonka kautta kaikki ovat, joka paljon lapsia kunniaan saattaa, että hän heidän autuutensa Pääruhtinaan kärsimisen kautta täydelliseksi tekis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 11, 'Sillä ne kaikki yhdestä ovat, sekä se, joka pyhittää, että ne, jotka pyhitetään, jonka tähden ei hän myös häpee heitä veljiksensä kutsua,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 12, 'Sanoen: minä julistan sinun nimes minun veljilleni ja keskellä seurakuntaa sinua veisulla ylistän;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 13, 'Ja taas: minä turvaan häneen; ja taas: katso, minä ja ne lapset, jotka Jumala minulle antanut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 14, 'Että siis lapsilla on liha ja veri, niin on hän myös niistä osalliseksi tullut, että hän olis kuoleman kautta hukuttanut sen, jolla kuoleman valta oli, se on: perkeleen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 15, 'Ja päästänyt ne, jotka kuoleman pelvosta piti kaiken ikänsä orjana oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 16, 'Sillä ei tosin hän koskaan enkeleitä päällensä ota, vaan Abrahamin siemenen hän päällensä ottaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 17, 'Josta hänen kaiketi piti veljiensä kaltainen oleman, että hän armollinen ja uskollinen ylimmäinen Pappi Jumalan edessä olis, sovittamaan kansan syntejä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 18, 'Sillä siitä, että hän kärsinyt on ja on kiusattu, taitaa hän myös niitä auttaa, jotka kiusataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 1, 'Sentähden pyhät veljet, jotka taivallisessa kutsumisessa osalliset olette! ottakaat vaari siitä apostolista ja ylimmäisestä Papista, jonka me tunnustamme, Kristuksesta Jesuksesta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 2, 'Joka on uskollinen sille, joka hänen tehnyt oli, niinkuin Moseskin koko hänen huoneeseensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 3, 'Mutta tämä on sitä suuremman kunnian ansainnut kuin Moses, että sillä suurempi kunnia huoneesta olis, joka sen rakensi, kuin itse huoneella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 4, 'Sillä jokainen huone on joltakin rakennettu; mutta joka kaikki rakensi, se on Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 5, 'Ja Moses tosin oli uskollinen kaikessa hänen huoneessansa, niinkuin palvelia, niiden todistukseksi, joita sitte sanottaman piti;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 6, 'Mutta Kristus niinkuin Poika ylitse huoneensa, jonka huone me olemme, jos me muutoin uskalluksen ja toivon kerskaamisen loppuun asti vahvana pidämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 7, 'Sentähden, niinkuin Pyhä Henki sanoo: tänäpänä, jos te kuulette hänen äänensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 8, 'Niin älkäät paaduttako sydämiänne, niinkuin haikeudessa tapahtui kiusauksen päivänä korvessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 9, 'Kussa teidän isänne minua kiusasivat: he koettelivat minua, ja näkivät minun työni neljäkymmentä ajastaikaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 10, 'Sentähden minä närkästyin tämän sukukunnan päälle ja sanoin: aina he eksyvät sydämellänsä, mutta ei he tunteneet minun teitäni,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 11, 'Niin että minä vannoin minun vihassani: ei heidän pidä minun lepooni tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 12, 'Katsokaat, rakkaat veljet, ettei teissä joskus olisi kelläkään paha, uskotoin sydän, joka elävästä Jumalasta luopuis,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 13, 'Vaan neuvokaat teitänne keskenänne joka päivä, niinkauvan kuin tänäpänä sanotaan, ettei joku teistä synnin petoksen kautta paatuisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 14, 'Sillä me olemme Kristuksesta osallisiksi tulleet, jos me muutoin aljetun uskon loppuun asti vahvana pidämme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 15, 'Kuin sanotaan: tänäpänä, jos te kuulette hänen äänensä; niin älkäät paaduttako sydämiänne, niinkuin haikeudessa tapahtui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 16, 'Sillä koska muutamat sen kuulivat, niin he vihoittivat hänen, vaan ei kaikki, jotka Egyptistä Moseksen kautta läksivät ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 17, 'Mutta keille hän neljäkymmentä ajastaikaa vihainen oli? eikö niille, jotka syntiä tekivät, joiden ruumiit korvessa hukkuivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 18, 'Mutta keille hän vannoi, ettei heidän pitänyt hänen lepoonsa tuleman? eikö uskomattomille?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 19, 'Ja me näemme, ettei he voineet epäuskon tähden sinne tulla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 1, 'Niin peljätkäämme siis, ettemme joskus hänen lepoonsa tulemisen lupausta hylkäisi, ja ettei kenkään meistä takaperin jäisi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 2, 'Sillä se on meille ilmoitettu niinkuin heillekin; mutta ei heitä sanan kuulo mitään auttanut, koska ei he niitä uskoneet, jotka sen kuulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 3, 'Sillä me, jotka uskoimme, tulemme lepoon, niinkuin hän sanoi: niinkuin minä vannoin minun vihassani: ei heidän pidä minun lepooni tuleman; ja tosin, koska työt maailman alusta täytetyt olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 4, 'Sillä hän sanoi yhdessä paikassa seitsemännestä päivästä näin: ja Jumala lepäsi seitsemäntenä päivänä kaikista töistänsä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 5, 'Ja taas tässä: ei heidän pidä minun lepooni tuleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 6, 'Että siis se vielä edespäin on, että muutamain pitää siihen tuleman, ja ne, joille se ensin ilmoitettu oli, ei ole siihen tulleet epäuskon tähden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 7, 'Määrää hän taas yhden päivän, niin pitkän ajan perästä, ja Davidin kautta sanoo: tänäpänä, (niinkuin sanottu on) tänäpänä, jos te kuulette hänen äänensä, niin älkäät paaduttako teidän sydämiänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 8, 'Sillä jos Josua olis heidät lepoon saattanut, niin ei hän olisi toisesta päivästä puhunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 9, 'Sentähden on Jumalan kansalle yksi lepo vielä tarjona.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 10, 'Sillä joka hänen lepoonsa jo tullut on, se lepää töistänsä, niinkuin Jumalakin lepää töistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 11, 'Niin ahkeroitkaamme siis siihen lepoon tulla, ettei joku samaan epäuskon esikuvaan lankeaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 12, 'Sillä Jumalan sana on elävä ja voimallinen, ja terävämpi kuin joku kaksiteräinen miekka, ja tunkee lävitse, siihenasti kuin se sielun ja hengen eroittaa, ja jäsenet ja ytimet, ja on ajatusten ja sydämen aivoitusten tuomari,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 13, 'Ja ei ole yhtään luontokappaletta hänen edessänsä näkymättä, mutta kaikki ovat paljaat ja julki hänen silmäinsä edessä, josta me puhumme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 14, 'Että siis meillä suuri ylimmäinen Pappi on, Jesus Jumalan Poika. joka taivaisiin mennyt on, niin pysykäämme siinä tunnustuksessa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 15, 'Sillä ei meillä ole se ylimmäinen pappi, joka ei taida meidän heikkouttamme armahtaa, vaan se, joka kaikissa kiusattu on, niin kuin mekin, kuitenkin ilman syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 16, 'Sentähden käykäämme edes uskalluksella armoistuimen tykö, että me laupiuden saisimme ja löytäisimme silloin armon, kuin me apua tarvitsemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 1, 'Sillä jokainen ylimmäinen pappi, otettu ihmisistä, pannaan ihmisten edestä niissä asioissa, jotka Jumalalle tulevat, uhraamaan lahjoja ja uhreja syntein edestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 2, 'Joka niitä armahtaisi, jotka taitamattomat ja eksyväiset ovat, että hän itsekin heikkoudella ympärikääritty on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 3, 'Ja tämän tähden tulee hänen niinkuin kansan edestä, niin itsensäkin edestä uhrata syntein edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 4, 'Ja ei yksikään omista itsellensä sitä kunniaa, vaan se, joka Jumalalta kutsutaan, niinkuin myös Aaron.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 5, 'Niin myös Kristus ei ole itsiänsä kunnioittanut, että hän ylimmäiseksi Papiksi oli tuleva, mutta se, joka hänelle sanoi: sinä olet minun Poikani, tänäpänä minä sinun synnytin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 6, 'Niinkuin hän sanoo toisessa paikassa: sinä olet Pappi ijankaikkisesti, Melkisedekin säädyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 7, 'Joka lihansa päivinä on uhrannut rukoukset ja nöyrät anomiset, väkevällä huudolla ja kyyneleillä sen tykö, joka hänen voi kuolemasta pelastaa, ja on myös kuultu, että hän Jumalaa kunnioitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 8, 'Ja vaikka hän (Jumalan) Poika oli, on hän kuitenkin niistä, joita hän kärsi, kuuliaisuuden oppinut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 9, 'Ja kuin hän täydelliseksi tuli, on hän kaikille niille, jotka hänelle kuuliaiset ovat, syy ijankaikkiseen autuuteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 10, 'Ja on Jumalalta ylimmäiseksi Papiksi nimitetty, Melkisedekin säädyn jälkeen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 11, 'Josta meillä on paljo sanomista, ja se on työläs selittää; sillä te olette kovakorvaisiksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 12, 'Sillä te, joiden piti alkaa opettajat oleman, tarvitsette taas, että me teille ensimäiset puustavit Jumalan sanan opista opettaisimme, ja olette tulleet niiksi, jotka tarvitsevat rieskaa ja ei vahvaa ruokaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 13, 'Sillä jolle vielä rieskaa pitää annettaman, se on harjoittamatoin vanhurskauden sanaan; (sillä hän on lapsi;)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 14, 'Mutta täydellisten sopii vahva ruoka, joilla ovat tottumisen kautta harjoitetut mielet hyvää ja pahaa eroittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 1, 'Sentähden antakaamme Kristuksen opin alun sillänsä olla, ja ruvetkaamme niihin, jotka täydellisyyteen saattavat: ei vasta-uudesta perustusta laskein parannukseen kuolevaisista töistä ja uskoon Jumalan päälle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 2, 'Kasteen oppiin, kätten päällepanemiseen, kuolleitten ylösnousemiseen ja ijankaikkiseen tuomioon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 3, 'Ja sen me tahdomme tehdä, jos Jumala muutoin sallii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 4, 'Sillä se on mahdotoin, että ne, jotka kerran valaistus ovat, ja sitä taivaallista lahjaa maistaneet, ja ovat Pyhästä Hengestä osallisiksi tulleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 5, 'Ja maistaneet Jumalan hyvää sanaa, ja tulevaisen maailman voimaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 6, 'Jos he lankeevat pois, että he vasta-uudesta parannukseen uudistettaisiin, jotka toistamiseen itsellensä Jumalan Pojan ristiinnaulitsevat ja pilkkana pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 7, 'Sillä maa, joka sateen sisällensä särpää, joka usein sen päälle tulee, ja kasvaa tarpeellisia ruohoja niille, jotka sitä viljelevät, se saa siunauksen Jumalalta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 8, 'Mutta joka orjantappuroita ja ohdakkeita kasvaa, se on kelvotoin ja lähin kirousta, jonka loppu on, että se poltetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 9, 'Mutta me toivomme teiltä rakkahimmat, parempaa ja sitä, mikä autuuteen sopii, ehkä me näin puhumme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 10, 'Sillä ei Jumala ole väärä, että hän unohtais teidän tekonne ja työnne rakkaudessa, jonka te hänen nimellensä osoititte, koska te pyhiä palvelitte ja vielä palvelette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 11, 'Mutta me halajamme, että jokainen teistä sen ahkeruuden osoittais, pitäin toivon vahvuuden hamaan loppuun asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 12, 'Ettette hitaiksi tulisi, vaan olisitte niiden seuraajat, jotka uskon ja pitkämielisyyden kautta luvatun perimisen saavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 13, 'Sillä Jumala, joka Abrahamille lupauksen antoi, koska ei hän taitanut yhdenkään suuremman kautta vannoa, niin hän vannoi itse kauttansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 14, 'Sanoen: totisesti tahdon minä siunaten siunata sinua ja enentäen enentää sinua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 15, 'Ja että hän kärsivällisesti odotti, niin hän sai lupauksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 16, 'Sillä ihmiset tosin vannovat sen kautta, joka suurempi on kuin he, ja se on kaiken heidän riitansa loppu, jos se valalla vahvistetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 17, 'Jossa Jumala tahtoi lupauksen perillisille neuvonsa vahvuuden yltäkylläisesti osoittaa, vannoi hän valan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 18, 'Että me kahden liikkumattoman kappaleen kautta, joissa mahdotoin on Jumalan valehdella, juuri vahvan uskalluksen pitäisimme, me jotka siihen turvaamme, että me taritun toivon saisimme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 19, 'Jonka me pidämme vahvana ja lujana meidän sielumme ankkurina, joka ulottuu sisälle hamaan niihinkin asti, jotka esiripun sisälmäisellä puolella ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 20, 'Johonka edelläjuoksia on meidän edellämme mennyt sisälle, Jesus, Melkisedekin säädyn jälkeen, ylimmäiseksi Papiksi tehty ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 1, 'Sillä tämä Melkisedek oli Salemin kuningas, kaikkein korkeimman Jumalan pappi, joka Abrahamia vastaan meni, kuin hän palasi kuningasten taposta, ja siunasi häntä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 2, 'Jolle myös Abraham jakoi kymmenykset kaikista. Ensin hän tulkitaan vanhurskauden kuninkaaksi, vaan sen jälkeen Salemin kuninkaaksi, se on: rauhan kuningas,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 3, 'Ilman isää, ilman äitiä, ilman sukua, ja ei hänellä ole päiväin alkua eikä elämän loppua; mutta hän on Jumalan Poikaan verrattu ja pysyy pappina ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 4, 'Mutta katsokaat, kuinka suuri tämä on, jolle Abraham patriarkka saaliista kymmenykset antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 5, 'Ja ne, jotka Levin pojista papin viran ottavat, niin heillä on käsky kymmenyksiä kansalta ottaa lain jälkeen, se on: heidän veljiltänsä, vaikka ne Abrahamin kupeista tulleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 6, 'Mutta se, jonka sukua ei heidän seassansa lueta, otti Abrahamilta kymmenykset ja siunasi häntä, jolla lupaukset olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 7, 'Mutta ei yksikään sitä kiellä, että vähempi siunataan siltä, joka enempi on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 8, 'Ja tässä tosin kuolevaiset ihmiset kymmenyksiä ottavat; mutta siellä hän todistaa hänen elävän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 9, 'Ja (että minun niin sanoman pitää,) Levin, joka tottui kymmenyksiä ottamaan, täytyi myös Abrahamissa kymmenyksiä antaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 10, 'Sillä hän oli vielä isäinsä kupeissa, kuin Melkisedek häntä vastaan meni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 11, 'Sentähden, jos täydellisyys on Levin pappeuden kautta tapahtunut; (sillä sen alla on kansa lain saanut,) mitä sitte oli tarvetta sanoa, että toinen pappi oli Melkisedekin säädyn jälkeen tuleva, ja ei Aaronin säädyn jälkeen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 12, 'Sillä kussa pappeus muutetaan, siinä pitää myös laki muutettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 13, 'Sillä se, josta näitä sanotaan, on toisesta suvusta, josta ei yksikään alttaria palvellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 14, 'Sillä se on julkinen, että meidän Herramme on Juudan sukukunnasta tullut, jolle sukukunnalle ei Moses ole mitään pappeudesta puhunut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 15, 'Ja se on vielä selkeämpi, jos Melkisedekin säädyn jälkeen toinen pappi tulee ylös,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 16, 'Joka ei lihallisen käskyn lain jälkeen tehty ole, vaan loppumattoman elämän voiman jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 17, 'Sillä näin hän todistaa: sinä olet pappi ijankaikkisesti Melkisedekin säädyn jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 18, 'Sillä ensimäinen laki lakkaa, sen heikkouden ja kelvottomuuden tähden;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 19, 'Sillä ei se laki taitanut täydelliseksi tehdä, vaan se oli sisällejohdatus parempaan toivoon, jonka kautta me Jumalaa lähenemme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 20, '(Ja niin paljoa enempi, ettei ilman valaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 21, 'Sillä ne olivat tosin ilman valaa papiksi tulleet, mutta tämä valalla, hänen kauttansa, joka hänelle sanoi: Herra on vannonut ja ei sitä kadu: sinä olet pappi Melkisedekin säädyn jälkeen ijankaikkisesti,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 22, 'Ja näin paljoa paremman Testamentin toimittajaksi on Jesus tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 23, 'Ja niitä tosin monta papiksi tuli, ettei kuolema sallinut heidän pysyä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 24, 'Mutta tällä, että hän pysyy ijankaikkisesti, on katoomatoin pappeus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 25, 'Josta hän myös taitaa ne ijankaikkisesti autuaiksi tehdä, jotka hänen kauttansa Jumalan tykö tulevat, ja elää aina ja rukoilee alati heidän edestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 26, 'Sillä senkaltainen ylimmäinen Pappi meille sopii, pyhä, viatoin, saastatoin, syntisistä eroitettu ja korkeammaksi taivaita tullut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 27, 'Jolla ei olisi joka päivä tarve, niinkuin muut ylimmäiset papit, ensin omain synteinsä edestä uhraamaan, sitte kansan syntein edestä; sillä sen hän on jo silloin tehnyt, kuin hän itsensä uhrasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 28, 'Sillä laki asettaa ihmiset ylimmäiseksi papiksi, joilla heikkous on; mutta valan sana, joka lain jälkeen sanottiin, asettaa Pojan ijankaikkisesti täydelliseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 1, 'Mutta tämä on pääkappale niistä, joita me puhumme: meillä on senkaltainen ylimmäinen Pappi, joka istuu oikialla kädellä majesteetin istumella taivaissa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 2, 'Ja on pyhäin lahjain palvelia, ja sen totisen majan, jonka Jumala asetti ja ei ihminen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 3, 'Sillä jokainen ylimmäinen pappi asetetaan uhraamaan lahjoja ja uhreja: sentähden tarvitaan, että tälläkin olis jotakin uhraamista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 4, 'Sillä jos hän nyt maan päällä olis, niin ei hän olisi pappi; sillä papit ovat, jotka lain jälkeen lahjoja uhraavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 5, 'Jotka palvelevat taivaallisten esikuvaa ja varjoa, niinkuin jumalallinen vastaus Mosekselle sanoi, kuin hänen piti majan päättämän: katso, sanoo hän, ettäs kaikki teet sen kuvan jälkeen, mikä sinulle vuorella osoitettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 6, 'Mutta nyt on hän paremman viran saanut, niinkuin hän paremman Testamentinkin välimies on, joka parempain lupausten päällä seisoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 7, 'Sillä jos entinen olis puuttumatoin ollut, niin ei toiselle olisi siaa tehty;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 8, 'Sillä hän nuhtelee heitä ja sanoo: katso, päivät tulevat, sanoo Herra, että minä Israelin huoneelle ja Juudan huoneelle tahdon Uuden Testamentin päättää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 9, 'En sen Testamentin jälkeen, jonka minä heidän isillensä sinä päivänä annoin, kuin minä heidän käteensä rupesin, heitä Egyptin maalta johdattaakseni; sillä ei he pysyneet minun Testamentissani, niin en minäkään ole heistä lukua pitänyt, sanoo Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 10, 'Sillä tämä on se Testamentti, jonka minä tahdon säätää Israelin huoneelle, niiden päiväin jälkeen, sanoo Herra: minä tahdon antaa minun lakini heidän mieleensä, ja tahdon ne kirjoittaa heidän sydämiinsä, ja tahdon olla heidän Jumalansa, ja heidän pitää oleman minun kansani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 11, 'Ja ei yhdenkään pidä lähimmäistänsä opettaman eikä veljeänsä, ja sanoman: tunne Herra! sillä kaikki pitää minun tunteman, hamasta pienestä heidän seassansa niin suurimpaan asti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 12, 'Sillä minä tulen lepytetyksi heidän vääryydestänsä ja heidän synneistänsä, ja heidän vääryyttänsä en minä tahdo enempi muistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 13, 'Siinä kuin hän sanoo: uusi, vanhensi hän entisen; sillä joka vanha ja ijällinen on, se on läsnä loppuansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 1, 'Niin oli tosin entiselläkin majalla jumalanpalveluksen oikeus ja ulkonainen pyhyys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 2, 'Sillä ensimäinen maja oli rakennettu, jossa olivat kynttiläjalka, ja pöytä, ja katselmusleivät, joka pyhäksi kutsuttiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 3, 'Mutta toisen esiripun takana oli se maja, joka kaikkein pyhimmäksi kutsuttiin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 4, 'Jossa oli kultainen pyhän savun astia ja Testamentin arkki kaikkialta kullalla silattu, siinä myös oli kultainen astia, jossa oli manna, ja kukoistavainen Aaronin sauva ja Testamentin taulut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 5, 'Mutta sen päällä olivat kunnian Kerubimit, jotka armo-istuimen varjosivat; joista ei nyt ole erinomattain sanomista.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 6, 'Mutta kuin ne näin asetetut olivat, menivät papit aina siihen ensimäiseen majaan ja toimittivat jumalanpalveluksen;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 7, 'Vaan toiseen meni ainoasti ylimmäinen pappi kerran vuodessa yksinänsä, ei ilman verta, jonka hän uhrasi omainsa ja kansan rikosten edestä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 8, 'Jolla Pyhä Henki ilmoitti, ettei pyhityksen tietä niinkauvan julistettu, kuin se entinen maja seisoo,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 9, 'Joka sillä ajalla oli esikuva, jossa lahjat ja uhrit uhrattiin, jotka ei voineet omantunnon perään täydelliseksi tehdä sitä, joka jumalanpalvelusta teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 10, 'Ainoastaan ruilla ja juomilla, ja moninaisilla pesemisillä ja lihan säädyissä, jotka ojennuksen aikaan asti olivat päälle pannut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 11, 'Mutta Kristus on tullut tulevaisten tavarain ylimmäiseksi Papiksi, suuremman ja täydellisemmän majan kautta, joka ei käsillä tehty ole, se on: joka ei näin ole rakennettu;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 12, 'Eikä kauristen taikka vasikkain veren kautta, vaan hän on kerran oman verensä kautta mennyt pyhään, ja ijankaikkisen lunastuksen löytänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 13, 'Sillä jos härkäin ja kauristen veri, ja hehkoisen tuhka, priiskotettu saastaisten päälle, pyhittää lihalliseen puhtauteen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 14, 'Kuinka paljoa enemmin Kristuksen veri, joka itsensä ilman kaiketa viata iankaikkisen hengen kautta Jumalalle uhrannut on, on puhdistava omantuntomme kuolevaisista töistä, elävää Jumalaa palvelemaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 15, 'Ja sentähden on hän myös Uuden Testamentin välimies, että ne, jotka kutsutut ovat, sen luvatun ijankaikkisen perimisen saisivat, että hänen kuolemansa siinä välillä kävi niiden ylitsekäymisten lunastukseksi, jotka entisen Testamentin alla olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 16, 'Sillä kussa Testamentti on, siinä pitää myös hänen kuolemansa oleman, joka Testamentin teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 17, 'Sillä kuolemalla testamentti vahvistetaan, joka ei ole niin kauvan vahva, kuin se elää, joka sen teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 18, 'Sentähden ei se entinenkään ilman verta säätty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 19, 'Sillä kuin Moses oli puhunut kaikelle kansalle jokaisen käskyn lain jälkeen, otti hän vasikkain ja kauristen verta veden kanssa, ja purpuravilloja, ja isoppia, ja priiskotti sekä Raamatun että kaiken kansan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 20, 'Sanoen: tämä on sen Testamentin veri, jonka Jumala teille käskenyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 21, 'Ja majan ja kaikki jumalanpalveluksen astiat priiskotti hän myös verellä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 22, 'Ja lähes kaikki verellä lain jälkeen puhdistetaan, ja paitsi veren vuodatusta ei yhtään anteeksiantamusta tapahdu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 23, 'Niin siis tarvitaan, että taivaallisten kuvat senkaltaisilla puhdistetaan; mutta itse taivaalliset pitää paremmilla uhreilla puhdistettaman kuin ne olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 24, 'Sillä ei Kristus mennyt käsillä tehtyyn pyhään, joka totisen kuva on, vaan hän meni itse taivaasen, että hän nyt Jumalan kasvoin edessä meidän tähtemme ilmestyis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 25, 'Ei, että hänen pitää useimmin itsensä uhraaman, niinkuin ylimmäinen pappi joka vuosi meni muukalaisella verellä pyhään:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 26, '(Muutoin olis hänen useammin tullut jo maailman alusta kärsiä,) mutta nyt kerran maailman lopulla on hän oman uhrinsa kautta ilmestynyt synnin poispanemiseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 27, 'Ja niinkuin kaikkein ihmisten pitää kerran kuoleman, mutta senjälkeen tuomio,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 28, 'Niin on myös Kristus kerran uhrattu monen syntejä ottamaan pois; mutta toisella haavalla on hän ilman syntiä ilmestyvä niille, jotka häntä odottavat autuudeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 1, 'Sillä lailla on tulevaisten tavarain varjo, ei itse hyvyyden olento; niillä uhreilla, joita he joka vuosi alinomaa uhraavat, ei se ikänä taida niitä täydelliseksi tehdä, jotka uhraavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 2, 'Muutoin olis uhraamasta lakattu, jos ei niillä, jotka uhrasivat, synneistä silleen omaatuntoa olisi, koska he kerran puhdistetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 3, 'Vaan sillä tapahtuu joka vuosi synnin muistuttamus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 4, 'Sillä mahdotoin on härkäin ja kauristen veren kautta syntejä ottaa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 5, 'Sentähden, kuin hän maailmaan tuli, sanoi hän: uhria ja lahjaa et sinä tahtonut, mutta ruumiin olet sinä minulle valmistanut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 6, 'Polttouhrit ja syntiuhrit ei ole sinun mieleises.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 7, 'Silloin minä sanoin: katso, minä tulen, (Raamatussa on minusta kirjoitettu,) että minun pitää tekemän sinun tahtos, Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 8, 'Niinkuin hän ennen sanoi: uhria ja lahjaa, ja polttouhria ja syntiuhria et sinä tahtonut, ei myös ne sinulle kelvanneet, (jotka lain jälkeen uhrataan,)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 9, 'Silloin hän sanoi: katso, minä tulen tekemään, Jumala, sinun tahtos. Hän ottaa pois entisen, että hän toisen asettais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 10, 'Jonka tahdon kautta me kerran pyhitetyt olemme, Jesuksen Kristuksen ruumiin uhraamisella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 11, 'Ja jokainen pappi on siihen pantu, että hänen joka päivä jumalanpalvelusta tekemän pitää ja usein yhtäläistä uhria uhraaman, jotka ei koskaan voi syntejä ottaa pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 12, 'Mutta kuin tämä oli yhden ijankaikkisesti kelpaavan uhrin syntein edestä uhrannut, istuu hän nyt Jumalan oikialla kädellä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 13, 'Ja odottaa, että hänen vihollisensa pannaan hänen jalkainsa astinlaudaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 14, 'Sillä yhdellä uhrilla on hän ijankaikkisesti täydelliseksi tehnyt ne, jotka pyhitetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 15, 'Mutta sen todistaa myös meille itse Pyhä Henki, sillä että hän ennen sanoi:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 16, 'Tämä on se Testamentti, jonka minä tahdon heille tehdä niiden päiväin jälkeen, sanoo Herra: minä tahdon antaa minun lakini heidän sydämiinsä, ja heidän mieliinsä minä ne kirjoitan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 17, 'Ja heidän syntejänsä ja vääryyttänsä en minä enempi tahdo muistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 18, 'Mutta kussa näiden anteeksiantamus on, siinä ei silleen uhria syntein edestä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 19, 'Että siis meillä, rakkaat veljet, on vapaus mennä pyhään, Jesuksen veren kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 20, 'Jonka hän meille on valmistanut uudeksi ja eläväksi tieksi, esiripun kautta, se on: hänen lihansa kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 21, 'Ja meillä on yksi suuri Pappi, Jumalan huoneen haltia;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 22, 'Niin käykäämme hänen tykönsä totisella sydämellä, täydellä uskolla, priiskotetut meidän sydämissämme, (ja päästetyt) pahasta omastatunnosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 23, 'Ja pestyt ruumiin puolesta puhtaalla vedellä, ja pitäkäämme horjumatoin toivon tunnustus: (sillä se on uskollinen, joka ne lupasi),');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 24, 'Ja ottakaamme vaari toinen toisestamme, että me ahkeroitsemme rakkaudesta ja hyvistä töistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 25, 'Ei antain ylön yhteistä seurakuntaa, niinkuin muutamain tapa on, vaan neuvokaat teitänne keskenänne, ja sitä enemmin kuin te näette sen päivän lähestyvän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 26, 'Sillä jos me ehdollamme sitte syntiä teemme, kuin me olemme totuuden tuntoon tulleet, niin ei meillä ole enään yhtään uhria syntein edestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 27, 'Vaan hirmuinen tuomion odotus ja tulen kiivaus, joka vastahakoiset syövä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 28, 'Jos joku Moseksen lain rikkoo, hänen pitää ilman armoa kuoleman kahden taikka kolmen todistajan kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 29, 'Kuinka paljoa enemmän rangaistuksen te luulette sen ansainneen, joka Jumalan Pojan jaloilla tallaa ja Testamentin veren saastuttaa, jonka kautta hän pyhitetty on, ja armon Henkeä pilkkaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 30, 'Sillä me tunnemme hänen, joka sanoi: minun on kosto, minä tahdon kostaa, sanoo Herra; ja taas: Herra on kansansa tuomitseva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 31, 'Hirmuinen on langeta elävän Jumalan käsiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 32, 'Muistakaa siis entisiä päiviä, joina te valistetut olitte ja kärsitte monen vaivan kilvoituksen:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 33, 'Puolittain silloin, kuin te sekä pilkkain että tuskain kautta kaikille ihmeeksi olitte: puolittain, kuin te niiden kanssa osalliset olitte, joille myös niin kävi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 34, 'Sillä te olette myös niistä vaivoista, jotka minun siteistäni tapahtuivat, osalliset olleet, ja teidän hyvyytenne raatelemisen olette te ilolla kärsineet, tietäen, että teillä on parempi ja pysyväisempi tavara taivaissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 35, 'Älkäät siis heittäkö pois teidän uskallustanne, jolla suuri palkan makso on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 36, 'Sillä kärsivällisyys on teille tarpeellinen, tehdäksenne Jumalan tahtoa, että te lupauksen saisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 37, 'Sillä vähän hetken perästä tulee se, joka tuleva on, ja ei viivyttele.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 38, 'Mutta vanhurskas elää uskosta: ja joka välttää, siihen ei minun sieluni mielisty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 39, 'Mutta emme ole ne, jotka meitämme kadotukseen vältämme, vaan jotka uskomme sielun tallella pitämiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 1, 'Mutta usko on vahva uskallus niihin, joita toivotaan, ja ei näkymättömistä epäile.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 2, 'Sen kautta ovat vanhat todistuksen saaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 3, 'Uskon kautta me ymmärrämme, että maailma on Jumalan sanalla valmistettu, ja että kaikki, mitä me näemme, ne ovat tyhjästä tehdyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 4, 'Uskon kautta Abel uhrasi Jumalalle suuremman uhrin kuin Kain, jonka kautta hän sai todistuksen, että hän oli vanhurskas, kuin Jumala hänen lahjoistansa todisti; ja sen kautta hän vielä puhuu, vaikka hän kuollut on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 5, 'Uskon kautta Enok otettiin pois, ettei hän kuolemaa nähnyt, ja ei ole löydetty, että Jumala hänen otti pois; sillä ennenkuin hän otettiin pois, oli hänellä todistus, että hän kelpasi Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 6, 'Sillä ilman uskoa on mahdotoin kelvata (Jumalalle); sillä joka Jumalan tykö tulla tahtoo, sen pitää uskoman, että hän on, ja on niille kostaja, jotka häntä etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 7, 'Uskon kautta sai Noa Jumalan käskyn niistä, jotka ei vielä näkyneet, pelkäsi ja valmisti arkin huoneensa autuudeksi; jonka kautta hän maailman tuomitsi, ja tuli sen vanhurskauden perilliseksi, joka uskon kautta tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 8, 'Uskon kautta tuli Abraham kuuliaiseksi, kuin hän kutsuttiin menemään siihen maahan, jonka hän oli perivä, ja hän meni eikä tietänyt kuhunka hän tuleva oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 9, 'Uskon kautta oli hän muukalainen luvatussa maassa, niinkuin vieraalla maalla, ja asui majoissa Isaakin ja Jakobin kanssa, jotka olivat sen lupauksen kanssaperilliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 10, 'Sillä hän oli odottanut sitä kaupunkia, jolla perustus oli, jonka rakentaja ja luoja on Jumala.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 11, 'Uskon kautta myös Saara sai voiman siittääksensä, ja synnytti jälkeen ikänsä ajan; sillä hän piti sen uskollisena, joka sen hänelle luvannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 12, 'Sentähden myös yhdestä, joka niin jo kuollut oli, syntyi monta, niinkuin tähtiä on taivaassa ja niinkuin santaa meren rannassa, joka epälukuinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 13, 'Nämät kaikki ovat uskossa kuolleet ja ei ole niistä lupauksista saaneet, vaan ainoastansa taampaa nähneet ja kuitenkin niihin turvanneet ja hyvin tyytyivät ja tunnustivat, että he vieraat ja muukalaiset maan päällä olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 14, 'Sillä ne, jotka näitä sanovat, he osoittavat, että he isänmaata etsivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 15, 'Ja jos he sitte muistaneet olisivat, kusta he lähteneet olivat, olis heillä kyllä aikaa palata ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 16, 'Mutta he pyytävät parempaa, se on: taivaallista. Sentähden ei Jumala häpee kutsuttaa heidän Jumalaksensa; sillä hän valmisti heille kaupungin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 17, 'Uskon kautta uhrasi Abraham Isaakin, kuin hän kiusattiin, ja uhrasi ainokaisensa, kuin hän jo oli lupaukset saanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 18, 'Josta sanottu oli: Isaakissa kutsutaan sinulle siemen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 19, 'Ja ajatteli, että Jumala voi kuolleistakin herättää; josta hän myös hänen niinkuin yhdessä esikuvassa jälleen sai.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 20, 'Uskon kautta siunasi Isaak tulevaisista asioista Jakobia ja Esauta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 21, 'Uskon kautta siunasi Jakob kuollessansa molemmat Josephin pojat, rukoili ja nojasi sauvansa pään päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 22, 'Uskon kautta puhui Joseph kuollessansa Israelin lasten lähtemisestä ja antoi käskyn luistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 23, 'Uskon kautta Moses, kuin hän syntynyt oli, salattiin kolme kuukautta vanhemmiltansa, että he näkivät, kuinka kaunis poikainen hän oli, ja ei peljänneet kuninkaan haastoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 24, 'Uskon kautta Moses, kuin hän jo suureksi tuli, kielsi kutsuttaa itsensä Pharaon tyttären pojaksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 25, 'Ja valitsi paljoa paremmaksi kärsiä vaivaa Jumalan joukon kanssa, kuin ajallista tarvetta synnissä nautita,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 26, 'Ja luki suuremmaksi rikkaudeksi Kristuksen pilkan, kuin Egyptin tavarat; sillä hän katsoi palkan maksoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 27, 'Uskon kautta jätti hän Egyptin ja ei peljännyt kuninkaan hirmuisuutta; sillä hän riippui hänessä, jota ei hän nähnyt, niinkuin hän jo olis hänen nähnyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 28, 'Uskon kautta piti hän pääsiäistä ja veren vuodatusta, ettei se, joka esikoiset tappoi, olisi ruvennut heihin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 29, 'Uskon kautta kävivät ne Punaisen meren lävitse niinkuin kuivaa maata myöten, jota myös Egyptiläiset koettelivat ja upposivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 30, 'Uskon kautta Jerikon muurit lankesivat, kuin niitä seitsemän päivää käytiin ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 31, 'Uskon kautta ei portto Rahab hukkunut uskomattomain kanssa, koska vakoojat rauhallisesti huoneeseensa korjasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 32, 'Ja mitä minun pitää enempi sanoman? Sillä aika tulis minulle lyhyeksi, jos minun pitäis luetteleman Gideonista, ja Barakista, ja Simsonista, ja Jephtasta, ja Davidista, ja Samuelista, ja prophetaista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 33, 'Jotka uskon kautta ovat valtakunnat voittaneet, tehneet vanhurskautta, saaneet lupaukset, tukkineet jalopeurain suut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 34, 'Sammuttaneet tulen voiman, välttäneet miekan terän, ovat väkeväksi heikkoudesta tulleet ovat voimalliseksi sodassa tulleet, muukalaisten sotajoukot maahan lyöneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 35, 'Vaimot ovat kuolleensa ylösnousemisesta jälleen saaneet; mutta muut ovat rikki revityt, ja ei pelastusta ottaneet vastaan, että heidän paremman ylösnousemisen saaman piti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 36, 'Muutamat taas ovat pilkkoja ja haavoja kärsineet, ja vielä sittekin kahleet ja vankiuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 37, 'Ovat kivitetyt, rikki hakatut, lävitse pistetyt, miekalla surmatut, vaeltaneet ympäri lammasten ja vuohten nahoissa, ovat olleet köyhät, ahdistetut, vaivatut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 38, '(Joille maailma oli mahdotoin), ovat korvessa eksyneet ja vuorilla, ja mäen rotkoissa ja maan kuopissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 39, 'Ja kaikki nämät ovat uskon kautta todistuksen saaneet, eikä saaneet sitä lupausta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 40, 'Että Jumala on jotakin paremmin meille edeskatsonut, ettei he ilman meitä täydelliseksi tulleet olisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 1, 'Sentähden myös me, että meillä on näin suuri todistusten joukko meidän ympärillämme, niin pankaamme pois kaikki kuorma ja synti, joka aina meihin tarttuu ja hitaaksi tekee, ja juoskaamme kärsivällisyyden kautta siinä kilvoituksessa, joka meidän eteemme pantu on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 2, 'Ja katsokaamme uskon alkajan ja päättäjän Jesuksen päälle, joka, vaikka hän olis kyllä taitanut iloita, kärsi ristiä, ei totellut pilkkaa, ja nyt istuu oikialla kädellä Jumalan istuimella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 3, 'Niin muistakaat häntä, joka senkaltaisen vastahakoisuuden on syntisiltä itse vastaansa kärsinyt, ettette väsy teidän mielessänne ja lakkaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 4, 'Sillä ette ole vielä hamaan vereen asti kilvoitellen syntiä vastaan olleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 5, 'Ja te olette jo unohtaneet sen manauksen, joka teille niin. kuin lapsille puhuu: minun poikani, älä katso ylön Herran kuritusta, ja älä näänny, koskas häneltä rangaistaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 6, 'Sillä jota Herra rakastaa, sitä hän myös rankaisee; mutta jokaista poikaa hän pieksää, jonka hän korjaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 7, 'Jos te kurituksen kärsitte, niin Jumala taritsee itsensä teille niinkuin lapsillensa; sillä kuka on se poika, jota ei isä kurita?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 8, 'Mutta jos te olette ilman kuritusta, josta kaikki ovat osalliset olleet, niin te olette äpärät ja ette lapset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 9, 'Ja kuin meillä ovat lihalliset isät olleet kurittajana, niin me olemme niitä kavahtaneet: eikö meidän siis paljoa enemmin pidä hengelliselle Isälle alamaiset oleman, että me eläisimme?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 10, 'Sillä ne tosin ovat meitä kurittaneet harvoina päivinä luulonsa jälkeen; mutta tämä meidän tarpeeksemme, että me hänen pyhyytensä saisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 11, 'Mutta koska kaikkinainen rangaistus käsissä on, niin ei se näy meille iloksi, vaan murheeksi; mutta sitte antaa hän rauhallisen vanhurskauden hedelmän niille, jotka siinä harjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 12, 'Sentähden ojentakaat vaipuneet kätenne ja väsyneet polvenne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 13, 'Ja astukaat vilpittömät askeleet jaloillanne, ettei joku kompastuisi niinkuin ontuva, vaan paljoa enemmin terveeksi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 14, 'Noudattakaat rauhaa kaikkein kanssa ja pyhyyttä, paitsi jota ei yksikään saa Herraa nähdä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 15, 'Ja ottakaat vaari, ettei joku Jumalan armosta tulisi pois, ettei joskus kasvaisi joku karvas juuri jotakuta vastahakoisuutta tekemään ja monta sen kautta tulisi saastutetuksi;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 16, 'Ettei joku olisi huorintekiä eli jumalatoin niinkuin Esau, joka yhden atrian tähden myi pois esikoisuutensa oikeuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 17, 'Sillä te tiedätte, että kuin hän sitte tahtoi periä siunausta, tuli hän hyljätyksi; sillä ei hän löytänyt yhtään parannuksen siaa, vaikka hän sitä kyyneleillä etsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 18, 'Sillä ette ole käyneet sen vuoren tykö, johon ei ruveta saa, ja joka tulesta paloi, ette myös käyneet siihen synkeyteen ja pimeyteen, ja sen hirmuisen ilman tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 19, 'Sen basunan kajauksen ja sanain äänen tykö, josta ne, jotka sen kuulivat, rukoilivat, ettei se sana pitänyt heille sanottaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 20, 'Sillä ei he voineet kärsiä niitä, mitkä siinä sanottiin, ja jos joku peto siihen vuoreen sattui, niin se piti kivitettämän eli nuolella ammuttaman lävitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 21, 'Niin hirmuinen sen näky oli, että Moseskin sanoi: minä olen hämmästyksissä ja vapisen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 22, 'Vaan te olette käyneet Zionin vuoren tykö, ja elävän Jumalan kaupungin, taivaallisen Jerusalemin, ja monen tuhannen enkelitten joukon tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 23, 'Yhteisen kokouksen ja esikoisten seurakunnan tykö, jotka taivaissa kirjoitetut ovat, ja Jumalan, kaikkein tuomarin tykö ja täydellisten vanhurskasten henkein tykö,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 24, 'Ja uuden Testamentin välimiehen Jesuksen tykö, ja priiskotusveren tykö, joka parempia puhuu kuin Abelin (veri).');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 25, 'Katsokaat, ettette häntä kiellä pois, joka puhuu; sillä jos ei ne paeta saaneet, jotka kielsivät sen, joka maan päällä käskyn antoi, paljoa vähemmin me, jos me sitä pyydämme karttaa, joka taivaasta puhuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 26, 'Jonka ääni silloin maata järisti; mutta nyt hän lupaa ja sanoo: vielä minä nytkin kerran tahdon järistää, en ainoastansa maata, mutta myös taivasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 27, 'Mutta kuin hän sanoo: vielä kerran, tahtoo hän osoittaa, että järiseväiset pitää muutettaman niinkuin ne, jotka rakennetut ovat, että järisemättömät pysyisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 28, 'Sentähden saamme me sen valtakunnan, joka ei järistä taida, meillä on armo, jonka kautta me Jumalaa palvelemme, hänen mielensä nouteeksi, siveydellä ja pelvolla');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 29, 'Sillä meidän Jumalamme on kuluttavainen tuli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 1, 'Pysykäät vahvana veljellisessä rakkaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 2, 'Huoneesen ottamista älkäät unohtako; sillä sen kautta ovat muutamat tietämättä enkeleitäkin huoneeseensa ottaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 3, 'Muistakaat sidotuita, niin kuin te heidän kanssansa sidotut olisitte, ja niitä, jotka murhetta kärsivät, niinkuin te itse vielä lihassa olisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 4, 'Aviokäsky pitää kunniallisesti kaikkein seassa pidettämän ja aviovuode saastatoinna; mutta huorintekiät ja salavuoteiset Jumala tuomitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 5, 'Teidän menonne olkoon ilman ahneutta, ja tyytyvät niihin, mitkä teillä on; sillä hän on sanonut: en suinkaan minä sinua anna ylön, enkä ikänä sinua hylkää;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 6, 'Niin että me hyvässä turvassa sanomme: Herra on minun auttajani, enkä minä pelkää, mitä ihminen minulle tekis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 7, 'Muistakaat teidän opettajianne, jotka teille Jumalan sanaa puhuneet ovat, joiden uskoa te seuratkaat, ja ottakaat vaari, millainen loppu heidän menollansa oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 8, 'Jesus Kristus sama eilen ja tänäpänä ja myös ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 9, 'Älkäät antako vietellä teitänne moninaisilla ja muukalaisilla opetuksilla; sillä se on hyvä, että sydän vahvistuu armolla ja ei rualla, joista ei ne mitään hyötyneet, jotka niissä vaelsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 10, 'Meillä on alttari, Josta ei ole niiden lupa syödä, jotka majassa palvelevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 11, 'Sillä joiden eläinten veren ylimmäinen pappi vie pyhään syntein edestä, niiden ruumis ulkona leiristä poltetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 12, 'Sentähden myös Jesus, että hän oli pyhittävä kansan omalla verellänsä, on ulkona portista kärsinyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 13, 'Niin menkäämme siis hänen tykönsä ulos leiristä, kantain hänen pilkkaansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 14, 'Sillä ei meillä tässä ole pysyväistä kaupunkia, vaan tulevaista me etsimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 15, 'Niin uhratkaamme siis aina Jumalalle kiitosuhri hänen kauttansa, se on: niiden huulten hedelmät, jotka hänen nimensä tunnustavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 16, 'Mutta älkäät hyvin tekemistä ja jakamista unohtako; sillä senkaltaiset uhrit kelpaavat Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 17, 'Olkaat teidän opettajillenne kuuliaiset ja seuratkaat heitä; sillä he valvovat teidän sieluanne niinkuin ne, jotka luvun niistä tekemän pitää; että he sen ilolla tekisivät ja ei huokauksella; sillä ei se ole teille hyödyllinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 18, 'Rukoilkaat meidän edestämme; sillä se on meidän uskalluksemme, että meillä on hyvä omatunto, ja että me ahkeroitsemme pitää hyvää menoa kaikkein seassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 19, 'Mutta päälliseksi minä neuvon teidän näitä tekemään, että minä sitä pikemmin teidän tykönne tulisin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 20, 'Mutta rauhan Jumala, joka on kuolleista jälleen tuottanut suuren lammaspaimenen, ijankaikkisen Testamentin veren kautta, meidän Herran Jesuksen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 21, 'Saattakoon teidät kaikessa hyvässä työssä toimellisiksi, tekemään hänen tahtoansa jaa tehköön teissä, mitä hänen edessänsä otollinen on, Jesuksen Kristuksen kautta, jolle olkoon kunnia ijankaikkisesta ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 22, 'Minä neuvon teitä, rakkaat veljet: ottakaat tämä neuvon sana hyväksi; sillä minä olen lyhykäisesti teille kirjoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 23, 'Tietäkäät, että meidän veljemme Timoteus on päässyt, jonka kanssa, jos hän pian tulee, minä tahdon teitä nähdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 24, 'Tervehtikäät kaikkia teidän opettajianne ja kaikkia pyhiä. Teitä tervehtivät veljet Italiasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 25, 'Armo olkoon kaikkein teidän kanssanne, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 1, 'Jakob, Jumalan ja Herran Jesuksen Kristuksen palvelia, kahdelletoistakymmenelle sukukunnalle, jotka hajalla ovat, toivottaa terveyttä!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 2, 'Minun rakkaat veljeni, pitäkäät se sulana riemuna, kuin te moninaisiin kiusauksiin lankeatte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 3, 'Tietäen, että teidän uskonne koettelemus vaikuttaa kärsivällisyyden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 4, 'Mutta olkoon kärsivällisyydellä täydellinen työ, että te täydelliset ja kokonaiset olisitte ja ei missään puuttuvaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 5, 'Mutta jos joltain teistä viisautta puuttuis, hän anokaan sitä Jumalalta, joka hänelle antaa yksinkertaisesti, ja ei soimaa, ja se hänelle annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 6, 'Mutta anokaan uskossa epäilemättä; sillä joka epäilee, se on meren aallon kaltainen, joka tuulelta ajetaan ja liikutetaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 7, 'Älkään se ihminen luulko jotakin Herralta saavansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 8, 'Epäileväinen mies horjuu kaikissa teissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 9, 'Mutta veli, joka nöyrä on, kehukaan korotuksestansa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 10, 'Ja taas, joka rikas on, (se kehukaan) alentamisestansa; sillä niinkuin ruohon kukoistus pitää hänen katooman pois.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 11, 'Sillä aurinko nousi helteen kanssa ja kuivasi ruohon, ja sen kukkanen varisi, ja hänen kauneutensa katosi; niin myös rikkaan pitää teissänsä lakastuman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 12, 'Autuas on se mies, joka kiusauksen kärsii; sillä koska hän koeteltu on, niin hänen pitää elämän kruunun saaman, jonka Herra niille luvannut on, jotka häntä rakastavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 13, 'Älkään kenkään sanoko, kuin häntä kiusataan, että hän Jumalalta kiusataan; sillä ei Jumala ole kiusaaja pahuuteen, ja ei hän ketään kiusaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 14, 'Vaan jokainen kiusataan, kuin hän omalta himoltansa vietellään ja houkutellaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 15, 'Sitte kuin himo on siittänyt, niin hän synnyttää synnin; mutta kuin synti täytetty on, niin se synnyttää kuoleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 16, 'Älkäät eksykö, minun rakkaat veljeni!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 17, 'Kaikkinainen hyvä anto ja kaikkinainen täydellinen lahja tulee ylhäältä valkeuden Isältä, jonka tykönä ei ole muutosta eikä valkeuden ja pimeyden vaihetusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 18, 'Hän on meidät synnyttänyt tahtonsa jälkeen totuuden sanalla, että me uutiset hänen luontokappaleistansa olisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 19, 'Sentähden, minun rakkaat veljeni, olkoon jokainen ihminen nopia kuulemaan, (mutta) hidas puhumaan, ja hidas vihaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 20, 'Sillä miehen viha ei tee Jumalan edessä sitä, mikä oikein on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 21, 'Sentähden pankaat pois kaikkinainen saastaisuus ja kaikkinainen pahuus, ja ottakaat sana siveydellä vastaan, joka teissä istutettu on ja voi teidän sielunne autuaaksi saattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 22, 'Mutta olkaat myös sanantekiät ja ei ainoastaan kuuliat, pettäin teitänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 23, 'Sillä jos joku on sanan kuulia ja ei tekiä, hän on sen miehen kaltainen, joka ruumiillisen kasvonsa peilissä kurkistelee,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 24, 'Ja sittekuin hän itsensä kurkistellut on, niin hän menee pois ja unohtaa kohta, millinen hän oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 25, 'Mutta joka katsoo vapauden täydelliseen lakiin ja pysyy, ja ei ole unohtava kuulia, vaan tekiä, se tulee hänen teossansa autuaaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 26, 'Mutta jos joku teistä näkyy jumalinen olevan, ja ei suista kieltänsä, vaan viettelee sydämensä, sen jumalanpalvelus on turha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 27, 'Se on Isälle ja Jumalalle puhdas ja saastatoin jumalanpalvelus: oppia orpoja ja leskiä heidän murheessansa, ja itsensä saastatoinna maailmassa pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 1, 'Rakkaat veljeni, älkäät muodonkatsomisessa pitäkö uskoa kunnian Herran Jesuksen Kristuksen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 2, 'Sillä jos teidän seurakuntaanne tulis joku mies, kantain kultasormusta, ja kiiltävällä vaatteella puetettu; ja tulis myös köyhä ryysyllä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 3, 'Ja te katsoisitte sitä, joka kiiltävissä vaatteissa on, ja sanoisitte hänelle: istu tässä hyvästi; ja sille köyhälle sanoisitte: seiso sinä siellä, taikka istu tässä minun jaloissani:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 4, 'Niin ette sitä oikein ajattele, vaan te tulette tuomariksi ja teette pahan eroituksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 5, 'Kuulkaat, rakkaat veljeni: eikö Jumala ole tämän maailman köyhiä valinnut, jotka uskossa rikkaat ja valtakunnan perilliset ovat, jonka hän lupasi niille, jotka häntä rakastavat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 6, 'Mutta te olette häväisseet köyhän. Eikö rikkaat ole väkivaltaiset teitä polkemaan ja vetämään teitä oikeuden eteen?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 7, 'Eikö he pilkkaa sitä hyvää nimeä, josta te nimitetyt olette?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 8, 'Jos te kuninkaallisen lain, Raamatun jälkeen, täytätte: rakasta lähimmäistäs niinkuin itsiäs, niin te hyvin teette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 9, 'Mutta jos te ihmisten muotoa katsotte, niin te syntiä teette ja rangaistaan lailta, niinkuin sen rikkojat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 10, 'Sillä jos joku koko lain pitää, ja rikkoo yhdessä, hän on vikapää kaikissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 11, 'Sillä se, joka sanoi: ei sinun pidä huorin tekemän, hän on myös sanonut: ei sinun pidä tappaman. Jos et sinä huorin tee, mutta tapat, niin sinä olet lainrikkojaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 12, 'Näin te puhukaat ja näin te tehkäät, niinkuin ne, jotka vapauden lain kautta pitää tuomittaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 13, 'Sillä armotoin tuomio pitää hänen päällensä tuleman, joka ei laupiutta tehnyt; ja laupius kehuu tuomiota vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 14, 'Mitä se auttaa, rakkaat veljeni, jos joku sanoo hänellänsä uskon olevan, ja ei hänellä kuitenkaan ole töitä? Taitaako usko hänen autuaaksi saattaa?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 15, 'Mutta jos veli taikka sisar alasti olis ja puuttuis jokapäiväistä ravintoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 16, 'Jos joku teistä heille sanois: menkäät rauhassa, lämmittäkäät ja ravitkaat teitänne; ja ette kuitenkaan anna heille mitään ruumiin tarvetta: mitä se heitä auttais?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 17, 'Näin myös usko, jos ei hänellä töitä ole, on kuollut itsessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 18, 'Mutta sanokaan joku: sinulla on usko, ja minulla on työt: osoita minulle sinun uskos sinun töilläs, niin minäkin tahdon minun uskoni osoittaa minun töilläni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 19, 'Sinä uskot, että yksi Jumala on, sen sinä oikein teet; perkeleet myös sen uskovat ja vapisevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 20, 'Mutta tahdotkos tietää, sinä turha ihminen, että usko ilman töitä kuollut on?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 21, 'Eikö Abraham, meidän isämme, töiden kautta vanhurskautetuksi osoitettu, kuin hän poikansa Isaakin alttarille uhrasi?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 22, 'Näetkös, että usko on myös vaikuttanut hänen töissänsä, ja että usko on töissä täydelliseksi tullut?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 23, 'Ja se Raamattu on täytetty, joka sanoo: Abraham uskoi Jumalan, ja se luettiin hänelle vanhurskaudeksi, ja hän kutsuttiin Jumalan ystäväksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 24, 'Niin te siis näette, että ihminen töistä vanhurskautetuksi osoitetaan ja ei ainoastansa uskosta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 25, 'Niin myös portto Rahab, eikö hän töiden kautta vanhurskautetuksi nähty, koska hän korjasi ne vakoojat ja toista tietä heidät päästi ulos?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 26, 'Sillä niinkuin ruumis ilman henkeä on kuollut, niin myös usko on ilman töitä kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 1, 'Älkäät, rakkaat veljeni, jokainen pyytäkö opettajana olla, tietäen, että me sitä suuremman tuomion saamme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 2, 'Sillä moninaisissa me kukin puutumme. Mutta joka ei puheessa lankee, se on täydellinen mies, joka voi myös koko ruumiinsa suistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 3, 'Katso, me panemme hevosten suuhun suitset, että he meitä kuulisivat, ja heidän koko ruumiinsa me käännämme ympäri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 4, 'Katso, laivat myös, ehkä kuinka suuret he ovat ja jaloilta tuulilta ajetaan, kuitenkin he käännetään ympäri vähällä perälaudalla, kuhunka se tahtoo, joka sitä hallitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 5, 'Niin myös kieli on piskuinen jäsen, ja kuitenkin suuria asioita toimittaa. Katso, vähä tuli, kuinka suuren metsän se sytyttää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 6, 'Ja kieli on myös tuli, maailma vääryyttä täynnänsä; niin on myös kieli meidän jäsentemme seassa, joka koko ruumiin saastuttaa, ja sytyttää kaiken meidän menomme, koska se helvetistä syttyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 7, 'Sillä kaikki luonto, sekä petoin että lintuin ja kärmetten ja merellisten, tehdään lakiaksi, ja on lakiaksi tehty inhimilliseltä luonnolta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 8, 'Mutta kieltä ei taida yksikään ihminen asettaa, sitä levotointa pahuutta, kuolettavaista myrkkyä täynnänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 9, 'Sen kautta me kiitämme Jumalaa ja Isää, ja sen kautta me myös kiroilemme ihmisiä, jotka Jumalan kuvan jälkeen luodut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 10, 'Yhdestä suusta kiitos ja kirous käy ulos. Ei se niin, rakkaat veljeni, oleman pidä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 11, 'Kuohuuko joku lähde yhdestä huovosta makiaa ja karvasta vettä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 12, 'Taitaako, rakkaat veljeni, fikunapuu kantaa öljyä, taikka viinapuu fikunia? Niin ei taida myös yksikään lähde suolaista ja makiaa vettä vuotaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 13, 'Kuka viisas ja taitava on teidän seassanne, se osoittakaan hyvällä menollansa työnsä viisauden siveydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 14, 'Mutta jos teillä on katkera kiivaus ja riita sydämessänne, niin älkäät kerskatko ja älkäät valehdelko totuutta vastaan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 15, 'Sillä ei se ole viisaus, joka ylhäältä tullut on, vaan maallinen, inhimillinen ja perkeleellinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 16, 'Sillä kussa kiivaus ja riita on, siellä on myös sekaseuraisuus ja kaikki paha meno.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 17, 'Mutta se viisaus, joka ylhäältä on, se on ensisti tosin puhdas, sitte rauhallinen, siviä, uskova, täynnä laupiutta ja hyviä hedelmiä, eriseuratoin ja ulkokullatoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 18, 'Mutta vanhurskauden hedelmä rauhassa kylvetään niille, jotka rauhan pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 1, 'Kusta sodat ja tappelukset tulevat teidän seassanne? Eikö siitä, (nimittäin) teidän himoistanne, jotka teidän jäsenissänne sotivat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 2, 'Te himoitsette, ja ette saa sillä mitään. Te kadehditte ja kiivaatte, ja ette sillä voita mitään. Te soditte ja tappelette, ja ei teillä mitään ole, ettette mitään anokaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 3, 'Te anotte, ja ette saa, että te kelvottomasti anotte, että te teidän himoissanne sen kuluttaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 4, 'Te huorintekiät ja huorat! ettekö te tiedä, että maailman ystävyys on viha Jumalaa vastaan? Joka siis tahtoo maailman ystävä olla, hän tulee Jumalan vihamieheksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 5, 'Eli luuletteko, että Raamattu sanoo turhaan: henki, joka meissä asuu, himoitsee kateutta vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 6, 'Ja antaa runsaasti armon; sentähden hän sanoo: Jumala seisoo ylpeitä vastaan, mutta nöyrille antaa hän armon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 7, 'Niin olkaat siis Jumalalle alamaiset, mutta vastaan seisokaat perkelettä, niin hän teistä pakenee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 8, 'Lähestykäät Jumalaa, niin hän lähestyy teitä. Puhdistakaat kätenne, te syntiset, ja peratkaat teidän sydämenne, te kaksimieliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 9, 'Olkaat surulliset, murehtikaat ja itkekäät. Teidän naurunne kääntyköön itkuksi ja ilonne murheeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 10, 'Nöyryyttäkäät teitänne Jumalan kasvoin edessä, niin hän teitä ylentää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 11, 'Älkäät toinen toistanne panetelko, rakkaat veljet: joka veljeänsä panettelee ja veljensä tuomitsee, se panettelee lakia ja tuomitsee lain. Mutta jos sinä tuomitset lain, niin et sinä ole lain tekiä vaan tuomari.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 12, 'Yksi on lain antaja, joka voi vapahtaa ja kadottaa. Kuka sinä olet, joka toista tuomitset?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 13, 'Nyt hyvin, te jotka sanotte: menkäämme tänäpänä taikka huomenna siihen eli siihen kaupunkiin, ja viettäkäämme siinä yksi vuosi, ja tehkäämme kauppaa ja voittakaamme,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 14, 'Jotka ette tiedä, mitä huomenna tapahtuu. Sillä mikä on teidän elämänne? Se on löyhkä, joka vähäksi (hetkeksi) näkyy, mutta sitte katoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 15, 'Mutta teidän pitää sanoman: jos Herra tahtoo, ja me elämme, niin me tätä taikka sitä tahdomme tehdä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 16, 'Mutta nyt te kerskaatte teidän ylpeydessänne. Kaikki senkaltainen kerskaus on paha.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 17, 'Sillä joka taitaa hyvää tehdä, ja ei tee, niin se on hänelle synniksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 1, 'Nyt hyvin, te rikkaat! itkekäät ja ulvokaat teidän viheliäisyyttänne, joka teidän päällenne tuleva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 2, 'Teidän rikkautenne ovat mädänneet, teidän vaatteenne ovat koidellut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 3, 'Teidän kultanne ja hopianne ovat ruostuneet, ja niiden ruoste pitää oleman teille todistukseksi, ja pitää syömän teidän lihanne niinkuin tuli. Te olette rikkauden koonneet teillenne viimeisinä päivinä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 4, 'Katso, työmiesten palkka, jotka teidän maakuntainne elon niittäneet ovat, joka petoksella teiltä pidetty on, huutaa, ja elonleikkaajain parut ja huudot ovat tulleet Herran Zebaotin korville:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 5, 'Te olette herkuissa eläneet maan päällä, ja olette teidän hekumanne pitäneet, ja teidän sydämenne syötelleet niinkuin teuraspäivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 6, 'Te olette tuominneet, te olette tappaneet vanhurskaan, joka ei ole teitä vastaan ollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 7, 'Niin olkaat siis kärsivälliset, rakkaat veljet, Herran tulemiseen asti. Katso, peltomies odottaa kallista maan hedelmää, ja on kärsivällinen siihenasti kuin hän saa varhaisen ja hiljaisen sateen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 8, 'Niin olkaat te myös kärsivälliset ja vahvistakaat sydämenne; sillä Herran tulemus lähestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 9, 'Älkäät huoatko, rakkaat veljet, toinen toistanne vastaan, ettette kadotetuksi tulisi. Katso, tuomari seisoo oven edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 10, 'Ottakaat, rakkaat veljeni, vaivan ja kärsivällisyyden esikuva niistä prophetaista, jotka Herran nimeen puhuneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 11, 'Katso, me sanomme ne autuaiksi, jotka kärsineet ovat. Jobin kärsivällisyyden te olette kuulleet ja Herran lopun te nähneet olette; sillä Herra on sangen laupias ja armollinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 12, 'Ennen kaikkia, rakkaat veljeni, älkäät vannoko, ei taivaan kautta eikä maan, ei myös yhtään muuta valaa; mutta olkoon teidän puheenne niin kuin niin on, ja se olkoon ei kuin ei on, ettette ulkokullaisuuteen lankeaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 13, 'Jos joku kärsii vaivaa teidän seassanne, se rukoilkaan, jos joku on hyvällä mielellä, se veisatkaan virsiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 14, 'Jos joku sairastaa teidän seassanne, hän kutsukaan tykönsä seurakunnan papit, ja ne rukoilkaan hänen edestänsä, voidellen häntä öljyllä Herran nimeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 15, 'Ja uskon rukous parantaa sairaan, ja Herra ojentaa hänen, ja jos hän on syntiä tehnyt, niin ne hänelle anteeksi annetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 16, 'Tunnustakaat toinen toisellenne teidän rikoksenne ja rukoilkaat toinen toisenne edestä, että te terveeksi tulisitte. Vanhurskaan rukous voi paljo, koska se totinen on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 17, 'Elias oli ihminen, niissä haluissa vikapää kuin mekin ja hän rukoili rukouksella, ettei pitänyt sataman, ja ei satanutkaan maan päällä kolmena vuotena ja kuutena kuukautena,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 18, 'Ja hän taas rukoili, ja taivas antoi sateen, ja maa kasvoi hedelmänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 19, 'Rakkaat veljeni, jos joku teistä eksyis totuudesta ja joku palauttais hänen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 20, 'Se tietäkään, että joka syntisen palauttaa tiensä erehdyksestä, se vapahtaa sielun kuolemasta ja peittää syntein paljouden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 1, 'Pietari, Jesuksen Kristuksen apostoli, valituille muukalaisille, hajalla asuvaisille Pontossa, Galatiassa, Kappadokiassa, Asiassa ja Bityniassa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 2, 'Isän Jumalan aivoituksen jälkeen Hengen pyhittämisen kautta, kuuliaisuuteen ja Jesuksen Kristuksen veren priiskottamiseen: armo ja rauha lisääntyköön teille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 3, 'Kiitetty olkoon Jumala ja meidän Herran Jesuksen Kristuksen Isä, joka meitä suuresta laupiudestansa on synnyttänyt jälleen elävään toivoon, Jesuksen Kristuksen ylösnousemisen kautta kuolleista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 4, 'Katoomattomaan ja saastuttamattomaan ja turmelemattomaan perintöön, joka taivaassa tähdelle pantu on teitä varten,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 5, 'Jotka Jumalan väellä uskon kautta autuuteen kätketään, joka sitä varten valmistettu on, että se viimeisellä ajalla ilmi tulis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 6, 'Jossa te saatte iloita, te, joita nyt vähän aikaa, (jos tarvitaan,) moninaisilla kiusauksilla vaivataan:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 7, 'Että teidän uskonne koettelemus paljoa kalliimmaksi löydettäisiin kuin katoova kulta, joka tulessa koetellaan, kiitokseksi, ylistykseksi ja kunniaksi, koska Jesus Kristus ilmaantuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 8, 'Jota te rakastatte, vaikka ette häntä näe, jonka päälle te myös uskotte, ehkette nyt häntä näe, niin te kuitenkin saatte iloita sanomattomalla ja kunniallisella ilolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 9, 'Ja käsitätte teidän uskonne lopun, sieluin autuuden,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 10, 'Jota autuutta prophetat ovat etsineet ja tutkineet, jotka teille tulevaista armoa ennustaneet ovat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 11, 'Ja ovat tutkineet, millä taikka minkäkaltaisella ajalla Kristuksen Henki, joka heissä oli, ilmoitti, joka oli jo ennen todistanut niistä vaivoista, jotka Kristuksessa ovat, ja siitä kunniasta, joka niiden jälkeen tapahtuva oli:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 12, 'Joille se ilmoitettu oli, sillä ei he itseänsä sen kautta palvelleet, vaan meitä, jotka nyt teille niiden kautta julistetut ovat, jotka teille evankeliumia saarnanneet ovat Pyhän Hengen kautta, taivaasta lähetetyn, jota enkelit nähdä himoitsevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 13, 'Sentähden vyöttäkäät mielenne kupeet, olkaa raittiit, pankaat täydellinen toivonne siihen armoon, joka teille Jesuksen Kristuksen ilmestyksen kautta taritaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 14, 'Niinkuin kuuliaiset lapset, ei asettaen teitänne niinkuin ennen, kuin te teidän tyhmyydessänne himoissa elitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 15, 'Vaan sen jälkeen, joka teitä kutsunut on, ja on pyhä, olkaat te myös pyhät kaikissa teidän menoissanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 16, 'Sillä kirjoitettu on: teidän pitää pyhät oleman, sillä minä olen pyhä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 17, 'Ja jos te rukoilette sitä Isää, joka tuomitsee kunkin töidensä jälkeen ilman ihmisten muodon katsomista, niin katsokaat, että te teidän viipymisenne ajan pelvossa vaeltaisitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 18, 'Tietäen, ettette ole katoovaisella hopialla eli kullalla lunastetut teidän turhasta menostanne, jonka te isäin säädystä saitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 19, 'Vaan kalliilla Kristuksen verellä, niinkuin viattoman ja puhtaan Karitsan;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 20, 'Joka tosin jo ennen oli aivottu kuin maailman perustus pantu oli, mutta ilmoitettu viimeisinä aikoina teidän tähtenne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 21, 'Jotka hänen kauttansa uskotte Jumalan päälle, joka hänen kuolleista herätti ja hänelle kunnian antoi, että teillä olis usko ja toivo Jumalan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 22, 'Ja tehkäät puhtaaksi teidän sielunne totuuden kuuliaisuudessa, Hengen kautta, veljelliseen rakkauteen, joka vilpitöin olis, ja olkaat keskenänne palavaisessa rakkaudessa puhtaasta sydämestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 23, 'Niinkuin ne, jotka jälleen syntyneet ovat, ei katoovaisesta, vaan katoomattomasta siemenestä, elävästä Jumalan sanasta, joka ijankaikkisesti pysyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 24, 'Sillä kaikki liha on niinkuin ruoho ja kaikki ihmisen kunnia niinkuin ruohon kukkanen. Ruoho on kuivunut, ja sen kukkanen lakastunut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 25, 'Mutta Herran sana pysyy ijankaikkisesti, ja se on se sana, joka teidän seassanne saarnattu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 1, 'Niin pankaat pois nyt kaikki pahuus ja kaikki petos, ja ulkokullaisuus ja kateus, ja kaikki panetus,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 2, 'Ja halaitkaat sitä terveellistä sanan rieskaa, niinkuin äsken-syntyneet lapsukaiset, että te sen kautta kasvaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 3, 'Jos te muutoin maistaneet olette, että Herra on suloinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 4, 'Jonka tykö te myös tulleet olette niinkuin elävän kiven tykö, joka kyllä ihmisiltä hyljätty on, mutta Jumalalta valittu, kallis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 5, 'Ja myös te, niinkuin elävät kivet, rakentakaat teitänne hengelliseksi huoneeksi ja pyhäksi pappeudeksi uhraamaan hengellisiä uhreja, jotka Jumalalle Jesuksen Kristuksen kautta otolliset ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 6, 'Sentähden on myös Raamatussa: katso, minä panen Zioniin valitun kalliin kulmakiven: joka uskoo hänen päällensä, ei hän suinkaan tule häpiään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 7, 'Teille siis, jotka nyt uskotte, on hän kallis; mutta uskottomille on se kivi, jonka rakentajat hyljänneet ovat, kulmakiveksi tullut, ja loukkauskiveksi, ja pahennuksen kallioksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 8, 'Nimittäin niille, jotka itsensä sanaan loukkaavat, ja ei sitä usko, johonka he myös asetetut olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 9, 'Mutta te olette valittu suku, kuninkaallinen pappeus, pyhä kansa, omaisuuden kansa, ilmoittamaan sen voimaa, joka teitä pimeydestä ihmeelliseen valkeuteensa kutsunut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 10, 'Jotka ette muinen kansa olleet, mutta nyt olette Jumalan kansa: jotka ette muinen armossa olleet, mutta nyt te armossa olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 11, 'Rakkaat veljet! minä neuvon teitä, niinkuin outoja ja muukalaisia: välttäkäät lihallisia himoja, jotka sotivat sielua vastaan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 12, 'Ja pitäkäät hyvä meno pakanain seassa, että ne, jotka teitä panettelevat niinkuin pahointekijöitä, näkisivät teidän hyvistä töistänne ja kiittäisivät Jumalaa etsikon päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 13, 'Sentähden olkaat alamaiset kaikelle inhimilliselle säädylle Herran tähden, olisko se kuninkaalle, niinkuin ylimmäiselle,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 14, 'Taikka päämiehille, niinkuin niille, jotka häneltä lähetetyt ovat pahointekiöille rangaistukseksi ja hurskaille kiitokseksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 15, 'Sillä se on Jumalan tahto, että te hyvällä työllä tukitsette hulluin ja tyhmäin ihmisten suun,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 16, 'Niinkuin vapaat, ja ei niin, että se vapaus olis niinkuin pahuuden peite, vaan niinkuin Jumalan palveliat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 17, 'Olkaat kunnialliset jokaista kohtaan, rakastakaat veljiä, peljätkäät Jumalaa, kunnioittakaat kuningasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 18, 'Te palveliat! olkaat alamaiset kaikella pelvolla teidän isännillenne, ei ainoastaan hyville ja siveille, vaan myös tuimille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 19, 'Sillä se on armo, jos joku omantuntonsa tähden Jumalan tykö vaivaa kärsii, ja syyttömästi kärsii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 20, 'Sillä mikä kiitos se on, jos te pahain tekoinne tähden piestään, ja te kärsitte? Mutta kuin te hyvin teette ja kuitenkin vaivataan, ja te sen kärsitte, niin se on armo Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 21, 'Sillä sitä varten olette te kutsutut, että Kristus myös kärsi meidän edestämme ja jätti meille esikuvan, että teidän pitää hänen askeleitansa noudattaman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 22, 'Joka ei yhtään syntiä tehnyt eikä yhtään petosta ole hänen suustansa löydetty,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 23, 'Joka ei kironnut, kuin häntä kirottiin, ei uhannut, kuin hän kärsi; mutta antoi hänelle koston, joka oikein tuomitsee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 24, 'Joka meidän syntimme itse uhrasi omassa ruumiissansa puun päällä, että me synneistä pois kuolleet eläisimme vanhurskaudelle; jonka haavain kautta te olette terveiksi tulleet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 25, 'Sillä te olitte niinkuin eksyväiset lampaat, vaan nyt te olette palanneet teidän sieluinne paimenen ja piispan tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 1, 'Niin olkaan vaimot myös miehillensä alamaiset, että nekin, jotka ei sanaa usko, vaimoin tavoista ilman sanaa voitetuksi tulisivat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 2, 'Kuin he teidän puhtaan menonne näkevät pelvossa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 3, 'Joidenka kaunistus ei pidä oleman ulkonaisissa hiusten palmikoissa ja kullan ympäri-ripustamisessa eli vaatteen puvussa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 4, 'Vaan salainen ihminen ilman vikaa sydämessä, lakialla ja hiljaisella hengellä, se on kallis Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 5, 'Sillä näin ovat pyhätkin vaimot muinen itsensä kaunistaneet, jotka toivonsa panivat Jumalan päälle ja olivat miehillensä alamaiset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 6, 'Niinkuin Sara oli Abrahamille kuuliainen ja kutsui hänen herraksi, jonka tyttäriksi te tulleet olette, jos te hyvin teette ja pelkäämättä olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 7, 'Te, miehet, myös asukaat heidän kanssansa taidolla ja antakaat vaimolliselle niinkuin heikommalle astialle hänen kunniansa, niinkuin myös elämän armon kanssaperillisille, ettei teidän rukouksenne estetyiksi tulisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 8, 'Mutta viimein olkaat kaikki yksimieliset, ynnä kärsiväiset, pitäin veljellistä rakkautta keskenänne, laupiaat, ystävälliset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 9, 'Ei kostain pahaa pahalla, eikä kirouksella kirousta, vaan paremmin siunatkaat, tietäen, että te olette kutsutut siunausta perimään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 10, 'Sillä joka elää tahtoo ja hyviä päiviä nähdä, hän hillitkään kielensä pahuudesta ja huulensa vilppiä puhumasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 11, 'Hän välttäkään pahaa ja tehkään hyvää, etsikään rauhaa ja noudattamaan sitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 12, 'Sillä Herran silmät ovat vanhurskasten päälle ja hänen korvansa heidän rukouksissansa; mutta Herran kasvot ovat pahointekiöitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 13, 'Ja kuka on, joka taitaa teitä vahingoittaa, jos te hyvää pyydätte?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 14, 'Ja jos te vielä oikeudenkin tähden kärsisitte, niin te kuitenkin autuaat olette; mutta älkäät peljätkö heidän vaatimistansa, alkäät myös heitä hämmästykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 15, 'Mutta pyhittäkäät Herra Jumala teidän sydämissänne. Olkaat myös aina valmiit vastaamaan jokaista, joka teidän toivonne perustusta tutkistelee, joka teissä on, hiljaisuudella ja pelvolla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 16, 'Ja pitäkäät hyvä omatunto, että ne, jotka teitä panettelevat niinkuin pahantekiöitä, häpeäisivät, että he ovat häväisseet teidän hyvän menonne Kristuksessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 17, 'Sillä se on parempi, jos Jumalan tahto niin on, että te hyvän työn tähden kärsitte kuin pahan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 18, 'Sillä Kristus myös kerran kärsi meidän synteimme tähden, hurskas vääräin edestä, että hän meitä Jumalalle uhrais: lihan kautta tosin kuoletettu, mutta Hengen kautta eläväksi tehty,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 19, 'Jossa hän myös meni pois ja saarnasi hengille vankeudessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 20, 'Jotka ei muinen uskoneet, kuin Jumala kerran Noan aikana odotti ja kärsiväinen oli, kuin arkki valmistettiin, jossa harvat (se on: kahdeksan sielua) veden kautta päästetyksi tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 21, 'Se nyt meitäkin kasteessa autuaaksi tekee, joka sitä aavisti (ei että lihan saastaisuudet pannaan pois, vaan että se on hyvän omantunnon liitto Jumalan tykönä) Jesuksen Kristuksen ylösnousemisen kautta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 22, 'Joka on Jumalan oikialle kädelle, taivaasen mennyt, ja hänelle ovat enkelit ja vallat ja voimat alamaiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 1, 'Että siis Kristus lihassa meidän edestämme on kärsinyt, niin te myös varustakaat teitänne sillä mielellä; sillä joka lihassa kärsii, se lakkaa synnistä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 2, 'Ettei hän enään sitä aikaa, jonka hän lihassa edespäin on, ihmisten himon jälkeen, vaan Jumalan tahdon jälkeen eläisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 3, 'Sillä kyllä siinä on, että me edesmenneen ajan elämästä kulutimme pakanain mielen jälkeen, vaeltaissamme irstaudessa, himoissa, juopumisessa, ylönsuömisessä, ylönjuomisessa ja hirmuisissa epäjumalan palveluksissa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 4, 'He oudoksuvat, ettette heidän kanssansa juokse samaan säädyttömän hekuman menoon, ja pilkkaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 5, 'Niiden pitää luvun tekemän hänelle, joka on valmis tuomitsemaan eläviä ja kuolleita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 6, 'Sillä sitä varten evankeliumi kuolleillekin saarnattu on, että he kyllä tuomittaisiin ihmisten jälkeen lihassa, mutta Jumalan jälkeen eläisivät hengessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 7, 'Mutta nyt kaikkein loppu lähestyy. Niin olkaat siis raittiit ja valppaat rukoilemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 8, 'Mutta ennen kaikkia pitäkäät keskenänne palava rakkaus; sillä rakkaus peittää paljon rikoksia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 9, 'Olkaat vierasten holhoojat keskenänne napisematta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 10, 'Ja palvelkaat toinen toistanne, jokainen sillä lahjalla, minkä hän saanut on, niinkuin hyvät Jumalan moninaisen armon huoneenhaltiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 11, 'Jos joku puhuu, hän puhukaan niinkuin Jumalan sanoja: jos jollakin on joku virka, hän tehkään niinkuin siitä voimasta, jonka Jumala antaa, että Jumala kaikissa Jesuksen Kristuksen kautta kunnioitettaisiin, jolla on kunnia ja valta ijankaikkisesta ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 12, 'Minun rakkaani! älkäät oudoksuko sitä hellettä, joka teille tapahtuu, että teitä koetellaan, niinkuin teille jotakin outoa tapahtuis;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 13, 'Vaan iloitkaat, että te Kristuksen kanssa kärsitte, että tekin ajallansa hänen kunniansa ilmestyksessä iloitsisitte ja riemuitsisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 14, 'Autuaat olette te, jos teitä Kristuksen nimen tähden pilkataan; sillä se Henki, joka on kunnian ja Jumalan Henki, lepää teidän päällänne: heiltä hän pilkataan, vaan teiltä hän kunnioitetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 15, 'Älkään yksikään teistä kärsikö niinkuin murhaaja eli varas, taikka pahantekiä, eli niinkuin se, joka toisen virkaan rupee;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 16, 'Mutta jos hän kärsii niinkuin kristitty, älköön hävetkö, vaan kiittäkään Jumalaa sen osan tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 17, 'Sillä aika on, että tuomion pitää Jumalan huoneesta alkaman. Mutta jos se ensin meistä alkaa, minkäs lopun ne saavat, jotka ei Jumalan evankeliumia usko?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 18, 'Ja jos hurskas tuskalla vapaaksi tulee, kussa sitte jumalatoin ja syntinen näkyy?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 19, 'Sentähden ne, jotka Jumalan tahdon jälkeen kärsivät, antakaan sielunsa niinkuin uskolliselle Luojalle hyvissä töissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 1, 'Vanhoja pappeja teidän seassanne minä neuvon, joka myös pappi olen ja Kristuksen kärsimisten tunnustaja ja osallinen siitä kunniasta, joka ilmestyvä on:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 2, 'Kaitkaat Kristuksen laumaa, joka teidän hallussanne on, ja pitäkäät siitä vaari, ei vaaditut, vaan hyvällä mielellä, ei turhan voiton tähden, vaan hyvästä tahdosta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 3, 'Ei myös niinkuin herrat kansansa päälle, vaan olkaat laumalle esikuvaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 4, 'Niin te, ylimmäisen Paimenen ilmestyessä, katoomattoman kunnian kruunun saatte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 5, 'Niin myös te nuoret, olkaat vanhoille alamaiset ja olkaat kaikki toinen toisellenne alamaiset, ja pitäkäät teitänne kiintiästi nöyryyteen; sillä Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 6, 'Nöyryyttäkäät siis teitänne Jumalan väkevän käden alle, että hän teitä ajallansa korottais.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 7, 'Kaikki teidän murheenne pankaat hänen päällensä; sillä hän pitää murheen teistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 8, 'Olkaat raittiit, valvokaat; sillä teidän vihollisenne perkele käy ympäri niinkuin kiljuva jalopeura, ja etsii, kenen hän nielis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 9, 'Sitä te seisokaat vastaan, vahvat uskossa, tietäen, että ne vaivat tapahtuvat teidän veljillennekin maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 10, 'Mutta Jumala, jolta kaikki armo tulee, joka meitä on kutsunut ijankaikkiseen kunniaansa Kristuksessa Jesuksessa, teitä, jotka vähän aikaa kärsitte, valmistaa, vahvistaa, tukee, perustaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 11, 'Sille olkoon kunnia ja väkevyys ijankaikkisesta ijankaikkiseen! amen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 12, 'Silvanuksen, teidän uskollisen veljenne kanssa (niinkuin minä luulen) olen minä teidän tykönne harvoilla sanoilla kirjoittanut, neuvoen ja tunnustain, että tämä on se oikia Jumalan armo, jossa te olette.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 13, 'Teitä tervehtivät valitut Babyloniassa ja minun poikani Markus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 14, 'Tervehtikäät toinen toistanne rakkauden suun-annolla. Rauha olkoon teille kaikille, jotka Kristuksessa Jesuksessa olette, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 1, 'Simon Pietari, Jesuksen Kristuksen palvelia ja apostoli, niille, jotka ovat saaneet meidän kanssamme yhdenkaltaisen kalliin uskon vanhurskaudessa, jonka meidän Jumalamme ja Vapahtajamme Jesus Kristus antaa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 2, 'Armo ja rauha lisääntyköön teille, Jumalan ja meidän Herran Jesuksen Kristuksen tuntemisen kautta!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 3, 'Että hänen jumalallinen voimansa meille kaikkinaiset (jotka elämään ja jumaliseen menoon sopivat) on lahjoittanut hänen tuntemisensa kautta, joka meitä kunniaan ja avuun kutsunut on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 4, 'Joidenka kautta meille ne suurimmat ja kalliit lupaukset lahjoitetut ovat, että te niiden kautta Jumalan luonnosta osalliseksi tulisitte, jos te katoovaisen maailman himon vältätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 5, 'Niin ahkeroitkaat kaikella vireydellä teidän uskonne avua osoittamaan, ja avussa tointa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 6, 'Ja toimessa kohtuullisuutta, ja kohtuullisuudessa kärsivällisyyttä, ja kärsivällisyydessä jumalisuutta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 7, 'Ja jumalisuudessa veljellistä rakkautta, ja veljellisessä rakkaudessa yhteistä rakkautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 8, 'Sillä koska nämät täydellisesti teissä ovat, niin ei he teitä salli löydettää joutilaina eli hedelmättöminä meidän Herran Jesuksen Kristuksen tuntemisessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 9, 'Mutta jolla ei näitä ole, hän on sokia, ja ei näe mitään kaukaa, ja on unohtanut itsensä olleen puhdistetun entisistä synneistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 10, 'Sentähden, rakkaat veljet, ahkeroitkaat paremmin sitä, että te teidän kutsumisenne ja valitsemisenne vahvistaisitte; sillä jos te sen teette, niin ette suinkaan koskaan kompastu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 11, 'Sillä teidän sallitaan alttiisti käydä sisälle meidän Herran ja Vapahtajan Jesuksen Kristuksen ijankaikkiseen valtakuntaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 12, 'Sentähden en minä tahdo unohtaa teille aina näistä muistuttaa, vaikka te tiedätte ja vahvistetut olette tässä nykyisessä totuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 13, 'Sillä minä arvaan sen kohtuulliseksi, niinkauvan kuin minä tässä majassa olen, herättää teitä ja muistuttaa teille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 14, 'Sillä minä tiedän, että minun pitää pian tämän minun majani paneman pois, niinkuin meidän Herra Jesus Kristus minulle ilmoitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 15, 'Mutta minä tahdon myös aina ahkeroida, että te nämät minun lähtemiseni jälkeen muistossa pidätte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 16, 'Sillä emmepä me ole kavaloita juttuja noudatelleet, teille tiettäväksi tehdessämme meidän Herran Jesuksen Kristuksen voimaa ja tulemista; vaan me olemme itse nähneet hänen suuren kunniansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 17, 'Kuin hän Isältä Jumalalta sai kunnian ja ylistyksen, äänen kautta, joka hänelle näin siltä suurelta kunnialta tapahtui: tämä on minun rakas Poikani, johon minä mielistyin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 18, 'Ja tämän äänen me kuulimme tulevan taivaasta, kuin me pyhällä vuorella hänen kanssansa olimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 19, 'Ja meillä on vahva prophetallinen sana, ja te teette hyvin, että te siitä vaarin otatte niinkuin kynttilästä, joka pimeässä valistaa, niinkauvan kuin päivä valkenee ja kointähti koittaa teidän sydämissänne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 20, 'Ja se tulee teidän ensin tietää, ettei yksikään prophetia Raamatussa tapahdu omasta selityksestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 21, 'Sillä ei yksikään prophetia ole vielä ihmisen tahdosta tuotu edes; vaan pyhät Jumalan ihmiset ovat puhuneet, vaikutetut Pyhältä Hengeltä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 1, 'Niin oli myös vääriä prophetaita kansan seassa, niinkuin teidänkin sekaanne vääriä opettajia tulee, jotka vahingolliset eriseurat tuovat ja kieltävät sen Herran, joka heidät ostanut on, saattain itsellensä nopian kadotuksen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 2, 'Ja moni noudattaa heidän kadotustansa, joiden kautta totuuden tie pilkataan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 3, 'Ja ahneudesta ajatelluilla sanoilla pitää heidän teitä kauppaaman, joiden tuomio ei silleen kauvan viivy, eikä heidän kadotuksensa makaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 4, 'Sillä jos ei Jumala armahtanut niitä enkeleitä, jotka syntiä tekivät, vaan on pimeyden kahleilla helvettiin syössyt, ja antoi ylön heidät tuomioon kätkettää,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 5, 'Ja ei ole armahtanut entistä maailmaa, vaan vapahti Noan vanhurskauden saarnaajan itse kahdeksantena, ja toi vedenpaisumisen jumalattomain maailman päälle;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 6, 'Ja on ne kaupungit Sodoman ja Gomorran tuhaksi tehnyt, kukistanut ja kadottanut, ja teki ne jumalattomille peljästykseksi, jotka sitte tulevat olivat;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 7, 'Ja on pelastanut hurskaan Lotin, joka riettaisilta ihmisiltä heidän haureutensa menolla vaivattiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 8, '(Sillä hän oli hurskas ja asui heidän seassansa, ja kuitenkin senkaltaista piti näkemän ja kuuleman, he vaivasivat sitä hurskasta sielua joka päivä väärillä töillänsä;)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 9, 'Niin Herra tietää jumaliset kiusauksista pelastaa, mutta väärät kätkeä tuomiopäivään asti vaivattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 10, 'Mutta enimmästi ne, jotka lihan jälkeen saastaisessa himossa vaeltavat ja herrauden katsovat ylön, rohkiat, itsestänsä paljon pitäväiset, jotka ei pelkää valtojakaan pilkata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 11, 'Vaikka ne enkelit, jotka väessä ja voimassa suuremmat ovat, ei kärsi heitä vastaan Herran tykönä pilkallista tuomiota,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 12, 'Kuitenkin he niinkuin järjettömät luontokappaleet, jotka luonnostansa kiiniotettaa ja teurastettaa tehdyt ovat, pilkkaavat niitä, joita ei he ymmärrä, ja hukkuvat turmeluksessansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 13, 'Ja saavat vääryyden palkan, pitäin sen hekumana, että he ajallisissa herkuissa elävät, he ovat ilkeydet ja pilkat, kerskaavat heidän petoksistansa, nautiten herkkuja teidän kanssanne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 14, 'Heillä on silmät huoruutta täynnä ja ei taida synnistä lakata, he houkuttelevat tykönsä horjuvat sielut, he ovat sydämensä ahneudessa harjaantuneet, kirottu kansa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 15, 'Jotka antoivat ylön oikian tien ja eksyivät, he noudattavat Balaamin, Bosorin pojan, tietä, joka vääryyden palkkaa rakasti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 16, 'Mutta hän rangaistiin vääryydestänsä; mykkä työjuhta puhui ihmisen äänellä, ja esti prophetan hulluuden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 17, 'Ne ovat vedettömät lähteet ja pilvet, jotka tuulispäältä ympäri ajetaan, joille on kätketty synkiä pimeys ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 18, 'Sillä he puhuvat röyhkeitä sanoja, jotka turhat ovat, ja yllyttävät tavattomuuden kautta lihallisiin himoihin niitä, jotka tosin ovat niitä välttäneet, kuin eksyksissä vaeltavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 19, 'Ja lupaavat heille vapauden, vaikka he itse turmeluksen palveliat ovat; sillä jolta joku voitetaan, sen palvelia hän myös on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 20, 'Ja sittenkuin he ovat paenneet maailman saastaisuudesta Herran ja Vapahtajan Jesuksen Kristuksen tuntemiseen, niin he kuitenkin heitänsä niihin käärivät, ja voitetaan, ja on heille viimeinen pahemmaksi tullut kuin ensimäinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 21, 'Sillä se olis heille parempi ollut, ettei he vanhurskauden tietä tunteneetkaan olisi, kuin että he tunsivat sen ja poikkesivat pois pyhästä käskystä, joka heille annettu oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 22, 'Niille on tapahtunut se totinen sananlasku: koira syö oksennuksensa, ja pesty sika rypee rapakossa jälleen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 1, 'Tämän nyt toisen lähetyskirjan minä teille, minun rakkaani, kirjoitan, jolla minä herätän ja neuvon teidän vakaata mieltänne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 2, 'Että te muistaisitte ne sanat, jotka ennen pyhiltä prophetailta sanotut ovat, ja myös meidän käskymme, jotka olemme Herran ja Vapahtajan apostolit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 3, 'Ja tietäkäät se ensin, että viimeisinä päivinä tulevat pilkkaajat, jotka oman himonsa jälkeen vaeltavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 4, 'Ja sanovat: kussa on lupaus hänen tulemisestansa? Sillä siitä päivästä, kuin isät ovat nukkuneet, pysyvät kaikki niinkuin ne luonnon alusta olleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 5, 'Mutta tietäen ei he tahdo tietää, että taivaat muinen olivat, ja maa vedestä, joka vedessä Jumalan sanan kautta seisoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 6, 'Kuitenkin siihen aikaan se maailma niiden kautta vedenpaisumisella hukkui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 7, 'Niin myös ne taivaat ja maa, jotka nyt ovat, hänen sanansa kautta säästetään tulen varaksi tuomiopäivään asti, jona jumalattomat ihmiset kadotetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 8, 'Mutta tätä yhtä ei pidä teiltä salattaman, minun rakkaani: yksi päivä on Herran edessä niinkuin tuhannen ajastaikaa, ja tuhannen ajastaikaa niinkuin yksi päivä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 9, 'Ei Herra viivytä lupaustansa, (niinkuin muutamat sen viipyvän luulevat,) vaan hän on meidän kanssamme kärsiväinen, ja ei tahdo, että jonkun pitäis hukkuman, vaan että jokainen itsensä parannukseen kääntäis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 10, 'Mutta Herran päivä on tuleva niinkuin varas yöllä, ja silloin taivaat suurella pauhinalla menevät pois, mutta elementit pitää palavuudesta sulaman, ja maa, ja rakennukset, jotka hänessä ovat, pitää palaman ylös.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 11, 'Että kaikki nämät pitää katooman, minkäkaltaiset tulee teidän silloin olla pyhissä menoissa ja jumalisuudessa:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 12, 'Niin että te odotatte ja ikävöitsette Jumalan päivän tulemista, jona taivaat tulesta raukeevat ja elementit palavuudesta sulavat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 13, 'Mutta me odotamme uusia taivaita ja uutta maata hänen lupauksensa jälkeen, joissa vanhurskaus asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 14, 'Sentähden, minun rakkaani, että te näitä odotatte, niin ahkeroitkaat, että te hänen edessänsä puhtaiksi ja nuhteettomiksi rauhassa löydettäisiin;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 15, 'Ja lukekaat meidän Herran Jesuksen Kristuksen pitkämielisyys teidän autuudeksenne, niinkuin myös meidän rakas veljemme Paavali siitä viisaudesta, joka hänelle annettu on, teille on kirjoittanut,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 16, 'Joka myös jokaisessa kirjassansa näistä puhuu, joissa muutamat ovat työläät ymmärtää, jotka taitamattomat ja huikentelevaiset turmelevat, niinkuin muutkin Raamatut, omaksi kadotukseksensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 17, 'Nyt että te, minun rakkaani, sen jo ennen tiedätte, niin karttakaat, ettette vieteltäisi jumalattomain eksytyksellä ynnä heidän kanssansa, ja lankeaisi pois omasta vahvuudestanne,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 18, 'Vaan kasvakaat meidän Herramme ja Vapahtajan Jesuksen Kristuksen armossa ja tuntemisessa: jolle olkoon kunnia sekä nyt että ijankaikkiseen aikaan, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 1, 'Joka alusta oli, jonka me kuulimme, jonka me silmillämme näimme, jota me katselleet olemme, ja meidän kätemme pidelleet ovat elämän sanasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 2, '(Ja elämä on ilmestynyt, ja me olemme nähneet, ja todistamme ja ilmoitamme teille sen elämän, joka ijankaikkinen on, joka oli Isän tykönä, ja on meille ilmestynyt.)');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 3, 'Mitä me nähneet ja kuulleet olemme, sen me teille ilmoitamme, että teilläkin meidän kanssamme osallisuus olis ja meidän osallisuutemme on Isän ja hänen Poikansa Jesuksen Kristuksen kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 4, 'Ja näitä me teille kirjoitamme, että teidän ilonne täydellinen olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 5, 'Ja tämä on se ilmoitus, jonka me häneltä kuulleet olemme, ja teille ilmoitamme, että Jumala on valkeus, ja ei hänessä ole yhtään pimeyttä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 6, 'Jos me sanomme, että meillä on osallisuus hänen kanssansa, ja vaellamme pimeydessä, niin me valehtelemme ja emme tee totuutta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 7, 'Mutta jos me valkeudessa vaellamme, niinkuin hänkin valkeudessa on, niin meillä on osallisuus keskenämme, ja Jesuksen Kristuksen, hänen Poikansa veri puhdistaa meitä kaikesta synnistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 8, 'Jos me sanomme, ettei meillä ole syntiä, niin me petämme itsemme, ja ei ole totuus meissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 9, 'Jos me tunnustamme meidän syntimme, niin hän on uskollinen ja hurskas, joka meille synnit anteeksi antaa ja puhdistaa meitä kaikesta vääryydestä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 10, 'Jos me sanomme: emmepä me syntiä tehneet ole, niin me teemme hänet valehteliaksi ja ei hänen sanansa ole meissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 1, 'Minun lapsukaiseni! näitä minä teille kirjoitan, ettette syntiä tekisi. Ja jos joku syntiä tekee, niin meillä on edesvastaaja Isän tykönä, Jesus Kristus, joka vanhurskas on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 2, 'Ja hän on sovinto meidän synteimme edestä, ei ainoastaan meidän, vaan myös kaiken maailman edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 3, 'Ja siitä me ymmärrämme, että me hänen tunnemme, jos me hänen käskynsä pidämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 4, 'Joka sanoo: minä tunnen hänen, ja ei pidä hänen käskyjänsä, hän on valehtelia, ja ei hänessä ole totuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 5, 'Mutta joka hänen sanansa pitää, totisesti on Jumalan rakkaus hänessä täydellinen. Siitä me tiedämme, että me hänessä olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 6, 'Joka sanoo itsensä hänessä pysyvän, hänen pitää niin vaeltaman kuin hänkin vaelsi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 7, 'Rakkaat veljet, en minä uutta käskyä teille kirjoita, vaan vanhan käskyn, joka teillä alusta oli. Vanha käsky on se sana, jonka te alusta kuulitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 8, 'Minä kirjoitan teille taas uuden käskyn, se mikä hänessä totinen on, ja teissä myös; sillä pimeys on mennyt pois ja totinen valkeus nyt paistaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 9, 'Joka sanoo valkeudessa olevansa ja vihaa veljeänsä, hän on vielä pimeydessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 10, 'Joka veljeänsä rakastaa, se pysyy valkeudessa ja ei hänessä ole pahennusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 11, 'Mutta joka veljeänsä vihaa, hän on pimeydessä ja vaeltaa pimeydessä, eikä tiedä, kuhunka hän menee; sillä pimeydet ovat hänen silmänsä soaisseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 12, 'Rakkaat poikaseni, minä kirjoitan teille, että teille synnit anteeksi annetaan hänen nimensä tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 13, 'Minä kirjoitan teille, isät; sillä te tunsitte hänen, joka alusta on. Minä kirjoitan teille nuorukaiset, sillä te voititte pahan. Minä kirjoitan teille, lapsukaiseni; sillä te tunsitte Isän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 14, 'Minä kirjoitin teille, isät; sillä te tunsitte sen, joka alusta on. Minä kirjoitin teille, nuorukaiset; sillä te olette väkevät, ja Jumalan sana pysyy teissä, ja te olette pahan voittaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 15, 'Älkäät maailmaa rakastako eli mitään mitä maailmassa on. Jos joku maailmaa rakastaa, ei hänessä ole Isän rakkaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 16, 'Sillä kaikki, mitä maailmassa on, lihan himo, silmäin pyyntö ja elämän koreus, ei se ole Isästä, vaan se on maailmasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 17, 'Ja maailma katoo ja hänen himonsa; mutta joka tekee Jumalan tahdon, se pysyy ijankaikkisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 18, 'Lapsukaiset, nyt on viimeinen aika, ja niinkuin te olette kuulleet, että antikristus tulee, niin nyt myös monta antikristusta rupee olemaan; sillä me tunnemme, että viimeinen aika on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 19, 'He ovat meistä lähteneet, mutta ei he olleet meistä; sillä jos he meistä olleet olisivat, niin he tosin olisivat meidän kanssamme pysyneet: mutta että ne julki tulisivat, ettei he kaikki ole meistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 20, 'Ja teillä on voide häneltä, joka pyhä on, ja te tiedätte kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 21, 'En minä teille kirjoittanut niinkuin totuuden tietämättömille, vaan niinkuin sen tietäville, ja ettei yksikään valhe ole totuudesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 22, 'Kuka on valehtelia, vaan se joka kieltää Jesuksen olevan Kristuksen? Se on antikristus, joka kieltää Isän ja Pojan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 23, 'Jokainen joka kieltää Pojan, ei hänellä Isääkään ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 24, 'Mitä te siis alusta kuulitte, se teissä pysykään: jos se teissä pysyy, minkä te alusta kuulitte, niin te myös Pojassa ja Isässä pysytte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 25, 'Ja tämä on se lupaus, jonka hän meille luvannut on, sen ijankaikkisen elämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 26, 'Nämät minä teille niistä kirjoitin, jotka teitä viettelevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 27, 'Ja se voide, jonka te häneltä saaneet olette, pysyy teissä, ja ette tarvitse, että joku teitä opettaa; vaan niinkuin se voide teitä kaikista opettaa, niin on se tosi ja ei valhe, ja niinkuin se teitä opetti, niin myös te hänessä pysykäät,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 28, 'Ja nyt, lapsukaiseni, pysykäät hänessä: että kuin hän ilmestyy, meillä olis turva, ettemme hänen edessänsä häpiään tulisi hänen tulemisessansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 29, 'Jos te tiedätte, että hän vanhurskas on, niin tietäkäät myös, että jokainen, joka vanhurskautta tekee, se on syntynyt hänestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 1, 'Katsokaat, minkäkaltaisen rakkauden Isä on meille osoittanut, että me Jumalan lapsiksi nimitetään. Sentähden ei maailma teitä tunne; sillä ei hän häntäkään tunne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 2, 'Minun rakkaani! nyt me olemme Jumalan lapset, ja ei ole se vielä ilmestynyt, miksi me tulemme; mutta me tiedämme, kuin se ilmestyy, niin me hänen kaltaisiksensa tulemme; sillä me saamme hänen nähdä niinkuin hän on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 3, 'Ja jokainen, jolla tämä toivo on hänen tykönsä, puhdistaa itsensä, niinkuin hänkin puhdas on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 4, 'Jokainen, joka syntiä tekee, se myös tekee vääryyttä, ja synti on vääryys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 5, 'Ja te tiedätte hänen ilmestyneen, että hän meidän syntimme ottais pois; ja ei hänessä ole syntiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 6, 'Jokainen, joka hänessä pysyy, ei hän syntiä tee; mutta jokainen, joka syntiä tekee, ei se ole häntä nähnyt eikä häntä tuntenut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 7, 'Lapsukaiset, älkäät antako kenenkään teitänne vietellä. Joka vanhurskautta tekee, se on vanhurskas, niinkuin hänkin vanhurskas on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 8, 'Joka syntiä tekee, hän on perkeleestä; sillä perkele tekee syntiä alusta. Sitä varten Jumalan Poika ilmestyi, että hän perkeleen työt särkis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 9, 'Jokainen, joka Jumalasta syntynyt on, ei se syntiä tee; sillä hänen siemenensä pysyy hänessä, ja ei hän taida syntiä tehdä, sillä hän on Jumalasta syntynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 10, 'Siitä ilmaantuvat Jumalan lapset ja perkeleen lapset. Jokainen, joka ei tee vanhurskautta, ei se ole Jumalasta, ja joka ei rakasta veljeänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 11, 'Sillä tämä on ilmoitus, jonka te alusta kuulitte, että me toinen toistamme rakastaisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 12, 'Ei niinkuin Kain, joka pahasta oli, ja tappoi veljensä; ja minkätähden hän tappoi hänen? Sillä hänen työnsä olivat pahat, ja hänen veljensä vanhurskaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 13, 'Älkäät ihmetelkö, minun veljeni, jos teitä maailma vihaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 14, 'Me tiedämme, että me olemme kuolemasta elämään siirretyt, sillä me rakastamme veljiä. Joka ei veljeänsä rakasta, se pysyy kuolemassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 15, 'Jokainen, joka veljeänsä vihaa, hän on murhaaja; ja te tiedätte, ettei yhdessäkään murhaajassa ole ijankaikkinen elämä pysyvä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 16, 'Siitä me tunsimme rakkauden, että hän on henkensä meidän edestämme pannut; niin pitää meidän veljeimme edestä henkemme paneman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 17, 'Mutta jos jollakin olis tämän maailman hyvyyttä, ja näkis veljensä tarvitseman, ja sulkee sydämensä häneltä, kuinkas Jumalan rakkaus pysyy hänessä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 18, 'Lapsukaiseni, älkäämme rakastako sanalla eli kielellä, vaan työllä ja totuudella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 19, 'Siitä me tiedämme, että me totuudesta olemme ja taidamme hänen edessänsä meidän sydämemme hillitä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 20, 'Että jos meidän sydämemme tuomitsee meitä, niin on Jumala suurempi kuin meidän sydämemme ja tietää kaikki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 21, 'Te rakkahimmat! jos ei meidän sydämemme tuomitse meitä, niin meillä on turva Jumalaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 22, 'Ja mitä me anomme, niin me saamme häneltä, että me hänen käskynsä pidämme ja teemme, mitä hänelle kelpaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 23, 'Ja tämä on hänen käskynsä, että me hänen Poikansa Jesuksen Kristuksen nimen päälle uskoisimme, ja rakastaisimme toinen toistamme, niinkuin hän käskyn meille antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 24, 'Ja joka hänen käskynsä pitää, se pysyy hänessä ja hän siinä, ja siitä me tiedämme, että hän meissä pysyy, siitä Hengestä, jonka hän meille antoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 1, 'Te rakkaimmat! älkäät jokaista henkeä uskoko, vaan koetelkaat henget, josko he Jumalasta ovat; sillä monta väärää prophetaa ovat tulleet maailmaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 2, 'Sillä te tuntekaat Jumalan Henki, että jokainen henki, joka tunnustaa Jesuksen Kristuksen lihaan tulleen, se on Jumalasta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 3, 'Ja jokainen henki, joka ei tunnusta Jesusta Kristusta lihaan tulleeksi, ei se ole Jumalasta: ja se on antikristuksen henki, josta te kuulitte, että hän on tuleva, ja on jo parhaallansa maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 4, 'Lapsukaiseni, te olette Jumalasta ja olette heidät voittaneet; sillä se, joka teissä on, hän on suurempi kuin se, joka maailmassa on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 5, 'He ovat maailmasta, sentähden he puhuvat maailmasta ja maailma kuulee heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 6, 'Me olemme Jumalasta: ja joka Jumalan tuntee, hän kuulee meitä; joka ei Jumalasta ole, ei hän kuule meitä. Siitä me tunnemme totuuden hengen ja eksytyksen hengen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 7, 'Te rakkahimmat, rakastakaamme toinen toistamme, sillä rakkaus on Jumalasta: ja jokainen, joka rakastaa, se on Jumalasta syntynyt ja tuntee Jumalan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 8, 'Joka ei rakasta, ei hän tunne Jumalaa; sillä Jumala on rakkaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 9, 'Sen kautta ilmestyi Jumalan rakkaus meidän kohtaamme, että Jumala lähetti ainoan Poikansa maailmaan, että me hänen kauttansa eläisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 10, 'Siinä on rakkaus, ei että me rakastimme Jumalaa, vaan että hän rakasti meitä ja lähetti Poikansa sovinnoksi meidän synteimme edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 11, 'Te rakkahimmat, jos Jumala meitä niin rakasti, niin meidän pitää myös toinen toistamme rakastaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 12, 'Ei ole yksikään Jumalaa koskaan nähnyt. Jos me rakastamme toinen toistamme, niin Jumala pysyy meissä, ja hänen rakkautensa on täydellinen meissä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 13, 'Siitä me tunnemme, että me pysymme hänessä ja hän meissä, ja että hän antoi meille Hengestänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 14, 'Ja me näimme ja todistamme, että Isä on lähettänyt Poikansa maailman Vapahtajaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 15, 'Jokainen, joka tunnustaa Jesuksen Jumalan Pojaksi, hänessä pysyy Jumala ja hän Jumalassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 16, 'Ja me tunsimme ja uskoimme sen rakkauden, jolla Jumala meitä rakastaa. Jumala on rakkaus, ja joka rakkaudessa pysyy, hän pysyy Jumalassa ja Jumala hänessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 17, 'Siinä täytetään rakkaus meissä, että meillä olis turva tuomiopäivänä; sillä niinkuin hän on, niin olemme me myös tässä maailmassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 18, 'Ei pelko ole rakkaudessa, vaan täydellinen rakkaus ajaa pois pelvon, sillä pelvolla on vaiva; mutta joka pelkää, ei hän ole täydellinen rakkaudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 19, 'Me rakastamme häntä; sillä hän rakasti meitä ensin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 20, 'Jos joku sanoo: minä rakastan Jumalaa, ja vihaa veljeänsä, se on valehtelia; sillä joka ei rakasta veljeänsä, jonka hän näkee, kuinka hän taitaa Jumalaa rakastaa, jota ei hän näe?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 21, 'Ja tämä käsky on meillä häneltä: joka Jumalaa rakastaa, hänen pitää myös veljeänsä rakastaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 1, 'Jokainen, joka uskoo, että Jesus on Kristus, hän on Jumalasta syntynyt, ja jokainen, joka rakastaa sitä, joka synnytti, hän rakastaa myös sitä, joka hänestä syntynyt on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 2, 'Siitä me tunnemme, että me rakastamme Jumalan lapsia, koska me Jumalaa rakastamme ja hänen käskynsä pidämme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 3, 'Sillä tämä on rakkaus Jumalan tykö, että me hänen käskynsä pidämme, ja hänen käskynsä ei ole raskaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 4, 'Sillä kaikki, mitä Jumalasta syntynyt on, se voittaa maailman, ja meidän uskomme on se voitto, joka maailman voitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 5, 'Kuka siis on, joka voittaa maailman, mutta se joka uskoo, että Jesus on Jumalan Poika?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 6, 'Tämä on se, joka vedellä ja verellä tulee, Jesus Kristus, ei ainoastansa vedellä, vaan vedellä ja verellä. Ja Henki todistaa, että Henki on totuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 7, 'Sillä kolme ovat, jotka todistavat taivaassa: Isä, Sana ja Pyhä Henki, ja ne kolme yksi ovat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 8, 'Ja kolme ovat, jotka todistavat maan päällä: Henki ja vesi ja veri, ja ne kolme yhdessä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 9, 'Jos me ihmisten todistuksen otamme, niin on Jumalan todistus suurempi; sillä tämä on Jumalan todistus, jonka hän Pojastansa todisti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 10, 'Joka uskoo Jumalan Pojan päälle, hänellä on todistus itsessänsä: joka ei usko Jumalaa, hän tekee hänen valehteliaksi; sillä ei hän uskonut sitä todistusta, jonka Jumala on Pojastansa todistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 11, 'Ja tämä on se todistus, että Jumala on meille ijankaikkisen elämän antanut, ja se elämä on hänen Pojassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 12, 'Jolla Jumalan Poika on, hänellä on elämä; jolla ei Jumalan Poika ole, ei hänellä ole elämää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 13, 'Näitä minä teille kirjoitin, jotka Jumalan Pojan nimen päälle uskotte: että te tietäisitte teillänne ijankaikkisen elämän olevan, ja että te uskoisitte Jumalan Pojan nimen päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 14, 'Ja tämä on se turva, joka meillä on häneen, että jos me jotakin anomme hänen tahtonsa jälkeen, niin hän meitä kuulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 15, 'Ja jos me tiedämme, että hän meitä kuulee, mitä ikänä me anomme, niin me tiedämme, että meillä ovat ne anomiset, joita me häneltä anoimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 16, 'Jos joku näkee veljensä tekevän jonkun synnin, ei kuolemaan, hän rukoilkaan, niin hän on antava niille elämän, jotka syntiä tekevät, ei kuolemaan. Jos synti on kuolemaan: senkaltaisista en minä sano, että joku rukoilis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 17, 'Kaikki vääryys on synti; on myös muutama synti ei kuolemaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 18, 'Me tiedämme, että jokainen, joka Jumalasta syntynyt on, ei hän syntiä tee; vaan joka Jumalasta syntynyt on, se varjelee itsensä, ja paha ei rupee häneen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 19, 'Me tiedämme, että me olemme Jumalasta ja koko maailma on pahuudessa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 20, 'Mutta me tiedämme, että Jumalan Poika tuli ja on meille mielen antanut, että me sen totisen tunnemme, ja olemme siinä totisessa, hänen Pojassansa Jesuksessa Kristuksessa: Tämä on totinen Jumala ja ijankaikkinen elämä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 21, 'Lapsukaiset, kavahtakaat epäjumalia, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 1, 'Vanhin valitulle rouvalle ja hänen lapsillensa, joita minä totuudessa rakastan, ja en ainoastaan minä, mutta myös kaikki, jotka totuuden tunteneet ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 2, 'Sen totuuden tähden, joka meissä pysyy ja on meidän kanssamme oleva ijankaikkisesti:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 3, 'Armo, laupius, rauha Isältä Jumalalta ja Herralta Jesukselta Kristukselta, Isän Pojalta, totuudessa ja rakkaudessa olkoon teidän kanssanne!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 4, 'Minä olen suuresti ihastunut, että minä löysin sinun lapsistas niitä, jotka totuudessa vaeltavat, niinkuin me käskyn Isältä saaneet olemme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 5, 'Ja nyt rukoilen minä sinua, rouva, en, että minä uutta käskyä sinulle kirjoittaisin, vaan sen mikä meillä alusta oli, että me toinen toistamme rakastaisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 6, 'Ja tämä on rakkaus, että me hänen käskynsä jälkeen vaellamme. Tämä on käsky, jonka te alusta kuulitte, että te siinä vaeltaisitte.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 7, 'Sillä monta vietteliää on maailmaan tullut, jotka ei tunnusta Jesusta Kristusta, että hän on lihaan tullut. Tämä on vietteliä ja antikristus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 8, 'Katsokaat visusti teitänne, ettemme kadottaisi, mitä me työtä tehneet olemme, vaan että me täyden palkan saisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 9, 'Jokainen, joka harhaelee ja ei pysy Kristuksen opissa, ei hänellä ole Jumalaa: joka pysyy Kristuksen opissa, hänellä on sekä Isä että Poika.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 10, 'Jos joku tulee teidän tykönne ja ei tuo tätä opetusta kanssansa, niin älkäät häntä huoneeseen ottako, älkäät myös häntä tervehtikö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 11, 'Sillä joka häntä tervehtii, hän on osallinen hänen pahoista töistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 12, 'Minulla olis paljon teille kirjoittamista, mutta en minä tahtonut paperilla ja läkillä; vaan minä toivon tulevani teidän tykönne, ja tahdon läsnä ollessani teidän kanssanne puhua, että meidän ilomme täydellinen olis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 13, 'Sinua tervehtivät sinun valitun sisares lapset, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 1, 'Vanhin rakkaalle Gajukselle, jota minä totuudessa rakastan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 2, 'Minun rakkaani! ylitse kaikkein minä toivotan, ettäs menestyisit ja terveenä olisit, niinkuin sinun sielus menestyy.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 3, 'Sillä minä ihastuin suuresti, kuin veljet tulivat ja todistivat sinun totuudestas, niinkuin sinä totuudessa vaellat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 4, 'Ei minulla ole suurempaa iloa kuin se, että minä kuulen lapseni totuudessa vaeltavan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 5, 'Minun rakkaani! sinä teet uskollisesti, mitäs veljille ja vieraille teet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 6, 'Jotka myös sinun rakkaudestas seurakunnan edessä todistaneet ovat. Ja sinä teet hyvin, ettäs heidät kauniisti lähettänyt olet, Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 7, 'Sillä hänen nimensä tähden he ovat lähteneet, ja ei ole pakanoilta mitään ottaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 8, 'Niin meidän pitää senkaltaisia korjaaman, että me totuuden apulaiset olisimme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 9, 'Minä kirjoitin seurakunnalle; mutta Diotrephes, joka heidän seassansa tahtoo jalo olla, ei ota meitä vastaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 10, 'Sentähden, jos minä tulen, niin minä tahdon ilmoittaa hänen työnsä, joita hän tekee, joka pullikoitsee meitä vastaan pahoilla sanoilla, ja ei niihinkään pysäänny, ja ei hän itse veljiä korjaa, estää myös muita, jotka niitä korjata tahtovat, ja ajaa heitä pois seurakunnasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 11, 'Minun rakkaani, älä seuraa pahaa, vaan hyvää: joka hyvin tekee, se on Jumalasta; mutta joka pahoin tekee, ei se ole nähnyt Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 12, 'Demetriuksella on jokaiselta todistus, ja itse totuudesta. Ja me myös todistamme, ja te tiedätte, että meidän todistuksemme on tosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 13, 'Minulla olis paljo sinun tykös kirjoittamista, vaan en minä tahtonut läkillä ja kynällä kirjoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 14, 'Mutta minä toivon sinun pian näkeväni, ja läsnä ollessani me saamme toinen toistamme puhutella.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 15, 'Rauha olkoon sinulle! Ystävät tervehtivät sinua. Tervehdi ystäviä, kutakin nimeltänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 1, 'Juudas, Jesuksen Kristuksen palvelia, mutta Jakobin veli, niille kutsutuille, jotka Isässä Jumalassa pyhitetyt ovat ja Jesuksessa Kristuksessa vapahdetut:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 2, 'Laupius ja rauha ja rakkaus lisääntyköön teille!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 3, 'Te rakkaat! että minulla oli suuri ahkeruus teille yhteisestä autuudesta kirjoittaa, pidin minä sen tarpeellisena teitä kirjoituksella neuvoa, että te uskon puolesta kilvoittelisitte, joka kerta pyhille annettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 4, 'Sillä muutamat ihmiset ovat luikahtaneet sisälle, jo muinen kirjoitetut tähän tuomioon, jumalattomat, jotka meidän Jumalan armon vetävät haureuteen ja kieltävät Jumalan, joka ainoa hallitsia on, ja meidän Herran Jesuksen Kristuksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 5, 'Mutta minä tahdon teille muistuttaa, että te sen kerran tietäisitte, että koska Herra kansansa Egyptistä terveenä pelastanut oli, hukkasi hän sitte ne, jotka ei uskoneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 6, 'Ja ne enkelit, jotka ei alkuansa pitäneet, vaan antoivat ylön kotonsa, on hän kätkenyt pimeyteen ijankaikkisilla kahleilla suuren päivän tuomioon asti,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 7, 'Niinkuin Sodoma ja Gomorra ja ne lähikaupungit, jotka sillä muotoa kuin hekin huorin tehneet olivat ja muukalaisen lihan jälkeen menneet, ovat pannut muille opiksi, ijankaikkisen tulen vaivaa kärsimään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 8, 'Niin ovat myös nämät unennäkiät, jotka lihan saastuttavat, hallitukset katsovat ylön ja majesteetteja pilkkaavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 9, 'Mutta Mikael, ylimmäinen enkeli, kuin hän perkeleen kanssa riiteli ja kamppaili Moseksen ruumiista, ei rohjennut sanoa sen pilkan tuomiota, vaan sanoi: Herra sinua rangaiskoon!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 10, 'Mutta nämät pilkkaavat niitä, joista ei he mitään tiedä; vaan mitä he luonnon kautta tietävät niinkuin muut järjettömät eläimet, niissä he turmeltuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 11, 'Voi heitä! sillä he käyvät Kainin tiellä ja lankeevat Balaamin eksytykseen palkan tähden, ja hukkuvat Koren kapinassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 12, 'Nämät ovat häpiäpilkut vieraana ollessansa teidän rakkaus-aterioissanne, jotka ravitsevat itsiänsä pelkäämättä: he ovat vedettömät pilvet, jotka tuulelta ajetaan ympäri, paljaat, hedelmättömät puut, kahdesti kuolleet, juurinensa reväistyt ylös;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 13, 'Meren julmat aallot, jotka oman häpiänsä vaahtuvat; eksyväiset tähdet, joille pimeyden kauheus on ijankaikkisesti tähdelle pantu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 14, 'Niin on myös Enok, seitsemäs Adamista, senkaltaisista ennustanut ja sanonut: katso, Herra tulee monen tuhannen pyhäinsä kanssa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 15, 'Tekemään kaikkein tuomiota, ja rankaisemaan kaikkia jumalattomia heidän seassansa, kaikkein heidän jumalattomain töittensä tähden, joilla he pahaa tehneet ovat, ja kaikkea sitä kovaa, jota ne jumalattomat syntiset häntä vastaan puhuneet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 16, 'Nämät ovat napisiat ja valittajat, omain himoinsa jälkeen vaeltavaiset, ja heidän suunsa puhuu röyhkeitä sanoja ja he ihmettelevät ihmisiä hyödytyksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 17, 'Mutta te, rakkaat veljet, muistakaat niitä sanoja, joita ennen meidän Herran Jesuksen Kristuksen apostoleilta sanottiin:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 18, 'Että viimeisellä ajalla tulevat pilkkaajat, jotka jumalattomissa himoissansa vaeltavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 19, 'Nämät ovat ne, jotka eriseurat tekevät, lihalliset, joilla ei henkeä ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 20, 'Mutta te, minun rakkaani! rakentakaat itsiänne teidän kaikkein pyhimmän uskonne päälle, Pyhän Hengen kautta, ja rukoilkaat, pitäin teitänne keskenänne Jumalan rakkaudessa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 21, 'Ja odottakaat meidän Herran Jesuksen Kristuksen laupiutta ijankaikkiseen elämään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 22, 'Ja pitäkäät se eroitus, että te muutamia armahtaisitte,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 23, 'Mutta muutamia pelvolla autuaaksi tekisitte, ja temmatkaat heitä ulos tulesta, ja vihatkaat sitä lihalta saastutettua hametta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 24, 'Mutta hänelle, joka teidät voi viasta varjella ja asettaa nuhteetoinna kunniansa kasvoin eteen, riemulla,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 25, 'Ainoalle viisaalle Jumalalle, meidän Vapahtajallemme, olkoon kunnia, ja majesteetti, ja valta, ja voima, nyt ja kaikessa ijankaikkisuudessa, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 1, 'Jesuksen Kristuksen Ilmestys, jonka Jumala hänelle antoi, ilmoittaa palvelioillensa niitä, mitkä pian tapahtuman pitää, ja on tiettäväksi tehnyt ja lähettänyt enkelinsä kautta palveliallensa Johannekselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 2, 'Joka todisti Jumalan sanaa, ja sen todistuksen Jesuksesta Kristuksesta, ja mitä hän nähnyt oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 3, 'Autuas on se, joka lukee, ja ne, jotka kuulevat prophetian sanat ja pitävät ne, mitkä siinä kirjoitetut ovat; sillä aika on läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 4, 'Johannes seitsemälle Asian seurakunnalle: armo olkoon teille ja rauha siltä, joka on, joka oli, ja joka tuleva on, ja seitsemältä hengeltä, jotka hänen istuimensa edessä ovat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 5, 'Ja Jesukselta Kristukselta, joka se uskollinen todistaja on, ja esikoinen kuolleista, ja maan kuningasten Päämies: joka meitä rakasti ja on meitä verellänsä meidän synneistämme pessyt,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 6, 'Ja teki meidät kuninkaiksi ja papeiksi Jumalan ja Isänsä edessä: hänelle olkoon kunnia ja valta ijankaikkisesta ijankaikkiseen, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 7, 'Katso, hän tulee pilvien kanssa, ja jokaisen silmän pitää hänen näkemän ja ne, jotka häntä pistäneet ovat ja kaikki maan sukukunnat pitää parkuman. Niin, amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 8, 'Minä olen A ja O, alku ja loppu, sanoo Herra, joka on, joka oli, ja joka tuleva on, kaikkivaltias.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 9, 'Minä Johannes, teidän veljenne ja osallinen vaivassa ja valtakunnassa ja kärsivällisyydessä, Jesuksessa Kristuksessa, olin luodossa, joka kutsutaan Patmos, Jumalan sanan ja Jesuksen Kristuksen todistuksen tähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 10, 'Minä olin hengessä yhtenä sunnuntaina ja kuulin minun jäljessäni suuren äänen, niinkuin basunan,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 11, 'Sanovan: minä olen A ja O, ensimäinen ja viimeinen. Mitäs näet, kirjoita kirjaan ja lähetä Asian seurakunnille, jotka Ephesossa ovat, ja Smyrnassa, ja Pergamossa, ja Tyatirassa, ja Sardissa, ja Philadelphiassa, ja Laodikeassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 12, 'Ja minä käännyin sitä ääntä katsomaan, joka minun kanssani puhui, ja minun kääntyessäni näin minä seitsemän kultaista kynttiläjalkaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 13, 'Ja kultaisten kynttiläjalkain keskellä Ihmisen Pojan muotoisen, vaatetetun pitkällä hameella ja vyötetyn rinnoilta kultaisella vyöllä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 14, 'Mutta hänen päänsä ja hiuksensa olivat valkiat niinkuin valkia villa ja niinkuin lumi, ja hänen silmänsä niinkuin tulen liekki,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 15, 'Ja hänen jalkansa valantovasken kaltaiset, niinkuin pätsissä palavaiset, ja hänen äänensä oli niinkuin paljon veden kuohina.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 16, 'Ja seitsemän tähteä oli hänen oikiassa kädessänsä, ja hänen suustansa kävi ulos kaksiteräinen terävä miekka, ja hänen kasvonsa, niinkuin aurinko paistaa voimassansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 17, 'Ja kuin minä hänen näin, lankesin minä hänen jalkainsa eteen niinkuin kuollut, ja hän pani oikian kätensä minun päälleni ja sanoi minulle: älä pelkää, minä olen ensimäinen ja viimeinen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 18, 'Ja elävä, ja olin kuollut, ja katso, minä olen elävä ijankaikkisesta ijankaikkiseen, amen! Ja minulla on helvetin ja kuoleman avaimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 19, 'Kirjoita, mitäs nähnyt olet, mitä nyt on, ja mitä tästälähin tapahtuva on;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 20, 'Se salaisuus niistä seitsemästä tähdestä, jotka sinä minun oikiassa kädessäni nähnyt olet, ja seitsemän kultaista kynttiläjalkaa. Ne seitsemän tähteä ovat seitsemän seurakunnan enkelit: ja ne seitsemän kynttiläjalkaa, jotka sinä nähnyt olet, ovat seitsemän seurakuntaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 1, 'Kirjoita Epheson seurakunnan enkelille: näitä sanoo se, joka seitsemän tähteä pitää oikiassa kädessänsä, joka käy seitsemän kultaisen kynttiläjalan keskellä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 2, 'Minä tiedän sinun työs ja tekos ja sinun kärsivällisyytes, ettet sinä voi kärsiä pahoja: sinä olet niitä jo kiusannut, jotka itsensä apostoleiksi sanovat ja ei ole, ja löysit heidät valehtelioiksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 3, 'Ja sinä kannoit ja kärsit, ja minun nimeni tähden sinä työtä teit ja et väsynyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 4, 'Mutta minulla on sinua vastaan, että sinä sinun ensimäisen rakkautes annoit ylön.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 5, 'Muista siis, kusta lankesit pois, ja tee parannus, ja tee niitä ensimäisiä töitä; vaan jos ei, niin minä tulen sinulle pian ja syöksen kynttiläjalkas pois sialtansa, ellet sinä tee parannusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 6, 'Mutta se sinulla on, ettäs vihaat Nikolailaisten töitä, joita minäkin vihaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 7, 'Jolla korva on, se kuulkaan, mitä Henki seurakunnille sanoo. Sen, joka voittaa, annan minä elämän puusta syödä, joka keskellä Jumalan paradisia on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 8, 'Ja Smyrnan seurakunnan enkelille kirjoita: näitä sanoo ensimäinen ja viimeinen, joka oli kuollut ja elää:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 9, 'Minä tiedän sinun tekos ja vaivas ja köyhyytes, (mutta sinä olet rikas,) ja niiden pilkan, jotka itsensä Juudalaisiksi sanovat ja ei olekaan, vaan ovat saatanan joukko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 10, 'Älä sinä ensinkään pelkää, mitä sinun kärsimän pitää. Katso, perkele on muutamia teistä heittävä vankiuteen, kiusattaa; ja teillä pitää oleman vaiva kymmenen päivää. Ole uskollinen kuolemaan asti, niin minä sinulle elämän kruunun annan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 11, 'Jolla korva on, se kuulkaan, mitä Henki seurakunnille sanoo: Joka voittaa, ei se toiselta kuolemalta vahingoiteta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 12, 'Ja Pergamon seurakunnan enkelille kirjoita: näitä sanoo se, jolla on kaksiteräinen terävä miekka:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 13, 'Minä tiedän sinun tekos, ja kussas asut, kussa saatanan istuin on: ja sinä pidät minun nimeni ja et kieltänyt minun uskoani niinäkään päivinä, joina Antipas, minun uskollinen todistajani, teidän tykönänne tapettu on, kussa saatana asuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 14, 'Mutta minulla on vähä sinua vastaan: että sinulla siellä on niitä, jotka Balaamin oppia pitävät, joka opetti Balakin antamaan pahennusta Israelin lasten edessä, epäjumalten uhria syödä ja salavuoteudessa maata.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 15, 'Niin myös sinulla on niitä, jotka Nikolailaisten oppia pitävät, jota minä vihaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 16, 'Tee parannus; vaan jos ei, niin minä tulen sinulle pian, ja tappelen heidän kanssansa minun suuni miekalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 17, 'Jolla korva on, se kuulkaan, mitä Henki seurakunnille sanoo: sen, joka voittaa, annan minä syödä siitä salatusta mannasta, ja tahdon hänelle hyvän todistuksen antaa, ja sillä todistuksella uuden kirjoitetun nimen, jota ei yksikään tiedä, vaan se, joka sen saa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 18, 'Ja Tyatiran seurakunnan enkelille kirjoita: näitä sanoo Jumalan Poika, jonka silmät ovat niinkuin tulen liekki ja hänen jalkansa valantovasken kaltaiset:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 19, 'Minä tiedän sinun tekos ja rakkautes, ja palvelukses ja uskos, ja sinun kärsivällisyytes ja sinun tekos, ja ne viimeiset usiammat kuin ensimäiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 20, 'Vaan minulla on vähä sinua vastaan, ettäs sallit sen vaimon Jesabelin, joka itsensä prophetaksi sanoo, opettavan ja minun palvelioitani viettelevän, salavuoteudessa makaavan ja epäjumalan uhria syövän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 21, 'Ja minä annoin hänelle ajan parannusta tehdä salavuoteudestansa, mutta ei hän tehnytkään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 22, 'Katso, minä panen hänen vuoteesen ja ne, jotka hänen kanssansa huorin tekevät, suureen vaivaan, ellei he tee parannusta töistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 23, 'Ja hänen lapsensa minä tapan kuolemalla. Ja jokaisen seurakunnan pitää tietämän, että minä olen se, joka munaskuut ja sydämet tutkin, ja annan kullekin teistä teidän työnne jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 24, 'Mutta teille minä sanon ja muille, jotka Tyatirassa olette, joilla ei tämä oppi ole ja jotka ei saatanan syvyyttä tunteneet, niinkuin he sanovat: en minä laske teidän päällenne muuta kuormaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 25, 'Kuitenkin se, mikä teillä on, pitäkäät siihenasti kuin minä tulen,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 26, 'Ja joka voittaa ja minun tekoni hamaan loppuun asti pitää, sille minä annan voiman pakanain ylitse,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 27, 'Ja hänen pitää heitä rautaisella vitsalla hallitseman ja niinkuin savenvalajan astioita heitä särkemän, niinkuin minäkin Isältäni sain;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 28, 'Ja annan hänelle kointähden.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 29, 'Jolla korva on, se kuulkaan, mitä Henki seurakunnille sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 1, 'Ja kirjoita Sardin seurakunnan enkelille: näitä sanoo se, jolla ne seitsemän Jumalan henkeä ja ne seitsemän tähteä ovat: minä tiedän sinun tekos; sillä sinulla on nimi ettäs elät, ja olet kuollut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 2, 'Ole valpas ja vahvista niitä muita, jotka kuolemallansa ovat; sillä en minä löytänyt sinun tekojas täydellisiksi Jumalan edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 3, 'Niin ajattele siis, kuinka sinä saanut ja kuullut olet, ja pidä se, ja tee parannus. Ellet sinä siis valvo, niin minä tulen sinun päälles niinkuin varas, ja et sinä tiedä, millä hetkellä minä sinun päälles tulen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 4, 'Sinulla on myös muutamat nimet Sardissa, jotka ei ole vaatteitansa saastuttaneet: niiden pitää minun kanssani valkeissa vaatteissa vaeltaman; sillä he ovat mahdolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 5, 'Joka voittaa, se pitää valkeilla vaatteilla puetettaman, ja en minä pyyhi hänen nimeänsä elämän kirjasta, ja minä tahdon tunnustaa hänen nimensä minun Isäni edessä ja hänen enkeleinsä edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 6, 'Jolla korva on, se kuulkaan, mitä Henki seurakunnille sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 7, 'Ja Philadelphian seurakunnan enkelille kirjoita: näitä sanoo se Pyhä, se totinen, jolla on Davidin avain, joka avaa ja ei yksikään sulje, joka sulkee ja ei yksikään avaa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 8, 'Minä tiedän sinun tekos: katso, minä annoin sinun etees aukian oven, ja ei yksikään voi sitä sulkea; sillä sinulla on vähä voimaa, ja pidät minun sanani, etkä minun nimeäni kieltänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 9, 'Katso, minä annan sinulle saatanan joukosta ne, jotka itsensä Juudalaisiksi sanovat, ja ei olekaan, vaan he valehtelevat. Katso, minä tahdon vaatia heitä siihen, että heidän pitää tuleman ja kumartaman sinun jalkais edessä, ja heidän pitää tietämän, että minä sinua rakastin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 10, 'Ettäs pidit minun kärsivällisyyteni sanat, niin minä tahdon sinun varjella kiusauksen hetkestä, joka koko maan piirin päälle tuleva on, niitä kiusaamaan, jotka maan päällä asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 11, 'Katso, minä tulen pian: pidä mitä sinulla on, ettei kenkään sinun kruunuas ottaisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 12, 'Joka voittaa, hänen minä teen patsaaksi minun Jumalani templissä, ja ei hänen pidä silleen sieltä lähtemän ulos, ja tahdon kirjoittaa hänen päällensä minun Jumalani nimen ja minun kaupunkini, uuden Jerusalemin nimen, joka taivaasta minun Jumalaltani tuli alas, ja minun uuden nimeni.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 13, 'Jolla korva on, se kuulkaan, mitä Henki seurakunnille sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 14, 'Ja Laodikean seurakunnan enkelille kirjoita: näitä sanoo Amen, uskollinen ja totinen todistaja, Jumalan luontokappalten alku:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 15, 'Minä tiedän sinun tekos, ettet sinä kylmä etkä palava ole: oi jospa kylmä taikka palava olisit!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 16, 'Sentähden ettäs pensiä olet, ja et kylmä etkä palava, rupean minä sinua minun suustani oksentamaan ulos.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 17, 'Ettäs sanot: minä olen rikas, minä olen rikastunut ja en minä mitään tarvitse; ja et tiedä, ettäs viheliäinen ja raadollinen olet, köyhä, sokia ja alastoin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 18, 'Minä neuvon sinua minulta ostamaan kultaa tulella selitettyä, ettäs rikastuisit, ja valkiat vaatteet, joillas sinus pukisit, ettei sinun alastomuutes häpy näkyisi, ja voitele silmäs silmäin voiteella, ettäs näkisit.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 19, 'Joita minä rakastan, niitä minä myös nuhtelen ja kuritan; niin ole siis ahkera ja tee parannus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 20, 'Katso, minä seison ovessa ja kolkutan: jos joku minun ääneni kuulee ja avaa oven, sen tykö minä tahdon mennä sisälle, ja pitää ehtoollista hänen kanssansa ja hän minun kanssani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 21, 'Joka voittaa, sen minä annan istua minun kanssani minun istuimellani, niinkuin minäkin voitin ja olen minun isäni kanssa hänen istuimellansa istunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 22, 'Jolla korva on, se kuulkaan, mitä Henki seurakunnille sanoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 1, 'Sitte näin minä, ja katso, ovi avattiin taivaassa, ja ensimäinen ääni, jonka minä kuulin niinkuin basunan puhuvan minun kanssani, sanoen: astu tänne ylös, ja minä osoitan sinulle, mitä tästälähin tapahtuva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 2, 'Ja kohta minä olin hengessä, ja katso, istuin oli pantu taivaasen, ja istuimella oli (yksi) istuva.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 3, 'Ja se, joka istui, oli näkyänsä kiven jaspiksen ja sardin kaltainen, ja taivaan kaari istuimen ympäri näkyänsä smaragdin kaltainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 4, 'Ja sen istuimen ympärillä oli neljäkolmattakymmentä istuinta, ja niillä istuimilla näin minä neljäkolmattakymmentä vanhinta istuvan, valkeilla vaatteilla puetettuna, ja heidän päässänsä olivat kultaiset kruunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 5, 'Ja istuimesta kävivät ulos leimaukset ja pitkäiset ja äänet, ja seitsemän tulista lamppua paloi istuimen edessä, jotka seitsemän Jumalan henkeä ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 6, 'Ja istuimen edessä oli niinkuin lasinen meri, kristallin muotoinen, ja keskellä istuinta ja ympäri istuinta neljä eläintä, edestä ja takaa silmiä täynnänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 7, 'Ja ensimäinen eläin oli jalopeuran muotoinen, ja toinen eläin vasikan muotoinen, ja kolmannella eläimellä olivat niinkuin ihmisen kasvot, ja neljäs eläin lentäväisen kotkan muotoinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 8, 'Ja niillä neljällä eläimellä oli kullakin kuusi siipeä ympärillä, ja he olivat sisältä silmiä täynnänsä; ja ei heillä ollut lepoa päivällä eikä yöllä, ja sanoivat: pyhä, pyhä, pyhä on Herra Jumala kaikkivaltias, joka oli, ja joka on, ja joka tuleva on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 9, 'Ja kuin ne eläimet antoivat kiitoksen ja kunnian ja siunauksen sille, joka istuimella istui, joka elää ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 10, 'Niin ne neljäkolmattakymmentä vanhinta lankesivat istuimella istuvaisen eteen, ja kumartaen rukoilivat sitä, joka elää ijankaikkisesta ijankaikkiseen, ja heittivät kruununsa istuimen eteen ja sanoivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 11, 'Herra! sinä olet mahdollinen saamaan ylistyksen ja kunnian ja voiman; sillä sinä olet kaikki luonut, ja sinun tahdostas he ovat, ja luodut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 1, 'Ja minä näin istuimella istuvaisen oikiassa kädessä kirjan, sisältä ja ulkoa kirjoitetun, seitsemällä sinetillä lukitun.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 2, 'Ja minä näin väkevän enkelin suurella äänellä saarnaavan: kuka on mahdollinen tätä kirjaa avaamaan ja hänen sinettiänsä päästämään?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 3, 'Ja ei yksikään voinut, ei taivaassa, eikä maassa, eikä maan alla, kirjaa avata, eikä siihen katsoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 4, 'Ja minä itkin kovin, ettei yksikään löydetty mahdolliseksi kirjaa avaamaan eikä sitä näkemään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 5, 'Ja yksi vanhimmista sanoi minulle: älä itke! katso, Jalopeura voitti, joka on Juudan sukukunnasta, Davidin juuri, avaamaan sitä kirjaa ja päästämään sen seitsemää sinettiä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 6, 'Ja minä näin, ja katso, keskellä istuinta, ja neljän eläimen ja vanhimpien keskellä seisoi Karitsa, niinkuin tapettu *, jolla oli seitsemän sarvea ja seitsemän silmää, jotka ovat seitsemän Jumalan henkeä kaikelle maalle lähetetyt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 7, 'Ja se tuli ja otti kirjan istuimella istuvaisen oikiasta kädestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 8, 'Ja kuin hän kirjan ottanut oli, lankesivat ne neljä eläintä ja neljäkolmattakymmentä vanhinta Karitsan eteen, ja jokaisella oli kantele ja kultaiset maljat suitsutusta täynnä, jotka ovat pyhäin rukoukset,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 9, 'Ja veisasivat uutta virttä, sanoen: sinä olet mahdollinen kirjaa ottamaan ja sen sineteitä avaamaan; sillä sinä olet tapettu ja verelläs meitä Jumalalle lunastit kaikkinaisista sukukunnista, ja kielistä, ja kansoista ja pakanoista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 10, 'Ja olet meidät tehnyt meidän Jumalallemme kuninkaiksi ja papeiksi, ja me saamme vallita maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 11, 'Ja minä näin ja kuulin monen enkelin äänen istuimen ja eläinten ja vanhimpien ympärillä, ja heidän lukunsa oli kymmenentuhatta kertaa kymmenentuhatta, ja tuhannen kertaa tuhatta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 12, 'Ja sanoivat suurella äänellä: Karitsa, joka tapettu on, on mahdollinen ottamaan voiman, ja rikkauden, ja viisauden, ja kunnian, ja kiitoksen, ja siunauksen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 13, 'Ja kaikki luontokappaleet, jotka taivaassa ovat, ja maan päällä, ja maan alla, ja meressä, ja kaikki, jotka niissä ovat, kuulin minä sille sanovan, joka istuimella istui, ja Karitsalle: siunaus ja kunnia, ja ylistys ja voima, ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 14, 'Ja ne neljä eläintä sanoivat: amen! Ja ne neljäkolmattakymmentä vanhinta lankesivat maahan, kumarsivat ja rukoilivat sitä, joka elää ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 1, 'Ja minä näin, kuin Karitsa ensimäisen sinetin avasi, ja minä kuulin yhden neljästä eläimestä sanovan, niinkuin pitkäisen jylinän: tule ja katso!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 2, 'Ja minä näin, ja katso, valkia orhi; ja se, joka sen päällä istui, piti joutsea, ja hänelle annettiin kruunu, ja hän läksi voittamaan ja saamaan voittoa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 3, 'Ja kuin hän toisen sinetin avasi, kuulin minä toisen eläimen sanovan: tule ja katso!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 4, 'Ja ruskia orhi meni ulos; ja sille, joka sen päällä istui, annettiin rauha maasta ottaa pois, että heidän piti keskenänsä toinen toisensa tappaman; ja hänelle oli suuri miekka annettu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 5, 'Ja kuin hän kolmannen sinetin avasi, kuulin minä kolmannen eläimen sanovan: tule ja katso! Ja minä näin, ja katso, musta orhi; ja sillä, joka sen päällä istui, oli vaaka kädessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 6, 'Ja minä kuulin äänen neljän eläimen keskeltä sanovan: mitta nisuja yhteen penninkiin ja kolme mittaa ohria yhteen penninkiin, ja älä viinaa eikä öljyä vahingoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 7, 'Ja kuin hän avasi neljännen sinetin, kuulin minä neljännen eläimen äänen sanovan: tule ja katso!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 8, 'Ja minä näin, ja katso, hiirenkarvainen orhi, ja joka sen päällä istui, sen nimi oli kuolema; ja helvetti noudatti häntä. Ja hänelle annettiin voima tappaa neljättä osaa maan päältä miekalla ja nälällä, ja surmalla ja pedoilla maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 9, 'Ja kuin hän viidennen sinetin avasi, näin minä alttarin alla niiden sielut, jotka Jumalan sanan tähden tapetut olivat ja sen todistuksen tähden, joka heillä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 10, 'Ja he huusivat suurella äänellä sanoen: sinä pyhä ja totinen Herra! kuinka kauvan et sinä tuomitse ja meidän vertamme kosta niille, jotka maan päällä asuvat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 11, 'Ja kullekin heistä annettiin valkia vaate ja sanottiin heille, että heidän piti vielä vähän aikaa lepäämän, siihenasti kuin heidän kanssapalveliainsa ja veljeinsä luku täytetyksi tulis, jotka piti tapettaman niinkuin hekin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 12, 'Ja minä näin, kuin hän kuudennen sinetin avasi, katso, niin tapahtui suuri maanjäristys, ja aurinko tuli mustaksi niinkuin karvasäkki ja kuu tuli kokonansa niinkuin veri,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 13, 'Ja tähdet putosivat taivaasta maan päälle, niinkuin fikunapuu fikunansa varistaa, kuin hän suurelta tuulelta häälytetään.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 14, 'Ja taivas pakeni niinkuin kämärtynyt kirja, ja kaikki vuoret ja luodot siirrettiin sioistansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 15, 'Ja kuninkaat maan päällä, ja ylimäiset, ja rikkaat, ja päämiehet, ja väkevät, ja kaikki orjat, ja kaikki vapaat kätkivät itsensä luoliin ja vuorten rotkoihin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 16, 'Ja sanoivat vuorille ja kukkuloille: langetkaat meidän päällemme ja peittäkäät meitä sen kasvoin edestä, joka istuimella istuu, ja Karitsan vihasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 17, 'Sillä se suuri hänen vihansa päivä on tullut, ja kuka voi pysyä?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 1, 'Ja sitte näin minä neljä enkeliä seisovan neljän maan kulman päällä, ja neljää maan tuulta pitävän, ettei tuuli oisi puhaltanut maan päälle, eikä meren päälle, eikä yhdenkään puun päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 2, 'Ja minä näin toisen enkelin auringon koitosta tulevan ylös jolla oli elävän Jumalan sinetti, ja hän huusi suurella äänellä niille neljälle enkelille, joiden maata ja merta oli annettu vahingoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 3, 'Ja sanoi: älkäät maata eikä merta eikä puita vahingoittako siihenasti kuin me merkitsemme meidän Jumalamme palveliat heidän otsissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 4, 'Ja minä kuulin, että merkittyin luku oli sata ja neljäviidettäkymmentä tuhatta, jotka kaikkein Israelin lasten sukukunnista merkityt olivat:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 5, 'Juudan sukukunnasta kaksitoistakymmentä tuhatta merkityt Rubenin sukukunnasta kaksitoistakymmentätuhatta merkityt, Gadin sukukunnasta kaksitoistakymmentätuhatta merkityt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 6, 'Asserin sukukunnasta kaksitoistakymmentä tuhatta merkityt, Naphtalin sukukunnasta kaksitoistakymmentä tuhatta merkityt, Manassen sukukunnasta kaksitoistakymmentä tuhatta merkityt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 7, 'Simeonin sukukunnasta kaksitoistakymmentä tuhatta merkityt, Levin sukukunnasta kaksitoistakymmentä tuhatta merkityt, Isaskarin sukukunnasta kaksitoistakymmentä tuhatta merkityt:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 8, 'Zebulonin sukukunnasta kaksitoistakymmentä tuhatta merkityt, Josephin sukukunnasta kaksitoistakymmentä tuhatta merkityt, Benjaminen sukukunnasta kaksitoistakymmentä tuhatta merkityt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 9, 'Sen jälkeen näin minä, ja katso, suuri joukko, jota ei yksikään lukea taitanut, kaikista pakanoista, ja sukukunnista, ja kansoista ja kielistä, seisovan istuimen edessä ja Karitsan edessä, valkeilla vaatteilla puetetut, ja palmut heidän käsissänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 10, 'Ja he huusivat suurella äänellä, sanoen: autuus olkoon meidän Jumalallemme, joka istuimella istuu, ja Karitsalle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 11, 'Ja kaikki enkelit seisoivat ympäri istuinta, ja vanhimpia, ja neljää eläintä, ja lankesivat kasvoillensa istuimen eteen, kumarsivat ja rukoilivat Jumalaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 12, 'Sanoen: amen! Siunaus, ja ylistys, ja viisaus, ja kiitos, ja kunnia, ja voima, ja väkevyys olkoon meidän Jumalallemme ijankaikkisesta ijankaikkiseen. Amen!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 13, 'Ja yksi vanhimmista vastasi ja sanoi minulle: kutka nämät valkeilla vaatteilla puetetut ovat, ja kusta he tulleet ovat?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 14, 'Ja minä sanoin hänelle: herra, sinäpä sen tiedät. Ja hän sanoi minulle: nämät ovat ne, jotka suuresta vaivasta tulivat, ja he ovat vaatteensa pesseet ja ovat vaatteensa Karitsan veressä valaisseet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 15, 'Sentähden ovat he Jumalan istuimen edessä ja palvelevat häntä päivällä ja yöllä hänen templissänsä. Ja se, joka istuimella istuu, asuu heidän päällänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 16, 'Ei heidän pidä enään isooman, eikä enään janooman, eikä aurinko lankee heidän päällensä, ei myös yksikään palavuus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 17, 'Sillä Karitsa, joka istuimen keskellä on, kaitsee heitä ja johdattaa heitä eläväin vesilähdetten tykö, ja Jumala on kuivaava kaikki kyyneleet heidän silmistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 1, 'Ja kuin hän seitsemännen sinetin avasi, oltiin ääneti taivaassa lähes puoli hetkeä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 2, 'Ja minä näin seitsemän enkeliä Jumalan edessä seisovan, joille seitsemän basunaa annettiin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 3, 'Ja toinen enkeli tuli ja seisoi alttarin edessä, ja hänellä oli kultainen pyhän savun astia, jolle paljo suitsutusta annettiin, kaikkein pyhäin rukouksiin, kultaiselle alttarille antaaksensa, joka on istuimen edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 4, 'Ja suitsutuksen savu pyhäin rukouksista nousi enkelin kädestä Jumalan eteen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 5, 'Ja enkeli otti pyhän savun astian, ja täytti sen alttarin tulesta, ja heitti maan päälle, ja niin tapahtuivat äänet ja pitkäisen jylinät ja leimaukset ja maanjäristykset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 6, 'Ja ne seitsemän enkeliä seitsemällä basunalla hankitsivat basunilla soittamaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 7, 'Ja ensimäinen enkeli soitti basunalla, ja tuli rakeita ja tulta verellä sekoitettuja, jotka maan päälle heitettiin; ja kolmas osa puista paloi ja kaikki viheriäinen ruoho paloi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 8, 'Ja toinen enkeli soitti basunalla, ja mereen heitettiin niinkuin suuri vuori tulessa palava: ja kolmas osa merestä tuli vereksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 9, 'Ja kolmas osa elävistä luontokappaleista meressä kuoli ja kolmas osa haaksista hukkui.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 10, 'Ja kolmas enkeli soitti basunalla, ja suuri tähti lankesi taivaasta, palava niinkuin tulisoitto, ja lankesi kolmannen osan virtain ja vesilähdetten päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 11, 'Ja tähti kutsutaan koiruohoksi: ja kolmas osa vesistä muuttui koiruohoksi, ja monta ihmistä kuoli vetten tähden, että ne haikiaksi tehdyt olivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 12, 'Ja neljäs enkeli soitti basunalla, ja kolmas osa auringosta lyötiin, ja kolmas osa kuusta, ja kolmas osa tähdistä, niin että kolmas osa heistä pimeni, ja ei kolmas osa päivästä valaissut, eikä yöstä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 13, 'Ja minä näin ja kuulin enkelin keskelle taivasta lentävän ja suurella äänellä sanovan: voi, voi, voi, asuvaisia maan päällä, muiden kolmen enkelin basunan äänistä, jotka vielä basunilla soittaman pitää!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 1, 'Ja viides enkeli soitti basunalla, ja minä näin tähden taivaasta maan päälle putoovan, ja hänelle annettiin syvyyden kaivon avain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 2, 'Ja hän avasi syvyyden kaivon, ja kaivon savu kävi ylös niinkuin suuren pätsin savu, ja aurinko ja ilma pimisi kaivon savusta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 3, 'Ja savusta läksivät metsäsirkat maan päälle, ja heille annettiin voima, niinkuin skorpionilla on voima maan päällä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 4, 'Ja heille sanottiin, ettei heidän pitänyt vahingoittaman maan ruohoa eikä mitään viheriäistä, ei myös yhtään puuta, vaan ainoastaan ihmisiä, joiden otsissa ei Jumalan sinetti ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 5, 'Ja se annettiin heille, ettei heidän pitänyt heitä tappaman, vaan viisi kuukautta vaivaaman, ja heidän vaivaamisensa oli niinkuin skorpionin vaivaaminen, kuin hän on ihmistä pistänyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 6, 'Ja niinä päivinä ihmiset etsivät kuolemaa, ja ei löydä häntä, ja pyytää kuolla, vaan kuolema pakenee heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 7, 'Ja metsäsirkat ovat orhitten kaltaiset, jotka sotaan valmistetut ovat, ja heidän päässänsä niinkuin kruunut, kullan muotoiset, ja heidän kasvonsa niin-ihmisten kasvot.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 8, 'Ja heillä olivat hiukset, ja heidän hampaansa olivat niinkuin jalopeuran.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 9, 'Ja heillä oli pantsari niinkuin rautapantsarit; ja heidän siipiensä havina niinkuin ratasten kituma, kussa monta hevosta sotaan juoksee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 10, 'Ja heillä oli pyrstöt niinkuin skorpionilla, ja heidän pyrstöissänsä olivat neulaiset, ja heidän voimansa oli ihmisiä viisi kuukautta vahingoittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 11, 'Ja heidän kuninkaansa on syvyyden enkeli, jonka nimi Hebrean kielellä on Abaddon, ja Grekan kielellä on hänen nimensä Apollyon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 12, 'Yksi voi on mennyt edes, katso, vielä kaksi voita sen jälkeen tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 13, 'Ja kuudes enkeli soitti basunalla, ja minä kuulin äänen neljästä kultaisen alttarin sarvesta, joka Jumalan edessä on,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 14, 'Sanovan sille kuudennelle enkelille, jolla basuna oli: päästä ne neljä enkeliä, jotka suuressa Euphratin virrassa sidottuna ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 15, 'Ja ne neljä enkeliä päästettiin, jotka olivat valmiit hetkeksi, ja päiväksi, ja kuukaudeksi ja vuodeksi, tappamaan kolmatta osaa ihmisistä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 16, 'Ja ratsasmiesten sotajoukon luku oli kaksin kerroin kymmentuhatta kertaa kymmenentuhatta, ja minä kuulin heidän lukunsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 17, 'Ja niin minä näin ne orhiit näyssä, ja niillä, jotka heidän päällänsä istuivat, olivat tuliset ja keltaiset ja tulikiviset pantsarit, ja orhitten päät olivat niinkuin jalopeurain päät, ja heidän suustansa kävi ulos tuli, ja savu, ja tulikivi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 18, 'Näillä kolmella vitsauksella tapettiin kolmas osa ihmisistä, tulella, savulla ja tulikivellä, jotka kävivät ulos heidän suustansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 19, 'Sillä heidän voimansa oli heidän suussansa ja heidän pyrstöissänsä, ja heidän pyrstönsä olivat kärmetten muotoiset, heillä olivat päät ja niillä he vahingoitsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 20, 'Ja muut ihmiset, jotka ei näillä vitsauksilla ole tapetut, ei heidän kättensä töistä parannusta tehneet: ettei he olisi perkeleitä kumartaneet ja kultaisia, ja hopiaisia, ja vaskisia, ja kivisiä ja puisia epäjumalia, jotka ei nähdä taida, eikä kuulla, ei myös käydä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 21, 'Ja ei tehneet parannusta murhistansa, eikä velhoudestansa, eikä huoruudestansa, ei myös varkaudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 1, 'Ja minä näin toisen väkevän enkelin tulevan alas taivaasta, joka pilvellä puetettu oli, ja taivaan kaari hänen päänsä päällä, ja hänen kasvonsa olivat niinkuin aurinko, ja hänen jalkansa niinkuin tulen patsaat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 2, 'Ja hänen kädessänsä oli avoin kirja, ja hän pani oikian jalkansa meren päälle ja vasemman maan päälle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 3, 'Ja huusi suurella äänellä, niinkuin jalopeura kiljuu. Ja koska hän huusi, puhuivat ne seitsemän pitkäistä äänensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 4, 'Ja kuin ne seitsemän pitkäistä olivat äänensä puhuneet, tahdoin minä sen kirjoittaa. Ja minä kuulin äänen taivaasta sanovan minulle: lukitse se, mitä ne seitsemän pitkäistä puhuivat, ja älä niitä kirjoita.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 5, 'Ja enkelin, jonka minä meren päällä ja maan päällä näin seisovan, nosti kätensä taivaasen päin,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 6, 'Ja vannoi sen kautta, joka elää ijankaikkisesta ijankaikkiseen, joka taivaan luonut oli ja ne, mitkä siinä on, ja maan ja ne, mitkä siinä on, ja meren ja ne, mitkä siinä on, ettei silleen aikaa enempi oleman pidä:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 7, 'Vaan seitsemännen enkelin äänen päivinä, kuin hän rupee basunalla soittamaan, niin pitää Jumalan salaisuus täytettämän, niinkuin hän on palvelioillensa prophetaille ilmoittanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 8, 'Ja ääni, jonka minä kuulin taivaasta, puhui taas minun kanssani ja sanoi: mene ja ota avoin kirja enkelin kädestä, joka meren ja maan päällä seisoo.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 9, 'Ja minä menin enkelin tykö ja sanoin: anna kirja minulle. Ja hän sanoi minulle: ota ja syö se! ja se on karvasteleva sinun vatsassas, vaan sinun suussas pitää sen oleman makian niinkuin hunaja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 10, 'Ja minä otin kirjan enkelin kädestä ja söin sen, ja se oli makia minun suussani niinkuin hunaja. Ja kuin minä sen syönyt olin, karvasteli se minun vatsassani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 11, 'Ja hän sanoi minulle: taas tulee sinun propheteerata kansoille, ja pakanoille, ja kielille, ja monelle kuninkaalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 1, 'Ja minulle annettiin ruoko niinkuin sauva, ja enkeli seisoi ja sanoi: nouse ja mittaa Jumalan templi ja alttari, ja ne, jotka siinä rukoilevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 2, 'Mutta syökse sisälmäinen kuori ulos templistä, ja älä sitä mittaa; sillä se on pakanoille annettu, ja he tallaavat pyhää kaupunkia kaksiviidettäkymmentä kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 3, 'Ja minä annan kahdelle minun todistajalleni, ja heidän pitää tuhannen kaksisataa ja kuusikymmentä päivää propheteeraaman, säkeissä puetettuna.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 4, 'Nämät ovat kaksi öljypuuta ja kaksi kynttiläjalkaa, jotka maan Jumalan edessä seisovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 5, 'Ja jos joku heitä tahtoo vahingoittaa, niin tuli käy ulos heidän suustansa, ja syö heidän vihollisensa; ja jos joku tahtoo heitä vahingoittaa, niin se tapetaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 6, 'Näillä on valta taivasta sulkea, ettei niinä päivinä, joina he propheteeraavat, sataman pidä; ja heillä on valta vesiä vereksi muuttaa, ja löydä maata kaikkinaisella vitsauksella, niin usein kuin he tahtovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 7, 'Ja koska he todistuksensa lopettaneet ovat, niin peto, joka astui ylös syvyydestä, on heidän kanssansa sotiva, ja heitä voittava ja tappava heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 8, 'Ja heidän ruumiinsa pitää makaavan sen suuren kaupungin kaduilla, joka hengellisesti kutsutaan Sodoma ja Egypti, kussa myös meidän Herramme ristiinnaulittu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 9, 'Ja muutamat sukukunnista, ja kansoista, ja kielistä, ja pakanoista pitää näkemän heidän ruumiinsa kolme päivää ja puolen, ja ei he salli heidän ruumiitansa haudattaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 10, 'Ja jotka maan päällä asuvat, ne iloitsevat heistä, ja riemuitsevat, ja lahjoja keskenänsä lähettelevät, sillä nämät kaksi prophetaa ahdistelivat niitä, jotka maan päällä asuivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 11, 'Ja kolmen päivän perästä ja puolen meni Jumalalta elämän henki heihin: ja he seisoivat jaloillansa, ja suuri pelko tuli niiden päälle, jotka heidät näkivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 12, 'Ja he kuulivat suuren äänen taivaasta sanovan heille: astukaat tänne. Ja he astuivat taivaasen pilvessä, ja heidän vihollisensa näkivät heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 13, 'Ja sillä hetkellä tapahtui suuri maanjäristys, ja kymmenes osa kaupungista lankesi maahan. Ja siinä maanjäristyksessä tapettiin seitsemäntuhannen ihmisten nimi, ja ne muut hämmästyivät ja antoivat kunnian taivaan Jumalalle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 14, 'Toinen voi on mennyt edes, ja katso, kolmas voi pian tulee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 15, 'Ja seitsemäs enkeli soitti basunalla, ja suuret äänet kuuluivat taivaassa, sanoen: maailman valtakunnat ovat meidän Herrallemme ja hänen Kristuksellensa tulleet, ja hän on hallitseva ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 16, 'Ja neljäkolmattakymmentä vanhinta, jotka Jumalan edessä istuimillansa istuvat, lankesivat kasvoillensa ja kumarsivat Jumalaa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 17, 'Sanoen: me kiitämme sinua Herra, kaikkivaltias Jumala, joka olet, ja olit, ja tuleva olet: että sinä olet saanut sinun suuren voimas, ja hallinnut;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 18, 'Ja pakanat ovat vihastuneet, ja sinun vihas on tullut, ja kuolleitten aika heitä tuomittaa, ja sinun palveliais prophetain palkka maksettaa, ja pyhäin, ja niiden, jotka sinun nimeäs pelkäävät, pienten ja suurten, ja kadottaa niitä, jotka maan turmelleet ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 19, 'Ja Jumalan templi aukeni taivaassa, ja hänen testamenttinsa arkki nähtiin hänen templissänsä; ja tapahtuivat leimaukset, ja äänet ja pitkäiset, ja maanjäristykset, ja suuret rakeet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 1, 'Ja suuri ihme ilmestyi taivaassa: vaimo oli puetettu auringolla, ja kuu hänen jalkainsa alla, ja hänen päässänsä kruunu kahdestatoistakymmenestä tähdestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 2, 'Ja hän oli raskas, ja huusi synnyttäissänsä, ja hänellä oli suuri vaiva synnyttää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 3, 'Ja toinen ihme näkyi taivaassa, katso: suuri ruskia lohikärme, jolla oli seitsemän päätä ja kymmenen sarvea, ja hänen päissänsä seitsemän kruunua.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 4, 'Ja hänen pyrstönsä veti kolmannen osan taivaan tähdistä, ja heitti ne maan päälle. Ja lohikärme seisoi vaimon edessä, joka oli synnyttämällänsä, että kuin hän olis synnyttänyt, se olisi syönyt hänen lapsensa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 5, 'Ja hän synnytti poikalapsen, joka oli kaikki pakanat hallitseva rautaisella vitsalla. Ja hänen poikansa temmattiin Jumalan tykö ja hänen istuimensa tykö.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 6, 'Ja vaimo pakeni korpeen, kussa hänelle oli sia Jumalalta valmistettu, siinä ruokittaa tuhannen kaksisataa ja kuusikymmentä päivää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 7, 'Ja (suuri) sota tapahtui taivaassa: Mikael ja hänen enkelinsä sotivat lohikärmeen kanssa, ja lohikärme soti ja hänen enkelinsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 8, 'Ja ei he voittaneet, eikä heidän siaansa enää löydetty taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 9, 'Ja suuri lohikärme, vanha mato, joka perkeleeksi ja saatanaksi kutsutaan, heitettiin ulos, joka koko maan piirin viettelee, hän heitettiin maan päälle, ja hänen enkelinsä myös hänen kanssansa heitettiin sinne.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 10, 'Ja minä kuulin suuren äänen taivaassa sanovan: nyt on autuus, ja voima, ja valtakunta, ja väki meidän Jumalamme, ja valta hänen Kristuksensa: että meidän veljiemme päällekantaja on heitetty ulos, joka heidän päällensä yötä ja päivää Jumalan edessä kantoi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 11, 'Ja he ovat hänen voittaneet Karitsan veren kautta, ja heidän todistuksensa sanan kautta; ja ei he henkeänsä kuolemaan asti rakastaneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 12, 'Sentähden te, taivaat, iloitkaat, ja jotka niissä asutte. Voi maan ja meren asuvia! sillä perkele astuu alas teidän tykönne, pitäin suurta vihaa, tietäen itsellänsä vähän aikaa olevan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 13, 'Ja kuin lohikärme näki itsensä maahan heitetyksi, vainosi hän vaimoa, joka pojan synnytti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 14, 'Ja vaimolle annettiin kaksi suuren kotkan siipeä, että hän olis korpeen siaansa lentänyt, kussa hän elätetään ajan, ja kaksi aikaa, ja puolen aikaa, kärmeen kasvoin edestä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 15, 'Ja kärme puuskasi vaimon jälkeen suustansa vettä niinkuin kosken, upottaaksensa häntä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 16, 'Mutta maa autti vaimoa, ja maa avasi suunsa, ja särpi veden, jonka lohikärme suustansa puuskannut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 17, 'Ja lohikärme vihastui vaimon päälle, ja meni sotimaan muiden kanssa hänen siemenestänsä, jotka Jumalan käskyt kätkevät ja Jesuksen Kristuksen todistuksen pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 18, 'Ja minä seisoin meren sannalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 1, 'Ja minä näin pedon merestä astuvan ylös, jolla oli seitsemän päätä ja kymmenen sarvea, ja hänen sarvissansa kymmenen kruunua, ja hänen päissänsä pilkan nimi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 2, 'Ja peto, jonka minä näin, oli pardin muotoinen, ja hänen jalkansa olivat niinkuin karhun käpälät, ja hänen suunsa oli niinkuin jalopeurain suu; ja lohikärme antoi sille voimansa, ja istuimensa, ja suuren vallan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 3, 'Ja minä näin yhden hänen päistänsä niinkuin se olis kuoliaaksi haavoitettu ollut, ja hänen kuolemahaavansa parani, ja koko maan piiri ihmetteli sitä petoa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 4, 'Ja kumarsivat lohikärmettä, joka pedolle voiman antoi. Ja he kumarsivat petoa ja sanoivat: kuka on tämän pedon kaltainen? kuka voi sotia häntä vastaan?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 5, 'Ja hänelle annettiin suu puhua suuria asioita ja pilkkoja, ja hänelle annettiin valta pitää sotaa kaksiviidettä kuukautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 6, 'Ja hän avasi suunsa pilkkoja puhumaan Jumalaa vastaan, pilkkaamaan hänen nimeänsä, ja hänen majaansa, ja niitä, jotka taivaassa asuvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 7, 'Ja hänen sallittiin sotia pyhäin kanssa ja voittaa heitä. Ja hänelle annettiin valta kaikkein sukukuntain päälle, ja kansain, ja kielten, ja pakanain.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 8, 'Ja kaikki, jotka maassa asuvat, kumarsivat häntä, joiden nimet ei ole kirjoitetut Karitsan elämän kirjassa, joka maailman alusta tapettu on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 9, 'Jos jollakin korva on, se kuulkaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 10, 'Joka vankiuteen vie, se vankiuteen menee, joka miekalla tappaa, se miekalla tapetaan. Tässä on pyhäin kärsivällisyys ja usko.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 11, 'Ja minä näin toisen pedon maasta astuvan ylös, ja hänellä oli kaksi sarvea niinkuin lampaalla, ja hän puhui niinkuin lohikärme.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 12, 'Ja se tekee kaiken entisen pedon voiman, sen nähden, ja saattaa maan ja sen asuvaiset ensimäistä petoa kumartamaan, jonka kuolemahaava parantunut oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 13, 'Ja tekee suuria ihmeitä, niin että hän saattaa tulenkin putoomaan taivaasta alas maan päälle, ihmisten edestä;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 14, 'Ja viettelee maan asuvia niillä ihmeillä, joita hänen oli annettu pedon edessä tehdä, sanoen maan asuville, että he tekisivät pedon kuvan, jolla miekan haava on, ja joka virkosi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 15, 'Ja sallittiin hänelle antaa hengen pedon kuvalle, että pedon kuva myös puhuis, ja tekis, että jokainen, joka ei pedon kuvaa kumarra, pitää tapettaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 16, 'Ja se saattaa kaikki, pienet ja suuret, rikkaat ja köyhät, vapaat ja palveliat, ottamaan merkin oikiaan käteensä taikka otsiinsa;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 17, 'Ja ettei kenkään taitanut ostaa eikä myydä, jolla ei se merkki ollut, taikka pedon nimi, eli hänen nimensä luku.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 18, 'Tässä on viisaus. Jolla on ymmärrys, laskekaan pedon luvun; sillä se on ihmisen luku, ja hänen lukunsa on kuusisataa kuusikymmentä ja kuusi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 1, 'Ja minä näin, ja katso, Karitsa seisoi Zionin vuorella, ja hänen kanssansa sata ja neljäviidettäkymmentä tuhatta, joilla oli hänen Isänsä nimi kirjoitettu heidän otsissansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 2, 'Ja minä kuulin äänen taivaasta niinkuin paljon veden äänen, ja niinkuin suuren pitkäisen äänen. Ja se ääni, jonka minä kuulin, oli niinkuin kanteleen soittajain, jotka kanteleitansa soittavat,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 3, 'Ja veisasivat niinkuin uutta virttä istuimen edessä, ja neljän eläimen edessä, ja vanhinten. Ja ei yksikään taitanut sitä virttä oppia, paitsi niitä sataa ja neljääviidettäkymmentä tuhatta, jotka maasta ostetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 4, 'Nämät ovat ne, jotka ei vaimoin kanssa ole saastutetut; sillä he ovat neitseet: nämät ovat ne, jotka seuraavat Karitsaa, kuhunka hän menee. Nämät ovat ihmisistä ostetut Jumalalle ja Karitsalle uutiseksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 5, 'Joiden suussa ei ole petosta löydetty; sillä he ovat ilman saastaisuutta Jumalan istuimen edessä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 6, 'Ja minä näin toisen enkelin lentävän taivaan keskitse, jolla ijankaikkinen evankeliumi oli, jota hänen pitää niille ilmoittaman, jotka maan päällä asuvat, ja kaikille pakanoille ja sukukunnille, ja kielille ja kansoille;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 7, 'Joka sanoi suurella äänellä: peljätkäät Jumalaa, ja antakaat hänelle kunnia; sillä hänen tuomionsa hetki on tullut: ja kumartakaat ja rukoilkaat sitä, joka taivaan ja maan ja meret ja vesilähteet teki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 8, 'Ja toinen enkeli seurasi, sanoen: lankesi, lankesi Babylon, suuri kaupunki; sillä hän oli huoruutensa vihan (a) viinalla kaikki pakanat juottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 9, 'Ja kolmas enkeli seurasi niitä, sanoen suurella äänellä: jos joku petoa ja hänen kuvaansa kumartaa, ja ottaa sen merkin otsaansa taikka käteensä,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 10, 'Sen pitää myös Jumalan vihan viinaa juoman, selkiää viinaa, joka hänen vihansa maljaan kaadettu on; ja häntä pitää tulella ja tulikivellä pyhäin enkeleitten edessä ja Karitsan edessä vaivattaman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 11, 'Ja heidän vaivansa savu astuu ylös ijankaikkisesta ijankaikkiseen, ja ei heillä ole lepoa päivällä eikä yöllä, jotka petoa ja hänen kuvaansa kumartavat, ja jos joku on hänen nimensä merkin ottanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 12, 'Tässä on pyhäin kärsivällisyys. Tässä ne ovat, jotka Jumalan käskyt ja Jesuksen uskon pitävät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 13, 'Ja minä kuulin äänen taivaasta minulle sanovan: kirjoita: autuaat ovat ne kuolleet, jotka Herrassa kuolevat tästälähin. Jaa, Henki sanoo: heidän pitää lepäämän töistänsä; sillä heidän tekonsa noudattavat heitä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 14, 'Ja minä näin, ja katso, valkia pilvi, ja pilven päällä istui Ihmisen Pojan muotoinen, jonka päässä oli kultainen kruunu ja terävä sirppi hänen kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 15, 'Ja toinen enkeli läksi templistä, huutaen suurella äänellä pilven päällä istuvaiselle: sivalla sirpilläs ja leikkaa; sillä sinulle tuli hetki leikatakses, ja elo on maan päällä kuivaksi tullut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 16, 'Ja se, joka pilven päällä istui, sivalsi sirpillänsä maan päältä, ja maa tuli leikatuksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 17, 'Ja toinen enkeli läksi templistä, joka taivaassa on, jolla myös terävä sirppi oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 18, 'Ja toinen enkeli läksi alttarista, jolla oli valta tulen päälle, ja huusi suurella äänellä sille, jolla terävä sirppi oli, ja sanoi: sivalla terävällä sirpilläs, ja leikkaa ne viina-oksan versot maan päältä; sillä hänen viinamarjansa ovat kypsyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 19, 'Ja enkeli sivalsi terävällä sirpillänsä maan päällä, ja niitti maan viinamäen, ja heitti ne Jumalan vihan suureen kuurnaan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 20, 'Ja kuurna sotkuttiin ulkona kaupungista, ja veri kuurnasta kuohui ulos hamaan orhitten suitsiin asti, tuhannen ja kuusisataa vakomittaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 1, 'Ja minä näin toisen merkin taivaassa, suuren ja ihmeellisen: seitsemän enkeliä, joilla seitsemän viimeistä vitsausta oli; sillä niissä on Jumalan viha täytetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 2, 'Ja minä näin niinkuin lasisen meren, tulella sekoitetun, ja ne, jotka pedosta voiton saaneet olivat ja hänen kuvastansa ja hänen merkistänsä ja hänen nimensä luvusta, seisovan lasisen meren päällä, ja heillä oli Jumalan kanteleet,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 3, 'Ja he veisasivat Moseksen, Jumalan palvelian virttä, sanoen: suuret ja ihmeelliset ovat sinun tekos, Herra Jumala kaikkivaltias! oikiat ja totiset ovat sinun ties, sinä pyhäin Kuningas!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 4, 'Kuka ei pelkää sinua, Herra, ja sinun nimeäs ylistä? Sillä sinä yksinäs pyhä olet; sillä kaikki pakanat tulevat, ja sinun kasvois edessä kumartavat ja rukoilevat: että sinun tuomios julistetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 5, 'Sitte näin minä, ja katso, todistuksen majan templi avattiin taivaassa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 6, 'Ja templistä läksivät seitsemän enkeliä, joilla seitsemän vitsausta oli, puetetut puhtailla ja kirkkailla liinavaatteilla, ja vyötetyt rinnoilta kultaisilla vöillä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 7, 'Ja yksi neljästä eläimestä antoi seitsemälle enkelille seitsemän kultaista maljaa, täynnänsä Jumalan vihaa, joka elää ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 8, 'Ja templi täytettiin savulla Jumalan kunniasta ja hänen voimastansa, ja ei yksikään voinut templiin mennä sisälle, siihenasti kuin seitsemän enkelin seitsemän vitsausta täytetyiksi tulivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 1, 'Ja minä kuulin suuren äänen templistä sanovan seitsemälle enkelille: menkäät ja vuodattakaat Jumalan vihan maljat maan päälle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 2, 'Ja ensimäinen meni ja vuodatti maljansa maan päälle: ja tuli paha ja häijy haava ihmisten päälle, joilla pedon merkki oli, ja niiden päälle, jotka sen kuvaa kumarsivat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 3, 'Ja toinen enkeli vuodatti maljansa mereen, ja se tuli niinkuin kuolleen veri, ja kaikki eläväiset sielut kuolivat meressä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 4, 'Ja kolmas enkeli vuodatti maljansa virtoihin ja vesilähteisiin: ja se tuli vereksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 5, 'Ja minä kuulin vetten enkelin sanovan: Herra, sinä olet vanhurskas, joka olet, ja joka oli, ja pyhä, ettäs nämät tuomitsit;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 6, 'Sillä he ovat pyhäin ja prophetain veren vuodattaneet, ja sinä annoit heille verta juoda; sillä he ovat sen ansainneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 7, 'Ja minä kuulin toisen (enkelin) alttarilta sanovan: jaa, Herra kaikkivaltias Jumala, sinun tuomios ovat totiset ja oikiat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 8, 'Ja neljäs enkeli vuodatti maljansa aurinkoon: ja sille annettiin ihmisiä vaivata helteellä tulen kautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 9, 'Ja ihmiset tulivat palavaksi suuresta helteestä, ja pilkkasivat Jumalan nimeä, jolla niiden vitsausten päälle valta oli, ja ei tehneet parannusta antaaksensa hänelle kunniaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 10, 'Ja viides enkeli vuodatti maljansa pedon istuimelle; ja hänen valtakuntansa tuli pimiäksi, ja he pureskelivat kielensä rikki kivuillansa,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 11, 'Ja pilkkasivat taivaan Jumalaa kipuinsa ja haavainsa tähden, ja ei tehneet parannusta töistänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 12, 'Ja kuudes enkeli vuodatti maljansa suuren virran Euphratin päälle: ja sen vesi kuivui, että tie olis valmistettu itäisille kuninkaille.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 13, 'Ja minä näin lohikärmeen suusta ja pedon suusta ja väärän prophetan suusta lähtevän kolme rietasta henkeä, sammakkoin muotoista;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 14, 'Sillä he ovat perkeleiden henget, jotka ihmeitä tekevät ja menevät maan ja koko maanpiirin kuningasten tykö, kokoomaan heitä sotaan suurena kaikkivaltiaan Jumalan päivänä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 15, 'Katso, minä tulen niinkuin varas: autuas on se, joka valvoo ja kätkee vaatteensa, ettei hän alasti kävisi, ettei hänen häpiäänsä nähtäisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 16, 'Ja hän on koonnut heitä siihen siaan, jota kutsutaan Hebreaksi Armageddon.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 17, 'Ja seitsemäs enkeli vuodattaa maljansa ilmaan: ja taivaan templistä läksi suuri ääni, istuimelta, joka sanoi: se on tapahtunut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 18, 'Ja äänet tulivat ja pitkäiset ja leimaukset, ja suuri maanjäristys tapahtui, jonka kaltaista ei ole ollut sitte kuin ihmiset tulivat maan päälle, senkaltainen suuri maanjäristys.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 19, 'Ja se suuri kaupunki tuli kolmeksi osaksi, ja pakanain kaupungit lankesivat; ja se suuri Babylon muistettiin Jumalan edessä, että hän antais hänelle juoma-astian hirmuisen vihansa viinasta;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 20, 'Ja kaikki luodot pakenivat, ja ei vuoria löydetty;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 21, 'Ja suuri rae niinkuin leiviskän paino lankesi alas taivaasta ihmisten päälle. Ja ihmiset pilkkasivat Jumalaa rakeen vitsauksen tähden, sillä sen vitsaus oli sangen suuri.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 1, 'Ja tuli yksi seitsemästä enkelistä, joilla seitsemän maljaa oli, ja puhui minun kanssani ja sanoi minulle: tule, minä osoitan sinulle sen suuren porton tuomion, joka paljoin vetten päällä istuu,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 2, 'Jonka kanssa maan kuninkaat huorin tehneet ovat, ja ne, jotka maan päällä asuvat, ovat hänen huoruutensa viinasta juopuneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 3, 'Ja hän vei minun hengessä korpeen. Ja minä näin vaimon istuvan verenkarvaisen pedon päällä, täynnänsä pilkkanimiä, jolla oli seitsemän päätä ja kymmenen sarvea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 4, 'Ja vaimo oli vaatetettu purpuralla ja verenkarvaisella, ja oli kullalla kullattu, ja kalliilla kivillä ja päärlyillä, ja piti kädessänsä kultaisen maljan, täynnä kauhistuksia ja hänen huoruutensa riettautta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 5, 'Ja hänen otsassansa oli nimi kirjoitettu: salaus: suuri Babylon, huoruuden ja maan kauhistuksen äiti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 6, 'Ja minä näin vaimon juopuneena pyhäin ja Jesuksen todistajain verestä; ja minä ihmettelin suuresti, kuin minä sen näin.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 7, 'Ja enkeli sanoi minulle, miksis ihmettelet? Minä sanon sinulle vaimon salaisuuden ja pedon salaisuuden, joka häntä kantaa, ja jolla on seitsemän päätä ja kymmenen sarvea.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 8, 'Peto, jonkas näit, on ollut ja ei ole, ja se on syvyydestä tuleva ylös ja on kadotukseen menevä: ja ne, jotka maan päällä asuvat, (joidenka nimet ei ole elämän kirjassa maailman alusta kirjoitetut,) ihmettelevät, kuin he näkevät pedon, joka oli ja ei ole, vaikka hän kuitenkin on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 9, 'Ja tässä on mieli, jolla viisaus on. Ne seitsemän päätä ovat seitsemän vuorta, joidenka päällä vaimo istuu.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 10, 'Ja ovat seitsemän kuningasta: viisi ovat langenneet, ja yksi on, ja toinen ei ole vielä tullut, ja kuin hän tulee, niin hänen pitää vähän aikaa pysymän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 11, 'Ja peto, joka oli ja ei ole, on itse kahdeksas, ja on niistä seitsemästä, ja menee kadotukseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 12, 'Ja ne kymmenen sarvea, jotkas näit, ovat kymmenen kuningasta, jotka ei vielä valtakuntaa saaneet ole, mutta niinkuin kuninkaat saavat voiman yhdeksi hetkeksi pedon kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 13, 'Näillä on yksi neuvo, ja he antavat pedolle voimansa ja valtansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 14, 'Nämät sotivat Karitsan kanssa, ja Karitsa on heidät voittava; sillä hän on herrain\' Herra, ja kuningasten Kuningas: ja ne, jotka hänen kanssansa ovat, kutsutut ja valitut ja uskolliset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 15, 'Ja hän sanoi minulle: vedet, jotkas näit, kussa portto istuu, ovat kansat ja joukot, ja pakanat ja kielet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 16, 'Ja ne kymmenen sarvea, jotka sinä pedossa näit, ne pitää porttoa vihaaman, ja pitää hänen hävittämän ja alastomaksi tekevän, ja heidän pitää syömän hänen lihansa, ja sen tulella polttavat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 17, 'Sillä Jumala on antanut heidän sydämeensä, että he hänen suosionsa jälkeen tekevät, ja että he sen yhdestä tahdosta tekevät, ja antavat valtakuntansa pedolle, siihenasti kuin Jumalan sanat täytetyksi tulevat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 18, 'Ja vaimo, jonka sinä näit, on suuri kaupunki, jolla on valta maan kuningasten ylitse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 1, 'Ja sitte näin minä toisen enkelin tulevan alas taivaasta, jolla oli suuri voima: ja maa valistui hänen kirkkaudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 2, 'Ja hän huusi väkevästi suurella äänellä ja sanoi: lankesi, lankesi suuri Babylon, ja on tullut perkeleitten asumasiaksi, ja kaikkein rietasten henkein kätköksi, ja kaikkein rietasten ja vihattavain lintuin kätköksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 3, 'Sillä hänen huoruutensa vihan viinasta ovat kaikki pakanat juoneet, ja maan kuninkaat hänen kanssansa huorin tehneet, ja kauppamiehet maan päällä ovat rikastuneet hänen herkkuinsa voimasta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 4, 'Ja minä kuulin toisen äänen taivaasta sanovan: te. minun kansani, lähtekäät ulos hänestä, ettette hänen synneistänsä osallisiksi tulisi, ettette myös jotakin hänen vitsauksistansa saisi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 5, 'Sillä hänen syntinsä ovat ulottuneet hamaan taivaasen asti, ja Jumala muisti hänen vääryytensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 6, 'Maksakaat hänelle niinkuin hänkin maksoi teille, ja kertokaat hänelle kaksinkertaisesti hänen töittensä jälkeen; sillä juoma-astialla, josta hän teille pani sisälle, niin pankaat hänelle kaksinkertaisesti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 7, 'Niin paljo kuin hän itsiänsä kunnioitti ja koreili, niin antakaat hänelle niin paljon vaivaa ja itkua; sillä hän sanoo sydämessänsä: minä istun ja olen kuningatar ja en leski, ja ei minun pidä itkua näkemän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 8, 'Sentähden pitää hänen vitsauksensa yhtenä päivänä tuleman: kuolema ja itku ja nälkä, ja hän pitää tulella poltettaman; sillä Herra Jumala on väkevä, joka hänen tuomitsee.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 9, 'Ja häntä pitää itkettämän, ja maan kuninkaat parkuvat häntä, jotka hänen kanssansa huorin tekivät ja hekumassa elivät, kuin he hänen palonsa savun näkevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 10, 'Ja pitää taampana seisoman hänen vaivansa pelvon tähden ja sanoman: voi, voi suurta kaupunkia Babylonia, väkevää kaupunkia! sillä yhdellä hetkellä tuli sinun tuomios.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 11, 'Ja kauppamiehet maan päällä itkevät ja murehtivat häntä, ettei kenkään enempi heidän kalujansa osta:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 12, 'Kulta- ja hopiakaluja, ja kalliita kiviä ja päärlyjä, ja kalliita liinavaatteita, ja purpuraa ja silkkiä, ja tulipunaista, ja kaikkinaisia kalliita puita, ja kaikkinaisia astioita elephantin luista, ja kaikkinaisia astioita kalleimmista puista, ja vaskesta, ja raudasta, ja marmorista,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 13, 'Ja kanelia ja hyvänhajullisia, ja voidetta, ja pyhää savua, ja viinaa, ja öljyä, ja sämpyliä, ja nisuja, ja karjaa, lampaita ja hevosia, rattaita, ja orjia ja ihmisten sieluja.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 14, 'Ja hedelmät, joita sinun sielus himoitsee, ovat sinulta paenneet pois, ja kaikki, jotka lihavat ja kauniit olivat, ne ovat sinusta oljenneet pois, ja ei sinun pidä niitä enää löytämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 15, 'Näiden kaluin kauppamiehet, jotka hänestä rikastuneet ovat, pitää taampana seisoman hänen vaivansa pelvon tähden, itkemän ja murehtiman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 16, 'Ja sanoman: voi, voi suurta kaupunkia! joka puetettu oli kalliilla liinalla ja purpuralla, ja tulipunaisella, ja kullalla yltäkullattu, ja kalliilla kivillä, ja päärlyillä; yhdellä hetkellä ovat senkaltaiset rikkaudet hävitetyt.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 17, 'Ja kaikki haahdenhaltiat, ja kaikki haaksiväki, jotka laivoissa asuvat, ja merimiehet, ja jotka merellä vaeltavat, seisoivat taampana,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 18, 'Ja huusivat, kuin he savun hänen palostansa näkivät, ja sanoivat: kuka on tämän suuren kaupungin verta?');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 19, 'Ja he heittivät multaa päittensä päälle, huusivat, itkivät ja murehtivat, sanoen: voi, voi suurta kaupunkia! jossa kaikki rikastuneet ovat, joilla laivat meressä olivat, hänen kalliista kaluistansa; yhdellä hetkellä on hän hävitetty.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 20, 'Ihastu, taivas, hänestä, ja te pyhät apostolit ja prophetat! sillä Jumala tuomitsee teidän tuomionne hänen päällensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 21, 'Ja yksi väkevä enkeli nosti ison kiven, niinkuin myllynkiven, ja heitti sen mereen ja sanoi: näin äkisti pitää suuri kaupunki Babylon heitettämän pois, ja ei häntä pidä enempi löydettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 22, 'Ja kanteleiden soittajain ja laulajain, ja huiluin ja basunan soittajain ääni ei pidä enempi sinusta kuuluman, ja ei yhtäkään virkamiestä yhdestäkään virasta pidä enempi sinussa löydettämän, ja myllyn ääni ei pidä enempi sinussa kuuluman;');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 23, 'Ja kynttilän valkeus ei pidä sinussa enää valistaman, ja yljän ja morsiamen ääni ei pidä enää sinussa kuuluman; sillä sinun kauppamiehes olivat maan päämiehet, ja sinun noitumises kautta ovat kaikki pakanat eksyneet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 24, 'Ja hänessä on prophetain ja pyhäin veri löydetty, ja kaikkein niiden, jotka maan päällä tapetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 1, 'Ja sitte kuulin minä suuren äänen, niinkuin paljolta kansalta taivaassa, sanovan: halleluja! autuus ja ylistys, kunnia ja voima olkoon Herralle meidän Jumalalle!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 2, 'Sillä hänen tuomionsa ovat totiset ja vanhurskaat: että hän on suuren porton tuominnut, joka huoruudellansa maan turmeli, ja on palveliainsa veren sen kädestä kostanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 3, 'Ja taas he sanoivat: halleluja! Ja sen savu käy ylös ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 4, 'Ja neljäkolmattakymmentä vanhinta ja neljä eläintä maahan lankesivat ja rukoilivat Jumalaa, istuimella istuvaista, ja sanoivat: amen! halleluja!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 5, 'Ja ääni kuului istuimelta, sanoen: kiittäkäät meidän Jumalaamme kaikki hänen palveliansa ja jotka häntä pelkäätte, sekä pienet että suuret.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 6, 'Ja minä kuulin niinkuin paljon kansan äänen, ja niinkuin suuren veden äänen, ja niinkuin suurten pitkäisten äänen, jotka sanoivat: halleluja! sillä Herra kaikkivaltias Jumala on valtakunnan omistanut.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 7, 'Iloitkaamme ja riemuitkaamme, ja antakaamme kunnia hänelle, sillä Karitsan häät ovat tulleet, ja sen emäntä valmisti itsensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 8, 'Ja hänen annettiin pukea itsensä puhtaalla ja kiiltävällä kalliilla liinalla, joka kallis liina on pyhäin vanhurskaus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 9, 'Ja hän sanoi minulle: kirjoita: autuaat ovat ne, jotka ovat Karitsan häihin ehtoolliselle kutsutut. Ja hän sanoi minulle: nämät Jumalan sanat ovat totiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 10, 'Ja minä lankesin hänen jalkainsa eteen häntä rukoilemaan. Mutta hän sanoi minulle: katso, ettes sitä tee; minä olen sinun ja sinun veljeis kanssapalvelia ja niiden, joilla Jesuksen todistus on: kumarra ja rukoile Jumalaa, sillä Jesuksen todistus on prophetain henki.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 11, 'Ja minä näin taivaan avatuksi, ja katso, valkia orhi, ja se, joka sen päällä istui, kutsuttiin uskolliseksi ja totiseksi, ja vanhurskaudella hän tuomitsee ja sotii.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 12, 'Ja hänen silmänsä ovat niinkuin tulen liekki, ja hänen päässänsä on monta kruunua, ja hänellä oli kirjoitettu nimi, jota ei kenkään tietänyt, vaan hän itse.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 13, 'Ja hän oli vaatetettu vereen kastetulla vaatteella. Ja sen nimi kutsutaan Jumalan sanaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 14, 'Ja sotajoukko, joka taivaassa on, seurasi häntä valkeilla hevosilla, vaatetetut valkialla puhtaalla kalliilla liinalla.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 15, 'Ja hänen suustansa kävi ulos terävä miekka, jolla hänen pitää pakanoita lyömän, joita hän on hallitseva rautaisella vitsalla. Ja hän on sotkuva kaikkivaltiaan Jumalan närkästyksen ja vihan viinakuurnan.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 16, 'Ja hänellä on vaatteessansa ja reidessänsä nimi kirjoitettu: kuningasten Kuningas ja herrain Herra.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 17, 'Ja minä näin enkelin seisovan auringossa, joka huusi suurella äänellä ja sanoi kaikille linnuille, jotka taivaan alla lentävät: tulkaat ja kokoontukaat suuren Jumalan ehtoolliselle.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 18, 'Syömään kuningasten lihaa ja päämiesten lihaa, ja väkeväin lihaa, ja orhitten lihaa, ja niillä ajavaisten, ja kaikkein vapaitten ja orjain, sekä pienten että suurten.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 19, 'Ja minä näin pedon, ja maan kuninkaat, ja heidän sotaväkensä koottuna sotimaan sen kanssa, joka oriin päällä istui, ja myös hänen sotaväkensä kanssa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 20, 'Ja peto otettiin kiinni, ja hänen kanssansa väärä propheta, joka ihmeitä hänen edessänsä teki, joilla hän niitä vietteli, jotka pedon merkin ottivat, ja jotka hänen kuvaansa kumarsivat: nämä kaksi ovat elävältä tuliseen järveen heitetyt, joka tulikivestä paloi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 21, 'Ja muut tapettiin miekalla, joka sen suusta kävi ulos, joka oriin päällä istui; ja kaikki linnut ravittiin heidän lihastansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 1, 'Ja minä näin enkelin astuvan alas taivaasta, jolla oli syvyyden avain ja suuri kahle hänen kädessänsä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 2, 'Ja hän otti lohikärmeen kiinni, vanhan madon, joka on perkele ja saatana, ja sitoi hänen tuhanneksi vuodeksi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 3, 'Ja heitti hänen syvyyteen, ja sulki hänen, ja lukitsi päältä, ettei hänen enempi pitäisi pakanoita viettelemän, siihenasti kuin tuhannen vuotta kuluu; ja sitte pitää hän vähäksi hetkeksi päästettämän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 4, 'Ja minä näin istuimet, ja he istuivat niiden päällä, ja heille annettiin tuomio; ja niiden sielut, jotka Jesuksen todistuksen ja Jumalan sanan tähden mestatut olivat, ja jotka ei petoa kumartaneet eikä hänen kuvaansa, ja ei ottaneet hänen merkkiänsä otsiinsa taikka käsiinsä; ja he elivät ja hallitsivat Kristuksen kanssa tuhannen vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 5, 'Mutta ne muut ei kuolleista virvonneet siihenasti kuin tuhannen ajastaikaa kului. Tämä on ensimäinen ylösnousemus.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 6, 'Autuas ja pyhä on se, jolla on osa ensimäisessä ylösnousemisessa: niiden ylitse ei ole toisella kuolemalla yhtään valtaa, vaan he tulevat Jumalan ja Kristuksen papeiksi, ja hallitsevat hänen kanssansa tuhannen vuotta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 7, 'Ja kuin tuhannen vuotta kuluneet ovat, niin saatana päästetään vankiudestansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 8, 'Ja hän menee ulos pakanoita viettelemään, jotka neljällä maankulmalla ovat, Gog ja Magog, että hän heitä sotaan kokoais, joidenka luku on niinkuin meren santa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 9, 'Ja he astuivat maan avaruuden päälle, ja piirittivät pyhäin leirin ja rakkaan kaupungin. Ja tuli lankesi Jumalalta taivaasta ja söi heidät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 10, 'Ja perkele, joka heitä vietteli, heitettiin tuliseen ja tulikiviseen järveen, jossa sekä peto että väärä propheta oli; ja ne pitää vaivattaman päivää ja yötä ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 11, 'Ja minä näin suuren valkian istuimen ja senpäällä istuvan, jonka kasvoin edestä maa ja taivas pakeni; ja ei heille löydetty siaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 12, 'Ja minä näin kuolleet, sekä pienet että suuret, seisovan Jumalan kasvoin edessä, ja kirjat avattiin, ja toinen kirja avattiin, joka on elämän, ja kuolleet tuomittiin niistä, mitkä kirjoissa kirjoitetut olivat, töittensä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 13, 'Ja meri antoi ne kuolleet, jotka hänessä olivat, ja kuolema ja helvetti antoi ne kuolleet, jotka heissä olivat: ja ne tuomittiin jokainen töittensä jälkeen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 14, 'Ja kuolema ja helvetti heitettiin tuliseen järveen. Tämä on toinen kuolema.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 15, 'Ja joka ei löydetty elämän kirjassa kirjoitetuksi, se heitettiin tuliseen järveen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 1, 'Ja minä näin uuden taivaan ja uuden maan, sillä ensimäinen taivas ja ensimäinen maa katosi, ja ei meri silleen ole.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 2, 'Ja minä Johannes näin pyhän kaupungin, uuden Jerusalemin, astuvan alas taivaasta, Jumalalta valmistetun, niinkuin morsiamen kaunistetun hänen miehellensä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 3, 'Ja kuulin suuren äänen taivaasta sanovan: katso Jumalan maja ihmisten seassa, ja hän on asuva heidän kanssansa, ja he tulevat hänen kansaksensa, ja itse Jumala on oleva heidän kanssansa ja heidän Jumalansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 4, 'Ja Jumala on pyyhkivä pois kaikki kyyneleet heidän silmistänsä, ja ei kuolemaa pidä silleen oleman, eikä itkua, eikä parkua, eikä kipua pidä silleen oleman; sillä ne entiset poismenivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 5, 'Ja se, joka istuimella istui, sanoi: katso, minä uudistan kaikki. Ja sanoi minulle: kirjoita! sillä nämä sanat ovat totiset ja vahvat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 6, 'Ja hän sanoi minulle: Se on tapahtunut. Minä olen A ja O, alku ja loppu. Minä annan janoovalle elämän veden lähteestä lahjaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 7, 'Joka voittaa, sen pitää kaikki nämät perimän, ja minä olen hänen Jumalansa, ja hänen pitää oleman minun poikani.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 8, 'Mutta pelkureille ja uskottomille, ja hirmuisille, ja murhaajille, ja salavuoteisille, ja velhoille, ja epäjumalisille, ja kaikille valehtelioille pitää osa oleman siinä järvessä, joka tulesta ja tulikivestä palaa, joka on toinen kuolema.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 9, 'Ja minun tyköni tuli yksi seitsemästä enkelistä, joilla oli seitsemän maljaa täynnä seitsentä viimeistä vitsausta, ja puhui minun kanssani, sanoen: tule, minä osoitan sinulle morsiamen, Karitsan emännän.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 10, 'Ja hän vei minun hengessä suurelle ja korkialle vuorelle, ja osoitti minulle suuren kaupungin, pyhän Jerusalemin, astuvan alas taivaasta Jumalalta,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 11, 'Jolla oli Jumalan kirkkaus; ja sen valkeus oli kaikkein kalleimman kiven muotoinen, niinkuin kirkas jaspis.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 12, 'Ja hänellä oli suuri ja korkia muuri, jolla oli kaksitoistakymmentä porttia, ja porteissa kaksitoistakymmentä enkeliä, ja nimet kirjoitetut, jotka ovat kahdentoistakymmenen Israelin lasten sukukuntain nimet:');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 13, 'Idässä kolme porttia, pohjoisessa kolme porttia, etelässä kolme porttia, lännessä kolme porttia.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 14, 'Ja sen kaupungin muurilla oli kaksitoistakymmentä perustusta, ja niissä Karitsan kahdentoistakymmenen apostolin nimet.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 15, 'Ja sillä, joka minun kanssani puhui, oli kultainen ruoko, kaupunkia mitataksensa ja hänen porttejansa ja muuriansa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 16, 'Ja kaupunki on pantu nelikulmaiseksi, ja hänen pituutensa on niin suuri kuin hänen leveytensä. Ja hän mittasi kaupungin ruovolla kaksitoistakymmentä tuhatta vakomittaa; ja hänen pituutensa ja leveytensä ja korkeutensa ovat yhtäläiset.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 17, 'Ja mittasi hänen muurinsa, sata ja neljäviidettäkymmentä kyynärää ihmisen mitan jälkeen, joka enkelillä oli.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 18, 'Ja muurin rakennus oli jaspiksesta, ja itse kaupunki puhtaasta kullasta, puhtaan lasin kaltainen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 19, 'Ja kaupungin muurin perustukset olivat kaikkinaisilla kalliilla kivillä kaunistetut: ensimäinen perustus oli jaspis, toinen saphiri, kolmas kalkedoni, neljäs smaragdi,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 20, 'Viides sardoniks, kuudes sardius, seitsemäs krysoliti, kahdeksas berilli, yhdeksäs topasis, kymmenes krysoprasi, yksitoistakymmenes hyakinti, kaksitoistakymmenes ametysti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 21, 'Ja ne kaksitoistakymmentä porttia olivat kaksitoistakymmentä päärlyä, ja kukin portti oli yhdestä päärlystä; ja kaupungin kadut olivat puhdas kulta, niinkuin lävitse paistavainen lasi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 22, 'Ja en minä hänessä templiä nähnyt; sillä Herra kaikkivaltias Jumala on hänen templinsä, ja Karitsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 23, 'Ja ei se kaupunki tarvitse aurinkoa eikä kuuta hänessä valistamaan; sillä Jumalan kirkkaus valistaa hänessä, ja hänen valkeutensa on Karitsa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 24, 'Ja pakanat, jotka autuaaksi tulevat, pitää hänen valkeudessansa vaeltaman, ja maan kuninkaat tuovat kunniansa ja ylistyksensä siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 25, 'Ja ei sen portteja suljeta päivillä; sillä ei siellä yötä pidä oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 26, 'Ja pakanain ylistys ja kunnia tuodaan siihen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 27, 'Ja ei pidä häneen mitään saastuttavaa tuleman sisälle, taikka sitä, mikä kauhistuksen eli valheen saattaa; vaan ne, jotka Karitsan elämän kirjassa kirjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 1, 'Ja hän osoitti minulle puhtaan elämän veden virran, selkiän niinkuin kristallin, vuotavan Jumalan ja Karitsan istuimesta.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 2, 'Keskellä hänen katuansa ja molemmilla puolilla virtaa seisoi elämän puu, joka kantoi kaksitoistakymmeniset hedelmät, ja antoi hedelmänsä kunakin kuukautena, ja puun lehdet pakanain terveydeksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 3, 'Ja ei kirousta pidä silleen ensinkään oleman; vaan Jumalan ja Karitsan istuin pitää hänessä oleman, ja hänen palveliansa pitää häntä palveleman,');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 4, 'Ja näkemän hänen kasvonsa, ja hänen nimensä pitää heidän otsissansa oleman.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 5, 'Ja yötä ei pidä siellä oleman, eikä he tarvitse kynttilää taikka auringon valkeutta; sillä Herra Jumala valaisee heitä: ja heidän pitää hallitseman ijankaikkisesta ijankaikkiseen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 6, 'Ja hän sanoi minulle: nämät sanat ovat vahvat ja totiset, ja Herra, pyhäin prophetain Jumala, on enkelinsä lähettänyt osoittamaan palvelioillensa niitä, mitkä pian tapahtuman pitää.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 7, 'Katso, minä tulen nopiasti. Autuas on se, joka kätkee tämän kirjan prophetian sanat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 8, 'Ja minä Johannes olen se, joka näitä näin ja kuulin. Ja kuin minä näitä kuulin ja näin, lankesin minä maahan rukoilemaan enkelin jalkain eteen, joka minulle näitä osoitti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 9, 'Ja hän sanoi minulle: katso, ettes sitä tee; sillä minä olen sinun kanssapalvelias, ja sinun veljeis prophetain ja niiden, jotka tämän kirjan sanat kätkevät: kumarra ja rukoile Jumalaa.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 10, 'Ja hän sanoi minulle: älä tämän kirjan prophetian sanoja lukitse; sillä aika on läsnä.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 11, 'Joka paha on, se olkoon vielä paha, ja joka saastainen on, se tulkoon vielä saastaiseksi; mutta joka vanhurskas on, se tulkoon vielä hurskaaksi, ja joka pyhä on, se tulkoon vielä pyhäksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 12, 'Ja katso, minä tulen pian, ja minun palkkani on minun kanssani, antamaan kullekin niinkuin hänen työnsä on.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 13, 'Minä olen A ja O, alku ja loppu, ensimäinen ja viimeinen.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 14, 'Autuaat ovat ne, jotka hänen käskynsä pitävät, että heidän voimansa elämän puussa olis ja he porteista kaupunkiin sisälle menisivät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 15, 'Mutta ulkona ovat koirat ja velhot, ja huorintekiät ja murhaajat, ja epäjumalan palveliat, ja kaikki ne, jotka valhetta rakastavat ja tekevät.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 16, 'Minä Jesus lähetin minun enkelini todistamaan näitä teille seurakunnissa. Minä olen Davidin juuri ja suku, se kirkas kointahti.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 17, 'Ja henki ja morsian sanovat: tule. Ja joka kuulee, se sanokaan: tule. Joka janoo, se tulkaan, ja joka tahtoo, se ottakaan elämän vettä lahjaksi.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 18, 'Mutta minä todistan jokaiselle, joka tämän kirjan prophetian sanoja kuuleva on: jos joku lisää näihin, niin Jumala on paneva hänen päällensä ne vitsaukset, jotka tässä kirjassa kirjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 19, 'Ja jos joku tämän kirjan prophetian sanoista ottaa pois, niin Jumala ottaa pois hänen osansa elämän kirjasta, ja pyhästä kaupungista, ja niistä, mitkä tässä kirjassa kirjoitetut ovat.');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 20, 'Se, joka näitä todistaa, sanoo: jaa, minä tulen pian: amen! Niin tule, Herra Jesus!');
INSERT INTO `FinBiblia_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 21, 'Meidän Herran Jesuksen Kristuksen armo olkoon teidän kaikkein kanssanne. Amen!');
